INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sang-tao-doanh-chau-a-phan-1', 'Sáng Tạo Doanh Châu Á (Phần 1)', 'Chuang Asia (Season 1)', 'https://phimimg.com/upload/vod/20250210-1/df1674bd8e62c951edd85f4050d45697.jpg', 'https://phimimg.com/upload/vod/20250210-1/b0c6ebb2419137c20552e299862f8b95.jpg', '<p>CHUANG - Sáng Tạo Doanh, chương trình tìm kiếm thần tượng nổi tiếng của Trung Quốc đã trở lại với tên gọi Sáng Tạo Doanh Châu Á 2024 diễn ra ở Thái Lan.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"The8","avatar":""},{"name":"BamBam","avatar":""},{"name":"Jeff Satur","avatar":""},{"name":"Tia Ray","avatar":""},{"name":"Urassaya Sperbund","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["创造营亚洲","CHUANG ASIA","創造營亞洲"]', 1784690324219);
