INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-sinh-thanh-quy-toc-toi-su-dung-ky-nang-giam-dinh-de-tien-than-trong-the-gioi-phan-1', 'Chuyển Sinh Thành Quý Tộc, Tôi Sử Dụng Kỹ Năng Giám Định Để Tiến Thân Trong Thế Giới (Phần 1)', 'As A Reincarnated Aristocrat, I''ll Use My Appraisal Skill To Rise In The World (Season 1)', 'https://phimimg.com/upload/vod/20240530-1/558c195a2e253e1c15a61421b174ea83.jpg', 'https://phimimg.com/upload/vod/20240530-1/e17b8afd7b0c3b4f8ca66f6eec9ba8a6.jpg', '<p>Series phim kể về cuộc sống sau khi tái sinh từ một người làm công ăn lương bình thường thành Ars Louvent, con trai của một quý tộc. Mặc dù không có tài về phép thuật hay kiếm thuật nhưng anh ấy có một kỹ năng mà không ai có: Thẩm định. Sử dụng khả năng này, Ars có thể xác định sức mạnh hiện tại của một người, tiềm năng của họ và tài năng của họ nằm ở đâu.

Với mong muốn xây dựng một lãnh thổ hưng thịnh, Ars bắt đầu tìm kiếm những cộng sự tài năng. Một người nước ngoài bị đàn áp với thanh kiếm vô song, một nô lệ với tài năng ma thuật vô danh và một cậu bé nhút nhát với niềm khao khát kiến thức không thể nguôi - những tài năng này hỗ trợ Ars rất nhiều trong công cuộc tạo ra lãnh thổ hùng mạnh nhất.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsumi Fujiwara","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Narumi Kaho","avatar":""},{"name":"Miho Okasaki","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324219);
