INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-tinh-thuc-su', 'Danh Tính Thực Sự', 'Faceless', 'https://phimimg.com/upload/vod/20250210-1/43b114f3daf6bdadc693a7c4c05db6d6.jpg', 'https://phimimg.com/upload/vod/20250210-1/ba736c19524cebe1f9d5d8b3a7874e83.jpg', '<p>Kaburagi bị bắt vì bị tình nghi trong một vụ án giết người dã man, nhưng anh ta đã trốn thoát. Anh ta tiếp tục lẩn trốn và di chuyển khắp Nhật Bản. Trong thời gian này, anh ta gặp Sayaka, Kazuya và Mai. Thám tử Matanuki đang trên đường truy bắt Kaburagi. Ông thẩm vấn những người đã gặp Kaburagi, nhưng mỗi người lại miêu tả Kaburagi khác nhau. Kaburagi đã mất tích 488 ngày. Kaburagi thực sự là ai? Kế hoạch của anh ta là gì?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryusei Yokohama","avatar":""},{"name":"Riho Yoshioka","avatar":""},{"name":"Shintaro Morimoto","avatar":""},{"name":"Anna Yamada","avatar":""},{"name":"Takayuki Yamada","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shōtai","Shotai","Shoutai","Faceless","真实身份","嫌疑者的真相","正体","Sin Rostro"]', 1784690324219);
