INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('danh-tinh-thuc-su', 'Danh Tính Thực Sự', 'Faceless', 'danh tính thực sự faceless ryusei yokohama riho yoshioka shintaro morimoto anna yamada takayuki yamada shōtai shotai shoutai faceless 真实身份 嫌疑者的真相 正体 sin rostro', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-em-o-ngay-the-gioi-ket-thuc-ban-dien-anh', 'Cùng Em Ở Ngày Thế Giới Kết Thúc (Bản Điện Ảnh)', 'Love You As The World Ends Final: The Movie', 'https://phimimg.com/upload/vod/20250210-1/6034b3ab34f5ac644d9fdc92d34f5de8.jpg', 'https://phimimg.com/upload/vod/20250210-1/f8cf6ed90384cd1981feee558b7c438d.jpg', '<p>Utopia từng là tòa tháp của hy vọng, nhưng nó trở thành tòa tháp của tuyệt vọng do dục vọng của con người tạo ra. Trong Utopia, họ đang nghiên cứu cách duy nhất để cứu thế giới này: một loại vắc-xin chống lại quái vật được gọi là Golem. Một cô gái có kháng thể đặc biệt đã được sử dụng làm vật liệu nghiên cứu. Cô gái ấy tên là Mirai, con gái của Hibiki Mamiya. Hibiki quyết định giải cứu Mirai cùng với năm người đàn ông đã tụ họp tại Utopia. Những người đàn ông này đang cố gắng cứu người thân, gia đình và bạn bè của họ, và ăn trộm lương thực, tiền bạc để sinh tồn. Mặc dù mỗi người có lập trường riêng và một số nổi loạn, nhưng dần dần họ bắt đầu đồng cảm với niềm tin của Hibiki và quyết định chiến đấu cùng nhau.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryoma Takeuchi","avatar":""},{"name":"Fumiya Takahashi","avatar":""},{"name":"Mayu Hotta","avatar":""},{"name":"Rihito Itagaki","avatar":""},{"name":"Airu Kubozuka","avatar":""},{"name":"Yuki Tachibana","avatar":""},{"name":"Sakura Kiryu","avatar":""},{"name":"Kenta Suga","avatar":""},{"name":"Ryosuke Mikata","avatar":""},{"name":"Mario Kuroba","avatar":""},{"name":"Kotaro Yoshida","avatar":""},{"name":"Ayami Nakajo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Gekijoban Kimi to Sekai ga Owaru Hi ni FINAL","Kimi to Sekai ga Owaru Hi ni FINAL","劇場版 君と世界が終わる日に FINAL"]', 1784690324219);
