INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-khong-the-noi-ra', 'Bí Mật Không Thể Nói Ra', 'Secret: A Hidden Score', 'https://phimimg.com/upload/vod/20250210-1/c9424ea5989bebc3fe7751d091b57af2.jpg', 'https://phimimg.com/upload/vod/20250210-1/e0be654ba36a16f5f279c649c87c3588.jpg', '<p>Minato học piano tại một học viện âm nhạc. Một ngày nọ, anh ta phải lòng Yukino, một sinh viên cùng khóa, người đang mang trong mình một bí mật đau buồn sẽ thử thách tình yêu của họ.</p>', 'Full', 1, 'single', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Taiga Kyomoto","avatar":""},{"name":"Kotone Furukawa","avatar":""},{"name":"Mayuu Yokota","avatar":""},{"name":"Ryota Miura","avatar":""},{"name":"Ryotaro Sakaguchi","avatar":""},{"name":"Sarutoki Minagawa","avatar":""},{"name":"Naomi Nishida","avatar":""},{"name":"Toshinori Omi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不能说的秘密 日本版","เพลงรักพาเธอกลับมา","Secret: A Hidden Score","Ienai Himitsu","不能說的秘密","不能说的秘密","言えない秘密"]', 1784690324219);
