INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sachan-men-thuong', 'Sa-chan Mến Thương', 'Dear Sa-chan', 'https://phimimg.com/upload/vod/20250209-1/b754af8e68d2dea307457ae19650bb2d.jpg', 'https://phimimg.com/upload/vod/20250209-1/6661b99a896f49bafa6d0d2546665357.jpg', '<p>Sa-chan thân mến, giá như lúc đó anh làm tình với em thì có lẽ anh đã không phải đi vào con đường tai hại này. Một câu chuyện về tình yêu đích thực và sự sụp đổ của nó, được làm sống lại bởi một người được bảo hộ độc đáo.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ren Ishikawa","avatar":""},{"name":"Keito Kimura","avatar":""},{"name":"Hinano Nakayama","avatar":""},{"name":"Dori Sakurada","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sacchan, Boku wa.","Querida Sa-chan","ซัตจังครับ คือว่าผม","小早、我啊。","Dear Sa-chan","さっちゃん、僕は。"]', 1784690324219);
