INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-loi-o-phan-lan', 'Lạc Lối Ở Phần Lan', 'Rented In Finland', 'https://phimimg.com/upload/vod/20241209-1/38ab15572362f16b9d8da7fb890d75a4.jpg', 'https://phimimg.com/upload/vod/20241209-1/94493e358c9378062d7532e49becdb3d.jpg', '<p>Bốn chàng tài tử nổi tiếng màn ảnh Hàn gồm Lee Je Hoon, Cha Eun Woo, Lee Dong Hwi và Kwak Dong Yeon sẽ &quot;di cư&quot; đến quê hương của ông già Noel ở Lapland, Phần Lan. Thử thách cuộc sống mới đầy thú vị với lối sống tự cung tự cấp của người bản địa, họ sẽ xoay xở thế nào khi mà đến cả điện và nước máy cũng là những thứ xa xỉ?</p>', 'Hoàn Tất (20/20)', 20, 'tvshows', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Je-hoon","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Kwak Dong-yeon","avatar":""},{"name":"Cha Eun-woo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["핀란드 셋방살이","Finland rent-a-room","Rent a room: Finland","Living in a Rented Room in Finland"]', 1784690324219);
