INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dep-va-co-don', 'Sắc Đẹp và Cô Đơn', 'Parthenope', 'https://phimimg.com/upload/vod/20250208-1/f5a9691f75496dfe2391bf014d0ba2c8.jpg', 'https://phimimg.com/upload/vod/20250208-1/d215bf1fe5a93f3a5189e9dcdae2e2fd.jpg', '<p>Phim kể về cuộc đời của Parthenope, một cô gái xinh đẹp, bí ẩn và thông minh, sinh ra gần biển Naples năm 1950. Vẻ đẹp của cô thu hút nhiều người theo đuổi nhưng cũng mang đến những hệ lụy. Trên hành trình trưởng thành, cô khám phá tình yêu, đam mê và nỗi cô đơn, chạm trán những nhân vật lừng danh, trong đó có nhà văn John Cheever (Gary Oldman).&nbsp;Bộ phim là bức tranh đầy mê hoặc về sự giao thoa giữa nhan sắc, hạnh phúc và nỗi buồn, với phong cách đậm chất thơ của Sorrentino.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Celeste Dalla Porta","avatar":""},{"name":"Stefania Sandrelli","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Silvio Orlando","avatar":""},{"name":"Luisa Ranieri","avatar":""},{"name":"Peppe Lanzetta","avatar":""},{"name":"Isabella Ferrari","avatar":""},{"name":"Silvia Degrandi","avatar":""},{"name":"Lorenzo Gleijeses","avatar":""},{"name":"Daniele Rienzo","avatar":""},{"name":"Dario Aita","avatar":""},{"name":"Marlon Joubert","avatar":""},{"name":"Alfonso Santagata","avatar":""},{"name":"Biagio Izzo","avatar":""},{"name":"Nello Mascia","avatar":""},{"name":"Francesca","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["帕特诺普","帕尔忒诺普","Parthenope: Los amores de Nápoles","Parthenope: Os Amores de Nápoles","Партенопа","Parthenope - Napolis datter","Parthenope - Napolin kauneus","Παρθενόπη",