INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-hoa-cay-bo-de', 'Tinh Hoa Cây Bồ Đề', 'The Seed Of The Sacred Fig', 'tinh hoa cây bồ đề the seed of the sacred fig misagh zare soheila golestani mahsa rostami setareh maleki niousha akhshi reza akhlaghirad shiva ordooie amineh mazrouie arani mohammad kamal alavi parisa mohyedini barat azimi die saat des heiligen feigenbaums daneh anjeer moghadas 신성한 나무의 씨앗 les graines du figuier sauvage dane-ye anjir-e ma''abed the seed of the sacred fig a szent füge magja nasiona świętej figi семя священного инжира sinseonghan namuui ssias la semilla de la higuera sagrada det heliga trädets frukter kutsal i̇ncirin tohumu a semente da figueira sagrada 神圣无花果之种 دانه‌ی انجیر معابد a semente do figo sagrado sămânța smochinului sacru دانه های انجیر معابد les graines du figuier sauvage', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-ket-hon-moi-duoc', 'Phải Kết Hôn Mới Được', 'Save It For The Honey Moon', 'https://phimimg.com/upload/vod/20250208-1/ecbb6305e6a0348b6a71d678a704ae1d.jpg', 'https://phimimg.com/upload/vod/20250208-1/c3167c5add48b1631b4c4e181492def7.jpg', '<p>Lâm Tuyết Nồng là một nhân viên ủ rượu bình thường trong nhà máy rượu. Vì muốn kiếm tiền nuôi bản thân và lo cho bố, cô chỉ một lòng muốn tập trung vào công việc, không có hứng thú với chuyện yêu đương. Nhưng rồi cuộc sống của cô bỗng đảo lộn hoàn toàn khi Chu Hoành, tổng giám đốc mới ở công ty của cô, đến nhậm chức.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Quản Lịch","avatar":""},{"name":"Lâm Tiểu Trạch","avatar":""},{"name":"Lãnh Tâm Thanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["結婚才可以","结婚才可以"]', 1784690324219);
