INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-quyet-sai-lam', 'Phán Quyết Sai Lầm', 'The Prosecutor', 'https://phimimg.com/upload/vod/20250207-1/e6ad20bb533f06d7e602a0459c2b653e.jpg', 'https://phimimg.com/upload/vod/20250207-1/1d281f96ac4a5e3dc35adfd3c0fbf988.jpg', '<p>Một vụ án buôn bán ma túy bất công khiến bị cáo phải đối mặt với án tù 27 năm. Công tố Tử Hào, một cựu thanh tra, đã dựa vào sự nhạy bén và kiên trì của mình để mở cuộc điều tra. Cuộc đấu tranh sinh tử ở hậu trường sắp nổ ra. Ngày xét xử cuối cùng đang đến gần. Liệu Tử Hào có thể đập tan sự bất công và lật ngược bản án?</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Francis Ng Chun-Yu","avatar":""},{"name":"Julian Cheung Chi-Lam","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Michael Hui Koon-Man","avatar":""},{"name":"Lau Kong","avatar":""},{"name":"Mason Fung Ho-Yeung","avatar":""},{"name":"MC Cheung","avatar":""},{"name":"Yu Kang","avatar":""},{"name":"Adam Pak Tin-Nam","avatar":""},{"name":"Locker Lam Ka-Hei","avatar":""},{"name":"Tommy Chu Pak-Hong","avatar":""},{"name":"Shirley Chan Yan-Yin","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Misjudgement","誤判","The Prosecutor","误判","El Fiscal","Juicio Erroneo","El Lado Oscuro de la Justicia","El Fiscal: El Lado Oscuro de la Justicia"]', 1784690324219);
