INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kromoleo-su-am-anh', 'Kromoleo: Sự Ám Ảnh', 'Kromoleo: The Haunting', 'https://phimimg.com/upload/vod/20250104-1/68ade38e843cd85eb3d6b139496f236f.jpg', 'https://phimimg.com/upload/vod/20250104-1/a48393be9baa369e60cf9cb8eaca12c7.jpg', '<p>Zia, một cô gái trẻ đến từ Djarot, một tên côn đồ có biệt danh là Gali, đã kết hôn với con gái của mình là Danang, người thực sự là thủ lĩnh của PETRUS (BẮN SÚNG BÍ ẨN). Khi Danang không còn cần Djarot và Gali mà hắn đang sử dụng nữa, Danang quyết định giết chóc và tàn sát. Tất cả kể từ đó, những linh hồn bồn chồn của người Gali đã chết đã xuất hiện, trở thành một nhóm hồn ma chở những chiếc quan tài khiến dân làng gọi là “KROMOLEO”, bất cứ ai chứng kiến Kromoleo phải sợ hãi. sẽ chết vì nỗi kinh hoàng của Kromoleo, Zia bị mắc kẹt giữa 2 sự lựa chọn, chọn Danang, ông nội cô hoặc Djarot, cha cô.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Safira Ratu Sofya","avatar":""},{"name":"Tio Pakusadewo","avatar":""},{"name":"Abun Sungkar","avatar":""},{"name":"Rukman Rosadi","avatar":""},{"name":"Cornelio Sunny","avatar":""},{"name":"Totos Rasiti","avatar":""},{"name":"Aline Fauziah","avatar":""},{"name":"Dayu Wijanto","avatar":""},{"name":"Vonny Anggraini","avatar":""},{"name":"Ilham Setyadi","avatar":""},{"name":"Kemal Giffari","avatar":""},{"name":"Nick Musa","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kromoleo: Hantu Keranda","Kromoelo: Teror 1 Malam","猛鬼村","Kromoleo"]', 1784690324219);
