INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-yeu', 'Em Yêu', 'Babygirl', 'https://phimimg.com/upload/vod/20250206-1/be68c22869bee8d7171039546c2c3c1d.jpg', 'https://phimimg.com/upload/vod/20250206-1/5829c9ff91099a508e8b95ce65265e3f.jpg', '<p>Câu chuyện xoay quanh Romy Mathis, một nữ doanh nhân thành đạt nhưng cảm thấy cuộc sống cá nhân thiếu sự thỏa mãn. Cô bắt đầu một mối quan hệ tình cảm mãnh liệt với Samuel, thực tập sinh trẻ tuổi tại công ty của mình. Mối quan hệ này đặt sự nghiệp và gia đình của Romy vào tình thế nguy hiểm, khi cô phải đối mặt với những xung đột nội tâm về quyền lực, dục vọng và trách nhiệm.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Harris Dickinson","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Esther-Rose McGregor","avatar":""},{"name":"Sophie Wilde","avatar":""},{"name":"Vaughan Reilly","avatar":""},{"name":"Victor Slezak","avatar":""},{"name":"Leslie Silva","avatar":""},{"name":"Gaite Jansen","avatar":""},{"name":"Robert Farrior","avatar":""},{"name":"Bartley Booz","avatar":""},{"name":"Anoop Desai","avatar":""},{"name":"Mary Ann Lamb","avatar":""},{"name":"Gabrielle Policano","avatar":""},{"name":"Gabriela Torres","avatar":""},{"name":"Izabel Mar","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["宝贝女孩","宝贝","Babygirl Deseo Prohibido","Хороша погана дівчинка","Плохая девочка","乖女孩","बेबीगर्ल","বেবিগার্ল","Աղջնակը","熟女诱罪","Babygirl"]', 1784690324219);
