INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-painted', 'The Painted', 'The Painted', 'https://phimimg.com/upload/vod/20250206-1/6585a8c327e6890a3281dc03c076c978.jpg', 'https://phimimg.com/upload/vod/20250206-1/cc93d1232415255f7f8b6390e79381e6.jpg', '<p>Khi Evelyn Elster thừa kế tài sản của người em họ xa lạ, cô nghĩ rằng gia đình mình cuối cùng đã có được cơ hội mà họ cần. Ít ai ngờ rằng họ không chỉ thừa kế được tài sản của người em họ, mà còn cả một lời nguyền gia đình, và phải làm mọi thứ có thể để tránh trở thành nạn nhân mới nhất của nó.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Aleksa Palladino","avatar":""},{"name":"Sean Bridgers","avatar":""},{"name":"Jadon Cal","avatar":""},{"name":"Jessica Ruth Bell","avatar":""},{"name":"Zara King","avatar":""},{"name":"Amadeus Serafini","avatar":""},{"name":"Patrice Johnson","avatar":""},{"name":"Gary Poux","avatar":""},{"name":"Carl Solomon","avatar":""},{"name":"Time Winters","avatar":""},{"name":"Jill Young","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Maldición de Evelyn","Retratos Siniestros","The Painted"]', 1784690324219);
