INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-ngan-troi-may', 'Muôn Ngàn Trời Mây', 'Your Sky', 'https://phimimg.com/upload/vod/20241123-1/f14f2b3287f7b656cc3c87d3d55392ce.jpg', 'https://phimimg.com/upload/vod/20241123-1/cd21c00b4def93202ceac6491ea90dcf.jpg', '<p>Teerak (Kong), một sinh viên năm nhất đại học đầy lạc quan, được các anh chị khóa trên đặt cho biệt danh mới là &quot;má chảy xệ&quot;. Một ngày nọ, tại một bữa tiệc, Teerak đồng ý uống rượu dù cho người bạn thân nhất cậu, Punlee khuyên anh không làm vậy. Trong khi Teerak say, một anh chàng cố gắng tán tỉnh cậu. Sau đó, chủ nhà hàng, Muenfah, anh trai của Punlee, đến giải cứu Teerak. Teerak say xỉn từ sau đó ngưỡng mộ Muenfah và dụ dỗ anh khi anh đưa cậu về nhà. Teerak cầu xin Muenfah hôn lên đầu mình, trong khi không biết rằng Muenfah đã thầm thích cậu một thời gian dài.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kongpob Jirojmontri","avatar":""},{"name":"Teetut Chungmanirat","avatar":""},{"name":"Suppakarn Jirachotikul","avatar":""},{"name":"Thanaphum Sestasittikul","avatar":""},{"name":"Worapong Walor","avatar":""},{"name":"Jirachart Buspavanich","avatar":""},{"name":"In Inthira Sae-sieo","avatar":""},{"name":"Chinnarat Siriphongchawalit","avatar":""},{"name":"Morakot Liu","avatar":""},{"name":"Piamchon Damrongsunthornchai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["缘定天空","YSTS","Ki Muen Fa","Gee Meun Faa","กี่หมื่นฟ้า Your Sky of us","Your Sky The Series","กี่หมื่นฟ้า"]', 1784690324219);
