INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muon-ngan-troi-may', 'Muôn Ngàn Trời Mây', 'Your Sky', 'muôn ngàn trời mây your sky kongpob jirojmontri teetut chungmanirat suppakarn jirachotikul thanaphum sestasittikul worapong walor jirachart buspavanich in inthira sae-sieo chinnarat siriphongchawalit morakot liu piamchon damrongsunthornchai 缘定天空 ysts ki muen fa gee meun faa กี่หมื่นฟ้า your sky of us your sky the series กี่หมื่นฟ้า', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-cam-nhan-gia', 'Thục Cẩm Nhân Gia', 'Brocade Odyssey', 'https://phimimg.com/upload/vod/20241201-1/c89ee8750c4764f7fbafbcef76a09b34.jpg', 'https://phimimg.com/upload/vod/20241201-1/29f8aabe3c745a60efec0ca36ac10fd8.jpg', '<p>“Thục Cẩm Nhân Gia” là câu chuyện về lòng dũng cảm, đấu tranh và không sợ gian khổ. Nó xoay quanh huyền thoại về Quý Anh Anh với tính cách mạnh mẽ, từ một cô gái trẻ ở phường nhuộm Hoán Hoa trở thành một nữ thợ thủ công. Vào thời nhà Đường, vẻ đẹp của gấm Thục đã được người đời biết đến, giới quyền quý đổ xô theo nó, trong quân đội thậm chí có thể “dùng gấm để đổi lấy lương bổng”, tấc gấm tấc vàng. Nó trở thành mục tiêu tranh giành lợi ích của tất cả các thế lực. Dưới sự thịnh vượng của ngành gấm ở Ích Châu là sóng ngầm dữ dội. Tơ đỏ gấm Thục của nhà họ Quý ở Ích Châu vô cùng hiếm có, và nổi danh là “Gấm đỏ xuất hiện, ngàn đỏ lu mờ”. Tuy nhiên, nhà họ Quý không may dính líu đến vụ án gấm giả, gia chủ chết trong ô nhục, cả gia đình rơi vào cảnh điêu tàn chỉ sau một đêm. Tiểu thư nhà họ Quý, Quý Anh Anh, từ nhỏ đã thông minh, say mê nhuộm lụa, tài năng dần dần bộc lộ, nàng quyết chí chấn hưng gia nghiệp, minh oan cho cha.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tan Songyun","avatar":""},{"name":"Zheng Yecheng","avatar":""},{"name":"Jing Chao","avatar":""},{"name":"Zhang Haowei","avatar":""},{"name":"Chen Xiaoyun","avatar":""},{"name":"Wang Yinuo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Brocade Odyssey","蜀锦人家"]', 1784690324219);
