INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-vu-van-gian', 'Mặc Vũ Vân Gian', 'The Double', 'https://phimimg.com/upload/vod/20240602-1/ea00932d509eda54c198f4789859cead.jpg', 'https://phimimg.com/upload/vod/20240602-1/a4e5d5c008ab10331cc06e2aea0a0e99.jpg', '<p>Mặc Vũ Vân Gian là hành trình đi tìm công lý của nàng tiểu thư nhà huyện lệnh Tiết Phương Phi dưới sự giúp đỡ của quốc công lạnh lùng Tiêu Hoành. Sau khi thi đỗ trạng nguyên, chồng của Phương Phi vì muốn kết hôn với công chúa mà rắp tâm hãm hại, dồn nàng vào bước đường cùng. May mắn thoát chết, Phương Phi lấy thân phận của ân nhân cứu mạng là Khương Lê để hồi kinh, lên kế hoạch báo thù.</p>', 'Hoàn Tất (41/41)', 40, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Cẩn Ngôn","avatar":""},{"name":"Vương Tinh Việt","avatar":""},{"name":"Trần Hâm Hải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324219);
