INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cam-tu-ky-cuu', 'Đội Cảm Tử Kỳ Cựu', 'Elderly Expendables Team', 'https://phimimg.com/upload/vod/20250126-1/ba5bae54caffe57187bb05fcb67b4dbb.jpg', 'https://phimimg.com/upload/vod/20250126-1/e64640eaa27730220c591c5a99fcbe46.jpg', '<p>3 vận động viên thể thao đã về hưu Cao Đạt, Ngô Lập Vỹ, Kim Thạch Ứng nhận được lời mời từ người bạn cũ Hoa Dung tham gia chuyến du lịch Đông Nam Á. Tại đây, họ phát hiện ra con gái của Hoa Dung là Hoa Xuất Trần bị một băng đảng địa phương bắt giữ trái phép và đòi khoản tiền chuộc khổng lồ. Không thể nhờ ai giúp đỡ, bốn người quyết định tự thành lập một đội đặc nhiệm tuổi già, dũng cảm xông vào băng đảng. Họ không chỉ giải cứu được Hoa Xuất Trần mà còn giải thoát cho những đồng bào khác bị giam giữ.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Ding Haifeng","avatar":""},{"name":"Shen Yu","avatar":""},{"name":"田锋","avatar":""},{"name":"Cai Xuanyi","avatar":""},{"name":"Shi Xuanru","avatar":""},{"name":"Wang Hui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["老炮敢死隊","Old Cannons Suicide Squad","Old Cannon Expendables Team","老炮敢死队"]', 1784690324219);
