INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dieu-tra-so-7-phan-2-guong-mat-van-veo', 'Đội Điều Tra Số 7 (Phần 2) : Gương Mặt Vặn Vẹo', 'Investigation Team No. 7 (Season 2) : Twisted Face', 'https://phimimg.com/upload/vod/20241217-1/299cc9528266c12d0124041d741e153d.jpg', 'https://phimimg.com/upload/vod/20241217-1/58cdaf811fad4513de17f40ff07486f5.jpg', '<p>Phim khắc hoạ những nhiệm vụ hóc búa của lực lượng cảnh sát hình sự, thủ đoạn gây án tinh vi của các đối tượng có trí tuệ khác thường gây nên nhiều khó khăn trong quá trình điều tra. Bên cạnh sự đấu trí căng thẳng, kịch bản phim còn mang đến những cảnh quay hành động đẹp mắt, ấn tượng, khai thác bối cảnh độc đáo, hoang sơ, rùng rợn. Bộ phim là tác phẩm tâm huyết của Điện ảnh CAND cùng tất cả ekip sản xuất, hứa hẹn sẽ mang đến cho khán giả những phút giây theo dõi, trải nghiệm hấp dẫn nhưng cũng mang ý nghĩa giá trị nhân văn sâu sắc.</p>', 'Tập 15', 40, 'series', 'ongoing', 14, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Chiều Xuân","avatar":""},{"name":"Bá Anh","avatar":""},{"name":"Xuân Tùng","avatar":""},{"name":"Thanh Hương","avatar":""},{"name":"Trung Ruồi","avatar":""},{"name":"Thụy Hòa","avatar":""},{"name":"Tùng Minh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Arthur Askey Show"]', 1784690324219);
