INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-phieu', 'Lá Phiếu', 'Balota', 'https://phimimg.com/upload/vod/20250203-1/389147114d317c8363376954b4e9e079.jpg', 'https://phimimg.com/upload/vod/20250203-1/b42fc145b9ce3f2ef60e1c7961e7567f.jpg', '<p>Một giáo viên liều mạng bảo vệ một thùng phiếu chứa đầy những lá phiếu quan trọng khi các thế lực thối nát đe dọa lật ngược kết quả của một cuộc bầu cử then chốt ở địa phương.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Marian Rivera","avatar":""},{"name":"Will Ashley","avatar":""},{"name":"Royce Cabrera","avatar":""},{"name":"Nico Antonio","avatar":""},{"name":"Donna Cariaga","avatar":""},{"name":"Sassa Gurl","avatar":""},{"name":"Esnyr Ranollo","avatar":""},{"name":"Sue Prado","avatar":""},{"name":"Raheel Bhyria","avatar":""},{"name":"Joel Saracho","avatar":""},{"name":"Gardo Versoza","avatar":""},{"name":"Mae Paner","avatar":""},{"name":"Myke Salomon","avatar":""},{"name":"Carlo Enciso Catu","avatar":""},{"name":"Dylan Ray Talon","avatar":""},{"name":"Jade Castro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Balota"]', 1784690324219);
