INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-truy-hon', 'Ác Quỷ Truy Hồn', 'Sakaratul Maut', 'https://phimimg.com/upload/vod/20250203-1/c0d633ba773cd17171c656ad8ba7b3ea.jpg', 'https://phimimg.com/upload/vod/20250203-1/785eeb832038e59b86c3325fff8f963e.jpg', '<p>Sau một tai nạn, cô gái trẻ Retno mất mẹ, trong khi cha cô rơi vào tình trạng hôn mê. Cô cùng chị gái mình quyết định đưa cha về chăm sóc, nhưng quãng thời gian này trở thành địa ngục với cả gia đình khi những sự kiện ghê rợn liên tiếp xảy ra. Cùng lúc đó, sự xuất hiện của người con trai ngoài giá thú của cha cô châm ngòi cho cuộc chiến tranh giành khoản thừa kế, đồng thời mở ra những bí ẩn kinh hoàng trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Indah Permatasari","avatar":""},{"name":"Claresta Taufan","avatar":""},{"name":"José Rizal Manua","avatar":""},{"name":"Della Dartyan","avatar":""},{"name":"Retno Soetarto","avatar":""},{"name":"Aksara Dena","avatar":""},{"name":"Maryam Supraba","avatar":""},{"name":"Landung Simatupang","avatar":""},{"name":"Nayla Sakhi","avatar":""},{"name":"Rendra Bagus Pamungkas","avatar":""},{"name":"Siti Fauziah","avatar":""},{"name":"Muhammad Irfan Nurjihad","avatar":""},{"name":"Zafran Batutah","avatar":""},{"name":"Sharon Gracella","avatar":""},{"name":"Putri Manjo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ác Quỷ Truy Hồn","Sakaratul Maut"]', 1784690324219);
