INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-hoan-hao-2024', 'Gia Đình Hoàn Hảo', 'A Normal Family', 'https://phimimg.com/upload/vod/20250202-1/65f222a9e4b66154862d7d2365a8145c.jpg', 'https://phimimg.com/upload/vod/20250202-1/2343d41ee69792449ca3d77186e727d4.jpg', '<p>Jae-wan là một luật sư chuyên bào chữa thành công cho những vụ án giết người. Em trai Jae-wan là một bác sĩ lương tri, luôn ưu tiên và đặt bệnh nhân lên trên lợi ích của chính mình. Bất ngờ, một sự việc nghiêm trọng giữa hai người con của hai anh em đã diễn ra và đặt ra cho họ một bài toán lương tâm về hướng giải quyết.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Sul Kyung-gu","avatar":""},{"name":"Jang Dong-gun","avatar":""},{"name":"Kim Hee-ae","avatar":""},{"name":"Claudia Kim","avatar":""},{"name":"Hong Ye-ji","avatar":""},{"name":"Kim Jung-chul","avatar":""},{"name":"Choi Ri","avatar":""},{"name":"Yoo Su-bin","avatar":""},{"name":"Byun Joong-hee","avatar":""},{"name":"Ahn Ye-rim","avatar":""},{"name":"Yu In-seon","avatar":""},{"name":"Choi Eden","avatar":""},{"name":"Bang Ga-eul","avatar":""},{"name":"Roh Jae-won","avatar":""},{"name":"Lee Ga-kyung","avatar":""},{"name":"Jeon Yeong","avatar":""},{"name":"Lee Sae-ro-mi","avatar":""},{"name":"Song Woo-rim","avatar":""},{"name":"Jo Jin-kyul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Dinner","더 디너","非普通家族","Gia Đình Hoàn Hảo","満ち足りた家族","Нормальная семья","Uma Família Normal","Botong-ui Gajok","یک خانواده معمولی","משפחה נורמלית","এ নরমাল ফ্যামিলি","普通家庭","良心風暴","ลูกฉัน... เป็นคนดี","보통의 가족"]', 1784690324219);
