INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-hoan-hao-2024', 'Gia Đình Hoàn Hảo', 'A Normal Family', 'gia đình hoàn hảo a normal family sul kyung-gu jang dong-gun kim hee-ae claudia kim hong ye-ji kim jung-chul choi ri yoo su-bin byun joong-hee ahn ye-rim yu in-seon choi eden bang ga-eul roh jae-won lee ga-kyung jeon yeong lee sae-ro-mi song woo-rim jo jin-kyul the dinner 더 디너 非普通家族 gia đình hoàn hảo 満ち足りた家族 нормальная семья uma família normal botong-ui gajok یک خانواده معمولی משפחה נורמלית এ নরমাল ফ্যামিলি 普通家庭 良心風暴 ลูกฉัน... เป็นคนดี 보통의 가족', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giot-mua-mang-mui-ri-set', 'Giọt Mưa Mang Mùi Rỉ Sét', 'Petrichor', 'https://phimimg.com/upload/vod/20241124-1/c35dd5d852e5584d390b7e981ce08995.jpg', 'https://phimimg.com/upload/vod/20241124-1/78f0bd072c87bfd3d8a53caf6aa49044.jpg', '<p>Chuyến công tác đầu tiên của Tul trong công việc mới không suôn sẻ như mong đợi. Tình hình càng trở nên tồi tệ hơn khi cô phải làm việc với Cherran, bác sĩ pháp y phụ trách vụ án. Tính cách và thái độ của họ xung đột, dẫn đến mối quan hệ làm việc căng thẳng. Họ còn phải đối mặt với áp lực dư luận, khiến các vụ án họ đang điều tra thêm phần khó khăn. Tuy nhiên, khi có nhiều cơ hội làm việc cùng nhau hơn, mối quan hệ giữa Tul và Cherran dần dần được cải thiện. Qua thời gian, họ bắt đầu hiểu nhau hơn và học cách hợp tác hiệu quả, từ đó tạo nên một đội ngũ ăn ý trong công việc.</p>', 'Tập 10', 10, 'series', 'ongoing', 11, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Charlotte Austin","avatar":""},{"name":"Engfa Waraha","avatar":""},{"name":"Rina Chatamonchai","avatar":""},{"name":"Naphat Vikairungroj","avatar":""},{"name":"Nattapol Diloknawarit","avatar":""},{"name":"Rathavit Kijworalak","avatar":""},{"name":"Inntouch Naphat Chalermphonphakdee","avatar":""},{"name":"Atom Nathaphop Kanjanteak","avatar":""},{"name":"Film Jirayu Aungvanich","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["페트리코르","Yod Fon Klin Sanim","Yut Fon Klin Sanim","Petrichor The Series","Rust-Smelling Raindrops","หยดฝนกลิ่นสนิม"]', 1784690324219);
