INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-day-sao-2024', 'Đêm Đầy Sao', 'Namib', 'https://phimimg.com/upload/vod/20250105-1/8fcd3bcb511aa53a2eeec3077f0e04ff.jpg', 'https://phimimg.com/upload/vod/20250105-1/716dead0dc7c9cfc234a6cf8c6e05095.jpg', '<p>Bộ phim lấy bối cảnh ngành giải trí Hàn, mô tả những thách thức của một cựu CEO bị sa thải và một thực tập sinh không thể ra mắt. Kang Soo Hyun (Go Hyun Jung) là cựu giám đốc điều hành của Pandora Entertainment và đang đứng trước nguy cơ phải ra đi tay trắng sau sau một cuộc họp hội đồng khẩn cấp do bị nghi ngờ lạm dụng quyền lực. Trong khi đó Yoo Jin Wo (Ryeowoon) là một thực tập sinh bị đuổi khỏi công ty với khoản nợ 200 triệu won.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ko Hyun-jung","avatar":""},{"name":"Ryeoun","avatar":""},{"name":"Yoon Sang-hyun","avatar":""},{"name":"Lee Jin-woo","avatar":""},{"name":"Lee Gi-taek","avatar":""},{"name":"Kim Hyun-sook","avatar":""},{"name":"In Gyo-jin","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Choi Yu-ju","avatar":""},{"name":"Sa Kang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["纳米布","星星闪耀的夜晚","شب پرستاره","나미브","ناميب","星星閃耀的夜晚","The Starry Night"]', 1784690324219);
