INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-nang-nha-cai-phan-2', 'Cẩm Nang Nhà Cái (Phần 2)', 'Bookie (Season 2)', 'https://phimimg.com/upload/vod/20241224-1/95039a5eec737ed5c1eb070d440aeb2b.jpg', 'https://phimimg.com/upload/vod/20241224-1/2eef060cd04a3a052c30fc7f2dc7a6be.jpg', '<p>Mùa hai của loạt phim truyền hình Cẩm Nang Nhà Cái tiếp tục là những câu chuyện đời thường của một anh chàng chuyên đi nhận cá cược bất hợp pháp, và những rắc rối trái khoáy khi đi đòi tiền những &quot;con bạc khát nước&quot;.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sebastian Maniscalco","avatar":""},{"name":"Omar J. Dorsey","avatar":""},{"name":"Jorge Garcia","avatar":""},{"name":"Andrea Anders","avatar":""},{"name":"Vanessa Ferlito","avatar":""},{"name":"Maxim Swinton","avatar":""},{"name":"Rob Corddry","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["组头真命苦","סוכן ההימורים","How to Be a Bookie","Bookie"]', 1784690324219);
