INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-muoi', 'Hai Muối', 'Salt''s Papa', 'https://phimimg.com/upload/vod/20250128-1/2089c4ade5ce274d97fa9e9ce82a4c97.jpg', 'https://phimimg.com/upload/vod/20250128-1/ede258f75b02c54deeb80dd9f8d43565.jpg', '<p>Là màn trở lại sau 20 năm của diễn viên Quyền Linh. Mối quan hệ giữa Muối, cô gái mồ côi mẹ và người cha hết mực yêu thương chuyển sang bước ngoặt khi cô rời lên thành phố cùng giấc mơ đổi đời.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Quyền Linh","avatar":""},{"name":"Kim Hải","avatar":""},{"name":"Hồng Vân","avatar":""},{"name":"Việt Anh","avatar":""},{"name":"Tú Tri","avatar":""},{"name":"Minh Luân","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Huỳnh Bảo Ngọc","avatar":""},{"name":"Năm Chà","avatar":""},{"name":"Tạ Lâm","avatar":""},{"name":"Kiều Oanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Hai Muối"]', 1784690324220);
