INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-darim', 'Gia Đình Darim', 'Iron Family', 'https://phimimg.com/upload/vod/20241008-1/33dd4ecd6efc1081209afebf7285ae44.jpg', 'https://phimimg.com/upload/vod/20241008-1/a98f562015459671da8ad0a9b66acc8f.jpg', '<p>Gia Đình Darim (Iron Family) là câu chuyện về tình yêu và xung đột trong một gia đình, mở ra cơ hội để khán giả suy ngẫm về ý nghĩa của gia đình trong xã hội hiện đại. Với sự tham gia của các diễn viên hàng đầu như 김정현, 금새록, 최태준, 양혜지, phim mang lại cái nhìn sâu sắc về các mối quan hệ gia đình. Đạo diễn tài năng Sung Joon-hae đã tạo nên một bức tranh sống động về cuộc sống gia đình thông qua Iron Family.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Jung-hyun","avatar":""},{"name":"Geum Sae-rok","avatar":""},{"name":"Choi Tae-joon","avatar":""},{"name":"Yang Hye-ji","avatar":""},{"name":"Lee Sung-yeol","avatar":""},{"name":"Shin Hyun-joon","avatar":""},{"name":"Park Ji-young","avatar":""},{"name":"Kim Hye-eun","avatar":""},{"name":"Kim Yeong-ok","avatar":""},{"name":"Park In-hwan","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Darimi Paemilri","العائلة الحديدية","다리미 패밀리"]', 1784690324220);
