INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-xuan-dao-diet-ta', 'Tú Xuân Đao: Diệt Tà', 'Brotherhood of Blades: Exterminate Evil', 'https://phimimg.com/upload/vod/20250116-1/1a0a6da22b3ea4b522d29c9d8fbbc23d.jpg', 'https://phimimg.com/upload/vod/20250116-1/d09b761ba08c1f417d5eb5f94cca5aa0.jpg', '<p>Vào năm Thiên Khải triều Minh, triều đình chia bè phái đấu đá, hoạn quan lộng hành. Một đêm nọ, cánh tay đắc lực của phe hoạn quan là Thôi Tứ đột ngột chết một cách kỳ lạ trong phủ. Viên hoạn quan quyền lực Ngụy Trung Hiền tức giận, ra lệnh Cẩm y vệ điều tra vụ việc. Thiên hộ Từ Phan Tinh chỉ định tiểu kỳ Cẩm y vệ là Sở Mặc chịu trách nhiệm điều tra. Tuy luôn giữ vững lòng chính nghĩa và không muốn đồng lõa với phe hoạn quan, Sở Mặc đành miễn cưỡng nhận nhiệm vụ. Thế nhưng, càng đi sâu vào vụ án, Sở Mặc càng phát hiện ra một âm mưu khổng lồ đang ẩn giấu đằng sau.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yaqi Zhang","avatar":""},{"name":"Zhu Hong","avatar":""},{"name":"Gong Xiaojun","avatar":""},{"name":"Zhong Lei","avatar":""},{"name":"Chai Yuanle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["绣春刀: 诛邪"]', 1784690324220);
