INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-nuong', 'Xuân Nương', 'Ghost of Spring', 'https://phimimg.com/upload/vod/20250116-1/329bc3c8cd18632886e845c66aa883fb.jpg', 'https://phimimg.com/upload/vod/20250116-1/4f3672447e90d14df551c4dc31854d7b.jpg', '<p>Cuộc đại lễ đúc liên quan đến vận mệnh quốc gia mỗi 12 năm mới gặp một lần sắp đến. Tuy nhiên, những người thợ đúc đỉnh liên tiếp chết một cách kỳ lạ. Một thiên tài điều tra vụ án mắc chứng sợ máu, luôn hành động khác thường và một nữ trợ lý có võ công tuyệt đỉnh nhưng trí óc đơn giản cùng khám phá một vụ án đã bị chôn vùi suốt bao năm về việc phụ nữ thời phong kiến bị áp bức . Đẹp không phải là tội, nhưng đối với những người phụ nữ bị áp bức, bị &quot;vật hóa&quot;, liệu có phải họ chỉ có thể cúi đầu trước số phận?</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cailun Huang","avatar":""},{"name":"Chuan Li","avatar":""},{"name":"Yu Zi Xuan","avatar":""},{"name":"Zhao Ying","avatar":""},{"name":"He Qiwei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Chun Niang","春娘"]', 1784690324220);
