INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dung-doc-chien', 'Cô Dũng Độc Chiến', 'Whispers of Betrayal: The Drug Underworld', 'https://phimimg.com/upload/vod/20250116-1/c3d0d64c8bab704c2b58890890f67926.jpg', 'https://phimimg.com/upload/vod/20250116-1/7caeaaecacd43452e21ab38c33fa358d.jpg', '<p>Vào những năm 30-40 của thế kỷ 20 tại Thượng Hải, các băng nhóm xã hội đen hoành hành, giao dịch ma túy diễn ra rầm rộ. Trùm ma túy Sâm Ca với thế lực hùng mạnh khiến cảnh sát khó thu thập được chứng cứ. Trong một lần giao dịch, A Nhân và A Mỹ bất ngờ tái ngộ, nhưng ẩn sau đó là âm mưu của ba thế lực: Quỷ Ca, Sâm Ca và cảnh sát. Giữa những hoài nghi và thử thách, A Nhân, với vai trò là cảnh sát ngầm, đã xâm nhập vào sào huyệt kẻ thù, thành công hỗ trợ cảnh sát bắt giữ Sâm Ca cùng các tay buôn ma túy quốc tế.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Hui","avatar":""},{"name":"William Wu","avatar":""},{"name":"Li Qia","avatar":""},{"name":"Deng Kaiyun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Lone Hero","孤勇毒战"]', 1784690324220);
