INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-phieu-luu-toi-vu-do', 'Đêm Phiêu Lưu Tới Vụ Đô', 'Land in the Hell', 'https://phimimg.com/upload/vod/20250116-1/88f8cb190344d73bfa5c5e10720824dc.jpg', 'https://phimimg.com/upload/vod/20250116-1/6107ae19c33b86c8e7ce1e16aa073551.jpg', '<p>Trần Tiểu Khôi là thanh niên công sở bị bóc lột, vì không có tiền nên thường xuyên chịu đả kích và đối xử lạnh nhạt, liên tục đối mặt với khủng hoảng trong cả tình yêu lẫn sự nghiệp. Đúng lúc này, quê anh bất ngờ có thông báo giải tỏa, sắp giàu lên chỉ sau một đêm, nhưng trong cơn say, Trần Tiểu Khôi đã đốt mất tờ giấy chứng nhận quyền sử dụng đất quan trọng nhất để nhận tiền đền bù, và đưa nó cho người cha quá cố của mình. Không còn cách nào khác, anh buộc phải xuống âm phủ để tìm lại cha và lấy lại giấy tờ nhà đất, từ đó bắt đầu một cuộc phiêu lưu kỳ lạ, đầy hiểm nguy nhưng cũng không kém phần hài hước.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Song Muzi","avatar":""},{"name":"Fan Ming","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Bai Yu","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Peng Bo","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Wu Du Qi Yu Ye","Land.In.The.Hell","雾都奇遇夜"]', 1784690324220);
