INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tinh-sai-trai', 'Cuộc Tình Sai Trái', 'Ali Topan', 'https://phimimg.com/upload/vod/20250126-1/ba16d79d894b07e4f3a4b18c83a0ac74.jpg', 'https://phimimg.com/upload/vod/20250126-1/209b7bf3fee0d1c8811f29899ce7d70e.jpg', '<p>Anh là một đứa trẻ lang thang trên đường phố, cô là con gái của một ông trùm. Khi họ quyết định cùng nhau bỏ trốn vì tình yêu thì mọi thứ bắt đầu vượt khỏi tầm kiểm soát.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Jefri Nichol","avatar":""},{"name":"Lutesha","avatar":""},{"name":"Reza Hilman","avatar":""},{"name":"Omara Esteghal","avatar":""},{"name":"Bebeto Leutualy","avatar":""},{"name":"Anya Zen","avatar":""},{"name":"Ari Sihasale","avatar":""},{"name":"Bizael Tanasale","avatar":""},{"name":"Dominique Sanda","avatar":""},{"name":"Widika Sidmore","avatar":""},{"name":"Axel Matthew Thomas","avatar":""},{"name":"Onadio Leonardo","avatar":""},{"name":"Dellu Uye","avatar":""},{"name":"Willem Bevers","avatar":""},{"name":"Rukman Rosadi","avatar":""},{"name":"Unique Priscilla","avatar":""},{"name":"Agnes Naomi","avatar":""},{"name":"Fa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Ali Topan"]', 1784690324220);
