INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hanh-trinh-co-doc-noi-di-gioi', 'Hành Trình Cô Độc Nơi Dị Giới', 'Loner Life in Another World', 'hành trình cô độc nơi dị giới loner life in another world shuichiro umeda haruka shiraishi rika abe kanon takao mari takahashi hina suguta mai kanno yuki nakashima yuka iwahashi haruna mikawa reo kurachi maria sashide asuka shioiri nozomi furuki haruna terada mami uchida arisa nakada kyouhei nat hitoribocchi no isekai kouryaku 独自一人的异世界攻略 孤单一人的异世界攻略 تنها در جهانی دیگر زندگی یک منزوی در دنیایی دیگر tutto solo alla conquista di un altro mondo - isekaibocchi (loner life in another world) hitoribotchi no isekai koryaku bocchi kouryaku hitoribotchi no isekai kōryaku حياة منعزلة في عالم آخر lonely attack on a different world loner life in another world ひとりぼっちの異世界攻略', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-nguyet-vo-bien', 'Phong Nguyệt Vô Biên', 'The Revenge Of Begonia', 'https://phimimg.com/upload/vod/20240607-1/b48d3d44bc7991120386bc91e380047f.jpg', 'https://phimimg.com/upload/vod/20240607-1/c2e4a0ed2def11ea953949f1ae277e48.jpg', '<p>Để trả thù cho anh trai, cô đào nổi tiếng Dương An Ngưng đã mạo hiểm kết hôn với &quot;ác quỷ&quot; Hạ Hành Châu - Nhị thiếu gia phủ Tư Lệnh. Dần dần, qua những cạm bẫy và mưu kế, hai người không chỉ tiến gần đến sự thật mà còn khám phá ra những cảm xúc đầy trắc trở trong lòng mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồng Tiêu","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324220);
