INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-dao-trieu-thien', 'Đại Đạo Triều Thiên', 'One Way Or Another', 'https://phimimg.com/upload/vod/20250125-1/7935ef30a9a30938458a8b6015cde750.jpg', 'https://phimimg.com/upload/vod/20250125-1/c5278509252e81febe378fe3a390ecdc.jpg', '<p>Trăm dặm giết một người, mười bước không muốn đi.

Ta chính là kiếm.

Trăm dặm giết một người, mười bước không muốn đi.

Trăm dặm giết một người, mười bước không thể đi.

Trăm dặm giết một người, mười bước? Không thể!

Trong ta có kiếm, trong kiếm có ta.

