INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rhapsody-mi-tuong-den-han-quoc', 'Rhapsody: Mì Tương Đen Hàn Quốc', 'Jjajangmyeon Rhapsody', 'https://phimimg.com/upload/vod/20250125-1/dca19437c73d2f3e044577f23d802e0a.jpg', 'https://phimimg.com/upload/vod/20250125-1/3540cd0c5bf08930e1f1327e46999c29.jpg', '<p>Loạt phim về món ngon này dõi theo quá trình phát triển hương vị của mì tương đen từ nguồn gốc Trung Quốc đến vị thế một trong những món giải khuây được yêu thích nhất ở Hàn Quốc.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Paik Jong-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["짜장면 랩소디"]', 1784690324220);
