INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rhapsody-ga-ran-han-quoc', 'Rhapsody: Gà Rán Hàn Quốc', 'Korean Fried Chicken Rhapsody', 'https://phimimg.com/upload/vod/20250125-1/c2e8120f686adffcd9167237e0d53a82.jpg', 'https://phimimg.com/upload/vod/20250125-1/a61b1c6c30c4a2e5b9fe532ff94d449b.jpg', '<p>Loạt phim tài liệu này khám phá cách các công thức nấu ăn truyền thống định hình bối cảnh ẩm thực hiện tại của Hàn Quốc, nêu bật sự kết hợp phổ biến giữa gà rán và bia.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Paik Jong-won","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["치킨 랩소디"]', 1784690324220);
