INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-hon-nhan', 'Cuộc Chiến Hôn Nhân', 'Battle Of Marriage', 'https://phimimg.com/upload/vod/20250101-1/14eff05fa45c35ed4fb7dc7967d01621.jpg', 'https://phimimg.com/upload/vod/20250101-1/12a2662c95ce40636831cac47a222b51.jpg', '<p>18 năm trước, Lâm Thái Lâm nhờ quay quảng cáo nước tinh khiết mà nổi tiếng, trở thành &quot;nữ thần quảng cáo&quot;. Sau đó, cô giải nghệ và kết hôn với Nghiêu, trở thành bà nội trợ 15 năm, cô cùng hai con qua Canada sinh sống. Trong khi đó, Đinh Trọng Nghiêu với hình tượng yêu vợ đã nhanh chóng nổi tiếng và tự thành lập công ty quảng cáo. Thái Lâm bất ngờ trở về, tạo ngạc nhiên cho chồng, nhưng Trọng Nghiêu có vẻ xa cách. Lâm quyết định tái xuất, tìm lại giá trị của bản thân. Lâm và nữ minh tinh đang nổi tiếng Thẩm Lạc Trừng cùng gia nhập công ty của Nghiêu. Họ tranh nhau vai nữ chính của nhãn nước tinh khiết năm xưa. Ngoài mặt, Nghiêu tỏ ra thương vợ, nhưng sau lưng, anh lại lén lút hẹn hò với Lạc Trừng trong 3 năm qua. Thái Lâm phải đối diện với cuộc hôn nhân này như thế nào?</p>', 'Tập 20', 20, 'series', 'ongoing', 13, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Tiêu Chính Nam","avatar":""},{"name":"Ngô Nhược Hy","avatar":""},{"name":"Chu Mẫn Hãn","avatar":""},{"name":"Lại Úy Linh","avatar":""},{"name":"Hà Viễn Đông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Battle of Marriage","奔跑吧！勇敢的女人們"]', 1784690324220);
