INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-co-hai-ba-noi', 'Nhà Có Hai Bà Nội', 'The House With Two Grandmothers', 'https://phimimg.com/upload/vod/20250124-1/0de119424b6e4c3dbe166273bd2aff82.jpg', 'https://phimimg.com/upload/vod/20250124-1/73ad9143c04bfe1c9cb23dfdd35c3f1e.jpg', '<p>Dù đã có tổ ấm mới, ông Điệp vẫn kiên quyết đưa người cũ và con gái về để bù đắp những thiếu sót ngày xưa. Nhưng khi gia đình cũ và gia đình mới sống chung dưới một mái nhà thì mâu thuẫn và tranh chấp là điều không thể nào tránh khỏi. Hàng loạt biến cố và hiểu lầm giữa các thành viên tạo nên những câu chuyện dở khóc dở cười cùng những nỗi đau thấu tâm can.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Đào Anh Tuấn","avatar":""},{"name":"Ngân Quỳnh","avatar":""},{"name":"Thanh Ngọc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Candid Eye"]', 1784690324220);
