INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhim-sonic-3', 'Nhím Sonic 3', 'Sonic The Hedgehog 3', 'https://phimimg.com/upload/vod/20250124-1/535166781a53d302e14c9341f0d161a2.jpg', 'https://phimimg.com/upload/vod/20250124-1/3f63def7ce3bc30c56063ca2c05a0cca.jpg', '<p>Sonic, Knuckles và Tails phải đối mặt với một kẻ thù mới cực kỳ mạnh mẽ là Shadow - một nhân vật phản diện bí ẩn với sức mạnh không giống bất kỳ đối thủ nào họ từng đối mặt trước đây. Bị áp đảo về năng lực, Sonic phải lên đường thành lập một liên minh to lớn hơn.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Ben Schwartz","avatar":""},{"name":"Keanu Reeves","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Colleen O''Shaughnessey","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Tika Sumpter","avatar":""},{"name":"Lee Majdoub","avatar":""},{"name":"Krysten Ritter","avatar":""},{"name":"Adam Pally","avatar":""},{"name":"Natasha Rothwell","avatar":""},{"name":"Shemar Moore","avatar":""},{"name":"Alyla Browne","avatar":""},{"name":"Tom Butler","avatar":""},{"name":"Jorma Taccone","avatar":""},{"name":"Sofia Pernas","avatar":""},{"name":"Cristo Fernández","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["ソニック・ザ・ヘッジホッグ3","Sonic 3: O Filme","Соник 3","Sonic x Shadow TOKYO MISSION","סוניק 3","音速小子3","Սոնիկ Ոզնին 3","Sonic 3","超音鼠大電影3","수퍼