INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-tinh', 'Đồng Tính', 'Queer', 'https://phimimg.com/upload/vod/20250124-1/85b7e831ea84daa836d4309007bfc0d3.jpg', 'https://phimimg.com/upload/vod/20250124-1/e4e53149d88c9c5e69b99555b937b205.jpg', '<p>Lấy bối cảnh những năm 1950 tại thành phố Mexico, QUEER là câu chuyện và hành trình đầy kỳ ảo của William Lee, một gã người Mỹ cuối tuổi tứ tuần, sống một cuộc đời lặp đi lặp lại từ quán bar này sang quán bar khác. Sự xuất hiện của chàng trai trẻ Eugene Allerton tựa như một làn gió mới. Anh chàng bí ẩn và khó nắm bắt tâm tư ấy đã khuấy động và làm thay đổi cách nhìn nhận thế giới, thúc đẩy mong muốn thiết lập một mối quan hệ có ý nghĩa với ai đó của Lee.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Daniel Craig","avatar":""},{"name":"Drew Starkey","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Lesley Manville","avatar":""},{"name":"Henry Zaga","avatar":""},{"name":"Drew Droege","avatar":""},{"name":"Andra Ursuta","avatar":""},{"name":"Lisandro Alonso","avatar":""},{"name":"Ariel Schulman","avatar":""},{"name":"David Lowery","avatar":""},{"name":"Daan de Wit","avatar":""},{"name":"Colin Bates","avatar":""},{"name":"Simon Rizzoni","avatar":""},{"name":"Octavio Mendoza","avatar":""},{"name":"Omar Apollo","avatar":""},{"name":"Silverio Castro","avatar":""},{"name":"Amir Antonio Sama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Queer: Desejo Mórbido","William S. Burroughs'' Queer","Queer"]', 1784690324220);
