INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-749', 'Cục 749', 'Bureau 749', 'https://phimimg.com/upload/vod/20250124-1/50e7058b261cca84b6898be5f422373c.jpg', 'https://phimimg.com/upload/vod/20250124-1/b0d7343e96fbb0620e07660e234a2261.jpg', '<p>Một chàng trai trẻ bị tổn thương với những bất thường về thể chất buộc phải gia nhập một văn phòng bí ẩn để đối mặt với thảm họa lan rộng khắp trái đất do một sinh vật vô danh gây ra. Anh dấn thân vào một cuộc phiêu lưu khám phá những bí ẩn về cuộc đời mình.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Karry Wang","avatar":""},{"name":"Miao Miao","avatar":""},{"name":"Ryan Zheng Kai","avatar":""},{"name":"Ren Min","avatar":""},{"name":"Xin Baiqing","avatar":""},{"name":"Jerry Lee","avatar":""},{"name":"Janine Chang Chun-Ning","avatar":""},{"name":"Yang Haoyu","avatar":""},{"name":"Yu Kailei","avatar":""},{"name":"Li Meng","avatar":""},{"name":"Li Junmo","avatar":""},{"name":"Jin Shijia","avatar":""},{"name":"Dong Shaohui","avatar":""},{"name":"Firdaus","avatar":""},{"name":"Guo Daixin","avatar":""},{"name":"Li Guangjie","avatar":""},{"name":"Zhou Yiwei","avatar":""},{"name":"Cao Weiyu","avatar":""},{"name":"Li Qinqin","avatar":""},{"name":"Liu Lu","avatar":""},{"name":"Kun Liu","avatar":""},{"name":"Xing Y","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["749：异族崛起","两万里计划","Cục 749","Bureau 749","oficina 749","Departamento 749","El ascenso de las razas alienígenas 74