INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-cam-nguoi-me', 'Linh Cảm Người Mẹ', 'Mothers'' Instinct', 'https://phimimg.com/upload/vod/20250124-1/1e8b3cdecd0db2d96cbf5142c0f13f6f.jpg', 'https://phimimg.com/upload/vod/20250124-1/c56cda9c51772eb1ac3012ee4a8cfa40.jpg', '<p>Câu chuyện xoay quanh hai người mẹ, Alice và Céline, sống trong một khu phố ngoại ô Mỹ những năm 1960. Một tai nạn đau lòng khiến một đứa trẻ chết, dẫn đến những cảm giác trách nhiệm, nghi ngờ và lo âu làm suy yếu mối quan hệ giữa hai người mẹ.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Anders Danielsen Lie","avatar":""},{"name":"Josh Charles","avatar":""},{"name":"Caroline Lagerfelt","avatar":""},{"name":"Alexander Blaise","avatar":""},{"name":"Steve Routman","avatar":""},{"name":"Joel Nagle","avatar":""},{"name":"Larry Petersen","avatar":""},{"name":"Eamon Patrick O''Connell","avatar":""},{"name":"Keeley Miller","avatar":""},{"name":"Baylen D. Bielitz","avatar":""},{"name":"Lauren Yaffe","avatar":""},{"name":"Scott Robertson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["마더스 인스팅트","母亲的直觉","Dupla Obsessão","سرشت مادران","Instinto maternal","Mothers'' Instinct"]', 1784690324220);
