INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-gia-hoi-xuan', 'Ngoại Già Hồi Xuân', 'Who Is She', 'https://phimimg.com/upload/vod/20241218-1/39388c89ebf12feb7a0c242a81c22d78.jpg', 'https://phimimg.com/upload/vod/20241218-1/c77bcae5704ce6d07ed23e055d488d4d.jpg', '<p>Ngoại Già Hồi Xuân - Who Is She kể về hành trình theo đuổi giấc mơ dở dang thời thanh xuân của một người phụ nữ ở độ tuổi 70. Mất chồng từ khi còn trẻ, bà Mal Sun một mình nuôi dạy con cái và làm chủ một nhà hàng nhỏ. Một ngày nọ, bà vô tình lấy lại được cơ thể 20 tuổi và dùng cơ hội trời cho này để thực hiện mơ ước ngày xưa: trở thành ca sĩ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hae-sook","avatar":""},{"name":"Jung Ji-so","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Chae Won-been","avatar":""},{"name":"Sowon","avatar":""},{"name":"Lee Hwa-Kyum","avatar":""},{"name":"Lee Kwang-hee","avatar":""},{"name":"Yoo Jung-hoo","avatar":""},{"name":"Jung Bo-seog","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["奇怪的她剧版","او کیست؟","من هي؟","Miss Granny","수상한 그녀"]', 1784690324220);
