INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-ve-em', 'Hướng Về Em', 'All Of Her', 'https://phimimg.com/upload/vod/20250122-1/d90d87bdb0e7d3c539ad61f935ee026e.jpg', 'https://phimimg.com/upload/vod/20250122-1/8925c23d8a36b758ec9832264ff23c63.jpg', '<p>Ngôn Trinh được gả vào Tập đoàn An Thủy và trở thành bà chủ nhỏ, nhưng chưa đầy một năm thì đã góa chồng. Chồng cô gặp sự cố, biến mất không rõ tung tích vào ngày kỷ niệm cưới của hai người. Bốn năm sau, Ngôn Trinh trở thành một trợ lý quyết đoán và lạnh lùng cho tổng giám đốc tập đoàn. Khi chuẩn bị tuyên bố về cái chết của chồng, thì bất ngờ gặp lại “người chồng trở về”. Người đàn ông trước mắt có ngoại hình giống hệt chồng cô, nhưng tính cách thì hoàn toàn khác, tự xưng là em chồng. Người đàn ông này luôn đối đầu với Ngôn Trinh, cho rằng cô là người đứng sau thao túng sự cố năm xưa, còn Ngôn Trinh dường như cũng đang che giấu một bí mật nào đó.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xia Meng","avatar":""},{"name":"Li Zhuoyang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Wu Yu Lun Bi De Ta","All of Her","向她逆光而来"]', 1784690324220);
