INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gioi-sieu-giau-o-han-quoc-', 'Giới Siêu Giàu Ở Hàn Quốc', 'Super Rich In Korea', 'https://phimimg.com/upload/vod/20250122-1/3156fe078047f3aa98e8a09578070ece.jpg', 'https://phimimg.com/upload/vod/20250122-1/4fb9beca1b84305364a044e3559b5290.jpg', '<p>Phim&nbsp;<span style="background-color: rgb(255, 255, 255); color: rgb(34, 34, 34); font-family: Roboto; font-size: 17.6px; letter-spacing: -0.2px;">có sự góp mặt của những nhân vật nổi bật như: Tỉ phú người Singapore David Yong, đại sứ thương hiệu xa xỉ độc quyền của Hàn Quốc Yoo Hee Ra (được biết đến với cái tên Paris Hilton của Hàn Quốc), thành viên hoàng gia Pakistan Anna và Noor Naim - người có 50 triệu người theo dõi trên mạng xã hội và thường được gọi là &quot;Kim Kardashian người Ả Rập&quot;...&nbsp;</span><span style="background-color: rgb(255, 255, 255); color: rgb(34, 34, 34); font-family: Roboto; font-size: 17.6px; letter-spacing: -0.2px;">Ngoài ra, chương trình còn mang đến cái nhìn thoáng qua về cuộc sống bí mật và hào nhoáng của họ, giới thiệu những cảnh như: CEO của thương hiệu xa xỉ hòa nhập với những người nổi tiếng toàn cầu trong bữa tiệc sinh nhật, xuất hiện tại Tuần lễ thời trang Paris và siêu xe cao cấp lấp đầy bãi đậu xe.</span></p><p><br/></p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jo Se-ho","avatar":""},{"name":"BamBam","avatar":""},{"name":"Mimi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["超级富豪异乡人","超富异邦人","슈퍼리치 이방인"]', 1784690324220);
