INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-nguy-hiem-2-sat-nhan-trai-dao', 'Cô Nàng Nguy Hiểm 2: Sát Nhân Trái Đào', 'Wild Agent 2: Peach Assassination', 'https://phimimg.com/upload/vod/20250116-1/d910cc36d46c4596eda92a7ad8181f5c.jpg', 'https://phimimg.com/upload/vod/20250116-1/c851c6540a5987a00bd4615fbfae7243.jpg', '<p>Để đạt được mục đích xâm nhập vào hệ thống tài chính toàn cầu, tổ chức tội phạm TNT đã bắt cóc chuyên gia AI Phương Lực. Vợ anh, Nhã Mỹ, một cựu đặc vụ của tổ chức ATO đã lui về ở ẩn buộc phải quay lại tổ chức để giải cứu chồng mình. Thủ lĩnh của tổ chức là Saul đã ra lệnh cho sát thủ máu lạnh Mật Đào truy sát Nhã Mỹ nhằm ngăn cản cuộc giải cứu. Nhã Mỹ vượt qua nhiều trở ngại, cuối cùng cứu được chồng và bắt giữ sát thủ Mật Đào giao cho pháp luật xử lý.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Sheng Nan","avatar":""},{"name":"Luo Liqun","avatar":""},{"name":"Henry Prince Mak","avatar":""},{"name":"Zhong Lei","avatar":""},{"name":"Wei Lu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["特工狂花2：蜜桃殺機","Miss Agent 2","Wild Agent II: Peach Assassination","ยอดจารชนสาว 2 : นักฆ่าลูกพีช","Cô Nàng Nguy Hiểm 2: Sát Nhân Trái Đào","특공광화2 : 밀도살기","特工狂花Ⅱ：蜜桃杀机","特工狂花2：蜜桃杀机"]', 1784690324220);
