INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-thu-dao-cam-lang', 'Dị Thú Đảo Câm Lặng', 'The Strange Beast of Silent Island', 'https://phimimg.com/upload/vod/20250116-1/698a0d6b039c572f0b1a72959c2f54fc.jpg', 'https://phimimg.com/upload/vod/20250116-1/35e540b8c1b227da7f4b0ca1b89f8fde.jpg', '<p>Vợ chồng Diệp Bác Minh và Y Lâm làm nghề nuôi trồng thủy sản trên một hòn đảo hẻo lánh. Người em họ Y Na đến thăm và tình cờ phát hiện một hầm mỏ bị bỏ hoang, vô tình giải phóng những sinh vật bí ẩn. Những sinh vật này săn mồi dựa vào âm thanh, để sinh tồn mọi người buộc phải giữ im lặng tuyệt đối. Tuy nhiên, dù lặng lẽ đến đâu, những sinh vật bí ẩn vẫn luôn theo sát, khiến thế giới tĩnh lặng trở nên ngột ngạt và ẩn chứa những hiểm họa chết người khó lường...</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Haocheng","avatar":""},{"name":"Dong Luman","avatar":""},{"name":"Huang Youtian","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Silent Island: Strange Beasts","Ji Jing Dao Zhi Yi Shou","The Strange Beast of Silent Island","寂靜島之異獸","เกาะสงบพบสัตว์ประหลาด","Dị Thú Đảo Câm Lặng","静寂の島の異獣","적정도지이수 : 조용한 섬의 몬스터","寂静岛之异兽"]', 1784690324220);
