INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-bat-hanh', 'Trái Tim Bất Hạnh', 'Unhappy Heart', 'https://phimimg.com/upload/vod/20241221-1/d6376387139e107b7ebeeb51cee8bf2d.jpg', 'https://phimimg.com/upload/vod/20241221-1/37ea177d984d00cb42edd0f8b07f26de.jpg', '<p>Bộ phim Trái tim bất hạnh khai thác đề tài nóng hổi là vấn nạn bạo hành trẻ em và bạo lực học đường, hai đề tài vốn đang là tâm điểm mà xã hội quan tâm. Phim dựa trên một câu chuyện có thật về vụ án bạo lực trẻ em xảy ra cách đây ba năm tại Tp.HCM, khi mẹ ruột mất quyền nuôi con và người con bị mẹ kế b.ạo hà.nh d.ữ d.ội, gây rất nhiều bứ.c x.úc trong xã hội lúc bấy giờ. “Trái tim bất hạnh” chứa đựng biết bao nhiêu nỗi niềm của những trái tim bị tổ.n th.ương, đó là những đứa trẻ thiếu thốn tình thương của mẹ, đó là sự đau đớn khi bị bắt nạt, là những con tim khốn khổ sau thất bại hôn nhân….</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Oanh Kiều","avatar":""},{"name":"Khôi Trần","avatar":""},{"name":"Lê Hạ Anh","avatar":""},{"name":"Thân Thúy Hà","avatar":""},{"name":"Trung Dũng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["What About Brian"]', 1784690324220);
