INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bao-hoa-hong', 'Cơn Bão Hoa Hồng', 'The Storm Of Roses', 'https://phimimg.com/upload/vod/20250103-1/bfbb663a1ddca04fa2815c087cae5e78.jpg', 'https://phimimg.com/upload/vod/20250103-1/eaa388265bb2855849278e437dff7c34.jpg', '<p>Năm 2015 khi nền kinh tế internet bùng nổ và thị trường vốn đầy rẫy biến động, Tổng biên tập tạp chí tài chính Tạ Lâm Huệ năm 40 tuổi đã công bố vụ bê bối liên quan đến việc ngoại tình và các hoạt động kinh doanh bất hợp pháp của cổ đông tại quỹ đầu tư nào đó. Bài báo thẳng thắn này đã gây chấn động giới đầu tư và dẫn đến một cuộc tái cơ cấu trong ngành, trực tiếp đẩy một giám đốc đầu tư như Giang Nhất Địch vào khủng hoảng nghề nghiệp. Tuy nhiên, hành động theo dõi sát sao những hành vi sai trái trong ngành của Tạ Lâm Huệ đã khiến cô bị nhiều bên hãm hại, cuối cùng bị đình chỉ công tác do đăng một bài báo có dữ liệu sai lệch, và người cung cấp thông tin chính là Giang Nhất Địch. Thị trường biến động không ngừng, chẳng màng đến sự thăng trầm của con người, và công ty y tế thông minh do Giang Nhất Địch phụ trách cũng lâm vào bế tắc, kéo cả Tạ Lâm Huệ và Giang Nhất Địch vào một cơn bão lớn hơn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tan Zhuo","avatar":""},{"name":"Liu Yijun","avatar":""},{"name":"Gao Ye","avatar":""},{"name":"Lin Shen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["橙色光芒","Ray of Sunshine","蔷薇风暴"]', 1784690324220);
