INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-quyen-ru-cua-25d', 'Sự quyến rũ của 2.5D', '2.5 Dimensional Seduction', 'https://phimimg.com/upload/vod/20240713-1/c674ecff1636bc7db322896bc9c5414c.jpg', 'https://phimimg.com/upload/vod/20240713-1/6c7557779fba2e7ac72e1b4223597e07.jpg', '<p>Tôi không có hứng thú với các cô gái 3D! Hôm nay, Giám đốc Phòng Nghiên cứu Manga, Okumura, ở một mình trong phòng câu lạc bộ, hét to tên nhân vật hai chiều yêu quý của mình, Liliel, người được phản chiếu ở phía bên kia màn hình... Người đến Okumura là Ririsa Amano là một cô gái 3D nói, ``Tôi muốn trở thành Liliel.&#39;&#39; Cô yêu thích những &quot;bộ trang phục&quot; nghịch ngợm, dễ thương của các cô gái xuất hiện trong manga. Và anh ấy là một otaku yêu Liliel nhiều như Okumura!</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"榎木淳弥","avatar":""},{"name":"前田佳織里","avatar":""},{"name":"鬼頭明里","avatar":""},{"name":"鈴代紗弓","avatar":""},{"name":"渡部紗弓","avatar":""},{"name":"山根綺","avatar":""},{"name":"市道真央","avatar":""},{"name":"貫井柚佳","avatar":""},{"name":"杉田智和","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324220);
