INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-an-co-bi-mang-tieng-ac-phan-2', 'Rồng Ăn Cỏ Bị Mang Tiếng Ác (Phần 2)', 'A Herbivorous Dragon Of 5000 Years Gets Unfairly Villainized (Season 2)', 'https://phimimg.com/upload/vod/20241030-1/831bb81ddfbb21fe53ec8735817133ad.jpg', 'https://phimimg.com/upload/vod/20241030-1/2e9a1cac4a9ce5494ea675456b68f9ae.jpg', '<p>Chú rồng ăn cỏ chỉ muốn sống cuộc sống bình an không tranh giành gặp phải Reiko một nữ sinh cấp hai. Thế là bất luận nó nói hay nói ngọt khuyên giải thế nào đều không thể khuyên nổi Reiko một lòng muốn chết, không còn cách nào nó chỉ đành bịa ra lời nói dối để giúp Reiko sống tiếp. Dưới lời nói dối của ” ác long” Reiko bắt tay vào hành trình đánh bại quân của Ma vương cùng với thứ mà cô tin là con “ác long” mạnh nhất.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xing Kaixin","avatar":""},{"name":"Lan Jiu","avatar":""},{"name":"Wei Ruchen","avatar":""},{"name":"Meme Yan","avatar":""},{"name":"Shan Xin","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Shi Cao Lao Long Bei Guan Yi E Long Zhi Ming","吾乃食草龙","Shi Cao Lao Long Bei Guanyi E Long Zhi Ming","食草老龙被冠以恶龙之名（日配版）","Un dragón herbívoro de 5000 años es injustamente villanizado","Yowai 5000-nen no Soushoku Dragon, Iwarenaki Jaryuu Nintei","齢5000年の草食ドラゴン、いわれなき邪竜認定","Безобидный пятитысячелетний дракон","It Was Recognized as an Evil Dragon Without Any Cause.","A Gentle Dragon of 5000 Years Old","Rồng Ăn Cỏ Bị Mang Tiếng Ác","食草老龙被冠以恶龙之名"]', 1784690324220);
