INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-cam-do-chet-nguoi', 'Sự Cám Dỗ Chết Người', 'The Dangerous Affair', 'https://phimimg.com/upload/vod/20250108-1/e5fb8302dcb3ffa4da68af752eef97f1.jpg', 'https://phimimg.com/upload/vod/20250108-1/a84606a21240910c19ad7f560bd3d5c2.jpg', '<p>Khi Alex bắt đầu cảm thấy nhàm chán với cuộc sống với vợ mình là Lara và cố gắng tìm một lối thoát đẹp đẽ, anh gặp Nadine, người cũng đang mắc kẹt trong mối quan hệ phức tạp với chồng cô, Erwin. Dám đùa với lửa nhưng liệu bạn cũng có dám mạo hiểm?</p>', 'Tập 9', 10, 'series', 'ongoing', 16, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Luna Maya","avatar":""},{"name":"Darius Sinathrya","avatar":""},{"name":"Marcelino Lefrandt","avatar":""},{"name":"Rana Audi Marissa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Main Api"]', 1784690324220);
