INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-day', 'Thúc Đẩy', 'Impulse', 'https://phimimg.com/upload/vod/20250118-1/792c3127b7de562c4cc16f5e838e0a63.jpg', 'https://phimimg.com/upload/vod/20250118-1/6b729ad040ad6246916d849ee41234ec.jpg', '<p>Một nhà báo trẻ kết nối một vài cái chết nổi tiếng dường như bị cô lập và bị kéo vào quỹ đạo của một nhóm toàn cầu bao gồm các ông trùm truyền thông, chính trị gia và giới thượng lưu Hollywood…</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dajana Gudic","avatar":""},{"name":"Nick Cassavetes","avatar":""},{"name":"Paul Johansson","avatar":""},{"name":"Lou Ferrigno Jr.","avatar":""},{"name":"Miraj Grbić","avatar":""},{"name":"Rob Kirkland","avatar":""},{"name":"Jami Alix","avatar":""},{"name":"Johanna Liauw","avatar":""},{"name":"Jonathan Kowalsky","avatar":""},{"name":"Mark Hapka","avatar":""},{"name":"Jessica Blythe Kemejuk","avatar":""},{"name":"Denny Love","avatar":""},{"name":"Jerry Rector","avatar":""},{"name":"Will Hirschfeld","avatar":""},{"name":"Mae Aswell","avatar":""},{"name":"Christian Combs","avatar":""},{"name":"Peter Zizz","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Impulso","Impulse"]', 1784690324220);
