INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuc-day', 'Thúc Đẩy', 'Impulse', 'thúc đẩy impulse dajana gudic nick cassavetes paul johansson lou ferrigno jr. miraj grbić rob kirkland jami alix johanna liauw jonathan kowalsky mark hapka jessica blythe kemejuk denny love jerry rector will hirschfeld mae aswell christian combs peter zizz impulso impulse', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-sat-nhan-nua-dem', 'Kẻ Sát Nhân Nửa Đêm', '12 To Midnight', 'https://phimimg.com/upload/vod/20250118-1/247cefb791a80aae99dfae306a0df5f8.jpg', 'https://phimimg.com/upload/vod/20250118-1/68606ef2b1c761ac3c0997eb2f494d2f.jpg', '<p>Nội dung xoay quanh một thám tử, người rơi vào bế tắc sau cái chết bi thảm của vợ mình. Sự kiện này không chỉ để lại vết thương sâu sắc trong tâm hồn anh, mà còn khiến anh buộc phải từ chức khỏi lực lượng cảnh sát.Tuy nhiên, khi một kẻ sát nhân hàng loạt xuất hiện và dường như cố ý thách thức anh, anh buộc phải quay trở lại điều tra. Trong quá trình truy lùng, anh phát hiện kẻ giết người không chỉ là một con người bình thường mà còn sở hữu sức mạnh siêu nhiên. Điều này đẩy cuộc truy tìm vào một mê cung đầy bí ẩn và nguy hiểm, nơi anh phải đối mặt với những bóng ma từ quá khứ và tìm cách vượt qua nỗi đau cá nhân để ngăn chặn tên sát nhân trước khi hắn tàn sát thêm nhiều người vô tội.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Bronzi","avatar":""},{"name":"Tito Ortiz","avatar":""},{"name":"Daniel Roebuck","avatar":""},{"name":"Helene Udy","avatar":""},{"name":"Sadie Katz","avatar":""},{"name":"Eric Francis Melaragni","avatar":""},{"name":"Searra Sawka","avatar":""},{"name":"Valerie Bittner","avatar":""},{"name":"Lukas Stoiber","avatar":""},{"name":"Patrick Voss Davis","avatar":""},{"name":"Sarah Cugini","avatar":""},{"name":"Destiny Leilani Brown","avatar":""},{"name":"Tristan Ott","avatar":""},{"name":"Tom Parnell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["12 to Midnight"]', 1784690324220);
