INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-sat-nhan-nua-dem', 'Kẻ Sát Nhân Nửa Đêm', '12 To Midnight', 'kẻ sát nhân nửa đêm 12 to midnight robert bronzi tito ortiz daniel roebuck helene udy sadie katz eric francis melaragni searra sawka valerie bittner lukas stoiber patrick voss davis sarah cugini destiny leilani brown tristan ott tom parnell 12 to midnight', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kraven-tho-san-thu-linh', 'Kraven: Thợ Săn Thủ Lĩnh', 'Kraven The Hunter', 'https://phimimg.com/upload/vod/20241217-1/2d211735637df6cc8b2504fcf0f7a85d.jpg', 'https://phimimg.com/upload/vod/20241217-1/dfd1bcd57c31ca4cee062a3030d7e2a3.jpg', '<p>Sergei Kravinoff (Aaron Taylor-Johnson thủ vai) cùng bố của anh đi săn ở Châu Phi. Bố của Sergei Kravinoff là một tay săn lão luyện. Khi Sergei bị một con sư tử tấn công, bố của anh cho rằng anh chỉ là một kẻ yếu đuối. Mặc dù bị sư tử cắn và bị chính bố mình bỏ mặc, nhưng Sergei đã không chết mà thay vào đó, vết cắn lại cho Sergei một sức mạnh phi thường. Cũng từ đây, gã nhập cư Sergei Kravinoff đang thực hiện nhiệm vụ chứng minh rằng anh ta là thợ săn vĩ đại nhất thế giới.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Ariana DeBose","avatar":""},{"name":"Fred Hechinger","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Christopher Abbott","avatar":""},{"name":"Levi Miller","avatar":""},{"name":"Billy Barratt","avatar":""},{"name":"Diaana Babnicova","avatar":""},{"name":"Dritan Kastrati","avatar":""},{"name":"Yuri Kolokolnikov","avatar":""},{"name":"Guillaume Delaunay","avatar":""},{"name":"Murat Seven","avatar":""},{"name":"Anita-Joy Uwajeh","avatar":""},{"name":"Tom Reed","avatar":""},{"name":"Greg","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["كرايفن ذي هانتر","קרייבן הצייד","Kraven ovçu","Kraven el Cazador","Kraven, o Caça