INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-thoi-doi-van', 'Thay Thời Đổi Vận', 'Good Luck', 'https://phimimg.com/upload/vod/20250102-1/ffd8dafca99e7dc4926aade1bb3c8f42.jpg', 'https://phimimg.com/upload/vod/20250102-1/08763926d6bae52f11cc5e68a855cdd1.jpg', '<p style="box-sizing: border-box; margin-top: 0px; margin-bottom: 0px; padding: 0px;">Một nhân vật nhỏ bé tầm thường, một cơ duyên lạ kỳ với đá, ba cuộc gặp gỡ với phong cách khác nhau, vận may bất ngờ ập đến rồi lại gặp phải một cú sốc lớn. Tại vùng đất bí ẩn Cô Miệt cũng có một cuộc gặp gỡ kỳ diệu đang chờ đợi Thạch Lai. Cậu nhóc nghèo sẽ làm gì để lật ngược tình thế, bước lên đỉnh cao cuộc đời?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jing Yanjun","avatar":""},{"name":"Gao Tianni","avatar":""},{"name":"Meng Lu","avatar":""},{"name":"Zheng Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shi Lai Yun Zhuan","石来运转"]', 1784690324220);
