INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-tham-tan-tien-sinh-mi-tuong', 'Chân Thám Tần Tiên Sinh: Mị Tướng', 'Detective Qin 2', 'https://phimimg.com/upload/vod/20250103-1/c5cac3327656483cd32412c162ecb27e.jpg', 'https://phimimg.com/upload/vod/20250103-1/eb209c72fe1b81491d065e070d11ac7d.jpg', '<p>Trong những năm đầu của Trung Hoa Dân Quốc, Tần Dương Tần tiên sinh, một người đàn ông có năng lực và kỳ lạ, đã cùng hợp tác với Thẩm Nhu, thiên kim du học về và Viên Tinh Tinh, một cô gái lập dị, và gặp thám tử cảnh sát Hà Hồng Phong. Với sự giúp đỡ của anh dần phá được vụ án kỳ lạ phức tạp và khó hiểu trong thành phố, vạch trần âm mưu của thế lực tà ác Dạ Thần hội, và cuối cùng bảo vệ được hòa bình một phương.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qin Yangming","avatar":""},{"name":"Rao Jiadi","avatar":""},{"name":"Xie Wendi","avatar":""},{"name":"Wang Yipu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["真探秦先生第二季之魅相","真探秦先生","True Detective Mr. Qin 2","Detective Qin II"]', 1784690324220);
