INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-bao', 'Kẻ Săn Bão', 'Bolt From The Blue', 'https://phimimg.com/upload/vod/20250112-1/f4d1d34c9f2d935ee0b37f2fecf55735.jpg', 'https://phimimg.com/upload/vod/20250112-1/a8e7746f18b48bb8460d1cc7138b1bd9.jpg', '<p>Một cô kỹ sư bị xem thường đã được cử đến Alaska để đánh giá nhận định của một nhà khoa học lập dị rằng việc &quot;bắt giữ&quot; sét có thể trở thành một nguồn năng lượng tái tạo mới. Cuộc gặp gỡ oái oăm này lại là hành trình đáng nhớ với nhiều điều không tưởng.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Kevin Michael Martin","avatar":""},{"name":"Page Tudyk Gomez","avatar":""},{"name":"Manny Spero","avatar":""},{"name":"Kate Flannery","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Elle Young","avatar":""},{"name":"Kevin Changaris","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Storm Chasers","Bolt from the Blue"]', 1784690324220);
