INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-gunnar-snsteby', 'Anh Hùng Gunnar Sønsteby', 'Number 24', 'https://phimimg.com/upload/vod/20250112-1/2594bc017fa0cade0a86a10f182efa9d.jpg', 'https://phimimg.com/upload/vod/20250112-1/ff4d12fd42d33fd1660d447b7d21c1dc.jpg', '<p>Gunnar Sønsteby, một thanh niên xuất thân từ Rjukan, quyết định tham gia cuộc kháng chiến chống lại Đức Quốc xã ngay từ ngày đầu tiên quân Đức xâm lược Na Uy. Dù còn trẻ, anh trở thành thủ lĩnh của nhóm &quot;Oslo-gang&quot;, thực hiện nhiều chiến dịch phá hoại táo bạo, đe dọa nghiêm trọng các kế hoạch chiến tranh của kẻ thù. Những hành động dũng cảm của Sønsteby đã giúp anh trở thành biểu tượng của sự kiên cường và là anh hùng vĩ đại nhất trong lịch sử chiến tranh Na Uy.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Na Uy', 1, '[{"name":"Sjur Vatne Brean","avatar":""},{"name":"Erik Hivju","avatar":""},{"name":"Lisa Loven Kongsli","avatar":""},{"name":"August Wittgenstein","avatar":""},{"name":"Ines Høysæter Asserson","avatar":""},{"name":"Lars Berge","avatar":""},{"name":"Espen Lervaag","avatar":""},{"name":"Per Kjerstad","avatar":""},{"name":"Mark Noble","avatar":""},{"name":"Magnus Dugdale","avatar":""},{"name":"Morten Rudå","avatar":""},{"name":"Cato Skimten Storengen","avatar":""},{"name":"Kristian Halken","avatar":""},{"name":"Benjamin Myhre","avatar":""},{"name":"Michael Shelford","avatar":""},{"name":"Ter","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["编号24","N.º 24","Número 24","Numéro 24","Numero 24","Broj 24","24-es","No. 24","Но