INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-toc-do-phan-1', 'Những Người Bạn Tốc Độ (Phần 1)', 'Fast Friends (Season 1)', 'https://phimimg.com/upload/vod/20241224-1/2706fdc5c938accf2f84d5a57b3bd192.jpg', 'https://phimimg.com/upload/vod/20241224-1/98e08be8fef83f68f3087c00a15275a6.jpg', '<p>Chương trình là cuộc thi tài giữa những người hâm mộ trung thành nhất của loạt phim truyền hình nổi tiếng Những Người Bạn, trong đó họ sẽ thể hiện hiểu biết của mình về mọi tình tiết trong phim để giành lấy giải thưởng cao nhất, chiếc Cúp Geller.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Whitney Cummings","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fast Friends"]', 1784690324220);
