INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-trong-rung-mua', 'Chuyện Tình Trong Rừng Mưa', 'Rainforest Passions', 'https://phimimg.com/upload/vod/20241231-1/24e539d2d6ed9b44c22c96d26d86cf03.jpg', 'https://phimimg.com/upload/vod/20241231-1/88787d54f2cc5213f51f780ef45c4b21.jpg', '<p>Tiểu thư giả Tô Hạ Mạch vì tìm đệ đệ mà đến Mang Bắc, nhưng lại bị truy sát. Trong khi đó, Thích Xuyên, người đang điều tra nguyên nhân cái chết của ca ca mình, phát hiện Hạ Mạch có liên quan đến vụ việc nên đã cứu cô. Hai người &quot;vô tình&quot; thành thân dưới sự chứng kiến của trưởng lão nơi đó. Từ đây, họ bắt đầu hành trình dây dưa đầy thú vị, cưới trước yêu sau, và con đường chinh phục trái tim qua những màn truy đuổi lẫn nhau.</p>', 'Tập 30', 30, 'series', 'ongoing', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đại Cao Chính","avatar":""},{"name":"Trịnh Diệu","avatar":""},{"name":"Viên Đại Sâm","avatar":""},{"name":"Trương Duyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["野火烧","Burning","雨林爱发生"]', 1784690324220);
