INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-tranh-dong-muu-co-toi', 'Cạnh Tranh: Đồng Mưu Có Tội', 'Compete: Cartel Hunters', 'https://phimimg.com/upload/vod/20250110-1/5f7d81fb28f60a6dcca643187a16f018.jpg', 'https://phimimg.com/upload/vod/20250110-1/882ef7f1bb0fcc2e997618121e474d73.jpg', '<p>Dựa trên các vụ án có thật, phim “Cạnh Tranh – Đồng Mưu Có Tội” chỉ ra những hành vi có thể cấu thành tội trong hoạt động thương mại như gian lận đấu thầu, phân chia thị trường, thông đồng định giá,... Bốn nhân viên tổ điều tra của Ủy ban Cạnh tranh (Competition Commission) là Lâm Thụ Sinh, Dương Mi, Tống Trọng Cơ và Sầm Gia Bảo hàng ngày phải đối mặt với nhiều vụ án như thế. Bên cạnh áp lực công việc, phim cũng đan xen câu chuyện về tình đồng nghiệp, tình yêu giữa họ.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'ongoing', 9, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lục Tuấn Quang","avatar":""},{"name":"Huỳnh Định Khiêm","avatar":""},{"name":"Dư Hương Ngưng","avatar":""},{"name":"Lâm Thiên Đình","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["競爭之合謀有罪"]', 1784690324220);
