INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-no-ve-dem', 'Hoa Nở Về Đêm', 'Knight Flower', 'https://phimimg.com/upload/vod/20240123-1/670f482a3b73f013e4b08e9f972adf56.jpg', 'https://phimimg.com/upload/vod/20240123-1/b90a6a09b5e1adb3c00296ff82bc8584.jpg', '<p>Hoa Nở Về Đêm - Knight Flower kể về Cho Yeo Hwa, người phụ nữa đã góa chồng 15 năm. Cô là phu nhân trong một gia đình quý tộc danh giá nhất vùng. Ban ngày, cô sống rất lặng lẽ và không bao giờ tiếp xúc với bên ngoài. Cô thể hiện mình là một phu nhân rất chỉnh chu và có gia phép. Tuy nhiên, trong đêm, Cho Yeo Hwa đã lẻn ra ngoài và giúp đỡ những người có hoàn cảnh khó khăn. Trong thời gian này, cô đã vô tình gặp Soo Ho, một cảnh vệ trong thành, có ngoại hình ưa nhìn và rất ưu tú. Soo Ho luôn xuất hiện để giúp đỡ Yeo Hwa mỗi khi cô gặp khó khăn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Ha-nee","avatar":""},{"name":"Lee Jong-won","avatar":""},{"name":"Kim Sang-joong","avatar":""},{"name":"Lee Ki-woo","avatar":""},{"name":"Park Se-hyun","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Seo Yi-sook","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Heo Jeong-do","avatar":""},{"name":"Yoon Sa-bong","avatar":""},{"name":"Jung Yong-ju","avatar":""},{"name":"Kim Hyeong-mook","avatar":""},{"name":"Woo Kang-min","avatar":""},{"name":"Lee Woo-je","avatar":""},{"name":"Lee Ruby","avatar":""},{"name":"Nam Mi-jung","avatar":""},{"name":"Jeong So-ri","avatar":""},{"name":"Jeong Ye-na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324220);
