INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-no-ve-dem', 'Hoa Nở Về Đêm', 'Knight Flower', 'hoa nở về đêm knight flower lee ha-nee lee jong-won kim sang-joong lee ki-woo park se-hyun kim mi-kyeong seo yi-sook jo jae-yun kim kwang-kyu heo jeong-do yoon sa-bong jung yong-ju kim hyeong-mook woo kang-min lee woo-je lee ruby nam mi-jung jeong so-ri jeong ye-na ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-thieu-trong-gio', 'Lửa Thiêu Trong Gió', 'Let Wind Goes By', 'https://phimimg.com/upload/vod/20250103-1/e8ee3f7c827cdd73c299ea4a7f8fbf70.jpg', 'https://phimimg.com/upload/vod/20250103-1/67ad6af9beb8649ce289d1bd1979ecfc.jpg', '<p>Năm 2003, một thị trấn nhỏ ở khu mỏ ở Ninh Hạ đối mặt với việc di dời. Một thi thể nữ bị thiêu cháy xuất hiện trước cửa đồn cảnh sát, tình trạng chết giống hệt một vụ án nghiêm trọng xảy ra 10 năm trước chưa kết án tại địa phương. Cảnh sát trưởng già sắp nghỉ hưu Chư Chí Cường và Trương Thao, người vì sai sót công việc mà bị hạ xuống đội cảnh sát hình sự khu mỏ trở thành đồng nghiệp. Cả hai cùng hợp sức điều tra phá án, trong khi thị trấn chuẩn bị di dời cũng dần hé lộ sự thật bi thảm của những gì đã xảy ra trong quá khứ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Jingchun","avatar":""},{"name":"Jiang Qiming","avatar":""},{"name":"Yang Caiyu","avatar":""},{"name":"Wu Xiaoliang","avatar":""},{"name":"Huang Chengcheng","avatar":""},{"name":"Tan Kai","avatar":""},{"name":"You Jingru","avatar":""},{"name":"Zhang Jingwei","avatar":""},{"name":"Xiangrong Dong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["风中的火焰","天坑","Let Wind Goes By","Let Wind Go By"]', 1784690324220);
