INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-tuyen-tap-phim-giang-sinh', 'Doraemon: Tuyển tập phim Giáng Sinh', 'Doraemon: Christmas movie collection', 'https://phimimg.com/upload/vod/20250108-1/59758d0ea39cc934cf4a6b19192efd68.jpg', 'https://phimimg.com/upload/vod/20250108-1/253015e0b5f1c0fe4f0f686e81c7c115.jpg', '<p>Đây là tuyển tập phim về Giáng Sinh được nhóm Mon Fansub dịch thuật. Có tổng cộng 9 tập phim.</p><p>Thứ tự như sau:<br/>Tập 1- Giáng sinh trong ngôi nhà bánh kẹo</p><p>Tập 2- Giáng sinh thực tế ảo tương lai</p><p>Tập 3- Giáng sinh từ máy tua bước nhảy thời gian</p><p>Tập 4- Ảo thuật gia Nobita - Phép màu giáng sinh</p><p>Tập 5- Giáng sinh vui vẻ với bàn thợ gốm</p><p>Tập 6- Hạt giống cây giáng sinh</p><p>Tập 7- Bữa tiệc giáng sinh đầy bất ngờ</p><p>Tập 8- Ông già Noel Nobita trong đêm Giáng sinh</p><p>Tập 9- Tên trộm quà trong đêm giáng sinh</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324220);
