INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ca-di-hoc', 'Đại Ca Đi Học', 'High School Return Of A Gangster', 'https://phimimg.com/upload/vod/20250108-1/c93e22d899384d43ca88a19b56a21d2f.jpg', 'https://phimimg.com/upload/vod/20250108-1/8de319190d181bcd945cfe74823939f7.jpg', '<p>Kim Deuk Pal là một tay trùm xã hội đen 47 tuổi, là kẻ đứng thứ 2 trong băng đảng của hắn. Anh ấy không có nền tảng học vấn do cha mẹ nghèo nhưng anh ấy có ước mơ được vào một trường đại học. Anh ấy đã học tập để đạt được ước mơ của mình, nhưng điều đó không hề dễ dàng. Một ngày nọ, anh nhìn thấy một chàng trai trẻ, Song Yi Heon, sắp tự sát. Khi đó, linh hồn của Deuk Pal đã chiếm hữu cơ thể của cậu học sinh trung học 19 tuổi có ý định tự tử. Deuk Pal sớm biết rằng Yi Heon là nạn nhân của sự bắt nạt, điều này khiến anh muốn tự kết liễu đời mình. Giờ đây, Deuk Pal, trong cơ thể của Yi Heon, đối mặt với những kẻ bắt nạt để trừng phạt chúng và trở thành bạn của bạn cùng lớp Choi Se Kyung. Se Kyung là một học sinh gương mẫu, có hoàn cảnh hoàn hảo nhưng lại bị bố bạo hành tại nhà.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon Chan-young","avatar":""},{"name":"Bong Jae-hyun","avatar":""},{"name":"Won Tae-min","avatar":""},{"name":"Lee Seo-jin","avatar":""},{"name":"Seo Tae-hwa","avatar":""},{"name":"Kim Se-won","avatar":""},{"name":"Joo Yoon-chan","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Shin Min-jae","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["黑社会的我成为了高中生","High School Return of a Gangster","조폭고","عودة رجل عصابة إلى المدرسة الثانوية","นักเลงซ่าส์ ท้าวัยเรียน","Гангстер-старшокласник","I, a Gangster, Became a High Schooler","조폭인 내가 고등학생이 되었습니다"]', 1784690324220);
