INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-ca-di-hoc', 'Đại Ca Đi Học', 'High School Return Of A Gangster', 'đại ca đi học high school return of a gangster yoon chan-young bong jae-hyun won tae-min lee seo-jin seo tae-hwa kim se-won joo yoon-chan lee kyung-young shin min-jae 黑社会的我成为了高中生 high school return of a gangster 조폭고 عودة رجل عصابة إلى المدرسة الثانوية นักเลงซ่าส์ ท้าวัยเรียน гангстер-старшокласник i, a gangster, became a high schooler 조폭인 내가 고등학생이 되었습니다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ghi-chep-ky-quai', 'Ghi Chép Kỳ Quái', 'Strange Notes', 'https://phimimg.com/upload/vod/20241227-1/c2ddee27ecc51d6d1ba6c111a09701c5.jpg', 'https://phimimg.com/upload/vod/20241227-1/42c6da8d886598bc3afa0b12b358d2fc.jpg', '<p>Một cửa hàng tạp hóa &quot;Căn nhà kỳ lạ&quot; được mở ở khu vực trung tâm thành phố. Những món hàng bên trong tưởng chừng như bình thường nhưng chúng đều có công dụng kỳ lạ. Ông chủ Đới Mông ghi lại hướng dẫn của họ vào &quot;Bút Ký Kỳ Lạ&quot; và khách có thể chọn vật phẩm theo nhu cầu của mình. Tất cả mọi loại người đến với &quot;Căn nhà kỳ lạ&quot; đều gặp phải những khó khăn của riêng mình và muốn tìm cách thoát khỏi tình trạng khó khăn, nhưng cuối cùng họ luôn nhận ra rằng giải pháp cho vấn đề không phải là những cửa hàng tạp hóa kỳ lạ này mà là tình yêu và niềm tin của họ</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tân Minh","avatar":""},{"name":"Bồ Ba Giáp","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Lưu Sướng","avatar":""},{"name":"Trần Bá Dung","avatar":""},{"name":"Hải Linh","avatar":""},{"name":"Vương Tử Vy","avatar":""},{"name":"Triệu Tần","avatar":""},{"name":"Tống Mộc Tử","avatar":""},{"name":"Cao Sảng","avatar":""},{"name":"Vương Trạch Hiên","avatar":""},{"name":"Vương Lệ Na","avatar":""},{"name":"Lưu Á Côn","avatar":""},{"name":"Trình Kỳ","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["怪奇筆記","怪奇笔记"]', 1784690324220);
