INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-hang-xom', 'Những Người Hàng Xóm', 'The Neighbors', 'https://phimimg.com/upload/vod/20250106-1/a8902e5eded8b9e7112bd352b4911930.jpg', 'https://phimimg.com/upload/vod/20250106-1/4022c540c45f64856e937553c4d7eb0f.jpg', '<p>Trong đêm khuya, nữ diễn viên Chu Vân Kỳ bị sát hại dã man tại nhà riêng. Điều tra viên Zhao Shang phát hiện ra một mạng lưới các mối quan hệ phức tạp liên quan đến sáu nghi phạm chính—mỗi người đều có mối liên hệ sâu sắc với Chu Vân Kỳ. Khi cuộc điều tra mở ra, động lực phức tạp của nỗi ám ảnh, ghen tị và động cơ tiềm ẩn trong số họ lộ ra ánh sáng, bộc lộ những mặt tối của bản chất con người.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Shunyao","avatar":""},{"name":"Jia Qing","avatar":""},{"name":"Hu Jun","avatar":""},{"name":"He Dujuan","avatar":""},{"name":"Yuan Jiahuan","avatar":""},{"name":"Jiang Fangting","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["七","邻居","The Neighbors","她和她的他们"]', 1784690324220);
