INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hen-song-con-phan-5', 'Cuộc Hẹn Sống Còn (Phần 5)', 'Date A Live (Season 5)', 'https://phimimg.com/upload/vod/20240419-1/061c2eee56977344434ff377d3e83845.jpg', 'https://phimimg.com/upload/vod/20240419-1/5a6dd33e4287be8c02f53227e92153c1.jpg', '<p>Tuy mang hình dáng của nữ giới, nhưng tinh linh thật ra là sinh vật mạnh mẽ đến từ thế giới lân cận. Chúng gây ra những thảm họa gọi là Không Chấn, dẫn đến cái chết của hơn 150 triệu người và bị xem là kẻ thù của nhân loại. Loài người có thể tiêu diệt chúng bằng vũ lực hoặc dễ dàng hơn: thông qua hẹn hò. Shido Itsuka là người sở hữu khả năng phong ấn sức mạnh của tinh linh bằng nụ hôn. Vì vậy, nhiệm vụ của anh là phải hẹn hò với Tohka - tinh linh từng hủy diệt Trái Đất 30 năm trước, để ngăn chặn thảm họa không tái diễn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Misuzu Togashi","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Iori Nomizu","avatar":""},{"name":"Asami Sanada","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Sarah Emi Bridcutt","avatar":""},{"name":"Minori Chihara","avatar":""},{"name":"Aya Endo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324220);
