INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('umjolonhung-co-gai-si-tinh', 'Umjolo:Những cô gái si tình', 'Umjolo: The Gone Girl', 'https://phimimg.com/upload/vod/20241112-1/b8a93c55ecaf981c2ec033e6f58136f3.jpg', 'https://phimimg.com/upload/vod/20241112-1/1e21ca1008d745b412d604234cdf5a29.jpg', '<p>Mối quan hệ tưởng như hoàn hảo của một cặp đôi tan vỡ khi một trong hai phát hiện ra sự không chung thủy của người kia, nhưng ai nói rằng mối quan hệ đó là dễ dàng?</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Shezi Sibongiseni","avatar":""},{"name":"Tyson Mathonsi","avatar":""},{"name":"Thobeka Shangase","avatar":""},{"name":"Gugu Gumede","avatar":""},{"name":"Ntando Menzi Mncube","avatar":""},{"name":"Nirvana Mokwe","avatar":""},{"name":"Nkansiyo Makhanya","avatar":""},{"name":"Baby Cele","avatar":""},{"name":"Sbusisiwe Jili","avatar":""},{"name":"Zama Ngcobo","avatar":""},{"name":"Meshack Mavuso","avatar":""},{"name":"Monica Zulu","avatar":""},{"name":"Tina Redman","avatar":""},{"name":"Thozama Ngwenya","avatar":""},{"name":"Sbusiswe Ngubane","avatar":""},{"name":"Londeka Sishi","avatar":""},{"name":"Yo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Umjolo: The Gone Girl"]', 1784690324220);
