INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boboiboy-galaxy-phan-3', 'BoBoiBoy Galaxy (Phần 3)', 'BoBoiBoy Galaxy (Season 3)', 'https://phimimg.com/upload/vod/20240624-1/50dcfb876cd98acbc98900da2176da30.jpg', 'https://phimimg.com/upload/vod/20240624-1/8fea5a7c9c023c7c5291c790e530defe.jpg', '<p>Power Spheras là những robot công nghệ cao mang theo sức mạnh không thể tưởng tượng được. Được nhiều người thèm muốn, những người máy này đã bỏ trốn và ẩn náu ở nhiều nơi trong thiên hà. Từng người một, Power Spheras đã bị truy lùng và bắt giữ bởi những kẻ có mục đích xấu. Và giờ đây, sức mạnh của chúng được sử dụng để tàn phá và hủy diệt khắp vũ trụ. Đây là câu chuyện về siêu anh hùng của Trái đất, BoBoiBoy và nhiệm vụ giải cứu các Quả cầu Sức mạnh và bảo vệ thiên hà của chúng ta.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Nur Fathiah Diaz","avatar":""},{"name":"Nur Sarah Alisya","avatar":""},{"name":"Yap Ee Jean","avatar":""},{"name":"Dzubir Mohamed Zakaria","avatar":""},{"name":"Wong Wai Kay","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324220);
