INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-sao-diem-vuong', 'Chuyện Tình Sao Diêm Vương', 'Pluto', 'https://phimimg.com/upload/vod/20241020-1/725514627a43d1adf758b7d9930d50bc.jpg', 'https://phimimg.com/upload/vod/20241020-1/9430e001afd8864ee85b57c77c7f7484.jpg', '<p><span style="text-wrap: nowrap;">Ai-oon là cặp song sinh đáng thất vọng của Ob-oom thành công và được yêu mến. Họ không ở gần.&nbsp;</span><span style="text-wrap: nowrap;">Vào đêm tân hôn của Ob-oom, cô kéo Ai-oon sang một bên và đưa ra yêu cầu với cô. Ob-oon và chồng cô ấy là Paul sẽ đi hưởng tuần trăng mật và cô ấy sẽ để lại một thứ quan trọng phía sau: người yêu, May, cô ấy vẫn chưa chia tay—và cô ấy muốn Ai-oon làm điều đó cho cô ấy.</span></p><p><span style="text-wrap: nowrap;">Vào sáng sớm sau đám cưới, Ai-oon biết tin cặp đôi mới cưới gặp tai nạn. Paul đã qua đời và Ob-oom đang hôn mê. Khi Ai-oon quyết định thực hiện yêu cầu của em gái mình, cô bị sốc khi biết May vừa bị mù vừa là phụ nữ. Cô thấy mình không chuẩn bị để hoàn thành nhiệm vụ.</span></p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Tipnaree Weerawatnodom","avatar":""},{"name":"รชานันท์ มหาวรรณ์","avatar":""},{"name":"พลอยนิรา หิรัญทวีศิลป์","avatar":""},{"name":"รัตท์ริชา ประภากิติ","avatar":""},{"name":"ปรียาภัทย์ หล่อสุวรรณศิริ","avatar":""},{"name":"Thinnaphan Tantui","avatar":""},{"name":"ศิวกร เลิศชูโชติ","avatar":""},{"name":"วีรยุทธ จันทร์สุข","avatar":""},{"name":"Neen Suwanamas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱情冥王星","冥王星恋人","冥王星之恋","Nithan Duangdao Khwam Rak","冥王星之戀","冥王星愛戀","Pluto","นิทาน ดวงดาว ความรัก"]', 1784690324221);
