INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tinh-sao-diem-vuong', 'Chuyện Tình Sao Diêm Vương', 'Pluto', 'chuyện tình sao diêm vương pluto tipnaree weerawatnodom รชานันท์ มหาวรรณ์ พลอยนิรา หิรัญทวีศิลป์ รัตท์ริชา ประภากิติ ปรียาภัทย์ หล่อสุวรรณศิริ thinnaphan tantui ศิวกร เลิศชูโชติ วีรยุทธ จันทร์สุข neen suwanamas 爱情冥王星 冥王星恋人 冥王星之恋 nithan duangdao khwam rak 冥王星之戀 冥王星愛戀 pluto นิทาน ดวงดาว ความรัก', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-thien-huyen-minh-nguyet', 'Vân Thiên Huyền Minh Nguyệt', 'True Love Moon', 'https://phimimg.com/upload/vod/20250103-1/c8fa2f54a3b7a73b7bb630f73beca0d6.jpg', 'https://phimimg.com/upload/vod/20250103-1/f3f1438de1cf3ed19d51339160378653.jpg', '<p>Sử dụng một chiếu chỉ giả, hoàng tử thứ hai dụ Yun Tianchen vào bẫy, nơi anh ta suýt bị giết. Luo Mingyue, người sống sót duy nhất, hợp lực với Yun Tianchen cải trang để vạch trần những kẻ âm mưu và nhận thấy mối quan hệ của họ ngày càng phát triển trong bối cảnh trả thù và âm mưu chính trị.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qiu Dingjie","avatar":""},{"name":"Zhu Jintong","avatar":""},{"name":"Yuan Zhiying","avatar":""},{"name":"Wang Gang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Yun Tian Xuan Ming Yue","True Love Moon","云天悬明月"]', 1784690324221);
