INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-gap-tinh-yeu-o-trung-khanh', 'Bắt Gặp Tình Yêu Ở Trùng Khánh', 'Meet Love In Chong Qing', 'https://phimimg.com/upload/vod/20241228-1/c40aefca2abc60a3fd81715aea2547bb.jpg', 'https://phimimg.com/upload/vod/20241228-1/65e3b95daa6a2524c46b68b036b977f2.jpg', '<p>Điền Ninh Mông là một cô gái vùng khác đến Bắc Kinh sinh sống làm việc; bạn trai ngoại tình, công ty phá sản, cô bị buộc phải về quê nhà ở Đồng Nam. Trên đường về, cô gặp chàng trai Tiêu Đường, anh chủ động trả hết nợ nần cho cô, từ đó hai người bắt đầu hành trình lập nghiệp dở khóc dở cười, có cả niềm vui và nước mắt. Không ngờ số mệnh đã sớm ràng buộc hai người với nhau.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sabrina Qiu","avatar":""},{"name":"Jiang Peng","avatar":""},{"name":"Lu Yao","avatar":""},{"name":"Ding Huiyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["重庆遇见爱"]', 1784690324221);
