INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-hinh-hung-thu', 'Dáng Hình Hung Thủ', 'The Appearance Of The Murderer', 'https://phimimg.com/upload/vod/20250105-1/72a042e9988ce0e6d7a223f8cc8b5f8d.jpg', 'https://phimimg.com/upload/vod/20250105-1/b2bd8e4255d32054a73620c801da0f47.jpg', '<p>Lin Chuan, bị ám ảnh bởi cái chết bí ẩn của một người bạn cùng lớp, đã dành mười năm để tìm kiếm sự thật. Trong khi đó, Thẩm Hạ và anh trai Thẩm Đông bị lôi kéo vào thế giới ngầm tội phạm sau bi kịch gia đình. Khi con đường của họ va chạm nhau, một cuộc đấu tranh căng thẳng giữa công lý và tội ác diễn ra, hòa quyện giữa tình yêu, sự căm ghét và sự trả thù trong một câu chuyện hấp dẫn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Han Dong","avatar":""},{"name":"Chen Xiaoyun","avatar":""},{"name":"Zhang Tao","avatar":""},{"name":"Wang Daqi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["暴雪追凶","The Appearance Of The Murdere","凶手的样子"]', 1784690324221);
