INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-tho', 'Song Thố', 'Soul Sisters', 'https://phimimg.com/upload/vod/20250105-1/ef2a93c60cb247b7ca67936a6f60fdb8.jpg', 'https://phimimg.com/upload/vod/20250105-1/c1faa39a126053d20be8345ebc68595c.jpg', '<p>Gu Jinyu, vị lãnh chúa trẻ tuổi thông minh của thành phố Bailong, đã cải trang thành nam giới từ khi còn nhỏ. Trong khi bí mật tại Thành trì Hắc Hổ để tìm kiếm bản đồ kho báu, cô bị Bai Yunxi, nữ thừa kế ngọt ngào nhưng vụng về bắt cóc và buộc phải kết hôn giả. Cả hai hình thành mối quan hệ hợp tác bất ngờ để cứu thành trì đang thất bại, đối mặt với những âm mưu, kẻ thù và thử thách của đối thủ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vicky Liang","avatar":""},{"name":"Yang Fuyu","avatar":""},{"name":"Shengheng Chen","avatar":""},{"name":"Ye Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Shuang Tu","双兔"]', 1784690324221);
