INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-nhe-lop-ba', 'Cảm Ơn Nhé, Lớp Ba', 'Thanks, Class Three', 'https://phimimg.com/upload/vod/20250105-1/0756bc1b6072735a94cfdf5adbb7d45f.jpg', 'https://phimimg.com/upload/vod/20250105-1/899769965cc0cbebb7a2227ab300946b.jpg', '<p>Sinh ra trong một gia đình nấu ăn, nữ chính Cai Cai trở thành thành viên của tầng lớp thứ ba và gặp Liao Yingzi, một gia sư sành ăn “độc” một cách tình cờ. Cô gặp Liao Yingzi, một gia sư sành ăn “độc”. Mặc dù Liao Yingzi là một nhà phê bình gay gắt, nhưng anh ấy đã khiến cô ấy tiến bộ mà cô ấy không nhận ra, đồng thời cô ấy vừa ghét vừa ngưỡng mộ anh ấy. Trong quá trình gặp gỡ, cả hai trở thành bạn bè. Với khả năng nấu nướng, Cai Cai giúp các bạn cùng lớp giải quyết nhiều vấn đề và với sự động viên của Liao Yingzi, cô đã có thể giải quyết mâu thuẫn gia đình lâu đời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dong Siyi","avatar":""},{"name":"Qiu Bai Hao","avatar":""},{"name":"Yang Yutong","avatar":""},{"name":"Jiang Yiduo","avatar":""},{"name":"Shi Kai","avatar":""},{"name":"Xu Qijie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Duo Xie San Ban","多謝三班","Thank you, Class 3","多谢三班"]', 1784690324221);
