INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-dien-thoai-do-chuong', 'Khi Điện Thoại Đổ Chuông', 'When The Phone Rings', 'https://phimimg.com/upload/vod/20241124-1/ecd277c545defc3abb0a8e1809c48abf.jpg', 'https://phimimg.com/upload/vod/20241124-1/8cae6333c0578004fe8906a830e5e460.jpg', '<p>Một cặp đôi sống trong một cuộc hôn nhân sắp đặt, không nói chuyện với nhau suốt ba năm, nhận được một cuộc gọi đe dọa từ một kẻ bắt cóc.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 25, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Yeon-seok","avatar":""},{"name":"Chae Soo-bin","avatar":""},{"name":"Heo Nam-jun","avatar":""},{"name":"Jang Gyu-ri","avatar":""},{"name":"Jeong Dong-hwan","avatar":""},{"name":"You Seong-joo","avatar":""},{"name":"Chu Sang-mi","avatar":""},{"name":"Choi Gwang-il","avatar":""},{"name":"Oh Hyun-kyung","avatar":""},{"name":"Han Jae-yi","avatar":""},{"name":"Lim Cheol-soo","avatar":""},{"name":"Yang Jo-a","avatar":""},{"name":"Ko Sang-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Quando o Telefone Toca","现在拨打的电话","وقتی تلفن زنگ میخوره","وقتی تلفن زنگ می‌زنه","هنگامی که تلفن زنگ می‌خورد","The Number You Have Dialed","Jigeum Geosin Jeonhwaneun","지금 거신 전화는","Набранный Вами номер","Номер который вы набрали","حين يرن الهاتف","เมื่อเสียงโทรศัพท์ดัง","When the Phone Rings"]', 1784690324221);
