INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-dien-thoai-do-chuong', 'Khi Điện Thoại Đổ Chuông', 'When The Phone Rings', 'khi điện thoại đổ chuông when the phone rings yoo yeon-seok chae soo-bin heo nam-jun jang gyu-ri jeong dong-hwan you seong-joo chu sang-mi choi gwang-il oh hyun-kyung han jae-yi lim cheol-soo yang jo-a ko sang-ho quando o telefone toca 现在拨打的电话 وقتی تلفن زنگ میخوره وقتی تلفن زنگ می‌زنه هنگامی که تلفن زنگ می‌خورد the number you have dialed jigeum geosin jeonhwaneun 지금 거신 전화는 набранный вами номер номер который вы набрали حين يرن الهاتف เมื่อเสียงโทรศัพท์ดัง when the phone rings', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-duoi-bat-w2', 'Trò Chơi Đuổi Bắt W2', 'Chaser Game W2: Utsukushiki Tennyotachi', 'https://phimimg.com/upload/vod/20240929-1/04e0332724cf700379ed399acded3300.jpg', 'https://phimimg.com/upload/vod/20240929-1/0598cab6b72944fd0c151ebf2daec5fc.jpg', '<p>Mặc dù Itsuki và Fuyu đã từng xa cách dù có tình cảm với nhau nhưng họ đã đoàn tụ thành công nhờ sự thấu hiểu của chồng Fuyu và con gái họ. Họ trải qua những khoảng thời gian hạnh phúc bên nhau, lấp đầy khoảng trống sau khoảng thời gian không thể gặp nhau, trò chuyện rất nhiều và ôm nhau. Tuy nhiên, mối tình đầu của Fuyu xuất hiện trước mặt Itsuki, và mẹ của Fuyu, người không đồng tình với mối quan hệ của họ, vẫn tiếp tục theo dõi họ, tạo ra bầu không khí căng thẳng giữa hai người. Làm thế nào họ sẽ vượt qua những thử thách xảy ra sau khi cuối cùng ở bên nhau?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"菅井友香","avatar":""},{"name":"中村ゆりか","avatar":""},{"name":"Chise","avatar":""},{"name":"Hina Kikuchi","avatar":""},{"name":"Nozomi Hanayagi","avatar":""},{"name":"Nao Hoshino","avatar":""},{"name":"黒谷友香","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["追踪者游戏W 职权骚扰的上司是我的前女友","猎人游戏W 滥用职权的上司是前女友","Chaser Game Double","Chaser Game W: Power Harassment Joshi wa Watashi no Moto Kano","Chaser Game W: Power Harassment Joushi wa Watashi no Motokano","チェイサーゲームW パワハラ上司は私の元カノ","チェイサーゲームW","Chaser Game W: Power Harassment Boss is My Ex-Girlfriend","Cheisa Gemu W: Pawahara Joushi wa Watashi no Moto Kano","チェイサ