INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-duong-dich-cong-an', 'Đại Đường Địch Công Án', 'Judge Dee''s Mystery', 'https://phimimg.com/upload/vod/20240208-1/045fa7c9360fb45b8affa92a1ef17999.jpg', 'https://phimimg.com/upload/vod/20240208-1/d01ddaa016870d60aa6c39701c7f25d1.jpg', '<p>Kể về câu chuyện vào thời Võ Tắc Thiên, triều đình ban hành luật bổ nhiệm, bãi nhiệm quan chức. Vào lúc này, Địch Nhân Kiệt, người đang muốn làm nên nghiệp lớn đã lên đường đi đến thị trấn phía Đông xa xôi. Dựa vào tài năng phá án của bản thân, ông đã giải quyết các khó khăn hết lần này đến lần khác. Tuy nhiên khi càng đi sâu vào vụ án, ông phát hiện ra sự việc ngày càng rối rắm, phức tạp. Bản thân ông đã đi khắp lãnh thổ Đại Đường, giải mã được vô vàn vụ kỳ án, sau cùng quay về Trường An, gặp lại cha. Hai cha con đã hợp sức với nhau, phá giải được mối nguy hiểm có thể xảy ra bất cứ lúc nào tại Trường An.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Nhất Vi","avatar":""},{"name":"Vương Lệ Khôn","avatar":""},{"name":"Chung Sở Hi","avatar":""},{"name":"Trương Gia Dịch","avatar":""},{"name":"Trương Nhược Du","avatar":""},{"name":"Vưu Dũng","avatar":""},{"name":"Cơ Tha","avatar":""},{"name":"Lăng Tư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324221);
