INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tich-hoa-chi', 'Tích Hoa Chỉ', 'Blossoms In Adversity', 'https://phimimg.com/upload/vod/20240402-1/5297b0ed257a17cbf1e5c1eee349ba49.jpg', 'https://phimimg.com/upload/vod/20240402-1/e0529f8a23bae9ab51d2fd2114b05131.jpg', '<p>Hoa phủ cao quý hiển hách bất ngờ bị tịch biên và lưu đày, chỉ còn lại phụ nữ cùng trẻ em bơ vơ. Đại tiểu thư Hoa Chỉ không còn giả vờ ngốc nghếch giấu dốt nữa, cô dẫn dắt phụ nữ trong nhà trình diễn màn lột xác của phụ nữ quyền quý, thoát khỏi cảnh đói rét và nguy hiểm trong muôn vàn chông gai. Cô còn biến ty sứ Thất Túc là Cố Yến Tích dũng mãnh vô song thành Yến tiên sinh, người thương mà ai nấy đều yêu mến. Trong suốt hành trình có cãi vã, có mặn nồng, từ một tiểu thư khuê các gặp nạn, Hoa Chỉ cũng trưởng thành và trở thành người chủ gia đình, hướng tới một cuộc sống mới rực rỡ.&nbsp;</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Nhất Thiên","avatar":""},{"name":"Trương Tịnh Nghi","avatar":""},{"name":"Ngô Hi Trạch","avatar":""},{"name":"Lư Dục Hiểu","avatar":""},{"name":"Bian Cheng","avatar":""},{"name":"Hồ Hạnh Nhi","avatar":""},{"name":"Liu Jia","avatar":""},{"name":"Hải Nhất Thiên","avatar":""},{"name":"Dương Minh Na","avatar":""},{"name":"Cao Hùng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324221);
