INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-trao', 'Quy Trạo', 'The Way Home', 'https://phimimg.com/upload/vod/20241225-1/11e1003cdebbfe2505c0b3d2a542e808.jpg', 'https://phimimg.com/upload/vod/20241225-1/94ffa91b95490524a21765681d4d27c9.jpg', '<p>Bộ phim dựa trên truyền thống đua thuyền rồng của vùng Lĩnh Nam, Trung Quốc, kể về hai anh em họ bị buộc phải chia cắt do biến cố gia đình. Tuy nhiên, dưới lời mời tham gia một cuộc thi đua thuyền rồng truyền thống, họ đã phá vỡ rào cản huyết thống, khôi phục tình cảm gia đình và cùng nhau tham gia thi đấu. Cuối cùng, trong quá trình thi đấu, họ đã hàn gắn lại tình thân, tạo dựng tình bạn và tìm ra lý tưởng sống.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ma Boquan","avatar":""},{"name":"Zhang Kangle","avatar":""},{"name":"Vivi Chen","avatar":""},{"name":"Yuan Mingze","avatar":""},{"name":"Fu Yushu","avatar":""},{"name":"Rebecca Zhu","avatar":""},{"name":"Yao Jingyuan","avatar":""},{"name":"Raymond Ho-Yin Wong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gui Zhao","The Way Love","The Way You Love","归棹"]', 1784690324221);
