INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-cua-moana-2', 'Hành Trình Của Moana 2', 'Moana 2', 'https://phimimg.com/upload/vod/20250102-1/f53075ad773ee3febea275a29cd86e9f.jpg', 'https://phimimg.com/upload/vod/20250102-1/8953bd972ef278ea03c548752f252206.jpg', '<p>“Hành Trình của Moana 2” là màn tái hợp của Moana và Maui sau 3 năm, trở lại trong chuyến phiêu lưu cùng với những thành viên mới. Theo tiếng gọi của tổ tiên, Moana sẽ tham gia cuộc hành trình đến những vùng biển xa xôi của Châu Đại Dương và sẽ đi tới vùng biển nguy hiểm, đã mất tích từ lâu. Cùng chờ đón cuộc phiêu lưu của Moana đầy chông gai sắp tới nhé.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Auliʻi Cravalho","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Hualālai Chung","avatar":""},{"name":"Rose Matafeo","avatar":""},{"name":"David Fane","avatar":""},{"name":"Awhimai Fraser","avatar":""},{"name":"Khaleesi Lambert-Tsuda","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Nicole Scherzinger","avatar":""},{"name":"Rachel House","avatar":""},{"name":"Gerald Ramsey","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Tofiga Fepulea''i","avatar":""},{"name":"Tiana Johnson","avatar":""},{"name":"Jasmin","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Moana: Um Mar de Aventuras 2","Маана 2","モアナ２","莫阿娜2","海洋奇緣2","Մոանա 2","海洋奇缘2","موانا ٢","Moana 2","Vaiana 2"]', 1784690324221);
