INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-tinh-yeu', 'Ác Mộng Tình Yêu', 'Suffocating Love', 'https://phimimg.com/upload/vod/20250102-1/1bcc979b701679aff313fbe3147e065f.jpg', 'https://phimimg.com/upload/vod/20250102-1/3fd0a4a75e5255dd53241e391eebae0d.jpg', '<p>Cảm thấy ngột ngạt vì cô bạn gái kiểm soát, chàng trai nọ ao ước được tự do nhưng rốt cuộc phải đối mặt với những hậu quả kinh hoàng khi giấc mơ của anh trở thành hiện thực.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Austin Lin","avatar":""},{"name":"Chloe Xiang","avatar":""},{"name":"Nikki Hsieh","avatar":""},{"name":"DaYuan Lin","avatar":""},{"name":"YELLOW","avatar":""},{"name":"McFly Wu","avatar":""},{"name":"Tzu-Chi Pei","avatar":""},{"name":"Chu Ou","avatar":""},{"name":"Chien Tsung-Fu","avatar":""},{"name":"Yi-tai Chiu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["夢魘","愛的噩夢"]', 1784690324221);
