INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-re-tai-ba', 'Chàng Rể Tài Ba', 'The Best Man', 'https://phimimg.com/upload/vod/20241220-1/0f4aee0324a7960cb554c10272ef5932.jpg', 'https://phimimg.com/upload/vod/20241220-1/5a4326cc97758344d664e5245f215a4b.jpg', '<p>Để tìm ra sự thật về cái chết của mẹ mình, Trần Trác - người thừa kế của nhà họ Trần ẩn giấu thân phận làm nhân viên bảo vệ tại công ty của Hứa Mỹ Doanh và vô tình trở thành rể ăn nhờ ở đậu. Anh trai song sinh của Trần Trác là Trần Việt luôn muốn trở thành người thừa kế của nhà họ Trần, đã giả làm Trần Trác để ở lại bên cạnh Hứa Mỹ Doanh. Trần Trác gánh trên vai áp lực của gia tộc, đã vạch trần bộ mặt thật của Trần Việt. Khi vượt qua mọi chuyện, Trần Trác đã dành phần đời còn lại bên cạnh Hứa Mỹ Doanh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leo Yang","avatar":""},{"name":"Li Huan","avatar":""},{"name":"Li Jiajia","avatar":""},{"name":"Jiang Yushun","avatar":""},{"name":"Liu Jiaxi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["乘龙赘婿"]', 1784690324221);
