INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-long-oan-gia', 'Phải Lòng Oan Gia', 'Love Your Enemy', 'https://phimimg.com/upload/vod/20241218-1/a93225ccf01d29f8cc6a5d4724190727.jpg', 'https://phimimg.com/upload/vod/20241218-1/bf8dd64a328775a54e260c454c495a05.jpg', '<p>Phim kể về câu chuyện tình yêu và thù hận giữa hai nhân vật chính – Seok Ji Won (Ju Ji Hoon) và Yoon Ji Won (Jung Yu Mi). Seok Ji Won là giám đốc điều hành của một tập đoàn, đồng thời cũng là chủ tịch của một trường trung học. Anh đa tài, giỏi cả về thể thao và học thuật, chính vì thế Ji Won trở thành tấm gương sáng và khiến nhiều người ngưỡng mộ. Trong khi đó, Yoon Ji Won lại là giáo viên thể dục tại cùng ngôi trường của Ji Won, cô thường được biết đến là một người sôi nổi và có tinh thần công lý mạnh mẽ. Hai người từng có tình cảm với nhau nhưng sau 15 năm xa cách, họ gặp lại nhau với tư cách là đối thủ, từ đó dẫn đến những cuộc đấu đá đầy hài hước và ấm áp.</p>', 'Tập 12', 12, 'series', 'ongoing', 15, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ju Ji-hoon","avatar":""},{"name":"Jung Yu-mi","avatar":""},{"name":"Lee Si-woo","avatar":""},{"name":"Kim Ye-won","avatar":""},{"name":"Kim Kap-soo","avatar":""},{"name":"Lee Byung-joon","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Baek Hyun-joo","avatar":""},{"name":"Kim Jae-chul","avatar":""},{"name":"Yoon Seo-hyun","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Kim Hee-chang","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Yi Seo","avatar":""},{"name":"Kim Hyeon-mok","avatar":""},{"name":"Hong Min-gi","avatar":""},{"name":"Oh Ye-ju","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["사랑은 외나무다리에서","Любовь на узком мостике","أحب عدوك","Love on a Single Log Bridge"]', 1784690324221);
