INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-gian-la', 'Không Gian Lạ', 'Call Of Destiny', 'https://phimimg.com/upload/vod/20241202-1/c6449da0dcfbf46dae1256870845a91b.jpg', 'https://phimimg.com/upload/vod/20241202-1/819ba0a61cb6fcccd9e9d0e24ae86365.jpg', '<p>Năm 2024, Phương Nhật Tấn (do Trần Gia Lạc đóng) – giáo sư đại học, tiến sĩ phân tích tâm lý học tội phạm – có linh cảm với những chuyện sắp xảy ra. Nhật Tấn nhận được email và điện thoại kỳ lạ từ Mary. Nhưng đó là điện thoại đến từ tương lai, dự báo nhiều vụ án tàn bạo sắp xảy ra. Nhật Tấn hợp tác cùng nữ cảnh sát Hình Khả Lam (do Trần Hiểu Hoa đóng) và trợ lý pháp y Trang Định Cần (do Nguyễn Hạo Tông đóng) cố gắng ngăn cản những vụ án đó. Nhưng hung thủ luôn ra tay sớm hơn họ. Cuối cùng, Nhật Tấn biết Mary chính là Hình Khả Lam của tương lai, Lam đang bị cảnh sát truy đuổi do nghi ngờ cô giết người...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Gia Lạc","avatar":""},{"name":"Trần Hiểu Hoa","avatar":""},{"name":"Nguyễn Hạo Tông","avatar":""},{"name":"Đàm Khải Kỳ","avatar":""},{"name":"Hà Viễn Đông","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["异空感应","Call Of Destiny","異空感應"]', 1784690324221);
