INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-cam-noi-yeu-nguoi', 'Dũng Cảm Nói Yêu Người', 'Caged Again', 'https://phimimg.com/upload/vod/20241116-1/5fe15c7660c7c08951aaae7694486261.jpg', 'https://phimimg.com/upload/vod/20241116-1/6ec34458a191e475ee40634936e6841f.jpg', '<p>&quot;Junior&quot;, một con chim cánh cụt biến hình thành con người trốn khỏi chuồng nuôi với hy vọng được đến Bắc Cực. Nhưng sau đó cậu lại bị giam cầm trong một ngôi trường nội trú. Mọi chuyện trở nên hỗn loạn khi Junior cầu xin &quot;Sun&quot;, vốn là chú báo đen biến thành người, đưa Junior thoát khỏi ngôi trường này! Bản năng kẻ đi săn của Sun bị đánh thức, trái tim Sun kêu gào đói khát mỗi khi ở cạnh Junior.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ben Benjamin Greenwell","avatar":""},{"name":"Jay Sorathon Chaloemlapsombut","avatar":""},{"name":"Jiraphat Sodjam","avatar":""},{"name":"Nokia Chinnawat Phattharathanachot","avatar":""},{"name":"Jeng Chotipat Suthadsanasoung","avatar":""},{"name":"Rasika Saisang","avatar":""},{"name":"Arm Sappanyoo Panatkool","avatar":""},{"name":"Porsch Apiwat Apiwatsayree","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["勇敢说爱你","#CagedAgain","Caged Again","บอกกรงๆ...ว่ารักเธอ"]', 1784690324221);
