INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-thanh-minh-thuong-ha-do', 'Mật Mã Thanh Minh Thượng Hà Đồ', 'Riverside Code At Qingming Festival', 'https://phimimg.com/upload/vod/20241218-1/1ac77c4871ae59c8d41d6cc75f8a0cf8.jpg', 'https://phimimg.com/upload/vod/20241218-1/46620b4af7d5af63affe01a0cbe40352.jpg', '<p>Vào thời Bắc Tống, tại góc phố Tước Nhi ở Biện Lương, có một gia đình năm người với tính cách trái ngược: Triệu Bất Ưu, Ôn Duyệt và các thành viên khác. Triệu Bất Ưu vốn chỉ là một tiểu lại cấp thấp tại Đại Lý Tự, chỉ mong muốn sống một cuộc sống bình dị, trái lại vợ anh, Ôn Duyệt, luôn ôm mộng mua nhà tậu ruộng. Dù thường xuyên tranh cãi, gia đình họ vẫn giữ được không khí ấm áp, đầy ắp tiếng cười. Một sự cố bất ngờ đã kéo cả gia đình vào vụ án &quot;Thuyền Mai&quot; chấn động, họ bước vào hành trình vừa phá giải những vụ án bí ẩn, vừa giải quyết hàng loạt vấn đề gia đình nảy sinh. Trong quá trình này, các thành viên dần hiểu và chấp nhận nhau hơn, cùng nhau trưởng thành và vượt qua muôn vàn khó khăn. Khi từng vụ án được làm sáng tỏ, mọi manh mối đều dẫn đến một &quot;Đại thiện nhân Giang Nam&quot;.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Baihe","avatar":""},{"name":"Zhang Songwen","avatar":""},{"name":"Zhou Yiwei","avatar":""},{"name":"Xia Meng","avatar":""},{"name":"Lin Jiachuan","avatar":""},{"name":"Zhang Xinyu","avatar":""},{"name":"Zhang Yao","avatar":""},{"name":"Hou Yansong","avatar":""},{"name":"Jiang Peiyao","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["qing ming shang he tu mi ma","Riverside Code at Qingming Festival","清明上河图密码"]', 1784690324221);
