INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-chanh-ngay-he', 'Cỏ Chanh Ngày Hè', 'I Am The Secret In Your Heart', 'https://phimimg.com/upload/vod/20241231-1/59bc9e25fc472e2a158cd4c2bfc605bd.jpg', 'https://phimimg.com/upload/vod/20241231-1/442fd97be3d0aa5d2b5b448742a7460d.jpg', '<p>Mê mẩn một học sinh chuyển trường quyến rũ, nữ sinh cấp ba nọ vướng vào chuyện tình tay ba giữa người cô thầm thích và một người bạn thân thời thơ ấu.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Đài Loan', 1, '[{"name":"Moon Lee","avatar":""},{"name":"Tsao Yu-ning","avatar":""},{"name":"Shou Lou","avatar":""},{"name":"Lin Mei-Shiu","avatar":""},{"name":"Kuang-Yao Fan","avatar":""},{"name":"Andy Huang","avatar":""},{"name":"Peggy Tseng","avatar":""},{"name":"Tie-Hsiang Ban","avatar":""},{"name":"Li Hsuan","avatar":""},{"name":"Porima Cheng","avatar":""},{"name":"Heather Chen","avatar":""},{"name":"Ying-Ru Chen","avatar":""},{"name":"Xavier Lin","avatar":""},{"name":"Tsai Chen-ju","avatar":""},{"name":"Nina Yeh","avatar":""},{"name":"Hajjah Lin","avatar":""},{"name":"An-Cheng Cheng","avatar":""},{"name":"Mario Pu","avatar":""},{"name":"Livion Lee","avatar":""},{"name":"Hangee Liu","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夏日的柠檬草","爱你很久很久","여름날의 레몬그라스","여름 날의 레몬그라스","夏日的檸檬草"]', 1784690324221);
