INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paris-that-thu', 'Paris Thất Thủ', 'Paris Has Fallen', 'https://phimimg.com/upload/vod/20241211-1/824f071817fd74d46e2c32997b50a62f.jpg', 'https://phimimg.com/upload/vod/20241211-1/0f038f27caafb98272a2c8e756cf3f55.jpg', '<p>Paris đang đứng trước nguy cơ bị tấn công khủng bố quy mô lớn. Một nhóm khủng bố do Jacob Pearce cầm đầu đã xâm nhập vào hàng ngũ cơ quan mật vụ, đe dọa an ninh quốc gia. Sĩ quan Vincent và điệp viên MI6 Zara phải hợp tác để tìm ra kẻ phản bội và ngăn chặn âm mưu khủng bố trước khi quá muộn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Tewfik Jallab","avatar":""},{"name":"Ritu Arya","avatar":""},{"name":"Emmanuelle Bercot","avatar":""},{"name":"Ana Ularu","avatar":""},{"name":"Nathan Willcocks","avatar":""},{"name":"Sean Harris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["巴黎沦陷","سقوط پاریس","Paris Has Fallen"]', 1784690324221);
