INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nguoi-duyen-ma-tai-hop', 'Tình Người Duyên Ma: Tái Hợp', 'Kang Mak: From Pee Mak', 'https://phimimg.com/upload/vod/20241230-1/54fc7e4ba2dcec81f9453d7e39179f78.jpg', 'https://phimimg.com/upload/vod/20241230-1/2c0c50af81df7f377628f50ebd706590.jpg', '<p>Remake từ bộ phim hài – kinh dị ảnh nổi tiếng của Thái Lan là Pee Mak – Tình Người Duyên Ma. Kang Mak kể lại hành trình trở về nhà từ chiến trường của anh lính tên Makmur. Tuy nhiên, Makmur phát hiện người vợ Sari của anh đã chết và trở thành một hồn ma.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Vino G. Bastian","avatar":""},{"name":"Marsha Timothy","avatar":""},{"name":"Indra Jegel","avatar":""},{"name":"Rigen Rakelna","avatar":""},{"name":"Tora Sudiro","avatar":""},{"name":"Indro","avatar":""},{"name":"Aming Sugandhi","avatar":""},{"name":"Andre Taulany","avatar":""},{"name":"TJ","avatar":""},{"name":"Tarzan","avatar":""},{"name":"Ananta Rispo","avatar":""},{"name":"Jirayut Afisan","avatar":""},{"name":"Almanzo Konoralma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Kang Mak","คังมาก","បងម៉ាកសំណព្វចិត្ត","Tình Người Duyên Ma: Tái Hợp","Kang Mak from Pee Mak"]', 1784690324221);
