INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-gui-tinh-yeu-vao-gio', 'Tôi Gửi Tình Yêu Vào Gió', 'Chasing The Wind', 'https://phimimg.com/upload/vod/20241225-1/5d65f4a09779c204cd29e3c51e018a10.jpg', 'https://phimimg.com/upload/vod/20241225-1/dbcb56559065ecbef691cc026023b587.jpg', '<p>Vì một trận thi đấu từ thuở nhỏ, cô bé Lâm Cách được cậu thiếu niên Nhiếp Trì giới thiệu vào trường thể thao, bắt đầu sự nghiệp trượt băng tốc độ cự ly ngắn. Lâm Cách lạc quan, phóng khoáng nhưng thấu đáo; Nhiếp Trì điềm tĩnh, sắc sảo và đầy lý tưởng. Cả hai trưởng thành dưới sự chăm sóc tận tình của huấn luyện viên Phương Thế Trung, người được ví như người cha già của trường thể thao, cùng với Phương Siêu, con trai của huấn luyện viên Phương, gia nhập đội tuyển tỉnh.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Zhenyu","avatar":""},{"name":"Gu Zicheng","avatar":""},{"name":"Shi Mingze","avatar":""},{"name":"Chen Jiawen","avatar":""},{"name":"Xia Ningjun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["我将喜欢告诉了风"]', 1784690324221);
