INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-vut-bay', 'Tuổi Trẻ Vút Bay', 'Genius Comes First ‎', 'https://phimimg.com/upload/vod/20241221-1/912d45dba39d064bdb59b8b2f18fbec6.jpg', 'https://phimimg.com/upload/vod/20241221-1/090446542e891f8f7a0bccb1ad168f1b.jpg', '<p>Sinh viên năm nhất Lý Ngôn Hạo đã hành động dám làm việc nghĩa nhưng lại bị &quot;nạn nhân&quot; Lý Giai Đồng gán cho cái mác &quot;kẻ biến thái&quot;, khiến danh tiếng của anh bị tổn hại toàn trường. Khi anh đang chán nản, anh gặp người bạn thời thơ ấu Du Lam và biết rằng nữ thần đang chuẩn bị cho một liên hoan phim trong khuôn viên trường và bắt đầu thành lập một nhóm làm phim ngắn. Mặc dù các thành viên trong nhóm đều là người mới nhưng điều này đã giúp Lý Ngôn Hạo chán nản tìm được hướng đi mới trong cuộc sống.</p>', 'Tập 22', 24, 'series', 'ongoing', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qin Tianyu","avatar":""},{"name":"Liu Yufeng","avatar":""},{"name":"Dai Yaqi","avatar":""},{"name":"Zhuo Yi Na Mu","avatar":""},{"name":"Wang Renke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Teng Kong Er Qi De Shao Nian","Flying Boy","腾空而起的少年"]', 1784690324221);
