INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-vuong-2099', 'Ma Vương 2099', 'Demon Lord 2099', 'https://phimimg.com/upload/vod/20241222-1/24f1c95063e63241783fc25db5ed683a.jpg', 'https://phimimg.com/upload/vod/20241222-1/68828f3555c348fe8799c648bdcec79e.jpg', '<p>Câu chuyện diễn ra vào năm 2099, tại thành phố Shinjuku - nơi khoa học công nghệ tiên tiến và ma thuật đã hòa quyện với nhau. Sau khi bị anh hùng Gram tiêu diệt cách đây 500 năm, Ma Vương Veltol đã được hồi sinh. Lần xuất hiện này, Veltol mong đợi những tham vọng thống trị thế giới năm xưa sẽ nhanh chóng trở thành sự thật. Tuy nhiên, hiện thực phũ phàng đang chờ đợi hắn: thuộc hạ phản bội, tín đồ biến mất, pháp thuật giảm sút. Ma Vương 2099 gần như trở thành một người bình thường. Để thống trị thế giới mới, Veltol đã dấn thân vào con đường đầy chông gai, thậm chí là phải trở thành người đứng đầu của giới &quot;streamer&quot;.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Satoshi Hino","avatar":""},{"name":"Miku Itou","avatar":""},{"name":"Masaya Matsukaze","avatar":""},{"name":"Shizuka Itou","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["DEMON LORD 2099","魔王2099","The Lord of Immortals Blooming In the Abyss F.E. 2099","Maou 2099"]', 1784690324221);
