INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ma-vuong-2099', 'Ma Vương 2099', 'Demon Lord 2099', 'ma vương 2099 demon lord 2099 satoshi hino miku itou masaya matsukaze shizuka itou demon lord 2099 魔王2099 the lord of immortals blooming in the abyss f.e. 2099 maou 2099', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-gia-dinh', 'Chuyện Gia Đình', 'Family Matters', 'https://phimimg.com/upload/vod/20241207-1/2d137dcd687ada9feed9320310635cc8.jpg', 'https://phimimg.com/upload/vod/20241207-1/dea357ed07cbfcdb2e96d0d23b1436b1.jpg', '<p>Bộ phim khai thác xung quanh cuộc sống của một nhóm người sở hữu năng lực đặc biệt phải cải trang thành một gia đình sau khi trốn thoát khỏi một nhà tù đặc biệt. Trong đó, Han Young Soo (Bae Doona) trở thành người mẹ yêu thương con cái và sở hữu skill “hack não” - cho phép thao túng hoặc bóp méo ký ức của bất kỳ ai. Baek Cheol Hee (Ryu Seung Bum) vào vai một người cha che giấu năng lực đặc biệt và vô cùng nhút nhát, yêu thương vợ tuyệt đối. Ông nội Baek Cheol Hee (Ryu Seung Bum) với tính cách hòa nhã, vui vẻ nhưng sâu bên trong lại có phần mờ ám. Cặp anh em sinh đôi Baek Ji Woo (Lee Soo Hyun) và Baek Ji Hoon (Lomon) thì tính cách trái ngược nhau, không ai chịu ai. Tưởng chừng cuộc sống và thân phận mới của họ sẽ trôi qua nhẹ nhàng, êm đềm, nhưng chốn dung thân mới này nhanh chóng trở thành một mớ bòng bong hỗn loạn bởi hàng loạt vụ mất tích, sát hại diễn ra một cách bí ẩn. Từ đây, bộ phim hé mở những âm mưu đen tối trong quá khứ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Bae Doona","avatar":""},{"name":"Ryoo Seung-bum","avatar":""},{"name":"Baek Yoon-sik","avatar":""},{"name":"Lomon","avatar":""},{"name":"Lee Soo-hyun","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["家族计划","پلانی خێزان","Gajokgyehoek","가족계획","Cuestión de familia","خطة عائلية","家族計劃","Family Plan","Family Matters"]', 1784690324221);
