INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-toi-nguoi-khong-co-cam-xuc', 'Vợ Tôi Người Không Có Cảm Xúc', 'My Wife Has No Emotion', 'https://phimimg.com/upload/vod/20241229-1/6330d6779f1725abde806ff51e09794e.jpg', 'https://phimimg.com/upload/vod/20241229-1/3760f12e1faae718eb38e88af4db5bdd.jpg', '<p>Takuma không phải là chàng trai thú vị nhất. Anh ấy vụng về, độc thân và không làm gì ngoài việc đi làm và về nhà. Mệt mỏi vì làm việc nhà, anh ta quyết định mua một robot dọn phòng tên là Mina. Cô ấy có thể nấu ăn và dọn dẹp một cách hoàn hảo, và cả hai hiểu nhau hơn theo thời gian. Chẳng mấy chốc, Takuma bắt đầu phải lòng Mina! Nhưng liệu một robot có thể yêu lại anh ta không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiyuki Toyonaga","avatar":""},{"name":"Konomi Inagaki","avatar":""},{"name":"Yoshino Aoyama","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Risae Matsuda","avatar":""},{"name":"Yuuki Wakai","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Boku no Tsuma wa Kanjou ga nai","Boku no Tsuma wa Kanjō ga nai","My Wife Has No Emotions","我的妻子不具感情","僕の妻は感情がない"]', 1784690324221);
