INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-ba-hoi-xuan', 'Ông Bà Hồi Xuân', 'Grandpa And Grandma Turn Young Again', 'https://phimimg.com/upload/vod/20241229-1/6c2c6aceeef99d3bf54527914236744e.jpg', 'https://phimimg.com/upload/vod/20241229-1/312a724470d79151d3bb1eafaff60573.jpg', '<p>Một cặp vợ chồng già tỉnh dậy và thấy mình trẻ như xưa. Họ quyết định tận dụng hết tuổi trẻ và sinh lực, mang lại niềm vui và nỗi bất ngờ cho gia đình và bạn bè.</p>', 'Full', 11, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shin-ichiro Miki","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Shiori Mikami","avatar":""},{"name":"Nao Toyama","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爷爷奶奶返老还童","老夫老妻重返青春","Jiisan Baasan Wakagaeru","Ojiisan to Obaasan ga Wakagaetta Hanashi","Jii-san Baa-san Wakagaeru","Дедушка и бабушка вновь стали молодыми","История о дедушке и бабушке, которые снова стали молодыми","คุณปู่คุณย่าย้อนวัยใส","A Story About a Grandpa and Grandma Who Returned Back to Their Youth","Grandpa and Grandma Turn Young Again","じいさんばあさん若返る"]', 1784690324221);
