INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-ba-hoi-xuan', 'Ông Bà Hồi Xuân', 'Grandpa And Grandma Turn Young Again', 'ông bà hồi xuân grandpa and grandma turn young again shin-ichiro miki mamiko noto shiori mikami nao toyama 爷爷奶奶返老还童 老夫老妻重返青春 jiisan baasan wakagaeru ojiisan to obaasan ga wakagaetta hanashi jii-san baa-san wakagaeru дедушка и бабушка вновь стали молодыми история о дедушке и бабушке, которые снова стали молодыми คุณปู่คุณย่าย้อนวัยใส a story about a grandpa and grandma who returned back to their youth grandpa and grandma turn young again じいさんばあさん若返る', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-chuc-khung-bo', 'Tổ Chức Khủng Bố', 'The Order', 'https://phimimg.com/upload/vod/20241229-1/2895fceb24f9c1650e0945b61105cf99.jpg', 'https://phimimg.com/upload/vod/20241229-1/8ccbeac4762449f4461b74f97b7a6f46.jpg', '<p>Các vụ cướp ngân hàng và trộm xe đang gia tăng ở vùng Tây Bắc Thái Bình Dương. Một nhân viên FBI nghi ngờ rằng tội ác không phải được thực hiện bởi những tên cướp thông thường nhằm mục đích làm giàu cho bản thân mà bởi một nhóm khủng bố nguy hiểm, kẻ cầm đầu tàn nhẫn đang lên kế hoạch tuyên chiến với chính phủ Mỹ. The Silent Brotherhood là một bộ phim kinh dị tội phạm do Justin Kurzel đạo diễn và có sự tham gia của Nicholas Hoult, Jude Law và Tye Sheridan. Bộ phim dựa trên một câu chuyện có thật gây chấn động cả nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jude Law","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Tye Sheridan","avatar":""},{"name":"Jurnee Smollett","avatar":""},{"name":"Alison Oliver","avatar":""},{"name":"Odessa Young","avatar":""},{"name":"Sebastian Pigott","avatar":""},{"name":"George Tchortov","avatar":""},{"name":"Victor Slezak","avatar":""},{"name":"Phillip Lewitski","avatar":""},{"name":"Matias Lucas","avatar":""},{"name":"Bradley Stryker","avatar":""},{"name":"Morgan Holmstrom","avatar":""},{"name":"Marc Maron","avatar":""},{"name":"Daniel Yip","avatar":""},{"name":"Daniel Doheny","avatar":""},{"name":"John Warkenti","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["教团","המסדר","النظام","秩序","The Orde