INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-ngo-gap-ma-lay', 'Gái Ngố Gặp Ma Lầy', 'Idiot Girls and School Ghost: School Anniversary', 'https://phimimg.com/upload/vod/20241229-1/6c13702fe85123d7b1c1ca12beb1e1df.jpg', 'https://phimimg.com/upload/vod/20241229-1/94dac53065ced70f8c112ca21ba4b2b2.jpg', '<p>Một nhóm bạn tình cờ tìm thấy một cuốn băng video bí ẩn cũ từ năm 1998 trong tủ của phòng phát thanh của trường. Họ phát hiện ra nếu chiến thắng trò chơi trốn tìm với con ma bị nguyền rủa vào đêm kỷ niệm ngày thành lập trường, họ sẽ nhận được điểm cao trong kỳ thi tuyển sinh đại học. Bần cùng nên làm liều, họ thực hiện các nghi thức như trong cuốn băng bí ẩn. Thế nhưng những hiện tượng ngộ - lạ và ối giồi ôi bắt đầu xảy ra với tất cả bọn họ. Truyền thuyết học đường giờ đây không còn là câu chuyện hư cấu mà đã trở thành tấn hài kịch bao trùm lấy họ.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kim Do-yeon","avatar":""},{"name":"Eunseo","avatar":""},{"name":"Jeong Ha-dam","avatar":""},{"name":"Kang Shin-hee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Amoeba Girls and School Ghost Stories: School Anniversary","아메바 소녀들과 학교괴담: 개교기념일"]', 1784690324221);
