INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-ki-quai', 'Ngôi Nhà Kì Quái', 'A Strange House', 'https://phimimg.com/upload/vod/20241228-1/9a7bb6680e59695adaa309661e5e1562.jpg', 'https://phimimg.com/upload/vod/20241228-1/4409a02695191de07b96ba2f11cce972.jpg', '<p>Amemiya (Mamiya Shotaro) là một YouTuber không được nổi tiếng lắm và chuyên thực hiện các video về chủ đề bí ẩn, huyền bí. Một ngày nọ, quản lý của anh mang đến một bản sơ đồ căn nhà kỳ quái nọ. Vị quản lý nói đây là sơ đồ nhà bình thường nhưng nhìn kỹ sẽ thấy có điều khó hiểu. Amemiya bắt đầu có hứng thú và xem xét kỹ hơn về sơ đồ căn nhà và quyết định nhờ vả vị kiến trúc sư đam mê khám phá những điều bí ẩn Kurihara (Sato Jiro) cùng tham gia. Cả 2 cùng nhau tìm hiểu bí ẩn đằng sau thì bất ngờ, Amemiya nhận được lời nhắn từ Yuzuki (Kawaei Rina) nói với anh rằng cô biết một sự thật bất ngờ ẩn sau sơ đồ căn nhà ấy. Cuối cùng, Yuzuki đã cùng Amemiya và Kurihara điều tra về bí ẩn ngôi nhà, tuy vậy cô ấy dường như còn cất giấu bí mật đen tối nào đó. Bộ phim được chuyển thể từ tiểu thuyết cùng tên của nhà văn Uketsu.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shotaro Mamiya","avatar":""},{"name":"Jiro Sato","avatar":""},{"name":"Rina Kawaei","avatar":""},{"name":"DJ Matsunaga","avatar":""},{"name":"Seiya Osada","avatar":""},{"name":"Miori Takimoto","avatar":""},{"name":"Masanobu Takashima","avatar":""},{"name":"Toshie Negishi","avatar":""},{"name":"Yuki Saito","avatar":""},{"name":"Koji Ishizaka","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Hen na Ie","Strange House","Henna Ie","A Strange House","The Floor Plan","บ้านวิกล","诡异之家","変な家"]', 1784690324221);
