INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xoa-tan-ky-uc', 'Xóa Tan Ký Ức', 'Bad Memory Eraser', 'https://phimimg.com/upload/vod/20241228-1/68c34296f69a182a0780e8584f6e2861.jpg', 'https://phimimg.com/upload/vod/20241228-1/021f4b27cb8bf7e4c252aa8684f89719.jpg', '<p>Xóa Tan Ký Ức kể về Lee Goon (Kim Jae Joong thủ vai) từng là một tay vợt triển vọng, nhưng anh đã bị chấn thương. Sau đó, anh mất hết tự tin và cuộc sống của anh thay đổi hoàn toàn. Với sự giúp đỡ của một thiết bị xóa ký ức, ký ức của anh bị xóa sạch và anh tái sinh với sự tự tin và hiện diện tối đa. Mối tình đầu tiên bị thao túng của anh là với Kyeong Joo Yeon (Jin Se Yeon thủ vai), một bác sĩ tâm lý tại trung tâm nghiên cứu não. Những người xung quanh anh còn có em trai Lee Shin, tay vợt số một thế giới. Trong khi đó, Jeon Sae Yan là phiên dịch viên của Lee Shin.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2024, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Jae-joong","avatar":""},{"name":"Jin Se-yeon","avatar":""},{"name":"Lee Jong-won","avatar":""},{"name":"Yang Hye-ji","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Bae Hae-seon","avatar":""},{"name":"Lee Ruby","avatar":""},{"name":"Han Sang-jin","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Jang Eui-soo","avatar":""},{"name":"Yoon Hee-won","avatar":""},{"name":"Jo Yi-hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Стирая плохие воспоминания","ممحاة الذاكرة السيئة","Bad Memory Eraser","나쁜 기억 지우개"]', 1784690324221);
