INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-trai-dep-hen-ho', 'Khi Trai Đẹp Hẹn Hò', 'How I Attended An All-Guy''s Mixer', 'khi trai đẹp hẹn hò how i attended an all-guy''s mixer mikako komatsu shunsuke takeuchi aoi yuki shun horie nao toyama gakuto kajiwara 到了联谊会上发现连一个女生都没有 去联谊，却发现没有女生 去参加联谊，却发现完全没有女生在场 goukon ni ittara onna ga inakatta hanashi gōkon ni ittara onna ga inakatta hanashi 合コンに行ったら女がいなかった話', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sinh-thanh-quy-toc-toi-co-ky-nang-tham-dinh-ba-dao-phan-2', 'Tái Sinh Thành Quý Tộc, Tôi Có Kỹ Năng Thẩm Định Bá Đạo (Phần 2)', 'As A Reincarnated Aristocrat, I''ll Use My Appraisal Skill To Rise In The World (Season 2)', 'https://phimimg.com/upload/vod/20241228-1/8d5d6df4fad45caeef6fa367d4633bab.jpg', 'https://phimimg.com/upload/vod/20241228-1/e69f925a79dac325ace7df033a0383ae.jpg', '<p>Series phim kể về cuộc sống sau khi tái sinh từ một người làm công ăn lương bình thường thành Ars Louvent, &quot;con trai của một quý tộc&quot;. Mặc dù không có tài về phép thuật hay kiếm thuật nhưng anh ấy có một kỹ năng mà không ai có: Thẩm định. Sử dụng khả năng này, Ars có thể xác định sức mạnh hiện tại của một người, tiềm năng của họ và tài năng của họ nằm ở đâu.

Với mong muốn xây dựng một lãnh thổ hưng thịnh, Ars bắt đầu tìm kiếm những cộng sự tài năng. Một người nước ngoài bị đàn áp với thanh kiếm vô song, một nô lệ với tài năng ma thuật vô danh và một cậu bé nhút nhát với niềm khao khát kiến thức không thể nguôi - những tài năng này hỗ trợ Ars rất nhiều trong công cuộc tạo ra lãnh thổ hùng mạnh nhất.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsumi Fujiwara","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Narumi Kaho","avatar":""},{"name":"Miho Okasaki","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Hitomi Nabatame","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Yuki Tanaka","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["轉生貴族憑鑑定技能扭轉人生 ～繼承弱小領土後，招募優秀人才打造最強領土～","轉生貴族憑鑑定技能扭轉人生","转生贵族凭鉴定技能扭转人生","Tensei Kizoku, Kantei Skill de Nariagaru","Tensei Kizoku","เกิดใหม่เป็นขุนนาง ขึ้นเป็นใหญ่ด้วยสกิลประเมิน -พอบุคคลชั้นยอดเข้ามา แคว้นแสนงอกง่อยที่รับสืบทอดก็กลายเป็นแคว้นสุดแกร่ง","เกิดใหม่เป็นขุนนาง ขึ้นเป็นใหญ่ด้วยสกิลประเมิน","轉生貴族憑鑑定技能扭轉人生～繼承弱小領土後，招募優秀人才打造最強領土～","Перероджений в аристократа, я використовуватиму свої навички оцінювання, щоб піднятися у світі","As A Reincarnated Aristocrat, I''ll Use My Appraisal Skill To Rise In The World","Chuyển Sinh Thành Quý Tộc, Tôi Sử Dụng Kỹ Năng Giám Định Để Tiến Thân Trong Thế Giới","Chuyển Sinh Thành Quý Tộc Với Kĩ Năng Thẩm Định","Tái Sinh Thành Quý Tộc, Tôi Có Kỹ Năng Thẩm Định Bá Đạo","転生貴族、鑑定スキルで成り上がる"]', 1784690324221);
