INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('niet-ban-thien-kim', 'Niết Bàn Thiên Kim', 'Ms. Nirvana', 'https://phimimg.com/upload/vod/20241218-1/28e70053e03fd822814c680835a8ebcf.jpg', 'https://phimimg.com/upload/vod/20241218-1/4336630c65f96838781ff32a3b8cc314.jpg', '<p>Cả nhà họ Phó bị hãm hại, duy chỉ có con gái Phó Chiếu Tuyết may mắn sống sót, mà chứng cứ lại chỉ về phía tình cũ Cố Kinh Châu. Cô phẫu thuật thẩm mỹ quay trở về, giả danh là Lâm Thiên Ngữ gả vào nhà họ Cố, trở thành chị dâu Cố Kinh Châu, từng bước điều nhà bí mật giấu kín trong nhà họ Cố. Cô cố tình tiếp cận với Cố Kinh Châu, để hai người nảy sinh tình cảm cấm kỵ, khiến anh em nhà họ Cố trở mặt. Chân tướng dần được phơi bày, Lâm Thiên Ngữ và Cố Kinh Châu cuối cùng khó mà kìm nén cảm xúc thật, nối lại tình xưa. Thù nhà và yêu hận dâng trào trong khoảnh khắc hé lộ chân tướng...</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Trạch","avatar":""},{"name":"Dương Y Mặc","avatar":""},{"name":"Lâm Tiêu","avatar":""},{"name":"Lưu Chỉ Vi","avatar":""},{"name":"Tôn Tử Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["替嫁千金","Nie Pan Qian Jin","涅槃千金"]', 1784690324221);
