INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-so-tinh-yeu', 'Biến Số Tình Yêu', 'Fervent Kiss', 'https://phimimg.com/upload/vod/20241221-1/36f0e387f9c3d9fcecb5934cb4ad007a.jpg', 'https://phimimg.com/upload/vod/20241221-1/a6eb38bde94f662d5f3d3a9e6fa1c193.jpg', '<p>Sau một vụ tai nạn, Thẩm Hàm Tinh phát hiện người yêu mình là Hạ Trầm đã bị em trai song sinh Hạ Xán mạo danh thay thế. Để điều tra rõ sự thật, cô giả vờ đính hôn với Chung Tư Hoài, chú của Hạ Trầm để tiếp cận Hạ Xán. Càng điều tra sâu hơn, mối quan hệ giữa hai người càng trở nên mập mờ. Thẩm Hàm Tinh dần phát hiện ra dường như người luôn ở bên cạnh cô mới chính là Hạ Trầm thật sự!</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guo Jianan","avatar":""},{"name":"Zhou Jingbo","avatar":""},{"name":"Qin Fen","avatar":""},{"name":"Li Qian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["炙吻","重生后我嫁给了残疾大佬","Fervent Love","爱的未知"]', 1784690324221);
