INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-cua-cho-rung-phan-1', 'Ngày Của Chó Rừng (Phần 1)', 'The Day Of The Jackal (Season 1)', 'https://phimimg.com/upload/vod/20241226-1/5a38c9f8cad4d83e2bea3e3106709f6b.jpg', 'https://phimimg.com/upload/vod/20241226-1/b94966cea0280609a68f4ff449e8c942.jpg', '<p>Bộ phim kể về một sát thủ chuyên nghiệp có biệt danh là Jackal (Chó Rừng). Anh được thuê để thực hiện một nhiệm vụ ám sát quan trọng với mức giá cao. Trong khi đó, Bianca Pullman, một đặc vụ của MI6, được giao nhiệm vụ ngăn chặn Jackal. Cuộc rượt đuổi căng thẳng và đầy kịch tính giữa Jackal và Pullman diễn ra khắp châu Âu, khiến hai người phải đối đầu trực tiếp trong một trò chơi sinh tử.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Eddie Redmayne","avatar":""},{"name":"Lashana Lynch","avatar":""},{"name":"Úrsula Corberó","avatar":""},{"name":"Chukwudi Iwuji","avatar":""},{"name":"Khalid Abdalla","avatar":""},{"name":"Lia Williams","avatar":""},{"name":"Eleanor Matsuura","avatar":""},{"name":"Ben Hall","avatar":""},{"name":"Sule Rimi","avatar":""},{"name":"Jon Arias","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Day of The Jackal","豺狼的日子","The Day of the Jackal","데이 오브 더 자칼","자칼의 날","Sjakalen","يوم إبن آوى","豺狼之日"]', 1784690324221);
