INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-giac-dau-ii', 'Võ Sĩ Giác Đấu II', 'Gladiator II', 'https://phimimg.com/upload/vod/20241206-1/60a7f92198233ca36dfcb6f5bf53f0da.jpg', 'https://phimimg.com/upload/vod/20241206-1/a6c7a02cb4965ea2e8d78e5836f86d64.jpg', '<p>20 năm trước, một anh hùng đã được sinh ra và nhanh chóng thống trị mọi mặt trận phòng vé toàn cầu đầy kiêu hãnh. Tên gã là &quot;Maximus Decimus Meridius, chỉ huy quân đội phương Bắc, tướng quân của Felix Legions, người trung thành với hoàng đế chân chính Marcus Aurelius, cha của một đứa con đã bị giết, chồng của một người vợ đã bị giết. Và tôi sẽ trả thù, trong kiếp này hoặc kiếp sau&quot;. Và 20 năm sau, Võ Sĩ Giác Đấu II tiếp nối với câu chuyện được thúc đẩy bởi nỗi căm thù của cậu bé Lucius, lúc này đã là một chàng võ sĩ giác đấu cường tráng bị ép buộc phải bước vào Đấu Trường La Mã khi cả vương quốc của mình rơi vào tay những gã Hoàng Đế bạo chúa.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Paul Mescal","avatar":""},{"name":"Denzel Washington","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Joseph Quinn","avatar":""},{"name":"Fred Hechinger","avatar":""},{"name":"Lior Raz","avatar":""},{"name":"Derek Jacobi","avatar":""},{"name":"Peter Mensah","avatar":""},{"name":"Matt Lucas","avatar":""},{"name":"Alexander Karim","avatar":""},{"name":"Yuval Gonen","avatar":""},{"name":"Richard McCabe","avatar":""},{"name":"Tim McInnerny","avatar":""},{"name":"Alec Utgoff","avatar":""},{"name":"Rory McCann","avatar":""},{"name":"Yann Gael","avatar":""},{"name":"Riana Duce","avatar":""},{"name":"Alf","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Il gladiatore 2","גלדיאטור 2","Gladyatör II","Gladyatör 2","Гладиатор II","글래디에이터 2","Qladiator II","グラディエーターII 英雄を呼ぶ声","帝國驕雄 2","Gladiador 2","角斗士2","글래디에이터Ⅱ","글래디에이터 II","Գլադիատոր 2","Gladiateur II","神鬼戰士II","المجالد 2","글래디에이터 Ⅱ","Gladiator II"]', 1784690324221);
