INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-si-giac-dau-ii', 'Võ Sĩ Giác Đấu II', 'Gladiator II', 'võ sĩ giác đấu ii gladiator ii paul mescal denzel washington pedro pascal connie nielsen joseph quinn fred hechinger lior raz derek jacobi peter mensah matt lucas alexander karim yuval gonen richard mccabe tim mcinnerny alec utgoff rory mccann yann gael riana duce alf il gladiatore 2 גלדיאטור 2 gladyatör ii gladyatör 2 гладиатор ii 글래디에이터 2 qladiator ii グラディエーターii 英雄を呼ぶ声 帝國驕雄 2 gladiador 2 角斗士2 글래디에이터ⅱ 글래디에이터 ii գլադիատոր 2 gladiateur ii 神鬼戰士ii المجالد 2 글래디에이터 ⅱ gladiator ii', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-chon-song-chet', 'Lựa Chọn Sống Chết', 'Spare Me Your Mercy', 'https://phimimg.com/upload/vod/20241129-1/df216bc8ba138373e2f6be3675382679.jpg', 'https://phimimg.com/upload/vod/20241129-1/d725cdc84c228e411780844ec14fa02f.jpg', '<p>Chúng ta có quyền quyết định về cái chết của chính mình hay không? Tỷ lệ tử vong ngày càng tăng một cách đáng ngờ ở những bệnh nhân giai đoạn cuối đã để lại dấu vết nghi ngờ không thể xóa nhòa trong tâm trí của Wasan (JJ). Mẹ anh, người vừa qua đời chỉ vài ngày trước khi anh về đến quê hương, có thể là một trong những nạn nhân của vụ việc này. Kantaphat (Tor Thanapob), một bác sĩ giảm đau từng chăm sóc mẹ Wasan trong những ngày cuối đời, cũng trở thành người chăm sóc trái tim cho con trai bà trong những ngày đau buồn. Khi mối quan hệ của họ ngày càng sâu sắc hơn, bí ẩn dần được làm sáng tỏ và mọi manh mối trong vụ án này đều dẫn đến Kantaphat. Liệu Wasan có thể vượt qua tình thế tiến thoái lưỡng nan này và hết lòng tin tưởng người yêu?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thanapob Leeratanakachorn","avatar":""},{"name":"Kritsanapoom Pibulsonggram","avatar":""},{"name":"Bhumibhat Thavornsiri","avatar":""},{"name":"Duangjai Hiransri","avatar":""},{"name":"Gandhi​ Wasuvitchayagit","avatar":""},{"name":"Pongsatorn Jongwilas","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Atchareeya Potipipittanakorn","avatar":""},{"name":"Yasaka Chaisorn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["安乐死","การุณยฆาต"]', 1784690324221);
