INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lua-chon-song-chet', 'Lựa Chọn Sống Chết', 'Spare Me Your Mercy', 'lựa chọn sống chết spare me your mercy thanapob leeratanakachorn kritsanapoom pibulsonggram bhumibhat thavornsiri duangjai hiransri gandhi​ wasuvitchayagit pongsatorn jongwilas arisara wongchalee atchareeya potipipittanakorn yasaka chaisorn 安乐死 การุณยฆาต', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-mong-phu-sinh', 'Nhất Mộng Phù Sinh', 'Land Of Dreams', 'https://phimimg.com/upload/vod/20241225-1/8b6b0df1300338de207f89d6e9f1642a.jpg', 'https://phimimg.com/upload/vod/20241225-1/507e2b639b53531678b053e74a99c234.jpg', '<p>Cuối thời nhà Thanh đầu Dân Quốc, phú thương nhà họ Lâm bị thảm sát. Cô con gái duy nhất trong nhà là Lâm Mộng Thần bị bán cho gia đình gian thương họ Hoàng, tổ chức minh hôn với người con trai đã chết của họ. Vào lúc Mộng Thần sắp bị chôn sống, Hiểu Sinh, sát thủ hàng đầu tổ chức sát thủ Huyết Tế Đường nhận nhiệm vụ tiêu diệt nhà họ Hoàng, vô tình cứu được cô. Mộng Thần chứng kiến toàn bộ quá trình Hiểu Sinh giết người, không những không sợ hãi mà còn coi Hiểu Sinh đang thực hiện nhiệm vụ là ân nhân của mình. Diệp Hiểu Sinh quyết định mang Lâm Mộng Thần theo bên mình, từ đó trở đi coi cô như em gái, bảo vệ cô suốt đời. Thấm thoắt đã mười năm, Hiểu Sinh vì muốn cho &quot;em gái&quot; một môi trường phát triển tốt mà luôn mang hai thân phận. Những khi ở nhà, trước mặt Mộng Thần, hắn là thương nhân, chưởng quầy Diệp, mở hiệu buôn bán đồ Tây kiếm sống. Còn trong bóng tối nơi Mộng Thần không nhìn thấy, hắn vẫn là sát thủ số một của Huyết Tế Đường.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Yiren","avatar":""},{"name":"Fang Sichang","avatar":""},{"name":"Chang Jin","avatar":""},{"name":"Chen Guoliang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一夢浮生","Land of Dreams","一梦浮生"]', 1784690324221);
