INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-bach-quyet', 'Hắc Bạch Quyết', 'Duel Of Shadows', 'https://phimimg.com/upload/vod/20241225-1/596dcaa3534114780e2ff38be77abf59.jpg', 'https://phimimg.com/upload/vod/20241225-1/98e00c5acb2dfcf1d05fa0a73112428a.jpg', '<p>Trong suốt 15 ngày truy tìm hung thủ, cảnh sát hình sự trẻ Hàn Chứng Phi đã trải qua muôn vàn khó khăn nhưng dù chết vẫn kiên định. Mái tóc bỗng bạc trắng sau một đêm nhưng anh vẫn giữ tấm lòng son, cuối cùng, anh đã truy bắt được hung thủ thành công, đồng thời tìm được niềm tin nghề nghiệp của một người thực thi pháp luật.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Xuwen","avatar":""},{"name":"Tian Yu","avatar":""},{"name":"Zhang Zhijian","avatar":""},{"name":"Gai Yuexi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Hei Bai Jue","Duel of Shadows","黑白诀"]', 1784690324221);
