INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-hong-nuong', 'Tiếu Hồng Nương', 'When Fate Plays Matchmaker', 'https://phimimg.com/upload/vod/20241113-1/f3eb26e407ea8df93b9315c0f7ec084f.jpg', 'https://phimimg.com/upload/vod/20241113-1/8fbff56072481d0ddfa5b034e59532ab.jpg', '<p>Giới thiệu Tiếu Hồng Nương Tiếu Hồng Nương Giới thiệu Triệu Song Song, chủ quán Nhân Duyên, sở hữu đôi mắt có thể nhìn thấy &quot;sợi chỉ đỏ&quot; kết nối những người định mệnh, giúp cô trở thành người mai mối nổi tiếng nhất thành Lâm An. Ước mơ lớn nhất của cô là sớm se duyên cho 81 cặp đôi và sau đó tìm được hạnh phúc cho chính mình. Triệu Song Song gặp được Trình Nhân, người đàn ông thề sẽ phá vỡ mọi cuộc hôn nhân vì sư huynh của anh đã qua đời bi thảm sau khi bị một bà mối độc ác mai mối. Hai người vừa yêu vừa hận, nhưng qua thời gian, Trình Nhân dần dần có cảm tình với Triệu Song Song. Khi Tào Tuế, người mà Triệu Song Song thầm yêu, xuất hiện, Trình Nhân mới nhận ra tình cảm của mình dành cho cô. Tuy nhiên, một vấn đề lớn đang chờ đợi họ. Cái chết của sư huynh Trình Nhân có mối liên hệ trực tiếp với Triệu Song Song. Cuối cùng, bí mật về quá khứ cũng được hé mở. Cả hai hạnh phúc cùng nhau quản lý quán Nhân Duyên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wei Tianhao","avatar":""},{"name":"Zhao Xinghui","avatar":""},{"name":"Wang Yiqin","avatar":""},{"name":"Sun Cailun","avatar":""},{"name":"Xuan Le","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["俏紅娘","俏红娘"]', 1784690324221);
