INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-tan-yen-vu', 'Nhất Tán Yên Vũ', 'A Love Story Of Oiled Paper Umbrella', 'https://phimimg.com/upload/vod/20241219-1/ab7ec005f6881fc4f34ed2cc2828d2a1.jpg', 'https://phimimg.com/upload/vod/20241219-1/545276be00f66c19ef0ade136c3b151e.jpg', '<p>Đại Lý Tự chính Nam Phong Ý và nữ nha nhân Mộng Tây Châu vì án gặp nhau, kết làm sư đồ cùng bắt yêu. Khi tình cảm giữa hai người dần sâu đậm, yêu vương Mộng Tây Châu hiện thế bị tâm ma mê hoặc khống chế. Nam Phong Ý cũng phát hiện trong cơ thể mình có yêu đan của Mộng Tây Châu đã mất nhiều năm. Để cứu người yêu, Nam Phong Ý mổ đan trả lại, và dùng hết sinh mệnh cuối cùng cùng Mộng Tây Châu liên thủ kháng cự, trả lại tự do cho những sinh linh vô tội.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yu Menglong","avatar":""},{"name":"Li Zixuan","avatar":""},{"name":"June Wu","avatar":""},{"name":"Zhong Lili","avatar":""},{"name":"He Hua","avatar":""},{"name":"Feng Lijun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["一伞烟雨"]', 1784690324221);
