INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lenh-tong-da-lau-khong-gap', 'Lệnh Tổng Đã Lâu Không Gặp', 'In The Grip Of Love', 'https://phimimg.com/upload/vod/20241214-1/283eb99bcc91bd1b37c189d1cc5016a0.jpg', 'https://phimimg.com/upload/vod/20241214-1/43557f3cef62587517cef998e84f9c06.jpg', '<p>Lần đầu tiên Vu Hi Lệnh - một nữ doanh nhân giỏi giang và thông minh, tình cờ gặp gỡ Cố Triêu Hòa - một sinh viên thể dục đầy nam tính là do một vụ hiểu lầm sau cơn say. Thả thính qua lại, giằng co đến cực hạn, &quot;hồng hài nhi&quot; kém tuổi thẳng thắn bày tỏ tình cảm, ai sẽ là người nộp vũ khí đầu hàng trước? Người chồng chưa cưới mất tích ba năm bỗng nhiên trở về, rốt cuộc đằng sau là những âm mưu và toan tính gì?</p>', 'Tập 30', 30, 'series', 'ongoing', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nghệ Hiểu Kì","avatar":""},{"name":"Trình Vũ Phong","avatar":""},{"name":"Trang Đạt Phi","avatar":""},{"name":"Phùng Uyển Hạ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ling Zong Wu Yang","令总有恙","영총무양: 어쩌다 연하남","令总无恙"]', 1784690324221);
