INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-vong-giau-sang', 'Tham Vọng Giàu Sang', 'Ambition For Wealth', 'https://phimimg.com/upload/vod/20241118-1/85886e6311230114a1d1b21a03abde5d.jpg', 'https://phimimg.com/upload/vod/20241118-1/d9c6412ef66e13b688a0b75eed5a615e.jpg', '<p>Có nỗi oán hận được nung nấu từ những đắng cay, tủi nhục chất chồng theo năm tháng. Để rồi, tham vọng cháy bỏng về một cuộc đổi đời cùng bao tính toan đầy ích kỷ… tất cả đã trở thành ngọn nguồn khơi mào tấn bi kịch của tình thân và tình yêu… “Tham vọng giàu sang” - một xuất phẩm “hương xưa” đặc sắc được giới thiệu lúc 20h các ngày từ thứ Hai đến thứ Bảy trên THVL1, bắt đầu từ 26/10/2024.</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Cao Minh Đạt","avatar":""},{"name":"Lê Phương","avatar":""},{"name":"Bạch Công Khanh","avatar":""},{"name":"YeYe Nhật Hạ","avatar":""},{"name":"Tam Triều Dâng","avatar":""},{"name":"Đình Hiếu","avatar":""},{"name":"Thanh Hiền","avatar":""},{"name":"Trung Dũng","avatar":""},{"name":"Văn Phượng","avatar":""},{"name":"Dũng Bino","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324221);
