INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-giang-sinh', 'Mối Tình Giáng Sinh', 'A Sprinkle Of Christmas', 'https://phimimg.com/upload/vod/20241224-1/2206f17cdba9d3fa2a95fd5327b0934c.jpg', 'https://phimimg.com/upload/vod/20241224-1/170f8a3536d3f133f37c976a0586a808.jpg', '<p>Libby là một thợ làm bánh mới nổi, mở cửa hàng của mình đúng vào mùa Giáng sinh. Trong khi cố gắng ổn định công việc, cô vô tình rơi vào cuộc tranh cãi trên mạng với Peter - một diễn viên hạng A bởi vì anh ta đưa ra đánh giá ẩn danh nhưng khá gay gắt về tiệm bánh của cô. Điều trùng hợp là Libby vừa nhận công việc cung cấp bánh kẹo cho bữa tiệc đính hôn của anh trai Peter. Cả hai không nhận ra rằng họ đã từng tranh cãi kịch liệt. Những tình huống dở khóc dở cười bắt đầu kéo theo sự khởi đầu của một mối tình thú vị.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Hayley Sales","avatar":""},{"name":"Marshall Williams","avatar":""},{"name":"Teagan Vincze","avatar":""},{"name":"Shay Galor","avatar":""},{"name":"Sarah Angelle","avatar":""},{"name":"Nik Andrews","avatar":""},{"name":"Ajay Bharti","avatar":""},{"name":"Neville Bowman","avatar":""},{"name":"Rhys Cawley","avatar":""},{"name":"Tavia Cervi","avatar":""},{"name":"Tyler Cody","avatar":""},{"name":"Tyler Cody","avatar":""},{"name":"Toni Nielsen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["A Sprinkle of Christmas"]', 1784690324221);
