INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('punghyanggo', 'Punghyanggo', 'Punghyanggo', 'https://phimimg.com/upload/vod/20241223-1/cd0bad75e4bd427342b42708bf9a13bd.jpg', 'https://phimimg.com/upload/vod/20241223-1/35e3221008dc04ca7ff0a04a97a68d8d.jpg', '<p>Việt Nam đang ngày càng khẳng định sức hút trên bản đồ du lịch thế giới, không chỉ bởi cảnh sắc thiên nhiên tuyệt đẹp mà còn nhờ nền ẩm thực đa dạng, tinh tế. Mới đây, hương vị Việt đã chinh phục khán giả quốc tế khi xuất hiện trong tập đầu tiên của chương trình &quot;Punghyanggo&quot; - show truyền hình nổi tiếng xứ Hàn.</p>', 'Tập 4', 10, 'tvshows', 'ongoing', 12, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae Suk","avatar":""},{"name":"Hwang Jung Min","avatar":""},{"name":"Yang Se Chan","avatar":""},{"name":"Ji Suk Jin","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Breakfast at Dawn"]', 1784690324221);
