INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('love-sick-2024', 'Love Sick 2024', 'Love Sick 2024', 'https://phimimg.com/upload/vod/20241018-1/6864a0d03816bfffc6213fa7479aa477.jpg', 'https://phimimg.com/upload/vod/20241018-1/2b668c311e736e4536f835c811cc1241.jpg', '<p>Câu chuyện về một ngôi trường toàn nam tên là &quot;Friday College&quot;. Pun, phó chủ tịch hội học sinh hoàn hảo, có bạn gái nhưng bố lại muốn cậuhẹn hò với con gái của bạn mình. Bố của Pun không thèm nghe Pun nói nhưng lại rất yêu quý cô em gái là Pang, người bị ám ảnh với tình yêu giữa các cậu trai. Trong khi đó, No, chủ tịch sôi nổi của câu lạc bộ âm nhạc đang cần ngân sách cao hơn cho câu lạc bộ của mình, nếu không cậu sẽ gặp rắc rối lớn. Pun biết mình có thể giúp No giải quyết vấn đề của mình nên đã đề nghị No trở thành bạn trai giả để đổi lấy sự giúp đỡ. Tuy nhiên, mối quan hệ giả vờ này sớm chuyển sang một điều gì đó hơn thế nữa khi No và Pun nảy sinh tình cảm với nhau.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Almond Poomsuwan Suwansatit","avatar":""},{"name":"Progress Passawish Thamasungkeeti","avatar":""},{"name":"Krit Ngamtanakijja","avatar":""},{"name":"Phop Pongphop Samranchaiyakorn","avatar":""},{"name":"Jennie Panhan","avatar":""},{"name":"Toto Thayawat Sereeviriyakun","avatar":""},{"name":"NJ Deeprompt Soontornsittisopa","avatar":""},{"name":"Volk Vachirawit Ouitayakul","avatar":""},{"name":"Sky Phasith Aroonratanakul","avatar":""},{"name":"Shane","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chunlamun K