INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muu-ke-co-xua-long-bich-chien', 'Mưu Kế Cổ Xưa: Long Bích Chiến', 'Antique StrategyThe Battle of longbi', 'https://phimimg.com/upload/vod/20241220-1/bdc1546fb3333bfba84355ed479003c4.jpg', 'https://phimimg.com/upload/vod/20241220-1/d386df7007eedff2b4db073f624fcdc3.jpg', '<p>Đường Chính từ nhỏ đã theo ông luyện võ, và nhờ công phu tuyệt vời mà được trọng dụng tại một võ đường dân gian. Tình cờ, anh phát hiện ra chủ võ đường Triệu Long Long liên quan đến việc buôn bán đồ cổ. Triệu Long Long đã tham gia một trận cược quyền với Lôi Báo, và Đường Chính đã đại diện tham gia, chiến đấu gian nan nhưng cuối cùng giành chiến thắng. Khi anh yêu cầu món đồ Qùy Long Bích, hai bên xảy ra mâu thuẫn và cảnh sát đã kịp thời có mặt. Anh em Hồ Tử không liên quan đến giao dịch trái phép, sau khi bị giáo dục, trở thành người quản lý của Đường Chính. Trong thời gian rảnh, Đường Chính truyền dạy võ thuật, và mọi người đều tin rằng công lý cuối cùng sẽ chiến thắng.</p>', 'Full', 1, 'single', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuqing Shi","avatar":""},{"name":"Li Chang-Hai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324221);
