INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-thanh-pho', 'Anh Hùng Thành Phố', 'Great Nobody', 'https://phimimg.com/upload/vod/20241220-1/01a549b47bd2bb3f70805a04273afbc7.jpg', 'https://phimimg.com/upload/vod/20241220-1/8f8cf5f3e022421589d650278dbed2d6.jpg', '<p>Bộ phim kể về ba người là Mã Lực, Hầu Cơ và Dương Tiếu Tiếu làm việc tại cùng một công ty năng lượng tái tạo. Cả ba vì mục đích riêng của mình mà bị cuốn vào cuộc tranh chấp giữa ông chủ Long Bách Xuyên và nhà đầu tư Kim tiên sinh. Mọi người đấu tranh kịch liệt quanh một viên pin siêu mạnh. Cuối cùng, Mã Lực và Dương Tiếu Tiếu trong tình thế nguy cấp đã cứu được Hầu Cơ và tìm lại chính mình.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Amber Kuo","avatar":""},{"name":"Liu Xun","avatar":""},{"name":"Yi Yunhe","avatar":""},{"name":"Yue Yang","avatar":""},{"name":"Li Chengru","avatar":""},{"name":"Cailun Huang","avatar":""},{"name":"Liu Yan","avatar":""},{"name":"Kun Liu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["市井英雄"]', 1784690324221);
