INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-thieu-tien', 'Không Thiếu Tiền', 'Not Short of Money', 'https://phimimg.com/upload/vod/20241220-1/7af63ba507844d2df59364aace19337c.jpg', 'https://phimimg.com/upload/vod/20241220-1/7cc8f5d3df8d428e150d1e035ce6645f.jpg', '<p>Nam chính Trịnh Đại Lỗi giả vờ trúng số để giữ vợ, nữ chính luôn theo đuổi vật chất, trách móc chồng. Khi đối mặt với sinh tử, cô mới nhận ra rằng tiền bạc không quan trọng, hạnh phúc gia đình, tình yêu thương và những ngày tháng bình dị, đầy đủ mới là điều cô thực sự muốn. Thế giới của người lớn phức tạp và không dễ dàng, chỉ những linh hồn có thể vượt qua cám dỗ và thử thách mới được gọi là trưởng thành.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Song Guanpeng","avatar":""},{"name":"Yang Shulin","avatar":""},{"name":"Cheng Ye","avatar":""},{"name":"Bi Chang","avatar":""},{"name":"Wen Song","avatar":""},{"name":"Tang Jianjun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Not Short of Money","It''s Not That Bad","不差钱"]', 1784690324221);
