INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-tan-long-mon-anh-hung-thuc-tinh', 'Khách Sạn Tân Long Môn: Anh Hùng Thức Tỉnh', 'The New Dragon Inn: Heroes Awakening', 'https://phimimg.com/upload/vod/20241220-1/3b9392abef2efd3f2f93e24037c26b3d.jpg', 'https://phimimg.com/upload/vod/20241220-1/fd33182a8c08357f7efbb1afc76d828e.jpg', '<p>Giữa triều Minh, thái giám nắm quyền, dân chúng lầm than khổ cực. Vì một thánh chỉ bí ẩn, tướng quân Đông Hải là Châu Hoài An hộ tống cô gái mồ côi Khúc Linh đến Khách sạn Long Môn trên đảo Long Môn, chờ đến lễ Trung Nguyên để giao người theo thánh chỉ. Tại Khách sạn Long Môn, giang hồ tụ hội, âm mưu ngầm trỗi dậy. Đông Xưởng và Tây Xưởng lần lượt ra tay, bà chủ Kim Khảm Ngọc nhiều lần thử lòng, sát thủ Khâu Mạc Ngôn lại khuấy động tình thế, khiến Châu Hoài An cảm thấy mục đích chuyến đi này ngày càng khó đoán. Khi lễ Trung Nguyên cận kề, lời nguyền máu truyền đời trên đảo Long Môn bất ngờ hé lộ bí mật về &quot;tiên dược&quot;. Phó Đốc chủ của Đông Xưởng, Phùng Đốc chủ, vì tham vọng đoạt được tiên dược đã sát hại Khúc Linh. Trước tình thế nguy cấp, Châu Hoài An sẽ chọn nghe theo tham vọng của Phùng Đốc chủ để bảo vệ danh dự gia tộc, hay giữ vững công lý trong lòng và dũng cảm chống lại cái ác? Một trận chiến sinh tử giữa chính nghĩa và tà ác bắt đầu.</p>', 'Full', 1, 'single', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leni Lan","avatar":""},{"name":"李子峰","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["신용문객잔","新龙门客栈之英雄觉醒"]', 1784690324221);
