INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-dai-hiep-nay-co-chut-nhat', 'Vị Đại Hiệp Này Có Chút Nhát', 'This Hero is a Bit Timid', 'https://phimimg.com/upload/vod/20241220-1/6dfe59c02c0da958a54b42bd6a1f90f3.jpg', 'https://phimimg.com/upload/vod/20241220-1/51225c7e16e77ccb3ecf03d2ceeeea9d.jpg', '<p>Vạn Tiểu Hoa là một hiệp khách giang hồ, nhưng nhát gan sợ chết. Khi trừ gian diệt ác... mục tiêu mà hắn lựa chọn đều là những kẻ già yếu, bệnh tật. Còn với những tên xấu xa có võ công hoặc tuổi tác ngang ngửa mình, vì lý do an toàn, hắn sẽ nhường cho những đại hiệp gan dạ khác xử lý. Mọi chuyện thay đổi khi hắn gặp được nữ hiệp tên Tô Mặc Yên, từ đó bước vào một hành trình đầy hiểm nguy và bất ngờ...</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Tao","avatar":""},{"name":"Erfan Aziz","avatar":""},{"name":"Yi Wen","avatar":""},{"name":"Liu Yujia","avatar":""},{"name":"Wu Chunyi","avatar":""},{"name":"Jiang Xiaolin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zhe Ge Da Xia You Dian Song","Sniper Hero","这个大侠有点怂"]', 1784690324221);
