INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-vao-tinh-yeu', 'Sa Vào Tình Yêu', 'Love Trap', 'https://phimimg.com/upload/vod/20241219-1/38993980f7cda1b7fc41539c5cdd7dcc.jpg', 'https://phimimg.com/upload/vod/20241219-1/e5f9d7f3475965b3c25dee6a2731fc22.jpg', '<p>Thành viên hội Phi Điểu tổ chức phản quân phiệt Khương Dao, để tiếp cận lấy được quân tình từ quân phiệt Nghiêm Huyền, ngụy trang thành vật trưng bày trong buổi đấu giá, ý đồ được Nghiêm Huyền đấu giá.Thấy mục tiêu sắp rơi vào bẫy, lại không ngờ vào lúc cạnh tranh giá, có một người thần bí ra giá cao đấu giá Khương Dao. Kế hoạch bị làm loạn, dưới ánh mắt của mọi người, người thần bí ngược sáng đi tới, Khương Dao mới phát hiện người đấu giá mình là tình vũ 5 năm trước Trì Nghiễn Chu! 5 năm không gặp, Trì Nghiễn Chu đã không còn tình cảm ngày trước, ngược lại tràn ngập hận thù với Khương Dao. Hóa ra, anh từng là một mục tiêu của hội Phi Điểu, Khương Dao du học trở về liền được trọn làm gián điệp, trong quá trình tiếp cận, hai người dần nảy sinh tình cảm. Vì đại cục, Khương Dao cuối cùng lựa chọn hoàn thành nhiệm vụ, lại gián tiếp gây ra cái chết của cha Trì. Trì Nghiễn Chu lại mất tích. Lâu ngày gặp lại, Trì Nghiễn Chu đã có quyền thế ngập trời, anh ta ôm trái tim báo thù, nghĩ hết mọi cách để giày vò sỉ nhục Khương Dao, làm loạn thế giới của Khương Dao, đồng thời sa vào đau khổ sâu hơn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yan Zixian","avatar":""},{"name":"Zhao Andi","avatar":""},{"name":"Lin Yadong","avatar":""},{"name":"Liu Xinnian","avatar":""},{"name":"Yan Junyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qing Xian","Limerence","情陷"]', 1784690324222);
