INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-tinh', 'Độc Tình', 'Love Is A Poison', 'https://phimimg.com/upload/vod/20240918-1/9acbaf48aa03773145410f8e4c9d03b9.jpg', 'https://phimimg.com/upload/vod/20240918-1/c982f3594301178c713372105502ec19.jpg', '<p>Shiba Ryouma (Hama Shogo) – một luật sư thiên tài, cậu vượt qua kì thi đầu vào trường luật với điểm số cao và là cộng tác viên trẻ tuổi nhất của một công ty luật lơn. Cậu làm cố vấn pháp lý cho rất nhiều khách hàng lớn. Một ngày nọ cậu gặp Haruto (Hyodo Katsumi) – một thiên tài lừa đảo bí ẩn tại quán bar. Sau đó Haruto đã ngỏ ý mời Ryouma làm công sự của mình. Ryouma, người lần đầu biết yêu đã dần dần phải lòng Haruto – một người rất giỏi chiều lòng đối phương và hết mình vì chủ nhân của mình bất chấp mọi nguy hiểm. Hai con người hoàn toàn trái ngược nhau lại tạo nên một bộ đôi bí mật cùng nhau giải quyết những vấn đề ly kì và cùng nhau đương đầu với cái ác.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shogo Hama","avatar":""},{"name":"Katsumi Hyodo","avatar":""},{"name":"Aoba Kawai","avatar":""},{"name":"中村育二","avatar":""},{"name":"Nose Rin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Doku Koi: Doku mo Sugireba Koi to Naru","Dokukoi: Doku mo Sugireba Koi to Naru","독연: 독도 지나치면 사랑이 된다","Love Is Like a Poison","毒恋～毒もすぎれば恋となる～"]', 1784690324222);
