INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-buc-man', 'Sau Bức Màn', 'Behind The Scenes', 'https://phimimg.com/upload/vod/20241214-1/e3ee0455d5c72da5920514eb39ba7120.jpg', 'https://phimimg.com/upload/vod/20241214-1/a68572442ae3c5c6bbbf6b6fbb37097a.jpg', '<p>Vào thời kỳ Dân quốc xảy ra một vụ cướp ngân hàng cực lớn trị giá 80 triệu tệ. Cha của Thành Như đã hy sinh trong vụ cướp này. Để điều tra nguyên nhân cái chết của cha, Thành Như cải trang thành một cô ca sĩ tại hộp đêm và tiếp cận Diêm Lương, chủ tịch thương hội. Trong quá trình đấu trí với Diêm Lương, tình cảm của hai người dần dần nảy sinh. Đồng thời, Thành Như phát hiện ra bí mật của chồng chưa cưới Trình Phong, những bí ẩn ngày càng nhiều.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Cận Đồng","avatar":""},{"name":"Hồ Bác Văn","avatar":""},{"name":"Chu Mân Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["幕后"]', 1784690324222);
