INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dieu-nho-be-ay', 'Những Điều Nhỏ Bé Ấy', 'Small Things Like These', 'https://phimimg.com/upload/vod/20241222-1/c555e07d11c93b2d0cbc703ae2175722.jpg', 'https://phimimg.com/upload/vod/20241222-1/b16f8547cc21aa88316b10d7f31cdfb2.jpg', '<p>Small Things Like These 2024 Lấy bối cảnh Giáng sinh năm 1985 tại thị trấn New Ross - Ireland, xoay quanh Bill Furlong một người cha tận tụy và là một thương nhân buôn bán than, củi. Anh là một người đàn ông trầm lặng, chăm chỉ, luôn cố gắng mang lại cuộc sống tốt đẹp cho vợ và năm cô con gái. Trong quá trình làm việc Bill dần khám phá ra những bí mật đen tối về Tu viện Magdalene trong thị trấn, nơi được điều hành bởi các nữ tu và là nơi cưu mang những phụ nữ trẻ &quot;lầm lỡ&quot;. Những phụ nữ này bị bóc lột sức lao động, bị đối xử tàn nhẫn và phải sống trong điều kiện khắc nghiệt. Bill vốn cũng từng trải qua tuổi thơ khó khăn khi là con của một người mẹ đơn thân, bị giằng xé giữa việc giữ im lặng để bảo vệ gia đình mình hay lên tiếng chống lại sự bất công đang diễn ra. Anh phải đối mặt với lương tâm và lựa chọn giữa sự an toàn của bản thân và trách nhiệm đạo đức với những người phụ nữ khốn khổ trong tu viện.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Michelle Fairley","avatar":""},{"name":"Eileen Walsh","avatar":""},{"name":"Zara Devlin","avatar":""},{"name":"Clare Dunne","avatar":""},{"name":"Helen Behan","avatar":""},{"name":"Ella Cannon","avatar":""},{"name":"Patrick Ryan","avatar":""},{"name":"Peter Claffey","avatar":""},{"name":"Ian O''Reilly","avatar":""},{"name":"Sarah Morris","avatar":""},{"name":"Cillian O''Gairbhi","avatar":""},{"name":"Tadhg Moloney","avatar":""},{"name":"Liadán Dunlea","avatar":""},{"name":"Giulia Doherty","avatar":""},{"name":"Rachel Ly","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kleine Dinge wie diese","דברים קטנים כאלה","Piccole cose come queste","Такі дрібниці","Pequenas Coisas Como Estas","Pequeñas cosas, grandes secretos","Bunun Kimi Balaca Şeylər","Takové maličkosti","Small Things Like These"]', 1784690324222);
