INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('maria', 'Maria', 'Maria', 'https://phimimg.com/upload/vod/20241222-1/fe26beba875c8afb0ff06d8c921501d2.jpg', 'https://phimimg.com/upload/vod/20241222-1/9fdcd6407f489023df2ab7e558303450.jpg', '<p>Những ngày cuối đời của Maria Callas, giọng ca opera vĩ đại nhất thế giới, được tái hiện tại Paris những năm 1970, khi bà đối diện với bản thân và cuộc đời.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Pierfrancesco Favino","avatar":""},{"name":"Alba Rohrwacher","avatar":""},{"name":"Haluk Bilginer","avatar":""},{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Stephen Ashfield","avatar":""},{"name":"Valeria Golino","avatar":""},{"name":"Caspar Phillipson","avatar":""},{"name":"Vincent Macaigne","avatar":""},{"name":"Aggelina Papadopoulou","avatar":""},{"name":"Erofili Panagiotarea","avatar":""},{"name":"Jörg Westphal","avatar":""},{"name":"Philipp Droste","avatar":""},{"name":"Alessandro Bressane","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["玛利亚","María Callas","Maria","Maria Callas Last Days"]', 1784690324222);
