INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buon-vui-cuoc-doi-can-thu', 'Buồn Vui Cuộc Đời Cần Thủ', 'Negative Positive Angler', 'https://phimimg.com/upload/vod/20241004-1/46c16ae33ee8508edb8f8b092deea0e4.jpg', 'https://phimimg.com/upload/vod/20241004-1/36373a84b28e6d9cc5f8826ea0af068d.jpg', '<p>Cuộc sống của Tsunehiro không hề dễ dàng. Sau khi bác sĩ cho anh ta sống được hai năm và những người đòi nợ đến gõ cửa, anh ta bị ngã từ trên cầu xuống. Trong khoảng thời gian ngắn, Hana và phi hành đoàn của cô đã phát hiện ra Tsunehiro và kéo anh đến nơi an toàn. Trước khi quay trở lại, họ thả neo ngoài khơi để câu cá và Tsunehiro bắt được một con cá vược khổng lồ nhờ sự may mắn của người mới bắt đầu. Khi tòa nhà chung cư của anh sụp đổ, cuộc sống mới của Tsunehiro bắt đầu mở ra!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"岩中睦樹","avatar":""},{"name":"ファイルーズあい","avatar":""},{"name":"石川界人","avatar":""},{"name":"土屋李央","avatar":""},{"name":"土田大","avatar":""},{"name":"菅原正志","avatar":""},{"name":"戸松遥","avatar":""},{"name":"広瀬裕也","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["悲喜渔生","Negapoji Angurā","เนกาโปจิ อังกูรา","เนกาโพซิแองเกลอร์","เนกาโปจิ แองเกลอ","悲喜漁生","NegaPosi Angler","ネガポジアングラー"]', 1784690324222);
