INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dont-give-up', 'DON''T GIVE UP', 'DON''T GIVE UP', 'https://phimimg.com/upload/vod/20240729-1/883190bca665a27c1832066a1e204860.jpg', 'https://phimimg.com/upload/vod/20240729-1/5337508e1f1f7366405388ccb2a2e26b.jpg', '<p>Men Ke, một nhân viên văn phòng và nô lệ của công ty, đã trải qua nửa đầu cuộc đời buồn chán đến mức đặt câu hỏi về sự tồn tại của mình. Tuy nhiên, trong nửa sau, cô phải đối mặt với một tình huống mà sự nhàm chán có thể giết chết cô theo đúng nghĩa đen. Hàng ngày, cô đối mặt với nguy cơ tử vong nhưng vẫn phải đi làm. Câu chuyện xoay quanh nữ anh hùng người Trái đất này và một anh hùng ngoài hành tinh nhiệt tình nhưng có phần kém cỏi muốn cứu cô. Cùng nhau, họ phải tìm cách vượt qua sự nhàm chán và sống với nụ cười!</p>', 'Tập 24', 24, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"賀文瀟","avatar":""},{"name":"Su Shangqing","avatar":""},{"name":"土豆","avatar":""},{"name":"金弦","avatar":""},{"name":"Fuzheng Zhang","avatar":""},{"name":"Chang Rongshan","avatar":""},{"name":"Qian Chen","avatar":""},{"name":"Xing Chao","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"劉琮","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324222);
