INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-cam', 'Vợ Câm', 'The Silent Wife', 'https://phimimg.com/upload/vod/20241205-1/c1e076139fb594bb13f96c331573d7be.jpg', 'https://phimimg.com/upload/vod/20241205-1/e5e559c3cb0980d1083148aa43a8ad9b.jpg', '<p>Giám đốc điều hành mất trí nhớ Thẩm Trì Yến coi người vợ câm Tống Thất Niên làm thư ký của mình, thậm chí còn sử dụng cô ấy làm gói máu dự phòng cho Bạch Nguyệt Quang. Tống Thất Niên có lời nói nên lời và cố gắng giúp Thẩm Trì Yến lấy lại trí nhớ nhưng không thành công. Bạch Nguyệt Quang tỉnh lại âm mưu phá hủy gia đình Tống Thất Niên. Dưới sự kích thích tan vỡ của tình yêu và cái chết của người thân, người vợ câm đã lên tiếng!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Teng Zewen","avatar":""},{"name":"Tian Xuning","avatar":""},{"name":"Liu Xinnian","avatar":""},{"name":"Tong Liang","avatar":""},{"name":"Wang Ruizi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["宋秘书别离职，沈总孤枕难眠了","아처: 벙어리 아내","The Silent Wife","哑妻"]', 1784690324222);
