INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoang-tu-rong-phan-7', 'Hoàng Tử Rồng (Phần 7)', 'The Dragon Prince (Season 7)', 'hoàng tử rồng (phần 7) the dragon prince (season 7) jack de sena paula burrows sasha rojen o príncipe dragão: o mistério de aaravos 龙王子 dračí princ der prinz der drachen drageprinsen el príncipe dragón lohikäärmeprinssi le prince des dragons ο πρίγκιπας δράκος princ zmajeva a sárkányherceg il principe dei draghi ドラゴン王子 드래곤 프린스 드래곤 프린스: 아라보스의 미스터리 smoczy książę o príncipe dragão принц-дракон drakprinsen ejderhalar prensi the dragon prince: mystery of aaravos the dragon prince', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-bong-chay-tai-xuat', 'Huyền Thoại Bóng Chày Tái Xuất', 'Oblivion Battery', 'https://phimimg.com/upload/vod/20241219-1/b0266a70fa20912513dd3507c4419f9f.jpg', 'https://phimimg.com/upload/vod/20241219-1/485bd23710ef76933b3ca4dacad4e2ac.jpg', '<p>Haruka Kiyomine - một tay ném bóng có kỹ thuật siêu đẳng, gần như bất bại, đặc biệt nổi tiếng trong thế giới bóng chày của trường cấp hai cùng với Kei Kaname - một tay bắt bóng nhạy bén với biệt danh &quot;Commander&quot;. Họ được biết đến là một cặp đôi &quot;Monster Battery&quot;. &nbsp;Các trường học trên khắp Nhật Bản với đội bóng chày mạnh đã cố gắng chiêu mộ hai người, nhưng vì lý do nào đó, họ lại đăng ký vào trường trung học Kotesashi - một ngôi trường hoàn toàn xa lạ trong thế giới bóng chày. &nbsp;Sự thật là Kei đã mất trí nhớ cùng với tất cả kiến thức về bóng chày. Nhập học trung học Kotesashi không chỉ có duy nhất cặp đôi này mà còn có một vài thiên tài khác, những người đã từng bị đánh bại bởi &quot;Monster Battery&quot; cũng đã tìm được đường đến trường… Một cuộc hội ngộ bất ngờ khiến họ lại tiếp tục hành động, và điều đó đánh dấu sự khởi đầu cho câu chuyện bóng chày ở trường trung học của họ!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiki Masuda","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Yoshitaka Yamaya","avatar":""},{"name":"Takeo Otsuka","avatar":""},{"name":"Mark Ishii","avatar":""},{"name":"Kengo Kawanishi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Bōkyaku Battery","Boukyaku Battery","Забвение бэттери","失憶投捕","忘却バッテリー"]', 1784690324222);
