INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-la-dai-luc-nhien-hon-chien', 'Đấu La Đại Lục: Nhiên Hồn Chiến', 'The Land Of Warriors', 'https://phimimg.com/upload/vod/20241126-1/ad517d9b9bcd7518ee4d034e9e0f20d3.jpg', 'https://phimimg.com/upload/vod/20241126-1/084de941871a9dfcda95c631fb1959d2.jpg', '<p>Sau trận chung kết cuộc thi tinh anh học viện hồn sư cao cấp toàn đại lục, Đường Tam cùng các đồng đội lưu luyến tạm biệt nhau, hẹn ước năm năm sau sẽ gặp lại, rồi mỗi người một ngả, bước vào hành trình riêng của cuộc đời. Đường Tam đi theo phụ thân là Đường Hạo đến khe núi ẩn mình để tu luyện đặc biệt, nâng cao năng lực. Với sự giúp đỡ của Đường Hạo, Đường Tam không chỉ tăng cường kinh nghiệm mà còn trở nên ngày càng chín chắn, có thể vững vàng đối mặt với nhiều thử thách hơn. Đới Mộc Bạch và Chu Trúc Thanh được gia tộc tán thành, trở thành thái tử và thái tử phi tương lai của Tinh La. Tiểu Áo và Ninh Vinh Vinh cũng bắt đầu quá trình rèn luyện khắc khổ để tăng cường thực lực còn Mã Hồng Tuấn thì ra ngoài học hỏi, nỗ lực mở mang tầm mắt. Tuy nhiên, vào lúc này, Bỉ Bỉ Đông của điện Võ Hồn lại âm thầm bày mưu, quét sạch các tông môn lớn, tham vọng thống trị đại lục Đấu La.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhou Yiran","avatar":""},{"name":"Zhang Yuxi","avatar":""},{"name":"Chen Muchi","avatar":""},{"name":"Kong Xueer","avatar":""},{"name":"Ding Jiayi","avatar":""},{"name":"Zhou Jingbo","avatar":""},{"name":"Cao Zishuo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name