INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('singham-tro-lai', 'Singham Trở Lại', 'Singham Again', 'https://phimimg.com/upload/vod/20241219-1/1159e0c58b8e98ec6b0e904867d463d2.jpg', 'https://phimimg.com/upload/vod/20241219-1/e4716f0bb7ad481e7b826fc03baef0fc.jpg', '<p>Một cuộc rượt đuổi mới lại bắt đầu – liên quan đến sử thi Ramayana, Singham và nhóm của anh phải đối mặt với một nhân vật phản diện mơ hồ để cứu vợ anh.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Ajay Devgn","avatar":""},{"name":"Kareena Kapoor Khan","avatar":""},{"name":"Deepika Padukone","avatar":""},{"name":"Tiger Shroff","avatar":""},{"name":"Ranveer Singh","avatar":""},{"name":"Akshay Kumar","avatar":""},{"name":"Arjun Kapoor","avatar":""},{"name":"Jackie Shroff","avatar":""},{"name":"Dayanand Shetty","avatar":""},{"name":"Shweta Tiwari","avatar":""},{"name":"Ravi Kishan","avatar":""},{"name":"Salman Khan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["دوباره سینگهام","सिंघम अगेन"]', 1784690324222);
