INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-co-cua-hoa-hong', 'Ván Cờ Của Hoa Hồng', 'Two Foxes', 'https://phimimg.com/upload/vod/20241219-1/2ee600fff2b24361c140a70df116c556.jpg', 'https://phimimg.com/upload/vod/20241219-1/111cef42e3313608dcf56861676f6e1f.jpg', '<p>Wang Xinyan, một giám đốc đầu tư tài giỏi, thâm nhập vào Tập đoàn Minglan với một mục đích bí mật: trả thù cho gia đình đã hủy hoại cuộc đời cô. Khi cô tìm kiếm công lý cho cái chết bi thảm của em trai mình, kế hoạch của cô có một bước ngoặt bất ngờ khi cô vướng vào một mạng lưới tình yêu và xung đột đầy sóng gió với người thừa kế của Tập đoàn Jin, Jin Yelei và chú của anh, Jin Xuyan.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cui Yiliang","avatar":""},{"name":"Cheng Yufeng","avatar":""},{"name":"Guo Xingye","avatar":""},{"name":"Ma Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["狐狸","Mei Gui De Qi Ju","狐狸啊","玫瑰的棋局"]', 1784690324222);
