INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nham-song-sinh', 'Yêu Nhầm Song Sinh', 'Misplacement', 'https://phimimg.com/upload/vod/20241211-1/72c55a1ce3e866982ea3fe88003e21f6.jpg', 'https://phimimg.com/upload/vod/20241211-1/df13904e8d261e5abfaabc63dd2116be.jpg', '<p>Ca nữ Thẩm Tri Thu vì muốn khám phá sự thật về việc bị chị gái bỏ rơi năm xưa nên đã lên kế hoạch tỉ mỉ để tiếp cận cậu chủ nhà họ Doãn. Tuy nhiên, cô lại vô tình phải đính hôn với cậu ba Doãn Hành của nhà họ Doãn. Ở một gia đình đầy nguy hiểm như nhà họ Doãn, Thẩm Tri Thu và chị gái cứu lấy nhau và giải quyết mọi hiểu lầm. Đồng thời, cô và Doãn Hành từ mối quan hệ lợi dụng lẫn nhau đã dần dần yêu nhau thật lòng. Cuối cùng, cả hai cùng bắt tay thực hiện một màn trả thù hoành tráng.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Pengyu","avatar":""},{"name":"Hong Yao","avatar":""},{"name":"Lu Siheng","avatar":""},{"name":"Yu Lang","avatar":""},{"name":"Huang Xiao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["错位","Misplacement","错爱双生"]', 1784690324222);
