INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-phai-ga-sep-xau-xa', 'Yêu Phải Gã Sếp Xấu Xa', 'Bad Guy My Boss', 'https://phimimg.com/upload/vod/20240916-1/c97676f090fa931aa0ce1d18d2b81f1e.jpg', 'https://phimimg.com/upload/vod/20240916-1/b4bb1f3daa0dd80b9666c0982f53ddec.jpg', '<p>Pat phải lòng ông chủ đa chủng tộc nghiêm khắc của mình tên là Eris. Tuy nhiên, với địa vị của họ, Pat chỉ có thể giữ bí mật tình cảm của mình, cố gắng duy trì mối quan hệ của họ với tư cách là sếp và trợ lý. Dù Pat đã đặt ra ranh giới nhưng Eris cũng không hề tạo điều kiện dễ dàng cho anh ấy. Đi theo anh khắp nơi và giữ chặt Pat để anh có thể ở bên cạnh anh giữa cuộc chiến kinh doanh trị giá hàng tỷ đô la, nơi các đối thủ cũng để mắt tới cô trợ lý trẻ. Eris phải rũ bỏ thái độ kiêu ngạo và rũ bỏ hình ảnh &#39;ông chủ tồi&#39;, không được người khác yêu mến, dù việc rũ bỏ con người cũ không dễ như cởi bỏ bộ đồ trợ lý!</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"James Prescott","avatar":""},{"name":"Kad Ploysupa","avatar":""},{"name":"Zax Nattapat Suthisawan","avatar":""},{"name":"Nick Gaksch","avatar":""},{"name":"Fam Thanuphat Poungsuwan","avatar":""},{"name":"Kin Anakin Nontiprasit","avatar":""},{"name":"Perth Napat Rueangchaisiwawet","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324222);
