INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lai-la-tui-bac-ba-phi', 'Lại Là Tui, Bác Ba Phi', 'It''s Me Again Uncle Ba Phi', 'https://phimimg.com/upload/vod/20241218-1/a84a574c50f89986629f09efa074d319.jpg', 'https://phimimg.com/upload/vod/20241218-1/402175c8b585da99b2cf582ee9c59c79.jpg', '<p>Lấy cảm hứng từ nguồn tư liệu phong phú trong dân gian, phim xoay quanh các câu chuyện dí dỏm được cường điệu hóa giữa bác Ba Phi và những người xung quanh. Qua đó, cuộc sống sinh hoạt thường ngày ở nông thôn miền Nam cũng được lột tả một cách đặc sắc.</p>', 'Hoàn Tất (103/103)', 103, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thanh Nam","avatar":""},{"name":"Tam Thanh","avatar":""},{"name":"Đào Vân Anh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Adventures on Orsum Island"]', 1784690324222);
