INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-thicha', 'Nàng Thicha', 'Thicha', 'https://phimimg.com/upload/vod/20241126-1/512db3cd7964f96821683bea3670614d.jpg', 'https://phimimg.com/upload/vod/20241126-1/7b249234f72b4ddc976e346d731c8137.jpg', '<p>Bị áp bức và đè nén bởi giai cấp cùng khoảng cách giàu nghèo, Thicha quyết định vùng lên trả thù để đòi lại công bằng. Câu chuyện đầy kịch tính hứa hẹn sẽ khiến khán giả nghẹt thở với diễn xuất ấn tượng của Baifern Pimchanok.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Baifern Pimchanok","avatar":""},{"name":"Peach Pachara","avatar":""},{"name":"Lukkade Metinee Kingpayome","avatar":""},{"name":"Tai Penpak Sirikul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bakit Kay Tagal ng Sandali?"]', 1784690324222);
