INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ngot-cam-ky', 'Mật Ngọt Cấm Kỵ', 'The Sweetest Taboo', 'https://phimimg.com/upload/vod/20241009-1/472e84b7d1ba9a13ba64ac53f8b9944c.jpg', 'https://phimimg.com/upload/vod/20241009-1/8fb216906dceea749ccf28de780213e8.jpg', '<p>Phim Mật Ngọt Cấm Kỵ kể về câu chuyện tình yêu giữa Phakamalin, một nữ doanh nhân tự phụ trên mạng, và Khatha, một sinh viên năm nhất đại học. Họ phải đối mặt với những khác biệt và thử thách khi Lin phát hiện ra rằng Khatha là con trai duy nhất của Rangsun, người đứng đầu đế chế kinh doanh mà cô từng bí mật ngoại tình. Trớ trêu thay, Kate - mẹ của Khatha và là vợ của Rangsun - cố gắng phá hoại mối quan hệ không chính thống của con trai với tình nhân của chồng. Tình yêu của Lin và Khatha sẽ được thử thách khi họ phải đối diện với những rắc rối trong cuộc sống gia đình và công việc. liệu họ có thể vượt qua mọi khó khăn để tìm được hạnh phúc cho bản thân?</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Peeranee Kongthai","avatar":""},{"name":"ไมกี้ ปณิธาน บุตรแก้ว","avatar":""},{"name":"Dom Haetrakul","avatar":""},{"name":"Marsha Vadhanapanich","avatar":""},{"name":"ธฤษณุ สรนันท์","avatar":""},{"name":"Yoghurt Nattasha Bunprachom","avatar":""},{"name":"Jennie Panhan","avatar":""},{"name":"Suriyont Arunwattanakul","avatar":""},{"name":"ธงชัย ทองกันทม","avatar":""},{"name":"เจนนิษฐ์ โอ่ประเสริฐ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Sweetest Taboo","หวานรักต้องห้าม"]', 1784690324222);
