INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-di-giao-2024', 'Kẻ Dị Giáo', 'Heretic', 'https://phimimg.com/upload/vod/20241216-1/ab241949bdb5187ac2b8a0119896b885.jpg', 'https://phimimg.com/upload/vod/20241216-1/4edd37c487ecdeedf5c74d957c6c2d5b.jpg', '<p>Heretic là một bộ phim tâm lý kinh dị của Mỹ năm 2024 do Scott Beck và Bryan Woods viết kịch bản và đạo diễn. Phim có sự tham gia của Sophie Thatcher và Chloe East trong vai hai nhà truyền giáo Mormon cố gắng cải đạo một người đàn ông ẩn dật nhưng nhận ra rằng anh ta nguy hiểm hơn vẻ ngoài của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Sophie Thatcher","avatar":""},{"name":"Chloe East","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Elle Young","avatar":""},{"name":"Julie Lynn-Mortensen","avatar":""},{"name":"Haylie Hansen","avatar":""},{"name":"Elle McKinnon","avatar":""},{"name":"Hanna Huffman","avatar":""},{"name":"Miguel Castillo","avatar":""},{"name":"Anesha Bailey","avatar":""},{"name":"Stephanie Lavigne","avatar":""},{"name":"Wendy Gorling","avatar":""},{"name":"River Codack","avatar":""},{"name":"Carolyn Adair","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hereje","مرتد","ملحد","异教徒","異教詭屋","異端者の家","Hérésie","Heretiku","Heretic"]', 1784690324222);
