INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nin-tho', 'Nín Thở', 'Hold Your Breath', 'https://phimimg.com/upload/vod/20241216-1/ea1f121e5cb00b1c4ec1874c21f24a82.jpg', 'https://phimimg.com/upload/vod/20241216-1/9312feac1a4ef1ec406499c9701b924a.jpg', '<p>Nín Thở là một bộ phim kinh dị tâm lý năm 2024, kể về Margaret Bellum, một người phụ nữ sống ở Oklahoma trong những năm 1930. Trong bối cảnh một cơn bão bụi tàn phá khu vực, Margaret phải đối mặt với những hiện tượng siêu nhiên đe dọa gia đình mình. Cô dần khám phá ra những điều kinh hoàng và đấu tranh để bảo vệ những người thân yêu, với sự kết hợp của yếu tố tâm lý và kinh dị đầy kịch tính. Bộ phim kết thúc với nhiều tình tiết bất ngờ, khiến khán giả phải suy nghĩ và hồi hộp đến phút cuối cùng.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Sarah Paulson","avatar":""},{"name":"Amiah Miller","avatar":""},{"name":"Annaleigh Ashford","avatar":""},{"name":"Alona Jane Robbins","avatar":""},{"name":"Ebon Moss-Bachrach","avatar":""},{"name":"Arron Shiver","avatar":""},{"name":"Bill Heck","avatar":""},{"name":"Frances Lee McCain","avatar":""},{"name":"Courtney Cunningham","avatar":""},{"name":"James Healy Jr.","avatar":""},{"name":"Nathan Gariety","avatar":""},{"name":"Ethan Woodall","avatar":""},{"name":"Hannah Mosqueda","avatar":""},{"name":"Emily Katherine Ford","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["نفستو نگه دار","نفست را حبس کن","Hold Your Breath"]', 1784690324222);
