INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-toi-la-hoc-sinh-tieu-hoc', 'Vợ Tôi Là Học Sinh Tiểu Học', 'TsumaSho', 'https://phimimg.com/upload/vod/20241109-1/e1ee3ca4773e42b8a514ecb7adc6ca63.jpg', 'https://phimimg.com/upload/vod/20241109-1/423481f0d9bd34518940442cb26d978f.jpg', '<p>Phim kể về câu chuyện gia đình đầy cảm động của Niijima Keisuke. Anh đã mất đi Takae - người vợ yêu quý trong một tai nạn xe hơi cách đây 10 năm. Kể từ đó, Keisuke sống trong đau khổ và trở nên u ám. Anh chỉ còn lại cô con gái duy nhất là Mai. Một ngày nọ, một cô bé xuất hiện và tự nhận mình là Takae tái sinh, kéo Keisuke và Mai vào cuộc hội ngộ kỳ diệu chưa từng có.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Yuuki","avatar":""},{"name":"Daisuke Hirakawa","avatar":""},{"name":"Maiko Nomura","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["妻子变成小学生","Tsuma, Shougakusei ni Naru.","If my wife becomes an elementary school student.","TsumaSho","妻子變成小學生","妻、小学生になる。"]', 1784690324222);
