INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-y', 'Như Ý', 'Ruyi', 'https://phimimg.com/upload/vod/20241215-1/e6b8def6baf076c72e9860f177822940.jpg', 'https://phimimg.com/upload/vod/20241215-1/ccb32521bcb985433aa687156296d371.jpg', '<p>Ye Ruyi bất ngờ được đưa vào truyện tranh với tư cách là một nhân vật phụ, cam chịu số phận, nơi cô gặp Zuo Qianchen, một hoàng tử sa ngã sống cuộc sống hai mặt như một anh hùng. Cùng nhau, họ chuyển từ thao túng lẫn nhau sang cứu chuộc, đánh thức các nhân vật khác và định hình lại số phận của họ để viết lại câu chuyện.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Zixuan","avatar":""},{"name":"Haodong Ma","avatar":""},{"name":"Xiang Hao","avatar":""},{"name":"Liu Yixin","avatar":""},{"name":"Yang Wanyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Ru Yi","如意"]', 1784690324222);
