INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-thien-tai-ban-thai', 'Bác Sĩ Thiên Tài (Bản Thái)', 'Good Doctor (Thailand Version)', 'https://phimimg.com/upload/vod/20241013-1/fe352509644075f779b675876355e490.jpg', 'https://phimimg.com/upload/vod/20241013-1/beed97462894998676294e314eb54339.jpg', '<p>Bác Sĩ Thiên Tài (Bản Thái) thuộc đề tài y khoa, xoay quanh cuộc sống của những bác sĩ trẻ nhiệt huyết với nhân vật trung tâm là một bác sĩ có bệnh tự kỷ. Từ nhỏ, Shone đã phải đối mặt với sự thành kiến của xã hội vì anh vừa mắc hội chứng bác học vừa bị bệnh tự kỷ. Dù vậy, Shone vẫn quyết tâm thực hiện ước mơ của cuộc đời mình là trở thành bác sĩ khoa nhi. Phim được làm từ bộ phim Hàn Quốc cùng tên, một tác phẩm truyền hình đã được nhiều nước trên thế giới chuyển thể lại.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Neng Sarun Naraprasertkul","avatar":""},{"name":"Pat Chayanit Chansangavej","avatar":""},{"name":"Toni Rakkaen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["诛仙青云志","Qing Yun Zhi","Zhu Xian Qing Yun Zhi","青云志","青云志 2","Zhu Xian","诛仙","青云志 第二季","诛仙青云志2","青云志Ⅱ","决战青云","青云志 第一季","誅仙青雲志","Noble Aspirations","Jade Dynasty"]', 1784690324222);
