INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-hon-nhan-ngoai-hon-nhan', 'Trong Hôn Nhân Ngoài Hôn Nhân', 'Married', 'https://phimimg.com/upload/vod/20241201-1/7a1a4352ed9d6cab30f5dcbf7c8f9270.jpg', 'https://phimimg.com/upload/vod/20241201-1/ee5b2df7a1cef778c78c783fc97f8e97.jpg', '<p>Từ một sự cố bất ngờ, luật sư công ích Ninh Duyệt bắt đầu nhận ra rằng cuộc sống sau hôn nhân ổn định và hạnh phúc của mình thực chất chỉ là bức màn do người chồng Hồ Thành tạo ra bằng sự dối trá và kiểm soát, được che phủ bằng &quot;chất gây tê&quot;.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"William Feng","avatar":""},{"name":"Cai Wenjing","avatar":""},{"name":"Xing Zhaolin","avatar":""},{"name":"Jia Naina","avatar":""},{"name":"Victor Huang","avatar":""},{"name":"Hu Jing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dentro e Fora do Casamento","Wo He Hun Yin De Zhan Dou","我和婚姻的战斗","My Battle with Marriage","Hun Nei Hun Wai","Married","婚内婚外"]', 1784690324222);
