INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-than-lenh', 'Tinh Thần Lệnh', 'Calling From The Galaxy', 'https://phimimg.com/upload/vod/20241201-1/eaa336b695ace68e32e5d9ccf7eeb2f0.jpg', 'https://phimimg.com/upload/vod/20241201-1/7f3ffb9a94e36e49eb34299153ed8801.jpg', '<p>Ở hai đầu sông Ngân Hà có hai vị Nam Đế và Bắc Đế sinh sống, cai quản sinh mệnh của vạn vật. Một ngày nọ, trong lúc đánh cờ, họ đã đánh cược, lấy tình yêu làm vật trung gian, kiếp nạn sinh tử làm điều kiện đánh cược rồi ném Bắc Đẩu Huyền Châu xuống phàm trần, trải qua ba kiếp tình duyên.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Tian Qi","avatar":""},{"name":"Zhang Chuhan","avatar":""},{"name":"Peng Biyao","avatar":""},{"name":"Lu Xuanle","avatar":""},{"name":"Zhu Danni","avatar":""},{"name":"He Yijun","avatar":""},{"name":"Yang Yunxi","avatar":""},{"name":"Yu Xuan Chen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Xing Chen Ling","星辰令"]', 1784690324222);
