INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('men-say-tinh-yeu', 'Men Say Tình Yêu', 'Brewing Love', 'https://phimimg.com/upload/vod/20241104-1/86e4894002928b08937ddd6fb891140e.jpg', 'https://phimimg.com/upload/vod/20241104-1/26e9a849cc1c17ead82dadbbca3d62a5.jpg', '<p>Chae Yong Joo, một cựu đặc nhiệm đầy nhiệt huyết, hiện là &quot;vua bán hàng&quot; của một công ty rượu. Cuộc sống của cô đảo lộn khi chi nhánh đứng trước nguy cơ đóng cửa. Nhiệm vụ của cô là bán loại bia đặc biệt của bậc thầy Yoon Min Joo, một người đàn ông sống ẩn dật. Sự xuất hiện của Yong Joo đã làm xáo trộn cuộc sống yên bình của anh.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Se Jeong","avatar":""},{"name":"Lee Jong Won","avatar":""},{"name":"Shin Do Hyun","avatar":""},{"name":"Baek Sung Chul","avatar":""},{"name":"Baek Hyun Joo","avatar":""},{"name":"Park Jee A","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["酒醉罗曼史","주의 이름으로","Juui Ileumeuro","Chwihaneun Lomaenseu","تخمير الحب","Brewing Love","Drunk Romance","In the Name of the Lord","취하는 로맨스"]', 1784690324222);
