INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('goi-toi-la-nhac-dong-que-beyonce-va-chuyen-luu-dien-renaissance-tai-nashville', 'Gọi Tôi Là Nhạc Đồng Quê Beyoncé Và Chuyến Lưu Diễn Renaissance Tại Nashville', 'Call Me Country: Beyoncé & Nashville''s Renaissance', 'gọi tôi là nhạc đồng quê beyoncé và chuyến lưu diễn renaissance tại nashville call me country: beyoncé & nashville''s renaissance rhiannon giddens john osborne t.j. osborne rissi palmer aaron vance denitia touré larisha paul chris molanphy kyle coroneos keith hill holly g. tanner d. country es mi nombre: beyoncé y el renacimiento de nashville call me country: beyoncé & nashville''s renaissance', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-vi-uong', 'Dạ Vị Ương', 'The Night is Still Young', 'https://phimimg.com/upload/vod/20241207-1/9a6b5eaa8a232568c8f5e75c7297e35e.jpg', 'https://phimimg.com/upload/vod/20241207-1/7ad36070556a0e2165c94a1d9a03025a.jpg', '<p>Hoàng thúc Dạ Bắc Trần, người có thể một tay che trời, thường xuyên đêm không thể ngủ, điên cuồng nghĩ về một người: Thượng Quan Vị Ương, thê tử của cháu trai ông. Ở kiếp trước, Dạ Bắc Trần định âm thầm bảo vệ nàng, nhưng lại nhận lấy kết cục là Thượng Quan Vị Ương một thân hồng y, mang oán hận tự bắt chết mình rồi rơi xuống tường thành. Thế là, trái tim ông như rơi xuống vực sâu không đáy, đau đớn không cam lòng, hối hận sự tác thành của bản thân. Vì thế, Dạ Bắc Trần, người điên cuồng vì tình yêu, không tiếc mạng sống, quyết tâm xoay chuyển tình thế, chỉ mong có cơ hội gặp lại nàng, yêu nàng một lần nữa! Ở kiếp này, Thượng Quan Vị Ương trùng sinh, nhưng lại bị kẻ thù kiếp trước là Dạ Bắc Trần cưỡng đoạt và kiểm soát ngang ngược. Không ai biết rằng, Dạ Bắc Trần trong kiếp này vì tình yêu mà trở nên điên dại, biến cháu dâu mình thành vợ ông.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ryan Zhang","avatar":""},{"name":"Vicky Liang","avatar":""},{"name":"Wang Junhao","avatar":""},{"name":"Deng Zhi Hao","avatar":""},{"name":"Zhang Kaiyue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["双世长思","夜未央"]', 1784690324222);
