INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-thua-ke-2', 'Quý Cô Thừa Kế 2', 'Quý Cô Thừa Kế 2', 'https://phimimg.com/upload/vod/20241209-1/72aa277a11a63a027741777de82b3fb4.jpg', 'https://phimimg.com/upload/vod/20241209-1/b617d0fec1bdae3203ef14dc9a4318ac.jpg', '<p>“Có mấy ông lắm tiền nhiều của, vợ bé con riêng, gia đình tan nát&quot;... Dần dần câu chuyện thật của giới thượng lưu ngàn tỷ được hé mở. Từ những buổi tiệc thác loạn, đến gia đình đại gia nhưng lộ ra là những bí mật &quot;dơ bẩn&quot; về một gia đình quyền quý… Quý Cô Thừa Kế 2 hứa hẹn sẽ tháo bỏ lớp mặt nạ hào nhoáng của thế giới thượng lưu để lộ ra một &quot;âm mưu vô cùng đen tối&quot;...</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Huy Khánh","avatar":""},{"name":"Hứa Minh Đạt","avatar":""},{"name":"Lâm Vĩ Dạ","avatar":""},{"name":"Trang Nhung","avatar":""},{"name":"Otis","avatar":""},{"name":"Quyên Qui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Quý Cô Thừa Kế 2"]', 1784690324222);
