INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-dac-biet', 'Tin Đặc Biệt', 'A Deadly Loop', 'https://phimimg.com/upload/vod/20241201-1/597b9d5b6176c1d40828ed849bdd1e8c.jpg', 'https://phimimg.com/upload/vod/20241201-1/dd56c9601fc0bcbd5e2ee237fb3981c1.jpg', '<p>Khi ngày cưới đến gần, cô dâu Lưu Tĩnh Chi bị giết tại nhà. Chồng sắp cưới của doanh nhân giàu có Phương Học Văn bị buộc tội oan là kẻ sát nhân và chết một cách bi thảm trong một vụ nổ súng ngẫu nhiên. Một cơn đau nhói đã đánh thức anh và anh bất ngờ thấy mình bị mắc kẹt trong một vòng lặp. Du hành xuyên thời gian và tái sinh vô hạn, Phương Học Văn thề sẽ tìm ra sự thật đằng sau cái chết bi thảm của vợ mình và thay đổi kết cục cái chết oan uổng của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Peng Chuyue","avatar":""},{"name":"Xiao Yu","avatar":""},{"name":"Liu Minghao","avatar":""},{"name":"Wu Bowei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hao Wai! Hao Wai!","号外！号外！"]', 1784690324222);
