INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-tuoc-cac', 'Đồng Tước Các', 'My Contractual Husband', 'https://phimimg.com/upload/vod/20241202-1/eead4230df61b4c696cc5e63b3e4736e.jpg', 'https://phimimg.com/upload/vod/20241202-1/eefd6d96245208aaeb6188ddb743828f.jpg', '<p>Cố Bình An đến Tiền Đường điều tra vụ án bí ẩn mà cha mình để lại, tình cờ gặp Tống Thi Nhụy đang đau đầu vì phải đóng &quot;thuế độc thân&quot;. Hai người giả làm vợ chồng mở tửu lâu, trong quá trình hợp tác khởi nghiệp đã nảy sinh tình cảm với nhau, chung tay chiến thắng trong cuộc chiến kinh doanh tửu lâu, còn khui ra thế lực đen tối đang chiếm giữ Tiền Đường, rửa sạch án oan của cha Cố Bình An.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Ze","avatar":""},{"name":"Hana Lin","avatar":""},{"name":"Li Ze","avatar":""},{"name":"Yang Junhan","avatar":""},{"name":"Xie Yibo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["銅雀閣","铜雀阁"]', 1784690324222);
