INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-nay-that-khong-hoan-hao', 'Thế Giới Này Thật Không Hoàn Hảo', 'Quality Assurance In Another World', 'https://phimimg.com/upload/vod/20241209-1/3d4b88fc95804afc830992bb91b366b3.jpg', 'https://phimimg.com/upload/vod/20241209-1/4485af50b935aa263d1db0bf3c3aa261.jpg', '<p>Phía nam lục địa Fernark, đảo Clayborne vẫn luôn náo nhiệt với 5 quốc gia nhỏ và những cuộc xung đột không hồi kết. Trong số đó, vương quốc Bayle là nơi nhỏ bé và yên bình nhất. Tại một ngôi làng hẻo lánh của vương quốc này, cô gái Nicola đang sống một cuộc đời bình dị. Một ngày nọ, cô bất ngờ chạm trán với một con rồng khổng lồ - vốn chỉ sinh sống tận sâu trong núi. Ngay khi ngôi làng sắp bị tấn công, một người đàn ông tên Haga xuất hiện, tự xưng là một trong những King Seeker trên Thế giới đang thực hiện công việc quan sát rồng. Nicola vốn chưa từng cảm thấy chán ngán cuộc sống yên bình hàng ngày, bỗng nảy sinh lòng ngưỡng mộ Haga và mong muốn được bước ra thế giới bên ngoài. Và rồi, cô sẽ khám phá ra bộ mặt thật của thế giới này!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaito Ishikawa","avatar":""},{"name":"Hinaki Yano","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["这个世界漏洞百出","Kono Sekai wa Fukanzen Sugiru","この世界は不完全すぎる"]', 1784690324222);
