INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hon-nhat-nhoa', 'Hoàng Hôn Nhạt Nhòa', 'Twilight Out Of Focus', 'https://phimimg.com/upload/vod/20241209-1/045d859471f4fe6aadf336c8f7f7fc4b.jpg', 'https://phimimg.com/upload/vod/20241209-1/f2d95dc3ef2b06323f4a56d85d1251bd.jpg', '<p>Tsuchiya Mao và Ootomo Hisashi đã thỏa thuận với nhau 3 điều:

1. Mao sẽ không tiết lộ bí mật của Hisashi rằng cậu ấy là gay và đã có bạn trai.

2. Hisashi sẽ không coi Mao là gay và trở thành đối tượng của cậu.

3. Khi về đến ký túc xá phải luôn gõ cửa để không làm phiền những lúc riêng tư của nhau.

Cứ tưởng rằng với những điều đã thỏa thuận, cả 2 sẽ đảm bảo bình yên khi ở chung phòng ký túc xá, nhưng...LỜI HỨA GIÓ BAY. Liệu mối quan hệ ấy sẽ đi đến đâu!?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Soma Saito","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Masatomo Nakazawa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["黄昏失焦","Tasogare Out Focus","Tasogare Outfocus","รักนอกสายตา","เอาต์ โฟกัส รักนอกสายตา","黄昏アウトフォーカス"]', 1784690324222);
