INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jentry-chau-doi-dau-the-gioi-ngam', 'Jentry Chau Đối Đầu Thế Giới Ngầm', 'Jentry Chau Vs The Underworld', 'https://phimimg.com/upload/vod/20241208-1/eaa8eb5491c6937a527d7bd32e66a574.jpg', 'https://phimimg.com/upload/vod/20241208-1/e7149122e567f68f8884f7efd1e4ccc0.jpg', '<p>Sắp đến sinh nhật 16 tuổi, thiếu nữ không hề tầm thường nọ tìm lại sức mạnh phóng lửa mà cô kìm nén bấy lâu nay và phải đối mặt với những ác quỷ của mình – theo đúng nghĩa đen.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ali Wong","avatar":""},{"name":"Lori Tan Chinn","avatar":""},{"name":"Bowen Yang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Джентри Чау против демонов","Jentry Chau vs the Underworld"]', 1784690324222);
