INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-xua-bien-thuy', 'Chuyện Xưa Biên Thủy', 'Escape from the Trilateral Slopes', 'https://phimimg.com/upload/vod/20240818-1/a7a9367acec689c8cd0d4c4f828acb8f.jpg', 'https://phimimg.com/upload/vod/20240818-1/249350c4c2263986237d76218c2a6c16.jpg', '<p>Sanbianpo là khu vực có khí hậu nhiệt đới gió mùa, nơi người tốt và người xấu trộn lẫn, khoảng cách giàu nghèo rất lớn. Shen Xing, người mới gia nhập xã hội và đang làm việc khắp nơi để kiếm sống, vô tình đến Sanbianpo. Tình cờ, Shen Xing gặp chú Cai, một người hòa giải có mối quan hệ tốt với cả thế giới đen và trắng của Sanbianpo.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Vưu Dũng","avatar":""},{"name":"Giang Cơ Lâm","avatar":""},{"name":"Châu Chính Kiệt","avatar":""},{"name":"Cam Quân Thần","avatar":""},{"name":"Tống Gia Đằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324222);
