INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-lung-co-ay-truoc-mat-toi', 'Sau Lưng Cô Ấy, Trước Mắt Tôi', 'She Behind, I Before', 'https://phimimg.com/upload/vod/20241204-1/7efdef8a895fa8a848eb7c1344699efe.jpg', 'https://phimimg.com/upload/vod/20241204-1/3f4387301d2a33f88a8fb162fcb72774.jpg', '<p>Khi ngày cưới đến gần, cô dâu Lưu Tĩnh Chi bị giết tại nhà. Chồng sắp cưới của doanh nhân giàu có Phương Học Văn bị buộc tội oan là kẻ sát nhân và chết một cách bi thảm trong một vụ nổ súng ngẫu nhiên. Một cơn đau nhói đã đánh thức anh và anh bất ngờ thấy mình bị mắc kẹt trong một vòng lặp. Du hành xuyên thời gian và tái sinh vô hạn, Phương Học Văn thề sẽ tìm ra sự thật đằng sau cái chết bi thảm của vợ mình và thay đổi kết cục cái chết oan uổng của mình.</p>', 'Tập 18', 18, 'series', 'ongoing', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mịch Nhĩ","avatar":""},{"name":"Trạch Nam","avatar":""},{"name":"Bách Trình Tuấn","avatar":""},{"name":"Lưu Nhuế Kiều","avatar":""},{"name":"Lý Viêm Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["背后的她眼前的我","Bei Hou De Ta, Yan Qian De Wo","背后的她，眼前的我"]', 1784690324222);
