INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-xui-xeo-va-anh-chang-may-man', 'Cô Nàng Xui Xẻo Và Anh Chàng May Mắn', 'Misfortune Miss and Lucky Mr', 'https://phimimg.com/upload/vod/20241204-1/c4b8f7f0bd7380df895572f123e41cce.jpg', 'https://phimimg.com/upload/vod/20241204-1/ab0e11b8e6b358a036733ae924ec0259.jpg', '<p>Tiểu Khưu, biên tập viên của nhà xuất bản vừa mới đánh giá một cuốn tiểu thuyết Mary Sue siêu sốc. Trong buổi họp kiểm duyệt đã trực tiếp đưa ra kết luận &quot;không duyệt&quot;. Thế nhưng, cô ngủ thiếp đi trong tủ quần áo của mình, khi tỉnh dậy lại bước vào một thế giới khác. Sau vài lần tìm hiểu, cô nhận ra mình đã xuyên không vào cuốn tiểu thuyết mà chính mình đã &quot;khai tử&quot;, còn trở thành nữ phụ xui xẻo nhất - Thẩm Thanh Ca! Mặc dù cô có lợi thế của tác giả, có thể nhìn thấy chỉ số may mắn của tất cả mọi người, nhưng chỉ số may mắn của bản thân lại thấp đến đáng thương, chuyện xui xẻo gì cũng ập tới cô. Hệ thống của tiểu thuyết gợi ý, chỉ khi tiếp cận nam chính may mắn Cố Dịch Thần thì chỉ số may mắn của cô mới được cải thiện, mới có cơ hội xuyên không về nhà.</p>', 'Tập 20', 20, 'series', 'ongoing', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hàm","avatar":""},{"name":"Dương Hân Kha","avatar":""},{"name":"Ngô Thuần Nhất","avatar":""},{"name":"Tưởng Hân Kỳ","avatar":""},{"name":"Cốc Nhạc Thần","avatar":""},{"name":"Từ Nghệ Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["倒霉小姐与幸运先生"]', 1784690324222);
