INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('elyas', 'Elyas', 'Elyas', 'https://phimimg.com/upload/vod/20241208-1/adbe0908f39f6494b7b673649b77ab25.jpg', 'https://phimimg.com/upload/vod/20241208-1/8f2eed3d37ba02e4e6d200ac861dff2b.jpg', '<p>Phim kể về Elyas Flores, một cựu chiến binh Lực lượng Đặc biệt đang đối mặt với những ám ảnh sau một nhiệm vụ ở Afghanistan. Anh được giao nhiệm vụ bảo vệ Amina và con gái Nour, khi họ tới nghỉ phép từ Trung Đông.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Roschdy Zem","avatar":""},{"name":"Laëtitia Eïdo","avatar":""},{"name":"Nabil Elouahabi","avatar":""},{"name":"Sherwan Haji","avatar":""},{"name":"Dimitri Storoge","avatar":""},{"name":"Jeanne Michel","avatar":""},{"name":"Frédéric Maranber","avatar":""},{"name":"Aguibou Ba","avatar":""},{"name":"Leonid Glushchenko","avatar":""},{"name":"Toussaint Martinetti","avatar":""},{"name":"Olivia Bonamy","avatar":""},{"name":"Sième Miladi","avatar":""},{"name":"Randa Berrouba-Tani","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["伊利亚斯","埃利亚斯","Elyas"]', 1784690324222);
