INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-thu-va-bao-dom-den', 'Mùa Thu Và Báo Đốm Đen', 'Autumn And The Black Jaguar', 'https://phimimg.com/upload/vod/20241208-1/e9bf5069ef34e87296d3305f3594a9cd.jpg', 'https://phimimg.com/upload/vod/20241208-1/116271ac663a342470c9cec357d808a5.jpg', '<p>Lớn lên trong rừng nhiệt đới Amazon, Autumn sống cùng Hope, chú báo đốm dễ thương mà cô nhận nuôi. Tuy nhiên, một hoàn cảnh buộc Autumn phải quay trở lại New York. Autumn quay trở lại rừng rậm để cứu Hope khỏi mối nguy hiểm nghiêm trọng.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Lumi Pollack","avatar":""},{"name":"Emily Bett Rickards","avatar":""},{"name":"Wayne Charles Baker","avatar":""},{"name":"Paul Greene","avatar":""},{"name":"Kelly Hope Taylor","avatar":""},{"name":"Lucrezia Pini","avatar":""},{"name":"Letitia Brookes","avatar":""},{"name":"K.C. Coombs","avatar":""},{"name":"Airam Camacho","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Jaguar My Love","Emma ja must jaaguar","Le Dernier Jaguar"]', 1784690324222);
