INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-chut-my-vi', 'Thiếu Chút Mỹ Vị', 'Almost Delicious', 'https://phimimg.com/upload/vod/20241128-1/2f24b3cdf1f48f7e387186b2abe66eca.jpg', 'https://phimimg.com/upload/vod/20241128-1/2342c3dabef3a3d31bd29d477411c406.jpg', '<p>Phương Mông, người mắc chứng rối loạn vị giác từ nhỏ, sau khi bố qua đời đã tiếp quản nhà hàng Hoa Tố đang trên bờ vực phá sản. Dưới sự giúp đỡ của Thư Chính Ngôn, cô không ngừng thử sức và nỗ lực. Từ một tay gà mờ chỉ biết làm những món ăn thảm họa, cuối cùng đã lội ngược dòng thành công, phát triển Hoa Tố thành nhà hàng tiêu biểu nhất thành phố, và cùng Thư Chính Ngôn tận hưởng cuộc sống sau muôn vàn khó khăn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Qing","avatar":""},{"name":"Li Mingjun","avatar":""},{"name":"Anson Chen","avatar":""},{"name":"Wang Xiaoshi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Near Lie","差一分的谎言","差一分的美味"]', 1784690324222);
