INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-dung-cam-vo-ich', 'Lòng Dũng Cảm Vô Ích', 'Later, I Laughed', 'https://phimimg.com/upload/vod/20241124-1/d58fdccec18439ddf13c623c4346fd72.jpg', 'https://phimimg.com/upload/vod/20241124-1/b8ebeda31c38ec9861f875c9ce3844a0.jpg', '<p>Bộ phim kể về mối duyên phận &quot;talk show&quot; giữa Ngô Tú Nhã, &quot;cô gái mê chương trình Thực Tập Sinh Thần Tượng&quot; thời nay với người bạn Sử Dã từ hồi cấp ba. Nhiều năm sau, Ngô Tú Nhã có vẻ có một sự nghiệp ổn định và một người bạn trai có chí tiến thủ, nhưng cô không hề hài lòng với cuộc sống của mình. Tất cả mọi thứ của cô đều nghe theo sắp xếp, đặt đâu ngồi đấy của người khác, gò ép bản thân, quen với cuộc sống cả nể để lấy lòng người khác. Tình cờ, Ngô Tú Nhã gặp lại Sử Dã, chính thức tiếp cận với lĩnh vực talk show, từ đó cô đã tìm ra sân khấu có thể trực tiếp thể hiện bản thân, bắt đầu câu chuyện không ngừng theo đuổi đam mê, dũng cảm thay đổi, sống một cuộc sống của chính mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Gengxi","avatar":""},{"name":"Wei Daxun","avatar":""},{"name":"Wang Hao","avatar":""},{"name":"Xu Mengjie","avatar":""},{"name":"Ding Guan Sen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Later I Laughed","不讨好的勇气"]', 1784690324222);
