INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-lau-4', 'Án Mạng Lầu 4', 'Impermanent Residents', 'https://phimimg.com/upload/vod/20241207-1/388d7627b52943b9d3ed3161d832b543.jpg', 'https://phimimg.com/upload/vod/20241207-1/e3c8247f7c3a940b5051d793b9365eb7.jpg', '<p>Nhận trông giúp đứa trẻ sơ sinh nhà hàng xóm, đôi vợ chồng trẻ bỗng phát hiện đứa bé đã chết từ lúc nào. Cả hai phải căng não thoát khỏi tình huống nghiệt ngã, đồng thời tìm ra thủ phạm thực sự.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Trương Thế Vinh","avatar":""},{"name":"Lương Bích Hữu","avatar":""},{"name":"Blacka","avatar":""},{"name":"Kiều Trinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Án Mạng Lầu 4"]', 1784690324222);
