INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-hoan-khong-de-choc', 'Nha Hoàn Không Dễ Chọc', 'Popeyete & Cute Master', 'https://phimimg.com/upload/vod/20241207-1/c3fb42a587c42c72662510111b0fdc9a.jpg', 'https://phimimg.com/upload/vod/20241207-1/28088a507d2a7070c5bd087fe0e7b941.jpg', '<p>Kua Xiao&#39;e là một người phụ nữ kỳ lạ cứng rắn với sức mạnh ma thuật có thể hạ gục mọi người chỉ bằng một cái tát. Danh tính thực sự của cô là hậu duệ của Hercules Kua&#39;e. Shen Wang, người giàu nhất keo kiệt ở thành phố Sun Yao, liên tục bị ám sát bởi những nhân vật bí ẩn. Anh ta vô tình nhìn thấy sức mạnh ma thuật của Kua Xiao&#39;e và lừa cô chiêu mộ cô vào Shen Mansion để trở thành người giúp việc và vệ sĩ riêng của anh ta. Cả hai từ chỗ là kẻ thù vui vẻ, thường xuyên gặp hoàn cảnh trở thành dần dần phát triển mối quan hệ tốt đẹp. Sau đó, ma lực của Xiao&#39;e thất bại do tính toán của người đàn ông mặc đồ đen. Ngụy Trung, kẻ chủ mưu đứng sau đã giăng bẫy bắt cóc cô. Thẩm Vương liều mạng cứu Kua Xiao&#39;e. Sức mạnh siêu nhiên của Xiao&#39;e được phục hồi một lần nữa và cô đã khuất phục thành công kẻ chủ mưu Wei Zhong. Kua Xiao&#39;e và Shen Wang cuối cùng cũng kết hôn.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qiyu Lin","avatar":""},{"name":"Meng En","avatar":""},{"name":"Zong Mu Yi","avatar":""},{"name":"Chen Zhuo","avatar":""},{"name":"Dongfang Jun","avatar":""},{"name":"Chai Lu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["丫鬟不好惹","Popeyete & Cute Master"]', 1784690324222);
