INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tau-son', 'Tẩu Sơn', 'Mountains', 'https://phimimg.com/upload/vod/20241126-1/b1126f8a5c8b3cbbc1c807591eff0e07.jpg', 'https://phimimg.com/upload/vod/20241126-1/d92b75dcd97bd529116324b057e122aa.jpg', '<p>Người đi núi - Trương Bắc Thần, Đoàn Tư Ngôn võ công cao cường, hậu duệ Quỷ Y - Vệ Linh Nhi và Bắc Mã Mã Thiên Hồng cùng lên đường tìm kiếm sự thật biến cố Kim Ô. Cả chặng đường họ đã trải qua và phá giải rất nhiều chuyện kỳ quái, nhìn thấy rõ được tham, sân, si, hận của thế gian, cũng cảm nhận được tình cảm quý giá giữa người với người.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cảnh Nghiệp Đình","avatar":""},{"name":"Đinh Nhiên","avatar":""},{"name":"Lưu Bác","avatar":""},{"name":"Ô Nhật Lệ Cách","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Zou Shan","走山怪谈簿","Zou Shan Guai Tan Bu","走山"]', 1784690324222);
