INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vay-ham-tai-dai-bac', 'Vây Hãm Tại Đài Bắc', 'Weekend In Taipei', 'https://phimimg.com/upload/vod/20241205-1/0492f30096e5197407394c7475bd4817.jpg', 'https://phimimg.com/upload/vod/20241205-1/50a3901fe262c8e2560f927fc19eae1c.jpg', '<p>Theo chân John Lawlor là một đặc vụ DEA cừ khôi bất khả chiến bại, anh sẽ không tiếc hi sinh bất cứ điều gì để hoàn thành nhiệm vụ được giao.Trong khi đó, Joey Kwang là &quot;người vận chuyển&quot; hàng đầu ở Đài Bắc với tốc độ không ai sánh bằng và tư duy nhạy bén mà không ai có thể theo kịp cô. Vô tình số phận đã đưa họ đến với nhau trước khi thế lực tội phạm chia cắt họ.15 năm sau, số phận một lần nữa đẩy Joey và John va chạm nhau trong tình cảnh bất đắc dĩ vào cuối tuần tại Đài Bắc. Và cả hai sẽ khám phá ra rằng điều duy nhất khó hơn việc yêu… chính là yêu lại.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Luke Evans","avatar":""},{"name":"Gwei Lun-mei","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Wyatt Yang","avatar":""},{"name":"Pernell Walker","avatar":""},{"name":"Zach Ireland","avatar":""},{"name":"Patrick Lee","avatar":""},{"name":"Virginia Chien","avatar":""},{"name":"Lu Yi-ching","avatar":""},{"name":"Tou Tsung-Hua","avatar":""},{"name":"Tjarret Yong","avatar":""},{"name":"Erin Adele Clark","avatar":""},{"name":"Janet Hsieh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["週末在台北","סופ\"ש בטאיפיי","آخر هفته در تایپه","Weekend Escape Project","周末狂飙","台北追緝令","The Weekend Escape","Escape explosivo","Escape Explosivo","Weekend in Taipei"]', 1784690324223);
