INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-mo-vi-uong', 'Trường Mộ Vị Ương', 'Love Endures Eternally', 'https://phimimg.com/upload/vod/20241201-1/4978572f99da1fc1c4e3f5e75e149446.jpg', 'https://phimimg.com/upload/vod/20241201-1/157247d62858efeef2d4eb0b013dff5a.jpg', '<p>Người xuyên không Trì Nguyên vốn tưởng rằng đây là một nhiệm vụ tình yêu ngọt ngào, nhưng không ngờ với tư cách là một hộ vệ, cô lại bị cuốn vào kế hoạch trả thù của Thẩm Chiêu Mộ. Để đảm bảo hoàn thành xuất sắc nhiệm vụ kép &quot;tình yêu&quot; và &quot;trả thù&quot;, cả hai đã trải qua nhiều gian nan và cuối cùng đã giành được tình yêu đích thực!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Huan","avatar":""},{"name":"Chen Ziyou","avatar":""},{"name":"Li Xiwen","avatar":""},{"name":"Li Weihao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["长慕未央"]', 1784690324223);
