INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiep-chuyen-sinh-ngot-ngao', 'Kiếp Chuyển Sinh Ngọt Ngào', 'Sweet Reincarnation', 'https://phimimg.com/upload/vod/20241205-1/f9ce2091ed6ef1492d9bf9744720c230.jpg', 'https://phimimg.com/upload/vod/20241205-1/7f221bfa7055ac5b47797a3c6d44e3c2.jpg', '<p>Một quý tộc nghèo quản lý một thái ấp nghèo, nơi có một cậu bé được sinh ra. Cậu bé sẽ trở thành lãnh chúa tiếp theo - Pais. Pais, người có một tài năng hiếm có, đã có mục tiêu trở thành một đầu bếp bánh ngọt ở kiếp trước.

Đối mặt với những tên trộm tấn công tàn nhẫn, những con thú đột ngột nhe nanh, và những quý tộc xảo quyệt phản bội, cậu bé phải đối mặt với tình trạng thiếu nước và lãnh thổ cằn cỗi cũng như vô số khó khăn và thử thách.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Hiroshi Tsuchida","avatar":""},{"name":"Hitomi Nabatame","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Kaya Okuno","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Natsumi Fujiwara","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["甜点转生：最强甜点师降临异世界","Okashi na Tensei: Saikyou Patishie Isekai Kourin","Okashi na Tensei","Kiếp Chuyển Sinh Ngọt Ngào","おかしな転生"]', 1784690324223);
