INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kiep-chuyen-sinh-ngot-ngao', 'Kiếp Chuyển Sinh Ngọt Ngào', 'Sweet Reincarnation', 'kiếp chuyển sinh ngọt ngào sweet reincarnation ayumu murase hiroshi tsuchida hitomi nabatame kaede hondo kaya okuno maaya uchida natsumi fujiwara 甜点转生：最强甜点师降临异世界 okashi na tensei: saikyou patishie isekai kourin okashi na tensei kiếp chuyển sinh ngọt ngào おかしな転生', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tu-nhu-ngoc', 'Quân Tử Như Ngọc', 'Pretty Boy', 'https://phimimg.com/upload/vod/20241130-1/31f34e219462f1a13fdddf8ab9cd5d07.jpg', 'https://phimimg.com/upload/vod/20241130-1/22db6ff3a6fa2f85b33d3c0965510f4d.jpg', '<p>Bộ phim này kể về câu chuyện của Thanh Thái, con trai tiên vương (Quan Hồng thủ vai), người đã mai danh ẩn tích sống một cuộc sống yên bình ở một thị trấn nhỏ để tránh xa tranh đấu trong triều đình. Cho đến khi cha nuôi Hàn Trung gặp nguy hiểm, Thanh Thái đành phải cải trang thành nữ để cứu cha nuôi và lẻn vào Minh Di sơn trang, nơi chỉ nhận nữ đệ tử, gặp phải Cam Bồ (Trịnh Hợp Huệ Tử thủ vai), cô nhi dòng họ Mạc Môn đến báo thù, và những nhân vật có mục đích và thân phận khác như Vương Dật Thiếu (Chu Tán Cẩm thủ vai), Hàn Ngải Chân (Vương Tử Giáp thủ vai), Cao Âm (Khương Mộng Hiên thủ vai), Hồ Kiều (Doãn Tây Hi thủ vai), v.v.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Darren Chen","avatar":""},{"name":"Zheng Hehuizi","avatar":""},{"name":"Zhu Zanjin","avatar":""},{"name":"Wang Zijia","avatar":""},{"name":"Michelle Jiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Beautiful Boy","君子如玉"]', 1784690324223);
