INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luyen-luyen-hoa-nhan-ngu-bo', 'Luyến Luyến Hoa Nhan Ngự Bổ', 'Choose One of Four', 'https://phimimg.com/upload/vod/20241201-1/3d6bbef9777dc93706468df1677eb8e8.jpg', 'https://phimimg.com/upload/vod/20241201-1/8c783b621d55dafd1ff8f6de00b4996e.jpg', '<p>Lâm Lộc Sênh, một cô gái trẻ vô tình xuyên không bước vào thế giới truyện tranh nổi tiếng, và vô tình gặp phải bốn mỹ nam ngự bổ. Du hành xuyên thời không, xuyên qua giữa cổ đại và hiện đại, cô hợp tác với các ngự bổ để xử lý các vụ án, cùng nhau vượt qua nguy hiểm và dũng cảm tiến về phía trước. Cô không chỉ nhiều lần xử lý các vụ án kỳ lạ mà còn chiếm được trái tim các mỹ nam. Cuối cùng là ai đã cùng cô ấy thành đôi?</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sissi Bao","avatar":""},{"name":"Xu Haoxiang","avatar":""},{"name":"Liu Runming","avatar":""},{"name":"Shi Wei","avatar":""},{"name":"Wang Yukai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["戀戀花顏御捕","恋恋花颜御捕"]', 1784690324223);
