INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-sac-nguyet-quang', 'Hắc Sắc Nguyệt Quang', 'Darkside Of The Moon', 'https://phimimg.com/upload/vod/20241127-1/83ae85a2ef3a378d756ca6e79af9344b.jpg', 'https://phimimg.com/upload/vod/20241030-1/99a35df46ed033bf01fa0fd98948a91e.jpg', '<p>Dư Mãn Nguyệt là người phụ trách quan hệ công chúng, một chuyên gia xử lý khủng hoảng truyền thông cho các tập đoàn lớn. Trước mặt mọi người, Nguyệt tài sắc vẹn toàn, nhưng thâm sâu, cô có một ký ức đáng sợ. Mười tám năm trước, cô và em gái bị con trai thương gia Tưởng Triết Hiền là Tưởng Cơ Tuấn xâm hại. Gia đình vì thế mà gặp biến cố lớn, cha mẹ bị hại, em gái tàn tật, chị gái cũng bỏ nhà đi. Nỗi đau chồng chất, Nguyệt thề sẽ trả thù. Nhẫn nại suốt mười tám năm, cuối cùng Dư Mãn Nguyệt thành công phơi bày tội ác của cha con nhà họ Tưởng, khiến nhà họ Tưởng suy sụp và đưa những người tham gia vào vòng pháp luật. Đồng thời, trên hành trình báo thù, Nguyệt đã quen biết chuyên gia chứng khoán Thành Phong và dần nảy sinh tình cảm với anh. Hạnh phúc chưa lâu, Dư Mãn Nguyệt lại phát hiện kẻ chủ mưu thực sự chính là người bạn cũ, Trác Tuệ Vân. Hận thù trong lòng quá lớn, Nguyệt thỉnh cầu Phong tiếp cận Vân, lừa gạt cô ta đến chỗ trắng tay…</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2024, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Thiến Nghiêu","avatar":""},{"name":"Vương Hạo Tín","avatar":""},{"name":"Lâm Hạ Vy","avatar":""},{"name":"Mã Chí Uy","avatar":""},{"name":"Quách Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["He Se Yue Guang","Darkside of The Moon","نیمه تاریک ماه","黑色月光"]', 1784690324223);
