INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-san-cua-devara-phan-1', 'Di Sản Của Devara (Phần 1)', 'Devara: Part 1', 'https://phimimg.com/upload/vod/20241204-1/82fdc97f9481e9f1c47da92956c6d179.jpg', 'https://phimimg.com/upload/vod/20241204-1/3f1fb6adbca422afe35a7b360f7d1d8b.jpg', '<p>Một chiến binh biển hùng mạnh đã có hành động bạo lực chống lại những hành vi tội phạm của ngôi làng mình. Nhiều năm sau, người con trai hiền lành của ông cũng đi theo con đường của riêng mình.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"N.T. Rama Rao Jr.","avatar":""},{"name":"Saif Ali Khan","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Srikanth","avatar":""},{"name":"Kalaiyarasan","avatar":""},{"name":"Shruti Marathe","avatar":""},{"name":"Janhvi Kapoor","avatar":""},{"name":"Shine Tom Chacko","avatar":""},{"name":"Ajay","avatar":""},{"name":"Zarina Wahab","avatar":""},{"name":"Narain","avatar":""},{"name":"Murali Sharma","avatar":""},{"name":"Abhimanyu Singh","avatar":""},{"name":"Rameshwari Talluri","avatar":""},{"name":"Sudev Nair","avatar":""},{"name":"Tarak Ponnappa","avatar":""},{"name":"Sana","avatar":""},{"name":"Getup Srinu","avatar":""},{"name":"Hari Tej","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["NTR 30","NTRKoratalaSiva2","देवारा","தேவாரா","ದೇವರ","ദേവാര","Devara","دِوارا: بخش ۱","紅海怒濤","デーヴァラ","Devara: Part 1"]', 1784690324223);
