INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('di-san-cua-devara-phan-1', 'Di Sản Của Devara (Phần 1)', 'Devara: Part 1', 'di sản của devara (phần 1) devara: part 1 n.t. rama rao jr. saif ali khan prakash raj srikanth kalaiyarasan shruti marathe janhvi kapoor shine tom chacko ajay zarina wahab narain murali sharma abhimanyu singh rameshwari talluri sudev nair tarak ponnappa sana getup srinu hari tej ntr 30 ntrkoratalasiva2 देवारा தேவாரா ದೇವರ ദേവാര devara دِوارا: بخش ۱ 紅海怒濤 デーヴァラ devara: part 1', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tham-tu-tu-ma-nam-vu-an-bi-an-xac-trong-ruong', 'Nữ Thám Tử Tư Mã Nam: Vụ Án Bí Ẩn Xác Trong Rương', 'Once Upon a Time in China', 'https://phimimg.com/upload/vod/20241204-1/5e7ba7582857fbf419182a61bfe8f63d.jpg', 'https://phimimg.com/upload/vod/20241204-1/64884028f6a4d613c803dd96b26a2840.jpg', '<p>Bộ phim kể về câu chuyện của một nữ thám tử người Hoa tên là Tư Mã Nam. Trong thời kỳ hỗn loạn đầy biến động, cô đã dứt khoát từ bỏ cuộc sống sung túc trong giới kinh doanh để theo đuổi công lý. Với kỹ năng chuyên môn vững vàng, cô không ngừng tìm ra sự thật đằng sau các vụ án, bất kể nạn nhân là người giàu sang hay nghèo khổ. Cô cùng đội ngũ của mình luôn nghiêm túc và công bằng, kiên trì bảo vệ lẽ phải và minh oan cho những người đã khuất.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hua Tong","avatar":""},{"name":"Feng Lijun","avatar":""},{"name":"Zhang Jiayuan","avatar":""},{"name":"Zheng Tuojiang","avatar":""},{"name":"Han Mingxi","avatar":""},{"name":"范泓","avatar":""},{"name":"Liu Fengchao","avatar":""},{"name":"Wang Yitong","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Nv Zhen Tan Si Ma Nan Zhi Xiang Shi Mi An","Female Detective Sima Nan: The Mystery of the Corpse in the Box","Female Detective Sima Nan","女侦探司马楠之箱尸谜案"]', 1784690324223);
