INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tu-long-dat', 'Quái Vật Từ Lòng Đất', 'Elevation', 'https://phimimg.com/upload/vod/20241204-1/fee01253f9bf7d8ec3d8b5c17e39ae98.jpg', 'https://phimimg.com/upload/vod/20241204-1/02abfd745c7e65b24879d8b44d7a452e.jpg', '<p>Elevation diễn ra tại vùng núi Rocky hậu tận thế, nơi loài người phải trốn khỏi các sinh vật cơ học gọi là &quot;Reapers.&quot; Những sinh vật này xuất hiện từ lòng đất, tấn công loài người và tránh các khu vực trên độ cao 8.000 feet. Will (Anthony Mackie), một người cha đơn thân, cùng nhà khoa học Nina (Morena Baccarin) và một vài người sống sót khác, mạo hiểm rời nơi trú ẩn để tìm cách cứu con trai Will và đối phó với các sinh vật này. Trong hành trình, nhóm phát hiện Reapers không phải là sinh vật sống mà là robot do công nghệ tiên tiến tạo ra, có thể liên quan đến một nhóm bí ẩn hoặc thậm chí người ngoài hành tinh. Nina phát triển đạn được laced cobalt để tiêu diệt chúng bằng cách gây nổ từ bên trong. Kết thúc phim, các cộng đồng con người đoàn kết, sử dụng phát minh của Nina để chiến đấu giành lại đất đai, mở ra hy vọng mới cho nhân loại.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anthony Mackie","avatar":""},{"name":"Morena Baccarin","avatar":""},{"name":"Maddie Hasson","avatar":""},{"name":"Danny Boyd Jr.","avatar":""},{"name":"Rachel Nicks","avatar":""},{"name":"Shauna Earp","avatar":""},{"name":"Tyler Grey","avatar":""},{"name":"Drexel Malkoff","avatar":""},{"name":"David Malkoff","avatar":""},{"name":"Mike Hickman","avatar":""},{"name":"Ian Hummel","avatar":""},{"name":"Dalila Orozco","avatar":""},{"name":"James Anthony Perez","avatar":""},{"name":"Gregg S. Perry","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ارتفاعات","高处营救","高地營救","Хищные земли","Elevation","Elevation - Don’t go down without a fight","Criaturas: Línea de extinción","ELEVAÇÃO"]', 1784690324223);
