INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-martin', 'Mật Danh Martin', 'Martin', 'https://phimimg.com/upload/vod/20241204-1/415fd7e4991fb66fb219cf7af2d38f79.jpg', 'https://phimimg.com/upload/vod/20241204-1/79fd66e6a058df1b6a8bf29278384dc1.jpg', '<p>Bộ phim xoay quanh nhân vật Trung tá Arjun Saxena, một quân nhân với sứ mệnh đặc biệt. Hành trình của anh bắt đầu từ Pakistan trở về Ấn Độ, nơi anh quyết tâm khám phá danh tính thật sự của mình. Trong quá trình này, Arjun phát hiện ra một âm mưu đen tối của các tay buôn chợ đen đang cấu kết với bọn khủng bố để thực hiện những cuộc tấn công quy mô lớn nhằm vào đất nước.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Dhruva Sarja","avatar":""},{"name":"Vaibhavi Shandilya","avatar":""},{"name":"Anveshi Jain","avatar":""},{"name":"Chikkanna","avatar":""},{"name":"Malavika Avinash","avatar":""},{"name":"Achyuth Kumar","avatar":""},{"name":"Nikitin Dheer","avatar":""},{"name":"Nawab Shah","avatar":""},{"name":"Rohit Pathak","avatar":""},{"name":"Rubiel Mosquera","avatar":""},{"name":"Nathan Jones","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["喋血杀机","Martin"]', 1784690324223);
