INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-tam', 'Thượng Tâm', 'The Dark Crown', 'https://phimimg.com/upload/vod/20241127-1/74f66ae378e0f3290d6119438fa01f8e.jpg', 'https://phimimg.com/upload/vod/20241127-1/34e53a7afd600599b4669e0a78d4571e.jpg', '<p>Vu Lạc bị người thân cận hãm hại, chết trong uất hận. Sau khi sống lại, cô thề phải giành lại cuộc đời của mình. Vu Lạc dựa vào ký ức kiếp trước, hô mưa gọi gió chốn thương trường, không ngờ lại gặp phải ác ma dây dưa không dứt từ kiếp trước - Liêu Hữu Đình...</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hana Lin","avatar":""},{"name":"Chen Junyu","avatar":""},{"name":"Feng Yuting","avatar":""},{"name":"Li Song Ci","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shang Xin","豪门重生：总裁夫人太彪悍","上心"]', 1784690324223);
