INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-y-thien-ha', 'Phượng Ý Thiên Hạ', 'The Reign Of Feng Yi', 'https://phimimg.com/upload/vod/20241127-1/a1ad6b235265240f79da39fb8201bd0b.jpg', 'https://phimimg.com/upload/vod/20241127-1/3c44aebd53b34b9475c9c82cf2673c9c.jpg', '<p>Thuở xưa, để giành quyền lực, thái hậu đã sắp đặt thay đổi giới tính của Phượng Ý, từ đó bắt đầu cuộc sống giả trang thành nam nhân của cô. Sau khi trưởng thành, không cam lòng trở thành hoàng đế bù nhìn, Phượng Ý bắt đầu xây dựng thế lực của riêng mình. Nhưng ai ngờ, khi muốn lấy lòng tể tướng thì tể tướng lại đột ngột qua đời trong thanh lâu, còn khi muốn lôi kéo Thái phó Tư Mã Kỳ, Tư Mã Kỳ lại nhiều lần muốn giết cô! Khổ hay không, nhìn con gái làm quân chủ! Bi thương hay không, chỉ cần sơ suất một chút là mất mạng!</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Song Zhaoyi","avatar":""},{"name":"Chen Jianyu","avatar":""},{"name":"Yang Teng","avatar":""},{"name":"Du Haoming","avatar":""},{"name":"Liu Jiaqi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Feng Yi Tian Xia","陛下，不可以","鳳懿天下","The Reign of Feng Yi","Feng Yi’s World","凤懿天下"]', 1784690324223);
