INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-tinh-tu', 'Mặt Trời Tinh Tú', 'See Her Again', 'https://phimimg.com/upload/vod/20241120-1/ab71ab8dd62c7aef74c8b978b9ca4f44.jpg', 'https://phimimg.com/upload/vod/20241120-1/1012f6e2ec92d15e40079e792ab7efac.jpg', '<p>Cảnh sát Hong Kong Dương Quang Diệu (Trần Vỹ Đình) gặp sự cố khi truy đuổi hung thủ của hàng loạt vụ giết người xuyên không đến năm 2018.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Vỹ Đình","avatar":""},{"name":"Lưu Nhã Sắt","avatar":""},{"name":"Phùng Đức Luân","avatar":""},{"name":"Tạ Quân Hào","avatar":""},{"name":"Châu Lệ Kỳ","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Protegendo o passado","See Her Again","太陽星辰"]', 1784690324223);
