INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-chia-xa-voi-chang', 'Không Chia Xa Với Chàng', 'Never Apart From You', 'https://phimimg.com/upload/vod/20241130-1/beeffa1365e3f8d9ed4020f0db57d4ce.jpg', 'https://phimimg.com/upload/vod/20241201-1/1edad43179d0bbe89e95ed370046c312.jpg', '<p>Chuyên gia pháp y Chu Li được đưa vào một cuốn tiểu thuyết trả thù tái sinh với vai Jiang Ruoli, nhân vật phản diện bị buộc tội giết nhân vật chính Jun Wuye và mẹ anh. Sử dụng kiến thức của mình về câu chuyện, Chu Li giúp Jun Wuye khám phá ra thủ phạm thực sự đồng thời hướng dẫn anh quay trở lại với những nguyên tắc và niềm tin vào nhân loại. Khi mối quan hệ hợp tác của họ trở nên tin tưởng và tình cảm sâu sắc hơn, họ phát hiện ra một sự thật gây sốc làm thay đổi mọi thứ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guan Xin","avatar":""},{"name":"Aaron Deng","avatar":""},{"name":"Chen Zhuo","avatar":""},{"name":"Junkai Zhao","avatar":""},{"name":"Wang Jiahui","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yu Jun Wu Bie Li","与君无别离"]', 1784690324223);
