INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khanh-bon-giai-nhan', 'Khanh Bổn Giai Nhân', 'Found & Lost', 'https://phimimg.com/upload/vod/20241122-1/3f69d9e31ec79ffd3f6f46eeebcbee0f.jpg', 'https://phimimg.com/upload/vod/20241122-1/ed2169d376d68f60e02f89ff3c578377.jpg', '<p>Đầu thời Dân quốc, Tô Mạn Lệ, vũ nữ dự bị ở vũ trường Tiên Lạc Tư, vì muốn tìm kiếm kẻ thù giết cha, quen biết với tiểu thư quý tộc Trần Bích, người gặp cảnh nhà tan cửa nát. Tô Mạn Lệ mượn thân phận của Trần Bích để tiếp cận Dương Tử Khâm, quản lý hội Hải Đường, cố gắng điều tra rõ chân tướng vụ thảm sát nhà họ Trần. Sau khi biết thân phận thật sự của Dương Tử Khâm, ba người quyết định hợp sức chống lại hung thủ thực sự.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wen Yuan","avatar":""},{"name":"Xu Zixuan","avatar":""},{"name":"Qu Yicheng","avatar":""},{"name":"焦雪睿","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["卿本佳人"]', 1784690324223);
