INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dai-dien', 'Người Đại Diện', 'Senyawa', 'https://phimimg.com/upload/vod/20241201-1/c5d12697ed6607b8b8b14c385d4e2bf4.jpg', 'https://phimimg.com/upload/vod/20241201-1/af137e46ef598d2e1e011772d9adc014.jpg', '<p>Bộ phim này đề cập đến một vấn đề khá nhạy cảm đó là vấn đề mang thai hộ là HARAM theo đạo Hồi. Kể về câu chuyện của Zabrina (Trisha Ooi), một nữ doanh nhân nổi tiếng, chủ một bệnh viện thẩm mỹ đang gặp khó khăn trong việc sinh con. Đã sẩy thai bốn lần, được bác sĩ xác nhận là có vấn đề về suy cổ tử cung, tử cung không đủ khỏe để chứa các chất bên trong. Vì điều đó, mẹ vợ của anh, Dato &#39;Asmida (Datin Nina Juren), người thực sự muốn có cháu trai làm người thừa kế di sản kinh doanh của mình, đã nhất quyết yêu cầu con trai bà, Iskandar (Shahz Jaszle), kết hôn với người khác.</p>', 'Tập 12', 12, 'series', 'ongoing', 19, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Trisha Ooi","avatar":""},{"name":"Shahz Jaszle","avatar":""},{"name":"Siti Hariesa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Senyawa"]', 1784690324223);
