INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tra-thu-cua-nang-bach-tuyet', 'Sự Trả Thù Của Nàng Bạch Tuyết', 'Snow White''s Revenge', 'https://phimimg.com/upload/vod/20241003-1/d6f433448d085c9f10f3ed52daf94f95.jpg', 'https://phimimg.com/upload/vod/20241003-1/97e19e6a4261278ddd5fa8f4da5c4e49.jpg', '<p>Jeong In được phát hiện đã chết, cầm trên tay một mảnh giấy báo trước cái chết của cô. Trong quá khứ, cô và Min Tae Chang đã âm mưu giết cha của Baek Seol Ah và cướp đi tài sản của ông. Sau khi sử dụng số tiền trộm được để trở thành CEO của một công ty sản xuất mà cô thành lập, cô gặp và yêu Seo Jin Ho, một diễn viên đầy tham vọng có ngoại hình giống hệt mối tình đầu của cô. Jeong In biến anh thành Jung Woo Jin, một ngôi sao hàng đầu. Tuy nhiên, cô biết được rằng tình cũ của anh là Baek Seol Ah và Park Jin Kyung, tác giả chưa được tiết lộ của &quot;Poker Face&quot;, cũng chính là Baek Seol Ah. Baek Seol Ah thề sẽ trả thù sau khi biết rằng bạn trai cũ của cô, Seo Jin Ho, có quan hệ với Jeong In, kẻ đã sát hại cha cô. Cô quyết tâm viết một vở kịch để hoàn thành cuộc trả thù của mình. Baek Seol Ah có thể là kẻ sát hại Moon Jeong In? Thủ phạm là người có mặt trong phòng tiệc nhưng ai cũng cầu mong cho Jeong In cái chết. Đó là ai và vì lý do gì họ giết cô ấy?</p>', 'Hoàn Tất (102/102)', 102, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"한채영","avatar":""},{"name":"Choi Woong","avatar":""},{"name":"이준혁","avatar":""},{"name":"한보름","avatar":""},{"name":"Kim Kyu-seon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["SWR","스캔들","فضيحة","醜聞","Scandal","Sự Trả Thù Của Bạch Tuyết"]', 1784690324223);
