INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-quan-vo-gian', 'Dữ Quân Vô Gian', 'Love In The Crossfire', 'https://phimimg.com/upload/vod/20241124-1/cc20c2b701170a8af890248ca3e6c405.jpg', 'https://phimimg.com/upload/vod/20241124-1/06c2b0bdee4cd1fe498d793dcdc43a9c.jpg', '<p>Hai nước Thịnh Vũ giao chiến, nước Thịnh bị đánh bại. Công chúa nước Thịnh bị ám sát trên đường đi hoà thân. Trước khi chết, A Nguyệt, cô gái y nữ riêng được công chúa nhờ giả làm Công chúa Thịnh Lạc Lăng để tiếp tục sứ mệnh đánh cắp bản đồ phòng thủ bí mật của nước Vũ. Ngu phi nước Vũ qua đời một cách bí ẩn, để lại Sở Như Hoành, hoàng tử thứ ba của nước Vũ, mang tiếng là một nghịch tử khiến mẹ tức chết. Sở Như Hoành làm mọi cách để tìm ra sự thật về cái chết của mẹ mình. Một &quot;Công chúa mồ côi chiến tranh giả&quot; gặp một &quot;Hoàng tử thật nổi loạn đích thực&quot;. Trong hoàng cung nguy hiểm, vì tình yêu và hòa bình, cả hai cùng nhau hóa giải những nguy hiểm, yêu thương và tin tưởng, dựa dẫm lẫn nhau.</p>', 'Tập 20', 20, 'series', 'ongoing', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Haoxuan","avatar":""},{"name":"Xiao Douhua","avatar":""},{"name":"Chen Luxi","avatar":""},{"name":"Lu Ming","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love and Peace","與君無間","与君无间"]', 1784690324223);
