INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-khong-the-o-ben-nhau', 'Chúng Ta Không Thể Ở Bên Nhau', 'The Love We Couldn''t Keep', 'https://phimimg.com/upload/vod/20241124-1/6223cf23ddb59d30b07c94d67499cb49.jpg', 'https://phimimg.com/upload/vod/20241124-1/e580f85f04bb68d4763e22b597331a61.jpg', '<p>Thang Vi Vi vốn đã hết hy vọng với tình yêu lại vì một sự cố hài hước và hiểu lầm mà yêu đương với thực tập sinh Lê Thứ. Ngay khi Thang Vi Vi đang đắm chìm trong hạnh phúc thì biết được Lê Thứ là em trai của mối tình đầu đã qua đời, cậu xuất hiện cũng là vì mục đích trả thù. Sau khi hóa giải hiểu lầm, hai người vẫn chọn chia tay nhau. Nhiều năm sau khi gặp lại trên đường, hai người nhìn nhau mỉm cười.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jackey Zhu","avatar":""},{"name":"Peihan Wang","avatar":""},{"name":"Lu Lu","avatar":""},{"name":"Dong Zexin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我们分手吧","We Can''t","We Can''t Be Together","我們不能在一起","我们不能在一起"]', 1784690324223);
