INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-vo-song', 'Công Tử Vô Song', 'Shameless Lover', 'https://phimimg.com/upload/vod/20241112-1/9a6650a99111af8ed0cb88c10a763584.jpg', 'https://phimimg.com/upload/vod/20241112-1/7feaf420cd064c3449d946128b6f0aaa.jpg', '<p>Thẩm Tri Ly đã sử dụng những thuốc dẫn cổ xưa để sư phụ sống lại, nhưng chuyến viếng thăm của Tô Trầm Triệt đã khiến Thẩm Tri Ly rơi vào vòng lặp thời gian. Thẩm Tri Ly phát hiện ra rằng thời gian sẽ quay ngược lại khi Tô Trầm Triệt chết. Để tìm ra thuốc thành công, nên hai người cùng nhau lên đường. Những hiểu biết ngầm và hiểu lầm lần lượt xảy ra, và một người đàn ông bí ẩn đã bí mật hướng dẫn họ. Liệu cả hai có thể giải quyết được bí ẩn về thời gian và không gian và tìm ra thuốc?</p>', 'Tập 32', 32, 'series', 'ongoing', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Tuyết Ninh","avatar":""},{"name":"Cảnh Nghiệp Đình","avatar":""},{"name":"Vu Hiên Thần","avatar":""},{"name":"Vương Nhất Lâm","avatar":""},{"name":"Lý Nghiên","avatar":""},{"name":"Phan Khải Ngôn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["公子无耻","公子無雙","Shameless Lover","公子无双"]', 1784690324223);
