INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-1995', 'Xin Chào 1995', 'Back To 1995', 'https://phimimg.com/upload/vod/20241201-1/285924ced2effd71b45f3336c22405c0.jpg', 'https://phimimg.com/upload/vod/20241201-1/66a2efd84067e7f6b45b9b7b211a432d.jpg', '<p>Zhang Dabao là một người đàn ông trung niên đã mất niềm tin vào cuộc sống sau vô số thất bại. Khi anh bất ngờ quay trở lại năm 1995 và gặp lại chính mình lúc 22 tuổi, cả hai bắt đầu một cuộc hành trình đầy thử thách truyền cảm hứng cho họ hợp lực. Cùng nhau, họ tìm cách hàn gắn những hối tiếc trong quá khứ và tạo nên một khởi đầu mới trong cuộc đời.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Weiyi","avatar":""},{"name":"Wu Jiayi","avatar":""},{"name":"Wang Ge","avatar":""},{"name":"Ma Xudong","avatar":""},{"name":"Xu Xiaohan","avatar":""},{"name":"Xing Hanqing","avatar":""},{"name":"Yang Zhengyi","avatar":""},{"name":"Song Muxin","avatar":""},{"name":"Yilia","avatar":""},{"name":"Sun Zhengyu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["嗨！1995","Hi 1995","嗨1995"]', 1784690324223);
