INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-chao-1995', 'Xin Chào 1995', 'Back To 1995', 'xin chào 1995 back to 1995 zhang weiyi wu jiayi wang ge ma xudong xu xiaohan xing hanqing yang zhengyi song muxin yilia sun zhengyu 嗨！1995 hi 1995 嗨1995', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-bong-nuoc', 'Thiếu Niên Bóng Nước', 'Youth Water Polo', 'https://phimimg.com/upload/vod/20241201-1/62f29365c319fcc894a5ea7fe07e1496.jpg', 'https://phimimg.com/upload/vod/20241201-1/b38df5268fc365c54de0e9c5a2c5fda9.jpg', '<p>Khi lễ tốt nghiệp đến gần, Chu Chí Viễn được huấn luyện viên bóng nước của chị gái truyền cảm hứng để vực dậy đội bóng đang gặp khó khăn của trường. Anh ta chiêu mộ một loạt các cầu thủ kỳ cựu, một cầu thủ bóng rổ bị từ chối và một cựu thần đồng bóng nước. Cùng nhau, họ phải đối mặt với những thách thức cả trong và ngoài sân cỏ, từ việc tranh giành không gian tập luyện cho đến vượt qua những nghi ngờ trong đội. Bất chấp những xung đột và thất bại, họ vẫn kiên trì, cuối cùng theo đuổi ước mơ chung là thành công trong môn bóng nước.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Haoxuan","avatar":""},{"name":"Hou Fuming","avatar":""},{"name":"Xue Zeyuan","avatar":""},{"name":"Min Xinghan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["扑通扑通的水球少年"]', 1784690324223);
