INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-kinh-hanh-phan-1', 'Thanh Kính Hành (Phần 1)', 'Ancient Forensic Expert (Season 1)', 'https://phimimg.com/upload/vod/20241201-1/3222a386b25b6cd94e77a848829c24d5.jpg', 'https://phimimg.com/upload/vod/20241201-1/80771bc0cd500822938cadfa00bf690b.jpg', '<p>Người chữa bệnh Khúc Chấn và Hoàng tử Dung Kim Sinh hợp lực để chống lại chất độc chết người lan truyền khắp Dasheng. Khi họ đối mặt với những hiểu lầm, sát thủ và âm mưu chính trị, kỹ năng và quyết tâm của Qu Zhen được thử thách. Cùng nhau, họ hành trình qua những vùng đất nguy hiểm, tìm kiếm phương pháp chữa trị và khám phá những bí mật đen tối đang đe dọa đế chế.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Jingxin","avatar":""},{"name":"Yu Xuan Hong Hao","avatar":""},{"name":"Huang Xiaochao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["青镜行第一季","青镜行"]', 1784690324223);
