INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-nao-do', 'Một Ngày Nào Đó', 'Satu Hari Nanti', 'https://phimimg.com/upload/vod/20241201-1/36bff6af52d09781a4cc4edbb6c34106.jpg', 'https://phimimg.com/upload/vod/20241201-1/610aaffe184b5519bb7ebbf6811da1f8.jpg', '<p>Bộ phim truyền hình Một Ngày Nào Đó kể về câu chuyện của chàng trai trẻ Trung Quốc Noah Lee (do Ezaidi Aziz thủ vai) và cô gái Audrey (do Nina KSC thủ vai) sau khi trải qua những thất vọng trong mối quan hệ trước đó. Từ đó, Noah cố gắng tìm kiếm sự khôn ngoan từ những gì đã xảy ra. Noah bắt đầu bận rộn với công việc từ thiện và gặp một cô gái ngọt ngào tên là Marissa Safiya (do Eyka Farhana thủ vai). Với tinh thần mạnh mẽ đứng lên vì nữ quyền, Marissa âm thầm khiến Noah yêu cô. Câu chuyện của họ sẽ kết thúc ra sao? Tình yêu khác tôn giáo có thể tiếp tục hay không?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Eyka Farhana","avatar":""},{"name":"Ezaidi Aziz","avatar":""},{"name":"Bella Astillah","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mei Ren Wei Xian","Truy Tìm Ký Ức","美人为馅"]', 1784690324223);
