INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('asaf', 'Asaf', 'Asaf', 'https://phimimg.com/upload/vod/20241201-1/5e8155eb58d61ba809c0977e0b89d0ef.jpg', 'https://phimimg.com/upload/vod/20241201-1/79d59c5ccdce804ac5e411a3da8774c9.jpg', '<p>Vật lộn với cuộc ly hôn của mình, người bố nọ lao vào thế giới tội phạm có tổ chức. Khi tính mạng con trai gặp nguy hiểm, anh sẽ làm gì tiếp theo?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Cihangir Ceyhan","avatar":""},{"name":"Ahmet Rıfat Şungar","avatar":""},{"name":"Burçin Terzioğlu","avatar":""},{"name":"Saadet Işıl Aksoy","avatar":""},{"name":"Fatih Al","avatar":""},{"name":"Çağdaş Onur Öztürk","avatar":""},{"name":"Uygar Özçelik","avatar":""},{"name":"Serra Arıtürk","avatar":""},{"name":"Rıza Kocaoğlu","avatar":""},{"name":"Umut Kurt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["عساف","Asaf"]', 1784690324223);
