INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-con-tram-mac', 'Không Còn Trầm Mặc', 'No More Silence', 'https://phimimg.com/upload/vod/20241130-1/7d93036e42fef401ab2c93e763122fdb.jpg', 'https://phimimg.com/upload/vod/20241130-1/48eef006cfe62ceadcc42dbcbcedd4da.jpg', '<p>Sau sáu năm kết hôn, Gu Xiaoya đã hy sinh ước mơ của chính mình để trở thành người nội trợ toàn thời gian cho gia đình. Nhưng chồng cô, Chu Dương, tuy tỏ ra quan tâm nhưng thực tế lại kiểm soát và bạo hành. Chịu đựng sự ngược đãi liên tục của cả Chu Dương và mẹ chồng, Gu Xiaoya cuối cùng cũng có đủ can đảm để đứng lên bảo vệ chính mình. Với sự hỗ trợ từ luật sư Shen Jia, cô theo đuổi công lý thông qua các biện pháp pháp lý, đòi lại quyền lợi của mình, buộc Chu Dương phải chịu trách nhiệm và tìm lại ý thức về bản thân.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shuai Zhao","avatar":""},{"name":"Du Zheyu","avatar":""},{"name":"Qin Yu","avatar":""},{"name":"Liu Ruiqiao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["No More Silent","不再沉默"]', 1784690324223);
