INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-chanh', 'Hương Chanh', 'The Scent Of Lime', 'https://phimimg.com/upload/vod/20241130-1/0a0c22b989bb3bf90b6e242700f81272.jpg', 'https://phimimg.com/upload/vod/20241130-1/2ec25f3aba7be8205fc847db0e319dee.jpg', '<p>Trong năm cuối trung học, ba thiếu niên thuộc lớp kém triển vọng nhất đều phải vật lộn với những khó khăn cá nhân. Gao Ling, thông minh nhưng rút lui, bị ám ảnh bởi việc cha mình bị bắt. Wei Yuno che giấu sự cô đơn của mình đằng sau vẻ ngoài dũng cảm, trong khi Zhang Wenqi, xuất thân từ một gia đình đơn thân, tìm cách chứng tỏ sự trưởng thành của mình bằng cách lao vào tuổi trưởng thành. Cùng nhau, họ vượt qua những thử thách của tuổi thiếu niên, đối mặt với những vết sẹo tình cảm và khám phá bản thân.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Yuyan","avatar":""},{"name":"Shi Wei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qing Ning Zhi Wei","青柠之味"]', 1784690324223);
