INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-khai-nhu-mong', 'Hoa Khai Như Mộng', 'Blossoms In Dream', 'https://phimimg.com/upload/vod/20241130-1/78e1e23afe61d106d43f6fd863b825b4.jpg', 'https://phimimg.com/upload/vod/20241130-1/4e96fcdd7143cfcee1f9ddfdfe764b80.jpg', '<p>Vào những năm 1930 ở Thượng Hải, cô bé Su Xian được người mẹ đơn thân Hui nuôi dưỡng. Một cuộc gặp gỡ tình cờ với ông chủ công ty điện ảnh Mạnh đã thay đổi cuộc đời của Su Xian, khi anh ta khai thác sự ngây thơ và ước mơ trở thành ngôi sao của cô, để rồi bỏ rơi cô khi chiến tranh xảy ra, khiến cô mang thai. Bị tàn phá, Hui chết trong đau buồn, và hy vọng duy nhất của Su Xian là con gái cô, Su Zhi. Đến những năm 1950, Su Zhi lớn lên và yêu bạn cùng lớp của mình, Zou Jie, nhưng mối quan hệ của họ gặp trở ngại do hoàn cảnh gia đình phức tạp.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Jiayi","avatar":""},{"name":"Dong Jie","avatar":""},{"name":"Wang Lin","avatar":""},{"name":"Zhang Luyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["妇女生活","花开如梦"]', 1784690324223);
