INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-to-cuoc-doi', 'Bão Tố Cuộc Đời', 'Punch Out Life', 'https://phimimg.com/upload/vod/20241130-1/0c707aa79d3c443398e3124f14dfb9bb.jpg', 'https://phimimg.com/upload/vod/20241130-1/4522109446f0fbdacf0987aeae27c5f4.jpg', '<p>Năm 1990, anh chàng kém cỏi Wang Qiang chạm đáy – thất nghiệp, bị vợ khinh miệt và bỏ rơi. Đột nhiên, anh ấy được chuyển đến năm 2020, hiện là cha của ông trùm địa phương Lu Siming. Sử dụng sự giàu có mới có được của mình, Wang nắm bắt cơ hội trả thù và vận may, để rồi bị ném trở lại cuộc sống nghèo khó vào năm 1990. Với kiến thức về tương lai, anh quyết tâm xây dựng lại cuộc đời theo cách riêng của mình.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Kaixin","avatar":""},{"name":"Liu Yinjun","avatar":""},{"name":"Mu Lan","avatar":""},{"name":"Zilin Zhang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Kuang Biao Ren Sheng","狂飆人生","狂飙人生"]', 1784690324223);
