INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-sang-cua-tan-tro', 'Ánh Sáng Của Tàn Tro', 'Like Dust With Light', 'https://phimimg.com/upload/vod/20241130-1/ec492fb75bfe38add45ac483b44bdb45.jpg', 'https://phimimg.com/upload/vod/20241130-1/f5b39ef87b47552d8775526639a52592.jpg', '<p>Khi đang hộ tống quân đội, Qiao Jiu bị phục kích bởi các đặc vụ của Nhị hoàng tử Chu Mubai và Dai Shuang. Để cứu anh, Jiang Yefeng kết hôn với Qiao Jiu, nhưng họ sớm bị gài bẫy và giam cầm. Sử dụng trí thông minh của mình, họ trốn thoát và bắt đầu khám phá ra sự thật. Trong quá trình tìm kiếm, Jiang Yefeng bị Chu Mubai tấn công khi đang bảo vệ Qiao Jiu. Quay trở lại cuộc sống của họ, Jiang nhận ra sai lầm của mình và cầu hôn Qiao Jiu, hy vọng cùng nhau có một khởi đầu mới.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zheng Fanxing","avatar":""},{"name":"Zhong Qi","avatar":""},{"name":"范迪禹","avatar":""},{"name":"Deng Zhi Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Yu Guang Tong Chen","王爷的小甜妃","听说王妃又赚了一座城","與光同塵","与光同尘"]', 1784690324223);
