INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-vali', 'Chiếc Vali', 'The Trunk', 'https://phimimg.com/upload/vod/20241130-1/03d008bf470f973c186b07f295454c8d.jpg', 'https://phimimg.com/upload/vod/20241130-1/5d3212903114c9bbbaf69410e50de03d.jpg', '<p>The Trunk xoay quanh câu chuyện của Han Jeong Won, một nhà sản xuất âm nhạc do Gong Yoo thủ vai. Nhân vật của anh tham gia vào một cuộc hôn nhân giả với Noh In Ji, một người phụ nữ có công việc &quot;làm vợ thuê&quot;, do Seo Hyun Jin đảm nhận. Cuộc hôn nhân này được sắp đặt bởi vợ cũ của Jeong Won, tạo nên nhiều tình huống dở khóc dở cười khi cả hai cố gắng tìm hiểu nhau trong bối cảnh một chiếc vali bí ẩn xuất hiện, làm tăng thêm sự hấp dẫn cho cốt truyện.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo Hyun-jin","avatar":""},{"name":"Gong Yoo","avatar":""},{"name":"Jung Yun-ha","avatar":""},{"name":"Kim Dong-won","avatar":""},{"name":"Uhm Ji-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一箱情缘","الحقيبة","The Trunk","트렁크"]', 1784690324223);
