INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jack-and-joker-nguoi-danh-cap-trai-tim-toi', 'Jack And Joker: Người Đánh Cắp Trái Tim Tôi!', 'Jack & Joker: U Steal My Heart!', 'https://phimimg.com/upload/vod/20240910-1/9b3bb1a646e6d7bed4b7d7eb9e06fd14.jpg', 'https://phimimg.com/upload/vod/20240910-1/cf674b2ebb7c83278b9cd3ff86047d21.jpg', '<p>Số phận đưa hai chàng trai trẻ vào mối quan hệ yêu ghét lẫn nhau. Jack, một võ sĩ taekwondo dự bị 18 tuổi không có cơ hội trở thành một tuyển thủ lên đài, quyết định từ bỏ sự nghiệp không may mắn này. Vì phải kiếm tiền nuôi gia đình, anh đã vay tiền để mở một trung tâm phát triển thanh thiếu niên trong cộng đồng và cũng làm nghề thu nợ với vẻ ngoài hung dữ nhưng có một trái tim nhân hậu. Jack gặp Joker, một tên cướp với nghìn khuôn mặt, cải trang thành nhân viên ngân hàng để lừa gia đình của mình rằng anh ta có một cuộc sống thành đạt và giàu có. Anh chàng là một người đàn ông quyến rũ và sắc sảo nhưng thực chất không giỏi về bất cứ điều gì, vậy nên anh ta quyết định lừa mọi người từ ngày này qua ngày khác. Cho đến khi bị cuốn vào một tình huống phức tạp, từ cướp để sinh tồn nay trở thành trả thù và Jack và Joker hợp tác để chuẩn bị thực hiện một phi vụ lớn của cả hai!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Yin Anan Wong","avatar":""},{"name":"Wanarat Ratsameerat","avatar":""},{"name":"Ratchapat Worrasarn","avatar":""},{"name":"Bonz Nadol Lamprasert","avatar":""},{"name":"Siwat Jumlongkul","avatar":""},{"name":"Nathanan Akkharakitwattanakul","avatar":""},{"name":"ศรัณยู ประชากริช","avatar":""},{"name":"Chatchawit Techarukpong","avatar":""},{"name":"Ne Netipat Luksanavisis","avatar":""},{"name":"Peerawich Ploynumpol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324223);
