INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-hen-cung-truong-thanh', 'Ước Hẹn Cùng Trưởng Thành', 'The Promise of Growing Up Together', 'https://phimimg.com/upload/vod/20241128-1/bdc2a985b291a62ea415fc80099072a8.jpg', 'https://phimimg.com/upload/vod/20241128-1/65825de7f91ced14e2e5a87690f393a5.jpg', '<p>Tại thị trấn sôi động Luxiang, một cô gái bình thường, Xia Mi, bất ngờ được nhận vào trường trung học hàng đầu của thành phố, nơi cô gặp ba người bạn cùng lớp độc đáo: Zhang Ruoxi hướng ngoại, học sinh đứng đầu kiên định Fan Yuan và Lin Ruolei tốt bụng. . Cùng với một nhóm bạn đa dạng, họ dấn thân vào một cuộc hành trình hài hước và chân thành, tìm kiếm tình bạn, gia đình và mối tình đầu. Khi lớn lên và theo đuổi ước mơ, họ tạo ra một câu chuyện khó quên về tuổi trẻ và sự kiên cường.</p>', 'Tập 24', 24, 'series', 'ongoing', 13, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Morpheus Tian","avatar":""},{"name":"Ji Meihan","avatar":""},{"name":"Chen Kang","avatar":""},{"name":"Zheng Cheng Cheng","avatar":""},{"name":"Yin Rui","avatar":""},{"name":"Ye Xiaoqiu","avatar":""},{"name":"Hu Haofan","avatar":""},{"name":"Chen Wen","avatar":""},{"name":"Liu Fanxin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Grow Up Together","一起长大的约定"]', 1784690324223);
