INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-niem-thuong-an', 'Nhất Niệm Thường An', 'Peace & Love', 'https://phimimg.com/upload/vod/20241128-1/7d927b35f3dd72439305820003182579.jpg', 'https://phimimg.com/upload/vod/20241128-1/a4f6f85247b03c1b716a4822477650cb.jpg', '<p>Tao Yao, một nữ thần được giao nhiệm vụ bảo vệ trái cây linh thiêng của núi Guoshen, bị đày xuống cõi phàm trần sau khi mất đi sức mạnh thần thánh của mình vào tay Chang Feng tinh quái. Tái sinh thành Vương Tiểu Điệp, cô phải chịu đựng sự phản bội và khó khăn của gia đình, chỉ để phát hiện ra rằng linh hồn chịu trách nhiệm cho sự sụp đổ của cô hiện đang cư trú trong chồng cô, Fu An.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wei Tianhao","avatar":""},{"name":"Li Huan","avatar":""},{"name":"Jin Pengbo","avatar":""},{"name":"Wang Zhiyao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["一念常安"]', 1784690324223);
