INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-khuat-o-gangnam', 'Góc Khuất Ở Gangnam', 'Gangnam B-Side', 'https://phimimg.com/upload/vod/20241108-1/b70b23a1684f6eabe4442b19938381bc.jpg', 'https://phimimg.com/upload/vod/20241108-1/f015014aea9432bf1eab693376bd5368.jpg', '<p>Một thám tử bị ruồng bỏ bị kéo trở lại trò chơi sau khi bạn của con gái anh ta mất tích. Là người mới nhất trong một loạt phụ nữ mất tích ở khu vực Gangnam của Seoul, thám tử sẽ quay trở lại thế giới tệ nạn, ma túy và tham nhũng để khám phá ra điều gì đó đe dọa lật đổ một số tầng lớp tinh hoa giàu có nhất của thành phố.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jo Woo-jin","avatar":""},{"name":"Ji Chang-wook","avatar":""},{"name":"Ha Yoon-kyung","avatar":""},{"name":"BIBI","avatar":""},{"name":"Jeong Jae-kwang","avatar":""},{"name":"Um Mun-suk","avatar":""},{"name":"Oh Ye-ju","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Im Sung-jae","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["江南重案组","벌크","جانغنام، الجانب الآخر","江南B-Side","Bulk","Gangnam B-Side","강남 비-사이드"]', 1784690324223);
