INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-ayodhaya', 'Nữ Hoàng Ayodhaya', 'The Empress Of Ayodhaya', 'https://phimimg.com/upload/vod/20241025-1/ca59a22440812b36ddfc23d4996ff78b.jpg', 'https://phimimg.com/upload/vod/20241025-1/16eae9e04b39809452bebeb6db993636.jpg', '<p>Nữ Hoàng Ayodhaya - The Empress of Ayodhaya kể về cuộc đời của Hoàng hậu Sudachan, nữ hoàng duy nhất trong lịch sử Ayutthaya. Từ nhỏ, cô đã được nuôi dưỡng với tham vọng trở thành hoàng hậu, học chiến lược, võ thuật, và các kỹ năng khác. Sau khi trở thành hoàng hậu, cô âm mưu ám sát vua để giành lại ngai vàng cho triều đại của mình. Bộ phim khai thác góc khuất tâm lý của một người phụ nữ bị coi là xấu xa vì đã giết chồng và con trai để tình nhân lên ngôi, hé lộ câu chuyện thật đằng sau những phán xét của lịch sử.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"ดาวิกา โฮร์เน่","avatar":""},{"name":"ธนภัทร กาวิละ","avatar":""},{"name":"Theerapat Sajakul","avatar":""},{"name":"Fern Nopjira Lerkkajornnamkul","avatar":""},{"name":"สิรีธร ลีห์อร่ามวัฒน์","avatar":""},{"name":"ชลวิทย์ มีทองคำ","avatar":""},{"name":"ปานวาด เหมมณี","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["摄政女王","摄政王妃","The Empress of Ayodhaya","Thao Sri Sudachan","Mae Yua","แม่หยัว"]', 1784690324223);
