INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chon-lam-nguoi-mot-nha', 'Chọn Làm Người Một Nhà', 'Family By Choice', 'https://phimimg.com/upload/vod/20241010-1/d8c72a52c1047c1a806b29733772f392.jpg', 'https://phimimg.com/upload/vod/20241010-1/0131c768cc0bbf3136482303932e51db.jpg', '<p>Từ những người xa lạ chung sống dưới một mái nhà, tình bạn của họ lớn dần theo năm tháng. 10 năm sau, cuộc tái ngộ đã khơi dậy những cảm xúc sâu kín. Bộ phim không chỉ là câu chuyện tình yêu ngọt ngào mà còn là hành trình trưởng thành, khám phá ý nghĩa gia đình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"황인엽","avatar":""},{"name":"정채연","avatar":""},{"name":"배현성","avatar":""},{"name":"최원영","avatar":""},{"name":"최무성","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["组合式家族","偶然成为家人","以家人之名韩国版","以家人之名","Une famille préfabriquée","FBC","重組家庭","Jolibsik Gajok","عائلة حسب الاختيار","Go Ahead","A Prefabricated Family","Avengers Siblings","Assembled Family","조립식 가족"]', 1784690324223);
