INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-nong-thon-cua-gen-z', 'Cuộc Sống Nông Thôn Của Gen Z', 'Country Life Of Gen-Z', 'https://phimimg.com/upload/vod/20240918-1/b0a9aa2053af38e3d71571f818829d4a.jpg', 'https://phimimg.com/upload/vod/20240918-1/939f52c0f3afc7d43baab575be640d1a.jpg', '<p>Một chương trình tạp kỹ &quot;hipster&quot; ngoài đời thực, trong đó những người nổi tiếng thuộc Thế hệ Z từ thành phố trở thành đất nước Z bằng cách sống ở nông thôn.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"양세찬","avatar":""},{"name":"이은지","avatar":""},{"name":"이이경","avatar":""},{"name":"송건희","avatar":""},{"name":"Jung Dong-won","avatar":""},{"name":"미연","avatar":""},{"name":"Winter Aespa","avatar":""},{"name":"Kim Jung-woo","avatar":""},{"name":"권은비","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324223);
