INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-nhan-khong-thua-thiet', 'Hôn Nhân Không Thua Thiệt', 'No Gain No Love', 'https://phimimg.com/upload/vod/20240827-1/703980192d4fe20f3adb35785ae29fa5.jpg', 'https://phimimg.com/upload/vod/20240827-1/b04e021610619fafa422afd9dd24817d.jpg', '<p>Nội dung No Gain No Love xoay quanh nữ chính Son Hae Yeong (do Shin Min Ah đóng), một kiểu người hà tiện và không muốn tốn tiền vào bất cứ trường hợp nào. Tại công sở, Hae Yeong đang tranh đấu để được thăng chức, nhưng lại đối mặt với nguy cơ thất bại lớn. Để giải quyết vấn đề này, Hae Yeong đã lên kế hoạch kết hôn giả, và chọn nam chính Kim Ji Uk (do Kim Young Dae đóng) làm chú rể.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Min-a","avatar":""},{"name":"Kim Young-dae","avatar":""},{"name":"Lee Sang-yi","avatar":""},{"name":"Han Ji-hyeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324223);
