INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hon-nhan-khong-thua-thiet', 'Hôn Nhân Không Thua Thiệt', 'No Gain No Love', 'hôn nhân không thua thiệt no gain no love shin min-a kim young-dae lee sang-yi han ji-hyeon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-bao-gio-quen', 'Không Bao Giờ Quên', 'Don''t Forget Me', 'https://phimimg.com/upload/vod/20241127-1/f0ab377642830816de3f98b17cbdda24.jpg', 'https://phimimg.com/upload/vod/20241127-1/22fa904eb779a2e08c06439c03ececbd.jpg', '<p>Câu chuyện kể về một mối tình vượt qua ngàn năm. Nữ chính, Tần Tư Nguyên, là chủ một tiệm nhỏ mang tên Vật Vong Trai, đã sống qua hàng ngàn năm. Ban ngày, cô mở tiệm đón đèn hoa; ban đêm, cô thắp sáng những chiếc đèn để tiễn đưa linh hồn của những người đang hấp hối. Mỗi lần thắp một ngọn đèn, cô giúp một người hoàn thành tâm nguyện cuối cùng. Thế nhưng, dù có thể giúp người khác hoàn thành điều họ mong muốn, cô lại không thể thực hiện được nguyện vọng chấm dứt sự sống của chính mình, bởi tội nghiệt quá nặng, không thể đầu thai, và phải sống mãi qua từng kiếp người, không sinh không diệt. Khi Thẩm Tranh tình cờ bước vào Vật Vong Trai, ngọn đèn Vật vong xảy ra dị tượng, Tần Tư Nguyên hiểu rằng người dập tắt đèn cô chờ đợi hàng ngàn năm cuối cùng đã xuất hiện. Đồng thời, Tần Tư Nguyên nhìn ra số mệnh Thẩm Tranh không sống qua 20 tuổi, nên cô giữ anh lại trong Vật Vong Trai để kéo dài sinh mệnh. Ta kéo dài mạng sống cho ngươi, ngươi giúp ta dập tắt đèn, cuộc giao dịch này thoạt nhìn có vẻ như Thẩm Tranh là người hưởng lợi. Nhưng không ngờ Thẩm Tranh lại vô cùng bướng bỉnh, luôn chống đối, khiến Tần Tư Nguyên phải dùng mọi cách mạnh tay để ngăn cản. Hai người cứ rượt đuổi và đấu trí với nhau, cho đến khi Thẩm Tranh phải khuất phục, trở thành người hầu của cô và giúp cô tìm chiếc chụp đèn để dập tắt ngọn đèn. Chiếc chụp đèn ẩn giấu trong thành phố lớn Hải Đô, và trong quá trình tìm kiếm đầy hiểm nguy, hai người dần nảy sinh tình cảm với nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Jiulin","avatar":""},{"name":"Tan Yanyan","avatar":""},{"name":"Liu Yanchi","avatar":""},{"name":"Qiu Dongjie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nian Nian Wu Wang","勿忘提灯人","Wu Wang Ti Deng Ren","念念勿忘"]', 1784690324223);
