INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-hong-sung', 'Dưới Họng Súng', 'Under The Gun', 'https://phimimg.com/upload/vod/20241127-1/3e9a63df9149175a39f1677ab2cd07c3.jpg', 'https://phimimg.com/upload/vod/20241127-1/38ccfbfdd7bcb62f83f30313a0c0c27d.jpg', '<p>Dưới Họng Súng - Under the Gun, Câu chuyện về một chàng trai đem lòng yêu một cô gái được gọi là &quot;Phù thủy&quot;. Park Mi Jeong là người con gái có vẻ ngoài rất ưa nhìn và luôn tận hưởng cuộc sống tự do mỗi ngày. Cô là thông dịch viên tiếng Anh nhờ vào khả năng của mình từ nhỏ. Mẹ cô mất từ khi sinh cô và cô luôn luôn có một cuộc sống tự lập từ nhỏ. Tuy nhiên, vì vẻ bề ngoài thu hút có chút bí hiểm, cô luôn thu hút những người con trai xung quanh cô, và được biết đến với cái tên là &quot;Phù thủy&quot;. Cô dần quen với cuộc sống cô đơn của mình nhưng đôi khi, cô lại nhớ về bạn trai thời trung học với nụ cười tỏa nắng.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Zuho","avatar":""},{"name":"Jo Soo-min","avatar":""},{"name":"Seo Ji Won","avatar":""},{"name":"Ji Su Min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["UNDER THE GUN","언더더건","eondeodeogeon","Under the Gun","ပိုကာချစ်သူ","UNDER THE GUN ပိုကာချစ်သူ","تحت تهديد السلاح"]', 1784690324223);
