INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-hoa-kinh', 'Song Hoa Kính', 'Dream In The Mirror', 'https://phimimg.com/upload/vod/20241120-1/a6345fa0e4689365f97a91ff0a3a8d04.jpg', 'https://phimimg.com/upload/vod/20241120-1/a978635b8d63e1c462fb1135d9e43eda.jpg', '<p>Triệu Thanh Thanh, một du y giang hồ, bất ngờ qua đời một cách bi thảm. Tuy nhiên, vì báu vật &quot;Gương Song Hoa&quot;, linh hồn của cô đã bị giam giữ trong cơ thể của một người có cùng ngày sinh và tử vi - Tô Nam Yên, con gái của tướng quân nhưng lại có liên quan chặt chẽ với cái chết của Triệu Thanh Thanh. Tô Nam Yên võ công cao cường và Triệu Thanh Thanh cực kỳ thông minh. Hai người phụ nữ trong cùng một cơ thể dấn thân vào con đường báo thù trong triều đình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Nhất Quân","avatar":""},{"name":"Quách Gia Ngữ","avatar":""},{"name":"Trương Vĩnh Bác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Shuang Hua Jing","雙花鏡","双花镜"]', 1784690324223);
