INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-hieu-nhuong-quyen-mua-1', 'Thương Hiệu Nhượng Quyền (Mùa 1)', 'The Franchise (Season 1)', 'https://phimimg.com/upload/vod/20241012-1/3352bae8e052c11394f842b24f03ae8d.jpg', 'https://phimimg.com/upload/vod/20241012-1/b3b046c56fd1c785c35f3bc015cf3c58.jpg', '<p>Đoàn làm phim của loạt phim không được yêu thích chiến đấu để giành lấy vị trí của mình trong một vũ trụ điện ảnh man rợ và ngang ngược. Loạt phim này đã làm sáng tỏ sự hỗn loạn bí mật bên trong thế giới làm phim siêu anh hùng, để đặt ra câu hỏi - xúc xích điện ảnh được tạo ra chính xác như thế nào? Bởi vì mỗi chuyện khốn kiếp đều có một câu chuyện gốc.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Himesh Patel","avatar":""},{"name":"Aya Cash","avatar":""},{"name":"Jessica Hynes","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Lolly Adefope","avatar":""},{"name":"Darren Goldstein","avatar":""},{"name":"Isaac Powell","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Daniel Brühl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["הזיכיון","مجموعه","片場無極限","超英無盡頭","The Franchise"]', 1784690324223);
