INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-nam-kha', 'Mộng Nam Kha', 'Fate''s Crossing Nan & Ke', 'https://phimimg.com/upload/vod/20241109-1/6648cd5ef438128c996259f4368a21ce.jpg', 'https://phimimg.com/upload/vod/20241109-1/4af2af44c70bd858eaa4fd42418cb87e.jpg', '<p>Câu chuyện lấy bối cảnh tại quán trọ Vọng Xuyên bí ẩn và kể về mối quan hệ phức tạp giữa bổ đầu lạnh lùng Thẩm Nam và người phụ nữ bí ẩn A Kha. A Kha có khả năng bí ẩn đi vào giấc mơ của người sống. Một y nữ xấu xí thoát chết, một bà nội trợ tuyệt vọng với cuộc hôn nhân bất hạnh, một thiếu gia giàu có nhưng sinh ra yếu đuối... A Kha nhìn thấy ba ngàn rắc rối trong thế giới phàm trần trong giấc mơ của những người này, nhưng không ngờ lại biết được rằng mình và Thẩm Nam vẫn có mối tình định mệnh nối dài từ kiếp trước đến hiện tại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Geyang","avatar":""},{"name":"Qi Yandi","avatar":""},{"name":"Dong Hui","avatar":""},{"name":"Feng Lijun","avatar":""},{"name":"Dai Shaodong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Nan Ke Meng","Tales of the Dream Eaters","南柯夢","Fates Crossing Nan And Ke","南柯梦"]', 1784690324223);
