INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-dao', 'Độc Đạo', 'Only Way', 'https://phimimg.com/upload/vod/20240912-1/46d5152bf0bb9421c6c0f7edd8aa648d.jpg', 'https://phimimg.com/upload/vod/20240912-1/0db8ef07872e0c69b0f1a68546066585.webp', '<p>“Độc đạo” là hành trình đi tìm công bằng cho gia đình của Hồng – một đứa trẻ bất hạnh khi cùng lúc mất đi cả bố lẫn mẹ và lạc mất đứa em trai là người thân duy nhất của mình. Hồng bơ vơ thì được bà Mộc – vợ ông Lê Toàn đưa về nhà chăm sóc. Những tưởng Hồng sẽ có một gia đình mới, một cuộc đời mới bình yên, bù đắp cho những bất hạnh trước đây, nhưng mọi chuyện không đơn giản như thế. Trên hành trình đi tìm sự thật về quá khứ, đi theo những “chỉ dẫn” có được khiến Hồng hoài nghi chính người bố nuôi là Lê Toàn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"NSƯT Hoàng Hải","avatar":""},{"name":"Duy Hưng","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Hồ Phong","avatar":""},{"name":"Thanh Huế","avatar":""},{"name":"Hà Việt Dũng","avatar":""},{"name":"Bảo Anh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324223);
