INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doc-dao', 'Độc Đạo', 'Only Way', 'độc đạo only way nsưt hoàng hải duy hưng doãn quốc đam hồ phong thanh huế hà việt dũng bảo anh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-son-phong-ma-truyen', 'Thục Sơn Phong Ma Truyện', 'Shushan Devil', 'https://phimimg.com/upload/vod/20241125-1/e16f9e2d926c31c115243ca16807b699.jpg', 'https://phimimg.com/upload/vod/20241125-1/2f5c240f4ffd1ca1167dce23af4343e3.jpg', '<p>Nhân vật chính Liêu Bất Phàm trong mắt người đời là một ngôi sao chổi mà ai gặp anh cũng xui xẻo, cũng đang vật lộn với lời tiên tri về Ma Đà chuyển thế. Để thay đổi số phận, anh đã đến Thục Sơn bái sư tu luyện, cùng các sư huynh đệ, cuối cùng nhận được sự công nhận và giúp đỡ của mọi người, thực hiện được giá trị bản thân và lý tưởng của mình. Liêu Bất Phàm không phải là người hài hước, nhưng anh thường đối mặt với thế giới bằng một nụ cười hời hợt, che giấu sự lo lắng trong lòng để không ai phải lo lắng cho mình. Đối với người ngoài, anh là người sống an phận theo hoàn cảnh, nhưng những người thân thiết xung quanh thường có thể nhận ra nỗi lo âu ẩn sâu trong tâm hồn anh. Dù có vẻ liều lĩnh, nhưng anh cũng rất lý trí, hiểu rằng con đường đúng đắn không phải là con đường dễ dàng, và trên con đường ấy, sẽ phải đối mặt với vô số khó khăn và thử thách. Nữ chính Linh Lung không tin vào những lời đồn đại mà chỉ tin vào những gì tận mắt chứng kiến, chính tình yêu của cô đã khiến Liêu càng tin tưởng vào lựa chọn của mình và không đi lệch hướng.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhou Lu","avatar":""},{"name":"Mao Na","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Shao Kun","avatar":""},{"name":"Li Binghan","avatar":""},{"name":"Zhang Fengjun","avatar":""},{"name":"Tie Dun","avatar":""},{"name":"Liu Di","avatar":""},{"name":"Li Bin","avatar":""},{"name":"Sun Yizhen","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The Legend of Shushan","蜀山封魔传"]', 1784690324223);
