INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cham-day-troi-day', 'Chạm Đáy Trỗi Dậy', 'The Man Rebounds', 'https://phimimg.com/upload/vod/20241125-1/65a74b2b90b7698c9ced49f515ce6c44.jpg', 'https://phimimg.com/upload/vod/20241125-1/1ec1e76eff8046f6d1ececed6ccdfae9.jpg', '<p>Trùm ma túy lịch lãm đã hại vợ của Ngụy Đông, sau khi ra tù, Ngụy Đông quyết định bắt tội phạm ma túy để kiếm tiền thưởng nhằm cứu vãn gia đình. Con bạc Hoắc Thắng giết chết tay sai vận chuyển ma túy để chiếm đoạt tiền và ma túy tại hiện trường tai nạn. Ngụy Đông và Hoắc Thắng tình cờ gặp nhau và trở thành đồng nghiệp trong một công trình xây dựng. Một quý ông tương tự như Sherlock Holmes lần theo manh mối tìm ra công trường của hai người. Từ đó, ba bên đã diễn ra một màn kịch hài đen đầy thú vị.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yu Long","avatar":""},{"name":"Han Chengcai","avatar":""},{"name":"Ouyang Keyi","avatar":""},{"name":"Wang Shouao","avatar":""},{"name":"Zhu Que","avatar":""},{"name":"Niu Xing","avatar":""},{"name":"Xia Changjun","avatar":""},{"name":"Yan Jianguo","avatar":""},{"name":"He Yongqi","avatar":""},{"name":"Tian Qi","avatar":""},{"name":"Liang Junhao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["触底反弹"]', 1784690324223);
