INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hau-elisabeth-phan-2', 'Hoàng hậu Elisabeth (Phần 2)', 'The Empress (Season 2)', 'https://phimimg.com/upload/vod/20241125-1/46664ccf1664367bc00aa740b5259409.jpg', 'https://phimimg.com/upload/vod/20241125-1/a4849842b4e2c43bb2ff0fd20f463ef5.jpg', '<p>Khi Elisabeth nổi loạn phải lòng hoàng đế Franz và trở thành cô dâu bất đắc dĩ của anh, cô bước vào thế giới đầy rẫy căng thẳng và âm mưu tại triều đình Viên.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Devrim Lingnau","avatar":""},{"name":"Philip Froissant","avatar":""},{"name":"Melika Foroutan","avatar":""},{"name":"Johannes Nussbaum","avatar":""},{"name":"Elisa Schlott","avatar":""},{"name":"Jördis Triebel","avatar":""},{"name":"Almila Bağrıaçık","avatar":""},{"name":"Wiebke Puls","avatar":""},{"name":"Alexander Finkenwirth","avatar":""},{"name":"Raymond Tarabay","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sisi and Franz","הקיסרית","ซีซี่ จักรพรรดินีแห่งรัก","The Empress","Die Kaiserin"]', 1784690324223);
