INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-nghi-chau-quang', 'Nhà Nghỉ Châu Quang', 'Pearl Hotel', 'https://phimimg.com/upload/vod/20241120-1/442dc3a6db6de98ec02280130eafe4a3.jpg', 'https://phimimg.com/upload/vod/20241120-1/82df633d0831ee6597d20957b6daac86.jpg', '<p>Truyền thuyết kể rằng nhà nghỉ Châu Quang từng là một pháp trường âm khí rất nặng vào cuối triều đại nhà Thanh. Một thanh kiếm gỗ đào nhuốm máu được giấu trong nhà nghỉ để trấn áp tà ma. Mã Tiểu Đạo, một thanh niên nông thôn đến nhà nghỉ Châu Quang nổi tiếng làm bảo vệ. Nào ngờ cậu ta vô tình đập vỡ thanh kiếm gỗ đào, khiến những cư dân kỳ quái trong toà nhà khiển trách và nổi giận. Những chuyện ly kỳ trong tòa nhà ngày càng nhiều...</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ban Mã Gia","avatar":""},{"name":"Tống Mộc Tử","avatar":""},{"name":"Mạch Gia Hân","avatar":""},{"name":"Trang Đĩnh Hân","avatar":""},{"name":"Vạn Ni Đạt","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["珠光宾馆"]', 1784690324223);
