INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rem-ngoc-chau-sa', 'Rèm Ngọc Châu Sa', 'The Story Of Pearl Girl', 'https://phimimg.com/upload/vod/20241101-1/fe00415d973f491cf6b8acf940ce4d47.jpg', 'https://phimimg.com/upload/vod/20241101-1/0f7b77cadbdcd3dac8c46a02a56f4f14.jpg', '<p>Rèm Ngọc Châu Sa lấy bối cảnh đầu thời nhà Đường. Nội dung phim kể về cô gái làm nghề bắt ngọc trai ở Hợp phố tên Đoan Ngọ vì muốn làm sáng tỏ thân thế của mình đã đồng ý gia nhập đội buôn của Yến Tử Kinh. Đoan Ngọ có một đầu óc vô cùng nhanh nhạy và tài năng kinh doanh không phải dạng vừa. Nhờ đó, nàng đã giúp việc làm ăn của đoàn buôn trở nên phát đạt.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lộ Tư","avatar":""},{"name":"Lưu Vũ Ninh","avatar":""},{"name":"Đường Hiểu Thiên","avatar":""},{"name":"Tạ Khả Dần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Zhu Lian Yu Mu","珠簾玉幕","昆山玉前传","주렴옥막","주옥의 여인","История жемчужной девушки","เรื่องราวหญิงสาวอัญมณี","ม่านมุกม่านหยก","Pearl Curtain and Jade Curtain","The Legend of Jewelry","The Story of Pearl Girl","珠帘玉幕"]', 1784690324223);
