INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rem-ngoc-chau-sa', 'Rèm Ngọc Châu Sa', 'The Story Of Pearl Girl', 'rèm ngọc châu sa the story of pearl girl triệu lộ tư lưu vũ ninh đường hiểu thiên tạ khả dần zhu lian yu mu 珠簾玉幕 昆山玉前传 주렴옥막 주옥의 여인 история жемчужной девушки เรื่องราวหญิงสาวอัญมณี ม่านมุกม่านหยก pearl curtain and jade curtain the legend of jewelry the story of pearl girl 珠帘玉幕', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-yeu-dau-cua-toi', 'Người Tình Yêu Dấu Của Tôi', 'My Cherie Amour', 'https://phimimg.com/upload/vod/20240920-1/ec43ca6fb740782b8a2f900da3f5ce49.jpg', 'https://phimimg.com/upload/vod/20240920-1/d51c7ff27ee4f1fc1aa957179a483ef4.jpg', '<p>Anong là một tiểu thư thượng lưu được nhiều đàn ông tranh giành, với địa vị của cô, điều quan trọng là gia đình cô phải tìm cho cô một nửa xứng đôi. Luật sư đam mê Wichai ngẫu nhiên được giao nhiệm vụ sàng lọc những người chồng tiềm năng cho cô. Nhiệm vụ của anh là loại bỏ những ứng viên không phù hợp và mở đường cho em trai mình. Tuy nhiên, Wichai định nghĩa lại thế nào là xứng đáng, khiến Anong nhận ra rằng không ai phù hợp hơn chính Wichai. Tuy nhiên, anh chỉ coi cô như em dâu. Anong cố gắng chiếm được trái tim anh, ngay cả khi chỉ có một phần trăm cơ hội để một người phụ nữ tự tin như cô có thể có được một vị thánh như anh.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"ธนภพ ลีรัตนขจร","avatar":""},{"name":"อุรัสยา เสปอร์บันด์","avatar":""},{"name":"Suwatjanee Chaimusik","avatar":""},{"name":"Peterpan Tadsapon Wiwitawan","avatar":""},{"name":"พีรวิชญ์ อรรถชิตสถาพร","avatar":""},{"name":"Sirilak Kwong","avatar":""},{"name":"Namnung Suttidachanai","avatar":""},{"name":"Janjira Janpitakchai","avatar":""},{"name":"Pentaii Natthanit Praditthan","avatar":""},{"name":"Nisachon Tuamsoongnuen","avatar":""},{"name":"Bird Kittitat Pradab","avatar":""},{"name":"Wattikor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["百分之一","Nueng Nai Roi","My Cherie Amour","One in a Hundred","หนึ่งในร้อย"]', 1784690324223);
