INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-coc-2024', 'Bắt Cóc', 'Kidnap', 'https://phimimg.com/upload/vod/20240907-1/665ad4eb65bf52d669338c750718a64d.jpg', 'https://phimimg.com/upload/vod/20240907-1/e1ad071f7bd7c15d5742befc0fddf229.jpg', '<p>Cần tiền mua thuốc cho anh trai, Min đi làm kẻ bắt cóc. Khi người chủ của anh ta yêu cầu anh ta giết chàng trai trẻ giàu có mà anh ta đã bắt cóc, Min không thể tự mình bóp cò. Thay vào đó, anh ta nói với họ rằng công việc đã hoàn thành và đưa anh ta về nhà để giấu đi.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"ภวัต จิตต์สว่างดี","avatar":""},{"name":"ธนพล อู่สินทรัพย์","avatar":""},{"name":"ฐิภากร ฐิตะฐาน","avatar":""},{"name":"พรหมพิริยะ ทองพุทธรักษ์","avatar":""},{"name":"Kirati Puangmalee","avatar":""},{"name":"Napapat Sattha-atikom","avatar":""},{"name":"สุพจน์ จันทร์เจริญ","avatar":""},{"name":"Pympan Chalayanacupt","avatar":""},{"name":"Pitisak Yaowananon","avatar":""},{"name":"Teeradej Vitheepanich","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324223);
