INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-kich-manh-liet', 'Truy Kích Mãnh Liệt', 'Explosive Chase', 'https://phimimg.com/upload/vod/20241121-1/2b75e0dba8a55c16aa879c6a118892f3.jpg', 'https://phimimg.com/upload/vod/20241121-1/1487bc7162c08cfbd0b2b89c79167372.jpg', '<p>Thượng Hạ là một tài xế xe chuyên chở ngay thẳng và hài hước. Người bạn xấu tính của anh, Hà Phong, là một kẻ háo sắc và nghiện cờ bạc, một tay chơi lão luyện trong xã hội, ngày ngày lang thang trong nhiều nhóm khác nhau. Hà Phong thường gây rắc rối và hay nhờ Thượng Hạ giúp giải quyết. Với người ngoài, Hà Phong luôn nói Thượng Hạ là tài xế riêng của mình. Một ngày nọ, trong lúc chơi bài, Hà Phong nhận được một công việc có mức thù lao cao. Vì muộn giờ hẹn, trong lúc gấp gáp Hà Phong đã nhờ Thượng Hạ đi đón khách hộ.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ni Xinyu","avatar":""},{"name":"Lü Yanting","avatar":""},{"name":"Liang Xu","avatar":""},{"name":"Li Yan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["五星先生","爆裂追击"]', 1784690324223);
