INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('olivia-rodrigo-guts-world-tour', 'Olivia Rodrigo: GUTS World Tour', 'Olivia Rodrigo: GUTS World Tour', 'https://phimimg.com/upload/vod/20241120-1/6a73d4980be299450477cf99bf441ff4.jpg', 'https://phimimg.com/upload/vod/20241120-1/0682bb073556bf9f746091b5c7530378.jpg', '<p>Trong một buổi hòa nhạc cháy vé tại quê nhà LA, Olivia Rodrigo đã dồn hết tâm huyết vào một đêm nhạc sôi động với những bản hit đứng đầu bảng xếp hạng và những bản ballad pop-rock mạnh mẽ.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Olivia Rodrigo","avatar":""},{"name":"Hayley Brownell","avatar":""},{"name":"Camila Mora","avatar":""},{"name":"Moa Munoz","avatar":""},{"name":"Emily Rosenfield","avatar":""},{"name":"Daisy Spencer","avatar":""},{"name":"India Carney","avatar":""},{"name":"Anilee List","avatar":""},{"name":"Devan Smith","avatar":""},{"name":"Julia Alaimo","avatar":""},{"name":"Kyra Cole","avatar":""},{"name":"Iyana Fawcett","avatar":""},{"name":"Myranda Gibson","avatar":""},{"name":"Forest Lee","avatar":""},{"name":"Paris Simpson","avatar":""},{"name":"Alex White","avatar":""},{"name":"Chappell Roan","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Olivia Rodrigo: GUTS World Tour"]', 1784690324223);
