INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-truy-duoi-toc-do', 'Cuộc Truy Đuổi Tốc Độ', 'Get Fast', 'https://phimimg.com/upload/vod/20241120-1/d425b2adfe8024dd152d87889002822a.jpg', 'https://phimimg.com/upload/vod/20241120-1/01d3f61f54341e00ac1df84f5eb332c5.jpg', '<p>Khi đối tác bị bắt cóc sau phi vụ trộm hàng triệu đô từ tay trùm ma túy tàn nhẫn Nushi, tay trộm Alex buộc phải hợp tác với Ryan, một cậu bé mồ côi nổi loạn, để giải cứu bạn mình. Nushi cử The Cowboy, sát thủ đáng tin cậy nhưng đầy quyến rũ, truy đuổi hai người. Những màn đấu súng, rượt đuổi tốc độ và những vụ nổ kịch tính mang lại lợi thế cho cặp đôi bất đắc dĩ, nhưng liệu họ có thể duy trì cuộc chơi này bao lâu trước khi mọi thứ sụp đổ?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"James Clayton","avatar":""},{"name":"Lou Diamond Phillips","avatar":""},{"name":"Fei Ren","avatar":""},{"name":"Lee Majdoub","avatar":""},{"name":"Alisha Ahamed","avatar":""},{"name":"Philip Granger","avatar":""},{"name":"James Hutson","avatar":""},{"name":"Elan Ross Gibson","avatar":""},{"name":"Suleiman Abutu","avatar":""},{"name":"Michael Matic","avatar":""},{"name":"Tefari Thompson","avatar":""},{"name":"Bradley Stryker","avatar":""},{"name":"Simon Chin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Get Fast"]', 1784690324223);
