INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-giai-cuu-vi-dai', 'Cuộc Giải Cứu Vĩ Đại', 'Striking Rescue', 'https://phimimg.com/upload/vod/20241120-1/ad2a87a19e18d83bdf8125a95dbced08.jpg', 'https://phimimg.com/upload/vod/20241120-1/67fcb707f2539025756778104dfa921e.jpg', '<p>Chuyên gia an ninh đã nghỉ hưu tên là Bảo An bắt cóc Hà Tình, một cô gái trẻ xuất thân từ một gia đình giàu có, với ý định trả thù cho vợ con mình nhưng lại vô tình giúp cô thoát khỏi sự tiêu diệt của bọn buôn ma túy. Hà Tình tuy còn trẻ nhưng có tâm hồn chín chắn. Đối mặt với tình thế tiến thoái lưỡng nan giữa sự sống và cái chết của cha cô, cô đơn và bất lực, cô đã thực sự đề nghị hợp tác với Bảo An, kẻ thù muốn giết cha cô, và họ cùng nhau hợp tác. lên đường đi tìm cha.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tony Jaa","avatar":""},{"name":"Eason Hung","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Philip Keung Hiu-Man","avatar":""},{"name":"Chen Duo-Yi","avatar":""},{"name":"Peng Bo","avatar":""},{"name":"Yu Bolin","avatar":""},{"name":"Mao Fan","avatar":""},{"name":"Ge Shuai","avatar":""},{"name":"Zhao Leiqi","avatar":""},{"name":"Yang Dachuan","avatar":""},{"name":"Zhang Tianqi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["驚天大營救","คนเดือดซัดนรก","نجات بزرگ Striking Rescue 2024","Rescate impactante","Fist of the Warrior","Striking Rescue","Venganza implacable","惊天大营救"]', 1784690324223);
