INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiec-nuoi-cua-huong-bac', 'Tiếc Nuối Của Hướng Bắc', 'Xiangbei Regret', 'https://phimimg.com/upload/vod/20241120-1/e6699bbbeaf92c880fb960f4d41ae74c.jpg', 'https://phimimg.com/upload/vod/20241120-1/0e240a3cdb950bb642746b6d81ef2cea.jpg', '<p>Nhiếp ảnh gia tự do Mạc Hướng Bắc mang thai ngoài ý muốn khi sự nghiệp của bạn trai Mộ Dĩ Nam đang trên đà phát triển. Mạc Hướng Bắc hy vọng bạn trai có thể ở bên mình nhiều hơn, trong khi Mộ Dĩ Nam lại muốn tăng tốc công việc để tạo dựng tương lai tốt hơn cho bạn gái và đứa con sắp chào đời. Dần dần, cả hai bắt đầu có những xung đột nhỏ. Từ nhỏ vốn thiếu thốn tình yêu thương, Mạc Hướng Bắc trở nên nhạy cảm và đa nghi, cuối cùng bất ngờ sảy thai. Cô rời bỏ cuộc sống cùng Mộ Dĩ Nam trong đêm, đi đến Đại Lý và mở một quán trọ nhỏ tên là &quot;Nhà trọ Tiếc Nuối,&quot; bắt đầu hành trình cứu rỗi bản thân.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bàng Hạn Thần","avatar":""},{"name":"Lam Bác","avatar":""},{"name":"Hạc Thu","avatar":""},{"name":"Lưu Hân Lôi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiangbei''s Regret","Xiangbei & Regret","向北的遺憾","向北的遗憾"]', 1784690324223);
