INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-song-trong-co-the-toi', 'Cô Gái Sống Trong Cơ Thể Tôi', 'The Girl Inside Me', 'https://phimimg.com/upload/vod/20241104-1/eef43e9983b6c7835885e27f8dbee0f3.jpg', 'https://phimimg.com/upload/vod/20241104-1/6d01a33018fbd7786d5c4bc14c539dd9.jpg', '<p>Linh hồn của Tiêu Tiêu bị giục cưới vô tình xuyên vào cơ thể của một người đàn ông cổ đại và bắt đầu hành trình vui vẻ chia sẻ cơ thể của mình với Sở Tiêu Nhiên, một thợ tắm cổ đại. Tiêu Tiêu sử dụng một túi bách bảo có thể lấy ra bất kỳ vật phẩm hiện đại nào để giúp Sở Tiêu Nhiên theo đuổi thành công công chúa lạnh lùng. Đồng thời trong quá trình đó, cô cũng sử dụng cơ thể của Sở Tiêu Nhiên để chọc ghẹo anh chàng đẹp trai.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"陈芳彤","avatar":""},{"name":"王澤軒","avatar":""},{"name":"Yixia A","avatar":""},{"name":"雷艺昊","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["住在我身體裡的那個她","The Girl Inside Me","住在我身体里的那个她"]', 1784690324223);
