INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sat-nhan', 'Trò Chơi Sát Nhân', 'Stream', 'https://phimimg.com/upload/vod/20241118-1/6ab50b853d130e12e06009153980df50.jpg', 'https://phimimg.com/upload/vod/20241118-1/84f8c9521dd106d80d17646b55192b66.jpg', '<p>Stream 2024 xoay quanh gia đình Keenan, những người chỉ muốn có một kỳ nghỉ cuối tuần đơn giản. Tuy nhiên, chuyến đi tưởng chừng bình yên này nhanh chóng biến thành một cơn ác mộng khi bốn kẻ sát nhân bệnh hoạn, tham gia vào một trò chơi tàn ác, chiếm giữ khách sạn và thi đua nhau giết hại tất cả các khách lưu trú. Các tên sát nhân không chỉ đơn thuần giết người, mà còn thi nhau thực hiện những vụ giết hại sáng tạo và khủng khiếp nhất, biến kỳ nghỉ của gia đình Keenan thành một cuộc chạy trốn để giữ mạng sống trong bối cảnh hỗn loạn và kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Combs","avatar":""},{"name":"Charles Edwin Powell","avatar":""},{"name":"Danielle Harris","avatar":""},{"name":"Wesley Holloway","avatar":""},{"name":"Sydney Malakeh","avatar":""},{"name":"Tim Reid","avatar":""},{"name":"Dee Wallace","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Jason Leavy","avatar":""},{"name":"David Howard Thornton","avatar":""},{"name":"Liana Pirraglia","avatar":""},{"name":"Mark Haynes","avatar":""},{"name":"Jadon Cal","avatar":""},{"name":"Andrew Rogers","avatar":""},{"name":"Michael Leavy","avatar":""},{"name":"Dave Sheridan","avatar":""},{"name":"Mark Holton","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夺命假期","استریم","Stream"]', 1784690324223);
