INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-anh-cong-duoc-toi', 'Đố Anh Còng Được Tôi', 'I, The Executioner', 'https://phimimg.com/upload/vod/20241118-1/3b9d2f3c9a5cf65d15a23db8d0c870ac.jpg', 'https://phimimg.com/upload/vod/20241118-1/9f929fc12384573847849f8786f16ae2.jpg', '<p>Các thanh tra kỳ cựu nổi tiếng đã hoạt động trở lại! Thám tử Seo Do-cheol (HWANG Jung-min) và đội điều tra tội phạm nguy hiểm của anh không ngừng truy lùng tội phạm cả ngày lẫn đêm, đặt cược cả cuộc sống cá nhân của họ. Nhận một vụ án sát hại một giáo sư, đội thanh tra nhận ra những mối liên hệ với các vụ án trong quá khứ và nảy sinh những nghi ngờ về một kẻ giết người hàng loạt. Điều này đã khiến cả nước rơi vào tình trạng hỗn loạn. Khi đội thanh tra đi sâu vào cuộc điều tra, kẻ sát nhân đã chế nhạo họ bằng cách công khai tung ra một đoạn giới thiệu trực tuyến, chỉ ra nạn nhân tiếp theo và làm gia tăng sự hỗn loạn. Để giải quyết mối đe dọa ngày càng leo thang, nhóm đã kết nạp một sĩ quan tân binh trẻ Park Sun-woo (JUNG Hae-in), dẫn đến những khúc mắc và đầy rẫy bất ngờ trong vụ án.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Hwang Jung-min","avatar":""},{"name":"Jung Hae-in","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Jang Yoon-ju","avatar":""},{"name":"Kim Si-hoo","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Shin Seung-hwan","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Byun Hong-jun","avatar":""},{"name":"Ahn Bo-hyun","avatar":""},{"name":"Heo Joon-ho","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Park Jun-myun","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Joo Bo-bi","avatar":""},{"name":"Kim Won-","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Veteran 2","I, The Executioner","I, The Executioner : A Veteran Story","베테랑 2"]', 1784690324223);
