INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ban-hang-can-man', 'Người Bán Hàng Cần Mẫn', 'A Virtuous Business', 'https://phimimg.com/upload/vod/20241023-1/9dc909358a9d14774d97f04a10463274.jpg', 'https://phimimg.com/upload/vod/20241023-1/c6f0e39a58716d6359d4393caf94eac1.jpg', '<p>Tìm kiếm mục đích, cơ hội và sự độc lập, bốn người phụ nữ nông thôn khởi nghiệp kinh doanh sản phẩm dành cho người lớn vào năm 1992 – và hành trình khám phá bản thân mở ra từ đây.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"김소연","avatar":""},{"name":"연우진","avatar":""},{"name":"김성령","avatar":""},{"name":"김선영","avatar":""},{"name":"Lee Se-hee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["یک تجارت شرافتمندانه","یک تجارت کارآمد","貞淑的推銷","A Virtuous Business","정숙한 세일즈"]', 1784690324223);
