INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-da-tinh-ha', 'Vĩnh Dạ Tinh Hà', 'Love Game In Eastern Fantasy', 'https://phimimg.com/upload/vod/20241101-1/4059b8a71f9caab33066389ee2630fe5.jpg', 'https://phimimg.com/upload/vod/20241101-1/3757ed8c6566d61cea4ef09246f7918e.jpg', '<p>Là câu chuyện cứu rỗi, chữa lành lẫn nhau giữa hai nhân vật chính. Đêm vĩnh hằng là lúc chạng vạng, khúc biệt ly từ cây sáo sênh. Bản thân hắn - Mộ Thanh (Đinh Vũ Hề) là &quot;quái vật&quot;, không được người đời dung thứ, cũng không dám để lộ mặt thật của mình. Nhưng hiện tại đúng là có một người, ngoại trừ tỷ tỷ hắn, ở gần hắn hơn bất cứ ai, cô gái mang tên Lăng Diệu Diệu</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngu Thư Hân","avatar":""},{"name":"Đinh Vũ Hề","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["O jogo do amor em uma fantasia oriental","Yong Ye Xing He","黑蓮花攻略手冊","Hei Lian Hua Gong Lue Shou Ce","黑莲花攻略手册","凌妙妙来了","Galaxia de la noche eterna","เกมรักแดนฝัน","Black Lotus Tactics Manual","Eternal Night of Star River","Black Lotus Strategy Manual","Eternal Night Galaxy","The Guide to Capturing a Black Lotus","Love Game in Eastern Fantasy","Sổ Tay Công Lược Hắc Liên Hoa","永夜星河"]', 1784690324223);
