INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vinh-da-tinh-ha', 'Vĩnh Dạ Tinh Hà', 'Love Game In Eastern Fantasy', 'vĩnh dạ tinh hà love game in eastern fantasy ngu thư hân đinh vũ hề o jogo do amor em uma fantasia oriental yong ye xing he 黑蓮花攻略手冊 hei lian hua gong lue shou ce 黑莲花攻略手册 凌妙妙来了 galaxia de la noche eterna เกมรักแดนฝัน black lotus tactics manual eternal night of star river black lotus strategy manual eternal night galaxy the guide to capturing a black lotus love game in eastern fantasy sổ tay công lược hắc liên hoa 永夜星河', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dao-trung-nhi', 'Gia Đạo Trung Nhị', '家道中二', 'https://phimimg.com/upload/vod/20240522-1/8f72503e2f9a91c42d776c415589e88c.jpg', 'https://phimimg.com/upload/vod/20240522-1/2fed507c6e707c0b332d87405b070f47.jpg', '<p>Tất cả những người sinh ra trong thế kỷ 20 đều đã bước vào hàng ngũ của tuổi già. Trong tương lai không xa, khi thế hệ sau 80, 90 đã lên chức ông bà, công nghệ sẽ phát triển hơn, 666G sẽ phổ biến trên toàn cầu, cuộc sống sẽ tươi đẹp hơn. rất tiện lợi. Trong một gia đình sáu người mà ai cũng nghiện Chuchu, ông nội của nhân vật chính lần thứ hai trở thành người trì hoãn và quyết tâm trở thành vua trì hoãn trong thế giới truyện tranh! Ngay trước khi thời hạn sắp vượt quá thời hạn của người trì hoãn nổi tiếng trong lịch sử, biên tập viên truyện tranh không chịu nổi đã thực sự cử một &quot;cảnh sát hai chiều&quot; chuyên nghiệp đến chấm dứt dự án của ông nội, và cuối cùng phải đối mặt với tình huống xấu hổ khi gặp chướng ngại vật khắp nơi và không có ai tiếp quản. Khi muốn xuất bản một tác phẩm mới, anh nhận thấy mình đã ở nhà quá lâu và xa lánh xã hội. Để tác phẩm mới đạt được thành công, ông nội anh đã thu thập được với sự giúp đỡ của gia đình. những câu chuyện từ mọi khía cạnh của xã hội để trải nghiệm những khía cạnh khác nhau của cuộc sống trong thời đại mới Từ câu lạc bộ truyện tranh nhỏ ở trường Tôn Tử, anh đã trải qua Những khúc mắc bắt đầu trỗi dậy. Gia đình kết nối mọi khía cạnh của câu chuyện hài và dẫn dắt mọi người vào cuộc sống của học sinh cấp hai trong tương lai gần.</p>', 'Hoàn Tất (120/120)', 120, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324223);
