INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liet-diem-chi-vu-canh-ky', 'Liệt Diễm Chi Vũ Canh Kỷ', 'Burning Flames', 'https://phimimg.com/upload/vod/20240310-1/b15b077200fbc0a0c4f3ac4c1f2c6275.jpg', 'https://phimimg.com/upload/vod/20240310-1/9c9414cdff091e5f4acf517f0103d125.jpg', '<p>Được chuyển thể từ tác phẩm hoạt hình nổi tiếng, Liệt Diễm Chi Vũ Canh Kỷ kể về câu chuyện của hoàng tử nhân tộc Ngũ Canh. Phải chịu cảnh nước mất nhà tan và trở thành nô lệ, Ngũ Canh luôn ôm trong lòng khát vọng báo thù cho cha mẹ và nhân tộc. Dựa vào ý chí kiên cường của mình, anh dốc hết sức mình luyện tập, vượt qua nhiều khó khăn khác nhau để thực hiện kế hoạch trả thù và tìm kiếm sự tự do.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Hình Phi","avatar":""},{"name":"Chúc Tự Đan","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324224);
