INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-mong-quy-ly', 'Đại Mộng Quy Ly', 'Fangs Of Fortune', 'https://phimimg.com/upload/vod/20241027-1/806c85ac04dea3442d703f7ace201461.jpg', 'https://phimimg.com/upload/vod/20241027-1/8d97b13538ef437420e760b3192b6bb2.jpg', '<p>"Đại Mộng Quy Li" là một bộ phim cổ trang do Hầu Minh Hạo ("Thợ Săn Tâm Trạch", "Hộ Tâm"), Trần Đô Linh ("Liên Hoa Lâu"), Điền Gia Thụy ("Vân Chi Vũ"), Trình Tiêu ("Khanh Khanh Ngã Tâm") đóng vai chính. Bộ phim này được lấy cảm hứng từ "Sơn Hải Kinh", kể về một câu chuyện truyền kỳ quỷ lệ về "yêu muốn bắt yêu". Trong thời kỳ Trinh Nguyên, do nữ thần Bạch Tắc, người kiểm soát hai giới người và yêu bất ngờ mất mạng, Bạch Tắc mất tích không dấu vết, yêu thú hoành hành trên đất người, gây ra nhiều vụ án đẫm máu. Trong thời điểm này, "Chu Yếm", thủ lĩnh đạo của bách yêu đã biến hình thành người có tên là Triệu Viễn Châu (Hầu Minh Hạo đóng), tự nguyện "sát cánh" với triều đình, đề xuất hỗ trợ triều đình thành lập Tập Yêu Ti, bắt yêu dẹp loạn.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"侯明昊","avatar":""},{"name":"陈都灵","avatar":""},{"name":"Tian Jiarui","avatar":""},{"name":"程瀟","avatar":""},{"name":"Lin Ziye","avatar":""},{"name":"Xu Zhenxuan","avatar":""},{"name":"Yan An","avatar":""},{"name":"Lai Weiming","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["大梦归离","大夢歸離","The Story of Mystics","Fangs of Fortune","Đại Mộng Quy Ly"]', 1784690324224);
