INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-phan-cong-cua-phu-nu', 'Sự Phản Công Của Phụ Nữ', 'The Fevengers', 'https://phimimg.com/upload/vod/20241031-1/88e44355e2e60d523916be2f01143a64.jpg', 'https://phimimg.com/upload/vod/20241031-1/d9cfcb4f6ef94620a43ff01f5d864043.jpg', '<p>Ôn Nhược Quân là người thừa kế của một tập đoàn trang sức. Sau một vụ bắt cóc, cô đã phát hiện ra chồng cô, Cố Diễm Thành, ngoại tình với bạn thân của mình. Không chỉ vậy, cuộc hôn nhân của hai người cũng là một kế hoạch lừa đảo tài sản được anh ta trù mưu từ trước. Sau khi phát hiện ra sự thật, Ôn Nhược Quân gặp được Lâm Gia Nghi, một nạn nhân khác của Cố Diễm Thành. Hai người phụ nữ quyết định hợp sức cùng những nạn nhân khác để trả thù gã đàn ông cặn bã này.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"夏若妍","avatar":""},{"name":"文淵","avatar":""},{"name":"Yang Xueer","avatar":""},{"name":"魏嘉","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Женская месть","女人的反攻","The Fevengers"]', 1784690324224);
