INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-da', 'Ma Da', 'The Drowning Spirit', 'https://phimimg.com/upload/vod/20241116-1/3747ec0cb2bbc3679512ef163621eefc.jpg', 'https://phimimg.com/upload/vod/20241116-1/e851bfbfc2dc5b2f9463571e5fba6734.jpg', '<p>Phim kể về hành trình của bà Lệ, người làm nghề vớt xác người chết trên sông để đưa về với gia đình. Trong quá trình làm nghề, bà Lệ đắc tội với Ma Da, một oan hồn sống dưới sông nước thường xuyên kéo chân người để thế mạng cho mình đi đầu thai. n oán của cả hai khiến cho Ma Da bắt mất bé Nhung, con gái của bà Lệ . Bà Lệ phải nhờ đến sự giúp đỡ của những người bên cạnh để cùng nhau lên đường tìm cách cứu bé Nhung và mở ra những bí mật đằng sau oan hồn Ma Da kia.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Việt Hương","avatar":""},{"name":"Dạ Chúc","avatar":""},{"name":"Trung Dân","avatar":""},{"name":"Diệu Đức","avatar":""},{"name":"Thành Lộc","avatar":""},{"name":"Cẩm Ly","avatar":""},{"name":"Duy Anh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Fancy Walk","화려한 외출","hwa-ryeo-han oi-chool","Love Lesson","愛的教慾","華麗的外出","情欲奏鳴曲"]', 1784690324224);
