INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-doat-menh-yeu-tang', 'Địch Nhân Kiệt: Đoạt Mệnh Yêu Tăng', 'Detective Di Renjie: The Deadly Monk', 'https://phimimg.com/upload/vod/20241115-1/d22dd5a145af18a31c46569ffe66298e.jpg', 'https://phimimg.com/upload/vod/20241115-1/f88dbc464d0e887c29057dbebd0fd3ef.jpg', '<p>Địch Nhân Kiệt nhận lệnh tuần tra các con đường ở Giang Nam. Khi đi qua thành Lâm An, ông bị cuốn vào một vụ án các thiếu nữ mất tích bí ẩn. Qua quá trình điều tra sâu rộng, ông phát hiện vụ án có liên quan đến một tà giáo dâm ô tại địa phương. Vụ án đầy rẫy những nghi ngờ, phức tạp và đằng sau là bóng dáng mờ ảo của yêu tăng. Bằng trí tuệ phi thường, Địch Nhân Kiệt dần dần lần ra từng manh mối, từng bước tiến gần đến sự thật, mở ra một cuộc hành trình điều tra nơi chính nghĩa và tà ác đối đầu nhau.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Luo Liqun","avatar":""},{"name":"Shang Na","avatar":""},{"name":"Liu Jin","avatar":""},{"name":"Norman Tsui Siu-Keung","avatar":""},{"name":"Huang Wei","avatar":""},{"name":"Zhao Zhiyan","avatar":""},{"name":"Tie Niu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Di Ren Jie Zhi Duo Ming Yao Seng","Detective Dee and the Deadly Monk","Detective Dee and Deadly Demon Monk"]', 1784690324224);
