INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-ra-em-la-dinh-menh-doi-anh', 'Hoá Ra Em Là Định Mệnh Đời Anh', 'You Are My Destiny', 'https://phimimg.com/upload/vod/20241108-1/1925d268d7f50d226da675e8bb5b4d4a.jpg', 'https://phimimg.com/upload/vod/20241108-1/a1935f9da0bed6f7f4061e126b4815bf.jpg', '<p>Thời hạn hợp đồng hôn nhân sắp kết thúc, sếp tổng độc đoán trung thành Nhiếp Lăng Phong vì muốn bảo vệ người tình trong mộng, đồng thời là người vợ hợp đồng Cố Á San nên đã cải trang thành vệ sĩ, luôn ở bên cạnh vợ mình, suýt nữa tự cắm sừng mình luôn!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huang Xin","avatar":""},{"name":"Pei Zhengzheng","avatar":""},{"name":"代羽宸","avatar":""},{"name":"范迪禹","avatar":""},{"name":"Kanice Lau Ka Ki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["现身吧！老公","Yuan Lai Ni Jiu Shi Wo De Ming Zhong Zhu Ding","原來你就是我的命中注定","原来你就是我的命中注定"]', 1784690324224);
