INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-ra-em-la-dinh-menh-doi-anh', 'Hoá Ra Em Là Định Mệnh Đời Anh', 'You Are My Destiny', 'hoá ra em là định mệnh đời anh you are my destiny huang xin pei zhengzheng 代羽宸 范迪禹 kanice lau ka ki 现身吧！老公 yuan lai ni jiu shi wo de ming zhong zhu ding 原來你就是我的命中注定 原来你就是我的命中注定', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-vien', 'Đoàn Viên', 'Our Days', 'https://phimimg.com/upload/vod/20241030-1/7c3eace517c85fa5fb4f70dbc0ff60ba.jpg', 'https://phimimg.com/upload/vod/20241030-1/2a6eea44da81b5dc3ac09886b1d60fa2.jpg', '<p>Ba cô con gái của Hướng Chất Quân lần lượt sinh sống ở Thượng Hải, Côn Sơn và Tô Châu. Hướng Tiền 35 tuổi, sự nghiệp có tiến triển tốt, Hướng Trung 31 tuổi, đang tích cực phấn đấu; Hướng Nam 26 tuổi, tính cách hồn nhiên ngây thơ. Hôn nhân của ba cô con gái nhà họ Hướng liên tiếp thất bại, họ giúp đỡ và động viên lẫn nhau. Dưới sự hướng dẫn và khuyên giải của cha mẹ, Hướng Trung thoát khỏi gia đình chồng hay gây sự vô lý và lấy lại niềm tin để vun vén cuộc hôn nhân; Hướng Tiền nhận ra sự đạo đức giả của người chồng Cao Bình và tìm lại được hướng đi cho sự nghiệp và cuộc đời; Hướng Nam không còn cảm thấy bối rối nữa, hiểu rõ và trưởng thành hơn về cuộc hôn nhân và bản thân.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Baihe","avatar":""},{"name":"李纯","avatar":""},{"name":"王玉雯","avatar":""},{"name":"Chen He","avatar":""},{"name":"章濤","avatar":""},{"name":"丁勇岱","avatar":""},{"name":"劉佳","avatar":""},{"name":"夏雨","avatar":""},{"name":"Yu Xiaowei","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["好团圆"]', 1784690324224);
