INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-cua-ong-trum', 'Giấc Mơ Của Ông Trùm', 'Emilia Pérez', 'https://phimimg.com/upload/vod/20241114-1/5623de2fbb0c526d7a20ae3a2f283a17.jpg', 'https://phimimg.com/upload/vod/20241114-1/73004bb3de6c66b181181323280748b3.jpg', '<p>Tại Mexico, một luật sư nhận được đề nghị bất ngờ từ một ông trùm khét tiếng trong giới cartel. Ông ta muốn nghỉ hưu và biến mất khỏi thế giới tội phạm bằng cách thực hiện ước mơ bí mật trở thành một người phụ nữ. Phim khám phá hành trình chuyển đổi đầy thử thách và ly kỳ của ông trùm này khi anh phải đối mặt với những rào cản không chỉ từ phía xã hội mà còn từ chính những kẻ thù trong bóng tối.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Karla Sofía Gascón","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Adriana Paz","avatar":""},{"name":"Edgar Ramírez","avatar":""},{"name":"Mark Ivanir","avatar":""},{"name":"Eduardo Aladro","avatar":""},{"name":"Emiliano Hasan","avatar":""},{"name":"James Gerard","avatar":""},{"name":"Eric Geynes","avatar":""},{"name":"Agathe Bokja","avatar":""},{"name":"Chun-Ting Lin","avatar":""},{"name":"Stéphane Ly-Cuong","avatar":""},{"name":"Line Phé","avatar":""},{"name":"Pascal Toussirot","avatar":""},{"name":"Karla Lazo","avatar":""},{"name":"Alonso Venegas-Flore","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["En busca de Emilia Pérez","EMILIA PÉREZ","毒王女人夢","Էմիլիա Պերեզ","璀璨女人夢","艾米莉亚·佩雷斯","毒王女人梦","璀璨女人梦","Emilia Pérez"]', 1784690324224);
