INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arya-ban-ben-thinh-thoang-lai-treu-gheo-toi-bang-tieng-nga', 'Arya bàn bên thỉnh thoảng lại trêu ghẹo tôi bằng tiếng Nga', 'Alya Sometimes Hides Her Feelings in Russian', 'https://phimimg.com/upload/vod/20240713-1/ba18b92509f3603a08f9478ef0e428de.jpg', 'https://phimimg.com/upload/vod/20240713-1/7e2009b2be50d6a5baecefce71ca8788.jpg', '<p>Masachika Kuse ngồi cạnh Alya, một cô gái mang hai dòng máu Nga và Nhật. Cô ấy xinh đẹp, kiêu kỳ và là một học sinh xuất sắc, trong khi Masachika thì ngốc nghếch và nổi tiếng là kẻ lười biếng. Anh ấy là mục tiêu dễ dàng cho những bình luận của cô ấy bằng tiếng Nga, điều mà cô ấy rất vui khi dịch được - ngoại trừ việc anh ấy có thể hiểu những gì cô ấy thực sự đang nói.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"天﨑滉平","avatar":""},{"name":"上坂すみれ","avatar":""},{"name":"丸岡和佳奈","avatar":""},{"name":"藤井ゆきよ","avatar":""},{"name":"会沢紗弥","avatar":""},{"name":"河瀬茉希","avatar":""},{"name":"石川界人","avatar":""},{"name":"長谷川育美","avatar":""},{"name":"青山吉能","avatar":""},{"name":"酒井広大","avatar":""},{"name":"市川太一","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324224);
