INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sao-khong-ai-nho-den-the-gioi-cua-toi', 'Tại Sao Không Ai Nhớ Đến Thế Giới Của Tôi', 'Why Does Nobody Remember Me in This World', 'https://phimimg.com/upload/vod/20241113-1/a5c9414c6298da0dcc84f4cb1f48d417.jpg', 'https://phimimg.com/upload/vod/20241113-1/65272383a3f0ccd1f55e002390b8e0d0.jpg', '<p>Sid - anh hùng đã dẫn dắt nhân loại chiến thắng trong cuộc chiến tranh giành quyền bá chủ Trái Đất, bỗng nhiên thấy mình bị xóa sổ khỏi lịch sử. Thế giới thay đổi, con người thất bại trước rồng và ác quỷ, và Sid trở thành kẻ vô danh. Kai là một cậu bé bí ẩn miễn nhiễm với sự thay đổi này, cũng là người duy nhất nhớ về Sid. Cùng Rinne, một cô gái bí ẩn, Kai quyết tâm khôi phục ký ức cho thế giới và đưa Sid trở lại vị trí anh hùng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shoya Chiba","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Lynn","avatar":""},{"name":"Hana Hishikawa","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Seiichiro Yamashita","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["¿Por qué nadie me recuerda en este mundo?","为何无人记得我的世界？","Why Does Nobody Remember Me in This World?","Naze Boku no Sekai wo Daremo Oboeteinai no ka?","なぜ僕","Nazeboku","¿Por qué nadie recuerda mi mundo?","為何我的世界被遺忘了？","Kí Ức Mong Manh Về Thế Giới Của Tôi","なぜ僕の世界を誰も覚えていないのか？"]', 1784690324224);
