INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-sao-khong-ai-nho-den-the-gioi-cua-toi', 'Tại Sao Không Ai Nhớ Đến Thế Giới Của Tôi', 'Why Does Nobody Remember Me in This World', 'tại sao không ai nhớ đến thế giới của tôi why does nobody remember me in this world shoya chiba kana ichinose haruka shiraishi lynn hana hishikawa sayumi suzushiro seiichiro yamashita ¿por qué nadie me recuerda en este mundo? 为何无人记得我的世界？ why does nobody remember me in this world? naze boku no sekai wo daremo oboeteinai no ka? なぜ僕 nazeboku ¿por qué nadie recuerda mi mundo? 為何我的世界被遺忘了？ kí ức mong manh về thế giới của tôi なぜ僕の世界を誰も覚えていないのか？', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-huong-nhu-mong', 'Trầm Hương Như Mộng', 'Agarwood Like A Dream', 'https://phimimg.com/upload/vod/20241107-1/3e22dfd6e5f5a607901c9c91c3e6624a.jpg', 'https://phimimg.com/upload/vod/20241107-1/0eafc3ef2f57577034c751545eef1245.jpg', '<p>Trong phim Trầm Hương Như Mộng, Doanh Hà Minh kết hôn vào gia đình kẻ thù để minh oan cho người mẹ đã qua đời. Cô trở thành thiếp của Diệp Bất Hoàn và bắt đầu một cuộc truy tìm sự thật phức tạp. Trải qua nhiều sóng gió, họ dần nhận ra tình cảm giữa họ không thể phủ nhận. Li Jiu Lin, Zhang Ya Zhuo, Ran Xu cùng với dàn diễn viên khác đã tái hiện một câu chuyện lãng mạn đầy xúc cảm và căng thẳng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Jiulin","avatar":""},{"name":"Zhang Yazhuo","avatar":""},{"name":"Ran Xu","avatar":""},{"name":"Ma Junke","avatar":""},{"name":"Tong Tong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Eaglewood Like a Dream","沉香如夢夜不寒","沉香如梦夜不寒"]', 1784690324224);
