INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tram-huong-nhu-mong', 'Trầm Hương Như Mộng', 'Agarwood Like A Dream', 'trầm hương như mộng agarwood like a dream li jiulin zhang yazhuo ran xu ma junke tong tong eaglewood like a dream 沉香如夢夜不寒 沉香如梦夜不寒', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-yen-nguoi-phe-minh', 'Đứng Yên! Người Phe Mình!', 'I Am Not Your Enemy', 'https://phimimg.com/upload/vod/20241107-1/19f91de8d691355e271bba0a178345ac.jpg', 'https://phimimg.com/upload/vod/20241107-1/8c0e243cea275a77ea9827336e856850.jpg', '<p>Mị Hữu Sơ, con gái của tướng quân từng vì tình mà cưới thế tử Tô Bất Tiếu, nhưng hắn lại ngoại tình, phản bội và thảm sát gia đình cô. Sau khi hồi sinh, Mị Hữu Sơ quyết tâm trả thù, cô rèn luyện võ nghệ và lên kế hoạch giết &quot;người chồng cũ&quot; Tô Bất Tiếu để trả lại mối hận xưa. Nào ngờ Tô Bất Tiếu giờ đã bị một người chơi từ thế giới khác xuyên không nhập vào, với mục tiêu chinh phục nữ chính trời chọn Mị Hữu Sơ. Hai người với hai bí mật riêng không ai biết, bắt đầu một trò chơi sinh tử &quot;anh đuổi cô giết&quot;. Khi một người bí ẩn với hình xăm hoa sen xuất hiện, nhà họ Mị một lần nữa lâm nguy, buộc Mị Hữu Sơ và Tô Bất Tiếu phải liên minh để đạt được mục đích của riêng mình. Họ cùng bắt đầu hành trình mạo hiểm và hài hước, trong khoảnh khắc sinh tử, họ dần nảy sinh tình cảm, cuối cùng cùng nhau phá giải âm mưu, cũng tìm thấy tình yêu và hạnh phúc.</p>', 'Tập 20', 20, 'series', 'ongoing', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guan Xin","avatar":""},{"name":"Zhang Teng","avatar":""},{"name":"Chen Zhihui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["別動！自己人","I am not your enemy","别动！自己人"]', 1784690324224);
