INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dung-yen-nguoi-phe-minh', 'Đứng Yên! Người Phe Mình!', 'I Am Not Your Enemy', 'đứng yên! người phe mình! i am not your enemy guan xin zhang teng chen zhihui 別動！自己人 i am not your enemy 别动！自己人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('atrimy-dear-moments', 'ATRI-My Dear Moments', 'ATRI-My Dear Moments', 'https://phimimg.com/upload/vod/20240729-1/8c30c6830dfff2809f52b9021e379ed7.jpg', 'https://phimimg.com/upload/vod/20240729-1/cb61aacc6225a51b017f53d357c920a1.jpg', '<p><span style="text-wrap: nowrap;">Trong tương lai gần, nước biển dâng đột ngột và không giải thích được đã khiến phần lớn nền văn minh nhân loại chìm trong nước. Ikaruga Natsuki, một cậu bé mất mẹ và chân trong một vụ tai nạn vài năm trước, vỡ mộng trở về sau cuộc sống khắc nghiệt ở thành phố lớn để tìm lại ngôi nhà quê cũ của mình đã bị biển nuốt chửng một nửa. Không có gia đình, tất cả những gì anh có mang tên mình là con tàu và tàu ngầm do bà nội hải dương học để lại cho anh và các khoản nợ của bà.</span></p><p><span style="text-wrap: nowrap;">Hy vọng duy nhất của anh để khôi phục lại những giấc mơ cho tương lai mà anh đã đánh mất là tận dụng cơ hội do người đòi nợ đáng ngờ Catherine trao cho anh. Họ ra khơi tìm kiếm tàn tích bị chìm trong phòng thí nghiệm của bà ngoại anh nhằm tìm ra kho báu được đồn đại rằng bà đã để lại ở đó. Nhưng những gì họ tìm thấy không phải là của cải hay châu báu; đó là một cô gái kỳ lạ đang nằm ngủ trong quan tài dưới đáy biển. Atri.</span></p><p><span style="text-wrap: nowrap;">Atri là một người máy, nhưng vẻ ngoài và cảm xúc phong phú của cô sẽ đánh lừa bất cứ ai nghĩ rằng cô là một con người đang sống và đang thở. Để biết ơn vì đã được cứu, cô tuyên bố với Natsuki: &quot;Tôi muốn thực hiện mệnh lệnh cuối cùng của chủ nhân. Cho đến khi tôi làm được, tôi sẽ là chân của cậu!&quot;</span></p><p><span style="text-wrap: nowrap;">Tại một thị trấn nhỏ đang dần bị đại dương bao bọc, một mùa hè khó quên sắp bắt đầu với chàng trai và cô gái robot bí ẩn này...</span></p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"小野賢章","avatar":""},{"name":"赤尾ひかる","avatar":""},{"name":"髙橋ミナミ","avatar":""},{"name":"細谷佳正","avatar":""},{"name":"日笠陽子","avatar":""},{"name":"春野杏","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324224);
