INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-quoc-yeu-ho-phan-2', 'Chiến Quốc Yêu Hồ (Phần 2)', 'Sengoku Youko (Season 2)', 'https://phimimg.com/upload/vod/20240713-1/acea912039024a8fa22edebd65b00b25.jpg', 'https://phimimg.com/upload/vod/20240713-1/a338cb0a39c0d499c7f9a08432d3fa7e.jpg', '<p>Con người và katawara đang có chiến tranh, nhưng mỗi bên đều có những người hợp lực. Tama là một hồ ly yêu thương con người, trong khi anh trai sendou của cô, Jinka, lại coi thường họ. Cùng nhau, họ sử dụng sức mạnh biến đổi linh hồn để đánh bại katawara quái dị và chấm dứt những tệ nạn của thời đại hỗn loạn này. Số phận nào đang chờ đợi bộ đôi ở cuối hành trình?</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 29, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"斉藤壮馬","avatar":""},{"name":"高田憂希","avatar":""},{"name":"木村良平","avatar":""},{"name":"黒沢ともよ","avatar":""},{"name":"七海ひろき","avatar":""},{"name":"内田真礼","avatar":""},{"name":"乃村健次","avatar":""},{"name":"豊崎愛生","avatar":""},{"name":"稲田徹","avatar":""},{"name":"宮城一貴","avatar":""},{"name":"高垣彩陽","avatar":""},{"name":"鈴木愛奈","avatar":""},{"name":"津田健次郎","avatar":""},{"name":"東地宏樹","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324224);
