INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-oan-trong-vuon-xuan', 'Ai Oán Trong Vườn Xuân', 'Spring Garden', 'https://phimimg.com/upload/vod/20241106-1/f0f6bba77d8779c876e548ce2c601132.jpg', 'https://phimimg.com/upload/vod/20241106-1/46591e84a4089f40700a1e0b38572714.jpg', '<p>Ai Oán Trong Vườn Xuân là bộ phim kinh dị đến từ NSX của The Medium. Phim xoay quanh So-hee, người đã mất đi gia đình hạnh phúc của mình vì cái chết đột ngột của chồng, và trải qua những điều kỳ lạ, rùng rợn sau khi đến thăm Neulbom Garden, một ngôi biệt thự nông thôn bí ẩn do chồng cô để lại.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Jo Yoon-hee","avatar":""},{"name":"Kim Joo-ryoung","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Jeong In-kyeom","avatar":""},{"name":"Choo Ye-jin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Neulbom: The Cursed","Neulbom: Spring Garden","ร้านผีคนกิน","Neulbomgadeun","حديقة الربيع","늘봄가든"]', 1784690324224);
