INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-long-2024', 'Chiếc lồng', 'The Cage', 'https://phimimg.com/upload/vod/20241112-1/e31262696a41c7bb58a2328d7b50aba2.jpg', 'https://phimimg.com/upload/vod/20241112-1/4e40c003d77cbbdbb2cf722da0cfa8f1.jpg', '<p>Ôm mộng võ sĩ chuyên nghiệp, võ sĩ trẻ nọ chật vật thu hút sự chú ý cho đến khi một trận đấu bất ngờ mang đến cho anh cơ hội nổi tiếng và một đối thủ tàn bạo trong lồng sắt.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Franck Gastambide","avatar":""},{"name":"Melvin Boomer","avatar":""},{"name":"Georges St-Pierre","avatar":""},{"name":"Bosh","avatar":""},{"name":"Adel Bencherif","avatar":""},{"name":"Cyril Gane","avatar":""},{"name":"Salahdine Parnasse","avatar":""},{"name":"Morgan Charriere","avatar":""},{"name":"Abdoul Abdouraguimov","avatar":""},{"name":"Taylor Lapilus","avatar":""},{"name":"Ramzan Jembiev","avatar":""},{"name":"Anissa Meksen","avatar":""},{"name":"Bilel Jkitou","avatar":""},{"name":"Souleymane Cissokho","avatar":""},{"name":"Samy Sana","avatar":""},{"name":"Edwige Ahonto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Cage","Buret","เดอะ เคจ","La Cage"]', 1784690324224);
