INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-bach-huu-gioi', 'Hắc Bạch Hữu Giới', 'Black and White Rounded', 'https://phimimg.com/upload/vod/20241112-1/abc11402eebc38424db7ef48c38dadbe.jpg', 'https://phimimg.com/upload/vod/20241112-1/58c660c368ac9f4fd03b020a77037dc5.jpg', '<p>Chủ mới của biệt thự khi sửa sang nhà cũ thì phát hiện một số tiền lớn. Cảnh sát điều tra nguồn gốc số tiền này, nhưng phát hiện chủ cũ Bạch Quốc Uy đã ngã lầu mà chết. Cảnh sát lần theo manh mối, một loạt các vụ án kỳ lạ liên tiếp xảy ra; họ dần dần làm sáng tỏ từng sự thật. Một cuộc chiến giữa chính nghĩa và tà ác diễn ra giữa cảnh sát và thế lực hắc ám; cuộc chiến giữa cảnh sát và tội phạm vì thế mà trở nên gay gắt.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Xianshi","avatar":""},{"name":"Gao Lancun","avatar":""},{"name":"Miao Haojun","avatar":""},{"name":"Cao Qi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Hei Bai You Jie","Black and White Rounded","黑白有界"]', 1784690324224);
