INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-doc', 'Trừ Độc', 'The Enigma of Arrival', 'https://phimimg.com/upload/vod/20241112-1/5b9f6df04a93a905552cde5d92de279d.jpg', 'https://phimimg.com/upload/vod/20241112-1/3c92f503ce5d5d2ede14df40ec8fe4de.jpg', '<p>Cảnh sát phòng chống ma túy Dịch Vĩnh Chính được phái đi điều tra một vụ án ma túy và gặp lại người bạn cũ. Năm xưa, để cứu con trai mình, Đinh Chỉ Đồng đã gia nhập vào một tổ chức buôn ma túy, bị kẻ thù truy sát và chồng cũng qua đời vì cô. Sau khi suy nghĩ lại, Đinh Chỉ Đồng quyết định giao nộp bằng chứng cho Dịch Vĩnh Chính. Đáng tiếc, hành động của cô đã bị phát hiện từ trước. Cuối cùng, cô hợp tác với Dịch Vĩnh Chính, cùng nhau triệt phá tổ chức buôn ma túy và chấp nhận chịu sự trừng phạt của pháp luật.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yisheng Jiang","avatar":""},{"name":"Shi Zhaoqi","avatar":""},{"name":"Zhao Longhao","avatar":""},{"name":"Wei Lu","avatar":""},{"name":"Hongbiao Bai","avatar":""},{"name":"Baode Wang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["The Enigma of Arrival","破毒"]', 1784690324224);
