INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dieu-tra-nguoi-ngoai-hanh-tinh', 'Cuộc điều tra người ngoài hành tinh', 'Investigation Alien', 'https://phimimg.com/upload/vod/20241112-1/b48295c476d623daa586bf14eab14fc3.jpg', 'https://phimimg.com/upload/vod/20241112-1/72d7efffe50df785868d10579b0bf58b.jpg', '<p>Trong loạt phim tài liệu hấp dẫn này, phóng viên huyền thoại George Knapp đi khắp thế giới để khám phá bằng chứng mới về UFO, đồng thời điều tra sự hiện diện của họ trên Trái Đất.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"George Knapp","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["外星人之谜：30年调查记录","Undersøkelse: Romvesener","Investigation Alien"]', 1784690324224);
