INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-quai-thu', 'Truy Tìm Quái Thú', 'Rippy', 'https://phimimg.com/upload/vod/20241112-1/3a65ef00477fc96442067050b1958bde.jpg', 'https://phimimg.com/upload/vod/20241112-1/6eb1fe6a698123aa242c2ba48005a224.jpg', '<p>Sĩ quan cảnh sát trẻ Maddy quyết tâm sống xứng đáng với di sản của người cha đã khuất. Lòng dũng cảm của cô bị thử thách khi người dân địa phương bị con chuột túi thây ma xé xác một cách dã man. Khi con quái vật bất tử để lại dấu vết tàn sát, Maddy, với sự giúp đỡ của chú Schmitty lập dị và dì Donna kiên cường, phải dấn thân vào một trận chiến nguy hiểm để cứu thị trấn</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Michael Biehn","avatar":""},{"name":"Tess Haubrich","avatar":""},{"name":"Aaron Pedersen","avatar":""},{"name":"Angie Milliken","avatar":""},{"name":"Mungo McKay","avatar":""},{"name":"Nancy Rizk","avatar":""},{"name":"Don Bridges","avatar":""},{"name":"Molly Belle Wright","avatar":""},{"name":"Liam Greinke","avatar":""},{"name":"Mara Jean Quinn","avatar":""},{"name":"Aaron Davison","avatar":""},{"name":"Nathan Jones","avatar":""},{"name":"Tom Block","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Red","Зомби-кенгуру","Rippy"]', 1784690324224);
