INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-duoi-2024', 'Kẻ Săn Đuổi', 'The Hunted', 'https://phimimg.com/upload/vod/20241112-1/7b2edd6514074a2f42aa84eabc3be506.jpg', 'https://phimimg.com/upload/vod/20241112-1/de725af8bb684e50e9ae572d0db3cb4c.jpg', '<p>Phim kể về một nhóm người di tản sau khi tàu của họ bị lật tại Địa Trung Hải. Họ được cứu bởi những người giàu ở một hòn đảo, nhưng sự cứu rỗi nhanh chóng biến thành ác mộng khi những người cứu giúp trở thành những kẻ săn đuổi tàn nhẫn.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Lily Banda","avatar":""},{"name":"Alec Newman","avatar":""},{"name":"Mylène Jampanoï","avatar":""},{"name":"Marlene Kaminsky","avatar":""},{"name":"Vassilis Koukalani","avatar":""},{"name":"Kostis Kallivretakis","avatar":""},{"name":"Pigmalion Dadakaridis","avatar":""},{"name":"Argyris Gaganis","avatar":""},{"name":"Daphne Alexander","avatar":""},{"name":"Raj Bajaj","avatar":""},{"name":"Aurora Marion","avatar":""},{"name":"Ayman Al Aboud","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Hunted: Cacería Humana","The Hunted"]', 1784690324224);
