INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-cuong-nhiet-sau-khi-ket-hon', 'Tình Yêu Cuồng Nhiệt Sau Khi Kết Hôn', 'The Heir''s Forbidden Love', 'https://phimimg.com/upload/vod/20241107-1/f8b2ec66bc90143ee33c82cc985f86c1.jpg', 'https://phimimg.com/upload/vod/20241107-1/7e36418af7c61678bdbbc1b4694f261e.jpg', '<p>Cố An An, con gái của tập đoàn Cố thị, bất ngờ gặp biến cố trong gia đình. Mẹ cô rơi xuống vực một cách kỳ lạ bị hôn mê. Cha cô, Dạ Đình Phong, người nghiện cờ bạc, cũng tìm cách chiếm đoạt toàn bộ tài sản của gia đình nhà họ Cố. Lúc này, Cố An An quyết định kết hôn với cậu chủ cả nhà họ Hoắc Hoắc Tư Văn, con trai cả của nhà họ Hoắc, để cứu tài sản của gia đình. Nhưng lại quen được Hoắc Tư Đình, cậu chủ thứ hai không được xem trọng của nhà họ Hoắc. Hai người quyết định thành lập liên minh. Trong quá trình đó, một tình yêu bị cấm đoán đã lặng lẽ xảy ra trong ngôi biệt thự giàu có...</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dai Jingyao","avatar":""},{"name":"Xueyao Zeng","avatar":""},{"name":"Liu Runming","avatar":""},{"name":"Ma Juanjuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Passionate Love After Marriage","婚後熱戀","婚后热恋"]', 1784690324224);
