INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-jae-nguoi-tot-hay-ke-xau', 'Dong Jae, Người Tốt Hay Kẻ Xấu', 'Dongjae, The Good Or The Bastard', 'https://phimimg.com/upload/vod/20241112-1/7f16589b66e9b5fd3f8d3249ec58f00e.jpg', 'https://phimimg.com/upload/vod/20241112-1/815cea3c1c0321b62e283d9cba7a60d9.jpg', '<p>Dong Jae, Người Tốt Hay Kẻ Xấu xoay quanh hành trình tìm kiếm bản thân và đối mặt với những lựa chọn khó khăn của nhân vật chính, Dong Jae. Trong một thế giới đầy rẫy những tình huống phức tạp, anh phải tự hỏi liệu mình là người tốt hay kẻ xấu.</p>', 'Tập 8', 10, 'series', 'ongoing', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jun-hyuk","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Lee Hang-na","avatar":""},{"name":"Park Seong-geun","avatar":""},{"name":"Choi Hee-seo","avatar":""},{"name":"Kim Su-gyeom","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["好或坏的东载","Dongjae, the Good or the Bastard","Good or Bad Dong-jae","Dongjae, The Good or The Bastard","或好或壞的東載","좋거나 나쁜 동재"]', 1784690324224);
