INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-nhan-chim-canh-cut', 'Ác Nhân Chim Cánh Cụt', 'The Penguin', 'https://phimimg.com/upload/vod/20240922-1/cd356b077be20de245dc985730779bc3.jpg', 'https://phimimg.com/upload/vod/20240922-1/e2f5381bcbaa3e5efda0d358d9816916.jpg', '<p>Được dựa trên nhân vật Penguin của DC Comics, đây là phần phim ngoại truyện của Batman: Vạch trần sự thật (2022) với cốt truyện xoay quanh sự trỗi dậy của Penguin để nắm lấy quyền lực tại thế giới tội phạm ngầm của Thành phố Gotham. Bộ phim được sản xuất bởi 6th &amp; Idaho, DC Studios và Dylan Clark Productions cùng sự hợp tác của Warner Bros. Television, với LeFranc đảm nhận vai trò nhà sản xuất phim truyền hình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Ireland', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Cristin Milioti","avatar":""},{"name":"Rhenzy Feliz","avatar":""},{"name":"Deirdre O''Connell","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Carmen Ejogo","avatar":""},{"name":"Michael Zegen","avatar":""},{"name":"Berto Colon","avatar":""},{"name":"James Madio","avatar":""},{"name":"Joshua Bitton","avatar":""},{"name":"David H. Holmes","avatar":""},{"name":"Daniel J. Watts","avatar":""},{"name":"Ben Cook","avatar":""},{"name":"Jayme Lawson","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Mark Strong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["البطريق","پنگوئن","The Penguin"]', 1784690324224);
