INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('seacabo-nu-hon-lam-thay-doi-bong-da-tay-ban-nha', 'SeAcabó: Nụ hôn làm thay đổi bóng đá Tây Ban Nha', 'It''s All Over: The Kiss That Changed Spanish Football', 'https://phimimg.com/upload/vod/20241111-1/b42ffb47261d44762542a397b939b314.jpg', 'https://phimimg.com/upload/vod/20241111-1/32972118dd889a40cdd5c2bb9f49f5c1.jpg', '<p>Lần đầu tiên các cầu thủ bóng đá Tây Ban Nha cùng nhau hồi tưởng lại World Cup nữ năm 2023 đầy biến động và nụ hôn làm lu mờ chiến thắng của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Jenni Hermoso","avatar":""},{"name":"Alexia Putellas","avatar":""},{"name":"Irene Paredes","avatar":""},{"name":"Aitana Bonmatí","avatar":""},{"name":"Olga Carmona","avatar":""},{"name":"Teresa Abelleira","avatar":""},{"name":"Ivana Andrés","avatar":""},{"name":"Laia Codina","avatar":""},{"name":"Sandra Paños","avatar":""},{"name":"Lola Gallardo","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["#SeAcabó: Diario de las campeonas"]', 1784690324224);
