INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-dem', 'Trăng Đêm', 'The Hidden Moon', 'https://phimimg.com/upload/vod/20240909-1/fa520df442537ee6085e5e4c225076f9.jpg', 'https://phimimg.com/upload/vod/20240909-1/4d6b93ca3f61ea4f31f6565eed9ce5ad.jpg', '<p>Một ngôi biệt thự cổ hai tầng uy nghi nằm dưới chân đồi và được bao quanh bởi thiên nhiên. Bầu không khí nó toát ra vừa hấp dẫn vừa bí ẩn. Nó háo hức chờ đợi sự xuất hiện của một nhóm người từ nơi xa xôi. Trong số đó có một copywriter trẻ năng động, người sẽ thực hiện chiến dịch tiếp thị cho khu nghỉ dưỡng thiên về bảo tồn này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kin Thanachai Sakchaicharoenkul","avatar":""},{"name":"David Matthew Roberts","avatar":""},{"name":"Jimmy Nuttapong Phaojinda","avatar":""},{"name":"Atcharee Buakhiao","avatar":""},{"name":"Meme Kansuda Chanakeeree","avatar":""},{"name":"Pom Kamonpop Kaewdiao","avatar":""},{"name":"Santa Napakawat Kettreekorn","avatar":""},{"name":"Tonkla Patittada Photajareon","avatar":""},{"name":"Bam Panichada Kongsawanya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324224);
