INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-quanh-barbie-cuoc-san-ngua-vi-dai', 'Bí ẩn quanh Barbie: Cuộc săn ngựa vĩ đại', 'Barbie Mysteries: The Great Horse Chase', 'https://phimimg.com/upload/vod/20241110-1/ffcad327139b61fd6efe70c882e8b184.jpg', 'https://phimimg.com/upload/vod/20241110-1/f523c5cde05a3b0690e17e7588e7ab91.jpg', '<p>Đôi bạn thân Brooklyn và Malibu chạy đua khắp châu Âu để phá giải bí ẩn khi một con ngựa biểu diễn bị đánh cắp trong lúc họ đang đi nghỉ ở vùng quê nước Anh.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Abby Trott","avatar":""},{"name":"Diamond White","avatar":""},{"name":"Josh Banday","avatar":""},{"name":"Griffin Burns","avatar":""},{"name":"Sohm Kapila","avatar":""},{"name":"Anjali Kunapaneni","avatar":""},{"name":"Cristina Milizia","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Mistérios da Barbie: O Grande Resgate","芭比的神秘之旅：伟大的寻马记","Zagadki Barbie: Wielki pościg","Os Mistérios da Barbie: A Grande Perseguição de Cavalos","Barbie: Passport to Adventure","Barbie Mysteries"]', 1784690324224);
