INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-ngoai-thanh-thoi-phan-3', 'Dã Ngoại Thảnh Thơi (Phần 3)', 'Yuru Camp (Season 3)', 'https://phimimg.com/upload/vod/20241110-1/edf8fd2c589143316013d842ce0e4704.jpg', 'https://phimimg.com/upload/vod/20241110-1/d9939ef260740f27dd4a3661b8f90c85.jpg', '<p>Câu chuyện bình dị này xoay quanh hai cô gái trẻ: Rin yêu thích cắm trại một mình bên bờ hồ, nơi có thế nhìn ra núi Phú Sĩ hùng vĩ; và Nadeshiko thích những chuyến đi xe một mình đến những nơi mà cô có thể ngắm thấy núi Phú Sĩ. Sau khi gặp nhau. Rin và Nadeshiko đã cùng nhau cắm trại, ăn mì ly và cùng thưởng thức cảnh đẹp.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yumiri Hanamori","avatar":""},{"name":"Nao Toyama","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["轻旅轻营","轻旅轻营△","Campamento libre","Yuru Camp - Au Grand Air","Yuru Camp","LET''S CAMP! 露营少女","Perkemahan Santai△","Yurukyan","Yuru Camp△","YuruCamp","ゆるキャン△","ゆるキャン△ SEASON２","ゆるキャン△ SEASON３","ゆるキャン△ SEASON４","유루캠프","유루캠△","유루캠△ SEASON 2","แคมป์อยู่บ้าน","แคมป์สบายสไตล์สาวๆ","โลลิตั้งแคมป์","摇曳露营","搖曳露營△ 第三季","搖曳露營△第三季","Дівочий табір"]', 1784690324224);
