INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-rat-yeu-co-ay', 'Vẫn Rất Yêu Cô Ấy', 'Lost And Found', 'https://phimimg.com/upload/vod/20241026-1/34e7c32c863d6f9d26af38f73c081600.jpg', 'https://phimimg.com/upload/vod/20241026-1/18e2f63c5fb5c2787852c1bd89dbc364.jpg', '<p>Tư Kình Dạ, tổng giám đốc tập đoàn Tư Thị và Ninh Vô Hối do âm mưu của kẻ xấu mà xảy ra hiểu lầm và chia tay không vui vẻ. Sau đó, Ninh Vô Hối vô tình mất trí nhớ khi đang mang thai, cô sinh con và trở thành mẹ đơn thân. Bảy năm sau, hai người tái ngộ và dần dần thấu hiểu, yêu thương nhau, xóa tan mọi hiểu lầm. Cuối cùng, họ cùng nhau bắt đầu một cuộc sống hạnh phúc với gia đình bốn người.</p>', 'Tập 23', 23, 'series', 'ongoing', 15, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wen Mo Yan","avatar":""},{"name":"申浩男","avatar":""},{"name":"王俊喆","avatar":""},{"name":"杨姝音","avatar":""},{"name":"Zhao Ziluo","avatar":""},{"name":"倪瑜坤","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["還是很愛她","还是很爱她"]', 1784690324224);
