INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('van-rat-yeu-co-ay', 'Vẫn Rất Yêu Cô Ấy', 'Lost And Found', 'vẫn rất yêu cô ấy lost and found wen mo yan 申浩男 王俊喆 杨姝音 zhao ziluo 倪瑜坤 還是很愛她 还是很爱她', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tinh-an', 'Thám Tình An', 'Dawn Amidst Hidden Clouds', 'https://phimimg.com/upload/vod/20241026-1/68a4f91b35a5e0a7adc2a840e17cd3a0.jpg', 'https://phimimg.com/upload/vod/20241026-1/f675c1dda17aeb20cfa10f456aec154b.jpg', '<p>Lan Triệt, một thiếu nữ đường phố hết lòng bảo vệ láng giềng của mình, vô tình bị cuốn vào một vụ án mạng và gặp Đại Lý Tự chính khanh Lâu Minh Dạ. Hai con người hoàn toàn khác biệt mới đầu đã liên tục xảy ra hiểu lầm, nhưng sau khi hiểu nhau hơn, họ đã giải quyết những hiểu lầm, chung sức hợp tác, liên tiếp phá các vụ kỳ án. Đồng thời trong quá trình phá án, hai người dần nảy sinh tình cảm, xác định thân phận của đối phương, sau cùng có được một tình yêu chân thành. Với sự đồng hành và giúp đỡ của Lâu Minh Dạ, Lan Triệt trải qua rèn luyện, từ một thiếu nữ đường phố trở thành nữ thiếu khanh đầu tiên của Đại Lý Tự, và thực hiện được lý tưởng của cuộc đời mình.</p>', 'Tập 22', 22, 'series', 'ongoing', 12, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chang Huasen","avatar":""},{"name":"赵晴","avatar":""},{"name":"Qiu Hongkai","avatar":""},{"name":"Wu Mingjing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["大理寺萌主","Dali Temple","探晴安"]', 1784690324224);
