INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-toi-ngoi-vuong-mua-2', 'Đường Tới Ngôi Vương (Mùa 2)', 'Road To Kingdom: Ace Of Ace', 'https://phimimg.com/upload/vod/20240928-1/9bd3135f535b4e577fcb0a7d4ca5342b.jpg', 'https://phimimg.com/upload/vod/20240928-1/c3c486b2cb8b588df34426b0e1fdc1b5.jpg', '<p>Mùa đầu tiên của &#39;Road to Kingdom&#39; đã tạo tiền đề cho một cuộc thi sinh tồn khó quên của nhóm nhạc nam. Bây giờ, nó trở lại với bảy nhóm nhạc nam mới sẵn sàng thể hiện tài năng của họ. TAEMIN của SHINee sẽ dẫn chương trình, mang đến sự cố vấn vô giá cho làn sóng ngôi sao K-pop tiếp theo.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"태민","avatar":""},{"name":"Moon Jaeyun","avatar":""},{"name":"Ji Myungho","avatar":""},{"name":"Yang Minho","avatar":""},{"name":"Cho Yoonsung","avatar":""},{"name":"Jung Haemin","avatar":""},{"name":"Kyungmin","avatar":""},{"name":"Lee Yungyu","avatar":""},{"name":"Lee Seungheon","avatar":""},{"name":"세림","avatar":""},{"name":"앨런","avatar":""},{"name":"정모","avatar":""},{"name":"우빈","avatar":""},{"name":"원진","avatar":""},{"name":"민희","avatar":""},{"name":"형준","avatar":""},{"name":"태영","avatar":""},{"name":"성민","avatar":""},{"name":"Lee Seo Ho","avatar":""},{"name":"Kim Gun Hak","avatar":""},{"name":"Lee Keon Hee","avatar":""},{"name":"Yeo Hwan Woong","avatar":""},{"name":"Son Dong Ju","avatar":""},{"name":"Hanbin","avatar":""},{"name":"Ahn Hyeong-seop","avatar":""},{"name":"LEW","avatar":""},{"name":"Koo Bonhyuk","avatar":""},{"name":"Cho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Rodeu tu kingdeom: Ace of Ace","Rodŭ t''u k''ingdŏm: Ace of Ace","로드 투 킹덤: ACE OF ACE"]', 1784690324224);
