INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duong-toi-ngoi-vuong-mua-2', 'Đường Tới Ngôi Vương (Mùa 2)', 'Road To Kingdom: Ace Of Ace', 'đường tới ngôi vương (mùa 2) road to kingdom: ace of ace 태민 moon jaeyun ji myungho yang minho cho yoonsung jung haemin kyungmin lee yungyu lee seungheon 세림 앨런 정모 우빈 원진 민희 형준 태영 성민 lee seo ho kim gun hak lee keon hee yeo hwan woong son dong ju hanbin ahn hyeong-seop lew koo bonhyuk cho rodeu tu kingdeom: ace of ace rodŭ t''u k''ingdŏm: ace of ace 로드 투 킹덤: ace of ace', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-nguoi-noi-phao-hoa-ruc-ro', 'Chờ Người Nơi Pháo Hoa Rực Rỡ', 'A Balloon''s Landing', 'https://phimimg.com/upload/vod/20241109-1/5223050570ff9a6c2d07246ce5cd789e.jpg', 'https://phimimg.com/upload/vod/20241109-1/ab91cf6b6630f8334bbb0f98d58071b3.jpg', '<p>Nhà văn Hồng Kông Thiên Vũ một mình đến Đài Bắc để tìm kiếm Vịnh Cá Voi - địa danh bí ẩn mà theo một người bạn qua thư của anh chàng viết là có thể dẫn lối đến thiên đường. Trong chuyến đi, anh bất ngờ gặp A Tường - anh chàng địa phương tốt bụng và đem đến nhiều cảm xúc cho Thiên Vũ. Dù hẹn ước sẽ cùng nhau đi tìm Vịnh Cá Voi, nhưng A Tường lại đột nhiên biến mất kể từ Lễ hội pháo hoa Kenting. Nhận ra cuộc gặp gỡ trước đó giữa mình và A Tường chính là định mệnh, Thiên Vũ quyết tâm đi tìm A Tường và luôn mong ngày gặp lại chàng trai ấy.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Đài Loan', 1, '[{"name":"Lưu Tuấn Khiêm","avatar":""},{"name":"Phạm Thiếu Huân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Balloon''s Journey","Wo zai zhe li deng ni","I''m Here Waiting for You","A Balloon''s Landing","我在这里等你","鯨が消えた入り江","Te espero aquí","Yitik Balinalar Koyu","我在這裡等你"]', 1784690324224);
