INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-plankton', 'Quý Ông Plankton', 'Mr. Plankton', 'https://phimimg.com/upload/vod/20241108-1/93323da9dff11317b8006a609d3387f0.jpg', 'https://phimimg.com/upload/vod/20241108-1/12e06045cf1aba5d94fe9af0bb3cb452.jpg', '<p>Một người đàn ông gặp nhiều bất hạnh và tình cũ của anh, cô dâu tương lai kém may mắn nhất, buộc phải đồng hành cùng nhau trong chặng hành trình cuối cùng của đời anh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Woo Do-hwan","avatar":""},{"name":"Lee You-mi","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Kim Min-seok","avatar":""},{"name":"Lee El","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Ahn Suk-hwan","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Kim Soo-jin","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Kim Chan-hyung","avatar":""},{"name":"Alex Landi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["미스터 플랑크톤","Mr 플랑크톤","浮游先生","MR. PLANKTON","Mr. 플랑크톤"]', 1784690324224);
