INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-quan-dai-nhan-xin-chi-giao-nhieu-hon', 'Nữ Quan Đại Nhân Xin Chỉ Giáo Nhiều Hơn', 'Ancient Workplace, Love Handbook', 'https://phimimg.com/upload/vod/20241021-1/4bcffa9fe2e24cd45fd891452bb159e8.jpg', 'https://phimimg.com/upload/vod/20241021-1/a14deefc945af83485569b9ba3d6b47c.jpg', '<p>Tân binh chốn công sở Hứa Tinh Lan vô tình xuyên không về cổ đại và bị ràng buộc với Vũ Văn Diễn, nhị thiếu gia của thành An Tấn, đối tượng ám sát của mình! Trong một tình huống oái oăm, họ bắt đầu trò chơi &quot;mèo vờn chuột&quot; yêu hận đan xen. Đồng thời, cô đã sử dụng tư duy hiện đại để mở ra hành trình kỳ diệu từ &quot;nữ sát thủ nữ số một&quot; trở thành &quot;&quot;nữ quan số một&quot; tại thành An Tấn.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Changxi","avatar":""},{"name":"龔婉怡","avatar":""},{"name":"Roada Xu","avatar":""},{"name":"杨朕","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Nv Guan Da Ren Duo Zhi Jiao","女官大人多指教"]', 1784690324224);
