INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('10-ngay-cua-mot-nguoi-to-mo', '10 ngày của một người tò mò', '10 Days of a Curious Man', 'https://phimimg.com/upload/vod/20241108-1/08bde3e23ce44eef65d592cb6ee32fb5.jpg', 'https://phimimg.com/upload/vod/20241108-1/e1922cc0417f32da7fc548322bc20e78.jpg', '<p>Khi một người phụ nữ trẻ mất tích ở Istanbul, nhà văn cạn kiệt cảm hứng nọ bị cuốn vào chuỗi sự kiện đầy chết chóc khi ông bắt đầu tìm kiếm cô... và một cốt truyện hay.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Nejat İşler","avatar":""},{"name":"Ilayda Akdoğan","avatar":""},{"name":"Şenay Gürler","avatar":""},{"name":"Ece İrtem","avatar":""},{"name":"Hazal Subaşı","avatar":""},{"name":"Rıza Kocaoğlu","avatar":""},{"name":"Ayten Uncuoğlu","avatar":""},{"name":"Cem Uslu","avatar":""},{"name":"Kadir Çermik","avatar":""},{"name":"Sezer Arıçay","avatar":""},{"name":"Gurur Çiçekoğlu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["10 Days of a Curious Man","Meraklı Adamın 10 Günü"]', 1784690324224);
