INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuyen-khong-cai-menh-gia-toc', 'Xuyên Không Cải Mệnh Gia Tộc', 'Chinatown Cha Cha', 'https://phimimg.com/upload/vod/20240901-1/bf600e5d633c6448a11cc5e2e6360a91.jpg', 'https://phimimg.com/upload/vod/20240901-1/5e3f8bbd2c245f2154ae17f44e3a6725.jpg', '<p>Xuyên Không Cải Mệnh Gia Tộc xoay quanh Kie (Mint Ranchrawee), một sinh viên ngành khảo cổ học, sinh ra trong một gia đình gốc Hoa tại khu phố Tàu. Ngay từ nhỏ, Kie đã chứng kiến gia đình liên tục dính xui xẻo, ngồi không cũng gặp chuyện. Trong một lần cầu nguyện giải xui tại ngôi đền trong xóm, cô được thầy cúng tại đây cho biết, vận xui gia đình cô là nghiệp chướng do Kung (Alek Teeradetch) - ông tổ nhà cô gây ra. Dù không tin lắm vào trò mê tín, Kie nhờ thầy cúng giúp mình thực hiện nghi lễ thanh tẩy nghiệp chướng, cô vô tình bị đẩy về quá khứ và nhập xác vào người anh em thân thiết nhất của ông cố mình - Tai do March Chutavuth thủ vai. Từ đây, hàng loạt tình huống giở khóc giở cười liên tục ập đến, đồng thời những bí mật đen tối từ quá khứ đã dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Ranchrawee Uakoolwarawat","avatar":""},{"name":"Teeradetch Metawarayut","avatar":""},{"name":"Chutavuth Pattarakampol","avatar":""},{"name":"ชูเกียรติ เอี่ยมสุข","avatar":""},{"name":"Katchathathep Iamsiri","avatar":""},{"name":"Prasitthichoke Manasantadchat","avatar":""},{"name":"Noppadon Songsang","avatar":""},{"name":"จตุรงค์ พลบูรณ์","avatar":""},{"name":"เจริญพร อ่อนละม้าย","avatar":""},{"name":"Chalerm Parnkerd","avatar":""},{"name":"Passakorn Ponlaboon","avatar":""},{"name":"Thongthong","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324224);
