INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-nhan', 'Sơ Nhan', 'The Unbreakable Bond', 'https://phimimg.com/upload/vod/20241023-1/7060158ccfcba22285736c4e12c5eec6.jpg', 'https://phimimg.com/upload/vod/20241023-1/3369851ee77ed04d35e29984a47d782b.jpg', '<p>Câu chuyện kể về Lăng Sơ Hạ, một thiếu nữ lâm vào cảnh khốn cùng đã quyết định vùng lên đấu tranh chống lại xiềng xích của gia đình và can đảm đối mặt với những lời chỉ trích. Nàng gặp gỡ và đem lòng yêu nam chính Lương Quân Dạ - một con người có cùng cảnh ngộ. Cả hai giúp đỡ lẫn nhau vượt qua khó khăn, cùng vạch trần âm mưu của kẻ địch và bảo vệ nước nhà.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jia Ze","avatar":""},{"name":"Li Pei Yang","avatar":""},{"name":"Du Yu","avatar":""},{"name":"Zhou Hengyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Chu Yan","君夜伴夏梦","初顏","初颜"]', 1784690324224);
