INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phia-sau-cai-chet', 'Phía Sau Cái Chết', 'Behind The Death', 'https://phimimg.com/upload/vod/20241005-1/aac3986c07b75cd6a7002797cdd61fc9.jpg', 'https://phimimg.com/upload/vod/20241005-1/795e8f69a90d9b470c844a6d017e7565.jpg', '<p>Bộ phim “Phía sau cái chết” tập trung khai thác câu chuyện về Cẩm Linh – một nữ cảnh sát được mệnh danh là “ngôi sao phòng điều tra”. Cuộc gặp gỡ định mệnh của Cẩm Linh với Cường – một nhà văn có biệt tài “trò chuyện với xác chết” đã hình thành mối quan hệ đặc biệt giữa họ. Cường và Cẩm Linh cùng các thành viên của đội trọng án cùng nhau hóa giải nhiều vụ án và tìm ra một sự thật khiến tất cả bàng hoàng.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Cao Thái Hà","avatar":""},{"name":"Hải Nam","avatar":""},{"name":"Thanh Duy","avatar":""},{"name":"Hữu Vi","avatar":""},{"name":"Khương Thịnh","avatar":""},{"name":"Thùy Trang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gewagtes Spiel"]', 1784690324224);
