INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-nuoi-trai', 'Cô Nàng Nuôi Trai', 'Tahong', 'https://phimimg.com/upload/vod/20241106-1/5f112508e13d055718b32c4ad6c810b1.jpg', 'https://phimimg.com/upload/vod/20241106-1/2c1e213d67ef6e85b951fe7b7698cb0b.jpg', '<p>Mira là con gái của một người nuôi trai cần phải đấu tranh cho một dự án cải tạo. Cô sẽ làm mọi thứ để cứu kế sinh nhai của họ ngay cả khi phải hy sinh sự trong trắng của mình.</p>', 'Full', 1, 'single', 'completed', 22, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Candy Veloso","avatar":""},{"name":"Salome Salvi","avatar":""},{"name":"Marlon Marcia","avatar":""},{"name":"Emil Sandoval","avatar":""},{"name":"James Lomahan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Tahong"]', 1784690324224);
