INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-vo-hinh-2024', 'Đặc Vụ Vô Hình', 'The Grey Man', 'https://phimimg.com/upload/vod/20241106-1/7307f103a2673509d7ce98f550a9b06d.jpg', 'https://phimimg.com/upload/vod/20241106-1/8e60a33e0f53daf0a6c9e52deeae6433.jpg', '<p>Câu chuyện phim diễn ra tại Hồng Kông, Trung Quốc. Một học viên cảnh sát chưa tốt nghiệp, A Sơn (do Cổ Bân thủ vai), được giao nhiệm vụ khẩn cấp trong nhà tù để giúp tay chân của tập đoàn tội phạm là A Thiên (do An Chí Kiệt thủ vai) vượt qua các trở ngại, nhằm tiếp cận và giành được sự tin tưởng của hắn, để thu thập chứng cứ phạm tội của tập đoàn này. Sau khi hai người ra tù, A Sơn tiếp tục giúp A Thiên nhanh chóng thăng tiến trong tập đoàn tội phạm ở Hồng Kông. Trải qua nhiều gian truân, A Thiên cuối cùng đã thay thế được lão đại của tập đoàn là Báo Ca (do Tăng Chí Vĩ thủ vai), trở thành người đứng đầu và kiểm soát tập đoàn. Nhưng đúng lúc A Sơn sắp hoàn thành nhiệm vụ, thân phận của anh ta lại bị bại lộ…</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Eric Tsang","avatar":""},{"name":"Andy On","avatar":""},{"name":"Samuel Ku","avatar":""},{"name":"洪浚嘉","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"何佩瑜","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Grey Men","黑白潜行"]', 1784690324224);
