INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-vu-nu-2-nghi-thuc-hoi-sinh', 'Linh Hồn Vũ Nữ 2: Nghi Thức Hồi Sinh', 'Dancing Village: The Curse Begins', 'https://phimimg.com/upload/vod/20241106-1/ae1fb7c637e1b6e6d290395239e0e0f8.jpg', 'https://phimimg.com/upload/vod/20241106-1/060b751dbfccd84263cf7345e9fca08e.jpg', '<p>Linh Hồn Vũ Nữ 2: Nghi Thức Hồi Sinh tiếp tục khám phá những bí ẩn trong ngôi làng tại cực Đông của đảo Java, nơi linh hồn vũ nữ Badarawuhi ngự trị. Những nỗi kinh hoàng tiếp theo sẽ ập đến, cùng một nghi thức kinh hoàng để lựa chọn Dawuh mới, linh hồn bị nguyền rủa sẽ phải nhảy múa cho đến hết phần đời còn lại.</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Maudy Effrosina","avatar":""},{"name":"Aulia Sarah","avatar":""},{"name":"Jourdy Pranata","avatar":""},{"name":"Ardit Erwandha","avatar":""},{"name":"Moh Iqbal Sulaiman","avatar":""},{"name":"Claresta Taufan Kusumarina","avatar":""},{"name":"Aming Sugandhi","avatar":""},{"name":"Dinda Kanyadewi","avatar":""},{"name":"Pipien Putri","avatar":""},{"name":"Zainal Abidin Zetta","avatar":""},{"name":"Maryam Supraba","avatar":""},{"name":"Bimasena","avatar":""},{"name":"Putri Permata","avatar":""},{"name":"Baiq Vania Estiningtyas Sagita","avatar":""},{"name":"Baiq","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["KKN di Desa Penari 2: Badarawuhi","Linh Hồn Vũ Nữ 2: Nghi Thức Hồi Sinh","鬼舞村：詛咒起源","បណ្តាសាព្រលឹងស្រីរបាំ 2","鬼舞村：诅咒起源","댄싱 빌리지 : 저주의 시작","Badarawuhi di Desa Penari"]', 1784690324224);
