INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-thong-joe-biden', 'Tổng Thống Joe Biden', 'The Presidents: Joe Biden', 'https://phimimg.com/upload/vod/20241105-1/8f98f86247a70a20858a96052bbb26b9.jpg', 'https://phimimg.com/upload/vod/20241105-1/231a7fee97a4f8ab6e589691e395a419.jpg', '<p>Joe Biden là một chính khách kỳ cựu của Đảng Dân chủ với thời gian hoạt động chính trị lâu dài cũng như từng nắm những vị trí quan trọng. Ông là một trong số ít người được nhận huân chương tự do, huân chương dân sự cao quý nhất ở Hoa Kỳ. Và sau những thành tích chính trị đó, ông đã trở thành Tổng thống thứ 46 của nước này.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joe Biden","avatar":""},{"name":"Beau Biden","avatar":""},{"name":"Jill Biden","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Presidents: Obama"]', 1784690324224);
