INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-thong-george-w-bush', 'Tổng Thống George W. Bush', 'The Presidents: George W. Bush', 'https://phimimg.com/upload/vod/20241105-1/d1a013467998adbce7f6926b24c7644d.jpg', 'https://phimimg.com/upload/vod/20241105-1/cd40ecb82a63dc1a9c9b7d5bbcc7dbc4.jpg', '<p>Là con trai của cựu Tổng thống thứ 41, George W. Bush đã nối nghiệp cha mình, trở thành Tổng thống thứ 43 của Hoa Kỳ với kết quả chiến thắng sát sao. Sau cuộc tấn công khủng bố ngày 11/ 9, ông có được sự tín nhiệm cao nhất trong lịch sử.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"George W. Bush","avatar":""},{"name":"Dick Cheney","avatar":""},{"name":"Stephen Colbert","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Presidents: Obama"]', 1784690324224);
