INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-thong-barack-obama', 'Tổng Thống Barack Obama', 'The Presidents: Obama', 'https://phimimg.com/upload/vod/20241105-1/c2915c896740278158d228110b540897.jpg', 'https://phimimg.com/upload/vod/20241105-1/4e1b69b3f139c79fd1e2062c27c6ded0.jpg', '<p>Là vị Tổng thống da màu đầu tiên của Hoa Kỳ mang đến bước ngoặt về sắc tộc, Barack Obama còn được nhận giải Nobel Hòa bình 2019 bởi những nỗ lực phi thường để tăng cường ngoại giao quốc tế và hợp tác giữa các dân tộc.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Barack Obama","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Presidents: Obama"]', 1784690324224);
