INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-thong-bill-clinton', 'Tổng Thống Bill Clinton', 'The Presidents: Bill Clinton', 'https://phimimg.com/upload/vod/20241105-1/6e81719067412376359d30bf51afb897.jpg', 'https://phimimg.com/upload/vod/20241105-1/6498054d70a309aa0c428520799a08ed.jpg', '<p>Là một trong những Tổng thống trẻ tuổi nhất Hoa Kỳ, giai đoạn cầm quyền của Clinton là thời kỳ bùng nổ kinh tế lâu dài nhất trong lịch sử Mỹ. Dù sau đó vấp phải nhiều bê bối nhưng với những gì đã cống hiến, ông vẫn nhận được sự ủng hộ cao.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bill Clinton","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Presidents: Obama"]', 1784690324224);
