INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-tue-kep', 'Trí Tuệ Kép', 'Double iSmart', 'https://phimimg.com/upload/vod/20241104-1/3f3f9082b9408b1d16b638914dc45f08.jpg', 'https://phimimg.com/upload/vod/20241104-1/2e859e1fe747694ca8a0a618f5f3c134.jpg', '<p>Trí Tuệ Kép kể về Big Bull, một sát thủ khét tiếng, khao khát đạt được sự bất tử bằng cách chuyển ký ức của mình sang não của Shankar, người vốn đã mang ký ức của một cảnh sát đã chết. Sự xung đột bùng nổ khi Shankar, với trí tuệ đã được cấy ghép từ trước, phải đối đầu với Big Bull để ngăn chặn âm mưu kiểm soát ký ức của hắn.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Ram Pothineni","avatar":""},{"name":"Sanjay Dutt","avatar":""},{"name":"Kavya Thapar","avatar":""},{"name":"Sayaji Shinde","avatar":""},{"name":"Getup Srinu","avatar":""},{"name":"Makrand Deshpande","avatar":""},{"name":"Temper Vamsi","avatar":""},{"name":"Gurbani Judge","avatar":""},{"name":"Ali Basha","avatar":""},{"name":"Jhansi","avatar":""},{"name":"Pragathi Mahavadi","avatar":""},{"name":"Uttej","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["డబుల్ ఇస్మార్ట్"]', 1784690324224);
