INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ao-ma', 'Thế Giới Ảo Ma', 'Levels', 'https://phimimg.com/upload/vod/20241104-1/6b018cc11284b4d8b51942b6725b9cf0.jpg', 'https://phimimg.com/upload/vod/20241104-1/4a0c03322d4e759c8b1d5eb228d72888.jpg', '<p>Cốt truyện xoay quanh một người đàn ông chứng kiến cảnh bạn gái mình bị sát hại. Để tìm ra sự thật, anh chấp nhận đánh đổi mọi thứ, kể cả thực tại của chính mình.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Cara Gee","avatar":""},{"name":"Peter Mooney","avatar":""},{"name":"Aaron Abrams","avatar":""},{"name":"David Hewlett","avatar":""},{"name":"Amanda Tapping","avatar":""},{"name":"Adam Hurtig","avatar":""},{"name":"Sydney Sabiston","avatar":""},{"name":"Jade Ma","avatar":""},{"name":"BJ Verot","avatar":""},{"name":"Kristian Jordan","avatar":""},{"name":"Ava Julien","avatar":""},{"name":"Kevin Klassen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Levels"]', 1784690324224);
