INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-hanh-dong-liem-chinh', 'Đội Hành Động Liêm Chính', 'ICAC Investigators 2024', 'https://phimimg.com/upload/vod/20241104-1/6d549a200d150414a3930e903f639cca.jpg', 'https://phimimg.com/upload/vod/20241104-1/c5394fc16566d8f138e564cfaa81c198.jpg', '<p><span style="text-wrap-mode: wrap;">Chủ nhiệm hàng đầu đội điều tra của Sở Liêm chính - Giang Kiến Thu (do Trương Hy Văn đóng) và tổng chủ nhiệm điều tra Tư Đồ Hải Văn (do Trần Sơn Thông đóng) cùng dẫn dắt đội phá giải những vụ án có dấu hiệu vi phạm điều lệ tham nhũng. 5 tập phim &quot;Đội Hành Động Liêm Chính 2024&quot; là 5 câu chuyện phá án gay cấn và hấp dẫn, gồm: Tu sửa trái phép, Người trong tù, Người im lặng, Trong suy nghĩ và Người giả tạo.</span></p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 8, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Sơn Thông","avatar":""},{"name":"Trương Hy Văn","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"La Tử Dật","avatar":""},{"name":"Từ Vinh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["住在我身體裡的那個她","The Girl Inside Me","住在我身体里的那个她"]', 1784690324224);
