INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-phan-den-tu-dia-nguc', 'Thẩm Phán Đến Từ Địa Ngục', 'The Judge From Hell', 'https://phimimg.com/upload/vod/20240923-1/7e5fe43e4bfee1942ada75ab5073fad0.jpg', 'https://phimimg.com/upload/vod/20240923-1/4c333ba18cb9058f4d947579a3868ad6.jpg', '<p>Vẻ ngoài giống như một cô thư ký chốn công sở với ngoại hình cực kỳ ngọt nước, nhưng Kang Bit Na lại là một thẩm phán vô cùng tài giỏi, dù sao đó cũng chỉ là vẻ ngoài thôi, còn thực chất thì Kang Bit Na đến từ .... địa ngục, hay cũng có thể coi cô là QUỶ cũng được. Nhiệm vụ chính của Kang Bit Na là đưa những kẻ xấu xa đến với địa ngục, dù những kẻ đó trực tiếp hoặc gián tiếp gây ra tội ác, dẫn đến sự đăng xuất của người khác. Rồi một ngày đó Kang Bit Na đã gặp anh thám tử Hang Da On tài giỏi và cũng rất hiền lành, thân thiện. Tuy vậy nhưng Hang Da On lại có những nỗi niềm riêng tư rất khó nói, may mắn cho anh là cuộc sống với Kang Bit Na đã làm anh khá hơn rất nhiều.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박신혜","avatar":""},{"name":"김재영","avatar":""},{"name":"김아영","avatar":""},{"name":"김인권","avatar":""},{"name":"김혜화","avatar":""},{"name":"한상진","avatar":""},{"name":"이중옥","avatar":""},{"name":"최동구","avatar":""},{"name":"이미도","avatar":""},{"name":"이규한","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["从地狱来的法官","قاضی جهنمی","قاضيه من الجحيم","The.Judge.from.Hell.2024","從地獄來的法官","The.Judge.from.Hell","지옥에서 온 판사"]', 1784690324224);
