INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-phan-den-tu-dia-nguc', 'Thẩm Phán Đến Từ Địa Ngục', 'The Judge From Hell', 'thẩm phán đến từ địa ngục the judge from hell 박신혜 김재영 김아영 김인권 김혜화 한상진 이중옥 최동구 이미도 이규한 从地狱来的法官 قاضی جهنمی قاضيه من الجحيم the.judge.from.hell.2024 從地獄來的法官 the.judge.from.hell 지옥에서 온 판사', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nu-khong-nghe-lenh-tuong-quan', 'Tiểu Nữ Không Nghe Lệnh Tướng Quân', 'General Order', 'https://phimimg.com/upload/vod/20241030-1/0f079962f0b6ee52d82a23cba750515b.jpg', 'https://phimimg.com/upload/vod/20241030-1/9ea355a096b3a9392b9149c5dd87e21c.jpg', '<p>Trong lúc tham gia hoạt động ngoại khóa của câu lạc bộ khảo cổ, thành viên Tô Khả vô tình chạm vào lệnh bài tướng quân và bị xuyên không đến nước Ngô, đúng vào lúc đại tướng quân Đới Vũ đang điều tra một vụ án mạng liên hoàn. Vì có ngoại hình giống hệt nạn nhân nên Tô Khả bị Đới Vũ dùng lệnh bài tướng quân ép cưới về phủ. Thế nhưng đô thành sóng ngầm cuộn trào, Tô Khả liên tục bị ám sát, vì vậy cô quyết định cùng Đới Vũ điều tra hung thủ. Trong quá trình điều tra, Tô Khả quen được Lục Thần, thiếu trang chủ của sơn trang Lục Ly, còn được yết kiến Hoàng đế đương triều, lại phát hiện ra Hoàng đế chính là Tôn Đạc, thành viên câu lạc bộ cùng xuyên không tới. Thì ra các bạn học của Tô Khả đều xuyên không đến nước Ngô, hơn nữa vì thời điểm xuyên không khác nhau, nên tuổi tác và trải nghiệm của mỗi người cũng khác nhau, tâm tính cũng thay đổi. Dưới sự giúp đỡ của Tôn Đạc, Tô Khả và Đới Vũ thuận lợi điều tra ra hung thủ, trừng trị hắn theo pháp luật.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"程宇峰","avatar":""},{"name":"Qiao Jing Wen","avatar":""},{"name":"鹿鸣","avatar":""},{"name":"Liu Xinnian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["小女不聽將軍令","小女不听将军令"]', 1784690324224);
