INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ltns', 'LTNS', 'Long Time No Sex', 'https://phimimg.com/upload/vod/20241104-1/2019958f416e6a006d0bebcbf773b837.jpg', 'https://phimimg.com/upload/vod/20241104-1/c362356455d3b4bf9766cebeac196f57.jpg', '<p>Trong lúc cuộc sống vợ chồng của Woo Jin và Samuel đang dần nguội lạnh thì Woo Jin vô tình biết được chuyện ngoại tình của một người bạn. Cả hai quyết định hợp tác tống tiền người đó để kiếm thêm thu nhập. Trong quá trình theo dõi những biến cố của gia đình người khác, họ cũng bắt đầu nhìn nhận lại cuộc hôn nhân của chính mình.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Esom","avatar":""},{"name":"Ahn Jae Hong","avatar":""},{"name":"Ok Ja Yeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["롱 타임 노 섹스","Long Time No Sex","爱情少一啪","ลองไทม์โนเซ็กส์","愛情少一啪"]', 1784690324224);
