INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-noi-doi-cua-em-cung-de-nghe', 'Lời Nói Dối Của Em Cũng Dễ Nghe', 'A Beautiful Lie', 'https://phimimg.com/upload/vod/20241020-1/90e5c8ba790ecf25cd595c5a93cc2820.jpg', 'https://phimimg.com/upload/vod/20241020-1/60078d5ca118bc8398e57a1e7c052c9e.jpg', '<p>Lời Nói Dối Của Em Cũng Dễ Nghe là bộ phim tình cảm do Lý Huệ Châu (bộ phim &quot;Cửu Tiêu Hàn Dạ Noãn&quot;) làm đạo diễn, với sự tham gia của Trần Tinh Húc (tác phẩm &quot;Hành Động Diệt Sói&quot;) và Trương Dư Hi (tác phẩm &quot;Lưu Ly&quot;). Bộ phim được chuyển thể từ tiểu thuyết cùng tên của Nhị Nguyệt Sinh. Tại một vùng thiên tai ở phía Tây Nam, đội cứu trợ y tế và các tình nguyện viên đã đến hỗ trợ, trong đó có nữ diễn viên Tần Phỉ (do Trương Dư Hi thủ vai). Mọi người đều cho rằng Tần Phỉ đến làm tình nguyện chỉ để tạo hình ảnh, nhưng Tần Phỉ đã làm việc nghiêm túc và còn dũng cảm cứu người trong lúc nguy cấp. Ngày đêm bên nhau, đội trưởng đội y tế Hành Tri Chỉ (do Trần Tinh Húc thủ vai) đã thấy được sự kiên cường và lòng tốt từ nội tâm của Tần Phỉ, giúp cả hai hiểu rõ nhau hơn. Tần Phỉ cũng nhận ra rằng, vị bác sĩ trẻ đã cứu mạng và thắp lại hy vọng cho cô trong cuộc thi múa nhiều năm trước chính là Hành Tri Chỉ.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"陳星旭","avatar":""},{"name":"張予曦","avatar":""},{"name":"王森","avatar":""},{"name":"Chen Haolan","avatar":""},{"name":"林昕宜","avatar":""},{"name":"阳兵卓","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Una hermosa mentira","你的謊言也動聽","A Beautiful Lie","你的谎言也动听"]', 1784690324224);
