INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-the-z-khoi-nguon-dai-dich', 'Tận Thế Z: Khởi Nguồn Đại Dịch', 'Apocalypse Z: The Beginning of the End', 'https://phimimg.com/upload/vod/20241102-1/302f263b4ef5696a94ce9262162ac3b1.jpg', 'https://phimimg.com/upload/vod/20241102-1/a1ccb430973076351099962a296bbe13.jpg', '<p>Tận Thế Z: Khởi Nguồn Đại Dịch Apocalypse Z: The Beginning of the End 2024 lấy bối cảnh thế giới hậu tận thế, nơi một loại virus giống như bệnh dại đã biến con người thành những sinh vật hung hãn khát máu.&nbsp; Manel, một luật sư trẻ tuổi,&nbsp; phải tìm cách sinh tồn trong thế giới hỗn loạn này.&nbsp; Anh ta trốn trong căn hộ của mình cùng với con mèo,&nbsp; sử dụng trí thông minh và sự khéo léo để chống lại những thây ma khát máu. Manel không chỉ phải đối mặt với mối đe dọa từ zombie,&nbsp; mà còn phải đối phó với những người sống sót khác,&nbsp; những kẻ sẵn sàng làm bất cứ điều gì để sinh tồn, kể cả việc hãm hại lẫn nhau.&nbsp; Cuối cùng,&nbsp; Manel nhận ra rằng anh ta không thể trốn tránh mãi mãi và phải tìm cách thích nghi với thế giới mới này.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Francisco Ortiz","avatar":""},{"name":"José María Yázpik","avatar":""},{"name":"Berta Vázquez","avatar":""},{"name":"Marta Poveda","avatar":""},{"name":"Iria del Río","avatar":""},{"name":"Yuri Mykhaylychenko","avatar":""},{"name":"Jesús Lloveras","avatar":""},{"name":"Ali Boulabiar","avatar":""},{"name":"Elena Seijo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["آخر الزمان زد: آغاز پایان","Apocalypse Z: The Beginning of the End","Apokalypse Z - Der Anfang vom Ende","天启Z：完结的起点","Apocalipsis Z: el principio del fin"]', 1784690324224);
