INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-bo-cap', 'Qúy Cô Bọ Cạp', 'Lady Scorpions', 'https://phimimg.com/upload/vod/20241103-1/c69fd4b3b3f3fbc6055f0e7af3002d68.jpg', 'https://phimimg.com/upload/vod/20241103-1/391cd24f7de65a0243d8952b2fe312cd.jpg', '<p>Cuộc chiến chống lại một tổ chức tội phạm của một cựu đặc vụ FBI trở nên mang tính cá nhân khi chúng bắt cóc cháu gái của bà; bà và con gái, cả hai đều là bậc thầy võ thuật, tạo thành một đội không thể ngăn cản.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cynthia Rothrock","avatar":""},{"name":"Caitlin Dechelle","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"David W. Rice","avatar":""},{"name":"Jose Manuel","avatar":""},{"name":"Miguel Peralta","avatar":""},{"name":"Fernando Alonso","avatar":""},{"name":"Nicolas Sotnikoff","avatar":""},{"name":"Sofia O''Brien","avatar":""},{"name":"Mamyi Ithou","avatar":""},{"name":"Mark Allyn","avatar":""},{"name":"Bruce Del Castillo","avatar":""},{"name":"Noah Pao","avatar":""},{"name":"Barbarella Pardo","avatar":""},{"name":"Dan Gross","avatar":""},{"name":"Oscar Quiñonez","avatar":""},{"name":"Rudy Ga","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Lady Scorpions"]', 1784690324224);
