INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sweet-bobby-ac-mong-lua-tinh', 'Sweet Bobby: Ác Mộng Lừa Tình', 'Sweet Bobby: My Catfish Nightmare', 'https://phimimg.com/upload/vod/20241102-1/786ee5bf4f77a4b7583601f436a7502a.jpg', 'https://phimimg.com/upload/vod/20241102-1/77c405b1a277016ec22a30430a388c36.jpg', '<p>Trong bộ phim tài liệu gây sốc này, Kirat phải lòng một người đàn ông cô gặp trên mạng, rồi cuối cùng bị cuốn vào mối quan hệ ảo làm đảo lộn cuộc sống của cô trong nhiều năm.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Kirat Assi","avatar":""},{"name":"Hemma Gulhane","avatar":""},{"name":"Anurag Mehra","avatar":""},{"name":"Ariya Larker","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Sweet Bobby: My Catfish Nightmare","Sweet Bobby: Szerelmi átverés"]', 1784690324224);
