INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('haikyu-tran-chien-bai-phe-lieu', 'Haikyu!!: Trận Chiến Bãi Phế Liệu', 'HAIKYU!! The Dumpster Battle', 'https://phimimg.com/upload/vod/20241102-1/61f3894bee443c5281ec28b4914bc65a.jpg', 'https://phimimg.com/upload/vod/20241102-1/e03d31bee2807351ff6af645e1447bc7.jpg', '<p>Trường trung học Karasuno và trường trung học Nekoma chính thức đối đầu lần đầu trong vòng thứ ba của Giải vô địch quốc gia mùa xuân. Điều đó có nghĩa là giấc mơ lâu đời của Karasuno và Nekoma đã thành hiện thực! Trận chiến thùng rác, trận chiến giữa quạ và mèo rừng sắp bắt đầu. Sau nhiều trận đấu tập trong năm qua, Shoyo Hinata và Kenma Kozume cuối cùng cũng có cơ hội đấu với nhau trong một trận đấu sẽ kết thúc ngay lập tức nếu họ thua và không thể chơi lại.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"村瀬歩","avatar":""},{"name":"石川界人","avatar":""},{"name":"梶裕貴","avatar":""},{"name":"中村悠一","avatar":""},{"name":"内山昂輝","avatar":""},{"name":"日野聡","avatar":""},{"name":"林勇","avatar":""},{"name":"岡本信彦","avatar":""},{"name":"入野自由","avatar":""},{"name":"細谷佳正","avatar":""},{"name":"斉藤壮馬","avatar":""},{"name":"増田俊樹","avatar":""},{"name":"西山宏太朗","avatar":""},{"name":"立花慎之介","avatar":""},{"name":"石井マーク","avatar":""},{"name":"星野貴紀","avatar":""},{"name":"横田成吾","avatar":""},{"name":"澤田龍一","avatar":""},{"name":"池田恭祐","avatar":""},{"name":"渡辺拓海","avatar":""},{"name":"汐谷文康","avatar":""},{"name":"江川央生","avatar":""},{"name":"福田信昭","avatar":""},{"name":"神谷浩史","avatar":""},{"name":"山本兼平","avatar":""},{"name":"中博史","avatar":""},{"name":"名塚佳織","avatar":""},{"name":"諸星すみれ","avatar":""},{"name":"市道真央","avatar":""},{"name":"富田美憂","avatar":""},{"name":"小松由佳","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id"