INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-buong-tay-2024', 'Đừng Buông Tay', 'Never Let Go', 'https://phimimg.com/upload/vod/20241102-1/216c7c8e1bfe14e564a459a9f5171959.jpg', 'https://phimimg.com/upload/vod/20241102-1/1bff3327db765f4649c59afb1de34e1b.jpg', '<p>Một ngôi nhà chứa đầy bùa chú là nơi an toàn cuối cùng để tránh xa lũ quỷ trong thế giới hậu tận thế đáng sợ. Một người mẹ và 2 đứa con nhỏ phải kết nối với ngôi nhà bằng sợi dây thừng linh thiêng để sinh tồn nơi rừng rậm, nơi hai thực thể ác độc Kẻ Xấu và Kẻ Xa Lạ có thể tước đoạt mạng người trong một phút buông tay.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Halle Berry","avatar":""},{"name":"Anthony B. Jenkins","avatar":""},{"name":"William Catlett","avatar":""},{"name":"Percy Daggs IV","avatar":""},{"name":"Matthew Kevin Anderson","avatar":""},{"name":"Christin Park","avatar":""},{"name":"Stephanie Lavigne","avatar":""},{"name":"Cadence Compton","avatar":""},{"name":"Mila Morgan","avatar":""},{"name":"Georges Gracieuse","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Mother Land","Motherland","Tether","Nikdy se nepouštěj!","Μην σε Αγγίξει το Κακό","هرگز رها مکن","אל תשחרר לעולם","千万别松手","别松开绳子","Never Let Go"]', 1784690324224);
