INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-ve-nha', 'Đừng về nhà', 'Don''t Come Home', 'https://phimimg.com/upload/vod/20241102-1/c03e80a26db06ed7abf67abe4b00cd61.jpg', 'https://phimimg.com/upload/vod/20241102-1/f98f7f6c901da225dcea83dc6086b20d.jpg', '<p>Chuyển đến dinh thự cổ kỳ dị của gia đình, người mẹ nọ đương đầu với những bí mật đen tối trong quá khứ sau khi cô con gái nhỏ của cô mất tích bí ẩn.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"วรนุช ภิรมย์ภักดี","avatar":""},{"name":"พิชชาภา พันธุมจินดา","avatar":""},{"name":"ซินดี้ สิรินยา บิชอพ","avatar":""},{"name":"พลอยปภัส ฝนแก้วศิวพร","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Ya Klap Ban","อย่ากลับบ้าน"]', 1784690324224);
