INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dung-ve-nha', 'Đừng về nhà', 'Don''t Come Home', 'đừng về nhà don''t come home วรนุช ภิรมย์ภักดี พิชชาภา พันธุมจินดา ซินดี้ สิรินยา บิชอพ พลอยปภัส ฝนแก้วศิวพร ya klap ban อย่ากลับบ้าน', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-pha-hoai-seoul', 'Những Kẻ Phá Hoại Seoul', 'Seoul Busters', 'https://phimimg.com/upload/vod/20240911-1/cdb7074c02e03c57e488a99bdcda34b5.jpg', 'https://phimimg.com/upload/vod/20240911-1/95021bc6148dcab10c57f93ee1ed64e5.jpg', '<p>Những kẻ phá hoại Seoul (Seoul Busters) là một bộ phim Hàn Quốc thuộc thể loại hài hước về chủ đề điều tra tội phạm của đạo diễn Ahn Jong Yeon, Shin Joong Hoon. Phim này, sẽ mang đến đội điều tra tội phạm giết người cấp thấp nhất của quốc gia và đội trưởng đội điều tra án giết người tinh nhuệ nhất gặp nhau để trở thành đội mạnh nhất. Ở trong phim này, sẽ có sự tham gia của các diễn viên: Kim Dong Wook, Park Ji Hwan, Seo Hyun Woo, Park Se Wan, Lee Seung Woo,... Phim Những kẻ phá hoại Seoul kể về Dongbang Yu Bin, một người đàn ông cao ráo, thông minh và thể thao, trở thành trưởng nhóm điều tra án mạng tại đồn cảnh sát Songwon. Anh từng được đề nghị làm giáo sư thường trực tại một trường đại học nổi tiếng ở nước ngoài nhưng bất ngờ quay về Hàn Quốc và tình nguyện trở thành trưởng nhóm của Đội 2 Điều tra Án Mạng tại Songwon, đội có tỷ lệ bắt giữ thấp nhất cả nước. Yu Bin quyết tâm thay đổi tình hình, nhưng ngay lập tức anh đối mặt với một loạt thách thức. Đội của anh được xem là “những kẻ phá hoại” do lối làm việc không theo quy chuẩn và những phương pháp điều tra độc đáo nhưng kém hiệu quả. Để chứng minh giá trị của mình, Yu Bin và đội của mình phải giải quyết một vụ án liên hoàn phức tạp mà không một đội nào khác dám nhận. Trong quá trình điều tra, Yu Bin hợp tác với một thủ lĩnh đội điều tra án mạng hàng đầu với phương pháp làm việc hoàn toàn trái ngược. Mối quan hệ giữa hai người từ căng thẳng ban đầu dần trở nên ăn ý hơn qua từng vụ án. Họ bắt đầu hiểu và học hỏi lẫn nhau, từng bước hình thành nên một đội ngũ mạnh mẽ không ai ngờ tới, vừa có khả năng phá án tài tình vừa mang đến tiếng cười sảng khoái cho khán giả.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Dong Wook","avatar":""},{"name":"Park Ji Hwan","avatar":""},{"name":"Seo Hyun Woo","avatar":""},{"name":"Park Se Wan","avatar":""},{"name":"Lee Seung Woo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324224);
