INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-3000-lan', 'Yêu Em 3000 Lần', 'Love You 3000 Times', 'https://phimimg.com/upload/vod/20241030-1/12b8b02e7891c9a491d475ebb33bcf78.jpg', 'https://phimimg.com/upload/vod/20241030-1/747e850e70a3acfddd2d9a819f858d21.jpg', '<p>Yêu Em 3000 Lần xoay quanh câu chuyện hấp dẫn của Shen Xingchen, người sau một vụ tai nạn giao thông đã tỉnh dậy và phát hiện ra linh hồn mình đã được chuyển đến tương lai ba năm, trong cơ thể của anh trai song sinh He Yuchuan. Sống dưới một danh tính giả, anh gặp nhiều thử thách từ người yêu cũ Jiang Muyi. Cùng nhau, họ phải hợp tác để khám phá sự thật về vụ tai nạn trong khi đối mặt với một âm mưu phức tạp. Từ đó, mối tình giữa họ bắt đầu lại, đầy những cảm xúc và thách thức mới.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hu Wen Zhe","avatar":""},{"name":"Poppy","avatar":""},{"name":"Mai Tong","avatar":""},{"name":"Li Mo Han","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wan Ban Chen Lun","Love You 3000 Times","万般沉沦"]', 1784690324225);
