INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-biet-tuot', 'Chú Chó Biết Tuốt', 'Dog Knows Everything', 'https://phimimg.com/upload/vod/20240925-1/3d3c0f012a1f386a0a26bd5a1f481676.jpg', 'https://phimimg.com/upload/vod/20240925-1/5386894a695d5a2045c1c9501fd62ef9.jpg', '<p>Chú Chó Biết Tuốt là câu chuyện hài hước xoay quanh một nhóm bạn cao tuổi năng động và Sophie, một chú chó cảnh sát đã giải nghệ. Sau một sự cố khiến ông bị công chúng chỉ trích, diễn viên kì cựu Lee Soon Jae bỏ trốn đến đảo Geoje. Tại đây, ông vô cùng bất ngờ khi gặp chú chó Sophie và phát hiện chỉ có mình ông hiểu được tiếng sủa của nó. Với sự trợ giúp của Sophie, Lee Soon Jae cùng những người bạn mới quen bắt đầu điều tra những sự việc bí ẩn xảy ra trên đảo.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Soon Jae","avatar":""},{"name":"Kim Yong Geon","avatar":""},{"name":"Im Chae Moo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["狗之声","狗话","개소리"]', 1784690324225);
