INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-hanh-phuc', 'Vùng Đất Hạnh Phúc', 'Land of Happiness', 'https://phimimg.com/upload/vod/20241101-1/c83be1dfca968039155a839a1a29bb8d.jpg', 'https://phimimg.com/upload/vod/20241101-1/320aba19d7ba747e3cbbbaee703dfcb3.jpg', '<p>Ngày 26 tháng 10 năm 1979, một vụ ám sát tổng thống làm chấn động cả nước. Đảm nhận việc bào chữa cho Park Tae-joo, thư ký liên quan đến vụ ám sát tổng thống, luật sư Jung In-hoo bước vào phiên tòa chính trị khét tiếng nhất Hàn Quốc. Mặc dù Park Tae-joo phải đối mặt với bản án được định sẵn do địa vị quân đội của mình, Jung In-hoo vẫn chiến đấu không mệt mỏi để đảm bảo một phiên tòa công bằng, tức giận vì phiên tòa không công bằng.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"조정석","avatar":""},{"name":"이선균","avatar":""},{"name":"유재명","avatar":""},{"name":"우현","avatar":""},{"name":"이원종","avatar":""},{"name":"전배수","avatar":""},{"name":"송영규","avatar":""},{"name":"최원영","avatar":""},{"name":"강말금","avatar":""},{"name":"박훈","avatar":""},{"name":"Lee Hyun-kyun","avatar":""},{"name":"진기주","avatar":""},{"name":"유성주","avatar":""},{"name":"Kim Pub-lae","avatar":""},{"name":"임기홍","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Land of Happiness","행복의 나라"]', 1784690324225);
