INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-agatha', 'Phù Thủy Agatha', 'Agatha All Along', 'https://phimimg.com/upload/vod/20240920-1/fc946af9aaeb343ef9f393996049e05e.jpg', 'https://phimimg.com/upload/vod/20240920-1/a89c77993acc2463d820af6dfba4cdd0.jpg', '<p>Agatha Harkness bị bỏ bùa mê đã giành lại được tự do nhờ sự giúp đỡ của một thiếu niên. Bị hấp dẫn bởi lời cầu xin của cậu, cô bắt đầu thử thách Witches&#39; Road để giành lại sức mạnh của mình và khám phá động cơ của thiếu niên đó.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kathryn Hahn","avatar":""},{"name":"Joe Locke","avatar":""},{"name":"Sasheer Zamata","avatar":""},{"name":"Ali Ahn","avatar":""},{"name":"Okwui Okpokwasili","avatar":""},{"name":"Debra Jo Rupp","avatar":""},{"name":"Patti LuPone","avatar":""},{"name":"Aubrey Plaza","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Agatha À Chaque Fois par Marvel Television","女巫阿加莎","Marvels - Agatha all along","אגתה: לאורך כל הדרך","אגתה: יומני הדארקהולד","تمام مدت آگاتا","Agatha En Todas Partes de Marvel Studios","Agatha En Todas Partes de Marvel Television","Аґата увесь час","Це все Аґата","Agatha: House of Harkness","Marvel Studios'' Agatha","Agatha: Coven of Chaos","Marvel Studios'' Agatha: Coven of Chaos","Agatha: Darkhold Diaries","Marvel Studios'' Agatha: House of Harkness","Marvel Studios'' Agatha: Darkhold Dia