INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phu-thuy-agatha', 'Phù Thủy Agatha', 'Agatha All Along', 'phù thủy agatha agatha all along kathryn hahn joe locke sasheer zamata ali ahn okwui okpokwasili debra jo rupp patti lupone aubrey plaza agatha à chaque fois par marvel television 女巫阿加莎 marvels - agatha all along אגתה: לאורך כל הדרך אגתה: יומני הדארקהולד تمام مدت آگاتا agatha en todas partes de marvel studios agatha en todas partes de marvel television аґата увесь час це все аґата agatha: house of harkness marvel studios'' agatha agatha: coven of chaos marvel studios'' agatha: coven of chaos agatha: darkhold diaries marvel studios'' agatha: house of harkness marvel studios'' agatha: darkhold diaries agatha marvel television''s agatha all along agatha all along', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-thac', 'Tương Thác', 'Mistaken Love', 'https://phimimg.com/upload/vod/20241027-1/914fd4b51c8899f0bed023db8377115c.jpg', 'https://phimimg.com/upload/vod/20241027-1/3221d6ed30cd1cd9708f70d93e5bf501.jpg', '<p>Phim Tương Thác (Tuong Thac) là một bộ phim cổ trang tâm lý đầy sức hút và gây xúc động. Câu chuyện xoay quanh cuộc sống của những người dân thường trong một vùng quê xa xôi, nơi mà tình yêu và lòng hiếu thảo luôn được coi trọng. Trong phim, khán giả sẽ được chứng kiến cuộc sống khó khăn và những rắc rối của các nhân vật chính khi họ phải đối diện với những thử thách và khó khăn từ xã hội. Đồng thời, câu chuyện cũng mang đến những điều bất ngờ và kịch tính khi tình yêu và lòng hiếu thảo giữa các nhân vật được thể hiện qua từng cung bậc cảm xúc. Với diễn xuất tài năng của dàn diễn viên hàng đầu, phim Tương Thác không chỉ là một bộ phim giải trí mà còn là một tác phẩm nghệ thuật mang lại nhiều suy tư cho khán giả. Đồng thời, thông điệp về tình yêu, lòng hiếu thảo và sự hy sinh trong cuộc sống cũng được truyền đi một cách sâu sắc qua từng khoảnh khắc của phim.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shao Yuqi","avatar":""},{"name":"李岱昆","avatar":""},{"name":"閔星瀚","avatar":""},{"name":"Sun Yanen","avatar":""},{"name":"王子玖","avatar":""},{"name":"乔冠臻","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["將錯","将错"]', 1784690324225);
