INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-bat-coc-cua-nguoi-ngoai-hanh-tinh-o-manhattan', 'Vụ bắt cóc của người ngoài hành tinh ở Manhattan', 'The Manhattan Alien Abduction', 'https://phimimg.com/upload/vod/20241031-1/f7a7060ac252135c897662ec35e87baa.jpg', 'https://phimimg.com/upload/vod/20241031-1/e4639f31d72d7a7edb641b05b8bf57a6.jpg', '<p>Một người phụ nữ khẳng định đã bị bắt cóc khỏi phòng ngủ ở Manhattan. Loạt phim tài liệu này tìm hiểu xem đó là trò lừa bịp tinh vi hay là bằng chứng người ngoài hành tinh tồn tại.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Linda Napolitano","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Abducción extraterrestre en Manhattan","Abdução em Manhattan","Die Alien-Entführung von Manhattan","Enlèvement extraterrestre à Manhattan","The Manhattan Alien Abduction"]', 1784690324225);
