INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('azrael-cuoc-chien-sinh-ton', 'Azrael: Cuộc Chiến Sinh Tồn', 'Azrael', 'https://phimimg.com/upload/vod/20241009-1/952455d6b3095c7a9ebf8decc12b2312.jpg', 'https://phimimg.com/upload/vod/20241009-1/e5a34457f53887d8e5efc5b97a80000e.jpg', '<p>Azrael (2024) kể về một thế giới nơi con người sống trong im lặng tuyệt đối. Một cộng đồng nữ quyền sùng đạo truy đuổi Azrael, cô gái trẻ vừa trốn khỏi sự giam cầm. Bị bắt lại và chuẩn bị hiến tế cho một thế lực tà ác trong rừng sâu, Azrael quyết tâm chiến đấu vì sự sống, chống lại cả cộng đồng lẫn bóng tối cổ xưa đang rình rập.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Samara Weaving","avatar":""},{"name":"Vic Carmen Sonne","avatar":""},{"name":"Nathan Stewart-Jarrett","avatar":""},{"name":"Johhan Rosenberg","avatar":""},{"name":"Eero Milonoff","avatar":""},{"name":"Sebastian Bull Sarning","avatar":""},{"name":"Rea Lest","avatar":""},{"name":"Phong Giang","avatar":""},{"name":"Katariina Unt","avatar":""},{"name":"Sonia Roszczuk","avatar":""},{"name":"Valentin Tzin","avatar":""},{"name":"Vincent Willestrand","avatar":""},{"name":"Karen Bengo","avatar":""},{"name":"Peter Christoffersen","avatar":""},{"name":"Felix Leech","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Azrael: Angel of Death","عزرا","Azrael: Anjo da morte","อัศราเอล: เงียบสังเวย","Azrael, l''ange de la mort","Azrael"]', 1784690324225);
