INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tai-bat-hao-2024', 'Thiên Tài Bất Hảo', 'Bad Genius', 'https://phimimg.com/upload/vod/20241031-1/8c04a255bd3aec0eb51d94b376d86a3c.jpg', 'https://phimimg.com/upload/vod/20241031-1/ffcc0fc852bf3bd46ca52f7ff3848f6e.jpg', '<p>Một nữ sinh tài năng vượt trội, nhận thấy cơ hội thoát khỏi hoàn cảnh khó khăn của mình bằng cách giúp đỡ các bạn học giàu có gian lận trong những kỳ thi quan trọng. Tuy nhiên, điều này đặt cô vào tình thế đầy rủi ro, khi cô phải đánh đổi tương lai của mình để theo đuổi những lợi ích trước mắt.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Callina Liang","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Jabari Banks","avatar":""},{"name":"Taylor Hickson","avatar":""},{"name":"Samuel Braun","avatar":""},{"name":"Sarah-Jane Redmond","avatar":""},{"name":"Adam Beauchesne","avatar":""},{"name":"Tina Grant","avatar":""},{"name":"Conor Meadows","avatar":""},{"name":"Sarah Kelley","avatar":""},{"name":"Rob Carpenter","avatar":""},{"name":"Synto D. Misati","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["גאון רע","גאונות רעה","Ліга Мільйонерів","Mentes Peligrosas","BAD GENIUS／バッド・ジーニアス","Bad Genius"]', 1784690324225);
