INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-hoa-diem', 'Xuân Hoa Diễm', 'Kill Me Love Me', 'https://phimimg.com/upload/vod/20241014-1/d4e02c4a97ded5281682094bf10ae227.jpg', 'https://phimimg.com/upload/vod/20241014-1/bff2f79e3786f47c1f590fee55845e94.jpg', '<p>Hoàng tử Đại Viêm Mộ Dung Cảnh Hòa dẫn quân Uy Bắc giành lại lãnh thổ Thanh Châu bị mất, sau khi đánh thắng tiến vào thành, Thanh Châu đột nhiên bốc cháy. Trong thành lan tin đồn là Uy Bắc tướng quân Mộ Dung Cảnh Hòa ôm hận bách tính Thanh Châu phản bội Đại Viêm, nên sau khi vào thành liền hạ lệnh phóng hỏa tàn sát toàn thành, cũng vì vậy mà hắn từ một Uy Bắc tướng quân của đội quân chính nghĩa biến thành Tàn Sát tướng quân mà người người muốn giết. Thiếu nữ Thanh Châu Mi Lâm đau đớn vì mất đi người thân trong vụ hỏa hoạn, từ đó lập lời thề sẽ tự tay giết chết hung thủ tàn sát thành Thanh Châu. Mi Lâm gia nhập tổ chức bí mật Ám Xưởng, uống độc Mặc Mạch trở thành tử sĩ. Trải qua nhiều năm huấn luyện tàn khốc, Mi Lâm nhận nhiệm vụ hành thích đầu tiên, nhiệm vụ lần này lại chính là hành thích kẻ thù mà cô ngày đêm giày vò muốn lấy mạng hắn - hoàng tử Đại Viêm Mộ Dung Cảnh Hòa.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"劉學義","avatar":""},{"name":"吴谨言","avatar":""},{"name":"畢雯珺","avatar":""},{"name":"趙小棠","avatar":""},{"name":"陳楚河","avatar":""},{"name":"黄日莹","avatar":""},{"name":"Shao Weitong","avatar":""},{"name":"Jiang Kai","avatar":""},{"name":"Xu Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["春花焰","Kill Me Love Me"]', 1784690324225);
