INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-tinh-yeu-tuyet-dep', 'Câu Chuyện Tình Yêu Tuyệt Đẹp', 'Sweet Sixteen', 'https://phimimg.com/upload/vod/20241023-1/4646108aba68a09d9020c088ffaab2b4.jpg', 'https://phimimg.com/upload/vod/20241023-1/3b26799e1dcb6a37bca35a489b1c5d29.jpg', '<p>Thư Nhã Vọng và em trai nuôi Hạ Mộc, mối tình đầu thanh mai trúc mã Đường Tiểu Thiên cùng lớn lên bên nhau, nhưng cuộc sống vốn đang hạnh phúc lại bị đàn anh Khúc Úy Nhiên của Đường Tiểu Thiên phá vỡ. Khúc Úy Nhiên muốn chiếm hữu Thư Nhã Vọng nên đã lập bẫy và xâm hại cô, khiến Thư Nhã Vọng và Đường Tiểu Thiên phải chia tay nhau, Hạ Mộc lỡ tay làm Khúc Úy Nhiên bị thương. Vì muốn cứu Hạ Mộc, Thư Nhã Vọng lấy cái thai trong bụng làm lý do để kết hôn với Khúc Úy Nhiên, sau đó gặp sự cố sảy thai, cô mai danh ẩn tích, bỏ trốn tới xứ người. Bốn năm sau, Thư Nhã Vọng bỏ trốn khỏi quê hương gặp lại Hạ Mộc, Khúc Úy Nhiên và Đường Tiểu Thiên, khúc mắc tình cảm giữa bốn người lại quay lại...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Haodong Ma","avatar":""},{"name":"Shao Yuqi","avatar":""},{"name":"徐揚灝","avatar":""},{"name":"Zhou Yu Hang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夏有乔木，雅望天堂","夏有喬木 雅望天堂","夏有乔木雅望天堂"]', 1784690324225);
