INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-chung-dot-kich-nghich-chien', 'Đặc Chủng Đột Kích: Nghịch Chiến', 'SPECIAL RAID', 'https://phimimg.com/upload/vod/20241030-1/b9318cc4259373392004484fd29ab571.jpg', 'https://phimimg.com/upload/vod/20241030-1/67f4a60d9634b26fdd85544539c8ceb2.jpg', '<p>Miêu tả: Xích Báo là lực lượng tinh nhuệ trong đặc chủng quân đội. Trong một lần truy quét ma túy tại biên giới, họ gặp phải sự phản công từ băng đảng ma túy xuyên quốc gia, khiến đội trưởng hy sinh. Sau khi giải ngũ, anh em Xích Báo mỗi người một ngả, Tưởng Trí thâm nhập vào vương quốc của bọn buôn ma túy với quyết tâm trả thù cho đội trưởng. Còn Kha Bắc và các đồng đội mở một trại huấn luyện quân sự, sống cuộc sống yên bình. Tuy nhiên, một đoạn video đe dọa liên quan đến sự sống còn của Tưởng Trí khiến Kha Bắc phẫn nộ và quyết định đấu tranh đến cùng với băng đảng tội phạm quốc tế.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Ying Long","avatar":""},{"name":"Ma Chi","avatar":""},{"name":"Wang He He","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["特种突袭之逆战"]', 1784690324225);
