INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-roi-thoi-khong', 'Cứu Rỗi Thời Không', 'TIME AND SPACE REDEMPTION', 'https://phimimg.com/upload/vod/20241030-1/2b84502136da8147cdc7176a15937ebc.jpg', 'https://phimimg.com/upload/vod/20241030-1/836393b8918847eb677cc6404bc4aa02.jpg', '<p>Năm chàng trai trẻ lớn lên ở một thị trấn nhỏ biên giới Vân Nam, vì muốn thực hiện ước mơ nên mỗi ngày đều nỗ lực kiếm tiền, nhưng vẫn không thể thỏa mãn được xã hội thực dụng đầy ham muốn vật chất. A Triết, người anh thứ tư, còn phải lo kiếm tiền để chữa bệnh cho vợ chưa cưới, điều này khiến anh càng thêm đau đầu. Năm anh em hằng ngày đều mơ về việc phát tài, và để đạt được mục đích riêng của mình, họ lên kế hoạch “thực hiện” một vụ cướp tiệm trang sức, nhưng vì thế lại rơi vào một cuộc khủng hoảng lớn.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tan Xin Zer","avatar":""},{"name":"宋欣华","avatar":""},{"name":"Wang Zhigang","avatar":""},{"name":"孙亦沐","avatar":""},{"name":"Tian Lu","avatar":""},{"name":"Xiangrong Dong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Shi Kong Jiu Shu","Salvation Through Time and Space","时空救赎"]', 1784690324225);
