INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-si', 'Vệ Sĩ', 'The Bodyguard', 'https://phimimg.com/upload/vod/20241030-1/7a02fc7ac3cc3bd2d8cea14532f8d394.jpg', 'https://phimimg.com/upload/vod/20241030-1/da419e30bd09348051e67cae34322590.jpg', '<p>Cựu nữ đặc cảnh Chung Hiểu Nam nhận nhiệm vụ bảo vệ Lâm Tử Hào, con trai của nhà khoa học gốc Hoa Lâm Hằng trở về nước. Những thành tựu nghiên cứu khoa học mà cha con nhà họ Lâm nắm giữ đã thu hút sự thèm muốn của các tài phiệt nước ngoài. Họ cấu kết với các tổ chức tội phạm để âm mưu bắt cóc Lâm Tử Hào nhằm đánh cắp dữ liệu cốt lõi. Chung Hiểu Nam đã hợp tác cùng cảnh sát người Hoa Peter, đối đầu với băng nhóm tội phạm qua nhiều cuộc chiến cam go, và cuối cùng đã phá vỡ âm mưu của đối thủ, thành công bảo vệ Lâm Tử Hào trở về an toàn.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"屈菁菁","avatar":""},{"name":"YuanFufu","avatar":""},{"name":"杨杏","avatar":""},{"name":"淳于珊珊","avatar":""},{"name":"Ashton Chen","avatar":""},{"name":"譚凱","avatar":""},{"name":"刘峰超","avatar":""},{"name":"赵亮","avatar":""},{"name":"Yang Si","avatar":""},{"name":"Jiang Luxia","avatar":""},{"name":"Lan Man Yu","avatar":""},{"name":"Bo Lai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Bodyguard","The Body Guuard","保镖"]', 1784690324225);
