INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-hyeri-than-yeu', 'Gửi Hyeri Thân Yêu', 'Dear Hyeri', 'https://phimimg.com/upload/vod/20240923-1/a04555917d8d33208b885e78330a212e.jpg', 'https://phimimg.com/upload/vod/20240923-1/7d448d43a3c10c2f026f719d62bca2a7.jpg', '<p>Gửi Hyeri của Tôi - Dear Hyeri là một bộ phim tình cảm chữa lành xoay quanh Joo Eun Ho (Shin Hye Sun), một phát thanh viên mắc chứng rối loạn nhân dạng phân ly (Haeri có nghĩa là phân ly trong tiếng Hàn) sau khi em gái cô mất tích và cô chia tay người bạn trai lâu năm Hyun Oh (Lee Jin Wook) Joo Eun Ho là một phát thanh viên vô danh với 14 năm kinh nghiệm. Cô đấu tranh để có cơ hội được công chúng công nhận tên tuổi. Cô cũng có một nhân cách khác do một vết thương sâu trong lòng. Nhân cách khác của cô là Joo Hye Ri.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Hye Sun","avatar":""},{"name":"Lee Jin-Wook","avatar":""},{"name":"Kang Hoon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324225);
