INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-tu-an-ninh', 'Cẩm Tú An Ninh', 'The Rise Of Ning', 'https://phimimg.com/upload/vod/20241011-1/8147a32d424fbf01063e2445f2a97b4f.jpg', 'https://phimimg.com/upload/vod/20241011-1/6982e25fd6c58aaf3111d60332fe4bcd.jpg', '<p>Tiểu thư La Nghi Ninh của La gia lớn lên trong biệt viện, từ nhỏ đã không bị gò bó bởi những lễ nghi phiền phức, vì không chấp nhận thấy cảnh &quot;tam ca&quot; La Thận Viễn bị mọi người bắt nạt mà nhiều lần ra tay giúp đỡ. Dần dần cô phát hiện La Thận Viễn nhìn bề ngoài có vẻ thảm hại, nhưng thực chất lại là người văn võ song toàn. Từng chịu tổn thương trong tình cảm, La Nghi Ninh không muốn bị cầm chân trong bốn bức tường, chịu sự kiểm soát của người khác. Cô quyết tâm phá bỏ những quan niệm cũ, dùng sở trường của bản thân để mở cửa hàng kinh doanh, đạt được cuộc sống độc lập. Về phần La Thận Viễn, người sống cảnh khổ sở trong La phủ, vì ân sư bị hãm hại bỏ mạng, hắn vẫn luôn truy tìm chân tướng sự việc. La Thận Viễn cảm kích La Nghi Ninh đã mang đến cho hắn tình cảm ấm áp như người thân trong gia đình, khi cô gặp khó khăn trong kinh doanh, hắn cũng đã hết lòng ủng hộ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"张晚意","avatar":""},{"name":"任敏","avatar":""},{"name":"此沙","avatar":""},{"name":"高卿塵","avatar":""},{"name":"Wu Yuheng","avatar":""},{"name":"Hu Jiaxin","avatar":""},{"name":"Dong Siyi","avatar":""},{"name":"艾米","avatar":""},{"name":"Chen Bige","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["长街长","長街長","Chang Jie Chang","首辅养成手册","Jin Xiu An Ning","Shou Fu Yang Cheng Shou Ce","Long Life Long Street","The Rise of Ning","Cẩm Tú An Ninh","锦绣安宁"]', 1784690324225);
