INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-tam-ky', 'Trang Tâm Ký', 'The Glamorous Revenge', 'https://phimimg.com/upload/vod/20241023-1/bc35be46b7bc7163374185d48369b7f4.jpg', 'https://phimimg.com/upload/vod/20241023-1/4abb1b9a2efe5fb3632308531501d726.jpg', '<p>Để trả thù, Lâm Mộ Huyền đã dùng thuật &quot;dịch dung&quot; biến Hứa Triều Triều thành bạch nguyệt quang, dùng tuyệt kỹ thu hút kẻ chủ mưu đứng đằng sau. Trong chuyện tình &quot;trói buộc&quot; với vỏ bọc là kinh doanh hiệu làm đẹp, sự thông minh hoạt bát của Hứa Triều Triều đã khiến Lâm Mộ Huyền rơi vào lưới tình, bí mật dịch dung của Hứa Triều Triều và kế hoạch trả thù của Lâm Mộ Huyền cũng dần hé lộ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guan Yue","avatar":""},{"name":"Duan Xingyu","avatar":""},{"name":"蔡翊昇","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["朝朝暮暮美人妆","Makeup Heart Record","妆心记"]', 1784690324225);
