INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-on-do-hoa-nhung-thieu-nu', 'Làm Ơn Đó Hoa Nhung Thiếu Nữ', 'Girls Let''s Defy Fate', 'https://phimimg.com/upload/vod/20241011-1/b7bd137f06db4533a6158f9cde8d5c22.jpg', 'https://phimimg.com/upload/vod/20241011-1/347728e2b34d38766ff630f81f71f58c.jpg', '<p>Khi cô gái trẻ mắc bệnh hiếm gặp Thái Tiểu Ái bước vào &quot;Sở Môn&quot; đếm ngược sự sống gặp phải Cụ Ân Triệu lạnh lùng, cô độc và không có chút lòng thương nào với cô. Hai cô gái trẻ dường như bị số phận nguyền rủa bắt đầu cuộc hành trình đấu tranh vì sự sống, tình bạn, tình thân, tình yêu và tương lai, mà không biết rằng một âm mưu đã âm thầm chực chờ xung quanh họ từ lâu.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"孙芮","avatar":""},{"name":"Dai Meng","avatar":""},{"name":"Zhou Zhao Yuan","avatar":""},{"name":"Fei Qin Yuan","avatar":""},{"name":"Kuma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["拜托了花戎少女","被诅咒的国民少女","Bai Tuo Le, Hua Rong Shao Nv","拜託了，花戎少女","拜托了，花戎少女"]', 1784690324225);
