INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-thep-phan-6', 'Bằng Chứng Thép (Phần 6)', 'Forensic Heroes (Season 6)', 'https://phimimg.com/upload/vod/20240829-1/8ab0cf315b13e6e7d7aaffbe43c30f44.jpg', 'https://phimimg.com/upload/vod/20240829-1/4f51668138985bdcf65b61ff9eba79af.jpg', '<p>Chuyên gia pháp chứng Dư Tinh Bách (do Huỳnh Tông Trạch đóng), cảnh sát trọng án Tỉnh Hạo Nhiên (do Viên Vỹ Hào đóng) và pháp y Phạm Bội Thanh (do Thái Khiết đóng) – “tam giác thép” chỉ tin sự thật và chân tướng mà khoa học giải thích được. Bộ ba sẵn sàng đương đầu với những vụ án hóc búa nhất, tàn bạo nhất, cùng phá những vụ kỳ án như: xác thiếu niên lõa thể dưới giếng cống, băng đảng gây mê hãm hiếp, bí mật xác thiêu, tập đoàn sát thủ hiện đại, xác bay ngoài trời, ứng dụng thuê sát thủ…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Viên Vỹ Hào","avatar":""},{"name":"Thái Khiết","avatar":""},{"name":"Vương Mẫn Dịch","avatar":""},{"name":"Thái Tư Bối","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["法证先锋6之幸存者的救赎","法证先锋VI","法证先锋6","法证先锋6：幸存者的救赎","法證先鋒VI","Forensic Heroes VI: Redemption","Forensic Heroes VI","法證先鋒6","法證先鋒6 倖存者的救贖"]', 1784690324225);
