INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('failure-frame-toi-tro-thanh-manh-nhat-voi-ky-nang-trang-thai-va-huy-diet-tat-ca', 'Failure Frame: Tôi Trở Thành Mạnh Nhất Với Kỹ Năng Trạng Thái Và Hủy Diệt Tất Cả', 'Failure Frame: I Became the Strongest and Annihilated Everything with Low-Level Spells', 'https://phimimg.com/upload/vod/20241029-1/ab45ba3aa8f5ea56c387d67027fbec71.jpg', 'https://phimimg.com/upload/vod/20241029-1/10825f08c3a286bce46870216ae2bdfa.jpg', '<p>Đột nhiên bị đẩy vào một thế giới kỳ ảo, Mimori Touka và các bạn cùng lớp đã được nữ thần ở đó triệu hồi để phục vụ như những anh hùng. May mắn thay, hầu hết các học sinh đều thể hiện những kỹ năng tuyệt vời khi đến nơi, ngoại trừ Mimori, người chỉ đạt đến cấp độ E cực thấp. Nữ thần đã trục xuất Mimori đến một ngục tối - nơi không một ai có thể sống sót trở về. Nhưng hóa ra, kỹ năng của Mimori lại vô cùng lợi hại và anh ta bắt đầu kế hoạch trả thù của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryota Suzuki","avatar":""},{"name":"Saki Miyashita","avatar":""},{"name":"Karin Nanami","avatar":""},{"name":"Saori Hayami","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["靠废柴技能状态异常成为最强的我将蹂躏一切","靠废柴技能【状态异常】成为最强的我将蹂躏一切","依靠被嫌弃的【状态异常技能】而成为最强的我最终蹂躏一切","靠废材技能【状态异常】成为最强的我将蹂躏一切","Failure Frame","Hazure Waku no \"Jōtai Ijō Skill\" de Saikyō ni Natta Ore ga Subete wo Jūrin Suru made","Hazure Waku","Hazurewaku no \"Joutai Ijou Skill\" de Saikyou ni Nat