INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-chim-hoang-yen', 'Mật Danh Chim Hoàng Yến', 'Canary Black', 'https://phimimg.com/upload/vod/20241029-1/b4020d49e23694c0a311cf6a77c7919d.jpg', 'https://phimimg.com/upload/vod/20241029-1/3e0f4b1ff220ff281b562a22df5fe464.jpg', '<p>Canary Black (2024) kể về Avery Graves, một đặc vụ bị đẩy vào tình thế hiểm nghèo khi chồng cô bị nhóm khủng bố bắt cóc. Để cứu anh, cô buộc phải đối mặt với lựa chọn tàn khốc: phản bội đất nước mình hay mất đi người thân yêu nhất. Trong cuộc chiến chống lại kẻ thù, Avery phải sử dụng tất cả kỹ năng của mình để vượt qua những âm mưu</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Goran Kostić","avatar":""},{"name":"Ben Miles","avatar":""},{"name":"Jaz Hutchins","avatar":""},{"name":"Romina Tonković","avatar":""},{"name":"Ana Cilas","avatar":""},{"name":"Emma Gojković","avatar":""},{"name":"Igor Pečenjev","avatar":""},{"name":"Andrei Lenart","avatar":""},{"name":"Luka Alagić","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Canario Negro","Canari noir","قناری سیاه","黑雀特工","קנרית שחורה","Canary Black"]', 1784690324225);
