INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-toi-loi', 'Thiên Sứ Tội Lỗi', 'The Lady And Her Lovers', 'https://phimimg.com/upload/vod/20240816-1/3873624a70b2edf92a46c6939d1cf5ab.jpg', 'https://phimimg.com/upload/vod/20240816-1/1398a7862e5a4d520b3c404aae434328.jpg', '<p>Thiên Sứ Tội Lỗi là hành trình đổi đời của cô gái xinh đẹp nhưng nghèo khó Thongdee. Sau khi chuyển đến Bangkok với mong muốn có một cuộc sống tốt đẹp hơn, Thongdee bắt đầu học cách sử dụng nhan sắc để đạt được những điều mình muốn. Trong số chín người đàn ông lần lượt đi qua cuộc đời Thongdee, ai mới là người có thể mang lại hạnh phúc chân chính cho cô?</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Pimchanok Leuwisedpaiboon","avatar":""},{"name":"Jes Jespipat Tilapornputt","avatar":""},{"name":"Iang Sittha Sapanuchart","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324225);
