INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hellboy-dai-chien-quy-du', 'Hellboy: Đại Chiến Quỷ Dữ', 'Hellboy: The Crooked Man', 'https://phimimg.com/upload/vod/20241009-1/724ea490d95ba5da8051ea132fa49466.jpg', 'https://phimimg.com/upload/vod/20241009-1/67fb26596e316e12bbfb63a6f0d62030.jpg', '<p>The Crooked Man xoay quanh câu chuyện Quỷ đỏ bị mắc kẹt ở vùng nông thôn Appalachia những năm 1950 cùng với một thành viên của đội BPRD. Tại đây, họ phải đối đầu, trốn chạy cuộc truy sát của một nhóm phù thủy được dẫn đầu bởi ác quỷ Crooked Man - người có mối liên hệ rắc rối với quá khứ của Quỷ đỏ.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Đức', 1, '[{"name":"Jack Kesy","avatar":""},{"name":"Jefferson White","avatar":""},{"name":"Adeline Rudolph","avatar":""},{"name":"Martin Bassindale","avatar":""},{"name":"Leah McNamara","avatar":""},{"name":"Hannah Margetson","avatar":""},{"name":"Joseph Marcell","avatar":""},{"name":"Carola Colombo","avatar":""},{"name":"Nathan Cooper","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Hellboy et l’Homme Tordu","Hellboy: El Hombre Retorcido","天魔特攻：歪曲人的詛咒","地獄怪客：歪曲人的詛咒","地狱怪客：歪曲人的诅咒","ヘルボーイ／ザ・クルキッドマン","헬보이: 크루키드 맨","Hellboy: The Crooked Man"]', 1784690324226);
