INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-ung', 'Chim Ưng', 'Eagle', 'https://phimimg.com/upload/vod/20241028-1/d26a681eb921fede0dd78430313f433a.jpg', 'https://phimimg.com/upload/vod/20241028-1/32af994b61fa1de2f8d5671f54a5c9b3.jpg', '<p>Một nhà báo đã khám phá ra câu chuyện về một sát thủ tàn nhẫn khi cô điều tra một vụ che đậy của chính phủ.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Ravi Teja","avatar":""},{"name":"Anupama Parameswaran","avatar":""},{"name":"Kavya Thapar","avatar":""},{"name":"Navdeep","avatar":""},{"name":"Vinay Rai","avatar":""},{"name":"Srinivas Avasarala","avatar":""},{"name":"Madhoo","avatar":""},{"name":"Ajay Ghosh","avatar":""},{"name":"Srinivasa Reddy","avatar":""},{"name":"Mahaboob Basha","avatar":""},{"name":"Mirchi Kiran","avatar":""},{"name":"Sivannarayana Naripeddi","avatar":""},{"name":"ప్రణీత పట్నాయక్","avatar":""},{"name":"Surya Bhagawan Das","avatar":""},{"name":"Seshi Rao","avatar":""},{"name":"Master Dhruvan","avatar":""},{"name":"Madee Manepa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ఈగల్"]', 1784690324226);
