INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sat-thu', 'Nữ Sát Thủ', 'Dominique', 'https://phimimg.com/upload/vod/20241028-1/65cc107b3c54f6a8b16ee30f7c7848a2.jpg', 'https://phimimg.com/upload/vod/20241028-1/063e9b95cbcd2b71268ee3c18dac5973.jpg', '<p>Một sát thủ chuyên nghiệp đang chạy trốn khỏi quá khứ đầy rắc rối, gặp tai nạn máy bay và rơi xuống một thị trấn nhỏ ở Colombia, nơi đầy rẫy bạo lực. Cô được một gia đình địa phương cưu mang, nhưng lại bị cảnh sát truy đuổi. Dominique phải lựa chọn giữa việc bảo vệ bản thân hay đứng lên bảo vệ những người đã che chở cho mình. Khi người đàn ông duy nhất cô quan tâm bị sát hại dã man, Dominique quyết định hy sinh bản thân để bảo vệ gia đình vô tội của anh và huấn luyện họ chiến đấu chống lại chính quyền tham nhũng và băng đảng ma túy tàn bạo chịu trách nhiệm cho cái chết của anh.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Colombia', 0, '[{"name":"Oksana Orlan","avatar":""},{"name":"Sebastián Carvajal","avatar":""},{"name":"María del Rosario","avatar":""},{"name":"Maurice Compte","avatar":""},{"name":"Chase Coleman","avatar":""},{"name":"Ski Carr","avatar":""},{"name":"Jose Conejo Martin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["多米尼克：凤凰崛起","Dominique - Rise of the Phoenix","多明妮克：刺客復出","דומיניק","Dominique"]', 1784690324226);
