INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-sat-thu', 'Nữ Sát Thủ', 'Dominique', 'nữ sát thủ dominique oksana orlan sebastián carvajal maría del rosario maurice compte chase coleman ski carr jose conejo martin 多米尼克：凤凰崛起 dominique - rise of the phoenix 多明妮克：刺客復出 דומיניק dominique', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-an-ho-muoi', 'Dự Án Hồ Muối', 'Salt Lake Project', 'https://phimimg.com/upload/vod/20241028-1/da58f01adfa20b627339a9f0f36db316.jpg', 'https://phimimg.com/upload/vod/20241028-1/1125b93cae9e99667b43aa106d8a8147.jpg', '<p>Dự Án Hồ Muối là một bộ phim hài phiêu lưu xoay quanh câu chuyện về Lão Tương, một người đàn ông mang trong mình một bí mật và kế hoạch trả thù. Anh ta giả vờ điên rồ và ngu ngốc dưới sự chỉ đạo của đại ca Lao Ying để thực hiện mục tiêu của mình. Trên đường đi, anh va chạm với tài xế ô tô màu đen Liu Lu, không ngờ rằng họ lại có liên quan đến công việc kinh doanh ngầm của thủ lĩnh độc ác Deyi. Những tình huống dở khóc dở cười diễn ra khi Lão Tương và Liu Lu cùng nhau hợp tác để giải quyết các rắc rối trên con đường trả thù của Lão Tương. Cả hai không biết rõ đích đến cuối cùng của hành trình này nhưng lại tạo nên những khoảnh khắc vui nhộn và gây cười cho khán giả. Với sự tham gia của các diễn viên nổi tiếng như Ngô Chấn Ngọc, Xu Juncong, Sheng Shao và Lu Lei, Dự Án Hồ Muối hứa hẹn sẽ mang lại những phút giây giải trí sảng khoái và thú vị cho khán giả yêu thích phim hài.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"吳鎮宇","avatar":""},{"name":"许君聪","avatar":""},{"name":"盛冠森","avatar":""},{"name":"关雪盈","avatar":""},{"name":"Ryu Kohata","avatar":""},{"name":"佟磊","avatar":""},{"name":"Shao Laowu","avatar":""},{"name":"王翰闻","avatar":""},{"name":"Shao Jie Rui","avatar":""},{"name":"Cao Xixi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Saline Lake Project","盐湖计划"]', 1784690324226);
