INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-lenh-bi-an', 'Mật Lệnh Bí Ẩn', 'Classified', 'https://phimimg.com/upload/vod/20241028-1/1a7b31a104741546bdc00a667db0c3a7.jpg', 'https://phimimg.com/upload/vod/20241028-1/a29b2b42c9dcec5218495cb8a3ab36af.jpg', '<p>Một sát thủ kỳ cựu của CIA, luôn nhận nhiệm vụ qua các mục rao vặt trên báo, đột ngột phát hiện ra rằng đơn vị của mình đã bị giải thể từ lâu mà anh không hề hay biết. Điều này đẩy anh vào một âm mưu nguy hiểm, nơi mọi thứ anh tin tưởng đều có thể chỉ là vỏ bọc.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Abigail Breslin","avatar":""},{"name":"Matt Hookings","avatar":""},{"name":"Lucky Ali","avatar":""},{"name":"Joe Azzopardi","avatar":""},{"name":"Kirsty Bartolo","avatar":""},{"name":"Marc Cabourdin","avatar":""},{"name":"Myles Clohessy","avatar":""},{"name":"Kim DeLonghi","avatar":""},{"name":"Mariah Hardy","avatar":""},{"name":"Brandon Lessard","avatar":""},{"name":"Mark Meilak","avatar":""},{"name":"Massimo P Morana","avatar":""},{"name":"Mike Parish","avatar":""},{"name":"Marysia S. Peres","avatar":""},{"name":"Paul Portelli","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Objetivo Secreto","Classified"]', 1784690324226);
