INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-khoang-troi-song-song', 'Hai Khoảng Trời Song Song', 'Under Parallel Skies', 'https://phimimg.com/upload/vod/20241028-1/9dfebe87e788e8a4914dcee62def0921.jpg', 'https://phimimg.com/upload/vod/20241028-1/53b734ff0b1aa9f27c862287006e3ce4.jpg', '<p>Một thước phim tình cảm nhẹ nhàng nhưng đọng lại nhiều cảm xúc đến từ cặp đôi Win Metawin và Janella Salvador. Nhân duyên đưa họ đến với nhau ở một đất nước xa lạ và cũng đem đến nhiều cảm xúc phức tạp để họ khám phá bản thân mình.</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Hồng Kông', 1, '[{"name":"เมธวิน โอภาสเอี่ยมขจร","avatar":""},{"name":"Janella Salvador","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sa Ilalim ng Magkakaibang Langit"]', 1784690324226);
