INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-vo', 'Dễ Vỡ', 'Fragile', 'https://phimimg.com/upload/vod/20240910-1/62bcf56955ccdde146a2946d08e6f1ff.jpg', 'https://phimimg.com/upload/vod/20240910-1/582d4d76beb12a2c098ff82e085f49da.jpg', '<p>Có phải điểm thấp của trung tâm dạy kèm đang làm phiền Ji Yu? Hay đó là đôi vai lạnh lùng ở trường? Ji Yu cảm thấy mình thật nhỏ bé và cố gắng tìm kiếm sự bình yên thông qua bạn trai của mình. Ji Yu không tìm được bạn bè sau khi học kỳ bắt đầu, nhưng A Ra, học sinh chuyển trường, đã tiếp cận Ji Yu. Trong khi đó, Ji Yu bắt đầu nghi ngờ về Chan Seong - cả thế giới của cô...</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim So Hee","avatar":""},{"name":"Kim Eo Jin","avatar":""},{"name":"Gong Ju Han","avatar":""},{"name":"Kwon Hee Song","avatar":""},{"name":"Mun Ji Won","avatar":""},{"name":"Cha Ji Hyeok","avatar":""},{"name":"Cha Se Jin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324226);
