INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-duyen', 'Lương Duyên', 'Fateful Love', 'https://phimimg.com/upload/vod/20241021-1/93a27346d62bc0b93b31e859fcf21f8e.jpg', 'https://phimimg.com/upload/vod/20241021-1/b9a8a840ea5079b3a511115d2378c395.jpg', '<p>Truyền thuyết kể rằng, ngọc Bất Dạ có thể chữa bách bệnh nhưng lại mang lời nguyền chết chóc, chỉ có máu trong tim của con gái nhà họ Nguyễn mới hóa giải được. Để thoát khỏi số phận sống không quá 30 tuổi, Cố Tuy Chi đã bày mưu khiến Nguyễn Thù, cô bé mồ côi nhà họ Nguyễn phải lòng mình. Khi cả hai đang giằng xé giữa tình yêu và sự cứu rỗi, lại vô tình đánh thức ân oán từ kiếp trước...</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Ruotian","avatar":""},{"name":"Xu Shiyue","avatar":""},{"name":"Xu Heni","avatar":""},{"name":"Xin Yue","avatar":""},{"name":"Lei Siyu","avatar":""},{"name":"Yu Zhan Jiang","avatar":""},{"name":"郑千亦","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["流光鉴良缘","傲娇系暖婚","良缘"]', 1784690324226);
