INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-thuong-long', 'Vết Thương Lòng', 'Killer Heat', 'https://phimimg.com/upload/vod/20241001-1/627df24c4e437939574aafe93270fefb.jpg', 'https://phimimg.com/upload/vod/20241001-1/2c86db73cb3e03778269f5413da73451.jpg', '<p>Một bí ẩn đương đại ly kỳ theo phong cách phim đen cổ điển, Killer Heat theo chân thám tử tư Nick Bali (Joseph Gordon-Levitt), một người Mỹ xa xứ ở Hy Lạp, được thuê để điều tra cái chết được cho là do tai nạn của ông trùm vận tải biển trẻ tuổi Leo Vardakis (Richard Madden) trên đảo Crete. Chị dâu của nạn nhân (Shailene Woodley) không tin vào báo cáo chính thức của cảnh sát. Nhưng điều gì đã thực sự xảy ra với Leo và tại sao? Bất chấp vẻ đẹp tràn ngập ánh nắng của Địa Trung Hải kỳ lạ, Nick thấy bóng tối ở mọi ngã rẽ: nơi gia đình Vardakis giàu có và quyền lực cai trị như các vị thần, nơi sự ghen tuông ăn sâu, và bất kỳ ai cũng có thể là nghi phạm.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Richard Madden","avatar":""},{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Shailene Woodley","avatar":""},{"name":"Babou Ceesay","avatar":""},{"name":"Clare Holman","avatar":""},{"name":"Abbey Lee","avatar":""},{"name":"Manos Gavras","avatar":""},{"name":"Αργύρης Γκαγκάνης","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Jealousy Man","گرمای کشنده","آفتاب سوزان","Pokoli hőség","Killer Heat"]', 1784690324226);
