INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-tham', 'Yêu Thầm', 'A Secretly Love', 'https://phimimg.com/upload/vod/20241026-1/5a91f65660185f331209ccde6440e86d.jpg', 'https://phimimg.com/upload/vod/20241026-1/d9bdf32532a18560aef509409b36702c.jpg', '<p>Pluem lại bị người yêu cũ là Sroi chia tay và còn bị cô tát thẳng mặt giữa đám đông. Konprod đang học năm ba đã tận mắt chứng kiến cảnh này. Đây không phải lần đầu cậu nhìn thấy Pluem bị cô gái mình thích nói lời chia tay. Hay nói cách khác, cậu đã bắt gặp tình huống tương tự rất nhiều lần đến mức thành quen. Giương mắt nhìn Pluem ở trong tình cảnh khốn khổ như vậy trong thời gian dài mà cậu không có quyền gì để xen vào...</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Varodom Khemmonta","avatar":""},{"name":"Tanawat Sukfuengfoo","avatar":""},{"name":"Patthama Panthong","avatar":""},{"name":"Pun Chatpong Harnharuiharn","avatar":""},{"name":"Pong Chupat Harnharuiharn","avatar":""},{"name":"Seagame Phadtraruengrid Namwongyot","avatar":""},{"name":"Bam Gunganis Mangmee","avatar":""},{"name":"Bombom Nuntika Ransri","avatar":""},{"name":"Josh Benj Toopkrajang","avatar":""},{"name":"Note Mahatsajan Matsri","avatar":""},{"name":"Ice Thawatcha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暗恋","PLUM KHONPROAD","plumkhonproad","A Secretly Love","ปลื้มคนโปรด"]', 1784690324226);
