INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-xa-phu-sinh', 'Bạch Xà: Phù Sinh', 'White Snake: Afloat', 'https://phimimg.com/upload/vod/20241019-1/c93d2587ccd078f85f3367ca7f6bf2df.jpg', 'https://phimimg.com/upload/vod/20241019-1/9c45d3809d24076c5e89695602394191.jpg', '<p>Nam Tống Hàng Châu, tiểu Bạch tiểu Thanh tìm kiếm được a tuyên chuyển thế Hứa Tiên. Tiểu Bạch cùng Hứa Tiên cuối cùng thành vợ chồng. Hai người xây dựng bảo an đường trị bệnh cứu người, lại bị Pháp Hải nhìn thấu tiểu Bạch cùng tiểu Thanh yêu quái thân phận, muốn ngăn cản tiểu Bạch cùng Hứa Tiên cùng một chỗ.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"杨天翔","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["White Snake III","White Snake 3","白蛇3：浮生","白蛇3","Bai She 3: Fusheng","Bai She: Fusheng","White Snake:  Afloat","مار سفید: شناور","Белая Змея: Жизнь на воде","A Serpente Branca: À tona","A Serpente Branca 3","White Snake 3: Afloat","백사 3: 부생","白蛇：浮生"]', 1784690324226);
