INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-sau-chia-tay', 'Câu Chuyện Sau Chia Tay', 'What Comes After Love', 'https://phimimg.com/upload/vod/20240928-1/fdad458ca71ac5c3a8664a62ed15f25c.jpg', 'https://phimimg.com/upload/vod/20240928-1/9f28f6f03f85fd140475a641fb076328.jpg', '<p>Hong Yi, 30 tuổi, đã chôn vùi quá khứ với Joon Go ở Nhật Bản. Nhưng khi anh trở lại Hàn Quốc, quá khứ ấy bất ngờ sống dậy. Liệu cuộc gặp gỡ này sẽ là cơ hội để họ hàn gắn những vết thương cũ, hay lại một lần nữa khiến trái tim cô tan vỡ?</p>', 'Tập 6', 6, 'series', 'ongoing', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이세영","avatar":""},{"name":"坂口健太郎","avatar":""},{"name":"홍종현","avatar":""},{"name":"中村アン","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["爱过之后来临的","愛のあとにくるもの","Things That Come After Love","То, что приходит после любви","ما يحدث بعد الوقوع بالحب","愛過之後來臨的","What Comes After Love","사랑 후에 오는 것들"]', 1784690324226);
