INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-lay-phan-3', 'Vũng Lầy (Phần 3)', 'The Mire (Season 3)', 'https://phimimg.com/upload/vod/20241023-1/8cb61e496f2ad3b5930b9d9a11818337.jpg', 'https://phimimg.com/upload/vod/20241023-1/e27d8d0aed8bc583350a9bbba2dda3c1.jpg', '<p>Trận lụt thế kỷ làm lộ ra một thi thể khác trong rừng Gronty, và cùng với nó là nạn tham nhũng, những vụ lừa đảo từ thập niên 90 và bí mật bị che giấu từ Thế chiến II.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Ba Lan', 0, '[{"name":"Andrzej Seweryn","avatar":""},{"name":"Magdalena Różczka","avatar":""},{"name":"Dawid Ogrodnik","avatar":""},{"name":"Łukasz Simlat","avatar":""},{"name":"Filip Pławiak","avatar":""},{"name":"Piotr Fronczewski","avatar":""},{"name":"Janusz Gajos","avatar":""},{"name":"Tomasz Schuchardt","avatar":""},{"name":"Agnieszka Żulewska","avatar":""},{"name":"Michał Pawlik","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Mire ''97","泥潭1997","泥潭","The Mire","Rojst ''97","Rojst Millenium","The Mire Millennium","Rojst"]', 1784690324226);
