INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-lay-phan-3', 'Vũng Lầy (Phần 3)', 'The Mire (Season 3)', 'vũng lầy (phần 3) the mire (season 3) andrzej seweryn magdalena różczka dawid ogrodnik łukasz simlat filip pławiak piotr fronczewski janusz gajos tomasz schuchardt agnieszka żulewska michał pawlik the mire ''97 泥潭1997 泥潭 the mire rojst ''97 rojst millenium the mire millennium rojst', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-da-tuyet', 'Thất Dạ Tuyết', 'Snowy Night Timeless Love', 'https://phimimg.com/upload/vod/20241011-1/8f243be95dd6ffa296b5a2df520f3810.jpg', 'https://phimimg.com/upload/vod/20241011-1/c1dc7b2776bc2069c2492b53ea15fc64.jpg', '<p>“Thất dạ tuyết” là một bộ phim võ hiệp cổ trang do đạo diễn Nhậm Hải Đào (đạo diễn của &quot;Liên Hoa Lâu&quot;) và Lương Thắng Quyền (đạo diễn của &quot;Hoa Thiên Cốt&quot;) đồng chấp bút, có sự tham gia của Lý Thấm (diễn viên chính của &quot;Khánh Dư Niên Đệ Nhất Quý&quot;) và Tăng Thuấn Hy (diễn viên của &quot;Liên Hoa Lâu&quot;). Bộ phim được chuyển thể từ tiểu thuyết cùng tên của Thương Nguyệt. Trong câu chuyện, Hoắc Triển Bạch (do Tăng Thuấn Hy thủ vai), một kiếm khách tự do, để cứu mạng con trai của một người bạn, đã gặp Tiết Tử Dạ (do Lý Thấm thủ vai), một dược sư tài năng. Trong thời gian tám năm, họ đã sống chung và từ những tâm tư riêng biệt, đã dần dần hiểu biết và cảm thông lẫn nhau. Mối quan hệ của họ không chỉ là sự đồng lòng, mà còn là sự hiểu biết sâu sắc và thỏa thuận cùng nhau uống rượu dưới gốc cây mận vào năm tới. Nhưng do gánh vác những trách nhiệm riêng mà khó nói lên tình yêu, cuối cùng chỉ để lại niềm tiếc vĩnh cửu vì sự xa cách mãi mãi.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"李沁","avatar":""},{"name":"曾舜晞","avatar":""},{"name":"Wang Hongyi","avatar":""},{"name":"Edward Chen","avatar":""},{"name":"Jenny Zeng","avatar":""},{"name":"Jin Zehao","avatar":""},{"name":"Shao Yuqi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Snowy Night · Timeless Love","Snowy Night: Timeless Love","Семь снежных ночей","七夜雪","Snowy Night Timeless Love"]', 1784690324226);
