INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-nghiep-ban-thai', 'Khởi Nghiệp (Bản Thái)', 'Start-Up', 'https://phimimg.com/upload/vod/20241024-1/31420c0a2b7f4553a84941b2e830ff48.jpg', 'https://phimimg.com/upload/vod/20241024-1/94f147c80c5e72d073746b70dd1ec4ea.jpg', '<p>Được remake theo bản Hàn Quốc. Khởi Nghiệp - Start Up (bản Thái) là câu chuyện kể về khát vọng của một thế hệ thanh niên mới khởi nghiệp, cạnh tranh để đạt được thành công và tình yêu trong thế giới tàn khốc của ngành công nghệ cao ở Thái Lan.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"ภูมิพัฒน์ เอี่ยมสำอาง","avatar":""},{"name":"Kemisara Paladesh","avatar":""},{"name":"สพล อัศวมั่นคง","avatar":""},{"name":"อรัชพร โภคินภากร","avatar":""},{"name":"Talay Sanguandikul","avatar":""},{"name":"เพ็ญพักตร์ ศิริกุล","avatar":""},{"name":"นีรนุช ปัทมสูต","avatar":""},{"name":"Nonzee Nimibutr","avatar":""},{"name":"ธิติยา จิระพรศิลป์","avatar":""},{"name":"Buakaw Banchamek","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["สตาร์ทอัพ","Start Up","Start-Up"]', 1784690324226);
