INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoi-nghiep-ban-thai', 'Khởi Nghiệp (Bản Thái)', 'Start-Up', 'khởi nghiệp (bản thái) start-up ภูมิพัฒน์ เอี่ยมสำอาง kemisara paladesh สพล อัศวมั่นคง อรัชพร โภคินภากร talay sanguandikul เพ็ญพักตร์ ศิริกุล นีรนุช ปัทมสูต nonzee nimibutr ธิติยา จิระพรศิลป์ buakaw banchamek สตาร์ทอัพ start up start-up', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-tro-lai', 'Cô Ấy Trở Lại', 'Veil Of Revenge', 'https://phimimg.com/upload/vod/20241023-1/f8169d7d25588ec96b832e859fc8900f.jpg', 'https://phimimg.com/upload/vod/20241023-1/75f95fefbee6b429e91b781513b9fd9b.jpg', '<p>Trong quán bar, Lý Chí Nhân đang chờ bạn gái Trương Lộ Lộ nhưng lại bị một người phụ nữ bí ẩn tên Trần Duyệt Nhiên thu hút. Anh ngạc nhiên phát hiện ra cô không chỉ là đại diện của đối tác mà còn dần dần bước vào cuộc sống của anh. Tuy nhiên, sự thật dần hé lộ. Trần Duyệt Nhiên chính là người vợ cũ mà anh tưởng đã chết, nay đổi tên trở về chỉ để trả thù. Cô thận trọng từng bước, vạch trần bí mật của Trương Lộ Lộ và lôi kéo cô ta trở thành tay sai của mình, cuối cùng tống Lý Chí Nhân vào tù. Đồng thời, giữa Trần Duyệt Nhiên và Cao Lăng Vũ, một người đàn ông đầy quyền lực dần nảy sinh tình cảm, mở ra một cuộc đấu tranh thầm lặng giữa sự trả thù và tình yêu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gong Xiaojun","avatar":""},{"name":"李冰冰","avatar":""},{"name":"閔星瀚","avatar":""},{"name":"Zhou Luoyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Girl is Back","歸來的她","归来的她"]', 1784690324226);
