INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-nguoc-thoi-gian-vi-em', 'Đảo Ngược Thời Gian Vì Em', 'Reverse 4 You', 'https://phimimg.com/upload/vod/20240923-1/f755aef2a9ef504e9321ce06abc777b1.jpg', 'https://phimimg.com/upload/vod/20240923-1/fb811795d9a7389a78b79ebebe490822.jpg', '<p>Một người biết trước tương lai, còn người kia kiểm soát thời gian. Khi tình yêu đã hứa dường như phải chịu bi kịch, cặp đôi bắt đầu thay đổi số phận.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Methakarn Anektanasuwan","avatar":""},{"name":"Gulasatree Michalsky","avatar":""},{"name":"Natnicha Polsombat","avatar":""},{"name":"Thitinan Rattanathitinan","avatar":""},{"name":"Moniejaya Tanaryan","avatar":""},{"name":"Jirapat Rakkapoomphan","avatar":""},{"name":"Apasra Lertprasert","avatar":""},{"name":"Chotika Prapasjetsada","avatar":""},{"name":"Alicha Sriprathak","avatar":""},{"name":"Bom Nontach Thanawatyanyong","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ดาวบริวาร The Series","Reverse 4 You The Series","R4Y","Reverse.4.You","ดาวบริวาร"]', 1784690324226);
