INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-thien-kim-ta-day', 'Bổn Thiên Kim Ta Đây', 'The Princess', 'https://phimimg.com/upload/vod/20241011-1/5026d41d84c8ce24983e34d61140477f.jpg', 'https://phimimg.com/upload/vod/20241011-1/d6ee08a39fd7068a6cec306c254906c9.jpg', '<p>Thu Nhược Nhiễm, cô chủ nhà họ Thu, hóa thân thành Giang Như Nhược thoát khỏi thảm án diệt môn. Cô dùng thân phận thư ký thâm nhập vào nhà họ Tiêu để báo thù. Để cứu em trai Mộ Nhiễm, trời xui đất khiến cô lại trở thành &quot;vợ chồng giả&quot; với Cố Ngạn Đình, con nuôi của lão đốc quân ẩn náu bên cạnh Tiêu Ly. Cả hai hợp tác cùng đấu trí đấu dũng với Tiêu Ly! Giang Như Nhược từng bước vén lớp màn âm mưu và dối trá, cuối cùng đã vạch trần sự thật...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuan Hao","avatar":""},{"name":"姜之南","avatar":""},{"name":"Qiu Hongkai","avatar":""},{"name":"Jackey Zhu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["如若","If I First Saw You","我本千金"]', 1784690324226);
