INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-ho-caddo', 'Bí Ẩn Hồ Caddo', 'Caddo Lake', 'https://phimimg.com/upload/vod/20241022-1/ae33be03960eb93cd2f62aa0e70ba582.jpg', 'https://phimimg.com/upload/vod/20241022-1/96e2ed75ed2004f4af0b234f1d8e8226.jpg', '<p>&quot;Caddo Lake&quot; (2024) xoay quanh sự mất tích bí ẩn của một bé gái 8 tuổi tại hồ Caddo. Sự kiện này dần hé lộ những cái chết và vụ mất tích trong quá khứ, xâu chuỗi những bí ẩn đen tối, từ đó làm thay đổi số phận của một gia đình đang trên bờ vực tan vỡ.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dylan O''Brien","avatar":""},{"name":"Eliza Scanlen","avatar":""},{"name":"Lauren Ambrose","avatar":""},{"name":"Sam Hennings","avatar":""},{"name":"Diana Hopper","avatar":""},{"name":"Eric Lange","avatar":""},{"name":"Lance E. Nichols","avatar":""},{"name":"Nina Leon","avatar":""},{"name":"David Maldonado","avatar":""},{"name":"Kim Baptiste","avatar":""},{"name":"Jules Hilillo Fernandez","avatar":""},{"name":"Jody Sellers","avatar":""},{"name":"Caroline Falk","avatar":""},{"name":"Greysen Conley","avatar":""},{"name":"Larry S. White","avatar":""},{"name":"Zedrick Tinsley","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Vanishings at Caddo Lake","Caddo","دریاچه کادو","Os Horrores de Caddo Lake","Caddo Lake"]', 1784690324226);
