INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-an-ho-caddo', 'Bí Ẩn Hồ Caddo', 'Caddo Lake', 'bí ẩn hồ caddo caddo lake dylan o''brien eliza scanlen lauren ambrose sam hennings diana hopper eric lange lance e. nichols nina leon david maldonado kim baptiste jules hilillo fernandez jody sellers caroline falk greysen conley larry s. white zedrick tinsley a the vanishings at caddo lake caddo دریاچه کادو os horrores de caddo lake caddo lake', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-vo-thuc', 'Thế Giới Vô Thực', 'This World Is Not Real', 'https://phimimg.com/upload/vod/20241017-1/ff705dba087ba8eda301fa9522a74062.jpg', 'https://phimimg.com/upload/vod/20241017-1/cc704e6c32fc60ebbe95f2bfe39af4ae.jpg', '<p>Nhà thiết kế trò chơi Tình Vãn gặp tai nạn giao thông rồi hôn mê kéo dài. Chồng sắp cưới của cô, Lâm Hiển, là tổng giám đốc công ty game hàng đầu. Để đánh thức Tình Vãn, anh đã kết nối ý thức của cô với &quot;Tạo Cảnh&quot; - một công nghệ mô phỏng không gian và thời gian giống thế giới thực. Khi Lâm Hiển bước vào không gian Tạo Cảnh, anh phát hiện ra Tình Vãn đã quên anh. Để khơi dậy ký ức của cô, anh đã nhờ cô phát triển game ảo &quot;Thế Giới Vô Thực”. Đối thủ cạnh tranh lớn nhất của anh, Hách Phàm, muốn đánh cắp công nghệ “Tạo Cảnh”, đã mua chuộc trợ lý của Lâm Hiển là Hạ Lan Tuyết nhằm cài virus vào Tạo Cảnh. Thế giới ảo trở nên ngày càng nguy hiểm, Lâm Hiển quyết định hy sinh bản thân để đưa Tình Vãn rời khỏi đó. Từ đó Tình Vãn bắt đầu hành trình thức tỉnh…</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"张炯敏","avatar":""},{"name":"包晨希","avatar":""},{"name":"李权哲","avatar":""},{"name":"黃鑫","avatar":""},{"name":"张泽宇","avatar":""},{"name":"和子琪","avatar":""},{"name":"王楚渝","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qing Wan Zhi Lin","晴晚之林","This World Is Not Real"]', 1784690324226);
