INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-vo-thuc', 'Thế Giới Vô Thực', 'This World Is Not Real', 'thế giới vô thực this world is not real 张炯敏 包晨希 李权哲 黃鑫 张泽宇 和子琪 王楚渝 qing wan zhi lin 晴晚之林 this world is not real', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-nuong-thay-the', 'Tân Nương Thay Thế', 'The Killer Bride', 'https://phimimg.com/upload/vod/20241018-1/16c40debaf2eaf4158ec35a0064dd3cb.jpg', 'https://phimimg.com/upload/vod/20241018-1/7e9fd6e11bf9dc0a7227116110188e48.jpg', '<p>Nữ sát thủ trẻ mất trí nhớ tên Nguyệt Dao, năm mười sáu tuổi cuối cùng cũng đón nhận nhiệm vụ ám sát đầu tiên của mình. Nguyệt Dao nhận lệnh từ sư phụ để ám sát Tướng quân Hạc Vân Hành nổi tiếng tàn ác của Nha Môn Mười Bốn. Nguyệt Dao thâm nhập vào phủ tướng quân nhưng thất bại, lại còn bị Hạc Vân Hành thiết kế trở thành tân nương vừa được hắn cưới vào cửa! Để hoàn thành nhiệm vụ ám sát, Nguyệt Dao đành phải đóng giả làm tân nương mới cưới của Hạc Vân Hành. Không lâu sau, trong phủ tướng quân liên tục xảy ra những vụ án mạng liên hoàn, và Nguyệt Dao trở thành nghi phạm chính. Trong sự kích động của những vụ án đẫm máu, Nguyệt Dao dần dần bắt đầu khôi phục trí nhớ đã mất của mình, nhưng lúc này cô vẫn chưa biết rằng mình đã bị cuốn vào một âm mưu kinh thiên động địa.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Junchen","avatar":""},{"name":"Lin Siyi","avatar":""},{"name":"Zhang Yike","avatar":""},{"name":"Zhu Minxin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["权臣谋爱之掌中欢","Love of the Minister","Substitute Bride","替婚新娘"]', 1784690324226);
