INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-khac-im-lang', 'Giờ Khắc Im Lặng', 'The Silent Hour', 'https://phimimg.com/upload/vod/20241022-1/059b9e961a6e7cd9f69cafabe8b70c55.jpg', 'https://phimimg.com/upload/vod/20241022-1/1a3ef19d006f7beb0ea32af414b27851.jpg', '<p>The Silent Hour 2024 xoay quanh một thám tử bị suy giảm thính lực và một nhân chứng bị điếc đã chứng kiến một vụ giết người. Cả hai buộc phải dựa vào nhau để vượt qua những kẻ sát nhân khi họ bị mắc kẹt trong một khu chung cư bỏ hoang. Điều đặc biệt là họ phải đối mặt với kẻ thù mà họ không thể nghe thấy, tạo nên những tình huống căng thẳng và kịch tính, khi từng phút trôi qua đều là cuộc chiến giành sự sống trong thế giới im lặng.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joel Kinnaman","avatar":""},{"name":"Sandra Mae Frank","avatar":""},{"name":"Mekhi Phifer","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Michael Eklund","avatar":""},{"name":"Anthony Grant","avatar":""},{"name":"Jonathan Koensgen","avatar":""},{"name":"Mike Parish","avatar":""},{"name":"Seán James Sutton","avatar":""},{"name":"Djinda Kane","avatar":""},{"name":"Jamaal Grant","avatar":""},{"name":"Matthew Camilleri","avatar":""},{"name":"Chris Dingli","avatar":""},{"name":"Shane Rowe","avatar":""},{"name":"Anselmo DeSousa","avatar":""},{"name":"Marko Nikolic","avatar":""},{"name":"Becky Cam","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["La hora del silencio","寂静时刻","ساعت سکوت","The Silent Hour"]', 1784690324226);
