INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trea-turner-quay-dau', 'Trea Turner: Quay Đầu', 'The Turnaround', 'https://phimimg.com/upload/vod/20241021-1/a97c963d164d4dceb04a31f682978829.jpg', 'https://phimimg.com/upload/vod/20241021-1/ba5a4d60aab54340888df8f3e7c39468.jpg', '<p>Trong bộ phim tài liệu ngắn kích thích này, một cổ động viên trung thành của đội Phillies đã truyền cảm hứng để mọi người cổ vũ một cầu thủ đang chật vật, giúp xoay chuyển thế cục.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon McCann","avatar":""},{"name":"Alex Rodriguez","avatar":""},{"name":"Trea Turner","avatar":""},{"name":"J.D. Drew","avatar":""},{"name":"Kyle Schwarber","avatar":""},{"name":"John Kruk","avatar":""},{"name":"Tom McCarthy","avatar":""},{"name":"Larry Andersen","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Turnaround"]', 1784690324226);
