INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-sinh-vo-thuong', 'Tam Sinh Vô Thương', 'Beloved Of A Lifetime', 'https://phimimg.com/upload/vod/20241006-1/393c58d28d7d6f5f826b166ebf160e15.jpg', 'https://phimimg.com/upload/vod/20241006-1/21b9540ba7ac077f39292572a58517be.jpg', '<p>Thương Ấu, nữ tử trẻ tuổi của tộc Thánh Linh vô tình cứu được Tư Uyên, Minh Vương của Minh tộc vào trước ngày đại hôn, lại không biết đêm tân hôn toàn tộc sẽ bị giết. Để hồi sinh tộc nhân, Thương Ấu giả làm yêu tinh hươu Mộng Li tới Minh tộc để lấy trái tim hổ phách của Minh Vương. Trong khoảng thời gian cùng chung sống, Thương Ấu đã phải lòng kẻ thù của mình, nhưng để hồi sinh tộc nhân, Thương Ấu vẫn lựa chọn moi tim Tư Uyên, cuối cùng lại phát hiện kẻ thù là người khác...</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"鍾麗麗","avatar":""},{"name":"Guan Yue","avatar":""},{"name":"吳海","avatar":""},{"name":"Xie An Ran","avatar":""},{"name":"尹蕊","avatar":""},{"name":"宋益凡","avatar":""},{"name":"Sui Shuyang","avatar":""},{"name":"焦雪睿","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["San Sheng Wu Shang","三生无殇"]', 1784690324226);
