INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-dep-nhat', 'Mùa Hè Đẹp Nhất', 'That Summer, Will Be Back', 'https://phimimg.com/upload/vod/20241020-1/45a2928c8419706e975285f63e1fc574.jpg', 'https://phimimg.com/upload/vod/20241020-1/020fc24c146098e6736c82181c15dfeb.jpg', '<p>Mùa hè năm ấy, chúng ta chẳng có gì ngoài tuổi trẻ, những ước mơ và... có nhau. Nhưng cũng chính mùa hè đó - mùa hè mang theo những điều chúng ta chưa hoàn thành... Bạn đã sẵn sàng gặp lại phiên bản của chính mình từ những ngày hè tươi đẹp của tuổi trẻ và tiếp tục viết nên câu chuyện còn dang dở chưa?</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Công Dương","avatar":""},{"name":"Đức Sơn","avatar":""},{"name":"Trần Nghĩa","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Minh Dự","avatar":""},{"name":"Nguyễn Tụ","avatar":""},{"name":"Thanh Nam","avatar":""},{"name":"Việt Anh","avatar":""},{"name":"Đỗ Khánh Vân","avatar":""},{"name":"Hồng Ánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Mùa Hè Đẹp Nhất"]', 1784690324226);
