INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-tau-coi-am', 'Đoàn Tàu Cõi Âm', 'The Train Of Death', 'https://phimimg.com/upload/vod/20241020-1/1e7b77fb59e747ec023d0cfaf7914b8b.jpg', 'https://phimimg.com/upload/vod/20241020-1/976e3524349b50edfadd090eb1e8ee85.jpg', '<p>Từng toa tàu biến mất bí ẩn mỗi khi băng qua đường hầm cùng hàng loạt viễn cảnh ghê rợn và đẫm máu liên tiếp ập đến khiến hành khách phải đối diện với ranh giới sinh tử trước mắt.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Hana Malasan","avatar":""},{"name":"Yama Carlos","avatar":""},{"name":"Putri Ayudya","avatar":""},{"name":"Kiki Narendra","avatar":""},{"name":"Sahira Anjani","avatar":""},{"name":"Zara Leola","avatar":""},{"name":"Fadly Faisal","avatar":""},{"name":"Emil Kusumo","avatar":""},{"name":"Agnes Naomi","avatar":""},{"name":"Ruth Marini","avatar":""},{"name":"Haydar Salishz","avatar":""},{"name":"Ilyas Bach","avatar":""},{"name":"Totos Rasiti","avatar":""},{"name":"Eduwart Manalu","avatar":""},{"name":"Adinda Rizkyana","avatar":""},{"name":"Mulyono","avatar":""},{"name":"M. N. Qomaruddin","avatar":""},{"name":"Patty Sandya","avatar":""},{"name":"May","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Train of Death","鬼咧號","Sangkara","Đoàn Tàu Cõi Âm","Train to Hell","血腥列车","Kereta Berdarah"]', 1784690324226);
