INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doan-tau-coi-am', 'Đoàn Tàu Cõi Âm', 'The Train Of Death', 'đoàn tàu cõi âm the train of death hana malasan yama carlos putri ayudya kiki narendra sahira anjani zara leola fadly faisal emil kusumo agnes naomi ruth marini haydar salishz ilyas bach totos rasiti eduwart manalu adinda rizkyana mulyono m. n. qomaruddin patty sandya may the train of death 鬼咧號 sangkara đoàn tàu cõi âm train to hell 血腥列车 kereta berdarah', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-thuong-me-tinh', 'Tái Thượng Mê Tình', 'Desert Whispers', 'https://phimimg.com/upload/vod/20241007-1/c9a13938281d5a9f0d99691f11a5eee6.jpg', 'https://phimimg.com/upload/vod/20241007-1/921fdb887742da66cc77cf25137324b4.jpg', '<p>Kể về câu chuyện của những đứa trẻ mồ côi Cố Đam và Hà Động Lượng vì thầy bị ông chủ Lưu Bá Sướng bắt cóc để giải cứu thầy của mình, họ buộc phải đánh cắp cổ vật Tây Hạ Diệu Âm Điểu, đội trưởng đội an ninh và Dư Tiêu Tiêu điều tra viên giải quyết bồi thường của Diệu Âm Điểu, cũng vô tình bị cuốn đến vụ việc này. Một số người hợp lực để khám phá câu chuyện về âm mưu săn tìm kho báu gây sốc của một băng nhóm đạo mộ quốc tế.</p>', 'Tập 20', 20, 'series', 'ongoing', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"李東學","avatar":""},{"name":"湯晶媚","avatar":""},{"name":"黑子","avatar":""},{"name":"Chen Mengqi","avatar":""},{"name":"Li Yun Ao","avatar":""},{"name":"Liu Wei-Hua","avatar":""},{"name":"Zhang Penghao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["大夏宝藏‎","Sai Shang Mi Qing","塞上迷情"]', 1784690324226);
