INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-xi-nghiep', 'Người Hùng Xí Nghiệp', 'Big Biz Duel', 'https://phimimg.com/upload/vod/20240929-1/005641bb93585afb3a0bfa357985481b.jpg', 'https://phimimg.com/upload/vod/20240929-1/fad3b675849fbc463d8163b27ef87a2e.jpg', '<p>Xí nghiệp chuyển phát nhanh Hậu cần Thời Đại phát triển thành công ty lên sàn với giá thị trường hơn 100 tỷ đô. Chủ tịch Triệu Khải (do Trần Hào đóng) lấy 20% cổ phần chia cho các nhân viên, khiến các cổ đông bất mãn. Triệu Khải luôn quan niệm “lấy con người làm gốc”, xí nghiệp quan trọng nhất chính là con người, con người chính là linh hồn của mỗi công ty.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2024, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Moses Chan","avatar":""},{"name":"Shaun Tam Chun-Yin","avatar":""},{"name":"Katy Kung","avatar":""},{"name":"Kelly Cheung","avatar":""},{"name":"David Chiang Da-Wei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["企业强人","Big biz duel","企業強人"]', 1784690324226);
