INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-giua-troi-ruc-ro', 'Đi Giữa Trời Rực Rỡ', 'Walking Under The Bright Sky', 'https://phimimg.com/upload/vod/20240821-1/e84c3eb9aa4f77c64295b07b12580bc5.jpg', 'https://phimimg.com/upload/vod/20240821-1/2dcb9779c1194b5968fde078bad44e1c.jpg', '<p>Lấy bối cảnh vùng cao, Đi giữa trời rực rỡ xoay quanh cuộc sống của cô gái trẻ người Dao tên Pu (Thu Hà Ceri). Pu mang trong mình nhiều hoài bão, ước mơ và là niềm tự hào của làng khi trúng tuyển đại học trên thành phố. Tuy vậy, Pu đối mặt với nhiều rắc rối, ngăn trở cô đi học, từ người cha &quot;nát rượu&quot; không thèm lo tiền học cho cô, đến sự xuất hiện của Chải (Nguyễn Long Vũ), chàng &quot;rich kid&quot; yêu Pu từ cái nhìn đầu tiên và muốn cưới cô.</p>', 'Hoàn Tất (58/58)', 58, 'series', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Thu Hà Ceri","avatar":""},{"name":"Long Vũ","avatar":""},{"name":"Hoàng Khánh Ly","avatar":""},{"name":"Vương Anh","avatar":""},{"name":"Võ Hoài Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324226);
