INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-khoe-tinh-yeu', 'Mánh Khóe Tình Yêu', 'Affair', 'https://phimimg.com/upload/vod/20240831-1/79e9665b31a8c0c332103330f8b8f191.jpg', 'https://phimimg.com/upload/vod/20240831-1/c67e47adc6564d189675f4b493e28ed8.jpg', '<p>Siang Plaing và Wan Wanviwah lớn lên trong cùng một gia đình nhưng có địa vị khác nhau. Plaing là con của chủ nhà, trong khi Wan làm việc trong nhà. Mặc dù họ chưa bao giờ nghĩ đến việc phải chia xa, nhưng một ngày nọ, Wan nói với Plaing rằng cô cuối cùng cũng phải kết hôn. Plaing lên kế hoạch tìm cho Wan một người đàn ông tốt để tránh cô đơn. Tuy nhiên, kế hoạch này lại khiến Plaing nhận ra tình cảm của mình dành cho Wan. Khi tình yêu của họ ngày càng sâu đậm, Plaing mất cả cha lẫn mẹ vì một vụ làm ăn thất bại và bỏ đi, chỉ để lại cho Wan một bức thư tình. Sau này, họ gặp lại nhau, nhưng Wan đã đính hôn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Saranphat Pedersen","avatar":""},{"name":"Punyapat Wangpongsathaporn","avatar":""},{"name":"Bonz Nadol Lamprasert","avatar":""},{"name":"Kidakarn Chatkaewmanee","avatar":""},{"name":"Pop Pataraphol Wanlopsiri","avatar":""},{"name":"Apasiri Nitibhon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324226);
