INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-ngon-tay-anh-cham-vao-hoi-am-cua-em', 'Khi Ngón Tay Anh Chạm Vào Hơi Ấm Của Em', 'The Time of Fever', 'https://phimimg.com/upload/vod/20241019-1/1ad22a805ddcfb4f029543297f29949c.jpg', 'https://phimimg.com/upload/vod/20241019-1/40be0fca7b420c4c5cb13e80bd0e26a2.jpg', '<p>Bộ phim này là phần ngoại truyện của bộ phim truyền hình &quot;Chuyện Tình Bất Ngờ&quot;, kể về những trải nghiệm học sinh đầy cảm xúc giữa Ho Tae và Dong Hee. Ho Tae và Dong Hee lớn lên cùng nhau như anh em. Sau khi cha qua đời, Ho Tae chuyển đến Seoul, vài năm sau vì lý do nào đó trở về Gangneung cùng mẹ. Hai người gặp lại sau thời gian xa cách, sống chung dưới một mái nhà và bắt đầu lại cuộc sống. Dong Hee, đối diện với Ho Tae - người bạn thân cũng là mối tình đầu của mình, dù cố gắng kiềm chế những cảm xúc đang trỗi dậy trong lòng nhưng lại bất lực. Ho Tae cũng bắt đầu nảy sinh những cảm xúc chưa từng có đối với Dong Hee sau bao năm xa cách. Mối quan hệ tế nhị giữa hai người âm thầm thay đổi sau một sự cố bất ngờ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Won Tae-min","avatar":""},{"name":"한도우","avatar":""},{"name":"Gongchan","avatar":""},{"name":"Lee Eun-ju","avatar":""},{"name":"Lee Yoo Jung","avatar":""},{"name":"Lee Woo Tae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["僕の指先に君の温度が触れるとき","내 손끝에 너의 온도가 닿을 때","當你的溫度觸及我的指尖","當我的指尖觸碰到你的溫度時","The Time Of Fever"]', 1784690324226);
