INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-ngon-tay-anh-cham-vao-hoi-am-cua-em', 'Khi Ngón Tay Anh Chạm Vào Hơi Ấm Của Em', 'The Time of Fever', 'khi ngón tay anh chạm vào hơi ấm của em the time of fever won tae-min 한도우 gongchan lee eun-ju lee yoo jung lee woo tae 僕の指先に君の温度が触れるとき 내 손끝에 너의 온도가 닿을 때 當你的溫度觸及我的指尖 當我的指尖觸碰到你的溫度時 the time of fever', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-la', 'Hạnh Phúc Là', 'Happiness Is', 'https://phimimg.com/upload/vod/20241019-1/45f9a6b856c205bea6e32bf7260216df.jpg', 'https://phimimg.com/upload/vod/20241019-1/51658e19b8d9db8712405b55bcfa8941.jpg', '<p>Princess chỉ muốn sự kiện bước sang tuổi bốn mươi trôi qua bình lặng. Nhưng khi người bạn thân tổ chức cho cô một bữa tiệc khó quên, toàn bộ thế giới của cô đảo lộn.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Renate Stuurman","avatar":""},{"name":"Gail Mabalane","avatar":""},{"name":"Richard Lukunku","avatar":""},{"name":"Sivuyile Ngesi","avatar":""},{"name":"OC Ukeje","avatar":""},{"name":"Anton David Jeftha","avatar":""},{"name":"Rosemary Zimu","avatar":""},{"name":"Phaphama Nqabeni","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Happiness Is"]', 1784690324226);
