INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cham-dut-su-im-lang-maria-soledad', 'Chấm Dứt Sự Im Lặng: Maria Soledad', 'Breaking the Silence: The Maria Soledad Case', 'https://phimimg.com/upload/vod/20241019-1/c14fb32852d89350da089f8071731a6f.jpg', 'https://phimimg.com/upload/vod/20241019-1/fc6cfc8c8ddcc25fd78479ee55f0c290.jpg', '<p>Vào những năm 90 ở Argentina, vụ sát hại một học sinh trung học đã gây ra làn sóng biểu tình rộng khắp. Được kể lại bởi những người thân yêu của cô, bộ phim tài liệu này cho thấy cuộc chiến vì công lý của họ.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Argentina', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["María Soledad: El fin del silencio"]', 1784690324226);
