INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-yeu-ufo', 'Người đàn ông yêu UFO', 'The Man Who Loved UFOs', 'https://phimimg.com/upload/vod/20241019-1/406d5906155a28ceee9ccf6d5913a50a.jpg', 'https://phimimg.com/upload/vod/20241019-1/ae2d8af258abebb2e579d076e76b5483.jpg', '<p>Cuối những năm 1980 ở Argentina, cuộc điều tra của phóng viên nọ về hoạt động của người ngoài hành tinh suýt bị dừng lại do thiếu bằng chứng. Thế rồi anh ta quyết định bịa đặt.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Argentina', 0, '[{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Sergio Prina","avatar":""},{"name":"Osmar Núñez","avatar":""},{"name":"Renata Lerman","avatar":""},{"name":"María Merlino","avatar":""},{"name":"Agustín Rittano","avatar":""},{"name":"Norman Briski","avatar":""},{"name":"Daniel Aráoz","avatar":""},{"name":"Mónica Ayos","avatar":""},{"name":"Paula Grinszpan","avatar":""},{"name":"Eva Bianco","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["El hombre que amaba los platos voladores"]', 1784690324226);
