INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-dan-ong-yeu-ufo', 'Người đàn ông yêu UFO', 'The Man Who Loved UFOs', 'người đàn ông yêu ufo the man who loved ufos leonardo sbaraglia sergio prina osmar núñez renata lerman maría merlino agustín rittano norman briski daniel aráoz mónica ayos paula grinszpan eva bianco el hombre que amaba los platos voladores', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-than-dac-biet', 'Thế Thân Đặc Biệt', 'Special Double', 'https://phimimg.com/upload/vod/20241019-1/6147d17ebd3c0cf30e37f412fb390ff7.jpg', 'https://phimimg.com/upload/vod/20241019-1/ed52178eacc54b770a29bd323245810c.jpg', '<p>Hàn Gia Kiệt là một diễn viên đóng thế trong ngành điện ảnh truyền hình, để hoàn thành giá trị mà mình tin tưởng, anh luôn kiên trì theo đuổi lý tưởng của mình. Bạn gái cùng ngành ở tầng lớp thấp là Đàm Ngữ Hinh vì những vấn đề thực tế trong cuộc sống đã rời khỏi đây để đến nơi khác ký hợp đồng làm streamer. Kể từ đó, hai người bắt đầu yêu xa. Tuy nhiên, sự trưởng thành của bạn gái khiến Hàn Gia Kiệt càng trở nên tự ti. Khi những người xung quanh lần lượt rời bỏ, chỉ còn lại Hàn Gia Kiệt một mình, áp lực cuộc sống và sự đả kích tinh thần khiến anh bắt đầu dao động. Anh đến quán rượu để uống cho quên đi nỗi sầu nhưng vô tình chứng kiến một tiểu thư của một băng nhóm là Âu Oánh Oánh bị ám sát. Hàn Gia Kiệt đã ra tay cứu giúp nhưng điều đó đã thay đổi con đường sau này của anh. Khi cuộc sống càng trở nên bế tắc, Hàn Gia Kiệt quyết định theo chân gia đình Âu Oánh Oánh làm những việc trái với lương tâm và vi phạm pháp luật. Sau một thời gian, Hàn Gia Kiệt thấy được cảnh ngộ bi thảm của những nạn nhân, lòng tốt ẩn sâu trong anh được đánh thức. Anh chủ động liên hệ với cảnh sát để đầu thú. Nhờ sự phối hợp tác anh, cảnh sát đã thành công bắt giữ băng nhóm họ Âu.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuming Du","avatar":""},{"name":"Kou Zhanwen","avatar":""},{"name":"Wang Bin Ming","avatar":""},{"name":"向涛","avatar":""},{"name":"Zhuang Xiaolong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["特殊替身"]', 1784690324226);
