INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chac-chan-phai-la-co-ay', 'Chắc Chắn Phải Là Cô Ấy', 'Fatal Allure', 'https://phimimg.com/upload/vod/20241008-1/6b817464a931ed9fcbfa76819d28e3fc.jpg', 'https://phimimg.com/upload/vod/20241008-1/4fd8fbca120164f4b4b191cd0317712a.jpg', '<p>Cô gái nhút nhát Kỷ Thiền đổi mặt trùng sinh, lấy chính mình làm mồi nhử, đánh đổi trái tim chân thành để hóa thân thành nữ thần báo thù, mang theo sự quyến rũ chết người từng bước tiếp cận Tống Tư Phác, một anh chàng kỷ luật, cứng rắn và lạnh lùng. Không ngờ, sự xuất hiện của Kỷ Thiền khiến &quot;nghi phạm&quot; thâm hiểm như núi băng phải bùng nổ và mang quyết tâm chinh phục cô. Anh cũng chuyển từ thái độ thờ ơ sang bảo vệ cô hết lòng. Dù Kỷ Thiền ban đầu cũng có nhiều toan tính khi nhắm đến anh, nhưng dần dần anh đã trở thành tình yêu đích thực trong cô khiến cô không thể kìm chế. Sự thử lòng tán tỉnh qua lại giữa những người trưởng thành, các mối quan hệ tình cảm phức tạp, liệu đây sẽ là hành trình tìm kiếm sự thật hay một trò chơi về tình yêu, cuộc đối đầu gay gắt giữa hai con người mạnh mẽ đang chực chờ bùng nổ...</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"洪瀟","avatar":""},{"name":"Dai Gaozheng","avatar":""},{"name":"唐思佳","avatar":""},{"name":"Fan Xiaodong","avatar":""},{"name":"张瑞恩","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["She Must","谋她之年","非她不可"]', 1784690324226);
