INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-chien-thang', 'Vũ Điệu Chiến Thắng', 'Victory', 'https://phimimg.com/upload/vod/20241018-1/3733687f3cf00047b3908ffb0682e85c.jpg', 'https://phimimg.com/upload/vod/20241018-1/4e45cfee4fd242e2ae8a50bcf78884a1.jpg', '<p>Vào năm 1999 tại một ngôi làng nhỏ ở Geoje, Millennium Girls - đội cổ vũ được lập ra bởi Pil Sun (Hyeri) và Mi Na (Park Se Wan), hai nữ sinh “cá biệt” với niềm đam mê vũ đạo ngấm vào máu. Là tập hợp của 9 cô gái với những câu chuyện khác nhau, đội cổ vũ thời đại Y2K tham gia vào các trận bóng đá ở trường, nhảy múa ở chợ, mang niềm vui tới viện dưỡng lão, cổ vũ cho những người cha trong cuộc biểu tình giành lại công bằng cho bản thân và gia đình. Họ đã cùng nhau trưởng thành với thanh xuân thật rực rỡ.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"이혜리","avatar":""},{"name":"박세완","avatar":""},{"name":"이정하","avatar":""},{"name":"조아람","avatar":""},{"name":"현봉식","avatar":""},{"name":"최지수","avatar":""},{"name":"이찬형","avatar":""},{"name":"백하이","avatar":""},{"name":"권유나","avatar":""},{"name":"Yeom Ji-young","avatar":""},{"name":"Lee Han-joo","avatar":""},{"name":"박효은","avatar":""},{"name":"주진모","avatar":""},{"name":"Son Byeong-uk","avatar":""},{"name":"이시훈","avatar":""},{"name":"Seo Soo-hee","avatar":""},{"name":"이미도","avatar":""},{"name":"지이수","avatar":""},{"name":"공훈","avatar":""},{"name":"한종훈","avatar":""},{"name":"Cha Joo-wan","avatar":""},{"name":"정다정","avatar":""},{"name":"조강혁","avatar":""},{"name":"미연","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["FIGHTING！女孩們","胜利","빅토리"]', 1784690324226);
