INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-nhan-ai', 'Trái Tim Nhân Ái', 'Cabrini', 'https://phimimg.com/upload/vod/20241017-1/5747fe5c869eb6ee24d36111a683f60b.jpg', 'https://phimimg.com/upload/vod/20241017-1/585779ac718d46fa0332c48f91259d93.jpg', '<p>Sau khi chứng kiến bệnh tật và nghèo đói ở khu ổ chuột ở New York, Francesca Cabrini, người nhập cư Ý, bắt tay vào hành trình táo bạo thuyết phục thị trưởng thù địch cung cấp nhà ở và chăm sóc sức khỏe cho hàng trăm trẻ mồ côi.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Cristiana Dell''Anna","avatar":""},{"name":"David Morse","avatar":""},{"name":"Giancarlo Giannini","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Romana Maggiora Vergano","avatar":""},{"name":"Federico Ielapi","avatar":""},{"name":"Virginia Bocelli","avatar":""},{"name":"Rolando Villazón","avatar":""},{"name":"Jeremy Bobb","avatar":""},{"name":"Federico Castelluccio","avatar":""},{"name":"Patch Darragh","avatar":""},{"name":"Seán Cullen","avatar":""},{"name":"Andrew Polk","avatar":""},{"name":"Allen Lewis Rickman","avatar":""},{"name":"Giampi","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Una mujer italiana","Cabrini"]', 1784690324226);
