INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-phong-ngam', 'Mạc Phong Ngâm', 'Love In The Desert', 'https://phimimg.com/upload/vod/20240929-1/1b35b5ea95fc5d0331bd8dfcae2f2e3c.jpg', 'https://phimimg.com/upload/vod/20240929-1/9df22e93fbf4453b043e2d2302dd300c.jpg', '<p>Mạc Phong Ngâm là hành trình trưởng thành của Hoàng Bắc Sương - đệ nhất mỹ nữ Đại Mạc. Là công chúa của một bộ tộc đang suy tàn, gánh vác trên vai trọng trách bảo vệ người dân, Bắc Sương buộc phải đến thành Vân Phái hòa thân. Trên đường đi, nàng cùng lúc vướng vào lưới tình với ba người đàn ông quyền lực nhất Đại Mạc. Không cam chịu phó mặc cho số phận trêu đùa, Bắc Sương dựa vào mưu trí và lòng dũng cảm để tự tìm cho mình một chỗ đứng vững chắc giữa chốn sa mạc bao la.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cáp Ni Khắc Tư","avatar":""},{"name":"Phương Dật Luân","avatar":""},{"name":"Cao Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["大漠情殇","漠风吟"]', 1784690324226);
