INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cuop-tao-ton', 'Vụ Cướp Táo Tợn', 'Justice', 'https://phimimg.com/upload/vod/20241016-1/848179f8e01705bdae5d4fa29ea02995.jpg', 'https://phimimg.com/upload/vod/20241016-1/612a92ac19e91a16b5dca57970634b7f.jpg', '<p>Một công tố viên nhờ một sĩ quan cảnh sát đã giải ngũ giúp đỡ, cho anh ta cơ hội giành lại cuộc sống cũ bằng cách phá giải một vụ cướp ngân hàng.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Ba Lan', 0, '[{"name":"Olaf Lubaszenko","avatar":""},{"name":"Jędrzej Hycnar","avatar":""},{"name":"Wiktoria Gorodeckaja","avatar":""},{"name":"Magdalena Boczarska","avatar":""},{"name":"Łukasz Szczepanowski","avatar":""},{"name":"Stanisław Linowski","avatar":""},{"name":"Nel Kaczmarek","avatar":""},{"name":"Dariusz Toczek","avatar":""},{"name":"Mirosław Haniszewski","avatar":""},{"name":"Jowita Budnik","avatar":""},{"name":"Karol Bernacki","avatar":""},{"name":"Marcin Czarnik","avatar":""},{"name":"Krzysztof Dracz","avatar":""},{"name":"Szymon Kukla","avatar":""},{"name":"Jakub","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Assault","Justice","ล่าความยุติธรรม","El Atraco","Napad Der Ueberfall","Napad - Der Ueberfall","عدالت","Napad"]', 1784690324226);
