INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-cuop-tao-ton', 'Vụ Cướp Táo Tợn', 'Justice', 'vụ cướp táo tợn justice olaf lubaszenko jędrzej hycnar wiktoria gorodeckaja magdalena boczarska łukasz szczepanowski stanisław linowski nel kaczmarek dariusz toczek mirosław haniszewski jowita budnik karol bernacki marcin czarnik krzysztof dracz szymon kukla jakub the assault justice ล่าความยุติธรรม el atraco napad der ueberfall napad - der ueberfall عدالت napad', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-mang', 'Liều Mạng', 'Go For Broke', 'https://phimimg.com/upload/vod/20241016-1/d8b24ac23b8cdf8297f0da76efe761e4.jpg', 'https://phimimg.com/upload/vod/20241016-1/745a9f044b44b7c2e22851e8319df2ef.jpg', '<p>Trong một thế giới nơi trật tự bị phá vỡ, bóng tối ngự trị, các thế lực đang hoạt động và đầy rẫy những âm mưu. Con trai của một thủ lĩnh tập đoàn ma túy khét tiếng chiến đấu để giành lấy mạng sống và dần dần nổi lên. Đội trưởng đội chống ma túy là một kẻ giết người độc ác và tàn nhẫn. Những tên côn đồ hung bạo lang thang trong bóng tối can thiệp để gây rối và thề sẽ giành lấy lợi ích. Tình hình ngày càng trở nên khó hiểu hơn khi cả đội phát điên mà không nhận ra rằng đằng sau hậu trường đang có một âm mưu trả thù khổng lồ. Dưới bóng tối của những giao dịch tiền bạc và quyền lực, đấu tranh vũ trang phe phái, nội gián vàng đen lần lượt lộ diện. Trò chơi sinh tử được chờ đợi từ lâu đã bắt đầu......</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"張家輝","avatar":""},{"name":"阮經天","avatar":""},{"name":"張榕容","avatar":""},{"name":"Marc Ma","avatar":""},{"name":"线雨轩","avatar":""},{"name":"Jiang Yixuan","avatar":""},{"name":"陳國坤","avatar":""},{"name":"张俪","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Narilya Gulmongkolpech","avatar":""},{"name":"高捷","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Go for Broke","Go For Broke","Rebirth","重生"]', 1784690324226);
