INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-than-quen-nua-xa-la', 'Nửa Thân Quen Nửa Xa Lạ', 'In Between', 'https://phimimg.com/upload/vod/20240925-1/3629935c8c0c996dea179088c75f8942.jpg', 'https://phimimg.com/upload/vod/20240925-1/8d7a5682b123c5d74320cb7e73cbd257.jpg', '<p>Sau khi chia tay mối tình đầu, Hà Tri Nam tưởng chừng như đã tìm thấy hạnh phúc mới bên Cù Nhất Bằng. Thế nhưng, những bí ẩn đằng sau mối quan hệ này đã khiến cô hoang mang. May mắn thay, cô đã có những người bạn luôn ở bên cạnh, giúp cô vượt qua khó khăn và tìm thấy tình yêu đích thực.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"田曦薇","avatar":""},{"name":"辛雲來","avatar":""},{"name":"张哲华","avatar":""},{"name":"Zeng Mengxue","avatar":""},{"name":"袁文康","avatar":""},{"name":"侯雯元","avatar":""},{"name":"董潔","avatar":""},{"name":"Edward Chen","avatar":""},{"name":"周雨彤","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["半熟男女","In Between"]', 1784690324226);
