INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-nap', 'Ẩn Nấp', 'Take Cover', 'https://phimimg.com/upload/vod/20241015-1/1191239acb9c4b379ee942bac28065c8.jpg', 'https://phimimg.com/upload/vod/20241015-1/c5960f55ae1c46f7f1a12e378473ba16.jpg', '<p>Take Cover 2024 kể về Jack Parr (Scott Adkins), một cựu lính bắn tỉa đang ẩn náu sau khi thực hiện một nhiệm vụ ám sát thất bại. Anh ta bị mắc kẹt trong một căn hộ áp mái sang trọng toàn kính bởi một sát thủ bí ẩn. Không có chỗ ẩn nấp và không có sự hỗ trợ, Jack phải sử dụng tất cả kỹ năng và kinh nghiệm của mình để sống sót và tìm cách thoát khỏi tòa nhà trước khi kẻ thù tiếp cận.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Alice Eve","avatar":""},{"name":"Jack Parr","avatar":""},{"name":"Billy Clements","avatar":""},{"name":"Mădălina Bellariu Ion","avatar":""},{"name":"Renars Latkovskis","avatar":""},{"name":"Nik Coleman","avatar":""},{"name":"Alba De Torrebruna","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Take Cover","Sin refugio","Cúbrete"]', 1784690324226);
