INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ngu-2-hai-dao-ngu-quai', 'Đại Ngư 2: Hải Đảo Ngư Quái', 'Giant Fish 2', 'https://phimimg.com/upload/vod/20241015-1/370cb9e8e4c487ad76ebf5b3febb568e.jpg', 'https://phimimg.com/upload/vod/20241015-1/f860e8054aaedc5fbb5a3f8b0e6f4a15.jpg', '<p>Kể câu chuyện về một người chồng vì cứu vợ cũ mà vượt qua muôn vàn hiểm nguy, chiến đấu với con cá lớn bí ẩn và kẻ chủ mưu đứng sau tội ác. Bên bờ hồ có một khu nghỉ dưỡng dưỡng sinh cách biệt với thế giới bên ngoài, nhà sinh vật học Trương Trình đưa con gái đến đây để tìm vợ cũ Nghiêm Đồng, nhìn thấy cô ấy vậy mà cải lão hoàn đồng. Trương Trình biết được cô ấy đã sử dụng sản phẩm làm đẹp bí mật, và tại khách sạn này thường xuyên xảy ra những sự kiện kỳ lạ khi du khách biến mất một cách bí ẩn.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"王森","avatar":""},{"name":"Zhang Wen","avatar":""},{"name":"王一铭","avatar":""},{"name":"Pan Yan-Fei","avatar":""},{"name":"赵斌","avatar":""},{"name":"房營","avatar":""},{"name":"Wang Kai Jie","avatar":""},{"name":"田东霖","avatar":""},{"name":"李颖芝","avatar":""},{"name":"Bu Ziying","avatar":""},{"name":"刘悠然","avatar":""},{"name":"俞清蕾","avatar":""},{"name":"毛一飞","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["大鱼2狂暴大鱼","大鱼2海岛鱼怪"]', 1784690324226);
