INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-nhan-long-cuu-long-bich', 'Truyền Thuyết Nhân Long: Cửu Long Bích', 'The Nine Dragon Wall', 'https://phimimg.com/upload/vod/20241014-1/4de0d93ceba1e09967e6b0fba319e0cc.jpg', 'https://phimimg.com/upload/vod/20241014-1/ddab0ef518117ae4998b378652061488.jpg', '<p>Từ xưa, dòng họ nuôi rồng luôn sống chết, chiến đấu kề vai sát cánh cùng rồng. Nhưng đến đời của Đổng Văn Quảng lại bất ngờ trở mặt thành thù với rồng, phong ấn chín vị Long vương vào Cửu Long Bích. Con trai ông là Đổng Nhất Minh để được cha công nhận, đã bất chấp sự ngăn cản của Đổng Văn Quảng, bí mật điều tra tung tích của Long châu. Tuy nhiên, anh phát hiện ra mọi người chỉ là quân cờ trên bàn cờ của kẻ đứng sau, và sự thật phía sau vẫn chưa phải là sự thật cuối cùng.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yu Shaoqun","avatar":""},{"name":"赵芮玉","avatar":""},{"name":"Jun Guo","avatar":""},{"name":"Shen Baoping","avatar":""},{"name":"Wang Yuman","avatar":""},{"name":"Ding Huiyu","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["인룡전설: 구룡벽","人龙传说之九龙壁"]', 1784690324226);
