INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-mo-that-lac', 'Lăng Mộ Thất Lạc', 'The Lost Mausoleum', 'https://phimimg.com/upload/vod/20241014-1/10a7fbcd5e10ac3fbd5e0ad39f21410c.jpg', 'https://phimimg.com/upload/vod/20241014-1/84e290dd7dd7c9f6e8cd39cbfceed6bc.jpg', '<p>Dân gian lưu truyền rằng chỉ cần có được cuốn Ngự Giao Lục của Đại tư vu nước Nam Nguyệt là có thể nuôi rắn thành giao long, thuần phục giao long hóa thành rồng. Trong thời kỳ Dân Quốc, những kẻ trộm mộ từ nước ngoài ồ ạt đổ vào đất nước Hoa Hạ, cướp đoạt quốc bảo và phá hoại di tích. Một nhóm trong số họ phát hiện ra địa cung cất giấu cuốn Ngự Giao Lục và sau đó quyết định nhanh chóng tìm ra cuốn sách này rồi giấu đi.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"An Yi Xin","avatar":""},{"name":"Na Mao","avatar":""},{"name":"王玺","avatar":""},{"name":"段霄震","avatar":""},{"name":"韩东","avatar":""},{"name":"Ge Si","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["龙骨遗冢"]', 1784690324226);
