INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tuyet-va-quai-thu', 'Bão Tuyết Và Quái Thú', 'Cold Meat', 'https://phimimg.com/upload/vod/20241013-1/4b9cc2f7c639723be655ac0993d73289.jpg', 'https://phimimg.com/upload/vod/20241013-1/e02fe10694ecb13adbc35ed8d5cce6be.jpg', '<p>Một tài xế cứu cô hầu bàn khỏi người yêu cũ bạo hành, nhưng trên đường đi, anh gặp tai nạn giữa bão tuyết và bị mắc kẹt trong một khe núi. Khi bị thương và đối mặt với cái lạnh tàn khốc, anh phát hiện ra một con thú bí ẩn đang rình rập mình. Cuộc đấu tranh sinh tồn căng thẳng bắt đầu khi anh phải chiến đấu với cả thiên nhiên và con quái vật</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Allen Leech","avatar":""},{"name":"Nina Bergman","avatar":""},{"name":"Yan Tual","avatar":""},{"name":"James Barton-Steel","avatar":""},{"name":"Riley Banzer","avatar":""},{"name":"Sydney Hendricks","avatar":""},{"name":"William Kuklis","avatar":""},{"name":"Gil Botelho","avatar":""},{"name":"Kat Fullerton","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Cold Meat"]', 1784690324226);
