INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tran-bong-nay-cho-anh', 'Trận Bóng Này Cho Anh', 'The Rebound', 'trận bóng này cho anh the rebound นิชคุณ ขจรบริรักษ์ ปิง กฤตนัน อัญชนานันท์ krittanai arsalprakit ธนัตถ์ศรันย์ ซำทองไหล ชินวุฒ อินทรคูสิน เอิร์ธ นันทวัฒน์ ไพบูลย์ภัทรธน non ratchanon kanpiang thasorn klinnium joke chaloemdet thammawut bom panupong janchai perth napat rueangchais ', '');
