INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pachinko-phan-2', 'Pachinko (Phần 2)', 'Pachinko (Season 2)', 'https://phimimg.com/upload/vod/20240820-1/92fc6c8db3e5b6b08e9bf209c0873d91.jpg', 'https://phimimg.com/upload/vod/20240820-1/33aacf53e7daff8132043c8e98957368.jpg', '<p>Dựa trên cuốn tiểu thuyết trong danh sách bán chạy của New York Times, bộ phim này thuật lại hy vọng và giấc mơ của một gia đình nhập cư Hàn Quốc trải dài bốn thế hệ sau khi rời quê hương trong một hành trình can trường để sinh tồn và phát triển.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"윤여정","avatar":""},{"name":"Soji Arai","avatar":""},{"name":"진 하","avatar":""},{"name":"정은채","avatar":""},{"name":"김민하","avatar":""},{"name":"김성규","avatar":""},{"name":"이민호","avatar":""},{"name":"노상현","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324226);
