INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luyen-tiec-nhung-vi-sao', 'Luyến Tiếc Những Vì Sao', 'You Are My Lover Friend', 'https://phimimg.com/upload/vod/20240924-1/ba09ddeeaed83d8dd364886bc05d551b.jpg', 'https://phimimg.com/upload/vod/20240924-1/37b334513da61d6437462109a24bee22.jpg', '<p>Ba năm cấp ba đã tạo nên &quot;tình anh em&quot; sâu đậm giữa Tưởng Thời Diên và Đường Dạng. Hiện tại, Đường Dạng được điều về làm phó trưởng phòng Thẩm định tín dụng tại ngân hàng Hối Thương chi nhánh Dung Thành, nhưng cô luôn bị cấp trên là Cam Nhất Minh chèn ép. Dù vậy cô vẫn chống lại ý kiến đám đông để duyệt khoản vay cho hộ kinh doanh nhỏ &quot;Đồ kho Chí Lan&quot;. Trong khi đó, Tưởng Thời Diên, người sáng lập ra &quot;Món ngon Nhất Hưu&quot; đã âm thầm giúp đỡ Đường Dạng thông qua sức ảnh hưởng của mình trong lĩnh vực truyền thông ẩm thực. Khi cấp trên Cam Nhất Minh giả vờ say rượu để quấy rối Đường Dạng, Tưởng Thời Diên đã đánh anh ta. Hai người bắt đầu nghi ngờ tình cảm giữa họ đã vượt qua ranh giới &quot;anh em tốt&quot;. Trong lúc bối rối mập mờ, Tưởng Thời Diên bị viêm ruột thừa phải nhập viện, Đường Dạng đã chăm sóc anh tận tình, cuối cùng hai người chính thức yêu nhau. Tuy nhiên mọi người xung quanh dường như không tin rằng cặp bạn thân lâu năm này thật sự đang yêu nhau, gây ra nhiều tình huống hiểu nhầm.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"張新成","avatar":""},{"name":"王玉雯","avatar":""},{"name":"吴俊霆","avatar":""},{"name":"羅秋韻","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我拿你当兄弟你却","She Bu De S01","تو دوست عزیز منی","تو رفیق دوست‌داشتنی منی","捨不得星星","You Are My Lover Friend","舍不得星星"]', 1784690324226);
