INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-dem-kinh-hoang', 'Sáu Đêm Kinh Hoàng', 'Tarot', 'https://phimimg.com/upload/vod/20241011-1/092f3836a6b48952bfdd3c0af764c15c.jpg', 'https://phimimg.com/upload/vod/20241011-1/9705eed5f26c5e194fdc828cc34113db.jpg', '<p>Người mẹ đơn thân, anh thợ làm tóc, những số phận khác nhau lại vô tình vướng vào hàng loạt sự kiện bí ẩn. Cũng từ đây mọi thứ bị đảo lộn và vượt khỏi tầm kiểm soát. Rốt cuộc thế lực nào đứng đằng sau và điều khiển cuộc chơi vẫn là câu hỏi bị bỏ ngỏ và chờ đợi khán giả khám phá.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Yeo Jeong","avatar":""},{"name":"Kim Sung Tae","avatar":""},{"name":"Kim Jin Young","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["타로: 일곱 장의 이야기","Tarot: A Story of Seven Chapters","Таро","Tarot: Seven Stories","Sáu Đêm Kinh Hoàng"]', 1784690324226);
