INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-cua-anh-chi-em-toi', 'Chuyện Tình Của Anh Chị Em Tôi', 'My Sibling''s Romance', 'https://phimimg.com/upload/vod/20241011-1/d24ac9d254c945c78c2ce5384c724205.jpg', 'https://phimimg.com/upload/vod/20241011-1/b33e9924fae8cdfa4b1a59a8c7d13791.jpg', '<p>Nó định nghĩa lại các chương trình hẹn hò với một bước ngoặt gia đình! Cùng với bốn cặp anh chị em ruột, họ tập hợp trong một ngôi nhà chung để giúp đỡ nhau tìm kiếm đối tác lãng mạn. Nó giới thiệu một khái niệm mới mẻ nơi các anh chị em bắt đầu hành trình tìm kiếm tình yêu, không chỉ cho bản thân mình mà còn cho nhau, tất cả dưới sự chứng kiến của các anh chị em của họ.</p>', 'Hoàn Tất (16/16)', 16, 'tvshows', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"한혜진","avatar":""},{"name":"코드 쿤스트","avatar":""},{"name":"미연","avatar":""},{"name":"뱀뱀","avatar":""},{"name":"조나단 토나 욤비","avatar":""},{"name":"파트리샤 토나 욤비","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["MSR","Love Siblings","Chuyện Tình Của Anh Chị Em Tôi","연애남매"]', 1784690324226);
