INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-nao-do', 'Tình Yêu Nào Đó', 'That Kind of Love', 'https://phimimg.com/upload/vod/20241011-1/fa9520e2f6fbb0ab344de3b11b8d764f.jpg', 'https://phimimg.com/upload/vod/20241011-1/1f224eca195f5bdae8eb7871ea1e9689.jpg', '<p>Không tin vào những kỹ năng của cô, một người đàn ông hoài nghi thách thức chuyên gia tư vấn hẹn hò nọ làm mai cho anh. Nhưng tình yêu đích thực có thể ở gần hơn anh nghĩ.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"David Licauco","avatar":""},{"name":"Barbie Forteza","avatar":""},{"name":"Al Tantay","avatar":""},{"name":"Arlene Muhlach","avatar":""},{"name":"Kaila Estrada","avatar":""},{"name":"Divine Aucina","avatar":""},{"name":"Ivan Carapiet","avatar":""},{"name":"Jef Gaitan","avatar":""},{"name":"Ady Cotoco","avatar":""},{"name":"Jong Cuenco","avatar":""},{"name":"Marina Benipayo","avatar":""},{"name":"Trina Candaza","avatar":""},{"name":"Karen Joy Toyoshima","avatar":""},{"name":"TJ Valderrama","avatar":""},{"name":"Brian Gocheco","avatar":""},{"name":"Gaye Piccio","avatar":""},{"name":"Justin Uy","avatar":""},{"name":"Carol Re","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ganyang Klase ng Pag-ibig"]', 1784690324226);
