INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-dna', 'Người Tình DNA', 'DNA Lover', 'https://phimimg.com/upload/vod/20240901-1/3eee156d7bea1a7ab70a259210a7df65.jpg', 'https://phimimg.com/upload/vod/20240901-1/a499c225f2166da0d58cfd62118f350d.jpg', '<p>Người Tình DNA - DNA Lover kể về So Jin, một nhà nghiên cứu di truyền học yêu thích DNA, quyết định kết thúc mối quan hệ với bạn trai lăng nhăng và bắt đầu hành trình tìm kiếm một đối tác tương thích về mặt di truyền để có một mối quan hệ hạnh phúc. Trong hai người đàn ông mà So Jin gặp, bác sĩ sản phụ khoa Yeon Woo và lính cứu hỏa Kang Hoon, ai sẽ là người phù hợp hoàn hảo với cô? Một câu chuyện hấp dẫn xen lẫn với các kiến thức liên quan đến di truyền học! Câu chuyện này khắc họa những đấu tranh, tình yêu và cuộc sống hàng ngày của những người bạn trẻ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"정인선","avatar":""},{"name":"최시원","avatar":""},{"name":"이태환","avatar":""},{"name":"정유진","avatar":""},{"name":"이시훈","avatar":""},{"name":"이수빈","avatar":""},{"name":"방은정","avatar":""},{"name":"이철우","avatar":""},{"name":"서지영","avatar":""},{"name":"정이랑","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324226);
