INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-anh-trong-mo', 'Gặp Anh Trong Mơ', 'I Saw You in My Dream', 'https://phimimg.com/upload/vod/20240728-1/79c2e1ce555f40d78d42cc76d38added.jpg', 'https://phimimg.com/upload/vod/20240728-1/121dcf4b0e689df4cf83701f11d8ea55.jpg', '<p>Yu là anh trai nhà bên của Ai, cả hai cùng lớn lên từ nhỏ. Nhưng bỗng không biết từ khi nào, Yu bắt đầu thường xuyên xuất hiện trong giấc mơ của Ai, và còn là kiểu giấc mơ rất lãng mạn. Nhưng trên thực tế, những lúc hai người gặp nhau thường cãi nhau ỏm tỏi. Vậy làm sao Yu lại xuất hiện trong giấc mơ lãng mạn của Ai? Vả lại dường như giấc mơ sắp trở thành hiện thực... Điều này khiến Ai hoài nghi chính mình.

Hãy cùng xem &quot;Gặp Anh Trong Mơ&quot; để giải mã bí ẩn về giấc mơ của Ai!

Lý do xếp hạng độ tuổi: Đề tài đồng tính</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Putter Phubase Pratumrat","avatar":""},{"name":"อิงครัต ดำรงค์ศักดิ์กุล","avatar":""},{"name":"Patchara Silapasoonthorn","avatar":""},{"name":"Game Orarig Tanoi","avatar":""},{"name":"JJ Radchapon Phornpinit","avatar":""},{"name":"Steve Salisa Jaroenkijnumchok","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324226);
