INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ay-xam-chiem-the-gioi-cua-toi', 'Anh Ấy Xâm Chiếm Thế Giới Của Tôi', 'Monster Next Door', 'https://phimimg.com/upload/vod/20241007-1/4732aee0d0b666b3d1fcecd6d1f688b3.jpg', 'https://phimimg.com/upload/vod/20241007-1/802ea50f39fb134cbf6f80c1bf10cde5.jpg', '<p>Diew là một người có tính cách khá hướng nội, thường thích ở một mình trong phòng, tự tìm niềm vui với chú rùa cưng của mình. Nhưng cuộc sống yên bình ấy nhanh chóng bị phá vỡ bởi God, một chàng trai mới chuyển đến phòng bên cạnh. God là người có tính cách cởi mở, hướng ngoại, có rất nhiều bạn bè, thường xuyên cùng bạn bè tiệc tùng náo nhiệt đến tận khuya ở phòng bên. Thế giới yên tĩnh của Diew bị quái vật nhỏ này phá vỡ không thương tiếc! Giờ phải làm sao đây?! Làm sao giữa hai người có tính cách trái ngược nhau đến vậy có thể nảy sinh một tình yêu hoàn hảo đây?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thanakorn Kuljarassombat","avatar":""},{"name":"Park Anantadej Sodsee","avatar":""},{"name":"Thanakorn Sangwan","avatar":""},{"name":"Thanawat Sutthijaroen","avatar":""},{"name":"Kade Tanapon Hathaidachadusadee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["隔壁哥斯拉","入侵我世界的怪兽先生","他闯进我的世界","隔壁的怪物","邻家怪兽","隔壁的怪兽","怪兽先生和乌龟男孩","MONSTER NEXT DOOR","Phi Khao Buk Lok Khong Phom","พี่เขาบุกโลกของผม"]', 1784690324226);
