INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ren-luyen-y-chi', 'Rèn Luyện Ý Chí', 'The Forge', 'https://phimimg.com/upload/vod/20241009-1/39467a94004f5606d9d3bbe21807204b.jpg', 'https://phimimg.com/upload/vod/20241009-1/a60bdf8f6a7ab4a528988ae186d38ea2.jpg', '<p>Sau khi tốt nghiệp trung học mà không có kế hoạch cụ thể cho tương lai, Isaiah nhận được sự động viên để bắt đầu đưa ra những quyết định tốt hơn trong cuộc sống. Bộ phim kể về hành trình của Isaiah khi anh vượt qua sự mơ hồ và tìm kiếm hướng đi mới cho bản thân.</p>', 'Full', 1, 'single', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Aspen Kennedy Wilson","avatar":""},{"name":"Priscilla C. Shirer","avatar":""},{"name":"Cameron Arnett","avatar":""},{"name":"Karen Abercrombie","avatar":""},{"name":"T.C. Stallings","avatar":""},{"name":"B.J. Arnett","avatar":""},{"name":"Ken Bevel","avatar":""},{"name":"Benjamin Charles Watson","avatar":""},{"name":"Jonathan Evans","avatar":""},{"name":"Jerry Shirer","avatar":""},{"name":"Tommy Woodard","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Kendrick Brothers 2024 Film","La Forja","The Forge"]', 1784690324226);
