INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-kim-nhon', 'Chiếc Kim Nhọn', 'Acupuncture Needle', 'https://phimimg.com/upload/vod/20241009-1/44aebc03ea21135a404b7b3c843d3572.jpg', 'https://phimimg.com/upload/vod/20241009-1/2a428952d9e689c8073463df4a8a3576.jpg', '<p>Tại một nhà nghỉ ở Giang Thành, người ta phát hiện thi thể của một phụ nữ. Qua quá trình điều tra, cảnh sát xác nhận nạn nhân là Đồng Thoại, bác sĩ thực tập tại Bệnh viện tỉnh. Trong quá trình phá án, Đội trưởng đội Trọng án Từ Khải phát hiện cha mẹ của Lục Đình cũng là cảnh sát có liên quan đến vụ án. Tuy nhiên, khi một quá khứ đau buồn dần lộ ra sau vụ án mạng, Từ Khải nhận ra rằng kẻ chủ mưu thực sự lại là người khác.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tang Xu","avatar":""},{"name":"He Shaohong","avatar":""},{"name":"Tiffany Chu","avatar":""},{"name":"Zhao Yi Xiao","avatar":""},{"name":"Ding Qi","avatar":""},{"name":"Zhu Jintong","avatar":""},{"name":"Xu Shaoze","avatar":""},{"name":"Zhang Yining","avatar":""},{"name":"刘昱辰","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["芒针"]', 1784690324226);
