INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-hai-me-quat', 'Cực Hải Mê Quật', 'The Lost Cave of the Arctic Sea', 'https://phimimg.com/upload/vod/20241009-1/b98bed0f5b6f4fddd47759b91fa80f09.jpg', 'https://phimimg.com/upload/vod/20241009-1/91195e1f529086f7a17cfa77617517ed.jpg', '<p>Trên một hòn đảo nào đó, người ta phát hiện tàn tích nghi ngờ là của nước Nam Việt, tương truyền rằng có thể là nơi chôn giấu kho báu của Thừa tướng Lữ Gia nước Nam Việt. Khi cơn bão sắp ập đến, chuyên gia sinh tồn ngoài trời có thính giác phi thường, Ngô Ngân, nhận lời mời từ nhà sử học Nam Việt, Cố Lâm, để giúp đội khảo cổ khẩn trương bảo tồn các di tích. Tuy nhiên, anh tình cờ phát hiện một hang động có niên đại khác xa với thời của Lữ Gia, từ đó bước vào cuộc hành trình phiêu lưu. Một bí mật lịch sử nghìn năm sắp sửa được hé lộ.</p>', 'Full', 1, 'single', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"肖博","avatar":""},{"name":"Yu Xinyan","avatar":""},{"name":"淳于珊珊","avatar":""},{"name":"王亚楠","avatar":""},{"name":"Jin Yanna","avatar":""},{"name":"Jiang Zhenhao","avatar":""},{"name":"Meilin Mo","avatar":""},{"name":"Apollo Yu","avatar":""},{"name":"Wang Yanan","avatar":""},{"name":"Yue Dongfeng","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Polar Sea Lost Dungeon","지해미쿠","极海迷窟"]', 1784690324226);
