INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sat-thu-2024', 'Trò Chơi Sát Thủ', 'The Killer''s Game', 'https://phimimg.com/upload/vod/20241009-1/9108168a01dc72f8f921a66cfe023cb0.jpg', 'https://phimimg.com/upload/vod/20241009-1/2919756dfc1a9b629eca858a54837113.jpg', '<p>Nội dung phim xoay quanh Joe Flood (do Dave Bautista thủ vai), một sát thủ chuyên nghiệp làm việc tại Budapest. Trong một lần thực hiện nhiệm vụ tại buổi biểu diễn múa, Joe đã cứu giúp Maize (Sofia Boutella), một vũ công bị ngã. Từ đó, hai người bắt đầu một mối quan hệ tình cảm.Sau khi được chẩn đoán mắc bệnh nan y và chỉ còn ba tháng để sống, Joe quyết định thuê người ám sát mình để Maize có thể nhận được tiền bảo hiểm nhân thọ. Tuy nhiên, sau khi hợp đồng được ký kết, Joe phát hiện mình bị chẩn đoán sai và không hề mắc bệnh. Anh cố gắng hủy bỏ hợp đồng, nhưng những sát thủ mà anh thuê đã bắt đầu hành động, không chỉ nhắm vào anh mà còn vào Maize, người hiện đang mang thai. Joe buộc phải chiến đấu chống lại những sát thủ này để bảo vệ bản thân và gia đình nhỏ của mình</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dave Bautista","avatar":""},{"name":"Sofia Boutella","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Pom Klementieff","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Andrew Galloway","avatar":""},{"name":"Shaina West","avatar":""},{"name":"Lucy Cork","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Hoon Lee","avatar":""},{"name":"Marko Zaror","avatar":""},{"name":"Raffaello Degruttola","avatar":""},{"name":"Antonia Desplat","avatar":""},{"name":"George Somner","avatar":""},{"name":"Alex Kingston","avatar":""},{"name":"Dylan Moran","avatar":""},{"name":"Mi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["بازی قاتلان","משחק המתנקש","The Killers Game","殺手遊戲","Qatilin Oyunu","The Killer''s Game"]', 1784690324226);
