INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-bac-sinh-tu', 'Canh Bạc Sinh Tử', 'Bhaje Vaayu Vegam', 'https://phimimg.com/upload/vod/20241009-1/35869c63ccad61ff217acd0f86d297e0.jpg', 'https://phimimg.com/upload/vod/20241009-1/6320fb0e5ea06c282d99c0a806a9e9ea.jpg', '<p>Hai anh em từ làng chuyển đến thành phố để theo đuổi ước mơ của mình, nhưng hoàn cảnh khiến họ gặp rắc rối khi vô tình vướng vào tên trùm nguy hiểm ở địa phương, trong khi tuyệt vọng tìm kiếm tiền để chi trả cho cuộc phẫu thuật cứu sống cha mình.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Kartikeya Gummakonda","avatar":""},{"name":"Rahul Haridas","avatar":""},{"name":"Iswarya Menon","avatar":""},{"name":"Tanikella Bharani","avatar":""},{"name":"P. Ravi Shankar","avatar":""},{"name":"Sharath Lohitashwa","avatar":""},{"name":"Krishna Chaitanya","avatar":""},{"name":"Nellore Sudharshan","avatar":""},{"name":"Babloo Prithiveeraj","avatar":""},{"name":"Chatrapathi Sekhar","avatar":""},{"name":"Suman Shetty","avatar":""},{"name":"Racha Ravi","avatar":""},{"name":"Bharani Shankar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["BVV","Bhaje Vayu Vegam","Bhaje Vaayu Vegam","เดิมพันอันตราย","భజే వాయు వేగం"]', 1784690324227);
