INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-minh-tren-chien-hao', 'Bình Minh Trên Chiến Hào', 'Before Dawn', 'https://phimimg.com/upload/vod/20241009-1/7347af64710b7e4bd003a32000240c83.jpg', 'https://phimimg.com/upload/vod/20241009-1/de141c5747e90d6f1a792edb9e272086.jpg', '<p>Before Dawn (2024) kể về Jim Collins, một cậu bé từ vùng hẻo lánh Tây Úc, tham gia chiến đấu trên Mặt trận phía Tây trong Chiến tranh Thế giới thứ nhất. Bộ phim theo chân Jim và tiểu đoàn của anh đối mặt với những khốc liệt của chiến tranh trong các chiến hào đẫm máu. Từ một chàng trai trẻ đầy nhiệt huyết, Jim dần nhận ra sự tàn phá kinh hoàng của chiến</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Levi Miller","avatar":""},{"name":"Travis Jeffery","avatar":""},{"name":"Ed Oxenbould","avatar":""},{"name":"Stephen Peacocke","avatar":""},{"name":"Myles Pollard","avatar":""},{"name":"Tim Franklin","avatar":""},{"name":"Jordan Dulieu","avatar":""},{"name":"Darren Jasper","avatar":""},{"name":"Oscar Millar","avatar":""},{"name":"Lawrence Murphy","avatar":""},{"name":"Isaac Davies","avatar":""},{"name":"Noah D''Annunzio","avatar":""},{"name":"Peter Sullivan","avatar":""},{"name":"Peter Williams","avatar":""},{"name":"Robbie Anderson","avatar":""},{"name":"Paul Walenkamp","avatar":""},{"name":"Mit","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Antes da Alvorada","Before Dawn"]', 1784690324227);
