INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-mat-vao-man-dem', 'Biến mất vào màn đêm', 'Vanished into the Night', 'https://phimimg.com/upload/vod/20241009-1/22fbe124bb5cdf338145ddbf31035f5a.jpg', 'https://phimimg.com/upload/vod/20241009-1/d8d0b5412c7d86caed1cfbb035188a18.jpg', '<p>Chìm đắm trong quá trình ly hôn khó khăn, người bố nọ dấn thân vào một nhiệm vụ nguy hiểm khi các con biến mất khỏi ngôi nhà biệt lập của họ ở vùng nông thôn.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Riccardo Scamarcio","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Massimiliano Gallo","avatar":""},{"name":"Gaia Coletti","avatar":""},{"name":"Lorenzo Ferrante","avatar":""},{"name":"Giordano Agrusta","avatar":""},{"name":"Arturo Alessandri","avatar":""},{"name":"Martina Colaninno","avatar":""},{"name":"Giandomenico Cupaiuolo","avatar":""},{"name":"Carmine D''Ippolito","avatar":""},{"name":"Constantinos Danikas","avatar":""},{"name":"Giovanni De Maria","avatar":""},{"name":"Giuseppe Gimmi","avatar":""},{"name":"Gia","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Vanished into the Night","ค่ำคืนกลืนหาย","Forsvunnet inn i natten","Svaniti nella notte"]', 1784690324227);
