INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('world-dice-tour-2', 'World Dice Tour 2', 'World Dice Tour 2', 'https://phimimg.com/upload/vod/20241010-1/3a38412194a50410ce32de8f71045c71.jpg', 'https://phimimg.com/upload/vod/20241010-1/39a91b972232b30645400c7792123b36.jpg', '<p>Một cuộc phiêu lưu không thể đoán trước với việc tung xúc xắc! Một cuộc hành trình không thể đoán trước qua các mùa! Phần 2 của! Ba nhà sáng tạo du lịch, ªPani Bottle, Kwak Joon Bin và Won Ji (Won Ji&#39;s Life)ª đã trở lại! Bạn càng lăn, bạn càng có nhiều niềm vui! Một cuộc chiến nội dung bắt đầu trên một bảng được nâng cấp với thiết bị chơi game mới! Cuộc hành trình không thể đoán trước của Kwak Joon Bin, Pani Bottle và Won Ji, những người một lần nữa nhảy lên bảng theo con xúc xắc, bắt đầu.</p>', 'Hoàn Tất (14/14)', 14, 'tvshows', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"빠니보틀","avatar":""},{"name":"Kwak Joon-bin","avatar":""},{"name":"Lee Won-ji","avatar":""},{"name":"노홍철","avatar":""},{"name":"주우재","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["부루마불 세계여행","Blue Marble World Tour","Earth Marble World Tour","지구마불 세계여행"]', 1784690324227);
