INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('world-dice-tour-2', 'World Dice Tour 2', 'World Dice Tour 2', 'world dice tour 2 world dice tour 2 빠니보틀 kwak joon-bin lee won-ji 노홍철 주우재 부루마불 세계여행 blue marble world tour earth marble world tour 지구마불 세계여행', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum-riize', 'Ông Trùm RIIZE', 'Boss Riize', 'https://phimimg.com/upload/vod/20241010-1/dc50118f5eaa7f4e1cd94f3897c32705.jpg', 'https://phimimg.com/upload/vod/20241010-1/d8740ffc72fe5462c1c20d2ff03ad797.jpg', '<p>Các công nhân bắt đầu làm việc chăm chỉ trong khi các thành viên tiến vào đế chế nịnh nhằm chiến thắng trái tim của Ông Trùm SOHEE. Một thành viên thậm chí còn tự xưng là cánh tay phải và lấy lòng Ông Trùm thành công bằng chiến lược xuất sắc, bất chấp sự phản đối từ các công nhân. Đó có thể là ai? Một mặt khác, Ông Trùm Đệ Nhất SOHEE quyết định tận hưởng bữa trưa và gọi một bàn đầy những món hải sản tươi ngon. Từ các món ăn kèm đến thực đơn cua hoàng đế và gỏi cá sống, các thành viên được tha hồ thưởng thức hương vị biển. Tuy nhiên, trong bữa trưa, ai nấy đều bị sốc khi nhiệm vụ ẩn được tiết lộ. Tất cả các thành viên bắt đầu trở nên hiếu thắng vì tham vọng quyền lực. Nhiệm vụ ẩn dẫn đến cuộc đối đầu trực diện cho vị trí Ông Trùm sẽ là gì?</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"RIIZE","avatar":""},{"name":"SHOTARO","avatar":""},{"name":"EUNSEOK","avatar":""},{"name":"SUNGCHAN","avatar":""},{"name":"WONBIN","avatar":""},{"name":"SOHEE","avatar":""},{"name":"ANTON","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["보스 라이즈"]', 1784690324227);
