INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-trum-riize', 'Ông Trùm RIIZE', 'Boss Riize', 'ông trùm riize boss riize riize shotaro eunseok sungchan wonbin sohee anton 보스 라이즈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-pho-va-piano', 'Đào, Phở Và Piano', 'Peach Blossom, Pho and Piano', 'https://phimimg.com/upload/vod/20241009-1/e27faf714e7fe02e137a9e36798216dc.jpg', 'https://phimimg.com/upload/vod/20241009-1/c46afe4a9a24a57386a90c71e365ac49.jpg', '<p>Lấy bối cảnh trận chiến đông xuân kéo dài 60 ngày đêm từ cuối năm 1946 đến đầu năm 1947 ở Hà Nội, câu chuyện theo chân chàng dân quân Văn Dân và chuyện tình với nàng tiểu thư đam mê dương cầm Thục Hương. Khi những người khác đã di tản lên chiến khu, họ quyết định cố thủ lại mảnh đất thủ đô đã tan hoang vì bom đạn, mặc cho những hiểm nguy đang chờ đợi trước mắt.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Cao Thị Thuỳ Linh","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Trần Lực","avatar":""},{"name":"Trung Hiếu","avatar":""},{"name":"Nguyễn Tuấn Hưng","avatar":""},{"name":"Nguyễn Thiện Hùng","avatar":""},{"name":"Phạm Anh Tuấn","avatar":""},{"name":"Cao Nguyệt Hằng","avatar":""},{"name":"Bùi Hải Vy","avatar":""},{"name":"Nguyễn Diệu Thuý","avatar":""},{"name":"Nguyễn Xuân Hồng","avatar":""},{"name":"Văn Lượng","avatar":""},{"name":"Pham Minh Quang","avatar":""},{"name":"Tùng Lee","avatar":""},{"name":"Nguyễn Hải Quân","avatar":""},{"name":"Phạm Tiến Lợi","avatar":""},{"name":"Đoàn Ngọc Án","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Персики, фо и фортепиано","Đào, Phở và Piano"]', 1784690324227);
