INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dao-pho-va-piano', 'Đào, Phở Và Piano', 'Peach Blossom, Pho and Piano', 'đào, phở và piano peach blossom, pho and piano cao thị thuỳ linh doãn quốc đam trần lực trung hiếu nguyễn tuấn hưng nguyễn thiện hùng phạm anh tuấn cao nguyệt hằng bùi hải vy nguyễn diệu thuý nguyễn xuân hồng văn lượng pham minh quang tùng lee nguyễn hải quân phạm tiến lợi đoàn ngọc án персики, фо и фортепиано đào, phở và piano', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-lanh', 'Máu Lạnh', 'The Two Sisters', 'https://phimimg.com/upload/vod/20241009-1/9e2cabab16005ea773424b2ae2f6e9b8.jpg', 'https://phimimg.com/upload/vod/20241009-1/a7860ad0888c26fe7f0130cdd6bf0c03.jpg', '<p>Hai chị em Lee Hye Won và Lee Hye Ji rất thân thiết khi còn nhỏ. Sau khi bố mẹ họ ly hôn, họ đã bị chia cắt. Lee Hye Won đi sống với cha, còn Lee Hye Ji đi sống với mẹ. Cuộc sống của họ đi theo những con đường khác nhau, nhưng cả hai đều trải qua những thời kỳ khó khăn.

Khi trưởng thành, Hye Won trông có vẻ hoàn hảo, nhưng cô ấy mang những vết thương tinh thần. Cuộc sống của cô bị chi phối bởi mẹ kế. Hôn phu của cô là Yoon Ji Chang, và họ sắp kết hôn. Yoon Ji Chang là con trai của Yoon Yi Cheol, chủ tịch Tập đoàn JY.

Trong khi đó, Hye Ji đã sống qua những ngày tháng nghèo khó, cô đơn và bạo lực gia đình do mẹ và cha dượng của mình. Cô rất muốn thay đổi cuộc đời mình và đã lấy tên mới là Bae Do Eun. Sau đó, cô gặp Yi Cheol, chủ tịch của Tập đoàn JY. Để khởi đầu lại cuộc đời, cô bắt đầu một mối quan hệ với Yi Cheol. Rồi, cô gặp lại chị gái Hye Won, lần đầu tiên kể từ khi họ còn nhỏ.</p>', 'Hoàn Tất (104/104)', 104, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이소연","avatar":""},{"name":"하연주","avatar":""},{"name":"오창석","avatar":""},{"name":"Jang Se-hyun","avatar":""},{"name":"Park Sin-woo","avatar":""},{"name":"정찬","avatar":""},{"name":"Yoo Ji-yeon","avatar":""},{"name":"Yang Hye-Jin","avatar":""},{"name":"Jeong Hye-seon","avatar":""},{"name":"유태웅","avatar":""},{"name":"김예령","avatar":""},{"name":"정수영","avatar":""},{"name":"이응경","avatar":""},{"name":"윤복인","avatar":""},{"name":"강성진","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["THE TWO SISTERS","No Blood No Tears","ICB","TTS","Without Blood or Tears","피도 눈물도 업시","Pido Nunmuldo Eobshi","Без крови и слёз","Хладнокровное убийство","Without Blood and Tears","In Cold Blood","피도 눈물도 없이"]', 1784690324227);
