INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mau-lanh', 'Máu Lạnh', 'The Two Sisters', 'máu lạnh the two sisters 이소연 하연주 오창석 jang se-hyun park sin-woo 정찬 yoo ji-yeon yang hye-jin jeong hye-seon 유태웅 김예령 정수영 이응경 윤복인 강성진 the two sisters no blood no tears icb tts without blood or tears 피도 눈물도 업시 pido nunmuldo eobshi без крови и слёз хладнокровное убийство without blood and tears in cold blood 피도 눈물도 없이', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-thuy-dieu-dieu', 'Lưu Thủy Điều Điều', 'Love Of Nirvana', 'https://phimimg.com/upload/vod/20240915-1/08fe783029ef9f14f2d6ac40b3f017c8.jpg', 'https://phimimg.com/upload/vod/20240915-1/83d841a15456eff464b3cc91755131a0.jpg', '<p>Tiêu Vô Hà, thiếu thành chủ của thành Nguyệt Lạc, nhẫn nhục chịu đựng nằm vùng ở nước Lương nhiều năm với cái tên Vệ Chiêu, gánh vác tội danh gian thần. Vì muốn điều tra chân tướng về gia tộc năm xưa, Vệ Chiêu có ý định bắt cóc người còn sống sót duy nhất trong vụ án Tề Vương, song kế hoạch y dày công sắp đặt lại bị phá hỏng bởi cô gái trẻ bất ngờ xuất hiện, Giang Từ. Bùi Diễm nhân cơ hội này đưa Giang Từ đang bị thương nặng về phủ để tìm ra kẻ đã phá hỏng kế hoạch phía sau. Cảnh ngộ bi thương và đại nghĩa vì dân tộc của Vệ Chiêu đã lay động trái tim trong sáng của Giang Từ. Qua thời gian tiếp xúc, cả hai đã nhận ra điểm tốt đẹp ở đối phương, dần nảy sinh tình cảm. Cuối cùng, ba người Vệ Chiêu, Giang Từ và Bùi Diễm buông bỏ ân oán cá nhân, cùng nhau chống lại Lương Đế, thực hiện tâm nguyện bảo vệ Nguyệt Lạc, xây dựng một thiên hạ sạch trong.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Lý Lan Địch","avatar":""},{"name":"Từ Chính Khê","avatar":""},{"name":"Cao Hàn","avatar":""},{"name":"Trương Nhã Khâm","avatar":""},{"name":"Trương Phong Nghị","avatar":""},{"name":"Ôn Tranh Vanh","avatar":""},{"name":"Đào Hân Nhiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324227);
