INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luu-thuy-dieu-dieu', 'Lưu Thủy Điều Điều', 'Love Of Nirvana', 'lưu thủy điều điều love of nirvana nhậm gia luân lý lan địch từ chính khê cao hàn trương nhã khâm trương phong nghị ôn tranh vanh đào hân nhiên ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-nhan-kiep', 'Hoa Nhan Kiếp', 'Fate Of Beauty', 'https://phimimg.com/upload/vod/20240925-1/b53a1fcbf75469351b4022866dc60fb4.jpg', 'https://phimimg.com/upload/vod/20240925-1/185ef4ff4674b6c4d577fb82bc2b77af.jpg', '<p>Bộ phim kể về câu chuyện của nữ chính Hạ An Lạc. Khi còn nhỏ, gia tộc cô đã bị vị hôn phu Tiêu Diệp Đình mưu hại dẫn đến diệt vong. Sau nhiều năm chuẩn bị để khôi phục danh dự cho gia tộc, cô buộc phải nhẫn nhục, giấu kín thân phận và tiếp cận kẻ thù. Trong quá trình tìm kiếm chứng cứ, cô được Tiêu Mộ Nhiên đem lòng ngưỡng mộ. Yêu hận tình thù giữa ba người được hóa giải nhờ tình yêu, cuối cùng lựa chọn bảo vệ lẫn nhau, không chỉ đồng lòng rửa sạch oan khuất mà còn buông bỏ thù hận, tìm lại chính mình và theo đuổi tình yêu đích thực.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"張楚寒","avatar":""},{"name":"趙奐然","avatar":""},{"name":"严子贤","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["화안겁: 도화살","花颜劫"]', 1784690324227);
