INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-dem-he', 'Bí Mật Đêm Hè', 'Summer Night', 'https://phimimg.com/upload/vod/20240911-1/8c84bbaa50c841eb0227e2032e667714.jpg', 'https://phimimg.com/upload/vod/20240911-1/b0e6b5067c6c8e3eac629e0f18013338.jpg', '<p>Những năm học lẽ ra là khoảng thời gian đẹp nhất trong cuộc đời chúng ta, nhưng Lune lại dành những ngày tháng vô hình, không ai quan tâm đến anh ấy. Tuy nhiên, khi bắt đầu một mùa hè mới, những bí mật sắp đảo lộn cuộc sống đời thường của anh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"ภูวินทร์ ตั้งศักดิ์ยืน","avatar":""},{"name":"Nachcha Chuedang","avatar":""},{"name":"ณัฎฐ์ฐชัย บุญประเสริฐ","avatar":""},{"name":"Bhasidi Petchsutee","avatar":""},{"name":"Phudtripart Bhudthonamochai","avatar":""},{"name":"พบธรรม หรรษา","avatar":""},{"name":"Praekwan Phongskul","avatar":""},{"name":"Nichapha Phraephirakun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324227);
