INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-tran-hon-nhiet-huyet-suc-soi', 'Phố Trấn Hồn: Nhiệt Huyết Sục Sôi', 'Hero Is Back', 'https://phimimg.com/upload/vod/20240923-1/67e84e62375373e05215c9a80a0eb704.jpg', 'https://phimimg.com/upload/vod/20240923-1/a68b9ea88a612dd34c8ce7d359953551.jpg', '<p>Nó kể về câu chuyện của Cao Yanbing, hậu duệ của Wei Wu, người có cơ thể của thần chiến tranh, Xia Ling, người có một linh hồn hộ mệnh bí ẩn, và linh hồn cựu tướng Beifo Shimen với những mục đích khác nhau của họ. nguy hiểm và nguy hiểm. Họ đã hỗ trợ nhau trên đường đi, hoàn thành trải nghiệm và trưởng thành trong tình trạng khó khăn, và khám phá ra một số bí mật gây sốc ...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"敖瑞鵬","avatar":""},{"name":"金珈","avatar":""},{"name":"張予曦","avatar":""},{"name":"陈紫函","avatar":""},{"name":"刘美彤","avatar":""},{"name":"Li Junyi","avatar":""},{"name":"Xu Shiyue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Zhen Hun Jie","鎮魂街之熱血再燃","Rakshasa Street","镇魂街之热血再燃"]', 1784690324227);
