INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-lem-2-gio-sang', 'Lọ Lem 2 Giờ Sáng', 'Cinderella At 2AM', 'https://phimimg.com/upload/vod/20240902-1/9ac9b360a23ece4864193bb5e8b1630c.jpg', 'https://phimimg.com/upload/vod/20240902-1/db86dee9991f1314ba5c5ec8b1236beb.jpg', '<p>Yoon Seo thuộc type độc lập và thực tế. Mẹ của bạn trai cô yêu cầu cô chia tay cùng đề nghị sẽ cho cô 1 khoản tiền lớn. Yoon Seo tin rằng truyện cổ tích không tồn tại trong thế giới của cô và quyết định nhận tiền. Nhưng bạn trai cô lại cố gắng theo đuổi và thay đổi suy nghĩ của cô về tình yêu. Phim phát sóng song song với Hàn Quốc, độc quyền trên K+ bắt đầu từ ngày 24/8.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"신현빈","avatar":""},{"name":"문상민","avatar":""},{"name":"윤박","avatar":""},{"name":"박소진","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324227);
