INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-cua-bach-tuyet', 'Cái Chết Của Bạch Tuyết', 'Black Out', 'https://phimimg.com/upload/vod/20240818-1/2c12f8ee4a59b44b77355b3a37f07977.jpg', 'https://phimimg.com/upload/vod/20240818-1/7e0a6659ca4b14e4feca04f31d830574.jpg', '<p><span style="text-wrap: nowrap;">Câu chuyện xoay quanh hai thám tử điều tra những vụ việc bí ẩn trong một ngôi làng. Bộ phim sẽ diễn giải lại những sự kiện đó và các nhân vật trong sách để phù hợp với tình cảm của người Hàn Quốc và cho thấy mặt xấu của bản chất con người.</span></p><p><span style="text-wrap: nowrap;">Khi Go Jung Woo còn trẻ, anh đủ thông minh để có tên trong danh sách tuyển sinh sớm vào trường y. Sau khi làm bài kiểm tra SAT (bài kiểm tra năng lực học tập), anh đã đi du lịch, nhưng kể từ ngày đó, anh đã trở thành một kẻ giết người. Anh trở về quê hương sau khi được thả khỏi tù và tình cờ biết được những gì đã xảy ra 11 năm trước.</span></p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"변요한","avatar":""},{"name":"고준","avatar":""},{"name":"고보결","avatar":""},{"name":"김보라","avatar":""},{"name":"배종옥","avatar":""},{"name":"권해효","avatar":""},{"name":"Lee Ga-sub","avatar":""},{"name":"공정환","avatar":""},{"name":"김미경","avatar":""},{"name":"안내상","avatar":""},{"name":"조재윤","avatar":""},{"name":"박미현","avatar":""},{"name":"차순배","avatar":""},{"name":"이두일","avatar":""},{"name":"장원영","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324227);
