INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('21-ngay', '21 Ngày', 'The Limbo', 'https://phimimg.com/upload/vod/20240930-1/00ac0374666818ed6f1181ec83e0fec4.jpg', 'https://phimimg.com/upload/vod/20240930-1/a2c1589e71b8fe7e0e58ae69c2f3ee28.jpg', '<p>Gần đến Tết, tại trung tâm thương mại lâu đời La Bách Bách Hóa thành phố Hải Châu đột ngột xảy ra sự cố lún sụt khiến 13 người bị mắc kẹt dưới lòng đất. Cuộc đua với thời gian và sinh mạng này mang đến những thử thách lớn về nhân tính, đạo đức và niềm tin...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"歐豪","avatar":""},{"name":"張雪迎","avatar":""},{"name":"Zhiwen Wang","avatar":""},{"name":"姜武","avatar":""},{"name":"Ting Wang","avatar":""},{"name":"包文婧","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["掩埋的真相","掩埋","二十一天","Er Shi Yi Tian","The Limbo"]', 1784690324227);
