INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-y-tuy', 'Hồng Y Tuý', 'The Dangerous Lover', 'https://phimimg.com/upload/vod/20241004-1/c29cd7eed698056203c02924aab9d64a.jpg', 'https://phimimg.com/upload/vod/20241004-1/764b361117c0e662d2e529bd11cd3c30.jpg', '<p>Hộ Điềm Điềm đã thấy trước kết cục Hộ gia gặp họa diệt môn trong ván cờ. Để thay đổi số phận, Điềm Điềm đã lôi kéo Tô Yến Lê, hoàng tử được &quot;hồi sinh&quot; giống mình dẫn dắt ca ca phản diện hướng thiện. Ai ngờ, Tô Yến Lê có lẽ là thủ phạm khiến Hộ gia diệt môn. Trong quá trình giằng co, Điềm Điềm dần dần hiểu ra nguồn cơn số mệnh giữa nàng và Tô Yến Lê.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Gia Mẫn","avatar":""},{"name":"Hắc Trạch","avatar":""},{"name":"Dương Đằng","avatar":""},{"name":"Lưu Bối Thực","avatar":""},{"name":"Trương Tử Kiện","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["紅衣醉","Hong Yi Zui","红衣醉"]', 1784690324227);
