INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-sau-doi-khat-2', 'Hố Sâu Đói Khát 2', 'The Platform 2', 'https://phimimg.com/upload/vod/20240827-1/e29d4fa24e3908d5932c952a2d7f348c.jpg', 'https://phimimg.com/upload/vod/20240827-1/57b19f638351643422e5c4af23f41d8c.jpg', '<p>Khi một nhà lãnh đạo bí ẩn áp đặt quyền cai trị của họ trên Nền tảng, một cư dân mới bị lôi kéo vào cuộc chiến chống lại phương pháp gây tranh cãi này nhằm chống lại hệ thống cho ăn tàn bạo. Nhưng khi việc ăn nhầm đĩa trở thành bản án tử hình, bạn sẽ sẵn sàng đi bao xa để cứu mạng mình?</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Hovik Keuchkerian","avatar":""},{"name":"Milena Smit","avatar":""},{"name":"Deborah Ayorinde","avatar":""},{"name":"Callum Keith Rennie","avatar":""},{"name":"Natalia Tena","avatar":""},{"name":"Óscar Jaenada","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324227);
