INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cua-bep-truong-mon-mi', 'Bàn Của Bếp Trưởng: Món Mì', 'Chef''s Table: Noodles', 'https://phimimg.com/upload/vod/20241003-1/cf9652e3315801cf5ed5d636e293ebbf.jpg', 'https://phimimg.com/upload/vod/20241003-1/8c845cab10564b4fa898d0568bcb8bd9.jpg', '<p>Khám phá nghệ thuật nấu mì cùng các đầu bếp nổi tiếng thế giới khi mỗi người chia sẻ hành trình ẩm thực và câu chuyện đằng sau những món ăn đặc trưng thơm ngon của họ.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Chef''s Table: Noodles"]', 1784690324227);
