INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-cua-bep-truong-mon-mi', 'Bàn Của Bếp Trưởng: Món Mì', 'Chef''s Table: Noodles', 'bàn của bếp trưởng: món mì chef''s table: noodles  chef''s table: noodles', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-nu-nha-ta-truong-thanh-roi', 'Tài Nữ Nhà Ta Trưởng Thành Rồi', 'A Talented Girl Grows Up', 'https://phimimg.com/upload/vod/20240925-1/411430de67de311ce3c33c3a99a8fe98.jpg', 'https://phimimg.com/upload/vod/20240925-1/57afe19fa2cb1f023e1a5c3b4b8241be.jpg', '<p>Trình Mãn Ý, một cô gái yêu thích mơ mộng nhưng cuộc sống thực tại không như mong đợi. Sau khi dũng cảm cứu người và bị thương, cô ngất xỉu và mơ thấy mình trở thành nữ chính trong truyện tranh Thiên Hạ Đệ Nhất Tài Nữ . Trong giấc mơ, cô gặp Văn Thần Sí, người được gọi là &quot;Thiên Hạ Đệ Nhất Phu Tử&quot;. Cô gái &quot;mù chữ&quot; bèn giả vờ làm tài nữ và cùng Văn Thần Sí ký kết khế ước trở thành vợ chồng. Sự khác biệt về thời đại và tính cách khiến cả hai làm phát sinh vô số tình huống hài hước. Từ ngờ vực, thử thách rồi đến tin tưởng và yêu nhau, họ cùng vượt qua nhiều sóng gió và cuối cùng đến được với nhau. Trình Mãn Ý quyết tâm trở thành nữ Tuần Thành Ngự Sử đầu tiên của Đại Phượng. Cô cùng nhóm bạn thân thiết như ngũ hoàng tử Phượng Tê Ngô, Thôi Tuấn, Văn Thần Vi Vi… lập nên &quot;nhóm đệ nhất&quot; của Đại Phượng để phát triển sự nghiệp và chống lại các thế lực tàn ác. Bằng trí thông minh, họ đối đầu và chiến thắng Đỗ Nhã Cầm - kẻ có âm mưu xấu xa. Cuối cùng, cô thực hiện được ước mơ, bảo vệ cuộc sống bình yên cho người dân và gìn giữ danh dự văn hóa của Đại Phượng. Qua giấc mơ này, Trình Mãn Ý học được cách yêu thương và trưởng thành. Cô tìm ra được con đường thực hiện giá trị bản thân, hiểu thêm về tình yêu thực sự và nhận được tình thân, tình bạn quý giá.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"陈芳彤","avatar":""},{"name":"Zhao Wenhao","avatar":""},{"name":"Jackey Zhu","avatar":""},{"name":"Fang Sichang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Wu Jia Cai Nu Chu Zhang Cheng","天下第一才女","吾家才女初長成","A Talented Girl Grows Up","吾家才女初长成"]', 1784690324227);
