INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-su-hoan-hao-2024', 'Cộng Sự Hoàn Hảo', 'Good Partner', 'https://phimimg.com/upload/vod/20240728-1/0aa7093531b2c1ace4d8c3c8d5c06bb2.jpg', 'https://phimimg.com/upload/vod/20240728-1/26eb7bc95804833f8f9f2b77e8673d79.jpg', '<p>Luật sư Cha Eun Kyeong với 17 năm kinh nghiệm trong lĩnh vực luật ly hôn nhưng chính cô cũng phải đối mặt với khủng hoảng hôn nhân. Cô làm việc cùng luật sư tân binh Han Yoo Ri. Do khác biệt về quan điểm và kinh nghiệm, họ nảy sinh bất đồng, nhưng dần dần họ đã cùng nhau vượt qua những khác biệt.&nbsp;</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"장나라","avatar":""},{"name":"남지현","avatar":""},{"name":"김준한","avatar":""},{"name":"피오","avatar":""},{"name":"지승현","avatar":""},{"name":"한재이","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324227);
