INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-niem-ve-anh', 'Ý Niệm Về Anh', 'The Idea of You', 'https://phimimg.com/upload/vod/20241001-1/0228f94ad92b35dc98ca40f65e74efa6.jpg', 'https://phimimg.com/upload/vod/20241001-1/8533094971b011e865f213fface01502.jpg', '<p>Ý tưởng của bạn là một bộ phim hài lãng mạn của Mỹ năm 2024 do Michael Showalter đạo diễn từ kịch bản anh đồng sáng tác với Jennifer Westfeldt, dựa trên cuốn tiểu thuyết cùng tên của Robinne Lee. Với sự tham gia của Anne Hathaway và Nicholas Galitzine, bộ phim ghi lại mối tình giữa một bà mẹ đơn thân và ca sĩ chính của một nhóm nhạc nam nổi tiếng.</p>', 'Full', 1, 'single', 'ongoing', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Nicholas Galitzine","avatar":""},{"name":"Ella Rubin","avatar":""},{"name":"Annie Mumolo","avatar":""},{"name":"Reid Scott","avatar":""},{"name":"Perry Mattfeld","avatar":""},{"name":"Jordan Aaron Hall","avatar":""},{"name":"Mathilda Gianopoulos","avatar":""},{"name":"Meg Millidge","avatar":""},{"name":"Cheech Manohar","avatar":""},{"name":"Raymond Cham Jr.","avatar":""},{"name":"Jaiden Anthony","avatar":""},{"name":"Viktor White","avatar":""},{"name":"Dakota Adan","avatar":""},{"name":"Roxy Rivera","avatar":""},{"name":"Graham Norton","avatar":""},{"name":"Grace","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["아이디어 오브 유","关于你的想法","概念中的你","所有想法","Als du mich sahst","Sen İhtimali","خیال تو","خاطر تو","La idea de ti","The Idea of You"]', 1784690324227);
