INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-cay', 'Ma Cây', 'Respati', 'https://phimimg.com/upload/vod/20240930-1/364b05cf5cc499e78cbcab40868bfb84.jpg', 'https://phimimg.com/upload/vod/20240930-1/ea22fdd267f75f649b8022f87986598b.jpg', '<p>Sau cái chết bi thảm của cha mẹ, cậu thiếu niên Respati (Devano Danendra) đang cố gắng phục hồi tổn thương và tìm lại sự cân bằng trong cuộc sống. Tuy nhiên, việc phải chịu đựng những cơn ác mộng kinh hoàng mỗi đêm càng khiến tinh thần của Respati bị ảnh hưởng nghiêm trọng. Song, Respati nhận ra đó không đơn thuần là ác mộng, mà cậu đang sở hữu khả năng bước vào giấc mơ của người khác và giữ được ý thức trong mộng giới.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Devano Danendra","avatar":""},{"name":"Mikha Hernan","avatar":""},{"name":"Ratu Felisha","avatar":""},{"name":"Keisya Levronka","avatar":""},{"name":"Fajar Nugra","avatar":""},{"name":"Kiki Narendra","avatar":""},{"name":"Budi Ros","avatar":""},{"name":"Brilliana Desy Dwinawati","avatar":""},{"name":"Dinar Roos","avatar":""},{"name":"Sri Isworowati","avatar":""},{"name":"Maychelina Anis","avatar":""},{"name":"Eko Budi Antara","avatar":""},{"name":"Khayla Maharani","avatar":""},{"name":"Aisya Maharani","avatar":""},{"name":"Olive Nugroho","avatar":""},{"name":"Liek Suyanto","avatar":""},{"name":"Tumin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mimpi Pencabut Nyawa","레스파티","សុបិន្តអាគមខ្មៅ","Астрал. Ночной кошмар","Ma Cây","Respati","Malam Pencabut Nyawa"]', 1784690324227);
