INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-hai-dao', 'Đại Hải Đạo', 'Brother', 'https://phimimg.com/upload/vod/20240930-1/225ff933c962bc5614305462f7122b4d.jpg', 'https://phimimg.com/upload/vod/20240930-1/17f9f7d623d4beacd6c92a1e4e6057a6.jpg', '<p>Câu chuyện thông qua một giải đua xe địa hình hàng đầu thế giới, mang đến cái nhìn sâu sắc về những người trẻ nhiệt huyết theo đuổi ước mơ. Nhóm thanh niên sống ở Tân Cương, đến từ nhiều dân tộc khác nhau, đã dùng đam mê của mình để tái khởi động con đường tơ lụa cổ xưa, trở thành những người hùng trong cuộc sống bình dị. Họ mang theo bản năng hoang dã từ vùng Đại Hải Đạo, kể lại một câu chuyện Tân Cương của thời đại mới, đầy tình người và cảm xúc, đồng thời giới thiệu với thế giới một bức tranh sống động về cuộc sống đương đại tại Tân Cương.</p>', 'Tập 15', 24, 'series', 'ongoing', 14, 2024, 'Vietsub', '', 'Trung Quốc', 0, '[{"name":"Yin Fang","avatar":""},{"name":"Jiao Junyan","avatar":""},{"name":"Wa Er","avatar":""},{"name":"Jia Nai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Da Hai Dao","大海道"]', 1784690324227);
