INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-ho-7a', 'Căn Hộ 7A', 'Apartment 7A', 'https://phimimg.com/upload/vod/20240930-1/a2c17d150a7590ba4702686a050beb4e.jpg', 'https://phimimg.com/upload/vod/20240930-1/5cbeb855e028a2388e36b58b927e3af3.jpg', '<p>&quot;Apartment 7A&quot; (2024) kể về câu chuyện của một vũ công gặp khó khăn trong sự nghiệp, vô tình bị cuốn vào chuỗi sự kiện bí ẩn và siêu nhiên sau khi chuyển đến sống trong một căn hộ mới. Tại đây, cô gặp một cặp đôi kỳ lạ, họ hứa hẹn sẽ giúp cô đạt được danh tiếng và thành công trong sự nghiệp nhảy múa của mình. Tuy nhiên, cơ hội này không hề miễn phí, và cô sớm nhận ra rằng ý định thực sự của cặp đôi này ẩn chứa nhiều điều đen tối hơn cô tưởng. Khi dần khám phá ra bản chất thật sự của họ và những thế lực đứng sau lời hứa, cô phải đối mặt với những nguy hiểm của tham vọng và đấu tranh để giữ vững bản thân mình.</p>', 'Full', 1, 'single', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Julia Garner","avatar":""},{"name":"Dianne Wiest","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"Jim Sturgess","avatar":""},{"name":"Marli Siu","avatar":""},{"name":"Rosy McEwen","avatar":""},{"name":"Andrew Buchan","avatar":""},{"name":"Kobna Holdbrook-Smith","avatar":""},{"name":"Anton Blake Horowitz","avatar":""},{"name":"Patrick Lyster","avatar":""},{"name":"Tina Gray","avatar":""},{"name":"Raphael Sowole","avatar":""},{"name":"Patricia Jones","avatar":""},{"name":"Andre Lillis","avatar":""},{"name":"Rachel Atkins","avatar":""},{"name":"Tina Chiang","avatar":""},{"name":"Hannah Morley","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["آپارتمان 7A","آپارتمان ۷الف",