INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-duy-nhat-do', 'Người Duy Nhất Đó', 'The On1y One', 'https://phimimg.com/upload/vod/20240822-1/e6f973acfdb15b23fc4532444bbfc6af.jpg', 'https://phimimg.com/upload/vod/20240822-1/e8190d2ebd456d331dbc1e8f3a2456ad.jpg', '<p>Bộ phim kể về hai cậu học sinh cấp ba trở thành &quot;anh em&quot; do bố mẹ tái hôn, bất ngờ nảy sinh một tình cảm thân thiết, rồi trở thành &quot;ai đó&quot; trong trái tim nhau.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"劉冬沁","avatar":""},{"name":"曾向鎮","avatar":""},{"name":"洪小鈴","avatar":""},{"name":"段鈞豪","avatar":""},{"name":"Aining Yao","avatar":""},{"name":"Chen-Ting Tsai","avatar":""},{"name":"黃丞邦","avatar":""},{"name":"Mimi Shao","avatar":""},{"name":"An Jun Peng","avatar":""},{"name":"Jie-En Yu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324227);
