INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-hoa-rung-no-ro', 'Khi Hoa Rừng Nở Rộ', 'She and Her Girls', 'https://phimimg.com/upload/vod/20240913-1/e8cc824f2e645d47627df26204f9dd3e.jpg', 'https://phimimg.com/upload/vod/20240913-1/ec6cd7a379932ce7d686f4dec6b8ba85.jpg', '<p>Trương Quế Mai là một giáo viên trung học ở vùng núi phía Tây Trung Quốc. Trong nhiều năm, cô chứng kiến những học sinh nữ của mình phải bỏ học vì hoàn cảnh gia đình khó khăn, và nếu không kết hôn ở tuổi 16, họ sẽ phải ra ngoài làm thuê. Điều này khiến cô cảm thấy rất đau lòng và tiếc nuối. Quyết tâm thay đổi tình hình, cô đã mở một trường cấp ba hoàn toàn miễn phí dành cho nữ sinh, với mục tiêu giúp các cô gái miền núi có cơ hội học tập, thi đỗ đại học, và thay đổi vận mệnh của mình. Năm 2008, trường cấp ba miễn phí đầu tiên dành cho nữ sinh của Trung Quốc được thành lập. Dù phải đối mặt với nhiều khó khăn như thiếu giáo viên, học sinh, kinh phí, và kinh nghiệm, Trương Quế Mai cùng với các giáo viên và học sinh đã vượt qua những thử thách lớn để đạt được thành công. Các nữ sinh với nền tảng học vấn kém đã thi đỗ đại học, giúp họ thoát khỏi vùng núi và thay đổi số phận.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"宋佳","avatar":""},{"name":"Lan Xiya","avatar":""},{"name":"Du Lan","avatar":""},{"name":"合詩雨","avatar":""},{"name":"楊顔嘉","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324227);
