INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-bach-te', 'Hà Bách Tế', 'Please Remember Me', 'https://phimimg.com/upload/vod/20240919-1/63984080ada78ca6ac631bac912f9c62.jpg', 'https://phimimg.com/upload/vod/20240919-1/7470fa4f7e737d162aec4dca14502b5e.jpg', '<p>Thiếu nữ A Niệm của Cấp tộc tình cờ gặp gỡ thiếu niên ngoại tộc Tiêu Tử Túc tại quê hương Tố Thủy, trong quá trình tiếp xúc cả hai dần rơi vào lưới tình. Khi ngày cưới sắp đến, Tiểu Mãn chờ đợi khắc khoải sự xuất hiện của tình lang, nhưng không ngờ thứ cô nhận được lại là tai họa diệt tộc do anh trai của Tử Túc mang đến. Thảm kịch này khiến hai người mất đi ký ức về nhau. Để trả thù cho người trong tộc, A Niệm lấy tên Tiểu Mãn, một mình đến phủ tướng quân, giả vờ ở lại bên cạnh Tử Túc. Tiêu Tử Túc mất trí nhớ đối diện với Tiểu Mãn đột ngột xuất hiện, một mặt vừa nghi ngờ, thăm dò mục đích của Tiểu Mãn khi cô đến phủ, vừa cảm thấy cô quen thuộc, coi cô là chìa khóa để tìm lại ký ức đã mất. Trong khi đó, Tiểu Mãn dần phát hiện ra rằng anh không hề lạnh lùng tàn nhẫn như cô từng nghĩ. Sự ấm áp và tình yêu không thể che giấu của anh khiến cô bắt đầu nghi ngờ rằng kẻ thực sự đứng sau thảm họa diệt tộc là người khác. Trong những mảnh ký ức rời rạc, cả hai dần tìm lại ký ức ban đầu và cùng nhau thực hiện lời hứa bị lãng quên năm xưa...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"楊澤","avatar":""},{"name":"Zong Yuanyuan","avatar":""},{"name":"Feifei Zhang","avatar":""},{"name":"Wang Ya Ni","avatar":""},{"name":"Jiamao Wang","avatar":""},{"name":"潘霖","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["河伯祭"]', 1784690324227);
