INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-chu-gioi-chay-tron', 'Thiếu Chủ Giỏi Chạy Trốn', 'The Elusive Samurai', 'https://phimimg.com/upload/vod/20240929-1/986dc91f028d7b19002a494f7e5ce8d0.jpg', 'https://phimimg.com/upload/vod/20240929-1/15d7cfa3169effa0d84d1272116af556.jpg', '<p>Lấy bối cảnh giữa thời Kamakura và Muromachi, trong thời kỳ Khôi phục Kenmu, câu chuyện kể về Hojo Tokiyuki, một cậu bé chạy trốn sau khi gia đình bị Ashikaga Takauji lật đổ. Với đồng minh duy nhất của mình là một linh mục mờ ám và những người theo ông, lãnh chúa trẻ phải tìm cách trả thù và lấy lại vinh quang bằng vũ khí duy nhất của mình: khả năng siêu phàm để chạy trốn và lẩn trốn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"結川あさき","avatar":""},{"name":"中村悠一","avatar":""},{"name":"矢野妃菜喜","avatar":""},{"name":"日野まり","avatar":""},{"name":"鈴代紗弓","avatar":""},{"name":"悠木碧","avatar":""},{"name":"戸谷菊之介","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["擅长逃跑的少主殿下","少主溜得快","Nige Jouzu no Wakagimi","NigeWaka","にげじょうずのわかぎみ","逃げ若","Nige Jōzu no Wakagimi","NigeJouzu no Wakagimi","逃げ上手の若君第一期","The Young Lord Who Is Skilled at Escaping","逃げ上手の若君"]', 1784690324227);
