INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-san-vay-mau', 'Di sản vấy máu', 'Blood Legacy', 'https://phimimg.com/upload/vod/20240927-1/5679797213e28b560d8e365e40bc7540.jpg', 'https://phimimg.com/upload/vod/20240927-1/a25fa6f5ececfce9c46753d0d3f0f111.jpg', '<p>Sau nhiều năm xa cách, Khanyi Adesina trở về nhà để đấu tranh cho đế chế kinh doanh của gia đình khi nó có nguy cơ sụp đổ vì sự mục nát bên trong.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Treasure Nkosi","avatar":""},{"name":"Xolile Tshabalala","avatar":""},{"name":"Buyile Mdladla","avatar":""},{"name":"Mike Ndlangamandla","avatar":""},{"name":"Connie Chiume","avatar":""},{"name":"Sello Maake Ka-Ncube","avatar":""},{"name":"Pallance Dladla","avatar":""},{"name":"Anthony Oseyemi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Blood Legacy"]', 1784690324227);
