INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-duc-tin', 'Hành Trình Đức Tin', 'Between the Temples', 'https://phimimg.com/upload/vod/20240927-1/38c3ec3edd62c5b32145bac26cdaa0ae.jpg', 'https://phimimg.com/upload/vod/20240927-1/88f633f48a69dd477382ef353d32146f.jpg', '<p>Nội dung phim kể về Ben Gottlieb, một ca trưởng đang trải qua khủng hoảng đức tin sau cái chết của vợ mình. Cuộc sống của anh bị đảo lộn khi Carla Kessler, giáo viên âm nhạc tiểu học của anh, trở thành học viên Bat Mitzvah trưởng thành của anh. Bộ phim khai thác sâu sắc mối quan hệ giữa họ, khi cả hai cùng đối diện với quá khứ và tìm lại chính mình</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Schwartzman","avatar":""},{"name":"Carol Kane","avatar":""},{"name":"Dolly de Leon","avatar":""},{"name":"Caroline Aaron","avatar":""},{"name":"Robert Smigel","avatar":""},{"name":"Madeline Weinstein","avatar":""},{"name":"Matthew Shear","avatar":""},{"name":"Lindsay Burdge","avatar":""},{"name":"Julia Walsh","avatar":""},{"name":"Brittany Walsh","avatar":""},{"name":"Diane Lanyi","avatar":""},{"name":"Keith Poulson","avatar":""},{"name":"Jason Grisell","avatar":""},{"name":"Annie Hamilton","avatar":""},{"name":"Jaden Waldman","avatar":""},{"name":"Simona Sickler","avatar":""},{"name":"Pauline","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Carla et moi","Entre os Templos","Between the Temples"]', 1784690324227);
