INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-cho-toi-thay-ban-la-ai', 'Hãy Cho Tôi Thấy Bạn Là Ai', 'I Can See You Shine', 'https://phimimg.com/upload/vod/20240907-1/9506463474b614ea54b128e5dab80d4c.jpg', 'https://phimimg.com/upload/vod/20240907-1/89fc9fbc64ec5f67899a83bea6ccb992.jpg', '<p>Hai nữ sinh trung học Yang và Tung là bạn thân dù tính cách trái ngược nhau và xuất thân khác nhau. Tình bạn của họ bị rạn nứt khi họ phải đối mặt với những vấn đề rắc rối của tuổi teen, tình yêu đơn phương, những rắc rối trong gia đình và cuộc sống trung học đầy rối loạn. Nếu tuổi thiếu niên chưa đủ khó khăn thì người ta còn phải đối mặt với bãi mìn văn hóa khi trở thành người nhập cư thế hệ thứ hai.</p>', 'Tập 8', 8, 'series', 'ongoing', 14, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"雷嘉汭","avatar":""},{"name":"Zhan Huai-Yun","avatar":""},{"name":"Andy Huang","avatar":""},{"name":"鄭宇恩","avatar":""},{"name":"金東昱","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324227);
