INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-lac-khuc', 'Trường Lạc Khúc', 'Melody Of Golden Age', 'https://phimimg.com/upload/vod/20240901-1/3058020177b648c1c18e6eaa46c8de1e.jpg', 'https://phimimg.com/upload/vod/20240901-1/cc16c95a8984e7bc1f7dbfe00ede66b2.jpg', '<p>Bộ phim kể về câu chuyện của một cặp đôi kẻ thù không đội trời chung vô tình trở thành một cặp nhưng lại yêu nhau trong một loạt các vụ án kỳ lạ và cuối cùng đã chọn chiến đấu cùng nhau.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"丁禹兮","avatar":""},{"name":"邓恩熙","avatar":""},{"name":"Mao Zijun","avatar":""},{"name":"肖燕","avatar":""},{"name":"Song Fangyuan","avatar":""},{"name":"張傑","avatar":""},{"name":"喬詩語","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324227);
