INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac-ky-dieu-cua-chung-toi', 'Thời Khắc Kỳ Diệu Của Chúng Tôi', 'Their Wonderful Time', 'https://phimimg.com/upload/vod/20240910-1/740c92d092a6a3c9619637a8c307d54d.jpg', 'https://phimimg.com/upload/vod/20240910-1/4bff6835b0363380b55c9d543f4d1ad2.jpg', '<p>Nhà thiết kế trò chơi Tống Linh Linh vô tình bị NPC trong game do mình thiết kế nhập vào người, bị ép phải bắt đầu cuộc sống chung đụng dở khóc dở cười với nhà đầu tư Tiêu Nhiên. Hai người vừa sửa bug trò chơi, vừa sửa &quot;bug tâm lý&quot; của mình, từ chí chóe như chó với mèo đến yêu mến nhau. Họ cùng những người bạn như Trương Vân Phi trải qua bao nguy hiểm giữa hai thế giới ảo và thực, bắt đầu một mối tình vượt không gian, cuối cùng nhận lại tình bạn và tình yêu thuộc về mình!</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhou Jieqiong","avatar":""},{"name":"Ge Qiugu","avatar":""},{"name":"Zhang Sifan","avatar":""},{"name":"李梦琪","avatar":""},{"name":"Shi Qingyan","avatar":""},{"name":"Li Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324227);
