INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thoi-khac-ky-dieu-cua-chung-toi', 'Thời Khắc Kỳ Diệu Của Chúng Tôi', 'Their Wonderful Time', 'thời khắc kỳ diệu của chúng tôi their wonderful time zhou jieqiong ge qiugu zhang sifan 李梦琪 shi qingyan li hao ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-don-gio', 'Thanh Xuân Đón Gió', 'Wind Direction', 'https://phimimg.com/upload/vod/20240909-1/f987b92eab7bc69e01472925653f0763.jpg', 'https://phimimg.com/upload/vod/20240909-1/3387247444cec60a1eb6f1d3a0c26df9.jpg', '<p>Cả hai chị em Trình Miêu Miêu 17 tuổi và Trình Nha Nha 16 tuổi đều sinh ra tại nhà máy khai thác dầu mỏ Lâm Thất, gia đình ba đời đều là công nhân dầu mỏ. Bố của họ, Trình Bằng Phi, là bác sĩ tai mũi họng, còn mẹ là Giả Đại Ngọc làm công tác hậu cần cho đội xe. Cả gia đình đã chuyển từ Tây Bắc đến thị trấn Hà Bình ở cơ sở ven biển. Cuối thập niên 90, Miêu Miêu mang trong lòng khát khao khám phá thế giới bên ngoài, rủ người bạn thanh mai trúc mã Lý Tứ và cô bạn thân Hồ Thu Mẫn lên kế hoạch thực hiện chuyến phiêu lưu &quot;đi Hong Kong đón ngày trở về&quot; trong kỳ nghỉ hè lớp 10, nhưng không suôn sẻ. Trong khi đó, Nha Nha, cậu em 16 tuổi, đi khảo cổ trên núi sau suýt bị hiểu nhầm là kẻ đào mộ. Mẹ Giả Đại Ngọc vô cùng đau đầu, và hai chị em bắt đầu cuộc sống cấp ba đầy rắc rối. Trình Miêu Miêu rơi vào khủng hoảng tình cảm với Lý Tứ, còn Nha Nha thì đứng ra bảo vệ cô bạn mới chuyển đến là con gái của kẻ truy nã là Viên Sơn Thanh khỏi những ánh mắt thù địch từ mọi phía. Trong sự thay đổi, các cô cậu học sinh đã trải qua và trưởng thành.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sun Qian","avatar":""},{"name":"翟子路","avatar":""},{"name":"刘琳","avatar":""},{"name":"田雨","avatar":""},{"name":"Li Qing","avatar":""},{"name":"Qi Yu Chen","avatar":""},{"name":"刘小北","avatar":""},{"name":"李羽桐","avatar":""},{"name":"李乃文","avatar":""},{"name":"曾黎","avatar":""},{"name":"Jia Bing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324227);
