INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-hai-hoa', 'Tạng Hải Hoa', 'Adventure Behind The Bronze Door', 'https://phimimg.com/upload/vod/20240901-1/f4b80b0b0375f37cb0bf68d41247853a.jpg', 'https://phimimg.com/upload/vod/20240901-1/92fffa7db013a1c5d5c20e9f825a53ce.jpg', '<p>Câu chuyện được kể lại sau khi &quot;Đạo Mộ Bút Ký&quot; kết thúc. Trong một lần tình cờ, Ngô Tà và Vương Bàn Tử cùng nhau đến núi tuyết để khám phá thân thế bí ẩn của Trương Khởi Linh. Trong cuộc hành trình này, họ đã phải đối mặt với những thử thách cam go, đấu trí đấu dũng cùng hai anh em Trương Hải Hạnh và Trương Hải Khách của Trương gia. Hai người cũng bị cuốn vào một âm mưu chưa từng thấy. Một cuộc phiêu lưu lãng mạn đầy kịch tính bắt đầu từ đây...</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Luyi","avatar":""},{"name":"Janice Man","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Zhang Kangle","avatar":""},{"name":"Shawn Wei","avatar":""},{"name":"白冰","avatar":""},{"name":"喬振宇","avatar":""},{"name":"Xia Zi Xuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324227);
