INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-chu-mao-hiem-gia-tan-binh-duoc-to-doi-manh-nhat-huan-luyen-cho-den-chet-va-tro-thanh-vo-dich', 'Ông Chú Mạo Hiểm Giả Tân Binh Được Tổ Đội Mạnh Nhất Huấn Luyện Cho Đến Chết Và Trở Thành Vô Địch', 'The Ossan Newbie Adventurer, Trained to Death by the Most Powerful Party, Became Invincible', 'https://phimimg.com/upload/vod/20240909-1/4a6c7b69005484049ba5f8902dc09177.jpg', 'https://phimimg.com/upload/vod/20240909-1/a29041e1267784b4f5f4929b3918766b.jpg', '<p>Một ông chú tân binh 30 tuổi quyết định rời bỏ công việc nhân viên văn phòng của hội để trở thành mạo hiểm giả. Anh ấy đã trải qua “một thứ gì đó khủng khiếp hơn cả địa ngục” trong hai năm huấn luyện với các đàn anh của “Orihalcon Fist”, nhóm được cho là mạnh nhất lục địa, và đã phát triển vượt bậc. Những ngày huấn luyện lặp đi lặp lại giữa cái chết và sự hồi sinh đã trở thành một chấn thương tâm lý sâu sắc của anh.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"佐藤拓也","avatar":""},{"name":"大西沙織","avatar":""},{"name":"三宅健太","avatar":""},{"name":"豊永利行","avatar":""},{"name":"久野美咲","avatar":""},{"name":"下地紫野","avatar":""},{"name":"木村良平","avatar":""},{"name":"徳留慎乃佑","avatar":""},{"name":"長岡龍歩","avatar":""},{"name":"小西克幸","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324227);
