INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-chu-mao-hiem-gia-tan-binh-duoc-to-doi-manh-nhat-huan-luyen-cho-den-chet-va-tro-thanh-vo-dich', 'Ông Chú Mạo Hiểm Giả Tân Binh Được Tổ Đội Mạnh Nhất Huấn Luyện Cho Đến Chết Và Trở Thành Vô Địch', 'The Ossan Newbie Adventurer, Trained to Death by the Most Powerful Party, Became Invincible', 'ông chú mạo hiểm giả tân binh được tổ đội mạnh nhất huấn luyện cho đến chết và trở thành vô địch the ossan newbie adventurer, trained to death by the most powerful party, became invincible 佐藤拓也 大西沙織 三宅健太 豊永利行 久野美咲 下地紫野 木村良平 徳留慎乃佑 長岡龍歩 小西克幸 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-quang-dan', 'Lưu Quang Dẫn', 'Fateful Love', 'https://phimimg.com/upload/vod/20240901-1/be3cf312f8b545603737b363e650435c.jpg', 'https://phimimg.com/upload/vod/20240901-1/258921dffd2980a76f996d667c62340e.jpg', '<p>Hàn Tử Tình, thứ nữ của phủ thừa tướng vì một biến cố bất ngờ biến đổi thân phận mà tình cờ gặp gỡ Quân Bắc Nguyệt, chiến thần Thiên Minh, bị cuốn vào cuộc chiến tranh giành đại lục giữa các cường quốc và dân tộc khác nhau. Độc hương mê hoặc đã hé lộ bí mật thân thế của Hàn Tử Tình. Bảy âm phù rải rác khắp đại lục chính là manh mối dẫn dắt cô về quê hương. Để vén màn vô vàn bí ẩn, Hàn Tử Tình cùng Quân Bắc Nguyệt bước vào hành trình đầy hiểm nguy. Cả hai đấu trí đấu dũng với nhiều thế lực ngầm hùng mạnh trên đại lục Long Uyên, từ Nghị Nhân Phu dưới biển sâu đến thế giới Đặc Thảo thần bí. Đồng thời khám phá những vùng đất bí ẩn mà người thường không thể đặt chân tới, như Cầm Yếu Hải Cốc, đảo Diên Tiên và nơi chỉ tồn tại trong truyền thuyết. Sau bao gian nan thử thách, cuối cùng hai người cũng khám phá ra bí mật về thân thế, tiêu diệt các thế lực tà ác và bảo vệ sự yên bình của Long Uyên. Tình yêu giữa Hàn Tử Tình và Quân Bắc Nguyệt cũng đơm hoa kết trái.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Han","avatar":""},{"name":"祝緒丹","avatar":""},{"name":"姚弛","avatar":""},{"name":"Hai Ling","avatar":""},{"name":"Ren Shihao","avatar":""},{"name":"Luo Shi Qi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324227);
