INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-cung-gia-tao', 'Hậu Cung Giả Tạo', 'Pseudo Harem', 'https://phimimg.com/upload/vod/20240713-1/c0a9bce5b312138b28631ba3d66df3d5.jpg', 'https://phimimg.com/upload/vod/20240713-1/ed5c2491f53501e3ed7883d0f2712ae4.jpg', '<p>Một hậu cung chỉ có một nữ chính?! Eiji Kitahama, học sinh cuối cấp của câu lạc bộ kịch, người khao khát có được một hậu cung giống như trong bộ truyện tranh, và Rin Nanakura, người không thể không đóng vai những nhân vật khác trước mặt đàn anh Kitahama của mình. Tsundere và Teaser, Clingy và Cool, cũng như Ladylike, càng đóng nhiều nhân vật, cô càng mất kiểm soát cảm xúc dành cho tiền bối của mình. Phải chăng Nanakura đã bộc lộ con người thật của mình với tiền bối, một người có phần ngốc nghếch và cứng đầu?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"早見沙織","avatar":""},{"name":"岡本信彦","avatar":""},{"name":"鳴海まい","avatar":""},{"name":"諏訪部順一","avatar":""},{"name":"遊佐浩二","avatar":""},{"name":"阿保まりあ","avatar":""},{"name":"佐藤未奈子","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324227);
