INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-thanh-hoan', 'Độ Thanh Hoan', 'No One But You', 'https://phimimg.com/upload/vod/20240910-1/000072ca89f645d2b98c36fd05b23faf.jpg', 'https://phimimg.com/upload/vod/20240910-1/3493c8abc514199a67578911c060d0a2.jpg', '<p>Sau khi chị gái chết thảm, Ngu Thanh Hoan được anh rể Giang Mạc Hàn là giám đốc quân đội nhận nuôi, bồi dưỡng thành bà chủ phố đèn đỏ. Ai ngờ cô phát hiện anh rể mà mình luôn yêu quý, kính trọng lại là hung thủ đã giết chị gái cô. Giang Mạc Hàn tưởng rằng bản thân sẽ không bao giờ rung động với người khác, nhưng lại bại trận trước Ngu Thanh Hoan. Sương mù tiêu tan, hai người bất hòa mà vô tình yêu nhau, cũng là định mệnh của đời nhau, nảy sinh mối tình cấm kỵ trong nỗi thù hận. Nhưng muôn vàn hiểu lầm và tổn thương đan xen giữa hai người sẽ đem tới sự áp chế hay ràng buộc?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guan Chang","avatar":""},{"name":"Jin Ze","avatar":""},{"name":"Yuan Ziming","avatar":""},{"name":"Jiaqi Sun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324227);
