INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-thu-hai', 'Màn Thứ Hai', 'The Second Act', 'https://phimimg.com/upload/vod/20240924-1/f5db325dc10b8ed597f8d9356ec1f9b6.jpg', 'https://phimimg.com/upload/vod/20240924-1/961b39f4a5b9d8c55d44e387bce5ebb2.jpg', '<p>Florence muốn giới thiệu David, người đàn ông mà cô yêu điên cuồng, với cha cô là Guillaume. Nhưng David không bị Florence thu hút và muốn ném cô vào vòng tay của người bạn Willy. Bốn nhân vật gặp nhau tại một nhà hàng ở giữa hư không.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Léa Seydoux","avatar":""},{"name":"Louis Garrel","avatar":""},{"name":"Vincent Lindon","avatar":""},{"name":"Raphaël Quenard","avatar":""},{"name":"Manuel Guillot","avatar":""},{"name":"Françoise Gazio","avatar":""},{"name":"Valérie Vogt","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["À notre beau métier","Le Deuxième Acte","敬我们美丽的职业","Второй акт","拍三小電影","Երկրորդ Ակտ"]', 1784690324227);
