INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-tinh-yeu-ket-thuc', 'Nơi Tình Yêu Kết Thúc', 'It Ends With Us', 'https://phimimg.com/upload/vod/20240924-1/8445283fe7ba7ce0b2278df6a8728f0d.jpg', 'https://phimimg.com/upload/vod/20240924-1/b6d55a24afa91e1b66c24b9dd087bbb0.jpg', '<p>Lily Bloom vượt qua tuổi thơ đau thương để bắt đầu cuộc sống mới ở Boston và theo đuổi ước mơ cả đời là mở doanh nghiệp của riêng mình. Cuộc gặp gỡ tình cờ với bác sĩ giải phẫu thần kinh quyến rũ Ryle Kincaid khơi dậy một mối liên hệ mãnh liệt, nhưng khi cả hai yêu nhau sâu đậm, Lily bắt đầu nhìn thấy những khía cạnh của Ryle khiến cô nhớ đến mối quan hệ của cha mẹ cô.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Blake Lively","avatar":""},{"name":"Justin Baldoni","avatar":""},{"name":"Brandon Sklenar","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Hasan Minhaj","avatar":""},{"name":"Amy Morton","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"Isabela Ferrer","avatar":""},{"name":"Alex Neustaedter","avatar":""},{"name":"Robert Clohessy","avatar":""},{"name":"Robyn Lively","avatar":""},{"name":"Megan Robinson","avatar":""},{"name":"Robin S. Walker","avatar":""},{"name":"Emily Baldoni","avatar":""},{"name":"Adam Mondschein","avatar":""},{"name":"Caroline Siegrist","avatar":""},{"name":"Steve","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["以我们结束","Hər şey bizimlə bitəcək","Colleen Hoover''s It Ends With Us","Isto Acaba Aqui","با ما به پایان می‌رسد","以我们告终","到我們為止","It Ends with Us"]', 1784690324227);
