INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-chon-cua-thai-tu-phan-3', 'Lựa Chọn Của Thái Tử (Phần 3)', 'Young Royals (Season 3)', 'https://phimimg.com/upload/vod/20240924-1/d94ed629d11f782766720aafc1af0e63.jpg', 'https://phimimg.com/upload/vod/20240924-1/0350920d7dd23e0e2e758d4731d39dee.jpg', '<p>Hoàng tử Wilhelm thích nghi với cuộc sống mới ở ngôi trường nội trú danh giá Hillerska, nhưng làm theo lời trái tim mách bảo hóa ra lại khó hơn cậu nghĩ nhiều.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Thụy Điển', 0, '[{"name":"Edvin Ryding","avatar":""},{"name":"Omar Rudberg","avatar":""},{"name":"Malte Gårdinger","avatar":""},{"name":"Frida Argento","avatar":""},{"name":"Nikita Uggla","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["JEUNESSE ROYALE","王儲的抉擇","王储的抉择","Jovenes altezas","Jóvenes Altezas","Książęta","Молодые монархи","Genç Asilzadeler","Young Royals"]', 1784690324227);
