INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-den-cung-gio-bien', 'Tình Yêu Đến Cùng Gió Biển', 'Love Comes With The Sea Breeze', 'https://phimimg.com/upload/vod/20240924-1/267d434b9ffa0a094a57d2615320e290.jpg', 'https://phimimg.com/upload/vod/20240924-1/834bfeead5bf08f9c1f2ad0e8a2a9ece.jpg', '<p>“Tình yêu đến cùng gió biển” không chỉ mang vẻ đẹp của cảnh quan thiên nhiên, con người vùng biển Ninh Thuận hiền hòa mà còn có vẻ đẹp muôn màu của tình yêu trai gái, giữa con người và con người với nhau. Nơi đây có Duyên- một cô nàng đau đớn ôm con quay trở về nhà mẹ ruột sau khi ly dị với người chồng ngoại tình. Tại đây, Duyên đã gặp lại Khôi - tình yêu đầu đời thơ mộng của mình . Giờ đây Khôi đã là Quản lý cấp cao của một resort lớn,có rất nhiều người mến mộ và yêu thích, còn Duyên chỉ là thân phận một cô nàng lao công, quá lứa lỡ thì. Liệu tình yêu ngày xưa có đưa hai người đến với nhau một lần nữa, vượt qua bao nhiêu khó khăn, trở ngại ở hiện tại?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thuận Nguyễn","avatar":""},{"name":"Oanh Kiều","avatar":""},{"name":"Karen Nguyễn","avatar":""},{"name":"Lê Lộc","avatar":""},{"name":"Bảo Trung","avatar":""},{"name":"Bùi Tấn Hảo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yuan Zui","原罪2","原罪"]', 1784690324227);
