INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ellie-si-tinh', 'Ellie Si Tình', 'Lovesick Ellie', 'https://phimimg.com/upload/vod/20240920-1/44182036d947c4faf174d43ff1c2f55a.jpg', 'https://phimimg.com/upload/vod/20240920-1/813bb3b0cc3c9a3bc2288f2035640f76.jpg', '<p><span style="text-wrap: nowrap;">Eriko Ichimura có một cuộc sống học sinh bình thường và không được chú ý ở trường trung học của mình. Niềm vui duy nhất của cô là ngắm nhìn nam sinh nổi tiếng Akira Omi và tưởng tượng họ là một cặp. Cô viết ra những suy nghĩ đó trên tài khoản mạng xã hội của mình dưới cái tên Lovesick Ellie. Akira Omi có vẻ là một chàng trai hoàn hảo, có ngoại hình đẹp và tính cách hiền lành.</span></p><p><span style="text-wrap: nowrap;">Một ngày nọ, cô chứng kiến Akira Omi phun ra những ngôn từ thô tục và cô nhận ra anh ta giống như một người hai mặt. Mọi chuyện càng trở nên tồi tệ hơn khi những suy nghĩ viển vông của cô lại bị anh phát hiện. Anh ấy nghĩ rằng cô ấy thật hài hước và anh ấy tiếp cận cô ấy.</span></p><p><br/></p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"宮世琉弥","avatar":""},{"name":"原菜乃華","avatar":""},{"name":"Takuya Nishimura","avatar":""},{"name":"Mizuho Shiromiya","avatar":""},{"name":"Kodai Fujimoto","avatar":""},{"name":"Keito Tsuna","avatar":""},{"name":"小関裕太","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Koiwazurai no Ellie","Koiwazurai no Erii","恋わずらいのエリー"]', 1784690324227);
