INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tau-son-nhan-ky-dam', 'Tẩu Sơn Nhân Kỳ Đàm', 'Strange Tales of Mountain Folk', 'https://phimimg.com/upload/vod/20240919-1/cbb84ef1be77d7ec9dc25bd591b2bd2a.jpg', 'https://phimimg.com/upload/vod/20240919-1/4cac2e746b81fad5633219a756e84f60.jpg', '<p>Bộ tộc người Miêu ở thôn Độc Long trong núi sâu liên tiếp gặp phải các sự cố &quot;gặp ma&quot;, nhiều người bị &quot;ma&quot; hại chết, nên đã mời Lâm Thanh Dương, một người chuyên giải quyết bí ẩn trong núi, đến giúp phá giải. Lâm Thanh Dương dẫn theo đệ tử tiến sâu vào núi, giải quyết nhiều vụ &quot;gặp ma&quot;, cứu được cô gái rơi xuống hang, và vạch trần vụ thảm sát gia đình tộc trưởng mười năm trước. Cuối cùng, ông đã triệt phá toàn bộ băng nhóm sơn tặc ẩn nấp trong thôn Độc Long.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gangyun Sa","avatar":""},{"name":"Luo Yutian","avatar":""},{"name":"李恰","avatar":""},{"name":"田锋","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["走山人奇谈"]', 1784690324227);
