INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tu-tieu-hong-nuong', 'Thiên Tứ Tiểu Hồng Nương', 'The Little Red Matchmaker', 'https://phimimg.com/upload/vod/20240913-1/c6f082c335da0a07e79ad450ae2d9557.jpg', 'https://phimimg.com/upload/vod/20240913-1/7f262d7a528159148ae26c9c465234b3.jpg', '<p>500 năm trước hai sao Hồng Loan và Thiên Hỷ chiến đấu với Cửu Vĩ Hồ. Vì sao Hồng Loan, sao Thiên Hỷ quyết định dùng hết hồn lực nghìn năm của mình phong ấn Cửu Vĩ Hồ. Sao Hồng Loan mất trí nhớ biến thành hồng nương Liễu Oanh Oanh, chinh phục tiên quân Khương Trường Thanh chuyển thế bị hạ Tuyệt Tình Chú. Đúng lúc này, Cửu Vĩ Hồ sắp phá được phong ấn. Tình kiếp ba đời, vận mệnh ngàn năm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Hân Nghi","avatar":""},{"name":"Điền Hử Ninh","avatar":""},{"name":"Châu Thần Giai","avatar":""},{"name":"Thạch Tuyết Tinh","avatar":""},{"name":"Đại Siêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324227);
