INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-tu-tieu-hong-nuong', 'Thiên Tứ Tiểu Hồng Nương', 'The Little Red Matchmaker', 'thiên tứ tiểu hồng nương the little red matchmaker lâm hân nghi điền hử ninh châu thần giai thạch tuyết tinh đại siêu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pham-nhan-ca', 'Phàm Nhân Ca', 'Born To Be The One', 'https://phimimg.com/upload/vod/20240912-1/1d77def5f82e01dd17ad85a64bb52bac.jpg', 'https://phimimg.com/upload/vod/20240912-1/96ac73e543848578493aa2773af55023.jpg', '<p>Câu chuyện xoay quanh ba cặp vợ chồng và người yêu sống tại Bắc Kinh. Một biến cố trong công ty đã khiến cuộc sống trung lưu của Thẩm Lâm và Lão Na trở nên bấp bênh, buộc họ phải tìm cách tự cứu mình, liên tục xoay chuyển trong công việc và sự nghiệp. Đồng thời, những người lao động sống hết mình như Lý Hiểu Duyệt, thanh niên Phật hệ trong cơ chế nhà nước là Thẩm Lỗi, lập trình viên chìm trong cạnh tranh là Na Bằng, cùng với Tạ Mỹ Lam, người đang gặp khó khăn trong hôn nhân với Thẩm Lỗi, cũng đều đang chủ động hoặc bị động đối mặt với những thử thách trong cuộc sống của họ.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"殷桃","avatar":""},{"name":"王驍","avatar":""},{"name":"章若楠","avatar":""},{"name":"Qin Junjie","avatar":""},{"name":"张哲华","avatar":""},{"name":"陳昊宇","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324227);
