INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nho-ma-thoi', 'Chuyện Nhỏ Mà Thôi', 'Not A Big Deal', 'https://phimimg.com/upload/vod/20240908-1/eea10500b813be6cb9a5b20fb5d7815e.jpg', 'https://phimimg.com/upload/vod/20240908-1/a6dbd11c5aa2c6989fd67fb81c18bc42.jpg', '<p>Vào giữa những năm 80 của thế kỷ trước, Vương Tiểu Thanh và Đỗ Mãn Đường là thanh mai trúc mã, nhưng vì mẹ của Vương Tiểu Thanh phản đối mà Trương Trạch Trung có cơ hội xen vào. Tuy nhiên Trương Trạch Trung lại kết hôn với con gái của hiệu phó vì muốn thăng tiến sự nghiệp, Đỗ Mãn Đường lại về với Vương Tiểu Thanh. Trương Trạch Trung kết hôn vì tham vọng quyền quý, bị gia đình vợ khinh thường, sự nghiệp liên tục thất bại, chuẩn bị xuôi Nam để khởi nghiệp, nhưng vì không có vốn khởi nghiệp nên anh ta đành phải bán nhà. Anh ta bịa ra tin đồn có bảo vật chôn dưới nhà nhằm nâng giá nhà. Giá nhà tăng vọt khiến anh ta đánh mất bản thân, tự tay đào bảo vật, kết quả suýt làm sập nhà, cuối cùng bỏ đi trong thất bại. Thời gian trôi qua, 30 năm sau, Đỗ Mãn Đường và Trương Trạch Trung đều trở thành quản lý khu phố. Trương Trạch Trung lập kế hoạch kiếm lợi từ quá trình thương mại hóa các con hẻm nhưng lại vấp phải sự ngăn cản kịch liệt của Đỗ Mãn Đường.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Bing","avatar":""},{"name":"Yu Qian","avatar":""},{"name":"Zhu Yuanyuan","avatar":""},{"name":"Xu Yue","avatar":""},{"name":"Sheng Guansen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324227);
