INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-leha', 'Giải Cứu Leha', 'Leha', 'https://phimimg.com/upload/vod/20240918-1/7f594914e23232d7214ec4a39398d9e7.jpg', 'https://phimimg.com/upload/vod/20240918-1/4a67dc93136f42c9c3105d368ca7282d.jpg', '<p>Leha và bạn trai Zaman làm việc trong nhà máy công nghiệp địa phương. Cuộc sống của họ đang gặp nguy hiểm khi họ tìm thấy một hồ sơ ghi lại các công việc bất hợp pháp của Dato Murad, chủ sở hữu của nhà máy.</p>', 'Full', 1, 'single', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Khir Rahman","avatar":""},{"name":"Kodi Rasheed","avatar":""},{"name":"Cat Farish","avatar":""},{"name":"Silfeny Osman","avatar":""},{"name":"D''boy Hamdan","avatar":""},{"name":"Ali Puteh","avatar":""},{"name":"Den Wahab","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Penculikan Leha Lawa","Leha"]', 1784690324228);
