INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giet-toi-di-hoi-tinh-yeu', 'Giết tôi đi, hỡi tình yêu', 'Kill Me If You Dare', 'https://phimimg.com/upload/vod/20240918-1/3a67b5bb71fe36c9adb20b3abeedfb59.jpg', 'https://phimimg.com/upload/vod/20240918-1/59ef74089f77c6b73a4b11bca535b612.jpg', '<p>Một tờ vé số trúng thưởng gây ra những hậu quả nặng nề cho một cặp vợ chồng khi họ bắt đầu ấp ủ kế hoạch giết lẫn nhau để giành lấy tiền thưởng.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Ba Lan', 0, '[{"name":"Weronika Książkiewicz","avatar":""},{"name":"Mateusz Banasiuk","avatar":""},{"name":"Agnieszka Więdłocha","avatar":""},{"name":"Piotr Rogucki","avatar":""},{"name":"Mikołaj Roznerski","avatar":""},{"name":"Paulina Gałązka","avatar":""},{"name":"Mirosław Baka","avatar":""},{"name":"Dorota Pomykała","avatar":""},{"name":"Piotr Gąsowski","avatar":""},{"name":"Małgorzata Mikołajczak","avatar":""},{"name":"Piotr Nowak","avatar":""},{"name":"Weronika Warchoł","avatar":""},{"name":"Milena Lisiecka","avatar":""},{"name":"Bartłomiej Firlet","avatar":""},{"name":"Bar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Kill Me If You Dare","Tue-moi si tu l''oses","جرات داری منو بکش","Giết tôi đi, hỡi tình yêu","Zabij mnie, kochanie","够胆你就杀了我","打喊杀还是爱","有种你就杀了我"]', 1784690324228);
