INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-an-bi-van-luc-nhiep-an-nuong', 'Trường An Bí Văn Lục: Nhiếp Ẩn Nương', 'A Love Story Of Assassin', 'https://phimimg.com/upload/vod/20240917-1/e99fff717f80bf98051546193ed5300b.jpg', 'https://phimimg.com/upload/vod/20240917-1/7c8663f53793be34581f879eec384689.jpg', '<p>Trong giang hồ có một môn phái bí ẩn tên là Vụ Ẩn. Nhiếp Ẩn Nương là người có võ công đứng đầu trong Vụ Ẩn. Sư phụ Diệu Huệ Thần Ni giao cho Nhiếp Ẩn Nương một nhiệm vụ, đó là ám sát thương nhân giàu có Lưu Trường Nghĩa. Nhiếp Ẩn Nương dễ dàng hoàn thành nhiệm vụ, nhưng lại bị cuốn vào một âm mưu và qua đó gặp gỡ Thiếu khanh của Đại lý tự là Tư Mã Sinh An. Trong quá trình điều tra vụ án, hai người dần nảy sinh tình cảm và cùng nhau tìm ra chân tướng đằng sau âm mưu này.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"徐垚","avatar":""},{"name":"Jiang Kaitong","avatar":""},{"name":"孙晶晶","avatar":""},{"name":"孙佩琪","avatar":""},{"name":"王鹰","avatar":""},{"name":"鲍嘉诚","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Chang An Mi Wen Lu Zhi Nie Yi Niang","Secrets of Chang''an: Story of Nie Yinniang","长安秘闻录之聂隐娘"]', 1784690324228);
