INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-thi-tan-truyen', 'Tây Thi Tân Truyện', 'New Biography of Xi Shi', 'https://phimimg.com/upload/vod/20240917-1/7468ebf8b6961a2a694dea68cd27e036.jpg', 'https://phimimg.com/upload/vod/20240917-1/88e91f6ef4e5b7256bd823e6c0d41031.jpg', '<p>Bộ phim Tây Thi Tân Truyện do Công ty Văn hóa Điện ảnh Giang Huệ Vô Tích và Công ty Phát triển Du lịch Văn hóa Tòng Thụy Khu Huyện sản xuất, do Đới Nghệ Lâm đạo diễn, kịch bản của tác giả gốc Thẩm Nhã Cầm (Nhất Điệp), với sự tham gia diễn xuất của Tào Hi Nguyệt, Ứng Hạo Minh, La Lập Quần, Triệu Anh Tử, Sa Sa, Lý Uyển Trinh, Lưu Tích Minh, Dương Thanh Văn, Cố Ất Lượng, Thẩm Tuyết Vỹ, Đổng Ngạn Lâm, Lưu Uy Châu, Hàn Thu Đình, Hứa Nhược Đồng, Vương Kim Hồng, An Hạ, Lưu Liễu Hi và nhiều diễn viên khác. Bộ phim sẽ ra rạp và chiếu trực tuyến cùng lúc vào ngày 15 tháng 9 năm 2024.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Xiyue","avatar":""},{"name":"Ying Haoming","avatar":""},{"name":"Luo Liqun","avatar":""},{"name":"Zhao Yingzi","avatar":""},{"name":"沙莎","avatar":""},{"name":"韩秋婷","avatar":""},{"name":"李苑祯","avatar":""},{"name":"Canti Lau Sek-Ming","avatar":""},{"name":"沈雪炜","avatar":""},{"name":"董彦麟","avatar":""},{"name":"Yang Qingwen","avatar":""},{"name":"王志萍","avatar":""},{"name":"Liu Weizhou","avatar":""},{"name":"Ao Lei","avatar":""},{"name":"许若彤","avatar":""},{"name":"顾乙亮","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["New Biography of Xi Shi","西施新传"]', 1784690324228);
