INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tich', 'Mất Tích', 'Missing', 'https://phimimg.com/upload/vod/20240917-1/e92a76da9b453cf52424ef3dbe5e9baa.jpg', 'https://phimimg.com/upload/vod/20240917-1/d7bc9be6f3b7bf91ac548141da3d2923.jpg', '<p>Một cô bé mất tích khi đang đi bộ trên đường. Ba tháng trôi qua mà không có bất kỳ manh mối nào về tung tích của cô. Khi con gái mất tích, người mẹ Saori đã đi xem buổi biểu diễn trực tiếp của thần tượng yêu thích. Thông tin này và những tin đồn về Saori bắt đầu lan truyền trên mạng. Những lời đồn về cô ngày càng trở nên tồi tệ hơn theo thời gian. Hơn nữa, Saori cảm thấy chồng mình ngày càng lạnh nhạt. Điều này khiến họ cãi vã không ngừng. Khi thời gian trôi qua, sự chú ý của các phương tiện truyền thông lớn dần phai nhạt về vụ mất tích của cô bé, chỉ có một đài truyền hình địa phương vẫn tiếp tục theo dõi vụ việc. Nhưng rồi...</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"石原さとみ","avatar":""},{"name":"青木崇高","avatar":""},{"name":"森優作","avatar":""},{"name":"Tsugumi Arita","avatar":""},{"name":"小野花梨","avatar":""},{"name":"小松和重","avatar":""},{"name":"Gaku Hosokawa","avatar":""},{"name":"Shinsuke Kato","avatar":""},{"name":"Naohiro Yamamoto","avatar":""},{"name":"柳憂怜","avatar":""},{"name":"美保純","avatar":""},{"name":"中村倫也","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["失踪","我的女兒不見了","Missing","消失的女儿","Misshingu","ミッシング"]', 1784690324228);
