INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-truy-duoi-bi-an', 'Cuộc Truy Đuổi Bí Ẩn', 'New Life', 'https://phimimg.com/upload/vod/20240917-1/3532fd37bf6949fc8262d10674bceb62.jpg', 'https://phimimg.com/upload/vod/20240917-1/bb5b2fab519099309b98a4086a0866b5.jpg', '<p>“New Life” (2023) là một bộ phim kinh dị và ly kỳ do John Rosman đạo diễn. Phim kể về một người phụ nữ bí ẩn đang chạy trốn và một người sửa chữa tài ba được giao nhiệm vụ bắt cô ấy. Câu chuyện của họ liên kết chặt chẽ khi cuộc truy đuổi trở nên căng thẳng đến mức tận cùng</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sonya Walger","avatar":""},{"name":"Hayley Erin","avatar":""},{"name":"Tony Amendola","avatar":""},{"name":"Ayanna Berkshire","avatar":""},{"name":"Jeb Berrier","avatar":""},{"name":"Blaine Palmer","avatar":""},{"name":"Betty Moyer","avatar":""},{"name":"David Loftus","avatar":""},{"name":"Nick George","avatar":""},{"name":"Cyndi Rhoads","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324228);
