INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-tra-tan', 'Mồ Tra Tấn', 'Grave Torture', 'https://phimimg.com/upload/vod/20240916-1/b7d3e35838a2aa5efc1f69198b450a20.jpg', 'https://phimimg.com/upload/vod/20240916-1/4ad680b62b659424f0219b77d219223e.jpg', '<p>Sau khi cha mẹ Sita thiệt mạng bất ngờ trong một vụ đánh bom liều chết, chỉ vì câu chuyện truyền miệng về Mồ Tra Tấn. Đau đớn và phẫn nộ, Sita quyết dành cả đời mình để chứng minh rằng Mồ Tra Tấn không tồn tại. Cho đến khi Sita quyết định ngủ trong ngôi mộ của một xác chết, sự thật kinh hoàng hé lộ, tất cả vượt xa sự hiểu biết của loài người...</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Faradina Mufti","avatar":""},{"name":"Reza Rahadian","avatar":""},{"name":"Widuri Puteri","avatar":""},{"name":"Muzakki Ramdhan","avatar":""},{"name":"Slamet Rahardjo","avatar":""},{"name":"Niniek L. Karim","avatar":""},{"name":"Christine Hakim","avatar":""},{"name":"Arswendi Nasution","avatar":""},{"name":"Runny Rudiyanti","avatar":""},{"name":"Egy Fedly","avatar":""},{"name":"Fachry Albar","avatar":""},{"name":"Happy Salma","avatar":""},{"name":"Jajang C. Noer","avatar":""},{"name":"Putri Ayudya","avatar":""},{"name":"Djenar Maesa Ayu","avatar":""},{"name":"Haydar Salishz","avatar":""},{"name":"Ahm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
