INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tro-ve-mai-am', 'Tình Yêu Trở Về Mái Ấm', 'Romance In The House', 'https://phimimg.com/upload/vod/20240818-1/123ac64a5150d0ebbab22827ca665d91.jpg', 'https://phimimg.com/upload/vod/20240818-1/81e0e12444e777c3c4305cfbf890f138.jpg', '<p>Sau khi việc làm ăn sụp đổ, người đàn ông nọ biến mất khỏi gia đình trong 11 năm. Nhưng khi anh trở lại với tư cách người chủ nhà giàu có của họ, cuộc đoàn tụ đầy hỗn loạn xảy ra.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"지진희","avatar":""},{"name":"김지수","avatar":""},{"name":"손나은","avatar":""},{"name":"민호","avatar":""},{"name":"Yoon San-ha","avatar":""},{"name":"김도현","avatar":""},{"name":"김기천","avatar":""},{"name":"정웅인","avatar":""},{"name":"김영재","avatar":""},{"name":"박철민","avatar":""},{"name":"정석용","avatar":""},{"name":"황정민","avatar":""},{"name":"황보라","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
