INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-gau-ngot-ngao', 'Đầu Gấu Ngọt Ngào', 'My Sweet Mobster', 'https://phimimg.com/upload/vod/20240916-1/00dc56f108e00bf437bc1edf92bfe6db.jpg', 'https://phimimg.com/upload/vod/20240916-1/b2c6eb7372fc477cd163dbe43804a539.jpg', '<p>Sự phấn khích bất ngờ tạo nên mối tình lãng mạn giữa Ji-hwan, một cựu thành viên băng đảng to lớn, người đã xóa bỏ quá khứ đen tối của mình và Eun-ha, một người phụ nữ nhỏ bé chơi đùa với trẻ em vì công việc của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2024, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"엄태구","avatar":""},{"name":"한선화","avatar":""},{"name":"권율","avatar":""},{"name":"Kim Hyun-jin","avatar":""},{"name":"박재찬","avatar":""},{"name":"Moon Dong-hyeok","avatar":""},{"name":"양현민","avatar":""},{"name":"이유준","avatar":""},{"name":"Kim Hyun-kyu","avatar":""},{"name":"문지인","avatar":""},{"name":"이병준","avatar":""},{"name":"Song Seo-rin","avatar":""},{"name":"임철수","avatar":""},{"name":"Yoon Jin-seong","avatar":""},{"name":"Kim Hyun-joon","avatar":""},{"name":"박철민","avatar":""},{"name":"김뢰하","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324228);
