INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-gau-ngot-ngao', 'Đầu Gấu Ngọt Ngào', 'My Sweet Mobster', 'đầu gấu ngọt ngào my sweet mobster 엄태구 한선화 권율 kim hyun-jin 박재찬 moon dong-hyeok 양현민 이유준 kim hyun-kyu 문지인 이병준 song seo-rin 임철수 yoon jin-seong kim hyun-joon 박철민 김뢰하 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cong-so', 'Cuộc Chiến Công Sở', 'The Auditors', 'https://phimimg.com/upload/vod/20240727-1/806f956bf997d6c5332c963a6806d67e.jpg', 'https://phimimg.com/upload/vod/20240727-1/84bef77189bf1a6219a8352cd863ce1f.jpg', '<p>Shin Cha Il bắt đầu làm trưởng nhóm kiểm toán tại JU Construction, nơi nạn tham nhũng tràn lan. Shin Cha Il không có niềm tin vào người khác. Anh ấy có phong thái lạnh lùng và thực hiện công việc của mình với khả năng phán đoán nhạy bén và hành động quyết đoán. Nhóm kiểm toán còn có nhân viên tân binh Gu Han Soo. Ban đầu anh nộp đơn vào nhóm kiểm toán như một bước đệm để được chuyển sang chi nhánh Florida của công ty mình, nhưng kế hoạch của anh không hề dễ dàng vì Shin Cha Il. Không giống như sếp của mình, Gu Han Soo là một người tốt bụng và có trái tim ấm áp. Làm việc với Shin Cha Il, Gu Han Soo trưởng thành với tư cách là thành viên nhóm kiểm toán. Trong khi đó, Hwang Dae Woong là phó chủ tịch của JU Construction, đồng thời là con trai thứ ba của người sáng lập công ty. Tham vọng của anh là trở thành chủ tịch công ty bằng cách đánh bại hai người anh trai của mình để giành lấy vị trí này. Yoon Seo Jin cũng là nhân viên tân binh trong nhóm kiểm toán tại JU Construction. Cô ấy là người theo chủ nghĩa cá nhân và luôn hướng tới thành công. Cô ấy có tính cách hoàn toàn trái ngược của Goo Han Soo. Cô cũng biết Phó chủ tịch Hwang Dae Woong từ khi còn nhỏ nhưng họ giả vờ như không biết nhau tại nơi làm việc.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"신하균","avatar":""},{"name":"이정하","avatar":""},{"name":"진구","avatar":""},{"name":"조아람","avatar":""},{"name":"정문성","avatar":""},{"name":"이도엽","avatar":""},{"name":"김홍파","avatar":""},{"name":"백현진","avatar":""},{"name":"정동환","avatar":""},{"name":"박수영","avatar":""},{"name":"우미화","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324228);
