INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-xac', 'Tắm Xác', 'The Corpse Washer', 'https://phimimg.com/upload/vod/20240910-1/57ee009a0c22972a119a3e7c3b9590df.jpg', 'https://phimimg.com/upload/vod/20240910-1/bb0bc0badcc6ea85632ec7960d09bde8.jpg', '<p>Sau khi mẹ cô đột ngột qua đời, một người tắm xác ở một thị trấn nhỏ quyết định đi tìm sự thật kinh hoàng đằng sau hàng loạt cái chết bí ẩn.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Aghniny Haque","avatar":""},{"name":"Djenar Maesa Ayu","avatar":""},{"name":"Ibrahim Risyad","avatar":""},{"name":"Ruth Marini","avatar":""},{"name":"Vonny Anggraini","avatar":""},{"name":"Mian Tiara","avatar":""},{"name":"Amara Sophie","avatar":""},{"name":"Deni Saputra","avatar":""},{"name":"Riafinola Ifani Sari","avatar":""},{"name":"M. N. Qomaruddin","avatar":""},{"name":"Nelly Sukma","avatar":""},{"name":"Messi Gusti","avatar":""},{"name":"Aji Santosa","avatar":""},{"name":"Hifdzi Khoir","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
