INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-bao-cua-quy', 'Điềm Báo Của Quỷ', 'The First Omen', 'https://phimimg.com/upload/vod/20240529-1/ab90cb9bd03024b5c599703d0fc37e51.jpg', 'https://phimimg.com/upload/vod/20240529-1/d7893a2772d243c0c6dd9a93133c5878.jpg', '<p>Khi một cô gái người Mỹ được đưa đến Rome để bắt đầu phụng sự Giáo Hội, cô đã phát hiện ra thế lực hắc ám khiến cô hoài nghi về đức tin của chính mình, đồng thời hé lộ một âm mưu kinh hoàng nhằm tái sinh linh hồn ác quỷ đầu thai đến nhân thế.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Nell Tiger Free","avatar":""},{"name":"Ralph Ineson","avatar":""},{"name":"Sônia Braga","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"María Caballero","avatar":""},{"name":"Nicole Sorace","avatar":""},{"name":"Tawfeek Barhom","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Ishtar Currie Wilson","avatar":""},{"name":"Andrea Arcangeli","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324228);
