INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-tung', 'Phục Tùng', 'Subservience', 'https://phimimg.com/upload/vod/20240916-1/a8b06c15d141cd1e171667ac5780e1ee.jpg', 'https://phimimg.com/upload/vod/20240916-1/242c0cdacfae36e6e810645dcb6e6e2f.jpg', '<p>Khi vợ bị bệnh, một người cha đang gặp khó khăn mang về nhà một AI sống động như thật—chỉ để nhận được sự trợ giúp mới tự nhận thức của mình muốn có mọi thứ mà gia đình mới của cô có thể cung cấp, chẳng hạn như tình cảm của người chủ. Và cô ấy sẽ giết người để có được nó.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Megan Fox","avatar":""},{"name":"Michele Morrone","avatar":""},{"name":"Madeline Zima","avatar":""},{"name":"Matilda Firth","avatar":""},{"name":"Andrew Whipp","avatar":""},{"name":"Jude Greenstein","avatar":""},{"name":"Atanas Srebrev","avatar":""},{"name":"Kate Nichols","avatar":""},{"name":"Trevor Van Uden","avatar":""},{"name":"Euan Macnaughton","avatar":""},{"name":"Max Kraus","avatar":""},{"name":"J.R. Esposito","avatar":""},{"name":"Doroteya Toleva","avatar":""},{"name":"Rosmary Yaneva","avatar":""},{"name":"Kexin Wang","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324228);
