INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-nu-phi-cong', 'Chàng Nữ Phi Công', 'Pilot', 'https://phimimg.com/upload/vod/20240915-1/2ff4c14f2c758031257c8730e6c1a012.jpg', 'https://phimimg.com/upload/vod/20240915-1/dcb2ae3eae8617e6557b11532d82c6e9.jpg', '<p>Từ đỉnh cao danh vọng, hào quang cơ trưởng của HAN Jung-woo (CHO Jung-seok) tắt ngỏm khi dính vào những thị phi công sở. Đứng trước thị trường tuyển dụng khó khăn, HAN Jung-woo quyết định &quot;nhập vai&quot; em gái, ứng tuyển &quot;nữ phi công&quot; với hi vọng lấy lại những gì đã mất!</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Jo Jung-suk","avatar":""},{"name":"Lee Ju-myoung","avatar":""},{"name":"Han Sun-hwa","avatar":""},{"name":"Shin Seung-ho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
