INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-cua-than-tinh-yeu', 'Sứ Mệnh Của Thần Tình Yêu', 'Misi Cinta Cik Cupid', 'https://phimimg.com/upload/vod/20240730-1/0b2999337fdd79fe04e0d5b0d50aaf1d.jpg', 'https://phimimg.com/upload/vod/20240730-1/969985189479fbed093a2cb246af4c55.jpg', '<p>Một cô gái vụng về với chiếc ô, một thợ máy tại xưởng tháo dỡ xe và một tay đua xe mới vào nghề thường xuyên gặp sự cố đã cùng nhau thực hiện ước mơ trở thành đội đua xe máy bất khả chiến bại. Dần dần, họ trở nên nổi tiếng trong các cuộc đua vòng nhỏ, cho đến khi họ gặp được thần tượng đua xe huyền thoại của mình, người mang đến cho họ cơ hội duy nhất trong đời! Họ bắt đầu huấn luyện để giành một vị trí trong đội của thần tượng, tham gia một cuộc đua bền bỉ nguy hiểm để giành tiền mặt và sự nổi tiếng trong sự nghiệp đua xe. Điều họ không biết là những khúc ngoặt của số phận đã vượt xa dự đoán, và họ bị cuốn vào một cuộc đua với các giao dịch đen tối.</p>', 'Tập 16', 16, 'series', 'ongoing', 20, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Fatin Afeefa","avatar":""},{"name":"Hafidz Rosdhi","avatar":""},{"name":"Chacha Maembong","avatar":""},{"name":"Hadizul Kamal","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324228);
