INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chua-tung-sai', 'Người Chưa Từng Sai', 'Club Friday Season 16: Never Wrong', 'https://phimimg.com/upload/vod/20240810-1/5e9c7737ad9db207b33878c2dc971059.jpg', 'https://phimimg.com/upload/vod/20240810-1/210af92dbc253e707f645af6499dadfc.jpg', '<p>Người Chưa Từng Sai là câu chuyện về một người phụ nữ ngày càng lún sâu vào con đường tội lỗi nhưng không bao giờ chịu thừa nhận sai lầm của bản thân. Mimi vốn luôn nghĩ rằng cô có một tình yêu hoàn hảo với một người bạn trai vô cùng lý tưởng. Và rồi một ngày nọ cô phát hiện bạn trai của mình thực chất là người đã có gia đình. Thay vì chia tay kẻ lừa dối, Mimi lại tiếp tục mối quan hệ sai trái và cương quyết tranh giành những thứ mà cô cho rằng phải thuộc về mình.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Fon Sananthachat Thanapatpisal","avatar":""},{"name":"Up Poompat Iam-samang","avatar":""},{"name":"Fah Yongwaree Anilbol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
