INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-woo', 'Nữ Hoàng Woo', 'Queen Woo', 'https://phimimg.com/upload/vod/20240829-1/6bf1f7140786f7ee5522844194aa3b29.jpg', 'https://phimimg.com/upload/vod/20240829-1/2c58899d51372fac92ae5c82979bb725.jpg', '<p>Sau khi nhà vua qua đời ở Goguryeo, một cuộc chiến khốc liệt nổ ra giữa các bộ tộc. Nữ hoàng Woo, người ngay lập tức trở thành mục tiêu của các hoàng tử và năm bộ tộc tranh giành ngai vàng, đấu tranh để trao vương miện cho một vị vua mới trong vòng 24 giờ. Liệu Nữ hoàng Woo có thể vượt qua được những ràng buộc về giới tính và thời đại để tự tạo ra số phận của mình không?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"전종서","avatar":""},{"name":"김무열","avatar":""},{"name":"지창욱","avatar":""},{"name":"정유미","avatar":""},{"name":"이수혁","avatar":""},{"name":"박지환","avatar":""},{"name":"전배수","avatar":""},{"name":"조한철","avatar":""},{"name":"강영석","avatar":""},{"name":"정재광","avatar":""},{"name":"송재림","avatar":""},{"name":"박보경","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324228);
