INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-thuan-gio-hoa', 'Mưa Thuận Gió Hoà', 'Sowers Of Hope', 'https://phimimg.com/upload/vod/20240908-1/080ce19b4daa9be5b967438f826f1b0f.jpg', 'https://phimimg.com/upload/vod/20240908-1/3b073c3c2c5135c9120d9f31b581ab89.jpg', '<p>Năm 2002, An Nhan vừa tốt nghiệp và được phân về dạy học tại trường trung học Hòa Bình thuộc huyện Trường Trị. Là người sinh ra và lớn lên ở thành phố nên ban đầu cô khó thích nghi với môi trường và quan niệm giáo dục của trường học nông thôn. Nhưng sau khi tiếp xúc với học sinh và tìm hiểu sâu hơn về gia đình, An Nhan dần nhận ra tầm quan trọng của giáo dục nông thôn và cảm nhận được giá trị của việc &quot;được cần đến&quot;. Dưới sự khích lệ của hiệu trưởng cũ là Vu Điền và hiệu trưởng đương nhiệm là Phù Thắng Trị, cô đã thấu hiểu và tiếp nối triết lý giáo dục &quot;giữ gìn&quot; và &quot;ấp ủ&quot;, trở thành một giáo viên xuất sắc nổi tiếng gần xa. Năm 2012, An Nhan được bổ nhiệm làm phó hiệu trưởng phụ trách việc hậu cần của trường trung học Hòa Bình, thúc đẩy chương trình &quot;Bữa trưa dinh dưỡng&quot; đi vào thực hiện. Năm 2016, An Nhan được bổ nhiệm làm hiệu trưởng trường học di dân tái định cư, giúp đỡ người nghèo.</p>', 'Tập 32', 32, 'series', 'ongoing', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"佟麗婭","avatar":""},{"name":"楊玏","avatar":""},{"name":"Johnny Zhang","avatar":""},{"name":"刘佩琦","avatar":""},{"name":"Kang Aishi","avatar":""},{"name":"Cao Jun","avatar":""},{"name":"徐洋","avatar":""},{"name":"An Yuexi","avatar":""},{"name":"Ma Bo","avatar":""},{"name":"Xinying Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
