INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-nghe-am-thanh-mat-troi', 'Lắng Nghe Âm Thanh Mặt Trời', 'I Hear the Sunspot', 'https://phimimg.com/upload/vod/20240731-1/ba1970d116d8a43d8850b1869545c9ed.jpg', 'https://phimimg.com/upload/vod/20240731-1/9b9eac9ee72f43c97911683a6498ccbd.jpg', '<p>Do bị khiếm thính, Sugihara Kohei thường bị hiểu lầm và gặp khó khăn trong việc hòa nhập với cuộc sống ở trường; như vậy, anh ấy giữ khoảng cách. Mọi chuyện thay đổi khi anh gặp Sagawa Taichi thẳng thắn và vui vẻ. Anh an ủi Kohei và đảm bảo với anh rằng việc mất thính giác không phải lỗi của anh. Những lời nói tử tế của Taichi đã cắt đứt cơ chế phòng thủ thông thường của Kōhei và mở rộng trái tim anh. Bây giờ, họ hơn mức bạn bè và ít hơn tình yêu. Dù vậy, mối quan hệ này đã thay đổi Kohei mãi mãi.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Motoki Nakazawa","avatar":""},{"name":"Toranosuke Kobayashi","avatar":""},{"name":"Takuma Usa","avatar":""},{"name":"Omi Natsuki","avatar":""},{"name":"西田尚美","avatar":""},{"name":"Denden","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324228);
