INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-su-manh-nhat-cua-quan-doi-ma-vuong-hoa-ra-lai-la-con-nguoi', 'Pháp Sư Mạnh Nhất Của Quân Đội Ma Vương Hóa Ra Lại Là Con Người', 'The Strongest Magician in the Demon Lord''s Army Was a Human', 'https://phimimg.com/upload/vod/20240713-1/ed7ba1173ce18300142dba1e77de715f.jpg', 'https://phimimg.com/upload/vod/20240713-1/3ef702d967d1b66403c1a7fe18204ad5.jpg', '<p>Tài năng và mạnh mẽ, Ike được mệnh danh là &quot;Pháp sư mạnh nhất của quân đội Ma vương&quot;. Ông sở hữu phép thuật vô song, có thể một mình chiếm được pháo đài, làm nên chiến công vang dội của đội quân Ma vương trước loài người. Tuy nhiên, ẩn sau chiến tích đó lại là bí mật động trời: Ike thực chất là một con người! Che giấu thân phận thật, ông sống giữa quân đoàn hung ác và phải luôn cảnh giác, đồng thời âm thầm lên kế hoạch cho tương lai.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"伊藤静","avatar":""},{"name":"石見舞菜香","avatar":""},{"name":"立花日菜","avatar":""},{"name":"福山潤","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324228);
