INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-tan-an-toan-khoi-the-ky-21', 'Sơ tán an toàn khỏi Thế kỷ 21', 'Escape from the 21st Century', 'https://phimimg.com/upload/vod/20240913-1/2565b59f9e0d63f7a238a270355c1192.jpg', 'https://phimimg.com/upload/vod/20240913-1/54c6e8dfee431d9f1a3f360a3bc110dd.jpg', '<p>Trên hành tinh K mà không ai trên Trái Đất biết đến, ba thiếu niên được số phận lựa chọn có thể du hành tới tương lai hai mươi năm sau chỉ bằng cách hắt hơi. Đối mặt với âm mưu hủy diệt thế giới, họ chẳng có gì ngoài sự ngốc nghếch rõ ràng và sức mạnh chiến đấu yếu ớt. Làm sao họ có thể hóa thân thành anh hùng để chống lại tên ác nhân siêu ác đang có ý định hủy diệt thế giới?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"张若昀","avatar":""},{"name":"鍾楚曦","avatar":""},{"name":"Song Yang","avatar":""},{"name":"吴晓亮","avatar":""},{"name":"朱顏曼滋","avatar":""},{"name":"Leon Lee","avatar":""},{"name":"Wen Zhengrong","avatar":""},{"name":"Shi Liang","avatar":""},{"name":"Yichen Chen","avatar":""},{"name":"李卓钊","avatar":""},{"name":"Qixuan Kang","avatar":""},{"name":"Ma Fanding","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324228);
