INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-trong-bong-toi', 'Sứ Mệnh Trong Bóng Tối', 'Darkness Of Man', 'https://phimimg.com/upload/vod/20240530-1/50c595f1c711ec8ea3d431b1319df49f.jpg', 'https://phimimg.com/upload/vod/20240530-1/09f63027282e77e31964bf3b81a063a3.jpg', '<p>Russell Hatch, một đặc vụ của Interpol, người đảm nhận vai trò là người cha của Jayden, con trai của một người cung cấp thông tin bị giết trong một cuộc đột kích thường lệ. Nhiều năm sau, Hatch thấy mình phải bảo vệ Jayden và ông nội của anh khỏi một nhóm băng đảng tàn nhẫn. -ra chiến tranh trên sân, không dừng lại ở việc bảo vệ Jayden và chống lại bất cứ ai cản đường anh ta.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Emerson Min","avatar":""},{"name":"Kristanna Loken","avatar":""},{"name":"Peter Jae","avatar":""},{"name":"Sticky Fingaz","avatar":""},{"name":"Spencer Breslin","avatar":""},{"name":"Ji Yong Lee","avatar":""},{"name":"Andrey Ivchenko","avatar":""},{"name":"Zack Ward","avatar":""},{"name":"Shannen Doherty","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324228);
