INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-bi-an', 'Cô Gái Bí Ẩn', 'Hiraya', 'https://phimimg.com/upload/vod/20240819-1/d4a84acd648e165c230ce8ed9e8d9b97.jpg', 'https://phimimg.com/upload/vod/20240819-1/aa61773956bdb3c0b6ab1039f5b84cf1.jpg', '<p>Hiraya là một người phụ nữ bí ẩn được tìm thấy bất tỉnh trên sông. Cô tỉnh dậy không nhớ bất cứ điều gì và không thể nói được. Người dân thị trấn lợi dụng Hiraya, nhưng có vẻ như những người làm vậy luôn gặp bất hạnh.</p>', 'Full', 1, 'single', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Rica Gonzales","avatar":""},{"name":"Denise Esteban","avatar":""},{"name":"Quinn Carrillo","avatar":""},{"name":"Itan Magnaye","avatar":""},{"name":"Nathan Rojas","avatar":""},{"name":"Pantene Palanca","avatar":""},{"name":"Tabs Sumulong","avatar":""},{"name":"Jhai Slvr","avatar":""},{"name":"JD Aguas","avatar":""},{"name":"Elmo Elarmo Jr.","avatar":""},{"name":"Alvaro Oteyza","avatar":""},{"name":"VJ Vera","avatar":""},{"name":"Mark Grabador","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '[]', 1784690324228);
