INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-truong-sinh-tu', 'Đấu Trường Sinh Tử', 'Kung Fu Games', 'https://phimimg.com/upload/vod/20240913-1/80e00d4030d2f05749e865c90af17241.jpg', 'https://phimimg.com/upload/vod/20240913-1/77e5ae0a3ab3d7bd4205266a719a2999.jpg', '<p>Khi ánh đèn vụt tắt, trò chơi mới bắt đầu. Bị săn đuổi, bị phản bội, họ phải chiến đấu để giành lấy sự sống. Nhưng kẻ thù thực sự là ai? Và lối thoát nằm ở đâu? Bị giam cầm trong một trò chơi võ thuật tàn bạo do một kẻ giàu có bệnh hoạn tạo ra, những võ sĩ khét tiếng phải đối mặt với những trận chiến sống còn. Không lối thoát, không vũ khí, chỉ có kỹ năng chiến đấu để sinh tồn trong cuộc đấu sinh tử đẫm máu.</p>', 'Full', 1, 'single', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Strange","avatar":""},{"name":"Caitlin Dechelle","avatar":""},{"name":"Jade Xu","avatar":""},{"name":"Jose Manuel","avatar":""},{"name":"Matt Goodwin","avatar":""},{"name":"Lathrop Walker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324228);
