INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-hiep-khach-hoang-da', 'Ngũ Hiệp Khách Hoang Dã', 'Welcome To My Side', 'https://phimimg.com/upload/vod/20240913-1/d94c23d63d777b0b6cb84ef288f43221.jpg', 'https://phimimg.com/upload/vod/20240913-1/191b1391f088e1a1fd32b9bda7bb67b9.jpg', '<p>Đầu thời Dân Quốc, lưu dân khắp nơi nổi dậy, năm người bao gồm ông quản lý sổ sách, người ăn xin, thợ săn, thợ thiến, và thầy lang chân đất kết bạn đồng hành. Trên đường đi, vì không chịu nổi cơn đói, năm người này đã quyết định làm cướp một cách hoang đường. Họ hô khẩu hiệu “Cướp tiền, cướp lương thực, cướp phụ nữ” và bắt đầu cuộc sống của bọn cướp. Khi họ đến thôn Thạch Khoát định cướp bóc thì phát hiện ra dịch bệnh lan tràn trong làng, biến nơi này thành thôn ma.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ren Chenxi","avatar":""},{"name":"Ju Qingyu","avatar":""},{"name":"Lu Wenfei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324228);
