INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vay-no-tinh-yeu', 'Vay Nợ Tình Yêu', 'Love You to Debt', 'https://phimimg.com/upload/vod/20240910-1/ad80aa22491511795656824814219b0d.jpg', 'https://phimimg.com/upload/vod/20240910-1/61b1a3c36251849fe8a10cc7b0ba4b25.jpg', '<p>Khi một khách hàng không trả tiền, người đi đòi nợ nọ bèn thỏa thuận hẹn hò với cô. Nhưng mối quan hệ giả của họ có thể dẫn đến chuyện tình thật.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"วชิรวิชญ์ ชีวอารี","avatar":""},{"name":"อุรัสยา เสปอร์บันด์","avatar":""},{"name":"พรชิตา ณ สงขลา","avatar":""},{"name":"นิติ ชัยชิตาทร","avatar":""},{"name":"ธนบูรณ์ เกียรตินิรันดร์","avatar":""},{"name":"D Gerrard","avatar":""},{"name":"วงศกร รัศมิทัต","avatar":""},{"name":"วัชระ ปานเอี่ยม","avatar":""},{"name":"Prakpoom Jongmunwattana","avatar":""},{"name":"Tanapat Lekyim","avatar":""},{"name":"Raiwin Ong","avatar":""},{"name":"Deedee Piamwiriyaku","avatar":""},{"name":"กิตติภัค ทองอ่วม","avatar":""},{"name":"Teerapong Khiawwijit","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324228);
