INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vay-no-tinh-yeu', 'Vay Nợ Tình Yêu', 'Love You to Debt', 'vay nợ tình yêu love you to debt วชิรวิชญ์ ชีวอารี อุรัสยา เสปอร์บันด์ พรชิตา ณ สงขลา นิติ ชัยชิตาทร ธนบูรณ์ เกียรตินิรันดร์ d gerrard วงศกร รัศมิทัต วัชระ ปานเอี่ยม prakpoom jongmunwattana tanapat lekyim raiwin ong deedee piamwiriyaku กิตติภัค ทองอ่วม teerapong khiawwijit ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-hoa-muay-thai', 'Tinh Hoa Muay Thái', 'Art of Eight Limbs', 'https://phimimg.com/upload/vod/20240910-1/a885e71239987ed8b44a1ad9613b4969.jpg', 'https://phimimg.com/upload/vod/20240910-1/82fda552a3435f68e7abde6701b3e046.jpg', '<p>Bộ phim kể về một nhà phân tích dữ liệu trẻ tuổi của CIA, người có kỹ năng boxing và được giao một nhiệm vụ cực kỳ nhạy cảm. Khi một lãnh chúa ở Myanmar đang bán khí độc VX cho kẻ trả giá cao nhất, CIA can thiệp để ngăn chặn kế hoạch của hắn. Lựa chọn tốt nhất của họ không phải là một đặc vụ kỳ cựu, mà là một nhà phân tích dữ liệu. Trong khi bị cuốn vào thế giới tội phạm này, anh phải đối mặt với những chiến binh tài năng trong một giải đấu võ thuật chết người, không chỉ để bảo vệ tính mạng của mình mà còn là số phận của cả thế giới.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ludi Lin","avatar":""},{"name":"Grace Vorananth","avatar":""},{"name":"สหจักร บุญธนกิจ","avatar":""},{"name":"Nicholas Hammond","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Ron Smoorenburg","avatar":""},{"name":"Tofan Pirani","avatar":""},{"name":"Andrey Kasushkin","avatar":""},{"name":"Maverick Kamuela Kang Jr.","avatar":""},{"name":"Jaroslav Shvets","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
