INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-sieu-y', 'Thần Thám Siêu Ý', 'SUSPECT (Cantonese ver.)', 'https://phimimg.com/upload/vod/20240410-1/b6d090f97325521312903eab298782e8.jpg', 'https://phimimg.com/upload/vod/20240410-1/564ee6eacf98b6ac443e9d86f9e221ed.jpg', '<p>Cựu cảnh sát Quách Văn Bân mắc chứng siêu trí nhớ, bị cuốn vào một trò chơi của kẻ giết người thách thức công lý có trí thông minh cao. Kẻ nghi can tuyên bố tự mình thay pháp luật thực hiện hình phạt cho tội phạm, sử dụng những phương tiện kỳ lạ để tiêu diệt tội ác, một cách mạnh mẽ thách thức hệ thống tư pháp, khiến cả xã hội rơi vào tình trạng hoang mang. Phía trước là tính mạng người quan trọng, sau là công chúng nghi ngờ, anh ta dựa vào khả năng siêu nhớ đặc biệt của mình, đã từng bước phát hiện và làm sáng tỏ bí ẩn của trò chơi giữa cảnh sát và tội phạm này, bất chấp sự phản đối của đám đông.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nick Cheung","avatar":""},{"name":"Zhang Yishang","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Niki Chow Lai-Kei","avatar":""},{"name":"Yongqi Liang","avatar":""},{"name":"Wang Zun","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324228);
