INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-nhan-cao-boi', 'Nữ Nhân Cao Bồi', 'Calamity Jane', 'https://phimimg.com/upload/vod/20240910-1/732e578ebbb36140ae4a90a7c5b05529.jpg', 'https://phimimg.com/upload/vod/20240910-1/6f972fa03d7ffec6165fe5ee52640851.jpg', '<p>Sau khi Wild Bill bị giết trong một ván poker, Calamity Jane phải vượt ngục và tìm cách trả thù. Nhiệm vụ của cô bị cản trở bởi Cảnh sát trưởng Mason của Deadwood, người đang ra tay giam giữ và bắt giữ cô.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Emily Bett Rickards","avatar":""},{"name":"Stephen Amell","avatar":""},{"name":"Tim Rozon","avatar":""},{"name":"Priscilla Faia","avatar":""},{"name":"Garrett Black","avatar":""},{"name":"Christian Sloan","avatar":""},{"name":"Gage Marsh","avatar":""},{"name":"James Drew Dean","avatar":""},{"name":"Spencer Borgeson","avatar":""},{"name":"Jana Berengel","avatar":""},{"name":"Tyler Burrows","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
