INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-xui-giuc', 'Những Kẻ Xúi Giục', 'Firebrand', 'https://phimimg.com/upload/vod/20240910-1/9ae1cbd2e4d228fb0d2e587811c2904b.jpg', 'https://phimimg.com/upload/vod/20240910-1/0b152e5221e059274d60a6d1d25680aa.jpg', '<p>Ở nước Anh thời Tudor đẫm máu, Katherine Parr, người vợ thứ sáu và cũng là người vợ cuối cùng của Vua Henry VIII, được phong làm Nhiếp chính trong khi bạo chúa Henry đang chiến đấu ở nước ngoài. Katherine đã làm mọi thứ có thể để thúc đẩy một tương lai mới dựa trên niềm tin Tin lành cấp tiến của mình. Khi vị vua ngày càng ốm yếu và nghi ngờ, ông ta chuyển cơn giận dữ của mình sang những kẻ cấp tiến, buộc tội người bạn thời thơ ấu của Katherine về tội phản quốc và thiêu sống họ. Katherine khi này thấy mình còn đang phải chiến đấu vì sự tồn tại của chính mình</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Alicia Vikander","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Sam Riley","avatar":""},{"name":"Simon Russell Beale","avatar":""},{"name":"Erin Doherty","avatar":""},{"name":"Ruby Bentall","avatar":""},{"name":"Bryony Hannah","avatar":""},{"name":"Maia Jemmett","avatar":""},{"name":"Patsy Ferran","avatar":""},{"name":"Junia Rees","avatar":""},{"name":"Andy M Milligan","avatar":""},{"name":"Edward Harrison","avatar":""},{"name":"Mina Andala","avatar":""},{"name":"Paul Tinto","avatar":""},{"name":"Frank Howell","avatar":""},{"name":"Ashleigh Reynolds","avatar":""},{"name":"Ian Dry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
