INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('didi', 'Dìdi', 'Dìdi (弟弟)', 'https://phimimg.com/upload/vod/20240910-1/30495fb27013e8e13a3cdd8200deec9c.jpg', 'https://phimimg.com/upload/vod/20240910-1/06904a8df3d1c26b293c95d37e57326b.jpg', '<p>Vào mùa hè cuối cùng trước khi bước vào trung học, một cậu bé người Mỹ gốc Đài Loan 13 tuổi học được những điều mà gia đình không thể dạy cậu: cách trượt ván, cách tán tỉnh và cách yêu thương mẹ mình. Trong quãng thời gian ngắn ngủi này, cậu trải qua những cảm xúc đầu đời, khám phá bản thân và tìm thấy ý nghĩa của tình cảm gia đình.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Izaac Wang","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Shirley Chen","avatar":""},{"name":"Chang Li Hua","avatar":""},{"name":"Mahaela Park","avatar":""},{"name":"Raul Dial","avatar":""},{"name":"Aaron Chang","avatar":""},{"name":"Chiron Cillia Denk","avatar":""},{"name":"Sunil Mukherjee Maurillo","avatar":""},{"name":"Montay Boseman","avatar":""},{"name":"Alysha Syed","avatar":""},{"name":"Alaysia Simmons","avatar":""},{"name":"Tarnvir Kamboj","avatar":""},{"name":"Shiu Fang Wang","avatar":""},{"name":"Jayden Chiang","avatar":""},{"name":"Joziah Lagonoy","avatar":""},{"name":"Joshua Hank","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324228);
