INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-huyen-thoai', 'Anh Hùng Huyền Thoại', 'Kalki 2898 AD', 'https://phimimg.com/upload/vod/20240912-1/b257c92f5eb97381a522f64a935e3ab8.jpg', 'https://phimimg.com/upload/vod/20240912-1/5f08e35710979011ac6d112ec5bfd141.jpg', '<p>Vào năm 2898 sau Công nguyên, khoảng 6000 năm sau chiến tranh Kurukshetra, Ashwatthama chuẩn bị cho trận chiến cứu chuộc cuối cùng của mình trước dấu hiệu hy vọng ở một thế giới đen tối và Bhairava, một thợ săn tiền thưởng khôn ngoan và tư lợi, mệt mỏi với cuộc sống đầy nguy hiểm trở thành kẻ săn tiền thưởng. trở ngại trong quá trình này.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Prabhas","avatar":""},{"name":"Deepika Padukone","avatar":""},{"name":"Amitabh Bachchan","avatar":""},{"name":"Kamal Haasan","avatar":""},{"name":"Saswata Chatterjee","avatar":""},{"name":"Shobana","avatar":""},{"name":"Rajendra Prasad","avatar":""},{"name":"Pasupathy","avatar":""},{"name":"Anna Ben","avatar":""},{"name":"Keya Nair","avatar":""},{"name":"Disha Patani","avatar":""},{"name":"Harshith Malgireddy","avatar":""},{"name":"Ayaz Pasha","avatar":""},{"name":"Humhu","avatar":""},{"name":"Kavya Ramachandran","avatar":""},{"name":"Anil George","avatar":""},{"name":"Brahmanandam","avatar":""},{"name":"கீர்த்தி சுரேஷ்","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324228)