INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tai-cua-ngoai', 'Gia Tài Của Ngoại', 'How to Make Millions Before Grandma Dies', 'https://phimimg.com/upload/vod/20240912-1/64bf86cb22534c7bfae9a710e0ace8e1.jpg', 'https://phimimg.com/upload/vod/20240912-1/9e13b635ca60b62f004f6e3de4ed5336.jpg', '<p>Gia Tài Của Ngoại xoay quanh câu chuyện về M (do Billkin Putthipong thủ vai) là một chàng trai thất nghiệp và đang tìm mọi cách để làm giàu. Một ngày nọ, M nhận ra có một cách làm giàu nhanh chóng: chăm sóc người bà đang mắc ung thư giai đoạn cuối để lấy tài sản thừa kế. Vì vậy, M quyết định đến chăm sóc người bà của mình. Tuy nhiên, trong khoảng thời gian sống cùng bà, M đã nhận ra những điều còn giá trị hơn cả tài sản.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Thái Lan', 1, '[{"name":"พุฒิพงศ์ อัสสรัตนกุล","avatar":""},{"name":"Usha Seamkhum","avatar":""},{"name":"ต้นตะวัน ตันติเวชกุล","avatar":""},{"name":"พงศธร จงวิลาส","avatar":""},{"name":"สฤญรัตน์ โทมัส","avatar":""},{"name":"Sanya Kunakorn","avatar":""},{"name":"Himawari Tajiri","avatar":""},{"name":"Duangporn Oapirat","avatar":""},{"name":"Wattana Subpakit","avatar":""},{"name":"Sumalee Suteeratham","avatar":""},{"name":"Phichai Prommate","avatar":""},{"name":"Buppa Suttisanon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
