INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-tai-cua-ngoai', 'Gia Tài Của Ngoại', 'How to Make Millions Before Grandma Dies', 'gia tài của ngoại how to make millions before grandma dies พุฒิพงศ์ อัสสรัตนกุล usha seamkhum ต้นตะวัน ตันติเวชกุล พงศธร จงวิลาส สฤญรัตน์ โทมัส sanya kunakorn himawari tajiri duangporn oapirat wattana subpakit sumalee suteeratham phichai prommate buppa suttisanon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-bo-doi-dau', 'Ông Bố Đối Đầu', 'Your Honor', 'https://phimimg.com/upload/vod/20240829-1/3faba97c08f43a3786952226000fc74d.jpg', 'https://phimimg.com/upload/vod/20240829-1/80aa1c64763a33fd9f8d0df47b3f0f87.jpg', '<p>Ông Bố Đối Đầu là cuộc chiến tàn khốc giữa hai người bố ở hai phía đối lập của công lý. Song Pan Ho là một thẩm phán được người người tôn trọng vì sự công bằng chính trực, còn Kim Kang Heon là ông trùm tội phạm độc ác luôn xem thường pháp luật. Nhưng lằn ranh thiện ác đó bỗng bị xóa nhòa khi con của thẩm phán vô tình gây tai nạn khiến con của ông trùm tử vong. Cả hai người bố đều sẵn sàng làm mọi thứ để bảo vệ con mình, cuối cùng thì công lý sẽ thuộc về tay ai?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"손현주","avatar":""},{"name":"김명민","avatar":""},{"name":"김도훈","avatar":""},{"name":"Heo Nam-jun","avatar":""},{"name":"정은채","avatar":""},{"name":"최무성","avatar":""},{"name":"정애연","avatar":""},{"name":"박세현","avatar":""},{"name":"Shin Ye-chan","avatar":""},{"name":"백주희","avatar":""},{"name":"Park Ji-yeon","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
