INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-bo-doi-dau', 'Ông Bố Đối Đầu', 'Your Honor', 'ông bố đối đầu your honor 손현주 김명민 김도훈 heo nam-jun 정은채 최무성 정애연 박세현 shin ye-chan 백주희 park ji-yeon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-phuong-quan', 'Tứ Phương Quán', 'Go East', 'https://phimimg.com/upload/vod/20240824-1/8093c4b50f87947befeb31366d5eef5b.jpg', 'https://phimimg.com/upload/vod/20240824-1/0f9f7aea1b395a72c9c9f791c609ccb8.jpg', '<p>&quot;Tứ Phương Quán&quot; là bộ phim hài cổ trang do Triệu Khải Thần (đạo diễn &quot;Ở Rể&quot;) đạo diễn, có sự tham gia của Đàm Kiện Thứ (diễn viên &quot;Lạp Tội Đồ Giám&quot;), Châu Y Nhiên (diễn viên &quot;Đuổi bắt thanh xuân&quot;) và Đỗ Thuần (diễn viên &quot;Bát Bách&quot;), Hám Thanh Tử (diễn viên &quot;Chuyến Bay Sinh Tử&quot;). Bộ phim kể về câu chuyện của Nguyên Mạc, A Thuật, Vương Khôn Ngô, và Úy Trì Hoa, bốn chí sĩ với lý tưởng lớn lao, dũng cảm tiến lên vì gia đình, quốc gia và công lý, dù họ chỉ sống trong một thế giới nhỏ bé. Trong thời kỳ An Bình của Đại Ung, chàng trai trẻ Nguyên Mạc người thành Trường Nhạc (Đàm Kiện Thứ đóng) mang theo con dấu Tứ Phương Quán để cấp giấy phép vào thành cho dị tộc, không ngờ sao lại gặp phải A Thuật từ nước Yên Nhạc đến tị nạn. Thân mang tội danh, cậu bị đày đến Tứ Phương Quán để phục dịch cho tướng quân Vương Côn Ngô (Đỗ Thuần đóng) đang thủ ở biên cương. Và thế, anh chàng phải ăn bao nhiêu là &quot;trái ngọt&quot;: Anh đã bị Vương Côn Ngô lừa và buộc phải làm việc cho Tứ Phương Quán, trở thành một viên quan nhỏ xử lý công sự của các nước khác. Vô tình sao, A Thuật lại trở thành &quot;thị nữ&quot; cho Nguyên Mạc, Vương Côn Ngô vượt lên làm cấp trên. Chưa kể, quận chúa Úy Trì Hoa (Hám Thanh Tử đóng) cũng tới hóng chuyện. Ở Tây viện vốn bị chê cười là nơi chó cũng chê này, Nguyên Mạc dần trưởng thành hơn qua từng nhiệm vụ khó khăn.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"檀兮爾","avatar":""},{"name":"周依然","avatar":""},{"name":"Du Chun","avatar":""},{"name":"Kan Qingzi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324228);
