INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-thanh-quy-su', 'Giang Thành Quỷ Sự', 'Strange Tales Of Jiang Cheng', 'https://phimimg.com/upload/vod/20240818-1/4b63a1e86c7a7d54c1b32a470bfd2184.jpg', 'https://phimimg.com/upload/vod/20240818-1/20e08679f0fc7fcda4649b986aa424a0.jpg', '<p>Những năm đầu Dân Quốc, tình hình Giang Châu ở vùng Tây Nam vô cùng hỗn loạn, những vụ án kỳ lạ xảy ra ngày càng nhiều. Tần Hỏa Lạc đi du học trở về, gặp được đội trưởng đội điều tra Tống Hà giữa thời loạn lạc, cùng nhau khám phá điều bí ẩn. Cùng với sự trợ giúp của nữ pháp y Phạm Tiểu Phạn, ba người dùng sự chân thành và trí tuệ của mình để xua đi màn sương nhuốm máu vây bọc người dân, bảo vệ chính nghĩa trong xã hội.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"夏之光","avatar":""},{"name":"吳希澤","avatar":""},{"name":"Wang Zhi Yi","avatar":""},{"name":"黑子","avatar":""},{"name":"朱铁","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324228);
