INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-luoc-hon-nhan', 'Chiến Lược Hôn Nhân', 'We All Lie', 'https://phimimg.com/upload/vod/20240830-1/00c72a1fa17c656cbf35c626cde06853.jpg', 'https://phimimg.com/upload/vod/20240830-1/8ef91f02e5ee7672ec747817e5a492da.jpg', '<p>Biên kịch nổi tiếng Tô Ly và đạo diễn nổi danh Trương Thư Hằng có với nhau một cuộc hôn nhân nhiều người ngưỡng mộ, nhưng khi sống trong hạnh phúc Tô Ly lại nhận được một lá thư nặc danh, nói rằng Trương Thư Hằng đang ngoại tình. Với việc liên tục điều tra, cuối cùng Tô Ly xác định được sự thật rằng chồng cô đã lừa dối cô và phát hiện ra rằng người anh ta ngoại tình cùng lại là người bạn thân nhất của cô trong nhiều năm. Đối mặt với sự phản bội của cả tình bạn và tình yêu, Tô Ly đau khổ vô cùng. Vôn là người yêu ghét rõ ràng, cô quyết định ly hôn ngay lập tức. Tuy nhiên, sau khi hỏi ý kiến luật sư, cô phát hiện ra rằng Trương Thư Hằng gần như không có tài sản đứng tên mình do thất bại trong đầu tư trước đây. Nếu ly hôn, Tô Ly sẽ phải chia một nửa tài sản của mình cho Trương Thư Hằng. Không thể chấp nhận điều này, Tô Ly quyết định giả vờ không biết chuyện ngoại tình và hoãn việc ly hôn cho đến khi chuẩn bị xong mọi thủ tục ly hôn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"何泓姍","avatar":""},{"name":"Li Zifeng","avatar":""},{"name":"陈牧扬","avatar":""},{"name":"Zheng Nanxi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
