INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rao-ban-nha-ma', 'Rao Bán Nhà Ma', 'Peaceful Property', 'https://phimimg.com/upload/vod/20240910-1/bbf6d9764b74e2d0814b2789a841b2fe.jpg', 'https://phimimg.com/upload/vod/20240910-1/6e80954eff5875101b1be8e4e34b1799.jpg', '<p>Home, người thừa kế của một gia đình Thái giàu có và nổi tiếng, sống một cuộc sống vô tư cho đến khi ông nội qua đời và anh phải trở về Thái Lan để nhận tài sản thừa kế. Tài sản thừa kế mà ông để lại không phải là tài sản thông thường, tất cả tài sản đều bị đồn là có ma ám nên không thể bán được. Cuộc đời của đầu bếp lành nghề Peach thay đổi đáng kể khi anh gặp một tai nạn nghiêm trọng. Sau khi hồi phục, anh ấy phát triển khả năng nhìn thấy các linh hồn và lỗ hổng ở nhà, khiến chị gái Pangpang, người có ảnh hưởng điên cuồng trên TikTok của anh ấy khó chịu. Một ngày nọ, Peach đến dự một bữa tiệc tân gia đầy ma và TikTok của Pangpang tại sự kiện này ngay lập tức được lan truyền rộng rãi. Home rất tức giận khi xem đoạn clip, vì vậy anh ấy và Luật sư Kan đã tìm Peach và gây áp lực buộc anh ấy phải chịu trách nhiệm về những gì anh ấy đã làm bằng cách trừ tà nơi này... và hơn thế nữa.</p>', 'Tập 2', 14, 'series', 'ongoing', 9, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Tawan Vihokratana","avatar":""},{"name":"Thitipoom Techa-apaikhun","avatar":""},{"name":"Ployshompoo Supasap","avatar":""},{"name":"วรนิษฐ์ ถาวรวงศ์","avatar":""},{"name":"Tanapon Sukumpantanasan","avatar":""},{"name":"ปณชัย ศรีอาริยะรุ่งเรือง","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324228);
