INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-nu-bao-thu', 'Đả Nữ Báo Thù', 'Revolver', 'https://phimimg.com/upload/vod/20240909-1/8ce93ad8951ad6e9fbbdf394be24a6c2.jpg', 'https://phimimg.com/upload/vod/20240909-1/1c8dec855a5913bac1775e750f16ec20.jpg', '<p>Nữ cảnh sát Ha Soo Young (Jeon Do Yeon) chấp nhận ngồi tù oan vì giao kèo về khoản đền bù kếch xù từ Andy (Ji Chang Wook). Nhưng khi cô được trả tự do, những kẻ hứa hẹn ngày xưa đều mất dạng, chỉ có cô gái bí ẩn Jung Yoon Sun (Lim Ji Yeon) đến đón cô. Bất chấp tất cả, Ha Soo Young quyết tâm tập trung vào một mục tiêu duy nhất là truy tìm sự thật, lấy lại những gì thuộc về mình!</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"전도연","avatar":""},{"name":"지창욱","avatar":""},{"name":"임지연","avatar":""},{"name":"김준한","avatar":""},{"name":"김종수","avatar":""},{"name":"정만식","avatar":""},{"name":"전혜진","avatar":""},{"name":"이정재","avatar":""},{"name":"정재영","avatar":""},{"name":"오의식","avatar":""},{"name":"윤경호","avatar":""},{"name":"양현민","avatar":""},{"name":"김혜은","avatar":""},{"name":"유성주","avatar":""},{"name":"김준배","avatar":""},{"name":"Oh Choong-geun","avatar":""},{"name":"정규영","avatar":""},{"name":"마웅규","avatar":""},{"name":"김회창","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
