INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-truong-narko-integriti', 'Cảnh Sát Trưởng: Narko Integriti', 'Sheriff: Narko Integriti', 'https://phimimg.com/upload/vod/20240908-1/391e9fb62de761b43fecd06f13c7b107.jpg', 'https://phimimg.com/upload/vod/20240908-1/cab7482e5dc880fb6469d8b1fd7b11d4.jpg', '<p>Cảnh sát trưởng, một sĩ quan cảnh sát của Cục Liêm chính là người tận tâm và sâu sắc. Anh ta đóng cặp với Nazri, một sĩ quan cảnh sát trẻ và có lý tưởng từ Cục Ma túy. Nhiệm vụ của họ là triệt phá một tập đoàn ma túy do tên trùm tàn nhẫn Tony đứng đầu. Tên trùm có liên quan đến việc phân phối methamphetamine và nhiều người đã chết dưới tay tên sát nhân Meth này.</p>', 'Full', 1, 'single', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Zul Ariffin","avatar":""},{"name":"Syafiq Kyle","avatar":""},{"name":"Aaron Aziz","avatar":""},{"name":"Elizabeth Tan","avatar":""},{"name":"Azira Shafinaz","avatar":""},{"name":"Amir Nafis","avatar":""},{"name":"Kodi Rasheed","avatar":""},{"name":"Shaharuddin Thamby","avatar":""},{"name":"Esma Daniel","avatar":""},{"name":"Kamal Affandi Hashim","avatar":""},{"name":"Natasya Mahyan","avatar":""},{"name":"Zen Ng","avatar":""},{"name":"Meynillen Thamil Selvan","avatar":""},{"name":"Hazama Azmi","avatar":""},{"name":"Azri Iskandar","avatar":""},{"name":"Hasnul Rahmat","avatar":""},{"name":"Siraj Alsagof","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]'