INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-lien-ket-bi-an', 'Mối Liên Kết Bí Ẩn', 'Connection', 'https://phimimg.com/upload/vod/20240909-1/e0bf01daa60c676f94961d458af9e09d.jpg', 'https://phimimg.com/upload/vod/20240909-1/09efbf69a3f8900131c78f9dc926ed73.jpg', '<p>Mối Liên Kết Bí Ẩn - Connection là Bộ phim trinh thám tội phạm mô tả tình bạn bị rạn nứt của nhóm bạn thân nhau từ hồi trung học khi họ cùng nhau điều tra sự thật về cái chết của một người bạn và khoản tiền bảo hiểm trị giá 5 tỷ won mà người đó để lại. Ji Sung sẽ đảm nhận vai Jang Jae Kyung, một thanh tra cảnh sát thuộc Đội chống ma túy của Đơn vị điều tra đô thị, với tính cách thông minh và điềm tĩnh. Jang Jae Kyung là người đã nhận số tiền bảo hiểm 5 tỷ won sau cái chết đầy bí ẩn của một người bạn thời trung học. Jeon Mi Do sẽ đóng vai nữ chính Oh Yoon Jin - phóng viên về các vấn đề xã hội của Nhật báo Kinh tế Anhyeon - một người đầy quyết tâm và thẳng thắn. Với tính cách mạnh mẽ cùng tài năng trong công việc, Yoon Jin không ngại ngần đưa ra những nhận xét thẳng thắn cho mọi người, dù họ có địa vị cao trong xã hội. Tuy nhiên, chính vì lí do này khiến cô trước đó đã bị sa thải vì không thể nhắm mắt làm ngơ trước những sự việc bất công.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"지성","avatar":""},{"name":"전미도","avatar":""},{"name":"권율","avatar":""},{"name":"김경남","avatar":""},{"name":"정유민","avatar":""},{"name":"정순원","avatar":""},{"name":"윤나무","avatar":""},{"name":"서이라","avatar":""},{"name":"정재광","avatar":""},{"name":"차엽","avatar":""},{"name":"Lee Kang-wook","avatar":""},{"name":"Cho Han-gyeol","avatar":""},{"name":"김민주","avatar":""},{"name":"Yoo Hee-je","avatar":""},{"name":"박근록","avatar":""},{"name":"류혜린","avatar":""},{"name":"박정표","avatar":""},{"name":"Yoon Sa-bong","avatar":""},{"name":"문성근","avatar":""},{"name":"Han Hyeon-jun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324228);
