INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-tru-ta', 'Thầy Trừ Tà', 'The Exorcism', 'https://phimimg.com/upload/vod/20240909-1/ebc9924308bb5caa7f3cde5e73b5749e.jpg', 'https://phimimg.com/upload/vod/20240909-1/d7e4ee17af41af1527e9191730c55494.jpg', '<p>Nam diễn viên đoạt giải Oscar Russell Crowe vào vai Anthony (Tony) Miller, một diễn viên với nhiều phiền muộn vừa nhận một vai diễn mới trong một bộ phim kinh dị, siêu nhiên. Tony bắt đầu có những cư xử kì lạ khiến con gái của ông - Lee (Ryan Simpkins) tự hỏi liệu cha của mình có đang dấn thân vào con đường cũ hay có gì đó tồi tệ và đen tối hơn đang đứng đằng sau...</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Russell Crowe","avatar":""},{"name":"Ryan Simpkins","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Chloe Bailey","avatar":""},{"name":"Adam Goldberg","avatar":""},{"name":"Adrian Pasdar","avatar":""},{"name":"David Hyde Pierce","avatar":""},{"name":"Tracey Bonner","avatar":""},{"name":"Marcenae Lynette","avatar":""},{"name":"Joshua John Miller","avatar":""},{"name":"Hallie Samuels","avatar":""},{"name":"Samantha Mathis","avatar":""},{"name":"Anna Maria Reyer","avatar":""},{"name":"Jayden Fontaine","avatar":""},{"name":"Zach Padlo","avatar":""},{"name":"Josh Warren","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
