INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc-tinh-yeu', 'Khế Ước Tình Yêu', 'Taking Love As A Contract', 'https://phimimg.com/upload/vod/20240908-1/2082d17a329ce6178da4b708a6a739cb.jpg', 'https://phimimg.com/upload/vod/20240908-1/34f3e92ead85f3274a07f676b43c1b45.jpg', '<p>Vào mùa hè, &quot;diễn viên chim sẻ&quot; bận rộn với cuộc sống, vì bảo vệ nhà bà ngoại, đã nỗ lực tuyệt vọng để thay thế danh tính của con gái nhà họ Hà, cải trang thành &quot;công chúa&quot;, giúp con trai nuôi giàu có Ji Cheng xuan được gia đình He công nhận, vượt qua sự kháng cự của mọi bên, và liên tục phá vỡ bong bóng dối trá, và cuối cùng cả hai đã bảo vệ tình cảm gia đình tương ứng của mình và bất ngờ có được sự chân thành của nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lục Nghiên Kì","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Phạm Tĩnh Y","avatar":""},{"name":"Trang Đạt Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324228);
