INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-cung-nhau-rung-chuyen-mat-troi', 'Chúng Ta Cùng Nhau Rung Chuyển Mặt Trời', 'Viva La Vida', 'https://phimimg.com/upload/vod/20240908-1/8c10b76eb2fd6bbc17be1e4b692fad62.jpg', 'https://phimimg.com/upload/vod/20240908-1/039c88db443a53c8cb0b1a9a378de6b5.jpg', '<p>Chạy đua với thời gian, hai người xa lạ mắc bệnh nan y giao kèo giúp nhau tìm thấy tình yêu và ý nghĩa trong những ngày còn lại của họ.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"彭昱暢","avatar":""},{"name":"Li Gengxi","avatar":""},{"name":"Jerry Lee","avatar":""},{"name":"徐帆","avatar":""},{"name":"Gao Yalin","avatar":""},{"name":"王迅","avatar":""},{"name":"刘丹","avatar":""},{"name":"宋伊人","avatar":""},{"name":"Liu Xun","avatar":""},{"name":"楊玏","avatar":""},{"name":"李建义","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324229);
