INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-di-thue', 'Bạn Trai Đi Thuê', 'Romantic Boyfriend', 'https://phimimg.com/upload/vod/20240908-1/9d97c59818e82dd03eb0d278db84158c.jpg', 'https://phimimg.com/upload/vod/20240908-1/34dbf6f2fd2ea109bdaf2a57eb360e2f.jpg', '<p>Một Tết Nguyên đán nữa lại đến, nhưng Khưu Phi Phi, người bị giục kết hôn lại không hề mong chờ gì, để có thể ăn Tết yên bình, Khưu Phi Phi bỏ ra số tiền lớn để thuê bạn trai trong ba ngày. Kỷ Huyền, bạn trai ở khoa diễn xuất diễn vô cùng đạt. Mẹ Khưu vô cùng hài lòng về cậu con rể này. Lúc Kỷ Huyền chuẩn bị thành công rút lui, một tình huống bất ngờ khiến Kỷ Huyền phải ở lại nhà họ Khưu. Để không bị lộ, hai người kí kết hợp đồng vô cùng nghiêm khắc, khi bạn của họ, Kim Minh Minh và bạn trai cùng nhập cuộc, bốn người đấu trí đấu dũng, không ngừng trao đổi thế chủ động, dẫn tới hết trò vui này tới trò vui khác.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"段晓薇","avatar":""},{"name":"Cai Zhengjie","avatar":""},{"name":"周梓倩","avatar":""},{"name":"Wanting Liu","avatar":""},{"name":"陈沐","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
