INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sunny', 'Sunny', 'Sunny', 'https://phimimg.com/upload/vod/20240718-1/cfe2712cfd0eb23f5bf421914549fcd2.jpg', 'https://phimimg.com/upload/vod/20240718-1/625d8834d22a70a1d412214126a95a35.jpg', '<p>Cuộc sống của một người phụ nữ Mỹ sống ở Kyoto, Nhật Bản bị đảo lộn khi chồng và con trai cô biến mất trong một tai nạn máy bay bí ẩn. Để an ủi cô, người ta tặng cô Sunny, một trong những rô-bốt gia dụng mới do công ty điện tử của chồng cô sản xuất.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rashida Jones","avatar":""},{"name":"西島秀俊","avatar":""},{"name":"Joanna Sotomura","avatar":""},{"name":"ジュディ・オング","avatar":""},{"name":"YOU","avatar":""},{"name":"annie the clumsy","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324229);
