INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-tinh', 'Gai Tình', 'Love & Bid Farewell', 'https://phimimg.com/upload/vod/20240827-1/878e203559bdb93a1fe442bf012f1b79.jpg', 'https://phimimg.com/upload/vod/20240827-1/4c297ae6fe316e58a7340a943508259f.jpg', '<p>Năm năm trước, vì bị vu oan mưu phản mà cả nhà Cố Quân Dao chết thảm. Nàng ngấm ngầm nương thân bao năm ở tổ chức bí mật chỉ vì báo thù. Hoàng tử Nhạc Cẩn Thần chính là thứ vũ khí báo thù tốt nhất của nàng. Ai mà nghĩ đến đóa sen trắng tựa tiên tử bị lưu đày mà tâm tư lại xấu xa thâm độc, từng bước biến thành con rối như vậy. Một bên thì ham muốn cháy bỏng, một bên thâm cung quỷ kế chồng chất, nàng phải làm thế nào đây?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Xuanlin","avatar":""},{"name":"严子贤","avatar":""},{"name":"Gao Mingchen","avatar":""},{"name":"Han Mo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
