INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nuong-ham-tien', 'Cô Nương Ham Tiền', 'Debit Queen', 'https://phimimg.com/upload/vod/20240829-1/4a6136053a96c4244a53265e0030ffa9.jpg', 'https://phimimg.com/upload/vod/20240829-1/9a34e42f9b10e076f353889162df6b82.jpg', '<p>Linh Sắt, đại tiểu thư của Lệnh Kí Bố Trang luôn mong ước rời xa gia đình vào ngày sinh nhật, sống cuộc sống tự do, không cần gả đi, không cần nhìn sắc mặt người khác. Không ngờ xui rủi gặp ngay người giàu có nhất Lâm Xuân Thành, Từ Tử Lộc, cửa hàng cô tìm kiếm đã lâu bị hắn ta cướp, lại lừa cô trở thành vợ chồng kế ước. Từ Tử Lộc bị ấn tưởng bởi sự lương thiện, độc lập và sự nháy bén trong kinh doanh của Linh Sắt, nảy sinh tình cảm với cô. Vào lúc cặp oan gia đang vui vẻ, nguy cơ của Từ gia dần hé lộ, sự xuất hiện bất ngờ của đối thủ Ngô Kỳ khiến Từ Tử Lộ rơi vào nguy cơ về cảnh sự nghiệp lẫn tình cảm. May mắn thay, Linh Sắt thông minh giàu có, có đầu óc kinh doanh, sáng tạo ra một loạt sản phẩm độc quyền, trên đường vào Kinh giải quyết khủng hoảng gia đình, cô và Từ Tử Lộc tin tưởng giúp đỡ lẫn nhau, trái tim của hai người lại gần nhau hơn, vợ chồng chung tay tranh đoạt vị trí hoàng tương, bắt đầu hành trình kinh doanh hoàn toàn mới tại Kinh thành.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"趙弈欽","avatar":""},{"name":"Li Jiaqi","avatar":""},{"name":"Jiang Junhan","avatar":""},{"name":"潘悦","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324229);
