INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-linh-trong-xac-me', 'Ác Linh Trong Xác Mẹ', 'Nearing Death', 'https://phimimg.com/upload/vod/20240906-1/9e2a574ba5d03b34176014365322515b.jpg', 'https://phimimg.com/upload/vod/20240906-1/ee93abe99457a6e330b0cf06da959b7d.jpg', '<p>Sekar cố gắng một mình nuôi 3 đứa con của mình bằng cách mở một quầy bán đồ ăn. Gần đây anh ấy lo lắng vì hàng hóa của anh ấy luôn bị ôi thiu ngay sau khi đồ ăn được phục vụ. Sekar đến gặp Mak Ambar, pháp sư đã đặt &#39;penglaris&#39; trong gian hàng của mình. Tuy nhiên, hóa ra Mak Ambar đã chết. Kể từ đó, Jin, người luôn giúp đỡ anh, đòi mạng sống của anh cho đến khi Sekar bị chiếm hữu hàng đêm. Ba đứa trẻ đã cố gắng tìm cách điều trị nhưng nỗ lực này thực sự đã đe dọa đến tính mạng của các em và gia đình.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Shareefa Daanish","avatar":""},{"name":"Caitlin Halderman","avatar":""},{"name":"Daffa Wardhana","avatar":""},{"name":"Ruth Marini","avatar":""},{"name":"Shakeel Fauzi Aisy","avatar":""},{"name":"M. N. Qomaruddin","avatar":""},{"name":"Michael Olindo","avatar":""},{"name":"Dewi Pakis","avatar":""},{"name":"Deni Saputra","avatar":""},{"name":"Stella Bodea","avatar":""},{"name":"Elzan Aziz","avatar":""},{"name":"Yopi Hedrawan","avatar":""},{"name":"Abah Dinar","avatar":""},{"name":"Angga Muharam","avatar":""},{"name":"Bajai Van Nizam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
