INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-quyen-ru', 'Quỷ Dữ Quyến Rũ', 'Succubus', 'https://phimimg.com/upload/vod/20240905-1/bf4658569ac58ee27040e48052c0f01c.jpg', 'https://phimimg.com/upload/vod/20240905-1/4aca5aab8de6f0397c300e0be229d16c.jpg', '<p>Một người cha mới trải qua cuộc ly thân tham gia một ứng dụng hẹn hò và kết đôi với một phụ nữ trẻ xinh đẹp nhưng bí ẩn... người có sức mạnh quyến rũ và thao túng khiến anh ta vướng vào một bí ẩn kinh hoàng hơn những gì anh ta có thể tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ron Perlman","avatar":""},{"name":"Rosanna Arquette","avatar":""},{"name":"Brendan Bradley","avatar":""},{"name":"Olivia Grace Applegate","avatar":""},{"name":"Derek Smith","avatar":""},{"name":"Emily Kincaid","avatar":""},{"name":"Finley Rose Slater","avatar":""},{"name":"Rachel Cook","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
