INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-nam-chua-cuoi-se-chia-tay', '7 Năm Chưa Cưới Sẽ Chia Tay', '7 Năm Chưa Cưới Sẽ Chia Tay', 'https://phimimg.com/upload/vod/20240624-1/9ac89499bf4df0ca060c58cffec1c5e2.jpg', 'https://phimimg.com/upload/vod/20240624-1/101b9b2fcd95c454139fc68f8acb49fb.jpg', '<p>7 Năm Chưa Cưới Sẽ Chia Tay xoay quanh câu chuyện của một chàng trai nhà giàu phải lòng cô gái ngây thơ nhưng ngoan cường, người có liên quan đến cái chết của bạn gái anh. Khi câu chuyện mở ra, những bí mật bắt đầu sáng tỏ.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thúy Ngân","avatar":""},{"name":"Võ Cảnh","avatar":""},{"name":"Jun Phạm","avatar":""},{"name":"Thảo Tâm","avatar":""},{"name":"Nguyệt Ánh","avatar":""},{"name":"Huỳnh Trường Thịnh","avatar":""},{"name":"Trung Dũng","avatar":""},{"name":"Ngân Hòa","avatar":""},{"name":"NSƯT Thanh Nam","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324229);
