INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gieng-quy', 'Giếng Quỷ', 'The Well', 'https://phimimg.com/upload/vod/20240905-1/3830cc27b37b14b2d0e68c5216fdcb98.jpg', 'https://phimimg.com/upload/vod/20240905-1/99e3b9871a0f0d821a60daac999a2c9e.jpg', '<p>Một nhà phục chế nghệ thuật vừa chớm nở đi đến một ngôi làng nhỏ của Ý để mang một bức tranh thời trung cổ trở lại vinh quang trước đây của nó. Cô ấy không biết rằng cô ấy đang đặt cuộc sống của mình vào nguy hiểm từ một lời nguyền độc ác và một con quái vật sinh ra từ huyền thoại và nỗi đau tàn bạo.</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Ý', 1, '[{"name":"Lauren LaVera","avatar":""},{"name":"Claudia Gerini","avatar":""},{"name":"Giovanni Lombardo Radice","avatar":""},{"name":"Linda Zampaglione","avatar":""},{"name":"Jonathan Dylan King","avatar":""},{"name":"Lorenzo Renzi","avatar":""},{"name":"Yassine Fadel","avatar":""},{"name":"Taylor Zaudtke","avatar":""},{"name":"Gianluigi Calvani","avatar":""},{"name":"Claudio Nathan Brezzi","avatar":""},{"name":"Peppe Fonzo","avatar":""},{"name":"Melanie Gaydos","avatar":""},{"name":"Elisabetta Klein","avatar":""},{"name":"Stefano Martinelli","avatar":""},{"name":"Den","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324229);
