INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuynh-ai', 'Khuynh Ái', 'Sacrifice For Love', 'https://phimimg.com/upload/vod/20240827-1/b5d507c40aa6248713676707b6b47525.jpg', 'https://phimimg.com/upload/vod/20240827-1/515eb1d9db1f88579d074d012a7e2d3f.jpg', '<p>Trong thời kỳ dân quốc hỗn loạn, vụ án mạng của một vũ nữ bình thường đã làm rúng động các thế lực đen tối ở Nam Thành. Cố Mạn Khuynh từ nhỏ đã nương tựa người chị vũ nữ của mình, lại chưa từng nghĩ rằng sẽ tận mắt thấy Lục Ngật Xuyên hại chết chị mình trong ngày cưới. Sau khi Cố Mạn Khuynh dùng dao giết Lục Ngật Xuyên trong đêm tân hôn thất bại, cô đã nhảy cửa sổ để trốn thoát, từ đó mai danh ẩn tích bắt đầu cuộc sống mới. Những tưởng Cố Mạn Khuynh gả vào hào môn sẽ có được cuộc sống hạnh phúc, nào ngờ việc làm mẹ kế nhà Lục Ngật Xuyên chỉ là bước đầu báo thù của Cố Mạn Khuynh. Cố Mạn Khuynh không tiếc cược cả nửa đời sau để báo thù Lục Ngật Xuyên nhưng đến khi sắp giết được kẻ thù lại phát hiện âm mưu ẩn giấu đằng sau còn lớn hơn...</p>', 'Tập 24', 24, 'series', 'ongoing', 14, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qiu Dingjie","avatar":""},{"name":"Cao Mingyue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
