INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-da-truong-minh', 'Vĩnh Dạ Trường Minh', 'Dawn Is Breaking', 'https://phimimg.com/upload/vod/20240820-1/27cc3b64ae0a4bca9b8a093c64988f7a.jpg', 'https://phimimg.com/upload/vod/20240820-1/53cd6f9660fb73cb83099e18d04a5895.jpg', '<p>Phương Túy thanh cao, không vướng bụi trần trong truyền thuyết lại thản nhiên tươi cười giết chết quốc trượng đương triều. Cũng vì thế, Tạ Vãn Âm trở thành con mồi của quốc sư. Quả đúng như vậy, dưới âm mưu của Đông Phương Túy, hôn lễ của Tạ Vãn Âm và Thái tử xảy ra biến cố. Nhưng điều khiến Tạ Vãn Âm bất ngờ là Đông Phương Túy không hề muốn giết cô để diệt khẩu mà lại uy hiếp cả dòng tộc Tạ gia để ép buộc Tạ Vãn Âm trở thành phu nhân quốc sư. Người đời đều đồn rằng quốc sư một thân áo trắng, bộc trực, cởi mở, chỉ có Tạ Vãn Âm biết hắn là một tên điên cực kỳ hung ác tàn bạo. Tạ Vãn Âm thà chết không chịu nghe theo, với bản tính quả cảm của mình, cô không do dự quyết định sẽ giết chết tên điên này. Đêm tân hôn, Tạ Vãn Âm quyết tâm ra tay với âm mưu đã ấp ủ bấy lâu. Chẳng ngờ, Đông Phương Túy lại cười tươi nắm chặt lấy cánh tay đang cầm con dao găm của Tạ Vãn Âm, thuận thế đâm con dao vào ngực mình. “Phu nhân muốn giết ta thì nói với ta một câu là được, không cần vòng vo như vậy.” Từ đó, Tạ Vãn Âm bắt đầu hành trình đấu trí với phu quân quốc sư của mình, nhưng dần dần, cô phát hiện ra Đông Phương Túy dường như khá giống với một người quen cũ khi nhỏ của mình. Và một âm mưu được nung nấu suốt vài năm liên quan tới người của hai triều đại cũng bắt đầu phía sau hai người, dần dần lộ rõ chân tướng.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Xuanlin","avatar":""},{"name":"李菲","avatar":""},{"name":"Wang Xingwei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
