INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-yeu-quai-cua-toi', 'Bạn Gái Yêu Quái Của Tôi', 'Boku no Itoshii Youkai Girlfriend', 'https://phimimg.com/upload/vod/20240903-1/4b205d32dccc0d67fcebf576a0bce1a6.jpg', 'https://phimimg.com/upload/vod/20240903-1/5c194a326e6e290c4ad74af288dd9394.jpg', '<p>Sinh viên đại học Tadashi &#39;Hachi&#39; Inukai mệt mỏi vì cảm thấy mình là kẻ thua cuộc. Nhưng tất cả thay đổi vào một ngày nọ khi anh vô tình thực hiện một nghi lễ bí ẩn tìm thấy trên mạng, triệu hồi một yêu quái quỷ dữ đến cõi phàm trần, có biệt danh là Izzy. Được liên kết bởi phép thuật, Hachi và Izzy phải tìm ra cách định hướng cuộc sống, tình yêu và giết người.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"佐野勇斗","avatar":""},{"name":"吉川愛","avatar":""},{"name":"Takashi Sorimachi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324229);
