INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liet-diem-truy-kich', 'Liệt Diễm Truy Kích', 'Fierce Hunt', 'https://phimimg.com/upload/vod/20240902-1/74ea37cd41626c3a5272102123bf10c2.jpg', 'https://phimimg.com/upload/vod/20240902-1/b77f5d704b4babac4967aa86f6f879bb.jpg', '<p>Thiên Hải, băng nhóm tội phạm do Hỏa Ca cầm đầu đã nhiều lần cướp tiệm vàng và nhiều lần thoát khỏi vòng vây của cảnh sát nhờ khả năng &quot;dự đoán hành động&quot; như có con mắt thần. Cảnh sát hình sự Văn Chương và thầy trò Trần Mặc được giao nhiệm vụ đối phó với tình huống nguy cấp này và nhanh chóng xác định được nghi phạm vốn luôn nằm ngoài tầm ngắm của cảnh sát. Tuy nhiên, Hỏa Ca không hề sợ hãi, liên tục thực hiện các vụ án táo bạo với mục đích khiêu khích cảnh sát... Trò chơi mèo vờn chuột giữa cảnh sát và tội phạm bắt đầu từ đây.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mingjian Zhang","avatar":""},{"name":"Luo Liqun","avatar":""},{"name":"于喜山","avatar":""},{"name":"Wanchen Zhai","avatar":""},{"name":"Chang Cheng","avatar":""},{"name":"赵小锐","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
