INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-menh-vo-thuong-tran', 'Tuyệt Mệnh Vô Thường Trấn', 'Death Town', 'https://phimimg.com/upload/vod/20240902-1/2bea344915fb987a847437c20147a704.jpg', 'https://phimimg.com/upload/vod/20240902-1/a51a4aa92efa4f950d7de6481f27576c.jpg', '<p>Trấn Vô Thường, nơi bao năm qua đã tránh xa khỏi chiến tranh và sống trong bình yên, bỗng liên tiếp xảy ra hàng loạt vụ tử vong bất ngờ. Trong quá trình điều tra, đội trưởng đội cảnh sát Trần Mặc đã cứu sống một cô gái trẻ tên Bạch Sương khỏi chết đuối. Nhờ sự hợp tác của Bạch Sương, họ nhiều lần đến hiện trường các vụ tử vong nhưng luôn thoát khỏi lưỡi hái của tử thần trong gang tấc. Những cái chết bất ngờ trước mắt nhiều người là do thiên tai hay nhân họa?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hao Ze","avatar":""},{"name":"王可","avatar":""},{"name":"海颜","avatar":""},{"name":"Zhang Luyao","avatar":""},{"name":"Qiu Bin","avatar":""},{"name":"Sun Xiaomin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324229);
