INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiet-huyet-thien-su', 'Nhiệt Huyết Thiên Sứ', 'Hot Blooded Angel', 'https://phimimg.com/upload/vod/20240902-1/95b2921c7e040365a97056a1396e77b3.jpg', 'https://phimimg.com/upload/vod/20240902-1/2416a9f52b9438786076a5129e113800.jpg', '<p>Bộ phim kể về câu chuyện của chị đại khu phố Tàu nơi đất khách quê người Quan Tinh. Nhờ vào tinh thần kiên cường, cô đã vượt qua muôn vàn khó khăn, cuối cùng đẩy lùi thế lực đen tối địa phương, bảo vệ khu phố Tàu. Nhân vật nữ chính Quan Tinh vừa chịu khó vừa chăm chỉ và dũng cảm, đối mặt với nhiều khó khăn và thử thách. Khi bị bọn côn đồ quấy rối, cô kiên quyết phản kháng, nghe theo lương tâm và cảm giác chính nghĩa của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"徐冬冬","avatar":""},{"name":"Michael Tong","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"黄涛","avatar":""},{"name":"Feng Yanyan","avatar":""},{"name":"郎贵钧","avatar":""},{"name":"梅景洪","avatar":""},{"name":"Wang Ruofei","avatar":""},{"name":"Sun Wenxue","avatar":""},{"name":"Liu Sasa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
