INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhiet-huyet-thien-su', 'Nhiệt Huyết Thiên Sứ', 'Hot Blooded Angel', 'nhiệt huyết thiên sứ hot blooded angel 徐冬冬 michael tong kent tong 黄涛 feng yanyan 郎贵钧 梅景洪 wang ruofei sun wenxue liu sasa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-dinh-ba', 'Cây Đinh Ba', 'Three Old Boys', 'https://phimimg.com/upload/vod/20240902-1/1aecbcf89f3029b51e8995af9531d0ad.jpg', 'https://phimimg.com/upload/vod/20240902-1/cecb67949ed9a5c066fd8c04480720ab.jpg', '<p>Hai mươi năm trước, ba cảnh sát lừng lẫy được giới cảnh sát vinh danh là &quot;Tam Xoa Kích&quot; (ba cây đinh ba) đã từng làm mưa làm gió. Giờ đây, đã sắp đến tuổi nghỉ hưu, họ bất ngờ phá được một vụ án rửa tiền lớn, đóng băng một khoản tiền phi pháp khổng lồ. Để giải phóng tài sản này, kẻ lừa đảo tài chính không ngần ngại thuê giang hồ sử dụng những biện pháp cực đoan. &quot;Tam Xoa Kích&quot; phải đối mặt với những đối thủ cũ từ 20 năm trước và chịu sự thách thức từ nhiều thế lực khác nhau. Đối diện với tội phạm kiểu mới, họ vẫn sử dụng các phương pháp truyền thống của cảnh sát để đối phó. Trước những cám dỗ khổng lồ từ đối thủ, mối quan hệ giữa ba người bắt đầu trở nên phức tạp. Nhưng trước trách nhiệm của một cảnh sát, họ cuối cùng đã đoàn kết và cùng nhau đánh bại tập đoàn tội phạm tài chính, đồng thời đưa những kẻ tham nhũng đứng sau ra trước pháp luật.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"黃志忠","avatar":""},{"name":"姜武","avatar":""},{"name":"郭濤","avatar":""},{"name":"歐豪","avatar":""},{"name":"韓庚","avatar":""},{"name":"Dong Yong","avatar":""},{"name":"金士傑","avatar":""},{"name":"魏晨","avatar":""},{"name":"邢佳栋","avatar":""},{"name":"蘇鑫","avatar":""},{"name":"Xu Li","avatar":""},{"name":"包贝尔","avatar":""},{"name":"Zhou Yunpeng","avatar":""},{"name":"Huang Lu","avatar":""},{"name":"陈都灵","avatar":""},{"name":"Zhao Ziqi","avatar":""},{"name":"He Dujuan","avatar":""},{"name":"Chunyang Zhao","avatar":""},{"name":"Xiaoguang Hu","avatar":""},{"name":"陈兵","avatar":""},{"name":"Meng Zhou","avatar":""},{"name":"陈国星","avatar":""},{"name":"Marc Ma","avatar":""},{"name":"孙之鸿","avatar":""},{"name":"Cao Weiyu","avatar":""},{"name":"Liu Xiaohai","avatar":""},{"name":"白紅標","avatar":""},{"name":"Hongjia Zhu","avatar":""},{"name":"Baode Wang","avatar":""},{"name":"黄小蕾","avatar":""},{"name":"Zhang Gasong","avatar":""},{"name":"Si Lig","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324229);
