INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cay-dinh-ba', 'Cây Đinh Ba', 'Three Old Boys', 'cây đinh ba three old boys 黃志忠 姜武 郭濤 歐豪 韓庚 dong yong 金士傑 魏晨 邢佳栋 蘇鑫 xu li 包贝尔 zhou yunpeng huang lu 陈都灵 zhao ziqi he dujuan chunyang zhao xiaoguang hu 陈兵 meng zhou 陈国星 marc ma 孙之鸿 cao weiyu liu xiaohai 白紅標 hongjia zhu baode wang 黄小蕾 zhang gasong si lig ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-ao-anh-thien-cung', 'Địch Nhân Kiệt: Ảo Ảnh Thiên Cung', 'Detective Dee: The Mirage in Heaven', 'https://phimimg.com/upload/vod/20240902-1/6b2c385ff1e5fedb50c1e5c7cff642c9.jpg', 'https://phimimg.com/upload/vod/20240902-1/78c28338c0b536d14303fae01a750bb7.jpg', '<p>Võ Tắc Thiên nhân dịp khánh thành Vạn Tượng Thần Cung, sắp xếp thợ thủ công tài ba sử dụng kỹ thuật phản chiếu ánh sáng, khiến cho phượng hoàng vàng trên đỉnh Vạn Tượng Thần Cung trở nên sống động, vỗ cánh bay lượn, và còn thu hút được hiện tượng chim muôn triều phượng, tạo nên cảnh tượng kỳ diệu khiến các quan lại kinh ngạc kêu lên rằng Võ Tắc Thiên chính là nữ thần của trời, thiên mệnh đã định. Võ Tắc Thiên có thể nhân cơ hội này thuận lợi lên ngôi, nhưng không ngờ rằng, đột nhiên trời nổi gió mây, trên trời xuất hiện thiên cung và giáng xuống thần tướng đá phá hủy phượng hoàng vàng, biến điềm lành thành điềm xấu. Võ Tắc Thiên nổi giận, lập tức triệu hồi Địch Nhân Kiệt về kinh điều tra vụ việc! Địch Nhân Kiệt lại một lần nữa nhận lệnh trong lúc nguy cấp, nhanh chóng ứng biến, bằng trí tuệ và sáng tạo đặc biệt của mình phá giải thêm một vụ án kỳ lạ!</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"李晟荣","avatar":""},{"name":"Li Zhen''an","avatar":""},{"name":"Zheng Qingwen","avatar":""},{"name":"Li Xiaopeng","avatar":""},{"name":"Xuan Yi Hao","avatar":""},{"name":"Wang Tung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324229);
