INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-ha-thuy-quai', 'Hoàng Hà Thủy Quái', 'Yellow River Monster', 'https://phimimg.com/upload/vod/20240902-1/dca3a6592d07c45bb426d044cf195fcb.jpg', 'https://phimimg.com/upload/vod/20240902-1/012c9b816c07c50668255e795bd32b73.jpg', '<p>Câu chuyện lấy bối cảnh vào cuối triều đại nhà Minh, kể về ba anh em Hiệu Liệt Vệ: Kỳ Phong, Dương Thập Nhất và Vân Tiếu Thiên. Họ đã giúp đỡ người dân dọc thượng nguồn sông Hoàng Hà tiêu diệt thủy quái sông Hoàng Hà đã gây họa nhiều năm tại địa phương, vạch trần đám lừa đảo mê tín phong kiến do Hoàng Hà nương nương đứng đầu, và mang lại cuộc sống yên bình cho người dân dọc bờ sông Hoàng Hà.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wei Wang","avatar":""},{"name":"Zhao Zhenhua","avatar":""},{"name":"Zhang Enshuo","avatar":""},{"name":"牛晓琳","avatar":""},{"name":"Shang Churan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324229);
