INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-bao-tam-long-bac-minh-con-cung', 'Đoạt Bảo Tầm Long: Bắc Minh Côn Cung', 'Treasure Hunting', 'https://phimimg.com/upload/vod/20240902-1/34aaf917c46e9cb1592828103a8df9a9.jpg', 'https://phimimg.com/upload/vod/20240902-1/e66d3ab01b4e720bb8af215d879de847.jpg', '<p>Câu chuyện này hư cấu về &quot;Kim Túc Vệ,&quot; những người bảo vệ quốc bảo truyền thống từ xưa. Câu chuyện diễn ra vào thời kỳ Dân Quốc, khi hậu duệ của Kim Túc Vệ đến vùng Đông Bắc để bảo vệ kho báu của tộc Nữ Chân, ngăn chặn người Nhật chiếm đoạt và điều tra bí mật về việc Kim Túc Vệ bị đàn áp. Ba nhân vật chính của bộ phim kiên quyết bảo vệ kho báu quốc gia, Lục Hoàn Sơn đã hy sinh thân mình để bảo vệ quốc bảo khỏi sự cướp bóc của kẻ xâm lược. Trong phim, nhân vật mặc giáp từ đầu bị ép buộc phải tìm kho báu cho người Nhật, cuối cùng đã hy sinh để tiêu diệt kẻ xâm lược Nhật Bản, thể hiện sự thức tỉnh về ý thức dân tộc và truyền tải tinh thần chủ đạo của sự đoàn kết dân tộc và anh dũng chống giặc.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chi Shuai","avatar":""},{"name":"Elaine Yi","avatar":""},{"name":"刘峰超","avatar":""},{"name":"Cheng Qimeng","avatar":""},{"name":"Shi Xuanru","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324229);
