INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-duong-thu-son-nhan', 'Âm Dương Thủ Sơn Nhân', 'Mountain Guardians', 'https://phimimg.com/upload/vod/20240902-1/5301e0f0d865cdd8d1dc1b5f5d911187.jpg', 'https://phimimg.com/upload/vod/20240902-1/e7fcf817e9800b4b6cd9ff8e8ca27882.jpg', '<p>Những năm đầu của thời Dân Quốc, quân phiệt hoành hành, yêu ma quỷ quái lộng hành. Người Nhật dòm ngó lãnh thổ Trung Hoa, đẩy nhanh bước tiến xâm lược. Âm Dương Sư Nhật Bản mang sứ mệnh bí ẩn, dưới danh nghĩa giao lưu văn hóa, đã sớm vào Trung Quốc, âm mưu tìm kiếm long mạch của Trung Hoa, phá hoại phong thủy Hoa Hạ, để mở đường cho cuộc xâm lược sau này. Nhóm đạo sĩ dân gian Trung Quốc, đứng đầu là Thất thúc, cuối cùng đã phát hiện ra âm mưu của Âm Dương Sư Nhật Bản. Họ gánh vác đại nghĩa dân tộc, hy sinh thân mình để bảo vệ long mạch, và tiến hành một cuộc đấu tranh giữa âm mưu và đạo pháp với Âm Dương Sư Nhật Bản...</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ge Shuai","avatar":""},{"name":"Wang Ruixuan","avatar":""},{"name":"Fan Zhengjun","avatar":""},{"name":"Chen Youjun","avatar":""},{"name":"Xie Yizhen","avatar":""},{"name":"Zhetao Chang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324229);
