INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-thoai-2', 'Thần Thoại 2', 'A Legend', 'https://phimimg.com/upload/vod/20240901-1/04177ec08b63d24568321f2061b4bce6.jpg', 'https://phimimg.com/upload/vod/20240901-1/653a7da3d1c53cdc2591064584cbfbdc.jpg', '<p>Một nhà khảo cổ học nhận thấy rằng kết cấu của các di tích được phát hiện trong quá trình khai quật sông băng gần giống với mặt dây chuyền ngọc bích được nhìn thấy trong một trong những giấc mơ của ông. Ông và nhóm của mình sau đó bắt tay vào một cuộc thám hiểm vào độ sâu của sông băng.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"成龍","avatar":""},{"name":"Zhang Yixing","avatar":""},{"name":"古力娜扎","avatar":""},{"name":"Aarif Rahman","avatar":""},{"name":"Jerry Lee","avatar":""},{"name":"Peng Xiaoran","avatar":""},{"name":"竇驍","avatar":""},{"name":"鄭業成","avatar":""},{"name":"Ma Yuan","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Jin QiaoQiao","avatar":""},{"name":"Ma Yanli","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Stanley Tong","avatar":""},{"name":"김희선","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324229);
