INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-quan-gia-phan-4', 'Hắc Quản Gia (Phần 4)', 'Black Butler (Season 4)', 'https://phimimg.com/upload/vod/20240630-1/1170054f22f308f7b480fcdd777339e3.jpg', 'https://phimimg.com/upload/vod/20240630-1/cbd1ab72ac82a509b06eb48aaae64e4a.jpg', '<p>Gia tộc Phantomhive nhiều đời làm “người dọn dẹp” trong bóng tối của hòang gia Anh. Chủ nhân hiện tại của Phantomhive là Ciel Phantomhive, một cậu bé 12 tuổi với tính cách khá lạnh lùng. Ciel là người quản lý công việc kinh doanh của Phantomhive và cũng là người khiến nó ngày càng phát triển hơn. Phục vụ cho Ciel là quản gia Sebastian Michaels, một nhân vật đen từ đầu tới chân (cũng như từ trong ra ngòai). Cái tên của Sebastian cũng là do Ciel đặt, không ai biết rõ lai lịch của Sebastian. Sebastian là một quản gia đầy tài năng, gần như là hòan hảo, hầu như bất cứ việc gì anh ta cũng biết làm , và vì một lý do nào đó, anh ta hết mực trung thành với Ciel, giúp đỡ Ciel rất nhiều trong mọi việc…</p>', 'Full', 11, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"小野大輔","avatar":""},{"name":"坂本真綾","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324229);
