INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-than-quen-ban-thai', 'Người Vợ Thân Quen (Bản Thái)', 'Yesterday Wife', 'https://phimimg.com/upload/vod/20240823-1/42d7d5be062efadd802d40a1ccc4c780.webp', 'https://phimimg.com/upload/vod/20240823-1/b032bbd2c4d6a3c5c118f3167574a146.jpg', '<p>Được làm lại từ phim Hàn Quốc cùng tên, Người Vợ Thân Quen (Bản Thái) là câu chuyện &quot;đổi vợ&quot; đầy oái oăm của Poom. Thường xuyên cãi vã với cô vợ Prapye, Poom luôn bất mãn với cuộc hôn nhân hiện tại. Một ngày nọ, Poom bất ngờ được tái sinh vào một cuộc sống mới sung túc và cả một người vợ mới là Nalin, người thương thời đại học mà anh vẫn còn vương vấn bấy lâu nay. Poom cứ tưởng mình đã có được cuộc hôn nhân trong mơ, nhưng &quot;vợ cũ&quot; Prapye lại xuất hiện trong kiếp mới của anh, và giữa họ vẫn tồn tại một sức hút vô hình.</p>', 'Tập 14', 14, 'series', 'ongoing', 12, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Anchasa Mongkhonsamai","avatar":""},{"name":"Chaiyapol Pupart","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
