INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('borderlands-tro-lai-pandora', 'Borderlands: Trở Lại Pandora', 'Borderlands', 'https://phimimg.com/upload/vod/20240901-1/1686c4e128ff026e902c041287529b91.jpg', 'https://phimimg.com/upload/vod/20240901-1/8fcffcbebd44e4849c43c1f3fc7c1623.jpg', '<p>Trở về hành tinh quê nhà, một kẻ ngoài vòng pháp luật khét tiếng hình thành một liên minh bất ngờ với một nhóm gồm những anh hùng bất ngờ. Cùng nhau, họ chiến đấu với những con quái vật ngoài hành tinh và những tên cướp nguy hiểm để tìm kiếm một cô gái mất tích nắm giữ chìa khóa của sức mạnh không thể tưởng tượng được.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cate Blanchett","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Edgar Ramírez","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Ariana Greenblatt","avatar":""},{"name":"Florian Munteanu","avatar":""},{"name":"Janina Gavankar","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Benjamin Byron Davis","avatar":""},{"name":"Olivier Richters","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Ryann Redmond","avatar":""},{"name":"Bobby Lee","avatar":""},{"name":"Sophie Popper","avatar":""},{"name":"Haley Bennett","avatar":""},{"name":"Riana Emma Balla","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324229);
