INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('borderlands-tro-lai-pandora', 'Borderlands: Trở Lại Pandora', 'Borderlands', 'borderlands: trở lại pandora borderlands cate blanchett kevin hart edgar ramírez jamie lee curtis ariana greenblatt florian munteanu janina gavankar jack black benjamin byron davis olivier richters gina gershon ryann redmond bobby lee sophie popper haley bennett riana emma balla ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thong-tha-nhip-yeu', 'Thong Thả Nhịp Yêu', 'Love Andante', 'https://phimimg.com/upload/vod/20240830-1/b221564da46180797a14cde3267f8e44.jpg', 'https://phimimg.com/upload/vod/20240830-1/9a91a58a36f6a9a67d86980f340d4287.jpg', '<p>Trong tương lai gần, Hàn Quốc và Triều Tiên thành lập một &quot;Làng Hòa Bình&quot; để thử nghiệm trong quá trình thảo luận về việc thống nhất. Cả hai quốc gia cho người dân hai miền Bắc và Nam sống ở đó trong một năm để tạo ra hình ảnh tích cực về việc thống nhất. Tuy nhiên, do một sai sót, nghệ sĩ dương cầm nổi tiếng của Hàn Quốc là Joo Hyung và con gái của một quan chức cấp cao của Bắc Triều Tiên là Na Gyeong bị xếp vào cùng một ngôi nhà. Vì lợi ích của việc thống nhất, cả hai quyết định đồng ý chia sẻ ngôi nhà trong một năm. Joo Hyung kiêu ngạo không thích Na Gyeong lạnh lùng, nhưng có câu trái dấu thì hút nhau. Joo Hyung bắt đầu có cảm tình với Na Gyeong, người tuy bướng bỉnh nhưng chu đáo. Cả hai sớm nhận ra tình cảm của mình dành cho nhau nhưng không thể thổ lộ, biết rằng họ sẽ phải chia tay sau một năm. Sau đó, cha của Na Gyeong bất ngờ đến thăm, nói rằng &quot;Phải phá hủy Làng Hòa Bình!&quot; Những người hàng xóm đoàn kết để bảo vệ hòa bình và tình yêu đích thực.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kwon Hyun-bin","avatar":""},{"name":"Song Ji-woo","avatar":""},{"name":"Ji Won","avatar":""},{"name":"Hong Jun-ki","avatar":""},{"name":"Ki Hyun-woo","avatar":""},{"name":"Kim Sun-je","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca