INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-vo-dich-2024', 'Nhà Vô Địch', 'Chandu Champion', 'https://phimimg.com/upload/vod/20240827-1/e1f2cd2f6ee9c5f61e94a7e96f0ecf3f.jpg', 'https://phimimg.com/upload/vod/20240827-1/010142aedfd0513fca4b78ba1edb84c0.jpg', '<p>9 vết đạn (một vết vẫn còn trên người), ba môn thể thao khác nhau và quyết tâm không thể lay chuyển để thực hiện ước mơ huy chương Vàng Olympic sau này, Muralikant Petkar, vận động viên Paralympic đầu tiên của Ấn Độ về đích ở vị trí cao nhất trên bục vinh quang, đã được chính đất nước mình công nhận 45 năm sau khi anh đạt được điều mà không vận động viên nào ở đất nước anh có thể làm được.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"कार्तिक आर्यन","avatar":""},{"name":"Vijay Raaz","avatar":""},{"name":"Bhuvan Arora","avatar":""},{"name":"Rajpal Yadav","avatar":""},{"name":"Yashpal Sharma","avatar":""},{"name":"Aniruddh Dave","avatar":""},{"name":"Himangi Kavi","avatar":""},{"name":"Nitin Bhajan","avatar":""},{"name":"Shreyas Talpade","avatar":""},{"name":"Brijendra Kala","avatar":""},{"name":"Dilnaz Irani","avatar":""},{"name":"Bhagyashree Borse","avatar":""},{"name":"Sonali Kulkarni","avatar":""},{"name":"Gavie Chahal","avatar":""},{"name":"Pushkaraj Chirputkar","avatar":""},{"name":"Ganesh Yadav","avatar":""},{"name":"Jagat Ra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
