INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-vo-dich-2024', 'Nhà Vô Địch', 'Chandu Champion', 'nhà vô địch chandu champion कार्तिक आर्यन vijay raaz bhuvan arora rajpal yadav yashpal sharma aniruddh dave himangi kavi nitin bhajan shreyas talpade brijendra kala dilnaz irani bhagyashree borse sonali kulkarni gavie chahal pushkaraj chirputkar ganesh yadav jagat ra ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tau-thoat-2024', 'Tẩu Thoát', 'Escape', 'https://phimimg.com/upload/vod/20240827-1/e14d736f3d7b35682c74fe35d9723242.jpg', 'https://phimimg.com/upload/vod/20240827-1/cb276e1d704c33f4461989ab2b8befda.jpg', '<p>Trại quân đội gần Khu phi quân sự của một đất nước bị chia cắt, nơi phía Nam là vùng đất của tự do, còn phía đối diện là vùng đất của sự đàn áp. Thượng sĩ Kyu Nam, người đã lên kế hoạch đào thoát sang phía Nam từ lâu, bị bắt khi ngăn cản một binh lính bình thường, Dong Hyuk, trốn thoát. Đứng trước nguy cơ bị xử án tử hình, Trung tá Cục An ninh Quốc gia Hyun Sang nhận ra Kyu Nam từ thời thơ ấu. Thay vì cáo buộc anh, Hyun Sang quyết định làm cho Kyu Nam trở thành một anh hùng đã bắt giữ một kẻ đào ngũ. Vì vậy, Hyun Sang đã thành công trong việc bảo vệ hồ sơ thành tích của mình bằng cách cứu mạng Kyu Nam. Tuy nhiên, Kyu Nam vẫn muốn sống theo ý chí của riêng mình, không phải theo mệnh lệnh của chính phủ. Anh không bao giờ từ bỏ việc vượt biên. Ngược lại, Hyun Sang quyết liệt ngăn cản Kyu Nam để bảo vệ cuộc sống của chính mình, một cuộc sống đã được xây dựng bằng việc từ bỏ giấc mơ của mình.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"이제훈","avatar":""},{"name":"구교환","avatar":""},{"name":"홍사빈","avatar":""},{"name":"서현우","avatar":""},{"name":"이성욱","avatar":""},{"name":"Yoo Tae-joo","avatar":""},{"name":"정준원","avatar":""},{"name":"장영남","avatar":""},{"name":"송강","avatar":""},{"name":"이솜","avatar":""},{"name":"이호정","avatar":""},{"name":"신현지","avatar":""},{"name":"이호철","avatar":""},{"name":"Kim Sang-heun","avatar":""},{"name":"Park Yoon-hee","avatar":""},{"name":"Woo Jeong-won","avatar":""},{"name":"차순배","avatar":""},{"name":"Song Yo-sep","avatar":""},{"name":"Jin Yong-uk","avatar":""},{"name":"Jang Yo-hoon","avatar":""},{"name":"O Seung-baek","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
