INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-may-tinh-yeu', 'Thang Máy Tình Yêu', 'Elevator', 'https://phimimg.com/upload/vod/20240827-1/b51570268b41bfdf7aebcbde4ffd3e3c.jpg', 'https://phimimg.com/upload/vod/20240827-1/80cea1cc549c0ff8e433630e0bd7dd57.jpg', '<p>Bị mắc kẹt bên trong thang máy của một khu phức hợp sòng bạc khách sạn, một chàng trai thang máy tầm thường đã phải lòng nhân tình của nhà đầu tư, buộc anh phải lựa chọn giữa tình yêu dành cho cô hoặc ước mơ về một tương lai tốt đẹp hơn.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Paulo Avelino","avatar":""},{"name":"Kylie Verzosa","avatar":""},{"name":"Adrian Pang","avatar":""},{"name":"Chai Fonacier","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324229);
