INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-khong-loi', 'Tình Yêu Không Lời', 'Silent Love', 'https://phimimg.com/upload/vod/20240827-1/bdc530d789232dbf056121b77f4aab7e.jpg', 'https://phimimg.com/upload/vod/20240827-1/9f22573da1e2d9f1b192a0aad8b7c7f3.jpg', '<p>Câu chuyện xoay quanh chàng trai trẻ Aoi (Ryosuke Yamada) thầm yêu nữ học viên Mika (Minami Hamabe) với khao khát trở thành nghệ sĩ piano. Một tai nạn bất ngờ đã khiến Mika mất đi thị lực, Aoi vẫn luôn âm thầm bên cạnh và dùng sự dịu dàng vụng về của mình bảo vệ cô. Nhưng số mệnh như một dòng nước đục ngầu cuốn đi chuyện tình thuần khiết đang còn dở dang.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"古田新太","avatar":""},{"name":"浜辺美波","avatar":""},{"name":"円井 わん","avatar":""},{"name":"中島歩","avatar":""},{"name":"Shuhei Nogae","avatar":""},{"name":"野村周平","avatar":""},{"name":"Takuro Tatsumi","avatar":""},{"name":"Ryosuke Yamada","avatar":""},{"name":"吉村界人","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
