INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-bao-oan', 'Linh Hồn Báo Oán', 'Oddity', 'https://phimimg.com/upload/vod/20240827-1/b0f741796955d0a0e5618ac54381992a.jpg', 'https://phimimg.com/upload/vod/20240827-1/775d6595c5bb0fe602a1c8e1fae67223.jpg', '<p>Một bộ phim kinh dị siêu nhiên của Ireland năm 2024 do Damian Mc Carthy đạo diễn. Bộ phim kể về Darcy, một người mù sở hữu cửa hàng đồ cổ và là người thông linh, người đang cố gắng tìm hiểu nguyên nhân cái chết bí ẩn của người chị em sinh đôi Dani. Darcy sử dụng những vật phẩm bị ám từ cửa hàng của mình để khám phá sự thật, dẫn đến những chạm trán rùng rợn với thế lực siêu nhiên.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Carolyn Bracken","avatar":""},{"name":"Jonathan French","avatar":""},{"name":"Steve Wall","avatar":""},{"name":"Joe Rooney","avatar":""},{"name":"Gwilym Lee","avatar":""},{"name":"Tadhg Murphy","avatar":""},{"name":"Caroline Menton","avatar":""},{"name":"Ivan de Wergifosse","avatar":""},{"name":"Shane Whisker","avatar":""},{"name":"Josuha Campbell","avatar":""},{"name":"Austin Lawlor","avatar":""},{"name":"Peter McCarthy","avatar":""},{"name":"Fiach McHugh","avatar":""},{"name":"Patrick Mullins","avatar":""},{"name":"Jim O''Donnell","avatar":""},{"name":"Inma Pavon","avatar":""},{"name":"Leticia","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324229);
