INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-janet', 'Hành Tinh Janet', 'Janet Planet', 'https://phimimg.com/upload/vod/20240827-1/60f3eb87d0f7f6b1f99336f944534d2c.jpg', 'https://phimimg.com/upload/vod/20240827-1/db4a6c617eadfd4498f1202fdea23e78.jpg', '<p>Ở vùng nông thôn Tây Massachusetts, Lacy 11 tuổi dành mùa hè năm 1991 ở nhà, bị mê hoặc bởi trí tưởng tượng của chính mình và sự chú ý của mẹ cô, Janet. Nhiều tháng trôi qua, ba du khách bước vào quỹ đạo của họ, tất cả đều bị quyến rũ bởi Janet.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Julianne Nicholson","avatar":""},{"name":"Zoe Ziegler","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Luke Bosco","avatar":""},{"name":"June Walker Grossman","avatar":""},{"name":"Abby Harri","avatar":""},{"name":"Edie Moon Kearns","avatar":""},{"name":"Mary Beth Brooker","avatar":""},{"name":"Mary Shultz","avatar":""},{"name":"Jeremy Louise Eaton","avatar":""},{"name":"Raky Sastri","avatar":""},{"name":"John Peitso","avatar":""},{"name":"Carolyn Walker","avatar":""},{"name":"Matthew Glassman","avatar":""},{"name":"Ge","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
