INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harold-va-cay-but-phep-thuat', 'Harold và Cây Bút Phép Thuật', 'Harold and the Purple Crayon', 'https://phimimg.com/upload/vod/20240827-1/42420a222f8d567960f872e287a2638d.jpg', 'https://phimimg.com/upload/vod/20240827-1/f1177daff40eda6c1c10e6f6d57abcfe.jpg', '<p>Cốt truyện dựa trên bộ truyện cùng tên - được xuất bản vào năm 1955. Cuốn sách của Crockett Johnson kể về Harold, một cậu bé 4 tuổi, với sức mạnh của cây bút chì màu, đã tạo ra thế giới xung quanh mình. Harold sử dụng cây bút chì màu tím kì diệu của mình để vẽ một cánh cửa dẫn vào Thế giới Thực, nơi anh và những người bạn của mình dấn thân vào một cuộc phiêu lưu mới lạ.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Zachary Levi","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Benjamin Bottani","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Tanya Reynolds","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Ravi Patel","avatar":""},{"name":"Camille Guaty","avatar":""},{"name":"Pete Gardner","avatar":""},{"name":"Zele Avradopoulos","avatar":""},{"name":"Patrice Fisher","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324229);
