INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-tran', 'Cẩu Trận', 'Black Dog', 'https://phimimg.com/upload/vod/20240827-1/57c48b97732af025688d377522f29118.jpg', 'https://phimimg.com/upload/vod/20240827-1/830a5d628cb91dacc89b7c82e52aa3c9.jpg', '<p>Bộ phim lấy bối cảnh ở rìa sa mạc Gobi phía Tây Bắc Trung Quốc, xoay quanh một người đàn ông trở về quê hương sau khi ra tù. Trong khi làm việc cho đội tuần tra địa phương để dọn sạch những chú chó đi lạc trong thị trấn trước khi Thế vận hội Olympic diễn ra, anh bỗng có một mối liên hệ khó tin với một chú chó đen. Cả hai đều mang tâm hồn đơn độc và quyết định cùng nhau đi tìm cuộc hành trình mới.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"彭于晏","avatar":""},{"name":"佟麗婭","avatar":""},{"name":"Jia Zhangke","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"周遊","avatar":""},{"name":"Yuan Hong","avatar":""},{"name":"魏晨","avatar":""},{"name":"Yanhui Wang","avatar":""},{"name":"张建亚","avatar":""},{"name":"Zhang Yang","avatar":""},{"name":"Wang Yiquan","avatar":""},{"name":"Xiaoguang Hu","avatar":""},{"name":"Yin Yuanzhang","avatar":""},{"name":"张立","avatar":""},{"name":"Motu Hongzhe","avatar":""},{"name":"Da Youwei","avatar":""},{"name":"吴优","avatar":""},{"name":"楚布花羯","avatar":""},{"name":"Wang Naixun","avatar":""},{"name":"趙毅","avatar":""},{"name":"Ben Niu","avatar":""},{"name":"Qiang Gao","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"梁靜","avatar":""},{"name":"Huang Miyi","avatar":""},{"name":"Sha Baoliang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
