INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-xoa-sach-dau-vet', 'Biệt Đội Xóa Sạch Dấu Vết', 'The Clean Up Crew', 'https://phimimg.com/upload/vod/20240827-1/f499a57a901cf42fb90f0d252cf1aae0.jpg', 'https://phimimg.com/upload/vod/20240827-1/5e1dfc7752ae0857f2fd8d0ce04d7a00.jpg', '<p>Theo chân một nhóm chuyên gia làm sạch hiện trường sau các vụ giết người. Họ không chỉ đơn thuần dọn dẹp, mà còn khéo léo xóa mọi dấu vết, giúp các tội phạm trốn thoát khỏi sự truy lùng của pháp luật. Nhưng khi họ vô tình phát hiện ra một bí mật đen tối liên quan đến một tổ chức ngầm đầy quyền lực, cả nhóm bị cuốn vào cuộc chiến sinh tử. Đứng giữa lựa chọn bảo vệ bản thân hay đối đầu với một thế lực đáng sợ, họ phải đưa ra những quyết định mang tính sống còn.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Swen Temmel","avatar":""},{"name":"Laurence Kinlan","avatar":""},{"name":"Andy Kellegher","avatar":""},{"name":"Conor Mullen","avatar":""},{"name":"Matthew Tompkins","avatar":""},{"name":"Ian Toner","avatar":""},{"name":"Elaine Purdue","avatar":""},{"name":"Gavin Coventry","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
