INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-doi-xoa-sach-dau-vet', 'Biệt Đội Xóa Sạch Dấu Vết', 'The Clean Up Crew', 'biệt đội xóa sạch dấu vết the clean up crew jonathan rhys meyers melissa leo antonio banderas swen temmel laurence kinlan andy kellegher conor mullen matthew tompkins ian toner elaine purdue gavin coventry ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-sau-su-that', 'Đằng Sau Sự Thật', 'The Whole Truth', 'https://phimimg.com/upload/vod/20240824-1/efb965f079d2477d9219b1a37373c9fd.jpg', 'https://phimimg.com/upload/vod/20240824-1/b5d94a13e9bf7a37080c123c5f5032af.jpg', '<p>Vào một đêm khuya, tại khu phố cổ của một thành phố ven biển đã xảy ra một vụ án mạng ly kỳ. Quan Kính Đường, một người đàn ông cao tuổi có danh vọng tại địa phương chết thảm trong chính căn biệt thự của mình. Đội trưởng cảnh sát hình sự An Bình được giao nhiệm vụ điều tra vụ án. Học viên xuất sắc của sở cảnh sát tỉnh - Thượng Tiệp chủ động xin hỗ trợ. Cả hai phối hợp hết mình, tiến hành một cuộc điều tra kỹ lưỡng. Tuy nhiên, càng đi sâu vào điều tra, những nghi vấn mâu thuẫn xuất hiện ngày càng nhiều, thêm vào đó là một lượng lớn tiền mặt không rõ tung tích, người phụ nữ mặc áo đỏ như đã từng quen, hình vẽ những bông hoa đỏ thẫm như máu, cùng các mối quan hệ phức tạp của gia đình họ Quan khiến vụ án trở nên mơ hồ hơn bao giờ hết. Không chỉ vậy, những vụ án mạng vẫn tiếp tục nối đuôi nhau xảy ra, các nạn nhân đều có mối quan hệ mật thiết với Quan Kính Đường.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"韓棟","avatar":""},{"name":"屈菁菁","avatar":""},{"name":"張皓然","avatar":""},{"name":"上淇","avatar":""},{"name":"Aliyah","avatar":""},{"name":"易大千","avatar":""},{"name":"Yang Yu","avatar":""},{"name":"邵庄","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324229);
