INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nguoi-den-chet', 'Yêu Người Đến Chết', 'Club Friday Season 16 : Love You To Death', 'https://phimimg.com/upload/vod/20240826-1/7e88a942a1e35d9c3d2197eec4084ec7.jpg', 'https://phimimg.com/upload/vod/20240826-1/846481b4d1e70528603fbd23132e7aab.jpg', '<p>Yêu Người Đến Chết là câu chuyện đau lòng về cách sự hoài nghi giết chết một cuộc hôn nhân. Sau nhiều lần bị chồng hoài nghi ngoại tình, Foon đau lòng đến mức chỉ có thể đề nghị ly hôn. Nào ngờ quyết định của Foon lại khiến chồng cô nghĩ quẩn. Foon sẽ phải đối mặt thế nào với một mất mát lớn như thế?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Praew Narupornkamol Chaisang","avatar":""},{"name":"Garfield Pantach Kankham","avatar":""},{"name":"Plan Thanawat Koosuwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
