INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-cam-hay-la-tinh-ich-k', 'Trầm Cảm Hay Là Tình Ích K', 'Club Friday Season 16 : Depression Or Just Selfishness', 'https://phimimg.com/upload/vod/20240826-1/c3542b37c76fddacbbfa7a19d5b67ede.jpg', 'https://phimimg.com/upload/vod/20240826-1/046c2ac8ddebf528a881636200c5e927.jpg', '<p>Trầm Cảm Hay Là Tình Ích Kỷ là câu chuyện về một mối tình luôn bị ám ảnh bởi bóng ma của quá khứ. Rin muốn có được tình yêu của Nont nhưng anh vẫn không thể quên người bạn gái đã mất ba năm trước. Điều này khiến Rin đau buồn và càng ngày càng lún sâu vào hố sâu tuyệt vọng. Liệu họ có thể trút bỏ gánh nặng tâm lý để tìm thấy hạnh phúc thật sự hay không?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pim Pimprapa Tangprabhaporn","avatar":""},{"name":"March Chutavuth Pattarakhumphol","avatar":""},{"name":"Pim Latkamon Pinrojkirati","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
