INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-cuong-tin', 'Tình Yêu Cuồng Tín', 'Club Friday Season 16 : Love Superstitions', 'https://phimimg.com/upload/vod/20240826-1/5a783dae88987104196152306e6d18e6.png', 'https://phimimg.com/upload/vod/20240826-1/76b8f287cd7a801df67a20b4424d27b0.jpg', '<p>Là một người mê tín, Namfon luôn nghe lời thầy bói trong mọi vấn đề của cuộc sống, từ chuyện công việc đến cá nhân. Dù đã biết chuyện này từ trước khi kết hôn, Oat vẫn chấp nhận vì yêu cô. Nhưng liệu tình yêu đó có đủ mạnh để vượt qua sóng gió hôn nhân khi cả hai bắt đầu tính đến chuyện con cái và Namfon vẫn để yếu tố tâm linh can thiệp vào quyết định trọng đại này?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Toon Pimpawee Kograbin","avatar":""},{"name":"Pangpond Akalavut Mankalasut","avatar":""},{"name":"Took Chanokwanun Rakcheep","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
