INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-tren-ung-dung-hen-ho', 'Bí Mật Trên Ứng Dụng Hẹn Hò', 'Club Friday Season 16 Secret Of Dating Apps', 'https://phimimg.com/upload/vod/20240825-1/e998e74c11a31b92304a6ff92a240e9d.jpg', 'https://phimimg.com/upload/vod/20240825-1/4e58ab7237e3c7d259e71bb4871d2a24.jpg', '<p>Khi công nghệ ngày càng phát triển, việc hẹn hò trong xã hội hiện đại càng ngày càng dễ dàng hơn. Nhưng dù hẹn hò bằng hình thức nào thì sự chân thành vẫn là nền tảng quan trọng để có được tình yêu bền vững. Đó chính là bài học mà cô nàng sinh viên Ploy đúc kết được một cách cay đắng sau hàng loạt mối tình đầy sóng gió với các anh chàng mà cô quen qua ứng dụng hẹn hò.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Punpun Sutatta Udomsilp","avatar":""},{"name":"Jackie Jackrin Kungwankiatichai","avatar":""},{"name":"Lay Talay Sanguandikul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
