INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-mat-tren-ung-dung-hen-ho', 'Bí Mật Trên Ứng Dụng Hẹn Hò', 'Club Friday Season 16 Secret Of Dating Apps', 'bí mật trên ứng dụng hẹn hò club friday season 16 secret of dating apps punpun sutatta udomsilp jackie jackrin kungwankiatichai lay talay sanguandikul ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-nay-khong-co-dau-dua', 'Tình Yêu Này Không Có Đậu Đũa', 'This Love Doesn''t Have Long Beans', 'https://phimimg.com/upload/vod/20240719-1/da2dea530cdc9e61a9505ce73e846490.jpg', 'https://phimimg.com/upload/vod/20240719-1/9057cca2fa565650565139c1b3983dce.jpg', '<p>Đầu bếp tre siêu hot sở hữu một nhà hàng nổi tiếng với món ăn pad krapow (thịt xào húng quế) của Thái Lan, Chef Aob muốn cho thuê nhà hàng của mình cho người thật sự yêu thích pad krapow, với điều kiện người đó không được bán lại nhà hàng cho bất kỳ ai. Sau đó, một cuộc thi tuyển chọn đầu bếp tiếp theo đã diễn ra và khiến Chef Oab gặp đượcmột chàng người mẫu trẻ tuổi “Whale”, người đã thay đổi cuộc đời khi được phân công tham gia cuộc thi món ăn pad krapow này để trở thành chủ nhà hàng. Nhưng mục tiêu thực chất là bán nhà hàng đi sau khi giành chiến thắng. Trong khi mối quan hệ giữa Whale và Chef Oab ngày càng bền chặt với những khoảnh khắc ngọt ngào lẫn cay đắng, Chef Oab phát hiện ra động cơ thực sự của Whale và quyết định để lại nhà hàng yêu quý của mình cho anh ta. Whale cảm thấy tội lỗi và hy vọng một ngày nào đó Chef Oab sẽ quay trở lại.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sailub Hemmawich Kwanamphaiphan","avatar":""},{"name":"Pon Thanapon Aiemkumchai","avatar":""},{"name":"Pantach Kankham","avatar":""},{"name":"Benz Atthanin Thaninphanuwiwat","avatar":""},{"name":"Michael Kiettisak Vatanavitsakul","avatar":""},{"name":"Lee Asre Wattanayakul","avatar":""},{"name":"Tanawat Hudchaleelaha","avatar":""},{"name":"Aon Kasama Khamtanit","avatar":""},{"name":"Belle Jiratchaya Kittavornsakul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c4301