INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-loi-thoat-2024', 'Không Lối Thoát', 'No Way Out The Roulette', 'https://phimimg.com/upload/vod/20240811-1/15044c097565ae7096db86087a621d81.jpg', 'https://phimimg.com/upload/vod/20240811-1/c2cabc8bd655ce39ddb52ec7f2a7e7d6.jpg', '<p>Phim tập trung vào một vụ án mạng bí ẩn, liên quan đến một khoản tiền thưởng khổng lồ dành cho kẻ ám sát một tên tội phạm khét tiếng. Các nhân vật chính, những người đang ở vào đường cùng trong cuộc sống, quyết định tham gia vào cuộc chơi nguy hiểm này với hy vọng đổi đời. Tuy nhiên, càng đi sâu vào vụ án, họ càng nhận ra rằng mình đang bị cuốn vào một âm mưu phức tạp và nguy hiểm hơn nhiều so với tưởng tượng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"조진웅","avatar":""},{"name":"유재명","avatar":""},{"name":"염정아","avatar":""},{"name":"김무열","avatar":""},{"name":"이광수","avatar":""},{"name":"許光漢","avatar":""},{"name":"김성철","avatar":""},{"name":"성유빈","avatar":""},{"name":"현봉식","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
