INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-khu-chinh-cang', 'Phân Khu Chính Cảng', 'GG Precinct', 'https://phimimg.com/upload/vod/20240822-1/0b78350cd9309dedc1671500b6a41df4.jpg', 'https://phimimg.com/upload/vod/20240822-1/9f99219450865edfd31ad0ebdca40c02.jpg', '<p>Đối mặt loạt án mạng dàn dựng dưới dạng trò chơi đố chữ rùng rợn, đội trưởng cảnh sát mới và một thám tử ngu ngơ chạy đua để giải những câu đố chết chóc của gã sát nhân hàng loạt.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"許光漢","avatar":""},{"name":"王淨","avatar":""},{"name":"馬念先","avatar":""},{"name":"Ki-pin Ng","avatar":""},{"name":"LULU Huang","avatar":""},{"name":"林鶴軒","avatar":""},{"name":"Chen Yen-Tso","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324229);
