INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-kiem-sat-vien-so-9', 'Phòng Kiểm Sát Viên Số 9', 'For The Young Ones', 'https://phimimg.com/upload/vod/20240818-1/2d534d424baa3b8cfa6ef8318bf23179.jpg', 'https://phimimg.com/upload/vod/20240818-1/2c56793ea4a33d49c36f9f598147366d.jpg', '<p>Giám đốc Lôi Húc (do Trương Dịch thủ vai) của bộ phận kiểm sát thiếu niên được điều động đột xuất, cùng với kiểm sát viên Đô Tử Du (do Tần Lam thủ vai), thư ký viên Dương Điềm (do Từ Phàm thủ vai), cảnh sát tư pháp Từ Trương Lệ (do Vương Chân Nhi thủ vai) và các thành viên khác trong Bộ Chín đang xử lý một vụ án hình sự liên quan đến người chưa thành niên, thì vụ án bất ngờ xảy ra đảo ngược. Đồng thời, một nghi phạm thiếu niên trong vụ án chết do tai nạn cũng lọt vào tầm ngắm của Bộ Chín... Những vụ án tưởng chừng không liên quan gì đến nhau nhưng lại có mối liên hệ chặt chẽ. Các kiểm sát viên của Bộ Chín từng bước điều tra ra sự thật đằng sau các vụ án, đưa tội phạm ra trước pháp luật. Họ đồng lòng bảo vệ thanh thiếu niên, dùng tình yêu để nuôi dưỡng tương lai, hy vọng một ngày nào đó sẽ không còn vụ án nào để xử lý!</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Yi","avatar":""},{"name":"秦嵐","avatar":""},{"name":"徐帆","avatar":""},{"name":"Wang Zhener","avatar":""},{"name":"Zou Yuanqing","avatar":""},{"name":"Jia Xiaohan","avatar":""},{"name":"Li Hongtao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324229);
