INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-thu', 'Lớp Thú', 'Mammals', 'https://phimimg.com/upload/vod/20240731-1/2e2590ee55320ab65f077216a74a20fe.jpg', 'https://phimimg.com/upload/vod/20240731-1/e7cbff9f76d22fa29a0ec2aa0087aae4.jpg', '<p>Bộ truyện cung cấp những hiểu biết thú vị về nhóm động vật thành công nhất trên thế giới. Từ chuột chù Etruscan nhỏ bé đến cá voi xanh khổng lồ, Động vật có vú sẽ tiết lộ bí mật thành công của chúng và thiết kế chiến thắng, khả năng thích ứng đáng kinh ngạc, trí thông minh vô song và khả năng hòa đồng độc đáo của chúng đều góp phần vào sự phát triển đáng chú ý của chúng.</p>', 'Tập 6', 6, 'series', 'ongoing', 13, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324229);
