INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-phu-phu-nhan-khong-de-lam', 'Hầu Phủ Phu Nhân Không Dễ Làm', 'Hard Noble Lady', 'https://phimimg.com/upload/vod/20240815-1/685df26a33e7b6ad5344431029abd13f.jpg', 'https://phimimg.com/upload/vod/20240815-1/0544533d7b8c50d7130039c09c929eef.jpg', '<p>Tổng tài bá đạo trẻ tuổi Lưu Tập là một nhà tư bản trong công việc và một &quot;tay chơi&quot; trong tình cảm. Trong cuộc sống và công việc, anh hay coi thường phụ nữ, gây nhiều phiền toái và tổn thương cho những phụ nữ quanh mình mà không hề hay biết. Một ngày nọ, sự cố bất ngờ ập đến khiến Lưu Tập xuyên không vào Hầu phủ và trở thành thiếu phu nhân Liễu Tích Triêu, người bị nhiều thế lực trong phủ bắt nạt vì gả cao hơn thân phận. Chồng của Liễu Tích Triêu là Lục Thiếu Dương, tứ thiếu gia ăn chơi của phủ Trường Bình Hầu. Tra nam Liễu Tích Triêu đối đầu với thói ăn chơi của Lục Thiếu Dương khiến hai người như nước với lửa không thể dung hòa! Liễu Tích Triêu đột nhiên trở nên táo bạo và hành động khác thường khiến Lục Thiếu Dương kinh ngạc. Khi còn chưa kịp thích nghi với thân phận nữ giới bất ngờ, Liễu Tích Triêu đã bị mẹ chồng kéo đi nghe giảng về quy củ.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ke Ying","avatar":""},{"name":"鄧超元","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
