INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-ba-kinh-hoang-chuyen-rung-ron', 'Thứ Ba Kinh Hoàng Chuyện Rùng Rợn', 'Terror Tuesday Extreme', 'thứ ba kinh hoàng chuyện rùng rợn terror tuesday extreme ณัฏฐ์ กิจจริต ชาราฎา อิมราพร สุทธิรักษ์ ทรัพย์วิจิตร ภาลฎา ฐิตะวชิระ เฌอปราง อารีย์กุล แพรวา สุธรรมพงษ์ ภัทรวดี บุญมีทรัพย์ ชญานิษฐ์ ชาญสง่าเวช รุจิรา ช่วยเกื้อ วรฤทธิ์ เฟื่องอารมย์ นฤภรกมล ฉายแสง ปูน มิตรภักดี ดวงพร สนธิขันธ์ ปาณิสรา ริกุลสุ ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-so-roi-chay-thoi', 'Trúng Số Rồi, Chạy Thôi!', 'Jackpot!', 'https://phimimg.com/upload/vod/20240819-1/02dbf3c3b2ab2c4b38877f0cf995046f.jpg', 'https://phimimg.com/upload/vod/20240819-1/26f2c8b5bd58405cb5c52edb5ea696f3.jpg', '<p>Trong tương lai gần, một &quot;Xổ số lớn&quot; đã được thành lập - mục đích: giết người chiến thắng trước khi mặt trời lặn để nhận giải độc đắc trị giá hàng tỷ đô la của họ một cách hợp pháp. Khi Katie Kim nhầm lẫn với tấm vé trúng thưởng, cô miễn cưỡng gia nhập lực lượng với nhân viên bảo vệ xổ số nghiệp dư Noel Cassidy, người phải đưa cô đến lúc mặt trời lặn để đổi lấy một phần giải thưởng của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Awkwafina","avatar":""},{"name":"John Cena","avatar":""},{"name":"Simu Liu","avatar":""},{"name":"Ayden Mayeri","avatar":""},{"name":"Donald Watkins","avatar":""},{"name":"Sam Asghari","avatar":""},{"name":"Machine Gun Kelly","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Dolly de Leon","avatar":""},{"name":"Michael Hitchcock","avatar":""},{"name":"Becky Ann Baker","avatar":""},{"name":"Leslie David Baker","avatar":""},{"name":"Murray Hill","avatar":""},{"name":"Adam Ray","avatar":""},{"name":"Taylor Ortega","avatar":""},{"name":"Holmes","avatar":""},{"name":"Krystal Smith","avatar":""},{"name":"Bobby Le","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324229);
