INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-ben-trong', 'Quái Thú Bên Trong', 'The Beast Within', 'https://phimimg.com/upload/vod/20240819-1/21d88a0147f46a353ccfa3b0b2ef2c77.jpg', 'https://phimimg.com/upload/vod/20240819-1/e24b5abcbd3f0b14d32f20532966b812.jpg', '<p>Cô bé Willow mười tuổi đi theo bố mẹ trong một chuyến đi bí mật vào đêm khuya tới trung tâm của một khu rừng cổ xưa. Sau khi chứng kiến người cha của mình trải qua một sự biến đổi khủng khiếp, cô bé cũng bị vướng vào bí mật gia truyền tăm tối mà họ đã cố gắng giấu kín.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kit Harington","avatar":""},{"name":"Ashleigh Cummings","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Caoilinn Springall","avatar":""},{"name":"Ian Giles","avatar":""},{"name":"Adam Basil","avatar":""},{"name":"Martina McClements","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
