INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tho-tran-trui', 'Nàng Thơ Trần Trụi', 'Ang Pintor At Ang Paraluman', 'https://phimimg.com/upload/vod/20240819-1/45fcd3afd5e96a272eac9e15b23951ab.jpg', 'https://phimimg.com/upload/vod/20240819-1/15525e9da9a021cd159df94a90bf0567.jpg', '<p>Một nghệ sĩ gặp một người phụ nữ bí ẩn, người trở thành người mẫu cho tác phẩm nghệ thuật khỏa thân của anh. Sau đó, anh tưởng tượng mình đang làm tình với cô; tuy nhiên, anh luôn nhớ quy tắc số một của cô - cô không thể bị chạm vào.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Ali Asistio","avatar":""},{"name":"Athena Moran","avatar":""},{"name":"Skye Gonzaga","avatar":""},{"name":"Yda Manzano","avatar":""},{"name":"Juan Calma","avatar":""},{"name":"Mark Dionisio","avatar":""},{"name":"Arjay Bautista","avatar":""},{"name":"Enzo Ruiz","avatar":""},{"name":"Mhack Morales","avatar":""},{"name":"Ayah Alfonso","avatar":""},{"name":"Seon Quintos","avatar":""},{"name":"Ayra Salvador","avatar":""},{"name":"Ali Asaytona","avatar":""},{"name":"Athena Moran","avatar":""},{"name":"Red Angoncillo","avatar":""},{"name":"Anne Marie","avatar":""},{"name":"Prince Mccoy Imperial","avatar":""},{"name":"Neil Tolen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
