INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-tuyet-mat', 'Liên Minh Tuyệt Mật', 'The Union', 'https://phimimg.com/upload/vod/20240819-1/107e9bbabf6c06ffa56ae53419c2ca8d.jpg', 'https://phimimg.com/upload/vod/20240819-1/9a6ec69f9ce318e3214207f666ae79ca.jpg', '<p>Một công nhân xây dựng ở New Jersey từ anh chàng bình thường trở thành điệp viên triển vọng khi tình cũ thời cấp 3 thất lạc từ lâu chiêu mộ anh cho một nhiệm vụ gián điệp.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Mike Colter","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Jessica De Gouw","avatar":""},{"name":"Alice Lee","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Stephen Campbell Moore","avatar":""},{"name":"Lorraine Bracco","avatar":""},{"name":"Dana Delany","avatar":""},{"name":"Patch Darragh","avatar":""},{"name":"James McMenamin","avatar":""},{"name":"Juan Carlos Hernández","avatar":""},{"name":"Alex Brightman","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324229);
