INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-khong-luc-mot', 'Giải Cứu Không Lực Một', 'Air Force One Down', 'https://phimimg.com/upload/vod/20240819-1/1a04b5b9349bb2bb1dd570bcda2b8f8a.jpg', 'https://phimimg.com/upload/vod/20240819-1/c38236184f0a3cdadb370c9ef0f80f4a.jpg', '<p>Trong nhiệm vụ đầu tiên trên chiếc Air Force One, một nhân viên Mật vụ tân binh phải đối mặt với thử thách cuối cùng khi những kẻ khủng bố cướp máy bay với ý định làm hỏng một thỏa thuận năng lượng quan trọng. Với mạng sống của Tổng thống đang bị đe dọa và cuộc khủng hoảng toàn cầu đang bị đe dọa, lòng dũng cảm và kỹ năng của cô bị đẩy đến giới hạn trong một trận chiến không ngừng nghỉ có thể thay đổi tiến trình lịch sử.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Katherine McNamara","avatar":""},{"name":"Ian Bohen","avatar":""},{"name":"Dascha Polanco","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Paul S. Tracey","avatar":""},{"name":"Anthony Michael Hall","avatar":""},{"name":"Trevor Van Uden","avatar":""},{"name":"J.R. Esposito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
