INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-gai-mat-xa', 'Em Gái Mát Xa', 'Backrider', 'https://phimimg.com/upload/vod/20240819-1/9843a32a81b3e6ad6b6d90b0ece85d1f.jpg', 'https://phimimg.com/upload/vod/20240819-1/0bfd3483af9d3ea934d9bd9c1571215a.jpg', '<p>Faith là một chuyên gia mát-xa riêng. Sau khi chia tay với bạn trai nghiện game và tiền điện tử, cô tìm thấy sự an ủi ở khách hàng giàu có và có vẻ tử tế của mình, nhưng lại thấy mình trong một tình huống đầy đam mê và nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Jenn Rosa","avatar":""},{"name":"Aerol Carmelo","avatar":""},{"name":"Chad Alviar","avatar":""},{"name":"Jonica Lazo","avatar":""},{"name":"Ivan Ponce","avatar":""},{"name":"Mark Grabador","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
