INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-tinh-em-thua', 'Đường Tình Em Thua', 'Kaskasero', 'https://phimimg.com/upload/vod/20240819-1/6ac513ac4b5eae8760d34bbcfd3cc418.jpg', 'https://phimimg.com/upload/vod/20240819-1/c6ba678c183ef9340e67c235a3b10591.jpg', '<p>Người thợ máy tài năng Migs bị một khách hàng quyến rũ, Gabbi, lôi kéo vào cuộc đua xe đường phố bất hợp pháp. Khi anh đào sâu hơn, tìm hiểu về quá khứ rắc rối của Gabbi, những lựa chọn liều lĩnh của Migs đã gây nguy hiểm cho mối quan hệ của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Angela Morena","avatar":""},{"name":"Itan Magnaye","avatar":""},{"name":"Marco Gomez","avatar":""},{"name":"Christine Bermas","avatar":""},{"name":"Jeffrey Santos","avatar":""},{"name":"Vern Kaye","avatar":""},{"name":"Elmo Elarmo Jr.","avatar":""},{"name":"Alvaro Oteyza","avatar":""},{"name":"Jhai Salvador","avatar":""},{"name":"Angelica Cervantes","avatar":""},{"name":"Quinn Carrillo","avatar":""},{"name":"Rica Gonzales","avatar":""},{"name":"Ralmon Mendoza","avatar":""},{"name":"Cess Garcia","avatar":""},{"name":"Karl Aquino","avatar":""},{"name":"Krisha Macalanda","avatar":""},{"name":"Thia Ledes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
