INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-toi-la-zombies', 'Chúng Tôi Là Zombies', 'We Are Zombies', 'https://phimimg.com/upload/vod/20240819-1/2dbb2dde28706bfa8a26525aecc12a16.jpg', 'https://phimimg.com/upload/vod/20240819-1/cdbd629f2db4f5010941b893d5b64d50.jpg', '<p>Trong một thành phố bị nhiễm đầy những người mất khả năng sống, hay còn gọi là những xác sống không ăn thịt - ba kẻ lười biếng, sau khi kiếm được chút tiền dễ dàng, phải đấu tranh với bọn tội phạm nhỏ lẻ và một tập đoàn khổng lồ độc ác để cứu bà của họ bị bắt cóc.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Alexandre Nachi","avatar":""},{"name":"Derek Johns","avatar":""},{"name":"Megan Peta Hill","avatar":""},{"name":"Clare Coulter","avatar":""},{"name":"Benz Antoine","avatar":""},{"name":"Vincent Leclerc","avatar":""},{"name":"Carlo Mestroni","avatar":""},{"name":"Guy Nadon","avatar":""},{"name":"Marc-André Boulanger","avatar":""},{"name":"Stéphane Demers","avatar":""},{"name":"Teneisha Collins","avatar":""},{"name":"Patrick Abellard","avatar":""},{"name":"Adrian Burhop","avatar":""},{"name":"Michelle Leblanc","avatar":""},{"name":"Kevin Woodhouse","avatar":""},{"name":"Rosemarie","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
