INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cuu-con', 'Cuộc Chiến Cứu Con', 'Gunner', 'https://phimimg.com/upload/vod/20240819-1/f41856bcde0aa18875af2bd8bfd7f18f.jpg', 'https://phimimg.com/upload/vod/20240819-1/8b8ddd69ffa4f16ebca996a2c26384e3.jpg', '<p>Trong một chuyến đi cắm trại để hàn gắn, cựu chiến binh, Đại tá Lee Gunner phải cứu hai con trai của mình khỏi một băng đảng tội phạm khi chúng bị bắt cóc sau khi vô tình vấp phải một vụ buôn bán ma túy lớn.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Luke Hemsworth","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Joseph Baena","avatar":""},{"name":"Maurice P. Kerry","avatar":""},{"name":"Mykel Shannon Jenkins","avatar":""},{"name":"Grant Feely","avatar":""},{"name":"Connor DeWolfe","avatar":""},{"name":"Sean Rogers","avatar":""},{"name":"Gene Dante","avatar":""},{"name":"Derrick Goodman Jr.","avatar":""},{"name":"Barry Jay Minoff","avatar":""},{"name":"Will Koberg","avatar":""},{"name":"André Wilkerson","avatar":""},{"name":"Leslie Sides","avatar":""},{"name":"Breana Symone","avatar":""},{"name":"Creek Wilson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324229);
