INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-chua', 'Bạo Chúa', 'The Tyrant', 'https://phimimg.com/upload/vod/20240818-1/8997d1cef7167a7628d318120ac9fd11.jpg', 'https://phimimg.com/upload/vod/20240818-1/efb916956258d9cc6bb7680b40b6c788.jpg', '<p>Một dự án bí mật ở Hàn Quốc bị lộ ở Mỹ nên dự án bị hủy bỏ và mẫu sẽ được bàn giao khi xảy ra tai nạn giao hàng. Giám đốc Choe cố gắng giấu mẫu khi Paul tìm kiếm, nhưng cuối cùng họ lại ở cùng một nơi với Jagyeong và Lim Sang. Cuối cùng ai sẽ lấy mẫu?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"차승원","avatar":""},{"name":"김선호","avatar":""},{"name":"김강우","avatar":""},{"name":"조윤수","avatar":""},{"name":"무진성","avatar":""},{"name":"장영남","avatar":""},{"name":"김주헌","avatar":""},{"name":"이기영","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324229);
