INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('om-nhau-trong-dem-toi', 'Ôm Nhau Trong Đêm Tối', 'Embrace In The Dark Night', 'https://phimimg.com/upload/vod/20240818-1/7c7a2e78cbbb783109271c266a6bec56.jpg', 'https://phimimg.com/upload/vod/20240818-1/90eca6dbe79e9eeae711c1eefb53a36e.jpg', '<p>Trong một lần du lịch ở nước ngoài, Ôn Hề vô tình bị đưa đến võ đài ngầm của ông Giả, ông trùm đứng sau bọn cho vay nặng lãi, trở thành một chiến lợi phẩm dành cho người chiến thắng trong cuộc đấu. Người cuối cùng giành được Ôn Hề là một chàng trai người gốc Hoa trẻ tuổi và bí ẩn, Từ Triết Thanh. Ông Giả rất thích tài đánh của Từ Triết Thanh, dùng uy và quyền để ép anh ở lại phục vụ mình. Nhưng ông ta không biết, thân phận thật sự của Từ Triết Thanh là một cố vấn an ninh cá nhân đến đây để giải cứu Ôn Hề. Sau khi trải qua nhiều nguy hiểm, cả hai cùng nhau trốn thoát khỏi sự kiểm soát của ông Giả. Ba năm sau, chị gái song sinh Ôn Hảo của Ôn Hề đột ngột qua đời. Cô quyết định thay chị gái đến công ty G.E. để tìm ra sự thật và bất ngờ gặp lại Từ Triết Thanh. Hai người thuộc hai phe khác nhau, nhưng họ lại bị ảnh hưởng bởi những cảm xúc trong quá khứ. Lần này, liệu hai người có thể cùng nắm tay nhau một lần nữa để vượt qua bóng tối của màn đêm và bên nhau đón khoảnh khắc hạnh phúc...?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ren Yunjie","avatar":""},{"name":"Gao Rong Fang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
