INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-phu-the-2024', 'Tiểu Phu Thê', 'As Husband As Wife', 'https://phimimg.com/upload/vod/20240731-1/831f88acd1333aac0dc53440a54ab801.jpg', 'https://phimimg.com/upload/vod/20240731-1/530e948bf8318ee1155d848074ae341a.jpg', '<p>Chu Toàn và Xa Lê vốn có một gia đình hạnh phúc bỗng một ngày khi một người bị sa thải vì thiếu tài năng, trong khi người kia vội vàng khởi nghiệp kinh doanh. Những thay đổi bất ngờ đã khiến cuộc hôn nhân 10 năm của họ rơi vào bế tắc. Liệu hai người ở độ tuổi ba mươi có thể quay lại con đường hạnh phúc?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yin Tao","avatar":""},{"name":"Guo Jingfei","avatar":""},{"name":"Qi Xi","avatar":""},{"name":"張雲龍","avatar":""},{"name":"韓童生","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324229);
