INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-ngo-ve-phong-khoi-kim-lang', 'Kim Ngô Vệ: Phong Khởi Kim Lăng', '金吾卫之风起金陵', 'https://phimimg.com/upload/vod/20240529-1/2cb40c23bddcf3c95a5c6a8acebdb2dc.jpg', 'https://phimimg.com/upload/vod/20240529-1/dad2492cb3e18c68c7af53e875425e39.jpg', '<p>Trong thời kỳ Kim Ngô, nơi vua có quyền thế và những võ sĩ mạnh mẽ.&nbsp; Jin, người đã được giao nhiệm vụ quan trọng là bảo vệ Kim Lăng – nơi chứa đựng những bí mật quan trọng của triều đình.Để có thể bảo vệ được Kim Lăng Jin đã phải trả qua những cuộc chiến dấu&nbsp; khó khăn, nguy hiểm trước những thế lực mạnh của kể thù hòng chiếm đoạt sức mạnh ẩn giấu trong đó.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324229);
