INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-hau-nhat-quyen', 'Túy Hậu Nhất Quyền', 'The Drunken Prodigy', 'https://phimimg.com/upload/vod/20240816-1/ffafb5315a072076822827611031bf27.jpg', 'https://phimimg.com/upload/vod/20240816-1/0e30faaa89ebff9b6c8daee7b4ee3ecc.jpg', '<p>Bộ phim kể về câu chuyện của Lâm Diệu, công tử quyền quý thích võ nghệ từ nhỏ. Trong quá trình theo đuổi hoa khôi thanh lâu Tần Sương, anh gặp phải âm mưu lừa đảo liên hoàn của Lý Bạch My và những người khác, bị lừa đến mức tán gia bại sản. Tuy nhiên, cuối cùng Lâm Diệu đã nhận ra bản thân mình. Với sự giúp đỡ của gia đình và Tần Sương, hắn đã học xong võ công, đánh bại Lý Bạch My và những kẻ khác, đồng thời bảo vệ được dân trong trấn.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Ashton Chen","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"郝劭文","avatar":""},{"name":"Zhang Shi","avatar":""},{"name":"Vivi Chen","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"翁虹","avatar":""},{"name":"Paul Che Biu-law","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324229);
