INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-hoa-no-gap-lai-nguoi', 'Mùa Hoa Nở Gặp Lại Người', 'Meet You at the Blossom', 'https://phimimg.com/upload/vod/20240718-1/3948716e60d369e161170b46bf463496.jpg', 'https://phimimg.com/upload/vod/20240718-1/654d27c98b272e6a45e9651a3f725a45.jpg', '<p>Chàng thiếu gia phong lưu xa hoa của Kim gia, Kim Tiểu Bảo tuy ham hố sắc đẹp nhưng cũng hài hước và ân cần. Nhưng trong một đêm hôm khuya khoắt, người trong mộng lại xuất hiện trước mặt anh ta! Không ngờ, cô nương Hoài Ân có vẻ đẹp tuyệt sắc và khí chất lạnh lùng lại vướng vào một thảm họa sát thân làm sao Tiểu Bảo có thể bỏ lỡ cơ hội cứu mỹ nhân được! Nhưng vừa ra tay, anh không những không cưới được mỹ nhân làm thiếu phu nhân mà còn đánh mất bản thân! Không chỉ giới tính của &quot;mỹ nhân&quot; này là điều bí ẩn mà thân thế cũng liên quan mật thiết đến Kim gia... Khi Tiểu Bảo và Hoài Ân nhận rõ ra nhau, liệu họ còn đủ dũng khí để nối lại mối lương duyên?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Yunkai","avatar":""},{"name":"Li Jun Liang","avatar":""},{"name":"Kou Wei Long","avatar":""},{"name":"Sukonlaphat Sribubpha","avatar":""},{"name":"Song Jia Xi","avatar":""},{"name":"Ni Song Yang","avatar":""},{"name":"Jing Feng","avatar":""},{"name":"Du Le","avatar":""},{"name":"Lucas Lee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324229);
