INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-ngoc-yen', 'Phất Ngọc Yên', 'The Unexpected Marriage', 'https://phimimg.com/upload/vod/20240731-1/e678e355305124839803c7db9f1bdfb6.jpg', 'https://phimimg.com/upload/vod/20240731-1/7991b9978070b45cc3c03c7e184f67e2.jpg', '<p>Lý Quả Đóa bị đồng đội Đồ Linh Linh phản bội nên đã bỏ lỡ cơ hội được bước vào trường đại học thể thao mà cô hằng mơ ước. Vì để tiếp tục theo đuổi ước mơ, cô đã đến đại học Tân Cảng rồi trở thành đồng đội ăn ý nhất với Trần Úy Lam, người chuyển hướng từ bóng chuyền thông thường sang bóng chuyền bãi biển. Cả hai đã vượt qua chính mình, trở thành vận động viên bóng chuyền bãi biển xuất sắc, cùng nhau dũng cảm tiến về phía trước giữa những lời chúc phúc đến từ người thân, bạn bè và người yêu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qi Yu Chen","avatar":""},{"name":"吴俊霆","avatar":""},{"name":"Gao Huilin","avatar":""},{"name":"Wang Chuan","avatar":""},{"name":"Xingyao Li","avatar":""},{"name":"Jin Chong","avatar":""},{"name":"Chake Lau","avatar":""},{"name":"Liu Jin","avatar":""},{"name":"Dai Yi","avatar":""},{"name":"Han Xiaoyao","avatar":""},{"name":"Ma Jiaying","avatar":""},{"name":"Li Jingyi","avatar":""},{"name":"Ye Huo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324229);
