INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dep-trai-thay-sai-sai', 'Đẹp Trai Thấy Sai Sai', 'Handsome Guys', 'https://phimimg.com/upload/vod/20240815-1/1580cf1921d8a3c38d1710429727ea9c.jpg', 'https://phimimg.com/upload/vod/20240815-1/3dea8fdc7611d41377b662b921da205a.jpg', '<p>Hai người đàn ông thô lỗ nhưng giản dị, tự xưng là &quot;Những anh chàng đẹp trai&quot;. Họ có ước mơ được sống ở vùng nông thôn và cuối cùng giấc mơ của họ đã thành hiện thực. Tuy nhiên, vào ngày đầu tiên chuyển đến ngôi nhà mới, một bí mật bị phong ấn dưới tầng hầm của họ đã được đánh thức. Từ đây gây ra một loạt những hài kịch khó đỡ.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"이성민","avatar":""},{"name":"이희준","avatar":""},{"name":"공승연","avatar":""},{"name":"박지환","avatar":""},{"name":"이규형","avatar":""},{"name":"우현","avatar":""},{"name":"장동주","avatar":""},{"name":"강기둥","avatar":""},{"name":"Bin Chan-uk","avatar":""},{"name":"박정화","avatar":""},{"name":"김도훈","avatar":""},{"name":"박경혜","avatar":""},{"name":"이서환","avatar":""},{"name":"Song You-hyun","avatar":""},{"name":"Jamie Horan","avatar":""},{"name":"진태건","avatar":""},{"name":"임원희","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324229);
