INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-chung-ta', 'Bí Mật Của Chúng Ta', 'The Secret Of Us', 'https://phimimg.com/upload/vod/20240625-1/b2b181f7c1ba96bf90388fd36be03d50.jpg', 'https://phimimg.com/upload/vod/20240625-1/1b137f9126548c629bba414fcaa7caef.jpg', '<p>Sau cuộc chia tay tàn khốc, hai người phụ nữ nọ có duyên gặp lại và phải xoay xở với tình yêu, sự không chắc chắn và quá khứ trước khi nối lại tình xưa.</p>', 'Hoàn Tất (8/8)', 10, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sirilak Kwong","avatar":""},{"name":"Kornnaphat Sethratanapong","avatar":""},{"name":"Apasiri Nitibhon","avatar":""},{"name":"Paramej Noiam","avatar":""},{"name":"Narumon Phongsupan","avatar":""},{"name":"Chatsak Mahata","avatar":""},{"name":"Gap Jakkarin Phooriphad","avatar":""},{"name":"Dandao Yamapai","avatar":""},{"name":"Sureeyares Yakares","avatar":""},{"name":"Ying Anada Prakobkit","avatar":""},{"name":"Pentaii Natthanit Praditthan","avatar":""},{"name":"Nene Thanchanok Yutthasarnsiri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
