INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-be-boi-anh-trang', 'Vụ Bê Bối Ánh Trăng', 'Fly Me to the Moon', 'https://phimimg.com/upload/vod/20240815-1/a55fb35c8c29567f875885790ac53723.jpg', 'https://phimimg.com/upload/vod/20240815-1/5126f55a7ef7747f7cf432ff043403ea.jpg', '<p>Vào thập niên 1960 hay còn được gọi là thời kỳ Chạy đua vào không gian giữa Hoa Kỳ và Liên Xô, một mối quan hệ đã được chớm nở giữa một giám đốc NASA phụ trách dự án phòng tàu Apollo 11 với một chuyên gia tiếp thị đến để chỉnh sửa hình ảnh của NASA trước công chúng và dàn dựng một cuộc đổ bộ lên mặt trăng giả để &quot;dự phòng&quot;.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Scarlett Johansson","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Ray Romano","avatar":""},{"name":"Jim Rash","avatar":""},{"name":"Anna Garcia","avatar":""},{"name":"Donald Watkins","avatar":""},{"name":"Noah Robbins","avatar":""},{"name":"Christian Clemenson","avatar":""},{"name":"Colin Woodell","avatar":""},{"name":"Nick Dillenburg","avatar":""},{"name":"Christian Zuber","avatar":""},{"name":"Gene Jones","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"Stephanie Kurtzuba","avatar":""},{"name":"Colin Jost","avatar":""},{"name":"Dariusz Wol","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324229);
