INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dieu-tra-hoan-hao', 'Đội Điều Tra Hoàn Hảo', 'The Infallibles', 'https://phimimg.com/upload/vod/20240815-1/c2a61c08d5b4928f811ab2a4a042e72a.jpg', 'https://phimimg.com/upload/vod/20240815-1/1151dd89075223f35114827245621981.jpg', '<p>Theo chân nhóm thám tử tài ba được biết đến với biệt danh “Đội Điều Tra Hoàn Hảo”. Dưới sự lãnh đạo của nữ thám tử Alice Lambert, nhóm điều tra một loạt vụ án mạng liên hoàn nhắm vào những người có ảnh hưởng lớn trong xã hội Paris. Những vụ án này đều có liên quan đến một biểu tượng bí ẩn và một tổ chức tội phạm quốc tế.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Inès Reg","avatar":""},{"name":"Kévin Debonne","avatar":""},{"name":"Vincent Rottiers","avatar":""},{"name":"Moussa Maaskri","avatar":""},{"name":"François Neycken","avatar":""},{"name":"Pierre Olivier","avatar":""},{"name":"Hugo Gonzalez","avatar":""},{"name":"Daphné Huynh","avatar":""},{"name":"Loriane Klupsch","avatar":""},{"name":"Adèle Sierra","avatar":""},{"name":"Kévin Azaïs","avatar":""},{"name":"Philippe Résimont","avatar":""},{"name":"Lionnel Astier","avatar":""},{"name":"Julian Naceri","avatar":""},{"name":"Majida Ghomari","avatar":""},{"name":"Bachir Baccour","avatar":""},{"name":"Stéphan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324229);
