INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-va-con', 'Cha Và Con', 'Ezra', 'https://phimimg.com/upload/vod/20240815-1/22d9704cc150e3890310030e743f8299.jpg', 'https://phimimg.com/upload/vod/20240815-1/b0e35c41b5d538ab21c3177775d3af3e.jpg', '<p>Max Barnel là một cựu biên kịch hài, giờ đây phải chật vật kiếm sống với vai trò diễn viên hài độc thoại và sống cùng cha mình, Stan. Anh không hòa hợp với vợ cũ Jenna vì cả hai thường xuyên bất đồng về cách nuôi dạy con trai tự kỷ của họ, Ezra. Ezra gặp khó khăn trong việc thích nghi với thế giới bên ngoài, và Max thường dẫn con đến các câu lạc bộ hài để Ezra làm bùa may mắn cho mình, điều này khiến Jenna khó chịu....</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bobby Cannavale","avatar":""},{"name":"William A. Fitzgerald","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Whoopi Goldberg","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"Tony Goldwyn","avatar":""},{"name":"Jackson Frazer","avatar":""},{"name":"Greer Barnes","avatar":""},{"name":"Tess Goldwyn","avatar":""},{"name":"Ella Ayberk","avatar":""},{"name":"Lois Robbins","avatar":""},{"name":"Alex Plank","avatar":""},{"name":"Daphne Rubin-Vega","avatar":""},{"name":"Matilda Lawler","avatar":""},{"name":"Joe Pachec","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
