INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-bao-thu', 'Người Mẹ Báo Thù', 'Hard Home', 'https://phimimg.com/upload/vod/20240815-1/48778042c3e798720cd599928343e13d.jpg', 'https://phimimg.com/upload/vod/20240815-1/42ddfc8072104903522d6c13fb043908.jpg', '<p>Một người mẹ đau buồn dụ kẻ giết con gái mình vào ngôi nhà thông minh của cô để trả thù, từ đó bị cuốn vào một trò chơi méo mó nơi sinh tử treo trên sợi chỉ.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Simone Kessell","avatar":""},{"name":"Andrew Howard","avatar":""},{"name":"Rosie Day","avatar":""},{"name":"Joseph Millson","avatar":""},{"name":"Rachel Adedeji","avatar":""},{"name":"Daphne Cheung","avatar":""},{"name":"Teresa Cendon-Garcia","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324229);
