INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loc-xoay-tu-than', 'Lốc Xoáy Tử Thần', 'Twisters', 'https://phimimg.com/upload/vod/20240814-1/9480f5611185c640f0faa1704a05d3a1.jpg', 'https://phimimg.com/upload/vod/20240814-1/8ef4ee092f21b93b96e534f8f68f3ef0.jpg', '<p>Kate Cooper, một nhà săn bão từng trải qua cơn lốc xoáy thời đại học hiện tại đang làm nhà nghiên cứu đặc điểm, hiện tượng của những cơn bão thông qua màn hình tại thành phố New York. Cô được Javi - một người bạn cũ, mời đến một vùng đồng bằng để thử nghiệm hệ thống theo dõi mới mang tính đột phá. Tại đó, cô tình cờ gặp Tyler Owens - một ngôi sao truyền thông mạng xã hội đầy sức quyến rũ, nổi tiếng với việc đăng tải những chuyến phiêu lưu săn bão nghẹt thở cùng với đoàn nhân viên ồn ào, thích thú với những sự nguy hiểm. Khi mùa bão trở nên khắc nghiệt hơn, những hiện tượng kỳ lạ chưa từng thấy trước đây dần được hé lộ. Kate, Tyler và đội nhóm của họ thấy mình bị cuốn vào hệ thống những cơn bão khó lường hội tụ tại trung tâm Oklahoma, tại đây, họ sẽ phải đối mặt với những thử thách chưa từng có để có thể sống sót.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Daisy Edgar-Jones","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Brandon Perea","avatar":""},{"name":"Maura Tierney","avatar":""},{"name":"Harry Hadden-Paton","avatar":""},{"name":"Sasha Lane","avatar":""},{"name":"Daryl McCormack","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Nik Dodani","avatar":""},{"name":"David Corenswet","avatar":""},{"name":"Tunde Adebimpe","avatar":""},{"name":"Katy O''Brian","avatar":""},{"name":"David Born","avatar":""},{"name":"Paul Scheer","avatar":""},{"name":"Laura Poe","avatar":""},{"name":"Austin Bulloc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
