INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-me-dam-2', 'Người Tình Mê Đắm 2', 'Phir Aayi Hasseen Dillruba', 'https://phimimg.com/upload/vod/20240814-1/ba3f83b8d84b3444e901337d4777c97d.jpg', 'https://phimimg.com/upload/vod/20240814-1/8884235d4cf8c5c33dcf7b3f11262279.jpg', '<p>Trong khi lẩn trốn cảnh sát ở Agra, Rani và Rishu âm mưu chạy trốn cùng nhau. Nhưng khi kế hoạch đổ bể, Rani nhờ một người ôn hòa có cảm tình với mình giúp đỡ.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Taapsee Pannu","avatar":""},{"name":"Vikrant Massey","avatar":""},{"name":"Sunny Kaushal","avatar":""},{"name":"Jimmy Shergill","avatar":""},{"name":"Aditya Srivastava","avatar":""},{"name":"Bhumika Dube","avatar":""},{"name":"Sapna Sand","avatar":""},{"name":"Manoj Kumar Singh","avatar":""},{"name":"Alok Pandey","avatar":""},{"name":"Manwendra Tripathy","avatar":""},{"name":"Trupti Khamkar","avatar":""},{"name":"Gautam Gadaballi","avatar":""},{"name":"Sahela Raza","avatar":""},{"name":"Ambrish Saxena","avatar":""},{"name":"Sonu","avatar":""},{"name":"Pramod Rana","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324229);
