INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-sau-san-dau', 'Cuộc Sống Sau Sàn Đấu', 'Life After Fighting', 'https://phimimg.com/upload/vod/20240814-1/a1c560478ce0d341633bcddff935c291.jpg', 'https://phimimg.com/upload/vod/20240814-1/abefc923072e46a2feeb24b26a91edae.jpg', '<p>Một huấn luyện viên võ thuật phải đối mặt với sự biến mất của hai học trò của mình, dẫn anh ta vào một cuộc đối đầu trực tiếp với một nhóm buôn bán trẻ em quốc tế.</p>', 'Full', 1, 'single', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Bren Foster","avatar":""},{"name":"Cassie Howarth","avatar":""},{"name":"Luke Ford","avatar":""},{"name":"Annabelle Stephenson","avatar":""},{"name":"Anthony Nassif","avatar":""},{"name":"Arielle Jean Foster","avatar":""},{"name":"Eddie Arrazola","avatar":""},{"name":"Ethan Browne","avatar":""},{"name":"Ruby Busuttil","avatar":""},{"name":"Denise Chan","avatar":""},{"name":"Mike Duncan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
