INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-sat-2024', 'Hạ Sát', 'Kill', 'https://phimimg.com/upload/vod/20240814-1/e99555f4167d4ee7996ba4f6987ce57f.jpg', 'https://phimimg.com/upload/vod/20240814-1/0d2b15984c8c7be5b8f33e24cb4db18a.jpg', '<p>Khi một đặc công quân đội phát hiện ra tình yêu đích thực của mình đã đính hôn trái với ý muốn của cô, anh lên chuyến tàu đến New Dehli trong một nhiệm vụ táo bạo nhằm làm trật bánh cuộc hôn nhân sắp đặt. Nhưng khi một nhóm trộm cầm dao bắt đầu khủng bố những hành khách vô tội trên chuyến tàu của anh ta, người biệt kích đã tự mình hạ gục họ trong một cuộc giết chóc bất chấp cái chết để cứu những người xung quanh - biến những gì lẽ ra là một chuyến đi thông thường thành một adrenaline- thúc đẩy chuyến đi hồi hộp.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Lakshya Lalwani","avatar":""},{"name":"Raghav Juyal","avatar":""},{"name":"Tanya Maniktala","avatar":""},{"name":"Abhishek Chauhan","avatar":""},{"name":"Ashish Vidhyarthi","avatar":""},{"name":"Adrija Sinha","avatar":""},{"name":"Harsh Chhaya","avatar":""},{"name":"Parth Tiwari","avatar":""},{"name":"Akshay Vichare","avatar":""},{"name":"Jitendra Kumar Sharma","avatar":""},{"name":"Rupesh Kumar Charanpahari","avatar":""},{"name":"Sahil Gangurde","avatar":""},{"name":"Priyam Gupta","avatar":""},{"name":"Vivek Kashyap","avatar":""},{"name":"Sameer Kumar","avatar":""},{"name":"Cal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 178