INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-chuot', 'Bẫy Chuột', 'The Mouse Trap', 'https://phimimg.com/upload/vod/20240814-1/1b95d7ce1e9d77a46eed1d1075cc2f90.jpg', 'https://phimimg.com/upload/vod/20240814-1/bd1020b4e46d3020b5587c9de720415a.jpg', '<p>Câu chuyện bắt đầu vào sinh nhật lần thứ 21 của Alex, nhưng thay vì một bữa tiệc bình thường, cô lại phải làm việc trễ tại một trung tâm trò chơi giải trí. Đêm của cô trở nên kinh hoàng khi bạn bè cô bất ngờ đến chơi, và họ tất cả đều bị mắc kẹt với một kẻ giết người đeo mặt nạ hình con chuột Mickey, chơi một trò chơi sinh tử.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Simon Phillips","avatar":""},{"name":"Sophie McIntosh","avatar":""},{"name":"Nick Biskupek","avatar":""},{"name":"James Laurin","avatar":""},{"name":"Mireille Gagné","avatar":""},{"name":"Damir Kovic","avatar":""},{"name":"Calum Sywyk","avatar":""},{"name":"Allegra Nocita","avatar":""},{"name":"Ben Harris","avatar":""},{"name":"Mackenzie Mills","avatar":""},{"name":"Jesse Nasmith","avatar":""},{"name":"Madeline Kelman","avatar":""},{"name":"Liam Grue","avatar":""},{"name":"Kayleigh Styles","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324229);
