INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-bach-ma-tuy-xuan-phong', 'Thiếu Niên Bạch Mã Túy Xuân Phong', 'Dashing Youth', 'https://phimimg.com/upload/vod/20240720-1/2a3a83725ffaf18803d5f5c156458059.jpg', 'https://phimimg.com/upload/vod/20240720-1/fce9d8e58ca8d2a13e7459fa3b1a2055.jpg', '<p>Tiểu công tử Bách Lý Đông Quân của phủ Trấn Tây hầu không học võ nghệ mà chỉ say mê ủ rượu, nguyên nhân là vì lời hẹn &quot;tửu kiếm thành tiên&quot; với người bạn thuở nhỏ Diệp Vân. Số mệnh đưa đẩy cậu nhận Lý Trường Sinh đệ nhất thiên hạ làm thầy, bắt đầu học võ, gặp gỡ hồng nhan tri kỷ Nguyệt Dao, gặp lại Diệp Vân đã đổi tên thành Diệp Đỉnh Chi, kết bạn với lãng khách giang hồ Tư Không Trường Phong. Những thiếu niên cùng nhau bắt đầu câu chuyện giang hồ thuộc về riêng mình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hou Minghao","avatar":""},{"name":"何与","avatar":""},{"name":"Hu Lianxin","avatar":""},{"name":"夏之光","avatar":""},{"name":"Jiang Zhenyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324229);
