INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-long-dai-duong', 'Phải Lòng Đại Dương', 'Love Sea', 'https://phimimg.com/upload/vod/20240610-1/e93db2cabde70bdc7edb012ed288033b.jpg', 'https://phimimg.com/upload/vod/20240610-1/12660d5c9bd40566a0806254fba02962.jpg', '<p>‘Tongrak’ là một anh chàng đẹp trai và nóng bỏng, xuất thân từ một gia đình giàu có, đồng thời là tác giả của những cuốn tiểu thuyết lãng mạn nổi tiếng. Trong khi đi du lịch để tìm cảm hứng cho cuốn tiểu thuyết gần đây nhất của mình, anh tình cờ gặp &#39;Mahasamut&#39;, một người đàn ông miền Nam trẻ tuổi, cáu kỉnh và ngốc nghếch. Tuy nhiên, khi họ lên giường cùng nhau, Tongrak thấy mình bị cuốn hút.</p>', 'Tập 10', 10, 'series', 'ongoing', 13, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Wasuthorn Chaijindar","avatar":""},{"name":"Thitipong Sengngai","avatar":""},{"name":"Aya Orapan Phongmaykin","avatar":""},{"name":"Forth Kashane Pichetsopon","avatar":""},{"name":"Chanya Amarit Duval","avatar":""},{"name":"Ivy Phattaree Tassananakajit","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
