INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bung-chay-nao-co-gai-bong-chuyen', 'Bùng Cháy Nào! Cô Gái Bóng Chuyền', 'Go! Beach Volleyball Girls', 'https://phimimg.com/upload/vod/20240727-1/c21c34cda08fdb05550e9a44996daa9d.jpg', 'https://phimimg.com/upload/vod/20240730-1/c25ab7023844f51629d6f19812cf11b0.jpg', '<p>Lý Quả Đóa bị đồng đội Đồ Linh Linh phản bội nên đã bỏ lỡ cơ hội được bước vào trường đại học thể thao mà cô hằng mơ ước. Vì để tiếp tục theo đuổi ước mơ, cô đã đến đại học Tân Cảng rồi trở thành đồng đội ăn ý nhất với Trần Úy Lam, người chuyển hướng từ bóng chuyền thông thường sang bóng chuyền bãi biển. Cả hai đã vượt qua chính mình, trở thành vận động viên bóng chuyền bãi biển xuất sắc, cùng nhau dũng cảm tiến về phía trước giữa những lời chúc phúc đến từ người thân, bạn bè và người yêu.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tuyết Nghênh","avatar":""},{"name":"Hứa Linh Nguyệt","avatar":""},{"name":"Phí Khải Minh","avatar":""},{"name":"Cao Mân Duệ","avatar":""},{"name":"Tô Khả","avatar":""},{"name":"Trương Diễm Diễm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
