INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-quoc-yeu-ho-phan-1', 'Chiến Quốc Yêu Hồ (Phần 1)', 'Sengoku Youko (Season 1)', 'https://phimimg.com/upload/vod/20240305-1/08636d512be82f3a7c5ca4ae88067ad8.jpg', 'https://phimimg.com/upload/vod/20240305-1/fdb60663cf88d2352477342ee67e7cd1.jpg', '<p>Tama - một Yêu Hồ đem lòng yêu con người, thề bảo vệ họ khỏi cái ác, ngay cả khi phải chiến đấu lại với đồng loại. Trong khi người anh em của cô là Jinka lại ghét loài người. Hai anh em gặp gỡ Hyodo Shinsuke - một lãng khách đang muốn học cách trở nên mạnh mẽ, làm nên một câu chuyện thú vị về Tiên Đạo và Yêu Hồ trong thời Chiến Quốc. Những con người họ gặp gỡ, những nơi họ đến, và những cuộc chiến đấu của họ sẽ trở thành huyền thoại.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 14, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Soma Saito","avatar":""},{"name":"Yuuki Takada","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Tomoyo Kurosawa","avatar":""},{"name":"Hiroki Nanami","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Kenji Nomura","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Kazuki Miyagi","avatar":""},{"name":"Ayahi Takagaki","avatar":""},{"name":"Aina Suzuki","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Hiroki Touchi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324229);
