INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-ngoc-den', 'Viên Ngọc Đen', 'Rathnam', 'https://phimimg.com/upload/vod/20240810-1/cce9dc82bd4404034b54e4c8885f3bbc.jpg', 'https://phimimg.com/upload/vod/20240810-1/aec9200d80ddca660a1ab06d176ff6bb.jpg', '<p>Bộ phim kể về Rathnam, một tay sai làm việc cho MLA Panneer Selvam ở Vellore, bảo vệ Malliga, một sinh viên y khoa có ngoại hình giống mẹ quá cố của anh, khỏi sự truy đuổi của những kẻ cướp đất Beema Rayudu và anh em của hắn. Cuộc đấu tranh giữa Rathnam và những kẻ thù của anh dẫn đến việc anh khám phá ra quá khứ đen tối của gia đình mình. Cuối cùng, Rathnam tiêu diệt kẻ thù của mình và tự nộp mình cho cảnh sát, trước khi rời đi, anh yêu cầu Malliga kết hôn và đặt tên con của cô theo tên anh.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Vishal Krishna","avatar":""},{"name":"Priya Bhavani Shankar","avatar":""},{"name":"Samuthirakani","avatar":""},{"name":"Murli Sharma","avatar":""},{"name":"Hareesh Peradi","avatar":""},{"name":"Muthukumar","avatar":""},{"name":"Yogi Babu","avatar":""},{"name":"Vijayakumar","avatar":""},{"name":"Jayaprakash","avatar":""},{"name":"Tulasi","avatar":""},{"name":"Rajendran","avatar":""},{"name":"Ganesh Venkatraman","avatar":""},{"name":"Y. G. Mahendran","avatar":""},{"name":"Mohan Raman","avatar":""},{"name":"Gajaraj","avatar":""},{"name":"Kumki Ashwin","avatar":""},{"name":"''Jeeva'' Ravi","avatar":""},{"name":"Superg","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324229);
