INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vien-ngoc-den', 'Viên Ngọc Đen', 'Rathnam', 'viên ngọc đen rathnam vishal krishna priya bhavani shankar samuthirakani murli sharma hareesh peradi muthukumar yogi babu vijayakumar jayaprakash tulasi rajendran ganesh venkatraman y. g. mahendran mohan raman gajaraj kumki ashwin ''jeeva'' ravi superg ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-manh-ba-2024', 'Truyền Thuyết Mạnh Bà', 'Legend of Meng Po', 'https://phimimg.com/upload/vod/20240810-1/90080fe6fc088593b9ff5843d77e4b20.jpg', 'https://phimimg.com/upload/vod/20240810-1/fb12e74c3ee6d2f2fd240fc586899d62.jpg', '<p>Có một cô gái tên là Tam Thất lúc nào cũng sống trong vùng đất tám trăm dặm sa mạc. Tính cách cô ấy hơi ngốc nghếch, tướng mạo thì tiều tụy, cô ấy làm bạn với người sắp chết. Vào một ngày nọ, có một chàng trai trẻ tên là Trường Sinh đã đến đây. Tam Thất bắt đầu biết yêu , nhưng sự xuất hiện của Trường Sinh, không chỉ mang đến cho cô ấy một tình yêu ngọt ngào, mà còn là một âm mưu bí mật nào đó. Tình yêu mới chớm nở của Tam Thất rồi sẽ đi về đâu?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"郝冠玉","avatar":""},{"name":"董金龙","avatar":""},{"name":"Li Yutong","avatar":""},{"name":"Lai Yi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324229);
