INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-thoi-kiep-an', 'Lâm Thời Kiếp Án', 'Rob N Roll', 'https://phimimg.com/upload/vod/20240810-1/b1aa3474ece534007796f686cc7ea940.jpg', 'https://phimimg.com/upload/vod/20240810-1/a58fa9220042cdf00291fc2f0c35a325.jpg', '<p>Câu chuyện xoay quanh một tên cướp khét tiếng lên kế hoạch cho một vụ cướp lớn, nhưng kế hoạch của hắn vô tình bị phá hỏng bởi hai người bạn trung niên chán nản. Số tiền bị cướp mất, buộc cả ba phải chạy trốn khỏi sự truy đuổi của một nữ cảnh sát quyết tâm, đồng thời tham gia vào những cuộc đấu súng nguy hiểm để giành lại số tiền</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Lam Ka-tung","avatar":""},{"name":"任賢齊","avatar":""},{"name":"Maggie Cheung Hoh-Yee","avatar":""},{"name":"Nancy Wu","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Leung Chung-Hang","avatar":""},{"name":"Calvert Fu Ka Tsun","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"鮑起靜","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"張松枝","avatar":""},{"name":"Anson Chan","avatar":""},{"name":"曾比特","avatar":""},{"name":"袁志健","avatar":""},{"name":"Jimmy Wong Wa-Wo","avatar":""},{"name":"John Chiang","avatar":""},{"name":"Jr.","avatar":""},{"name":"Hui Hei-Man","avatar":""},{"name":"王颂茵","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324229);
