INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-chu-muu-2024', 'Kẻ Chủ Mưu', 'The Instigators', 'https://phimimg.com/upload/vod/20240810-1/631d93690a3e6f64f01fb7cddfc033fc.jpg', 'https://phimimg.com/upload/vod/20240810-1/5e1f34c6336b1901b65b466911a93516.jpg', '<p>Rory và Cobby là cộng sự bất đắc dĩ: một người cha tuyệt vọng và một cựu tù nhân bị xô đẩy buộc phải thực hiện một vụ trộm với nhau. Khi mọi chuyện trở nên tồi tệ, họ hợp sức với một đồng phạm bất thường: nhà trị liệu của Rory để thoát khỏi cảnh sát, những quan chức lạc hậu và một tên trùm tội phạm đầy thù hận.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Hong Chau","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Paul Walter Hauser","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Jack Harlow","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"André De Shields","avatar":""},{"name":"Toby Onwumere","avatar":""},{"name":"Rob Gronkowski","avatar":""},{"name":"Natalie Carter","avatar":""},{"name":"Owen Earls","avatar":""},{"name":"Richie Moriarty","avatar":""},{"name":"David Gborie","avatar":""},{"name":"Shei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324229);
