INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-tai-gia', 'Đặc Vụ Tại Gia', 'Mission: Cross', 'https://phimimg.com/upload/vod/20240810-1/aa1338a13d40a79ab58b305ed7faf867.jpg', 'https://phimimg.com/upload/vod/20240810-1/6b08d9d7ad06582d873ff66152321dd6.jpg', '<p>Trong thử thách tột cùng của hôn nhân, một đặc vụ trở thành người chồng nội trợ bỗng vướng vào một nhiệm vụ nguy hiểm cùng người vợ thám tử không biết gì về quá khứ của anh.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"황정민","avatar":""},{"name":"염정아","avatar":""},{"name":"전혜진","avatar":""},{"name":"정만식","avatar":""},{"name":"김주헌","avatar":""},{"name":"차래형","avatar":""},{"name":"김찬형","avatar":""},{"name":"이호철","avatar":""},{"name":"김준한","avatar":""},{"name":"옥자연","avatar":""},{"name":"Kim Byung-nam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324229);
