INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-an-mat-tham-hoa-tren-cau', 'Dự Án Mật: Thảm Họa Trên Cầu', 'Project Silence', 'https://phimimg.com/upload/vod/20240810-1/f811fa89f8a02c39da05f8544cbc5c88.jpg', 'https://phimimg.com/upload/vod/20240810-1/4317864656ccb66c2c45de72fd97d296.jpg', '<p>Do điều kiện thời tiết xấu đi đột ngột, tầm nhìn trên cây cầu đến sân bay bị suy giảm nghiêm trọng, khiến người dân bị mắc kẹt và có nguy cơ sập cầu do hàng loạt va chạm dây chuyền và các vụ nổ. Giữa sự hỗn loạn, những chú chó &quot;Echo&quot; từ thí nghiệm quân sự &quot;Dự án Mật&quot;, đang được vận chuyển bí mật, thoát ra ngoài và tất cả những người sống sót đều trở thành mục tiêu của các cuộc tấn công không ngừng. Nhiều người bị mắc kẹt trên cầu vì nhiều lý do khác nhau - một quan chức chính phủ từ văn phòng tổng thống (LEE Sun Kyun), người đang tiễn con gái mình (KIM Su An) tại sân bay; tài xế xe đầu kéo (JU Ji Hoon) đang trên đường đến hiện trường vụ va chạm; một cặp vợ chồng già (MOON Sung Geun, YE Su Jeong) đang trở về sau chuyến đi nước ngoài; chị em (PARK Hee Von, PARK Ju Hyun) đã lỡ chuyến bay và Tiến sĩ Yang (Kim Hie Won), nhà nghiên cứu chịu trách nhiệm về Dự án Mật - và một cuộc đấu tranh tuyệt vọng bắt đầu để họ trốn thoát đến nơi an toàn.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"이선균","avatar":""},{"name":"주지훈","avatar":""},{"name":"김희원","avatar":""},{"name":"문성근","avatar":""},{"name":"예수정","avatar":""},{"name":"김태우","avatar":""},{"name":"박희본","avatar":""},{"name":"박주현","avatar":""},{"name":"김수안","avatar":""},{"name":"하도권","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324229);
