INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-troi-cau-chuyen-mien-tay-my-phan-1', 'Chân Trời: Câu Chuyện Miền Tây Mỹ - Phần 1', 'Horizon: An American Saga - Chapter 1', 'https://phimimg.com/upload/vod/20240810-1/f1ccc16cea31910d9d8abb6243847656.jpg', 'https://phimimg.com/upload/vod/20240810-1/6263972f50c10695e969107996af68f9.jpg', '<p>Phần 1 trong loạt phim 4 phần do Kevin Kostner đạo diễn. Truyện phim kể về quá trình mở rộng, định cư trước-sau cuộc nội chiến (1861-1865) đầy gian khổ &amp; cuộc xung đột đẫm máu giữa người da đỏ bản địa với người da trắng.
 Phần 2 sẽ khởi chiếu cuối tháng 8, phần 3-4 dự kiến chiếu năm 2025.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Abbey Lee","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Ella Hunt","avatar":""},{"name":"Tatanka Means","avatar":""},{"name":"Owen Crow Shoe","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Tom Payne","avatar":""},{"name":"Jamie Campbell Bower","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Georgia MacPhail","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"W","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
