INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chan-troi-cau-chuyen-mien-tay-my-phan-1', 'Chân Trời: Câu Chuyện Miền Tây Mỹ - Phần 1', 'Horizon: An American Saga - Chapter 1', 'chân trời: câu chuyện miền tây mỹ - phần 1 horizon: an american saga - chapter 1 kevin costner sienna miller sam worthington jena malone abbey lee michael rooker danny huston luke wilson ella hunt tatanka means owen crow shoe jeff fahey tom payne jamie campbell bower michael angarano georgia macphail giovanni ribisi w ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-choi-dai', 'Cuộc Chơi Dài', 'The Long Game', 'https://phimimg.com/upload/vod/20240810-1/ac3566098cc031e2b4fa35cf1518af87.jpg', 'https://phimimg.com/upload/vod/20240810-1/880f920680c3de278daa6dc5a531b0cb.jpg', '<p>&quot;The Long Game&quot; (2024) là một bộ phim dựa trên câu chuyện có thật. Nội dung phim kể về năm cậu bé người Mỹ gốc Mexico, làm caddie vào năm 1955. Với tình yêu mãnh liệt dành cho golf, họ quyết tâm học chơi môn thể thao này và đã tạo ra sân golf của riêng mình giữa sa mạc Nam Texas.</p><p>Bộ phim không chỉ xoay quanh niềm đam mê và sự quyết tâm của những cậu bé này, mà còn khắc họa bối cảnh lịch sử và xã hội của thời kỳ đó, với những thách thức mà cộng đồng người Mỹ gốc Mexico phải đối mặt. Những khó khăn và định kiến mà họ gặp phải chỉ càng làm tăng thêm quyết tâm và sự đoàn kết của nhóm.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jay Hernandez","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Julian Works","avatar":""},{"name":"Jaina Lee Ortiz","avatar":""},{"name":"Brett Cullen","avatar":""},{"name":"Óscar Núñez","avatar":""},{"name":"Paulina Chávez","avatar":""},{"name":"Gregory Diaz IV","avatar":""},{"name":"José Julián","avatar":""},{"name":"Christian Gallegos","avatar":""},{"name":"Miguel Ángel García","avatar":""},{"name":"Gillian Vigman","avatar":""},{"name":"Richard Robichaux","avatar":""},{"name":"Jimmy Gonzales","avatar":""},{"name":"Michael Southwor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324229);
