INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-mau-tinh-yeu-tram-nam', 'Phép Màu Tình Yêu Trăm Năm', 'Century Of Love', 'https://phimimg.com/upload/vod/20240720-1/201de45ff5101d2f25ff9a607caa3520.jpg', 'https://phimimg.com/upload/vod/20240720-1/0ab367d06fba30c1540535bb5718d064.jpg', '<p><span style="text-wrap: nowrap;">San chung thủy hết lòng vì tình yêu của mình. Anh đã dành cả cuộc đời để chờ đợi người yêu đã mất của mình, Wad, tái sinh sau cái chết của cô một thế kỷ trước. Nhưng khi màn đêm buông xuống, anh sẽ bị sức mạnh của đá ngũ sắc hành hạ. Nếu anh ta không tìm thấy trong cửa sổ thời gian của thế kỷ này, anh ta chắc chắn sẽ phải chịu một cái chết bi thảm mãi mãi.</span></p><p><span style="text-wrap: nowrap;">Năm cuối cùng của thế kỷ sắp kết thúc trước khi sức mạnh của viên đá biến thành lời nguyền vĩnh cửu của anh. Anh gặp Vee, một nữ thần phù phiếm, quyến rũ, người dường như có mối liên hệ với cuộc đời anh.</span></p><p><span style="text-wrap: nowrap;">San cảm thấy kinh hoàng trước Vee ngay từ cái nhìn đầu tiên, nhưng cậu bé không liên quan này thực sự là Wad yêu quý của anh, người mà anh đã mong đợi gần một thế kỷ.</span></p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Daou Pittaya Saechua","avatar":""},{"name":"กันตภณ จินดาทวีผล","avatar":""},{"name":"Cookie Yada Suwanpattana","avatar":""},{"name":"พลวิชญ์ เกตุประภากร","avatar":""},{"name":"Pornsroung Rouyruen","avatar":""},{"name":"Gumpuns Koravich Sarasin","avatar":""},{"name":"Deuntem Salitul","avatar":""},{"name":"เพ็ญเพ็ชร เพ็ญกุล","avatar":""},{"name":"จิราวัฒน์ วชิรศรัณย์ภัทร","avatar":""},{"name":"Parattakorn Kaiyanan","avatar":""},{"name":"Natpongpon Suddee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
