INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('king-kong-tro-lai', 'King Kong Trở Lại', 'King Kong is Coming Back', 'https://phimimg.com/upload/vod/20240809-1/691d2ba759f2182dd2147e8e1e993d5a.jpg', 'https://phimimg.com/upload/vod/20240809-1/ad96a3d5c2cd12023ca468105c7e16d4.jpg', '<p>Bộ phim thông qua câu chuyện một nhóm người cùng chung sống với một con khỉ đột khổng lồ trong rừng sâu kể về quá trình gặp gỡ và nhận nhau giữa đứa trẻ được khỉ đột nuôi dưỡng tên Cố Nghiêu và cha mẹ đến thám hiểm của cậu tên Mã Khả. Câu chuyện đầy kịch tính và ly kỳ, hình ảnh hùng vĩ và tuyệt đẹp, thể hiện chủ đề muôn thuở về sự cần thiết của mối quan hệ hòa hợp giữa con người và thiên nhiên.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jason Chu Wing-Tong","avatar":""},{"name":"Sun Jianhong","avatar":""},{"name":"Gabriel Wong","avatar":""},{"name":"Wang Lei","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324229);
