INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-son-thu-lang-nhan', 'Âm Sơn Thủ Lăng Nhân', 'Tomb Guarding Man', 'https://phimimg.com/upload/vod/20240809-1/e057dfa56aef83d475bc7910738fb22e.jpg', 'https://phimimg.com/upload/vod/20240809-1/e2b0fa0e98ff43289e6483e3c29c47cd.jpg', '<p>Tương truyền rằng dưới chân núi Âm Sơn có một ngôi mộ cổ nghìn năm bằng da vàng chứa một bảo vật quý giá. Những tin đồn huyền bí về bảo vật này đã thu hút nhiều người đến để dòm ngó. Một thời gian, những kẻ mang tâm địa xấu xa tụ tập tại trấn An Lăng. Trong thời gian đó, hàng loạt các sự kiện ly kỳ và quái dị như hiến tế người sống và mượn xác hoàn hồn cũng lần lượt diễn ra do cuộc săn tìm bảo vật...</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Du Yiheng","avatar":""},{"name":"He Qiwei","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Zhu Xinyuan","avatar":""},{"name":"Paul Che Biu-law","avatar":""},{"name":"An Jianlin","avatar":""},{"name":"Zeng Chen","avatar":""},{"name":"Chen Yuyong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324229);
