INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-ca-xong-pha-dong-bac', 'Đông Ca Xông Pha Đông Bắc', 'Once Upon A Time In Asia', 'https://phimimg.com/upload/vod/20240809-1/1626ede81fb1292494fbfaa75779c361.jpg', 'https://phimimg.com/upload/vod/20240809-1/74cfe3c273df89a24c3a4f9c9653c58b.jpg', '<p>Bộ phim kể về trùm Đông Bắc Tạ Văn Đông phát triển ngành bất động sản ở Đông Nam Á gây ra mâu thuẫn không ngừng với tập đoàn Lợi Ích. Sau khi người thân liên tiếp bị bức hại, Tạ Văn Đông trở về Đông Bắc, đưa mẹ mai danh ẩn tích để an hưởng tuổi già. Tại địa phương, ông bị bọn côn đồ áp bức, kẻ thù từ Đông Nam Á cũng tìm đến. Vì mẹ và cô gái Đông Bắc thích mình là Vương Tử Hàm, Tạ Văn Đông một lần nữa bước lên con đường trả thù ở Đông Nam Á.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Jianguo","avatar":""},{"name":"Kan Xin","avatar":""},{"name":"Li Kui","avatar":""},{"name":"李子雄","avatar":""},{"name":"郭强","avatar":""},{"name":"邓洛淋","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
