INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-chieu', 'Quá Chiêu', 'The Love Duel', 'https://phimimg.com/upload/vod/20240729-1/3260c861bad4f4cba363f81d9fe170f0.jpg', 'https://phimimg.com/upload/vod/20240729-1/bd1bc7586a1846d9e8da5d1e5a929a97.jpg', '<p>Một cô gái mạnh mẽ, phóng khoáng buộc phải đóng vai nha hoàn chịu mọi áp bức, một tổng giám đốc nhã nhặn buộc phải giả vờ làm vương gia tàn ác. Cô mài đao hằng đêm, thử đủ mọi cách để lấy mạng anh. Anh trêu ghẹo mỗi ngày, tấn công trái tim cô một cách gian nan. Cùng xem trong màn giằng co trí mạng vừa buồn cười vừa xao động này, ai sẽ vươn lên giành thắng lợi trước? Trong lúc đọ chiêu, hai bên mới phát hiện ra đã bị cuốn vào một âm mưu.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hu Dandan","avatar":""},{"name":"Wang Xuan","avatar":""},{"name":"Leo Yang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324229);
