INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-ngay-va-dem', 'Cô Ấy, Ngày Và Đêm', 'Miss, Night and Day', 'https://phimimg.com/upload/vod/20240606-1/6df508ab924ffcd6c6955e6189e215d7.jpg', 'https://phimimg.com/upload/vod/20240606-1/5fa46714e4fbb0878e87c3b4108441c3.jpg', '<p>Chuyển qua lại một cách kỳ diệu giữa độ tuổi 20 và 50, người phụ nữ nọ nhận được suất thực tập tại cơ quan công tố rồi mắc kẹt giữa hai thế hệ và một vị sếp khó tính.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이정은","avatar":""},{"name":"정은지","avatar":""},{"name":"최진혁","avatar":""},{"name":"윤병희","avatar":""},{"name":"정석용","avatar":""},{"name":"정영주","avatar":""},{"name":"김아영","avatar":""},{"name":"Baek Seo Hoo","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324229);
