INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-ay-ngay-va-dem', 'Cô Ấy, Ngày Và Đêm', 'Miss, Night and Day', 'cô ấy, ngày và đêm miss, night and day 이정은 정은지 최진혁 윤병희 정석용 정영주 김아영 baek seo hoo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-ta-gap-nhau', 'Ngày Ta Gặp Nhau', 'The Best Day of My Life', 'https://phimimg.com/upload/vod/20240725-1/d7c4fdfeea978c476fb6d045523f1226.jpg', 'https://phimimg.com/upload/vod/20240725-1/b79540aec49a459dcfaa3812644db256.jpg', '<p>Nhân viên kế hoạch của công ty quảng cáo Thương Tâm - Hứa Mộ vừa nếm trải sự thất bại trong buổi xem mặt lần thứ sáu, nhưng theo như lời cô nói, tìm người yêu không phải đi mua đồ, chỉ nhìn các điều kiện bên ngoài thì quá là vật chất, cho dù bố mẹ hối thúc kết hôn nhưng vẫn luôn giữ đúng chừng mực. Mặc dù gặp nhiều trắc trở trong chuyện tình cảm nhưng lại có chút thành tựu trong công việc. Một lần, trong cuộc họp đề án với bên A, Hứa Mộ gặp lại bạn cùng bàn thời cấp ba là Tạ Thời, sau bao nhiêu năm, Tạ Thời đã trở thành một tổng giám bên A lạnh lùng mưu mô, bánh xe vận mệnh cứ vậy mà xoay vòng. Vì một lần nhầm lẫn trong cơn say, Tạ Thời đã trở thành bạn trai chính thức của Hứa Mộ trong mắt bạn bè, đứng trước những lời chúc mừng vô duyên vô cớ của bạn bè người thân, Hứa Mộ tiến thoái lưỡng nan, hai người miễn cưỡng đâm lao nên phải theo lao, trở thành người yêu hợp đồng, bắt đầu sống thử với nhau.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Jiongmin","avatar":""},{"name":"姜之南","avatar":""},{"name":"Wang Chuan","avatar":""},{"name":"严智超","avatar":""},{"name":"He Lei","avatar":""},{"name":"Gou Zhongbin","avatar":""},{"name":"Wu Ren Yuan","avatar":""},{"name":"Zheng Xiao Wan","avatar":""},{"name":"Zhang Haoyue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324230);
