INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-khu-den-toi', 'Quá Khứ Đen Tối', 'MaXXXine', 'https://phimimg.com/upload/vod/20240804-1/3476688694c9d85714b134c6c337e3df.jpg', 'https://phimimg.com/upload/vod/20240804-1/ec5a850b6fc0c36cef62537cced2f352.jpg', '<p>Vào những năm 1980 ở Hollywood, ngôi sao phim người lớn và nữ diễn viên đầy tham vọng Maxine Minx cuối cùng cũng có được bước đột phá lớn. Nhưng khi một kẻ giết người bí ẩn rình rập những ngôi sao trẻ của Hollywood, một vệt máu đe dọa sẽ tiết lộ quá khứ đen tối của cô.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mia Goth","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Moses Sumney","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Halsey","avatar":""},{"name":"Lily Collins","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Charley Rowan McCain","avatar":""},{"name":"Simon Prast","avatar":""},{"name":"Deborah Geffner","avatar":""},{"name":"Daniel Lench","avatar":""},{"name":"Chloe Farnworth","avatar":""},{"name":"Brad Swanick","avatar":""},{"name":"Uli Latukefu","avatar":""},{"name":"Susan Ping","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324230);
