INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-nhang', 'Lăng Nhăng', 'Balinsasayaw', 'https://phimimg.com/upload/vod/20240804-1/f883be048509a7e9cc03a60cd6d4f252.jpg', 'https://phimimg.com/upload/vod/20240804-1/59ab546fa127bfd14e8173771379dbf1.jpg', '<p>Một người phụ nữ giàu có kết hôn với một người lăng nhăng quyến rũ, người đang âm mưu với bạn thân của vợ anh ta. Khi mọi tiết lộ được phơi bày, tình thế bất ngờ thay đổi.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Apple Dy","avatar":""},{"name":"Aiko Garcia","avatar":""},{"name":"Benz Sangalang","avatar":""},{"name":"Jonica Lazo","avatar":""},{"name":"Aria Bench","avatar":""},{"name":"Izza Watanabe","avatar":""},{"name":"Marc Capilador","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
