INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-bo-bat-on-phan-2', 'Ông Bố Bất Ổn (Phần 2)', 'Unstable (Season 2)', 'https://phimimg.com/upload/vod/20240804-1/a9a1e27816c5b14521d16c421a54c8fa.jpg', 'https://phimimg.com/upload/vod/20240804-1/5a84c4fb67b18ddb7defd60b849da75b.jpg', '<p>Anh là thiên tài công nghệ sinh học lập dị. Con trai anh là người thực dụng, sống dưới cái bóng của anh. Để cứu việc kinh doanh của gia đình, họ sẽ phải giải quyết một số vấn đề.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rob Lowe","avatar":""},{"name":"John Owen Lowe","avatar":""},{"name":"Sian Clifford","avatar":""},{"name":"Rachel Marsh","avatar":""},{"name":"Emma Ferreira","avatar":""},{"name":"Aaron Branch","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
