INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('say-de-yeu-em', 'Say Để Yêu Em', 'Drunk To Love You', 'https://phimimg.com/upload/vod/20240804-1/735634f5b82d39ecc50aa7c8834b1ff6.jpg', 'https://phimimg.com/upload/vod/20240804-1/cc9d98973ac2443f7e1f25e887e6b05b.jpg', '<p>Jiang Lu, người cũng khẳng định mình không bao giờ say, đã cho Liu Yali nếm thử khi gặp đối thủ của mình, và lần đầu tiên sau một thời gian dài, cô thấy mình &quot;say&quot; ngay tại chỗ. Tỉnh dậy sau cơn say, Liu Yali thề sẽ tìm Jiang Lu, nhưng rồi phát hiện ra rằng người đàn ông bí ẩn Jiang Lu thực sự là ông chủ mới mà cô chưa từng gặp trước đây! Dường như còn nhiều điều hơn thế nữa đằng sau khả năng &quot;nén rượu&quot; của anh ấy...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"董又霖","avatar":""},{"name":"林昕宜","avatar":""},{"name":"徐棵二","avatar":""},{"name":"柴燁","avatar":""},{"name":"梁曉龍","avatar":""},{"name":"朱良奇","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324230);
