INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-giua-dat-troi-dao-dien', 'Yêu Giữa Đất Trời Đảo Điên', 'Undercover Affair', 'https://phimimg.com/upload/vod/20240804-1/8a47eceb36dbbaa3274706aa3784cbf2.jpg', 'https://phimimg.com/upload/vod/20240804-1/b95fb95ccc1461fd3f7112fa4fcda3b4.jpg', '<p><span style="text-wrap: nowrap;">Tại một quán bar, Sen từ Nhóm Kuntai gặp Ling Yi, một nữ tiếp viên và con đường của họ đan xen nhau. Trong quá trình tương tác của họ, Sen biết được nỗi đau khổ của Ling Yi sau khi bị bạn trai bỏ rơi kể từ khi cô bị giam vì vô tình gây ra cái chết cho ai đó. Dù đã khép kín tình cảm nhưng Sen vẫn thấy mình thực sự bị thu hút bởi cô gái tốt bụng này.</span></p><p><span style="text-wrap: nowrap;">Một ngày nọ, Sen thú nhận với Ling Yi rằng anh là cảnh sát chìm, người đã dành cả thập kỷ thâm nhập vào các hoạt động tội phạm của Tập đoàn Kuntai với hy vọng cuối cùng sẽ đưa họ ra trước công lý. Giữa những tình huống nguy hiểm, mối quan hệ của Sen và Ling Yi ngày càng phát triển khi họ tìm thấy niềm an ủi ở nhau. Cả hai đều hứa sẽ cùng nhau bắt đầu lại từ đầu sau khi mọi chuyện kết thúc.</span></p><p><br/></p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leo Yang","avatar":""},{"name":"Han Xinyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324230);
