INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-nu-canh-sat-ao-xanh', 'Biệt Đội Nữ Cảnh Sát Áo Xanh', 'Women in Blue', 'https://phimimg.com/upload/vod/20240801-1/130d8d2a4012274290796d1f8a0b0b3a.jpg', 'https://phimimg.com/upload/vod/20240801-1/c7574d194973ff04935100a3d1973d96.jpg', '<p>Năm 1971, bốn phụ nữ bất chấp những chuẩn mực cực kì bảo thủ và gia nhập lực lượng cảnh sát nữ đầu tiên của Mexico - chỉ để phát hiện ra rằng đó là một chiêu trò quảng bá nhằm đánh lạc hướng giới truyền thông khỏi một kẻ giết người hàng loạt. Khi số lượng thi thể ngày càng tăng, họ thỏa thuận với nhau đưa kẻ giết người ra trước công lí.</p>', 'Tập 2', 10, 'series', 'ongoing', 20, 2024, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Bárbara Mori","avatar":""},{"name":"Ximena Sariñana","avatar":""},{"name":"Natalia Téllez","avatar":""},{"name":"Amorita Rasgado","avatar":""},{"name":"Miguel Rodarte","avatar":""},{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Christian Tappán","avatar":""},{"name":"Horacio García Rojas","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
