INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cai-dao', 'Kẻ Cải Đạo', 'The Convert', 'https://phimimg.com/upload/vod/20240801-1/3e2b4dda6120d5aa2d7b07bae752548a.jpg', 'https://phimimg.com/upload/vod/20240801-1/dd0421ca8e3acad9b4a5b6c862728ee6.jpg', '<p>Bộ phim lấy bối cảnh những năm 1830, kể về Thomas Munro (Guy Pearce thủ vai), một nhà truyền giáo người Anh đến định cư tại một khu vực của Anh ở New Zealand. Được thách thức bởi quá khứ bạo lực và đức tin của mình, Munro bị cuốn vào cuộc xung đột đẫm máu giữa các bộ tộc Maori.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Tioreore Ngatai-Melbourne","avatar":""},{"name":"Antonio Te Maioha","avatar":""},{"name":"Jacqueline McKenzie","avatar":""},{"name":"Te Kohe Tuhaka","avatar":""},{"name":"Lawrence Makoare","avatar":""},{"name":"Dean O''Gorman","avatar":""},{"name":"Jared Turner","avatar":""},{"name":"Kelly Vivian","avatar":""},{"name":"Jack Barry","avatar":""},{"name":"Marris Collins","avatar":""},{"name":"Duane Evans Jr.","avatar":""},{"name":"Andrew G Hill","avatar":""},{"name":"Renee Lyons","avatar":""},{"name":"Leonard Mathews","avatar":""},{"name":"Made","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
