INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhien-tam', 'Nhiên Tâm', 'Crush', 'https://phimimg.com/upload/vod/20240801-1/875248071730bf08275e504d2a71aa87.jpg', 'https://phimimg.com/upload/vod/20240801-1/32ae47419e70c295dcd59b288b315eb4.jpg', '<p>Nhiên Tâm là phim truyền hình cổ trang hành động và bí ẩn. Phim kể về Fu Yun Yue, người đứng thứ hai của bang Long Thành Xích Diễm, đã không nghe lời ngăn cản của người anh trai là Fu Yun Zheng, giả dạng để tiếp cận với Shen Xi Ze, thiếu gia nhà họ Shen. Mục đích của Fu Yun Yue là để trả thù cho mẹ mình bằng cách ám sát ông lão Shen Wen De của gia đình Shen. Tuy nhiên, trong quá trình thực hiện, cô phát hiện ra những bí mật sâu xa hơn nhiều so với những gì cô và mọi người đã biết. Trong quá trình giả dạng và gần gũi với Shen Xi Ze, Fu Yun Yue bắt đầu phát triển tình cảm thực sự với anh, điều này khiến cô phải đối mặt với xung đột nội tâm giữa lòng trung thành với gia tộc và tình yêu dành cho Shen Xi Ze. Càng tìm hiểu sâu về gia đình Shen, Fu Yun Yue càng nhận ra rằng cái chết của mẹ mình có nhiều uẩn khúc và liên quan đến các âm mưu lớn hơn trong giới quý tộc. Câu chuyện trở nên phức tạp khi Fu Yun Yue khám phá ra những bí mật đen tối của gia tộc Shen và thấy mình bị cuốn vào một mạng lưới quyền lực và báo thù phức tạp, nơi mỗi quyết định của cô có thể ảnh hưởng đến số phận của nhiều người. Cuối cùng, cô phải đưa ra quyết định giữa việc thực thi công lý cho mẹ mình hay bảo vệ người mà cô yêu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Yingbo","avatar":""},{"name":"Ling Mei Shi","avatar":""},{"name":"高天妮","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324230);
