INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-ket-hon-dau-tien', 'Lần Kết Hôn Đầu Tiên', 'First Marriage', 'https://phimimg.com/upload/vod/20240730-1/1748131d54d6d295facb844414dcfc7b.jpg', 'https://phimimg.com/upload/vod/20240730-1/1166a8ed795db797a8b7391575e233d9.jpg', '<p>Bộ phim kể về câu chuyện của cô gái đã mai danh ẩn tính đi du học tên là Phùng Vũ Tễ, để báo thù cho người chị song sinh của mình, cô đã giả danh làm chị mình, thiếu phu nhân của nhà họ Thẩm để trở lại nhà họ Thẩm. Cô tiếp cận con trai của một thương gia giàu có, Thẩm Đàn Khiêm, và bắt đầu điều tra chân tướng vụ việc, từ đó đã phơi bày sự thật về một vụ án mạng đã bị chôn giấu từ lâu, khiến kẻ thù phải tự chịu quả báo. Trong quá trình đó, từ mối quan hệ không tin tưởng lẫn nhau, họ đã dần trở nên cởi mở và chữa lành lẫn nhau. Cuối cùng, nhờ vào sự dũng cảm, khôn ngoan và sức mạnh của tình yêu thật sự sẵn sàng hy sinh cho nhau, sự thật của năm đó đã được phơi bày rõ ràng trước mắt mọi người. Đồng thời, với sự vén màn sự thật và nỗ lực chung của cặp đôi nam nữ chính, việc kinh doanh thuốc phiện của nhà họ Thẩm và người Nhật đã bị dẹp bỏ hoàn toàn, và thói quen hút thuốc phiện trong thành phố cũng dần được xoá bỏ, thiết lập nên một phong cách mới khoa học và văn minh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Rilige","avatar":""},{"name":"于杨","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324230);
