INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('niem-niem-nhan-gian-ngoc', 'Niệm Niệm Nhân Gian Ngọc', 'The Fragments of Kylin', 'https://phimimg.com/upload/vod/20240731-1/9401849ea591267583031d567ddb9ce7.jpg', 'https://phimimg.com/upload/vod/20240731-1/371cba55b061588711877b3a43fcf694.jpg', '<p>Liên hôn giữa hai gia tộc diệt ma lớn đã khiến Mạc Viêm và Hiên Viên Ngọc trở thành phu thê. Ban đầu, họ chỉ nghĩ rằng mối quan hệ hôn nhân chỉ là tạm thời trong hai năm, nhưng Mạc Viêm lại phát hiện ra rằng, nàng từ lâu đã chiếm lĩnh trái tim anh... Với những mâu thuẫn liên tục nảy sinh và sự thật ẩn sau vẻ bề ngoài, liệu họ có thể thực sự đến với nhau không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"楊肸子","avatar":""},{"name":"Sun Chenjun","avatar":""},{"name":"Gao Zitian","avatar":""},{"name":"He Shi","avatar":""},{"name":"Cen Ming","avatar":""},{"name":"Xu Nuo Yan","avatar":""},{"name":"Jiang Chen","avatar":""},{"name":"Zheng Chu Chen","avatar":""},{"name":"Hollis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324230);
