INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lhakpa-sherpa-nu-hoang-dinh-everest', 'Lhakpa Sherpa Nữ hoàng đỉnh Everest', 'Mountain Queen The Summits of Lhakpa Sherpa', 'https://phimimg.com/upload/vod/20240731-1/6e88b4e57d641f9095916f4eb9e1c122.jpg', 'https://phimimg.com/upload/vod/20240731-1/4c0819c6848d879ad8a76316044c5e50.jpg', '<p>Trong bộ phim tài liệu này, một nhà leo núi người Nepal mạo hiểm tất cả trong chuyến leo núi Everest phá kỷ lục để đảm bảo tương lai tươi sáng hơn cho các con gái của mình.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lhakpa Sherpa","avatar":""},{"name":"Shiny Dijmarescu","avatar":""},{"name":"Sunny Dijmarescu","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324230);
