INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-vat-an-tap', 'Động Vật Ăn Tạp', 'Omnivore', 'https://phimimg.com/upload/vod/20240731-1/227e786abc3ea2e412e420c09d7efb24.jpg', 'https://phimimg.com/upload/vod/20240731-1/c5f36e89f40099d50d88a6bca6db92d8.jpg', '<p>Từ đồng muối Peru đến rừng cà phê Rwanda, hãy cùng khám phá và tôn vinh những nguyên liệu đã gây dựng nên xã hội, định hình đức tin và mãi mãi thay đổi bức tranh con người.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"René Redzepi","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324230);
