INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-vat-an-tap', 'Động Vật Ăn Tạp', 'Omnivore', 'động vật ăn tạp omnivore rené redzepi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-dep-hon-anh-sao', 'Em Đẹp Hơn Ánh Sao', 'As Beautiful As You', 'https://phimimg.com/upload/vod/20240713-1/cb5f9ae8938535a2fe9d29a313dbdbfd.jpg', 'https://phimimg.com/upload/vod/20240713-1/debf03fc2d736137b71893a6f9bab8b7.jpg', '<p>Kỷ Tinh tốt nghiệp từ một trường Đại học có danh tiếng, cô là một sinh viên có kiến thức chuyên ngành rất vững chắc. Sau khi tốt nghiệp, Kỷ Tinh vào làm ở Quảng Hoa, hừng hực khí thế muốn tạo dựng một tương lai tươi sáng. Kết quả là hiện thực phũ phàng đã giáng cho cô một cái bạt tai. Đi làm ba năm, chưa xây dựng nên cơ đồ thì đã rơi vào đủ mọi “cạm bẫy” nơi công sở, trải qua nhiều nỗi đau. Với tư duy sắc bén, thông minh, sau khi cô xử lý xong việc ở công ty liền hiên ngang từ chức, bắt đầu khởi nghiệp. Kỷ Tinh dám nghĩ dám làm, hơn nữa cô lại còn rất thông minh, vì vậy trên con đường khởi nghiệp dù có trắc trở những cô đã gặt hái được thành công riêng. Cô ấy gặp được Hàn Đình - “Bá Lạc” của đời mình, cũng là nhà đầu tư cho dự án khởi nghiệp của cô.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"譚松韻","avatar":""},{"name":"許凱","avatar":""},{"name":"He Ruixian","avatar":""},{"name":"Gao Han","avatar":""},{"name":"施詩","avatar":""},{"name":"Wu Shile","avatar":""},{"name":"周大為","avatar":""},{"name":"Wang Yilan","avatar":""},{"name":"Tang Zhenchao","avatar":""},{"name":"Luo Zekai","avatar":""},{"name":"Hailan Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
