INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-beverly-hills-axel-f', 'Cảnh Sát Beverly Hills: Axel F', 'Beverly Hills Cop: Axel F', 'https://phimimg.com/upload/vod/20240529-1/6fd7d1d0704321572e9e773998bdb26f.jpg', 'https://phimimg.com/upload/vod/20240529-1/9486c00f78bd065a054c5cf03236749d.jpg', '<p>Thám tử Axel Foley quay trở lại hoạt động ở Beverly Hills. Sau khi mạng sống của con gái Jane bị đe dọa, cô và Foley hợp tác với một đối tác mới và những người bạn cũ Billy Rosewood và John Taggart để làm nóng lên và khám phá một âm mưu.</p>', 'Full', 1, 'single', 'ongoing', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Judge Reinhold","avatar":""},{"name":"John Ashton","avatar":""},{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Taylour Paige","avatar":""},{"name":"Paul Reiser","avatar":""},{"name":"Bronson Pinchot","avatar":""},{"name":"James Preston Rogers","avatar":""},{"name":"Giovannie Cruz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324230);
