INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-kho-can', 'Vùng Đất Khô Cằn', 'The Dead Don''t Hurt', 'https://phimimg.com/upload/vod/20240730-1/b94616191f0ace69cece9f1ba0a4c9f4.jpg', 'https://phimimg.com/upload/vod/20240730-1/b9686d7505aee53218eac55141a1d58d.jpg', '<p>Bối cảnh phim diễn ra vào những năm 1860, nơi Vivienne Le Coudy (Vicky Krieps thủ vai) và Holger Olsen (Viggo Mortensen thủ vai) gặp nhau và nảy sinh tình cảm. Tuy nhiên, họ phải đối mặt với nhiều khó khăn và thử thách trong môi trường khắc nghiệt của miền Tây hoang dã. Bất chấp mọi gian nan, tình yêu và sự kiên cường của họ giúp vượt qua mọi thử thách, tạo nên một câu chuyện đầy cảm hứng về sự hy sinh và lòng kiên định.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Vicky Krieps","avatar":""},{"name":"Viggo Mortensen","avatar":""},{"name":"Solly McLeod","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"W. Earl Brown","avatar":""},{"name":"Shane Graham","avatar":""},{"name":"Rafel Plana","avatar":""},{"name":"Colin Morgan","avatar":""},{"name":"Ray McKinnon","avatar":""},{"name":"Atlas Green","avatar":""},{"name":"Alex Breaux","avatar":""},{"name":"Michael Weaver","avatar":""},{"name":"Angela Lentz","avatar":""},{"name":"Nadia Litz","avatar":""},{"name":"Marc Dennis","avatar":""},{"name":"John Getz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
