INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-la-chong-sap-cuoi', 'Chỉ Là Chồng Sắp Cưới', 'Life is Drama', 'https://phimimg.com/upload/vod/20240730-1/2928c749c3aa0f2c538ecdc1cfd01df0.jpg', 'https://phimimg.com/upload/vod/20240730-1/3780ff7c877555ac21d7016acd637fe8.jpg', '<p>Sau khi gia đình gặp biến cố, Thượng Quan Sơ Hạ mất trí nhớ và được nhận nuôi, đổi tên thành Phùng Đông Đông. Cô tình cờ quen biết Vân Tô và bất ngờ nhớ lại thân thế của mình. Để điều tra chân tướng, cô đóng giả làm người hầu chua ngoa, chỉnh đốn lại nhà họ Thượng Quan và hợp tác với Vân Tô - chồng chưa cưới theo hợp đồng của mình để đưa hung thủ ra trừng trị trước pháp luật. Trong quá trình tiếp xúc, hai người dần cảm nhận được tìm cảm đối phương dành cho mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hiên","avatar":""},{"name":"Bồ Ngọc Đồng","avatar":""},{"name":"Chu Thiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324230);
