INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chi-la-chong-sap-cuoi', 'Chỉ Là Chồng Sắp Cưới', 'Life is Drama', 'chỉ là chồng sắp cưới life is drama vương hiên bồ ngọc đồng chu thiên ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kieu-nguyet-luu-hoa', 'Kiểu Nguyệt Lưu Hỏa', 'Secrets of The Shadow Sect', 'https://phimimg.com/upload/vod/20240730-1/b770d4c195e87bc5efdd1d50cea59e73.jpg', 'https://phimimg.com/upload/vod/20240730-1/85a74b05c3ea1526ed8c809587cb6c61.jpg', '<p>Võ lâm có Linh Thiên Cung nửa chính nửa tà, thế lực hùng mạnh nhưng quy ẩn đã lâu. Mười năm trước, trong một lần du ngoạn, thiếu cung chủ Linh Huyền bắt gặp một cặp huynh muội hấp hối. Cô lập ra giao ước mười năm với người ca ca, lấy việc cứu sống muội muội y làm điều kiện để đưa y vào Ảnh Các của Linh Thiên Cung huấn luyện. Nếu mười năm sau y có thể sống sót trở ra thì sẽ trở thành trợ thủ của cô. Thiếu niên trải qua muôn vàn cuộc vật lộn chém giết, thập tử nhất sinh, cuối cùng đã sống sót rời khỏi Ảnh Các với cái tên Ảnh Thập. Tuy nhiên lúc này, Linh Thiên Cung nguy cơ rình rập, lão cung chủ vì muốn chiếm đoạt công pháp Vạn Tâm Quyết của mẹ Linh Huyền mà bất chấp làm loạn võ lâm, thậm chí trở mặt với con gái ruột. Linh Huyền đành phải đóng vai một kẻ vô dụng phóng đãng, tính tình quái đản, tàn nhẫn ác độc nhằm tự bảo vệ mình, chờ thời cơ lên kế hoạch phản kích. Đúng lúc này, Ảnh Thập phụng mệnh Ảnh Các tìm kiếm Vạn Tâm Quyết và đến bên Linh Huyền.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"胡亦瑤","avatar":""},{"name":"林澤輝","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324230);
