INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-day-dinh-menh', 'Sợi Dây Định Mệnh', 'TERJERAT', 'https://phimimg.com/upload/vod/20240624-1/d655fc9960c580e5352da83125ec172f.jpg', 'https://phimimg.com/upload/vod/20240624-1/89b4b6e79bee7029a724c858a7a0fe5d.jpg', '<p>Bộ phim kể về câu chuyện về Nadia (do Ruhainies thủ vai), người bị lu mờ bởi cuộc khủng hoảng nợ nần của chồng cô, Izham (do Fendy Bakry thủ vai), người rất nghiêm túc vì cờ bạc. Nadia bị cô ấy cá cược chủ nợ của chồng. Thật bất ngờ, Nadia gặp Faliq (do Aliff Aziz thủ vai), người đã bị mắc kẹt trước đó. Ngày tháng trôi qua, mối quan hệ thuần khiết của họ trở thành một mối quan hệ yêu đương bị cấm đoán. đầu hàng số phận và không nhận ra điều đó, họ đã vướng vào một trò chơi tình yêu bị cấm đoán. Diễn viên: Aliff Aziz trong vai Faliq Ruhanies trong vai Nadia Fendy Bakry trong vai Izham Jaja Iliyes trong vai Anis&quot;.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Aliff Aziz","avatar":""},{"name":"Ruhainies Farehah","avatar":""},{"name":"Haifa Halina","avatar":""},{"name":"Jaja Iliyes","avatar":""},{"name":"Fendy Bakry","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324230);
