INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-khung-hoang-trai-dat-vo-cuc-phan-3', 'Liên Minh Công Lý: Khủng Hoảng Trái Đất Vô Cực (Phần 3)', 'Justice League: Crisis on Infinite Earths (Part 3)', 'https://phimimg.com/upload/vod/20240728-1/263096072a5a42dbc24b57aa850dcdfe.jpg', 'https://phimimg.com/upload/vod/20240728-1/9a4b1c860bf9bd69d8f11b0f56cae8e8.jpg', '<p>Hiện đã được tiết lộ đầy đủ là mối đe dọa cuối cùng đối với sự tồn tại, Anti-Monitor tiến hành một cuộc tấn công không ngừng vào những Trái đất còn sống sót đang đấu tranh sinh tồn trong một vũ trụ bỏ túi. Từng người một, những thế giới này và tất cả cư dân của chúng đều bị bốc hơi! Trên các hành tinh còn sót lại, ngay cả thời gian cũng bị tan vỡ, và các anh hùng từ quá khứ gia nhập Justice League và các đồng minh của họ để chống lại hình ảnh thu nhỏ của cái ác. Nhưng khi họ đứng vững cuối cùng, liệu sự hy sinh của các siêu anh hùng có đủ để cứu tất cả chúng ta?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jensen Ackles","avatar":""},{"name":"Darren Criss","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Gideon Adlon","avatar":""},{"name":"Ike Amadi","avatar":""},{"name":"Geoffrey Arend","avatar":""},{"name":"Troy Baker","avatar":""},{"name":"Brian Bloom","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Ashly Burch","avatar":""},{"name":"Zach Callison","avatar":""},{"name":"Kevin Conroy","avatar":""},{"name":"Alexandra Daddario","avatar":""},{"name":"Brett Dalton","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Meg Donnelly","avatar":""},{"name":"Ato Essandoh","avatar":""},{"name":"Keith Ferguson","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324230);
