INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lien-minh-cong-ly-khung-hoang-trai-dat-vo-cuc-phan-3', 'Liên Minh Công Lý: Khủng Hoảng Trái Đất Vô Cực (Phần 3)', 'Justice League: Crisis on Infinite Earths (Part 3)', 'liên minh công lý: khủng hoảng trái đất vô cực (phần 3) justice league: crisis on infinite earths (part 3) jensen ackles darren criss corey stoll gideon adlon ike amadi geoffrey arend troy baker brian bloom matt bomer ashly burch zach callison kevin conroy alexandra daddario brett dalton john dimaggio meg donnelly ato essandoh keith ferguson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-minh-co-ca-con', 'Bắc Minh Có Cá Côn', 'Kun in the Distant Ocean', 'https://phimimg.com/upload/vod/20240728-1/e68f7134f0a068430dd37f3b86b56857.jpg', 'https://phimimg.com/upload/vod/20240728-1/34eca73a977991fe8fe05a50deab76d3.jpg', '<p>Hải thần cưới vợ, các thiếu nữ loài người đua nhau chủ động hiến tế. Linh Vũ, con gái một gia đình ngư dân vô tình bước vào cấm địa của tộc Hải thần, gặp một hoàng tử thật và một hoàng tử giả, một xấu một đẹp và rất nhiều cô dâu thây ma trong quan tài băng vô cùng đáng sợ. Hải thần vì cứu người vợ yêu dấu của mình mà bị yêu ma hãm hại, hai vợ chồng bị đóng băng trong địa cung. Hoàng tử Hải thần vì cha mẹ mình đã dũng cảm đột nhập vào Rừng Rắn Đen, nhưng lại vô tình mở phong ấn khiến Xà Yêu khổng lồ xuất hiện trở lại. Vào thời khắc nguy nan, những người thân xung quanh lại ngấm ngầm nổi ý định giết người, quay lưng lại với nhau khiến hoàng tử rơi vào bước đường cùng! Cá lớn bay lên không trung và nuốt chửng con người bằng cái miệng khổng lồ, trận quyết chiến giữa các thần thú kinh thiên động địa. Liệu hoàng tử trẻ có thể chiến thắng ác ma, giải cứu cha mẹ mình khỏi hàng loạt âm mưu và từ cá Côn biến thành thần hay không?</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Zhu Shengyi","avatar":""},{"name":"Xiao Xiangfei","avatar":""},{"name":"Wang Yitong","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324230);
