INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-khung-hoang-trai-dat-vo-cuc-phan-2', 'Liên Minh Công Lý: Khủng Hoảng Trái Đất Vô Cực (Phần 2)', 'Justice League: Crisis on Infinite Earths (Part 2)', 'https://phimimg.com/upload/vod/20240728-1/83b9d30844313d4a02f65910c0a983db.jpg', 'https://phimimg.com/upload/vod/20240728-1/5bb9703477e39cdf56ef61912ba1ea01.jpg', '<p>Một đội quân quỷ bóng tối vô tận đang có ý định tiêu diệt tất cả các bầy đàn thực tế trên thế giới của chúng ta và tất cả các Trái đất song song! Điều duy nhất chống lại họ là đội siêu nhân hùng mạnh nhất từng được tập hợp. Nhưng ngay cả sức mạnh tổng hợp của Superman, Batman, Wonder Woman, Green Lantern và tất cả các siêu anh hùng đồng nghiệp của họ cũng không thể làm chậm được sự tấn công dữ dội của đám đông bất khả chiến bại này. Thế lực bí ẩn nào đang điều khiển họ? Và làm thế nào mà những bí mật bị chôn vùi từ lâu của Monitor và Supergirl có nguy cơ phá hủy hàng phòng thủ cuối cùng của chúng ta?</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jensen Ackles","avatar":""},{"name":"Darren Criss","avatar":""},{"name":"Meg Donnelly","avatar":""},{"name":"Stana Katic","avatar":""},{"name":"Jonathan Adams","avatar":""},{"name":"Gideon Adlon","avatar":""},{"name":"Geoffrey Arend","avatar":""},{"name":"Troy Baker","avatar":""},{"name":"Zach Callison","avatar":""},{"name":"Darin De Paul","avatar":""},{"name":"Ato Essandoh","avatar":""},{"name":"Keith Ferguson","avatar":""},{"name":"Will Friedle","avatar":""},{"name":"Jennifer Hale","avatar":""},{"name":"Aldis Hodge","avatar":""},{"name":"Jamie Gray Hyder","avatar":""},{"name":"Erika Ishii","avatar":""},{"name":"David Ka","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324230);
