INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lien-minh-cong-ly-khung-hoang-trai-dat-vo-cuc-phan-2', 'Liên Minh Công Lý: Khủng Hoảng Trái Đất Vô Cực (Phần 2)', 'Justice League: Crisis on Infinite Earths (Part 2)', 'liên minh công lý: khủng hoảng trái đất vô cực (phần 2) justice league: crisis on infinite earths (part 2) jensen ackles darren criss meg donnelly stana katic jonathan adams gideon adlon geoffrey arend troy baker zach callison darin de paul ato essandoh keith ferguson will friedle jennifer hale aldis hodge jamie gray hyder erika ishii david ka ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-khung-hoang-trai-dat-vo-cuc-phan-1', 'Liên Minh Công Lý: Khủng Hoảng Trái Đất Vô Cực (Phần 1)', 'Justice League: Crisis on Infinite Earths (Part 1)', 'https://phimimg.com/upload/vod/20240728-1/0e49894e1265d1e30cfb16675860cf60.jpg', 'https://phimimg.com/upload/vod/20240728-1/f1786ea6f0596068577165afa61f9071.jpg', '<p>Cái chết đang đến gần. Tệ hơn cả cái chết: sự lãng quên. Không chỉ đối với Trái đất của chúng ta, mà còn đối với tất cả mọi người, ở mọi nơi, trong mọi vũ trụ! Để chống lại sự hủy diệt cuối cùng này, Người giám sát bí ẩn đã tập hợp đội Siêu anh hùng vĩ đại nhất từng được tập hợp. Nhưng sức mạnh tổng hợp của Siêu nhân có thể là gì, Wonder Woman, Batman, The Flash, Green Lantern và hàng trăm Siêu anh hùng từ nhiều Trái đất thậm chí còn nỗ lực cứu toàn bộ thực tại khỏi một trận chiến phản vật chất không thể ngăn cản?!</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Matt Bomer","avatar":""},{"name":"Jensen Ackles","avatar":""},{"name":"Darren Criss","avatar":""},{"name":"Meg Donnelly","avatar":""},{"name":"Stana Katic","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Zachary Quinto","avatar":""},{"name":"Jonathan Adams","avatar":""},{"name":"Ike Amadi","avatar":""},{"name":"Geoffrey Arend","avatar":""},{"name":"Zach Callison","avatar":""},{"name":"Alexandra Daddario","avatar":""},{"name":"Alastair Duncan","avatar":""},{"name":"Ato Essandoh","avatar":""},{"name":"Cynthia Hamidi","avatar":""},{"name":"Aldis Hodge","avatar":""},{"name":"Erika Ishii","avatar":""},{"name":"David","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f008490