INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-toc-gaa', 'Gia Tộc Ga''a', 'House Of Ga''a', 'https://phimimg.com/upload/vod/20240727-1/22c770a9e22abe6a1c7189f984090b03.jpg', 'https://phimimg.com/upload/vod/20240727-1/5d0d2dc28b87297435cb390fd37bcdab.jpg', '<p>Femi Branch đóng chính cùng dàn diễn viên toàn sao, trong đó có Mike Afolarin, Toyin Abraham và Funke Akindele, trong bộ phim lịch sử hoành tráng về Bashorun Ga&#39;a này.</p>', 'Full', 1, 'single', 'completed', 30, 2024, 'Vietsub', 'FHD', 'Châu Phi', 0, '[{"name":"Femi Branch","avatar":""},{"name":"Mike Afolarin","avatar":""},{"name":"Funke Akindele","avatar":""},{"name":"Femi Adebayo","avatar":""},{"name":"Ibrahim Chatta","avatar":""},{"name":"Toyin Abraham","avatar":""},{"name":"Bimbo Manuel","avatar":""},{"name":"Lateef Adedimeji","avatar":""},{"name":"Adeniyi Johnson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324230);
