INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xu-so-than-tien', 'Xứ Sở Thần Tiên', 'Wonderland', 'https://phimimg.com/upload/vod/20240726-1/4e6cdc01ef938bb0fdf17e38c6dd598a.jpg', 'https://phimimg.com/upload/vod/20240726-1/a9eb559cfe406d04173fb39217eb0f80.jpg', '<p>Xứ sở thần tiên - Wonderland lấy bối cảnh một thế giới giả tưởng, nơi con người có thể gặp gỡ và đoàn tụ với những người thân yêu đã khuất thông qua công nghệ trí tuệ nhân tạo. Bộ phim xoay quanh câu chuyện của những nhân vật khác nhau, mỗi người đều có những lý do riêng để tìm đến Wonderland.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"湯唯","avatar":""},{"name":"배수지","avatar":""},{"name":"박보검","avatar":""},{"name":"정유미","avatar":""},{"name":"최우식","avatar":""},{"name":"공유","avatar":""},{"name":"탕준상","avatar":""},{"name":"성병숙","avatar":""},{"name":"최무성","avatar":""},{"name":"Lee Eol","avatar":""},{"name":"강애심","avatar":""},{"name":"김성령","avatar":""},{"name":"박희본","avatar":""},{"name":"아누팜 트리파티","avatar":""},{"name":"달시 파켓","avatar":""},{"name":"Jang Yoon-jung","avatar":""},{"name":"Song Duk-ho","avatar":""},{"name":"Jang Sung-yoon","avatar":""},{"name":"鮑起靜","avatar":""},{"name":"Park Yeon-woo","avatar":""},{"name":"Min Ji-a","avatar":""},{"name":"강진아","avatar":""},{"name":"김그림","avatar":""},{"name":"박미현","avatar":""},{"name":"조희봉","avatar":""},{"name":"Jeon Soo-ji","avatar":""},{"name":"Jeon Woon-jong","avatar":""},{"name":"Jeong Seong-in","avatar":""},{"name":"Son Kyoung-won","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 17846