INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rua-toi-cho-quy', 'Rửa Tội Cho Quỷ', 'The Devil''s Bath', 'https://phimimg.com/upload/vod/20240726-1/ac3fbedadf315b2b3e59d4c5c84b3263.jpg', 'https://phimimg.com/upload/vod/20240726-1/b0520faf7019db122601becff806230a.jpg', '<p>Áo thế kỷ 18. Những ngôi làng được bao quanh bởi rừng sâu. Một người phụ nữ bị kết án tử hình sau khi giết chết một đứa trẻ. Agnes sắp kết hôn với người mình yêu và thẳng thắn chuẩn bị cho cuộc sống vợ chồng. Ngay sau đó, đầu và tim cô bắt đầu cảm thấy nặng nề. Ngày qua ngày, cô ngày càng bị mắc kẹt trong con đường âm u và cô đơn dẫn đến những ý nghĩ xấu xa. Có lẽ không chỉ là suy nghĩ…</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Áo', 0, '[{"name":"Anja Plaschg","avatar":""},{"name":"Maria Hofstätter","avatar":""},{"name":"David Scheid","avatar":""},{"name":"Natalya Baranova","avatar":""},{"name":"Lukas Walcher","avatar":""},{"name":"Agnes Lampl","avatar":""},{"name":"Camilla Schilien","avatar":""},{"name":"Lorenz Tröbinger","avatar":""},{"name":"Reinhold Felsinger","avatar":""},{"name":"Elias Schützenhofer","avatar":""},{"name":"Elmar Kurz","avatar":""},{"name":"Tim Valerian Alberti","avatar":""},{"name":"Elisabeth Gobbers","avatar":""},{"name":"Annemarie Schwarzenberger","avatar":""},{"name":"Franzi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324230);
