INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-hoang-tham-do', 'Ông hoàng thảm đỏ', 'The Movie Emperor', 'https://phimimg.com/upload/vod/20240726-1/9791b96dc24795fc122641a270d3bd61.jpg', 'https://phimimg.com/upload/vod/20240726-1/03b160c2de0fb820b99a1388bf71b15f.jpg', '<p>Trong nỗ lực giành lại sự quan tâm của công chúng, cựu ngôi sao điện ảnh Hồng Kông Lau Wai-chi thực hiện một bộ phim trở lại với một đạo diễn lớn. Để chuẩn bị cho vai một nông dân vào những năm 1960, anh đến vùng nông thôn Trung Quốc đại lục để trải nghiệm cuộc sống nông thôn ở đó, nhưng sự kiêu ngạo của anh đã gây ra một loạt trò hề.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Pal Sinn Lap-man","avatar":""},{"name":"瑞瑪·席丹","avatar":""},{"name":"Daniel Yu","avatar":""},{"name":"甯浩","avatar":""},{"name":"林熙蕾","avatar":""},{"name":"梁家輝","avatar":""},{"name":"楊千嬅","avatar":""},{"name":"Wong Jing","avatar":""},{"name":"張子賢","avatar":""},{"name":"Eliz Lao","avatar":""},{"name":"Zhou Wei","avatar":""},{"name":"Sunny Sun","avatar":""},{"name":"Xue Baohe","avatar":""},{"name":"Ma Dong","avatar":""},{"name":"Ruoqing Liu","avatar":""},{"name":"Xiao Wei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
