INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-map-khong-gian', 'Cá Mập Không Gian', 'Space Sharks', 'https://phimimg.com/upload/vod/20240726-1/5e1d62e2641e9382c8149a0273e6d03f.jpg', 'https://phimimg.com/upload/vod/20240726-1/47def9a103a020045d751c083c167271.jpg', '<p>Một thí nghiệm quân sự được thực hiện trên trạm vũ trụ đã gặp sai lầm khủng khiếp, gửi một giống cá mập mới được trang bị vũ khí đến trái đất chỉ với một nhiệm vụ: tiêu diệt mọi thứ trên đường đi của chúng.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eric Roberts","avatar":""},{"name":"Brinke Stevens","avatar":""},{"name":"Scott Swartz","avatar":""},{"name":"Peter Stickles","avatar":""},{"name":"Mel Novak","avatar":""},{"name":"Traci Burr","avatar":""},{"name":"Carl Crew","avatar":""},{"name":"Janet Lopez","avatar":""},{"name":"Allie Perez","avatar":""},{"name":"Jarad Allen","avatar":""},{"name":"Ben Anderson","avatar":""},{"name":"Chris Mills","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324230);
