INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ca-map-khong-gian', 'Cá Mập Không Gian', 'Space Sharks', 'cá mập không gian space sharks eric roberts brinke stevens scott swartz peter stickles mel novak traci burr carl crew janet lopez allie perez jarad allen ben anderson chris mills ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-phan-hac', 'Anh Hùng Phản Hắc', 'No Room for Crime', 'https://phimimg.com/upload/vod/20240714-1/92dc8a67a51ab3708df5a66c90a4dbb5.jpg', 'https://phimimg.com/upload/vod/20240714-1/748752557306e462e2a8356f2c6e5b8e.jpg', '<p>Tiếng chuông cảnh sát báo động, các cảnh sát Quan Chí Hiên, Từ Hiền, anh Thụ và anh Xán đuổi bắt tên cướp, nhưng tên phỉ máu lạnh đã cướp được súng, anh Thụ bị bắn chết ngay tại chỗ! Phát súng máu lạnh của tên phỉ liều mạng đã viết lại số phận của 4 anh cảnh sát… Anh Thụ tuẫn chức, Hiên một lần nữa gia nhập bộ đội cơ động, anh Xán được điều động đến phòng điều tra các vụ linh tinh, Hiền rút khỏi đội cảnh sát, trà trộn vào hắc bang lớn nhất của Tây Cửu Long, và một thời gian sau trở thành trùm đại ca “Tiểu Hiền Ca” Tây Cửu Vương vô lương, sống cuộc sống phi nhân loại bằng đao kiếm, giết chóc; thế nhưng anh ta là cảnh sát nằm vùng trong xã hội đen. Sau cái chết của tên Lương, trùm ma túy lớn hoành hành bá đạo, trong lúc “ngai vàng” đang để trống, quần hùng bắt đầu tranh giành, thế là trận máu mưa gió tanh xảy ra, vô số thương vong. Ông Đới giám đốc cảnh sát yêu cầu Hiền tiếp tục nằm vùng, và thừa cơ hội tiếp quản cả thế lực xã đoàn của tên Lương. Nhưng nào ngờ thân phận cảnh sát nằm vùng của Hiền bị bại lộ, đối đầu của xã hội đen truy sát anh ta, suýt bị thiệt mạng. Lúc này Từ Hiền lâm vào điểm giao thoa của cuộc đời: Làm trùm xã hôi đen Tây Cửu Vương hằng năm giao dịch ma túy với giá trị mấy chục tỷ, hay làm lại một cảnh sát, một anh hùng chống xã hội đen mỗi tháng ăn lương hơn ba mươi ngàn Đô-la Hồng Kong?</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2024, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Joel Chan","avatar":""},{"name":"Owen Cheung","avatar":""},{"name":"袁偉豪","avatar":""},{"name":"Elaine Yiu","avatar":""},{"name":"Rebecca Zhu","avatar":""},{"name":"Jonathan Cheung Wing-Hong","avatar":""},{"name":"Kelly Fu","avatar":""},{"name":"Hugo Wong","avatar":""},{"name":"Mat Yeung","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324230);
