INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suy-doan-vo-toi', 'Suy Đoán Vô Tội', 'Presumed Innocent', 'https://phimimg.com/upload/vod/20240625-1/448d1fd844adae10af2e96ecfacb1abc.jpg', 'https://phimimg.com/upload/vod/20240625-1/2d0ae6c193a57489f75320d524c108ba.jpg', '<p>Một vụ án mạng kinh hoàng làm rúng động Phòng Công tố Chicago khi một nhân viên bị tình nghi là thủ phạm, khiến cho bị cáo phải đấu tranh để níu giữ gia đình mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Ruth Negga","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"O-T Fagbenle","avatar":""},{"name":"Chase Infiniti","avatar":""},{"name":"Elizabeth Marvel","avatar":""},{"name":"Nana Mensah","avatar":""},{"name":"Renate Reinsve","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Kingston Rumi Southwick","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324230);
