INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-khung-hoang-tren-trai-dat-vo-tan-phan-ba', 'Liên Minh Công Lý: Khủng Hoảng Trên Trái Đất Vô Tận Phần Ba', 'Justice League: Crisis on Infinite Earths Part Three', 'https://phimimg.com/upload/vod/20240726-1/cd74cccda9e668c195a73189e98f5a84.jpg', 'https://phimimg.com/upload/vod/20240726-1/920b8e804ad0ed9c49849574a895bb9c.jpg', '<p>Hiện đã được tiết lộ đầy đủ là mối đe dọa cuối cùng đối với sự tồn tại, Anti-Monitor tiến hành một cuộc tấn công không ngừng vào những Trái đất còn sống sót đang đấu tranh sinh tồn trong một vũ trụ bỏ túi. Từng người một, những thế giới này và tất cả cư dân của chúng đều bị bốc hơi! Trên các hành tinh còn sót lại, ngay cả thời gian cũng bị tan vỡ, và các anh hùng từ quá khứ gia nhập Justice League và các đồng minh của họ để chống lại hình ảnh thu nhỏ của cái ác. Nhưng khi họ đứng vững cuối cùng, liệu sự hy sinh của các siêu anh hùng có đủ để cứu tất cả chúng ta?</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jensen Ackles","avatar":""},{"name":"Darren Criss","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Gideon Adlon","avatar":""},{"name":"Ike Amadi","avatar":""},{"name":"Geoffrey Arend","avatar":""},{"name":"Troy Baker","avatar":""},{"name":"Brian Bloom","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Ashly Burch","avatar":""},{"name":"Zach Callison","avatar":""},{"name":"Kevin Conroy","avatar":""},{"name":"Alexandra Daddario","avatar":""},{"name":"Brett Dalton","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Meg Donnelly","avatar":""},{"name":"Ato Essandoh","avatar":""},{"name":"Keith Ferguson","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"n