INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lien-minh-cong-ly-khung-hoang-tren-trai-dat-vo-tan-phan-ba', 'Liên Minh Công Lý: Khủng Hoảng Trên Trái Đất Vô Tận Phần Ba', 'Justice League: Crisis on Infinite Earths Part Three', 'liên minh công lý: khủng hoảng trên trái đất vô tận phần ba justice league: crisis on infinite earths part three jensen ackles darren criss corey stoll gideon adlon ike amadi geoffrey arend troy baker brian bloom matt bomer ashly burch zach callison kevin conroy alexandra daddario brett dalton john dimaggio meg donnelly ato essandoh keith ferguson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-kho-bau-nhan-gian', 'Truyền Thuyết Kho Báu Nhân Gian', 'Treasure Hunter', 'https://phimimg.com/upload/vod/20240726-1/6aa38694cc5b26a76f579a778028682f.jpg', 'https://phimimg.com/upload/vod/20240726-1/a0142a76291791878953a5103b8c15db.jpg', '<p>Những năm đầu thời Dân Quốc, giữa rừng núi yên tĩnh ở Đông Bắc có một ngôi làng tên Tam Đạo Lĩnh Tử. Ngày nọ, Khổng Chiêu Tô, một người làm nghề &quot;biệt bảo&quot; không thuộc tám ngành nghề trong giang hồ, vô tình bước vào nơi này và phát hiện ra rằng ngôi làng tưởng chừng yên bình này lại đầy rẫy những điều kỳ quái. Những sự kiện kỳ lạ như &quot;kiệu giấy cướp hôn, mỹ nhân hương quan tài, cát vàng địa ngục&quot; liên tiếp xảy ra. Điều bất ngờ hơn cả là ngôi làng nhỏ này lại ẩn chứa một bí mật kinh hoàng...</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"贾征宇","avatar":""},{"name":"方楚彤","avatar":""},{"name":"Zhang Xingyao","avatar":""},{"name":"Gao Linyu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324230);
