INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-thuyet-kho-bau-nhan-gian', 'Truyền Thuyết Kho Báu Nhân Gian', 'Treasure Hunter', 'truyền thuyết kho báu nhân gian treasure hunter 贾征宇 方楚彤 zhang xingyao gao linyu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-nhan-ngu', 'Thực Nhân Ngư', 'Sharp Teeth', 'https://phimimg.com/upload/vod/20240726-1/a1f6979754cde9cbc27e5e1300e19bb7.jpg', 'https://phimimg.com/upload/vod/20240726-1/1e86b7bace04b095527ba1c7b1f96132.jpg', '<p>Trương Thạc mời chiến hữu và bạn gái Lưu Mạnh Tưởng cùng bạn thân của cô ấy tham gia chuyến du lịch ngày nghỉ. Ban đầu, anh định nhân cơ hội này để thực hiện kế hoạch cầu hôn đã ấp ủ từ lâu, nhưng mọi thứ bị phá hỏng bất ngờ. Trong một lần tình cờ, họ đã đặt chân vào khách sạn đảo mộng mơ xa hoa nhất ở địa phương. Mọi người khó giấu niềm vui, mong đợi chuyến đi tiếp theo sẽ càng thú vị hơn. Tuy nhiên, phía sau vẻ ngoài xa hoa của khách sạn lại ẩn chứa một bí mật kinh hoàng. Chủ khách sạn là ông Ngưu đã dùng thủ đoạn bất hợp pháp để có được một con cá biển sâu kỳ lạ từ thị trường. Con cá này đẻ ra những con non có hương vị tươi ngon độc đáo, khiến ông nảy sinh dã tâm tham lam. Cá biển sâu này kỳ lạ và cực kỳ hung dữ, do lỗi của công nhân, hàng loạt con cá non đã tràn vào khu vực sinh sống của con người qua các đường ống, gây ra thảm họa liên hoàn. Cuối cùng, sau khi trả giá nặng nề, bằng ý chí kiên định và sự mạnh mẽ, họ đã tiêu diệt toàn bộ cá biển sâu và những con non. Dù trải qua biến cố này đã củng cố tình cảm giữa Trương Thạc và Lưu Mạnh Tưởng, nhưng cũng đã cảnh tỉnh mọi người phải tôn trọng tự nhiên và quý trọng sinh mạng.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"黄涛","avatar":""},{"name":"Li Jingmu","avatar":""},{"name":"Zhao Xintong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324230);
