INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-sieu-lay-2', 'Điệp Viên Siêu Lầy 2', 'My Spy The Eternal City', 'https://phimimg.com/upload/vod/20240726-1/beea12bb16525945635c60f31414eda8.jpg', 'https://phimimg.com/upload/vod/20240726-1/33b17b68dcb935eeccd7490b094828dc.jpg', '<p>Khi dàn hợp xướng trường trung học của Sophie được chọn tham gia chuyến lưu diễn ở Ý mà đỉnh cao là buổi biểu diễn cho Giáo hoàng tại Thành phố Vatican, JJ coi đây là cơ hội để gắn kết với cô con gái riêng mới của mình, vì vậy anh tình nguyện giúp đỡ người giám sát nhóm vượt qua các kênh đào Venice, băng qua những cây cầu nổi tiếng của Florence và vào các di tích lịch sử nhất của Rome. Tuy nhiên anh sớm phát hiện ra rằng bản thân và Sophie đã vô tình trở thành những con tốt trong một âm mưu khủng bố có thể kết thúc thế giới.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dave Bautista","avatar":""},{"name":"Chloe Coleman","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"Flula Borg","avatar":""},{"name":"Taeho K","avatar":""},{"name":"Billy Barratt","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Tamer Burjaq","avatar":""},{"name":"Paul du Toit","avatar":""},{"name":"Kyra Janse van Rensburg","avatar":""},{"name":"Peter Butler","avatar":""},{"name":"Arin Gonçalves","avatar":""},{"name":"Nicola Correia Damude","avatar":""},{"name":"Noah Dalton Danby","avatar":""},{"name":"Devere Ro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324230);
