INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vien-sieu-lay-2', 'Điệp Viên Siêu Lầy 2', 'My Spy The Eternal City', 'điệp viên siêu lầy 2 my spy the eternal city dave bautista chloe coleman kristen schaal ken jeong anna faris flula borg taeho k billy barratt craig robinson tamer burjaq paul du toit kyra janse van rensburg peter butler arin gonçalves nicola correia damude noah dalton danby devere ro ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-dinh-dai', 'Tiểu Đình Đài', 'Rise From the Ashes', 'https://phimimg.com/upload/vod/20240718-1/030f0988a5bbdbc9e757b3218af8b8e7.jpg', 'https://phimimg.com/upload/vod/20240718-1/65edc332d5e011ad864ad2dfa849c0f0.jpg', '<p>Thiếu nữ Trình Tịch Niên bất ngờ sống lại, sau khi biết được chân tướng kiếp trước mình bị lợi dụng đến chết, cô đã bắt tay với Tô Cảnh Nguyên- người đang ẩn mình ở nhà họ Trình để trả thù cho gia tộc. Hai người phối hợp ăn ý nhưng cũng có vài lần giao tranh, cuối cùng họ nắm tay nhau bước về phía trước trong hận thù và tình cảm đan xen phức tạp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"姜之南","avatar":""},{"name":"Zonglin Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324230);
