INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tren-co-gia-duoi-co-tre', 'Trên Có Già Dưới Có Trẻ', 'Family', 'https://phimimg.com/upload/vod/20240714-1/d039ab7c34b67a994d3651b12098f4f4.jpg', 'https://phimimg.com/upload/vod/20240714-1/6640176e77dcc7957d94636cd4a7c0f6.jpg', '<p>Gu Xiaomeng, một giáo viên trung học xuất sắc đã làm việc chăm chỉ trong nhiều năm và chồng cô, Lu Xiang, một nhà thiết kế, cuối cùng đã mua được ngôi nhà nhỏ của riêng mình, nhưng họ cũng chào đón cha mẹ của Lu Xiang, những người thực sự đang đến Bắc Kinh để chữa bệnh. Cùng lúc đó, mẹ của Gu Xiaomeng là Liu Meiqin và em trai Gu Xiaosong, những người thường xuyên gặp rắc rối, cũng đến từ Tô Châu. Gu Xiaosong nhiều lần bị người đại diện lừa để ra nước ngoài nên đã bán căn nhà ở quê nhà và để lại Liu Meiqin cho Gu Xiaomeng. Ba ông già một kịch, khi gia đình gặp nhiều khó khăn, Cố Hiểu Mộng biết tin mình có thai, hai vợ chồng bắt đầu cuộc sống quanh co với hai anh em lớn tuổi. Dù gặp đủ mọi khó khăn trong cuộc sống và sự nghiệp nhưng quyết tâm bảo vệ tình yêu và gia đình đã tiếp thêm sức mạnh cho họ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"楊玏","avatar":""},{"name":"Deng Jiajia","avatar":""},{"name":"許娣","avatar":""},{"name":"Wu Yufang","avatar":""},{"name":"曲国强","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
