INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sinh-than-bo-tuong-dau-ma-thuong', 'Song Sinh Thần Bổ Tường Đầu Mã Thượng', 'Detective Duo Maiden and Horseman', 'https://phimimg.com/upload/vod/20240719-1/8f40a710b5fd4899dec50f6d068ea86d.jpg', 'https://phimimg.com/upload/vod/20240719-1/fe3be22435f7872ece132341b51fbdd2.jpg', '<p>Liang Zijie, một họa sĩ nổi tiếng ở thành phố Trường An, đột ngột qua đời, người phụ nữ trong bức tranh nổi tiếng của ông sống lại một cách kỳ lạ, gây ra hàng loạt câu chuyện kỳ quái. Dưới sự điều tra của thám tử Cai Sanlang và Luo Youhuo của Trường An, một câu chuyện cũ đã bị phong ấn suốt 15 năm đã được tiết lộ. Tuy nhiên, khi cuộc điều tra đi sâu hơn, cái chết của Liang Zijie cuối cùng trở nên phức tạp và khó hiểu hơn. nỗ lực của cặp thám tử song sinh, danh tính thực sự của người phụ nữ trong tranh đã được hé lộ, nhiều kẻ có ý đồ xấu xa lộ diện, họ đã thú nhận tội ác của mình và cặp thám tử song sinh lại giải quyết được những vụ án kỳ lạ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Song Muzi","avatar":""},{"name":"Zhang Menglu","avatar":""},{"name":"金沫汐","avatar":""},{"name":"李柏言","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324230);
