INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pop-ban-vu-lua-dao-nhom-nhac-nam', 'Pop bẩn: Vụ lừa đảo nhóm nhạc nam', 'Dirty Pop: The Boy Band Scam', 'https://phimimg.com/upload/vod/20240725-1/35c4447a3a01877b2c7835fe861bbee4.jpg', 'https://phimimg.com/upload/vod/20240725-1/1128d31684c39cbf86a4d08e9ef078de.jpg', '<p>Backstreet Boys. NSYNC. Lou Pearlman lập ra những nhóm nhạc nam đình đám nhất thập niên 90 và một trong những mô hình Ponzi lớn nhất lịch sử trong loạt phim tài liệu hấp dẫn này.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 6, 2024, 'Vietsub', 'FullHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324230);
