INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-mua-mang-em-den', 'Ngày Mưa Mang Em Đến', 'Kissed By The Rain', 'https://phimimg.com/upload/vod/20240724-1/00ff6a2ac6774711fc8b56123e7f626c.jpg', 'https://phimimg.com/upload/vod/20240724-1/5f32f409c067c69b519128ba22887726.jpg', '<p>Plaifon works as a social worker for children and women. She meets a boy named Mawin. Mawin and his mother are on the run from an abusive father and hope to find shelter at the foundation where Plaifon works. When his mother suddenly dies, Mawins world comes apart at the seams, and Plaifon is the only support in his life. Plaifon knows that love can give and take everything from a person, leaving a long trail of regret. She decides to leave Mawin to avoid the unwanted mistake. Will their paths cross again? Can they ever let go of their past?</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 7, 2024, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"มาริโอ้ เมาเร่อ","avatar":""},{"name":"Natapohn Tameeruks","avatar":""},{"name":"Thatchathon Sabanun","avatar":""},{"name":"Sirilak Kwong","avatar":""},{"name":"Gap Jakkarin Phooriphad","avatar":""},{"name":"Maneerat Kam-Uan","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Supoj Janjareonborn","avatar":""},{"name":"Apinun Prasertwattanakul","avatar":""},{"name":"Khwanruedi Klomklom","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
