INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ga-trai-hu-choi-hay-bi-xoi', 'Những Gã Trai Hư: Chơi Hay Bị Xơi', 'Bad Boys: Ride or Die', 'https://phimimg.com/upload/vod/20240724-1/ba5ff01dd3ec9a213784f1072330aa1e.jpg', 'https://phimimg.com/upload/vod/20240724-1/15e23457c5ad9d088e6d8f062c995535.jpg', '<ul class="collateral-tabs list-paddingleft-2" style="box-sizing: border-box; margin: 0px; padding: 0px; width: 980px;"><li><p>Mùa hè này, bom tấn hài hành động Bad Boys đã quay trở lại nhưng lần này có một sự thay đổi lớn: dân chơi Miami hiện đang bị truy nã. Cảnh sát trưởng mà họ kính trọng bị nghi ngờ đã tham gia vào đường dây tham nhũng điều này khiến Mike và Marcus không thể ngồi yên. Từ đây, hàng loạt bất ngờ xảy ra đẩy Mike và Marcus trở thành kẻ bị tình nghi số 01 mà không có cách nào minh oan.</p></li></ul><ul style="list-style-type: none;" class=" list-paddingleft-2"><li><p><br/></p></li></ul>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FullHD', 'Âu Mỹ', 1, '[{"name":"Will Smith","avatar":""},{"name":"Martin Lawrence","avatar":""},{"name":"Vanessa Hudgens","avatar":""},{"name":"Alexander Ludwig","avatar":""},{"name":"Paola Nuñez","avatar":""},{"name":"Eric Dane","avatar":""},{"name":"Ioan Gruffudd","avatar":""},{"name":"Jacob Scipio","avatar":""},{"name":"Melanie Liburd","avatar":""},{"name":"Tasha Smith","avatar":""},{"name":"Rhea Seehorn","avatar":""},{"name":"Tiffany Haddish","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"DJ Khaled","avatar":""},{"name":"John Salley","avatar":""},{"name":"Bianca Bethune","avatar":""},{"name":"Dennis McDonald","avatar":""},{"name":"Quinn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324230);
