INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuong-tu-nha-ta-khong-de-choc', 'Nương Tử Nhà Ta Không Dễ Chọc', 'My Sassy Wife', 'https://phimimg.com/upload/vod/20240622-1/a73f1cb3e8a7304d934fadbe71d44169.jpg', 'https://phimimg.com/upload/vod/20240622-1/6b51e600b9dd56f3c71c36b640043a52.jpg', '<p>Lu Nanyi, con gái của một doanh nhân giàu có ở thủ đô và Lin Qingqiu, con trai quý tộc của một gia đình giàu có, đã yêu nhau từ khi còn nhỏ, và tình yêu của họ dần dần phát triển. Mười năm sau, cha mẹ cô ra lệnh cho Lin Qingqiu đính hôn với người khác. Lin Qingqiu đã yêu Lu Nanyi, và cả hai đồng ý bỏ trốn vào ngày cưới. Không ngờ họ lại bị cản trở bởi một người muốn làm điều đó. Mỗi người đều nhận được một lá thư chia tay, hiểu lầm rằng người kia không tốt bụng và bất công, và giờ họ đã xa nhau. Một năm sau, Lin Qingqiu theo đuổi vợ và trở thành huyện trưởng Cẩm Châu, còn Lu Nanyi trở thành một nhà văn viết truyện nổi tiếng. Một vụ án mạng xảy ra ở Cẩm Châu, cái chết của người quá cố giống hệt như những gì được viết trong sách của Lu Nanyi, do đó Lu Nanyi có liên quan đến vụ giết người. Chức vụ chính thức mới của Lin Qingqiu là điều đầu tiên khiến anh trở thành kẻ tình nghi. Người yêu cũ của anh trở thành kẻ tình nghi khi gặp nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
