INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-cong-luoc', 'Mỹ Nhân Công Lược', 'Beauty Strategy', 'https://phimimg.com/upload/vod/20240618-1/3f8110b4d7b44e427ff1320f32859cdf.jpg', 'https://phimimg.com/upload/vod/20240618-1/3e92a90bdd777363f9b4ccf7784f5995.jpg', '<p>Đại lục Hyun-kun từng được cai trị bởi năm gia tộc. Sáu năm trước, có một cuộc chiến tranh giữa năm gia tộc và tộc người đã đánh bại bốn gia tộc khác để thiết lập sự thống trị của họ. Trong chiến tranh, công chúa Masano của tộc Reishi đã trốn thoát thành công mà không có nơi nào để tìm. Sáu năm sau, cô bước vào cung điện của loài người giả dạng Ling Zhi để tìm ra sự thật về sự tuyệt chủng của gia tộc mình và giải cứu những người bị giam cầm bởi loài người. Ở trong cung nguy cơ tứ phía, Lăng Chí biểu hiện cẩn thận từng li từng tí, tùy cơ ứng biến, rốt cục tiếp cận quân nhân gian Mục Huyền Tước. Theo hai người thăm dò lẫn nhau, dần dần sinh ra tình cảm. Lăng Chí cuối cùng phát hiện ra chân tướng. Cuối cùng, nàng và Mục Huyền Giác hợp lực đánh bại ác nhân, đạt được mục đích chung sống hòa thuận của Ngũ tộc.&nbsp;</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guan Chang","avatar":""},{"name":"Zhang JingYun","avatar":""},{"name":"Zhu Jintong","avatar":""},{"name":"Yuan Ziming","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
