INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('we-are-series-chinh-la-ta-yeu-nhau', 'We Are Series: Chính Là Ta Yêu Nhau', 'We Are', 'https://phimimg.com/upload/vod/20240411-1/8fbc6a7484ad13a9531e35ac50bd9c5f.jpg', 'https://phimimg.com/upload/vod/20240411-1/a3065778213735c5c840d8dc0b2b1a47.jpg', '<p>We Are Series: Chính Là Ta Yêu Nhau mang đến câu chuyện miêu tả cuộc sống đầy những biến động của những người bạn đại học. Dù có học tập chăm chỉ đến đâu, họ cũng phải trải qua những câu chuyện khiến họ đau đầu khi vướng vào những khoảnh khắc phức tạp và những vướng mắc lãng mạn không ngừng nghỉ! Chúng ta là…bạn bè, nhưng sau đó chúng ta lại là kẻ thù của nhau. Chúng ta có tình cảm với nhau, tán tỉnh nhau, và làm thế nào chúng ta có thể yêu nhau đây? Chúng ta hãy cùng nhau khám phá những mối quan hệ đặc biệt này nhé. Đừng bỏ lỡ !!! Phim sẽ phát sóng trên app iQIYI và iQ.com với phụ đề tiếng Việt</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Prin Suparat","avatar":""},{"name":"Urassaya Sperbund","avatar":""},{"name":"Kummun Klomkaew","avatar":""},{"name":"Pitchapa Phanthumchinda","avatar":""},{"name":"Willy McIntosh","avatar":""},{"name":"Phiravich Attachitsataporn","avatar":""},{"name":"Maneerat Kam-Uan","avatar":""},{"name":"Supachai Suwanon","avatar":""},{"name":"Franky Weerapat Ounsa-ard","avatar":""},{"name":"Namnung Suttidachanai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324230);
