INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-vo-hiep-kim-dung', 'Thế Giới Võ Hiệp: Kim Dung', 'The Legend of Heroes', 'https://phimimg.com/upload/vod/20240617-1/f0a59700b210cee0762317eb4636c8bc.jpg', 'https://phimimg.com/upload/vod/20240617-1/571de830542cc19351b3b509c1c0438a.jpg', '<p>Bộ phim được ra mắt đúng dịp kỷ niệm 100 năm ngày sinh của nhà văn nổi tiếng nhất Trung Quốc Kim Dung, gồm 5 phần phim khác nhau được ấy cảm hứng từ tác phẩm của cố nhà văn: Đông Tà Tây Độc, Nam Để Bắc Cái, Hoa Sơn Luận Kiếm, Cửu Âm Chân Kinh, Thiết huyết đan tâm.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"周一圍","avatar":""},{"name":"高偉光","avatar":""},{"name":"陳都靈","avatar":""},{"name":"Peter Ho","avatar":""},{"name":"哈妮克孜","avatar":""},{"name":"Ming Dao","avatar":""},{"name":"Meng Ziyi","avatar":""},{"name":"何与","avatar":""},{"name":"Ci Sha","avatar":""},{"name":"Bao Shangen","avatar":""},{"name":"Wang Hongyi","avatar":""},{"name":"Huang Yi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324230);
