INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-tri-menh', 'Cuộc Gọi Trí Mệnh', 'The Caller', 'https://phimimg.com/upload/vod/20240719-1/83c60399371bdbc8680a12d3b39db31a.jpg', 'https://phimimg.com/upload/vod/20240719-1/96cdc58d7deedc287fbc19922ea45c04.jpg', '<p>Để tránh bị chồng bạo hành, tại ngôi nhà mới Mộng Gia đã tình cờ nhận cuộc gọi từ Như Mai, người thuê nhà trước đây. Ban đầu, cả hai vì tò mò về cuộc gọi xuyên không gian và thời gian, lại thêm việc cả hai đều là nạn nhân của bạo hành gia đình, nên mối quan hệ dần trở nên thân thiết. Cho đến khi Như Mai giết chết người chồng bạo hành đối với mình. Như Mai còn cho rằng mình bị Mộng Gia bỏ rơi, sau nhiều lần níu kéo không thành, cô bắt đầu điên cuồng trả thù Mộng Gia…</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FullHD', 'Trung Quốc', 1, '[{"name":"柳岩","avatar":""},{"name":"Song Yang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324230);
