INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-goi-tri-menh', 'Cuộc Gọi Trí Mệnh', 'The Caller', 'cuộc gọi trí mệnh the caller 柳岩 song yang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-trung-quy-su-quan-tai-bi-an', 'Quan Trung Quỷ Sự Quan Tài Bí Ẩn', 'Lost In The Tomb', 'https://phimimg.com/upload/vod/20240719-1/b9099a1df2c18ca066ad32fbf4cb85a9.jpg', 'https://phimimg.com/upload/vod/20240719-1/d8ccd42701b2533cf9e2857de0d7bff5.jpg', '<p>Vầng hào quang của Lăng Hàn thực sự có liên quan đến chấn thương tâm lý lớn trong thời thơ ấu do sự mất tích bí ẩn của cha anh, Lăng Vi. Một doanh nhân lớn từ một tập đoàn sinh học, Tư Mã Phong, mời Lăng Hàn khám phá nền văn minh Hoa Hư, biến mất cách đây 4600 năm và sức mạnh thần bí &quot;vượt qua sinh tử&quot; trong truyền thuyết. Ngoài khoản thù lao khổng lồ, Tư Mã Phong còn trình bày hình ảnh được gửi về trước khi đội tiên phong bị tiêu diệt hoàn toàn - một manh mối mà Lăng Hàn không thể từ chối. Trải qua các thử thách sinh tử như vực sâu bí ẩn và sinh vật hình người dưới lòng đất, Lăng Hàn cuối cùng dẫn đội đến di tích cuối cùng của nền văn minh Hoa Hư, &quot;Thành phố ẩn trong sương mù.&quot; Bí mật về việc cha anh dấn thân khám phá nơi này và mục đích thực sự của Tư Mã Phong cũng được tiết lộ. &quot;Bí mật cuối cùng&quot; của nền văn minh Hoa Hư hiện ra trước mắt mọi người. Hành động của Tư Mã Phong đã đánh thức 3000 chiến binh Hoa Hư, những người đã trở thành &quot;chiến binh bất tử&quot; để bảo vệ dân tộc từ 4600 năm trước. Đối mặt với vi khuẩn cổ đại sắp lan ra mặt đất và kết cục không thể tránh khỏi, Lăng Hàn quyết định tiến tới giải pháp cuối cùng.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FullHD', 'Trung Quốc', 1, '[{"name":"Clara Lee","avatar":""},{"name":"张维伊","avatar":""},{"name":"Ken Lok Tat-Wah","avatar":""},{"name":"Pu Tao","avatar":""},{"name":"蓝骁","avatar":""},{"name":"Wang Baoguang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324230);
