INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-da-me-tinh', 'Quỷ Dạ Mê Tình', 'The Night Of The Peak', 'https://phimimg.com/upload/vod/20240719-1/661840d06b476147e54d6fb11913358f.jpg', 'https://phimimg.com/upload/vod/20240719-1/d5b9c4bc3e19bbfa55510cee7cd9465e.jpg', '<p>Sau khi bạn trai của nhà văn mạng mới nổi Sophie bất hạnh bị sát hại, cô một mình đến một nơi rất vắng vẻ. Ở đây, cô không những không được hưởng một khoảnh khắc yên bình, mà ngược lại, rơi vào cái bẫy tinh vi của kẻ sát nhân. Cô phải vật lộn trong một mạng lưới mê tình kỳ lạ và quái đản. Kẻ đó từng bước thận trọng dẫn dụ cô tự nguyện tìm đến, sau một cuộc ân ái, một quá khứ bị chôn vùi kinh hoàng hiện ra. Đằng sau đó, lại là một câu chuyện bi thảm về một thiếu niên khiến lòng người tan nát.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FullHD', 'Trung Quốc', 1, '[{"name":"杨渌","avatar":""},{"name":"李牧谣","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324230);
