INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-hay-khong-mat', 'Mất Hay Không Mất', 'Almost Lost', 'https://phimimg.com/upload/vod/20240719-1/d2c0427f57228ff8cdb9eaf7326137b9.jpg', 'https://phimimg.com/upload/vod/20240719-1/9aec2d84edc5f042835ed4681d3f7874.jpg', '<p>Phim kể về những câu chuyện riêng biệt nhưng đan xen của bốn sinh viên quốc tế Trung Quốc, vật lộn và sống sót ở thành phố Toronto, vào một ngày hè nóng nực.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FullHD', 'Trung Quốc', 1, '[{"name":"Cecilia Guo","avatar":""},{"name":"Melody Shang","avatar":""},{"name":"Liny Li","avatar":""},{"name":"Ruo Feng","avatar":""},{"name":"Victoria Wang","avatar":""},{"name":"Jessie Yang","avatar":""},{"name":"Tanghua Xiao","avatar":""},{"name":"Liu Si Mu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324230);
