INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-ngam-tinh-anh-nguy-co-nano', 'Tay Ngắm Tinh Anh Nguy Cơ Nano', 'Sniper Elite Nano Crisis', 'https://phimimg.com/upload/vod/20240719-1/f9ac0518f881ed268e95a74a8573dec9.jpg', 'https://phimimg.com/upload/vod/20240719-1/34bc76f607d00ec51faad087917c0605.jpg', '<p>Bộ phim kể về phần tử khủng bố tại nước S chiếm giữ một lượng lớn robot nano y tế, được phát triển bởi các nhà khoa học hàng đầu thế giới từ nhiều quốc gia, có khả năng cứu sống vô số bệnh nhân. Bọn khủng bố dự định sử dụng công nghệ này để thực hiện kế hoạch lật đổ chính quyền. Thiện xạ Bạch Dạ dẫn dắt đội an ninh vượt qua nhiều hiểm nguy, đấu tranh với bọn khủng bố. Cuối cùng, họ trải qua sinh tử, trừng trị kẻ ác và giải quyết khủng hoảng quốc gia. Bạch Dạ và các thành viên đội an ninh Dạ Ảnh có kỹ thuật quân sự tinh thông, nhận thức cao, có lòng yêu nước mãnh liệt và trách nhiệm trong việc tiêu diệt tội phạm. Trong thời khắc nguy nan, họ đặt lợi ích quốc gia lên hàng đầu, với niềm tin sinh mạng người dân là trên hết, không sợ nguy hiểm, cứu vớt mạng sống của người dân, thể hiện tinh thần yêu nước và lòng yêu dân cao cả.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FullHD', 'Trung Quốc', 1, '[{"name":"高世名","avatar":""},{"name":"李恰","avatar":""},{"name":"艾科","avatar":""},{"name":"Deng Kaiyun","avatar":""},{"name":"Sun Wenxue","avatar":""},{"name":"田锋","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324230);
