INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thac-vi-canh-dan-xen', 'Thác Vị Cảnh Đan Xen', 'Interlaced Scenes', 'https://phimimg.com/upload/vod/20240719-1/863a67a9b631a5c945fe925aa15ff906.jpg', 'https://phimimg.com/upload/vod/20240719-1/8806c481196a0783213284ddbbf83d4b.jpg', '<p>Câu chuyện kể về cảnh sát hình sự Khương Quang Minh (do Mã Y Lý đóng) và Thạch Lạc (do Cao Chí Đình đóng) trong quá trình điều tra một vụ án, họ tình cờ phát hiện ra rằng hiện trường tội ác được tác giả Cố Kỷ Minh (do Đại Vĩ đóng) mô tả trong tiểu thuyết của mình kỳ lạ trùng khớp với hiện trường mà họ đang điều tra... Sự giao thoa giữa hư cấu và hiện thực, sự xuất hiện của tiểu thuyết đã mang lại hướng đi mới cho cuộc truy đuổi của hai người, nhưng cũng đã dẫn họ vào những bí ẩn sâu hơn... Vụ án trong vụ án, bí ẩn trong bí ẩn, kẻ thủ ác ẩn nấp sau màn đó là ai?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 5, 2024, 'Vietsub', 'FullHD', 'Trung Quốc', 0, '[{"name":"马伊琍","avatar":""},{"name":"佟大为","avatar":""},{"name":"高至霆","avatar":""},{"name":"蓝盈莹","avatar":""},{"name":"Christine Zheng","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"宋宁峰","avatar":""},{"name":"高曙光","avatar":""},{"name":"Wei Zixin","avatar":""},{"name":"Yang Kun","avatar":""},{"name":"Lu Hong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324230);
