INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thac-vi-canh-dan-xen', 'Thác Vị Cảnh Đan Xen', 'Interlaced Scenes', 'thác vị cảnh đan xen interlaced scenes 马伊琍 佟大为 高至霆 蓝盈莹 christine zheng wang jinsong 宋宁峰 高曙光 wei zixin yang kun lu hong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tuong-bien-mat', 'Đại Tượng Biến Mất', 'The Elephant is Right Here', 'https://phimimg.com/upload/vod/20240719-1/d7cb9a3365d3649ecea62180bce44ec8.jpg', 'https://phimimg.com/upload/vod/20240719-1/87869998c35be9279f38144d772e8ec9.jpg', '<p>Thị trấn lạc hậu Tượng Thành đang chuẩn bị chuyển mình, tổ chức &quot;sự kiện quốc tế&quot;: Marathon vạn người. Tin tức vừa lan truyền, các phe phái liền đổ xô đến xuất hiện quanh sự kiện này. Thanh niên địa phương Trương Khoáng một lòng muốn làm lớn mạnh, dự định giành quyền tổ chức Marathon để thăng tiến từ đó, nhưng không ngờ lại dính vào giao dịch tiền giả, con voi mượn từ đoàn xiếc cũng biến mất. Trương Khoáng để tiếp tục vinh quang phải đi vay tiền. Không ngờ chủ nợ là côn đồ địa phương Cẩu Ca. Hắn đã nhòm ngó miếng đất của đoàn xiếc từ lâu, muốn dùng mưu trí, nhưng trí thông minh không đủ, lại tự hại chính mình. Cùng lúc đó, Chí thúc và Hắc tỷ, những kẻ làm tiền giả từ lâu cũng có nỗi lo của riêng mình, tiền điện tử nổi lên, tiền giả đã trở thành ngành công nghiệp lạc hậu, họ muốn lợi dụng cuộc Marathon này để rửa sạch số tiền cuối cùng và thoát ra. Trương Khoáng mờ mịt trở thành kẻ chịu tội thay. Mục tiêu duy nhất của Trương Khoáng là hoàn thành &quot;chạy hết&quot; cuộc Marathon này!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FullHD', 'Trung Quốc', 0, '[{"name":"Li Jiuxiao","avatar":""},{"name":"蔣龍","avatar":""},{"name":"Ma Yinyin","avatar":""},{"name":"Zhiwen Wang","avatar":""},{"name":"Suxi Ren","avatar":""},{"name":"Duan Bowen","avatar":""},{"name":"余皑磊","avatar":""},{"name":"Xu Yukun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324230);
