INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-trom-gang-tay-xanh-luc-phan-2', 'Băng trộm Găng Tay Xanh Lục (Phần 2)', 'The Green Glove Gang (Season 2)', 'https://phimimg.com/upload/vod/20240718-1/de3be4f7bb746b37124eab972d158a43.jpg', 'https://phimimg.com/upload/vod/20240718-1/5067b924910d0df0e017bebaeed411a4.jpg', '<p><span style="color: rgb(88, 88, 88); font-family: Tahoma, ">Khi vụ trộm gần nhất đổ bể, ba nữ đạo chích lớn tuổi trốn tránh chính quyền bằng cách ẩn nấp trong viện dưỡng lão rồi khám phá ra một bí mật hiểm ác ở đó.</span></p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2024, 'Vietsub', 'FullHD', 'Ba Lan', 0, '[{"name":"Magdalena Kuta","avatar":""},{"name":"Małgorzata Potocka","avatar":""},{"name":"Anna Romantowska","avatar":""},{"name":"Krzysztof Tyniec","avatar":""},{"name":"Mirosław Zbrojewicz","avatar":""},{"name":"Karolina Rzepa","avatar":""},{"name":"Andrzej Grabowski","avatar":""},{"name":"Beata Bandurska","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324230);
