INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninja-kamui', 'Ninja Kamui', 'Ninja Kamui', 'https://phimimg.com/upload/vod/20240625-1/6fb03c27423c20b7ff2a5f9403b0d021.jpg', 'https://phimimg.com/upload/vod/20240625-1/c0d45374850807a288a9466d909a24f2.jpg', '<p>Một nhóm sát thủ thực hiện một cuộc trả thù đẫm máu đối với Joe Logan – một cựu ninja đã trốn thoát khỏi gia tộc của mình – và gia đình anh ta vì đã phản bội mật mã cổ xưa của họ. Thoát khỏi cái chết dường như của mình, Joe sẽ tái xuất với tư cách là con người cũ của mình - Ninja Kamui - để trả thù cho gia đình và bạn bè cũng như hạ bệ chính gia tộc đã tạo nên anh.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kenjiro Tsuda","avatar":""},{"name":"Atsushi Ono","avatar":""},{"name":"Yuuki Wakai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324230);
