INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-dinh-menh', 'Vòng Xoáy Định Mệnh', 'Twist of Fate', 'https://phimimg.com/upload/vod/20240207-1/5470fd8c4e63ae4ea19655e1bf950637.jpg', 'https://phimimg.com/upload/vod/20240207-1/64bc5d07684e464c33e471b17586ebfd.jpg', '<p>Một hiểu lầm đã phá vỡ một gia đình, khiến cho hai anh em sinh đôi phải xa nhau. Tuy nhiên, định mệnh đã đưa họ trở lại nhờ vào tình yêu. Hai anh em sinh đôi này xuất hiện trong cuộc đời của Wimala vào những thời điểm khác nhau. Người anh, Thiwa, đến từ phương xa. Người em, Tawan, bước vào cuộc đời cô trong lúc đầy sóng gió. Liệu Wimala sẽ chọn ai? Thiwa, một sĩ quan cảnh sát trẻ phải đóng giả thành Tawan, một chàng trai quyến rũ thuộc tầng lớp thượng lưu để điều tra một vụ ma túy xuyên quốc gia mà không hề hay biết họ chính là anh em sinh đôi. Tawan bị mất trí nhớ và được Wimala, hôn thê của Thiwa chăm sóc. Trong khi đó, Thiwa lại phải chịu sự giám sát và theo dõi của Grace, người yêu Tawan. Một sự hoán đổi sẽ thay đổi vận mệnh của họ mãi mãi.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pattaradet Sa-nguankwamdee","avatar":""},{"name":"Thisa Varitthisa Limthammahisorn","avatar":""},{"name":"Sky Maria Hoerschler","avatar":""},{"name":"Sarawut Martthong","avatar":""},{"name":"Premsinee Ratanasopha","avatar":""},{"name":"Adisorn Athakrit","avatar":""},{"name":"Tos Rawidcha Panjawit","avatar":""},{"name":"Pol Tanthasatien","avatar":""},{"name":"Rachanee Siralert","avatar":""},{"name":"Siripich Wimolnoch","avatar":""},{"name":"Sumet Ong-ard","avatar":""},{"name":"Surasak Chaiat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324230);
