INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-hai-chien-tuyen', 'Tình Yêu Hai Chiến Tuyến', 'My Military Valentine', 'https://phimimg.com/upload/vod/20240410-1/b6ab6243982bf720da46a4549e9424ce.jpg', 'https://phimimg.com/upload/vod/20240410-1/611bcc158dfa3d51117d706ce293865e.jpg', '<p>Tình Yêu Hai Chiến Tuyến - My Military Valentine, kể về câu chuyện về sự lãng mạn và thống nhất giữa hai miền Triều Tiên giữa một ngôi sao thế giới Hàn Quốc đã nhập ngũ và một nữ quân nhân Triều Tiên. Lloyd là một ngôi sao thế giới có lượng fan nữ trên toàn cầu. Mặc dù anh ấy là một ngôi sao đẳng cấp thế giới, người đã càn quét tất cả các kỷ lục nghệ sĩ thế kỷ 21 của Hàn Quốc, nhưng anh ấy vẫn nhập ngũ sau khi bị cuốn vào một dạng âm mưu nào đó và trải qua một loạt các sự kiện. Thiếu úy Baek Young Ok dẫn đầu quân đoàn thứ tám của Triều Tiên trong lực lượng đặc biệt. Trái ngược với vẻ ngoài xinh đẹp, Baek Young Ok lại có nét quyến rũ hoài nghi và tính cách hoàn hảo.</p>', 'Tập 12', 16, 'series', 'ongoing', 10, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Nam Gyu Ri","avatar":""},{"name":"Kim Min seok","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324230);
