INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-19', 'Tầng 19', '19th Floor', 'https://phimimg.com/upload/vod/20240205-1/aed94d62d0258abed3753ddf20afdd00.jpg', 'https://phimimg.com/upload/vod/20240205-1/7b03ae0184ece3bcd624a2f409a0ab93.jpg', '<p>Sinh viên Xuân Vũ, từ nhỏ đã nuôi trong mình khúc mắc đối với cha ruột, bất ngờ bị hút vào một cuộc phiêu lưu đầy nguy hiểm mang tên &quot;Tầng Thứ Mười Chín&quot;. Trong thế giới này, Xuân Vũ kết thân với Cao Vân - một người thông minh và điềm tĩnh, Đậu Đậu - có sức mạnh vũ lực đáng kinh ngạc, và Dương Bát Vạn - người hài hước. Họ bước chân vào một căn nhà ma đầy bí ẩn, nơi họ đối mặt với những thách thức khó khăn, như con rối giấy tấn công ở cổng vào thị trấn vắng. Trong bối cảnh nguy cơ rình rập, Xuân Vũ quyết định khám phá nguyên nhân sâu sắc của trò chơi. Họ tiến vào thế giới đầy biến động giữa thực tế và trò chơi, và khám phá những âm mưu nằm sau sự huyền bí này. Qua hành trình đầy chông gai, mọi người học được cách yêu thương và tôn trọng, nhận ra ý nghĩa của cuộc sống trong những tình huống khó khăn nhất. Mỗi người chọn lựa cách tiếp cận riêng để vượt qua thách thức, hiểu rõ hơn về cha mẹ và chấp nhận bản thân mình. Cuối cùng, sự can thiệp của cảnh sát giúp bóc lột bí mật đằng sau trò chơi &quot;Tầng Thứ Mười Chín&quot;</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sun Qian","avatar":""},{"name":"Miles Wei","avatar":""},{"name":"Bai Shu","avatar":""},{"name":"Wang Ruoshan","avatar":""},{"name":"Luo Yutong","avatar":""},{"name":"Yuetong Pan","avatar":""},{"name":"Xiao Kaizhong","avatar":""},{"name":"Dai Yaqi","avatar":""},{"name":"Zhang Yiyang","avatar":""},{"name":"Tao Hai","avatar":""},{"name":"Chen Chuang","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324230);
