INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tang-19', 'Tầng 19', '19th Floor', 'tầng 19 19th floor sun qian miles wei bai shu wang ruoshan luo yutong yuetong pan xiao kaizhong dai yaqi zhang yiyang tao hai chen chuang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('stalker-toi-ac-hoan-hao', 'Stalker: Tội Ác Hoàn Hảo', 'Following', 'https://phimimg.com/upload/vod/20240716-1/3cd1df33338aa8714e658c5d466e3739.jpg', 'https://phimimg.com/upload/vod/20240716-1/ded28521d45ecfba09e549a5958cce5b.jpg', '<p>Nhân vật Han Sora là một “influencer” - người nổi tiếng trên mạng xã hội với ngoại hình xinh đẹp cùng những nội dung về cuộc sống lành mạnh và sành điệu. Nhưng Koo Jung-tae - nhân viên môi giới bất động sản có sở thích kỳ lạ - rình rập cuộc sống của mọi người, thường xuyên lợi dụng công việc để đột nhập vào nhà và trộm các món đồ không cần thiết bằng chìa khoá khách hàng đưa, đã vô tình phát hiện ra bí mật của Han Sora. Cô ta ăn một cái xúc xích ở cửa hàng tiện lợi trong khi đăng tải hình ảnh salad chay lên tài khoản mạng xã hội, hay tự ý lấy túi hiệu của một người không quen biết trong quán cà phê để chụp hình “sống ảo”.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FullHD', 'Hàn Quốc', 1, '[{"name":"변요한","avatar":""},{"name":"신혜선","avatar":""},{"name":"윤병희","avatar":""},{"name":"Lee Chang-won","avatar":""},{"name":"심달기","avatar":""},{"name":"이엘","avatar":""},{"name":"Kim Mi-hye","avatar":""},{"name":"박명훈","avatar":""},{"name":"Lee Se-rang","avatar":""},{"name":"Yun Seul","avatar":""},{"name":"장성범","avatar":""},{"name":"박예니","avatar":""},{"name":"Park E-hyun","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324230);
