INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-cua-than', 'Trò Chơi Của Thần', 'Gods'' Game We Play', 'https://phimimg.com/upload/vod/20240402-1/f691f8a45707ba6255ed18df40f3fbf4.jpg', 'https://phimimg.com/upload/vod/20240402-1/ec982068b40d5347fdb4429fe4f88856.jpg', '<p>Reiyan Asura, nếu đó là tên thật của anh ấy, thức tỉnh trong khoảng không, bị ràng buộc bởi xiềng xích. Anh ta không nhớ mình là ai hay làm thế nào anh ta đến được thế giới màu trắng này.</p><p>Anh ấy không hề biết rằng anh ấy đã cùng hàng triệu người khác tham gia vào một trò chơi phức tạp, nơi chỉ có kẻ mạnh nhất mới thắng thế. Reiyan tuy mạnh mẽ nhưng liệu anh có bí mật nào có thể giúp anh sống sót không? Chào mừng đến với trò chơi của Thần. Hãy chứng minh giá trị của bạn hoặc chết để giải trí cho Ngài.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akari Kito","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Hina Tachibana","avatar":""},{"name":"Kanna Nakamura","avatar":""},{"name":"Ami Koshimizu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
