INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-vu-tru-lon', 'Thời Đại Vũ Trụ Lớn', 'The Age of Cosmos Exploration', 'https://phimimg.com/upload/vod/20240304-1/c17071abd969826431d2d9a65e199f1e.jpg', 'https://phimimg.com/upload/vod/20240304-1/aabaeaa268f0797ad3b4be938b1a14a0.jpg', '<p>Trái đất đang trong cơn khủng hoảng tàn khốc do sự xuất hiện của các mảnh sao neutron. Black Star Squad, lực lượng đặc biệt do Yao Yuan đứng đầu, nhận sứ mệnh cứu lấy tương lai của loài người. Họ sử dụng Spacecraft Hope để đưa một lượng lớn người rời khỏi Trái đất để khám phá một hành tinh mới trong vũ trụ. Trong cuộc phiêu lưu và chiến đấu của mình, họ nhận ra sự tồn tại của một nền văn minh vũ trụ tiên tiến hơn và sự thật kinh hoàng: vũ trụ không phải là thiên đường, mà là một vương quốc vô danh đầy bóng tối, nguy hiểm, chết chóc và kinh hoàng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324230);
