INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-duoi-khoi-to-doi-anh-hung-toi-nham-den-mot-cuoc-song-nhan-nha-o-vung-bien-cuong-phan-2', 'Bị đuổi Khỏi Tổ đội Anh Hùng, Tôi Nhắm đến Một Cuộc Sống Nhàn Nhã ở Vùng Biên Cương Phần 2', '真の仲間じゃないと勇者のパーティーを追い出されたので、辺境でスローライフすることにしました 第2期', 'https://phimimg.com/upload/vod/20240304-1/471c25e9c8fc2ede1d8e8f34626be0b1.jpg', 'https://phimimg.com/upload/vod/20240304-1/208375af14585e8a8e4e4f99636b5ac1.jpg', '<p>Người hùng Reid từng bị trục xuất khỏi đội dũng cảm và bị coi là không phải là đối tác thực sự. Giờ đây, anh điều hành một cửa hàng thuốc thảo dược ở một nơi xa xôi cùng với tình yêu trọn đời của mình là Công chúa Litte và người chị gái dũng cảm và thân thiết trước đây Luti, sống một cuộc sống yên bình và thoải mái. Tôi rất hạnh phúc. Tôi có thể tận hưởng khung cảnh tuyệt đẹp cùng Red. Tôi rất vui khi có thể dành thời gian với anh trai mình một lần nữa. Để có được viên ngọc quý nhất, họ bắt đầu du hành trong khi tận hưởng cảnh đẹp, vừa thưởng thức đồ ăn ngon...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324230);
