INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('metallic-rouge', 'Metallic Rouge', 'Metallic Rouge', 'https://phimimg.com/upload/vod/20240111-1/e46a71a86dc8a6b59b7a6482699e241a.jpg', 'https://phimimg.com/upload/vod/20240111-1/9a11174328168063827219c02da0a7de.jpg', '<p>Trong một thế giới nơi con người cùng tồn tại với người máy tên là Neans, một nhóm được gọi là Immortal Nine nổi lên chống lại xã hội. Được giao nhiệm vụ xử lý những kẻ nổi dậy, một Nean tên là Rouge Redstar (hay còn gọi là Metal Rouge) và điều tra viên Naomi Orthmann tiến đến sao Hỏa để truy tìm chúng… nhưng trước tiên, Rouge muốn một ít sô cô la.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yume Miyamoto","avatar":""},{"name":"Tomoyo Kurosawa","avatar":""},{"name":"Shunsuke Takeuchi","avatar":""},{"name":"Yu Shimamura","avatar":""},{"name":"Hiroyuki Yoshino","avatar":""},{"name":"Yui Ogura","avatar":""},{"name":"Kenjiro Tsuda","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324230);
