INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-blind-box-cua-toi', 'Người Yêu Blind Box Của Tôi', 'Limited 72 Hours of Love', 'https://phimimg.com/upload/vod/20240625-1/31c7a2c258df53271b67137417476a98.jpg', 'https://phimimg.com/upload/vod/20240625-1/bd14406d051e3250f3a19e91b70e550c.jpg', '<p>Tô Noãn Noãn là một nhà thiết kế blind box 25 tuổi không có gì nổi bật lắm. Vào ngày sinh nhật của mình, cô đã phải chịu đựng nhiều tổn thương từ việc tăng ca, bị hiểu lầm và cả chia tay bạn trai. Điều ước sinh nhật của cô là có được một anh bạn trai hoàn hảo. Với tâm trạng cực kỳ thất vọng, cô bước vào tiệm tạp hóa blind box rồi mua một chiếc hộp blind box tầm thường nằm trong góc khuất. Từ đó, cô bắt đầu bước vào hành trình ở cạnh những anh bạn trai blind box kỳ ảo.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Tử Tuyền","avatar":""},{"name":"Trình Tương","avatar":""},{"name":"Hà Sưởng Hy","avatar":""},{"name":"Vương Tinh Khải","avatar":""},{"name":"Đặng Trạch Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
