INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-yeu-blind-box-cua-toi', 'Người Yêu Blind Box Của Tôi', 'Limited 72 Hours of Love', 'người yêu blind box của tôi limited 72 hours of love lý tử tuyền trình tương hà sưởng hy vương tinh khải đặng trạch minh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chau-ngoc-ke-ben', 'Châu Ngọc Kề Bên', 'Treasures Around', 'https://phimimg.com/upload/vod/20240628-1/7ceff5e9f1129f23b5cee33c5ecd4456.jpg', 'https://phimimg.com/upload/vod/20240628-1/434fbf0f95014a2e9865f0b11f6528eb.jpg', '<p>Thiện Đan Đan mồ côi từ nhỏ, cô thông minh lanh lợi và ôm ấp hoài bão về sự nghiệp. Sau khi vào Bùi phủ, cô bị Bùi Phái dùng đủ mọi cách gây khó dễ. Thế nhưng Đan Đan lại tùy cơ ứng biến hóa giải được mọi khó khăn, từ đó xảy ra một loạt câu chuyện dở khóc dở cười. Trong quá trình tiếp xúc với Đan Đan, Bùi Phái dần dần nảy sinh tình yêu với cô. Nhưng một âm mưu đã vén màn ân oán từ tám năm trước, cuộc đời của Thiện Đan Đan và Bùi Phái chỉ vừa mới bắt đầu...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"徐璐","avatar":""},{"name":"畢雯珺","avatar":""},{"name":"Dai Chao","avatar":""},{"name":"Mengmeng Li","avatar":""},{"name":"Ma Ruihan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
