INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chau-ngoc-ke-ben', 'Châu Ngọc Kề Bên', 'Treasures Around', 'châu ngọc kề bên treasures around 徐璐 畢雯珺 dai chao mengmeng li ma ruihan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('omg-vampire-uncut-ver', 'OMG Vampire (Uncut Ver.)', 'OMG Vampire (Uncut Ver.)', 'https://phimimg.com/upload/vod/20240610-1/b569917b9237e4233b0b2e6fb9927e5b.jpg', 'https://phimimg.com/upload/vod/20240610-1/e972b15e507f2eb6d9e51053df31100d.jpg', '<p>Sau khi thức dậy từ giấc ngủ dài cả thế kỷ, ma cà rồng Poom phát hiện ra rằng vùng đất của ma cà rồng đã cấm ma cà rồng gen-x yêu nhau. Luật mới không phù hợp với Poom và anh rủ nhóm bạn thân của mình là Ren, Ran, Mix và Jolie - chạy trốn đến vùng đất của loài người, nơi mọi người có nhiều tự do hơn. Tuy nhiên, việc đến được đó sẽ không hề dễ dàng. Họ sẽ cần ghi tên mình vào sổ Sự Sống và sống trong cơ thể của con người song trùng với họ, và việc này cũng sẽ gây nên nhiều hiểm họa không thể đoán trước. Poom đến thế giới loài người và sống cuộc đời của một chàng trai trẻ có trái tim tan vỡ. Cuộc sống ở vùng đất của con người trở nên hỗn loạn khi anh gặp Patrick, chủ một quán bar bí mật và cuối cùng Poom tới làm việc cho anh ta. [Vietsub từ Sub Thái Khốt Ngai]</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Lee Long Shi","avatar":""},{"name":"Thanatsaran Samthonglai","avatar":""},{"name":"David Kittikawin Justice","avatar":""},{"name":"Kan Tangruek","avatar":""},{"name":"Son Ravisut Patipatvasin","avatar":""},{"name":"Non Nonpawit Lertrommayanant","avatar":""},{"name":"Buntawit Tragulpanich","avatar":""},{"name":"Tanadech Deeseesuk","avatar":""},{"name":"Thanakorn Kuljarassombat","avatar":""},{"name":"Varakorn Varuncharoentham","avatar":""},{"name":"Peter Tuinstra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324230);
