INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-ken-phan-2', 'Phá Kén (Phần 2)', 'Insect Detective (Season 2)', 'https://phimimg.com/upload/vod/20240521-1/f2d3729e2f2516abe726fe41eef00135.jpg', 'https://phimimg.com/upload/vod/20240521-1/28d5656fcdb10f746c0ceb079687c717.jpg', '<p>Bộ phim kể về câu chuyện một nghiên cứu sinh ngành Độc học Côn trùng Đàm Cảnh Thiên vô tình bị cuốn vào một vụ án ly kỳ. Trong quá trình giúp cảnh sát phá án anh đã nảy sinh tình cảm với bác sĩ pháp y Kim Linh, đồng thời khám phá ra bí ẩn về thân thế của mình, vạch trần kẻ đứng sau đã ẩn náu nhiều năm.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"張耀","avatar":""},{"name":"Chuyue Chen","avatar":""},{"name":"Thassapak Hsu","avatar":""},{"name":"Lawrence Wong","avatar":""},{"name":"Zhu Gang Ri Yao","avatar":""},{"name":"高卿尘","avatar":""},{"name":"Pornnappan Pornpenpipat","avatar":""},{"name":"Eazin Poe","avatar":""},{"name":"Zhou Kaikai","avatar":""},{"name":"Zhang Duo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324230);
