INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-gia-quyet-giang-ho-quy-su-luc', 'Bách Gia Quyết: Giang Hồ Quỷ Sự Lục', 'Bai Jia Jue Zhi Jiang Hu Gui Shi Lu', 'https://phimimg.com/upload/vod/20240320-1/4d2aa88a17dfc4a84e40bcedf947a206.jpg', 'https://phimimg.com/upload/vod/20240320-1/91fbfb4c9ac4de4d4f409cba81708243.jpg', '<p>Nhân vật chính có một hành trình phiêu lưu trong giang hồ đầy thách thức và nguy hiểm. Phim được sản xuất với đồ họa đẹp mặt, Cốt truyện hấp dẫn li kỳ sẽ mang đến cho khác giả những trải nghiệm chân thực và chứng kiến những trận chiến đầy kịch tính, nghẹt thở.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324230);
