INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tonbo', 'Tonbo!', 'Tonbo!', 'https://phimimg.com/upload/vod/20240427-1/32c098b04abed5f4e2cbb473700c72c7.jpg', 'https://phimimg.com/upload/vod/20240427-1/1a9108a4c3419d36aad81bedacb4aa13.jpg', '<p>Câu chuyện kịch tính về golf trên Quần đảo Tokara tuyệt đẹp. Igarashi từ bỏ quá khứ, chuyển đến đảo Hinoshima, &quot;thiên đường cuối cùng của Nhật&quot;. Anh gặp Tonbo, học sinh duy nhất với tài năng golf phi thường. Cuộc gặp này thay đổi số phận họ.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rika Hayashi","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Shin Aomori","avatar":""},{"name":"Mizuka Arima","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Mimi Maihane","avatar":""},{"name":"Kenji Yamauchi","avatar":""},{"name":"Kentaro Takano","avatar":""},{"name":"Arisa Sekine","avatar":""},{"name":"Satomi Kobashi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
