INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-standin-chuc-nghiep-the-than', 'MY STAND-IN: Chức Nghiệp Thế Thân', 'MY STAND-IN (UNCUT)', 'https://phimimg.com/upload/vod/20240426-1/c5e201f9a5117f6d0ecf46759f014764.jpg', 'https://phimimg.com/upload/vod/20240426-1/7dbf93893b95d8b99a3581bf22adfc80.jpg', '<p>Joe, một diễn viên đóng thế cho Tong, một ngôi sao trẻ nổi tiếng, tình cờ gặp Ming. Hai người có một mối quan hệ sâu sắc mà Joe không hề biết rằng Ming luôn xem anh như người thay thế cho Tong. Khi sự thật được phơi bày, Joe phải làm việc trên một bộ phim nước ngoài và một tai nạn đáng tiếc đã cướp đi mạng sống của anh. Joe tỉnh dậy trong cơ thể của một chàng trai tên Joe, người đã gặp tai nạn vào cùng ngày và được mẹ chăm sóc cùng sự giúp đỡ từ Wut. Mọi thứ đưa Joe trở lại cuộc sống như trước đây, với những người và Joe gặp lại Ming. Trong cuộc sống này, Ming muốn Joe trở lại bên mình như trước đây. Ming cố gắng tìm hiểu sự thật về việc Joe còn sống để đưa anh trở lại bên mình và kể cho anh lý do tại sao anh không có cơ hội để nói cho Joe biết trước khi quá muộn...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Poompat Iam-samang","avatar":""},{"name":"Phuripan Sapsangsawat","avatar":""},{"name":"Porsche Tanathorn Charoenratanaporn","avatar":""},{"name":"Jirakit Thawornwong","avatar":""},{"name":"Inntouch Naphat Chalermphonphakdee","avatar":""},{"name":"Billy Possathorn Wittanyaprechapol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
