INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-voi-1000-dua-con', 'Người đàn ông với 1000 đứa con', 'The Man with 1000 Kids', 'https://phimimg.com/upload/vod/20240713-1/766d668282b899db3d2cc2ae0a4d6869.jpg', 'https://phimimg.com/upload/vod/20240713-1/14805e8b311495415ecec9b59bf2a258.jpg', '<p>Một nhóm các gia đình biết được rằng người đàn ông cuốn hút mà họ tin tưởng lại chính là người hiến tinh trùng cho hàng trăm đứa trẻ khác trên thế giới.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2024, 'Vietsub', 'FullHD', 'Anh', 0, '[{"name":"Jonathan Meijer","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324230);
