INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-thanh-pho-bi-an', 'Truyền Thuyết Thành Phố Bí Ẩn', 'Legend of the Hidden Land', 'https://phimimg.com/upload/vod/20240609-1/fda77c3e00440cbe466a21e0ed3b843b.jpg', 'https://phimimg.com/upload/vod/20240609-1/17f21f36e1395ae175ceb5b671f0bf7f.jpg', '<p>Truyền Thuyết Thành Phố Bí Ẩn - The Legend of Hidden City xoay quanh câu chuyện về Khem, một cô gái lớn lên không biết về quá khứ của mình. Đột nhiên, cô phải đối mặt với trách nhiệm lớn khi phát hiện ra mình là công chúa của thành phố bí mật &quot;Muang Bang Bod&quot; và sở hữu vương trượng ma thuật &quot;Nopparat Scepter&quot;. Để đánh thức sức mạnh của vương trượng và bảo vệ thành phố khỏi sự đe dọa tà ác, Khem phải khám phá bản chất thực sự của mình và chiến đấu trong một cuộc phiêu lưu đầy thách thức trước khi tuổi 21 của mình kết thúc.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 7, 2024, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Petch Boranin","avatar":""},{"name":"Nicha Piyawattananont","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324230);
