INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-gia-phong-cap-cuu-ban-thai', 'Oan Gia Phòng Cấp Cứu (Bản Thái)', 'Emergency Couple (Thailand)', 'https://phimimg.com/upload/vod/20240609-1/5e1b31d8666f76deaa625a4e9da180f8.jpg', 'https://phimimg.com/upload/vod/20240609-1/8df3f7ffb2f37070727e5129c542ae41.jpg', '<p>Oan Gia Phòng Cấp Cứu (Bản Thái) - Emergency Couple kể về Pun, một chuyên gia dinh dưỡng, đã tận hưởng một cuộc sống êm đềm cho đến khi cô gặp Sean, một sinh viên y đến từ một gia đình giàu có và truyền thống làm bác sĩ. Mặc dù gặp phải sự phản đối từ gia đình của Sean, hai người quyết định kết hôn. Tuy nhiên, họ nhanh chóng nhận ra rằng cuộc sống hôn nhân của họ không hề màu hồng. Sau khi ly hôn, cả Pun và Sean tốt nghiệp y và bắt đầu thực tập tại một bệnh viện. Vào một ngày định mệnh, họ gặp nhau tại phòng cấp cứu của bệnh viện, mở ra một chương mới trong mối quan hệ của họ.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2024, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Bua Nalinthip Sakulongumpai","avatar":""},{"name":"Sean Jindachot","avatar":""},{"name":"Nophand Boonyai","avatar":""},{"name":"Patteera Sarutipongpokin","avatar":""},{"name":"Ploynira Hiruntaveesin","avatar":""},{"name":"Akalavut Mankalasut","avatar":""},{"name":"Sansanee Sawangrot","avatar":""},{"name":"Tanawat Cheawaram","avatar":""},{"name":"Daraneenute Pasutanavin","avatar":""},{"name":"Noon Daran Thitakawin","avatar":""},{"name":"Prin Wikran","avatar":""},{"name":"Chertsak Pratumsrisakh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324230);
