INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-khi-vuong-quoc-moi', 'Hành Tinh Khỉ: Vương Quốc Mới', 'Kingdom Of The Planet Of The Apes', 'https://phimimg.com/upload/vod/20240507-1/840c544652e6f54bcb8882fb9301aebc.jpg', 'https://phimimg.com/upload/vod/20240507-1/569ff6ca8838fb86e397a82f167e6e3b.jpg', '<p>Phim lấy bối cảnh nhiều năm sau triều đại của Proximus Ceasar trong Đại Chiến Hành Tinh Khỉ (2017). Khỉ trở thành giống loài thống trị thế giới, còn con người phải khép mình trong bóng tối. Triều đại độc tài mới được thiết lập. Noa – một chú khỉ trẻ đặt ra những câu hỏi về quá khứ của hành tinh khỉ và dấn thân vào hành trình chống lại đế chế mới.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Owen Teague","avatar":""},{"name":"Freya Allan","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Peter Macon","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Eka Darville","avatar":""},{"name":"Travis Jeffery","avatar":""},{"name":"Neil Sandilands","avatar":""},{"name":"Sara Wiseman","avatar":""},{"name":"Ras-Samuel Welda''abzgi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324230);
