INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-tay-choi-sieu-dang-2-bac-thay-lua-dao', 'Những Tay Chơi Siêu Đẳng 2: Bậc Thầy Lừa Đảo', 'The Player 2: Master Of Swindlers', 'https://phimimg.com/upload/vod/20240604-1/4fe95d84aa32f20013ad40dbfe80f274.jpg', 'https://phimimg.com/upload/vod/20240604-1/64d51ce17708ee0ba4d8cc2e13cfa396.jpg', '<p>Tiếp nối phần đầu ăn khách, trong Những Tay Chơi Siêu Đẳng 2: Bậc Thầy Lừa Đảo, những kẻ lừa đảo bậc thầy sẽ tái hợp để thực hiện các phi vụ tưởng chừng như bất khả thi. Kẻ thù mới của họ là một tổ chức tội phạm tinh vi chuyên thực hiện những hoạt động bất hợp pháp. Liệu các tay chơi siêu đẳng có thể một lần nữa giành chiến thắng và phơi bày tội ác của chúng hay không?</p>', 'Hoàn Tất (12/12)', 14, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Seung Hyun","avatar":""},{"name":"Oh Yeon Seo","avatar":""},{"name":"Lee Si Eon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324230);
