INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thach-ma-dam-yeu', 'Thách Mà Dám Yêu', 'Dare to Love Me', 'https://phimimg.com/upload/vod/20240522-1/c29dd17e068eafbcfc8c35d848983c34.jpg', 'https://phimimg.com/upload/vod/20240522-1/8d45424004788050a8d8e20cf34da15d.jpg', '<p>Sau khi rời quê nhà vùng nông thôn được gây dựng dựa trên luật pháp Joseon, nam nhân nọ gặp một nữ nhân có cá tính mạnh thử thách những ranh giới xã hội cứng nhắc của chàng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Myung Soo","avatar":""},{"name":"Lee Yoo Young","avatar":""},{"name":"Sunwoo Jae Deok","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324231);
