INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-anh-hung', 'Phản Anh Hùng', 'Anti-Hero', 'https://phimimg.com/upload/vod/20240504-1/3e9b049d9c1823fcde5c73daa8b79fa3.jpg', 'https://phimimg.com/upload/vod/20240504-1/f32fe13a211c5ffc4c1fb9f7991ede0d.jpg', '<p>Trong một hệ thống tư pháp kết án hầu như mọi bị cáo, một luật sư vượt mọi khó khăn để biện hộ cho thân chủ của mình – bất kể chứng cứ buộc tội họ có rõ ràng đến đâu.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroki Hasegawa","avatar":""},{"name":"Takumi Kitamura","avatar":""},{"name":"Mayu Hotta","avatar":""},{"name":"Oshima Yuko","avatar":""},{"name":"Yoshino Kimura","avatar":""},{"name":"Mansai Nomura","avatar":""},{"name":"Takanori Iwata","avatar":""},{"name":"Kazuyuki Aijima","avatar":""},{"name":"Misuzu Kanno","avatar":""},{"name":"Toshimasa Komatsu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324231);
