INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-tam-ky', 'Nhan Tâm Ký', 'Follow Your Heart', 'https://phimimg.com/upload/vod/20240622-1/a735814ac11eb899991588cd00983ef0.jpg', 'https://phimimg.com/upload/vod/20240622-1/d0bf2647f61c7d02de2a2cd048121bb8.jpg', '<p>&quot;Nhan Tâm Ký&quot; là bộ phim cổ trang tình cảm do Vu Trung Trung (tác phẩm &quot;Nửa Là Đường Mật, Nửa Là Đau Thương&quot;) làm đạo diễn, với sự tham gia của La Vân Hi (tác phẩm &quot;Hương Mật Tựa Khói Sương&quot;) và Tống Dật (tác phẩm &quot;Khánh Dư Niên - Phần 1&quot;) trong vai trò diễn viên chính. Bộ phim kể về câu chuyện lãng mạn định mệnh giữa Giang Tâm Bạch (La Vân Hi thủ vai) - vị quận vương lạnh lùng mắc chứng mù mặt, quyết tâm tiêu diệt &quot;Quế Thảo&quot; trên khắp thiên hạ, và Nhan Nam Tinh (Tống Dật thủ vai) - nữ du y nhiệt huyết &quot;biến hình&quot; mỗi tháng một lần. Cả hai cùng nhau phiêu lưu giang hồ để tìm kiếm tình yêu, qua đó truyền tải ý nghĩa thật sự của tình yêu – dung mạo tuy quan trọng nhưng không thể so sánh với sự đồng điệu trong tâm hồn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"羅雲熙","avatar":""},{"name":"宋轶","avatar":""},{"name":"Chen Yao","avatar":""},{"name":"丞磊","avatar":""},{"name":"黃日瑩","avatar":""},{"name":"Gu Zicheng","avatar":""},{"name":"Guan Zijing","avatar":""},{"name":"Deng Kai","avatar":""},{"name":"唐曾","avatar":""},{"name":"Huang Xiaolei","avatar":""},{"name":"洪堯","avatar":""},{"name":"Wen Zhengrong","avatar":""},{"name":"He Zhonghua","avatar":""},{"name":"Yue Yueli","avatar":""},{"name":"Cao Weiyu","avatar":""},{"name":"Liu Tianzuo","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Wang Yifei","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a0