INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('iland-2-na', 'I-LAND 2 N/a', 'I-LAND 2 N/a', 'https://phimimg.com/upload/vod/20240608-1/faca93a3b7528bab3d14c6b67da069b6.jpg', 'https://phimimg.com/upload/vod/20240608-1/e8431f84829d45d6f0f6a7394be3c87f.jpg', '<p>Tiếp nối thành công mùa 1 với các nam thần ENHYPEN, mùa 2 của I-Land sẽ dành riêng cho các quý cô cạnh tranh để tạo nên một nhóm nhạc nữ đáng mơ ước. Liệu thí sinh nào sẽ lọt vào &quot;mắt xanh&quot; của dàn tiền bối kỳ cựu bao gồm Taeyang, Monika, Lee Jung Lee, Jeon Somi, 24 và VVN?</p>', 'Full', 11, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"송강","avatar":""},{"name":"Teddy Park","avatar":""},{"name":"태양","avatar":""},{"name":"VVN","avatar":""},{"name":"모니카","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324231);
