INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-trieu-tich', 'Hiểu Triều Tịch', 'Jade''s Fateful Love', 'https://phimimg.com/upload/vod/20240616-1/ff895c6b938bbe99f9074b8db6bc5ec3.jpg', 'https://phimimg.com/upload/vod/20240616-1/4e3196397f63242e3ce5b73108f2351f.jpg', '<p>Nữ chính Đồ Lệ là một phàm nhân, thích huyền ca và là một kỹ sư. Nam chính Kính Huyền có ước muốn lớn lên sẽ trở thành một chủ tướng khí thế. Nữ chính 2 Tu Linh Tê: là hậu duệ Thần Gia, là nữ nhân cầm kỳ thư họa đều tinh thông. Nam chính 2 Tiêu Tế là phàm nhân, anh ta khá đặc biệt, là hoàng tộc Tiêu Thị Phụng Miên: nữ chính 3, là một nữ tử thần bí, thuộc chủng tộc Thượng Cổ Thần Thú tộc Linh Hoàng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hani Kezi","avatar":""},{"name":"Yan Xu Jia","avatar":""},{"name":"Zhang Jia-Yuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324231);
