INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-tay-huong-dan-yeu-duong-tiet-kiem', 'Sổ Tay Hướng Dẫn Yêu Đương Tiết Kiệm', 'Love on a Shoestring', 'https://phimimg.com/upload/vod/20240425-1/a5c1888c3c08740f703daedfef8ccf91.jpg', 'https://phimimg.com/upload/vod/20240425-1/4391f21860d519882bb8314a3cdfab27.jpg', '<p>Nhân vật chính là Giản Khả Khả (do Quách Thư Diệu thủ vai), một nhân viên văn phòng siêu tiết kiệm không hề theo đuổi tình yêu lại vô tình gặp phải người tiêu tiền như nước Vương Hải Khoát (do Lâm Tử Hoành thủ vai). Elly (do Châu Trí Huệ thủ vai) yêu thời trang và Giản Khả Khả không ưa nhau, còn Tôn Gia Lị (do Trần Ngữ An thủ vai), một cô gái ngọt ngào, gặp phải sinh viên đại học ngốc nghếch Lý Nguyên Sùng (do Hoàng Bách Phong thủ vai). Họ làm thế nào để lựa chọn giữa tình yêu và vật chất với những giá trị quan khác nhau một trời một vực.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Shu-yao Kuo","avatar":""},{"name":"Sam Lin","avatar":""},{"name":"Cheryl Chou","avatar":""},{"name":"He-Hsuan Lin","avatar":""},{"name":"Hugh Huang","avatar":""},{"name":"Katie Chen","avatar":""},{"name":"Tyler Ten","avatar":""},{"name":"Jernelle Oh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324231);
