INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noc-doc', 'Nọc Độc', 'Sting', 'https://phimimg.com/upload/vod/20240630-1/0008311385af2054b2d2690c00f95b86.jpg', 'https://phimimg.com/upload/vod/20240630-1/db23d5879552000e0b3c69930e480d5c.jpg', '<p>Sting 2024 là một bộ phim kinh dị do Kiah Roache-Turner đạo diễn. Nội dung phim xoay quanh cô bé 12 tuổi tên là Charlotte, do Alyla Browne thủ vai. Charlotte phát hiện ra một quả trứng nhện rơi xuống Trái Đất và nở ra một con nhện nhỏ có bé đặt tên là Sting,. Con nhện này nhanh chóng biến thành một con quái vật khổng lồ ăn thịt người. Khi con nhện trở nên nguy hiểm hơn, Charlotte phải chiến đấu để bảo vệ bản thân và gia đình.</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Úc', 1, '[{"name":"Alyla Browne","avatar":""},{"name":"Ryan Corr","avatar":""},{"name":"Penelope Mitchell","avatar":""},{"name":"Robyn Nevin","avatar":""},{"name":"Noni Hazlehurst","avatar":""},{"name":"Silvia Colloca","avatar":""},{"name":"Danny Kim","avatar":""},{"name":"Jermaine Fowler","avatar":""},{"name":"Tony J. Black","avatar":""},{"name":"Alcira Carpio","avatar":""},{"name":"Kate Walsh","avatar":""},{"name":"Lee Perry","avatar":""},{"name":"Jett Berry","avatar":""},{"name":"Kade Berry","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324231);
