INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-theo-doi', 'Những Kẻ Theo Dõi', 'The Watchers', 'https://phimimg.com/upload/vod/20240629-1/f01324dd9f19995f68cc3575cc334458.jpg', 'https://phimimg.com/upload/vod/20240629-1/ea49f58dff5033894d45698146c05683.jpg', '<p>Bộ phim theo chân Mina, một họa sĩ 28 tuổi bị lạc trong khu rừng hoang sơ ở phía tây Ireland. Khi Mina tìm được nơi trú ẩn, cô không hề biết rằng mình đã bị mắc kẹt cùng ba người lạ khác, mà tất cả đều đang bị theo dõi và săn lùng bởi những sinh vật bí ẩn mỗi đêm.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Dakota Fanning","avatar":""},{"name":"Georgina Campbell","avatar":""},{"name":"Olwen Fouéré","avatar":""},{"name":"Oliver Finnegan","avatar":""},{"name":"Siobhan Hewlett","avatar":""},{"name":"Alistair Brammer","avatar":""},{"name":"Hannah Howland","avatar":""},{"name":"Charles Camrose","avatar":""},{"name":"Kya Brame","avatar":""},{"name":"Shane O''Regan","avatar":""},{"name":"Cara Steele","avatar":""},{"name":"Shannon Antonia","avatar":""},{"name":"Kofi De Graft Jordan","avatar":""},{"name":"Diarmuid de Faoite","avatar":""},{"name":"Ann Marie Horan","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324231);
