INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-am-sam-lam', 'Hắc Ám Sâm Lâm', 'Dark Forest', 'https://phimimg.com/upload/vod/20240629-1/4abc43a316a3ad9542d2a133fa656778.jpg', 'https://phimimg.com/upload/vod/20240629-1/65d0153db4306bf4e514108b08d016b9.jpg', '<p>Tổ chức Phòng chống Ma túy của Liên Hợp Quốc và cảnh sát Trung Quốc - Myanmar phối hợp tấn công tổ chức buôn ma túy do tập đoàn Saka đứng đầu, có âm mưu buôn lậu ma túy qua Trung Quốc để bán ra khắp thế giới. Công an rừng Trịnh Hồng Phong bất ngờ bị cuốn vào một vụ án lớn của bọn buôn ma túy và rơi vào tình thế nguy hiểm. Để trả thù cho đồng nghiệp bị sát hại và ngăn chặn ma túy tràn vào Trung Quốc, anh đã hợp tác với lão Ngô, người chịu nhiều đau khổ do bọn buôn ma túy gây ra. Trong khu rừng rậm biên giới, họ cùng chống lại bọn buôn ma túy và cuối cùng phối hợp với đặc nhiệm chống ma túy để phá hủy hang ổ của bọn chúng.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qi Hang","avatar":""},{"name":"Rick Xu","avatar":""},{"name":"于荣光","avatar":""},{"name":"Basa","avatar":""},{"name":"He Minghan","avatar":""},{"name":"Xu Yukun","avatar":""},{"name":"Liu Yihan","avatar":""},{"name":"Guo Zhen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324231);
