INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('club-friday-season-16-vi-yeu-nen-phai-nhan-tam', 'Club Friday Season 16: Vì Yêu Nên Phải Nhẫn Tâm', 'Club Friday Season 16: Love Bully', 'https://phimimg.com/upload/vod/20240608-1/bf6f76a09e94244143db5fbc8e6301f6.jpg', 'https://phimimg.com/upload/vod/20240608-1/0293cf01b580f9a6d9a450102965da28.jpg', '<p>Vì Yêu Nên Phải Nhẫn Tâm là câu chuyện tình đầy chông gai giữa cô chủ quán bar Night và cô gái nhà giàu Irin. Một người luôn quá bận tâm đến ý kiến của kẻ khác, người còn lại luôn thờ ơ với miệng lưỡi thế gian. Thế nào mới là cách tốt nhất để bảo vệ tình yêu của họ trước sự phản đối từ những người xung quanh?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Charlotte Austin","avatar":""},{"name":"Engfa Waraha","avatar":""},{"name":"Sirinart Sugandharat","avatar":""},{"name":"Meenay Jutai","avatar":""},{"name":"Thanapat Phiukham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324231);
