INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('them-phan-2', 'Them (Phần 2)', 'Them (Season 2)', 'https://phimimg.com/upload/vod/20240628-1/fec5823d4ef623669a275ba84984bd72.jpg', 'https://phimimg.com/upload/vod/20240628-1/4777c18051edb2c7984c23a338c0e137.jpg', '<p>Đó là năm 1991, và thám tử điều tra án mạng LAPD Dawn Reeve được giao phụ trách một vụ án mới: vụ sát hại khủng khiếp người mẹ nuôi đã khiến ngay cả những thám tử cứng rắn nhất cũng phải rung chuyển. Vượt qua khoảng thời gian hỗn loạn ở Los Angeles và thành phố đang trên bờ vực hỗn loạn, Dawn quyết tâm ngăn chặn kẻ sát nhân. Nhưng khi cô đến gần sự thật hơn, một điều gì đó đáng ngại và ác độc đã bủa vây cô và gia đình cô…</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Deborah Ayorinde","avatar":""},{"name":"Pam Grier","avatar":""},{"name":"Luke James","avatar":""},{"name":"Joshua J. Williams","avatar":""},{"name":"Jeremy Bobb","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324231);
