INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-nhap-cu', 'Dân Nhập Cư', 'Expats', 'https://phimimg.com/upload/vod/20240628-1/088e1962f2805b7b948b5d3e367734cb.jpg', 'https://phimimg.com/upload/vod/20240628-1/284b8cfb93f99a68a5b70dbb130af8b4.jpg', '<p>Dân Nhập Cư kể về đối lập với tấm thảm phức tạp của cư dân Hồng Kông, một nhóm phụ nữ đa diện bắt đầu một chuỗi các sự kiện thay đổi cuộc sống khiến mọi người phải điều hướng sự cân bằng phức tạp giữa đổ lỗi và trách nhiệm giải trình.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Sarayu Blue","avatar":""},{"name":"Ji-young Yoo","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"Tiana Gowen","avatar":""},{"name":"Bodhi del Rosario","avatar":""},{"name":"Ruby Ruiz","avatar":""},{"name":"Amelyn Pardenilla","avatar":""},{"name":"Jack Huston","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324231);
