INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyet-thuong-trieu-nhan', 'Nguyệt Thượng Triêu Nhan', 'Moon Love', 'https://phimimg.com/upload/vod/20240627-1/351d6989689972899351f79c51a1f770.jpg', 'https://phimimg.com/upload/vod/20240627-1/f5ab386b8a388cae1fa8bb8d8ae71326.jpg', '<p>Vân Triêu Nhan, một cô gái có khả năng nhìn thấy những người kẻ mà người thường không thể nhìn thấy được gọi là &quot;nghịch tiên&quot;. Một ngày nọ cô tình cờ gặp Nhậm Thời Khuyết vốn là vị thần mặt trăng đang đi tuần tại nhân gian. Vì nghịch tiên không dám tới gần Thời Khuyết nên cô tìm mọi cách có thể để đi theo Thời Khuyết để tránh khỏi rắc rối. Từ đây cả hai đã bắt đầu một câu chuyện đồng hành kỳ lạ và mối quan hệ của họ không dừng lại ở đó.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"王敬轩","avatar":""},{"name":"Meihan Li","avatar":""},{"name":"Wang Xuan","avatar":""},{"name":"Cao Wanjin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324231);
