INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-xi-ga-lon', 'Điếu Xì Gà Lớn', 'The Big Cigar', 'https://phimimg.com/upload/vod/20240627-1/80fea278c0cbb760a1e6472a1362e718.jpg', 'https://phimimg.com/upload/vod/20240627-1/3159541881651cf61d9f97555bca8f3d.jpg', '<p>The Big Cigar là một bộ phim truyền hình tiểu sử kinh dị miniseries được phát triển bởi Jim Hecht, dựa trên bài báo cùng tên trên Playboy năm 2012 của Joshuah Bearman. Sau các sự kiện của Đảng Báo đen vào những năm 1970, loạt phim kể về người sáng lập đảng Huey P.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"André Holland","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Tiffany Boone","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Marc Menchaca","avatar":""},{"name":"Moses Ingram","avatar":""},{"name":"Rebecca Dalton","avatar":""},{"name":"Olli Haaskivi","avatar":""},{"name":"Jordane Christie","avatar":""},{"name":"Glynn Turman","avatar":""},{"name":"Courtney Friel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324231);
