INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cung-phong-te-nhat-phan-2', 'Bạn Cùng Phòng Tệ Nhất (Phần 2)', 'Worst Roommate Ever (Season 2)', 'https://phimimg.com/upload/vod/20240627-1/9a9b597e143a61ea0e773683c232ef03.jpg', 'https://phimimg.com/upload/vod/20240627-1/14f8644bbe2c7494b820c6013dd4e5c8.jpg', '<p>Kẻ lừa đảo bạo lực. Kẻ thì sát nhân mặt lạnh. Những câu chuyện thật đáng sợ này hé lộ một số những cuộc sống chung tồi tệ nhất mà người ta có thể tưởng tượng.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324231);
