INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-cung-phong-te-nhat-phan-2', 'Bạn Cùng Phòng Tệ Nhất (Phần 2)', 'Worst Roommate Ever (Season 2)', 'bạn cùng phòng tệ nhất (phần 2) worst roommate ever (season 2)  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-lac-giang-ho', 'Phượng Lạc Giang Hồ', 'Phoenix Lands in the World', 'https://phimimg.com/upload/vod/20240611-1/eac30a25c015c0c9dd9f0c9d7ee08355.jpg', 'https://phimimg.com/upload/vod/20240611-1/2a6cda176bf37f95f515d490e961eddb.jpg', '<p>Tác giả “sao chép cốt truyện” siêu hot trên mạng Mạnh Tiểu Đường (Kha Dĩnh đóng), gặp được bên A mình luôn ao ước, đập tiền yêu cầu cô tìm lại tâm nguyện thuở đầu của cuốn tiểu thuyết võ hiệp cẩu huyết “Nam Tịch Truyện” kể về nữ chủ phản phái từ bỏ tình yêu chỉ để thượng vị. Mạnh Tiểu Đường vì tiền tùy ý thay đổi hoàn toàn cốt truyện, khiến hệ thống Văn Mạng nổi giận, ngoài ý muốn bị đưa tới thế giới võ hiệp chưa biết trước cốt truyện, trở thành nữ ma đầu hản phái Phượng Nam Tịch bị cả giang hồ truy sát, trong người có Hấp Vân Thần Công vô địch thiên hạ lại không sử dụng được. Trong lúc tìm đường giữ mạng, Phượng Nam Tịch gặp được tên trộm hoa đẹp trai Thẩm Dụ (Đặng Siêu Nguyên đóng), phát hiện mình bị ràng buộc cùng anh không thể giải thích được. Phượng Nam Tịch nếu muốn sử dụng Hấp Vân đại pháp, chỉ có thể dựa vào Thẩm Dụ. Phượng Nam Tịch biết rõ lợi mình, một lòng muốn tìm nam chính nguyên tác Diệp Vô Trần, hoàn thành nhiệm vụ “tái hiện cốt truyện” mà hệ thống giao cho. Trước ngày 15 tháng 8, chính đạo bao vây, khiến Diệp Vô Trần yêu mình, sau đó giết chết hắn. Nhưng trong ngoài giáo nguy cơ tứ phía, khiến cô chỉ có thế nắm chặt “bùa hộ thân” Thẩm Dụ. Phượng Nam Tịch không biết là, thân phận thật của Thẩm Dụ chính là Diệp Vô Trần cô đang vất vả tìm kiếm, đồng thời, mục đích Diệp Vô Trần hóa thân Thẩm Dụ tiếp cận Phượng Nam Tịch, chính là để giết chết cô, cướp đi bí kíp Hấp Vân thần công. Cuộc đọ sức giữa chính đạo và phản phái, sinh tử tồn vong, đóng kịch và chân tình, cứ thế âm thầm diễn ra…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ying Ke","avatar":""},{"name":"Deng Chao Yuan","avatar":""},{"name":"XINGYU CAO","avatar":""},{"name":"Li Jia Le","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324231);
