INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chay-xuyen-khong-gian', 'Người Chạy Xuyên Không Gian', 'Dark Matter', 'https://phimimg.com/upload/vod/20240508-1/a2843efad0fcc93a32caab3734b8c22c.jpg', 'https://phimimg.com/upload/vod/20240508-1/9fdd512bbf64e5426592223a798261d8.jpg', '<p>Jason Dessen bị bắt cóc vào một phiên bản khác của cuộc đời anh. Để trở về với gia đình thực sự của mình, anh dấn thân vào một hành trình đau khổ để cứu họ khỏi kẻ thù đáng sợ nhất có thể tưởng tượng: chính anh.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joel Edgerton","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Dayo Okeniyi","avatar":""},{"name":"Oakes Fegley","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324231);
