INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-ve-van-menh-phan-2', 'Tấm Vé Vận Mệnh (Phần 2)', 'The Big Door Prize (Season 2)', 'https://phimimg.com/upload/vod/20240625-1/920fcab65bfff9f5b2ea338372dc8ac2.jpg', 'https://phimimg.com/upload/vod/20240625-1/f074cceb36425bef50ff72b5020236a2.jpg', '<p>Một thị trấn nhỏ bị thay đổi mãi mãi khi một cỗ máy bí ẩn xuất hiện, hứa hẹn tiết lộ tiềm năng thật sự của mỗi người. Không lâu sau, người dân thị trấn bắt đầu chuyển việc, đánh giá lại các mối quan hệ và nghi ngờ những đức tin đã có từ lâu - tất cả để mưu cầu một tương lai tốt đẹp hơn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris O''Dowd","avatar":""},{"name":"Gabrielle Dennis","avatar":""},{"name":"Ally Maki","avatar":""},{"name":"Josh Segarra","avatar":""},{"name":"Damon Gupton","avatar":""},{"name":"Sammy Fourlas","avatar":""},{"name":"Djouliet Amara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324231);
