INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-cua-hoa-hong', 'Câu Chuyện Của Hoa Hồng', 'The Tale of Rose', 'https://phimimg.com/upload/vod/20240608-1/02344013ef8434a5dd741ee1f0cc3fd3.jpg', 'https://phimimg.com/upload/vod/20240608-1/317e8aec53d63b8a7fca7ce91d77073b.jpg', '<p>Hoàng Diệc Mai sinh ra và lớn lên trong sự bao bọc của một gia đình trí thức, cô sớm bộc lộ năng khiếu nghệ thuật ngay từ khi còn nhỏ. Hoàng Diệc Mai vừa đi làm đã được trọng dụng, cô gặp và yêu đối tác của mình là Bành Quốc Đống, nhưng cuối cùng họ không đến với nhau. Khoảng thời gian đi làm này cũng giúp cô có kế hoạch rõ ràng hơn cho cuộc sống của mình và quyết định quay lại trường học để học chuyên sâu. Sau khi tốt nghiệp, cô kết hôn với đàn anh khóa trên là Phương Hiệp Văn. Nhưng sau khi kết hôn, hướng phát triển của hai người quá khác nhau, cuối cùng họ chọn cách ly hôn. Hoàng Diệc Mai bắt đầu khởi nghiệp và nỗ lực làm việc trong lĩnh vực giám tuyển nghệ thuật. Trong khoảng thời gian này, cô cũng gặp được tri kỉ là Phó Gia Minh, nhưng Phó Gia Minh chỉ còn sống được vài tháng và tình yêu của họ kết thúc bằng sự chia ly giữa sự sống và chết. Nhưng Hoàng Diệc Mai không vì vậy mà cảm thấy chán nản, cô vẫn tiếp tục nỗ lực làm việc để có một cuộc sống tươi đẹp hơn.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"劉亦菲","avatar":""},{"name":"佟大為","avatar":""},{"name":"林更新","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"林一","avatar":""},{"name":"Peng Guanying","avatar":""},{"name":"霍建華","avatar":""},{"name":"Zhu Zhu","avatar":""},{"name":"Bi Wu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324231);
