INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ar-vat-ngu-xin-dung-giet-toi', 'AR Vật Ngữ: Xin Đừng Giết Tôi', 'AR Story (DONTKILLME)', 'https://phimimg.com/upload/vod/20240625-1/db62960a331b206e3b68631bcaf5566e.jpg', 'https://phimimg.com/upload/vod/20240625-1/cdd9f8744300ee036ad93b1294cb13f0.jpg', '<p>Bộ phim này được chuyển thể từ tiểu thuyết &quot;Đừng giết tôi&quot; của nữ hoàng trinh thám Nhật Bản, Natsuki Shizuko. Để giành lại tình yêu của vợ mình là Syndica, Trương Hiểu Long sử dụng công nghệ AR để tích hợp liền mạch thông tin từ thế giới thực với thế giới ảo. Anh đã thành công trong việc chuyển đổi thông tin thế giới ảo được thiết kế trước thành ký ức thực sự của Syndica, từ đó thay đổi thành công quyết định cảm xúc của cô. Tuy nhiên, trong kế hoạch của Trương Hiểu Long tồn tại một lỗi nghiêm trọng. Anh không tính đến sự phản bội của con người, dẫn đến việc vợ anh là Syndica bị người bạn thân nhất của cô là Hình Ba bí mật bắt cóc. Trong quá trình giải cứu vợ mình, Trương Hiểu Long buộc phải “tiết lộ” tất cả bí mật trước đây của mình, đẩy mối quan hệ của anh và Syndica một lần nữa đến bờ vực sinh tử.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Yin","avatar":""},{"name":"Owodog Chuang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324231);
