INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-thanh-thoi-tai-di-gioi-cua-cuu-ung-vien-dung-gia-da-gian-lan-tu-cap-do-hai', 'Cuộc Sống Thảnh Thơi Tại Dị Giới Của Cựu Ứng Viên Dũng Giả Đã Gian Lận Từ Cấp Độ Hai', 'Chillin'' In Another World With Level 2 Super Cheat Powers', 'https://phimimg.com/upload/vod/20240418-1/bdee29b1e7dc393d1aad66f792554056.jpg', 'https://phimimg.com/upload/vod/20240418-1/6d2a84c4b191cda3b92051b5ac8f5a03.jpg', '<p>Anime kể về Banaza, anh được triệu hồi đến Vương Quốc Ma Thuật Cryroad với tư cách là ứng cử viên cho chức vị Anh Hùng . Nhưng các chỉ số của Banaza chỉ ở mức ngang với 1 thường dân nên bị mọi người cho là 1 thất bại và đuổi anh khỏi cung điện . Tuy nhiên , khi anh lên Lv.2 thì mọi chỉ số được nâng lên vô cực và mở khóa toàn bộ skills . Câu chuyện phiêu lưu của anh chàng anh hùng bắt đầu từ đây ,...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Satoshi Hino","avatar":""},{"name":"Rie Kugimiya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324231);
