INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-da-den-phep-thuat', 'Người Da Đen Phép Thuật', 'The American Society of Magical Negroes', 'https://phimimg.com/upload/vod/20240624-1/443eabbb396cda1534136a6c0fe6ff7d.jpg', 'https://phimimg.com/upload/vod/20240624-1/7e341b027b63c2fc762df142c5b1b6e3.jpg', '<p>Trong nhiều thế kỷ, đã có một xã hội ẩn mình, hoạt động bí mật để bảo vệ người Da đen khỏi bị tổn hại. Và khi chàng trai trẻ Aren được tuyển vào, anh chàng có thể gây ra những xáo trộn thậm chí gây tổn hại đến mối tình mới chớm nở của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Justice Smith","avatar":""},{"name":"David Alan Grier","avatar":""},{"name":"An-Li Bogan","avatar":""},{"name":"Drew Tarver","avatar":""},{"name":"Michaela Watkins","avatar":""},{"name":"Aisha Hinds","avatar":""},{"name":"Tim Baltz","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Nicole Byer","avatar":""},{"name":"Zachary Barton","avatar":""},{"name":"Anthony Coons","avatar":""},{"name":"Robbie Troy","avatar":""},{"name":"Gillian Vigman","avatar":""},{"name":"James E. Welsh","avatar":""},{"name":"Mia Ford","avatar":""},{"name":"Eric Lutz","avatar":""},{"name":"Kees DeVos","avatar":""},{"name":"Aaron Coleman","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324231);
