INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duy-hoa-phong-bao-doi', 'Duy Hòa Phòng Bạo Đội', 'Formed Police Unit', 'https://phimimg.com/upload/vod/20240624-1/fdc8e9b0fabd2b9247cfac9c651173ca.jpg', 'https://phimimg.com/upload/vod/20240624-1/a835357ff3ff81c280acd62de04e9d03.jpg', '<p>Phim tập trung vào những khoảnh khắc sinh tử ít ai biết của lực lượng cảnh sát gìn giữ hòa bình Trung Quốc! Theo yêu cầu của Liên hợp quốc và được nhà nước cử đi, các sĩ quan cảnh sát gìn giữ hòa bình gánh vác sứ mệnh thiêng liêng ra nước ngoài thực hiện nhiệm vụ gìn giữ hòa bình ở những vùng truyền giáo bị chiến tranh tàn phá. Họ sẽ phải đối mặt với các cuộc tấn công khủng bố, bạo loạn vũ trang, băng nhóm và các tình huống nguy hiểm khác, hoạt động gìn giữ hòa bình không thể trì hoãn…</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"黃景瑜","avatar":""},{"name":"王一博","avatar":""},{"name":"鍾楚曦","avatar":""},{"name":"歐豪","avatar":""},{"name":"Zhu Yawen","avatar":""},{"name":"Jason Koo","avatar":""},{"name":"Zhao Huawei","avatar":""},{"name":"Bai Narisu","avatar":""},{"name":"Yu Peishan","avatar":""},{"name":"Kevin Lee","avatar":""},{"name":"Liu Xue","avatar":""},{"name":"Nan Fu Long","avatar":""},{"name":"Yin Xiaotian","avatar":""},{"name":"Joyce Feng","avatar":""},{"name":"Sun Yihan","avatar":""},{"name":"Li Mincheng","avatar":""},{"name":"Linyan Jiang","avatar":""},{"name":"Nwachukwu Kennedy Chukwuebuka","avatar":""},{"name":"Ling Chen","avatar":""},{"name":"Wei Chong","avatar":""},{"name":"Gao Shuqiao","avatar":""},{"name":"Dmitry Antonov","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784