INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-hai-cap-song-sinh-o-bogota', 'Chuyện Hai Cặp Song Sinh Ở Bogota', 'The Accidental Twins', 'https://phimimg.com/upload/vod/20240624-1/65ef32e7d032b5ab0994d3359f4ccaf6.jpg', 'https://phimimg.com/upload/vod/20240624-1/ea8fa07928cbf44c8231200412f312b1.jpg', '<p>Bị hoán đổi lúc mới sinh ở Colombia, hai cặp song sinh giống hệt nhau khám phá quá khứ phức tạp và danh tính mới trong bộ phim tài liệu hấp dẫn này.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324231);
