INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sang-den', 'Sáng Đèn', 'Sáng Đèn', 'https://phimimg.com/upload/vod/20240623-1/80776fe0c2d849f7ba732ce480c9064a.jpg', 'https://phimimg.com/upload/vod/20240623-1/ede7f7892e47d75d65afef9d5c65f016.jpg', '<p>Câu chuyện vào những năm 1994, lúc bấy giờ đoàn hát cải lương chính thống, được khán giả săn đón, Thanh khi đó là một cậu bé 10 tuổi làm nghề bắt cá trên sông đã bất chấp nguy hiểm, ôm giữ bằng được bàn thờ Tổ và sau đó được ông Bầu đoàn hát nhận nuôi theo đoàn. Kiều Trúc Linh, một cô bé 9 tuổi xinh xắn, là con gái của cô đào hát nổi tiếng Kiều Trúc Lệ. Vì cứu con nên Trúc Lệ đã hy sinh thân mình… Mười năm sau, tình trạng ế khách kéo dài dù chủ đoàn đã dùng đủ mọi cách từ một đoàn cải lương chính thống, giờ trở thành một đoàn tạp kỷ có xiếc có lô tô ca nhạc, riêng tuồng hát thì chỉ còn trích đoạn và tân cổ giao duyên. Mặc dù tất cả mọi người đã đồng lòng cố gắng nhưng vẫn không cải thiện được tình hình bao nhiêu, vẫn cảnh ế khách, thu nhập vẫn eo hẹp. Mặc dù phải vật lộn với hoàn cảnh khó khăn của đoàn hát nhưng tình yêu nghề, tình yêu đôi lứa vẫn luôn được đề cao trong mỗi cá nhân. Tiêu biểu là mối tình đẹp trong sáng của Thanh và Linh; mối tình sâu đậm được xây đắp qua năm tháng nhưng cuối cùng phải chia lìa của Phi Khanh và Kim Yến. Chuyện đoàn hát lại tiếp tục xảy ra những tình cảnh không ai ngờ tới, để rồi cuối cùng họ vấn tiếp tục cùng nhau đi tiếp trên con đường nghệ thuật mình đã chọn, giá trị cốt lõi của sân khấu trong tâm những con người ăn cơm tổ vẫn còn mãi.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hữu Châu","avatar":""},{"name":"Bạch Công Khanh","avatar":""},{"name":"Kim Tử Long","avatar":""},{"name":"Chí Tâm","avatar":""},{"name":"Lê Thiện","avatar":""},{"name":"Cao Minh Đạt","avatar":""},{"name":"Hồng Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324231);
