INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-dai-huyen-thuat-su', 'Địch Nhân Kiệt: Đại Huyễn Thuật Sư', 'Detective Dee and the Great Illusionist', 'https://phimimg.com/upload/vod/20240622-1/3f7dda4194072d3186dfac99b42364d8.jpg', 'https://phimimg.com/upload/vod/20240622-1/db6589bd3b084752c7b94eaa0d5c5b0a.jpg', '<p>Chuyển thể từ truyền thuyết dân gian, kể về một vụ việc kỳ bí xảy ra tại vùng đất Ninh Châu, khi quái vật đang quấy phá, Địch Nhân Kiệt sau khi biết được chuyện này đã dẫn theo trợ thủ tiến hành điều tra bí mật lại phát hiện ra một vụ án tham nhũng không ai biết đến.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"周晴","avatar":""},{"name":"Zhou Ting","avatar":""},{"name":"Kenneth Zhu","avatar":""},{"name":"Jiao Haihua","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324231);
