INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-hinh-ky-sinh-khoi-nguyen', 'Dị Hình Ký Sinh: Khởi Nguyên', 'The Captives', 'https://phimimg.com/upload/vod/20240620-1/751f9c8abeed189021d4a2262594d680.jpg', 'https://phimimg.com/upload/vod/20240620-1/eb760add666715fbddea6007c2f54410.jpg', '<p>“Rốt cuộc mày là người hay quái vật?” Khi sinh vật ngoài hành tinh có trí tuệ vượt trội hơn con người xuất hiện, nhân loại đang sống trong thời kỳ khó khăn sẽ đối phó ra sao? Liên minh vệ binh Trái Đất đã chống lại bọ thú suốt hai mươi năm, không ngờ lại gặp phải một cuộc tấn công kỳ quái nhất. Kẻ thù của Tổng tư lệnh Kim Thiện Nhã không chỉ có bọ thú mà còn có... kẻ đứng sau giật dây như ma quỷ không biết ở nơi đâu...</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Henry Prince Mak","avatar":""},{"name":"Diao Biao","avatar":""},{"name":"于小琬","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324231);
