INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-ra-mot-the-gioi-tuyet-voi-phan-3', 'Mở Ra Một Thế Giới Tuyệt Vời (Phần 3)', 'KONOSUBA - God''s Blessing On This Wonderful World! (Season 3)', 'https://phimimg.com/upload/vod/20240412-1/2516f53b6a40da2b9ca5a46868590ff3.jpg', 'https://phimimg.com/upload/vod/20240412-1/25d434ecbe6f2c14cee82002226f2181.jpg', '<p>Satou Kazuma, một hikikomori đam mê trò chơi, Nhưng cuộc sống ngắn ngủi của anh kết thúc vì tai nạn giao thông lãng xẹt ... Nhưng khi anh ta tỉnh dậy, một cô gái xinh đẹp, người tự gọi mình là một nữ thần đã ở phía trước đôi mắt anh ấy và đưa anh ấy đến một thế giới khác, Khi sang thế giới mới, cậu gặp ngày càng nhiều mấy cô nàng không điên thì cũng tâm thần, riết rồi cậu muốn quay trở về thế giới cũ càng nhanh càng tốt...</p>', 'Tập 11', 11, 'hoathinh', 'ongoing', 7, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Jun Fukushima","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Kanon Takao","avatar":""},{"name":"Sayuri Yahagi","avatar":""},{"name":"Reina Ueda","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324231);
