INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tung-buoc-lun-sau', 'Từng Bước Lún Sâu', 'Your Trap', 'https://phimimg.com/upload/vod/20240612-1/0991be51baede8411e12761f42d1ac6a.jpg', 'https://phimimg.com/upload/vod/20240612-1/13d69cc3032f7be69ae581b1b2320dea.jpg', '<p>Hàn Khanh là một chuyên gia tư vấn tình cảm. Cô được khách hàng ủy thác điều tra chồng ngoại tình, trở thành trợ lý riêng của Phùng Tư Càn, chủ tịch tập đoàn Hoa Kinh, từ đó cô bị cuốn vào một âm mưu được dàn xếp tỉ mỉ. Trải qua những nghi ngờ và dè chừng ban đầu, họ bắt đầu hợp tác, hỗ trợ, thẳng thắn với nhau để đi tìm chân tướng. Cuối cùng, họ khám phá ra bản chất của hôn nhân và tìm thấy tình yêu đích thực.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wen Mo Yan","avatar":""},{"name":"Haonan Shen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324231);
