INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-nan', 'Tai Nạn', 'Crash', 'https://phimimg.com/upload/vod/20240616-1/50f226eea82bde7daa285637698aae0d.jpg', 'https://phimimg.com/upload/vod/20240616-1/e38b33a29f463217a48f328e51a20a62.jpg', '<p>Thanh Tra Giao Thông xoay quanh Đội Điều Tra Tội Phạm Giao Thông (TCI), chuyên điều tra các vụ án liên quan đến xe cộ như gian lận bảo hiểm, lái xe báo thù và các tội phạm giao thông phức tạp. Cha Yeon Ho, một cựu sinh viên KAIST logic, và Min So Hee, chuyên gia điều tra giao thông sắc sảo, là hai nhân vật chính của câu chuyện. Bằng cách kết hợp hành động, kinh dị, bí ẩn và hài kịch, bộ phim mang đến cho khán giả những trải nghiệm hấp dẫn khi theo dõi cuộc phiêu lưu của Đội Điều Tra Tội Phạm Giao Thông trong việc vén màn bí ẩn của các vụ án giao thông.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이민기","avatar":""},{"name":"곽선영","avatar":""},{"name":"허성태","avatar":""},{"name":"이호철","avatar":""},{"name":"최문희","avatar":""},{"name":"백현진","avatar":""},{"name":"김광식","avatar":""},{"name":"오대석","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324231);
