INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-tuong-tuong', 'Những Người Bạn Tưởng Tượng', 'IF', 'https://phimimg.com/upload/vod/20240618-1/5b88a08c0fe9e10d8a24bafbba2230f7.jpg', 'https://phimimg.com/upload/vod/20240618-1/e998fd6708850226d2b5a805a1284cd6.jpg', '<p>Bộ phim xoay quanh một cô bé bất ngờ phát hiện ra mình có thể nhìn thấy những người bạn tưởng tượng của mọi người. Và cuộc hành trình bắt đầu khi cô bé sử dụng siêu năng lực của mình để giúp đỡ những người bạn tưởng tượng này tránh khỏi việc bị bỏ rơi và lãng quên bằng cách tìm kiếm, kết nối chúng với những đứa trẻ.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Cailey Fleming","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Steve Carell","avatar":""},{"name":"Phoebe Waller-Bridge","avatar":""},{"name":"Louis Gossett Jr.","avatar":""},{"name":"Alan Kim","avatar":""},{"name":"Liza Colón-Zayas","avatar":""},{"name":"Bobby Moynihan","avatar":""},{"name":"Catharine Daddario","avatar":""},{"name":"Audrey Hoffman","avatar":""},{"name":"Laquet Sharnell Pringle","avatar":""},{"name":"Ed Herbstman","avatar":""},{"name":"Barbara Andres","avatar":""},{"name":"Alexan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324231);
