INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-dung-cuoi-tai-yuma', 'Điểm Dừng Cuối Tại Yuma', 'The Last Stop in Yuma County', 'https://phimimg.com/upload/vod/20240619-1/80e8c4a1c665e3c7ccae45dcab959565.jpg', 'https://phimimg.com/upload/vod/20240619-1/7c7241b50e26b530f39013e4325207b0.jpg', '<p>Khi bị mắc kẹt tại một điểm dừng chân ở vùng nông thôn Arizona, một nhân viên bán hàng du lịch bị đẩy vào tình huống bắt giữ con tin nghiêm trọng bởi sự xuất hiện của hai tên cướp ngân hàng không hề e ngại về việc sử dụng sự tàn ác - hoặc thép cứng, lạnh lùng - để bảo vệ tài sản vấy máu của họ.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jim Cummings","avatar":""},{"name":"Jocelin Donahue","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Nicholas Logan","avatar":""},{"name":"Faizon Love","avatar":""},{"name":"Michael Abbott Jr.","avatar":""},{"name":"Connor Paolo","avatar":""},{"name":"Ryan Masson","avatar":""},{"name":"Sierra McCormick","avatar":""},{"name":"Gene Jones","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"Jon Proudstar","avatar":""},{"name":"Barbara Crampton","avatar":""},{"name":"Alex Essoe","avatar":""},{"name":"Sam Huntington","avatar":""},{"name":"Robert Broski","avatar":""},{"name":"Matt McVay","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324240);
