INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bai-tro-lai-tat-tay', 'Thần Bài Trở Lại Tất Tay', 'All In', 'https://phimimg.com/upload/vod/20240619-1/180956b7ed2b7f9f26f30f6ddeaa01fa.jpg', 'https://phimimg.com/upload/vod/20240619-1/2c24172ccd659dca5ad96cd9f92d32ef.jpg', '<p>Mang danh thần bài trăm trận trăm thắng, Trình Gia Lãng phát hoảng khi siêu năng lực mắt thần đột nhiên mất vào tay một kẻ gà mờ - Hoàng Tiểu Thất. Từ đây, cả hai phải miễn cưỡng hợp lực hòng chiến thắng vua bài - Vi Nhất Phú và làm lộ ra bí mật động trời...</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Malaysia', 1, '[{"name":"Lâm Đức Vinh","avatar":""},{"name":"Khương Hạo Văn","avatar":""},{"name":"Namewee","avatar":""},{"name":"Vương Lỗi","avatar":""},{"name":"Hoàng Thi Kỳ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324240);
