INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-ban-phim', 'Anh Hùng Bàn Phím', 'Troll Factory', 'https://phimimg.com/upload/vod/20240618-1/85bb8ca0547b90e2b9724bc8852e7f67.jpg', 'https://phimimg.com/upload/vod/20240618-1/bd90cfc1f17425a759ed9336609e0522.jpg', '<p>Im Sang-jin - một phóng viên mảng xã hội đã bị đình chỉ công tác sau bài phóng sự điều tra sai lệch về những lùm xùm của tập đoàn Manjun. Tưởng rằng phải chịu nỗi oan ức suốt đời, Im Sang-jin bất ngờ nhận được thông tin ẩn danh khẳng định anh không sai, mà mọi thứ đã bị thao túng bởi một “đội quân” trực tuyến: Chỉ cần có tiền, sự thật nào cũng hoá thành dối lừa, còn tin tức giả lại hoá thành sự thật. Quyết tâm dấn thân vào con đường điều tra “Team Aleph”, Im Sang-jin dần khám phá ra những bí mật động trời khi tiếp xúc với các thành viên chủ chốt của nhóm chuyên gieo rắc tin giả. Thế lực đứng sau các thông tin sai lệch có sức mạnh khủng khiếp đến nhường nào? Liệu Im Sang-jin có thể lật tẩy tất cả và giành chiến thắng giữa ranh giới mong manh của sự thật và dối trá?</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"손석구","avatar":""},{"name":"김성철","avatar":""},{"name":"김동휘","avatar":""},{"name":"홍경","avatar":""},{"name":"Lee Sun-hee","avatar":""},{"name":"Cha Young-ju","avatar":""},{"name":"Kim So-min","avatar":""},{"name":"김준한","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324240);
