INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-pooh-mau-va-mat-2', 'Gấu Pooh: Máu và Mật 2', 'Winnie-the-Pooh: Blood and Honey 2', 'https://phimimg.com/upload/vod/20240618-1/1a2e6d07b5405213ad78c7f30dd97569.jpg', 'https://phimimg.com/upload/vod/20240618-1/de32a89fc3d50219624529d13b00f499.jpg', '<p>Sau công cuộc tàn sát trong phần 1, các nhân vật gấu Pooh, heo Piglet, hổ Tigger... lần lượt bị phơi bày ra ánh sáng, bị con người biết đến nhiều hơn. Không muốn sống trong bóng tối nữa, hội sát nhân gấu Pooh lập kế hoạch càn quét thị trấn Ashdown, cũng là quê nhà của người bạn thơ ấu Christopher Robin. Liệu trong phần phim này, các nhân vật hay Christopher Robin sẽ thắng thế?</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Scott Chambers","avatar":""},{"name":"Ryan Oliva","avatar":""},{"name":"Marcus Massey","avatar":""},{"name":"Tallulah Evans","avatar":""},{"name":"Lewis Santer","avatar":""},{"name":"Simon Callow","avatar":""},{"name":"Eddy MacKenzie","avatar":""},{"name":"Thea Evans","avatar":""},{"name":"Alec Newman","avatar":""},{"name":"Nicola Wright","avatar":""},{"name":"Teresa Banham","avatar":""},{"name":"Toby Wynn-Davies","avatar":""},{"name":"Flynn Matthews","avatar":""},{"name":"Peter DeSouza-Feighoney","avatar":""},{"name":"Philip Philmar","avatar":""},{"name":"Mason Stanley Gold","avatar":""},{"name":"So","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324240);
