INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-quy-tan-nuong', 'Thủy Quỷ Tân Nương', 'Shuigui Bride', 'https://phimimg.com/upload/vod/20240617-1/19cb6f9fce6bf530a4f8a40943fdf456.jpg', 'https://phimimg.com/upload/vod/20240617-1/45d5c48d269385dbbe88ab71c30f297d.jpg', '<p>Trong một đêm mưa gió, tám người với những thân phận khác nhau tụ tập trong ngôi miếu đổ nát để tránh mưa và bắt đầu kể về truyền thuyết cô dâu ma nước ở thị trấn gần đó. Điều kỳ lạ là từng người trong miếu lần lượt chết một cách bí ẩn, khiến họ buộc phải tin rằng đó là ma nước báo thù, cô dâu đòi mạng. Hóa ra, những người này đều có mối quan hệ mật thiết với vụ thảm sát cả gia đình cô dâu ma nước năm xưa.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"尹思淇","avatar":""},{"name":"Wen Sheng","avatar":""},{"name":"Peize Li","avatar":""},{"name":"陆羽晴","avatar":""},{"name":"Li Ping","avatar":""},{"name":"庞统","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324240);
