INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-tu-bien-mat-roi', 'Thế Tử Biến Mất Rồi!', 'Missing Crown Prince', 'https://phimimg.com/upload/vod/20240425-1/22f92d9ac296e75ff33a419f6fe30303.jpg', 'https://phimimg.com/upload/vod/20240425-1/7ab0a5cb170f1e0dafa4e9414b01c1c7.jpg', '<p>Lấy bối cảnh thời Joseon, Thế Tử Biến Mất Rồi! kể về câu chuyện giữa Thế tử Yi Geon và Choi Myung Yoon, một cô gái có tài cưỡi ngựa và chữa bệnh xuất sắc. Tất cả bắt đầu khi Myung Yoon bắt cóc Yi Geon và cả hai buộc phải trốn chạy để bảo toàn tính mạng. Sau một khởi đầu đầy khó khăn, khoảng thời gian ở bên nhau và cùng nhau vượt qua hiểm nguy đã làm nảy nở mối tình lãng mạn giữa hai người.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Suho","avatar":""},{"name":"Hong Ye-ji","avatar":""},{"name":"Kim Min-kyu","avatar":""},{"name":"Myung Se-bin","avatar":""},{"name":"Kim Joo-heon","avatar":""},{"name":"Yoo Se-rye","avatar":""},{"name":"Jeon Jin-oh","avatar":""},{"name":"Cha Kwang-soo","avatar":""},{"name":"Kim Seol-jin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324240);
