INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-hoang-tien-ban', 'Bà Hoàng tiền Bẩn', 'Nelma Kodama The Queen of Dirty Money', 'https://phimimg.com/upload/vod/20240616-1/0d8a65ee681a8598a195cfebb4119901.jpg', 'https://phimimg.com/upload/vod/20240616-1/37ded0027377e8a28fcc30b6c42e480f.jpg', '<p>Phim kể về Nelma Kodama, một người phụ nữ kinh doanh người Brazil đã đi tù vì tham nhũng, tội phạm tổ chức và trốn thuế tiền tệ trong Chiến dịch Car Wash sau khi cô bị bắt khi cố gắng lên máy bay với 200 nghìn euro trong quần lót của mình tại sân bay Guarulhos</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Nelma Kodama","avatar":""},{"name":"Anzu Lawson","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324240);
