INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-so-khanh', 'Gã Sở Khanh', 'Mahal ko ang Mahal Mo', 'https://phimimg.com/upload/vod/20240616-1/188a9cc7ef75d9649eda611c1af98724.jpg', 'https://phimimg.com/upload/vod/20240616-1/94d0878a3bdc9af70a34b6be29111924.jpg', '<p>Hai người phụ nữ bị tổn thương bởi cùng một người đàn ông đã thành lập một liên minh để bắt quả tang người bạn trai lăng nhăng của họ. Nhưng mối liên kết bất ngờ của họ dẫn đến một mối tình lãng mạn khó có thể xảy ra giữa họ.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Angelica Hart","avatar":""},{"name":"Angeline Aril","avatar":""},{"name":"Van Allen Ong","avatar":""},{"name":"Mia Cruz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324240);
