INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-dong-thon-di-xa-co-su', 'Thượng Đồng Thôn: Dị Xà Cổ Sự', 'The Strange Snake Story in Shangtong Village', 'https://phimimg.com/upload/vod/20240616-1/9f2b93b86e657ac78cea0ce738e80973.jpg', 'https://phimimg.com/upload/vod/20240616-1/b7215b68355b3ff3b6ae82cb4a14e4e6.jpg', '<p>Bộ phim kể về một câu chuyện huyền thoại thời Dân Quốc. Người Nhật thèm khát một loài hoa thần kỳ trên đất Trung Hoa, nên đã ép Ngự Lân Long giúp họ tìm kiếm loài hoa này. Ngự Lân Long để bảo vệ loài hoa không bị ngoại bang chiếm đoạt đã bày mưu và đấu trí với họ, cuối cùng tiêu diệt kẻ xâm lược. Cuối cùng, Ngự Lân Long và những người khác đã giết được Sakamoto, thành công bảo vệ loài hoa thần kỳ trong hang động.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leung Kar-yan","avatar":""},{"name":"Xue Jiangtao","avatar":""},{"name":"Wang Zitong","avatar":""},{"name":"Li Binglei","avatar":""},{"name":"Wang Miao","avatar":""},{"name":"张郎","avatar":""},{"name":"马嘉苒","avatar":""},{"name":"王诗梦","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324240);
