INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuong-dong-thon-di-xa-co-su', 'Thượng Đồng Thôn: Dị Xà Cổ Sự', 'The Strange Snake Story in Shangtong Village', 'thượng đồng thôn: dị xà cổ sự the strange snake story in shangtong village leung kar-yan xue jiangtao wang zitong li binglei wang miao 张郎 马嘉苒 王诗梦 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-khong-thay-bong', 'Thiếu Niên Không Thấy Bóng', 'Lost in the Shadows', 'https://phimimg.com/upload/vod/20240607-1/7f45bfb3d4310dc5a46ed7756f06ac66.jpg', 'https://phimimg.com/upload/vod/20240607-1/1b15102761ccac7abbb22a779a6c43f2.jpg', '<p>Những năm 90 của thế kỷ trước, vào một đêm bão táp, trong một thị trấn nhỏ có tên Chiếu Dương, một thiếu niên bị truy sát một cách bí ẩn, không rõ sống chết. Hai thiếu niên khác cũng bị mất tích cùng cậu ta, bốc hơi khỏi thế gian. Ba năm sau, một trong số họ đột nhiên trở thành &quot;tay móc túi nhỏ&quot;, giả vờ mất trí nhớ về với gia đình. Sự thật đằng sau việc nhận thân thành công là gương vỡ lại lành hay đã sai càng thêm sai? Đằng sau gia đình đoàn tụ lại ẩn chứa bí mật và âm mưu giết người? Cảnh sát già đang điều tra một cách bí mật, sau một cuộc rượt đuổi, sự biến mất của hai thiếu niên khác cũng bắt đầu lộ ra dấu vết, sự thật về nhiều vụ mất tích, buôn người, ngộ sát, mưu sát dần dần được hé lộ. Khi bí ẩn được vén màn, cảnh sát cũng như &quot;thiếu niên mất tích&quot; đều thực hiện giải cứu hai chiều, tạo nên một câu chuyện về tình thân dưới lớp áo trinh thám bí ẩn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"張頌文","avatar":""},{"name":"Cheng Taishen","avatar":""},{"name":"Rong Zishan","avatar":""},{"name":"Yusi Chen","avatar":""},{"name":"Ke-Yu Guo","avatar":""},{"name":"Li Jian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324240);
