INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-quyt-co-ga', 'Nước Quýt Có Ga', 'Orange Soda', 'https://phimimg.com/upload/vod/20240611-1/e4d6d2f54bc6dc1c0d9f1258366b949c.jpg', 'https://phimimg.com/upload/vod/20240611-1/b4684dacec8e8c6bec5eb435fe592454.jpg', '<p>Châu Ngư - cô gái ở thị trấn nhỏ và Ngôn Từ - hotboy lạnh lùng của trường là thanh mai trúc mã. Họ và Trình Ngộ Châu - chàng thiếu gia nhà giàu đến thị trấn nhỏ chuẩn bị thi Đại học đã gặp gỡ và dần trở thành bạn bè. Tuy nhiên, số phận bất công đã vô tình khiến họ phải xa nhau, và tuổi thanh xuân của họ cũng kết thúc. Nhiều năm sau, cả ba gặp lại nhau tại quê nhà, tình yêu mà họ kìm nén bấy lâu nay bùng cháy lên dữ dội, câu chuyện thanh xuân tại thị trấn nhỏ lại được tái hiện...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Eleanor Lee","avatar":""},{"name":"Hollis","avatar":""},{"name":"He Changxi","avatar":""},{"name":"金沫汐","avatar":""},{"name":"Xiaotang Yao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324240);
