INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-vi-ham-nguc', 'Mỹ Vị Hầm Ngục', 'Delicious in Dungeon', 'https://phimimg.com/upload/vod/20240105-1/454fe3b7c0e0c5230ea5e399ee2afd6b.jpg', 'https://phimimg.com/upload/vod/20240105-1/c97887e70567869b0f3b2f56d0c1e376.jpg', '<p>Hầm ngục, rồng… và món quái vật hầm thơm ngon!? Các nhà thám hiểm đột nhập vào vương quốc trúng lời nguyền bị chôn vùi để cứu bạn mình và gây náo loạn trên đường đi.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kentaro Kumagai","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Asuna Tomari","avatar":""},{"name":"Hiroshi Naka","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Akira Miki","avatar":""},{"name":"Shinji Kawada","avatar":""},{"name":"Wataru Katoh","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Toru Nara","avatar":""},{"name":"Yuya Hirose","avatar":""},{"name":"Kei Kawamura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324240);
