INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-giau-mat-chuong-1', 'Sát Nhân Giấu Mặt: Chương 1', 'The Strangers: Chapter 1', 'https://phimimg.com/upload/vod/20240612-1/aff2cde1bd5da4fbb6e4b51ddc571d7d.jpg', 'https://phimimg.com/upload/vod/20240612-1/63d912a7500ee1bf37a8212b85e5ffe4.jpg', '<p>&quot;The Strangers: Chapter 1&quot; (2024) là một bộ phim kinh dị kể về câu chuyện của một cặp đôi trẻ, Maya và Ryan, bị mắc kẹt trong một thị trấn nhỏ sau khi xe của họ bị hỏng. Họ buộc phải qua đêm tại một căn nhà gỗ hẻo lánh. Khi màn đêm buông xuống, họ bị ba kẻ lạ mặt đeo mặt nạ tấn công mà không có lý do rõ ràng. Bộ phim tạo ra một bầu không khí căng thẳng và đầy sợ hãi với những pha hù dọa ám ảnh và không khoan nhượng.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Madelaine Petsch","avatar":""},{"name":"Froy Gutierrez","avatar":""},{"name":"Gabriel Basso","avatar":""},{"name":"Ema Horvath","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Rachel Shenton","avatar":""},{"name":"Ella Bruccoleri","avatar":""},{"name":"George Young","avatar":""},{"name":"Janis Ahern","avatar":""},{"name":"Pedro Leandro","avatar":""},{"name":"Ryan Brown","avatar":""},{"name":"Ben Cartwright","avatar":""},{"name":"Florian Clare","avatar":""},{"name":"Miles Yekinni","avatar":""},{"name":"Rebecka Johnston","avatar":""},{"name":"Stevee Davies","avatar":""},{"name":"Brooke Lena","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324240);
