INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-quan-hanh', 'Dữ Quân Hành', 'Walk With You', 'https://phimimg.com/upload/vod/20240612-1/19671a17375f03ea97142910de28671d.jpg', 'https://phimimg.com/upload/vod/20240612-1/2299bf108c33b70ef8dd2b4cfaa9838c.jpg', '<p>Vào ngày con gái Tô Oánh Oánh của Tô thị - trung thần thủ phụ nội các được gả cho Nhị hoàng tử Tạ Dư Hành, Tạ Dư Hành đã dẫn quân lính tàn sát toàn bộ Tô gia với lý do Tô thủ phụ theo địch phản quốc, nhờ đó được ngồi lên ghế Thái tử. Ba năm sau, Tô Oánh Oánh trở lại với ý định rửa sạch oan khuất cho cha, điều tra rõ ràng vụ án theo địch phản quốc. Cô đã bắt tay với Thất hoàng tử Tạ Ngật An, giả làm nha hoàn Tố Anh. Cả hai bắt đầu từ vụ án ngân phiếu giả, phát hiện ra vụ án này có liên quan đến Tô thủ phụ và Tạ Dư Hành nên tiến hành điều tra sâu hơn. Cả hai cũng từ quan hệ không hợp nhau ban đầu tiến đến nảy sinh tình cảm, họ đồng tâm hiệp lực, bất chấp nguy hiểm, đích thân tiếp cận người có liên quan đến vụ án ngân phiếu giả và từng bước đến gần với sự thật, cũng từ đó vạch trần âm mưu chiếm quyền, soán ngôi của Tạ Dư Hành. Thì ra Tạ Dư Hành không phải con cháu hoàng thất.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lin Zehui","avatar":""},{"name":"Xu Zhenzhen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324240);
