INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-cua-cac-chien-binh-terracotta', 'Bí ẩn của các chiến binh Terracotta', 'Mysteries of the Terracotta Warriors', 'https://phimimg.com/upload/vod/20240612-1/38115e3dbc81aeaf16e25595b008ef51.jpg', 'https://phimimg.com/upload/vod/20240612-1/abdd0837cdb0c0346046f94e303ae31f.jpg', '<p>Hàng ngàn chiến binh đất nung canh giữ lăng mộ của vị hoàng đế đầu tiên của Trung Quốc. Đây là câu chuyện của họ được kể thông qua các bằng chứng khảo cổ và màn tái hiện.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324240);
