INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-chay-va-truy-lung', 'Trốn Chạy Và Truy Lùng', 'ESCAPE AND TRACK', 'https://phimimg.com/upload/vod/20240611-1/31fce16499db447cd72162e055f53731.jpg', 'https://phimimg.com/upload/vod/20240611-1/48840b973b9ce9d7a6d5920be87d2ba6.jpg', '<p>Một vụ tai nạn giao thông nghiêm trọng đã xảy ra tại một thị trấn nhỏ ở miền Nam, kẻ gây ra vụ tai nạn đã tẩu thoát. Để nhanh chóng bắt giữ kẻ phạm tội lẩn trốn, đội cảnh sát giao thông đã nỗ lực hết mình. Điều bất ngờ là, trong quá trình truy bắt vụ tai nạn giao thông này, đã phát hiện ra một vụ án ma túy đã tồn tại năm năm. Kẻ gây tai nạn giao thông lại liên quan đến các tay buôn ma túy. Trong quá trình này, đã xảy ra nhiều biến cố gây rúng động. Cuối cùng, đội cảnh sát giao thông phối hợp với đội cảnh sát hình sự điều tra và bắt giữ thành công các tội phạm trong vụ án này, đưa chúng ra trước pháp luật.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai En","avatar":""},{"name":"Choenyi Tsering","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324240);
