INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-dao-lac-loi', 'Lưỡi Dao Lạc Lối', 'Hovering Blade', 'https://phimimg.com/upload/vod/20240611-1/0b2645e39fd24315478ec07c02afa76d.jpg', 'https://phimimg.com/upload/vod/20240611-1/2019f96c64465ee95fca28c4833c5679.jpg', '<p>Một người cha sống nương tựa vào con gái, sau khi con gái bị hai thiếu niên hành hạ đến chết, đã không ngần ngại bị cảnh sát truy nã để trả thù, trở thành một kẻ giết người chạy trốn khắp nơi.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Qian-Yuan","avatar":""},{"name":"Wang Jingchun","avatar":""},{"name":"Qi Xi","avatar":""},{"name":"Zhang Youhao","avatar":""},{"name":"Wang Tianchen","avatar":""},{"name":"Alan Aruna","avatar":""},{"name":"Zhou Zhengjie","avatar":""},{"name":"Shuang Wu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324241);
