INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-su-phu', 'Đinh Sư Phụ', 'Dinh Su Phu', 'https://phimimg.com/upload/vod/20240505-1/fae0413d40c681bd24b4eb7c43662884.jpg', 'https://phimimg.com/upload/vod/20240505-1/5314a84e2a02960c3c7cda0cbe931d24.jpg', '<p>Vì muốn lui về ở ẩn nên Đinh sư phụ hầu như chỉ bốc thuốc chữa bệnh cho bà con dân làng chứ không nhận dạy võ cho đệ tử. “Người tính không bằng trời tính”, trong một lần chữa bệnh cho người hàng xóm, ông bị vu oan là làm cho làm cho bệnh nhân bị liệt nên bị bắt phải bồi thường một số tiền khá lớn nếu muốn yên thân. Vì không muốn mất đi danh tiếng của “Đinh Gia Vọng Tộc” nên thầy Đinh đành chấp nhận An làm đệ tử, đổi lại một số tiền để bồi thường cho người hàng xóm. Từ đó, câu chuyện “tình tay ba” giữa An, Cúc và Mạnh – một thanh niên khá giả trong làng, bạn thân từ nhỏ với Cúc cùng những “tai họa” từ trên trời ập xuống nhà thầy Đinh khiến bộ phim thêm phần gay cấn, lôi cuốn và hấp dẫn, cùng những tình tiết hài hước, dở khóc dở cười. Tuy nhiên, điều khiến người xem tò mò và thắc mắc là sự thật ẩn đằng sau câu chuyện An bằng mọi cách bái thầy Đinh làm sư phụ. Những tai họa cũng không phải ngẫu nhiên mà đều có sự sắp đặt. Vậy sự thật đó là gì? Cùng chờ đón những diễn biến bất ngờ, kịch tính của bộ phim “Đinh Sư Phụ”.</p>', 'Full', 11, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Võ Đức","avatar":""},{"name":"Phạm Thị Tú Trinh","avatar":""},{"name":"Tô Nhật Diễm Trang","avatar":""},{"name":"Lê Minh Lợi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324241);
