INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dinh-su-phu', 'Đinh Sư Phụ', 'Dinh Su Phu', 'đinh sư phụ dinh su phu võ đức phạm thị tú trinh tô nhật diễm trang lê minh lợi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-thu-doc-dia', 'Tâm Thư Độc Địa', 'Wicked Little Letters', 'https://phimimg.com/upload/vod/20240609-1/d160c8c961e339921decdf714ad1bd69.jpg', 'https://phimimg.com/upload/vod/20240609-1/8095cf0142b04195ef975ecfdb516921.jpg', '<p>Bộ phim theo sau câu chuyện về hai người hàng xóm: một phụ nữ địa phương rất bảo thủ, Edith Swan và người nhập cư người Ireland năng động, Rose Gooding. Khi Edith và những người dân khác bắt đầu nhận được những lá thư độc ác đầy những lời nói tục tĩu, Rose ngay lập tức bị buộc tội. Những lá thư ẩn danh này gây ra sự hỗn loạn trên toàn nước Anh và một phiên tòa diễn ra. Tuy nhiên, khi phụ nữ trong thị trấn, dẫn đầu bởi Sĩ quan Cảnh sát Gladys Moss , bắt đầu điều tra vụ án, họ nghi ngờ rằng có điều gì đó không ổn và Rose có thể không phải là thủ phạm gây ra mọi chuyện.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Olivia Colman","avatar":""},{"name":"Jessie Buckley","avatar":""},{"name":"Anjana Vasan","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Gemma Jones","avatar":""},{"name":"Malachi Kirby","avatar":""},{"name":"Alisha Weir","avatar":""},{"name":"Joanna Scanlan","avatar":""},{"name":"Eileen Atkins","avatar":""},{"name":"Lolly Adefope","avatar":""},{"name":"Hugh Skinner","avatar":""},{"name":"Paul Chahidi","avatar":""},{"name":"Krishni Patel","avatar":""},{"name":"Grant Crookes","avatar":""},{"name":"Adam Treasure","avatar":""},{"name":"Jonny Sweet","avatar":""},{"name":"Tim Key","avatar":""},{"name":"Jason Watkins","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324241);
