INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-em-chay-ve-moi-thoi-khong', 'Khi Em Chạy Về Mọi Thời Không', 'Present, is Present', 'https://phimimg.com/upload/vod/20240524-1/9f82c43945bc5273440bcfa01d1f8eb7.jpg', 'https://phimimg.com/upload/vod/20240524-1/356561ea0a2e1bf5123c4474297566a8.jpg', '<p>Tuy rằng Nguyên Hạ lớn lên trong hoàn cảnh khó khăn, nhưng trái tim cô vẫn luôn giữ được sự ấm áp. Cô và Ngụy Tử Kỳ luôn hướng về nhau, bù đắp cho nhau. Vượt qua không gian thời gian, giữa vô vàn vũ trụ song song, họ không ngừng cứu lấy đối phương và dành tình cảm sâu đậm cho nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Fan Zhixin","avatar":""},{"name":"Tu Bing","avatar":""},{"name":"Wu Haoze","avatar":""},{"name":"劉賈璽","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324241);
