INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-toc-cuc-chien', 'Phong Tốc Cực Chiến', 'Lost But Win', 'https://phimimg.com/upload/vod/20240608-1/8f2b3de9ded5c56960aad3b320e0d960.jpg', 'https://phimimg.com/upload/vod/20240608-1/38cfab340c7e4c3c682e530bc0f5950b.jpg', '<p>Bốn người trong tất cả các cuộc đua, gần như mỗi trận đều nằm trong top bốn, họ thay phiên nhau xếp hạng, mỗi lần luôn có một người đứng bên cạnh bục trao giải tự thêm một cái bục nhỏ và khui sâm banh cho hạng tư. Trong đó, A Hoa và A Thường thường xuyên giành vị trí nhất và nhì, hai người ngang tài ngang sức, A Phong thì hoặc đứng thứ hai hoặc thứ ba, A Lạc thường xếp thứ tư, là người chậm nhất trong bốn người. Nhưng trong một cuộc đua nhỏ, A Lạc không may mất lái và qua đời. 15 năm sau, thời gian trôi qua, A Thường rời khỏi sòng bạc nơi anh đã đạt đến vị trí rất cao, quay lại đường đua và thấy A Hoa vẫn là tay đua đỉnh cao, được mọi người ngưỡng mộ. A Thường quyết định quay lại đường đua để thách đấu A Hoa, lấy lại vinh quang mà anh từng có. Sau đó, A Thường mới nhận ra rằng, anh đã thua A Hoa không chỉ là nửa vòng hay một vòng đua mà còn là 20 năm tuổi trẻ đã mãi mãi không thể quay lại.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Michael Tse","avatar":""},{"name":"Jason Chu Wing-Tong","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324241);
