INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-ly-sat-nhan', 'Nghịch Lý Sát Nhân', 'Paradox Effect', 'https://phimimg.com/upload/vod/20240607-1/13e9c46c6cad05059d1821375a82545e.jpg', 'https://phimimg.com/upload/vod/20240607-1/d2628091d205f22b692c2707e95c452f.jpg', '<p>Một người từng nghiện ngập chứng kiến một vụ giết người. Cô buộc phải hợp tác với kẻ giết người để cứu mạng con gái mình. Cô phải chiến đấu với thời gian, cảnh sát và thế giới tội phạm ngầm để cứu người duy nhất có ý nghĩa với cô.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Olga Kurylenko","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Oliver Trevena","avatar":""},{"name":"Alice Astons","avatar":""},{"name":"Talia Asseraf","avatar":""},{"name":"Meredith Mickelson","avatar":""},{"name":"Malich Cissé","avatar":""},{"name":"Lucia Zotti","avatar":""},{"name":"Paul Sampson","avatar":""},{"name":"Scot Ruggles","avatar":""},{"name":"Enjy Kiwan","avatar":""},{"name":"Andrea Garofalo","avatar":""},{"name":"Stella Addario","avatar":""},{"name":"Luke Cannella","avatar":""},{"name":"Steven Langa","avatar":""},{"name":"Roman Palacio","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324241);
