INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hitler-va-be-lu-quoc-xa-phan-xu-ac-quy', 'Hitler và bè lũ quốc xã: Phán xử ác quỷ', 'Hitler and the Nazis: Evil on Trial', 'https://phimimg.com/upload/vod/20240607-1/d8ad1b05d50504b5c9e1331a81a3b809.jpg', 'https://phimimg.com/upload/vod/20240607-1/f467bf2a8ab12ae73d3bb67eaebe6336.jpg', '<p>Loạt phim tài liệu hấp dẫn về hành trình trỗi dậy, cai trị và kết cục của Adolf Hitler và Đức Quốc xã từ trước Thế chiến II, thảm họa Holocaust đến các phiên tòa ở Nuremberg.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"William L. Shirer","avatar":""},{"name":"Károly Kozma","avatar":""},{"name":"Imre Csok","avatar":""},{"name":"Balázs Kató","avatar":""},{"name":"Soma Zámbori","avatar":""},{"name":"Barnabás Bergendi","avatar":""},{"name":"Domonkos Fellinger","avatar":""},{"name":"István Dankó","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324241);
