INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-gia-vo', 'Sát Thủ Giả Vờ', 'Hit Man', 'https://phimimg.com/upload/vod/20240607-1/648892f67c195d470bcb866df355c855.jpg', 'https://phimimg.com/upload/vod/20240607-1/53c183d40e038438e2e4f8dfc4f0ddf1.jpg', '<p>Vị giáo sư lịch lãm nọ đóng giả làm sát thủ giết thuê và bị cảnh sát nhắm đến, khơi dậy đủ kiểu rắc rối khi anh phải lòng một khách hàng tiềm năng.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Glen Powell","avatar":""},{"name":"Adria Arjona","avatar":""},{"name":"Austin Amelio","avatar":""},{"name":"Retta","avatar":""},{"name":"Sanjay Rao","avatar":""},{"name":"Molly Bernard","avatar":""},{"name":"Evan Holtzman","avatar":""},{"name":"Mike Markoff","avatar":""},{"name":"Ritchie Montgomery","avatar":""},{"name":"Kate Adair","avatar":""},{"name":"Beth Bartley","avatar":""},{"name":"Morgana Shaw","avatar":""},{"name":"Richard Robichaux","avatar":""},{"name":"Anthony Michael Frederick","avatar":""},{"name":"Jordan Salloum","avatar":""},{"name":"Jo-Ann Robinson","avatar":""},{"name":"Bryant Carr","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324241);
