INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-hay-yeu-duong-voi-ke-hai-huoc-nhu-toi', 'Xin Hãy Yêu Đương Với Kẻ Hài Hước Như Tôi', 'The Journey to Find True Love', 'https://phimimg.com/upload/vod/20240524-1/327c61c5e37e9fe107ff26aaf0007327.jpg', 'https://phimimg.com/upload/vod/20240524-1/2e8008c93242382cfe309eb7f7e5d82e.jpg', '<p>Chu Mạt, 32 tuổi, là phó chủ tịch một công ty phần mềm mạng xã hội. Trong mắt đồng nghiệp, cô là người phụ nữ độc lập và tự tin của thời đại; Trong mắt những người bạn thân, cô là một cô gái có lòng tự trọng rất cao; Trong mắt sếp, cô là một người có năng lực luôn khiến người ta phải đau đầu. Nhưng dường như đường tình của cô không được suôn sẻ lắm. Cô đã lần lượt gặp Giang Khởi, một chàng trai ngọt ngào kém mình nhiều tuổi, Vu Đại Chí, doanh nhân có phong cách như một người cha và Hạ Vũ, người yêu cũ lạnh lùng. Nhưng có lẽ tình yêu là như thế, gặp đúng người nhưng sai thời điểm, đúng thời điểm thì lại gặp sai người. Sau những vấp ngã, cô vẫn thất bại trên chiến trường tình yêu và cuộc sống. Tình yêu có cần được hôn nhân bảo vệ? Yêu một người không phải vì mục đích kết hôn có đúng không? Rốt cuộc tại sao phải kết hôn? Có thể không kết hôn không? Tình yêu có thực sự không thể kiểm soát được? Dù lúc nào cũng phải vượt mọi chông gai nhưng cô vẫn muốn tìm ra câu trả lời.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Haoming","avatar":""},{"name":"Swin","avatar":""},{"name":"Zhu Zijie","avatar":""},{"name":"ROCK","avatar":""},{"name":"Zhao Xue","avatar":""},{"name":"Bboy Keven","avatar":""},{"name":"Guan Xiangyun","avatar":""},{"name":"Shi Yanan","avatar":""},{"name":"Zhao Xilin","avatar":""},{"name":"Li Fankai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
