INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-hay-yeu-duong-voi-ke-hai-huoc-nhu-toi', 'Xin Hãy Yêu Đương Với Kẻ Hài Hước Như Tôi', 'The Journey to Find True Love', 'xin hãy yêu đương với kẻ hài hước như tôi the journey to find true love chen haoming swin zhu zijie rock zhao xue bboy keven guan xiangyun shi yanan zhao xilin li fankai ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tra-tinh-yeu', 'Đồi Trà Tình Yêu', 'Love in the Tea Garden', 'https://phimimg.com/upload/vod/20240529-1/530c9e69fd1d5814c700e0883b365a15.jpg', 'https://phimimg.com/upload/vod/20240529-1/9e8b33e1bae67eb2bdc05de9f3599e26.jpg', '<p>Trong một lần về vùng nông thôn khảo sát, thiên kim tập đoàn Diệp thị, Diệp Tịch Nhan (do Thích Nghiên Địch thủ vai) gặp tai nạn xe, được Lục Minh Vũ (do Tiêu Tử Mặc thủ vai) – chủ đồi trà thôn Cổ Yến, tình cờ đi ngang qua cứu giúp. Để tránh nguy hiểm, Diệp Tịch Nhan giả vờ mất trí nhớ nhưng lại bị nhận nhầm thành một cô thôn nữ Tú Phân, còn vô tình đính hôn với Lục Minh Vũ, cuộc sống vui vẻ ngọt ngào cũng bắt đầu từ đây… Tuy nhiên, sự xuất hiện của cậu ấm Thôi Tử Hào của tập đoàn Thôi thị (do Cao Khải thủ vai) đã phá vỡ cuộc sống bình yên của hai người. Thân phận thôn nữ của Diệp Tịch Nhan bị nghi ngờ, quá khứ từng làm vệ sĩ của Lục Minh Vũ cũng dần bại lộ. Hai người đều có tâm sự riêng, sinh ra hiểu lầm chồng chất. Âm mưu nhắm vào đồi trà và tập đoàn Diệp thị cũng dần lộ rõ. Liệu cả hai có thể cùng nhau đối mặt với nguy cơ, kiên định gìn giữ tình yêu đích thực của đời mình?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qi Yandi","avatar":""},{"name":"Eric Hsiao","avatar":""},{"name":"Kai Gao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324241);
