INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chap-but', 'Chấp Bút', 'Fortune Writer', 'https://phimimg.com/upload/vod/20240524-1/9907b58a8f87a0902792758f322a1f81.jpg', 'https://phimimg.com/upload/vod/20240524-1/a4d01de95ae71cb96e743e7596503e56.jpg', '<p>Chấp Bút kể về Tô Vân Khởi, đích nữ của Tể tướng, vô tình phát hiện mình là nữ pháo bia trong &quot;Sách định mệnh&quot;, bị ghi vào &quot;Sách định mệnh&quot;, không thể thay đổi. Đối mặt với số phận bất công, Tô Vân Khởi lựa chọn phản kháng, cô muốn dùng &quot;cuốn sách định mệnh&quot; để thay đổi vận mệnh của mình trái với ý trời, tìm kiếm con người thật của mình và có được tình yêu đích thực!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Muchen","avatar":""},{"name":"Ye Shengjia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
