INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-chuyen-can-khon', 'Đấu Chuyển Càn Khôn', 'Revolutionize The World', 'https://phimimg.com/upload/vod/20240606-1/1003f7289fbcee2a17a84b83c01dbb38.jpg', 'https://phimimg.com/upload/vod/20240606-1/d4262c70ea5b71122ee193ceb39db39f.jpg', '<p>Câu chuyện kể về nhân vật chính Vân Thư, vì chính nghĩa của thế gian mà một lòng muốn tìm ra tung tích của Hầu Vương Đấu Chiến Thắng Phật, nhằm lật đổ sự thống trị tàn bạo của Hỗn Thế Ngoan Hầu Diễm Nhĩ. Trong quá trình tìm kiếm, anh dần phát hiện ra sự mất tích của Đấu Chiến Thắng Phật có liên quan đến âm mưu của Ma Tôn muốn phá vỡ phong ấn và tái kiểm soát Tam giới, và Diễm Nhĩ cũng chỉ là một con tốt bị Ma Tôn lợi dụng. Cuối cùng, dưới sự cảm hóa và giúp đỡ của Thần Nữ A Hà, Vân Thư vượt qua chính mình, ngăn chặn việc mở cánh cửa phong ấn và trở thành anh hùng thực sự.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Pakho Chau","avatar":""},{"name":"Alex Fong Lik-Sun","avatar":""},{"name":"Andy Chen","avatar":""},{"name":"He Hua","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"Zhu Ziyue","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324241);
