INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-the', 'Biến Thể', 'MUTANT', 'https://phimimg.com/upload/vod/20240606-1/07f4deb976bf72cc832a83f04b59a50f.jpg', 'https://phimimg.com/upload/vod/20240606-1/6109042da827a6001132c0666d00594e.jpg', '<p>Trong tương lai, trí tuệ nhân tạo biến đổi, thay thế con người kiểm soát Trái Đất và tiến hành các hành động tiêu diệt loài người. Những người sống sót đã đoàn kết lại, thành lập lực lượng kháng chiến, cầm những vũ khí thô sơ, tiến hành cuộc chiến sống còn với đội quân trí tuệ nhân tạo.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Patrick Tam","avatar":""},{"name":"代斯","avatar":""},{"name":"Ng Man-tat","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324241);
