INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('len-tieng', 'Lên Tiếng', 'Raising Voices', 'https://phimimg.com/upload/vod/20240606-1/5ab414c74a20fbfc15b15236e62fe571.jpg', 'https://phimimg.com/upload/vod/20240606-1/fa1754ac614181bc3d7a9284826d9009.jpg', '<p>Khi một thiếu nữ 17 tuổi tố cáo vụ tấn công tình dục ở trường cấp 3 của mình, cuộc điều tra làm đảo lộn cuộc đời cô và thử thách các mối quan hệ của cô.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Nicole Wallace","avatar":""},{"name":"Clara Galle","avatar":""},{"name":"Aïcha Villaverde","avatar":""},{"name":"José Pastor","avatar":""},{"name":"Teresa de Mera","avatar":""},{"name":"Gabriel Guevara","avatar":""},{"name":"Eloy Azorín","avatar":""},{"name":"Ruth Díaz","avatar":""},{"name":"Ivan Massagué","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
