INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-gia-cua-thua-ke', 'Cái Giá Của Thừa Kế', 'The Price of Nonna''s Inheritance', 'https://phimimg.com/upload/vod/20240606-1/685e47fad1ea6b2072d40aa0b0d0972a.jpg', 'https://phimimg.com/upload/vod/20240606-1/e12faba97891a2154f2c9e442d2a6e38.jpg', '<p>Khi một người bà phải lòng một người theo đuổi táo bạo có những ý định đáng ngờ, gia đình bà nảy ra một kế hoạch bí mật để bảo vệ tính mạng của bà... và cả tài sản thừa kế của họ.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Christian De Sica","avatar":""},{"name":"Angela Finocchiaro","avatar":""},{"name":"Claudio Colica","avatar":""},{"name":"Dharma Mangia Woods","avatar":""},{"name":"Darko Peric","avatar":""},{"name":"Antonino Bruschetta","avatar":""},{"name":"Fioretta Mari","avatar":""},{"name":"Irma Carolina Di Monte","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324241);
