INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-ngoc-khanh-tam', 'Nam Ngọc Khanh Tâm', 'Practice Daughter', 'https://phimimg.com/upload/vod/20240520-1/59f4a45e7e1006e238e793cd777dfbc3.jpg', 'https://phimimg.com/upload/vod/20240520-1/24ebfc49f04a3001fa39351880477a37.jpg', '<p>Thiên kim cao quý của thừa tướng, Mai Ngọc Phiến và thần trộm Tiểu Đậu Tử là hai cô gái mang hai tính cách và thân phận khác xa nhau, đã tạo nên bao câu chuyện dở khóc dở cười trong quá trình trao đổi cuộc đời cho nhau. Hãy xem thiên kim thừa tướng Mai Ngọc Phiến sẽ làm thế nào để tán đổ thái tử Nam Cung Diệu của nước Tịch Tây bằng sức hút trái ngược của thần trộm bá đạo. Và liệu thái tử Nam Cung Diệu lạnh lùng lại còn mắc chứng rối loạn ám ảnh cưỡng chế có thể phá vỡ lời tiên đoán của quốc sư Bạch Diệp rằng nước Tịch Tây sẽ bị hủy diệt bởi tình yêu của thái tử, cuối cùng không phụ nước nhà chẳng phụ nàng hay không?&nbsp;</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Hạo Minh","avatar":""},{"name":"張淼怡","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
