INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-tu-than-ky', 'Tiểu Tử Thần Kỳ', 'Broken Trust', 'https://phimimg.com/upload/vod/20240602-1/390c18c1ce5daf4f6f31ee1998a9a2de.jpg', 'https://phimimg.com/upload/vod/20240602-1/bb8c2786e9284f824fd8d0940e903255.jpg', '<p>&quot;Thương gia Tiền Đại Hải (do Trịnh Tắc Sĩ đóng) dù ở công ty hay ở nhà, đều rất độc đoán. Nhưng “tức nước thì vỡ bờ”, chính tính cách đó càng lúc càng đẩy ông ra xa các mối quan hệ thân thiết: từ con trai cả Tiền Kế Lai (do Tào Vĩnh Liêm đóng), con gái út được “cưng như trứng mỏng” – Tiền Hữu Phương (do Phó Gia Lợi đóng) đến hồng nhan tri kỷ Hồng Mai Khôi (do Phàn Diệc Mẫn đóng). Bất mãn, nghi hoặc giữa họ lên đến đỉnh điểm khi ông Hải đột nhiên bị bắt cóc. Rốt cuộc, vụ bắt cóc là do ai làm? Sau tất cả, mối quan hệ giữa ông Hải với người thân sẽ thế nào?&quot;</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Edwin Siu","avatar":""},{"name":"Amy Fan Yik-Man","avatar":""},{"name":"Archie Sin","avatar":""},{"name":"Yuki Law Yuk Yee","avatar":""},{"name":"Raymond Cho Wing-Lim","avatar":""},{"name":"Felix Ng","avatar":""},{"name":"Kelly Fu","avatar":""},{"name":"Yuki Law Yuk Yee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324241);
