INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('irenas-vow', 'Irena''s Vow', 'Irena''s Vow', 'https://phimimg.com/upload/vod/20240603-1/1f23854e5693c2bee3d25dc0b10d9c50.jpg', 'https://phimimg.com/upload/vod/20240603-1/9625449e7c340cafda33444ef7245d6a.jpg', '<p>Irena Gut, 19 tuổi, được thăng chức làm quản gia tại nhà của một sĩ quan Đức Quốc xã rất được kính trọng ở Ba Lan khi cô phát hiện ra rằng khu ổ chuột Do Thái sắp bị thanh lý. Quyết tâm giúp đỡ 12 công nhân Do Thái, cô quyết định cho họ trú ẩn ở nơi an toàn nhất mà cô có thể nghĩ đến - tầng hầm nhà của Thiếu tá Đức. Trong tám tháng tiếp theo, Irena sử dụng sự hóm hỉnh, hài hước và lòng dũng cảm to lớn của mình để che giấu bạn bè lâu nhất có thể.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Sophie Nélisse","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Andrzej Seweryn","avatar":""},{"name":"Maciej Nawrocki","avatar":""},{"name":"Sharon Azrieli","avatar":""},{"name":"Eliza Rycembel","avatar":""},{"name":"Aleksandar Milićević","avatar":""},{"name":"Agata Turkot","avatar":""},{"name":"Filip Kosior","avatar":""},{"name":"Krzysztof Szczepaniak","avatar":""},{"name":"Irena Melcer","avatar":""},{"name":"Eryk Kulm jr","avatar":""},{"name":"Zuzanna Puławska","avatar":""},{"name":"Tomasz Tyndyk","avatar":""},{"name":"Julia Kostow","avatar":""},{"name":"Rafał Mohr","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
