INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('club-friday-season-16-tinh-yeu-gioi-tre', 'Club Friday Season 16: Tình Yêu Giới Trẻ', 'Club Friday Season 16: Young Love', 'https://phimimg.com/upload/vod/20240603-1/49484536ca22c4300546c9735e57981f.jpg', 'https://phimimg.com/upload/vod/20240603-1/60fe105dbc5042986572f06b2dd522cd.jpg', '<p>Tình Yêu Giới Trẻ là vở kịch tình yêu giữa Monet và Sky. Để ngăn bố bỏ mẹ, cô học trò Monet không nghĩ ra được cách nào khác ngoài việc giả vờ yêu sớm để bố quan tâm đến mình hơn và từ bỏ ý định ly hôn. Cậu bạn học Sky chính là người được Monet thuê làm bạn trai hờ. Dù ban đầu chỉ là yêu giả, Monet lại dần dà nảy sinh tình cảm thật sự với Sky. Nhưng liệu Sky có yêu cô không? Hay anh chỉ xem cô như một &quot;khách hàng&quot;?</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Belle Jiratchaya Kittavornsakul","avatar":""},{"name":"Aton Thanakorn Techawicha","avatar":""},{"name":"Tiger Tanawat Hudchaleelaha","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
