INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-hoa', 'Sinh Hóa', 'Bionic', 'https://phimimg.com/upload/vod/20240530-1/fec0dcc683f8308ec3e43cbd9ef2ccf0.jpg', 'https://phimimg.com/upload/vod/20240530-1/d1c0cad38e05e3cb2ae07fb5b08a84c9.jpg', '<p>Bộ phim lấy bối cảnh tương lai, khi công nghệ robot đã làm thay đổi hoàn toàn thể thao, biến các vận động viên Paralympic trở thành những siêu sao mới.Hai chị em Gabi và Maria, những người cạnh tranh trong môn nhảy xa với sự hỗ trợ của các cấy ghép sinh hóa. Tuy nhiên, sự cạnh tranh này không chỉ dừng lại ở sân thi đấu mà còn lan sang thế giới tội phạm và bạo lực, đưa ra nhiều câu hỏi về đạo đức và tác động của công nghệ đối với thể thao và cuộc sống</p>', 'Full', 1, 'single', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Jessica Córes","avatar":""},{"name":"Bruno Gagliasso","avatar":""},{"name":"Gabz","avatar":""},{"name":"Christian Malheiros","avatar":""},{"name":"Nill Marcondes","avatar":""},{"name":"Guta Ruiz","avatar":""},{"name":"Miguel Nader","avatar":""},{"name":"Márcio Fecher","avatar":""},{"name":"Nicole Cordery","avatar":""},{"name":"Emilly Nayara","avatar":""},{"name":"Miguel Falabella","avatar":""},{"name":"Klebber Toledo","avatar":""},{"name":"Paulo Vilhena","avatar":""},{"name":"Danton Mello","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324241);
