INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-tan-cua-de-quoc', 'Ngày Tàn Của Đế Quốc', 'Civil War', 'https://phimimg.com/upload/vod/20240530-1/39dd6c78bd6891dd7977a7b121c4ed3d.jpg', 'https://phimimg.com/upload/vod/20240530-1/5767ee3e5ac9e15046426d3ee3789eae.jpg', '<p>Cuộc hành trình xuyên nước Mỹ trong một tương lai đen tối, theo chân một nhóm nhà báo gắn bó cùng quân đội chạy đua với thời gian để đến Washington D.C. trước khi các phe phái nổi dậy tràn vào Nhà Trắng. (thằng ngu nào dịch là Ngày tàn đế quốc vậy?)</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Anh', 1, '[{"name":"Kirsten Dunst","avatar":""},{"name":"Wagner Moura","avatar":""},{"name":"Cailee Spaeny","avatar":""},{"name":"Stephen McKinley Henderson","avatar":""},{"name":"Nelson Lee","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Jefferson White","avatar":""},{"name":"Evan Lai","avatar":""},{"name":"Vince Pisani","avatar":""},{"name":"Justin James Boykin","avatar":""},{"name":"Jess Matney","avatar":""},{"name":"Greg Hill","avatar":""},{"name":"Edmund Donovan","avatar":""},{"name":"Sonoya Mizuno","avatar":""},{"name":"Tim James","avatar":""},{"name":"Simeon Freeman","avatar":""},{"name":"James Yaegas","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
