INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-bai-ma-quy', 'Lá Bài Ma Quỷ', 'Tarot', 'https://phimimg.com/upload/vod/20240530-1/97ab7fffc93b354b3b8c1b51a163ee2a.jpg', 'https://phimimg.com/upload/vod/20240530-1/d8d8f3cfdd69c63a245f79e2ea5c01d7.jpg', '<p>Phim xoay quanh một nhóm bạn trẻ bất chấp những lời cảnh báo, đùa cợt và phá vỡ quy tắc thiêng liêng của bộ bài Tarot. Từ đây, bi kịch ập đến, từng người trong nhóm lần lượt đối mặt với số phận nghiệt ngã, bị lôi vào trò chơi chết chóc. Họ phải tìm cách hóa giải lời nguyền trước khi quá muộn, trước khi bóng tối nuốt chửng tất cả. Liệu tình bạn và lòng dũng cảm có đủ sức giúp họ chiến thắng thế lực siêu nhiên đầy thù hận, hay tất cả sẽ phải trả giá cho sự ngạo mạn của mình?</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Harriet Slater","avatar":""},{"name":"Adain Bradley","avatar":""},{"name":"Avantika","avatar":""},{"name":"Jacob Batalon","avatar":""},{"name":"Humberly Gonzalez","avatar":""},{"name":"Wolfgang Novogratz","avatar":""},{"name":"Larsen Thompson","avatar":""},{"name":"Olwen Fouéré","avatar":""},{"name":"Sunčica Milanović","avatar":""},{"name":"Alan Wells","avatar":""},{"name":"Joss Carter","avatar":""},{"name":"James Swanton","avatar":""},{"name":"Staša Nikolić","avatar":""},{"name":"Anna Halberg","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324241);
