INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-van-chuyen', 'Kẻ Vận Chuyển', 'The Courier', 'https://phimimg.com/upload/vod/20240530-1/83b9e4b4c83cea8368581a33eff08838.jpg', 'https://phimimg.com/upload/vod/20240530-1/f7849c329aadd27a757ed949518d9336.jpg', '<p>Phim xoay quanh Iván Márquez, một chàng trai trẻ làm công việc đỗ xe tại Madrid. Khát khao thoát khỏi cuộc sống bình thường, Iván tham gia vào một tổ chức rửa tiền quốc tế. Anh nhanh chóng leo lên vị trí quan trọng trong tổ chức, vận chuyển tiền mặt qua các thành phố lớn như Brussels và Geneva. Mối quan hệ phức tạp của anh với Leticia, con gái của ông trùm Escamez, càng khiến tình hình thêm căng thẳng. Cuối cùng, Iván bị cảnh sát bắt giữ và phải đối mặt với hậu quả nặng nề từ những hành động của mình</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Arón Piper","avatar":""},{"name":"María Pedraza","avatar":""},{"name":"Luis Tosar","avatar":""},{"name":"Laura Sépul","avatar":""},{"name":"Nourdin Batán","avatar":""},{"name":"José Manuel Poga","avatar":""},{"name":"Luis Zahera","avatar":""},{"name":"Manuel Gancedo","avatar":""},{"name":"Antonio Buíl","avatar":""},{"name":"Lukas Olszewski","avatar":""},{"name":"Alberto Jo Lee","avatar":""},{"name":"Stefan Weinert","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
