INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('geek-girl', 'Geek Girl', 'Geek Girl', 'https://phimimg.com/upload/vod/20240531-1/3ef8f9fee004df60f9837101f7c4da96.jpg', 'https://phimimg.com/upload/vod/20240531-1/a523daf58097942bc7d6222439223bbc.jpg', '<p>Thiếu nữ vụng về Harriet luôn muốn hòa nhập. Rồi cô bỗng được một quản lý người mẫu hàng đầu ở London săn đón và biết rằng một số người sinh ra là để nổi bật.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Emily Carey","avatar":""},{"name":"Tim Downie","avatar":""},{"name":"Sarah Parish","avatar":""},{"name":"Jemima Rooper","avatar":""},{"name":"Liam Woodrum","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324241);
