INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('eric', 'Eric', 'Eric', 'https://phimimg.com/upload/vod/20240531-1/994d9fd3f5f24774edf6c02f6cd3766b.jpg', 'https://phimimg.com/upload/vod/20240531-1/523a4c736af07bffde6bfb793e8e7581.jpg', '<p>Một người bố tuyệt vọng và một cảnh sát ngoan cường chiến đấu với ác quỷ trong họ trên đường phố New York những năm 1980 khi anh tìm kiếm cậu con trai chín tuổi đang mất tích.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Benedict Cumberbatch","avatar":""},{"name":"Gaby Hoffmann","avatar":""},{"name":"McKinley Belcher III","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Clarke Peters","avatar":""},{"name":"Ivan Morris Howe","avatar":""},{"name":"Phoebe Nicholls","avatar":""},{"name":"David Denman","avatar":""},{"name":"Bamar Kane","avatar":""},{"name":"Adepero Odyue","avatar":""},{"name":"Alexis Molnar","avatar":""},{"name":"Roberta Colindrez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324241);
