INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('eric', 'Eric', 'Eric', 'eric eric benedict cumberbatch gaby hoffmann mckinley belcher iii dan fogler clarke peters ivan morris howe phoebe nicholls david denman bamar kane adepero odyue alexis molnar roberta colindrez ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-trung-cu-tam-tu', 'Vân Trung Cư Tam Tử', 'The Mirage House in the Clouds', 'https://phimimg.com/upload/vod/20240427-1/5cf1df13059e458fbb95db4e0730f7b4.jpg', 'https://phimimg.com/upload/vod/20240427-1/7ee087d77a7e9996218686d1ab4e6a73.jpg', '<p>Thần tiên, yêu ma và phàm nhân cùng tồn tại trong thời cổ đại, tiên nhân Trường Nhĩ và đồ đệ Tiểu Lương sống ẩn dật trong Hang Phù Quang, cuộc sống yên bình bị Yêu Vương Đại Bằng theo dõi mà xáo trộn. Tiểu Lương nhút nhát bị ép phải cùng với học giả thông minh lẫn mượt mà Giang Thành, cùng với vị sư sĩ quả cảm và kiên định Trùng Minh, bắt đầu một chuyến đi tìm kiếm nơi ở của tiên nhân huyền thoại, Điện Trung Cư. Trong hành trình, ba người sẽ đối mặt với nhiều khó khăn, trải qua những phút giây lãng mạn đầy xúc động, trải qua thử thách của tình bạn và sinh tử. Đồng thời, một âm mưu lớn liên quan đến sức mạnh tam giới đang dần hé mở trước họ... Bộ phim hoạt hình &quot;Vân Trung Cư Tam Tử&quot; hướng tới việc tái hiện phong cách độc đáo của trường phái hoạt họa Trung Quốc bằng công nghệ CG, mang đến một truyền thuyết hấp dẫn về tuổi trẻ, giang hồ và trừ yêu.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jinwen Chen","avatar":""},{"name":"Liu Mingyue","avatar":""},{"name":"Lanling Li","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324241);
