INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-hanh-kien', 'Thiên Hành Kiện', 'Heroes', 'https://phimimg.com/upload/vod/20240509-1/412864021483356bbba57d1b81306b0e.jpg', 'https://phimimg.com/upload/vod/20240509-1/2110dc53adddf934c6c94606aaddd247.jpg', '<p>Bộ phim kể về những năm cuối thời Thanh, một nhóm người với thân phận khác biệt vì một cơ duyên mà bị cuốn vào hành trình tìm kiếm báu vật kì lạ, và họ dần kiên định với lý tưởng cứu nước của mình trong làn sóng lịch sử rộng lớn cuộn trào.&nbsp;</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qin Junjie","avatar":""},{"name":"Liu Yuning","avatar":""},{"name":"Maggie Huang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
