INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-dao-hoan-truyen-ky-tay-thien-thang-canh', 'Tạ Dao Hoàn Truyền Kỳ: Tây Thiên Thắng Cảnh', 'The Legend of Xie Yaohuan', 'https://phimimg.com/upload/vod/20240529-1/bec4b43c575a8a4a7e24c5db5d5f66db.jpg', 'https://phimimg.com/upload/vod/20240529-1/fecdf62558b0d222c82a4903bb381b4e.jpg', '<p>Dựa trên bối cảnh thời đại của Cửu châu thịnh thế, câu chuyện kể về những vụ án kỳ bí xảy ra tại hoàng cung trong dịp sinh nhật của Nữ Hoàng, với sự xuất hiện bất ngờ của một vùng đất bí ẩn từ phương Tây. Nữ quan triều đình Tạ Dao Hoàn cùng với tiểu vương gia Hạ Hoằng Lực đã vượt qua những khó khăn, giải mê cung, và giải mã bí ẩn để bảo vệ Nữ Hoàng, hoàng cung và nhân dân.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kaderya","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324241);
