INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thi-mang', 'Kẻ Thí Mạng', 'PUPPET', 'https://phimimg.com/upload/vod/20240529-1/04ac5bf8f12ad0f40a7c92a2739ef037.jpg', 'https://phimimg.com/upload/vod/20240529-1/85b1b1a7465209339355a84aae75fd18.jpg', '<p>Vào năm Vạn Lịch thời nhà Minh, trong quá trình điều tra vụ mất cắp hỏa khí, Đinh Tiễn của Bắc Trấn Phủ Ti có thê tử là Tô Thanh bị kẻ cướp bắt cóc. Đinh Tiễn bị ép phải ám sát tam hoàng tử, thê tử thì bị chết oan, còn bản thân Đinh Tiễn cũng trở thành kẻ phản nghịch. Để báo thù và tìm ra sự thật, cùng với bạn tốt Lý Tiến Trung từng bước vén màn bí mật, lại không ngờ rằng bản thân chỉ là một quân cờ đáng thương...</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"彭禺厶","avatar":""},{"name":"He Shengming","avatar":""},{"name":"Liu Jingyi","avatar":""},{"name":"He Qiwei","avatar":""},{"name":"Zhang Xiaojun","avatar":""},{"name":"Zhao Xiaodong","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324241);
