INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-giac-ai-tinh', 'Tam Giác Ái Tình', 'Restu', 'https://phimimg.com/upload/vod/20240427-1/3f50e961ecbf219cdab6a8060dfaf1e9.jpg', 'https://phimimg.com/upload/vod/20240427-1/6342b36200c35e3038d9c8031631f943.jpg', '<p>Ông bố đơn thân Razak quyết định bắt đầu hẹn hò lại, tìm kiếm một người vợ và người mẹ phù hợp cho mình và con gái Amy. Khi anh phải lựa chọn giữa ba người phụ nữ đang theo đuổi mình, anh nhanh chóng nhận ra mình đã rơi vào một tình huống khó xử. Một người là bạn thân của vợ quá cố, một người là đồng nghiệp quan tâm đến anh, và người kia là một người có ảnh hưởng giúp công ty anh đạt được nhiều danh tiếng hơn. Quan trọng nhất là lựa chọn của anh cần phải được Amy chấp thuận, và Amy thì không muốn chào đón thành viên mới gia nhập gia đình lắm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Remy Ishak","avatar":""},{"name":"Puteri Rafasya","avatar":""},{"name":"Siti Elizad","avatar":""},{"name":"Wanna Ali","avatar":""},{"name":"Elizabeth Tan","avatar":""},{"name":"Yusuf Bahrin","avatar":""},{"name":"Ahirine Ahirudin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324241);
