INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chanh-thanh-tra-1958', 'Chánh Thanh Tra 1958', 'Chief Detective 1958', 'https://phimimg.com/upload/vod/20240425-1/5325906facb298e1118552f73ff90ca2.jpg', 'https://phimimg.com/upload/vod/20240425-1/9331ea34eecee3cf943444ca3f50f3cc.jpg', '<p>Phim kể về hành trình của thám tử Park Young-han (Lee Je-hoon), người nổi tiếng với tỷ lệ bắt giữ tội phạm cao, đặc biệt là những tên trộm vặt. Cùng với ba đồng nghiệp độc đáo, anh lập thành một đội để chống lại sự tham nhũng và bất công, trở thành &quot;thám tử của nhân dân&quot;.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Je-hoon","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Seo Eun-soo","avatar":""},{"name":"Choi Woo-sung","avatar":""},{"name":"Yoon Hyun-soo","avatar":""},{"name":"Chung Su-bin","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Song Wook-kyung","avatar":""},{"name":"Ryu Yeon-seok","avatar":""},{"name":"Jo Han-joon","avatar":""},{"name":"Nam Hyun-woo","avatar":""},{"name":"Ko Sang-ho","avatar":""},{"name":"Oh Yong","avatar":""},{"name":"Kim Young-sung","avatar":""},{"name":"Kang In-kwon","avatar":""},{"name":"Park Joung-hyuck","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324241);
