INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-tinh-vien', 'Cảm Tình Viên', 'The Sympathizer', 'https://phimimg.com/upload/vod/20240417-1/a970d0b1555517556b0fb16fa6a06798.jpg', 'https://phimimg.com/upload/vod/20240417-1/4e9b12967b5f47a8e647cc2f3b9cca1f.jpg', '<p>Một bộ phim về gián điệp và châm biếm đa văn hóa về cuộc đấu tranh của một điệp viên cộng sản nửa Pháp, nửa Việt Nam trong những ngày cuối cùng của Chiến tranh Việt Nam và sau đó là cuộc lưu đày của anh ta ở Hoa Kỳ.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hoa Xuande","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Fred Nguyen Khan","avatar":""},{"name":"Toan Le","avatar":""},{"name":"Alan Trong","avatar":""},{"name":"Vy Le","avatar":""},{"name":"Nguyễn Cao Kỳ Duyên","avatar":""},{"name":"Duy Nguyễn","avatar":""},{"name":"Phanxinê","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
