INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-biet-cot-truyen-cung-khong-sao', 'Không Biết Cốt Truyện Cũng Không Sao', 'A Lucid Dream', 'https://phimimg.com/upload/vod/20240524-1/6e53ded6d8c72ea27dd7912792d63459.jpg', 'https://phimimg.com/upload/vod/20240524-1/f4e5d5bd8e8c2040943544d95a3b4cd5.jpg', '<p>Zhang Yimeng, người sống ở thời hiện đại, tin chắc rằng cô là một công chúa du hành xuyên thời gian từ Vương quốc Tây, và đang thử mọi cách có thể để quay về quá khứ. Một cơn choáng váng bất ngờ thực sự đã đưa cô trở lại đất nước Xi cổ xưa, nơi xung quanh vừa quen mà lại vừa xa lạ. Tuy nhiên, đây thực chất là một phương pháp điều trị do cha cô và bác sĩ tâm thần Jing Cheng lên kế hoạch cho cô! Cái nào đúng hay sai, mọi thứ đều đầy sự đảo ngược!</p>', 'Tập 18', 18, 'series', 'ongoing', 13, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yajia Wang","avatar":""},{"name":"Cheng Yufen","avatar":""},{"name":"Yu Kaining","avatar":""},{"name":"Cheng Qimeng","avatar":""},{"name":"Xinyue Lou","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
