INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-thi-co-sat', 'Cương Thi Cổ Sát', 'The Zombies', 'https://phimimg.com/upload/vod/20240524-1/68836ce9610d21997858303ff1f2d452.jpg', 'https://phimimg.com/upload/vod/20240524-1/5de44ab1d20b3b6199300b585b18883d.jpg', '<p>Trong thời kỳ cuối cùng của triều đại Thanh, quân đội Anh xâm lược Quảng Châu. Và vào thời điểm này, tại một ngôi chùa cổ ở Tam Viên Lí, người ta đã chứng kiến sự xuất hiện kinh hoàng của xác sống tấn công con người, khiến toàn thành hoang mang. Các vụ tấn công liên tục của xác sống cũng ảnh hưởng đến việc nhập khẩu thuốc phiện, khiến cho lãnh đạo quân đội Anh, Roberts, tức giận. Để loại bỏ nguy cơ tiềm ẩn, Roberts dẫn đầu quân đội Anh tiêu diệt xác sống, nhưng trên đường đến ngôi chùa cổ, họ đã bị bầy xác sống tấn công dữ dội, làm cho hơn một nửa quân lính Anh thương vong. Roberts đã ra lệnh cho vị thái úy của Quảng Châu, Vương Bình Chi, dẫn đầu quân đội Trung Quốc để tiêu diệt xác sống. Trong tình hình sợ hãi và bất lực, Vương Bình Chi không còn lựa chọn nào khác ngoài việc mời thực tập tuần kiểm bị cắt chức Viên Sĩ Thành trở lại. Để đảm bảo an toàn cho dân chúng thành phố Quảng Châu, Viên Sĩ Thành chỉ huy thầy cúng tiến vào ngôi chùa cổ, nhưng họ đã phát hiện ra một bí mật khác...</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Du Yiheng","avatar":""},{"name":"林昕宜","avatar":""},{"name":"Ge Shuai","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Lui Hei","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Dmitriy Shcherbynsky","avatar":""},{"name":"Shen Baoping","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324241);
