INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-oni-cua-toi', 'Cô Gái Oni Của Tôi', 'My Oni Girl', 'https://phimimg.com/upload/vod/20240524-1/117fa0e320ffb3a3a3bbfac93351ba07.jpg', 'https://phimimg.com/upload/vod/20240524-1/0fad3dfdcd51c3ddde33ae515dacef07.jpg', '<p>Khả năng nói không của cậu thiếu niên nhút nhát nọ bị thử thách khi một cô gái cứng đầu kéo cậu vào cuộc hành trình thần bí giữa trời tuyết rơi mùa hè để tìm người mẹ mất tích.</p>', 'Full', 1, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"小野賢章","avatar":""},{"name":"富田美憂","avatar":""},{"name":"浅沼晋太郎","avatar":""},{"name":"山根綺","avatar":""},{"name":"Tomoko Shiota","avatar":""},{"name":"斎藤志郎","avatar":""},{"name":"田中美央","avatar":""},{"name":"ゆきのさつき","avatar":""},{"name":"佐々木省三","avatar":""},{"name":"日髙のり子","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324241);
