INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phe-tam', 'Phệ Tâm', 'Broken the Heart', 'https://phimimg.com/upload/vod/20240509-1/a9a41e0aae4dcc1e460b6b58aa28d8b9.jpg', 'https://phimimg.com/upload/vod/20240509-1/ee6cd718e28866b90985673f664beb4d.jpg', '<p>Ban Nhược Thủy là công chúa ngây thơ và tốt bụng của vương quốc Yin, nhưng khi bị gửi đến đất nước Nam Giang, cô phải chịu đựng vô số dày vò và tra tấn, buộc cô phải thay đổi nếu muốn theo đuổi tự do và độc lập.

Câu chuyện tình yêu của cô với Yu Wen Sheng, hoàng tử Bắc Giang, dường như đã kết thúc vì dù anh có yêu bao nhiêu đi chăng nữa, sự trả thù và hận thù của anh có thể sẽ hủy hoại mọi thứ...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Daisy Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
