INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-thach-dau', 'Những Kẻ Thách Đấu', 'Challengers', 'https://phimimg.com/upload/vod/20240524-1/3e98f925b931e4e04c8a75bdc98c481d.jpg', 'https://phimimg.com/upload/vod/20240524-1/aba9dfbf41ea87a8ed8cae79cc154cae.jpg', '<p>Đến từ nhà làm phim với tầm nhìn đáng nể Luca Guadagnino, “Những Kẻ Thách Đấu” có sự góp mặt của Zendaya trong vai Tashi Duncan, một cựu thần đồng quần vợt, một người không từ bất cứ thủ đoạn nào để dành chiến thắng (dù là trong hay ngoài sân đấu). Cô kết hôn với một nhà vô địch đang đối mặt với chuỗi trận thua liên tiếp. Kế hoạch tìm lại hào quang cho chồng của Tashi đối mặt với bước ngoặt lớn khi đối thủ mà chồng cô phải đối mặt là Patrick. Đó vừa là người bạn thân cũ của chồng cô, và cũng là bạn trai cũ của Tashi. Khi quá khứ và hiện tại đan xen, cùng những xung đột đang ngày một lớn hơn, Tashi phải tự hỏi chính mình, cái giá của chiến thắng đắt bao nhiêu?</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Zendaya","avatar":""},{"name":"Mike Faist","avatar":""},{"name":"Josh O''Connor","avatar":""},{"name":"Darnell Appling","avatar":""},{"name":"Bryan Doo","avatar":""},{"name":"Shane T Harris","avatar":""},{"name":"Nada Despotovich","avatar":""},{"name":"Joan Mcshane","avatar":""},{"name":"Chris Fowler","avatar":""},{"name":"Mary Joe Fernández","avatar":""},{"name":"A.J. Lister","avatar":""},{"name":"Connor Aulson","avatar":""},{"name":"Doria Bramante","avatar":""},{"name":"Christine Dye","avatar":""},{"name":"James Sylva","avatar":""},{"name":"Kenneth A. Osherow","avatar":""},{"name":"Kevin Collin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
