INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-be-gi-tam-nay', 'Bạn Bè Gì Tầm Này', 'Ricky Stanicky', 'https://phimimg.com/upload/vod/20240524-1/938acea7a4cafe72e7bae53913069593.jpg', 'https://phimimg.com/upload/vod/20240524-1/2c8b36d8819bb2f2b128da7a54e046a7.jpg', '<p>Khi ba người bạn thân thời thơ ấu thực hiện một trò chơi khăm không thành công, họ đã nghĩ ra Ricky Stanicky tưởng tượng để giúp họ thoát khỏi rắc rối. Hai mươi năm sau, họ vẫn sử dụng Ricky không tồn tại như một bằng chứng ngoại phạm hữu ích cho hành vi non nớt của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"John Cena","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"Jermaine Fowler","avatar":""},{"name":"Andrew Santino","avatar":""},{"name":"Lex Scott Davis","avatar":""},{"name":"Anja Savcic","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Riley Stiles","avatar":""},{"name":"Oscar Wilson","avatar":""},{"name":"Gaius Nolan","avatar":""},{"name":"Brian Jarvis","avatar":""},{"name":"Jackie Flynn","avatar":""},{"name":"Kevin Flynn","avatar":""},{"name":"Jasmine Anders","avatar":""},{"name":"Stan Grant","avatar":""},{"name":"Bob Farrelly","avatar":""},{"name":"Nathan Jones","avatar":""},{"name":"Jasper Bagg","avatar":""},{"name":"Di","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324241);
