INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-uyen-cu-thu', 'Thâm Uyên Cự Thú', 'The Monster in the Abyss', 'https://phimimg.com/upload/vod/20240522-1/fef57bdd366cb0b58b6d188292caa346.jpg', 'https://phimimg.com/upload/vod/20240522-1/42cb9de62fddf21aefb935e4276f6c9b.jpg', '<p>Đại quái thú cổ đại Quỳ Ngưu ngủ say bị con người bất ngờ đánh thức, quái vật sau khi tỉnh giấc thể hiện ra khả năng phá hoại mạnh mẽ, sự tồn tại của nó đe dọa nghiêm trọng đến sự an toàn của con người. Mặc dù thượng cấp thái thú tổ chức lực lượng để đi đối phó, nhưng người dân vẫn đặt ra nhiều nghi vấn khi đối mặt với quái vật, quái vật đến từ đâu. Cuộc điều tra của A Ninh cũng đã làm cho những bí mật lộ ra, thì ra tất cả đều là kết cục xấu do con người tự gây ra.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gong Xiaojun","avatar":""},{"name":"Nan Jīnling","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Tang Guo-Zhong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324241);
