INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-do-rong-mo', 'Tiền Đồ Rộng Mở', 'Dog Days Are Over', 'https://phimimg.com/upload/vod/20240522-1/ef1cf05c61e1584767c2b66dbb2cbfcb.jpg', 'https://phimimg.com/upload/vod/20240522-1/a67b7bdd03c9fbae79fc18844a24bd7b.jpg', '<p>Đường hầm sụp xuống, năm người lạ lẫm với tính cách và địa vị khác nhau bị kẹt, chỉ có một lô bia là thức ăn, muốn sống sót chỉ có thể uống bia trong hành trình thoát thân, một cuộc hành trình mạo hiểm, hồi hộp và hài hước.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bao Bei Er","avatar":""},{"name":"Ming Dao","avatar":""},{"name":"Han Yunyun","avatar":""},{"name":"Ba Duo","avatar":""},{"name":"Terence Yin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324241);
