INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-nuong-lac-hoa-dong', 'Tân Nương Lạc Hoa Động', 'Bride and The Beast', 'https://phimimg.com/upload/vod/20240522-1/0cf24cd74f116cf19c5d4d6ed88edd4c.jpg', 'https://phimimg.com/upload/vod/20240522-1/b8d6e45a79ba0d89988a2cc71ae4afbb.jpg', '<p>Phim lấy cảm hứng thật từ tam tà Tây Hồ Nam - Cô gái động Lạc Hoa, mỗi năm làng Lạp Nhĩ - Tây Hồ Nam phải hiến tế một thiếu nữ đương thì thanh xuân cho Thần núi, nếu không cả làng sẽ bị nguyền rủa, các sự kiện kỳ quái liên tục xảy ra... Con gái nhà họ Quế, Quế Đồng không may bị ma quỷ chọn trúng, Lãng Đức và Kỳ Phong đều yêu cô sâu đậm, đêm tân hôn liệu họ có thể cứu được người mình yêu không? Lời nguyền ở làng sẽ được phá giải như thế nào?</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhu Minxin","avatar":""},{"name":"倪寒尽","avatar":""},{"name":"任学海","avatar":""},{"name":"Zhou Xiaofei","avatar":""},{"name":"周炎","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324241);
