INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-thoi-tien-su', 'Quái Vật Thời Tiền Sử', 'Prehistoric Monster', 'https://phimimg.com/upload/vod/20240522-1/cb23d5f867e8d9b4a94c22be1b1e5684.jpg', 'https://phimimg.com/upload/vod/20240522-1/bfcfffc2bc1161489e469f1ccc609a67.jpg', '<p>Hòn đảo bí ẩn có những cây cổ thụ cao chót vót và những đàn chim, giống như một vùng đất cấm không có người ở trong thế giới thời tiền sử đầy rẫy những nguy hiểm. Nữ chính Wu You dấn thân vào cuộc hành trình với những người có mục đích khác nhau. Hòn đảo đầy rẫy nguy hiểm và nguy hiểm, những con khủng long cổ đại thường xuyên chặn đường, quái vật lần lượt xuất hiện. Nơi đây còn có con khủng long bạo chúa đói khát lâu ngày ẩn náu trong khu rừng rậm rạp và háo hức theo dõi. Những con người tưởng như không thể tách rời nhau đang nỗ lực tiến về phía trước. Trên hòn đảo có thể ăn thịt người này, liệu con người có thể sống sót vượt qua?</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Shengye","avatar":""},{"name":"Hong Zhu","avatar":""},{"name":"Huang Nuan Nuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324241);
