INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-my-tro-ve', 'Nhất My Trở Về', 'Yi Mei Returns', 'https://phimimg.com/upload/vod/20240522-1/3a58eddc529975215b80f53093b797d9.jpg', 'https://phimimg.com/upload/vod/20240522-1/be116d735ebe0543a7f113ef4af8abf1.jpg', '<p>Trong thời kỳ Vạn Lịch, đại hiệp thân mang tuyệt kỹ Nhất Mi tiên sinh nhận nhiệm vụ đi đến một ngôi làng xa xôi để trừ ma diệt quỷ. Trên đường đi, anh vừa hay bắt gặp yêu ma quấy phá, Nhất Mi tiên sinh đã ra tay hàng phục chúng, không ngờ đối phương lại là sư đệ Thiên Chân mà anh đã xa cách nhiều năm. Sư đệ dù biết con đường phía trước hung hiểm, lại vẫn quyết định đi cùng Nhất Mi. Trong một thị trấn bí ẩn, yêu quái hung ác hoành hành, dân không kiếm sống nổi. Nhất Mi tiên sinh vạch trần bí mật của yêu ma, dẫn dắt mọi người phản công bảo vệ quê hương, nhưng không ngờ rằng người hậu thuẫn của mình Vương viên ngoại lại đi theo phía địch và tấn công ngược lại. Nhất Mi tiên sinh bị vây hãm, rơi vào đường cùng, cô độc không ai giúp đỡ. Thủ lĩnh của phe ác đã dẫn theo binh hùng tướng mạnh thận trọng , gọn ghẽ từng bước chiếm đóng cổ trấn, Nhất Mi tiên sinh không màng sinh tử, đã triển khai cuộc chiến với thủ lĩnh phe ác. Giữa những tia sét và tia lửa, Nhất Mi tiên sinh vượt lên với kỹ năng của mình, đánh bại thủ lĩnh của phe ác, giữ bình yên cho một phương.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dong Shaohui","avatar":""},{"name":"Yang Neng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324241);
