INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-my-tro-ve', 'Nhất My Trở Về', 'Yi Mei Returns', 'nhất my trở về yi mei returns dong shaohui yang neng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-tuyen-thu-kich', 'Hỏa Tuyến Thư Kích', 'Firewire Sniper', 'https://phimimg.com/upload/vod/20240522-1/7c7b42bcbaf6b173f7311dba3b64fb65.jpg', 'https://phimimg.com/upload/vod/20240522-1/cd0a7ecc82057e4d633ae29989bee153.jpg', '<p>Câu chuyện diễn ra tại một vùng đất ở Đông Nam Á. Nam nhân vật chính, Tụng Ân, từ nhỏ đã chứng kiến cha mình, một nạn nhân của các tay buôn ma túy giết chết khi là một điệp viên ngầm. Anh quyết tâm trả thù cho cha và sau này gia nhập cảnh sát. Tuy nhiên, trong một buổi tập huấn tại trường cảnh sát, anh bị thương nặng và để lại hậu quả về sau. Cấp trên đề xuất anh nên rút lui, nhưng với lòng không chịu thua, Tụng Ân đã trong một đêm đen tối cướp súng đạn của đội cảnh sát và lẩn trốn trong sợ hãi, mất hút từ đó. Nhiều năm sau, khi Tụng Ân xuất hiện trước bạn cùng học của mình, Tra Nông và Tô Thiến, anh đã trở thành tay phụ tá và cánh tay đắc lực của một trùm ma túy lớn ở Đông Nam Á. Thì ra, màn kịch sợ tội bỏ trốn nhiều năm trước đó đã được cấp trên thiết kế kỹ lưỡng để cho Tụng Ân xâm nhập vào băng đảng ma túy. Trong trận chiến tiêu diệt băng đảng ma túy, Tụng Ân và đồng đội đã nội ứng ngoại hợp, tiêu diệt toàn bộ băng đảng ma túy, tiêu diệt lãnh đạo của băng đảng, cũng là kẻ giết cha mình trên biên giới quốc gia, an ủi linh hồn cha anh trên trời.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xie Mengwei","avatar":""},{"name":"Lu Peng","avatar":""},{"name":"Zhang Di","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
