INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-bi-diet-tinh', 'Họa Bì: Diệt Tình', 'Love Without Permission', 'https://phimimg.com/upload/vod/20240522-1/c5aacd06404b4aa3e335118562ba5a17.jpg', 'https://phimimg.com/upload/vod/20240522-1/05103b8671ca18767d8618637173d1f6.jpg', '<p>Đông Hải Long Nữ một lòng quyết tâm tìm kiếm người mình yêu và bằng mọi giá đến bên phàm nhân Vương Sinh. Tuy nhiên, yêu quái muốn lấy được chiếc lá bảo linh quý giá nhất từ Đông Hải Long Nữ và bày mưu tính kế làm tổn thương trái tim Vương Sinh. Long Nữ không còn cách nào khác đành phải dùng lá bảo linh để làm lành trái tim Vương Sinh, nên hai người phụ nữ bắt đầu kế hoạch &quot;đánh cắp trái tim&quot; Vương Sinh.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gillian Chung","avatar":""},{"name":"Li Mingxuan","avatar":""},{"name":"Cui Zhenzhen","avatar":""},{"name":"Michelle Wai","avatar":""},{"name":"Wei Qing","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Leng Haoze","avatar":""},{"name":"He Chengxi","avatar":""},{"name":"Liu Beige","avatar":""},{"name":"Dong Shaohui","avatar":""},{"name":"Ouyang Qinyi","avatar":""},{"name":"包晨希","avatar":""},{"name":"Cheng-Xuan Shih","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324241);
