INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-bi-diet-tinh', 'Họa Bì: Diệt Tình', 'Love Without Permission', 'họa bì: diệt tình love without permission gillian chung li mingxuan cui zhenzhen michelle wai wei qing yuming du leng haoze he chengxi liu beige dong shaohui ouyang qinyi 包晨希 cheng-xuan shih ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-dien-ha-that-ky-la', 'Công Chúa Điện Hạ Thật Kỳ Lạ', 'The Strange Princess', 'https://phimimg.com/upload/vod/20240522-1/00a93b72b7f02454c4751917b92e5f56.jpg', 'https://phimimg.com/upload/vod/20240522-1/a0be0641316d29e5b65da0e8a09f9b60.jpg', '<p>Sơn Đại vương Mã Đại Hữu bắt cóc công chúa Giang Thiên Nhi, bị sét đánh trúng và kỳ diệu hoán đổi cơ thể, thậm chí còn cảm nhận được nhau, trở thành chung số phận. Giang Thiên Nhi muốn hoán đổi lại cơ thể để tổ chức hôn lễ với thiếu tướng quân yêu quý Lục Thiên Hành, còn Mã Đại Hữu cũng muốn báo thù cho cha mình. Hai người buộc phải thỏa hiệp với hiện thực, hợp tác cùng nhau vượt qua các cửa ải khó khăn. Ứng Vương âm mưu tạo phản, cho người lẻn vào sơn trại của Mã Đại Hữu, chiếm lấy sơn trại làm nơi bí đóng quân bí mật. Giang Thiên Nhi giúp Mã Đại Hữu tra rõ chân tướng về mối thù cha năm xưa, còn Lục Thiên Hành cũng phải tìm bằng chứng về việc Ứng Vương mưu phản cho hoàng đế, cả ba người mỗi người một mục đích đều đến ở tại phủ Ứng Vương. Ứng Vương mưu phản trước kế hoạch, lật đổ triều đình, Giang Thiên Nhi lập tức trở thành người không nhà để về. Lục Thiên Hành cũng bị cha mình ép phải cưới con gái của Ứng Vương là Giang Khả Lam để thể hiện lòng trung thành.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lu Zhaohua","avatar":""},{"name":"Yu Xuan Chen","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324241);
