INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-dien-8-nguoi', 'Buổi Diễn 8 Người', 'The 8 Show', 'https://phimimg.com/upload/vod/20240521-1/35cf34cd19573e0cb04d295f82f41cd2.jpg', 'https://phimimg.com/upload/vod/20240521-1/73ecbca4f1fb016b43b130c61812956f.jpg', '<p>8 người bị nhốt tại tòa nhà 8 tầng bí ẩn trong chương trình hấp dẫn mà nguy hiểm này. Ở đó, thời gian càng trôi qua, họ càng kiếm được nhiều tiền.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"류준열","avatar":""},{"name":"천우희","avatar":""},{"name":"박정민","avatar":""},{"name":"이열음","avatar":""},{"name":"박해준","avatar":""},{"name":"이주영","avatar":""},{"name":"문정희","avatar":""},{"name":"배성우","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324241);
