INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-hay-yeu-anh-nhu-vay', 'Xin Hãy Yêu Anh Như Vậy', 'Men in Love', 'https://phimimg.com/upload/vod/20240504-1/fda559198f2bd641c970bb31b1d7dd9a.jpg', 'https://phimimg.com/upload/vod/20240504-1/e7740060fe3f6652fb2e974041ce8e83.jpg', '<p>&quot;Xin hãy yêu anh như vậy&quot; là một bộ phim truyền hình tình cảm đô thị do đạo diễn Trương Bác Dục (đạo diễn của &quot;Khúc biến tấu ánh trăng&quot;) chỉ đạo, có sự tham gia của Hồ Nhất Thiên (diễn viên chính trong &quot;Gửi thời thanh xuân ngây thơ tươi đẹp&quot;), Lương Khiết (người đóng chính trong &quot;Một ngày biến thành em&quot;) đóng vai chính. Câu chuyện xoay quanh Diệp Hàm (do Hồ Nhất Thiên đóng), một biên tập viên chính trị có tính kỷ luật, chăm chỉ, tình cờ giúp đỡ Lý Tiêu Tiêu (do Lương Khiết đóng), một giáo viên thể dục vụng về, đáng yêu hết lần này đến lần khác. Tuy nhiên, vì những trải nghiệm trong quá khứ, Diệp Hàm khó lòng mở cửa trái tim một lần nữa. Từ Giai Thành (Đại Húc đóng) một nhà xuất bản nhiệt huyết và thẳng thắn , tình cờ gặp lại Đồng Y Văn (Tôn Gia Linh đóng), người mẫu nổi tiếng ngày xưa. Họ cố gắng cân bằng giữa tình yêu và sự nghiệp. Mối quan hệ giữa bốn người trở nên phức tạp và thách thức do Tiêu Tiêu thầm yêu Giai Thành.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hu Yitian","avatar":""},{"name":"Liang Jie","avatar":""},{"name":"Dai Xu","avatar":""},{"name":"Sun Jia Ling","avatar":""},{"name":"Wu Qianying","avatar":""},{"name":"Li Dianzun","avatar":""},{"name":"Liu Chang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
