INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-song-o-noi-khac', 'Tôi Sống Ở Nơi Khác', 'What If', 'https://phimimg.com/upload/vod/20240507-1/870f405cd889789a797387b2d6c72917.jpg', 'https://phimimg.com/upload/vod/20240507-1/cf8abb4a6047e9616b3370fba9122f5e.jpg', '<p>Bộ phim kể về câu chuyện của Hạ Quả, một cô gái bình thường. Khi phải đối mặt với vô vàn sự lựa chọn khác nhau trong cuộc sống, cô đã xướng lên khúc dạo đầu dẫn đến hai cuộc đời hoàn toàn trái ngược. Liệu cô ấy sẽ chọn cuộc sống ngập tràn náo nhiệt ở thành phố nhỏ hay sẽ dấn thân vào cuộc sống bôn ba ở đô thị sầm uất phồn hoa? Con đường nào mới có thể dẫn cô đến với một cuộc sống phi thường hơn một chút?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhong Chuxi","avatar":""},{"name":"Liu Xueyi","avatar":""},{"name":"Lin Shen","avatar":""},{"name":"Zeawo","avatar":""},{"name":"Liu Mengmeng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
