INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-suc-khoe-bi-quyet-khoa-hoc-ve-an-uong', 'Vì sức khỏe: Bí quyết khoa học về ăn uống', 'Hack Your Health: The Secrets of Your Gut', 'https://phimimg.com/upload/vod/20240518-1/7c6e413a3ac8d9668b463a7c592597d8.jpg', 'https://phimimg.com/upload/vod/20240518-1/f6cf6df259451a7ad95614a168d5bb4f.jpg', '<p>Thông qua bộ phim tài liệu này, chúng ta sẽ khám phá về hệ tiêu hóa một cách nhẹ nhàng và thông qua nội dung mang tính thông tin cao. Bộ phim sẽ giải mã vai trò quan trọng của sức khỏe ruột trong quá trình phát triển tổng thể của chúng ta.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Giulia Enders","avatar":""},{"name":"Tim Spector","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324241);
