INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vi-suc-khoe-bi-quyet-khoa-hoc-ve-an-uong', 'Vì sức khỏe: Bí quyết khoa học về ăn uống', 'Hack Your Health: The Secrets of Your Gut', 'vì sức khỏe: bí quyết khoa học về ăn uống hack your health: the secrets of your gut giulia enders tim spector ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('franklin', 'Franklin', 'Franklin', 'https://phimimg.com/upload/vod/20240425-1/2e06da1d9e2feb1ba74c4706b046ddca.jpg', 'https://phimimg.com/upload/vod/20240425-1/25327df4fe887f4d071d89fb8fff3a72.jpg', '<p>Vào tháng 12/1776, Benjamin Franklin nổi tiếng thế giới với các thí nghiệm về điện. Nhưng niềm đam mê và quyền lực của ông bị thử thách khi ông bắt tay vào một nhiệm vụ bí mật tới Pháp - với số phận nền độc lập của nước Mỹ đang bấp bênh.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Noah Jupe","avatar":""},{"name":"Daniel Mays","avatar":""},{"name":"Ludivine Sagnier","avatar":""},{"name":"Thibault de Montalembert","avatar":""},{"name":"Assaad Bouab","avatar":""},{"name":"Théodore Pellerin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324241);
