INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-ngu-yeu-thuong', 'Ngôn Ngữ Yêu Thương', 'A Sign Of Affection', 'https://phimimg.com/upload/vod/20240517-1/d414559b382cd749c8dfe4db4c740f73.jpg', 'https://phimimg.com/upload/vod/20240517-1/0709723573ef54cf7ba984b5bc79390f.jpg', '<p>Itose Yuki là một sinh viên đại học bị khiếm thính. Thế giới của cô đã bị bao phủ bởi sự im lặng kể từ khi sinh ra. Cô rất hiếm khi giao tiếp với người ngoài, ngoại trừ người bạn thân của mình là Fujishiro Rin. Một ngày nọ, trên tàu điện, cô gặp một anh chàng tóc bạch kim và biết đa ngôn ngữ tên là Itsuomi Nagi, một người bạn của Rin. Không như những người khác, Itsuomi tỏ ra rất bình thường trước khiếm khuyết của Yuki, và điều này đã khiến Yuki rất cảm động. Sau khi chia tay, tình cảm của cô với Itsuomi bắt đầu lớn dần. Một thế giới mới đã mở ra cho cả Yuki và Itsuomi khi họ bắt đầu tìm hiểu về cuộc sống của nhau.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sumire Morohoshi","avatar":""},{"name":"Yu Miyazaki","avatar":""},{"name":"Takeo Otsuka","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Ryota Osaka","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Tasuku Hatanaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
