INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uyen-uyen-nhu-mong-tieu', 'Uyển Uyển Như Mộng Tiêu', 'Part For Ever', 'https://phimimg.com/upload/vod/20240517-1/f884f0453a9a1f6f6a34088dbbe45239.jpg', 'https://phimimg.com/upload/vod/20240517-1/9f29faa759d2d82d26d4389379892c59.jpg', '<p>Lăng Tiêu ẩn núp nhiều năm, thoắt cái đã trở thành tân thành chủ quyền thế ngất trời. Để trả thù, hắn cưỡng ép chiếm đoạt con gái của lão thành chủ là Tô Uyển Nhi. Dù hai người có ân oán thù hận ngăn cách, nhưng qua nhiều lần nguy hiểm và bảo vệ, hai người vẫn rơi vào vướng mắc yêu hận, cuối cùng tương lai của cả hai sẽ đi về đâu?&nbsp;</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
