INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('two-worlds-hai-the-gioi-mot-trai-tim', 'Two Worlds: Hai Thế Giới, Một Trái Tim', 'Two Worlds', 'https://phimimg.com/upload/vod/20240404-1/5428c39eab4234a1383e52b11209e39f.jpg', 'https://phimimg.com/upload/vod/20240404-1/7f12b7f2e2ebdf13a601e455c64f4e03.jpg', '<p>Two Worlds: Hai Thế Giới, Một Trái Tim kể về câu chuyện của Kram, vì mất đi người thân là Phupa mà quyết định đi đến Hồ Thác Bóng Trăng - nơi có truyền thuyết kể rằng có thể khiến người chết sống lại. Kram vô tình rơi xuống hồ và xuyên qua một thế giới song song. Bất ngờ thay tại đây, Kram đã tìm thấy người ấy - Phupa vẫn còn sống! Kram muốn sửa những điều đã xảy ra trong quá khứ để có thể cứu mạng Phupa, thứ mà anh ấy không thể làm được ở thế giới bên kia. Kram phải bất đắc dĩ nhờ đến sự giúp đỡ của Thai, một người đàn ông bí ẩn để cứu Phupa và Thai đã đồng ý giúp đỡ. Nhưng khi họ ở bên nhau, tim Kram đập ngày càng nhanh hơn mỗi khi ở bên Thai và Thai dường như cũng có tình cảm với Kram! Liệu Kram có cứu được mạng Phupa không? Và liệu anh có thể yêu Thai ở thế giới khác hay không?. Phim được phát sóng với phụ đề tiếng Việt trên iQIYI và iQ.com</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kornthas Rujeerattanavorapan","avatar":""},{"name":"Natasitt Uareksit","avatar":""},{"name":"Thapanawat Kaewbumrung","avatar":""},{"name":"Chavitpong Pusomjitsakul","avatar":""},{"name":"Mon Taechin Phaisanwan","avatar":""},{"name":"Rapeepat Eakpankul","avatar":""},{"name":"Yokyek Chernyim","avatar":""},{"name":"Kate Thiyada Phanbua","avatar":""},{"name":"Janya Thanasawaangkoun","avatar":""},{"name":"Nattawat Tunkaew","avatar":""},{"name":"Freya Waranit Nitanitiphat","avatar":""},{"name":"Pla","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324241);
