INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-noi-ra', 'Không Thể Nói Ra', 'Tell No One', 'https://phimimg.com/upload/vod/20240509-1/9e790f71c0b6ede7e8528f5325e9ad77.jpg', 'https://phimimg.com/upload/vod/20240509-1/ff7f0f5a529923c25d256262a7749f8c.jpg', '<p>Không Thể Nói Ra do Lưu Tín (Hunting ) trực tiếp tham gia và có sự tham gia của Âu Hào (Mãn Giang Hồng), Lý Nhất Đồng (Cuồng Phong), Dương Lặc (Phong thần 1: Bộ tam khúc), Trương Quốc Cường (Thám Tử Phố Tàu 3) và Hồ Liên Tâm (Nhân thế gian ) đóng vai chính trong bộ phim kịch tính. Một chiến dịch bắt giữ vừa thành công vừa thất bại đã thay đổi số phận của mọi người. Chờ đợi trong đau đớn có nghĩa là không bao giờ bỏ cuộc, và những tội ác thầm kín đó cũng đang chờ cơ hội quay trở lại. Lần này là trận chiến cuối cùng giữa thiện và ác. Tranh tài!&nbsp;</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Oho Ou","avatar":""},{"name":"Li Yitong","avatar":""},{"name":"Yang Le","avatar":""},{"name":"Guoqiang Zhang","avatar":""},{"name":"Hu Lianxin","avatar":""},{"name":"Zhao Yang","avatar":""},{"name":"Liu Yijun","avatar":""},{"name":"Wang Tonghui","avatar":""},{"name":"Chen Chuhan","avatar":""},{"name":"Qi Kui","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324241);
