INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-minh-cung-bay', 'Ước Mình Cùng Bay', 'I Wish We Could Fly Together', 'https://phimimg.com/upload/vod/20240404-1/40d6aa5219ba14a2083adce7eac50adb.jpg', 'https://phimimg.com/upload/vod/20240404-1/518e2ccafaaca1bf161e9ebd152d9e6d.jpg', '<p>Bộ phim kể về số phận của những con người mong muốn thoát nghèo, họ buộc phải bước vào cuộc mưu sinh để những thiếu thốn biến mất và nhường chỗ cho cuộc đua vươn tới giàu sang.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thùy Dung","avatar":""},{"name":"Trịnh Thảo","avatar":""},{"name":"Lãnh Thanh","avatar":""},{"name":"Võ Điền Gia Huy","avatar":""},{"name":"Quang Đại...","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324241);
