INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-babylon', 'Thiếu Niên Babylon', 'Young Babylon', 'https://phimimg.com/upload/vod/20240502-1/20d5a18a9a2252f8330543dd019ef6ae.jpg', 'https://phimimg.com/upload/vod/20240502-1/d0e20272560ac42f4732e85863c7d417.jpg', '<p>Chuyện kể về đầu những năm 90, tại thị trấn nhỏ ven biển ở Đông Nam - Phúc Thành, có một nhóm bạn trẻ nhiệt huyết, liều lĩnh, thỏa sức sống hết mình, chạy theo tuổi trẻ trên chuyến tàu thời gian.Trên hành trình tìm kiếm chân trời mơ ước, họ nỗ lực hoàn thiện bản thân một cách bình thường mà phi thường. Trong những năm tháng tuổi trẻ ngọt ngào và huy hoàng nhất, họ cố gắng hết mình để chào đón những phút giây rực rỡ thuộc về mình, từ đó gặt hái được sự trưởng thành và tình yêu.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hou Minghao","avatar":""},{"name":"Yang Caiyu","avatar":""},{"name":"Xiang Hanzhi","avatar":""},{"name":"Fei Qiming","avatar":""},{"name":"Zhang Teng","avatar":""},{"name":"Chen Yige","avatar":""},{"name":"Sui Yuan","avatar":""},{"name":"Zhang Song","avatar":""},{"name":"Zhao Qian","avatar":""},{"name":"Zhang Lei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
