INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-sac-tam-tich', 'Mộ Sắc Tâm Tích', 'Dusk Love', 'https://phimimg.com/upload/vod/20240502-1/3777852c22f73163402c973493af709c.jpg', 'https://phimimg.com/upload/vod/20240502-1/263d9212f56002ac48ca16a79091e48d.jpg', '<p>Câu chuyện về nhà thiết kế thời trang quyền lực Jian Mo Ran, người bị một biến cố nào đó buộc phải bí mật kết hôn với nam diễn viên nhỏ Hoắc Jin Yan nhưng dần dần nhận ra Hoắc Jin Yan chính là ngôi sao may mắn của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"An Yongchang","avatar":""},{"name":"Dai Gaozheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
