INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khanh-du-nien-1-ban-dac-biet', 'Khánh Dư Niên 1 - Bản Đặc Biệt', 'Joy of Life Special Edition', 'https://phimimg.com/upload/vod/20240509-1/a46bdadcec5d71117965c4c89e187383.jpg', 'https://phimimg.com/upload/vod/20240509-1/f0b1cef3c51a676b1060ecab5b4fe9d9.jpg', '<p>Chàng sinh viên Trương Khánh học đại học chuyên ngành lịch sử văn học, rất quen thuộc với những danh tác cổ điển, nhưng đề tài luận văn của anh sử dụng quan niệm hiện đại để phân tích lịch sử văn học cổ đại không được giáo sư Diệp công nhận. Để giáo sư Diệp trở thành người hướng dẫn nghiên cứu sinh cho mình, Trương Khánh quyết định trình bày chi tiết hơn những quan điểm mà anh muốn thể hiện bằng cách viết tiểu thuyết. Tiểu thuyết của anh kể về chàng trai trẻ Phạm Nhàn có lai lịch bí ẩn, sống với bà nội từ bé ở một tòa thành nhỏ ven biển tên Đạm Châu. Cùng chuyến thăm bất ngờ của một người thầy, cuộc sống tưởng chừng như yên bình của chàng bắt đầu đối mặt với nhiều hiểm nguy và thử thách cam go. Được người thầy bí ẩn và người bảo vệ bịt mắt hướng dẫn, Phạm Nhàn làm quen với dược tính, dược lý, tu luyện chân khí bá đạo và nâng cao võ nghệ. Từ đó, chàng liên tục phá được nhiều cạm bẫy nguy hiểm. Tò mò về thân thế bí ẩn của mình, Phạm Nhàn rời Đạm Châu đến kinh thành. Thấm thía tình người ấm lạnh chốn kinh thành, Phạm Nhàn vẫn kiên quyết bảo vệ chính nghĩa và sự thiện lương. Trải qua bao thử thách và rèn luyện từ gia đình, giang hồ đến triều đình, chàng viết nên một huyền thoại về cuộc đời huy hoàng.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nhược Quân","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Trần Đạo Minh","avatar":""},{"name":"Ngô Cương","avatar":""},{"name":"Lý Tiểu Nhiễm","avatar":""},{"name":"Vu Vinh Quang","avatar":""},{"name":"Tân Chỉ Lôi","avatar":""},{"name":"Lý Thần","avatar":""},{"name":"Tống Dật","avatar":""},{"name":"Lưu Hoa","avatar":""},{"name":"Viên Tuyền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324241);
