INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-giet-nguoi-ky-la', 'Vụ Giết Người Kỳ Lạ', 'Murder Mubarak', 'https://phimimg.com/upload/vod/20240515-1/2a4413d4a693db49106fab34d5e2b150.jpg', 'https://phimimg.com/upload/vod/20240515-1/bc1f10156076247a508501c851dc3ce7.jpg', '<p>Khi một huấn luyện viên thể dục bị sát hại tại câu lạc bộ thượng lưu nọ ở Delhi, một điều tra viên ranh ma lật mở bí mật bẩn thỉu của các thành viên siêu giàu để tìm ra hung thủ.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Pankaj Tripathi","avatar":""},{"name":"Sara Ali Khan","avatar":""},{"name":"Vijay Varma","avatar":""},{"name":"Tisca Chopra","avatar":""},{"name":"Sanjay Kapoor","avatar":""},{"name":"Karisma Kapoor","avatar":""},{"name":"Dimple Kapadia","avatar":""},{"name":"Suhail Nayyar","avatar":""},{"name":"Aashim Gulati","avatar":""},{"name":"Priyank Tiwari","avatar":""},{"name":"Deven Bhojani","avatar":""},{"name":"Brijendra Kala","avatar":""},{"name":"Varun Mitra","avatar":""},{"name":"Grusha Kapoor","avatar":""},{"name":"Purnendu Bhattacharya","avatar":""},{"name":"Paalin Kabak","avatar":""},{"name":"Padmini","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324241);
