INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-nuoc-tu-than', 'Làn Nước Tử Thần', 'Something in the Water', 'https://phimimg.com/upload/vod/20240515-1/c0577e7080797f281bb7ea372ae5fe46.jpg', 'https://phimimg.com/upload/vod/20240515-1/c3e72903a4ff1a92ad535cbc7f6e5608.jpg', '<p>Theo chân một nhóm năm người bạn gái phải chiến đấu để giành lấy sự sống ở vùng nước rộng mở sau khi đám cưới trong mơ biến thành cơn ác mộng.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Hiftu Quasem","avatar":""},{"name":"Lauren Lyle","avatar":""},{"name":"Natalie Mitson","avatar":""},{"name":"Nicole Rieko Setsuko","avatar":""},{"name":"Ellouise Shakespeare-Hart","avatar":""},{"name":"Gabriel Prevost","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324241);
