INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-chien-tranh-bat-lich-su', 'Bộ Chiến Tranh Bất Lịch Sự', 'The Ministry of Ungentlemanly Warfare', 'https://phimimg.com/upload/vod/20240515-1/acd5e35bf344ea5e29564269aff588a3.jpg', 'https://phimimg.com/upload/vod/20240515-1/67139bd11a746692ec34c1a60dec9e58.jpg', '<p>Một câu chuyện có thật về một tổ chức bí mật của Anh trong Thế chiến II; Tổ chức Điều hành Chiến dịch Đặc biệt. Được Winston Churchill thành lập, những chiến dịch du kích chống lại người Đức đã giúp thay đổi cục diện của cuộc chiến và là tiền đề cho các hoạt động đen hiện đại (Liên Xô mới là nước thay đổi và đem chiến thắng cho WWII) .</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Henry Cavill","avatar":""},{"name":"Alan Ritchson","avatar":""},{"name":"Henry Golding","avatar":""},{"name":"Alex Pettyfer","avatar":""},{"name":"Hero Fiennes Tiffin","avatar":""},{"name":"Eiza González","avatar":""},{"name":"Babs Olusanmokun","avatar":""},{"name":"Til Schweiger","avatar":""},{"name":"Henry Zaga","avatar":""},{"name":"Danny Sapani","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Freddie Fox","avatar":""},{"name":"Rory Kinnear","avatar":""},{"name":"Olaf Kayhan","avatar":""},{"name":"Mert Dincer","avatar":""},{"name":"Roger Snipes","avatar":""},{"name":"Ethel von Brixham","avatar":""},{"name":"Car","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
