INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-tu-co', 'Tương Tư Cổ', 'Lovesickness', 'https://phimimg.com/upload/vod/20240515-1/99709b7fcefc6651ba59d61c6da39c6c.jpg', 'https://phimimg.com/upload/vod/20240515-1/bd73d83159330852851147bc2cea0c72.jpg', '<p>Cô gái bình thường Mạc An An bất ngờ xuyên không về nghìn năm trước, gặp và hiểu biết lẫn nhau về Sở quốc công Tiêu Sở, quyền khuynh triều dã, Tiêu Sở. Để thay đổi số phận bị kẻ xấu hại của Tiêu Sở, Mạc An An xuyên qua ba lần, cùng Tiêu Sở trải qua một tình yêu đầy đau khổ kéo dài hàng nghìn năm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yu Yilei","avatar":""},{"name":"Yan Zixian","avatar":""},{"name":"Wang Zifei","avatar":""},{"name":"Zhao Wenlong","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
