INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-hoan-hao', 'Cô Ấy Hoàn Hảo', 'Perfect Her', 'https://phimimg.com/upload/vod/20240515-1/52ebeb0ff7201334e231b224263bca10.jpg', 'https://phimimg.com/upload/vod/20240515-1/1d9fe4bf74d1c4f8483904cd15e33581.jpg', '<p>Trong buổi kỷ niệm mười năm kết hôn của nữ chính Bạch Lê và chồng là Diệp Vân Khải, cô gặp gỡ nam chính Tô Du, đàn em của mình từ đại học. Khi đó, Tô Du đã là bạn trai của Ninh Mạt Thần. Bạch Lê bị Ninh Mạt Thần bày mưu phát hiện sự thật về chồng ngoại tình, trong khi Ninh Mạt Thần lại là đối tượng của mối quan hệ ngoại tình đó. Sau một vụ tai nạn, linh hồn của nữ chính và tiểu tam hoán đổi, sau đó linh hồn của nữ chính cùng với tiểu tam tỉnh lại, mở đường cho con đường trả thù. Vợ cả Bạch Nguyệt và linh hồn của tiểu tam ác độc hoán đổi, đội lên mặt nạ phát hiện lội ngược dòng để xoay chuyển tình thế.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Luo Zheng","avatar":""},{"name":"Xu Yiyang","avatar":""},{"name":"Yang Bingzhuo","avatar":""},{"name":"Du Yuchen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
