INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loai-thong-tri', 'Loài Thống Trị', 'Blood Free', 'https://phimimg.com/upload/vod/20240411-1/590865599eb1c7fe71232e1851d4c37f.jpg', 'https://phimimg.com/upload/vod/20240411-1/66405f1bc5dba722cbe111354fdc5ded.jpg', '<p>Sau khi lao xuống hang thỏ với những đầu mối rối rắm, một cựu vệ sĩ nhận ra mình được tuyển dụng để bảo vệ CEO của một công ty sản xuất thịt trong phòng thí nghiệm gây nhiều tranh cãi, người cũng là người sống sót sau cuộc tấn công định mệnh đã thay đổi cuộc đời anh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2024, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ju Ji-hoon","avatar":""},{"name":"Han Hyo-joo","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Lee Moo-saeng","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Park Ji-yeon","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Yi Seo","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
