INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-lap-thai-cua-toi', 'A Lạp Thái Của Tôi', 'To the Wonder', 'https://phimimg.com/upload/vod/20240509-1/64eee8e3ec2de91dff823022f33d216a.jpg', 'https://phimimg.com/upload/vod/20240509-1/a9e939a95ca18ba27edc56560ce7499f.jpg', '<p>&quot;Altay Của Tôi &quot; được đạo diễn bởi Đằng Tùng Tùng (Đưa Tôi Lên Mây Xanh), với sự tham gia diễn xuất của Mã Ý Lệ (Long Thành), Châu Y Nhiên (Cô Gái Sáng Ngời), Vu Thích (trong &quot;Phong Thần Đệ Nhất Bộ: Triều Ca Phong Vân&quot;), cùng với sự tham gia diễn xuất đặc biệt của Tưởng Kì Minh (Cáp Nhĩ Tân 1944), Diêm Bội Lân (Cuộc Thi Hài Kịch Mỗi Năm Một Lần). Bộ phim được chuyển thể từ bộ tập văn xuôi cùng tên của Lý Quyên, kể về Lý Văn Tú là một thiếu nữ dân tộc Hán lớn lên ở Altay. Cô ấy luôn mơ ước theo đuổi giấc mơ văn học trong thành phố lớn, nhưng đã gặp nhiều khó khăn và buộc phải trở về quê nhà sống cùng mẹ mình, người đang kinh doanh một cửa hàng nhỏ. Sau khi gặp gỡ cậu bé Kazakh Batai, Văn Tú dần dần khám phá ra vẻ đẹp của vùng đất này.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ma Yili","avatar":""},{"name":"Zhou Yiran","avatar":""},{"name":"Yu Shi","avatar":""},{"name":"Jiang Qiming","avatar":""},{"name":"Yan PeiLun","avatar":""},{"name":"Xiaojuan Huang","avatar":""},{"name":"Alimjian Tursunbek","avatar":""},{"name":"阿丽玛","avatar":""},{"name":"Hailaiti Hamu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
