INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('a-lap-thai-cua-toi', 'A Lạp Thái Của Tôi', 'To the Wonder', 'a lạp thái của tôi to the wonder ma yili zhou yiran yu shi jiang qiming yan peilun xiaojuan huang alimjian tursunbek 阿丽玛 hailaiti hamu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-am-chi-hoa', 'Vi Ám Chi Hoả', 'Tender Light', 'https://phimimg.com/upload/vod/20240507-1/4dff5cfe46179da8a9c6f6f96b6ab813.jpg', 'https://phimimg.com/upload/vod/20240507-1/6fa13b65ffd621df49c5bb1ffd5df030.jpg', '<p>Châu Lạc là học sinh giỏi đầu tiên của thị trấn Thanh Thủy thi đỗ vào trường đại học nổi tiếng, nhưng còn chưa tốt nghiệp anh đã thôi học về quê ôn thi lại, gây xôn xao dư luận trong thị trấn. Nếu không vì bản thân bị người khác bàn tán, có lẽ Châu Lạc sẽ chẳng bao giờ chú ý đến một nhân vật thị phi khác của thị trấn, Nam Nhã. Nam Nhã là chủ cửa hàng quần áo cực kỳ xinh đẹp, những lời đồn đại về cô không bao giờ dứt. Mỗi ngày, cô đi lại giữa cửa hàng quần áo và nhà, chăm sóc cô con gái bệnh tật Uyển Loan.Khi ngày càng thân thiết hơn với Nam Nhã, Châu Lạc phát hiện cuộc sống hôn nhân của cô không hề hạnh phúc. Khi về nhà, người chồng doanh nhân Từ Nghị của Nam Nhã có khuynh hướng bạo lực, Châu Lạc từng tận mắt chứng kiến anh ta bạo hành cô. Mà &quot;Vụ án cây cầu lớn&quot; xảy ra kéo theo rất nhiều vấn đề trong kinh doanh của Từ Nghị tại công ty. Tất cả mọi chuyện khiến cuộc hôn nhân của Nam Nhã đứng trước bờ vực đổ vỡ. Nam Nhã muốn ly hôn để bảo vệ con gái Uyển Loan. Chàng trai tốt bụng Châu Lạc không đành lòng nhìn Nam Nhã liên tục bị tổn thương trong hôn nhân bèn chủ động ra tay giúp đỡ Nam Nhã.Cuối cùng, với sự giúp đỡ của Châu Lạc, cảnh sát và những người dân tốt bụng trong thị trấn, các bên liên quan trong vụ án đều được đối xử công bằng.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tong Yao","avatar":""},{"name":"Zhang Xincheng","avatar":""},{"name":"Ye Zuxin","avatar":""},{"name":"Wang Zixuan","avatar":""},{"name":"Zhao Haohong","avatar":""},{"name":"Tu Zhiying","avatar":""},{"name":"Tian Xiaojie","avatar":""},{"name":"Liu Junxiao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
