INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-thien-ky-an-2', 'Nghịch Thiên Kỳ Án 2', 'Sinister Beings 2', 'https://phimimg.com/upload/vod/20240411-1/aa89a78fe2f97c31f1c531d24c4ad3c1.jpg', 'https://phimimg.com/upload/vod/20240410-1/79a25ff0bc4f37bb2ea7f6fe1fe1a0e2.jpg', '<p>Hai thanh tra cao cấp Hứa Tuấn Sâm (do Trần Triển Bằng đóng) và Thẩm Vi Lực (do Huỳnh Trí Hiền đóng) cùng làm việc cho Tổ điều tra tội phạm có tổ chức và Tam hiệp hội OCTB hay Điểm O (Organised Crime and Triad Bureau). Bằng trí thông minh và khả năng quan sát nhạy bén, họ phá được nhiều vụ án. Tội phạm nguy hiểm Ngụy Tử Lạc (do Trương Dĩnh Khang đóng) mất trí nhớ và bị giam trong bệnh viện tâm thần. Trước khi bị bắt, Lạc chuyển ra nước ngoài một số tiền lớn, không lâu sau có người thần bí tấn công khủng bố. Tuấn Sâm và Vi Lực phá được án nhờ sự giúp sức của giáo sư Đường Quán Phong (do Phương Lực Thân đóng), nhưng lại phát hiện đằng sau Tử Lạc ẩn chứa âm mưu lớn hơn. Bên cạnh đó, họ còn gặp những vụ án hóc búa như: lính cận vệ đánh thuê, xe ô tô bị gây nhiễu hệ thống lái, sóng gió Hồng Thắng xã, nhà trống chứa bạch cốt, kẻ trọng phạm vượt ngục...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Triển Bằng","avatar":""},{"name":"Huỳnh Trí Hiền","avatar":""},{"name":"Lâm Hạ Vy","avatar":""},{"name":"Phùng Doanh Doanh","avatar":""},{"name":"Phương Lực Thân","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324241);
