INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-ho-404', 'Căn Hộ 404', 'Apartment 404', 'https://phimimg.com/upload/vod/20240323-1/e82d749cd8f28e2a71d14e9e4be854ea.jpg', 'https://phimimg.com/upload/vod/20240323-1/0ca86247d5b1d3e6460a3466dc5b70ca.jpg', '<p>Phim Căn Hộ 404 – Apartment 404 (2024) là chương trình thực tế được kỳ vọng rất nhiều tại Hàn Quốc, dự kiến phát sóng từ ngày 23 tháng 2 năm 2024, chắc chắn sẽ mang đến món ăn tinh thần thú vị cho mọt phim xứ kim chi. Yoo Jae Suk vẫn là cái tên đảm nhận vị trí “chủ chốt” của chương trình, anh là một diễn viên hài và người dẫn chương trình hài kịch truyền hình Hàn Quốc. Anh đã khẳng định mình là một trong những diễn viên hài và nhân vật truyền hình hàng đầu xứ Hàn. Ngoài ra, anh cũng là một trong những nhân vật truyền hình được trả lương cao nhất ở Hàn Quốc và là một trong những người được săn đón nhiều nhất quy tụ dàn sao đình đám như Jennie (Blackpink), Yoo Jae Suk, Lee Jung Ha…</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae-suk","avatar":""},{"name":"Cha Tae-hyun","avatar":""},{"name":"Oh Na-ra","avatar":""},{"name":"Yang Se-chan","avatar":""},{"name":"Jennie Kim","avatar":""},{"name":"Lee Jung-ha","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324241);
