INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-nhat-nung-tinh', 'Xuân Nhật Nùng Tình', 'Roses and Guns', 'https://phimimg.com/upload/vod/20240502-1/6af74f2f223c6bbc2697df16fa49c15e.jpg', 'https://phimimg.com/upload/vod/20240502-1/ce65629d9d7d5ae7d8a2eb9b2b3b9ae2.jpg', '<p>Để tìm ra sự thật về mối thù diệt tộc của nhà họ Ôn, Ôn Ngọc Nùng đã mượn danh tính giả để vào Tần gia, nhưng vô tình gặp lại Tần Khắc Văn, người yêu ba năm về trước, và nhiệm vụ của cô liên tục bị cản trở. Tần Khắc Văn quay trở lại với mục đích trả thù, thề sẽ vạch trần bộ mặt thật của kẻ lừa dối tình cảm là Ôn Ngọc Nùng. Hai người ăn miếng trả miếng, nhưng quanh đi quẩn lại hết lần này đến lần khác, tình cảm của họ ngày càng bền chặt.</p>', 'Tập 18', 20, 'series', 'ongoing', 13, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dai Gaozheng","avatar":""},{"name":"Flora Dai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
