INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-truong', 'Trạm Trưởng', 'Chief of Station', 'https://phimimg.com/upload/vod/20240508-1/c52cbb1f09933d4e77939d193aed1d7c.jpg', 'https://phimimg.com/upload/vod/20240508-1/83b321b84e2c17887be5c77073e040c9.jpg', '<p>Sau khi biết cái chết của vợ mình không phải là một tai nạn, cựu Giám đốc Trạm CIA bị buộc phải quay trở lại thế giới gián điệp ngầm, hợp tác với một kẻ thù để làm sáng tỏ một âm mưu thách thức mọi thứ mà anh ta nghĩ mình biết.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Alex Pettyfer","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Laëtitia Eïdo","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Chris Petrovski","avatar":""},{"name":"Nina Bergman","avatar":""},{"name":"Kris Johnson","avatar":""},{"name":"Jonathan Ajayi","avatar":""},{"name":"Isobel Wood","avatar":""},{"name":"Bleona","avatar":""},{"name":"Josef Cannon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324241);
