INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-vien-mau', 'Tu Viện Máu', 'Immaculate', 'https://phimimg.com/upload/vod/20240509-1/cda1ddc448bb37ea36ec5752a5fab6f7.jpg', 'https://phimimg.com/upload/vod/20240509-1/ce39c1832c42524d50bc95423c02af98.jpg', '<p>Cecilia, một phụ nữ sùng đạo, được chào đón nồng nhiệt khi đến vùng nông thôn Ý, nơi cô được giao một vai trò mới tại một tu viện lừng danh. Nhưng Cecilia nhận ra rằng ngôi nhà mới của cô ẩn chứa những bí mật đen tối và kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Sydney Sweeney","avatar":""},{"name":"Álvaro Morte","avatar":""},{"name":"Benedetta Porcaroli","avatar":""},{"name":"Dora Romano","avatar":""},{"name":"Giorgio Colangeli","avatar":""},{"name":"Simona Tabasco","avatar":""},{"name":"Giampiero Judica","avatar":""},{"name":"Niccolò Senni","avatar":""},{"name":"Giulia Heathfield Di Renzi","avatar":""},{"name":"Giampiero Judica","avatar":""},{"name":"Betti Pedrazzi","avatar":""},{"name":"Giuseppe Lo Piccolo","avatar":""},{"name":"Cristina Chinaglia","avatar":""},{"name":"Isabel Desantis","avatar":""},{"name":"Viv","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324241);
