INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-uoc-ireland', 'Điều Ước Ireland', 'Irish Wish', 'https://phimimg.com/upload/vod/20240509-1/eecdf51c8e4b6739dada4b09aba97b73.jpg', 'https://phimimg.com/upload/vod/20240509-1/80d2272980ba7f332d96a5ddec74ef47.jpg', '<p>Còn vài ngày nữa là chàng trai trong mộng của Maddie cưới bạn thân của cô. Và rồi điều ước về tình yêu đích thực trước hòn đá cổ ở Ireland thay đổi số phận của cô một cách kỳ diệu.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lindsay Lohan","avatar":""},{"name":"Ed Speleers","avatar":""},{"name":"Alexander Vlahos","avatar":""},{"name":"Ayesha Curry","avatar":""},{"name":"Elizabeth Tan","avatar":""},{"name":"Jacinta Mulcahy","avatar":""},{"name":"Jane Seymour","avatar":""},{"name":"Matty McCabe","avatar":""},{"name":"Dawn Bradfield","avatar":""},{"name":"Maurice Byrne","avatar":""},{"name":"James Rottger","avatar":""},{"name":"Aidan Jordan","avatar":""},{"name":"Dakota Lohan","avatar":""},{"name":"Tim Landers","avatar":""},{"name":"Steve Hartland","avatar":""},{"name":"Carl Shaaban","avatar":""},{"name":"Rodrigo Ternevoy","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324241);
