INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-san-ma-ky-nguyen-bang-gia', 'Biệt Đội Săn Ma: Kỷ Nguyên Băng Giá', 'Ghostbusters: Frozen Empire', 'https://phimimg.com/upload/vod/20240425-1/d5c213a3a7bece94b4c77a9933bbb03f.jpg', 'https://phimimg.com/upload/vod/20240425-1/61588438f082a673355b3c1a94cca14e.jpg', '<p>Chuyện phim kể về gia đình Spengler quyết định rời khỏi vùng Summerville, Oklahoma để trở lại New York. Tại đây, “biệt đội săn ma nguyên bản” đã phát triển một phòng thí nghiệm nghiên cứu bảo mật cấp cao, tìm cách đưa việc tiêu diệt các hồn ma lên một bước tiến mới bằng loại vũ khí proton tối tân. Tuy nhiên, sự cố xảy ra đã vô tình giải phóng Death Chill - thế lực bí ẩn và độc ác nằm bên trong một món cổ vật. Điều này khiến cả những “cựu binh” và “tân binh” của biệt đội săn ma phải hợp tác để bảo vệ ngôi nhà của họ, cũng như bảo vệ thế giới trước mối hiểm họa mang tên Death Chill.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Mckenna Grace","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Carrie Coon","avatar":""},{"name":"Finn Wolfhard","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Kumail Nanjiani","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Celeste O''Connor","avatar":""},{"name":"Logan Kim","avatar":""},{"name":"Emily Alyn Lind","avatar":""},{"name":"James Acaster","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Annie Potts","avatar":""},{"name":"William Atherton","avatar":""},{"name":"Shelley Williams","avatar":""},{"name":"Chris Tummings","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324241);
