INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-tac', 'Không Tặc', 'Yodha', 'https://phimimg.com/upload/vod/20240509-1/9c6ef50ceda168a91be621356e463e4d.jpg', 'https://phimimg.com/upload/vod/20240509-1/9a2cbb08e6a72b00084fc1c2936f51c7.jpg', '<p>Sau khi những kẻ khủng bố cướp một chiếc máy bay chở khách, một người lính ngoài nhiệm vụ trên máy bay nghĩ ra chiến lược đánh bại những tên không tặc và đảm bảo sự sống sót của hành khách khi động cơ hỏng.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sidharth Malhotra","avatar":""},{"name":"Disha Patani","avatar":""},{"name":"Raashii Khanna","avatar":""},{"name":"Shivangi Bhardwaj","avatar":""},{"name":"Col Ravi Sharma","avatar":""},{"name":"Sadiq Farooqui","avatar":""},{"name":"Ankit Raaj","avatar":""},{"name":"Mohd Talib","avatar":""},{"name":"Apeksha Pandey","avatar":""},{"name":"Abhishek Mishra","avatar":""},{"name":"Amit Singh Thakur","avatar":""},{"name":"Anvishaa Tyagi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324241);
