INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-quang-dam-mau', 'Hào Quang Đẫm Máu', 'Wannabe', 'https://phimimg.com/upload/vod/20240509-1/7cc4b9fb380a30ec5aaafb78709d7545.jpg', 'https://phimimg.com/upload/vod/20240509-1/c82a2995e65a8e4683ea94c1cc59eefa.jpg', '<p>Câu chuyện kể về Lee Soo-yeon (do Ji-yeon thủ vai) - một nữ minh tinh màn bạc đang ở đỉnh cao sự nghiệp nhưng bất chợt tuột dốc không phanh vì tai nạn chết người do chính cô gây ra trong lúc say rượu. Sau thời gian dài “ở ẩn” để trả giá cho sai lầm, Lee Soo-yeon bắt đầu nuôi mộng trở lại với khán giả nhưng bê bối từ quá khứ của cô luôn bị người đời đay nghiến, châm chọc.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Park Ji-yeon","avatar":""},{"name":"Song Ji-eun","avatar":""},{"name":"Kim Nu-ri","avatar":""},{"name":"Lee Ji-hoon","avatar":""},{"name":"Kim He-sang","avatar":""},{"name":"Seo Jin-won","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324241);
