INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-tiec-trong-hang-tho', 'Bữa Tiệc Trong Hang Thỏ', 'Down the Rabbit Hole', 'https://phimimg.com/upload/vod/20240508-1/603919d110817f63760e65a609edc81b.jpg', 'https://phimimg.com/upload/vod/20240508-1/154d15d9f0bfef84a244f28c7a00b5fc.jpg', '<p>Lớn lên trong sự giàu có và văn hóa, cuộc sống xa hoa của cậu bé 10 tuổi Tochtli tương phản với bóng tối len lỏi từ các hoạt động tội phạm của bố cậu bé.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Debi Mazar","avatar":""},{"name":"Teresa Ruiz","avatar":""},{"name":"Daniel Giménez Cacho","avatar":""},{"name":"Mercedes Hernández","avatar":""},{"name":"Raúl Briones","avatar":""},{"name":"Manuel Garcia-Rulfo","avatar":""},{"name":"Pierre Louis","avatar":""},{"name":"Alfredo Gatica","avatar":""},{"name":"Miguel Valverde","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
