INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-biet-doi-nhan-ban-dac-biet-phan-3', 'Star Wars: Biệt Đội Nhân Bản Đặc Biệt (Phần 3)', 'Star Wars: The Bad Batch (Season 3)', 'https://phimimg.com/upload/vod/20240229-1/11258f68ef2a6e98625b12e76200f2ec.jpg', 'https://phimimg.com/upload/vod/20240229-1/2efdf24d403fbcc67b2806f9d92e9aed.jpg', '<p>The Bad Batch là một đội đặc biệt được biến đổi gene để có khả năng đặc biệt hơn người bình thường. Đội này chuyên có những nhiệm vụ đặc biệt mà thậm chí Jedi mới có thể làm, thường những nhiệm vụ này trên trình Clone bình thường. Trong phần 7 vừa rồi, The Bad Batch đã xuất hiện để hỗ trợ Anakin và Rex cứu lấy Echo. Tuy nhiên vì khác biệt với phần còn lại nên Echo đã đi cùng The Bad Batch để khác biệt cùng họ.</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dee Bradley Baker","avatar":""},{"name":"Michelle Ang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324241);
