INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-mat-troi-lan', 'Khi Mặt Trời Lặn', 'Arcadian', 'https://phimimg.com/upload/vod/20240504-1/c80b1372f7596cb10894423fbec27679.jpg', 'https://phimimg.com/upload/vod/20240504-1/024115eb292f914cd94d06b3d5884e29.jpg', '<p>Trong phim, nam diễn viên kỳ cựu Nicolas Cage đảm nhận vai người cha đang nỗ lực bảo vệ hai cậu con trai sinh đôi, Joseph và Thomas trong một trang trại hẻo lánh. Gia đình anh phải đối mặt với những nguy hiểm khi mặt trời lặn vào cuối ngày và các thành viên cần gắn kết với nhau để tăng cơ hội sống sót. “Arcadian” mang đến cho người xem một cái nhìn mới lạ về ngày tận thế qua tài năng diễn xuất của Nicolas Cage và chỉ đạo diễn xuất của Benjamin Brewer.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Jaeden Martell","avatar":""},{"name":"Maxwell Jenkins","avatar":""},{"name":"Sadie Soverall","avatar":""},{"name":"Samantha Coughlan","avatar":""},{"name":"Joel Gillman","avatar":""},{"name":"Joe Dixon","avatar":""},{"name":"Daire McMahon","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324241);
