INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-ve-phia-lua', 'Đi về phía LỬA', 'Toward The Fire', 'https://phimimg.com/upload/vod/20240504-1/ec4426ea42d50f42e9e8397c6c34f03e.jpg', 'https://phimimg.com/upload/vod/20240504-1/a71aad6be9ca22d1f37d05654b3d1ae0.jpg', '<p>&quot;Đi về phía lửa&quot; là bộ phim truyền hình dài tập về nghề lính cứu hỏa, cứu hộ, cứu nạn - một trong những công việc được coi là nguy hiểm nhất thế giới, do đạo diễn Trần Thanh Huy thực hiện. Bộ phim được lấy cảm hứng từ series truyền hình đình đám Đài Loan - &quot;Nước mắt của hỏa thần&quot; (Tears On Fire). Đây hứa hẹn là một sự chuyển thể đầy ấn tượng, phù hợp với văn hoá, bối cảnh và lối sống của khán giả Việt Nam.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lãnh Thanh","avatar":""},{"name":"Trần Ngọc Vàng","avatar":""},{"name":"Nguyễn Xuân Phúc","avatar":""},{"name":"Hồ Thu Anh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324241);
