INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('di-ve-phia-lua', 'Đi về phía LỬA', 'Toward The Fire', 'đi về phía lửa toward the fire lãnh thanh trần ngọc vàng nguyễn xuân phúc hồ thu anh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-thieu-nien-cua-toi', 'Thời Đại Thiếu Niên Của Tôi', 'Our Memories', 'https://phimimg.com/upload/vod/20240502-1/20c1ded756df2e2ac663fca471126f8c.jpg', 'https://phimimg.com/upload/vod/20240502-1/64cf8ef7839d26d273724e845046a9f9.jpg', '<p>Tọa lạc tại &quot;phố vũ trụ&quot; của một thị trấn nhỏ ven biển, &quot;Vua trẻ em&quot; Vương Hoàn Vũ, &quot;Nữ thần vũ đạo&quot; Vệ Tinh, &quot;Cửa hàng thế hệ thứ hai&quot; Hàn Soái, &quot;Thiếu nữ ma ngựa&quot; Quách Đình và &quot;Nhà văn học&quot; Sử Văn Khả từ nhỏ là thanh mai trúc mã, cùng nhau lớn lên. Đối mặt với năm cuối cấp tốt nghiệp phổ thông, bất luận học sinh kém như Vương Hoàn Vũ, Hàn Soái và Quách Đình, hay học bá như Vệ Tinh và Sử Văn Khả đều phải đối mặt với vấn đề khó tương lai đi đâu về đâu. Phiền não của sự trưởng thành đi cùng với sự mờ mịt của thanh xuân, cũng lặng lẽ gõ cửa trái tim bọn trẻ. Thanh xuân là một trận nhốn nháo hoảng loạn, nhưng chỉ cần có những người bạn quan tâm ở bên, bạn chẳng có gì phải sợ hãi. Một năm nay, nhóm thanh thiếu niên với những tính cách khác nhau và có sức hấp dẫn lẫn nhau, với khí chất riêng, đã trải qua những niềm vui, nỗi buồn do tình cảm gia đình, tình bạn và tình yêu hồ đồ mang lại.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lu Xiaoyu","avatar":""},{"name":"Fang Xiaodong","avatar":""},{"name":"Hongxin Cheng","avatar":""},{"name":"Li Mengying","avatar":""},{"name":"Cao Saiya","avatar":""},{"name":"Yang Yikai","avatar":""},{"name":"Zhang Xiao''ang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
