INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-trung-chi-thanh', 'Thành Trung Chi Thành', 'City Of The City', 'https://phimimg.com/upload/vod/20240411-1/06033e0a77ee19fb6989b0b6f8276514.jpg', 'https://phimimg.com/upload/vod/20240411-1/e4e86c6107186aa36008b1bb10f50f5b.jpg', '<p>Thanh niên trẻ ở thị trấn Đào Vô Kỵ được chi nhánh ven sông của Ngân hàng Thâm Mậu tuyển dụng, bắt đầu làm từ vị trí thấp nhất là nhân viên quầy, còn bạn gái của anh là Điền Hiểu Tuệ, một cô gái Thượng Hải được chị họ giới thiệu vào công ty ký gửi. Cả hai hẹn ước sẽ phát triển trong ngành tài chính và cố gắng sớm định cư ở Thượng Hải. Đào Vô Kỵ làm việc chăm chỉ và nỗ lực, bộc lộ tài năng nên được giám đốc chi nhánh Triệu Huy, trưởng phòng kiểm toán Miêu Triệt nhìn trúng, dốc lòng bồi dưỡng, dần dần tìm ra ý nghĩa và phương hướng làm việc của mình ở ngân hàng; Còn Hiểu Tuệ sau khi gia nhập công ty ký gửi phải đối mặt với cuộc sống khắc nghiệt, từng bước tiến lên nhưng nhận ra rằng trong thế giới tiền bạc này, cả hai đều đối mặt với nhiều thách thức và thử thách. Vô Kỵ và Hiểu Tuệ, Triệu Huy và Miêu Triệt, hai thế hệ nhà tài chính trải qua sự lựa chọn nghề nghiệp và vận mệnh thăng trầm, đối mặt với cám dỗ và khó khăn, họ phải lần lượt đưa ra lựa chọn, liệu họ sẽ nước chảy bèo trôi hay không quên sơ tâm, đầu xuôi đuôi lọt?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Yufan","avatar":""},{"name":"Yu Hewei","avatar":""},{"name":"Xia Meng","avatar":""},{"name":"Long Ni","avatar":""},{"name":"Wang Xiao","avatar":""},{"name":"Feng Jiayi","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Yang Zishan","avatar":""},{"name":"Chen Jin","avatar":""},{"name":"Tu Songyan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
