INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-su-dai-nhan-cua-ta', 'Thần Sứ Đại Nhân Của Ta', 'My Divine Emissary', 'https://phimimg.com/upload/vod/20240428-1/d06d50d845bf59cae627271e4d6ee9e0.jpg', 'https://phimimg.com/upload/vod/20240428-1/b6b0c23a725295527d71187d62423143.jpg', '<p>Li Mengmeng, một nữ sinh hiện đại thiếu tự tin và không ai chú ý đến mình, lạc vào một thời gian và không gian xa lạ - nước Qi, và trở thành sứ giả thần thánh, người có thành tích học tập thấp nhất thời hiện đại. phản công thành công ở nước Tề và trở thành Cố vấn trẻ tuổi của hoàng đế độc ác Qi Yan, cả hai cùng nhau hợp tác như một đồng đội ngầm để xây dựng sự nghiệp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Zixuan","avatar":""},{"name":"Chen Jingke","avatar":""},{"name":"Wei Tianhao","avatar":""},{"name":"Tan Xiaofan","avatar":""},{"name":"He Derui","avatar":""},{"name":"Wang Yunzhi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
