INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trom-duoc-tuong-quan-nua-ngay-nhan', 'Trộm Được Tướng Quân Nửa Ngày Nhàn', 'The Substitute Princess''s Love', 'https://phimimg.com/upload/vod/20240426-1/d69d293e5150c8f23f60dc98743bb4ad.jpg', 'https://phimimg.com/upload/vod/20240426-1/1c20e7322869eced3740bbfdd6ccea8e.jpg', '<p>Chiến Thần Văn Dạ hy sinh trên chiến trường ngay trước ngày kết hôn, cả nước đều thương tiếc. Cô dâu ban đầu muốn gả đi là con gái chính thức của gia đình Thẩm tể tướng, bà Thẩm không muốn con gái mình trở thành góa phụ nhưng lại sợ việc hủy hôn sẽ nhận lấy chỉ trích từ dư luận. Vì vậy, bà tìm Thẩm Khả Hỷ, là con gái ngoài giá thú đang sống bên ngoài của Thẩm gia, ép cô kết hôn thay cho con gái bà. Tuy nhiên, tin tức ngoài chiến trường đã bị nhầm lẫn, Văn Dạ dẫn quân trở lại triều đình, Thẩm Khả Hỷ được gả cho Văn Dạ và chính thức trở thành công chúa, cô và hoàng tử trở thành cặp đôi vô cùng hạnh phúc, trong suốt quá trình đó, hai người thực sự đã nảy sinh tình cảm với nhau. Sau những thách thức mà họ đã đối mặt, cuối cùng, họ đã hiểu rõ giá trị thực sự của tình yêu và sự chăm sóc. Họ quyết định ở bên nhau, không theo đuổi sự giàu có và thịnh vượng, chỉ mong muốn tận hưởng những khoảnh khắc bình yên và đáng trân quý mà họ có thể trao cho nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dylan Kuo","avatar":""},{"name":"Zhang Miaoyi","avatar":""},{"name":"Ren Yunjie","avatar":""},{"name":"Liu Zhiwei","avatar":""},{"name":"Wu Yijia","avatar":""},{"name":"Liu Shu Yuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324241);
