INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-bai-the-tham', 'Thất Bại Thê Thảm', 'Fiasco', 'https://phimimg.com/upload/vod/20240502-1/dbf9f1717c69a9448e979eb037171fe2.jpg', 'https://phimimg.com/upload/vod/20240502-1/6794494d27a511334007662f8db0d549.jpg', '<p>Khi thảm họa ập xuống phim trường của một người lần đầu làm đạo diễn, đoàn làm phim ghi lại mọi chuyện khi những tai nạn, hành vi tống tiền và phá hoại xảy ra sau đó ở hậu trường.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Pierre Niney","avatar":""},{"name":"François Civil","avatar":""},{"name":"Géraldine Nakache","avatar":""},{"name":"Pascal Demolon","avatar":""},{"name":"Leslie Medina","avatar":""},{"name":"Louise Coldefy","avatar":""},{"name":"Djimo","avatar":""},{"name":"Juliette Gasquet","avatar":""},{"name":"Jessy Ugolin","avatar":""},{"name":"Soraya Garlenq","avatar":""},{"name":"Marie-Christine Barrault","avatar":""},{"name":"Ethann Isidore","avatar":""},{"name":"Igor Gotesman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324241);
