INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-nuoc-mat', 'Nữ Hoàng Nước Mắt', 'Queen of Tears', 'https://phimimg.com/upload/vod/20240310-1/344c7b4a45bc06caf2ca8968a0ed67f9.jpg', 'https://phimimg.com/upload/vod/20240310-1/cf38fab455d6d0849a2486b97eabb487.jpg', '<p>Nữ hoàng cửa hàng bách hóa và hoàng tử siêu thị xoay xở với khủng hoảng hôn nhân, rồi tình yêu bắt đầu nảy nở trở lại theo cách kỳ diệu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Soo-hyun","avatar":""},{"name":"Kim Ji-won","avatar":""},{"name":"Park Sung-hoon","avatar":""},{"name":"Kwak Dong-yeon","avatar":""},{"name":"Na Young-hee","avatar":""},{"name":"Kim Jung-nan","avatar":""},{"name":"Kim Joo-ryoung","avatar":""},{"name":"Lee Ju-bin","avatar":""},{"name":"Yoon Bo-mi","avatar":""},{"name":"Kim Kap-soo","avatar":""},{"name":"Lee Mi-sook","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Kim Do-hyun","avatar":""},{"name":"Lee Su-ji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
