INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tich-2024', 'Mất Tích', 'HIDE', 'https://phimimg.com/upload/vod/20240402-1/67fe1b7f33c42157779593e7b7dc94b6.jpg', 'https://phimimg.com/upload/vod/20240402-1/1a9153554f009460327c690b8e5c50b0.jpg', '<p>Mất Tích - Hide, bộ phim xoay quanh nhân vật Na Moon Young (Lee Bo Young) trong hành trình tìm kiếm người chồng mất tích Cha Sung Jae (Lee Moo Saeng) và khám phá bí mật đằng sau sự biến mất của anh. Đồng hành cùng cô là người hàng xóm Ha Yeon Joo (Lee Chung Ah) và sự xuất hiện của người đàn ông bí ẩn tên Do Jin Woo (Lee Min Jae), người nắm giữ bí mật về sự mất tích của Cha Sung Jae.&nbsp;</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Bo-young","avatar":""},{"name":"Lee Moo-saeng","avatar":""},{"name":"Lee Chung-ah","avatar":""},{"name":"Lee Min-jae","avatar":""},{"name":"Jo Eun-sol","avatar":""},{"name":"Kim Sang-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
