INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-trang-mat-song-gio', 'Kỳ Trăng Mật Sóng Gió', 'Honeymoonish', 'https://phimimg.com/upload/vod/20240502-1/f3986f1d266a69645fea1e6fb630a785.jpg', 'https://phimimg.com/upload/vod/20240502-1/f0b7bf2bc71f40b48bc9114bbb7dded6.jpg', '<p>Một cặp vợ chồng mới cưới nhận ra trong tuần trăng mật của họ rằng họ thực sự hoàn toàn khác. Nhưng các mặt đối lập có là điểm thu hút không?</p>', 'Full', 1, 'single', 'completed', 21, 2024, 'Vietsub', 'FHD', 'Ả Rập Xê Út', 0, '[{"name":"Mahmoud Boushahri","avatar":""},{"name":"Nour Al-Ghandour","avatar":""},{"name":"Faisal Almezel","avatar":""},{"name":"Ascia Al Faraj","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
