INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-kim-quy-su-luc', 'Hoàng Kim Quỷ Sự Lục', 'Huang Jin Gui Shi Lu Film Series', 'https://phimimg.com/upload/vod/20240502-1/184955a93212b16adb117c99ca098dd2.jpg', 'https://phimimg.com/upload/vod/20240502-1/890f2c6f1087d9f8dca17f673e2f20d2.jpg', '<p>Huyện Hoa Dung bị lời nguyền từ Hoàng Kim Thất Lệnh. Huyện trưởng Lục đã mời đạo sĩ để trừ tai họa , nhưng không ngờ đạo sĩ Trần Bì và bốn đồ đệ đã chết một cách lạ lùng. Sự kiện kỳ lạ này đã gây ra cuộc hoang mang lớn tại huyện Hoa Dung. Trong khi đó, thánh linh thần bí La Sát giáo trong huyện, đã xúi giục dân chúng và gây ra nhiều vụ án bi kịch và huyền bí hơn nữa, khiến nhiều người tin vào La Sát giáo. Trong thời khắc nguy nan, Lục huyện trưởng đã nhờ cảnh sát trưởng Đoàn Quảng Long và hai huynh muội Tiết Tiểu Phong và Tiết Tiểu Hoa hợp tác để điều tra một âm mưu lớn đằng sau Hoàng Kim Thất Lệnh và La Sát giáo. Khi huyện trưởng Lục gặp nguy hiểm, Tiết Tiểu Phong và Tiết Tiểu Hoa cùng với Đoàn Quảng Long và những người khác đã bí mật hợp tác trong cuộc điều tra âm mưu phía sau của Hoàng Kinh Thất Lệnh và La Sát giáo. Họ đã xâm nhập vào La Sát giáo, công xưởng người nước ngoài ẩn, và tham chiến với xác chết ở trụ sở cảnh sát, khám phá ra rằng tất cả những điều này đều là một âm mưu xấu xa của người ngoại quốc John Dylan, sử dụng Hoàng Kim Thất Lệnh kết hợp với chất độc linh lan để gây ra hiện tượng ảo giác ở người trúng độc, tạo ra dư luận quỷ thần ở huyện Hoa Dung để trắng trợn lừa lấy văn vật trân quý. Con cháu Hoa Hạ không thể bị xỉ nhục, dưới sự hợp tác của Tiết Tiểu Phong, Tiết Tiểu Hoa và Đoàn Quảng Long, cuối cùng đã đánh bại âm mưu xấu xa của người ngoại quốc John Dylan.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324242);
