INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dat-nuoc-toi', 'Đất Nước Tôi', 'Ae Watan Mere Watan', 'https://phimimg.com/upload/vod/20240502-1/653d18ae3cc2a8b97a673609ba18e0a8.jpg', 'https://phimimg.com/upload/vod/20240502-1/00ea627d1932fb285ff31ed01bb5a671.jpg', '<p>Giữa cuộc đấu tranh vì tự do của Ấn Độ vào năm 1942, một cô gái trẻ dũng cảm thành lập đài phát thanh ngầm để truyền bá thông điệp đoàn kết, gây ra cuộc rượt đuổi gay cấn với chính quyền Anh trong phong trào Thoát khỏi Ấn Độ.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sara Ali Khan","avatar":""},{"name":"Sachin Khedekar","avatar":""},{"name":"Sparsh Shrivastav","avatar":""},{"name":"Abhay Verma","avatar":""},{"name":"Alexx O''Nell","avatar":""},{"name":"Anand Tiwari","avatar":""},{"name":"Emraan Hashmi","avatar":""},{"name":"Madhu Raja","avatar":""},{"name":"Pratik Yadav","avatar":""},{"name":"Aditi Sanwal","avatar":""},{"name":"Chrisann Pereira","avatar":""},{"name":"Manoj Diwakar","avatar":""},{"name":"Godaan Kumar","avatar":""},{"name":"Sangram Salvi","avatar":""},{"name":"Richard Bhakti Klein","avatar":""},{"name":"Uday Chandra","avatar":""},{"name":"Ira D","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324242);
