INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-duong-cua-pon', 'Chặng Đường Của Pon', 'Pon no Michi', 'https://phimimg.com/upload/vod/20240302-1/8ba8a578d2ec9970f6535781f4d34605.jpg', 'https://phimimg.com/upload/vod/20240302-1/5f3c95de9e311f27df2e803bb99b8d8e.jpg', '<p>Ở Onomichi, Hiroshima, nữ sinh Nashiko Jippensha rơi vào thế khó khi bị mẹ đuổi khỏi nhà. Cô băn khoăn không biết nên tụ tập ở đâu cùng bạn bè. May mắn thay, cô được giao quán cờ tướng cũ của cha mình để tạo nên một nơi thân mật cho cô và bạn bè Pai và Izumi. Đây trở thành địa điểm lý tưởng cho họ để chơi game, nấu ăn, thưởng thức trà và đôi khi chơi cờ tướng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kaori Maeda","avatar":""},{"name":"Iori Saeki","avatar":""},{"name":"Shion Wakayama","avatar":""},{"name":"Yui Kondo","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Hibiku Yamamura","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
