INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cuop-chuyen-bay-601', 'Vụ Cướp Chuyến Bay 601', 'The Hijacking of Flight 601', 'https://phimimg.com/upload/vod/20240428-1/2142a4056c71987bde39316638c09dcb.jpg', 'https://phimimg.com/upload/vod/20240428-1/bf0a8b103f4721f0c6877cb8ebfebbe2.jpg', '<p>Sau khi máy bay bị cướp, hai tiếp viên phải đánh lừa những kẻ tấn công họ giữa các cuộc đàm phán căng thẳng cả trên không lẫn trên mặt đất. Bộ phim dựa trên các sự kiện có thật.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Monica Lopera","avatar":""},{"name":"Christian Tappán","avatar":""},{"name":"Enrique Carriazo","avatar":""},{"name":"Carlos Manuel Vesga","avatar":""},{"name":"Ilenia Antonini","avatar":""},{"name":"Valentín Villafañe","avatar":""},{"name":"Juan Pablo Raba","avatar":""},{"name":"Alián Devetac","avatar":""},{"name":"Marcela Benjumea","avatar":""},{"name":"Ángela Cano","avatar":""},{"name":"Johan Rivera Zumaqué","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
