INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-cuop-chuyen-bay-601', 'Vụ Cướp Chuyến Bay 601', 'The Hijacking of Flight 601', 'vụ cướp chuyến bay 601 the hijacking of flight 601 monica lopera christian tappán enrique carriazo carlos manuel vesga ilenia antonini valentín villafañe juan pablo raba alián devetac marcela benjumea ángela cano johan rivera zumaqué ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-tru-doc', 'Nhiệm Vụ Trừ Độc', 'Anti Drug Operation', 'https://phimimg.com/upload/vod/20240428-1/c61d4eda13faf7775a003b0df3bbc4f4.jpg', 'https://phimimg.com/upload/vod/20240428-1/d6c3015d1491b4d6f197f3ef99ad9354.jpg', '<p>Bộ phim này kể về hai thế hệ cha con cảnh sát chống ma túy, để diệt tận gốc tập đoàn bán ma túy mà người trước ngã xuống, người sau tiếp bước. Nhân vật chính Tống Văn Đào gia nhập tập đoàn buôn ma túy làm nội ứng, hợp tác mạnh mẽ với cảnh sát chống ma túy, phá vỡ tầng tầng lớp lớp thử thách, thông qua việc lập kế hoạch tỉ mỉ trong thời gian dài, cuối cùng đưa bọn buôn ma túy ra trước pháp luật, công lý chiến thắng tà ác, và thực hiện câu chuyện tự mình trưởng thành, lột xác.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tao Wang","avatar":""},{"name":"Hou Yong","avatar":""},{"name":"He Yongsheng","avatar":""},{"name":"Liu Weizhou","avatar":""},{"name":"李相炫","avatar":""},{"name":"李沐子","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324242);
