INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('knuckles', 'Knuckles', 'Knuckles', 'https://phimimg.com/upload/vod/20240426-1/2855271ef54b37e378a9dec07ea08011.jpg', 'https://phimimg.com/upload/vod/20240426-1/1a14199a13164bcba737e187cd909cd8.jpg', '<p>Knuckles dấn thân vào một hành trình khám phá bản thân vui nhộn và đầy hành động khi anh đồng ý huấn luyện Wade làm người bảo trợ của mình và dạy anh cách sống của chiến binh Echidna.</p>', 'Tập 2', 6, 'series', 'ongoing', 15, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Idris Elba","avatar":""},{"name":"Adam Pally","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324242);
