INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-cuong-loan', 'Yêu Cuồng Loạn', 'Love Lies Bleeding', 'https://phimimg.com/upload/vod/20240428-1/39410c0f5bdb0b111d72c09bf9bfe30d.jpg', 'https://phimimg.com/upload/vod/20240428-1/89fc894ec9814867958e59ffe84aa8df.jpg', '<p>Cuộc tình mới chớm nở giữa nữ quản lý phòng tập Lou (Kristen Stewart) và vận động viên thể hình đầy tham vọng Jackie (Katy O’Brian) khiến cả hai bị lún sâu vào chuỗi những rắc rối đẫm máu liên quan đến gia đình tội phạm khét tiếng của Lou.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Katy O''Brian","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Anna Baryshnikov","avatar":""},{"name":"Orion Carrington","avatar":""},{"name":"Catherine Haun","avatar":""},{"name":"Jerry G. Angelo","avatar":""},{"name":"Tait Fletcher","avatar":""},{"name":"Jamie Javier Guerreo","avatar":""},{"name":"Roger Ivens","avatar":""},{"name":"David DeLao","avatar":""},{"name":"Mikandrew","avatar":""},{"name":"Lontrell Anderson","avatar":""},{"name":"Keith Jardine","avatar":""},{"name":"Hilar","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324242);
