INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-khuc-trieu-vong', 'Tà Khúc Triệu Vong', 'The Sin', 'https://phimimg.com/upload/vod/20240427-1/872d32e2cddd39400f15e14ef8a1d388.jpg', 'https://phimimg.com/upload/vod/20240427-1/5c61bee9fdffba845cd2d966c5b9b3a0.jpg', '<p>Là tựa phim kinh dị mới gây rúng động bởi điệu múa gọi hồn đậm chất tâm linh chưa từng có, TÀ KHÚC TRIỆU VONG kể về một nữ diễn viên có khả năng thực hiện nghi thức cấm để triệu hồi quỷ dữ. Từ đây, loạt án mạ.ng bí ẩn liên tiếp ập đến kéo theo những sự kiện kỳ lạ xảy ra tại một ngôi trường bị bỏ hoang.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'HD', 'Hàn Quốc', 1, '[{"name":"Kim Yoon-hye","avatar":""},{"name":"Song Yi-jae","avatar":""},{"name":"Park Ji-hoon","avatar":""},{"name":"Lee Sang-ah","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
