INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dead-boy-detectives', 'Dead Boy Detectives', 'Dead Boy Detectives', 'https://phimimg.com/upload/vod/20240426-1/b8b595733e7cae70a06d35e8bf1ff858.jpg', 'https://phimimg.com/upload/vod/20240426-1/40bb14ec80b9de0b33db25538ac746c2.jpg', '<p>Hai con ma tuổi teen hợp tác với một nhà ngoại cảm để phá giải bí ẩn cho những khách hàng siêu nhiên của họ cho đến khi một phù thủy hùng mạnh khiến kế hoạch của họ rối tung.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"George Rexstrew","avatar":""},{"name":"Jayden Revri","avatar":""},{"name":"Kassius Nelson","avatar":""},{"name":"Briana Cuoco","avatar":""},{"name":"Ruth Connell","avatar":""},{"name":"Yuyu Kitamura","avatar":""},{"name":"Jenn Lyon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
