INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dead-boy-detectives', 'Dead Boy Detectives', 'Dead Boy Detectives', 'dead boy detectives dead boy detectives george rexstrew jayden revri kassius nelson briana cuoco ruth connell yuyu kitamura jenn lyon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-huong-toi-cac-vi-sao', 'Chúng Ta Hướng Tới Các Vì Sao', 'Embracing the Stars Together', 'https://phimimg.com/upload/vod/20240426-1/a31c6b52d2b9e7862d02eeb44e7a1e4f.jpg', 'https://phimimg.com/upload/vod/20240426-1/6ddb7deb7842740bb10952c70cfe7cdc.jpg', '<p>Bặc Hàm Lộc, học sinh lớp 10, muốn trở thành phi công vì khi cô còn nhỏ, chị gái cô-cơ trưởng Bặc Hàm vũ của Hồng liên, bị người ngoài hành tinh bắt giữ vì bảo vệ cô., cô đã làm việc chăm chỉ trong nhiều năm chỉ để giải cứu chị gái mình. Vì một đôi găng tay, Bặc Hàm Lộc và kẻ bắt nạt học đường Lâm Thiên Dữ đã đoàn kết lại. Kẻ bắt nạt học đường và cô gái bướng bỉnh đã tiến hành nhiều vòng PK, từ tranh găng tay, tranh giành sân thượng, đến chiến tranh chơi khăm, đội kịch của Bặc Lộc Hàm và đội phản diện của Lâm Thiên Dữ đã phát triển tình bạn. Để thực hiện ước mơ thành lập câu lạc bộ thiên văn của Bặc Hàm Lộc, mọi người đã cùng nhau tìm kiếm UFO và điều tra kính viễn vọng thiên văn bị mất tích. Những người bạn phát hiện ra rằng Bặc Hàm Lộc mắc chứng &quot;hoang tưởng về người ngoài hành tinh&quot;. Em gái của Lâm thiên dữ và Lâm thiên dữ, là kẻ chủ mưu vụ lừa đảo này, hóa ra cô ấy là bạn tốt của Bặc Hàm Lộc, để giúp Bặc Hàm Lộc thực hiện tâm nguyện cuối cùng của mình, cô ấy đã tạo ra một giấc mơ ngoài hành tinh cho Bặc Hàm Lộc. Sau khi biết được sự thật, Bặc Hàm Lộc phát hiện ra rằng tuổi trẻ không phụ thuộc vào việc ngắm nhìn mà phụ thuộc vào những người bạn đáng yêu này.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Jiayi","avatar":""},{"name":"Wu Qianying","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
