INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-thanh-pho-2024', 'Thợ Săn Thành Phố', 'City Hunter', 'https://phimimg.com/upload/vod/20240426-1/fea453b90723d2d9982d0b0c66995f2c.jpg', 'https://phimimg.com/upload/vod/20240426-1/9b1e1edaaf15a21c56fdf5c842f9cbe4.jpg', '<p>Vừa là tay thiện xạ xuất chúng, vừa cũng là trai hư &quot;hết thuốc chữa&quot;, thám tử tư Saeba Ryo bất đắc dĩ liên minh với em gái của người cộng sự quá cố để điều tra cái chết của anh ấy.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryohei Suzuki","avatar":""},{"name":"Misato Morita","avatar":""},{"name":"Masanobu Ando","avatar":""},{"name":"Fumino Kimura","avatar":""},{"name":"Asuka Hanamura","avatar":""},{"name":"Isao Hashizume","avatar":""},{"name":"Tetta Sugimoto","avatar":""},{"name":"Ayame Misaki","avatar":""},{"name":"Takaya Sakoda","avatar":""},{"name":"Moemi Katayama","avatar":""},{"name":"Yasushi Ami","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
