INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chet-tro-ve', 'Người Chết Trở Về', 'Dead Man', 'https://phimimg.com/upload/vod/20240426-1/2d408c47a7eecb2b538ae81a52ae0a9a.jpg', 'https://phimimg.com/upload/vod/20240426-1/e6cd186dd219fbf90b91be50d0cbb104.jpg', '<p>Bị dồn vào đường cùng, Lee Man Jae (Jo Jin Woong) phải bán cả tên của mình để tồn tại. Khi đứa con đầu lòng chuẩn bị chào đời, Man Jae quyết định thực hiện một phi vụ lớn cuối cùng, nhưng lại bị vướng vào vụ tham ô trị giá 100 tỉ won. Anh sống như một kẻ đã chết, cho đến một ngày kia, một chính trị gia họ Shim bí ẩn (Kim Hee Ae) đề nghị sẽ giúp anh lấy lại danh tính và cuộc đời mình. Lee Man Jae bắt đầu hành trình &quot;trở về từ cõi chết&quot;, đồng thời lật mở những bí mật nhơ nhuốc của xã hội.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Cho Jin-woong","avatar":""},{"name":"Kim Hee-ae","avatar":""},{"name":"Lee Soo-kyung","avatar":""},{"name":"Choi Soo-young","avatar":""},{"name":"Choi Jae-woong","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Han Dong-kyu","avatar":""},{"name":"Baek Seung-ik","avatar":""},{"name":"Lee Ha-young","avatar":""},{"name":"Jung Yun-ha","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
