INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-chet-tro-ve', 'Người Chết Trở Về', 'Dead Man', 'người chết trở về dead man cho jin-woong kim hee-ae lee soo-kyung choi soo-young choi jae-woong park ho-san han dong-kyu baek seung-ik lee ha-young jung yun-ha ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ly-ca', 'Ly Ca', 'The Farewell Song', 'https://phimimg.com/upload/vod/20240426-1/4b09fe9223f811f8573ebcd978010c22.jpg', 'https://phimimg.com/upload/vod/20240426-1/f4c1f3ce041286ff671f00cb38d58e2d.jpg', '<p>Khi Mã Trác 8 tuổi, được mẹ Trần Quả Quả đưa đến sống ở Lâm Giang, cô gặp anh trai hàng xóm Hạ Trạch, hai người trở thành bạn thuở nhỏ và dần dần có cảm tình. Sau khi tốt nghiệp trung học, họ đi theo cả hai hướng và đưa ra quyết định riêng, bất chấp sự phản đối của cha mẹ cũng như những rào cản khi ở nơi khác. Không ngờ, mẹ của Mã Trác, đột ngột qua đời vào thời điểm này, cha của Hạ Trạch, Hạ Cương, bị liệt vào danh sách nghi phạm, không rõ tung tích. Thân phận của Mã Trác và Hạ Trạch từ tình nhân thay đổi thành &quot;con gái của nạn nhân&quot; và &quot;con trai của nghi phạm&quot;, họ chia tay một cách đau đớn và dứt khoát. Vài năm sau, Mã Trác, người đã trở thành một luật sư xuất sắc, quay trở lại Lâm Giang và gặp lại Hạ Trạch, hai người cùng nhau theo đuổi sự thật về cha mẹ với nhiều hiểm nguy và chông gai phải đối mặt.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Tingting","avatar":""},{"name":"Zhou Chengao","avatar":""},{"name":"Mi Mi","avatar":""},{"name":"Cui Yuxin","avatar":""},{"name":"Bing Shao","avatar":""},{"name":"Ni Jingyang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
