INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('monkey-man-bao-thu', 'Monkey Man Báo Thù', 'Monkey Man', 'https://phimimg.com/upload/vod/20240424-1/a030ad0d5043f306c3404dd684793bc2.jpg', 'https://phimimg.com/upload/vod/20240424-1/21c5725b57c83cefbf6b84c0b3e46d30.jpg', '<p>Một chàng trẻ vô danh, đã bắt đầu cuộc hành trình trả thù chống lại những kẻ lãnh đạo tham nhũng đã sát hại mẹ anh và đàn áp những người nghèo khổ và yếu thế hơn.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Canada', 1, '[{"name":"Dev Patel","avatar":""},{"name":"Pitobash","avatar":""},{"name":"Sikandar Kher","avatar":""},{"name":"Makrand Deshpande","avatar":""},{"name":"Adithi Kalkunte","avatar":""},{"name":"Jatin Malik","avatar":""},{"name":"Sobhita Dhulipala","avatar":""},{"name":"Vipin Sharma","avatar":""},{"name":"Ashwini Kalsekar","avatar":""},{"name":"Sharlto Copley","avatar":""},{"name":"Brahim Achabbakhe","avatar":""},{"name":"Zakir Hussain","avatar":""},{"name":"Reva Marchellin","avatar":""},{"name":"Dayangku Zyana","avatar":""},{"name":"Pehan Abdul","avatar":""},{"name":"Agus Mulana","avatar":""},{"name":"Fahad Scal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324242);
