INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-lai-tieu-dao', 'Gặp Lại Tiêu Dao', 'Sword and Fairy 1', 'https://phimimg.com/upload/vod/20240402-1/d37f292a08dce32eb7c07a3665f9a7ad.jpg', 'https://phimimg.com/upload/vod/20240402-1/9fa85bbee38a1b051fe079e9681a88a9.jpg', '<p>Tiểu nhị Lý Tiêu Dao có ước mơ trở thành đại hiệp tình cờ gặp được Triệu Linh Nhi, hậu duệ của Nữ Oa. Họ kết bạn và cùng nhau đi tìm Thủy Linh Châu có thể chấm dứt nạn hạn hán khắp thiên hạ. Trên đường đi, họ lần lượt kết giao với nhiều người bạn cùng chí hướng như oan gia Lâm Nguyệt Như, thư sinh nho nhã Lưu Tấn Nguyên... Cả nhóm cùng nhau vượt qua khó khăn, nguy hiểm để tìm kiếm linh châu, đập tan âm mưu đáng sợ là hủy diệt cả thế giới của Bái Nguyệt giáo chủ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Yu","avatar":""},{"name":"Yang Yutong","avatar":""},{"name":"Xu Hao","avatar":""},{"name":"Hu Yixuan","avatar":""},{"name":"Chuan Li","avatar":""},{"name":"Ye Shengjia","avatar":""},{"name":"Yang Kun","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Ding Xiaoying","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324242);
