INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deep-night-dem-nay-chi-co-chung-ta', 'Deep Night: Đêm Nay Chỉ Có Chúng Ta', 'Deep Night', 'https://phimimg.com/upload/vod/20240423-1/178ed6dca17b04ec851b8dd8f09f9869.jpg', 'https://phimimg.com/upload/vod/20240423-1/6020907e3d01ee846592e31e9da4cdd7.jpg', '<p>Deep Night: Đêm Nay Chỉ Có Chúng Ta kể về câu chuyện tại Deep Night Club, một câu lạc bộ nổi tiếng với những buổi biểu diễn múa mạo hiểm và khác biệt so với những quán bar khác. CLB thuộc sở hữu của bà &#39;Freya&#39; (Tanya). Bà là mẹ của &#39;Khemthit&#39; (Shogun) người sẽ tiếp quản kinh doanh sau khi Freya nghỉ hưu. Khemthit thực sự không thích câu lạc bộ này, nhưng khi anh gặp &#39;Vela&#39; (First), một người bạn đại học và cũng là một trong những người chủ nhà hàng đầu ở đây, anh đã bị quyến rũ và muốn mở lòng với ngưừi ấy và nghề nghiệp này. Tuy nhiên, vì sự khác biệt về địa vị xã hội, điều này làm cho câu chuyện tình yêu này không dễ dàng và cả hai đều cần phải chứng minh niềm tin vào tình yêu này cùng nhau. Tuy nhiên, bà Freya không thể chấp nhận rằng con trai mình yêu một nhân viên và có &#39;Meiji&#39; (Ning), người bạn thân nhất của bà, bên cạnh để vượt qua thời kỳ khó khăn. Khemthit phải chứng minh cho cả mẹ và Vela và anh đã thực hiện điều đó bắt đầu làm việc từ vị trí thấp nhất.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Shogun Paramee Thesdaroon","avatar":""},{"name":"First Piyangkull Saohin","avatar":""},{"name":"Seagames Teerapat Angkanit","avatar":""},{"name":"Neptune Bhurichon Khumsiri","avatar":""},{"name":"Chalarm Siam Pipatcharoenwong","avatar":""},{"name":"Dan Aaron Ramnarong","avatar":""},{"name":"Sun Tananat Lertrungvichien","avatar":""},{"name":"Tanyares Engtrakul","avatar":""},{"name":"Panita Tumwattana","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
