INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-minh-quai-dam', 'Phượng Minh Quái Đàm', 'The Ghost Town', 'https://phimimg.com/upload/vod/20240426-1/c7d57f8e3216cd326659b1ca0903bfc1.jpg', 'https://phimimg.com/upload/vod/20240426-1/7f691f25f98e510ab68dd154409b09ed.jpg', '<p>Tiểu thư của tập đoànTrầm , Chu Thất, nghe tin chị gái là Thập Tam, người cô ấy đã phải sống phụ thuộc vào trong suốt thời thơ ấu, bất ngờ mất tích khi tìm kiếm một loại thảo dược quý. Trong hoàn cảnh khẩn cấp, cô tìm đến tên buôn thuốc Vương Ngũ, nhưng hai người đã xảy ra xung đột. Chu Thất được cứu thoát bởi con trai của phụ tá Cốc Vũ Sinh, cũng là người bạn thời thơ ấu của cô. Vương Ngũ bỏ trốn, nhưng vào đêm đó, ông ta lại chết một cách bí ẩn. Đội trưởng cảnh sát Ngô Húc, người chịu trách nhiệm điều tra, dựa vào nhiều manh mối đã xác định kẻ giết người là Chu Thất. Vì nóng lòng tìm kiếm chị gái, Chu Thất đột nhập vào hiện trường để tìm kiếm dấu vết từ thi thể của Vương Ngũ. Dấu vết chỉ đến một nơi gọi là &quot;Phượng Minh Trấn&quot;. Tình cờ, lúc đó cảnh sát trưởng Ngô Húc đến kiểm tra hiện trường và, bắt được Chu Thất. Trong lúc giằng co, Chu Thất vô tình làm rách áo mình, nhưng Ngô Húc đưa áo của anh để mặc cho cô, và vô tình làm rơi giấy chứng minh cảnh sát. Tận dụng danh tính &quot;Thiếu tá Ngô&quot; Chu Thất thành công đến Phượng Minh Trấn. Tuy nhiên, khắp nơi trong ngôi làng có nhiều điều kỳ lạ, những người dân mà Chu Thất đã tiếp xúc đều bị chết một cách kỳ bí... Trong hoàn cảnh tuyệt vọng, Cảnh sát trưởng Ngô Búc và trợ lý Cốc Vũ Sinh lần lượt đến Phụng Minh Trấn. Qua một loạt các sự kiện huyền bí và kỳ quái, sự thật về cái chết của người dân trong làng dần dần xuất hiện, số phận đau thương của Thập Tam dần rõ ràng, và tình cảm giữa ba người cũng trở nên phức tạp. Nhưng họ không biết rằng, họ đã trở thành mục tiêu của kẻ thủ ác đằng sau bức màn.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Ying-Luo","avatar":""},{"name":"Xu Hao Xiang","avatar":""},{"name":"Lei Shu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
