INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-thu-cung-cua-toi', 'Người Yêu Thú Cưng Của Tôi', 'My Piggy Lover', 'https://phimimg.com/upload/vod/20240425-1/ece0b460a54d79a71c06064abe6245ea.jpg', 'https://phimimg.com/upload/vod/20240425-1/dbcb1cfbe9284f58f1a0bad139a0c24f.jpg', '<p>Cô gái xinh đẹp sau một đêm biến thành chú heo nhỏ? Bởi vì bạn trai không thích heo xinh, nên Chu Châu quyết định đem chú heo xinh của mình tặng cho người khác. Cô ôm chú heo đến một cửa hàng thú cưng vùng hẻo lánh, ông chủ ở đó cũng đồng ý nhận chú heo. Không ngờ Chu Châu yêu phải tra nam, bị anh ta vứt vỏ. Cô đau buồn uống rượu say khóc lóc gọi heo xinh. Sáng hôm sau tỉnh dậy cô phát hiện ra mình lại biến thành chú heo xinh, nằm trong tiệm thú cưng. Đồng thời, phía cửa xuất hiện sếp Lục Minh của cô, Lục Minh nhẹ nhàng bế cô và nhận nuôi cô. Những mẩu chuyện vui thú vị bắt đầu xuất phát từ đây...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
