INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-bon-ba-la-dinh-menh-cua-toi', 'Nếu Bôn Ba Là Định Mệnh Của Tôi', 'Born to Run', 'https://phimimg.com/upload/vod/20240426-1/7434255b8d15042cdd980d194a8ce0f7.jpg', 'https://phimimg.com/upload/vod/20240426-1/de6bd13b3b5dc529cfc7b86aaa2e64e4.jpg', '<p>&quot;Born to Run&quot; kể câu chuyện đạo đức gia đình đầy cảm hứng của hai bà mẹ và cô con gái xây dựng lại tâm hồn và khơi dậy cuộc sống sau một vụ tai nạn ô tô chạm tới đáy cuộc đời họ qua góc nhìn của phụ nữ. Xiu Fang và Xiu Li là một cặp chị em hoàn toàn khác nhau. Xiu Fang là người lạc quan và ngoan cường. Sau khi chồng mất, bà mở quán gà rán để kiếm sống. Trong suốt thời gian đó đang trải qua trầm cảm. Xiu Li là người bi quan, chán nản, gia trưởng và rất muốn kiểm soát hai đứa con của mình. Sau bữa tiệc sinh nhật lần thứ 60 của Xiu Fang, một vụ tai nạn xe hơi đã cướp đi đôi chân của con gái bà An Xin và mạng sống của con trai Xiu Li. Làm thế nào để bắt đầu lại cuộc sống đã trở thành vấn đề lớn nhất mà hai gia đình phải đối mặt... Khi số phận trêu đùa bạn, bạn sẽ chọn làm gì? Tương lai bị chặn lại bởi bức tường oán giận, sợ hãi, bất lực, do dự, tuyệt vọng vậy bạn sẽ làm gì?</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhong Chuxi","avatar":""},{"name":"Yang Chaoyue","avatar":""},{"name":"Xu Di","avatar":""},{"name":"Chen Xiaoyi","avatar":""},{"name":"Hou Wenyuan","avatar":""},{"name":"Song Yang","avatar":""},{"name":"Wang Youjun","avatar":""},{"name":"Li Tiannuo","avatar":""},{"name":"Rong Fei","avatar":""},{"name":"Wang Ning","avatar":""},{"name":"Liu Xun","avatar":""},{"name":"Tan Xihe","avatar":""},{"name":"Wang Deshun","avatar":""},{"name":"Yan Su","avatar":""},{"name":"Ai Liya","avatar":""},{"name":"Niu Piao","avatar":""},{"name":"Zeng Kelang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
