INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-trong-guong', 'Hoa Trong Gương', 'Flower in the Mirror', 'https://phimimg.com/upload/vod/20240425-1/6ec66602190b8da92592795c22862e3f.jpg', 'https://phimimg.com/upload/vod/20240425-1/8e86dac2a2690286a13166bf83e778ef.jpg', '<p>Vào thời Trung Hoa Dân Quốc, Du Lanruo, con gái của một gia đình giàu có ở Dương Thành, bị mất trí nhớ do tai nạn khi còn nhỏ, dẫn đến mất danh tính. Sau đó, anh được nghệ sĩ Erhu Lao Ma nhận nuôi, người đã đổi tên thành Ma Qingqing. He và anh trai Shui Sheng, ba bậc thầy và người học việc đi biểu diễn nghệ thuật trong các quán trà và kiếm sống bằng nghề bồi bàn. Sở thích duy nhất của cô là diễn xuất và cô có tài năng diễn xuất tuyệt vời. Ước mơ lớn nhất của Qingqing là trở thành một ngôi sao nổi tiếng như Du Lanruo, một mặt cô muốn tìm lại cha mẹ ruột của mình, mặt khác đó là tình yêu của Qingqing với diễn xuất. Sau đó, do một tai nạn, anh vô tình quay trở lại Du Mansion, đồng thời bắt đầu mối thù gia đình và đất nước với người yêu thời thơ ấu của mình, Guan Muyun.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ryan Zhang","avatar":""},{"name":"Cheng Jinming","avatar":""},{"name":"Zu Ka Er","avatar":""},{"name":"Yanbei Lu","avatar":""},{"name":"Li Tianye","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
