INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rebel-moon-phan-hai-ke-khac-vet-seo', 'Rebel Moon – Phần Hai: Kẻ Khắc Vết Sẹo', 'Rebel Moon - Part Two: The Scargiver', 'https://phimimg.com/upload/vod/20240425-1/03856a6b0df5b344dcb4e24940f5c373.jpg', 'https://phimimg.com/upload/vod/20240425-1/db0682599e9da62b5a5ce60b09923496.jpg', '<p>Quân kháng chiến chuẩn bị chiến đấu với các thế lực ở Thế Giới Mẹ khi các mối liên kết không thể phá vỡ được thiết lập, anh hùng xuất hiện và huyền thoại được tạo nên.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sofia Boutella","avatar":""},{"name":"Michiel Huisman","avatar":""},{"name":"Ed Skrein","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Staz Nair","avatar":""},{"name":"Elise Duffy","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Cleopatra Coleman","avatar":""},{"name":"Fra Fee","avatar":""},{"name":"Charlotte Maggi","avatar":""},{"name":"Sky Yang","avatar":""},{"name":"Stuart Martin","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Alfonso Herrera","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Rhian Rees","avatar":""},{"name":"Dustin Ceithamer","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
