INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-chuyen-dem-khuya-voi-quy-du', 'Trò Chuyện Đêm Khuya Với Quỷ Dữ', 'Late Night with the Devil', 'https://phimimg.com/upload/vod/20240425-1/71c5b2ccfca03822959e919fa90f3bf9.jpg', 'https://phimimg.com/upload/vod/20240425-1/9561e925cd0f02b99b8ee95d5cbf76d3.jpg', '<p>Một buổi truyền hình trực tiếp của chương trình trò chuyện đêm khuya năm 1977 đã không diễn ra như dự định khi ma quỷ xuất hiện trên sóng.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Dastmalchian","avatar":""},{"name":"Laura Gordon","avatar":""},{"name":"Ian Bliss","avatar":""},{"name":"Fayssal Bazzi","avatar":""},{"name":"Ingrid Torelli","avatar":""},{"name":"Rhys Auteri","avatar":""},{"name":"Georgina Haig","avatar":""},{"name":"Josh Quong Tart","avatar":""},{"name":"Steve Mouzakis","avatar":""},{"name":"Paula Arundell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324242);
