INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-chuyen-dem-khuya-voi-quy-du', 'Trò Chuyện Đêm Khuya Với Quỷ Dữ', 'Late Night with the Devil', 'trò chuyện đêm khuya với quỷ dữ late night with the devil david dastmalchian laura gordon ian bliss fayssal bazzi ingrid torelli rhys auteri georgina haig josh quong tart steve mouzakis paula arundell ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-tim-nan-tam', 'Khó Tìm (Nan Tầm)', 'Hard to Find', 'https://phimimg.com/upload/vod/20240404-1/fccd42b0a27f8bbc1b6940300d402c71.jpg', 'https://phimimg.com/upload/vod/20240404-1/f18e7a867050a90661f8c9f27c8f6b92.jpg', '<p>Khó Tìm (Nan Tầm) là câu chuyện kể về Công chúa Phượng Diên và Thiếu gia Lâm Xuyên Liên Hi. Trên vùng đất Cửu Trạch, Tích Cựu, con trai cả của tộc Sóc Vân, chuẩn bị kết hôn với vị hôn thê Lương Thiềm, nhưng Lương Thiềm bị bắt cóc bởi vị thiếu gia Lâm Xuyên bí ẩn - Hách Liên Hi vào đêm trước đám cưới. Hách Liên Hi ép Lương Thiềm giao ra Liên Lý Chi, người có thể hồi sinh gia tộc Lâm Xuyên, tuy nhiên Lương Thiềm không biết Liên Hi đang nói về cái gì do cô bị mất trí nhớ. Tuy nhiên, khi Hách Liên Hi đưa Lương Thiềm đến cõi tâm thức của cây thiêng, quá khứ bụi bặm dần dần được đánh thức, Lương Thiềm cuối cùng cũng nhớ ra rằng cô từng là vợ của Liên Hi, cô chính là công chúa Phượng Diên của Lâm Xuyên. Cô và việc Lâm Xuyên bị diệt vong có một mối quan hệ không thể tránh khỏi... Cả hai vốn là một cặp được định sẵn để nên duyên, tuy nhiên, họ đã đưa ra quyết định riêng cho cuộc sống của mình, điều này gây ra những thay đổi lớn trong gia tộc. Khi cả hai đoàn tụ, một cuộc chiến cám dỗ và lôi kéo, một câu chuyện tình mang hương vị phương Đông và sự cứu rỗi đã bắt đầu.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Yiqin","avatar":""},{"name":"Shen Yujie","avatar":""},{"name":"Fang Xiao Dong","avatar":""},{"name":"Wang Zexuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324242);
