INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tuong-quan', 'Đại Tướng Quân', 'Shōgun', 'https://phimimg.com/upload/vod/20240302-1/3bb3816f46ed192c2da158f401bc4fa6.jpg', 'https://phimimg.com/upload/vod/20240302-1/1c4d7090f4f53cfe76d1834c6a1b0e98.jpg', '<p>Tại Nhật Bản vào năm 1600, vào buổi bình minh của cuộc nội chiến mang tính chất thế kỷ, Lãnh chúa Yoshii Toranaga đang chiến đấu để giành lấy mạng sống khi những kẻ thù của ông trong Hội đồng Nhiếp chính đoàn kết chống lại ông thì một con tàu châu Âu bí ẩn được tìm thấy mắc kẹt ở một ngư trường gần đó. làng bản.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hiroyuki Sanada","avatar":""},{"name":"Cosmo Jarvis","avatar":""},{"name":"Anna Sawai","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Takehiro Hira","avatar":""},{"name":"Tommy Bastow","avatar":""},{"name":"Fumi Nikaido","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
