INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-nguyet', 'Truy Nguyệt', 'Off the Stage', 'https://phimimg.com/upload/vod/20240421-1/dfea4ea423028a0f339ccd97e023ca7e.jpg', 'https://phimimg.com/upload/vod/20240421-1/143cea1b74eeafafc5aef43786d51799.jpg', '<p>Cô Thích là một nữ diễn viên nhạc kịch nổi tiếng, người đã trở nên nổi tiếng khắp cả nước khi còn trẻ với tác phẩm &quot;Truy Nguyệt&quot;. Sau nhiều năm thành công, cô bất ngờ trở về quê hương và muốn đoàn tụ với gia đình. Thế nhưng cậu con trai lớn bị bỏ rơi Thu Sinh và cậu con trai nhỏ Hạ Sinh đều trở nên khó gần gũi với cô. Một sự cố bất ngờ dần dần khiến sự thật bí mật của quá khứ lộ diện...</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Saifei","avatar":""},{"name":"Yuan Wenkang","avatar":""},{"name":"Lou Yujian","avatar":""},{"name":"Tu Ling","avatar":""},{"name":"Gao  Zifeng","avatar":""},{"name":"Xu Ge","avatar":""},{"name":"Lu Hanbiao","avatar":""},{"name":"Qian Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324242);
