INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arthur-chu-cho-kien-cuong', 'Arthur: Chú Chó Kiên Cường', 'Arthur the King', 'https://phimimg.com/upload/vod/20240425-1/650fd5d94e24659a8f5dfd1495cf23d8.jpg', 'https://phimimg.com/upload/vod/20240425-1/6fa8665d6cc9fc878b9ed2077617bb36.jpg', '<p>Chú Chó Kiên Cường Arthur the King 2024 được phát hành vào năm 2024, thuộc thể loại phiêu lưu, kịch tính với độ tuổi phù hợp từ 13 tuổi trở lên. Đạo diễn bởi Simon Cellan Jones và kịch bản được viết bởi Michael Brandt, phim có sự tham gia của các diễn viên như Mark Wahlberg, Simu Liu, Nathalie Emmanuel và Bear Grylls trong vai chính của mình. Phim dựa trên câu chuyện có thật về Mikael Lindnord, một vận động viên đua phiêu lưu người Thụy Điển, người đã kết nối không thể tách rời với một chú chó hoang tên là Arthur trong một cuộc đua khắc nghiệt. Câu chuyện kéo dài 10 ngày và dài 435 dặm, khám phá các chủ đề như chiến thắng, lòng trung thành và tình bạn khi đội đối mặt với những thử thách khắc nghiệt.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Canada', 1, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Nathalie Emmanuel","avatar":""},{"name":"Simu Liu","avatar":""},{"name":"Ali Suliman","avatar":""},{"name":"Juliet Rylance","avatar":""},{"name":"Bear Grylls","avatar":""},{"name":"Michael Landes","avatar":""},{"name":"Paul Guilfoyle","avatar":""},{"name":"Rob Collins","avatar":""},{"name":"Elizabeth Chahin","avatar":""},{"name":"Viktor Åkerblom","avatar":""},{"name":"Zamantha Díaz","avatar":""},{"name":"Cece Valentina","avatar":""},{"name":"Roger Wasserman","avatar":""},{"name":"Sharon Gallardo","avatar":""},{"name":"Andrés Castillo","avatar":""},{"name":"Angie B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324242);
