INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-tuoc-thanh-su-xin-hay-rung-dong', 'Khổng Tước Thánh Sứ Xin Hãy Rung Động', 'Peacock in Wonderland', 'https://phimimg.com/upload/vod/20240423-1/e86e8eff2b0bbe1d59f464fc1c353259.jpg', 'https://phimimg.com/upload/vod/20240423-1/38715ecf881489763469e85b867330f4.jpg', '<p>Học bá Vật lý Hoa Nghê bất ngờ xuyên không đến thành Khổng Tước và vô tình trở thành thánh sứ của phái Khổng Tước. Hoa Nghê quanh quẩn giữa phái Khổng Tước coi cô như cái đinh trong mắt, và tổ chức sát thủ bí ẩn Bách Hoa Sát. Dưới sự giúp đỡ của Lễ bộ lang trung Lý Mục Dương, Hoa Nghê đã chuyển nguy thành an. Khi Hoa Nghê đang rung động trước nam tử tuấn nhã, ôn hòa và biết lễ nghĩa này, cô lại phát hiện anh chính là thủ lĩnh của Bách Hoa Sát. Hoa Nghê từ từ cảm nhận được mục tiêu của Bách Hoa Sát là cứu rỗi dân chúng và bảo vệ chân lý. Vì vậy, Hoa Nghê quyết tâm cùng Lý Mục Dương giúp đỡ dân chúng thành Khổng Tước. Trong quá trình này, họ dần trở nên thấu hiểu và đồng cam cộng khổ. Tuy nhiên, khi họ chuẩn bị cho đại hôn sắp tới, những bí mật từ quá khứ bất ngờ được hé lộ...</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhou Junwei","avatar":""},{"name":"Zhang Chuhan","avatar":""},{"name":"Xu Muchan","avatar":""},{"name":"Jerron Wu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324242);
