INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-quy-ca-ca-mau-di-di', 'Chưởng Quỹ Ca Ca Mau Đi Đi', 'Bazaar Beloved Birds', 'https://phimimg.com/upload/vod/20240423-1/a509d90cf7b76970398848c2cc4901c5.jpg', 'https://phimimg.com/upload/vod/20240423-1/0a5a1e6ceccdaab6ea6ea36ec02fb8a5.jpg', '<p>Dư Tịch Tịch và Dư Triều cùng lớn lên dưới một mái nhà, nhưng tính cách của họ rất khác biệt. Dư Triều ít nói, nghiêm túc và luôn giữ lời, trong khi Dư Tịch Tịch lại hoạt bát, lanh lợi và đôi khi hơi quậy phá. Trước khi mẹ họ qua đời, bà đã giao phó Hội Tiên Lâu và Dư phủ cho Dư Triều, đồng thời yêu cầu Dư Triều sớm cưới Dư Tịch Tịch càng sớm càng tốt và hy vọng rằng trong tương lai, họ có thể hỗ trợ và chăm sóc lẫn nhau. Nhưng hai người lại không thích nhau, đồng thời, việc bê bối cách đây 15 năm lại được đề cập đến. Với sự phức tạp trong giang hồ, những mối quan hệ rắc rối và tình cảm đan xen, cùng với những tin đồn bí ẩn, Dư Tịch Tịch và Dư Triều đã trải qua những thời kỳ khó khăn. Cuối cùng, họ tìm thấy con đường riêng của mình trong giang hồ, nơi mà họ cảm thấy được giải thoát và hiểu rõ hơn về bản chất thực sự của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liang Sen","avatar":""},{"name":"Bubble Zhu","avatar":""},{"name":"Hou Li","avatar":""},{"name":"Ma Xinyu","avatar":""},{"name":"Wang Cheng","avatar":""},{"name":"Linfei Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
