INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-toc-chien-canh-doc-bao', 'Cực Tốc Chiến Cảnh: Độc Bạo', 'Extreme Speed Police-The War on Drugs', 'https://phimimg.com/upload/vod/20240423-1/289c2accc4dd72f19a350e1aa9779f2b.jpg', 'https://phimimg.com/upload/vod/20240423-1/5838c9ecd0ec10f329b542eb52946077.jpg', '<p>Bộ phim được chuyển thể từ vụ án buôn bán và sản xuất ma túy lớn nhất Tứ Xuyên theo sự chỉ đạo của Giám sát số 516 Bộ Công An. Tại một con đường quốc lộ ở thành phố Đạt Xuyên, Trưởng đội trinh sát ma túy Tào Nhậm Phàm cùng đội của mình đang chiến đấu gay gắt với các tên buôn ma túy tay không đang cố giữ một xe buýt, trong cuộc xung đột nảy lửa, họ đã giải cứu con tin và bắt giữ được chuyên gia sản xuất ma túy Bành Gia Hạo. Đội trinh sát ma túy tiếp tục điều tra sâu và phân tích, hủy diệt âm mưu mà tên chủ mưu ma túy đã lập kế hoạch kỹ lưỡng để tìm ra gián điệp của cảnh sát, và sử dụng Bành Gia Hạo làm mồi để bắt giữ &quot;Kiều Ca&quot; - kẻ cung cấp nguyên liệu làm ma túy lớn nhất Đông Nam Á. Tổ ma túy ẩn náu ở núi Lục Giáp đã bị phát hiện, đội trinh sát ma túy cùng với hơn một trăm cảnh sát đặc nhiệm đã bắt đầu một cuộc chiến sinh tử với tổ chức buôn bán ma túy tàn bạo và tàn nhẫn này, thề phải phá hủy tổ chức tội phạm lớn này.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shi Yuanting","avatar":""},{"name":"Li Jiayi","avatar":""},{"name":"Jiang Yongbo","avatar":""},{"name":"Li Feng","avatar":""},{"name":"Jane Wu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324242);
