INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-phau-thuat-truc-tuyen', 'Phòng Phẫu Thuật Trực Tuyến', 'Live Surgery Room', 'https://phimimg.com/upload/vod/20240410-1/4dbbe4b89cee72ddf3c97ddc8a5d599d.jpg', 'https://phimimg.com/upload/vod/20240410-1/63d67d49843630f2e12e1ddab85590ce.jpg', '<p>Bác sĩ thiên tài Trịnh Nhân đến, phá vỡ bầu trời vốn không yên tĩnh của bệnh viện Hải Thành. Bởi vì mục đích của hắn, là muốn vạch trần một vụ án oan phát sinh ở bệnh viện này mười tám năm trước. Chủ nhiệm khoa cấp cứu cá muối Tô Vân và Trịnh Nhân hợp thành một đôi &quot;oan gia vui mừng&quot;, trong lúc yêu nhau giết nhau đã phá được hết chứng bệnh nan y này đến chứng bệnh nan y khác, mở ra một đoạn con đường y học &quot;sảng khoái, cháy, khốc, hi&quot;. Trong thời gian này, Trịnh Nhân không chỉ vạch trần &quot;chân tướng tàn khốc&quot; năm đó, mà còn đồng thời cùng với đám người Tô Vân, Lâm Uyên, Tạ Y tạo thành một tổ công kiên có độ khó cực cao. Dưới sự hướng dẫn mô phỏng huấn luyện và tinh thần y học kiên định bất di bất dịch, vì cứu vớt tính mạng, vì chữa khỏi bệnh nhân, vì ấm lòng người, vì tấm lòng ban đầu trở thành thiên sứ áo trắng trong lòng mình, phấn đấu, kiên trì.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vin Zhang","avatar":""},{"name":"Dai Xu","avatar":""},{"name":"Liu Mintao","avatar":""},{"name":"Yang Yutong","avatar":""},{"name":"Yuan Shanshan","avatar":""},{"name":"Zhao Zhiwei","avatar":""},{"name":"Liu Guancheng","avatar":""},{"name":"Vivienne Tien","avatar":""},{"name":"Peilu Wang","avatar":""},{"name":"Liang Gao","avatar":""},{"name":"Li Jianyi","avatar":""},{"name":"Zhang Shen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
