INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-2024', 'Truy Lùng', 'Manhunt', 'https://phimimg.com/upload/vod/20240402-1/6c4ec2df5cdd34058c046954d10c443e.jpg', 'https://phimimg.com/upload/vod/20240402-1/42e932d654a28a18f502191a041d8854.jpg', '<p>Bộ phim gay cấn đề tài thuyết âm mưu về một trong những tội ác nổi tiếng nhất, nhưng ít ai hiểu rõ nhất lịch sử. Đây là câu chuyện đầy kinh ngạc về cuộc săn lùng John Wilkes Booth sau vụ ám sát Abraham Lincoln – trong khi số phận đất nước đang bấp bênh.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tobias Menzies","avatar":""},{"name":"Anthony Boyle","avatar":""},{"name":"Lovie Simone","avatar":""},{"name":"Brandon Flynn","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Hamish Linklater","avatar":""},{"name":"Anne Dudek","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
