INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bo-khuynh-tam', 'Bộ Bộ Khuynh Tâm', 'Step By Step Love', 'https://phimimg.com/upload/vod/20240405-1/6fa174d60e50963a503c4680d4342968.jpg', 'https://phimimg.com/upload/vod/20240405-1/39b35d7b6604674bfcd35ec6f5d1f1ee.jpg', '<p>Câu chuyện kể về nhà thiết kế không gian Bộ Nhiễm trong một lần tình cờ kết giao với ông chủ Lộ Sâm Dương cũng có khả năng thiết kế. Cả hai nếm trải thất bại nhưng vẫn bước từng bước trên con đường theo đuổi ước mơ ngày càng vững chãi. Dẫu trải qua thăng trầm, họ vẫn giữ được tình yêu cháy bỏng và thủy chung với lý tưởng ban đầu. Cuối cùng, họ đã nhận được sự báo đáp chân thành nhất trong nghề.&nbsp;</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Zhiwei","avatar":""},{"name":"Yangyang Lu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
