INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-si-tinh', 'Đôi Mắt Si Tình', 'Eye Love You', 'https://phimimg.com/upload/vod/20240228-1/3e49ffba0192faee57840a3f42c2269d.jpg', 'https://phimimg.com/upload/vod/20240228-1/d9cf685fd76234aa0c0e489f9ac706df.jpg', '<p>Tình cảm nảy sinh khi cô nàng có năng lực ngoại cảm nhưng không còn muốn yêu bỗng gặp chàng sinh viên Hàn Quốc tốt bụng và suy nghĩ bằng ngôn ngữ mà cô không thể hiểu được.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fumi Nikaido","avatar":""},{"name":"Chae Jong-hyeop","avatar":""},{"name":"Taishi Nakagawa","avatar":""},{"name":"Mizuki Yamashita","avatar":""},{"name":"Tetta Sugimoto","avatar":""},{"name":"Shiraku Tatekawa","avatar":""},{"name":"Hiroya Shimizu","avatar":""},{"name":"Narumi Yui","avatar":""},{"name":"Itose Soichi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
