INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('city-of-star-thanh-pho-thinh-vuong', 'City Of Star: Thành Phố Thịnh Vượng', 'City Of Star', 'https://phimimg.com/upload/vod/20240203-1/28d54ce4c4fcfac38955f7828af3082a.jpg', 'https://phimimg.com/upload/vod/20240203-1/b17bc6aa01f7f9694e7fea696261e263.jpg', '<p>Bạn đã từng nghe đến ứng dụng Zendaya chưa? Đây là một ứng dụng mạng xã hội yêu cầu mọi bài đăng chỉ chứa nội dung tích cực. Những hạn chế trong ý tưởng của ứng dụng đã khiến nó ít phổ biến hơn cho đến khi nhân vật phản diện nổi tiếng nhất Thái Lan &quot;FeungNakhon&quot; đăng ký và đăng thông điệp đầu tiên: &quot;Hãy gửi năng lượng tích cực cho nhau&quot; đã tạo nên một làn sóng chấn động. Zendaya bị nhiều người dùng Thái Lan tấn công và lan truyền nhanh chóng...thậm chí còn làm rung chuyển văn phòng nhỏ của Zendaya ở Thung lũng Silicon. Kommata, một nhân viên người Thái ban đầu dự định quay lại Thái Lan để nghỉ dưỡng, cũng đã phải ngồi co ro để giải quyết việc ứng dụng đột nhiên trở nên phổ biến này. Hơn nữa... ai có thể ngờ rằng người gây ra hỗn loạn như Fueng Nakorn lại xuất hiện trước cửa và bấm chuông, xin mẹ anh ta nấu cơm cho ăn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Job Krisz Ahandrik","avatar":""},{"name":"Porsche Sitha Kanchana-alongkorn","avatar":""},{"name":"Varodom Khemmonta","avatar":""},{"name":"Thanathip Srithongsuk","avatar":""},{"name":"Vashirawish Jaruruangphong","avatar":""},{"name":"Rathasat Butwong","avatar":""},{"name":"Hassaya Isereekul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
