INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-bach-nguyet-quang', 'Tạm Biệt Bạch Nguyệt Quang', 'Fall in Love Again', 'https://phimimg.com/upload/vod/20240320-1/66b820020762c51c7902bf492ac89d4b.jpg', 'https://phimimg.com/upload/vod/20240320-1/9de6a7f1e0794d1ac6489f311ae1c0bb.jpg', '<p>Ngay trước đám cưới 6 năm trước, Chu Miên đã bị phản bội và rơi xuống biển. Cô đã được Mạch Khác cứu sống và cô được biết đến mối liên quan giữa tai nạn của cha mẹ cô và với chồng chưa cưới Lục Vân Khởi. Sau 6 năm, Chu Miên trở về dưới danh nghĩa là Hạ Nhân - một nhà thiết kế hàng đầu thế giới, và đối đầu trực tiếp với Lục Vân Khởi. Lục Vân Khởi nghi ngờ Hạ Nhân chính là vợ đã mất và đã thử tiếp cận cô nhiều lần. Chu Miên cũng không chịu thua, cô cũng quyết đoán gia nhập công ty của Lục Vân Khởi. Trong quá trình tìm hiểu lẫn nhau, họ gần như đã xảy ra xung đột. Chu Miên phát hiện rằng trong 6 năm qua, Lục Vân Khởi chưa bao giờ từ bỏ việc tìm kiếm cô, tai nạn của cha mẹ cô tại nhà máy đồ chơi năm xưa cũng có bí mật khác, và Mạch Khác dùng nhiều cách để xúi giục Chu Miên ra tay với Lục Vân Khởi. Cuối cùng, Chu Miên đã thay đổi quyết định trong lúc gặp nguy hiểm, cùng với Lục Vân Khởi giải quyết vấn đề, phơi bày sự thật và làm hòa với nhau.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Flora Dai","avatar":""},{"name":"Aaron Deng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
