INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-tau-grimm', 'Biến Tấu Grimm', 'The Grimm Variations', 'https://phimimg.com/upload/vod/20240418-1/09a1a6f460b0f5c094a940cf7dc5a846.jpg', 'https://phimimg.com/upload/vod/20240418-1/4145c1fde0c12e3f50250f9106fc8e08.jpg', '<p>Lấy cảm hứng từ những câu chuyện kinh điển của anh em nhà Grimm, hợp tuyển này bao gồm sáu câu chuyện cổ tích có biến tấu đen tối, vạch trần mặt tối trong ham muốn của con người.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Misato Fukuen","avatar":""},{"name":"Tatsuhisa Suzuki","avatar":""},{"name":"Kenji Nojima","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324242);
