INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-song-cua-chung-ta', 'Thế Giới Sống Của Chúng Ta', 'Our Living World', 'https://phimimg.com/upload/vod/20240418-1/779a799c51ba2cf102dcf4ba919f62b2.jpg', 'https://phimimg.com/upload/vod/20240418-1/be6f5cda308ee32aa2218ec240bc9c5a.jpg', '<p>Loạt phim mãn nhãn về thiên nhiên do Cate Blanchett thuyết minh này khám phá trí thông minh tài tháo vát và mối liên hệ mật thiết của sự sống trên hành tinh chúng ta.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Cate Blanchett","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324242);
