INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-song-cua-chung-ta', 'Thế Giới Sống Của Chúng Ta', 'Our Living World', 'thế giới sống của chúng ta our living world cate blanchett ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-reo-dao-nho-cua-anh-da-toi-roi', 'Chuông Reo: Đảo Nhỏ Của Anh Đã Tới Rồi', 'Bell Ringing', 'https://phimimg.com/upload/vod/20240419-1/455618706f6ddb88da4aeb78539944d5.jpg', 'https://phimimg.com/upload/vod/20240419-1/ea6b4d15bb120b98da2a8dd8c16024b4.jpg', '<p>Thẩm Thất là một cô gái vô tư, yêu ngay từ cái nhìn đầu tiên với Chi Ye bí ẩn, người đột nhiên đến vào một ngày nọ, và vì vậy cô bắt đầu theo đuổi anh ta, hy vọng chiến lược tình yêu của mình sẽ thành công. Tuy nhiên, việc Chi Ye liên tục từ chối và tránh mặt cô khiến Thẩm Thất cho rằng tất cả chỉ là mơ mộng, cho đến khi cô nói với anh rằng &quot;Ước mơ của em là được ở bên anh&quot;. Với những lời đó, trái tim Chi Ye bắt đầu dịu lại. Khi những bánh răng tình yêu đó bắt đầu chuyển động, cả hai dành mỗi ngày bên nhau, cảm nhận những cơn gió và ngắm mây và hoàng hôn, dần dần tiến về sảnh cưới với sự chúc phúc của người dân trên đảo. Nhưng khi nhớ lại trăm năm trước, mối tình đẹp lại có một câu chuyện quá khứ khiến người ta không dám nhìn lại.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Daikun","avatar":""},{"name":"Amber Song","avatar":""},{"name":"Yu Yilei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
