INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-do-toi-da-chuyen-sinh-thanh-slime-tom-tat-mua-1-trong-mot-tieng', 'Lúc đó Tôi đã Chuyển Sinh Thành Slime: Tóm Tắt Mùa 1 Trong Một Tiếng', '転生したらスライムだった件', 'https://phimimg.com/upload/vod/20240418-1/9bdaaf6fdf8199507427d3cf98e536ff.jpg', 'https://phimimg.com/upload/vod/20240418-1/c5e4e715d392679683e85cf195cc0c13.jpg', '<p>Cuộc sống của Slime đã bắt đầu. Satoru Mikami, một người làm công ăn lương, khi phát hiện ra thì đã được hồi sinh ở một thế giới khác. Tuy nhiên, đó lại là bộ dạng của Slime. Slime Genesis trở thành bạn của chủng tộc quái vật, sử dụng những kĩ năng có được để giải quyết các vấn đề khác nhau.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324242);
