INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-chinh-minh', 'Giải Cứu Chính Mình', 'Rescue on One''s Own', 'https://phimimg.com/upload/vod/20240418-1/8d8efd5e7c3c84ba666a83b356eb8ac6.jpg', 'https://phimimg.com/upload/vod/20240418-1/2b0dfd94043cc465a10993ea8544d89a.jpg', '<p>Câu chuyện về sĩ quan cảnh sát đặc nhiệm đã nghỉ hưu Chu Đông Dương một mình ra nước ngoài để tìm Đào Đào, đứa con trai bị bắt cóc của đồng đội Lưu Hiểu Cương, đi sâu vào &quot;hang cọp&quot;, chiến đấu chống lại các nhóm tội phạm, cuối cùng phá hủy hang ổ của kẻ thù và giải cứu những đứa trẻ bị bắt cóc. Hình ảnh một chàng trai Trung Quốc cứng rắn, coi trọng tình bạn, coi trọng lời hứa, ghét cay ghét đắng cái ác, đặc biệt là Chu Đông Dương, người đã khiến thuyền trưởng phải hy sinh vì lỗi lầm của mình, sau khi giải nghệ, anh đã từng mê muội và sống một cuộc sống tiêu cực. Nhưng lần này, trải qua quá trình đi lên một mình dấn thân vào nguy hiểm, cứu Đào Đào và phá hủy sào huyệt của kẻ thù, anh ấy đã tìm lại được sự phấn chấn như xưa, cứu rỗi chính mình và tìm lại được hướng đi tích cực trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Luo Liqun","avatar":""},{"name":"Wei Lu","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Junpeng Huang","avatar":""},{"name":"Xin Lu","avatar":""},{"name":"Yang Si","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324242);
