INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-ben-kia-buc-tuong', 'Tình yêu, bên kia bức tường', 'Love, Divided', 'https://phimimg.com/upload/vod/20240416-1/1a90c0d3c761e361f1c377052b0e1098.jpg', 'https://phimimg.com/upload/vod/20240416-1/622f2dba594dc41e495455b0bf4a09f6.jpg', '<p>Valentina là nghệ sĩ piano trẻ đang bắt đầu lại từ đầu. David, hàng xóm của cô, là nhà phát minh ghét tiếng ồn. Và bức tường mỏng như tờ giấy sắp trở thành bà mối của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Aitana","avatar":""},{"name":"Fernando Guallar","avatar":""},{"name":"Natalia Rodríguez","avatar":""},{"name":"Adam Jezierski","avatar":""},{"name":"Paco Tous","avatar":""},{"name":"Miguel Ángel Muñoz","avatar":""},{"name":"Àlex Maruny","avatar":""},{"name":"Macarena de Rueda","avatar":""},{"name":"Joan Sentís","avatar":""},{"name":"Maite Sandoval","avatar":""},{"name":"Rocío Marín","avatar":""},{"name":"Manu Imizcoz","avatar":""},{"name":"Eduardo Ferrés","avatar":""},{"name":"Carlos Cañas","avatar":""},{"name":"Mario Santos","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
