INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-chan-chinh-phan-4', 'Thám Tử Chân Chính (Phần 4)', 'True Detective (Season 4)', 'https://phimimg.com/upload/vod/20240411-1/035d04fc7bbde8201af70f3c5fd1b214.jpg', 'https://phimimg.com/upload/vod/20240411-1/d01a41902b5885ae1a28a3c6cb8002b4.jpg', '<p>Là một series mới được đánh giá khá cao của HBO, kể về hai thám tử Rust Cohle và Martin Hart trong cuộc săn lùng tên sát nhân giết người hàng loạt kéo dài 17 năm ở Louisiana.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jodie Foster","avatar":""},{"name":"Kali Reis","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Finn Bennett","avatar":""},{"name":"Isabella Star LaBlanc","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"John Hawkes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
