INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-trai-chi-di-dong-nhan-ngu', 'Liêu Trai Chí Dị: Đồng Nhân Ngữ', 'Strange Tales of a Lonely Studio', 'https://phimimg.com/upload/vod/20240412-1/2f6bb098647686c569a2b16c9dc7448e.jpg', 'https://phimimg.com/upload/vod/20240412-1/2de4cc6c19f6067213b201b499ef5c55.jpg', '<p>Bộ phim này kể về Tú tài Phương Đống, vì ham muốn mỹ sắc mà nguy đến tính mạng. A hoàn lương thiện của hắn vì yêu hắn sâu đậm mà hy sinh chính mình đổi lấy Phương Đống. Lãng tử quay đầu như Phương Đống bắt đầu một cuộc hành trình để tìm lại tình yêu đích thực, lại vô tình cứu giúp nữ yêu lương thiện bị áp bức, dưới sự giúp đỡ của thầy bắt yêu và những người khác, cuối cùng trở thành câu chuyện tình bi thương mà người có tình rốt cuộc cũng thành người nhà.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Yilong","avatar":""},{"name":"Linfei Li","avatar":""},{"name":"Gao Weiman","avatar":""},{"name":"Zou Siyang","avatar":""},{"name":"Hao Ze","avatar":""},{"name":"Yan Yan","avatar":""},{"name":"Li Hung-Kit","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324242);
