INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phong-van-sot-deo', 'Cuộc Phỏng Vấn Sốt Dẻo', 'Scoop', 'https://phimimg.com/upload/vod/20240412-1/7d61e55c3be4ce635a9a6a331a8b2be4.jpg', 'https://phimimg.com/upload/vod/20240412-1/30b7d45f1cc787bb8d49b25a16b4e25b.jpg', '<p>Dựa trên sự kiện có thật, phim chính kịch hư cấu này có lời kể của người trong cuộc về cách những nhân viên nữ của Newsnight có được cuộc phỏng vấn khét tiếng với hoàng tử Andrew.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Gillian Anderson","avatar":""},{"name":"Billie Piper","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"Keeley Hawes","avatar":""},{"name":"Romola Garai","avatar":""},{"name":"Richard Goulding","avatar":""},{"name":"Amanda Redman","avatar":""},{"name":"Connor Swindells","avatar":""},{"name":"Lia Williams","avatar":""},{"name":"Charity Wakefield","avatar":""},{"name":"Jordan Kouamé","avatar":""},{"name":"Paul Popplewell","avatar":""},{"name":"Zach Colton","avatar":""},{"name":"Kate Fleetwood","avatar":""},{"name":"Aoife Hinds","avatar":""},{"name":"Alex Waldmann","avatar":""},{"name":"Colin We","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
