INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-nhac', 'Âm Nhạc', 'Música', 'https://phimimg.com/upload/vod/20240412-1/4b9b44f662f9e87ff143e93730fc7190.jpg', 'https://phimimg.com/upload/vod/20240412-1/eee16473272bfc50afbdd66f7a6c5010.jpg', '<p>Một câu chuyện tình yêu tuổi mới lớn kể về một nhà sáng tạo đầy tham vọng mắc chứng mê sảng, người phải đối mặt với một tương lai không chắc chắn, đồng thời vượt qua những áp lực về tình yêu, gia đình và văn hóa Brazil của mình ở Newark, New Jersey.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rudy Mancuso","avatar":""},{"name":"Camila Mendes","avatar":""},{"name":"Francesca Reale","avatar":""},{"name":"Maria Mancuso","avatar":""},{"name":"J.B. Smoove","avatar":""},{"name":"Andy Grotelueschen","avatar":""},{"name":"Camila Senna","avatar":""},{"name":"Regina Schneider","avatar":""},{"name":"Gregory Jones","avatar":""},{"name":"Finn Brown","avatar":""},{"name":"Milly Guzman","avatar":""},{"name":"The Silvin G","avatar":""},{"name":"Bia Borin","avatar":""},{"name":"Beatriz Cavalieri","avatar":""},{"name":"Josanna Vaz","avatar":""},{"name":"Andy Muschietti","avatar":""},{"name":"Gabriela Amert","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324242);
