INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tho-cua-miller', 'Nàng Thơ Của Miller', 'Miller''s Girl', 'https://phimimg.com/upload/vod/20240228-1/f92e66222daf5882efe674f290da2722.jpg', 'https://phimimg.com/upload/vod/20240228-1/a1f1f4f3605a037483617e99ccc86633.jpg', '<p>Một nhà văn trẻ sớm phát triển tham gia cùng giáo viên viết văn sáng tạo ở trường trung học của mình trong một bộ phim đen tối dành cho lứa tuổi mới lớn, xem xét những ranh giới mờ nhạt của mối liên hệ cảm xúc giữa giáo sư và người được bảo trợ.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Martin Freeman","avatar":""},{"name":"Jenna Ortega","avatar":""},{"name":"Bashir Salahuddin","avatar":""},{"name":"Gideon Adlon","avatar":""},{"name":"Dagmara Domińczyk","avatar":""},{"name":"Christine Adams","avatar":""},{"name":"Augustine Hargrave","avatar":""},{"name":"Elyssa Samsel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324242);
