INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ngam-tokyo-phan-2', 'Thế Giới Ngầm Tokyo (Phần 2)', 'Tokyo Vice (Season 2)', 'https://phimimg.com/upload/vod/20240302-1/1b5f6c0480492dda3bfb2ccaf0c80339.jpg', 'https://phimimg.com/upload/vod/20240302-1/6f471babe38d738f182aa5dad80ef662.jpg', '<p>Tokyo Vice lấy bối cảnh vào năm 1993, chàng trai Adelstein được nhận vào làm phóng viên tân binh cho Yomiuri Shimbum, anh được sự dẫn dắt bởi Sekiguchi một vị thám tử. Giờ đây, Adelstein vô cùng gặp khó khăn trong quá trình truy tìm kẻ giết hại Lucie Blackman khi anh phải đối mặt với những tên tội phạm khét tiếng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ansel Elgort","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Rachel Keller","avatar":""},{"name":"Show Kasamatsu","avatar":""},{"name":"Rinko Kikuchi","avatar":""},{"name":"Ayumi Ito","avatar":""},{"name":"Yosuke Kubozuka","avatar":""},{"name":"Miki Maya","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
