INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-ngam-tokyo-phan-2', 'Thế Giới Ngầm Tokyo (Phần 2)', 'Tokyo Vice (Season 2)', 'thế giới ngầm tokyo (phần 2) tokyo vice (season 2) ansel elgort ken watanabe rachel keller show kasamatsu rinko kikuchi ayumi ito yosuke kubozuka miki maya ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mieu-yeu-ky-dam', 'Miêu Yêu Kỳ Đàm', 'Love Death and Cat', 'https://phimimg.com/upload/vod/20240411-1/1cfb833838fdc7241bffa8baba7b7558.jpg', 'https://phimimg.com/upload/vod/20240411-1/01a6b9b4ffee81bc54f56eab0eba7e61.jpg', '<p>Vũ cơ miêu yêu đã sống 90 năm, để giữ gìn thân xác mỹ nhân không thuộc về mình để níu giữ tình lang Cung Thiên Bảo, cô cố tình thu hút đạo sĩ bắt yêu Lục Chỉ, muốn hấp thụ tu vi phi thường của hắn; con mèo đen hai đuôi Tiểu Hắc đã cứu mạng Liễu Nguyên Trực, ân nhân cứu mạng trước kia , cũng là chồng của con gái xấu xí nhà Quốc cữu gia, từ đó họ sống cuộc sống ẩn cư an nhàn, nhưng không nghĩ đây sẽ là tình kiếp không tránh khỏi của nàng; tiểu miêu yêu sắp chín tuổi Mao Cầu, cần phải uống máu tinh khiết của một con chuột tinh để mọc ra cái đuôi đầu tiên, khi nàng gặp một con chuột tinh nhỏ, nàng lại trở thành bạn bè với đối phương một cách không ngờ; tình yêu giữa người và yêu quái chấn động vô cùng, dùng mắt mèo nhìn lòng người gian trá phức tạp, sự trưởng thành cuối cùng phải trả giá bằng đau khổ, ba thế hệ miêu yêu đi đến những kết cục khác nhau...</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sandrine Pinna","avatar":""},{"name":"Wang Ziyi","avatar":""},{"name":"Chen Yutong","avatar":""},{"name":"Lai Jing","avatar":""},{"name":"Lin Muran","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
