INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anthracit', 'Anthracit', 'Anthracite', 'https://phimimg.com/upload/vod/20240411-1/e7aa1051ef26c69d89f071a634677c57.jpg', 'https://phimimg.com/upload/vod/20240411-1/83119c592eb15b912ab35126d6dfd257.jpg', '<p>Một vụ án cũ được lật mở khi một phóng viên mất tích, khiến cô con gái là thám tử mạng của anh đến thị trấn miền núi nhỏ bị ám ảnh bởi một giáo phái, bí mật và cái chết.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Hatik","avatar":""},{"name":"Noémie Schmidt","avatar":""},{"name":"Camille Lou","avatar":""},{"name":"Nicolas Godart","avatar":""},{"name":"Raphaël Ferret","avatar":""},{"name":"Kad Merad","avatar":""},{"name":"Jean-Marc Barr","avatar":""},{"name":"Stefano Cassetti","avatar":""},{"name":"Vincent Rottiers","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
