INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('together-cu-an-ba-cua-manchester-city', 'Together: Cú ăn ba của Manchester City', 'Together: Treble Winners', 'https://phimimg.com/upload/vod/20240410-1/da77eadd2984808d02dec6eb89b38d59.jpg', 'https://phimimg.com/upload/vod/20240410-1/2cec15d09172bbb9ceedd09a1600b641.jpg', '<p>Loạt phim tài liệu này tái hiện mùa giải 2022 – 2023 phá kỷ lục của CLB Manchester City – mùa giải chứng kiến Đội Xanh giành được cú ăn ba chưa từng có.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Pep Guardiola","avatar":""},{"name":"Erling Haaland","avatar":""},{"name":"Jack Grealish","avatar":""},{"name":"Riyad Mahrez","avatar":""},{"name":"Kevin de Bruyne","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324242);
