INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-co-ay-cua-hom-nay', 'Các Cô Ấy Của Hôm Nay', 'Fry Me To The Moon', 'https://phimimg.com/upload/vod/20240405-1/4dd993f063e6d4759cc80ed36795d5ca.jpg', 'https://phimimg.com/upload/vod/20240405-1/d556f26f56d0e8f62556b597a93c6c91.jpg', '<p>Lộ Chân Chân, một người coi trọng sự nghiệp, đã dũng cảm từ bỏ mọi thứ để trở về Thành Đô vì tình yêu. Bạn thân của cô là Cố Mạn Đình, người đã kết hôn với thanh mai trúc mã từ sớm nhưng lại luôn muốn trốn tránh hôn nhân, đã mời Chân Chân vào làm ở Xuyên Bạch Lâu - nhà hàng lâu đời của gia đình. Quỹ đạo cuộc sống của cả hai bị phá vỡ bởi sự xuất hiện đột ngột của Lương Thanh Nhiên - một doanh nhân ẩm thực. Cuộc khủng hoảng bất ngờ ở Xuyên Bạch Lâu khiến ba người phụ nữ với ba tính cách khác biệt từ thù hóa thành bạn. Sau vô vàn thử thách về tình yêu, sự nghiệp và lý tưởng, họ sẽ đưa ra lựa chọn như thế nào ở chốn Thành Đô bình dị này?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
