INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-the-thao-dep', 'Môn Thể Thao Đẹp', 'The Beautiful Game', 'https://phimimg.com/upload/vod/20240404-1/897c3361fcfb6a2867c7731844be0751.jpg', 'https://phimimg.com/upload/vod/20240404-1/56fe56f1083a2a6bdb4bd3a31f7f501e.jpg', '<p>Khi một đội bóng đá Anh tới Rome để tham dự World Cup Vô Gia Cư, cầu thủ mới tài năng của họ phải buông bỏ quá khứ và học cách trở thành thành viên của đội.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Bill Nighy","avatar":""},{"name":"Micheal Ward","avatar":""},{"name":"Valeria Golino","avatar":""},{"name":"Susan Wokoma","avatar":""},{"name":"Tom Vaughan-Lawlor","avatar":""},{"name":"Callum Scott Howells","avatar":""},{"name":"Kit Young","avatar":""},{"name":"Sheyi Cole","avatar":""},{"name":"Robin Nazari","avatar":""},{"name":"Cristina Rodlo","avatar":""},{"name":"Sian Reese-Williams","avatar":""},{"name":"Aoi Okuyama","avatar":""},{"name":"Kazuhiro Muroyama","avatar":""},{"name":"Tadashi Watanabe","avatar":""},{"name":"Jessye Romeo","avatar":""},{"name":"Layo-Christina Akin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
