INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-sach-cua-clarence', 'Cuốn Sách của Clarence', 'The Book of Clarence', 'https://phimimg.com/upload/vod/20240402-1/f1915c2d57522dc3dc31d3d4e69675c8.jpg', 'https://phimimg.com/upload/vod/20240402-1/4769ba9b5b34e896cb35f5011ac1a68f.jpg', '<p>The Book of Clarence là một bộ phim hài kịch kinh thánh của Mỹ năm 2023 do Jeymes Samuel viết kịch bản và đạo diễn, Samuel, Jay-Z, James Lassiter và Tendo Nagenda sản xuất. Phim có sự tham gia của LaKeith Stanfield, Omar Sy, RJ Cyler, Anna Diop, David Oyelowo, Micheal Ward, Alfre Woodard, Teyana Taylor, Caleb McLaughlin, Eric Kofi-Abrefa, Marianne Jean-Baptiste, James McAvoy và Benedict Cumberbatch. Phim kể về một người đàn ông kém may mắn tên là Clarence sống ở Jerusalem năm 33 sau Công Nguyên, người đang tìm cách tận dụng sự trỗi dậy của Chúa Giêsu Kitô, bằng cách tự xưng là Đấng Mê-si mới được Chúa gửi đến, trong nỗ lực giải thoát bản thân khỏi nợ nần và bắt đầu cuộc sống vinh quang cho riêng mình.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"LaKeith Stanfield","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"RJ Cyler","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Teyana Taylor","avatar":""},{"name":"Caleb McLaughlin","avatar":""},{"name":"James McAvoy","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Anna Diop","avatar":""},{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Babs Olusanmokun","avatar":""},{"name":"Eric Kofi Abrefa","avatar":""},{"name":"Nicholas Pinnock","avatar":""},{"name":"Micheal Ward","avatar":""},{"name":"Chase W. Dillon","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
