INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-ke-rinh-mo-sat-nhan', 'Người yêu, kẻ rình mò, sát nhân', 'Lover, Stalker, Killer', 'https://phimimg.com/upload/vod/20240404-1/e3b76a09dddb90693336ba29edfb3fe5.jpg', 'https://phimimg.com/upload/vod/20240404-1/b8d8ca4a7620cd2ed887f6a7e1bbe6f0.jpg', '<p>Trong bộ phim tài liệu xoắn não này, người thợ máy nọ lần đầu tiên thử hẹn hò qua mạng và rồi gặp một người phụ nữ có nỗi ám ảnh tình ái đến mức chết người.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Dave Kroupa","avatar":""},{"name":"Ryan Avis","avatar":""},{"name":"Jessica Johnson","avatar":""},{"name":"Chris Maher","avatar":""},{"name":"Katie Otten","avatar":""},{"name":"Cari Farver","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324242);
