INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-yeu-ke-rinh-mo-sat-nhan', 'Người yêu, kẻ rình mò, sát nhân', 'Lover, Stalker, Killer', 'người yêu, kẻ rình mò, sát nhân lover, stalker, killer dave kroupa ryan avis jessica johnson chris maher katie otten cari farver ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-thay-dau', 'Quỷ Thay Đầu', 'Baghead', 'https://phimimg.com/upload/vod/20240410-1/1e20f90f89f28218cca270c610def72a.jpg', 'https://phimimg.com/upload/vod/20240410-1/542950c787683096dd3dc06a1b4d7221.jpg', '<p>Sau khi người cha qua đời, Iris thừa kế quán rượu cũ xuống cấp ở Berlin và khám phá một bí mật kinh hoàng về con quỷ 400 tuổi tên Baghead bị nhốt dưới tầng hầm. Baghead có khả năng triệu hồi người chết và Iris sử dụng sức mạnh của bà để kiếm tiền bằng cách cung cấp dịch vụ gọi hồn. Tuy nhiên, khi Iris và người bạn Katie lạm dụng sức mạnh này, họ nhận ra rằng sự tham lam có thể gây ra hậu quả khủng khiếp. Họ phải chiến đấu để giữ quyền kiểm soát Baghead và tìm ra cách tiêu diệt bà ta trước khi sự thảm họa lan rộng ra ngoài tầng hầm của quán rượu, đe dọa cả hai thế giới.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Đức', 1, '[{"name":"Freya Allan","avatar":""},{"name":"Jeremy Irvine","avatar":""},{"name":"Ruby Barker","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Anne Müller","avatar":""},{"name":"Svenja Jung","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Julika Jenkins","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Felix Römer","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324242);
