INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-mon-tham-uyen', 'Tinh Môn Thâm Uyên', 'Star Abyss', 'https://phimimg.com/upload/vod/20240329-1/7c9931e30186308dc171e41f843b6aa0.jpg', 'https://phimimg.com/upload/vod/20240329-1/27da9487393bd6a4f78e396da6036419.jpg', '<p>Trong tương lai, con người bắt đầu thực hiện hành trình du hành giữa các hành tinh thông qua cổng sao. Một con tàu vũ trụ bất ngờ bị mắc kẹt trong &quot;Hố Sao&quot; và chỉ có 4 trong số 15 hành khách có cơ hội sống sót thông qua việc vào các buồng ngủ đông. Mọi người lo lắng đang tập trung tại kho hàng, đối mặt với cơ hội sống quý báu, có người đã thả quái vật ngoài hành tinh bị giam giữ ra, cố gắng điều khiển quái vật để tàn sát người khác. Trong bóng tối sâu thẳm này, một trận chiến cho công lý đang bắt đầu.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Zhiting","avatar":""},{"name":"Andrew Lin","avatar":""},{"name":"Ming Zi-Yu","avatar":""},{"name":"Maiqian Guo","avatar":""},{"name":"Qi Xinyue","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324242);
