INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('knox-goes-away', 'Knox Goes Away', 'Knox Goes Away', 'https://phimimg.com/upload/vod/20240410-1/6b3d0588108d1801f62028e644a1bb73.jpg', 'https://phimimg.com/upload/vod/20240410-1/801188bb9ec7d9249765e09d5f81da40.jpg', '<p>Khi một kẻ giết người theo hợp đồng mắc chứng mất trí nhớ tiến triển nhanh chóng, anh ta có cơ hội chuộc lỗi bằng cách cứu sống đứa con trai trưởng thành bị ghẻ lạnh của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Keaton","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Suzy Nakamura","avatar":""},{"name":"Joanna Kulig","avatar":""},{"name":"Ray McKinnon","avatar":""},{"name":"John Hoogenakker","avatar":""},{"name":"Lela Loren","avatar":""},{"name":"Morgan Bastin","avatar":""},{"name":"Dennis Dugan","avatar":""},{"name":"Jay Paulson","avatar":""},{"name":"Sasha Neboga","avatar":""},{"name":"Marisa Echeverria","avatar":""},{"name":"Chad Donella","avatar":""},{"name":"Skip Howland","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324242);
