INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nu-chinh-tri-gia-tre-tuoi', 'Những Nữ Chính Trị Gia Trẻ Tuổi', 'Girls State', 'https://phimimg.com/upload/vod/20240410-1/f189cc0485b535fddb37365598a05ead.jpg', 'https://phimimg.com/upload/vod/20240410-1/d7c223a6ed37b255197573103dcf9d76.jpg', '<p>Nền dân chủ Mỹ sẽ như thế nào dưới bàn tay của các cô gái tuổi teen? Trong bộ phim tài liệu này, các nữ lãnh đạo trẻ với xuất thân rất khác nhau ở Missouri bước vào một thử nghiệm chân thực để xây dựng một chính quyền từ gốc.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Faith Glasgow","avatar":""},{"name":"Cecilia Bartin","avatar":""},{"name":"Nisha Murali","avatar":""},{"name":"Brooke Taylor","avatar":""},{"name":"Emily Worthmore","avatar":""},{"name":"Maddie Rowan","avatar":""},{"name":"Tochi Ihekona","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324242);
