INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-gieo-nuoc-mat', 'Người Gieo Nước Mắt', 'The Tearsmith', 'https://phimimg.com/upload/vod/20240410-1/67b7c679b60d4e62109243b3cafe777a.jpg', 'https://phimimg.com/upload/vod/20240410-1/9dc9f49181e3af7600b1fac6c034369a.jpg', '<p>Được nhận nuôi cùng nhau sau tuổi thơ khó khăn ở trại trẻ mồ côi, Nica và Rigel nhận ra rằng những cảm xúc bất ngờ nhưng không thể cưỡng lại đã giúp cả hai thân thiết hơn.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Caterina Ferioli","avatar":""},{"name":"Simone Baldasseroni","avatar":""},{"name":"Sabrina Paravicini","avatar":""},{"name":"Alessandro Bedetti","avatar":""},{"name":"Roberta Rovelli","avatar":""},{"name":"Orlando Cinque","avatar":""},{"name":"Eco Andriolo Ranzi","avatar":""},{"name":"Nicky Passarella","avatar":""},{"name":"Sveva Romano Candelletta","avatar":""},{"name":"Laura Baldi","avatar":""},{"name":"Matteo Capraro","avatar":""},{"name":"Anna Cianca","avatar":""},{"name":"Juju Di Domenico","avatar":""},{"name":"Filippo Giacomelli","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
