INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-gieo-nuoc-mat', 'Người Gieo Nước Mắt', 'The Tearsmith', 'người gieo nước mắt the tearsmith caterina ferioli simone baldasseroni sabrina paravicini alessandro bedetti roberta rovelli orlando cinque eco andriolo ranzi nicky passarella sveva romano candelletta laura baldi matteo capraro anna cianca juju di domenico filippo giacomelli ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tinh-nghi-thu-3', 'Kẻ Tình Nghi Thứ 3', 'The Third Suspect', 'https://phimimg.com/upload/vod/20240410-1/36ab55fd308cab138e7eec9fb2981767.jpg', 'https://phimimg.com/upload/vod/20240410-1/981c2e164298c1dd11d6a0d4c4c9b613.jpg', '<p>Khu vực Long Sơn liên tiếp xảy ra hai vụ án mạng, gây phản ứng cực lớn trong xã hội, người dân hoang mang lo sợ, áp lực của cảnh sát tăng cao, ngay lập tức thành lập nhóm chuyên án &quot;118&quot; với trưởng và phó nhóm lần lượt là Phó đồn trưởng, trưởng phòng Hình sự Lý Huy và đội trưởng đội Cảnh sát Hình sự Quách Minh. Lý Huy, người chỉ còn hơn mười ngày nữa là về hưu, quyết tâm giải quyết vụ án này trước khi nghỉ hưu, vẽ dấu chấm hết hoàn hảo cho sự nghiệp cảnh sát Hình sự mà mình đã theo đuổi cả đời. Nhưng đằng sau hai vụ án mạng có vẻ như không liên quan này ẩn chứa một âm mưu được thiết kế tỉ mỉ, tình tiết vụ án đầy ẩn số như sương mù trùng trùng bao phủ. Chị gái Lưu Hân Hân do ghen ghét mà sinh hận , để giành được tài sản kếch xù và hãm hại em gái cùng cha khác mẹ Lưu Úc mà thường xuyên tự do thay đổi thân phận giữa Lưu Úy và Lưu Hân Hân. Cảnh sát Hình sự mới và cũ liên thủ giải quyết mâu thuẫn trước kia, cuối cùng giải mã được ẩn số.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Chengfeng","avatar":""},{"name":"Song Ning","avatar":""},{"name":"Shi Zhaoqi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
