INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-xem-toi-la-ai', 'Đoán Xem Tôi Là Ai', 'Guess Who I Am', 'https://phimimg.com/upload/vod/20240402-1/bafa9c17800eed5911887edf3d7a918b.jpg', 'https://phimimg.com/upload/vod/20240402-1/c3d36dcb8d6f71376daa0e93c5d52169.jpg', '<p>Nghe đồn trong giới nhà giàu có một tổ chức bí ẩn, chuyên trừng trị những tên cặn bã có tiền mà không có đức, chỉ cần trả thù lao hợp lý thì dù đối tượng có khó đối phó đến mấy cũng đều bị tổ chức này giải quyết. Trên thực tế, tổ chức bí ẩn này chẳng qua là một nhóm nhỏ tự phát, sở dĩ họ chưa từng thất bại là nhờ có thể chất kỳ lạ thu hút người giàu của thành viên chủ chốt trong tổ chức - Tống Dao. Chỉ cần là kẻ lắm tiền thường xuyên nói dối, khi nhìn vào mắt Tống Dao ba giây sẽ say mê cô ấy không dứt ra nổi, để mặc cho cô ấy thao túng. Nhưng thể chất này có ghê gớm đến mấy cũng có ngày thất bại: không ngờ cặp mắt phóng điện thần kỳ của Tống Dao lại mất tác dụng khi đối diện với cậu cả Quý Thừa Xuyên của tập đoàn Thừa Thiên! Sau vài lần đọ sức thất bại, Tống Dao mới hiểu rõ nguyên do, cậu cả gì chứ, rõ ràng là hàng giả! Tần Hạo giả danh Quý Thừa Xuyên là vì muốn vào được nội bộ Thừa Thiên, điều tra sự thật về vụ hỏa hoạn xảy ra 15 năm trước. Để tránh gây thêm nhiều phiền toái, Tần Hạo vốn không muốn dính dáng tới cô nàng đào mỏ Tống Dao, nhưng trùng hợp thế nào lại không thể không giả làm vợ chồng với cô ấy. Sau khi Tần Hạo nhậm chức tổng giám đốc, trở thành đại gia đích thực, thì ngay khoảnh khắc nhìn vào mắt Tống Dao, anh như bị ma xui quỷ khiến phải lòng cô ấy! Cô gái trừng trị kẻ xấu gặp phải một tên lừa đảo, hai thánh diễn với mục đích khác nhau ắt sẽ mở ra một cuộc chiến không khói lửa. Cuối cùng ai sẽ là người chiến thắng đây? Hãy cùng đón xem nhé.&nbsp;</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Yuxi","avatar":""},{"name":"Wang Ziqi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324242);
