INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-chung-song-ngu-quy-su', 'Bao Chửng: Song Ngư Quỷ Sự', 'The Mystery of Jade', 'https://phimimg.com/upload/vod/20240410-1/fba750492a9e626e59d7cfaa2299b6bf.jpg', 'https://phimimg.com/upload/vod/20240410-1/a99e53a4faa3465a3b5d6bc4a21eb426.jpg', '<p>Đột nhiên, Tư thiên giám tự sát chết ở phố xá sầm uất, trước khi tự sát luôn miệng lẩm bẩm: &quot;Song Ngư hiện thế, triều dã loạn, ảnh phản chiếu ở khắp nơi khiến vận mệnh đứt đoạn!&quot; Tống Nhân Tông cho Bao Chửng ba ngày để phá án, Bao Chửng với Triển Châu đến Đại Lý Tự để điều tra vụ án, nhưng lại bị Đại Lý Tự cố ý gây khó dễ. Dù vậy, Bao Chửng vẫn tra ra được manh mối quan trọng. Một miếng ngọc bội Song Ngư vốn dĩ phải ở trên người Ti thiên giám đã biến mất, cùng lúc đó, Đại Lý Tự Khanh cũng bắt đầu có những hành vi kỳ quái giống như trước khi Tư thiên giám tự sát. Ngọc bội Song Ngư trong truyền thuyết nổi lên mặt nước, nhưng vụ án vẫn chưa có chút manh mối nào. Lúc này, hạn cuối để phá án chỉ còn mỗi một ngày......</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Joe Xu","avatar":""},{"name":"Li Mingxuan","avatar":""},{"name":"Cao Xiyue","avatar":""},{"name":"Tang Xin","avatar":""},{"name":"Wen Haibo","avatar":""},{"name":"Shen Baoping","avatar":""},{"name":"Linjing Jiang","avatar":""},{"name":"Jiusheng Wang","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
