INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-da-giet-co-ay', 'Ai Đã Giết Cô Ấy?', 'Kill Sera Sera?', 'https://phimimg.com/upload/vod/20240410-1/2fd9ed69ce7658b843ce9c35321e76d1.jpg', 'https://phimimg.com/upload/vod/20240410-1/cedbe98bee7ec599e0e886094eff8c46.jpg', '<p>Trong một gia đình chất chứa những bí mật, người nghệ sĩ nọ tạo ra màn kịch động trời trong nỗ lực truy tìm hung thủ sát hại cô con gái yêu quý của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Jessica Hester Hsuan","avatar":""},{"name":"James Wen","avatar":""},{"name":"Christopher Lee Ming-Shun","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
