INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-sinh-thu-vung-xam', 'Ký Sinh Thú: Vùng Xám', 'Parasyte: The Grey', 'https://phimimg.com/upload/vod/20240409-1/9cc94d60380213261a7759d04a06e547.jpg', 'https://phimimg.com/upload/vod/20240409-1/e87dfb05c29c16df1bade6e34634716e.jpg', '<p>Khi những ký sinh thú vô danh tàn bạo chiếm con người làm vật chủ và giành được quyền chi phối, nhân loại phải vùng lên chiến đấu với mối đe dọa leo thang này.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2024, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
