INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-song-nhung-ke-con-lai', 'Xác Sống: Những Kẻ Còn Lại', 'The Walking Dead: The Ones Who Live', 'https://phimimg.com/upload/vod/20240305-1/87da1cb4bcf3fcadad33af44ce5c41dd.jpg', 'https://phimimg.com/upload/vod/20240305-1/cd60fe433aaa45ab74c0e5e246858462.jpg', '<p>Chuyện tình giữa Rick và Michonne. Bị thay đổi bởi một thế giới không ngừng thay đổi, liệu họ sẽ thấy mình đang trong một cuộc chiến chống lại người sống hay họ sẽ phát hiện ra rằng họ cũng là The Walking Dead?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Andrew Lincoln","avatar":""},{"name":"Danai Gurira","avatar":""},{"name":"Pollyanna McIntosh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
