INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-khong-gia-tao', 'Trái Tim Không Giả Tạo', 'Beauty Newbie', 'https://phimimg.com/upload/vod/20240313-1/b4a5b8aa3cbb104fd8c1ac362c097d55.jpg', 'https://phimimg.com/upload/vod/20240313-1/a80de671dacb802a764629c534c95c7d.jpg', '<p>Trái Tim Không Giả Tạo - Beauty Newbie kể về cô gái tên Liu có ngoại hình xấu xí. Cô đã đi chỉnh sửa khuôn mặt với hy vọng có thể tìm được tình yêu. Thế nhưng, dù dung nhan đã thay đổi nhưng Liu vẫn không dám đến với anh chàng điển trai tên Guy vì cô tin rằng Faye với vẻ ngoài xinh đẹp tự nhiên vẫn phù hợp với Guy hơn cô ấy. Mọi chuyện càng thêm rắc rối khi quá khứ của Liu bị lộ...</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pimchanok Luevisadpaibul","avatar":""},{"name":"Metawin Opas-iamkajorn","avatar":""},{"name":"Sapol Assawamunkong","avatar":""},{"name":"Ramida Jiranorraphat","avatar":""},{"name":"Rutricha Phapakithi","avatar":""},{"name":"Thasorn Klinnium","avatar":""},{"name":"Thanaboon Kiatniran","avatar":""},{"name":"Thanawin Teeraphosukarn","avatar":""},{"name":"Phatchatorn Thanawat","avatar":""},{"name":"Sattabut Laedeke","avatar":""},{"name":"Chinnarat Siriphongchawalit","avatar":""},{"name":"Suphakor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
