INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-le-bat-kha-thi', 'Hôn Lễ Bất Khả Thi', 'Wedding Impossible', 'https://phimimg.com/upload/vod/20240303-1/a8b12eedaa7196352ced4be70d4d3255.jpg', 'https://phimimg.com/upload/vod/20240303-1/310a16ba2f47581eb92455db0479c0ef.jpg', '<p>Nhiệm vụ lãng mạn giữa một nữ diễn viên kém cỏi lên kế hoạch cho một cuộc hôn nhân giả VS anh rể tương lai đầy tham vọng phản đối</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jun Jong-seo","avatar":""},{"name":"Moon Sang-min","avatar":""},{"name":"Kim Do-wan","avatar":""},{"name":"Bae Yoon-kyung","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Park Jae-wan","avatar":""},{"name":"Kim Ye-won","avatar":""},{"name":"Kang Na-eon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
