INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cong-phuc-yeu', 'Chu Công Phục Yêu', 'Zhou Gong Subdues Demons', 'https://phimimg.com/upload/vod/20240404-1/36c06c18e7954d58e739fe42df4930c5.jpg', 'https://phimimg.com/upload/vod/20240404-1/1eeded6bc655e96339e50ff6307eae91.jpg', '<p>Theo truyền thuyết, sau khi Bàn Cổ khai thiên, để ổn định không gian, tổ Hồng Quân đã lấy âm dương của trời đất và luyện chế thành Huyền Thiên Thần Kiếm với sức mạnh của vũ trụ. Đứng trên đỉnh Cửu Thiên, bảo vệ tất cả mọi người trên thế giới. Một ngày nọ, Đông Hoàng Thái Nhất và Yêu Hoàng Đế Tuấn đang giao chiến ác liệt ở thiên giới, vô tình làm phiền Huyền Thiên Thần Kiếm đang luyện tập, thân kiếm và bao kiếm đã bị rơi xuống trần gian do linh lực của Thái Nhất và Đế Tuấn. Thân kiếm đầu thai sinh ra tại Châu phủ và trở thành công tử Châu phủ Châu Can, cậu ấy không còn kí ức và linh lực. Bao kiếm mang theo kí ức và chút linh lực không hoàn thiện rơi vào rừng hoa đào. Nàng được mệnh danh là tiên nữ Hoa Đào vì đã cứu giúp rất nhiều người. Đông Hoàng Thái Nhất đánh trọng thương Yêu Hoàng Đế Tuấn. Khi Yêu Hoàng Đế Tuấn chạy trốn ở nhân gian, vô tình phát hiện thân kiếm đã chuyển thế phàm trần, hắn muốn khống chế Huyền Thiên Thần Kiếm, nên tiêu diệt toàn bộ nhà họ Châu. Châu Can không ngừng luyện tập, dấn thân vào con đường báo thù, trong quá trình thu phục yêu ma và diệt yêu, anh đã gặp thầy diệt yêu Linh Nhi. Sau đó, cuối cùng cũng gặp được định mệnh của mình là Hoa Đào. Cuối cùng với sự nỗ lực của ba người, họ đã đánh bại được Yêu Hoàng Đế Tuấn bảo vệ nhân gian.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jason Sze","avatar":""},{"name":"Di Zheng","avatar":""},{"name":"Ju Keer","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Yu Jiachuan","avatar":""},{"name":"Fang Qingping","avatar":""},{"name":"Tian Jingquan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324242);
