INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-gian-lenh', 'Hoa Gian Lệnh', 'In Blossom', 'https://phimimg.com/upload/vod/20240323-1/c52079a69a48e34a498acab8a27bdc49.jpg', 'https://phimimg.com/upload/vod/20240323-1/76623831699fbd3f14dff3e10ba9d51b.jpg', '<p>Tại thành Hoà Dương nhuốm đầy tội ác, Phan Việt - mỹ nam được vô số thiếu nữ yêu mến, kết hôn cùng người mà ai nấy đều ghét bỏ, Dương Thái Vi. Vào ngày đại hôn, Dương Thái Vi bị giết hại, nghi phạm lại chính là Phan Việt. Sau khi &quot;từ cõi chết trở về&quot;, Dương Thái Vi trở lại đầy mạnh mẽ dưới vỏ bọc &quot;ác nữ&quot; Thượng Quan Chỉ, quyết tâm vạch trần bộ mặt thật của Phan Việt. Trong quá trình chiến đấu chống lại thế lực tà ác &quot;tứ đại gia tộc&quot; và điều tra các vụ án cũ, hai trái tim sát lại gần nhau. Dương Thái Vi phát hiện thủ phạm thực sự giết hại mình là một người khác, còn Phan Việt từ đầu đến cuối vẫn luôn yêu cô sâu đậm. Khi mọi chuyện sắp viên mãn, kẻ đứng sau một lần nữa lại giăng bẫy, đẩy hai người vào tình cảnh vạn kiếp bất phục.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ju Jingyi","avatar":""},{"name":"Liu Xueyi","avatar":""},{"name":"Wu Jiayi","avatar":""},{"name":"Li Geyang","avatar":""},{"name":"Zheng Hehuizi","avatar":""},{"name":"Ray Zhang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
