INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yen-nghi', 'Yên Nghỉ', 'Rest In Peace', 'https://phimimg.com/upload/vod/20240402-1/a56b6260fdc35a310bb674b85e2963ee.jpg', 'https://phimimg.com/upload/vod/20240402-1/5d04ab0558f006ca3da7bde1a705b6b5.jpg', '<p>Sergio đối mặt với áp lực tài chính leo thang và sức khỏe giảm sút. Và rồi số phận cho anh cơ hội bảo vệ gia đình mình, nhưng cái giá phải trả là mạng sống của anh.&nbsp;</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Argentina', 0, '[{"name":"Joaquín Furriel","avatar":""},{"name":"Griselda Siciliani","avatar":""},{"name":"Gabriel Goity","avatar":""},{"name":"Lali González","avatar":""},{"name":"Luciano Borges","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
