INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-tru-xa-la', 'Vũ Trụ Xa Lạ', 'Constellation', 'https://phimimg.com/upload/vod/20240228-1/0b4e7f8cf3b7c7b0d7f05ef762405d51.jpg', 'https://phimimg.com/upload/vod/20240228-1/e63fe1cc34076b530f077c0b4075c83b.jpg', '<p>Khi một tai nạn chết người xảy ra trên Trạm Vũ trụ Quốc tế, một phi hành gia đơn độc thực hiện hành trình dũng cảm trở về Trái đất để rồi phát hiện ra những phần quan trọng trong cuộc đời cô - bao gồm cả cô con gái nhỏ - đã thay đổi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Noomi Rapace","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"James D''Arcy","avatar":""},{"name":"Rosie Coleman","avatar":""},{"name":"Davina Coleman","avatar":""},{"name":"William Catlett","avatar":""},{"name":"Barbara Sukowa","avatar":""},{"name":"Julian Looman","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
