INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-bao-an-luong', 'Trừ Bạo An Lương', 'Punish Evil', 'https://phimimg.com/upload/vod/20240402-1/a3be738f20b06c0aaf6b2c6c3d4e002a.jpg', 'https://phimimg.com/upload/vod/20240402-1/d885adff07a7e82bf2cc5b3a1a1041b1.jpg', '<p>Trong quá trình đảm bảo an ninh xã hội, đội trưởng cảnh sát hình sự Thường Dũng phát hiện một nhóm côn đồ cướp một lượng lớn tiền mặt rồi giấu trong thành phố. Với việc điều tra chuyên sâu vụ cướp, nhiều manh mối mới dần lộ diện. Cuối cùng, với sự nỗ lực của toàn đội cảnh sát hình sự do Trường Dũng dẫn dắt, những con người không ngại gian khổ và nguy hiểm. Cuối cùng họ đã đập tan âm mưu phạm tội của bọn tội phạm và đưa bọn tội phạm ra trước công lý.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tan Kai","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Cao Minghua","avatar":""},{"name":"Li Sibo","avatar":""},{"name":"Liu Ruiqiao","avatar":""},{"name":"Han Xiao","avatar":""},{"name":"Liu Dengyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324242);
