INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-muoi-phut', 'Sáu Mươi Phút', '60 Minuten (Sixty Minutes)', 'https://phimimg.com/upload/vod/20240402-1/21315b6e3da24ef99eb6fb59ac17f78f.jpg', 'https://phimimg.com/upload/vod/20240402-1/e17e00e25cda5a2341e4c1788344f590.jpg', '<p>Không muốn mất quyền nuôi con gái, một võ sĩ võ thuật tổng hợp bỏ trận đấu lớn, gấp rút đến đầu bên kia của Berlin để dự tiệc sinh nhật của con gái mình.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Emilio Sakraya","avatar":""},{"name":"Dennis Mojen","avatar":""},{"name":"Marie Mouroum","avatar":""},{"name":"Paul Wollin","avatar":""},{"name":"Florian Schmidtke","avatar":""},{"name":"Aristo Luis","avatar":""},{"name":"José Barros","avatar":""},{"name":"Vassilis Koukalani","avatar":""},{"name":"Janna Striebeck","avatar":""},{"name":"Morik Heydo","avatar":""},{"name":"Livia Matthes","avatar":""},{"name":"Mehmet Ateşçi","avatar":""},{"name":"Eniko Fulop","avatar":""},{"name":"Bruno Salgueiro","avatar":""},{"name":"Tatjana Šojić","avatar":""},{"name":"Alain Blazevic","avatar":""},{"name":"Szabolcs Ke","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324242);
