INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('players', 'Players', 'Players', 'https://phimimg.com/upload/vod/20240402-1/a62fba1330b16c0a0e71f59d8cbf91b2.jpg', 'https://phimimg.com/upload/vod/20240402-1/3b74a4dd317fcd183f9ea88bf9e93990.jpg', '<p>Sáng tác cuốn sách về kế hoạch cặp kè thông minh, nhà văn thể thao nọ ở New York bất ngờ rơi vào lưới tình. Liệu cô có thể chuyển từ vui chơi qua đường sang yêu đương nghiêm túc?</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gina Rodriguez","avatar":""},{"name":"Damon Wayans Jr.","avatar":""},{"name":"Tom Ellis","avatar":""},{"name":"Augustus Prew","avatar":""},{"name":"Joel Courtney","avatar":""},{"name":"Liza Koshy","avatar":""},{"name":"Jerry Kernion","avatar":""},{"name":"Ego Nwodim","avatar":""},{"name":"Marin Hinkle","avatar":""},{"name":"Brock O''Hurn","avatar":""},{"name":"Gina Jun","avatar":""},{"name":"Kais Boukthir","avatar":""},{"name":"Sterling Jonatán Williams","avatar":""},{"name":"Darron Jay Morgan","avatar":""},{"name":"Dan Cordle","avatar":""},{"name":"Claudia Maree Mailer","avatar":""},{"name":"Geo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
