INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-vo-cung-hoang-duong-cua-dick-turpin', 'Những Cuộc Phiêu Lưu Vô Cùng Hoang Đường Của Dick Turpin', 'The Completely Made-Up Adventures Of Dick Turpin', 'https://phimimg.com/upload/vod/20240310-1/92d07dfc365da0a5f7b542a9c67b9ee5.jpg', 'https://phimimg.com/upload/vod/20240310-1/54ba0039692b13292120265ce201f33c.jpg', '<p>Kẻ cướp đường huyền thoại Dick Turpin thực hiện một loạt những vụ trốn thoát hết sức ngớ ngẩn khi anh trở thành thủ lĩnh bất đắc dĩ của một nhóm tội phạm ngoài vòng pháp luật — và được giao nhiệm vụ qua mặt viên tướng bắt cướp cực kỳ thối nát Jonathan Wilde.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324242);
