INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mashle-ma-thuat-va-co-bap-phan-2', 'Mashle: Ma Thuật Và Cơ Bắp (Phần 2)', 'MASHLE: MAGIC AND MUSCLES (Season 2)', 'https://phimimg.com/upload/vod/20240304-1/3140f78ae9ea4ffed3ecdfd1e031f20e.jpg', 'https://phimimg.com/upload/vod/20240304-1/45212abfec600d71c79d1f466f582a8f.jpg', '<p>Đây là một thế giới của phép thuật, nơi phép thuật được sử dụng cho mọi thứ. Nhưng sâu trong khu rừng tồn tại một chàng trai dành thời gian của mình để tập luyện. Anh chàng không thể sử dụng phép thuật, nhưng anh ấy tận hưởng một cuộc sống yên bình với cha mình. Nhưng một ngày nọ, cuộc sống của anh ấy bị đe dọa! Liệu cơ thể vạm vỡ của anh ấy có bảo vệ anh ấy khỏi những kẻ sử dụng ma thuật? Cơ bắp được rèn luyện mạnh mẽ sẽ nghiền nát ma thuật khi ảo tưởng ma thuật bất thường này bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
