INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thuan-hoa-yeu-nhat-bat-dau-hanh-trinh-nhat-rac', 'Kẻ Thuần Hóa Yếu Nhất Bắt Đầu Hành Trình Nhặt Rác', 'The Weakest Tamer Began a Journey to Pick Up Trash', 'https://phimimg.com/upload/vod/20240305-1/3901c48f01cce79ffb68ec0e0a7ae1d4.jpg', 'https://phimimg.com/upload/vod/20240305-1/0668767c47794c50f6a6924e7c26935e.jpg', '<p>Trong thế giới của Ivy, những vì sao là tất cả mọi thứ. Cô ấy là một Người Huấn Luyện, sinh ra để khuất phục quái vật và động vật, nhưng cô ấy cũng sinh ra không có vì sao nào! Với cuộc sống của mình đang gặp nguy hiểm, Ivy bỏ chạy vào khu rừng nơi cô kết bạn với một viên nhầy yếu đuối tên là Sora - loài sinh vật duy nhất cô có thể huấn luyện. Cùng nhau, cặp đôi không tưởng này bắt đầu hành trình, giữ lại rác rưởi để tồn tại. Trên đường đi, họ sẽ chinh phục trái tim, tránh né nguy hiểm và khám phá ra rằng có nhiều điều hơn trong Ivy không có vì sao mà mắt thường thấy!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Aina Suzuki","avatar":""},{"name":"Mutsumi Tamura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
