INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-lai-nguoi-ben-goi', 'Gặp Lại Người Bên Gối', 'In Bed With A Stranger', 'https://phimimg.com/upload/vod/20240309-1/d7462e1612ecf58b5cdbeb0198446b50.jpg', 'https://phimimg.com/upload/vod/20240309-1/24548eac96e611fc92e0dcc11ac417db.jpg', '<p>Người đàn ông tuổi trung niên thành đạt về sự nghiệp nhưng phiền não trong tình cảm. Tình nghĩa khó vẹn toàn, một người là vợ cũ mất tích nhiều năm, một người là hồng nhan tri kỷ. Năm 2012, nữ phóng viên Cố Tình Thiên (do Huỳnh Trí Văn đóng) yêu “sư phụ” Dương Vạn Sâm (do Mã Đức Chung đóng). Sau đó, họ kết hôn và sinh con trai Dương Chí Khiên. Năm 2016, Thiên gặp tai nạn, rơi xuống biển mất tích. Dương Vạn Sâm “gà trống nuôi con”, anh mất hết hy vọng khi tìm kiếm vợ. Sau 7 năm, Sâm trở thành tổng giám đốc sáng tạo của công ty sản xuất, anh tổ chức hôn lễ với Chu Thiện Mỹ (do Trương Hy Văn đóng) - hồng nhan tri kỷ giúp anh thoát khỏi vực sâu cuộc đời. Đột nhiên, Tình Thiên trở về. Thiên bị hôn mê nhiều năm, cô mất trí nhớ và lưu lạc đến Indonesia. Được sự giúp đỡ của luật sư Kim Trường Thắng (do La Thiên Vũ đóng), Thiên trở về tìm lại ký ức năm xưa. Đám cưới của Sâm và Mỹ tạm hoãn, Sâm tìm cách giúp Thiên hồi phục trí nhớ. Tình Thiên quay lại nghề phóng viên. Thiên điều tra được sự cố té núi năm xưa không phải tai nạn, mà có người hãm hại. Mặt khác, Vạn Sâm đối mặt với người tình mới và vợ cũ nên cảm thấy khó xử. Lúc này, anh lại lo sợ Tình Thiên hồi phục trí nhớ nên luôn theo dõi cô. Mỹ cảm thấy ghen tị với Thiên nên bày nhiều mưu kế lấy lòng Sâm và Chí Khiên...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 15, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Joe Ma","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Kelly Cheung","avatar":""},{"name":"Joey Law","avatar":""},{"name":"Tsui Wing","avatar":""},{"name":"Fred Cheng","avatar":""},{"name":"Nicole Wan See Pui","avatar":""},{"name":"To Yin-Gor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
