INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thu', 'Đại Thú', 'Sianviathan', 'https://phimimg.com/upload/vod/20240402-1/a898583d7fcb958c9d82ddba1c6aabb6.jpg', 'https://phimimg.com/upload/vod/20240402-1/a4f591c5f24ecc44e3107271942929cb.jpg', '<p>Những năm cuối của triều đại nhà Tùy, một buổi tối nọ một thư sinh tên là Vương Phục Sinh lánh nạn ở quán trọ đã có một cuộc kỳ ngộ ở bến đò bên sông. Chàng vô tình lạc vào cuộc đấu giành &quot;Thần kiếm &quot; giữa quần hùng, trải qua những thử thách khó khăn từ cướp bóc, phản quân, quái thú, đến quan lại lưu vong, cuối cùng trở nên chín chắn, trở thành một vị quan danh tiếng một thời.</p>', 'Full', 1, 'single', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Jianyu","avatar":""},{"name":"Qian Dongni","avatar":""},{"name":"Zou Mingyang","avatar":""},{"name":"Wang Zun","avatar":""},{"name":"Ma Lun","avatar":""},{"name":"Zhang Hongfa","avatar":""},{"name":"Deng Qimeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324242);
