INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-va-meo', 'Chó và Mèo', 'Cat and Dog', 'https://phimimg.com/upload/vod/20240402-1/c0407b1c0fd3235463c942d143e4c620.jpg', 'https://phimimg.com/upload/vod/20240402-1/b0334840abbe55c74db740d26c07439c.jpg', '<p>Một con mèo và một con chó thoát khỏi chuồng ở sân bay, chủ nhân của chúng phải hợp tác để tìm lại thú cưng quý giá của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Franck Dubosc","avatar":""},{"name":"Reem Kherici","avatar":""},{"name":"Philippe Lacheau","avatar":""},{"name":"Inès Reg","avatar":""},{"name":"Artus","avatar":""},{"name":"Raphaëlle Fugère-Larocque","avatar":""},{"name":"Oscar Desgagnés","avatar":""},{"name":"Lenie Scoffié","avatar":""},{"name":"Martin Dansky","avatar":""},{"name":"Élisabeth Locas","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
