INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cho-va-meo', 'Chó và Mèo', 'Cat and Dog', 'chó và mèo cat and dog franck dubosc reem kherici philippe lacheau inès reg artus raphaëlle fugère-larocque oscar desgagnés lenie scoffié martin dansky élisabeth locas ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-gia-dinh-nho', 'Cuộc Sống Gia Đình Nhỏ', 'Simple Days', 'https://phimimg.com/upload/vod/20240315-1/b69093be088a661d74fad3a0281dd7b3.jpg', 'https://phimimg.com/upload/vod/20240315-1/0ff1b03ddbad3047d97f189c176fd694.jpg', '<p>Cố Mạt Lị và Chu Kình Thảo vật lộn phấn đấu từ quê hương lên Thượng Hải để cắm rễ và lập gia đình. Tuy nhiên, hôn nhân lại mang đến cho họ một vấn đề vốn không đáng có, đó là làm sao để chung sống hòa hợp với cha mẹ. Từ việc mất không gian riêng tư cho đến mua nhà, từ bố mẹ đôi bên cho đến hai vợ chồng cũng bất đồng quan điểm. Cuộc sống của gia đình nhỏ bắt đầu đầy rẫy nguy cơ, đến khi vượt ngoài tầm kiểm soát, cặp đôi mới nhận ra nguyên nhân đến từ chính họ. Sau khi trải qua giai đoạn nguội lạnh, cả hai quyết định ly hôn, xử lý lại vướng mắc trong gia đình. Với sự xuất hiện của giấy ly hôn, những thử thách cho đôi vợ chồng trẻ và gia đình họ mới bắt đầu. Trưởng thành luôn đi kèm với vô vàn va vấp. Sau khi ly hôn, cả hai gặp phải khủng hoảng lòng tin, khủng hoảng tài chính và khủng hoảng nơi đất khách, điều này cũng khiến họ hiểu rõ hơn về trách nhiệm gia đình.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324242);
