INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-gia-cua-su-so-hai', 'Cái Giá Của Sự Sợ Hãi', 'The Wages of Fear', 'https://phimimg.com/upload/vod/20240402-1/8880d44630964588646badb97698b2ab.jpg', 'https://phimimg.com/upload/vod/20240402-1/652a6ea939df5814bd72b952dd191bb7.jpg', '<p>Khi vụ nổ ở giếng dầu đe dọa mạng sống của hàng trăm người, một đội chuyên biệt được triệu tập để thực hiện nhiệm vụ vượt qua sa mạc chết chóc cùng nitroglycerine.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Franck Gastambide","avatar":""},{"name":"Alban Lenoir","avatar":""},{"name":"Ana Girardot","avatar":""},{"name":"Sofiane Zermani","avatar":""},{"name":"Astrid Whettnall","avatar":""},{"name":"Bakary Diombera","avatar":""},{"name":"Alka Matewa","avatar":""},{"name":"Sarah Afchain","avatar":""},{"name":"Joseph Beddelem","avatar":""},{"name":"Birol Tarkan Yıldız","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324242);
