INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cai-gia-cua-su-so-hai', 'Cái Giá Của Sự Sợ Hãi', 'The Wages of Fear', 'cái giá của sự sợ hãi the wages of fear franck gastambide alban lenoir ana girardot sofiane zermani astrid whettnall bakary diombera alka matewa sarah afchain joseph beddelem birol tarkan yıldız ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-dung-sai-cua-ma-thuat-chua-tri', 'Cách Dùng Sai Của Ma Thuật Chữa Trị', 'The Wrong Way to Use Healing Magic', 'https://phimimg.com/upload/vod/20240127-1/f29e10f7d083452c5cb3c60929e28005.jpg', 'https://phimimg.com/upload/vod/20240127-1/94f3c8d98e7a94172dd0d05596a131cb.jpg', '<p>Một chuyến đi bộ bình thường từ trường về nhà trở thành một hành trình hoành tráng đối với Usato. Sau khi bất ngờ bị rơi vào một thế giới khác cùng với hai bạn học, Usato biết rằng mình vô tình được triệu hồi đến đó. Nhưng mọi thứ xoay chuyển khi anh phát hiện ra năng khiếu độc đáo về phép thuật chữa bệnh! Giờ đây, anh ta rèn luyện vượt qua giới hạn của con người, sử dụng khả năng tự phục hồi của mình để có được sức mạnh phi thường và sức chịu đựng vô song.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 10, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shogo Sakata","avatar":""},{"name":"Ayaka Nanase","avatar":""},{"name":"Kengo Takanashi","avatar":""},{"name":"Saya Aizawa","avatar":""},{"name":"Atsuko Tanaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
