INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ven-duong', 'Nhà Ven Đường', 'Road House', 'https://phimimg.com/upload/vod/20240330-1/aae34823cfbbfe1dd5dee759470e4836.jpg', 'https://phimimg.com/upload/vod/20240330-1/364602f22d0c5f60242c17fb26f4a8f6.jpg', '<p>Road House là một bộ phim hành động Mỹ năm 2024 của đạo diễn Doug Liman từ kịch bản của Anthony Bagarozzi và Chuck Mondry, và là phiên bản làm lại của bộ phim năm 1989. Phim có sự tham gia của Jake Gyllenhaal, Daniela Melchior, Conor McGregor (trong bộ phim đầu tay của anh), J. D. Pardo, Arturo Castro và Billy Magnussen. Joel Silver sản xuất bộ phim, như anh ấy đã làm bản gốc.
 Road House đã có buổi ra mắt thế giới vào ngày 8 tháng 3 năm 2024, tại South by Southwest dưới dạng phim đêm khai mạc và được Amazon MGM Studios phát hành thông qua Prime Video vào ngày 21 tháng 3 năm 2024. Bộ phim nhận được nhiều ý kiến trái chiều từ các nhà phê bình, với một số ca ngợi diễn xuất của Gyllenhaal và những người khác chỉ trích kịch bản và việc sử dụng rộng rãi CGI cho các cảnh chiến đấu.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Daniela Melchior","avatar":""},{"name":"Conor McGregor","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Hannah Love Lanier","avatar":""},{"name":"Joaquim de Almeida","avatar":""},{"name":"B.K. Cannon","avatar":""},{"name":"J. D. Pardo","avatar":""},{"name":"Arturo Castro","avatar":""},{"name":"Lukas Gage","avatar":""},{"name":"Post Malone","avatar":""},{"name":"Dominique Columbus","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Kevin Carroll","avatar":""},{"name":"Bob Menery","avatar":""},{"name":"Darr","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324242);
