INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-tri-nhan-sinh-2024', 'Phi Trì Nhân Sinh', 'Pegasus', 'https://phimimg.com/upload/vod/20240310-1/cf842bc0933c445fd983d46a71bf6feb.jpg', 'https://phimimg.com/upload/vod/20240310-1/66888488d881d52832849e9b78a15618.jpg', '<p>Bộ phim kể về Trương Trì, người bị thương nặng sau khi văng khỏi đường đua và bất ngờ xuyên không vào cơ thể của Lâm Trăn Đông 21 tuổi. Anh đã tìm mọi cách để ngăn cản anh của tuổi 24 tuổi đi vào vết xe đổ một lần nữa và giúp Lâm Trăn Đông trở thành tay đua chuyên nghiệp.<br/>&nbsp;</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
