INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-nhu-an-banh-thu-thach-sieu-cap', 'Dễ Như Ăn Bánh! Thử Thách Siêu Cấp', 'The Big Nailed It Baking Challenge', 'https://phimimg.com/upload/vod/20240304-1/14e1ef0799a133209cc7743b8790298e.jpg', 'https://phimimg.com/upload/vod/20240304-1/fef56e474276704952ea533e3d93cd63.jpg', '<p>Ở cuộc thi đầy cam go ăn theo &quot;Dễ như ăn bánh!&quot;, 10 thợ làm bánh dở tệ nhận lời khuyên từ các huấn luyện viên chuyên nghiệp trong khi cạnh tranh để giành món tiền thưởng ngọt ngào.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 10, 2024, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicole Byer","avatar":""},{"name":"Jacques Torres","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324242);
