INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-cua-thien-than-ngoc-nghech-va-ac-quy', 'Vũ Điệu Của Thiên Thần Ngốc Nghếch Và Ác Quỷ', 'The Foolish Angel Dances with the Devil', 'https://phimimg.com/upload/vod/20240130-1/52429ce4c50686929d71ce7c04c3d159.jpg', 'https://phimimg.com/upload/vod/20240130-1/ae3cbc5e8604c5855bdc659636b86b3f.jpg', '<p>Để chống lại cuộc tấn công từ thế giới trời, Ác ma Akutsu Masahiro đã đến thế giới con người để tuyển mộ những tài năng có phong cách lãnh đạo, cứu chính mình. Anh đã đến một ngôi trường cấp 3, tại đây anh che dấu thân phận thật sự của mình và gặp gỡ cô gái xinh đẹp Teno Ririi. Akutsu tin rằng có một người có thể cứu lấy thế giới ma quỷ. Vì vậy, anh đã cố gắng mời Ririi tham gia, nhưng...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuma Uchida","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Shuichiro Umeda","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Masako Nozawa","avatar":""},{"name":"Mayumi Tanaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
