INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-phiet-x-canh-sat', 'Tài Phiệt X Cảnh Sát', 'Flex X Cop', 'https://phimimg.com/upload/vod/20240130-1/19d0bbdffd0d9ce631693f785b9fa5e2.jpg', 'https://phimimg.com/upload/vod/20240130-1/f7e65d5ab3c0f255bb3732d3c17ab4d9.jpg', '<p>Jin Yi Soo có tất cả mọi thứ trong cuộc sống. Là tập đoàn thế hệ thứ ba, anh ấy không bao giờ cần sự giúp đỡ của người khác. Tuy nhiên, mọi chuyện bắt đầu thay đổi khi anh vướng vào một vụ án. Jin Yi Soo gia nhập đội điều tra bạo lực tại Sở cảnh sát Kangha chuyên truy bắt cướp. Anh ta đặt mục tiêu sử dụng sự giàu có và các mối quan hệ cá nhân của mình để làm lợi thế cho mình. Anh làm việc dưới sự chỉ huy của thám tử Lee Kang Hyun. Kang Hyun là người tận tâm, ăn nói trôi chảy và không quan tâm đến sự hiện diện của Yi Soo khi họ bắt đầu làm đối tác.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ahn Bo-hyun","avatar":""},{"name":"Park Ji-hyun","avatar":""},{"name":"Kang Sang-jun","avatar":""},{"name":"Kim Shin-bi","avatar":""},{"name":"Lee Na-eun","avatar":""},{"name":"Kwak Si-yang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
