INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-toi-ac', 'Truy Lùng Tội Ác', 'Hunt The Wicked', 'https://phimimg.com/upload/vod/20240323-1/64c376ca9c66ae05f88dd8f8a85d1d3e.jpg', 'https://phimimg.com/upload/vod/20240323-1/08fb672c8bab5b3627274ca2c9597dd7.jpg', '<p>Bộ phim này kể về thiên tài phá án Hoàng Minh Kim và thiên tài tội phạm Ngụy Vân Châu, xoay quanh bí mật cốt lõi giữa thành phố tội ác bí ẩn, với nhiều cuộc giao tranh và đối đầu sinh tử, lượng lớn cảnh sát , người trước hy sinh, người sau tiếp bước, kẻ phạm tội thì nhiều vô kể, có người liều mạng giữ gìn hòa bình, có người cửu tử nhất sinh để phá vỡ cục diện, khi mạng che của tội ác dần bị lột bỏ, khi mạng lưới ma túy ngầm dần xuất hiện, cảnh sát và kẻ giang hồ cuối cùng sẽ làm thế nào trong quá trình trừng phạt tội ác và đưa ra lựa chọn của riêng mình, đang chờ đợi họ là một cuộc kiểm tra, càng là một cuộc phán xét.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tse Miu","avatar":""},{"name":"Andy On","avatar":""},{"name":"Andrew Lin","avatar":""},{"name":"Hong Shuang","avatar":""},{"name":"Gu Jing","avatar":""},{"name":"Anson Leung Chun-Yat","avatar":""},{"name":"Han Rui","avatar":""},{"name":"Liu Sasa","avatar":""},{"name":"Jane Wu","avatar":""},{"name":"尹聪","avatar":""},{"name":"李梓嘉","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
