INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-le-cua-ma-do-tinh-binh', 'Nô Lệ Của Ma Đô Tinh Binh', 'Chained Soldier', 'https://phimimg.com/upload/vod/20240304-1/562463e269761f911bfbb56141a29cd1.jpg', 'https://phimimg.com/upload/vod/20240304-1/0a2bda40fa2852d1a0a3bfd88ba10f45.jpg', '<p>Bỗng nhiên những cánh cổng bí ẩn đã xuất hiện trên khắp Nhật Bản.

Bên kia cánh cổng là dị thứ nguyên được gọi là Ma Đô, nơi có những trái đào ban cho các thiếu nữ năng lực đặc biệt nếu ăn chúng. Để tiêu diệt Xú Quỷ đến từ nơi này, một lực lượng chiến đấu toàn các nữ chiến binh đã được thành lập với tên gọi Kháng Ma Đội.

Một ngày nọ, chàng thiếu niên tên Wakura Yuuki đã lạc vào Ma Đô trong lúc đang đi tìm đường mưu sinh và bị Xú Quỷ tấn công. Uzen Kyouka, đội trưởng xinh đẹp của Phân đội 7 thuộc Kháng Ma Đội đã lập tức tới ứng cứu. Kyouka có năng lực biến Yuuki thành nô lệ và khiến cậu có thể đánh bại Xú Quỷ. Từ đó, Yuuki đã trở thành nô lệ kiêm tạp vụ của Kháng Ma Đội.

Câu chuyện giả tưởng về “chàng thiếu niên bị xiềng xích” sẽ bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuya Hirose","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Yume Miyamoto","avatar":""},{"name":"Mari Hino","avatar":""},{"name":"Hina Tachibana","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Nene Hieda","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Rina Hidaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
