INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-em-da-suoi-am-anh', 'Cảm Ơn Em Đã Sưởi Ấm Anh', 'Angels Fall Sometimes', 'https://phimimg.com/upload/vod/20240310-1/26b62b4c71c417707903e2bdec6e521f.jpg', 'https://phimimg.com/upload/vod/20240310-1/61a10fd12e9ef46e58c803e3665e6392.jpg', '<p>Hai người bạn trẻ Lâm Thác và An Tri Tước gặp nhau trong một buổi hội chợ việc làm vào kỳ thực tập hè năm ba đại học. Họ đã phải lòng nhau ngay từ cái nhìn đầu tiên và sau khi tìm hiểu về nhau, họ quyết định đi đến hẹn hò. Khi mùa tốt nghiệp đến gần, cả hai cùng nhau bước từ thế giới mộng mơ ra ngoài xã hội, cùng nhau làm thêm, xin việc và lên kế hoạch cho tương lai. Dù chặng đường đời không mấy suôn sẻ nhưng với sự khích lệ lẫn nhau, họ đã dần đi đúng hướng. Khi mọi thứ tưởng chừng diễn ra suôn sẻ, Lâm Thác được chẩn đoán mắc bệnh xơ cứng teo cơ một bên, hay còn được gọi là ALS. Căn bệnh đã chấm dứt cuộc đời tưởng chừng bình dị nhưng tràn đầy hy vọng của Lâm Thác. Tuy cuộc đời bị rút ngắn, nhưng Lâm Thác, với sự ấm áp và yêu thương của gia đình, người yêu, bạn bè và các đồng nghiệp, đã từ bỏ ý muốn buông xuôi, học cách chung sống với căn bệnh nan y và dũng cảm chiến đấu với nó.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lin Yi","avatar":""},{"name":"Li Landy","avatar":""},{"name":"Sun Tianyu","avatar":""},{"name":"Li Xinran","avatar":""},{"name":"Lin Lu","avatar":""},{"name":"Wang Youjun","avatar":""},{"name":"Xia Minghao","avatar":""},{"name":"Ren Luomin","avatar":""},{"name":"Jiang Chao","avatar":""},{"name":"Liu Jun","avatar":""},{"name":"Liu Jie","avatar":""},{"name":"Xiong Wenwen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
