INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-on-em-da-suoi-am-anh', 'Cảm Ơn Em Đã Sưởi Ấm Anh', 'Angels Fall Sometimes', 'cảm ơn em đã sưởi ấm anh angels fall sometimes lin yi li landy sun tianyu li xinran lin lu wang youjun xia minghao ren luomin jiang chao liu jun liu jie xiong wenwen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-vuong-chi-vuong', 'Trạng Vương Chi Vương', 'Justice Sung Begins', 'https://phimimg.com/upload/vod/20240319-1/ca7996f06a4f4a3f4b543d26cebf884d.jpg', 'https://phimimg.com/upload/vod/20240319-1/a2a9b5b7288918b2d4ec7d23150a6206.jpg', '<p>Tống Thế Kiệt (do Vương Hạo Tín đóng) có cha là cai ngục Tống An (do Trương Đạt Minh đóng), nên từ nhỏ, anh đã thường xuyên lui tới chốn lao tù, tận mắt chứng kiến đủ chuyện bất công, buồn vui ly hợp ở đây. Trong thời cuộc mà triều chính hủ bại, tham quan lộng quyền, Kiệt tin rằng, luật pháp và công nghĩa chỉ là chuyện cổ tích xa vời. Chính vì vậy, anh không màng danh lợi. Sau khi âm thầm giúp đỡ người bạn không thông minh nhưng tốt tính – Hà Thủ Tín (do Lâm Tử Thông đóng) thi đỗ và làm quan, anh bỏ đi. Kiệt cùng người anh em tên A Cửu (do Kim Cang đóng) sống cuộc sống tiêu dao tự tại. Nhưng ông trời không phí phạm tài hoa, một cô gái tên Linh Lung (do Diêu Tử Linh đóng) xuất hiện, thay đổi cuộc đời Kiệt...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 11, 2024, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Vincent Wong","avatar":""},{"name":"Elaine Yiu","avatar":""},{"name":"Jin Gang","avatar":""},{"name":"Ada Wong","avatar":""},{"name":"Celina Harto","avatar":""},{"name":"Lam Tze-chung","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Chan Ho-Man","avatar":""},{"name":"Gabriel Harrison","avatar":""},{"name":"Keith Mok Ka Kam","avatar":""},{"name":"Ricky Yi Fan-Wai","avatar":""},{"name":"Pang Wai-On","avatar":""},{"name":"Ku Ming-Wah","avatar":""},{"name":"Jacquline Chong Si-Man","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324242);
