INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('not-tram-doi-bac-si', 'Nốt Trầm Đời Bác Sĩ', 'Doctor Slump', 'https://phimimg.com/upload/vod/20240207-1/4a4b3a9c2170d01bd1c77367b904beb6.jpg', 'https://phimimg.com/upload/vod/20240207-1/8d82d0da53636721562e570615643948.jpg', '<p>Một thời là đối thủ ở trường, nay hai bác sĩ xuất sắc tình cờ gặp lại – mỗi người đối mặt với nốt trầm tồi tệ nhất trong cuộc sống và bất ngờ tìm thấy niềm an ủi ở nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Shin-hye","avatar":""},{"name":"Park Hyung-sik","avatar":""},{"name":"Yoon Park","avatar":""},{"name":"Kong Seong-ha","avatar":""},{"name":"Park Won-ho","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Jang Hye-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
