INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chu-bau-troi', 'Bá Chủ Bầu Trời', 'Masters of the Air', 'https://phimimg.com/upload/vod/20240212-1/9a4b4b09b52bd8bd5260a25b34db3275.jpg', 'https://phimimg.com/upload/vod/20240212-1/f6d92f9f8db1ed683654af4400d894dd.jpg', '<p>Trong Thế chiến II, các phi công mạo hiểm mạng sống gia nhập Nhóm Ném Bom 100, tình anh em được hun đúc bởi lòng dũng cảm, sự mất mát và chiến thắng.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Austin Butler","avatar":""},{"name":"Callum Turner","avatar":""},{"name":"Anthony Boyle","avatar":""},{"name":"Nate Mann","avatar":""},{"name":"Laurie Davidson","avatar":""},{"name":"Stephen Campbell Moore","avatar":""},{"name":"James Murray","avatar":""},{"name":"Sawyer Spielberg","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324242);
