INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-o-seongsu', 'Nụ Hôn Ở Seongsu', 'Branding In Seongsu', 'https://phimimg.com/upload/vod/20240206-1/d4c83a1fb3a19b44b22ba7c44b108b5b.jpg', 'https://phimimg.com/upload/vod/20240206-1/2bdab45af537b75e8899d8ff705fcab5.jpg', '<p>Nụ hôn ở Seongsu xoay quanh về chuyện tình giữa trưởng nhóm marketing giỏi giang Kang Na Eon (Kim Ji Eun thủ vai) và thực tập sinh So Eun Ho (Park Solomon đóng). Kang Na Eon là một người nghiện công việc. Cô sẵn sàng đánh đổi tình bạn và tình yêu để đạt được thành tựu sự nghiệp. Trong khi đó, So Eun Ho là một chàng trai với vẻ ngoài thân thiện, dễ thương. Nhân vật này sống với tinh thần tận hưởng cuộc sống. Vì thế, anh thường có những bất đồng với vị sếp luôn tham công tiếc việc của mình. Có thể thấy, Kang Na Eon và So Eun Ho là hai con người hoàn toàn khác biệt. Thậm chí, Kang Na Eon còn coi So Eun Ho như kẻ ngốc. Thế nhưng, họ lại rơi vào lưới tình vì một tình huống tréo ngoe – linh hồn của cả hai bị hoán đổi cho nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Ji-eun","avatar":""},{"name":"Lomon","avatar":""},{"name":"Yang Hye-ji","avatar":""},{"name":"Kim Ho-young","avatar":""},{"name":"Jung Yi-rang","avatar":""},{"name":"Chae Soo-ah","avatar":""},{"name":"Jeon Jun-ho","avatar":""},{"name":"Lee Kwang-hee","avatar":""},{"name":"Ahn Yeon-hong","avatar":""},{"name":"Park Ki-deok","avatar":""},{"name":"Yeon Ji-hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
