INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thuat-tinh-yeu', 'Nghệ Thuật Tình Yêu', 'Art of Love', 'https://phimimg.com/upload/vod/20240316-1/ff68dfd4d9be2c3816b8c88d22392b4a.jpg', 'https://phimimg.com/upload/vod/20240316-1/bb3db8a095eb025372d4b70d2f0daf07.jpg', '<p>Sau khi biết được kẻ trộm tranh mà cô truy đuổi bấy lâu chính là người yêu cũ của cô, nữ sĩ quan làm việc cho Interpol lên kế hoạch bắt quả tang hắn.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Birkan Sokullu","avatar":""},{"name":"Esra Bilgiç","avatar":""},{"name":"Fırat Tanış","avatar":""},{"name":"Ushan Çakır","avatar":""},{"name":"Hakan Ummak","avatar":""},{"name":"Osman Alkaş","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
