INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-nuong-khat-tinh', 'Tân Nương Khát Tình', 'Rita', 'https://phimimg.com/upload/vod/20240316-1/b9f9b159e3a0204b2b599e6bf8357896.jpg', 'https://phimimg.com/upload/vod/20240316-1/1756c2ec3bfb44757b8e8aba05fa3c6c.jpg', '<p>Tân nương Rita thấy cô đơn khi chồng Ariel đi làm ở nước ngoài. Cả hai đều tìm thấy sự thỏa mãn tình dục ở người khác. Khi Ariel quay lại, cả hai đều làm như không có chuyện gì xảy ra. Nhưng liệu điều này có giúp cuộc hôn nhân của họ không tan vỡ?</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Christine Bermas","avatar":""},{"name":"Gold Aceron","avatar":""},{"name":"VR Relosa","avatar":""},{"name":"Josh Ivan Morales","avatar":""},{"name":"Amabella De Leon","avatar":""},{"name":"Sahil Khan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
