INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-nugget', 'Gà Nugget', 'Chicken Nugget', 'https://phimimg.com/upload/vod/20240316-1/5b338852fbb80317b2049e31ce3dc489.jpg', 'https://phimimg.com/upload/vod/20240316-1/42530f7c6253a1e14ee3e5de0791c279.jpg', '<p>Người phụ nữ nọ bước vào cỗ máy kỳ quặc rồi hóa thành... gà nugget?! Khi đó, bố cô và anh chàng thích cô phải dấn thân vào cuộc hành trình lạ đời để đưa cô trở về.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ahn Jae-hong","avatar":""},{"name":"Ryu Seung-ryong","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324242);
