INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-xuyen-quang-minh-tam-kiet', 'Tử Xuyên: Quang Minh Tam Kiệt', 'Eternal Brotherhood', 'https://phimimg.com/upload/vod/20240228-1/09bdbe505015ab105b5ebd76ccbcd075.jpg', 'https://phimimg.com/upload/vod/20240228-1/eba98a5c7c77a027bbd28d8a2066e58e.jpg', '<p>&quot;Tử Tuyền - Quang Minh Tam Kiệt&quot; là bộ phim cổ trang được chuyển thể từ tiểu thuyết cùng tên của tác giả Lão Trâu. Phim do Trương Manh (đạo diễn của &quot;Đại Chúa Tể&quot;) và David Wai (đạo diễn của &quot;Chung Cực Bút Ký&quot;) đồng chấp bút, với sự tham gia của Dương Húc Văn (diễn viên trong &quot;Ký Sự Truyện Kỳ Dị Đường Triều&quot;) và Lưu Vũ Ninh (diễn viên chính trong &quot;A Journey to Love&quot;). Đặc biệt, Trương Minh Hà (diễn viên chính trong &quot;Hà Thần&quot;) cũng được mời đóng vai chính trong bộ phim. Câu chuyện diễn ra tại lục địa Tây Xuyên, nơi mà xung đột và chiến tranh giữa hai bộ tộc là Tử Tuyền và Tắc Nhung đang diễn ra căng thẳng. Tử Xuyên Túc (do Dương Húc Văn thủ vai), người giữ biên giới của Tử Xuyên, trở về Đế Đô với chiến tích lớn, mang lại sự ổn định cho đất nước. Tuy nhiên, nguy cơ mới nổi lên khi quan lại lớn trong triều đình, Dương Minh Hoa, nổi loạn và gây ra cuộc nổi dậy. Tử Xuyên Túc, cùng với hai đồng đội là Đế Lâm (do Lưu Vũ Ninh thủ vai) và Tư Đặc Lâm (do Trương Minh Hà thủ vai), hợp tác để tiêu diệt mối đe dọa và đưa Tử Xuyên trở lại bình yên. Tuy nhiên, khi Tử Xuyên vẫn chưa kịp hồi phục, bộ tộc Tắc Nhung lại chính thức tuyên chiến. Hỏa lạt bốc cháy, ba anh em Tử Xuyên Túc, Đế Lâm và Tư Đặc Lâm rời xa quê hương, hành động vì tổ quốc, bảo vệ người thân yêu và vì hòa bình, tạo nên một câu chuyện đam mê và hùng tráng. Bộ phim sẽ được phát sóng trực tuyến trên trang web quốc tế của iQiyi (iQ.com).</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324242);
