INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liet-chien', 'Liệt Chiến', 'Cruel War', 'https://phimimg.com/upload/vod/20240313-1/8b22bc0b9818981a9af974d779daacf3.jpg', 'https://phimimg.com/upload/vod/20240313-1/98c36491d1ba706aba228cf6ce313ff3.jpg', '<p>Chịu ảnh hưởng của hiệu ứng nhà kính, các thiên tai tự nhiên cực đoan đã phổ biến trên toàn cầu, để chống lại ảnh hưởng của thiên tai tự nhiên đối với thực vật, Công ty Hạt giống Tinh Hỏa sử dụng công nghệ biên tập gen để phát triển và sản xuất hạt giống cao su siêu cấp SR-2, đã được Công ty DB Đông Nam Á mời thử nghiệm trồng tại vùng góc Johor Bahru. Đội trưởng đội an ninh quốc tế Lâm Tường dẫn đội, và kẻ có mưu đồ đoạt lấy hạt giống để đạt mục đích gian ác là Lê Văn Diệu, dưới sự giúp đỡ của người dân địa phương Ngô Liệt, người đã hiểu rõ sự thật và từ bỏ bóng tối, cùng nhau đánh bại âm mưu của Lê Văn Diệu, cuối cùng bảo vệ trọn vẹn câu chuyện năng lượng tích cực của hạt giống, để hạt giống đại diện cho trí tuệ và hạnh phúc có thể đâm chồi nảy lộc…</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Andy On","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Li Meng","avatar":""},{"name":"Hu Guofang","avatar":""},{"name":"Nita Lei","avatar":""},{"name":"Jing Zhao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324242);
