INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('liet-chien', 'Liệt Chiến', 'Cruel War', 'liệt chiến cruel war andy on xing yu li meng hu guofang nita lei jing zhao ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-vu-thu-dang-van-quy-su', 'Dạ Vũ Thu Đăng Vấn Quỷ Sự', 'Night Rain and Autumn Lantern Hear Strange Stories', 'https://phimimg.com/upload/vod/20240313-1/976dd483b6d898f9f8055d550c5b7bde.jpg', 'https://phimimg.com/upload/vod/20240313-1/38ab566f320de70fe2589e40536b90d0.jpg', '<p>Hồ Nam về thăm bà ngoại nhưng bất ngờ gặp phải hàng loạt sự việc kỳ lạ. Hồ Nam vô cùng bối rối và không thể phân biệt được đâu là thực và đâu là ảo ảnh. Với sự giúp đỡ của các bác sĩ, Hồ Nam dần hồi phục trí nhớ. Khi Hồ Nam bị thương, anh được Lam Ni cứu và hai người yêu nhau. Bọn cướp tấn công làng m Dương Lĩnh, Hồ Nam bị thương nặng để cứu Lam Ni và Lam Ni chết để cứu Hồ Nam. Trong lúc Hồ Nam cảm thấy tội lỗi và tự trách mình vì Lam Ni, Hồ Nam đã bị ảo giác và thêu dệt nên bộ truyện này. Để không quên Lam Ni, Hồ Nam đã từ chối phẫu thuật và đẩy cuộc sống vào khủng hoảng. Dưới sự thuyết phục của Lam Ni trong ảo giác, Hồ Nam cuối cùng đã thực hiện ca phẫu thuật. Mặc dù ý thức hời hợt đã quên Lam Ni nhưng sâu trong trái tim, Lam Ni vẫn luôn ở bên Hồ Nam.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yu Shaoqun","avatar":""},{"name":"Liu Xiaoqing","avatar":""},{"name":"Wang Jiali","avatar":""},{"name":"Wang Hui","avatar":""},{"name":"Yue Dongfeng","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324242);
