INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('time-the-series', 'Time The Series', 'Time The Series', 'https://phimimg.com/upload/vod/20240206-1/ea0a04a8be4f3c5157d6137e1c9cc3de.jpg', 'https://phimimg.com/upload/vod/20240206-1/8224c7ad0946e54b97b5b88d106de0b0.jpg', '<p>Diễn viên Foam nổi tiếng tận mắt chứng kiến người yêu mình là Chris bị cảnh sát ngộ sát. May mắn thay, số phận cho anh một cơ hội nữa, để anh trở về quá khứ, thay đổi tình huống đã khiến Chris gặp nạn. Khi một người đàn ông bí ẩn đưa cho Foam một chiếc đồng hồ có thể trở lại quá khứ, liệu anh có thể thành công thay đổi quá khứ, hoàn thành việc ngược dòng thời gian cứu người yêu này hay không, chúng ta hãy cùng chờ xem nhé!</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Camp Kunathip Trakarnchan","avatar":""},{"name":"Jimmy Jirameth Ju","avatar":""},{"name":"Petch Tutton Cherdchumalaikit","avatar":""},{"name":"Bas Karan Thongphan","avatar":""},{"name":"Art Sirirach Sornsut","avatar":""},{"name":"Bess Worapon Tapaopong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
