INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('time-the-series', 'Time The Series', 'Time The Series', 'time the series time the series camp kunathip trakarnchan jimmy jirameth ju petch tutton cherdchumalaikit bas karan thongphan art sirirach sornsut bess worapon tapaopong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sen-boss-sum-vay', 'Sen Boss Sum Vầy', 'Dog Days', 'https://phimimg.com/upload/vod/20240311-1/955f65daf346a69eb794716f7b7366b0.jpg', 'https://phimimg.com/upload/vod/20240311-1/e9007462ef67483e58bef1b8e03b8d3e.jpg', '<p>Chuyện phim mở ra một góc nhìn ấm áp, thú vị về chuỗi liên kết bất ngờ được hình thành giữa các nhân vật khác nhau thông qua tình yêu chung của họ dành cho những chú chó. Đó là sự liên kết bất chấp thế hệ, ngành nghề, tính cách: giữa một kiến trúc sư nổi tiếng toàn cầu (Youn Yuh-jung) và một người giao hàng trẻ đang chật vật kiếm sống (Tang Jun-sang); giữa một người đàn ông độc thân ghét động vật (Yoo Hai-jin) và một nữ bác sĩ thú y quên mình để cứu chữa các chú chó bị bỏ rơi (Kim Seo-hyung); giữa một cặp vợ chồng hiếm muộn (Kim Yun-jin, Jung Sung-hwa) và cô con gái nhỏ được nhận nuôi từ cô nhi viện (Yoon Chae-na); giữa một nhạc sĩ trẻ đang chăm sóc “boss” của bạn gái (Lee Hyun woo) và người yêu cũ của bạn gái đột nhiên xuất hiện với những yêu cầu kỳ quặc (Daniel Henney). Tất cả họ đều gặp nhau trong những tình huống oái ăm nhưng cũng không kém phần “cười ra nước mắt”.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Youn Yuh-jung","avatar":""},{"name":"Yoo Hai-jin","avatar":""},{"name":"Yunjin Kim","avatar":""},{"name":"Chung Sung-hwa","avatar":""},{"name":"Kim Seo-hyung","avatar":""},{"name":"Daniel Henney","avatar":""},{"name":"Lee Hyun-woo","avatar":""},{"name":"Tang Joon-sang","avatar":""},{"name":"Yoon Chae-na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
