INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-ly-hon', 'Nữ Hoàng Ly Hôn', 'Queen of Divorce', 'https://phimimg.com/upload/vod/20240208-1/9b83f6986ef1e7c53de0c5ce3ef86ba3.jpg', 'https://phimimg.com/upload/vod/20240208-1/7b45060255dfbc66a03e7ebebbe66015.jpg', '<p>Kim Sa Ra may mắn được làm dâu hào môn khi nhà chồng sở hữu công ty luật lớn nhất nhì Hàn Quốc. Nhưng chồng cô bắt ngờ phản bội và cướp đi tất cả những gì cô có. Không chùn bước, cô quyết tâm bắt đầu lại. Cô cùng cộng sự là Dong Ki Joon giúp đỡ những người rơi vào tình huống như cô.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Ji-ah","avatar":""},{"name":"Kang Ki-young","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Oh Min-suk","avatar":""},{"name":"Lee Tae-gu","avatar":""},{"name":"Seo Hye-won","avatar":""},{"name":"Park Sun-im","avatar":""},{"name":"Na Young-hee","avatar":""},{"name":"Kang Ae-sim","avatar":""},{"name":"Jeong Min-jun","avatar":""},{"name":"Lee Seo-An","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324242);
