INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-tay-quy-su', 'Tương Tây Quỷ Sự', 'XIANGXI GUISHI', 'null', 'https://phimimg.com/upload/vod/20240310-1/b71d659680bb052102cd0480a6ca925c.jpg', '<p>Hàng loạt sự việc kỳ lạ xảy ra tại làng ở phía tây Hồ Nam, họ đã trả rất nhiều tiền để thuê ông Phong Thuỷ đến hỗ trợ điều tra nhưng vô tình rơi vào cái bẫy do ông Kim bày ra và buộc ông Phong Thuỷ phải xuống lăng mộ. Ông Phong Thuỷ không một người thân dẫn dắt dân làng tham gia vào cuộc phiêu lưu khám phá lăng mộ</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Purba Rgyal","avatar":""},{"name":"Wang Wanzhong","avatar":""},{"name":"Zhaoyan Guozhang","avatar":""},{"name":"Clara Lee","avatar":""},{"name":"Shang Tielong","avatar":""},{"name":"Yue Dongfeng","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324242);
