INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-nang-lam-chieu-2024', 'Những Cô Nàng Lắm Chiêu', 'Mean Girls', 'https://phimimg.com/upload/vod/20240310-1/4c57b347ed21acf1be287cce121e0d91.jpg', 'https://phimimg.com/upload/vod/20240310-1/460b5da85c2ad0c8bee22e781c19ecd1.jpg', '<p>Phiên bản remake của bản phim Mean Girls năm 2004 đình đám một thời. Phim có sự tham gia trở lại của 2 diễn viên Tina Fey (vai cô giáo Norbury) &amp; Lindsay Lohan.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Angourie Rice","avatar":""},{"name":"Reneé Rapp","avatar":""},{"name":"Auli''i Cravalho","avatar":""},{"name":"Jaquel Spivey","avatar":""},{"name":"Avantika","avatar":""},{"name":"Bebe Wood","avatar":""},{"name":"Christopher Briney","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Busy Philipps","avatar":""},{"name":"Tina Fey","avatar":""},{"name":"Tim Meadows","avatar":""},{"name":"Lindsay Lohan","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Ashley Park","avatar":""},{"name":"Connor Ratliff","avatar":""},{"name":"Mahi Alam","avatar":""},{"name":"John El-Jor","avatar":""},{"name":"Brian Altemus","avatar":""},{"name":"Mega","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324242);
