INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-co-nang-lam-chieu-2024', 'Những Cô Nàng Lắm Chiêu', 'Mean Girls', 'những cô nàng lắm chiêu mean girls angourie rice reneé rapp auli''i cravalho jaquel spivey avantika bebe wood christopher briney jenna fischer busy philipps tina fey tim meadows lindsay lohan jon hamm ashley park connor ratliff mahi alam john el-jor brian altemus mega ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-ba-truyen-duyen-khoi', 'Mạnh Bà Truyện: Duyên Khởi', 'Biography of Meng Po', 'https://phimimg.com/upload/vod/20240310-1/126f2f1e32b14a91210a6709c2a9772d.jpg', 'https://phimimg.com/upload/vod/20240310-1/2c9d787e4d1d573a81b632888c57a27f.jpg', '<p>Trong quá khứ, khi Mạnh Thanh không phải Mạnh Phá và Thanh Hành không phải Nhạc Lão, hai người yêu nhau bất tử đã bị thần trừng buộc phải chia cắt. Mạnh Thanh chết đi, cùng với linh hồn còn sót lại của Thanh Hằng rơi vào thế giới của người chết - Võ Thành. Tại thành phố Vạn Thành nguy hiểm và đầy rẫy sự nguy hiểm, Mạnh Thanh tìm mọi cách để khôi phục lại linh hồn còn lại của Thanh Hằng, nhưng cuối cùng cô phát hiện ra rằng người yêu mình hằng mong ước vẫn còn sống. Để khám phá sự thật năm đó và tìm lại người yêu của mình, Mạnh Thanh đã đột phá thành phố và tiến về phía trước. Điều đang chờ đợi cô ở phía trước chỉ là sự thật phũ phàng. Tình yêu và tình bạn, trả thù và buông bỏ, trưởng thành và giải thoát, cuối cùng Mạnh Thanh nên lựa chọn như thế nào...</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Hua","avatar":""},{"name":"Feng Lijun","avatar":""},{"name":"Shang Tielong","avatar":""},{"name":"Rain Li","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324242);
