INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('manh-ba-truyen-duyen-khoi', 'Mạnh Bà Truyện: Duyên Khởi', 'Biography of Meng Po', 'mạnh bà truyện: duyên khởi biography of meng po he hua feng lijun shang tielong rain li ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ly-tu-thieu-khanh-du', 'Đại Lý Tự Thiếu Khanh Du', 'White Cat Legend', 'https://phimimg.com/upload/vod/20240229-1/fc42380711d115a471f7093c8a6d38d7.jpg', 'https://phimimg.com/upload/vod/20240229-1/ae6916fc580d6aeb505d4491cfce0299.jpg', '<p>Đại Lý Tự Thiếu Khanh Du là một bộ phim cổ trang trinh thám.do Vương Uy đạo diễn, với sự tham gia của Đinh Vũ Hề, Đinh Gia Văn và Châu Kỳ. Bộ phim được chuyển thể từ tác phẩm truyện tranh của tác giả RC mang tên Nhật Ký Đại Lý Tự, kể về câu chuyện về Lý Bính dẫn dắt mọi người trong Đại Lý Tự, tham gia những vụ án ly kỳ, mạo hiểm đầy kịch tính và bảo vệ sự công bằng. Câu chuyện diễn ra dưới triều đại nữ hoàng. Trong một đêm tiệc cung Đường, Lý Bính (do Đinh Vũ Hề thủ vai) được nữ hoàng trọng dụng và bổ nhiệm làm Đại Lý Tự Thiếu Khanh. Trong Đại Lý Tự, có Trần Thập (do Châu Kỳ thủ vai), Vương Thất (do Phùng Mãn thủ vai), A Lý Ba Ba (do Ngoại Nhithủ vai), Thôi Bội (do Đinh Gia Văn thủ vai) và Tôn Báo (do Trương Dịch Thông thủ vai), dưới sự hướng dẫn của Thiếu Khanh mới nhậm chức Lý Bính - mọi người cùng nhau xuyên qua mê cung, đấu tranh chống lại số phận, tìm và bảo vệ công đạo.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ding Yuxi","avatar":""},{"name":"Zhou Qi","avatar":""},{"name":"Ding Jiawen","avatar":""},{"name":"Zhang Yicong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
