INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trao-nang-ban-tay', 'Trao Nàng Bàn Tay', 'A Tale of Love and Loyalty', 'https://phimimg.com/upload/vod/20240228-1/1ba025f19459c9e688f98db12d64c4ec.jpg', 'https://phimimg.com/upload/vod/20240228-1/e3fc67c517dbb2c72cf4a3dc618a5c3a.jpg', '<p>Hoàng đế bệnh nặng, thái tử còn nhỏ tuổi, phản quân làm loạn, quân lính đã tới dưới thành, nước và nhà của nàng đều sắp sụp đổ. Bởi lẽ vậy, nàng viết thư cầu xin Nam Xuyên Vương, chỉ cần chàng dẫn binh tới cứu, nàng có thể đồng ý với chàng bất cứ chuyện gì. Cuối cùng chàng cũng tới, cứu nàng và con của nàng với phu quân. Cho dù nàng vô tình thế nào, chàng cũng không nỡ. Nhưng dù thế nào cũng phải trả giá, điều chàng muốn chưa bao giờ là ngôi báu của thiên hạ này, mà là một người mà thôi.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Richard Li","avatar":""},{"name":"Minh Gia Gia","avatar":""},{"name":"Quyền Phái Luân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324242);
