INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-the-gioi-ngam-2024', 'Quý Ông Thế Giới Ngầm', 'The Gentlemen', 'https://phimimg.com/upload/vod/20240307-1/73fe9704d483d8ed0d6d300e3000f8ba.jpg', 'https://phimimg.com/upload/vod/20240307-1/0f4306888811d425ad0eb8029ef8d19d.jpg', '<p>Thừa kế bất động sản của gia đình, chàng quý tộc Eddie phát hiện ra rằng đó là nơi một đế chế cần sa khổng lồ ngự trị và người đứng đầu đế chế đó không chịu rời đi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Theo James","avatar":""},{"name":"Kaya Scodelario","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Daniel Ings","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Peter Serafinowicz","avatar":""},{"name":"Alexis Rodney","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324243);
