INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-tuong-vat', 'Trường Tương Vật', 'Miss You Forever', 'https://phimimg.com/upload/vod/20240307-1/ace5d5c78589ed5c86f6ce307cbe1778.jpg', 'https://phimimg.com/upload/vod/20240307-1/a64a3ab638bfc4d97fb07a7e57555145.jpg', '<p>Lý Mộng Giác và Tạ Ảnh Thù trở thành &quot;phu thê trăm ngày&quot; bằng hợp đồng do sự cố ở Hoa Triều Lâu, trong mắt người ngoài, hai người rất yêu nhau, thậm chí còn hợp nhau. Lý Mộng giác đoan trang và tao nhã, mang đến cho cô sự đoan trang của một quý cô thực sự, Tạ Ảnh Thù tuy diễn xuất không tốt nhưng cũng là người ân cần và dịu dàng. Nhưng ai biết rằng hai người họ đang che giấu ý định xấu xa của nhau và âm mưu chống lại nhau. Lý Mộng Giác vốn là một trinh sát giang hồ thuộc giáo phái tác mệnh, và anh ta đã lẻn vào Hoa Triều lâu để điều tra &quot;Vụ án thiên xu&quot;. Tạ Ảnh Thù thậm chí còn che giấu danh tính của mình là Hầu tước Định Bắc, giả làm một doanh nhân giàu có là một tay chơi. Cho đến một đêm giông bão đen tối, hai người nhìn nhau mỉm cười, Lý Mộng Giác xuất hiện, cặp đôi từng giả vờ yêu nhau trong quá khứ bỗng cởi bỏ lớp giả vờ cuối cùng. Tuy nhiên, vào thời điểm đó, các vụ án giết người lần lượt xảy ra, manh mối đều chỉ về quá khứ của vụ thảm sát và vụ án Thiên Xu. Bị thúc ép bởi thực tế theo đuổi cùng một mục tiêu, cả hai đã đạt được một liên minh ngắn ngủi, và Lộc Khuê Nhi, Ảnh Yến, cùng Liễu Dữ An dấn thân vào hành trình tìm &quot;nhánh ngải cứu trên tuyết&quot; để bắt kẻ hiếp dâm...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324243);
