INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phao-hoa-nhan-gian', 'Pháo Hoa Nhân Gian', 'Islands', 'https://phimimg.com/upload/vod/20240228-1/6b55625ee90388efa5ef0a535210b4c1.jpg', 'https://phimimg.com/upload/vod/20240228-1/c950768d6934d182184fe55ad11f5c84.jpg', '<p>Người phụ nữ mạnh mẽ, quyền lực trong nhà Kiều Hải Vân từng lập ra quy định, mỗi năm Tết đến mọi người bắt buộc phải về nhà ăn Tết, từ trước đến nay chưa từng có ai phá vỡ quy tắc này, cho đến khi Lý Y Cẩm người cháu ngoan ngoãn nhất bỗng dưng đi ngược lại truyền thống, đến nhà bạn trai ăn Tết, gây nên mâu thuẫn trong gia tộc. Kiều Hải Vân có ba người con gái, người con gái cả Mạnh Minh Vỹ không phải con ruột, vì khuyết tật ở chân dẫn đến tự ti nên luôn mong con gái thành tài, quan hệ giữa hai người vô cùng căng thẳng, nhưng cuối cùng họ đã hiểu được nỗi khổ của nhau, hiểu được rằng giữ một khoảng cách thích hợp mới là cách hay nhất để gìn giữ mối quan hệ mẹ con. Người con gái thứ hai Mạnh Uyển Thanh được coi là có mối quan hệ hoàn hảo với đứa con gái học giỏi Đào Xu Na, nhưng hai người từng chia sẻ với nhau mọi điều lại vô tình phát hiện ra bí mật của nhau.&nbsp;</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Fan","avatar":""},{"name":"Ma Sichun","avatar":""},{"name":"Liang Jing","avatar":""},{"name":"Li Xiaoran","avatar":""},{"name":"Song Chunli","avatar":""},{"name":"Li Chengru","avatar":""},{"name":"Liu Jun","avatar":""},{"name":"Sun Qian","avatar":""},{"name":"Wang Tianchen","avatar":""},{"name":"Song Ningfeng","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
