INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liep-bang', 'Liệp Băng', 'The Hunter', 'https://phimimg.com/upload/vod/20240228-1/4cee4bee050717aa8cd7a52e71352920.jpg', 'https://phimimg.com/upload/vod/20240228-1/8e5522fe84299510fdf00efb81c45847.jpg', '<p>Ở thành phố Tam Bình, đội chống ma túy thu giữ được một lô ma túy đá mới, quy mô và độ tinh khiết cực hiếm, công an Tam Bình lập tức điều tra. Với sự nhạy bén và khả năng quan sát, nữ cảnh sát Triệu Hữu Nam đã nhắm tới Hoàng Tông Vĩ, một người bán hóa chất. Bất kể hắn có xảo quyệt đến đâu, cô cũng có thể tìm ra manh mối và sự thật. Đội công an do Triệu Hữu Nam đứng đầu và băng nhóm sản xuất, buôn bán ma túy do Hoàng Tông Vĩ đứng đầu là một cuộc đối đầu “mèo vờn chuột” đầy kịch tính...&nbsp;</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Songwen","avatar":""},{"name":"Annabel Yao","avatar":""},{"name":"Han Geng","avatar":""},{"name":"Bao Wenjing","avatar":""},{"name":"Su Xin","avatar":""},{"name":"Peng Yu Si","avatar":""},{"name":"Hongjia Zhu","avatar":""},{"name":"Zhou Yunpeng","avatar":""},{"name":"Chunyang Zhao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324243);
