INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-tap-sinh-trong-trai-tim-toi', 'Thực Tập Sinh Trong Trái Tim Tôi', 'Intern In My Heart', 'https://phimimg.com/upload/vod/20240228-1/e443ad5d804726d1907ebc2946dd9c63.jpg', 'https://phimimg.com/upload/vod/20240228-1/738725e9b42140ee27ccbdc6c85917ef.jpg', '<p>Ray là một thực tập sinh có khả năng đặc biệt để nhìn ra danh tính thực sự của sếp mình, Rin, người mà mọi người coi là ác quỷ. Tuy nhiên, anh sẽ làm mọi cách để chiếm được trái tim cô.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pongtiwat Tangwancharoen","avatar":""},{"name":"Sirin Horwang","avatar":""},{"name":"Virithipa Pakdeeprasong","avatar":""},{"name":"Nicole Theriault","avatar":""},{"name":"Jirakit Kuariyakul","avatar":""},{"name":"Chawinroj Likitchareonsakul","avatar":""},{"name":"Penpak Sirikul","avatar":""},{"name":"Peter Corp Dyrendal","avatar":""},{"name":"Surapol Poonpiriya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
