INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('argylle-sieu-diep-vien', 'Argylle: Siêu Điệp Viên', 'Argylle', 'https://phimimg.com/upload/vod/20240305-1/08afe7dcef04ed9fca6b92e792560320.jpg', 'https://phimimg.com/upload/vod/20240305-1/61f1126ceebbbfe1eed35b950550cb77.jpg', '<p>Khi nội dung bộ sách điệp viên của mình bám theo quá sát hoạt động của một tổ chức ngầm nguy hiểm, tiểu thuyết gia hướng nội Elly Conway và con mèo của mình bị cuốn vào thế giới tình báo ngoài đời thực, nơi không thứ gì, và không ai, giống như vẻ bề ngoài.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Bryce Dallas Howard","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"Ariana DeBose","avatar":""},{"name":"Dua Lipa","avatar":""},{"name":"John Cena","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Sofia Boutella","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324243);
