INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('argylle-sieu-diep-vien', 'Argylle: Siêu Điệp Viên', 'Argylle', 'argylle: siêu điệp viên argylle bryce dallas howard sam rockwell bryan cranston catherine o''hara henry cavill ariana debose dua lipa john cena samuel l. jackson sofia boutella ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-kiem-phieu-dieu-luc', 'Cổ Kiếm Phiêu Diêu Lục', 'Sword E Flag', 'null', 'https://phimimg.com/upload/vod/20240305-1/dff0ff4c1cbcc8076b08419dc4d3c923.jpg', '<p>Vào cuối thời nhà Minh, các hoạn quan ở Đông Xưởng từng nắm quyền, nhưng công lý vẫn còn trong lòng người dân, khi ngày càng có nhiều người đoàn kết chống lại, tình trạng hoạn quan nắm quyền dần dần đi đến hồi kết. Trong cuộc chiến tranh quyền tại triều đình, vị thái tử dưới sự chăm sóc của Lục Thiên Môn đã trốn thoát và mất tích. Đông Xưởng đang triển khai một chiến dịch rộng lớn để bắt giữ thái tử, nhằm lấy lại quyền lực kiểm soát triều đình. Ở tỉnh Thanh Hà, cách thủ đô hai trăm km, gần đây đã xảy ra một vụ án mạng, người đứng đầu Thanh Hà, Lãnh Lâm đã bị giết một cách kỳ lạ, tại hiện trường không có manh mối nào khác ngoại trừ một bức tranh kỳ lạ về một con quái vật. Vì cách chết của anh quá kỳ lạ và khủng khiếp nên những câu chuyện lan truyền về “Hạn Bạt”gây hoang mang khắp kinh thành. Có một thiếu niên hiệp sĩ trẻ tuổi tên là Lãnh Lạc Phong, người chăm chỉ điều tra vụ án giết người do &quot;Hạn Bạt&quot; gây ra, với sự tận tâm ngang bằng hoặc thậm chí cao hơn cả những người điều tra chuyên nghiệp. Lãnh Lạc Phong là sinh viên của Học viện Linh Lan, một trường dành riêng để đào tạo nhân tài về văn hóa và quân sự cho triều đình. Anh ta có võ công mạnh mẽ và là một trong những tài năng xuất sắc tại học viện. Kể từ vụ án mạng ở Thanh Hà phủ</p>', 'Full', 1, 'single', 'ongoing', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"YuanFufu","avatar":""},{"name":"Mengyuan Xu","avatar":""},{"name":"Wang Hefan","avatar":""},{"name":"Yi Yi Zi","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324243);
