INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-hac-tien-sinh', 'Thiên Hạc Tiên Sinh', 'Master Qianhe', 'https://phimimg.com/upload/vod/20240305-1/4d2ad737e11133cc339a052e742beb9d.jpg', 'https://phimimg.com/upload/vod/20240305-1/3f14c756783d00cca4142e815c360ab2.jpg', '<p>Bộ phim này do Trần Lý Dương đạo diễn, Chung Phát là diễn viên chính, với sự tham gia của Tống Mỹ Na, Zukar và các diễn viên khác, thuộc thể loại cổ trang, kinh dị và hành động. Truyền thuyết trong thời kỳ loạn lạc Cộng hòa Nhân dân Trung Hoa, một đạo sĩ tên Long Tam, sở hữu kỹ năng đặc biệt được giao nhiệm vụ đi đến Bao Đầu để giải quỷ cứu người, trừ ma bảo đạo. Trong hành trình, ông bị băng cướp tấn công tại làng Hoàng Miếu, gặp và cứu giúp tiên nữ Tiên Nhi, người tạo ra ảo ảnh. Tại thành phố Bao Đầu, để tìm lại vũ khí ma thuật bị mất của mình và giúp đỡ nàng tiên quỷ bị mắc kẹt ở phía dưới, anh ta đã đánh tan băng cướp, đánh thức Hải Yến đang bị nhiễm độc. Nhưng không ngờ, lại có những thế lực đứng sau băng cướp. Dưới sự giúp đỡ của Tiên Nhi và Hải Yến, Long Tam tiếp tục phát hiện ra tội ác của quan đội đối với những cô gái trẻ. Và kẻ chủ mưu là người lính đã phản bội Tiên Nhi cùng là kẻ đã hại người dân làng Hoàng Miếu nhiều năm trước đó.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Paul Chung Fat","avatar":""},{"name":"Meina Song","avatar":""},{"name":"Zu Ka Er","avatar":""},{"name":"Jin Qingling","avatar":""},{"name":"Dong Shaohui","avatar":""},{"name":"Meiling Jin","avatar":""},{"name":"Ma Danhe","avatar":""},{"name":"Zhao Hong","avatar":""},{"name":"Li Jiateng","avatar":""},{"name":"Shu Shu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324243);
