INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-trang-bao-do', 'Tây Trang Bạo Đồ', 'Desperado', 'https://phimimg.com/upload/vod/20240305-1/1da642d33524f54d5b482827db3f8a62.jpg', 'https://phimimg.com/upload/vod/20240305-1/f789b6a32ba37f28b7714796af5af899.jpg', '<p>Nhiều năm trước, Chu Khắc một mình đột nhập vào hang ổ của băng đảng xã hội đen để giải cứu anh trai Bano, nhưng cuối cùng lại bị bắt và giam giữ. Nhiều năm trôi qua, sau khi ra tù, Chu Khắc sống một cuộc sống thoải mái ở thành phố với biệt danh Lý Phi. Tuy nhiên, trong thành phố yên bình đó, có những sóng gió âm thầm bắt đầu nổi lên, và làn sóng tội ác mới đang trỗi dậy, nhưng lần này, Chu KHắc sẽ phải đối mặt với điều gì và anh ta sẽ chọn hướng đi nào.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Danny Chan Kwok-kwan","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Miya Muqi","avatar":""},{"name":"Ken Lok Tat-Wah","avatar":""},{"name":"Baotong Wang","avatar":""},{"name":"Luo Liqun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324243);
