INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-minh-huu-con', 'Bắc Minh Hữu Côn', 'Kun in the Distant Ocean', 'null', 'https://phimimg.com/upload/vod/20240305-1/f745d3770456af936b5bcd0d2f5eb34b.jpg', '<p>A Li là cô dâu của hải thần có vẻ đẹp không tuổi đã thu hút các cô gái loài người hiến tế để trở thành cô dâu của hải thần. Cô gái trẻ Linh Vũ cùng chị gái vô tình đi vào vùng cấm của tộc Hải Thần, gặp hoàng tử thật và giả, một xấu một đẹp, cô dính líu đến âm mưu của cặp đôi hải thần bị đóng băng trong cung điện dưới lòng đất. Vô số cô dâu hiến tế bị phong ấn trong quan tài băng và biến thành xác sống, yêu quái khổng lồ của rừng Hắc Xà tái xuất, quái vật biển khổng lồ quậy tung biển cả, , mở miệng rộng đầy máu để nuốt chửng những người. Hoàng tử hải thần, khó phân biệt giữa thiện và ác, và tình yêu nhầm lẫn giữa hai chị em gái của gia đình ngư dân, sẽ dẫn chúng ta đi về đâu?</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Xiangfei","avatar":""},{"name":"Wang Yitong","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324243);
