INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-ngua-cuop-dao', 'Chặn Ngựa Cướp Đao', 'Blocking The Horse', 'https://phimimg.com/upload/vod/20240303-1/36c01d281a529a754c459df781045a3e.jpg', 'https://phimimg.com/upload/vod/20240303-1/5a6ca0b30707e37bb21e20614f865015.jpg', '<p>Trong cuộc Bắc phạt của Ủng Hi vào đầu thời nhà Tống, Dương Nghiệp tổng tư lệnh của quân Tây Lộ, một mình tiến sâu vào quân đội và hy sinh anh dũng, được trao một thanh kiếm vàng chín vòng do hoàng đế ban tặng và rơi vào lãnh thổ nhà Liêu. Mười năm sau, Dương Bát Thư và Dương Cửu Muội trưởng thành nhớ linh hồn của cha mình trên thiên đường và thề sẽ lấy lại thanh kiếm vàng và khôi phục quyền lực của nhà Tống. Sau khi trốn thoát trong gang tấc, hai chị em đã hợp tác để đoạt lấy thanh kiếm vàng, trên đường trở về, họ gặp Tiêu Quang Phổ , một người lính của Dương Nghiệp, chủ một quán trọ ở biên giới, hai bên không hề quen biết nhau trước khi giao chiến. , họ hợp lực chiến đấu với ba nhóm quân địch và chống chọi đến chết, cuối cùng hộ tống thanh kiếm về quê hương.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Song Tianshuo","avatar":""},{"name":"Zhang Xintong","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Yu Kang","avatar":""},{"name":"You Xianchao","avatar":""},{"name":"Xinlei Liu","avatar":""},{"name":"Wang Ganggang","avatar":""},{"name":"Tan Kai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324243);
