INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-cung-tran-co-lau', 'Lăng Cung Trấn Cổ Lâu', 'Ancient Building Town Mausoleum Palace', 'https://phimimg.com/upload/vod/20240303-1/85228bb07b68c160d11a66dd3293ba6f.jpg', 'https://phimimg.com/upload/vod/20240303-1/05e42509d5d4a7528f2fb180c5c2c09a.jpg', '<p>Những kẻ cướp mộ Vương Khánh Niên và Lý Nhị Đản cải trang thành công nhân dầu mỏ đến một thị trấn nhỏ ở phía tây bắc Trung Quốc để bí mật tìm kiếm ngôi mộ huyền thoại của Con đường tơ lụa cổ đại. Vương Khánh Niên giúp một đoàn xe bị mắc kẹt thoát khỏi hiểm nguy. Thành viên của đoàn xe bao gồm các chuyên gia về phía Tây như giáo sư Triệu và Lâm Uyển. Vương Khánh Niên và Lý Nhị Đản tham gia vào đội khảo cổ học dưới danh nghĩa là hướng dẫn viên. Dưới sự dẫn dắt của Vương Khánh Niên, họ tìm thấy mục tiêu và phát hiện ra thi thể của những nhà thám hiểm trước đó. Lâm Uyển suy đoán rằng trong những di vật có một cuốn sách cổ viết về đất nước cổ xưa Lâu Lan, và sau khi được Vương Khánh Niên giải mã, họ biết rằng Lâu Lan đã bị tấn công bởi quái vật đáng sợ. Vị vua cuối cùng của Lâu Lan đã đánh bại con quỷ và xây dựng một &quot;quan tài ức chế linh hồn&quot; để phong ấn con quỷ với chính mình. Dưới đống đổ nát là vị trí của &quot;Quan tài linh hồn&quot;...</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sheng Luyue","avatar":""},{"name":"Lou Jiayue","avatar":""},{"name":"Bao Haochen","avatar":""},{"name":"Shi Damao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324243);
