INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ti-thua-dai-nhan-than-yeu', 'Ti Thừa Đại Nhân Thân Yêu', 'Marry Me, My Evil Lord', 'https://phimimg.com/upload/vod/20240301-1/6df3ca85d1889aa2d74d4afd58f50870.jpg', 'https://phimimg.com/upload/vod/20240301-1/5d25687979e6f5e1800b32c0eb062ea6.jpg', '<p>Mei Shiqi, một cô gái bảo vệ cấp dưới của Sở Y tế Yu Chaoyin, khao khát quyền tự do kết hôn thông qua việc thăng chức và tăng lương. Một vụ án mạng kỳ lạ xảy ra trong cung điện, và người vợ lẽ yêu quý của hoàng đế qua đời. Hoàng đế Yu đã ra lệnh cho Sở Yinwei và Cục Giám sát lần lượt điều tra vụ án. Trong quá trình điều tra, Mei Shiqi gặp phải thanh tra Si Cheng Leng Moyan nham hiểm và nham hiểm. Hai người nghi ngờ lẫn nhau, và họ cản trở lẫn nhau, gây ra rất nhiều hỗn loạn và ly kỳ ly kỳ. Sau khi trải qua nhiều tình huống sinh tử và tương trợ lẫn nhau, họ dần dần bắt đầu tin tưởng lẫn nhau. Cả hai đã hợp tác chân thành để truy tìm thủ phạm thực sự của tội ác đe dọa an ninh quốc gia và an toàn của đất nước, trong cuộc đấu tranh trí tuệ và lòng dũng cảm với kẻ chủ mưu đằng sau hậu trường, họ đã yêu nhau và giết nhau, và cuối cùng xác định rằng người kia là tình yêu của đời mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Haodong Ma","avatar":""},{"name":"Wang Xinting","avatar":""},{"name":"Su Zhenhua","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
