INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-di-nhan-phan-ii', 'Truy Lùng Dị Nhân Phần II', 'Code 8 Part II', 'https://phimimg.com/upload/vod/20240301-1/6c74c9cd721dc67b3f699aebb28af748.jpg', 'https://phimimg.com/upload/vod/20240301-1/60b6b6b96097050e4d506c52b6c230ce.jpg', '<p>Theo chân một cô gái chiến đấu để đòi lại công lý cho người anh trai bị sát hại bởi những sĩ quan cảnh sát tham nhũng. Cô nhờ đến sự giúp đỡ của một cựu tù nhân và cộng sự cũ của anh ta. Họ phải đối mặt với một trung sĩ cảnh sát được đánh giá cao và được bảo vệ tốt nhưng lại không muốn trở thành người như vậy.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Stephen Amell","avatar":""},{"name":"Robbie Amell","avatar":""},{"name":"Alex Mallari Jr.","avatar":""},{"name":"Sirena Gulamgaus","avatar":""},{"name":"Aaron Abrams","avatar":""},{"name":"Moe Jeudy-Lamour","avatar":""},{"name":"Akiel Julien","avatar":""},{"name":"Natalie Liconti","avatar":""},{"name":"Nneka Elliott","avatar":""},{"name":"Sammy Azero","avatar":""},{"name":"Jean Yoon","avatar":""},{"name":"Altair Vincent","avatar":""},{"name":"Sarena Parmar","avatar":""},{"name":"Jessica Allen","avatar":""},{"name":"Jane Moffat","avatar":""},{"name":"Sunnie McFadden","avatar":""},{"name":"Noorin Gulam","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324243);
