INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-o-cua-so-3-ta-nhin-thay-nhau', 'Qua Ô Cửa Sổ 3: Ta Nhìn Thấy Nhau', 'Through My Window 3: Looking at You', 'https://phimimg.com/upload/vod/20240301-1/b696b344ffaac5bde855886816130b06.jpg', 'https://phimimg.com/upload/vod/20240301-1/f2d43f9ef9dca1da88b0e3167870dbb0.jpg', '<p>Raquel và Ares không quên được nhau kể cả khi đang hẹn hò với người khác. Liệu họ có bất chấp áp lực gia đình để về bên nhau trong chương cuối của bộ ba phim này?</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Clara Galle","avatar":""},{"name":"Julio Peña","avatar":""},{"name":"Natalia Azahara","avatar":""},{"name":"Eric Masip","avatar":""},{"name":"Andrea Chaparro","avatar":""},{"name":"Emilia Lazo","avatar":""},{"name":"Ivan Lapadula","avatar":""},{"name":"Hugo Arbues","avatar":""},{"name":"Pilar Castro","avatar":""},{"name":"Rachel Lascar","avatar":""},{"name":"Abel Folk","avatar":""},{"name":"Omar Chaparro","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324243);
