INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-cap-2024', 'Nâng Cấp', 'Upgraded', 'https://phimimg.com/upload/vod/20240301-1/b2af4511a4a37881ecf7c93628907782.jpg', 'https://phimimg.com/upload/vod/20240301-1/05294b99b0da9ef09a919e4399723ebb.jpg', '<p>Upgraded 2024 là một bộ phim hài lãng mạn đầy sáng tạo, đã được phát hành trên Amazon Prime Video vào ngày 9 tháng 2 năm 2024. Câu chuyện xoay quanh cuộc sống của Ana, một cô gái trẻ đầy tham vọng và mơ ước về một sự nghiệp trong lĩnh vực nghệ thuật. Trong quá trình cố gắng để gây ấn tượng với sếp khó tính của mình, Claire, Ana đã vô tình gặp Will, một chàng trai lịch lãm và quyến rũ. Một sự nhầm lẫn nhỏ đã khiến Ana trở thành sếp của mình. Với lời nói dối này, cuộc sống của cô bắt đầu thay đổi hoàn toàn. Ana và Will dần trở nên thân thiết và tình cảm giữa họ nảy nở. Tuy nhiên, những rắc rối và tình huống dở khóc dở cười không ngừng xảy ra khi Ana phải duy trì lời nói dối của mình để không bị phát hiện.&nbsp;</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Camila Mendes","avatar":""},{"name":"Archie Renaux","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Lena Olin","avatar":""},{"name":"Anthony Stewart Head","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Rachel Matthews","avatar":""},{"name":"Grégory Montel","avatar":""},{"name":"Andrew Schulz","avatar":""},{"name":"Saoirse-Monica Jackson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324243);
