INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-phai-nhuom-do', 'Tay Phải Nhuốm Đỏ', 'Red Right Hand', 'https://phimimg.com/upload/vod/20240229-1/bda72544e140661e832f6fd5cc62b1c4.jpg', 'https://phimimg.com/upload/vod/20240229-1/6f3e160a0cb3d5a6f8fffe040ba1c6ac.jpg', '<p>Red Right Hand (2024) Cash đang cố gắng sống một cuộc sống trung thực và yên tĩnh khi chăm sóc đứa cháu gái mới mồ côi Savannah ở thị trấn Appalachian của Quận Odim. Khi tên trùm tàn bạo Big Cat, người điều hành thị trấn buộc anh phải quay lại phục vụ bà ta, Cash biết rằng anh có khả năng làm bất cứ điều gì – thậm chí là giết người – để bảo vệ thị trấn và gia đình duy nhất anh còn lại. Khi cuộc hành trình trở nên khó khăn hơn, Cash bị cuốn vào một cơn ác mộng làm mờ đi ranh giới giữa thiện và ác.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Orlando Bloom","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"Scott Haze","avatar":""},{"name":"Chapel Oaks","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Mo McRae","avatar":""},{"name":"Brian Geraghty","avatar":""},{"name":"Kenneth Miller","avatar":""},{"name":"Nicholas Logan","avatar":""},{"name":"Daniel David Stewart","avatar":""},{"name":"William McKinney","avatar":""},{"name":"James Lafferty","avatar":""},{"name":"Jeremy Ratchford","avatar":""},{"name":"Jemuel Morris","avatar":""},{"name":"Jared Wofford","avatar":""},{"name":"Evan Gamble","avatar":""},{"name":"Tom F","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324243);
