INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hi-quyen-thuong-lac-thanh', 'Hỉ Quyển Thường Lạc Thành', 'The Happy Seven in Changan', 'https://phimimg.com/upload/vod/20240206-1/8fbf8c52e31fd4ebf80427362b73f640.jpg', 'https://phimimg.com/upload/vod/20240206-1/e189ab9ef5b9ff482946c65d5372c57b.jpg', '<p>Tạ Toàn Giai đến thành Trường Lạc tìm cha, bất ngờ trở thành con gái duy nhất của phú ông Lý Thiên Địa nhưng thứ mà cô thừa kế không phải là gia tài giàu có, mà là khoản nợ khổng lồ. Thượng Quan Cổ Xuyên đến đòi nợ, Phạm Trọng Cử vào kinh đi thi và thiếu hiệp Lưu Lãng Tề đến báo ân đều tề tựu ở Lý phủ. Tạ Toàn Giai một mặt sắp xếp chỗ ở cho mọi người, một mặt cho thuê phòng để giải quyết nợ nần. Từ đó, ai nấy đều dồn sức lập nghiệp ở Trường Lạc, sống một cuộc sống đầy sóng gió nhưng vui vẻ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ma Tianyu","avatar":""},{"name":"Bu Guanjin","avatar":""},{"name":"Zong Juntao","avatar":""},{"name":"Zhang Yiduo","avatar":""},{"name":"Cheng Guo","avatar":""},{"name":"Li Yinwei","avatar":""},{"name":"Ren Zihui","avatar":""},{"name":"Merxat","avatar":""},{"name":"Cao Zheng","avatar":""},{"name":"Gao Xiaopan","avatar":""},{"name":"Tong Lei","avatar":""},{"name":"Shang Jiu Xi","avatar":""},{"name":"Chui Na Li Sha","avatar":""},{"name":"Eleanor Lee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324243);
