INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hi-quyen-thuong-lac-thanh', 'Hỉ Quyển Thường Lạc Thành', 'The Happy Seven in Changan', 'hỉ quyển thường lạc thành the happy seven in changan ma tianyu bu guanjin zong juntao zhang yiduo cheng guo li yinwei ren zihui merxat cao zheng gao xiaopan tong lei shang jiu xi chui na li sha eleanor lee ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-lai-bac-vang-vao-nam-ra-bac', 'Nam Lai Bắc Vãng (Vào Nam Ra Bắc)', 'Always on the Move', 'https://phimimg.com/upload/vod/20240206-1/08eb6a0086d86b67b3986acc4ab8cc4e.jpg', 'https://phimimg.com/upload/vod/20240206-1/d055b5524f094774522ecfab2d76c65e.jpg', '<p>&quot;Nam Lai Bắc Vãng&quot; là một bộ phim truyền hình thể loại tình cảm lịch sử do Trịnh Hiểu Long (&quot;Hậu Cung Chân Hoàn Truyện&quot;) và Lưu Chương Mục (&quot;Hành Động Phá Băng&quot;) đồng đạo diễn. Phim có sự tham gia của Bạch Kính Đình (&quot;Tân Xuyên Nhật Thường&quot;), Kim Thần (&quot;Được Ăn Cả Ngã Về Không&quot;), và Đinh Dũng Đại (&quot;Phong Thần 1: Tam Bộ Khúc&quot;) đảm nhận các vai chính. Vào cuối thập kỷ 1970, trên chuyến tàu hơi nước từ Ninh Dương đến cáp Nhĩ Tân, Uông Tân (do Bạch Kính Đình thủ vai), một thanh niên làm công việc kiểm soát trên tàu, đang chăm chỉ thực hiện nhiệm vụ giữ trật tự giữa đám đông hối hả. Anh nhầm lẫn Mã Khôi (do Đinh Dũng Đại thủ vai), một cựu cảnh sát đường sắt là một kẻ đang chạy trốn, cả hai mở đầu một mối quan hệ thầy trò không mấy dễ dàng. Từ việc ban đầu không thích nhau, đến sự đồng cảm và tôn trọng lẫn nhau, Uông Tân và Mã Khôi đồng lòng chiến đấu tại tuyến đầu của cảnh sát đường sắt. Họ chống lại tội phạm trộm cắp, truy bắt những người bắt cóc trẻ em, chống ma túy, tuần tra, và đối mặt với những vụ cướp, lừa đảo, luôn đặt sự an toàn của mỗi hành khách lên hàng đầu trong công việc, không ngừng bảo vệ sự an toàn của những chuyến tàu từ Nam đi Bắc và ngược lại. Uông Tân và Mã Khôi, hai thế hệ cảnh sát đường sắt, truyền lửa nghề từ thế hệ này sang thế hệ khác, chứng kiến sự phát triển của đường sắt Trung Quốc từ máy hơi nước đến đầu máy điện rồi đến tàu cao tốc. Họ là nhân chứng của sự biến đổi nhanh chóng của Trung Quốc. Bộ phim sẽ được phát sóng trực tuyến trên trang iQ.com, nền tảng quốc tế của iQiyi.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Jingting","avatar":""},{"name":"Ding Yongdai","avatar":""},{"name":"Jin Chen","avatar":""},{"name":"Zuo Xiaoqing","avatar":""},{"name":"Liu Jun","avatar":""},{"name":"Jiang Yan","avatar":""},{"name":"Hu Ke","avatar":""},{"name":"Ni Dahong","avatar":""},{"name":"Li Naiwen","avatar":""},{"name":"Ren Zhengbin","avatar":""},{"name":"张瑞涵","avatar":""},{"name":"Tang Xu","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Ning Li","avatar":""},{"name":"Gan Ting Ting","avatar":""},{"name":"Wang Herun","avatar":""},{"name":"Pan Binlong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324243);
