INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-tan-khoc', 'Trận Chiến Tàn Khốc', 'Land of Bad', 'https://phimimg.com/upload/vod/20240221-1/f29f0a93811b570b7abf68b9694cd551.jpg', 'https://phimimg.com/upload/vod/20240221-1/54dd3e0f841357547de18d0821c08bea.jpg', '<p>Khi một nhiệm vụ đặc biệt của Lực lượng Delta gặp trục trặc nghiêm trọng, phi công lái máy bay không người lái Reaper của Lực lượng Không quân có 48 giờ để khắc phục những gì đã biến thành một chiến dịch giải cứu hoang dã. Không có vũ khí và không có phương tiện liên lạc nào ngoài chiếc máy bay không người lái phía trên, nhiệm vụ trên mặt đất</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Liam Hemsworth","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Luke Hemsworth","avatar":""},{"name":"Ricky Whittle","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Chika Ikogwe","avatar":""},{"name":"Daniel MacPherson","avatar":""},{"name":"Robert Rabiah","avatar":""},{"name":"Jack Finsterer","avatar":""},{"name":"Chris Masters Mah","avatar":""},{"name":"Lincoln Lewis","avatar":""},{"name":"Lachlan Engeler","avatar":""},{"name":"Miguel Usares","avatar":""},{"name":"Timothy Latimer","avatar":""},{"name":"Michael Joaquin","avatar":""},{"name":"Joey Vieira","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324243);
