INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-di-ma-lay-chong-toi', 'Cô Đi Mà Lấy Chồng Tôi', 'Marry My Husband', 'https://phimimg.com/upload/vod/20240103-1/828367adc1b1ed49adbeee3e846f70bd.jpg', 'https://phimimg.com/upload/vod/20240103-1/dcb136dc0b17079f4ac1bd887bb83bb0.jpg', '<p>Khi Ji-won, một bệnh nhân ung thư 37 tuổi, bước vào gặp chồng và cũng là bạn thân của cô, cô nhận ra cả cuộc đời mình chỉ là một lời nói dối. Tệ hơn nữa, cô lại chết một cách bi thảm dưới tay chồng mình. Liệu mọi chuyện có khác đi nếu cô ấy đưa ra những lựa chọn khác? May mắn thay cho Ji-won, cô có cơ hội viết lại số phận của mình khi được tái sinh thành bản thân lúc trẻ. Lần này, cô thề sẽ sống một cuộc sống hạnh phúc. Nhưng trước hết là sự trả thù. Kế hoạch của cô ấy? Để gả người bạn thân cũ của mình cho người chồng dối trá, lừa dối của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Min-young","avatar":""},{"name":"Na In-woo","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Song Ha-yoon","avatar":""},{"name":"Lee Gi-kwang","avatar":""},{"name":"Gong Min-jeung","avatar":""},{"name":"Kwon BoA","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
