INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ready-set-love', 'Ready, Set, Love', 'Ready, Set, Love', 'https://phimimg.com/upload/vod/20240220-1/4782cede7af8bf0acae8f2b63f9ac533.jpg', 'https://phimimg.com/upload/vod/20240220-1/4693c5fa2d9718770b3fd22c8841d70b.jpg', '<p>Ở thế giới đang vật lộn với tình trạng số lượng đàn ông ngày càng giảm, người phụ nữ khiêm tốn nọ tham gia một cuộc thi hẹn hò do chính phủ tài trợ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pongtiwat Tangwancharoen","avatar":""},{"name":"Kemisara Paladesh","avatar":""},{"name":"Nichapalak Thongkham","avatar":""},{"name":"Natthaweeranuch Thongmee","avatar":""},{"name":"Panadda Wongphudee","avatar":""},{"name":"Trisanu Soranun","avatar":""},{"name":"Jaytiya Naiwattanakul","avatar":""},{"name":"Neennara Boonnithipaisit","avatar":""},{"name":"Anongnart Yusananda","avatar":""},{"name":"Tharathorn Bhumirat","avatar":""},{"name":"Chayapak Tunprayoon","avatar":""},{"name":"Kunchanuj Ken","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324243);
