INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ready-set-love', 'Ready, Set, Love', 'Ready, Set, Love', 'ready, set, love ready, set, love pongtiwat tangwancharoen kemisara paladesh nichapalak thongkham natthaweeranuch thongmee panadda wongphudee trisanu soranun jaytiya naiwattanakul neennara boonnithipaisit anongnart yusananda tharathorn bhumirat chayapak tunprayoon kunchanuj ken ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alienoid-2-da-chieu-hon-chien', 'Alienoid 2: Đa Chiều Hỗn Chiến', 'Alienoid: The Return to the Future', 'https://phimimg.com/upload/vod/20240219-1/e6c34f5c559d88456916874e87f787ed.jpg', 'https://phimimg.com/upload/vod/20240219-1/724303abd883e1aa8d25720220b91a16.jpg', '<p>Ean (KIM Tae-ri) bị mắc kẹt ở quá khứ trong khi cố ngăn chặn sự trốn thoát của những tù nhân ngoài hành tinh bị nhốt trong cơ thể con người. Cô cuối cùng đã tìm thấy Gươm Thần, có thể mở ra cánh cổng xuyên thời gian, và giờ phải tìm Thunder (KIM Woo-bin) để trở về hiện tại. Trong khi đó, Muruk (RYU Jun-yeol), người giúp Ean thoát khỏi những tình huống nguy hiểm, bắt đầu cảm thấy bất an khi anh nhận thấy sự hiện diện của một sinh vật lạ trong cơ thể mình. Trở lại hiện tại, sự phát tán của khí haava bởi Thủ Lĩnh, kẻ lãnh đạo những tù nhân ngoài hành tinh đã khiến hàng ngàn người chết. Min Gaelin (LEE Ha-nee) người tình cờ chứng kiến điều này đã nhận ra rằng đây chỉ là khởi đầu. Chỉ còn 48 phút trước khi tất cả các bong bóng khí haava được thiết lập để nổ tung, cánh cửa thời gian cuối cùng được mở ra và Muruk, Thunder, cùng Lam Tử và Hắc Nương được kéo về hiện tại cùng với Ean. Những bí mật động trời dần được hé lộ. Họ phải làm gì để chống lại những sinh vật ngoài hành tinh, ngăn chặn sự nổ tung của khí haava và giải cứu nhân loại?</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryu Jun-yeol","avatar":""},{"name":"Kim Tae-ri","avatar":""},{"name":"Kim Woo-bin","avatar":""},{"name":"Lee Ha-nee","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Shin Jung-keun","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Lee Si-hoon","avatar":""},{"name":"So Ji-sub","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Choi Yu-ri","avatar":""},{"name":"Kim Ki-cheon","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Ok Ja-yeon","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324243);
