INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('alienoid-2-da-chieu-hon-chien', 'Alienoid 2: Đa Chiều Hỗn Chiến', 'Alienoid: The Return to the Future', 'alienoid 2: đa chiều hỗn chiến alienoid: the return to the future ryu jun-yeol kim tae-ri kim woo-bin lee ha-nee yum jung-ah jo woo-jin kim eui-sung jin sun-kyu shin jung-keun yoon kyung-ho lee si-hoon so ji-sub kim dae-myung choi yu-ri kim ki-cheon kim hae-sook yoo jae-myung yoon byung-hee ok ja-yeon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-noi-thi-tran-nho', 'Chuyện Nơi Thị Trấn Nhỏ', 'Small Town Stories', 'https://phimimg.com/upload/vod/20240212-1/4aecc58e1fd79086b5868348b4fb4a1a.jpg', 'https://phimimg.com/upload/vod/20240212-1/b11eea96e35a105d01f8f8a1c71fd4b5.jpg', '<p>Mặc Địch, một nữ sinh viên cao cấp tại trường đại học Bắc Kinh chuyên ngành âm nhạc, vì bệnh tật mà không thể tham gia kỳ thi, từ bỏ cơ hội gia nhập đoàn quốc gia, buộc phải trở về quê nhà để nghỉ dưỡng. Tại đây, cô gặp phải Bạch Lãng, chủ tịch của một công ty tổ chức tại thị trấn nhỏ, người này thông minh linh hoạt và hiểu biết về con người và xã hội. Hai người, mỗi người một tính cách và lịch sử phát triển khác nhau, từ lúc không quen biết đến hợp tác chân thành, họ đã thay đổi lẫn nhau. Câu chuyện mà họ trải qua tại thị trấn nhỏ này, giống như một bữa ăn đa dạng khó quên, cũng giống như một quán ăn với những tiếng cười và nước mắt xen lẫn. Mọi người đều có thể cảm nhận được sự đa dạng về văn hóa, sự ấm áp, lạnh lẽo và những biến đổi trong cuộc sống qua câu chuyện này.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Karlina Zhang","avatar":""},{"name":"Gao Zhiting","avatar":""},{"name":"Lu Xiaoyu","avatar":""},{"name":"Wu Xingjian","avatar":""},{"name":"Song Jiateng","avatar":""},{"name":"Zhu Rui","avatar":""},{"name":"Na Renhua","avatar":""},{"name":"Tan Xihe","avatar":""},{"name":"Tian Zheng","avatar":""},{"name":"Wang Qing","avatar":""},{"name":"Xu Shaoying","avatar":""},{"name":"Niu Chao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
