INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-noi-thi-tran-nho', 'Chuyện Nơi Thị Trấn Nhỏ', 'Small Town Stories', 'chuyện nơi thị trấn nhỏ small town stories karlina zhang gao zhiting lu xiaoyu wu xingjian song jiateng zhu rui na renhua tan xihe tian zheng wang qing xu shaoying niu chao ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-ly-ke-sat-nhan', 'Nghịch Lý Kẻ Sát Nhân', 'A Killer Paradox', 'https://phimimg.com/upload/vod/20240209-1/eb2d11593c8620359b9be7324f85b515.jpg', 'https://phimimg.com/upload/vod/20240209-1/f1e23bc6cb63a3a9fcaf987557441050.jpg', '<p>Nghịch Lý Kẻ Sát Nhân (A Killer Paradox) là một bộ phim Hàn Quốc thuộc thể loại hành động, chính kịch của đạo diễn Lee Chang Hee. Phim này, được chuyển thể từ webtoon cùng tên của Kkomabi, phim kể câu chuyện về một chàng trai vô tình giết chết kẻ sát nhân hàng loạt và một thám tử không ngừng truy đuổi anh ta. Trong phim sẽ có sự tham gia diễn xuất của các diễn viên: Choi Woo Shik, Son Suk Ku, Lee Hee Jun,...Nội dung phim Nghịch Lý Kẻ Sát Nhân xoay quanh câu chuyện kể về nhân vật Lee Tang (Choi Woo Sik thủ vai), một sinh viên đại học bình thường. Khi đang làm việc bán thời gian tại một cửa hàng tiện lợi, anh đánh nhau với một người đàn ông say rượu thô lỗ và vô tình giết chết anh ta. Anh ta sợ rằng mình đã giết một người và cuộc sống có thể bị hủy hoại. Hóa ra, người đàn ông đã chết là một kẻ giết người hàng loạt và anh ta đã bị truy nã suốt 4 năm qua. Lee Tang nhận ra rằng mình có khả năng đặc biệt để nhận ra những kẻ xấu đáng phải chết. Lee Tang sớm trở thành kẻ giết người hàng loạt để tiêu diệt những kẻ độc ác này. Thám tử Jang Nan Gam (Son Suk Ku đóng) điều tra một vụ án giết người do Lee Tang thực hiện. Bản năng thám tử khiến anh nghi ngờ Lee Tang là kẻ giết người. Trong khi đó, Song Chon (Lee Hee Jun vào vai) là một cựu thám tử đang một mình truy đuổi Lee Tang. Từ đây, mở ra những câu chuyện hấp dẫn, lôi cuốn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Woo-shik","avatar":""},{"name":"Son Suk-ku","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Kim Yo-han","avatar":""},{"name":"Nam Jin-bok","avatar":""},{"name":"Lee Joo-Young","avatar":""},{"name":"Han Sang-kyung","avatar":""},{"name":"Kim Keum-soon","avatar":""},{"name":"Jo Hyun-wu","avatar":""},{"name":"Jung Hoe-ryn","avatar":""},{"name":"Jeon Hyun-suk","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324243);
