INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-hang-sat-thu', 'Cửa Hàng Sát Thủ', 'A Shop for Killers', 'https://phimimg.com/upload/vod/20240119-1/15dd4a2e7f2426cb3694e94127ecd7d6.jpg', 'https://phimimg.com/upload/vod/20240119-1/a7db32edb09c39a49e68749557f26275.jpg', '<p>Khi Jung Ji-An (Kim Hye Jun) còn nhỏ, mẹ cô bị cha cô s.á.t h.ạ.i sau đó t.ự s.á.t. Chú của ấy là Jung Jin Man (Lee Dong Wook) đã nuôi dậy cô bé kể từ đó. &nbsp;Cô bé không hề biết rằng chú mình đã bí mật điều hành một trung tâm mua sắm bí ẩn. &nbsp;Jung Ji An sau khi đăng ký vào một trường đại học thì đã rời khỏi nhà của chú và bắt đầu sống một mình. &nbsp;Một ngày nọ, Jung Ji An nghe tin chú của cô đột ngột qua đời. Cô trở về nhà của chú mình và biết được bí mật mà chú cô ấy đã chôn giấu bấy lâu nay. &nbsp;Bị bao quanh bởi những mối nguy hiểm do công việc của chú, liệu cô ấy có lựa chọn tiếp tục làm hay không?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Dong-wook","avatar":""},{"name":"Kim Hye-jun","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Geum Hae-na","avatar":""},{"name":"Park Ji-bin","avatar":""},{"name":"Jo Han-sun","avatar":""},{"name":"Lee Tae-young","avatar":""},{"name":"Min Kim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324243);
