INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ted', 'ted', 'ted', 'https://phimimg.com/upload/vod/20240207-1/e9ac534a26412351627ecbac9ee91f74.jpg', 'https://phimimg.com/upload/vod/20240207-1/612019e6a3b814ce44130ba9fc5aba70.jpg', '<p>Năm 1993 và khoảnh khắc nổi tiếng của chú gấu Ted đã qua, khiến anh phải sống cùng với người bạn thân nhất của mình, John Bennett, 16 tuổi, trong một ngôi nhà thuộc tầng lớp lao động ở Boston cùng với bố mẹ và anh em họ của mình. Ted có thể không phải là ảnh hưởng tốt nhất đối với John, nhưng khi mọi việc trở nên nghiêm trọng, anh sẵn lòng làm mọi thứ để giúp đỡ bạn bè và gia đình của mình.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Seth MacFarlane","avatar":""},{"name":"Max Burkholder","avatar":""},{"name":"Alanna Ubach","avatar":""},{"name":"Scott Grimes","avatar":""},{"name":"Giorgia Whigham","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324243);
