INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tuyet', 'Bão Tuyết', 'Snowstorm', 'https://phimimg.com/upload/vod/20240206-1/f487a71105b0369900ee3938e7482867.jpg', 'https://phimimg.com/upload/vod/20240206-1/723b0a99390290643f685911e8e93a12.jpg', '<p>Phim được chuyển thể từ sự kiện có thật. Một vụ án giết người liên quan đến súng trên đường phố đã gây náo động, đội trưởng đội điều tra tội phạm Châu Vũ Đồng và người học việc Vương Phong đã nhiều lần truy tìm kẻ sát nhân chuyên nghiệp. Kẻ giết người không ngần ngại mạo hiểm, thiết kế một vụ nổ lớn để giết người, Vương Phong ra tay, không may anh ta chết trong vụ tai nạn, nhưng nghi phạm tàn bạo đã giết người và cướp xe, cố gắng băng qua rừng và cánh đồng tuyết để rời khỏi thị trấn. Châu vũ Đông không kịp đau buồn đã tức giận truy đuổi kẻ sát nhân, bị thương nặng nhưng vẫn kiên trì cầm cự và bắt đầu cuộc đấu tranh sinh tử với tên cướp tàn nhẫn Phạm Cự Hữu rong cái lạnh cực độ âm 30 độ...</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Zhi Liu","avatar":""},{"name":"Eva Cheng","avatar":""},{"name":"Hongbiao Bai","avatar":""},{"name":"Wang Xinman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324243);
