INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-tuyet', 'Bão Tuyết', 'Snowstorm', 'bão tuyết snowstorm louis fan siu-wong xing yu zhi liu eva cheng hongbiao bai wang xinman ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-tinh-phai-long-em', 'Vô Tình Phải Lòng Em', 'Have A Crush On You', 'https://phimimg.com/upload/vod/20240113-1/0d8cd7048d1da06eaa750a88a633c8b9.jpg', 'https://phimimg.com/upload/vod/20240113-1/fa367e10cd3ed2ca0ffa392feafa23a4.jpg', '<p>Bạn thân của Lâm Vũ Manh bị bạn trai lừa dối tình cảm nên cô đứng ra thay bạn mình đến dạy dỗ. Cuộc tranh cãi từ lời nói chuyển sang hành động, cô nàng với sức mạnh bắt nguồn từ gia đình võ thuật trong quá trình thể hiện chính nghĩa cũng vì thế vô tình gây hại cho chiếc xe sang. Do không có khả năng bồi thường nên cô nàng bị chủ nhân của chiếc xe yêu cầu cô ký hợp đồng để trả nợ! Sau khi kết hôn, cuộc sống của Lâm Vũ Manh đã thay đổi hoàn toàn, bị bắt phải học hỏi và bị bắt nạt bởi Quý thiếu gia. Tuy nhiên càng hiểu rõ về gia đình họ Quý, Lâm Vũ Manh càng bắt đầu cảm thông cho người chồng hợp đồng này, cùng phá hoại âm mưu của người mẹ kế muốn lấy cổ phần của mẹ ruột Quý thiếu gia. Đồng thời, cả hai cũng vô tình đánh mất trái tim của mình. Ban đầu chỉ là một cuộc hôn nhân hợp đồng</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Er Yi Xuan","avatar":""},{"name":"Jackson Jin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324243);
