INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trinh-sat-anh-hung', 'Trinh Sát Anh Hùng', 'Scout Hero', 'https://phimimg.com/upload/vod/20240123-1/7b7efcdcd9740001a0f236d137eb5f9b.jpg', 'https://phimimg.com/upload/vod/20240123-1/50b34bcd71e4c0148d443a86070fc492.jpg', '<p>Dưới góc nhìn của một nhà thám hiểm, vở kịch kể về câu chuyện anh hùng của Liang Chen, trưởng bộ phận trinh sát của một sư đoàn nào đó của Quân tình nguyện, người đã chỉ huy một đại đội trinh sát làm tiên phong trong cuộc kháng chiến chống Mỹ xâm lược và viện trợ Triều Tiên. , và nhiều lần dựa vào chiến lược, chiến thuật ưu việt để chống lại quân đội Mỹ.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Luo Jin","avatar":""},{"name":"Ma Sichun","avatar":""},{"name":"Huang Chengcheng","avatar":""},{"name":"Lu Xiaolin","avatar":""},{"name":"Han Pengyi","avatar":""},{"name":"Cao Lu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324243);
