INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sep-cua-toi-la-chu-lon-nho', 'Sếp Của Tôi Là Chú Lợn Nhỏ', 'My Piggy Boss', 'https://phimimg.com/upload/vod/20240205-1/d98abe4dac2d3e8494d301f90115d696.jpg', 'https://phimimg.com/upload/vod/20240205-1/f56cdcb92315859994f5ff8ff3b5dd55.jpg', '<p>Nhân viên cấp thấp, Dương Tiểu Châu, bất ngờ trở thành trợ lý cho tổng giám đốc Chu Khiếu Dương của công ty sản xuất đèn lồng, người phải đến làm việc mỗi sáng từ 6 giờ. Sau khi bị Chu Khiếu Dương sa thải vì làm việc chủ quan, Chu Khiếu Dương tình cờ nhặt được một con heo nhỏ dễ thương trong nhà vệ sinh. Khi thức dậy vào ngày thứ hai, con heo ban đầu nằm bên cạnh cô đã biến thành tổng giám đốc trần trụi! Hóa ra, mỗi khi mặt trời lặn, Chu Khiếu Dương biến thành một con heo nhỏ dễ thương, chỉ có nụ hôn của tình yêu thực sự mới có thể giải mã. Dương Tiểu Châu, người tốt bụng, chấp nhận nhiệm vụ từ mẹ của Chu Khiếu Dương và bắt đầu thử bắt đầu mối quan hệ tình cảm với Chu Khiếu Dương, mở đầu cho cuộc sống chung, cùng đối mặt với cạm bẫy cạnh tranh tàn ác trên thị trường kinh doanh, tình cảm giữa họ ngày càng phát triển lên.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lu Dong Xu","avatar":""},{"name":"Chen Liang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324243);
