INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sep-cua-toi-la-chu-lon-nho', 'Sếp Của Tôi Là Chú Lợn Nhỏ', 'My Piggy Boss', 'sếp của tôi là chú lợn nhỏ my piggy boss lu dong xu chen liang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-giang-dai-ha-3', 'Đại Giang Đại Hà 3', 'Like a Flowing River 3', 'https://phimimg.com/upload/vod/20240109-1/0a3f698dbcbfa28842ba3e983f53350c.jpg', 'https://phimimg.com/upload/vod/20240109-1/58f3497ee2daa613b07c14e6020d721d.jpg', '<p>Tháng 6 năm 1993, sự hợp tác quốc tế giữa Công ty Hóa chất Đông Hải và Công ty Lạc Đạt đang diễn ra hết sức sôi nổi, và người chủ chốt đưa ra quyết định hợp tác này là Tống Vận Huy, hiện đang đẩy mạnh quá trình cải tiến công nghệ tại Nhà máy Thuốc trừ sâu Phương Diện thuộc Đông Hải, cùng với đội ngũ công nhân. Sau những thăng trầm lớn từ Đông Hải đến Phương Diện, nơi mà Tống Vận Huy không hiểu biết về ngành công nghiệp thuốc trừ sâu, anh vẫn giữ vững tinh thần chiến đấu ban đầu, kiên trì dẫn dắt mọi người trong quá trình nghiên cứu và phát triển thuốc trừ sâu hiệu quả và an toàn, giúp những nhà máy thuốc trừ sâu nhỏ lẻ nơi mà đã bị cấm hoạt động trở lại. Lôi Đông Bảo, dẫn dắt nhà máy dây điện Đăng Phong, hợp nhất các nhà máy nhỏ, thành lập tập đoàn dây cáp Lôi Đình, thiết lập quy tắc, tham gia đấu thầu, phát triển thương mại quốc tế, thu hút đầu tư, trải qua những gian khổ và trái ngược của đời sống, anh vẫn đặt lợi ích của cộng đồng và dân làm chủ hàng đầu. Dương Tuân và Lương Tư Thân hợp tác xây dựng một trung tâm thương mại, phát triển mối quan hệ với Lương gia. Trong bóng tối của thị trường kinh doanh, anh ta lần lữa giữa việc làm người tốt hay làm người xấu, nhưng cuối cùng vẫn làm những điều mà lòng an tâm. Lương Tư Thân cố gắng cân bằng lợi ích giữa Lạc Đạt và Đông Hải trong dự án liên doanh, nhưng đồng nghiệp từ Lạc Đạt đã làm lớn chuyện trong một cuộc xung đột quốc tế, tận dụng cơ hội đưa ra điều kiện để Lương Tư Thân từ chức. Cuối cùng, Lương Tư Thân nhượng bộ, sử dụng sự rút lui của mình để Đông Hải có thể khôi phục sản xuất an toàn. Từ việc tránh né ban đầu đến dần dần mở lời lòng, Tống Vận Huy và Lương Tư Thân trao đổi tâm tư, cùng nhau đối mặt với những thách thức của tương lai.Con đường đã có những thăng trầm, hoàn cảnh có thay đổi nhưng điều không thay đổi chính là sự nỗ lực, chịu khó của những con người dũng cảm theo đuổi ước mơ của mình.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nick Wang","avatar":""},{"name":"Yang Shuo","avatar":""},{"name":"Đổng Tử Kiện","avatar":""},{"name":"Oraphan Saithong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
