INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-nghe-bay', 'Nhật Ký Nghề Bay', 'The Airport Diary', 'https://phimimg.com/upload/vod/20240123-1/adb47a38d4b748426f5dab6eedb609bb.jpg', 'https://phimimg.com/upload/vod/20240123-1/15dda900c73586d6badef0aa17e0ca0c.jpg', '<p>Kể từ khi chuyển đến Chek Lap Kok vào năm 1998, lưu lượng hành khách tại Sân bay Quốc tế Hồng Kông đã tăng gấp ba lần trong 25 năm. Và Yeung Sheung-wai, người khởi nghiệp là thư ký, đã được thăng chức lên Giám đốc nghĩa vụ IAC. Ông được giao nhiệm vụ giám sát hoạt động của sân bay. Sheung-wai cũng có một đội ngũ đối tác thân thiện, bao gồm trợ lý kiêm người ngưỡng mộ Fong Ho-yee, Lui Chi-shan – người phụ trách các dịch vụ hành khách tại sân bay – Chan Kit – người phụ trách an ninh hàng không – và Lee Sing-cheung, người chịu trách nhiệm về dịch vụ tạp dề. Họ hợp tác để hỗ trợ giải quyết tất cả các loại sự cố xảy ra tại sân bay. Sheung-wai vẫn giữ liên lạc với vợ cũ Cheung Yeuk-ling, Giám sát sân bay Metro Harbor Airlines. Thực ra, họ vẫn nghĩ đến nhau sau khi ly hôn. Mối quan hệ của bộ đôi được nhen nhóm khi cơ trưởng hãng hàng không Kwok Kai-kwong và tiếp viên hàng không Ko Nga-man xuất hiện.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 13, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ma Kwok-Ming","avatar":""},{"name":"Sisley Choi","avatar":""},{"name":"Samantha Ko","avatar":""},{"name":"Tony Hung","avatar":""},{"name":"Moses Chan","avatar":""},{"name":"Brian Chu","avatar":""},{"name":"Tiffany Lau","avatar":""},{"name":"Rosita Kwok","avatar":""},{"name":"Joey Thye","avatar":""},{"name":"Ricco Ng","avatar":""},{"name":"Tsui Wing","avatar":""},{"name":"Tiffany Fabienne Kwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
