INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lift-vu-trom-tren-khong', 'Lift: Vụ Trộm Trên Không', 'Lift', 'https://phimimg.com/upload/vod/20240113-1/de9d407c6b58e8747e7529ee4cdd6917.jpg', 'https://phimimg.com/upload/vod/20240113-1/5cfbf60ab7937b111f7eb66a9a90bca7.jpg', '<p>Tay trộm lão luyện cùng đội trộm chuyên nghiệp thực hiện phi vụ cuối: đánh cắp số vàng trị giá 500 triệu đô-la Mỹ trong két trên máy bay, ở độ cao hơn 12.000 mét trên không trung.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""},{"name":"Gugu Mbatha-Raw","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Úrsula Corberó","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Jacob Batalon","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Viveik Kalra","avatar":""},{"name":"Kim Yun-jee","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"David Proud","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324243);
