INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('echo', 'Echo', 'Echo', 'https://phimimg.com/upload/vod/20240111-1/ee1b8d6039ffeb7049d9010eb009feeb.jpg', 'https://phimimg.com/upload/vod/20240111-1/f002cff4832305451f3b27a86feebea6.jpg', '<p>Bị truy đuổi bởi đế chế tội phạm của Wilson Fisk, hành trình của Maya đưa cô về nhà và cô phải đối đầu với gia đình và di sản của chính mình.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alaqua Cox","avatar":""},{"name":"Chaske Spencer","avatar":""},{"name":"Tantoo Cardinal","avatar":""},{"name":"Devery Jacobs","avatar":""},{"name":"Cody Lightning","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Vincent D''Onofrio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324243);
