INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-nha-ho-ton', 'Anh em nhà họ Tôn', 'The Brothers Sun', 'https://phimimg.com/upload/vod/20240104-1/ebb7c287735c7799208e017a19981cf7.jpg', 'https://phimimg.com/upload/vod/20240104-1/808fc9a2be6f1094192cf6ad75e4b2d8.jpg', '<p>Khi kẻ thù bí ẩn nhắm vào gia đình anh, một thành viên trong hội Tam Hoàng Đài Bắc tới Los Angeles để bảo vệ người mẹ kiên cường và cậu em trai ngây thơ của mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michelle Yeoh","avatar":""},{"name":"Justin Chien","avatar":""},{"name":"Sam Li","avatar":""},{"name":"Highdee Kuan","avatar":""},{"name":"Jon Xue Zhang","avatar":""},{"name":"Jenny Yang","avatar":""},{"name":"Joon Lee","avatar":""},{"name":"Alice Hewkin","avatar":""},{"name":"Madison Hu","avatar":""},{"name":"Maite Garcia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
