INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-huynh-a-su-huynh', 'Sư Huynh À Sư Huynh', 'My Senior Brother is Too Steady', 'https://phimimg.com/upload/vod/20250117-1/d2d7ee02b72e59bea282b367e36b0094.jpg', 'https://phimimg.com/upload/vod/20250117-1/a9e32b44820101a9ba2c887344f7334c.jpg', '<p>Lý Trường Thọ - một thanh niên mắc bệnh hiểm nghèo vô tình được tái sinh vào thời thượng cổ trước đại chiến phong thần, trở thành một Luyện khí sĩ. Vì để tu được trường sinh bất lão và sống yên thân nơi hồng hoang tàn khốc này mà hắn hành sự khiêm tốn, tính trước làm sau, trước giờ không bao giờ bước vào nơi nguy hiểm, giấu át chủ bài, tu độn thuật, luyện đan độc. Cho đến một hôm, sư phụ của hắn nhận một sư muội về cho hắn, Lý Trường Thọ vốn muốn khiêm tốn tu hành bị cuốn vào hiểm nguy</p>', 'Tập 150', 150, 'hoathinh', 'ongoing', 64, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chaoran Yang","avatar":""},{"name":"Bingtian Wang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Shixiong A Shixiong","Shi Xiong A Shi Xiong","Big Brother","Wo Shixiong Shizai Tai Wenjianle","Wo Shi Xiong Shi Zai Tai Wen Jian Le","我师兄实在太稳健了","国漫 师兄啊师兄","国漫 师兄实在太稳健了","Мой старший брат чересчур сдержанный","Мой старший брат слишком стабилен","師兄啊師兄","我師兄實在太穩健了","My Senior Brother is Too","My Senior Brother is Too Steady","My Senior Brother is a Bit Too Cautious","Senior Brother","Sư Huynh À Sư Huynh","师兄啊师兄"]', 1784690324243);
