INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-ve-vox-machina-phan-2', 'Truyền Thuyết về Vox Machina (Phần 2)', 'The Legend Of Vox Machina (Season 2)', 'https://phimimg.com/upload/vod/20240308-1/458d3ac1ebc03d9ac8f074e0490bba41.jpg', 'https://phimimg.com/upload/vod/20240308-1/e8f99e2b727dce36b101c9308bc27bf8.jpg', '<p>Sau khi cứu vương quốc khỏi cái ác và sự hủy diệt dưới bàn tay của cặp đôi quyền lực đáng sợ nhất ở Exandria, Vox Machina một lần nữa phải đối mặt với việc cứu thế giới—lần này, khỏi một nhóm rồng độc ác được gọi là Hội nghị Chroma.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 47, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laura Bailey","avatar":""},{"name":"Taliesin Jaffe","avatar":""},{"name":"Ashley Johnson","avatar":""},{"name":"Liam O''Brien","avatar":""},{"name":"Marisha Ray","avatar":""},{"name":"Travis Willingham","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324243);
