INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-nghich', 'Tiên Nghịch', 'Renegade Immortal', 'https://phimimg.com/upload/vod/20240118-1/290650828b2ef3b9e4a63ce422a5919a.jpg', 'https://phimimg.com/upload/vod/20240118-1/9295479ab21037d136d970e219e5f07d.jpg', '<p>Vương Lâm một cái thiếu niên bình thường, tình cờ có được 1 cái danh nghạch trắc thí vào 1 môn phái tu tiên xuống dốc của Triệu quốc, vì thiếu linh căn, vì một hiểu nhầm tai hại, vì một khối thiết tinh và nhờ có được một &quot;thần bí hạt châu&quot;. Hắn đã bước lên con đường tu tiên và trên con đường tu tiên hắn sẽ đối mặt với chuyện gì ?

Tu tiên là nghịch thiên hay thuận thiên?

Tu tiên là vô tình hay hữu tình? Hãy dõi theo bước chân của Vương Lâm để biết hắn làm thế nào bằng vào sức lực của chính mình từng bước tiến lên phía trước dương danh &quot;Tu Chân Giới&quot;.

Chúc bạn có những giây phút vui vẻ khi đọc truyện Tiên Nghịch!</p>', 'Tập 149', 150, 'hoathinh', 'ongoing', 83, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324243);
