INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loki-phan-2', 'Loki (Phần 2)', 'Loki (Season 2)', 'https://phimimg.com/uploads/movies/20260713/loki-phan-2-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/loki-phan-2-poster.webp', '<p>Khi Steve Rogers, Tony Stark và Scott Lang quay trở về cột mốc 2012, ngay khi trận chiến ở New York kết thúc, để “mượn tạm” quyền trượng của Loki. Nhưng một tai nạn bất ngờ xảy đến, khiến Loki nhặt được khối lặp phương Tesseract và tiện thể tẩu thoát. Cuộc trốn thoát này đã dẫn đến dòng thời gian bị rối loạn. Cục TVA – tổ chức bảo vệ tính nguyên vẹn của dòng chảy thời gian, buộc phải can thiệp, đi gô cổ ông thần này về làm việc. Tại đây, Loki có hai lựa chọn, một là giúp TVA ổn định lại thời gian, không thì bị tiêu hủy. Dĩ nhiên Loki chọn lựa chọn thứ nhất. Nhưng đây là nước đi vô cùng mạo hiểm, vì ông thần này thường lọc lừa, “lươn lẹo”, chuyên đâm lén như bản tính tự nhiên của gã.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 31, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hiddleston","avatar":""},{"name":"Sophia Di Martino","avatar":""},{"name":"Wunmi Mosaku","avatar":""},{"name":"Eugene Cordero","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Gugu Mbatha-Raw","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Marvels - Loki","ლოკი","Локи","โลกิ","Локі","Marvel Studios'' Loki","Loki: Thần Lừa Lọc","Loki"]', 1784690324243);
