INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-toi-la-ho-ly-phan-2', 'Bạn Trai Tôi Là Hồ Ly (Phần 2)', 'Tale of the Nine Tailed 1938 (Season 2)', 'https://phimimg.com/uploads/movies/20260711/ban-trai-toi-la-ho-ly-phan-2-thumb.webp', 'https://phimimg.com/uploads/movies/20260711/ban-trai-toi-la-ho-ly-phan-2-poster.webp', '<p>Lấy bối cảnh vào năm 1930, kể về quá trình Lee Yeon (Lee Dong Wook) trở thành người thống trị ngọn núi và câu chuyện về Lee Rang (Kim Bum) không được tiết lộ trong phần trước. Kim Soyeon sẽ vào vai Ryu Hongju, người được đồn đại là trẻ mãi không già. Ryu Hongju là chủ của một nhà hàng sang trọng ở Gyeongseong (tên cũ của thành phố Seoul) và là người từng là người cai quản ngọn núi phía tây. Ryu Hongju và Lee Yeon là 2 trong 4 chúa sơn lâm trên Bán đảo Triều Tiên!!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 113, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Dong-wook","avatar":""},{"name":"Kim So-yeon","avatar":""},{"name":"Kim Bum","avatar":""},{"name":"Ryu Kyung-soo","avatar":""},{"name":"Kim Yong-ji","avatar":""},{"name":"Kim Jung-nan","avatar":""},{"name":"Hwang Hee","avatar":""},{"name":"An Kil-kang","avatar":""},{"name":"Han Kyun-yu","avatar":""},{"name":"Kim Ju-Young","avatar":""},{"name":"Kim Na-hyun","avatar":""},{"name":"Kang Na-eon","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Woo Hyun-jin","avatar":""},{"name":"Lim Ji-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-