INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-lam-texas-biet-dong-texas', 'Kiểm Lâm Texas (Biệt Động Texas)', 'One Ranger', 'https://phimimg.com/uploads/movies/20260710/kiem-lam-texas-biet-dong-texas-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/kiem-lam-texas-biet-dong-texas-poster.webp', '<p>Biệt Động Texas Được tình báo Anh tuyển dụng, Biệt đội Texas phải truy tìm và ngăn chặn một tên khủng bố nguy hiểm tấn công London.</p>', 'Full', 1, 'single', 'completed', 53, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Thomas Jane","avatar":""},{"name":"Dominique Tipper","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Dean S. Jagger","avatar":""},{"name":"Patrick Bergin","avatar":""},{"name":"Nick Moran","avatar":""},{"name":"Gregory Zaragoza","avatar":""},{"name":"James Oliver Wheatley","avatar":""},{"name":"Gary Cairns","avatar":""},{"name":"Jess Liaudin","avatar":""},{"name":"Spencer Collings","avatar":""},{"name":"Chris Shipton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Na Mira","Viens reindžeris","One Ranger"]', 1784690324243);
