INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-la-dai-luc-2-tuyet-the-duong-mon', 'Đấu La Đại Lục 2 (Tuyệt Thế Đường Môn)', 'Soul Land 2 (The Peerless Tang Clan)', 'https://phimimg.com/upload/vod/20240103-1/bbe888d771d0e6ff0f9935f8f6194c79.jpg', 'https://phimimg.com/upload/vod/20240103-1/af2ae10bcb72617994f00dce440205dc.jpg', '<p>Nơi đây không có ma pháp, không có hơn thua, không có võ thuật, nhưng lại có võ hồn. Đường Môn suy thoái sau khi đã thành lập được vạn năm ở Đấu La Đại Lục. Một lớp anh tài xuất hiện, liệu thế hệ Thất quái Sử Lai Khắc mới này có chấn hưng được Đường Môn, viết nên bài ca tuyệt thế Đường Môn hay không? Hồn thú triệu năm, Tử Linh Thánh Pháp Thần nắm giữ Nhật Nguyệt Trích Tinh, hệ thống Hồn Đạo Khí hoàn toàn mới khiến Đường Môn suy yếu. Tất cả thần khí đều sẽ lần lượt xuất hiện. Ám khí Đường Môn liệu có chấn hưng được uy phong, Đường Môn có thể tái hiện được huy hoàng hay không?</p>', 'Tập 161', 180, 'hoathinh', 'ongoing', 57, 2023, 'Vietsub', 'FDH', 'Trung Quốc', 0, '[{"name":"Wei Zhai","avatar":""},{"name":"Tao Dian","avatar":""},{"name":"Dawei Liang","avatar":""},{"name":"Yajing Tang","avatar":""},{"name":"Kaiyin Sun","avatar":""},{"name":"Xiyue Chen","avatar":""},{"name":"Ying Huang","avatar":""},{"name":"Chengyuan Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324243);
