INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-nguyen-do', 'Thương Nguyên Đồ', 'The Demon Hunter', 'https://phimimg.com/upload/vod/20250530-1/9c37d265d1409b9652a7a7afeb35fd6f.jpg', 'https://phimimg.com/upload/vod/20250530-1/435941e1bbd5462ab142b2d1d03b608e.jpg', '<p>Bối cảnh phim là Thương Nguyên Giới, nơi mà yêu tà hoành hành. Mạnh Xuyên từ nhỏ đã mất mẹ vì yêu quái, từ đó anh lập lời thề phải tiêu diệt yêu tà. Anh gia nhập Đạo viện Kính Hồ, bắt đầu con đường tu luyện của mình.

Trên con đường tu luyện, Mạnh Xuyên gặp gỡ nhiều người bạn mới, cũng như đối mặt với nhiều thử thách nguy hiểm. Anh phải chiến đấu với yêu quái, vượt qua những gian nan thử thách, và dần dần trưởng thành.

Bộ phim có cốt truyện hấp dẫn, đồ họa đẹp mắt và các nhân vật được xây dựng tốt.</p>', 'Tập 85', 99, 'hoathinh', 'ongoing', 88, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Chính Dương","avatar":""},{"name":"Hồ Chính Kiện","avatar":""},{"name":"Lâm Cường","avatar":""},{"name":"Bảo Mộc Trung Dương","avatar":""},{"name":"Triệu Trấn","avatar":""},{"name":"Lưu Thiên Hàn","avatar":""},{"name":"Chu Đông","avatar":""},{"name":"Đoàn Nghi Hiên","avatar":""},{"name":"Vương Tiểu Khiêm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Cang Yuan Tu","Azure Legacy","The Demon Hunter","El Cazador de Demonios (Cang Yuan Tu)","滄元圖","Thương Nguyên Đồ","沧元图"]', 1784690324243);
