INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chua-te-3d', 'Đại Chúa Tể 3D', 'The Great Ruler', 'https://phimimg.com/upload/vod/20260415-1/708b632451a627340ce179f85e88fd3e.jpg', 'https://phimimg.com/upload/vod/20260415-1/b5d7394aa49cde793f86f5d9163ced85.jpg', '<p>Đại Chúa Tể 3D mở ra một thế giới huyền ảo nơi vô số chủng tộc cùng tồn tại giữa những vùng trời rộng lớn giao thoa, tạo nên một bức tranh vừa tráng lệ vừa hiểm nguy. Câu chuyện xoay quanh Mục Trần, chàng thiếu niên đến từ hạ giới mang trong mình khát vọng vượt qua số phận để bước vào hàng ngũ kiếm hiệp tối thượng. Trên con đường tu luyện, cậu phải đối mặt với những thử thách khắc nghiệt, từ linh thú cổ đại, thế lực tà ác cho đến những âm mưu giành đoạt quyền năng giữa các thế giới. Mỗi trận chiến, mỗi bước đi đều khiến Mục Trần trưởng thành hơn, thấu hiểu ý nghĩa của sức mạnh và lòng kiên định. Giữa khung cảnh kỳ vĩ được tái hiện sống động qua kỹ xảo hoạt hình 3D, người xem như lạc vào cõi tiên giới rực rỡ, nơi lòng can đảm và niềm tin trở thành ngọn lửa dẫn lối cho những linh hồn không chịu khuất phục.</p>', 'Tập 81', 104, 'hoathinh', 'completed', 40, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"孙郎朗","avatar":""},{"name":"Li Shimeng","avatar":""},{"name":"江月","avatar":""},{"name":"He Wenxiao","avatar":""},{"name":"Zhang Fuzheng","avatar":""},{"name":"Zhenyan Liu","avatar":""},{"name":"Liu Cong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["大主宰 年番","大主宰 3D","大主宰动画","大主宰3D","Da Zhuzai","大主宰年番2","The Great Ruler (3D)","大主宰","Da Zhu Zai Nian Fan","The Grand Lord","Year of the Great Master","The Great Ruler","Đại Chúa Tể 3D"]', 1784690324243);
