INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-chua-te-3d', 'Đại Chúa Tể 3D', 'The Great Ruler', 'đại chúa tể 3d the great ruler 孙郎朗 li shimeng 江月 he wenxiao zhang fuzheng zhenyan liu liu cong 大主宰 年番 大主宰 3d 大主宰动画 大主宰3d da zhuzai 大主宰年番2 the great ruler (3d) 大主宰 da zhu zai nian fan the grand lord year of the great master the great ruler đại chúa tể 3d', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-co-ban-gai-yeu-ban-rat-rat-rat-rat-rat-nhieu-phan-1', '100 Cô Bạn Gái Yêu Bạn Rất Rất Rất Rất Rất Nhiều (Phần 1)', 'The 100 Girlfriends Who Really, Really, Really, Really, REALLY Love You (Season 1)', 'https://phimimg.com/upload/vod/20250617-1/cefb0c2671bb4851b3608c1016c3f8ac.jpg', 'https://phimimg.com/upload/vod/20250617-1/0f9d3a678583ba035f15fd726ebc34ab.jpg', '<p>Rentaro Aijo đã trải qua 100 lần thất tình hồi còn học sơ trung. Khi vừa lên cao trung, cậu đã đến một đền thờ và ước rằng &quot;tôi muốn có người yêu&quot;. Thần tình yêu xuất hiện và phán rằng &quot;tại cao trung, con sẽ gặp được 100 người định mệnh của mình&quot;. Tuy nhiên, theo vị thần, những người gặp một nửa định mệnh của mình phải yêu nhau và cảm thấy hạnh phúc, bằng không họ sẽ chết. Gặp gỡ liên tiếp những con người định mệnh của mình, Rentaro sẽ làm thế nào đây? Điều gì sẽ đến với 100 cô bạn gái của cậu?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 50, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Wataru Katoh","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Maria Naganawa","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Ayaka Asai","avatar":""},{"name":"Shigeru Chiba","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mis 100 novias que me quieren mucho mucho","Las 100 novias que de verdad, te Aman","超超超超超喜欢你的100个女朋友","Mis 100 novias que me quieren mogollón mogollón","100 Pacar yang Sungguh Sangat Amat Benar-benar Mencintaimu","100 החברות שבאמת, באמת, באמת, באמת, באמת, באמת אוהבות אותך","Kimi no Koto ga Dai Dai Dai Dai Daisuki na 100 Nin no Kanojo","Hyakkano","Kimi no Koto ga Daidaidaidaidaisuki na 100-nin no Kanojo","너를 너무너무너무너무 좋아하는 100명의 그녀 2기","Сто девушек, которые очень-очень-очень-очень-очень сильно тебя любят","The 100 Girlfriends Who Really Really Really Really REALLY Love You","100 cô bạn gái yêu bạn rất, rất, rất, rất, rất nhiều","君のことが大大大大大好きな100人の彼女"]', 1784690324243);
