INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ly-do-toi-quay-tro-lai-tuoi-17', 'Lý Do Tôi Quay Trở Lại Tuổi 17', 'Back To Seventeen', 'https://phimimg.com/upload/vod/20260705-1/f4497528c7ee14430e32399dd7a407f2.jpg', 'https://phimimg.com/upload/vod/20260705-1/021d3776402072515b57826ac8185094.jpg', '<p>Chung Tiếu Tiếu, cô gái 27 tuổi, vô tình quay trở lại tuổi 17 sau khi mở một chiếc máy quay DV cũ tại buổi họp lớp. Để trở về hiện tại, cô phải ở gần mối tình đầu thời trung học là Hứa Dạng, bởi thời gian chỉ trôi bình thường khi anh ở bên cạnh. Trong quá trình sống lại quãng đời học sinh, cả hai dần chữa lành những tiếc nuối của tuổi trẻ và tìm thấy tình yêu còn dang dở.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 63, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Miểu Di","avatar":""},{"name":"Phương Hiểu Đông","avatar":""},{"name":"Hoàng Hoài Đình","avatar":""},{"name":"Lưu Mộng Nhuế","avatar":""},{"name":"Hạ Lỗi","avatar":""},{"name":"Triệu Doãn Trạch","avatar":""},{"name":"Khang Khởi Hiên","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我回到17岁的理由","我回到十七岁的理由"]', 1784690324243);
