INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ly-do-toi-quay-tro-lai-tuoi-17', 'Lý Do Tôi Quay Trở Lại Tuổi 17', 'Back To Seventeen', 'lý do tôi quay trở lại tuổi 17 back to seventeen trương miểu di phương hiểu đông hoàng hoài đình lưu mộng nhuế hạ lỗi triệu doãn trạch khang khởi hiên 我回到17岁的理由 我回到十七岁的理由', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-qua-bien-gian-du', 'Băng Qua Biển Giận Dữ', 'Across The Furious Sea', 'https://phimimg.com/upload/vod/20260705-1/9d72ac5260a6332ebcd67bd60d352b6f.jpg', 'https://phimimg.com/upload/vod/20260705-1/f7f971c3a7eaaae03cd1994dbca3e994.jpg', '<p>Lão Kim, một ngư dân vất vả kiếm sống để nuôi con gái Kim Lệ Na du học tại Nhật Bản, bàng hoàng khi nhận tin con bị sát hại với 17 nhát dao. Nghi phạm chính là bạn trai của cô, Lý Miêu Miêu, đã bỏ trốn về Trung Quốc dưới sự che chở của mẹ mình. Quyết tâm báo thù, Lão Kim lao vào cuộc truy đuổi đầy phẫn nộ, nhưng càng tiến gần sự thật, ông càng phát hiện những bí mật đau lòng về cả gia đình nạn nhân lẫn hung thủ.</p>', 'Full', 1, 'single', 'completed', 56, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Bột","avatar":""},{"name":"Châu Tấn","avatar":""},{"name":"Tổ Phong","avatar":""},{"name":"Trương Hựu Hạo","avatar":""},{"name":"Châu Y Nhiên","avatar":""},{"name":"Diêm Ny","avatar":""},{"name":"Tôn An Khả","avatar":""},{"name":"Nhan Bắc","avatar":""},{"name":"Vương Tấn","avatar":""},{"name":"A Bộ Lực","avatar":""},{"name":"Thi Kinh Minh","avatar":""},{"name":"Tizzy T","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Across the Furious Sea","涉过愤怒的海"]', 1784690324243);
