INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ghet-giang-sinh-odio-il-natale-phan-2', 'Tôi Ghét Giáng Sinh (Odio il Natale) (Phần 2)', 'I Hate Christmas (Season 2)', 'https://phimimg.com/upload/vod/20260704-1/31f57a441ed1fec09c1da221c09df3d0.jpg', 'https://phimimg.com/upload/vod/20260704-1/fcc8e26dbbeb234c5c4700a77d746d65.jpg', '<p>Sau khi nói dối gia đình về việc có bạn trai, một y tá độc thân phải tìm cho ra nửa kia bằng mọi giá trước Giáng sinh – tức là còn 24 ngày nữa.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 47, 2023, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Pilar Fogliati","avatar":""},{"name":"Beatrice Arnera","avatar":""},{"name":"Fiorenza Pieri","avatar":""},{"name":"Massimo Rigo","avatar":""},{"name":"Sabrina Paravicini","avatar":""},{"name":"Simonetta Solder","avatar":""},{"name":"Glen Blackhall","avatar":""},{"name":"Pierpaolo Spollon","avatar":""},{"name":"Chiara Bono","avatar":""},{"name":"Federico Calistri","avatar":""},{"name":"Giulia Gonella","avatar":""},{"name":"Nicolas Maupas","avatar":""},{"name":"Matteo Martari","avatar":""},{"name":"Tommaso Basili","avatar":""},{"name":"Jenny De Nucci","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我讨厌圣诞节","I Hate Christmas","Odio il Natale"]', 1784690324243);
