INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-silo-phan-1', 'Hầm SILO (Phần 1)', 'Silo (Season 1)', 'https://phimimg.com/upload/vod/20260704-1/b3ee63c76418eb123e49e040c2ef70dc.jpg', 'https://phimimg.com/upload/vod/20260704-1/52845d44789dddbdfbd6bb5142668c6d.jpg', '<p>Trong thế giới hoang tàn và nhiễm độc ở tương lai, hàng nghìn người sống trong một silo khổng lồ sâu dưới lòng đất. Sau khi một cảnh sát trưởng phá vỡ một quy tắc chủ chốt và dân thường thiệt mạng một cách bí ẩn, kỹ sư Juliette bắt đầu phát hiện ra những bí mật gây sốc và sự thật về silo.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 40, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rebecca Ferguson","avatar":""},{"name":"Common","avatar":""},{"name":"Chinaza Uche","avatar":""},{"name":"Ashley Zukerman","avatar":""},{"name":"Shane McRae","avatar":""},{"name":"Remmie Milner","avatar":""},{"name":"Alexandria Riley","avatar":""},{"name":"Reed Birney","avatar":""},{"name":"Laura Innes","avatar":""},{"name":"Jessica Brown Findlay","avatar":""},{"name":"Billy Postlethwaite","avatar":""},{"name":"Morven Christie","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Tim Robbins","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["羊毛战记","სილოსი","사일로","지하창고 사일로의 비밀","Бункер","الصومعة","Wool","Silo"]', 1784690324243);
