INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zoey-khac', 'Zoey Khác', 'The Other Zoey', 'https://phimimg.com/upload/vod/20260703-1/3574a3de6c53f4144630f4e3347d0dae.jpg', 'https://phimimg.com/upload/vod/20260703-1/bd023455f5743bce0e3280e5fd74599c.jpg', '<p>Zoey Miller, một sinh viên chuyên ngành máy tính siêu thông minh, không quan tâm đến tình yêu lãng mạn, cuộc sống của cô bị đảo lộn khi Zack, ngôi sao bóng đá của trường, bị mất trí nhớ và nhầm Zoey với bạn gái của anh.</p>', 'Full', 1, 'single', 'completed', 36, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Josephine Langford","avatar":""},{"name":"Drew Starkey","avatar":""},{"name":"Archie Renaux","avatar":""},{"name":"Mallori Johnson","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"Patrick Fabian","avatar":""},{"name":"Heather Graham","avatar":""},{"name":"Olive Abercrombie","avatar":""},{"name":"Amalia Yoo","avatar":""},{"name":"Maggie Thurmon","avatar":""},{"name":"Jorge López","avatar":""},{"name":"Gabriella Saraivah","avatar":""},{"name":"Christie Lynn Smith","avatar":""},{"name":"Pierce Lackey","avatar":""},{"name":"John Crow","avatar":""},{"name":"Salem Murphy","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["زویی دیگر","The Other Zoey"]', 1784690324243);
