INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('zoey-khac', 'Zoey Khác', 'The Other Zoey', 'zoey khác the other zoey josephine langford drew starkey archie renaux mallori johnson andie macdowell patrick fabian heather graham olive abercrombie amalia yoo maggie thurmon jorge lópez gabriella saraivah christie lynn smith pierce lackey john crow salem murphy زویی دیگر the other zoey', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-thien-ta-than', 'Nghịch Thiên Tà Thần', 'Against The Gods', 'https://phimimg.com/upload/vod/20260420-1/a00de874909fb1bfb7f7749f926081a3.jpg', 'https://phimimg.com/upload/vod/20260420-1/0a4c1589001cf10c879d5b8c4f7e75d6.jpg', '<p>Trên đại lục Thương Vân, Đại Thổ Y Tông đã bị sát hại tàn nhẫn vì giữ một trong bảy viên Thần Dược Thiên Không. Việc này đã khiến cho cả thiên hạ đều thèm muốn viên Thần Dược này, dẫn đến cái chết đau đớn của ông. Người trò truyện của ông, Vân Triệt, đã mang viên Thần Dược này để báo thù cho thầy, và trong quá trình này đã gieo ra biết bao sóng gió và chết chóc. Cuối cùng, anh đã bị các cao thủ võ lâm đẩy đến bước đường cùng tại Thiên Huyền Dã. Dẫu vậy, Vân Triệt đã không chịu khuất phục, anh nuốt viên Thần Dược đó và nhảy xuống vực tự tử. Tuy nhiên, ý thức của anh không biết bởi một lực lượng bí ẩn đã hướng dẫn, anh đã tự mình vượt thời gian và tỉnh dậy trong thế giới Thiên Huyền Lục Lâm, trên cơ thể của một thiếu niên tên là Tiêu Triệt</p>', 'Tập 44', 80, 'hoathinh', 'ongoing', 26, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guo Hongbo","avatar":""},{"name":"Shen Dawei","avatar":""},{"name":"Xie Tiantian","avatar":""},{"name":"Feng Junhua","avatar":""},{"name":"Yixiao Wen","avatar":""},{"name":"Feng Junhua","avatar":""},{"name":"Wang Rui Qi","avatar":""},{"name":"Xiao zheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e07