INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-bi-mat-nha-trang', 'Đội Đặc Nhiệm Bí Mật Nhà Trắng', 'White House Plumbers', 'https://phimimg.com/upload/vod/20260630-1/794a7b415600628a0b4a8e7bf0881bf3.jpg', 'https://phimimg.com/upload/vod/20260630-1/733a04ba3828abf2d0b743ad9844d5cc.jpg', '<p>Câu chuyện có thật về việc những kẻ phá hoại chính trị và cũng là những bộ óc đạo diễn vụ Watergate của chính Tổng thống Nixon, đã vô tình lật đổ chính chiếc ghế Tổng thống mà họ đang dùng mọi cách cực đoan nhất để ra sức bảo vệ.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 36, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Woody Harrelson","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Liam James","avatar":""},{"name":"Tony Plana","avatar":""},{"name":"Yul Vazquez","avatar":""},{"name":"Zoe Levin","avatar":""},{"name":"Tre Ryder","avatar":""},{"name":"Nelson Ascencio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["白宫水管工","Los Plomeros de la Casa Blanca","The White House Plumbers","White House Plumbers"]', 1784690324243);
