INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-vang-son-phan-2', 'Thời Đại Vàng Son (Phần 2)', 'The Gilded Age (Season 2)', 'https://phimimg.com/upload/vod/20260630-1/0fd57dee5f12b4142ee4a770d5487eef.jpg', 'https://phimimg.com/upload/vod/20260630-1/0f5ecf59c24f33605127bd69396d906f.jpg', '<p>Vào năm 1882, khi Thời kỳ Hoàng kim của nước Mỹ đang ở giai đoạn đỉnh cao rực rỡ, Marian Brook — cô con gái mồ côi trẻ tuổi của một vị tướng miền Nam — đã chuyển đến New York để sống cùng các dì của mình, những người luôn tuân thủ các quy tắc truyền thống một cách cứng nhắc. Với sự giúp đỡ của Peggy Scott, một phụ nữ Mỹ gốc Phi đang giả làm hầu gái của cô, Marian bị cuốn vào cuộc sống hào nhoáng của những người hàng xóm giàu có, đồng thời phải đấu tranh để lựa chọn giữa việc tuân theo các chuẩn mực xã hội cũ kỹ hay tự tìm kiếm lối đi riêng cho chính mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 27, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Carrie Coon","avatar":""},{"name":"Morgan Spector","avatar":""},{"name":"Louisa Jacobson","avatar":""},{"name":"Denée Benton","avatar":""},{"name":"Taissa Farmiga","avatar":""},{"name":"Harry Richardson","avatar":""},{"name":"Blake Ritson","avatar":""},{"name":"Simon Jones","avatar":""},{"name":"Jack Gilpin","avatar":""},{"name":"Ben Ahlers","avatar":""},{"name":"Kelley Curran","avatar":""},{"name":"Celia Keenan-Bolger","avatar":""},{"name":"Ben Lamb","avatar":""},{"name":"Debra Monk","avatar":""},{"name":"Kristine Nielsen","avatar":""},{"name":"Kelli O''Hara","avatar":""},{"name":"Patrick Page","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Gilded Age : La loi du vieux New York","عصر طلایی","دوره طلایی","더 길디드 에이지","The Gilded Age"]', 1784690324243);
