INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-hau-lap-lanh', 'Dưa Hấu Lấp Lánh', 'Twinkling Watermelon', 'https://phimimg.com/upload/vod/20240324-1/73ae08c643e99c50ed3ac4f10bf68399.jpg', 'https://phimimg.com/upload/vod/20240324-1/c743899ca883ce2f38f2297e6d005720.jpg', '<p>Một học sinh CODA (con của người lớn khiếm thính) sinh ra với năng khiếu về âm nhạc đã hạ cánh xuống một nơi xa lạ sau một thời gian du hành qua một cửa hàng âm nhạc đáng ngờ. Tại đây, anh thành lập ban nhạc Watermelon Sugar cùng với những thanh niên bí ẩn khác.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 35, 2023, 'Vietsub + Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Ryeoun","avatar":""},{"name":"Choi Hyun-wook","avatar":""},{"name":"Seol In-a","avatar":""},{"name":"Shin Eun-soo","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Seo Young-hee","avatar":""},{"name":"Jung Sang-hoon","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Goh Doo-shim","avatar":""},{"name":"Kim Joo-ryoung","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324243);
