INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sau-tat-ca', 'Sau Tất Cả', 'After Everything', 'sau tất cả after everything hero fiennes tiffin josephine langford mimi keene stephen moyer louise lombard arielle kebbel carter jenkins kiana madeira rob estes frances turner benjamin mascolo rosa escoda ella martine jessica webber cora kirk harrison osterfield niyi after 5 after everything: the final chapter after 5. na zawsze after: her şey 애프터 5 אחרי שהכל נגמר 애프터 에브리씽 禁忌世代 sau tất cả after everything', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nhan-phan-1', 'Tiêu Nhân (Phần 1)', 'Blades Of The Guardians (Season 1)', 'https://phimimg.com/upload/vod/20260613-1/2e8d2bf05427f588abef24964995ab03.jpg', 'https://phimimg.com/upload/vod/20260613-1/dbd9b46b5fa30b68f2de2e34fffee5f4.jpg', '<p>Đại Nghiệp năm thứ 3 (năm 607 sau Công Nguyên), vương triều nhà Tùy nằm dưới ách thống trị tàn bạo của Tùy Dạng Đế Dương Quảng khiến dân chúng lầm than, nguy cơ tứ phía. Vị tiêu khách (thợ săn tiền thưởng) “Đao Mã” phiêu bạt nơi sa mạc Tây Vực nhận được yêu cầu hộ tống một người tới “Trường An”, vương đô nhà Tùy. Người được hộ tống là Trí Thế Lang, thủ lĩnh của bang hội bí ẩn “Hoa Nhan Đoàn” có mục tiêu lật đổ ách thống trị nhà Tùy. Nhằm tiêu diệt Trí Thế Lang, triều đình Trung Nguyên đã thỏa thuận cùng gia tộc Ngũ Hồ ở phương Bắc. Song, việc ám sát lại không phải là mục đích thật sự của triều đình Trung Nguyên. Hành trình rung chuyển vận mệnh toàn thiên hạ bắt đầu hé mở từ đây…</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 20, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Beichen","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"Zhao Qianjing","avatar":""},{"name":"Wang Xiaobing","avatar":""},{"name":"Yan Ning","avatar":""},{"name":"Huang Xiangyu","avatar":""},{"name":"Li Chanfei","avatar":""},{"name":"Sanshi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Biaoren","Biao Ren","镖人第二季","Blades of the Guardians","鏢人","镖人"]', 1784690324243);
