INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-phai-tai-nan', 'Không Phải Tai Nạn', 'No Accident', 'https://phimimg.com/upload/vod/20260512-1/cc5fd59f8a08e00a48371cd4582bbdb9.jpg', 'https://phimimg.com/upload/vod/20260512-1/d5bddb1e364c1162032a72eb9b10cbd9.jpg', '<p>Sau cuộc biểu tình Unite the Right gây chết người ở Charlottesville, Virginia, một vụ kiện dân sự đã được đệ trình chống lại các nhà lãnh đạo và tổ chức dân tộc chủ nghĩa da trắng, thay mặt cho các nguyên đơn bị thương trong khi phản đối một cách ôn hòa. Bộ phim tài liệu này ghi lại phiên tòa dân quyền mang tính bước ngoặt này, vạch trần một mạng lưới rộng lớn những kẻ chủ mưu và nêu chi tiết những thách thức trong việc buộc các nhà lãnh đạo và tổ chức đó phải chịu trách nhiệm về hành động của họ.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Richard Spencer","avatar":""},{"name":"Christopher Cantwell","avatar":""},{"name":"Donald Trump","avatar":""},{"name":"Ellen DeGeneres","avatar":""},{"name":"Roberta Kaplan","avatar":""},{"name":"Tucker Carlson","avatar":""},{"name":"Joe Biden","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["No Accident"]', 1784690324243);
