INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-vay', 'Phố Vẫy', 'The Stroll', 'https://phimimg.com/upload/vod/20260512-1/ea525e1807760737f3b0450e44b5ff86.jpg', 'https://phimimg.com/upload/vod/20260512-1/dcf5612c42f6a7102b8046b659b93fc7.jpg', '<p>Lịch sử của Khu Meatpacking ở New York, được kể lại từ góc nhìn của những người chuyển giới hành nghề mại dâm từng sống và làm việc tại đây. Nhà làm phim Kristen Lovell, người đã đi bộ dọc con đường The Stroll trong một thập kỷ, đã đoàn tụ cộng đồng của mình để kể lại những năm tháng bạo lực, cảnh sát, tình trạng vô gia cư và sự đô thị hóa mà họ đã vượt qua để xây dựng một phong trào đấu tranh cho quyền của người chuyển giới.</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ceyenne Doroshow","avatar":""},{"name":"Egyptt LaBeija","avatar":""},{"name":"Izzi “Cashmere” Starz","avatar":""},{"name":"Tabytha Gonzalez","avatar":""},{"name":"Stefanie Rivera","avatar":""},{"name":"Elizabeth Rivera","avatar":""},{"name":"Carey Smith","avatar":""},{"name":"Sylvia Rivera","avatar":""},{"name":"Marsha P. Johnson","avatar":""},{"name":"RuPaul","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Stroll"]', 1784690324243);
