INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-va-ngay', 'Đêm Và Ngày', 'Night And Day', 'https://phimimg.com/upload/vod/20260513-1/bdc8612b9bab27eec46a5ce5b8edccfc.jpg', 'https://phimimg.com/upload/vod/20260513-1/216fb5ef9cadd54869cadf6cdf4d8f7b.jpg', '<p>Young-taek bị dị ứng với ánh sáng mặt trời, còn bạn trai Eui-jun thì chán ngán việc chỉ biết hẹn hò trong bóng tối. Vào ngày sinh nhật của mình, Eui-jun mong muốn được tận hưởng một buổi hẹn hò ban ngày, điều này đã giúp Young-taek có can đảm lên kế hoạch cho một buổi hẹn ăn trưa, nhưng liệu mọi chuyện có suôn sẻ?</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Dong-yeong","avatar":""},{"name":"Do Geon-wu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["밤낮없이"]', 1784690324243);
