INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('david-holmes-chang-trai-song-sot', 'David Holmes: Chàng Trai Sống Sót', 'David Holmes: The Boy Who Lived', 'https://phimimg.com/upload/vod/20260512-1/a0c46858b41ba6c970ebdb3c0d74e5a0.jpg', 'https://phimimg.com/upload/vod/20260512-1/abdba34c8d5e4b646f73e88924fb2e5e.jpg', '<p>Là diễn viên đóng thế cho Daniel Radcliffe trong loạt phim Harry Potter, David Holmes đã được hàng triệu khán giả trên toàn thế giới đón nhận. Đáng buồn thay, một tai nạn trên phim trường đã chấm dứt điều mà David gọi là công việc tuyệt vời nhất thế giới, khiến anh bị liệt. Giống như nhân vật trên màn ảnh mà anh góp phần thổi hồn, David quyết tâm tiếp tục tìm kiếm những cuộc phiêu lưu và sống trọn vẹn cuộc sống bất chấp những trở ngại ngày càng gia tăng.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Sue Holmes","avatar":""},{"name":"Andy Holmes","avatar":""},{"name":"Tommy Wells","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["David Holmes: The Boy Who Lived"]', 1784690324243);
