INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-em-di', 'Để Em Đi', 'Let You Go', 'https://phimimg.com/upload/vod/20260513-1/002e86fc1a454691412f4016d9744484.jpg', 'https://phimimg.com/upload/vod/20260513-1/03599a2339adb1729fa33693a54b3da6.jpg', '<p>Hyemi liên tục gặp ác mộng kể từ khi bạn gái cô qua đời trong một vụ tai nạn xe hơi. Căn phòng họ ở chung vẫn không hề thay đổi, chú rùa cưng của họ dành cả ngày trong bể cá, và Hyemi chìm đắm trong quá khứ. Tuy nhiên, cô không thể thoát khỏi cảm giác bóng ma của bạn gái mình vẫn còn lởn vởn...</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["천장지구"]', 1784690324243);
