INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-hoc', 'Bài Học', 'The Lesson', 'https://phimimg.com/upload/vod/20260513-1/b5a0d0ea9a67c2a26fca0d10d2021f20.jpg', 'https://phimimg.com/upload/vod/20260513-1/5c7e5f1b514c5730021128affc117d6c.jpg', '<p>Liam, một nhà văn trẻ đầy tham vọng và hoài bão, háo hức nhận lời làm gia sư tại điền trang của thần tượng mình, nhà văn nổi tiếng J.M. Sinclair. Nhưng chẳng bao lâu sau, Liam nhận ra mình đang bị mắc kẹt trong một mạng lưới bí mật gia đình, sự oán giận và trả thù. Sinclair, vợ anh, Hélène, và con trai Bertie đều đang canh giữ một quá khứ đen tối, một quá khứ đe dọa tương lai của Liam cũng như của chính họ.</p>', 'Full', 1, 'single', 'completed', 28, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Richard E. Grant","avatar":""},{"name":"Julie Delpy","avatar":""},{"name":"Daryl McCormack","avatar":""},{"name":"Stephen McMillan","avatar":""},{"name":"Crispin Letts","avatar":""},{"name":"Tomas Spencer","avatar":""},{"name":"Joseph Meurer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Tutor","The Lesson"]', 1784690324243);
