INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-mua-yeu', 'Những Mùa Yêu', 'Seasons', 'https://phimimg.com/upload/vod/20260513-1/4fdd040e27a3df8961a4da953579b57e.jpg', 'https://phimimg.com/upload/vod/20260513-1/b9782d738fec6a279670f4dc1b9685f3.jpg', '<p>Sau một loạt mối quan hệ thất bại, đôi bạn thân nọ quyết định chấp nhận rủi ro và tìm kiếm tình yêu một lần nữa. Nhưng có thể đó sẽ là tình yêu giữa cả hai.</p>', 'Full', 1, 'single', 'completed', 32, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Philippines', 0, '[{"name":"Lovi Poe","avatar":""},{"name":"Carlo Aquino","avatar":""},{"name":"Sarah Edwards","avatar":""},{"name":"Jolo Estrada","avatar":""},{"name":"Casie Banks","avatar":""},{"name":"Ivan Carapiet","avatar":""},{"name":"Sheenly Gener","avatar":""},{"name":"Christian Ty","avatar":""},{"name":"Ancher Alaba Cua","avatar":""},{"name":"Jay-L Dizon","avatar":""},{"name":"Ron Angeles","avatar":""},{"name":"Toni Carag","avatar":""},{"name":"Keith Alawag","avatar":""},{"name":"Mark Gil Adorna","avatar":""},{"name":"Aldo Corpuz","avatar":""},{"name":"Andrea Dawn Peralta","avatar":""},{"name":"Rob Imperial","avatar":""},{"name":"Matthew An","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Seasons"]', 1784690324243);
