INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-mau-2023', 'Khát Máu', 'Blood', 'https://phimimg.com/upload/vod/20260509-1/c08b6e094b3e93e02910b11a366c42a5.jpg', 'https://phimimg.com/upload/vod/20260509-1/e0b29f706fab30e1c90d72eec429ddbe.jpg', '<p>Jess, một người mẹ và y tá mới ly thân, chuyển đến trang trại cũ của gia đình cô cùng với Tyler, cô con gái tuổi teen và Owen, cậu con trai tám tuổi của cô. Một đêm nọ, con chó của gia đình cảm nhận được thứ gì đó trong rừng và chạy đi tìm nó. Anh ta quay lại vài ngày sau đó và tấn công Owen, cắn anh ta một cách dã man trước khi Jess có thể can thiệp. Owen được đưa đến bệnh viện. Tình trạng của anh ấy trở nên tồi tệ hơn, và không ai có thể hiểu tại sao... cho đến khi Jess phát hiện ra một phương pháp chữa trị đáng lo ngại...</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michelle Monaghan","avatar":""},{"name":"Skeet Ulrich","avatar":""},{"name":"Erik Athavale","avatar":""},{"name":"June B. Wilde","avatar":""},{"name":"Finlay Wojtak-Hissong","avatar":""},{"name":"Onalee Ames","avatar":""},{"name":"Danika Frederick","avatar":""},{"name":"Skylar Morgan Jones","avatar":""},{"name":"Jerni Stewart","avatar":""},{"name":"Jennifer Rose Garcia","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Sang","Blood"]', 1784690324244);
