INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-mu-quang-brazil-phan-3', 'Yêu là mù quáng: Brazil (Phần 3)', 'Love Is Blind: Brazil (Season 3)', 'https://phimimg.com/upload/vod/20260508-1/b2c48f4f6b13c4b384912a3844cdbe38.jpg', 'https://phimimg.com/upload/vod/20260508-1/7cf12fbf91487dcb713091a4aeb94c0b.jpg', '<p>Tình yêu đích thực có thể nảy nở bên trong buồng hò hẹn không? Camila Queiroz và Klebber Toledo hướng dẫn nhóm người Brazil độc thân mới đang trên hành trình tìm kiếm nửa kia.</p>', 'Full', 11, 'tvshows', 'completed', 25, 2023, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Camila Queiroz","avatar":""},{"name":"Klebber Toledo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Love Is Blind: Brazil - A Fresh Start","Casamento às Cegas: Brasil"]', 1784690324244);
