INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-an', 'Thần Ẩn', 'The Last Immortal', 'https://phimimg.com/upload/vod/20260509-1/282fe95095e6e8b03004931dc0530111.jpg', 'https://phimimg.com/upload/vod/20260509-1/54eae4df377041938345f8ec8bbd968c.jpg', '<p>Câu chuyện đầy cảm hứng kể về A Âm, thú Thủy Ngưng chăm chỉ cầu tiến và Cổ Tấn, con trai của chân thần bị phong ấn thần lực, hai người tình cờ quen biết, từ đây bước vào con đường tìm kiếm tiên nguyên Phượng Ẩn, sau đó đồng hành cùng các bạn là Hồng Dịch, hồ ly Yêu tộc và Yến Sảng, công chúa Ưng tộc. Họ lên đường thu thập tiên nguyên Phượng Ẩn, trải qua vô vàn hiểm trở, nhiều lần đánh bại sự cản trở từ phản diện Thanh Lâm và thuộc hạ của hắn, giúp sức cho Phượng Ẩn niết bàn trở về, họ gặt hái được tình yêu, tình bạn và tình thân, bảo vệ hòa bình thế gian, gánh vác đại nghĩa chúng sinh.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'ongoing', 28, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lộ Tư","avatar":""},{"name":"Vương An Vũ","avatar":""},{"name":"Lý Quân Nhuệ","avatar":""},{"name":"Gia Nại Na","avatar":""},{"name":"Dĩnh Nhi","avatar":""},{"name":"Tào Phỉ Nhiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shen Yin","The Last Immortal","ตำนานรักผนึกสวรรค์","神隱","Hidden God","神隐"]', 1784690324244);
