INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('milli-vanilli', 'Milli Vanilli', 'Milli Vanilli', 'https://phimimg.com/upload/vod/20260505-1/311bf851c05598eba968b7a9a3431ba4.jpg', 'https://phimimg.com/upload/vod/20260505-1/8b5dc92457e3215388d5059cddd61304.jpg', '<p>Câu chuyện về Robert Pilatus và Fabrice Morvan, hai người bạn thân thiết từ thời trẻ ở Đức. Rob xuất thân từ một gia đình tan vỡ, còn Fabrice thì rời bỏ một gia đình bạo hành, cả hai đều có hoàn cảnh nuôi dưỡng tương tự, cũng như một mục tiêu tương lai: trở thành những siêu sao nổi tiếng. Chỉ trong vài năm ngắn ngủi, giấc mơ của họ đã trở thành hiện thực. Rob và Fab, được biết đến với cái tên Milli Vanilli, đã trở thành bộ đôi nhạc pop nổi tiếng nhất thế giới năm 1990 và giành giải GRAMMY cho Nghệ sĩ mới xuất sắc nhất. Tuy nhiên, sự thăng tiến đến thành công của họ lại đi kèm với một cái giá quá đắt, cuối cùng dẫn đến sự sụp đổ tai tiếng của họ.</p>', 'Trailer', 1, 'single', 'ongoing', 12, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Fab Morvan","avatar":""},{"name":"Rob Pilatus","avatar":""},{"name":"Downtown Julie Brown","avatar":""},{"name":"Timbaland","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Milli Vanilli"]', 1784690324244);
