INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-tinh-yeu-cua-rocky-va-rani', 'Câu Chuyện Tình Yêu Của Rocky Và Rani', 'Rocky Aur Rani Kii Prem Kahaani', 'https://phimimg.com/upload/vod/20260505-1/60250dfbefc07ec757b1f4ae02279976.jpg', 'https://phimimg.com/upload/vod/20260505-1/24b49e384df871ebbec5bb2ffffb9d90.jpg', '<p>Rocky, một chàng trai mê tập gym, phải lòng Rani, một cô gái xuất thân từ gia đình người Bengal có học thức. Đến từ hai thế giới hoàn toàn trái ngược, cả hai quyết định đổi gia đình để thích nghi với văn hóa và hoàn cảnh của nhau, cũng như để xem liệu cuộc hôn nhân của họ có thể bền vững hay không. Rocky và Rani bị mắc kẹt trong một thế giới nơi họ được gắn kết bởi tình yêu nhưng bị chia cách bởi gia đình, và câu hỏi cuối cùng là liệu họ có thể hòa nhập được hay không?</p>', 'Trailer', 1, 'single', 'ongoing', 21, 2023, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Alia Bhatt","avatar":""},{"name":"Ranveer Singh","avatar":""},{"name":"Jaya Bachchan","avatar":""},{"name":"शबाना आज़मी","avatar":""},{"name":"Dharmendra","avatar":""},{"name":"Aamir Bashir","avatar":""},{"name":"Tota Roy Chowdhury","avatar":""},{"name":"Kshitee Jog","avatar":""},{"name":"Anjali Anand","avatar":""},{"name":"Namit Das","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Rocky Aur Rani Ki Prem Kahani","Rocky Aur Rani Kii Prem Kahaani","Rocky aur Rani Kii Prem Kahani","寶萊塢之我們相愛吧","L''histoire d''amour de Rocky et Rani","Роки и Рани. История любви","The love story of Rocky and Rani","रॉकी और रानी की प्रेम कहानी"]', 1784690324244);
