INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-nu', 'Đả Nữ', 'Knuckle Girl', 'https://phimimg.com/upload/vod/20260502-1/70a5d3833924046326ba945df21b773c.jpg', 'https://phimimg.com/upload/vod/20260502-1/64d6ff2fec778fc09b425375dc29d816.jpg', '<p>Phim theo chân câu chuyện của Ran (Ayaka Miyoshi), người đối mặt với một tổ chức bí ẩn thông qua việc tham gia vào cuộc chiến không kỷ luật sau khi phát hiện ra em gái mình, Yuzuki (Kotona Minami), liên quan đến một vụ tội ác. Với nguy hiểm ẩn chứa ở mọi góc độ, Ran phải đổi găng tay quyền anh của mình thành găng tay đồng để cứu em gái. Liệu cô có thể cứu được em gái mình không?</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayaka Miyoshi","avatar":""},{"name":"Hideaki Ito","avatar":""},{"name":"Yosuke Kubozuka","avatar":""},{"name":"Goki Maeda","avatar":""},{"name":"Kanata Hosoda","avatar":""},{"name":"Kotona Minami","avatar":""},{"name":"Satoshi Jinbo","avatar":""},{"name":"Ruka Matsuda","avatar":""},{"name":"Masaki Miura","avatar":""},{"name":"Eishin","avatar":""},{"name":"Yukio Naya","avatar":""},{"name":"Yoshimasa Kondo","avatar":""},{"name":"Narimi Arimori","avatar":""},{"name":"Yuichi Yasoda","avatar":""},{"name":"Tomoki Kimura","avatar":""},{"name":"Kenichi Abe","avatar":""},{"name":"Taiga Komizu","avatar":""},{"name":"Ayako Inokuchi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Knuckle Girl","دختر مشت‌زن","反击少女","手指虎少女","ナックルガール"]', 1784690324244);
