INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('da-nu', 'Đả Nữ', 'Knuckle Girl', 'đả nữ knuckle girl ayaka miyoshi hideaki ito yosuke kubozuka goki maeda kanata hosoda kotona minami satoshi jinbo ruka matsuda masaki miura eishin yukio naya yoshimasa kondo narimi arimori yuichi yasoda tomoki kimura kenichi abe taiga komizu ayako inokuchi knuckle girl دختر مشت‌زن 反击少女 手指虎少女 ナックルガール', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-ngoai-truyen-loi-chan-tu', 'Phong Thần Ngoại Truyện: Lôi Chấn Tử', 'Lei Zhenzi Of The Creation Gods', 'https://phimimg.com/upload/vod/20231204-1/e33dbc70d9cef7f45d53b89812e77fea.jpg', 'https://phimimg.com/upload/vod/20231204-1/f592834b7fa0a6a7d41331cdda550d19.jpg', '<p>Hạ Đinh ban đầu là con của một gia đình tướng quân ở thànhTây Kì. Những kẻ man rợ đã xâm chiếm và giết cha mẹ của Hạ Đinh và tất cả binh lính của thànhTây Kì. Hạ Đinh chạy trốn đến trấn Thái Bình và lớn lên ở đây và hay bị con trai tù trưởng bắt nạt.. Tuy nhiên, để bảo vệ người dân ở thị trấn Thái Bình, Hạ Đinh đã chiến đấu chống lại những con rồng và sói xấu xa, khi những kẻ man rợ xâm chiếm thị trấn Thái Bình, Hạ Đinh cuối cùng cũng biết rằng mình là người được Thor lựa chọn. Anh mọc ra đôi cánh, tạo ra sấm sét, giết tất cả những kẻ man rợ, và cũng giết chết phù thủy độc ác. Đáng tiếc cuối cùng người yêu A Lê bị mụ phù thủy làm cho đau lòng mà chết, Hạ Đinh dùng đôi cánh của mình bảo vệ A Lê, biến thành người đá, trăm năm sau, sấm sét đánh tới, hòn đá nứt ra mà sinh ra đến một cậu bé tên Lôi Chấn Tử. Kể từ đó, Lôi Chấn Tử &nbsp;tạo ra sức mạnh của sấm sét và đã giúp đỡ mọi người</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Jack","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Wu Chun Yi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324244);
