INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-than-thai-thuong-vong-tinh', 'Dương Thần: Thái Thượng Vong Tình', 'Soul Of Light', 'https://phimimg.com/upload/vod/20260502-1/4e4da4b6a7d8baf40a42b5117f61bd5d.jpg', 'https://phimimg.com/upload/vod/20260502-1/f028bf125e3c33862719246c529b3b88.jpg', '<p>Dương Thần Chi Thái Thượng Vong Tình là một bộ phim cổ trang ly kỳ và giả tưởng kể về câu chuyện của Triệu Phi Dung, một vị thánh của giáo phái Đại La, người đã cố gắng bằng mọi cách để tìm ra Hồ tộc, bộ tộc ẩn giấu và giải thoát con quỷ của giáo phái Đại La. Hồng Dịch đã bị bắt nạt từ khi còn nhỏ, và để khiến mẹ mở màu mở mặt cậu đã vào thành để tham gia kỳ thi. Thật bất ngờ, vào đêm trước ngày nhập học, một cô gái bí ẩn đã mời Hồng Dịch đến dạy học cho Hồ tộc và Hồng Dịch đã tham gia vào một cuộc truy đuổi nguy hiểm. Sau khi trải qua nhiều cuộc phiêu lưu nguy hiểm, Hồng Dịch bị áp bức quyết định học võ thuật và gia nhập Hồ tộc để chống lại giáo phái Đại La.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Tổ Quân","avatar":""},{"name":"Dư Mộng Hàn","avatar":""},{"name":"Viên Tường Nhân","avatar":""},{"name":"Tôn Giao Long","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yang Shen Spirit","阳神之太上忘情"]', 1784690324244);
