INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-hinh-nhan', 'Bùa Hình Nhân', 'Hoon Payon', 'https://phimimg.com/upload/vod/20260502-1/20b6755bd32f2d72d339538feadef2bb.jpg', 'https://phimimg.com/upload/vod/20260502-1/a86c7b2ada9701edcdf0e7431a67f5e1.jpg', '<p>Thắm tìm kiếm anh trai Thi để báo tin cha mẹ qua đời. Thi được xuất gia làm tu sĩ tại một ngôi chùa trên đảo Don Sing Tham. Khi đến nơi, Thắm gặp Jes, cháu trai của cựu trụ trì. Jes làm hoon payon, những hình nộm đầy mê hoặc của người chết. Thẩm biết được tin đồn Thị biến mất sau khi sát hại trụ trì.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Phuwin Tangsakyuen","avatar":""},{"name":"Poompat Iam-samang","avatar":""},{"name":"Kunatip Pinpradub","avatar":""},{"name":"Bhuripat Vejvongsatechavat","avatar":""},{"name":"Thasorn Klinnium","avatar":""},{"name":"Sivawong Piyakesin","avatar":""},{"name":"Somyot Matures","avatar":""},{"name":"Waratthip Kittisiripaisan","avatar":""},{"name":"Pannawit Phattanasiri","avatar":""},{"name":"Nuttawatt Thanathaveeprasert","avatar":""},{"name":"Pongsakorn Meechai","avatar":""},{"name":"Jaturawit Chea","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Hoon Payon","ຫຸ່ນອາຄົມ","หุ่นพยนต์","ปลุกพยนต์","Pook Payon","Hoon Pa Yon","巫蛊人偶"]', 1784690324244);
