INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-nhan-tinh-co-truoc-giang-sinh', 'Tin Nhắn Tình Cờ Trước Giáng Sinh', '''Twas the Text Before Christmas', 'https://phimimg.com/upload/vod/20260501-1/ea9446935866c5733e6da634417eed63.jpg', 'https://phimimg.com/upload/vod/20260501-1/217163b0aa01eebebeb64727914fbf9c.jpg', '<p>Một tin nhắn không ngờ tới truyền cảm hứng cho Addie thực hiện chuyến đi nghỉ lễ tại Vermont. Ở đó, tình bạn mà cô có với Nana sẽ thay đổi cuộc đời cô mãi mãi.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Merritt Patterson","avatar":""},{"name":"Trevor Donovan","avatar":""},{"name":"Rob Stewart","avatar":""},{"name":"Jayne Eastwood","avatar":""},{"name":"Marisa McIntyre","avatar":""},{"name":"Peyton Boulley","avatar":""},{"name":"Derek Moran","avatar":""},{"name":"Tara Andrea","avatar":""},{"name":"Patrice Goodman","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Christmas by Chance","Twas the Text Before Christmas","Julemelding på villspor","叮咚聖誕情","''Twas the Text Before Christmas"]', 1784690324244);
