INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-mat-ma-ho-ve', 'Gấu Boonie: Mật Mã Hộ Vệ', 'Boonie Bears: Guardian Code', 'https://phimimg.com/upload/vod/20260429-1/803bf7953ee8d19351b5923c03f08bcc.jpg', 'https://phimimg.com/upload/vod/20260429-1/062f76ca89c38d928537d69a67041519.jpg', '<p>Một trận hỏa hoạn xảy ra khiến hai anh em gấu Briar và Bramble vô cùng đau buồn vì người mẹ yêu thương họ hết mực đã biến mất bí ẩn. Nhiều năm sau, khi cùng Vick đến một triển lãm rô-bốt, Briar và Bramble vô tình có được manh mối của gấu mẹ. Lần theo dấu vết để tìm mẹ, họ bất ngờ bị cuốn vào vụ bắt cóc của băng đảng Phế Liệu Nổi Loạn, đối mặt với vô vàn nguy hiểm để tìm ra sự thật năm xưa.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2023, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Bingjun","avatar":""},{"name":"Zhang Wei","avatar":""},{"name":"Yingying Miu","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"贾晨露","avatar":""},{"name":"Ming Zhang","avatar":""},{"name":"王思雨","avatar":""},{"name":"聂吉轩","avatar":""},{"name":"王天昊","avatar":""},{"name":"周子瑜","avatar":""},{"name":"Li Wanyao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["熊出没大电影9","熊出没·伴我“熊芯”","Boonie Bears: Guardian Code","熊出没大电影09之伴我熊芯","Загадковий світ роботів","Boonie Bears 9","부니베어 : 가디언 코드","부니 베어 : 가디언 코드","Xiong Chu Mei Ban Wo Xiong Xin","Xiong chu mo: Ban Wo Xiong Xin","Lustakad Karud: Kaotatud Aare"]', 178469