INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-sau', 'Biển Sâu', 'Deep Sea', 'https://phimimg.com/upload/vod/20260423-1/463d57c06c6fdf1dce44ea4f494d1159.jpg', 'https://phimimg.com/upload/vod/20260423-1/a4fe2989017621defb625fc16d8e268b.jpg', '<p>Sống như người tàng hình trong gia đình mới của bố, cô bé Sâm Tú đuổi theo tinh linh biển để đi tìm mẹ ruột. Trong quá trình ấy, Sâm Tú gặp gỡ nhân viên của quán cơm Thâm Hải. Ông chủ &quot;Nam Hà&quot; hứa sẽ dẫn Sâm Tú tìm mẹ nếu cô giúp đỡ quán cơm của &quot;chú&quot;. Liệu lời hứa ấy có được thực hiện? Ai mới là &quot;người tàng hình&quot; chân chính? Dưới biển sâu là mộng xưa khó tỉnh, hay người xưa khó về?</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Tingwen","avatar":""},{"name":"Su Xin","avatar":""},{"name":"Kuixing Teng","avatar":""},{"name":"Yang Ting","avatar":""},{"name":"Jing Ji","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"Tian Xiaopeng","avatar":""},{"name":"Fang Taochen","avatar":""},{"name":"Dong Yi","avatar":""},{"name":"Zhou Juan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["深海之驭海人","Deep Sea","Shēn Hǎi","Tiefe See","深海","심해","Shenhai","Shen Hai","Shen Hai Zhi Yu Hai Ren","Shenhai: Yu Hai Ren"]', 1784690324244);
