INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-quan-khong-nhu-y', 'Lang Quân Không Như Ý', 'The Princess And The Werewolf', 'https://phimimg.com/upload/vod/20260422-1/1b1a8b5f0acc7fc3d7ca4c7cf9a22bfa.jpg', 'https://phimimg.com/upload/vod/20260422-1/d972d6c9baf98e8e822731c3b85ac4dc.jpg', '<p>Công chúa Tề Ba sau một giấc tỉnh dậy, phát hiện mình bị bắt đến thế giới Hoá Thú kỳ ảo, trở thành người sắp được gả cho Hoá Thú Đại Vương - Khuê Mộc Lang.

Tề Ba nhiều lần bỏ trốn nhưng không thành công, còn gặp phải một nam nhân tên Lý Hùng khiến cho cuộc sống càng long trời lở đất.

Nhưng Tề Ba không biết rằng, Khuê Mộc Lang và Lý Hùng là dạng biến thân ban đêm - ban ngày của Đại Vương.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 20, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Tuyên Nghi","avatar":""},{"name":"Trần Triết Viễn","avatar":""},{"name":"Sư Tử Tầm","avatar":""},{"name":"Vương Lộ Tình","avatar":""},{"name":"Dương Xuyên Bắc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Go Princess Go 2","Lang Quân Không Như Ý","郎君不如意"]', 1784690324244);
