INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-va-con-buom', 'Huyền thoại và Con bướm', 'THE LEGEND & BUTTERFLY', 'https://phimimg.com/upload/vod/20260420-1/a008913ebf1d81ac02a429fe07cd634a.jpg', 'https://phimimg.com/upload/vod/20260420-1/ca40a6c14e420931d8244f5b8729bc67.jpg', '<p>Oda Nobunaga và Nōhime ban đầu kết hôn để hàn gắn mối quan hệ thù địch giữa hai vùng lân cận. Thật không may, họ lại trái ngược nhau như nước với lửa, dẫn đến một cuộc hôn nhân không mấy hạnh phúc. Khi kẻ thù của Oda, Imagawa Yoshimoto, tấn công Owari với đạo quân hùng mạnh, Oda vô cùng hoảng sợ trước sự chênh lệch sức mạnh quân sự quá lớn. Tuy nhiên, Nohime đã động viên ông đừng tuyệt vọng, và cả hai cùng vạch ra một kế hoạch chiến thuật để vượt qua khó khăn.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takuya Kimura","avatar":""},{"name":"Haruka Ayase","avatar":""},{"name":"Hideaki Ito","avatar":""},{"name":"Miki Nakatani","avatar":""},{"name":"Takumi Saitoh","avatar":""},{"name":"Hio Miyazawa","avatar":""},{"name":"Somegoro Ichikawa","avatar":""},{"name":"Kinya Kitaoji","avatar":""},{"name":"Masato Wada","avatar":""},{"name":"Tsutomu Takahashi","avatar":""},{"name":"Manabu Hamada","avatar":""},{"name":"Daisuke Honda","avatar":""},{"name":"Kokoro Morita","avatar":""},{"name":"Ai Mikami","avatar":""},{"name":"Shūichirō Masuda","avatar":""},{"name":"Hirotaro Honda","avatar":""},{"name":"Toshinori Omi","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["レジェンド・アンド・バタフライ","レジェンド&バタフライ","The Legend and Butterfly","傳奇與