INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-kiep-may-man', 'Bảy Kiếp May Mắn', 'Love You Seven Times', 'https://phimimg.com/upload/vod/20260420-1/f9e0975b670bb12393fcf8141ed141e3.jpg', 'https://phimimg.com/upload/vod/20260420-1/fc059f44c7b342a66b1486507bf59ea8.jpg', '<p>Bảy Kiếp Không May&quot; của Cửu Lộ Phi Hương, xoay quanh câu chuyện kể về hai vị thần tiên trên trời vì làm rối tơ hồng của Nguyệt lão mà bị Ngọc Hoàng trách phạt cùng nhau chịu 7 kiếp nhân duyên ở chốn nhân gian. Vân Tường là tiểu tiên nữ trông coi tơ hồng nhân duyên trong phủ Nguyệt Lão còn Sơ Không là tiên quân cai quản tháng đầu tiên của năm. Hai người vừa gặp mặt đã nhận mặt kẻ thù không đội trời chung, cãi lộn đến mức mớ tơ hồng đã rối nay còn rối tung. Cả hai bị Nguyệt lão phạt lịch kiếp xuống trần, trải qua đủ 7 lần tình kiếp mới được trở về tiên giới. Và những câu chuyện thú vị bắt đầu xảy ra từ đây.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 18, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Siêu Việt","avatar":""},{"name":"Đinh Vũ Hề","avatar":""},{"name":"Trương Lăng Hách","avatar":""},{"name":"Tinh Trạch","avatar":""},{"name":"Trương Tuyết Hạm","avatar":""},{"name":"Lâm Bách Duệ","avatar":""},{"name":"Lư Dục Hiểu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love You Seven Times","一时冲动，七世吉祥"