INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nha-cung-gia-dinh-fury-phan-1', 'Ở Nhà Cùng Gia Đình Fury (Phần 1)', 'At Home With The Furys (Season 1)', 'https://phimimg.com/upload/vod/20260415-1/e2341e1d0cc4f4a55cfb324cdb2b3ab3.jpg', 'https://phimimg.com/upload/vod/20260415-1/90d764abba3771cacfc84964cea735f4.jpg', '<p>Nhà vô địch hạng nặng bất bại Tyson Fury giã từ sự nghiệp boxing để quay về với cuộc sống gia đình đầy những tình huống lập dị và hài hước trong bộ phim tài liệu thực tế (docusoap) đầy vui nhộn nhưng cũng không kém phần chân thành này. Bộ phim mở ra một góc nhìn hoàn toàn khác về &quot;Vua giang hồ&quot; khi anh rời xa ánh đèn sân khấu để đối mặt với những thử thách thường nhật của một người cha và một người chồng.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 20, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tyson Fury","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["At Home with the Furys"]', 1784690324244);
