INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-vuong-trum-cuoi-cung-hung-cuc-ac-se-doc-suc-vi-nguoi-dan-phan-1', 'Nữ Vương Trùm Cuối Cùng Hung Cực Ác Sẽ Dốc Sức Vì Người Dân (Phần 1)', 'The Most Heretical Last Boss Queen: From Villainess to Savior (Season 1)', 'nữ vương trùm cuối cùng hung cực ác sẽ dốc sức vì người dân (phần 1) the most heretical last boss queen: from villainess to savior (season 1) fairouz ai haruka tomatsu higeki no genkyō to naru saikyō gedō last boss joō wa tami no tame ni tsukushimasu. higeki no genkyou to naru saikyou gedou last boss joou wa tami no tame ni tsukushimasu. ラス為 lastame 成為悲劇元兇的最強異端，最後頭目女王為了人民犧牲奉獻 第二季 the most heretical last boss queen: from villainess to savior. 悲劇の元凶となる最強外道ラスボス女王は民の為に尽くします。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-moi-dieu-dan-an-bai', 'Khi Mọi Điều Dần An Bài', 'Falling into Place', 'https://phimimg.com/upload/vod/20260414-1/65f52873abcc8d07d33dabdfb3a9d1f4.jpg', 'https://phimimg.com/upload/vod/20260414-1/7643c8ab963fcbf773b4356d19200a4c.jpg', '<p>Kira và Ian – cả hai đều ở độ tuổi giữa 30 – gặp nhau vào một ngày cuối tuần mùa đông trên đảo Skye. Cả hai đều đang chạy trốn – khỏi quá khứ cũng như khỏi thực tại của cuộc sống hiện tại. 36 giờ họ ở bên nhau trôi qua trong niềm vui và sự thoải mái. Một mối liên kết sâu sắc, gần như kỳ diệu, nảy sinh giữa hai người xa lạ. Mọi thứ dường như đều có thể. Nhưng số phận lại chia cắt họ một lần nữa. Cả hai trở về London, không hề hay biết rằng họ đang sống trong cùng một thành phố. Thường chỉ cách nhau vài phút, vài mét và những sự trùng hợp ngẫu nhiên, Kira và Ian di chuyển trong thành phố nhộn nhịp; họ không bao giờ gặp nhau. Trước khi thực sự gặp gỡ, họ phải đối mặt với những con quỷ trong lòng mình.</p>', 'Full', 1, 'single', 'completed', 25, 2023, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Aylin Tezel","avatar":""},{"name":"Chris Fulton","avatar":""},{"name":"Rory Fleck-Byrne","avatar":""},{"name":"Alexandra Dowling","avatar":""},{"name":"Samuel Anderson","avatar":""},{"name":"Juliet Cowan","avatar":""},{"name":"Olwen Fouéré","avatar":""},{"name":"Michael Carter","avatar":""},{"name":"Seylan Baxter","avatar":""},{"name":"Cian Barry","avatar":""},{"name":"Kevin Mains","avatar":""},{"name":"Anna Russell-Martin","avatar":""},{"name":"Mike Noble","avatar":""},{"name":"Layo-Christina Akinlude","avatar":""},{"name":"Kathryn Howden","avatar":""},{"name":"Jerry Hoffmann","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Cavale sentimentale","Falling into Place"]', 1784690324244);
