INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-moi-dieu-dan-an-bai', 'Khi Mọi Điều Dần An Bài', 'Falling into Place', 'khi mọi điều dần an bài falling into place aylin tezel chris fulton rory fleck-byrne alexandra dowling samuel anderson juliet cowan olwen fouéré michael carter seylan baxter cian barry kevin mains anna russell-martin mike noble layo-christina akinlude kathryn howden jerry hoffmann cavale sentimentale falling into place', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-thue-phan-3', 'Bạn Gái Thuê (Phần 3)', 'Rent-A-Girlfriend (Season 3)', 'https://phimimg.com/upload/vod/20250921-1/7464e6aff4d69c4811cd6ac8874cbd7a.jpg', 'https://phimimg.com/upload/vod/20250921-1/2a285f0bcfb758696a05e3dd19d95c54.jpg', '<p>Sau khi bị bạn gái bỏ rơi, cậu sinh viên đại học Kinoshita Kazuya cố gắng vá lại trái tim tan vỡ của mình bằng một người bạn gái thuê từ ứng dụng di động. Lúc đầu, Mizuhara Chzuru có vẻ như là một người bạn gái hoàn hảo với tất cả phẩm chất mà bất cứ chàng trai nào cũng phải mong đợi: xinh đẹp, dễ thương và chu đáo.

Với những cảm xúc lẫn lộn sau buổi hẹn hò đầu tiên, Kazuya nghĩ Chizuru chỉ đang trêu đùa với trái tim của mình nên đã đánh giá cô 1 sao trên ứng dụng di động. Điều này khiến Chizuru tức giận và bộc lộ bản chất thật của mình trong buổi hẹn hò thứ 2: một Chizuru đanh đá, nóng nảy, trái ngược hoàn toàn với ấn tượng ban đầu. Ngay lúc đó, bà của Kazuya bị ngất xíu nên cậu phải kéo cả Chizuru vào bẹnh viện.

Mặc dù tình hình của bà Kazuya không có gì nghiêm trọng, nhưng bà lại ngây ngất Chizuru và cực kỳ cảm động vì cuối cùng đứa cháu trai của mình đã có bạn gái. Không thể nói ra sự thật, Kazuya và Chizuru phải tiếp tục mối quan hệ bạn gái thuê này.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 13, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shun Horie","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Aoi Yuuki","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Yukari Nozawa","avatar":""},{"name":"Sayuri Sadaoka","avatar":""},{"name":"Masayuki Akasaka","avatar":""},{"name":"Gakuto Kajiwara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["租借女友","किराए पर प्रेमिका","Kano Kari","Kanojo, Okarishimasu","Kanojo, Okarishimasu 2","KanoKari 2","彼女、お借りします","Rental Girlfriend The Animation","Kanojo Okarishimasu","Una novia de alquiler","Девушка напрокат","Девушка на час","Девушка в аренду","สะดุดรักยัยแฟนเช่า","I''d Like to Borrow a Girlfriend","Rental Girlfriend","Rental Girlfriend 2","Rent-a-Girlfriend","Dịch Vụ Thuê Bạn Gái","Bạn gái, tôi thuê cô"]', 1784690324244);
