INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-trang-2023', 'Tẩy Trắng', 'Clean Sweep', 'https://phimimg.com/upload/vod/20260409-1/c4d2d2cca587e3f01e459fb9e2f45e5b.jpg', 'https://phimimg.com/upload/vod/20260409-1/84aaa0edbf443c9d95660e0f99bb736d.jpg', '<p>Shelly Mohan là một người mẹ bình thường, luôn tất bật xoay xở với cuộc sống và lịch trình dày đặc của ba đứa con cùng người chồng là thanh tra cảnh sát địa phương. Đó là một cuộc sống hỗn loạn và ít khi được ghi nhận, nhưng cô vẫn cảm thấy hạnh phúc... cho đến khi một bí mật đen tối từ quá khứ bất ngờ bị khơi lại.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 23, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Charlene McKenna","avatar":""},{"name":"Barry Ward","avatar":""},{"name":"Aidan McCann","avatar":""},{"name":"Rhys Mannion","avatar":""},{"name":"Katelyn Rose Downey","avatar":""},{"name":"Jeanne Nicole Ní Áinle","avatar":""},{"name":"Adam Fergus","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Clean Sweep"]', 1784690324244);
