INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-canh-nhan-quai-dam', 'Đả Canh Nhân Quái Đàm', 'The Story Of The Night Watcher 2', 'https://phimimg.com/upload/vod/20260409-1/33db62b432c7fe4f26597de58e6baa60.jpg', 'https://phimimg.com/upload/vod/20260409-1/38fbc45ad210771471019148a3395dd9.jpg', '<p>Chuyện kể về thời Dân Quốc, trấn Lâm Gia bất ngờ xuất hiện vụ án kỳ quái, nhiều người dân như trúng phải tà, bị một thế lực mờ ám thao túng thần trí đi lang thang như xác sống, chỉ trong một đêm đã biến mất không để lại dấu vết. Trong thành có một kẻ gác đêm tên là Thẩm Tiểu Hàn, vì để giải cứu dân chúng nên anh bắt tay vào điều tra. Nhờ thuật pháp của kẻ gác đêm, anh cuối cùng tìm ra và triệt hạ được lão Khương bị tẩu hỏa nhập ma vì luyện xà cổ, cứu được dân chúng trong thành, bảo vệ an toàn cho trấn Lâm Gia.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Ngu Tư","avatar":""},{"name":"Uyển Quỳnh Đan","avatar":""},{"name":"Trần Sáng","avatar":""},{"name":"Trần Ngọc Dũng","avatar":""},{"name":"Vương Hâm Đình","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Strange Tales of the Night Watchman","打更人怪谈"]', 1784690324244);
