INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-map-sat-thu', 'Cá Mập Sát Thủ', 'Man-Eating Shark (Shark Evil)', 'https://phimimg.com/upload/vod/20241001-1/558042d63440da03b34711bb877d78d8.jpg', 'https://phimimg.com/upload/vod/20241001-1/04b417b48bd7c5bca385db8f9bc52c1d.jpg', '<p>Một nhóm kẻ săn trộm săn bắt cá mập bừa bãi trên biển khơi khiến cá mập trắng lớn tức giận và những kẻ săn trộm đã bị cá mập ăn thịt. Sau đó cá mập trắng dã hướng mắt để ý đến bốn người bạn đang tổ chức lễ tốt nghiệp trên thuyền. Bốn người họ phải chiến đấu quyết liệt, giữa sự sống và cái chết, chỉ có tìm cách thoát khỏi miệng cá mập và quay trở lại bờ biển mới có thể sống sót...</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tín Triết","avatar":""},{"name":"Đổng Phàn (Vana)","avatar":""},{"name":"Ngụy Hiểu Tuyền","avatar":""},{"name":"Hoàng Tử Lăng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["White Shark","SHARK EVIL","食人鲨"]', 1784690324244);
