INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-nha-ben-phan-1', 'Thiên Sứ Nhà Bên (Phần 1)', 'The Angel Next Door Spoils Me Rotten (Season 1)', 'https://phimimg.com/upload/vod/20241109-1/d36f420eae1baea249c18d64e211a0a2.jpg', 'https://phimimg.com/upload/vod/20260404-1/26f9522b699bbc1a17f8ea6b865b1902.jpg', '<p>Sau khi bị cảm lạnh khi đưa chiếc ô duy nhất của mình cho một cô gái đang ngồi dưới mưa, Amane Fujimiya chỉ mong cô ấy cuối cùng sẽ trả lại nó. Tuy nhiên, Mahiru Shiina, &quot;Thiên thần&quot; của trường Amane và là hàng xóm của cậu, lại cho cậu nhiều hơn thế.

Từ duy nhất Mahiru có thể mô tả sự hỗn loạn là &quot;khó coi&quot;. Nhưng bất chấp sự miêu tả không thiện cảm của cô ấy, Mahiru vẫn tiếp tục giúp đỡ Amane đang vô vọng. Có điều gì mà Thiên sứ không làm được không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Taito Ban","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Haruka Shiraishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["关于邻家的天使大人不知不觉把我惯成了废人这件事","关于邻家的天使大人不知不觉把我惯成了废人这档子事","关于我在无意间被隔壁的天使变成废柴这件事","關於我在無意間被隔壁的天使變成廢柴這件事","Otonarino-Tenshisama","Otonari No Tenshi-Sama","Otonari no Tenshi-sama ni Itsunomanika Dame Ningen ni Sareteita Ken","Otonari no Tenshi-sama ni Itsu no Ma ni ka Dame Ningen ni Sareteita Ken","Ангел по соседству меня ужасно балует","關於我在無意間被隔壁的天使變成廢柴這件事 2","The Angel Next Door Spoils Me Rotten","Thiên Sứ Nhà Bên","お隣の天使様にいつの間にか駄目人間にされていた件"]', 1784690324244);
