INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-lo-duong-ve-nha', 'Quy Lộ (Đường Về Nhà)', 'Road Home', 'https://phimimg.com/upload/vod/20260403-1/f6c977079d58cfa1bb2cdfacdc4a47e2.jpg', 'https://phimimg.com/upload/vod/20260403-1/dc1e871a4b4fa8ba1cb779511c6729ff.jpg', '<p>Quy Lộ do đạo diễn Từ Thúy Hoa chỉ đạo được chuyển thể từ bộ tiểu thuyết cùng tên của tác giả Mặc Bảo Phi Bảo với sự tham gia của Đàm Tùng Vận và Tỉnh Bách Nhiên. Bộ phim xoay quanh cặp đôi Quy Hiểu và Lộ Viêm Thần, là mối tình đầu của nhau, nhưng sau khi tốt nghiệp đại học Lộ Viêm Thần đi làm cảnh sát đặc nhiệm. Cùng lúc đó, gia đình Quy Hiểu xảy ra biến cố, tình yêu của họ cũng kết thúc từ đó. Mười năm sau, Quy Hiểu và Lộ Viêm Thần gặp lại và tái hợp, hai người đều nhận ra họ không thể kìm chế được sự khao khát tình yêu dành cho nhau. Thế nhưng cha mẹ của Lộ Viêm Thần lại sắp đặt hôn ước cho anh, và Lộ Viêm Thần đã quyết định đưa ra lựa chọn. Sau khi kết hôn, Viêm Thần bị thương trong một lần làm nhiệm vụ và hôn mê. Quy Hiểu mang thai chạy đến bên và sinh cho anh một đứa con gái, ở thành phố biên giới nơi anh làm nhiệm vụ suốt mười năm. Một gia đình ba người hạnh phúc bên nhau.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 15, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Jing Boran","avatar":""},{"name":"Tan Songyun","avatar":""},{"name":"Zhang Bojia","avatar":""},{"name":"Li Mincheng","avatar":""},{"name":"Zhang Qiaoer","avatar":""},{"name":"Zhang Enshuo","avatar":""},{"name":"Wang Hao","avatar":""},{"name":"Liang Tian","avatar":""},{"name":"Niu Junfeng","avatar":""},{"name":"Sha Baoliang","avatar":""},{"name":"Hai Ling","avatar":""},{"name":"Lu Yupeng","avatar":""},{"name":"Xu Rongzhen","avatar":""},{"name":"Gong Rui","avatar":""},{"name":"Wu Yufang","avatar":""},{"name":"Song Ningfeng","avatar":""},{"name":"Guo Xiaotian","avatar":""},{"name":"Li Mozhi","avatar":""},{"name":"Liu Lu","avatar":""},{"name":"Su Xin","avatar":""},{"name":"Zheng Jiabin","avatar":""},{"name":"Wu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["归路","Road Home","Road to Home"]', 1784690324244);
