INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-cau-be-but-chi-31-dai-chien-sieu-nang-luc-sushi-bay-', 'Shin - Cậu Bé Bút Chì 31: Đại Chiến Siêu Năng Lực ~ Sushi Bay ~', 'New Dimension! Crayon Shin-chan the Movie: Battle of Supernatural Powers ~Flying Sushi~', 'https://phimimg.com/upload/vod/20260402-1/0f07d9968e1b28a1c2dce38834255d16.jpg', 'https://phimimg.com/upload/vod/20260402-1/56d3d6c53133e6e2f96fc19a35580b91.jpg', '<p>3DCG! Shin Cậu Bé Bút Chì: Đại Chiến Siêu Năng Lực ~Sushi Bay~ xoay quanh câu chuyện về hai nguồn sáng đặc biệt từ vũ trụ mang theo siêu năng lực đặc biệt tới Trái Đất. Một nguồn sáng tích cực “nhập” vào nhóc Shin, khiến cặp mông núng nính của cậu chàng trở nên nóng bỏng và có khả năng điều khiển những đồ vật xung quanh theo ý muốn.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Yumiko Kobayashi","avatar":""},{"name":"Miki Narahashi","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Suzuki Mogura","avatar":""},{"name":"Tori Matsuzaka","avatar":""},{"name":"Mizukawa Katamari","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Shin Jigen! Crayon Shin-chan THE MOVIE: Chounouryoku Dai Kessen ~Tobe Tobe Temakizushi~","Shin Jigen! Crayon Shin-chan The Movie Chōnōryoku Dai Kessen: Tobetobe Temakizushi","Shin Jigen! Crayon Shin-chan the Movie: Chounouryoku Daikessen - Tobe Tobe Temakizushi","New Dimension! Crayon Shin-chan the Movie Great Psychokinetic Battle: Leaping Handmade Sushi","Crayon Shin-chan Movie 31: Chounouryoku Daikessen - Tobe Tobe Temakizushi","ชินจัง เดอะมูฟวี่ ตอน มิติใหม่! สุดยอดศึกพลังจิต บินไปเลยเทมากิซูชิ","新次元！蜡笔小新THE MOVIE 超能力大决战～飞吧！手卷寿司","โฉมใหม่! เครยอนชินจัง เดอะมูฟวี่ มหาสงครามซุปเปอร์พลังจิต - ซูชิเหินเวหา -","新次元！蠟筆小新大電影：超能力大決戰～飛吧飛吧手捲壽司～","New.Dimension.Crayon.Shinchan.the.Movie.Battle.of.Supernatural.Powers.~Flying.Sushi~","Shin Jigen! Crayon Shin-chan The Movie","Shin - Cậu Bé Bút Chì: Đại Chiến Siêu Năng Lực - Sushi Bay","Shin-chan: El superhéroe","しん次元！クレヨンしんちゃんTHE MOVIE 超能力大決戦 ～とべとべ手巻き寿司～"]', 1784690324244);
