INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('shin-cau-be-but-chi-31-dai-chien-sieu-nang-luc-sushi-bay-', 'Shin - Cậu Bé Bút Chì 31: Đại Chiến Siêu Năng Lực ~ Sushi Bay ~', 'New Dimension! Crayon Shin-chan the Movie: Battle of Supernatural Powers ~Flying Sushi~', 'shin - cậu bé bút chì 31: đại chiến siêu năng lực ~ sushi bay ~ new dimension! crayon shin-chan the movie: battle of supernatural powers ~flying sushi~ yumiko kobayashi miki narahashi toshiyuki morikawa satomi korogi suzuki mogura tori matsuzaka mizukawa katamari shin jigen! crayon shin-chan the movie: chounouryoku dai kessen ~tobe tobe temakizushi~ shin jigen! crayon shin-chan the movie chōnōryoku dai kessen: tobetobe temakizushi shin jigen! crayon shin-chan the movie: chounouryoku daikessen - tobe tobe temakizushi new dimension! crayon shin-chan the movie great psychokinetic battle: leaping handmade sushi crayon shin-chan movie 31: chounouryoku daikessen - tobe tobe temakizushi ชินจัง เดอะมูฟวี่ ตอน มิติใหม่! สุดยอดศึกพลังจิต บินไปเลยเทมากิซูชิ 新次元！蜡笔小新the movie 超能力大决战～飞吧！手卷寿司 โฉมใหม่! เครยอนชินจัง เดอะมูฟวี่ มหาสงครามซุปเปอร์พลังจิต - ซูชิเหินเวหา - 新次元！蠟筆小新大電影：超能力大決戰～飛吧飛吧手捲壽司～ new.dimension.crayon.shinchan.the.movie.battle.of.supernatural.powers.~flying.sushi~ shin jigen! crayon shin-chan the movie shin - cậu bé bút chì: đại chiến siêu năng lực - sushi bay shin-chan: el superhéroe しん次元！クレヨンしんちゃんthe movie 超能力大決戦 ～とべとべ手巻き寿司～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zienlang-mai-la-ban-than', 'Zien-Lang Mãi Là Bạn Thân', 'Zien-Lang The Movie Best Friends Forever', 'https://phimimg.com/upload/vod/20260402-1/1c1e242cec762acd0baf648a2f19051e.jpg', 'https://phimimg.com/upload/vod/20260402-1/038098323ef2cd8591f8687dd3c299b9.jpg', '<p>Câu chuyện xoay quanh một nhóm 8 người bạn thiếu niên vùng Isaan (Đông Bắc Thái Lan). Họ tận hưởng cuộc sống nông thôn thanh bình, cùng nhau vui đùa, săn bắt và tìm kiếm thức ăn giữa thiên nhiên hoang sơ. Thế nhưng, cuộc sống vô tư lự ấy bỗng chốc bị đảo lộn khi cả nhóm phát hiện ra một sự thật nghiệt ngã: một người bạn trong nhóm sẽ bị mù hoàn toàn chỉ trong vòng một tháng tới. Nguyên nhân được xác định là do thói quen lạm dụng rượu trắng (rượu lậu) quá mức trong thời gian dài. Đối mặt với nghịch cảnh, nhóm bạn đã cùng nhau trải qua những ngày tháng cuối cùng đầy xúc động để giúp người bạn ấy lưu giữ những ký ức đẹp nhất về ánh sáng và tình bạn.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Phuwanet Seechomphu","avatar":""},{"name":"Songkran Sitthi","avatar":""},{"name":"Pralinya Natongchai","avatar":""},{"name":"Tanin Laitong","avatar":""},{"name":"Surat Kaewchan","avatar":""},{"name":"Sitthichai Rattanavichai","avatar":""},{"name":"Natthawut Saenyabut","avatar":""},{"name":"Boonchok Sikham","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เซียนหรั่งเดอะมูฟวี่","เซียนหรั่ง เดอะมูฟวี่ ตอน แหล่งเพื่อนรัก","Best Friend Forever","Sian Lang The Movie","Zian Rang The Movie","ຊຽນຫຣັ່ງ ເດິມູວີ","Xian Rang The Movie","Zian Rhung The Movie","เซียนหรั่ง เดอะมูฟวี่"]', 1784690324244);
