INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soundtrack-2', 'Soundtrack #2', 'Soundtrack #2', 'https://phimimg.com/upload/vod/20260401-1/e480dfd0a37afbc43357dc4554b94cac.jpg', 'https://phimimg.com/upload/vod/20260401-1/0d2e8f1bd6c051e010b94d4e9701abb2.jpg', '<p>Su-ho và Hyeon-seo, cặp đôi từng có 6 năm mặn nồng bên nhau, tình cờ tái ngộ trong hoàn cảnh hoàn toàn khác biệt: một người giờ đây là vị CEO trẻ tuổi giàu có, người kia là một giáo viên dạy piano. Mối nhân duyên trỗi dậy khi K – một nhạc sĩ tài năng – cùng Su-ho thực hiện một dự án âm nhạc chung và đã mời Hyeon-seo tham gia. Từ đây, Su-ho và Hyeon-seo bắt đầu một hành trình tình yêu đầy gập ghềnh với những nút thắt và biến cố bất ngờ. Liệu lịch sử có lặp lại một lần nữa hay họ sẽ có một cái kết khác cho bản nhạc tình này?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Keum Sae-rok","avatar":""},{"name":"Steve Sanghyun Noh","avatar":""},{"name":"Demian","avatar":""},{"name":"Kwon Seung-woo","avatar":""},{"name":"Jeon Hye-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Soundtrack Number 2","A Segunda Canção de Amor","單戀原聲帶2","Soundtrack 2","사운드트랙 #2"]', 1784690324244);
