INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-quang-chi-ha', 'Lưu Quang Chi Hạ', 'Against The Light', 'https://phimimg.com/upload/vod/20260330-1/47b89f932f02d3b4e89271776e74f2c4.jpg', 'https://phimimg.com/upload/vod/20260330-1/329f36dd57dca0da3226f53e468a1fe7.jpg', '<p>Năm 10 tuổi, Bạch Tịch Ninh từ một tiểu thư tập đoàn trang sức rơi vào biến cố gia đình, được một Hoa kiều Canada nhận nuôi và rời xa Trung Quốc. Mười lăm năm sau, khi phát hiện mẹ mình từng bị hãm hại và ngồi tù oan, cô trở về với thân phận mới là Cố Tinh Nghiên, gia nhập Tập đoàn Đông Thần để tìm lại công bằng. Giữa cuộc đấu quyền lực khốc liệt trong giới tư bản, cùng theo dõi Tịch Ninh từng bước vạch trần sự thật và khẳng định vị trí của mình trong ngành trang sức qua các tập phim.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 24, 2023, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Doanh Oánh","avatar":""},{"name":"Lý Tử Hùng","avatar":""},{"name":"Trương Hàm Dư","avatar":""},{"name":"Từ Tiểu Táp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逆光","Against The Light","流光之下"]', 1784690324244);
