INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-bien-sau', 'Thảm Họa Biển Sâu', 'The Abyss Rescue', 'https://phimimg.com/upload/vod/20260320-1/5bb70892a0c137c92b1924f5bbd446bc.jpg', 'https://phimimg.com/upload/vod/20260320-1/ca4c2ddb82dc640f4057e41a8d666227.jpg', '<p>Đội thám hiểm đại dương của doanh nghiệp An Thụy đang tiến hành khảo sát khoa học tại một rãnh biển sâu. Tàu lặn &quot;Kẻ Phiêu Lưu&quot; trong lúc ở độ sâu 6.130 mét dưới đáy biển đã vô tình lọt vào một thác nước ngầm; chân vịt của tàu bị dây cáp từ xác tàu đắm quấn chặt, khiến các nhà khoa học bị mắc kẹt dưới đáy đại dương. Vì tàu &quot;Thanh Long&quot; từng có kinh nghiệm thám hiểm rãnh biển này vài năm trước, doanh nghiệp An Thụy đã gửi lời yêu cầu cứu hộ khẩn cấp.&nbsp; Đội cứu hộ được thành lập và tàu Thanh Long lập tức nhổ neo xuất phát. Khi đến hiện trường, tàu mẹ của &quot;Kẻ Phiêu Lưu&quot; thông báo một tin chấn động: lượng oxy trên tàu lặn chỉ còn đủ dùng trong 32 giờ. Trong tình thế ngàn cân treo sợi tóc, ba phi công lặn trên tàu Thanh Long ngay lập tức triển khai kế hoạch giải cứu. Tuy nhiên, việc cứu hộ tại khu vực có môi trường khắc nghiệt nhất Trái Đất đối mặt với vô vàn khó khăn: áp suất cực cao, bóng tối hoàn toàn, nhiệt độ thấp và lượng oxy ít ỏi. Các phi công tàu Thanh Long đã lần lượt vượt qua tất cả và cuối cùng cũng tìm thấy tàu &quot;Kẻ Phiêu Lưu&quot;. Đối mặt với con tàu đã mất hoàn toàn động lực, các thành viên của cả hai tàu lặn đã cùng nhau hợp tác để thoát khỏi vùng biển sâu u tối.</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mân Thành","avatar":""},{"name":"Lý Viện","avatar":""},{"name":"Lâm Nghiên Nhu","avatar":""},{"name":"Bành Sĩ Đằng","avatar":""},{"name":"Cao Cao","avatar":""},{"name":"Vu Tiểu Bân","avatar":""},{"name":"Hoàng Nhất Hàm","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Abyss Rescue","Deep Sea Rescue","怒海浩劫"]', 1784690324244);
