INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lu-khach-su-that-sau-tam-ao-vua', 'Lữ Khách: Sự Thật Sau Tấm Áo Vua', 'The Traveller: The Naked King', 'https://phimimg.com/upload/vod/20260311-1/2bf44c575b5dd905e54f44059b8d9d55.jpg', 'https://phimimg.com/upload/vod/20260311-1/d89e9f7dd796acb7c2107f8e07cf332c.jpg', '<p>Đại úy Kandinsky lần theo cuốn sổ bí ẩn ghi lại hàng loạt vụ án chưa có lời giải và dần phát hiện một chuỗi tội ác kéo dài suốt nhiều năm. Nhờ những manh mối quan trọng từ Ủy viên Macena, anh xác nhận sự tồn tại của một kẻ sát nhân hàng loạt hoạt động xuyên biên giới. Cùng sự hỗ trợ của các cộng sự, Kandinsky kiên trì ghép nối từng mảnh ghép từ lời kể của gia đình nạn nhân và các ghi chép trong sổ tay. Cuộc truy lùng cuối cùng cũng dẫn anh đến danh tính thật sự của kẻ đứng sau tất cả.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Bruno Debrandt","avatar":""},{"name":"Jeanne Bournaud","avatar":""},{"name":"Hubert Delattre","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324244);
