INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-live-action-phan-1', 'Đảo Hải Tặc (Live Action) (Phần 1)', 'ONE PIECE (Live Action) (Season 1)', 'https://phimimg.com/upload/vod/20260310-1/fad63813186f00a3c206f4c7d04211b2.jpg', 'https://phimimg.com/upload/vod/20260310-1/8013044ff3248265d4125729933e1413.jpg', '<p>Với chiếc mũ rơm và nhóm bạn đủ thành phần, hải tặc trẻ Monkey Monkey D. Luffy có hành trình săn kho báu hoành tráng trong bản chuyển thể người đóng này của bộ manga nổi tiếng.</p>', 'Hoàn tất (8/8)', 8, 'series', 'completed', 24, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Iñaki Godoy","avatar":""},{"name":"Emily Rudd","avatar":""},{"name":"Mackenyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324244);
