INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-trom-khong-the-giau', 'Vụng Trộm Không Thể Giấu', 'Hidden Love', 'https://phimimg.com/upload/vod/20240314-1/95c23009354463bf639852c6b906577c.jpg', 'https://phimimg.com/upload/vod/20240314-1/a20f333b7e8c7fe022e33f74bd6e87de.jpg', '<p>Xoay quanh câu chuyện diễn ra vào thời trung học, Tang Trĩ thường xuyên bị mời phụ huynh, để giải quyết phiền toái này cô quyết định nhờ anh trai đi hộ. Nhưng anh em ruột hễ gặp nhau là cà khịa, không thể làm gì khác hơn là phải nhờ người bạn cùng phòng thường đến nhà chơi của anh trai là Đoàn Gia Hứa. Dưới sự nhờ vả và uy hiếp của Tang Trĩ, Đoàn Gia Hứa giúp Tang Trĩ đến trường gặp giáo viên, vì vậy mà hai người cũng kết duyên, từ đây Đoàn Gia Hứa càng yêu mến và che chở Tang Trĩ như em gái ruột mình. Đoàn Gia Hứa tốt nghiệp đại học, hai người chia cách hai nơi, bởi vì một vài hiểu lầm mà quan hệ hời hợt. Cho đến khi Tang Trĩ trưởng thành, thi được vào trường học ở thành phố có Đoàn Gia Hứa như cô mong muốn, hai người mới gặp lại nhau. Tiếp xúc ngày càng thân mật, Tang Trĩ dần phát hiện cội nguồn áp lực của Đoàn Gia Hứa, cô muốn bảo vệ người anh trai luôn đối xử rất tốt với mình này, nhặt lại tình cảm thầm mến đã chôn giấu từ lâu. Bằng sự bầu bạn của Tang Trĩ, Đoàn Gia Hứa dần dần tháo gỡ khúc mắc, anh đã thật tâm yêu thích Tang Trĩ. Câu chuyện thầm mến hồn nhiên cuối cùng cũng nở ra một đoá hoa tình yêu xinh đẹp.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 16, 2023, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Lộ Tư","avatar":""},{"name":"Trần Triết Viễn","avatar":""},{"name":"Mã Bá Khiên","avatar":""},{"name":"Đinh Tiếu Oánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324244);
