INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hung-long-phong-ba-phan-2', 'Hùng Long Phong Bá (Phần 2)', 'Brothers For Life (Season 2)', 'https://phimimg.com/upload/vod/20240304-1/c68dc025f5f43230b8d1bad107036e4c.jpg', 'https://phimimg.com/upload/vod/20240304-1/502aa1fb2315eaaaa9717919d48691b7.jpg', '<p>Hùng Long Phong Bá” xoay quanh hành trình rời quê lên thành phố với hi vọng đổi đời bộ tứ Hùng (Tùng Min), Long (Steven Nguyễn), Phong (Võ Đình Hiếu), Bá (Trầm Minh Hoàng). Những tưởng 4 chàng trai trẻ khả năng “đem tiền về cho mẹ” từ những công việc đàng hoàng, lương thiện nhưng không ngờ tất cả đều bị cuốn vào vòng xoáy tranh quyền, đoạt vị của thế giới ngầm, để rồi đánh mất chính mình cùng tình anh em bao lâu gắn bó.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 30, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Tùng Min","avatar":""},{"name":"Steven Nguyễn","avatar":""},{"name":"Trầm Minh Hoàng","avatar":""},{"name":"Võ Đình Hiếu","avatar":""},{"name":"NSƯT Công Ninh","avatar":""},{"name":"Tiểu Bảo Quốc","avatar":""},{"name":"Quách Ngọc Tuyên","avatar":""},{"name":"Thanh Hoa","avatar":""},{"name":"Phan Ngân","avatar":""},{"name":"Vũ Ngọc Anh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324244);
