INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-an-ba-van-dam', 'Trường An Ba Vạn Dặm', 'Chang''an', 'https://phimimg.com/upload/vod/20260213-1/91972505b9272d258ade034553248dcf.jpg', 'https://phimimg.com/upload/vod/20260213-1/2f0bd194c4789bc8d9c561063816ad74.jpg', '<p>Lấy bối cảnh Trung Quốc thời nhà Đường, vài năm sau khi Loạn An Sử do An Lộc Sơn đứng đầu nổ ra. Đồng Quan bại trận, Cao Thích buộc phải rút quân trốn chạy khiến cho Trường An rơi vào thế khó, vua Đường Huyền Tông rời bỏ kinh đô. Trong bối cảnh lịch sử đầy khắc nghiệt đó, tình bạn giữa Cao Thích và Lý Bạch trở thành một giai thoại đáng để ngưỡng mộ và ca ngợi.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Tianxiang","avatar":""},{"name":"Ling Zhenhe","avatar":""},{"name":"Junquan Wu","avatar":""},{"name":"Xuan Xiaoming","avatar":""},{"name":"Lu Lifeng","avatar":""},{"name":"Sun Lulu","avatar":""},{"name":"Liu Xiaoyu","avatar":""},{"name":"Lu Xiran","avatar":""},{"name":"Li Shimeng","avatar":""},{"name":"Hu Yajie","avatar":""},{"name":"Ba He","avatar":""},{"name":"Xu Jiaqi","avatar":""},{"name":"Qiu Qiu","avatar":""},{"name":"Shang Hong","avatar":""},{"name":"Chen Zhe","avatar":""},{"name":"Shuiyu Tang","avatar":""},{"name":"Jiang Qiuzai","avatar":""},{"name":"Li Haojia","avatar":""},{"name":"Tom Fu","avatar":""},{"name":"Yan Yansheng","avatar":""},{"name":"Fan Zhechen","avatar":""},{"name":"Cai Zhuangzhu","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Chang An","장안삼만리","장안 삼만리","Chang''an","长安三万里"]', 178