INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-1', 'Chiến Binh 1%', 'One-Percenter', 'https://phimimg.com/upload/vod/20260210-1/5e05e4501e7f9da41aae2df32fac56fe.jpg', 'https://phimimg.com/upload/vod/20260210-1/c5d1f7a749a8b17285f33afb3457ac63.jpg', '<p>Sau khi lối đánh võ thuật nhanh như chớp theo phong cách samurai khiến các nhà làm phim quay lưng lại với anh, một ngôi sao hành động huyền thoại đã tự mình thực hiện bộ phim – trên lãnh địa tranh giành của các băng đảng yakuza, bao gồm cả sát thủ võ thuật nguy hiểm nhất Nhật Bản.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Tak Sakaguchi","avatar":""},{"name":"Kohei Fukuyama","avatar":""},{"name":"Kanon Narumi","avatar":""},{"name":"Rumika Fukuda","avatar":""},{"name":"Sho Aoyagi","avatar":""},{"name":"Norihisa Hiranuma","avatar":""},{"name":"Togo Ishii","avatar":""},{"name":"Taro Suruga","avatar":""},{"name":"Keisuke Horibe","avatar":""},{"name":"Oji Hiroi","avatar":""},{"name":"Itsuji Itao","avatar":""},{"name":"Kenjirou Ishimaru","avatar":""},{"name":"Kai Asakura","avatar":""},{"name":"Shoji Maruyama","avatar":""},{"name":"Yoshitaka Inagawa","avatar":""},{"name":"Masanori Mimoto","avatar":""},{"name":"Yuki Ashida","avatar":""},{"name":"Ar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["One-Percent Warrior","One Percenter","1%er"]', 1784690324244);
