INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-bat-nghi-2023', 'Lưỡng Bất Nghi', 'The Trust', 'https://phimimg.com/upload/vod/20260211-1/b5943cd753fa8f8a4ceebfb3db20c0dd.jpg', 'https://phimimg.com/upload/vod/20260211-1/facaa55f0af55a516e023ff6d1f74d67.jpg', '<p>&quot;Lưỡng bất nghi&quot; xoay quanh câu chuyện của Hoàng đế Diệp Cẩm Vân (Trương Hạo Duy thủ vai) và Hoàng hậu Từ Ngọc (Tống Nghiên Phi).

Hoàng hậu Từ Ngọc vốn có xuất thân con nhà quan võ, nàng không giỏi cầm kỳ thi họa nhưng tài văn thao võ lược thì không thua kém gì đấng nam nhi. Trong khi đó, Hoàng đế Diệp Cẩm Vân lại là người hay văn dở võ, trọng văn hơn võ.

Bởi vì Từ gia thống lĩnh quân lính ở biên cương, Diệp Cẩm Vân lo sợ Từ gia tạo phản, vì vậy cuộc hôn nhân của họ chỉ vì mục đích chính trị. Không có tình yêu, lại có quá nhiều khác biệt trong tính cách và sở trường, vậy nên từ khi Từ Ngọc bước chân vào hậu cung, nàng đã bị phu quân ghẻ lạnh.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 13, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Nghiên Phi","avatar":""},{"name":"Trương Hạo Duy","avatar":""},{"name":"Mã Lật","avatar":""},{"name":"Tào Tuấn Tường","avatar":""},{"name":"Vu Ba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["En Ai Liang Bu Yi","Ēn Ài Liǎng Bù Yí","两不疑","The Trust","No Doubt About Love","No Doubt in Us","恩爱两不疑"]', 1784690324244);
