INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luong-bat-nghi-2023', 'Lưỡng Bất Nghi', 'The Trust', 'lưỡng bất nghi the trust tống nghiên phi trương hạo duy mã lật tào tuấn tường vu ba en ai liang bu yi ēn ài liǎng bù yí 两不疑 the trust no doubt about love no doubt in us 恩爱两不疑', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-nguyet-tan-minh', 'Trường Nguyệt Tẫn Minh', 'Till The End Of The Moon', 'https://phimimg.com/upload/vod/20260210-1/6cf8eccf6a39cc3270cbb183903cb924.jpg', 'https://phimimg.com/upload/vod/20260210-1/bcc3b748fe77dec755aca4c04713c678.jpg', '<p>Tam giới dưới sự thống trị tàn bạo của ma thần Đạm Đài Tẫn, chúng linh lầm than. Để cứu lấy chúng sinh, Lê Tô Tô – con gái của Hành Dương tông chưởng môn, đã quyết định thực hiện một nhiệm vụ vô cùng nguy hiểm, quay trở lại thời điểm 500 năm trước ngăn cản Đạm Đài Tẫn trước khi hắn bị tà cốt trong người xâm chiếm hoàn toàn trở thành ma thần. Tại đây, Lê Tô Tô hoá thân thành Diệp gia tiểu thư – Diệp Tịch Vụ. Không ngờ số phận trêu đùa, Đạm Đài Tẫn lại chính là trượng phu trên danh nghĩa của Diệp Tịch Vụ, sau nhiều biến cố, hai người dần dần nảy sinh tình cảm. Sau cùng, Lê Tô Tô đã lấy thân chứng đạo, thay đổi cục diện vận mệnh của Đạm Đài Tẫn và cả tam giới.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 23, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"La Vân Hi","avatar":""},{"name":"Bạch Lộc","avatar":""},{"name":"Đặng Vi","avatar":""},{"name":"Trần Đô Linh","avatar":""},{"name":"Cảnh Nghiệp Đình","avatar":""},{"name":"Tôn Trân Ni","avatar":""},{"name":"Vu Ba","avatar":""},{"name":"Hoàng Hinh Dao","avatar":""},{"name":"Trịnh Quốc Lâm","avatar":""},{"name":"Li Phải Ân","avatar":""},{"name":"Hồ Ý Lâm","avatar":""},{"name":"Tiêu Trọng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad35638