INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-nguyet-tan-minh', 'Trường Nguyệt Tẫn Minh', 'Till The End Of The Moon', 'trường nguyệt tẫn minh till the end of the moon la vân hi bạch lộc đặng vi trần đô linh cảnh nghiệp đình tôn trân ni vu ba hoàng hinh dao trịnh quốc lâm li phải ân hồ ý lâm tiêu trọng 长月烬明·月照千峰 月照千峰为一人 长月无烬 黑月光拿稳be剧本 碧城诀 jusqu''à ce que la lune nous sépare светлый пепел луны 长月烬明', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giot-ruou-than-thanh-les-gouttes-de-dieu-phan-1', 'Giọt Rượu Thần Thánh (Les Gouttes de Dieu) (Phần 1)', 'Drops Of God (Season 1)', 'https://phimimg.com/upload/vod/20260209-1/bfee63e7cbb90ca6defbc0341d6783ee.jpg', 'https://phimimg.com/upload/vod/20260209-1/26abe33238e04aba484497ec7a6e8988.jpg', '<p>Trong khi thế giới rượu vang tiếc thương cái chết của Alexandre Léger, Camille - cô con gái bị ghẻ lạnh của ông biết rằng bộ sưu tập đặc biệt của ông giờ là của cô. Nhưng trước khi đòi được quyền thừa kế của mình, Camille phải vượt qua Issei, người mà Alexandre bảo trợ, trong một cuộc thi về giác quan của họ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 23, 2023, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Fleur Geffrier","avatar":""},{"name":"Tomohisa Yamashita","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["神之水滴","ღვინის წვეთები","ღვთის წვეთები","טיפות של אלוהים","Kami no Shizuku/Drops of God","Kami no Shizuku","Les Gouttes de Dieu"]', 1784690324244);
