INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nu-binh-thuong', 'Nam Nữ Bình Thường', 'In Our Prime', 'https://phimimg.com/upload/vod/20260208-1/dd394342cfed7e1bce4fe2d2d832352e.jpg', 'https://phimimg.com/upload/vod/20260208-1/f0df5f2052c81f86d90e9fc266602fc6.jpg', '<p>Bộ phim xoay quanh câu chuyện của Lý Nhất Điềm, một cô gái đang nỗ lực bám trụ và lập nghiệp nơi thành thị đại lộ. Tác phẩm tái hiện chân thực thực trạng cuộc sống của thế hệ trẻ, tập trung vào những con người bình thường đang dốc sức mưu sinh trong xã hội đương đại. Đó là hành trình đầy biến động: từ những lý tưởng rực rỡ đến nỗi bất lực trước thực tại, rồi trải qua nỗi đau để tái sinh và tiếp tục nỗ lực phấn đấu.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Lộc","avatar":""},{"name":"Quách Đào","avatar":""},{"name":"Trương Quốc Lợi","avatar":""},{"name":"Đoạn Bác Văn","avatar":""},{"name":"Lục Tư Vũ","avatar":""},{"name":"Tiêu Hạo Tĩnh","avatar":""},{"name":"Vương Gia Gia","avatar":""},{"name":"Ngô Ngọc Phương","avatar":""},{"name":"Trần Kiến Bình","avatar":""},{"name":"Hoàng Lôi","avatar":""},{"name":"Ngưu Lệ","avatar":""},{"name":"Bao Bối Nhĩ","avatar":""},{"name":"Vương Đại Lục","avatar":""},{"name":"Trương Diệu","avatar":""},{"name":"Lý Thiện","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["风华正茂的我们","普通男女"]', 1784690324244);
