INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nam-nu-binh-thuong', 'Nam Nữ Bình Thường', 'In Our Prime', 'nam nữ bình thường in our prime hoàng lộc quách đào trương quốc lợi đoạn bác văn lục tư vũ tiêu hạo tĩnh vương gia gia ngô ngọc phương trần kiến bình hoàng lôi ngưu lệ bao bối nhĩ vương đại lục trương diệu lý thiện 风华正茂的我们 普通男女', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-swat-bao-den', 'Đội SWAT Báo Đen', 'Panther SWAT', 'https://phimimg.com/upload/vod/20260207-1/31f7418a383a36a254185be62a2f3f31.jpg', 'https://phimimg.com/upload/vod/20260207-1/ccb4e54f41cfd8e2699cb15c7c33a6d6.jpg', '<p>Vụ nổ dữ dội phá vỡ sự yên tĩnh của ngân hàng, một nhóm tay súng lái xe với số tiền bị đánh cắp và cảnh sát nghe tin, đuổi theo trên đường, nổ súng ác liệt, chiếc xe bị lật và bốc cháy, còn lại đám giang hồ sau khi bỏ xe, cuống cuồng tẩu thoát. Đội SWAT tinh nhuệ đã nhận được cảnh báo - Đội đặc nhiệm Báo Đen đã vội vã đến hiện trường vụ việc; mặt khác, thành viên đội SWAT bị cưỡng chế Giang Diểu biết rằng kẻ chủ mưu đằng sau những tên cướp Hóa ra là kẻ giết người. giết anh trai mình cũng là cảnh sát.Sau khi khuất phục được xã hội đen, Giang Diểu kiên quyết tìm đến thành trì ẩn giấu của kẻ chủ mưu đứng sau xã hội đen...</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Linh Tùng","avatar":""},{"name":"Trương Chỉ Nguyên","avatar":""},{"name":"Cao Lượng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hei Bao Te Jing Dui","黑豹特警队"]', 1784690324244);
