INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luat-su-lincoln-phan-2', 'Luật Sư Lincoln (Phần 2)', 'The Lincoln Lawyer (Season 2)', 'luật sư lincoln (phần 2) the lincoln lawyer (season 2) manuel garcia-rulfo becki newton angus sampson jazz raycole адвокат на лінкольні the lincoln lawyer', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-voi-toi-anh-ay-la-nguoi-nguy-hiem', 'Đối Với Tôi, Anh Ấy Là Người Nguy Hiểm', 'My Lethal Man', 'https://phimimg.com/upload/vod/20260206-1/78cc3763f1adf386fdfa10dbe00008d0.jpg', 'https://phimimg.com/upload/vod/20260206-1/06d0841a9052bbe3370c84e68a142dea.jpg', '<p>Một vụ án bắt cóc ly kỳ đã khiến Thẩm Mạn Ninh vô tình gặp được song trùng của mình là Trang Tâm Nghiên, và cái chết chóng vánh của Tâm Nghiên đã khiến Nghiêm Tinh Trình quyền lực và bí ẩn dùng danh nghĩa “vị hôn phu” buộc Thẩm Mạn Ninh sống với thân phận “song trùng”. Thẩm Mạn Ninh bị Nghiêm Tinh Trình nhấn chìm và dẫn vào vòng xoáy biến động của gia đình họ Trang, cả hai đi từ thù địch sinh tử đến tay trong tay từng bước, vượt qua mọi khó khăn và cuối cùng ổn định lại đại lý sắp sụp đổ . Nghiêm Tinh Trình cuối cùng cũng tìm ra sự thật đáng kinh ngạc về quá khứ bí mật 17 năm trước... Cuối cùng, sự thật về vụ án chưa được giải quyết 17 năm trước được đưa ra ánh sáng, và cả hai nhận ra sự ấm áp của tình yêu và gia đình đích thực. Nghiêm Tinh Trình và Thẩm Mạn Ninh chung tay, bắt đầu một cuộc sống mới với tình yêu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mộ Chi","avatar":""},{"name":"Phạm Chí Tân","avatar":""},{"name":"Lý Nhất Chân","avatar":""},{"name":"Lý Tân Nhiên","avatar":""},{"name":"Vương Xử Đông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324244);
