INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trai-tim-rung-dong', 'Trái Tim Rung Động', 'Skip A Beat', 'trái tim rung động skip a beat hạ duệ tiên la chính vincent cao ân kỳ quách gia nam chu cẩn đồng tiêu ruồi lỗ kháng ninh lý á hỷ chân nhi skip a beat trái tim rung động 心跳', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-muon-di-nguoc-chieu-gio', 'Tôi Muốn Đi Ngược Chiều Gió', 'Rising With The Wind', 'https://phimimg.com/upload/vod/20260206-1/e406652e3c29cc6378773236a2b62fee.jpg', 'https://phimimg.com/upload/vod/20260206-1/516d52ac64eacffd8ccd6756ea6b60c7.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết cùng tên Vị Tại. Kể câu chuyện về sự hồi sinh của một thương hiệu quốc gia dưới tác động của nền kinh tế thương mại điện tử Từ Tư (Cung Tuấn thủ vai), một nhà đầu tư từ công ty ngân hàng đầu tư ở Hong Kong chuyển sang công ty đầu tư nội địa, gặp gỡ Giang Hồ (Chung Sở Hi thủ vai), con gái độc nhất của Chủ tịch tập đoàn thời trang quốc gia. Hai người do có quan điểm kinh doanh khác nhau nên không hòa hợp. Doanh nghiệp của cha Giang Hồ đột nhiên phá sản, cô gái từ một người giàu có trở thành một người khốn khổ. Trong khi đó, Từ Tư luôn quan tâm đến thương hiệu giày cao cấp &quot;Đằng Nhạc&quot; mà cha của Giang Hồ đã xây dựng, khiến cô quyết định làm mọi cách để bảo vệ &quot;Đằng Nhạc&quot;. Sau nhiều vòng đàm phán, cuối cùng Từ Tư và Giang Hồ có thể làm mới &quot;Đằng Nhạc&quot; hay không, câu chuyện này sẽ quyết định số phận của họ...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cung Tuấn","avatar":""},{"name":"Chung Sở Hy","avatar":""},{"name":"Ngô Tuyên Nghi","avatar":""},{"name":"Cao Chí Đình","avatar":""},{"name":"Ngụy Triết Minh","avatar":""},{"name":"Trương Thần Quang","avatar":""},{"name":"Ôn Tranh Vanh","avatar":""},{"name":"Lưu Bội Kỳ","avatar":""},{"name":"Cao Thự Quang","avatar":""},{"name":"Vệ Chiêm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我要逆風去","I Want To Go Against the Wind","我要逆风去"]', 1784690324244);
