INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-mot-doi-xa-hoa', 'Để Một Đời Xa Hoa', 'Liar', 'https://phimimg.com/upload/vod/20260203-1/bfaa22a7050a9f9387ffe737b98980bf.jpg', 'https://phimimg.com/upload/vod/20260203-1/dece43b860d6bc0f660e217105e7abc4.jpg', '<p>Simala là một phụ nữ xinh đẹp. Nhiều người cho rằng cô ấy trông giống như một quý cô giàu có. Nhưng thật ra đó là sự nhập vai của cô ấy với mục tiêu lừa đảo được một người đàn ông giàu có. Nhiều người nổi tiếng giàu có quan tâm đến Simala. Nhưng người duy nhất cô phải lòng là Varodom, một chàng trai lôi cuốn với vẻ ngoài triệu phú. Chuyện gì sẽ xảy ra sau khi cả hai đều biết chuyện của mình?</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 16, 2023, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Karnklao Duaysienklao","avatar":""},{"name":"Warit Sirisantana","avatar":""},{"name":"Ponlawit Ketprapakorn","avatar":""},{"name":"Sopitnapa Chumpanee","avatar":""},{"name":"Tanawat Hudchaleelaha","avatar":""},{"name":"Santisuk Promsiri","avatar":""},{"name":"Nataya Chanrung","avatar":""},{"name":"Aanan Boonnak","avatar":""},{"name":"Chutima Naiyana","avatar":""},{"name":"Kalaya Lerdkasemsap","avatar":""},{"name":"Sukol Sasijulaka","avatar":""},{"name":"Nattapol Diloknawarit","avatar":""},{"name":"Pamela Bowden","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["荷叶屋顶","Dreams in the Dust","Langkha Bai Bua","Lotus Leaf Roof","หลังคาใบบัว"]', 1784690324244);
