INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-diet-vong-hametsu-no-oukoku', 'Đế Chế Diệt Vong (Hametsu no Oukoku)', 'The Kingdoms Of Ruin', 'https://phimimg.com/upload/vod/20260203-1/52db28f620012aa1bab045d9c31bc512.jpg', 'https://phimimg.com/upload/vod/20260203-1/c2b352ab0b2d1449d32c7f97dcdb8e9d.jpg', '<p>Trong suốt hàng thế kỷ, nhân loại phát triển nhờ vào sức mạnh của phép thuật, một món quà từ những phù thủy để giúp đỡ nhân loại. Nhưng thời đại đã thay đổi. Sự mở rộng công nghệ Gear đã làm cả phép thuật lẫn phù thủy trở nên lỗi thời. Để giải phóng nhân loại khỏi đại dịch của phép thuật, Đế chế Redia mạnh mẽ đã bắt đầu một cuộc săn lùng tàn nhẫn để tiêu diệt tất cả các phù thủy. Adonis chỉ là một cậu bé khi cuộc săn lùng bắt đầu, học việc dưới sự hướng dẫn của một người phù thủy mà cậu yêu quý, tuy nhiên khi người đó mất mạng dưới tay Đế chế, Adonis đã thề quyết trả thù. Bằng sức mạnh của một pháp sư quyết liệt này, máu sẽ rơi!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaito Ishikawa","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Ryoko Shiraishi","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Hikaru Tono","avatar":""},{"name":"Kisho Taniyama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324244);
