INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-thu-cuoc-doi-2-phan-2-halloween-dam-mau-quyet-chien-tokyo-revengers-live-action-movie', 'Phục Thù Cuộc Đời 2 (Phần 2: Halloween Đẫm Máu - Quyết Chiến) (Tokyo Revengers Live Action Movie)', 'Tokyo Revengers 2 Part 2: Bloody Halloween - Final Battle', 'https://phimimg.com/upload/vod/20260118-1/ea1081cd4d1a43b63296c2830eab92cb.jpg', 'https://phimimg.com/upload/vod/20260118-1/f485a32cc46498bed06199759e61d891.jpg', '<p>Vào thời điểm này tại quá khứ, Toman đang phải đối đầu với băng nhóm nổi loạn tên Valhalla - Thiên sứ không đầu. Giờ hẹn đã điểm, 2 băng đối đầu nhau với sự chứng kiến của những băng đảng máu mặt trong giới giang hồ. Tuy nhiên, án mạng đã xảy ra, sự việc vượt sức tưởng tượng khiến Mikey hắc hóa và nguy cơ có thêm người chết càng cao. Takemichi cảm thấy mọi việc đang đi theo hướng mà Kisaki đã sắp đặt. Cậu quyết tâm vùng dậy ngăn chặn âm mưu xấu xa của Kisaki, để bảo vệ Hina cũng như Toman trong tương lai sắp tới...</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takumi Kitamura","avatar":""},{"name":"Ryo Yoshizawa","avatar":""},{"name":"Yuki Yamada","avatar":""},{"name":"Nijiro Murakami","avatar":""},{"name":"Kento Nagayama","avatar":""},{"name":"Mahiro Takasugi","avatar":""},{"name":"Mio Imada","avatar":""},{"name":"Hiroya Shimizu","avatar":""},{"name":"Shotaro Mamiya","avatar":""},{"name":"Yosuke Sugino","avatar":""},{"name":"Gordon Maeda","avatar":""},{"name":"Taketo Tanaka","avatar":""},{"name":"Kazuki Miki","avatar":""},{"name":"Shuhei Umeda","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["東京リベンジャーズ2 血のハロウィン編 決戦","โตเกียว รีเวนเจอร์ส 2.2","โตเกียว รีเวนเจอร์ส: ฮาโลวีนสีเลือด - ศึกตัดสิน","Tokyo Revengers 2: Bloody Halloween - Decisive Battle","东京复仇者2 血腥万圣节篇 -决战-","東京リベンジャーズ2 血のハロウィン編 -決戦-"]', 1784690324244);
