INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('frieren-phap-su-tien-tang-phan-1', 'Frieren: Pháp Sư Tiễn Táng (Phần 1)', 'Frieren: Beyond Journey''s End (Season 1)', 'https://phimimg.com/upload/vod/20250528-1/f3b84ccdf8c4fb61aa247a54b27018d1.jpg', 'https://phimimg.com/upload/vod/20260118-1/f14ad17b956c80a59d16a58268d34059.jpg', '<p>Sau một thập kỷ phiêu lưu, Frieren cùng tổ đội của dũng sĩ Himmel đã đánh bại Ma vương và mang lại hòa bình cho thế giới. Thế rồi cô ấy, một Elf với thọ mệnh hơn cả ngàn năm tuổi, lập lời hứa sẽ tái ngộ cùng nhóm Himmel rồi lên đường đi phiêu lưu một mình. 50 năm sau, Frieren đến thăm Himmel, nhưng lúc này anh ta đã già và chỉ còn lại một chút thời gian ngắn ngủi. Chứng kiến cái chết của Himmel, Frieren hối hận vì đã không &quot;tìm hiểu nhiều hơn về con người&quot;, và thế là một chuyến phiêu lưu mới của cô với mục đích trên đã bắt đầu. Trên chuyến phiêu lưu này, cô đã gặp gỡ rất nhiều người và trải qua rất nhiều sự kiện.</p>', 'Hoàn Tất (28/28)', 28, 'hoathinh', 'completed', 16, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Youji Ueda","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Atsuko Tanaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709