INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-kinh-di-my-phan-12-delicate', 'Truyện Kinh Dị Mỹ (Phần 12) (Delicate)', 'American Horror Story (Season 12)', 'truyện kinh dị mỹ (phần 12) (delicate) american horror story (season 12) emma roberts matt czuchry kim kardashian annabelle dexter-jones michaela jaé rodriguez denis o''hare cara delevingne julie white maaz ali história de horror americana uma história de horror americana 美恐 american horror story - die dunkle seite in dir american horror story: la casa del crimen סיפור אימה אמריקאי アメリカン・ホラー・ストーリー 아메리칸 호러 스토리 американская история ужасов американська історія жахів american horror story: freak show ahs hotel american horror story: hotel ahs american horror story: murder house american horror story: asylum american horror story: coven american horror story: roanoke american horror story: cult american horror story: apocalypse american horror story: 1984 american horror story: double feature american horror story: red tide american horror story: death valley american horror story: nyc american horror story: delicate american horror story', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tong-thieu-nien-chi-2', 'Đại Tống Thiếu Niên Chí 2', 'Young Blood 2', 'https://phimimg.com/upload/vod/20240309-1/c16fcbfdef9d1f6e2a7da0096c505f31.jpg', 'https://phimimg.com/upload/vod/20240309-1/d87d52f980b047c568d45a0ee0947e2c.jpg', '<p>Phim lấy bối cảnh chiến tranh giữa Bắc Tống và Tây Hạ thời Khánh Lịch, nội dung kể về một nhóm thiếu niên cùng bắt tay nhau để bảo vệ an nguy của Bắc Tống. Bắc Tống tuy bên ngoài nhìn có vể phồn hoa yên bình nhưng thực chất bên trong lại vô cùng phức tạp khi ẩn chứa những đấu đá ngầm dữ dội. Trong thành Biện kinh, một mật thám ngầm với mục đích chia cắt chính quyền vẫn luôn ẩn nấp, thậm chí kẻ này còn bí mật điều tra về quân sự và chính trị của Đại Tống.Đối mặt với tình hình này, một nhóm thiếu niên mật thám đã được ra đời, họ được đào tạo nghiêm ngặt nhằm bảo vệ cho Bắc Tống. Mặc dù, mỗi người đều có cá tính riêng nhưng sau khi cùng nhau trải qua nhiều gian truân trắc trở, nhóm thiếu niên dần hiểu nhau hơn và cùng nhau đoàn kết một lòng để bảo vệ giang sơn. Sang đến phần hai, sau thanh thiếu niên ấy lại hội tụ một lần sau ba năm, từ đó dẫn đến một loạt các câu chuyện phá án dở khóc dở cười.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tân Thành","avatar":""},{"name":"Châu Vũ Đồng","avatar":""},{"name":"Trịnh Vĩ","avatar":""},{"name":"Vương Hựu Thạc","avatar":""},{"name":"Hòa Hạo Thần","avatar":""},{"name":"Tô Hiểu Đồng","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324244);
