INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-tac-phan-1', 'Không Tặc (Phần 1)', 'Hijack (Season 1)', 'https://phimimg.com/upload/vod/20260117-1/dc821702cb9864570be51f984dbdc45e.jpg', 'https://phimimg.com/upload/vod/20260117-1/26e75bfd8f6000b6bf257285283e4730.jpg', '<p>Khi Chuyến bay KA29 bị không tặc trong chuyến hành trình kéo dài bảy giờ từ Dubai đến London, Sam Nelson - một nhà đàm phán kinh doanh tài ba - cố gắng sử dụng các kỹ năng nghề nghiệp của mình để cứu mọi người trên máy bay. Liệu chiến lược rủi ro cao này có khiến anh thất bại?</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Idris Elba","avatar":""},{"name":"Christine Adams","avatar":""},{"name":"Albrecht Schuch","avatar":""},{"name":"Christian Näthe","avatar":""},{"name":"Clare-Hope Ashitey","avatar":""},{"name":"Lisa Vicari","avatar":""},{"name":"Dejan Bućin","avatar":""},{"name":"Karima McAdams","avatar":""},{"name":"Jasmine Bayes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Sequestro no Ar","劫机七小时","Únos letadla","Secuestro en el aire","Kingdom","H/jack","Αεροπειρατεία","高空歷劫 7 小時","Az eltérített járat","חטיפה","Hijack - Sette ore in alta quota","하이재킹","Secuestro aéreo","H/JACK","W powietrzu","Deturnarea","Угон самолёта","Unesený let","劫機七小時","Захоплений рейс","Hijack"]', 1784690324244);
