INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ta-co-mot-con-ma', 'Nhà Ta Có Một Con Ma', 'We Have a Ghost', 'https://phimimg.com/upload/vod/20260112-1/58962acb38fde254e13ceb5bddf27a54.jpg', 'https://phimimg.com/upload/vod/20260112-1/dc7aa5e802e1ef1490accc98d9988278.jpg', '<p>Sau khi Kevin tìm thấy một hồn ma tên Ernest đang ám ngôi nhà mới của anh, anh trở thành nhân vật nổi bật trên mạng xã hội chỉ sau một đêm. Nhưng khi Kevin và Ernest đi điều tra bí ẩn về quá khứ của Ernest, họ trở thành mục tiêu của CIA.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Harbour","avatar":""},{"name":"Jahi Di''Allo Winston","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Erica Ash","avatar":""},{"name":"Niles Fitch","avatar":""},{"name":"Isabella Russo","avatar":""},{"name":"Tig Notaro","avatar":""},{"name":"Tom Bower","avatar":""},{"name":"Sean Boyd","avatar":""},{"name":"Nicholas X. Parsons","avatar":""},{"name":"Steve Coulter","avatar":""},{"name":"Scott A. Martin","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Peggy Walton-Walker","avatar":""},{"name":"Sherri Eakin","avatar":""},{"name":"Faith Ford","avatar":""},{"name":"Yosh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Ernest","บ้านนี้มีผีป่วน","Mamy tu ducha","Fantasma e CIA","Tenemos un fantasma","Imamo duha","Szellem van a házunkban","Avem o fantomă","Un fantasma in casa","屋根裏のアーネスト","У нас привидение!","Имамо духа","У нас є привид","Un fantasma anda suelto por casa","Meşhur Hayalet Ernest","Nhà Ta Có Một Con Ma","في بيتنا شبح","Meillä asuu aave","我们家有鬼","我家有鬼","We Have a Ghost"]', 1784690324245);
