INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vat-than-thoai', 'Sinh Vật Thần Thoại', 'Chupa', 'https://phimimg.com/upload/vod/20260112-1/dac86e00caaabd26073a618dfbd9be5a.jpg', 'https://phimimg.com/upload/vod/20260112-1/f218ab07ee03481adbe5928149a83beb.jpg', '<p>Khi đến thăm gia đình ở Mexico, một cậu bé cô đơn kết bạn với một sinh vật thần thoại ẩn náu trong trang trại của ông cậu rồi dấn thân vào cuộc phiêu lưu để đời.</p>', 'Full', 1, 'single', 'completed', 24, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Mexico', 0, '[{"name":"Evan Whitten","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Ashley Ciarra","avatar":""},{"name":"Julio Cesar Cedillo","avatar":""},{"name":"Alex Knight","avatar":""},{"name":"Nickolas Verdugo","avatar":""},{"name":"Adriana Paz","avatar":""},{"name":"Gerardo Taracena","avatar":""},{"name":"Michael Kostroff","avatar":""},{"name":"Krystin Goodwin","avatar":""},{"name":"Finnegan George","avatar":""},{"name":"Greg Facio","avatar":""},{"name":"Hyrum Colbert","avatar":""},{"name":"Tyler Dochstader","avatar":""},{"name":"Tyson Hill","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Meu Amigo Lutcha","アレックスとチュパ","Чупа","我的吸血怪好友","Chupa"]', 1784690324245);
