INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sinh-vat-than-thoai', 'Sinh Vật Thần Thoại', 'Chupa', 'sinh vật thần thoại chupa evan whitten demián bichir christian slater ashley ciarra julio cesar cedillo alex knight nickolas verdugo adriana paz gerardo taracena michael kostroff krystin goodwin finnegan george greg facio hyrum colbert tyler dochstader tyson hill m meu amigo lutcha アレックスとチュパ чупа 我的吸血怪好友 chupa', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dia-nguc-cuc-lac-phan-1', 'Địa Ngục Cực Lạc (Phần 1)', 'Hell''s Paradise (Season 1)', 'https://phimimg.com/upload/vod/20260112-1/38a238b93eb2f131f99d4ef044cdbd71.jpg', 'https://phimimg.com/upload/vod/20260112-1/8ca1564d9ad46b06d893d7c63a46d25b.jpg', '<p>Gabimaru Vô Hồn, vốn là một ninja sát thủ, bị nhiều người khiếp sợ như một kẻ máu lạnh. Mặc dù đã bị kết án tử hình nhưng không có ai đủ khả năng để giết chết cậu ta. Sau đó, nữ đao phủ nhà Asaemon đến gặp Gabimaruvà thắp lên chút hi vọng mong manh cho cậu ta với lời đề nghị vô cùng bất ngờ, rằng nếu muốn gặp lại người vợ thân thương của mình, Gabimaru sẽ phải bắt đầu một cuộc hành trình dưới sự giám sát của Mạc Phủ, tới một hòn đảo bí ẩn để tìm thứ thuốc trường sinh bất lão bất tử. Chỉ cần tìm thấy thứ đó, Gabimaru, hoặc những tên phạm nhân khát máu khác, sẽ được miễn hết tội danh và có thể bắt đầu lại một cuộc sống mới. Một cuộc phiêu lưu siêu kịch tính đã bắt đầu!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Chiaki Kobayashi","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Ryota Suzuki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hell''s Paradise: Jigokuraku","地狱乐","Jigokuraku","地獄楽"]', 1784690324245);
