INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-yamada-o-lv999', 'Yêu Yamada Ở Lv999!', 'My Love Story With Yamada-kun At Lv999', 'https://phimimg.com/upload/vod/20260111-1/db14631b154245c2ae8ee45d7c943b3c.jpg', 'https://phimimg.com/upload/vod/20260111-1/bc33150278bff9381d1da260cd06f361.jpg', '<p>Khi Akane sắp từ bỏ trò chơi game mà cô từng chơi với bạn trai thì lại gặp Yamada trong một tựa game khác cùng thể loại. Yamada trong cuộc sống ngoài đời thực có thể được coi là một &quot;huyền thoại&quot;. Vấn đề duy nhất là anh ta CHỈ quan tâm đến game thôi. Khi tình cảm của Akane dành cho cậu ngày càng lớn, liệu Yamada có tập trung chơi game nữa không?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Inori Minase","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Ai Kakuma","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Nobuo Tobita","avatar":""},{"name":"Rio Tsuchiya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["与山田谈一场Lv999的恋爱","和山田进行LV.999的恋爱","Mi historia de amor con Yamada-kun en Lv999","סיפור האהבה שלי עם יאמאדה-קון ברמה 999","Yamada-kun to Lv999 no Koi wo Suru","Yamada-kun to Lv999 no Koi o Suru","Моя любовь к Ямаде девятьсот девяносто девятого уровня","Моя любовь к Ямаде 999 уровня","قصة حبي مع يامادا-كن عند المستوى 999","Loving Yamada at Lv999","山田くんとLv999の恋をする"]', 1784690324245);
