INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-quoc-ky-dam-phan-1', 'Trung Quốc Kỳ Đàm (Phần 1)', 'Yao-Chinese Folktales (Season 1)', 'https://phimimg.com/upload/vod/20260110-1/f4cdf558767f6336d00e7a0edb632102.jpg', 'https://phimimg.com/upload/vod/20260110-1/4973fd9c4b976b5518a22ea122295c31.jpg', '<p>Tuyển tập phim ngắn &quot;Trung Quốc Kỳ Đàm&quot; gồm 8 mẩu truyện dựa theo văn hoa truyền thống của Trung Quốc: &quot;Mùa hè của tiêu yêu quái&quot;, &quot;Ngỗng ngỗng ngỗng&quot;, &quot;Lâm Lâm&quot;, &quot;Xe buýt thôn quê đưa nhóc Vương và thần tiên đi mất&quot;, &quot;Tiểu Mãn&quot;, &quot;Thỏ Ngọc&quot;,&nbsp; &quot;Tiệm Tạp Hóa&quot;, &quot;Chim và cá&quot;. Những câu truyện nhìn về quá và hiện tại, hướng tới tương lai, từ nông thôn hoài niệm đến công nghệ viễn tưởng, từ cuộc sống đến suy nghĩ nhân sinh, thể hiện trí tưởng tượng kiểu Trung, chứa đựng triết lý và văn hóa của dân tộc Trung Quốc.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhong Guo Qi Tan","Yao-Chinese Folktales","中国奇谭.Yao-Chinese.Folktales","Yao Chinese Folktales","中国奇谭2","중국기담(中國奇譚)","Truyện cổ Trung Quốc","中国奇谭"]', 1784690324245);
