INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('influencer', 'Influencer', 'Influencer', 'https://phimimg.com/upload/vod/20260108-1/c65bbe696642cfe2bc16a09af727cd81.jpg', 'https://phimimg.com/upload/vod/20260108-1/86be73e8594c34001dfd8ce36f5051ce.jpg', '<p>Trong chuyến du lịch bụi một mình đầy khó khăn ở Thái Lan, Madison, một người có tầm ảnh hưởng trên mạng xã hội, gặp CW, người du lịch rất dễ dàng và cho cô thấy một lối sống phóng khoáng hơn. Nhưng sự quan tâm của CW dành cho cô dần chuyển sang hướng đen tối hơn.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cassandra Naud","avatar":""},{"name":"Emily Tennant","avatar":""},{"name":"Rory J. Saper","avatar":""},{"name":"Sara Canning","avatar":""},{"name":"Paul Spurrier","avatar":""},{"name":"Justin Sams","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Influencer"]', 1784690324245);
