INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-nguoi-va-than', 'Đại Chiến Người Và Thần', 'Adipurush', 'https://phimimg.com/upload/vod/20260109-1/4119dd3018792483e65c3e35f9571f3c.jpg', 'https://phimimg.com/upload/vod/20260109-1/f70839925c1ed8d3b49bf04359ad1457.jpg', '<p>7000 năm trước, Thái tử Raghava và Hoàng tử Sesh của thành Ayodhya, cùng với những chiến binh khỉ Vanar hùng mạnh, đã lên đường tiến về đảo quốc Lanka với mục tiêu giải cứu Janaki – thê tử của Raghava, người đã bị tên vua của đảo Lanka là Lankesh bắt cóc.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Prabhas","avatar":""},{"name":"Saif Ali Khan","avatar":""},{"name":"Kriti Sanon","avatar":""},{"name":"Sunny Singh","avatar":""},{"name":"Devdatta Nage","avatar":""},{"name":"Vatsal Sheth","avatar":""},{"name":"Siddhant Karnick","avatar":""},{"name":"Gaurrav Walia","avatar":""},{"name":"Roopesh Jadhav","avatar":""},{"name":"Manohar Pandey","avatar":""},{"name":"Trupti Toradmal","avatar":""},{"name":"Tejaswini Pandit","avatar":""},{"name":"Sonal Chauhan","avatar":""},{"name":"Lavi Pajni","avatar":""},{"name":"Asha Sharma","avatar":""},{"name":"Urvi Singh","avatar":""},{"name":"Krishna Kotian","avatar":""},{"name":"Sonali K","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Adhipurush","Aadipurush","Aadhipurush","ادی‌پوروش","اولین انسان","Adipurush","आदिपुरुष"]', 1784690324245);
