INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-chien-nguoi-va-than', 'Đại Chiến Người Và Thần', 'Adipurush', 'đại chiến người và thần adipurush prabhas saif ali khan kriti sanon sunny singh devdatta nage vatsal sheth siddhant karnick gaurrav walia roopesh jadhav manohar pandey trupti toradmal tejaswini pandit sonal chauhan lavi pajni asha sharma urvi singh krishna kotian sonali k adhipurush aadipurush aadhipurush ادی‌پوروش اولین انسان adipurush आदिपुरुष', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-di-nhan', 'Thế Giới Dị Nhân (Dị Nhân Chi Hạ)', 'I Am Nobody', 'https://phimimg.com/upload/vod/20260108-1/dcfee089da6118720eaadf9f98e88ddd.jpg', 'https://phimimg.com/upload/vod/20260108-1/3bf1aabfdb57af8240be112753f46128.jpg', '<p>Do thi thể ông nội biến mất một cách ly kỳ, chàng trai bình thường Trương Sở Lam bị cuốn vào thế giới &quot;dị nhân&quot; xa lạ, phải đối mặt với màn truy sát bất ngờ ập tới từ &quot;Toàn Tính&quot;. Cô gái thần bí Phùng Bảo Bảo đột ngột xuất hiện, Trương Sở Lam quyết tâm không che giấu dị năng nữa. Cùng với việc lần theo quá khứ của ông nội, Trương Sở Lam dần dần hòa nhập vào thế giới của dị nhân, và bí ẩn lịch sử cũng từng bước hé mở, dường như đằng sau đó ẩn chứa một bí mật động trời, còn thân thế thần bí của Phùng Bảo Bảo có lẽ chính là chìa khóa giải đáp bí ẩn. Đứng trước mối nguy lũ lượt kéo đến, các dị nhân trẻ tuổi đã tập hợp lại và xây dựng tình bạn cùng sự gắn kết sâu sắc. Trên con đường trưởng thành, mỗi người đều đang tìm kiếm lý tưởng của riêng mình, trận quyết đấu giữa ánh sáng và bóng tối sắp sửa bùng nổ...</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 13, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Peng Yuchang","avatar":""},{"name":"Hou Minghao","avatar":""},{"name":"Wang Yinglu","avatar":""},{"name":"Wen Qi","avatar":""},{"name":"Yin Fang","avatar":""},{"name":"Kevin Yan","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Shao Bing","avatar":""},{"name":"Luo Zheng","avatar":""},{"name":"Zhao Da","avatar":""},{"name":"Sun Zeyuan","avatar":""},{"name":"Duan Xiaowei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["异人","异人之下真人版","剧版一人之下","I Am Nobody 2","I Am Nobody: The Showdown Between Yin & Yang","异人之下·新篇","异人之下之决战！碧游村","异人之下之血战！唐门","စည်းအပြင်ဘက်ကလူ","I am nobody","Один из отвергнутых","Под властью нелюдей","Yi Ren Zhi Xia","The Outcast","I Am Nobody","Thế Giới Dị Nhân","异人之下"]', 1784690324245);
