INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-di-nhan', 'Thế Giới Dị Nhân (Dị Nhân Chi Hạ)', 'I Am Nobody', 'thế giới dị nhân (dị nhân chi hạ) i am nobody peng yuchang hou minghao wang yinglu wen qi yin fang kevin yan pan binlong shao bing luo zheng zhao da sun zeyuan duan xiaowei 异人 异人之下真人版 剧版一人之下 i am nobody 2 i am nobody: the showdown between yin & yang 异人之下·新篇 异人之下之决战！碧游村 异人之下之血战！唐门 စည်းအပြင်ဘက်ကလူ i am nobody один из отвергнутых под властью нелюдей yi ren zhi xia the outcast i am nobody thế giới dị nhân 异人之下', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-minh-la-lam', 'Nhà Mình Lạ Lắm', 'Odd Family', 'https://phimimg.com/upload/vod/20260105-1/bc76c09343c4b710c6808a7d1036fc7b.jpg', 'https://phimimg.com/upload/vod/20260105-1/f0d216e368f80cd516f0e52f9236017c.jpg', '<p><span style="text-wrap-mode: wrap;">Một tai nạn giao thông kinh hoàng đã cướp đi sinh mệnh của 7 người trong cùng một gia đình, chỉ duy nhất cô bé Thanh Mỹ (8 tuổi) còn sống sót. Thành, cậu của Thanh Mỹ dù cố gắng chữa chạy hết sức nhưng cô bé vẫn không nhớ ra bất kỳ chuyện gì hay bất kỳ ai. Theo lời gợi ý của bác sỹ, Kim đề nghị sẽ tạo ra một gia đình giả, để cô bé được sống trong môi trường hạnh phúc và quen thuộc giống như trước kia, với hy vọng sẽ mau chóng khôi phục trí nhớ cho cô bé với ít tổn thương nhất. Và thế là, một “tổ hợp người thân” với đầy đủ các xuất thân, tính cách được hình thành. Từ những người xa lạ, họ phải học cách chung sống hoà hợp với nhau để mang lại bầu không khí gia đình hạnh phúc cho Thanh Mỹ. Sau những bối rối và hiểu lầm ban đầu, họ xích lại gần nhau hơn, mỗi một thành viên đều có hành trình trưởng thành của riêng mình với sự giúp đỡ của những người còn lại.</span></p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Kim Xuân","avatar":""},{"name":"Trung Anh","avatar":""},{"name":"Nhan Phúc Vinh","avatar":""},{"name":"Lê Bống","avatar":""},{"name":"Samuel An","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324245);
