INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-diet-than-vuong', 'Bất Diệt Thần Vương', 'The Rich God, Bu Mie Shen Wang', 'https://phimimg.com/upload/vod/20250224-1/b7e6cd7091e97ae75df507a526fa91d1.jpg', 'https://phimimg.com/upload/vod/20250224-1/5508b313b74fba04c4b31583c37aa5f9.jpg', '<p>Vương Khả, vô tình bị kiếm thần tổ truyền đưa đến Thần Châu tinh, ông tưởng rằng sự thành công sẽ đến với mình, nhưng không ngờ rằng ông sẽ bị cuốn vào con sóng ngầm của chánh đạo và ma đạo.Tuy nhiên, ông không chùn bước, mà thậm chí biến những khó khăn thành cơ hội để phát triển. Với thiên phú và sự khôn ngoan, Vương Khả không chỉ chiến thắng trên thương trường . Ông xây dựng một đế quốc thương mại mạnh mẽ, đưa tên tuổi của mình lên đỉnh cao. Ông trở thành Bất Diệt Thần Vương.</p>', 'Hoàn Tất (19/19)', 19, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Bu Mie Shen Wang","不滅神王","不灭神王"]', 1784690324245);
