INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dua-mf-ghost-phan-1', 'Giải Đua MF Ghost (Phần 1)', 'MF Ghost (Season 1)', 'https://phimimg.com/upload/vod/20260102-1/f5e3fdb3a87a1fbb3eb8ee7c3968a4f2.jpg', 'https://phimimg.com/upload/vod/20260102-1/28fb6c24e36be78565df3971d3ccfbdd.jpg', '<p>Nhật Bản chính thức áp dụng xe điện tự lái, khiến hầu hết các động cơ chạy xăng trở nên lỗi thời vào những năm 202X. Thế nhưng, những chiếc xe tốc độ nhất đã tìm thấy &#39;đời sống mới&#39; tại MFG – một giải đua xe diễn ra ngay trên những tuyến đường cao tốc của Nhật Bản. Các tay đua từ khắp nơi trên thế giới đổ về đây để tranh giành ngôi vị quán quân.Kanata Rivington từ Anh trở về Nhật Bản để tham gia MFG — và cũng để tìm kiếm người cha của mình. Liệu anh có thể giành lấy danh hiệu vô địch và tìm ra câu trả lời cho riêng mình? Hãy thắt dây an toàn và nhấn ga đến giới hạn cuối cùng!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuma Uchida","avatar":""},{"name":"Ayane Sakura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["燃油车斗魂","MF Ghost","MF고스트","MFゴースト"]', 1784690324245);
