INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-suu-tap-nha-dau-gia-goldin-phan-1', 'Vua Sưu Tập: Nhà Đấu Giá Goldin (Phần 1)', 'King Of Collectibles: The Goldin Touch (Season 1)', 'https://phimimg.com/upload/vod/20251230-1/b65a6e7464783e4114a4d64adfdd274e.jpg', 'https://phimimg.com/upload/vod/20251230-1/6c9d9e2e8e018c738a43f0fa44382f3a.jpg', '<p>Ken Goldin cùng đội ngũ tài năng của mình dẫn dắt các hoạt động trong loạt phim này, mang đến cái nhìn cận cảnh bên trong một nhà đấu giá hàng đầu chuyên về các món đồ sưu tầm quý hiếm.</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["King of Collectibles: The Goldin Touch"]', 1784690324245);
