INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-sinh-muu-meo-xin-chi-giao', 'Tiên Sinh Mưu Mẹo Xin Chỉ Giáo', 'Trick In Love', 'https://phimimg.com/upload/vod/20251230-1/6148cecb6124f7e35634d12fe59c520d.jpg', 'https://phimimg.com/upload/vod/20251230-1/7f12cd1b82cede3c9c3c52367f8e7104.jpg', '<p>Sau một đêm say rượu, Mạc Tố Tình lên kế hoạch tiếp cận Diệp Chung Giác chỉ để phơi bày chân tướng về tai nạn xe năm xưa cướp đi mạng sống của mẹ cô. Cô muốn mượn tay Diệp Chung Giác phá hủy tập đoàn Tuyệt Thế, nhưng Tố Tình không ngờ, mọi chuyện tiến hành thuận lợi đều do vô vàn kế hoạch của Diệp Chung Giác sắp xếp. Thỏ trắng xảo quyệt Mạc Tố Tình và sói xám thật thà Diệp Chung Giác, hai người đều lên kế hoạch tiếp cận nhau, ngồi chờ người kia sa chân vào “chiếc bẫy” tình yêu. Nhưng cả hai đều không biết, trong trò chơi tình cảm này, hai người đều là con mồi, và đồng thời cũng là ánh trăng sáng và sự cứu rỗi của nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Ca Dương","avatar":""},{"name":"Từ Tử Nhân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["套路先生請指示","Tao Lu Xian Sheng Qing Zhi Shi","套路先生请指示官方","Please Instruct","套路先生请指示"]', 1784690324245);
