INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dam-huyen-thoai-3', 'Tay Đấm Huyền Thoại 3', 'Creed III', 'https://phimimg.com/upload/vod/20251230-1/aee7743e227512b671bb4c310a65f3ab.jpg', 'https://phimimg.com/upload/vod/20251230-1/a4fae6da226e38695f66b87671762c38.jpg', '<p>Tay đấm lừng danh Adonis Creed, khi gặp gỡ một người bạn cũ, nhưng cũng đồng thời là đối thủ mới của anh, Anderson Dame. Cả hai từng có một quá khứ thân thiết, mà theo lời Creed nói, Dame “giống như gia đình của anh”. Tuy nhiên, một biến cố trong quá khứ xảy ra, đẩy Creed và Dame về hai đầu chiến tuyến. Giờ đây, khi đã trưởng thành, họ gặp lại nhau trên sàn đấu, để rồi trở thành những đối thủ “không đội trời chung”.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Michael B. Jordan","avatar":""},{"name":"Tessa Thompson","avatar":""},{"name":"Jonathan Majors","avatar":""},{"name":"Phylicia Rashād","avatar":""},{"name":"Mila Davis-Kent","avatar":""},{"name":"Wood Harris","avatar":""},{"name":"José Benavidez Jr.","avatar":""},{"name":"Florian Munteanu","avatar":""},{"name":"Selenis Leyva","avatar":""},{"name":"Thaddeus J. Mixson","avatar":""},{"name":"Spence Moore II","avatar":""},{"name":"Tony Bellew","avatar":""},{"name":"Ann Najjar","avatar":""},{"name":"Jacob ''Stitch'' Duran","avatar":""},{"name":"Terence C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Creed 3","Կրիդ 3","クリード３","Крид 3","Tay Đấm Huyền Thoại 3","Rocky IX","Rocky 9 - Creed 3","Creed: 3 - No puedes escapar de tu pasado","Creed 3 - Rocky''s Legacy","Creed III"]', 1784690324245);
