INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-em-day-yeu', 'Vú Em Dạy Yêu', 'No Hard Feelings', 'https://phimimg.com/upload/vod/20240919-1/c247eb310263ba3e050ba985e07dda42.jpg', 'https://phimimg.com/upload/vod/20240919-1/3a7fca0e768b4fa934dc9fea99f32bd7.jpg', '<p>Nội dung phim kể về một cô gái lẳng lơ, sống nay đây mai đó với đủ loại công việc. Cho đến một ngày, cô nhận lời của một cặp vợ chồng trung niên là quyến rũ cậu con trai 19 tuổi của họ. Cũng từ đây, hành trình của bà cô U40 đi cò cưa trai trẻ bắt đầu với bao tình huống éo le, khó đỡ.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Andrew Barth Feldman","avatar":""},{"name":"Laura Benanti","avatar":""},{"name":"Natalie Morales","avatar":""},{"name":"Matthew Broderick","avatar":""},{"name":"Scott MacArthur","avatar":""},{"name":"Ebon Moss-Bachrach","avatar":""},{"name":"Kyle Mooney","avatar":""},{"name":"Hasan Minhaj","avatar":""},{"name":"Jordan Mendoza","avatar":""},{"name":"Amalia Yoo","avatar":""},{"name":"Alysia Joy Powell","avatar":""},{"name":"Quincy Dunn-Baker","avatar":""},{"name":"Matthew Noszka","avatar":""},{"name":"Zahn McClarnon","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Без лоши чувства","Μαθήματα Αποπλάνησης","Nieko asmeniško","Vú Em Dạy ''Yêu''","Büyü de Gel","Tudo na Boa!","Sin malos rollos","Que Horas Eu Te Pego?","珍愛硬起來","Dərin Duyğular Olmadan","不要见怪","No Hard Feelings"]', 17846