INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-em-day-yeu', 'Vú Em Dạy Yêu', 'No Hard Feelings', 'vú em dạy yêu no hard feelings jennifer lawrence andrew barth feldman laura benanti natalie morales matthew broderick scott macarthur ebon moss-bachrach kyle mooney hasan minhaj jordan mendoza amalia yoo alysia joy powell quincy dunn-baker matthew noszka zahn mcclarnon m без лоши чувства μαθήματα αποπλάνησης nieko asmeniško vú em dạy ''yêu'' büyü de gel tudo na boa! sin malos rollos que horas eu te pego? 珍愛硬起來 dərin duyğular olmadan 不要见怪 no hard feelings', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-me-cung-long-an', 'Địch Nhân Kiệt: Mê Cung Long Ẩn', 'Dragon Hidden In A Mysterious Hole', 'https://phimimg.com/upload/vod/20251226-1/3bba23338c994c78962298d750e75d70.jpg', 'https://phimimg.com/upload/vod/20251226-1/fc64099d17cbf2d88b598fcddcff5559.jpg', '<p>Khi &quot;thuyền ma&quot; tiến vào cảng Hồng Kông, ông chủ để tự bảo vệ mình mà muốn kết thúc vụ án bằng &quot;Thủy tặc loạn&quot;, nhưng Địch Nhân Kiệt lại mơ hồ cảm thấy sự tình kỳ quặc. Đại lễ sắp tới, người dân Trường An bởi vụ án này đã vô cùng hoảng sợ, hoàng hậu lệnh cho Thần Minh, người đứng đầu Đại Lý Tự, trong vòng ba ngày phải kết thúc vụ án, nhưng hắn lại đem áp lực phá án cho Địch Nhân Kiệt. Đốc Thủy Giám trưởng quan Lãnh Tế Nguyệt cũng tham gia, khi trên thuyền ma xem xét lại gặp phải người quen cũ Đoạn Ngôn. Ba người này đã cùng đi tới trung tâm tình báo Trường An để lấy thông tin. Sau khi tìm tòi nghiên cứu, hai lực lượng ngầm ở Trường An cuối cùng đã tìm thấy nơi cất giấu bí mật - Vân Quật. Đám người Địch Nhân Kiệt đi vào Cổ Lăng Vân Quật, liên tục phá cơ quan cạm bẫy, nhưng lại lâm tình thế tuyệt vọng, Địch Nhân Kiệt dựa vào việc nhận dạng tầng đất tìm được đường ra, rốt cục phá vỡ Dương mộ tìm được âm mộ của Hoài Vương cùng di tộc Đại Nguyệt nuôi dưỡng Long Ngao. Chân tướng dần dần lộ ra, đại điển sắp tới, các cổ thế lực hắc ám đang chờ cơ hội ra tay, mà Địch Nhân Kiệt đã sớm nhìn ra chân tướng mà bày ra thiên la địa võng…</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trúc Tử Kiêu","avatar":""},{"name":"Thị Huyển Như","avatar":""},{"name":"Trương Bành","avatar":""},{"name":"Mạc Thiên","avatar":""},{"name":"Bình An","avatar":""},{"name":"Lưu Kim","avatar":""},{"name":"Lý Bùi Trạch","avatar":""},{"name":"Châu Cẩm Lâm","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["龙隐迷窟","Dragon Hidden In A Mysterious Hole","Địch Nhân Kiệt: Mê Cung Long Ẩn","Detective Dee and Dragon Hidden Lair"]', 1784690324245);
