INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dich-nhan-kiet-me-cung-long-an', 'Địch Nhân Kiệt: Mê Cung Long Ẩn', 'Dragon Hidden In A Mysterious Hole', 'địch nhân kiệt: mê cung long ẩn dragon hidden in a mysterious hole trúc tử kiêu thị huyển như trương bành mạc thiên bình an lưu kim lý bùi trạch châu cẩm lâm 龙隐迷窟 dragon hidden in a mysterious hole địch nhân kiệt: mê cung long ẩn detective dee and dragon hidden lair', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-dau-lam-minh-tinh-tu-hom-nay-thien-su-tinh-ca', 'Bắt Đầu Làm Minh Tinh Từ Hôm Nay: Thiên Sứ Tình Ca', 'Re:STARS: Two Shining Stars Connect to the Future (Super Star: Love Song)', 'https://phimimg.com/upload/vod/20251225-1/9a1ad72bdd9906d3c7127341ac578012.jpg', 'https://phimimg.com/upload/vod/20251225-1/4fa5fe1ddf4a72d4ffd48b4c0cb2e87d.jpg', '<p>Bộ phim kể về em trai Tần Trạch có tài năng âm nhạc từ nhỏ, nhưng vì bỏ lỡ một cuộc thi quan trọng nên đã để lại ám ảnh tâm lý, không thể nào bước lên sân khấu ca hát. Vì muốn biến ước mơ âm nhạc của em trai thành hiện thực, chị gái là ca sĩ nổi tiếng Tần Nhã đã từ bỏ ước mơ làm diễn viên để cố gắng trở thành ca sĩ, đồng thời dùng cách “hoán đổi thân phận” để giúp em trai khắc phục chướng ngại tâm lý. Cuối cùng hai chị em đều có thể biến ước mơ của mỗi người thành hiện thực.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ma Zhengyang","avatar":""},{"name":"Chen Liyang","avatar":""},{"name":"Wen Sen","avatar":""},{"name":"Wang Xiaoqian","avatar":""},{"name":"Zhou Dong","avatar":""},{"name":"Teng Xin","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Zhu Rongrong","avatar":""},{"name":"Liangwei Hu","avatar":""},{"name":"Baomu Zhongyang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Re:STARS ~Mirai he Tsunagu Futatsu no Kiraboshi~","Re:STARS: Mirai e Tsunagu 2-tsu no Kiraboshi","今天开始做明星剧场版","今天开始做明星之天使情歌"]', 1784690324245);
