INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bat-dau-lam-minh-tinh-tu-hom-nay-thien-su-tinh-ca', 'Bắt Đầu Làm Minh Tinh Từ Hôm Nay: Thiên Sứ Tình Ca', 'Re:STARS: Two Shining Stars Connect to the Future (Super Star: Love Song)', 'bắt đầu làm minh tinh từ hôm nay: thiên sứ tình ca re:stars: two shining stars connect to the future (super star: love song) ma zhengyang chen liyang wen sen wang xiaoqian zhou dong teng xin sheng feng zhu rongrong liangwei hu baomu zhongyang re:stars ~mirai he tsunagu futatsu no kiraboshi~ re:stars: mirai e tsunagu 2-tsu no kiraboshi 今天开始做明星剧场版 今天开始做明星之天使情歌', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-lac-truyen', 'An Lạc Truyện', 'The Legend Of Anle', 'https://phimimg.com/upload/vod/20251223-1/09f4f6203a5eccdc0eadf9fb4b335f64.jpg', 'https://phimimg.com/upload/vod/20251223-1/ea25d6f9e8af4e86acd9199f14826104.jpg', '<p>Thiếu nữ Đế Tử Nguyên một thân chính khí, lòng mang thương sinh, nhưng gia tộc gặp phải biến cố nên phải lưu lạc nhân gian.

Vì không muốn vận mệnh vị bóp chặt, nàng đổi tên thành Nhậm An Lạc, chờ mong có thể dốc sức vì sự bình yên của bá tánh, đồng thời điều tra sự thật, lấy lại trong sạch cho gia tộc.

Trong quá trình đó, nàng được thái tử Hàn Diệp xem trọng, trở thành phụ tá của thái tử. Lúc này chiến tranh nổ ra, Nhậm An Lạc quyết định đi theo thái tử Hàn Diệp xuất chinh, hy vọng đổi lấy sự an cư lạc nghiệp của bá tánh. Đối mặt tình trạng địch mạnh ta yếu, Nhậm An Lạc bày mưu lập kế, mang bệnh giết địch, đoạt được thắng hiểm, giúp bá tánh nghênh đón hoà bình.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 12, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Cung Tuấn","avatar":""},{"name":"Lưu Vũ Ninh","avatar":""},{"name":"Hạ Nam","avatar":""},{"name":"Bùi Tử Thiêm","avatar":""},{"name":"Trần Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["帝皇书","The Legend of An Le","အန်းလဲ့မည်တွင် လွမ်းပုံပြင်","อันเล่อ โฉมงามพลิกชะตา","อันเล่อจ้วน","安乐传"]', 1784690324245);
