INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('an-lac-truyen', 'An Lạc Truyện', 'The Legend Of Anle', 'an lạc truyện the legend of anle địch lệ nhiệt ba cung tuấn lưu vũ ninh hạ nam bùi tử thiêm trần đào 帝皇书 the legend of an le အန်းလဲ့မည်တွင် လွမ်းပုံပြင် อันเล่อ โฉมงามพลิกชะตา อันเล่อจ้วน 安乐传', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-dau-lam-minh-tinh-tu-hom-nay-phan-2', 'Bắt Đầu Làm Minh Tinh Từ Hôm Nay (Phần 2)', '(Re:STARS) Super Star (Season 2)', 'https://phimimg.com/upload/vod/20251221-1/d8282a97b5fded783ad6d8866b38007c.jpg', 'https://phimimg.com/upload/vod/20251221-1/798034085779be4a670dc3390f4849d0.jpg', '<p>&nbsp;Sau khi giành chiến thắng trong cuộc thi ca hát, Tần Trạch được một công ty môi giới nổi tiếng trong ngành phát hiện, lúc này Tần Trạch mới nhận ra mình đã rơi vào bẫy hợp đồng, nếu không ký hợp đồng sẽ phải bồi thường rất lớn. Tần Trạch rơi vào tình thế tiến thoái lưỡng nan giữa ước mơ và hiện thực. Tần Trạch gia nhập đoàn làm phim, đây là tác phẩm lớn đầu tiên của cô sau khi cô hoàn toàn lột xác thành một diễn viên chính thức, điều này quyết định sự nghiệp diễn viên sau này của cô có thuận buồm xuôi gió hay không. Tuy nhiên, sự gia nhập của nữ diễn viên quốc tế Lulu đã mang đến cho Tần Trạch rất nhiều rắc rối, bất kể là danh tiếng hay kỹ năng diễn xuất, Lulu đều vượt trội Tần Trạch. Tuy nhiên, tất cả những điều này đều là âm mưu của giải trí Thuỵ Trì...</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Liyang","avatar":""},{"name":"Ma Zhengyang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jīn Tiān Kāi Shǐ Zuò Míng Xīng","Jintian Kaishi Zuo Mingxing","今天开始做明星","今天开始闪耀登场","Jin Tian Kai Shi Zuo Ming Xing","Jintian Wo Kaishi Zuo Mingxing","リ・スターズ","Start to be a Star Today","Super Star"]', 1784690324245);
