INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-loi-hai-chan-cao-quy', 'Cô Nàng Lợi Hại Chân Cao Quý', 'Amazing Girls', 'https://phimimg.com/upload/vod/20251220-1/82087e960dd25b842111f28b71ecf08f.jpg', 'https://phimimg.com/upload/vod/20251220-1/f7ca116f726d8020bf9dc637d89cbc1e.jpg', '<p>Bộ phim kể về câu chuyện của cô tiểu thư quý tộc, Chân Cao Quý, bị phá sản và buộc phải làm việc tại một công ty quảng cáo do áp lực cuộc sống. Tại đây, cô gặp gỡ và va chạm với tổng giám đốc Chung Ý Danh. Một tiểu thư nhà giàu sau khi du học về phát hiện gia đình bị phá sản, một nhị thiếu gia sau thời gian nhàn rỗi bỗng được giao nhiệm vụ quan trọng. Hai người bắt đầu hợp tác để biến một dự án nhỏ thành một doanh nghiệp lớn. Trong quá trình này, cả hai đều có tình cảm và bắt đầu tìm hiểu nhau. Cuộc hành trình của họ trở nên hoàn hảo, và tình yêu giữa Chung Ý Danh và Chân Cao Quý cũng dần chớm nở. Bộ phim mang đến những câu chuyện hài hước và đáng yêu về sự trưởng thành trong tình yêu và sự phát triển trong công việc. Đây là một bộ phim vui nhộn về tình cảm trong môi trường làm việc, tập trung vào sự hài hước và sự phát triển tích cực của cả nam và nữ chính.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Ý Nam","avatar":""},{"name":"Cật Mỹ Hàm","avatar":""},{"name":"Chu Gia Kỳ","avatar":""},{"name":"La Mị","avatar":""},{"name":"Chu Sảo Nhĩ","avatar":""},{"name":"Trương Hán","avatar":""},{"name":"Khưu Gia Kỳ","avatar":""},{"name":"Hoàng Du Nhiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["فتيات مذهلات","Amazing Girls","了不起的甄高贵"]', 1784690324245);
