INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('percy-jackson-va-cac-vi-than-tren-dinh-olympus-phan-1', 'Percy Jackson Và Các Vị Thần Trên Đỉnh Olympus (Phần 1)', 'Percy Jackson And The Olympians (Season 1)', 'https://phimimg.com/upload/vod/20251212-1/bbbba6b07473ccbd69b9e864eb08d976.jpg', 'https://phimimg.com/upload/vod/20251212-1/d8a8b2951574ef7f11b15baa06a69c77.jpg', '<p>Bộ phim kể về cuộc phiêu lưu của Percy Jackson, một cậu bé 12 tuổi từ New York, khi cậu phát hiện mình là con của vị thần biển Poseidon. Cùng với những người bạn thân thiết Annabeth Chase và Grover Underwood, Percy bắt đầu hành trình tìm kiếm tia sét của vị thần Zeus để giải oan cho bản thân.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Walker Scobell","avatar":""},{"name":"Leah Sava Jeffries","avatar":""},{"name":"Aryan Simhadri","avatar":""},{"name":"Charlie Bushnell","avatar":""},{"name":"Dior Goodjohn","avatar":""},{"name":"Daniel Diemer","avatar":""},{"name":"Beatrice Kitsos","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["波西·杰克逊与奥林匹斯众神","波西·杰克逊","Percy Jackson - Die Serie","Percy Jackson ja olymposlaiset","Percy Jackson et les Olympiens","波西·傑克遜與奧林匹亞諸神","波西·傑克遜與奧林匹斯眾神","波西·傑克遜與奧林匹亞眾神","波西·傑克遜與奧林匹斯諸神","波西·傑克遜","퍼시잭슨과 올림포스의 신들","Percy Jackson y los Olímpicos","Percy