INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('percy-jackson-va-cac-vi-than-tren-dinh-olympus-phan-1', 'Percy Jackson Và Các Vị Thần Trên Đỉnh Olympus (Phần 1)', 'Percy Jackson And The Olympians (Season 1)', 'percy jackson và các vị thần trên đỉnh olympus (phần 1) percy jackson and the olympians (season 1) walker scobell leah sava jeffries aryan simhadri charlie bushnell dior goodjohn daniel diemer beatrice kitsos 波西·杰克逊与奥林匹斯众神 波西·杰克逊 percy jackson - die serie percy jackson ja olymposlaiset percy jackson et les olympiens 波西·傑克遜與奧林匹亞諸神 波西·傑克遜與奧林匹斯眾神 波西·傑克遜與奧林匹亞眾神 波西·傑克遜與奧林匹斯諸神 波西·傑克遜 퍼시잭슨과 올림포스의 신들 percy jackson y los olímpicos percy jackson ve olimposlular percy jackson pjo percy jackson and the olympians', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-mayfair-phan-1', 'Phù Thủy Mayfair (Phần 1)', 'Mayfair Witches (Season 1)', 'https://phimimg.com/upload/vod/20251128-1/2a90750b7b11520f17da32f9d2465ef4.jpg', 'https://phimimg.com/upload/vod/20251128-1/040066752020e2f8b96523c3e35ccea8.jpg', '<p>Phim xoay quanh bác sĩ giải phẫu thần kinh, tiến sĩ Rowan Fielding. Cô được cho là hậu duệ và là người thừa kế mới nhất của gia đình phù thủy Mayfair ở New Orleans. Rowan là phù thủy thứ 13 và cũng là người có trách nhiệm hoàn thành sứ mệnh của gia tộc. Rowan Fielding sở hữu trực giác cực kỳ nhạy bén và những sức mạnh nhất định. Bằng trực giác của mình, cô cảm thấy nghi ngờ liệu mình có thật sự là người thừa kế. Đồng thời, trong quá trình tiếp quản vai trò mới, Rowan phải đối phó với một thế lực độc ác đã hiện diện trong gia đình và ám ảnh họ qua nhiều thế hệ. Những cuộc chiến căng thẳng nổ ra. Và nhiều bí mật dần dần được phơi bày.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alexandra Daddario","avatar":""},{"name":"Tongayi Chirisa","avatar":""},{"name":"Ben Feldman","avatar":""},{"name":"Alyssa Jirrels","avatar":""},{"name":"Jack Huston","avatar":""},{"name":"Harry Hamlin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["梅菲尔女巫","Czarownice Mayfair","As Bruxas Mayfair de Anne Rice","Відьми Майфейр","Anne Rice''s Mayfair Witches","Mayfair Witches"]', 1784690324245);
