INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ky-thuong-ngay-cua-tien-vuong-phan-4', 'Nhật Ký Thường Ngày Của Tiên Vương (Phần 4)', 'The Daily Life Of The Immortal King (Season 4)', 'nhật ký thường ngày của tiên vương (phần 4) the daily life of the immortal king (season 4) sun lulu qian chen yin long gu jiangshan titus jin guo haoran shuai guan 仙王的日常生活第二季 xian wang de ri chang sheng huo 王令的日常生活 الحياة اليومية للملك الخالد 不滅の王の日常 daily life of the immortal king cuộc sống thường ngày của tiên vương 仙王的日常生活', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-mi-2023', 'Hoạ Mi', 'Unshakable Faith', 'https://phimimg.com/upload/vod/20251214-1/b2506deb072029428fcb3e7999c02b19.jpg', 'https://phimimg.com/upload/vod/20251214-1/840c9ed284e2e25485a04f1bcb8cab6f.jpg', '<p>Năm 1958, “Dự án Thủy Tích” nghiên cứu dựa trên lý thuyết cơ bản của tàu ngầm được triển khai. Sau khi công trình này được khởi động, nó đã trở thành cái gai trong mắt đặc vụ địch, chúng đã vạch ra một kế hoạch phá hoại có biệt hiệu là &quot;Hành động Bàn Thạch&quot; để ăn miếng trả miếng. Cảnh sát Bàng Hồng Mai nhận nhiệm vụ quan trọng là bảo vệ &quot;Dự án Thủy Tích&quot; và giải cứu Kế Đan Dương, một nhà khoa học yêu nước trở về từ Hoa Kỳ từ tay đặc vụ địch trong bối cảnh đặc vụ Hoa Kỳ và Tưởng Giới Thạch dựng lên vô số trở ngại, và hộ tống Kế Đan Dương đến thành phố Lộ Môn để tham gia &quot;Dự án Thủy Tích&quot;. Đặc vụ địch tập trung lực lượng ngầm và cố gắng hết sức để phá hoại &quot;Dự án Thủy Tích&quot;.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Hiểu Nhiên","avatar":""},{"name":"Lưu Học Nghi","avatar":""},{"name":"Kiều Nhân Tử","avatar":""},{"name":"Thạch Dư Phủ","avatar":""},{"name":"Lý Tân Tự","avatar":""},{"name":"Đinh Vĩnh Đại","avatar":""},{"name":"Hứa Bối Hối","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hua Mei","画眉"]', 1784690324245);
