INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-chien-nguoi-va-than-phan-2', 'Đại Chiến Người Và Thần (Phần 2)', 'Record Of Ragnarok (Season 2)', 'đại chiến người và thần (phần 2) record of ragnarok (season 2) miyuki sawashiro tomoyo kurosawa wataru takagi junichi suwabe tomokazu seki soma saito kazuhiro yamaji takahiro sakurai shūmatsu no valkyrie shūmatsu no walküre shuumatsu no valkyrie shuumatsu no walküre 終末のワルキューレⅱ 종말의 발키리 record of ragnarok walkirie kresu dziejów - record of ragnarok معركة راغناروك повість про кінець світу record of ragnarok ii record of ragnarok iii 終末のワルキューレ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-ket-ultraman-decker-hanh-trinh-vuon-xa', 'Hồi Kết Ultraman Decker: Hành Trình Vươn Xa', 'Ultraman Decker Finale: Journey To Beyond', 'https://phimimg.com/upload/vod/20251211-1/62fe56b0c454608379d60e6bfde8be9f.jpg', 'https://phimimg.com/upload/vod/20251211-1/80d9af8dd1104127d3b424dced8c1c34.jpg', '<p>Bộ phim tiếp nối cuộc chiến của Asumi Kanata sau khi Trái Đất bước vào giai đoạn hòa bình ngắn ngủi. Khi một tín hiệu bí ẩn từ vũ trụ sâu thẳm cảnh báo về hiểm họa mới, Kanata buộc phải hợp nhất với Decker lần nữa để bảo vệ nhân loại. Họ đối đầu kẻ thù đến từ chiều không gian xa lạ cùng âm mưu hủy diệt toàn thể vũ trụ. Bộ phim mang đến không khí hoành tráng, cảm xúc trưởng thành và thông điệp mạnh mẽ về hy vọng.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroki Matsumoto","avatar":""},{"name":"Yūka Murayama","avatar":""},{"name":"Nobunaga Daichi","avatar":""},{"name":"Sae Miyazawa","avatar":""},{"name":"Masaya Kikawada","avatar":""},{"name":"Kayano Nakamura","avatar":""},{"name":"Hiroshi Tsuchida","avatar":""},{"name":"Ryusei Nakao","avatar":""},{"name":"Dancho Yasuda","avatar":""},{"name":"HIRO","avatar":""},{"name":"Kuro-chan","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Akira Hongo","avatar":""},{"name":"Koji Nakamura","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Koichiro Nagayoshi","avatar":""},{"name":"Kaoru Nishiuchi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf40779166