INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-ket-ultraman-decker-hanh-trinh-vuon-xa', 'Hồi Kết Ultraman Decker: Hành Trình Vươn Xa', 'Ultraman Decker Finale: Journey To Beyond', 'hồi kết ultraman decker: hành trình vươn xa ultraman decker finale: journey to beyond hiroki matsumoto yūka murayama nobunaga daichi sae miyazawa masaya kikawada kayano nakamura hiroshi tsuchida ryusei nakao dancho yasuda hiro kuro-chan tomokazu seki akira hongo koji nakamura yuhko kaida koichiro nagayoshi kaoru nishiuchi 德凯奥特曼最终章：前往旅途的彼岸 ultraman decker finale.journey to beyond อุลตร้าแมนเดกเกอร์ การเดินทางสู่อนาคต ウルトラマンデッカー最終章 旅立ちの彼方へ…', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-doan-tu', 'Giáng Sinh Đoàn Tụ', 'A Season For Family', 'https://phimimg.com/upload/vod/20251211-1/01edfced211502b92f45304ba474c50f.jpg', 'https://phimimg.com/upload/vod/20251211-1/c24f51d4678f2acc0a5745acbb2249df.jpg', '<p>Sau nhiều năm làm việc, bà mẹ đơn thân Maddy quyết định dùng kỳ nghỉ dài đầu tiên cho chuyến trở về quê nhà ở Utah. Cô đi cùng cậu con trai nuôi Wesley - người luôn khao khát gặp lại anh trai, đang sống ở một gia đình khác. Tại Park City, hai mẹ con gặp Paul, một người cha góa vợ đang gặp khó khăn trong việc nuôi dạy con trai Cody. Maddy và Paul dần nảy sinh tình cảm, trong khi Wesley và Cody nhanh chóng trở thành bạn thân. Tuy nhiên, một bí mật lớn được tiết lộ: hai đứa trẻ chính là anh em ruột. Điều này khiến cho mối quan hệ của họ trở nên phức tạp. Liệu phép màu của Giáng sinh có thể giúp tất cả giải quyết được vấn đề?</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Brendan Penny","avatar":""},{"name":"Stacey Farber","avatar":""},{"name":"Benjamin Jacobson","avatar":""},{"name":"Azriel Dalman","avatar":""},{"name":"Gabriel Jacob-Cross","avatar":""},{"name":"Jim Martens","avatar":""},{"name":"Edward Ruttle","avatar":""},{"name":"Jessica Sipos","avatar":""},{"name":"Cameron Bancroft","avatar":""},{"name":"Laura Soltis","avatar":""},{"name":"Cardi Wong","avatar":""},{"name":"Dean Marshall","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Family Christmas","A Season for Family"]', 1784690324245);
