INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bien-mau-phan-1', 'Bờ Biển Máu (Phần 1)', 'Blood Coast (Season 1)', 'https://phimimg.com/upload/vod/20251211-1/781779d6c3e90e585d763e55b9259b70.jpg', 'https://phimimg.com/upload/vod/20251211-1/69ea2eacbfb6fb62dce40e81927e08e9.jpg', '<p>Khi tay buôn ma túy thâm hiểm cố gắng mở rộng địa bàn ở Marseille, vị đại úy cảnh sát bất hảo và đội ngũ liều lĩnh của anh chào đón một tân binh có kế hoạch riêng.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Tewfik Jallab","avatar":""},{"name":"Jeanne Goursaud","avatar":""},{"name":"Nicolas Duvauchelle","avatar":""},{"name":"Olivier Barthelemy","avatar":""},{"name":"Lani Sogoyou","avatar":""},{"name":"Idir Azougli","avatar":""},{"name":"Samir Boitard","avatar":""},{"name":"Moussa Maaskri","avatar":""},{"name":"Florence Thomassin","avatar":""},{"name":"Diouc Koma","avatar":""},{"name":"Bilal Ben Osmane","avatar":""},{"name":"Adel Fellous","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["血红海岸","Pax Massilia","Marseille-freden","Blood Coast"]', 1784690324245);
