INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-vit-di-cu', 'Nhà Vịt Di Cư', 'Migration', 'https://phimimg.com/upload/vod/20251206-1/a673fd81b7a42be019dee585e335a222.jpg', 'https://phimimg.com/upload/vod/20251206-1/b0edb282907a3bcde3ec24de705abc67.jpg', '<p>Nhà Vịt Di Cư theo chân một gia đình vịt trời gồm vịt bố, vịt mẹ, cậu con trai tuổi teen Dax và vịt út Gwen, trong lần đầu tiên trải nghiệm chuyến di cư tiến về phía nam để trú đông. Thế nhưng, niềm vui vẻ sự háo hức kéo dài không bao lâu, gia đình vịt nhận ra, họ đang bay ngược chiều với tất cả các đàn vịt khác. Không kịp quay đầu, họ bất ngờ gặp phải loạt “chướng ngại vật” là những tòa nhà cao tầng của thành phố hiện đại. Liên tiếp sau đó là những thước phim đầy kịch tính nhưng vô cùng hài hước của nhà vịt trong quá trình khám phá đô thị mới.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Kumail Nanjiani","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Caspar Jennings","avatar":""},{"name":"Tresi Gazal","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Carol Kane","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"David Mitchell","avatar":""},{"name":"Isabela Merced","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Ozioma Akagha","avatar":""},{"name":"Jozanne Marie","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Sarah Musnitsky","avatar":""},{"name":"Valenzia Algarin","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{