INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-di-rac-roi', 'Chuyến Đi Rắc Rối', 'Joy Ride', 'https://phimimg.com/upload/vod/20251206-1/52cf61a6cfd4854bf838182a4e910191.jpg', 'https://phimimg.com/upload/vod/20251206-1/c018cacebeacba7e7c971f5631b69623.jpg', '<p>Khi chuyến công tác châu Á của Audrey gặp trục trặc, cô phải nhờ đến sự giúp đỡ của Lolo, cô bạn thân từ thuở nhỏ, người luôn bất kính và cũng là một người cực kỳ bừa bộn; Kat, người bạn đại học đã trở thành ngôi sao phim truyền hình Trung Quốc; và Deadeye, cô em họ lập dị của Lolo. Trải nghiệm hoành tráng và không giới hạn này trở thành một hành trình gắn kết, tình bạn, tìm kiếm sự thuộc về, và những cuộc thác loạn hoang dại, hé lộ chân lý phổ quát về ý nghĩa của việc hiểu và yêu con người thật của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Ashley Park","avatar":""},{"name":"Sherry Cola","avatar":""},{"name":"Sabrina Wu","avatar":""},{"name":"Stephanie Hsu","avatar":""},{"name":"Debbie Fan","avatar":""},{"name":"Kenneth Liu","avatar":""},{"name":"Annie Mumolo","avatar":""},{"name":"David Denman","avatar":""},{"name":"Isla Rose Hall","avatar":""},{"name":"Chloe Pun","avatar":""},{"name":"Desmond Chiam","avatar":""},{"name":"Ronny Chieng","avatar":""},{"name":"Meredith Hagner","avatar":""},{"name":"Baron Davis","avatar":""},{"name":"Chris Pang","avatar":""},{"name":"Alexander Hodge","avatar":""},{"name":"Rohain Arora","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Timo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["แก๊งตั