INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-gia-gia-ngheo-2', 'Thiếu Gia Giả Nghèo 2', 'Rich in Love 2', 'https://phimimg.com/upload/vod/20251205-1/74f4e5d2844f5bb9e6f2b326d71d2a32.jpg', 'https://phimimg.com/upload/vod/20251205-1/024e92a6004113daea746cbda888f1b6.jpg', '<p>Khi Paula rời Rio de Janeiro để tiếp tục công việc bác sĩ tình nguyện ở Amazon, Teto nảy ra kế hoạch bốc đồng để đi theo cô. Và rồi hỗn loạn xảy ra!</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Danilo Mesquita","avatar":""},{"name":"Giovanna Lancellotti","avatar":""},{"name":"Jaffar Bambirra","avatar":""},{"name":"Lellê","avatar":""},{"name":"Fernanda Paes Leme","avatar":""},{"name":"Ernani Moraes","avatar":""},{"name":"Aline Dias","avatar":""},{"name":"Kay Sara","avatar":""},{"name":"Adanilo","avatar":""},{"name":"Roney Villela","avatar":""},{"name":"Ermelinda Yapario","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Reich an Liebe 2","Богат любовью 2","Riche en Amour 2","Rico en Amor 2","Rich in Love: Part 2","Ricos em Amor: Parte 2","Ricco d''Amore 2","リッチ・イン・ラブ 2","富有的愛 2","리치 인 러브 2","غني بالحب 2","รวยเล่ห์รัก 2","Богатые тоже любят","Богатство в любви 2","Ricos de Amor 2"]', 1784690324245);
