INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-hoc-chien-tranh-phan-1', 'Đại Học Chiến Tranh (Phần 1)', 'University War (Season 1)', 'đại học chiến tranh (phần 1) university war (season 1)  大学战争 elite league 대학전쟁', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yuri-la-cong-viec-cua-toi-watashi-no-yuri-wa-oshigoto-desu', 'Yuri Là Công Việc Của Tôi (Watashi no Yuri wa Oshigoto desu!)', 'Yuri Is My Job!', 'https://phimimg.com/upload/vod/20251204-1/5438a0eccca35c2b6a71b9e58b88bedd.jpg', 'https://phimimg.com/upload/vod/20251204-1/ccde856a94da8e995b9e48ab99123f41.jpg', '<p>Hime là một nữ sinh đẹp như tranh vẽ và được tất cả mọi người ngưỡng mộ. Một hôm cô ấy vô tình làm bị thương người quản lý quán cà phê Liebe nên phải làm việc thay cho cô ấy ở một nơi mà các nhân viên toàn nữ luôn nỗ lực hết mình vì những khách hàng thân thiết của họ.Tuy nhiên, dưới sự hướng dẫn của cô gái duyên dáng nhất ở đó, Hime không thể không đỏ mặt và mắc lỗi! Bên cạnh những điều rườm rà và tiếng cười, Hime cảm thấy căng thẳng khi cô ấy tìm hiểu thêm về công việc mới cũng như những cảm xúc chớm nở của mình…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yui Ogura","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Yukari Tamura","avatar":""},{"name":"Asami Seto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的百合是工作！","百合是我的工作！","我的百合乃工作是也！","Watashi no Yuri wa Oshigoto desu!","私の百合はお仕事です！"]', 1784690324245);
