INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yuri-la-cong-viec-cua-toi-watashi-no-yuri-wa-oshigoto-desu', 'Yuri Là Công Việc Của Tôi (Watashi no Yuri wa Oshigoto desu!)', 'Yuri Is My Job!', 'yuri là công việc của tôi (watashi no yuri wa oshigoto desu!) yuri is my job! yui ogura sumire uesaka minami tanaka makoto koichi yukari tamura asami seto 我的百合是工作！ 百合是我的工作！ 我的百合乃工作是也！ watashi no yuri wa oshigoto desu! 私の百合はお仕事です！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-da-yeu-nu-phan-dien-mat-roi', 'Tôi Đã Yêu Nữ Phản Diện Mất Rồi', 'I''m In Love With The Villainess', 'https://phimimg.com/upload/vod/20251204-1/376f100ceda03df81944513855c9bdb7.jpg', 'https://phimimg.com/upload/vod/20251204-1/6bf61ff7f4820b70b088c88745913466.jpg', '<p>Thế giới đảo lộn khi một nhân viên văn phòng bình thường tỉnh dậy và trở thành Rae Taylor, nhân vật nữ chính trong trò chơi otome (game hẹn hò dành cho nữ) yêu thích của cô, mang tên Revolution.Rae vô cùng phấn khích trước cơ hội được theo đuổi Claire François—nữ phản diện trong trò chơi và cũng là đối tượng cô thầm yêu.Với kiến thức đã có về trò chơi và những sự kiện sắp xảy ra, Rae bắt đầu lên kế hoạch để khiến Claire phải lòng mình. Nhưng nữ phản diện sẽ đón nhận những lời tán tỉnh lãng mạn của Rae như thế nào?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yu Serizawa","avatar":""},{"name":"Karin Nanami","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Aimi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["我的推是坏人大小姐。","我推乃是恶役大小姐","我推是反派大小姐。","Watashi no Oshi wa Akuyaku Reijou","Watashi no Oshi wa Akuyaku Reijō","WataOshi","Me enamoré de la villana","Я предпочитаю злодейку","我的推是壞人大小姐。","私の推しは悪役令嬢。"]', 1784690324245);
