INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-da-yeu-nu-phan-dien-mat-roi', 'Tôi Đã Yêu Nữ Phản Diện Mất Rồi', 'I''m In Love With The Villainess', 'tôi đã yêu nữ phản diện mất rồi i''m in love with the villainess yu serizawa karin nanami daisuke namikawa yoko hikasa ikumi hasegawa aimi 我的推是坏人大小姐。 我推乃是恶役大小姐 我推是反派大小姐。 watashi no oshi wa akuyaku reijou watashi no oshi wa akuyaku reijō wataoshi me enamoré de la villana я предпочитаю злодейку 我的推是壞人大小姐。 私の推しは悪役令嬢。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-cach-mang-ma-thuat-cua-cong-chua-chuyen-sinh-va-tieu-thu-thien-tai', 'Cuộc Cách Mạng Ma Thuật Của Công Chúa Chuyển Sinh Và Tiểu Thư Thiên Tài', 'The Magical Revolution Of The Reincarnated Princess And The Genius Young Lady', 'https://phimimg.com/upload/vod/20251204-1/69f369d6e31db815025e4834042ec5eb.jpg', 'https://phimimg.com/upload/vod/20251204-1/38857c41b1a4d63ede24dd644a6f62ef.jpg', '<p>Bất chấp việc được cho là kém cỏi với phép thuật thông thường, Công chúa Anisphia đã bất chấp kỳ vọng của tầng lớp quý tộc bằng cách phát triển &quot;ma thuật học&quot;, một lý thuyết ma thuật độc đáo dựa trên ký ức từ kiếp trước của cô. Một ngày nọ, cô chứng kiến nữ quý tộc tài giỏi Euphyllia bị tước bỏ danh hiệu quốc vương tiếp theo của vương quốc một cách bất công. Đó là khi Anisphia vạch ra một kế hoạch để giúp Euphyllia lấy lại danh tiếng của mình - điều này đã khiến họ sống cùng nhau và cùng nghiên cứu phép thuật! Tuy nhiên, hai người phụ nữ này không biết rằng cuộc gặp gỡ tình cờ của họ sẽ thay đổi không chỉ tương lai của chính họ mà còn của cả thế giới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sayaka Senbongi","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Ai Kakuma","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Yu Sasahara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["转生王女与天才千金的魔法革命","轉生公主與天才千金的魔法革命","Tensei Ōjo to Tensai Reijō no Mahō Kakumei","Tensei Oujo to Tensai Reijou no Mahou Kakumei","Tenten Kakumei","MagiRevo","転生王女と天才令嬢の魔法革命"]', 1784690324245);
