INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-si-2', 'Vệ Sĩ 2', 'Bodyguard 2', 'https://phimimg.com/upload/vod/20250204-1/8b95c97957b91cca0a9df598918ff371.jpg', 'https://phimimg.com/upload/vod/20250204-1/c104f0aaca4fcfa7a9957a30a55331bb.jpg', '<p>Phim kể về Cao Thiên, một vệ sĩ quốc tế, đã lập tức đi giải cứu sau khi nhận được cuộc gọi khẩn cấp từ người chủ cũ của mình. Manh mối bằng không, giúp đỡ không có, Cao Thiên đã tìm thấy những người tiền bối cũ của mình, nhận được sự trợ giúp từ họ, anh đã thành lập một đội giải cứu tạm thời. Tuy nhiên, nhiệm vụ giải cứu đầy éo le, tình báo rối ren, khó phân biệt đúng sai, ai mới là tội phạm cuối cùng...</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Niệm Vinh Tân","avatar":""},{"name":"Triệu Yến Quốc Chương","avatar":""},{"name":"Cung Phương Nghi","avatar":""},{"name":"Đới Thiên","avatar":""},{"name":"Gia Vĩ","avatar":""},{"name":"Từ Khôn","avatar":""},{"name":"Nỗ Bố","avatar":""},{"name":"Hàn Văn Quân","avatar":""},{"name":"Quan Vĩ","avatar":""},{"name":"Mã Á Quân","avatar":""},{"name":"Ngô Khắc Cương","avatar":""},{"name":"Bạch Dao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bodyguard 2","护卫者2"]', 1784690324245);
