INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguu-ma-vuong-tro-lai', 'Ngưu Ma Vương Trở Lại', 'Bull Demon King Rise Again', 'https://phimimg.com/upload/vod/20251126-1/c1481f37e55ff756eea295af9f3e7445.jpg', 'https://phimimg.com/upload/vod/20251126-1/41940aa9b479dc141cbc479bddf79391.jpg', '<p>Bộ phim kể lại câu chuyện vào thời cổ đại, Xi Vưu thủ lĩnh của Ma tộc, kiêu ngạo ngạo mạn, gây ra hỗn loạn thiên giới, nhưng cuối cùng cũng bị đánh trở lại hình dạng ban đầu. Không ngờ vài năm sau, bản tính yêu quái và trí nhớ của Xi Vưu bị đánh thức, Xi Vưu một mình đến Côn Lôn tìm cách giải quyết, trên đường đi gặp Diệp Tiêu Tiêu. Hai người này cùng nhau vượt qua khó khăn nguy hiểm, và tình yêu của họ từ từ nảy nở. Xi Vực liên tục lang thang giữa thiện và ác. Điều này gần như gây ra sự tàn phá, nhưng cuối cùng, cái ác không thể đàn áp cái thiện. Những âm mưu xung quanh cậu ấy từ thời xa xưa đã được hóa giải.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Phàn Thiếu Hoàng","avatar":""},{"name":"Lý Mộc Duẫn","avatar":""},{"name":"Vương Cương","avatar":""},{"name":"Trần Diệc Minh","avatar":""},{"name":"Tăng Thần","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The Return of Bull Demon King","牛魔王之魔王再临"]', 1784690324245);
