INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-loi-hoa-huyen-long', 'Địch Nhân Kiệt: Lôi Hỏa Huyền Long', 'Detective Dee And Grand Canal Dragon', 'https://phimimg.com/upload/vod/20251126-1/7a48b3d26155893fbc2a7865dc78203d.jpg', 'https://phimimg.com/upload/vod/20251126-1/4aba2727ce33147e8b28eb3f265220db.jpg', '<p>Địch Nhân Kiệt: Lôi Hỏa Huyền Long nói về ương truyền ở hành cung Lạc Dương mới xây có thần long xuất hiện, phun lửa thiêu rụi cả hành cung, thợ mộc thì kẻ chết người bị thương. Địch Nhân Kiệt được được đặc cách làm thiếu khanh Đại Lý Tự để xử lý vụ “Hỏa hoạn ở Hành cung”. Trong công cuộc phá án, chàng bị một lực lượng bí ẩn cản trở, thậm chí còn bị phục kích. &nbsp;Nhưng nhờ vào dấu vết từ cuộc phục kích cùng với lời gợi ý từ Lý cư sĩ ẩn thế, chàng tìm được thiếu cung chủ. Với đầu mối thiếu cung chủ này, anh dần dần khám phá ra sự thật. Được hồng nhan tri kỷ Liễu Nguyệt Như giúp đỡ, chàng đã thành công phá hủy cơ quan ngầm của thiếu cung chủ. Nhưng hóa ra tên thiếu cung chủ này chỉ là tốt thí, đằng sau gã ta còn có một người bí ẩn kiểm soát cục diện.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Thịnh Vinh","avatar":""},{"name":"Trần Dịch Anh","avatar":""},{"name":"Trịnh Thanh Văn","avatar":""},{"name":"Lê Chân An","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Di Renjie''s canal startled the dragon","Legend of Detective Dee","狄仁杰之运河惊龙"]', 1784690324245);
