INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-tin-tuc-phan-1', 'Nữ Hoàng Tin Tức (Phần 1)', 'The Queen Of News (Season 1)', 'https://phimimg.com/upload/vod/20251114-1/5b662eec0c569b65134175c5a0f304c0.jpg', 'https://phimimg.com/upload/vod/20251114-1/263ccae54b904b2ede65e3a5892bf84c.jpg', '<p>Trong khung giờ bản tin sáng, biên tập viên Hứa Thi Tình (do Cao Hải Ninh đóng) bằng ưu thế vóc dáng và khuôn mặt xinh đẹp, cô được thăng tiến bởi biết nắm bắt những điểm cao trào trong bản tin; nhưng thực ra cô chỉ hy vọng người cha bị sa sút trí tuệ nhìn thấy cô trên truyền hình. Trong khung giờ bản tin trưa, biên tập viên Trương Gia Nghiên (do Lý Thi Hoa đóng) tránh xa sự tranh giành bè phái, nhưng nào ngờ cô bị lợi dụng, làm một con cờ cân bằng thế lực, bị lôi cuốn vào sự đấu tranh quyền lực. Trong khung giờ tin tức tối khuya, biên tập viên Từ Hiểu Vi (do Hà Y Đình đóng) trung thành với người tại vị, cho rằng danh lợi cuối cùng sẽ thuộc về mình, nhưng kết quả là không những người thân bị thiệt thòi, hơn nữa bản thân cô còn bị tổn thương về tinh thần. Người mới Lưu Diễm (do Vương Mẫn Dịch đóng) tràn trề nhiệt thành, theo đuổi chân tướng, nhắc nhở mọi người rằng làm nghề truyền thông, nên có tấm lòng son.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Xa Thi Mạn","avatar":""},{"name":"Mã Quốc Minh","avatar":""},{"name":"Lý Thi Hoa","avatar":""},{"name":"Đàm Tuấn Ngạn","avatar":""},{"name":"Cao Hải Ninh","avatar":""},{"name":"Hà Y Đình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新闻女王","新闻女王2","The.Queen.of.NEWS","The QUEEN of News 2","The Queen of NEWS","新聞女王","新聞