INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-tu-2023', 'Trùng Tử', 'The Journey Of Chongzi', 'https://phimimg.com/upload/vod/20251109-1/020281527db9422b48059ce6fe7ac04b.jpg', 'https://phimimg.com/upload/vod/20251109-1/95241b1974e5b013dc1942332b75487a.jpg', '<p>Tam giới gặp tai kiếp, Ma tôn Nghịch Luân bị tiêu diệt, tà linh Cửu U chạy tán loạn, trốn vào nhân gian. Trùng Tử trong sáng lương thiện, song lại là con gái của Nghịch Luân. Vì được Vân quân tử Sở Bất Phục cứu mạng nên cô đã đến Nam Hoa xin học, nhưng do sát khí bẩm sinh mà bị từ chối thẳng thừng, đốc giáo của Nam Hoa là Mẫn Vân Trung còn quả quyết cô ắt sẽ nhập tà. Đúng lúc then chốt,Trùng Hoa tôn giả Lạc Âm Phàm đứng ra thu nhận cô làm đệ tử, kể từ đó Trùng Tử trở thành đồ đệ duy nhất của Lạc Âm Phàm. Trùng Tử ỷ lại Lạc Âm Phàm, chỉ mong được bầu bạn bên sư phụ sớm sớm chiều chiều, Lạc Âm Phàm cũng hứa sẽ bảo vệ Trùng Tử hết mực. Vì không thể chống lại âm mưu của Cửu U, Lạc Âm Phàm đành giương mắt nhìn Trùng Tử bị giam cầm mà lực bất tòng tâm và buộc phải &quot;kết liễu&quot; cô vì chúng sinh thiên hạ. Tại Vân Không, Trùng Tử một lần nữa xuất hiện ở Nam Hoa để bái sư, Lạc Âm Phàm nhận ra cô ngay tức thì.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Siêu Việt","avatar":""},{"name":"Từ Chính Khê","avatar":""},{"name":"Mã Văn Viễn","avatar":""},{"name":"Đặng Vi","avatar":""},{"name":"Lâm Tư Ý","avatar":""},{"name":"Uông Trác Thành","avatar":""},{"name":"Vu Ba","avatar":""},{"name":"Trương Chỉ Khê","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chong Zi","重紫"]', 1784690324245);
