INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-tokyo-2023', 'Chuyện Tình Tokyo', 'Tokyo Love Act Story', 'https://phimimg.com/upload/vod/20251106-1/5a00c83760934003479e824231348677.jpg', 'https://phimimg.com/upload/vod/20251106-1/a6ff4158aefe334eebe1c8c891f0ee15.jpg', '<p>Chuyến đi đến Tokyo mà Chu Quốc Bân mong đợi bấy lâu chỉ nhằm gặp gỡ Momo Nogi – người bạn quen qua mạng mà anh đã thầm yêu suốt ba năm. Bất ngờ, một người đàn ông bí ẩn nhét vào tay anh một cuốn sổ nhỏ mang tên “Shi” cùng một chiếc bao cao su, rồi đe dọa rằng nếu anh không tìm được “lông mu” của mình, anh sẽ kiệt sức mà chết!&nbsp; Chính cuốn sổ kỳ lạ “Shi” ấy đã đưa Chu Quốc Bân gặp gỡ hàng loạt nữ diễn viên phim người lớn (AV), mở ra chuỗi cuộc gặp gỡ kỳ quái và siêu thực.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Kana Momonogi","avatar":""},{"name":"Moe Amatsuka","avatar":""},{"name":"Umi Yatsugake","avatar":""},{"name":"Ria Yamate","avatar":""},{"name":"Minami Aizawa","avatar":""},{"name":"Iori Kogawa","avatar":""},{"name":"Karen Yuzuriha","avatar":""},{"name":"Saika Kawakita","avatar":""},{"name":"Mihiro Taniguchi","avatar":""},{"name":"Ai Haneda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["东京爱情动作故事","Tokyo Sex Story","Tokyo Love Act Story","Tokyo Love Action Story","東京愛情動作故事"]', 1784690324245);
