INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('psycho-pass-su-menh', 'Psycho-Pass: Sứ Mệnh', 'Psycho-Pass: Providence', 'psycho-pass: sứ mệnh psycho-pass: providence kana hanazawa tomokazu seki kenji nojima shizuka itoh miyuki sawashiro ayane sakura takahiro sakurai hiroki touchi takako honda kazuhiro yamaji noriko hidaka psycho-pass サイコパス providence psycho-pass: the movie providence 剧场版 心灵判官  providence ไซโคพาส โพวิเด้นท์ психопаспорт: провидение 사이코패스 프로비덴스 心理测量者 剧场版：天意 剧场版 心理测量者 providence 劇場版 psycho-pass 心靈判官 providence 극장판 psycho-pass：providence 劇場版 psycho-pass サイコパス providence', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('upin-ipin-phan-17', 'Upin & Ipin (Phần 17)', 'Upin & Ipin (Season 17)', 'https://phimimg.com/upload/vod/20251022-1/6650e718747a9f3a64c76a7e4dad5dfa.jpg', 'https://phimimg.com/upload/vod/20251022-1/a6acb3e73f9cfb2b2fa4d5d0ecc30324.jpg', '<p>“Upin &amp; Ipin” là loạt phim hoạt hình 3D do Les’ Copaque Production Sdn. Bhd. sản xuất và hiện là một trong những loạt phim hoạt hình ăn khách nhất tại Malaysia, nhận được nhiều đánh giá tích cực và trung bình đạt khoảng 800.000 lượt xem mỗi tập. Bộ phim thực chất là phần ngoại truyện của bộ phim đầu tay “Geng: Pengembaraan Bermula” của công ty.</p><p>Bộ phim xoay quanh cặp song sinh 5 tuổi Upin và Ipin, những người kể chuyện về cuộc sống thường ngày của mình thông qua những hành động vui nhộn và thú vị với bạn bè, đồng thời học hỏi những điều mới mẻ trong các hoạt động thường ngày. Giống như bao đứa trẻ khác, Upin và Ipin rất tinh nghịch và thường xuyên gặp rắc rối, chủ yếu là với cô em gái tuổi teen Ros.</p><p><br/></p><p><br/></p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 19, 2023, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Asyiela Putri","avatar":""},{"name":"Siti Khairunnisa","avatar":""},{"name":"Hajah Ainon Ariff","avatar":""},{"name":"Calvin Tony Lokeemin","avatar":""},{"name":"Tang Ying Sowk","avatar":""},{"name":"Muhammad Hafiz Hassan","avatar":""},{"name":"Muhammad Fareez Daniel","avatar":""},{"name":"Rufaidah Mohamed Fadzil","avatar":""},{"name":"Usayd Uqashah Kamsani","avatar":""},{"name":"Siti Nor Adwin Safie","avatar":""},{"name":"Irfan Fahim","avatar":""},{"name":"Maheswary Mohan","avatar":""},{"name":"Suleiman Bakti Azl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Upin & Ipin"]', 1784690324245);
