INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-ha-truyen-ban-hoat-hinh', 'Ám Hà Truyện (Bản Hoạt Hình)', 'Tales Of Dark River', 'https://phimimg.com/upload/vod/20251020-1/a44087709e4d5e832144ac16d6d1adf1.jpg', 'https://phimimg.com/upload/vod/20251020-1/2df97f6ace99ee03d3acb025dc3dc57a.jpg', '<p>Ám Hà, tổ chức sát thủ thần bí nhất trong giang hồ, tạo thành bởi ba gia tộc họ Tô, Tạ, Mộ, thủ lĩnh tối cao của ba nhà gọi là Đại gia trưởng. Đại gia trưởng thân trúng kỳ độc, tính mạng nguy trong sớm tối. Sau khi thế lực ba nhà Ám Hà biết được tin tức bèn nhân cơ hội nổi dậy. Tô Mộ Vũ, thân là thủ lĩnh đội Thù Ảnh chuyên bảo vệ Đại gia trưởng, một bên tìm thần y Bạch Hạc Hoài của Dược Vương Cốc xin chữa bệnh cho Đại gia trưởng, một bên đối phó với sát thủ của các gia tộc bảo vệ an toàn cho Đại gia trưởng. Lúc này, bạn thân Tô Tinh Hà của hắn trong tổ chức Ám Hà lại đại diện Tô gia, gia nhập hành động ám sát Đại gia trưởng.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Mingyue","avatar":""},{"name":"Tang Xiaoxi","avatar":""},{"name":"Wei Chao","avatar":""},{"name":"Jinwen Chen","avatar":""},{"name":"Qiao Shiyu","avatar":""},{"name":"Lin Qiang","avatar":""},{"name":"Jiasi Li","avatar":""},{"name":"Zhao Mingzhou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Anhe Zhuan","少年歌行外传","少年歌行外传：暗河传","暗河传","少年歌行之暗河传","Legend of Assassin","Легенда о подземной реке","暗河傳","少年歌行外傳：暗河傳","Tales Of Dark River","Tales of The 