INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-dong-2023', 'Sống Động', 'Vivant', 'https://phimimg.com/upload/vod/20251020-1/589f66ec4e5d0841ede3266e8606c9e1.jpg', 'https://phimimg.com/upload/vod/20251020-1/1486dbf7b651554159f51c45a3ba1da9.jpg', '<p>Trong khi điều tra một vụ chuyển nhầm số tiền rất lớn, doanh nhân vụng về nọ bị cuốn vào cuộc phiêu lưu hoành tráng có quy mô toàn cầu.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masato Sakai","avatar":""},{"name":"Hiroshi Abe","avatar":""},{"name":"Fumi Nikaido","avatar":""},{"name":"Tori Matsuzaka","avatar":""},{"name":"Kazunari Ninomiya","avatar":""},{"name":"Koji Yakusho","avatar":""},{"name":"Ryo Ryusei","avatar":""},{"name":"Kento Hayashi","avatar":""},{"name":"Rin Takanashi","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Iinuma Ai","avatar":""},{"name":"Takaya Sakoda","avatar":""},{"name":"Takashi Yamanaka","avatar":""},{"name":"Satoshi Hashimoto","avatar":""},{"name":"Kunito Watanabe","avatar":""},{"name":"Robin Furuya","avatar":""},{"name":"Kaho Mizutan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["活著","活着","别班","ヴィヴァン","ตายไม่ได้","VIVANT"]', 1784690324245);
