INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-long-quy-su', 'Tầm Long Quỷ Sự', 'Dragon Hunting Mystery', 'https://phimimg.com/upload/vod/20251020-1/5a45277bd4843d4535158c6ffbf40205.jpg', 'https://phimimg.com/upload/vod/20251020-1/249e10e1c7fbb464e3d91c350ff09dfe.jpg', '<p>Bộ phim này lấy nhân vật thần thoại cổ đại Thần Nông làm bối cảnh của câu chuyện, lấy việc tìm kiếm hộp kho báu của Thần Nông làm tình tiết, diễn giải các câu chuyện thần thoại và truyền thuyết dưới góc độ khoa học, kể về câu chuyện của Thành Tử một người bình thường, đột nhiên một ngày nọ trở thành một nhân vật lịch sử lớn, có công giải cứu nhân loại. Đối mặt với kẻ ác độc ác mạnh mẽ và bộ tộc ngoài hành tinh của hắn, Thành Tử ngay từ đầu đã bị giới hạn bởi tầm nhìn và khuôn mẫu hạn hẹp dần dần trở thành một anh hùng hy sinh bản thân để bảo vệ thế giới, đối mặt với những khó khăn và nguy hiểm, với sự giúp đỡ của mọi người họ cùng nhau trải qua muôn vàn khó khăn và dũng cảm chiến đấu với kẻ ác đến cùng, cuối cùng đã tập hợp trí tuệ và sức mạnh của mọi người để đánh bại kẻ ác, giải quyết khủng hoảng nhân loại .</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Thần Hào","avatar":""},{"name":"Trương Tử Tuyên","avatar":""},{"name":"Hầu Hiểu","avatar":""},{"name":"Cao Hùng","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Dragon Hunt","Tầm Long Quỷ Sự","寻龙诡事"]', 1784690324245);
