INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-capsule-phan-2', 'Kế Hoạch Capsule (Phần 2)', 'Capsules (Season 2)', 'https://phimimg.com/upload/vod/20251012-1/4b9074dcd92a4db33f152bb3e51c2978.jpg', 'https://phimimg.com/upload/vod/20251012-1/35db983939c06d213d6cee2cad086b01.jpg', '<p><span style="text-wrap-mode: wrap;">Bộ phim&nbsp;khai thác bảy loại cảm xúc cực hạn, mỗi loại tương ứng với một màu “capsule” khác nhau. Các đội ngẫu nhiên chọn ra hai viên&nbsp;</span><span style="text-wrap-mode: wrap;">capsule</span><span style="text-wrap-mode: wrap;">, từ đó xây dựng nên những bộ phim ngắn dựa trên sự kết hợp cảm xúc của hai màu đó, tạo nên những câu chuyện độc đáo và đa dạng.</span></p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["胶囊计划 第一届","Jiaonang Jihua","Jiao Nang Ji Hua","Capsule","Capsule Plan","Capsule Project","Capsule Project: Hero","胶囊计划"]', 1784690324245);
