INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-long-tu-tien-3-chien-truong-thuong-co', 'Ngự Long Tu Tiên 3: Chiến Trường Thượng Cổ', 'Dragon Sword: Ancient Battlefield', 'https://phimimg.com/upload/vod/20251020-1/c97e6b480e98f78876e86a02a202350f.jpg', 'https://phimimg.com/upload/vod/20251020-1/50de5d93380821bc7f0c6e8fd76a9bb4.jpg', '<p>Để cứu Lam Mặc Y, một trong thập đại tu tiên thánh thể nhưng lại gặp phải biến cố gây nguy hiểm tới tính mạng, Bác Viêm kiên quyết đến vùng đất được thần ban phước nằm trong chiến trường thượng cổ do phân thân cao thủ Chân Thần Kỳ bảo hộ để tìm kiếm Viêm Thần. Chiến trường thượng cổ chia làm ba tầng, tầng sau còn hiểm trở hơn tầng trước. Khi hàng phục quái thú Mặc Huyền Giao canh giữ tầng ngoài đến tận lối vào, Bác Viêm gặp được kẻ Nghiêm Hoan – kẻ thù tiến vào Tứ Tượng Cực Địa ở trung tầng từ nghìn năm về trước đang bị thương trong lúc thu phục Thổ Linh Thú, tông chủ của Thương Nham Tông – Thương Thạch Linh Quân, cả hai đã hòa giải sau trận chiến khốc liệt để giành một nửa bản đồ kho báu của đối phương, sau đó cùng tiến về Tứ Tượng Cực Địa...</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Vũ Tư","avatar":""},{"name":"Lôi Mông","avatar":""},{"name":"Đỗ Phùng Vũ Dung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yu Long Xiu Xian Zhuan 3 Shang Gu Zhan Chang","Dragon Sword: Ancient Battlefield","御龙修仙传3上古战场"]', 1784690324245);
