INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngu-long-tu-tien-3-chien-truong-thuong-co', 'Ngự Long Tu Tiên 3: Chiến Trường Thượng Cổ', 'Dragon Sword: Ancient Battlefield', 'ngự long tu tiên 3: chiến trường thượng cổ dragon sword: ancient battlefield bành vũ tư lôi mông đỗ phùng vũ dung yu long xiu xian zhuan 3 shang gu zhan chang dragon sword: ancient battlefield 御龙修仙传3上古战场', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mao-son-thuc-thuc', 'Mao Sơn Thúc Thúc', 'Uncle Maoshan (Mao Mountain Uncle)', 'https://phimimg.com/upload/vod/20251020-1/45d2c23fa46b6563c1546ac05251d0b8.jpg', 'https://phimimg.com/upload/vod/20251020-1/ff65c69dd4ceccc757440d201d56755f.jpg', '<p>Trong thời kỳ cuối thế kỷ 19 và đầu thế kỷ 20, ông trùm tài phiệt Nhậm Lão qua đời bất ngờ và lan truyền thông tin trong xóm là ông đã bị “ma cà rồng” hại chết. Người chết không chỉ sống lại một cách kỳ quái, biến thành “ma cà rồng” theo lời đồn đại của dân làng, mà còn làm chết nhiều người. Trung sĩ Tào, thủ trưởng đội cảnh sát, buộc phải mời đạo sĩ Thiên Hạc đến để trừ tà. Tuy nhiên, sau khi thực hiện nghi thức, thậm chí thầy pháp Thiên Hạc cũng không thể kiểm soát. Theo dấu vết từng mảng chỉ mục, đệ tử của đạo sĩ Thiên Hạc, Mao Tiểu Phương, dần dần phát hiện ra sự thật đằng sau vụ án.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Đông","avatar":""},{"name":"Lâu Nam Quang","avatar":""},{"name":"Hà Kì Vĩ","avatar":""},{"name":"Trống Phát","avatar":""},{"name":"Nhạc Đông Phong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["茅山叔叔","Mao Sơn Thúc Thúc","Mao Shan Uncle","MaoShan Uncle","Uncle Maoshan"]', 1784690324245);
