INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mao-son-thuc-thuc', 'Mao Sơn Thúc Thúc', 'Uncle Maoshan (Mao Mountain Uncle)', 'mao sơn thúc thúc uncle maoshan (mao mountain uncle) trương đông lâu nam quang hà kì vĩ trống phát nhạc đông phong 茅山叔叔 mao sơn thúc thúc mao shan uncle maoshan uncle uncle maoshan', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-trai-tan-bien-chi-anh-ninh', 'Liêu Trai Tân Biên Chi Anh Ninh', 'Legend Of Ghost YingNing', 'https://phimimg.com/upload/vod/20251020-1/764a860fabc03ea79ff91a85b4274eff.jpg', 'https://phimimg.com/upload/vod/20251020-1/381693942ab1341d963172e01e0d1048.jpg', '<p>Chàng thư sinh Vương Tử Phục đã yêu cô gái Anh Ninh ngay từ lần đầu tiên nhìn thấy cô. Tình cờ, anh tìm được nơi cô ở và hai người trở thành vợ chồng sau khi biết được Anh Ninh là yêu hồ, Vương Mẫu - mẹ của Tử Phục - đã chia cắt hai người và khiến Tử Phục bị bệnh nặng. Anh Ninh rất đau buồn và tình cờ phát hiện ra lai lịch của mình, đánh bại yêu quái, chữa lành vết thương cho Tử Phục và hai người cuối cùng đã hạnh phúc sống cùng nhau. Đây là một câu chuyện tình yêu cổ trang đầy cảm động và hy vọng.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Vũ Bằng","avatar":""},{"name":"Mã Huệ","avatar":""},{"name":"Lâm Vi","avatar":""},{"name":"Tống Tử Khiếu","avatar":""},{"name":"Triệu Hàn Tuyết","avatar":""},{"name":"Phạm Tử Kỳ","avatar":""},{"name":"Hầu Lâm Lâm","avatar":""},{"name":"Quách Đái Tấn","avatar":""},{"name":"Ái Uy","avatar":""},{"name":"Lâm Tuấn Hiền","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["聊斋新篇之婴宁","聊斋新编之婴宁"]', 1784690324246);
