INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lieu-trai-tan-bien-chi-anh-ninh', 'Liêu Trai Tân Biên Chi Anh Ninh', 'Legend Of Ghost YingNing', 'liêu trai tân biên chi anh ninh legend of ghost yingning chu vũ bằng mã huệ lâm vi tống tử khiếu triệu hàn tuyết phạm tử kỳ hầu lâm lâm quách đái tấn ái uy lâm tuấn hiền 聊斋新篇之婴宁 聊斋新编之婴宁', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-nu-thien-menh', 'Huyền Nữ Thiên Mệnh', 'The Girl Of Destiny', 'https://phimimg.com/upload/vod/20251020-1/ec0943d0e4215519abf31ae5b4a24547.jpg', 'https://phimimg.com/upload/vod/20251020-1/33bfdc294a1818e61d2dce272ab53091.jpg', '<p>Huyền thoại kể rằng tổ tiên của nhà Thương ra đời sau khi mẹ anh ăn quả trứng chim. Nhà Thương tin rằng, Thiên Mệnh Huyền Nữ sẽ bảo hộ họ. Thương Chủ Tiểu Ất, vì muốn mượn quyền lực của Tướng quân Cổ Dã để đàn áp các bộ tộc, đã lén đánh tráo kết quả của Huyền Điểu Giáng Thế. 20 năm sau, nhà Lạc xâm chiếm. Từ khi còn nhỏ, Phụ Hảo, người được định sẵn là Thiên Mệnh Huyền Nữ đã can dự vào cuộc chiến và cứu vớt quân đội nhà Thương khỏi hung hiểm. Sau đó, cùng với Vũ Đinh - vương tử nhà Thương - chống lại giặc ngoại xâm và dập tắt nội chiến. Cuối cùng, cả hai cùng nhau trải qua gian khổ, cùng nhau trưởng thành, không chỉ trục xuất được người Lạc mà còn giành được tình cảm của bách tính muôn tộc.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Uông Tĩnh Nhi","avatar":""},{"name":"Mã Tuyết Dương","avatar":""},{"name":"Mã Thư Lương","avatar":""},{"name":"Triệu Hồng Hạ","avatar":""},{"name":"Lợi Lân Phi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Girl of Destiny","天命玄女","The Mystery of Xuannu","The Goddess of War","Fu Hao"]', 1784690324246);
