INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ngoai-giao-phan-1', 'Nhà Ngoại Giao (Phần 1)', 'The Diplomat (Season 1)', 'https://phimimg.com/upload/vod/20251017-1/207cd1798a2b3bf922fa596ea59b7abd.jpg', 'https://phimimg.com/upload/vod/20251017-1/e8ad839ee4b7e08b0cee00209b642166.jpg', '<p>Giữa khủng hoảng quốc tế, một nhà ngoại giao Hoa Kỳ vật lộn với công việc gây chú ý là đại sứ tại Vương quốc Anh và cuộc hôn nhân căng thẳng với một chính trị gia nổi tiếng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Keri Russell","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"David Gyasi","avatar":""},{"name":"Ali Ahn","avatar":""},{"name":"Rory Kinnear","avatar":""},{"name":"Ato Essandoh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Diplomatische Beziehungen","نماینده سیاسی","دیپلمات","The Diplomat"]', 1784690324246);
