INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thuc-da-ngoai-tai-di-gioi-voi-ky-nang-khong-tuong-phan-1', 'Ẩm Thực Dã Ngoại Tại Dị Giới Với Kỹ Năng Không Tưởng (Phần 1)', 'Campfire Cooking In Another World With My Absurd Skill (Season 1)', 'https://phimimg.com/upload/vod/20241227-1/807e1c81c0502e9847a9470839859769.jpg', 'https://phimimg.com/upload/vod/20241227-1/16ebb246cc842fdb9c059034f64dd1aa.jpg', '<p>Chàng trai bình thường nọ rốt cuộc lại đến một thế giới khác và có năng lực mang đến những sản phẩm từ một siêu thị hiện đại, với những kết quả ngon lành trong thế giới mới này.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuma Uchida","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Hina Kino","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Saho Shirasu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Cocinando en otro mundo con mi absurda habilidad","拥有超常技能的异世界流浪美食家","网购技能开启异世界美食之旅","Campfire Cooking in Another World With My Absurd Skill","किसी दूसरी दुनिया में अलाव पर खाना पकाना, मेरी बेतुकी कला के साथ","Tondemo Skill de Isekai Hōrō Meshi","Tondemo Skill de Isekai Hourou Meshi","とんでもスキルで異世界放浪メシ2","Ẩm Thực Gia Tại Dị Giới","Đốt Lửa Trại Ở Một Thế Giới Khác Với Kỹ Năng Phi Lý Của Tôi","とんでもスキルで異世界放浪メシ"]', 1784690324246);
