INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-thuc-da-ngoai-tai-di-gioi-voi-ky-nang-khong-tuong-phan-1', 'Ẩm Thực Dã Ngoại Tại Dị Giới Với Kỹ Năng Không Tưởng (Phần 1)', 'Campfire Cooking In Another World With My Absurd Skill (Season 1)', 'ẩm thực dã ngoại tại dị giới với kỹ năng không tưởng (phần 1) campfire cooking in another world with my absurd skill (season 1) yuma uchida satoshi hino hina kino maaya uchida you taichi yuhko kaida saho shirasu cocinando en otro mundo con mi absurda habilidad 拥有超常技能的异世界流浪美食家 网购技能开启异世界美食之旅 campfire cooking in another world with my absurd skill किसी दूसरी दुनिया में अलाव पर खाना पकाना, मेरी बेतुकी कला के साथ tondemo skill de isekai hōrō meshi tondemo skill de isekai hourou meshi とんでもスキルで異世界放浪メシ2 ẩm thực gia tại dị giới đốt lửa trại ở một thế giới khác với kỹ năng phi lý của tôi とんでもスキルで異世界放浪メシ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('family-guy-phan-22', 'Family Guy (Phần 22)', 'Family Guy (Season 22)', 'https://phimimg.com/upload/vod/20251015-1/43a6814436f3e07ad0767ddd925cebe5.jpg', 'https://phimimg.com/upload/vod/20251015-1/7e629e19f2c45548bf8d2d163ef85440.jpg', '<p><span style="text-wrap-mode: wrap;">Bộ phim xoay quanh những cuộc phiêu lưu và hoạt động thường nhật của gia đình Griffin, bao gồm trụ cột gia đình Peter Griffin, một người đàn ông béo phì trung niên ngốc nghếch và vụng về làm việc trong nhà máy bia, Lois, nội trợ kiêm giáo viên dạy piano, vốn xuất thân từ gia đình tài phiệt Pewterschmidt, Meg, một cô bé 18 tuổi thường xuyên bị bắt nạt, Chris, cậu bé 15 tuổi thừa cân và cư xử ngốc nghếch giống Peter và Stewie, một bé trai 1 tuổi thông minh nhưng tinh ranh và đôi khi nham hiểm, cư xử theo cách của một người trưởng thành. Sống cùng gia đình là Brian, chú chó được nhân cách hóa, với nhiều thói quen của con người như hút thuốc, uống rượu martini, mặc dù về nhiều mặt vẫn được coi là thú cưng.</span></p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Seth MacFarlane","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Arif Zahir","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["გრიფინები","Keluarga Pria","مرد خانه","خانواده‌ دوست","쇼킹 패밀리","쇼킹패밀리","परिवारको केटा","Сім’янин","Ґріффіни","Family Guy"]', 1784690324246);
