INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('family-guy-phan-22', 'Family Guy (Phần 22)', 'Family Guy (Season 22)', 'family guy (phần 22) family guy (season 22) seth macfarlane alex borstein mila kunis seth green patrick warburton arif zahir გრიფინები keluarga pria مرد خانه خانواده‌ دوست 쇼킹 패밀리 쇼킹패밀리 परिवारको केटा сім’янин ґріффіни family guy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-huyen-thien-tren-noc-xe', 'Thần Huyền Thiên Trên Nóc Xe', 'Be With Me', 'https://phimimg.com/upload/vod/20251013-1/8665eeb46341fcae4ae37eb234546f48.jpg', 'https://phimimg.com/upload/vod/20251013-1/8216c60210a925895963023f0f578445.jpg', '<p>Phim kể về Phù Nguyệt (do Lâm Y Thần thủ vai) – một họa sĩ thiết kế mỹ thuật phim tại Đài Bắc. Khi cha lâm bệnh nặng, cô buộc phải rời khỏi đoàn phim giữa chừng, tạm gác lại việc cải tạo một ngôi nhà cổ để trở về quê nhà Gia Nghĩa chăm sóc cha. Trong những ngày sống cùng gia đình ở quê, Phù Nguyệt lần theo dấu chân của người ông quá cố, nhớ lại niềm tin và tinh thần truyền thống mà ông để lại. Hành trình ấy giúp cô tìm lại bản thân, sức mạnh nội tâm và mối liên kết với cội nguồn tín ngưỡng dân gian — đặc biệt là tín ngưỡng về Huyền Thiên Thượng Đế, vị thần bảo hộ mang ý nghĩa sâu sắc trong văn hóa Đài Loan. Tóm lại, bộ phim là một câu chuyện nhẹ nhàng, sâu lắng về gia đình, niềm tin và hành trình chữa lành tâm hồn, thể hiện tình cảm gắn bó giữa người trẻ thành thị và quê hương.</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lâm Y Thần","avatar":""},{"name":"Châu Du Dân","avatar":""},{"name":"Nguyễn Kinh Thiên","avatar":""},{"name":"Trương Hiếu Toàn","avatar":""},{"name":"Hoàng Văn Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["車頂上的玄天上帝"]', 1784690324246);
