INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-huyen-thien-tren-noc-xe', 'Thần Huyền Thiên Trên Nóc Xe', 'Be With Me', 'thần huyền thiên trên nóc xe be with me lâm y thần châu du dân nguyễn kinh thiên trương hiếu toàn hoàng văn anh 車頂上的玄天上帝', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-bi-mat-cua-ai-u', 'Phòng Bí Mật Của Ái U', 'X&Y', 'https://phimimg.com/upload/vod/20251014-1/49009828a1925cc844b08edf708f86ac.jpg', 'https://phimimg.com/upload/vod/20251014-1/67f112a59fb5329e1ffc24c68df6810f.jpg', '<p>Diêm Nguyệt Xuất trở về quê hương làm việc và quen biết những người bạn mới trong công ty. Một lần cùng nhóm bạn đến “Phòng Mật XY” để chơi trò giải mật thất, anh bất ngờ bị thu hút bởi chủ nhân của nơi này — Hứa Ái U. Tuy nhiên, đó cũng chính là khởi đầu cho chuỗi ảo cảnh quỷ dị trong những căn mật thất kỳ lạ.Cùng lúc ấy, khi mối quan hệ giữa Diêm Nguyệt Xuất và Hứa Ái U dần trở nên gần gũi hơn, hàng loạt sự kiện bí ẩn liên tiếp xảy ra xung quanh anh, thậm chí còn cuốn cả bạn bè anh vào vòng xoáy nguy hiểm. Trong quá trình giải mã các mật thất và truy tìm kẻ đứng sau mọi chuyện, Diêm Nguyệt Xuất dần chạm tới sự thật bị che giấu suốt bao năm qua…</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Youwu","avatar":""},{"name":"Hao Xianghai","avatar":""},{"name":"Shen Nianru","avatar":""},{"name":"Li Shenqian","avatar":""},{"name":"Teng Xin","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Aiyou de Mishi","Ai You De Mi Shi","Тайная комната, любящая безмолвие","爱幽的密室","Aiyou''s Secret Room"]', 1784690324246);
