INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-hy-linh', 'Thời Đại Hy Linh', 'Xyrin Empire', 'https://phimimg.com/upload/vod/20251012-1/c6503b76132bd829aaf788dd6a6dffc8.jpg', 'https://phimimg.com/upload/vod/20251012-1/acfc74d72566eaf58b68feba981f43ee.jpg', '<p>Trần Tuấn — một “trạch nam giả” với chí hướng chỉ muốn ăn no chờ chết — bỗng nhiên, chẳng hề được chuẩn bị tinh thần, lại trở thành hoàng đế của một đế quốc hùng mạnh thống trị đa vũ trụ. Dù Trần Tuấn khiêm tốn tuyên bố rằng mình chỉ muốn làm một người bình thường, nhưng nữ tướng cao mét hai của đế quốc Pandora, chị đẹp Cục Dị Năng Lâm Tuyết, và nữ hoàng đồng trị của đế quốc Sandora đều đồng loạt phản đối. Ngay cả cô bạn thanh mai tràn đầy năng lượng Hứa Thiển Thiển cũng nói: “Không được, anh phải làm hoàng đế đấy~” Thế là, trong hoàn cảnh chẳng thể chọn lựa, Trần Tuấn đành bước vào cuộc sống bận rộn: thứ Hai đến thứ Sáu cứu thế giới, còn thứ Bảy, Chủ nhật thì nghỉ ngơi chơi game.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhenyan Liu","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Hao Xianghai","avatar":""},{"name":"Shen Nianru","avatar":""},{"name":"Yeqiao Yan","avatar":""},{"name":"Zhang Youwu","avatar":""},{"name":"Zhang Youwu","avatar":""},{"name":"Sun Lulu","avatar":""},{"name":"Meme Yan","avatar":""},{"name":"Ye Zhiqiu","avatar":""},{"name":"Chang Rongshan","avatar":""},{"name":"Yang Ning","avatar":""},{"name":"Zhao Mingzhou","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["希灵帝国","希靈帝國","希靈紀元","Xyrin Empire","希灵纪元"]', 1784690324246);
