INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuc-chien-ca-khong-gian-di-gioi', 'Khúc Chiến Ca Không Gian Dị Giới', 'THRUD', 'https://phimimg.com/upload/vod/20251012-1/c032734e34939feb9164f6dbb87231b1.jpg', 'https://phimimg.com/upload/vod/20251012-1/13c4ab10dbc9e491f44bf8a92d6a21d0.jpg', '<p>Nữ chiến binh thiếu nữ Fania tình cờ gặp một chàng trai mất trí nhớ tên là “Người Hướng Dẫn”, và cả hai cùng nhau bắt đầu chuyến hành trình phiêu lưu. Trong quá trình đó, họ dần khám phá ra bí mật về kẻ thù — những “Dị sinh thể”. Đồng thời, họ cũng phát hiện ra đằng sau mọi chuyện là một “thế lực bí ẩn” đang âm mưu thao túng vận mệnh của các nữ chiến binh “Slude”. Trước âm mưu đó, họ quyết định vùng dậy phản kháng, thanh tẩy mảnh đất này…</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Kong Zhan Ge","斯露德 空中女武神","THRUD","THRUD: Broken Heaven","异空战歌"]', 1784690324246);
