INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-danh-thue-4', 'Biệt Đội Đánh Thuê 4', 'Expend4bles', 'https://phimimg.com/upload/vod/20251012-1/77c17c946f1141765f79605e6c3f782d.jpg', 'https://phimimg.com/upload/vod/20251012-1/89b54b2e012622fd62f5b4264791c388.jpg', '<p>Biệt Đội Đánh Thuê 4 – The Expendables 4 (2023) là phim hành động Mỹ được đạo diễn bởi Scott Waugh với phần kịch bản do Spenser Cohen, Max Adams và John Joseph Connolly chấp bút. Đây là phần hậu truyện của Biệt đội đánh thuê 3 và đồng thời cũng là phần phim thứ bốn của loạt phim Biệt đội đánh thuê.
 Biệt Đội Đánh Thuê 4 bao gồm các chiến binh kỳ cựu và tân binh, đang đối mặt với nhiệm vụ nguy hiểm: ngăn chặn Suharato Rahmat, một tên buôn vũ khí nguy hiểm, khỏi giao kíp nổ hạt nhân cho Ocelot, một kẻ độc ác đe dọa thế giới. Hành trình từ một nhà máy vũ khí cũ ở Qadhafi đến con thuyền Jantara sẽ hé lộ những bí mật và sự thật đáng kinh ngạc về Ocelot.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Bulgaria', 0, '[{"name":"Jason Statham","avatar":""},{"name":"50 Cent","avatar":""},{"name":"Megan Fox","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Tony Jaa","avatar":""},{"name":"Iko Uwais","avatar":""},{"name":"Andy García","avatar":""},{"name":"Sylvester Stallone","avatar":""},{"name":"Randy Couture","avatar":""},{"name":"Jacob Scipio","avatar":""},{"name":"Levy Tran","avatar":""},{"name":"Lucy Newman-Williams","avatar":""},{"name":"Daren Nop","avatar":""},{"name":"Kenny \"Cowboy\" Bartram","avatar":""},{"name":"Cody Mackie","avatar":""},{"name":"Cokey Falkow","avatar":""},{"name":"Dan Chupong","avatar":""},{"name":"Kar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Nesunaikinami 4","Expendables 4","Biệt Đội Đánh Thuê 4","The Expendables 4","I mercen4ri","Os Mercen4rios","Eroi de sacrificiu 4","Неудержимые 4","浴血任務4","Os Mercenários 4","Plaćenici 4","Expend4bles: Postr4datelní","轟天猛將4","Feláldozh4tók","エクスペンダブルズ ニューブラッド","โคตรคนทีมมหากาฬ 4","بی‌مصرف‌ها ۴","The Expendables 4 - Expend4bles","敢死队4","Cəhənnəm Mələkləri 4","Les S4crifiés","A feláldozhatók 4 - Expend4bles","Los Mercenarios: 4","Expend4bles","Les Sacrifiés 4","轰天猛将4"]', 1784690324246);
