INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-doi-danh-thue-4', 'Biệt Đội Đánh Thuê 4', 'Expend4bles', 'biệt đội đánh thuê 4 expend4bles jason statham 50 cent megan fox dolph lundgren tony jaa iko uwais andy garcía sylvester stallone randy couture jacob scipio levy tran lucy newman-williams daren nop kenny "cowboy" bartram cody mackie cokey falkow dan chupong kar nesunaikinami 4 expendables 4 biệt đội đánh thuê 4 the expendables 4 i mercen4ri os mercen4rios eroi de sacrificiu 4 неудержимые 4 浴血任務4 os mercenários 4 plaćenici 4 expend4bles: postr4datelní 轟天猛將4 feláldozh4tók エクスペンダブルズ ニューブラッド โคตรคนทีมมหากาฬ 4 بی‌مصرف‌ها ۴ the expendables 4 - expend4bles 敢死队4 cəhənnəm mələkləri 4 les s4crifiés a feláldozhatók 4 - expend4bles los mercenarios: 4 expend4bles les sacrifiés 4 轰天猛将4', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-chinh-da-giai-nghe-nhieu-nam', 'Nữ Chính Đã Giải Nghệ Nhiều Năm', 'Since I Wasn''t The Heroine', 'https://phimimg.com/upload/vod/20251012-1/bf22d2ab1d72feaba009d0ee63f7e989.jpg', 'https://phimimg.com/upload/vod/20251012-1/107bd961a120156fc368e49b6d0216a1.jpg', '<p>Bắc Di dùng mưu kế tập kích bất ngờ vào Bạch Thành – trọng trấn biên giới phía bắc của Đại Tề quốc. Tướng thủ thành Đường Nghiêu dẫn quân tử chiến chống địch, nhưng vì lực lượng quá chênh lệch, toàn quân hy sinh, chỉ còn lại nhị tiểu thư Đường Anh may mắn sống sót. Điều khiến Đường Anh càng thêm bi phẫn là cha nàng hy sinh vì nước, nhưng đổi lại lại bị mang tội thông đồng với địch. Để minh oan cho cha, Đường Anh một mình xông vào kinh đô, song phát hiện mọi chuyện không hề đơn giản như tưởng tượng. Liệu hoàng tử thứ hai của Đại Tề quốc – Nguyên Lăng – có liên quan đến Bắc Di hay không? Tại sao lại có một cô gái giả mạo nàng với dung mạo giống hệt mình một cách kỳ lạ? “Người từ thế giới khác” mà Yêu Nương của Ảnh Bộ nhắc đến là ai? Và những ký ức vừa xa lạ vừa quen thuộc luôn ám ảnh nàng rốt cuộc là gì?... Quá nhiều bí ẩn đang chờ Đường Anh từng bước vén màn giải đáp.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Ni","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ta Bu Dang Nuzhu Hen Duonian","她不当刁民很多年","Ta Bu Dang Nuzhu Hen Duo Nian","Ta Bu Dang Nüzhu Hen Duonian","她不當女主很多年","I Have Not Been a Pleb for Many Years","She Is A Heroine Ever","她不当女主很多年"]', 1784690324246);
