INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-hanh-phuc-cua-thieu-chu-chinh-phai', 'Cuộc Sống Hạnh Phúc Của Thiếu Chủ Chính Phái', 'The Little Master''s Better Life', 'https://phimimg.com/upload/vod/20251012-1/b31e22e0793de9a431d969e961839487.jpg', 'https://phimimg.com/upload/vod/20251012-1/b91ab64c3a0087528d373ca79d2efda8.jpg', '<p>Trong thế giới Đại Hoang, con người tuy nhỏ bé nhưng không hề thấp hèn. Dù là Thần Nông và thần dân của nhân vực, hay các bộ tộc nơi Bắc Dã, tất cả đều đang nỗ lực sinh tồn và không ngừng phát triển theo cách riêng của mình. Dẫu cho họ bị Tinh Thần mê hoặc và áp chế, nhưng để bảo vệ bộ tộc, gìn giữ huyết mạch và người thân, họ vẫn kiên cường đứng lên chống lại Tinh Thần, mở ra một cuộc chiến sinh tử giữa nhân loại và thần linh.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Zhengjing Shao Zhu de","Zheng Jing Shao Zhu de Xing Fu Sheng Huo","这个人仙太过正经","Zhege Ren Xian Taiguo Zhengjing","Zhe Ge Ren Xian Tai Guo Zheng Jing","Zhèngjīng Shǎo Zhǔ De Xìngfú Shēnghuó","Este Inmortal Es Demasiado Serio","Kehidupan Bahagia sang Tuan Muda","The Little Master''s Better Life","正经少主的幸福生活"]', 1784690324246);
