INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-kien-tao', 'Kẻ Kiến Tạo', 'The Creator', 'https://phimimg.com/upload/vod/20251010-1/1f1c6b6ff250e556050b9263967174d2.jpg', 'https://phimimg.com/upload/vod/20251010-1/e6f308eb5366226d016045c3b80d37ca.jpg', '<p>Từ Biên kịch/Đạo diễn Gareth Edwards (&quot;Rogue One,&quot; &quot;Godzilla&quot;) mang đến một bộ phim hành động viễn tưởng lấy bối cảnh cuộc chiến trong tương lai giữa loài người và trí tuệ nhân tạo. Joshua, một cựu đặc vụ đang đau buồn trước sự mất tích của người vợ, được thuê để tiêu diệt Creator, kẻ đã đứng sau phát triển một loại vũ khí có sức mạnh chấm dứt mọi cuộc chiến và sự sống của toàn thể nhân loại. Joshua và nhóm đặc vụ tinh nhuệ đã lần theo dấu vết tiến vào lãnh thổ bị A.I chiếm đóng, chỉ để khám phá ra vũ khí hủy diệt thế giới mà anh ta được giao tiêu diệt là một A.I dưới hình hài của một đứa trẻ.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"John David Washington","avatar":""},{"name":"Madeleine Yuna Voyles","avatar":""},{"name":"Gemma Chan","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Sturgill Simpson","avatar":""},{"name":"Amar Chadha-Patel","avatar":""},{"name":"Marc Menchaca","avatar":""},{"name":"Robbie Tann","avatar":""},{"name":"Ralph Ineson","avatar":""},{"name":"Michael Esper","avatar":""},{"name":"Veronica Ngo","avatar":""},{"name":"Ian Verdun","avatar":""},{"name":"Daniel Ray Rodriguez","avatar":""},{"name":"Rad Pereira","avatar":""},{"name":"Syd Skidmore","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"982