INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ghet-ma-van-yeu-2023', 'Ghét Mà Vẫn Yêu', 'Anyone But You', 'https://phimimg.com/upload/vod/20251010-1/6be74a007f94da9281b7aa68010c9ddb.jpg', 'https://phimimg.com/upload/vod/20251010-1/0050ca04e28165a672f420105e5587a6.jpg', '<p>Bộ phim xoay quanh Bea (Sydney Sweeney) và Ben (Glen Powell) - hai kẻ ghét nhau như “chó với mèo” từ thời Đại học. Sau nhiều năm tái ngộ, họ đều trở nên “ngon” hơn xưa gấp bội. Nhân chuyến du lịch Sydney (Úc), cả hai quyết định vờ làm người yêu và thực hiện luôn một đám cưới giả vì những lý do riêng. Thế nhưng, đây cũng là lúc vô số sự kiện dở khóc dở cười ập đến khiến hai kẻ thù dần nảy sinh tình cảm.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sydney Sweeney","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"Mia Artemis","avatar":""},{"name":"Nat Buchanan","avatar":""},{"name":"GaTa","avatar":""},{"name":"Alexandra Shipp","avatar":""},{"name":"Hadley Robinson","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Rachel Griffiths","avatar":""},{"name":"Deborah Faye Lee","avatar":""},{"name":"Lance Kerfuffle","avatar":""},{"name":"Taryn Gluck","avatar":""},{"name":"Alexandra Gluck","avatar":""},{"name":"Summer Tian","avatar":""},{"name":"Dan Liu","avatar":""},{"name":"Davina Chan Gallagher","avatar":""},{"name":"Charlee Fraser","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Anyone But You: The Valentine Encore","Только не ты","Кто угодно, но не ты","Обичам да те мразя","Senden Başka Herkes","애니원 벗 유","Senden Başka","Cualq