INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-the-cua-co-ay', 'Cơ Thể Của Cô Ấy', 'Her Body', 'https://phimimg.com/upload/vod/20251009-1/0a186030cd1e2416e9a92d292060c0c4.jpg', 'https://phimimg.com/upload/vod/20251009-1/adb9543b24d39ed8afc526d94cf21874.jpg', '<p>Her Body là câu chuyện đầy kịch tính của năm 2023 với bối cảnh xoay quanh một vận động viên thành công, thành viên của đội Olympic, sau một chấn thương xương sống và sự kết thúc buộc phải của sự nghiệp thể thao, trở thành một diễn viên phim người lớn thành công và nổi tiếng. Dựa trên câu chuyện có thật của nhà vô địch lặn Olympic Andrea Absolonová. Phim kết hợp giữa thể loại tâm lý và tài năng chỉ đạo của đạo diễn Natálie Císařovská, cùng dàn diễn viên xuất sắc như Natalia Germani, Denisa Barešová, Cyril Dobrý, Zuzana Mauréry...đem lại cho khán giả những trải nghiệm không thể quên.</p>', 'Full', 1, 'single', 'completed', 23, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Natalia Germani","avatar":""},{"name":"Denisa Barešová","avatar":""},{"name":"Cyril Dobrý","avatar":""},{"name":"Zuzana Mauréry","avatar":""},{"name":"Martin Finger","avatar":""},{"name":"Zuzana Stivínová","avatar":""},{"name":"Karolína Krezlová","avatar":""},{"name":"Tereza Švejdová","avatar":""},{"name":"Štěpán Lustyk","avatar":""},{"name":"Jiří Rendl","avatar":""},{"name":"Andrej Polák","avatar":""},{"name":"Roman Polák","avatar":""},{"name":"Martin Valihora","avatar":""},{"name":"Tarra White","avatar":""},{"name":"Ayelet Halamish","avatar":""},{"name":"Oldřich Widman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["身段","Její tělo"]', 1784690324246);
