INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-dung-vao-hoi-cua-toi', 'Đừng Đụng Vào Hội Của Tôi!!', 'Don''t Touch My Gang', 'https://phimimg.com/upload/vod/20251008-1/0a5e8181c37a833ed92e2f79e8f4e53e.jpg', 'https://phimimg.com/upload/vod/20251008-1/dff1dc9ee25936cbab94cb187c131f6c.jpg', '<p>Bốn chàng trai mơ ước được lên thành phố học. Nhưng sai lầm từ việc gõ sai tên trường khiến cuối cùng họ phải học ở trường cho thợ cơ khí. Và tại nơi đây, họ gặp được một nữ sinh đã thay đổi cuộc đời họ trong hàng rào ngôi trường cơ khí...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Purim Rattanaruangwattana","avatar":""},{"name":"Phantira Pipityakorn","avatar":""},{"name":"Harit Cheewagaroon","avatar":""},{"name":"Thanawat Shinawatra","avatar":""},{"name":"Ratchapon Pootong","avatar":""},{"name":"Panupan Jantanawong","avatar":""},{"name":"Panisara Rikulsurakan","avatar":""},{"name":"Kittisak Patomburana","avatar":""},{"name":"Chaleumpol Tikumpornteerawong","avatar":""},{"name":"Suchada Sonpan","avatar":""},{"name":"Poon Mitpakdee","avatar":""},{"name":"Chayapak Tunprayo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Gang Kha Khrai Ya Te","แก๊งข้าใครอย่าเตะ!!"]', 1784690324246);
