INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-thoi-hao', 'Tứ Thời Hảo', 'Yes, Her Majesty', 'https://phimimg.com/upload/vod/20251008-1/362a10939b5d69df5943d840c4baf1a8.jpg', 'https://phimimg.com/upload/vod/20251008-1/d6ab736de9d75093d62a282b6d253304.jpg', '<p>Sau khi rơi xuống nước, &quot;nữ hoàng&quot; nước Đại Yến mắc chứng rối loạn trí nhớ, rơi vào &quot;mộng đẹp dối trá&quot; mà &quot;nam hoàng hậu&quot; hay gây sự thêu dệt nên, nguy hiểm trùng trùng, nghi ngờ bủa vây, trong quá trình nữ hoàng khám phá ra sự thật về thân phận của mình, nàng cũng dần dần phải lòng người chung chăn gối với mình, người luôn âm thầm bảo vệ nàng, nguyện làm hậu phương vững chắc giúp nàng thực hiện ước mơ.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hu Dandan","avatar":""},{"name":"Cheng Yufeng","avatar":""},{"name":"Zhang Dongzi","avatar":""},{"name":"Lai Xilong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Si Shi Hao","殿下四时好","四時好","Dian Xia Si Shi","四时好"]', 1784690324246);
