INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-diep-vien-phan-2', 'Gia Đình Điệp Viên (Phần 2)', 'Spy x Family (Season 2)', 'https://phimimg.com/upload/vod/20251005-1/ecd8450b64e6a6b4efb36f406942864a.jpg', 'https://phimimg.com/upload/vod/20251005-1/47bb414c4cf258cd7abdcdbd15bc84e8.jpg', '<p>Nhằm ngăn những kẻ cực đoan châm ngòi cho cuộc chiến với quốc gia láng giềng Ostania, Twilight, điệp viên hàng đầu của Westalis phải điều tra chính trị gia người Ostanian là Donovan Desmond bằng cách xâm nhập vào trường học của con trai ông ta - học viện Eden danh giá. Dưới vỏ bọc Loid Forger, một bác sĩ, Twilight đã nhận nuôi cô bé mồ côi Anya và kết hôn giả với Yor Briar rồi cho Anya nhập học tại học viện Eden mà không hề hay biết hai người này cũng có thân phận bí mật: Yor là sát thủ được mệnh danh &quot;Công chúa Thorn&quot; còn Anya là siêu năng lực gia có khả năng đọc suy nghĩ. Tuy khởi đầu là một gia đình giả mà cả ba đều lợi dụng lẫn nhau, nhưng theo thời gian, họ dần nhận ra tầm quan trọng của hai người kia trong trái tim mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Takuya Eguchi","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Saori Hayami","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Agent x Ailə","间谍家家酒","间谍过家家","Spy X Family","SPYxFAMILY間諜家家酒Season2","SPYFAMILY間諜家家酒Season2","SPY x FAMILY 間諜家家酒 Season 2","SPY FAMILY 間諜家家酒 Season 2","מרגל × משפחה","स्पाई x फैमिली","スパイファミリー","Spy Family","Spy x Family 2nd","SPY×FAMILY：2022","간첩 가족","스파이×패밀리","스파이 패밀리","عائلة × جاسوس","สปายแฟมิลี่","SPY X FAMILY 間諜家家酒","間諜家家酒","SPY×FAMILY 間諜家家酒 Season 3","Шпигун × Сім’я","Сім’я шпигуна","Шпигун × Родина","Сім''я × Шпигуна","Шпигун та сім''я","Gia Đình Điệp Viên","SPY×FAMILY"]', 1784690324246);
