INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-diep-vien-phan-2', 'Gia Đình Điệp Viên (Phần 2)', 'Spy x Family (Season 2)', 'gia đình điệp viên (phần 2) spy x family (season 2) takuya eguchi atsumi tanezaki saori hayami agent x ailə 间谍家家酒 间谍过家家 spy x family spyxfamily間諜家家酒season2 spyfamily間諜家家酒season2 spy x family 間諜家家酒 season 2 spy family 間諜家家酒 season 2 מרגל × משפחה स्पाई x फैमिली スパイファミリー spy family spy x family 2nd spy×family：2022 간첩 가족 스파이×패밀리 스파이 패밀리 عائلة × جاسوس สปายแฟมิลี่ spy x family 間諜家家酒 間諜家家酒 spy×family 間諜家家酒 season 3 шпигун × сім’я сім’я шпигуна шпигун × родина сім''я × шпигуна шпигун та сім''я gia đình điệp viên spy×family', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-nhu-da-kien-nhu-ban-thach', 'Vững Như Đá (Kiên Như Bàn Thạch)', 'Under The Light', 'https://phimimg.com/upload/vod/20251004-1/88b71d6f3b8d5be1263a35866b8948bf.jpg', 'https://phimimg.com/upload/vod/20251004-1/6722b039ebfadf820d93cf9ff2ff3efe.jpg', '<p>Câu chuyện xoay quanh cuộc điều tra chung của Tô Kiến Minh và Lí Huệ Lâm đối với một vụ án hình sự liên quan đến các nhóm lợi ích khổng lồ. Kiến Minh bất chấp sự can ngăn của đã quyết định dấn thân vào &quot;Hồng Môn Yến&quot; do một doanh nhân giàu có tổ chức để truy tìm manh mối. Tuy nhiên, dòng nước ngầm dâng trào đằng sau những sự việc này khiến người ta mơ hồ cảm thấy rằng một ván cờ lớn đang được lên kế hoạch.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lôi Giai Âm","avatar":""},{"name":"Trương Quốc Lập","avatar":""},{"name":"Vu Hòa Vỹ","avatar":""},{"name":"Trần Sùng","avatar":""},{"name":"Đặng Gia Gia","avatar":""},{"name":"Tô Phàm","avatar":""},{"name":"Tân Bôn","avatar":""},{"name":"Lý Na","avatar":""},{"name":"Chu Á Văn","avatar":""},{"name":"Nhiếp Viễn","avatar":""},{"name":"Trần Trác","avatar":""},{"name":"Trương Dịch","avatar":""},{"name":"Lý Dịch Phong","avatar":""},{"name":"Trương Dung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rock Solid","Hard as Rock","Jian ru pan shi","Under the Light","Under the Light CN","坚如磐石"]', 1784690324246);
