INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-ha-chi-anh', 'Sơn Hà Chi Ảnh', 'Pledge Of Allegiance', 'https://phimimg.com/upload/vod/20251003-1/ee535b7b35852a77f8fb7e05c0f9e749.jpg', 'https://phimimg.com/upload/vod/20251003-1/2d8e5e75c630dd2df320f54a80ef2763.jpg', '<p>Vào năm Kiến Văn thứ ba, Lí Vụ - một tên trộm từ Kê Nga Hạng, bắt gặp quan viên Vương Khắc Cung của Phủ Tế Nam đang mang theo vàng bạc của cải chạy đến Nam Kinh. Vì vậy, gã đã lẻn vào phủ Vương Khắc Công, đánh cắp bức thiếp Cẩm Y Bách Hộ nổi tiếng của Lý Đông Phương. Còn tưởng trộm được bảo vật một cách thuận lợi, sau một đêm phất lên hưởng phú quý. Không ngờ rằng, trong phủ Vương Khắc Công có biến ngầm, Lí Vụ bị ép phải can dự vào cuộc chiến vũ khí tiền triều bắt nguồn từ Khóa Ngư Minh. Lí Vụ , ban đầu vốn là người ngoài cuộc, đã trở thành người nắm Khóa Ngư Minh trong tay và rơi vào tâm vòng xoáy. Tống Trân, cậu bé thuở nhỏ đã cứu Lí Vụ khỏi ngục giam, giờ đã trở thành Cẩm Y Vệ Lục Tranh, là đồng liêu với Lí Vụ, cả hai gặp nhưng không nhận ra nhau. Thư Đường cô gái ở cùng trong ngục với Lí Vụ đã trở thành sát thủ ngầm, còn cùng Lí Vụ giả làm một cặp phu thê, cùng nhau hoàn thành những âm mưu ẩn trong bóng tối,</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Vân Long","avatar":""},{"name":"Trần Nhược Huyền","avatar":""},{"name":"Tôn Y","avatar":""},{"name":"Ma Duệ Kiệt","avatar":""},{"name":"Tư Sa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984