INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-ngai-cuoi-chi-can-mot-ly-do', 'Không Ngại Cưới Chỉ Cần Một Lý Do', 'Just A Reason To Get Married', 'https://phimimg.com/upload/vod/20250930-1/66b4b1343206b0b6ea3c122409fd501a.jpg', 'https://phimimg.com/upload/vod/20250930-1/5a645171f2725cc8b9f974c34ce6d1b8.jpg', '<p>Bộ phim xoay quanh câu chuyện của Hoàng Yến (Hoàng Thùy Linh) và Đình Đông (Nguyễn Trọng Lân) – hai anh em trong một gia đình có điều kiện ở nông thôn, đều quá tuổi lập gia đình nhưng vẫn độc thân. Yến – một sếp nữ &quot;ác ma&quot;, một mình bươn chải để có được vị trí như hiện tại khiến cô có những tiêu chí cao đến mức bất khả thi để chọn bạn đời. Trái với Yến, Đông là một thiếu gia làng, sống không cần ước mơ, không khát vọng và đặc biệt tuyên bố không kết hôn. Anh chỉ cần sống khoẻ, không vi phạm pháp luật và chờ đến ngày được tiêu số tiền mình được thừa kế...</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hoàng Thùy Linh","avatar":""},{"name":"Nhan Phúc Vinh","avatar":""},{"name":"Lương Quỳnh","avatar":""},{"name":"Nguyễn Trọng Lân","avatar":""},{"name":"Lại Phú Đôn","avatar":""},{"name":"Nguyễn Thanh Bình","avatar":""},{"name":"Phạm Bảo Hân","avatar":""},{"name":"Quang Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324246);
