INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-ngai-cuoi-chi-can-mot-ly-do', 'Không Ngại Cưới Chỉ Cần Một Lý Do', 'Just A Reason To Get Married', 'không ngại cưới chỉ cần một lý do just a reason to get married hoàng thùy linh nhan phúc vinh lương quỳnh nguyễn trọng lân lại phú đôn nguyễn thanh bình phạm bảo hân quang anh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-minh-duoi-kinh-hien-vi', 'Đại Minh Dưới Kính Hiển Vi', 'Under the Microscope', 'https://phimimg.com/upload/vod/20250929-1/d03db4912c1df877d8c8b73de9786f29.jpg', 'https://phimimg.com/upload/vod/20250929-1/5d737976447ecdc572230e140e10b6a0.jpg', '<p>Soái Gia Mặc, là chàng trai bị ám ảnh bởi toán học, không chút hứng thú với tửu sắc bài bạc, thú vui của anh là chỉnh sửa lại những sai sót trong sổ sách. Chỉ cần có cơ hội, anh chàng sẽ nghĩ cách để vào kho tài liệu xem lại những sổ sách cũ để tính toán lại các con số. Tất cả các loại thuế của phủ Huy Châu do 6 huyện cùng gánh vác, Gia Mặc vô tình phát hiện mục “thuế tơ lụa” lại chỉ do một huyện Thiệp đảm đương nhiều năm qua. Sau đó, y tìm được bằng chứng giúp người dân huyện Thiệp đòi lại công đạo. Từ đây, Soái Gia Mặc bị cuốn vào “vụ án tơ lụa” mở ra một câu chuyện theo dòng lịch sử chính trị của triều Đại Minh. Bất luận phía có bao nhiêu trở ngại hay khó khăn, động chạm đến lợi ích của ai, &quot;phép tính&quot; có lỗi sai nhất định phải sửa đổi đó chính là hoài bão và ý chí kiên định của Soái Gia Mặc.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 11, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Vy","avatar":""},{"name":"Trương Nhược Quân","avatar":""},{"name":"Vương Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Daming Under Microscope","显微镜下的大明","显微镜下的大明之金华丝绢案始末","大明宫","殿下与臣民","Under The Microscope","显微镜下的大明之丝绢案"]', 1784690324246);
