INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-tieng-dam-mau', 'Danh Tiếng Đẫm Máu', 'The Glorious My Revenge', 'https://phimimg.com/upload/vod/20250928-1/e8d7e9b856b179000a2d540e8fb43a67.jpg', 'https://phimimg.com/upload/vod/20250928-1/936c773073caf15cea4f1242ff89f61f.jpg', '<p>Con trai qua đời mà thủ phạm lại chẳng đền tội, gia đình và sự nghiệp của Ryoo Yi dần sụp đổ. Khi sắp vực dậy bắt đầu cuộc sống mới, anh lại tình cờ chạm mặt Im Hak Chon - kẻ thủ ác mà mình căm thù.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Heo Joon-seok","avatar":""},{"name":"Lee Young-suk","avatar":""},{"name":"Nam Bo-ra","avatar":""},{"name":"Shin Won-ho","avatar":""},{"name":"Oh Tae-kyung","avatar":""},{"name":"Kwon Oh-geon","avatar":""},{"name":"Song You-hyun","avatar":""},{"name":"Park Seon-Hu","avatar":""},{"name":"Choi Bum-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Glorious of My Revenge","My Shining Revenge","찬란한 나의 복수"]', 1784690324246);
