INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bao-tuoi-doi-muoi', 'Cơn Bão Tuổi Đôi Mươi', 'Windmill', 'https://phimimg.com/upload/vod/20250928-1/453ab4e24c739e26b15ea25386fb30e3.jpg', 'https://phimimg.com/upload/vod/20250928-1/bb51e1ca5718ebec676abcb913d0961d.jpg', '<p>Là thước phim thanh xuân khắc họa cuộc sống, tình yêu không mấy tươi sáng của những người trẻ đang mắc kẹt trong ký ức và vết thương lòng. Liệu họ có tìm thấy bình yên và ánh sáng cho tương lai?</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cha Sun-woo","avatar":""},{"name":"Yoo Ji-ae","avatar":""},{"name":"Kim So-hee","avatar":""},{"name":"Oh Jae-moo","avatar":""},{"name":"Choe Min","avatar":""},{"name":"Kim Dong-eui","avatar":""},{"name":"Kim Yong-soo","avatar":""},{"name":"Yoon Ki-won","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["黑色風暴","바람개비"]', 1784690324246);
