INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-si-tuyet-dep', 'Vệ Sĩ Tuyệt Đẹp', 'Exquisite Bodyguard', 'https://phimimg.com/upload/vod/20250926-1/794c1553ecf35d151ad6b7c683ba11ef.jpg', 'https://phimimg.com/upload/vod/20250926-1/125f70d8083bbfa64a178f5dc75236b4.jpg', '<p>Tưởng Nam Anh, Hồ Lệ Phi và Mã yến Ni được ông trùm buôn ma túy quốc tế Bạch Tư Lý ủy thác cho việc hộ tống thiên tài y học Hoàng Gia Đống trở về nước. Tưởng Nam Anh và Hoàng Gia Đống sau khi trải qua sinh tử cùng nhau đã phát sinh tình yêu và cùng nhau bước vào lễ đường. Tuy nhiên, ngày cưới của họ lại trở thành cơn ác mộng khi Hoàng Gia Đông bị bắt cóc. Ban đầu, Hoàng Gia Đông bị tên trùm xã hội đen Lạp Ca truy bắt, sau đó lại bị đồng môn là Bạch Tư Lý lừa dối và kiểm soát để nghiên cứu ma túy. Vì lợi ích chung, hai trùm ma túy lớn là Lạp Ca và Bạch Tư Lý đã cấu kết với nhau. Tưởng Nam Anh bị kẻ thù bao vây, rơi vào tình thế tuyệt vọng. Cô không chỉ phải chiến đấu vì người yêu mà còn chiến đấu vì công lý! Cô sẽ quyết tâm đấu tranh chống ma túy và hy sinh thân minh để diệt trừ cái ác như thế nào?</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cam Đình Đình","avatar":""},{"name":"Lưu Tát Tát","avatar":""},{"name":"Lý Anh Chi","avatar":""},{"name":"Ca Bác Lân","avatar":""},{"name":"Vương Huy","avatar":""},{"name":"Điền Khải","avatar":""},{"name":"Lộ Nhất Bình","avatar":""},{"name":"Trần Hiểu Tuyết","avatar":""},{"name":"La Minh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bodyguard of the Year","绝色保镖"]', 1784690324246);
