INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-tran-thuong-nhac-thuong-nhac-tran-quy-su', 'Bí Ẩn Trấn Thường Nhạc (Thường Nhạc Trấn Quỷ Sự)', 'The Legend Of Bayi''s Grandpa', 'https://phimimg.com/upload/vod/20250926-1/3921732e90723f4f6c2948f30bad68ea.jpg', 'https://phimimg.com/upload/vod/20250926-1/0e86e53fa976ee47eb4e2c6614c954f2.jpg', '<p>Bộ phim kể về câu chuyện Hồ Quốc Hoa bị kẻ gian hãm hại, gài bẫy cờ bạc khiến gia sản mất trắng. Anh ta phá phách đến mức tự đào mộ tổ tiên của mình, ngày một sa sút, thậm chí dàn dựng trò lố bịch như rước cô dâu giấy làm vợ để lừa tiền. Khi cuộc đời không còn hy vọng, anh tình cờ gặp được Tôn Quốc Phụ của Mô Kim Môn, được người chỉ dạy mà bắt đầu tỉnh ngộ. Tuy rằng tạo hoá trêu ngươi, Hồ Quốc Hoa đánh mất tình yêu của mình mãi mãi, nhưng anh đã rút ra bài học từ trải nghiệm đau đớn và thành công chuyển mình từ một thanh niên hư hỏng sang một du hiệp Mô Kim.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Gia Mẫn","avatar":""},{"name":"Trương Long","avatar":""},{"name":"Lưu Bân","avatar":""},{"name":"Vương Khảm","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chang Le Zhen Gui Shi","Changle Town is treacherous","长乐镇诡事","The Legend of Bayi’s Grandpa","Strange Things in Changle Town","常乐镇诡事"]', 1784690324246);
