INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-hoa-thuong', 'Phong Thần: Họa Thương', 'League Of Gods: The Fall Of Sheng', 'https://phimimg.com/upload/vod/20250926-1/22e7c1b558a4a830c1e4a3bfbc20923c.jpg', 'https://phimimg.com/upload/vod/20250926-1/be7fecccca8d69949edc83e922946720.jpg', '<p>Bộ phim lấy bối cảnh cuối triều Thương, khi thiên hạ rối ren, nhân tâm dao động. Trụ Vương hoang dâm vô đạo, tham luyến Đát Kỷ, khiến triều đình suy tàn, bá tánh lầm than. Trong cơn binh lửa loạn thế, các tướng lĩnh và hiền sĩ lần lượt quy tụ dưới cờ Chu Vũ Vương, cùng nhau khởi binh phạt Trụ. Cuộc chiến thần – ma – nhân đan xen, mở ra thiên sử thi bi tráng của thời Phong Thần Bảng.</p>', 'Full', 1, 'single', 'completed', 36, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Diêu Di","avatar":""},{"name":"Vương Quần Thạch","avatar":""},{"name":"Ngô Kỳ","avatar":""},{"name":"Khương Tiểu Đông","avatar":""},{"name":"Cảnh Cảnh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["祸商","League of Gods：The Fall of Shang","封神：祸商"]', 1784690324246);
