INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nien-hoi-bat-dinh', 'Niên Hội Bất Đình', 'Johnny Keep Walking!', 'https://phimimg.com/upload/vod/20250926-1/ffd0fb8b63fbb870ff5d475cd8ffead7.jpg', 'https://phimimg.com/upload/vod/20250926-1/2ba175eee11cf54d0b05fa3083a48fd2.jpg', '<p>Thợ lắp ráp Hồ Kiến Lâm được thăng chức trong bối cảnh sa thải nhân viên, nhưng xuất thân từ nông thôn của anh lại mâu thuẫn với văn hóa doanh nghiệp. Liệu anh có thể vượt qua được chính trị văn phòng và khám phá sự thật?</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Thành Bằng","avatar":""},{"name":"Bạch Khách","avatar":""},{"name":"Trang Đạt Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Johnny Keep Walking","年会不能停！"]', 1784690324246);
