INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-thien-hiep-dao-doan', 'Kinh Thiên Hiệp Đạo Đoàn', 'Tricksters', 'https://phimimg.com/upload/vod/20250926-1/a214a022a8ce930168aab451010f6c4f.jpg', 'https://phimimg.com/upload/vod/20250926-1/955e616219e3031fcd2fa336ed050386.jpg', '<p>Giữa cơn loạn thế, xâu xé giang sơn, tranh giành triều thế, dịch bệnh hoàn hành, các khoản hỗ trợ của triều đình bị gian thần Lưu Chí Khiêm biển thủ, được tiêu cục của Tô gia tuồn trở về kinh thành dưới cái mác tiền thuế. Trên đường áp tiêu, băng trộm 4 người do Trung Ngọc và Thích Phong Hà cầm đầu đã khéo léo xoay đổi tình thế, đem được tiền hỗ trợ về cho các hộ dân gặp nạn. Không ngờ rằng, hành động này đã kéo theo tai họa đến với Tô gia, những nạn nhân được hưởng lợi từ tai họa đó đều bị bức hại dã man. Giữa thời thế nhiễu nhương bất công, cuộc sống của bách tích khó mà êm ấm. Băng trộm hiệp lực rung chuyển đất trời, giành lại an bình cho dân chúng, đánh bật gốc những gốc cây đã bám rễ sâu hoắm!</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bàng Hàn Trần","avatar":""},{"name":"Chu Uy Đồng","avatar":""},{"name":"Vương Nhất Minh","avatar":""},{"name":"Lỗ Tinh Nguyệt","avatar":""},{"name":"Tô Vũ Hàng","avatar":""},{"name":"An Trạch Hào","avatar":""},{"name":"Trương Thư Dương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Now You See Me","惊天侠盗团"]', 1784690324246);
