INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-con-sot-lai-phan-1', 'Những Người Còn Sót Lại (Phần 1)', 'The Last Of Us (Season 1)', 'https://phimimg.com/upload/vod/20250920-1/7bc493b1459221b83c6c8fe5be20edbe.jpg', 'https://phimimg.com/upload/vod/20240309-1/9d3c0aa43547c8e125758450ee2a3dc9.jpg', '<p>Hai mươi năm sau khi nền văn minh hiện đại bị hủy diệt. Joel, một người sống sót cứng cỏi, được thuê để đưa Ellie, một bé gái 14 tuổi, ra khỏi khu cách ly đầy áp bức. Khởi đầu là một công việc nhỏ nhanh chóng trở thành một hành trình tàn khốc, đau lòng, khi cả hai phải băng qua nước Mỹ và phụ thuộc vào nhau để sinh tồn.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pedro Pascal","avatar":""},{"name":"Bella Ramsey","avatar":""},{"name":"Gabriel Luna","avatar":""},{"name":"Merle Dandridge","avatar":""},{"name":"Jeffrey Pierce","avatar":""},{"name":"Anna Torv","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bizdən Geriyə Qalanlar","আমাদের শেষ","Les derniers d''entre nous","Poslední z nás","De sidste som os","האחרונים מבנינו","האחרונים שמבינינו","האחרונים שביננו","آخرین بازمانده‌ی ما","آخرین ما","ザ・ラスト・オブ・アス","ラスト・オブ・アス","ラスアス","라스트 오브 어스","Paskutiniai iš mūsų","Одни из нас","Posledný z nás","ปัจฉิมอเมริกา","Bizden geriye kalanlar","Останні з нас","Những Người Còn Sót Lại","The Last of Us"]', 1784690324246);
