INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-nguoi-con-sot-lai-phan-1', 'Những Người Còn Sót Lại (Phần 1)', 'The Last Of Us (Season 1)', 'những người còn sót lại (phần 1) the last of us (season 1) pedro pascal bella ramsey gabriel luna merle dandridge jeffrey pierce anna torv bizdən geriyə qalanlar আমাদের শেষ les derniers d''entre nous poslední z nás de sidste som os האחרונים מבנינו האחרונים שמבינינו האחרונים שביננו آخرین بازمانده‌ی ما آخرین ما ザ・ラスト・オブ・アス ラスト・オブ・アス ラスアス 라스트 오브 어스 paskutiniai iš mūsų одни из нас posledný z nás ปัจฉิมอเมริกา bizden geriye kalanlar останні з нас những người còn sót lại the last of us', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-kien-va-chien-binh-ong-the-gioi-luong-tu', 'Người Kiến Và Chiến Binh Ong: Thế Giới Lượng Tử', 'Ant-Man And The Wasp: Quantumania', 'https://phimimg.com/upload/vod/20250919-1/a4fc837a2f4b7f03f4b3c0909fd88870.jpg', 'https://phimimg.com/upload/vod/20250919-1/ef49e5ce4d3a81ee0bb6920d42753d4f.jpg', '<p>Scott Lang và Hope Van Dyne trở lại tiếp tục cuộc phiêu lưu của họ với vai trò Người Kiến và Chiến binh Ong. Cùng với cha mẹ của Hope, họ sẽ có chuyến khám phá Lượng Tử Giới, gặp gỡ những sinh vật mới lạ và bắt đầu cuộc hành trình vào thế giới lượng tử.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Jonathan Majors","avatar":""},{"name":"Kathryn Newton","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Katy O''Brian","avatar":""},{"name":"William Jackson Harper","avatar":""},{"name":"Jamie Andrew Cutler","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Mark Weinman","avatar":""},{"name":"Ross Mullan","avatar":""},{"name":"Tom Cl","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ant-Man 3","Homem-Formiga 3","Homem-Formiga e a Vespa 3","Человек-муравей