INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-he-v-phan-1', 'Thế Hệ V (Phần 1)', 'Gen V (Season 1)', 'https://phimimg.com/upload/vod/20250917-1/bc48d46aeb6f0eb2467307794a4afdc5.jpg', 'https://phimimg.com/upload/vod/20250917-1/2d2c325735fab9297739654453d9c54d.jpg', '<p>Tại trường đại học duy nhất dành cho siêu anh hùng ở Mỹ, những sinh viên tài năng đặt ra những ranh giới đạo đức để kiểm tra, cạnh tranh để giành thứ hạng cao nhất của trường đại học và có cơ hội gia nhập đội siêu anh hùng ưu tú của The Seven, Vought International. Khi những bí mật đen tối của trường được đưa ra ánh sáng, họ phải quyết định xem mình muốn trở thành loại anh hùng nào.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jaz Sinclair","avatar":""},{"name":"Lizze Broadway","avatar":""},{"name":"Maddie Phillips","avatar":""},{"name":"London Thor","avatar":""},{"name":"Derek Luh","avatar":""},{"name":"Asa Germann","avatar":""},{"name":"Sean Patrick Thomas","avatar":""},{"name":"Ethan Slater","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Do mundo de The Boys: Gen V","黑袍纠察队：V世代","V世代","The Boys : Gen V","דור הווי","نسل دانشگاهی","نسل V","더 보이즈: 젠 V","제너레이션 V","Пацаны: Поколение Ви","Пацаны: Поколение V","Поколение Ви","The Boys: Varsity","The Boys: Gen V","The Boys Present