INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-he-v-phan-1', 'Thế Hệ V (Phần 1)', 'Gen V (Season 1)', 'thế hệ v (phần 1) gen v (season 1) jaz sinclair lizze broadway maddie phillips london thor derek luh asa germann sean patrick thomas ethan slater do mundo de the boys: gen v 黑袍纠察队：v世代 v世代 the boys : gen v דור הווי نسل دانشگاهی نسل v 더 보이즈: 젠 v 제너레이션 v пацаны: поколение ви пацаны: поколение v поколение ви the boys: varsity the boys: gen v the boys presents: varsity gen v', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-hoa-lau', 'Liên Hoa Lâu', 'Mysterious Lotus Casebook', 'https://phimimg.com/upload/vod/20250708-1/e573b6f9039415f07a9ff3101893f568.jpg', 'https://phimimg.com/upload/vod/20250708-1/6b84d0473f7c9f723eb5dcb37dad3933.jpg', '<p>kể về Lý Tương Di - Môn chủ Tứ Cố Môn nổi tiếng trong võ lâm, sau một trận chiến lớn bị thương nặng và từ đó lui về làm một lang trung không thèm quan tâm danh vọng. Trong cuộc gặp gỡ người bạn mới Phương Đa Bệnh và Địch Phi Thanh - kẻ thù cũ, Tương Di quyết định trở lại giang hồ một lần nữa. Mười năm trước, Lý Tương Di (do Thành Nghị thủ vai) - Chủ Môn phái Tứ Cố Môn, với thanh kiếm Tương Di Đại Kiếm vô song thiên hạ, trở thành ánh sáng của võ lâm chính đạo. Nhưng vì chiến hẹn Đông Hải với Địch Phi Thanh (Tiêu Thuận Nghiêu thủ vai) -Minh Chủ Kim Oanh Môn, hai cao thủ này biến mất khỏi giang hồ. Tứ Cố Môn và Kim Oanh Môn cũng dần dần biến mất khỏi giang hồ. Mười năm sau đó, Lý Liên Hoa (do Thành Nghị thủ vai) - một y sĩ lang thang trong làng, nhận được danh hiệu danh y.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 17, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Thành Nghị","avatar":""},{"name":"Tăng Thuấn Hy","avatar":""},{"name":"Tiêu Thuận Nghiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["吉祥纹莲花楼","หอดอกบัวลายมงคล","Mysterious Lotus Casebook","莲花楼"]', 1784690324246);
