INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-quy-du-dao-tu-than', 'Vùng Đất Quỷ Dữ: Đảo Tử Thần', 'Resident Evil: Death Island', 'https://phimimg.com/upload/vod/20250716-1/49ae690382b268fc589d6f9f0b3f4404.jpg', 'https://phimimg.com/upload/vod/20250716-1/e227452183d87d8dd9cac1538585401b.jpg', '<p>Đặc vụ D.S.O. Leon S. Kennedy đang thực hiện nhiệm vụ giải cứu Tiến sĩ Antonio Taylor khỏi những kẻ bắt cóc, thì bất ngờ bị một phụ nữ bí ẩn ngăn cản. Trong lúc đó, đặc vụ B.S.A.A. Chris Redfield đang điều tra một đại dịch xác sống ở San Francisco mà chưa xác định được nguyên nhân lây nhiễm. Điểm chung duy nhất của các nạn nhân là tất cả đều ghé thăm đảo Alcatraz không lâu trước đó. Lần theo manh mối này, Chris và đồng đội tìm đến hòn đảo, nơi một cơn kinh hoàng khác đang chờ đón họ.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Matthew Mercer","avatar":""},{"name":"Nicole Tompkins","avatar":""},{"name":"Kevin Dorman","avatar":""},{"name":"Stephanie Panisello","avatar":""},{"name":"Erin Cahill","avatar":""},{"name":"Salli Saffioti","avatar":""},{"name":"Daman Mills","avatar":""},{"name":"Lucien Dodge","avatar":""},{"name":"Cristina Valenzuela","avatar":""},{"name":"Frank Todaro","avatar":""},{"name":"Alejandro Saab","avatar":""},{"name":"Bob Carter","avatar":""},{"name":"Isaac Robinson-Smith","avatar":""},{"name":"Bill Butts","avatar":""},{"name":"Brent Mukai","avatar":""},{"name":"Dawn M. Bennett","avatar":""},{"name":"Joe","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởn