INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pokemon-concierge', 'Pokémon Concierge', 'Pokémon Concierge', 'https://phimimg.com/upload/vod/20250912-1/8ed38330b844f82328d2e4742a034b32.jpg', 'https://phimimg.com/upload/vod/20250912-1/99e0c2b770217ad853fa602ba657fc56.jpg', '<p>Chào mừng bạn đến với Khu nghỉ dưỡng Pokémon, nơi yên bình để Pokémon thư giãn và vui chơi. Nhân viên tiền sảnh mới Haru sẽ kết bạn và giúp đỡ vị khách đáng yêu nào trước đây?</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 17, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Non","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Eita Okuno","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["宝可梦礼宾部","هتل‌راهنمای پوکمون","ポケモンコンシェルジュ"]', 1784690324246);
