INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('pokemon-concierge', 'Pokémon Concierge', 'Pokémon Concierge', 'pokémon concierge pokémon concierge non fairouz ai eita okuno 宝可梦礼宾部 هتل‌راهنمای پوکمون ポケモンコンシェルジュ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-nhan-sinh-nhan-sinh-lo-dao', 'Con Đường Nhân Sinh (Nhân Sinh Lộ Dao)', 'Miles To Go', 'https://phimimg.com/upload/vod/20250912-1/dc24e0212e0dc29a8682292fd631228d.jpg', 'https://phimimg.com/upload/vod/20250912-1/a0eb6f83df2c0680fa65b0e5cc9cdfba.jpg', '<p>Bộ phim&nbsp;kể về câu chuyện vào những năm 1980, Cao Gia Lâm, một thanh niên sống ở Cao Gia Câu, phía bắc Thiểm Tây, được mọi người trong làng biết đến với biệt danh học tài &quot;trạng nguyên&quot;. Tuy nhà nghèo nhưng ham đọc sách văn thơ, lòng muốn sánh với trời cao, thầm nhủ phải gột sạch bụi đất quê nghèo. Cao khảo là cơ hội duy nhất để thay đổi vận mệnh của cậu, nhưng ngờ đâu cậu thi trượt. Cậu đã làm việc chăm chỉ để trở thành giáo viên tại một trường tiểu học tư thục, lại bị biên chế giáo viên chèn ép. Cao Gia Lâm rơi xuống vực sâu cuộc sống, sau đó cậu được Lưu Xảo Trân động viên lấy lại niềm vui, kiên trì viết lách, thắp lên hy vọng về cuộc sống, còn khiến lửa tình với Xảo Trân bừng cháy. Việc chú của Gia Lâm trở về làng đã gián tiếp tạo cơ hội cho Gia Lâm làm việc với tư cách là một phóng viên trong quận. Cậu gặp Hoàng Á Bình, một người bạn học cùng chí hướng ở thị trấn, sự bảo vệ thầm lặng của cô gái nhà quê Xảo Trân và màn tỏ tình ấm áp của cô gái Thượng Hải Hoàng Á Bình đã khiến câu rơi vào tình thế tiến thoái lưỡng nan không thể đưa ra lựa chọn. Sau nhiều cuộc đấu tranh và nhiều lựa chọn, chỉ với cây bút bên người câu đã chọn đến Thượng Hải. Những thử thách của số phận nối tiếp nhau, Cao Gia Lâm bất ngờ biết rằng vị trí đại học của cậu đã bị thay thế bởi người bạn Song Tinh khi cậu vừa chạm tuổi ba mươi. Mặc dù vậy, Gia Lâm đã không bị đánh bại, cậu thuận theo thời thế mà làm việc chăm chỉ để học hỏi những kiến thức mới, làm việc chăm chỉ và trải qua những thăng trầm của thế giới, cậu đã viết nên những câu chuyện cuộc sống phi thường của những người bình thường trong làn sóng thời đại.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hiểu","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Trương Gia Ni","avatar":""},{"name":"Vương Thiên Trần","avatar":""},{"name":"Tang Tằng","avatar":""},{"name":"Lâm Vĩnh Kiện","avatar":""},{"name":"Quách Hiểu Đình","avatar":""},{"name":"Lưu Uy","avatar":""},{"name":"Lý Vũ Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["人生之路","The Long Journey","Miles to Go","The road of life"]', 1784690324246);
