INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-truong-bi-an-truong-hoc-noi-tru', 'Ngôi Trường Bí Ẩn (Trường Học Nội Trú)', 'Home School', 'https://phimimg.com/upload/vod/20250724-1/7dc08e6b3fe0e7ef42932ab3f084bb68.jpg', 'https://phimimg.com/upload/vod/20250724-1/b34c5e2f1e8c1583ffd8facfca119644.jpg', '<p>Ngôi Trường Bí Ẩn - Homeschool xoay quanh một ngôi trường nội trú nằm giữa một khu rừng hẻo lánh. Ba năm một lần, trường chọn những học sinh mới đáp ứng các tiêu chí của họ, mỗi thế hệ bao gồm không quá mười ba học sinh. Vnsub.vip Các sinh viên dành tổng cộng ba năm tại trường. Ngôi trường nhằm thu hút những sinh viên giàu có với chương trình giảng dạy độc đáo và tất cả những tiện nghi như ở nhà. Tuy nhiên, Home School có vẻ giống một nhà tù hơn là một trường học với những quy tắc nghiêm ngặt và sự cô lập hoàn toàn.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Hirunkit Changkham","avatar":""},{"name":"Jirawat Sutivanichsak","avatar":""},{"name":"Atthaphan Phunsawat","avatar":""},{"name":"Rachanun Mahawan","avatar":""},{"name":"Ramida Jiranorraphat","avatar":""},{"name":"Wachirawit Ruangwiwat","avatar":""},{"name":"Kay Lertsittichai","avatar":""},{"name":"Juthapich Indrajundra","avatar":""},{"name":"Pattranite Limpatiyakorn","avatar":""},{"name":"Chayapol Jutamas","avatar":""},{"name":"Chayakorn Jutamas","avatar":""},{"name":"Benyapa Jeenprasom","avatar":""},{"name":"Sur","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Home School","Home School Nak Riian Dtong Kang","Nak Riian