INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-ca-sau', 'Hồ Sơ Cá Sấu', 'Crocodile Profile', 'https://phimimg.com/upload/vod/20250904-1/4b525742cce1a1484676d1666fe25c9e.jpg', 'https://phimimg.com/upload/vod/20250904-1/fac89595a8442e8c3d55ea7f6a949abb.jpg', '<p>Hồ sơ cá sấu xoay quanh câu chuyện của vợ chồng Hải và Nguyệt. Cuộc sống của họ bắt đầu thay đổi từ khi Nguyệt được lãnh đạo của mình là Khánh giao cho quản lý một file tài liệu mang tên &quot;hồ sơ cá sấu&quot;, một hồ sơ liên quan đến sai phạm của Tuấn, người điều hành một tập đoàn xã hội đen đội lốt doanh nghiệp và đồng thời là sếp của Hải. Việc Nguyệt phải liên tục phải chạy trốn khỏi sự công kích từ Tuấn đã khiến Hải và gia đình cô không yên ổn trong một thời gian dài. Sự việc chỉ chấm dứt khi có sự tham gia của đội cảnh sát điều tra tội phạm do Kim Vũ và Khắc Dũng chỉ huy. Không chỉ là câu chuyện phá án của cánh sát hình sự, bộ phim còn xoay quanh những cuộc tranh giành quyền lực liên quan đến thị phần làm ăn giữa các phe phái xã hội, cũng như cuộc chiến nội bộ trong ngành công an. Bên cạnh đó là câu chuyện huyết thống giữa chị em Nguyệt - Thu và ông Phương sau sự cố tranh giành tài sản thừa kế từ người mẹ của mình.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Việt Anh","avatar":""},{"name":"Mạnh Trường","avatar":""},{"name":"Bảo Anh","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Ngọc Quỳnh","avatar":""},{"name":"NSƯT Hoàng Hải","avatar":""},{"name":"Kiều Anh","avatar":""},{"name":"Huyền Lizzie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035a