INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-va-cac-cau-be-nha-walter-phan-1', 'Tôi Và Các Cậu Bé Nhà Walter (Phần 1)', 'My Life With The Walter Boys (Season 1)', 'https://phimimg.com/upload/vod/20250830-1/8fcc20412955a344600759c478f2435f.jpg', 'https://phimimg.com/upload/vod/20250830-1/6d9566a24b56782bc161ded4979b8f4c.jpg', '<p>Khi bi kịch đảo lộn cuộc sống của cô, thiếu nữ nọ chuyển đến sống cùng gia đình lớn của người giám hộ ở thị trấn nhỏ và có những bài học mới về tình yêu, hi vọng và tình bạn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Nikki Rodriguez","avatar":""},{"name":"Noah LaLonde","avatar":""},{"name":"Ashby Gentry","avatar":""},{"name":"Johnny Link","avatar":""},{"name":"Corey Fogelmanis","avatar":""},{"name":"Connor Stanhope","avatar":""},{"name":"Zoë Soul","avatar":""},{"name":"Sarah Rafferty","avatar":""},{"name":"Marc Blucas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["My Life with the Walter Boys"]', 1784690324246);
