INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhen-du-hanh-vu-tru-nhen', 'Người Nhện: Du Hành Vũ Trụ Nhện', 'Spider-Man: Across The Spider-Verse', 'https://phimimg.com/upload/vod/20250828-1/8eb367ab5ba2a2b125205cbf4a21107f.jpg', 'https://phimimg.com/upload/vod/20250828-1/a4b7cb04bd30ea4d6fdb3bdbf8058a8f.jpg', '<p>Miles Morales tái xuất trong phần tiếp theo của bom tấn hoạt hình từng đoạt giải Oscar - Spider-Man: Across the Spider-Verse. Sau khi gặp lại Gwen Stacy, chàng Spider-Man thân thiện đến từ Brooklyn phải du hành qua đa vũ trụ và gặp một nhóm Người Nhện chịu trách nhiệm bảo vệ các thế giới song song. Nhưng khi nhóm siêu anh hùng xung đột về cách xử lý một mối đe dọa mới, Miles buộc phải đọ sức với các Người Nhện khác và phải xác định lại ý nghĩa của việc trở thành một người hùng để có thể cứu những người cậu yêu thương nhất.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Shameik Moore","avatar":""},{"name":"Hailee Steinfeld","avatar":""},{"name":"Brian Tyree Henry","avatar":""},{"name":"Luna Lauren Velez","avatar":""},{"name":"Jake Johnson","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Issa Rae","avatar":""},{"name":"Daniel Kaluuya","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Greta Lee","avatar":""},{"name":"Mahershala Ali","avatar":""},{"name":"Amandla Stenberg","avatar":""},{"name":"Jharrel Jerome","avatar":""},{"name":"Andy Samberg","avatar":""},{"name":"Jack Quaid","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id"