INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tam-biet-ly-kha-lac', 'Tạm Biệt, Lý Khả Lạc', 'So Long For Love', 'tạm biệt, lý khả lạc so long for love diêm ni đàm tùng vận ngô kinh tương long triệu tiểu đường phùng lôi lý hổ thành bình an tiểu thất tiểu khả lạc vu cẩn vĩ cao lộ 再见，李可乐 เข่อเล่อ : ด้วยรักจากคุณหมา', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-nam-ruc-ro-2023', 'Tháng Năm Rực Rỡ', 'Burning Years', 'https://phimimg.com/upload/vod/20250827-1/f514ba04ca88f25223b0ed17877e4f4d.jpg', 'https://phimimg.com/upload/vod/20250827-1/7e23526f77601a5aa798dc193381fc74.jpg', '<p>Bộ phim kể về năm người bạn thân có tính cách khác nhau Lâm Chí Hoa, Từ Vệ Bưu, Uông Lỗi, Trương Bằng. Họ bị chia cắt bởi lựa chọn đi trên những con đường khác nhau khi thời đại thay đổi. Theo nhịp bước thay đổi to lớn của xã hội, Lâm Chí Hoa với trái tim tràn đầy chính nghĩa cuối cùng cũng thực hiện được ước mơ làm cảnh sát, lại vì thế mà đứng về chiến tuyến đối lập với người bạn thân đã đi vào con đường sa ngã.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Đông Quân","avatar":""},{"name":"Giá Hồng Tiêu","avatar":""},{"name":"Trương Du Hạo","avatar":""},{"name":"Cam Vân Thần","avatar":""},{"name":"Mã Lệ","avatar":""},{"name":"Lưu Dương","avatar":""},{"name":"Trương Diệu Vũ","avatar":""},{"name":"Ngô Hiểu Lượng","avatar":""},{"name":"Tạ Viên","avatar":""},{"name":"Lưu Bội Kỳ","avatar":""},{"name":"Đỗ Chí Quốc","avatar":""},{"name":"Đỗ Túc Đông","avatar":""},{"name":"Diêu Lỗ","avatar":""},{"name":"Lương Thiên","avatar":""},{"name":"Vương Kỷ","avatar":""},{"name":"Cung Bội Bội","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["北京往事","Burning Years","似火流年"]', 1784690324246);
