INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thang-nam-ruc-ro-2023', 'Tháng Năm Rực Rỡ', 'Burning Years', 'tháng năm rực rỡ burning years hàn đông quân giá hồng tiêu trương du hạo cam vân thần mã lệ lưu dương trương diệu vũ ngô hiểu lượng tạ viên lưu bội kỳ đỗ chí quốc đỗ túc đông diêu lỗ lương thiên vương kỷ cung bội bội 北京往事 burning years 似火流年', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-sinh-an-cu-yeu-dau', 'Tiên Sinh Ẩn Cư Yêu Dấu', 'Dear Mr. Recluse (Dear Mr. Hermitage)', 'https://phimimg.com/upload/vod/20250827-1/96bb3df6546352b5648c3b5ff2360580.jpg', 'https://phimimg.com/upload/vod/20250827-1/ea072b7763265f781cb17f0560b01a02.jpg', '<p>Do bị cộng sự chơi xấu, blogger ẩm thực vô danh Tô Thời Vũ đánh mất dự án đã theo suốt mấy tháng trời. Cô đành phải nhận lời thực hiện nhiệm vụ hết sức vô lý của Lâm Hiếu Kiện, chủ tịch Tập đoàn Cà Phê Hảo Vị. Cô phải khuyên con trai chủ tịch là Lâm Vị từ bỏ việc tu hành trên núi để quay về thừa kế tập đoàn. Tô Thời Vũ vốn cho rằng mình chỉ cần thể hiện tài ăn nói, nào ngờ lại liên tục phải chịu bẽ mặt. Lâm Vị là một vị Bồ Tát sống không sao lay chuyển được. Anh không chỉ có trái tim “một lòng hướng Phật” mà còn sở hữu tài lập luận sắc sảo. Tô Thời Vũ không biết khuyên thế nào, phải bất lực trước bức tường đồng vách sắt này. Trong suốt quá trình, một Tô Thời Vũ bề ngoài ưa náo nhiệt nhưng thực chất bên trong lại vô cùng cô độc đã từ từ học được cách sống độc lập thật sự. Cô vô thức tiến gần cuộc sống của Lâm Vị hơn, còn Lâm Vị cũng dần rung động với Tô Thời Vũ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thang Mẫn","avatar":""},{"name":"Trần Tĩnh Khả","avatar":""},{"name":"Vương Tư Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dear Mr Recluse","Dear Mr Hermitage","亲爱的隐居先生"]', 1784690324246);
