INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tien-sinh-an-cu-yeu-dau', 'Tiên Sinh Ẩn Cư Yêu Dấu', 'Dear Mr. Recluse (Dear Mr. Hermitage)', 'tiên sinh ẩn cư yêu dấu dear mr. recluse (dear mr. hermitage) thang mẫn trần tĩnh khả vương tư hạo dear mr recluse dear mr hermitage 亲爱的隐居先生', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-tinh-yeu', 'Hương Tình Yêu', 'I Feel You Linger In The Air', 'https://phimimg.com/upload/vod/20250827-1/2a2b4a563b2debfc94d84b787e0d4c0e.jpg', 'https://phimimg.com/upload/vod/20250827-1/bc11422aa571964be1188500315672d9.jpg', '<p>Bộ phim nói về Jom, một kiến trúc sư chịu trách nhiệm cải tạo một ngôi nhà lịch sử dọc theo sông Ping. Ở đó, anh phát hiện ra một chiếc rương gỗ chứa đầy những bức vẽ cũ, những bức vẽ trông quen thuộc đến lạ lùng. Nội dung hấp dẫn. Tuy nhiên, Jom không có thời gian để quan tâm đến chúng; anh ấy phải thực hiện một chuyến đi trở lại Bangkok để nhìn thấy tình yêu của mình. Trong nhiều năm, Jom đã đếm từng ngày cho đến khi bạn trai của mình trở về sau chuyến học xa của mình, chỉ để thấy anh ấy đã đính hôn với một người khác.Đau lòng, Jom đến nơi chấp nhận khi phóng xe xuống sông. Trong bóng tối lạnh lẽo, Jom bắt gặp hương thơm ngào ngạt của những bông hoa frangipani tươi từ dòng suối và từ xa, anh có thể phát ra một giọng nói trầm ấm, nhẹ nhàng phát âm rõ ràng, &quot;Pho Jom.&quot;Jom sẽ thấy mình thức dậy ở Chiang Mai những năm 1920.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chanon Santinatornkul","avatar":""},{"name":"Rapheephong Thapsuwan","avatar":""},{"name":"Teeratee Buddeehong","avatar":""},{"name":"Auttharinya Uengsilpsrikul","avatar":""},{"name":"Kantapon Chompupan","avatar":""},{"name":"Attila Arthur Gagnaux","avatar":""},{"name":"Duangjai Hiransri","avatar":""},{"name":"Atcharee Buakhiao","avatar":""},{"name":"Savitree Samipak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["穿越过香气的爱","待到芬芳沁心时","爱的香气","爱情芬芳","我感到你萦绕于空中","萦香爱恋","萦爱飘香","萦香芳恋","缅栀花芳香","芳香爱恋","三生三世鸡蛋花香","恋香","爱意花香","缅栀香恋","香气之爱","夏日栊花香","爱情香气","甜蜜的爱","越过香气的爱恋","我感觉到你在空气中徘徊","လေပြည်ကြားကချစ်ပုံလွှာ","စံကားပန်းမြေမှ ချစ်ခြင်းရနံ့","Hom Klin Khwam Rak","Scent of Memory","คำอธิษฐานของความคิดถึง","Scent of Love","Sweet Smell of Love","The Fragrance of Love","หอมกลิ่นความรัก"]', 1784690324246);
