INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huong-tinh-yeu', 'Hương Tình Yêu', 'I Feel You Linger In The Air', 'hương tình yêu i feel you linger in the air chanon santinatornkul rapheephong thapsuwan teeratee buddeehong auttharinya uengsilpsrikul kantapon chompupan attila arthur gagnaux duangjai hiransri atcharee buakhiao savitree samipak 穿越过香气的爱 待到芬芳沁心时 爱的香气 爱情芬芳 我感到你萦绕于空中 萦香爱恋 萦爱飘香 萦香芳恋 缅栀花芳香 芳香爱恋 三生三世鸡蛋花香 恋香 爱意花香 缅栀香恋 香气之爱 夏日栊花香 爱情香气 甜蜜的爱 越过香气的爱恋 我感觉到你在空气中徘徊 လေပြည်ကြားကချစ်ပုံလွှာ စံကားပန်းမြေမှ ချစ်ခြင်းရနံ့ hom klin khwam rak scent of memory คำอธิษฐานของความคิดถึง scent of love sweet smell of love the fragrance of love หอมกลิ่นความรัก', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-sao-cung-de-thuong-phan-2', 'Dù Sao Cũng Dễ Thương (Phần 2)', 'TONIKAWA: Over The Moon For You (Season 2)', 'https://phimimg.com/upload/vod/20250826-1/bbe65a8ff5d7628e8b908f3411575e9a.jpg', 'https://phimimg.com/upload/vod/20250826-1/0260c8ef35db2a3ebcdcd5c1b2097a5c.jpg', '<p>Yuzaki Hoshizora (Nasa) đã dính tình yêu sét đánh với cô gái xinh đẹp bí ẩn Tsukasa. Một cặp đôi hài hước hạnh phúc với tình yêu, một cuộc sống mới cưới dễ thương và đáng quý bắt đầu!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akari Kito","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Hitomi Ohwada","avatar":""},{"name":"Yuki Nagaku","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Shiori Mikami","avatar":""},{"name":"Misaki Kuno","avatar":""},{"name":"Fumi Hirano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tonikaku Kawaii","Tonikaku Kawaii: SNS","Tonikaku Kawaii: Seifuku","トニカクカワイイ ~制服~","Tonikaku Kawaii: Joshikou-hen","トニカクカワイイ 女子高編","Tonikaku Kawaii: Fly Me to the Moon","トニカクカワイイ Fly Me to the Moon","จะยังไงภรรยาผมก็น่ารัก","TONIKAWA: Over The Moon For You ~High School Days~","Fly Me to the Moon","Tóm Lại Em Rất Dễ Thương","トニカクカワイイ"]', 1784690324246);
