INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-nguoi-gio-cung-ngot-ngao', 'Bên Người Gió Cũng Ngọt Ngào', 'Believe In Love', 'https://phimimg.com/upload/vod/20250825-1/9166b68cc015b236a1fb14788bcb204b.jpg', 'https://phimimg.com/upload/vod/20250825-1/4a72754be9523c19a4dcc2b4a29ed18a.jpg', '<p>Diệp Khuynh Thừa là nhân vật phong vân của thành Vinh, anh và Đường Cửu Cửu là thanh mai trúc mã, nhưng vì nguyên nhân gia đình mà phải rời đi từ nhỏ. Nhiều năm sau, Đường Cửu Cửu đã trở thành một nữ pha chế rượu, vô tình nhận nhầm Trì Mặc Nhiên là bạn thuở nhỏ. Lần trở về này, Diệp Khuynh Thừa không chỉ để thực hiện lời hứa năm xưa, mà còn để cưng chiều và theo đuổi tình yêu, ngọt ngào đến tận xương tủy.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324246);
