INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoc-cot-dao', 'Ngọc Cốt Dao', 'The Longest Promise', 'https://phimimg.com/upload/vod/20250813-1/f21b147903b4e86271440e76d3ee0d2c.jpg', 'https://phimimg.com/upload/vod/20250813-1/e6bf01c709c2c30559f71e499106eebd.jpg', '<p>Thời Ảnh - thế tử Không Tang cao ngạo lạnh lùng và Chu Nhan - quận chúa Xích tộc nhiệt tình trượng nghĩa nên duyên định mệnh nhờ ơn một đóa hoa, rồi lại tình cờ trở thành thầy trò bầu bạn ba năm. Tà ác trỗi dậy, Không Tang đứng trước nguy cơ diệt vong. Thời Ảnh lầm tưởng Chỉ Uyên – giao nhân cùng lớn lên với Chu Nhan là Hải hoàng, do đó đã tự tay phong ấn Chỉ Uyên. Cuối cùng, Chu Nhan rút Ngọc Cốt đâm về phía Thời Ảnh, lời sấm thành sự thật. Thế nhưng số phận đã sớm thay đổi kể từ ngày trái tim ai đó trao đi...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Chiến","avatar":""},{"name":"Nhậm Mẫn","avatar":""},{"name":"Vương Sở Nhiên","avatar":""},{"name":"Phương Dật Luân","avatar":""},{"name":"Hàn Đống","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["玉骨谣","The Longest Promisse","옥골요","ลำนำกระดูกหยก","โชคชะตาฟ้าลิขิต ความคะนึงหากลายเป็นชะตากรรม","Jade Bone Ballad","玉骨遥"]', 1784690324246);
