INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-xe-ban-sung-phan-1', 'Đua Xe Bắn Súng (Phần 1)', 'Twisted Metal (Season 1)', 'https://phimimg.com/upload/vod/20250812-1/7e7db913d37191bcbee44e0b70b86b1c.jpg', 'https://phimimg.com/upload/vod/20250812-1/612792b7cdf274e6a8622b9ad4a742e3.jpg', '<p>Một người ngoài cuộc mồm mép và không có ký ức về quá khứ của mình sẽ có cơ hội có một cuộc sống tốt hơn, nhưng chỉ khi anh ta có thể chuyển thành công một gói hàng bí ẩn xuyên qua vùng đất hoang hậu tận thế. Với sự giúp đỡ của một tên trộm xe cầm rìu hung hãn, anh ta sẽ phải đối mặt với những tên cướp man rợ lái những phương tiện hủy diệt và những mối nguy hiểm khác trên con đường rộng mở, bao gồm cả một chú hề loạn trí lái chiếc xe bán kem quá quen thuộc.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anthony Mackie","avatar":""},{"name":"Stephanie Beatriz","avatar":""},{"name":"Nuufolau Joel Seanoa","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Anthony Carrigan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Twisted Metal: Сериалът","Искорёженный металл","Поплавлений метал","Покручений метал","Twisted Metal Live Action","Twisted Metal"]', 1784690324246);
