INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-chien-tranh-vu-tru', 'Siêu Chiến Tranh Vũ Trụ', 'Hyper Space War', 'https://phimimg.com/upload/vod/20250811-1/43d4f48b7f067dce8da7888e1d951a4b.jpg', 'https://phimimg.com/upload/vod/20250811-1/04b5ad3a7db87db9f382476c3255bf38.jpg', '<p>Vì không kiểm soát được năng lượng của các quái vật trong thẻ bài Siêu Không Gian, Andy thường né tránh các trận thi đấu. Sau khi vô tình có được một hộp thẻ bài huyền thoại, cậu quyết định lên đường tìm kiếm bốn thẻ bài Siêu Không Gian huyền thoại để thực hiện điều ước tìm được anh trai và cứu thế giới khỏi nguy hiểm.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 16, 2023, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hạo Thiên","avatar":""},{"name":"Từ Trình Hạo","avatar":""},{"name":"Phùng Mẫn","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Chao Yuan Jue Zhan","Chaoyuanjuezhan","超元绝战"]', 1784690324246);
