INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-ve-si-2023', 'Nữ Vệ Sĩ', 'Shero', 'https://phimimg.com/upload/vod/20250808-1/b5f7e47ffa4b57f9d7870b84275050ef.jpg', 'https://phimimg.com/upload/vod/20250808-1/80dcac09f0a6c46875f6584b7968e36d.jpg', '<p>Doãn Thần và Doãn Tịch là một cặp chị em rất thân thiết. Doãn Thần là một nhiếp ảnh gia tài năng trong khi Doãn Tịch điều hành một công ty vệ sĩ nữ, SHERO. Trong một lần thực hiện nhiệm vụ ở nước ngoài, Doãn Tịch bị một sát thủ bí ẩn tấn công và mất tích. Đau khổ vì mất em gái, Doãn Thần quyết định gia nhập SHERO với tư cách vệ sĩ để tiếp nối di sản của Doãn Tịch và điều tra vụ mất tích của em gái cô.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2023, 'Lồng Tiếng', 'FHD', 'Singapore', 0, '[{"name":"Bạch Vi Tú","avatar":""},{"name":"Trần La Mật Âu","avatar":""},{"name":"Huỳnh Tư Điềm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["女英雄","女保镖","Shero"]', 1784690324246);
