INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-de-nhat-bo-trieu-ca-phong-van', 'Phong Thần Đệ Nhất Bộ: Triều Ca Phong Vân', 'Creation Of The Gods I: Kingdom Of Storms', 'https://phimimg.com/upload/vod/20250511-1/1fa346c639c4eda3bbdadecbfd510b67.jpg', 'https://phimimg.com/upload/vod/20250511-1/aec12cc70425c34292bd63e2b292048c.jpg', '<p>Nội dung phim bắt đầu khi đất nước phải đối mặt với hàng loạt hiện tượng kỳ lạ mà trời đất bất ngờ trừng phạt. Trước tình thế đó, Khương Tử Nha quyết định rời khỏi núi Côn Luân và mang theo Bảng Phong Thần đến chỗ Thương Vương Ân Thọ để giải cứu chúng sinh khỏi cảnh lầm than. Khương Tử Nha không biết rằng ngọn nguồn của mọi tai họa đều đến từ sự thông đồng giữa Thương vương Ân Thọ, yêu hồ Đát Kỷ và Thân Công Báo. Điều này tạo nên một cuộc đối đầu gay go và quyết liệt giữa cái thiện và cái ác. Thương vương Ân Thọ đã trở thành một đại ác nhân. Trong khi đó, Thân Công Báo sở hữu võ công cao cường, có khả năng tách đầu ra khỏi cơ thể, tạo ra mối nguy hiểm lớn cho Khương Tử Nha và đồng đội.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ô Nhĩ Thiện","avatar":""},{"name":"Phí Tường","avatar":""},{"name":"Lý Tuyết Kiện","avatar":""},{"name":"Hoàng Bột","avatar":""},{"name":"Vu Thích","avatar":""},{"name":"Thử Sa","avatar":""},{"name":"Trần Mục Trì","avatar":""},{"name":"Na Nhiên","avatar":""},{"name":"Hạ Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Creation of The Gods 1: Kingdom of Storms","封神演义系列·龙之战","봉신제일부: 조가풍운","Creation of the Gods I Kingdom of Storms","آفرینش خدایان ۱: پادشاهی طوفان‌ها","خلقت خدایان ۱: قلمرو طوفان‌ها","封神三部曲1","封神三部曲之妖乱国殇","Phong Thần: Phần 1 - Phong Vân Triều Ca","Création des dieux : Le royaume des tempêtes","Creation of the Gods I","Criação dos Deuses 1: Reino das Tempestades","봉신 제1부: 조가풍운","La creación de los dioses el reino de las tormentas","封神：朝歌风云","封神第一部之朝歌风云","Creation of the Gods I: Kingdom of Storms","Feng Shen 1: Zhaoge Feng Yun","Création des dieux, Le royaume des tempêtes","Criação dos Deuses 1","Investidura dos Deuses Parte 1","封神第一部：朝歌風雲","封神第一部","封神第一部：朝歌风云"]', 1784690324246);
