INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-than-de-nhat-bo-trieu-ca-phong-van', 'Phong Thần Đệ Nhất Bộ: Triều Ca Phong Vân', 'Creation Of The Gods I: Kingdom Of Storms', 'phong thần đệ nhất bộ: triều ca phong vân creation of the gods i: kingdom of storms ô nhĩ thiện phí tường lý tuyết kiện hoàng bột vu thích thử sa trần mục trì na nhiên hạ vũ creation of the gods 1: kingdom of storms 封神演义系列·龙之战 봉신제일부: 조가풍운 creation of the gods i kingdom of storms آفرینش خدایان ۱: پادشاهی طوفان‌ها خلقت خدایان ۱: قلمرو طوفان‌ها 封神三部曲1 封神三部曲之妖乱国殇 phong thần: phần 1 - phong vân triều ca création des dieux : le royaume des tempêtes creation of the gods i criação dos deuses 1: reino das tempestades 봉신 제1부: 조가풍운 la creación de los dioses el reino de las tormentas 封神：朝歌风云 封神第一部之朝歌风云 creation of the gods i: kingdom of storms feng shen 1: zhaoge feng yun création des dieux, le royaume des tempêtes criação dos deuses 1 investidura dos deuses parte 1 封神第一部：朝歌風雲 封神第一部 封神第一部：朝歌风云', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-bo-gia', 'Đặc Vụ Bố Già', 'Transfusion', 'https://phimimg.com/upload/vod/20250804-1/cf63146feb93b6c0f2273ccf0ae9e275.jpg', 'https://phimimg.com/upload/vod/20250804-1/1c33173857db8efee2639d7f174ef799.jpg', '<p>Sau khi rời khỏi quân đội, Ryan trở về và cố hòa nhập với cuộc sống bình thường, xây dựng một mái ấm bình yên. Nhưng nào ngờ, cựu lính đặc nhiệm lại phải dấn thân thế giới ngầm để cứu con trai.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Sam Worthington","avatar":""},{"name":"Matt Nable","avatar":""},{"name":"Phoebe Tonkin","avatar":""},{"name":"Edward Carmody","avatar":""},{"name":"Susie Porter","avatar":""},{"name":"Jeremy Lindsay Taylor","avatar":""},{"name":"Sam Parsonson","avatar":""},{"name":"Sam Cotton","avatar":""},{"name":"George Houvardas","avatar":""},{"name":"Damien Strouthos","avatar":""},{"name":"Brad McMurray","avatar":""},{"name":"Julian Maroun","avatar":""},{"name":"Alex Malone","avatar":""},{"name":"Trystan Go","avatar":""},{"name":"Alison McGirr","avatar":""},{"name":"Darius Williams","avatar":""},{"name":"Mike Dun","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Transfusion - A Father''s Mission","Transfusion","Vlastní krev"]', 1784690324246);
