INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-tot-dep-hon', 'Cuộc Sống Tốt Đẹp Hơn', 'The Better Life', 'https://phimimg.com/upload/vod/20250804-1/1b158cab81b4359354d92982a121d9ba.jpg', 'https://phimimg.com/upload/vod/20250804-1/e58961d5460f36418666167ec00e8278.jpg', '<p>Chàng tài xế bị suy thận là Vươn Hữu Tài tình cờ gặp Lý Trí Viễn, một người đàn ông là thế hệ thứ hai trong một gia đình quyền lực, bị mắc bệnh tim bẩm sinh. Hai người vô tình nhận ra họ rất hợp nhau và đã ký kết &quot;thỏa thuận sinh tử&quot;. Nhằm thực hiện tâm nguyện cuối cùng của Vương Hữu Tài, Lý Trí Viễn đã giúp vương Hữu Tài hẹn hò với vợ, Vươn Hữu Tài thì khuyến khích Lý Trí Viễn tìm lại mối tình đầu của mình. Cuộc hành trình cuối cùng của cuộc đời họ đã kết thúc với nhiều nụ cười và nước mắt, và đó là câu chuyện về sự giúp đỡ và tương trợ lẫn nhau trong suốt cuộc hành trình cuối cùng đầy ý nghĩa.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Shenyang","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Shen Chunyang","avatar":""},{"name":"Yuxi Chen","avatar":""},{"name":"Ma Yue","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Better Life","穷兄富弟"]', 1784690324246);
