INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-bao-thu', 'Bộ Đôi Báo Thủ', 'Ransomed', 'https://phimimg.com/upload/vod/20250804-1/07ce9b334c6b4a144fb87aa92bac9915.jpg', 'https://phimimg.com/upload/vod/20250804-1/5a00f132e225762eda1a511fee076a02.jpg', '<p>Lấy cảm hứng từ một sự kiện có thật - lần đầu tiên một nhà ngoại giao bị bắt cóc trong lịch sử Hàn Quốc, bộ phim hành động Ransomed (tựa Việt: Bộ Đôi Báo Thủ) xoay quanh hành trình giải cứu người đồng nghiệp đang mất tích của nhà ngoại giao Min-jun (Ha Jung-woo thủ vai) và tài xế taxi Pan-su (Ju Ji-hoon thủ vai) ở Beirut, Lebanon vào năm 1986.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ha Jung-woo","avatar":""},{"name":"Ju Ji-hoon","avatar":""},{"name":"Lim Hyung-kook","avatar":""},{"name":"Kim Eung-soo","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Park Hyuk-kwon","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Choi Jung-woo","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Marcin Dorociński","avatar":""},{"name":"Fehd Benchemsi","avatar":""},{"name":"Anas El Baz","avatar":""},{"name":"Nisrine Adam","avatar":""},{"name":"Han Soo-hyun","avatar":""},{"name":"Chun Sin-hwan","avatar":""},{"name":"Seo Young-sam","avatar":""},{"name":"Lee San","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kidnapped","피랍","Unofficial Operation","عملية غير رسمية","فدية","คู่ระห่ำไถ่ข้ามโลก","คู่ระห่ำ ไถ่ข้ามโลก","Ransomed","Неофициальная операция","Resgatado","Bi-gong-sik-jak-jeon",