INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-doi-bao-thu', 'Bộ Đôi Báo Thủ', 'Ransomed', 'bộ đôi báo thủ ransomed ha jung-woo ju ji-hoon lim hyung-kook kim eung-soo kim jong-soo park hyuk-kwon yoo seung-mok jang so-yeon choi jung-woo burn gorman marcin dorociński fehd benchemsi anas el baz nisrine adam han soo-hyun chun sin-hwan seo young-sam lee san kidnapped 피랍 unofficial operation عملية غير رسمية فدية คู่ระห่ำไถ่ข้ามโลก คู่ระห่ำ ไถ่ข้ามโลก ransomed неофициальная операция resgatado bi-gong-sik-jak-jeon 비공식작전', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diabolik-ban-la-ai', 'Diabolik Bạn Là Ai', 'Diabolik: Who Are You?', 'https://phimimg.com/upload/vod/20250802-1/7cbe2626844e277c9b6d96e6018cf7a9.jpg', 'https://phimimg.com/upload/vod/20250802-1/742744e71d58e9fee73b8e53bd908d38.jpg', '<p>Bị một băng cướp ngân hàng tàn ác bắt giữ, kẻ thù không đội trời chung là Diabolik và thanh tra Ginko buộc phải hợp tác để sống sót. Trong khi đó, Eva Kant và Altea – người yêu của họ – lập một liên minh bất ngờ để giải cứu, còn Diabolik tiết lộ quá khứ bí ẩn của mình với vị thanh tra.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Giacomo Gianniotti","avatar":""},{"name":"Miriam Leone","avatar":""},{"name":"Valerio Mastandrea","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Pier Giorgio Bellocchio","avatar":""},{"name":"Chiara Martegiani","avatar":""},{"name":"Massimiliano Rossi","avatar":""},{"name":"Mario Sgueglia","avatar":""},{"name":"Francesco Turbanti","avatar":""},{"name":"Emanuele Linfatti","avatar":""},{"name":"Michele Ragno","avatar":""},{"name":"Amanda Campana","avatar":""},{"name":"Andrea Arru","avatar":""},{"name":"Max Gazzè","avatar":""},{"name":"Carolina C","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Diabolik - Chi sei?"]', 1784690324247);
