INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diabolik-ban-la-ai', 'Diabolik Bạn Là Ai', 'Diabolik: Who Are You?', 'diabolik bạn là ai diabolik: who are you? giacomo gianniotti miriam leone valerio mastandrea monica bellucci pier giorgio bellocchio chiara martegiani massimiliano rossi mario sgueglia francesco turbanti emanuele linfatti michele ragno amanda campana andrea arru max gazzè carolina c diabolik - chi sei?', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-tram-co-doc-phan-1', 'Không Trạm Cô Độc (Phần 1)', 'Beacon 23 (Season 1)', 'https://phimimg.com/upload/vod/20250724-1/13127ca31e3a03b8bf61b89f793328af.jpg', 'https://phimimg.com/upload/vod/20250724-1/cd169727f053532ed9bf3ea8ffd712d3.jpg', '<p>Halan là người duy nhất vận hành Beacon 23, ngọn hải đăng cô độc giữa các vì sao trong không gian sâu thẳm. Một ngày nọ, khi phi thuyền Crest gặp tai nạn gần hải đăng, Halan chỉ kịp thời cứu được Aster - một đặc vụ được chính phủ cử đến. Mắc kẹt cùng nhau ở nơi tận cùng vũ trụ, một cuộc chiến tâm lý căng thẳng bắt đầu diễn ra giữa hai con người đang cố gắng che giấu những bí mật của riêng mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lena Headey","avatar":""},{"name":"Stephan James","avatar":""},{"name":"Natasha Mumba","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Маяк 23","فانوس راهنما ۲۳","Beacon 23"]', 1784690324247);
