INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-quyet-cua-do-vo-dinh', 'Quỷ Quyệt: Cửa Đỏ Vô Định', 'Insidious: The Red Door', 'https://phimimg.com/upload/vod/20250731-1/3b28db1eec65c01ddc8f0f8887bbc7e2.jpg', 'https://phimimg.com/upload/vod/20250731-1/6bf7cce66b598e7cc98ef84b6a5ccd15.jpg', '<p>Phần tiếp theo của loạt phim kinh dị Insidious với sự góp mặt của dàn diễn viên gốc thuộc gia đình Lambert. Câu chuyện xoay quanh quyết định mở ra cánh cửa đỏ và đi sâu vào Cõi Vô Định của Josh (Patrick Wilson) và Dalton (Ty Simpkins) - nay đã trưởng thành - để tiêu diệt một lần và mãi mãi những con quỷ đang ám ảnh cả gia đình mình. Từ đó họ phải đối mặt với quá khứ tăm tối và đầy bí ản của gia đình, nơi những ám ảnh kinh hoàng nhất đang rình rập. Dàn diễn viên gốc từ Insidious trở lại gồm Patrick Wilson (kiêm vai trò đạo diễn), Ty Simpkins, Rose Byrne và Andrew Astor. Cũng có sự tham gia của Sinclair Daniel và Hiam Abbass. Phim do Jason Blum, Oren Peli, James Wan và Leigh Whannell sản xuất. Kịch bản được viết bởi Scott Teems dựa trên câu chuyện của Leigh Whannell, và nhân vật do Leigh Whannell tạo ra.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ty Simpkins","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Sinclair Daniel","avatar":""},{"name":"Hiam Abbass","avatar":""},{"name":"Andrew Astor","avatar":""},{"name":"Juliana Davies","avatar":""},{"name":"Steve Coulter","avatar":""},{"name":"Peter Dager","avatar":""},{"name":"Joseph Bishara","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Justin Sturgis","avatar":""},{"name":"David Call","avatar":""},{"name":"Stephen Gray","avatar":""},{"name":"Robin S. Walker","avatar":""},{"name":"Bridget K","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Астрал 5","인시디어스 5","Insidious 5","Insidious - La porta rossa","La Noche Del Demonio: La Puerta Roja","Quỷ Quyệt 5: Cửa Đỏ Vô Định","인시디어스: 챕터 5","วิญญาณตามติด: ประตูผีผ่าน","วิญญาณตามติด 5","兒凶：血色大門","Ruhlar Bölgesi: Kırmızı Kapı","इनसिडियस द रेड डोर","陰兒房：鬼門陰深處","Insidious: A vörös ajtó","Tūnąs tamsoje: raudonos durys","Naznaczony: Czerwone drzwi","Παγιδευμένη Ψυχή: Η Πορφυρή Πόρτα","Sobrenatural: A Porta Vermelha","Insidious: A Porta Vermelha","Insidious: Červené dveře","הרוע שבפנים: הדלת האדומה","La noche del demonio: La puerta roja","Astralna Podmuklost: Crvena Vrata","Астрална Подмуклост: Црвена Врата","Коварен капан: Червената врата","La noche del Demonio: La Puerta Roja","潜伏5：红门","Astraal: punane uks","インシディアス: 赤い扉","Астрал 5: Красная дверь","Insidious: La puerta roja","Астрал: Червоні двері","غدار: الخوف من الظلام","توطئه‌آمیز: در قرمز","Insidious Chapter 5","Insidious - The Red Door","Insidious The Red Door","Insidious, The Red Door","Insidious: Chapter 5 - The Red Door","Sobrenatural A Porta Vermelha","Insidious: The Red Door"]', 1784690324247);
