INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-tia-chop-phan-9', 'Người Hùng Tia Chớp (Phần 9)', 'The Flash (Season 9)', 'https://phimimg.com/upload/vod/20250729-1/b3f83a585bab3206906db280588f8a74.jpg', 'https://phimimg.com/upload/vod/20250729-1/341fcfebbb3c3aa10cce59e4b13280ac.jpg', '<p>Phim dựa theo một nhân vật của DC Comics, trong 1 thí nghiệm tại Starling City, anh chàng Barry đã vô tình bị ảnh hưởng bởi vụ nổ trong thí nghiệm khiến anh hôm mê bất tỉnh nhiều ngày trong bệnh viện. Khi tỉnh dậy, anh ta đã phát hiện ra rằng mình có khả năng đặc biệt đó là tăng tốc độ cơ thể và di chuyển siêu nhanh. Kể từ đây, huyền thoại về người anh hùng Flash bắt đầu.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Grant Gustin","avatar":""},{"name":"Candice Patton","avatar":""},{"name":"Danielle Panabaker","avatar":""},{"name":"Danielle Nicolet","avatar":""},{"name":"Kayla Compton","avatar":""},{"name":"Brandon McKnight","avatar":""},{"name":"Jon Cor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["闪电侠 (格兰特·古斯汀)","The Flash (2014)","The Flash 2014","פלאש","플래시","The Flash"]', 1784690324247);
