INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-phong-thap-tam-tai-nghi-an-13-nam', 'Trần Phong Thập Tam Tái (Nghi Án 13 Năm)', 'Thirteen Years Of Dust', 'https://phimimg.com/upload/vod/20250728-1/7ff0e46c7818e81fdd6e0b46ea430e41.jpg', 'https://phimimg.com/upload/vod/20250728-1/cd85f7c9832c7797390aa6b1f0ebea42.jpg', '<p>Vụ án giết người đặc biệt chưa được giải quyết vào năm 1997 tái hiện 13 năm sau, cảnh sát hình sự Vệ Tranh Vinh, người chưa bao giờ lần ra hung thủ thực sự, đã bị sốc và rời khỏi tiền tuyến. Nhiều sự trùng hợp ngẫu nhiên của vụ án đã đưa người thầy và người học việc lại với nhau để truy tìm thủ phạm thực sự.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Kiến Bân","avatar":""},{"name":"Trần Hiểu","avatar":""},{"name":"Trần Diệc Hiên","avatar":""},{"name":"Lưu Dịch Quân","avatar":""},{"name":"Kha Lam","avatar":""},{"name":"Vương Hựu Quân","avatar":""},{"name":"Cao Vĩnh Quân","avatar":""},{"name":"Tô Thịnh Minh","avatar":""},{"name":"Hầu Lệ Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["尘封十三载","Тринадцать покрытых пылью лет","Тринадцать лет забвения","Thirteen Years of Dust"]', 1784690324247);
