INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tran-phong-thap-tam-tai-nghi-an-13-nam', 'Trần Phong Thập Tam Tái (Nghi Án 13 Năm)', 'Thirteen Years Of Dust', 'trần phong thập tam tái (nghi án 13 năm) thirteen years of dust trần kiến bân trần hiểu trần diệc hiên lưu dịch quân kha lam vương hựu quân cao vĩnh quân tô thịnh minh hầu lệ vân 尘封十三载 тринадцать покрытых пылью лет тринадцать лет забвения thirteen years of dust', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-hau-but-luc', 'Thất Hầu Bút Lục', 'Spirits In Chinese Brushes', 'https://phimimg.com/upload/vod/20250728-1/609ae1351121c5d9503401314d7d9ed8.jpg', 'https://phimimg.com/upload/vod/20250728-1/cd8acd54bd4edd5655847118acf3a3a0.jpg', '<p>Hai nghìn năm trước, hậu nhân của phái Âm Dương cảm thán việc Tần Thủy Hoàng đốt sách chôn nho, tiếc thương A Phòng Cung bị thiêu hủy. Với tâm nguyện “không để tài hoa thiên hạ trôi vào quên lãng”, ông đã bắt đầu thu thập nguyên thần của các văn nhân thi sĩ khi họ qua đời, luyện thành “bút”, giữ cho tài hoa được lưu truyền muôn đời. Hai nghìn năm sau, sinh viên bình thường La Trung Hạ vô tình có được Thanh Liên Di Bút của Lý Bạch, từ đó sở hữu siêu năng lực do bút linh mang lại. Nhưng bình yên chẳng kéo dài, nhiều thế lực thèm khát sức mạnh to lớn của Thanh Liên Di Bút, khiến La Trung Hạ liên tục rơi vào nguy hiểm. Để thoát khỏi tranh chấp, anh nỗ lực tìm cách trả lại bút nhưng hết lần này đến lần khác thất bại, thay vào đó lại bước vào mối nhân duyên khó dứt với “Quản Thành Thất Hầu”…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Jiaxiang","avatar":""},{"name":"Shan Xin","avatar":""},{"name":"Mengqiao Zhao","avatar":""},{"name":"Zhang Enze","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["SPiritsin Chinese Brushes","Qi Hou Bilu","七侯笔录"]', 17846903