INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('paw-patrol-phim-sieu-dang', 'PAW Patrol: Phim Siêu Đẳng', 'PAW Patrol: The Mighty Movie', 'paw patrol: phim siêu đẳng paw patrol: the mighty movie mckenna grace taraji p. henson marsai martin christian convery ron pardo lil rel howery kim kardashian chris rock serena williams alan kim brice gonzález north west saint west james marsden kristen bell finn lee-epp christian corrao luxto la pat'' patrouille 2 paw patrol 2 paw patrol: the movie 2 퍼피 구조대 2 ขบวนการเจ้าตูบสี่ขา เดอะ ไมตี้ มูฟวี paw patrol der mighty kinofilm patrulha pata: o super filme paw patrol la super pelicula paw patrol: superfilmen psići u ophodnji: moćan film 汪汪队立大功大电影2：超能大冒险 käpapatrull: vägev film paw patrol: the mighty movie', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-duyen-truyen', 'Tiên Duyên Truyện', 'Fate Of Devil: Devastation', 'https://phimimg.com/upload/vod/20250725-1/3b3e16d276c46089cbec5c3ace30b497.jpg', 'https://phimimg.com/upload/vod/20250725-1/cc91f613e2f4da4666a779fe14f63109.jpg', '<p>Thiếu niên có tính cách nổi loạn và ngang ngược Du Phương vô tình tiết lộ nguồn gốc của mình là hậu duệ của tộc quỷ để giải cứu người bạn đồng hành Thái Vi, người đang điều tra vụ mất tích của thiếu nữ. Hơn nữa do sức mạnh của viên thuốc ma thuật mà Hoàng Phiên Tinh phong ấn trong cơ thể anh nên anh ta bị quốc sư Huyền Chân và và tân quỷ vương Ogino truy đuổi. May mắn thay, sư phụ của Du Phương là Chu Cát Thập Phương, đã giúp và hướng dẫn họ đến chùa Tiên Phong, nơi họ hy vọng sẽ tìm thấy Đại sư Vô Trần để giải mã cuốn sách trời và giải quyết vụ án. Trên đường trốn thoát, Du Phương buộc phải hợp lực với người anh em song sinh Ogino để chiến đấu chống lại những kẻ sát nhân tàn nhẫn Hungry Shura và Shinshimaru do Huyền Chân phái đến.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tín Triết","avatar":""},{"name":"Hoàng Tao","avatar":""},{"name":"Chu Nha","avatar":""},{"name":"Vương Cương","avatar":""},{"name":"Hoàng Hải","avatar":""},{"name":"Lý Gia Văn","avatar":""},{"name":"Vương Vĩ An","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fate Of Devil Devastation","Fate of Devil","Legend of Immortal Fate","仙缘传"]', 1784690324247);
