INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-mat-na-revice-hau-truyen', 'Hiệp Sĩ Mặt Nạ: Revice Hậu Truyện', 'Revice Forward: Kamen Rider Live & Evil & Demons', 'https://phimimg.com/upload/vod/20250725-1/a0d966c382bd534c888ba0f29888d4cc.jpg', 'https://phimimg.com/upload/vod/20250725-1/2d87fe5f080096e78862033d5bc4a8fe.jpg', '<p>Sau sự sụp đổ của tổ chức phòng chống ác ma bù nhìn Fenix, hai cựu thành viên Daiji và Hiromi tiếp tục dẫn dắt tổ chức dưới tên mới là Blue Bird với sứ mệnh bảo vệ hòa bình cho người dân. Giữa lúc một tổ chức cực đoan bắt cóc trẻ em đang hoành hành và một ác ma mới xuất hiện, Hiromi bất ngờ bị truy nã vì có liên quan đến các vụ bắt cóc. Trong khi đó, ác ma bên trong Daiji thì lại bắt đầu phản bội chính cậu.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Wataru Hyuga","avatar":""},{"name":"Junya Komatsu","avatar":""},{"name":"Kentaro Maeda","avatar":""},{"name":"Ayaka Imoto","avatar":""},{"name":"Noritaka Hamao","avatar":""},{"name":"Hikari Kabashima","avatar":""},{"name":"Claud Hachijoin","avatar":""},{"name":"Uji Kiyotaka","avatar":""},{"name":"Kazuya Tanabe","avatar":""},{"name":"Ryosuke Takahashi","avatar":""},{"name":"Yu Imari","avatar":""},{"name":"Hayate Kajihara","avatar":""},{"name":"Rima Matsuda","avatar":""},{"name":"Sakura Miyajima","avatar":""},{"name":"Hiroshi Doki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Kamen Rider Revice Epilogue","Ribaisu Fōw