INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hiep-si-mat-na-revice-hau-truyen', 'Hiệp Sĩ Mặt Nạ: Revice Hậu Truyện', 'Revice Forward: Kamen Rider Live & Evil & Demons', 'hiệp sĩ mặt nạ: revice hậu truyện revice forward: kamen rider live & evil & demons wataru hyuga junya komatsu kentaro maeda ayaka imoto noritaka hamao hikari kabashima claud hachijoin uji kiyotaka kazuya tanabe ryosuke takahashi yu imari hayate kajihara rima matsuda sakura miyajima hiroshi doki kamen rider revice epilogue ribaisu fōwarudo: kamen raidā raibu ando ebiru ando demonzu リバイスforward 仮面ライダーライブ&エビル&デモンズ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-truong-sinh-tu-khuc-hat-cua-chim-ca-ran-doc', 'Đấu Trường Sinh Tử: Khúc Hát Của Chim Ca & Rắn Độc', 'The Hunger Games: The Ballad Of Songbirds & Snakes', 'https://phimimg.com/upload/vod/20250725-1/57ed42eda541fe8b680f81de898fb46a.jpg', 'https://phimimg.com/upload/vod/20250725-1/c1ddb08dd741beb5b71a937c2fd85aa1.jpg', '<p>Phần tiền truyện này theo chân Coriolanus Snow (Tom Blyth thủ vai) trẻ tuổi, chính là vị Tổng thống Snow sau này. Hiệu trưởng Casca Highbottom (do Peter Dinklage thủ vai) triệu tập tất cả mọi người cho Lễ chiêu quân lần thứ 10, và chuẩn bị lựa chọn vật tế từ 12 quận. Lúc này, Coriolanus Snow được chỉ định trở thành cố vấn cho trò chơi với vai trò là trợ giúp vật tế trong đấu trường và là cố vấn của Lucy Gray Baird (Rachel Zegler thủ vai). &nbsp;Phần phim này sẽ hé lộ quá khứ của Tổng thống Snow thời trẻ, những sự kiện nguồn cơn dẫn Snow đến con đường trở thành thủ lĩnh độc tài của Panem thay vì là chàng thiếu niên lương thiện. Đến cuối cùng, khán giả mới có thể được biết ai sẽ là chim ca, hót lên một khúc hát của kẻ chiến thắng và ai là rắn độc thật sự.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Đức', 0, '[{"name":"Tom Blyth","avatar":""},{"name":"Rachel Zegler","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Hunter Schafer","avatar":""},{"name":"Josh Rivera","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Fionnula Flanagan","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Dexter Sol Ansell","avatar":""},{"name":"Rosa Gotzler","avatar":""},{"name":"Clemens Schick","avatar":""},{"name":"Ashley Liao","avatar":""},{"name":"Athena Strates","avatar":""},{"name":"Joshua Kantara","avatar":""},{"name":"Amélie Hoeferle","avatar":""},{"name":"Kaitlyn A","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Đấu Trường Sinh Tử: Khúc Ca Của Chim Ca & Rắn Độc","عطش مبارزه: تصنیف پرندگان آوازخوان و مارها","Hunger Games 0","The Hunger Games: The Ballad of Songbirds and Snakes","The Hunger Games - The Ballad of Songbirds and Snakes","Los Juegos Del Hambre: Balada de Pájaros Cantores y Serpientes","Hunger Games 5 - La Ballade du serpent et de l''oiseau chanteur","Igre gladi: Balada pjevica i zmija","Hunger Games : La Ballade du serpent et de l''oiseau chanteur","Սոված Խաղեր","La ballade du serpent et de l’oiseau chanteur","Hunger Games: la ballade du serpent et de l''oiseau chanteur","Os Jogos da Fome: A Balada dos Pássaros e das Serpentes","The Hunger Games: The Ballad of Songbirds & Snakes"]', 1784690324247);
