INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-truong-sinh-tu-khuc-hat-cua-chim-ca-ran-doc', 'Đấu Trường Sinh Tử: Khúc Hát Của Chim Ca & Rắn Độc', 'The Hunger Games: The Ballad Of Songbirds & Snakes', 'đấu trường sinh tử: khúc hát của chim ca & rắn độc the hunger games: the ballad of songbirds & snakes tom blyth rachel zegler peter dinklage jason schwartzman hunter schafer josh rivera viola davis fionnula flanagan burn gorman dexter sol ansell rosa gotzler clemens schick ashley liao athena strates joshua kantara amélie hoeferle kaitlyn a đấu trường sinh tử: khúc ca của chim ca & rắn độc عطش مبارزه: تصنیف پرندگان آوازخوان و مارها hunger games 0 the hunger games: the ballad of songbirds and snakes the hunger games - the ballad of songbirds and snakes los juegos del hambre: balada de pájaros cantores y serpientes hunger games 5 - la ballade du serpent et de l''oiseau chanteur igre gladi: balada pjevica i zmija hunger games : la ballade du serpent et de l''oiseau chanteur սոված խաղեր la ballade du serpent et de l’oiseau chanteur hunger games: la ballade du serpent et de l''oiseau chanteur os jogos da fome: a balada dos pássaros e das serpentes the hunger games: the ballad of songbirds & snakes', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-trang-3-thien-dang-hay-dia-nguc', 'Bão Trắng 3: Thiên Đàng Hay Địa Ngục', 'The White Storm 3: Heaven Or Hell', 'https://phimimg.com/upload/vod/20250725-1/bafa0f6068ec711750d302072b2e85c7.jpg', 'https://phimimg.com/upload/vod/20250725-1/a9849b728002597ea1eccf880d80a4ed.jpg', '<p>Âu Chí Viễn và Trương Kiến Hành là cảnh sát chìm hoạt động trong một băng đảng ma túy do ông trùm Khang Tố Sai đứng đầu tại Hồng Kông. Trong một lần bị thương nặng, Trương Kiến Hành đã được ông trùm cứu trên con tàu tới khu Tam Giác Vàng. Sau lần trở về từ cõi chết và cảm kích tấm lòng của Khang Tố Sai, Trương Kiến Hành miễn cưỡng tham gia sản xuất thuốc phiện. Mặt khác, Âu Chí Viễn lần theo dấu vết đồng nghiệp của mình, cùng cảnh sát quốc tế truy nã ông trùm ma túy. Chuyện gì sẽ xảy ra khi cả ba chạm mặt nhau? Tình nghĩa hay chính nghĩa sẽ chiến thắng?</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Phú Thành","avatar":""},{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Lưu Thanh Vân","avatar":""},{"name":"La Gia Lương","avatar":""},{"name":"Phương Trung Tín","avatar":""},{"name":"Trần Quốc Bang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["The White Storm 3","掃毒3","扫毒3天大地大","扫毒3：人在天涯","扫毒3:人在天涯","คนอันตรายล่าข้ามโลก","طوفان سفید ۳: بهشت یا جهنم","화이트 스톰 3: 헤븐 오어 헬","So duk 3: Yun joi tin ngai","掃毒3︰人在天涯"]', 1784690324247);
