INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thi-tran-fargo-phan-5', 'Thị Trấn Fargo (Phần 5)', 'Fargo (Season 5)', 'thị trấn fargo (phần 5) fargo (season 5) juno temple jennifer jason leigh david rysdahl joe keery lamorne morris richa shukla moorjani sam spruell sienna king dave foley jon hamm 雪花高离奇命案 冰血暴 fargo/ファーゴ фарго fargo: year one fargo: year two fargo: year three fargo: year four fargo: year five fargo', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-lac-ngung-thanh-duong', 'Tinh Lạc Ngưng Thành Đường', 'The Starry Love', 'https://phimimg.com/upload/vod/20250722-1/cec7af467698427fcdd694eb07b9d033.jpg', 'https://phimimg.com/upload/vod/20250722-1/fd77a1b298bb6ae3e17178e4e418d257.jpg', '<p>Hai nàng công chúa sinh đôi với tính cách đối lập. Nếu tỷ tỷ Ly Quang Thanh Quỳ là người lương thiện ấm áp, tài mạo song toàn và là điềm may của cả gia tộc, thì muội muội Ly Quang Dạ Đàm lại được coi là điềm gở khi có tính cách bướng bỉnh, dữ dằn và chuyên phá hỏng mọi chuyện. Thanh Quỳ vốn được định gả cho Thiên tộc, còn Dạ Đàm sẽ về làm dâu Ma tộc.&nbsp; Nhưng một sự cố trên đường đưa dâu đã khiến Thanh Quỳ lương thiện phải bước chân vào Ma tộc khát máu tàn bạo làm vợ hoàng tử Trào Phong. Dạ Đàm cá tính mạnh mẽ lại trở thành cô dâu Thiên tộc, vợ của thái tử Thiếu Điển Hữu Cầm.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tinh Húc","avatar":""},{"name":"Lý Lan Địch","avatar":""},{"name":"Trần Mục Trì","avatar":""},{"name":"Hà Tuyên Lâm","avatar":""},{"name":"Tần Thiên Vũ","avatar":""},{"name":"Chu Lịch Kiệt","avatar":""},{"name":"Đới Nhã Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Xing Luo Ning Cheng Tang","星隕凝結成糖果","星落凝结成糖","Love When the Stars Fall","星落凝成糖"]', 1784690324247);
