INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-lac-ngung-thanh-duong', 'Tinh Lạc Ngưng Thành Đường', 'The Starry Love', 'tinh lạc ngưng thành đường the starry love trần tinh húc lý lan địch trần mục trì hà tuyên lâm tần thiên vũ chu lịch kiệt đới nhã kỳ xing luo ning cheng tang 星隕凝結成糖果 星落凝结成糖 love when the stars fall 星落凝成糖', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-giang-ho', 'Thiếu Niên Giang Hồ', 'Wanru''s Journey', 'https://phimimg.com/upload/vod/20250722-1/30010aede76843608b6e3816034f33cb.jpg', 'https://phimimg.com/upload/vod/20250722-1/22eab6fc14ed7f4dbab478601344c4c8.jpg', '<p>Là cô gái có võ công bình thường, Tiểu Như kiếm sống bằng cách bán bí kíp võ công và lừa tiền thiên hạ, nhưng lại luôn sẵn sàng giúp người. Vì một hiểu lầm, cô trở thành tiểu thư của gia tộc nhà Mộ Dung và gặp gỡ hai thiếu hiệp Mộ Dung Xung và Phù Hoằng. Từ đó, họ cùng nhau đối mặt với vô vàn thử thách trong chốn giang hồ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngao Thụy Bằng","avatar":""},{"name":"Đặng Siêu Nguyên","avatar":""},{"name":"Tông Nguyên Viên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我才不要当盟主","宛如桃李慕春风","Wanru''s Journey","Thiếu Niên Giang Hồ","少年江湖"]', 1784690324247);
