INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-thieu-nien-sieu-dang', 'Đội Thiếu Niên Siêu Đẳng', 'Moving', 'https://phimimg.com/upload/vod/20250721-1/81a986bc4c9689dc2b0d2037e81aa474.jpg', 'https://phimimg.com/upload/vod/20250721-1/b99ca1e2bd09ab11f5804a668c961a66.jpg', '<p>Nội dung bộ phim xoay quanh câu chuyện về Kim Bong Seok, Jang Hee Soo và Lee Gang Hoon học cùng trường trung học. Họ trông giống như những học sinh bình thường, nhưng họ có những khả năng đặc biệt mà họ thừa hưởng từ cha mẹ. Kim Bong Seok có khả năng bay. Jang Hee Soo có khả năng thể thao tuyệt vời và anh ấy có thể nhanh chóng hồi phục sau chấn thương, chẳng hạn như bị bắn hoặc bị đâm. Lee Gang Hoon có sức mạnh và tốc độ phi thường. Ba học sinh này cố gắng che giấu khả năng đặc biệt của mình với người khác, trong khi cha mẹ của họ đấu tranh để bảo vệ họ khỏi bị người khác lợi dụng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Han Hyo-joo","avatar":""},{"name":"Zo In-sung","avatar":""},{"name":"Cha Tae-hyun","avatar":""},{"name":"Ryoo Seung-bum","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Kim Hie-won","avatar":""},{"name":"Moon Sung-keun","avatar":""},{"name":"Lee Jung-ha","avatar":""},{"name":"Go Youn-jung","avatar":""},{"name":"Kim Do-hoon","avatar":""},{"name":"Kwak Sun-young","avatar":""},{"name":"Park Hee-soon","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["超异能族","متحرک","در حال حرکت","ムービング","Moving","timing and moving","Движение","В движении","Перемещение","異能","Moving Kr","무빙"]', 1784690324247);
