INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-26-tau-ngam-sat-mau-den', 'Thám Tử Lừng Danh Conan 26: Tàu Ngầm Sắt Màu Đen', 'Detective Conan: Black Iron Submarine', 'https://phimimg.com/upload/vod/20231016-1/6a45585d457b3d77e91cbe7757f28c94.jpg', 'https://phimimg.com/upload/vod/20231016-1/b015db4de6e3973c7c183880406d2d1f.jpg', '<p>Địa điểm lần này được đặt ở vùng biển gần đảo Hachijo-jima, Tokyo. Các kỹ sư từ khắp nơi trên thế giới đã tập hợp để vận hành toàn diện &quot;Phao Thái Bình Dương&quot;, một cơ sở ngoài khơi để kết nối các camera an ninh thuộc sở hữu của lực lượng cảnh sát trên toàn thế giới. Một thử nghiệm về một &quot;công nghệ mới&quot; nhất định dựa trên hệ thống nhận dạng khuôn mặt đang được tiến hành ở đó. Trong khi đó, Conan và Đội thám tử nhí đến thăm Hachijo-jima theo lời mời của Sonoko và nhận được một cuộc điện thoại từ Subaru Okiya thông báo rằng một nhân viên Europol đã bị sát hại ở Đức bởi Jin của Tổ chức Áo đen. Conan lo lắng, lẻn vào cơ sở và phát hiện ra rằng một nữ kỹ sư đã bị Tổ chức Áo đen bắt cóc...! Hơn nữa, một ổ USB chứa một số thông tin nhất định mà cô ấy sở hữu lại lọt vào tay tổ chức... Một bóng đen cũng len lỏi vào Ai Haibara.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Shuichi Ikeda","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Yukimasa Kishino","avatar":""},{"name":"Yukitoshi Hori","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Mami Koyama","avatar":""},{"name":"Toru Furuya","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Hiroyuki Kinoshit","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324247);
