INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-thu-ma-am', 'Dinh Thự Ma Ám', 'Haunted Mansion', 'https://phimimg.com/upload/vod/20250719-1/104b0d84e6440f4f63ac1a93e29ec481.jpg', 'https://phimimg.com/upload/vod/20250719-1/c935e3f2d27a0636ca299c68b37dd9a2.jpg', '<p>Một bà mẹ đơn thân tên Gabbie và cậu con trai 9 tuổi đang tìm cách bắt đầu một cuộc sống mới bằng việc chuyển đến một biệt thự giá cả phải chăng kỳ lạ ở New Orleans. Sau khi phát hiện ra ngôi nhà ẩn chứa những hồn ma, Gabbie đã cố gắng liên hệ với một linh mục, người này nhờ sự trợ giúp của một nhà khoa học, một chuyên gia huyền bí và một sử học gia khác để giúp trừ tà cho dinh thự.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rosario Dawson","avatar":""},{"name":"Chase W. Dillon","avatar":""},{"name":"LaKeith Stanfield","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Tiffany Haddish","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"J.R. Adduci","avatar":""},{"name":"Creek Wilson","avatar":""},{"name":"Ben Bladon","avatar":""},{"name":"Lindsay Lamb","avatar":""},{"name":"Charity Jordan","avatar":""},{"name":"Fedor Steer","avatar":""},{"name":"Terence Rosemore","avatar":""},{"name":"Mike Benitez","avatar":""},{"name":"Erika Coleman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["הטירה הרדופה","Disney''s Haunted Mansion","عمارت جن‌زده","鬼咁多大屋","幽靈公館","幽灵鬼屋","Mansión en