INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phon-thanh-chi-ha', 'Phồn Thành Chi Hạ', 'Ripe Town', 'https://phimimg.com/upload/vod/20250718-1/e77077e3122007ffdd5a5a276b49dfe9.jpg', 'https://phimimg.com/upload/vod/20250718-1/47f51d4aab808e9fd0bf1f1becb26c28.jpg', '<p>Năm Vạn Lịch thứ 37 thời nhà Minh, tại huyện thành Đố Huyện ở Giang Nam liên tiếp xảy ra những vụ án giết người. Những nạn nhân này có thân phận khác biệt, không liên quan đến nhau, xác chết được xếp thành hình thù quái lạ, mà ở tất cả các hiện trường vụ án đều để lại một câu. Là đồ đệ của nạn nhân đầu tiên, tiểu bổ khoái Khúc Tam Canh đã cùng nhóm bạn điều tra phá án. Trong quá trình đi sâu điều tra, mọi hạng người, mọi tầng lớp người lần lượt xuất hiện, trong màn sương mù dày đặc, vụ án cũ mười năm trước dần dần được hé lộ. Rốt cuộc hung thủ là ai, và mục đích của hắn là gì?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Vũ Phàm","avatar":""},{"name":"Ninh Lý","avatar":""},{"name":"Hướng Hàm Chi","avatar":""},{"name":"Lưu Di Đồng","avatar":""},{"name":"Trương Hạo Duy","avatar":""},{"name":"Tăng Lê","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["青蝇宴","Ripe Town","繁城之下"]', 1784690324247);
