INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-thien-duong-phan-2', 'Mùa Hè Thiên Đường (Phần 2)', 'The Summer I Turned Pretty (Season 2)', 'https://phimimg.com/upload/vod/20250718-1/e4c8bfb93303610528295bb8683aa234.jpg', 'https://phimimg.com/upload/vod/20250718-1/00ab8af5b888a14b8096bfbfd3bcb5ed.jpg', '<p>Belly Conklin sắp bước sang tuổi 16 và chuẩn bị lên đường tới nơi yêu thích nhất của mình trên thế gian là bãi biển Cousins để nghỉ hè cùng gia đình mình và gia đình Fisher. Belly đã lớn hẳn lên trong năm vừa qua và cô có cảm giác mùa hè này sẽ khác tất cả các mùa hè trước.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lola Tung","avatar":""},{"name":"Christopher Briney","avatar":""},{"name":"Gavin Casalegno","avatar":""},{"name":"Sean Kaufman","avatar":""},{"name":"Rain Spencer","avatar":""},{"name":"Jackie Chung","avatar":""},{"name":"Isabella Briggs","avatar":""},{"name":"Kristen Connolly","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我变美的那夏天","我变漂亮的那个夏天","El verano en que me enamoré","הקיץ בו הפכתי ליפה","내가 예뻐진 그 여름","То лето, когда я похорошела","Літо, коли я стала привабливою","The Summer I Turned Pretty"]', 1784690324247);
