INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ma-quai-phan-2', 'Thế Giới Ma Quái (Phần 2)', 'Sweet Home (Season 2)', 'https://phimimg.com/upload/vod/20250717-1/d55698f82ddedb9115eba81c815c35e4.jpg', 'https://phimimg.com/upload/vod/20250717-1/8ab4711f48d6a47f97be4ffbb1c4a0b1.jpg', '<p>Khi con người biến thành quái vật man rợ gieo rắc kinh hoàng, một thiếu niên trăn trở và hàng xóm ở căn hộ của cậu phải chiến đấu để sinh tồn – và giữ lấy nhân tính.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Kang","avatar":""},{"name":"Lee Jin-uk","avatar":""},{"name":"Lee Si-young","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Lee Do-hyun","avatar":""},{"name":"Go Min-si","avatar":""},{"name":"Yu Oh-seong","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Kim Moo-yul","avatar":""},{"name":"Kim Si-a","avatar":""},{"name":"Chae Won-been","avatar":""},{"name":"Kim Ji-an","avatar":""},{"name":"Yang Hye-ji","avatar":""},{"name":"Heo Nam-jun","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sweet Home","Dulce Hogar","خانه شیرین","خانه آرام","스위트홈","스위트홈 시즌 3","스위트홈 시즌 2","甜蜜家园","甜蜜家園"]', 1784690324247);
