INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-ma-quai-phan-2', 'Thế Giới Ma Quái (Phần 2)', 'Sweet Home (Season 2)', 'thế giới ma quái (phần 2) sweet home (season 2) song kang lee jin-uk lee si-young jung jin-young lee do-hyun go min-si yu oh-seong oh jung-se kim moo-yul kim si-a chae won-been kim ji-an yang hye-ji heo nam-jun sweet home dulce hogar خانه شیرین خانه آرام 스위트홈 스위트홈 시즌 3 스위트홈 시즌 2 甜蜜家园 甜蜜家園', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-troi-day-cua-khien-hiep-si-phan-3', 'Sự Trỗi Dậy Của Khiên Hiệp Sĩ (Phần 3)', 'The Rising Of The Shield Hero (Season 3)', 'https://phimimg.com/upload/vod/20240105-1/18cfa62812e89031fa6806875bd5b283.jpg', 'https://phimimg.com/upload/vod/20240105-1/247190ce454563d686d9e042fa83e6aa.jpg', '<p>Iwatani Naofumi bị triệu hồi vào thế giới song song cùng với 3 thằng đực rựa khác. Mỗi đứa đều được trang bị 4 thanh Huyền Khí khi được triệu hồi, Naofumi được nhận Huyền Thuẫn. Tiếc cái ở cái thế giới này lại tôn thờ Tam Đại Thánh Khí (chém đó) bao gồm Thương, Cung, Kiếm và tất nhiên Khiên lại được cho là thứ tà giáo. Naofumi vừa được triệu hồi sẽ phải đối mặt với sự phản bội, sự tàn bạo, sự chà đạp,... của chính những kẻ gọi là con người ở đây. Liệu Naofumi sẽ chấp nhận cuộc sống không bằng người đó hay sẽ đứng dậy luyện khí bứt phá đập chết tụi nó?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kaito Ishikawa","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Rina Hidaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324247);
