INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-tuong-tu-phan-1', 'Trường Tương Tư (Phần 1)', 'Lost You Forever (Season 1)', 'https://phimimg.com/upload/vod/20250708-1/89fe135d48c23f3ec1fbfc1e5a3bea62.jpg', 'https://phimimg.com/upload/vod/20250708-1/3ab92a966d95aab8e7af37dd8be16602.jpg', '<p>Bộ phim Trường tương tư kể về nàng Tiểu Yêu (Dương Tử) sống nay đây mai đó nhưng sau này lại trở thành Vương cơ của Cao Tân. Cuộc đời của Tiểu Yêu gắn liền với nhiều trắc trở, đặc biệt là mối quan hệ của cô với Thương Huyền (Trương Vãn Ý), Đồ Sơn Cảnh (Đặng Vi) và Tương Liễu (Đàn Kiện Thứ). Sau khi hoàn thành đại nghiệp, Tiểu Yêu đã lựa chọn từ bỏ tất cả và quy ẩn giang hồ. Vào thời thượng cổ, người, thần, yêu chung sống cùng nhau, ba nước Thần Nông, Hiên Viên, Cao Tân tạo thế chân vạc. Cửu Dao, Vương cơ của Cao Tân lưu lạc Đại Hoang trải qua trăm năm khốn khổ, không những mất đi thân phận, cũng mất cả dung mạo, dừng chân ở trấn Thanh Thủy, trở thành Văn Tiểu Lục không nơi nào để đi, không có ai để nương tựa, không thể tự bảo vệ mình. Cô hành nghề y làm kế sinh nhai, sống tự do bất kham.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tử","avatar":""},{"name":"Trương Vãn Ý","avatar":""},{"name":"Đặng Vi","avatar":""},{"name":"Đàn Kiện Thứ","avatar":""},{"name":"Đại Lộ Oa","avatar":""},{"name":"Vương Hoằng Nghị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An AllConsuming Love","Perdu pour toujours","ห้วงคำนึง ดวงใจนิรันดร์","Lost You Forever","Trường Tương Tư","长相思"]', 1784690324247);
