INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-tuong-tu-phan-1', 'Trường Tương Tư (Phần 1)', 'Lost You Forever (Season 1)', 'trường tương tư (phần 1) lost you forever (season 1) dương tử trương vãn ý đặng vi đàn kiện thứ đại lộ oa vương hoằng nghị an allconsuming love perdu pour toujours ห้วงคำนึง ดวงใจนิรันดร์ lost you forever trường tương tư 长相思', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bat-dau-tu-ly-hon', 'Tình Yêu Bắt Đầu Từ Ly Hôn', 'Love From Divorce', 'https://phimimg.com/upload/vod/20250708-1/2231d653f9f057f491a7e78a2e9154fd.jpg', 'https://phimimg.com/upload/vod/20250708-1/b0df553846576ae38cab8d7ff796ea69.jpg', '<p>Mất trí nhớ sau một vụ tai nạn, Ôn Lan kết hôn với Mục Bạch dưới sự giới thiệu của gia đình. Sau khi kết hôn, tình cảm giữa hai người rất mờ nhạt và luôn mâu thuẫn với nhau. Nhưng khi tai nạn xảy ra lần nữa, Ôn Lan lấy lại ký ức trước đây và quyết định ly hôn Mục Bạch để theo đuổi con đường nghiên cứu khoa học của riêng mình. Khi đối mặt với một Ôn Lan hoàn toàn khác so với trước kia, Mục Bạch dần dần không muốn buông tay, thậm chí còn vô thức trì hoãn thời gian xin giấy ly hôn. Phải đến khi Ôn Lan rời xa nhà họ Mục và chuyển sang tập trung nghiên cứu dược phẩm thì hai người mới ly hôn hoàn toàn. Chính lúc này Mục Bạch nhận ra tình yêu của mình dành cho Ôn Lan và bắt đầu hành trình mặt dày theo đuổi vợ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 10, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Khải Hâm","avatar":""},{"name":"Phạm Lạc Kỳ","avatar":""},{"name":"Mã Thần Hi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["从离婚开始的爱情","從離婚開始的愛情"]', 1784690324247);
