INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-duyen-ngang-trai', 'Lương Duyên Ngang Trái', 'Unhating You', 'https://phimimg.com/upload/vod/20250705-1/c774e7e391768207c700f9fe5fefb7a2.jpg', 'https://phimimg.com/upload/vod/20250705-1/4d023f62cc8887d920a24646d079d199.jpg', '<p>Rossana và Anond được mọi người chào đón ngoại trừ “Korn”, con trai duy nhất của Kasem. Korn cảm thấy rằng Rossana là một người đào mỏ, người chỉ đến vì tài sản. Sau khi Rossana đến, cô ấy đã tìm lại được niềm hạnh phúc trong ngôi nhà này. Cô ấy đã chăm sóc Kasem chu đáo và khiến Phen, mẹ của Korn cảm thấy hạnh phúc hơn. Tuy nhiên, Korn tò mò về mối quan hệ của Rossana và Anond nên anh ấy đã cố gắng tìm ra sự thật.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2023, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Nawat Kulrattanarak","avatar":""},{"name":"Nopjira Lerkkajornnamkul","avatar":""},{"name":"Ohm Atshar Nampan","avatar":""},{"name":"Amena Pinit","avatar":""},{"name":"Pornsroung Rouyruen","avatar":""},{"name":"Montree Jenuksorn","avatar":""},{"name":"Paweena Charivsakul","avatar":""},{"name":"Kanjanaporn Plodpai","avatar":""},{"name":"Nat Thewphaingam","avatar":""},{"name":"Graphic Ratchawit Chanrunganan","avatar":""},{"name":"Penpak Sirikul","avatar":""},{"name":"Kongkapan Sangsuriya","avatar":""},{"name":"Vorari","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jam Laeng Rak","Ton Rai Plai Rak","ต้นร้ายปลายรัก"]', 1784690324247);
