INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-canh-ky', 'Điền Canh Kỷ', 'Romance On The Farm', 'https://phimimg.com/upload/vod/20250628-1/ee1fa182172d8a592fffe70d2d02b557.jpg', 'https://phimimg.com/upload/vod/20250628-1/1bff1faaf5ee1a25210c1cf0449abc36.jpg', '<p>Cô gái hiện đại Liên Mạn Nhi bỗng nhiên bị lôi đến vùng nông thôn cổ đại trong thế giới trò chơi và gặp gỡ chàng trai bí ẩn Thẩm Nặc. Từ mối quan hệ oan gia, Mạn Nhi và Thẩm Nặc dần dà hiểu nhau hơn. Họ cùng nhau đối phó với những người họ hàng xấu tính cũng như trồng trọt canh tác để nỗ lực làm giàu. Tất nhiên, lửa gần rơm lâu ngày cũng bén, giữa hai người bắt đầu nảy sinh tình cảm đặc biệt dành cho nhau.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Điền Hi Vi","avatar":""},{"name":"Tăng Thuấn Hy","avatar":""},{"name":"Lý Mặc Chi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["恬耕纪","重生小地主","我是小地主","tian geng ji","田耕紀 田園ロマンス","Romance On The Farm","Điền Canh Kỷ","田耕纪"]', 1784690324247);
