INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-huu-am-huong-lai-mui-huong-cua-thoi-gian', 'Vi Hữu Ám Hương Lai (Mùi Hương Của Thời Gian)', 'Scent Of Time', 'https://phimimg.com/upload/vod/20250702-1/14e8dbc1d62519177cd11e74dab27321.jpg', 'https://phimimg.com/upload/vod/20250702-1/4ddef71a2114cbe42de0124000a3862c.jpg', '<p>Một cô gái được quay trở lại quá khứ để sửa chữa những quyết định sai lầm của bản thân hòng cứu lấy gia đình mình, nhưng mọi chuyện dần biến đổi theo những cách mà chính cô cũng không kiểm soát được.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Châu Dã","avatar":""},{"name":"Vương Tinh Việt","avatar":""},{"name":"Bành Sở Việt","avatar":""},{"name":"Triệu Tình","avatar":""},{"name":"Trương Dật Kiệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["洗铅华","Scent of Time","El Aroma del Tiempo","Wei you an xiang lai","為有暗香來","为有暗香来"]', 1784690324247);
