INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-phat', 'Trừng Phạt', 'Retribution', 'https://phimimg.com/upload/vod/20250701-1/0d63254f9b2aa2dcb3d82bdee4b1a2f1.jpg', 'https://phimimg.com/upload/vod/20250701-1/d7f8e2e0c1e68e8598ba7a0a39008e17.jpg', '<p>Matt Turner - một doanh nhân thành đạt, đang phải cân bằng giữa sự nghiệp và gia đình. Một sáng nọ, Matt nhận một cuộc điện thoại và buộc hoàn thành loạt nhiệm vụ nếu không muốn chết. Mắc kẹt trong cuộc rượt đuổi căng thẳng và nguy hiểm, anh phải nghe theo “kẻ lạ mặt” để bảo vệ gia đình và tìm ra chân tướng của bí ẩn này.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Lilly Aspell","avatar":""},{"name":"Jack Champion","avatar":""},{"name":"Matthew Modine","avatar":""},{"name":"Noma Dumezweni","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Arian Moayed","avatar":""},{"name":"Emily Kusche","avatar":""},{"name":"Luca Márkus","avatar":""},{"name":"Bernhard Piesk","avatar":""},{"name":"Michael S. Ruscheinsky","avatar":""},{"name":"Antonije Stankovic","avatar":""},{"name":"Christian Koerner","avatar":""},{"name":"Gerhard Elfers","avatar":""},{"name":"Tine Gerhäeusser","avatar":""},{"name":"Peter Miklu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Retaliação","เหยียบระห่ำ ดับโคตรแค้น","عقوبت","قصاص","爆復","Justice Vengeresse","Αντίστροφη μέτρηση","Contrarreloj","A Chamada","急速营救","炸掉银行经理","疾速营救","Odmazda","Jízda smrti","Kättemaks","Megtorlás","Be''Milkoud","バッド・デイ・ドライブ","Заложники","Одмазда","Ultim