INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-thao-tung', 'Những Kẻ Thao Túng', 'Hypnotic', 'https://phimimg.com/upload/vod/20250701-1/e2cb18650ac632a57c7ddf0cde7b7287.jpg', 'https://phimimg.com/upload/vod/20250701-1/b8ca2d756294ea9202e4f548ce8ee329.jpg', '<p>Phim theo chân thám tử Daniel Rourke (Ben Affleck) trong hành trình tìm kiếm cô con gái bị mất tích. Anh sớm nhận ra tất cả những chuyện bí ẩn này đều liên quan đến một người đàn ông có sức mạnh thôi miên, bẻ cong thực tại. Với sự hỗ trợ từ nhà ngoại cảm Diana Cruz (Alice Braga), Daniel bắt đầu truy đuổi hắn và phải tìm mọi cách để đưa con gái mình trở về nhà an toàn.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"J. D. Pardo","avatar":""},{"name":"Hala Finley","avatar":""},{"name":"Ionie Olivia Nieves","avatar":""},{"name":"Dayo Okeniyi","avatar":""},{"name":"Kelly Frye","avatar":""},{"name":"Corina Calderon","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Sandy Avila","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Zane Holtz","avatar":""},{"name":"Ruben Javier Caballero","avatar":""},{"name":"Ryan Ryusaki","avatar":""},{"name":"Nikki Dixon","avatar":""},{"name":"Evan Vines","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name