INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-ve-huu', 'Kế Hoạch Về Hưu', 'The Retirement Plan', 'https://phimimg.com/upload/vod/20250701-1/aba1d6cd064de917000cad8385371dad.jpg', 'https://phimimg.com/upload/vod/20250701-1/ab7adf952951e9999e62ce4428374af7.jpg', '<p>Ashley và con gái nhỏ Sarah của cô bị cuốn vào một tổ chức tội phạm khiến họ bị đe dọa tính mạng. Cô đã nhờ đến người duy nhất có thể giúp đỡ mình - ông bố Matt, hiện đang sống lang thang trên bãi biển ở quần đảo Cayman. Cuộc đoàn tụ diễn ra chóng vánh khi họ sớm bị trùm tội phạm Donnie và trung úy Bobo truy đuổi trên đảo. Khi Ashley, Sarah và Matt bị vướng vào một mạng lưới ngày càng nguy hiểm, Ashley nhanh chóng biết được rằng cha cô có một quá khứ bí mật.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Thalia Campbell","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Grace Byers","avatar":""},{"name":"Lynn Whitfield","avatar":""},{"name":"Joel David Moore","avatar":""},{"name":"Jordan Johnson-Hinds","avatar":""},{"name":"Rick Fox","avatar":""},{"name":"Ronnie James Hughes","avatar":""},{"name":"Jon Ambrose","avatar":""},{"name":"Kip Brown","avatar":""},{"name":"Nick Alachiotis","avatar":""},{"name":"Samantha Kaine","avatar":""},{"name":"Dax R","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ب