INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-hau-thu-tinh-yeu-queer-phan-1', 'Tối Hậu Thư: Tình Yêu Queer (Phần 1)', 'Tối Hậu Thư: Tình Yêu Queer (Phần 1)', 'https://phimimg.com/upload/vod/20250701-1/0dc20bb7194ad19d3abfdc9052ec5518.jpg', 'https://phimimg.com/upload/vod/20250701-1/08e2f381f1bf5ba6952e5aeda9cc3287.jpg', '<p>Sáu cặp đôi thử thách tình yêu của mình bằng cách dọn vào sống cùng người yêu khác. Liệu họ đã sẵn sàng cho hôn nhân hay &quot;nửa kia&quot; thực ra lại là người khác?</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"JoAnna Garcia Swisher","avatar":""},{"name":"AJ Blount","avatar":""},{"name":"Pilar Dizon","avatar":""},{"name":"Haley Drexler","avatar":""},{"name":"Ashley Johnson","avatar":""},{"name":"Dayna Mathews","avatar":""},{"name":"Bridget Matloff","avatar":""},{"name":"Magan Mourad","avatar":""},{"name":"Kyle Neal","avatar":""},{"name":"Marita Prodger","avatar":""},{"name":"Marie Robertson","avatar":""},{"name":"Britney Thompson","avatar":""},{"name":"Mel Vitale","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["最后通牒：酷儿的爱","เลิกหรือแต่ง ฉบับเควียร์","The Ultimatum: Queer Love"]', 1784690324247);
