INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-hau-thu-tinh-yeu-queer-phan-1', 'Tối Hậu Thư: Tình Yêu Queer (Phần 1)', 'Tối Hậu Thư: Tình Yêu Queer (Phần 1)', 'tối hậu thư: tình yêu queer (phần 1) tối hậu thư: tình yêu queer (phần 1) joanna garcia swisher aj blount pilar dizon haley drexler ashley johnson dayna mathews bridget matloff magan mourad kyle neal marita prodger marie robertson britney thompson mel vitale 最后通牒：酷儿的爱 เลิกหรือแต่ง ฉบับเควียร์ the ultimatum: queer love', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-vu-no-tren-the-gioi-tuyet-voi-nay', 'Một Vụ Nổ Trên Thế Giới Tuyệt Vời Này', 'KonoSuba An Explosion On This Wonderful World!', 'https://phimimg.com/upload/vod/20250701-1/8d8cd0f86f41d0b6ca886222fe516d57.jpg', 'https://phimimg.com/upload/vod/20250701-1/291344475b0eb44b250784d5d5fa325f.jpg', '<p>Theo quan điểm của Megumin, một câu chuyện hoàn toàn nguyên bản diễn ra vào năm trước khi Kazuma tái sinh, lấy bối cảnh ở vùng đất của Quỷ đỏ! &quot;Có được ma thuật cấp cao được coi là một kỹ năng thực sự, và những thứ như ma thuật Explosion chỉ đơn giản là quanh co.&quot;—Megumin làm ngược với những lời dạy của quê hương Hồng Ma, và học tập chăm chỉ để học phép Explosion .Một cuộc sống học đường sôi động, nơi cậu buộc phải chấp nhận thử thách từ người bạn cùng lớp Yoyo. Một ngày nọ, khi về nhà, cậu phát hiện ra em gái Xiaomi của mình đang ôm một con mèo đen có ngoại hình kỳ lạ——! ?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rie Takahashi","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Maria Naganawa","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Shizuka Ishigami","avatar":""},{"name":"Hitomi Nabatame","avatar":""},{"name":"Mitsuhiro Sakamaki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Konosuba: Uma Explosão Neste Mundo Maravilhoso!","为美好的世界献上爆焰！","为美好的世界献上爆炎！","KonoSuba: Explosión en un mundo maravilloso","KonoSuba – An Explosion on This Wonderful World!","為美好的世界獻上爆焰！","Konosuba - An Explosion on This Wonderful World","Kono Subarashii Sekai ni Bakuen wo!","Kono Subarashii Sekai ni Bakuen o","이 멋진 세계에 폭염을!","KONOSUBA -An Explosion on This Wonderful World!","Да благословит взрыв сей расчудесный мир!","Одаривая этот замечательный мир взрывами!","Да взорвётся сей расчудесный мир!","Коносуба","Mở Ra Một Thế Giới Tuyệt Vời","この素晴らしい世界に爆焔を！"]', 1784690324247);
