INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-vu-no-tren-the-gioi-tuyet-voi-nay', 'Một Vụ Nổ Trên Thế Giới Tuyệt Vời Này', 'KonoSuba An Explosion On This Wonderful World!', 'một vụ nổ trên thế giới tuyệt vời này konosuba an explosion on this wonderful world! rie takahashi aki toyosaki maria naganawa kaori nazuka miyu tomita sayumi suzushiro shizuka ishigami hitomi nabatame mitsuhiro sakamaki konosuba: uma explosão neste mundo maravilhoso! 为美好的世界献上爆焰！ 为美好的世界献上爆炎！ konosuba: explosión en un mundo maravilloso konosuba – an explosion on this wonderful world! 為美好的世界獻上爆焰！ konosuba - an explosion on this wonderful world kono subarashii sekai ni bakuen wo! kono subarashii sekai ni bakuen o 이 멋진 세계에 폭염을! konosuba -an explosion on this wonderful world! да благословит взрыв сей расчудесный мир! одаривая этот замечательный мир взрывами! да взорвётся сей расчудесный мир! коносуба mở ra một thế giới tuyệt vời この素晴らしい世界に爆焔を！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-quy-cap-1-va-anh-hung-mot-phong', 'Chúa Tể Quỷ Cấp 1 Và Anh Hùng Một Phòng', 'Level 1 Demon Lord & One Room Hero', 'https://phimimg.com/upload/vod/20250701-1/98f8aba7b8e8f7a2aa261819535f4914.jpg', 'https://phimimg.com/upload/vod/20250701-1/ece85d2b9717cd796e075f72e1093dcc.jpg', '<p>Chúa Quỷ đã bị anh hùng Max đánh bại, nhưng ngay cả sau khi chết, Chúa Quỷ vẫn có khả năng thức tỉnh. Chúa Quỷ sau đó vội vã thức dậy sau 10 năm ngủ yên để đánh bại Max bằng chính đôi tay của mình...!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuichi Nakamura","avatar":""},{"name":"Naomi Ohzora","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Ami Koshimizu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["LV1魔王与独居废勇者","菜鸟魔王与独居勇者","Lv1 Maō to One Room Yūsha","Lv1 Maou to One Room Yuusha","Однушка лорда демонов и героя","Однушка повелителя демонов и героя","LV1 魔王與獨居廢勇者","Level 1 Demon Lord and One Room Hero","Lv1魔王とワンルーム勇者"]', 1784690324247);
