INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mach-thuong-nhan-nhu-ngoc', 'Mạch Thượng Nhân Như Ngọc', 'Special Lady', 'https://phimimg.com/upload/vod/20250629-1/110900af2b3981919e18481b2733248a.jpg', 'https://phimimg.com/upload/vod/20250629-1/a06b1211fb26bdf203abf3e915903c0f.jpg', '<p>Tống Trúc là tiểu thư thứ ba của nhà họ Tống, sinh ra trong gia đình Nho học nổi tiếng nhưng lại không thừa hưởng được bất kì ưu điểm nào của cha mẹ. Không những thế, nàng lại còn muốn theo đuổi tình yêu đích thực và kịch liệt phản đối cuộc hôn nhân sắp đặt của gia đình. Nhưng rồi mọi kế hoạch mà Tống Trúc muốn thực hiện bỗng thay đổi khi gặp được Tiêu Vũ, một thiếu gia che giấu thân phận thật sự để đến học ở thư viện Nghi Dương cùng nàng.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Yến","avatar":""},{"name":"Trạch Tử Lộ","avatar":""},{"name":"Thịnh Anh Hào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Special Lady","陌上人如玉"]', 1784690324247);
