INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-gia-vo-song-con-duong-ma-nhan-vien-van-phong-chon-de-sinh-ton-o-di-gioi', 'Thánh Giả Vô Song: Con Đường Mà Nhân Viên Văn Phòng Chọn Để Sinh Tồn Ở Dị Giới', 'The Great Cleric', 'https://phimimg.com/upload/vod/20250628-1/2e33cd75fe860b0ab825ce0833518199.jpg', 'https://phimimg.com/upload/vod/20250628-1/771ab3ff821c5a9a546d9a2af8811f83.jpg', '<p>Cựu nhân viên văn phòng trở thành thiên hạ vô song ở dị giới?

Vì một lý do nào đó, cậu nhân viên văn phòng được một vị thần cho tái sinh sang dị giới với thân phận là Luciel, một trị liệu sư 15 tuổi.

Tại đất nước nơi cậu sinh ra, các trị liệu sư luôn bị người ta căm ghét. Lo lắng cho số phận, Luciel đã liều mình gõ cửa hội mạo hiểm giả để bảo vệ bản thân. Tuy nhiên, cuộc huấn luyện khắc nghiệt hơn cậu nghĩ. Đã vậy, mỗi ngày, cậu còn bị ép uống một loại nước uống bí ẩn được gọi là &quot;vật thể X&quot;. &nbsp;Ủa... sao chẳng thấy liên quan gì đến trị liệu sư hết vậy?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Reiji Kawashima","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Hina Tachibana","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Rika Kinugawa","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["圣者无双～上班族、在异世界的存活之道～","聖者無双","聖者無双 ~サラリーマン, 異世界で生き残るために歩む道~","Seija Musou: Salaryman, Isekai de Ikinokoru Tame ni Ayumu Michi","Seija Musō: Salaryman, Isekai de Ikinokoru Tame ni Ayumu Michi","성자무쌍","Великий святой","Непобедимый святой: Путь, которым я иду, чтобы выжить в другом мире","Thánh Giả Vô Song: Con Đường Mà Nhân Viên Văn Phòng Chọn Để Sinh Tồn Ở Dị Giới","Hoán Hồi Mệnh Tử Sinh Hoàn Tại Dị Giới","聖者無双～サラリーマン、異世界で生き残るために歩む道～"]', 1784690324247);
