INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-lam-sao-day-ieyasu', 'Phải Làm Sao Đây Ieyasu', 'What Will You Do, Ieyasu?', 'https://phimimg.com/upload/vod/20250625-1/0f07b29696b903f20b060d6d24814088.jpg', 'https://phimimg.com/upload/vod/20250625-1/f2b5a0f64c45019bb7f48c93b64d9f87.jpg', '<p>Bộ phim khắc họa cuộc đời của Tokugawa Ieyasu - 1 trong 3 tên tuổi vĩ đại nhất thời Chiến quốc, người đã thống nhất Nhật Bản và lập nên một triều đại hòa bình và thịnh vượng suốt 260 năm. Tokugawa Ieyasu, ấu danh Takechiyo, sinh ra là người thừa kế gia tộc Matsudaira ở tỉnh Mikawa, một vùng đất yếu thế nằm dưới sự cai trị của lãnh chúa Imagawa Yoshimoto vùng Suruga. Năm lên 6, ông phải rời quê hương đến Suruga làm con tin cùng với các thuộc hạ thân thuộc cho đến lúc trưởng thành. Trong 1 lần về thăm quê nhà - thành Odazaki, Mikawa và nhìn thấy sự tiêu điều của quê hương, Ieyasu đã bắt đầu xây dựng cơ nghiệp và từng bước trở thành một lãnh chúa lẫy lừng. Cuộc đời Ieyasu trải dài và kinh qua rất nhiều trận chiến, những lần biến đổi thời cuộc, đạt được bao chiến công vang dội cũng như những sai lầm ngàn cân treo sợ tóc. &quot;Phải làm sao đây, Ieyasu&quot; là câu chuyện về những bước đi quân sự nối tiếp nhau mà mỗi bước là một sự đánh đổi sinh tử, mỗi quyết định đều như đi trên băng mỏng giữa chiến tranh máu lửa và tàn bạo...</p>', 'Hoàn Tất (25/25)', 50, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Jun Matsumoto","avatar":""},{"name":"Junichi Okada","avatar":""},{"name":"Kasumi Arimura","avatar":""},{"name":"Tsuyoshi Muro","avatar":""},{"name":"Mansai Nomura","avatar":""},{"name":"Hiroshi Abe","avatar":""},{"name":"Nao Omori","avatar":""},{"name":"Yuki Yamada","avatar":""},{"name":"Yosuke Sugino","avatar":""},{"name":"Rihito Itagaki","avatar":""},{"name":"Takuma Otoo","avatar":""},{"name":"Shinya Kote","avatar":""},{"name":"Dai Okabe","avatar":""},{"name":"Issey Ogata","avatar":""},{"name":"Alice Hirose","avatar":""},{"name":"Takayuki Yamada","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Kenichi Mat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["怎麼辦家康","Dō suru Ieyasu","Dou Suru Ieyasu","Dousuru Ieyasu","어쩌지 이에야스","What Will You Do Ieyasu","どうする家康"]', 1784690324247);
