INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-tinh', 'Oán Tình', 'Behind The Revenge', 'https://phimimg.com/upload/vod/20250624-1/bd5090a63a2be7566a4ce03474a5847d.jpg', 'https://phimimg.com/upload/vod/20250624-1/75f03c58bfaef74bb4db021285023758.jpg', '<p>Dành hết tiền bạc và tình cảm cho Ponwalai để rồi phát hiện cô có người đàn ông khác, Prakob lên cơn đau tim và qua đời, để lại phần lớn tài sản cho ả tình nhân bội bạc. Vì điều này mà con trai ông là Noppharuj vô cùng căm hận Ponwalai và cả người em gái vô tội của cô, Yodthian. Noppharuj điên cuồng tìm đủ mọi cách hãm hại hai chị em để trả thù, còn Yodthian dù biết rõ ý định của anh nhưng sẵn sàng cam chịu tất cả vì mặc cảm tội lỗi.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2023, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Yuke Songpaisan","avatar":""},{"name":"Pimprapa Tangprabhaporn","avatar":""},{"name":"Namthip Jongrachatawiboon","avatar":""},{"name":"Sarawut Martthong","avatar":""},{"name":"Sanya Kunakorn","avatar":""},{"name":"Jarunee Suksawat","avatar":""},{"name":"Kratip Chawallakorn Wanthanapisitkul","avatar":""},{"name":"Jira Danbawornkiat","avatar":""},{"name":"Pichapat Mahathityakul","avatar":""},{"name":"Kidakarn Chatkaewmanee","avatar":""},{"name":"Dao Nathapatsorn Simasthien","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Behind the Revenge","ไฟลวง"]', 1784690324247);
