INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-lap-lanh-phim-le', 'Ngôi Sao Lấp Lánh', 'Shining For One Thing', 'https://phimimg.com/upload/vod/20250624-1/333ba11a0a109fb2f7e485deb791ce45.jpg', 'https://phimimg.com/upload/vod/20250624-1/f16e93b8a2de40876a0973ea0dcf796a.jpg', '<p>Cuộc sống gần 30 của Lâm Bắc Tinh chẳng mấy suôn sẻ, nhưng cô bỗng được quay về tuổi 18, viết lại quá khứ rồi phải lòng Trương Vạn Sâm. Khi biết tương lai anh sẽ qua đời, cô quyết thay đổi định mệnh.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khuất Sở Tiêu","avatar":""},{"name":"Trương Giai Ninh","avatar":""},{"name":"Tưởng Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一閃一閃亮星星","在宇宙尽头一起出发吧","Yi Shan Yi Shan Liang Xing Xing","Zai Yu Zhou Jin Tou Yi Qi Chu Fa Ba","Shining for One Thing: The Movie","Let''s Start Together at the End of the Universe","The Moment of Meeting Again","一闪一闪亮星星"]', 1784690324247);
