INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-sao-lap-lanh-phim-le', 'Ngôi Sao Lấp Lánh', 'Shining For One Thing', 'ngôi sao lấp lánh shining for one thing khuất sở tiêu trương giai ninh tưởng quân 一閃一閃亮星星 在宇宙尽头一起出发吧 yi shan yi shan liang xing xing zai yu zhou jin tou yi qi chu fa ba shining for one thing: the movie let''s start together at the end of the universe the moment of meeting again 一闪一闪亮星星', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-grit-doi-phan-ung-va-tinh-bao-toan-cau-linh-ban-tia-10', 'Lính Bắn Tỉa G.R.I.T. Đội Phản Ứng Và Tình Báo Toàn Cầu (Lính Bắn Tỉa 10)', 'Sniper: G.R.I.T. - Global Response & Intelligence Team', 'https://phimimg.com/upload/vod/20250624-1/e9db794f021c38cf687d1f0d1586cab7.jpg', 'https://phimimg.com/upload/vod/20250624-1/fb88cb8418f56425f3b0994645d04794.jpg', '<p>Khi một giáo phái khủng bố quốc tế đe dọa sự ổn định chính trị toàn cầu và bắt cóc một đặc vụ đồng đội, xạ thủ bắn tỉa Ace Brandon Beckett cùng Đội Phản Ứng &amp; Tình Báo Toàn Cầu mới thành lập – gọi tắt là G.R.I.T. – dưới sự chỉ huy của Đại tá Stone, phải lên đường đến Malta, thâm nhập vào tổ chức khủng bố, tiêu diệt thủ lĩnh của chúng để giải cứu Lady Death và ngăn chặn mối đe dọa toàn cầu.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chad Michael Collins","avatar":""},{"name":"Ryan Robbins","avatar":""},{"name":"Luna Fujimoto","avatar":""},{"name":"Josh Brener","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Toshiji Takeshima","avatar":""},{"name":"Matthew Sim","avatar":""},{"name":"Paul Kissaun","avatar":""},{"name":"Eugenia Caruso","avatar":""},{"name":"Marko Nikolic","avatar":""},{"name":"Christian Scicluna","avatar":""},{"name":"Renald Caruana","avatar":""},{"name":"Antonella Axisa","avatar":""},{"name":"Tarik Badwan","avatar":""},{"name":"Midori Mark","avatar":""},{"name":"Kokoro Ishizawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["تک‌تیرانداز: G.R.I.T - تیم واکنش و اطلاعات جهانی","Sniper: G.R.I.T. - Global Response & Intelligence Team"]', 1784690324247);
