INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-nguyet-dam', 'Thanh Xuân Nguyệt Đàm', 'Our Blooming Youth', 'https://phimimg.com/upload/vod/20250621-1/bf3a717854a4ff6a074cabddda1fe438.jpg', 'https://phimimg.com/upload/vod/20250621-1/260c81b959663c488b8efd5ed424b5a9.jpg', '<p>Bộ phim lấy bối cảnh giả tưởng ở thời kỳ Nhà Triều Tiên, kể về câu chuyện tình yêu định mệnh giữa vị Thế tử để hạ Lee Hwan (Park Hyung-sik) và cô gái Min Jae Yi (Jeon So-nee).

Lee Hwan là một vị Đông Cung Thế tử kiêu ngạo và tính khí thất thường đang phải chịu đựng một lời nguyền bí ẩn. Anh là một người cô đơn, luôn che giấu vết sẹo sâu trong tâm trí. Trong khi đó, Min Jae Yi là một cô gái cực kỳ thông minh và xuất thân từ một gia đình quý tộc được kính trọng. Một ngày, cả gia đình cô đột nhiên bị sát hại và cô bị coi là kẻ giết người. Vừa phải trốn chạy, cô cũng vẫn quyết tâm tìm ra sự thật bị che giấu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hyung-sik","avatar":""},{"name":"Jeon So-nee","avatar":""},{"name":"Pyo Ye-jin","avatar":""},{"name":"Yun Jong-seok","avatar":""},{"name":"Lee Tae-seon","avatar":""},{"name":"Heo Won-seo","avatar":""},{"name":"Cho Seong-ha","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Lee Jong-hyuk","avatar":""},{"name":"Hong Soo-hyun","avatar":""},{"name":"Park Hyo-joon","avatar":""},{"name":"Kim Ki-doo","avatar":""},{"name":"Lee Min-ji","avatar":""},{"name":"Jeong In-kyeom","avatar":""},{"name":"Jeong Da-eun","avatar":""},{"name":"Lim Han-bin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["簪中录","Jeunesse en fleur","افسانه مین جه","شکوفایی جوانی ما","Youth Climbing Over the Wall","Sleep Memo","Sleeping Rock","Youth Monthly Talk","청춘월담"]', 1784690324247);
