INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-truy-duoi-trong-benh-vien', 'Cuộc Truy Đuổi Trong Bệnh Viện', 'Mercy', 'https://phimimg.com/upload/vod/20250607-1/e1af8febd6c7e2b99c99b5d27611ae88.jpg', 'https://phimimg.com/upload/vod/20250607-1/64d0547ef947d6349d9e9dac17f832f3.jpg', '<p>Một nữ bác sĩ từng làm nhiệm vụ trong quân đội nhận ra mình đang bị cuốn vào cuộc chiến sinh tồn đầy nguy hiểm khi băng đảng mafia Ireland chiếm quyền kiểm soát bệnh viện mà cô làm việc. Khi con trai cô bị bắt làm con tin, cô buộc phải dựa vào quá khứ đầy gian khổ và kỹ năng chết người của mình sau khi nhận ra không còn ai cứu vãn tình hình ngoại trừ chính cô.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Leah Gibson","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Anthony Konechny","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Sebastien Roberts","avatar":""},{"name":"Bobby Stewart","avatar":""},{"name":"Anthony Bolognese","avatar":""},{"name":"Mike Dopud","avatar":""},{"name":"Bradley Stryker","avatar":""},{"name":"Mark Masterton","avatar":""},{"name":"Christopher Russell","avatar":""},{"name":"Patrick Roccas","avatar":""},{"name":"Eric Breker","avatar":""},{"name":"Ryan Russell","avatar":""},{"name":"Marc-Anthony Massiah","avatar":""},{"name":"Caitli","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Golpe de Misericórdia","Mercy"]', 1784690324247);
