INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shaakuntalam', 'Shaakuntalam', 'Shaakuntalam', 'https://phimimg.com/upload/vod/20250606-1/344f037b2ee178ad61bac10660aa9b1c.jpg', 'https://phimimg.com/upload/vod/20250606-1/9ec1ad6c9f0e2edc3bfeea036895805c.jpg', '<p>Shakuntala, con gái của tiên nữ Meneka và hiền nhân Vishwamitra, sống trong rừng cùng với thầy của mình là hiền nhân Kanva. Trong rừng, cô gặp vua Dushyant, cả hai phải lòng nhau và kết hôn. Sau khi Shakuntala sinh con trai của họ là hoàng tử Bharata, Dushyant rời khỏi rừng với lời hứa sẽ sớm quay lại đón cô. Tuy nhiên, do bị một lời nguyền của đạo sĩ, Dushyant quên mất Shakuntala, cho đến khi định mệnh đưa họ gặp lại nhau.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Samantha Ruth Prabhu","avatar":""},{"name":"Dev Mohan","avatar":""},{"name":"Aditi Balan","avatar":""},{"name":"Ananya Nagalla","avatar":""},{"name":"Sachin Khedekar","avatar":""},{"name":"Gautami Tadimalla","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Kabir Bedi","avatar":""},{"name":"Allu Arha","avatar":""},{"name":"Kabir Duhan Singh","avatar":""},{"name":"Subbaraju","avatar":""},{"name":"Harish Uthaman","avatar":""},{"name":"Malhottra Shivam","avatar":""},{"name":"Madhoo","avatar":""},{"name":"Jisshu Sengupta","avatar":""},{"name":"Siva Balaji","avatar":""},{"name":"Varshini Sounderaja","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Shakuntalam","Saakuntalam","Shaakunthalam","Shakunthalam","Sakunthalam","Saakunthalam","Shaakuntalam","शकुंतलम","శాకుంతలం"]', 17846903