INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuot-nhi-va-su-menh-than-bien', 'Chuột Nhí và Sứ Mệnh Thần Biển', 'Epic Tails (Argonuts)', 'https://phimimg.com/upload/vod/20250606-1/47c1216709a5c8ff9d37fb52143a9577.jpg', 'https://phimimg.com/upload/vod/20250606-1/673787efe5b461dc176f9638e292b66c.jpg', '<p>Mang một thân hình nho nhỏ và ước mơ to to, Bé Tí đã lên đường cùng Bố Bự và Bác Tay Sắt đi tìm kiếm kho báu đại dương để giải cứu Thành Phố Cảng Xanh khỏi tai họa tan thành khói bụi trước nhiệm vụ bất khả thi của vị Thần Biển. Liệu tổ đội này có vượt qua được thử thách đầy gian truân này hay không?</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Lồng Tiếng', 'FHD', 'Pháp', 1, '[{"name":"Kaycie Chase","avatar":""},{"name":"Christophe Lemoine","avatar":""},{"name":"Emmanuel Curtil","avatar":""},{"name":"Michel Tureau","avatar":""},{"name":"Pierre Richard","avatar":""},{"name":"Frantz Confiac","avatar":""},{"name":"Jérôme Pauwels","avatar":""},{"name":"Barbara Tissier","avatar":""},{"name":"Paul Borne","avatar":""},{"name":"Emmanuel Garijo","avatar":""},{"name":"Valérie Siclay","avatar":""},{"name":"Julien Bouanich","avatar":""},{"name":"Serge Biavan","avatar":""},{"name":"Pascal Casanova","avatar":""},{"name":"Céline Monsarrat","avatar":""},{"name":"Aloïs Le Labo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Argonauts","Argonuts","Argonautas: Heróis do Olimpo","Taru pienistä sankareista"