INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tue-tue-thanh-lien', 'Tuế Tuế Thanh Liên', 'Blooming Days', 'https://phimimg.com/upload/vod/20250601-1/b5c3fcffcd36b582f89034bc554d97ab.jpg', 'https://phimimg.com/upload/vod/20250601-1/51aa90a9649cc8c41d3f61f0b85aef7c.jpg', '<p>Tuế Tuế Thanh Liên được chuyển thể từ tác phẩm Hậu Cung Hi Phi Truyện với bối cảnh là thời vua Ung Chính. Thiếu nữ Lạc Thanh Liên bị đưa vào vương phủ Khúc Lương tham gia tuyển chọn tú nữ. Nào ngờ, trời xui đất khiến, nàng lại trở thành tỳ thiếp của Hạ Liên Tín, con trai thứ ba của lão vương gia. Ban đầu, Thanh Liên một lòng muốn tìm cách trốn thoát, nhưng dần dần nàng thấy được tấm lòng nhân từ của Hạ Liên Tín đối với bách tính nên quyết định ở lại bên cạnh chàng, cùng nhau vượt qua mọi thử thách, trắc trở.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Hoằng San","avatar":""},{"name":"Hà Nhuận Đông","avatar":""},{"name":"Huỳnh Thánh Y","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Blooming Days","Story of Qinglian","Tuế Tuế Thanh Liên","岁岁青莲"]', 1784690324247);
