INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-man-cung-la-mot-nghe', 'May Mắn Cũng Là Một Nghề', 'Miss Lucky Go!', 'https://phimimg.com/upload/vod/20250601-1/2f9cffc3597adc15a1e77153fe079572.jpg', 'https://phimimg.com/upload/vod/20250601-1/9e94cfff8b5ee29dc9c0d586bb016b58.jpg', '<p>Trần Mê Nhân trong vai bạn gái bỏ trốn của chàng trai đẹp trai trong trường, đã phải chịu đựng ba năm khó khăn ở trường trung học để thoát khỏi gánh nặng tình cảm nặng nề của “tình yêu bị đánh cắp” này. Cô khao khát trở thành một nhà thiết kế tượng nhỏ và nộp đơn vào khoa thiết kế của trường đại học với hy vọng có một khởi đầu mới. Tuy nhiên, số phận đã xoay chuyển, cô bị chuyển sang một chuyên ngành khác. Điều đáng tiếc hơn nữa là cô sẽ là bạn cùng lớp suốt 4 năm với mối tình đầu, chàng trai đã nhẫn tâm bỏ rơi cô trong quá khứ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Thất Dư","avatar":""},{"name":"Lưu Đặc","avatar":""},{"name":"Từ Mộc Thiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Miss Lucky Go","锦鲤是个技术活"]', 1784690324247);
