INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-van-chi', 'Lăng Vân Chí', 'The Legends Of Changing Destiny', 'lăng vân chí the legends of changing destiny lâm phong tưởng mộng tiệp ngô khắc quân trình nghiên thu vương tư vận tưởng y y tạ soái tông phong nham lưu bác trương tân lý nhã nam phùng huy chu tán kim vương bồi căn trương diêu vũ dương vân triệu mã hạo ngô kính tâm 大泼猴 the legends of monkey king 凌云志', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ruby-thuy-quai-tuoi-teen', 'Ruby Thủy Quái Tuổi Teen', 'Ruby Gillman, Teenage Kraken', 'https://phimimg.com/upload/vod/20250531-1/3401b69b8dc03f0d257763ee132384c5.jpg', 'https://phimimg.com/upload/vod/20250531-1/4032949cf91e70ec993d08413994318a.jpg', '<p>Ruby Thủy Quái Tuổi Teen kể về cô bé Ruby Gillman nhút nhát, tình cờ phát hiện ra mình là một phần của dòng dõi thủy quái hoàng gia huyền thoại. Và kể từ giây phút này, số phận của cô bé dưới đáy đại dương bỗng thay thổi hoàn toàn, cùng với đó là một sứ mệnh lớn hơn tất cả những gì cô từng mơ đến.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Lana Condor","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Annie Murphy","avatar":""},{"name":"Sam Richardson","avatar":""},{"name":"Liza Koshy","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Colman Domingo","avatar":""},{"name":"Jaboukie Young-White","avatar":""},{"name":"Blue Chapman","avatar":""},{"name":"Ramona Young","avatar":""},{"name":"Eduardo Franco","avatar":""},{"name":"Jane Fonda","avatar":""},{"name":"Nicole Byer","avatar":""},{"name":"Echo Kellum","avatar":""},{"name":"Brianna Arsement","avatar":""},{"name":"Juju Green","avatar":""},{"name":"Preston Arsement","avatar":""},{"name":"Jorda","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Meet the Gillmans","Руби Гилман: Тийн кракен","Krakens y Sirenas: Conoce a los Gillman","Ruby: Aventuras de una kraken adolescente","Ruby, l’ado Kraken","Ruby - Teini-ikäinen merihirviö","Rosa - Det vilde søuhyre","Ruby: Tinejdžerica Kraken","Ruby Marinho, Monstro Adolescente","Ruby Kiewmans: Tiener met tentakels","Ruby Gillman, tinikráken","Ruby Gillman, la ragazza con i tentacoli","Ruby taucht ab","Rūbija - Jūras nezvērs","Ruby Tinejdžerka: Morsko čudoviste","Genç Deniz Canavarı Ruby","Ruby: Najstniški kraken","Krakenteena Ruby","รูบี้ สาวน้อยอสูรทะเล","Кракен-дівча на ім''я Рубі[","Ruby - Havsmonstret","Ruby: Thủy Quái Tuổi Teen","Ρούμπι Ενα κρακεν στην Εφηβεια","Ruby Gillman: Táningssæskrímslið","Ruby Gillman, La Jeune Kraken","Ruby Kieuwmans: Tiener met Tentakels","Ruby Gillman: teismeline merekoleti","ルビー・ギルマン、ティーンエイジ・クラーケン","Ruby: Sjømonsteret","Ruby Gillman, Tinejdžerski Kraken","露比格曼：海怪神话","Ruby Gillman, Teenage Kraken"]', 1784690324247);
