INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-hon-nhai-phan-3', 'Trấn Hồn Nhai (Phần 3)', 'Rakshasa Street (Season 3)', 'https://phimimg.com/upload/vod/20250530-1/36a1b39b9761ae4a4a9e905dbd6b2b2c.jpg', 'https://phimimg.com/upload/vod/20250530-1/44987dc6ca68507816f9751f1e98a8ef.jpg', '<p>Tào Diễm Binh - Trấn hồn tướng của La sát &nbsp;Nhai và Linh Hạ - Người ký linh bước vào con đường sửa chữa Linh hoè. Trấn hồn tướng Nam Ngự Phu của Vũ Lâm Nhai phụng lệnh bắt Tào Diễm Binh, may mắn được Trấn hồn tướng Bắc Lạc sư môn của Bồ Đề Nhai cứu giúp. Nhưng trong lòng Nam Ngự Phu toàn suy nghĩ xấu xa, Bắc Lạc sư môn và cô gái Thuỷ Nhi cũng che giấu bí mật. Tào Diễm Binh và Linh Hạ phải ứng phó thế nào đây?</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lê Tiểu Mông","avatar":""},{"name":"Bảo Mộc Trung Dương","avatar":""},{"name":"Quách Thịnh","avatar":""},{"name":"Tiểu Liên Sát","avatar":""},{"name":"Tề Khắc Kiến","avatar":""},{"name":"Trương Kiệt","avatar":""},{"name":"Đằng Tân","avatar":""},{"name":"Lý Lộ","avatar":""},{"name":"Kiều Phi Phi","avatar":""},{"name":"Sơn Tân","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["镇魂街","Zhen Hun Jie Di Yi Ji","Rakshasa Street Ⅱ","Rakshasa Street","镇魂街 第三季","ちんこんがい","Ракшаса - Улица демонов","鎮魂街","Trấn Hồn Nhai"]', 1784690324247);
