INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tran-hon-nhai-phan-3', 'Trấn Hồn Nhai (Phần 3)', 'Rakshasa Street (Season 3)', 'trấn hồn nhai (phần 3) rakshasa street (season 3) lê tiểu mông bảo mộc trung dương quách thịnh tiểu liên sát tề khắc kiến trương kiệt đằng tân lý lộ kiều phi phi sơn tân 镇魂街 zhen hun jie di yi ji rakshasa street ⅱ rakshasa street 镇魂街 第三季 ちんこんがい ракшаса - улица демонов 鎮魂街 trấn hồn nhai', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-dem-xuat-chung', 'Màn Đêm Xuất Chúng', 'To Be Continued', 'https://phimimg.com/upload/vod/20250530-1/9ae9be44564875d08d7faca31d88049a.jpg', 'https://phimimg.com/upload/vod/20250530-1/c7a12f262133401f24a2b4f0f38c2ac7.jpg', '<p>Báo nhỏ, một &quot;hot TikToker&quot; luôn khao khát nổi tiếng, đang đối mặt với hai khủng hoảng cùng lúc: công ty sắp phá sản và phải bồi thường khoản tiền lớn. Hai cộng sự thân thiết là Chó và Khỉ cũng tuyên bố muốn tan rã nhóm. Trong lúc tuyệt vọng, ba người nhận được một lời mời đặc biệt đến phim trường của một bộ phim kinh dị để bí mật quay lén – họ dự định sẽ &quot;làm cú chót&quot; thật đậm. Không ngờ, họ vô tình quay được cảnh độc quyền khi nữ chính của đoàn phim gặp tai nạn! Cả ba nhanh chóng ứng biến, tiếp tục quay lén với hy vọng đổi đời. Tuy nhiên, họ không lường trước được rằng những tiếng la hét rùng rợn và tình huống kỳ quái bắt đầu ngày càng dồn dập...</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Fan Chengcheng","avatar":""},{"name":"Jiang Long","avatar":""},{"name":"Jiang Yi","avatar":""},{"name":"Wang Zexuan","avatar":""},{"name":"Liang Long","avatar":""},{"name":"Kong Lianshun","avatar":""},{"name":"Jiang Shimeng","avatar":""},{"name":"Gan Yunchen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["惊昏记","Liao bu qi de ye wan","Vlogger","To Be Continued","了不起的夜晚"]', 1784690324247);
