INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-canh-sat-dong-bac-2', 'Câu Chuyện Cảnh Sát Đông Bắc 2', 'Fight Against Evil 2', 'https://phimimg.com/upload/vod/20250530-1/87f366f9ff40507a9d1279733ca9587b.jpg', 'https://phimimg.com/upload/vod/20250530-1/129fd70f7fcea466b7517f940e8be08a.jpg', '<p>Bộ phim này là phần tiền truyện của bộ phim &quot;Câu Chuyện Cảnh Sát Đông Bắc&quot;, được đoàn làm phim gốc tái tổ chức và quay dựng lại. Câu chuyện kể về một cảnh sát Đông Bắc đầy lòng căm phẫn là Lý Hồng Kỳ (do Tạ Miêu thủ vai) trong một cuộc giao hữu, tình cờ phát hiện ra sự tồn tại của chuỗi ngành công nghiệp liên quan đến việc buôn bán mại dâm tại địa phương. Khi tiến hành điều tra sâu hơn, một &quot;đế chế&quot; đồ sộ về mại dâm và kiểm soát ma túy bắt đầu được hé lộ, đe dọa đến an nguy tính mạng. Anh không ngờ rằng ngay cả người em trai chí cốt của mình cũng dính dáng đến... Đối diện với những tội phạm như súc vật và vô số phụ nữ vô tội bị tổn thương, Lý Hồng Kỳ quyết định chống chọi đến cùng, quyết tâm loại bỏ &quot;khối u&quot; này.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tạ Miêu","avatar":""},{"name":"Trương Hạo Sâm","avatar":""},{"name":"Giang Dịch Huyên","avatar":""},{"name":"Trương Lập","avatar":""},{"name":"Hình Hán","avatar":""},{"name":"Lưu Phong Siêu","avatar":""},{"name":"Phòng Nham","avatar":""},{"name":"Chu Hiển Hân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["North East Police Story 2","Fight Against Evi 2","东北警察故事2"]', 1784690324247);
