INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-canh-sat-dong-bac-2', 'Câu Chuyện Cảnh Sát Đông Bắc 2', 'Fight Against Evil 2', 'câu chuyện cảnh sát đông bắc 2 fight against evil 2 tạ miêu trương hạo sâm giang dịch huyên trương lập hình hán lưu phong siêu phòng nham chu hiển hân north east police story 2 fight against evi 2 东北警察故事2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-hon-ruoc-le', 'Vong Hồn Rước Lễ', 'The Communion Girl', 'https://phimimg.com/upload/vod/20250530-1/37ff656fca8b3baf714b3d9515135a1b.jpg', 'https://phimimg.com/upload/vod/20250530-1/7de6b00efcfab271b34f468f346bb1a2.jpg', '<p>Dựa trên truyền thuyết đô thị kinh dị bậc nhất Tây Ban Nha, Vong Hồn Rước Lễ kể về hồn ma ác nghiệt trú ngụ trong thân xác của một con búp bê. Bối cảnh phim diễn ra ở Tây Ban Nha vào cuối thập niên 1980. Sara (Carla Campra) vừa chuyển nhà tới một thị trấn nhỏ khép kín ở tỉnh Tarrgona và đang tìm cách hoà nhập với bạn bè cùng lứa tại đây. Tuy nhiên, chỉ có cô nàng hướng ngoại Rebe (Aina Quiñones) là người sẵn lòng kết giao với Sara. Một hôm, cả hai rủ nhau đi chơi ở một câu lạc bộ đêm và về nhà rất muộn. Trên đường về, họ đụng phải một cô gái nhỏ mặc váy trắng, tay cầm theo con búp bê. Từ thời khắc đó, cơn ác mộng mới thực sự bắt đầu.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Carla Campra","avatar":""},{"name":"Aina Quiñones","avatar":""},{"name":"Marc Soler","avatar":""},{"name":"Carlos Oviedo","avatar":""},{"name":"Olimpia Roch","avatar":""},{"name":"María Molins","avatar":""},{"name":"Xavi Lite","avatar":""},{"name":"Anna Alarcón","avatar":""},{"name":"Victor Solé","avatar":""},{"name":"Daniel Rived","avatar":""},{"name":"Jacob Torres","avatar":""},{"name":"Manel Barceló","avatar":""},{"name":"Mercè Llorens","avatar":""},{"name":"Claudia Riera","avatar":""},{"name":"Mariona Lucas","avatar":""},{"name":"Andrea Carrión Samaniego","avatar":""},{"name":"María Fontcuberta","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A primeira comunhão","La niña de la comunión","駭人骨娃娃","Vong Hồn Rước Lễ","A Menina da Comunhão","Заклятье. Первое пробуждение","Comunión Con El Diablo"]', 1784690324247);
