INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('katak-va-su-menh-chinh-phuc-dai-duong', 'Katak Và Sứ Mệnh Chinh Phục Đại Dương', 'Katak: The Brave Beluga', 'https://phimimg.com/upload/vod/20250527-1/ffe4d556bbc08c99b0f5a407eb88aefd.jpg', 'https://phimimg.com/upload/vod/20250527-1/f07338f040bce1ee9e6ec936e2d20f0b.jpg', '<p>Chú cá voi Katak vẫn nhỏ bé và xám xịt dù đã tới tuổi trưởng thành. Để chứng minh bản thân và thực hiện di nguyện của bà, Katak quyết định khởi hành đến Tảng Băng Vĩ Đại - một nơi ngập tràn hiểm nguy.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Lồng Tiếng', 'FHD', 'Canada', 0, '[{"name":"Alexandre Bacon","avatar":""},{"name":"Nancy Bernier","avatar":""},{"name":"Jeff Boudreault","avatar":""},{"name":"Benoît Brière","avatar":""},{"name":"Jérémie Desbiens","avatar":""},{"name":"Martin Drainville","avatar":""},{"name":"Marie-Thérèse Fortin","avatar":""},{"name":"Carolanne Foucher","avatar":""},{"name":"Yves Jacques","avatar":""},{"name":"Émilie Josset","avatar":""},{"name":"Renaud Lacelle-Bourdon","avatar":""},{"name":"Maxime Le Flaguais","avatar":""},{"name":"Jacques Leblanc","avatar":""},{"name":"Johanne Léveillé","avatar":""},{"name":"Justi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Katak. Podwodna przygoda","Kataks: Baltvaļa ceļojums","Julge vaalapoeg Katak","Katak, le brave béluga"]', 1784690324247);
