INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-an-danh', 'Kẻ Ẩn Danh', 'Bad Blood', 'https://phimimg.com/upload/vod/20250526-1/848aae26fbb19037760d59e475f116d8.jpg', 'https://phimimg.com/upload/vod/20250526-1/520d233385ba79e203798d8809e57f8d.jpg', '<p>Lâm - một người đàn ông từng là xã hội đen nhưng lại mất trí nhớ và nay đang lẩn trốn như một người bình thường, kiếm sống bằng lao động chân tay. Lâm sống cùng vợ - Hạnh và con gái riêng của cô là Hiền. Hiền vẫn chưa chấp nhận tình yêu thương của chú Lâm dành cho mình. Hiền lớn lên với sự bốc đồng và bị dụ dỗ bởi Tiến - một thanh niên đạo đức giả chuyên dụ dỗ những cô gái vào nhà thổ để trở thành gái mại dâm. Xuyên suốt bộ phim là hành trình đi tìm con gái của Lâm</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Mạc Văn Khoa","avatar":""},{"name":"Quốc Trường","avatar":""},{"name":"Vân Trang","avatar":""},{"name":"Mai Cat Vi","avatar":""},{"name":"Nguyễn Mạnh Lân","avatar":""},{"name":"Thua Tuan Anh","avatar":""},{"name":"Đàm Phương Linh","avatar":""},{"name":"Tuyền Mập","avatar":""},{"name":"Lam Thanh Nha","avatar":""},{"name":"Kim Nhung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Kẻ Ẩn Danh"]', 1784690324248);
