INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-dai-dong-noi-2025', 'Hoa Dại Đồng Nội', 'Wild Flowers', 'https://phimimg.com/upload/vod/20250524-1/ee6e6148fbf148b24432754dd223d528.jpg', 'https://phimimg.com/upload/vod/20250524-1/2fe245641959890f0f237354c30070df.jpg', '<p>Kevin là một nam diễn viên điện ảnh quyến rũ, hiện đang quay phim tại một địa điểm hẻo lánh. Khi công việc kết thúc, họ đã tổ chức một buổi tiệc với dàn diễn viên, ngập tràn rượu và ma túy. Sau một đêm vui vẻ và ăn chơi thác loạn, Kevin khăng khăng muốn trở về thành phố, bất chấp những lời cảnh báo và khuyên ngăn của các đồng nghiệp rằng điều đó có thể rất nguy hiểm. Và như thể họ đã dự đoán trước điều gì sẽ xảy ra, Kevin mất lái khi đang lái xe và gặp tai nạn nghiêm trọng…</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Arron Villaflor","avatar":""},{"name":"Sheila Snow","avatar":""},{"name":"Chloe Jenna","avatar":""},{"name":"Jeric Raval","avatar":""},{"name":"Sheree","avatar":""},{"name":"Marissa Sanchez","avatar":""},{"name":"Gerald Madrid","avatar":""},{"name":"Dominic Roco","avatar":""},{"name":"Raul Morit","avatar":""},{"name":"Dianne Moldez","avatar":""},{"name":"Van Allen Ong","avatar":""},{"name":"Chloe Mendoza","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ligaw na Bulaklak"]', 1784690324248);
