INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lam-chuyen-phan-7', 'Lắm Chuyện (Phần 7)', 'Big Mouth (Season 7)', 'lắm chuyện (phần 7) big mouth (season 7) nick kroll john mulaney jessi klein jason mantzoukas fred armisen maya rudolph jordan peele maria bamford jenny slate gina rodriguez david thewlis ali wong chelsea peretti bobby cannavale andrew rannells zachary quinto ayo edebiri فم كبير 大嘴巴 hormonokkal túlfűtve פה גדול ビッグマウス 빅마우스 gură bogată 青春無密語 bigmouth big mouth', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-nhan-that-kho-voi-ninja', 'Hôn Nhân Thật Khó Với Ninja', 'Marriage Is Difficult For A Ninja', 'https://phimimg.com/upload/vod/20250523-1/9dca319620909da76a7a72c48f0c328c.jpg', 'https://phimimg.com/upload/vod/20250523-1/713c286f8679c16c6287a35c0d7ca432.jpg', '<p><span style="text-wrap-mode: wrap;">Kusakari Hotaru đã kết hôn với Kusakari Gorou và hiện đang làm dược sĩ tại một nhà thuốc. Chồng cô là một nhân viên giao hàng của bưu điện. Hai người đến với nhau vì tình yêu nhưng lại không biết rằng đối phương đều đang che giấu một bí mật: Đó là thân phận thực sự của họ chính là Ninja! Trong khi Hotaru là ninja của gia tộc Kouga thì Gorou là ninja thuộc gia tộc Iga và hai gia tộc này lại là kì phùng địch thủ của nhau! Cuộc hôn nhân của họ ban đầu rất hạnh phúc nhưng sau thời gian chung sống, hai người xảy ra mâu thuẫn liên quan đến vấn đề sinh hoạt trong gia đình. Đúng lúc đó, hai người nhận được nhiệm vụ và sau đó, một vụ ám sát xảy ra đã đẩy hai người ở thế đối đầu. Liệu vợ chồng họ sẽ chọn cuộc hôn nhân của mình hay là truyền thống của gia tộc?</span></p>', 'Full', 11, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nanao","avatar":""},{"name":"Nobuyuki Suzuki","avatar":""},{"name":"Ryo Katsuji","avatar":""},{"name":"Maika Yamamoto","avatar":""},{"name":"Ayako Yoshitani","avatar":""},{"name":"Taiyu Fujiwara","avatar":""},{"name":"Miwako Kakei","avatar":""},{"name":"Rie Tomosaka","avatar":""},{"name":"Arata Furuta","avatar":""},{"name":"Masachika Ichimura","avatar":""},{"name":"Shinji Rokkaku","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"P