INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-than-bi', 'Bác Sĩ Thần Bí', 'Dr. Lifesaver', 'https://phimimg.com/upload/vod/20250521-1/4d52e761d534a7e5093c0a3ee764c6a6.jpg', 'https://phimimg.com/upload/vod/20250521-1/74a13cfa97ed7cc22080c3f9b215db0e.jpg', '<p>Thảm họa hai mươi năm trước đã cướp mất người bạn gái bác sĩ của bác sĩ Đỗ Lạc Sinh, khiến ông thất vọng mà rời khỏi thể chế của bệnh viện, từ đó sống ẩn mình trong một phòng khám nhỏ, hóa thân thành người giao thuốc, cấp cứu cho các bệnh nhân, đồng thời chữa lành những tổn thương và cảm giác tội lỗi bên trong bản thân mình.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 14, 2023, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Vương Thức Hiền","avatar":""},{"name":"Trần Gia Hoa","avatar":""},{"name":"Kha Thúc Nguyên","avatar":""},{"name":"Giang Tổ Bình","avatar":""},{"name":"Lý Duy Duy","avatar":""},{"name":"Phan Quân Luân","avatar":""},{"name":"Khâu Tư Cầm","avatar":""},{"name":"Lâm Vân Nghệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sheng Ming Bu Shou","Dr. Lifesaver","Doctor Lifesaver","生命捕手"]', 1784690324248);
