INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-vung-dat-ly-tuong-tren-bau-troi', 'Doraemon: Nobita và Vùng Đất Lý Tưởng Trên Bầu Trời', 'Doraemon the Movie: Nobita''s Sky Utopia', 'https://phimimg.com/upload/vod/20250521-1/e0d158cdb1b12f7cae32426dc3695ee0.jpg', 'https://phimimg.com/upload/vod/20250521-1/27f8594f3cb3fc39982d825896a8a9cf.jpg', '<p>Phim điện ảnh Doraemon: Nobita Và Vùng Đất Lý Tưởng Trên Bầu Trời kể câu chuyện khi Nobita tìm thấy một hòn đảo hình lưỡi liềm trên trời mây. Ở nơi đó, tất cả đều hoàn hảo… đến mức cậu nhóc Nobita mê ngủ ngày cũng có thể trở thành một thần đồng toán học, một siêu sao thể thao. Cả hội Doraemon cùng sử dụng một món bảo bối độc đáo chưa từng xuất hiện trước đây để đến với vương quốc tuyệt vời này. Cùng với những người bạn ở đây, đặc biệt là chàng robot mèo Sonya, cả hội đã có chuyến hành trình tới vương quốc trên mây tuyệt vời… cho đến khi những bí mật đằng sau vùng đất lý tưởng này được hé lộ.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Ren Nagase","avatar":""},{"name":"Miki Fujimoto","avatar":""},{"name":"Ryota Yamasato","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Yasunori Matsumoto","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Eiga Doraemon: Nobita to Sora no Utopia","โดราเอมอน ตอน ฟากฟ้าแห่งยูโทเปียของโนบิตะ","דורימון: נוביטה''ס סקיי אוטופיה","Doraemon the Movie Nobitas Sky Utopia","映画ドラえもん のび太と空の理想郷","Doraemon: Nobita''s Sky Utopia","哆啦A梦：大雄与天空乌托邦","โดราเอมอนเดอะมูฟวี่ ตอนฟากฟ้าแห่งยูโทเปียของโนบิตะ","哆啦A梦 大雄与天空的理想乡","電影多啦A夢：大雄與天空的理想鄉"]', 1784690324248);
