INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-vung-dat-ly-tuong-tren-bau-troi', 'Doraemon: Nobita và Vùng Đất Lý Tưởng Trên Bầu Trời', 'Doraemon the Movie: Nobita''s Sky Utopia', 'doraemon: nobita và vùng đất lý tưởng trên bầu trời doraemon the movie: nobita''s sky utopia wasabi mizuta megumi oohara yumi kakazu subaru kimura tomokazu seki marina inoue inori minase ren nagase miki fujimoto ryota yamasato kotono mitsuishi yasunori matsumoto eiga doraemon: nobita to sora no utopia โดราเอมอน ตอน ฟากฟ้าแห่งยูโทเปียของโนบิตะ דורימון: נוביטה''ס סקיי אוטופיה doraemon the movie nobitas sky utopia 映画ドラえもん のび太と空の理想郷 doraemon: nobita''s sky utopia 哆啦a梦：大雄与天空乌托邦 โดราเอมอนเดอะมูฟวี่ ตอนฟากฟ้าแห่งยูโทเปียของโนบิตะ 哆啦a梦 大雄与天空的理想乡 電影多啦a夢：大雄與天空的理想鄉', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-hon-the-khe-uoc-cua-cong-tuoc', 'Vị Hôn Thê Khế Ước Của Công Tước', 'Why Raeliana Ended Up at the Duke''s Mansion', 'https://phimimg.com/upload/vod/20250521-1/10ddad673e6da9274d0f4a58d60046ba.jpg', 'https://phimimg.com/upload/vod/20250521-1/d5d1c49ec5830978165edd9a0fb86fc5.jpg', '<p>Chuyển sinh thành nhân vật phụ xấu số trong tiểu thuyết, Rinko đề nghị nhân vật chính của câu chuyện làm hôn phu của mình trong sáu tháng. Nhưng liệu điều đó có đủ để cứu mạng cô?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yume Miyamoto","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Shuichiro Umeda","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Yumika Yano","avatar":""},{"name":"Junichi Suwabe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Reason Why Raeliana Ended up at the Duke''s Mansion","The Duke''s Fiancée","公爵的契约未婚妻","她去公爵家的理由","Wie ich auf dem Landsitz Wynknight überlebte","¿Por qué Raeliana terminó en la mansión del duque?","Comment Raeliana a survécu au manoir Wynknight","Comment j''ai survécu au Manoir Wynknight","Kanojo ga Koushaku-tei ni Itta Riyuu","Kanojo ga Kōshaku-tei ni Itta Riyū","Kanojo ga Kōshakutei ni Itta Riyū","Kanojo ga Koushakutei ni Itta Riyuu","그녀가 공작저로 가야했던 사정","Geunyeoga Gongjagjeolo Gaya Haessdeon Sajeong","Лериана, невеста герцога по контракту","彼女が公爵邸に行った理由"]', 1784690324248);
