INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doc-chien-2', 'Độc chiến 2', 'Believer 2', 'độc chiến 2 believer 2 cho jin-woong cha seung-won han hyo-joo oh seung-hoon lee zoo-young kim dong-young jung jun-won seo ha-jung kang seung-hyun cho han-cheul lee sang-hee choi gwang-il park hae-jun yang ik-june tzi ma byun yo-han jun suk-ho ahn hyun-ho creyente ii 毒战2 독전 2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trach-quan-ky', 'Trạch Quân Ký', 'Choice Husband', 'https://phimimg.com/upload/vod/20240116-1/83ae3dbf8e4b096bc6b67fcdf2bc225c.jpg', 'https://phimimg.com/upload/vod/20240116-1/5b587cd2382c9c498384210ea8b80b3b.jpg', '<p>Thẩm Diệu (Trương Tuyết Nghênh đóng) là con gái nhà phú ông giàu có, vẻ ngoài ưa nhìn, nhưng lại trở thành người mà không ai dám cưới của thành Dương Châu. Nguyên nhân chỉ vì hai lần thành thân trước quá tốt. Lần thứ nhất, thì gả cho Bùi Diễn Trinh (Hình Chiêu Lâm đóng) là thư sinh nhà quan, có tính tình hiền lành, chung sống với nhau cũng được xem như hòa thuận. Nhưng nào ngờ đâu Hoàng thượng truyền thánh chỉ hòa ly, buộc hai người phải chia xa. Trời xui đất khiến, đến lần thứ hai, Thẩm Diệu gả cho Tống Tịch Viễn (Vương Dĩ Luân đóng) là một công tử thương gia giàu có, nhưng mới thành hôn chưa được hai tháng thì Thẩm Diệu có tin vui, mọi người xung quanh bàn tán xôn xao về thời gian của cái thai, quá bất lực, Thẩm Diệu chỉ đành hòa ly lần nữa. Thẩm Diệu vốn cởi mở, nên chuẩn bị đi xem mắt, nhưng lúc này hai người phu quân cũ lại cùng tìm đến. Tình yêu và thù hận ngày càng loạn giữa ba người dần được hé mở dưới vỏ bọc âm mưu của triều đình.<br/>&nbsp;</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hình Chiêu Lâm","avatar":""},{"name":"Trương Tuyết Nghênh","avatar":""},{"name":"Vương Dĩ Luân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324248);
