INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-la-tung-yeu-thuong', 'Người Lạ Từng Yêu Thương', 'Strangers Again', 'https://phimimg.com/upload/vod/20250518-1/de408e32fdcfe7612e4e6a6a631aa03c.jpg', 'https://phimimg.com/upload/vod/20250518-1/3aef75c5c215d3c44ba5f24b12c173fb.jpg', '<p>Xoay quanh câu chuyện của Oh Ha Ra và Goo Eun Beom. Hai nhân vật chính từng là một cặp vợ chồng đầy đam mê, nhưng cuộc hôn nhân của họ kết thúc trong ly hôn do những hiểu lầm và tổn thương khó hóa giải. Sau khi chia tay, họ trở thành đồng nghiệp tại cùng một văn phòng luật chuyên về các vụ ly hôn.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2023, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang So-ra","avatar":""},{"name":"Jang Seung-jo","avatar":""},{"name":"Lee Jae-won","avatar":""},{"name":"Cho Eun-ji","avatar":""},{"name":"Moo Jin-sung","avatar":""},{"name":"Kil Hae-yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Namyi Dwel Su Yidseulgga","Can We Be Strangers?","남이 될 수 있을까"]', 1784690324248);
