INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hon-nhan-hoan-hao', 'Cuộc Hôn Nhân Hoàn Hảo', 'Perfect Marriage Revenge', 'https://phimimg.com/upload/vod/20250506-1/49c358e24238df4a42549dee2263f966.jpg', 'https://phimimg.com/upload/vod/20250506-1/671caf6e6bf0247879b8d73066472737.jpg', '<p>Phim xoay quanh cô gái mồ côi lương thiện Han Yi Joo (Jung Yoo Min) được một gia đình giàu có nhận nuôi. Thế nhưng thay vì yêu thương, Yi Joo lại trở thành &quot;con cờ&quot; bị lợi dụng trong bối cảnh hào môn, về sau trở thành vợ của Yoo Se Hyeok (Oh Seung Yeon). Se Hyeok cưới cô chị nhưng vốn dĩ chỉ yêu cô em là Han Yoo Ra (Jin Ji Hee). Biến cố ập đến khi Yi Joo bị hãm hại và qua đời, sau đó cô &quot;xuyên không&quot; về thời điểm trước khi cưới Se Hyeok. Lúc này, Yi Joo đã quyết định hủy hôn, lập kế hoạch trả thù những ai đã lợi dụng và hại cô.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Yoo-min","avatar":""},{"name":"Sung Hoon","avatar":""},{"name":"Jin Ji-hee","avatar":""},{"name":"Kang Shin-hyo","avatar":""},{"name":"Oh Seung-yun","avatar":""},{"name":"Lee Min-young","avatar":""},{"name":"Jeon No-min","avatar":""},{"name":"Kim Eung-soo","avatar":""},{"name":"Ban Hyo-jung","avatar":""},{"name":"Jin Hee-kyung","avatar":""},{"name":"Lee Byung-joon","avatar":""},{"name":"Lee Mi-sook","avatar":""},{"name":"Oh Ha-ni","avatar":""},{"name":"Lee Myung-hoon","avatar":""},{"name":"Lee Won-hee","avatar":""},{"name":"Kim Ye-ryeong","avatar":""},{"name":"Song Su-i","avatar":""},{"name":"Lee Da-hae","avatar":""},{"name":"Do Yu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["완벽한 결혼의 정석"]', 1784690324248);
