INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-hon-nhan-hoan-hao', 'Cuộc Hôn Nhân Hoàn Hảo', 'Perfect Marriage Revenge', 'cuộc hôn nhân hoàn hảo perfect marriage revenge jung yoo-min sung hoon jin ji-hee kang shin-hyo oh seung-yun lee min-young jeon no-min kim eung-soo ban hyo-jung jin hee-kyung lee byung-joon lee mi-sook oh ha-ni lee myung-hoon lee won-hee kim ye-ryeong song su-i lee da-hae do yu 완벽한 결혼의 정석', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-sinh-lo-bat-thuc-duong-doi-la-lam', 'Nhân Sinh Lộ Bất Thục (Đường Đời Lạ Lẫm)', 'Godspeed', 'https://phimimg.com/upload/vod/20250416-1/816ec68982bc1b32ea276655ece3f6a2.jpg', 'https://phimimg.com/upload/vod/20250416-1/2f1f8bca02bab49b0ea9c5a6df43f033.jpg', '<p>Trưởng đội xe vận chuyển Châu Đông Hải và vợ mình là Hoắc Mai Mai vô tình đồng hành trên chuyến xe tự lái cùng với con gái Châu Vi Vũ và bạn trai của con gái là Vạn Nhất Phàm, bắt đầu chuyến về quê đầy những điều lạ lẫm. Châu Đông Hải quyết định mượn cơ hội lần này để quan sát toàn diện người con rể. Vạn Nhất Phàm cũng dùng cả tính mạng để giải thích thế nào là &quot;lật xe kiểu sách giáo khoa&quot;. Trên đường đi, họ gặp phải tai nạn xe dã ngoại với &quot;chuyên gia chọc tức&quot; trưởng phòng Giả, trò hề say rượu tại sơn trang &quot;gà rừng&quot; của Quang Tử - thanh mai trúc mã của Vi Vũ, và cuộc đại chiến vây bắt &quot;bọn trộm xăng&quot;. Hành trình về quê gà bay chó chạy đầy ắp tình huống khó xử nhưng cũng không thiếu những tiếng cười sảng khoái.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Kiều Sam","avatar":""},{"name":"Phạm Thừa Thừa","avatar":""},{"name":"Mã Lệ","avatar":""},{"name":"Trương Tịnh Nghi","avatar":""},{"name":"Thường Viễn","avatar":""},{"name":"Điền Vũ","avatar":""},{"name":"Y Chính","avatar":""},{"name":"Tiểu Ái","avatar":""},{"name":"Trương Lỗi","avatar":""},{"name":"Trương Hi Nhiên","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Godspeed","人生路不熟"]', 1784690324248);
