INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninh-an-nhu-mong', 'Ninh An Như Mộng', 'Story of Kunning Palace', 'https://phimimg.com/upload/vod/20250516-1/a8dcdb46d759d82c85b9d119ce8c7c05.jpg', 'https://phimimg.com/upload/vod/20250516-1/fa2ecdf84ab43c7e67fec7878a227e89.jpg', '<p>Phim là câu chuyện kể về cuộc đời của Khương Tuyết Ninh – người không từ thủ đoạn để lên ngôi hoàng hậu. Sau cùng, Tuyết Ninh cũng chẳng thể có được tham vọng đó, thậm chí còn bị ép tự sát. Kiếp sau, để chuộc lại những lỗi lầm mình từng gây ra nàng thề với lòng sẽ tu tâm thay đổi. Nhưng không ngờ, cô vẫn vào cung và trở thành học trò của Tạ Nguy. Trong khi nhận được sự dạy dỗ của Tạ Nguy, Khương Tuyết Ninh bí mật lên kế hoạch ngăn chặn &quot;Lễ trao vương miện&quot; sắp tới của Yến Lâm. Với kế hoạch của Tạ Nguy và Khương Tuyết Ninh, mạng sống của gia đình Yến Lâm đã được cứu. Sau &quot;Lễ trao vương miện&quot;, Khương Tuyết Ninh đã bị kéo vào tham gia vào kế hoạch của triều đình để loại bỏ những kẻ nổi loạn chống lại Vua Bình Nam, và cùng Trương Già xâm nhập cung điện kẻ thù...</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 18, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Lu","avatar":""},{"name":"Zhang Linghe","avatar":""},{"name":"Wang Xingyue","avatar":""},{"name":"Jacky Zhou","avatar":""},{"name":"Liu Xiening","avatar":""},{"name":"Wang Ziteng","avatar":""},{"name":"Elisa Ye","avatar":""},{"name":"Dai Yi","avatar":""},{"name":"Zhou Dawei","avatar":""},{"name":"Tang Mengjia","avatar":""},{"name":"Qin Tianyu","avatar":""},{"name":"Joyin Cai","avatar":""},{"name":"Cui Shaoyang","avatar":""},{"name":"Yu Zhongli","avatar":""},{"name":"Zhou Tishun","avatar":""},{"name":"Liu Jinyan","avatar":""},{"name":"Lu Yanbei","avatar":""},{"name":"Wang Yani","avatar":""},{"name":"Yi Nan Ting","avatar":""},{"name":"Zu Kaer","avatar":""},{"name":"Fan Jingwen","avatar":""},{"name":"Yvonne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Ning An Ru Meng","坤宁","Kun Ning","命转皇后","宁安如梦","寧安如夢(ねいあんにょむ)～宮廷にふたたび舞い降りる愛～","ချစ်ရိပ်ခြုံလွှမ်း အိပ်မက်နန်းတော်","เล่ห์รักวังคุนหนิง","寧安如夢","Story of Kunning Palace"]', 1784690324248);
