INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ninh-an-nhu-mong', 'Ninh An Như Mộng', 'Story of Kunning Palace', 'ninh an như mộng story of kunning palace bai lu zhang linghe wang xingyue jacky zhou liu xiening wang ziteng elisa ye dai yi zhou dawei tang mengjia qin tianyu joyin cai cui shaoyang yu zhongli zhou tishun liu jinyan lu yanbei wang yani yi nan ting zu kaer fan jingwen yvonne ning an ru meng 坤宁 kun ning 命转皇后 宁安如梦 寧安如夢(ねいあんにょむ)～宮廷にふたたび舞い降りる愛～ ချစ်ရိပ်ခြုံလွှမ်း အိပ်မက်နန်းတော် เล่ห์รักวังคุนหนิง 寧安如夢 story of kunning palace', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-kia-dong-song-va-trong-rung-cay', 'Bên Kia Dòng Sông và Trong Rừng Cây', 'Across the River and Into the Trees', 'https://phimimg.com/upload/vod/20250515-1/14f059cf0554be709898ecbe7f2179fb.jpg', 'https://phimimg.com/upload/vod/20250515-1/0923c0c22a837a0aa30fd9715dca544c.jpg', '<p>Across the River and Into the Trees (2022) là một bộ phim tâm lý - chiến tranh, dựa trên tiểu thuyết cùng tên của Ernest Hemingway. Phim Lấy bối cảnh Venice sau Thế chiến II, phim kể về Đại tá Richard Cantwell, một sĩ quan quân đội Mỹ mang trong mình vết thương thể xác lẫn tinh thần. Ông bị ám ảnh bởi quá khứ chiến tranh và biết rằng mình không còn nhiều thời gian. Trong những ngày cuối cùng, ông quyết định thực hiện chuyến đi săn và ghé thăm những nơi từng có ý nghĩa với mình. Trên hành trình đó, ông gặp một nữ quý tộc trẻ tuổi, người mang đến cho ông niềm hy vọng về sự đổi thay và tình yêu.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Liev Schreiber","avatar":""},{"name":"Matilda De Angelis","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Laura Morante","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Giulio Berruti","avatar":""},{"name":"Enzo Cilenti","avatar":""},{"name":"Sabrina Impacciatore","avatar":""},{"name":"Alessandro Bressanello","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["در امتداد رودخانه و به سمت درخت‌ها","Across the River and into the Trees"]', 1784690324248);
