INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-tu-than', 'Hàm Tử Thần', 'Deep Fear', 'https://phimimg.com/upload/vod/20250515-1/e16b830131027752f96df37d2d37e8de.jpg', 'https://phimimg.com/upload/vod/20250515-1/59f96bef34f5c820a33da839631698e8.jpg', '<p>Trên chuyến hành trình xuyên biển đoàn tụ gia đình, một cơn bão buộc Naomi rời khỏi lộ trình và vướng vào phi vụ nguy hiểm dưới lòng đại dương. Nhiệm vụ khó thành, hàm tử thần chực chờ nuốt chửng, liệu Naomi có thể thoát khỏi biển máu!?</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Mădălina Ghenea","avatar":""},{"name":"Ed Westwick","avatar":""},{"name":"Macarena Gómez","avatar":""},{"name":"Stany Coppet","avatar":""},{"name":"Ibrahima Gueye","avatar":""},{"name":"David Leguesse","avatar":""},{"name":"Mariana Garradas","avatar":""},{"name":"Marco Canadea","avatar":""},{"name":"John-Paul Pace","avatar":""},{"name":"Tenika Mahoney","avatar":""},{"name":"Shane Rowe","avatar":""},{"name":"Natasha Tikasz","avatar":""},{"name":"Robert Capelli Jr.","avatar":""},{"name":"Matthew Charlery-Smith","avatar":""},{"name":"Mike Parish","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["ترس عمیق","딥 피어","Deep Fear"]', 1784690324248);
