INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-tong-phu-nhan-lai-chan-anh-roi', 'Cố Tổng, Phu Nhân Lại Chặn Anh Rồi', 'Mr. Gu, Your Wife Has Blocked You Again', 'https://phimimg.com/upload/vod/20250513-1/d4cba192ccd9e2cdff6fb6bd858b6c69.jpg', 'https://phimimg.com/upload/vod/20250513-1/bc4ba86fe562d5105afc4161c0d202ab.jpg', '<p>Bộ phim kể về câu chuyện tình yêu giữa tổng giám đốc Cố Cảnh Diễm và vợ là Kiều Nhược Tinh. Cố Cảnh Diễm luôn nhớ về mối tình đầu và thờ ơ với vợ mình. Sau khi bị tổn thương, Kiều Nhược Tinh quyết định ly hôn và chặn mọi liên lạc với anh. Nhận ra tình cảm thật sự của mình, Cố Cảnh Diễm cố gắng hàn gắn mối quan hệ, nhưng Kiều Nhược Tinh đã không còn tin tưởng anh nữa.</p>', 'Hoàn Tất (100/100)', 100, 'series', 'completed', 28, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Cách Cách","avatar":""},{"name":"Thân Hạo Nam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["顧總，太太又把您拉黑了","Gu Zong, Tai Tai You Ba Nin La Hei Le","Mr. Gu, Your Wife Has Blocked You Again","顾总，太太又把您拉黑了"]', 1784690324248);
