INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jane-phan-1', 'Jane (Phần 1)', 'Jane (Season 1)', 'https://phimimg.com/upload/vod/20240309-1/f593ac38d3d651dace0b53562c212c21.jpg', 'https://phimimg.com/upload/vod/20240309-1/bbec007aa27f8658196a363b8d234cc4.jpg', '<p>Nhà bảo vệ môi trường mới chớm nở Jane là một cô bé 9 tuổi đang thực hiện nhiệm vụ cứu các loài động vật đang bị đe dọa. Sử dụng trí tưởng tượng mạnh mẽ của mình, Jane đưa những người bạn thân nhất của mình là David và chú tinh tinh Greybeard vào những cuộc phiêu lưu sử thi để giúp bảo vệ động vật hoang dã trên toàn thế giới.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ava Louise Murchison","avatar":""},{"name":"Mason Blomberg","avatar":""},{"name":"Tamara Almeida","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324248);
