INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('james-may-o-nau-an-phan-2', 'James May: Ơ Nấu Ăn (Phần 2)', 'James May: Oh Cook (Season 2)', 'https://phimimg.com/upload/vod/20250512-1/0812cc4fe425a7c4357f2b0d1099b5a9.jpg', 'https://phimimg.com/upload/vod/20250512-1/96c597cea33ef593deb0238d5430b9ea.jpg', '<p>James May không phải là đầu bếp. Nhưng đó chính là điều cốt lõi: bạn không cần phải là một đầu bếp tài ba để nấu được những món ăn ngon. Trong chương trình, anh sẽ đưa khán giả đến với Viễn Đông, Địa Trung Hải, và cả những quán rượu địa phương – tất cả đều từ căn bếp của một chuyên gia kinh tế gia đình. James sẽ thực hiện những công thức món ăn ngon mà bạn hoàn toàn có thể tự làm, với nguyên liệu dễ kiếm, và đặc biệt là không hề dùng đến những chiêu trò thường thấy trong các chương trình nấu ăn trên truyền hình.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Nikki Morgan","avatar":""},{"name":"James May","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["James May: Oh Cook!"]', 1784690324248);
