INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-ac-linh', 'Thợ Săn Ác Linh', 'Dark Gathering', 'https://phimimg.com/upload/vod/20250512-1/f5e4878e1d60e2d8cfa75a451d8b724f.jpg', 'https://phimimg.com/upload/vod/20250512-1/f20691fe7bd2c0dba96ee68613dcb921.jpg', '<p>Keitarou, chàng trai có khả năng thu hút ma quỷ, được thuê làm gia sư cho một cô bé mang tên gọi Yayoi, người có thể trông thấy ma quỷ và đang trong công cuộc tìm kiếm con ma đã mang người mẹ của mình đi mất.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yu Sasahara","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Kana Hanazawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["DARK GATHERING","ダークギャザリング"]', 1784690324248);
