INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-dau-tu-su-ket-thuc', 'Bắt Đầu Từ Sự Kết Thúc', 'The End We Start From', 'https://phimimg.com/upload/vod/20250511-1/fb2d178acad85e94fc4f08c70d324eb4.jpg', 'https://phimimg.com/upload/vod/20250511-1/46cd1f89d3d1df4f0130fc8775e6b428.jpg', '<p>Một người phụ nữ cố gắng tìm đường về nhà cùng đứa con mới sinh trong khi cuộc khủng hoảng môi trường nhấn chìm London trong nước lũ.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jodie Comer","avatar":""},{"name":"Katherine Waterston","avatar":""},{"name":"Joel Fry","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Gina McKee","avatar":""},{"name":"Nina Sosanya","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Alexandria Riley","avatar":""},{"name":"Ramanique Ahluwalia","avatar":""},{"name":"Neil Bell","avatar":""},{"name":"Yves Rassou","avatar":""},{"name":"Phillipa Peak","avatar":""},{"name":"Jake Davies","avatar":""},{"name":"Roddy McDermott","avatar":""},{"name":"Charlotte Grisley","avatar":""},{"name":"Theo Barklem-Biggs","avatar":""},{"name":"Ans","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我們從末日開始","Конец, с которого мы начинаем","Кінець, з якого ми починаємо","Всесвітній потоп","La fin d''où nous partons","디 엔드 위 스타트 프롬","The End We Start From"]', 1784690324248);
