INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bat-dau-tu-su-ket-thuc', 'Bắt Đầu Từ Sự Kết Thúc', 'The End We Start From', 'bắt đầu từ sự kết thúc the end we start from jodie comer katherine waterston joel fry mark strong gina mckee nina sosanya benedict cumberbatch alexandria riley ramanique ahluwalia neil bell yves rassou phillipa peak jake davies roddy mcdermott charlotte grisley theo barklem-biggs ans 我們從末日開始 конец, с которого мы начинаем кінець, з якого ми починаємо всесвітній потоп la fin d''où nous partons 디 엔드 위 스타트 프롬 the end we start from', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-gi-duoc-nay', 'Ước Gì Được Nấy', 'Switch', 'https://phimimg.com/upload/vod/20240919-1/8051e42f168919a1a474c71a004d082f.jpg', 'https://phimimg.com/upload/vod/20240919-1/56505f3862a727a315180609a85441be.jpg', '<p>Là dòng phim hoán đổi, giả tưởng, xem lẫn yếu tố hài hước và tình cảm gia đình, bộ phim &quot;Ước Gì Được Nấy&quot; hứa hẹn sẽ mang một làn gió mới vào điện ảnh xứ sở Kim Chi. Tác phẩm còn đánh dấu sự hợp tác đáng mong đợi của bộ 3 diễn viên nổi tiếng là Kwon Sang Woo, Oh Jung Se và Rhee Min Jung. &nbsp;Bộ phim sẽ xoay quanh Park Kang (Kwon Sang Woo), nam tài tử thực lực điển trai nhưng cũng nhiều tai tiếng. Dẫu luôn miệng nói rằng ưa thích tận hưởng cuộc sống độc thân trên núi tiền, chàng ta thực chất lại rất sợ hãi cảm giác trống trải, cô đơn. Vào đêm giáng sinh, trong cơn say mèm, Park Kang đã ước giá như mình có cơ hội thay đổi vài lựa chọn nơi quá khứ.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"권상우","avatar":""},{"name":"오정세","avatar":""},{"name":"이민정","avatar":""},{"name":"박소이","avatar":""},{"name":"Kim Joon","avatar":""},{"name":"김미경","avatar":""},{"name":"Cha Hee","avatar":""},{"name":"이서환","avatar":""},{"name":"Cha Si-won","avatar":""},{"name":"성병숙","avatar":""},{"name":"Kim Seung-hoon","avatar":""},{"name":"Min Tae-yul","avatar":""},{"name":"유재명","avatar":""},{"name":"황승언","avatar":""},{"name":"송영재","avatar":""},{"name":"이지훈","avatar":""},{"name":"황병국","avatar":""},{"name":"Kim Ji-hwan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Christmas Gift","크리스마스 선물","Sewichi","大明星多重宇宙","圣诞节礼物","倒转人生","Різдяний подарунок","스위치"]', 1784690324248);
