INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-xa-la-2023', 'Người Xa Lạ', 'Not Others', 'https://phimimg.com/upload/vod/20250509-1/79c403ad586662c861a5f26dadb39596.jpg', 'https://phimimg.com/upload/vod/20250509-1/13e17295052a910c8d0fe0666314018b.jpg', '<p>Phim xoay quanh cặp mẹ con &quot;trái tính trái nết&quot; sống chung một nhà. Người con Jin Hee (Soo Young) là cô cảnh sát trẻ vừa vào nghề, tính cách bộc trực, thẳng thắn. Trong khi đó, mẹ của Jin Hee là Eun Mi (Jeon Hye Jin) - một chuyên viên vật lý trị liệu, sống đơn thân, vất vả nuôi con nên không hẹn hò ai suốt thời thanh xuân. Sống cùng nhau, cả hai có nhiều tình huống va chạm dở khóc dở cười, nhưng cũng không kém phần ấm áp.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeon Hye-jin","avatar":""},{"name":"Sooyoung Choi","avatar":""},{"name":"Ahn Jae-wook","avatar":""},{"name":"Park Sung-hoon","avatar":""},{"name":"Kim Hye-eun","avatar":""},{"name":"Lim Sung-kyun","avatar":""},{"name":"Seo Ye-hwa","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Kim Yeong-ok","avatar":""},{"name":"Lee Yong-i","avatar":""},{"name":"Yang Hee-kyung","avatar":""},{"name":"Ahn So-yo","avatar":""},{"name":"Kim Dong-soo","avatar":""},{"name":"Park Jung-eon","avatar":""},{"name":"Yoon Seok-hyun","avatar":""},{"name":"Yu Bee","avatar":""},{"name":"Son So-mang","avatar":""},{"name":"Kim Se-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["남남","Strangers"]', 1784690324248);
