INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-an-quy-du', 'Phong Ấn Quỷ Dữ', 'It Lives Inside', 'https://phimimg.com/upload/vod/20231017-1/cf195b156c744471c62fc479123b57cc.jpg', 'https://phimimg.com/upload/vod/20231017-1/de9259cfbc7b13206923b0e4a3861e70.jpg', '<p>Sam, một thiếu niên người Mỹ gốc Ấn, đang cố gắng hòa nhập môi trường học tập với nhiều khác biệt văn hóa. Khi một con quỷ khát máu trong thần thoại đeo bám người bạn thân thiết của cô, Sam buộc phải đối mặt để đánh bại nó.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Megan Suri","avatar":""},{"name":"Neeru Bajwa","avatar":""},{"name":"Mohana Krishnan","avatar":""},{"name":"Betty Gabriel","avatar":""},{"name":"Vik Sahay","avatar":""},{"name":"Gage Marsh","avatar":""},{"name":"Beatrice Kitsos","avatar":""},{"name":"Jamie Ives","avatar":""},{"name":"Siddhartha Minhas","avatar":""},{"name":"Saisha Ram Muni","avatar":""},{"name":"Sangeeta Wylie","avatar":""},{"name":"Jenaya Ross","avatar":""},{"name":"Jared Ager-Foster","avatar":""},{"name":"Nutan Thakur","avatar":""},{"name":"Paige Shaw","avatar":""},{"name":"Carlo Yu","avatar":""},{"name":"Josh Raymond","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
