INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-chuyen-tinh-noi-cong-xuong', 'Một Chuyện Tình Nơi Công Xưởng', 'Romantic Factory', 'https://phimimg.com/upload/vod/20250508-1/40ea3ca07deb0e1ae75c11c08a657378.jpg', 'https://phimimg.com/upload/vod/20250508-1/5589efd19ae1609cd3c6e9935d74bdf7.jpg', '<p>Sim Bok Ser, cựu cầu thủ sa sút vì nợ nần cờ bạc, phải làm bảo vệ tại một nhà máy. Trong lúc chán nản với cuộc sống đơn điệu, anh gặp Bok Hee – vợ đội trưởng bảo vệ. Sự đồng cảm và cô đơn dần khiến họ có thêm hy vọng và nảy sinh tình cảm. Nhưng rồi mọi chuyện trở nên phức tạp, khiến chuyện tình cả hai gặp nhiều trắc trở.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Sim Hee-seop","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Park Soo-young","avatar":""},{"name":"Park Jae-cheol","avatar":""},{"name":"Han Seung-do","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Romantic Factory","낭만적 공장"]', 1784690324248);
