INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-nguoi-yeu-cu-4-som-yeu-tre-cuoi', 'Kế Hoạch Người Yêu Cũ 4: Sớm Yêu Trễ Cưới', 'The Ex-Files 4: Marriage Plan', 'https://phimimg.com/upload/vod/20250508-1/dcbdc009f640322d940363123b467814.jpg', 'https://phimimg.com/upload/vod/20250508-1/75d3e87116cbe699973e91438a2b2338.jpg', '<p>Là chuỗi phim tình cảm thương hiệu, phần bốn trở lại khi Mạnh Vân đang loay hoay tìm đối tượng, trong khi Dư Phi lại tiến đến bước trải nghiệm trước cuộc sống hôn nhân. Dù đôi bạn nằm ở &quot;hai đầu quả đất&quot;, nhưng thử thách lại cùng đến với mỗi người theo cách khác nhau.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Canh","avatar":""},{"name":"Trịnh Khải","avatar":""},{"name":"Vu Văn Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["前任4","前任：分手清单","前任攻略4","The Ex-File 4: Early Marriage","The Ex-Files 4: Marriage Plan","前任4：英年早婚"]', 1784690324248);
