INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-tam-hoang-2-giang-ho-xa-la', 'Hội Tam Hoàng 2: Giang Hồ Xa Lạ', 'Triad 2: The Brotherhood Of Rebel', 'https://phimimg.com/upload/vod/20250508-1/9c6a5f1dc84ccdef3e7abdcd7f9bfde5.jpg', 'https://phimimg.com/upload/vod/20250508-1/f16712f352646a06d853ba7b1dd8c75e.jpg', '<p>A Tề, A Mao và Kim Chảy lớn lên cùng nhau, trở thành đệ tử của thủ lĩnh Hựu. Nhưng sau khi Hựu bất ngờ qua đời, cả ba đã đi theo những con đường riêng. Nhiều năm sau, vợ Hựu phát hiện cái chết của chồng có thể có liên quan đến một trong ba anh em. Ba con người từng đồng sinh cộng khổ sẽ đối diện với sự thật thế nào?</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Trần Gia Lạc","avatar":""},{"name":"Huỳnh Đức Bân","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Triad 2","扎职2","扎职2：江湖陌路","紮職2","The Brotherhood of Rebel"]', 1784690324248);
