INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-tu-thieu-hoa-luc', 'Tống Từ Thiều Hoa Lục', 'The Forensic Examiner Song Ci', 'https://phimimg.com/upload/vod/20250505-1/42c4097758f2eced542741bf573249ab.jpg', 'https://phimimg.com/upload/vod/20250505-1/efc5a73dde217eb206c0b1cf91ae7505.jpg', '<p>Chuyện kể về sáu thiếu niên do Tống Từ đứng đầu tình cờ gặp gỡ, chung tay phá giải nhiều nghi án thần bí kỳ lạ, vô tình bị cuốn vào tranh đấu giữa phe chủ chiến và phe chủ hòa của triều đình Nam Tống, dần dần các thiếu niên ngây ngô đã khôn lớn thành những con người thật sự biết nghĩ cho đại nghĩa nước nhà.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Trạch Nguyên","avatar":""},{"name":"Trần Tâm Dự","avatar":""},{"name":"Cư Lai Đề·Khố Đề Lai","avatar":""},{"name":"Âm Tẩm","avatar":""},{"name":"Lý Tư Bác","avatar":""},{"name":"Nhan Yên","avatar":""},{"name":"Lý Nại Văn","avatar":""},{"name":"Đổng Huyên","avatar":""},{"name":"Hải Nhất Thiên","avatar":""},{"name":"Hà Minh Hán","avatar":""},{"name":"Lưu Kim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["宋慈韶华录"]', 1784690324248);
