INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tong-tu-thieu-hoa-luc', 'Tống Từ Thiều Hoa Lục', 'The Forensic Examiner Song Ci', 'tống từ thiều hoa lục the forensic examiner song ci tôn trạch nguyên trần tâm dự cư lai đề·khố đề lai âm tẩm lý tư bác nhan yên lý nại văn đổng huyên hải nhất thiên hà minh hán lưu kim 宋慈韶华录', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-thay-tinh-yeu', 'Tìm Thấy Tình Yêu', 'Find Yourself', 'https://phimimg.com/upload/vod/20240207-1/db9f9723784b5aa533bfdbf5b96603b8.jpg', 'https://phimimg.com/upload/vod/20240207-1/f10ef69b3f5778adf6d192be1efdfb46.jpg', '<p>Bộ phim được chuyển thể từ bộ phim nổi tiếng Trạm Kế Tiếp Là Hạnh Phúc (Trung Quốc), cả hai bộ phim đều lấy cảm hứng từ bộ phim đình đám Chị Đẹp Mua Cơm Ngon Cho Tôi cực kỳ nổi tiếng và ăn khách của xứ sở Kim Chi. Chị Đẹp Mua Cơm Ngon Cho Tôi (Bản Thái) xoay quanh câu chuyện tình yêu của Yin, một cô nàng mê công việc và Chain chàng thực tập sinh kém 15 tuổi. Yin quyết định thử hẹn hò với Chain trong 3 tháng. Cùng lúc đó, Ray - một thương nhân tỷ phú cũng tiếp cận và tán tỉnh Yin. Đồng nghiệp và bố mẹ cô đều ủng hộ cho Ray. Yin đã tự hỏi lòng mình xem cô ấy có cảm xúc với Chain - một người chu đáo hay Ray - một sự lựa chọn hoàn hảo hơn, người mà ai ai cũng thấy rất hợp với cô.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Taksaorn Paksukcharern","avatar":""},{"name":"Chanon Santinatornkul","avatar":""},{"name":"Pirapat Watthanasetsiri","avatar":""},{"name":"Panisara Yang","avatar":""},{"name":"Saharat Sangkapreecha","avatar":""},{"name":"Suphakorn Sriphothong","avatar":""},{"name":"Neen Suwanamas","avatar":""},{"name":"Jaonine Packapol Sodjam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
