INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-minh-thich-tiec-tung-ban-truyen-hinh', 'Khổng Minh Thích Tiệc Tùng (Bản Truyền Hình)', 'Ya Boy Kongming!', 'https://phimimg.com/upload/vod/20250504-1/9917c239d8e8b0fb1fcbef0b8f079729.jpg', 'https://phimimg.com/upload/vod/20250504-1/453683a96884811008e331ae800336d4.jpg', '<p>Gia Cát Lượng – vị đại quân sư lẫy lừng thời Tam Quốc – đã dành cả đời chinh chiến, trải qua muôn vàn trận mạc để trở thành chiến lược gia tài ba như mọi người biết đến. Nhưng vào giây phút cuối đời, ông chỉ mong được tái sinh trong một thế giới hòa bình… và thế là, ông được đưa thẳng đến trung tâm tiệc tùng náo nhiệt của thời hiện đại – Tokyo! Liệu ngay cả một thiên tài chiến lược như Gia Cát Lượng cũng có thể thích nghi với những giai điệu sôi động và đám đông tiệc tùng còn ‘cháy’ hơn cả chiến trường?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Osamu Mukai","avatar":""},{"name":"Moka Kamishiraishi","avatar":""},{"name":"Mirai Moriyama","avatar":""},{"name":"Dean Fujioka","avatar":""},{"name":"Koharu Sugawara","avatar":""},{"name":"Ryubi Miyase","avatar":""},{"name":"Rikako Yagi","avatar":""},{"name":"Mandy Sekiguchi","avatar":""},{"name":"Avu-chan","avatar":""},{"name":"Win Morisaki","avatar":""},{"name":"Yuki Takao","avatar":""},{"name":"Chiaki Matsunobu","avatar":""},{"name":"ELLY","avatar":""},{"name":"Utano Aoi","avatar":""},{"name":"Futaba Mori","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["派对浪客诸葛孔明","派对咖孔明","YA BOY KONGMING!","Paripi Komei","パリピ孔明"]', 1784690324248);
