INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoc-an-ca-nga-ve-khong-2023', 'Được Ăn Cả Ngã Về Không', 'No More Bets', 'https://phimimg.com/upload/vod/20240920-1/d4d48289811f743667c02cc59f79bcb3.jpg', 'https://phimimg.com/upload/vod/20240920-1/92bfb6697dad3c4ddb5f12cc9b7187e4.jpg', '<p>Bị thu hút bởi công việc béo bở ở nước ngoài, một lập trình viên và một người mẫu rơi vào một đường dây lừa đảo. Tại đây, lối thoát duy nhất của họ là đi lừa lại người khác.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nghệ Hưng","avatar":""},{"name":"Kim Thần","avatar":""},{"name":"Vịnh Mai","avatar":""},{"name":"Vương Truyền Quân","avatar":""},{"name":"Vương Đại Lục","avatar":""},{"name":"Chu Dã","avatar":""},{"name":"Tôn Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["捕鱼行动","捕鱼之放手一搏","放手一搏","همه یا هیچ","Được Ăn Cả Ngã Về Không Trung Quốc","no more bets","No More Bets","孤注一掷"]', 1784690324248);
