INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-kim-co-dien', 'Hắc Kim Cổ Điện', 'Misty Creed', 'https://phimimg.com/upload/vod/20250428-1/6a4a7c5fdcd13ce0e0045717f0ef20d2.jpg', 'https://phimimg.com/upload/vod/20250428-1/9d8c591043454f8122af4623a4dd3480.jpg', '<p>Cuộc sống ẩn dật ở thôn Vũ của Ngô Tà, Vương Bàn Tử, Trương Khởi Linh - Thiết Tam Giác phiêu lưu, đã bị một lão già tên Khánh Xuân phá vỡ. Ông ta báo tin rằng gần đây, những điều kỳ lạ thường xuyên xảy ra ở dãy núi Ô Mộc Lặc: trên núi đột nhiên xuất hiện sương mù dày đặc; trong sương lại lấp ló bóng đen lay động; người dân mất tích; Vụ Tiên hiển linh;... Tất cả đều mang đến một cảm giác kinh hoàng khó tả. Khánh Xuân nhờ ba người đi đến điều tra, mở ra cuộc phiêu lưu mới của Thiết Tam Giác. Đi sâu vào vùng núi, mọi người dường như bị sương mù dày đặc nuốt chửng và bị một thế lực vô hình cản trở. Sau quãng đường leo núi vất vả, dưới gốc cây hoa đào to lớn và kỳ lạ trên đỉnh núi xuất hiện bầu không khí lễ hội, nhưng lại không có bóng dáng của người dân làng nào. Lúc này, trong sương mù xuất hiện rất nhiều bóng đen, dẫn đoàn người đến địa cung thần bí dưới lòng núi. Nơi đây dường như là ngọn nguồn của đám sương mù.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Jing Yanjun","avatar":""},{"name":"Chen Yesheng","avatar":""},{"name":"Wang Bowen","avatar":""},{"name":"Yuan Hangming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["盗墓笔记：黑金古殿","Misty Creed","The Black and Gold Palace","黑金古殿"]', 1784690324248);
