INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-cong-nhanh', 'Phản Công Nhanh', 'Quick Counterattack', 'https://phimimg.com/upload/vod/20240305-1/7e0baf062b9c5adb2a0b9a563f352f33.jpg', 'https://phimimg.com/upload/vod/20240305-1/fa1ec87edacd6aeadb1a048bfcc0f2ec.jpg', '<p>Tại một thị trấn nhỏ ven biển, các nhóm tội phạm lừa đảo dựa vào bạo lực mạng để phát triển chuỗi ngành tội phạm mạng bao gồm các khoản cho vay trực tuyến bất hợp pháp, nội dung khiêu dâm, cờ bạc và mại dâm. Do tính ảo của Internet có thể che giấu được danh tính, cảnh sát đã tìm kiếm cơ hội để tiêu diệt các nhóm tội phạm đồng thời đột phá từng nhóm một, cùng lúc đó, Mã Húc Đông, người đã làm công tác an ninh ở nước ngoài nhiều năm, quay trở lại Trung Quốc truy lùng những kẻ đứng sau hoạt động &quot;cho vay trực tuyến&quot;, không rõ tung tích con gái, đối mặt với một nhóm tội phạm hung ác, cảnh sát và Mã Húc Đông bắt đầu trò chơi sinh tử với bọn tội phạm, và cuối cùng đã phát hiện và phá hủy chuỗi tội phạm mạng.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Ma Yujie","avatar":""},{"name":"Tian Lu","avatar":""},{"name":"An Zehao","avatar":""},{"name":"Wu Chunyi","avatar":""},{"name":"Rhea","avatar":""},{"name":"孙亦沐","avatar":""},{"name":"吕晨曦","avatar":""},{"name":"王巍","avatar":""},{"name":"石天硕","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
