INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-long-quyet-sinh-tu-mon', 'Tầm Long Quyết: Sinh Tử Môn', 'The Lost Legend', 'https://phimimg.com/upload/vod/20250428-1/32f871f364bf4ff7dd7aae5211a5e3c8.jpg', 'https://phimimg.com/upload/vod/20250428-1/98b5c96d1b2b0eb0e7273a82d4c80f9b.jpg', '<p>Ở một quốc gia Đông Nam Á, người Trung Quốc làm chuyên gia phong thủy là Trần Vô Kỵ đã mất mạng trong một lần đi tìm thuốc cứu người do rơi vào bẫy của một nhóm đạo tặc mộ. Ba đệ tử của Trần Vô Kỵ gồm Tiểu Mãn, Đại Thử, Bạch Lộ sau khi biết được được sự thật ẩn giấu phía sau đã dùng mưu để phá vỡ âm mưu của nhóm đạo tặc mộ, cuối cùng phối hợp với cảnh sát để đưa nhóm đạo tặc mộ ra trước công lý.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Da","avatar":""},{"name":"Liu Tianzuo","avatar":""},{"name":"Cherry Ngan","avatar":""},{"name":"Zhou Dayong","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Scotty Cox","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["The Lost Legend","Dragon Quest: Gate of Life and Death","寻龙诀：生死门"]', 1784690324248);
