INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-phong-than-nhi-lang-than', 'Tân Phong Thần: Nhị Lang Thần', 'Er-Lang God Of The New Legend Of Deification', 'https://phimimg.com/upload/vod/20241019-1/a07845505eb78a4bc139deafb0aa3db6.jpg', 'https://phimimg.com/upload/vod/20241019-1/ce848106aec2af1fc24944aab53b143d.jpg', '<p>Nó kể về câu chuyện của Dương Tiễn, để cứu mẹ mình người đang chịu bao đau khổ trên núi Đào, phải phục tùng mệnh lệnh của Ngọc Đinh, trải qua nhiều thử thách, chinh phục quái vật và có được vũ khí thần thánh. Cuối cùng, kẻ độc ác đã bị khuất phục và thế giới trở nên hòa bình.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"張睿","avatar":""},{"name":"Shi Xuejing","avatar":""},{"name":"Liang Chao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Xin Feng Shen Zhi Er Lang Shen","新封神之二郎神"]', 1784690324248);
