INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-guom-diet-quy-phan-4-lang-tho-ren', 'Thanh Gươm Diệt Quỷ (Phần 4) (Làng Thợ Rèn)', 'Demon Slayer (Season 4) (Swordsmith Village Arc)', 'https://phimimg.com/upload/vod/20240308-1/a0f9644299d8322f495e5fda38098f39.jpg', 'https://phimimg.com/upload/vod/20250427-1/c1ed81199e77a349d236c842953c9c6a.jpg', '<p>Sau trận chiến với Thượng Huyền Lục, thanh gươm của Tanjiro bị hư hỏng nặng và cần được sửa chữa để tiếp tục lên đường làm nhiệm vụ. Cậu được đưa đến Làng Thợ Rèn, nơi phụ trách rèn vũ khí cho các kiếm sĩ của Đội Diệt Quỷ. Trong thời gian chờ sửa lại thanh gươm, Tanjiro nhập hội cùng Hà Trụ Muichiro và Luyến Trụ Mitsuri để chuẩn bị cho trận chiến mới với các thành viên mạnh nhất trong hàng Thượng Huyền của Thập Nhị Quỷ Nguyệt.</p>', 'Full', 11, 'hoathinh', 'completed', 6, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Hanae Natsuki","avatar":""},{"name":"Kito Akari","avatar":""},{"name":"Shimono Hiro","avatar":""},{"name":"Matsuoka Yoshitsugu","avatar":""},{"name":"Sakurai Takahiro","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Kaji Yuki","avatar":""},{"name":"Kakuma Ai","avatar":""},{"name":"Okamoto Nobuhiko","avatar":""},{"name":"Morikawa Toshiyuki","avatar":""},{"name":"Yuki Aoi","avatar":""},{"name":"Izawa Shiori","avatar":""},{"name":"Namikawa Daisuke","avatar":""},{"name":"Yamazaki Takumi","avatar":""},{"name":"Midorikawa Hikaru","avatar":""},{"name":"Koyasu Takehito","avatar":""},{"name":"Hino S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324248);
