INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuyen-khong-thanh-canh-vuong-phi-phan-2', 'Xuyên Không Thành Cảnh Vương Phi (Phần 2)', 'Actors Princess Cultivate Undergo (Season 2)', 'https://phimimg.com/upload/vod/20250427-1/2b521173696fabb4169e57aa1a6076e9.jpg', 'https://phimimg.com/upload/vod/20250427-1/db6f06d95945970ca46a430583211c9d.jpg', '<p>Sau khi trải qua nhiều biến cố, giữa cô gái xuyên không Triệu Thiều Hoan và Cảnh Vương gia Nam Cung Cảnh đã nảy sinh tình cảm thực sự. Đồng vợ đồng chồng, họ cùng nhau đối phó với những âm mưu nham hiểm của hai mẹ con Hoàng hậu và Thái tử và tìm hiểu sự thật phía sau cái chết năm xưa của mẹ Nam Cung Cảnh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Chỉ Y","avatar":""},{"name":"Tào Tuấn Tường","avatar":""},{"name":"Lâu Hinh Nguyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Xi Jing Wang Fei Yang Cheng Ji","戲精王妃養成記","Actors Princess Cultivate Undergo","戏精王妃养成记"]', 1784690324248);
