INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuyen-khong-thanh-canh-vuong-phi-phan-1', 'Xuyên Không Thành Cảnh Vương Phi (Phần 1)', 'Actors Princess Cultivate Undergo (Season 1)', 'https://phimimg.com/upload/vod/20250427-1/baeeac764ef0dd967222c6f68583eb22.jpg', 'https://phimimg.com/upload/vod/20250427-1/94aa8aeb568f31dd76b2902a4e0275e3.jpg', '<p>Một nữ diễn viên quần chúng thời hiện đại vô tình xuyên không về quá khứ, nhập vào thân xác của người cùng tên với mình là Triệu Thiều Hoan, tân nương của Cảnh Vương gia Nam Cung Cảnh. Vốn là người thông minh và mạnh mẽ, cô nhanh chóng thích nghi với thời cổ đại và luôn tìm được cách đối phó trước mọi mưu hèn kế bẩn của những kẻ xấu xa xung quanh. Không những thế, cô còn quyết tâm vực dậy một gánh hát sắp phá sản để thỏa mãn đam mê nghệ thuật của bản thân mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Chỉ Y","avatar":""},{"name":"Tào Tuấn Tường","avatar":""},{"name":"Cát Hiểu Hy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Xi Jing Wang Fei Yang Cheng Ji","戲精王妃養成記","Actors Princess Cultivate Undergo","戏精王妃养成记"]', 1784690324248);
