INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tham-lang', 'Người Thầm Lặng', 'The Silent Man', 'https://phimimg.com/upload/vod/20250427-1/a6e0a76e0a26d2db02c829d5fc6a39a3.jpg', 'https://phimimg.com/upload/vod/20250427-1/64a206cf37e06674fe7b5d5958ba3ba3.jpg', '<p>Bạo lực, ma túy Cảnh sát môi trường Huy Cường quyết tâm chuyển sang đội phòng chống ma túy bất chấp sự phản đối của người yêu. Thuở ban đầu còn thiếu kinh nghiệm, nhưng dần dà anh đã trở thành một cảnh sát chìm kiên cường, đối mặt với những băng đảng nguy hiểm nhất. Bên cạnh Huy Cường, phim còn khắc họa sâu sắc sự hy sinh thầm lặng của những đồng đội khác, qua đó tôn vinh hình ảnh quả cảm của người chiến sĩ công an và giá trị của công lý.</p>', 'Hoàn Tất (87/87)', 87, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Huỳnh Trường Thịnh","avatar":""},{"name":"Lê Hạ Anh","avatar":""},{"name":"Nguyễn Dương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324248);
