INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-ac', 'Kẻ Thủ Ác', 'Criminal', 'https://phimimg.com/upload/vod/20250427-1/5a797ddede623fed9fea7c93657bbbeb.jpg', 'https://phimimg.com/upload/vod/20250427-1/0fb79736085d9742e062eeaa9740dff6.jpg', '<p>Lấy tư liệu từ các vụ án mạng có thật trong và ngoài nước, Kẻ Thủ Ác vạch trần những chiếc bẫy tâm lý nhằm thao túng nạn nhân của kẻ gây án. Thông qua mỗi câu chuyện, người xem sẽ được chứng kiến nhiều mánh khóe tinh vi khác nhau của những đối tượng tội phạm khác nhau. Đặc biệt, phim còn hé lộ những góc khuất, động cơ đưa đẩy con người vào vòng lao lý.</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hồ Bích Trâm","avatar":""},{"name":"Ngọc Tưởng","avatar":""},{"name":"Quốc Huy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324248);
