INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-phung-lieu-nguyen', 'Hỏa Phụng Liêu Nguyên', 'The Ravages Of Time', 'https://phimimg.com/upload/vod/20250121-1/bbd870cf70d0b7619ce998e586deb8f8.jpg', 'https://phimimg.com/upload/vod/20250121-1/3922162ac89038c38be90d5c4828cdcb.jpg', '<p>Cuối thời Đông Hán, Đổng Trác làm loạn kinh đô, lấy hoàng đế ra lệnh cho các hoàng tử, bắt thân nhân của các hoàng tử làm con tin. Sau đó, theo kế hoạch của Lữ Bố, ông ta lên kế hoạch sử dụng Lạc Dương làm mồi nhử để dụ quân Đồng minh vào thành và đốt cháy Lạc Dương. Để cứu con tin, Lực lượng Đồng minh đã nghĩ ra những mánh khóe độc đáo của riêng họ</p>', 'Hoàn Tất (32/32)', 32, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shen Lei","avatar":""},{"name":"Guangyi Du","avatar":""},{"name":"Xiaotong Wang","avatar":""},{"name":"Jing Lin","avatar":""},{"name":"Jingtian Zheng","avatar":""},{"name":"Ke Jiang","avatar":""},{"name":"Chen Huang","avatar":""},{"name":"Ran Jiang","avatar":""},{"name":"Hongxiu Wang","avatar":""},{"name":"Chong Fu","avatar":""},{"name":"Cheng Yuzhu","avatar":""},{"name":"Jiaxin Yao","avatar":""},{"name":"Xiaotong Wang","avatar":""},{"name":"Jiachen Ren","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Huo Feng Liao Yuan","HFLY","Huǒ Fèng Liáo Yuán","かほうりょうげん","火鳳燎原","火鳳","Hỏa Phụng Liêu Nguyên","火凤燎原"]', 1784690324248);
