INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thay-y-duc-phan-3', 'Người Thầy Y Đức (Phần 3)', 'Dr. Romantic (Season 3)', 'https://phimimg.com/upload/vod/20231004-1/6dc1349a0cfeb2c40108f55a0d5b6cbe.jpg', 'https://phimimg.com/upload/vod/20231004-1/de53ea7bc80015760ddeef97150cd8b1.jpg', '<p>Người Thầy Y Đức 3 (Dr. Romantic 3) là một bộ phim truyền hình Hàn Quốc thuộc thể loại tâm lý, tình cảm chủ đề y khoa của đạo diễn Yoo In Shik. Trong phim sẽ có sự tham gia diễn xuất của dàn diễn viên gồm: Han Suk Kyu, Ahn Hyo Seop, Lee Sung Kyung, Kim Min Jae, So Ju Yeon, Jin Kyung, Im Won Hee, Byun Woo Min, Jung Ji Ahn,... Nội dung phim Người Thầy Y Đức 3 vẫn xoay quanh những câu chuyện tại bệnh viện Doldam. Tại đây, 3 con người với những câu chuyện của riêng mình là Boo Yong-joo (Han Suk Kyu thủ vai) tận tâm, Seo Woo-jin (Ahn Hyo Seop thủ vai) có cuộc sống cá nhân đầy biến cố bị các đồng nghiệp tẩy chay và bác sĩ trẻ Cha Eun-jae (Lee Sung Kyung thủ vai) bị đình chỉ công việc do sai sót trong công việc. Từ đây, họ đã cùng nhau cộng tác ăn ý trong công việc để cống hiến cho y học, cứu sống bao người. Những bài học về tình yêu, tình đồng nghiệp, tình người được khắc họa đan xen với nhiều chi tiết tinh tế tạo nên những thước phim cuốn hút người xem đến tập cuối cùng.</p>', 'Hoàn tất (16/16)', 16, 'series', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Han Suk-kyu","avatar":""},{"name":"Ahn Hyo-Seop","avatar":""},{"name":"Lee Sung-kyoung","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"So Joo-yeon","avatar":""},{"name":"Jin Kyung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324248);
