INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-khan-cap-911-ngoi-sao-don-doc-phan-4', 'Cuộc Gọi Khẩn Cấp 9-1-1: Ngôi sao đơn độc (Phần 4)', '9-1-1: Lone Star (Season 4)', 'https://phimimg.com/upload/vod/20250426-1/b616ce8e676c51940cb0de9afb541360.jpg', 'https://phimimg.com/upload/vod/20250426-1/394734c0de5f2a95b1e928a123194d88.jpg', '<p>Một lính cứu hỏa ở New York chuyển đến Austin, Texas cùng con trai, nơi anh làm việc để cứu sống mọi người trong khi cố gắng giải quyết các vấn đề cá nhân của mình.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rob Lowe","avatar":""},{"name":"Gina Torres","avatar":""},{"name":"Ronen Rubinstein","avatar":""},{"name":"Sierra McClain","avatar":""},{"name":"Jim Parrack","avatar":""},{"name":"Natacha Karam","avatar":""},{"name":"Brian Michael Smith","avatar":""},{"name":"Rafael Silva","avatar":""},{"name":"Julian Works","avatar":""},{"name":"Brianna Baker","avatar":""},{"name":"Kelsey Yates","avatar":""},{"name":"Skyler Yates","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324248);
