INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-goi-khan-cap-911-ngoi-sao-don-doc-phan-4', 'Cuộc Gọi Khẩn Cấp 9-1-1: Ngôi sao đơn độc (Phần 4)', '9-1-1: Lone Star (Season 4)', 'cuộc gọi khẩn cấp 9-1-1: ngôi sao đơn độc (phần 4) 9-1-1: lone star (season 4) rob lowe gina torres ronen rubinstein sierra mcclain jim parrack natacha karam brian michael smith rafael silva julian works brianna baker kelsey yates skyler yates ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-phong-do', 'Trường Phong Độ', 'Destined', 'https://phimimg.com/upload/vod/20240304-1/9e79f8ebe5eb3a2bf2d5653d277522a7.jpg', 'https://phimimg.com/upload/vod/20240304-1/133afbc3184703d613b9cea02d0450ee.jpg', '<p>Câu chuyện tình cưới trước yêu sau của cặp đôi Liễu Ngọc Như và Cố Cửu Tư. Liễu Ngọc Như là con gái của một thương nhân buôn vải ở Dương Châu. Mẹ của cô qua đời do bệnh nặng. Ngọc Như sống cùng cha và mẹ kế. Cô chịu nhiều uất ức khi cha không xem trọng, mẹ kế tìm cách gây khó dễ. Vượt qua sự chèn ép đó, Ngọc Như luôn cố gắng học hỏi lễ nghi, phép tắc để trở thành một khuê nữ điển hình. Cũng như nhiều cô gái khác, Ngọc Như chỉ mong được gả cho một đấng phu quân tốt. Tuy nhiên, số phận đưa đẩy, cô được chỉ hôn cho Cố Cửu Tư – một công tử ăn chơi trác táng thành Dương Châu. Cố Cửu Tư là thiếu gia nhà họ Cố – một họ giàu có nhất thành. Vì gia đình có điều kiện nên Cửu Tư khinh thường Ngọc Như ra mặt. Anh cho rằng cô vì ham gia sản, muốn trèo cao nên mới chấp nhận gả cho mình. Sau khi vào làm dâu nhà họ Cố, Ngọc Như theo mẹ chồng học cách làm ăn, buôn bán. Vốn có tư chất thông minh, cộng thêm tính tình chăm chỉ, chịu khó, cô nhanh chóng tiếp quản tốt công việc. Ngọc Như dần chứng minh được giá trị của mình. Cô giúp việc kinh doanh của gia đình ngày càng phát đạt. Về phía Cửu Tư, chàng công tử nhà họ Cố ngày càng có cái nhìn khác về hiền thê mình. Chứng kiến sự độc lập, giỏi giang của Ngọc Như, anh dần yêu mến cô. Cửu Tư cũng từ từ thay tâm đổi tính, chí thú làm ăn. Cặp đôi đồng hành cùng nhau vượt qua nhiều biến cố, thử thách, cùng giữ gìn và phát huy gia nghiệp hiển hách.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 13, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Kính Đình","avatar":""},{"name":"Tống Dật","avatar":""},{"name":"Lưu Học Nghĩa","avatar":""},{"name":"Trương Hạo Duy","avatar":""},{"name":"Trương Duệ","avatar":""},{"name":"Triệu Tử Kỳ","avatar":""},{"name":"Sa Dật","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
