INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-sup-xi-trum', 'Món Súp Xì Trum', 'The Smurfs 3D: Chef Soup', 'https://phimimg.com/upload/vod/20250424-1/7ea2600904b02a569ffaf3e9df935b22.jpg', 'https://phimimg.com/upload/vod/20250424-1/f179bc1002ac9f4dcbbb1a8e8f700e9e.jpg', '<p>Bộ phim là những cuộc phiêu lưu của các cô cậu Xì Trum màu xanh nhỏ bé, sống trong những ngôi nhà hình nấm dễ thương ở một ngôi làng yên bình. Chỉ cần nghe tên gọi là có thể biết được tố chất, bản tính của họ, nào là Tí Vua, Tí Quạu, Tí Cô Nương, Tí Điệu, Tí Đô, Tí Quậy... Họ luôn đoàn kết, bảo bọc nhau trước cái xấu và những âm mưu, thủ đoạn của lão Gà Mên độc ác.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 7, 2023, 'Lồng Tiếng', 'FHD', 'Pháp', 0, '[{"name":"Bá Nghị","avatar":""},{"name":"Ngọc Châu","avatar":""},{"name":"Hoàng Sơn","avatar":""},{"name":"Quang Tuyên","avatar":""},{"name":"Huyền Chi","avatar":""},{"name":"Trần Vũ","avatar":""},{"name":"Kim Ngọc","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324248);
