INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mon-sup-xi-trum', 'Món Súp Xì Trum', 'The Smurfs 3D: Chef Soup', 'món súp xì trum the smurfs 3d: chef soup bá nghị ngọc châu hoàng sơn quang tuyên huyền chi trần vũ kim ngọc ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-le-dai-chien', 'Hôn Lễ Đại Chiến', 'The Matchmakers', 'https://phimimg.com/upload/vod/20241228-1/ea20ba3f3d280246deed1718c057b956.jpg', 'https://phimimg.com/upload/vod/20241228-1/dc5cb0c43edc40f9b488e08dea305d38.jpg', '<p>Shim Jung Woo là một học giả trẻ tài hoa của triều đình Joseon. Jung Woo đã đứng đầu bảng trong kỳ thi quan trọng nhất, trở thành ứng cử viên xuất sắc cho vị trí phò mã khi được công chúa nhắm trúng. Thế nhưng, vào ngày diễn ra hôn lễ, công chúa đột ngột qua đời, khiến Jung Woo trở thành người góa vợ ở tuổi 17. Ở thời Joseon, những người góa bụa sẽ không được làm bất cứ việc gì trọng đại và đặc biệt không được tái hôn. Suốt 8 năm ròng, ngày nào Jung Woo cũng dâng sớ xin được hủy bỏ hôn ước, nhưng đều không được chấp nhận. Rồi một ngày, quốc vương cũng đồng ý hủy bỏ danh hiệu phò mã và trả tự do cho anh, với một nhiệm vụ: làm mối thành công cho một cặp góa bụa. một cảnh trong phim Ảnh: Instagram @kbsdrama Công việc của Jung Woo không hề suôn sẻ như anh nghĩ. Rồi anh gặp Jung Soon Deok, một góa phụ che giấu thân phận để hành nghề mai mối hàng đầu tại thành Hanyang, kiêm bán trang sức. Soon Deok là một góa phụ mạnh mẽ, con dâu của gia tộc tể tướng họ Jo danh tiếng. Ít ai biết cô còn sống với một danh tính bí mật là Yeo Joo, bà mối giỏi nhất thủ đô Hanyang. Sau khi Jung Woo đồng hành cùng người “đồng nghiệp” bất đắc dĩ Soon Deok, quan niệm về tình yêu và hôn nhân của anh cũng dần thay đổi. Cả hai cùng nhau mai mối cho đàn ông và phụ nữ quá tuổi, và cũng trở thành “ông bà mối” của chính mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Rowoon","avatar":""},{"name":"Cho Yi-hyun","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Park Ji-young","avatar":""},{"name":"Choi Kyung-hoon","avatar":""},{"name":"Oh Ye-ju","avatar":""},{"name":"Jung Bo-min","avatar":""},{"name":"Heo Nam-jun","avatar":""},{"name":"Son Sang-yeon","avatar":""},{"name":"Park Ji-won","avatar":""},{"name":"Jeong Sin-hye","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Choi Hee-jin","avatar":""},{"name":"Park Hwan-Hee","avatar":""},{"name":"Seo Jin-won","avatar":""},{"name":"Jung Seung-kil","avatar":""},{"name":"Lee Soon-won","avatar":""},{"name":"Kim Da-huin","avatar":""},{"name":"Kim Hyeon-","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["朝鮮婚姻大作戰","혼례대첩"]', 1784690324248);
