INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hon-le-dai-chien', 'Hôn Lễ Đại Chiến', 'The Matchmakers', 'hôn lễ đại chiến the matchmakers rowoon cho yi-hyun jo han-chul park ji-young choi kyung-hoon oh ye-ju jung bo-min heo nam-jun son sang-yeon park ji-won jeong sin-hye lee hae-yeong choi hee-jin park hwan-hee seo jin-won jung seung-kil lee soon-won kim da-huin kim hyeon- 朝鮮婚姻大作戰 혼례대첩', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-khanh-hanh', 'Dữ Khanh Hành', 'Cordial Companions', 'https://phimimg.com/upload/vod/20240324-1/fdc41d0c9ffe2e348ae2e5976daa7df7.jpg', 'https://phimimg.com/upload/vod/20240324-1/46dd8d27d45c755b873b8ac2d24e3b38.jpg', '<p>Vì muốn vực dậy tiêu cục đang làm ăn sa sút, Lâm Vãn Khanh đành phải đi làm sát thủ bán thời gian để kiếm tiền. Nào ngờ số trời run rủi, ở phi vụ nào nàng cũng chạm trán Tô Mặc Ý, người đứng đầu Đại Lý Tự. Ban đầu còn đề phòng, nghi ngờ nhau, nhưng dần dà họ đã trở thành cộng sự, cùng nhau phá án và diệt trừ kẻ gian để bảo vệ kinh thành.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Diêu Tiểu Tiểu","avatar":""},{"name":"Trình Tương","avatar":""},{"name":"Bành Thi Địch","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
