INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('du-khanh-hanh', 'Dữ Khanh Hành', 'Cordial Companions', 'dữ khanh hành cordial companions diêu tiểu tiểu trình tương bành thi địch ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-ai-vi-doanh', 'Dĩ Ái Vi Doanh', 'Only For Love', 'https://phimimg.com/upload/vod/20240113-1/3a20a7bda07cb8d5331ea68f7fcc2397.jpg', 'https://phimimg.com/upload/vod/20240113-1/93a321d708133aa16fb47d5f18352929.jpg', '<p>Dĩ Ái Vi Doanh kể về câu chuyện tình yêu giữa Thời Yến và Trịnh Thư Ý. Trịnh Thư Ý là một nữ phóng viên xinh đẹp, thông minh và thành công với nhiều bài báo lớn cho Tuần san Kinh tế Tài Chính. Vào ngày sinh nhật của bạn trai Nhạc Tinh Châu, cô bị cuốn vào cuộc phỏng vấn Thời Yến, tổng giám đốc ngân hàng Minh Dự Vân Sang, một ngôi sao mới nổi trong ngành tài chính. Điều đó khiến cô buộc phải bỏ lỡ buổi hẹn hò với bạn trai. Tuy nhiên, trong cùng ngày đó, Thư Ý phát hiện rằng Tinh Châu đã hẹn hò với một cô gái giàu có khác và cô gái đó lại là cháu gái của Thời Yến. Để trút giận, Thư Ý quyết định tán tỉnh cậu của &quot;trà xanh&quot; này, với mục tiêu làm &quot;mợ&quot; của bạn trai cũ để trêu chọc và trả thù. Tuy nhiên, người cậu mà cô tán tỉnh không có liên quan gì đến cháu gái &quot;trà xanh&quot; kia. Việc tán tỉnh Thời Yến đã trở nên vô cùng khó khăn, tuy nhiên, điều đó không khiến Thư Ý từ bỏ. Sau nhiều lần tiếp xúc, Thời Yến nhận thấy năng lực, sự thông minh và sự kiên nhẫn của Trịnh Thư Ý. Qua các lần hợp tác và chia sẻ, cô đã giúp anh nhận ra tầm quan trọng của truyền thông. Dần dần, cả hai bắt đầu nảy sinh và Trịnh Thư Ý cũng nhận ra rằng suốt thời gian qua cô đã cưa cẩm sai người.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Lộc","avatar":""},{"name":"Vương Hạc Đệ","avatar":""},{"name":"Ngụy Triết minh","avatar":""},{"name":"Thẩm Vũ Khiết","avatar":""},{"name":"Lưu Đông Thấm","avatar":""},{"name":"Khương Bội Dao","avatar":""},{"name":"Vương Vy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
