INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-la-mo-dung-nang-tua-hoa', 'Chàng Là Mộ Dung, Nàng Tựa Hoa', 'A Mystery Case Leads Me To You', 'https://phimimg.com/upload/vod/20250424-1/07f26bd6c0c4e68820e2c6e0381a22b9.jpg', 'https://phimimg.com/upload/vod/20250424-1/0322ca32d7e9f04efecb00fca1c014f6.jpg', '<p>Nhà văn Hoa Lý Lý trong lúc bất cẩn rơi từ trên cao xuống ngay đúng lúc một tiểu hành tinh lạ bay ngang qua. Thế là cô bị cuốn vào tác phẩm mà chính mình đang viết dở dang và trở thành Hoa Đại Lực, một nữ thổ phỉ sẽ bị nam chính Mộ Dung Quân Trạch giết chết. Để trở về thế giới thật, Lý Lý phải dùng thân phận của Đại Lực để giúp cốt truyện hư cấu đi đến hồi kết. Trớ trêu thay, trong quá trình thực hiện nhiệm vụ, cô lại lỡ phải lòng nam chính trong thế giới sách.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạo Trinh","avatar":""},{"name":"Trương Băng Thiến","avatar":""},{"name":"Tiên Gia Thần","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324248);
