INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nghe-thuat-san-quy-va-nau-mi-phan-2', 'Nghệ Thuật Săn Qủy Và Nấu Mì (Phần 2)', 'The Uncanny Counter (Season 2)', 'nghệ thuật săn qủy và nấu mì (phần 2) the uncanny counter (season 2) cho byeong kyu yu jun sang kim se jeong yeom hye ran ahn seok hwan moon sook choi yoon young lee hong nae 惊人的传闻 惊奇的传闻 驱魔面馆 悪霊狩猟団：カウンターズ 悪霊狩猟団 カウンターズ あくりょうしゅりょうだん：カウンターズ 경이로운 소문 驚異로운 所聞 경이로운 소문2: 카운터 펀치 el contador asombroso чудесный слух удивительный слух 驅魔麵館 the uncanny counter: counter punch amazing rumor amazing so mun', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-05', 'Người Đàn Ông 0.5', '0.5 Man (0.5 no Otoko)', 'https://phimimg.com/upload/vod/20250422-1/098558cd27f914bf535402e2af456fa6.jpg', 'https://phimimg.com/upload/vod/20250422-1/7603aca75ddbb7a521ec061c481066c6.jpg', '<p>Masaharu &quot;Masaji&quot; Tachibana từng là một lập trình viên xuất sắc, nhưng sau khi kiệt sức vì công việc, anh đột ngột nghỉ làm và biến mất khỏi môi trường công sở. Giờ đây, anh sống cùng cha mẹ, dành cả ngày để ngủ và chơi game. Thứ duy nhất khiến anh rời khỏi phòng là những lần đi đến cửa hàng tiện lợi gần nhà để mua nước tăng lực và đồ ăn vặt. Mọi chuyện bắt đầu thay đổi khi Masaji phát hiện cha mẹ mình đã quyết định xây một ngôi nhà &quot;2.5 thế hệ&quot; – nơi gia đình của chị gái anh cũng sẽ chuyển đến sống cùng. Bị buộc phải thích nghi với môi trường mới, Masaji dần dần bắt đầu bước ra khỏi căn phòng của mình – và cả khỏi thế giới nội tâm đầy bế tắc của anh.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryuhei Matsuda","avatar":""},{"name":"Asami Usuda","avatar":""},{"name":"Tamaki Shiratori","avatar":""},{"name":"Kai Inowaki","avatar":""},{"name":"Yuzu Aoki","avatar":""},{"name":"Atsushi Shinohara","avatar":""},{"name":"Katsumi Kiba","avatar":""},{"name":"Nanase Nishino","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Kato Yahiro","avatar":""},{"name":"Yugo Mikawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["0.5的男人","0.5 no otoko","Полчеловека","The 0.5","0.5 Man","0.5の男"]', 1784690324248);
