INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-thuong-khung-2-ngung-chien', 'Đấu Phá Thương Khung 2: Ngừng Chiến', 'Fights Break Sphere 2', 'https://phimimg.com/upload/vod/20250421-1/0be58bc52e9f35b0c2d2223af68bf2e4.jpg', 'https://phimimg.com/upload/vod/20250421-1/d814a4b3ca79794acf00b3048a653d36.jpg', '<p>Để giành chiến thắng trong cuộc thách đấu ba năm với Nạp Lan Yên Nhiên, Tiêu Viêm và Dược Lão đã đến sa mạc của tộc rắn, tìm kiếm ngọn lửa kỳ bí - Lửa Trái Đất Thanh Liên, để nâng cao sức mạnh của mình. Trong sa mạc của tộc rắn, họ bất ngờ bị cuốn vào cuộc chiến tranh giữa nhân loại và tộc rắn. Nữ hoàng của tộc rắn, Medusa, đang đóng cửa tu luyện để thăng cấp tôn nhi, tình cờ tạo cơ hội cho Tiêu Viêm. Do đó, Tiêu Viêm liên minh với Thanh Lân và Mực Lực, cùng nhau xâm nhập lâu đài của tộc rắn. Trong lúc này, Medusa do hấp thụ Lửa Trái Đất Thanh Liên mà mê muội, Tiêu Viêm dễ dàng giành được &quot;Lửa Trái Đất Thanh Liên&quot; mà anh từng ao ước. Trong khi đó, bên ngoài thành phố, cuộc chiến tranh lớn giữa nhân loại và tộc rắn đang diễn ra... Sức mạnh của Tiêu Viêm tăng vọt, hủy diệt âm mưu kế hoạch của tộc rắn. Sau một chuỗi sắp xếp, Tiêu Viêm bắt đầu hành trình đến &quot;Học Viện Ca-na-an&quot;...</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Victor Ma","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"Jiang Wu","avatar":""},{"name":"Gao Shuguang","avatar":""},{"name":"Hu Jing","avatar":""},{"name":"Wen Huang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Fights Break Sphere2","Battle Through the Heaven 2","Dou Po Cang Qiong: Zhi Ge","斗破苍穹2：止戈"]', 1784690324248);
