INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-pha-thuong-khung-2-ngung-chien', 'Đấu Phá Thương Khung 2: Ngừng Chiến', 'Fights Break Sphere 2', 'đấu phá thương khung 2: ngừng chiến fights break sphere 2 victor ma li jiuxiao jiang wu gao shuguang hu jing wen huang fights break sphere2 battle through the heaven 2 dou po cang qiong: zhi ge 斗破苍穹2：止戈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-thuong-khung-thuc-tinh', 'Đấu Phá Thương Khung: Thức Tỉnh', 'Fights Break Sphere', 'https://phimimg.com/upload/vod/20250421-1/549ea6e681d7e912df000f71578b0f16.jpg', 'https://phimimg.com/upload/vod/20250421-1/1c364a383027b2e6f9ed49d8bb1a72dd.jpg', '<p>Tiêu Viêm (Mã Bá Khiên đóng) là con trai thứ ba của một trong ba gia tộc lớn nhất thành Ô Thản, vì đấu khí không cao mà trở thành trò cười của mọi người. Khi bị đại đệ tử của Vân Lam Tông là Nạp Lan Yên Nhiên (Cận Dương Dương đóng) hủy hôn, Tiêu Viêm không chịu được sự sỉ nhục đã lập ra giao hẹn ba năm với Yên Nhiên, ba năm sau sẽ tỷ thí để quyết định hôn ước. Để nâng cao đấu khí, Tiêu Viêm đã đến rặng núi ma thú, kết bạn với Tiểu Y Tiên (Từ Y đóng), nhưng rồi cũng bị vướng vào trận tranh chấp của binh đoàn Đầu Sói. Khi trốn chạy sự truy đuổi của binh đoàn Đầu Sói, Tiêu Viêm đã vô tình bắt gặp Đấu hoàng Vân Chi (Hồ Tĩnh đóng) và Dực sư vương Tử Tinh đang giao đấu với nhau. Vân Chi không thể đánh bại Dực sư, Tiêu Viêm đã cứu Vân Chi. Sau một vài biến cố, hai người quyết định đi thách đấu Dực sư một lần nữa. Hai người chia nhau ra hành động, sau cùng giành thắng lợi. Vân Chi âm thầm rời đi, Tiêu Viêm cũng quyết định rời khỏi rặng núi ma thú, hướng đến sa mạc của Xà tộc....</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Victor Ma","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Jiang Wu","avatar":""},{"name":"Gao Shuguang","avatar":""},{"name":"Wen Huang","avatar":""},{"name":"Jiang Zhuojun","avatar":""},{"name":"Nita Xia","avatar":""},{"name":"Jin Yangyang","avatar":""},{"name":"Xu Kelong","avatar":""},{"name":"Hu Jing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Fights Break Sphere","Fights Breaks Sphere (The Movie)","Doupo Cangqiong","Dou Po Cang Qiong","Dou Po Cang Qiong - Jue Xing","Battle Through The Heavens","하늘깨기","斗破苍穹1：觉醒"]', 1784690324248);
