INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xi-trum-toi-tuong-lai', 'Xì Trum Tới Tương Lai', 'The Smurfs 3D: Smurf To The Future!', 'https://phimimg.com/upload/vod/20250421-1/787383874509bf4a2ab8d45521426d99.jpg', 'https://phimimg.com/upload/vod/20250421-1/e1d7c266ef6e7679ce525444d5275e09.jpg', '<p>Bộ phim là những cuộc phiêu lưu của các cô cậu Xì Trum màu xanh nhỏ bé, sống trong những ngôi nhà hình nấm dễ thương ở một ngôi làng yên bình. Chỉ cần nghe tên gọi là có thể biết được tố chất, bản tính của họ, nào là Tí Vua, Tí Quạu, Tí Cô Nương, Tí Điệu, Tí Đô, Tí Quậy... Họ luôn đoàn kết, bảo bọc nhau trước cái xấu và những âm mưu, thủ đoạn của lão Gà Mên độc ác.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 6, 2023, 'Lồng Tiếng', 'FHD', 'Pháp', 0, '[{"name":"Ngọc Châu","avatar":""},{"name":"Hoàng Sơn","avatar":""},{"name":"Quang Tuyên","avatar":""},{"name":"Anh Tuấn","avatar":""},{"name":"Huyền Chi","avatar":""},{"name":"Kim Ngọc","avatar":""},{"name":"Trần Vũ","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["炎炎消防队 叁之章","炎炎消防队 贰之章","炎炎消防队 壹之章","Fire Force","En''en no Shouboutai","Enn Enn no Shōbōtai","Enen no Shouboutai","Enen no Shouboutai: Ni no Shou","Enen no shôbôtai","En''en no Shouboutai Ni no Shou","Enn Enn no Shouboutai","Enen no Shōbōtai","Enen No Shouboutai - Ni no Shou","炎炎ノ消防隊 弐ノ章","炎炎ノ消防隊 参ノ章","Enen no Shouboutai San","Пламенная бригада пожарных","Пламенный отряд","Огненная бригада пожарных!","Огненная бригада","炎炎消防隊 貳之章","炎炎消防隊 參之章","Fire Brigade of Flames","Fireforce","Blazing Fire Brigade","Bộc Hỏa Nhân Tượng","炎炎