INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-thay-bau-troi-tua-nhu-ngay-ay-phan-2', 'Muốn Thấy Bầu Trời Tựa Như Ngày Ấy (Phần 2)', 'Our Skyy (Season 2)', 'https://phimimg.com/upload/vod/20250421-1/3f00af22ad89599534b23a5cd917dade.jpg', 'https://phimimg.com/upload/vod/20250421-1/f6683ca05115e83a80633cae81c1e7c6.jpg', '<p>Our Skyy 2 là một bộ phim gồm 8 phần, mỗi phần kể tiếp câu chuyện tình yêu của các cặp đôi nổi tiếng trong những phim trước như Bad Buddy, A Tale of Thousand Stars, My School President,... Mỗi cặp đôi sẽ gặp lại nhau trong những tình huống mới, đôi khi hài hước, đôi khi cảm động, giúp chúng ta hiểu hơn về tình yêu, sự trưởng thành và sự gắn bó. Đây là bộ phim rất dễ thương và gần gũi, đặc biệt phù hợp với những bạn yêu thích tình bạn, tình yêu tuổi học trò.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Nanon Korapat","avatar":""},{"name":"Ohm Pawat","avatar":""},{"name":"Jimmy Jitaraphol","avatar":""},{"name":"Sea Tawinan","avatar":""},{"name":"Gemini Norawit","avatar":""},{"name":"Fourth Nattawat","avatar":""},{"name":"Earth Pirapat","avatar":""},{"name":"Mix Sahaphap","avatar":""},{"name":"Joong Archen","avatar":""},{"name":"Dunk Natachai","avatar":""},{"name":"Pond Naravit","avatar":""},{"name":"Phuwin Tangsakyuen","avatar":""},{"name":"Force Jiratchapong","avatar":""},{"name":"Book Kasidet","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我们的天空2","Our Skyy 2 แค่เพื่อนครับเพื่อน x นิทานพันดาว","Our Skyy 2 เพื่อนายแค่หนึ่งเดียว","Our Skyy 2 ชอกะเชร์คู่กันต์","Our Skyy 2 แฟนผมเป็นประธานนักเรียน","Our Skyy 2 คาธ","Our Skyy 2 แล้วแต่ดาว","Our Skyy 2 แค่เพื่อนครับเพื่อน","Our Skyy 2 นิทานพันดาว","Our Skyy 2 Vice Versa","Our Skyy 2"]', 1784690324248);
