INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-thoi-joseon', 'Luật Sư Thời Joseon', 'Joseon Attorney: A Morality', 'https://phimimg.com/upload/vod/20250110-1/078e9c2ccd1cf6101a2a7d5d71941f1d.jpg', 'https://phimimg.com/upload/vod/20250110-1/0832142d380c3336fecb8a22215c82a2.jpg', '<p>Kang Han Soo cố gắng trở thành luật sư để trả thù kẻ chịu trách nhiệm về cái chết của cha mẹ mình. Bề ngoài, Han Soo nhìn có vẻ nông cạn và ngu ngốc, nhưng chàng có những cảm nhận sâu sắc, cùng trí óc thông minh của một thiên tài. Trong quá trình tích lũy kinh nghiệm, Han Soo cuối cùng đã trở thành một luật sư có năng lực, giúp nước, cứu dân.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2023, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Woo Do-hwan","avatar":""},{"name":"Bona","avatar":""},{"name":"Cha Hak-yeon","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Song Geon-hee","avatar":""},{"name":"Choi Hyeon-jin","avatar":""},{"name":"Lee Go-eun","avatar":""},{"name":"Kang Hyun-oh","avatar":""},{"name":"Lee Kyu-sung","avatar":""},{"name":"Lee Tae-geom","avatar":""},{"name":"Kim Do-yeon","avatar":""},{"name":"Han So-eun","avatar":""},{"name":"Choi Byung-mo","avatar":""},{"name":"Nam Kyung-eup","avatar":""},{"name":"Jeong A-mi","avatar":""},{"name":"Kim Jong-tae","avatar":""},{"name":"Shin Dong-mi","avatar":""},{"name":"Choi Moo-seong","avatar":""},{"name":"Lee Jun-hyeo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["조선 변호사","جوسون محامي الشعب","Joseon Lawyer","조선변호사"]', 1784690324248);
