INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-quan-tam', 'Vùng Quan Tâm', 'The Zone of Interest', 'https://phimimg.com/upload/vod/20250420-1/70ef4d0c8bdd48128fbe7402a7b5c743.jpg', 'https://phimimg.com/upload/vod/20250420-1/4604efea0341d651aca0f58b9fc2a7c5.jpg', '<p>&quot;The Zone Of Interest&quot; là phim chính kịch lịch sử của đạo diễn Jonathan Glazer, dựa trên cuốn tiểu thuyết cùng tên của tác giả nổi tiếng Martin Amis. Phim xoay quanh một gia đình Đức quốc xã sống cạnh trại tập trung Auschwitz. Trong đó, Rudolf Hoss - chỉ huy trại tập trung - và vợ Hedwig đang cố gắng xây dựng một cuộc sống mơ ước cho gia đình của họ tại một ngôi nhà và khu vườn bên cạnh trại tập trung này.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Christian Friedel","avatar":""},{"name":"Sandra Hüller","avatar":""},{"name":"Johann Karthaus","avatar":""},{"name":"Luis Noah Witte","avatar":""},{"name":"Nele Ahrensmeier","avatar":""},{"name":"Lilli Falk","avatar":""},{"name":"Anastazja Drobniak","avatar":""},{"name":"Cecylia Pekala","avatar":""},{"name":"Kalman Wilson","avatar":""},{"name":"Medusa Knopf","avatar":""},{"name":"Maximilian Beck","avatar":""},{"name":"Andrey Isaev","avatar":""},{"name":"Julia Babiarz","avatar":""},{"name":"Stephanie Petrowitz","avatar":""},{"name":"Martyna Poznanski","avatar":""},{"name":"Zuzann","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["利益区域","더 존 오브 인터레스트","منطقه مورد علاقه","KP24: Interesų zona","La zona de interés","존 오브 인터레스트","Maraq Dairəsi","Zona de interés","Zona de Interesse"