INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-toi-va-ma-quy-thanh-nguoi-mot-nha', 'Chuyện Tôi Và Ma Quỷ Thành Người Một Nhà', 'Marry My Dead Body', 'https://phimimg.com/upload/vod/20250420-1/4a606a62d0a19f3d2feabde3ce46affc.jpg', 'https://phimimg.com/upload/vod/20250420-1/8709b88069ba3c8ea52f9051595bb234.jpg', '<p>Sau khi nhặt được chiếc phong bì kỳ lạ, cuộc đời của cảnh sát Minh Hàn gặp bước ngoặt đáng sợ: giờ anh đã kết hôn với một người chồng ma và họ phải cùng nhau phá án.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Đài Loan', 1, '[{"name":"Greg Hsu","avatar":""},{"name":"Austin Lin","avatar":""},{"name":"Gingle Wang","avatar":""},{"name":"Tsai Chen-Nan","avatar":""},{"name":"Ma Nien-Hsien","avatar":""},{"name":"Man-Chiao Wang","avatar":""},{"name":"Tou Tsung-Hua","avatar":""},{"name":"Cheng Chih-wei","avatar":""},{"name":"Aaron Yan","avatar":""},{"name":"Chang Tsai-hsing","avatar":""},{"name":"Chen Yen-Tso","avatar":""},{"name":"Liu Kuan-ting","avatar":""},{"name":"Chris Lee","avatar":""},{"name":"Dean Tong","avatar":""},{"name":"Aaron Hong","avatar":""},{"name":"Lin He-Hsuan","avatar":""},{"name":"Che-Wen Tsai","avatar":""},{"name":"Emma Lin","avatar":""},{"name":"Wang Jun","avatar":""},{"name":"He","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["내가 귀신과 가족이 된 사건에 관하여","메마데바","Guan yu wo han gui bian cheng jia ren de na jian shi","Mi boda con un fantasma","Marry My Dead Body","Um Romance do Além","关于我和鬼变成家人的那件事","鬼家人","關於我和鬼變成家人的那件事","僕と幽霊が家族になった件","Czy poślubisz moje zwłoki?","Casa com o meu Cadáver","Как я женился на призраке","Chuyện Tôi & Ma Quỷ Thành Người Một Nhà"]', 1784690324248);
