INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-toi-va-ma-quy-thanh-nguoi-mot-nha', 'Chuyện Tôi Và Ma Quỷ Thành Người Một Nhà', 'Marry My Dead Body', 'chuyện tôi và ma quỷ thành người một nhà marry my dead body greg hsu austin lin gingle wang tsai chen-nan ma nien-hsien man-chiao wang tou tsung-hua cheng chih-wei aaron yan chang tsai-hsing chen yen-tso liu kuan-ting chris lee dean tong aaron hong lin he-hsuan che-wen tsai emma lin wang jun he 내가 귀신과 가족이 된 사건에 관하여 메마데바 guan yu wo han gui bian cheng jia ren de na jian shi mi boda con un fantasma marry my dead body um romance do além 关于我和鬼变成家人的那件事 鬼家人 關於我和鬼變成家人的那件事 僕と幽霊が家族になった件 czy poślubisz moje zwłoki? casa com o meu cadáver как я женился на призраке chuyện tôi & ma quỷ thành người một nhà', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-lac-huong', 'Kẻ Lạc Hướng', 'Mayhem! / Farang', 'https://phimimg.com/upload/vod/20250420-1/d8bd0dfa7b39d4144d2c7e48b06e2a01.jpg', 'https://phimimg.com/upload/vod/20250420-1/d3e2da1ac9ec53e1844b7a57cce91604.jpg', '<p>Kẻ Lạc Hướng xoay quanh Sam, một tù nhân gương mẫu, chỉ vài tháng trước khi được giải thoát, Sam đã cẩn trọng chuẩn bị cho cuộc tái hòa nhập xã hội. Tuy nhiên, mọi kế hoạch của anh sụp đổ khi quá khứ bất ngờ trỗi dậy, và một tai nạn buộc anh phải đưa ra quyết định khó khăn: trốn thoát. Năm năm sau, Sam đã xây dựng lại cuộc sống tại Thái Lan và có một gia đình hạnh phúc. Nhưng Narong, một ông trùm tội phạm địa phương, bắt buộc Sam phải trở lại con đường tội ác. Khi Sam quyết tâm thoát khỏi ánh sáng đen tối này, Narong đe dọa gia đình anh... Sam không thể tránh khỏi cuộc đấu tranh đầy nguy hiểm và băng qua vùng đất Thái Lan để thực hiện sứ mệnh trả thù.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Nassim Lyes","avatar":""},{"name":"Loryn Nounay","avatar":""},{"name":"Olivier Gourmet","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Mehdi Hadim","avatar":""},{"name":"Kenneth Won","avatar":""},{"name":"Sahajak Boonthanakit","avatar":""},{"name":"Chananticha Chaipa","avatar":""},{"name":"Boonsong Nakphoo","avatar":""},{"name":"Sawanee Utoomma","avatar":""},{"name":"Narilya Gulmongkolpech","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Venganza Del Dragón","Farang","Mayhem!","Фаранґ","Чужак","Farang - Implacável","ファラン","Farang - Schatten Der Unterwelt","极拳攻缉"]', 1784690324248);
