INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sat-phong-bao', 'Ám Sát Phong Bạo', 'Death Notice', 'https://phimimg.com/upload/vod/20240417-1/f8b6ad750ecaf9de11186f4fe4abb526.jpg', 'https://phimimg.com/upload/vod/20240417-1/728e31a5aec5e7360e548163f2487392.jpg', '<p>Kẻ sát nhân bí ẩn Darker, tự xưng là &quot;Thẩm phán&quot;, đã gây ra nhiều vụ án giết người có thông báo trước chấn động toàn thành phố. Bất cứ ai nhận được &quot;giấy báo tử&quot; của hắn đều sẽ bị sát hại tàn nhẫn theo ngày ghi trên đó. Để nhanh chóng phá án, cảnh sát La Phi (Trương Trí Lâm), nhân chứng vụ nổ Hoàng Thiếu Bình (Cổ Thiên Lạc), và trưởng ban chuyên án Hàn Hạo (Ngô Trấn Vũ) cùng nhau tham gia vào cuộc điều tra. Darker rốt cuộc là ai? Chân tướng liên tục đảo ngược, những bí mật kinh hoàng dần dần hé lộ.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Trương Trí Lâm","avatar":""},{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Hồ Hạnh Nhi","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Trần Quốc Khôn","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
