INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lego-ninjago-nhung-con-rong-troi-day-phan-1', 'LEGO Ninjago: Những Con Rồng Trỗi Dậy (Phần 1)', 'LEGO Ninjago: Dragons Rising (Season 1)', 'lego ninjago: những con rồng trỗi dậy (phần 1) lego ninjago: dragons rising (season 1) sam vincent deven mack kelly metzger vincent tong kazumi evans sabrina pitre lego ninjago: ascenção dos dragões 乐高幻影忍者：神龙崛起 乐高幻影忍者第17季 乐高幻影忍者第18季 לגו נינג''גו עליית הדרקונים lego 닌자고: 드래곤 라이징 레고 닌자고: 드래곤 라이징 new 닌자고 드래곤 라이징 樂高旋風忍者：猛龍崛起 ніндзяґо: повстання драконів ninjago: united ninjago: dragons rising lego ninjago: dragons rising - the elemental mechs lego ninjago: dragons rising', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-tu-phi-cong-luoc', 'Thế Tử Phi Công Lược', 'Dramatic Self-Help Strategy', 'https://phimimg.com/upload/vod/20250416-1/15cc254f45aff05e25b877235eaed2eb.jpg', 'https://phimimg.com/upload/vod/20250416-1/acbd4a2a78bc91e2137b34419118d224.jpg', '<p>Nữ diễn viên Lý Thái Vi bất ngờ xuyên không đến thời cổ đại và trở thành thế tử phi ngốc nghếch cùng tên. Thế tử phi này có hôn ước từ nhỏ với Thế tử Thẩm Hoài Cẩn, nhưng cứ đến ngày thành hôn là thế tử lại mất mạng, khiến Lý Thái Vi rơi vào vòng lặp không hồi kết. Để chấm dứt tình trạng oái oăm này, cô bắt đầu truy tìm hung thủ và cũng từ đó mà dần dần phải lòng Thẩm Hoài Cẩn.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Tử Tuyền","avatar":""},{"name":"Hách Phú Thân","avatar":""},{"name":"Lý Tuấn Hào","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["世子妃攻略","Princess Raiders","희정자구공략: 세자를 구하라","戲精自救攻略","戏精自救攻略"]', 1784690324248);
