INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-tu-phi-cong-luoc', 'Thế Tử Phi Công Lược', 'Dramatic Self-Help Strategy', 'thế tử phi công lược dramatic self-help strategy kim tử tuyền hách phú thân lý tuấn hào 世子妃攻略 princess raiders 희정자구공략: 세자를 구하라 戲精自救攻略 戏精自救攻略', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-ve-dem-o-truong-sa', 'Cuộc Sống Về Đêm Ở Trường Sa', 'Tale Of The Night', 'https://phimimg.com/upload/vod/20250416-1/2de5701a7cefbd0046c70ebd789960e5.jpg', 'https://phimimg.com/upload/vod/20250416-1/ce630579ba4a0da6bf1057b6e02f83f9.jpg', '<p>Phim kể về một đêm kỳ diệu ở Trường Sa (Trường Sa của Việt Nam). Cảnh Vi Vi và Hà Tây Tây, hai người xa lạ, gặp nhau tình cờ trong một hiệu sách và hen nhau đi du lich đêm. Hà Tây Tây chia sẻ về người anh trai cùng cha khác mẹ của mình- Hà An, một diễn viên hài độc thoai sẽ biểu diễn đêm nav. Bố của Hà An xuất hiện trong khán phòng, hai người chia tay trong cảnh chẳng vui vẻ. Ở phía khác, Trần Thanh Trí, Lương Bảo Kỳ và lão Tạ đang canh giữ vòng đu quay. Họ vừa ngắm cảnh đêm vừa thở dài, nhận ra rằng công việc bản thời gian không dễ dàng. Đêm dần trở nên khuya hơn, và đây cũng là lần cuối cùng bà chủ quán ăn nổi tiếng trên mạng đứng bếp. Chị quyết định giao quyền tiếp quản quán cho học trò của mình. Trong thành phố này, mọi người cùng nhau ngồi ăn phở, gặp gỡ, yêu thương, ở lại, rời đi, hoà giải và đoàn tụ. Mỗi người đều tìm thấy lý do để yêu thương nơi này.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Duẫn Phưởng","avatar":""},{"name":"Trương Tịnh Nghi","avatar":""},{"name":"Tô Nham","avatar":""},{"name":"Ngô Hạo Thần","avatar":""},{"name":"Bạch Vũ Phàm","avatar":""},{"name":"Chu Tư Vũ","avatar":""},{"name":"Ngô Quân","avatar":""},{"name":"La Cương","avatar":""},{"name":"Trương Nghệ Hưng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["群星闪耀的夜晚","我的夜晚比白天多","长沙夜生活"]', 1784690324248);
