INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-song-ve-dem-o-truong-sa', 'Cuộc Sống Về Đêm Ở Trường Sa', 'Tale Of The Night', 'cuộc sống về đêm ở trường sa tale of the night duẫn phưởng trương tịnh nghi tô nham ngô hạo thần bạch vũ phàm chu tư vũ ngô quân la cương trương nghệ hưng 群星闪耀的夜晚 我的夜晚比白天多 长沙夜生活', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-mai-moi-xung-tam', 'Kẻ Mai Mối Xứng Tầm', 'Sassy Matchmaker', 'https://phimimg.com/upload/vod/20250415-1/8d7c48ba8e8a4d554298981129485caa.jpg', 'https://phimimg.com/upload/vod/20250415-1/7e91b4fd585268e8b5694d27d59dd8e1.jpg', '<p>Bộ phim xoay quanh Nori - cô cháu gái xinh đẹp, thông minh của bà Thaem - bà mối số một tại kinh đô Băng Cốc. Vốn dĩ chỉ muốn giúp đỡ bà mình trong vài phi vụ mai mối nho nhỏ, Nori bất ngờ bị cuốn vào một nhiệm vụ tưởng chừng đơn giản mà hóa ra lại phức tạp đến không ngờ: tìm vợ cho Khun Phra – một chàng cảnh sát tài giỏi, điển trai, nhưng đã bước sang tuổi 40 mà vẫn chưa lập gia đình. Khun Phra là mẫu người nguyên tắc, ít nói, thậm chí có phần lạnh lùng. Anh không mấy mặn mà với chuyện yêu đương, càng không hứng thú với những buổi mai mối. Thế nhưng, dưới sự thúc ép của gia đình và sự nhiệt tình của bà Thaem, anh đành miễn cưỡng tham gia cuộc gặp gỡ &quot;định mệnh&quot; do Nori sắp đặt. Từ đây, hàng loạt tình huống dở khóc dở cười xảy ra...</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 7, 2023, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Sean Jindachot","avatar":""},{"name":"Charlette Wasita Hermenau","avatar":""},{"name":"Cholawit Meetongcom","avatar":""},{"name":"Nutchaporn Ounsawad","avatar":""},{"name":"Parn Khomkrit Duangsuwan","avatar":""},{"name":"Sarucha Petchroj","avatar":""},{"name":"Pu Kittipong Pluempredaporn","avatar":""},{"name":"Jakkrit Amarat","avatar":""},{"name":"Peter Tuinstra","avatar":""},{"name":"Jubjang Vimpolphan Chaleejunghran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7