INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noc-doc-vang-phan-2', 'Nọc Độc Vàng (Phần 2)', 'Yellowjackets (Season 2)', 'https://phimimg.com/upload/vod/20250415-1/2868d79ec2b2cb0901930f8ed4d9bf54.jpg', 'https://phimimg.com/upload/vod/20250415-1/3be9cd7432f2e68411ff22dff1eb83ef.jpg', '<p>Một đội bóng đá nữ trung học vô cùng tài năng trở thành những người may mắn sống sót sau vụ tai nạn máy bay sâu trong vùng hoang dã Ontario.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Melanie Lynskey","avatar":""},{"name":"Tawny Cypress","avatar":""},{"name":"Sophie Nélisse","avatar":""},{"name":"Jasmin Savoy Brown","avatar":""},{"name":"Sophie Thatcher","avatar":""},{"name":"Sammi Hanratty","avatar":""},{"name":"Steven Krueger","avatar":""},{"name":"Warren Kole","avatar":""},{"name":"Courtney Eaton","avatar":""},{"name":"Liv Hewson","avatar":""},{"name":"Kevin Alves","avatar":""},{"name":"Lauren Ambrose","avatar":""},{"name":"Christina Ricci","avatar":""},{"name":"Sarah Desjardins","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["黄蜂","צהובות","옐로우재킷","Lapsenes","Yellowjackets"]', 1784690324248);
