INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-nam-hieu-long-toi', 'Gió Nam Hiểu Lòng Tôi', 'South Wind Knows', 'https://phimimg.com/upload/vod/20250413-1/5d4e632609b09be0882a19416221743b.jpg', 'https://phimimg.com/upload/vod/20250413-1/2fbd9d9edd3f5981d688e346b706ab9a.jpg', '<p>Trong quá trình cùng nhau tìm kiếm thảo dược để nghiên cứu thuốc, cặp đôi oan gia Chu Cựu và Phó Vân Thâm bắt đầu nảy sinh tình cảm. Nhưng rồi một bi kịch đã xảy ra, khiến hai người phải chia cắt. Hai năm sau, họ gặp lại nhau và quyết tâm nối lại tình xưa. Liệu lần này tình yêu của họ có thể chiến thắng mọi thử thách chông gai hay không?</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Dư Hi","avatar":""},{"name":"Thành Nghị","avatar":""},{"name":"Phó Tân Bác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["South Wind Knows My Mood","South Wind Knows","南风知我意"]', 1784690324248);
