INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dung-trung-manh', 'Bỗng Dưng Trúng Mánh', 'Usury Academy', 'https://phimimg.com/upload/vod/20241028-1/00c278aa4c37dc947c8f5083de9267a8.jpg', 'https://phimimg.com/upload/vod/20241028-1/8b14b661f9f923766590ce467615f3a5.jpg', '<p>Bỗng Dưng Trúng Mánh là câu chuyện từ cá biệt toàn trường hoá tài phiệt học đường của Lee Kang-jin - một học sinh vốn thường xuyên bị bắt nạt. Tình cờ nhặt được chiếc phong bì chứa đầy tiền mặt của ông trùm cho vay nặng lãi Rang, cuộc đời Kang-jin đã hoàn toàn thay đổi. Rang dạy Kang-jin những bài học đầu tiên về nghề cho vay siêu lợi nhuận, từ đó biến cậu học trò lầm lì trở thành chiến thần tài chính, đại gia mới nổi, ông hoàng cho vay nặng lãi của trường trung học Geumhwa.</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Yoo Seon-ho","avatar":""},{"name":"Kang Mi-na","avatar":""},{"name":"Yoo In-soo","avatar":""},{"name":"Shin Soo-hyun","avatar":""},{"name":"Lee Chan-hyeong","avatar":""},{"name":"Seo Hye-won","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["참, 잘했어요!","Good Job","Loan Boy","Usury Academy","Oh, Well Done!","Cham, Jalhaesseoyo!","You Did Great!","Хорошая работа!","사채소년"]', 1784690324248);
