INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bong-dung-trung-manh', 'Bỗng Dưng Trúng Mánh', 'Usury Academy', 'bỗng dưng trúng mánh usury academy yoo seon-ho kang mi-na yoo in-soo shin soo-hyun lee chan-hyeong seo hye-won 참, 잘했어요! good job loan boy usury academy oh, well done! cham, jalhaesseoyo! you did great! хорошая работа! 사채소년', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-6', 'Họa giang hồ chi bất lương nhân (Phần 6)', 'A Portrait of Jianghu: Bad Guys (Season 6) / The Degenerate-Drawing Jianghu 6', 'https://phimimg.com/upload/vod/20250412-1/b7a3ea6313b5e4fb9484a3bf574285f9.jpg', 'https://phimimg.com/upload/vod/20250412-1/07bb3d6931a1eacb6969bc511d8663c4.jpg', '<p>Sau phần 5 Nhiêu Cương, 10 tập đầu của phần 6 là những cục diện rải rác hỗn loạn, liên tục đào hố rồi lấp hố. Lý Tinh Vân và Trương Tử Phàm trở về từ Miêu Cương, lấy bàn cờ làm mở đầu, kéo ra hai tuyến hành động một sáng một tối. Lý Tinh Vân cứu Bất Lương Nhân, trở thành Bất Lương soái, chết đi rồi sống lại, từ đó tuyến trong tối dần dần hình thành. Trương Tử Phàm thì đi thuyết phục chư hầu, liên hợp với Thạch Kính Đường chuẩn bị cho những nước đi cuối cùng. Lý Tinh Vân lấy thân phận Thiên Ám Tinh để cai quản Bất Lương Nhân. Nước Kỳ suy tàn, vào Lạc Dương để tỏ ra như là một hành động chắc chắn sẽ thua, nhưng thực chất là ép Lý Tự Nguyên thỏa hiệp với Mạc Bắc, khiến cho trung thần mất niềm tin, không còn ủng hộ, để trải sẵn bước đệm cho việc xưng đế và đại điển Tây Cung. Ở 10 tập sau, dùng thế cờ để dẫn cả bàn cờ hành động, Lý Tinh Vân và Trương Tử Phàm triển khai chiến đấu với Lý Tự Nguyên ở Tây Cung. Lý Tự Nguyên hấp thụ nội lực chí chân chí dương của Lý Tinh Vân, dung hợp với công pháp của mình, nhưng không đấu lại được màn kết hợp của Lý Tinh Vân và Trương Tử Phàm. Cuối cùng, Trương Tử Phàm dùng kiếm Long Tuyền đâm vào thân thể Lý Tự Nguyên, lấy quạt sắt chém đầu lão, Lý Tự Nguyên hết vai. Kết cục cuối cùng là Trương Tử Phàm xưng đế với danh nghĩa của Lý Tự Nguyên, Lâm Hiên thành Hoàng Hậu, Lý Tinh Vân thì tiếp tục giả làm Bất Lương Soái, hoàn thành ý chí lúc đầu của cả hai. Ngoài ra, trong phim còn có rất nhiều tình tiết đặc sắc về Cơ Như Tuyết, Lâm Hiên, Lạc Tiểu Bắc Bất Lương Nhân đại chiến Lý Tồn Lễ, hay là Kỳ Vương giả nữ mang theo Huyễn Âm Phường và Tứ Đại Thi Tổ chi viện cho chiến cục ngoài cung…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Mengmeng Yan","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Qiuxiang Shen","avatar":""},{"name":"Jun Chu","avatar":""},{"name":"Shuren Zhao","avatar":""},{"name":"Xuecen Bai","avatar":""},{"name":"Lu Zhixing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["画江湖之不良人动画版","Huajianghu Bu Liang Ren","Buliang Ren VI","画江湖之不良人Ⅴ","Buliang Ren II","Buliang Ren V","Buliang Ren III","Buliang Ren IV","Buliang Ren","Drawing Jianghu Of Bu Liang Ren Ⅵ","Drawing Jianghu of Bu Liang Ren","Hua Jiang Hu Zhi Bu Liang Ren","The Degenerate-Drawing Jianghu","画江湖之不良人II","画江湖之不良人第七季：九幽玄天","画江湖之不良人","畫江湖之不良人","A Portrait of Jianghu Bad Guys","A Portrait of Jianghu : Bad Guys"]', 1784690324248);
