INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-6', 'Họa giang hồ chi bất lương nhân (Phần 6)', 'A Portrait of Jianghu: Bad Guys (Season 6) / The Degenerate-Drawing Jianghu 6', 'họa giang hồ chi bất lương nhân (phần 6) a portrait of jianghu: bad guys (season 6) / the degenerate-drawing jianghu 6 jiang bian mengmeng yan zhao yi qiuxiang shen jun chu shuren zhao xuecen bai lu zhixing 画江湖之不良人动画版 huajianghu bu liang ren buliang ren vi 画江湖之不良人ⅴ buliang ren ii buliang ren v buliang ren iii buliang ren iv buliang ren drawing jianghu of bu liang ren ⅵ drawing jianghu of bu liang ren hua jiang hu zhi bu liang ren the degenerate-drawing jianghu 画江湖之不良人ii 画江湖之不良人第七季：九幽玄天 画江湖之不良人 畫江湖之不良人 a portrait of jianghu bad guys a portrait of jianghu : bad guys', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-khach-khong-chiu-roi-di', 'Vị Khách Không Chịu Rời Đi', 'The Smurfs', 'https://phimimg.com/upload/vod/20250412-1/5a820991abe12b9eb4f5d08ab6e4e153.jpg', 'https://phimimg.com/upload/vod/20250412-1/9d0cc7ea50682dfaeb67e663af5efcde.jpg', '<p>Bộ phim là những cuộc phiêu lưu của các cô cậu Xì Trum màu xanh nhỏ bé, sống trong những ngôi nhà hình nấm dễ thương ở một ngôi làng yên bình. Chỉ cần nghe tên gọi là có thể biết được tố chất, bản tính của họ, nào là Tí Vua, Tí Quạu, Tí Cô Nương, Tí Điệu, Tí Đô, Tí Quậy... Họ luôn đoàn kết, bảo bọc nhau trước cái xấu và những âm mưu, thủ đoạn của lão Gà Mên độc ác.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 7, 2023, 'Lồng Tiếng', 'FHD', 'Pháp', 0, '[{"name":"Ngọc Châu","avatar":""},{"name":"Hoàng Sơn","avatar":""},{"name":"Quang Tuyên","avatar":""},{"name":"Anh Tuấn","avatar":""},{"name":"Huyền Chi","avatar":""},{"name":"Kim Ngọc","avatar":""},{"name":"Trần Vũ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["蓝色小精灵","蓝精灵","Els barrufets 3D","개구쟁이 스머프","스머프","නිල් කුරුමිට්ටෝ","Les Schtroumpfs"]', 1784690324248);
