INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-ky-lan-phan-1', 'Học Viện Kỳ Lân (Phần 1)', 'Unicorn Academy (Season 1)', 'https://phimimg.com/upload/vod/20240628-1/32f09db5b0edabbcad72083c2d9b779d.jpg', 'https://phimimg.com/upload/vod/20240628-1/dc50c916c95821443e33466799905520.jpg', '<p>Khi thế lực hắc ám đe dọa phá hủy đảo Kỳ Lân, một thiếu nữ dũng cảm và năm người bạn cùng trường phải đứng lên bảo vệ học viện phép thuật mà họ trân quý.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '[]', 1784690324248);
