INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guong-den-phan-6', 'Gương Đen (Phần 6)', 'Black Mirror (Season 6)', 'https://phimimg.com/upload/vod/20231002-1/acd0c47209f01ca2345d8832e9a2e513.jpg', 'https://phimimg.com/upload/vod/20231002-1/bde825e0ddc9cfe9a786ddd7520048f4.jpg', '<p>Những câu chuyện lắt léo và cả những nỗi kinh hoàng kéo dài qua các thời đại, mang đến vô số bất ngờ trong mùa khó đoán nhất của hợp tuyển mang tính đột phá này.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jesse Plemons","avatar":""},{"name":"Cristin Milioti","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Michaela Coel","avatar":""},{"name":"Rosemarie DeWitt","avatar":""},{"name":"Douglas Hodge","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Brenna Harding","avatar":""},{"name":"Owen Teague","avatar":""},{"name":"Andrew Gower","avatar":""},{"name":"Kiran Sonia Sawar","avatar":""},{"name":"Georgina Campbell","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Maxine Peake","avatar":""},{"name":"Jake Davies","avatar":""},{"name":"Clint Dyer","avatar":""},{"name":"Letitia Wr","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324248);
