INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-tiec-dam-mau', 'Bữa Tiệc Đẫm Máu', 'Kill Her Goats', 'https://phimimg.com/upload/vod/20250411-1/6f2b6f7f04b4a6835315b95fd7ae4d42.jpg', 'https://phimimg.com/upload/vod/20250411-1/cbed78818673a56fba627f1b3eb479f1.jpg', '<p>Món quà tốt nghiệp của Audra là ngôi nhà mơ ước của cô, nhưng nó nhanh chóng trở thành cơn ác mộng sống khi một số vị khách không mời mà đến dự bữa tiệc trở về quê hương của cô, những người không mấy tinh tế về việc họ không chấp thuận chủ nhân mới của ngôi nhà.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Arielle Raycene","avatar":""},{"name":"Ellie Gonsalves","avatar":""},{"name":"Kane Hodder","avatar":""},{"name":"Danielle Mathers","avatar":""},{"name":"Monica Sims","avatar":""},{"name":"Amberleigh West","avatar":""},{"name":"Colleen Hagerty","avatar":""},{"name":"Skyler Seymour","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Kill Her Goats"]', 1784690324248);
