INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-tinh-dinh-menh', 'Sợi Tình Định Mệnh', 'Yeonak, My Destiny', 'https://phimimg.com/upload/vod/20250411-1/708cd22085f6abb35086c904cdc4ddca.jpg', 'https://phimimg.com/upload/vod/20250411-1/7c412bfebee1ab5644d51499e88c3ce5.jpg', '<p>Vào đầu triều đại Joseon, khi đất nước đang được đặt nền móng bằng lễ nhạc. Đại vương Sejong ban chiếu chỉ cho thiên tài âm nhạc Park Yeon phải thiết lập lại hệ thống âm luật của Joseon. Tuân theo thánh chỉ, Park Yeon ngày đêm nghiên cứu, nhưng liên tục vấp phải khó khăn và thất bại trong môi trường khắc nghiệt. Ngay cả lời tỏ tình của Bạch A, một danh cầm nổi tiếng với đàn Gayageum, người luôn âm thầm yêu mến anh bên cạnh, cũng khiến Park Yeon càng thêm rối bời. Park Yeon, thiên tài âm nhạc làm rung chuyển lịch sử âm nhạc Joseon — người từng xem âm nhạc là tất cả, nay đang đứng trước một chương mới trong cuộc đời mình!</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Wook","avatar":""},{"name":"Song Min-gyeong","avatar":""},{"name":"Park Geun-soo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["연악: 나의 운명"]', 1784690324248);
