INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-menh-ngang-trai', 'Định Mệnh Ngang Trái', 'Meant To Be', 'https://phimimg.com/upload/vod/20250410-1/5768a841ecc972d94d91640dac311658.jpg', 'https://phimimg.com/upload/vod/20250410-1/0f0b4771154c5e77eda6278554ad272d.jpg', '<p>Bộ phim đi sâu vào những phức tạp của tình yêu, bản chất con người và việc theo đuổi ham muốn cá nhân. Đồng thời, bộ phim là câu chuyện về niềm hy vọng và sự cứu đỗi, một bông hoa vẫn nở rộ bất chấp mặt đất đóng băng. Bên cạnh đó cũng đưa ra bài học khiến chúng ta suy ngẫm về cuộc sống của chính mình, hiểu rõ hơn về bản thân, những người xung quanh và những lựa chọn mà chúng ta đưa ra.</p>', 'Hoàn Tất (120/120)', 120, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Yu-seok","avatar":""},{"name":"Jeon Hye-yeon","avatar":""},{"name":"Seo Han-gyeol","avatar":""},{"name":"Jung Woo-yeon","avatar":""},{"name":"Jin Ju-hyung","avatar":""},{"name":"Go Eun-mi","avatar":""},{"name":"Jo Mi-ryung","avatar":""},{"name":"Byun Woo-min","avatar":""},{"name":"Park Chan-hwan","avatar":""},{"name":"Lee Hoon","avatar":""},{"name":"Cho Eun-sook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["هر چه خواست خداست","تقدیر","하늘의 인연"]', 1784690324248);
