INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuc-sau', 'Vực Sâu', 'Justice In The Dark', 'https://phimimg.com/upload/vod/20250408-1/df64e064a3188d8c183aa60ee9c458d7.jpg', 'https://phimimg.com/upload/vod/20250408-1/7824cecaf4a87c70171276799c7b8842.jpg', '<p>Giới thiệu Vực Sâu Vực Sâu Giới thiệu Vào năm 253 của nền văn minh Tân Nguyên, tỷ lệ tội phạm gia tăng liệu có liên quan đến &quot;người không có sự đồng cảm&quot; hay không đang trở thành chủ đề ngày càng thu hút nhiều sự chú ý trong xã hội. Một vụ án giết hại người giao hàng có liên quan đến một băng nhóm tội phạm và hung thủ được xác định là &quot;người không có sự đồng cảm&quot;, kiểu người khơi dậy nhiều sự tranh luận của xã hội nhất. Tuy vụ án đã kết thúc thuận lợi nhưng Lạc Vi Chiêu, một trinh sát viên của đội điều tra đặc biệt phụ trách vụ án này lại nhận ra mọi thứ không hề đơn giản như bề nổi. Sau đó, vụ án người mất tích, vụ tai nạn xe của một đại gia, vụ án sinh viên đại học đi lạc bị giết hại, từng &quot;người không có sự đồng cảm&quot; bị đẩy ra trước công chúng. Lạc Vi Chiêu nhận ra ngoài những hung thủ bị đẩy ra này, Bùi Tố, một trinh sát viên thực tập dường như cũng có liên quan, đằng sau những vụ án này còn có người khác đang làm người chắp nối. Cuối cùng, những thế lực phạm tội này đã bị tóm gọn, mọi người cũng nhận ra rằng gen không thể quyết định một người là tốt hay xấu, con người có thể chiến thắng gen, con người có thể tự do lựa chọn, chỉ cần trong tim tồn tại ánh sáng hy vọng thì cho dù ở trong bóng tối cũng sẽ có ngày về dưới ánh mặt trời.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Xincheng","avatar":""},{"name":"Fu Xinbo","avatar":""},{"name":"Zhao Zhiwei","avatar":""},{"name":"Liu Yihong","avatar":""},{"name":"Xiao Yu","avatar":""},{"name":"Geng Jiawei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["深渊","默读","Guang Yuan","Безмолвное чтение","Освещая тьму","Бездна","Правосудие во тьме","The Abyss","Light the Darkness","The Light in the Night","光·渊"]', 1784690324248);
