INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-trinh-tham-ban-thai', 'Bác Sĩ Trinh Thám (Bản Thái)', 'Doctor Detective', 'https://phimimg.com/upload/vod/20250404-1/fa731eb228ed71bddca51bbae2e5536d.jpg', 'https://phimimg.com/upload/vod/20250404-1/6cdae7b7aede37754cf5810317cb8e43.jpg', '<p>Phim lấy cảm hứng từ đại dịch Covid-19 với mục tiêu giúp khán giả hiểu rõ hơn quy trình làm việc và những khó khăn mà các y bác sĩ phải đối mặt khi dịch bệnh bùng phát. Khi một bệnh truyền nhiễm chết người tàn phá một ngôi làng nhỏ, nhóm các nhà dịch tễ học do bác sĩ Khunkhao dẫn đầu phải chạy đua với thời gian để điều tra nguồn gốc bệnh cũng như cố gắng ngăn chặn sự lây lan của căn bệnh nguy hiểm này.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Nadech Kugimiya","avatar":""},{"name":"Kimberly Ann Voltemas","avatar":""},{"name":"Alexander Rendell","avatar":""},{"name":"Phulita Supinchompoo","avatar":""},{"name":"Sanya Kunakorn","avatar":""},{"name":"Kathaleeya McIntosh","avatar":""},{"name":"Songsit Rungnopakunsi","avatar":""},{"name":"Phollawat Manuprasert","avatar":""},{"name":"Khwanruedi Klomklom","avatar":""},{"name":"Niti Chaichitathorn","avatar":""},{"name":"Pai Virasut Hiranbuth","avatar":""},{"name":"Nipaporn Thititanakarn","avatar":""},{"name":"Th","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["สืบลับหมอระบาด"]', 1784690324248);
