INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-ho-dia-nguc', 'Hoan Hô Địa Ngục', 'Hail To Hell', 'https://phimimg.com/upload/vod/20250403-1/81e125759da0bcfd5eadd60208d99347.jpg', 'https://phimimg.com/upload/vod/20250403-1/4daf8ce2e1041d122d129d73358c0172.jpg', '<p>Na-mi và Sun-woo, hai kẻ bị cô lập trong trường, lên kế hoạch tự sát thay vì tham gia chuyến dã ngoại của lớp. Thế nhưng, ngay khoảnh khắc sắp thành công, họ phát hiện ra Chae-lin—người từng khiến cuộc sống của họ khốn khổ—giờ đây lại đang tận hưởng một cuộc sống hạnh phúc ở Seoul. Quyết tâm trả thù trước khi kết thúc cuộc đời, họ tìm đến Chae-lin. Nhưng khi cuối cùng cũng chạm mặt cô ấy, họ lại thấy trước mắt mình một cô gái tốt bụng, khiến kế hoạch của họ hoàn toàn đảo lộn…</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Oh Woo-ri","avatar":""},{"name":"Bang Hyo-rin","avatar":""},{"name":"Jung Yi-ju","avatar":""},{"name":"Park Sung-hoon","avatar":""},{"name":"Lee Sun-hee","avatar":""},{"name":"Lee Ju-won","avatar":""},{"name":"Lee Eun-sol","avatar":""},{"name":"Kim Young-sun","avatar":""},{"name":"Heo Jeong-do","avatar":""},{"name":"Yang Heung-ju","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hail to Hell","지옥만세"]', 1784690324248);
