INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-chu-nai-ha-khong-de-lam', 'Trại Chủ Nại Hà Không Dễ Làm', 'Yes, I Am a Spy', 'https://phimimg.com/upload/vod/20250331-1/240163354a478a0ed6e1051b91783058.jpg', 'https://phimimg.com/upload/vod/20250331-1/58a97534da1f1d83b92613959e1913b4.jpg', '<p>Việc rò rỉ danh sách bí mật của các đặc vụ bí mật của Ấn Diệu bị đánh cắp bởi cnội gián đã gây ra sự hoang mang trong tổ chức. Người đứng đầu Ấn Diệu - Thẩm Dịch Phụng nhận lệnh đi tìm gián điệp. Ngoài ra, để bảo vệ các mật vụ còn hoạt động bên ngoài, danh sách bị đánh cắp phải được thu hồi. Trương Tiểu Hoa được giao nhiệm vụ điều tra xem ai là gián điệp và phát hiện ra rằng trại Nại Hà có tin tức của danh sách nên đã giả vờ để nhị trại chủ bắt. Muốn quyến rũ trại chủ để lấy lại danh sách nhưng không ngờ suýt mất mạng. Trong lúc cấp bách nhị trại chủ ra tay giúp đỡ, ngỏ lời muốn lấy làm vợ, trại chủ nể tình chỉ có thể miễn cưỡng đồng ý, nhưng bí mật lên kế hoạch loại bỏ quyền lực của Lạc Hà. Tiểu Hoa thấy được trong trại luôn có nội chiến, nên lợi dụng mỹ nhân kế để chia rẽ quan hệ của Lạc Hà và trại chủ, nhân cơ hội tìm kiếm danh sách. Nhưng Lạc Hà sớm nhìn rõ mưu kế của cô, và thân phận của Lạc Hà cũng không hề đơn giản...</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Xuan","avatar":""},{"name":"Cao Saiya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["奈何寨主不好当"]', 1784690324248);
