INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-lua-nhan-gian-cua-toi', 'Khói Lửa Nhân Gian Của Tôi', 'Fireworks Of My Heart', 'https://phimimg.com/upload/vod/20240815-1/5575adcae0a157a0c1ea8b9b08daa589.jpg', 'https://phimimg.com/upload/vod/20240815-1/008e6a063b10e760b0fcd86a72f85708.jpg', '<p>Xoay quanh đội trưởng đội cứu hỏa Tống Diễm và bác sĩ khoa cấp cứu Hứa Thấm. Thời niên thiếu, dù đẹp đôi nhưng buộc phải chia tay vì bị gia đình phản đối. Sau 10 năm, cả hai đều đã trưởng thành hơn và ít nhiều đã đổi khác so với trước kia. Nút thắt ngăn cách giữa hai người cũng dần được tháo gỡ, họ cùng nhau khắc phục những rào cản, vượt qua tất cả để đồng hành bên nhau.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Dương","avatar":""},{"name":"Trương Bân Bân","avatar":""},{"name":"Vương Sở Nhiên","avatar":""},{"name":"Dương Siêu Việt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
