INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-du-ky-bat-tien-phuc-ma', 'Đông Du Ký: Bát Tiên Phục Ma', 'Travel to the East', 'https://phimimg.com/upload/vod/20250325-1/d5ae0c7042ad4b345e41b4a97ecd8c6e.jpg', 'https://phimimg.com/upload/vod/20250325-1/6bcf6a77974c4000e9621bfe8086f33c.jpg', '<p>Phim kể về Lã Động Tân, một trong Bát tiên, đã hành động trái phép trong trận chiến với Côn Nguyên Ma Tôn, điều này đã gián tiếp dẫn đến cái chết của Hà Tiên Cô. Sau khi bị giáng xuống trần gian, anh gặp Bạch Oanh, chủ nhân của ngôi nhà tranh có ngoại hình giống Hà Tiên Cô nhưng tính cách hoàn toàn khác. Để cứu Hà Tiên Cô, Lã Động Tân, Bạch Oanh và thần khuyển Ao đã bắt tay vào hành trình một cuộc hành trình đầy nguy hiểm về phía đông…</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ma Jingtao","avatar":""},{"name":"Dong Weijia","avatar":""},{"name":"Gong Hanlin","avatar":""},{"name":"Liang Yuan","avatar":""},{"name":"He Qiwei","avatar":""},{"name":"Cui Zhigang","avatar":""},{"name":"He Chengxi","avatar":""},{"name":"Li Faguang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Travel To The East","东游之八仙伏魔"]', 1784690324248);
