INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('transformers-quai-thu-troi-day', 'Transformers: Quái Thú Trỗi Dậy', 'Transformers: Rise of the Beasts', 'https://phimimg.com/upload/vod/20250325-1/8bfb54c093ec7b3a0c09b160732fb84d.jpg', 'https://phimimg.com/upload/vod/20250325-1/9b20952c4ea497062766f4ad651075bb.jpg', '<p>Lấy bối cảnh vào năm 1994, bộ phim lấy mốc thời gian 300 năm sau khi Bumblebee xuất hiện. Lúc này, Michael Bay vẫn còn chưa cầm trịch và Optimus Prime, thủ lĩnh can trường của Autobots vẫn còn lạ lẫm với Trái đất. &nbsp;Tại đây, Optimus đã gặp gỡ Optimus Primal và nhánh Maximals - nhóm robot mới xuất hiện và có khả năng biến mình thành động vật thay vì ô tô như trước đó. Họ bị cuốn vào một trận chiến giữa Terrorcons và phe cánh Predacons. Bên cạnh đó, Optimus cũng phải đương đầu với trận chiến truyền kiếp giữa Autobots và Decepticons. Ngoài ra, Optimus còn phải đối đấu với Scourge - kẻ đứng đầu Terrorcons và có sở thích săn lùng các Autobots lẫn Maximal.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Anthony Ramos","avatar":""},{"name":"Dominique Fishback","avatar":""},{"name":"Peter Cullen","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Pete Davidson","avatar":""},{"name":"Liza Koshy","avatar":""},{"name":"Cristo Fernández","avatar":""},{"name":"Luna Lauren Velez","avatar":""},{"name":"Dean Scott Vazquez","avatar":""},{"name":"Tobe Nwigwe","avatar":""},{"name":"Sarah Stiles","avatar":""},{"name":"Leni Parker","avatar":""},{"name":"Frank Marrs","avatar":""},{"name":"Aidan Devine","avatar":""},{"name":"Kerwin Jack","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Transformers 7","트랜스포머 7","ทรานส์ฟอร์เมอร์ส : กำเนิดจักรกลอสูร","Robot Đại Chiến: Quái Thú Trỗi Dậy","變形金剛：萬獸崛起","變形金剛：狂獸崛起","变形金刚：超能勇士崛起","Transformers: Canavarların Yüksəlişi","Transformers - Petojen Nousu","變形金剛7：狂獸崛起","Transformers: Η εξέγερση των θηρίων","Transformers 6 - Aufstieg der Bestien","Transformers - Le réveil des Bêtes","Трансформеры 7","Трансформеры Ребут 2","变形金刚：狂兽崛起","Transformers 6 : Rise of the Beasts","变形金刚6：万兽崛起","Transformers: Canavarların Yükselişi","Transformers: Rise of the Beasts"]', 1784690324248);
