INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('transformers-quai-thu-troi-day', 'Transformers: Quái Thú Trỗi Dậy', 'Transformers: Rise of the Beasts', 'transformers: quái thú trỗi dậy transformers: rise of the beasts anthony ramos dominique fishback peter cullen ron perlman peter dinklage michelle yeoh pete davidson liza koshy cristo fernández luna lauren velez dean scott vazquez tobe nwigwe sarah stiles leni parker frank marrs aidan devine kerwin jack transformers 7 트랜스포머 7 ทรานส์ฟอร์เมอร์ส : กำเนิดจักรกลอสูร robot đại chiến: quái thú trỗi dậy 變形金剛：萬獸崛起 變形金剛：狂獸崛起 变形金刚：超能勇士崛起 transformers: canavarların yüksəlişi transformers - petojen nousu 變形金剛7：狂獸崛起 transformers: η εξέγερση των θηρίων transformers 6 - aufstieg der bestien transformers - le réveil des bêtes трансформеры 7 трансформеры ребут 2 变形金刚：狂兽崛起 transformers 6 : rise of the beasts 变形金刚6：万兽崛起 transformers: canavarların yükselişi transformers: rise of the beasts', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-thuc-tu-than', 'Nghi Thức Tử Thần', 'The Ritual Killer', 'https://phimimg.com/upload/vod/20250325-1/a7adc0fddd8c29832ecd443a6cf2ea32.jpg', 'https://phimimg.com/upload/vod/20250325-1/4a692f2bb11f9242cb9a8bfb1e81556a.jpg', '<p>Một thám tử (Cole Hauser thủ vai) săn lùng một kẻ giết người quốc tế thực hiện những vụ án giết người theo nghi lễ ở một thị trấn nhỏ ở Mississippi. Anh ta tìm kiếm sự giúp đỡ từ một giáo sư nhân chủng học (Morgan Freeman thủ vai), người là chuyên gia về các nghi lễ cổ đại đang được thực hiện.</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Vernon Davis","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Giuseppe Zeno","avatar":""},{"name":"Murielle Hilaire","avatar":""},{"name":"Luke Stratte-McClure","avatar":""},{"name":"Brian Kurlander","avatar":""},{"name":"Julie Lott","avatar":""},{"name":"Destiny Loren","avatar":""},{"name":"Virginia Dru Bramblett","avatar":""},{"name":"Paul Sampson","avatar":""},{"name":"Ron Goleman","avatar":""},{"name":"Lara Pictet","avatar":""},{"name":"Giuseppe Zeno","avatar":""},{"name":"Mayumi Roller","avatar":""},{"name":"Tal","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Muti","Rituel meurtrier","Death by ritual","Muti - The Ritual Killer","قاتل آیینی","무티: 주술 살인","ブラッド・チェイサー 呪術捜査線","The Ritual Killer"]', 1784690324248);
