INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-so-trai-dat-hang-hai-cot', 'Ẩn Số Trái Đất: Hang Hài Cốt', 'Unknown: Cave of Bones', 'https://phimimg.com/upload/vod/20250325-1/b5a7a6892366500ab1ea84b447a0e23b.jpg', 'https://phimimg.com/upload/vod/20250325-1/9d41a07e1ced2c0bfa4bcf2d41f9da7d.jpg', '<p>Các nhà khoa học xem xét những manh mối dưới lòng đất từ hơn 250.000 năm trước, đặt ra câu hỏi về những người họ hàng đầu tiên của chúng ta và ý nghĩa thực sự của việc làm người.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lee Berger","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Det ukjente: Knokkelhulen","Unknown: Cave of Bones"]', 1784690324248);
