INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-tam', 'Hộ Tâm', 'Back From The Brink', 'https://phimimg.com/upload/vod/20240418-1/1d9774b9bcd729b62de36c4884f9118c.jpg', 'https://phimimg.com/upload/vod/20240418-1/d060838ac5eeba80c1d642e4f1b699c4.jpg', '<p>Yêu long ngàn năm Thiên Diệu bị chính người con gái mình yêu phản bội, thân xác phân tán nhiều nơi. May mắn thay, linh hồn của Thiên Diệu kịp trốn thoát. Còn vảy hộ tâm của chàng thì bay đến sông Hắc Hà, vô tình cứu sống đứa bé sơ sinh Nhạn Hồi có khiếm khuyết bẩm sinh ở tim. Nhiều năm sau, Thiên Diệu nay đã tái sinh gặp được Nhạn Hồi và nhận ra nàng chính là hy vọng giúp mình lấy lại thân xác cũ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hầu Minh Hạo","avatar":""},{"name":"Châu Dã","avatar":""},{"name":"Dương Dung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324248);
