INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-khach-san-2023', 'Bóng Ma Khách Sạn', 'The Haunted Hotel', 'https://phimimg.com/upload/vod/20240918-1/a5c1308b7face707527f78e2d4776cbe.jpg', 'https://phimimg.com/upload/vod/20240918-1/6c7f26274c1dad582c25a6a4a4f83db3.jpg', '<p>Hai chị em tới Semarang để giúp quản lý một khách sạn bí ẩn. Tại đó, họ tình cờ chạm trán với một bí mật đen tối và một lời nguyền đầy chết chóc.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Luna Maya","avatar":""},{"name":"Christian Sugiono","avatar":""},{"name":"Bianca Hello","avatar":""},{"name":"Egy Fedly","avatar":""},{"name":"Firstriana Aldila","avatar":""},{"name":"Rafael Adwel","avatar":""},{"name":"Budi Ros","avatar":""},{"name":"Oce Permatasari","avatar":""},{"name":"Landung Simatupang","avatar":""},{"name":"Ivonne Dahler","avatar":""},{"name":"Ernanta Kusuma","avatar":""},{"name":"Hami Diah","avatar":""},{"name":"Neysa Chandria","avatar":""},{"name":"Willem Bevers","avatar":""},{"name":"Alleyra Fakhira","avatar":""},{"name":"Syalshabilla Aldian","avatar":""},{"name":"Bu Joko","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Haunted Place","Panggonan Wingit"]', 1784690324248);
