INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-an-cho-em', 'Bình An Cho Em', 'Post Truth', 'https://phimimg.com/upload/vod/20250324-1/b61faeb1293f49b90884955c4086c542.jpg', 'https://phimimg.com/upload/vod/20250324-1/35c4b8267a5827c4c3e87a63cd553885.jpg', '<p>Ngụy Bình An, một người đàn ông trung niên sa cơ lỡ vận, kiếm sống bằng cách livestream bán đất nghĩa trang. Sau khi khách hàng của anh – Hàn Lộ – qua đời, cô bất ngờ bị tung tin đồn thất thiệt và bôi nhọ danh tiếng. Không thể làm ngơ trước bất công, Ngụy Bình An quyết tâm đứng ra minh oan cho cô, không ngại ngược xuôi để vạch trần sự thật. Thế nhưng, chính anh cũng dần bị cuốn vào vòng xoáy của những lời đồn ác ý và bạo lực mạng.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dong Chengpeng","avatar":""},{"name":"Li Xueqin","avatar":""},{"name":"Yin Zheng","avatar":""},{"name":"Wang Xun","avatar":""},{"name":"Wang Shengdi","avatar":""},{"name":"Ma Li","avatar":""},{"name":"Victoria Song","avatar":""},{"name":"Bai Yu","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Yang Di","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Ni Hongjie","avatar":""},{"name":"Qiao Shan","avatar":""},{"name":"Yu Yang","avatar":""},{"name":"Liu Jinshan","avatar":""},{"name":"Cao Bingkun","avatar":""},{"name":"Liang Chao","avatar":""},{"name":"Zhang Lin","avatar":""},{"name":"Deng Fei","avatar":""},{"name":"Ye Tian","avatar":""},{"name":"Zhang Waner","avatar":""},{"name":"Chanart","avatar":""},{"name":"Wu Haoche","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b4