INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-vong', 'Tiễn Vong', 'The Undertaker', 'https://phimimg.com/upload/vod/20241222-1/d554bfe95f3b75f76fd80e54e3a5ca70.jpg', 'https://phimimg.com/upload/vod/20241222-1/b445f249bab10497d2c747723bd949c2.jpg', '<p>Joed sau khi tốt nghiệp trường Luật bỗng nhận hung tin rằng người cha của anh mắc bệnh nan y cũng là lúc anh đối diện với nỗi ám ảnh kế nghiệp nghề gia truyền - thay cha trở thành một Người Trục Vong hay còn được biết đến với tên gọi là Nghề Mai Táng theo các phong tục tâm linh mà một người thường không thể mường tượng nổi. Ngoài công việc cơ bản như xử lý x.á.c ch.ết tưởng chừng quá đủ với một người có nỗi ám ảnh lớn với m*a quỷ như Joed thì chuỗi phong tục từ gọi hồn để giao tiếp với người đã khuất cho đến nghi lễ “du hành&nbsp; linh hồn” để triệu hồi vong hồn về cõi âm,... khiến cú sang chấn của chàng trai trẻ vượt qua cực hạn.&nbsp; “Bài thực hành” đầu tiên của Joed nhanh chóng được bắt đầu sau vụ t.ự t.ử của một thai phụ trẻ làm dậy sóng cả làng. Bằng nỗ lực tìm ra lý do vong hồn của cô gái trẻ xấu số chưa thể siêu thoát, diễn biến của bộ phim Tiễn Vong gây rùng mình bởi những màn thực hiện nghi thức nhập hồn và cách mai táng đậm chất văn hoá Thái Lan dưới góc nhìn ma mị siêu thực được gài gắm nhiều thông điệp về ranh giới âm - dương và truyền tải các tầng ý nghĩa sâu xa của Châu Á về quan niệm thế giới bên kia đã thực sự tồn tại như thế nào?</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Chatchai Chinsi","avatar":""},{"name":"Naruepol Yaiim","avatar":""},{"name":"Archariya Sritha","avatar":""},{"name":"Sutida Buatig","avatar":""},{"name":"Natthawut Saenyabut","avatar":""},{"name":"Thanadon Buarabat","avatar":""},{"name":"Chompumat Phongsangam","avatar":""},{"name":"Naraphat Ngodngam","avatar":""},{"name":"Somchai Saiutha","avatar":""},{"name":"Phuwanet Seechomphu","avatar":""},{"name":"Khamtun Jindamol","avatar":""},{"name":"Boonthao Kanyaphila","avatar":""},{"name":"Phatchaniya Thanalad","avatar":""},{"name":"Tiparom","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Sup Pa Ror","ไทบ้านเดอะซีรี่ส์: สัปเหร่อ","The Undertaker","สัปเหร่อ"]', 1784690324249);
