INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-thap-luc-ky', 'Tam Thập Lục Kỵ', 'Thirty Six Cavalry', 'https://phimimg.com/upload/vod/20250319-1/b691cb3f6fc1fdaa1f383f33b14fda23.jpg', 'https://phimimg.com/upload/vod/20250319-1/666ae41cc3af15ba9968d595213c47f8.jpg', '<p>Câu chuyện xảy ra vào thời Hán Minh đế, vì chuyện huynh trưởng gánh tội thay cha mà huynh muội Ban Siêu, Ban Chiêu đi đến Lạc Dương. Ở nơi đó, Ban Siêu dùng mưu trí cứu huynh trưởng đại náo đài Du Dã, cuối cùng nhận yến phù của Hán Minh đế chuẩn bị đi sứ Tây Vực. Ban Siêu tập hợp người tài ba dị sĩ lập thành đoàn đi về phía tây, đồn thời triển khai trận chiến thành Y Ngô. Sau đó, tam thập lục kỵ chia cách đại quân Đậu Cố ở Y Ngô, quân hán hướng về phía bắc công thành phá trại, tam thập lục kỵ hướng về phía nam phạt giao phạt mưu.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Thirty-six Cavalry","三十六騎","36 Riders","Tam Thập Lục Kỵ","三十六骑"]', 1784690324249);
