INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-huy-diet-phan-3', 'Sự Hủy Diệt (Phần 3)', 'Star Trek: Picard (Season 3)', 'https://phimimg.com/upload/vod/20240305-1/2fa3fd501c20acc9890e072f9b154bc9.jpg', 'https://phimimg.com/upload/vod/20240305-1/89a07922d89e3a55b213810983ee7e7b.jpg', '<p>Trong phần ba, một thông điệp tuyệt vọng từ một người bạn đã mất từ lâu đã lôi kéo Đô đốc huyền thoại Starfleet Jean-Luc Picard tham gia vào nhiệm vụ táo bạo nhất trong đời anh ta, buộc anh ta phải chiêu mộ các đồng minh trải dài từ nhiều thế hệ cũ và mới. Cuộc phiêu lưu cuối cùng này đưa anh ta vào một quá trình va chạm với di sản của quá khứ và những khám phá mới, bùng nổ của anh ta sẽ thay đổi số phận của Liên bang mãi mãi.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Stewart","avatar":""},{"name":"Jeri Ryan","avatar":""},{"name":"Michelle Hurd","avatar":""},{"name":"Ed Speleers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324249);
