INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-anh-truy-kich', 'Điệp Ảnh Truy Kích', 'Dead Ringer', 'https://phimimg.com/upload/vod/20240324-1/0c2d96668e9d245bf01e3fc437ff474a.jpg', 'https://phimimg.com/upload/vod/20240324-1/78786dfb84ff604f64f1a82fbec45ca7.jpg', '<p>Trong lúc triệt phá một vụ án buôn người, Ngụy Hiểu Thần phát hiện thi thể của người em gái song sinh Lương Hy đã thất lạc từ lâu. Với sự hỗ trợ của các đặc cảnh đồng nghiệp, Hiểu Thần lấy thân phận của Lương Hy từ Singapore đến Hồng Kông để âm thầm điều tra những người từng ở bên cạnh em mình. Thật giả khó phân, chính tà bất định, Hiểu Thần sẽ làm thế nào để đưa sự thật ra ánh sáng?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2023, 'Vietsub + Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Tú Na","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Huỳnh Hạo Nhiên","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324249);
