INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-ho-1001', 'Căn Hộ 1001', 'A Thousand and One', 'https://phimimg.com/upload/vod/20250317-1/aead24a2f2ab933d3273681eb321b7a3.jpg', 'https://phimimg.com/upload/vod/20250317-1/a5fd9bff2a31efabf313072ccde4f4a2.jpg', '<p>Đang vật lộn nhưng luôn sống theo cách riêng, Inez chuyển từ nơi trú ẩn này sang nơi trú ẩn khác tại thành phố New York giữa thập niên 90. Với con trai 6 tuổi của mình, Terry, đang được chăm sóc trong hệ thống nuôi dưỡng và cô không thể chấp nhận việc phải xa cách cậu, cô đã bắt cóc cậu để họ có thể cùng nhau xây dựng cuộc sống. Theo thời gian, gia đình họ dần mở rộng và Terry trở thành một thiếu niên thông minh nhưng trầm lặng, nhưng bí mật đã định hình cuộc sống của họ đe dọa phá hủy mái ấm mà họ đã xây dựng một cách khó tin.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Teyana Taylor","avatar":""},{"name":"William Catlett","avatar":""},{"name":"Josiah Cross","avatar":""},{"name":"Aven Courtney","avatar":""},{"name":"Aaron Kingsley Adetola","avatar":""},{"name":"Terri Abney","avatar":""},{"name":"Delissa Reynolds","avatar":""},{"name":"Amelia Workman","avatar":""},{"name":"Adriane Lenox","avatar":""},{"name":"Mark Gessner","avatar":""},{"name":"Gavin Schlosser","avatar":""},{"name":"Jolly Swag","avatar":""},{"name":"Azza El","avatar":""},{"name":"Alicia Pilgrim","avatar":""},{"name":"Jennean Farmer","avatar":""},{"name":"Kal-El White","avatar":""},{"name":"Jamier Wil","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["1001","Mille et un","Mil Uno","Mil e Um","一千零一种","A Thousand and One"]', 1784690324249);
