INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-anh-em-cua-gia-dinh-yuzuki', 'Bốn Anh Em Của Gia Đình Yuzuki', 'The Yuzuki Family''s Four Sons', 'https://phimimg.com/upload/vod/20250316-1/224a02b3e369b792f336ee5e12af53c9.jpg', 'https://phimimg.com/upload/vod/20250316-1/59ed2aca783335b07410a1be09e793d1.jpg', '<p>Gia đình Yuzuki gồm có bốn anh em, cha mẹ đã mất cách đây hai năm. Hayato, con trai cả, là một người chăm chỉ và là trụ cột của gia đình. Mikoto, con trai thứ hai, điềm tĩnh và tự chủ, nhưng lại có cảm tình với em trai Minato, người mà anh yêu quý và cho là dễ thương. Minato, con trai thứ ba, năng nổ và yêu quý các anh trai của mình nhưng lại vụng về và vụng về. Gakuto, con trai thứ tư, là một học sinh lớp một hiếu học và trưởng thành, thường được gọi là &quot;nhà thông thái&quot;.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryota Iwasaki","avatar":""},{"name":"Kikunosuke Toya","avatar":""},{"name":"Miyuki Sakurai","avatar":""},{"name":"Momoka Terasawa","avatar":""},{"name":"Misato Matsuoka","avatar":""},{"name":"Akari Tadano","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Satsuki Kokubu","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Os Quatro Irmãos da Família Yuzuki","Os Quatro Irmãos Yuzuki","Yuzuki-san Chi no Yon Kyoudai.","Yuzuki-san Chi no Yon Kyōdai.","Yuzuki-san Chi no Yonkyōdai","Yuzuki-san Chi no Yonkyoudai","YuzuAni","유즈키네 사형제","The Four Brothers of the Yuzuki Household","Youth Story of a Family","柚木さんちの四兄弟。"]', 178