INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rahsia-bi-mat', 'Rahsia: Bí Mật', 'Rahsia', 'https://phimimg.com/upload/vod/20250315-1/000357e7f80bc90b19f4d22fdb5a8582.jpg', 'https://phimimg.com/upload/vod/20250315-1/0e6037e4de91b134152f765668ff8950.jpg', '<p>Trong bản làm lại đầy kịch tính này, người mẹ nọ dần suy sụp sau khi con trai cô biến mất một cách khó hiểu và cô tin rằng một linh hồn báo thù đã bắt cóc cậu bé.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Nabila Huda","avatar":""},{"name":"Fikry Ibrahim","avatar":""},{"name":"Eman Manan","avatar":""},{"name":"Marsha Milan Londoh","avatar":""},{"name":"Rashidi Ishak","avatar":""},{"name":"Nur Qistina Raisah","avatar":""},{"name":"Syed Ali Murtadha","avatar":""},{"name":"Susan Lankester","avatar":""},{"name":"Mislina Mustaffa","avatar":""},{"name":"Aloy Paradoks","avatar":""},{"name":"Iman Corinne Adrienne","avatar":""},{"name":"Othman Hafsham","avatar":""},{"name":"Nu''Man Bin Mohd Salleh","avatar":""},{"name":"Nabil Zakaria","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rahsia"]', 1784690324249);
