INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kien-quai', 'Kiến Quái', 'Detrimental', 'https://phimimg.com/upload/vod/20250315-1/34ac9419a662fbae2dec1758c953d632.jpg', 'https://phimimg.com/upload/vod/20250315-1/d9924561e5ec81dd6fd7fd5abd3df3a5.jpg', '<p>Năm 2070, một công nhân mù mắc kẹt trên hòn đảo bị bão tàn phá. Vậy là anh phải một mình sống sót và trốn tránh đám quái vật ẩn nấp trong bóng tối.</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vincent Wong Ho-Shun","avatar":""},{"name":"Kenneth Chan","avatar":""},{"name":"Tony Wu","avatar":""},{"name":"Thor Lok","avatar":""},{"name":"Max Cheung Tat-Lun","avatar":""},{"name":"Shirley Chan Yan-Yin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["見怪","见怪"]', 1784690324249);
