INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kien-quai', 'Kiến Quái', 'Detrimental', 'kiến quái detrimental vincent wong ho-shun kenneth chan tony wu thor lok max cheung tat-lun shirley chan yan-yin 見怪 见怪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-bai-the-than', 'Vương Bài Thế Thân', 'Super Daddy', 'https://phimimg.com/upload/vod/20250313-1/662b8d43e1216e059de36fed2cf8b8bc.jpg', 'https://phimimg.com/upload/vod/20230919-1/aa462744467558d5d4b472ae1888829a.jpg', '<p>Vương Tử một người có ước mơ trở thành diễn viên đã bước vào tuổi trung niên nhưng sự nghiệp vẫn không tiến triển mặc dù có kỹ năng võ thuật, vợ anh là Mễ Thiến sắp tái hôn với doanh nhân giàu có Cao Dương cùng con gái nhỏ Tiểu Khả ra nước ngoài.Trong một lần tình cờ, Vương Tử nhận được công việc biểu diễn trong cuộc họp báo giới thiệu công nghệ &quot;Ngoại xương&quot; mà Cao Dương tổ chức. Tuy nhiên, tại buổi tập kịch bản, anh đã chứng kiến Tiểu Khả bị một người bắt cóc. Ban đầu, &quot;Ngoại xương&quot; là sáng chế của bạn đồng hành của Cao Dương là Bảo Ca, nhưng sau đó bị Cao Dương lấy trái phép và sở hữu. Để vạch trần sự thật về Cao Dương, Bảo Ca quyết định giành lại công trình nghiên cứu mà anh tạo ra, nhưng không ngờ bộ điều khiển lại được giấu trong người Tiểu Khả nên anh ta chỉ có cách đưa Tiểu Khả về phòng thí nghiệm của mình. Vương Tử và Mễ Thiến đã hợp lực khi họ nhận thấy tình hình và bắt đầu hành trình giải cứu Tiểu Khả. Sau một cuộc truy đuổi đầy căng thẳng trên đường, Vương Tử đã đến phòng thí nghiệm của Bảo Ca và biết được sự thật về mọi chuyện. Anh quyết định hợp tác với Bảo Ca để vạch trần danh tính thật của Cao Dương. Cuối cùng, thông qua sự hợp tác hoàn hảo giữa võ thuật và công nghệ, cũng như giữa Vương Tử và Mễ Thiến, họ đã thành công vạch trần âm mưu của Cao Dương. Trong quá trình này, cặp đôi Vương Tử và Mễ Thiến cũng đã xóa bỏ được hiểu lầm và xa cách trong nhiều năm qua.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Sammy Hung","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Kimmy Tong Fei","avatar":""},{"name":"Sun Yue","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324249);
