INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ma-thon-hoang-mieu', 'Chuyện Ma Thôn Hoàng Miếu', 'Huang Miao Village''s Tales Of Mystery', 'https://phimimg.com/upload/vod/20250313-1/ecf27f531e8b059581b34744bf46fd74.jpg', 'https://phimimg.com/upload/vod/20250313-1/da9abf5031769d6121977893e6fb04d5.jpg', '<p>Sư đồ Cửu thúc trên đường hành y cứu thế, trong đêm khuya đi nhầm vào thôn Hoàng Miếu, tình cờ gặp phú hộ nhà họ Hoàng đang đưa tang, ai ngờ đêm đó cô dâu ma lại báo mộng cho tên đồ đệ là Trường Canh đi tìm bài vị, Cửu thúc bấm tay tính toán nhận thấy chuyện này khá kỳ lạ, trong quá trình sư đồ Cửu thúc điều tra án mạng nhà họ Hoàng, Thuý Cô răng hô cứ xuất hiện gây rối, hai người đấu trí đọ sức, chuyện hài hước xảy ra không ngừng, cùng với việc vạch trần sự thật về cái chết của Hoàng phu nhân, cuộc đấu thật sự cũng theo đó bắt đầu...</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ge Shuai","avatar":""},{"name":"Fan Zhengjun","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Chen Yuanyuan","avatar":""},{"name":"Wang Gang","avatar":""},{"name":"Zhen Zhang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Huang Miao Village''s Tales of Mystery","The Strange Story of Huangmiao Village","Huang Miao Villages Tales of Mystery","黄庙村怪谈"]', 1784690324249);
