INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-ho-tinh-duyen', 'Bạch Hồ: Tình Duyên', 'White Fox', 'https://phimimg.com/upload/vod/20250313-1/88fe467a6a6abb4ae17d78983eaa6256.jpg', 'https://phimimg.com/upload/vod/20231013-1/b10fdb49f5aec5fc0529895c4c5f9f03.jpg', '<p>Bộ phim kể về câu chuyện của một kỷ nguyên trên cao đầy quỷ, nơi một phù thủy trẻ gặp một con cáo mất trí nhớ banshee, một người và một con quỷ trải nghiệm tình yêu và thù hận trong một cuộc phiêu lưu giả tưởng, và cuối cùng hợp lực để ngăn chặn âm mưu hủy diệt thế giới với sự giúp đỡ của kiếm sĩ Thục Sơn, nhưng kể từ đó câu chuyện về người chuyển giới mãi mãi.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Giang Khai Tông","avatar":""},{"name":"Chen Yelin","avatar":""},{"name":"Li Mengmeng","avatar":""},{"name":"Wang Guan","avatar":""},{"name":"Gao Shuyao","avatar":""},{"name":"Diệp Tương Minh","avatar":""},{"name":"Thượng Tư Kỳ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324249);
