INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('100-dieu-toi-muon-lam-truoc-khi-tro-thanh-xac-song', '100 Điều Tôi Muốn Làm Trước Khi Trở Thành Xác Sống', 'Zom 100: Bucket List Of The Dead', '100 điều tôi muốn làm trước khi trở thành xác sống zom 100: bucket list of the dead shuichiro umeda tomori kusunoki makoto furukawa minami takahashi 僵尸100～变成僵尸之前想做的100件事～ 僵尸100～变成僵尸前想要完成的100件事～ 僵尸 100～在成为僵尸前要做的 100 件事～ 僵尸百分百～变成僵尸前想做的100件事～ zom 100: zombie ni naru made ni shitai 100 no koto zom 100 зомби-апокалипсис и сто предсмертных дел зомби-апокалипсис и список из ста дел, что я выполню перед смертью предсмертный список зомби зомби-апокалипсис и 100 предсмертных дел зомбиапокалипсис и список из 100 дел, что я выполню перед смертью ซอม 100: 100 สิ่งที่อยากทำก่อนจะกลายเป็นซอมบี้ ซอม 100～100 สิ่งที่อยากทำก่อนจะกลายเป็นซอมบี้～ 殭屍100～在成為殭屍前要做的100件事～ 殭屍 100～在成為殭屍前要做的 100 件事～ zom 100: список справ майбутнього зомбі зом 100: передсмертний список мерця zom 100 - bucket list of the dead 100 điều tôi sẽ làm trước khi trở thành zombie ゾン100～ゾンビになるまでにしたい100のこと～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-tap-lam-bo', 'Sát Thủ Tập Làm Bố', 'Buddy Daddies', 'https://phimimg.com/upload/vod/20250312-1/6fc51bcba4d955f9c48af092e98e0619.jpg', 'https://phimimg.com/upload/vod/20250312-1/76bab129b5586672863c0137c7357d66.jpg', '<p>Buddy Daddies xoay quanh một gia đình ba người hoàn toàn chẳng có máu mủ gì với nhau: Kazuki Kurusu và Rei Suwa, những sát thủ sống chung dưới một mái nhà và Miri, con gái của mục tiêu ám sát của Kazuki và Rei, cô bé cuối cùng được Kazuki, người mà cô bé nghĩ là cha ruột, nhặt về.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiyuki Toyonaga","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Hina Kino","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Mitsuaki Madono","avatar":""},{"name":"Nanako Mori","avatar":""},{"name":"Haruka Terui","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Shinshu Fuji","avatar":""},{"name":"Hiroyuki Kinoshita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["მეგობარი მამიკოები","BUDDY DADDIES","バディ·ダディズ","Family Story of Two Killers and a Girl","Buddy Daddies"]', 1784690324249);
