INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phung-chi-sung-quan', 'Phụng Chỉ Sủng Quân', 'Kill You Love You', 'https://phimimg.com/upload/vod/20230914-1/df8887253d4280c805e6243ab9f27412.jpg', 'https://phimimg.com/upload/vod/20230914-1/4eb17f7404f42e8b60d1f49af2de4855.jpg', '<p>Kiếm khách Tô Thiện Linh của Tứ Phương Hội nhận nhiệm vụ ám sát thành chủ Lạc Dịch – Đông Phương Cảnh. <span style="text-wrap-mode: wrap;">Tô Thiện&nbsp;</span>Linh trà trộn vào cung, không chỉ ám sát bất thành mà còn được Cảnh cứu. Sau đó, <span style="text-wrap-mode: wrap;">Tô Thiện&nbsp;</span>Linh mới biết cô nhầm lẫn, nhiệm vụ của cô là bảo vệ Đông Phương Cảnh. Sau nhiều lần sinh tử có nhau, cả hai rung động trước đối phương. Tuy nhiên, Tô Thiện Linh vô tình phát hiện thân thế của mình, cả tộc Phụng Minh của cô bị tiêu diệt bởi phụ thân của Đông Phương Cảnh vào 18 năm trước. Giữa một bên là tình, một bên là nghĩa, <span style="text-wrap-mode: wrap;">Tô Thiện&nbsp;</span>Linh sẽ lựa chọn ra sao?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Lệ Lam","avatar":""},{"name":"Lý Nhược Thiên","avatar":""},{"name":"Hàn Trữ Cáp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324249);
