INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-bat-ngu-da-hanh-lang', 'Tử Bất Ngữ: Dạ Hành Lang', 'Dead Slience', 'https://phimimg.com/upload/vod/20240228-1/da3c2fd3278b7e38fe17ba2213bb915f.jpg', 'https://phimimg.com/upload/vod/20240228-1/df9490c2fc652a93a2e5b2a732f5c9f4.jpg', '<p>Trong một thế giới đầy kỳ quái và bí ẩn, Lục Lệ - một người thợ rèn nhỏ - bị cuộc sống đưa đẩy vào vận mệnh khó đoán. Sau cái chết đột ngột của vợ mới cưới, anh bỏ lại quê hương và tình cờ trở thành một người lính đêm được mọi người kính trọng. Bảy năm sau, khi Lục Lệ trở về quê hương, anh không chỉ tiêu diệt con quỷ huyền thoại gây hạn hán, thiếu nước, mà còn phát hiện ra rằng cái chết của vợ anh ẩn chứa một âm mưu lớn hơn ngoài sức tưởng tượng.Tuy nhiên, trong quá trình tìm hiểu sự thật về cái chết của người vợ, một người phụ nữ khác đã hy sinh để bảo vệ Lục Lệ. Với nỗi thù cũ và mới đan xen, Lục Lệ hét lên: Tôi không muốn làm một người lính đêm nữa! Vậy, anh sẽ lựa chọn đi đâu trong tương lai?</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Sun Qi Heng","avatar":""},{"name":"Lian Sai","avatar":""},{"name":"Ming Li","avatar":""},{"name":"Shu Yao Xuan","avatar":""},{"name":"Gu Wan Jing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324249);
