INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-sang-cho-em', 'Soi Sáng Cho Em', 'A Date With The Future', 'https://phimimg.com/upload/vod/20240305-1/df8be4d559bb157875c24490e8ac7fee.jpg', 'https://phimimg.com/upload/vod/20240305-1/3494b05d12aace1790d4f42372cdf89c.jpg', '<p>Mười năm trước, Xu Lai bị mắc kẹt trong trận động đất và được cứu bởi lính cứu hỏa, Jin Shichuan và chú chó tìm kiếm và cứu hộ, Zhuifeng. Để xoa dịu Từ Lai bị thương, Kim Thập Xuyên hứa hẹn bổ nhiệm cô mười năm. Mười năm sau, Xu Lai trở về Trung Quốc để trở thành một phóng viên và một người huấn luyện chó quốc tế. Anh gặp Jin Shichuan tại địa điểm giải cứu. Kim Thập Xuyên không những không nhận ra Từ Lai mà còn hiểu lầm cô là một phóng viên vô đạo đức. Xu Lai đã sửa lại tên của đội cứu hộ bất chấp sự hiểu lầm. Khi thành lập đội chó tìm kiếm và cứu hộ, Xu Lai trở thành đối tác của Jinshichuan với tư cách là một người huấn luyện chó quốc tế, chinh phục người dân bằng kỹ năng chuyên môn xuất sắc và trao chú chó cứu hộ Pingan của mình cho Jin Shichuan. Là nhà báo và lính cứu hỏa, họ luôn gặp nhau ở tuyến đầu nguy hiểm. Hai người bọn họ từng bị sinh tử thử thách đã dần dần hâm nóng tình cảm.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Vỹ Đình","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Nhậm Hào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324249);
