INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-khong-the-sanh-duyen', 'Công Tử Không Thể Sánh Duyên', 'Catch Up My Prince', 'https://phimimg.com/upload/vod/20250305-1/e0f3445f8e01a3ba6c3f10b3d7a4c0bf.jpg', 'https://phimimg.com/upload/vod/20250305-1/4ef8ad6629fbe2ef8ac4257246e0cb79.jpg', '<p>Bác sĩ thực tập Lục Nhiễm Nhiễm bước vào thế giới ảo của một trò chơi tương tác trí não nhập vai đang trong giai đoạn thử nghiệm. Trong lúc làm nhiệm vụ, cô gặp gỡ và kết giao cùng Tứ hoàng tử Triệu Thần Dật. Trải qua muôn vàn thử thách sinh tử, hai người nảy sinh tình yêu chân thành. Về sau, Nhiễm Nhiễm biết được Thần Dật vốn là nhà sáng tạo trò chơi nhưng bị mất ý thức. Để đánh thức anh trở về thế giới hiện thực, cô một lần nữa bước vào trò chơi.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Nhược Hàm","avatar":""},{"name":"Lưu Dịch Sướng","avatar":""},{"name":"Hạ Ninh Tuấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["这坑爹的穿越游戏","公子不可逑","公子不可求"]', 1784690324249);
