INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goi-hon-quy-du', 'Gọi Hồn Quỷ Dữ', 'Talk to Me', 'https://phimimg.com/upload/vod/20250304-1/ea20fcb74fc2faf2d93dcee79d78d37e.jpg', 'https://phimimg.com/upload/vod/20250304-1/3234c7a9834945c98728b4bd92e2eb72.jpg', '<p>Phim nói về một nhóm bạn phát hiện ra bàn tay ma quái cho phép họ triệu hồi các linh hồn bí ẩn. Họ dần bị cuốn vào trò chơi này mà không biết rằng một trong số họ đã đi quá xa và giải phóng thế lực hắc ám kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Úc', 1, '[{"name":"Sophie Wilde","avatar":""},{"name":"Alexandra Jensen","avatar":""},{"name":"Joe Bird","avatar":""},{"name":"Otis Dhanji","avatar":""},{"name":"Miranda Otto","avatar":""},{"name":"Zoe Terakes","avatar":""},{"name":"Chris Alosio","avatar":""},{"name":"Marcus Johnson","avatar":""},{"name":"Alexandria Steffensen","avatar":""},{"name":"Ari McCarthy","avatar":""},{"name":"Sunny Johnson","avatar":""},{"name":"James Oliver","avatar":""},{"name":"Cass Cumerford","avatar":""},{"name":"Jett Gazley","avatar":""},{"name":"Kitt Erhart-Bruce","avatar":""},{"name":"Hamish Phillips","avatar":""},{"name":"Kidaan Zelle","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["鬼手鬼手 請開口","Nagga''ta Nirtzakhta","TALK TO ME／トーク・トゥ・ミー","トーク・トゥ・ミー","Два, три, демон, приди!","Mluv se mnou!","Háblame","Talk to Me","Govori z mano"]', 1784690324249);
