INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-nhung', 'Hoa Nhung', 'Beauty Of Resilience', 'https://phimimg.com/upload/vod/20240307-1/a9d1e734fdbb4555333f49d735286f74.jpg', 'https://phimimg.com/upload/vod/20240307-1/2faee11c71fa5bca5bcb7d9e00f165cb.jpg', '<p>Từ bé đã bị xem như sao chổi, Ngụy Chi quyết tâm tham gia buổi kiểm tra tiên cốt với hy vọng được tu tiên. Khi kính Giám Tiên quét qua chỗ nàng, hình ảnh của thần thú Phượng Hoàng đã mai danh ẩn tích từ lâu lóe lên. Thế là Ngụy Chi cùng những người đứng xung quanh cùng được đưa vào thư viện Bạch Lộ để học tập. Tại đây, Ngụy Chi gặp sư phụ Viêm Việt, một thiên quân được thượng giới cử xuống để tìm người kế thừa huyết mạch của Phượng Hoàng.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cúc Tịnh Y","avatar":""},{"name":"Quách Tuấn Thần","avatar":""},{"name":"Lưu Đông Thấm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324249);
