INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-bang-gia-va-nang-lanh-lung', 'Chàng Băng Giá Và Nàng Lạnh Lùng', 'The Ice Guy And His Cool Female Colleague', 'https://phimimg.com/upload/vod/20250301-1/7320ed535e3cc9b5f00b996fdf6e691c.jpg', 'https://phimimg.com/upload/vod/20250301-1/1bea0d9122252cea44ed2a3a7de602f1.jpg', '<p>Himuro là một nhân viên văn phòng thuộc chủng tộc siêu nhiên với sức mạnh kỳ lạ. Bất cứ khi nào anh ấy tập trung cao độ, anh ấy vô thức đẩy những người đồng nghiệp tội nghiệp của mình vào một màn trình diễn gần gũi của Bắc Cực. Mặc dù vậy, Himuro là một người ấm áp và tốt bụng.

Himuro có thiện cảm với đồng nghiệp Fuyutsuki, một người phụ nữ điềm tĩnh, có sở trường đưa ra những giải pháp đơn giản cho những vấn đề khác thường của anh.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yui Ishikawa","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Yumi Uchiyama","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Shugo Nakamura","avatar":""},{"name":"Hiyori Nitta","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["冰屬性男子與無表情女子","冰属性男子和酷酷女同事","冰属性男子与酷酷女同事","Koori Zokusei Danshi to Cool na Douryou Joshi","Kōri Zokusei Danshi to Cool na Dōryō Joshi","氷属性男子とクールな同僚女子"]', 1784690324249);
