INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-mo-mong-la-nguoi-theo-chu-nghia-hien-thuc', 'Chàng Trai Mơ Mộng Là Người Theo Chủ Nghĩa Hiện Thực', 'The Dreaming Boy Is A Realist', 'https://phimimg.com/upload/vod/20250301-1/9627719d4cc249bbfcc35188f5021d3a.jpg', 'https://phimimg.com/upload/vod/20250301-1/52f2d9987a3d6991225141a9c90d26a9.jpg', '<p>Trong câu chuyện &quot;tình yêu đơn phương hai chiều&quot;, cậu học sinh trung học Wataru Sajo đã đem lòng yêu cô bạn cùng lớp xinh đẹp Aika Natsukawa. Aika chỉ xem cậu là một kẻ phiền toái, nhưng cậu vẫn mơ về việc được hẹn hò với Aika và luôn cố gắng tiếp cận cô.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Naoya Miyase","avatar":""},{"name":"Akiho Suzumoto","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Kaori Ishihara","avatar":""},{"name":"Iori Saeki","avatar":""},{"name":"Minami Kurisaka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Yumemiru Danshi ha Genjitsushugisha","Мрійливий хлопець реаліст","The Dreaming Man Is a Realist","夢見る男子は現実主義者"]', 1784690324249);
