INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-mu-quang-phan-4', 'Yêu Là Mù Quáng (Phần 4)', 'Love Is Blind (Season 4)', 'https://phimimg.com/upload/vod/20231219-1/af170e4d30e71f99340ea5bac9b6957b.jpg', 'https://phimimg.com/upload/vod/20231219-1/715b78fc73df47c9265ccce4f34bba09.jpg', '<p>Thêm nhiều người độc thân sẵn sàng coi trọng tình yêu hơn ngoại hình tìm đến các lô để tán tỉnh, yêu đương và nếu may mắn, họ sẽ tìm được đối tượng kết hôn.</p>', 'Hoàn Tất (16/16)', 16, 'tvshows', 'completed', 9, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nick Lachey","avatar":""},{"name":"Vanessa Lachey","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324249);
