INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hmlycp', 'HMLYCP', 'HyeMiLeeYeChaePa', 'https://phimimg.com/upload/vod/20250301-1/874c5b61dccf70a14963f5f8ca77fba4.jpg', 'https://phimimg.com/upload/vod/20250301-1/838f98a385203329fed18db3933fc14d.jpg', '<p>Sáu chị em tràn đầy năng lượng nỗ lực hoàn thành nhiệm vụ để kiếm tiền và sinh tồn trong một ngôi làng hẻo lánh trên núi. Chào mừng đến với ngôi nhà **HyeMiLeeYeChaePa**! Sáu chị em **Hye-ri, Mi-yeon, Lee-jung, Ye-na, Chae-won,** và **Patricia** phải hoàn thành nhiệm vụ để kiếm tiền. Họ cùng chơi game, nhảy múa, ăn uống, ngủ nghỉ và trang trí tổ ấm của mình tại một ngôi làng xa xôi. Mỗi thành viên đều có sức hút riêng, nhưng họ nhanh chóng gắn kết như một gia đình thực sự. Không chỉ mang đến tiếng cười với những khoảnh khắc cạnh tranh căng thẳng, bộ sáu còn thể hiện nhan sắc, tài năng và nét quyến rũ độc đáo của mình trong những trò chơi đầy nhiệt huyết. Hãy cùng chờ đón cuộc sống náo nhiệt của họ, khi những cô gái này biến một ngôi nhà trống không thành tổ ấm trong mơ!</p>', 'Hoàn Tất (12/12)', 12, 'tvshows', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Hye-ri","avatar":""},{"name":"Cho Mi-yeon","avatar":""},{"name":"Leejung Lee","avatar":""},{"name":"Choi Ye-na","avatar":""},{"name":"Kim Chaewon","avatar":""},{"name":"Patricia Thona Yiombi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["惠美李叡采帕","惠美李艺彩派","惠薇李叡采派","HMLYCP","혜미리예채파"]', 1784690324249);
