INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh', 'Giả Định', 'Supposed', 'https://phimimg.com/upload/vod/20250228-1/6aa03d734485b0748daa4a12ea7eaf1e.jpg', 'https://phimimg.com/upload/vod/20250228-1/154429f2de9b3aa5985b6fda2cc45cc8.jpg', '<p>Một người đàn ông trung niên có mối quan hệ với một cô gái trẻ mà anh ta gặp trên mạng với điều kiện cả hai phải tạo danh tính mới và không tiết lộ danh tính khi gặp nhau. Ngày tháng trôi qua, anh ngày càng gắn bó với cô gái hơn và phá vỡ quy tắc, khiến mối quan hệ của họ đi đến một kết cục bất ngờ.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ananda Everingham","avatar":""},{"name":"Chayanit Chansangavej","avatar":""},{"name":"Pratarn Teeratada","avatar":""},{"name":"Paradorn Vesurai","avatar":""},{"name":"Nisachol Siwthaisong","avatar":""},{"name":"Warawan Sinjit","avatar":""},{"name":"Pipattanaphol Pumpo","avatar":""},{"name":"Yanawee Kuptavethin","avatar":""},{"name":"Punada Vosbein","avatar":""},{"name":"Adisak Puang-ok","avatar":""},{"name":"Taddanai Praman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["สมมติ","Suppose"]', 1784690324249);
