INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-sung-cuoi-cung-phan-2', 'Phát Súng Cuối Cùng (Phần 2)', 'Reacher (Season 2)', 'https://phimimg.com/upload/vod/20250227-1/3cb43c61ae7ecb806743a9c3da06f1c7.jpg', 'https://phimimg.com/upload/vod/20250227-1/cd4ac7c32fd2b26d3464d6627f91cc8e.jpg', '<p>Jack Reacher 2022: Phát Súng Cuối Cùng, kể về câu chuyện của Jack Reacher, một cựu cảnh sát hình sự, bị vướng vào một âm mưu vu oan to lớn, được thực hiện bởi một nhóm cảnh sát, doanh nhân lẫn chính trị gia biến chất. Reacher và vợ sẽ phải làm gì để thoát khỏi âm mưu này, nhất là sau cái chết của người anh mình?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alan Ritchson","avatar":""},{"name":"Maria Sten","avatar":""},{"name":"Sonya Cassidy","avatar":""},{"name":"Johnny Berchtold","avatar":""},{"name":"Roberto Montesinos","avatar":""},{"name":"Olivier Richters","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"Anthony Michael Hall","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["烈探雷彻","侠探杰克","ریچر","ジャック・リーチャー 正義のアウトロー","ジャック・リーチャー -正義のアウトロー-","잭 리처","Джек Ричер","แจ็ค รีชเชอร์ ยอดคนสืบระห่ำ","神隱任務","Reacher","Reacher[M]"]', 1784690324249);
