INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-hart-ra-tay', 'Khi Hart Ra Tay', 'Die Hart', 'https://phimimg.com/upload/vod/20250227-1/3199e5e8a3478d057670054f141bf466.jpg', 'https://phimimg.com/upload/vod/20250227-1/061b01049c8b5bb1958295af08229642.jpg', '<p>Kevin Hart - thủ vai một phiên bản của chính anh ta - đang thực hiện nhiệm vụ bất chấp tử thần để trở thành một ngôi sao hành động. Và với một chút trợ giúp từ John Travolta, Nathalie Emmanuel và Josh Hartnett - anh ta có thể thành công hay không?</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""},{"name":"John Travolta","avatar":""},{"name":"Nathalie Emmanuel","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Josh Hartnett","avatar":""},{"name":"Kenneth Trujillo","avatar":""},{"name":"Joshua Lamboy","avatar":""},{"name":"Brandon Quinn","avatar":""},{"name":"Milana Vayntrub","avatar":""},{"name":"Stephan Jones","avatar":""},{"name":"Jason Jones","avatar":""},{"name":"Eric Mainade","avatar":""},{"name":"Haley Dumas","avatar":""},{"name":"Danielle Madison","avatar":""},{"name":"Ronny Mathew","avatar":""},{"name":"Gary Weeks","avatar":""},{"name":"Rahiem Riley","avatar":""},{"name":"Chloe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Die Hart","ฮาร์ต อึดสุดพลัง","Die Hart: The Movie","תמות הארט: הסרט","Die Hart - Il Film","Hart: Duro de entrenar","終極哈特","猫胆虫威","动作巨星","Muere, Hart","动作明星梦"]', 1784690324249);
