INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('true-spirit-hai-trinh-cua-jessica', 'True Spirit: Hải Trình Của Jessica', 'True Spirit', 'https://phimimg.com/upload/vod/20250226-1/bb43af86a06dc9f05cd7da8262a749fc.jpg', 'https://phimimg.com/upload/vod/20250226-1/3e689649b82365590994419d1a3e1ae6.jpg', '<p>Theo đuổi ước mơ và đối mặt với nỗi sợ, một thiếu nữ người Úc ngoan cường quyết tâm trở thành người trẻ nhất đi thuyền một mình vòng quanh thế giới.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Teagan Croft","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Alyla Browne","avatar":""},{"name":"Josh Lawson","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"Bridget Webb","avatar":""},{"name":"Stacy Clausen","avatar":""},{"name":"Todd Lasance","avatar":""},{"name":"Josephine Flynn","avatar":""},{"name":"Alice Tate","avatar":""},{"name":"Ling Cooper Tang","avatar":""},{"name":"Shanyn Asmar","avatar":""},{"name":"Tomoka Tsuyuki","avatar":""},{"name":"Joey Vieira","avatar":""},{"name":"Justin Gerardin","avatar":""},{"name":"Jessica Watson","avatar":""},{"name":"Freya Callaghan","avatar":""},{"name":"Chri","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["ทรู สปิริต","Espíritu libre","逐梦大海","روح شجاعة","True Spirit"]', 1784690324249);
