INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('true-spirit-hai-trinh-cua-jessica', 'True Spirit: Hải Trình Của Jessica', 'True Spirit', 'true spirit: hải trình của jessica true spirit teagan croft cliff curtis alyla browne josh lawson anna paquin bridget webb stacy clausen todd lasance josephine flynn alice tate ling cooper tang shanyn asmar tomoka tsuyuki joey vieira justin gerardin jessica watson freya callaghan chri ทรู สปิริต espíritu libre 逐梦大海 روح شجاعة true spirit', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-matalada', 'Cô Nàng Matalada', 'To The Moon And Back', 'https://phimimg.com/upload/vod/20250224-1/97a64aea964e18acd220257ce5e0217b.jpg', 'https://phimimg.com/upload/vod/20250224-1/1d7298614cd45491456cc5dec0ec7a8f.jpg', '<p>Purim (James Jirayu) là một bác sĩ phẫu thuật não nổi tiếng. Anh sinh ra trong một gia đình danh tiếng và giàu có. Ba anh là một giáo sư kinh tế và mẹ anh là một cựu nữ diễn viên nổi tiếng. Cha anh luôn vạch sẵn con đường cho anh ngay từ khi anh được sinh ra. Purim chưa bao giờ được làm những việc mà mình muốn. Vì vậy, anh quyết định dọn ra ở riêng để có thể làm điều mình thích. Matalada (Toey Jarinporn) là một cô nàng kỳ lạ có phong cách Bohemian. Ba cô là một người đồng tính và là chủ của một quán rượu ở Pattaya. Hồi nhỏ, cô thường bị bạn bè bắt nạt, nhưng bù lại, cô nhận được nhiều tình yêu thương từ đồng nghiệp của ba cô. Ngược lại với ba của Purim, ba của Matalada luôn tôn trọng và cho cô tự do quyền quyết định cuộc đời của mình. Cuộc sống yên bình của Purim kết thúc khi Matalada chuyển đến sống với dì – một ladyboy trong quán rượu và cô trở thành hàng xóm của anh. Những chuyện dở khóc dở cười, hiểu lầm của Matalada về Purim khiến cả hai dần gặp nhau nhiều hơn và xích lại gần nhau.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jarinporn Joonkiat","avatar":""},{"name":"Jirayu Tangsrisuk","avatar":""},{"name":"Amanda Chalisa Obdam","avatar":""},{"name":"Vachirawich Aranthanawong","avatar":""},{"name":"Niti Chaichitathorn","avatar":""},{"name":"Chartayodom Hiranyatithi","avatar":""},{"name":"Noppol Gomarachun","avatar":""},{"name":"Tassawan Seneewongse","avatar":""},{"name":"Kokkorn Benjathikoon","avatar":""},{"name":"Penpetch Benyakul","avatar":""},{"name":"Apinun Prasertwattanakul","avatar":""},{"name":"Arisara Wong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Matalada","มาตาลดา"]', 1784690324249);
