INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-thanh-voi-tinh-yeu', 'Chân Thành Với Tình Yêu', 'True To Love', 'https://phimimg.com/upload/vod/20250224-1/60410e9ed242761fd7b9081a3441a379.jpg', 'https://phimimg.com/upload/vod/20250224-1/ac638f454df079b5afa9f5fab814a004.jpg', '<p>Yeon Bo-Ra (Yoo In-Na) là một nhà văn và cô làm việc dưới bút danh Deborah. Cô ấy là tác giả của một cuốn sách bán chạy nhất về tình yêu và cô ấy cũng nổi tiếng với tư cách là một huấn luyện viên hẹn hò. Cô từng có nhiều câu nói nổi tiếng trong vai trò huấn luyện viên hẹn hò và nhận được thiện cảm từ công chúng. Trong vai Deborah, Yeon Bo-Ra trung thực, hóm hỉnh và được lòng phụ nữ. Là Yeon Bo-Ra, mọi thứ đều khác với cô ấy. Cô có quan hệ với Lee Soo-Hyeok (Yoon Hyun-Min).

Lee Soo-Hyeok làm công việc lập kế hoạch xuất bản. Anh ấy là một người đàn ông khó đoán. Anh ấy đôi khi dịu dàng và say đắm với phụ nữ, nhưng đôi khi thờ ơ và lạnh lùng. Tình yêu là một điều khó khăn đối với anh ấy. Anh ấy không thích Deborah, người nói như thể cô ấy biết mọi thứ về tình yêu, nhưng anh ấy bất ngờ dính líu đến cô ấy và phải đối mặt với một sự thay đổi trong cuộc đời mình.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo In-na","avatar":""},{"name":"Yoon Hyun-min","avatar":""},{"name":"Ju Sang-uk","avatar":""},{"name":"Park So-jin","avatar":""},{"name":"Hwang Chan-seong","avatar":""},{"name":"Ju-ne","avatar":""},{"name":"Kim Ye-ji","avatar":""},{"name":"Hong Hwa-yeon","avatar":""},{"name":"Lee Sang-un","avatar":""},{"name":"Kim Ji-an","avatar":""},{"name":"Song Min-ji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fiel ao Amor","宝拉！黛宝拉","من در مورد قرار جدی هستم","보라! 데보라","I''m Serious About Dating","Bora Deborah","Bora! Deborah","True to Love","Bo-ra! Deborah"]', 1784690324249);
