INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-nha-toi', 'Anh Hùng Nhà Tôi', 'My Home Hero', 'https://phimimg.com/upload/vod/20250224-1/4e8698ff90a560e41bee9d450380b130.jpg', 'https://phimimg.com/upload/vod/20250224-1/4468fbe7bb6ef60889e696770dd28d6f.jpg', '<p>Tetsuo Tosu, một người làm công ăn lương bình thường, phát hiện ra con gái mình, Reika, bị bạn trai của cô, Matori Nobuto, bạo hành thể xác. Cố gắng tìm hiểu thêm về anh ta, Tetsuo phát hiện ra âm mưu của Matori nhằm tống tiền ông bà giàu có của Reika, đồng thời phát hiện ra rằng anh ta là thành viên của một tổ chức tội phạm, với tiền án giết những người bạn gái cũ của mình.

Đầy giận dữ và sợ hãi khi nghĩ đến việc Reika gặp nguy hiểm, Tetsuo đã giết chết Nobuto, và với sự giúp đỡ của vợ anh ta, Kasen, đã vứt xác thành công. Giờ đây, khi các thành viên của hiệp hội bắt đầu đặt câu hỏi về sự biến mất đột ngột của Nobuto, Tetsuo và Kasen phải làm việc cùng nhau để đảm bảo an toàn cho con gái của họ và ngăn cô ấy dính líu đến tình trạng khó khăn hơn nữa.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Junichi Suwabe","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Chihiro Shirata","avatar":""},{"name":"Kent Ito","avatar":""},{"name":"Akio Otsuka","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["我家的英雄","我家的英雄动画版","マイホームヒーロー","My Home Hero"]', 1784690324249);
