INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-hieu-cun-cung', 'Tín Hiệu Cún Cưng', 'Dog Signal', 'https://phimimg.com/upload/vod/20250221-1/2b2b628fc089fb94da537af6bb8e3537.jpg', 'https://phimimg.com/upload/vod/20250221-1/e81c48424e2e16fbe87961498614155e.jpg', '<p>Huấn luyện chó là một công việc kết nối chó và con người. Miyu Samura, một chàng trai trẻ thiếu quyết đoán, đã gặp Shinichiro Niwa, một huấn luyện viên chó kỳ diệu, khi đang dắt chó của bạn gái cũ đi dạo. Cuộc gặp gỡ tình cờ này sẽ thay đổi lớn cuộc đời Miyu! Đây là câu chuyện về sự trưởng thành của một huấn luyện viên chó mới!</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kenichirou Matsuda","avatar":""},{"name":"Anna Mugiho","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Kenichi Suzumura","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"KENN","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["アニメ ドッグシグナル","愛犬訊號","ドッグシグナル"]', 1784690324249);
