INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-hon-chi-da', 'Hồi Hồn Chi Dạ', 'A Night of Return (A Night of Soul Turning)', 'https://phimimg.com/upload/vod/20250219-1/16a4c7cfe94248d949b20f7a9132b8fa.jpg', 'https://phimimg.com/upload/vod/20250219-1/e707d631eaa8b6b3b257a9b2b9d596ca.jpg', '<p>Câu chuyện kể về nam chính Đỗ An, một người sống trong cảnh nghèo khó. Anh ta không chỉ thất nghiệp mà còn gặp tai nạn xe hơi, vô tình đâm phải người đi bộ và bất tỉnh. Trong giấc mơ, được một người bảo vệ già dẫn đường, Đỗ An hiểu rằng người ta không nên luôn trốn tránh trách nhiệm và không nên nuôi dưỡng ý định xấu vì những thất bại tạm thời. Làm như vậy chỉ dẫn đến đau khổ và bất hạnh vô tận.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Ziyi","avatar":""},{"name":"Liu Yuanyuan","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Li Qinqin","avatar":""},{"name":"Han xitong","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Night of Soul Turning","回魂之夜"]', 1784690324249);
