INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-phong', 'Cuồng Phong', 'The Knockout', 'https://phimimg.com/upload/vod/20250218-1/98abcbae74c8172b7e25d525bed9fc20.jpg', 'https://phimimg.com/upload/vod/20250218-1/4e245e1e29a76707e2ae813920ef1ee0.jpg', '<p>An Hân, cảnh sát hình sự tuyến đầu ở thành phố Kinh Hải. Trong cuộc đấu tranh chống lại các thế lực tà ác, anh ta liên tục bị tấn công, nhưng không thể truy bắt kẻ ác đến cùng vì một bên nào đó đã bảo vệ chống lại các thế lực tà ác này. Sau khi bắt đầu đào tạo và cải cách đội ngũ chính trị và pháp luật quốc gia, tỉnh Lâm Giang đã cử một nhóm cố vấn đến Kinh Hải, phối hợp chặt chẽ với Sở Công an, Viện kiểm sát và Cục pháp luật, thanh trừng những phần tử tham nhũng trong đội chính trị và pháp luật, phá hủy sự bảo vệ của các thế lực xấu xa.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Yi","avatar":""},{"name":"Zhang Songwen","avatar":""},{"name":"Li Yitong","avatar":""},{"name":"Zhang Zhijian","avatar":""},{"name":"Ni Dahong","avatar":""},{"name":"Han Tongsheng","avatar":""},{"name":"Li Jianyi","avatar":""},{"name":"Shi Zhaoqi","avatar":""},{"name":"Wu Gang","avatar":""},{"name":"Li Jian","avatar":""},{"name":"Zhao Da","avatar":""},{"name":"Shen Danping","avatar":""},{"name":"Song Jiateng","avatar":""},{"name":"Gao Ye","avatar":""},{"name":"Wang Xiao","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Hao Ping","avatar":""},{"name":"Su Xiaoding","avatar":""},{"name":"Lin Jiachuan","avatar":""},{"name":"A Runa","avatar":""},{"name":"Bao Dazhi","avatar":""},{"name":"Ling Zhuo","avatar":""},{"name":"Long","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"han