INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-hoc-bong', 'Cuộc Chiến Học Bổng', 'Get Rich', 'https://phimimg.com/upload/vod/20250217-1/cdb0a4024a79e014946c1dd96e4ed8f2.jpg', 'https://phimimg.com/upload/vod/20250217-1/ad6498d187307e6e282e37fc918f9b27.jpg', '<p>Rose là một học sinh nhận học bổng xuất sắc tại trường Sudruethai, một ngôi trường có nhiều mối quan hệ có thể giúp cô đạt được thứ hạng tốt trong tương lai. Tuy nhiên, khi bước vào ngôi trường này, Rose nhận ra rằng để có được cuộc sống tốt đẹp ở đất nước này, tiền bạc là tất cả. Mọi thứ đều xoay quanh tiền bạc và các mối quan hệ của cha mẹ. Người sử dụng điều đó nhiều nhất là Lily, nữ hoàng của trường, có cha là một thành viên của Hiệp hội Phụ huynh. Rose, một học sinh nhận học bổng bị kéo vào chuỗi cuối cùng của ngôi trường này, đã phải đứng dậy, &#39;cướp lại những gì mà học sinh xứng đáng có&#39; cùng với Surf, một học sinh nhận học bổng yên lặng nhưng thông minh và Boo, một vận động viên Taekwondo điên cuồng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Phantira Pipityakorn","avatar":""},{"name":"Tonhon Tantivejakul","avatar":""},{"name":"Sadanont Durongkhaweroj","avatar":""},{"name":"Venita Loywattanakul","avatar":""},{"name":"Supha Sangaworawong","avatar":""},{"name":"Warintorn Pahuyut","avatar":""},{"name":"Natnaree Rerkkriangkrai","avatar":""},{"name":"Praewpannarai Sansanapitayakorn","avatar":""},{"name":"Dujdao Vadhanapakorn","avatar":""},{"name":"Peerapol Kijreunpiromsuk","avatar":""},{"name":"Ornanong Thaisriwon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["拜金人生","模范生向钱冲","最好的学