INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-nha-van-tao-bao-phan-3', 'Nữ Nhà Văn Táo Bạo (Phần 3)', 'Valeria (Season 3)', 'https://phimimg.com/upload/vod/20240305-1/593605a435260406cea61b45448a5b3d.jpg', 'https://phimimg.com/upload/vod/20240305-1/3dc5d0f7c78237be4fc67a42fef6fb9d.jpg', '<p>Tình tay ba mới. Giai đoạn mới trong cuộc sống. Các bữa tiệc sinh nhật chào đón một thập kỷ mới. Bốn người bạn cũ cùng nhau xoay xở với tất cả.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2023, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Diana Gómez","avatar":""},{"name":"Silma López","avatar":""},{"name":"Paula Mália","avatar":""},{"name":"Teresa Riott","avatar":""},{"name":"Maxi Iglesias","avatar":""},{"name":"Juanlu González","avatar":""},{"name":"Federico Aguado","avatar":""},{"name":"Ibrahim Al Shami","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324249);
