INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-de', 'Bóng Đè', 'Shadow', 'https://phimimg.com/upload/vod/20250214-1/ca0c4cb1418838c348a4c666b9bbe926.jpg', 'https://phimimg.com/upload/vod/20250214-1/62530a707b7efba497ae941818111ae2.jpg', '<p>Năm 1999, Dan đang học lớp mười một khi cậu chuyển đến Saint Lawrence, một trường Công giáo dành cho nam sinh. Cha của cậu đang được điều trị tại một bệnh viện gần đó vì ung thư não giai đoạn cuối; mẹ cậu đã qua đời khi cậu mới bảy tuổi. Dan thân thiết với thầy Anurak, hiệu trưởng và nhà tâm lý học của trường. Thầy Anurak cố gắng chữa trị chứng tê liệt khi ngủ của Dan. Trong những giấc mơ, Dan nhìn thấy một bóng đen làm cậu ngạt thở và nó càng tệ hơn khi cậu chuyển trường. Ngay ngày đầu tiên, Dan gây hoảng loạn khi chọn ngồi vào bàn của Trin, một học sinh lớp trên đã biến mất bí ẩn tại hồ sau trường một năm trước đó. Không ai dám ngồi vào bàn đó, và cũng không ai dám vứt nó đi. Cậu quen biết với Nine, bạn học cùng lớp, và George, bạn cùng phòng cũng như Cha-em, học sinh từ trường Saint Mary&#39;s đến biểu diễn trong vở kịch hàng năm. Khi bốn người trở nên thân thiết hơn, họ bắt đầu tìm hiểu về sự biến mất của Trin, đồng thời giúp Dan tránh khỏi bóng đen đang ám ảnh cậu.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Prachaya Ruangroj","avatar":""},{"name":"Natouch Siripongthon","avatar":""},{"name":"Uttsada Panichkul","avatar":""},{"name":"Patchata Janngeon","avatar":""},{"name":"Poon Mitpakdee","avatar":""},{"name":"Chinaradee Anupongpichat","avatar":""},{"name":"Pathomphop Phunklan","avatar":""},{"name":"Pol Nopwichai","avatar":""},{"name":"Danai Jarujinda","avatar":""},{"name":"Chanokwanun Rakcheep","avatar":""},{"name":"Suchao Pongwilai","avatar":""},{"name":"Rastprapa Wisuma","avatar":""},{"name":"Prapakorn Chairak","avatar":""},{"name":"Poom","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["เงาล่าตาย","SHADOW","เงา/ล่า/ตาย"]', 1784690324249);
