INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-luc-hoang-hon', 'Án Mạng Lúc Hoàng Hôn', 'Sunset', 'https://phimimg.com/upload/vod/20250214-1/e46d7e928fe6af869dd30c725acd7e02.jpg', 'https://phimimg.com/upload/vod/20250214-1/2d41d6ebc82efb3e5790a7ec91ccd00c.jpg', '<p>Hasebe Kaori là một đạo diễn phim mới vào nghề. Cô tham khảo ý kiến của nhà biên kịch mới Kai Chihiro về kịch bản phim của mình. Kịch bản dựa trên vụ án giết người trong gia đình Sasazukacho xảy ra cách đây 15 năm. Vụ án này liên quan đến một người đàn ông hikikomori đã giết em gái mình tại nhà và sau đó phóng hỏa đốt nhà. Đám cháy cũng đã giết chết cha mẹ của anh ta. Thị trấn nơi xảy ra vụ án cũng là quê hương của Kai Chihiro. Cả Hasebe Kaori và Kai Chihiro đều có những bí mật liên quan đến vụ án giết người trong gia đình này. Khi Hasebe Kaori và Kai Chihiro điều tra vụ án này cho bộ phim của mình, một sự thật kinh hoàng được hé lộ.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Keiko Kitagawa","avatar":""},{"name":"Riho Yoshioka","avatar":""},{"name":"Hitomi Kuroki","avatar":""},{"name":"Ryoma Takeuchi","avatar":""},{"name":"Shiori Kubo","avatar":""},{"name":"Sei Matobu","avatar":""},{"name":"Mitsuomi Takahashi","avatar":""},{"name":"Ichirôta Miyakawa","avatar":""},{"name":"Manabu Hamada","avatar":""},{"name":"Ren Komai","avatar":""},{"name":"Atom Shukugawa","avatar":""},{"name":"Takashi Kobayashi","avatar":""},{"name":"Matsuo Tatsuru","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["落日","Rakujitsu"]', 1784690324249);
