INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('leo-reich-literally-who-cares', 'Leo Reich: Ai Thèm Quan Tâm Chứ', 'Leo Reich: Literally Who Cares', 'https://phimimg.com/upload/vod/20250214-1/6f6e57f15d118d93565aa6fd97d2e240.jpg', 'https://phimimg.com/upload/vod/20250214-1/ad0c7066fabbf280060bb917f6a8eaf5.jpg', '<p>Chương trình hài độc thoại của nghệ sĩ trẻ Leo Reich, nơi anh thể hiện nhân sinh quan độc nhất vô nhị của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Leo Reich","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Leo Reich: Literally Who Cares?!"]', 1784690324249);
