INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ichikeis-crow-the-movie', 'Ichikei''s Crow The Movie', 'Ichikei''s Crow The Movie', 'https://phimimg.com/upload/vod/20250214-1/b9bf043ad87646a1dace987c46c6ce66.jpg', 'https://phimimg.com/upload/vod/20250214-1/c69be43841c0a673f8fd452ed2e33720.jpg', '<p>Hai năm sau khi Iruma Michio rời khỏi Tòa Hình sự số Một (&quot;Ichikei&quot;) của Tòa án Quận Tokyo, anh ấy hiện đang làm thẩm phán tại Setouchi, tỉnh Okayama. Anh ấy hiện đang xử lý một vụ án thương tích liên quan đến Bộ trưởng Quốc phòng trẻ nhất từ trước đến nay của Nhật Bản. Trong khi đó, Sakama Chizuru đang làm luật sư, theo hệ thống các thẩm phán tích lũy kinh nghiệm làm việc khác. Cô ấy hiện đang xử lý một vụ án liên quan đến một công ty lớn địa phương. Vụ án của cô ấy nằm ở một thị trấn lân cận nơi Iruma Michio làm việc. Hai vụ án của họ dường như hoàn toàn không liên quan đến nhau, nhưng một bí mật được hé lộ giữa hai vụ án này.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yutaka Takenouchi","avatar":""},{"name":"Haru Kuroki","avatar":""},{"name":"Osamu Mukai","avatar":""},{"name":"Takumi Saitoh","avatar":""},{"name":"Tokio Emoto","avatar":""},{"name":"Nanase Nishino","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Ikusaburo Yamazaki","avatar":""},{"name":"Yuki Sakurai","avatar":""},{"name":"Kaho Mizutani","avatar":""},{"name":"Yoh Yoshida","avatar":""},{"name":"Kankuro Kudo","avatar":""},{"name":"Yusuke Hirayama","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Hideaki Anno","avatar":""},{"name":"Riku Kurokou","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ichikei no Karasu: Gekijoban","Eiga ''Ichikei no karasu''","一刑的乌鸦 电影版","鴉色刑事錄 電影版","映画 イチケイのカラス"]', 1784690324249);
