INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-khach-kenshin-2023', 'Lãng Khách Kenshin', 'Rurouni Kenshin', 'https://phimimg.com/upload/vod/20250213-1/8abcdcc2183341a74a8af93763958a87.jpg', 'https://phimimg.com/upload/vod/20250213-1/521d7bca4b1e6d825007143d8951169a.jpg', '<p>Một samurai lang thang có tên Kenshin Himura vẫn cố gắng từng ngày để đảm bảo những giá trị mà bản thân chiến đấu xứng đáng trong kỷ nguyên mới. Từng được biết đến với cái tên Hitokiri Battousai, người được xem là tàn nhẫn nhất trong tất cả các nhà cách mạng thì giờ đây lại bị ám ảnh bởi cảm giác tội lỗi. Kenshin đã thề sẽ không bao giờ giết người để chuộc lỗi với những sinh mạng mà anh đã lấy đi. Hòa bình sẽ không tồn tại xung quanh anh cho đến khi việc anh giết người trở thành dĩ vãng.

(Nguồn: VuiGhe)</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Soma Saito","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Saori Onishi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Rurouni Kenshin","Samurai X","浪客剑心 - 明治剑客浪漫谭","明治剑客浪漫谭","浪客剑心 －明治剑客浪漫谭－","浪客剑心 －明治剑客浪漫谭－ 京都动乱","浪客劍心 (2023)","Rurouni Kenshin: Meiji Kenkaku Romantan","Rurouni Kenshin (2023)","るろうにけんしん めいじけんかくろまんたん","るろ剣","るろうに剣心 －明治剣客浪漫譚－ 京都動乱","るろうに剣心 －明治剣客浪漫譚－ 序幕東京","Rurouni Kenshin: Meiji Kenkaku Romantan - Kyoto Douran","바람의 검심: 메이지 검객 낭만담","바람의 검심 -메이지 검객 낭만기-","바람의 검심: 메이지 검객 낭만기","Kenshin, o Samurai Errante","Самурай Икс","神劍闖江湖 ―明治劍客浪漫譚―","神劍闖江湖 ―明治劍客浪漫譚― 京都動亂","Rurouni Kenshin -Kyoto Disturbance-","Rurouni Kenshin -Tokyo Prologue-","るろうに剣心 －明治剣客浪漫譚－"]', 1784690324249);
