INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-cua-toi', 'Hiệp Sĩ Của Tôi', 'MY (K)NIGHT', 'https://phimimg.com/upload/vod/20250210-1/e615c5f48b83ba8e3816af18bea4d6dd.jpg', 'https://phimimg.com/upload/vod/20250210-1/d7b591086d209c0fb1d4916cec6a341e.jpg', '<p>Ba người phụ nữ ở Yokohama có những rắc rối và suy nghĩ riêng, đang tìm kiếm sự cứu rỗi. Họ đã tìm đến &quot;các nhà trị liệu hẹn hò&quot; để chữa lành cho họ, cứu thế giới, và trở thành người tình một đêm.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kazuma Kawamura","avatar":""},{"name":"Riku Aoyama","avatar":""},{"name":"Hokuto Yoshino","avatar":""},{"name":"Yumi Adachi","avatar":""},{"name":"Moeka Hoshi","avatar":""},{"name":"Natsuko","avatar":""},{"name":"Maki Sakai","avatar":""},{"name":"Atsushi Murakami","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["MY (K)NIGHT","MY (K)NIGHT マイ・ナイト"]', 1784690324249);
