INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-len-saitama-tu-biwa-voi-tinh-yeu', 'Bay Lên Saitama: Từ Biwa Với Tình Yêu', 'Fly Me To The Saitama: From Biwa Lake With Love', 'https://phimimg.com/upload/vod/20250210-1/afa0f7c15b64421ab732cb403e346c50.jpg', 'https://phimimg.com/upload/vod/20250210-1/fa5b57931a4acd9d269fc762d6ffef51.jpg', '<p>Người dân tỉnh Saitama, sau nhiều năm bị người Tokyo áp bức, quyết đứng lên để giành tự do. Nhờ có Momomi Hakuhodo (do Fumi Nikaido thủ vai) và Mặt trận Giải phóng Saitama, chế độ laissez-passer bị bãi bỏ. Người dân tỉnh Saitama lại có thể tận hưởng cuộc sống yên bình hằng ngày, nhưng Mặt trận Giải phóng Saitama lại hướng tới mục tiêu tiếp theo của họ, dẫn đến một vụ án lớn.</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fumi Nikaido","avatar":""},{"name":"Gackt","avatar":""},{"name":"Ryo Kato","avatar":""},{"name":"Masuwaka Tsubasa","avatar":""},{"name":"Maju Ozawa","avatar":""},{"name":"Shôko Nakahara","avatar":""},{"name":"Anne Watanabe","avatar":""},{"name":"Ainosuke Kataoka","avatar":""},{"name":"Norika Fujiwara","avatar":""},{"name":"Momiji Yamamura","avatar":""},{"name":"Emi Wakui","avatar":""},{"name":"Akira 100%","avatar":""},{"name":"Nao Asahi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tonde Saitama: Biwako Yori Ai o Komete","Fly Me to the Saitama 2","Fly Me to the Saitama: From Lake Biwa with Love","翔んで埼玉 ～琵琶湖より愛をこめて～"]', 1784690324249);
