INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tinh-nguyen-tham-chien', 'Quân Tình Nguyện: Tham Chiến', 'The Volunteers: To The War', 'https://phimimg.com/upload/vod/20250203-1/9a6a7dcfbea0bfe10ba4f0216f098e2e.jpg', 'https://phimimg.com/upload/vod/20250203-1/3a37423af10059307f91e2badfd57600.jpg', '<p>Vào những ngày đầu thành lập nước Cộng hòa Nhân dân Trung Hoa năm 1949, Trung Quốc mới phải đối mặt với &quot;những rắc rối bên trong và bên ngoài&quot;. Từ khi Nội chiến Triều Tiên nổ ra, quân đội Hoa Kỳ đã nhiều lần khiêu khích biên giới giữa Trung Quốc và Bắc Triều Tiên, và thường dân đã bị ném bom tàn bạo. Để duy trì hòa bình khó khăn giành được và sự ổn định lâu dài cho các thế hệ, vào tháng 10 năm 1950, Quân tình nguyện Nhân dân Trung Hoa đã tiến vào Bắc Triều Tiên và cuộc chiến &quot;Kháng chiến viện trợ Hoa Kỳ của Triều Tiên&quot; đã nổ ra.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tang Guoqiang","avatar":""},{"name":"Wang Yanhui","avatar":""},{"name":"Liu Jin","avatar":""},{"name":"Xin Baiqing","avatar":""},{"name":"Zhang Songwen","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Zhu Yawen","avatar":""},{"name":"Zhang Zifeng","avatar":""},{"name":"Wei Daxun","avatar":""},{"name":"Xiao Yang","avatar":""},{"name":"Wang Xiao","avatar":""},{"name":"Arthur Chen","avatar":""},{"name":"Vision Wei","avatar":""},{"name":"Yin Fang","avatar":""},{"name":"Zhang Youhao","avatar":""},{"name":"Hai Qing","avatar":""},{"name":"Eric Wang Chuanjun","avatar":""},{"name":"Lang Yueting","avatar":""},{"name":"Du Chun","avatar":""},{"name":"Ji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["伟大的胜利","伟大的胜利(上)","伟大的战争·抗美援朝","伟大的战争·保家卫国","战与祀","The Great War","The Volunteers: To the War","The Volunteers To the War","志愿军：雄兵出击","志願軍：雄兵出擊"]', 1784690324249);
