INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-su-va-khau-sung', 'Nhà Sư Và Khẩu Súng', 'The Monk And The Gun', 'https://phimimg.com/upload/vod/20250203-1/51be95a0eae59a3047b987d9f7e7d3bc.jpg', 'https://phimimg.com/upload/vod/20250203-1/f102e04488498483c517ae030d0b9cf6.jpg', '<p>The Monk and the Gun 2023 kể về cuộc phiêu lưu của một nhà sư trẻ tuổi ở Bhutan trong bối cảnh đất nước chuẩn bị tổ chức cuộc bầu cử tự do đầu tiên. Nhiệm vụ của anh là tìm hai khẩu súng trước khi trăng đầy. Trong hành trình này, anh gặp nhiều nhân vật đa dạng và thú vị. Bộ phim là sự kết hợp của hài hước, bi kịch và phiêu lưu, truyền tải thông điệp về hòa bình và niềm vui.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Bhutan', 0, '[{"name":"Tandin Wangchuk","avatar":""},{"name":"Tandin Sonam","avatar":""},{"name":"Choeying Jatsho","avatar":""},{"name":"Deki Lhamo","avatar":""},{"name":"Pema Zangmo Sherpa","avatar":""},{"name":"Harry Einhorn","avatar":""},{"name":"Kelsang Choejay","avatar":""},{"name":"Tandin Phubz","avatar":""},{"name":"Yuphel Lhendup Selden","avatar":""},{"name":"Phub Dorji","avatar":""},{"name":"Tsheri Zom","avatar":""},{"name":"Kunzang Wangmo","avatar":""},{"name":"Ugyen Dorji","avatar":""},{"name":"Pema Tenzin","avatar":""},{"name":"Oddiyana Kanya Lai-Dorji","avatar":""},{"name":"Tshering Dorji","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Le Moine au fusil","不丹沒有槍","The Monk and the Gun"]', 1784690324249);
