INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('that-hinh-dai-toi-tu-ky-si-khai-huyen-phan-1', 'Thất Hình Đại Tội: Tứ Kỵ Sĩ Khải Huyền (Phần 1)', 'The Seven Deadly Sins: Four Knights Of The Apocalypse (Season 1)', 'thất hình đại tội: tứ kỵ sĩ khải huyền (phần 1) the seven deadly sins: four knights of the apocalypse (season 1) shou komura aino shimada kanna nakamura kikunosuke toya koki uchiyama rikiya koyama sachi kokuryu toshiyuki morikawa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nuong-tu-duong-gia', 'Tiểu Nương Tử Đương Gia', 'Invincible Stepmother', 'https://phimimg.com/upload/vod/20250201-1/a0861d725e6494337482429d0478255e.jpg', 'https://phimimg.com/upload/vod/20250201-1/86404b8b52be0bc52faca4751282c923.jpg', '<p>Do dị tượng từ trên trời giáng xuống, nữ minh tinh Trì Nguyệt vô tình xuyên không về thời cổ đại, trở thành góa phụ trẻ ở trấn Tây Không, không những vậy còn phải nuôi ba đứa con thơ của chồng. Nàng vừa xây dựng tình cảm với bọn trẻ vừa trừng trị những người họ hàng xấu xa ức hiếp chúng trong gia tộc họ Lý. Đồng thời, Trì Nguyệt dựa vào lợi thế là người của thời hiện đại, tự kinh doanh phường rượu, kiếm đủ số tiền để đám nhóc không phải lo cái ăn cái mặc còn xây thêm phòng ốc. Tuy nhiên, qua những lần vùng lên thoát khỏi hiểm cảnh kia, Trì Nguyệt dần phát hiện kẻ chủ mưu đứng sau tất cả dường như chính là người con gái thứ ba của Lý lão phu nhân, Lý Nghi...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Mei Chen","avatar":""},{"name":"Chen Junyu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Invincible Stepmother","Dang Jia Xiao Niang Zi","The Young Lady in Charge of the Household","當家小娘子","当家小娘子"]', 1784690324249);
