INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-so-hai-phan-1', 'Không Sợ Hãi (Phần 1)', 'The Fearless (Season 1)', 'https://phimimg.com/upload/vod/20250127-1/ebe8cf1b74ccb08a22258500aa55ab4f.jpg', 'https://phimimg.com/upload/vod/20250127-1/359b745364f03600818cea4a340ab879.jpg', '<p>“Hoàn toàn không đáng sợ” là một bộ phim truyền hình về luật pháp đô thị với nhân vật chính - nữ luật sư, do đạo diễn Triệu Cẩm Đảo (đạo diễn phim &quot;Màu đỏ&quot;) và Đàm Gia Ngôn (đạo diễn phim”Cảnh sát vinh dự”) chỉ đạo, với kịch bản của Triệu Đông Linh (tác giả phim”Cảnh sát vinh dự”). Phim có sự tham gia của các diễn viên nổi tiếng như Nhiệt Y Trát (Trường An 12 canh giờ), Vương Dương (Khánh Dư Niên Đệ Nhất Quý), và Xuyết Ni (Nửa đời trước của tôi). Câu chuyện kể về cuộc đời của La Anh Tử (do Nhiệt Y Trát đóng), người không bao giờ nghĩ rằng sau 28 năm thuận buồm xuôi gió, cuộc đời cô lại rơi xuống vực thẳm.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Rayza","avatar":""},{"name":"Wang Yang","avatar":""},{"name":"Chuai Ni","avatar":""},{"name":"Huang Jue","avatar":""},{"name":"Shen Yujie","avatar":""},{"name":"Feng Hui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["你好生活","无所畏惧2","无所畏惧之永不放弃","ザ・フィアレス","무소외구","เกรงไม่กลัว","無所畏懼","Unspoken","The Fearless","Fearless 2","Unbreakable Ⅱ","Unbreakable","无所畏惧"]', 1784690324249);
