INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-so-hai-phan-1', 'Không Sợ Hãi (Phần 1)', 'The Fearless (Season 1)', 'không sợ hãi (phần 1) the fearless (season 1) rayza wang yang chuai ni huang jue shen yujie feng hui 你好生活 无所畏惧2 无所畏惧之永不放弃 ザ・フィアレス 무소외구 เกรงไม่กลัว 無所畏懼 unspoken the fearless fearless 2 unbreakable ⅱ unbreakable 无所畏惧', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-meena', 'Thám Tử Meena', 'P.I. Meena', 'https://phimimg.com/upload/vod/20250126-1/efc8a1eaba21e9962c8b479216949228.jpg', 'https://phimimg.com/upload/vod/20250126-1/ba7360ad87478ec6b305c900cd0e5d5d.jpg', '<p>Bị ám ảnh bởi quá khứ bi thảm, thám tử tư Meenakshi Iyer hay còn gọi là P.I. Meena, bắt đầu điều tra những gì có vẻ giống như một vụ án đâm xe rồi bỏ chạy thông thường, chỉ để phát hiện ra rằng nó có nhiều điều hơn những gì bạn thấy và bị vướng vào một mạng lưới âm mưu đang xé nát thế giới của tất cả những ai đến gần nó.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Tanya Maniktala","avatar":""},{"name":"Jisshu Sengupta","avatar":""},{"name":"Parambrata Chatterjee","avatar":""},{"name":"Vinay Pathak","avatar":""},{"name":"Zarina Wahab","avatar":""},{"name":"Saurav Das","avatar":""},{"name":"Harsh Chhaya","avatar":""},{"name":"Vipin Sharma","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["侦探米娜","P.I.Meena","P. I. Meena","P.I. मीना"]', 1784690324249);
