INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-doi-be-bi', 'Hoán Đổi Bé Bi', 'Maybe Baby', 'https://phimimg.com/upload/vod/20250124-1/1f38dbf52ac772c46d9a6bd45d1bbc75.jpg', 'https://phimimg.com/upload/vod/20250124-1/6e01d72f86aac30f5f993ca9be38b8f3.jpg', '<p>Khi biết rằng phòng khám phụ sản đã hoán đổi nhầm trứng của họ, hai người phụ nữ mang thai phải tìm cách xoay xở với nhầm lẫn đó và cả thái độ khinh miệt nhau.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Đan Mạch', 0, '[{"name":"Mille Dinesen","avatar":""},{"name":"Lars Ranthe","avatar":""},{"name":"Thomas Bo Larsen","avatar":""},{"name":"Neel Rønholt","avatar":""},{"name":"Laura Bro","avatar":""},{"name":"Katinka Lærke Petersen","avatar":""},{"name":"Kasper Dalsgaard","avatar":""},{"name":"Sarah Boberg","avatar":""},{"name":"Solbjørg Højfeldt","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Cambio de bebés","Troca de Bebês","Maybe Baby","寶貝對不對","Bytte bytte baby"]', 1784690324249);
