INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nierautomata-ver11a', 'Giải Cứu Địa Cầu', 'NieR:Automata Ver1.1a', 'https://phimimg.com/upload/vod/20250122-1/8d55ef9eccaee0f74c22c8bcd5baa3cb.jpg', 'https://phimimg.com/upload/vod/20250122-1/93c11d18c83ff13d1dff432447aee7ba.jpg', '<p>Nhân loại đã bị đẩy ra khỏi hành tinh xanh bởi những sinh vật máy móc từ thế giới khác. Trong nỗ lực cuối cùng để chiếm lại Trái Đất, con người đã tạo ra một lực lượng lính android để tiêu diệt những kẻ xâm lược. Một cuộc chiến giữa những cỗ máy đang hoành hành và những người máy thông minh sẽ bắt đầu.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yui Ishikawa","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Ayaka Suwa","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Kaoru Akiyama","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Tatsuhisa Suzuki","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Chiaki Kano","avatar":""},{"name":"Keiko Isobe","avatar":""},{"name":"Mary Hatsumi","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Ryoko Shiraishi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["尼尔：机械纪元 Ver1.1a","尼尔：自动人形 Ver1.1a","尼尔：自动人形动画版","尼尔：机械纪元","尼尔：机械纪元动画版","NieR:Automata Ver1.1a","ニーア オートマタ Ver1.1a","NieRAutomata","NieR：Automata Ver1.1a","NieR Automata Ver1.1a","니어:오토마타 Ver1.1a","NieR:Automata Ver 1.1a","Ver"]', 1784690324249);
