INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nierautomata-ver11a', 'Giải Cứu Địa Cầu', 'NieR:Automata Ver1.1a', 'giải cứu địa cầu nier:automata ver1.1a yui ishikawa natsuki hanae ayaka suwa hiroki yasumoto kaoru akiyama daisuke namikawa tatsuhisa suzuki aoi yuki chiaki kano keiko isobe mary hatsumi atsumi tanezaki ryoko shiraishi 尼尔：机械纪元 ver1.1a 尼尔：自动人形 ver1.1a 尼尔：自动人形动画版 尼尔：机械纪元 尼尔：机械纪元动画版 nier:automata ver1.1a ニーア オートマタ ver1.1a nierautomata nier：automata ver1.1a nier automata ver1.1a 니어:오토마타 ver1.1a nier:automata ver 1.1a ver', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuoc-dao-mon-truyen-ky-phan-1', 'Thước Đao Môn Truyền Kỳ (Phần 1)', 'Legend Of The Undercover Chef (Season 1)', 'https://phimimg.com/upload/vod/20250122-1/36a7512569ad2476016ee77d7c794ac5.jpg', 'https://phimimg.com/upload/vod/20250122-1/7e5ea2791f8b8905e0a0e91d61878a1e.jpg', '<p>Những năm cuối triều đại, giặc Oa gây rối khắp nơi, hoạn quan lộng quyền, Tào công công của Đông Xưởng cấu kết giặc Oa, ý đồ mưu phản. Tây Môn Trường Hải ở bên ngoài là chưởng môn Thước Đao Môn, thực chất là thành viên tổ chức bí mật chống giặc, ngoại trừ tiêu diệt giặc Oa, một nhiệm vụ khác là điều tra Hán gian. Tào công công phát hiện có nhân sĩ phản đối mình, phái người giám sát các môn phái võ lâm. Để che giấu tai mắt, Trường Hải tìm huynh đệ song sinh ở quê nhà là Tây Môn Trường Tại, nhờ y đóng giả mình. Tuy là huynh đệ song sinh nhưng tính cách hai huynh đệ hoàn toàn khác nhau, đệ đệ là đại hiệp anh hùng khí phách, ca ca lại là đầu bếp phố chợ nhát gan yếu đuối. Trước lời nhờ vả của đệ đệ, Trường Tại bất đắc dĩ đồng ý đóng giả. Cứ thế, Trường Tại từ một đầu bếp trở thành chưởng môn, bước vào thế giới võ hiệp đầy sắc màu. Trường Tại đến Thước Đao Môn lạ nước lạ cái, muốn đóng giả đệ đệ thì ải đầu tiên gặp phải chính là phải lừa được những người thân cận bên cạnh đệ đệ: Đại đệ tử Hách Minh, Diệp Tứ Nương, nhị đồ đệ Triệu Đức Trụ, khó nhất là con gái của đệ đệ - Tây Môn Nhu. Sóng gió ồ ạt kéo đến, những người như bang chủ Thiên Trì Bang Cao Đại Mao, giáo chủ Ngũ Độc Giáo lần lượt tìm đến, nguy hiểm nhất là Tào công công ở Đông Xưởng.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Bổn Sơn","avatar":""},{"name":"Tống Tiểu Bảo","avatar":""},{"name":"Tống Hiểu Phong","avatar":""},{"name":"Văn Tống","avatar":""},{"name":"Trình Dã","avatar":""},{"name":"Dương Thụ Lâm","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Que Dao Men Chuan Qi","鹊刀门传奇 2","鹊刀门传奇 第二季","Legend of the Undercover Chef","鹊刀门传奇"]', 1784690324249);
