INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-kretek', 'Cô Gái Kretek', 'Cigarette Girl', 'https://phimimg.com/upload/vod/20250122-1/23204add15e8f05b3fde682ea606a895.jpg', 'https://phimimg.com/upload/vod/20250122-1/c393ede7b4c966632cc028b291db9957.jpg', '<p>Hành trình yêu thương và tự khám phá của một nghệ nhân tài ba mở ra khi cô thách thức truyền thống trong ngành thuốc lá đinh hương ở Indonesia những năm 1960.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Dian Sastrowardoyo","avatar":""},{"name":"Ario Bayu","avatar":""},{"name":"Putri Marino","avatar":""},{"name":"Arya Saloka","avatar":""},{"name":"Tissa Biani","avatar":""},{"name":"Sheila Dara","avatar":""},{"name":"Ibnu Jamil","avatar":""},{"name":"Rukman Rosadi","avatar":""},{"name":"Sha Ine Febriyanti","avatar":""},{"name":"Verdi Solaiman","avatar":""},{"name":"Winky Wiryawan","avatar":""},{"name":"Dimas Aditya","avatar":""},{"name":"Pritt Timothy","avatar":""},{"name":"Tutie Kirana","avatar":""},{"name":"Siti Fauziah","avatar":""},{"name":"Haru Sandra","avatar":""},{"name":"Nasarius Ardhani Sudar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["دختر سیگار","Cigaretno dekle","Gadis Kretek"]', 1784690324249);
