INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-linh-thu-phan-2', 'Có Linh Thú (Phần 2)', 'Fabulous Beasts (Season 2)', 'https://phimimg.com/upload/vod/20250122-1/4e68f547b2e3a08c44a8e10872ecfa6a.jpg', 'https://phimimg.com/upload/vod/20250122-1/74fb9015824fe6d590bd602e5f64852b.jpg', '<p><span style="text-wrap-mode: wrap;">Được đặt tên theo &quot;The Classic of Mountains and Seas&quot;: &quot;Một con thú trông giống khỉ với đôi tai trắng...&quot;, &quot;Fabulous Beasts&quot; có cùng thế giới quan với các tác phẩm khác trong sê-ri &quot;Không phải con người&quot;. Các nhân vật được lấy cảm hứng từ tỳ hưu và các con thú thần thoại truyền thống khác của Trung Quốc, với các yếu tố hiện đại được thêm vào để làm cho các nhân vật khác biệt với các hoạt hình hình người khác. Thiết kế &quot;quái vật&quot; dễ thương và sống động cộng với hài kịch bình thường giúp khán giả trong xã hội căng thẳng này thư giãn và sưởi ấm trái tim.</span></p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ajie","avatar":""},{"name":"Yang Ning","avatar":""},{"name":"Shuai Guan","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Liu Cong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Fabulous Beasts","You Shou Yan","There Are Beasts","有兽焉"]', 1784690324249);
