INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ataturk-hanh-trinh-cua-nguoi-anh-hung', 'Ataturk: Hành Trình Của Người Anh Hùng', 'Ataturk: 1881-1919', 'https://phimimg.com/upload/vod/20250118-1/6105bad901fbece71b35a9c5def68f59.jpg', 'https://phimimg.com/upload/vod/20250118-1/64cf845b7c91e91ad2d9cc5f2571fb4d.jpg', '<p>Phim&nbsp;kể về cuộc đời của Mustafa Kemal từ khi tốt nghiệp trường quân sự. Là một người yêu nước lý tưởng, ông là một sĩ quan trong quân đội Ottoman và luôn mặc quân phục với niềm tự hào. Tuy nhiên, Mustafa Kemal dần nhận ra rằng Đế chế Ottoman đang dần suy tàn và cần có sự thay đổi lớn để cứu vãn tình thế.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Aras Bulut İynemli","avatar":""},{"name":"Songül Öden","avatar":""},{"name":"Sarp Akkaya","avatar":""},{"name":"Esra Bilgiç","avatar":""},{"name":"Mehmet Günsür","avatar":""},{"name":"Celile Toyon","avatar":""},{"name":"Darko Peric","avatar":""},{"name":"Berk Cankat","avatar":""},{"name":"John James","avatar":""},{"name":"Emre Mete Sönmez","avatar":""},{"name":"Sahra Şaş","avatar":""},{"name":"Bertan Asllani","avatar":""},{"name":"Sahin Sancak","avatar":""},{"name":"Atakan Yarımdünya","avatar":""},{"name":"Beran Kotan","avatar":""},{"name":"Sinan Arslan","avatar":""},{"name":"Lidija Kordić","avatar":""},{"name":"Oğulcan A","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Atatürk 1. Film","Atatürk 1881-1919 (1. Film)","Atatürk","Atatürk 1 1881 - 1919","Atatürk 1881 - 1919"]', 1784690324249);
