INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kaguyasama-cuoc-chien-to-tinh-nu-hon-dau-khong-hoi-ket', 'Kaguya-sama: Cuộc chiến tỏ tình - Nụ hôn đầu không hồi kết', 'かぐや様は告らせたい-ファーストキッスは終わらない-', 'https://phimimg.com/upload/vod/20250118-1/c9fded692de24b3ad3a4d9d69ff4e501.jpg', 'https://phimimg.com/upload/vod/20250118-1/8c8969f9836998c64d6073d45818362d.jpg', '<p>Phó chủ tịch Kaguya Shinomiya và chủ tịch hội học sinh Miyuki Shirogane gặp nhau trong hội học sinh của Học viện Shuzhiin, sau một thời gian dài đấu trí và tiếp xúc, cuối cùng hai thiên tài cũng bày tỏ tình cảm với nhau. Tuy nhiên, cả hai vẫn chưa thổ lộ rõ ràng, tưởng chừng sắp thành người yêu nhưng vẫn duy trì mối quan hệ mập mờ, thay vào đó lại quan tâm đến nhau và cùng đón Giáng sinh. Shirogane, người &quot;khao khát trở nên hoàn hảo&quot; và Kaguya, người theo đuổi anh &quot;không hoàn hảo&quot;, đây là một câu chuyện tình yêu vô cùng &quot;bình thường&quot; của những thiên tài</p>', 'Hoàn Tất (5/5)', 5, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324249);
