INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-gia-toc-farad-phan-1', 'Bí Mật Gia Tộc Farad (Phần 1)', 'Los Farad (Season 1)', 'https://phimimg.com/upload/vod/20250116-1/d1cbd4fcefa25df8b89948ad1e30aa1d.jpg', 'https://phimimg.com/upload/vod/20250116-1/be003833b667399594a0ea6f9880add8.jpg', '<p>Bộ phim kể về Oskar, một chàng trai trẻ ở Madrid năm 1985, với khát khao vươn lên từ nghèo khó. Cuộc đời anh thay đổi khi gặp gia đình Farad giàu có và bí ẩn. Oskar nhanh chóng bước vào thế giới buôn bán vũ khí quốc tế, nơi anh nếm trải sự xa hoa, phiêu lưu và quyền lực, nhưng cũng đối mặt với bạo lực và sự đánh đổi đầy khắc nghiệt.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Miguel Herrán","avatar":""},{"name":"Susana Abaitua","avatar":""},{"name":"Pedro Casablanc","avatar":""},{"name":"Adam Jezierski","avatar":""},{"name":"Nora Navas","avatar":""},{"name":"Amparo Piñero","avatar":""},{"name":"Fernando Tejero","avatar":""},{"name":"Igal Naor","avatar":""},{"name":"Makram J. Khoury","avatar":""},{"name":"Omar Ayuso","avatar":""},{"name":"Moussa Echarif","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["法拉德家族","Los Farad"]', 1784690324249);
