INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('erin-va-aaron', 'Erin Và Aaron', 'Erin & Aaron', 'https://phimimg.com/upload/vod/20250113-1/f8642eca00b0be5e681cb555e11f7bd2.jpg', 'https://phimimg.com/upload/vod/20250113-1/7a5b3f51ff14a38b26d845bf2b2ab221.jpg', '<p>Tên của Erin và Aaron nghe có vẻ giống nhau, nhưng họ lại hết sức đối lập. Thông qua âm nhạc, hai chị em kế mới này học cách chung sống hòa thuận.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ava Ro","avatar":""},{"name":"Jensen Gering","avatar":""},{"name":"Celia Méndez","avatar":""},{"name":"David S. Jung","avatar":""},{"name":"Pyper Braun","avatar":""},{"name":"Larisa Oleynik","avatar":""},{"name":"Luca Diaz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Erin and Aaron","Erin & Aaron"]', 1784690324249);
