INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-si-da-hoi-sinh-the-gioi-phan-3', 'Tiến Sĩ Đá: Hồi Sinh Thế Giới (Phần 3)', 'Dr. STONE (Season 3)', 'https://phimimg.com/upload/vod/20241009-1/7fa4e647cf37376debe05c403013cb5f.jpg', 'https://phimimg.com/upload/vod/20241009-1/a529372d9b16de8244bc544d08db9b54.jpg', '<p>&quot;Dr. Stone mùa 3&quot; là phần thứ ba của hoạt hình &quot;Dr. Stone&quot;, một bộ truyện tranh khoa học viễn tưởng được sáng tác bởi họa sĩ truyện tranh Nhật Bản Riichiro Inagaki Sau khi bị Hyoga phản bội, Senku quyết định hợp tác với Chrome để tạo thành một bộ đôi thần kỳ đối đầu với hắn. Trong khi đó, để làm sáng tỏ bí ẩn của hiện tượng hóa đá, Senku và nhóm của anh ấy cố gắng giong buồm vào thế giới của những điều chưa biết, nhưng họ cần một con tàu và một thuyền trưởng để làm điều đó. Hãy sẵn sàng để bắt đầu cuộc hành trình bước vào thời đại khám phá vĩ đại và khám phá bí ẩn của sự hóa đá! Kỷ nguyên Khám phá Thế giới Đá cuối cùng cũng mở ra! Bộ phim này sẽ được phát sóng trực tuyến trên trang web quốc tế của iQiyi (iQ.com).</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"小林裕介","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Доктор Стоун","石纪元","新石纪","石纪元 科学与未来 第2部分","Dr.STONE","डॉ. स्टोन","ドクターストーン","Dr.STONE STONE WARS","Dr.STONE (ドクターストーン)","Dr.STONE NEW WORLD","Dr.STONE SCIENCE FUTURE","닥터스톤","닥터스톤 4기",