INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoc-su-tu-su-phan-1', 'Dược Sư Tự Sự (Phần 1)', 'The Apothecary Diaries (Season 1)', 'https://phimimg.com/upload/vod/20240103-1/e630f5d58fadb865d55a880d1dfae9a2.jpg', 'https://phimimg.com/upload/vod/20240103-1/f85819a6db3c8f53f6ca1875e43da3af.jpg', '<p>Trong triều đình phong kiến Trung Quốc, một vài tháng đã trôi qua kể từ khi bé gái 17 tuổi có tên Miêu Miêu bị bắt cóc và bị buộc làm người hầu cấp thấp trong cung điện hoàng gia. Tuy nhiên, cô bé vẫn giữ tinh thần tích cực và cứ làm việc cho đến mãn hạn. Một ngày nọ, cô đã nghe tin hai đứa con của hoàng đế bị mắc bệnh nặng. Tại đây, cô đã quyết định hành động bí mật dựa vào những kinh nghiệm có sẵn từ phố đèn đỏ nghèo để cứu chữa.</p><p>Mặc dù đã cố gắng ở ẩn nhưng Miêu Miêu lại nhanh chóng gây sự chú ý với Jinshi, một người có quyền lực nhận ra tài năng của cô. Từ đây, thân phận thực sự của Miêu Miêu được tiết lộ với những bí ẩn về y học đa dạng.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 170, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Yuki","avatar":""},{"name":"Takeo Otsuka","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Hina Kino","avatar":""},{"name":"Yuhko Kaida","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324249);
