INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-angel-city-phan-1', 'Đội Bóng Angel City (Phần 1)', 'Angel City (Season 1)', 'https://phimimg.com/upload/vod/20250110-1/cf90f1302bb64871b3c17afcff3cd7fb.jpg', 'https://phimimg.com/upload/vod/20250110-1/00d9c910268b79e6bfc8f263572f50fa.jpg', '<p>Bộ phim theo chân những người phụ nữ mạnh mẽ trong quá trình tạo lập một đội bóng đá nữ mới để tham gia vào giải nhà nghề tại Mỹ. Điều khác biệt ở họ là ban lãnh đạo hầu hết là nữ, những người khao khát đem lại sự bình đẳng cho phái nữ trong thể thao.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Angel City"]', 1784690324249);
