INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-cuoi-cung-sat-nhan-hang-loat-san-lung-nguoi-da-dang-gioi-o-new-york-phan-1', 'Cuộc Gọi Cuối Cùng Sát Nhân Hàng Loạt Săn Lùng Người Đa Dạng Giới Ở New York (Phần 1)', 'Last Call: When A Serial Killer Stalked Queer New York (Season 1)', 'https://phimimg.com/upload/vod/20250110-1/cbf8f1f8b5f20c3601195140df0020ea.jpg', 'https://phimimg.com/upload/vod/20250110-1/9e73dcca81a31e2a140f07e5d3553fce.jpg', '<p>Trong lúc đại dịch AIDS trở nên gay go vào đầu thập niên 1990, sự thù ghét với người đồng tính gia tăng, và một kẻ giết người hàng loạt đã xâm nhập vào đời sống về đêm của họ để tìm con mồi.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Foreman","avatar":""},{"name":"Michael Ferreri","avatar":""},{"name":"Bea Hanson","avatar":""},{"name":"Andy Humm","avatar":""},{"name":"Ceyenne Doroshow","avatar":""},{"name":"Thomas Macauley","avatar":""},{"name":"Edgar Rodriguez","avatar":""},{"name":"Thomas Hayes","avatar":""},{"name":"Isaac J. Conner","avatar":""},{"name":"Lisa Hall","avatar":""},{"name":"Gregory G. Allen","avatar":""},{"name":"Antonio Marrero","avatar":""},{"name":"Tracey O''Shea","avatar":""},{"name":"Kimberly Stevens","avatar":""},{"name":"Diana Malkentzos","avatar":""},{"name":"David Wertheimer","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Ultima llamada: El asesino en serie de la Nueva York queer","Ultima llamada. El asesino en serie de la Nueva York queer","Última llamada. El asesino en serie de la nueva York queer","Last Call: When a Serial Killer Stalked Queer New York"]', 1784690324249);
