INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-chien-ii-loi-ke-tu-tien-tuyen', 'Thế Chiến II: Lời Kể Từ Tiền Tuyến', 'World War II: From The Frontlines', 'https://phimimg.com/upload/vod/20240913-1/97272014f63b21ffa855bfd44697f957.jpg', 'https://phimimg.com/upload/vod/20240913-1/5a23adf1035bc86f129c15565ab6dfa7.jpg', '<p>Thông qua các thước phim tư liệu được nâng tầm đầy sống động và chia sẻ từ mọi phía của cuộc xung đột, loạt phim tài liệu này giúp Thế chiến II trở nên sống động hơn bao giờ hết.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"John Boyega","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324249);
