INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-len-ban-ngay', 'Trăng Lên Ban Ngày', 'Moon In The Day', 'https://phimimg.com/upload/vod/20250110-1/aeba46fa9f5ad19012622820216fbe1f.jpg', 'https://phimimg.com/upload/vod/20250110-1/193fd8ddcd8bca0c5cf97fee7959a762.jpg', '<p>Đan xen giữa quá khứ và hiện tại, Trăng Lên Ban Ngày theo chân một cặp đôi có nghiệt duyên từ kiếp trước. Sau một tai nạn, thân xác của ngôi sao nổi tiếng Han Juno bị chiếm hữu bởi Do Ha, một quý tộc thời xưa đã chết dưới tay vợ mình. Trong cơ thể mới, Do Ha quyết tâm trả thù. Trùng hợp thay, người vợ năm xưa của Do Ha trong kiếp này lại chính là Young Hwa, vệ sĩ mới của Juno.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Young-dae","avatar":""},{"name":"Pyo Ye-jin","avatar":""},{"name":"On Ju-wan","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Moon Ye-won","avatar":""},{"name":"Jeong Sin-hye","avatar":""},{"name":"Kim Dong-young","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Lee Young-suk","avatar":""},{"name":"Shin Yu-ro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["白日升月","قمر في النهار","Luna en el día","白昼之月","白晝之月","The Moon That Rises in the Day","낮에 뜨는 달"]', 1784690324249);
