INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-tuyet-voi-de-tro-thanh-cun', 'Ngày Tuyệt Vời Để Trở Thành Cún', 'A Good Day To Be A Dog', 'https://phimimg.com/upload/vod/20240111-1/b7ceea689eb8a4aeee642d3639bb09a9.jpg', 'https://phimimg.com/upload/vod/20240111-1/6955d7eebf20dde2d6c6c6295b0ba1d9.jpg', '<p>Hae-na, người chắc chắn phải thừa hưởng lời nguyền của gia đình, biến thành một con chó sau khi nhận được nụ hôn đầu tiên. Cách duy nhất để phá bỏ lời nguyền là có được nụ hôn thứ hai. Vấn đề là chàng trai trao cho Hae-na nụ hôn đầu tiên lại sợ chó.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 8, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Gyu-young","avatar":""},{"name":"Cha Eun-woo","avatar":""},{"name":"Lee Hyun-woo","avatar":""},{"name":"Yoon Hyun-soo","avatar":""},{"name":"Kim Yi-kyeong","avatar":""},{"name":"Lee Seo-el","avatar":""},{"name":"Song Young-ah","avatar":""},{"name":"Ryu Abel","avatar":""},{"name":"Jo Ah-young","avatar":""},{"name":"Yoo Seung-mok","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324249);
