INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-chuong-hanh-phuc', 'Một Chương Hạnh Phúc', 'My Happy Ending', 'https://phimimg.com/upload/vod/20240109-1/c4ac81a1d90dbc4adb88dab01ae0b4c6.jpg', 'https://phimimg.com/upload/vod/20240109-1/f47915b1945d6a550f9624dfa679c1d6.jpg', '<p>Một Chương Hạnh Phúc - My Happy Ending kể về Seo Jae won (do Jang Na ra thủ vai) là một CEO thành đạt với cuộc sống vợ chồng tưởng chừng như rất hạnh phúc, có người cha dượng yêu chiều hết mực, có tất cả mọi thứ để người khác ghen tị. Nhưng một ngày nọ, cô phát hiện ra chồng của mình đang ngoại tình với người bạn thân nhất của mình, người cha dượng là người đã giết hại mẹ cô và cô đồng nghiệp đã theo dõi cô trong nhiều năm. Cô bị sốc và dường như không thể tin tưởng bất cứ ai, Jae won đã bắt đầu làm sáng tỏ những bí mật gây sốc xung quanh cô.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Na-ra","avatar":""},{"name":"Son Ho-jun","avatar":""},{"name":"So I-hyeon","avatar":""},{"name":"Lee Gi-taek","avatar":""},{"name":"Kim Hong-pa","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Kim Myung-soo","avatar":""},{"name":"Jung Jin-woo","avatar":""},{"name":"Choi So-yul","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324249);
