INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huynh-de-ky-tich', 'Huynh Đệ Kỳ Tích', 'Miraculous Brothers', 'https://phimimg.com/upload/vod/20240305-1/4fa4fe4f5edd605a235aaae304c66b4e.jpg', 'https://phimimg.com/upload/vod/20240305-1/1eaf8811ac9bad6b6a4f944f6da17d51.jpg', '<p>Nội dung của phim Huynh Đệ Kỳ Tích xoay quanh câu chuyện kể về Yook Dong Ju – một nhà văn tài năng đầy tham vọng nhưng phải gánh trên vai vô số nợ nần và một người mẹ chuyên gây rắc rối. Định mệnh sắp đặt anh gặp được Kang San, một chàng trai bí ẩn có khả năng đọc suy nghĩ và cảm nhận được nỗi đau, sự tuyệt vọng của người khác. Trong khi đấu tranh để sống với cuộc đời của chính mình, Yook Dong Joo tình cờ trở thành người giám hộ của Kang San, hiện đang mất trí do gặp tai nạn. Nhân vật với năng lực đặc biệt này liên tục bị lôi cuốn vào nỗi đau đớn của người khác, góp phần tạo thêm sự đa dạng cho cuộc sống của cả hai.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 14, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Woo","avatar":""},{"name":"Bae Hyeon-seong","avatar":""},{"name":"Park Yu-rim","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Lee Ki-woo","avatar":""},{"name":"Kang Mal-geum","avatar":""},{"name":"Seo Jae-hee","avatar":""},{"name":"So Hee-jung","avatar":""},{"name":"Jo Bok-rae","avatar":""},{"name":"Lee Ji-hyeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324249