INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-dich-hoan-hao', 'Giao Dịch Hoàn Hảo', 'The Deal', 'https://phimimg.com/upload/vod/20241104-1/0259ef304b922316b2c6775d029c7164.jpg', 'https://phimimg.com/upload/vod/20241104-1/748a7125ec904b648de5aa47b31f7489.jpg', '<p>Joon Sung, Jae Hyo, và Min Woo là bạn học thời cấp ba. Sau một thời gian dài không liên lạc, họ gặp lại nhau và nảy ra âm mưu giả vờ bắt cóc Min Woo - con trai độc nhất của một gia đình giàu có - để tống tiền gia đình cậu. Nhưng rồi những sự cố bất ngờ xảy đến và giao kèo hoàn hảo giữa họ bắt đầu rạn nứt.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Seung Ho","avatar":""},{"name":"Kim Dong Hwi","avatar":""},{"name":"Yoo Soo Bin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["الصفقة","The Perfect Deal","Georae","Deal","거래"]', 1784690324249);
