INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-tu-than', 'Trái Tim Tử Thần', 'Kokdu: Season Of Deity', 'https://phimimg.com/upload/vod/20240305-1/f17e1a26a6a4a3039a02b433182e9c4d.jpg', 'https://phimimg.com/upload/vod/20240305-1/dcc0fc9746182cda9cc14f4a54929a31.jpg', '<p>Trái Tim Tử Thần - Kokdu: Season of Deity xoay quanh Kokdu (Kim Jung Hyun) - người từng là một vị thần nhưng phạm sai lầm và phải biến thành thần chết. Nhiệm vụ của anh là dẫn dắt những linh hồn người chết sang thế giới bên kia. Sau 99 năm, Kokdu được trở lại nhân gian, sống trong thân phận Do Jin Woo - người có vẻ ngoài giống anh. Jin Woo có mối tình lãng mạn với bác sĩ đa khoa Han Gye Jeol (Im Soo Hyang).</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Im Soo Hyang","avatar":""},{"name":"Kim Jung-hyun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324249);
