INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('idol-than-thanh', 'Idol Thần Thánh', 'The Heavenly Idol', 'https://phimimg.com/upload/vod/20240309-1/e66343d4b110a9081a543813db38a0a6.jpg', 'https://phimimg.com/upload/vod/20240309-1/6ba686071a0813d36ac035ca6df97f11.jpg', '<p>Pontifex Lembrary chiến đấu chống lại ác quỷ, anh ta được chuyển đến một thế giới khác với cơ thể của Woo Yeon-woo, thành viên của một nhóm nhạc thần tượng không nổi tiếng có tên là Wild Animal. Trong một ngành kinh doanh giải trí nơi các kỹ năng xã hội, xu hướng và tài năng áp đảo là rất cần thiết, thật khó để Lembrary trang nghiêm, thánh thiện thích nghi. Do những lời nói và việc làm không phù hợp với tư cách là một người nổi tiếng, Lembrary bị công chúng bàn tán và nhận được sự chú ý mà anh không ngờ tới. Sử dụng lòng tốt và tình yêu của mình, Lembrary chữa lành thế giới cằn cỗi và vặn vẹo mà mọi người đang sống trong khi đi hết con đường này đến con đường khác để ổn định bản thân như một thần tượng.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 17, 2023, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Min-gue","avatar":""},{"name":"Go Bo-gyeol","avatar":""},{"name":"Lee Jang-woo","avatar":""},{"name":"Tak Jae-hoon","avatar":""},{"name":"Ye Ji-won","avatar":""},{"name":"Park Sang-nam","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324249);
