INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xu-so-cac-nguyen-to', 'Xứ Sở Các Nguyên Tố', 'Elemental', 'https://phimimg.com/upload/vod/20230917-1/fa2828e7ddff444bb7a5bf53a09afd08.jpg', 'https://phimimg.com/upload/vod/20230917-1/71749e1dc06af7dd713ac8ff9ba92443.jpg', '<p><span style="font-family: ">Xứ Sở Các Nguyên Tố từ Disney và Pixar lấy bối cảnh tại thành phố các các nguyên tố, nơi lửa, nước, đất và không khí cùng chung sống với nhau. Câu chuyện xoay quanh nhân vật Ember, một cô nàng cá tính, thông minh, mạnh mẽ và đầy sức hút. Tuy nhiên, mối quan hệ của cô với Wade - một anh chàng hài hước, luôn thuận thế đẩy dòng - khiến Ember cảm thấy ngờ vực với thế giới này.</span></p>', 'Full', 1, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 1, '[{"name":"Leah Lewis","avatar":""},{"name":"Mamoudou Athie","avatar":""},{"name":"Ronnie del Carmen","avatar":""},{"name":"Shila Ommi","avatar":""},{"name":"Wendi McLendon-Covey","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Mason Wertheimer","avatar":""},{"name":"Ronobir Lahiri","avatar":""},{"name":"Wilma Bonet","avatar":""},{"name":"Joe Pera","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324249);
