INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tomochan-la-con-gai', 'Tomo-chan Là Con Gái', 'Tomo-chan Is A Girl', 'tomo-chan là con gái tomo-chan is a girl rie takahashi kaito ishikawa rina hidaka sally amaki kohei amasaki yoshitsugu matsuoka 智酱是女生！ 小智是女生！ tomo-chan es una chica! tomo-chan wa onnanoko! tomo-chan wa onna no ko! 토모쨩은 여자아이 トモちゃんは女の子！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tieu-thu-va-chang-ve-si', 'Nàng Tiểu Thư Và Chàng Vệ Sĩ', 'A Girl & Her Guard Dog', 'https://phimimg.com/upload/vod/20241229-1/14ee266c37a19d589e333dada19bbf4e.jpg', 'https://phimimg.com/upload/vod/20241229-1/ab53cde4ec09904ec65a9644fe74e3f1.jpg', '<p>&quot;Sinh con đau đớn, nuôi dưỡng thấy bà cố nội&quot; nhưng Isaku chưa bao giờ mong muốn trở thành con gái của một ông trùm yakuza. Đến khi cha mẹ cô qua đời trong một vụ tai nạn xe hơi khi cô mới 5 tuổi, ông nội xã hội đen của cô đã nhận cô về và nuôi nấng cô như một thành viên của gia tộc. Sau nhiều năm bị các bạn cùng trường tránh mặt vì mối quan hệ gia đình, Isaku cuối cùng cũng sẵn sàng xuất hiện ở cao trung, sống một cuộc sống bình thường và thậm chí có thể tìm thấy tình yêu... cho đến khi người hầu trung thành của gia đình và người giám hộ tận tâm của Isaku, Keiyai - 26 tuổi, vào trường ngay bên cạnh cô và thề sẽ bảo vệ cô khỏi tất cả những điều trên! Bây giờ cô ấy phải đối phó với một bộ giáp hiệp sĩ mặc áo giáp hút thuốc lá, cầm súng lục và điều phối trường cao trung? Một cô gái trẻ phải làm gì?!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akari Kito","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Mai Nakahara","avatar":""},{"name":"Yoshino Aoyama","avatar":""},{"name":"Hitomi Ueda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Uma Garota e Seu Cã