INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('horimiya-nhung-manh-ghep-bi-mat', 'Horimiya: Những Mảnh Ghép Bị Mất', 'Horimiya: The Missing Pieces', 'https://phimimg.com/upload/vod/20241229-1/a09e897dd451d150bfb52c3258633b1f.jpg', 'https://phimimg.com/upload/vod/20241229-1/a615e797705a62e067006eafa945a463.jpg', '<p>Kyouko Hori được nhiều người yêu thích, xinh đẹp và thông minh. Mặt khác, bạn cùng lớp của cô, Izumi Miyamura, người buồn tẻ và hay buồn bã, thường được miêu tả là một &quot;fanboy thất bại&quot;. Nhưng hai thanh niên khác biệt đáng kể này học được rằng có nhiều khía cạnh trong mọi câu chuyện — và con người — khi Miyamura, người có vô số hình xăm và khuyên, đồng thời rất đẹp trai, đột ngột xuất hiện trước cửa nhà Hori...

Câu chuyện lãng mạn ngọt ngào lại bắt đầu!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Haruka Tomatsu","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Yurie Kozakai","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Reina Kondo","avatar":""},{"name":"Daiki Yamashita","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Momo Asakura","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Yuka Terasaki","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Hisako Kanemoto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["堀与宫村 -piece-","动画 堀与宫村 -piece-","堀与宫村 拼图","Horimiya The Missing Pieces","Horimiya -piece-","Horimiya: piece","アニメ ホリミヤ -piece-","โฮริมิยะ สาวมั่นกับนายมืดมน: ส่วนเติมเต็ม","堀與宮村 -piece-","ホリミヤ -piece-"]', 1784690324250);
