INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('horimiya-nhung-manh-ghep-bi-mat', 'Horimiya: Những Mảnh Ghép Bị Mất', 'Horimiya: The Missing Pieces', 'horimiya: những mảnh ghép bị mất horimiya: the missing pieces haruka tomatsu koki uchiyama seiichiro yamashita yurie kozakai nobuhiko okamoto mao ichimichi reina kondo daiki yamashita jun fukuyama taku yashiro momo asakura ai kayano yuka terasaki daisuke ono daisuke namikawa hisako kanemoto 堀与宫村 -piece- 动画 堀与宫村 -piece- 堀与宫村 拼图 horimiya the missing pieces horimiya -piece- horimiya: piece アニメ ホリミヤ -piece- โฮริมิยะ สาวมั่นกับนายมืดมน: ส่วนเติมเต็ม 堀與宮村 -piece- ホリミヤ -piece-', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-dinh-cu', 'Những Người Định Cư', 'The Settlers', 'https://phimimg.com/upload/vod/20241229-1/b2201e1f2ad13e2c456a5814c7d30d6e.jpg', 'https://phimimg.com/upload/vod/20241229-1/be9004d6e9d6547bce4ef3dfa5d74d0f.jpg', '<p>Phim kể về một nhóm ba người đàn ông, Segundo, MacLennan và Bill, được giao nhiệm vụ bảo vệ một vùng đất rộng lớn của một ông chủ giàu có ở Chile vào năm 1901. Tuy nhiên, hành trình này nhanh chóng trở nên bạo lực khi nhóm này phát hiện ra rằng nhiệm vụ thực sự của họ là tiêu diệt người dân bản địa Onas trên quần đảo Tierra del Fuego. Bộ phim khám phá sâu sắc những vết thương lịch sử và những hành động bạo lực của thực tế, đồng thời đặt ra câu hỏi về việc liệu việc định cư và bành trướng lãnh thổ có thể xảy ra mà không có sự đổ máu và diệt chủng.</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'FHD', 'Argentina', 0, '[{"name":"Camilo Arancibia","avatar":""},{"name":"Heinz K. Krattiger","avatar":""},{"name":"Mark Stanley","avatar":""},{"name":"Alfredo Castro","avatar":""},{"name":"Benjamín Westfall","avatar":""},{"name":"Agustín Rittano","avatar":""},{"name":"Juan Imbert","avatar":""},{"name":"Mariano Monsalve","avatar":""},{"name":"Mariano Llinás","avatar":""},{"name":"Maxmiliano Speranza","avatar":""},{"name":"Joaquin Gabriel Pereira","avatar":""},{"name":"Daniel Sanchez","avatar":""},{"name":"Gianna Soledad Ceballos","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Jorg","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Поселенці","開拓者たち","Los colonos"]', 1784690324250);
