INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-cao-cua-pilecki', 'Báo Cáo Của Pilecki', 'Pilecki''s Report', 'https://phimimg.com/upload/vod/20241229-1/31e97d54c5fba94b210e452517794859.jpg', 'https://phimimg.com/upload/vod/20241229-1/26202d00ffa7fccc235a867e7e1b2a76.jpg', '<p>Câu chuyện về người anh hùng vĩ đại của Thế chiến thứ hai - Đại úy Witold Pilecki, người sau khi tiến hành các hoạt động quân sự đã phản đối sự thống trị của Liên Xô của Ba Lan. Tiểu sử của ông cho thấy cuộc đấu tranh anh hùng, đôi khi vô vọng, chống lại hai chủ nghĩa toàn trị tàn nhẫn của thế kỷ 20: Đức và Liên Xô.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Ba Lan', 0, '[{"name":"Przemysław Wyszyński","avatar":""},{"name":"Paulina Chapko","avatar":""},{"name":"Mariusz Jakus","avatar":""},{"name":"Karol Wróblewski","avatar":""},{"name":"Paweł Paprocki","avatar":""},{"name":"Jan Aleksandrowicz-Krasko","avatar":""},{"name":"Dominik Bąk","avatar":""},{"name":"Piotr Beluch","avatar":""},{"name":"Adam Blecharz","avatar":""},{"name":"Olgierd Blecharz","avatar":""},{"name":"Krzysztof Broda-Żurawski","avatar":""},{"name":"Adrian Brząkała","avatar":""},{"name":"Beata Chruścińska","avatar":""},{"name":"Piotr Dąbrowski","avatar":""},{"name":"Da","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Raport Pileckiego"]', 1784690324250);
