INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diva-cua-dao-hoang', 'Diva Của Đảo Hoang', 'Castaway Diva', 'https://phimimg.com/upload/vod/20241229-1/5694a3a6784bd6ebb8ea6eeb82c8b0b1.jpg', 'https://phimimg.com/upload/vod/20241229-1/b4b4435c24de3b6db418f442262f0e95.jpg', '<p>Mười lăm năm sau khi bị mắc kẹt trên một hòn đảo xa xôi, một ca sĩ đầy tham vọng tái hòa nhập xã hội - không dừng lại ở việc theo đuổi ước mơ trở thành diva.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Eun-bin","avatar":""},{"name":"Chae Jong-hyeop","avatar":""},{"name":"Kim Hyo-jin","avatar":""},{"name":"Cha Hak-yeon","avatar":""},{"name":"Kim Ju-hun","avatar":""},{"name":"Lee Re","avatar":""},{"name":"Bae Gang-hee","avatar":""},{"name":"Shin Joo-hyup","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Kim Min-seok","avatar":""},{"name":"Moon Woo-jin","avatar":""},{"name":"Kim Bo-jeong","avatar":""},{"name":"Yoon Jung-hoon","avatar":""},{"name":"Jeong Jun","avatar":""},{"name":"Oh Gyeong-hwa","avatar":""},{"name":"Kim Yoon-seol","avatar":""},{"name":"Lee Yoo-jun","avatar":""},{"name":"Seo Jeong-yeon","avatar":""},{"name":"Lee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Diva à Deriva","无人岛的Diva","مغنية الجزيرة المهجورة","ديفا المنبوذة","مغنية على جزيرة مهجورة","無人島的歌姬","Діва з безлюдного острова","Diva of the Deserted Island","Castaway Diva","무인도의 디바"]', 1784690324250);
