INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ban-toi-tham-thich-lai-quen-mang-kinh-roi', 'Cô Bạn Tôi Thầm Thích Lại Quên Mang Kính Rồi', 'The Girl I Like Forgot Her Glasses', 'https://phimimg.com/upload/vod/20241228-1/0ee4168cb268f07c526b481f972fcfbb.jpg', 'https://phimimg.com/upload/vod/20241228-1/1393fdbf4e33d7685862d804a04c63f3.jpg', '<p>Komura thích Mie, người ngồi cạnh anh ấy. Tuy nhiên, một ngày nọ, Komura phát hiện ra rằng đôi mắt của Mie trở nên rất hung dữ. Hóa ra cô ấy quên đeo kính, vì vậy Komura đã cố gắng giúp Mie, người không thể không nhìn rõ. Chỉ là Mie-san quên đeo kính hơn một ngày thôi. Đối mặt với tất cả các loại cuộc gặp gỡ gần gũi do tầm nhìn ba chiều kém, trái tim của Komura có thể chịu nổi không?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masahiro Ito","avatar":""},{"name":"Shion Wakayama","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我喜欢的女孩忘记戴眼镜","喜欢的女孩忘戴眼镜了","喜欢的人忘戴眼镜了","La chica que me gusta se ha olvidado sus gafas","Suki na Ko ga Megane o Wasureta","Suki na Ko ga Megane wo Wasureta","sukimega","Sukinakoga Wo Wasureta","好きめが","Любовь, не скрытая очками","我喜歡的女孩忘記戴眼鏡","好きな子がめがねを忘れた"]', 1784690324250);
