INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-den-trong-tim-phan-1', 'Bóng Đen Trong Tim (Phần 1)', 'The Dangers In My Heart (Season 1)', 'https://phimimg.com/upload/vod/20241227-1/b2344b9d232f9c2d57e07dfca6e42b7b.jpg', 'https://phimimg.com/upload/vod/20241227-1/77e070b3dee7126f74af452043b273f3.jpg', '<p>Ichikawa Kyotaro, một cậu học sinh luôn chật vật ở đáy xã hội của trường, thầm tin rằng mình là nhân vật chính đầy đau khổ trong một bộ phim tâm lý kinh dị nào đó. Cậu dành cả ngày để nghĩ ra những cách phá vỡ cuộc sống yên bình của các bạn cùng lớp và thầm thương trộm nhớ Yamada Anna, thần tượng của lớp. Nhưng Kyotaro không phải là một thiếu niên rắc rối như cậu giả vờ... và hóa ra Anna cũng có chút kỳ quặc!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shun Horie","avatar":""},{"name":"Hina Youmiya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["我内心的糟糕念头","Fui Robaron","Boku no Kokoro no Yabai Yatsu","僕ヤバ","BokuYaba","내 마음의 위험한 녀석 2기","내마위","Peligros en mi corazón","我內心的糟糕念頭","僕の心のヤバイやつ"]', 1784690324250);
