INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung-cua-cong-chua', 'Mê Cung Của Công Chúa', 'Princess And Labyrinth', 'https://phimimg.com/upload/vod/20241225-1/77bfb561f30ac64040fa9c314204400c.jpg', 'https://phimimg.com/upload/vod/20241225-1/b515276a2ecedc8a353b7723240bd2ba.jpg', '<p>Chuyển thể những câu chuyện cổ tích kinh điển, xen kẽ với những câu đố, đồng thời hướng dẫn khán giả tìm ra manh mối, cùng nhau đối mặt khó khăn và giải quyết vấn đề. Giúp trẻ phát triển khả năng nhận thức, tư duy logic và lý luận.</p>', 'Hoàn Tất (70/70)', 70, 'hoathinh', 'completed', 31, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '["Eet Smakelijk!"]', 1784690324250);
