INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-khoi-lac-duong-song-tu-truy-hung', 'Phong Khởi Lạc Dương: Song Tử Truy Hung', 'Gemini Mission', 'https://phimimg.com/upload/vod/20241225-1/41cd4d788a38ff99cf83fed9dc746c02.jpg', 'https://phimimg.com/upload/vod/20241225-1/7432cba85d7bbe29206cf29494c07375.jpg', '<p>Sau khi tình trạng hồ yêu hỗn loạn lắng xuống, kinh thành đã trở lại thịnh vượng và nhộn nhịp như trước đây, Vũ hoàng hậu có tâm trạng tốt và quyết định tổ chức một cuộc đi săn mùa thu thật hoành tráng, mời các hoàng tử, quý tộc và những người giỏi võ thuật tụ tập lại để thi đấu trên lưng ngựa và bắn cung. Mộ Dung Kỷ, khanh trẻ của Thổ Cốc Hỗn, cũng được mời tham gia cuộ đi săn mùa thu này, nhưng vô tình trở thành &quot;nghi phạm&quot; trong âm mưu ám sát hoàng hậu. Mộ Dung Kỷ không còn cách nào khác ngoài nhờ Bồi Khôn giúp đỡ, hy vọng anh có thể giúp tìm ra kẻ sát nhân thực sự và làm rõ danh tính của hắn. Để bảo vệ hòa bình của nhà Đường và nhân dân, đồng thời giúp đỡ bạn bè của mình, Bồi Khôn, Úy Trì Trụ, Hàn Đông Thanh và các cộng sự khác một lần nữa hợp lực điều tra vụ án và cuối cùng thủ phạm thực sự lên kế hoạch ám sát Vũ Hoàng hậu đã bị truy tìm, cuộc chiến giữa nhà Đường và Thổ Cốc Hỗn đã bị ngăn chặn.</p>', 'Full', 1, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Feng Qi Luo Yang Zhi Shuang Zi Zhui Xiong","Feng Qi Luoyang Shuangzi Zhui Xiong","Feng Qi Luoyang: Shuangzi Zhui Xiong","风起洛阳之双子追凶"]', 1784690324250);
