INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-khoi-lac-duong-song-tu-truy-hung', 'Phong Khởi Lạc Dương: Song Tử Truy Hung', 'Gemini Mission', 'phong khởi lạc dương: song tử truy hung gemini mission  feng qi luo yang zhi shuang zi zhui xiong feng qi luoyang shuangzi zhui xiong feng qi luoyang: shuangzi zhui xiong 风起洛阳之双子追凶', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-ky-quai', 'Khu Rừng Kỳ Quái', 'The Weird Forest', 'https://phimimg.com/upload/vod/20241225-1/03534a09fe030e192cbe7abe47750e5c.jpg', 'https://phimimg.com/upload/vod/20241225-1/6e4f5851677336e2d02155ebbae1c3c2.jpg', '<p>Mã Hoành Viễn dẫn mọi người vào khu vực cấm của núi Trường Bạch để tìm tàu hỏa, trên đường đi, Bắc Bá Thiên tham lam và ngu ngốc không muốn tuân theo quy tắc của rừng già, trong thời gian nghỉ ngơi, những con búp bê ma đã gây ra náo loạn trong trại. Trong khi chạy trốn, họ gặp một hang động dưới lòng đất, từng tên cướp bị hang động nuốt chửng, Miêu Nữ và Lão Hổ xuất hiện và đưa Mã Hoành Viễn và những người khác rời khỏi khu vực hang động nguy hiểm. Những người sống sót tiếp tục tiến vào làng Long Hưng và phát hiện ra rằng họ đang tổ chức tang lễ. Tên cướp La Cô đã nảy lòng tham, xúc phạm &quot;xác chết&quot;, nhưng người dân làng chỉ dám tức giận chứ không dám lên tiếng. Hòa thượng đã sắp xếp cho mọi người ở trong Đền thờ và cảnh báo họ không nên ra khỏi nhà vào ban đêm. Tuy nhiên, mọi người cho rằng Hòa thượng ngu dốt và không để ý đến cảnh báo của ông.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mou Fengbin","avatar":""},{"name":"Li Xinai","avatar":""},{"name":"Baode Wang","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"Mu Lan","avatar":""},{"name":"Yang Hanbin","avatar":""},{"name":"Zhou Xiaorui","avatar":""},{"name":"Li Yalin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Mysterious Things in the Deep Forest","深林诡事"]', 1784690324250);
