INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khu-rung-ky-quai', 'Khu Rừng Kỳ Quái', 'The Weird Forest', 'khu rừng kỳ quái the weird forest mou fengbin li xinai baode wang wang hongqian mu lan yang hanbin zhou xiaorui li yalin mysterious things in the deep forest 深林诡事', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-ha-thu-mo-nhan', 'Hoàng Hà Thủ Mộ Nhân', 'Tomb Keeper', 'https://phimimg.com/upload/vod/20241225-1/b60fa9133553a3528d02ab43d6485ed2.jpg', 'https://phimimg.com/upload/vod/20241225-1/b9e9a81445796d07cd90a294e29330ea.jpg', '<p>Theo truyền thuyết, sau khi Vương Mãng lên ngôi hoàng đế, để đảm bảo quyền lực của hoàng gia có thể truyền từ thế hệ này sang thế hệ khác, đồng thời để ngăn chặn những kẻ dòm ngó kho báu trong lăng mộ của mình, ông đặt mộ của mình trong một quan tài hình con thuyền lớn, sau đó chôn nó dưới lớp cát của dòng sông Hoàng Hà. Ông cũng thành lập bốn giáo phái lớn trên sông Hoàng Hà, bao gồm Đào Sa, Lao Thi, Quy Táng và Thủ Lăng để chôn cất và bảo vệ lăng mộ. Mặc dù họ tổ chức mua bán hàng hóa trên sông nhưng nhiệm vụ hàng đầu của họ vẫn là bảo vệ lăng mộ. Do đó, trong khu vực lưu vực sông Hoàng Hà, có truyền thuyết xa xưa về &quot;kho báu bí mật của mắt Long Vương&quot; truyền miệng. Trong thời Trung Hoa dân quốc, bốn bang hội hàng hải lớn nhất vùng do nhiều năm tham chiến và tác động của biến cố chính trị đã trở nên bất đồng và không còn tuân theo các quy tắc truyền thống. Ngoài ra, các lãnh đạo thế hệ trước của bốn tổ chức đã già nua. Bốn tổ chức thường xảy ra xung đột lớn với nhau, và tình hình dưới lòng sông Hoàng Hà trở nên hỗn loạn. Vương Ngũ Đẩu, một thành viên của tổ chức Đào Sa, từ nhỏ đã được nhận nuôi bơi thủ lĩnh nhưng do không rõ lai lịch nên anh luôn bị gia tộc coi thường. Vương Ngũ Đẩu tham gia vào một cuộc hành trình tìm kiếm kho báu dưới lòng sông Hoàng Hà, thực ra là để tìm ra danh tính thật của mình. Điều này đánh dấu sự khởi đầu của cuộc hành trình phiêu lưu dưới lòng sông Hoàng Hà.</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhou Chengao","avatar":""},{"name":"Liu Meitong","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Zhao Yiji","avatar":""},{"name":"Dmitriy Shcherbynsky","avatar":""},{"name":"Cai Qinxin","avatar":""},{"name":"Liu Chenglong","avatar":""},{"name":"Wang Kai Jie","avatar":""},{"name":"Mei Aoxue","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Gravekeeper Of The Yellow River","黄河守墓人"]', 1784690324250);
