INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-den-ben-toi', 'Nàng Đến Bên Tôi', 'She Came To Me', 'https://phimimg.com/upload/vod/20241224-1/f39e0d83e3798b577bf86c1410dd06d7.jpg', 'https://phimimg.com/upload/vod/20241224-1/5222eaf699807861c4a3c4cf058089c3.jpg', '<p>Một câu chuyện tình yêu trải qua nhiều thế hệ diễn ra tại thành phố New York hoa lệ, khi một nhà viết kịch đang cạn kiệt ý tưởng bất ngờ có một tao ngộ làm đảo lộn mọi thứ trong đời anh.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Peter Dinklage","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Evan Ellison","avatar":""},{"name":"Harlow Jane","avatar":""},{"name":"Joanna Kulig","avatar":""},{"name":"Brian d''Arcy James","avatar":""},{"name":"Judy Gold","avatar":""},{"name":"Anthony Roth Costanzo","avatar":""},{"name":"Samuel H. Levine","avatar":""},{"name":"Sue Jean Kim","avatar":""},{"name":"Gregg Edelman","avatar":""},{"name":"Aalok Mehta","avatar":""},{"name":"Chris Gethard","avatar":""},{"name":"Dale Soules","avatar":""},{"name":"Tommy Buck","avatar":""},{"name":"George She","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Une rencontre inattendue","Llegó a mí","Иди ко мне, детка","Viciados em Amor","Przyszła do mnie","او مرا درک می‌کند","她来找我","쉬 케임 투 미","היא באה אליי","Addicted to romance","She Came to Me"]', 1784690324250);
