INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-nang-nha-cai-phan-1', 'Cẩm Nang Nhà Cái (Phần 1)', 'Bookie (Season 1)', 'https://phimimg.com/upload/vod/20241224-1/b3a30acfbc5ba58b64988417dea23eab.jpg', 'https://phimimg.com/upload/vod/20241224-1/4095e7f2e70c810471e38324767b33f0.jpg', '<p>Một cặp đôi nhà cái thể thao bất hợp pháp gặp phải những tình huống tréo ngoe với đủ kiểu khách hàng trong quá trình hành sự.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sebastian Maniscalco","avatar":""},{"name":"Omar J. Dorsey","avatar":""},{"name":"Jorge Garcia","avatar":""},{"name":"Andrea Anders","avatar":""},{"name":"Vanessa Ferlito","avatar":""},{"name":"Maxim Swinton","avatar":""},{"name":"Rob Corddry","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["组头真命苦","סוכן ההימורים","How to Be a Bookie","Bookie"]', 1784690324250);
