INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-phieu-luu-keo-ngot', 'Chuyến Phiêu Lưu Kẹo Ngọt', 'Candy Cane Lane', 'https://phimimg.com/upload/vod/20241221-1/be331914e16d2c2c0325a6bd93021895.jpg', 'https://phimimg.com/upload/vod/20241221-1/c545ca7d7b545d69eb98028319f80c14.jpg', '<p>Eddie Murphy đảm nhận vai chính trong bộ phim phiêu lưu hài kịch dịp lễ này, và nhiệm vụ phải chiến thắng cuộc thi trang trí ngôi nhà Giáng sinh hàng năm của khu phố đã khiến anh vô tình ký một thỏa thuận với một yêu tinh tinh nghịch và biến Mười Hai Ngày Giáng Sinh trở thành sự thật.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Tracee Ellis Ross","avatar":""},{"name":"Jillian Bell","avatar":""},{"name":"Genneya Walton","avatar":""},{"name":"Thaddeus J. Mixson","avatar":""},{"name":"Madison Thomas","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Chris Redd","avatar":""},{"name":"Robin Thede","avatar":""},{"name":"David Alan Grier","avatar":""},{"name":"Ken Marino","avatar":""},{"name":"Anjelah Johnson-Reyes","avatar":""},{"name":"Lombardo Boyar","avatar":""},{"name":"Timothy Simons","avatar":""},{"name":"Danielle Pinnock","avatar":""},{"name":"D.C. Young Fl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Büyülü Kasaba","拐杖糖小道","Candy Cane Lane"]', 1784690324250);
