INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinland-saga-ban-hung-ca-viking-phan-2', 'Vinland Saga Bản Hùng Ca Viking (Phần 2)', 'Vinland Saga (Season 2)', 'https://phimimg.com/upload/vod/20240126-1/99fa9901142f1e671fbde7afedb369ea.jpg', 'https://phimimg.com/upload/vod/20240126-1/afe323695eae0535923e4e1ce4abf50e.jpg', '<p>Khi một thiên niên kỷ mới bắt đầu, Thorfinn vật lộn kiếm tìm ý nghĩa đời mình. Trong khi đó, vị vua mới của nước Anh tìm cách mở rộng lãnh thổ.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ishigami Shizuka","avatar":""},{"name":"Uemura Yuto","avatar":""},{"name":"Matsuda Kenichiro","avatar":""},{"name":"Uchida Naoya","avatar":""},{"name":"Ono Kensho","avatar":""},{"name":"Otsuka Akio","avatar":""},{"name":"Yasumoto Hiroki","avatar":""},{"name":"Takeuchi Shunsuke","avatar":""},{"name":"Sako Mayumi","avatar":""},{"name":"Hayashi Yu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324250);
