INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-jade-nguoi-trung-gian', 'Anh Jade: Người Trung Gian', 'The Middleman''s Love', 'https://phimimg.com/upload/vod/20241219-1/81127abe8f187c737c38b00b5776b5b5.jpg', 'https://phimimg.com/upload/vod/20241219-1/ae7c6f06d35e2466ee447a45a689c18a.jpg', '<p>Jade là một nhà thiết kế đồ họa. Anh ấy luôn đóng vai trò là người trung gian kể từ khi còn nhỏ. Xếp ở giữa. Điểm số của anh ấy ở trường cũng rất tầm thường. Những người xung quanh anh ấy, chẳng hạn như anh chị em hoặc bạn bè của anh ấy, đều ưa nhìn, và anh ấy luôn bị phớt lờ hoặc làm trung gian cho những người muốn tìm hiểu về anh chị em hoặc bạn bè của anh ấy. Jade đã ở trong tình trạng này nhiều năm và phải chấp nhận nó. Trong trái tim anh ấy không biết từ lúc nào đã hình thành một bức tường ngăn cản. Anh ấy đã hết hy vọng vào một mối quan hệ, bởi vì anh ấy đã biết rằng bất cứ ai đến với anh ấy chỉ là cố gắng gần gũi với những người xung quanh anh ấy. Một ngày nọ, một thực tập sinh tên Mai đến văn phòng của anh. Mai là một sinh viên xinh đẹp nổi tiếng trong số các cô gái trong văn phòng. Jade nhận thấy rằng Mai thường nhìn chằm chằm vào anh ta và bạn của anh ta là Uea. Anh ấy nghĩ Mai quan tâm đến Uea, vâng - anh ấy sẽ lại là người trung gian. Tuy nhiên, điều anh không biết là người thực sự thu hút Mai lại chính là anh. Điều gì xảy ra khi người trung gian không còn là người trung gian như trước nữa?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pharinyakorn Khansawa","avatar":""},{"name":"Koraphat Lamnoi","avatar":""},{"name":"Siraphop Manithikhun","avatar":""},{"name":"Supamongkon Wongwisut","avatar":""},{"name":"Peerapun Chungcharoenpanich","avatar":""},{"name":"Tai Thanaphat Khajornchaikul","avatar":""},{"name":"Sorntast Buangam","avatar":""},{"name":"Parnupat Anomakiti","avatar":""},{"name":"Teetut Chungmanirat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Phee Jet Khon Klang","Middleman Phee Jet","Middle Love","Middleman''s love Series","Middle Love Project","พี่เจตคนกลาง"]', 1784690324250);
