INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-game-rac-phan-1', 'Thợ Săn Game Rác (Phần 1)', 'Shangri-La Frontier (Season 1)', 'https://phimimg.com/upload/vod/20241219-1/122d5e58ac368b1a0668db3e55c508da.jpg', 'https://phimimg.com/upload/vod/20241219-1/af8c4a8e28195c50046a8d43147de0dd.jpg', '<p>Nam sinh cao trung năm hai Rakurou Hizutome chỉ quan tâm đến một chuyện duy nhất là tìm ra &quot;những trò chơi tồi tệ&quot; và phá đảo chúng. Kỹ năng chơi game của anh đã trở nên bất bại khi không ai sánh kịp và không còn trò chơi nào đủ tệ để anh có thể thưởng thức. Cho nên, khi được giới thiệu về một game VR mới Shangri-La Frontier, anh đã bước vào game ngay lập tức và bỏ qua cả hướng dẫn mở đầu dành cho tân binh. Nhưng liệu lão làng game thủ &quot;rank thách đấu&quot; có thể phá đảo những gì đang tồn tại trong Shangri-La Frontier?</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuma Uchida","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Umeka Shouji","avatar":""},{"name":"Asaki Yuikawa","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Megumi Han","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["香格里拉·开拓异境～粪作猎手挑战神作～","香格里拉边境","香格里拉边境~粪作猎人向神作游戏发起挑战~","香格里拉 · 开拓异境","シャングリラ・フロンティア ～クソゲーハンター、神ゲーに挑まんとす～","Shangri-La Frontier - Kusogē Hunter, Kamige ni Idoman to Su","Shangri-La Frontier - Kusogee Hunter, Kamige ni Idoman to Su","ShanFro","シャンフロ","Рубеж Шангри-Ла","Фронтир Шангри-ла","香格里拉・開拓異境～糞作獵手挑戰神作～","Кордон Шангрі-Ла","ShangriLa Frontier","Shangri-La Frontier","Thợ Săn Game Rác Thách Thức Game Cấp Thánh","シャングリラ・フロンティア"]', 1784690324250);
