INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-loan-mang-nguyen-co', 'Nổi Loạn Mang Nguyên Cớ', 'Riot! Rebel With A Cause', 'https://phimimg.com/upload/vod/20241218-1/101d67432edca51e97ef3a3c4daaa1d3.jpg', 'https://phimimg.com/upload/vod/20241218-1/955c9dafc10a10f60fb9d736f15c7caf.jpg', '<p>Cuộc náo loạn! theo chân bốn sinh viên trong một trường đại học nơi những hành vi sai trái của một giáo sư thường không được chú ý. Chán nản với sự bất công, họ tìm đến âm nhạc để khơi dậy một cuộc nổi loạn vang dội...</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 18, 2023, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Nelissa Edreena Nizam","avatar":""},{"name":"Mia Sara Shauki","avatar":""},{"name":"Tami Anadan","avatar":""},{"name":"Aniq Durar","avatar":""},{"name":"Nia Atasha","avatar":""},{"name":"Rashidi Ishak","avatar":""},{"name":"Iedil Dzuhrie Alaudin","avatar":""},{"name":"Amanda Ang","avatar":""},{"name":"Sue Tan","avatar":""},{"name":"Nasir Alaydrus","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Riot!: Rebel With a Cause"]', 1784690324250);
