INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('noi-loan-mang-nguyen-co', 'Nổi Loạn Mang Nguyên Cớ', 'Riot! Rebel With A Cause', 'nổi loạn mang nguyên cớ riot! rebel with a cause nelissa edreena nizam mia sara shauki tami anadan aniq durar nia atasha rashidi ishak iedil dzuhrie alaudin amanda ang sue tan nasir alaydrus riot!: rebel with a cause', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kubo-khong-de-toi-vo-hinh', 'Kubo Không Để Tôi Vô Hình', 'Kubo Won''t Let Me Be Invisible', 'https://phimimg.com/upload/vod/20241218-1/8fe38a88dad366c336591088e3f1c223.jpg', 'https://phimimg.com/upload/vod/20241218-1/1d1b5d65ffa010df40bfee8b2d06a7ed.jpg', '<p>Học sinh trung học Junta Shiraishi có một mục tiêu đơn giản là sống một tuổi trẻ viên mãn. Trên thực tế, sự vắng mặt của Shiraishi nghiêm trọng đến mức mọi người nghĩ rằng chỗ ngồi của anh ấy trong lớp luôn trống và lầm tưởng rằng anh ấy thường trốn học. Thậm chí còn có một tin đồn kỳ lạ, cho rằng những ai nhìn thấy Shiraishi sẽ được ban phước lành.

Người duy nhất nhận ra sự tồn tại của anh ấy là Nagisa Kubo, cô gái ngồi cạnh anh ấy. Tuy nhiên, thật không may cho anh ấy, Kubo thích trêu chọc anh ấy hàng ngày. Khi những trò hề khôi hài của Kubo tiếp tục liên quan đến Shiraishi, anh ấy có thể sớm phát hiện ra rằng tuổi trẻ của mình có thể không nhàm chán như anh ấy nghĩ ban đầu?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kana Hanazawa","avatar":""},{"name":"Kengo Kawanishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["久保同学不放过我","Kubo-san wa Mob wo Yurusanai","Kubo-san Doesn''t Leave Me Be (a Mob)","Kubo-san wa Boku o Yurusanai","久保さんは僕(モブ)を許さない","久保同學不放過我","Kubo Won''t Let Me Be Invisible","久保さんは僕を許さない"]', 1784690324250);
