INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dieu-tra-so-7-phan-1', 'Đội Điều Tra Số 7 (Phần 1)', 'Investigation Team No. 7 (Season 1)', 'https://phimimg.com/upload/vod/20241126-1/8c6f2635d41fe7872faf1905ef9b583b.jpg', 'https://phimimg.com/upload/vod/20241126-1/56cea416f80e17e455978e8c625be591.jpg', '<p>Đội Điều Tra Số 7 là một chuỗi các vụ án hình sự khắc họa quá trình phá án logic, gay cấn và chân thực của cảnh sát. Ngoài những pha hành động nghẹt thở cùng các tình tiết vụ án khó đoán, phim còn có những giây phút lắng đọng về cuộc đời của các chiến sĩ cảnh sát, những người luôn sẵn sàng hy sinh vì sự nghiệp bảo vệ sự yên bình cho người dân.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Tạ Minh Thảo","avatar":""},{"name":"Hà Việt Dũng","avatar":""},{"name":"Đỗ Thụy Hòa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Italian Restaurant"]', 1784690324250);
