INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-thanh-phu-phan-1', 'Dạ Thành Phú (Phần 1)', 'Ye Cheng', 'https://phimimg.com/upload/vod/20241212-1/ab16e70c7478d17a1003e7bfec75b2ce.jpg', 'https://phimimg.com/upload/vod/20241213-1/2b305207409670c3b1f464616c933d5d.jpg', '<p>Nữ đệ tử đệ nhất thế gia Sở Gia – Thư Thành ở Thanh Ngọc phái học nghệ. Cô bị tổ chức hắc ám truy lùng, sau đó được cứu bởi Thẩm Dạ. Người đã cải trang thành một thiếu niên gù lưng, cả hai đã dần nảy sinh tình cảm. Để che giấu thân phận, Thư Thành đành phải giả làm một công tử ăn chơi trác táng. Thư Thành muốn tiết lộ dung mạo tuyệt thế của Thẩm Dạ để giúp hắn trở thành đại mỹ nam đương thời. Nhưng lại phát hiện ra rằng Thẩm Dạ dường như có nhiều danh tính.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2023, 'Lồng Tiếng + Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Viên Hạo","avatar":""},{"name":"Tiết Huỷ Uy","avatar":""},{"name":"Trương Nhan Thư","avatar":""},{"name":"Trương Mộng Như","avatar":""},{"name":"Gia Trạch","avatar":""},{"name":"Tôn Hi Chi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["夜郎自大","夜城赋之离生","Ye Cheng Fu Zhi Li Sheng","Ye Cheng 2","Е Чен Перерождение","Ye Cheng","Reborn","夜城赋"]', 1784690324250);
