INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-cu-dop', 'Sau Cú Đớp', 'After the Bite', 'https://phimimg.com/upload/vod/20241210-1/9f52633290da01aee14a63fae563b195.jpg', 'https://phimimg.com/upload/vod/20241210-1/a94cc791f1be3dd2eb3f192e6f50401c.jpg', '<p>Sau khi xảy ra sự cố cá mập đớp tại một vùng biển vốn khá yên bình, một loạt các biện pháp được ban hành để đảm bảo an toàn cho cư dân. Đồng thời sự việc cũng dấy lên những câu hỏi về vấn đề biến đổi khí hậu tác động đến tập tính của động vật biển.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lisa Sette","avatar":""},{"name":"Greg Skomal","avatar":""},{"name":"Meg Winton","avatar":""},{"name":"Alec Wilkinson","avatar":""},{"name":"Crocker Snow","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["After the Bite"]', 1784690324250);
