INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('1000-la-chinh-minh-lon-len-khi-la-con-lai', '1000% Là Chính Mình Lớn Lên Khi Là Con Lai', '1000% Me: Growing Up Mixed', 'https://phimimg.com/upload/vod/20241209-1/642d0ebd990ff4e19bd81091f92a9aba.jpg', 'https://phimimg.com/upload/vod/20241209-1/adebff7eea1b3172889959f807c8d888.jpg', '<p>Bộ phim tài liệu kể câu chuyện của những đứa trẻ lai tại đất Mỹ. Phim thể hiện một góc nhìn nhân văn qua đôi mắt cảm nhận của những đứa trẻ về cách mà chúng được thế giới nhìn nhận.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["1000% Me: Growing Up Mixed"]', 1784690324250);
