INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-song-hoang-da', 'Dòng Sông Hoang Dã', 'River Wild', 'https://phimimg.com/upload/vod/20241206-1/8ca652d24bd36d3a8c838e2259704119.jpg', 'https://phimimg.com/upload/vod/20241206-1/e42b5710229b88dc15a5dee188d1399d.jpg', '<p>Đây là một bộ phim hành động phiêu lưu kịch tính của Mỹ, được làm lại từ phim The River Wild năm 1994. Phim kể về một cặp anh chị em yêu nhưng không tin tưởng nhau khi họ tham gia một chuyến đi thuyền trên dòng sông nước trắng cùng một nhóm nhỏ. Một trong những người bạn từ thời thơ ấu của họ hóa ra nguy hiểm hơn họ tưởng.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Brody","avatar":""},{"name":"Leighton Meester","avatar":""},{"name":"Taran Killam","avatar":""},{"name":"Olivia Swann","avatar":""},{"name":"Eve Connolly","avatar":""},{"name":"Nicholas Wittman","avatar":""},{"name":"Courtney Chen","avatar":""},{"name":"Matt Devere","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Rivière Sauvage","The River Wild","Río salvaje","狂野河流","נהר פראי","River Wild"]', 1784690324250);
