INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-han-nhieu-menh', 'Hảo Hán Nhiêu Mệnh', 'Hero Forgive', 'https://phimimg.com/upload/vod/20241204-1/68d0c58637bc2bb3f0d5f5cf06bd9b8f.jpg', 'https://phimimg.com/upload/vod/20241204-1/991482c343af645742da19d90117472a.jpg', '<p>Vương Hảo Hán một cậu bé nuôi ngựa, bị chủ nhân của mình bỏ tù vì bị kết án oan. Trong lúc trốn chạy, anh đã vô tình lấy thân phận của Tướng quân Diêu Viễn và thoát khỏi cái chết. Để cứu cha mình, Vương Uyển Nhi đã nhờ Hảo Hán giả làm Diêu Viễn, một người văn võ song toàn, với tấm lệnh bài miễn chết, Vương Hảo Hán liều lĩnh đã vướng vào một âm mưu lớn hơn.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qinniu Zhengwei","avatar":""},{"name":"Wang Luojia","avatar":""},{"name":"Xiao Xu","avatar":""},{"name":"Chen Bing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["好汉饶命"]', 1784690324250);
