INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('swing-into-romance', 'Swing Into Romance', 'Swing Into Romance', 'https://phimimg.com/upload/vod/20241204-1/72355325b80f625df3f68bab0ee7b21b.jpg', 'https://phimimg.com/upload/vod/20241204-1/5776a9c77453901296ffe962f9676854.jpg', '<p>Cựu vũ công Christine Sims khi cô tạm thời trở về quê hương dự Lễ hội mùa thu và được biết rằng Cửa hàng tổng hợp của gia đình cô đang gặp khó khăn. Để cứu vãn công việc kinh doanh, Christine sẽ phải phủi bụi đôi giày khiêu vũ của mình và đối mặt với chồng chưa cưới cũ của mình - và cô ấy thậm chí có thể tìm thấy tình yêu trong quá trình này.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Danica McKellar","avatar":""},{"name":"David Haydn-Jones","avatar":""},{"name":"Gleb Savchenko","avatar":""},{"name":"Brenda Bazinet","avatar":""},{"name":"Valerie Boyle","avatar":""},{"name":"Taya Messier","avatar":""},{"name":"Michelle Jackett-Webster","avatar":""},{"name":"Ipsita Paul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Swinging into Romance","Great American Autumn: Swing Into Romance","Swing Into Romance"]', 1784690324250);
