INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dau', 'Tình Đầu', 'First Love', 'https://phimimg.com/upload/vod/20241203-1/b6050c2c976a36e58c75af84b01053d3.jpg', 'https://phimimg.com/upload/vod/20241203-1/44da1b630cba97a7408e2dd1d836d0dc.jpg', '<p>Lưu Vân lầm lì, ít nói vì mang thân phận con gái kẻ giết người, điều tươi sáng duy nhất trong cuộc đời là khoảng thời gian cô gặp được Toàn Phong, hạnh phúc không được bao lâu thì biến cố xảy ra khiến giấc mơ của Lưu Vân tan vỡ. Cô biến mình trở thành Daisy lạnh lùng và trở về từ nước ngoài cùng vị hôn phu Leon- Tuấn Triết để ấp ủ kế hoạch trả thù mạo hiểm. Liệu ở ngã ba tình Toàn Phong và Tuấn Triết, Lưu Vân sẽ chọn nghe con tim hay lý trí?</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lê Thu","avatar":""},{"name":"Nguyễn Quốc Trường Thịnh","avatar":""},{"name":"Trịnh Xuân Nhản","avatar":""},{"name":"Trịnh Kim Chi","avatar":""},{"name":"Thanh Hiền","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["異搜店","Used Good"]', 1784690324250);
