INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-luat-su', 'Nữ Luật Sư', 'Female Lawyer', 'https://phimimg.com/upload/vod/20241203-1/1f410d7248538f0c17214086823760c1.jpg', 'https://phimimg.com/upload/vod/20241203-1/e89eb8f63453422a1ba9a829b8f760a6.jpg', '<p>Bộ phim tái hiện hai vụ án oan sai có thật năm xưa với sự đấu tranh của một nữ luật sư chính trực, dám đứng lên giành lại công bằng cho những người nghèo bị kẻ xấu hãm hại. Chồng cô là nhà báo, vì cám dỗ của đồng tiền nên đã bẻ cong ngòi bút của mình. Do đó khi cùng vướng vào một vụ án, cả hai vợ chồng phải đứng hai đầu chiến tuyến đối lập với nhau . Liệu sóng gió hôn nhân trong ngôi nhà nhỏ, bão tố lớn ở tòa án và xã hội sẽ cuốn hai vợ chồng về đâu?</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Kim Tuyến","avatar":""},{"name":"Ngọc Quỳnh","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Trung Dũng","avatar":""},{"name":"Trọng Trinh","avatar":""},{"name":"Lan Hương","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chega Mais"]', 1784690324250);
