INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-nguoc', 'Gió Ngược', 'Crosswind', 'https://phimimg.com/upload/vod/20241203-1/a3d3e4109b8b5a7fd35e1147e7e5b029.jpg', 'https://phimimg.com/upload/vod/20241203-1/b53eaa056dbef8c7202582116b4cbe1c.jpg', '<p>Bộ phim ca ngợi cuộc sống mộc mạc bình dị của những người dân Đồng Tháp lam lũ chịu thương chịu khó. Cho dẫu là một cuộc sống lênh đênh trên bè cá hay đạm bạc bên cánh đồng sen. Tiền bạc không dư nhưng nghĩa tình thì không thiếu. Họ an yên và hài lòng với cuộc sống dung dị của mình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lê Trung Hiếu","avatar":""},{"name":"Khánh Trinh","avatar":""},{"name":"Ngọc Lan","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"Hoàng Mập","avatar":""},{"name":"Mỹ Hạnh","avatar":""},{"name":"Trần Kim Hải","avatar":""},{"name":"Thanh Hiền","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Aswat Khafita"]', 1784690324250);
