INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gio-nguoc', 'Gió Ngược', 'Crosswind', 'gió ngược crosswind lê trung hiếu khánh trinh ngọc lan huy khánh hoàng mập mỹ hạnh trần kim hải thanh hiền aswat khafita', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-khong-phai-co-ay', 'Em Không Phải Cô Ấy', 'You''re Just Not Her', 'https://phimimg.com/upload/vod/20241203-1/e6df80f2840ead5c6d0e12440fc35c83.jpg', 'https://phimimg.com/upload/vod/20241203-1/42ab4d2d36f2c610c6981d6d5d6c53a8.jpg', '<p>Giám đốc kinh doanh thị trường thực phẩm - Lâm Tín (Đinh Tử Lãng) &nbsp;&amp; cô chủ tiệm thời trang Hạ Lợi (Phùng Doanh Doanh) sống chung với nhau nhiều năm. Tình yêu giữa họ ngày càng phai nhạt, quan điểm tương lai cũng khác nhau. Mâu thuẫn ngày càng tích tụ, Lợi đề nghị chia tay. Lâm Tín &nbsp;&amp; Hạ Lợi cãi nhau khi đang lái xe đua mới, dẫn đến tai nạn. Trải qua thời khắc sinh tử, Tín bị thương ở chân, còn Lợi may mắn không bị gì. Từ đó, Lợi thay đổi tính tình, việc gì cũng ưu tiên cho Tín. Mỗi khi Tín bị ăn hiếp, Lợi luôn giúp đỡ anh. Chị gái của Lâm Tín là Lâm Thiện (Xa Uyển Uyển), cấp trên Mạch Mỹ Na (Diêu Gia Ni), đối thủ cạnh tranh Lạc Vĩ Thao (Trương Dĩnh Khang), anh em tốt Mục Gia Kiệt (Mã Quán Đông) &nbsp;&amp; huấn luận viên thể hình Âu Văn (Huỳnh Đình Phong) nhiều lần gặp rắc rối vì Hạ Lợi. Lâm Tín tuy còn tình cảm &nbsp;&amp; sự lãng mạn như khi mới quen nhau với Hạ Lợi, nhưng Tín cảm nhận Lợi hoàn toàn là một người khác. Lâm Tín bắt đầu nghi ngờ tình yêu của Lợi đối với mình có phải chân thật không?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 7, 2023, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Đinh Tử Lãng","avatar":""},{"name":"Phùng Doanh Doanh","avatar":""},{"name":"Trương Dĩnh Khang","avatar":""},{"name":"Xa Uyển Uyển","avatar":""},{"name":"Diêu Giai Ni","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["You''re Just Not Her","妳不是她"]', 1784690324250);
