INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-nguoi-thua-ke', 'Bí Mật Người Thừa Kế', 'The Heirs Secret', 'https://phimimg.com/upload/vod/20241203-1/4f96e013ab8134c83736e169f61b79ba.jpg', 'https://phimimg.com/upload/vod/20241203-1/0ed5a7a1dfa36fe226164349ca10a83c.jpg', '<p>Vincent Phạm điều hành chuỗi nhà hàng khách sạn lớn nhất ở Đà Lạt sau khi cha mất. Tuy nhiên khối gia sản này lại vô cùng bí mật khiến Vincent khó mà giải thích được. Sau khi nhận thừa kế, mẹ anh quay về đầy bất ngờ, xung đột với người vợ mới cưới của anh, ngay cả bạn gái khi du học cũng cùng lúc xuất hiện khiến Vincent càng thêm căng thẳng. Vậy cuối cùng, &quot;bí ẩn&quot; về quyền thừa kế và phần phân chia tài sản của Chủ tịch hàng đầu chuỗi nhà hàng khách sạn du lịch là gì? Liệu Vincent có hạnh phúc với khối tài sản to lớn và gia đình đầy sóng gió?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Xuân Văn","avatar":""},{"name":"Triệu An","avatar":""},{"name":"Thu Bi","avatar":""},{"name":"Thân Thúy Hà","avatar":""},{"name":"Tùng Yuki","avatar":""},{"name":"Cao Hoàng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The F.B.I."]', 1784690324250);
