INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-luat-su', 'Bí Mật Của Luật Sư', 'Lawyer''s Secret', 'https://phimimg.com/upload/vod/20241202-1/e25ac2228621e176390bc0ea1621ed82.jpg', 'https://phimimg.com/upload/vod/20241202-1/f07102b3bb5f9c41c73908d7807fb742.jpg', '<p>Gia đình hạnh phúc của Tuấn Khải bỗng sụp đổ ngay trước mắt cậu vì âm mưu của một phụ nữ lạ mặt. Cha chết, mẹ mất tích, người chị thì lưu lạc, Tuấn Khải phải mất gần 20 năm mới có thể tìm lại những kẻ thủ ác năm xưa. Liệu Tuấn Khải sẽ làm gì để đưa những con người kia ra trước pháp luật, &quot; bí mật&quot; của chàng luật sư tài hoa sẽ như thế nào?</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Nhan Sỹ Toàn","avatar":""},{"name":"Mai Chi","avatar":""},{"name":"Trương Minh Quốc Thái","avatar":""},{"name":"Sơn SoHo","avatar":""},{"name":"Kim Phượng","avatar":""},{"name":"Lê Phương","avatar":""},{"name":"Châu Thiên Kim","avatar":""},{"name":"Nguyễn Quốc Trường Thịnh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Khotey Sikkey"]', 1784690324250);
