INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-sao-cung-de-thuong-mua-2', 'Dù Sao Cũng Dễ Thương (Mùa 2)', 'Tonikaku Kawaii (Season 2)', 'https://phimimg.com/upload/vod/20240308-1/363e8f272a5ef5a8999b077eaf1be280.jpg', 'https://phimimg.com/upload/vod/20240308-1/e1102578727e54e36b704c72aa6337cf.jpg', '<p>Chàng trai đã yêu cô gái bí ẩn và xinh đẹp ngay từ cái nhìn đầu tiên. Trước lời tỏ tình của anh, câu trả lời của cô là &quot;Nếu anh bằng lòng lấy em, thì em sẽ hẹn hò với anh&quot;? !</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324250);
