INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-dung-tin-co-ay', 'Xin Đừng Tin Cô Ấy', 'Too Beautiful To Lie', 'https://phimimg.com/upload/vod/20241126-1/5fb675c376653a7fb7145431e3490b75.jpg', 'https://phimimg.com/upload/vod/20241126-1/15b9583c0c0b1aff9b369c9646c3a5e8.jpg', '<p>Xin Đừng Tin Cô Ấy là một bộ phim hài lãng mạn Trung Quốc, dựa trên bộ phim Hàn Quốc cùng tên ra mắt năm 2004. Câu chuyện xoay quanh một người phụ nữ lừa đảo, giả làm bạn gái của con trai trưởng thôn, và dần dần trở thành một phần trong gia đình. Cô ấy tạo ra nhiều tình huống hài hước khi mưu đồ của mình bị phơi bày. Được đạo diễn bởi Yang Yuanhan, phim có sự tham gia của Zhang Ruonan và Yuhan Wu, khám phá các chủ đề về nhận dạng và tình cảm gia đình.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Ruonan","avatar":""},{"name":"Wu Yuhan","avatar":""},{"name":"Wu Yanshu","avatar":""},{"name":"Du Xiaoyu","avatar":""},{"name":"Wang Chengsi","avatar":""},{"name":"Bu Guanjin","avatar":""},{"name":"Ma Li","avatar":""},{"name":"Chang Yuan","avatar":""},{"name":"Wei Xiang","avatar":""},{"name":"Sihui Ma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Слишком красива, чтобы лгать","请别相信她"]', 1784690324250);
