INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-co-gi-de-xem-phan-1', 'Đâu Có Gì Để Xem (Phần 1)', 'Nothing to See Here (Season 1)', 'https://phimimg.com/upload/vod/20241125-1/b138aefac7c9b18c970d6b8d44a2c330.jpg', 'https://phimimg.com/upload/vod/20241125-1/97098e644cdf891a9413b1e550dfff1d.jpg', '<p>Khi một người khiếm thị theo đuổi ước mơ trở thành diễn viên hài, anh cùng người bạn thân bại não đối đầu với cả thế giới, bất kể có khó khăn như thế nào.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Alexis Arroyo","avatar":""},{"name":"Kike Vázquez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["여기에는 볼 것이 없어요","Ojitos de huevo"]', 1784690324250);
