INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cong-my', 'Vũ Công Mỹ', 'The American', 'https://phimimg.com/upload/vod/20241122-1/561d3e0e06745a656d6e11adccf673ef.jpg', 'https://phimimg.com/upload/vod/20241122-1/b02eff627a01f2d7af3e7ed6edc3f999.jpg', '<p>Joy Womack, một vũ công ballet người Mỹ, được nhận vào Học viện Ballet Bolshoi danh tiếng và đầy thử thách ở Moscow, với ước mơ trở thành một nữ diễn viên ballet vĩ đại. Tại đây, cô phải đối mặt với vô số khó khăn và thử thách, từ áp lực đào tạo khắc nghiệt đến sự cạnh tranh gay gắt. Dù gặp nhiều trở ngại, Joy vẫn quyết tâm theo đuổi đam mê và chinh phục giấc mơ của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Talia Ryder","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Oleg Ivenko","avatar":""},{"name":"Natasha Alderslade","avatar":""},{"name":"Natalia Osipova","avatar":""},{"name":"Charlotte Ubben","avatar":""},{"name":"Borys Szyc","avatar":""},{"name":"Tomasz Kot","avatar":""},{"name":"Karolina Gruszka","avatar":""},{"name":"Martin Hugh Henley","avatar":""},{"name":"Ewa Rodart","avatar":""},{"name":"Tamiła Dudnik","avatar":""},{"name":"Martyna Wrzesińska","avatar":""},{"name":"Weronika Juchimiuk","avatar":""},{"name":"Julia Bielska","avatar":""},{"name":"Zuzanna Burak","avatar":""},{"name":"Zu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Joika","Joika - A un passo dal sogno","Πρίμα Μπαλαρίνα Joika","Джойка","The American"]', 1784690324250);
