INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-trang-trai-nho', 'Bí Mật Trang Trại Nho', 'Wineville', 'https://phimimg.com/upload/vod/20241108-1/556e8341d4bb5ce967ca922b681a1df2.jpg', 'https://phimimg.com/upload/vod/20241108-1/0ef1313fbf8d0099baebf6619e438308.jpg', '<p>Một người phụ nữ đã trốn khỏi vườn nho của người cha vũ phu khi còn là thiếu niên trở về sau khi ông qua đời. Cô khám phá ra những bí mật đen tối của gia đình, đã lan rộng, dẫn đến bạo lực và cái chết, khi cô giải quyết điền trang.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brande Roderick","avatar":""},{"name":"Texas Battle","avatar":""},{"name":"Carolyn Hennesy","avatar":""},{"name":"Casey King","avatar":""},{"name":"Taylor Murphy-Sinclair","avatar":""},{"name":"Chris Schellenger","avatar":""},{"name":"Christie Nicole Chaplin","avatar":""},{"name":"Keaton Roderick Cadrez","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wineville"]', 1784690324250);
