INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-ho-voi-ong-gia-tuyet', 'Hẹn Hò Với Ông Già Tuyết', 'Dating Santa', 'https://phimimg.com/upload/vod/20241108-1/1a848de99a21dbec9eefc9a11c0db3d0.jpg', 'https://phimimg.com/upload/vod/20241108-1/69706b6c2010701186de041766a4d81d.jpg', '<p>Lucía là một bà mẹ đơn thân hết lòng vì cô con gái nhỏ Leo bị ám ảnh bởi Giáng sinh đến nỗi cô ấy đã tự đóng mình lại với ý tưởng lãng mạn. Nhưng khi cô ấy đồng ý đi hẹn hò với đầu bếp Sergio mơ mộng, tia lửa tình yêu là không thể phủ nhận.</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Ana Serradilla","avatar":""},{"name":"David Chocarro","avatar":""},{"name":"Olivia Duflos","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Santa, mi amor"]', 1784690324250);
