INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-minh-chang-muon-bi-dau-nen-minh-se-nang-toi-da-luc-phong-ngu-mua-2', 'Vì Mình Chẳng Muốn Bị Đau Nên Mình Sẽ Nâng Tối Đa Lực Phòng Ngự (Mùa 2)', 'BOFURI: I Don''t Want to Get Hurt, so I''ll Max Out My Defense. (Season 2)', 'https://phimimg.com/upload/vod/20241108-1/f6145b139a6eadf0f2f6ec7f07ca3c92.jpg', 'https://phimimg.com/upload/vod/20241108-1/6f864870c5e63d5d2266be41c51b251b.jpg', '<p>Sau khi nhận được lời mời từ người bạn Risa Shiromine, Kaede Honjou bắt đầu chơi trò chơi VRMMO New World Online với tư cách là nhân vật Maple. Thiếu kiến thức về trò chơi, cô phân bổ tất cả các điểm trạng thái của mình để phòng thủ. Kết quả là, chuyển động của cô rất chậm, cô không thể sử dụng phép thuật, và thậm chí còn bị lũ thỏ tấn công. Tuy nhiên, cô có được một kỹ năng gọi là Phòng thủ tuyệt đối nhờ phát huy tối đa điểm sinh lực của mình và kỹ năng phản đòn giết chết trong một đòn duy nhất. Một người mới làm quen với phong cách pháo đài di động với một kỹ năng độc hại khiến tất cả các cuộc tấn công không hợp lệ và vượt qua mọi chướng ngại vật, cô ấy đi vào cuộc phiêu lưu, coi thường sự bất thường của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaede Hondo","avatar":""},{"name":"Ruriko Noguchi","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Satomi Arai","avatar":""},{"name":"Ai Kakuma","avatar":""},{"name":"Nanaka Suwa","avatar":""},{"name":"Noriaki Sugiyama","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Takumi Yamazaki","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Nobutoshi Canna","avatar":""},{"name":"Rina Sato","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Yuko Minaguchi","avatar":""},{"name":"Sakura Tange","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["怕痛的我，把防御力点满就对了","Itai No Wa","BOFURI : Je suis pas venue ici pour souffrir alors j''ai tout mis en défense","Itai no wa Iya nanode Bougyoryoku ni Kyokufuri Shitai to Omoimasu.","Bofuri","痛いのは嫌なので防御力に極振りしたいと思います。2","Itai no wa Iya nano de Bōgyoryoku ni Kyokufuri Shitai to Omoimasu.","아픈 건 싫으니까 방어력에 올인하려고 합니다","Разве я не просила усреднить мои способности в следующей жизни?!","怕痛的我，把防禦力點滿就對了","Я ненавиджу біль, тому покращу свій захист на максимум","Мені не подобається біль, тому качатиму тільки захист","Не люблю біль, тому вкачаю все у захист","Не люблю біль, тому все вкачаю у захист","I Do Not Want Pain, so I Would Like to Focus on Defense","I Hate Being in Pain, so I Think I''ll Make a Full Defense Build","I Hate Getting Hurt, so I Put All My Skill Points Into Defense","Sợ Đau Nên Tôi Tăng Hết Vào Phòng Thủ","痛いのは嫌なので防御力に極振りしたいと思います。"]', 1784690324250);
