INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-mau-giua-dem-dong', 'Phép Màu Giữa Đêm Đông', 'White Bird', 'https://phimimg.com/upload/vod/20241106-1/248200b5a02f7b00668915e183ffb2b4.jpg', 'https://phimimg.com/upload/vod/20241106-1/12189dad41fe299b4566f94405595a2b.jpg', '<p>Chuyển tới một ngôi trường mới, Julian tự cô lập bản thân, không để tâm với mọi người xung quanh. Biết vậy, bà nội của cậu, Sara Blum giãi bày tâm sự với Julian và tiết lộ cho cậu câu chuyện về thời niên thiếu của mình. Dưới thời Pháp bị Đức Quốc xã chiếm đóng, một cậu bé đã mạo hiểm tất cả để bảo vệ tính mạng bà. Trong đêm đen của chiến tranh và bom đạn, tình yêu, tình thân, tình người vẫn luôn hiện hữu.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ariella Glaser","avatar":""},{"name":"Orlando Schwerdt","avatar":""},{"name":"Bryce Gheisar","avatar":""},{"name":"Gillian Anderson","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Jo Stone-Fewings","avatar":""},{"name":"Patsy Ferran","avatar":""},{"name":"Stuart McQuarrie","avatar":""},{"name":"Olivia Ross","avatar":""},{"name":"Ishai Golan","avatar":""},{"name":"Nadine Leon Gobet","avatar":""},{"name":"John Bubniak","avatar":""},{"name":"Jim High","avatar":""},{"name":"Philip Lenkowsky","avatar":""},{"name":"James Beaumont","avatar":""},{"name":"Teagan Stark","avatar":""},{"name":"Priya G","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["White Bird: A Wonder Story","Белая птица: История чуда","Білий птах: Нове диво","Θαύμα: Λευκό πουλί","پرنده سفید","Alas blancas","