INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('romeo-va-chuc-anh-dai', 'Romeo Và Chúc Anh Đài', 'Romeo And His Butterfly Lover', 'https://phimimg.com/upload/vod/20241105-1/68bb186fb6adddb5b534a80d6a054f3c.jpg', 'https://phimimg.com/upload/vod/20241105-1/c982e941d71db61c8c65a618084cb6d8.jpg', '<p>Một đất nước xa xôi, một không gian không biết tên. Hai câu chuyện tình yêu kinh điển nhất tái hiện hoàn toàn mới. Yêu hận đan xen, phổ thành một tình khúc thê lương, oanh liệt.

“Em tưởng đâu em phải từ bỏ tình yêu, nhưng thì ra bấy lâu, tình yêu không hề từ bỏ em”, đây là sự trải nghiệm đối với cuộc đời của Chúc Anh Đài.

“Cho dù đêm tối dài như thế nào, ngày mới chắc chắn sẽ tới”, đây là thái độ làm người của Romeo.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2023, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Moses Chan","avatar":""},{"name":"Aimee Chan","avatar":""},{"name":"Kalok Chow","avatar":""},{"name":"Kayan Yau","avatar":""},{"name":"Elena Kong Mei-Yee","avatar":""},{"name":"Joman Chiang","avatar":""},{"name":"Timothy Cheng Chi-Sing","avatar":""},{"name":"Felix Ng","avatar":""},{"name":"Judy Kwong","avatar":""},{"name":"Tsui Wing","avatar":""},{"name":"Kyle Lee Ka-Ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Romeo And His Butterfly Lover","羅密歐與祝英台","Ромео и Чжу Интай"]', 1784690324250);
