INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-nhung-gi-ta-da-yeu', 'Vì Những Gì Ta Đã Yêu', 'All That We Loved', 'https://phimimg.com/upload/vod/20241104-1/e2c10d50514eeb491c958d86130bfc62.jpg', 'https://phimimg.com/upload/vod/20241104-1/96b00469107ad79a6e349e76f8b88079.jpg', '<p>&quot;All That We Loved&quot; (hoặc &quot;Everything We Loved&quot;) xoay quanh câu chuyện tình bạn và tình yêu của những thiếu niên tuổi 18. Hai người bạn thân Go Yoo (Sehun) và Go Joon Hee (Jo Joon Young) cùng đem lòng yêu cô bạn mới chuyển trường - Han So Yeon (Jang Yeo Bin).

Khi Joon Hee bị bệnh nặng, Go Yoo đã quyết định hiến một bên thận cho bạn thân. Từ đây, bộ phim đi sâu vào chủ đề trí nhớ tế bào, đưa ra giả thuyết ký ức được chuyển giao giữa những người nhận ghép tạng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"세훈","avatar":""},{"name":"Cho Jun-young","avatar":""},{"name":"Jang Yeo-bin","avatar":""},{"name":"송재림","avatar":""},{"name":"정유진","avatar":""},{"name":"이승준","avatar":""},{"name":"박은혜","avatar":""},{"name":"Jeong Hye-seon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Everything That We Loved","우리가 사랑했던 모든 것"]', 1784690324250);
