INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-gian-nhat-chien', 'Vô Gian Nhất Chiến', 'Endless Battle', 'https://phimimg.com/upload/vod/20241031-1/185f265da1f071041bd877be3dbe246c.jpg', 'https://phimimg.com/upload/vod/20241031-1/1f6574644262d74d4291ce4b2d487049.jpg', '<p>Bành Kiến Trung, một cảnh sát chống ma túy với lý tưởng công lý kiên định, nhưng bỗng một ngày, anh phát hiện người em trai Bành Kiến Thành dường như có dính líu đến một tập đoàn ma túy. Liệu anh có đủ &quot;công tư phân minh&quot; để tìm ra sự thật và triệt phá đường dây tội phạm này?</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Tạ Thiên Hoa","avatar":""},{"name":"Thái Tư Bối","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["無間一戰","Endless Battle"]', 1784690324250);
