INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-khong-thanh-hien-thuc', 'Giấc Mơ Không Thành Hiện Thực', 'La Chimera', 'https://phimimg.com/upload/vod/20241031-1/03d8a3eb350e2c561161f65efdfcd284.jpg', 'https://phimimg.com/upload/vod/20241031-1/361205253ba742004b50676558852326.jpg', '<p>Bộ phim lấy bối cảnh vào những năm 1980 và xoay quanh nhân vật chính là Arthur, một nhà khảo cổ học người Anh đang đau khổ vì mất đi tình yêu của người yêu cũ, Beniamina. Arthur cùng nhóm trẻ em khảo cổ học tìm kiếm và đánh cắp các hiện vật lịch sử của người Etruscan. Bộ phim đã nhận được nhiều giải thưởng danh giá tại các liên hoan phim.</p>', 'Full', 1, 'single', 'completed', 27, 2023, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Josh O''Connor","avatar":""},{"name":"Carol Duarte","avatar":""},{"name":"Alba Rohrwacher","avatar":""},{"name":"Isabella Rossellini","avatar":""},{"name":"Vincenzo Nemolato","avatar":""},{"name":"Lou Roy-Lecollinet","avatar":""},{"name":"Giuliano Mantovani","avatar":""},{"name":"Gian Piero Capretto","avatar":""},{"name":"Melchiorre Pala","avatar":""},{"name":"Ramona Fiorini","avatar":""},{"name":"Luca Gargiullo","avatar":""},{"name":"Yile Vianello","avatar":""},{"name":"Barbara Chiesa","avatar":""},{"name":"Elisabetta Perotto","avatar":""},{"name":"Chi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["A Quimera","Химера","לה צ''ימרה","La Quimera","奇美拉","墓泥棒と失われた女神","Haka Dorobō to Ushinawareta Megami","Η χίμαιρα","La Chimère","La chimera"]', 1784690324250);
