INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-gap-lai-em-tren-ngon-doi-hoa-no', 'Nếu Gặp Lại Em Trên Ngọn Đồi Hoa Nở', 'Till We Meet Again on the Lily Hill', 'https://phimimg.com/upload/vod/20241029-1/f3de34a4632fabbc69809f271be9b66c.jpg', 'https://phimimg.com/upload/vod/20241029-1/8758199d68a295a8fa4cdfc8e48a5219.jpg', '<p>Là một kỳ tích xúc động từ phòng vé Nhật Bản với 3,5 triệu vé được bán ra, bộ phim xoay quanh Yuri, một nữ sinh trung học đã vô tình xuyên không về Nhật Bản 70 năm trước. Tại đây, cô gặp gỡ một chàng trai tên Akira là một phi công cảm tử. Sau những ngày tháng kề bên, Yuri dần đem lòng cảm mến người con trai này.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"福原遥","avatar":""},{"name":"水上恒司","avatar":""},{"name":"伊藤健太郎","avatar":""},{"name":"上川周作","avatar":""},{"name":"小野塚勇人","avatar":""},{"name":"出口夏希","avatar":""},{"name":"坪倉由幸","avatar":""},{"name":"松坂慶子","avatar":""},{"name":"中嶋朋子","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Ano Hana ga Saku Oka de, Kimi to mata Deaetara","I Wish I Could Meet You Again on the Hill Where That Flower Blooms","あの花が咲く丘で、君とまた出会えたら。"]', 1784690324250);
