INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-danh-up-trong-bang-tuyet-2', 'Trận Đánh Úp Trong Băng Tuyết 2', 'Ice Sniper 2', 'https://phimimg.com/upload/vod/20241029-1/4c6aa31d72c2443dd9a8b8d2676d7ef9.jpg', 'https://phimimg.com/upload/vod/20241029-1/8d2d8662bcc49933bdd772e17a41ef64.jpg', '<p>Các thế lực siêu nhiên đưa ra lời kết tội đẫm máu, đày con người xuống địa ngục và nâng đỡ nhóm tôn giáo được thành lập dựa trên ý tưởng công lý của thần thánh.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Xiaoqing","avatar":""},{"name":"Wang Xinjun","avatar":""},{"name":"于荣光","avatar":""},{"name":"Gan Ting Ting","avatar":""},{"name":"Ren Qing''an","avatar":""},{"name":"Chi Zhiqiang","avatar":""},{"name":"Jiexi Chen","avatar":""},{"name":"Zhang Guanbin","avatar":""},{"name":"Ai Li-Ku","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["冰雪狙击2"]', 1784690324250);
