INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-phieu-tu-hinh', 'Lá Phiếu Tử Hình', 'The Killing Vote', 'https://phimimg.com/upload/vod/20231202-1/e5852b3b32904a6f4fe45b36387b9056.jpg', 'https://phimimg.com/upload/vod/20230923-1/0f17e12592b743253d24e073149a4395.jpg', '<p>The Killing Vote&nbsp;là một bộ&nbsp;phim Hàn Quốc&nbsp;thuộc thể loại&nbsp;kinh dị, tâm lý tội phạm của đạo diễn Park Shin Woo, được chuyển thể từ webtoon nổi tiếng cùng tên, đăng nhiều kỳ trên Kakao Webtoon và KakaoPage. Trong phim sẽ có sự tham gia của dàn diễn viên:&nbsp;Park Hae Jin, Park Sung Woong, Lim Ji Yeon,... Nội dung phim The Killing Vote xoay quanh câu chuyện kể về hành trình đi tìm danh tính thực sự của một người tên Gaetal. Hắn ta mang một chiếc mặt nạ chó và chuyên xử tử những tên tội phạm ghê tởm. Khi những tên tội phạm ghê tởm trốn tránh sự trừng phạt của pháp luật, tất cả công dân trên 18 tuổi sẽ nhận được một tin nhắn văn bản thăm dò ý kiến của họ về việc liệu người đó có nên nhận án tử hình hay không. Nếu hơn 50% phản hồi ủng hộ án tử hình, người đó sẽ bị Dog Mask giết. Trong khi đó, cảnh sát đuổi theo Dog Mask và ba người tham gia. Kim Moo Chan là trưởng nhóm điều tra đầu tiên tại Cơ quan cảnh sát phía Nam. Anh chỉ quan tâm đến sự nghiệp của mình ở cơ quan cảnh sát. Kwon Seok Joo từng là một học giả luật nổi tiếng, nhưng anh đã giết kẻ hiếp dâm đã tấn công con gái nhỏ của mình rồi đầu thú với cảnh sát. Bây giờ anh ta đang ở trong tù và anh ta được các tù nhân khác gọi là Giáo sư. Joo Hyun là một sĩ quan cảnh sát đã làm việc tại Cục An toàn Mạng tại Cơ quan Cảnh sát Thủ đô Seoul trong 5 năm.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Hae Jin","avatar":""},{"name":"Lim Ji Yeon","avatar":""},{"name":"Park Sung Woong","avatar":""},{"name":"Kim Yoo Mi","avatar":""},{"name":"Shin Jung Keun","avatar":""},{"name":"Kim Kwon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324250);
