INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loan-chien-lanh-chua', 'Loạn Chiến Lãnh Chúa', 'Kubi', 'https://phimimg.com/upload/vod/20241028-1/632f1d3e67a86b1c909ee376277f60e5.jpg', 'https://phimimg.com/upload/vod/20241028-1/c63d0c7773262339a9987240cfe2b399.jpg', '<p>“Kubi” (2023) xoay quanh thời kỳ Nhật Bản hỗn loạn, khi các lãnh chúa đối đầu nhau để tranh giành quyền lực. Lãnh chúa Oda Nobunaga, với tham vọng thống nhất đất nước, đã phát động chiến tranh chống lại nhiều gia tộc đối địch. Tuy nhiên, một trong những thuộc hạ của ông, Araki Murashige, nổi loạn và sau đó biến mất một cách bí ẩn.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"ビートたけし","avatar":""},{"name":"西島秀俊","avatar":""},{"name":"加瀬亮","avatar":""},{"name":"浅野忠信","avatar":""},{"name":"大森南朋","avatar":""},{"name":"中村獅童","avatar":""},{"name":"木村祐一","avatar":""},{"name":"遠藤憲一","avatar":""},{"name":"勝村政信","avatar":""},{"name":"桐谷健太","avatar":""},{"name":"小林薫","avatar":""},{"name":"岸部一徳","avatar":""},{"name":"寺島進","avatar":""},{"name":"六平直政","avatar":""},{"name":"大竹まこと","avatar":""},{"name":"津田寛治","avatar":""},{"name":"荒川良々","avatar":""},{"name":"寛一郎","avatar":""},{"name":"Jun Soejima","avatar":""},{"name":"中村育二","avatar":""},{"name":"矢島健一","avatar":""},{"name":"東根作寿英","avatar":""},{"name":"堀部圭亮","avatar":""},{"name":"仁科貴","avatar":""},{"name":"柴田理恵","avatar":""},{"name":"平原テツ","avatar":""},{"name":"Hawking Aoyama","avatar":""},{"name":"Amawres Ani","avatar":""},{"name":"日野陽仁","avatar":""},{"name":"國本鍾建","avatar":""},{"name":"柳憂怜","avatar":""},{"name":"Takeshi Ohnishi","avatar":""},{"name":"Sotaro Tanaka","avatar":""},{"name":"Kenzo Ryu","avatar":""},{"name":"佐藤銀平","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c38