INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-giac', 'Cảnh Giác', 'Vigilante', 'https://phimimg.com/upload/vod/20241026-1/9c0ac74f16c790bace383ce21cf407ef.jpg', 'https://phimimg.com/upload/vod/20241026-1/9cb4177c07d196ece3d695ed20edc2bb.jpg', '<p>Khi Kim Ji Yong còn nhỏ, mẹ anh đã bị đánh chết trên đường phố. Thủ phạm chỉ nhận ba năm rưỡi tù. Kim Ji Yong - bây giờ đã trưởng thành - thấy rằng kẻ giết mẹ mình không thay đổi chút nào. Ji Yong tự mình giải quyết vấn đề và đánh đập anh ta một cách tàn nhẫn.

Sau đó, Kim Ji Yong bắt đầu sống hai cuộc sống hoàn toàn khác nhau. Vào các ngày trong tuần, anh ấy là một sinh viên gương mẫu tại trường đại học cảnh sát. Vnsub.net ,Trong những ngày cuối tuần, anh ta trừng phạt những tên tội phạm đã nhận bản án nhẹ và tiếp tục thực hiện các hành vi phạm tội. Bây giờ được gọi là Vigilante, Ji Yong nhận được sự giúp đỡ từ người ngưỡng mộ Cho Kang Ok. Trong khi đó, thám tử Cho Heon đuổi theo người đàn ông được gọi là Vigilante.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"남주혁","avatar":""},{"name":"유지태","avatar":""},{"name":"김소진","avatar":""},{"name":"이준혁","avatar":""},{"name":"권해효","avatar":""},{"name":"Lee Seung-woo","avatar":""},{"name":"이서환","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["الحارس","آتش به اختیار","비질란테","ပြည်သူ့ဘက်တော်သား","القائم بالقانون","Месник","Вартівник","Vigilante"]', 1784690324250);
