INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-du-nguyen', 'Lạc Du Nguyên', 'Wonderland Of Love', 'https://phimimg.com/upload/vod/20241020-1/eccf2f8ce8b56e38b2861de0038151bd.jpg', 'https://phimimg.com/upload/vod/20241020-1/b6718d2d47edd19ba7cdd1fcfca02fca.jpg', '<p>Triều đình hỗn loạn, hoàng quyền sụp đổ. Hoàng tôn Lý Nghi phụ trách trấn thủ biên quan bị buộc phải gánh vác trọng trách dẹp loạn. Chàng cùng Thôi Lâm, con gái duy nhất của tướng quân đang che giấu thân phận, mỗi người thống lĩnh một đội quân cùng cuốn vào cuộc chiến. Hai người đấu tranh trong tối ngoài sáng, ra chiêu hiểm giữa nhiều phe thế lực. Sau vô số các cuộc giao tranh, hai đối thủ ngang sức ngang tài yêu nhau lắm cắn nhau đau.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"許凱","avatar":""},{"name":"景甜","avatar":""},{"name":"鄭合惠子","avatar":""},{"name":"高寒","avatar":""},{"name":"赵嘉敏","avatar":""},{"name":"劉冬沁","avatar":""},{"name":"Dai Yi","avatar":""},{"name":"何奉天","avatar":""},{"name":"曾黎","avatar":""},{"name":"Apollo Yu","avatar":""},{"name":"Tang Guo-Zhong","avatar":""},{"name":"Yu Tong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["乐游原","عالَم شگفت‌انگیز عشق","พสุธารักเคียงใจ","樂遊原"]', 1784690324250);
