INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lac-du-nguyen', 'Lạc Du Nguyên', 'Wonderland Of Love', 'lạc du nguyên wonderland of love 許凱 景甜 鄭合惠子 高寒 赵嘉敏 劉冬沁 dai yi 何奉天 曾黎 apollo yu tang guo-zhong yu tong 乐游原 عالَم شگفت‌انگیز عشق พสุธารักเคียงใจ 樂遊原', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hau-cua-thieu-gia-mu', 'Người Hầu Của Thiếu Gia Mù', 'Romance With Blind Master', 'https://phimimg.com/upload/vod/20241019-1/7f37a1441ca58ebc96b8e06f01c49db1.jpg', 'https://phimimg.com/upload/vod/20241019-1/547e476d25c3ccb8003095d49de5f9e6.jpg', '<p>Nguyễn Thanh Điềm bị mẹ kế ngấm ngầm ký hợp đồng riêng làm quản gia cho Nhậm Hạo Minh - vị tổng tài độc đoán. Điều tồi tệ là vị tổng tài này là một tên mù với tính cách vô cùng bạo lực. Tệ hơn thế nữa là Nguyễn Thanh Điềm có mối quan hệ thâm sâu với người đàn ông này! Nguyễn Thanh Điềm bị ép ở lại với Nhậm Hạo Minh và bị Nhậm Hạo Minh chì chiết thậm tệ! Ông trời thương Nguyễn Thanh Điềm tốt bụng, ngày ngày sống chung, cô và Nhậm Hạo Minh yêu nhau. Tuy nhiên, khi Nhậm Hạo Minh lấy lại được thị lực sau ca phẫu thuật và cầu hôn Nguyễn Thanh Điềm, Nguyễn Thanh Điềm đã bị chị gái Nguyễn Tâm Tâm phản bội, kết quả là Nhậm Hạo Minh và Nguyễn Tâm Tâm đính hôn. Nguyễn Thanh Điềm chỉ có thể bí mật quan tâm đến Nhậm Hạo Minh, nhưng Nhậm Hạo Minh lại coi cô không khác gì một ả “hồ ly tinh”, lại tiếp tục hành hạ cô hết lần này đến lần khác.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"林柏叡","avatar":""},{"name":"严智超","avatar":""},{"name":"John Wu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Love at First Sight","สาวใช้เจี๋ยมเจี้ยมของคุณชายตาบอด","盲少爷的小女仆"]', 1784690324250);
