INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-hau-cua-thieu-gia-mu', 'Người Hầu Của Thiếu Gia Mù', 'Romance With Blind Master', 'người hầu của thiếu gia mù romance with blind master 林柏叡 严智超 john wu love at first sight สาวใช้เจี๋ยมเจี้ยมของคุณชายตาบอด 盲少爷的小女仆', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngan-bau-troi-che-lap-di-vi-sao', 'Ngăn Bầu Trời Che Lấp Đi Vì Sao', 'Venus in the Sky', 'https://phimimg.com/upload/vod/20241019-1/fe4b4a5a15127e23bc2dbd356df50feb.jpg', 'https://phimimg.com/upload/vod/20241019-1/7ad75965844df5547fd76c5d6604f91d.jpg', '<p>Sky và Venus gặp lại sau khi biến mất khỏi cuộc đời nhau. Cả hai đều có những câu chuyện trong lòng. Chuyện trong quá khứ cứ tưởng thời gian sẽ chữa lành, nhưng khi gặp lại, lại không thể ngăn được tình cảm dành cho nhau. Hơn ba năm cách biệt, Venus quyết định nghỉ việc và về nhà nghỉ ngơi cho đến khi muốn quay lại làm việc lần nữa. Trong lúc đó, mỗi tối cậu cũng tới phụ việc anh trai Janus - người vừa mới đầu tư mở cửa hàng tiện lợi 24/24 ở ngoại ô cho bớt chán. Venus sẽ nhận phụ việc vặt như lái xe giao hàng cho &quot;khách hàng thường xuyên&quot; sống ở nơi tiện đường về nhà của cậu. Nhưng rồi một ngày, Venus gặp được chủ nhân chưa từng thấy mặt suốt cả tuần của ngôi nhà này. Mà chủ ngôi nhà lại chính là Sky - bạn thời đại học, giờ là bác sĩ trẻ, vẫn luôn vui vẻ, tràn đầy năng lượng dù công việc ở bệnh viện rất vất vả. Nhưng khi gặp lại nhau, cả hai đều không thể kìm nén được tình cảm dành cho đối phương.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pranapong Khaisang","avatar":""},{"name":"Cheque Wacharawee Kaewpoolsri","avatar":""},{"name":"Tontae Tinnakorn Puwasakdiwong","avatar":""},{"name":"Aungpao Chananyu Sinprasit","avatar":""},{"name":"Max Detter","avatar":""},{"name":"Boss Wasupol Panyalertprapha","avatar":""},{"name":"Poom Sirawit Homanake","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["恋恋维纳斯","ห้ามฟ้าห่มดาว"]', 1784690324250);
