INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngan-bau-troi-che-lap-di-vi-sao', 'Ngăn Bầu Trời Che Lấp Đi Vì Sao', 'Venus in the Sky', 'ngăn bầu trời che lấp đi vì sao venus in the sky pranapong khaisang cheque wacharawee kaewpoolsri tontae tinnakorn puwasakdiwong aungpao chananyu sinprasit max detter boss wasupol panyalertprapha poom sirawit homanake 恋恋维纳斯 ห้ามฟ้าห่มดาว', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-struck-truy-tinh', 'Star Struck: Truy Tinh', 'Star Struck', 'https://phimimg.com/upload/vod/20241019-1/514a61b87f8e4657492cf820131bfb4a.jpg', 'https://phimimg.com/upload/vod/20241019-1/299f249bd21800cf24c9e26f90eee0d0.jpg', '<p>Nơi duy nhất mà hai thiếu niên tội nghiệp có thể thư giãn là sân chơi dưới bầu trời đêm đầy sao. Han-joon ban đầu nghĩ rằng anh ấy là người duy nhất sẽ nhìn thấy bầu trời đầy sao ở đó, nhưng anh ấy không biết rằng có những người khác cũng đã thấy. Han-joon chào người ấy mà không ngờ lại nhận lại được câu trả lời. Dưới bầu trời đêm đầy sao, hai thiếu niên cô đơn và bất hạnh, Han-joon và Yoo-jae đã gặp nhau. Sau khi Han-joon và Yoo-jae gặp nhau lần đầu tiên ở trường cấp hai, họ cùng học tại một trường cấp 3 và nỗ lực thi đỗ cùng một trường đại học. Cùng với Yoon Chae-young, Park Jin-hwan và Lee Ing-yu. Họ trải qua cuộc sống thú vị và vui vẻ. Tuy nhiên, Han-joon luôn cảm thấy khoảng thời gian thú vị nhất là khoảng thời gian anh dành cho Yoo-jae. Vì vậy, một ngày Hanjun nhận ra rằng tình cảm của mình dành cho Yoo-jae không chỉ là tình bạn... Một ngày nọ, Chaeyoung quyết định thổ lộ tình cảm của mình. Han-joon trở nên quẫn trí sau khi biết tin. Nhận ra tình cảm thực sự của mình, Han-joon quyết định bày tỏ trái tim mình... Đối với một thiếu niên, đây là một tình bạn độc nhất vô nhị, nhưng đối với một người khác, đó là một tình yêu độc nhất vô nhị. Câu chuyện về một thiếu niên tỏa sáng như một ngôi sao bắt đầu từ đây...</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Zuho","avatar":""},{"name":"Kim In-sung","avatar":""},{"name":"Park Tae-in","avatar":""},{"name":"Chae Soo-ah","avatar":""},{"name":"Kim Yu-bin","avatar":""},{"name":"Lee Sang-min","avatar":""},{"name":"Kwon San","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["ဓူဝံကြယ်၏ ချစ်ခြင်း","STAR STRUCK","星夜戀人","STAR STRUCK 追星","追星STAR STRUCK","Starstruck","스타스트럭"]', 1784690324250);
