INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sung-cuoi-cung-2023', 'Tay Súng Cuối Cùng', 'The Last Rifleman', 'https://phimimg.com/upload/vod/20241020-1/03d4f3abe720420de6dfb28f2c9ac50d.jpg', 'https://phimimg.com/upload/vod/20241020-1/1463651dffe2c814dc8096a6ca62a437.jpg', '<p>Bộ phim kể về Artie Crawford, một vị chiến binh người Bắc Ireland từ Thế chiến II, quyết định thoát khỏi nhà trọ dưỡng lão và bắt đầu hành trình cảm động từ Bắc Ireland đến Pháp để tham dự lễ kỷ niệm D-Day. Trên đường đi, Artie phải đối mặt với những ký ức quá khứ của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Clémence Poésy","avatar":""},{"name":"John Amos","avatar":""},{"name":"Jürgen Prochnow","avatar":""},{"name":"Ian McElhinney","avatar":""},{"name":"Tara Lynne O''Neill","avatar":""},{"name":"Samuel Bottomley","avatar":""},{"name":"Desmond Eastwood","avatar":""},{"name":"Stella McCusker","avatar":""},{"name":"Claire Rafferty","avatar":""},{"name":"Joseph Loane","avatar":""},{"name":"James Keating","avatar":""},{"name":"Ali White","avatar":""},{"name":"Rosie McClelland","avatar":""},{"name":"Leo McDermott","avatar":""},{"name":"Maggie Cron","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["O Último Soldado","最后一名步枪兵","最后一个枪手","The Last Rifleman"]', 1784690324250);
