INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-chua-caligula-2023', 'Bạo Chúa Caligula', 'Caligula: The Ultimate Cut', 'https://phimimg.com/upload/vod/20241019-1/4899403314e1793020aec1c1fd5fb0fa.jpg', 'https://phimimg.com/upload/vod/20241019-1/be96186bdcf260e7f722b9d964cd8489.jpg', '<p>Sau cái chết của hoàng đế hoang tưởng Tiberius, Caligula, người thừa kế của ông, nắm quyền lực và đẩy đế chế vào một vòng xoáy đẫm máu của sự điên rồ và đồi trụy.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Malcolm McDowell","avatar":""},{"name":"Teresa Ann Savoy","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Peter O''Toole","avatar":""},{"name":"John Steiner","avatar":""},{"name":"Guido Mannari","avatar":""},{"name":"Paolo Bonacelli","avatar":""},{"name":"Leopoldo Trieste","avatar":""},{"name":"Giancarlo Badessi","avatar":""},{"name":"Mirella D''Angelo","avatar":""},{"name":"Anneka Di Lorenzo","avatar":""},{"name":"Lori Wagner","avatar":""},{"name":"Adriana Asti","avatar":""},{"name":"John Gielgud","avatar":""},{"name":"Bruno Brive","avatar":""},{"name":"Rick P","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Io, Caligola","Caligula: The Ultimate Cut","Calígula","칼리굴라: 얼티메이트 컷 무삭제판","Caligola"]', 1784690324250);
