INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('21-khoanh-khac', '21 Khoảnh Khắc', '21 Positions', 'https://phimimg.com/upload/vod/20241019-1/65106d8b60cccaa49ee2153fb859ddec.jpg', 'https://phimimg.com/upload/vod/20241019-1/cb4a9ceeba37edaedcea36cfbde2e7cb.jpg', '<p>21 Positions (2023) xoay quanh Julia và Mateo, một cặp đôi trẻ sống giản dị bên bờ biển Cádiz, kiếm sống bằng cách chia sẻ những khoảnh khắc thân mật qua OnlyFans. Dù đáp ứng được những ước muốn của khán giả, họ lại dần mất đi ngọn lửa đam mê khi áp lực biểu diễn ngày càng nặng nề.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"María Lázaro","avatar":""},{"name":"Fernando Barona","avatar":""},{"name":"Mario Fernández Alonso","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["21 Paradise","21 paraíso"]', 1784690324250);
