INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-uoc-cua-toi', 'Điều Ước Của Tôi', 'My Blessing', 'https://phimimg.com/upload/vod/20241016-1/4dd1da519fc41e5730dd0186a50ec7de.jpg', 'https://phimimg.com/upload/vod/20241016-1/dad34ab012a516e6e74688b1f2632ccd.jpg', '<p>Naina là người chưa bao giờ tự tin trong tình yêu, chưa biết cách theo đuổi bất kỳ ai đúng cách. Tuy nhiên, Naina chưa bao giờ bỏ cuộc, tự tin rằng một ngày nào đó tình yêu sẽ đến! Cho đến sinh nhật năm 20 tuổi, anh tổ chức một bữa tiệc với Ton, người bạn thân duy nhất của mình. Cũng trong đêm đó, anh đã ước gặp được tình yêu đích thực. Cuộc sống của Naina đã thay đổi khi anh nghe tin đồn về một cái cây linh thiêng, nói rằng bất cứ điều gì ước nguyện đều sẽ trở thành sự thật. Nhưng ai biết được cuộc sống của Naina sẽ thay đổi như thế nào khi cậu gặp Cen - người xuất hiện trong giấc mơ của cậu....</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chang Jayapol Chiewpitayakan","avatar":""},{"name":"Boat Anakame Binsaman","avatar":""},{"name":"Aom Pattaradanai Jainak","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["พรนี้ที่ฉันขอ"]', 1784690324250);
