INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-socola', 'Bác Sĩ Socola', 'Dr. Chocolate', 'https://phimimg.com/upload/vod/20241011-1/db37ca67854b83ea1582d861b59f891a.jpg', 'https://phimimg.com/upload/vod/20241011-1/9db19fdcdb5468a9db2ff1f77094258e.jpg', '<p>Hai năm trước, Noda Tetsuya làm bác sĩ. Anh ấy là một thực tập sinh y khoa được đào tạo bởi bác sĩ phẫu thuật tim Terashima Koichi. Một ngày nọ, Koichi và vợ bị sát hại. Lúc đó, Tetsuya đã mất đi cánh tay phải. Vợ chồng Koichi để lại cô con gái 8 tuổi Terashima Yui. Giờ đây, Noda hợp tác với Yui để lãnh đạo một nhóm phẫu thuật bí mật bất hợp pháp, mục đích cuối cùng của họ là tìm ra sự thật đằng sau cái chết của cha mẹ cô. Để thuê đội phẫu thuật chợ đen, cần phải nộp khoản phí 100 triệu yên tiền mặt cũng như yêu cầu NDA và sôcôla. Nhóm có thể cứu sống bệnh nhân bất kể hoàn cảnh nào, nhưng một phóng viên báo chí bắt đầu đuổi theo họ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"坂口健太郎","avatar":""},{"name":"Noa Shiroyama","avatar":""},{"name":"西野七瀬","avatar":""},{"name":"葵わかな","avatar":""},{"name":"鈴木紗理奈","avatar":""},{"name":"前田旺志郎","avatar":""},{"name":"Yukiyoshi Ozawa","avatar":""},{"name":"斉藤由貴","avatar":""},{"name":"山本耕史","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Dr Chocolate","Dr. 초콜릿","Dr.チョコレート"]', 1784690324250);
