INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-thai-cua-su-ham-muon', 'Sắc Thái Của Sự Ham Muốn', 'Shades of Desire', 'https://phimimg.com/upload/vod/20241009-1/bdca9c2eae6176a2f5ff9a138a1b3beb.jpg', 'https://phimimg.com/upload/vod/20241009-1/2cf9c3c40cda581c5c01e416a262e79b.jpg', '<p>Bộ phim kể về hai chị em sinh đôi sống hai cuộc đời hoàn toàn trái ngược nhau. Aubrey thành công, đã kết hôn và có cuộc sống sung túc, trong khi Jennifer là một người làm việc trong ngành công nghiệp tình dục và gặp rắc rối với băng đảng</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jenny Miller","avatar":""},{"name":"Danielle Scott","avatar":""},{"name":"May Kelly","avatar":""},{"name":"Harrison Thomas Boxley","avatar":""},{"name":"Mark Sears","avatar":""},{"name":"Sarah Dionna","avatar":""},{"name":"Jamie Robertson","avatar":""},{"name":"Darrell Griggs","avatar":""},{"name":"Sian Altman","avatar":""},{"name":"Freddie Hogan","avatar":""},{"name":"Fahad Salman","avatar":""},{"name":"Di Spoto Sarah","avatar":""},{"name":"Elizabeth Custodio","avatar":""},{"name":"Kierath Jandoo","avatar":""},{"name":"Karell Vertet","avatar":""},{"name":"Simon Ellis","avatar":""},{"name":"Daniel Go","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Segredos Proibidos","Shades of Desire"]', 1784690324250);
