INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sac-thai-cua-su-ham-muon', 'Sắc Thái Của Sự Ham Muốn', 'Shades of Desire', 'sắc thái của sự ham muốn shades of desire jenny miller danielle scott may kelly harrison thomas boxley mark sears sarah dionna jamie robertson darrell griggs sian altman freddie hogan fahad salman di spoto sarah elizabeth custodio kierath jandoo karell vertet simon ellis daniel go segredos proibidos shades of desire', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-may-an-tien', 'Cú Máy Ăn Tiền', 'Cobweb', 'https://phimimg.com/upload/vod/20241009-1/ceec676346d5794496ac7f75b3fd664c.jpg', 'https://phimimg.com/upload/vod/20241009-1/673514f20a52e7ed3471b83b9eaea9d8.jpg', '<p>Cú Máy Ăn Tiền lấy bối cảnh thực tế và câu chuyện làm phim những năm 1970 ở Hàn Quốc. Kim Yeol (Song Kang Ho thủ vai) - một đạo diễn điện ảnh có bộ phim đầu tay được giới phê bình khen ngợi, nhưng sự nghiệp của ông tuột dốc không phanh khi liên tiếp ra đời những tác phẩm bị coi là “phim rác”. Sau khi hoàn thành xong bộ phim mới nhất là Cobweb, đạo diễn Kim cảm thấy cần quay lại cái kết để có thể tạo ra một kiệt tác. Tuy nhiên, kịch bản mới không vượt qua được khâu kiểm duyệt và các diễn viên cũng không thể hiểu được cái kết mới của ông. Giữa lịch trình rối rắm, sự phản đối từ nhà sản xuất, sự can thiệp của cơ quan kiểm duyệt và những mâu thuẫn đang xung đột trước mắt khiến đạo diễn Kim như muốn phát điên, nhưng ông vẫn tiếp tục một cách bất chấp: “Nếu tôi có thể thay đổi cái kết, một kiệt tác sẽ xuất hiện. Tất cả những gì tôi cần là 2 ngày”.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"송강호","avatar":""},{"name":"임수정","avatar":""},{"name":"오정세","avatar":""},{"name":"전여빈","avatar":""},{"name":"정수정","avatar":""},{"name":"박정수","avatar":""},{"name":"장영남","avatar":""},{"name":"정우성","avatar":""},{"name":"엄태구","avatar":""},{"name":"염혜란","avatar":""},{"name":"김민재","avatar":""},{"name":"김동영","avatar":""},{"name":"Kim Jae-geon","avatar":""},{"name":"장광","avatar":""},{"name":"정인기","avatar":""},{"name":"Jang Nam-yeol","avatar":""},{"name":"Jeong Gi-seop","avatar":""},{"name":"Kim Joong-hee","avatar":""},{"name":"Kim Moon-hak","avatar":""},{"name":"Lee Seung-jin","avatar":""},{"name":"Kang Chae-young","avatar":""},{"name":"Kim Min-ha","avatar":""},{"name":"Jo Seung-goo","avatar":""},{"name":"Park Hyeon-cheol","avatar":""},{"name":"정미형","avatar":""},{"name":"이양희","avatar":""},{"name":"Bae Seong-il","avatar":""},{"name":"Lee Hye-a","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["韓戲逼人","Ça tourne à Séoul ! Cobweb","Geomijip","Cobweb","Pajęczyna","В паутине","Tela de araña","I mästarens nät - Cobweb","誆世巨作：蜘蛛窩新宇宙","Cú Máy Ăn Tiền","거미집"]', 1784690324250);
