INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oggy-oggy-phan-3', 'Oggy Oggy (Phần 3)', 'Oggy Oggy (Season 3)', 'https://phimimg.com/upload/vod/20241007-1/02eab707f1d99c7d9deb3007a5af2c63.jpg', 'https://phimimg.com/upload/vod/20241007-1/8bcf463357e0bec4b3c36d9dc3d1cdb5.jpg', '<p>Tham gia cùng Oggy Oggy đáng yêu và hội bạn ở thế giới mèo con tươi sáng và đầy màu sắc. Họ tất bật với những phút giây vui vẻ – và các cuộc phiêu lưu tuyệt đỉnh!</p>', 'Hoàn Tất (23/23)', 23, 'hoathinh', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Оггі Оггі","Oggy Oggy"]', 1784690324250);
