INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hon-nhan-thu-ba', 'Cuộc Hôn Nhân Thứ Ba', 'The Third Marriage', 'https://phimimg.com/upload/vod/20241010-1/3ae422eb86d73b88b696aeafa762e297.jpg', 'https://phimimg.com/upload/vod/20241010-1/8cd01400bcdd8109c94e65a212b7b60d.jpg', '<p>Cuộc Hôn Nhân Thứ Ba là một bức tranh tinh thần đầy màu sắc, mô tả cuộc hành trình của Kim Min Hee, một phụ nữ trẻ đối diện với những thử thách và bi kịch đầy khắc nghiệt của cuộc đời. Da Jung, một đầu bếp vui vẻ, tích cực và luôn muốn an ủi người khác bằng thức ăn mình làm. Cô cũng là vợ của Sang Chul và có một con gái. Tuy nhiên, cô đau lòng vì mối quan hệ ngoại tình của bạn mình, Se Ran với chồng cô. Se Ran ích kỷ và muốn có được nhiều hơn, vì vậy cô đã làm xáo trộn cuộc sống của Da Jung. Để trả thù cha mình, cô đã phá huỷ cuộc sống của Da Jung, nhưng cuối cùng nhận ra sai lầm. Sự trả thù do hiểu lầm này đã dẫn đến sự trả thù khác. Hai người phụ nữ chọn hai hướng trái ngược nhau, nhưng họ sẽ thay đổi thế nào khi gặp tình yêu đích thực?</p>', 'Hoàn Tất (132/132)', 132, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Oh Seung A","avatar":""},{"name":"Yoon Sun Woo","avatar":""},{"name":"Oh Se Young","avatar":""},{"name":"Mun Ji Hu","avatar":""},{"name":"Ahn Nae Sang","avatar":""},{"name":"Yoon Hae Young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["TTM","ازدواج سوم","세번째결혼","세번째 결혼","세 번째 결혼"]', 1784690324250);
