INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-kho-doan', 'Gia Đình Khó Đoán', 'Unpredictable Family', 'https://phimimg.com/upload/vod/20241009-1/88c427e778d6eca6dd26a1510982514f.jpg', 'https://phimimg.com/upload/vod/20241009-1/1167e56aa86ab675888d441cca8385cf.jpg', '<p><span style="text-wrap: nowrap;">Eun Sung, con gái của Dong Gu và Chun Young, mơ ước trở nên thành công nhưng cô lại là một diễn viên không ai biết đến. Đã hơn ba năm kể từ khi cô gia nhập rạp hát với ước mơ đầy tham vọng nhưng cô vẫn phải dán áp phích, dọn dẹp rạp và chỉ tập luyện khi các diễn viên khác không có mặt. Sun Woo, con trai của Jung Ae và Ki Seok, là một đạo diễn phim Hollywood đầy triển vọng và luôn đạt được mục tiêu đề ra. Eun Sung và Sun Woo yêu nhau và quyết định kết hôn.n</span><span style="text-wrap: nowrap;">Tuy nhiên, họ nhận ra Dong Gu và Jung Ae là kẻ thù truyền kiếp đã ly hôn 30 năm trước. Mối quan hệ tồi tệ này giữa cha mẹ và con cái gây tranh cãi về cuộc hôn nhân của họ. Câu chuyện về những người ghét nhau nhất trở thành gia đình hoang dã nhất, kỳ lạ nhất nhưng vui nhộn nhất bắt đầu từ bây giờ!</span></p>', 'Full', 131, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Nam Sang-ji","avatar":""},{"name":"Lee Do-gyeom","avatar":""},{"name":"Kang Da-bin","avatar":""},{"name":"Lee Hyo-na","avatar":""},{"name":"임하룡","avatar":""},{"name":"이종원","avatar":""},{"name":"김선경","avatar":""},{"name":"이대연","avatar":""},{"name":"임나영","avatar":""},{"name":"Joo Sae-byeok","avatar":""},{"name":"최수린","avatar":""},{"name":"안연홍","avatar":""},{"name":"Jeong Min-jun","avatar":""},{"name":"Choi Woo-hyuk","avatar":""},{"name":"김보미","avatar":""},{"name":"Oh Chae-yi","avatar":""},{"name":"Chae Seo-kyeong","avatar":""},{"name":"Song Young-ah","avatar":""},{"n