INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-den-phan-10', 'Danh Sách Đen (Phần 10)', 'The Blacklist (Season 10)', 'https://phimimg.com/upload/vod/20240309-1/f55326f7806a5b552c724ea1a66a98c0.jpg', 'https://phimimg.com/upload/vod/20240309-1/cf3842fd3ad8bb417d6ede4faf08d85e.jpg', '<p>Sáu tháng sau khi Wujing trốn thoát khỏi nơi giam giữ, Reddington tái xuất một cách bí ẩn ở Manhattan giữa một vụ nổ. Khi một cựu Blacklister được tìm thấy tại hiện trường, Lực lượng Đặc nhiệm bắt đầu điều tra một âm mưu lớn hơn đang diễn ra.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 4, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Spader","avatar":""},{"name":"Diego Klattenhoff","avatar":""},{"name":"Harry Lennix","avatar":""},{"name":"Hisham Tawfiq","avatar":""},{"name":"Anya Banerjee","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324250);
