INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-sat-nhan', 'Thanh Tra Sát Nhân', 'Devils', 'https://phimimg.com/upload/vod/20241004-1/6913bda6ea8c9a3c6f659c2629489878.jpg', 'https://phimimg.com/upload/vod/20241004-1/c4e51c7dcaef172a4e9cad54798b0d6c.jpg', '<p>Phim điện ảnh Thanh Tra Sát Nhân (tên tiếng Anh: Devils) của đạo diễn Kim Jae-hoon xoay quanh màn tráo đổi thân phận bí ẩn, ly kỳ của thanh tra Jae-hwan (Oh Dae-hwan thủ vai) và tên giết người hàng loạt Jin-hyuk (Jang Dong-yoon thủ vai). Kẻ phản diện sống cuộc đời chính nghĩa, người lương thiện lại bất đắc dĩ trở thành sát nhân, những tình tiết không tưởng liên tục xảy ra khiến người xem không thể rời mắt khỏi cuộc truy đuổi nghẹt thở giữa hai nhân vật.</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"장동윤","avatar":""},{"name":"오대환","avatar":""},{"name":"장재호","avatar":""},{"name":"최귀화","avatar":""},{"name":"손종학","avatar":""},{"name":"신승환","avatar":""},{"name":"윤병희","avatar":""},{"name":"김원해","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["애프터","Devils","Aepeuteo","Akmadeul","악마들"]', 1784690324250);
