INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-cham-soc-me', 'Hãy Chăm Sóc Mẹ', 'Take Care Of My Mom', 'https://phimimg.com/upload/vod/20241004-1/f99e8b4748ac8ee162e02ed61b3b7441.jpg', 'https://phimimg.com/upload/vod/20241004-1/064bf3652863d544c95d9f5451a2f67b.jpg', '<p>Jeong Mal-im, một cụ bà 85 tuổi đến từ Daegu, đã luôn sống mà không cần bất kỳ sự giúp đỡ nào từ con cái và cố gắng tận hưởng một cuộc đời thứ 2 bằng cách tự chi trả cho cuộc sống của mình. Nhưng chẳng may, cơ thể của bà không cho phép! Bà bị gãy tay trong lúc đứa con trai duy nhất Jong-wook đến thăm sau một thời gian dài, và tai nạn này đã mang đến cho bà một người chăm sóc, Mi-seon. Trái ngược với trái tim mình, bà chỉ nói những lời cay nghiệt với đứa con trai đang cố gắng dùng camera quan sát để lo lắng cho mẹ mình. Và bà cũng không thích người chăm sóc vì dường như cô ta đang âm mưu gì đó. Tưởng chừng xích mích dần được hòa giải thì vào một ngày lễ, gia đình Jong Wook đột ngột đến thăm bà, mâu thuẫn vốn đã bị chôn vùi lại bùng nổ lần nữa...</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"김영옥","avatar":""},{"name":"김영민","avatar":""},{"name":"박성연","avatar":""},{"name":"이정은","avatar":""},{"name":"김혜나","avatar":""},{"name":"Kim Jae-rok","avatar":""},{"name":"심소영","avatar":""},{"name":"Choi Seo-yeon","avatar":""},{"name":"이양희","avatar":""},{"name":"Kwak Min-jun","avatar":""},{"name":"Kim Han-sang","avatar":""},{"name":"정성일","avatar":""},{"name":"Kim Jun-seok","avatar":""},{"name":"Lee Joo-mi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["엄마를 부탁해","우리 엄마를 부탁해","拜托了妈妈","Take Care of Mother","말임씨를 부탁해"]', 1784690324250);
