INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chac-anh-dong-y', 'Chắc Anh Đồng Ý', 'Maybe I Do', 'https://phimimg.com/upload/vod/20241004-1/fbe21ac26607051521f2a1b0494ec325.jpg', 'https://phimimg.com/upload/vod/20241004-1/8ef79c66e6faa22132dae073a148c197.jpg', '<p>Michelle và Allen, những người đã đạt đến điểm trong mối quan hệ của họ khi họ đang xem xét các bước tiếp theo, quyết định mời cha mẹ họ đến gặp mặt và đưa ra một số hiểu biết về lý do tại sao hôn nhân lại thành công. Ngoại trừ việc cha mẹ đã biết nhau khá rõ, điều này dẫn đến một số quan điểm rất khác biệt về giá trị của hôn nhân.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emma Roberts","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Diane Keaton","avatar":""},{"name":"Richard Gere","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"DazMann Still","avatar":""},{"name":"Azriél Patricia","avatar":""},{"name":"Michael Kostroff","avatar":""},{"name":"Adrienne Acevedo Lovette","avatar":""},{"name":"John Rothman","avatar":""},{"name":"James Monroe Iglehart","avatar":""},{"name":"Joshua Jacobs","avatar":""},{"name":"Natalia Ortega","avatar":""},{"name":"James Earl Jones II","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["非常亂婿娶佳人","アバウト・ライフ　幸せの選択肢","Maybe I Do"]', 1784690324250);
