INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-chat-anh-hung-phan-1', 'Tố Chất Anh Hùng (Phần 1)', 'Hero Inside (Season 1)', 'https://phimimg.com/upload/vod/20241001-1/feb5ce53fca1c0f8649d5f2eb6cedc85.jpg', 'https://phimimg.com/upload/vod/20241001-1/d90539f375ff28c8b2469fe12527beb1.jpg', '<p>Cuộc phiêu lưu bắt đầu sau khi Scott, một họa sĩ hoạt hình và có tinh thần tự do, biến mất một cách bí ẩn sau khi vẽ 100 siêu anh hùng trên 100 cuốn truyện tranh mà không bao giờ được xuất bản.</p>', 'Full', 11, 'hoathinh', 'completed', 7, 2023, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Marc Thompson","avatar":""},{"name":"James Brown Jr.","avatar":""},{"name":"Barrett Leddy","avatar":""},{"name":"Samantha Cooper","avatar":""},{"name":"Valory Pierce","avatar":""},{"name":"Dinesh Alvis","avatar":""},{"name":"Brent Mukai","avatar":""},{"name":"Gianni Matragrano","avatar":""},{"name":"Jamie Craib","avatar":""},{"name":"Jason Griffith","avatar":""},{"name":"Jenny Yokobori","avatar":""},{"name":"Lucas Schuneman","avatar":""},{"name":"Adin Rudd","avatar":""},{"name":"Cat Protano","avatar":""},{"name":"Henry Mason","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Homem Chorão","Hero Books","漫迷英雄梦","히어로 인사이드"]', 1784690324250);
