INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-tay-luc-hoang-hon', 'Nắm Tay Lúc Hoàng Hôn', 'Hold My Hand At Twilight', 'https://phimimg.com/upload/vod/20240930-1/f316d175337a7f6071a3704d71b1eb9c.jpg', 'https://phimimg.com/upload/vod/20240930-1/7da51752ce1d62bf66a0f5bea34b7bf2.jpg', '<p>Asagi Soramame lớn lên ở một vùng quê hẻo lánh của Kyushu, Nhật Bản. Cô ấy là một người năng động và tươi sáng. Cô theo vị hôn phu của mình, cũng là một người bạn thời thơ ấu, đến Tokyo. Cô đã có một cuộc gặp gỡ định mệnh và gây sốc với một người đàn ông tên là Umino Oto, nhưng họ cho rằng họ sẽ không bao giờ gặp lại nhau. Giờ đây, Asagi Soramame, 23 tuổi, gặp lại Umino Oto tại một khu nhà trọ nơi cả hai cùng sống.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"広瀬すず","avatar":""},{"name":"永瀬廉","avatar":""},{"name":"田辺桃子","avatar":""},{"name":"夏木マリ","avatar":""},{"name":"遠藤憲一","avatar":""},{"name":"黒羽麻璃央","avatar":""},{"name":"Rikka Ihara","avatar":""},{"name":"Rio Uchida","avatar":""},{"name":"松本若菜","avatar":""},{"name":"川上洋平","avatar":""},{"name":"櫻井海音","avatar":""},{"name":"茅島成美","avatar":""},{"name":"酒向芳","avatar":""},{"name":"横田真悠","avatar":""},{"name":"松雪泰子","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["黄昏時分, 牽起手","Holding Hands at Dusk","Hold My Hand At Twilight","Yugure ni, te wo tsunagu","Yūgure ni, te o tsunagu","Yuugure ni, te wo tsunagu","해 질 녘에, 손을 잡는다","夕暮れに、手をつなぐ"]', 1784690324250);
