INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-noi-day-cua-ai', 'Cuộc Nổi Dậy Của AI', 'Simulant', 'https://phimimg.com/upload/vod/20240926-1/bc6eb6200f9bda3acaea351760d8d235.jpg', 'https://phimimg.com/upload/vod/20240926-1/b4184472f962d6769ac23d2c447c8c12.jpg', '<p>Faye cố gắng thay thế người chồng mới qua đời của cô, Evan, bằng một thiết bị mô phỏng android (SIM). Mặc dù SIM Evan trông giống Evan con người về mọi mặt, nhưng Faye không cảm thấy tình yêu dành cho SIM Evan giống như tình yêu dành cho cô ấy. SIM Evan cố gắng giành lại Faye đồng thời đang chạy trốn khỏi một đặc vụ chính phủ đang truy đuổi những SIM đã trở nên “có ý thức” và có khả năng trở thành mối đe dọa cho loài người.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Robbie Amell","avatar":""},{"name":"Jordana Brewster","avatar":""},{"name":"Simu Liu","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Alicia Sanz","avatar":""},{"name":"Masa Lizdek","avatar":""},{"name":"Christine L. Nguyen","avatar":""},{"name":"Emmanuel Kabongo","avatar":""},{"name":"Samantha Helt","avatar":""},{"name":"Conrad Coates","avatar":""},{"name":"Mayko Nguyen","avatar":""},{"name":"Mercedes Leggett","avatar":""},{"name":"Von Flores","avatar":""},{"name":"James Burke","avatar":""},{"name":"Byron Abalos","avatar":""},{"name":"Zarrin Darnell-Martin","avatar":""},{"name":"Moni Og","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Simulant","Больше, чем люди","Quem Está Aí?","Les Simulants","Hello Stranger","סימולנט","Bolshe chem lyudi","โลกร่างเสมือน"]', 1784690324250);
