INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-phep-3-ngay', 'Kỳ Nghỉ Phép 3 Ngày', 'Our Season', 'https://phimimg.com/upload/vod/20240925-1/9cf5f7d9e5c0d5774c649f12c8a4cb11.jpg', 'https://phimimg.com/upload/vod/20240925-1/aadd70c5e168773dd4a7b73d18ec68a5.jpg', '<p>Bok-ja được cấp một kỳ nghỉ đặc biệt sau khi cô qua đời, cho phép cô đến gặp con gái mình, Jin-joo, một giáo sư đại học sống ở nước ngoài. Không giống như mong đợi của cô, Bok-ja thấy Jin-joo sống trong ngôi nhà cũ của cô và điều hành một quán ăn địa phương và trở nên thất vọng với những câu hỏi mà cô không thể hỏi. Sau thời gian bên cạnh Jin-joo, Bok-ja nhận ra rằng con gái cô đang phải vật lộn với những cảm xúc không thể giải quyết được về mình và cố gắng tìm cách thể hiện những cảm xúc chân thành mà cô chưa từng chia sẻ trước đây.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"김해숙","avatar":""},{"name":"신민아","avatar":""},{"name":"강기영","avatar":""},{"name":"황보라","avatar":""},{"name":"차미경","avatar":""},{"name":"박명훈","avatar":""},{"name":"배해선","avatar":""},{"name":"김현수","avatar":""},{"name":"정라엘","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Hyuga","휴가","3일의 휴가"]', 1784690324250);
