INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-nao-do-chung-ta-se-ke-cho-nhau-moi-dieu', 'Một Ngày Nào Đó Chúng Ta Sẽ Kể Cho Nhau Mọi Điều', 'Someday We''ll Tell Each Other Everything', 'https://phimimg.com/upload/vod/20240922-1/c4fc39ba0b30e7ed411c15e89fe1482a.jpg', 'https://phimimg.com/upload/vod/20240922-1/f35fcdfbb11674cb4c81bd4d78a166a7.jpg', '<p>Bộ phim dựa trên tiểu thuyết cùng tên của Daniela Krien và có sự tham gia của các diễn viên Marlene Burow và Felix Kramer. Nội dung: Phim lấy bối cảnh mùa hè năm 1990 tại Đông Đức cũ, kể về một cô gái trẻ bắt đầu mối quan hệ với một nông dân lớn tuổi hơn cô gấp đôi. Bộ phim đã được công chiếu lần đầu tại Liên hoan phim Berlin vào ngày 17 tháng 2 năm 2023 và ra rạp vào ngày 14 tháng 4 năm 2023.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Marlene Burow","avatar":""},{"name":"Felix Kramer","avatar":""},{"name":"Cedric Eich","avatar":""},{"name":"Silke Bodenbender","avatar":""},{"name":"Christine Schorn","avatar":""},{"name":"Victoria Mayer","avatar":""},{"name":"Jördis Triebel","avatar":""},{"name":"Tom Quaas","avatar":""},{"name":"Petra Kalkutschke","avatar":""},{"name":"Stephanie Petrowitz","avatar":""},{"name":"Christian Erdmann","avatar":""},{"name":"Philippine Pachl","avatar":""},{"name":"Peter Rauch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Someday We’ll Tell Each Other Everything","說不出口的禁忌愛慾","One Day We''ll Tell Each Other Everything","Irgendwann werden wir uns alles erzählen"]', 1784690324250);
