INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-dich-doi-doi', 'Giao Dịch Đổi Đời', 'The Wild', 'https://phimimg.com/upload/vod/20240920-1/df8c21715f3dd3d22cd6eace2d12b802.jpg', 'https://phimimg.com/upload/vod/20240920-1/5446274f167378fc98360e57ecaaae30.jpg', '<p>Woo-chul từng là võ sĩ quyền anh thành công nhưng anh phải vào tù vì đối thủ chết giữa trận đấu. Bây giờ anh ấy đã được thả ra, anh ấy có ý định trở thành một công dân kiểu mẫu. Trong khi đó, người bạn Do-shik của anh sẽ làm mọi cách để tiến lên phía trước. Sau khi chọn những con đường khác nhau, họ sẽ buộc phải âm mưu chống lại và phản bội lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박성웅","avatar":""},{"name":"오대환","avatar":""},{"name":"오달수","avatar":""},{"name":"주석태","avatar":""},{"name":"서지혜","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["야수의 피","Deo Waildeu","The Wild","恶兽之战","더 와일드: 야수들의 전쟁"]', 1784690324250);
