INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('magic-mike-vu-dieu-cuoi-cung', 'Magic Mike: Vũ Điệu Cuối Cùng', 'Magic Mike''s Last Dance', 'https://phimimg.com/upload/vod/20230922-1/7789f95691772c1687a4037a235e1424.jpg', 'https://phimimg.com/upload/vod/20230922-1/0995efb2a60501a0b2e18a572850af76.jpg', '<p>Mike Lane một lần nữa bước lên sân khấu khi một hợp đồng kinh doanh đổ bể khiến anh khánh kiệt và phải làm nhân viên pha chế ở Florida. Hy vọng có được một chuyến vượt rào cuối cùng, Mike đến London cùng một người bạn xã hội giàu có, người đã dụ dỗ anh bằng một lời đề nghị mà anh không thể từ chối -- và một chương trình nghị sự của riêng cô. Với tất cả mọi thứ trên đường dây, anh ấy sớm thấy mình đang cố gắng đánh bại một đội vũ công tài năng mới nóng bỏng thành hình.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Channing Tatum","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Ayub Khan-Din","avatar":""},{"name":"Jemelia George","avatar":""},{"name":"Ethan Lawrence","avatar":""},{"name":"Juliette Motamed","avatar":""},{"name":"Alan Cox","avatar":""},{"name":"Caitlin Gerard","avatar":""},{"name":"Vicki Pepperdine","avatar":""},{"name":"Suzanne Bertish","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324251);
