INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-boy', 'Doi Boy', 'Doi Boy', 'doi boy doi boy อวัช รัตนปิณฑะ arak amornsupasiri ภูมิภัทร ถาวรศิริ ปาณิสรา ริกุลสุรกาน ornjira lamwilai noomsang nattapong mooring phamon atthanee tokeree bundit thianrat teerawat mulvilai jarunun phantachat pree asvaraksha pree nokham thaworn santhong jai ดอยบอย 도이 보이 doi boy ドイ・ボーイ 路地裏の僕ら evden uzakta', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-gau-dung-dau-dat', 'Đầu Gấu Đụng Đầu Đất', 'Woongnami', 'https://phimimg.com/upload/vod/20240919-1/851ef28c74bc6280dba2c804e76b6dce.jpg', 'https://phimimg.com/upload/vod/20240919-1/68da6bf13fe5fcb34bb69ebbf44a474e.jpg', '<p>Phim Đầu Gấu Đụng Đầu Đất dựa trên câu chuyện thần thoại nổi tiếng tại Hàn Quốc về hai chú gấu sinh đôi hoá thành người sau khi ăn tỏi và ngải cứu trong 100 ngày. Chú gấu ăn tỏi trở thành Na Woong-nam, được một cặp vợ chồng nhà khoa học mang về nuôi nấng, tuy chỉ mới 25 tuổi nhưng lại sở hữu “giao diện” của một ông chú 52 với cái “đầu đất” ngây thơ, hiền lành. Trong khi đó, chú gấu ăn ngải cứu trở thành “đầu gấu” Lee Jeong-hak, được một tên trùm tổ chức tội phạm mang về nuôi và bị lợi dụng như một món “vũ khí” phòng vệ. Trong một tình huống bất đắc dĩ, Na Woong-nam đã trực tiếp đối đầu cùng anh em song sinh Lee Jeong-hak để ngăn chặn một vụ khủng bố virus có tầm lây lan mạnh. Sức mạnh của loài gấu bộc phát sẽ đẩy cuộc đụng độ của cặp gấu song sinh hoá người đi đến hồi kết nào?</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박성웅","avatar":""},{"name":"이이경","avatar":""},{"name":"염혜란","avatar":""},{"name":"오달수","avatar":""},{"name":"최민수","avatar":""},{"name":"윤제문","avatar":""},{"name":"백지혜","avatar":""},{"name":"서동원","avatar":""},{"name":"Han Da-sol","avatar":""},{"name":"김준호","avatar":""},{"name":"정우성","avatar":""},{"name":"김기천","avatar":""},{"name":"김종구","avatar":""},{"name":"안일권","avatar":""},{"name":"Choi Sun-ja","avatar":""},{"name":"Gun Woo","avatar":""},{"name":"Jeon Ji-hak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c7