INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-lai-vo-ngau', 'Yêu Lại Vợ Ngầu', 'Love Reset', 'https://phimimg.com/upload/vod/20240919-1/e12e83084e1aa08f77bc5b5687281280.jpg', 'https://phimimg.com/upload/vod/20240919-1/9fde3ba58060b05a83453338bbb1747c.jpg', '<p>Cặp vợ chồng trẻ No Jung Yeol (Kang Ha-neul) và Hong Na Ra (Jung So-min) từ cuộc sống hôn nhân màu hồng dần “hiện nguyên hình” trở thành cái gai trong mắt đối phương với vô vàn thói hư, tật xấu. Không thể đi đến tiếng nói chung, Jung Yeol và Na Ra quyết định ra toà ly dị. Tuy nhiên, họ phải chờ 30 ngày cho đến khi mọi thủ tục chính thức được hoàn tất. Trong khoảng thời gian này, một vụ tai nạn xảy ra khiến cả hai mất đi ký ức và không nhớ người kia là ai. Từ thời gian 30 ngày chờ đợi để được “đường ai nấy đi”, tình huống trớ trêu khiến cả hai bắt đầu nảy sinh tình cảm trở lại. Liệu khi nhớ ra mọi thứ, họ vẫn sẽ ký tên vào tờ giấy ly hôn?</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Ha Neul","avatar":""},{"name":"Jeong So-min","avatar":""},{"name":"Kim Sun-young","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["بازگشت عشق","۳۰ روز","تنظیم مجدد عشق","30 Days","30 วัน โคตร(เกลียด)เธอเลย","Yêu Lại Vợ Ngầu","30天","30일"]', 1784690324251);
