INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-thu-ba', 'Cuộc Đời Thứ Ba', 'Countdown', 'https://phimimg.com/upload/vod/20240919-1/6b2940fa6edb32cca817f3a6d5947656.jpg', 'https://phimimg.com/upload/vod/20240919-1/7e7778efdef559aa2168b943f423073f.jpg', '<p>Cựu võ sĩ Park Si Heon trở thành giáo viên ở thị trấn nhỏ sau khi giã từ sự nghiệp trong ô nhục. Những tưởng quá khứ sẽ mãi ngủ yên nhưng số phận lại đưa đẩy anh dẫn dắt đội đấm bốc của trường.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jin Sun Kyu","avatar":""},{"name":"Sung Yu Bin","avatar":""},{"name":"Oh Na Ra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Count","카운트"]', 1784690324251);
