INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-uop-cuoc-phieu-luu-den-london', 'Xác Ướp: Cuộc Phiêu Lưu Đến London', 'Mummies', 'https://phimimg.com/upload/vod/20240919-1/4f62df93d0d11608cabac88ce065896b.jpg', 'https://phimimg.com/upload/vod/20240919-1/12dc4d8880948fe6111055d3733b0eb7.jpg', '<p>Sâu dưới lòng đất, một vương quốc xác ướp với lịch sử cả ngàn năm đang rất thịnh vượng. Theo thông lệ, công chúa Nefer phải kết hôn với Thut dù cả hai đều không bằng lòng với chuyện này. Nhưng vì không thể thoát khỏi yêu cầu của thần, Thut bắt buộc phải kết hôn với Nefer trong vòng 7 ngày, cùng với chiếc nhẫn các Pharaoh đã ban cho anh. Bước ngoặt xảy ra khi chiếc nhẫn bị đánh cắp, vậy nên cả Thut, Nefer cùng cậu em trai Sekhem và chú cá sấu đáng yêu Croc cùng nhau chu du đến London nhằm tìm lại chiếc nhẫn quý giá, và rồi nhận ra những thay đổi trong trái tim mình.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Tây Ban Nha', 1, '[{"name":"Joe Thomas","avatar":""},{"name":"Eleanor Tomlinson","avatar":""},{"name":"Hugh Bonneville","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Dan Starkey","avatar":""},{"name":"Óscar Barberán","avatar":""},{"name":"Ana Esther Alborg","avatar":""},{"name":"Luis Pérez Reina","avatar":""},{"name":"María Luisa Solá","avatar":""},{"name":"Jaume Solà","avatar":""},{"name":"José Luis Mediavilla","avatar":""},{"name":"José Javier Serrano Rodríguez","avatar":""},{"name":"Aleix Estadella","avatar":""},{"name":"María Moscardó","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Mumier på eventyr","Moomios","木乃伊","翻生木乃