INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tram-nam-hanh-phuc-2023', 'Trăm năm hạnh phúc!', 'Long Live Love!', 'trăm năm hạnh phúc! long live love! ซันนี่ สุวรรณเมธานนท์ อารยา เอ ฮาร์เก็ต becky armstrong นิติ ชัยชิตาทร nopachai jayanama sadanont durongkhaweroj munin kangsathien pannawit phattanasiri pichsinee veerasuthima punyada praichana chayapa praditphan direkvarat amatayakul anchalee ลอง ลีฟ เลิฟว์! trăm năm hạnh phúc 爱情万岁 真爱万岁 ロング・リブ・ラブ 〜愛に乾杯!〜 ลอง ลีฟ เลิฟว์', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-lua-gap-sieu-lay', 'Siêu Lừa Gặp Siêu Lầy', 'Hustler vs Scammer', 'https://phimimg.com/upload/vod/20240919-1/5489fae29d34ab2c8c116e2417f06fc0.jpg', 'https://phimimg.com/upload/vod/20240919-1/ef0bc57cc068af0c1b13943b7a40852f.jpg', '<p>Siêu Lừa Gặp Siêu Lầy của đạo diễn Võ Thanh Hòa theo chân của Khoa – tên lừa đảo tầm cỡ “quốc nội” đến đảo ngọc Phú Quốc với mong muốn đổi đời. Tại đây, Khoa gặp Tú – tay lừa đảo “hàng real” và cùng Tú thực hiện các phi vụ từ nhỏ đến lớn. Cứ ngỡ sự ranh mãnh của Tú và sự may mắn trời cho của Khoa sẽ giúp họ trở thành bộ đôi bất khả chiến bại, nào ngờ lại đối mặt với nhiều tình huống dở khóc – dở cười. Nhất là khi băng nhóm của bộ đôi nhanh chóng mở rộng vì sự góp mặt của ông Năm (Nhất Trung) và bé Mã Lai (Ngọc Phước).</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Mạc Văn Khoa","avatar":""},{"name":"Anh Tú","avatar":""},{"name":"Ngọc Phước","avatar":""},{"name":"Nhật Trung","avatar":""},{"name":"Mỹ Duyên","avatar":""},{"name":"Đại Nghĩa","avatar":""},{"name":"Lâm Vỹ Dạ","avatar":""},{"name":"Hứa Minh Đạt","avatar":""},{"name":"Đỗ Duy Nam","avatar":""},{"name":"BB Trần","avatar":""},{"name":"Cát Tường","avatar":""},{"name":"Hà Trung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Hustler and Scammer","Siêu Lừa Gặp Siêu Lầy","Hustler vs Scammer","เกมกลคนต้มตุ๋น"]', 1784690324251);
