INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('live-phattructiep', 'Live - #pháttrựctiếp', 'Live', 'https://phimimg.com/upload/vod/20240918-1/7f1bfeada42c4f6cc9972e2822f8ff94.jpg', 'https://phimimg.com/upload/vod/20240918-1/79436cbf7d16631b9c776d3fa87278d6.jpg', '<p>Hợp tuyển này theo chân một người phát trực tiếp đầy táo bạo trong mảng mukbang và một người đánh giá gây tranh cãi trên hành trình đầy ám ảnh của họ để có thêm nhiều lượt xem.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Ngọc Phước","avatar":""},{"name":"Khả Như","avatar":""},{"name":"BB Trần","avatar":""},{"name":"Hải Triều","avatar":""},{"name":"Quốc Khánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Live: Phát Trực Tiếp","Live: Phat Truc Tiep","Live - #pháttrựctiếp"]', 1784690324251);
