INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-mat-6-tam-ve-dinh-menh', 'Lật Mặt 6: Tấm Vé Định Mệnh', 'Face Off 6: The Ticket Of Destiny', 'https://phimimg.com/upload/vod/20240919-1/04dc2a0a9dbc3efbb6289dec6349de9e.jpg', 'https://phimimg.com/upload/vod/20240919-1/5c666eeb1ce5b80a0140906109da9d2a.jpg', '<p>Một nhóm bạn thân lâu năm bất ngờ nhận được cơ hội đổi đời &nbsp;khi biết tấm vé của cả nhóm trúng giải độc đắc 136.8 tỷ. Đột nhiên An, người nắm giữ tấm vé bất ngờ gặp tai nạn không qua khỏi. Đứng trước món tiền trúng số đáng mơ ước lẽ ra sẽ dễ dàng có được trong tầm tay, nhóm bạn bước chân vào hành trình đi tìm tờ vé số. Nhưng đó chỉ là khởi đầu của vô số những sự kiện không ngờ đến. Liệu hành trình tìm kiếm và chia chác món tiền trong mơ béo bở này sẽ thực sự dẫn đưa cả nhóm đến đâu?</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Trung Dũng","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"Quốc Cường","avatar":""},{"name":"Tiết Cương","avatar":""},{"name":"Huỳnh Thi","avatar":""},{"name":"Thanh Thức","avatar":""},{"name":"Diệp Bảo Ngọc","avatar":""},{"name":"Thùy Linh","avatar":""},{"name":"Tạ Lâm","avatar":""},{"name":"Tú Tri","avatar":""},{"name":"Quách Ngọc Tuyên","avatar":""},{"name":"Hoàng Mèo","avatar":""},{"name":"Lý Hải","avatar":""},{"name":"Kim Hải","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Face Off 6: The Ticket of Destiny","Lật Mặt 6: Tấm Vé Định Mệnh"]', 1784690324251);
