INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-ta-hai-lam', 'Khi Ta Hai Lăm', 'Twenty Five', 'https://phimimg.com/upload/vod/20240919-1/2e2b77518c497839048258f742c820fc.jpg', 'https://phimimg.com/upload/vod/20240919-1/74047a7d0c9dfc022e969bcf031756d8.jpg', '<p>Tuệ Lâm (Midu) một quản lý nghệ sĩ trẻ với tâm huyết cháy bỏng dành cho nhóm nhạc của mình - The Air. Tuy nhiên một biến cố lớn xảy ra khiến mọi dự định dành cho nhóm bị trì hoãn, còn Tuệ Lâm phải sang Hàn Quốc làm việc. Ngay sau khi trở về, cô quyết tâm khôi phục lại nhóm nhạc đầu tiên mà mình quản lý trong sự nghiệp và cho họ một màn debut xứng đáng.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Lê Dương Bảo Lâm","avatar":""},{"name":"Him Phạm","avatar":""},{"name":"Lãnh Thanh","avatar":""},{"name":"Midu","avatar":""},{"name":"Tiko Tien Cong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["When We Were Young","Khi Ta 25"]', 1784690324251);
