INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-nguoi-nghien-goi-dau', 'Hội Người Nghiện Gội Đầu', 'Miss Shampoo', 'hội người nghiện gội đầu miss shampoo 宋芸樺 hong yu hong 柯震東 蔡昌憲 wei-min ying bai jing yi mei-man jin 苗可麗 郭子乾 洪都拉斯 鍾欣凌 屈中恆 kongkiat limpongsatorn 周群達 lucas ro hsia teng hung 蔡凡熙 胡智強 shao-yu lee chih-ju lin 段鈞豪 吳志慶 bruce he yu-cheng yang shu-wei wu chun-yung wang alvin qing wen hai you na li xu yao jia qiang 請問，還有哪裡需要加強', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chau-bau-doi-toi', 'Châu báu đời tôi', 'My Precious', 'https://phimimg.com/upload/vod/20240918-1/48a3a840eeb3c5c3830e977d8cc57dac.jpg', 'https://phimimg.com/upload/vod/20240918-1/185de10ab947cd24d4747804b495904d.jpg', '<p>Mối tình trong trẻo được tái hiện bởi cặp đôi Nanon (vai Tong) và Film (vai Lin) sẽ khiến khán giả bồi hồi về tình yêu đầu đời trên ghế nhà trường. Tong, cậu nhóc học sinh cá biệt được chuyển bàn ngồi trước Lin, một cô gái chăm chỉ, mọt sách, có vẻ ngoài bí ẩn và là đối tượng theo đuổi của nhiều chàng trai trong trường. Qua những lời thách thức từ &quot;lũ bạn thân trời đánh&quot; của Tong, cả hai dần nhận ra tình cảm đặc biệt họ dành cho nhau.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"กรภัทร์ เกิดพันธุ์","avatar":""},{"name":"Rachanun Mahawan","avatar":""},{"name":"ภวัต จิตต์สว่างดี","avatar":""},{"name":"วชิรวิชญ์ เรืองวิวรรธน์","avatar":""},{"name":"ตรัย นิ่มทวัฒน์","avatar":""},{"name":"ธนเศรษฐ์ สุริยะชัยสกุล","avatar":""},{"name":"เบญญาภา จีนประสม","avatar":""},{"name":"จตุรงค์ พลบูรณ์","avatar":""},{"name":"Pimonwan Hoonthongkam","avatar":""},{"name":"Yingyong Yodbuangam","avatar":""},{"name":"Chitisan Chaisena","avatar":""},{"name":"Puang Kaewprasert","avatar":""},{"name":"Adirek Watleela","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["My Precious รักแรก โคตรลืมยาก","รักแรก โคตรลืมยาก","รักแรกโคตรลืมยาก","My Precious"]', 1784690324251);
