INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chau-bau-doi-toi', 'Châu báu đời tôi', 'My Precious', 'châu báu đời tôi my precious กรภัทร์ เกิดพันธุ์ rachanun mahawan ภวัต จิตต์สว่างดี วชิรวิชญ์ เรืองวิวรรธน์ ตรัย นิ่มทวัฒน์ ธนเศรษฐ์ สุริยะชัยสกุล เบญญาภา จีนประสม จตุรงค์ พลบูรณ์ pimonwan hoonthongkam yingyong yodbuangam chitisan chaisena puang kaewprasert adirek watleela my precious รักแรก โคตรลืมยาก รักแรก โคตรลืมยาก รักแรกโคตรลืมยาก my precious', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-la-so-1-ban-dien-anh', 'Mãi Mãi Là Số 1 (Bản Điện Ảnh)', 'No1 For You', 'https://phimimg.com/upload/vod/20240918-1/75660529904af6a0288dcaae0334784e.jpg', 'https://phimimg.com/upload/vod/20240918-1/a75f53f9ef7035579d699251415807c5.jpg', '<p>Lúc nào cũng bị người khác chèn ép là cảm giác thế nào? Châu Thư Dật trừng mắt nhìn bảng thành tích của cả lớp trong tay, cậu lại một lần nữa trông thấy cái tên Cao Sĩ Đức đè lên đầu mình. Cậu không hiểu, kể từ năm lớp năm khi người này bước vào cuộc đời cậu, vị trí thứ nhất đã bỏ cậu mà đi, để cậu từ “luôn là số một” trở thành “số hai vạn năm”… Cuối cùng, đến năm lớp 12 thì cậu không chịu đựng nổi nữa. Châu Thư Dật cười trộm, tốt lắm, vào đại học là đường ai nấy đi, cuối cùng họ cũng có thể không gặp lại nhau nữa rồi! Châu Thư Dật vui sướng đón chào cuộc sống đại học, cậu vào câu lạc bộ bơi lội mà mình yêu thích nhất, lúc nào cũng được tán tụng. Nào ngờ, trước khi tốt nghiệp, trong một cuộc thi dành cho sinh viên mới gia nhập câu lạc bộ, cậu lại thấy Cao Sĩ Đức xuất hiện. Lần này, không những chưa kịp đoạt giải quán quân trước mặt đàn chị mà mình yêu thầm, cậu còn bị ngã xuống nước, chuột rút suýt nữa chết đuối. Châu Thư Dật chỉ có ba chữ… Thật – muốn – chết! Sau đó cậu lại phát hiện ra đàn chị hẹn hò với cậu bạn thân nhất của mình, cậu càng muốn đập đầu vào gối tự sát, quả nhiên cứ gặp Cao Sĩ Đức là không có chuyện gì tốt đẹp! Cậu không biết trời đất rộng lớn như vậy, tại sao đi đến đâu Cao Sĩ Đức cũng bám theo cậu. Người đó nói… “Tôi luôn dõi theo cậu”, vậy muốn dõi theo đến lúc nào mới chịu buông tha cho cậu đây?</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lâm Tử Hoành","avatar":""},{"name":"YU Dương Vũ Đằng","avatar":""},{"name":"Trương Duệ Gia","avatar":""},{"name":"Thạch Trí Điền","avatar":""},{"name":"Lý Tề","avatar":""},{"name":"Evan Luo","avatar":""},{"name":"Zack Fanchiang","avatar":""},{"name":"Tân Giai Dĩnh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Even Angels Eat Beans","Også engle spiser bønner","Der Dicke in Amerika","Les anges aussi cognent dur","Také andělé jedí fazole","Auch die Engel essen Bohnen","Az angyalok is esznek babot","Anche gli angeli mangiano fagioli"]', 1784690324251);
