INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-quy', 'Ngạ Quỹ', 'Mind Body Spirit', 'https://phimimg.com/upload/vod/20240916-1/38609c4cf01d971357fab4fad66bc8f4.jpg', 'https://phimimg.com/upload/vod/20240916-1/76f4f0c0a9533ca55b7fff04db4a5000.jpg', '<p>Cô gái tình cờ phát hiện một quyển sách cũ trong ngôi nhà của người bà để lại. Phim không dùng hiệu ứng âm thanh làm giật mình, những tình tiết xãy ra trước máy quay của cô gái, mình xem xong cảm thấy kết thúc phim khá bất ngờ. Tên phim chắc dịch đúng là &quot;Thiền định&quot; nhưng do cái kết phim nên để là &quot;Ngạ Quỹ&quot;. Phim xem rất ổn.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sarah J. Bartholomew","avatar":""},{"name":"Madi Bready","avatar":""},{"name":"Anna Knigge","avatar":""},{"name":"Kristi Noory","avatar":""},{"name":"KJ Flahive","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
