INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hannah-waddingham-dem-giang-sinh-am-ap', 'Hannah Waddingham: Đêm Giáng Sinh Ấm Áp', 'Hannah Waddingham: Home For Christmas', 'https://phimimg.com/upload/vod/20240713-1/5a069b97dd292ee3bd9551d0e0de26fc.jpg', 'https://phimimg.com/upload/vod/20240713-1/02f234eafe66be16ca040001f93ecca9.jpg', '<p>Đón chào ngày lễ cùng ngôi sao đoạt giải Emmy, Hannah Waddingham, khi cô chào đón các vị khách đặc biệt cho buổi diễn âm nhạc hoành tráng tại nhà hát London Coliseum.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Hannah Waddingham","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Phil Dunster","avatar":""},{"name":"Brendan Hunt","avatar":""},{"name":"Nick Mohammed","avatar":""},{"name":"Leslie Odom Jr.","avatar":""},{"name":"James Lance","avatar":""},{"name":"Billy Harris","avatar":""},{"name":"Sam Ryder","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324251);
