INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-cua-maxine-cau-chuyen-cua-tyler-perry', 'Con Của Maxine: Câu Chuyện Của Tyler Perry', 'Maxine''s Baby: The Tyler Perry Story', 'https://phimimg.com/upload/vod/20240713-1/ab5ee17cbdabb90ec89bf7eeb5194602.jpg', 'https://phimimg.com/upload/vod/20240713-1/08d9784b077ab316582488270de197fa.jpg', '<p>Tyler Perry là người có nhiều gạch nối hoàn hảo của nước Mỹ. Nhưng bên dưới gã khổng lồ giải trí này là một người đàn ông khiêm tốn làm việc để chữa lành vết thương thời thơ ấu bằng cách biến nỗi đau thành lời hứa. Bộ phim tài liệu này, một sự thể hiện tình yêu của mẹ anh, là một bức chân dung thân mật của Tyler Perry có tầm nhìn xa trông rộng và con đường gian khổ nhưng trung thành của anh để đạt đến đỉnh cao trong một ngành không phải lúc nào cũng có anh.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tyler Perry","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324251);
