INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-dung-pha-hong-bau-vat-nui-foggy', 'Xin Đừng Phá Hỏng: Báu Vật Núi Foggy', 'Please Don''t Destroy: The Treasure Of Foggy Mountain', 'https://phimimg.com/upload/vod/20240711-1/ca626d065106b5c1cc65f289c57eb4f1.jpg', 'https://phimimg.com/upload/vod/20240711-1/093932c601d2267f99bdcc9553c9b744.jpg', '<p>Khi ba người bạn sống cùng nhau nhận ra rằng họ không thích quỹ đạo cuộc sống của mình, họ lên đường đi tìm kho báu vàng được đồn đại là được chôn cất ở ngọn núi gần đó.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Herlihy","avatar":""},{"name":"John Higgins","avatar":""},{"name":"Ben Marshall","avatar":""},{"name":"Conan O''Brien","avatar":""},{"name":"Bowen Yang","avatar":""},{"name":"Megan Stalter","avatar":""},{"name":"X Mayo","avatar":""},{"name":"Nichole Sakura","avatar":""},{"name":"Cedric Yarbrough","avatar":""},{"name":"Chloe Troast","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324251);
