INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-dung-pha-hong-bau-vat-nui-foggy', 'Xin Đừng Phá Hỏng: Báu Vật Núi Foggy', 'Please Don''t Destroy: The Treasure Of Foggy Mountain', 'xin đừng phá hỏng: báu vật núi foggy please don''t destroy: the treasure of foggy mountain martin herlihy john higgins ben marshall conan o''brien bowen yang megan stalter x mayo nichole sakura cedric yarbrough chloe troast ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-vuong', 'Hoa Vương', 'The Flower Of Queen', 'https://phimimg.com/upload/vod/20240915-1/fe9f1234c593b458272dabc4fcec15ca.jpg', 'https://phimimg.com/upload/vod/20240915-1/f40d248f7114c86355b67893e8a6d787.jpg', '<p>Anh Thư là một người phụ nữ tuổi 40, quyết tâm phải nhanh chóng khẳng định vị trí của mình và khao khát thành công bằng mọi giá. Cô bất chấp tất cả mọi thứ để đạt được điều mình muốn, không bao giờ để cho ai coi thường và chà đạp mình. Sau đó, Anh Thư thành công trong việc tiếp cận giám đốc giàu có Hải Đăng (Ngọc Quỳnh) rồi trở thành vợ anh. Thế nhưng cuộc hôn nhân này không dễ dàng như cô hằng tưởng khi bà Trà My (Hồng Ánh) - mẹ kế của chồng cô cũng là một người phụ nữ tham vọng không kém. Vì bảo vệ quyền thừa kế cho con trai bà là Đăng Khoa (Nhật Trường), bà dùng mọi cách để chia rẽ Anh Thư và Hải Đăng. Câu chuyện càng gây cấn hơn khi Trà My phát hiện ra Anh Thư có một đứa con riêng là Trúc Mai (Rima Thanh Vy), mà cô bé đó lại đang yêu đương với đứa con trai yêu quý của bà. Tại sao một người có tất cả mọi thứ (tình yêu, con cái, tiền của và nhan sắc...) như bà Trà My lại không ngừng muốn cướp đoạt gia sản của chồng bà?</p>', 'Hoàn Tất (102/102)', 102, 'series', 'completed', 20, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hồng Ánh","avatar":""},{"name":"Anh Thư","avatar":""},{"name":"Rima Thanh Vy","avatar":""},{"name":"Otis","avatar":""},{"name":"Đỗ Nhật Trường","avatar":""},{"name":"NSƯT Quốc Trọng","avatar":""},{"name":"Thanh Thúy","avatar":""},{"name":"Ngọc Quỳnh","avatar":""},{"name":"Phạm Vũ Thanh Duy","avatar":""},{"name":"Gin Tuấn Kiệt","avatar":""},{"name":"Lê Tam Triều Dâng","avatar":""},{"name":"Hạnh Thúy","avatar":""},{"name":"Lan Hương","avatar":""},{"name":"Ngọc Thuận","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
