INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-dia', 'Thánh Địa', 'Sanctuary', 'https://phimimg.com/upload/vod/20230921-1/8474daca4ed6a6d57e02c6d6c7cd3852.jpg', 'https://phimimg.com/upload/vod/20230921-1/89e1ce6b098062fcd4b692d592bccce5.jpg', '<p>Bị nhốt trong một căn phòng khách sạn ngột ngạt, người thừa kế của một đế chế khách sạn và người thống trị đã giúp anh thành công, bị nhốt trong một cuộc chiến trí tuệ và ý chí khi anh cố gắng chấm dứt mối quan hệ với cô.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Margaret Qualley","avatar":""},{"name":"Christopher Abbott","avatar":""},{"name":"Danita Battle","avatar":""},{"name":"Rene Calvo","avatar":""},{"name":"Christian Casatelli","avatar":""},{"name":"Dominick Defilips","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324251);
