INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thong-long-ma-3', 'Thòng Lọng Ma 3', 'The Rope Curse 3', 'https://phimimg.com/upload/vod/20240913-1/bfba1da059a210a933f316eb7e09cb4e.jpg', 'https://phimimg.com/upload/vod/20240913-1/da94f10ea1d25434a5915f66e6a8a599.jpg', '<p>Khao khát trở thành người có ảnh hưởng trong mảng parkour, một chàng trai tài năng xuất thân từ gia đình trừ tà bị cuốn vào vòng xoáy của những sự kiện ma quái ở khách sạn lạ lùng.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'VIetsub', 'FHD', 'Đài Loan', 0, '[{"name":"Zhang Ting Hu","avatar":""},{"name":"Hsing-Wen Lee","avatar":""},{"name":"Yi-Jung Wu","avatar":""},{"name":"Hsu An-Chih","avatar":""},{"name":"陳博正","avatar":""},{"name":"Hangee Liu","avatar":""},{"name":"Chang Lee","avatar":""},{"name":"王彩樺","avatar":""},{"name":"Chen Wei-Min","avatar":""},{"name":"曾莞婷","avatar":""},{"name":"Vera Chen","avatar":""},{"name":"鄒承恩","avatar":""},{"name":"黃柔閩","avatar":""},{"name":"Tung-Ling Shih","avatar":""},{"name":"Fou-Xi You","avatar":""},{"name":"Liting Hsu","avatar":""},{"name":"Shao-Hui Chen","avatar":""},{"name":"陳昭妃","avatar":""},{"name":"Kang In","avatar":""},{"name":"Cheng-Yang Wu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324251);
