INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-ru', 'Quyến Rũ', 'Tayuan', 'https://phimimg.com/upload/vod/20230921-1/3acc325615710d72cd39797cf9989653.jpg', 'https://phimimg.com/upload/vod/20230921-1/744dca70dd98e4f092c8c5b536bd1777.jpg', '<p>Ella, người quản lý dự án sự kiện, thường sử dụng dịch vụ vận chuyển tư nhân. Tuy nhiên, cô buộc phải đi xe buýt, nơi người soát vé xe buýt Rico trở nên phấn khích khi cơ thể cô bị ép vào anh ta do đám đông dày đặc. Cuộc gặp gỡ này ảnh hưởng sâu sắc đến Ella, và từ đêm đó trở đi, cô bắt đầu theo đuổi Rico. Ngay cả sau khi phát hiện ra rằng Rico đã kết hôn và có một cô con gái, Ella vẫn không quan tâm và sẽ làm bất cứ điều gì để khiến anh ấy cũng muốn cô ấy nhiều như vậy.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Angeli Khang","avatar":""},{"name":"Stephanie Raz","avatar":""},{"name":"Chester Grecia","avatar":""},{"name":"Francine Garcia","avatar":""},{"name":"Rash Flores","avatar":""},{"name":"PJ Rosario","avatar":""},{"name":"Anthony Dabao","avatar":""},{"name":"Dianne Moldez","avatar":""},{"name":"Benz Sangalang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '[]', 1784690324251);
