INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dia-cau-luu-lac-2', 'Địa Cầu Lưu Lạc 2', 'The Wandering Earth II', 'https://phimimg.com/upload/vod/20231018-1/fd4d49a3dcf284524c33b5ef51cd5357.jpg', 'https://phimimg.com/upload/vod/20231018-1/4c0e24f0ffc9a8f5d60522778c59ba9b.jpg', '<p>Con người đã chế tạo những động cơ khổng lồ trên bề mặt trái đất để tìm một ngôi nhà mới. Nhưng con đường đến với vũ trụ thật nguy hiểm. Để cứu trái đất, những người trẻ tuổi một lần nữa phải bước ra để bắt đầu một cuộc chạy đua với thời gian cho sự sống và cái chết.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Jing","avatar":""},{"name":"Sha Yi","avatar":""},{"name":"Zhu-Yan Manzi","avatar":""},{"name":"Li Xuejian","avatar":""},{"name":"Andy Friend","avatar":""},{"name":"Wang Zhi","avatar":""},{"name":"Kawawa Kadichi","avatar":""},{"name":"Vatilli Makarychev","avatar":""},{"name":"Clara Lee","avatar":""},{"name":"Tony Nicholson","avatar":""},{"name":"Vladimir Ershov","avatar":""},{"name":"Li Ren","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Wang Ruoxi","avatar":""},{"name":"Ning Li","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Tong Liya","avatar":""},{"name":"Ang Cin","avatar":""},{"name":"Guo Yiqian","avatar":""},{"name":"Wu Enxuan","avatar":""},{"name":"Liu Jiayun","avatar":""},{"name":"Ding","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324251);
