INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-oi-chao-mi-2023', 'Ma Ơi Chào Mi!', 'Hello Ghost!', 'https://phimimg.com/upload/vod/20240913-1/dece4fee56278e41ee7b8e01560cd7a0.jpg', 'https://phimimg.com/upload/vod/20240913-1/a4fe0c7a1faee83950ad75ff1bc078bf.jpg', '<p>Bộ phim này được chuyển thể từ bom tấn Hàn Quốc năm 2010 và bộ phim hài lấy nước mắt Hello Ghost. Một người đàn ông giao hàng cô đơn, A-wei, cố gắng tự tử nhiều lần nhưng bất kể anh ta có làm gì đi chăng nữa. Thông qua những nỗ lực thất bại này, anh gặp bốn hồn ma - một con ma hút thuốc, một kẻ hay kêu ca, một con ma đau khổ và một con ma tinh nghịch. Để có thể chết, anh biết rằng trước tiên anh phải giúp bốn hồn ma này thực hiện được tâm nguyện cuối cùng của họ. Trong quá trình đó, A-wei kết bạn với bốn hồn ma này và vượt qua lòng tự trọng thấp kém của mình để bước ra khỏi vùng an toàn và trải nghiệm nhiều điều đầu tiên trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"曾敬驊","avatar":""},{"name":"邵雨薇","avatar":""},{"name":"陸弈靜","avatar":""},{"name":"Tsai-Hsing Chang","avatar":""},{"name":"Jia-Yin Tsai","avatar":""},{"name":"Chun-Hao Hung","avatar":""},{"name":"Bai Jing Yi","avatar":""},{"name":"謝坤達","avatar":""},{"name":"陳博正","avatar":""},{"name":"Vent Teng","avatar":""},{"name":"郁方","avatar":""},{"name":"Bryan Shu-Hao Chang","avatar":""},{"name":"Ralf Chiu","avatar":""},{"name":"Wei-min Ying","avatar":""},{"name":"Ying-Hung Lee","avatar":""},{"name":"Calvin Tsou","avatar":""},{"name":"Lilo Kao","avatar":""},{"name":"Frances Cheng","avatar":""},{"name":"洪毓璟","avatar":""},{"name":"Yi-Ting Yeh","avatar":""},{"name":"潘客印","avatar":""},{"name":"Kurt Hsiao","avatar":""},{"name":"Yi-Le Huang","avatar":""},{"name":"Ian Hsie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324251);
