INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-co-dong-song-chay', 'Chỉ Có Dòng Sông Chảy', 'Only the River Flows', 'https://phimimg.com/upload/vod/20240910-1/114ba6f9660f93517ed26fa198e2d940.jpg', 'https://phimimg.com/upload/vod/20240910-1/d8af50b4078caeaeb5d2ee98fefa981f.jpg', '<p>Phim nói về cảnh sát hình sự Mã Triết, do Chu Nhất Long đóng, điều tra vụ sát hại một phụ nữ có tuổi ở một thị trấn ven sông miền nam Trung Quốc những năm 1990. Khi cuộc điều tra tiến triển, những bí mật bị chôn giấu của thị trấn lộ ra, đỉnh điểm là nhiều người chết ảnh hưởng đến tinh thần của cảnh sát Mã.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"朱一龍","avatar":""},{"name":"曾美慧孜","avatar":""},{"name":"Hou Tianlai","avatar":""},{"name":"Tong Linkai","avatar":""},{"name":"Zeng Qi","avatar":""},{"name":"Wang Jianyu","avatar":""},{"name":"刘白沙","avatar":""},{"name":"周遊","avatar":""},{"name":"楚布花羯","avatar":""},{"name":"Chunlin Mo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
