INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-hay-thu', 'Bạn Hay Thù', 'Foe', 'https://phimimg.com/upload/vod/20240713-1/6299ee9a66ef89a4613afeeb5818fa30.jpg', 'https://phimimg.com/upload/vod/20240713-1/11219d0888ae1835b32d06056ba6ef91.jpg', '<p>Henrietta và Junior làm trang trại trên một mảnh đất hẻo lánh đã thuộc về gia đình Junior qua nhiều thế hệ, nhưng cuộc sống bình lặng của họ rơi vào tình trạng hỗn loạn khi một người lạ không mời mà đến xuất hiện trước cửa nhà họ với một lời cầu hôn bất ngờ. Liệu họ có mạo hiểm mối quan hệ và danh tính cá nhân của mình để có cơ hội sống sót trong một thế giới mới?</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Paul Mescal","avatar":""},{"name":"Aaron Pierre","avatar":""},{"name":"Jordan Chodziesner","avatar":""},{"name":"William Freeman","avatar":""},{"name":"Jalen Ong","avatar":""},{"name":"Patrick Williams","avatar":""},{"name":"David Woods","avatar":""},{"name":"Yesse Spence","avatar":""},{"name":"Shamita Sivabalan","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324251);
