INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-to-bang-coc', 'Bão Tố Băng Cốc', 'Bangkok Storm', 'https://phimimg.com/upload/vod/20230926-1/6016680b72c67264e2416539e73e4d59.jpg', 'https://phimimg.com/upload/vod/20230926-1/c0d7fb268dd4a915bcaae74244dab9ac.jpg', '<p>Bão Tố Băng Cốc – Bangkok Storm (2023) lấy bối cảnh vào mùa hè năm 2010, bên cạnh sông Chao Phraya, Lin Feng, người đầy thương tích, mắc cạn trên bờ và được phát hiện bởi quản đốc Fei Lai. Dưới sự chăm sóc cẩn thận của Fei Lai và con gái Xiao Lai, Lin Feng nhanh chóng tỉnh lại, nhưng trí nhớ của anh đã bị mất hoàn toàn. Chachai, ông chủ da đen, muốn ký hợp đồng với đất đai của Feilai, và luôn gây rắc rối cho công trường xây dựng của Feilai, trong vòng tay của Lin Feng, người đến sau.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Fan Siu-wong","avatar":""},{"name":"Zaimire Aheiti","avatar":""},{"name":"Jeff Liu","avatar":""},{"name":"Xiong Xinxin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324251);
