INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-thuong-chang-the-roi-le', 'Đau Thương Chẳng Thể Rơi Lệ', 'Behind The Blue Eyes', 'https://phimimg.com/upload/vod/20240911-1/12977f0d2eba05446d4df3d0301382a1.jpg', 'https://phimimg.com/upload/vod/20240911-1/1e395e2ba13ca1367eee4205304457cb.jpg', '<p>Triệu Tâm Huỷ (Hà Lam Đậu) và Lâm Hán Thông (Thái Phàm Hi) là bạn bè từ thuở bé, cả hai xác định đời này sẽ ở bên nhau cho đến mai sau. Khoảng thời gian trưởng thành mang đến những cột mốc mới mẻ cho mối quan hệ của hai người. Rất nhiều rào cản khiến họ không ít lần phải buông tay, đặc biệt là sự ngăn cấm từ gia đình và màn tỏ tình bất ngờ của Trần Hiếu Danh (Hứa Quang Hán thủ vai) dành cho Triệu Tâm Hủy. Theo thời gian, nội tâm của Triệu Tâm Hủy bắt đầu lung lay, cô do dự khi nghĩ đến việc hàn gắn với Lâm Hán Thông. Chẳng biết là vì đã hết yêu hay đang mong cầu điều gì, cả hai người đều trở nên mệt mỏi với điều mà họ cố gắng gìn giữ nhiều năm qua. Liệu họ sẽ bỏ lỡ nhau hay cùng nằm tay đi qua mọi khó khăn?</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Lam Đậu","avatar":""},{"name":"Sái Phàm Hi","avatar":""},{"name":"Hứa Quang Hán","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
