INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tat-ca-chung-ta-deu-la-nguoi-la', 'Tất Cả Chúng Ta Đều Là Người Lạ', 'All of Us Strangers', 'https://phimimg.com/upload/vod/20240310-1/960179905542d3792bae1d13a3a5cd13.jpg', 'https://phimimg.com/upload/vod/20240310-1/6b56eafbe37ccdd2a562fc88dd3206b4.jpg', '<p>Một đêm nọ trong căn hộ trống rỗng của mình ở London hiện đại, Adam có cơ hội gặp gỡ với người hàng xóm bí ẩn Harry, người đã phá vỡ nhịp sống hàng ngày của anh. Khi mối quan hệ phát triển giữa họ, Adam bận tâm đến những ký ức về quá khứ và thấy mình bị kéo trở lại thị trấn ngoại ô nơi anh lớn lên và ngôi nhà thời thơ ấu nơi cha mẹ anh dường như đang sống, giống như ngày họ qua đời vào 30 năm trước.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Andrew Scott","avatar":""},{"name":"Paul Mescal","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Claire Foy","avatar":""},{"name":"Carter John Grout","avatar":""},{"name":"Ami Tredrea","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324251);
