INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-truoc-ngay-cuoi', 'Yêu Trước Ngày Cưới', 'Before We Get Married', 'https://phimimg.com/upload/vod/20240909-1/ea4c7c87ca9102d79a398fced35c96bd.jpg', 'https://phimimg.com/upload/vod/20240909-1/8a43ebf50386936491ae1349b56d6338.jpg', '<p>Yêu trước ngày cưới lột tả một cách chân thật về quan điểm tình yêu và lối sống tình dục của giới trẻ hiện nay. Không chỉ bóc tách những vấn đề nhức nhối, những góc khuất trước (lẫn ngoài) hôn nhân mà giới trẻ phải đối diện, phim còn là hành trình trưởng thành của người trẻ, lựa chọn con đường khiến mình cảm thấy tự do và hạnh phúc nhất.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Song Luân","avatar":""},{"name":"Minh Trang","avatar":""},{"name":"Tran Quoc Anh","avatar":""},{"name":"Sĩ Thanh","avatar":""},{"name":"Nhã Phương","avatar":""},{"name":"Hữu Vi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
