INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-truoc-ngay-cuoi', 'Yêu Trước Ngày Cưới', 'Before We Get Married', 'yêu trước ngày cưới before we get married song luân minh trang tran quoc anh sĩ thanh nhã phương hữu vi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rat-nho-rat-nho-anh', 'Rất Nhớ, Rất Nhớ Anh', 'Love Me, Love My Voice', 'https://phimimg.com/upload/vod/20240909-1/f2006bf952c0814a4d9e6da8fd99f284.jpg', 'https://phimimg.com/upload/vod/20240909-1/8d879cde2d1eac8bd25aee89b5b78854.jpg', '<p>Bộ phim kể về hành trình kiên trì theo đuổi ước mơ của cô sinh viên năm tư đam mê âm nhạc, Cố Thanh. Cô âm thầm che giấu thân phận &quot;Thanh Thanh Mạn&quot;, ca sĩ vô danh trong làng nhạc cổ phong của mình, đồng thời khao khát được hợp tác một lần với cao thủ &quot;Thương Thanh Từ&quot; trong giới lồng tiếng mà cô luôn thầm thương trộm nhớ. Trùng hợp thay, cô và Mạc Thanh Thành (&quot;Thương Thanh Từ&quot; ngoài đời) đã vô tình quen biết nhau trong một sự kiện. Nhờ sự giúp đỡ nhiệt tình của bạn thân, khoảng cách của hai người dần thu hẹp. Sau đó, Mạc Thanh Thành đã dùng đồ ăn ngon và giọng nói của mình làm &quot;mồi nhử&quot; để thực hiện kế hoạch theo đuổi mưa dầm thấm lâu. Đợi tới khi Cố Thanh nhận ra thì cô đã rơi vào cạm bẫy tình yêu ngọt ngào với Mạc Thanh Thành…</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"檀兮爾","avatar":""},{"name":"周也","avatar":""},{"name":"侯雯元","avatar":""},{"name":"楊肸子","avatar":""},{"name":"曹恩齊","avatar":""},{"name":"Chen Haolan","avatar":""},{"name":"Zhang Qiaoer","avatar":""},{"name":"涓子","avatar":""},{"name":"Chen Guan Ning","avatar":""},{"name":"劉哲琿","avatar":""},{"name":"Liang Tian","avatar":""},{"name":"Xia Ningjun","avatar":""},{"name":"陳澤","avatar":""},{"name":"Shi An","avatar":""},{"name":"Yang Dongqi","avatar":""},{"name":"Xia Zhen","avatar":""},{"name":"Wang Zhi-Yi","avatar":""},{"name":"Huang Erchun","avatar":""},{"name":"Zou Jixin","avatar":""},{"name":"Kong Qingxin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
