INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rat-nho-rat-nho-anh', 'Rất Nhớ, Rất Nhớ Anh', 'Love Me, Love My Voice', 'rất nhớ, rất nhớ anh love me, love my voice 檀兮爾 周也 侯雯元 楊肸子 曹恩齊 chen haolan zhang qiaoer 涓子 chen guan ning 劉哲琿 liang tian xia ningjun 陳澤 shi an yang dongqi xia zhen wang zhi-yi huang erchun zou jixin kong qingxin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tro-tinh-yeu', 'Quán Trọ Tình Yêu', 'The Secret Romantic Guesthouse', 'https://phimimg.com/upload/vod/20240909-1/9d235b5b33ba581518a8d6571c96a8ce.jpg', 'https://phimimg.com/upload/vod/20240909-1/5eda56990605b4abb3f3ca11bcbffd76.jpg', '<p>kể về Yoon Dan Oh, người từng tận hưởng cuộc sống sung túc với tư cách là cô con gái út yêu quý của một gia đình khá giả, nhưng giờ thì không còn nữa. Cô ấy hiện là trụ cột của gia đình và điều hành nhà trọ Ihwawon, nơi có nhiều khách mời là các học giả đến Hanyang để tham gia kỳ thi tuyển công chức để trở thành quan chức cấp cao.\r\nTrong số các học giả ở tại nhà trọ Ihwawon có Kang San, Kim Si Yeol và Jeong Yoo Ha, tất cả đều có những bí mật sâu sắc. Yoon Dan Oh và những người ở trọ kết hợp thông tin của họ và hợp tác để tìm Lee Seol, người đã biến mất 13 năm trước.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"신예은","avatar":""},{"name":"려운","avatar":""},{"name":"강훈","avatar":""},{"name":"정건주","avatar":""},{"name":"한채아","avatar":""},{"name":"현우","avatar":""},{"name":"오만석","avatar":""},{"name":"이준혁","avatar":""},{"name":"인교진","avatar":""},{"name":"안내상","avatar":""},{"name":"이미도","avatar":""},{"name":"Jo Hye-joo","avatar":""},{"name":"Hwang Bo-reum-byeol","avatar":""},{"name":"Kwon Do-hyung","avatar":""},{"name":"Gil Eun-hye","avatar":""},{"name":"남기애","avatar":""},{"name":"주석태","avatar":""},{"name":"Jung Yoo-hyeon","avatar":""},{"name":"Song Ji-hyuk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324251);
