INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-ngay-tho-nguoi-tung-trai-va-cau-chuyen-tinh-cua-chung-toi', 'Kẻ Ngây Thơ Người Từng Trải Và Câu Chuyện Tình Của Chúng Tôi', 'Our Dating Story: The Experienced You and the Inexperienced Me', 'https://phimimg.com/upload/vod/20240908-1/8af210d7326095be010fd9c9a0894f51.jpg', 'https://phimimg.com/upload/vod/20240908-1/c2c5346af28013be4e2085cea6a3ff01.jpg', '<p>Ryuuto Kashima là một học sinh cao trung buồn thấy bà. Như thử thách của trò chơi, anh buộc phải tỏ tình với Runa Shirakawa, cô gái đứng đầu trường được nhiều người ngưỡng mộ. Cuối cùng cả hai đã hẹn hò với nhau vì lý do, &quot;Ờ, giờ tôi cũng khá rảnh...&quot;. Đủ thứ mọi chuyện giữa hai người bắt đầu diễn ra từ đây.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"花江夏樹","avatar":""},{"name":"大西沙織","avatar":""},{"name":"古賀葵","avatar":""},{"name":"福原綾香","avatar":""},{"name":"楠木ともり","avatar":""},{"name":"落合福嗣","avatar":""},{"name":"阪口大助","avatar":""},{"name":"前野智昭","avatar":""},{"name":"KUN","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324251);
