INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-mua-dong', 'Mặt Trời Mùa Đông', 'Winter Sun', 'https://phimimg.com/upload/vod/20240902-1/9e5659b5eb0baedbbb9226c2992ad1e3.jpg', 'https://phimimg.com/upload/vod/20240902-1/d0ff5882664c1de381a61175dcfb17a8.jpg', '<p>Minh Hoàng và Minh Huy là hai anh em sinh đôi vô cùng gắn bó. Trong một vụ án mạng được sắp đặt, Minh Huy đã bị bọn xấu bắt đi và thay đổi tên họ. Mặc dù duyên trời khiến hai anh em có cơ hội đoàn tụ, nhưng chưa kịp vui vẻ họ đã tiếp tục bị cuốn vào vòng xoáy giết chóc.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Steven Nguyễn","avatar":""},{"name":"Trình Mỹ Duyên","avatar":""},{"name":"Quỳnh Lương","avatar":""},{"name":"Đại Nghĩa","avatar":""},{"name":"Huy Khánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
