INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tuoi-xe-chieu', 'Tình Yêu Tuổi Xế Chiều', 'Love Never Ends', 'https://phimimg.com/upload/vod/20231101-1/6d67c444e3b3ac1822010e9386602198.jpg', 'https://phimimg.com/upload/vod/20231101-1/1ad7570e8f290b1921a9aea69659a54c.jpg', '<p>Bạn đã bao giờ tự hỏi mình sẽ già đi như thế nào chưa? Bốn người 60 tuổi, hai mối tình xế chiều, tình yêu của họ thật trong sáng, lãng mạn và mãnh liệt. Trong hành trình hữu hạn của cuộc đời này, trước khi quá muộn, ai cũng muốn nói rằng I love you!</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ni Dahong","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"Cheng Guo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324251);
