INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('007-tro-thanh-trieu-phu', '007: Trở Thành Triệu Phú', '007: Road To A Million', 'https://phimimg.com/upload/vod/20240630-1/b12a590397bd30fcb4d4aa1b9d58159a.jpg', 'https://phimimg.com/upload/vod/20240630-1/4cb71468acad5f6d5bb6d483dfac3e5a.jpg', '<p>Chín cặp người thường được đưa vào một cuộc phiêu lưu toàn cầu hoành tráng thông qua một loạt thử thách lấy cảm hứng từ Bond, để có cơ hội giành được giải thưởng thay đổi cuộc đời trị giá 1.000.000 bảng Anh. Người điều khiển, Brian Cox, là người chủ mưu đằng sau trò chơi, theo dõi các cặp khi họ truy tìm 10 câu hỏi mà anh ta đang giấu kín trên khắp thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brian Cox","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324251);
