INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harlan-cobens-shelter', 'Harlan Coben''s Shelter', 'Harlan Coben''s Shelter', 'https://phimimg.com/upload/vod/20240630-1/7a5a51400a46d3bc2080b1e36017bd5a.jpg', 'https://phimimg.com/upload/vod/20240630-1/59ec60887fd88eab07f76d77847743c4.jpg', '<p>Theo dõi câu chuyện của Mickey Bolitar sau cái chết của cha anh, đưa anh bắt đầu cuộc sống mới ở ngoại ô New Jersey. Khi một học sinh mới khác biến mất, Mickey thấy mình bị vướng vào một mạng lưới bí mật. Với sự giúp đỡ của hai người bạn mới, Spoon và Ema, họ khám phá ra một thế giới ngầm đen tối có thể chứa đựng câu trả lời cho những vụ mất tích hàng thập kỷ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jaden Michael","avatar":""},{"name":"Constance Zimmer","avatar":""},{"name":"Didi Conn","avatar":""},{"name":"Adrian Greensmith","avatar":""},{"name":"Abby Corrigan","avatar":""},{"name":"Jen Jacob","avatar":""},{"name":"Brian Altemus","avatar":""},{"name":"Sage Linder","avatar":""},{"name":"Geoffrey Cantor","avatar":""},{"name":"Samantha Bugliaro","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324251);
