INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wolf-like-me-phan-2', 'Wolf Like Me (Phần 2)', 'Wolf Like Me (Season 2)', 'https://phimimg.com/upload/vod/20240630-1/21b3dea7a686a0435b882b4e3319b7d0.jpg', 'https://phimimg.com/upload/vod/20240630-1/a8169d00bd7b5b3450ca86ea4fbf3138.jpg', '<p>Trong phần hai, Mary và Gary bước sang giai đoạn tiếp theo của mối quan hệ và đối mặt với thử thách lớn nhất của họ: mang thai. Dù họ cố gắng để có một thai kỳ bình thường nhưng dường như điều đó là không thể với rất nhiều câu hỏi đặt ra cho họ. Con của họ sẽ là một đứa trẻ hay một con sói con? Họ có thể giữ bí mật mọi chuyện với những người còn lại trong gia đình trong bao lâu? Và liệu những gì xảy ra ở vùng hẻo lánh có quay trở lại ám ảnh họ không? Nhưng khi giáo sư cũ của Mary, Anton, đột nhiên xuất hiện trở lại trong cuộc đời cô, những bí mật mới về quá khứ của Mary được tiết lộ, khiến Mary và Gary phải đặt câu hỏi liệu họ có thực sự muốn ở bên nhau hay không.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 16, 2023, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Isla Fisher","avatar":""},{"name":"Josh Gad","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324251);
