INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-dau-tinh-quai', 'Nàng Dâu Tinh Quái', 'Devil In Law', 'https://phimimg.com/upload/vod/20240831-1/3702dc28fd16c75e9197f20ab1301aa3.jpg', 'https://phimimg.com/upload/vod/20240831-1/5c2c5b518001ba4111cf1a5ed7e285b2.jpg', '<p>Nàng Dâu Tinh Quái - Devil in Law kể về Srikanda, chị gái của Pawinee, là một người phụ nữ xinh đẹp khiến cha cô hết lòng tự hào. Cô yêu Noppanai và bất chấp sự phản đối của cha cô, họ quyết định bỏ trốn. Một ngày nọ, Pawinee tình cờ gặp lại Srikanda trong bộ dạng gầy gò hốc hác và không lâu sau đó, Srikanda qua đời. Pawinee rất tức giận sau khi biết chị gái mình bị mẹ và chị dâu bạo hành nên cô đã quyết định ký vào giấy đăng ký kết hôn với Noppanai với thỏa thuận &quot;không động chạm&quot; để có thể chăm sóc cháu trai. Sau khi kết hôn, Pawinee chuyển đến nơi chị gái cô từng sống và bắt đầu gây chiến với mẹ và chị gái của anh. Khác với Srikanda, cô đối đầu với họ không khoan nhượng và cuộc trả thù của cô bắt đầu từ đây.</p>', 'Hoàn Tất (34/34)', 17, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Nawasch Phupantachsee","avatar":""},{"name":"ณัฏฐณิชา ดังวัธนาวณิชย์","avatar":""},{"name":"Butsakorn Wongpuapan","avatar":""},{"name":"Pitchapa Phanthumchinda","avatar":""},{"name":"Paswitch Boorananut","avatar":""},{"name":"Lorena Schuett","avatar":""},{"name":"Chartayodom Hiranyatithi","avatar":""},{"name":"Fundee Junyatanakron","avatar":""},{"name":"Rungrawan Tonahongsa","avatar":""},{"name":"Tae Nuntasai Pisolyabut","avatar":""},{"name":"Athichanan Srisevok","avatar":""},{"name":"Sippoth","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
