INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang-dau-tinh-quai', 'Nàng Dâu Tinh Quái', 'Devil In Law', 'nàng dâu tinh quái devil in law nawasch phupantachsee ณัฏฐณิชา ดังวัธนาวณิชย์ butsakorn wongpuapan pitchapa phanthumchinda paswitch boorananut lorena schuett chartayodom hiranyatithi fundee junyatanakron rungrawan tonahongsa tae nuntasai pisolyabut athichanan srisevok sippoth ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoa-thuan-voi-ac-quy', 'Thoả Thuận Với Ác Quỷ', 'The Devil''s Deal', 'https://phimimg.com/upload/vod/20240827-1/7424faf8f5cb245a05dba83d305c444c.jpg', 'https://phimimg.com/upload/vod/20240827-1/5447e3c082233f407b6ccadc9bfd6ab6.jpg', '<p>Hae-woong, một ứng cử viên quốc hội, bị loại khỏi cuộc tranh cử vì anh trở thành cái gai trong mắt Sun-tae, một nhân vật quan trọng ở địa phương. Bị những kẻ cho vay nặng lãi săn lùng, do không trả được khoản vay trong chiến dịch tranh cử, anh quyết định làm bẩn tay mình. Anh ta đánh cắp thông tin mật của chính phủ về kế hoạch phát triển đô thị và nhận được sự giúp đỡ của thủ lĩnh băng đảng địa phương, Pil-do, bằng cách hứa hẹn lợi nhuận bất động sản khổng lồ. Bây giờ Hae-woong quay lại cuộc đua và cố gắng trả thù Sun-tae. Anh ta không hề hay biết, hành trình chính trị lộn xộn của anh ta chỉ mới bắt đầu.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"조진웅","avatar":""},{"name":"이성민","avatar":""},{"name":"김무열","avatar":""},{"name":"Won Hyun-jun","avatar":""},{"name":"김민재","avatar":""},{"name":"유승목","avatar":""},{"name":"Kim Yoon-sung","avatar":""},{"name":"Park Se-jin","avatar":""},{"name":"손여은","avatar":""},{"name":"Lee Sang-won","avatar":""},{"name":"박정표","avatar":""},{"name":"Park Dae-chul","avatar":""},{"name":"Heo Ji-won","avatar":""},{"name":"Han Gab-soo","avatar":""},{"name":"조영진","avatar":""},{"name":"Choi Min-cheol","avatar":""},{"name":"Seo Young-sam","avatar":""},{"name":"Choi Dong-goo","avatar":""},{"name":"노태우","avatar":""},{"name":"김영삼","avatar":""},{"name":"김대중","avatar":""},{"name":"Moon Soon-ju","avatar":""},{"name":"Moon Jung-dae","avatar":""},{"name":"Kim Sung-gon","avatar":""},{"name":"Kim Woo-hyun","avatar":""},{"name":"최","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324251);
