INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-ta-gap-nhau-o-tokyo', 'Khi Ta Gặp Nhau Ở Tokyo', 'When I Met You In Tokyo', 'https://phimimg.com/upload/vod/20240827-1/9be6848b44f78d70733fff7141662185.jpg', 'https://phimimg.com/upload/vod/20240827-1/78c3b020c8c0b6088d464ccaed90e714.jpg', '<p>Chẳng còn ý định yêu đương, hai người nước ngoài lớn tuổi cùng nhau có khởi đầu mới khi họ tìm lại tình yêu và chấp nhận quá khứ trắc trở.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Christopher de Leon","avatar":""},{"name":"Vilma Santos","avatar":""},{"name":"Cassy Legaspi","avatar":""},{"name":"Darren Espanto","avatar":""},{"name":"Kakai Bautista","avatar":""},{"name":"Lynn Ynchausti-Cruz","avatar":""},{"name":"John Gabriel","avatar":""},{"name":"Jacky Woo","avatar":""},{"name":"Gina Alajar","avatar":""},{"name":"Gabby Eigenmann","avatar":""},{"name":"Lotlot De Leon","avatar":""},{"name":"Tirso Cruz III","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324251);
