INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dom-dom', 'Đom Đóm', 'Firefly', 'https://phimimg.com/upload/vod/20240827-1/ed49336ed4429f4e449eefe22ffae7dd.jpg', 'https://phimimg.com/upload/vod/20240827-1/97f185803e51852fc797474d229aefa7.jpg', '<p>Bộ phim kể về cuộc tìm kiếm hòn đảo đom đóm thần thoại của một cậu bé được mô tả trong những câu chuyện trước khi đi ngủ của mẹ mình. Sử dụng &quot;manh mối&quot; mà cậu tin rằng mẹ mình để lại trong một cuốn sổ cũ, cậu bé thực hiện cuộc hành trình dài đến hòn đảo kỳ diệu để ước bà sống lại.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Alessandra de Rossi","avatar":""},{"name":"Euwenn Mikaell","avatar":""},{"name":"Dingdong Dantes","avatar":""},{"name":"Miguel Tanfelix","avatar":""},{"name":"Ysabel Ortega","avatar":""},{"name":"Cherry Pie Picache","avatar":""},{"name":"Epy Quizon","avatar":""},{"name":"Yayo Aguila","avatar":""},{"name":"Max Collins","avatar":""},{"name":"Kokoy de Santos","avatar":""},{"name":"Erlinda Villalobos","avatar":""},{"name":"Elle Villanueva","avatar":""},{"name":"Raul Dillo","avatar":""},{"name":"Dindo Arroyo","avatar":""},{"name":"Gigi Locsin","avatar":""},{"name":"Juancho Triviño","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324251);
