INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-nhi-ngay-tan-the', 'Điệp Viên Nhí: Ngày Tận Thế', 'Spy Kids: Armageddon', 'https://phimimg.com/upload/vod/20230925-1/aab58cdc0facbaf342c436b9bab9450a.jpg', 'https://phimimg.com/upload/vod/20230925-1/f98c24b42e44259b8b0b5a6cf1054889.jpg', '<p>Khi nhà phát triển trò chơi nọ tung ra loại virus máy tính mạnh mẽ, các con của hai mật vụ phải bắt tay để cứu bố mẹ và cả thế giới.</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Connor Esterson","avatar":""},{"name":"Everly Carganilla","avatar":""},{"name":"Zachary Levi","avatar":""},{"name":"Gina Rodriguez","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"D.J. Cotrona","avatar":""},{"name":"Joe Schilling","avatar":""},{"name":"Solar Dena Bennett","avatar":""},{"name":"Nicholas Ortiz","avatar":""},{"name":"Brody Stowers","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324251);
