INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vien-nhi-ngay-tan-the', 'Điệp Viên Nhí: Ngày Tận Thế', 'Spy Kids: Armageddon', 'điệp viên nhí: ngày tận thế spy kids: armageddon connor esterson everly carganilla zachary levi gina rodriguez billy magnussen d.j. cotrona joe schilling solar dena bennett nicholas ortiz brody stowers ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-chang-ngoc-2023', '3 Chàng Ngốc', '3 Idiot Heroes', 'https://phimimg.com/upload/vod/20240827-1/1aa790bd28822033f64b466b222cb8c7.jpg', 'https://phimimg.com/upload/vod/20240827-1/db4ff71a0d012de32f73eab9b9a5dcd7.jpg', '<p>3 Idiot Heroes là một bộ phim xoay quanh câu chuyện trong mùa thu hoạch hạt giống ở làng Ban Rabue. Trong phim, người xem sẽ được gặp lại nhân vật Ngern, người có trách nhiệm thu thập và tích trữ những hạt giống quan trọng cho cả làng. Cuộc sống yên bình của Ngern bị xáo trộn khi một nhóm trộm mặt đen âm mưu đánh cắp hạt giống. Trong lúc vô tình phải tự vệ, Ngern đã không may giết chết nhóm tội phạm này. Tuy nhiên, việc này đã gây ra rối ren và nguy hiểm tiềm ẩn cho ngôi làng. Để bảo vệ cộng đồng và ngăn chặn sự tái diễn của các cuộc tấn công, Ngern quyết định lên đường cùng hai người bạn của mình để tìm súng và mang về. Hành trình của ba anh hùng này không chỉ đơn thuần là đi tìm súng, mà còn là cuộc phiêu lưu khám phá và chiến đấu với những kẻ xấu trong các cuộc chiến khốc liệt sắp tới. Bằng lòng dũng cảm và sự thông minh, họ sẽ đối mặt với những thách thức và nguy hiểm để bảo vệ ngôi làng của mình. 3 Idiot Heroes mang lại cho khán giả những cảnh quay mãn nhãn, những tình huống hài hước và cảm xúc sâu lắng. Bộ phim này không chỉ là một câu chuyện giải trí, mà còn chứa đựng thông điệp về tình yêu, lòng dũng cảm và sự đoàn kết trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"แจ๊ส ชวนชื่น","avatar":""},{"name":"Akkharadech Yodjampa","avatar":""},{"name":"Arthit Somnoi","avatar":""},{"name":"Paparwadee Chansamorn","avatar":""},{"name":"Somphong Kunapratom","avatar":""},{"name":"Chonnipha Wisetsood","avatar":""},{"name":"จิราวัฒน์ วชิรศรัณย์ภัทร","avatar":""},{"name":"Chaleumpol Tikumpornteerawong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324251);
