INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('3-chang-ngoc-2023', '3 Chàng Ngốc', '3 Idiot Heroes', '3 chàng ngốc 3 idiot heroes แจ๊ส ชวนชื่น akkharadech yodjampa arthit somnoi paparwadee chansamorn somphong kunapratom chonnipha wisetsood จิราวัฒน์ วชิรศรัณย์ภัทร chaleumpol tikumpornteerawong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thuat-dac-biet-cua-phu-thuy-quay-nguoc-thoi-gian', 'Ma Thuật Đặc Biệt Của Phù Thủy Quay Ngược Thời Gian', 'A Returner''s Magic Should Be Special', 'https://phimimg.com/upload/vod/20240826-1/63ede590c97403d99dc0c1b1b71f06a9.jpg', 'https://phimimg.com/upload/vod/20240826-1/d177736ff25b6802301c88aa8e27fcd4.jpg', '<p>Thế giới đứng trước bờ vực diệt vong sau cuộc chiến tàn khốc kéo dài 10 năm trong &quot;mê cung bóng tối&quot;. Desir Arman là một trong những pháp sư tài giỏi cuối cùng còn sót lại, nhưng ngay cả anh ấy cũng không phải là đối thủ của kẻ địch ghê gớm đang đe dọa sự tồn tại của nhân loại. Ngay thời khắc anh ấy nghĩ rằng tất cả đã chấm dứt, anh ấy được gửi ngược về thời gian, tới những ngày đầu học phép thuật tại Học viện Hebrion danh giá! Với cơ hội hiếm hoi thứ hai này, Desir quyết tâm cứu không chỉ bản thân mà còn cả những người bạn và đồng đội đã mất. Với kiến thức về tương lai, sự nỗ lực của anh ấy có thể tạo ra sự khác biệt hay tất cả họ đều cam chịu sống lại cùng một số phận khủng khiếp? Dựa trên một cuốn tiểu thuyết ăn khách.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"寺島拓篤","avatar":""},{"name":"鈴代紗弓","avatar":""},{"name":"藤原夏海","avatar":""},{"name":"瀬戸麻沙美","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324251);
