INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-chi-la-thich-em', 'Không Chỉ Là Thích Em', 'I May Love You', 'https://phimimg.com/upload/vod/20240826-1/4050162d5e10238c8d7552380f1f27a7.jpg', 'https://phimimg.com/upload/vod/20240826-1/2344ffbea93d9fc02678ed6608622db9.jpg', '<p>Kể về câu chuyện tình yêu giữa nhà sản xuất phim kiêu ngạo Đường Vực và biên kịch tinh nghịch mới vào nghề Đường Hinh. Khi yêu thầm đã lâu lại vô tình được chung sống ngọt ngào, họ sẽ phát triển tình cảm ra sao khi làm việc trong ngành viết tiểu thuyết và làm phim đây? Tổng giám đốc lạnh lùng, chưa từng yêu sẽ theo đuổi vợ lãng mạn ra sao, cô biên kịch nhỏ tinh nghịch sẽ theo đuổi ước mơ thế nào? Câu chuyện tình yêu giữa hai kỳ phùng địch thủ này sắp bắt đầu, một hành trình ngọt ngào từ hai phía chuẩn bị khởi hành.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"魏哲鳴","avatar":""},{"name":"黄日莹","avatar":""},{"name":"楊仕澤","avatar":""},{"name":"張欣雨","avatar":""},{"name":"範津瑋","avatar":""},{"name":"何雨虹","avatar":""},{"name":"Chen Bohao","avatar":""},{"name":"Li Jinrong","avatar":""},{"name":"Tong Zhang","avatar":""},{"name":"Lu Yunfeng","avatar":""},{"name":"Mengyuan Xu","avatar":""},{"name":"Peng Biyao","avatar":""},{"name":"Xiao Ranxin","avatar":""},{"name":"Pan Qi Yan","avatar":""},{"name":"Gao Wen-feng","avatar":""},{"name":"Wang Cheng","avatar":""},{"name":"Han Shumei","avatar":""},{"name":"祁憶","avatar":""},{"name":"Yue Jiayi","avatar":""},{"name":"Zhu Weiwei","avatar":""},{"name":"Leng Haiming","avatar":""},{"name":"严子贤","avatar":""},{"name":"Sun Letian","avatar":""},{"name":"Honglei Li","avatar":""},{"name":"Lin Ruixue","avatar":""},{"name":"Chen Ji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"3