INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('butareba-cau-chuyen-nguoi-dan-ong-bien-thanh-lon', 'Butareba Câu Chuyện Người Đàn Ông Biến Thành Lợn', 'Butareba The Story Of A Man Turned Into A Pig', 'https://phimimg.com/upload/vod/20240825-1/9f507d14b049b11ca03c34f307e85c92.jpg', 'https://phimimg.com/upload/vod/20240825-1/2198a6ddee74f1e88c6f2d3a1d2a01d0.jpg', '<p>Bộ phim xoay quanh cuộc hành trình đầy phiêu lưu của một gã Otaku tẻ nhạt, người đã bị biến thành một con heo sau khi ăn gan lợn sống. Được chăm sóc và bảo vệ bởi Jess - một thiếu nữ xinh đẹp có khả năng đọc thấu nội tâm của người khác, anh ta đã trải qua những khó khăn và thử thách không ngờ trong thế giới mới này. Cuộc hành trình này không chỉ mang lại cho chú heo kỳ thú mà còn tạo ra sự gắn kết và tình bạn đáng yêu giữa hai người hoàn toàn khác biệt. Với câu chuyện hài hước và cảm động, Làm Nóng Lá Gan Chú Heo sẽ mang lại cho khán giả những giây phút vui vẻ và suy ngẫm về ý nghĩa của tình bạn và sự chăm sóc trong cuộc sống.<span style="color: rgb(171, 183, 196); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, Helvetica, sans-serif; text-wrap: wrap; background-color: rgb(2, 8, 15);"></span></p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"松岡禎丞","avatar":""},{"name":"楠木ともり","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324251);
