INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thuc-cuong-nhan', 'Bạo Thực Cuồng Nhân', 'Berserk Of Gluttony', 'https://phimimg.com/upload/vod/20240825-1/ccb3eaaa3ff4703d16c7891e534d5e11.jpg', 'https://phimimg.com/upload/vod/20240825-1/a8f41c223e4243859b128eb48dec5f25.jpg', '<p>Fate Graphite là một trong những kẻ bỏ đi. Bị nguyền rủa bởi quyền năng &quot;Bạo thực”, anh luôn bị cơn đói hành hạ đến phát điên. Cho đến một ngày, sau khi hạ gục một tên trộm đang đột nhập vào lâu đài, Fate đã khám phá ra sức mạnh thực sự của mình. Anh có khả năng nuốt chửng linh hồn của những kẻ mà anh đánh bại, sau đó hấp thụ toàn bộ sức mạnh của bọn chúng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"逢坂良太","avatar":""},{"name":"関智一","avatar":""},{"name":"東城日沙子","avatar":""},{"name":"関根瞳","avatar":""},{"name":"松岡美里","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324251);
