INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liet-ai', 'Liệt Ái', 'Passionate Love', 'https://phimimg.com/upload/vod/20240819-1/79e6f62dfff04d0657fd30338f38a6ee.jpg', 'https://phimimg.com/upload/vod/20240819-1/8c8594c3824789ca5ae338bea0e00a36.jpg', '<p>Chứng kiến cảnh cả gia đình bị thảm sát, Đoàn Tuân Sơ hiểu lầm chị dâu Lâm Văn Ngữ là con gái của kẻ thù. Nhiều năm sau, Đoàn Tuân Sơ trở thành thiếu tướng quân phiệt ôm đầy căm hận trở về báo thù, giữa họ liên tiếp xảy ra mâu thuẫn, hiểu lầm do vướng vào ân oán gia tộc. Trong quá trình đấu đá lẫn nhau, hai người đã thầm yêu đối phương, cuối cùng hóa giải hiểu lầm và cùng nắm tay nhau hướng tới tương lai.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Xuanlin","avatar":""},{"name":"Gao Mingchen","avatar":""},{"name":"Ma Jiaying","avatar":""},{"name":"Zheng Chu Chen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
