INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-thuong-khung-ban-dac-biet-3-hen-uoc-ba-nam', 'Đấu Phá Thương Khung Bản Đặc Biệt 3 (Hẹn Ước Ba Năm)', 'Fights Break Sphere Special 3 (Three Years Of Pledge)', 'https://phimimg.com/upload/vod/20240205-1/54c844e083d47334391b9ee6445198ed.jpg', 'https://phimimg.com/upload/vod/20240205-1/5e02f51d1330a9df841ec1e4592714f6.jpg', '<p>Ba năm trước, Naran Yanran, thiếu gia của phái Yun Lan, vội vàng hủy bỏ hôn ước. Xiao Yan xấu hổ sau đó đã có một cuộc hẹn ba năm với Naran Yanran. Vì lần giao dịch này, Tiêu Viêm đã tu luyện không ngừng, từ ma thú sơn mạch đến sa mạc kinh nghiệm, từ luyện đan đến các loại hỏa diễm thiêu thân thống khổ, tất cả đều là để chứng minh cho câu nói của hắn: “Sông đông ba mươi năm, ba mươi năm đến phía tây sông, đừng coi thường những người trẻ tuổi đã mất tất cả. Bây giờ, những người trong gia đình Xiao nhất định sẽ đối mặt với thử thách và không bao giờ lùi bước. Con đường phát triển của Xiao Yan vẫn tiếp tục.……</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 4, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324251);
