INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-tich-tinh-yeu', 'Kỳ Tích Tình Yêu', 'The Infinite Love', 'https://phimimg.com/upload/vod/20230915-1/9371e06e4956fa9624cfebd7f395e011.jpg', 'https://phimimg.com/upload/vod/20230915-1/f2220b5f636a7cb6c703e5b3708f9c95.jpg', '<p>Davika và Pawee vốn là một cặp nhưng vì một tai nạn, cô tưởng anh đã chết. Davika cuối cùng cũng tiếp tục tiến tới với Chatchawin, người luôn ở bên cạnh giúp đỡ và chữa lành trái tim tan vỡ của cô. Nhưng cô chưa bao giờ ngừng yêu Pawee. Sáu năm sau, Pawee trở lại. Giữa một tình yêu cũ in sâu trong tim, và một tình yêu mới với những ước mơ về một tương lai tươi sáng... Liệu cô ấy sẽ chọn ai?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Puttichai Kasetsin","avatar":""},{"name":"Son Yuke Songpaisan","avatar":""},{"name":"Pooklook Fonthip Watcharatrakul","avatar":""},{"name":"Virithipa Pakdeeprasong","avatar":""},{"name":"Chinawut Indracusin","avatar":""},{"name":"Nutchapon Rattanamongkol","avatar":""},{"name":"Jeep Wasu Saengsingkaeo","avatar":""},{"name":"Tao Somchai Khemklad","avatar":""},{"name":"Sukol Sasijulaka","avatar":""},{"name":"Kumoun Maneerat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
