INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('101-lan-hon-nhan-cuong-ep', '101 Lần Hôn Nhân Cưỡng Ép', '101 Marriages', 'https://phimimg.com/upload/vod/20240816-1/78333f05dc5ab5c2ce0becd2e5750108.jpg', 'https://phimimg.com/upload/vod/20240816-1/423945b5a08cd32c572350665a636a5c.jpg', '<p>Lễ kỷ niệm ngày cưới của Thịnh Thế và Cố Lan San được tổ chức tại một khách sạn thuộc tập đoàn Thịnh Thế. Nhưng ẩn dưới lớp vỏ bọc tưởng chừng hạnh phúc ấy lại là trái tim đầy những vết thương của cả hai.Từ thời trung học, Thịnh Thế đã say đắm Cố Lan San, nhưng Cố Lan San khi lên đại học lại đem lòng yêu Hàn Thành Trì. Thịnh Thế vốn là người tự tin và kiêu ngạo nên không chấp nhận nổi sự thật này. Trong một buổi tiệc, anh đã cố tình để Cố Lan San uống phải ly rượu bị người khác bỏ thuốc, rồi cứ thế biến cô thành người phụ nữ của mình. Sau đó, anh thỏa thuận trả cho mẹ nuôi của cô một khoản tiền, buộc cô trở thành vợ của anh.Sau khi Cố Lan San biết được những thủ đoạn của Thịnh Thế, cô cảm thấy anh đã phản bội lại tình cảm giữa họ. Trong ngày cưới, em trai Cố Lan San định đưa cô bỏ trốn, nhưng không may cậu gặp tai nạn và trở thành người thực vật. Đối mặt với chi phí y tế khổng lồ để cứu chữa cho em trai, Cố Lan San đành phải cầu xin Thịnh Thế giúp đỡ. Thịnh Thế đã nhân cơ hội này, lấy việc cứu em trai làm điều kiện để ép Cố Lan San phải kết hôn với mình. Khi đó, anh tin rằng yêu là phải chiếm hữu.Thịnh Thế đã đạt được điều mình muốn, còn trái tim của Cố Lan San lại hóa tro tàn. Hai người chẳng hiểu gì về tình yêu cùng bước chân vào một cuộc hôn nhân, vốn định sẵn là sẽ bất hạnh. Một người muốn kéo gần khoảng cách, còn người kia lại muốn trốn chạy, họ đã khiến nhau tổn thương sâu sắc.Cuối cùng, Thịnh Thế cũng nhận ra rằng yêu không phải là chiếm hữu mà là buông tay để đối phương được tự do. Hôn nhân đi đến bờ vực tan vỡ, nhưng cả hai lại như được tái sinh, dần dần hiểu được cách yêu thương đúng nghĩa.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"金澤","avatar":""},{"name":"Shujun Chen","avatar":""},{"name":"Chuxuan Feng","avatar":""},{"name":"Dexi Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
