INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-dao-chich', 'Mỹ Nhân Đạo Chích', 'Miss Fortune', 'https://phimimg.com/upload/vod/20240819-1/21c51905f3dbf6cea42fba5f6c25b772.jpg', 'https://phimimg.com/upload/vod/20240819-1/8dd0c93ab5f8b83d16bbffb4e7f398fb.jpg', '<p>Cặp mẹ con “đạo chích” Ji Hye - Joo Yeong từng thực hiện vô số phi vụ thành công, nhưng mà là… công cốc. Để khép lại sự nghiệp không mấy vẻ vang này, Ji Hye lên kế hoạch trộm số vàng với giá trị lên đến 60 tỷ Won bằng cách lợi dụng trái tim mong manh mới biết yêu của anh chàng tài phiệt Wan Gyu. Nhưng phi vụ đặc biệt này không hề suôn sẻ khi cũng có những kẻ khác đang nhòm ngó số vàng kếch xù này.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"엄정화","avatar":""},{"name":"송새벽","avatar":""},{"name":"방민아","avatar":""},{"name":"김재화","avatar":""},{"name":"손병호","avatar":""},{"name":"박호산","avatar":""},{"name":"Kim Sung-sik","avatar":""},{"name":"박진우","avatar":""},{"name":"정영주","avatar":""},{"name":"정인기","avatar":""},{"name":"Jo Han-joon","avatar":""},{"name":"박성웅","avatar":""},{"name":"박수영","avatar":""},{"name":"Choi Moon-kyoung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324251);
