INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dung-duoc-yeu', 'Bỗng Dưng Được Yêu', 'Love My Scent', 'https://phimimg.com/upload/vod/20240819-1/556977b2ae772308b2fd9b864f7dff7a.jpg', 'https://phimimg.com/upload/vod/20240819-1/f4cb57ed614b090722177e0accd8ebd0.jpg', '<p>ChangSoo một người đàn ông có vẻ ngoài giản dị, cuộc sống luôn đối xử tệ với anh, anh chưa bao giờ thực sự trải nghiệm một mối tình lãng mạn viên mãn. Mọi thứ thay đổi khi anh xịt một loại nước hoa bí ẩn do một người lạ mang đến cho. Đột nhiên, các cô gái không thể cưỡng lại sự quyến rũ và xô đến anh. Vô tình gặp gỡ Ara - một người phụ nữ chưa bao giờ cho phép bản thân sống thật với cảm xúc của chính mình. Ara đã yêu ChangSoo mà không hề biết lý do. Mọi thứ hoàn hảo cho đến khi James, người yêu cũ của Ara xuất hiện và tiết lộ bí mật của ChangSoo.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"윤시윤","avatar":""},{"name":"설인아","avatar":""},{"name":"노상현","avatar":""},{"name":"문지인","avatar":""},{"name":"Lee Kyu-bok","avatar":""},{"name":"김영웅","avatar":""},{"name":"Heo Eun-jung","avatar":""},{"name":"임도화","avatar":""},{"name":"Yang Hye-Jin","avatar":""},{"name":"김수미","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324251);
