INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-cu-la-sep-cua-toi', 'Bạn Trai Cũ Là Sếp Của Tôi', 'Ex-boyfriend & Boss', 'https://phimimg.com/upload/vod/20240730-1/325c2fc2829ecdbf6a481f743af69e2d.jpg', 'https://phimimg.com/upload/vod/20240730-1/6155be4e0bfff877013295dfcde7c852.jpg', '<p>Cặp thanh mai trúc mã Liêu Vân Thừa và Đồng Niệm đã yêu nhau từ thời đại học nhưng lại chia tay vì hiểu lầm. Nhiều năm sau, họ gặp lại nhau nhưng thân phận và địa vị đã chênh lệch. Công ty của Đồng Niệm được công ty của Liêu Vân Thừa mua lại, nên họ buộc phải trở thành đồng nghiệp. Biết được Đồng Niệm vẫn độc thân sau bao nhiêu năm qua, Liêu Vân Thừa quyết định theo đuổi cô. Để tránh cho Đồng Niệm hiểu lầm, anh lập một tài khoản mạng và trở thành bạn qua mạng của cô. Khi Đồng Niệm gặp nguy hiểm, Liêu Vân Thừa luôn là người đầu tiên đứng ra bảo vệ cô. Hai người họ cùng nhau vượt qua những cạm bẫy chốn công sở, những sự việc như quấy rối tình dục nơi công sở,... Sau khi cùng hợp tác xử lý kẻ phản diện, Liêu Vân Thừa đã thành công theo đuổi Đồng Niệm, hai người cuối cùng cũng trở về bên nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Jiajia","avatar":""},{"name":"Jin Xiao","avatar":""},{"name":"Qu Meng Ting","avatar":""},{"name":"Ду Цзы Ян","avatar":""},{"name":"Ван Юй Линь","avatar":""},{"name":"Чжай И Цин","avatar":""},{"name":"Wang Wei","avatar":""},{"name":"Xin Ruyi","avatar":""},{"name":"Бай Би Цин","avatar":""},{"name":"Лу Сы Хэн","avatar":""},{"name":"Ван Юн Ган","avatar":""},{"name":"Ли Сюэ Цзяо","avatar":""},{"name":"蔡壮壮","avatar":""},{"name":"Чжэн Хай Ян","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
