INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('love-senior-tien-boi-ky-luat-yeu-em-duoc-khong', 'Love Senior: Tiền Bối Kỷ Luật Yêu Em Được Không?', 'Love Senior', 'https://phimimg.com/upload/vod/20240812-1/d86b27317431880c12657f3ad9b9034c.jpg', 'https://phimimg.com/upload/vod/20240812-1/412b0cf2bb349ebf4cee715d5e1bcc31.jpg', '<p>Love Senior: Tiền Bối Kỷ Luật Yêu Em Được Không? là câu chuyện về Manao, cô nữ sinh mới nhập học, vô tình bị cuốn vào lời nói của Gyoza, học sinh lớp trên nghịch ngợm, và phải đại diện cho khoa kỹ thuật để tham gia cuộc thi Freshy. Một câu chuyện hỗn loạn bắt đầu khi học sinh lớp trên, người mà ai cũng coi là xấu xa, lại đáng yêu đến mức trái tim của cô nữ sinh nhỏ bỏ một nhịp. Càng gần hơn, trái tim cô càng đập mạnh. Trong câu chuyện này, liệu có phải là cô nữ sinh nhỏ đã chinh phục được trái tim của đàn chị lớp trên? Hay là cô nàng học sinh lớp trên đã phải lòng cô bé nữ sinh mới và không thể rời xa?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Anunta Teavirat","avatar":""},{"name":"Kamollak Sangsubsin","avatar":""},{"name":"Thunyaphat Inyawilert","avatar":""},{"name":"Aphichaya Kamnoetsirikun","avatar":""},{"name":"Putticha Boonyamas","avatar":""},{"name":"Pin Danita Choktadaporn","avatar":""},{"name":"Bank Toranin Manosudprasit","avatar":""},{"name":"Tanadech Deeseesuk","avatar":""},{"name":"Jame Kasama Khanjanawattana","avatar":""},{"name":"Mawin Tanawin Duangnate","avatar":""},{"name":"Jenny Pataravadee Thi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324251);
