INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-xui-xeo', 'Năm Xui Xẻo', 'Happy Bad Year', 'https://phimimg.com/upload/vod/20240811-1/0976dc81fc706c2b6384ba75fe5d6769.jpg', 'https://phimimg.com/upload/vod/20240811-1/e0b4f2f993aa7e63b85cc2dd3502fe1f.jpg', '<p><span style="text-wrap: nowrap;">Số phận của ba chị em đã gắn kết với nhau từ thời xa xưa. Bộ phim kể về câu chuyện của Duean, chị cả và là một nhà môi giới bất động sản hàng đầu; Duean, chị thứ và là một nữ chính nổi tiếng và Dream, cô út, một sinh viên mới ra trường giao dịch tiền điện tử.</span></p><p><span style="text-wrap: nowrap;">Khi một lời nguyền cũ tái hiện, cả ba buộc phải chuyển về sống chung và tuân theo một bộ quy tắc để xua tan vận rủi và quay trở lại cuộc sống may mắn.</span></p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"ภัทรศยา เครือสุวรรณศิริ","avatar":""},{"name":"Sakuntala Teinpairoj","avatar":""},{"name":"Carissa Springett","avatar":""},{"name":"Anuwat Choocherdratana","avatar":""},{"name":"Jarupong Kluaymaingam","avatar":""},{"name":"Pongphan Petchbuntoon","avatar":""},{"name":"Gung Kunpong Kultanaruangnonth","avatar":""},{"name":"Kitkasem McFadden","avatar":""},{"name":"Lee Long Shi","avatar":""},{"name":"Janya Thanasawaangkoun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324251);
