INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-cua-than-ran', 'Cô Dâu Của Thần Rắn', 'The Bride Of Naga', 'null', 'https://phimimg.com/upload/vod/20230909-1/85c8253a0c17a0c894d2aec16a2d640b.jpg', '<p>Chuyện phim bắt đầu từ một ngôi làng nhỏ. Một đợt dịch bệnh không rõ nguyên do khiến trẻ em ở làng có vảy kỳ lạ giống loài rắn. Lúc này, tiến sĩ Benedict phải tìm hiểu hiện tượng này nhanh nhất có thể. Asia, một họa sĩ minh họa y tế được chọn để giúp anh trong việc này. Trên đường đi, cả hai gặp Phumkhaobin, một anh chàng sôi nổi nhưng bí ẩn, và là em trai của Pheka. Khi tìm hiểu sự việc, họ không ngờ rằng ngoài những bí ẩn họ còn bị cuốn vào truyền thuyết cổ xưa về một ngôi làng thờ rắn của người bản địa.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Porapat Srikajorn","avatar":""},{"name":"Ausadaporn Siriwattanakul","avatar":""},{"name":"Petch Boranin","avatar":""},{"name":"Num Sornram Theappitak","avatar":""},{"name":"Sarucha Petchroj","avatar":""},{"name":"Kulteera Yordchang","avatar":""},{"name":"Ploypailin Thangprapapo","avatar":""},{"name":"Phromphiriya Thongputtaruk","avatar":""},{"name":"Benjasiri Wattana","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324251);
