INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-canh-buom-dem', 'Những Cánh Bướm Đêm', 'Bugaw', 'https://phimimg.com/upload/vod/20240810-1/b85a762acb6b700c70dd2625cd65e5a1.jpg', 'https://phimimg.com/upload/vod/20240810-1/c6e90050c3f25ad766595491da294c67.jpg', '<p>Anh em Dolores và Isaac được biết đến là gái mại dâm của thị trấn. Nhưng khi một sĩ quan cảnh sát tham nhũng giam giữ họ, họ buộc phải biến một cô gái trẻ tên là Lydia, gái điếm mới nhất của thị trấn.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Alexa Ocampo","avatar":""},{"name":"Clifford Pusing","avatar":""},{"name":"Ataska Mercado","avatar":""},{"name":"Jay Manalo","avatar":""},{"name":"MJ Cayabyab","avatar":""},{"name":"Gwen Garci","avatar":""},{"name":"Shiena Yu","avatar":""},{"name":"Manu Respall","avatar":""},{"name":"Clarence Sesbreño","avatar":""},{"name":"Raul Morit","avatar":""},{"name":"Juharra Zhianne Asayo","avatar":""},{"name":"Vic Romano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
