INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tren-chuyen-co-that-phan-1', 'Dựa Trên Chuyện Có Thật (Phần 1)', 'Based On A True Story (Season 1)', 'https://phimimg.com/upload/vod/20240808-1/325c0ea8e308e73051439233f68419ab.jpg', 'https://phimimg.com/upload/vod/20240808-1/9c257f3928a9537fb6d1758f88955472.jpg', '<p>Cuộc đời của một nhà môi giới bất động sản, một thợ sửa ống nước và một cựu ngôi sao quần vợt bất ngờ va chạm, phơi bày nỗi ám ảnh của nước Mỹ về tội ác thực sự, giết người và bồn cầu đóng chậm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kaley Cuoco","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Tom Bateman","avatar":""},{"name":"Priscilla Quintana","avatar":""},{"name":"Liana Liberato","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
