INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jet-san-sang-tien-len-trai-khong-gian', 'Jet Sẵn Sàng Tiến Lên! Trại Không Gian', 'Ready Jet Go Space Camp The Movie', 'https://phimimg.com/upload/vod/20240805-1/9dc653c5750a928f79f580a424b407b4.jpg', 'https://phimimg.com/upload/vod/20240805-1/8a6d31decd38634885d7fc23d00ed4dc.jpg', '<p>Jet cùng những người bạn Sean, Sydney và Mindy tham dự trại ngoài không gian, nơi họ thử thách kỹ năng của mình. Trên đường đi, Vết đen mặt trời phát triển một phản ứng dị ứng khiến anh ta bị thu nhỏ lại. Đội Động cơ đẩy phải rời trại và tìm cách chữa trị, &quot;Dehshrinkulum&quot;, mà Mitchell không phát hiện ra họ đang làm gì.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anthony Bolognese","avatar":""},{"name":"Gordon Cormier","avatar":""},{"name":"Jaeda Lily Miller","avatar":""},{"name":"Ashleigh Ball","avatar":""},{"name":"Vienna Leacock","avatar":""},{"name":"Viva Lee","avatar":""},{"name":"Mark Oliver","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Gabriel Jacob-Cross","avatar":""},{"name":"Diana Tsoy","avatar":""},{"name":"Kyle Rideout","avatar":""},{"name":"Meg Roe","avatar":""},{"name":"Brenda Crichlow","avatar":""},{"name":"Ana Sani","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324252);
