INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luan-phien-doi-vo', 'Luân Phiên Đổi Vợ', 'Kahalili', 'https://phimimg.com/upload/vod/20240804-1/2aef3849c2878543aebed115d82cb85e.jpg', 'https://phimimg.com/upload/vod/20240804-1/a5cba13de58a55a3d8c8d34da8d57493.jpg', '<p>Luân Phiên – Kahalili (2023) một phụ nữ trẻ tìm được việc làm tại trang trại của một cặp vợ chồng giàu có nhưng được yêu cầu cung cấp dịch vụ tối ưu: làm người mẹ thay thế. Khi quá trình mang thai của cô ấy phát triển, sự gắn bó tình dục của người chồng ngày càng tăng.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Stephanie Raz","avatar":""},{"name":"Millen Gal","avatar":""},{"name":"Sid Lucero","avatar":""},{"name":"VR Relosa","avatar":""},{"name":"Mercedes Cabral","avatar":""},{"name":"Dan Villegas","avatar":""},{"name":"Elan Villafuerte","avatar":""},{"name":"Maria Denice Valeda","avatar":""},{"name":"Shelley Amoncio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
