INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-dien-nghia-tram-tien-phi-dao', 'Phong Thần Diễn Nghĩa: Trảm Tiên Phi Đao', 'The League of Gods: The Dagger of Kill Celestial Being', 'https://phimimg.com/upload/vod/20240804-1/d51236b4bbd1f46980fc05010d2b3419.jpg', 'https://phimimg.com/upload/vod/20240804-1/8f7820eecd2c16c1a7a5ed142b82de7a.jpg', '<p>Vào cuối thời nhà Thương, Võ Vương tấn công nhà Thương, sau nhiều trận chiến, nhà Thương bị tướng quân nhà Chu là Dương Tiễn đánh bại. Chu Vương vô cùng tức giận tìm mọi cách đối phó Dương Tiễn và ban thưởng thật lớn để tìm người có thể chiến thắng Dương Tiễn. Quân sư Thân Công Báo đến khuyên và đề xuất treo thưởng để chiêu mộ Mai Sơn Thất Quái, đặc biệt là thủ lĩnh Viên Hồng cũng thông thạo thất thập nhị (72) huyền công ngang với Dương Tiễn. Ngoài ra Viên Hồng còn biết nhiều loại ma thuật, có thể đi ngàn dặm một ngày, có sức mạnh to lớn, võ công cao cường, cầm gậy sắt, thích giết người và có tài điều binh khiển tướng. Chu Vương thấy ý kiến này rất hay và sai Thân Công Báo lên đường đến Mai Sơn ngay lập tức. Thân Công Báo không quan tâm đến tính cách tàn bạo của Chu Vương, ra sức vận động đồng môn và những nhân tài trong Tam Sơn Ngũ Nhạc đến giúp đỡ nhà Thương trong cuộc chiến với nhà Chu, cố gắng hết sức để duy trì sự thống trị của nhà Thương, được sự tin tưởng và trọng dụng của Chu Vương. Với sự xuất hiện của quân đội nhà Chu do Dương Tiễn và quân đội nhà Thương do Viên Hồng lãnh đạo, cuộc chiến bắt đầu.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Zhicheng","avatar":""},{"name":"Li Zhu","avatar":""},{"name":"Zhou Yupeng","avatar":""},{"name":"李子雄","avatar":""},{"name":"Zhao Fanghua","avatar":""},{"name":"Zheng Xutao","avatar":""},{"name":"Sun Mingzhen","avatar":""},{"name":"李雄 Xiong Li","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324252);
