INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-hiep', 'Cưỡng Hiếp', 'Nightbird', 'https://phimimg.com/upload/vod/20231102-1/8f55fda35dbed55f9587c522eac8c685.jpg', 'https://phimimg.com/upload/vod/20231102-1/964534790cb37cb7dfdadc29345b8961.jpg', '<p>Trong một bữa tiệc do bạn bè sắp xếp, Rachel gặp bốn người đàn ông. Đêm đầy rượu và ma túy trở nên hỗn loạn khi những người đàn ông cưỡng hiếp Rachel và bạn của cô. Rachel thề sẽ tìm cách trả thù bằng bất cứ giá nào.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Christine Bermas","avatar":""},{"name":"Sid Lucero","avatar":""},{"name":"Felix Roco","avatar":""},{"name":"Arron Villaflor","avatar":""},{"name":"Mark Anthony Fernandez","avatar":""},{"name":"Guji Lorenzana","avatar":""},{"name":"Alexa Ocampo","avatar":""},{"name":"Chloe Jenna","avatar":""},{"name":"Lander Vera-Perez","avatar":""},{"name":"Yayo Aguila","avatar":""},{"name":"Niño Aquino","avatar":""},{"name":"Dianne Moldez","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
