INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-ruc-ro-ben-toi', 'Mặt Trời Rực Rỡ Bên Tôi', 'Sunshine by My Side', 'https://phimimg.com/upload/vod/20240803-1/7b42c752705d4f052d661b0767c7aefe.jpg', 'https://phimimg.com/upload/vod/20230908-1/28fb2f7f8a5e18f1f3de0407f0075241.jpg', '<p>Bộ phim truyền hình &quot;Mặt trời rực rỡ ở bên tôi&quot; là một bộ phim tình cảm đô thị do Tống Hiểu Phi đạo diễn đạo, Lý Tiêu và Khương Vô Cập làm biên kịch, cùng sự tham gia của các diễn viên Tiêu Chiến, Bạch Bách Hà, Điền Vũ, Chu Châu.</p><p>Giản Băng (do Bạch Bách Hà thủ vai) là một đạo diễn quảng cáo nổi tiếng trong ngành, Thịnh Dương (do Tiêu Chiến thủ vai) là một người mới vào ngành. Hai người tình cờ gặp nhau tại một nhà hàng - một người vừa mới li hôn, một người đang yêu thầm, hai kẻ xa lạ cứ thế quấn quýt nhau, bắt đầu một chặng đường tình yêu, trưởng thành kỳ diệu và lãng mạn. Với sự ủng hộ của Thịnh Dương, Giản Băng đã lấy lại niềm tin vào cuộc sống và tình yêu. Nhờ sự hướng dẫn và động viên từ Giản Băng, Thịnh Dương từ một chàng trai trẻ ngây thơ và vụng về, khẳng định được bản thân và trưởng thành. Hai người chữa lành vết thương lòng cho đối phương, cùng trưởng thành và dần bồi đắp tình cảm. Tuy nhiên lại không thoát khỏi hiện thực, đối mặt với sự khác biệt về địa vị, kinh nghiệm,sự phản đối từ gia đình và tin đồn trong công việc, Giản Băng và Thịnh Dương đã phó thác tương lai cho thời gian định đoạt. Ba năm đã làm cho hai người trưởng thành và thay đổi. Họ đã dành nhiều &quot;lần đầu tiên&quot; của cuộc đời cho nhau, và chính sự tin tưởng và trải nghiệm đó đã khiến cho họ trở thành những người tốt hơn, sau nhiều lần lạc bước, họ lại trở về bên nhau.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'ongoing', 16, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Chiến","avatar":""},{"name":"Bai Bai He","avatar":""},{"name":"Tian Yu","avatar":""},{"name":"Chu Châu","avatar":""},{"name":"Mickey","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324252);
