INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boku-no-kokoro-no-yabai-yatsu-phan-1', 'Boku no Kokoro no Yabai Yatsu (Phần 1)', 'The Dangers in My Heart (Season 1)', 'https://phimimg.com/upload/vod/20240802-1/8742765030bf51dfdba155cc91315fcf.jpg', 'https://phimimg.com/upload/vod/20240802-1/a28a23024dd78276e8d7f400b937f9ef.jpg', '<p>Nhân vật chính là nam sinh Ichikawa Kyotaro, người luôn tự ti rằng bản thân chỉ đang ở ‘đáy xã hội’, thậm chí cậu còn nghĩ mình chính là ‘main’ trong một bộ phim kinh dị tâm lý nào đó. Cũng vì điều này mà Ichikawa Kyotaro dành cả ngày chỉ để tìm cách phá đi cuộc sống yên bình của bạn bè xung quanh. Cậu cũng đang theo đuổi Anna Yamada, một nữ sinh thần tượng của lớp. Câu hỏi đặt ra là, liệu Kyotaro có thực sự là một thiếu niên rắc rối hay cậu ta chỉ đang giả vờ...?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"堀江瞬","avatar":""},{"name":"羊宮妃那","avatar":""},{"name":"朝井彩加","avatar":""},{"name":"潘めぐみ","avatar":""},{"name":"種﨑敦美","avatar":""},{"name":"岡本信彦","avatar":""},{"name":"佐藤元","avatar":""},{"name":"福島潤","avatar":""},{"name":"豊崎愛生","avatar":""},{"name":"田村ゆかり","avatar":""},{"name":"島﨑信長","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324252);
