INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-vu-sat', 'Anh Vũ Sát', 'Tainted Love', 'https://phimimg.com/upload/vod/20240801-1/cfb7772e4f31211686d3a394bdb30928.jpg', 'https://phimimg.com/upload/vod/20240801-1/7b8192ec634f46a121cefeb3a6e020c2.jpg', '<p>Chu Nhiễm bị lừa 550.000 tệ khi hẹn hò trực tuyến. Lần theo manh mối, cô tìm đến một thị trấn nhỏ ven biển và vô tình gặp Lâm Trí Quang và Hứa Chiếu, những kẻ có mặt trong đường dây tội ác này và Chu Nhiễm không phải là nạn nhân duy nhất. Từ đây, một cuộc trả thù tỉ mỉ đã bắt đầu để đòi lại những tổn thương cô phải chịu.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"周冬雨","avatar":""},{"name":"Zhang Yu","avatar":""},{"name":"Zhang Youhao","avatar":""},{"name":"李梦","avatar":""},{"name":"Cai Xiangyu","avatar":""},{"name":"Jiang Qiming","avatar":""},{"name":"A Mao","avatar":""},{"name":"Dora Ng","avatar":""},{"name":"Li Binyuan","avatar":""},{"name":"Cai Yuanfei","avatar":""},{"name":"Guo Xincong","avatar":""},{"name":"Nan Kai","avatar":""},{"name":"Li Yunsheng","avatar":""},{"name":"Yang Bingbing","avatar":""},{"name":"Wang Feiyang","avatar":""},{"name":"Zheng Haoyang","avatar":""},{"name":"Tian Guansheng","avatar":""},{"name":"Wu Zhiqiang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
