INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-kitty', 'Cô Gái Kitty', 'Kitty K7', 'https://phimimg.com/upload/vod/20230923-1/de03633e471c2a9306d32808a9d343a0.jpg', 'https://phimimg.com/upload/vod/20230923-1/ec30d2de5976d7d759c80a55b42b498d.jpg', '<p>Sau khi bạn trai chia tay với cô, Hana, một họa sĩ đồ họa được trả lương thấp, tự đổi mới mình thành Kitty K-7, cô gái quay phim mới nhất của thế giới thay đổi.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Rose Van Ginkel","avatar":""},{"name":"Marco Gallo","avatar":""},{"name":"Miggy Jimenez","avatar":""},{"name":"Debbie Garcia","avatar":""},{"name":"Jiad Arroyo","avatar":""},{"name":"Adrian Lindayag","avatar":""},{"name":"Jean Kiley Manguera","avatar":""},{"name":"Kier Legaspi","avatar":""},{"name":"Dolly de Leon","avatar":""},{"name":"Karl Medina","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
