INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-gap-anh-o-kiep-thu-19', 'Hẹn Gặp Anh Ở Kiếp Thứ 19', 'See You in My 19th Life', 'https://phimimg.com/upload/vod/20240731-1/bb81d63d305ba8cc95e7480496d8a46b.jpg', 'https://phimimg.com/upload/vod/20230929-1/f67d02421bbdd2afabf2cc1c266ea34f.jpg', '<p>Ban Ji Eum có thể chuyển sinh không ngừng. Nhưng khi kiếp sống thứ 18 của cô chết yểu, cô quyết định dành kiếp sống tiếp theo để tìm mối tình thơ ấu giờ đã trưởng thành của mình.</p>', 'Hoàn tất (12/12)', 12, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Hye-sun","avatar":""},{"name":"Ahn Bo-hyun","avatar":""},{"name":"Ha Yoon-kyung","avatar":""},{"name":"Ahn Dong-gu","avatar":""},{"name":"Ryu Hae-jun","avatar":""},{"name":"Kim Si-a","avatar":""},{"name":"Choi Jin-ho","avatar":""},{"name":"Park So-yi","avatar":""},{"name":"Jung Hyeon-jun","avatar":""},{"name":"Gi So-you","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324252);
