INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc', 'Khế Ước', 'Guy Ritchie''s The Covenant', 'https://phimimg.com/upload/vod/20230922-1/0dfeff6d0bce81d267fb0e16f88dea88.jpg', 'https://phimimg.com/upload/vod/20230922-1/085d141f0a5371f46514527c9eaab5c1.jpg', '<p><span style="font-family: ">Trong nhiệm vụ cuối cùng ở Afghanistan, Trung sĩ John Kinley cùng đội với phiên dịch viên bản địa Ahmed. Khi đơn vị của họ bị phục kích, Kinley và Ahmed là 2 người sống sót duy nhất. Bị kẻ địch truy đuổi, Ahmed liều mạng đưa Kinley đang bị thương băng qua nhiều dặm đường địa hình khắc nghiệt đến nơi an toàn. Trở về Mỹ, Kinley biết rằng Ahmed và gia đình không dc cấp giấy thông hành tới Mỹ như đã hứa. Quyết tâm bảo vệ bạn mình và đền ơn cứu mạng, Kinley trở lại chiến trường để giúp Ahmed và gia đình trước khi lực lượng phiến quân phát hiện ra họ.</span></p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Dar Salim","avatar":""},{"name":"Sean Sagar","avatar":""},{"name":"Jason Wong","avatar":""},{"name":"Rhys Yates","avatar":""},{"name":"Christian Ochoa","avatar":""},{"name":"Bobby Schofield","avatar":""},{"name":"Emily Beecham","avatar":""},{"name":"Jonny Lee Miller","avatar":""},{"name":"Alexander Ludwig","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324252);
