INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vay-ham-khong-loi-thoat', 'Vây Hãm: Không Lối Thoát', 'The Roundup: No Way Out', 'https://phimimg.com/upload/vod/20230920-1/2ef0fb6288b04315c52f89f148015af5.jpg', 'https://phimimg.com/upload/vod/20230920-1/1a22f3d7f9425d55fea7b296836282ac.jpg', '<p><span style="font-family: ">Quái vật cơ bắp Seok-do (Ma Dong Seok) dẫn đầu đội hình sự truy lùng đường dây buôn chất cấm của thiếu gia Joo Seong Cheol. Cuộc truy đuổi càng thêm gay cấn khi cú đấm công lý &quot;chú Ma&quot; chạm trán thanh kiếm lừng lẫy chốn giang hồ Nhật Bản.</span></p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ma Dong-seok","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Munetaka Aoki","avatar":""},{"name":"Lee Beom-soo","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Lee Ji-hun","avatar":""},{"name":"Kim Do-geon","avatar":""},{"name":"Go Gyu-pil","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Jun Kunimura","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324252);
