INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-chu-cam', 'Tà Chú Cấm', 'Home for Rent', 'https://phimimg.com/upload/vod/20230920-1/95046341d6a073dda93154cb48b13b14.jpg', 'https://phimimg.com/upload/vod/20230920-1/7af5eee1d213d731ac8e01dacad7ac05.jpg', '<p><span style="font-family: ">Phim kể về cặp vợ chồng Ning, Kwin và cô con gái 7 tuổi với tên gọi Ing. Vì khó khăn về tài chính, hai vợ chồng quyết định cho thuê ngôi nhà đang ở và chuyển đến một căn hộ chung cư giá rẻ để sinh sống. Sau khi những người thuê nhà chuyển đến, Ning nhận thấy chồng bắt đầu có những hành vi bất thường. Anh ta trở nên bí mật và thường biến mất khỏi căn hộ và lúc 4 giờ sáng. Kwin thậm chí còn có một hình xăm kỳ lạ ở ngực tựa như ký hiệu đặc biệt của một hội tà giáo bí ẩn. Khi hành vi của chồng ngày càng trở nên đáng lo ngại, cũng là lúc Ning nhận ra cô con gái của mình đang gặp hiểm nguy. Bí mật nào đang được che giấu trong ngôi nhà cho thuê của họ?</span></p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Nittha Jirayungyurn","avatar":""},{"name":"Sukollawat Kanarot","avatar":""},{"name":"Penpak Sirikul","avatar":""},{"name":"Thanyaphat Mayuraleela","avatar":""},{"name":"Namfon Pakdee","avatar":""},{"name":"Suphithak Chatsuriyawong","avatar":""},{"name":"Natniphaporm Ingamornrat","avatar":""},{"name":"Pawarisa Surathin","avatar":""},{"name":"Narupornkamol Chaisang","avatar":""},{"name":"Piranpatch Teawsakul","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324252);
