INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-hi-sinh', 'Trò Chơi Hi Sinh', 'The Sacrifice Game', 'https://phimimg.com/upload/vod/20240524-1/145a24239c8e487a880e359e49ffdee9.jpg', 'https://phimimg.com/upload/vod/20240524-1/16c6c9c90b7e210ddde809d7ebf51726.jpg', '<p>The Sacrifice Game 2023 là một bộ phim kinh dị của Mỹ do Jenn Wexler đạo diễn và đồng viết kịch bản. Phim lấy bối cảnh tại Học viện Blackvale và xoay quanh nhóm kẻ giết người thực hiện các vụ giết người mạng tính chất nghi lễ liên quan đến việc triệu hồi quỷ dữ. Phim có sự tham gia của Mena Massoud, Olivia Scott Welch, và Gus Kenworthy, được công chiếu tại Liên hoan Phim Fantasia vào tháng 7 năm 2023</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Georgia Acken","avatar":""},{"name":"Mena Massoud","avatar":""},{"name":"Olivia Scott Welch","avatar":""},{"name":"Gus Kenworthy","avatar":""},{"name":"Chloë Levine","avatar":""},{"name":"Derek Johns","avatar":""},{"name":"Laurent Pitre","avatar":""},{"name":"Madison Baines","avatar":""},{"name":"Sophie McIntosh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
