INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-dong-y-cua-co-gai-phap', 'Sự Đồng Ý Của Cô Gái Pháp', 'Consent', 'https://phimimg.com/upload/vod/20240724-1/13bfa0bf904cd2c38b71317cb65915a3.jpg', 'https://phimimg.com/upload/vod/20240724-1/1798da69fb6b307d9557a4aabfa54574.jpg', '<p>Vanessa Springora mới 14 tuổi khi cô được Gabriel Matzneff chuẩn bị chu đáo, trở thành nàng thơ và nạn nhân của anh ta. Sau khi trải qua cuộc sống gia đình rắc rối, Vanessa đánh mất chính mình dưới sự kiểm soát hủy diệt của Matzneff.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FullHD', 'Bỉ', 0, '[{"name":"Kim Higelin","avatar":""},{"name":"Jean-Paul Rouve","avatar":""},{"name":"Laetitia Casta","avatar":""},{"name":"Élodie Bouchez","avatar":""},{"name":"Jean Chevalier","avatar":""},{"name":"Lolita Chammah","avatar":""},{"name":"David Clavel","avatar":""},{"name":"Agathe Dronne","avatar":""},{"name":"Christophe Grégoire","avatar":""},{"name":"Doby Broda","avatar":""},{"name":"Benjamin Gomez","avatar":""},{"name":"Irène Ismaïloff","avatar":""},{"name":"Anne Loiret","avatar":""},{"name":"Lila-Rose Gilberti","avatar":""},{"name":"Tanguy Mercier","avatar":""},{"name":"Selma Tamiatto","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
