INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-nguyet-nhu-tuyet', 'Phong Nguyệt Như Tuyết', 'The Snow Moon', 'https://phimimg.com/upload/vod/20240718-1/6a1fb1bf46109660e8aed53ce78b4e1a.jpg', 'https://phimimg.com/upload/vod/20240718-1/0b5c424c80d93afe512019183767f911.jpg', '<p>Để hóa giải vòng lặp lời nguyền luân hồi rồi lại chết thảm cho người thương Tô Tiểu Hoàn, Hồ yêu Bá Cừu đã một mình chịu đựng nỗi cô độc ngàn năm, chín kiếp yêu trong đọa đày. Kiếp này, cả nhà Tô Tiểu Hoàn đều chết thảm dưới tay Bá Cừu. Tô Tiểu Hoàn lưu lạc đầu đường xó chợ từ khi còn nhỏ, nếm trải hết thói đời bạc bẽo, sống lay lắt gian nan nhờ tính cách trơ lì không để ý sĩ diện. Về sau, cô bị Thái tử phế truất của tiền triều là Hiên Viên Thanh Xuyên lợi dụng, đưa vào hoàng cung, gài đến bên cạnh Hồ yêu vang danh tàn bạo khát máu, chờ cơ hội báo thù. Không ngờ định mệnh lại khiến cô phải lòng Hồ yêu lúc nào không hay. Kiếp này, để phá vỡ gông xiềng của số phận, Bá Cừu lựa chọn không nhận lại người mình yêu, quyết hy sinh bản thân, dùng tình yêu chân thành nhất cảm hóa đất trời, cuối cùng đã hóa giải được lời nguyền của Tô Tiểu Hoàn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FullHD', 'Trung Quốc', 0, '[{"name":"Li Jiaqi","avatar":""},{"name":"Zuo Ye","avatar":""},{"name":"Xiang Xin","avatar":""},{"name":"王庭旭","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
