INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-giet-nguoi', 'Kẻ Giết Người', 'The Killer', 'https://phimimg.com/upload/vod/20231022-1/03d22f810bb34f35fba067858291c419.jpg', 'https://phimimg.com/upload/vod/20231022-1/ef3dd5372c6f78a6fe74ade73b74ef1d.jpg', '<p>Sau một vụ suýt xảy ra định mệnh, một sát thủ chiến đấu với chủ và chính mình trong một cuộc truy lùng quốc tế mà anh ta khẳng định không phải chuyện cá nhân.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Fassbender","avatar":""},{"name":"Arliss Howard","avatar":""},{"name":"Charles Parnell","avatar":""},{"name":"Gabriel Polanco","avatar":""},{"name":"Kerry O''Malley","avatar":""},{"name":"Emiliano Pernia","avatar":""},{"name":"Sala Baker","avatar":""},{"name":"Sophie Charlotte","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Monique Ganderton","avatar":""},{"name":"Kellan Rhude","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
