INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-cau-song-the-nao', 'Các Cậu Sống Thế Nào?', 'The Boy and the Heron', 'https://phimimg.com/upload/vod/20231019-1/617c2264d83b0f9f2370caae2ee8227b.jpg', 'https://phimimg.com/upload/vod/20231019-1/bb165fd40f366034a64b94481b252d03.jpg', '<p>Trong khi Chiến tranh thế giới thứ hai nổ ra, cậu thiếu niên Mahito, bị ám ảnh bởi cái chết bi thảm của mẹ mình, đã được chuyển từ Tokyo đến ngôi nhà nông thôn thanh bình của người mẹ kế mới của cậu là Tsuko, một người phụ nữ có nét giống mẹ cậu bé đến kinh ngạc. Khi anh cố gắng điều chỉnh, thế giới mới kỳ lạ này càng trở nên xa lạ hơn sau sự xuất hiện của một con diệc xám dai dẳng, kẻ khiến Mahito bối rối và mê mẩn, gọi anh là &quot;kẻ được chờ đợi từ lâu&quot;.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Soma Santoki","avatar":""},{"name":"Masaki Suda","avatar":""},{"name":"Ko Shibasaki","avatar":""},{"name":"Aimyon","avatar":""},{"name":"Yoshino Kimura","avatar":""},{"name":"Takuya Kimura","avatar":""},{"name":"Keiko Takeshita","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Sawako Agawa","avatar":""},{"name":"Karen Takizawa","avatar":""},{"name":"Shinobu Otake","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Kaoru Kobayashi","avatar":""},{"name":"Shōhei Hino","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
