INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-cua-x', 'Lưỡi Cưa X', 'Saw X', 'https://phimimg.com/upload/vod/20231018-1/71ffce9f00dd95f14cd619dad9320f5c.jpg', 'https://phimimg.com/upload/vod/20231018-1/b3ba60218a09db7d77a1c0ea6c95f21f.jpg', '<p>Giữa các sự kiện của &quot;Saw&quot; và &quot;Saw II&quot;, John Kramer ốm yếu và tuyệt vọng tới Mexico để thực hiện một thủ tục y tế mang tính thử nghiệm và đầy rủi ro với hy vọng có được phương pháp chữa trị thần kỳ cho căn bệnh ung thư của mình, chỉ để phát hiện ra toàn bộ hoạt động này là một trò lừa đảo để lừa gạt. dễ bị tổn thương nhất. Được trang bị với một mục đích mới, kẻ giết người hàng loạt khét tiếng quay trở lại công việc của mình, lật ngược tình thế với những kẻ lừa đảo theo cách nội tạng đặc trưng của hắn thông qua những cái bẫy quỷ quyệt, loạn trí và khéo léo.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tobin Bell","avatar":""},{"name":"Shawnee Smith","avatar":""},{"name":"Synnøve Macody Lund","avatar":""},{"name":"Renata Vaca","avatar":""},{"name":"Paulette Hernández","avatar":""},{"name":"Octavio Hinojosa Martínez","avatar":""},{"name":"Steven Brand","avatar":""},{"name":"Michael Beach","avatar":""},{"name":"Joshua Okamoto","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Jorge Briseño","avatar":""},{"name":"David Alfano","avatar":""},{"name":"Donagh Gordon","avatar":""},{"name":"Baltimore Beltrán","avatar":""},{"name":"Isan Beomhyun Lee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
