INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ky-nguyen-cua-taylor-swift', 'Những Kỹ Nguyên Của Taylor Swift', 'Taylor Swift: The Eras Tour', 'https://phimimg.com/upload/vod/20231016-1/fe83b83b7d797e75f9bddb93084f548b.jpg', 'https://phimimg.com/upload/vod/20231016-1/0d59a5ea1d8e178a1069046f172cd143.jpg', '<p>Hiện tượng văn hóa tiếp tục diễn ra trên màn ảnh rộng! Đắm chìm trong trải nghiệm xem phim hòa nhạc chỉ có một lần trong đời này với góc nhìn ngoạn mục, đậm chất điện ảnh về chuyến tham quan làm nên lịch sử.</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taylor Swift","avatar":""},{"name":"Amos Heller","avatar":""},{"name":"Paul Sidoti","avatar":""},{"name":"Matt Billingslea","avatar":""},{"name":"Mike Meadows","avatar":""},{"name":"Karina DePiano","avatar":""},{"name":"Kamilah Marshall","avatar":""},{"name":"Melanie Nyema","avatar":""},{"name":"Eliotte Woodford","avatar":""},{"name":"Jeslyn Gorman","avatar":""},{"name":"Natalie Reid","avatar":""},{"name":"Natalie Peterson","avatar":""},{"name":"Tori Evans","avatar":""},{"name":"Tamiya Lewis","avatar":""},{"name":"Whyley Yoshimura","avatar":""},{"name":"Raphael Thomas","avatar":""},{"name":"Taylor Ba","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324252);
