INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-bao', 'Thợ Săn Bão', 'Supercell', 'https://phimimg.com/upload/vod/20230922-1/33acb97f72a4e68a47cd37ef4a366cce.jpg', 'https://phimimg.com/upload/vod/20230922-1/4b624d71f62382f0a4053872a549012c.jpg', '<p>Cậu thiếu niên tốt bụng William luôn sống với hy vọng nối bước người cha quá cố và trở thành người săn bão. Di sản của cha anh giờ đây đã trở thành một doanh nghiệp kinh doanh du lịch đang theo đuổi cơn bão, được quản lý bởi Zane Rogers tham lam và liều lĩnh, người hiện đang sử dụng William làm điểm thu hút chính để dẫn dắt một nhóm các nhà thám hiểm không nghi ngờ tiến sâu vào mắt siêu xe nguy hiểm nhất từ trước đến nay đã xem.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Skeet Ulrich","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"Daniel Diemer","avatar":""},{"name":"Jordan Kristine Seamón","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Richard Gunn","avatar":""},{"name":"Praya Lundberg","avatar":""},{"name":"Johnny Wactor","avatar":""},{"name":"Anjul Nigam","avatar":""},{"name":"Gabriel Clark","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324252);
