INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tottochan-co-be-ben-cua-so', 'Totto-Chan: Cô Bé Bên Cửa Sổ', 'Totto-chan: The Little Girl at the Window', 'https://phimimg.com/upload/vod/20240627-1/cf234cfb67db0ebc549b6afd8e63c438.jpg', 'https://phimimg.com/upload/vod/20240627-1/58c6366744b3e335fee5e525da6018de.jpg', '<p>Sau khi không phù hợp với trường tiểu học ban đầu, Totto Chan đi học tại Tomoe Gakuen. Tại đây, cô gặp những học sinh đặc biệt và học được những điều mới mẻ, ngay cả khi Nhật Bản rơi vào chiến tranh.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Liliana Ohno","avatar":""},{"name":"Koji Yakusho","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Anne Watanabe","avatar":""},{"name":"Karen Takizawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324252);
