INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-va-chim-diec', 'Thiếu Niên Và Chim Diệc', 'The Boy and the Heron', 'https://phimimg.com/upload/vod/20240625-1/b39f92dc9895f89d4a9e085920e38255.jpg', 'https://phimimg.com/upload/vod/20240625-1/da7dceada71c21e7e3a4f8131217252b.jpg', '<p>Đến từ Studio Ghibli và đạo diễn Miyazaki Hayao, bộ phim là câu chuyện về hành trình kỳ diệu của cậu thiếu niên Mahito trong một thế giới hoàn toàn mới lạ. Trải qua nỗi đau mất mẹ cùng mối quan hệ chẳng mấy vui vẻ với gia đình cũng như bạn học, Mahito dần cô lập bản thân... cho đến khi cậu gặp một chú chim diệc biết nói kỳ lạ. Mahito cùng chim diệc bước vào một tòa tháp bí ẩn, nơi một thế giới thần kỳ mở ra, đưa cậu gặp gỡ những người mình yêu thương... trong một nhân dạng hoàn toàn khác.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Soma Santoki","avatar":""},{"name":"菅田将暉","avatar":""},{"name":"Ko Shibasaki","avatar":""},{"name":"Aimyon","avatar":""},{"name":"Yoshino Kimura","avatar":""},{"name":"木村拓哉","avatar":""},{"name":"Keiko Takeshita","avatar":""},{"name":"風吹ジュン","avatar":""},{"name":"Sawako Agawa","avatar":""},{"name":"Karen Takizawa","avatar":""},{"name":"Shinobu Otake","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Kaoru Kobayashi","avatar":""},{"name":"Shōhei Hino","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324252);
