INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-na-cuoc-tron-chay-cua-carlos-ghosn', 'Truy Nã: Cuộc Trốn Chạy Của Carlos Ghosn', 'Wanted: The Escape of Carlos Ghosn', 'https://phimimg.com/upload/vod/20230915-1/b53ed45c16da3b19eee6d17b5bda8406.jpg', 'https://phimimg.com/upload/vod/20230915-1/7f610ad4540258c6c2a4f7fd020eb098.jpg', '<p>Câu chuyện hấp dẫn về Carlos Ghosn, CEO chuyển sang chạy trốn, bao gồm cả quyền lực của ông, vụ bắt giữ gây sốc và chuyến trốn chạy được tính toán khiến cả thế giới choáng váng.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Carlos Ghosn","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324252);
