INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truy-na-cuoc-tron-chay-cua-carlos-ghosn', 'Truy Nã: Cuộc Trốn Chạy Của Carlos Ghosn', 'Wanted: The Escape of Carlos Ghosn', 'truy nã: cuộc trốn chạy của carlos ghosn wanted: the escape of carlos ghosn carlos ghosn ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiec-tai-gia', 'Tiệc Tại Gia', 'House Party', 'https://phimimg.com/upload/vod/20240625-1/73891b15274a121f7b27c591661e3b03.jpg', 'https://phimimg.com/upload/vod/20240625-1/d07937674905eef1e989c25a61696a8d.jpg', '<p>Những người quảng bá câu lạc bộ đầy tham vọng và những người bạn tốt nhất Damon (Tosin Cole) và Kevin (Jacob Latimore) hầu như không giữ được mọi thứ với nhau. Hết tiền, hết vận may và sắp mất mái nhà - và mới bị sa thải khỏi công việc lau dọn nhà cửa tầm thường - cặp đôi cần một khoản tiền lớn để giải quyết vấn đề của họ. Trong một cái quái gì vậy? di chuyển, họ quyết định tổ chức bữa tiệc của năm tại một biệt thự độc quyền, nơi họ làm công việc dọn dẹp cuối cùng, nơi tình cờ thuộc về không ai khác ngoài LeBron James. Không cho phép? Không vấn đề gì. Điều gì có thể đi sai? Còn về một DJ du hành thời gian, an ninh không đáng tin cậy, một danh sách khách mời bỏ trốn, một chiếc Lamborghini mượn, những người quảng cáo đối thủ tức giận, một chiếc nhẫn vô địch bị đánh cắp, thiệt hại tài sản leo thang, một con gấu túi tức giận..? Nhưng cũng, một chuyến đi kỳ quặc được xếp chồng lên nhau với những vai khách mời kép và những bản nhạc hồi tưởng vượt thời gian, bộ phim hài được xếp hạng R và hai người bạn đáng để cổ vũ... bạn phải xem mới tin được. Xét cho cùng, một đêm như thế này không đến hơn một lần.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jacob Latimore","avatar":""},{"name":"Tosin Cole","avatar":""},{"name":"Karen Obilom","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324252);
