INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-goi-toi-la-than-bai', 'Đừng gọi tôi là "Thần Bài"', 'One More Chance', 'https://phimimg.com/upload/vod/20240624-1/62f68bd2614caab49edce1b1fd4b16af.jpg', 'https://phimimg.com/upload/vod/20240624-1/a624e911140fa94d6fb144cc1caabf98.jpg', '<p>One More Chance, trước đây có tên Be Water, My Friend, là một bộ phim chính kịch hài hước của Hồng Kông năm 2023 do Anthony Pun đạo diễn và Châu Nhuận Phát đóng vai chính trong vai một tay cờ bạc bệnh hoạn đang tìm cách giao tiếp và kết nối với cậu con trai mắc chứng tự kỷ của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Will Or","avatar":""},{"name":"Anita Yuen","avatar":""},{"name":"Alex Fong","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Andy On","avatar":""},{"name":"Michael Ning","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""},{"name":"Calvin Choi Yat-Chi","avatar":""},{"name":"Amy Lo","avatar":""},{"name":"Ivana Wong","avatar":""},{"name":"Pauline Yeung Yung-Lin","avatar":""},{"name":"Henry Fong","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
