INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-gia-toc', 'Lời Nguyền Gia Tộc', 'Mallari', 'https://phimimg.com/upload/vod/20240624-1/012304d19aee191988130ef0fa40ad69.jpg', 'https://phimimg.com/upload/vod/20240624-1/4be3cd76bd546be08cd4e41e968a4294.jpg', '<p>Một bác sĩ lùng sục quá khứ huyền bí của gia đình mình để tìm cách ngăn chặn cái chết của vị hôn thê, nhưng rồi tìm ra những bí mật liên quan đến hàng loạt án mạng ở thế kỷ 19.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Piolo Pascual","avatar":""},{"name":"Gloria Diaz","avatar":""},{"name":"Janella Salvador","avatar":""},{"name":"JC Santos","avatar":""},{"name":"Elisse Joson","avatar":""},{"name":"Vangie Labalan","avatar":""},{"name":"Bart Guingona","avatar":""},{"name":"Ge Villamil","avatar":""},{"name":"Raffy Tejada","avatar":""},{"name":"Chrome Cosio","avatar":""},{"name":"Lao Rodriguez","avatar":""},{"name":"Tommy Alejandrino","avatar":""},{"name":"Ron Angeles","avatar":""},{"name":"Audrey Alquiroz","avatar":""},{"name":"Angie Castrence","avatar":""},{"name":"James Allen Fajardo","avatar":""},{"name":"Angellie N","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324252);
