INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-carpathian-grandpa', 'My Carpathian Grandpa', 'My Carpathian Grandpa', 'https://phimimg.com/upload/vod/20240619-1/e2024ebce2bb7e854033590ad5299688.jpg', 'https://phimimg.com/upload/vod/20240619-1/6838d7b245134dd64dd1700507b6c258.jpg', '<p>Michele trẻ người Ý, người gốc Ukraine, đến một ngôi làng Carpathian bị bỏ hoang để xua tan bụi bặm của mẹ mình. Tại đây anh gặp ông nội Michael. Cuộc gặp gỡ bất ngờ này đã thay đổi cuộc đời họ mãi mãi.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Богдан Бенюк","avatar":""},{"name":"Simone Costa","avatar":""},{"name":"Iryna Beniuk","avatar":""},{"name":"Susanna Gozzetti","avatar":""},{"name":"Mauro Cipriani","avatar":""},{"name":"Sissi Martina Palladini Farruggia","avatar":""},{"name":"Lorenzo Giordano","avatar":""},{"name":"Olexa Gorodenko","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
