INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoa-trong', 'Khóa trong', 'Locked In', 'https://phimimg.com/upload/vod/20240618-1/2cf43f57bbfc9fb8aac0234edf8ff7de.jpg', 'https://phimimg.com/upload/vod/20240618-1/e93cdd09f64f08749334a433ed436a13.jpg', '<p>Cố gắng giải mã bí mật về những chấn thương của một bệnh nhân hôn mê, nữ y tá tốt bụng phát hiện ra sự ganh đua gay gắt, ngoại tình, phản bội và án mạng liên quan đến họ.</p>', 'Full', 1, 'single', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Famke Janssen","avatar":""},{"name":"Rose Williams","avatar":""},{"name":"Alex Hassell","avatar":""},{"name":"Finn Cole","avatar":""},{"name":"Anna Friel","avatar":""},{"name":"Georgia Thorne","avatar":""},{"name":"Toby Ryan","avatar":""},{"name":"Karl Collins","avatar":""},{"name":"Lesley Molony","avatar":""},{"name":"Chris Hallaways","avatar":""},{"name":"Rachel Holifield","avatar":""},{"name":"Cameron Robertson","avatar":""},{"name":"Hope Delaney","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
