INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-xep-hinh-kinh-dien', 'Trò Chơi Xếp Hình Kinh Điển', 'Tetris', 'https://phimimg.com/upload/vod/20230922-1/482adedc37518915d8733000c5861c29.jpg', 'https://phimimg.com/upload/vod/20230922-1/012151012deb2a3a61f2e7fbf87bacfd.jpg', '<p><span style="font-family: ">Câu chuyện về cách một trong những trò chơi điện tử phổ biến nhất thế giới đến được với người chơi trên toàn cầu. Doanh nhân Henk Rogers và nhà phát minh Tetris Alexey Pajitnov hợp lực tại Liên Xô, mạo hiểm tất cả để đưa Tetris đến với đại chúng.</span></p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Nikita Efremov","avatar":""},{"name":"Sofia Lebedeva","avatar":""},{"name":"Anthony Boyle","avatar":""},{"name":"Ben Miles","avatar":""},{"name":"Ken Yamamura","avatar":""},{"name":"Igor Grabuzov","avatar":""},{"name":"Oleg Shtefanko","avatar":""},{"name":"Ayane Nagabuchi","avatar":""},{"name":"Rick Yune","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
