INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-long-bat-bo-kieu-phong-truyen', 'Thiên Long Bát Bộ: Kiều Phong Truyện', 'Sakra', 'https://phimimg.com/upload/vod/20230922-1/2244a5a496e3e9d90f7130ac9237c357.jpg', 'https://phimimg.com/upload/vod/20230922-1/25de208679595548436ea2a090bf6865.jpg', '<p>Câu chuyện trong Thiên Long Bát Bộ: Kiều Phong Truyện sẽ diễn ra ở Tụ Hiền Trang, nơi Kiều Phong (Tiêu Phong - Chân Tử Đan đóng) bị quần hùng tìm ra chân tướng là người Khiết Đan, nghi là gián điệp và muốn sát hại chàng. Kiều Phong cũng rơi vào bẫy của Mộ Dung Phục, bị nghi đã giết chết phó bang chủ Cái Bang Mã Đại Nguyên. Mộ Dung Phục cũng sắp đặt khiến người yêu của Kiều Phong là A Châu (Trần Ngọc Kỳ) bị giết. Trước khi đánh, Kiều Phong lấy rượu ra uống xem như tuyệt giao với các bằng hữu trước đây. Trận chiến diễn ra, một mình Kiều Phong chống quần hùng, Hàng Long Thập Bát Chưởng lại một lần nữa uy trấn thiên hạ, đánh bại tất cả. Đây là sự kiện quy tụ nhiều cao thủ võ lâm trong Thiên Long Bát Bộ, cũng tạo bối cảnh tốt để Kiều Phong của Chân Tử Đan thỏa sức thể hiện khả năng võ thuật.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Yukee Chen","avatar":""},{"name":"Liu Yase","avatar":""},{"name":"Kara Hui Ying-Hung","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Grace Wong","avatar":""},{"name":"Do Yuming","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Tsui Siu-Ming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
