INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-quang-khan-do', 'Thám Tử Quàng Khăn Đỏ', 'Once Upon a Crime', 'https://phimimg.com/upload/vod/20230916-1/ca3c633d42ec7ef50f75a09b188ffcd6.jpg', 'https://phimimg.com/upload/vod/20230916-1/6bb9f25af11a43b5513670931c02c798.jpg', '<p><span style="font-family: ">Khi dự vũ hội hoàng gia cùng Lọ Lem, Cô bé quàng khăn đỏ vướng vào một bí ẩn. Liệu cô có thể phá giải vụ án trước nửa đêm?</span></p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kanna Hashimoto","avatar":""},{"name":"Yuko Araki","avatar":""},{"name":"Takanori Iwata","avatar":""},{"name":"Natsuna Watanabe","avatar":""},{"name":"Yumi Wakatsuki","avatar":""},{"name":"Mirei Kiritani","avatar":""},{"name":"Tsuyoshi Muro","avatar":""},{"name":"Masaki Kaji","avatar":""},{"name":"Tomoharu Hasegawa","avatar":""},{"name":"Atsuhiro Inukai","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324252);
