INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-quang-khan-do', 'Thám Tử Quàng Khăn Đỏ', 'Once Upon a Crime', 'thám tử quàng khăn đỏ once upon a crime kanna hashimoto yuko araki takanori iwata natsuna watanabe yumi wakatsuki mirei kiritani tsuyoshi muro masaki kaji tomoharu hasegawa atsuhiro inukai ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-gio-noi-len', 'Khi Gió Nổi Lên', 'Where The Wind Blows', 'https://phimimg.com/upload/vod/20240618-1/ac3f66709b2c3db822b7866856f5d005.jpg', 'https://phimimg.com/upload/vod/20240618-1/b1590c7cea3b32b907a9ee40278545a0.jpg', '<p>Vào những năm 70, Ủy ban Độc lập Chống Tham nhũng Hồng Kông (HKICAC) được thành lập. Nhiệm vụ truy lùng những thám tử biến chất đã mở ra một chương mới của Hong Kong thời thuộc địa. Lui Lok (Aaron Kwok) và Nam Kong (Lương Triều Vỹ), từng là hai sĩ quan cảnh sát chính nghĩa muốn thay đổi hiện trạng. Họ đã xây dựng một đế chế tham nhũng bằng cách kiểm soát tội phạm có tổ chức và cuối cùng nắm giữ vị trí Giám đốc Thám tử Trung Quốc. Tuy nhiên, tranh giành quyền lực luôn là nguyên nhân dẫn đến sự hỗn loạn giữa hội tam hoàng và cảnh sát. Vợ của Lui Lok, Tsai Zhen (Du Juan) là mục tiêu của bộ ba vì đã giúp chồng cô giành được vị trí của mình. Ngay cả những thám tử trung thành nhất Fat-Bee (Michael Chow) và Yim Hung (Patrick Tam), gần như quay lưng lại với Lui Lok. Một trang sử mới đã bắt đầu khi HKICAC phát lệnh truy nã Lui Lok và Nam Kong. Thời đại của họ đã chính thức kết thúc. Gió thổi đi đâu, Hồng Kông không còn như xưa nữa.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Aaron Kwok","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Michael Chow Man-Kin","avatar":""},{"name":"Du Juan","avatar":""},{"name":"Michael Hui","avatar":""},{"name":"Jessie Li","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Jeana Ho","avatar":""},{"name":"Michael Ning","avatar":""},{"name":"Lam Yiu-Sing","avatar":""},{"name":"Chui Tien-You","avatar":""},{"name":"Lawrence Ko Yu-Luen","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"謝君豪","avatar":""},{"name":"Deon Cheung","avatar":""},{"name":"Maggie Cheung Hoh-","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
