INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-boi-vo-cuc', 'Hồ Bơi Vô Cực', 'Infinity Pool', 'https://phimimg.com/upload/vod/20230911-1/afbf7e0df6b5b79531630e7516c9496e.jpg', 'https://phimimg.com/upload/vod/20230911-1/d209e38463d82320e580e13fe571a2df.jpg', '<p>James và Em Foster đang tận hưởng kỳ nghỉ trọn gói trên bãi biển ở hòn đảo La Tolqa thì một tai nạn chết người khiến James bị rơi vào vòng lao lý. Dẫu vậy, anh ta được trao cơ hội khi có thể sử dụng tiền để tạo ra một bản sao nhằm chịu tội thay cho mình. Và từ đây, những trò chơi quái đản bắt đầu diễn ra một cách không thể kiểm soát.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Alexander Skarsgård","avatar":""},{"name":"Mia Goth","avatar":""},{"name":"Cleopatra Coleman","avatar":""},{"name":"Jalil Lespert","avatar":""},{"name":"Amanda Brugel","avatar":""},{"name":"John Ralston","avatar":""},{"name":"Jeff Ricketts","avatar":""},{"name":"Caroline Boulton","avatar":""},{"name":"Thomas Kretschmann","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '[]', 1784690324252);
