INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-dem-kinh-hoang', 'Màn Đêm Kinh Hoàng', 'Night Has Come', 'https://phimimg.com/upload/vod/20240616-1/8434a4a4dda94e979f54f3c1486c226a.jpg', 'https://phimimg.com/upload/vod/20240616-1/5d6a0177c4eb41b2c7eddf43b788a37a.jpg', '<p>Màn Đêm Kinh Hoàng - Night Has Come (2023) kể về chuyến dã ngoại kinh hoàng của các học sinh thuộc trường trung học phổ thông Yoo Il, khi mà họ đã phát hiện rằng mình bị bắt buộc tham gia vào một trò ma sói ở ngoài đời thực. Sự nguy hiểm luôn rình rập bên cạnh họ khi từng người phải bỏ mạng một cách đầy bí ẩn sau mỗi buổi tối. Nếu sự lựa chọn được đưa ra sai lầm họ sẽ phải trả giá bằng sinh mệnh của bạn bè, hoặc chính bản thân.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jae-in","avatar":""},{"name":"Kim U-seok","avatar":""},{"name":"Choi Ye-bin","avatar":""},{"name":"Cha Woo-min","avatar":""},{"name":"Ahn Ji-ho","avatar":""},{"name":"Jeong So-ri","avatar":""},{"name":"Kang Seol","avatar":""},{"name":"Oh Jung-taek","avatar":""},{"name":"Song Byeong-geun","avatar":""},{"name":"Kim So-hee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324252);
