INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-kien-quan-nhu-co', 'Tái Kiến Quân Như Cố', 'Love''s Deception', 'https://phimimg.com/upload/vod/20240602-1/18aee98c5fcb5f6cb88ce24b8235abb9.jpg', 'https://phimimg.com/upload/vod/20240602-1/0e80b17c1ac83c4bbce4e5a7d35d8b39.jpg', '<p>Thực thần Phượng Lê Lê bị phạt xuống trần vượt tình kiếp. Để tìm được chân mệnh thiên tử giúp mình lịch kiếp, Phượng Lê Lê sửa tên thành Phong Lê Lê, vào phủ thành chủ thành Cửu Lê, đồng thời run rủi gả cho thành chủ Thẩm Ngọc Xuyên. Nào ngờ chân mệnh thiên tử lại là người khác, vì vậy Phong Lê Lê tìm mọi cách thoát khỏi phủ thành chủ. Nhưng một âm mưu chính trị đang lặng lẽ mở màn, để bảo vệ Phong Lê Lê, Thẩm Ngọc Xuyên cố tình xa lánh cô. Bấy giờ Phong Lê Lê mới muộn màng phát hiện ra mình đã thích Thẩm Ngọc Xuyên. Vào lúc cô đang băn khoăn lại bất ngờ phát hiện ra Thẩm Ngọc Xuyên thích mình chỉ là một cú lừa đã lập kế hoạch tỉ mỉ trước. Cô vì yêu mà hận, quyết định trả thù Thẩm Ngọc Xuyên. Cho đến khi thân phận của chân mệnh thiên tử bị vạch trần.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"黃俊捷","avatar":""},{"name":"Zhong Qi","avatar":""},{"name":"Cao Xiyue","avatar":""},{"name":"權沛倫","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324252);
