INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-vo-tieu-tien-cua-cong-tu-da-toc', 'Cô Vợ Tiểu Tiên Của Công Tử Dạ Tộc', 'Devil Falls in Love with Fairy', 'https://phimimg.com/upload/vod/20240530-1/326d4f78bcb0aabeb56430bad32990cf.jpg', 'https://phimimg.com/upload/vod/20240530-1/016adf6d5a93580e15a417af066885e9.jpg', '<p>Nhà phê phim tương tác Hà Ý Hoan bước vào thế giới thực tế ảo, vô tình trở thành thê tử của Thái Cổ Dạ Tộc Huyền Minh. Cô phải hóa giải năm yêu kiếp lớn để ngăn chặn Huyền Minh hắc hóa thành ma tôn hủy diệt thế gian, thì mới có thể trở về hiện thực. Hai người đồng hành cùng nhau, đồng sinh cộng tử, Ý Hoan phải lòng Huyền Minh ngoài lạnh trong nóng. Không ngờ có một tai họa lớn hơn đang lặng lẽ ập đến...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guan Yue","avatar":""},{"name":"屠屠","avatar":""},{"name":"Li Chenhui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324252);
