INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-penduko', 'Người Hùng Penduko', 'Penduko', 'https://phimimg.com/upload/vod/20240612-1/39920093fc5b3e2b526b5dd403496c24.jpg', 'https://phimimg.com/upload/vod/20240612-1/59b2fc514a791b3098c14fc8910bd84b.jpg', '<p>Hi vọng kiếm tiền từ năng lực huyền bí, nhà thần bí nọ gia nhập một xã hội mờ ám và phải đối diện với bóng tối của chính mình trong khi tìm chỗ đứng nơi thế giới ngầm.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Matteo Guidicelli","avatar":""},{"name":"Kylie Verzosa","avatar":""},{"name":"John Arcilla","avatar":""},{"name":"Phoebe Walker","avatar":""},{"name":"Arron Villaflor","avatar":""},{"name":"Albert Martinez","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324252);
