INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mien-dat-hua-2023', 'Miền Đất Hứa', 'The Promised Land', 'https://phimimg.com/upload/vod/20240609-1/cad2c6fd17c146115d59bd86c20f97cc.jpg', 'https://phimimg.com/upload/vod/20240609-1/fbc31c5c4f206c86f0f73b3081057f58.jpg', '<p>Ludvig Kahlen đến vùng đất khô cằn Jutland vào năm 1755 với một mục tiêu duy nhất: đi theo lời kêu gọi của nhà vua để canh tác đất đai và mong muốn đạt được sự giàu có cũng như danh dự cho bản thân. Nhưng Kahlen nhanh chóng gây thù chuốc oán. Chủ đất tàn nhẫn, Frederik De Schinkel, người cai trị duy nhất của khu vực, tin rằng nơi đó thuộc về ông ta chứ không phải nhà vua. Khi người làm công của hắn bỏ trốn cùng vợ là Ann Barbara và tìm nơi ẩn náu tại nhà của Kahlen, người chủ đất làm mọi cách để đuổi tất cả đi, đồng thời thực hiện một cuộc trả thù tàn nhẫn...</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Đan Mạch', 0, '[{"name":"Mads Mikkelsen","avatar":""},{"name":"Amanda Collin","avatar":""},{"name":"Simon Bennebjerg","avatar":""},{"name":"Kristine Kujath Thorp","avatar":""},{"name":"Gustav Lindh","avatar":""},{"name":"Jacob Ulrik Lohmann","avatar":""},{"name":"Morten Hee Andersen","avatar":""},{"name":"Magnus Krepper","avatar":""},{"name":"Søren Malling","avatar":""},{"name":"Morten Burian","avatar":""},{"name":"Thomas W. Gabrielsson","avatar":""},{"name":"Morten Buus","avatar":""},{"name":"Olaf Højgaard","avatar":""},{"name":"Melina Hagberg","avatar":""},{"name":"Felix Kramer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
