INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-kieu', 'Đoạt Kiêu', 'Beauty Killer', 'https://phimimg.com/upload/vod/20240530-1/3a917c2860fe1149518373f8d6cab773.jpg', 'https://phimimg.com/upload/vod/20240530-1/f919bc726b19708d04dc300e5d4929fc.jpg', '<p>Tại thành Nhạc Lăng nơi nữ giới được tôn kính hơn nam giới, một nhóm sát thủ đang ẩn náu trong một quán trọ chờ cơ hội trả thù. Không ngờ, quán trọ lại bị nữ thương gia Lục Hoài Song mua lại. Một nhóm sát thủ giỏi dùng rìu, móc câu lại bị ép luyện tập gảy đàn và ca hát. Thủ lĩnh của nhóm sát thủ, Nhạc Khởi Sơn, dưới sự dạy dỗ của Lục Hoài Song còn trở thành cầm sư hàng đầu, cũng hoàn toàn phải lòng bà chủ của mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Qing","avatar":""},{"name":"Samuel Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
