INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khon-thu', 'Khốn Thú', 'Death Stranding', 'https://phimimg.com/upload/vod/20240606-1/a94a41085329c709c777f30bfcb6d755.jpg', 'https://phimimg.com/upload/vod/20240606-1/8de67a3c5f7a1c458f17c3687e09d7ea.jpg', '<p>Trong hàng thập kỷ, Hồ Thành rơi vào tình trạng hỗn loạn do ngành công nghiệp giải trí ngầm tham nhũng và rửa tiền. Thế lực tội phạm do Tứ Gia và Cục trưởng Cục điều tra thương mại Tả Quân Triết cầm đầu đã bí mật kiểm soát tình hình, cố gắng tranh giành quyền quản lý. Để lập lại trật tự và quyết tâm xóa bỏ mạng lưới tội phạm nguy hiểm này, cảnh sát Giang Văn Phong đã phát động một cuộc đối đầu đầy kịch tính.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"鍾漢良","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Myolie Wu","avatar":""},{"name":"Zhaoyan Guozhang","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Lily Ji","avatar":""},{"name":"Keru Wang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
