INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('best-enemy', 'Best Enemy', '宿命之敌', 'https://phimimg.com/upload/vod/20240522-1/bf915d51f0085095c5e166674a808744.jpg', 'https://phimimg.com/upload/vod/20240522-1/cd5564d595b3250b25f58812aaa0137e.jpg', '<p>Trong cuộc chiến kháng chiến chống lại Nhật Bản, để chiến đấu chống lại Dịch vụ đặc biệt của Chính phủ Puppet số 76, đồng phục quân đội đã thiết lập một khóa đào tạo đặc biệt Xin. Chen Kehai và Fang Li, những người anh em, đã đến cứu đất nước với mục đích chiến đấu chống lại Nhật Bản. Tuy nhiên, việc mất một nhiệm vụ cho phép Chen và Fang cho nhau. Hai năm sau, Chen Kehai, người đã bí mật gia nhập Đảng Cộng sản, trở về Thượng Hải và lẻn vào số 76, và thấy rằng Fang Li đã đứng ở phía đối diện. Khi anh em đoàn tụ cũng là thời điểm lựa chọn đường xá. Trước Chen Kehai, người đã thay đổi tính cách của mình, Fang Li liên tục cố gắng và thậm chí ngần ngại xác định danh tính của Chen Kehai. Chen Kehai đã ở trong trại của kẻ thù, Tiger và Wolf tôn thờ. Nhưng anh thấy rằng danh tính của Fang Li dường như không đơn giản. Sương mù của chiến tranh dần dần phân tán, và tâm sự của các bạn cùng lớp trong quá khứ sẽ mở ra cuộc đối đầu cuối cùng cho niềm tin của nhau.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2023, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Zhiting","avatar":""},{"name":"王森","avatar":""},{"name":"Chen Yao","avatar":""},{"name":"Zhang Yue","avatar":""},{"name":"Zhao Bin","avatar":""},{"name":"Wang Haiping","avatar":""},{"name":"王策","avatar":""},{"name":"Jiang Xueming","avatar":""},{"name":"Meng Asai","avatar":""},{"name":"Geng Yeting","avatar":""},{"name":"Fan Yize","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324252);
