INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('you-and-me', 'You and Me', 'Ikaw At Ako', 'https://phimimg.com/upload/vod/20240603-1/893c2e9c3059ac3081769b59a0eac4cb.jpg', 'https://phimimg.com/upload/vod/20240603-1/0cbda75a45f0de65a17a2b42378b51e0.jpg', '<p>Một cặp vợ chồng xoay xở với vụ ly hôn đang chờ xử lý. Một cặp vợ chồng lớn tuổi vật lộn với khủng hoảng sức khỏe. Hai đứa trẻ khám phá tình yêu tuổi trẻ ở trại.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Paolo Contis","avatar":""},{"name":"Rhian Ramos","avatar":""},{"name":"Ronaldo Valdez","avatar":""},{"name":"Boots Anson-Roa","avatar":""},{"name":"James Ignacio","avatar":""},{"name":"Fatima Marie Mislang","avatar":""},{"name":"Madeleine Nicolas","avatar":""},{"name":"Phoebe Walker","avatar":""},{"name":"Andrew Gan","avatar":""},{"name":"Marnie Lapus","avatar":""},{"name":"Francis Mata","avatar":""},{"name":"Angelito Galang","avatar":""},{"name":"Cloud Ugayan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
