INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-tua-khoi-suong', 'Tình Tựa Khói Sương', 'Silver Haze', 'https://phimimg.com/upload/vod/20240603-1/674b99730ad4f90a4b9b608314ecd2d6.jpg', 'https://phimimg.com/upload/vod/20240603-1/5eaa31fbe390e59f2bffa43f722cfe35.jpg', '<p>Mười lăm năm sau khi cô bị bỏng toàn thân khi quán rượu nơi cô ngủ khi còn nhỏ bốc cháy, Franky (nay đã 23 tuổi) tìm cách trả thù vì vẫn chưa tìm ra câu trả lời cho số phận.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Hà Lan', 0, '[{"name":"Vicky Knight","avatar":""},{"name":"Esme Creed-Miles","avatar":""},{"name":"Charlotte Knight","avatar":""},{"name":"Archie Brigden","avatar":""},{"name":"Angela Bruce","avatar":""},{"name":"Brandon Bendell","avatar":""},{"name":"Alfie Deegan","avatar":""},{"name":"TerriAnn Cousins","avatar":""},{"name":"Jeanette Maskell","avatar":""},{"name":"Daniel Phelan","avatar":""},{"name":"Bonnie O''Brien","avatar":""},{"name":"Billy Knight","avatar":""},{"name":"Nicola Bland","avatar":""},{"name":"Carrie Bunyan","avatar":""},{"name":"Sandra Kwiek","avatar":""},{"name":"Sarah-Jane Dent","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324252);
