INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-the-bi-bo-roi', 'Thi Thể Bị Bỏ Rơi', 'The Abandoned', 'https://phimimg.com/upload/vod/20240603-1/ebe45c8f6eb3243b260f5702df587b62.jpg', 'https://phimimg.com/upload/vod/20240603-1/4bb26c1f04ee99b2efcb8259e1e4cb6a.jpg', '<p>Một xác chết bí ẩn được tìm thấy trên một dòng sông. Trong lòng đầy đau khổ, viên sĩ quan cảnh sát nọ điều tra loạt án mạng ghê rợn khi nguy hiểm nhanh chóng tìm đến.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"張鈞甯","avatar":""},{"name":"Ethan Juan","avatar":""},{"name":"Yu An-Shun","avatar":""},{"name":"Sajee Apiwong","avatar":""},{"name":"Chloe Xiang","avatar":""},{"name":"Chen Wei-Min","avatar":""},{"name":"Simon Hsueh","avatar":""},{"name":"Teng-Hui Huang","avatar":""},{"name":"Lu Hsueh-Feng","avatar":""},{"name":"傅孟柏","avatar":""},{"name":"Lan Wei-Hua","avatar":""},{"name":"Winnie Chang","avatar":""},{"name":"宋少卿","avatar":""},{"name":"黃迪揚","avatar":""},{"name":"Yin Chao-Te","avatar":""},{"name":"Ming-shiou Tsai","avatar":""},{"name":"Kira Tsao","avatar":""},{"name":"Hung-Hsiu Wu","avatar":""},{"name":"Eddie Chen","avatar":""},{"name":"Ark Zheng","avatar":""},{"name":"Guo-Chiang Lee","avatar":""},{"name":"Duon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
