INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-nhan-van-va-nguoi-muon-tu-sat', 'Ma Cà Rồng Nhân Văn Và Người Muốn Tự Sát', 'Humanist Vampire Seeking Consenting Suicidal Person', 'https://phimimg.com/upload/vod/20240603-1/1149eb9e66c9684667d7b0d126ad5d89.jpg', 'https://phimimg.com/upload/vod/20240603-1/74ea29c203920ab720e8d7d7d1c4eb46.jpg', '<p>Sasha là một ma cà rồng trẻ tuổi với một vấn đề nghiêm trọng: Sợ giết. Mạng sống của Sasha gặp nguy hiểm khi cha mẹ cô tức giận cắt nguồn cung cấp máu. May mắn thay, cô gặp được Paul, một thiếu niên cô đơn có khuynh hướng tự sát sẵn sàng hy sinh mạng sống của mình để cứu cô. Nhưng thỏa thuận thân thiện của họ sớm trở thành một nhiệm vụ về đêm nhằm thực hiện những mong muốn cuối cùng của Paul trước khi trời sáng.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Sara Montpetit","avatar":""},{"name":"Félix-Antoine Bénard","avatar":""},{"name":"Steve Laplante","avatar":""},{"name":"Sophie Cadieux","avatar":""},{"name":"Noémie O''Farrell","avatar":""},{"name":"Arnaud Vachon","avatar":""},{"name":"Marie Brassard","avatar":""},{"name":"Madeleine Péloquin","avatar":""},{"name":"Gabriel-Antoine Roy","avatar":""},{"name":"Isabella Villalba","avatar":""},{"name":"Patrick Hivon","avatar":""},{"name":"Marc Beaupré","avatar":""},{"name":"Micheline Bernard","avatar":""},{"name":"Sylvie Lemay","avatar":""},{"name":"Ariane Ca","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324252);
