INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tieu-phu', 'Quái vật tiều phu', 'Lumberjack the Monster', 'https://phimimg.com/upload/vod/20240602-1/58860536fdac79c98f9b29f46f60a39b.jpg', 'https://phimimg.com/upload/vod/20240602-1/2714608a2db472580142728f20958044.jpg', '<p>Tự xưng là kẻ tâm thần, luật sư máu lạnh Ninomiya trở nên ám ảnh với việc ngăn chặn kẻ giết người hàng loạt cầm rìu coi anh là mục tiêu tiếp theo của hắn.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kazuya Kamenashi","avatar":""},{"name":"Nanao","avatar":""},{"name":"吉岡里帆","avatar":""},{"name":"Kiyohiko Shibukawa","avatar":""},{"name":"Shota Sometani","avatar":""},{"name":"中村獅童","avatar":""},{"name":"Reon Yuzuki","avatar":""},{"name":"Minosuke","avatar":""},{"name":"Keisuke Horibe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324252);
