INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-len-cac-be-cun-phan-4', 'Tiến Lên, Các Bé Cún! (Phần 4)', 'Go, Dog. Go! (Season 4)', 'https://phimimg.com/upload/vod/20240531-1/29f046e513ff44f8da9756f11672aec1.jpg', 'https://phimimg.com/upload/vod/20240531-1/3fc67851c6bee00fe6b7472811866902.jpg', '<p>Bé cún khéo léo và sáng tạo Tag theo đuổi cuộc phiêu lưu cùng cậu bạn thân Scooch. Trên hành trình đó, cả hai giải quyết vấn đề và giúp đỡ các cư dân của Pawston.</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michela Luci","avatar":""},{"name":"Callum Shoniker","avatar":""},{"name":"Martin Roach","avatar":""},{"name":"David Berni","avatar":""},{"name":"Anand Rajaram","avatar":""},{"name":"Linda Ballantyne","avatar":""},{"name":"Patrick McKenna","avatar":""},{"name":"Katie Griffin","avatar":""},{"name":"Tajja Isen","avatar":""},{"name":"Judy Marshak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324252);
