INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nhen', 'Ổ Nhện', 'Infested', 'https://phimimg.com/upload/vod/20240530-1/9a37195abdc9a7b283ebaa7d0c21c291.jpg', 'https://phimimg.com/upload/vod/20240530-1/79b0a88f407895c4e5d5fc1d181a57f0.jpg', '<p>Một bộ phim của đạo diễn người Pháp Sébastien Vanícek. Lấy bối cảnh một chung cư cũ, bộ phim xoay quanh Kaleb, một người đàn ông cô đơn trong độ tuổi 30. Một ngày kia, anh trở về nhà cùng một giống nhện kỳ lạ nhưng không quá để tâm. Thế nhưng, khi loài nhện ngày càng sinh sôi mạnh mẽ - một cách kinh hoàng, cả khu chung cư chìm ngập trong sự sợ hãi và chết chóc.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Pháp', 1, '[{"name":"Théo Christine","avatar":""},{"name":"Sofia Lesaffre","avatar":""},{"name":"Finnegan Oldfield","avatar":""},{"name":"Jérôme Niel","avatar":""},{"name":"Lisa Nyarko","avatar":""},{"name":"Marie-Philomène Nga","avatar":""},{"name":"Emmanuel Bonami","avatar":""},{"name":"Abdellah Moundy","avatar":""},{"name":"Mahamadou Sangaré","avatar":""},{"name":"Xing Xing Cheng","avatar":""},{"name":"Malik Amraoui","avatar":""},{"name":"Ike Zacsongo-Joseph","avatar":""},{"name":"Samir Nait","avatar":""},{"name":"Lehcem Mahidi","avatar":""},{"name":"Nasser Mehal","avatar":""},{"name":"Abdelkader","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324252);
