INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-chan-ngon-truyen-thuyet-bat-nguyet', 'Chiến Binh Chân Ngôn: Truyền Thuyết Bát Nguyệt', 'Mantra Warrior: The Legend Of The Eight Moons', 'https://phimimg.com/upload/vod/20240530-1/f2e2dc2fb32c45418ff23786348b7a3e.jpg', 'https://phimimg.com/upload/vod/20240530-1/dec921e31c5d6239920cca6681306851.jpg', '<p>Một câu chuyện lấy cảm hứng từ RAMAYANA gốc, được kể lại trong một vũ trụ tương lai, liên quan đến những chiến binh dũng cảm sở hữu sức mạnh cổ xưa từ một chiều không gian khác. Khi vợ bị tên bạo chúa thiên hà bắt cóc, hoàng tử nọ tiến hành trận chiến hùng tráng để giải thoát cô với sự hỗ trợ của anh trai, một vị vua tham chiến và một nhóm chiến binh.</p>', 'Full', 1, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ranee Campen","avatar":""},{"name":"Tachaya Pathumwan","avatar":""},{"name":"Sorawit Tongteng","avatar":""},{"name":"Nalinee Cheewasakorn","avatar":""},{"name":"Pattechin Sasipatthanathada","avatar":""},{"name":"Rujira Khajicharoen","avatar":""},{"name":"Apinan Teeranantakul","avatar":""},{"name":"Manop Srijupao","avatar":""},{"name":"Thanakrit Jenklongtham","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324252);
