INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-curses', 'Lời Nguyền! - Curses!', 'Curses!', 'https://phimimg.com/upload/vod/20240530-1/fd1ab7132570217d6087388c1660b91c.jpg', 'https://phimimg.com/upload/vod/20240530-1/31b9e0a551920ede0b108f4a6f59e726.jpg', '<p>Nhà Vanderhouven là gia đình điển hình… ngoại trừ một lời nguyền mới đây đã biến Alex - người chồng và người cha yêu thương của họ - thành đá. Để cứu anh, vợ và các con anh bắt đầu cuộc phiêu lưu sởn gai ốc để trả lại những cổ vật bị tổ tiên đánh cắp.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Andre Robinson","avatar":""},{"name":"Gabrielle Nevaeh Green","avatar":""},{"name":"Lyric Lewis","avatar":""},{"name":"Reid Scott","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"James Marsters","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324252);
