INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vang-trang-mau', 'Vầng Trăng Máu', 'Killers of the Flower Moon', 'https://phimimg.com/upload/vod/20231018-1/cab1898d7792b57a29fae7387a28ab22.jpg', 'https://phimimg.com/upload/vod/20231018-1/2d58f5a9e1a31d07f4c6d37f9d63e22c.jpg', '<p>Khi dầu được phát hiện vào những năm 1920 ở Oklahoma dưới vùng đất của Quốc gia Osage, người dân Osage lần lượt bị sát hại — cho đến khi FBI vào cuộc để làm sáng tỏ bí ẩn.</p>', 'Full', 1, 'single', 'ongoing', 11, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 1, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Lily Gladstone","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"Tantoo Cardinal","avatar":""},{"name":"Cara Jade Myers","avatar":""},{"name":"JaNae Collins","avatar":""},{"name":"Jillian Dion","avatar":""},{"name":"William Belleau","avatar":""},{"name":"Louis Cancelmi","avatar":""},{"name":"Tatanka Means","avatar":""},{"name":"Michael Abbott Jr.","avatar":""},{"name":"Pat Healy","avatar":""},{"name":"Scott Shepherd","avatar":""},{"name":"Jason Isbell","avatar":""},{"name":"Sturgill Simpson","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
