INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-kip-yeu-duong-cua-phuong-tieu-thu', 'Bí Kíp Yêu Đương Của Phương Tiểu Thư', 'Miss Fang''s Love Secrets', 'https://phimimg.com/upload/vod/20240515-1/7c71c64e775dd6aca1eaeaeceec44cc9.jpg', 'https://phimimg.com/upload/vod/20240515-1/9085a97a418f9e61969cfc8433f8206e.jpg', '<p>Phương Tịch Mộ, lập trình viên của game yêu đương Quan Hệ Bí Mật, vô tình bị mắc kẹt trong trò chơi và trở thành NPC có thể đăng xuất bất cứ lúc nào khi đang tăng ca. Để giữ được mạng quèn, phải chinh phục nam chính Bách Hạo Thiên của game, hoàn thành nhiệm vụ tình yêu tuyến chính trước. Phương Tịch Mộ với lý thuyết yêu đương thượng thừa nhưng lại ế từ trong trứng, còn đối thủ lại là tổng tài bá đạo với danh xưng Lý tưởng hoàn hảo của mọi cô gái, ai sẽ cao tay hơn đây? Chế độ Khó đã bắt đầu, chỉ còn một quy tắc sinh tồn - chỉ có đánh cắp trái tim mới có giữ được mạng, đến lúc thể hiện kỹ năng thật sự rồi...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Yijin","avatar":""},{"name":"Zhang Jingyun","avatar":""},{"name":"Xie Zhixun","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
