INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-choi-ca-the-gioi', 'Chàng Trai Chọi Cả Thế Giới', 'Boy Kills World', 'https://phimimg.com/upload/vod/20240524-1/fd67046fc06d2ea181f5e520a869f735.jpg', 'https://phimimg.com/upload/vod/20240524-1/7e3b3724c9e5a71870e4e8c40d2b48a3.jpg', '<p>Phim xoay quanh câu chuyện về một chàng trai điếc tên là Boy, sau khi gia đình anh bị giết hại, anh đã chạy trốn vào rừng và được một pháp sư bí ẩn huấn luyện để kìm nén trí tưởng tượng của mình và trở thành một công cụ của cái chết. Được huấn luyện trong môi trường hoang dã, Boy phải học cách sống sót và chiến đấu để báo thù cho gia đình của mình. Sự kết hợp giữa yếu tố hành động, huyền bí và tâm lý khiến cho bộ phim này trở nên đầy kịch tính và cuốn hút người xem.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bill Skarsgård","avatar":""},{"name":"Jessica Rothe","avatar":""},{"name":"Michelle Dockery","avatar":""},{"name":"Brett Gelman","avatar":""},{"name":"Isaiah Mustafa","avatar":""},{"name":"Yayan Ruhian","avatar":""},{"name":"Cameron Crovetti","avatar":""},{"name":"Nicholas Crovetti","avatar":""},{"name":"Quinn Copeland","avatar":""},{"name":"Andrew Koji","avatar":""},{"name":"Sharlto Copley","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"H. Jon Benjamin","avatar":""},{"name":"Dorothy Ann Gould","avatar":""},{"name":"Jane de Wet","avatar":""},{"name":"Inge Beckmann","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324252);
