INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-vuong-2', 'Tứ Vương 2', '4 Kings 2', 'https://phimimg.com/upload/vod/20240524-1/3ff515044e68eebb697d439eb5a81937.jpg', 'https://phimimg.com/upload/vod/20240524-1/cdd50d01dbf86a80cc912f3a4759bdf2.jpg', '<p>Sau khi một kẻ buôn ma túy bí mật bày mưu chống lại họ, hai băng nhóm học sinh vướng vào mối thù cay đắng dẫn đến chuỗi hậu quả bạo lực.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Somphol Rungphanit","avatar":""},{"name":"Sutthirak Subvijitra","avatar":""},{"name":"Sirat Intarachote","avatar":""},{"name":"D Gerrard","avatar":""},{"name":"Patara Eksangkul","avatar":""},{"name":"Nuttawut Jenmana","avatar":""},{"name":"Benjamin Joseph Varney","avatar":""},{"name":"Todsapol Maisuk","avatar":""},{"name":"Intira Jaroenpura","avatar":""},{"name":"Touch Na Takuatung","avatar":""},{"name":"Watsana Phunphon","avatar":""},{"name":"Sahatchai Chumrum","avatar":""},{"name":"Akarin Akaranitimaytharatt","avatar":""},{"name":"ธา","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324252);
