INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-tau-bac-cuc', 'Đoàn Tàu Bắc Cực', 'The Arctic Convoy', 'https://phimimg.com/upload/vod/20240524-1/7e75080b84105552c1ee76ae7aed0aa0.jpg', 'https://phimimg.com/upload/vod/20240524-1/883103571545dfcc83e9f364aab276e9.jpg', '<p>Năm 1942, một đoàn tàu gồm 35 tàu dân sự chở hàng tiếp tế quan trọng từ Iceland đến Liên Xô phải đối mặt với những thách thức chết người ở Bắc Cực. Bất chấp sự hộ tống của hải quân Đồng minh, những lỗi tình báo thảm khốc khiến đoàn xe phải đối mặt với các cuộc tấn công không ngừng của không quân và hải quân Đức. Trong điều kiện khắc nghiệt, các thủy thủ dân sự thiếu kinh nghiệm chiến đấu để sinh tồn, chỉ có 12 con tàu đến được đích.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Na Uy', 0, '[{"name":"Tobias Santelmann","avatar":""},{"name":"Anders Baasmo Christiansen","avatar":""},{"name":"Heidi Ruud Ellingsen","avatar":""},{"name":"Preben Hodneland","avatar":""},{"name":"Adam Lundgren","avatar":""},{"name":"Jon Ranes","avatar":""},{"name":"Olav Waastad","avatar":""},{"name":"Jakob Fort","avatar":""},{"name":"Fredrik Stenberg Ditlev-Simonsen","avatar":""},{"name":"Tord Kinge","avatar":""},{"name":"Kristian Repshus","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324252);
