INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-duoc-vui-ve', 'Để Được Vui Vẻ', 'Mast Mein Rehne Ka', 'https://phimimg.com/upload/vod/20240524-1/3301aeaf9e4c43b6e3840b4cbacdb24e.jpg', 'https://phimimg.com/upload/vod/20240524-1/70c454653dd5f3d769dcdea1a788ccca.jpg', '<p>Một người đàn ông chọn nhà của một người góa vợ già cho vụ cướp đầu tiên của mình, bắt đầu một loạt sự kiện khiến cả hai nhìn cuộc sống theo một cách mới và với những người bạn đồng hành mới trong sự ảm đạm của thành phố Mumbai.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Jackie Shroff","avatar":""},{"name":"Neena Gupta","avatar":""},{"name":"Abhishek Chauhan","avatar":""},{"name":"Monika Panwar","avatar":""},{"name":"Rakhi Sawant","avatar":""},{"name":"Shashi Kiran","avatar":""},{"name":"Faisal Malik","avatar":""},{"name":"Mashhoor Amrohi","avatar":""},{"name":"Priyadarshan Jadhav","avatar":""},{"name":"Uday Sabnis","avatar":""},{"name":"Vijay Maurya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
