INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-chung-tuoi-thanh-xuan-em-gai-xuat-hanh', 'Hội Chứng Tuổi Thanh Xuân: Em Gái Xuất Hành', 'Rascal Does Not Dream Of A Sister Venturing Out', 'https://phimimg.com/upload/vod/20240522-1/8e2c79b637ed59c05212f525d007a6bf.jpg', 'https://phimimg.com/upload/vod/20240522-1/d42fa2f0f0551f04fc93890746254b3b.jpg', '<p>Sau khi bị đe dọa tính mạng và những hành vi bắt nạt khác trên mạng, Kaede Azusagawa đã có một phá vỡ phân ly dẫn đến mất trí nhớ hoàn toàn. Trong hai năm tiếp theo, cô sống như một con người hoàn toàn mới, một người khép kín trốn tránh thế giới. May mắn thay, nhờ có sự đồng hành của anh trai và những người bạn mới, cô ấy đã có thể hồi phục — mặc dù cái giá phải trả để có thể hồi phục là những kỷ niệm trong hai năm quý giá đó. Bây giờ Kaede không chỉ phải cố gắng để tiến về phía trước với một lỗ hổng trong ký ức mà cô ấy còn phải đối phó với nỗi sợ hãi mà những người gần gũi nhất với mình bây giờ sẽ cảm thấy xa cách với con người hiện tại của cô ấy vì quá thân thuộc với bóng hình của cô gái trong hai năm qua.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"石川界人","avatar":""},{"name":"瀬戸麻沙美","avatar":""},{"name":"久保ユリカ","avatar":""},{"name":"東山奈央","avatar":""},{"name":"種﨑敦美","avatar":""},{"name":"内田真礼","avatar":""},{"name":"水瀬いのり","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
