INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-anh-sang-cua-anh', 'Em Là Ánh Sáng Của Anh', 'My Star', 'https://phimimg.com/upload/vod/20240515-1/1f481d3b7fb81a77cc9024de9b3e40d0.jpg', 'https://phimimg.com/upload/vod/20240515-1/ecfdd7f7d2726bcacf954fc2762f6535.jpg', '<p>Cố Lâm Tinh, đại thiếu gia nhà họ Cố trước giờ ngang ngược, kiêu căng vô tình gặp gỡ Trần Tư Nam, một trợ giảng đại học kiên cường, lương thiện. Cố Lâm Tinh lâm vào hoàn cảnh sa sút, buộc phải ký thỏa thuận thuê chung nhà, hai người từ đó bắt đầu cuộc sống chung ngọt ngào. Tuy nhiên mâu thuẫn gia đình đã nảy sinh. Trước những tin đồn bịa đặt và cám dỗ của đồng tiền, Cố Lâm Tinh và Trần Tư Nam sẽ lựa chọn như thế nào?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Han Chengyu","avatar":""},{"name":"Ma Jinghan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
