INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-gia-chung-tuong', 'Oan Gia Chung Tường', 'My Worst Neighbor', 'https://phimimg.com/upload/vod/20230920-1/1ae083ca36dff8df8dec357aa6204b51.jpg', 'https://phimimg.com/upload/vod/20230920-1/d467c83629700e9df6f5bcc989b0a84e.jpg', '<p><span style="font-family: ">“Oan Gia Chung Tường” là bộ phim kể về Seung-jin, chàng nhạc sĩ đầy tham vọng và Ra-ni, một nhà thiết kế mô hình nhân vật. Về mặt “cấu trúc nhà” học, hai người hướng nội tuy ở khác căn nhưng sinh hoạt khó khăn vì dùng chung một bức tường siêu mỏng với khả năng cách âm bằng không. Sau khi dùng 7749 chiêu trò để xua đuổi đối phương thì bỗng thấy thương thương người bên kia tường. Chuyện tình xa mặt…nhưng không cách lòng này hứa hẹn sẽ khiến nhiều thanh niên quyết tâm ra riêng để đường tình duyên trở nên tươi sáng.</span></p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Ji-hoon","avatar":""},{"name":"Han Seung-yeon","avatar":""},{"name":"Go Gyu-pil","avatar":""},{"name":"Kim Yoon-sung","avatar":""},{"name":"Lee Yoo-jun","avatar":""},{"name":"Jung Ae-yeun","avatar":""},{"name":"Im Kang-sung","avatar":""},{"name":"Shin Ji-woo","avatar":""},{"name":"Lee Se-joon","avatar":""},{"name":"JeA","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324252);
