INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-cuoc-doi', 'Một Cuộc Đời', 'One Life', 'https://phimimg.com/upload/vod/20240515-1/4b1b26c7234f70ac018b37acf3466f9f.jpg', 'https://phimimg.com/upload/vod/20240515-1/1614087fe9a72546c3fabf570624219b.jpg', '<p>Câu chuyện có thật về Ngài Nicholas &#39;Nicky&#39; Winton, một nhà môi giới trẻ ở London, trong những tháng trước Thế chiến thứ hai, đã giải cứu 669 trẻ em chủ yếu là người Do Thái khỏi tay Đức Quốc xã. Nicky đến thăm Praha vào tháng 12 năm 1938 và tìm thấy những gia đình đang cố gắng chạy trốn khỏi sự trỗi dậy của Đức Quốc xã, sống trong điều kiện tuyệt vọng với rất ít hoặc không có nơi ở và thức ăn. Anh ngay lập tức nhận ra đó là một cuộc chạy đua với thời gian. Anh và nhóm của mình có thể giải cứu bao nhiêu đứa trẻ trước khi biên giới đóng cửa? Năm mươi năm sau, vào năm 1988, Nicky luôn sống trong cảm giác bị ám ảnh về số phận của những đứa trẻ mà anh không thể đưa đến nơi an toàn. Mãi cho đến khi một chương trình truyền hình trực tiếp của BBC, &#39;That&#39;s Life&#39; tạo ra cơ hội để anh gặp lại một vài trong số những đứa trẻ còn sống - giờ đã trưởng thành - thì anh mới bắt đầu đối mặt với cảm giác tội lỗi và đau buồn mà mình đã mang theo suốt 5 thập kỷ.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Johnny Flynn","avatar":""},{"name":"Lena Olin","avatar":""},{"name":"Romola Garai","avatar":""},{"name":"Alex Sharp","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Juliana Moska","avatar":""},{"name":"Ziggy Heath","avatar":""},{"name":"Marthe Keller","avatar":""},{"name":"Tim Steed","avatar":""},{"name":"Matilda Thorpe","avatar":""},{"name":"Samantha Spiro","avatar":""},{"name":"Adrian Rawlins","avatar":""},{"name":"Tom Glenister","avatar":""},{"name":"Michael Gould","avatar":""},{"name":"Samuel Finzi","avatar":""},{"name":"Jiř","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324252);
