INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-bong-ma', 'Đặc Vụ Bóng Ma', 'Phantom', 'https://phimimg.com/upload/vod/20230922-1/a276c6142242563a6f62bfa6a50ddb38.jpg', 'https://phimimg.com/upload/vod/20230922-1/c36f1c9ba4a23271b36110fd5eefc90b.jpg', '<p>Năm 1933, khi Hàn Quốc còn bị Nhật Bản chiếm đóng, 5 người ở Kyungseong bị tình nghi là gián điệp “bóng ma” của tổ chức chống Nhật.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Sol Kyung-gu","avatar":""},{"name":"Lee Ha-nee","avatar":""},{"name":"Park So-dam","avatar":""},{"name":"Park Hae-soo","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Kim Dong-hee","avatar":""},{"name":"Kim Hye-ok","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Esom","avatar":""},{"name":"Lee Joo-young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324252);
