INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-san-rong', 'Biệt Đội Săn Rồng', 'Slyth: The Hunt Saga', 'https://phimimg.com/upload/vod/20240515-1/402383425faa16dd3fc52e9ff36d74ed.jpg', 'https://phimimg.com/upload/vod/20240515-1/6be2820e67b210d3cddc02a5c9aae033.jpg', '<p>Sau khi các vụ cháy tận thế khiến thế giới không thể ở được, nhóm bạn nọ vô tình gặp một sinh vật bò sát bí ẩn nắm giữ chìa khóa cho sự sống còn của con người.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Luke Ishikawa Plowden","avatar":""},{"name":"Mookda Narinrak","avatar":""},{"name":"Peemapol Panichtamrong","avatar":""},{"name":"Supakchaya Sukbaiyen","avatar":""},{"name":"Patpasit Na Songkhla","avatar":""},{"name":"Poy Kritsanapong Soonthornchatchawet","avatar":""},{"name":"Pasut Banyam","avatar":""},{"name":"Antoine Pinto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324252);
