INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-moi-cua-ba-ngoai', 'Thế Giới Mới Của Bà Ngoại', 'Grandma''s New World', 'https://phimimg.com/upload/vod/20240515-1/3877772ac2c38dde75071c22e62365ef.jpg', 'https://phimimg.com/upload/vod/20240515-1/c86e4d5477a3e01914c9bc9c8ec71964.jpg', '<p>Miêu tả: Năm năm trước, bà ngoại đột ngột bỏ nhà ra đi để đến một thế giới rộng lớn hơn để tìm và xây dựng lại cuộc sống mới. Năm năm sau, gia đình vô tình nhận được tin tức về bà ngoại, cháu gái Đậu Ỷ và chị gái song sinh của cô, dì, bắt đầu hành trình tìm kiếm bà. Trong khi tìm kiếm, họ lắng nghe những câu chuyện của bà và nhận ra mọi thứ mà bà đã trải qua. Những câu chuyện ấy khiến họ nhận ra nghị lực chôn sâu của bà, đôi khi ngỡ ngàng, đôi khi trầm ngâm. Nó cũng cho phép họ khám phá trái tim của chính mình và hiểu lại chính mình. Hết lần này đến lần khác, bí ẩn về người bà của chị em cô ngày càng rõ ràng.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"YanNi","avatar":""},{"name":"Deng En Xi","avatar":""},{"name":"Yao Chen","avatar":""},{"name":"May Wang Luodan","avatar":""},{"name":"Mei Ting","avatar":""},{"name":"Liu Lin","avatar":""},{"name":"Huang Zhi Zhong","avatar":""},{"name":"VIVI","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324252);
