INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-moi-cua-ba-ngoai', 'Thế Giới Mới Của Bà Ngoại', 'Grandma''s New World', 'thế giới mới của bà ngoại grandma''s new world yanni deng en xi yao chen may wang luodan mei ting liu lin huang zhi zhong vivi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chau-tinh-ky', 'Châu Tinh Kỷ', 'The Mermaid''s Pearl', 'https://phimimg.com/upload/vod/20240426-1/43470ecbf97c2bfaf003fb1974d1e28e.jpg', 'https://phimimg.com/upload/vod/20240426-1/9729c15579687fb9eeb559be6cbc37fa.jpg', '<p>Trong lúc tìm kiếm phụ thân Hải Nhâm, thiếu nữ giao nhân Bao Nhục Nhục vướng vào vụ án giết người, tình cờ quen được thần thám vua ban Cố Tinh Hà. Để điều tra tung tích phụ thân, Bao Nhục Nhục bị ép trở thành người hầu cho Cố Tinh Hà, còn Cố Tinh Hà muốn tìm thuốc chữa bệnh nên thăm dò thân phận giao nhân của Bao Nhục Nhục đủ mọi cách. Hai người giằng co rất lâu, khó phân thắng thua. Thiếu nữ ngây thơ mắc bẫy trở thành học trò, thần thám mưu mô gian xảo nhiều chiêu cao siêu… Cứ thế, hạt giống tình yêu lặng lẽ nảy mầm. Thần thám ham mê phá án gặp thiếu nữ giao nhân, cặp đôi kỳ lạ này đã chung tay phá được một loạt các vụ án kỳ dị, dần dần không còn thành kiến với nhau, giúp đỡ lẫn nhau, an ủi cho nhau. Chân tướng các vụ án lần lượt phơi bày, hai người phát hiện ra phía sau còn có mưu đồ tày trời, có liên quan chặt chẽ tới tung tích của Hải Nhâm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yajia Wang","avatar":""},{"name":"Shi An","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
