INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chau-tinh-ky', 'Châu Tinh Kỷ', 'The Mermaid''s Pearl', 'châu tinh kỷ the mermaid''s pearl yajia wang shi an ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-lau-moi-them-yeu-duong', 'Còn Lâu Mới Thèm Yêu Đương', 'Please Fall In Love', 'https://phimimg.com/upload/vod/20240423-1/5c663613fe0bf5b2c22103d5f87d99d8.jpg', 'https://phimimg.com/upload/vod/20240423-1/cadf78b1b69b17474c6fb1ae4d6a2329.jpg', '<p>Lôi Đồng đã thức liền năm đêm để hoàn thành bản thảo. Cô xuyên vào truyện &quot;Cô vợ nhỏ của tổng tài bá đạo&quot; mà mình chưa hoàn thành, trở thành nữ phụ làm nền - Sơ Tễ. Chỉ có tình yêu mới có thể giúp cô quay trở lại thế giới thực. Nhưng cô lại làm ngược lại, không cần đàn ông, không cần công việc, cô chỉ muốn trở thành một cô gái xinh đẹp giàu có, không ngờ tình yêu và sự nghiệp lại nối đuôi nhau đến trước cửa nhà cô!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Garvey Jin","avatar":""},{"name":"Vivi Chen","avatar":""},{"name":"Hu Chun-Yang","avatar":""},{"name":"Zhu Yun Long","avatar":""},{"name":"Chen Xin Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
