INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('malbatt-su-menh-bakara', 'Malbatt: Sứ Mệnh Bakara', 'Malbatt: Misi Bakara', 'https://phimimg.com/upload/vod/20240508-1/5ee44ea1cb8f8cdedc03f2271533a210.jpg', 'https://phimimg.com/upload/vod/20240508-1/46ff44faa998ac79cd4ea2fbb23e8d8a.jpg', '<p>Trong bộ phim dựa trên các sự kiện có thật này, Tiểu đoàn Malaysia thực hiện sứ mệnh giúp giải cứu quân đội Hoa Kỳ bị dồn vào thế bí trong trận Mogadishu.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Bront Palarae","avatar":""},{"name":"Shaheizy Sam","avatar":""},{"name":"Hairul Azreen","avatar":""},{"name":"Zahiril Adzim","avatar":""},{"name":"Iedil Putra","avatar":""},{"name":"Adlin Aman Ramlie","avatar":""},{"name":"Fauzi Nawawi","avatar":""},{"name":"Tony Eusoff","avatar":""},{"name":"Syazwan Zulkifly","avatar":""},{"name":"Dafi Ismail Sabri","avatar":""},{"name":"Taufiq Hanafi","avatar":""},{"name":"Nafiez Zaidi","avatar":""},{"name":"Dini Schatzmann","avatar":""},{"name":"Gambit Saifullah","avatar":""},{"name":"Safwan Nazri","avatar":""},{"name":"Theebaan Govindasamy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324252);
