INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khongkhaek-loi-nguyen', 'Khong-Khaek: Lời Nguyền', 'The Djinn''s Curse', 'https://phimimg.com/upload/vod/20240508-1/869eac1ec1e84d3423a45461a4a3286f.jpg', 'https://phimimg.com/upload/vod/20240508-1/a4f1ccbe380e0eb903e0dc1a5ff8304f.jpg', '<p>Một gia đình cố gắng bắt đầu lại sau khi chuyển đến Narathiwat, nhưng bị quấy nhiễu bởi một linh hồn giết chóc ám nhà mới của họ.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Akara Amarttayakul","avatar":""},{"name":"Amena Pinit","avatar":""},{"name":"Marika Paekiatchalorn","avatar":""},{"name":"Thiti Rumorn","avatar":""},{"name":"Hakim Donlapavijit","avatar":""},{"name":"Anyarin Terathananpat","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324252);
