INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-cho-chang', 'Gả Cho Chàng', 'The Reincarnated Lovers', 'https://phimimg.com/upload/vod/20240418-1/81a61cdb51d7f91969fcbef84b053111.jpg', 'https://phimimg.com/upload/vod/20240418-1/1bdf0a68e90f55bce57c9956c94dfb47.jpg', '<p>Vào đúng ngày thành thân, Đường Vãn Uyển bị tân lang Tiêu Huyền Ngật thảm sát cả nhà. Đường Vãn Uyển đem lòng thù hận, tìm cơ hội giết chết Tiêu Huyền Ngật sau đó tự sát, nhưng lại bất ngờ trở về ba năm trước. Mà điều nàng không biết là, kiếp này Tiêu Huyền Ngật cũng có ký ức kiếp trước. Hai người cùng sống lại, một mối tình đau đớn cùng cực bắt đầu từ đây...</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guan Yue","avatar":""},{"name":"Guo Jia Yu","avatar":""},{"name":"Patrick Quan","avatar":""},{"name":"Wu Rilige","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
