INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-nu', 'Ác Nữ', 'Lost in Perfection', 'https://phimimg.com/upload/vod/20240508-1/71ab207d3fe7ed17fe741cf0530c67ce.jpg', 'https://phimimg.com/upload/vod/20240508-1/17195b7a372bb95133b2df43b9fc3c06.jpg', '<p>Một biên tập viên nghi ngờ vị hôn thê của bố cô có thể là kẻ lừa đảo giết người, nhưng việc cố gắng chứng minh điều đó đẩy cô vào tình thế nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Ivy Shao","avatar":""},{"name":"Lin Mei-shiu","avatar":""},{"name":"Rhydian Vaughan","avatar":""},{"name":"Figaro Tseng","avatar":""},{"name":"Mark Lee","avatar":""},{"name":"Ven Kao","avatar":""},{"name":"Chia-Kuei Chen","avatar":""},{"name":"Chia-Hsuan Yu","avatar":""},{"name":"Jake Hsu","avatar":""},{"name":"Tzu-Chien Kuo","avatar":""},{"name":"Sara Yu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324252);
