INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-nuong-giay', 'Tân Nương Giấy', 'Paper Bride', 'https://phimimg.com/upload/vod/20240508-1/5351f65e89281dda5c332a6cc545fa80.jpg', 'https://phimimg.com/upload/vod/20240508-1/a7eb6c7b6877966df97515f928ff7e2c.jpg', '<p>Câu chuyện diễn ra trong giai đoạn đầu năm Dân quốc tại làng Thanh Bảo. Bà cả của gia đình Mã tổ chức một buổi minh hôn cho cháu trai lớn, Mã Bất Minh, người đã qua đời vì bệnh tật. Sự hỗn loạn bắt đầu khi cô dâu giấy bí ẩn, người đã từ trần, đột ngột trở lại. Pháp sư phong thủy tiết lộ rằng Mã Bất Khoái, cháu trai thứ hai của bà, có liên kết âm đới với cô dâu giấy, khiến anh ta bị ám ảnh và buộc phải rời bỏ gia đình. Mười một năm sau, Mã Bất Khoái trở về quê hương cùng với người yêu Lý Chiêu Ðệ để thảo luận về việc kết hôn. Tuy nhiên, khi anh quay về gia đình, một loạt vụ án kỳ quái xảy ra. Mặc dù không tin vào ma quỷ, nhưng Mã Bất Khoái cảm thấy có sự bí ẩn đằng sau những sự kiện này và quyết định tự mình điều tra để giải mã bí mật. Trong quá trình này, anh phát hiện ra nhiều điều về nỗi bất bình lâu nay.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tan Xin Zer","avatar":""},{"name":"王子甲","avatar":""},{"name":"Paul Che Biu-law","avatar":""},{"name":"Liu Ya Jin","avatar":""},{"name":"Han Mengwu","avatar":""},{"name":"Shen Xin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324252);
