INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-ngoai-vong-phap-luat', 'Quyền Ngoài Vòng Pháp Luật', 'Birthright Outlaw', 'https://phimimg.com/upload/vod/20240509-1/93552d8772ad944c7dc347dff3d99523.jpg', 'https://phimimg.com/upload/vod/20240509-1/412b379b7216db03582621b41dd82274.jpg', '<p>Một đứa con gái bị bắt cóc. Một quá khứ ẩn giấu được tiết lộ. Một cơ hội giải cứu dường như vô ích. Giờ đây, Mục sư Jeremiah Jacobs và vợ ông là Martha phải vượt qua những dối trá trong quá khứ để tìm thấy Hy vọng cho tương lai.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sarah Drew","avatar":""},{"name":"Lucas Black","avatar":""},{"name":"Olivia Sanabia","avatar":""},{"name":"Tom Proctor","avatar":""},{"name":"Eric Stanton Betts","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Janine Turner","avatar":""},{"name":"Jackson Hurst","avatar":""},{"name":"Jeremy Gauna","avatar":""},{"name":"Tiff Jensen","avatar":""},{"name":"Jenin Gonzalez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
