INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quyen-ngoai-vong-phap-luat', 'Quyền Ngoài Vòng Pháp Luật', 'Birthright Outlaw', 'quyền ngoài vòng pháp luật birthright outlaw sarah drew lucas black olivia sanabia tom proctor eric stanton betts jeff fahey janine turner jackson hurst jeremy gauna tiff jensen jenin gonzalez ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-2023', 'Quái Vật', 'Monster', 'https://phimimg.com/upload/vod/20240509-1/52096d392a5d71642977dfdcd10482de.jpg', 'https://phimimg.com/upload/vod/20240509-1/34c8033e68576653cc48f06d50aa4e15.jpg', '<p>Mugino Saori (Ando Sakura) là một bà mẹ đơn thân hiện đang nuôi cậu con trai học lớp 5 tên là Mugino Minato (Kurokawa Souya). Tuy nhiên, cậu bé đã sớm bắt đầu có những hành vi kỳ lạ như tự cắt tóc và khi đi học về nhà lại chỉ còn mang 1 chiếc giày. Một đêm nọ, Minato không về nhà và sau khi gọi điện khắp nơi, Saori tìm thấy cậu bé trong một đường hầm xe lửa bỏ hoang. Từ đây, Saori bắt đầu nghi ngờ giáo viên của con trai mình tên là Hori (Nagayama Eita) đang có những hành vi bạn hành con mình và đến trường đòi lời giải thích. Tuy nhiên, Saori phải sớm thất vọng trước thái độ của thầy Hori và những người khác, đỉnh điểm hơn khi thầy Hori có nhắc tới việc một cậu bé tên là Yori (Hiigari Hinata) mới là nạn nhân của Minato.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Sakura Ando","avatar":""},{"name":"Eita Nagayama","avatar":""},{"name":"Soya Kurokawa","avatar":""},{"name":"Hinata Hiiragi","avatar":""},{"name":"Yûko Tanaka","avatar":""},{"name":"Mitsuki Takahata","avatar":""},{"name":"Akihiro Kakuta","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Ryu Morioka","avatar":""},{"name":"Daisuke Kuroda","avatar":""},{"name":"Ayu Kitaura","avatar":""},{"name":"Haruto Kobayashi","avatar":""},{"name":"Kouga Yagishita","avatar":""},{"name":"Taichi Kanemitsu","avatar":""},{"name":"Harune Iida","avatar":""},{"name":"Shiyun Nakamura","avatar":""},{"name":"Pee","avatar":""},{"name":"Kay","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a0