INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-han-toi-day', 'Đưa Hắn Tới Đây', 'Bring Him to Me', 'https://phimimg.com/upload/vod/20240508-1/57dcb6f6fb5e9b0a26de7be3c38de017.jpg', 'https://phimimg.com/upload/vod/20240508-1/4d6a91507adb7feb5e8819a2479687ed.jpg', '<p>&quot;Đưa Hắn Tới Đây - Bring Him to Me 2023&quot; là một bộ phim hình sự đầy kịch tính của Úc, được ra mắt vào năm 2023 và do đạo diễn và nhà sản xuất Luke Sparke chịu trách nhiệm, với kịch bản được viết bởi Tom Evans. Bộ phim có sự tham gia của dàn diễn viên tài năng như Barry Pepper, Jamie Costa, Liam McIntyre, Rachel Griffiths và Sam Neill. Câu chuyện của phim xoay quanh một tài xế xe tẩu thoát sau một vụ cướp, người được giao nhiệm vụ đặc biệt từ ông chủ tội phạm tàn nhẫn của mình. Anh ta phải lái xe chở một thành viên băng đảng đến một cuộc phục kích không ngờ, với mục đích ám sát. Trong suốt hành trình đầy gian nan, tài xế phải đối mặt và chiến đấu với lương tâm của mình, khi biết rằng anh ta đang dẫn đến cái chết của người khác.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Barry Pepper","avatar":""},{"name":"Jamie Costa","avatar":""},{"name":"Liam McIntyre","avatar":""},{"name":"Rachel Griffiths","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Zachary Garred","avatar":""},{"name":"Alex Fleri","avatar":""},{"name":"Marcus Johnson","avatar":""},{"name":"Josemily Royle","avatar":""},{"name":"Allison Frances Boyd","avatar":""},{"name":"Harrison Irvin","avatar":""},{"name":"Thomas Pitts","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324252);
