INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dua-han-toi-day', 'Đưa Hắn Tới Đây', 'Bring Him to Me', 'đưa hắn tới đây bring him to me barry pepper jamie costa liam mcintyre rachel griffiths sam neill zachary garred alex fleri marcus johnson josemily royle allison frances boyd harrison irvin thomas pitts ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-giao-em-la-so-1', 'Cô Giáo Em Là Số 1', 'Brave Citizen', 'https://phimimg.com/upload/vod/20240509-1/e4c9bb8595382de6c69c440131158d0a.jpg', 'https://phimimg.com/upload/vod/20240509-1/8df0536efaf30c7425f5dc12b44f1a30.jpg', '<p>Si-min (do Shin Hae-sun thủ vai) là một võ sĩ quyền anh đầy triển vọng nhưng đã từ bỏ quyền thi đấu tại kỳ Thế vận hội Olympic để lấy tiền trả nợ cho cha. Từ đó, Si-min cũng nhận ra rằng, cuộc sống vốn không công bằng và “công lý không thể mài ra cơm”. Si-min gạt phăng giấc mơ trở thành võ sĩ quyền anh và quyết tâm trở thành giáo viên, với mong muốn về một cuộc sống ổn định hơn. Cô trở thành giáo viên hợp đồng của một trường trung học có tiếng cùng mục tiêu trở thành giáo viên chính thức ở đây. Để có thể nhanh chóng hoàn thành nguyện vọng, cô đã nỗ lực kìm nén cái tôi xuống đáy, luôn mỉm cười cho qua, bất chấp mọi tình huống trớ trêu xảy đến với mình. Tuy nhiên, Su-gang (do Lee Jun-young thủ vai) - kẻ cầm đầu của một băng đảng quậy phá, chuyên đi bắt nạt và hành hạ người yếu thế đã phá vỡ quy tắc của Si-min. Không thể chịu đựng được những hành vi bạo lực học đường của Su-gang, Si-min đeo lên một chiếc mặt nạ mèo và dạy cho tên côn đồ một bài học đáng nhớ.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Shin Hye-sun","avatar":""},{"name":"Lee Jun-young","avatar":""},{"name":"Park Jung-woo","avatar":""},{"name":"Park Hyeok-kwon","avatar":""},{"name":"Cha Chung-hwa","avatar":""},{"name":"Lee Chan-hyung","avatar":""},{"name":"Bae Hyeon-jun","avatar":""},{"name":"Cha Woo-min","avatar":""},{"name":"Kim Sang-woo","avatar":""},{"name":"Lee Tae-hee","avatar":""},{"name":"Lee Tae-gyun","avatar":""},{"name":"Kang Anna","avatar":""},{"name":"Kang Na-ru