INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sayen-bao-thu', 'Sayen: Báo Thù', 'Sayen', 'https://phimimg.com/upload/vod/20240426-1/30165546aeab72cca55867436d338416.jpg', 'https://phimimg.com/upload/vod/20240426-1/6cb6367c6b73b29c95f7616f59fdc3b3.jpg', '<p>Cô nàng Sayen đang săn lùng những kẻ đã sát hại bà của cô. Sử dụng sự đào tạo và kiến thức về tự nhiên của mình, cô ấy có thể lật ngược tình thế khi biết được âm mưu từ một tập đoàn đang đe dọa vùng đất tổ tiên của người dân cô ấy.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rallén Montenegro","avatar":""},{"name":"Arón Piper","avatar":""},{"name":"Enrique Arce","avatar":""},{"name":"Roberto García Ruiz","avatar":""},{"name":"Loreto Aravena","avatar":""},{"name":"Alejandro Trejo","avatar":""},{"name":"Eduardo Paxeco","avatar":""},{"name":"Camilo Arancibia","avatar":""},{"name":"Teresa Ramos","avatar":""},{"name":"Roberto Cayuqueo","avatar":""},{"name":"Antonia Méndez","avatar":""},{"name":"Ramón González","avatar":""},{"name":"Claudio Troncoso","avatar":""},{"name":"Álvaro Espinoza","avatar":""},{"name":"Matteo Sepúlveda","avatar":""},{"name":"Matia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324252);
