INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-tien-sinh-tu-tren-troi-roi-xuong', 'Sở Tiên Sinh Từ Trên Trời Rơi Xuống', 'Hi! My Mr. Right', 'https://phimimg.com/upload/vod/20240423-1/6bff6f25d442958b10dcd9e3df3f4880.jpg', 'https://phimimg.com/upload/vod/20240423-1/884f45fe5216034f1f1810010f4b4f62.jpg', '<p>Mẫn Mẫn lanh lợi tinh nghịch từ nhỏ, dựa vào tài ăn nói của mình để lừa gạt mọi người. Tuy nhiên, vào một lần sơ ý, bạn trai do Mẫn Mẫn bịa ra bất ngờ từ trên trời rơi xuống, đó chính là Sở Man. Sự xuất hiện của anh đã phá vỡ cuộc sống yên bình của Mẫn Mẫn, khiến cô vô cùng hối hận. Nhưng cô thực sự không kiềm chế được mà đem lòng yêu người bạn trai hư cấu này. Sau khi biết được sự thật, Sở Man vẫn quyết định giúp Mẫn Mẫn quay trở về thế giới hiện thực, mặc dù điều này có thể đồng nghĩa với việc cuối cùng hai người sẽ phải chia xa.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Meichen","avatar":""},{"name":"Li Peien","avatar":""},{"name":"Huang Jincheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
