INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-xa-4-the-gioi-that-lac', 'Đại Xà 4: Thế Giới Thất Lạc', 'Snake 4: The Lost World', 'https://phimimg.com/upload/vod/20240502-1/1e791470e34ed5b1c1d3d2c90f85cea1.jpg', 'https://phimimg.com/upload/vod/20240502-1/a2ba24509ce0ccce8aea2c28d026efc1.jpg', '<p>Sự thất bại trong kinh doanh của Hao Ren và sự ra đi của mẹ anh đã dập tắt hy vọng cuối cùng của anh. Trong cơn tuyệt vọng, anh lên máy bay đi nước ngoài. Tuy nhiên, trong quá trình hành trình, máy bay gặp phải một cơn giông lớn, sét đánh trúng động cơ máy bay. Trong hoàn cảnh khốn cùng này, Hao Ren nghĩ đến chuỗi bất hạnh của mình nên đã cố tình không đeo mặt nạ dưỡng khí, mong gây tai nạn để được trả tiền bảo hiểm, để lại một khoản tiền trang trải cuộc sống cho anh trai. Một vùng biển bí ẩn, một hòn đảo hoang không tên, mảnh vỡ của chiếc máy bay bị vỡ và tiếng than khóc của các nạn nhân đã phá vỡ sự im lặng trước đây của hòn đảo. Hác Nhân tỉnh lại, phát hiện mình đang ở trong một khu rừng nguyên sinh rậm rạp. Anh đứng dậy, tìm kiếm những hành khách còn sống sót khác, tất cả đều đầy vết thương và tinh thần run rẩy. Dần hồi phục sau trải nghiệm tai nạn máy bay gần đây, họ quyết định đi sang phía bên kia đảo hoang để tìm kiếm buồng lái máy bay, hy vọng liên lạc được với đội cứu hộ thông qua máy phát sóng vô tuyến</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jampa Tseten","avatar":""},{"name":"Yusi Chen","avatar":""},{"name":"Zhang Haoran","avatar":""},{"name":"Zhu Haijun","avatar":""},{"name":"Yue Yueli","avatar":""},{"name":"Yanjing Shi","avatar":""},{"name":"Zhao Wang","avatar":""},{"name":"Zhang Baiqiao","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324252);
