INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-thang-may', 'Trò Chơi Thang Máy', 'Elevator Game', 'https://phimimg.com/upload/vod/20230916-1/810e6ae0ea77752a257baa5181ab23f1.jpg', 'https://phimimg.com/upload/vod/20230916-1/a2d74e6dfc8f45368e9606176dbc5b70.jpg', '<p>Theo chân cậu thiếu niên vụng về xã hội Ryan, người phát hiện ra rằng vào cái đêm em gái cậu biến mất, cô đã chơi &#39;Trò chơi thang máy&#39; - một nghi lễ được tiến hành trong thang máy trong đó người chơi cố gắng du hành đến một không gian khác bằng cách sử dụng một bộ quy tắc có thể tìm thấy trên mạng. Bỏ qua những lời cảnh báo, anh quyết tâm đi theo và tìm thấy cô.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Megan Best","avatar":""},{"name":"Adam Hurtig","avatar":""},{"name":"Gino Anania","avatar":""},{"name":"Madison MacIsaac","avatar":""},{"name":"Nazariy Demkowicz","avatar":""},{"name":"Bradley Sawatzky","avatar":""},{"name":"Liam Stewart-Kanigan","avatar":""},{"name":"Verity Marks","avatar":""},{"name":"Alec Carlos","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324252);
