INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoa-thuan-cua-quy', 'Thỏa Thuận Của Quỷ', 'The Devil''s Deal', 'https://phimimg.com/upload/vod/20240428-1/3f33547aef95b96c6b3eb0209e64199e.jpg', 'https://phimimg.com/upload/vod/20240428-1/8f3b7de0716f2a5f3ecc709e504cad59.jpg', '<p>Hae-woong, một ứng cử viên hội đồng, bị loại khỏi cuộc tranh cử vì anh ta trở thành cái gai trong mắt của một ông trùm địa phương, Soon-tae. Bị săn đuổi bởi những kẻ cho vay nặng lãi, do vỡ nợ trong chiến dịch tranh cử, anh quyết định nhúng tay vào.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Jin-woong","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Kim Moo-yul","avatar":""},{"name":"Won Hyun-jun","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Kim Yoon-sung","avatar":""},{"name":"Park Se-jin","avatar":""},{"name":"Son Yeo-eun","avatar":""},{"name":"Lee Sang-won","avatar":""},{"name":"Park Jeong-pyo","avatar":""},{"name":"Park Dae-chul","avatar":""},{"name":"Heo Ji-won","avatar":""},{"name":"Han Gab-soo","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Choi Min-cheol","avatar":""},{"name":"Seo Young-sam","avatar":""},{"name":"Choi Dong-goo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324252);
