INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-xuan-seoul', 'Mùa Xuân Seoul', '12.12: The Day', 'https://phimimg.com/upload/vod/20240428-1/65da87dc23f4d4f879dabdf097296092.jpg', 'https://phimimg.com/upload/vod/20240428-1/17f9299613d17ea84c8cf9996039a87d.jpg', '<p>Vào tháng 12 năm 1979, Seoul đã phải trải qua một mùa đông đầy khắc nghiệt. Sau vụ ám sát Tổng thống Park Chung-hee, thiết quân luật đã được ban bố. Một cuộc đảo chính nổ ra bởi Chỉ huy An ninh Quốc phòng Chun Doo-gwang và nhóm sĩ quan riêng theo sau anh ta. Chỉ huy Phòng thủ Thủ đô Lee Tae-sin, một người lính cố chấp tin rằng quân đội không nên có hành động …</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hwang Jung-min","avatar":""},{"name":"Jung Woo-sung","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Park Hae-jun","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Jeong Dong-hwan","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"You Seong-joo","avatar":""},{"name":"Choi Byung-mo","avatar":""},{"name":"Park Hoon","avatar":""},{"name":"Lee Jae-yoon","avatar":""},{"name":"Kim Sung-oh","avatar":""},{"name":"Nam Yoon-ho","avatar":""},{"name":"Hong Seo-jun","avatar":""},{"name":"Ahn Se-ho","avatar":""},{"name":"Jung Hyung-suk","avatar":""},{"name":"Park Jeong-hak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324252);
