INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sayen-con-duong-kho-can', 'Sayen: Con Đường Khô Cằn', 'Sayen: Desert Road', 'https://phimimg.com/upload/vod/20240228-1/73a54e3b00c9a8c94c16a747226cdab6.jpg', 'https://phimimg.com/upload/vod/20240228-1/61df94102ef3e49c8acf738707759d05.jpg', '<p>Sayen đi theo con đường dẫn đến sa mạc Atacama hoang tàn đẹp như tranh vẽ. Ở đó, cô miễn cưỡng hợp tác với một cô gái trẻ Atacameño, Quimal, tìm cách xóa tên cha cô và cứu thị trấn của cô khỏi trở thành một vùng đất hoang khô cằn do việc sử dụng nước bóc lột của Acteon.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rallén Montenegro","avatar":""},{"name":"Enrique Arce","avatar":""},{"name":"Jorge López","avatar":""},{"name":"Katalina Sanchez","avatar":""},{"name":"Claudio Riveros","avatar":""},{"name":"Alfredo Castro","avatar":""},{"name":"Eyal Meyer","avatar":""},{"name":"Camilo Arancibia","avatar":""},{"name":"Carlos Briones","avatar":""},{"name":"Claudio Troncoso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324252);
