INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-chung-toi-la-hoan-hi-thien-doan', 'Xin Chào Chúng Tôi Là Hoan Hỉ Thiên Đoàn', 'The Shiny Group', 'https://phimimg.com/upload/vod/20240423-1/4db3c6bff4d183fb53049cd29435c056.jpg', 'https://phimimg.com/upload/vod/20240423-1/869569285299edffc4d845c842a5077e.jpg', '<p>Nước Hoan Hỉ tổ chức cuộc thi tuyển chọn nhạc sư cung đình, thần tượng nổi tiếng Vạn Tự nữ cải nam trang tham gia cuộc thi, gặp gỡ Đồ Thiên Châu - ám vệ nằm vùng để tìm kiếm nội gián, Kim Hâm Hâm - thiếu gia con nhà giàu. Trải qua bao chuyện dở khóc dở cười, Vạn Tự và Đồ Thiên Châu dần có tình cảm với nhau...</p>', 'Tập 20', 20, 'series', 'ongoing', 13, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Yi Jin","avatar":""},{"name":"Jin Wan Yu","avatar":""},{"name":"Yi Heng","avatar":""},{"name":"Nine Kornchid Boonsathitpakdee","avatar":""},{"name":"Wu Ya Lu","avatar":""},{"name":"Akezhuli Zhuguli","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324252);
