INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-vuot-sat', 'Móng Vuốt Sắt', 'The Iron Claw', 'https://phimimg.com/upload/vod/20240426-1/7a3e306b0aac2d692bc678ec209cdbb4.jpg', 'https://phimimg.com/upload/vod/20240426-1/ad78626c4f939e4a595287d27753f9fa.jpg', '<p>Câu chuyện có thật về anh em nhà Von Erich không thể tách rời, những người đã làm nên lịch sử trong thế giới đấu vật chuyên nghiệp đầy cạnh tranh khốc liệt vào đầu những năm 1980. Trải qua bi kịch và chiến thắng, dưới cái bóng của người cha và huấn luyện viên độc đoán, hai anh em tìm kiếm sự bất tử vượt trội trên sân khấu thể thao lớn nhất.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Zac Efron","avatar":""},{"name":"Jeremy Allen White","avatar":""},{"name":"Harris Dickinson","avatar":""},{"name":"Stanley Simons","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Maura Tierney","avatar":""},{"name":"Lily James","avatar":""},{"name":"Michael Harney","avatar":""},{"name":"Aaron Dean Eisenberg","avatar":""},{"name":"Kevin Anton","avatar":""},{"name":"Scott Innes","avatar":""},{"name":"Cazzey Louis Cereghino","avatar":""},{"name":"Maxwell Friedman","avatar":""},{"name":"Brady Pierce","avatar":""},{"name":"Ryan Nemeth","avatar":""},{"name":"Jim Gleason","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324252);
