INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mong-vuot-sat', 'Móng Vuốt Sắt', 'The Iron Claw', 'móng vuốt sắt the iron claw zac efron jeremy allen white harris dickinson stanley simons holt mccallany maura tierney lily james michael harney aaron dean eisenberg kevin anton scott innes cazzey louis cereghino maxwell friedman brady pierce ryan nemeth jim gleason c ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-anh-ay-va-co-ay', 'Bí Mật Của Anh Ấy Và Cô Ấy', 'His and Her Secrets', 'https://phimimg.com/upload/vod/20240426-1/74628c79ff33ebe0582c6ba97dd1b06b.jpg', 'https://phimimg.com/upload/vod/20240426-1/88833a4bb3a0546a1e47594886646061.jpg', '<p>Tô Mạn là một người phụ nữ của gia đình có vẻ có một cuộc sống hạnh phúc mỹ mãn, tình cờ phát hiện ra chồng mình Trịnh Văn Lương ngoại tình trong lúc anh ta đi tắm. Tô Mạn chịu đựng sự sỉ nhục khi bị phản bội để bảo vệ hôn nhân của mình, bắt đầu hành trình lập kế hoạch để tóm được kẻ thứ ba. Khi chân tướng tới gần, sự xoay chuyển giống như trong phim ập tới cuộc sống của cô. Chồng cùng giáo viên dương cầm của con gái, Diệp Tinh ngụy tạo bằng chứng cô ngoại tình, ngược lại đuổi cô ra khỏi nhà. Để đoạt lại quyền nuôi dưỡng con gái, Tô Mạn bỏ lại tất cả mọi chuyện đau lòng, cùng tiểu tam chung tay báo thù chồng cũ, xây dựng lại cuộc sống sau khi ly hôn. Lại không ngờ rằng chàng trai trẻ Diệp Tinh từng hãm hại cô, Diệp Tinh, để bù đắp tội lỗi mà lần nữa xông vào cuộc sống của cô, và mang cho cô cảm giác của tình yêu mất đi đã lâu. Vào lúc Tô Mạn đang khó khăn trong việc lựa chọn giữa tình yêu và con gái, một âm mưu khác được hé lộ. Diệp Tinh với vẻ ngoài ngây thơ lại âm mưu với tiểu tam để bòn rút tài sản của chồng cũ, cuộc hôn nhân của họ bị đổ vỡ chính là một phần trong kế hoạch của hai người. Nhưng tất cả, cũng chỉ là một góc nhỏ. Hai vợ chồng họ bị cuốn vào vòng xoáy báo thù không thể thoát thân, sẽ là liều chết phản kháng hay là thỏa hiệp rồi tự tìm đường sống riêng, tất cả đều do cô quyết định...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Muchen Zhang","avatar":""},{"name":"Qiu Dingjie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324252);
