INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-mat-cua-anh-ay-va-co-ay', 'Bí Mật Của Anh Ấy Và Cô Ấy', 'His and Her Secrets', 'bí mật của anh ấy và cô ấy his and her secrets muchen zhang qiu dingjie ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('beyond-the-star-con-duong-tinh-yeu-chinh-phuc-vi-sao', 'Beyond The Star: Con Đường Tình Yêu Chinh Phục Vì Sao', 'Beyond the Star', 'https://phimimg.com/upload/vod/20240426-1/a3699c07311de23127b0fd9523957db5.jpg', 'https://phimimg.com/upload/vod/20240426-1/c86f0dff56349f86f5358381bac7f43f.jpg', '<p>Kể về một dự án kết hợp giữa tuổi trẻ và ước mơ. Khi các công ty lớn như &quot;KJ Agency&quot; muốn thực hiện ước mơ của mình bằng cách sản xuất hàng loạt dự án lớn để tiếp tục tạo ra những siêu sao. Vì vậy, những diễn viên, nghệ sĩ xuất sắc nhất đã được tập trung vào trại huấn luyện và chỉ có 8 người được chọn. Cạnh tranh nội bộ bắt đầu. Bằng chứng về tình yêu, tình bạn, liệu họ có thành công? Công ty nổi tiếng &quot;KJ Agency&quot; có kế hoạch sản xuất một bộ phim truyền hình dài tập, công ty quy tụ những người trẻ có ước mơ tham gia trại huấn luyện trở thành nghệ sĩ, diễn viên. Tám thực tập sinh sẽ được chọn để trở thành siêu sao.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chanwut Kwanmongkolcharoen","avatar":""},{"name":"Louis Kittawat Chaodee","avatar":""},{"name":"Pan Jirachot Chotticomporn","avatar":""},{"name":"Plai Chattrin Chotticomporn","avatar":""},{"name":"Nanthakorn Sringenthap","avatar":""},{"name":"Woraphon Charoensuk","avatar":""},{"name":"Natthapat Meesuk","avatar":""},{"name":"Beer Rapeewish Sangiamwong","avatar":""},{"name":"Focus Poonyavee Ekpankul","avatar":""},{"name":"Willie Arawill Jartonk","avatar":""},{"name":"Gun S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
