INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('unforgotten-night-dem-kho-quen', 'Unforgotten Night: Đêm Khó Quên', 'Unforgotten Night', 'https://phimimg.com/upload/vod/20240426-1/8f46793d2a7f7a9c24c78ce7c09fa039.jpg', 'https://phimimg.com/upload/vod/20240426-1/598442118bfe4f42d1f5eb1e4a545634.jpg', '<p>Bộ phim kể về câu chuyện của một ông trùm băng đảng gặp một cậu bé buồn bã. Kim cần người ôm anh một đêm. Đây là đêm duy nhất mà bạn biết mình thực sự muốn gì. Đây cũng là đêm duy nhất mà trùm xã hội đen “Kamol” không muốn Kim thuộc về ai; Kim, một nhân viên văn phòng 25 tuổi, đã yêu tiền bối rất lâu. Để quên đi anh ấy và tiếp tục cuộc sống của mình, anh quyết định tình một đêm với một người lạ mà anh gặp trong quán bar. Điều anh không biết là người xa lạ này sẽ bắt đầu thích anh đến mức không thể quay lại; Kamol một tay xã hội đen 30 tuổi, có một số nhu cầu đặc biệt trên giường nên liên tục thay đổi bạn tình nhưng không ai có thể thỏa mãn. Một đêm nọ, anh gặp Kim, người đáp ứng nhu cầu của anh một cách hoàn hảo. Sau đó Kamol quyết định biến người đàn ông này thành của riêng mình và bắt đầu theo đuổi anh ta.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Phusanu Wongsavanischakorn","avatar":""},{"name":"Ton Saran Anantasetthakul","avatar":""},{"name":"Peat Suchanon Chueluecha","avatar":""},{"name":"Thapanawat Kaewbumrung","avatar":""},{"name":"Tong Supanut Sudjinda","avatar":""},{"name":"Tan Tanchanit Limsilatham","avatar":""},{"name":"Ku Deachit Daosaengpetch","avatar":""},{"name":"Areeya Pholphutrakul","avatar":""},{"name":"Sarunyu Prachakrit","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
