INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('unforgotten-night-dem-kho-quen', 'Unforgotten Night: Đêm Khó Quên', 'Unforgotten Night', 'unforgotten night: đêm khó quên unforgotten night phusanu wongsavanischakorn ton saran anantasetthakul peat suchanon chueluecha thapanawat kaewbumrung tong supanut sudjinda tan tanchanit limsilatham ku deachit daosaengpetch areeya pholphutrakul sarunyu prachakrit ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-khe-ky', 'Hoa Khê Ký', 'Love is an Accident', 'https://phimimg.com/upload/vod/20240426-1/732d768abeac143a0a0663b335274f4e.jpg', 'https://phimimg.com/upload/vod/20240426-1/46efdcc9a4533af687c20128eeb69fc2.jpg', '<p>Hoa Khê Ký là một bộ phim cổ trang ngọt ngào kể về cô nàng nghịch ngợm Lý Sơ Nguyệt vô tình xuyên không từ thời hiện đại tới Vân Uất sơn trang, bị ép phối hợp với thiếu trang chủ An Cảnh Siêu, giả làm vị hôn thê để che dấu tai mắt. Hai người liên thủ ứng phó với những nguy cơ của sơn trang và dần nảy sinh tình cảm đồng thời kẻ đứng sau mọi chuyện cũng dần hé lộ.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xing Fei","avatar":""},{"name":"Xu Kaicheng","avatar":""},{"name":"Fangzhou Xu","avatar":""},{"name":"Yang Gen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324253);
