INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-khe-ky', 'Hoa Khê Ký', 'Love is an Accident', 'hoa khê ký love is an accident xing fei xu kaicheng fangzhou xu yang gen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-bao-tinh-yeu', 'Dự Báo Tình Yêu', 'A Breeze of Love', 'https://phimimg.com/upload/vod/20240426-1/18cd55900364442d0df9fc3844e23100.jpg', 'https://phimimg.com/upload/vod/20240426-1/b57506b7bea37d1a5d85e85e699debcb.jpg', '<p>Do-hyun, đội trưởng đội bóng rổ, đang chuẩn bị cho giải vô địch bóng rổ. Trong trận đấu 5V5, khi một đồng đội bị thương và còn một vị trí trống, Hye-in, quản lý đội, sẽ dẫn một người có thể hình khỏe mạnh đến. Chàng trai mà Hye-in dẫn theo là Dong-wook ,mối tình đầu không có kết quả của Do-hyun... 5 năm trước, Dong-wook và Do-hyun học cùng trường trung học. Dong-wook bị chứng mất ngủ kinh niên mỗi đêm và tình trạng trở nên tồi tệ hơn khi thời tiết xấu. Một ngày nọ, trong những ngày đau khổ ấy, anh tình cờ chìm vào giấc ngủ sâu bên cạnh Do-hyun. Đó là cách Do-hyun trở thành nơi trú ẩn duy nhất cho Dong-wook. Hai người ở cùng nhau trong phòng tập, dần trở nên thân thiết hơn, cuối cùng họ hôn nhau. Tuy nhiên, do công việc kinh doanh của bố nên Dong-wook phải chuyển trường. Cậu không thể thổ lộ tình cảm của mình với Do-hyun sau khi chứng kiến Do-hyun chơi đùa với bạn cùng lớp nên đã bỏ đi, gây ra nỗi đau vô cùng lớn Do-hyun. Mối quan hệ của họ, bắt đầu bằng mối tình đầu và kết thúc trong hiểu lầm, lại tiếp tục sau khi đối mặt trong khuôn viên trường. Do-hyun phản đối ý định để Dong-wook tham gia trận đấu, nhưng anh không còn lựa chọn nào khác ngoài việc phải chơi cùng cậu trong trận đấu sắp tới. Họ cùng nhau đánh cược. Dong-wook dẫn dắt đội giành chiến thắng và cậu chính thức gia nhập câu lạc bộ bóng rổ. Sau khi thắng cược, Dong-wook đề nghị sống chung với Do-hyun, và cuối cùng kết quả như Dong-wook mong muốn...! Do-hyun, người rung động trước sự thẳng thắn của Dongwook, và Dong-wook, người chỉ có thể chìm vào giấc ngủ sâu khi ở bên Do-hyun, người mất ngủ vào ban đêm khi họ ở bên nhau. Liệu họ có thể hàn gắn lại mối quan hệ đã rạn nứt của mình?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Jung-yu","avatar":""},{"name":"Woo Ji-han","avatar":""},{"name":"Kim Hyun-jae","avatar":""},{"name":"Lee Seo-bin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
