INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('du-bao-tinh-yeu', 'Dự Báo Tình Yêu', 'A Breeze of Love', 'dự báo tình yêu a breeze of love shin jung-yu woo ji-han kim hyun-jae lee seo-bin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-nien', 'Thục Niên', 'In Later Years', 'https://phimimg.com/upload/vod/20240426-1/ba6c7fb72bf5bdc52b30d6775c5309c9.jpg', 'https://phimimg.com/upload/vod/20240426-1/e0f09406aa7166654ba03604138f90e7.jpg', '<p>Cuộc sống của bà Trương Xuân Mai trong mắt người đời quả thật là đáng mơ ước: con trai đậu trường cấp ba với thành tích ưu tú, chồng là giáo sư hướng dẫn, đạt tới đỉnh cao trong sự nghiệp, bản thân bà lại là phó tổng biên tập tạp chí đang được đề đạt thăng chức. Có nhà, có xe, có sổ tiết kiệm. Nhưng thực tế cay đắng, mà cay đắng này chỉ có một mình Xuân Mai nếm trải. Giai đoạn mãn tiền không báo mà ập tới, còn kéo theo biết bao nhiêu thứ khủng hoảng, Vĩ Cường chồng bà thì lại mất tích. Xuân Mai lần theo từng đầu mối nhỏ nhặt mà đi đến nhận định rằng Vĩ Cường đã ngoại tình. Đến khi cứ ngờ Vĩ Cường quay đầu là bờ trở về nhà, lại đề nghị ly hôn với Xuân Mai. Cuộc khủng hoảng tuổi trung niên này đâu chỉ có thế, khó khăn cứ tầng tầng lớp lớp đổ ập lên đầu bà, bà bắt đầu suy nghĩ làm thế nào để cân bằng công việc và gia đình dưới áp lực của cuộc sống, cũng như làm sao để bình tĩnh đối diện với tuổi già sắp tới.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hao Lei","avatar":""},{"name":"Wang Ou","avatar":""},{"name":"Tang Yixin","avatar":""},{"name":"Song Dandan","avatar":""},{"name":"Liu Yijun","avatar":""},{"name":"Wang Yanlin","avatar":""},{"name":"Guoqiang Zhang","avatar":""},{"name":"Cao Cuifen","avatar":""},{"name":"Ma Boquan","avatar":""},{"name":"Pang Hanchen","avatar":""},{"name":"Zhou Ti Shun","avatar":""},{"name":"Akezhuli Zhuguli","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
