INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oppa-xa-hoi-den-than-yeu', 'Oppa Xã Hội Đen Thân Yêu', 'My Dear Gangster Oppa', 'https://phimimg.com/upload/vod/20240426-1/226c4900ccb55dc37bce858c117c3f9f.jpg', 'https://phimimg.com/upload/vod/20240426-1/f8e4011b7810786ec8bd04224e043a16.jpg', '<p>Phim chưa có nội dung.</p>', 'Full', 1, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Meen Nichakoon Khajornborirak","avatar":""},{"name":"Ping Krittanun Aunchananun","avatar":""},{"name":"Winner Tanatat Kunaneksin","avatar":""},{"name":"Setthanan Manunapichu","avatar":""},{"name":"Pinyadar Salinvarradar","avatar":""},{"name":"Yosita Wasuphiruk","avatar":""},{"name":"Tinn Boonpongthong","avatar":""},{"name":"Cosmo Milis","avatar":""},{"name":"Anon Saisangcharn","avatar":""},{"name":"Charupob Ruangsuwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
