INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('oppa-xa-hoi-den-than-yeu', 'Oppa Xã Hội Đen Thân Yêu', 'My Dear Gangster Oppa', 'oppa xã hội đen thân yêu my dear gangster oppa meen nichakoon khajornborirak ping krittanun aunchananun winner tanatat kunaneksin setthanan manunapichu pinyadar salinvarradar yosita wasuphiruk tinn boonpongthong cosmo milis anon saisangcharn charupob ruangsuwan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-trai', 'Tai Trái', 'The Left Ear', 'https://phimimg.com/upload/vod/20240426-1/e47fbfc70db5c872be9f2538ca864e83.jpg', 'https://phimimg.com/upload/vod/20240426-1/3bba6d55acca07e2ea40bedcc6535918.jpg', '<p>Lý Nhị đã âm thầm phải lòng anh trai học lớp trên, Hứa Dực, trong khi Hứa Dực lại bị Lê Ba Lạp - cô nàng cá tính và quyến rũ hấp dẫn. Lý Nhị, trong một cơ hội tình cờ, trở thành bạn thân với Ba Lạp và cũng biết được rằng Ba Lạp theo đuổi Hứa Dực liên quan đến bạn của Hứa Dực, Trương Dạng. Sau khi tốt nghiệp, các nhân vật chính đã chọn con đường riêng của mình: Trương Dạng đã đỗ vào Đại học Bắc Kinh; Hứa Dực đến Thượng Hải để học chuyên ngành;Nhất Tâm, người luôn mơ ước trở thành ngôi sao, bắt đầu hành trình chinh phục giấc mơ của mình; trong khi Ba Lạp thì bất ngờ qua đời, mãi mãi ở trong ký ức của mọi người. Trương Dạng luôn cảm thấy có lỗi với Hứa Dực, do đó liên tục giúp đỡ anh, hy vọng anh có thể phục hồi tinh thần. Năm thứ hai, Lý Nhị đỗ vào Thượng Hải, và có một mối quan hệ ngắn ngủi với Hứa Dực, nhưng sau cùng họ chia tay. Trương Dạng và Lý Nhị gặp nhau trong động đất ở Môn Xuyên và Thế vận hội, hai người trưởng thành và hiểu biết về nhau hơn, từ đó tình yêu giữa họ bắt đầu. Hứa Dực gặp gỡ cô gái học người tên là Hạ Mễ Mễ và cuối cùng anh ta hồi phục tinh thần. Theo thời gian trôi qua và qua những trải nghiệm, nhóm thanh niên cuối cùng đã cùng nhau bước qua tuổi thanh xuân hỗ trợ lẫn nhau, vượt qua những thử thách và khó khăn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zheng Kai","avatar":""},{"name":"Jiang Qin-yun","avatar":""},{"name":"Wu Xin","avatar":""},{"name":"Yvonne Yung Hung","avatar":""},{"name":"Ma Yinyin","avatar":""},{"name":"Yang Shuo","avatar":""},{"name":"Jacob Hwang","avatar":""},{"name":"Zhou You","avatar":""},{"name":"Zhu Yanmanzi","avatar":""},{"name":"Mi Mi","avatar":""},{"name":"Bai Liu-xi","avatar":""},{"name":"Peter Ho","avatar":""},{"name":"Amelie Xu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
