INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scavengers-reign', 'Scavengers Reign', 'Scavengers Reign', 'https://phimimg.com/upload/vod/20240425-1/63f21d07cabace6c820753bad6610175.jpg', 'https://phimimg.com/upload/vod/20240425-1/1ba504afa33edb7b17aea2e78c9860b0.jpg', '<p>Scavengers Reign xoay quanh câu chuyện đầy kịch tính về một phi hành đoàn bị mắc kẹt trên một hành tinh hoang dã và ngoạn mục sau khi tàu chở hàng của họ bị hư hỏng trong không gian sâu. Trong cuộc chiến sinh tồn khốc liệt này, nhóm phi hành đoàn phải đối mặt với những thách thức khó khăn từ thiên nhiên hung dữ và các sinh vật xanh lơ. Hành tinh này không chỉ xinh đẹp, mà còn nguy hiểm vô cùng, với cảnh quan hoang vu và ác liệt. Di chuyển trở thành nhiệm vụ gian nan khi rừng cây rậm rạp và sa mạc khắc nghiệt chờ đợi nhóm phi hành đoàn ở mỗi bước đi. Không chỉ có thiên nhiên là thử thách, nhóm còn phải đấu tranh với những băng nhóm người sống sót khác để giành lấy sự sống. Trong cuộc chiến sinh tồn căng thẳng này, tình bạn và lòng tin vào nhau là điều quan trọng để vượt qua mọi khó khăn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sunita Mani","avatar":""},{"name":"Wunmi Mosaku","avatar":""},{"name":"Alia Shawkat","avatar":""},{"name":"Bob Stephenson","avatar":""},{"name":"Ted Travelstead","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324253);
