INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-giai-dich-chu-mau', 'Tấn Giai Đích Chủ Mẫu', 'Wise Woman', 'https://phimimg.com/upload/vod/20240410-1/a2ea07cb95a17fd01a28566904b1e4a0.jpg', 'https://phimimg.com/upload/vod/20240410-1/52f0d57c5d9a31cd13d0492e1afac7e5.jpg', '<p>Tiết Vãn Nhi theo chủ nghĩa yêu đương tự do bị gia tộc chối bỏ, bị trưởng tỷ lừa gạt lợi dụng, nàng niết bàn sống lại, đấu trí đấu dũng với kẻ thù, đấu tranh với lễ giáo cổ hủ thời phong kiến. Sau bao sóng gió, người thương trở về, nàng cũng giành lại được mọi thứ thuộc về mình, chào đón cuộc sống mới.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324253);
