INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chang-linh-ngu-lam-phan-2-milady', 'Ba Chàng Lính Ngự Lâm - Phần 2: Milady', 'The Three Musketeers - Part II: Milady', 'https://phimimg.com/upload/vod/20240425-1/903d35a7609a0fcd2283a1c9e2d2a898.jpg', 'https://phimimg.com/upload/vod/20240425-1/755156761bd9e0c7759e4e3493ea440e.jpg', '<p>Tiếp theo phần 1, phần này kể về D&quot;Artagnan trong hành trình giải cứu Constance bị bắt cóc, lại tình cờ gặp Milady de Winter bí ẩn. Căng thẳng giữa người Công giáo và người Tin lành cuối cùng cũng leo thang khi nhà vua tuyên chiến - buộc bốn người lính ngự lâm phải tham chiến. Nhưng khi chiến tranh tiếp diễn, họ đều bị thử thách về thể chất, tinh thần và cảm xúc.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"François Civil","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Romain Duris","avatar":""},{"name":"Pio Marmaï","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Lyna Khoudri","avatar":""},{"name":"Louis Garrel","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Jacob Fortune-Lloyd","avatar":""},{"name":"Eric Ruf","avatar":""},{"name":"Marc Barbé","avatar":""},{"name":"Patrick Mille","avatar":""},{"name":"Julien Frison","avatar":""},{"name":"Ralph Amoussou","avatar":""},{"name":"Alexis Michalik","avatar":""},{"name":"Camille Rutherford","avatar":""},{"name":"Dominique Valadié","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
