INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-tien-vuong-phi', 'Thỏ Tiên Vương Phi', 'The Princess Is A Rabbit Fairy', 'https://phimimg.com/upload/vod/20240411-1/8aaf942b1de8f0bc4e6e7dc84bb2c79f.jpg', 'https://phimimg.com/upload/vod/20240405-1/bfa9b7e7408ff4f88c9d67918b0dc8b2.jpg', '<p>Để trả thù cho sư phụ của mình, tiểu thỏ tiên Bạch Tại Tại đã vô tình đột nhập vào Vương phủ và trở thành thị vệ của nhị hoàng tử Lưu Trường Ca. Trong quá trình ở bên nhau, cả hai dần dần từ quen biết trở thành yêu nhau. Lưu Trường Ca đã giúp Bạch Tại Tại trả thù cho vụ sát hại sư phụ của mình, và Bạch Tại Tại cũng giúp Lưu Trường Ca đánh bại Quốc sư Thẩm Dật và các hoàng tử khác trong triều đình đầy rẫy hiểm nguy.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Fu Yu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
