INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-am-tin-do', 'Quỷ Ám: Tín Đồ', 'The Exorcist: Believer', 'https://phimimg.com/upload/vod/20231018-1/541bd843c90f89495c81f0f22948af44.jpg', 'https://phimimg.com/upload/vod/20231018-1/f42d80a88bc5cf2aa5e7e523f9e857d6.jpg', '<p>Phần tiếp theo của bộ phim năm 1973 kể về một cô bé 12 tuổi bị một thực thể ma quỷ bí ẩn chiếm hữu, buộc mẹ cô phải tìm đến sự giúp đỡ của hai linh mục để cứu cô.</p>', 'Full', 1, 'single', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leslie Odom Jr.","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Lidya Jewett","avatar":""},{"name":"Olivia Marcum","avatar":""},{"name":"Jennifer Nettles","avatar":""},{"name":"Norbert Leo Butz","avatar":""},{"name":"Ellen Burstyn","avatar":""},{"name":"E.J. Bonilla","avatar":""},{"name":"Raphael Sbarge","avatar":""},{"name":"Antoni Corone","avatar":""},{"name":"Danny McCarthy","avatar":""},{"name":"Norah Murphy","avatar":""},{"name":"Chloe Traicos","avatar":""},{"name":"Chandu Kanuri","avatar":""},{"name":"Richard Carr III","avatar":""},{"name":"Okwui Okpokwasili","avatar":""},{"name":"Malena","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324253);
