INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-dong-hanh', 'Những Người Đồng Hành', 'Fellow Travelers', 'https://phimimg.com/upload/vod/20240419-1/78bcae49a0c01d02af7448918608f780.jpg', 'https://phimimg.com/upload/vod/20240419-1/a73b1f1ce646c5024d0a5bbdb27dfc0a.jpg', '<p>Trong suốt bốn thập kỷ bao gồm các cuộc biểu tình phản đối chiến tranh Việt Nam trong những năm 1960, các cuộc ăn chơi khoái lạc trong những năm 1970, và khủng hoảng &nbsp;bệnh AIDS trong những năm 1980, Hawk, Tim, Marcus, Lucy, và Frankie lần lượt chạm mặt nhau khi bọn họ đều phải đối mặt với những rào cản của bản thân và thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Bomer","avatar":""},{"name":"Jonathan Bailey","avatar":""},{"name":"Jelani Alladin","avatar":""},{"name":"Allison Williams","avatar":""},{"name":"Noah J. Ricketts","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Will Brill","avatar":""},{"name":"Chris Bauer","avatar":""},{"name":"Erin Neufer","avatar":""},{"name":"Matt Visser","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
