INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-hon', 'Cầu Hồn', 'The Bridge Curse: Ritual', 'https://phimimg.com/upload/vod/20240412-1/5ae1c4abf00ab2b89d01080c6e3a5c91.jpg', 'https://phimimg.com/upload/vod/20240412-1/4f3f60ba419289a08e26158e3dfc7117.jpg', '<p>Cầu Hồn bắt đầu trong bối cảnh kỳ lạ của những câu chuyện siêu nhiên được lưu hành trong trường. Các địa điểm chính của trường bao gồm thư viện, phòng tập nhảy và thang máy đều toát lên sự kinh dị về những điềm báo đen tối sẽ diễn ra. Điểm đặc biệt của phim là cách lồng ghép khéo léo 3 nghi thức tâm linh vào 1 trò chơi thực tế ảo: Trò chơi 4 góc; Trò chơi trốn tìm 1 người; và Trò chơi thang máy. Bộ phim là sự trỗi dậy của TRUYỀN THUYẾT KINH HOÀNG CÂY CẦU MA NỮ TẠI ĐÀI LOAN.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Đài Loan', 1, '[{"name":"Wang Yu-xuan","avatar":""},{"name":"JC Lin","avatar":""},{"name":"Patrick Shih","avatar":""},{"name":"Shawn Hu","avatar":""},{"name":"Tzu Hsuan Chan","avatar":""},{"name":"Wei-Lun Xi","avatar":""},{"name":"Boris Wang","avatar":""},{"name":"Linus Wang","avatar":""},{"name":"Summer Meng","avatar":""},{"name":"Vera Yen","avatar":""},{"name":"Ning Chang","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324253);
