INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chang-linh-ngu-lam-dartagnan', 'Ba Chàng Lính Ngự Lâm: D''Artagnan', 'The Three Musketeers - Part I: D''Artagnan', 'https://phimimg.com/upload/vod/20230920-1/61958757ed7e59268be48b5d55027b6d.jpg', 'https://phimimg.com/upload/vod/20230920-1/0bf677b4db963c0122144f1c4404fd02.jpg', '<p><span style="font-family: ">Artagnan đến Paris để cố gắng tìm kiếm những kẻ tấn công mình sau khi bị bỏ mặc cho đến chết, chuyện này dẫn anh đến một cuộc chiến thực sự mà tương lai của nước Pháp đang bị đe dọa, khiến anh buộc phải phối hợp với Athos, Porthos và Aramis, ba chàng lính ngự lâm của Nhà vua.</span></p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"François Civil","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Romain Duris","avatar":""},{"name":"Pio Marmaï","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Louis Garrel","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Lyna Khoudri","avatar":""},{"name":"Jacob Fortune-Lloyd","avatar":""},{"name":"Eric Ruf","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
