INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tee-yod-quy-an-tang', 'Tee Yod: Quỷ Ăn Tạng', 'Tee Yod - Death Whisperer', 'https://phimimg.com/upload/vod/20240410-1/645d1eebd1a936a060abe82e22f1785b.jpg', 'https://phimimg.com/upload/vod/20240410-1/274cd164bd736d1502e4031b45c5a1ed.jpg', '<p>Khi linh hồn khát máu nọ nhập vào một cô gái trẻ ở ngôi làng hẻo lánh, anh trai cô đi đầu trong nỗ lực trục xuất linh hồn đó trước khi cô bị cái ác lấn át.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Nadech Kugimiya","avatar":""},{"name":"Denise Jelilcha Kapaun","avatar":""},{"name":"Rattanawadee Wongtong","avatar":""},{"name":"Kajbhunditt Jaidee","avatar":""},{"name":"Peerakrit Phacharaboonyakiat","avatar":""},{"name":"Nutthacha Padovan","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Paramej Noiam","avatar":""},{"name":"Ong-art Cheamcharoenpornkul","avatar":""},{"name":"Jampar Saenprom","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324253);
