INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-an-dai-duong-phan-2', 'Thánh Ăn Đại Đường (Phần 2)', 'Gourmet in Tang Dynasty (Season 2)', 'https://phimimg.com/upload/vod/20240313-1/96606f1e1a818802ec01da9e85661c0e.jpg', 'https://phimimg.com/upload/vod/20240313-1/451837d7b3b787d5dd0cdfab8b67ef80.jpg', '<p>Nguyên Uyển Nhi lẻn vào thư viện Tân Tân Đông Phương của Đại Đường để tìm kiếm cuốn thiên thư chứa đựng bí mật tối thượng, và vô tình quen biết Tư Mã Thanh Dương. Trải qua nhiều lần hiểu lầm và hợp tác, sự lương thiện và lanh lợi của Nguyên Uyển Nhi dần dần đã lay động Tư Mã. Hai người dần nảy sinh tình cảm. Trong lúc không ngừng tìm kiếm, họ đã cùng nhau mở khóa những bí mật của thiên thư và có được tình yêu định mệnh của mình.&nbsp;</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
