INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-trao-doi-bi-mat', 'Nhật Ký Trao Đổi Bí Mật', 'Our Secret Diary', 'https://phimimg.com/upload/vod/20240410-1/a20a145f60b422b53015054c13ffcd1c.jpg', 'https://phimimg.com/upload/vod/20240410-1/f0fee8561fde04edefed7b22608b9454.jpg', '<p>Nozomi Kuroda đang học lớp 2 trung học phổ thông. Một ngày, cô tìm thấy một bức thư trong bàn học trong lớp. Bức thư chỉ có một từ thích được viết trên đó. Người đã viết bức thư là Jun Setoyama. Anh ấy ngẫu nhiên là cậu bạn phổ biến nhất ở trường trung học. Nozomi Kuroda cảm thấy xấu hổ, nhưng cuối cùng cô đã để lại một lời trả lời trong tủ giày ở trường. Đó là cách mà cuốn nhật ký trao đổi bí mật của họ bắt đầu. Nozomi Kuroda sớm nhận ra rằng người nhận bức thư đầu tiên là bạn thân của cô. Dù vậy, Nozomi Kuroda lại bị thu hút bởi Jun Setoyama, người thể hiện suy nghĩ và cảm xúc khác biệt so với cô. Cô không thể nói với anh ấy sự thật rằng người đang trao đổi tin nhắn là cô chứ không phải bạn thân của cô.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fumiya Takahashi","avatar":""},{"name":"Hiyori Sakurada","avatar":""},{"name":"Mizuki Kayashima","avatar":""},{"name":"Ryosuke Sota","avatar":""},{"name":"Nagisa Saito","avatar":""},{"name":"Mizuki Itagaki","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
