INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-chon', 'Lựa Chọn', 'Stand By Me', 'https://phimimg.com/upload/vod/20240405-1/71fecb3854ea4cf11d8ca3b1f5d78457.jpg', 'https://phimimg.com/upload/vod/20240405-1/e39fd850597e2d60c4a9b116aba0f10e.jpg', '<p>Năm 1936, Hoàng Vĩ Kiệt, một thành viên của tổ chức yêu nước, tình cờ gặp được doanh nhân yêu nước Phùng Quán Vũ khi đang làm nhiệm vụ. Hai người là bạn thân từ nhỏ, do hiểu lầm mà chia xa. Phùng Quán Vũ nhất mực yêu cầu Hoàng Vĩ Kiệt làm vệ sĩ cho mình. Dù thường xuyên xảy ra mâu thuẫn nhưng giữa những hoạn nạn liên tiếp xảy ra, hai con người với lý tưởng chính nghĩa đã chung tay sát cánh, anh dũng cống hiến hết mình cho sự nghiệp yêu nước.&nbsp;</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Deng Kai","avatar":""},{"name":"Wang Zuyi","avatar":""},{"name":"Ma Jiaying","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
