INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-noi-mat-tham-chi-nhan-duyen-kiep', 'Đại Nội Mật Thám Chi Nhân Duyên Kiếp', 'The Killing Romance', 'https://phimimg.com/upload/vod/20240405-1/d5b3080e78f9097ea8e712dd569d5874.jpg', 'https://phimimg.com/upload/vod/20240405-1/eb7f5de1d22de210834ec33fdab38604.jpg', '<p>Nguyệt Lão đệ nhất thiên hạ có dung mạo tuyệt đẹp và giọng nói tuyệt vời - Vô Cực công tử - cùng đệ nhất thiên kim mạnh mẽ dũng cảm Đường Tiểu Lộc bất ngờ gặp nhau tại hội Nhân Duyên rồi cùng định hôn ước. Đôi phu thê tình sâu nghĩa nặng cùng bắt tay giải quyết bí ẩn về thân phận, nhưng mọi thứ bề ngoài hóa ra lại chỉ là tầng tầng lớp lớp âm mưu của kẻ khác, hết màn kịch này đến màn kịch khác giữa hai người.</p>', 'Tập 18', 18, 'series', 'ongoing', 13, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Haodong Ma","avatar":""},{"name":"Xu Zhenzhen","avatar":""},{"name":"黄怀霆","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
