INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tay-chiu-troi-di-doi-truong-han', 'Bó Tay Chịu Trói Đi Đội Trưởng Hàn', 'Captain Han', 'https://phimimg.com/upload/vod/20240410-1/dc2250d02a2265ded3ef7b98ac873d6e.jpg', 'https://phimimg.com/upload/vod/20240410-1/17587f2db3ed11cf7bdcca673c8e42ed.jpg', '<p>Bộ phim kể về câu chuyện tình yêu chữa lành cho nhau giữa phóng viên Hứa Nam Nam và đội trưởng đội kiểm lâm Hàn Tịch Châu. Trong quá trình cả hai cùng nhau chiến đấu chống lại thành phần lâm tặc, phát hiện ra sự thật về việc mất trí nhớ của Hứa Nam Nam mười năm trước. Bằng những nỗ lực không ngừng nghỉ, cuối cùng Hứa Nam Nam đã đánh bại nỗi sợ hãi trong lòng, bảo vệ được khu rừng, cả hai cũng đã gặt hái được tình yêu và trưởng thành.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tim Huang","avatar":""},{"name":"Chen Siche","avatar":""},{"name":"Sun Xizhi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
