INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-sinh-ton-phan-1', 'Cuộc Chiến Sinh Tồn (Phần 1)', 'The Escape Of The Seven (Season 1)', 'https://phimimg.com/upload/vod/20240404-1/6407c535ae6a22d8f70307653122247c.jpg', 'https://phimimg.com/upload/vod/20240404-1/8a9b24ff9ad97321cb7551546ed7bec2.jpg', '<p>The Escape of the Seven thuộc thể loại tội phạm bí ẩn, gay cấn, đặc biệt khác với phần lớn dự án khác thường chú trọng vào cái thiện, phim lại tập trung vào nhân vật phản diện với những ham muốn xấu xa đáng sợ.

Bộ phim xoay quanh bảy người bị cuốn vào vụ án về sự biến mất đầy bí ẩn của một cô gái trẻ. Bảy người họ với hoàn cảnh xuất thân khác nhau cùng bị vướng vào vòng xoáy của sự dối trá, những cám dỗ và tham vọng đầy phức tạp, trói buộc họ với vụ án mất tích.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Uhm Ki-joon","avatar":""},{"name":"Hwang Jung-eum","avatar":""},{"name":"Lee Joon","avatar":""},{"name":"Lee Yu-bi","avatar":""},{"name":"Shin Eun-kyung","avatar":""},{"name":"Yoon Jong-hoon","avatar":""},{"name":"Jo Yoon-hee","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Yoon Tae-young","avatar":""},{"name":"Lee Jung-shin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
