INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-sat-nhan', 'Phòng Sát Nhân', 'The Kill Room', 'https://phimimg.com/upload/vod/20240404-1/7dc94e557a1bcba39434fd4135b52923.jpg', 'https://phimimg.com/upload/vod/20240404-1/e18d023707d565e72dbf6f0acaa62ee9.jpg', '<p>Bộ phim &quot;Phòng Sát Nhân&quot; kể về cuộc gặp gỡ tình cờ của nghệ sĩ thất bại June và tay sát thuê Vince. Ban đầu, Vince được ông trùm tội phạm Mr. X thuê giết người đàn ông tên Andre. Trong một tình huống bất ngờ, cả June và Vince đều dính líu đến cái chết của nạn nhân. Hiểu nhầm June là sát thủ thực sự, Mr. X ra lệnh cho Vince tiêu diệt cô. Tuy nhiên Vince dần yêu June và quyết giúp cô thoát khỏi tay ông trùm. Cả hai bắt đầu hợp tác, sử dụng kỹ năng của mình để biến kế hoạch thoát thân thành hiện thực. Tuy nhiên, ông trùm tội phạm đối thủ hung hãn đang rình rập phía sau...</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Uma Thurman","avatar":""},{"name":"Joe Manganiello","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Maya Hawke","avatar":""},{"name":"Debi Mazar","avatar":""},{"name":"Dree Hemingway","avatar":""},{"name":"Amy Keum","avatar":""},{"name":"Candy Buckley","avatar":""},{"name":"Larry Pine","avatar":""},{"name":"Jennifer Kim","avatar":""},{"name":"Matthew Maher","avatar":""},{"name":"Tom Pecinka","avatar":""},{"name":"Alexander Sokovikov","avatar":""},{"name":"Gionna Daddio","avatar":""},{"name":"Mike Doyle","avatar":""},{"name":"Leah McSweeney","avatar":""},{"name":"James Di Giacomo","avatar":""},{"name":"Alexi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324253);
