INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-toan-phong-sai-tien-don-thu-thiet-quan', 'Tiểu Toàn Phong Sài Tiến: Đơn Thư Thiết Quần', 'Gentle Warrior 1', 'https://phimimg.com/upload/vod/20240404-1/f2b8f3d19a3be4cde0f0098b8736e78d.jpg', 'https://phimimg.com/upload/vod/20240404-1/ca240f4d2df5a536f4220b74316b24db.jpg', '<p>Tiểu Toàn Phong Sài Tiến Đơn Thư Thiết Quần - Gentle Warrior 1 xoay quanh việc Thương Châu gặp đại hạn, tình hình cấp bách không thể trì hoãn được nữa, nhưng chi phủ Thương Châu là Lương Khôn lại nuốt trọn số ngân lượng cứu tế thiên tai. Tiểu Toàn Phong Sài Tiến dựng lên liên hoàn kế, vạch trần tội ác của Lương Khôn, cuối cùng đoạt lại được ngân lượng cứu tế cho bách tính Thương Châu.</p>', 'Full', 1, 'single', 'completed', 22, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Văn Tuyết","avatar":""},{"name":"Trương Bác Hào","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324253);
