INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-toan-phong-sai-tien-tram-hoa-thinh-menh', 'Tiểu Toàn Phong Sài Tiến: Trâm Hoa Thỉnh Mệnh', 'Gentle Warrior 3', 'https://phimimg.com/upload/vod/20240404-1/1894ac47ceda50dfe3873c9c9c479970.jpg', 'https://phimimg.com/upload/vod/20240404-1/f691e3cc7e5b8679630d86b2328a9590.jpg', '<p>Tiểu Toàn Phong Sài Tiến Trâm Hoa Thỉnh Mệnh - Gentle Warrior 3 xoay quanh việc Sài Tiến vừa lên Lương Sơn đã nhanh chóng ghi công lập nghiệp. Vì để điều tra Trần Kim Thạch - một quan viên trong triều từng kể về 1 sự việc có đúng với sự thực hay không, nên Sài Tiến đã thỉnh mệnh xuống núi vào kinh đô. Phát hiện ra tất cả chỉ là âm mưu của Cao Cầu, vì để cứu Trần Kim Thạch, Sài Tiến đã mượn trâm hoa và áo choàng lông đột nhập vào hoàng cung, thuận lợi đem vạn ngôn thư bỏ vào Duệ Tư Điện, cứu được Trần Kim Thạch.</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Văn Tuyết","avatar":""},{"name":"Trương Bác Hào","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324253);
