INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-toan-phong-sai-tien-kho-bau-truyen-the', 'Tiểu Toàn Phong Sài Tiến: Kho Báu Truyền Thế', 'Gentle Warrior 4', 'https://phimimg.com/upload/vod/20240404-1/665d1adb1843c39d8cb8e761f2bd8527.jpg', 'https://phimimg.com/upload/vod/20240404-1/7825b9bcab55ac61a7901aa3dd655af7.jpg', '<p>Tiểu Toàn Phong Sài Tiến Kho Báu Truyền Thế - Gentle Warrior 4 kể về việc Tiểu Toàn Phong Sài Tiến dẫn theo con gái là Lương Huệ Anh mai danh ẩn tính sống dưới chân núi Lương Sơn nhưng lại bị Dương Hao phát hiện ra thân phận thật. Dương Hao cùng Thang huyện lệnh hợp mưu tính kế để lấy cho được bảo tàng, cuối cùng do lợi ích cá nhân mà Dương Hao giết chết Thang huyện lệnh, để che giấu tội ác tiếp tục mưu sát Sài Tiến, cuối cùng bị Thi Lương Thành và Sài Tiến giết chết.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Văn Tuyết","avatar":""},{"name":"Trương Bác Hào","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324253);
