INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-toan-phong-sai-tien-ep-len-luong-son', 'Tiểu Toàn Phong Sài Tiến: Ép Lên Lương Sơn', 'Gentle Warrior 2', 'https://phimimg.com/upload/vod/20240404-1/f4cfb9fb4e88ed4328d8e657f5b92b68.jpg', 'https://phimimg.com/upload/vod/20240404-1/6ad578c034ca859b1c8597d950079ec0.jpg', '<p>Tiểu Toàn Phong Sài Tiến Ép Lên Liên Sơn - Gentle Warrior 2 xoay quanh việc cửu cửu của tri phủ châu Cao Đường Cao Liêm là Ân Thiên Tứ chiếm đoạt trang viên của thúc phụ Sài Tiến là Sài Hoàng Thành. Dưới âm mưu của bọn họ, khế ước Đan Thư Thiết bị hủy, Sài Hoàng Thành mất mạng, Sài Tiến bị gán tội mưu phản nên bị bắt nhốt vào tử lao chờ hành hình. Cuối cùng Hắc Toàn Phong Lý Quỳ dẫn theo đội quân hùng mạnh từ Lương Sơn đến Cao Đường, cứu Sài Tiến thoát khỏi đó và cùng về Lương Sơn.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Văn Tuyết","avatar":""},{"name":"Trương Bác Hào","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324253);
