INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-nhay-khuynh-thanh', 'Điệu Nhảy Khuynh Thành', 'Night Beauties', 'https://phimimg.com/upload/vod/20240324-1/522e9325b5f9d5ba006924e29e8bc8ea.jpg', 'https://phimimg.com/upload/vod/20240324-1/efc3113e045d8b95ac3d14affac0db8a.jpg', '<p>“Điệu nhảy khuynh thành” đánh dấu màn tái xuất của nữ diễn viên TVB vang bóng một thời - Trần Pháp Dung.&nbsp;Thập niên 80, 90 của thế kỷ trước, kinh tế Hồng Kông “cất cánh”, theo đó, những địa điểm vui chơi, giải trí cũng mọc lên như nấm, nổi bật là hộp đêm Vạn Quốc Thành.&nbsp;Nói tới Vạn Quốc Thành thì người đầu tiên phải nhắc đến là má mì Sa Tịnh Hà (Trần Pháp Dung đóng). Hà rất “mát tay” trong tuyển chọn và đào tạo vũ nữ. Hai đào cưng của cô là Văn Nhã Luân (Thái Khiết đóng) và Giang Khiết Nhi (Trần Tinh Dư đóng) chính là hai “át chủ bài”, giúp hộp đêm ngày càng ăn nên làm ra, biến nơi đây thành lựa chọn hàng đầu của những kẻ lắm tiền nhiều của, “đốt tiền” không tiếc tay.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 12, 2023, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Monica Chan","avatar":""},{"name":"Jacky Cai","avatar":""},{"name":"Elaine Yiu","avatar":""},{"name":"Connie Man","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
