INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tore', 'Tore', 'Tore', 'https://phimimg.com/upload/vod/20240324-1/42c57628dc6ade7bb32b4037bb9795cf.jpg', 'https://phimimg.com/upload/vod/20240324-1/d8bf97892bb4ff73558a9c448b5b4a8f.jpg', '<p>Nông nổi và không có mục đích, một thanh niên 27 tuổi lao vào thế giới vô định của tình dục, ma túy và tự khám phá sau cái chết của người bạn thân.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2023, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"William Spetz","avatar":""},{"name":"Sanna Sundqvist","avatar":""},{"name":"Hannes Fohlin","avatar":""},{"name":"Lotta Tejle","avatar":""},{"name":"Per Svensson","avatar":""},{"name":"Victor Iván","avatar":""},{"name":"Peter Haber","avatar":""},{"name":"Carlos Romero Cruz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
