INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sebastian-fitzeks-die-therapie', 'Sebastian Fitzeks Die Therapie', 'Sebastian Fitzek''s Therapy', 'https://phimimg.com/upload/vod/20240324-1/38f29b084eed7c3e367e8b621b395d06.jpg', 'https://phimimg.com/upload/vod/20240324-1/8ac88220eff78c64a7113bdbee44dad5.jpg', '<p>Không có nhân chứng, không dấu vết và không xác chết, Josy, cô con gái 13 tuổi của bác sĩ tâm thần nổi tiếng Viktor Larenz, đã biến mất trong một hoàn cảnh không rõ nguyên nhân. Hai năm sau, một người phụ nữ bí ẩn xuất hiện. Cô buộc Viktor phải đối mặt với sự mất tích của con gái mình và đẩy anh đến giới hạn tâm lý của mình.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Stephan Kampwirth","avatar":""},{"name":"Helena Zengel","avatar":""},{"name":"Trystan Pütter","avatar":""},{"name":"Emma Bading","avatar":""},{"name":"Andrea Osvárt","avatar":""},{"name":"Axel Milberg","avatar":""},{"name":"Paula Kober","avatar":""},{"name":"Martin Feifel","avatar":""},{"name":"Peter Miklusz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
