INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sebastian-fitzeks-die-therapie', 'Sebastian Fitzeks Die Therapie', 'Sebastian Fitzek''s Therapy', 'sebastian fitzeks die therapie sebastian fitzek''s therapy stephan kampwirth helena zengel trystan pütter emma bading andrea osvárt axel milberg paula kober martin feifel peter miklusz ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-cung-cua-toi', 'Chó Cưng Của Tôi', 'My Pet My Angel', 'https://phimimg.com/upload/vod/20240324-1/040e2667c8302917991c513e8bbd3c76.jpg', 'https://phimimg.com/upload/vod/20240324-1/0e0ea36c48a161d6edd75b3b01c773ff.jpg', '<p>Bác sĩ thú y Kim Huệ Đình (do Lâm Hạ Vy đóng) là một người tin vào khoa học, làm việc theo quy củ. Tính cách cứng nhắc khiến cô khó hòa nhập ở nơi làm việc mới, đặc biệt, cô mau chóng kết “oan gia” với anh chàng đồng nghiệp, cũng là hàng xóm, tên Uông Thanh Nhân (do Châu Gia Lạc đóng). Nhân có biệt tài “độc tâm” thú cưng, chữa bệnh dựa vào sự phỏng đoán tâm lý con vật. Trong mắt Đình, cách chữa trị của Nhân là gạt người. Ngược lại, Nhân thì cho rằng Đình không linh hoạt, thân là thú y, lại không chăm sóc tốt chú chó Donut của mình. Vì thế, hai người thường xuyên xảy ra hiềm khích.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2023, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Rosina Lin","avatar":""},{"name":"Kalok Chow","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Hugo Wong","avatar":""},{"name":"Tsui Wing","avatar":""},{"name":"Toby Chan","avatar":""},{"name":"Roxanne Ho Pui-Ga","avatar":""},{"name":"Man Yeung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
