INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-nu-si-tinh', 'Ma Nữ Si Tình', 'Unchained Medley', 'https://phimimg.com/upload/vod/20240324-1/74a2a70af669cebeca670ee7be9b5d40.jpg', 'https://phimimg.com/upload/vod/20240324-1/9027d3f8e6e408f8f13dc96998be6d41.jpg', '<p>Nhà soạn nhạc nổi tiếng Đinh Nhất Tuấn (do Trương Chấn Lãng đóng) bị Thiên Vương Eric kiện sao chép nhạc. Tuấn bị công ty “phong sát”, anh chuyển đến thôn Đại Thắng tạm lánh, thư giãn. Từ nhỏ, Nhất Tuấn thường gặp ác mộng, thấy ai đó đâm chết mình.Trong căn nhà này, anh đã vô tình phóng thích một hồn ma nữ, tên là Vân Liễu Phương (do Cung Gia Hân đóng). Ma nữ vốn là một hoa đán tuồng kịch Quảng Đông, bị thiệt mạng bởi một trận hỏa hoạn vào năm 1993.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2023, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Owen Cheung","avatar":""},{"name":"Katy Kung","avatar":""},{"name":"Tiffany Lau","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
