INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ma-nu-si-tinh', 'Ma Nữ Si Tình', 'Unchained Medley', 'ma nữ si tình unchained medley owen cheung katy kung tiffany lau ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-cua-bi-mat', 'Cánh Cửa Bí Mật', 'Secret Door', 'https://phimimg.com/upload/vod/20240324-1/af591d039d18ec2af6b219727ed7c043.jpg', 'https://phimimg.com/upload/vod/20240324-1/17e27f5c9ae52d0ec8b1f8bbce8dce15.jpg', '<p>Ba mươi năm trước, tên tội phạm cứng rắn Yip Siu-tin bị bắt vì tội cướp có vũ trang và bị kết án tù. Con gái của Siu-tin, người xử lý chiến lợi phẩm, đổi tên thành Cheung Sum-yuet và bắt đầu cuộc sống mới. Cô cũng kết hôn với ông chủ công ty du thuyền Yen Ho-yin. Trong khi đó, Chong Chi-kiu là đứa trẻ bị đồng phạm bỏ lại và chết vì vụ cướp. Tang Sing-him tốt bụng trở thành cha mẹ nuôi của anh. Một tai nạn giao thông khiến Chi-kiu và Sum-yuet lại gặp nhau. Nhưng tai nạn này bằng cách nào đó lại có liên quan đến Siu-tin, người vừa mới ra tù. Sum-yuet không còn có thể trốn tránh Siu-tin, người luôn là cơn ác mộng với cô. Cuộc hôn nhân của cô cũng có một số vấn đề nhất định. Cảnh sát Yeung Yan-hiu can thiệp bằng cách mở một cuộc điều tra, và cô ấy tiếp tục truy lùng Siu-tin và Chi-kiu. Những mối hận thù chưa được giải quyết trong ba mươi năm một lần nữa lại được đặt lên hàng đầu. Tất cả những người có liên quan đến vụ cướp năm ngoái đều bị lôi kéo vào mớ hỗn độn này.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 10, 2023, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Ruco Chan","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Roxanne Tong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
