INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-doc-cuong-nhan', 'Phá Độc Cường Nhân', 'Jade Narcotics Heroes', 'https://phimimg.com/upload/vod/20240324-1/cc2d70dff54564b6a820c9dc8fef2c9b.jpg', 'https://phimimg.com/upload/vod/20240324-1/e5d920c5528338399bfdda10eec1550f.jpg', '<p>Cuộc đối đầu đầy kịch tính giữa cảnh sát và trùm ma túy sẽ diễn biến ra sao? Năm 2010, “Độc vương” ma túy Văn Hoa (do Trần Hào đóng) nắm giữ hơn một nửa thị trường ở Hồng Kông. Để đánh phá tên trùm đầu sỏ ma túy này, tổ chống ma túy NB đã cài cắm cảnh sát Diệp Hạo Thiên (do Tiêu Chính Nam đóng) ở bên cạnh Hoa. Ba năm sau, Hoa phát hiện thân phận nội gián của Thiên. Văn Hoa đã tiêm một lượng lớn ma túy vào người Thiên. Sau đó, Văn Hoa bị bắt ngồi tù.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2023, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Moses Chan","avatar":""},{"name":"Nancy Wu","avatar":""},{"name":"Edwin Siu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
