INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pluto', 'PLUTO', 'PLUTO', 'https://phimimg.com/upload/vod/20240324-1/112065cc4fad3fc464a2597f3954b483.jpg', 'https://phimimg.com/upload/vod/20240324-1/3381ba99ce12b7a96dce8a6516b0e14f.jpg', '<p>Khi bảy robot tiên tiến nhất thế giới cùng các đồng minh con người lần lượt bị sát hại, thanh tra Gesicht sớm nhận ra rằng anh cũng đang gặp nguy hiểm.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 9, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Fuji Shinshu","avatar":""},{"name":"Hikasa Yoko","avatar":""},{"name":"Minori Suzuki","avatar":""},{"name":"Yasumoto Hiroki","avatar":""},{"name":"Yamadera Koichi","avatar":""},{"name":"Kiuchi Hidenobu","avatar":""},{"name":"Koyama Rikiya","avatar":""},{"name":"Miyano Mamoru","avatar":""},{"name":"Seki Toshihiko","avatar":""},{"name":"Furukawa Toshio","avatar":""},{"name":"Tsuda Eizo","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Hazama Michio","avatar":""},{"name":"Tanaka Hideyuki","avatar":""},{"name":"Horiuchi Kenyu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
