INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-dai-phu-cua-toi', 'Xin Chào Đại Phu Của Tôi', 'Xin Chào Đại Phu Của Tôi', 'https://phimimg.com/upload/vod/20240324-1/f2efc6958c42480a5d765f12ced7cee1.jpg', 'https://phimimg.com/upload/vod/20240324-1/5fdab05e8d601f5b30d21f83a3ca1065.jpg', '<p>Trình Gia Ứng (do Thái Tư Bối đóng) tốt nghiệp trung y, cô luôn đạt thành tích xuất sắc từ lúc vào nghề. Ứng thăng tiến làm chủ nhiệm phục vụ trung y của chính phủ.Trong đó, Cô Thanh Kình là bạn thanh mai trúc mã, cũng là bạn học cùng khóa và là bạn trai cũ của Ứng. 10 năm trước, họ chia tay vì Kình đi làm thiện nguyện ở nước ngoài. Tôn chỉ của Kình là: Trước khi người bệnh chưa bị bệnh, thầy thuốc loại bỏ nguồn bệnh mới là thượng sách, cũng tức là chữa chưa bệnh.Kình làm việc vốn không theo nguyên tắc nên thường xảy ra xung đột với Ứng nhưng họ luôn lấy lợi ích người bệnh làm trọng.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 12, 2023, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Sisley Choi","avatar":""},{"name":"Matthew Ho","avatar":""},{"name":"Kayan Yau","avatar":""},{"name":"Erica Chan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
