INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-vo-de-ton-3d', 'Tiên Võ Đế Tôn 3D', 'Legend Of Xianwu', 'https://phimimg.com/upload/vod/20240324-1/7b1d211d7c0334cad7b22f3159743df3.jpg', 'https://phimimg.com/upload/vod/20240324-1/5c6106fddd2e9d0cf906f203749d2426.jpg', '<p>Diệp Thần phế vật của môn phái bị đuổi khỏi tông môn, không nhà để về, một lần tình cờ có được Chân Hoả, bước lên con đường tiên võ lần nữa. Đây là một thế giới Thần - Tiên - Ma - Phật cùng tồn tại, là thời đại chư thiên vạn vực hỗn loạn. Con đường nghịch thiên của Diệp Thần bắt đầu từ đây, trải qua trắc trở cùng luân hồi, sau cùng bước lên đỉnh cao đại đạo.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324253);
