INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-nhien-toi-thanh-ma-ca-rong', 'Bỗng Nhiên, Tôi Thành Ma Cà Rồng', 'I Woke Up A Vampire', 'https://phimimg.com/upload/vod/20240324-1/b10959f38d7b1f2cbf4e58a6458c0f68.jpg', 'https://phimimg.com/upload/vod/20240324-1/048963923b5c0c77a82bbed61cae39eb.jpg', '<p>Vào sinh nhật 13 tuổi, Carmie biết được cô thực ra là nửa người, nửa ma cà rồng. Và rồi những sức mạnh thần thoại đó khiến chặng đường học cấp 2 của cô thêm phức tạp.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kaileen Chang","avatar":""},{"name":"Niko Ceci","avatar":""},{"name":"Zebastin Borjeau","avatar":""},{"name":"Ana Araujo","avatar":""},{"name":"Aaliyah Cinello","avatar":""},{"name":"Ipsita Paul","avatar":""},{"name":"Rainbow Sun Francks","avatar":""},{"name":"Delia Lisette Chambers","avatar":""},{"name":"Jayd Deroché","avatar":""},{"name":"Kris Siddiqi","avatar":""},{"name":"Jillian Welsh","avatar":""},{"name":"Charlotte Legault","avatar":""},{"name":"Patrick McKenna","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324253);
