INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-truong-laserhawk-blood-dragon-remix', 'Đội Trưởng Laserhawk: Blood Dragon Remix', 'Captain Laserhawk: A Blood Dragon Remix', 'https://phimimg.com/upload/vod/20240324-1/603eb708512c65069240079bb3f88e35.jpg', 'https://phimimg.com/upload/vod/20240324-1/5323b6d7a5b627428db9915d307fdfa6.jpg', '<p>Bị coi là kẻ thù của quốc gia, rô-bốt siêu chiến binh chật vật tìm kiếm lý tưởng xứng đáng để đấu tranh tại một xã hội đen tối, nơi chẳng có gì giống như bề ngoài.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nathaniel Curtis","avatar":""},{"name":"Caroline Ford","avatar":""},{"name":"Balak","avatar":""},{"name":"Boris Hiestand","avatar":""},{"name":"David Menkin","avatar":""},{"name":"Mark Ebulué","avatar":""},{"name":"Nigel Barber","avatar":""},{"name":"Adi Shankar","avatar":""},{"name":"Courtney-Mae Briggs","avatar":""},{"name":"Glenn Wrage","avatar":""},{"name":"Daniel York Loh","avatar":""},{"name":"Kenny Omega","avatar":""},{"name":"Cody Rhodes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324253);
