INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-the', 'Thi Thể', 'Bodies', 'https://phimimg.com/upload/vod/20240324-1/93ad4b545a1a843b45afcd04abd21b4c.jpg', 'https://phimimg.com/upload/vod/20240324-1/20aeed225217739ad1e80aeaccc5d888.jpg', '<p>Bốn thanh tra. Bốn mốc thời gian. Một thi thể. Để cứu tương lai của nước Anh, trước tiên họ cần phá giải vụ án mạng đã làm thay đổi tiến trình lịch sử.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jacob Fortune-Lloyd","avatar":""},{"name":"Shira Haas","avatar":""},{"name":"Amaka Okafor","avatar":""},{"name":"Kyle Soller","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Greta Scacchi","avatar":""},{"name":"Tom Mothersdale","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
