INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thi-the', 'Thi Thể', 'Bodies', 'thi thể bodies jacob fortune-lloyd shira haas amaka okafor kyle soller stephen graham greta scacchi tom mothersdale ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ly-cua-toi-khong-don-gian', 'Trợ Lý Của Tôi Không Đơn Giản', 'Never Too Late', 'https://phimimg.com/upload/vod/20240324-1/3a32233f59ed78e55dc5015a4c62b289.jpg', 'https://phimimg.com/upload/vod/20240324-1/782b6ef99dd0c193584436a586a8dca5.jpg', '<p>Khương Điềm bỏ nhà đi để trở thành kiến trúc sư nội thất ở Bắc Kinh. Khi mọi thứ đang tiến triển theo hướng mà cô mong muốn, Khương Điềm bị chuyển về chi nhánh quê hương do cô xúc phạm lãnh đạo công ty. Không ngờ rằng, tại môi trường làm việc mới, cô trở thành đồng nghiệp của ông Ngô Kính Phương, một người 60 tuổi. Đối mặt với môi trường làm việc không phù hợp và kế hoạch trở về Bắc Kinh của cô bị gián đoạn do chia tay với bạn trai, Khương Điềm thất nghiệp, thất tình, không còn lựa chọn nào khác ngoài việc ở lại quê hương. Trong những ngày buồn rầu, Ngô Kính Phương từng bước xây dựng lại sự tự tin cho Khương Điềm để cô ở lại quê hương. Ngô Kính Phương cũng chăm chỉ học thiết kế từ Khương Điềm để có được chỗ đứng trong xã hội và trở thành trợ lý của Khương Điềm. Khương Điềm dẫn dắt Ngô Kính Phương tiếp tục tham gia vào xã hội cạnh tranh khốc liệt, và Ngô Kính Phương giúp Khương Điềm tìm cách hòa nhập với quê hương. Cả hai đã xây dựng được tình bạn sâu sắc thông qua những thất bại, trong khi giúp đỡ những người khác xây dựng ngôi nhà lý tưởng của mình, họ cũng xác định được con đường mình nên đi trong tương lai.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Olivia Wang","avatar":""},{"name":"Deng Jie","avatar":""},{"name":"Bạch Kính Đình","avatar":""},{"name":"Viva","avatar":""},{"name":"Hao Chen","avatar":""},{"name":"Jiang Yiru","avatar":""},{"name":"Shirley Dai","avatar":""},{"name":"Kim","avatar":""},{"name":"Ma Shao Hua","avatar":""},{"name":"Guo Hong","avatar":""},{"name":"Zhu Yin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324253);
