INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('everybody-loves-diamonds', 'Everybody Loves Diamonds', 'Everybody Loves Diamonds', 'https://phimimg.com/upload/vod/20240324-1/7951196d78511b4199605d713ff4ad86.jpg', 'https://phimimg.com/upload/vod/20240324-1/99022b6bb9bf792d186a7931239bf5ce.jpg', '<p>Một nhóm trộm người Ý nhỏ tuổi tìm cách đánh lừa lực lượng an ninh cấp cao nhất để đánh cắp những viên đá quý trị giá hàng triệu đô la từ Trung tâm Kim cương Antwerp. Lấy cảm hứng từ câu chuyện có thật về vụ cướp Diamond Center.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2023, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Kim Rossi Stuart","avatar":""},{"name":"Anna Foglietta","avatar":""},{"name":"Gianmarco Tognazzi","avatar":""},{"name":"Carlotta Antonelli","avatar":""},{"name":"Leonardo Lidi","avatar":""},{"name":"Johan Heldenbergh","avatar":""},{"name":"Kim Mousa","avatar":""},{"name":"Issam Dakka","avatar":""},{"name":"Synnøve Macody Lund","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
