INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-hoa-hong-dao', 'Mai Hoa Hồng Đào', 'Mr. & Mrs. Chen', 'https://phimimg.com/upload/vod/20240324-1/92c1c35f20bb1de731b5f965dcd41249.jpg', 'https://phimimg.com/upload/vod/20240324-1/9302f00f86686a611bb9b9ad74a1f91a.jpg', '<p>Một tác phẩm điện ảnh đặc sắc, lấy bối cảnh vào thập kỷ 1940. Câu chuyện xoay quanh hai người yêu cũ, Zuo Shuang Tao và Chen Jia Ping, một cách bất ngờ họ đoàn tụ. Được tái ngắm nhìn qua thời gian, tình yêu của họ nở rộ trong biển người điệp viên, khi họ cùng theo đuổi các mục tiêu tương tự trong thế giới nguy hiểm của người làm gián điệp.Sự tái hợp đánh thức những ký ức đẹp và thúc đẩy họ tiến vào một cuộc phiêu lưu đầy thách thức. Cùng nhau, họ phải đối diện với âm mưu đen tối và cuộc chiến nguy hiểm. Hai người sẽ cùng nhau xây dựng một tình yêu bền chặt, vượt qua những khó khăn và nguy cơ không ngừng gia tăng.Mai Hoa Hồng Đào 2023 VietSub - Mr &amp; Mrs Chen 2023&nbsp;là một câu chuyện lôi cuốn, đưa người xem trở lại thời kỳ lịch sử đầy biến động và hiểm nguy. Hãy cùng Zuo Shuang Tao và Chen Jia Ping trải qua cuộc hành trình đầy mạo hiểm, tìm hiểu về tình yêu, sự đoàn kết và trách nhiệm trong một thế giới đầy biến cố.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hàn Đông Quân","avatar":""},{"name":"Quan Hiểu Đồng","avatar":""},{"name":"Lý Nghệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
