INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('big-vape-thang-tram-cua-thuoc-la-juul', 'Big Vape: Thăng Trầm Của Thuốc Lá Juul', 'Big Vape: The Rise And Fall Of Juul', 'https://phimimg.com/upload/vod/20240324-1/432ab353af3ae1a5fa0290805be7ea2e.jpg', 'https://phimimg.com/upload/vod/20240324-1/e0652804d3987db6c97d54d3bc8a51e0.jpg', '<p>Trong loạt phim tài liệu này, một công ty khởi nghiệp thuốc lá điện tử rời rạc trở thành công ty trị giá hàng tỷ USD nhưng rồi dịch bệnh khiến thành công của họ tan thành mây khói.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Pierce","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324253);
