INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('big-vape-thang-tram-cua-thuoc-la-juul', 'Big Vape: Thăng Trầm Của Thuốc Lá Juul', 'Big Vape: The Rise And Fall Of Juul', 'big vape: thăng trầm của thuốc lá juul big vape: the rise and fall of juul david pierce ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-quoc-xu-so-banchan', 'Hàn Quốc: Xứ Sở Banchan', 'A Nation Of Banchan', 'https://phimimg.com/upload/vod/20240324-1/b3f086d0359fed25f4dba92409313d76.jpg', 'https://phimimg.com/upload/vod/20240324-1/530c080921dd4966cd6e0a5a1992175b.jpg', '<p>Mâm cơm của người Hàn Quốc vô cùng ngon mắt. Hãy cùng tìm hiểu mọi thứ từ các loại hạt đến món phụ, và khám phá bí quyết nấu những bữa cơm phong phú, đong đầy tình cảm.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Huh Young Man","avatar":""},{"name":"Ryu Soo Young","avatar":""},{"name":"Mimi","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324253);
