INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-lai-co-vo-cam-nho-be', 'Đứng Lại! Cô Vợ Câm Nhỏ Bé', 'My Lovely Wife', 'https://phimimg.com/upload/vod/20240324-1/0dc7e54712f280d41cdc5790e4dfa0ed.jpg', 'https://phimimg.com/upload/vod/20240324-1/f4132d1cafba2f10c094e7738bbce9e6.jpg', '<p>Thân Nhãn, sau khi chứng kiến cái chết của mẹ đã bị câm do bị PTSD. Cô mất đi tình yêu thương của mẹ và phải đối mặt với sự lạnh lùng của cha- người đã đưa tình nhân và một đứa con gái riêng bằng tuổi cô về nhà, đồng thời phải chịu sự ngược đãi của bà mẹ kế Giang Uyển Lệ và đứa con gái riêng của bả Hứa Dao. Tuy nhiên, Thân Nhãn luôn cho rằng có một bí mật ẩn sau cái chết của mẹ cô. Chính vì vậy cô luôn tỏ ra yếu đuối và câm lặng để tìm ra sự thật.Thực chất cô ấy là một “bông hoa sen đen”tốt bụng và vô cùng cao thượng.Ông chủ Cố Minh Diên với gương mặt lạnh lùng, tính cách quyết đoán, đã phải trải qua một tuổi thơ đầy khó khăn khiến anh mắc chứng “hoang tưởng bị bức hại, luôn cảnh giác với mọi người. Anh luôn nghi ngờ rằng cái chết của cha anh Cố Đào là một âm mưu do nhà họ hứa và Cố Hoành Vũ hợp sức thực hiện. Khi biết về thân phận thật sự của Thân Nhãn, anh muốn lợi dụng cô để làm sáng tỏ sự thật, vì vậy anh đã ký một hợp đồng hôn nhân giả để sống chung với cô, nhưng anh không biết rằng anh mới chính là con mồi của Thân Nhãn, một kẻ ngây thơ nhưng lại có lòng dạ đen tốiHai người luôn đấu trí với nhau, từ gian dối đến thật lòng, từ việc lợi dụng lẫn nhau đến cùng nhau đối phó với kẻ thù. Tuy nhiên, khi họ sắp chạm tới hạnh phúc, họ phát hiện ra rằng kẻ chủ mưu lại ở xa hơn họ tưởng, vậy mối quan hệ của họ sẽ đi về đâu</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Seek","avatar":""},{"name":"Zheng Nanxi","avatar":""},{"name":"Hu Yaqi","avatar":""},{"name":"Wang Lei","avatar":""},{"name":"Ren Zhong","avatar":""},{"name":"Zhang Hao Cheng","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324253);
