INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-greatest-show-never-made', 'The Greatest Show Never Made', 'The Greatest Show Never Made', 'https://phimimg.com/upload/vod/20240324-1/991ec1f04f8d7e410a70a0d528b88853.jpg', 'https://phimimg.com/upload/vod/20240324-1/eaf576babdc95f88d819844e1ab3e2a0.jpg', '<p>Năm 2002, sáu thanh niên đang tìm kiếm danh tiếng và vận may đã đăng ký tham gia một chương trình truyền hình thực tế mới, tuyệt mật. Họ rời bỏ nhà cửa, công việc và đối tác để đến London để bắt đầu cuộc phiêu lưu. Hai mươi năm sau khi giấc mơ của họ tan vỡ, họ vẫn đang tìm kiếm câu trả lời; cố gắng hiểu làm thế nào một chương trình không tồn tại và sự biến mất của người đàn ông đằng sau nó đã thay đổi cuộc đời họ mãi mãi.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324253);
