INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-greatest-show-never-made', 'The Greatest Show Never Made', 'The Greatest Show Never Made', 'the greatest show never made the greatest show never made  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-vien-me-tinh', 'Trang Viên Mê Tình', 'Miss Mystery', 'https://phimimg.com/upload/vod/20240324-1/238650c4b6f7f66c60557188ad6daacb.jpg', 'https://phimimg.com/upload/vod/20240324-1/6d0b15524a892afc0aee75f548765c36.jpg', '<p>Bộ phim đầy kịch tính kể về cuộc hành trình của Tiết Đồng, một tiểu thư giàu có nhưng gia đình cô đã gặp biến cố đầy bí ẩn từ khi cô còn nhỏ. Sau 18 năm, Tiết Đồng quyết định trở về cố hương dưới bí danh Lâm Bảo Nhi với mục tiêu rõ ràng: trả thù kẻ đã hủy hoại gia đình cô. Tuy nhiên, kế hoạch của cô bị đe dọa khi cô bị buộc phải tham gia buổi đính hôn và trở thành hôn thê của Chu Quan Văn, con trai của kẻ thù. Cuộc đối đầu giữa Tiết Đồng và Chu Quan Văn trở nên phức tạp hơn khi tình cảm xen vào. Liệu Tiết Đồng có thể tiêu diệt kẻ thù của mình và đồng thời bảo vệ tình yêu đang nảy nở?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shujun Chen","avatar":""},{"name":"Leo Yang","avatar":""},{"name":"Wu Jingxin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
