INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-co-gai-cua-rokudo', 'Các Cô Gái Của Rokudo', 'Rokudo''s Bad Girls', 'https://phimimg.com/upload/vod/20240314-1/8573fb7fa11b2fec8356b98b0d375f21.jpg', 'https://phimimg.com/upload/vod/20240314-1/10c3cc12193bc7c51065decf2c9971b8.jpg', '<p>Câu chuyện kể về Tо̄suke Rokudо̄, một nam sinh trung học nhút nhát bị bọn côn đồ bắt nạt. Anh nhận được một cuộn giấy từ người ông quá cố của mình, để lại dấu vết trên trán. Hiệu ứng của dấu ấn khiến một cô gái du côn tên Ranna Himawari phải lòng anh.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Gen Sato","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Naomi Ohzora","avatar":""},{"name":"Yuki Yomichi","avatar":""},{"name":"Misato Matsuoka","avatar":""},{"name":"Hitomi Sekine","avatar":""},{"name":"Haruki Ishiya","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324253);
