INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('protocol-sac-mua-cua-chung-ta', 'Protocol: Sắc Mưa Của Chúng Ta', 'Protocal: Rain', 'https://phimimg.com/upload/vod/20240314-1/a8efb5dbce30706d2097abf5a9d99e62.jpg', 'https://phimimg.com/upload/vod/20240314-1/8eb4724a83998b09f28cdaf80d414d71.jpg', '<p>Sau một tai nạn, cha của Shun Tokinoy đã qua đời còn em gái thì bị thương. Shun Tokinoy đã từ bỏ trò game duy nhất mà bản thân yêu thích và xin vào làm việc cho một quán cà phê thể thao có tên FOX ONE. Cậu dành toàn bộ thời gian để học tập và làm việc bán thời gian. Tuy nhiên, cậu phát hiện ra FOX ONE đang chìm ngập trong nợ nần. Shun và những người bạn của cậu hy vọng chiến thắng Xaxerion Championship và giành được tiền thưởng để trả nợ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ono Kensho","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Momo Asakura","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324253);
