INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-appetit', 'Bon Appetit', 'Bon Appetit', 'https://phimimg.com/upload/vod/20240314-1/31bd7cda98c8642497494036f1cbc10f.jpg', 'https://phimimg.com/upload/vod/20240314-1/93be15bf915f2f2c826a9f8e692c24c5.jpg', '<p>Bon Appetit: Mời Thưởng Thức Mỹ Vị là một sản phẩm đầy lãng mạn của đội ngũ sản xuất từ Giám Đốc Thường Mời Tôi Ăn Tối và Xe Công Nông Tình Yêu. Do Hoon là một người nhân viên văn phòng luôn đắm chìm trong công việc, mỗi ngày chỉ xoay quanh giữa nhà và công ty. Cuộc sống của anh dường như đơn điệu, tràn đầy cảm giác cô đơn và buồn bãi. Tuy nhiên, một ngày nọ, cuộc sống của anh bị người hàng xóm kế bên - Yoon Soo hoàn toàn đảo lộn. Yoon Soo là đàn em học đại học của Do Hoon, một chàng trai trẻ đột ngột bỏ học. Một ngày nọ, Yoon Soo đột ngột xuất hiện trước mặt Do Hoon, mang theo một bát chè ngọt như món quà chuyển nhà để tặng anh. Do Hoon nhận lấy chiếc bát tráng miệng này, và ngay lập tức mắt anh sáng rực, như thể vị ngọt ấm áp của nó đã làm dịu đi tâm hồn mệt mỏi của anh. Yoon Soo thổ lộ rằng, anh đã từng không dám thổ lộ tình cảm với Do Hoon một thời gian vì thiếu dũng cảm, và đã lựa chọn trốn tránh. Tuy nhiên, sau những năm tháng trôi qua, Yoon Soo coi sự việc đó như một ký ức xa xôi, trong khi Do Hoon lại bắt đầu từ thời điểm đó mà không rõ ràng, bắt đầu quan tâm đến Yoon Soo. Từ ngày đó, cuộc sống của Do Hoon và Yoon Soo đã trải qua những thay đổi đáng kể. Sau giờ làm, họ trở nên hài hòa trong việc cùng nhau dùng bữa tối một cách tự nhiên, và mỗi bữa ăn trở thành những khoảnh khắc quý báu mà họ chia sẻ. Do Hoon thậm chí không nhận ra rằng, tình cảm của anh dành cho Yoon Soo đang từ từ bùng cháy lên. Mà chất xúc tác giữa đôi họ không chỉ nhuốm hương vị của tình yêu, mà đan xen vào những lần nấu nướng ấy còn có ngày tìm được sự an ủi. Mỗi một món ăn đong đầy hương sắc trữ tình và hồi ức ấm áp, khiến cho Do Hoon và Yoon Soo càng lúc càng chìm sâu vào sự quyến luyến thân mật đầy ngọt ngào.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Gi taek","avatar":""},{"name":"Liu zeong hun","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
