INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-thu-ngay-luc-nay', 'Mọi Thứ. Ngay Lúc Này.', 'Everything Now', 'https://phimimg.com/upload/vod/20240314-1/c7c1752acfcd01e85b4841b37e9ee999.jpg', 'https://phimimg.com/upload/vod/20240314-1/0ea5aec475daa33571518d08b0c79422.jpg', '<p>Sau nhiều tháng hồi phục khỏi chứng rối loạn ăn uống, cô nàng 16 tuổi Mia nghĩ ra danh sách những trải nghiệm tinh túy dành cho tuổi teen để bù đắp khoảng thời gian đã mất.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sophie Wilde","avatar":""},{"name":"Lauryn Ajufo","avatar":""},{"name":"Harry Cadby","avatar":""},{"name":"Noah Thomas","avatar":""},{"name":"Sam Reuben","avatar":""},{"name":"Niamh McCormack","avatar":""},{"name":"Jessie Mae Alonzo","avatar":""},{"name":"Robert Akodoto","avatar":""},{"name":"Vivienne Acheampong","avatar":""},{"name":"Alex Hassell","avatar":""},{"name":"Stephen Fry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
