INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('moi-thu-ngay-luc-nay', 'Mọi Thứ. Ngay Lúc Này.', 'Everything Now', 'mọi thứ. ngay lúc này. everything now sophie wilde lauryn ajufo harry cadby noah thomas sam reuben niamh mccormack jessie mae alonzo robert akodoto vivienne acheampong alex hassell stephen fry ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ho-dai-nhan-than-men', 'Thiên Hồ Đại Nhân Thân Mến', 'Dear Mr. Heavenly Fox', 'https://phimimg.com/upload/vod/20240314-1/f29f7fe826be7d6f1413332d47e21237.jpg', 'https://phimimg.com/upload/vod/20240314-1/7a0745611bf6436a4362e1df0e12e19a.jpg', '<p>Theo truyền thuyết, một trăm năm trước, yêu hồ đã phù phép đứa con tinh thần đâm vào núi Đoạn Nguyệt, khiến vua bù nhìn xác chết bị phong ấn dưới núi gây rắc rối và gây hại cho thế giới. tộc cáo chưa tương tác với nhau. Qi Yuanbao, một cô gái trẻ xuất thân từ một gia đình tu luyện, lẻn ra khỏi nhà để đi ra đường, vô tình đột nhập vào núi Suiyue, khu vực cấm dành cho con người và gặp Changlan, Thiên hồ đang tu luyện ở đây. Bằng cách này, một người và một con cáo đã gặp nhau như định mệnh ở Broken Moon Mountain, bộc lộ tình yêu và lời thề đã bị chôn vùi hàng trăm năm.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Youshuo","avatar":""},{"name":"Lu Xiaoyu","avatar":""},{"name":"Zhou Zhao Yuan","avatar":""},{"name":"Li Yizhen","avatar":""},{"name":"Haodong Ma","avatar":""},{"name":"He Yichen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
