INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-ho-dai-nhan-than-men', 'Thiên Hồ Đại Nhân Thân Mến', 'Dear Mr. Heavenly Fox', 'thiên hồ đại nhân thân mến dear mr. heavenly fox wang youshuo lu xiaoyu zhou zhao yuan li yizhen haodong ma he yichen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-hac-yeu-su-luc', 'Hổ Hạc Yêu Sư Lục', 'Tiger And Crane', 'https://phimimg.com/upload/vod/20240314-1/584037c269e4c50f90e90de75302e7ab.jpg', 'https://phimimg.com/upload/vod/20240314-1/ba5babfc669fac6e35212455769c86de.jpg', '<p>Hổ Hạc Yêu Sư Lục là bộ phim do Quách Hổ chỉ đạo với sự tham gia của các diễn viên Tương Long, Trương Lăng Hách, Vương Ngọc Thanh, Diệp Thanh, Hà Lam Đậu.\nBộ phim được chuyển thể từ bộ truyện tranh Hổ Hạc Yêu Sư Lục. Câu chuyện là góc nhìn của Hổ Tử và Hiểu Hiên về một nhóm thanh thiếu niên, vì ước mơ, vì tình yêu và trách nhiệm, trong nước mắt và tiếng cười để giải tỏa , vượt qua khó khăn giải cứu thiên hạ.Cô bé mồ côi trên núi lạc quan và vui vẻ Hổ Tử đã vô tình nuốt chửng chí dương bảo vật xích châu. Cô còn gặp Kỳ Hiểu Hiên đội trưởng của quỷ vương triều lạnh lùng nghiêm nghị yêu sạch sẽ. Hai người trẻ với những tính cách rất khác nhau buộc phải đi chung con đường vì một viên xích châu, không những vậy họ còn quen với Triệu Hinh Đồng, Vương Vũ Thiên, Sơn Trà và những người khác. Bọn họ lúc đầu ghét bỏ phòng bị nhau đến bị thu hút bởi sự khác biệt và chớp nhoáng của nhau. Ở một phen trải qua nguy hiểm họ trở nên thân thiết hơn, để bảo hộ Hổ Tử, Kỳ Hiểu Hiên đã bị vào nhà giam. Để cứu Hiểu Hiên, Hổ Tử cùng các bạn cùng nhau tham gia chọn lựa, kết quả là họ đã tiết lộ âm mưu lớn của Quốc Ngự Yêu Sư và tìm ra chân tướng cuộc chiến giữa các yêu quái cách đây năm trăm năm. Bị áp chế năm trăm năm yêu quân rục rịch, ý đồ hủy diệt nhân gian. Ngay khi tham vọng của thế giới loài người và yêu quái sắp mang đến một thảm họa cho thế giới, một nhóm thanh niên đầy nhiệt huyết với ước mơ sẽ không ngần ngại hy sinh thân mình để giải cứu thế giới.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiang Long","avatar":""},{"name":"Trương Lăng Hách","avatar":""},{"name":"Wang Yu Wen","avatar":""},{"name":"Diệp Thanh","avatar":""},{"name":"He Lan Dou","avatar":""},{"name":"Trần Hựu Duy","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
