INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-quoc-xu-so-kim-chi', 'Hàn Quốc: Xứ Sở Kim Chi', 'A Nation Of Kimchi', 'https://phimimg.com/upload/vod/20240314-1/fbf42a8a3ef49a8e02b486e8ee33f0ff.jpg', 'https://phimimg.com/upload/vod/20240314-1/89818117204c745086ce168bdf80faae.jpg', '<p>Bước vào cuộc phiêu lưu ẩm thực của kim chi và khám phá những yếu tố giúp kim chi trở thành món ăn biểu tượng cho sự thống nhất, lịch sử và sức sáng tạo không ngừng của Hàn Quốc.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Huh Young Man","avatar":""},{"name":"Ryu Soo Young","avatar":""},{"name":"Mimi","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324253);
