INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-da-sat-hai-jill-dando', 'Ai Đã Sát Hại Jill Dando', 'Who Killed Jill Dando', 'https://phimimg.com/upload/vod/20240314-1/20ec016f0354b7b065b401c442a477b2.jpg', 'https://phimimg.com/upload/vod/20240314-1/0fd1c6d405503f48d67ff66e96966eb1.jpg', '<p>Trong bộ phim tài liệu chuyên sâu này, hãy nhìn lại vụ sát hại MC truyền hình được mến mộ Jill Dando gây chấn động năm 1999. Vụ việc vẫn khiến chuyên gia và công chúng hoang mang.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324253);
