INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('little-baby-bum-music-time', 'Little Baby Bum: Music Time', 'Little Baby Bum: Music Time', 'https://phimimg.com/upload/vod/20240314-1/8f64b16fe829682b6edc58836dfebba1.jpg', 'https://phimimg.com/upload/vod/20240314-1/9fadfd78f7b355bbe2e7c06bfe61731c.jpg', '<p>Hãy đến tham gia niềm vui tại trường mầm non Music Time kỳ diệu, nơi mỗi ngày là một cuộc phiêu lưu với những bài hát thân thiện với trẻ em - và rất nhiều điều học hỏi!</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Siu-see Hung","avatar":""},{"name":"Hannah Jane Fox","avatar":""},{"name":"Raj Ghatak","avatar":""},{"name":"Rishi Kuppa","avatar":""},{"name":"Eve Ridley","avatar":""},{"name":"Harriet Kershaw","avatar":""},{"name":"Felix Tandon","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324253);
