INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-khue-hi-su', 'Lan Khuê Hỉ Sự', 'Hilarious Family', 'https://phimimg.com/upload/vod/20240314-1/6eea6e361bf7a1ef81bea3035ca45d51.jpg', 'https://phimimg.com/upload/vod/20240314-1/065723aa45e90baf1a55b4ddd817078c.jpg', '<p>Góa chồng 18 năm, Du Ruyu quyết tâm gả 4 cô con gái vào những gia đình “tốt”. Để đạt được điều này, bà phải chịu áp lực tài chính rất lớn khi mua một căn nhà ở thủ đô, hy vọng các con gái của bà đều có được một cuộc hôn nhân phù hợp với địa vị kinh tế và xã hội của họ (với những người đàn ông giàu có hoặc quý phái). Tuy nhiên, thay vì những chàng rể giàu có lý tưởng, hàng loạt chàng trai trẻ bất ngờ đã xâm nhập vào cuộc sống của họ một cách khó hiểu: Lu Buping ngượng ngùng, con trai một sĩ quan quân đội; người thừa kế ngu ngốc nhưng kiêu ngạo của một hoàng tử; Tứ hoàng tử, người không biết gì về xã hội nhưng lại tốt bụng một cách tự nhiên; và Li Tengyun, người tràn đầy năng lượng tích cực nhưng luôn bừa bộn. Những người đàn ông này không ai đáp ứng được tiêu chuẩn của Du Ruyu, nhưng họ lại ngày càng thân thiết hơn với con gái của cô...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Lâm","avatar":""},{"name":"Lạt Mục Dương Tử","avatar":""},{"name":"Dương Hạo Vũ","avatar":""},{"name":"Nhậm Hào","avatar":""},{"name":"Ngô Giai Di","avatar":""},{"name":"Cổ Tự Thành","avatar":""},{"name":"Hàn Vân Vân","avatar":""},{"name":"Xướng Long","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
