INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-lang-lee-vui-ve', 'Trưởng Làng Lee Vui Vẻ', 'The Cheery Lee, Village Headman', 'https://phimimg.com/upload/vod/20240314-1/64f15a556e3b0f14fe745d5e533c41b3.jpg', 'https://phimimg.com/upload/vod/20240314-1/1873e225f6302e2aa549e214e665c92b.jpg', '<p>Sau cuộc sống thảm hại ở thành phố, một nghệ sĩ trang điểm trở về quê nhà và buộc phải tranh cử chức trưởng làng để tiếp nối truyền thống gia đình.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"James Rusameekae Fagerlund","avatar":""},{"name":"Narilya Gulmongkolpech","avatar":""},{"name":"Sutthirak Subvijitra","avatar":""},{"name":"Yong Chernyim","avatar":""},{"name":"Bunyawan Pongsuwan","avatar":""},{"name":"Arthur Potjes","avatar":""},{"name":"Seo Ji-yeon","avatar":""},{"name":"Atirut Singhaampol","avatar":""},{"name":"Pimchat Narongpiromkul","avatar":""},{"name":"Napat Chumjittree","avatar":""},{"name":"Thanupong Sakthanawat","avatar":""},{"name":"Yuwadee Ruangchai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
