INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nam-thang-tuoi-tre-khong-the-quay-tro-lai', 'Những Năm Tháng Tuổi Trẻ Không Thể Quay Trở Lại', 'Stand By Me', 'https://phimimg.com/upload/vod/20240314-1/03db27c3b31cd6deef9985a4e7a22615.jpg', 'https://phimimg.com/upload/vod/20240314-1/7510631cc6107cbed03103b183958312.jpg', '<p>Thư mục dữ liệu người dùng bị khóa bởi phiên bản đầu tiên và phiên bản thứ hai không có ngoại lệ. Vì vậy, giải pháp là tạo Userdata cho mỗi hồ sơ</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Kim Mạch","avatar":""},{"name":"Bạch Vũ Phàm","avatar":""},{"name":"Ngô Gia Khải","avatar":""},{"name":"Triệu Chiêu Nghi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
