INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-nam-thang-tuoi-tre-khong-the-quay-tro-lai', 'Những Năm Tháng Tuổi Trẻ Không Thể Quay Trở Lại', 'Stand By Me', 'những năm tháng tuổi trẻ không thể quay trở lại stand by me triệu kim mạch bạch vũ phàm ngô gia khải triệu chiêu nghi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ay-buoc-ra-tu-anh-lua', 'Anh Ấy Bước Ra Từ Ánh Lửa', 'Bright Eyes In The Dark', 'https://phimimg.com/upload/vod/20240314-1/0b9dc32501aa1d2b6b018270aa3b9837.jpg', 'https://phimimg.com/upload/vod/20240314-1/947a6c5b9fa5deab1aaf44e950c1d94e.jpg', '<p>Bộ phim Ánh Ấy Bước Ra Từ Ánh Lửa được chuyển thể từ tiểu thuyết cùng tên nổi tiếng trên diễn đàn Tấn Giang, do Thiên Nghị và Dịch Dũng đảm nhận vai trò đạo diễn. Với sự tham gia của Hoàng Cảnh Du và Trương Tịnh Nghi, đội ngũ sáng tạo và sản xuất đã từng thành công với Theo dòng nước ngầm đã mang đến một tác phẩm thể hiện lên sự cố gắng quên cả mệt nhọc trong ngành cứu hỏa.Lâm Lục Kiêu (do Hoàng Cảnh Du thủ vai) sở hữu kỹ năng cứu hỏa đặc biệt và kinh nghiệm phong phú trong lĩnh vực này, là trưởng đội đặc công Hòa Bình, thành phố Bắc Tuấn. Trùng hợp thế nào, anh được chọn làm huấn luyện viên trong một chương trình truyền hình thực tế nhằm giới thiệu kiến thức cứu hỏa. Trong chương trình, Lâm Lục Kiêu tình cờ gặp lại vũ công Nam Sơ (do Trương Tịnh Nghi thủ vai) - người anh từng cứu thoát khỏi đám cháy trong nhiều năm trước. Nam Sơ có cảm tình với Lâm Lục Kiêu, nhưng cô biết rõ tính chất nguy hiểm của công việc nên không dám tiến tới. Thế hệ lính cứu hỏa trẻ tuổi và dũng cảm như Thiệu Nhất Cửu (do Lý Minh Tuấn thủ vai), Tần Thập Toàn (do Trần Khang thủ vai) và Lâu Minh Dã (do Vương Tử Kỳ thủ vai), đã mang công nghệ trang bị tiên tiến từ nước ngoài trở về đội cứu hỏa. Ba thế hệ lính cứu hỏa thanh - trung - lão cùng hợp tác, hỗ trợ trong các tình huống cháy, động đất, cứu hộ trên không, đã nâng cao một bậc an toàn phòng cháy cho thành phố Bắc Tuấn. Trong quá trình tìm hiểu, Nam Sơ và Lâm Lục Kiêu đã nhận ra tình cảm của mình. Đối mặt với nguy hiểm nhất từ đám cháy rừng, Lâm Lục Kiêu và đồng đội của anh đã chọn tiến về phía ngọn lửa.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 23, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hoàng Cảnh Du","avatar":""},{"name":"Zhang Jing Yi","avatar":""},{"name":"Wu Gang","avatar":""},{"name":"Wang Zi Qi","avatar":""},{"name":"Tang Xiao Tian","avatar":""},{"name":"Zhang Jin","avatar":""},{"name":"Lu Si Yu","avatar":""},{"name":"Hu Yi","avatar":""},{"name":"Li Ming Jun","avatar":""},{"name":"Chen Kang","avatar":""},{"name":"Zhang Duo Han","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
