INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ayaka', 'AYAKA', 'AYAKA', 'https://phimimg.com/upload/vod/20240314-1/7e504d8c13148792837f7ea023a095bb.jpg', 'https://phimimg.com/upload/vod/20240314-1/9db53dd8d7b820b581a6eac72b521957.jpg', '<p>Câu chuyện kể về Yukito Yanagi, một đứa trẻ mồ côi một ngày nọ gặp được một đệ tử lập dị của cha mình. Người đàn ông lạ mặt đưa anh về nơi anh sinh ra ở Ayakajima, được tạo thành từ bảy hòn đảo, nơi được đồn đại là nơi sinh sống của những sinh vật bí ẩn tên là Mitama và những con rồng. Ở đó, Yukito gặp hai đệ tử khác của cha mình, những người bảo vệ sự hòa hợp của Ayakajima… điều này sớm có nguy cơ sụp đổ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuto Uemura","avatar":""},{"name":"Takuma Terashima","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Takahiro Sakurai","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
