INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sung-phi-hoang-do', 'Sủng Phi Hoàng Đồ', 'Estranged Fall In Love', 'https://phimimg.com/upload/vod/20240405-1/f8c6ebf885ec04a1952a9efd0159c88d.jpg', 'https://phimimg.com/upload/vod/20240405-1/9d3f75fc680f414ca2932e3819879930.jpg', '<p>Thương Hàn Duật vì muốn cứu người mình yêu là Nam Tự đã mở ra bí kíp hồi sinh, đồng thời phải dùng hôn sự kiếp này để trả giá cho nó. Nhưng hai người không chịu thua số mệnh, thề non hẹn biển cùng nắm tay nhau chiến đấu đến cùng với sự trừng phạt của trời và lời nguyền...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yan Zixian","avatar":""},{"name":"Hu Dandan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
