INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-mot-nua-than-thuoc-cua-toi', 'Người Yêu Một Nửa Thân Thuộc Của Tôi', 'My Immature Lover', 'https://phimimg.com/upload/vod/20240404-1/723a5a1b70a6a320fc0dfa7f79a7e563.jpg', 'https://phimimg.com/upload/vod/20240404-1/2336f0139be3a9c1e300ac52e2c03704.jpg', '<p>An Hạo, nhân tài đầu tư và Kim Gia Nam, bà chủ xinh đẹp của một công ty sắp phá sản bị ép buộc hẹn hò với nhau qua vòng tay ghép cặp. Nhờ sự giúp đỡ của tình địch, hai người từ không tình nguyện trở nên dần gắn bó với nhau hơn, còn phát hiện ra là bạn hồi nhỏ. Bạn trai cũ tồi tệ, đối thủ cạnh tranh bày mưu hãm hại khiến cuộc tình một nửa thân thuộc ngang tài ngang sức này trở nên tràn đầy thử thách.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhu Min Xin","avatar":""},{"name":"Liu Jia","avatar":""},{"name":"Cheng Xiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
