INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bombay-my-beloved', 'Bombay My Beloved', 'Bambai Meri Jaan', 'https://phimimg.com/upload/vod/20240314-1/395aa55902a778eaa951bde93be4afaa.jpg', 'https://phimimg.com/upload/vod/20240314-1/d36efa95e82069eb27eda0a8348e7b91.jpg', '<p>Bambai Meri Jaan ghi lại cuộc đời của trùm xã hội đen Dara Kadri qua con mắt của cha anh, một cựu cảnh sát, Ismail Kadri. Trong mùa này, chúng ta thấy Dara đặt mọi thứ vào tình thế nguy hiểm, kể cả gia đình mình khi anh trở thành một tay xã hội đen máu lạnh, dũng cảm, sử dụng sự nhạy bén trong kinh doanh của mình để chiến đấu không chỉ với cảnh sát và các đối thủ mà còn cả những con quỷ của chính mình trên đường đi. .</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Avinash Tiwary","avatar":""},{"name":"Kay Kay Menon","avatar":""},{"name":"Amyra Dastur","avatar":""},{"name":"Kritika Kamra","avatar":""},{"name":"Nawab Shah","avatar":""},{"name":"Nivedita Bhattacharya","avatar":""},{"name":"Saurabh Sachdeva","avatar":""},{"name":"Vivan Bhatena","avatar":""},{"name":"Jitin Gulati","avatar":""},{"name":"Sunil Palwal","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
