INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-trong-nhung-nha-tu-khoc-liet-nhat-the-gioi-phan-7', 'Bên Trong Những Nhà Tù Khốc Liệt Nhất Thế Giới (Phần 7)', 'Inside The World''s Toughest Prisons (Season 7)', 'https://phimimg.com/upload/vod/20240314-1/1c3f3c07b1999b374a31f4532eb0eb7a.jpg', 'https://phimimg.com/upload/vod/20240314-1/792385d644fe8a3ceb3500a1a57d803b.jpg', '<p>Nhà báo và cũng là cựu tù nhân Raphael Rowe trải nghiệm cuộc sống bên trong các nhà tù ở Phần Lan, Cộng hòa Séc, Indonesia và Quần đảo Solomon.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Paul Connolly","avatar":""},{"name":"Raphael Rowe","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324253);
