INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-vien-tai-nang-dong-dong-an', 'Nhân Viên Tài Năng Đổng Đổng Ân', 'Hello, I''m At Your Service', 'https://phimimg.com/upload/vod/20240314-1/1c6c14152eb817f7dd845993087b02b4.jpg', 'https://phimimg.com/upload/vod/20240314-1/bda1d120911744680940963c5e1c73c1.jpg', '<p>“Nhân Viên Tài Năng Đổng Đổng Ân” là bộ phim truyền hình do Lâm Nghị (“Khi Bóng Đêm Gợn Sóng”) làm đạo diễn, với các diễn viên chính: Từ Lộ (“Hậu Cung: Chân Hoàn Truyện”), Ngụy Triết Minh (“Sơn Hà Lệnh”), Lưu Nhuận Nam (“Khánh Dư Niên 1”), Trương Bách Nam (“Lạp Tội Đồ Giám”). Bộ phim cải biên từ tiểu thuyết cùng tên của Bộ Y Ma Thất, kể về nhân viên tài năng Đổng Đổng Ân cùng người phụ trách bên A Lâu Uyên đấu trí đấu dũng, dùng sức hút của bản thân thu phục trái tim của Lâu Uyên. Một sự hiểu lầm giữ nhân viên chăm sóc khách hàng tài năng Đổng Đổng Ân cùng người phụ trách bên A Lâu Uyên, khiến cuộc sống nơi làm việc vốn bình đạm của họ trở thành một mớ hỗn loạn. Sau khi ổn định ở bên A, Đổng Đổng Ân không chỉ thể hiện tố chất chuyên nghiệp sở trường của bản thân một cách xuất sắc, mà còn cùng bên A đấu trí đấu dũng, dùng sức hút của bản thân thu phục trái tim của Lâu Uyên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Từ Lộ","avatar":""},{"name":"Ngụy Triết Minh","avatar":""},{"name":"Lưu Nhuận Nam","avatar":""},{"name":"Zhang Bo Jia","avatar":""},{"name":"Guan Zi Jing","avatar":""},{"name":"Yitian Wang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
