INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dream-its-mygo', 'BanG Dream! It''s MyGO!!!!!', 'BanG Dream! It''s MyGO!!!!!', 'https://phimimg.com/upload/vod/20240314-1/7c337859b1f203aa69351bf8d8ba0eed.jpg', 'https://phimimg.com/upload/vod/20240314-1/13185cea7e2fd3ffdc55ea6312f0e961.jpg', '<p>Bạn có muốn ở trong ban nhạc với tôi đến hết cuộc đời không? Đó là vào cuối mùa xuân năm đầu tiên của Anon tại Học viện nữ sinh Haneoka và dường như hầu hết mọi người đều tham gia vào một ban nhạc. Để hòa nhập với những người còn lại trong lớp, Anon, người bắt đầu đi học muộn, vội vã tìm kiếm các thành viên ban nhạc và phát hiện ra rằng “Haneokas Weirdo Tomori vẫn chưa tham gia bất kỳ ban nhạc nào. Vì vậy Anon quyết tâm nói chuyện với Tomori bằng bất cứ giá nào nhưng... **Vết bầm tím và khó coi, đây là âm nhạc của chúng tôi, tiếng khóc của chúng tôi.** **Chúng tôi có thể lạc lối, nhưng chúng tôi sẽ tiếp tục bước đi như những người đã mất .**</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hina Yomiya","avatar":""},{"name":"Rin Tateishi","avatar":""},{"name":"Hina Aoki","avatar":""},{"name":"Mika Kohinata","avatar":""},{"name":"Coco Hayashi","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324253);
