INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-kich-lang-man', 'Phản Kích Lãng Mạn', 'Romantic, Counterattack Romance', 'https://phimimg.com/upload/vod/20240314-1/84464196d92ad8d524087bcece4ef752.jpg', 'https://phimimg.com/upload/vod/20240314-1/c54f96fbceb1822482ebf5680dec2db4.jpg', '<p>Lâm Nghiên, cô chủ của Lâm Thị bị chồng chưa cưới phản bội vào đúng ngày tổ chức hôn lễ và không may ngã khỏi tầng lầu. Ba năm sau, Lâm Nghiên bất ngờ tỉnh lại và quyết tâm báo thù, giành lại tài sản của gia tộc. Mỗi bước đi trên con đường phục thù đều khó khăn nguy hiểm. May thay cô gặp được vệ sĩ cũ của bố mình là Tiêu Mạch, hai người kề vai sát cánh, hạ gục gã đàn ông khốn nạn, xử lý ả tình nhân, tạo ra màn phản công ngọt ngào. Nhưng cùng với sự thăng hoa của tình yêu, thân phận thật sự của Tiêu Mạch cũng không hề đơn giản. Có lẽ tình yêu đích thực là một loại thuốc độc…</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guo Jia Nan","avatar":""},{"name":"Yang Xue Er","avatar":""},{"name":"Wang Jia Li","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
