INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phan-kich-lang-man', 'Phản Kích Lãng Mạn', 'Romantic, Counterattack Romance', 'phản kích lãng mạn romantic, counterattack romance guo jia nan yang xue er wang jia li ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhon-chan-de-den-gan-nguoi', 'Nhón Chân Để Đến Gần Người', 'Just Dance', 'https://phimimg.com/upload/vod/20240314-1/d803a4d4e1b70d2f94f156a905858ffa.jpg', 'https://phimimg.com/upload/vod/20240314-1/b782e1ab8013e4fe6d2d83cacc02c6b0.jpg', '<p>Học viện múa Hải Thành, một trường múa ba lê hàng đầu trong khu vực, xoay quanh giấc mơ khiêu vũ ba lê của các chàng trai và cô gái. Shi Xiao Chun, đến Haiwu với sự chúc phúc từ cha và quê hương, và đã gây ấn tượng với các giáo viên bằng tứ đại tuyệt sắc. Kết quả là cô đã được nhận vào trường thành công. Trong quá trình luyện tập khiêu vũ và theo đuổi ước mơ, Xiao Chun đã gặp được Ling Chen lạnh lùng và đẹp trai, công chúa múa ba lê Yu Man Man, cũng như các đối thủ và bạn bè, và với sự giúp đỡ của các giáo viên, cô đã làm việc chăm chỉ cùng mọi người để đối mặt với những khó khăn. thử nghiệm cuối cùng của các cuộc thi múa ba lê quốc tế.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đinh Nhất Nhất","avatar":""},{"name":"Lưu Dục Hàm","avatar":""},{"name":"Đàm Vịnh Văn","avatar":""},{"name":"Tạ Hân Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
