INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhon-chan-de-den-gan-nguoi', 'Nhón Chân Để Đến Gần Người', 'Just Dance', 'nhón chân để đến gần người just dance đinh nhất nhất lưu dục hàm đàm vịnh văn tạ hân hoa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-nghia-nhan', 'Cửu Nghĩa Nhân', 'Faithful', 'https://phimimg.com/upload/vod/20240314-1/640af21ce6b12d8d22f327f30b0767c6.jpg', 'https://phimimg.com/upload/vod/20240314-1/4d52445906c92d07842224ea11522cfc.jpg', '<p>Một phụ nữ trẻ tên Ru Lan, người đã mạo hiểm danh tiếng của mình để bày tỏ sự bất bình, đã chết trong vô vọng. Bảy năm sau, chín người có mối liên hệ chặt chẽ với vụ án Ru Lan gặp nhau vì những lý do khác nhau, từ đó bắt đầu câu chuyện trả thù. Bất chấp sự phản đối của người bạn tốt Mạnh Vạn, cô gái trẻ Lin Rulan đã mạo hiểm danh tiếng của mình để kiện Wu Lian, chủ nhân của Xiu Liu. Sau nhiều nỗ lực không thành công, Rulan nhận thấy không có nơi nào có thể lắng nghe những lời than phiền của mình cuối cùng đã tự sát để chứng minh mình vô tội. Mạnh Uyển chờ đợi bảy năm sau và tập hợp chín người để tìm kiếm công lý cho bạn mình. Trong quá trình đó, cuộc đấu tranh của một cô gái trẻ bị thời gian chôn vùi dần lộ diện.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Janice Wu","avatar":""},{"name":"Li Jiahang","avatar":""},{"name":"Hu Yixuan","avatar":""},{"name":"Qiao Zhenyu","avatar":""},{"name":"Bai Shu","avatar":""},{"name":"Zhang Kangle","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324253);
