INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-the', 'Tam Thể', 'Three Body', 'https://phimimg.com/upload/vod/20240304-1/7f03dff2e4dcef5a0264d8d816b1b941.jpg', 'https://phimimg.com/upload/vod/20240304-1/a884dbd9df537e5ada2937cac3feed10.jpg', '<p>Một chuyên gia về vật liệu nano nhìn thấy đồng hồ đếm ngược bí ẩn xuất hiện trong tầm nhìn của anh ta và thấy mình đang bị quân đội điều tra. Để làm sáng tỏ bí ẩn, anh tham gia trò chơi VR Three-Body được phát triển bởi một tổ chức bí mật ETO và khám phá ra sự thật đằng sau cái chết của hàng chục nhà khoa học và một bi kịch từ thời Cách mạng Văn hóa.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Lỗ Nhất","avatar":""},{"name":"Vu Hoà Vỹ","avatar":""},{"name":"Trần Cẩn","avatar":""},{"name":"Vương Tử Văn","avatar":""},{"name":"Lâm Vĩnh Kiện","avatar":""},{"name":"Lý Tiểu Nhiễm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324253);
