INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-yeu-2023', 'Con Yêu', 'Dear Child', 'https://phimimg.com/upload/vod/20240314-1/5a14e1ca7c2c02b67c78d8c86f5272d1.jpg', 'https://phimimg.com/upload/vod/20240314-1/76fe9e565b92160115228b9e376c1966.jpg', '<p>Một người phụ nữ bí ẩn trốn thoát khỏi nơi giam cầm đầy kinh hoàng, giúp các nhà điều tra tìm ra sự thật đen tối đằng sau vụ mất tích chưa có lời giải 13 năm trước.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Kim Riedle","avatar":""},{"name":"Naila Schuberth","avatar":""},{"name":"Sammy Schrein","avatar":""},{"name":"Hans Löw","avatar":""},{"name":"Haley Louise Jones","avatar":""},{"name":"Justus von Dohnányi","avatar":""},{"name":"Julika Jenkins","avatar":""},{"name":"Christian Beermann","avatar":""},{"name":"Seraphina Maria Schweiger","avatar":""},{"name":"Özgür Karadeniz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
