INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-xuat-ngoc-mon', 'Tây Xuất Ngọc Môn', 'Parallel World', 'https://phimimg.com/upload/vod/20240314-1/36582ecead522b7d7bd458274b12662f.jpg', 'https://phimimg.com/upload/vod/20240314-1/dbfd01fb56969bd5b921d19fd9d9f05d.jpg', '<p>Mỹ nữ bán dưa Diệp Lưu Tây và thợ rối bóng Tiểu Phạm, một người đi tìm lời giải về thân thế, một người đi tìm thi thể bạn gái, hai người hợp tác vào sâu trong sa mạc. Ở nơi không người, những hiện tượng kì lạ liên tục xuất hiện, hướng bọn họ đến tàn tích phong hóa đã lâu Ngọc Môn Quan. Hai người chiến đấu với Vũ Lâm Vệ, Phương Sĩ, Mắt Bọ Cạp, giữa vô vàn sự kiện dần tìm ra chân tướng, cũng nhận ra tình yêu đích thực qua nhiều lần thử thách sinh tử. Sự thật tưởng chừng đã gần kề, nhưng họ lại vướng vào một âm mưu lớn hơn.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nghê Ni","avatar":""},{"name":"Bạch Vũ","avatar":""},{"name":"Kim Hãn","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Trương Nghệ Thượng","avatar":""},{"name":"Triệu Đạt","avatar":""},{"name":"Hạ Mộng","avatar":""},{"name":"Lý Vân Nhuệ","avatar":""},{"name":"Lư Dực Hiểu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
