INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-truoc', 'Đêm Trước', 'The Eve', 'https://phimimg.com/upload/vod/20240314-1/499abadb2a761392eee5959e8c698d73.jpg', 'https://phimimg.com/upload/vod/20240314-1/0c12cf682eea7763286da520796e3364.jpg', '<p>Đêm Trước - The Eve 2023 là một bộ phim Việt Sub Thuyết Minh đầy hấp dẫn và đầy sự kịch tính. Câu chuyện xoay quanh thành viên của bang hội Lâm Tích, người đã trà trộn tại bến tàu và bị cuốn vào cuộc chiến tình báo giữa quân thống và địch Nhật xâm lược.Một chiếc chìa khóa quan trọng đã đưa anh ta gặp gỡ Tô Nam - một nữ sinh viên tiến bộ và Châu Ứng Quần - một đặc công quân thống chính trực với nguyên tắc. Dần dần, sự thật về chiếc chìa khóa được bật mí, khiến cuộc chiến giữa các băng nhóm và quốc gia trở nên hỗn loạn.Trong quá trình đấu tranh, Lâm Tích, Châu Ứng Quần và Lý Vân Phi đã trải qua nhiều khó khăn và nguy hiểm, trở thành những người anh em tốt. Lâm Tích cũng phát sinh tình cảm với Tô Nam, và lòng anh ta dần hướng về tín ngưỡng chủ nghĩa cộng sản.Sau 7 năm, ba người anh em cuối cùng cũng gặp lại nhau tại Cẩm Châu. Mỗi người đều đã có mục tiêu riêng và cạnh tranh lẫn nhau trong cuộc chiến tình báo cho các phe cánh mà họ đại diện. Thù mới hận cũ, lý tưởng trái ngược, và trong cuộc chiến tình báo và cuộc sống đầy nguy hiểm này, ba người anh em thản nhiên chấp nhận số phận của mình, hiểu và ủng hộ lẫn nhau. Họ cùng nhau dùng máu thịt, yêu hận và lý tưởng lớn lao để phá giải âm mưu của kẻ địch, và kiên trì giữ vững lý tưởng và niềm tin trong lòng mình.Bộ phim Đêm Trước - The Eve 2023 là một bộ phim Việt Sub Thuyết Minh chủ đề tình báo, mang đến cho khán giả những trải nghiệm đầy hấp dẫn và kịch tính. Câu chuyện xoay quanh nhân vật chính Lâm Tích, một thành viên của bang hội Lâm Tích, người đã tham gia cuộc chiến tình báo giữa quân thống và địch Nhật xâm lược.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 17, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Chí Vỹ","avatar":""},{"name":"Âu Hào","avatar":""},{"name":"Trương Huệ Văn","avatar":""},{"name":"Vương Nghệ Triết","avatar":""},{"name":"Nhậm Hựu Luân","avatar":""},{"name":"A Lệ Á","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
