INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-do-ban', 'Vùng Dơ Bẩn', 'The Dirty South', 'https://phimimg.com/upload/vod/20240402-1/1feeab7e5d37d4e870046bea793d5237.jpg', 'https://phimimg.com/upload/vod/20240402-1/a470b872a6aa9d955183cd58dee270bb.jpg', '<p>Nội dung của phim xoay quanh Sue Parker, do Willa Holland thủ vai, cô phải đối mặt với cuộc chiến tuyệt vọng để cứu vãn doanh nghiệp gia đình đang trên bờ vực sụp đổ do sự sao lãng của cha cô. Khi một người lang thang đẹp trai, do Shane West thủ vai, xuất hiện trong thị trấn, Sue coi anh ta là cơ hội duy nhất để ngăn chặn việc quán bar gia đình rơi vào tay một đại gia địa phương tàn nhẫn, do Dermot Mulroney thủ vai. Kế hoạch đơn giản ban đầu để cứu vãn gia đình nhanh chóng trở nên phức tạp hơn với tội phạm, pháp luật và hậu quả chết người.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Willa Holland","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Shane West","avatar":""},{"name":"Laura Cayouette","avatar":""},{"name":"Gissette E. Valentin","avatar":""},{"name":"Mike C. Manning","avatar":""},{"name":"Wayne Pére","avatar":""},{"name":"Billy Hayes","avatar":""},{"name":"Andrew Vogel","avatar":""},{"name":"Marie Gibeault","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
