INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-cau-be-but-chi-dai-chien-sieu-nang-luc-sushi-bay', 'Shin Cậu Bé Bút Chì: Đại Chiến Siêu Năng Lực Sushi Bay', 'New Dimension! Crayon Shinchan the Movie: Battle of Supernatural Powers ~Flying Sushi~', 'https://phimimg.com/upload/vod/20240402-1/b276028afafe282dd663cf4f663a9aa4.jpg', 'https://phimimg.com/upload/vod/20240402-1/aacaa3832da866af1bbc76e41ed2fa62.jpg', '<p>3DCG! Shin Cậu Bé Bút Chì: Đại Chiến Siêu Năng Lực ~Sushi Bay~ xoay quanh câu chuyện về hai nguồn sáng đặc biệt từ vũ trụ mang theo siêu năng lực đặc biệt tới Trái Đất. Một nguồn sáng tích cực “nhập” vào nhóc Shin, khiến cặp mông núng nính của cậu chàng trở nên nóng bỏng và có khả năng điều khiển những đồ vật xung quanh theo ý muốn.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yumiko Kobayashi","avatar":""},{"name":"Miki Narahashi","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Suzuki Mogura","avatar":""},{"name":"Tori Matsuzaka","avatar":""},{"name":"Mizukawa Katamari","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324253);
