INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-long-nhan', 'Sát Long Nhân', 'ラグナクリムゾン', 'https://phimimg.com/upload/vod/20240305-1/cd0a2cab1d2621d1097190e6f0407079.jpg', 'https://phimimg.com/upload/vod/20240305-1/09c5447c07081197a427a525619d756f.jpg', '<p>Ragna là một thợ săn rồng &quot;kém cỏi&quot;. Anh có một cô em gái vô cùng mạnh mẽ. Một ngày nọ một kẻ địch cực mạnh xuất hiện, đe dọa sinh mạng của em gái Ragna. Lúc này, một nhân vật lạ mặt xuất hiện - ông ta chính là Ragna trong tương lai và đang nắm giữ một sức mạnh vô cùng lớn. Ragna tương lai căm ghét sức mạnh của mình, nhưng Ragna hiện tại thì cần nó! Tương lai trao lại sức mạnh cho quá khứ và rồi một thợ săn rồng hùng mạnh ra đời!</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Chiaki Kobayashi","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Shunsuke Takeuchi","avatar":""},{"name":"Kozo Shioya","avatar":""},{"name":"Nobutoshi Canna","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324253);
