INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('salaar-phan-1-lenh-ngung-ban', 'Salaar: Phần 1 - Lệnh Ngừng Bắn', 'Salaar: Part 1 - Ceasefire', 'https://phimimg.com/upload/vod/20240402-1/6fd8f4d3f048514d5c126c5b8961ec87.jpg', 'https://phimimg.com/upload/vod/20240402-1/c1ecdbdd997ea910db1d956abe475983.jpg', '<p>Phim nói về Devaratha Deva Raisaar (do Prabhas thủ vai), người dính líu đến các cuộc đấu tranh quyền lực và chính trị phức tạp tại thành phố hư cấu Khansaar. Khansaar, một khu vực tuyên bố tự trị khỏi Ấn Độ vào năm 1947 và từ đó được cai trị bởi các bộ lạc và vua chúa.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Prabhas","avatar":""},{"name":"Prithviraj Sukumaran","avatar":""},{"name":"Shruti Haasan","avatar":""},{"name":"Easwari Rao","avatar":""},{"name":"Jagapati Babu","avatar":""},{"name":"Bobby Simha","avatar":""},{"name":"Sriya Reddy","avatar":""},{"name":"Ramachandra Raju","avatar":""},{"name":"Mime Gopi","avatar":""},{"name":"Tinnu Anand","avatar":""},{"name":"Pramod Panju","avatar":""},{"name":"Ramana","avatar":""},{"name":"John Vijay","avatar":""},{"name":"M. S. Chowdhary","avatar":""},{"name":"Vajrang Shetty","avatar":""},{"name":"Brahmaji","avatar":""},{"name":"Shafi","avatar":""},{"name":"Devaraj","avatar":""},{"name":"Saurav Lokesh","avatar":""},{"name":"Chelu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324253);
