INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-tinh-tinh', 'Đế Chế Tinh Tinh', 'Chimp Empire', 'https://phimimg.com/upload/vod/20240314-1/a67a8d140404e3882b4c70b1ac2ee038.jpg', 'https://phimimg.com/upload/vod/20240314-1/bd4bad899239222c1b9562a67703cac4.jpg', '<p>Một cộng đồng tinh tinh lớn mạnh trong một khu rừng ở Uganda. Chúng xoay xở với chính trị xã hội phức tạp, các mối quan hệ trong gia đình và cuộc chiến giành lãnh thổ nguy hiểm.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324253);
