INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-chu-cua-ta', 'Thành Chủ Của Ta', 'The Castellan Belongs To Me', 'https://phimimg.com/upload/vod/20240314-1/f3482e1c4423336e1f08c556b6053b09.jpg', 'https://phimimg.com/upload/vod/20240314-1/c5a9992f8b380071e228c776973c1721.jpg', '<p>Ngô Lâm vì nhiệt tình giúp người bạn Hứa Hề Hề sửa đoạn kết cho cuốn tiểu thuyết, đã xuyên không vào trong cuốn tiểu thuyết đó và trở thành nhân vật bản thân ghét nhất - phu nhân thành chủ thành Đông Lâm - Ngô Ngọc Lâm. Đối lập với cách hành xử của nữ chính trong tiểu thuyết, Ngô Lâm chán ghét chuyện đấu đá tranh sủng, phản đối việc vì đàn ông và quyền lực mà không từ thủ đoạn. Một mặt, cô nghĩ đủ mọi cách để quay về hiện thực viết nốt bản thảo, mặt khác cô cố hết sức để đảo ngược cốt truyện sáo rỗng, nhưng lại không may rơi vào âm mưu đoạt vị của đệ đệ thành chủ - Tống Dịch. Cuối cùng, cô đã đưa ra một quyết định táo bạo...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Trí Linh","avatar":""},{"name":"Lỗ Chiếu Hoa","avatar":""},{"name":"Kim Vũ Bá","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324253);
