INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tung-la-thieu-nien', 'Từng Là Thiếu Niên', 'Once And Forever', 'https://phimimg.com/upload/vod/20240314-1/ea3a6603a6865766ad8ad5500390dc61.jpg', 'https://phimimg.com/upload/vod/20240314-1/9e6f5873fc6c353124febc49bcaf3923.jpg', '<p>Câu chuyện kể về nhóm thanh niên cuối thập niên 80 tại Bắc Kinh, họ theo đuổi ước mơ, nỗ lực tận dụng cơ hội thời đại, trải qua những cuộc đua vì sự nghiệp và tình yêu tuyệt vời. Định mệnh của họ được gắn kết với thời đại, giống như chúng ta, mặc dù trải qua gian khổ, nhưng nhờ nỗ lực cá nhân, tích cực và luôn tiến lên. Mong mỗi người không làm trái với tuổi trẻ đã từng có</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zray Zhang","avatar":""},{"name":"Quan Hiểu Đồng","avatar":""},{"name":"Phạm Thừa Thừa","avatar":""},{"name":"Nikki","avatar":""},{"name":"Jiang Pei Yao","avatar":""},{"name":"Mao Xiao Hui","avatar":""},{"name":"Ye Xiao Wei","avatar":""},{"name":"Từ Thiệu Anh","avatar":""},{"name":"Zhang Xiao Yu","avatar":""},{"name":"Mao Le","avatar":""},{"name":"Zhao Zi Qi","avatar":""},{"name":"Wenling Li","avatar":""},{"name":"Hai Yi Tian","avatar":""},{"name":"Mercury","avatar":""},{"name":"Sun Gui Tian","avatar":""},{"name":"Wang Xin","avatar":""},{"name":"Qi Xiang","avatar":""},{"name":"Su Meng Yun","avatar":""},{"name":"Yiwen Zhang","avatar":""},{"name":"Wang Xiao Mu","avatar":""},{"name":"Stell","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
