INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tung-la-thieu-nien', 'Từng Là Thiếu Niên', 'Once And Forever', 'từng là thiếu niên once and forever zray zhang quan hiểu đồng phạm thừa thừa nikki jiang pei yao mao xiao hui ye xiao wei từ thiệu anh zhang xiao yu mao le zhao zi qi wenling li hai yi tian mercury sun gui tian wang xin qi xiang su meng yun yiwen zhang wang xiao mu stell ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-sach-ky-dieu-mua-he', 'Cuốn Sách Kỳ Diệu Mùa Hè', 'My Marvellous Fable', 'https://phimimg.com/upload/vod/20240314-1/5c0976f5124195a045ac86dc2570998a.jpg', 'https://phimimg.com/upload/vod/20240314-1/ecae777812a8a8ce493922ea7cb05d91.jpg', '<p>Nhiệm vụ đầu tiên của biên tập viên thực tập Phùng Thiên Lam là giục nhà văn Vương Bồ Đào giao bản thảo, còn Vương Bồ Đào lại yêu cầu Phùng Thiên Lam chở cô về quê làm điều kiện viết sách. Thì ra Vương Bồ Đào rất xa cách với bố mình, đi làm xa nhiều năm không chịu về quê, đến khi hay tin bố mắc bệnh Alzheimer, cô đành phải trở về. Trên đường đi, cô sáng tác còn anh sắp xếp bản thảo. Câu chuyện phản ánh cuộc đời của chính Vương Bồ Đào ở các giai đoạn khác nhau. Trong quá trình sáng tác, Vương Bồ Đào tự ngẫm lại bản thân, bớt đề phòng Phùng Thiên Lam, cũng dần dần hòa giải với quá khứ. Cô trở về gặp bố với tấm lòng chân thành, xóa bỏ xa cách suốt nhiều năm, một lần nữa được bao bọc bởi hơi ấm tình thân và tình yêu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Phi Phi","avatar":""},{"name":"Ngụy Triết Minh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
