INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-tien-sinh-khong-giong-nhu-vay', 'Tiêu Tiên Sinh Không Giống Như Vậy', 'A Different Mr. Xiao', 'https://phimimg.com/upload/vod/20240314-1/aba7b71522e2acf6a627ede6fbd96a7b.jpg', 'https://phimimg.com/upload/vod/20240314-1/fe2c45cef15bdc45f7cb7eab25c0a6cf.jpg', '<p>Sinh viên năm tư học viện y học cổ truyền Tống Ức Quất, từ lâu rồi cô đã dựa dẫm vào sự giúp đỡ của trợ giảng Tiêu Tĩnh để đủ điểm qua môn. Cả hai quen biết nhau đã lâu và luôn duy trì một mối quan hệ đôi bên cùng có lợi. Tuy nhiên, sau khi có một ngôi sao băng ban ngày xẹt qua thì Tiêu Tĩnh lại liên tục thay đổi, khiến cô nàng biếng học nhác làm Tống Ức Quất biếng ngơ ngác chẳng hiểu gì, trong long dấy lên cảnh báo. Sự thật thì Tiêu Tĩnh của bây giờ là người đến từ tương lai. Vì muốn có được dược liệu quý hiếm mà anh phải vượt thời không để tiếp cận ông của Tống Ức Quất, chờ đợi cơ hội ra tay lấy đi. Tuy nhiên, lại xuyên không lệch tận 3 tháng, ông của Tống ỨC Quất đã giao cô cho anh chăm sóc, mọi chuyện đều rối tung rối mù lên.Để đạt được mục tiêu, Tiêu Tĩnh đành ép bản thân xã giao, nhưng anh ta dần bị nữ sinh Tống Ức Quất làm tan chảy, tìm được liều thuốc cho tâm hồn. Nhưng sự chia ly vẫn đang chực chờ ở tương lai…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yiqin Zhao","avatar":""},{"name":"Duan Xing Yu","avatar":""},{"name":"Liu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324253);
