INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-bat-ke-sat-nhan-phan-3', 'Truy Bắt Kẻ Sát Nhân (Phần 3)', 'Catching Killers (Season 3)', 'https://phimimg.com/upload/vod/20240314-1/4d6f83391542ad656b9f7bd5e1a184a6.jpg', 'https://phimimg.com/upload/vod/20240314-1/a618f622cf35b9ebbb3d3a95e2db1b94.jpg', '<p>Những cuộc điều tra có thật thuật lại câu chuyện về những kẻ sát nhân máu lạnh, nỗ lực tuyệt vọng để ngăn chặn chúng và những người dũng cảm đưa chúng ra trước công lý.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324253);
