INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-ha-chi-chua-toi', 'Em Là Hạ Chí Chưa Tới', 'Summer Solstice', 'https://phimimg.com/upload/vod/20240314-1/6d7245ac624d99a34df801b5ad6d5dea.jpg', 'https://phimimg.com/upload/vod/20240314-1/d1cf83b86721ddf19f63ed8cd2696942.jpg', '<p>Cô gái hoạt bát Hạ Ương Ương gặp phải tình cảnh chồng sắp cưới ngoại tình cùng em gái cùng cha khác mẹ. Sau khi quyết định chia tay, duyên số run rủi thế nào mà cô lại đăng ký kết hôn với tổng giám đốc bá đạo Cố Kỳ Thâm. Hạ Ương Ương sợ mình sẽ bị lừa gạt, nhưng nào ngờ cô lại được Cố Kỳ Thâm vô cùng nuông chiều. Hai người ở bên nhau ngày càng ngọt ngào, mọi chuyện đều đẹp như mơ. Nhưng sau khi ánh trăng sáng của Hạ Kỳ Thâm về nước, mọi thứ đều chấm dứt. Liệu chuyện tình giữa một Hạ Ương Ương dám yêu dám hận và một Cố Kỳ Thâm nặng tình, sống nội tâm sẽ thế nào đây?<br/>&nbsp;</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Nhã Thiến","avatar":""},{"name":"Lý Thiên Kỳ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
