INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('schmigadoon-phan-2', 'Schmigadoon! (Phần 2)', 'Schmigadoon! (Season 2)', 'https://phimimg.com/upload/vod/20240314-1/71af88df22e6c137f44ef1a28db30039.jpg', 'https://phimimg.com/upload/vod/20240314-1/219bc77ef947aa126a22ab5dba366e38.jpg', '<p>Josh và Melissa bỏ lỡ điều kỳ diệu mà họ cảm nhận được ở Schmigadoon và trong nỗ lực quay trở lại, họ thấy mình đang ở Schmicago—thế giới được mô phỏng lại của các vở nhạc kịch thập niên 60 và 70.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keegan-Michael Key","avatar":""},{"name":"Cecily Strong","avatar":""},{"name":"Dove Cameron","avatar":""},{"name":"Ariana DeBose","avatar":""},{"name":"Jaime Camil","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Ann Harada","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Aaron Tveit","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324253);
