INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-lo-trieu-duong', 'Nhất Lộ Triều Dương', 'All The Way To The Sun', 'https://phimimg.com/upload/vod/20240314-1/b4f28183ace83e3a0421baaa25fb0413.jpg', 'https://phimimg.com/upload/vod/20240314-1/9ee2ad33432eb122e33aaec586d009d1.jpg', '<p>Phim kể về cô gái Lý Mộ Gia từ tỉnh lẻ lên Bắc Kinh, làm việc ở một văn phòng luật nổi tiếng nhất Bắc Kinh, dựa vào năng lực của bản thân phấn đấu từ vị trí trợ lý đến luật sư đại diện nổi tiếng. Sau đó bất ngờ chuyển hướng sang khởi nghiệp, sau thành công và thất bại thì đã khởi nghiệp thành công, làm chủ một công ty. Đây là câu chuyện có mốc thời gian trải dài từ năm 2007 đến năm 2019, kể về ba cô gái đối diện với những khao khát cuộc sống và hiện thực mà phải luôn thay đổi mình, sau hơn mười năm bầu bạn đã đạt được thành tựu cuộc đời, đi về hướng ánh sáng.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2023, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"ý Lan Địch","avatar":""},{"name":"Vương Dương","avatar":""},{"name":"Vương Cúc","avatar":""},{"name":"Cao Diệp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324253);
