INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-kiem-si', 'Trái Tim Kiếm Sĩ', 'Duangjai Jom Krabi (Tales Of Grandmaster)', 'https://phimimg.com/upload/vod/20240314-1/246e554b798ae4a648641c5ba1565067.jpg', 'https://phimimg.com/upload/vod/20240314-1/b1c7ec45f072ef12dbe8aab8ea4dcc5d.jpg', '<p>Trái Tim Kiếm Sĩ - Tales of Grandmaster có nội dung xoay quanh Nalin - một vlogger nghiệp dư, sống thoải mái nhờ tài sản thừa kế bố mẹ để lại cho cô. Một ngày nọ, cô leo lên một ngọn núi và bị rơi xuống thung lũng! Nalin sống sót, nhưng bên cạnh cô ấy, cô ấy nhìn thấy một người đàn ông đẹp trai mặc quần áo lạ đang nằm bất tỉnh. Khi tỉnh dậy, anh ấy giới thiệu với cô ấy mình là Wang Yitian - anh hùng của cuốn tiểu thuyết Truyền thuyết về thanh kiếm mà cô ấy từng nghiện đọc. Trên thực tế, Wang Yitian xuất hiện trong thế giới của Nalin vì chính anh ấy cầu nguyện được gặp và bảo vệ người phụ nữ trong mơ của anh ấy. Và chính anh sau đó cũng đã bảo vệ Nalin khỏi vụ ám sát của người chú tham lam, xảo quyệt.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Bright Norraphat Vilaiphan","avatar":""},{"name":"Plengkwan Nattaya Thongsaen","avatar":""},{"name":"Neng Sarun Esther Supreeleela","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
