INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-thoai-doc-nhat', 'Đồng Thoại Độc Nhất', 'Exclusive Fairy Tale', 'đồng thoại độc nhất exclusive fairy tale jun miaoyi zhang aobo lv zhao henry jiatai tan 林晨怡 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toan-tu-tan-to', 'Toàn Tư Tấn Tổ', 'An Actor''s Rhapsody', 'https://phimimg.com/upload/vod/20240314-1/40cc6be6ba2ecfff2f9a84a9af77efb4.jpg', 'https://phimimg.com/upload/vod/20240314-1/f0aaa8ae43eed57c94b2724b219bc5ad.jpg', '<p>Đây là câu chuyện về một nhà tư bản giàu trí tưởng tượng, người đã tài trợ toàn bộ cho một đội sản xuất để thực hiện ước mơ trở thành nam chính trong các bộ phim truyền hình cổ trang. Việc viết lại kịch bản một cách điên cuồng của anh ấy dẫn đến một cốt truyện rời rạc. Nhà biên kịch thấp hèn và tội nghiệp bất lực để chống lại, cố gắng lấp đầy những khoảng trống và sự mâu thuẫn trong tuyệt vọng mặc dù họ sắp rụng hết tóc. Kết quả là một sự khác biệt hoàn toàn so với phong cách ban đầu, với việc phát triển nhân vật liên tục không hiệu quả. Từ cung đình đến trinh thám, từ trinh thám đến kỳ ảo, từ kỳ ảo đến võ hiệp, từ võ hiệp đến cuộc sống cung đình, từ cuộc sống cung đình đến xuyên không... xuyên phá bức tường không gian. Tất cả các thể loại phim truyền hình lịch sử tập hợp lại với nhau, chuyển hướng thành một chủ đề đa dạng. Với những nỗ lực của họ, thể loại giả tưởng sẽ lần đầu tiên được xuất hiện, linh hồn nam chính mặt lạnh kỳ thật là một mảnh băng cổ tồn tại mấy ngàn năm; hậu cung phi thường hài hòa, tình nghĩa chị em sâu nặng; quá trình phá án của các cận vệ hoàng gia đầy hồi hộp nhưng kẻ sát nhân không bao giờ được tìm thấy trong suốt bộ phim; một thư sinh trên đường đến kỳ thi hoàng gia bất ngờ đăng quang quán quân của thế giới võ lâm thông qua một khoản đầu tư của một cô gái giàu có; cáo nam vừa thiện vừa ác, và nữ thợ săn yêu quái thường xuyên thay đổi tính cách, không thể cưỡng lại cám dỗ và trở thành kẻ thù vì tình yêu. Ngay cả con chó của bạn nhân vật chính, được mang đến phim trường trong một chuyến thăm, cũng được biến thành một linh hồn để thêm vào câu chuyện, với một tình tiết phụ lãng mạn được thêm vào... Tuy nhiên, đằng sau tất cả sự phi lý, bạn sẽ phát hiện ra rằng anh ấy là một diễn viên đang theo đuổi ước mơ của mình và cứu chuộc với niềm đam mê không thể kiềm chế.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Teng Yue","avatar":""},{"name":"morgan","avatar":""},{"name":"Rosalyn Luo","avatar":""},{"name":"Yang Zhiwen","avatar":""},{"name":"Chen Jingyang","avatar":""},{"name":"Seven Zou","avatar":""},{"name":"Gao Wei Wan","avatar":""},{"name":"Guan Bo","avatar":""},{"name":"Li Feng Wei","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324253);
