INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-on-dung-sung-toi-phan-5', 'Làm Ơn Đừng Sủng Tôi (Phần 5)', 'Please Don''t Spoil Me (Season 5)', 'https://phimimg.com/upload/vod/20240314-1/185d73dc2da0a83b0b9689b869c6755d.jpg', 'https://phimimg.com/upload/vod/20240314-1/38a31d688dfe986fe687ece9c4dd2484.jpg', '<p>Cuối cùng thì trí nhớ Nhan Nhất Nhất cũng đã được đánh thức bởi tình yêu của Tần Ngự, hai người bắt đầu một mối tình say đắm cuồng nhiệt. Nhưng cơ thể của Nhan Nhất Nhất liên tục gặp khủng hoảng vì Tần Ngự đã ở lại thế giới thực quá lâu. Để bảo vệ người mình yêu, Tần Ngự buộc phải nén đau thương, lựa chọn trở về thế giới trong sách. Cặp đôi số khổ này lại một lần nữa phải đối mặt với sinh tử chia lìa.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Miểu","avatar":""},{"name":"Di Kim","avatar":""},{"name":"Hiền Chính","avatar":""},{"name":"Phổ Phổ","avatar":""},{"name":"Vương Tử Phi","avatar":""},{"name":"Đường Hạo","avatar":""},{"name":"Vương Long","avatar":""},{"name":"Hàn Giai","avatar":""},{"name":"Hủy Uông","avatar":""},{"name":"Dĩnh Phi","avatar":""},{"name":"Chu Thiên","avatar":""},{"name":"Tiêu Mã","avatar":""},{"name":"Thiến Thiến","avatar":""},{"name":"Vu Bỉnh Trì","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324253);
