INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lam-on-dung-sung-toi-phan-5', 'Làm Ơn Đừng Sủng Tôi (Phần 5)', 'Please Don''t Spoil Me (Season 5)', 'làm ơn đừng sủng tôi (phần 5) please don''t spoil me (season 5) trương miểu di kim hiền chính phổ phổ vương tử phi đường hạo vương long hàn giai hủy uông dĩnh phi chu thiên tiêu mã thiến thiến vu bỉnh trì ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ke-hoa-luu-ly', 'Chuyện Kể Hoa Lưu Ly', 'Royal Rumours', 'https://phimimg.com/upload/vod/20240314-1/e8bf81eea68c06fb0d282d21b26508d4.jpg', 'https://phimimg.com/upload/vod/20240314-1/ed28376cceb6e7dee42b0a43e97b7b9e.jpg', '<p>Những năm Xương Long nước Đại Tấn, Hộ quốc tướng quân Hoa Ứng Đình vừa đánh bại Kim Phách, lập chiến công hiển hách, đã đưa cô con gái duy nhất được nâng niu như viên ngọc quý là Hoa Lưu Ly trở về kinh thành. Từ nhỏ Hoa Lưu Ly đã theo phụ thân, huynh đệ sống ở quân doanh nơi biên ải, tuy là con gái nhưng trời sinh thông minh, còn rèn luyện được võ nghệ cao cường. Tuy nhiên, kinh thành không giống biên ải. Một mặt, lời đồn nhà họ Hoa sở hữu quân đội nên không phục triều đình xôn xao khắp nơi, mặt khác, Nhị hoàng tử Cơ Nguyên Tố không phải là trưởng tử mà lại được sắc phong Thái tử, còn lông bông chẳng ra gì đã dấy lên xôn xao khắp kinh thành. Những tưởng Hoa Lưu Ly đã bước vào tâm bão, nhưng cô hoàn toàn không hành động theo lẽ thường. Suốt hành trình cô luôn tẩm ngẩm tầm ngầm mà đấm chết voi, giấu mình đóng giả thành người yếu đuối bệnh tật, một mình xử lý cả giới tiểu thư danh giá. Hơn thế nữa, cô còn khiến Thái tử và hoàng tử nước Kim Phách mê đắm, biến bộ phim mưu quyền đoạt ngôi thành bộ phim tình yêu ngọt ngào mà đầy hài hước....</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Chính Khê","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Chu Nguyên Băng","avatar":""},{"name":"Tô Mộng","avatar":""},{"name":"Vân Y","avatar":""},{"name":"Vân Hạc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324253);
