INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tharntype-the-series-2-moi-tinh-7-nam', 'TharnType The Series 2: Mối Tình 7 Năm', 'TharnType 2: 7 Years Of Love', 'https://phimimg.com/upload/vod/20240314-1/c46955b91e61d603be3cd67f4a7902a3.jpg', 'https://phimimg.com/upload/vod/20240314-1/10e2bc8760cd756165bd65bff7f16d8c.jpg', '<p>Từ ghét nhau đến thích nhau, Tharn và Type đã ở bên nhau bảy năm, nhưng cuộc sống ở thế giới người lớn không phải lúc nào cũng đầy hoa thơm và trái ngọt. Không chỉ cuộc sống công việc, mà cả kẻ thứ ba cũng thách thức mối quan hệ của họ. Họ có thể khắc phục được khó khăn gặp phải hay không?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mew Suppasit Jongcheveevat","avatar":""},{"name":"Gulf Kanawut Traipipattanapong","avatar":""},{"name":"Ja Phachara Suansri","avatar":""},{"name":"First Chalongrat Novsamrong","avatar":""},{"name":"Boat Napat Srinakluan","avatar":""},{"name":"Tanatorn Saenangkanikorn","avatar":""},{"name":"Mild Suttinut Uengtrakul","avatar":""},{"name":"Tong Thanayut Thakoon-auttaya","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324253);
