INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-luc-gap-duoc-em', 'Đúng Lúc Gặp Được Em', 'Hi Producer!', 'https://phimimg.com/upload/vod/20240314-1/a620de585e68b6ae276072b285168036.jpg', 'https://phimimg.com/upload/vod/20240314-1/b917a6dd85de19a2542c29fbc7a7fba6.jpg', '<p>Bộ phim kể về câu chuyện của một nhóm chương trình tạp kỹ với đạo diễn văn học Ngư Tại Tảo và chuyên gia di tích văn hóa trẻ tuổi Đào Đường nhằm thể hiện vẻ đẹp của nền văn minh Trung Quốc, cùng hợp tác để khởi động một chương trình truyền hình văn hóa.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guo Xiaodong","avatar":""},{"name":"Guo Xiao Dong","avatar":""},{"name":"Nan Zhang","avatar":""},{"name":"Lý Tiểu Nhiễm","avatar":""},{"name":"Jaco Zhang","avatar":""},{"name":"Zheng Kai","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
