INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-bai-noi-dau-song-phan-2', 'Thành Bại Nơi Đầu Sóng (Phần 2)', 'Make Or Break (Season 2)', 'https://phimimg.com/upload/vod/20240314-1/686d580e57777196c035af705cfd2479.jpg', 'https://phimimg.com/upload/vod/20240314-1/dffd2cb10d19c87e4835018a46c0bbf3.jpg', '<p>Hòa mình vào thế giới lướt sóng chuyên nghiệp với tư cách là người giỏi nhất trong môn thể thao này đi khắp thế giới để tranh chức vô địch Thế giới. Với khả năng tiếp cận chưa từng có, loạt phim tài liệu này ghi lại cuộc sống của các vận động viên trong chuyến lưu diễn và những hy sinh mà họ thực hiện để đạt đến đỉnh cao.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324254);
