INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-vuong-chau-phi-njinga', 'Nữ Vương Châu Phi: Njinga', 'African Queens: Njinga', 'https://phimimg.com/upload/vod/20240314-1/ab55214a404497d1d0134a2975320d37.jpg', 'https://phimimg.com/upload/vod/20240314-1/f0a428f6fa5319cac2701f05a210c1a2.jpg', '<p>Do Jada Pinkett Smith chỉ đạo sản xuất và dẫn chuyện, loạt phim tài liệu này về nữ vương chiến binh Njinga của Angola có các cuộc phỏng vấn với chuyên gia và phân cảnh tái hiện.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jada Pinkett Smith","avatar":""},{"name":"Oni Adesuwa","avatar":""},{"name":"Chipo Kureya","avatar":""},{"name":"Marilyn Nnadebe","avatar":""},{"name":"Philips Nortey","avatar":""},{"name":"Thabo Rametsi","avatar":""},{"name":"Cory Hippolyte","avatar":""},{"name":"Zethu Dlomo","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324254);
