INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-vuong-gia', 'Khách Sạn Vương Giả', 'King The Land', 'https://phimimg.com/upload/vod/20240314-1/6ba0418a61ce955e172ab21d73d62c4c.jpg', 'https://phimimg.com/upload/vod/20240314-1/8364cf0c68c66c767b15e12e3aeb5259.jpg', '<p>Giữa cuộc chiến thừa kế căng thẳng, một người thừa kế quyến rũ xung đột với một nhân viên mẫn cán nổi tiếng với nụ cười không ai cưỡng nổi, nhưng anh lại thấy không thể chịu nổi.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jun-ho","avatar":""},{"name":"Yoona","avatar":""},{"name":"Go Won-hee","avatar":""},{"name":"Kim Ga-eun","avatar":""},{"name":"Ahn Se-ha","avatar":""},{"name":"Kim Jae-won","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Kim Young-ok","avatar":""},{"name":"Kong Ye-ji","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
