INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-thu-trong-chien-loan', 'Thủy Thủ Trong Chiến Loạn', 'War Sailor', 'https://phimimg.com/upload/vod/20240314-1/f5a52af24a562c762c441090a3a718bc.jpg', 'https://phimimg.com/upload/vod/20240314-1/4ed7e306303d09f7212478a673943c3b.jpg', '<p>Khi Thế chiến II nổ ra, hai thủy thủ trên một tàu buôn Na Uy đối mặt với những điều kiện khắc nghiệt khi họ chiến đấu để sống sót trong cuộc xung đột mà cả hai buộc phải tham gia.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 14, 2023, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Kristoffer Joner","avatar":""},{"name":"Ine Marie Wilmann","avatar":""},{"name":"Pål Sverre Hagen","avatar":""},{"name":"Henrikke Lund Olsen","avatar":""},{"name":"Téa Grønner Joner","avatar":""},{"name":"Siv Torin Knudsen Petersen","avatar":""},{"name":"Armand Hannestad","avatar":""},{"name":"Daniel Berg","avatar":""},{"name":"Noah Nygård","avatar":""},{"name":"Oskar Hallaråker Hellesøy","avatar":""},{"name":"Leon Tobias Slettbakk","avatar":""},{"name":"Alexandra Gjerpen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
