INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moses-cua-binh-nguyen', 'Moses Của Bình Nguyên', 'Why Try To Change Me Now', 'https://phimimg.com/upload/vod/20240309-1/63949451805abbfeaba93ee415194328.jpg', 'https://phimimg.com/upload/vod/20240309-1/2c677558803025117a61c9d76b5a758c.jpg', '<p>Khi vượt qua hai khoảng thời gian khác nhau, một vụ án giết người chưa có lời giải xuất hiện và phá hủy sự yên bình của thị trấn nhỏ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 4, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Tử Kiện","avatar":""},{"name":"Hải Thanh","avatar":""},{"name":"Khâu Thiên","avatar":""},{"name":"Bảo Thạch GEM","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
