INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('moses-cua-binh-nguyen', 'Moses Của Bình Nguyên', 'Why Try To Change Me Now', 'moses của bình nguyên why try to change me now đổng tử kiện hải thanh khâu thiên bảo thạch gem ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-oc-sen-co-tinh-yeu-ban-thai', 'Nếu Ốc Sên Có Tình Yêu (Bản Thái)', 'When A Snail Falls In Love', 'https://phimimg.com/upload/vod/20240309-1/a47fdae3b58a4331cd8f0294fb1862be.jpg', 'https://phimimg.com/upload/vod/20240309-1/e195bc6f797830feea590f0ab1f97606.jpg', '<p>Wita là lính mới thiên tài trong nghiên cứu tâm lý. Trong đầu cô ấy như thể có một chiếc máy tính đang vận hành thần tốc, đây chính là năng khiếu bẩm sinh của cô gái ốc sên. Khi mới vào đội cảnh sát, cô phải đối mặt với việc bị đuổi khỏi đội vì thể lực không đạt yêu cầu. Chỉ có cảnh sát Prat giúp được cô ấy. Vì thế Wita nghĩ mọi cách xin Prat nhận cô làm học trò. Prat là đội trưởng Đội điều tra án đặc biệt của Cục cảnh sát, là thần thám hàng đầu trong đội cảnh sát, kinh nghiệm xử lý vụ án phong phú, võ nghệ hơn người. Ban đầu Prat không hề có thiện cảm với Wita, hai người có khác biệt lớn trong quan điểm phá án, nhưng sau khi cả hai bắt tay phá một loạt vụ án, Prat nảy sinh tình cảm với cô học trò thông minh ngây thơ của mình. Nhưng cô gái chậm chạp như “ốc sên” này không nhận được tín hiệu tình yêu. Khi hai người vừa tình cảm vừa phá án, vụ “giết người hàng loạt” yên ắng đã lâu lại xuất hiện, cuối cùng hai người nhận ra tình cảm đối với nhau trong quá trình điều tra nguy hiểm. Song lúc này, vụ án Luge mà Prat canh cánh trong lòng cũng được khởi động lại, cặp tình nhân nắm tay nhau bước vào hành trình tìm hung thủ đầy khó khăn, nguy hiểm.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Thassapak Hsu","avatar":""},{"name":"Zuvapit Traipornworakit","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
