INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-lost-flowers-of-alice-hart', 'The Lost Flowers Of Alice Hart', 'The Lost Flowers Of Alice Hart', 'https://phimimg.com/upload/vod/20240309-1/4a3bdf012d97366ae78011a03b3e3876.jpg', 'https://phimimg.com/upload/vod/20240309-1/5d3cc94105b73a9a6281a17070a25194.jpg', '<p>Sau khi mất cha mẹ trong một vụ hỏa hoạn bí ẩn, Alice Hart, 9 tuổi, được bà ngoại June nuôi dưỡng tại một trang trại hoa, nơi cô biết được rằng có những bí mật trong bí mật. Nhưng nhiều năm trôi qua, một sự phản bội được phát hiện khiến Alice buộc phải đối mặt với quá khứ của mình.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sigourney Weaver","avatar":""},{"name":"Alycia Debnam-Carey","avatar":""},{"name":"Charlie Vickers","avatar":""},{"name":"Frankie Adams","avatar":""},{"name":"Leah Purcell","avatar":""},{"name":"Alyla Browne","avatar":""},{"name":"Asher Keddie","avatar":""},{"name":"Sebastián Zurita","avatar":""},{"name":"Alexander England","avatar":""},{"name":"Jack LaTorre","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
