INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-cuong-tho', 'Kim Cương Thô', 'Rough Diamonds', 'https://phimimg.com/upload/vod/20240309-1/fc8455182ef814bdcaa73dc2b12e758e.jpg', 'https://phimimg.com/upload/vod/20240309-1/d1f2663d8ea425b97371225f9e01ba5f.jpg', '<p>Khi cậu con trai hoang đàng khiến đế chế của gia đình lâm vào cảnh nợ nần chồng chất, người anh trai xa cách từ lâu trở về quận kim cương Antwerp để khắc phục hậu quả.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Kevin Janssens","avatar":""},{"name":"Ini Massez","avatar":""},{"name":"Robby Cleiren","avatar":""},{"name":"Dudu Fisher","avatar":""},{"name":"Yona Elian","avatar":""},{"name":"Jeroen Van der Ven","avatar":""},{"name":"Marie Vinck","avatar":""},{"name":"Els Dottermans","avatar":""},{"name":"Tine Joustra","avatar":""},{"name":"Casper Knopf","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
