INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-mac-vung-cao', 'Sa Mạc Vùng Cao', 'High Desert', 'https://phimimg.com/upload/vod/20240309-1/b94cf032ee1792129c451340dcb55229.jpg', 'https://phimimg.com/upload/vod/20240309-1/f502b0dc8c4be13d4991f2394c442265.jpg', '<p>Peggy Newman, một phụ nữ có quá khứ đầy trắc trở, đưa ra quyết định thay đổi cuộc đời để trở thành điều tra viên tư nhân sau cái chết của người mẹ thân yêu của cô, người mà cô sống cùng ở thị trấn sa mạc nhỏ Yucca Valley, California.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patricia Arquette","avatar":""},{"name":"Matt Dillon","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Weruche Opia","avatar":""},{"name":"Bernadette Peters","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Jayden Gomez","avatar":""},{"name":"Christine Taylor","avatar":""},{"name":"Jeffrey Vincent Parise","avatar":""},{"name":"Kellen Joseph Quinn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324254);
