INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-ca-phe-chua-lanh', 'Tiệm Cà Phê Chữa Lành', 'Finland Papa', 'https://phimimg.com/upload/vod/20240309-1/734e423aa8972c59e2608140d9fa46e8.jpg', 'https://phimimg.com/upload/vod/20240309-1/267fe3cf3eef63946ae6331ed68dd2ef.jpg', '<p>“Finland Papa” sẽ xoay quanh một quán cà phê mang tên Finland Papa, nơi những người bị tổn thương sâu sắc và cần được chữa lành tìm đến để biết ý nghĩa thực sự của một gia đình đích thực là gì.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 21, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Bo-ra","avatar":""},{"name":"Kim Woo-seok","avatar":""},{"name":"Seong Byeong-sook","avatar":""},{"name":"Hwang Suk-jung","avatar":""},{"name":"Jung Min-sung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
