INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-ve-thanh-chu-dai-nhan-cua-ta', 'Bảo Vệ Thành Chủ Đại Nhân Của Ta', 'My Uncanny Destiny', 'https://phimimg.com/upload/vod/20240309-1/bceaa3488887ffd37d550cb177a0317a.jpg', 'https://phimimg.com/upload/vod/20240309-1/f4a53cacebf0cb2edb58101c336cc844.jpg', '<p>Bảo Vệ Thành Chủ Đại Nhân Của Ta (My Uncanny Destiny) xoay quanh bối cảnh thời cổ đại, thành Mộc A và thành Hiên Nguyệt đã chống lại nhau qua nhiều thế hệ, chiến đấu trong nhiều năm, cố gắng thôn tính nhau. Thành chủ cũ của thành Mộc A không có con, chỉ có cô con gái duy nhất là Diệp Chiêu Nam. Thành chủ cũ lo lắng Chiêu Nam kế vị sẽ khiến các gia tộc tranh đoạt quyền lực nên đã bí mật giấu giếm giới tính của con gái mình và ra lệnh cho Chiêu Nam từ nhỏ phải đóng giả là nam nhi. Trong một lần vô tình, Chiêu Nam rơi xuống vách đá và trôi theo dòng sông tình cờ vào cung và gặp Liễu Hiên Minh thành chủ của Hiên Nguyệt . Chiêu Nam luôn hy vọng hòa bình giữa hai thành nên đã che giấu thân phận thật của mình và ở lại bên Hiên Minh với tư cách là cung nữ để thuyết phục Hiên Minh. Tuy nhiên, phong thái thành chủ bẩm sinh của cô ấy là đặc biệt độc đáo trong thâm cung. Do đó, câu chuyện huyền thoại “một núi không thể chứa hai hổ, trừ khi chúng là chúa tể của thành phố” cũng được dàn dựng...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Yue Nan","avatar":""},{"name":"Yan Zi Xian","avatar":""},{"name":"Fan Wei","avatar":""},{"name":"Yunjia Xing","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
