INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-bi-vui-lap-phan-3', 'Bí Mật Bị Vùi Lấp (Phần 3)', 'Outer Banks (Season 3)', 'https://phimimg.com/upload/vod/20240309-1/042e4531e4f3929787031c204db90636.jpg', 'https://phimimg.com/upload/vod/20240309-1/de59e7ad0d881e7fc729660270f04870.jpg', '<p>Những cuộc phiêu lưu mới đưa gia đình Pogues đến vùng biển Caribe và xa hơn nữa khi những người bạn bị kéo vào cuộc săn lùng thành phố huyền thoại đã mất của một đối thủ nguy hiểm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chase Stokes","avatar":""},{"name":"Madelyn Cline","avatar":""},{"name":"Jonathan Daviss","avatar":""},{"name":"Madison Bailey","avatar":""},{"name":"Rudy Pankow","avatar":""},{"name":"Charles Esten","avatar":""},{"name":"Austin North","avatar":""},{"name":"Drew Starkey","avatar":""},{"name":"connor schnell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
