INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hom-nay-phai-co-len', 'Hôm Nay Phải Cố Lên', 'Never Give Up', 'https://phimimg.com/upload/vod/20240309-1/1bde7b0462a675c0774509d7774d3df3.jpg', 'https://phimimg.com/upload/vod/20240309-1/60216397168a2140659ea51f665a67d5.jpg', '<p>Nội dung của phim Hôm Nay Phải Cố Lên kể về những câu chuyện của những nhân viên trong Phòng Kế Hoạch 3, từng coi là nơi vô cùng thần bí của Tập đoàn Điện tử Cao Phát, nhưng 3 năm trở lại đây lại liên tục bị thụt lùi do sở hữu nhiều dự án không được khả thi. Tuy nhiên, mỗi nhân viên trong phòng lại có những quan điểm riêng của mình và thể hiện một cuộc sống gọi là “người bình thường phấn đấu”.Đặc biệt, dù là hố đen của công ty nhưng Lý Thiên Nhiên (Trịnh Khải thủ vai) hay là cô nàng Phạm Tư Tư (Trần Kỳ Ngọc thủ vai) và Bạch Mã Soái (Vương Hạc Đệ thủ vai) đã lựa chọn cách cố gắng hết hình trong công việc, mặc dù họ là những người bình thường, nhưng họ cũng đang đấu tranh để xây dựng lại vinh quang của bộ phận thứ ba và triển vọng nghề nghiệp của họ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"rịnh Khải","avatar":""},{"name":"Trần Ngọc Kỳ","avatar":""},{"name":"Vương Hạc Đệ","avatar":""},{"name":"Trương Thiệu Cương","avatar":""},{"name":"Lương Siêu","avatar":""},{"name":"Chung Lệ Lệ","avatar":""},{"name":"Ngô Á Hành","avatar":""},{"name":"Trương Duyệt Trì","avatar":""},{"name":"Trình Tử","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324254);
