INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hom-nay-phai-co-len', 'Hôm Nay Phải Cố Lên', 'Never Give Up', 'hôm nay phải cố lên never give up rịnh khải trần ngọc kỳ vương hạc đệ trương thiệu cương lương siêu chung lệ lệ ngô á hành trương duyệt trì trình tử ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-hu-cua-rokudo', 'Gái Hư Của Rokudo', 'Rokudo''s Bad Girls', 'https://phimimg.com/upload/vod/20240309-1/df68c1df0590c02acf3993e2d56a5313.jpg', 'https://phimimg.com/upload/vod/20240309-1/ab5e1af9855ffa5d866e1fcb4543abb3.jpg', '<p>Câu chuyện kể về Tо̄suke Rokudо̄, một nam sinh trung học nhút nhát bị bọn côn đồ bắt nạt. Anh nhận được một cuộn giấy từ người ông quá cố của mình, để lại dấu vết trên trán. Hiệu ứng nhãn hiệu khiến một cô gái du côn tên Ranna Himawari phải lòng anh.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 19, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Gen Sato","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Naomi Ohzora","avatar":""},{"name":"Yuki Yomichi","avatar":""},{"name":"Misato Matsuoka","avatar":""},{"name":"Hitomi Sekine","avatar":""},{"name":"Haruki Ishiya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324254);
