INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-den-ban-hien', 'Gửi Đến Bạn Hiền', 'From Me To You: Kimi Ni Todoke', 'https://phimimg.com/upload/vod/20240309-1/855a402d33be78c1fec434479dec3e5d.jpg', 'https://phimimg.com/upload/vod/20240309-1/7efe971d3aadeed7e85839a6fe314455.jpg', '<p>Phim kể về Sawako Kuronuma (Sara Minami), học sinh trung học. Mọi người xung quanh gọi cô ấy là Sadako và các bạn cùng lớp không kết giao với cô ấy. Cô ấy chỉ có một mình ở trường. Shota Kazehaya (Oji Suzuka) là học sinh cùng trường trung học. Anh ấy không quan tâm đến những gì người khác nghĩ và tiếp cận Sawako Kuronuma. Anh ấy là người duy nhất biết Sawako Kuronuma làm những công việc khó chịu cho các bạn cùng lớp của cô ấy. Vì Shota Kazehaya, các học sinh khác bắt đầu nói chuyện với Sawako Kuronuma. Cuộc sống học đường của cô ấy bắt đầu trở thành những gì cô ấy mong muốn và cô ấy cũng có tình cảm với Shota Kazehaya.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sara Minami","avatar":""},{"name":"Ouji Suzuka","avatar":""},{"name":"Kaito Sakurai","avatar":""},{"name":"Rinka Kumada","avatar":""},{"name":"Riho Nakamura","avatar":""},{"name":"Naho Toda","avatar":""},{"name":"Hiroyuki Hirayama","avatar":""},{"name":"Shohei Miura","avatar":""},{"name":"Jin Suzuki","avatar":""},{"name":"Atsuhiro Inukai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
