INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-chang-ten-gi', 'Công Tử Chàng Tên Gì', 'Hello There', 'https://phimimg.com/upload/vod/20240309-1/256181e5a8841e86c00398b72367c664.jpg', 'https://phimimg.com/upload/vod/20240309-1/34cba571f1e8ceae08ffce5aef9ce77e.jpg', '<p>Bộ phim này kể về Đường Bất Ngôn - một người năng nổ luôn tràn trề nhựa sống. Vì để giải quyết nan đề huyết mạch của gia tộc mà phải bôn ba bốn bể tìm được người định mệnh có nốt ruồi ở khóe mắt. Trong một lần trùng hợp làm sao, cô chạm mặt Lý Thành Hề thanh cao ưu nhã của Huyền Kỳ Môn. Định mệnh của cả hai vì vậy kết thành một mối, từ ấy mở ra một câu chuyện tình ấm áp và chữa lành.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Mo Xi","avatar":""},{"name":"Meng En","avatar":""},{"name":"Ngô Thừa Trạch","avatar":""},{"name":"Thái Tường Vũ","avatar":""},{"name":"Luyu Pan","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
