INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-nhu-da-noi-mot-trieu-lan', 'Giá Như Đã Nói Một Triệu Lần', 'Why Didn''t I Tell You A Million Times?', 'https://phimimg.com/upload/vod/20240309-1/295b62dae0f15a996c965846badae450.jpg', 'https://phimimg.com/upload/vod/20240309-1/fa51a8efa01e45e0e2baf5a813074d4f.jpg', '<p>Đoàn tụ khi trưởng thành, hai người bạn thời thơ ấu yêu nhau say đắm và sẽ không để bất cứ điều gì kể cả cái chết chia cắt họ trong chuyện tình siêu nhiên này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mao Inoue","avatar":""},{"name":"Satoh Takeru","avatar":""},{"name":"Matsuyama Kenichi","avatar":""},{"name":"Shim Eun Kyung","avatar":""},{"name":"Itakura Toshiyuki","avatar":""},{"name":"Yusuke Shoji","avatar":""},{"name":"Hoshi Moeka","avatar":""},{"name":"Chihiro Kondo","avatar":""},{"name":"Ichika Sakura","avatar":""},{"name":"Keizo Nagashima","avatar":""},{"name":"Karina","avatar":""},{"name":"Kikuchi Rinko","avatar":""},{"name":"Kanno Misuzu","avatar":""},{"name":"Hiraiwa Kami","avatar":""},{"name":"Shumputei Shota","avatar":""},{"name":"Arakawa Yoshiyoshi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
