INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-nhu-da-noi-mot-trieu-lan', 'Giá Như Đã Nói Một Triệu Lần', 'Why Didn''t I Tell You A Million Times?', 'giá như đã nói một triệu lần why didn''t i tell you a million times? mao inoue satoh takeru matsuyama kenichi shim eun kyung itakura toshiyuki yusuke shoji hoshi moeka chihiro kondo ichika sakura keizo nagashima karina kikuchi rinko kanno misuzu hiraiwa kami shumputei shota arakawa yoshiyoshi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('class-of-07', 'Class Of ''07', 'Class Of ''07', 'https://phimimg.com/upload/vod/20240309-1/06f9c9111bb4228948628d97975cac8b.jpg', 'https://phimimg.com/upload/vod/20240309-1/a11768fb7884f1a03e8adfbe1a3ec648.jpg', '<p>Khi một cơn thủy triều tận thế ập đến trong cuộc hội ngộ mười năm của một trường trung học toàn nữ, một nhóm phụ nữ phải tìm cách sống sót trên đỉnh hòn đảo trong khuôn viên trường trung học của họ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Emily Browning","avatar":""},{"name":"Caitlin Stasey","avatar":""},{"name":"Megan Smart","avatar":""},{"name":"Chi Nguyen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324254);
