INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-nien-thieu-cua-tang-thieu-nien', 'Thời Niên Thiếu Của Tăng Thiếu Niên', 'Once And Forever: The Sun Rises', 'https://phimimg.com/upload/vod/20240309-1/3913d88f91e7dfc4c6da00d5f0d4dcd5.jpg', 'https://phimimg.com/upload/vod/20240309-1/05a188c3196bf5a6c36ad14bb9e081d2.jpg', '<p><em>Thời Niên Thiếu Của Tăng Thiếu Niên</em> là&nbsp;một câu chuyện ấm áp về tình thân, tình bạn và sự trưởng thành của bốn gia đình ba thế hệ trong một tứ hợp viện ở Bắc Kinh vào những năm từ 1997 đến 2001. Hai thiếu niên thiếu nữ trung học Tạ Kiều, Tần Xuyên cùng bạn bè và người thân của mình đã trải qua những việc lớn nhỏ trong thời đại này, đối diện với những câu chuyện vừa muộn phiền vừa hạnh phúc trong quá trình trưởng thành. Tình cảm thân thiết và ấm áp giữa hàng xóm láng giềng đã trở thành những hành trang quý giá trong cuộc đời họ. Các bạn trẻ mang theo món quà mà thời gian ban tặng, từng bước trưởng thành, hướng đến một thời đại mới.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tử Mộc","avatar":""},{"name":"Trương Khai Thái","avatar":""},{"name":"Quách Tử Phàm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
