INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-phi-cua-ta-khong-de-choc-phan-2', 'Y Phi Của Ta Không Dễ Chọc (Phần 2)', 'I Have A Smart Doctor Wife', 'https://phimimg.com/upload/vod/20240309-1/d1e4b66ef56049c97a79edcd3e50a3a5.jpg', 'https://phimimg.com/upload/vod/20240309-1/18cac9180cdb23c392069e5a59e75aaa.jpg', '<p>Bộ phim kể về nhân vật chính Vấn Nhược Nguyệt, là một bác sĩ thời hiện đại. Trong một lần cứu người, cô không cẩn thận bị điện giật, và xuyên không về thời cổ đại. Cô đã dùng chính hệ thống y học của mình để hành y chữa bệnh, và bị chỉ định gả cho Ngọc Vương, thái tử triều trước. Hai con người, một người chữa bệnh cứu người, một người bảo vệ bách tính, từ ghét bỏ đến tán dương, đến kề vai sát cánh, yêu thương chữa lành lẫn nhau.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
