INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-toi-bi-an-an-mang-sicilia-phan-2', 'Đổ Tội! Bí Ẩn Án Mạng Sicilia (Phần 2)', 'Framed! A Sicilian Murder Mystery (Season 2)', 'https://phimimg.com/upload/vod/20240309-1/1eadc9e786b54f2ae67b2a1305a3b186.jpg', 'https://phimimg.com/upload/vod/20240309-1/6426fea3db189ec57b714c487cda2189.jpg', '<p>Hai kỹ thuật viên truyền hình không may có mặt ở hiện trường án mạng, và mỗi việc họ làm để tránh trở thành nghi phạm lại khiến họ lún sâu hơn vào rắc rối.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2023, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Salvo Ficarra","avatar":""},{"name":"Valentino Picone","avatar":""},{"name":"Leo Gullotta","avatar":""},{"name":"Anna Favella","avatar":""},{"name":"Marianna Di Martino","avatar":""},{"name":"Tony Sperandeo","avatar":""},{"name":"Maurizio Marchetti","avatar":""},{"name":"Mary Cipolla","avatar":""},{"name":"Sergio Friscia","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324254);
