INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-my-goc-hoa', 'Người Mỹ Gốc Hoa', 'American Born Chinese', 'https://phimimg.com/upload/vod/20240309-1/db124eed10406f069794f8fe28b7c952.jpg', 'https://phimimg.com/upload/vod/20240309-1/e5574c1d3c9ccf5e6265eac8e8eec557.jpg', '<p>Cậu thiếu niên bình thường Jin Wang tung hứng cuộc sống xã hội ở trường trung học với cuộc sống gia đình nhập cư của mình. Khi anh gặp một sinh viên nước ngoài mới vào ngày đầu tiên của năm học, thậm chí nhiều thế giới va chạm hơn khi Jin vô tình vướng vào trận chiến của các vị thần trong thần thoại Trung Quốc.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Wang","avatar":""},{"name":"Yann Yann Yeo","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"Jimmy Liu","avatar":""},{"name":"Sydney Taylor","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Michelle Yeoh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324254);
