INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-tinh-yeu', 'Làng Tình Yêu', 'Love Village', 'https://phimimg.com/upload/vod/20240309-1/b9a4dd4c9d7609dbd4346c677405c1ee.jpg', 'https://phimimg.com/upload/vod/20240309-1/69b36f707624118fcf0b54199dd84fc4.jpg', '<p>Có hoàn cảnh khác nhau, một số người độc thân từ 35 tuổi trở lên chung sống trong một ngôi nhà vùng nông thôn để kiếm tìm tình yêu. Liệu họ sẽ tìm thấy nửa kia hay một mình ra về?</p>', 'Hoàn Tất (18/18)', 18, 'tvshows', 'completed', 10, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tamura Atsushi","avatar":""},{"name":"Becky","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
