INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-viec-dieu-chung-ta-lam-ca-ngay', 'Công Việc: Điều Chúng Ta Làm Cả Ngày', 'Working: What We Do All Day', 'https://phimimg.com/upload/vod/20240309-1/46cc5edba3c39cdac6ad61a0d5172370.jpg', 'https://phimimg.com/upload/vod/20240309-1/23d0a4e0af4de4c5e8faa0f6d7a974b4.jpg', '<p>Với người này, đó là mưu sinh. Với người khác, đó là sứ mệnh. Loạt phim tài liệu này khám phá ý nghĩa của công việc đối với người Mỹ hiện đại trong thời kỳ thay đổi chóng mặt.</p>', 'Hoàn Tất (4/4)', 4, 'tvshows', 'completed', 12, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Barack Obama","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324254);
