INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-viec-dieu-chung-ta-lam-ca-ngay', 'Công Việc: Điều Chúng Ta Làm Cả Ngày', 'Working: What We Do All Day', 'công việc: điều chúng ta làm cả ngày working: what we do all day barack obama ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('taxi-ma-quai', 'Taxi Ma Quái', 'Delivery Man', 'https://phimimg.com/upload/vod/20240309-1/96567959a11f8e5ef9f40d0d67048ddb.jpg', 'https://phimimg.com/upload/vod/20240309-1/8cc9059063e69da54f7316b5f1718fa6.jpg', '<p>Chuyến Xe Ma Quái kể về Seo Young-Min (Yoon Chan-Young), tài xế taxi để nuôi sống bản thân. Bằng cách nào đó, Seo Young-Min bắt đầu chỉ coi những hồn ma là hành khách của mình và anh ấy ban cho họ những điều ước. Anh ấy được một hồn ma và một bác sĩ cấp cứu giúp đỡ. Kang Ji-Hyun (Bang Min-Ah) tình cờ lên taxi của Seo Young-Min. Cô không nhớ mình là ai khi còn sống. Cô ấy không biết tại sao, nhưng cô ấy không thể rời khỏi taxi của anh ấy. Cô ấy tự nhận mình là giám đốc bán hàng của chiếc taxi của Seo Young-Min. Seo Young-Min và Kang Ji-Hyun cùng nhau ban cho những điều ước của những hồn ma, bao gồm cả việc đuổi theo một kẻ giết người hàng loạt. Họ có một người trợ giúp là Do Kyu-Jin (Kim Min-Suk). Do Kyu-Jin là một bác sĩ cấp cứu nghiện công việc với vẻ ngoài đẹp trai. Anh ta cảm nhận được các dấu hiệu của các sự kiện nham hiểm trong ER, nơi mọi người đang ở trong tình huống sinh tử.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 22, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon Chan-young","avatar":""},{"name":"Bang Min-ah","avatar":""},{"name":"Kim Min-seok","avatar":""},{"name":"Kim Seung-su","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
