INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-nhin-thay-duyen-phan', 'Thiếu Nữ Nhìn Thấy Duyên Phận', 'Love Is Written In The Stars', 'https://phimimg.com/upload/vod/20240309-1/47da3bb864d059e69c50ac2f1a42f126.jpg', 'https://phimimg.com/upload/vod/20240309-1/f0263de4e24080a0a7c8e86425612772.jpg', '<p>Nó kể về Zhou Yuan, một cô gái mạnh mẽ, khi xúc động sẽ phát bệnh, để bảo vệ anh trai, cô cải trang thành nam giới và đến Học viện Qingyun ở kinh đô. hai người buộc phải liên kết lại với nhau, Chu Nguyên nhìn thấy vận mệnh liều mạng kết giao với Ngụy Kỳ, không ngờ lại bị hắn bắt gặp, bắt đầu tuổi trẻ vui vẻ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tề Yến Địch","avatar":""},{"name":"Ao Ruipeng","avatar":""},{"name":"Dịch Bách Thần","avatar":""},{"name":"Dương Tân Anh","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324254);
