INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-mong-giua-ban-ngay', 'Tôi Mộng Giữa Ban Ngày', 'You Are Desire', 'https://phimimg.com/upload/vod/20240309-1/6f8f2a8e867118e3f9b3beab1b01c1d5.jpg', 'https://phimimg.com/upload/vod/20240309-1/a9781b9ba89e144fe1741f611ce397c3.jpg', '<p>Nội dung phim kể về mối tình giữa đôi bạn Thẩm Quyện và Lâm Ngữ Kinh. Lần đầu tiên Thẩm Quyện và Lâm Ngữ Kinh gặp nhau, đó là ở cửa hàng xăm. Trong ấn tượng của Lâm Ngữ Kinh, đây là một gã gắt gỏng, lúc nào cũng trong trạng thái buồn ngủ. Cô không ngờ rằng về sau, anh chàng này chẳng những sẽ học cùng lớp mà còn ngồi chung bàn với mình.Hai người ngày ngày bên nhau, trải qua rất nhiều chuyện nên dần hiểu được con người thật của đối phương. Thì ra, đằng sau vẻ ngoài lạnh lùng của Thẩm Quyện là một tâm hồn dịu dàng, biết quan tâm người khác. Mối quan hệ giữa hai người dần chuyển từ bạn bè thành người yêu. Cũng nhờ Lâm Ngữ Kinh, Thẩm Quyện một lần nữa theo đuổi giấc mơ từng bị anh từ bỏ.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trang Đạt Phi","avatar":""},{"name":"Châu Dực Nhiên","avatar":""},{"name":"Trần Hạc Nhất","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
