INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ultraman-phan-3', 'Ultraman (Phần 3)', 'Ultraman (Season 3)', 'https://phimimg.com/upload/vod/20240309-1/673f29eec515f43023b2472ae56c8710.jpg', 'https://phimimg.com/upload/vod/20240309-1/7f582c54cc4cd773c09af34754419aa5.jpg', '<p>Khi tình cảm của công chúng quay lưng lại với Ultraman, Shinjiro biết rằng sức mạnh được thừa hưởng của mình có thể phải trả giá đắt, trong phần kết của loạt phim thú vị này.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ryohei Kimura","avatar":""},{"name":"Takuya Eguchi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324254);
