INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-tang-hinh', 'Biệt Đội Tàng Hình', 'The Invisibles', 'https://phimimg.com/upload/vod/20240309-1/d45158ca7b96bf94637d1d48d585eb3b.jpg', 'https://phimimg.com/upload/vod/20240309-1/853db69ff56b2397bdf948cc851c1238.jpg', '<p>Lực lượng cảnh sát Hồng Kông đã tăng cường và thành lập đội tình báo chống khủng bố để đập tan mọi hình thức hoạt động khủng bố. Đội CTRU tiến hành tuần tra và đối phó với các cuộc tấn công, trong khi đội POTT điều tra sâu để tiêu diệt mọi đe dọa tiềm tàng.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 2023, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Kenneth Ma","avatar":""},{"name":"Natalie Tong","avatar":""},{"name":"Joel Chan","avatar":""},{"name":"Tiffany Lau","avatar":""},{"name":"Moon Lau","avatar":""},{"name":"Alex Lam","avatar":""},{"name":"Elena Kong","avatar":""},{"name":"Jimmy Au","avatar":""},{"name":"Arnold Kwok","avatar":""},{"name":"Carlo Ng","avatar":""},{"name":"Jack Wu","avatar":""},{"name":"Candice Chiu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324254);
