INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-riverdale-phan-7', 'Thị Trấn Riverdale (Phần 7)', 'Riverdale (Season 7)', 'https://phimimg.com/upload/vod/20240309-1/9a513c65d26915cbbd6ba4a5a8d2146d.jpg', 'https://phimimg.com/upload/vod/20240309-1/22fe2b71d3e0c6480e392d9720baf945.jpg', '<p>Tiếp nối phần 6 đã kết thúc, phần 7 tìm thấy Jughead Jones bị mắc kẹt trong những năm 1950. Anh ta không biết làm thế nào anh ta đến đó, cũng như làm thế nào để quay trở lại hiện tại. Bạn bè của anh ấy không giúp được gì, vì họ đang sống cuộc sống có vẻ chân thực, tương tự như các đối tác Archie Comics cổ điển của họ, không biết rằng họ đã từng ở bất cứ đâu ngoài những năm 1950. Liệu Jughead và đồng bọn có thể trở về hiện tại? Hay các nhân vật của chúng ta sẽ bị mắc kẹt trong những năm 1950 mãi mãi? Và, nếu vậy ... đó có phải là một điều xấu?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"K.J. Apa","avatar":""},{"name":"Lili Reinhart","avatar":""},{"name":"Camila Mendes","avatar":""},{"name":"Cole Sprouse","avatar":""},{"name":"Madelaine Petsch","avatar":""},{"name":"Casey Cott","avatar":""},{"name":"Charles Melton","avatar":""},{"name":"Vanessa Morgan","avatar":""},{"name":"Drew Tanner","avatar":""},{"name":"Erinn Westbrook","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
