INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-tieu-han-da-noan', 'Cửu Tiêu Hàn Dạ Noãn', 'Warm On A Cold Night', 'https://phimimg.com/upload/vod/20240309-1/9747b706d58bbfa1e4c00ddf0e94a76c.jpg', 'https://phimimg.com/upload/vod/20240309-1/325712da8c9a2893ca0d1aa35cdc04c2.jpg', '<p>Cửu Tiêu Hàn Dạ Noãn do Lí Tuệ Châu đạo diễn, Cung do Nhâm tổng đạo diễn, Phượng Tù Hoàng - Đặng Vĩ Ân, &nbsp;Cẩm Tú Nam Ca - Hoàng Bân, Anh hùng xạ điêu - Lý Nhất Đồng, là bộ phim cổ trang tình yêu đặc biệt. Bộ phim kể về câu chuyện của nữ bộ khoái sợ lạnh của Kiền quốc Tô Cửu Nhi(Lý Nhất Đồng thủ vai) cùng Thiếu chủ “ngoài lạnh trong nóng” Hàn Tranh của Kỳ tộc (Tất Văn Quân thủ vai) vụ án giết người liên quan đến hai gia tộc mà gặp nhau, tình cờ tạo thành Đối tác chênh lệch nhiệt độ , cùng nhau vượt qua màn sương mù âm mưu dày đặc, tìm chân tướng sau lưng vụ án đồng thời hoá giải mối nguy hiểm của quốc gia.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Nhất Đồng","avatar":""},{"name":"Trần Hạc Nhất","avatar":""},{"name":"Tất Văn Quân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324254);
