INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-thanh', 'Long Thành', 'Take Us Home', 'https://phimimg.com/upload/vod/20240309-1/fc64ee457c6441ff06115eec860313bb.jpg', 'https://phimimg.com/upload/vod/20240309-1/d0ed0501b1bc6f218aab403dff0a9129.jpg', '<p>Long Thành chuyển thể từ tiểu thuyết Long Thành Tam Bộ Khúc của tác giả Địch An, kể về ba chị em họ của Trịnh gia bước ra từ gia đình nguyên sinh của mình, trong quá trình trưởng thành họ đã dìu dắt nhau, chữa lành và sưởi ấm cho nhau. Thể hiện sự yêu thương của tình thân dành cho mỗi một con người, vun vén tình cảm gia đình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Ý Ly","avatar":""},{"name":"Bạch Ngọc","avatar":""},{"name":"Lý Đình Đình","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Cao Tân","avatar":""},{"name":"Giới Băng","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324254);
