INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-se-khong-thich-cau-dau', 'Tôi Sẽ Không Thích Cậu Đâu!', 'Falling For You', 'https://phimimg.com/upload/vod/20240309-1/585b1f3c2467de0d0b48ed415ede32c7.jpg', 'https://phimimg.com/upload/vod/20240309-1/96aec72f1c4e5a3e74dbc4979b4a4acc.jpg', '<p>Nhà sản xuất hàng đầu cực kỳ có năng lực - Tô Thắng Nam - rất ghét những bộ phim lấy chủ đề ngọt ngào mất não, nhưng lại vô tình xuyên không vào một bộ phim ngọt sủng, trở thành nữ chính Mary Sue dịu dàng yếu đuối mà cô coi thường nhất, lại được nam chính bá đạo tổng tài Âu Dương Vũ Xuyên điên cuồng theo đuổi. Ban đầu cô không chịu nổi, thay đổi thiết lập nhân vật từ thỏ trắng thành cô gái mạnh mẽ, nhưng sau này dần dần nhận ra bản tính lương thiện của Âu Dương, hai người đắm chìm vào tình yêu đích thực xuyên thời gian và không gian.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Lệ Na","avatar":""},{"name":"Lý Khởi Ca","avatar":""},{"name":"Tô Vũ","avatar":""},{"name":"Hàng Hoàng","avatar":""},{"name":"Duyệt Nhiên","avatar":""},{"name":"Cát Tuấn Đình","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
