INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay', 'Vòng Xoáy', 'Vortex', 'https://phimimg.com/upload/vod/20240309-1/024a481ea56c18c702829313a7e43bb1.jpg', 'https://phimimg.com/upload/vod/20240309-1/4b3d1e250789176bf2c0ddb4ddadada5.jpg', '<p>Sau khi kết nối lại với người vợ đã khuất thông qua một lỗi trong thực tế ảo, viên sĩ quan cảnh sát nọ cố gắng phủ nhận vụ tai nạn bí ẩn đã cướp đi sinh mạng của cô.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Tomer Sisley","avatar":""},{"name":"Camille Claris","avatar":""},{"name":"Zineb Triki","avatar":""},{"name":"Éric Pucheu","avatar":""},{"name":"Sandrine Salyères","avatar":""},{"name":"Ludovik","avatar":""},{"name":"Léo Chalié","avatar":""},{"name":"Anaïs Parello","avatar":""},{"name":"Juliette Plumecocq-Mech","avatar":""},{"name":"Julien Floreancig","avatar":""},{"name":"Evelyne El Garbi Klaï","avatar":""},{"name":"Marc Andréoni","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
