INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-so-thap', 'Tần Số Thấp', 'Low Frequency', 'https://phimimg.com/upload/vod/20240309-1/329a7043c116476908511d398176bdee.jpg', 'https://phimimg.com/upload/vod/20240309-1/1d55aeeb99e6bc9aec65da5a334f0c1e.jpg', '<p>Tần Số Thấp là câu chuyện xoay quanh Mon, một nhà trang trí nội thất trẻ tuổi, có khả năng nhìn thấy linh hồn. Mon gặp Thames, một diễn viên trẻ tài năng nhưng bị trở thành chàng hoàng tử ngủ trong rừng sau khi gặp một tai nạn. Hai người họ trở thành đồng đội và cùng nhau giải quyết các vụ án, truy bắt kẻ xấu. Trong quá trình này, tình yêu giữa họ nảy nở. Cuối cùng, khi thủ phạm bị bắt, Mon và Thames gặp lại ở thế giới thực và trải qua những khoảnh khắc hạnh phúc bên nhau.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Guitar Sarin Tangcharoenpaisarn","avatar":""},{"name":"Ping Guntapat Kasemsan na ayudhya","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
