INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-mong-tinh-duyen', 'Huyễn Mộng Tình Duyên', 'Beyond Romance', 'https://phimimg.com/upload/vod/20240309-1/9493ad52fd51d3f77ac3c81c22ccc665.jpg', 'https://phimimg.com/upload/vod/20240309-1/5a7dfbcef9ca2e0c2f6baca8948b3bc3.jpg', '<p>Nữ diễn viên quần chúng nợ nần chồng chất Cố Trăn Trăn và nhân tài mới nổi trong lĩnh vực công nghệ Lục Vân Sâm vừa kết thúc hợp đồng hôn nhân, chuẩn bị chào đón một cuộc sống mới. Nhưng Lục Vân Sâm bất ngờ bị mất trí nhớ, chỉ nhớ Trăn Trăn là vợ của mình! Không còn cách nào, Cố Trăn Trăn đành phải tiếp tục cuộc hôn nhân hợp đồng để giúp Lục Vân Sâm lấy lại ký ức, nhưng dần dần cô lại khám phá ra sự thật đằng sau cuộc hôn nhân hợp đồng này và tìm thấy tình yêu đích thực.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Mộ Trần","avatar":""},{"name":"Trương Hân Ý","avatar":""},{"name":"Lí Thừa Hi","avatar":""},{"name":"Từ Thư Oánh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
