INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luden-cac-vi-vua-cua-reeperbahn', 'Luden - Các Vị Vua Của Reeperbahn', 'The Pimp - No F***ing Fairytale', 'https://phimimg.com/upload/vod/20240309-1/f3f79cb27c01a406832fa39cee646593.jpg', 'https://phimimg.com/upload/vod/20240309-1/eb91385d4d8e8508cb819730bf1acbb6.jpg', '<p>Lấy cảm hứng từ những sự kiện có thật, sử thi xã hội đen LUDEN kể về sự trỗi dậy của Băng đảng Nutella, băng ma cô nổi tiếng nhất ở Reeperbahn huyền thoại của Hamburg trong những năm 1980. Băng đảng khác thường biến khu đèn đỏ thô sơ ở St. Pauli thành nơi hào nhoáng, nhưng cũng là nơi bắt đầu cuộc tranh giành quyền lực với những tay ma cô đã thành danh của GMBH.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Lena Urzendowsky","avatar":""},{"name":"Noah Tinwa","avatar":""},{"name":"Karsten Antonio Mielke","avatar":""},{"name":"Stefan Konarske","avatar":""},{"name":"Lara Feith","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
