INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-vo-hinh-phan-2', 'Thanh Tra Vô Hình (Phần 2)', 'Shadow Detective (Season 2)', 'https://phimimg.com/upload/vod/20240309-1/5bebdd7f1e53c62aeafafc09c313c9b9.jpg', 'https://phimimg.com/upload/vod/20240309-1/48418f65f8b5197b7e9fe49a08bc2470.jpg', '<p>Taek-rok có mâu thuẫn với trưởng nhóm Yeon Ju-hyun. Seong A chật vật trong vụ điều tra trộm cắp vị thành niên.Thanh Tra Rok kể về Kim Taek-Rok, một thám tử kỳ cựu tại Sở cảnh sát Geumo. Kuk Jin-Han được chuyển đến Sở cảnh sát Geumo với tư cách là đội trưởng đội điều tra nơi Kim Taek-Rok làm việc. Một ngày nọ, Kuk Jin-Han nhận được một cuộc điện thoại bí ẩn với thông tin Kim Taek-Rok là đồng phạm giết hại đồng nghiệp. Liệu thanh tra Rok có thực sự phạm tội? Các đồng nghiệp có tìm ra được bí ẩn đằng sau vụ án.&nbsp;</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 19, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Sung-min","avatar":""},{"name":"Kyung Soo-jin","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Kim Shin-rock","avatar":""},{"name":"Go Gyu-pil","avatar":""},{"name":"Kim Jae-bum","avatar":""},{"name":"Jung Hae-kyun","avatar":""},{"name":"Ju Jin-mo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
