INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-du-chi-cap-do-1-nhung-vi-co-ky-nang-doc-nhat-nen-toi-la-nguoi-manh-nhat', 'Mặc Dù Chỉ Cấp Độ 1 Nhưng Vì Có Kỹ Năng Độc Nhất Nên Tôi Là Người Mạnh Nhất', 'My Unique Skill Makes Me OP Even At Level 1', 'https://phimimg.com/upload/vod/20240309-1/1ffd1401c844ade1f84417fea56923eb.jpg', 'https://phimimg.com/upload/vod/20240309-1/6969c6dfada3209b7ff390b65dcace5b.jpg', '<p>Sato Ryota đã bị chuyển đến một thế giới khác! Nhưng thật không may, dù cậu có cố gắng thế nào thì cấp độ cũng chỉ là cấp 1.

Mặc dù không thể cải thiện cấp độ, nhưng Ryota có một siêu kỹ năng vốn có với tỷ lệ rơi đều là hạng S và có thể rơi ra những vật phẩm tăng cường sức mạnh mà trong những trường hợp bình thường không thể lấy được.

Ryota không ngừng nâng cao năng lực của mình thông qua các kỹ năng, mặc dù cấp độ của anh ấy chỉ là cấp 1, nhưng giá trị năng lực của anh ấy là MAX</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324254);
