INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khao-khat-va-bai-tho', 'Khao Khát Và Bài Thơ', 'Desire & Poem', 'https://phimimg.com/upload/vod/20240309-1/97fb34d06e5da83e3d799bb5cb417531.jpg', 'https://phimimg.com/upload/vod/20240309-1/b3ffce36b72d9e60b7493417af746941.jpg', '<p>Vở kịch kể câu chuyện về cuộc nổi loạn của một số thanh niên tụ tập vì những mục đích khác nhau như ý chí, công lý và trả thù trong giới tài chính vận hành theo trật tự và quy tắc đã được thiết lập. Với trò chơi và cuộc đấu tranh giữa kẻ săn mồi và con mồi nổi loạn ở nơi làm việc, một bộ phim công sở mới mẻ, bùng cháy và ngay thẳng, với ba quan điểm ngay thẳng, từ từ bắt đầu.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nguyên Hào","avatar":""},{"name":"Chai Biyun","avatar":""},{"name":"Lý Tông","avatar":""},{"name":"Hàn Vương","avatar":""},{"name":"Vệ Đường Chân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
