INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khue-trung-mat-huu', 'Khuê Trung Mật Hữu', 'The Best Friend', 'https://phimimg.com/upload/vod/20240309-1/146d4bb95d01c846083f4297ce3f66fc.jpg', 'https://phimimg.com/upload/vod/20240309-1/1237b70e4ffc8cb2b7adecea45aa4e12.jpg', '<p>Đoạn Nhược Nam và Phàn Hiểu Vy vốn là đôi khuê mật thân thiết vô cùng. Sau khi bạn thân mình bị tra nam ruồng bỏ, Đoạn Nhược Nam đưa cô bạn về nhà sống chung với bạn trai của mình, nào ngờ đâu việc 3 người cùng sống dưới một mái nhà này đã dẫn tới Hiểu Vy và Lê Tiêu - bạn trai của Nhược Nam gieo mầm mối tình cấm kỵ, lén lút vụng trộm sau lưng Nhược Nam. Vào đúng ngày kỷ niệm của Nhược Nam và Lê Tiêu, những khúc mắt giữa chuyện tình tay ba này cũng phá kén chui ra. Tình chị em thân mật ngày nào giờ như nước với lửa, Nhược Nam đau đớn mà rời đi. Nhưng ngày vui nào kéo được dài lâu, những xúc cảm mới lạ giữa Lê Tiêu và Phàn Hiểu Vy rồi cũng dần nhạt đi, Hiểu Vy vốn luôn thiếu thốn cảm giác an toàn nay đã bắt đầu bộc lộ những sự khống chế gần như biến thái với Lê Tiêu, khiến Lê Tiêu ngột ngạt không thôi. Nhược Nam và Lê Tiêu chạm mặt nhau trong một lần tình cờ, cả ba người lại bắt đầu dây dưa, Lê Tiêu vốn đã chán ngấy sự quản giáo của Hiểu Vy nên muốn nối lại tình xưa với Nhược Nam, đồng thời đề nghị chia tay với Hiểu Vy. Hiểu Vy lại trút hết mọi tội lỗi lên đầu Nhược Nam, vì thế cô xin vào công ty mới của Nhược Nam để bắt đầu kế hoạch trả thù.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Yong Xi","avatar":""},{"name":"Liu Cheng Lin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324254);
