INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lego-dreamzzz', 'LEGO Dreamzzz', 'LEGO Dreamzzz', 'https://phimimg.com/upload/vod/20240309-1/06e21880ac4e0115173cb9a024ffe826.jpg', 'https://phimimg.com/upload/vod/20240309-1/542967bf6216f5e3dafe7ee6363d0044.jpg', '<p>Một nhóm trẻ em tham gia vào một cơ quan bí mật, nơi chúng học cách sử dụng sức mạnh của trí tưởng tượng để du hành vào Thế giới giấc mơ và tạo ra những tác phẩm tuyệt vời để giúp những đứa trẻ đang ngủ đang bị khủng bố bởi Vua ác mộng ác mộng đang muốn chinh phục Thế giới giấc mơ và xâm chiếm thế giới thức giấc.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 13, 2023, 'Lồng Tiếng', 'HD', 'Âu Mỹ', 0, '[{"name":"Brian Drummond","avatar":""},{"name":"Sarah Jeffery","avatar":""},{"name":"Maria del Mar","avatar":""},{"name":"Vincent Tong","avatar":""},{"name":"Marcos Cardenas","avatar":""},{"name":"Larissa Dias","avatar":""},{"name":"Mike Taylor","avatar":""},{"name":"Clay St. Thomas","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324254);
