INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lego-dreamzzz', 'LEGO Dreamzzz', 'LEGO Dreamzzz', 'lego dreamzzz lego dreamzzz brian drummond sarah jeffery maria del mar vincent tong marcos cardenas larissa dias mike taylor clay st. thomas ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-hanh-phuc', 'Trận Chiến Hạnh Phúc', 'Battle For Happiness (Happiness Battle)', 'https://phimimg.com/upload/vod/20240309-1/2a4e744db61207877e11d54a91377658.jpg', 'https://phimimg.com/upload/vod/20240309-1/1e02993f3fdfcbcfbb7d16d89d6b6497.jpg', '<p>Một bộ phim hồi hộp mô tả các bà mẹ tham gia vào một trận chiến khốc liệt trên mạng xã hội để phá hủy hạnh phúc của nhau vì chính họ, để giải phóng bản thân khỏi sự áp bức, tổn thương và bí mật, đồng thời lấy lại con người thật của họ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee El","avatar":""},{"name":"Jin Seo-yeon","avatar":""},{"name":"Cha Ye-ryun","avatar":""},{"name":"Park Hyo-joo","avatar":""},{"name":"Woo Jung-won","avatar":""},{"name":"Lee Kyu-han","avatar":""},{"name":"Moon Hee-kyung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
