INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tran-chien-hanh-phuc', 'Trận Chiến Hạnh Phúc', 'Battle For Happiness (Happiness Battle)', 'trận chiến hạnh phúc battle for happiness (happiness battle) lee el jin seo-yeon cha ye-ryun park hyo-joo woo jung-won lee kyu-han moon hee-kyung ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-bien-trong-mo-where-dreams-begin', 'Vùng Biển Trong Mơ - Where Dreams Begin', 'The Youth Memories', 'https://phimimg.com/upload/vod/20240309-1/9cf2ebe7846eb002163ec5ade2183027.jpg', 'https://phimimg.com/upload/vod/20240309-1/0409b4aa5bc04f73ba4dd6079e865b15.jpg', '<p>Bộ phim lấy bối cảnh về những năm 70 ở Bắc Kinh, là câu chuyện sinh động về quá trình trưởng thành, phấn đấu, theo đuổi ước mơ của một nhóm người trẻ tuổi. Nhân vật chính cùng những người anh em tốt của mình phải trải qua nhiều giai đoạn phát triển trong cuộc đời như thi đại học, vào đời, xây dựng sự nghiệp, ra nước ngoài, bước chân vào quan trường... và cùng nhau tìm ra ý nghĩa của việc cố gắng phấn đấu trong quá trình giúp đỡ lẫn nhau đó. Các nhân vật nữ trong phim cũng phải trải qua đủ mọi gập ghềnh vất vả của cuộc đời, để thấy được những gắn kết đan xen trong vận mệnh đời nhau. Thông qua bối cảnh của cuộc cải cách mở cửa, bộ phim đã miêu tả rõ nét sự trưởng thành và phá kén của các nhân vật, để khắc họa sự phát triển nhanh chóng của đất nước, và thể hiện tình cảm đáng quý giữa người với người, truyền tải đi những nguồn năng lượng tích cực về ý chí vươn lên để phát triển lớn mạnh.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Zhan","avatar":""},{"name":"Li Qin","avatar":""},{"name":"Zhao Xin","avatar":""},{"name":"Lenox Lu","avatar":""},{"name":"Cui Hang","avatar":""},{"name":"Cao Feiran","avatar":""},{"name":"Zhang Lingxin","avatar":""},{"name":"Liu Ruilin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
