INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('real-madrid-chien-dau-den-phut-cuoi-cung', 'Real Madrid: Chiến đấu đến Phút Cuối Cùng', 'Real Madrid: Until The End', 'https://phimimg.com/upload/vod/20240309-1/9cb623cf591265f73b4b8f85423e887e.jpg', 'https://phimimg.com/upload/vod/20240309-1/7aba19af6e8c0a8b217bb3ccecc6ff6f.jpg', '<p>Bước ra sân và khám phá hậu trường với đội bóng biểu tượng để xem lại mùa giải 2021–2022 đáng kinh ngạc của họ. Được thúc đẩy bởi những người hâm mộ cuồng nhiệt của họ, họ bất chấp những khó khăn và bịt miệng những người hoài nghi.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 15, 2023, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324254);
