INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-ao-den', 'Hiệp Sĩ Áo Đen', 'Black Knight', 'https://phimimg.com/upload/vod/20240308-1/26acc555ee6a991f43e1b9303c105c68.jpg', 'https://phimimg.com/upload/vod/20240308-1/1d963603c08886d9689c27468fcf37cf.jpg', '<p>Ở tương lai tăm tối bị ô nhiễm không khí tàn phá, chuyện sống còn của loài người phụ thuộc vào nhóm Hiệp sĩ áo đen và họ khác xa những người giao hàng bình thường.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Woo Bin","avatar":""},{"name":"Song Seung Heon","avatar":""},{"name":"Kang You Seok","avatar":""},{"name":"Esom","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
