INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('swagger-phan-2', 'Swagger (Phần 2)', 'Swagger (Season 2)', 'https://phimimg.com/upload/vod/20240308-1/9de2541cd90b90f4eb28a692d275ee99.jpg', 'https://phimimg.com/upload/vod/20240308-1/32557d5268e0fcfaaf79b9733cb2bb05.jpg', '<p>Từ ngôi sao NBA, Kevin Durant, nhà làm phim Reggie Rock Bythewood và đội ngũ làm phim Friday Night Lights. Bộ phim kể về một thần đồng bóng rổ phải tìm kiếm lối đi trong mê cung đầy rẫy những áp lực để tìm được con đường thành công và học được ý nghĩa thật sự của “ngông nghênh”.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"O''Shea Jackson Jr.","avatar":""},{"name":"Isaiah R. Hill","avatar":""},{"name":"Quvenzhané Wallis","avatar":""},{"name":"Shinelle Azoroh","avatar":""},{"name":"James Bingham","avatar":""},{"name":"Ozie Nzeribe","avatar":""},{"name":"Tessa Ferrer","avatar":""},{"name":"Caleel Harris","avatar":""},{"name":"Solomon Irama","avatar":""},{"name":"Tristan Mack Wilds","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
