INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('swagger-phan-2', 'Swagger (Phần 2)', 'Swagger (Season 2)', 'swagger (phần 2) swagger (season 2) o''shea jackson jr. isaiah r. hill quvenzhané wallis shinelle azoroh james bingham ozie nzeribe tessa ferrer caleel harris solomon irama tristan mack wilds ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-gian', 'Vô Gian', 'Infernal Affairs', 'https://phimimg.com/upload/vod/20240308-1/fa7af48cb45b864a91bfafb5ff6a2c85.jpg', 'https://phimimg.com/upload/vod/20240308-1/33e73f7af57508b616282a4c861be7b8.jpg', '<p>Phim kể lại câu chuyện vào năm 1944, trong cuộc kháng chiến giữa Quốc dân đảng và Đảng Cộng sản, đội trưởng Quốc dân đảng Mu Liang Feng, vốn là một thợ săn, được lệnh lãnh đạo một đội đặc biệt để phá hủy viện nghiên cứu vũ khí bí mật của quân đội Nhật Bản đã phát triển lựu đạn xyanate. .<br/>Với sự giúp đỡ của Zhang Jue và Liu Xiao Xian, các thành viên của đảng ngầm của Đảng Cộng sản Trung Quốc, anh đã trải qua rất nhiều khó khăn và nguy hiểm để hoàn thành nhiệm vụ. Nhưng trong thời kỳ này, cha của anh, Mu Da Ming, một người Cộng sản kiên trung, đã bị giết, và vợ anh, Liu Yan, cũng bị bức hại và mất trí nhớ. Mu Liang Feng bị kích thích sâu sắc và tùy tiện tin rằng Đảng Cộng sản đã gây ra tất cả những điều này, và bắt đầu căm ghét Đảng Cộng sản...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cận Đông","avatar":""},{"name":"Vương Lệ Khôn","avatar":""},{"name":"Vương Chí Văn","avatar":""},{"name":"Trương Chí Kiên","avatar":""},{"name":"Kỳ Đạo Xuế Ni","avatar":""},{"name":"Vương Tử Quyền","avatar":""},{"name":"Tào Lỗi","avatar":""},{"name":"Thích Tích","avatar":""},{"name":"Lý Viện Hải","avatar":""},{"name":"Nhất Thiên","avatar":""},{"name":"Đàm Khải","avatar":""},{"name":"Trương Hy Lâm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324254);
