INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-chin-sang-hai-muoi', 'Mười Chín Sang Hai Mươi', 'Nineteen To Twenty', 'https://phimimg.com/upload/vod/20240308-1/22ddcfcf49dde9c1fed32927c0759359.jpg', 'https://phimimg.com/upload/vod/20240308-1/a62ae643c53182b94a30f11abdbd31c4.jpg', '<p>Một nhóm cô cậu cùng trải qua tuần cuối của tuổi teen và tuần đầu của tuổi hai mươi, khám phá tự do và đủ mọi khía cạnh &quot;lần đầu&quot; của tuổi trưởng thành.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"KYUHYUN","avatar":""},{"name":"Kim Ji Eun","avatar":""},{"name":"Lee Su Hyun","avatar":""},{"name":"Jeong Se Woon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
