INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-tru-hoat-dong-nhu-the-nao-phan-11', 'Vũ Trụ Hoạt Động Như Thế Nào (Phần 11)', 'How The Universe Works (Season 11)', 'https://phimimg.com/upload/vod/20240308-1/869839665bbe3f59588931f25a75a672.jpg', 'https://phimimg.com/upload/vod/20240308-1/f2b4625f2a99a66071f77d3769510408.jpg', '<p>Hướng dẫn dành cho người dùng về vũ trụ, từ Vụ nổ lớn đến các thiên hà, ngôi sao, hành tinh và mặt trăng: tất cả đến từ đâu và làm thế nào để tất cả khớp với nhau? Một cuốn sách sơ lược dành cho những ai đã từng nhìn lên bầu trời đêm và tự hỏi.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324254);
