INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-kiep-yeu-han', 'Ba Kiếp Yêu Hận', 'Circle Of Love', 'https://phimimg.com/upload/vod/20240308-1/14069fd42c57355c12c77ec710ccbaed.jpg', 'https://phimimg.com/upload/vod/20240308-1/56db1f4ab402293e5355a5abb18a646e.jpg', '<p>Năm xưa, Cố Mộng - con gái độc nhất của phú hộ một vùng- bị vị hôn phu Tiêu Hồng Diệp hại nhà tan cửa nát. Nay cô trở về là một con người khác hiểm độc hơn, cô hóa thân thành vũ nữ, muốn ám sát Tiêu Hồng Diệp - giờ đã là một tên quân phiệt quyền lực - nhưng không may bị mất trí nhớ, ngược lại còn bị Tiêu Hồng Diệp giữ bên cạnh làm người hầu, dùng đủ mọi cách để giày vò. Dù chịu bao uất ức nhục nhã, Cố Mộng cũng không thỏa hiệp, cô mang theo nỗi căm hận của mình, quyết tâm vạch trần chân tướng, chính tay đâm chết kẻ thù, nhưng cùng lúc đó lại bị cảm giác yêu hận đan xen giằng xé, sau nhiều lần mất trí nhớ rồi lại khôi phục, cô đã yêu Tiêu Hồng Diệp như định mệnh không thể dứt bỏ…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Cửu Bộ","avatar":""},{"name":"Quan Sướng","avatar":""},{"name":"Viên Tử Minh","avatar":""},{"name":"Ngô Lạc Lang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
