INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bill-russell-huyen-thoai', 'Bill Russell: Huyền Thoại', 'Bill Russell: Legend', 'https://phimimg.com/upload/vod/20240308-1/614bf6bb8d9981179764e452b96555bd.jpg', 'https://phimimg.com/upload/vod/20240308-1/8b573a013508527bce6437bfe4701f0b.jpg', '<p>Bộ phim tài liệu tiểu sử này xoay quanh nhà vô địch NBA thành công nhất kiêm biểu tượng dân quyền Bill Russell, người gây dựng di sản hoành tráng cả ở trong và ngoài sân đấu.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 16, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Russell","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324254);
