INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-bo-bat-on', 'Ông Bố Bất Ổn', 'Unstable', 'https://phimimg.com/upload/vod/20240308-1/d045cae72f18713abfc510e7de6ea815.jpg', 'https://phimimg.com/upload/vod/20240308-1/b413cde5b9623938e2ddac7694502ee3.jpg', '<p>Một thiên tài công nghệ sinh học cố thoát khỏi hố sâu đau buồn với sự giúp đỡ của con trai, còn anh con trai thì cố thoát khỏi cái bóng của bố và cứu vãn việc làm ăn của gia đình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rob Lowe","avatar":""},{"name":"John Owen Lowe","avatar":""},{"name":"Sian Clifford","avatar":""},{"name":"Fred Armisen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324254);
