INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-cuoi-ca', 'Mèo Cưỡi Cá', 'Perfect Mismatch', 'https://phimimg.com/upload/vod/20240308-1/f25a7cefcbd975ed90512955782113d4.jpg', 'https://phimimg.com/upload/vod/20240308-1/f8e9cf6bd352c38874506be78a2ad9b0.jpg', '<p>Thi Hoa Hoa một cô gái vùng quê hoang dã, có tài võ nghệ, thông thạo “mười tám thế võ”, trên đường xuống núi rèn luyện phải thực hiện lời thề “chín chín tám mươi mốt lòng nhân ái” của sư phụ. Khi lần đầu tiên bước vào đô thị, do nhầm lẫn mà cô ấy đã trở thành người đại diện phát ngôn của một công ty và trượng nghĩa cứu giúp tổng tài bá đạo Châu Chi Phi. Tổng tài này vì bị cuốn vào thù hận gia đình mà nội tâm tổn thương sâu sắc. Một câu chuyện tưởng chừng như tình cờ nhưng cũng là một cơ duyên. Môi trường phát triển khác nhau, thái độ sống và lối sống của hai người đã hòa hợp và hàn gắn chữa lành nỗi đau cho nhau. Câu chuyện tình yêu giữa họ bắt đầu hình thành...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Chinh","avatar":""},{"name":"Lộ Tiểu Ngư","avatar":""},{"name":"Diệp Hạo Nhiên","avatar":""},{"name":"Lâm Yên Nhu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
