INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-on-dung-sung-toi-phan-4', 'Làm Ơn Đừng Sủng Tôi (Phần 4)', 'Please Don''t Spoil Me (Season 4)', 'https://phimimg.com/upload/vod/20240308-1/2340ace4d6e53c96872ba5bbcbd20889.jpg', 'https://phimimg.com/upload/vod/20240308-1/bd2b34d935ecbca2a3c99511d4fc0958.jpg', '<p>Tác giả mạng Nhan Nhất Nhất trong lúc tìm cảm hứng sáng tác thì vô tình gặp được Tần Ngự, mỹ nam cổ trang bước ra từ trong truyện, bảo rằng đang đi tìm ái phi Nhất Nhất. Sự xuất hiện của nhân vật hư cấu Tần Ngự gây náo loạn trật tự thế giới hiện thực, Nhan Nhất Nhất thân là tác giả thì càng bị trừng phạt nghiêm trọng hơn. Để bảo vệ bản thân và giữ cân bằng cho thế giới hiện thực và thế giới trong truyện, nên Nhan Nhất Nhất đã khởi động một cuộc tác chiến Chia tay khéo léo kéo dài 100 ngày với Tần Ngự.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Miểu Di","avatar":""},{"name":"Kim Hiền Chính","avatar":""},{"name":"Phổ Phổ","avatar":""},{"name":"Vương Tử Phi","avatar":""},{"name":"Đường Hạo","avatar":""},{"name":"Vương Long","avatar":""},{"name":"Hàn Giai Hủy","avatar":""},{"name":"Uông Dĩnh Phi","avatar":""},{"name":"Chu Thiên Tiêu","avatar":""},{"name":"Mã Thiến Thiến","avatar":""},{"name":"Vu Bỉnh Trì","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
