INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-gam', 'Tiếng Gầm', 'Dahaad', 'https://phimimg.com/upload/vod/20240308-1/53e61c3a251ffd8ffe0b57b84479eeba.jpg', 'https://phimimg.com/upload/vod/20240308-1/deb8eeeda459b5235080523764b32844.jpg', '<p>Phụ nữ đang biến mất không dấu vết ở Rajasthan và dường như không ai ngạc nhiên. Nhưng sĩ quan cảnh sát Anjali Bhaati nhận thấy sự giống nhau trong các vụ án: những cuộc điện thoại kéo dài hàng đêm và một người bạn trai mà không ai trong khu phố từng gặp.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Sonakshi Sinha","avatar":""},{"name":"Vijay Varma","avatar":""},{"name":"Gulshan Devaiah","avatar":""},{"name":"Sohum Shah","avatar":""},{"name":"Zoa Morani","avatar":""},{"name":"Jayati Bhatia","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
