INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-phi-cua-ta-khong-de-choc', 'Y Phi Của Ta Không Dễ Chọc', 'I Have A Smart Doctor Wife', 'https://phimimg.com/upload/vod/20240308-1/4eecce09c47e65376f169f9acbbcd133.jpg', 'https://phimimg.com/upload/vod/20240308-1/e1bfc3d038a6abdc790a1e8a85af8c02.jpg', '<p>Bộ phim kể về nhân vật chính Vấn Nhược Nguyệt, là một bác sĩ thời hiện đại. Trong một lần cứu người, cô không cẩn thận bị điện giật, và xuyên không về thời cổ đại. Cô đã dùng chính hệ thống y học của mình để hành y chữa bệnh, và bị chỉ định gả cho Ngọc Vương, thái tử triều trước. Hai con người, một người chữa bệnh cứu người, một người bảo vệ bách tính, từ ghét bỏ đến tán dương, đến kề vai sát cánh, yêu thương chữa lành lẫn nhau.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hứa Tình Nhã","avatar":""},{"name":"Văn Dĩ Phàm","avatar":""},{"name":"Minh Bằng","avatar":""},{"name":"Diệp Thư Dư","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324254);
