INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zombieverse', 'Zombieverse', 'Zombieverse', 'https://phimimg.com/upload/vod/20240308-1/0a2d425f1ea83d7d9a944ad5c78416a5.jpg', 'https://phimimg.com/upload/vod/20240308-1/69c32aa335ec8f8a095e1753c11307d4.jpg', '<p>Tại Seoul, nơi một đợt bùng phát virus thây ma đang hoành hành, ai sẽ đánh lừa lũ xác sống khi đối mặt với các nhiệm vụ đầy thử thách và sống sót trở về? Trong chương trình tạp kỹ thú vị này, một nhóm người nổi tiếng hoàn thành các nhiệm vụ và hợp tác cùng nhau để sống sót qua đợt bùng phát virus zombie.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Si-young","avatar":""},{"name":"Noh Hong-chul","avatar":""},{"name":"DinDin","avatar":""},{"name":"Fukutomi Tsuki","avatar":""},{"name":"Park Na-rae","avatar":""},{"name":"Dex","avatar":""},{"name":"Hong Sung-woo","avatar":""},{"name":"Patricia Thona Yiombi","avatar":""},{"name":"Jonathan Thona Yiombi","avatar":""},{"name":"Yoo Hee-kwan","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
