INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-nho-reminders', 'Vì Nhớ (ReminderS)', 'ReminderS', 'https://phimimg.com/upload/vod/20240308-1/4d23fadc0c03149288f8480cfa2bc88a.jpg', 'https://phimimg.com/upload/vod/20240308-1/eefcee02185388111caa780c5ed7cb7c.jpg', '<p>Vì Nhớ (ReminderS) kể về câu chuyện của Noh và Phun, giờ họ đã trưởng thành và là sinh viên đại học. Son và Pin đang yêu nhau và phải đối mặt với những vấn đề như ghen tuông, tự tin và tin tưởng. Còn Wish và Two là một cặp đôi mới bắt đầu mối quan hệ của họ.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 18, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chonlathorn Kongyingyong","avatar":""},{"name":"Nawat Phumphothingam","avatar":""},{"name":"Perth Tanapon Sukhumpantanasan","avatar":""},{"name":"Saint Suppapong Udomkaewkanjana","avatar":""},{"name":"Mean Phiravich Attachitsataporn","avatar":""},{"name":"Plan Rathavit Kijworalak","avatar":""}]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324254);
