INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-song-tich-cuc-len', 'Hãy Sống Tích Cực Lên', 'Along With Me', 'https://phimimg.com/upload/vod/20240308-1/9f08722749a644efa846a13e50b32314.jpg', 'https://phimimg.com/upload/vod/20240308-1/c43edb940641baba53efe412c381adfa.jpg', '<p>Câu chuyện của bộ phim này xoay quanh hai người bạn nhỏ đã khiêu vũ với nhau từ tấm bé. Đầu sư - Lạc Tinh Tinh và Đuôi sư - Hà Dương Quang từ nhỏ đã lớn lên cùng nhau, bị ảnh hưởng bởi người ông là thầy múa lân . Sau đó, gia đình họ Hà gặp biến cố, vì thế cả gia đình chuyển đến nước ngoài sinh sống, hai người chia tay và không còn liên lạc với nhau. Nhiều năm sau, Lạc Tinh Tinh đã đổi cả họ và tên, đại diện cho Đại học Thiên Phủ đến Singapore để trao đổi, nhưng tình cờ gặp Hà Dương Quang khi đã trưởng thành. Sau đó, Hà Dương Quang có cơ hội trở lại Trung Quốc, hai người cuối cùng gặp nhau ở lối vào của con phố cổ. Lúc này, nhìn Lạc Tinh Tinh đang bị chủ nợ truy đuổi, còn phải một mình chăm sóc bà của mình, trong lòng Hà Dương Quang có vô số nghi ngờ. Đối mặt với Lạc Tinh Tinh vừa gặp khi ấy, lần này anh chọn làm chỗ dựa vững chắc cho Lạc Tinh Tinh và âm thầm bù đắp cho cô; Mọi người cuối cùng cũng cởi trói cho nhau, giống như chú sư tử nhỏ</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Hành Kiến","avatar":""},{"name":"Mục Tử Dương","avatar":""},{"name":"Vương Nhược Hi","avatar":""},{"name":"Tô Tử Anh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
