INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hay-song-tich-cuc-len', 'Hãy Sống Tích Cực Lên', 'Along With Me', 'hãy sống tích cực lên along with me ngô hành kiến mục tử dương vương nhược hi tô tử anh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-phuong-lenh', 'Long Phượng Lệnh', 'Dragon And Phoenix''s Order', 'https://phimimg.com/upload/vod/20240308-1/5a7d90210d786b528a7e735938664e1e.jpg', 'https://phimimg.com/upload/vod/20240308-1/10a02255c9dbc23d3811418e7643f469.jpg', '<p>Phong Nhung Quốc ở Cửu Châu tôn sùng võ thuật. Bạch Tịch Dao, tông chủ Long Sát Tông và Lăng Hạo Hiền, minh chủ của Phượng Thê Minh đã tham gia vào trận chiến tranh cướp báu vật, nhưng do vụ nổ năng lượng của Thiên Thư Lệnh, linh hồn của hai người bị hoán đổi cho nhau. Hai con người mù mờ bị ép buộc phải che giấu thân phận và ẩn nấp trong doanh trại quân địch. Từ hai kẻ thù không ưa nhau, đến cặp đôi ăn ý đồng tâm hiệp lực cùng nhau đối phó với các tình huống nguy hiểm trong môn phái, cả hai đã dần dần hiểu nhau hơn. Nào ngờ, hai người sở hữu Thiên Thư Lệnh đã bị Thánh Quang Hội nhắm đến từ lâu. Cặp đôi đồng điệu cảm nhận được thế lực ma quỷ bí ẩn đang âm thầm trỗi dậy, lập tức đi đến quyết định chung, vạch trần âm mưu của kẻ thủ ác, chấm dứt tranh chấp giữa hai phe, giữ vững hòa bình chốn võ lâm. Trong quá trình này, cặp đôi đồng điệu kề cận sớm tối, tam quan đồng nhất, dần dần nảy sinh tình cảm, ước hẹn cùng nhau sống đến răng long đầu bạc!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Thừa Lâm","avatar":""},{"name":"Phan Duyệt","avatar":""},{"name":"Lưu Tích Minh","avatar":""},{"name":"Trần Hoàn","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324254);
