INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-khong-hop-de-yeu', 'Mùa Hè Không Hợp Để Yêu', 'Summer In Love', 'https://phimimg.com/upload/vod/20240308-1/b278e60c63bc242af9e1c1992d89b1b4.jpg', 'https://phimimg.com/upload/vod/20240308-1/9a435b92d42dffd3132cefcff4eef498.jpg', '<p><em>Mùa Hè Không Hợp Để Yêu - Summer in Love (VietSub - Thuyết Minh)</em>&nbsp;Những người thân yêu của Shi Yi và Xia He cùng quay trở lại năm 2008 với nhau. Trong khi đang tận hưởng thời gian bên nhau, người chồng trong tương lai đã lạm dụng Shi Yi, và cùng với cô vợ đã lừa dối anh ta, đều quay trở lại quá khứ, và 4 người họ phải đối mặt để chiến đấu cho tình yêu và thù hận của số phận.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Quân Hạo","avatar":""},{"name":"Bạch Hân Di","avatar":""},{"name":"Quách Khương Mẫn","avatar":""},{"name":"Diêu An Ni","avatar":""},{"name":"Trịnh Vi Chi","avatar":""},{"name":"Châu Dung Thiến","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
