INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('laws-of-attraction-luat-hap-dan', 'Laws Of Attraction: Luật Hấp Dẫn', 'Laws Of Attraction', 'https://phimimg.com/upload/vod/20240308-1/1e2349fef22caa8907ec88bc68ceb72e.jpg', 'https://phimimg.com/upload/vod/20240308-1/df6ebb6d6f122493a0456ea4ebae4006.jpg', '<p>Laws of Attraction: Luật Hấp Dẫn kể về câu chuyện của Charn và Tin. Charn là một luật sư thông minh, thích xử lý các vụ án với phần thưởng cao hoặc đem lại danh tiếng cho bản thân. Bất kể sử dụng phương pháp nào, anh ta đều có thể biến sai thành đúng. Nhưng một ngày nọ, anh bị loại khỏi một vụ án cao cấp mà không biết tại sao, điều này khiến anh ta cảm thấy xấu hổ và có lỗi với chính mình. Charn nghi ngờ rằng phải có một số manh mối trong vụ án này, vì vậy chính vì lợi ích của mình mà anh ấy cũng phải tìm ra chúng. Anh quyết định đổi phe để giúp đỡ Tin ở phe còn lại, chú của Tonkao, người đã chết oan trong một vụ tai nạn xe hơi. Tin làm mọi thứ có thể để cố gắng đòi lại công bằng cho đứa cháu của mình, nhưng những tuyên bố của anh lại gây tác dụng ngược. Charn và Tin cùng nhau điều tra sự thật của vụ án. Nhưng họ càng điều tra, nguy hiểm càng lớn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Film Thanapat Kawila","avatar":""},{"name":"Jam Rachata Humphanon","avatar":""},{"name":"Pearl Satjakorn  Chalard","avatar":""},{"name":"See Parattakorn Kaiyanan","avatar":""},{"name":"Not Vorarit Fuangarome","avatar":""},{"name":"Organ Rasee Diskul Na Ayudhaya","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
