INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('laws-of-attraction-luat-hap-dan', 'Laws Of Attraction: Luật Hấp Dẫn', 'Laws Of Attraction', 'laws of attraction: luật hấp dẫn laws of attraction film thanapat kawila jam rachata humphanon pearl satjakorn  chalard see parattakorn kaiyanan not vorarit fuangarome organ rasee diskul na ayudhaya ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-trong-mong-xuan-khue', 'Người Trong Mộng Xuân Khuê', 'Romance Of A Twin Flower', 'https://phimimg.com/upload/vod/20240308-1/778e8497779dfe59a777425f870d12a8.jpg', 'https://phimimg.com/upload/vod/20240308-1/b68391eec407ce20f2144927f6bebe10.jpg', '<p>Quý Mạn lớn lên ở Hải Phường từ nhỏ, vốn là một thiếu nữ vô lo, không ngờ trong một lần vào kinh chơi lại gặp chuyện ngoài ý muốn, sau khi tỉnh lại Quý Mạn bỗng mất trí nhớ và trở thành phu nhân của Mạch Ngọc hầu Ninh Ngọc Hiên. Ninh Ngọc Hiên là thiếu niên anh tài, được Hoàng đế coi trọng, vẫn luôn âm thầm điều tra manh mối về kẻ thù giết cha. Quý Mạn bị coi là đại phu nhân hung ác hay đố kỵ Nhiếp Tang Du, bị Ninh Ngọc Hiên nhốt vào Tư Quá Các. Để thoát khỏi hoàn cảnh khó khăn, Quý Mạn trở mình nhờ việc bán Thư Ngân Cao, rồi lại cứu phu quân trước mặt Hoàng thượng, được phong cáo mệnh phu nhân nhị phẩm. Ninh Ngọc Hiên điều tra ra manh mối về kẻ thù giết cha khi tiêu diệt thổ phỉ, lại bị người ta hãm hại nhốt vào nhà lao, bị sung quân đến Hải Phường. Sau khi đến Hải Phường, Ninh Ngọc Hiên và Quý Mạn liên tục đánh bại hai kẻ ác thống trị Hải Phường. Dưới sự quản lý của Ninh Ngọc Hiên, Hải Phường phát triển rực rỡ. Quý Mạn cũng kinh doanh tiệm son phấn Hạo Tuyết Đường với bạn bè. Trên hành trình này, tình cảm giữa Ninh Ngọc Hiên và Quý Mạn đã sớm trở nên sâu đậm. Khi hai người bái đường thành thân, thân thế của Quý Mạn bỗng nhiên bị vạch trần. Đối mặt với chuyện cũ, lần này họ sẽ lựa chọn thế nào...</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đinh Vũ Hề","avatar":""},{"name":"Bành Tiểu Nhiễm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324254);
