INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-thay', 'Cảm Ơn Thầy', 'Thank You Teacher', 'https://phimimg.com/upload/vod/20240308-1/5ce63d1d1ecb48a051ae53123d30a9c5.jpg', 'https://phimimg.com/upload/vod/20240308-1/1fc98dcf8c8f877d6470ab048bbb3dc9.jpg', '<p>Xoay quanh một cô gái trẻ muốn trở thành giáo viên giỏi, nhưng điều đó thật khó khăn khi cô ấy phải đối mặt với sự bất bình đẳng trong xã hội học đường và nhiều trở ngại khác nhau để trở thành một giáo viên. Liệu cô ấy có thể trở thành người khởi đầu cho một sự thay đổi trong hệ thống giáo dục?</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Cherprang Areekul","avatar":""},{"name":"Nattapong Pibultanakiet","avatar":""},{"name":"Hattaya Wongkrachang","avatar":""},{"name":"Silp Ruchiravanich","avatar":""},{"name":"Sedthawut Anusit","avatar":""},{"name":"Anthony Buisseret","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
