INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-dang', 'Hải Đăng', 'Lighthouse', 'https://phimimg.com/upload/vod/20240308-1/61bc4f2b74a7fd5878bee550190bf98c.jpg', 'https://phimimg.com/upload/vod/20240308-1/735ca8f90da1b71d5b87b2382c199f3e.jpg', '<p>Hai nghệ sĩ giải trí hàng đầu tình cờ gặp nhau để trò chuyện thực sự, làm sáng tỏ những tổn thương và lo lắng của họ, đồng thời mang đến nhiều tiếng cười trong suốt quá trình.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Gen Hoshino","avatar":""},{"name":"Masayasu Wakabayashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324254);
