INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-lua-chon-cua-phu-nu', 'Sự Lựa Chọn Của Phụ Nữ', 'Women''s Choice', 'https://phimimg.com/upload/vod/20240308-1/5a82453fee2dd9d43c83b9d7883569d9.jpg', 'https://phimimg.com/upload/vod/20240308-1/9f237f09557628d0d1da48741e36d00e.jpg', '<p>Trong mắt người ngoài, Su Yu Ning gần như có một cuộc sống viên mãn: sự nghiệp phát đạt, người chồng hiền lành và cô con gái ngoan ngoãn. Thật bất ngờ, cuộc sống tuyệt vời này đã sụp đổ chỉ sau một đêm. Đầu tiên là chồng cô lừa dối, sau đó con gái cô bị thương và bất tỉnh. Chẳng mấy chốc, Su Yu Ning phát hiện ra rằng cô ấy đã là một phần của và ở giữa một âm mưu được tính toán. Và thứ cố thủ, ở trung tâm của âm mưu lại chính là người mà cô không bao giờ ngờ tới. Để bảo vệ con gái mình, Su Yu Ning đã phải đứng ra tuyên chiến với cô ta.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 17, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Daotie","avatar":""},{"name":"Shuai Zhao","avatar":""},{"name":"Carmen Tong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
