INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-boc-chay', 'Thành Phố Bốc Cháy', 'City On Fire', 'https://phimimg.com/upload/vod/20240308-1/f7e2ecf00bae7830c946a50a05a5f28f.jpg', 'https://phimimg.com/upload/vod/20240308-1/e7ba3e1d2fa1d481a3f947d50d809905.jpg', '<p>Một sinh viên đại học bị bắn ở Công viên Central Park vào ngày 4 tháng 7 năm 2003. Cuộc điều tra xâu chuỗi một loạt vụ cháy bí ẩn trên toàn thành phố, làng âm nhạc trung tâm thành phố và một gia đình bất động sản giàu có đang gặp xung đột dưới áp lực của nhiều bí mật mà họ nắm giữ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jemima Kirke","avatar":""},{"name":"Wyatt Oleff","avatar":""},{"name":"Chase Sui Wonders","avatar":""},{"name":"Nico Tortorella","avatar":""},{"name":"Ashley Zukerman","avatar":""},{"name":"Xavier Clyde","avatar":""},{"name":"Max Milner","avatar":""},{"name":"Alexandra Doke","avatar":""},{"name":"Omid Abtahi","avatar":""},{"name":"Kathleen Munroe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
