INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-mua-ha', 'Hoa Mùa Hạ', 'The Forbidden Flower', 'https://phimimg.com/upload/vod/20240308-1/9bf9c2e98ea31612e9697000a8facd0d.jpg', 'https://phimimg.com/upload/vod/20240308-1/c5cb350ac8efa08ac9eedc9991a01f13.jpg', '<p>Bộ phim kể về quá trình học hỏi, yêu đương và trưởng thành của cô gái mang bệnh Hà Nhiễm ở giai đoạn cuối cùng của cuộc đời. Sau khi gặp Tiêu Hàn, một thợ làm vườn nghệ thuật khó buông bỏ quá khứ và gần như mất niềm tin vào tương lai. Hai người họ đã trải qua những cuộc gặp gỡ bất đắc dĩ nhưng lãng mạn, từ đó tìm lại được những điều mất mát quan trọng nhất trong cuộc đời của mình, tìm nhặt lại được niềm tin và hy vọng với cuộc sống cũng như có được tình yêu khắc cốt ghi tâm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngôn Thừa Húc","avatar":""},{"name":"Từ Nhược Hàn","avatar":""},{"name":"Hoàng Nghị","avatar":""},{"name":"Mã Tư Siêu","avatar":""},{"name":"Từ Tân Chi","avatar":""},{"name":"Ngô Nhã Hằng","avatar":""},{"name":"Viên Tương","avatar":""},{"name":"Vương Tử Hàn","avatar":""},{"name":"Triệu Viên Nguyên","avatar":""},{"name":"Đường Tăng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
