INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-mua-ha', 'Hoa Mùa Hạ', 'The Forbidden Flower', 'hoa mùa hạ the forbidden flower ngôn thừa húc từ nhược hàn hoàng nghị mã tư siêu từ tân chi ngô nhã hằng viên tương vương tử hàn triệu viên nguyên đường tăng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('be-mine-superstar', 'Be Mine. Superstar', 'Be Mine. Superstar', 'https://phimimg.com/upload/vod/20240308-1/6d7e9367053f4e61ae217bf8aed5927e.jpg', 'https://phimimg.com/upload/vod/20240308-1/54d41eeb43e9cefddb0c96c2ca093e30.jpg', '<p>Bộ phim kể về câu chuyện giữa ngôi sao truyền hình Ashi và thực tập sinh Pun. Thực tập sinh Pun đã yêu Ashi được chín năm. Mục tiêu cuối cùng của Pun là biến Ashi thành bạn trai của mình. Mặc dù Ashi đã từ bỏ mọi ý định về một mối quan hệ từ lâu nhưng Pun sẽ làm mọi cách để chứng minh tình yêu của mình dành cho Ashi. Cho đến khi Ashi nhận được một vai trong một bộ phim Nhật Bản. Ashi chưa bao giờ trải qua một mối quan hệ đồng tính, và anh ấy nghĩ rằng anh ấy có thể hiểu nhân vật này hơn nếu anh ấy có kinh nghiệm. Vì vậy, anh ấy quyết định mở lòng với Pun và để anh ấy bước vào cuộc đời mình. Điều này dẫn đến việc Title, người phải lòng Ashi, muốn hủy hoại mối quan hệ của họ. Còn siêu sao Nhật Bản Kevin cũng công khai rằng anh cũng thích Ashi. Mọi thứ trở nên phức tạp. Tình yêu của họ sẽ thành công hay thất bại?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ja Phachara Suansri","avatar":""},{"name":"First Chalongrat Novsamrong","avatar":""},{"name":"Bosston Suphadach Wilairat","avatar":""},{"name":"Jo Kavinpat Thanahiransilp","avatar":""},{"name":"Wayo Peerawat Sareewong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
