INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phan-cong-cua-me', 'Cuộc Phản Công Của Mẹ', 'Mommy''s Counterattack', 'https://phimimg.com/upload/vod/20240308-1/b48fc728cf5c1d3568385fdd78344d2a.jpg', 'https://phimimg.com/upload/vod/20240308-1/17a05313b330d30496ad5d9c81bac8b6.jpg', '<p>Cuộc Phản Công Của Mẹ kể về một cặp vợ chồng trẻ bị buộc phải chia tay trong 5 năm vì một mối quan hệ Yun Weiwei, và sau 5 năm gián đoạn, cô trở lại xinh đẹp để bắt đầu kế hoạch trả thù của riêng mình và tiết lộ sự thật của năm từng bước. Trong poster cuối cùng được phát hành hôm nay, Yun Qingwei (Lí Boyang thủ vai) đã dữ dội nắm lấy cà vạt của Giang Linh (Triệu Yibo thủ vai). Bắt chước. Tình yêu vượt quá sự hận thù trong đôi mắt của anh ta, chứa đầy một cảm giác mờ ám của sự tán tỉnh và dục vọng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Nhất Bác","avatar":""},{"name":"Lý Bác Dương","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
