INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-phan-cong-cua-me', 'Cuộc Phản Công Của Mẹ', 'Mommy''s Counterattack', 'cuộc phản công của mẹ mommy''s counterattack triệu nhất bác lý bác dương ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-muc-cung-chieu', 'Một Mực Cưng Chiều', 'Just Spoil You', 'https://phimimg.com/upload/vod/20240308-1/ff8748ca948dad8c6db221f5effc218d.jpg', 'https://phimimg.com/upload/vod/20240308-1/56925a0dd151b9e8225984f39fb4ec38.jpg', '<p>Cô nàng Chung Linh vì muốn chữa bệnh tiểu đường bẩm sinh của cậu con trai Khả Nhạc, đã đưa cậu bé trở lại thành phố mà mình rời đi 6 năm trước do chia tay với người yêu cũ Hàn Đông Lai. Ngờ đâu, khi Khả nhạc đi lạc, cậu bé tình cờ gặp gỡ Hàn Đông Lai, người trông rất giống người đàn ông thường xuất hiện trong bộ sưu tập của mẹ. Khả Nhạc nhầm người đó là cha và được Hàn Đông Lai đưa về văn phòng, tạo ra một cuộc trùng phùng và mở ra một tình yêu đầy tình thương và oan trái. Khi hai người gặp lại nhau, họ lại bị vướng vào vấn đề về nguồn gốc và tình trạng bệnh tật của Khả Nhạc. Một mặt, do Chung Linh rời đi những 6 năm, bạn thân của cô nàng từ kẻ vô danh vượt lên thành ngôi sao hàng đầu, việc tác phẩm của mình có cơ hội đề cử chuyển thể lại khiến bạn trai cũ Hàn Đông Lai ghen tị, âm thầm điều tra. Mặt khác, sự trở lại của Chung Linh khiến kẻ nặng tình với Hàn Đông Lai là Lâm Hạ Tịch phát điên, lại âm mưu hãm hại lần nữa. Cha ruột của Khả Nhạc là ai? Mối tình xưa liệu có cơ hội tái hợp?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Hao Xuan","avatar":""},{"name":"Song Mei Na","avatar":""},{"name":"MO","avatar":""},{"name":"Ma Qiu Yuan","avatar":""},{"name":"Li Yi Chen","avatar":""},{"name":"liuhanyu","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324254);
