INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-ky-la', 'Hành Tinh Kỳ Lạ', 'Strange Planet', 'https://phimimg.com/upload/vod/20240308-1/5a9267ba1cc4518541868dadfc2e078f.jpg', 'https://phimimg.com/upload/vod/20240308-1/b55a32274711a006b7e0b04277252078.jpg', '<p>Chào mừng đến với một hành tinh xa xôi không khác với chúng ta lắm, với những quan sát hài hước mà thấm thía về cuộc sống, tình yêu và tình bạn, được kể theo cách cực kỳ đặc biệt. Từ những nhà sáng tạo Nathan W. Pyle và Dan Harmon.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hannah Einbinder","avatar":""},{"name":"Danny Pudi","avatar":""},{"name":"Lori Tan Chinn","avatar":""},{"name":"Tunde Adebimpe","avatar":""},{"name":"Demi Adejuyigbe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324254);
