INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-ngu-yen', 'Sự Thật Ngủ Yên', 'Sleeping Dog', 'https://phimimg.com/upload/vod/20240308-1/3d28074cc643bac0d172c6fd5f3ec502.jpg', 'https://phimimg.com/upload/vod/20240308-1/0c731257a2d6e156d6eef2e63aaf4a2d.jpg', '<p>Một cựu thanh tra hiện sống lang thang trên đường tìm kiếm sự thật sau khi một cái chết khơi dậy những nghi ngờ đáng ngại về vụ án mạng tưởng chừng đã phá giải xong.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Max Riemelt","avatar":""},{"name":"Luise Von Finckh","avatar":""},{"name":"Carlo Ljubek","avatar":""},{"name":"Melika Foroutan","avatar":""},{"name":"Peri Baumeister","avatar":""},{"name":"Melodie Wakivuamina","avatar":""},{"name":"Antonio Wannek","avatar":""},{"name":"Tara Africah Corrigan","avatar":""},{"name":"Helgi Schmid","avatar":""},{"name":"Bernd Hölscher","avatar":""},{"name":"Martin Wuttke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
