INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-lac-bo-nhung-ke-mat-ngu', 'Câu Lạc Bộ Những Kẻ Mất Ngủ', 'Insomniacs After School', 'https://phimimg.com/upload/vod/20240308-1/06b4cee8aa435d22c98836973563034a.jpg', 'https://phimimg.com/upload/vod/20240308-1/2d0f2b29bc79107c07f417e72f8765f3.jpg', '<p>Nakami là một học sinh trung học siêng năng nhưng luôn cáu kỉnh và chống đối xã hội. Tuy nhiên, thái độ tồi tệ ấy của cậu xuất phát từ việc bị rối loạn giấc ngủ và thường xuyên thức trắng đêm. Một ngày nọ, cậu được nhờ đến đài quan sát thiên văn của trường để lấy đồ, một nơi được cho là bị ma ám. Cũng tại đây, cậu tình cờ phát hiện người bạn cùng lớp là Magari Isaki cũng đang mượn nơi này để chợp mắt. Hai con người giống nhau, cùng che giấu những vấn đề về chứng mất ngủ đã tìm đến đài quan sát như một chốn để bù đắp cho những đêm dài thao thức... Liệu họ có tìm thấy sự an yên mà bấy lâu nay vẫn kiếm tìm?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Gen Sato","avatar":""},{"name":"Konomi Tamura","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Lynn","avatar":""},{"name":"Natsumi Fujiwara","avatar":""},{"name":"Sumire Morohoshi","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Sho Karino","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
