INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-trai-tim-gan-nhau', 'Khi Trái Tim Gần Nhau', 'Don''t Say No The Series', 'https://phimimg.com/upload/vod/20240308-1/61a122869ec2b26b3529b68bfba55a6c.jpg', 'https://phimimg.com/upload/vod/20240308-1/c7ea5b1eade0e70699b6b8dc6ac9c7e6.jpg', '<p>“Leo” và “Fiat” là đôi bạn thân từ nhỏ từ mười năm trước. Họ lớn lên cùng nhau và chia sẻ mọi khoảnh khắc quan trọng trong cuộc đời với nhau. Leo và Fiat không thể tưởng tượng về cuộc sống thiếu nhau. Nhưng khi Fiat bắt đầu để ý tới một người khác, Leo bắt đầu cảm thấy lo lắng nên cậu đã đưa ra một quyết định quan trọng với sự hỗ trợ từ những người bạn chơi bóng rổ của mình, là thổ lộ tình cảm với Fiat. Liệu Fiat có chấp nhận tình cảm của Leo hay lời thú nhận bất ngờ này sẽ sự hủy hoại tình bạn này?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ja Phachara Suansri","avatar":""},{"name":"First Chalongrat Novsamrong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
