INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lau-dai-mau-trang', 'Lâu Đài Màu Trắng', 'The White Castle', 'https://phimimg.com/upload/vod/20240308-1/657a3fc27fa41b16ff1328d45b72f7e3.jpg', 'https://phimimg.com/upload/vod/20240308-1/9c32ffdb983ba17b1cd54a8c2e83bdce.jpg', '<p>Vào mùa tốt nghiệp, Wang Yangming, một bác sĩ y khoa, vào khoa cấp cứu của bệnh viện Ankang với tư cách là một bác sĩ thực tập, nhưng bị giám đốc khoa cấp cứu, ông chủ Guan, buộc phải làm người học việc cho Louis, người muốn từ chức, và đã chán ghét. Liu Fei, người cùng lúc gia nhập Wang Yangming, cực kỳ có năng lực, sự khinh thường của Louis và sự đè bẹp của Liu Fei đã truyền cảm hứng cho mong muốn chiến thắng của Wang Yangming. Anh ấy đã không từ bỏ bất kỳ cơ hội đào tạo nào, không chỉ thoát khỏi thành kiến của mọi người đối với sinh viên y khoa thiên về nghiên cứu, mà còn có được tình bạn và tình yêu, đồng thời thành lập Bốn bác sĩ cấp cứu cùng với Louis, Zu Wenda và Liu Fei .</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bành Quán Anh","avatar":""},{"name":"Đá Thông Từ","avatar":""},{"name":"gai Yuexi","avatar":""},{"name":"Cao Tân","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
