INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-mau-phao-hoa-nhan-gian', 'Sắc Màu Pháo Hoa Nhân Gian', 'Falling Before Fireworks', 'https://phimimg.com/upload/vod/20240308-1/7fc5a2a2f823052969428e9675cffa2b.jpg', 'https://phimimg.com/upload/vod/20240308-1/a2b833029b9b617d5a399dc15c2a08fe.jpg', '<p>Sắc Màu Pháo Hoa Nhân Gian (Falling Before Fireworks) xoay quanh cô nàng nhân viên bị áp đặt bởi công việc, xinh đẹp và năng động, với thành tích làm việc xuất sắc, sống cuộc sống bình thường theo đuổi xe hơi, căn hộ và tiền bạc. Để thu hồi một khoản vay không tốt, cô đã gặp gỡ lần đầu với nghệ nhân truyền thống Jing Chen. Một người là một nhân viên văn phòng bị áp lực bởi nhiệm vụ thu nợ, một người không có xe hơi, căn hộ và tiền bạc, nhưng sống ở nông thôn, được bao quanh bởi núi non và sông xanh lạnh. Hai người không hợp nhau, họ đối đầu nhau như một cặp oan gia khó hiểu. Vào ngày đông chí, sinh nhật thứ 28, cô cảm thấy bị bỏ rơi bởi bố mẹ và cô đơn bởi đồng nghiệp. Cô đến khu vườn Sự Viên, với một cốc rượu ngọt đông chí của Jing Chen, cô nghĩ rằng đó là sự ấm áp duy nhất trong sinh nhật của mình, dưới sự xúc động, cô đã đề nghị kết hôn. Jing Chen cũng đồng ý với yêu cầu của cô tuy nhiên, hôn nhân chỉ là khởi đầu.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lộ Dương Dương","avatar":""},{"name":"Trần Tâm Hải","avatar":""},{"name":"Nam Sinh","avatar":""},{"name":"Triệu Chấn Đình","avatar":""},{"name":"Cơ Hào","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324254);
