INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-khong-ten', 'Tình Yêu Không Tên', 'When I See Your Face', 'https://phimimg.com/upload/vod/20240308-1/e84192f15893583b7c255d0bfbd8ef4f.jpg', 'https://phimimg.com/upload/vod/20240308-1/2fb85b0b3d5d6a3ef16fadba53694615.jpg', '<p>Lộc Hối là cô gái sinh ra với chứng mù mặt nặng và quen giữ khoảng cách với người khác. Lãng Thừa Châu, một sinh viên trao đổi quốc tế tại Đại học Đức Thành, đã cứu Lộc Hối, người bị nghi ngờ đạo văn. Trong ngày đầu tiên trở lại trường, không ngờ anh lại bị Lộc Hối \3 lần chạm mặt soái ca mà không nhận ra\</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Duan Ao Juan","avatar":""},{"name":"Chen Bo Hao","avatar":""},{"name":"Lv Yun Feng","avatar":""},{"name":"Kuliko Shen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324254);
