INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ven-man-su-that-phan-3', 'Vén Màn Sự Thật (Phần 3)', 'Truth Be Told (Season 3)', 'https://phimimg.com/upload/vod/20240308-1/47665390467e11a3dc4b6059010d27e6.jpg', 'https://phimimg.com/upload/vod/20240308-1/cee8dfb9e4a2bc47a18b547e44025ed5.jpg', '<p>Trong phần ba, Poppy, thất vọng vì thiếu sự chú ý của giới truyền thông đối với một số cô gái trẻ Da đen mất tích, hợp tác với một hiệu trưởng không chính thống để giữ tên tuổi của các nạn nhân trong mắt công chúng trong khi truy đuổi dẫn đến một đường dây buôn bán tình dục bị nghi ngờ có thể đã gài bẫy họ. .</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Octavia Spencer","avatar":""},{"name":"Mekhi Phifer","avatar":""},{"name":"Ron Cephas Jones","avatar":""},{"name":"Tracie Thoms","avatar":""},{"name":"Haneefah Wood","avatar":""},{"name":"Gabrielle Union","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324254);
