INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-ban-trai-cua-toi', 'Xin Chào, Bạn Trai Của Tôi', 'The Girl Who Sees Smells', 'https://phimimg.com/upload/vod/20240308-1/7fc8796cc717383976c87851ae3f2758.jpg', 'https://phimimg.com/upload/vod/20240308-1/741302f8a6b168c3b55b86bc6ab9b950.jpg', '<p>Lục Phần Phần người đang ở dưới đáy cuộc đời, có tài năng thiên bẩm về hương vị và mơ ước trở thành bậc thầy về rượu, nhưng cô chỉ có thể làm nhân viên quảng cáo rượu trong siêu thị. Tình cờ, cô cứu được Hứa Minh Thần, chủ tịch của An Đạt Group. Một nụ hôn bất ngờ đã mở ra cánh cửa định mệnh cho mối quan hệ giữa hai người - nụ hôn ấy trở thành liều thuốc duy nhất cho căn bệnh kỳ lạ của Minh Thần. Để chữa khỏi bệnh, Minh Thần đã tiếp cận và theo đuổi Lục Phần Phần bằng nhiều cách khác nhau. Minh Thần dần dần từ chán ghét trở nên thích thú. Những tưởng cuối cùng cũng có một tình yêu viên mãn, nhưng tình yêu giữa hai người vẫn gặp phải nhiều thử thách, sự ngăn cản của người thân trong gia đình, những lời nói dối với động cơ không trong sáng, mâu thuẫn giữa những giấc mơ và sự nghiệp. Cuối cùng trải qua bao khó khăn họ cũng có một tình yêu tuyệt đẹp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jia Yi","avatar":""},{"name":"Jin Zi Xuan","avatar":""},{"name":"Phan Hiểu Đông","avatar":""},{"name":"Wu Ming Jing","avatar":""},{"name":"Du Hou Jia","avatar":""},{"name":"Chen Yi Qi","avatar":""},{"name":"Gao Kai Yuan","avatar":""},{"name":"Boyang Li","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
