INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chao-mung-toi-eden-phan-2', 'Chào Mừng Tới Eden (Phần 2)', 'Welcome To Eden (Season 2)', 'https://phimimg.com/upload/vod/20240308-1/7f231adf3d52f2b0e92e769993b4ee7e.jpg', 'https://phimimg.com/upload/vod/20240308-1/fdf4fb861b7825985106d7dca84a283b.jpg', '<p>Bạn có hạnh phúc không? Với câu hỏi này, Zoa và bốn thanh niên hấp dẫn khác, rất tích cực trên mạng xã hội, được mời tham dự bữa tiệc độc nhất trong lịch sử trên một hòn đảo bí mật, được tổ chức bởi một thương hiệu đồ uống mới. Những gì bắt đầu như một hành trình thú vị sẽ sớm trở thành hành trình của cả cuộc đời. Nhưng thiên đường không thực sự như vẻ ngoài của nó - Chào mừng đến với Eden.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Amaia Salamanca","avatar":""},{"name":"Amaia Aberasturi","avatar":""},{"name":"Belinda","avatar":""},{"name":"Lola Rodríguez","avatar":""},{"name":"Sergio Momo","avatar":""},{"name":"Begoña Vargas","avatar":""},{"name":"Berta Vázquez","avatar":""},{"name":"Tomy Aguilera","avatar":""},{"name":"Carlos Soroa","avatar":""},{"name":"Ana Wagener","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
