INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-phu-dai-nhan-co-thuat-doc-tam', 'Thủ Phụ Đại Nhân Có Thuật Đọc Tâm', 'The Senior Grand Secretary Can Read Minds', 'https://phimimg.com/upload/vod/20240308-1/871e04f8fb5e3acebd8a781bcb87d76d.jpg', 'https://phimimg.com/upload/vod/20240308-1/c6ed30dcab61cf8e92ddd79a23baddfe.jpg', '<p>Blogger ẩm thực Thẩm Tri Hoan đã xuyên không nhập vào thân xác của Thẩm Tri Hoan, người vợ mới thành hôn nửa năm của thủ phụ đương triều Đại Tuy Dư Yến Thanh. Tuy nhiên, số phận trêu ngươi, theo ghi chép lịch sử, thủ phụ đại nhân không chỉ độc ác tàn nhẫn, mà còn bị phe nổi phản quân thắt cổ chết ở tuổi 30. Thẩm Tri Hoan muốn thoát khỏi nanh vuốt hắn ta, không ngờ càng lún càng sâu. Vốn tưởng thủ phụ đại nhân không việc ác nào không làm, nhưng trong quá trình tiếp xúc, cũng dần dần nhìn rõ tâm can nhau, giữa hai người bắt đầu nảy sinh tình cảm. Tuy nhiên, cuộc tranh đấu triều đình phía sau họ đã khiến cả hai phải trải qua nhiều nguy hiểm ...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khâu Đỉnh Kiệt","avatar":""},{"name":"Quản Kim Lân","avatar":""},{"name":"Đổng Hiểu Húc","avatar":""},{"name":"Trương Ý Nguyệt","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324254);
