INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ridley-jones-phan-5', 'Ridley Jones (Phần 5)', 'Ridley Jones (Season 5)', 'https://phimimg.com/upload/vod/20240308-1/f2857cb7f138fdb302253a92f4117bfb.jpg', 'https://phimimg.com/upload/vod/20240308-1/eb5d5eced6b3e66084b3500bd47438c3.jpg', '<p>Cô bé tò mò Ridley và những người bạn của mình bảo vệ kho báu của Bảo tàng Lịch sử Tự nhiên và giữ bí mật kỳ diệu của nó an toàn: Mọi thứ trở nên sống động vào ban đêm!</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iara Nemirovsky","avatar":""},{"name":"iris menas","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324254);
