INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-ly-hon-shin', 'Luật Sư Ly Hôn Shin', 'Divorce Attorney Shin', 'https://phimimg.com/upload/vod/20240308-1/e60958533643ad1676a5b712b518ed9d.jpg', 'https://phimimg.com/upload/vod/20240308-1/f15d3389e2d542e8d04b640c18cb0922.jpg', '<p>Một bi kịch riêng thúc đẩy người nghệ sĩ dương cầm nọ trở thành luật sư. Anh xoay xở trong thế giới ly hôn phức tạp và dốc sức giúp thân chủ chiến thắng bằng mọi giá.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Seung Woo","avatar":""},{"name":"Han Hye Jin","avatar":""},{"name":"Kim Sung Kyun","avatar":""},{"name":"Jung Moon Sung","avatar":""},{"name":"Kang Mal Geum","avatar":""},{"name":"Cha Hwa Yeon","avatar":""},{"name":"Jeon Bae Soo","avatar":""},{"name":"Noh Susanna","avatar":""},{"name":"Han Eun Seong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324254);
