INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-dau', 'Yêu Là Đau', 'Love Hurts', 'https://phimimg.com/upload/vod/20240308-1/868782d855bdc7fbfff23bbdea156e49.jpg', 'https://phimimg.com/upload/vod/20240308-1/1de7e61ca33891c03bee8d044f26999c.jpg', '<p>Yêu Là Đau - Love Hurts xoay quanh Venika, một nữ doanh nhân, triệu phú trẻ tuổi. Sau đám cưới hoành tráng, Venika nhận được một tấm thiệp chúc mừng với bản sao giấy chứng nhận kết hôn của hôn phu Teerakit với một người phụ nữ bí ẩn. Venika bí mật tìm ra người phụ nữ trong giấy kết hôn. Cô thậm chí còn sốc hơn khi biết rằng chồng mình và người vợ bí ẩn của anh ta đang lên kế hoạch lừa đảo để tiếp quản công việc kinh doanh của mình. Cô phải làm mọi thứ cần thiết để tự cứu mình, với sự giúp đỡ từ Bantao - người đã yêu thầm Venika từ những ngày còn đi học.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 6, 2023, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Jes Jespipat","avatar":""},{"name":"Mai Davika","avatar":""},{"name":"Mew Supasit","avatar":""},{"name":"Lily Pantila","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324254);
