INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-them-lan-nua-2023', 'Yêu Thêm Lần Nữa', 'Individual Circumstances', 'https://phimimg.com/upload/vod/20240308-1/cc271020a1e3ff02d7b69aebb018de7b.jpg', 'https://phimimg.com/upload/vod/20240308-1/94d01135f74209b9169e78080504a087.jpg', '<p>Yêu Thêm Lần Nữa kể về câu chuyện xoay quanh Yeon Woo và Yeon Woo là một đạo diễn đã sản xuất các tác phẩm nổi tiếng, nhưng giai đoạn sau đó, anh ta không ghi được thành tích gì tốt đẹp, điều này cũng khiến sự nghiệp của anh ta gặp phải một nút thắt lớn.Trong một lần tình cờ, Yeon Woo đến gặp một tiểu thuyết gia nổi tiếng trên mạng, hy vọng có thể chuyển thể cuốn tiểu thuyết bán chạy nhất của anh ta, nhưng không ngờ tác giả lại là Woo Jae, người đã mất liên lạc nhiều năm! Những ân oán, ân oán năm xưa khiến cả hai phải chia xa, nay gặp lại, liệu họ có hóa giải êm đẹp hiểu lầm và trở thành cái kết có hậu cho nhau?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jun. Q","avatar":""},{"name":"Han Jung Wan","avatar":""},{"name":"Cha Shi Hyuk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324255);
