INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-sinh-duyen-khoi-thi-thanh-hoan', 'Tam Sinh Duyên Khởi Thị Thanh Hoan', 'The Origin Of Eternity', 'https://phimimg.com/upload/vod/20240308-1/cbd30872a14cea5f5d730d94ccdb1acd.jpg', 'https://phimimg.com/upload/vod/20240308-1/ff475924d01acc9a6a051f8af37d11e4.jpg', '<p>Thanh Hoan vốn là một đoá hoa diên vỹ bên bờ sông Quên, vô tình được thần quân Bạch Trạch điểm hoá, cũng vì vậy mà hai người phải lòng nhau, rơi vào luân hồi. Tam sinh tình kiếp, Bạch Trạch và Thanh Hoan trải qua biết bao lần bi hoan ly hợp, nếm trải đủ yêu hận tình thù, cuối cùng đã thấm đượm chữ tình, có được mối tình tuyệt đẹp và cảm động lòng người.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Trạch","avatar":""},{"name":"Lâm Nghiên","avatar":""},{"name":"Nhu Tào","avatar":""},{"name":"Quân Hào","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324255);
