INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oppa-giao-su-cua-em', 'Oppa! Giáo Sư Của Em', 'Lecturerku, Oppa!', 'https://phimimg.com/upload/vod/20240308-1/022758eb9c498bf1cb5ce884810ee564.jpg', 'https://phimimg.com/upload/vod/20240308-1/45bde22dcd1249bdfc89b8056ed45960.jpg', '<p>Jung-Hyun Hwang là giảng viên Trường Quản lý Du lịch tại một trường đại học địa phương ở thủ đô. Anh ấy là một người Hàn Quốc nói tiếng Mã Lai. Mặc dù đẹp trai và được nhiều sinh viên trong trường ngưỡng mộ, nhưng anh chỉ để mắt đến một sinh viên, một cô gái người Mã Lai tên Sara. Và khi Sara được giao thực hiện một dự án về Hàn Quốc, Hyun nhất quyết giúp đỡ cô để họ có thời gian bên nhau. Ban đầu, Sara phản đối, nhưng dần dần yêu nhau trong một chuyến đi đến trường của họ. Tuy nhiên, mối quan hệ giữa sinh viên và giảng viên không bao giờ suôn sẻ. Cuối cùng, Hyun cải sang đạo Hồi và lấy tên mới là Daniel Abdullah. Bắt đầu một cuộc hành trình mới với Sara yêu quý của mình. Nhưng trước tiên anh phải vượt qua hai điều: ăn chay và cắt bì.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 14, 2023, 'Vietsub', 'HD', 'Malaysia', 0, '[{"name":"Sweet Qismina","avatar":""},{"name":"Han Byul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324255);
