INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-nhan-de-de-cua-ta', 'Giao Nhân Đệ Đệ Của Ta', 'My Merman Brother', 'https://phimimg.com/upload/vod/20240308-1/9287f4dde4e4b3fe11cf3b59c2888883.jpg', 'https://phimimg.com/upload/vod/20240308-1/f7f44cfb60a916f1dc315793944bd141.jpg', '<p>Lâm Vi Tự, nữ Quốc sư của Đại Cầm vung tay tiêu diệt được nước Nam Chiêu, quyền lực khuynh đảo triều đình. Một ngày nọ, nàng bắt gặp người của Đại lý tự đang ngược đãi Giao nhân tù binh của nước Nam Chiêu bèn mủi lòng cứu hắn, không ngờ hắn lại đi theo nàng. Từ đó hai người bắt đầu hành trình ngọt ngào chữa lành vết thương lòng lẫn nhau và cùng bắt tay tìm ra hung thủ thực sự đã giết hại lão Quốc sư, quét sạch gian tế trong triều.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quản Kim Lân","avatar":""},{"name":"Thẩm Hoài","avatar":""},{"name":"Tề Vĩ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324255);
