INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-tro-thanh-thu-linh-giao-phai', 'Cách Trở Thành Thủ Lĩnh Giáo Phái', 'How To Become A Cult Leader', 'https://phimimg.com/upload/vod/20240308-1/e4dd7fb65b629ba6429c5429a9efd20f.jpg', 'https://phimimg.com/upload/vod/20240308-1/8d1ffaaa13b866bdb41faa452a436339.jpg', '<p>Xem thử sổ tay của thủ lĩnh giáo phái để biết cách giành được tình yêu vô điều kiện, lòng trung thành vĩnh viễn và sức mạnh kiểm soát tâm trí, thể xác và linh hồn của mọi người.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Peter Dinklage","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324255);
