INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-chu-dai-nhan-moi-thu-doc', 'Thành Chủ Đại Nhân Mời Thử Độc', 'My Bug, My Castellan', 'https://phimimg.com/upload/vod/20240305-1/e05b96e2210a20028d80f4c637245009.jpg', 'https://phimimg.com/upload/vod/20240305-1/40e40990adc5b2ad108ce948aa73f921.jpg', '<p>Thiếu nữ thần bếp bước vào game để sửa lỗi, nào ngờ thành chủ lại chính là lỗi cần sửa. Vì để xóa lỗi cho hệ thống trở lại bình thường, nàng phải nghĩ ra trăm phương ngàn kế để hạ độc thành chủ, nhưng trong quá trình tương ái tương sát nhau lại nảy sinh tình cảm, nàng phải làm thế nào đây?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Hiên","avatar":""},{"name":"Kim Tử Tuyền","avatar":""},{"name":"Hoàng Gia Hào","avatar":""},{"name":"Triệu Lan Quân","avatar":""},{"name":"Hồ Cách Sướng","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324255);
