INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yen-son-phai-va-bach-hoa-mon', 'Yến Sơn Phái Và Bách Hoa Môn', 'Love Young Forever', 'https://phimimg.com/upload/vod/20240305-1/11c8669e7d3e93e94ce8a4b114df3141.jpg', 'https://phimimg.com/upload/vod/20240305-1/2598a55d6d723fe8c0cae725e3a46d43.jpg', '<p>Có hai trường học chính ở Yan Shan thanh tao - Trường Yan Shan, có 2 nam và Bai Hua, có 2 nữ. Hai trường ngày đêm thân thiết với nhau nhưng vì nội quy, quy định cũ kỹ, chặt chẽ nên không tương tác với nhau. Nhưng không gì có thể ngăn cản được sự khao khát tình yêu của những người trẻ, và một loạt những khúc quanh và những câu chuyện vui vẻ được mở ra.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fang Yilun","avatar":""},{"name":"Liu Lingzi","avatar":""},{"name":"Ma Wenyuan","avatar":""},{"name":"Xiaotong Su","avatar":""},{"name":"冯铭潮","avatar":""},{"name":"Flora Dai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
