INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cangaco-novo', 'Cangaco Novo', 'New Bandits', 'https://phimimg.com/upload/vod/20240305-1/45a17669673f79d8236b0a9ed73f8f95.jpg', 'https://phimimg.com/upload/vod/20240305-1/0354c153c5b42f1ea8d2a88f046b411d.jpg', '<p>Trôi dạt và đang rất cần tiền để lo cho người cha nuôi ốm yếu của mình, Ubaldo, một nhân viên ngân hàng không thể nhớ được thời thơ ấu của mình, nhận được một tài sản thừa kế sẽ thay đổi vận mệnh của anh mãi mãi. Anh ta đến Cratará, ở trung tâm của sa mạc phía tây bắc, nơi anh ta sẽ trở thành thủ lĩnh của một nhóm cướp tàn nhẫn, hoàn thành di sản của cha ruột anh ta - một cangaceiro thần thoại.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2023, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Allan Souza Lima","avatar":""},{"name":"Alice Carvalho","avatar":""},{"name":"Thainá Duarte","avatar":""},{"name":"Ricardo Blat","avatar":""},{"name":"Marcélia Cartaxo","avatar":""},{"name":"Hermila Guedes","avatar":""},{"name":"Enio Cavalcante","avatar":""},{"name":"Adélio Lima","avatar":""},{"name":"Pedro Lamin","avatar":""},{"name":"Nivaldo Nascimento","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
