INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-horror-of-dolores-roach', 'The Horror Of Dolores Roach', 'The Horror Of Dolores Roach', 'https://phimimg.com/upload/vod/20240305-1/ac0e8962202f23347f1bebe570f3ce76.jpg', 'https://phimimg.com/upload/vod/20240305-1/f858064c41369ae776a0712c2eac1c03.jpg', '<p>Sau bản án 16 năm tù oan uổng, Dolores Roach trở lại Washington Heights hiền hòa, nơi cô gặp lại người bạn cũ là thợ đá, Luis, người đã cho cô sống và làm nhân viên mát xa dưới tầng hầm dưới cửa hàng empanada của anh ta. Khi lời hứa về sự ổn định mới tìm thấy của cô nhanh chóng bị đe dọa, “Những bàn tay ma thuật” Dolores bị đẩy đến những cực điểm gây sốc để tồn tại.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Justina Machado","avatar":""},{"name":"Alejandro Hernandez","avatar":""},{"name":"Kita Updike","avatar":""},{"name":"K. Todd Freeman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
