INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('treu-choc', 'Trêu Chọc', 'Provoke', 'https://phimimg.com/upload/vod/20240305-1/97b0094f6e1cac485a4ad7d43c68bd7a.jpg', 'https://phimimg.com/upload/vod/20240305-1/35d02c1da30cc20787ba7f6742d3292a.jpg', '<p>Đầu thế kỷ 20 ở Đường Thành, nữ ca sĩ hàng đầu Tân Tiên Lâm, Khương Anh, dày công sắp đặt gả vào nhà phú thương Đỗ Cảnh Song để hoàn thành kế hoạch trả thù. Đỗ Tầm Vũ, con trai Đỗ Cảnh Song nghi ngờ Khương Anh có ý đồ khác, nhưng trái lại suýt bị lộ tẩy thân phận con trai giả. Mẹ kế và con nuôi sống chung dưới một mái nhà đấu đá kịch liệt, lại dần nhận ra dường như đối phương là cố nhân, như định mệnh an bài, hai người trả thù vốn lẻ loi đơn độc đã trở thành điểm tựa và bảo vệ cho nhau, mà Đỗ Cảnh Song kẻ thù của họ lại đang bí mật quan sát mọi chuyện...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mộc Thần","avatar":""},{"name":"Triệu Dịch Khâm","avatar":""},{"name":"Vương Nhã","avatar":""},{"name":"Lân Y Linh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324255);
