INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('2-moons-the-ambassador', '2 Moons The Ambassador', '2 Moons The Ambassador', 'https://phimimg.com/upload/vod/20240305-1/c109046806f1810bec7a60b72bcef833.jpg', 'https://phimimg.com/upload/vod/20240305-1/f64ba68faafd1e83c48f664671176e05.jpg', '<p><em>2 Moons: The Ambassador (VietSub - Thuyết Minh)</em>&nbsp;Lomnaw là Mặt Trăngcủa khoa Nông nghiệp và cũng là em trai của Phana nên được nhiều người chú ý, nhưng cậu lại chỉ đứng hạng cuối trong bảng xếp hạng Mặt Trăng của trường. Thực ra trong khoa Nông nghiệp có một Tarntat huyền thoại đẹp trai không thua kém gì Phana, nhưng cậu ấy không muốn tham gia cuộc thi. Vì vậy mà khiến mọi người trong khoa đều tiếc nuối. Khi các khoa Nông nghiệp của các trường đại học thi đấu chọn ra người đại diện, Lomnaw phải miễn cưỡng tham gia cuộc thi dưới sự giám sát của Tarntat, và trong quá trình đó quan hệ giữa họ dần dần trở nên thân thiết hơn. Tuy nhiên sau sự xuất hiện của Phanon, người bạn tốt của Lomnaw thì mối quan hệ của cả hai lại gặp trục trặc. Vì Phanon yêu thầm Lomnaw, nên cậu ấy quyết định lấy lại những gì thuộc về mình, đồng thời cũng muốn báo thù Tarntat đã cướp mất nửa kia của người anh em sinh đôi Phara của mình. Sau đó Phanon quyết tâm giành lấy Lomnaw. Ngoài ra, phần này còn có cả những câu chuyện về 3 cặp đôi: Phana-Wayo, Ming-Kit, Forth-Beam. Tình cảm giữa Lomnaw-Tarntat và ba cặp còn lại sẽ phát triển thế nào? Các mối quan hệ phức tạp cuối cùng sẽ làm nên tình yêu chân thành nhất.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Danny Bandit Disatharit","avatar":""},{"name":"Mark Vachara Promma","avatar":""},{"name":"Hue Chasit Karapim","avatar":""},{"name":"Park Anantadej Sodsee","avatar":""},{"name":"Eiffel Chris Chen","avatar":""},{"name":"Toey Nathapong Sing-on","avatar":""},{"name":"Prame Pumipat Paiboon","avatar":""},{"name":"Payu Khunnaphat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324255);
