INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('2-moons-the-ambassador', '2 Moons The Ambassador', '2 Moons The Ambassador', '2 moons the ambassador 2 moons the ambassador danny bandit disatharit mark vachara promma hue chasit karapim park anantadej sodsee eiffel chris chen toey nathapong sing-on prame pumipat paiboon payu khunnaphat ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-cua-dinh-menh', 'Công Chúa Của Định Mệnh', 'The Princess Of Destiny', 'https://phimimg.com/upload/vod/20240305-1/bbce2f42a75af687fb4a8954b901198d.jpg', 'https://phimimg.com/upload/vod/20240305-1/a3986ba51847b80bba4aa6ddd6b2c78f.jpg', '<p>Jiang Muchen, người thừa kế của Tập đoàn Jiang, buộc phải kết hôn với Xia Yu, cháu gái của đồng đội của ông nội anh ta. Sau khi nhìn thấy Xia Yu, một cô thôn nữ ở làng chài, Jiang Muchen không thể tin rằng người này thực sự là đối tượng kết hôn do ông nội sắp đặt. Điều khiến anh ta càng không thể chấp nhận được là ông Jiang đã đưa ra một mệnh lệnh chết người rằng anh ta phải đưa Xia Yu đến bữa tiệc tối. Để trả thù cho ông nội, Jiang Muchen quyết định để Xia Yu xuất hiện trong bữa tiệc với tư cách là một cô gái làng chơi. Thật bất ngờ, Xia Yu đã ăn mặc đẹp đến tham dự đêm đó, khiến khán giả kinh ngạc và Jiang Muchen chết lặng. Hóa ra Jiang đã đạt đến mức này từ lâu, và sắp xếp cho Jiang Anchen, con trai thứ hai của nhà họ Jiang, mang theo Xia Yu để thực hiện một cuộc cải tổ lớn. Anh cả Jiang thậm chí còn tuyên bố việc Xia Yu đính hôn với Jiang Muchen ngay tại chỗ...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Văn Như","avatar":""},{"name":"Trần Duệ Phong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
