INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mashle-ma-thuat-va-co-bap', 'Mashle: Ma Thuật Và Cơ Bắp', 'Mashle: Magic And Muscles', 'https://phimimg.com/upload/vod/20240331-1/8e5ba089d2868d6a4248ff41f7ca451b.jpg', 'https://phimimg.com/upload/vod/20240331-1/25acd3c95c900c79494c0717e9b16587.jpg', '<p>Đây là một thế giới của phép thuật, nơi phép thuật được sử dụng cho mọi thứ. Nhưng sâu trong khu rừng tồn tại một chàng trai dành thời gian của mình để tập luyện. Anh chàng không thể sử dụng phép thuật, nhưng anh ấy tận hưởng một cuộc sống yên bình với cha mình. Nhưng một ngày nọ, cuộc sống của anh ấy bị đe dọa! Liệu cơ thể vạm vỡ của anh ấy có bảo vệ anh ấy khỏi những kẻ sử dụng ma thuật? Cơ bắp được rèn luyện mạnh mẽ sẽ nghiền nát ma thuật khi ảo tưởng ma thuật bất thường này bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Chiaki Kobayashi","avatar":""},{"name":"Reiji Kawashima","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Hiroaki Hirata","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324255);
