INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-hop-lop-nho-doi-phan-2', 'Buổi Họp Lớp Nhớ Đời (Phần 2)', 'The Afterparty (Season 2)', 'https://phimimg.com/upload/vod/20240305-1/7b6e188eb703ba396b3ab8e2d5342227.jpg', 'https://phimimg.com/upload/vod/20240305-1/1fa6f025c256cbff841a95dff5b172a0.jpg', '<p>Trong phần hai, một đám cưới bị hủy hoại khi chú rể bị sát hại và mọi khách mời đều là nghi phạm. Thám tử Danner trở lại để giúp Aniq và Zoë giải quyết vấn đề bằng cách thẩm vấn các thành viên trong gia đình, những người yêu nhau và đối tác kinh doanh, đồng thời nghe mỗi kẻ tình nghi kể lại về ngày cuối tuần, mỗi người có quan điểm và phong cách hình ảnh độc đáo của riêng họ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tiffany Haddish","avatar":""},{"name":"Sam Richardson","avatar":""},{"name":"Zoë Chao","avatar":""},{"name":"John Cho","avatar":""},{"name":"Paul Walter Hauser","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Anna Konkle","avatar":""},{"name":"Poppy Liu","avatar":""},{"name":"Elizabeth Perkins","avatar":""},{"name":"Jack Whitehall","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324255);
