INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khongboloc', '#KhôngBộLọc', '#NoFilter', 'https://phimimg.com/upload/vod/20240305-1/ec93b05b0be9976644f164cfbc3211fb.jpg', 'https://phimimg.com/upload/vod/20240305-1/e814119d6516020dcbd533cd5df112a9.jpg', '<p>Chán học, Marcely nghỉ ngang đại học để theo đuổi mục tiêu mới trong đời: trở thành người có ảnh hưởng. Nhưng cuộc sống trên mạng không dễ như cô tưởng…</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 14, 2023, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Ademara","avatar":""},{"name":"Flávia Reis","avatar":""},{"name":"Orã Figueiredo","avatar":""},{"name":"Mel Maia","avatar":""},{"name":"Thamyris Borsan","avatar":""},{"name":"Pedro Ottoni","avatar":""},{"name":"Maicon Rodrigues","avatar":""},{"name":"Lu Périssé","avatar":""},{"name":"Carol Garcia","avatar":""},{"name":"Leandro Santanna","avatar":""},{"name":"Sandra de Sá","avatar":""},{"name":"Maíra Azevedo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324255);
