INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-do-duyen', 'Phù Đồ Duyên', 'Floating On The Edge', 'https://phimimg.com/upload/vod/20240305-1/c5696fb701abb218bde14c270369b612.jpg', 'https://phimimg.com/upload/vod/20240305-1/d71b44668e36289a02071872ffd8d4e2.jpg', '<p>Bộ Âm Lâu (Trần Ngọc Kỳ) là một nhân tài vừa lọt qua vòng tuyển tú lại không may nhận được chỉ thị sẽ bị tuẫn táng theo Tiên đế. Thế nhưng trong cái rủi lại có cái may, nàng được tân hoàng nhìn trúng và được Tiêu Đạc (Vương Hạc Đệ) cứu mạng sau đó an bài cho sống trong Tiêu phủ. Ngày qua ngày Âm Lâu và Tiêu Đạc chung sống cùng nhau đã dần nảy sinh tình cảm, nhưng cả hai cũng chỉ đành chôn chặt trong lòng vì trở ngại thân phận. Đối mặt với trùng trùng gian truân trắc trở, sự chèn ép của tân hoàng và bí mật đằng sau thân phận của Tiêu Đạt, liệu vận mệnh của bộ đôi sẽ đi về đâu và họ sẽ có một cái kết có hậu?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạc Đệ","avatar":""},{"name":"Trần Ngọc Kỳ","avatar":""},{"name":"Hà Nhuận Đông","avatar":""},{"name":"Tăng Lê","avatar":""},{"name":"Vương Lịch Hâm","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324255);
