INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-mitarai-trong-bien-lua', 'Nhà Mitarai Trong Biển Lửa', 'Burn The House Down', 'https://phimimg.com/upload/vod/20240305-1/82b911d41c9a08565d6ac37938d395f1.jpg', 'https://phimimg.com/upload/vod/20240305-1/eb56909bd61108428bb4694f5d675c67.jpg', '<p>Sau khi mẹ cô gánh chịu tội lỗi về vụ hỏa hoạn thảm khốc 13 năm trước, Anzu lên kế hoạch trả thù bằng cách làm quản gia cho người mẹ kế lạnh lùng của mình dưới tên giả.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nagano Mei","avatar":""},{"name":"Kudo Asuka","avatar":""},{"name":"Nakagawa Taishi","avatar":""},{"name":"Tsunematsu Yuri","avatar":""},{"name":"Kitano Kii","avatar":""},{"name":"Hamada Mari","avatar":""},{"name":"Konishi Sakurako","avatar":""},{"name":"Kichise Michiko","avatar":""},{"name":"Oikawa Mitsuhiro","avatar":""},{"name":"Suzuki Kyoka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324255);
