INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-mitarai-trong-bien-lua', 'Nhà Mitarai Trong Biển Lửa', 'Burn The House Down', 'nhà mitarai trong biển lửa burn the house down nagano mei kudo asuka nakagawa taishi tsunematsu yuri kitano kii hamada mari konishi sakurako kichise michiko oikawa mitsuhiro suzuki kyoka ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-phoi-to-tam-duong', 'Tuyệt Phối Tô Tâm Đường', 'Taste Of Love', 'https://phimimg.com/upload/vod/20240305-1/1fb47772918322dff295e6b38997b507.jpg', 'https://phimimg.com/upload/vod/20240305-1/4a9efad29ff817135c68121c875990dd.jpg', '<p>Tuyệt Phối Tô Tâm Đường sắp lên sóng tại iQIYI. Phim được chuyển thể từ bộ truyện tranh \Tôi Bị Tổng Tài Anti Rồi\ và kể về câu chuyện của ngôi sao nhạc pop đình đám Đường Tô bị hiểu nhầm và bị đưa vào tình trạng tạm ngưng hoạt động nghệ thuật, sau đó tăng cân đến 50 kg và trở thành người giúp việc trực tiếp của Hoàng Phủ Quyết - chủ tịch của một tập đoàn giải trí. Thật không ngờ, Hoàng Phủ Quyết, người bị mù mặt lại chính là fan hâm mộ số một của Tang Tố.\n\nVì vậy, hai người đã bắt đầu một câu chuyện tình yêu vô cùng hài hước và nghịch ngợm khi Hoàng Phủ Quyết muốn \anti\ cô nàng ngôi sao tăng cân và \trục xuất\ cô khỏi công ty. Những tình huống dở khóc dở cười đã xảy ra khi Đường Tô cố gắng lấy lại tên tuổi của mình trong khi đối đầu với Hoàng Phủ Quyết.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Nhất Tấn","avatar":""},{"name":"Đặng Khải","avatar":""},{"name":"Lâm Yên Nhu","avatar":""},{"name":"Trần Tân Hải","avatar":""},{"name":"Tăng Hữu Chân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324255);
