INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shahmaran', 'Shahmaran', 'Shahmaran', 'https://phimimg.com/upload/vod/20240305-1/d193d3d3f11f60df52783947ff86c16a.jpg', 'https://phimimg.com/upload/vod/20240305-1/21297372dba05ecfb99b0c09ea500bc9.jpg', '<p>Đến gặp Adana để nghe giảng, Şahsu có cơ hội hoàn hảo để gặp người ông xa cách từ lâu. Nhưng chẳng mấy chốc, cô vướng vào một truyền thuyết.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2023, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Serenay Sarıkaya","avatar":""},{"name":"Burak Deniz","avatar":""},{"name":"Mustafa Uğurlu","avatar":""},{"name":"Mahir Günşiray","avatar":""},{"name":"Ebru Özkan","avatar":""},{"name":"Mert Ramazan Demir","avatar":""},{"name":"Hakan Karahan","avatar":""},{"name":"Elif Nur Kerkük","avatar":""},{"name":"Mehmet Bilge Aslan","avatar":""},{"name":"Berfu Halisdemir","avatar":""},{"name":"Nilay Erdönmez","avatar":""},{"name":"Nil Sude Albayrak","avatar":""},{"name":"Ayşe Lebriz Berkem","avatar":""},{"name":"Ece Ertez","avatar":""},{"name":"Beran Soys","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
