INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('shahmaran', 'Shahmaran', 'Shahmaran', 'shahmaran shahmaran serenay sarıkaya burak deniz mustafa uğurlu mahir günşiray ebru özkan mert ramazan demir hakan karahan elif nur kerkük mehmet bilge aslan berfu halisdemir nilay erdönmez nil sude albayrak ayşe lebriz berkem ece ertez beran soys ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-mua-dang-dang', 'Bốn Mùa Đằng Đẵng', 'The Long Season', 'https://phimimg.com/upload/vod/20240305-1/abe14ce57e06c62cbee66644f10746da.jpg', 'https://phimimg.com/upload/vod/20240305-1/cb4ff609213cb4657b1ea3293f0ed459.jpg', '<p>Trong khu rừng bạch dương của một thị trấn nhỏ, vào thời điểm này, Wang Xiang, một tài xế taxi, không bao giờ có thể mong đợi gặp được người mà anh ta muốn gặp nhất hoặc sợ hãi nhất trong cuộc đời mình. Anh ta là kẻ thù hay bạn bè? Vì anh ấy đã gặp anh ấy, anh ấy phải đóng cửa. Không chỉ cho anh ấy, mà còn cho con trai anh ấy. Trong khu rừng bạch dương của một thị trấn nhỏ, vào thời điểm đó, Wang Xiang, một người lái tàu, tràn đầy sức sống và sức sống vì anh ta đang điều khiển một con quái vật bằng thép với hai mươi toa tàu. Nhưng một mặt, anh thất bại trong việc điều hành một gia đình nhỏ gồm ba người với đầy những vấn đề tầm thường. Mặt khác, anh ta bị mắc kẹt trong một nhà máy đang lụi tàn với một cuộc khủng hoảng rình rập từ mọi ngóc ngách. Một gói các bộ phận cơ thể không xác định được thả trong rừng bạch dương, giống như một viên đá rơi xuống mặt nước yên tĩnh. Trong hai mươi năm qua, Wang Xiang không bao giờ có thể ngừng nghĩ về gói đó, ngay cả khi những chiếc lá chuyển sang màu vàng vào mùa thu. Một người cha đã mất, một người yêu đã chết và những người bạn cũ gặp lại nhau bị mắc kẹt ở ba thời đại khác nhau vì một bí ẩn chưa được giải quyết. Tất cả những gì họ muốn là tìm ra một sự thật xuyên suốt quá khứ, hiện tại và tương lai. Khi bí ẩn được hé lộ, chỉ còn lại sự bi tráng của số phận và thời đại trong trường đoạn dài với thời gian và không gian đan xen vào nhau.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phạm Vĩ Tần","avatar":""},{"name":"Hạo Trần","avatar":""},{"name":"Minh Hạo","avatar":""},{"name":"Lý Canh Hy","avatar":""},{"name":"Lưu Dịch Thiết","avatar":""},{"name":"Tưởng Kì Minh","avatar":""},{"name":"Lưu Lâm Sử","avatar":""},{"name":"Bình Nguyên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
