INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-tem-jai-the-series', 'Tin Tem Jai The Series', 'Tin Tem Jai The Series', 'https://phimimg.com/upload/vod/20240305-1/8f03e849e80c9a0b883a67b99ee2a553.jpg', 'https://phimimg.com/upload/vod/20240305-1/22df358215342f65a22b1174e7faa4e3.jpg', '<p>Câu chuyện về Tin và những người anh hàng xóm, băng nhóm thịt lợn giòn của thành phố. Tin sống với Park. Là con trai của dì Phawinee, chủ một tiệm bánh trong làng, Tin đã thầm thích Park từ nhỏ. Mục tiêu duy nhất của cuộc đời là kết hôn với Park. Nhưng trở ngại là tôi thường xuyên bị Park mắng với câu Khoan đã, tôi sẽ đá em. Phi vụ trói trái tim anh Park bắt đầu và không kết thúc dễ dàng. Tin đã cống hiến cả cơ thể và tâm trí của mình để biến ước mơ của mình thành hiện thực. Trong khi đó, anh em nhà bên thì ngày nào ở nhà cũng có chuyện để quậy!</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Run Kantheephop Sirorattanaphanit","avatar":""},{"name":"Tiger Aekapol Saeheng","avatar":""},{"name":"Longshi Lee","avatar":""},{"name":"Tong Surawit Ruangyod","avatar":""},{"name":"Yoshi Rinrada Thurapan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324255);
