INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-va-loi-noi-doi', 'Cô Ấy Và Lời Nói Dối', 'The Lady And The Lies', 'https://phimimg.com/upload/vod/20240305-1/f14086418d8760bd17cd919c2f61f1b2.jpg', 'https://phimimg.com/upload/vod/20240305-1/fa7d5803d52c14ee813b71b8e4c980a1.jpg', '<p>Zheng Xue Er, một phụ nữ mạnh mẽ với sự nghiệp thành công, không có kế hoạch kết hôn. Tuy nhiên, mẹ cô bị bệnh nặng, và để trấn an bà rằng bà sẽ tìm được một người chồng tử tế, Xue Er quyết định hạ thấp tiêu chuẩn chọn bạn đời và tìm một người lương thiện ổn định để kết hôn và sinh con càng sớm càng tốt. Dưới sự giới thiệu của người bạn thân Mi Li Li, cô gặp Tống Hạo Thiên và kết hôn với anh trong chớp nhoáng.Chẳng mấy chốc, mẹ cô qua đời và Zheng Xue Er nỗ lực để đạt được hạnh phúc trong gia đình nhỏ mới của mình. Sau khi kết hôn, Zheng Xue Er bị vô sinh vì lý do thể chất và mẹ chồng cô vô cùng không hài lòng về điều này. Nhưng kể cả khi cô mang thai thành công nhờ công nghệ ống nghiệm, thái độ của mẹ chồng đối với cô vẫn không hề cải thiện. Vẫn chưa đủ, phụ nữ sớm phát hiện ra rằng Hao Tian, người thích công khai yêu vợ, đã lừa dối cô với bạn của cô và cả hai lên kế hoạch chiếm đoạt tài sản của cô.Ban đầu, chỉ muốn bí mật điều tra chồng ngoại tình, Zheng Xue Er, khi biết rằng cái chết của mẹ cô cũng liên quan đến chồng cô, bị ám ảnh bởi sự cần thiết phải trả thù cho bà và trả giá cho tất cả những điều độc ác, hai người này đã làm đến cô, cô bắt đầu kế hoạch trả thù của mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feng Xi Yao","avatar":""},{"name":"Hu Wei","avatar":""},{"name":"Yu Yi Fu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
