INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-gia-mao', 'Đứa Trẻ Giả Mạo', 'The Changeling', 'https://phimimg.com/upload/vod/20230914-1/d3c422e8a062e804e0b48b7a434fb8ad.jpg', 'https://phimimg.com/upload/vod/20230914-1/90bda6dac8ad9a31bc21d454966549b5.jpg', '<p>Chuyện tình của Apollo và Emma là một câu chuyện cổ tích—cho đến khi Emma biến mất một cách bí ẩn. Bereft, Apollo thấy mình đang trong một cuộc phiêu lưu bất chấp cái chết xuyên qua Thành phố New York mà anh không hề biết là có tồn tại.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lakeith Stanfield","avatar":""},{"name":"Clark Backo","avatar":""},{"name":"Adina Porter","avatar":""},{"name":"Jared Abrahamson","avatar":""},{"name":"Samuel T. Herring","avatar":""},{"name":"Alexis Louder","avatar":""},{"name":"Victor LaValle","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324255);
