INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bollywood-lang-man', 'Bollywood Lãng Mạn', 'The Romantics', 'https://phimimg.com/upload/vod/20240305-1/822250fd29f0b6692f76e92f633626e6.jpg', 'https://phimimg.com/upload/vod/20240305-1/4fb47dab0efa46c57fa7fc88f31deb74.jpg', '<p>Có các cảnh quay tư liệu cùng các cuộc phỏng vấn sâu với người nổi tiếng, loạt phim tài liệu này tôn vinh cuộc đời và di sản của tượng đài làm phim Bollywood: Yash Chopra.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324255);
