INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-dau-tien-trong-cuoc-doi', 'Lần Đầu Tiên Trong Cuộc Đời', 'For The First Time In My Life', 'https://phimimg.com/upload/vod/20240305-1/41e60efbdb10a50cd69f82e2ccd82402.jpg', 'https://phimimg.com/upload/vod/20240305-1/9443cdd6f6a8c04c4e1b44d0a77e4262.jpg', '<p>Câu chuyện xuyên suốt ba khoảng thời gian và không gian, trong cùng một bệnh viện phụ sản, câu chuyện xoay quanh ba cặp vợ chồng về chuyện sinh nở, hôn nhân, sự nghiệp và gia đình. Năm 1993, Lu Minglei và Dai Sijin tìm kiếm một giải pháp dưới áp lực của cải cách hệ thống và thị trường. Năm 2008, Cheng Qianjin và Chen Lanqing, mặc dù họ là cha mẹ, nhưng trái tim họ không lớn lên. Năm 2022, Xia Zhixiong và Lu Yuan dần dần mất kiểm soát với cuộc sống của mình, và nhận ra rằng chỉ có hòa giải với chính mình, họ mới có thể đến được bờ bên kia.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Tử Văn","avatar":""},{"name":"Đường Nghệ Hân","avatar":""},{"name":"Myolie Wu","avatar":""},{"name":"Allen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324255);
