INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('erin-carter-la-ai', 'Erin Carter Là Ai?', 'Who Is Erin Carter?', 'https://phimimg.com/upload/vod/20240305-1/6f91f33e2172ce91b64d69c0990a258f.jpg', 'https://phimimg.com/upload/vod/20240305-1/90493407800ffd88007907e7fb2937a7.jpg', '<p>Cuộc đời bình lặng của một phụ nữ Anh ở Barcelona tuột khỏi tầm kiểm soát khi một vụ cướp có vũ trang ở siêu thị vạch trần bí mật và cả quá khứ bạo lực của cô.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Evin Ahmad","avatar":""},{"name":"Sean Teale","avatar":""},{"name":"Douglas Henshall","avatar":""},{"name":"Susannah Fielding","avatar":""},{"name":"Charlotte Vega","avatar":""},{"name":"Indica Watson","avatar":""},{"name":"Pep Ambròs","avatar":""},{"name":"Jake Fairbrother","avatar":""},{"name":"Ana Ularu","avatar":""},{"name":"Núria Deulofeu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324255);
