INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-cong-chua-bat-dac-di', 'Trưởng Công Chúa Bất Đắc Dĩ', 'Revenge Of Royal Princess', 'https://phimimg.com/upload/vod/20240305-1/f5fb0c0d6ae1a925f0a537c1569dd914.jpg', 'https://phimimg.com/upload/vod/20240305-1/0235f2ad7d73405d992dc99b0353525b.jpg', '<p>Để bồi dưỡng tay sai triều đình cho Hoàng đế đệ đệ, trưởng công chúa Lý Nhạn Sơ đã tới pháp trường cứu Hàn Thư sau đó đào tạo người này. Khi bệnh của Lý Nhạn Sơ vô phương cứa chữa, cô đã sắp xếp cái chết của mình để Hàn Thư một lòng trung thành phò tá Lý Hiệt. Ba năm sau Lý Nhạn Sơ sống lại trong cơ thể Tạ Vu Quy, phát hiện trước kia mình bị bệnh nặng là do có kẻ đầu độc, vậy nên đã bắt đầu điều tra nhưng lại dây dưa với Hàn Thư nay đã thay đổi tính tình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Nhã Kỳ","avatar":""},{"name":"Trương Tập Tuấn","avatar":""},{"name":"Tào Quân Hào","avatar":""},{"name":"Lưu Yên Kỳ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324255);
