INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-bat-ngo-cua-rieng-anh', 'Em Là Bất Ngờ Của Riêng Anh', 'You Are My Exclusive Surprise', 'https://phimimg.com/upload/vod/20240305-1/1a2ec82cb21da776ff34ae309edc0a51.jpg', 'https://phimimg.com/upload/vod/20240305-1/b9a4b5b31f022fc2b68bbe14752ee28f.jpg', '<p>Sau chuyến công tác trở về, Su Su phát hiện mình bị bạn trai và đồng nghiệp phản bội. Su Su tình cờ gặp Ji Ning Rui và nhờ sự giúp đỡ của Ji, cô đã giải quyết được nhiều khủng hoảng.Sau khi trải qua đủ mọi cung bậc cảm xúc, Su Su dần yêu Ji Ning Rui một cách sâu sắc. Tình cờ, Su Su phát hiện ra bí mật của Ji Ning Rui.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiao Na","avatar":""},{"name":"Bai Hao Yan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
