INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-yeu-ma-thoi', 'Là Yêu Mà Thôi', 'Nothing But You', 'https://phimimg.com/upload/vod/20240305-1/df1bb3dbcf99bd34e1cc7d5f958c3eb4.jpg', 'https://phimimg.com/upload/vod/20240305-1/51c64db03cfe15524b449ba32f8fd1a8.jpg', '<p>Nhân viên xuất sắc chốn công sở rơi vào giai đoạn khó khăn Lương Hữu An và vận động viên quen ngồi ghế dự bị Tống Tam Xuyên tình cờ gia nhập câu lạc bộ quần vợt Thảo Đài. Hai người họ một là quản lý câu lạc bộ chuyển nghề giữa chừng, một là vận động viên cầu lông chuyển sang quần vợt, nay cùng các đồng đội khắc phục khó khăn, cùng phấn đấu, cố gắng xây dựng một câu lạc bộ chuyên nghiệp và có tiếng tăm. Trong quá trình này, Lương Hữu An và Tống Tam Xuyên dần nảy sinh tình cảm, cũng đối mặt với xung đột từ quan điểm và trải nghiệm. Câu lạc bộ không ngừng phát triển, họ cũng ứng phó với thử thách hết lần này đến lần khác và vượt lên bản thân, tin tưởng lẫn nhau, cuối cùng phát triển cả sự nghiệp và có một tình yêu đẹp đẽ.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 10, 2023, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Leo Wu","avatar":""},{"name":"Zhou Yutong","avatar":""},{"name":"Jiang Peiyao","avatar":""},{"name":"Zhu Yongteng","avatar":""},{"name":"Zhang Tao","avatar":""},{"name":"Xia Haoran","avatar":""},{"name":"Ma Fanding","avatar":""},{"name":"Li Qing","avatar":""},{"name":"Ma Boquan","avatar":""},{"name":"Mingchen Gao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
