INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('remember-me-tinh-yeu-duoc-viet-bang-tinh-yeu', 'Remember Me: Tình Yêu Được Viết Bằng Tình Yêu', 'Remember Me', 'https://phimimg.com/upload/vod/20240305-1/598aed6d6555dbbc0183526a8646eaaf.jpg', 'https://phimimg.com/upload/vod/20240305-1/943a8bb60100efa51b2ae4f3bd29fdbc.jpg', '<p>Là một câu chuyện khiến mọi người phải suy nghĩ về mối quan hệ thân thiết mà hay liên lạc thông qua thư từ, MSN, BB và LINE. Điều này sẽ giúp đưa mối quan hệ của chúng ta gần gũi hơn?</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Title Teshin Anusananan","avatar":""},{"name":"Tanatorn Saenangkanikorn","avatar":""},{"name":"Mean Phiravich Attachitsataporn","avatar":""},{"name":"Man Supakrit Charoonmatha","avatar":""},{"name":"Ja Phachara Suansri","avatar":""},{"name":"First Chalongrat Novsamrong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
