INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-thanh-tieu-ngo-tac-phan-2', 'Long Thành Tiểu Ngỗ Tác (Phần 2)', 'The Coroner From Longcheng (Season 2)', 'https://phimimg.com/upload/vod/20240305-1/f7d6b481bd7d03eb7d5e4ece104ddb04.jpg', 'https://phimimg.com/upload/vod/20240305-1/5afb466aa57a8edc9b259302fcdc269c.jpg', '<p>Ye Fan, giám đốc của Cục Luật cấm ùn tắc giao thông Sanju, và He Lan, nhân viên bán hàng nhỏ bị sa thải, gặp lại và yêu nhau và cùng nhau giải quyết vụ án. He Lan đã tìm ra bước đột phá trong vụ án thông qua kỹ thuật khám nghiệm tử thi siêu phàm, và Ye Fan cũng tìm ra chân tướng của vụ án với sự giúp đỡ của He Lan, và cuối cùng đã đưa thủ phạm thực sự ra trước công lý.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lộ Hân","avatar":""},{"name":"Triệu Viên Hữu","avatar":""},{"name":"Tiên Gia Thần","avatar":""},{"name":"Hà Tư Cẩn","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324255);
