INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoa-hoc-ve-tinh-yeu', 'Khoa Học Về Tình Yêu', 'The Science Of Falling In Love', 'https://phimimg.com/upload/vod/20240305-1/823c9506cd471f63c368d39913505a37.jpg', 'https://phimimg.com/upload/vod/20240305-1/2df12c9eb1e5e59b15db0f1bf18b7449.jpg', '<p>Tại Đại học Khoa học và Công nghệ Đông Nam, một trường kỹ thuật nổi tiếng trong nước, tỷ lệ nam nữ là 7:1 , vậy mà sinh viên ngành sinh vật Tô Trinh Trinh chưa bao giờ có thể thoát ế. Cho đến một ngày, một loạt cuộc gặp gỡ kỳ lạ, lãng mạn và kỳ diệu giữa Tô Trinh Trinh và \thần nghiên cứu khoa học\ Tiêu Vũ Hà đã diễn ra. Do bốc đồng, Trinh Trinh đã đến gặp Vũ Hà và ttỏ tình: \Em thích anh\. Thật bất ngờ, cô được đưa vào phòng thí nghiệm não bộ và trí thông minh, để thử nghiệm, bằng cách sử dụng các phương pháp khoa học như khoa học não bộ, y học thần kinh và tâm lý học để xác minh \tình cảm\ của cô dành cho anh. Tuy nhiên, trong một thí nghiệm tình yêu được cho là ngọt ngào, Trinh Trinh phát hiện ra rằng Vũ Hà đầy \ác ý\...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Giai Di","avatar":""},{"name":"Lưu Dịch Sướng","avatar":""},{"name":"Trần Hạo Lam","avatar":""},{"name":"Wu Fei","avatar":""}]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324255);
