INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('class', 'Class', 'Class', 'https://phimimg.com/upload/vod/20240305-1/c8a27f08a60cbd52c9944e971bf231e4.jpg', 'https://phimimg.com/upload/vod/20240305-1/7468957bf47a65f710e3a86a1a1f57bd.jpg', '<p>Ba học sinh ở một khu phố nghèo theo học ngôi trường cấp ba dành riêng cho giới thượng lưu Delhi. Tại đó, những bí mật đen tối và tin đồn rốt cuộc đã dẫn đến án mạng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Gurfateh Pirzada","avatar":""},{"name":"Piyush Khati","avatar":""},{"name":"Anjali Sivaraman","avatar":""},{"name":"Madhyama Segal","avatar":""},{"name":"Cwaayal Singh","avatar":""},{"name":"Zeyn Shaw","avatar":""},{"name":"Ayesha Kanga","avatar":""},{"name":"Naina Bhan","avatar":""},{"name":"Moses Koul","avatar":""},{"name":"Chayan Chopra","avatar":""},{"name":"Chintan Rachchh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
