INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-vu-cong', 'Anh Em Vũ Công', 'Dance Brothers', 'https://phimimg.com/upload/vod/20240305-1/dae03beee94e1134f74d6cfed44cdd5e.jpg', 'https://phimimg.com/upload/vod/20240305-1/2ac54f10b180b2c530de9bbfad18e9fc.jpg', '<p>Muốn thành công với tư cách vũ công, hai anh em nọ mở câu lạc bộ riêng. Nhưng thôi thúc nghệ thuật sớm xung đột với công việc kinh doanh, đe dọa mối quan hệ giữa họ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 14, 2023, 'Vietsub', 'HD', 'Phần Lan', 0, '[{"name":"Roderick Kabanga","avatar":""},{"name":"Samuel Kujala","avatar":""},{"name":"Jeanine Muyima","avatar":""},{"name":"Cristal Snow","avatar":""},{"name":"Lauri Lohi","avatar":""},{"name":"Fanni Noroila","avatar":""},{"name":"Meri Nenonen","avatar":""},{"name":"Eeva Eloranta","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
