INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-chieu-anh-sang-vi-em', 'Ngược Chiều Ánh Sáng Vì Em', 'Love Of Replica', 'https://phimimg.com/upload/vod/20240305-1/ab4aeee94d4f21fd86d202059e8cde45.jpg', 'https://phimimg.com/upload/vod/20240305-1/b485c8d4bbdc58cf4b12ae22562395d8.jpg', '<p>Đại tiểu thư Hứa Hy Hề tỉnh lại sau hôn mê và bị mất trí nhớ, trúng tiếng sét ái tình với vệ sĩ Lộ Cận Ngôn, nhưng qua lời người bạn từ nhỏ Đinh Bắc Phàm, cô biết được mình không phải Hứa Hy Hề thật sự mà là An Duyệt có ngoại hình giống hệt. Trong quá trình điều tra sự thật, An Duyệt cũng phát hiện thêm nhiều bí mật động trời, mà chàng vệ sĩ Lộ Cận Ngôn cũng âm thầm mưu kế, hai người giằng co trong hoài nghi và mập mờ, tìm kiếm sự thật nhưng không quên thổ lộ ấm áp, đối mặt với vô vàn nguy cơ vẫn kiên quyết bảo vệ nhau, nương tựa vào nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tsao Yu-ning","avatar":""},{"name":"Yilia Yu","avatar":""},{"name":"Wu Haoze","avatar":""},{"name":"Tu Bing","avatar":""},{"name":"Zhang Guansen","avatar":""},{"name":"Wang Shu Yun","avatar":""},{"name":"Duo Duo Xu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
