INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-tan-the', 'Chuyến Tàu Tận Thế', 'Pending Train', 'https://phimimg.com/upload/vod/20240305-1/2e4f3b1d8816a5b22e686ab23efd5abe.jpg', 'https://phimimg.com/upload/vod/20240305-1/f12515edb30a48fb081e23da341e26be.jpg', '<p>Vào một buổi sáng bình thường ở Tokyo, các hành khách bỗng phải chiến đấu để sinh tồn khi toa tàu của họ xuyên không đến tương lai tận thế.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuki Yamada","avatar":""},{"name":"Eiji Akaso","avatar":""},{"name":"Moka Kamishiraishi","avatar":""},{"name":"Kai Inowaki","avatar":""},{"name":"Kotone Furukawa","avatar":""},{"name":"Joichiro Fujiwara","avatar":""},{"name":"Wataru Hyuga","avatar":""},{"name":"Rin Kataoka","avatar":""},{"name":"Tetta Sugimoto","avatar":""},{"name":"Yasuko Matsuyuki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324255);
