INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('25-gio-yeu', '25 Giờ Yêu', 'Sweet Games', 'https://phimimg.com/upload/vod/20240305-1/3d52718c998492fce685fa395fa0f88f.jpg', 'https://phimimg.com/upload/vod/20240305-1/433991493ed482792be42966f4feff78.jpg', '<p>Cô là An Nhiên một nữ doanh nhân thành đạt, có năng lực và trách nhiệm với công việc. Anh là Ngôn Việt người đồng hành cùng cô, một diễn viên lồng tiếng nổi tiếng cùng giọng nói nhẹ nhàng, ấm áp phía sau màn hình. Hãy cùng chờ đón bộ phim nhé!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Hoằng San","avatar":""},{"name":"Đổng Tư Thành","avatar":""},{"name":"Lãnh Kỷ Nguyên","avatar":""},{"name":"Hồ Bảo Sâm","avatar":""},{"name":"Đàm Hiểu Phàm","avatar":""},{"name":"Kim Tử Tuyền","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
