INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-phap-su-that', 'Liệu Pháp Sự Thật', 'Shrinking', 'https://phimimg.com/upload/vod/20240305-1/2c40556436af27d4b03c8e2e0d6e8f18.jpg', 'https://phimimg.com/upload/vod/20240305-1/17a1df47fd62a9d8712759964e8dfe0f.jpg', '<p>Jimmy đang vật lộn để đau buồn vì mất vợ khi vừa là một người cha, một người bạn và một nhà trị liệu. Anh ấy quyết định thử một cách tiếp cận mới với tất cả mọi người trên con đường của mình: sự trung thực tàn bạo, không bị lọc. Anh ta có thể tự giúp mình bằng cách giúp đỡ người khác không? Nó sẽ đưa anh ta trở lại ánh sáng?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Segel","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Luke Tennie","avatar":""},{"name":"Michael Urie","avatar":""},{"name":"Lukita Maxwell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324255);
