INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-rig', 'The Rig', 'The Rig', 'https://phimimg.com/upload/vod/20240305-1/7623bda4a605c6cd8585181c7ca2e9d7.jpg', 'https://phimimg.com/upload/vod/20240305-1/af45b3557bc21dcdf87fbbf29423b3aa.jpg', '<p>Một nhóm công nhân trên một giàn khoan dầu xa xôi của Scotland chuẩn bị trở về đất liền thì một màn sương mù bí ẩn bao phủ họ và các thế lực siêu nhiên nắm giữ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2023, 'VietSub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iain Glen","avatar":""},{"name":"Emily Hampshire","avatar":""},{"name":"Rochenda Sandall","avatar":""},{"name":"Martin Compston","avatar":""},{"name":"Molly Vevers","avatar":""},{"name":"Owen Teale","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
