INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-sac-tam-uoc', 'Mộ Sắc Tâm Ước', 'Twilight', 'https://phimimg.com/upload/vod/20240305-1/7d352459b0972edb5a2b8a764710e427.jpg', 'https://phimimg.com/upload/vod/20240305-1/2632cea9a0e88f674750b85b3cf38b6e.jpg', '<p>Nhà văn Qi Lianshan (do Ren Jialun thủ vai) muốn chuyển thể cuốn tiểu thuyết lý luận tâm lý của mình thành kịch bản. Sau khi nhìn thấy Lưu Hà (do AngelaBaby thủ vai), người đã hướng dẫn thành công một người phụ nữ muốn nhảy cầu bằng kiến thức tâm lý của mình, anh đã mời cô làm cố vấn. Trong quá trình chuyển thể tiểu thuyết, Kỳ Liên Sơn bị Lưu Hà thu hút sâu sắc, cuối cùng cả hai có được sự nghiệp thành công và một chuyện tình đẹp.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ren Jialun","avatar":""},{"name":"AngelaBaby","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
