INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-phan-dien-de-thuong', 'Chàng Phản Diện Dễ Thương', 'Cute Bad Guy', 'https://phimimg.com/upload/vod/20240305-1/e613f84c59b1eb5855c7282b5dbeeb36.jpg', 'https://phimimg.com/upload/vod/20240305-1/71d0940b3cf8651f2d84e44a38ff55e0.jpg', '<p>Câu chuyện kể về Hạ Vũ Manh, một họa sĩ truyện tranh là bà hoàng suy diễn, người sẵn sàng làm người tàng hình cả đời, Thẩm Minh Hề, đại boss phản diện được tạo ra trong truyện tranh tự giải trí của cô, trong một thời khắc bất thường đã xuyên không từ thế giới truyện tranh đến thế giới thật của cô, vừa phù hợp với thiết lập nhân vật trong truyện tranh, vừa mắc chứng mất trí nhớ kỳ lạ. Người tạo ra anh, Hạ Vũ Manh chỉ có thể chịu trách nhiệm cho Hàn Lỗi. Trong cơn hoảng loạn, cô đã để tên ác nhân này xen vào mối quan hệ của mình với nam thần trong mơ của mìn là Nhậm Vân Kiệt. Người bạn thân thiết nhất của cô là Viên Y Lâm và anh trai chân chó của họ Thẩm, Hàn Phi Dương liên tục thêm cảnh. Sau khi trải qua nhiều quảng thời gian ở chung , Hạ và Thẩm càng thêm tương ái tương sát, sống chết dính vào một chỗ. Vì hạnh phúc cuối cùng và hòa bình thế giới,Hạ Vũ Manh quyết định thực hiện kế hoạch cải tạo bạn trai phản diện, biến Thẩm Minh Hề thành một chàng trai tốt ở thế kỷ 21...</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Yi Jie","avatar":""},{"name":"Wang Er Yi Xuan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324255);
