INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-yearbook-sach-ky-yeu', 'The Yearbook: Sách Kỷ Yếu', 'The Yearbook The Series', 'https://phimimg.com/upload/vod/20240305-1/33b568dc3cee7e154ac42ced04382da1.jpg', 'https://phimimg.com/upload/vod/20240305-1/7a03b00993a328f606f5e72423ba7f3f.jpg', '<p>Bạn còn nhớ những người bạn trong “Kỷ yếu” không? Một loạt phim sẽ đưa bạn trở lại đầu những năm 2000 và mối liên hệ sâu sắc giữa Phob và Nut khi cả hai hứa sẽ cùng nhau theo đuổi ước mơ của mình. Thật không may, ai đó đã không giữ lời hứa và điều đó dẫn đến những bất đồng. Giữa họ chỉ còn lại nỗi đau. Cuối cùng, họ chia tay nhau. Bốn năm sau, cuốn kỷ yếu đưa người bạn đó trở lại với một số sự thật. Cuối cùng, tình bạn, sự thân thiết và ước mơ của họ sẽ trở lại hay họ sẽ phải đối mặt với thực tế và để lại mọi thứ như những kỷ niệm trong cuốn Kỷ yếu?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Phiravich Attachitsataporn","avatar":""},{"name":"Mean","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
