INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-cuoi-tinh-dau', 'Hạ Cuối Tình Đầu', 'Hạ Cuối Tình Đầu', 'https://phimimg.com/upload/vod/20240305-1/2bd71c2eddcbc69bd20c2e78fc5f3d16.jpg', 'https://phimimg.com/upload/vod/20240305-1/da0b5ad2a6496f5edeab5967d1cffeb6.jpg', '<p>Lưu Ly, Khánh Mai và Thanh Thảo là ba người bạn thân. Ngay trong đêm sinh nhật tuổi 18 của Lưu Ly, họ đã bị “sụp hầm” bởi hai chàng sinh viên đa tài. Tình đầu là mối tình đẹp nhất, nhưng đáng tiếc nó cũng là mối tình đầu của cô bạn thân. Sẽ ra sao khi cả hai đã trót yêu cùng một người, cùng một thời điểm?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 15, 2023, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Quỳnh Hương","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324255);
