INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-nang', 'Quyền Năng', 'The Power', 'https://phimimg.com/upload/vod/20240305-1/5b9ff69787a3af1d70f442adfb627255.jpg', 'https://phimimg.com/upload/vod/20240305-1/455bc356aa728f8cb1dac2796cf1283c.jpg', '<p>Thế giới của The Power là thế giới của chúng ta, nhưng đối với một khuynh hướng tự nhiên. Đột nhiên các cô gái tuổi teen phát triển sức mạnh để giật điện mọi người theo ý muốn. Theo chân những nhân vật đáng chú ý từ London đến Seattle, Nigeria đến Đông Âu, Sức mạnh phát triển từ cảm giác ngứa ran ở xương quai xanh của thanh thiếu niên đến sự đảo ngược hoàn toàn cán cân quyền lực.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Toni Collette","avatar":""},{"name":"Halle Bush","avatar":""},{"name":"Ria Zmitrowicz","avatar":""},{"name":"Auli''i Cravalho","avatar":""},{"name":"Toheeb Jimoh","avatar":""},{"name":"John Leguizamo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324255);
