INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-maisel-ky-dieu-phan-5', 'Cô Maisel Kỳ Diệu (Phần 5)', 'The Marvelous Mrs. Maisel (Season 5)', 'https://phimimg.com/upload/vod/20240305-1/f3b63e3657c1543e2e1f85beec736ae7.jpg', 'https://phimimg.com/upload/vod/20240305-1/35eb1270c81c94be74dffedeedb844c2.jpg', '<p>Sau khi đốt cầu và bị cắt khỏi chuyến lưu diễn, Midge Maisel vẫn kiên trì qua Phần bốn, xây dựng lại sự nghiệp và danh tiếng của mình. Những khoảnh khắc cuối cùng của mùa giải lên đến đỉnh điểm khi Midge rời khỏi Carnegie Hall như được tiếp thêm sinh lực và sẵn sàng vượt qua mọi trận bão tuyết. Sau khi hiển linh trước bảng quảng cáo đầy tuyết của The Gordon Ford Show, Midge đã sẵn sàng “Tiến lên phía trước” và chiến đấu để vươn lên thành ngôi sao—được trang bị trí thông minh nhanh nhạy và miệng lưỡi sắc bén, và không còn gì để mất.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rachel Brosnahan","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Michael Zegen","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Marin Hinkle","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Caroline Aaron","avatar":""},{"name":"Reid Scott","avatar":""},{"name":"Alfie Fuller","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
