INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-maisel-ky-dieu-phan-5', 'Cô Maisel Kỳ Diệu (Phần 5)', 'The Marvelous Mrs. Maisel (Season 5)', 'cô maisel kỳ diệu (phần 5) the marvelous mrs. maisel (season 5) rachel brosnahan alex borstein michael zegen tony shalhoub marin hinkle kevin pollak caroline aaron reid scott alfie fuller ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-cong-cung-nguyen', 'Đội Đặc Công Cung Nguyên', 'Route', 'https://phimimg.com/upload/vod/20240305-1/04ff00a124d344242b3d79a763dc1e14.jpg', 'https://phimimg.com/upload/vod/20240305-1/2e4251a8182550e6a8d883c95608afd9.jpg', '<p>Ngôi sao Cung Lễ đầy thị phi và cô cử nhân ngành Tâm lý học giả làm nhà chiêm tinh vô tình bị cuốn vào một vụ mưu sát, trở thành kẻ chịu tội thay trong mắt nhiều người. Cũng chính vì thế mà họ bị hãm hại, đuổi giết, mỗi bước đi đều rơi vào một âm mưu ly kì khác khiến con người ta ngày càng suy sụp. Nhưng rồi Cung Lễ đã vận dụng trí thông minh và lòng dũng cảm mà chính bản thân cũng không ngờ đến, chiến thắng bản chất của một người bình thường như lười biếng, ngốc nghếch. Anh nhìn thấu các chiêu trò, tùy cơ ứng biến, hợp tác với lực lượng cảnh sát chính nghĩa, cuối cùng thoát nạn trong tình huống ngàn cân treo sợi tóc và phá được vụ án động trời.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ming Dao","avatar":""},{"name":"Jiang Kaitong","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Apollo Yu","avatar":""},{"name":"Josephine Yu","avatar":""},{"name":"He Zeyuan","avatar":""},{"name":"Monica Chan","avatar":""},{"name":"Ma Yi","avatar":""},{"name":"Jackie Li","avatar":""},{"name":"Yuni Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
