INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-ve-tinh-yeu', 'Truyền Thuyết Về Tình Yêu', 'Love Of The Two Realms', 'https://phimimg.com/upload/vod/20240305-1/ec1d4ef51570674ddc1dfbc454394e03.jpg', 'https://phimimg.com/upload/vod/20240305-1/f2e58d72c405369a35242b7c8e441a68.jpg', '<p>Được xây dựng dựa trên câu chuyện dân gian của Thái Lan. Vì muốn có được hai cô nàng xinh đẹp Tapaokaew và Tapaothong mà Vua cá sấu hung dữ Chalawan đã bắt họ về cung điện của mình. Mọi nỗ lực để cứu hai nàng đều thất bại cho đến khi Kraithong xuất hiện.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ice Preechaya Pongthananikorn","avatar":""},{"name":"Golf Anuwat Choocherdratana","avatar":""},{"name":"Ohm Thitiwat Ritprasert","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324255);
