INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-thuyet-ve-tinh-yeu', 'Truyền Thuyết Về Tình Yêu', 'Love Of The Two Realms', 'truyền thuyết về tình yêu love of the two realms ice preechaya pongthananikorn golf anuwat choocherdratana ohm thitiwat ritprasert ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-17-cua-toi-va-bo', 'Tuổi 17 Của Tôi Và Bố', 'Who''s Your Daddy?', 'https://phimimg.com/upload/vod/20240305-1/2ef3efc30eb036abe0b2f2b707a9d014.jpg', 'https://phimimg.com/upload/vod/20240305-1/5d5a05834748b6c5732219bee0431d1c.jpg', '<p>Trần Tất Đạt ông trùm công nghệ tuổi trung niên gặp tai nạn và hoán đổi cơ thể với cậu học sinh cấp ba Cao Văn Minh. Để đổi lại cơ thể, Trần Tất Đạt phải vắt óc nghĩ đủ mọi cách, xảy ra nhiều va chạm và xung đột với các học sinh cấp ba mà đại diện chính là Giang Vũ con trai ông. Được Trần Tất Đạt khích lệ, Giang Vũ lại thắp lên ước mơ, chịu tác động từ tấm lòng son của Giang Vũ, Trần Tất Đạt tìm lại ước nguyện thuở xưa, đồng thời bắt đầu học gánh vác trách nhiệm của người làm cha. Trần Tất Đạt và Giang Vũ dần trở thành bạn thân nhất, hợp tác chiến thắng chức vô địch cuộc thi Sáng tạo Khoa học kỹ thuật dành cho học sinh cấp ba, đồng thời dẫn dắt cả lớp tham gia giải đua việt dã, một lần nữa khơi dậy tinh thần chiến đấu và tinh thần đoàn kết của toàn thể giáo viên học sinh. Thế nhưng, Cao Văn Minh thức tỉnh, khủng hoảng sự nghiệp của Trần Tất Đạt cũng theo đó tăng lên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Kỳ","avatar":""},{"name":"Lý Minh Đức","avatar":""},{"name":"Hạc Nam","avatar":""},{"name":"Trương Thần Tiêu","avatar":""},{"name":"Trần Kính Y","avatar":""},{"name":"Liêu Tuệ Giai","avatar":""},{"name":"Tiết Giai Ngưng","avatar":""},{"name":"Tôn Hạo","avatar":""},{"name":"Ngô Ngọc Phương","avatar":""},{"name":"Nghiêm Ngật Khoan","avatar":""},{"name":"Thi Vũ","avatar":""},{"name":"Cao Lượng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324255);
