INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cutie-pie-2-you', 'Cutie Pie 2 You', 'Cutie Pie 2 You', 'https://phimimg.com/upload/vod/20240305-1/e4d62f23e3a71076840f9d82bcb1cff5.jpg', 'https://phimimg.com/upload/vod/20240305-1/1ad033dfb5239ccc15e16f38491b2335.jpg', '<p>Kuea vừa tốt nghiệp và Lian hào hứng bắt đầu lên kế hoạch cho đám cưới của họ, nhưng giấc mơ của Kuea vẫn còn ở phía trước. Điều này có ảnh hưởng đến mối quan hệ của họ không? Trong khi Yi phải mất một thời gian để mở lòng và thú nhận tình yêu của mình dành cho Khondiao, giờ đây họ sẽ phải đối mặt với những thử thách mới nào? Cuối cùng, liệu Noor và Syn có làm sáng tỏ mối quan hệ mới chớm nở của họ không?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Zee Pruk Panich","avatar":""},{"name":"NuNew Chawarin Perdpiriyawong","avatar":""},{"name":"Max Kornthas Rujeerattanavorapan","avatar":""},{"name":"Nat Natasitt Uareksit","avatar":""},{"name":"Yim parinyakorn khansawa","avatar":""},{"name":"Tutor Koraphat Lamnoi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
