INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-su-2023', 'Hôn Sự', 'Dear Liar', 'https://phimimg.com/upload/vod/20240329-1/edaddd3af24f9713c29532cf03b4b530.jpg', 'https://phimimg.com/upload/vod/20240329-1/1db93cba93b392d83a10a1a2b6712efe.jpg', '<p>Sau nhiều tháng chuẩn bị, Tống Diệc Phi và Tần Lý cuối cùng cũng tổ chức hôn lễ, nhưng buổi lễ trọng thể ban đầu lại kết thúc trong một cuộc gặp gỡ ác mộng. Tống Diệc Phi lớn lên dưới sự chăm sóc của gia đình, cô ngây thơ và khao khát một cuộc hôn nhân viên mãn, nhưng cô lại phát hiện ra rằng cuộc hôn nhân của mình bị bao phủ bởi sự dối trá. Zheng Baosong, một người đàn ông xa lạ xuất hiện trong đám cưới, xuất hiện hết lần này đến lần khác trong cuộc đời cô, và mọi vấn đề dường như đều đổ dồn về chồng cô là Qin Li.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fan Zhi Xin","avatar":""},{"name":"Qu Meng Ru","avatar":""},{"name":"Huang Hao Nan","avatar":""},{"name":"Zhu Wei Ling","avatar":""},{"name":"Wang Yi Tong","avatar":""},{"name":"Cha Yi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
