INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hon-su-2023', 'Hôn Sự', 'Dear Liar', 'hôn sự dear liar fan zhi xin qu meng ru huang hao nan zhu wei ling wang yi tong cha yi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sep-cua-toi-sao-lai-nhu-vay', 'Sếp Của Tôi Sao Lại Như Vậy', 'Love Me Like I Do', 'https://phimimg.com/upload/vod/20240305-1/32c89a24d7199b44364c74cda29d4c2a.jpg', 'https://phimimg.com/upload/vod/20240305-1/abdf29cc5189484c5365ef589c8384b4.jpg', '<p>Điền Điềm là một họa sĩ minh họa, cô luôn mơ ước trở thành một nhà thiết kế art toy. Khi cô ấy ứng tuyển vị trí thiết kế art toys, cô ấy phát hiện ra rằng art toy của Tập đoàn Thiên Sinh đã sao chép các hình minh họa trước đây của cô ấy. Sau khi Điền Điềm yêu cầu tập đoàn Thiên Sinh giải thích nhiều lần, đã thu hút được sự chú ý của chủ tịch tập đoàn Liễu Hy Lai. Liễu Hy Lai không chỉ mua bản quyền của những tác phẩm ăn cắp ý tưởng mà còn để Điền Điềm gia nhập tập đoàn Thiên Sinh với tư cách là một nhà thiết kế art toy, đồng thời làm trợ lý đặc biệt cho chủ tịch để giúp anh giải quyết một số công việc cá nhân. Ban đầu,Điền Điềm dựa vào sự siêng năng và nhiệt tình của bản thân để chăm sóc cả hai bên, nhưng với sự tăng cường công việc của trợ lý đặc biệt của Liễu Hy Lai, Tian Tian đã kiệt sức và ngày càng không thể đáp ứng yêu cầu của Liễu Hy Lai, nảy sinh ra rất nhiều mâu thuẫn. Sau đó Tập đoàn Thiên rơi vào khủng hoảng, Liễu Hy Lai và Điền Điềm cùng nhau bảo vệ Tập đoàn Thiên Sinh, vừa hay lại giúp tâm tư của hai người gắn chặt hơn. Những đồng nghiệp và bạn bè bên cạnh họ cũng dần trưởng thành và đạt được thành tựu trong sự nghiệp.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Yin Jun","avatar":""},{"name":"Muxi Zhang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
