INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-thoi-tien-su-phan-2', 'Hành Tinh Thời Tiền Sử (Phần 2)', 'Prehistoric Planet (Season 2)', 'https://phimimg.com/upload/vod/20240305-1/728b09b36374f166662893282ff38a61.jpg', 'https://phimimg.com/upload/vod/20240305-1/241f653afd37f84a9a0a121cb1670f96.jpg', '<p>Trải nghiệm những điều kỳ diệu của thế giới chúng ta chưa từng có với loạt phim tài liệu này của Jon Fevreau và các nhà sản xuất của Planet Earth. Du hành trở về 66 triệu năm khi những con khủng long oai phong và những sinh vật phi thường lang thang trên các vùng đất, biển và bầu trời.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324255);
