INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thanh-trung-chap-niem-bat-luong', 'Người Thanh Trừng Chấp Niệm Bất Lương', 'Oh No! Here Comes Trouble', 'https://phimimg.com/upload/vod/20240305-1/1874cdb26d383456ae61c1f121f5de80.jpg', 'https://phimimg.com/upload/vod/20240305-1/cb81d9664ef286b4358c9e5c7a9eee54.jpg', '<p>Người Thanh Trừng Chấp Niệm Bất Lương (Oh No! Here Comes Trouble) kể về câu chuyện của cậu học sinh trung học Bồ Nhất Vĩnh rơi vào trạng thái hôn mê sau khi gặp phải một tai nạn xe hơi trên bờ vực sinh tử, sau khi tỉnh dậy thì bất ngờ sở hữu siêu năng lực, cuộc sống vốn vô vị từ nay xảy ra thay đổi điên đảo đất trời, cùng nữ cảnh sát tay mơ Trần Chử Anh và kẻ đối đầu Tào Quang Nghiên cùng trường, cả ba bắt tay một hành trình đánh quái vừa huyền ảo vừa điên rồ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Kính Hoa","avatar":""},{"name":"Bành Cẩn Du","avatar":""},{"name":"Lâm Hòa Xuân","avatar":""},{"name":"Cheryl Dương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324255);
