INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-tu-cai-nhin-thu-hai', 'Yêu Em Từ Cái Nhìn Thứ Hai', 'Love At Second Sight', 'https://phimimg.com/upload/vod/20240305-1/9595d3d9cbe14e34a54b7414883e573d.jpg', 'https://phimimg.com/upload/vod/20240305-1/81b63f44c973bb8510cffcbcd6fc9905.jpg', '<p>Nhân viên truyền thông mới Tô Nam vô tình gặp lại mối tình đầu - Cố Dịch Bắc, lúc này anh đã trở thành tài năng mới trong ngành IT. Năm năm trước, Tô Nam ra đi khi sự nghiệp của Cố Dịch Bắc rơi vào giai đoạn khủng hoảng nhất, khiến anh khúc mắc trong lòng, nhưng vẫn nhớ nhung khôn nguôi. Sau khi trùng phùng, Cô Dịch Bắc bắt đầu tạo ra đủ mọi tình huống tình cờ để gặp Tô Nam liên tục, và chân tướng đằng sau việc Tô Nam vô tình bỏ rơi anh cũng dần được hé mở.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tổ Nhất","avatar":""},{"name":"Thiệu Vũ","avatar":""},{"name":"Thất Hầu","avatar":""},{"name":"Đông Hàn","avatar":""},{"name":"Vũ Đồng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324255);
