INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-binh-pham', 'Con Đường Bình Phàm', 'The Ordinary Road', 'https://phimimg.com/upload/vod/20240305-1/46e8f9ec5a01c96767de7b4dfaad4906.jpg', 'https://phimimg.com/upload/vod/20240305-1/db359682b28a3bbc14dbf18a3519b7d9.jpg', '<p>Nó kể một câu chuyện đầy cảm hứng. Được dẫn dắt bởi những tiền bối giàu kinh nghiệm trong ngành, một nhóm thanh niên mới bắt đầu sự nghiệp đang lớn lên cùng nhau và cuối cùng vượt lên chính mình với niềm tin vững chắc bằng cách học hỏi lẫn nhau. Cuối cùng, họ không chỉ tạo ra một bước nhảy vọt trong khả năng làm việc mà còn học lại những ý nghĩa đa dạng của cuộc sống bình thường.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kevin Guo","avatar":""},{"name":"Jin Chen","avatar":""},{"name":"Yan Zidong","avatar":""},{"name":"Zhu Zhu","avatar":""},{"name":"Zhang Zixian","avatar":""},{"name":"Kang Keren","avatar":""},{"name":"Wang Zhifei","avatar":""},{"name":"Liu Weiwei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
