INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dieu-toi-chua-tung-phan-4', 'Những điều Tôi Chưa Từng (Phần 4)', 'Never Have I Ever (Season 4)', 'https://phimimg.com/upload/vod/20240305-1/c9324628377fa424b3ac8f81b3580074.jpg', 'https://phimimg.com/upload/vod/20240305-1/f7ab5e0b06dfa8a8372caee0f1463087.jpg', '<p>Cuối cùng đã đến năm cuối cấp. Giữa những câu hỏi hóc búa về trường đại học, khủng hoảng bản sắc và mối tình khó quên, liệu Devi và nhóm đã sẵn sàng đối mặt với tương lai?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maitreyi Ramakrishnan","avatar":""},{"name":"Poorna Jagannathan","avatar":""},{"name":"Richa Moorjani","avatar":""},{"name":"Ranjita Chakraverty","avatar":""},{"name":"John McEnroe","avatar":""},{"name":"Ramona Young","avatar":""},{"name":"Lee Rodriguez","avatar":""},{"name":"Megan Suri","avatar":""},{"name":"Jaren Lewison","avatar":""},{"name":"Darren Barnet","avatar":""},{"name":"Christina Kartchner","avatar":""},{"name":"Common","avatar":""},{"name":"Adam Shapiro","avatar":""},{"name":"Niecy Nash-Betts","avatar":""},{"name":"Sendhil Ramamurthy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
