INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-dieu-toi-chua-tung-phan-4', 'Những điều Tôi Chưa Từng (Phần 4)', 'Never Have I Ever (Season 4)', 'những điều tôi chưa từng (phần 4) never have i ever (season 4) maitreyi ramakrishnan poorna jagannathan richa moorjani ranjita chakraverty john mcenroe ramona young lee rodriguez megan suri jaren lewison darren barnet christina kartchner common adam shapiro niecy nash-betts sendhil ramamurthy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-duoc-uoc-thay-2023', 'Cầu Được Ước Thấy', 'Hello Beautiful Life', 'https://phimimg.com/upload/vod/20240305-1/a628d77f0f4cd18f198d017bc167eb84.jpg', 'https://phimimg.com/upload/vod/20240305-1/73d77f34fbf493f4536eaf20a97a1f1a.jpg', '<p>Tôn Tâm và Tôn Tưởng, một người dám chiến đấu và đột phá, người kia ấm áp như nước. Người chị Tôn Tâm xinh đẹp và hào phóng, theo đuổi tự do và dám chiến đấu hết mình. Cô em gái Tôn Tưởng, trong sáng và tốt bụng, luôn nói cười vui vẻ. Tính cách quá khác biệt khiến hai chị em bước vào những quỹ đạo cuộc đời hoàn toàn khác nhau. Người chị đang làm ăn phát đạt trong một công ty Internet, trải qua bao thăng trầm; em gái phát hiện ra thế mạnh của bản thân và trở thành một blogger ẩm thực, ăn ngon sống nhàn. Trong 8 năm từ 2012 đến 2020, cuộc sống của họ ngày càng khấm khá, dù trải qua nhiều nhưng họ luôn tràn đầy niềm tin vào tương lai.Cuộc sống muôn màu, bình thản hạnh phúc, phấn đấu thiết thực đều lại những “vị” cơ bản. Mỗi gia đình là một đất nước nhỏ thì quốc gia là hàng vạn gia đình. Chính vì có hàng ngàn người bình thường như chị em nhà họ Tôn siêng năng, tốt bụng và không ngừng theo đuổi ước mơ của mình mà xã hội tràn đầy sức sống và thịnh vượng, và \xã hội thịnh vượng vừa phải\ đã trở thành hiện thực sống động xung quanh người Trung Quốc.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mao Hiểu Đồng","avatar":""},{"name":"Zhang Li","avatar":""},{"name":"Zefeng Li","avatar":""},{"name":"Li Ze Feng","avatar":""},{"name":"BOOGIE","avatar":""},{"name":"Zhang Kai Li","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324255);
