INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('madoff-quai-vat-pho-wall', 'MADOFF: Quái Vật Phố Wall', 'MADOFF: The Monster Of Wall Street', 'https://phimimg.com/upload/vod/20240305-1/c925d5c4d6ac5b54f750a20c39207cc5.jpg', 'https://phimimg.com/upload/vod/20240305-1/e6a4952ed2cf0734e614e6e2a68c6e85.jpg', '<p>Loạt phim tài liệu này dõi theo hành trình thăng trầm của nhà tài chính Bernie Madoff, người dàn dựng một trong những mô hình Ponzi lớn nhất lịch sử Phố Wall.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324255);
