INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('madoff-quai-vat-pho-wall', 'MADOFF: Quái Vật Phố Wall', 'MADOFF: The Monster Of Wall Street', 'madoff: quái vật phố wall madoff: the monster of wall street  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-chang-qua-khong-muon-thua', 'Cô Ấy Chẳng Qua Không Muốn Thua', 'Stand Or Fall', 'https://phimimg.com/upload/vod/20240304-1/ae67fdf7cf6af34bf416acad84e9fe71.jpg', 'https://phimimg.com/upload/vod/20240304-1/d020ff7fde2c06e1ed64b1a9ade880da.jpg', '<p>Quản Văn, cô gái được mệnh danh là “khắc tinh của những khách hàng khó nhằn”, đường công danh thăng tiến như diều gặp gió trong doanh nghiệp nước ngoài, vào đêm trước sinh nhật 33 tuổi, gặp phải cạm bẫy do đồng nghiệp gây ra nên quyết định từ chức. Vào tuổi 33 tam tai, không ngờ chặng đường làm lại sự nghiệp lại vô cùng gian nan, bị chơi xấu trong các cuộc phỏng vấn, sau cùng đành phải vào làm ở một trung tâm thương mại vừa mới mở không bao lâu. Ngoài mặt, cô từ bên B trở thành bên A, trên thực tế, trung tâm thương mại này lại không hề khởi sắc vì gặp khó khăn trong việc tìm kiếm khách hàng. Ngoài ra, cô còn gặp lại người yêu cũ hồi học đại học nhưng lại rất lạnh lùng trong công việc - Đinh Ninh, hạch sách và soi mói cô đủ điều. Hai người từ tranh chấp chống đối dần trở nên mập mờ khó tả, rồi từ hẹn hò cho đến bẻ lái khét lẹt, trong tình cảm lại chứa đựng quá nhiều sự tính toán của thế giới người trưởng thành, Quản Văn tiến thoái lưỡng nan, vừa không muốn Đinh Ninh thỏa hiệp quá đáng, hy sinh sự nghiệp vì mình, sau khi suy đi tính lại, cô vẫn lựa chọn nắm lấy quyền quyết định của mình. Cùng lúc đó, hai người bạn thân của Quản Văn - vận động viên giải nghệ Trần Huyên Huyên, nữ ngôi sao hết thời Cảnh Tri Thu cũng gặp phải những chông gai trong cuộc đời: Một mối tình lâu năm đương đầu với thử thách, một cuộc hôn nhân đứng trước hồi chuông báo động. Họ phải làm sao để giành chiến thắng trong cuộc chiến cam go này? Nếu cuộc đời là một trận chiến thì bản thân họ chính là những vũ khí lợi hại nhất, có tuổi thì đã sao? Đánh đâu thua đó thì đã sao? Tiếp tục chiến đấu! Ai cũng muốn chiến thắng, họ không những muốn thắng, mà còn phải thắng thật oanh liệt!</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tần Lam","avatar":""},{"name":"Vương Dương","avatar":""},{"name":"Trương Manh","avatar":""},{"name":"Lưu Vân","avatar":""},{"name":"Ngụy Thiên Tường","avatar":""},{"name":"Trương Đạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
