INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gunther-chu-cho-trieu-phu', 'Gunther - Chú Chó Triệu Phú', 'Gunther''s Millions', 'https://phimimg.com/upload/vod/20240304-1/6e60e9433b86903b178cc37393c77643.jpg', 'https://phimimg.com/upload/vod/20240304-1/56e18c1b01cef4bc626a64cff376f181.jpg', '<p>Một chú chó có quỹ tín thác chưa phải là phần kỳ lạ nhất của câu chuyện này. Người quản lý lập dị của Gunther cũng sống một cuộc sống xa hoa với đoàn tùy tùng giống như giáo phái.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324255);
