INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-vuc-sumo', 'Thánh Vực Sumo', 'Sanctuary', 'https://phimimg.com/upload/vod/20240304-1/06ece82920d1518590f7c4ea68868de7.jpg', 'https://phimimg.com/upload/vod/20240304-1/0c0fe31576ae435ce7a5535b6758ece5.jpg', '<p>Một đứa trẻ cứng cỏi, liều mạng trở thành đô vật sumo, thu hút người hâm mộ bằng thái độ tự phụ của mình và trở thành cái gai trong mắt một ngành có truyền thống lâu đời.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ichinose Wataru","avatar":""},{"name":"Sometani Shota","avatar":""},{"name":"Kutsuna Shioli","avatar":""},{"name":"Taguchi Tomorowo","avatar":""},{"name":"Kitarou","avatar":""},{"name":"Maiguma Katsuya","avatar":""},{"name":"Sumi Hiroki","avatar":""},{"name":"Kaku So","avatar":""},{"name":"Inui Akito","avatar":""},{"name":"Omusubi","avatar":""},{"name":"Teramoto Rio","avatar":""},{"name":"Ando Sei","avatar":""},{"name":"Kaneko Daichi","avatar":""},{"name":"Sendo Nobuko","avatar":""},{"name":"Sawada Kensho","avatar":""},{"name":"Ishikawa Shuhei","avatar":""},{"name":"Yoshie Kazuya","avatar":""},{"name":"Kobayashi Kei","avatar":""},{"name":"Mecc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
