INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dung-thanh-tong-thong', 'Bỗng Dừng Thành Tổng Thống', 'Represent', 'https://phimimg.com/upload/vod/20240304-1/7c6205645e5692e4f463b6f6077271ae.jpg', 'https://phimimg.com/upload/vod/20240304-1/39d64a4f46c37b674a6aa16f06523122.jpg', '<p>Một người hướng dẫn tại trung tâm thanh niên ở vùng ngoại ô của Paris trở thành ứng viên trong cuộc bầu cử tổng thống. Nhưng liệu Pháp đã thực sự sẵn sàng cho tổng thống da đen?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean-Pascal Zadi","avatar":""},{"name":"Éric Judor","avatar":""},{"name":"Benoît Poelvoorde","avatar":""},{"name":"Fadily Camara","avatar":""},{"name":"Marina Foïs","avatar":""},{"name":"Fary","avatar":""},{"name":"Panayotis Pascot","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324255);
