INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-duong-nu-nhi-tinh', 'Nam Dương Nữ Nhi Tình', 'Sisterhood', 'https://phimimg.com/upload/vod/20240304-1/8254cf4d6324782b59796879568ed2b5.jpg', 'https://phimimg.com/upload/vod/20240304-1/d1482a36c86707b40613454905614381.jpg', '<p>Tình Nữ Nhi Nam Dương là bộ phim truyền hình sử thi đấu tranh truyền cảm hứng cho phụ nữ Trung Quốc của đạo diễn bởi Quách Thế Dân, với sự tham gia của các diễn viên Tiêu Yến và Đới Tương Vũ Tiêu Yến và Đới Hướng Vũ lại đóng phim cùng nhau, tiếp tục số phận của vai chính trong Chuyện tình cô bé Lọ Lem , kể về câu chuyện tình yêu ở Nam Dương. Một truyền thuyết về thời đại đầy cảm hứng, một tác phẩm mới đầy sức sống tập trung vào một nhân vật nữ. Một câu chuyện khắc họa tinh thần đấu tranh của Hoa kiều, đề cao trọn vẹn nét đẹp văn hóa Trung Hoa giữa những đổi thay của cuộc sống. Một huyền thoại đẹp sẽ được chia sẻ trên toàn thế giới.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Yến","avatar":""},{"name":"Xiangyu Dai","avatar":""},{"name":"Nhạc Lệ Na","avatar":""},{"name":"Wu Xi Ze","avatar":""},{"name":"Xu Fan Xi","avatar":""},{"name":"Zhang Xi Wen","avatar":""},{"name":"Feifan Yu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
