INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aquaman-va-vuong-quoc-that-lac', 'Aquaman và Vương Quốc Thất Lạc', 'Aquaman and the Lost Kingdom', 'https://phimimg.com/upload/vod/20231018-1/891efb14c090af1c018d611a9e604d58.jpg', 'https://phimimg.com/upload/vod/20231018-1/24656800bf1f179f0b5eb6010ad224e3.jpg', '<p>Đạo diễn James Wan và Jason Momoa trong vai Aquaman—cùng với Patrick Wilson, Amber Heard, Yahya Abdul-Mateen II và Nicole Kidman sẽ trở lại trong phần tiếp theo của bộ phim DC có doanh thu cao nhất mọi thời đại “Aquaman Và Vương Quốc Thất Lạc (tựa gốc: Aquaman and the Lost Kingdom)”.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jason Momoa","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Yahya Abdul-Mateen II","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Indya Moore","avatar":""},{"name":"Pilou Asbæk","avatar":""},{"name":"Jani Zhao","avatar":""},{"name":"Vincent Regan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324255);
