INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-den-tu-tuong-lai', 'Em Đến Từ Tương Lai', 'You From The Future', 'https://phimimg.com/upload/vod/20240304-1/2965e4726b489fe714f14ec8f8c71aca.jpg', 'https://phimimg.com/upload/vod/20240304-1/a1bb4672945dde43865707d48021b356.jpg', '<p>\Em Đến Từ Tương Lai \ do Châu Vĩnh đạo diễn, với sự tham gia của La Chính và Quý Mỹ Hàm\nHạ Mạt tốt nghiệp đại học, mong muốn trở thành một blogger Hán phục. Cha mẹ của Hạ Mạt có một ngôi nhà ở Hải Thị, và Hạ Mạt quyết định lấy lại ngôi nhà. Người thuê nhà hiện tại.Thẩm Quân Nghiêu là chủ tịch của một công ty công nghệ, để thuận tiện cho công việc của mình, Thẩm Quân Nghiêu đã lắp đặt rất nhiều thiết bị nghiên cứu khoa học trong nhà. Hạ Mạt và Thẩm Quân Nghiêu ở chung nhà. Hạ Mạt không ngờ rằng nơi cô sắp làm việc lại cùng tập đoàn nơi Thẩm Quân Nghiêu làm việc. Hai người sống chung dưới một mái nhà đã ghét nhau lại còn phải làm chung với nhau. Dần Dần Thẩm Quân Nghiêu đã phát hiện ra rằng cô gái này có điểm gì đó dễ thương và Thẩm Quân Nghiêu cũng quyết định theo đuổi Hạ Mạt. \nBộ phim này sẽ được phát sóng trực tuyến trên iQIYI quốc tế (iq.com).</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Chính","avatar":""},{"name":"Quý Mỹ Hàm","avatar":""},{"name":"Yang Ze","avatar":""},{"name":"Chen Si Che","avatar":""},{"name":"Wang Kang","avatar":""},{"name":"Jie Bing","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324255);
