INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-mang-mat-na', 'Cô Gái Mang Mặt Nạ', 'Mask Girl', 'https://phimimg.com/upload/vod/20240304-1/b1c4071c5336c2a2957540f13fcac83b.jpg', 'https://phimimg.com/upload/vod/20240304-1/ea3ffa81a697557af8e8792f45634ab4.jpg', '<p>Một nhân viên văn phòng không tự tin về ngoại hình của mình trở thành nhân vật đeo mặt nạ trên mạng vào ban đêm cho đến khi một chuỗi sự kiện đen đủi ập đến với cuộc đời cô.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ko Hyun-jung","avatar":""},{"name":"Nana","avatar":""},{"name":"Lee Han-byeol","avatar":""},{"name":"Ahn Jae-hong","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Daniel Choi","avatar":""},{"name":"Kim Ga-hee","avatar":""},{"name":"Park Jeong-hwa","avatar":""},{"name":"Han Ja-i","avatar":""},{"name":"Lee Jun-young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
