INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-dua-phu-nhan-ta-di-gium', 'Mau Đưa Phu Nhân Ta Đi Giùm', 'Take My Wife Away', 'https://phimimg.com/upload/vod/20240304-1/f330667d5f31eb525889c7f692e0d5cf.jpg', 'https://phimimg.com/upload/vod/20240304-1/7918ff161d9c703c86c409af5b357381.jpg', '<p>Tần Trăn, nữ giám đốc tài chính thời hiện đại xuyên về lại nước Đại Ngụy, trở thành thiếu phu nhân của tiêu cục Đệ Nhất sắp sụp đổ. Cô vừa đấu trí vừa đấu võ với chàng tướng công ăn chơi trác táng, đồng thời dùng phương pháp quản lý thời hiện đại để chấn hưng lại tiêu cục.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Y Linh","avatar":""},{"name":"Vương Cảnh Hạo","avatar":""},{"name":"Trần Lộ Xuyến","avatar":""},{"name":"Ngô Hân","avatar":""},{"name":"Châu Mạnh Tinh","avatar":""},{"name":"Đặng Chí Hạo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
