INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-duyen', 'Trần Duyên', 'Divine Destiny', 'https://phimimg.com/upload/vod/20240304-1/042e136fb9ba249ea12911c3cb3aa34e.jpg', 'https://phimimg.com/upload/vod/20240304-1/103673028617d620d32592ff25627267.jpg', '<p>Trần Duyên (Divine Destiny) kể về câu chuyện xoay quanh Kỷ Nhược Trần, là một tiểu tử bồi bàn của một khách sạn bí ẩn có cái tên Long Môn. Nhờ có tư chất thông minh, không hiểu vì cố ý hay vô tình mà hắn bị cả tu chân giới nhận nhầm là Trích Tiên (Tiên nhân xuống trần gian), là đối tượng mà cả tu chân giới thèm thuồng tranh đoạt. Chính nhờ cơ duyên này, hắn mơ hồ bước vào con đường đại đạo, từng bước vấn đỉnh thế giới tu chân kỳ ảo. Hãy đón xem lịch chiếu phim Trần Duyên, review phim và nội dung phim Trần Duyên được cập nhật sớm nhất trên iQIYI nhé.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Angelababy","avatar":""},{"name":"RayMa","avatar":""},{"name":"xuanlu","avatar":""},{"name":"Marius","avatar":""},{"name":"Cheng Yumiko","avatar":""},{"name":"Wang Rui Zi","avatar":""},{"name":"Qiao Ding","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324255);
