INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-doi-tinh-yeu-toi', 'Thức Đợi Tình Yêu Tới', 'Mr. Insomnia Waiting For Love', 'https://phimimg.com/upload/vod/20240304-1/2a41438be8dd9731d056b1150f88b471.jpg', 'https://phimimg.com/upload/vod/20240304-1/08fa9603497a77abcf0290ef4dbc5f70.jpg', '<p>Nhạc sĩ nổi tiếng Lu En Tong và chủ tịch công ty công nghệ Song Yan Xu đều mắc chứng mất ngủ mãn tính. Họ khám phá ra rằng bằng cách chạm vào nhau, giấc ngủ sẽ đến với cả hai chỉ trong vài giây.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Vũ Hành","avatar":""},{"name":"Vu Công","avatar":""},{"name":"Du Nhã Phi","avatar":""},{"name":"Khổng Tuyết Nhi","avatar":""},{"name":"Trương Trần","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324255);
