INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-ma-thuat', 'Người Đàn Ông Ma Thuật', 'Enigma', 'https://phimimg.com/upload/vod/20240304-1/f18db9bd4da95178a5451dd2710542e3.jpg', 'https://phimimg.com/upload/vod/20240304-1/432a9205869a091a286aeea1bb1b4b2d.jpg', '<p>Phim xoay quanh những thanh thiếu niên trong một trường trung học. Nội dung phim là những điều bí ẩn trong trường học của Fa, liên tiếp những sự kiện xảy ra khiến mọi người kinh ngạc. Hứa hẹn bộ phim sẽ đưa người xem đi từ bất ngờ này đến bất ngờ khác.</p>', '(Hoàn Tất 4/4)', 4, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Metawin Opas-iamkajorn","avatar":""},{"name":"Chanikarn Tangkabodee","avatar":""},{"name":"Kanyarat Ruangrung","avatar":""},{"name":"Sureeyares Yakares","avatar":""},{"name":"Preeyaphat Lawsuwansiri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324255);
