INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-song-han', 'Cảnh Sát Sông Hàn', 'Han River Police', 'https://phimimg.com/upload/vod/20240304-1/171071cd1832714775baf99c908fa254.jpg', 'https://phimimg.com/upload/vod/20240304-1/d74f3fc9fdd316db8c73e9ea36734942.jpg', '<p>Bị mắc kẹt cùng nhau trong chuyến tuần tra trên sông Hàn của Seoul, hai sĩ quan phải đối mặt với các tình huống khẩn cấp từ khủng bố đến tai nạn hàng ngày và các sự cố khác cần hỗ trợ khẩn cấp, tiền đề gợi ý tất cả các hành động, sự hài hước và cách giải quyết tội phạm kỳ lạ của người bạn cảnh sát cổ điển. thể loại.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kwon Sang-woo","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Lee Sang-yi","avatar":""},{"name":"Bae Da-bin","avatar":""},{"name":"Shin Hyeon-seung","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Nam Tae-woo","avatar":""},{"name":"Lee Sae-ron","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324255);
