INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sing-my-crush-truy-phong', 'Sing My Crush: Truy Phong', 'Sing My Crush', 'https://phimimg.com/upload/vod/20240304-1/a0932512e933a6cb513fd9dddf6ecc28.jpg', 'https://phimimg.com/upload/vod/20240304-1/85166e2c67db2cb6ac444e458891f00a.jpg', '<p>Bộ phim truyền hình Hàn Quốc \Truy Phong\ được sản xuất bởi nhà sản xuất của \Blooming for You\.\nGương mặt đại diện của ban nhạc Ddara Baram là \Baram\. Vì thất bại bi thảm của mối tình đầu, anh ấy nhận ra rằng mình không thể tin tưởng trao trái tim mình cho ai nữa. Anh ấy là một người thận trọng nhưng quyết đoán. \Hán Thái\ đã gặp \Baram\ trong lớp đào tạo guitar ở trường trung học, và đã phải lòng anh, sau đó trở thành bạn tốt kiêm quản lý của anh ấy.\nTrên thực tế, tình cảm Baram dành cho Hán Thái đã vượt qua tình bạn, nhưng anh ấy đã không thể hiện điều đó ra ngoài.\nMột ngày nọ, Baram rơi vào cơn bão dư luận vì nghi án đạo nhạc, không hiểu sao thái độ của Baram rất tiêu cực, Hán Thái quyết định giúp đỡ anh ấy theo cách của mình...\nPhim sẽ được công chiếu độc quyền trên iQiyi Quốc tế (iq.com) vào ngày 2 tháng 8.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Son Hyun Woo","avatar":""},{"name":"Do-yoo Jang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324255);
