INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sing-my-crush-truy-phong', 'Sing My Crush: Truy Phong', 'Sing My Crush', 'sing my crush: truy phong sing my crush son hyun woo do-yoo jang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-ve-van-menh', 'Tấm Vé Vận Mệnh', 'The Big Door Prize', 'https://phimimg.com/upload/vod/20240304-1/f3487f21d47cd7e6d7a939c838478c77.jpg', 'https://phimimg.com/upload/vod/20240304-1/d8a4c5c6fd6e8ecd2087a53acde098d0.jpg', '<p>Một thị trấn nhỏ bị thay đổi mãi mãi khi một cỗ máy bí ẩn xuất hiện, hứa hẹn tiết lộ tiềm năng thực sự của mọi người. Chẳng mấy chốc, cư dân bắt đầu thay đổi công việc, suy nghĩ lại về các mối quan hệ và đặt câu hỏi về niềm tin đã có từ lâu—tất cả nhằm theo đuổi một tương lai tốt đẹp hơn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Chris O''Dowd","avatar":""},{"name":"Gabrielle Dennis","avatar":""},{"name":"Josh Segarra","avatar":""},{"name":"Ally Maki","avatar":""},{"name":"Damon Gupton","avatar":""},{"name":"Crystal Fox","avatar":""},{"name":"Sammy Fourlas","avatar":""},{"name":"Djouliet Amara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324255);
