INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tam-ve-van-menh', 'Tấm Vé Vận Mệnh', 'The Big Door Prize', 'tấm vé vận mệnh the big door prize chris o''dowd gabrielle dennis josh segarra ally maki damon gupton crystal fox sammy fourlas djouliet amara ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-moi', 'Chim Mồi', 'Decoy', 'https://phimimg.com/upload/vod/20240304-1/79cd021210dbf210e0c9a76c60dec7b9.jpg', 'https://phimimg.com/upload/vod/20240304-1/fba7e67cc63086170c3737bf5c25fdf6.jpg', '<p>Tám năm trước, Noh Sang Chun (Heo Sung Tae), kẻ chủ mưu của một kế hoạch lừa đảo tài chính đã lừa hàng chục nghìn nạn nhân Hàn Quốc đầu tư hàng tỷ đô la tiền tiết kiệm của họ vào một dự án không có thật sau đó đã bỏ trốn. Anh ta đã cố gắng trốn tránh pháp luật bằng cách trốn sang Trung Quốc. Sau đó có thông tin rằng hắn ta đã chết tại đó.&nbsp;Gần một thập kỷ sau, một thám tử cảnh sát yêu công lý tên là Goo Do Han (Jang Keun Suk) đã có một khám phá đáng kinh ngạc…Trong quá trình điều tra một vụ án giết người trong gia đình, Goo Do Han tìm thấy bằng chứng cho thấy Noh Sang Chun là nghi phạm. Làm thế nào mà kẻ lừa đảo này - được cho là đã chết cách đây nhiều năm - lại có liên quan đến vụ án? Goo Do Han phải cố gắng xác định xem Noh Sang Chun có thực sự chết hay không. Nếu anh ta chết, kẻ giết người thực sự có thể là ai? Nếu không, Noh Sang Chun đã trốn ở đâu trong suốt thời gian qua? Khi thám tử tiếp tục điều tra, anh ta bắt đầu tự hỏi liệu có mối liên hệ nào giữa vụ lừa đảo tám năm trước… và vụ giết người bí ẩn hay không!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Geun Suk","avatar":""},{"name":"Heu Sung Tae","avatar":""},{"name":"Lee Elijah","avatar":""},{"name":"Yoo Sung Joo","avatar":""},{"name":"Park Myung Hoon","avatar":""},{"name":"Lee Sung Wook","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324255);
