INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-hau-charlotte-cau-chuyen-bridgerton', 'Vương Hậu Charlotte: Câu Chuyện Bridgerton', 'Queen Charlotte: A Bridgerton Story', 'https://phimimg.com/upload/vod/20240304-1/2d60a512f0f00c7ad4563d434b37b2f2.jpg', 'https://phimimg.com/upload/vod/20240304-1/027b639cffed794fe3e8329fa52df511.jpg', '<p>Trong tiền truyện này của &quot;Bridgerton&quot;, cuộc hôn nhân của vương hậu trẻ Charlotte với quốc vương George của nước Anh mở ra một chuyện tình ấn tượng và biến đổi xã hội thượng lưu.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"India Amarteifio","avatar":""},{"name":"Adjoa Andoh","avatar":""},{"name":"Michelle Fairley","avatar":""},{"name":"Ruth Gemmell","avatar":""},{"name":"Corey Mylchreest","avatar":""},{"name":"Golda Rosheuvel","avatar":""},{"name":"Arsema Thomas","avatar":""},{"name":"Sam Clemmett","avatar":""},{"name":"Freddie Dennis","avatar":""},{"name":"Hugh Sachs","avatar":""},{"name":"Julie Andrews","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
