INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuong-hau-charlotte-cau-chuyen-bridgerton', 'Vương Hậu Charlotte: Câu Chuyện Bridgerton', 'Queen Charlotte: A Bridgerton Story', 'vương hậu charlotte: câu chuyện bridgerton queen charlotte: a bridgerton story india amarteifio adjoa andoh michelle fairley ruth gemmell corey mylchreest golda rosheuvel arsema thomas sam clemmett freddie dennis hugh sachs julie andrews ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oc-dao-tuoi-tre', 'Ốc Đảo Tuổi Trẻ', 'Oasis', 'https://phimimg.com/upload/vod/20240304-1/a53d49dccf509b5a8fe1d17146a174f8.jpg', 'https://phimimg.com/upload/vod/20240304-1/188149131698851d2db16903aa83ea1f.jpg', '<p>Oasis là câu chuyện của những người trẻ đấu tranh quyết liệt để bảo vệ ước mơ, tình bạn cũng như mối tình đầu duy nhất của mình. Đồng thời, mô tả cuộc sống khốc liệt khi họ phải chạy theo quyền lực, tiền tài trong một xã hội đầy rẫy sai trái của Hàn Quốc những năm 1980 - 1990.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2023, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Dong Yoon","avatar":""},{"name":"Seol In Ah","avatar":""},{"name":"Choo Young Woo","avatar":""},{"name":"Do Sang Woo","avatar":""},{"name":"Hyun Seung Hee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324255);
