INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-kim-van-luong', 'Hoàng Kim Vạn Lượng', 'Golden Bowl', 'https://phimimg.com/upload/vod/20240304-1/e5729fde36857755ca890b0d00c8da4c.jpg', 'https://phimimg.com/upload/vod/20240304-1/7c5fb703e69576db615c0a2471f854a4.jpg', '<p>Mì kéo gia truyền của nhà họ Vạn được truyền từ đời này sang đời khác. Ông tổ của họ là Vạn Triều Tông. Nhưng đến đời thứ 18 thì các con lại tranh giành nhau.

Bà Vạn Tử Thiên Hồng (do Tiết Gia Yến đóng) khó xử với sự tranh giành của ba cậu con trai là Vạn Soái (do Tào Vĩnh Liêm đóng), Vạn Niên (do Huỳnh Tử Hằng đóng) và Vạn Thế (do Mã Quán Thông đóng). Mỗi người đều được chân truyền từ cha, tự mở tiệm mì cạnh tranh nhau trên cùng một con đường. Vạn Soái nấu nước lèo ngon ngọt, Vạn Niên với kỹ thuật kéo mì điêu luyện, còn Vạn Thế với món sa tế tuyệt chiêu. Ba người vợ của họ lần lượt là: Long Cửu (do Mạch Mỹ Ân đóng), Hoắc Tiểu Ngọc (do Chu Trí Hiền đóng), Kim Chi (do Giang Gia Mẫn đóng) vì thương chồng nên thường xích mích với nhau.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2023, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Nancy Sit Ka-Yin","avatar":""},{"name":"Cho Wing-Lim","avatar":""},{"name":"Hugo Wong","avatar":""},{"name":"Mark Ma","avatar":""},{"name":"Mayanne Mak","avatar":""},{"name":"Ashley Chu","avatar":""},{"name":"Kaman Kong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
