INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bep-truong-nam-sao', 'Bếp Trưởng Năm Sao', 'Five Star Chef', 'https://phimimg.com/upload/vod/20240304-1/4eeb0d2bc2a1696cdb200a6722546bb4.jpg', 'https://phimimg.com/upload/vod/20240304-1/a82f1a92e099dddd95277432a67c53de.jpg', '<p>Bảy đầu bếp chuyên nghiệp cạnh tranh để đưa ý tưởng ẩm thực cao cấp của họ vào nhà hàng Palm Court lịch sử tại khách sạn Langham sang trọng ở London.</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 12, 2023, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324255);
