INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-khong-phai-la-keo-co-sao', 'Đây Không Phải Là Kéo Co Sao?', 'Let''s Tug It!', 'https://phimimg.com/upload/vod/20240304-1/6b39a19a4a0aa2fe08b35ed05bc0bf67.jpg', 'https://phimimg.com/upload/vod/20240304-1/9d48fb0f6d53651c5b56003c29f678d2.jpg', '<p>Minh Thừa Đại Bội là một câu lạc bộ không nổi tiếng, huấn luyện viên không đáng tin cậy Lôi Minh đã tập hợp 8 tân binh đều có những mục đích riêng để thành lập một đội, họ ngẫu hứng tham gia thi đấu chuyên nghiệp. Họ đã bị đánh bại và chế giễu trong trận chiến đầu tiên . Qúa trình chiến đấu, va vấp rồi trưởng thành, đồng thời có được tình bạn, vậy làm thế nào để họ tiếp tục và hoàn thành thỏa thuận ban đầu?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Kinh Kha","avatar":""},{"name":"Dịch Đại Thiên","avatar":""},{"name":"Âm Tiểu Thiên","avatar":""},{"name":"Lâm Tân Di","avatar":""},{"name":"Mã Ngọc Khiết","avatar":""},{"name":"Bạn Hạo Nhiên","avatar":""}]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324255);
