INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ghet-ma-van-yeu', 'Ghét Mà Vẫn Yêu', 'Love To Hate You', 'https://phimimg.com/upload/vod/20240304-1/0dacce3eb6fcdfec81d34fba6ad3cd2a.jpg', 'https://phimimg.com/upload/vod/20240304-1/da5969701ab727da92f944c858d5d3fa.jpg', '<p>Đối với một luật sư ghét việc thua đàn ông và một diễn viên hạng A không tin phụ nữ, tình yêu là chuyện hoang đường. Nhưng rồi họ buộc phải hẹn hò với nhau.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Ok Bin","avatar":""},{"name":"Yoo Teo","avatar":""},{"name":"Kim Ji Hun","avatar":""},{"name":"Go Won Hee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
