INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-uoc-ngot-ngao-dau-ha', 'Hẹn Ước Ngọt Ngào Đầu Hạ', 'Promise In The Summer', 'https://phimimg.com/upload/vod/20240304-1/e540628efe67b3a53666f1ede1ee0a49.jpg', 'https://phimimg.com/upload/vod/20240304-1/213c45dceba71f8b30861bdff4508baf.jpg', '<p>Thiếu gia lạnh lùng Hàn Thất Lục mắc bệnh lạ. Chỉ cần tiếp xúc người khác giới sẽ bị dị ứng, nhưng lại miễn dịch với cô nàng lọ lem chăm chỉ An Sơ Hạ. Dưới yêu cầu của mẹ Hàn, tình yêu được nuôi dưỡng lớn dần, trong quá trình chữa bệnh cho Hàn Thất Lục, An Sơ Hạ cũng phát hiện ra bí mật về căn bệnh này...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Hạo Đông","avatar":""},{"name":"Lưu Niệm","avatar":""},{"name":"Kiến Trạch","avatar":""},{"name":"Chính Hoàng","avatar":""},{"name":"Vân Vân","avatar":""},{"name":"Trương Tân Đồng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
