INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-xu-nu', 'Tôi Là Xử Nữ', 'I''m A Virgo', 'https://phimimg.com/upload/vod/20240304-1/72b82feef0f2c2b5c630bf163d46cec5.jpg', 'https://phimimg.com/upload/vod/20240304-1/ade662f8bef683ddf78bca4a97fc77c6.jpg', '<p>Một trò vui dành cho lứa tuổi mới lớn về Cootie, một thanh niên da đen cao 13 ft ở Oakland, CA. Lớn lên ở ẩn, Cootie sớm trải nghiệm vẻ đẹp và những mâu thuẫn của thế giới lần đầu tiên. Anh kết bạn, tìm thấy tình yêu, vượt qua những tình huống khó xử và gặp thần tượng của mình, một siêu anh hùng ngoài đời thực tên là The Hero.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jharrel Jerome","avatar":""},{"name":"Brett Gray","avatar":""},{"name":"Kara Young","avatar":""},{"name":"Allius Barnes","avatar":""},{"name":"Olivia Washington","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Carmen Ejogo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324255);
