INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sexify-phan-2', 'Sexify (Phần 2)', 'Sexify (Season 2)', 'https://phimimg.com/upload/vod/20240304-1/d85b54508f1c37178e23fe301e8eca13.jpg', 'https://phimimg.com/upload/vod/20240304-1/2bfcc6a30b4275d6e5471215e8fab646.jpg', '<p>Trước tương lai bấp bênh của công ty khởi nghiệp của họ, ba doanh nhân trẻ phải cân bằng giữa đời tư sóng gió, một đối thủ không đội trời chung và một nhà đầu tư khó tính.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2023, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Aleksandra Skraba","avatar":""},{"name":"Maria Sobocińska","avatar":""},{"name":"Sandra Drzymalska","avatar":""},{"name":"Piotr Pacek","avatar":""},{"name":"Kamil Wodka","avatar":""},{"name":"Jan Wieteska","avatar":""},{"name":"Wojciech Solarz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
