INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-dong-cua-nhan-chap', 'Rung Động Của Nhan Chấp', 'Yan Zhi''s Romantic Story', 'https://phimimg.com/upload/vod/20240304-1/2fe13e4a2bbb3235e05f7ffd32b1d0e1.jpg', 'https://phimimg.com/upload/vod/20240304-1/0f9ef2f9c8acbecb82c1e21caef011e9.jpg', '<p>Nhan Ninh là một cô gái không giỏi bày tỏ, tuy yêu đơn phương Thẩm Chấp Chu đã nhiều năm nhưng không thể đối mặt với sự từ chối, nên cô chọn cách trị liệu tâm lý để xóa bỏ cảm xúc của mình đối với Thẩm Chấp Chu. Thẩm Chấp Chu là một chàng trai không tin vào tình yêu, vì lo sợ sẽ mất đi người bạn thân nhất nên anh luôn trốn tránh tình cảm dành cho Nhan Ninh. Hai nhân vật của công chúng một lần nữa bị ràng buộc với nhau trong chương trình hẹn hò dành cho người nổi tiếng. Họ cùng nhau cố gắng và vượt qua nhiều trở ngại, đến cuối cùng nhận ra trốn tránh không phải là lựa chọn tốt nhất. Chỉ có dũng cảm đối mặt mới có thể mang lại hạnh phúc cho nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mông Ân","avatar":""},{"name":"Trình Kim Minh","avatar":""},{"name":"Lý Gia Hào","avatar":""},{"name":"Tống Tiêu Anh","avatar":""},{"name":"Tử Lưu","avatar":""},{"name":"Hinh Kỳ","avatar":""},{"name":"Thẩm Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324255);
