INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rung-dong-cua-nhan-chap', 'Rung Động Của Nhan Chấp', 'Yan Zhi''s Romantic Story', 'rung động của nhan chấp yan zhi''s romantic story mông ân trình kim minh lý gia hào tống tiêu anh tử lưu hinh kỳ thẩm vũ ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-hay-tro-thanh-nguoi-nha-cua-toi', 'Xin Hãy Trở Thành Người Nhà Của Tôi', 'Please Be My Family', 'https://phimimg.com/upload/vod/20240304-1/86a43b7673a17e971b36bb08fdb8c850.jpg', 'https://phimimg.com/upload/vod/20240304-1/24a52f56cc1aaee9af0440fc091fdfe5.jpg', '<p>Nó kể câu chuyện về những người đàn ông và phụ nữ sinh vào những năm 90, từ cuộc sống độc thân với con cái đến khi về chung một mái nhà. Để có chi phí phẫu thuật khối u não của con gái mình là Xuanxuan, Qi Sile cần giành được đơn đặt hàng trong dự án lập kế hoạch của Maolin, và quấy rầy Song Haoyu, ông chủ của Maolin. Và khi Song Haoyu đưa con trai Chenchen của mình đi chọn quà sinh nhật, anh ấy đã phát hiện ra Qi Sile có chiếc trâm cài giống Chenchen. Song Haoyu dần xác nhận mối quan hệ giữa Xuanxuan và Chenchen thông qua manh mối của chiếc trâm cài. Để hai đứa trẻ có một gia đình hạnh phúc, Song Haoyu đã cầu hôn Qi Sile, và cả hai bước vào một cuộc hôn nhân với một tương lai không chắc chắn.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trịnh Thu Hồng","avatar":""},{"name":"Tạ Bân Bân","avatar":""},{"name":"Chu Nguyên Băng","avatar":""},{"name":"Sheng Huizi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324255);
