INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ay-da-den', 'Người Ấy Đã Đến', 'The Real Has Come!', 'https://phimimg.com/upload/vod/20240304-1/406ef9dbb7a3efbec7431f8b0b83f66a.jpg', 'https://phimimg.com/upload/vod/20240304-1/410393a52c77f3b49983628379592a37.jpg', '<p>Phim kể về&nbsp;Yeon-Doo , một bà mẹ đơn thân và nuôi con một mình. Cô gặp một người đàn ông độc thân Tae-Kyung, người đã chọn sống độc thân. Tae-Kyung làm việc như một OB-GYN. Họ đồng ý bắt đầu một mối quan hệ giả tạo.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Baek Jin-hee","avatar":""},{"name":"Ahn Jae-hyun","avatar":""},{"name":"Cha Joo-young","avatar":""},{"name":"Jung Eui-jae","avatar":""},{"name":"Kang Boo-ja","avatar":""},{"name":"Hong Yo-seob","avatar":""},{"name":"Cha Hwa-yeon","avatar":""},{"name":"Kim Hye-ok","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Ryu Jin","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
