INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-than-gia-dinh', 'Tình Thân Gia Đình', 'Family: The Unbreakable Bond', 'https://phimimg.com/upload/vod/20240304-1/93f6ffaff64b1dd14db1c38959c4abd4.jpg', 'https://phimimg.com/upload/vod/20240304-1/58cc6d49267075b502305ba430a1c33e.jpg', '<p>Kwon Do Hoon là một tay bắn tỉa lão luyện và là một đặc vụ bí mật làm việc cho Cục Tình báo Quốc gia. Để che giấu danh tính thực sự của mình, anh ta sống một cuộc sống hai mặt với tư cách là một nhân viên công ty thương mại bình thường, thậm chí còn giấu kín vợ mình là Kang Yoo Ra. Dù bận rộn với công việc nhưng Kwon Do Hoon vẫn vô cùng yêu thương vợ mình. Trong khi đó, Kang Yoo Ra, một người nội trợ tận tụy, che giấu một bí mật. Sự tồn tại yên bình của họ bị xáo trộn khi Tae Koo xuất hiện, gây ra mối đe dọa cho vẻ bề ngoài được trau chuốt cẩn thận của họ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Jang Na-ra","avatar":""},{"name":"Chae Jung-an","avatar":""},{"name":"Kim Nam-hee","avatar":""},{"name":"Lee Soon-jae","avatar":""},{"name":"Kim Kang-min","avatar":""},{"name":"Yun Sang-jeong","avatar":""},{"name":"Gabee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
