INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-noi-doi-em', 'Đừng Nói Dối Em', 'My Lovely Liar', 'https://phimimg.com/upload/vod/20240304-1/4f3878885ad132178e7445e1fc979143.jpg', 'https://phimimg.com/upload/vod/20240304-1/cc5a7dcbbb977929ae31bc446cee6524.jpg', '<p>Nội dung xoanh quanh Mok Sol Hee, người phụ nữ có khả năng siêu nhiên có thể nghe thấy những lời nói dối. Cô có mối tình với người hàng xóm Kim Do Ha - một nhà sản xuất âm nhạc thiên tài đang phải che giấu danh tính của mình với thế giới vì một bí mật không thể nói ra. Liệu chuyện tình lãng mạn nhưng cũng không kém phần bí ẩn của cặp đôi này sẽ diễn ra như thế nào, mời các bạn cùng đón xem!</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim So-hyun","avatar":""},{"name":"Minhyun","avatar":""},{"name":"Seo Ji-hoon","avatar":""},{"name":"Lee Si-woo","avatar":""},{"name":"Yoon Ji-on","avatar":""},{"name":"Nam Hyun-woo","avatar":""},{"name":"Song Jin-woo","avatar":""},{"name":"Ha Jong-woo","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Jin Kyung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324255);
