INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-dinh-menh', 'Kho Báu Định Mệnh', 'Treasure Of Destiny', 'https://phimimg.com/upload/vod/20240304-1/d6e7a5671c644b66e9b1e56561f1a91d.jpg', 'https://phimimg.com/upload/vod/20240304-1/26d097c80288167a0a786fa7e60676e9.jpg', '<p>Năm xưa, vua Khang Hy vì sợ phá hoại long mạch nên không đào kho báu lên. Sau hơn 400 năm, kho báu vẫn bị chôn vùi dưới lòng đất. Bản đồ kho báu giấu trong quyển “42 chương kinh”. Sau khi một người chết đi, trí nhớ và tiềm năng của họ ở trạng thái năng lượng chưa xác định, tồn tại trong một vĩ độ nào đó của vũ trụ. Nếu cơ duyên trùng hợp kết nối với người nào đó, họ sẽ có được trí nhớ và tiềm năng của người xưa...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2023, 'Lồng tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Cung Gia Hân","avatar":""},{"name":"Trịnh Tử Thành","avatar":""},{"name":"Giang Gia Mẫn","avatar":""},{"name":"Trần Hào","avatar":""},{"name":"Châu Gia Lạc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324255);
