INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-do-dang', 'Trùng Đồ Đằng', 'Insect Totem', 'https://phimimg.com/upload/vod/20240304-1/64a92ea8b266889e34a7caf357cc9c3f.jpg', 'https://phimimg.com/upload/vod/20240304-1/463d09d767541b30b582ea1da7e52f96.jpg', '<p>Ở thời Dân Quốc, danh y Phan Tuấn của Trùng Thảo Đường và hậu duệ của năm đại gia tộc Trùng tộc gặp gỡ nhau, biết được manh mối của tổ tiên liên quan đến kho báu Trùng tộc, từ đó dấn thân vào hành trình tìm kiếm báu vật gia tộc để lại. Họ bầu bạn với nhau, cùng tìm kiếm báu vật của năm tộc để có thể khởi động kho báu. Suốt thời gian này, họ ngao du qua các nơi, tìm tòi bí mật về tổ tiên, chống lại dịch bệnh và sự bất công trên đường đi. Khi càng lúc càng đến gần kho báu thì lại bị thế lực của kẻ trộm kho báu tấn công, nhờ đó đã vạch trần chân tướng vụ tranh đoạt kho báu 20 năm về trước. Từ khát vọng làm giàu ban đầu, họ cũng dần dần gánh vác sứ mệnh bảo vệ kho báu quốc gia, nhiều lần giằng co với kẻ trộm kho báu, cuối cùng đập tan lòng tham của đối phương, khiến kho báu Trùng tộc trong truyền thuyết lại một lần nữa được nhìn thấy ánh sáng. Trong quá trình đó, họ học được cách hợp tác tập thể, xây dựng tình bạn sâu sắc và phát triển thành tình yêu trong sáng, từ thiếu niên ngây ngô trở thành anh hùng có tinh thần trách nhiệm.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Ming''en","avatar":""},{"name":"Hu Bingqing","avatar":""},{"name":"Aly","avatar":""},{"name":"Lv Yunfeng","avatar":""},{"name":"Zhang Jiading","avatar":""},{"name":"Ding Xiangnan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324255);
