INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ay-vuot-nui-song-ma-den', 'Anh Ấy Vượt Núi Sông Mà Đến', 'I Belonged To Your World', 'https://phimimg.com/upload/vod/20240302-1/09aca88ee7df142ad519e6dd4875f66e.jpg', 'https://phimimg.com/upload/vod/20240302-1/ce4acf1759d315839263bd2bf4dd3ba5.jpg', '<p>Anh Ấy Vượt Núi Sông Mà Đến - I Belonged To Your World kể về Qi Yue, một cô gái trẻ không có tham vọng. Một ngày nọ, cô bất ngờ nhận được lời cảnh báo về cuộc sống tương lai của mình từ con trai Qi Shuo. Kể từ đó, cô buộc phải bắt tay vào kế hoạch làm lại cuộc đời. Trong khi cố gắng cải thiện bản thân, với sự hỗ trợ của Qi Shuo, họ cố gắng thu hút sự chú ý và tình yêu của Lu Xia, một học giả thông minh nhưng lạnh lùng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Nghiễn Địch","avatar":""},{"name":"Lưu Di Đồng","avatar":""},{"name":"Ngô Địch Phi","avatar":""},{"name":"Diệp Khả Nhi","avatar":""},{"name":"Thái Hân Dương","avatar":""},{"name":"Lưu Giai","avatar":""},{"name":"Trần Mỹ Lâm","avatar":""},{"name":"Trương Chương","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324255);
