INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-nao', 'Cân Não', 'Brain Works', 'https://phimimg.com/upload/vod/20240229-1/ce0a4c57e893d1e9c6da892a23f0f57e.jpg', 'https://phimimg.com/upload/vod/20240229-1/f511b511d98c07144099a963b581c8a1.jpg', '<p>Shin Ha Ru làm việc như một nhà thần kinh học. Anh ấy xuất thân từ một gia đình đã làm bác sĩ trong 3 thế hệ và anh ấy giàu có nhờ tài sản được thừa kế. Shin Ha Ru là một người tự tin, hành động và nói theo niềm tin của mình, nhưng anh ta không thương xót những người mà anh ta coi là cặn bã. Geum Myung Se làm thám tử. Anh ta hành động và nói năng cáu kỉnh với mọi người, điều này khiến những người không quen biết anh ta cho rằng anh ta có thể là một cảnh sát tham nhũng. Trên thực tế, Geum Myung Se là một thám tử tốt bụng và chính trực. Anh cũng từng kết hôn với Kim Mo Ran. Cô ấy có ham muốn tình dục đặc biệt mạnh mẽ. Shin Ha Ru và Geum Myung Se cùng nhau giải quyết các vụ án hình sự với sự giúp đỡ của Điều tra viên thôi miên Seol So Jung.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Yong Hwa","avatar":""},{"name":"Cha Tae Hyun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
