INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-keo-noi-dau', 'Giao Kèo Nỗi Đau', 'Pain Hustlers', 'https://phimimg.com/upload/vod/20240228-1/39b3bad6e13b1cc512c333764017520c.jpg', 'https://phimimg.com/upload/vod/20240228-1/3cac1366c1cd9bf53dab6723fd89a286.jpg', '<p>Nghèo nhưng tham vọng, người mẹ đơn thân nọ có cơ hội béo bở trong việc bán dược phẩm. Nhưng cô sẽ sẵn sàng làm những gì để loại thuốc giảm đau mới cực mạnh trở nên thành công?</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Blunt","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Andy García","avatar":""},{"name":"Brian d''Arcy James","avatar":""},{"name":"Chloe Coleman","avatar":""},{"name":"Amit Shah","avatar":""},{"name":"Britt Rentschler","avatar":""},{"name":"Selena Anduze","avatar":""},{"name":"Erin Ownbey","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
