INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('praise-this', 'Praise This', 'Praise This', 'https://phimimg.com/upload/vod/20240228-1/7eb5765636418970799fe0a9c441ed75.jpg', 'https://phimimg.com/upload/vod/20240228-1/15c29611e02866dd4e657ab226b66ca3.jpg', '<p>Khi siêu sao âm nhạc đầy tham vọng Sam bị buộc phải gia nhập đội ca ngợi đang gặp khó khăn, kém cỏi của anh họ mình để chuẩn bị cho một cuộc thi vô địch quốc gia, cô nhận thấy cơ hội để biến ước mơ của mình thành hiện thực.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chloe Bailey","avatar":""},{"name":"Anjelika Washington","avatar":""},{"name":"Druski","avatar":""},{"name":"Birgundi Baker","avatar":""},{"name":"Jekalyn Carr","avatar":""},{"name":"Quavo","avatar":""},{"name":"Tristan Mack Wilds","avatar":""},{"name":"Loren Lott","avatar":""},{"name":"Kiara Iman","avatar":""},{"name":"Ilario Grant","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324255);
