INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-giam-ho', 'Kẻ Giám Hộ', 'A Man Of Reason', 'https://phimimg.com/upload/vod/20240228-1/7cc61880eebc321efb8c6dc32d1ed8f8.jpg', 'https://phimimg.com/upload/vod/20240228-1/c2e34f86c66ff1d29ca90ec485df60a1.jpg', '<p>Sau 10 năm bị giam giữ thay mặt cho người chủ của mình, tất cả những gì Su-hyuk mong muốn là một cuộc sống bình thường - cuộc sống mà anh hy vọng sẽ có bạn gái cũ của mình, Min-seo, và con gái của họ, In-bi. Nhưng một khi bạn đã thâm nhập vào tầng lớp cao hơn của thế giới ngầm, điều bình thường có thể khó đạt được. Trong khi đó, trong thập kỷ qua, ông chủ của Su-hyuk đã tỏ ra hợp pháp. Ngày nay, băng đảng cũ trộm cắp và giết người dưới danh nghĩa phát triển đô thị. Và họ muốn Su-hyuk bất đắc dĩ tham gia.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 1, '[{"name":"Jung Woo-sung","avatar":""},{"name":"Kim Nam-gil","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Kim Jun-han","avatar":""},{"name":"Park You-na","avatar":""},{"name":"Lee Elijah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324255);
