INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dead-mans-hand', 'Dead Man''s Hand', 'Dead Man''s Hand', 'https://phimimg.com/upload/vod/20240228-1/c455e3626b51696971a3940132d194cb.jpg', 'https://phimimg.com/upload/vod/20240228-1/715fae50728c7859e137b4800996b639.jpg', '<p>Một tay súng mới kết hôn tìm kiếm một cuộc sống bình lặng với cô dâu của mình. Khi anh giết một tên cướp để tự vệ, anh thấy cả hai đều quay lại con đường cũ của mình. Thị trưởng tham nhũng của địa phương sẽ không để cái chết của anh trai mình không bị trừng phạt.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Dorff","avatar":""},{"name":"Jack Kilmer","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Camille Collard","avatar":""},{"name":"Mo Brings Plenty","avatar":""},{"name":"Forrie J. Smith","avatar":""},{"name":"Randall Batinkoff","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324255);
