INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-westward-the-kingdom-of-shadow', 'The Westward: The Kingdom Of Shadow', 'The Westward: The Kingdom Of Shadow', 'https://phimimg.com/upload/vod/20240228-1/85bbe04996ea55e7e991d083de5de6aa.jpg', 'https://phimimg.com/upload/vod/20240228-1/9bdf053e653e83129905beb1c25529cb.jpg', '<p>The Westward: Shadow City kể câu chuyện rằng để điều khiển Tang Sanzang chiếm lấy ngọn lửa vĩnh cửu, Moying, chúa tể của Shadow City, đã sử dụng khả năng của thành phố ma thuật để thỏa mãn mọi ham muốn nhằm thu hút trái tim của Tang Sanzang. Cuối cùng, Đường Tam Tạng đã vượt qua được nội tâm ma quỷ và thức tỉnh trở lại. Anh và những người học việc của mình đã hợp lực để đánh bại Moying, giải tán thành phố tà ác vốn là phe ác và lại bắt tay vào hành trình cứu những người dân thường trên thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324255);
