INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-muon-duong-am-binh', 'Địch Nhân Kiệt: Mượn Đường Âm Binh', 'Di Renjie Secret Soldier Borrows The Road', 'https://phimimg.com/upload/vod/20240228-1/bed9c00f5246b24931ad161c091e3af0.jpg', 'https://phimimg.com/upload/vod/20240228-1/a22dd44f76b55419968b8c6166e9141e.jpg', '<p>Vào thời Ngô Chu, gia đình của Hồ Hiển Đức bị giết hại, Võ Tắc Thiên đã ra lệnh cho Địch Nhân Kiệt điều tra. Cuộc điều tra của Địch Nhân Kiệt phát hiện ra rằng Hồ Hiển Đức, người vốn là người trung thực và có trách nhiệm, lại có liên quan một cách kỳ lạ đến một vụ án lớn, Địch Nhân Kiệt không khỏi nghi ngờ và nhận ra rằng vụ án này có thể là một vụ án trong một vụ án. Trong quá trình điều tra vụ án, Địch Nhân Kiệt liên tục gặp phải nhiều sự việc kỳ lạ khác nhau, những người liên quan đến vụ án cũng lần lượt chết một cách bí ẩn. Khi những có những người đòi lấy mạng sống của họ, vụ án rơi vào bế tắc và Địch Nhân Kiệt bị bao phủ trong một âm mưu lớn...</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Mark.DU","avatar":""},{"name":"Du Yi Heng","avatar":""},{"name":"Li Ruo Xi","avatar":""},{"name":"Lai Xi","avatar":""},{"name":"Shi Xuan Ru","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
