INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-vuong-trung-coc', 'Hiến Vương Trùng Cốc', 'The Worm Valley', 'https://phimimg.com/upload/vod/20240228-1/c21d5264a6b4edc4ab0683220867071d.jpg', 'https://phimimg.com/upload/vod/20240228-1/d0cdc317695098665ec6efb58f0394a7.jpg', '<p>Hồ Bát Nhất, Tuyết Lê Dương và Vương Khải Toàn để thoát khỏi lời nguyền ban đỏ, không ngờ đã gây ra việc rò rỉ một loại khói độc, đặt mạng sống của người dân vô tội trong các bộ lạc vào nguy hiểm. Trong nửa năm tiếp theo, Hồ Bát Nhất và Vương Khải Toàn phải vật lộn với những khó khăn khi sống lưu vong ở Đông Nam Á và bắt đầu phát sinh bất đồng trong việc tìm kiếm viên ngọc Mộ Trần. Không ngờ, Vương Khải Toàn vô tình gây rắc rối, Hồ Bát Nhất và Tuyết Lê Dương không thể làm ngơ trước tình hình này, đã quyết định đến lăng Thiên Vương Thánh Tiên để cứu Vương Khải Toàn về.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Luo Li Qun","avatar":""},{"name":"Zhang Wei Wei","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
