INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-thu-dam-mau', 'Hận Thù Đẫm Máu', 'Vindicta', 'https://phimimg.com/upload/vod/20240228-1/75d7faafe4f8014deb04961f71163b9d.jpg', 'https://phimimg.com/upload/vod/20240228-1/ff3046ebde87ec575abf0ab66a90767d.jpg', '<p>Bộ phim kể về một thành phố đang bị kinh sợ bởi một tên sát nhân hàng loạt tàn bạo. Một thám tử có kinh nghiệm cùng một nhân viên cấp cứu mới gia nhập phát hiện ra rằng chìa khóa để ngăn chặn sự đổ máu nằm trong việc làm sáng tỏ sự thật về quá khứ đầy ám ảnh của họ. Trong quá trình đấu tranh với tội ác, họ phải đối mặt với những vấn đề cá nhân, từ gánh nặng từ mất mát đau lòng đến quan hệ phức tạp với gia đình.<br/>Những chi tiết cụ thể như vụ giết cặp thanh tra cứu hỏa, nỗi ám ảnh về việc mẹ của Lou qua đời, và mối quan hệ đặc biệt giữa cô với cha mình, Patrick, tất cả đều tạo nên bức tranh phức tạp của bộ phim Vindicta.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michasha Armstrong","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Jaime M. Callica","avatar":""},{"name":"Karolina Cubitt","avatar":""},{"name":"Daniel Cudmore","avatar":""},{"name":"Elena Kampouris","avatar":""},{"name":"Travis Nelson","avatar":""},{"name":"Adam Pateman","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Bradley Stryker","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324256);
