INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-tuyet-vong', 'Con Đường Tuyệt Vọng', 'Desperation Road', 'https://phimimg.com/upload/vod/20240228-1/4ad6b3145cba0b940485f901d49ae6f5.jpg', 'https://phimimg.com/upload/vod/20240228-1/76f9927558ef3d23af8d907f51616773.jpg', '<p>Trong một thị trấn nhỏ ở Mississippi, công lý và luật pháp không phải lúc nào cũng đi đôi với nhau. Một bộ phim hình sự Noir phương Nam đưa người xem vào một thị trấn nơi mà rượu whiskey, súng, và mong muốn trả thù giao nhau một cách bạo lực. Câu chuyện tập trung vào một người phụ nữ và con gái nhỏ của cô, họ đang bị cuốn vào tâm điểm của cuộc xung đột. Hai linh hồn lạc lối, bị hành hạ bởi quá khứ đau thương, và ràng buộc bởi một bí mật khiến họ phải chạy trốn. Với sự tham gia của các diễn viên như Mel Gibson, Garret Hedlund, và Willa Fitzgerald, bộ phim này hứa hẹn sẽ mang đến cho khán giả những trải nghiệm đầy căng thẳng và bí ẩn.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Garrett Hedlund","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Ryan Hurst","avatar":""},{"name":"Willa Fitzgerald","avatar":""},{"name":"Ella Thomas","avatar":""},{"name":"Woody McClain","avatar":""},{"name":"Kat Foster","avatar":""},{"name":"Michael Aaron Milligan","avatar":""},{"name":"Paulina Gálvez","avatar":""},{"name":"Katy Bodenhamer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
