INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-duyen-tien-dinh', 'Nhân Duyên Tiền Đình', 'Honeysweet', 'https://phimimg.com/upload/vod/20240228-1/6026fd5c55d3296db6f87c8a451fa92d.jpg', 'https://phimimg.com/upload/vod/20240228-1/13c4f5f270beadec1d83fcd24c5ca28c.jpg', '<p>Chuyện phim xoay quanh nhân vật Chi-ho (Yoo Hae-jin) - nhà nghiên cứu bim bim với khả năng nếm vị xuất chúng, nhưng lại ngờ nghệch với mọi thứ xung quanh. Chi-ho là một người cực kỳ hướng nội, thích ở một mình và sống như một cái máy được lập trình sẵn mà không hề mắc lỗi dù chỉ một giây. Trong lúc phải đi trả nợ thay cho người anh trai cờ bạc (Cha In-pyo), Chi-ho đã gặp gỡ “nhân viên đòi nợ” Il-young - người phụ nữ hướng ngoại, luôn suy nghĩ tích cực về cuộc sống dù đang ở trong hoàn cảnh khó khăn của một bà mẹ đơn thân. Khác biệt về tính cách lẫn ngoại hình khiến cả hai trở thành “trái dấu hút nhau”. Sự “trái dấu” này đã đẩy đưa cuộc tình của họ đến vô vàn tình huống “cười ra nước mắt” nhưng cũng không kém phần cảm xúc.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 1, '[{"name":"Yoo Hae-jin","avatar":""},{"name":"Kim Hee-seon","avatar":""},{"name":"Cha In-pyo","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Han Seon-hwa","avatar":""},{"name":"Jeong Da-eun","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Lee Ji-hun","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Kim Seo-hyeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324256);
