INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-hoan', 'Tẫn Hoan', 'Tea of Destiny', 'https://phimimg.com/upload/vod/20240305-1/ed90b8dfc548ca549d6762c6a917ed65.jpg', 'https://phimimg.com/upload/vod/20240305-1/9b0b7e06d8e7d557df4ec74a07f3fa0f.jpg', '<p>Nữ hiệp giang hồ Tịnh Thất Nhi vì cứu cha nuôi bị “bệnh nặng” đã xuống núi tới hiệu trà Vong Ưu tìm một loại thần dược có tên đan Quy Nguyên. Nàng đã gặp các chủ Huyễn Vân Hoa của Vân Sơn các, hắn cải trang thành thiếu trang chủ đã mất tích nhiều năm của hiệu trà định cướp sạch nơi đây. Hai người giả làm phu thê, rồi bị cuốn vào mối ân oán nhiều năm trước, run rủi thế nào lại chấn hưng lại danh tiếng hiệu trà và phải lòng lẫn nhau. Giang hồ rộng lớn, vậy mà hạnh phúc và niềm vui lại dễ dàng đến vậy.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jia Ze","avatar":""},{"name":"Li Peien","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
