INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-qua-net-co', 'Đời Qua Nét Cọ', 'Paint', 'https://phimimg.com/upload/vod/20240228-1/01435b80c08759ae9abaaf3df8edc52c.jpg', 'https://phimimg.com/upload/vod/20240228-1/a05ce794f6d5d288c35cba708806cad7.jpg', '<p>Carl Nargle, họa sĩ truyền hình công cộng số 1 của Vermont, tin chắc rằng anh ta có tất cả: một mái tóc uốn đặc trưng, một chiếc xe tải tùy chỉnh và những chiếc quạt treo trên mỗi nét vẽ của anh ta… cho đến khi một nghệ sĩ trẻ hơn, giỏi hơn đánh cắp mọi thứ (và tất cả mọi người) mà Carl yêu thích.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Michaela Watkins","avatar":""},{"name":"Wendi McLendon-Covey","avatar":""},{"name":"Ciara Renée","avatar":""},{"name":"Lusia Strus","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Lucy Freyer","avatar":""},{"name":"Denny Dillon","avatar":""},{"name":"Evander Duck Jr.","avatar":""},{"name":"Elisabeth Henry-Macari","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
