INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-dai-de', 'Chiến Dịch Đại Đế', 'Operation Napoleon', 'https://phimimg.com/upload/vod/20240228-1/dd5eac606eeaccdf6b02f53c2f9ecacc.jpg', 'https://phimimg.com/upload/vod/20240228-1/3ef3fd3efb919b41e555aa9b48fd3ed7.jpg', '<p>Một luật sư thời hiện đại bị cuốn vào một âm mưu quốc tế sau khi bị buộc tội giết người mà cô không phạm tội. Cơ hội tự do duy nhất của cô nằm ở việc khám phá bí mật về một chiếc máy bay cũ của Đức trong Thế chiến II, bị chôn sâu dưới lớp băng từ lâu, trước CIA.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Vivian Ólafsdóttir","avatar":""},{"name":"Jack Fox","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Wotan Wilke Möhring","avatar":""},{"name":"Ólafur Darri Ólafsson","avatar":""},{"name":"Atli Óskar Fjalarsson","avatar":""},{"name":"Þröstur Leó Gunnarsson","avatar":""},{"name":"Nanna Kristín Magnúsdóttir","avatar":""},{"name":"Jaymes Butler","avatar":""},{"name":"Sabine Crossen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324256);
