INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-burial', 'The Burial', 'The Burial', 'https://phimimg.com/upload/vod/20240228-1/aa227e5b7703ba0a145c5533c85064d4.jpg', 'https://phimimg.com/upload/vod/20240228-1/a9d62abace15da4a33705a97b7bace3b.jpg', '<p>Lấy cảm hứng từ những sự kiện có thật, khi thỏa thuận bắt tay trở nên tồi tệ, chủ nhà tang lễ Jeremiah OKeefe (Tommy Lee Jones) đã nhờ luật sư lôi cuốn, ăn nói trôi chảy Willie E. Gary (Jamie Foxx) để cứu công việc kinh doanh của gia đình mình. Sự nóng nảy và tiếng cười xảy ra sau đó khi cặp đôi khó có thể gắn kết đồng thời vạch trần nạn tham nhũng trong công ty và sự bất công về chủng tộc trong câu chuyện đầy cảm hứng và chiến thắng này.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Foxx","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Alan Ruck","avatar":""},{"name":"Jurnee Smollett","avatar":""},{"name":"Mamoudou Athie","avatar":""},{"name":"Pamela Reed","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Amanda Warren","avatar":""},{"name":"Dorian Missick","avatar":""},{"name":"Teisha Speight","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
