INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dark-harvest', 'Dark Harvest', 'Dark Harvest', 'https://phimimg.com/upload/vod/20240228-1/375062281299db800c6d249d61f6aa94.jpg', 'https://phimimg.com/upload/vod/20240228-1/638b73a3e885d93009b7802a6353c86c.jpg', '<p>Tại một thị trấn bị nguyền rủa, vụ thu hoạch hàng năm trở thành một cuộc chiến sinh tồn tàn khốc. Vào Halloween năm 1963, Sawtooth Jack, một huyền thoại đáng sợ, trỗi dậy từ cánh đồng ngô, đe dọa trẻ em trong thị trấn. Các nhóm nam sinh đoàn kết để đánh bại tên bù nhìn sát nhân trước nửa đêm. Richie, một kẻ nổi loạn bị ruồng bỏ, tham gia cuộc chạy trốn, được thúc đẩy bởi chiến thắng trước đó của anh trai mình. Khi cuộc săn tiến triển, Richie có một phát hiện gây sốc và phải đối mặt với lựa chọn then chốt nhằm phá vỡ vòng luẩn quẩn không ngừng nghỉ.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Casey Likes","avatar":""},{"name":"Luke Kirby","avatar":""},{"name":"Jeremy Davies","avatar":""},{"name":"Elizabeth Reaser","avatar":""},{"name":"Emyri Crutchfield","avatar":""},{"name":"Megan Best","avatar":""},{"name":"Jake Brennan","avatar":""},{"name":"Britain Dalton","avatar":""},{"name":"Dustin Ceithamer","avatar":""},{"name":"Ezra Buzzington","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
