INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-xua-co-mot-ngoi-sao', 'Ngày Xưa Có Một Ngôi Sao', 'Once Upon A Star', 'https://phimimg.com/upload/vod/20240228-1/f05595a901286f31ce5d517ea7ac4e6a.jpg', 'https://phimimg.com/upload/vod/20240228-1/3e714ae4e0089ba93811fbd7666fad1f.jpg', '<p>Năm 1970, đoàn chiếu phim nọ đối mặt với vô số trở ngại khi họ đi khắp Thái Lan để giải trí cho khán giả háo hức bằng cách lồng tiếng trực tiếp cho những bộ phim được yêu thích.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Sukollawat Kanaros","avatar":""},{"name":"Nuengthida Sophon","avatar":""},{"name":"Jirayu Laongmanee","avatar":""},{"name":"Samart Payakaroon","avatar":""},{"name":"Nat Sakdatorn","avatar":""},{"name":"Sornchai Chatwiriyachai","avatar":""},{"name":"Pattamamontri Siriwet","avatar":""},{"name":"Phennee Sasithanasophon","avatar":""},{"name":"Yuthana Boonorm","avatar":""},{"name":"Kongkiat Komesiri","avatar":""},{"name":"Karinyut Jindawat","avatar":""},{"name":"Komsan Kajornpaisansuk","avatar":""},{"name":"Varatta Vaj","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
