INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-anh-thi-giac', 'Ảo Ảnh Thị Giác', 'Awareness', 'https://phimimg.com/upload/vod/20240228-1/84d8817e8757e56b2f78497769fc5d1c.jpg', 'https://phimimg.com/upload/vod/20240228-1/1793227ec3a769a65f039a7ac6fbdf7e.jpg', '<p>Ian là một thiếu niên sống với cha mình ở vùng ngoại ô bằng cách thực hiện các vụ lừa đảo nhỏ bằng cách sử dụng khả năng tạo ra ảo ảnh thị giác của Ian đối với những nạn nhân không nghi ngờ. Khi một trong những khuyết điểm của anh gặp vấn đề, khả năng của anh công khai vượt khỏi tầm kiểm soát và Ian trở thành mục tiêu của hai tổ chức đối thủ, mỗi tổ chức đều tìm cách khai thác sức mạnh của anh.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Carlos Scholz","avatar":""},{"name":"Pedro Alonso","avatar":""},{"name":"María Pedraza","avatar":""},{"name":"Óscar Jaenada","avatar":""},{"name":"Lela Loren","avatar":""},{"name":"Lucas Fuica","avatar":""},{"name":"Silvia Kal","avatar":""},{"name":"Karina Kolokolchykova","avatar":""},{"name":"María Mercado","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
