INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('domme', 'Domme', 'Domme', 'https://phimimg.com/upload/vod/20240228-1/1e13eab557a1791709c8fc9a56ed8164.jpg', 'https://phimimg.com/upload/vod/20240228-1/018b4eaafb7aab38bd92d69fbd5ba8f5.jpg', '<p>Một người đàn ông theo dõi hàng xóm của mình vì tiếng ồn mà họ tạo ra hàng đêm. Nhưng anh ấy phát hiện ra rằng họ thực hiện những hành vi khiêu dâm hoang dã. Khi anh ta can thiệp vào công việc kinh doanh của họ, anh ta càng can thiệp vào cuộc sống và mớ hỗn độn của họ.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Ava Mendez","avatar":""},{"name":"Ali Asistio","avatar":""},{"name":"Mark Anthony Fernandez","avatar":""},{"name":"Marco Gomez","avatar":""},{"name":"Ada Hermosa","avatar":""},{"name":"Audrey Avila","avatar":""},{"name":"Irene Tiru","avatar":""},{"name":"Jet Delgado","avatar":""},{"name":"Maica Manabat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
