INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-tay-quy-an', 'Tương Tây Quỷ Án', 'Strange Things In Western Hunan', 'https://phimimg.com/upload/vod/20240228-1/25dcc2ee82c96aa79da82b4a946cb570.jpg', 'https://phimimg.com/upload/vod/20240228-1/5da904ca19c20519f7fafd6216b449b2.jpg', '<p>Người dân Tương Tây yêu quê hương và có tục lệ đưa lá rụng về cội, cùng với địa lý địa phương hiểm trở, điều này đã làm nảy sinh nghề săn xác chết. Long Thất và đồ đệ Long Bình An là những người săn xác chết nổi tiếng ở thị trấn địa phương. Hai mươi năm trước, Long Thất gặp phải tình huống đáng sợ nhất khi làm nghề. Hai mươi năm sau, với sự xuất hiện của một xác chết không đầu, một loạt sự kiện kỳ lạ bắt đầu xảy ra trong thị trấn, và đáng ngạc nhiên là những sự kiện này có liên quan đến những gì Long Thất đã trải qua hai mươi năm trước...</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Jun Xi","avatar":""},{"name":"Norman Chui","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
