INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-an-mang-bi-an-phan-1', 'Vụ Án Mạng Bí Ẩn Phần 1', 'Murder Mystery', 'https://phimimg.com/upload/vod/20240228-1/65c4cf955c3392e77163cb20d5bd729b.jpg', 'https://phimimg.com/upload/vod/20240228-1/fd533deed0d4ee101b26762976aa7531.jpg', '<p>Tần Dũng được lệnh điều tra vụ án phân xác bi thảm, sự thật dần lộ ra trong quá trình rà soát và điều tra tội phạm, sự xấu xa và tình yêu của từng nghi phạm hình sự đã khiến toàn bộ vụ án trở nên phức tạp, sự thật mờ nhạt và những cảm xúc đằng sau đó khiến mọi người sững sờ</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guo Jiahao","avatar":""},{"name":"Zhang Sheng Peng","avatar":""},{"name":"Tao Hui Na","avatar":""},{"name":"Ding Yong Dai","avatar":""},{"name":"Hou Rui Xiang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
