INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kitty-the-killer', 'Kitty The Killer', 'Kitty The Killer', 'https://phimimg.com/upload/vod/20240228-1/b9faeb14a280020a08f4f99ec0370da1.jpg', 'https://phimimg.com/upload/vod/20240228-1/9eb0ed60b9a03709f1004a372a27b5af.jpg', '<p>Một tổ chức gián điệp ngầm có tên The Agency tuyển dụng một liên minh gồm các nữ sát thủ hàng đầu được biết đến với mật danh Kitty để thực hiện công việc bẩn thỉu của họ. Khi người cố vấn của Kitties, The Grey Fox, bị The Agency phản bội và bị đưa ra án tử hình, anh ta đã tuyển một nhân viên văn phòng trẻ ngốc nghếch thế chỗ. Chàng trai mới vào nghề nhai khung cảnh khi biến đổi từ số 0 thành anh hùng dưới sự huấn luyện khắc nghiệt đến mức tàn bạo của những chú Mèo con lạnh lùng như băng. Nhiệm vụ tiếp theo của họ? Để trả thù những kẻ vượt biên đôi! Được xây dựng dựa trên logic truyện tranh với giọng nói chắc chắn, bộ phim hài hành động hỗn loạn này là một sự châm biếm sôi nổi về những câu chuyện ngụ ngôn và tài liệu tham khảo về thể loại phim châu Á được kết hợp một cách hoa mỹ với khiếu hài hước náo loạn của Thái Lan để có một khoảng thời gian vui vẻ.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ploypailin Thangprapaporn","avatar":""},{"name":"Denkhun Ngamnet","avatar":""},{"name":"Somchai Kemglad","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Keetapat Pongruea","avatar":""},{"name":"Sutina Laoamnuaichai","avatar":""},{"name":"Pat Chatburirak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324256);
