INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('organ-trail', 'Organ Trail', 'Organ Trail', 'https://phimimg.com/upload/vod/20240228-1/99bc42229c1de23012c1b27d13881198.jpg', 'https://phimimg.com/upload/vod/20240228-1/b8b4bb87f8e1b59b04ed9c4d2719183e.jpg', '<p>Abigale Archer trẻ tuổi không có bạn bè và cô đơn trong mùa đông tàn khốc ở Montana vào những năm 1870—chiến đấu để sinh tồn và giành lại vật sở hữu trần thế duy nhất của mình, con ngựa của gia đình cô, từ một băng cướp khát máu.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zoé De Grand Maison","avatar":""},{"name":"Nicholas Logan","avatar":""},{"name":"Olivia Grace Applegate","avatar":""},{"name":"Michael Abbott Jr.","avatar":""},{"name":"Jessica Frances Dukes","avatar":""},{"name":"Clé Bennett","avatar":""},{"name":"Sam Trammell","avatar":""},{"name":"Alejandro Akara","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324256);
