INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('carmen', 'Carmen', 'Carmen', 'https://phimimg.com/upload/vod/20240228-1/d220af67e0930cce91a00469a62ebac3.jpg', 'https://phimimg.com/upload/vod/20240228-1/8c647ead124d6e03badcb6ab05159746.jpg', '<p>Một phụ nữ trẻ và độc lập quyết liệt, Carmen, buộc phải chạy trốn khỏi nhà ở sa mạc Mexico sau vụ sát hại dã man mẹ cô. Cô sống sót sau một cuộc vượt biên trái phép vào Mỹ, chỉ để đối mặt với một người lính biên phòng tình nguyện vô luật pháp. Khi người lính biên phòng và người đồng đội tuần tra Aidan của anh ta bị lôi kéo vào một cuộc đối đầu chết người, cả hai buộc phải cùng nhau trốn thoát.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Melissa Barrera","avatar":""},{"name":"Paul Mescal","avatar":""},{"name":"Rossy de Palma","avatar":""},{"name":"Elsa Pataky","avatar":""},{"name":"Nicole da Silva","avatar":""},{"name":"Tara Morice","avatar":""},{"name":"Benedict Hardie","avatar":""},{"name":"Kaan Guldur","avatar":""},{"name":"Pip Edwards","avatar":""},{"name":"Nico Cortez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324256);
