INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-buon-lau', 'Những Kẻ Buôn Lậu', 'Smugglers', 'https://phimimg.com/upload/vod/20240228-1/7c8ef727cc0ae09fffca45b063314288.jpg', 'https://phimimg.com/upload/vod/20240228-1/e2a2690984b445b2512424da70bb8bf9.jpg', '<p>Lấy bối cảnh những năm 1970, một hoạt động buôn lậu diễn ra tại một ngôi làng nhỏ yên bình bên bờ biển. Những người liên quan đến hoạt động buôn lậu là Chun-ja, người làm nghề buôn lậu để kiếm sống, bạn của cô, Jin-suk, người lãnh đạo một nhóm nữ thợ lặn và Thượng sĩ Kwon. Thượng sĩ Kwon là vua buôn lậu trên toàn quốc.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hye-soo","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Zo In-sung","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Go Min-si","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Park Jun-myun","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Joo Bo-bi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324256);
