INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-kich-vung-tu-dia', 'Đột Kích Vùng Tử Địa', 'Raid On The Lethal Zone', 'https://phimimg.com/upload/vod/20240228-1/fda6441cedc83b6206f493848a76ab08.jpg', 'https://phimimg.com/upload/vod/20240228-1/eb3e59ee4142b6a9025ca132805a5ab8.jpg', '<p>Biên giới Tây Nam của Trung Quốc vào cuối những năm 1990, đội quân đặc công 8077 của biên phòng quân và công an gặp phải một loạt biến cố trong nhiệm vụ tiêu diệt ma túy. Họ phải đối mặt với lũ lụt và âm mưu của bọn buôn ma túy, gây ra nhiều thương vong. Để tưởng nhớ đồng đội đã hi sinh, những người sống sót trong đội 8077 quyết tâm tiến hành một cuộc truy sát cuối cùng, thậm chí bằng cả tính mạng của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Âu Hào","avatar":""},{"name":"Cốc Gia Thành","avatar":""},{"name":"Ham Yu","avatar":""},{"name":"Runa Ke","avatar":""},{"name":"Hoàng Nghiêu","avatar":""},{"name":"Gao Zhi Ting","avatar":""},{"name":"Wang Yutian","avatar":""},{"name":"Sử Bàng Nguyên","avatar":""},{"name":"Xueming Jiang","avatar":""},{"name":"Liu Jun Qi","avatar":""},{"name":"Dong Bo Rui","avatar":""},{"name":"Chen Tian Ming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324256);
