INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-thien-thu-tuong-quan-khong-dau', 'Thiết Thiên Thư: Tướng Quân Không Đầu', 'Headless General', 'https://phimimg.com/upload/vod/20240228-1/e70c181f6db144fb8038d88531709b43.jpg', 'https://phimimg.com/upload/vod/20240228-1/d5f0dfc26ee80f9bceb6a683d784d29c.jpg', '<p>Người chỉ huy đội quân Lang Vệ dưới sự lãnh đạo của A Cốc Lực thèm muốn khám phá kho báu của Gia Tộc Thiên Nhạc và người đẹp nhất thiên hạ - Sử Thiên Kiều, đặt ra mục tiêu chiếm Thành Lưu Lạc để tìm kiếm họ. Tướng quân bảo vệ thành phố, Sử Vạn Phu, bất lực trước sự tấn công của đối thủ nên để cứu dân trong thành và con gái của mình, Sử Thiên Kiều, ông đã tham mưu cùng với người bạn tốt của mình, Tiêu Bất Bình, và sử dụng cuốn sách Thiết Thiên Thư</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jin Song","avatar":""},{"name":"Ma Shuai","avatar":""},{"name":"Jiang Rui Ze","avatar":""},{"name":"Zhou Xiao Chuan","avatar":""},{"name":"Wang Chen Xin","avatar":""},{"name":"Hanson","avatar":""},{"name":"Lou Yun Fei","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
