INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-kiem-an-cuu-luc', 'Thư Kiếm Ân Cừu Lục', 'Shujian Enchoulu', 'https://phimimg.com/upload/vod/20240228-1/62e273d1059d9a2960dcef50bd9e6b5f.jpg', 'https://phimimg.com/upload/vod/20240228-1/31e43a5f2ce370ff08dabda11c26e037.jpg', '<p>Nhà Thanh nămi Càn Long, Đà chủ của Hội Hồng Hoa – Dư Vạn Đình lâm trọng bệnh mà mất, đưa con trai Trần Gia Lạc lên nắm quyền thay thế. Trần Gia Lạc mới chập chững vào giang hồ thì hay tin các phân đà của Hội Hồng Hoa liên tục bị tấn công bởi một nhóm bí ẩn, tứ đà chủ Văn Thái Lai không rõ tung tích. Trong hành trình điều tra, Trần Gia Lạc hiệp nghị với vũ công Ngọc Như Ý luôn thèm khát kho báu của Phú Vương. Cả hai bắt đầu ra tay từ Tư Tiền ở Hành Châu, hợp lục với tam đà chủ Triệu Bán Sơn, tứ tẩu Lạc Văng để giải cứu Văn Thái Lai. Hóa ra Văn Thái lai đăng nắm trong tay một bí mật kinh thiên động đia, nên mới kéo theo vô số sự truy sát, dựng nên một vở nhiệm vụ bất khả thi giữa triều đình và giang hồ tứ phái. Đối mặt với hai chữ tình và nghĩa, Trận Gia Lạc phải quyết đoán như thế nào.</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Minh Hiên","avatar":""},{"name":"Cui Zhen Zhen","avatar":""},{"name":"He Zhong Hua","avatar":""},{"name":"jimingzhuwang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324256);
