INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jailer', 'Jailer', 'Jailer', 'https://phimimg.com/upload/vod/20240228-1/9166e9cfdfc2a547dcfc97aeab83403c.jpg', 'https://phimimg.com/upload/vod/20240228-1/4a47376b49b2e4e005b691fdca065160.jpg', '<p>Muthuvel Pandian, một cai ngục đã nghỉ hưu, nghiêm khắc nhưng giàu lòng nhân ái, sống một cuộc sống yên bình cùng gia đình, nhưng rắc rối đã ập đến với ông khi cuộc thử thách của con trai cảnh sát với một băng đảng mafia cổ xưa gặp trục trặc và buộc Muthu phải quay trở lại thế giới đen tối mà anh đã tự nguyện nắm giữ. thoát khỏi.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Rajinikanth","avatar":""},{"name":"Vinayakan","avatar":""},{"name":"Vasanth Ravi","avatar":""},{"name":"Yogi Babu","avatar":""},{"name":"Ramya Krishnan","avatar":""},{"name":"Mirnaa","avatar":""},{"name":"Rithvik","avatar":""},{"name":"G. Marimuthu","avatar":""},{"name":"Harshad","avatar":""},{"name":"Jaffer Sadiq","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324256);
