INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dat-rung-phuong-nam', 'Đất Rừng Phương Nam', 'Song of the South', 'https://phimimg.com/upload/vod/20240319-1/cb60138b0d4e4e8c7f8a7aaa8eb868ec.jpg', 'https://phimimg.com/upload/vod/20240319-1/72195bc6fd8ffa3063dc86ec088b6ffb.jpg', '<p>Đất Rừng Phương Nam phiên bản điện ảnh được kế thừa và phát triển từ tiểu thuyết cùng tên của nhà văn Đoàn Giỏi. Bộ phim kể về hành trình phiêu lưu của An - một cậu bé chẳng may mất mẹ trên đường đi tìm cha. Cùng với An, khán giả sẽ trải nghiệm sự trù phú của thiên nhiên và nét đẹp văn hoá đặc sắc của vùng đất Nam Kì Lục Tỉnh, sự hào hiệp của những người nông dân bám đất bám rừng và tinh thần yêu nước kháng Pháp đầu thế kỉ 20.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Trấn Thành","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Hồng Ánh","avatar":""},{"name":"Mai Tài Phến","avatar":""},{"name":"Tuấn Trần","avatar":""},{"name":"Tuyền Mập","avatar":""},{"name":"Hạo Khang","avatar":""},{"name":"Bảo Ngọc","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
