INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-diet-tru', 'Phong Thần: Diệt Trụ', 'Fengshen The Fall Of King Zhou', 'https://phimimg.com/upload/vod/20240228-1/f74b327b1ba7ea8e445e969e5628bced.jpg', 'https://phimimg.com/upload/vod/20240228-1/c5d9dbfbbe909d8633a48ec704911794.jpg', '<p>Nữ Oa và các vị thần đã phát động Kế hoạch Phong Thần nhằm lật đổ sự thống trị của nhà Thương, và sắp đặt cho yêu hồ ly chín đuôi thành mỹ nhân. Hoàng đế từ chối chấp nhận sắc lệnh của các vị thần, ông đã xây dựng lầu Trích Tinh và trèo lên trời. Hoàng đế dần yêu sự nuông chiều không kiềm chế của mỹ nhân , và bị xúi giục làm việc xấu. Giữa lúc hỗn loạn, người dân khổ không kể xiết, và một cuộc chiến giữa ba giới người, thần và quỷ bắt đầu ...</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Luo Li Qun","avatar":""},{"name":"Royi","avatar":""},{"name":"Mark.DU","avatar":""},{"name":"Du Yi Heng","avatar":""},{"name":"Shen Bao Ping","avatar":""},{"name":"Shi Xuan Ru","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324256);
