INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-gia-gan-2', 'Cớm Già Gân 2', 'The Squad: Home Run', 'https://phimimg.com/upload/vod/20240228-1/c57e3427163768cba990f1e6dd57d347.jpg', 'https://phimimg.com/upload/vod/20240228-1/2596d33db0e3ff90d1b3f0f98b6a0dce.jpg', '<p>Cựu huyền thoại Antigang Niels Cartier, người nổi tiếng với những phương pháp cơ bắp và độc đáo, đã rời bỏ lực lượng sau một sự can thiệp sai lầm và dẫn đến cái chết của vợ ông. Khi băng nhóm cướp ngân hàng chịu trách nhiệm cho cái chết của cô xuất hiện trở lại tám năm sau, Niels sẽ không để bất cứ ai cản đường anh ta để tìm cách trả thù. Ngay cả khi điều đó có nghĩa là phải tạo thành một bộ đôi bùng nổ với cô con gái 14 tuổi nóng nảy của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Alban Lenoir","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Sofia Essaïdi","avatar":""},{"name":"Stéfi Celma","avatar":""},{"name":"Cassiopée Mayance","avatar":""},{"name":"Sébastien Lalanne","avatar":""},{"name":"Jean-Toussaint Bernard","avatar":""},{"name":"Oumar Diaw","avatar":""},{"name":"Barbara Elisabeth Bühl","avatar":""},{"name":"Adrien Ménielle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
