INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-so-trai-dat-kim-tu-thap-that-lac', 'Ẩn Số Trái Đất: Kim Tự Tháp Thất Lạc', 'Unknown: The Lost Pyramid', 'https://phimimg.com/upload/vod/20240228-1/e97398e8612075d69d2670b3400c78ef.jpg', 'https://phimimg.com/upload/vod/20240228-1/cc1bf111056064f7c3cde74316dbd3c6.jpg', '<p>Trong bộ phim tài liệu này, các nhà khảo cổ học Ai Cập đào sâu lịch sử, khám phá lăng mộ và cổ vật hơn 4.000 năm tuổi khi họ tìm kiếm một kim tự tháp bị chôn vùi.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324256);
