INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-am-duong-trach', 'Đấu Phá Âm Dương Trạch', 'The Battle of Yin and Yang House', 'https://phimimg.com/upload/vod/20240316-1/62ee016c618fcc279093b374555b2a87.jpg', 'https://phimimg.com/upload/vod/20240316-1/f0026409d0bc16a206623989af505ce4.jpg', '<p>Thời Trung Hoa Dân Quốc, người ta phổ biến rộng rãi rằng nhà m được dùng để chôn cất theo phong thủy, câu nói làm giàu nhờ vào nhà m, thăng tiến nhờ vào nhà Âm rất phổ biến. Chức vụ của thầy phong thủy lại càng được ưa chuộng hơn bởi họ có khả năng định vị &quot;long mạch&quot; và phân tích ngôi mộ theo phong thủy. Trong phong tục truyền thống, có một nghi lễ kỳ bí được gọi là &quot;lễ cưới chuột&quot;, liên quan đến quan niệm về tử vong tại những nơi có phong thủy không tốt, nếu người còn sống mà sống trong nhà m, ngày về nhà sẽ mang theo tà linh trong bảy đêm. Hai người anh em đã tìm cách lợi dụng kiến thức về phong thủy để làm giàu, chịu tang 3 năm, đằng sau lòng hiếu thảo thật và giả là những câu chuyện cấm kỵ về “động cá chép”. Câu chuyện tiếp tục với việc người đàn ông sống ở ngôi nhà âm tìm kiếm một phụ nữ với áo đỏ và tóc dài hàng đêm. Tất cả manh mối đều liên quan đến ba phần của câu chuyện. Duyên phận không dứt và vòng tuần hoàn vẫn tiếp tục. Câu trả lời đằng sau nó là gì...</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Eddy Ko","avatar":""},{"name":"Hou Tongjiang","avatar":""},{"name":"Liu Jian Yu","avatar":""},{"name":"Wu Jingjing","avatar":""},{"name":"Xiang Hao","avatar":""},{"name":"Naomen Eerdeni","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Michael Mao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
