INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-pha-am-duong-trach', 'Đấu Phá Âm Dương Trạch', 'The Battle of Yin and Yang House', 'đấu phá âm dương trạch the battle of yin and yang house eddy ko hou tongjiang liu jian yu wu jingjing xiang hao naomen eerdeni yue dongfeng michael mao ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-song-con', 'Trò Chơi Sống Còn', 'Fatal Rule', 'https://phimimg.com/upload/vod/20240104-1/f38f8efdbdc0fbd95da67bd9ec13ebed.jpg', 'https://phimimg.com/upload/vod/20240104-1/45ddf57b8bffcf8e24bbdbf27f8ace66.jpg', '<p>Để không bị bắt làm nô lệ,Kiều Kinh Đình, người vô tình bước vào trò chơi vực thẳm, đã thành lập liên minh với Thư Ngải một game thủ cũ mang trong mình lòng hận thù, và Bạch Nhĩ, một thiếu niên với quá khứ bí ẩn. Họ cùng nhau đối mặt với sự ác độc của Hàn Bân, kẻ thống trị tàn ác, và tổ chức của anh ta. Sau những cuộc chiến khốc liệt, khi họ tự tin rằng chiến thắng đã đến gần, họ phát hiện ra mình bị rơi vào bẫy của Hàn Bân, lâm vào tình cảnh tuyệt vọng. Điều đáng sợ hơn là, với thất bại này, sự tin tưởng duy nhất giữa ba người cũng tan vỡ hoàn toàn. Trong thời khắc nguy cấp, sự xuất hiện của một cao thủ siêu phàm, Châu Nhất Đao, thay đổi cả cục diện lực lượng tại làng mới và mang đến cho Kiều Kinh Đình và những người khác một tia hy vọng trốn thoát.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 5, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324256);
