INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chech-quy-dao', 'Chệch Quỹ Đạo', 'Derailment', 'https://phimimg.com/upload/vod/20240309-1/ef1ab561cf5dee4fa6107e212416d4be.jpg', 'https://phimimg.com/upload/vod/20240309-1/6d4c7c2bbbb4b23d533038fb353af529.jpg', '<p>Đi theo tiếng nói trong tâm trí và nhìn thấu đường đời của bạn trong sự giao nhau giữa ánh sáng và bóng tối. Tỏa sáng rực rỡ trong thế giới của riêng mình, Giang Hiểu Viện và Kỳ Liên dành cả cuộc đời bên cạnh nhau. Yêu từ cái nhìn đầu tiên và hứa sẽ bên nhau mãi mãi! Đón nhận ánh sáng trên con đường tìm kiếm sự thật, ngẩng cao đầu và cảm nhận những điều tốt đẹp trong cuộc sống.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Haocun","avatar":""},{"name":"Lin Yi","avatar":""},{"name":"Huang Shengchi","avatar":""},{"name":"Fan Shiran","avatar":""},{"name":"Wang Chacha","avatar":""},{"name":"Wanyan Luorong","avatar":""},{"name":"Li Tiannuo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
