INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-an-hon', 'Kẻ Ăn Hồn', 'The Soul Reaper', 'https://phimimg.com/upload/vod/20240315-1/2c151504adb279ed692b550c7b7bb94b.jpg', 'https://phimimg.com/upload/vod/20240315-1/ae6b750d852646a5c94eb3873d5e7c78.jpg', '<p>Kẻ Ăn Hồn - phim về hàng loạt cái chết bí ẩn ở Làng Địa Ngục, nơi có ma thuật cổ xưa: 5 mạng đổi bình Rượu Sọ Người. Thập Nương - cô gái áo đỏ là kẻ nắm giữ bí thuật luyện nên loại rượu mạnh nhất! &nbsp;Diễn viên: Hoàng Hà, Võ Điền Gia Huy, Huỳnh Thanh Trực, NSƯT Chiều Xuân, Nghệ sĩ Viết Liên, NSND Ngọc Thư, Nguyễn Hữu Tiến, Nguyễn Phước Lộc, Nghinh Lộc, Lý Hồng Ân, Vũ Đức Ngọc… &nbsp;Phim điện ảnh mới của Đạo diễn Trần Hữu Tấn và NSX Hoàng Quân dự kiến khởi chiếu từ 15.12.2023!</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hoàng Hà","avatar":""},{"name":"Võ Điền Gia Huy","avatar":""},{"name":"Huỳnh Thanh Trực","avatar":""},{"name":"Lan Phương","avatar":""},{"name":"Chiều Xuân","avatar":""},{"name":"Viết Liên","avatar":""},{"name":"Ngọc Thư","avatar":""},{"name":"Nguyễn Hữu Tiến","avatar":""},{"name":"Nguyen Phuoc Loc","avatar":""},{"name":"Nghinh Lộc","avatar":""},{"name":"Lý Hồng Ân","avatar":""},{"name":"Vũ Đức Ngọc","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324256);
