INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jodie-nguoi-duoc-chon', 'Jodie, Người Được Chọn', 'The Chosen One', 'https://phimimg.com/upload/vod/20240220-1/8058db04423a728f3addb327c4bd1c8f.jpg', 'https://phimimg.com/upload/vod/20240220-1/72942811a966e79286c388cb7f42f9a1.jpg', '<p>Sau khi sống sót sau một tai nạn kinh hoàng, Jodie, một cậu bé mười hai tuổi đến từ Santa Rosalía, Baja California Sur, phát hiện ra rằng mình có sức mạnh giống như Chúa Giê-su: Cậu có thể biến nước thành rượu, khiến người tàn tật có thể đi lại và thậm chí có thể khiến người chết sống lại . Làm thế nào anh ta sẽ đối phó với số phận của mình và dẫn dắt thế giới vượt qua một cuộc xung đột đã được hình thành hàng ngàn năm?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Bobby Luhnow","avatar":""},{"name":"Dianna Agron","avatar":""},{"name":"Carlos Bardem","avatar":""},{"name":"Lilith Curiel","avatar":""},{"name":"Juanito Anguamea","avatar":""},{"name":"Jorge Javier Arballo","avatar":""},{"name":"Alberto Pérez-Jácome","avatar":""},{"name":"Patricio Serna Meza","avatar":""},{"name":"Alfonso Dosal","avatar":""},{"name":"Sofía Sisniega","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
