INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-tuong-truyen', 'Vân Tương Truyện', 'The Ingenious One', 'https://phimimg.com/upload/vod/20240220-1/f96ae35ee9de42824c8f3f2cc4d49ced.jpg', 'https://phimimg.com/upload/vod/20240220-1/778481a07f6e13991f3f1f96ad82cd38.jpg', '<p>\Vân Tương Truyện\ do Do Đạt Chí làm đạo diễn, với sự tham gia của Mao Hiểu Đồng và Trình Hiểu \nPhim là dự án chuyển thể từ bộ tiểu thuyết Thiên Môn &nbsp;của tác giả Phương Bạch Vũ. Câu chuyện xoay quanh nhân vật Vân Tương (do Trần Hiểu thủ vai) - một đệ tử của Vân Đài và hành trình bước ra \giang hồ\ sau mười năm khổ luyện.Trong quá trình đó, Vân Tương gặp Thư Á Nam (do Mao Hiểu Đồng thủ vai) - một nữ tử tinh ranh, thông minh và lanh lợi. Cả hai nảy sinh tình cảm và cùng nhau phá án. Điều tra về một thảm án, Vân Tương tìm ra sự thật kinh hoàng có liên quan đến Vân Đài và quyết định đứng lên bảo vệ chính nghĩa bằng cả trái tim mình, ngay cả khi phải trả giá bằng cả tính mạng.\nBộ phim sẽ được phát sóng trực tuyến trên iQiyi Quốc tế .</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 18, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Xiao","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""},{"name":"Tần Lam","avatar":""},{"name":"Wang Jin Song","avatar":""},{"name":"Kara Wai","avatar":""},{"name":"Tang Xiao Tian","avatar":""},{"name":"AmelieXu","avatar":""},{"name":"Liu Guan Lin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324256);
