INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('outlast-sinh-ton-noi-hoang-da', 'Outlast: Sinh Tồn Nơi Hoang Dã', 'Outlast', 'https://phimimg.com/upload/vod/20240220-1/3d000a7d095f9c9ae55e3ef17137ecb9.jpg', 'https://phimimg.com/upload/vod/20240220-1/8f958617b1ea14b7976e3bcd1a86b1b1.jpg', '<p>Trong môi trường hoang dã khắc nghiệt ở Alaska, 16 chuyên gia sinh tồn cạnh tranh giành giải thưởng tiền mặt khổng lồ. Song những con sói đơn độc này phải hợp sức để chiến thắng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324256);
