INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-2023', 'Ác Quỷ', 'Revenant', 'https://phimimg.com/upload/vod/20240313-1/3df35c783f941005112aa4249224172a.jpg', 'https://phimimg.com/upload/vod/20240313-1/de5bad8bc186e2807fcbad6884ff8f61.jpg', '<p>Một người phụ nữ bị chiếm hữu bởi một linh hồn xấu xa và một người đàn ông có thể nhìn thấy những linh hồn xấu xa đã khám phá ra bí mật về những cái chết bí ẩn xung quanh năm linh hồn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Tae-ri","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Hong Kyung","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Yang Hye-ji","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Park Ji-young","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Lee Gyu-hoe","avatar":""},{"name":"Ye Soo-jung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
