INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('9-lan-gap-em', '9 Lần Gặp Em', 'Nine Times Time Travel', 'https://phimimg.com/upload/vod/20240227-1/c1205d582de28c974be3e9ddfe544945.jpg', 'https://phimimg.com/upload/vod/20240227-1/be3bb933205dba4195fa53fd860f4346.jpg', '<p>Nhà khoa học não bộ Thiện Vũ vô tình biết được tin Mẫn Anh - tình đầu của mình qua đời. Trước khi chết Mẫn Anh nắm chặt một cây nến sinh nhật. Thiện Vũ đốt nến lên, ánh sáng của nến đã tạo nên kỳ tích. Ngọn nến đã đưa Thiện Vũ trở về mười năm trước. Thiện Vũ đã xuyên không nhiều lần để cứu lấy tình yêu của mình nhưng lại vô tình tạo ra những hiệu ứng bươm bướm, một tình cảm sâu sắc bị ẩn giấu mười năm trước dần lộ ra...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Daisy Li","avatar":""},{"name":"Lin Feng Song","avatar":""},{"name":"Fan Xiao Dong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
