INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('9-lan-gap-em', '9 Lần Gặp Em', 'Nine Times Time Travel', '9 lần gặp em nine times time travel daisy li lin feng song fan xiao dong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-ngay-tan-cua-gotham', 'Người Dơi: Ngày Tàn Của Gotham', 'Batman: The Doom That Came To Gotham', 'https://phimimg.com/upload/vod/20240227-1/96dbbaf646db678c21a916723634725d.jpg', 'https://phimimg.com/upload/vod/20240227-1/a4d1b8f983e28dfea6da15a2c1e3d872.jpg', '<p>là bộ phim hoạt hình Batman thứ hai mươi ba sắp ra mắt. Bộ phim là phiên bản chuyển thể từ tiểu thuyết đồ họa Elseworlds phần truyện năm 2000 cùng tên, được viết bởi Mike Mignola với sự hợp tác của Richard Pace và minh họa bởi Troy Nixey và Dennis Janke với sự trợ giúp của Dave Stewart. Tiểu thuyết này đã được xuất bản bởi DC Comics.Nhà thám hiểm Bruce Wayne khám phá ra một bí mật kinh hoàng đe dọa thành phố Gotham và toàn thế giới vào những năm 1920.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Giuntoli","avatar":""},{"name":")Tati Gabrielle","avatar":""},{"name":"David Dastmalchian","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324256);
