INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-menh-gan-ket', 'Vận Mệnh Gắn Kết', 'Kader Baglari', 'https://phimimg.com/upload/vod/20240314-1/5330ad04503bfb8363faef4ec841fa50.jpg', 'https://phimimg.com/upload/vod/20240314-1/0dc52942a70802c05e63919e340f162c.jpg', '<p>Bộ truyện sẽ kể về câu chuyện tình yêu đầy ấn tượng của Kerem và Sevda, những người có con đường xuyên quốc gia và đến tận Manisa. Các sự kiện trong truyện sẽ bắt đầu với việc Kerem vào tù vì phản đối sự bất công đối với Sevda. Tình yêu giữa Kerem và Sevda đầy những sự trùng hợp ngẫu nhiên sẽ dẫn đến xung đột giữa gia đình họ.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 16, 2023, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Serkan Çayoğlu","avatar":""},{"name":"Ayça Ayşin Turan","avatar":""},{"name":"Arzu Gamze Kılınç","avatar":""},{"name":"Alptekin Serdengeçti","avatar":""},{"name":"Nazlı Bulum","avatar":""},{"name":"Sanem Babi","avatar":""},{"name":"Mehmet Aykaç","avatar":""},{"name":"Zeynep Köse","avatar":""},{"name":"Betül Çobanoğlu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
