INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-uoc', 'Điều Ước', 'Wish', 'https://phimimg.com/upload/vod/20231018-1/b27ee37f5a8a7f3cc146528569a1c90e.jpg', 'https://phimimg.com/upload/vod/20231018-1/da6a74f4ccfd967601e4e75f2fefb198.jpg', '<p>Một bộ phim hoạt hình hoàn toàn mới với chủ đề về những ngôi sao ước vọng. Phim có Ariana DeBose lồng tiếng vai Asha và được đạo diễn bởi Chris Buck &amp; Fawn Veerasunthorn, sản xuất bởi Peter Del Vecho &amp; Juan Pablo Reyes với các bài hát được Julia Michaels sáng tác mới hoàn toàn.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ariana DeBose","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Angelique Cabral","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Natasha Rothwell","avatar":""},{"name":"Jennifer Kumiyama","avatar":""},{"name":"Evan Peters","avatar":""},{"name":"Harvey Guillén","avatar":""},{"name":"Ramy Youssef","avatar":""},{"name":"Niko Vargas","avatar":""},{"name":"Della Saba","avatar":""},{"name":"Jon Rudnitsky","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324256);
