INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-dem-thu-sau', 'Kế Hoạch Đêm Thứ Sáu', 'Friday Night Plan', 'https://phimimg.com/upload/vod/20240220-1/713e99913958e536168d5be96c4ca3ae.jpg', 'https://phimimg.com/upload/vod/20240220-1/f0a26b20b6008ef2f9751f3f68db96e9.jpg', '<p>Khi mẹ của họ đi công tác, hai anh em hay cãi cọ bèn bắt tay để bí mật tham dự bữa tiệc đỉnh nhất năm trước khi bà trở về.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Babil Khan","avatar":""},{"name":"Amrith Jayan","avatar":""},{"name":"Medha Rana","avatar":""},{"name":"Juhi Chawla","avatar":""},{"name":"Ninad Kamat","avatar":""},{"name":"Aadhya Anand","avatar":""},{"name":"Aditya Jain","avatar":""},{"name":"Rishabh Joshi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
