INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-huyen-thu', 'Đại Huyễn Thú', 'Big Eudemon', 'https://phimimg.com/upload/vod/20240220-1/ef488c648cb5e49a39cf42e702cb3288.jpg', 'https://phimimg.com/upload/vod/20240220-1/d8be12f196561b5bc73221b5f49cf957.jpg', '<p>Loạn Trường An còn chưa dẹp được, lòng người dao động, đương triều hoàng đế định cho Thái thượng hoàng mượn yến tiệc sinh nhật, mở kho thả thóc để ổn định lòng dân. mọi người. Quái thú muốn sử dụng đội hình bẩm sinh này để hút máu người dân, lật đổ loài người và sử dụng ma thú để kiểm soát thế giới. Hác Long Tiêu trước đây là một trong \Mười sáu cận vệ\ của đội cận vệ của hoàng đế. Để cứu em gái bị quái vật hãm hại, vô tình bị chiếc xe ma lợi dụng, trải qua đủ loại gian khổ và giành được đủ loại pháp khí, đấu tranh sinh tử. Vào thời khắc mấu chốt, Long Tiêu mở ra cánh cửa của các vị thần, mới nhận ra rằng mình chính là thần tổ của ma thú kiếp trước và cứu mạng những người dân thường.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guo Fang Zhou","avatar":""},{"name":"Tina","avatar":""},{"name":"Zeng Chen","avatar":""},{"name":"EnJing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324256);
