INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-dong-trong-tuyet', 'Cộng Đồng Trong Tuyết', 'Society of the Snow', 'https://phimimg.com/upload/vod/20240312-1/88c1ad794c2c26e0ec9d24596d13e46a.jpg', 'https://phimimg.com/upload/vod/20240312-1/f2b0155dbd12d6e5422df27c5ff134d8.jpg', '<p>Năm 1972, một chuyến bay của Uruguay bị rơi ở trung tâm xa xôi của dãy Andes, buộc những người sống sót trở thành niềm hi vọng lớn nhất của nhau.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Enzo Vogrincic","avatar":""},{"name":"Agustín Pardella","avatar":""},{"name":"Matías Recalt","avatar":""},{"name":"Tomás Wolf","avatar":""},{"name":"Diego Vegezzi","avatar":""},{"name":"Esteban Kukuriczka","avatar":""},{"name":"Francisco Romero","avatar":""},{"name":"Rafael Federman","avatar":""},{"name":"Felipe González Otaño","avatar":""},{"name":"Agustín Della Corte","avatar":""},{"name":"Valentino Alonso","avatar":""},{"name":"Simon Hempe","avatar":""},{"name":"Fernando Contigiani García","avatar":""},{"name":"Benjamín Segura","avatar":""},{"name":"Luci","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324256);
