INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-napoleon', 'Đế Chế Napoleon', 'Napoleon', 'https://phimimg.com/upload/vod/20240310-1/a8dd86873e8763b1504abd9929e453eb.jpg', 'https://phimimg.com/upload/vod/20240310-1/ee90af473cd75252af4b2c5364cef52f.jpg', '<p>Bộ phim là cái nhìn nguyên bản và cá nhân về nguồn gốc của Napoléon Bonaparte và quá trình leo lên ngôi hoàng đế nhanh chóng, tàn nhẫn của ông. Câu chuyện được kể qua lăng kính của vợ ông, mối quan hệ phức tạp và thường xuyên bất ổn, cùng Josephine, một tình yêu đích thực.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Vanessa Kirby","avatar":""},{"name":"Tahar Rahim","avatar":""},{"name":"Rupert Everett","avatar":""},{"name":"Mark Bonnar","avatar":""},{"name":"Paul Rhys","avatar":""},{"name":"Ben Miles","avatar":""},{"name":"Riana Duce","avatar":""},{"name":"Edouard Philipponnat","avatar":""},{"name":"Miles Jupp","avatar":""},{"name":"Scott Handy","avatar":""},{"name":"Youssef Kerkour","avatar":""},{"name":"John Hollingworth","avatar":""},{"name":"Abubakar Salim","avatar":""},{"name":"Thom Ashley","avatar":""},{"name":"Jannis Niewöhner","avatar":""},{"name":"Julian Rhind-Tutt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324256);
