INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-vong-2023', 'Tham Vọng', 'Agency', 'https://phimimg.com/upload/vod/20240220-1/14b13053d6ace6ebae5f1565bc4f0a5a.jpg', 'https://phimimg.com/upload/vod/20240220-1/20a1099388067c93e21583b70cf3d1aa.jpg', '<p>Tham Vọng - Agency kể về Go Ah In (Lee Bo Young), người trở thành nữ giám đốc điều hành đầu tiên của công ty quảng cáo hàng đầu Hàn Quốc. Mặc dù có hoàn cảnh gia đình nghèo khó và không có nền tảng học tập tốt nhất, cô có một khát vọng thành công mạnh mẽ. Càng cô đơn và đau đớn, Go Ah In càng tự thúc ép bản thân và cố gắng vươn tới đỉnh cao.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jo Sung Ha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
