INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('daisy-jones-the-six', 'Daisy Jones & The Six', 'Daisy Jones & The Six', 'https://phimimg.com/upload/vod/20240220-1/b0c87c28301aab61f2f669f838b74ca8.jpg', 'https://phimimg.com/upload/vod/20240220-1/bf484967078f09e0e014c4457f446a3c.jpg', '<p>Năm 1977, Daisy Jones &amp; The Six đứng đầu thế giới. Đứng đầu là hai ca sĩ chính lôi cuốn—Daisy Jones và Billy Dunne—ban nhạc đã vươn lên từ vô danh trở nên nổi tiếng. Và sau đó, sau một buổi biểu diễn cháy vé tại Chiến trường Chiến sĩ ở Chicago, họ tạm dừng buổi biểu diễn. Bây giờ, nhiều thập kỷ sau, các thành viên ban nhạc cuối cùng đã đồng ý tiết lộ sự thật. Đây là câu chuyện về cách một ban nhạc mang tính biểu tượng bùng nổ ở đỉnh cao quyền lực của nó.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Riley Keough","avatar":""},{"name":"Camila Morrone","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Nabiyah Be","avatar":""},{"name":"Will Harrison","avatar":""},{"name":"Suki Waterhouse","avatar":""},{"name":"Josh Whitehouse","avatar":""},{"name":"Sebastian Chacon","avatar":""},{"name":"Tom Wright","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
