INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-phong-lat-lat', 'Tây Phong Lật Lật', 'Intrigue And Love', 'https://phimimg.com/upload/vod/20240220-1/c6977670ed690565448028bc434d9a7e.jpg', 'https://phimimg.com/upload/vod/20240220-1/c43272347a2097141c4867aeec090fb4.jpg', '<p>Lý Tây Phong vì báo thù cho cha mà nhập cung, vô tình được chọn trở thành công chúa, đến Đột Quyết hòa thân để thăm dò quân tình. Lý Tây Phong vốn muốn lợi dụng thế lực của Cát Liệt để báo thù cho cha, nhưng lại biết được sở dĩ Cát Liệt cầu thân là vì đại ca hắn đang làm con tin ở Đại Đường, cưới nàng là vì muốn giữ chân hoàng đế Đại Đường mà thôi. Đằng sau mọi thủ đoạn lấy lòng của Cát Liệt chính là để lợi dụng thân phận công chúa của nàng để thăm dò tình báo, nhưng lại biết được rằng thân phận công chúa của Lý Tây Phong là giả. Hai người mang lòng thù hận, từ giấu giếm nhau đến lúc yêu nhau, cuối cùng cũng tìm được hạnh phúc mà mình muốn có.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Dịch Long","avatar":""},{"name":"Vương Lộ Thanh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324256);
