INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-hau', 'Phong Hậu', 'Queenmaker', 'https://phimimg.com/upload/vod/20240215-1/e36baee7bd275cd5e951849384678260.jpg', 'https://phimimg.com/upload/vod/20240215-1/375ef473ff7ca2fee4d7b99882465344.jpg', '<p>Sau tai nạn bi thảm, một chuyên gia dàn xếp đầy quyền lực dùng các kỹ năng của mình để biến một luật sư dân quyền thành thị trưởng tiếp theo và hạ bệ sếp cũ.</p>', 'Full', 11, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hee Ae","avatar":""},{"name":"Moon So Ri","avatar":""},{"name":"Ryu Soo Young","avatar":""},{"name":"Seo Yi Sook","avatar":""},{"name":"Ok Ja Yeon","avatar":""},{"name":"Yoon Ji Hye","avatar":""},{"name":"Kim Sae Byuk","avatar":""},{"name":"Lee Kyung Yung","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Kim Tae Hun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
