INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dead-friend-forever', 'Dead Friend Forever', 'Dead Friend Forever - DFF: Uncovered Version', 'https://phimimg.com/upload/vod/20240310-1/1df9ffe1e9e1d0075bde796ac32fba0b.jpg', 'https://phimimg.com/upload/vod/20240310-1/33e3f4325c95396f28ab762fbeff5d20.jpg', '<p>DFF: Dead Friend Forever xoay quanh câu chuyện về những người bạn cùng nhau đi du lịch đến một ngôi nhà nghỉ dưỡng giữa rừng để chia tay một người bạn sắp lên đường du học. Chuyến đi chia tay này khiến họ nhớ lại quá khứ và không thể ngờ rằng nó lại mang đến nhiều sự cố nguy hiểm đến tính mạng. Chẳng bao lâu, họ nhận ra đây không phải là một chuyến đi chia tay như đơn giản bình thường mà là một chuyến đi khủng khiếp với những thảm họa đang chờ đợi họ ở phía trước.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 18, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ta Nannakun Pakapatpornpob","avatar":""},{"name":"Copper Phuriwat Chotiratanasak","avatar":""},{"name":"Copper","avatar":""},{"name":"Barcode Trinnasit Isarapongporn","avatar":""},{"name":"JJ Patiphan Fueangfunuwat","avatar":""},{"name":"JJ","avatar":""},{"name":"Fuaiz Thanawat Shinawat","avatar":""},{"name":"Fuaiz","avatar":""},{"name":"Mio Athens werapatanakul","avatar":""},{"name":"Mio","avatar":""},{"name":"Us Nititorn Akkarachotsopon","avatar":""},{"name":"Bump Pawat Akkradetsakul","avatar":""},{"name":"Bump","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324256);
