INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chang-trai-tren-thuyen', 'Những Chàng Trai Trên Thuyền', 'The Boys in the Boat', 'https://phimimg.com/upload/vod/20240311-1/9df322d09d21cd3f509cec96c3349403.jpg', 'https://phimimg.com/upload/vod/20240311-1/1955829131bc3c3ed265b3533b83c9cf.jpg', '<p>Câu chuyện lấy bối cảnh những năm 1930 tập trung vào đội chèo thuyền của Đại học Washington, từ khởi đầu thời kỳ Suy thoái cho đến giành huy chương vàng tại Thế vận hội Berlin 1936</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joel Edgerton","avatar":""},{"name":"Callum Turner","avatar":""},{"name":"Peter Guinness","avatar":""},{"name":"Sam Strike","avatar":""},{"name":"Thomas Elms","avatar":""},{"name":"Jack Mulhern","avatar":""},{"name":"Luke Slattery","avatar":""},{"name":"Bruce Herbelin-Earle","avatar":""},{"name":"Wil Coban","avatar":""},{"name":"Tom Varey","avatar":""},{"name":"Joel Phillimore","avatar":""},{"name":"James Wolk","avatar":""},{"name":"Hadley Robinson","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Courtney Henggeler","avatar":""},{"name":"Alec Newman","avatar":""},{"name":"Laurel Lef","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324256);
