INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-chang-trai-tren-thuyen', 'Những Chàng Trai Trên Thuyền', 'The Boys in the Boat', 'những chàng trai trên thuyền the boys in the boat joel edgerton callum turner peter guinness sam strike thomas elms jack mulhern luke slattery bruce herbelin-earle wil coban tom varey joel phillimore james wolk hadley robinson chris diamantopoulos courtney henggeler alec newman laurel lef ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-vi-nhan-gian', 'Muôn Vị Nhân Gian', 'The Taste of Things', 'https://phimimg.com/upload/vod/20240310-1/7c7302a2bd36dfcc10905d4107c9cd2c.jpg', 'https://phimimg.com/upload/vod/20240310-1/a2140d6775ee98b84e208ef1172e38db.jpg', '<p>Trong bối cảnh năm 1885 tại Pháp, đầu bếp tài ba Eugenie đã làm việc cho nhà quý tộc sành ăn Dodin Bouffant suốt 20 năm qua. Công việc nấu nướng và lòng ngưỡng mộ mà cả hai dành cho nhau dần dẫn tới một mối quan hệ lãng mạn. Họ cùng nhau tạo ra những tuyệt tác ẩm thực, khiến ngay cả những đầu bếp lừng lẫy nhất thế giới cũng phải thán phục. Nhưng Eugenie yêu thích sự tự do của mình và chưa bao giờ muốn kết hôn với Dodin. Khi Dodin nhận ra tình cảm sâu sắc của mình dành cho người phụ nữ đã luôn kề bên những năm tháng qua, cũng là lúc ông phát hiện Eugenie lâm bệnh nặng. Liệu mối tình lãng mạn này có thể kết thúc với hạnh phúc trọn vẹn?</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Benoît Magimel","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"Patrick d''Assumçao","avatar":""},{"name":"Emmanuel Salinger","avatar":""},{"name":"Jan Hammenecker","avatar":""},{"name":"Frédéric Fisbach","avatar":""},{"name":"Galatéa Bellugi","avatar":""},{"name":"Pierre Gagnaire","avatar":""},{"name":"Bonnie Chagneau-Ravoire","avatar":""},{"name":"Yannik Landrein","avatar":""},{"name":"Sarah Adler","avatar":""},{"name":"Jean-Marc Roulot","avatar":""},{"name":"Mhamed Arezki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324256);
