INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-mat-troi', 'Người Mặt Trời', 'Daydreamers', 'https://phimimg.com/upload/vod/20240310-1/8d7bb822c23005484b80b12fa7690c94.jpg', 'https://phimimg.com/upload/vod/20240310-1/1c07cb506c8ffb4b37fabec50b209608.jpg', '<p>400 năm qua, loài Ma Cà Rồng đã bí mật sống giữa loài người trong hòa bình, nhưng hiểm họa bỗng ập đến khi một cô gái loài người phát hiện được thân phận của hai anh em Ma Cà Rồng. Người anh khát máu quyết săn lùng cô để bảo vệ bí mật giống loài, trong khi người còn lại chạy đua với thời gian để bảo vệ cô bằng mọi giá.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Chi Pu","avatar":""},{"name":"Thuận Nguyễn","avatar":""},{"name":"Trần Ngọc Vàng","avatar":""},{"name":"Trịnh Thảo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
