INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vat-than-thoai-phan-2', 'Sinh Vật Thần Thoại (Phần 2)', 'Carnival Row (Season 2)', 'https://phimimg.com/upload/vod/20240215-1/fc633f3e7243d37143ac45613bc3eb46.jpg', 'https://phimimg.com/upload/vod/20240215-1/365fb6127f44c8bf34c3de4958da75bc.jpg', '<p>Yêu. Giết người. âm mưu. Cuộc cách mạng. Khi những vụ giết người bí ẩn thổi bùng căng thẳng giữa Faefolk và những kẻ áp bức Con người của họ, mỗi cư dân của Carnival Row phải chọn họ là ai và hành động như thế nào.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Orlando Bloom","avatar":""},{"name":"Cara Delevingne","avatar":""},{"name":"David Gyasi","avatar":""},{"name":"Karla Crome","avatar":""},{"name":"Tamzin Merchant","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Anna Rust","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324256);
