INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nan-nhan-khong-hoan-hao', 'Nạn Nhân Không Hoàn Hảo', 'Imperfect Victim', 'https://phimimg.com/upload/vod/20240215-1/4ba4d50b2ae7e10b9ed1989b8c5bef9c.jpg', 'https://phimimg.com/upload/vod/20240215-1/eb0e0fdebca004b48644d2ae0e238dc9.jpg', '<p>Nạn Nhân Không Hoàn Hảo là một bộ phim truyền hình do Dương Dương đạo diễn, với sự tham gia của các diễn viên Châu Tấn, Lưu Dịch Quân, Lâm Duẫn, Trần Sác.Một vụ án quấy rối tình dục xảy ra trong môi trường công sở đã gây ra sự báo động khi bị tố cáo bởi một người thứ ba giấu tên. Ban đầu, nạn nhân nữ Triệu Tầm (do Lâm Duẫn thủ vai) phủ nhận việc bị hại, nhưng sau năm ngày, cô mới đủ dũng cảm tố cáo. Luật sư Lâm Khuyết (do Châu Tấn thủ vai) đã tham gia vào cuộc điều tra từ đầu, thông qua việc điều tra từng bằng chứng mà nạn nhân đưa ra, đã xác định và khám phá sự thật, đẩy lùi các cáo buộc và chấm dứt cuộc điều tra tội phạm, khiến các cơ quan công an rút lại vụ án. Mặt trái là việc tiết lộ chi tiết của vụ án đã khiến danh tính Triệu Tầm bị lộ và bị tấn công trên mạng, bị coi như điếm , mất đi công việc và cuộc sống trở nên hỗn loạn... Trong cuộc chiến giữa sự thật pháp lý và sự thật khách quan trong tâm trí, Lâm Khuyết đối diện với một thách thức đạo đức chưa từng có trong sự nghiệp của mình, và cô ấy sẽ lựa chọn điều gì</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jue","avatar":""},{"name":"劉奕君","avatar":""},{"name":"Jelly Lin","avatar":""},{"name":"Chung Sở Hi","avatar":""},{"name":"Chen Shu","avatar":""},{"name":"Jacoke","avatar":""},{"name":"Dong Jie","avatar":""},{"name":"Zhou Cheng Ao","avatar":""},{"name":"HeiZe","avatar":""},{"name":"Hei Ze","avatar":""},{"name":"Yunpeng Guan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324256);
