INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('33-lan-hon-dau', '33 Lần Hôn Đầu', 'First Kisses', 'https://phimimg.com/upload/vod/20240215-1/ce28fa0239ba6c6e7ad4fdb11095f473.jpg', 'https://phimimg.com/upload/vod/20240215-1/2ee48b24da1c466be8ec00a1b0540876.jpg', '<p>Thiếu nữ bị mất trí nhớ gặp gỡ nam thần nghiên cứu khoa học, sau nụ hôn tình cờ mở ra hành trình tìm lại ký ức! Dưới sức mạnh của từng nụ hôn liên tiếp diễn ra, tình cảm của hai người cũng dần thay đổi.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Quản Kim Lân","avatar":""},{"name":"Tống Bội Trạch","avatar":""},{"name":"Châu Tử Kiệt","avatar":""},{"name":"Lý Huệ Linh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324256);
