INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-gu', 'Thằng Gù', 'Quasi', 'https://phimimg.com/upload/vod/20240309-1/a9425d85604ce718d2902079361acb53.jpg', 'https://phimimg.com/upload/vod/20240309-1/908bf76a97354f2d8669b07f7b6e3dba.jpg', '<p>Phim “Quasi” (2023) là một bộ phim hài kịch-drama theo dõi câu chuyện của một người lưng gù đáng thương, người khao khát tình yêu nhưng lại tìm thấy mình giữa một cuộc tranh chấp giết người giữa Giáo hoàng và vua Pháp khi mỗi người ra lệnh cho người lưng gù giết đối phương</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brian Cox","avatar":""},{"name":"Kevin Heffernan","avatar":""},{"name":"Steve Lemme","avatar":""},{"name":"Jay Chandrasekhar","avatar":""},{"name":"Paul Soter","avatar":""},{"name":"Erik Stolhanske","avatar":""},{"name":"Adrianne Palicki","avatar":""},{"name":"Gabriel Hogan","avatar":""},{"name":"Roman Mitichyan","avatar":""},{"name":"Michael Yurchak","avatar":""},{"name":"Ty Bamla","avatar":""},{"name":"Michael Heidemann","avatar":""},{"name":"Maria Arroyo","avatar":""},{"name":"Ken May","avatar":""},{"name":"Maetrix Fitten","avatar":""},{"name":"James Hutson","avatar":""},{"name":"Suzanne Gutierrez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
