INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-co-sao-lai-the', 'Hoàng Phi Cớ Sao Lại Thế', 'What''s Wrong With My Princess', 'https://phimimg.com/upload/vod/20240302-1/946937a21301834650b61cccd5cfb4ca.jpg', 'https://phimimg.com/upload/vod/20240302-1/162de0e936d9bc2fec4ccc3445c716cf.jpg', '<p>Nữ tướng quân Mộ Dung Thu Vũ, yêu si mê Nhị hoàng tử Lê Mặc. Sau khi giúp hắn đoạt được hoàng vị, hắn đã liên thủ với muội muội nàng là Mộ Dung Hinh Nhi để sát hại nàng. Sau khi trùng sinh, Thu Vũ phát hiện mình quay về ngày đại hôn với Thất hoàng tử Lê Tiễn... Thu Vũ quyết định liên thủ với đối thủ của Lê Mặc là Lê Tiễn, để Mộ Dung Hinh Nhi và Lê Mặc phải chịu sự trừng phạt thích đáng!</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Mingjing","avatar":""},{"name":"Chang Bin","avatar":""},{"name":"Mu Leen","avatar":""},{"name":"Li Shiyao","avatar":""},{"name":"Wu Hao","avatar":""},{"name":"Wenxiao He","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
