INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cop-xe-tu-than', 'Cốp Xe Tử Thần', 'Trunk - Locked In', 'https://phimimg.com/upload/vod/20240309-1/a03bd303c7b209736b8f2565036a17a8.jpg', 'https://phimimg.com/upload/vod/20240309-1/845d56ba4c7c66720ab36a51e7cef930.jpg', '<p>Malina tỉnh dậy và mất phương hướng trong cốp của một chiếc ô tô đang chạy quá tốc độ và kinh hoàng phát hiện ra rằng cô đã mất đi nhiều thứ hơn là trí nhớ của mình. Với chiếc điện thoại di động là kết nối duy nhất với thế giới bên ngoài, cô bắt đầu một cuộc chiến sinh tồn tuyệt vọng.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Sina Martens","avatar":""},{"name":"Artjom Gilz","avatar":""},{"name":"Luise Helm","avatar":""},{"name":"Poal Cairo","avatar":""},{"name":"Charles Rettinghaus","avatar":""},{"name":"Janina Sachau","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
