INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-tung-den-tuong-lai-cua-em', 'Anh Từng Đến Tương Lai Của Em', 'I''ve Been To Your Future', 'https://phimimg.com/upload/vod/20240228-1/b3f2690167211a6042f35255175e2c06.jpg', 'https://phimimg.com/upload/vod/20240228-1/412167213146c2b95140c7020a2132cb.jpg', '<p>Trước ngày tốt nghiệp đại học, cuối cùng Diệp Phàm cũng thu hết can đảm tỏ tình với Đào Đào - người anh yêu thầm nhiều năm, nhưng Đào Đào lại bất ngờ gặp tai nạn qua đời, hai người âm dương cách biệt. Khi dọn dẹp di vật của Đào Đào, Diệp Phàm tình cờ tìm được chiếc điện thoại cũ cô từng dùng khi còn sống, có được khả năng liên kết với quá khứ. Để cứu Đào Đào, Diệp Phàm quyết định tiến hành một cuộc giải cứu xuyên thời không.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324256);
