INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oh-youngsim', 'Oh! Youngsim', 'Oh! Youngsim', 'https://phimimg.com/upload/vod/20240209-1/eba1ac1168f5e6a38f5b2aba83653080.jpg', 'https://phimimg.com/upload/vod/20240209-1/9ce11986d6349f77dfc65f6a8cc5a14f.jpg', '<p>Oh Young-Sim độc thân và ngoài 30 tuổi. Cô ấy đã làm việc với tư cách là một PD của chương trình truyền hình trong 8 năm. Cô ấy muốn làm mọi người cười với các chương trình truyền hình của mình, nhưng chúng luôn bị hủy do xếp hạng phổ biến thấp. Sự nghiệp của cô hiện đang rơi vào khủng hoảng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Ha-yoon","avatar":""},{"name":"Donghae","avatar":""},{"name":"Lee Min-jae","avatar":""},{"name":"Jung Woo-yeon","avatar":""},{"name":"Wang Ji-hye","avatar":""},{"name":"Song Yeong-jae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324256);
