INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('with-love-phan-2', 'With Love (Phần 2)', 'With Love (Season 2)', 'https://phimimg.com/upload/vod/20240209-1/1613687c9f0dbd1f5d29483427936daa.jpg', 'https://phimimg.com/upload/vod/20240209-1/d05dfd66e32ca931c36eaa111c30ba41.jpg', '<p>Anh chị em nhà Diaz, Lily và Jorge, đang thực hiện sứ mệnh tìm kiếm tình yêu và mục đích sống. Họ đi qua những con đường với những cư dân dường như không liên quan trong một số ngày cao điểm nhất trong năm - ngày lễ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emeraude Toubia","avatar":""},{"name":"Mark Indelicato","avatar":""},{"name":"Rome Flynn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
