INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('with-love-phan-2', 'With Love (Phần 2)', 'With Love (Season 2)', 'with love (phần 2) with love (season 2) emeraude toubia mark indelicato rome flynn ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-bao-thu-bo-bo-vi-ham', 'Cô Dâu Báo Thù (Bộ Bộ Vi Hạm)', 'Bride''s Revenge', 'https://phimimg.com/upload/vod/20240209-1/d8e46d379719167593d8100e4c6d2d20.jpg', 'https://phimimg.com/upload/vod/20240209-1/8689f3012247b46b12bb3bc47e652a53.jpg', '<p>Hai anh em nhà họ Mộ thành hôn cùng một ngày, song hỉ lâm môn. Không ngờ rằng cô dâu Diệp Thanh Lam của nhị thiếu gia nhà họ Mộ - Mộ An Hòa – lại là người yêu cũ của đại thiếu gia Mộ An Thừa. Không những thế, Mộ lão phu nhân xem Diệp Thanh Lam như “sao chổi”, suốt ngày đánh mắng cô. Diệp Thanh Khanh, người vừa là chị họ vừa là chị dâu, lại ném đá giấu tay, ngay cả Tri Hạ - nha hoàn bên cạnh nhị thiếu gia - cũng có thái độ không tốt với cô. Diệp Thanh Lam chịu đủ mọi dày vò, tủi nhục chỉ mong được ở bên cạnh Mộ An Hòa để trả ơn, nhưng không ngờ Mộ An Hòa lại bị giết. Diệp Thanh Lam đem lòng phẫn nộ, thù hận trút hết lên Mộ An Thừa và hai người phụ nữ bên cạnh hắn ta. Cho dù gặp nhiều khó khăn, cô vẫn muốn đánh đổi tất cả, tính toán từng bước để trả thù.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngụy Thiên Hạo","avatar":""},{"name":"Đại Cao Chính","avatar":""},{"name":"Khuất Mộng Nhữ","avatar":""},{"name":"Đổng Nhan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
