INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-dau-bao-thu-bo-bo-vi-ham', 'Cô Dâu Báo Thù (Bộ Bộ Vi Hạm)', 'Bride''s Revenge', 'cô dâu báo thù (bộ bộ vi hạm) bride''s revenge ngụy thiên hạo đại cao chính khuất mộng nhữ đổng nhan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-nuong-khe-uoc', 'Tân Nương Khế Ước', 'My Everlasting Bride', 'https://phimimg.com/upload/vod/20240209-1/f42a8c2f7cb435a6e9460de12b449453.jpg', 'https://phimimg.com/upload/vod/20240209-1/049be60ee7459eaf512c82a7dfde9c39.jpg', '<p>Vốn là ngày hôn lễ hạnh phúc giữa doanh nhân giàu có Shen và lãnh chúa Nie, nhưng cô cả Shen và cô dâu Qing Xia bất ngờ bị giết. Vẫn muốn tiến hành cuộc hôn nhân béo bở, người giúp việc Hu Die của gia đình Shen buộc phải giả làm Qing Xia để trả thù cho cô và kết hôn với Nie Zhen, một nguyên soái trẻ của gia đình Nie. Tuy nhiên, khi Hu Die phát hiện ra rằng hung thủ bị nghi ngờ, về cái chết của cô gái của cô và tất cả những lời gợi ý, đều chỉ thẳng vào Nie Zhen, cô càng trở nên sợ hãi và không chắc chắn về việc tiến hành theo kế hoạch ban đầu. Đặc biệt, dần dần, cô thực sự yêu Nie Zhen, và ngày càng nhìn thấy tính cách tốt bụng và lương thiện của anh. Nhưng liệu cô ấy có nhìn thấy Nie Zhen thật hay cô ấy đang dần rơi vào bẫy của anh ta?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ke Ying","avatar":""},{"name":"Cavan Wen","avatar":""},{"name":"Ke Bo Lun","avatar":""},{"name":"Angel Niu","avatar":""},{"name":"Ming Yue","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324256);
