INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tharntype-the-series-1-tu-ghet-toi-yeu', 'TharnType The Series 1: Từ Ghét Tới Yêu', 'TharnType 1', 'https://phimimg.com/upload/vod/20240209-1/fc814f245c0f6a0cace4549e31747808.jpg', 'https://phimimg.com/upload/vod/20240209-1/4dde165c3388efe1d1600516583081d5.jpg', '<p>Type là một sinh viên năm nhất đẹp trai và thân thiện, yêu bóng đá, nhưng lại kỳ thị tình yêu đồng tính và ghét những người đồng tính vì quá khứ đen tối, đau khổ của mình. Cuộc sống của cậu bị đảo lộn khi cậu biết đượcngười bạn cùng phòng đầy sức hút, Tharn (cũng là sinh viên năm nhất và là nhạc sĩ) thật ra là người đồng tính. Type làm mọi cách để đuổi Tharn ra khỏi cuộc đời cậu, trong khi Tharn cố gắng chứng minh rằng người đồng tính cũng là người bình thường. Tharn sẽ biến sự ghét bỏ của Type thành tình yêu?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mew Suppasit Jongcheveevat","avatar":""},{"name":"Gulf Kanawut Traipipattanapong","avatar":""},{"name":"Kaownah Kittipat Kaewcharoen","avatar":""},{"name":"Kokliang Parinya Angsanan","avatar":""},{"name":"Run Kantheephop Sirorattanaphanit","avatar":""},{"name":"Tong Thanayut Thakoon-auttaya","avatar":""},{"name":"Mild Suttinut Uengtrakul","avatar":""},{"name":"Hiter Natthad Kunakornkiat","avatar":""},{"name":"Mawin Tanawin Duan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324256);
