INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-lake-phan-2', 'The Lake (Phần 2)', 'The Lake (Season 2)', 'https://phimimg.com/upload/vod/20240205-1/072b70b51b653f71df809e8263f85f62.jpg', 'https://phimimg.com/upload/vod/20240205-1/eeb8f48444535c4daee456012d7df193.jpg', '<p>Justin quyết tâm làm cho mùa hè này trở nên tuyệt vời nhất. Thật không may, kế hoạch của anh ta tan thành mây khói khi pháo hoa của anh ta làm nổ tung nhà thuyền. Mọi người đổ lỗi cho Justin, nhưng anh ấy biết mình vô tội. Anh chỉ cần chứng minh điều đó. Mẹ của Maisy, Mimsy, xuất hiện để cùng gia đình trải qua mùa hè “cuối cùng” của cô ấy. Và Billie gặp cả một người trồng cây xinh đẹp và một nhà hoạt động khí hậu, những người cũng đe dọa sẽ thổi bay mùa hè của cô ấy.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Brielle Robillard","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
