INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-hiem-nguy', 'Vượt Qua Hiểm Nguy', 'Dangerous Waters', 'https://phimimg.com/upload/vod/20240308-1/d8bf6e646312df09f272313405592ead.jpg', 'https://phimimg.com/upload/vod/20240308-1/f436bfeaf8944e76c8f0770ab6b5768a.jpg', '<p>Phim kể về cô gái Rose sống cùng với người mẹ Alma sau khi cha của cô qua đời. Trong chuyến đi chơi mà Rose thấy không hào hứng khi có sự tham gia của Derek, người bạn trai mới quen của mẹ, những điều tồi tệ đã xảy đến. Chiếc thuyền của họ đã bị tấn công, Alma bị bắn chết và chỉ còn Derek và Rose giúp đỡ lẫn nhau để sống sót. Tuy nhiên, cô nàng nhanh chóng phát hiện ra sự bất thường ở Derek, Rose buộc phải tìm ra mục đích thực sự của hắn ta trước khi quá muộn.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Odeya Rush","avatar":""},{"name":"Eric Dane","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Roy Elghanayan","avatar":""},{"name":"Terrence Julien","avatar":""},{"name":"Sala Baker","avatar":""},{"name":"Alexya Garcia","avatar":""},{"name":"Omid Zader","avatar":""},{"name":"Trenton Rostedt","avatar":""},{"name":"Brian Duffy","avatar":""},{"name":"Peter Brooke","avatar":""},{"name":"Thalia Besson","avatar":""},{"name":"Yira Urena","avatar":""},{"name":"Matt Servitto","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
