INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wedding-plan-ke-hoach-yeu-den-toi-cua-chu-re', 'Wedding Plan: Kế Hoạch Yêu Đen Tối Của Chú Rể', 'Wedding Plan (Un-cut)', 'https://phimimg.com/upload/vod/20240205-1/0abc91c621fefabdd2183674696dbd04.jpg', 'https://phimimg.com/upload/vod/20240205-1/3501df6a509f7e37ba425149fa91ce0f.jpg', '<p>Nhà tổ chức tiệc cưới chuyên nghiệp Nam Nuea được giao nhiệm vụ lo liệu đám cưới giữa doanh nhân trẻ đẹp trai Sailom và cô dâu hoàn hảo Yiwa. Nhưng chuyện gì sẽ xảy ra khi Nam Nuea phát hiện ra rằng đám cưới mà anh dự định chỉ là một sự sắp đặt và Yiwa đã có người yêu tên là Marine? Mối quan hệ giữa chú rể và nhà thiết kế ngày càng thân thiết, câu chuyện sẽ ra sao?</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Sunny Wannarat Wattadalimma","avatar":""},{"name":"Pak Naphat Leelahatorn","avatar":""},{"name":"Aya Orapan Phongmaykin","avatar":""},{"name":"Kate Sasisarun Phiboonrattapong","avatar":""},{"name":"Forth Kashane Pichetsopon","avatar":""},{"name":"Donut Supawit Thongyuen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
