INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-minh-ruc-ro', 'Chuyển Mình Rực Rỡ', 'The Magical Women', 'https://phimimg.com/upload/vod/20240205-1/eca826cc2072b0b40a1b99c89e35728e.jpg', 'https://phimimg.com/upload/vod/20240205-1/3beab2e271f06c65edecbe749510d3dd.jpg', '<p>Tô Phi \thông minh\ và An Ninh \tàn nhẫn\ có cảm tình với nhau. Họ cùng nhau đương đầu với nỗi đau gia đình Tô Phi tan vỡ và cùng nhau bắt đầu một cuộc sống mới. Họ luôn dành cho nhau sự ấm áp, Tô Phi phát hiện ra quá khứ không rõ của An Ninh, khiến hai người lại trải qua sóng gió. Chấp nhận số phận với lòng bao dung là dấu hiệu cho thấy sự trưởng thành của người phụ nữ; tất nhiên, nếu bạn xúc phạm tôi, tôi sẽ bắt bạn phải trả lại - có lẽ đây là câu chuyện cuộc đời mà họ phải học.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Lam","avatar":""},{"name":"Deng Jiajia","avatar":""},{"name":"Trương Quân Ninh","avatar":""},{"name":"Wu Xiao Liang","avatar":""},{"name":"Ning Sun","avatar":""},{"name":"Tian Yi Tong","avatar":""},{"name":"Jeff Bao","avatar":""},{"name":"Hu Ke","avatar":""},{"name":"Tian-Yang Zhang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324256);
