INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-guom-tru-ta', 'Thanh Gươm Trừ Tà', 'Dr. Cheon and the Lost Talisman', 'https://phimimg.com/upload/vod/20240305-1/64e5efc279d1bd3a8eaa5afff575e145.jpg', 'https://phimimg.com/upload/vod/20240305-1/0a906a75221810f51cc79288238011c9.jpg', '<p>Chuyện phim xoay quanh nhân vật thầy trừ tà Cheon (Gang Dong Won thủ vai), cùng với chiến hữu của mình In Bae (Lee Dong Hwi thủ vai), chuyên đi lừa đảo với những màn trừ tà “pha ke&quot; sử dụng công nghệ cao cùng khả năng hùng biện và tài “thao túng tâm lý&quot; đỉnh cao. Tuy chuyên đi trừ tà nhưng cả hai đều không thể nhìn thấy và không tin vào ma quỷ cho tới khi họ phải đối đầu với một con ác quỷ thật đang khống chế em gái (Park So Yi thủ vai) của Yoo Kyung (Esom thủ vai). Yoo Kyung sở hữu “đôi mắt âm dương” có thể nhìn thấy những linh hồn. Kết hợp với thầy trừ tà Cheon và In Bae, họ phải đối đầu với con ác quỷ thật sự - Beom Cheom (Huh Joon Ho thủ vai) và từ đó, thầy trừ tà Cheon vô tình khám phá được bí mật đằng sau cái chết của em trai và ông nội mình. Nhận được sự giúp đỡ của một nhân vật bí ẩn cùng với những pha hành động trừ tà đẹp mắt, liệu thầy trừ tà Cheon có giúp được em gái của Yoo Kyung và diệt trừ ác quỷ đó?</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Gang Dong-won","avatar":""},{"name":"Heo Joon-ho","avatar":""},{"name":"Esom","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Park So-yi","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Joo Bo-bi","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Lee Kyu-ho","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Kim Jisoo","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Park Myung-hoon","avatar":""},{"name":"Cho Yi-hyun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324256);
