INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-thu-ky-nha-tu', 'Nữ Thư Ký Nhà Tù', 'Eileen', 'https://phimimg.com/upload/vod/20240305-1/ab32ff30b67faa360fb25a4428c8b442.jpg', 'https://phimimg.com/upload/vod/20240305-1/7b318fa7105bbb5f4954a37163ee36a6.jpg', '<p>Mùa đông buốt giá ở Massachusetts năm 1964, nhà tù nơi cô thư ký trẻ Eileen làm việc vừa tiếp nhận một cố vấn mới - Rebecca Saint John. Tình bạn chớm nở giữa họ rẽ sang hướng khác khi Rebecca tiết lộ một bí mật đen tối — đẩy Eileen vào con đường hung hiểm.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Thomasin McKenzie","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Sam Nivola","avatar":""},{"name":"Marin Ireland","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Tonye Patano","avatar":""},{"name":"William Hill","avatar":""},{"name":"Owen Teague","avatar":""},{"name":"Peter McRobbie","avatar":""},{"name":"Peter Von Berg","avatar":""},{"name":"Patrick Noonan","avatar":""},{"name":"Jefferson White","avatar":""},{"name":"Alexander Jameson","avatar":""},{"name":"Patrick Ryan Wood","avatar":""},{"name":"Gavin K. Barfi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324256);
