INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suc-manh-tien-le', 'Sức Mạnh Tiền Lẻ', 'Dumb Money', 'https://phimimg.com/upload/vod/20231023-1/caaa3dd696b30344791afded6889092a.jpg', 'https://phimimg.com/upload/vod/20231023-1/f0f79fbc4e405f30297508bfc6eb4cd6.jpg', '<p>Bộ phim Sức Mạnh Tiền Lẻ kể về những người hàng ngày lật ngược kịch bản ở Phố Wall và trở nên giàu có bằng cách biến GameStop (Cửa hàng trò chơi điện tử ở trung tâm thương mại) thành công ty hấp dẫn nhất thế giới. Không chỉ được lấy cảm hứng từ cuốn sách nổi tiếng, bộ phim còn dựa trên câu chuyện có thật xảy ra vào năm 2021 tại phố Wall với sự trỗi dậy của GameStop từ một công ty điện tử vô danh trở thành một cái tên &quot;hot nhất&quot; khu tài chính.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Dano","avatar":""},{"name":"Shailene Woodley","avatar":""},{"name":"America Ferrera","avatar":""},{"name":"Pete Davidson","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Myha''la Herrold","avatar":""},{"name":"Talia Ryder","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Rushi Kota","avatar":""},{"name":"Kate Burton","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Olivia Thirlby","avatar":""},{"name":"Dane DeHaan","avatar":""},{"name":"Larry Owe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324256);
