INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xu-huong-tim-kiem', 'Xu Hướng Tìm Kiếm', 'Trending Topic', 'https://phimimg.com/upload/vod/20240305-1/8bd4e50874a1eafa9b0aa82c6aff33b1.jpg', 'https://phimimg.com/upload/vod/20240305-1/f482221cddf3e225d9b8d83e39e0f558.jpg', '<p>Sau khi Trần Miêu, một người nổi tiếng trong chuyện tình cảm với hàng chục triệu fan hâm mộ đặt tiêu đề “Kẻ bắt nạt trường học” trên tweet của mình như một chủ đề tìm kiếm nóng, cô đã nhận được tin nhắn kẻ bắt nạt thực ra là người bị hại từ người lạ. Dần dần chân tướng được lộ diện, đó là một cuộc chiến tranh chính nghĩa về quyền lực và tôn nghiêm.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhou Dongyu","avatar":""},{"name":"Song Yang","avatar":""},{"name":"Yuan Hong","avatar":""},{"name":"Wang Hao","avatar":""},{"name":"Tao Hai","avatar":""},{"name":"Shi Rui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
