INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-ngo-thien-duyen', 'Kỳ Ngộ Thiên Duyên', 'Tale Of Phantom: A Love Story', 'https://phimimg.com/upload/vod/20240305-1/2fd68d32bdeec8b6370cfc40e9516eda.jpg', 'https://phimimg.com/upload/vod/20240305-1/a1fab4f6f9c76cffbc3888de12fc566b.jpg', '<p>Phim kể về hai bộ tộc con người và linh hồn cùng tồn tại trong một thế giới. Thế nhưng họ lại có mâu thuẫn và hận thù từ ngàn đời nay, họ đối xử tàn nhẫn, ko nhân nhượng cho nhau. Trên đường về sau nhiều năm học tập, học giả Trần Tài Ninh đã gặp linh nữ Thanh Nữ. Qua thời gian gặp gỡ và tiếp xúc, tình cảm giữa họ bắt đầu nảy nở, họ tin tưởng nhau, dũng cảm bước đi, chiến đấu chống lại toàn bộ linh tộc, không sợ hãi trước cái chết, tất cả đã dàn dựng nên một câu chuyện cảm động về tình yêu xuyên sắc tộc</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Kelong","avatar":""},{"name":"Shang Xuan","avatar":""},{"name":"Yang Qingzhu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324256);
