INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-huong-cang-2-long-tranh-ho-dau', 'Trùm Hương Cảng 2: Long Tranh Hổ Đấu', 'Extras for Chasing The Dragon', 'https://phimimg.com/upload/vod/20240305-1/1aa7667542c62061535bac99152b7046.jpg', 'https://phimimg.com/upload/vod/20240305-1/e81ce95f29d6542c6c21e450b1220914.jpg', '<p>Phim kể về câu chuyện của 3 kẻ là Ngũ Quốc Hào, Đại Tiểu Uy và anh em thuở nhỏ vượt từ Quảng Đông đến Hồng Kông để kiếm sống và được Từ Nhạc - vị thám trưởng cẩn trọng mười phần coi trọng, vẽ nên câu chuyện hắc bạch lưỡng đạo tranh đấu trong thời kỳ sau ở Hong Kong.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jordan Chan","avatar":""},{"name":"Vincent Wong","avatar":""},{"name":"Raquel Xu","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Dominic Ho","avatar":""},{"name":"Alex Lam Chi-Sin","avatar":""},{"name":"Yun QianQian","avatar":""},{"name":"Gui Jingjing","avatar":""},{"name":"Zhang Xinjie","avatar":""},{"name":"Zhao Fanghua","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324256);
