INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-mang-xa', 'Đại Chiến Mãng Xà', 'Battle of Snakes', 'https://phimimg.com/upload/vod/20240305-1/bdbb754e0e928e88f4d9dc9a8f8531d6.jpg', 'https://phimimg.com/upload/vod/20240305-1/94ea451b2bc2d4f0ed1f404e9bfb3790.jpg', '<p>Đại Chiến Mãng Xà – Battle of Snakes (2023) kể về Lâm Hạo Đông và người bạn Mã Đằng, là quản lý của một vườn thú đang đối diện với nguy cơ phá sản. Để cứu vãn tình hình, họ đã ký hợp đồng với ông Lão Ngô để tổ chức một sự kiện trình diễn động vật nước ngoài quy mô lớn. Con gái của Lâm Hạo Đông, Bánh Bao, mắc bệnh tự kỉ giả, ít nói chuyện, thích ở cùng khỉ. Lâm Hạo Đông quyết định nhân cơ hội này để đưa con gái đi du lịch biển, sau đó họ lên một con tàu du lịch sang trọng. &nbsp;Thực tế, họ không biết rằng ông Lão Ngô là một tay buôn quốc tế, lợi dụng việc vận chuyển động vật để chuyển hàng loạt nước thải ô nhiễm nặng từ nước ngoài ra biển, kiếm lợi từ việc này. Nước thải gây biến đổi gen đối với sinh vật biển sống gần đó, trong đó có một con rắn khổng lồ. Rắn bất ngờ tấn công, tàu đột ngột trải qua một cuộc biến động, động vật trong công viên liên tục biến đổi, và mọi người phải làm thế nào để thoát khỏi hiểm nguy, mọi điều vẫn chưa rõ ràng…</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wei Wei","avatar":""},{"name":"Shen Taoran","avatar":""},{"name":"Shao Shuai","avatar":""},{"name":"Cheng Qi","avatar":""},{"name":"John Ching Tung","avatar":""},{"name":"Naomen Eerdeni","avatar":""},{"name":"Guo Zhen","avatar":""},{"name":"Xu Xiaoqin","avatar":""},{"name":"Zhu Haijun","avatar":""},{"name":"Liu Lu","avatar":""},{"name":"Xu Min","avatar":""},{"name":"Cai Guolong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
