INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-sat-so-0', 'Truy Sát Số 0', 'The Comeback', 'https://phimimg.com/upload/vod/20240305-1/a63bba24185646792cc4ecd950b5bd05.jpg', 'https://phimimg.com/upload/vod/20240305-1/dc00090b1be32bca08eebd5b6301d920.jpg', '<p>Chú Hoa sống ở phố cổ từ nhiều năm nay, từ làng trên xóm dưới ai cũng yêu quý và kính trọng. Cuộc sống của chú phụ thuộc vào việc bán đồ cổ. &quot;Có khó khăn, tìm chú Hoa&quot; trở thành câu cửa miệng của người trong xóm. Nhưng vì một vụ giao dịch đất đai, phố cổ bị băng Thanh Long tấn công. Trong cửa hàng đồ cổ của chú Thúc, tình cờ sao đã phát hiện ra 6 xác chết, 7 hộ chiếu và vũ khí. Sự việc này khiến mọi người hoảng sợ, và những điều này đều được lão Tào sống lang thang ở phố cổ bắt được... Đồng thời, chú Thúc bị tổ chức bí ẩn do chủ lĩnh là A Kiệt đứng đầu truy đuổi. Vậy chú Thúc thật sự là ai? Mọi thứ dần rối tung rối mù cả lên.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Andy On","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Jiang Peiyao","avatar":""},{"name":"Mu Lei","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
