INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-im-lang', 'Quyền Im Lặng', 'Miranda''s Victim', 'https://phimimg.com/upload/vod/20240305-1/65a112b9fc181e24ac6b96f615ba4a75.jpg', 'https://phimimg.com/upload/vod/20240305-1/3ee5232144adee5d782468e2d2739025.jpg', '<p>Năm 1963, Trish Weir, mười tám tuổi, bị bắt cóc và cưỡng hiếp dã man. Cam kết đưa kẻ tấn công mình, Ernesto Miranda, vào tù, cuộc sống của cô gái trẻ bị hủy hoại bởi hệ thống pháp luật của Mỹ tuy nhiên đây cũng là cơ hội để giúp tạo ra một quy tắc cực kỳ quan trọng trong ngành tư pháp ngày nay, thường được biết đến với cái tên &quot;Quyền Im lặng&quot; hay &quot;cảnh báo Miranda&quot;</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Abigail Breslin","avatar":""},{"name":"Emily VanCamp","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Sebastian Quinn","avatar":""},{"name":"Andy García","avatar":""},{"name":"Mireille Enos","avatar":""},{"name":"Joshua Bowman","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Enrique Murciano","avatar":""},{"name":"Brent Sexton","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Nolan Gould","avatar":""},{"name":"Josephine Hies","avatar":""},{"name":"Benjamin Chamberlain","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324256);
