INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-ta-on-kinh-hoang', 'Lễ Tạ Ơn Kinh Hoàng', 'Thanksgiving', 'https://phimimg.com/upload/vod/20240305-1/f2824015f688414a7ef23c71a567d77e.jpg', 'https://phimimg.com/upload/vod/20240305-1/47b1369065e93a59f760fbf4fb261cd4.jpg', '<p>Sau khi cuộc náo động Black Friday kết thúc bằng một bi kịch, một kẻ giết người bí ẩn, được lấy cảm hứng từ ngày Lễ Tạ Ơn, gieo rắc nỗi kinh hoàng tại Plymouth, Massachusetts - nơi sinh ra lễ hội này. Lần lượt lấy đi tính mạng của những người dân, những vụ án trả thù ban đầu đã được tiết lộ là một phần nhỏ của một âm mưu lễ hội đen tối và to lớn hơn thế. Liệu thị trấn này có thể tìm ra kẻ giết người và sống sót qua mùa lễ... hay trở thành những vị khách tại bàn ăn lễ hội tàn ác của hắn?</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Dempsey","avatar":""},{"name":"Nell Verlaque","avatar":""},{"name":"Addison Rae","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Lynne Griffin","avatar":""},{"name":"Karen Cliche","avatar":""},{"name":"Rick Hoffman","avatar":""},{"name":"Derek McGrath","avatar":""},{"name":"Katherine Trowell","avatar":""},{"name":"Jalen Thomas Brooks","avatar":""},{"name":"Mika Amonsen","avatar":""},{"name":"Amanda Barker","avatar":""},{"name":"Shailyn Griffin","avatar":""},{"name":"Tim Dillon","avatar":""},{"name":"Chris Sandiford","avatar":""},{"name":"Tomaso Sanel","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
