INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('see-hear-love', 'SEE HEAR LOVE', 'SEE HEAR LOVE', 'https://phimimg.com/upload/vod/20240219-1/c40aa51c6418cf7e52f5f4fd4c820c13.jpg', 'https://phimimg.com/upload/vod/20240219-1/80e9255215dcf138ade66890bf465b7c.jpg', '<p>Họa sĩ truyện tranh Shinji Izumoto đã giành được hợp đồng làm phim. Lẽ ra anh ấy nên ăn mừng, nhưng anh ấy sắp bị mù, bộ truyện tranh của anh ấy đã bị hủy bỏ và anh ấy không thể chăm sóc cho bà của mình được nữa. Một mình, Shinji đưa ra quyết định tàn khốc là nhảy khỏi ban công. Khi Hibiki Aida, một người hâm mộ khiếm thính của anh ấy, cứu Shinji, họ bắt đầu một cuộc sống khác thường cùng nhau.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tomohisa Yamashita","avatar":""},{"name":"Yuko Araki","avatar":""},{"name":"Mahiro Takasugi","avatar":""},{"name":"Maika Yamamoto","avatar":""},{"name":"Motoki Fukami","avatar":""},{"name":"Sayaka Yamaguchi","avatar":""},{"name":"Mari Natsuki","avatar":""},{"name":"Dai Watanabe","avatar":""},{"name":"Masaya Kato","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324256);
