INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-duc-hoi-sinh', 'Sắc Dục Hồi Sinh', 'Poor Things', 'https://phimimg.com/upload/vod/20240304-1/fbd64393f6f377939922481e4228e812.jpg', 'https://phimimg.com/upload/vod/20240304-1/d8ba8fca16be1971c47cd15cf81f3935.jpg', '<p>Chuyện phim kể về một phụ nữ trẻ tên Bella (Emma Stone), sống ở thế kỷ 19. Sau khi tự sát, cô được một nhà khoa học hồi sinh bằng cách đặt vào đầu cô bộ não của trẻ sơ sinh. Bella bỏ trốn và gặp gỡ Duncan Wedderburn (Mark Ruffalo) một luật sư có lối sống phóng túng, trụy lạc. Trong cuộc hành trình phiêu lưu này, Bella đã có những phát hiện mới về bản thân mình, trong đó có những phát hiện đến từ trải nghiệm... tình dục của cô.&nbsp;</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324256);
