INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-trieu', 'Nộ Triều', 'Wolf Hiding', 'https://phimimg.com/upload/vod/20240303-1/aa0be3b0c819716982591a18b0cc02e6.jpg', 'https://phimimg.com/upload/vod/20240303-1/62184f343c9d7e794d389ca5441f1e4c.jpg', '<p>Tập đoàn Hồng Thái vượt qua ranh giới đen trắng và một tay che trời đang bược vào thời điểm thay đổi bầu cử, một sát thủ bí ẩn Trần An (do Trương Gia Huy thủ vai) đột nhiên một mình đột nhập vào vòng xoáy hỗn loạn đúng sai này, gây ra sự hỗn loạn trong tập đoàn Hồng Thái. Mai Long Văn (do Nguyễn Kinh Thiên thủ vai) trong trại cảnh sát và Mã Văn Khang (do Vương Đại Lục thủ vai) trong trại băng đảng cũng đang để mắt tới anh ta ... Tất cả thế lực đều đang chờ cơ hội, kẻ thao túng đằng sau hậu trường là ai? Một cuộc hỗn chiến khốc liệt sắp nổ ra.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nick Cheung","avatar":""},{"name":"Ethan Juan","avatar":""},{"name":"Darren Wang","avatar":""},{"name":"Danny Chan Kwok-kwan","avatar":""},{"name":"Chen Xiaoyi","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Xinlin He","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Andrew Lin","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Marc Ma","avatar":""},{"name":"Lawrence Ng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324256);
