INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tuong', 'Thần Tượng', 'The Idol', 'https://phimimg.com/upload/vod/20240302-1/4f6b42c8fb959380c214edd2424bfce4.jpg', 'https://phimimg.com/upload/vod/20240302-1/a85b36c863331af198c7dcc1af1b51bd.jpg', '<p>Sau cơn suy nhược thần kinh phá tan chuyến lưu diễn cuối cùng của Jocelyn, cô quyết tâm khẳng định lại vị thế là danh ca nhạc pop vĩ đại và quyến rũ nhất nước Mỹ. Niềm đam mê của cô được khơi dậy bởi Tedros, một ông bầu hộp đêm có quá khứ rắc rối. Liệu sự thức tỉnh đầy chất thơ này sẽ đưa cô lên tới tầm cao mới huy hoàng hay dìm cô xuống sâu thẳm trong tâm hồn?</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"The Weeknd","avatar":""},{"name":"Lily-Rose Depp","avatar":""},{"name":"Suzanna Son","avatar":""},{"name":"Troye Sivan","avatar":""},{"name":"Jane Adams","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
