INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiem-doat', 'Chiếm Đoạt', 'Black Rose', 'https://phimimg.com/upload/vod/20240301-1/f80ab3623d6d9bdba796dbb0aaa408a6.jpg', 'https://phimimg.com/upload/vod/20240301-1/76adf138697c721b094a2c6aac1ae78b.jpg', '<p>Kể về người vợ của một gia đình thượng lưu thuê cô bảo mẫu “trong mơ” để chăm sóc con trai mình. Nhưng cô không ngờ rằng, phía sau sự trong sáng, tinh khiết kia, cô bảo mẫu luôn che giấu âm mưu nhằm phá hoại hạnh phúc gia đình và khiến cuộc sống của cô thay đổi mãi mãi.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Miu Lê","avatar":""},{"name":"Lãnh Thanh","avatar":""},{"name":"Karik","avatar":""},{"name":"Phương Anh Đào","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324256);
