INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngay-hoan-hao', 'Những Ngày Hoàn Hảo', 'Perfect Days', 'https://phimimg.com/upload/vod/20240301-1/c62ec514afaa3d8914d2aebb6e59f2c3.jpg', 'https://phimimg.com/upload/vod/20240301-1/1e7cdbc20c4f368fb36d71fb08359291.jpg', '<p>Perfect Days là một bộ phim điện ảnh của đạo diễn Wim Wenders, kể về cuộc sống của một người lau dọn nhà vệ sinh ở Tokyo, người có niềm đam mê với âm nhạc và sách. Bộ phim được dựa trên bốn truyện ngắn và có sự tham gia của diễn viên Kōji Yakusho. Bộ phim được công chiếu tại Liên hoan phim Cannes năm 2023 và nhận được nhiều đánh giá tích cực từ giới phê bình.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Koji Yakusho","avatar":""},{"name":"Arisa Nakano","avatar":""},{"name":"Aoi Yamada","avatar":""},{"name":"Tokio Emoto","avatar":""},{"name":"Yumi Asou","avatar":""},{"name":"Sayuri Ishikawa","avatar":""},{"name":"Tomokazu Miura","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Miyako Tanaka","avatar":""},{"name":"Long Mizuma","avatar":""},{"name":"Soraji Shibuya","avatar":""},{"name":"Aoi Iwasaki","avatar":""},{"name":"Kisuke Shimazaki","avatar":""},{"name":"Yuriko Kawasaki","avatar":""},{"name":"Aki Kobayashi","avatar":""},{"name":"Bunmei Harada","avatar":""},{"name":"Reina","avatar":""},{"name":"Shunsuke Miura","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
