INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-cuc-han', 'Vùng Đất Cực Hàn', 'The Antarctic Octopus', 'https://phimimg.com/upload/vod/20240207-1/bb8bfd7812b8c3ad2a4b71d7b0a4db50.jpg', 'https://phimimg.com/upload/vod/20240207-1/3e8c8577d8437f47dc23bf647cdd93a4.jpg', '<p>Bạch tuộc khổng lồ biển sâu Nam Cực đã trả thù Phòng thí nghiệm Khoa học Quốc tế Nam Cực vì các hoạt động nghiên cứu thương mại của cơ quan này bị lợi ích con người che mắt. Hàn Liên một thành viên của đội vận chuyển Nam Cực, đã bị mắc kẹt trong thảm họa này, và đã chiến đấu với con bạch tuộc khổng lồ để trốn thoát cùng với Rosa và đồng đội của cô ấy là Cường Tử, cuối cùng họ đã trốn thoát được.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"JOE","avatar":""},{"name":"Chen Ruo Xi","avatar":""},{"name":"Zhu Tian Fu","avatar":""},{"name":"Ryan","avatar":""},{"name":"Xingchen Wang","avatar":""},{"name":"Shao hung Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324256);
