INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-biet-doi-nhan-ban-dac-biet-phan-2', 'Star Wars: Biệt Đội Nhân Bản Đặc Biệt (Phần 2)', 'Star Wars: The Bad Batch (Season 2)', 'https://phimimg.com/upload/vod/20240229-1/f86ff89bfebe039cfe2c0d439bb783c4.jpg', 'https://phimimg.com/upload/vod/20240229-1/6a591fd1e911f881c5efdcbc9771c62c.jpg', '<p>The Bad Batch là một đội đặc biệt được biến đổi gene để có khả năng đặc biệt hơn người bình thường. Đội này chuyên có những nhiệm vụ đặc biệt mà thậm chí Jedi mới có thể làm, thường những nhiệm vụ này trên trình Clone bình thường. Trong phần 7 vừa rồi, The Bad Batch đã xuất hiện để hỗ trợ Anakin và Rex cứu lấy Echo. Tuy nhiên vì khác biệt với phần còn lại nên Echo đã đi cùng The Bad Batch để khác biệt cùng họ.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dee Bradley Baker","avatar":""},{"name":"Michelle Ang","avatar":""},{"name":"Ming-Na Wen","avatar":""},{"name":"Stephen Stanton","avatar":""},{"name":"Andrew Kishino","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324256);
