INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-trai-hoa-bich', 'Liêu Trai Họa Bích', 'Liaozhai Painting Wall', 'https://phimimg.com/upload/vod/20240205-1/8196afaf57ec9be06cd746fbe7539968.jpg', 'https://phimimg.com/upload/vod/20240205-1/829ebe342b7a1222bca343c47177b908.jpg', '<p>Thông qua những bức bích họa trong ngôi đền cổ, Chu Tiếu Liêm họa sĩ số một ở Giang Nam, bước vào thế giới tranh bích họa nơi yêu ma sinh sống, anh gặp Vi Sinh người phụ nữ đầu tiên muốn mà anh muốn đích thân vẽ tranh cho cô, nhưng không ngờ lại phá vỡ âm mưu của yêu chim. Trong quá trình chiến đấu với yêu chim, họ yêu nhau và biết được rằng thân thế thật của Vi Sinh thực chất là Phượng Hoàng và cách duy nhất để đánh bại yêu chim là giúp Vi Sinh niết bàn.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hàn Đống","avatar":""},{"name":"Liu Meng Meng","avatar":""},{"name":"Di Yi Shu","avatar":""},{"name":"Daniella Wang","avatar":""},{"name":"Yang Yi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324256);
