INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-ta', 'Trừ Tà', 'Exorcism', 'https://phimimg.com/upload/vod/20240228-1/99ab654c8c70fe0ea7f69559ba3d78ee.jpg', 'https://phimimg.com/upload/vod/20240228-1/825b4b69d84a4b7181599df050c9f108.jpg', '<p>Những năm đầu của Trung Hoa Dân Quốc, chính quyền nhà Thanh suy đồi bị cách mạng lật đổ, tư tưởng dân chủ tiến bộ lan rộng khắp Trung Hoa. Tuy nhiên tình hình lúc đó vẫn rất hỗn loạn, dân chúng chưa hiểu biết, nạn thất học, phát triển yếu kém, niềm tin và lối tư duy phong kiến vẫn tràn ngập trong xã hội Trung Hoa. Con trai của Vương Chí Trương, một cảnh sát ở Trung Hoa Dân Quốc đã chết vì thuốc phiện, ông căm ghét xã hội cũ nơi tội ác tràn lan và tư tưởng phong kiến đầu độc người dân. Để kết thúc vấn đề này, ông đã cải trang thành một đạo sĩ, xâm nhập vào nhà của doanh nhân địa phương Trần lão để điều tra vụ buôn lậu thuốc phiện.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Zhen","avatar":""},{"name":"Qiaoqiao Jin","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"Wei Zi Qian","avatar":""},{"name":"Cao Nan","avatar":""},{"name":"Jin Zi He","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Lau Nam Kwong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
