INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('justice-league-x-rwby-super-heroes-huntsmen-part-one', 'Justice League X RWBY: Super Heroes & Huntsmen, Part One', 'Justice League X RWBY: Super Heroes & Huntsmen, Part One', 'https://phimimg.com/upload/vod/20240228-1/679df7c04c22b036d03e7f0effdd24ac.jpg', 'https://phimimg.com/upload/vod/20240228-1/fef1c51026fb36332adb847a66519c69.jpg', '<p>Superman, Batman, Wonder Woman, Flash, Cyborg, Green Lantern và Vixen được đưa đến thế giới kỳ lạ của Remnant và thấy mình bị biến thành những thiếu niên. Trong khi đó, các anh hùng còn sót lại Ruby, Weiss, Blake và Yang phải kết hợp lực lượng với Justice League để khám phá lý do tại sao hành tinh của họ lại bị thay đổi một cách bí ẩn trước khi Grimm siêu mạnh phá hủy mọi thứ.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Natalie Alyn Lind","avatar":""},{"name":"Chandler Riggs","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"Lindsay Jones","avatar":""},{"name":"Kara Eberle","avatar":""},{"name":"Arryn Zech","avatar":""},{"name":"Barbara Dunkelman","avatar":""},{"name":"Ozioma Akagha","avatar":""},{"name":"David Errigo Jr.","avatar":""},{"name":"Jeannie Tirado","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324256);
