INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('make-me-scream', 'Make Me Scream', 'Make Me Scream', 'https://phimimg.com/upload/vod/20240228-1/865d76d5b828e583b55fe0cf9642aaaf.jpg', 'https://phimimg.com/upload/vod/20240228-1/d2ce921840feaed340c3b884fac160f5.jpg', '<p>Trong chương trình đặc biệt Halloween kinh hoàng vui nhộn này do Tempestt Bledsoe và Darryl M. Bell tổ chức, ba đội nổi tiếng do Jaleel White, Shoniqua Shandai và Lil’ Xan dẫn đầu, bắt tay vào một trò chơi khủng bố khủng khiếp. Một trò chơi mà họ phải đối mặt với hàng loạt khu vực kinh hãi đến thấu xương trong khi cố gắng KHÔNG hét lên! Đội có số điểm thấp nhất sẽ sống sót qua đêm và mang về Huân chương Mayhem danh giá.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tempestt Bledsoe","avatar":""},{"name":"Darryl M. Bell","avatar":""},{"name":"Jaleel White","avatar":""},{"name":"Shoniqua Shandai","avatar":""},{"name":"Lil Xan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324256);
