INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-vung-dat-cua-cac-vi-than-va-toi-nhan', 'Ở Vùng Đất Của Các Vị Thần Và Tội Nhân', 'In The Land Of Saints And Sinners', 'https://phimimg.com/upload/vod/20240228-1/fffafb938dc077d718cd48d2ee01d491.jpg', 'https://phimimg.com/upload/vod/20240228-1/00feeca509ec3330959c7800995cfa52.jpg', '<p>Tại một ngôi làng xa xôi ở Ireland, Finbar bị tổn thương buộc phải chiến đấu để được cứu chuộc sau một đời tội lỗi, nhưng anh sẵn sàng trả cái giá nào? Ở vùng đất của thánh nhân và tội nhân, có một số tội lỗi không thể chôn vùi.&nbsp;</p>', 'Full', 1, 'single', 'completed', 30, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Sarah Greene","avatar":""},{"name":"Jack Gleeson","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Conor MacNeill","avatar":""},{"name":"Desmond Eastwood","avatar":""},{"name":"Seamus O''Hara","avatar":""},{"name":"Niamh Cusack","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
