INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-nha-cua-chappelle-luenell-thi-tran-chung-toi', 'Đội Nhà Của Chappelle – Luenell: Thị Trấn Chúng Tôi', 'Chappelle''s Home Team - Luenell: Town Business', 'https://phimimg.com/upload/vod/20240228-1/c774666ab2a2dc39f21c657f2e6a7b58.jpg', 'https://phimimg.com/upload/vod/20240228-1/96b6ca553d6344f2cad6f7a5d60e2b07.jpg', '<p>Trong tiết mục độc thoại đặc biệt này, hãy thắt dây an toàn khi Luenell bàn về người ngồi cùng ghế tồi tệ, ác cảm hạng nhất, em bé không đi tất và nhiều rủi ro khác khi đi du lịch.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luenell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324256);
