INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-11-bien-mat', 'Tầng 11 Biến Mất', 'THE LOST 11TH FLOOR', 'https://phimimg.com/upload/vod/20240118-1/70759b62f83d8e49cd70d29cb1ecd8b7.jpg', 'https://phimimg.com/upload/vod/20240118-1/661e81127efcaddf9663fd4249749d4b.jpg', '<p>Một tập báo cáo của Tập đoàn Cự Luân nổi tiếng ở thành phố Thương Hải đã che đậy sự thật về vụ tai nạn hầm mỏ, khiến phó cục trưởng Khúc Giang Hà (do Phan Việt Minh thủ vai) trở thành tâm điểm trong cuộc chiến trừ gian diệt ác này. Cuốn vào cuộc điều tra, anh mới hay hóa ra cuộc chiến trắng đen vốn chẳng phân rõ hai màu đen trắng. Vì biết bao lợi ích mà đối thủ, bạn bè và thậm chí cả cấp trên của anh đều yêu cầu anh che đậy chân tướng thật sự, mà nữ cục trưởng mới được bổ nhiệm Nghiêm Cáp (do Trần Sác thủ vai) lại không ngờ thực tế lại tàn khốc và hoành tráng đến vậy. Che đậy là tội ác còn nghiêm trọng hơn cả phạm tội.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Pan Yue Ming","avatar":""},{"name":"Chen Shu","avatar":""},{"name":"Guo Jing Lin","avatar":""},{"name":"Li Hong Tao","avatar":""},{"name":"Vạn Bằng","avatar":""},{"name":"Tim","avatar":""},{"name":"Sun Yan","avatar":""},{"name":"Trần Hạo Lam","avatar":""},{"name":"Wang Zheng","avatar":""},{"name":"Liu Shuai Liang","avatar":""},{"name":"Roy","avatar":""},{"name":"Zhu Hui","avatar":""},{"name":"Li Sheng Ye","avatar":""},{"name":"Han Yun Yun","avatar":""},{"name":"Zhang Chao","avatar":""},{"name":"Benjamin Zhang","avatar":""},{"name":"He Tie Hong","avatar":""},{"name":"Zhao Cheng Shun","avatar":""},{"name":"Wang Li Yun","avatar":""},{"name":"Zhang Hong Jie","avatar":""},{"name":"Zhao Cheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324256);
