INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tang-11-bien-mat', 'Tầng 11 Biến Mất', 'THE LOST 11TH FLOOR', 'tầng 11 biến mất the lost 11th floor pan yue ming chen shu guo jing lin li hong tao vạn bằng tim sun yan trần hạo lam wang zheng liu shuai liang roy zhu hui li sheng ye han yun yun zhang chao benjamin zhang he tie hong zhao cheng shun wang li yun zhang hong jie zhao cheng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-sac-tieu-than-y', 'Tuyệt Sắc Tiểu Thần Y', 'Ms. Fantastic Miracle Doctor', 'https://phimimg.com/upload/vod/20240220-1/089856366a6fe15cda7bbfb179b5fac3.jpg', 'https://phimimg.com/upload/vod/20240220-1/f9a67627510e6f0b5d0ed949f3fe8e24.jpg', '<p>Trong sự cố rò điện của bệnh viện, Giản Mạch - bác sĩ châm cứu nổi tiếng thời hiện đại - vô tình xuyên không vào Nguyệt Vô Nhan của Phượng Loan quốc, khi tỉnh dậy phát hiện mình trúng đao trên bụng, nằm gục nơi đồng hoang, còn vô tình quen biết nam chính Phong Khuynh Thành, từ đây mở ra một mối tình hài hước đầy yếu tố ngẫu nhiên. Khi bác sĩ hiện đại có y thuật cao minh gặp công tử tà mị bí ẩn, nữ giả nam trang quyền mưu cung đình, tình yêu sai chỗ đã âm thầm bước đến.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
