INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuyet-sac-tieu-than-y', 'Tuyệt Sắc Tiểu Thần Y', 'Ms. Fantastic Miracle Doctor', 'tuyệt sắc tiểu thần y ms. fantastic miracle doctor  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khanh-khanh-tam-tu', 'Khanh Khanh Tam Tư', 'The Deliberations of Love', 'https://phimimg.com/upload/vod/20240206-1/e4266de0103e70604c5c2ee5895f7eb8.jpg', 'https://phimimg.com/upload/vod/20240206-1/8ab4bcdafde19cf8ff8fb2959a1822b5.jpg', '<p>Lục Thanh là một người phụ nữ hiện đại, trong một lần tai nạn, linh hồn cô đã xuyên không tới thân xác của Sở Thanh - một cô gái thời cổ đại sắp bị ép hôn. Trải qua lần xuyên không đầu tiên, Lục Thanh không có thời gian để ngăn chặn, cô bị ép uống rượu độc và chết. Lần thứ hai xuyên không, Lục Thanh đã kịp ngăn cản kẻ giết người nhưng lại bị đồng phạm của hắn ám sát. Lần thứ ba trở về ngay trước đêm đính hôn, Lục Thanh quyết tâm thay đổi số phận, cô trước tiên đã sử dụng trí thông minh của mình để thoát khỏi một tai nạn, sau đó lại dùng kiến thức y học của mình để chiếm được lòng tin của những người quan trọng ở triều đình. Lục Thanh kết bạn trong cung và cuối cùng đã làm Hoàng đế nhận ra sự oan ức của cô, từ bỏ cuộc hôn nhân này. Trong quá trình tham gia vào việc triều đình, Lục Thanh cũng đã gặp một thanh niên vì oan ức mà vào kinh, hai người trải qua nhiều sự cố, hỗ trợ lẫn nhau và cuối cùng đã tạo nên một câu chuyện tình yêu đẹp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Jiamin","avatar":""},{"name":"Richard Li","avatar":""},{"name":"Yu Mingjia","avatar":""},{"name":"李季","avatar":""},{"name":"Yu Yangzi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
