INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nguoc-ba-giay-de-yeu-em', 'Đếm Ngược Ba Giây Để Yêu Em', 'Falling In Love With Me', 'https://phimimg.com/upload/vod/20240208-1/fa42d6c8d176e75452d4e5ce9e30229a.jpg', 'https://phimimg.com/upload/vod/20240208-1/70e84d76308ef029b2971d4c15e46fb0.jpg', '<p>Đồng Vũ Tâm sở hữu một sợi dây chuyền thần kỳ khiến cho người khác phải lòng cô trong một giờ đồng hồ. Nụ hôn ngoài ý muốn giữa cô và Đường Vũ Đồng khiến sợi dây chuyền chuyển qua người đối phương. Đồng Vũ Tâm mất đi phép thuật phải trở về nguyên trạng, nóng lòng muốn tiếp cận Đường Vũ Đồng để lấy lại sợi dây chuyền. Một bài học lãng mạn về tình yêu và âm nhạc cứ thế bắt đầu, quá khứ về mối tình đầu gửi gắm nhầm chỗ cũng được đưa ra ánh sáng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"康汐","avatar":""},{"name":"Zhi Liu","avatar":""},{"name":"Meng En","avatar":""},{"name":"Sun Xuening","avatar":""},{"name":"Gu Landi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
