INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-6-ngay-13-2023', 'Thứ 6 Ngày 13', 'Fear', 'https://phimimg.com/upload/vod/20240228-1/a4e6965dd07c1e18380174a9bde9a733.jpg', 'https://phimimg.com/upload/vod/20240228-1/f669ffcf809f835cd716bd08c7b21457.jpg', '<p>Nhóm bạn thân lên kế hoạch cho một kỳ nghỉ cuối tuần vui vẻ, nhưng nào ngờ rằng đó đã trở thành cơn ác mộng thực sự khi hàng loạt sự kiện khủng khiếp xảy ra ở nơi họ dừng chân.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joseph Sikora","avatar":""},{"name":"Ruby Modine","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Andrew Bachelor","avatar":""},{"name":"Annie Ilonzeh","avatar":""},{"name":"T.I.","avatar":""},{"name":"Terrence Jenkins","avatar":""},{"name":"Jessica Allain","avatar":""},{"name":"Tyler Abron","avatar":""},{"name":"Mezi Atwood","avatar":""},{"name":"Bayardo De Murguia","avatar":""},{"name":"Mario Fernandez","avatar":""},{"name":"Whylip Lee","avatar":""},{"name":"Chanel Gaines","avatar":""},{"name":"Michelle McCormick","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
