INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-va-toi', 'Tuổi Trẻ Và Tôi', 'Young People And Their Youth Of China', 'https://phimimg.com/upload/vod/20240227-1/df9ba0fc67b5b00e348c42438e6f3208.jpg', 'https://phimimg.com/upload/vod/20240227-1/c572c781fb7f266d591f5ec7c7ffdb5a.jpg', '<p>Bộ phim kể lại ba câu chuyện về những người thanh niên trong thời kỳ khai hoang phía Bắc, thời kỳ phát triển miền Tây Trung Quốc, thời kỳ mới xã hội chủ nghĩa. Vô số những người trẻ đầy nhiệt huyết đã hòa nhập lý tưởng cá nhân vào dòng chảy phát triển của thời đại, viết nên những bài hát tuổi trẻ với đầy nhiệt huyết. Bộ phim dùng câu chuyện tuổi trẻ của những con người bình thường để phác họa nên sự phát triển vượt bậc của thời đại, làm nổi bật tình cảm đối với gia đình, đất nước của biết bao thế hệ thanh niên.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yixing","avatar":""},{"name":"Wang Yibo","avatar":""},{"name":"Zhou Dongyu","avatar":""},{"name":"Yu Haoming","avatar":""},{"name":"Xing Fei","avatar":""},{"name":"Aaron Deng","avatar":""},{"name":"Monica Mok","avatar":""},{"name":"Boogie Wang","avatar":""},{"name":"Zhang Ruonan","avatar":""},{"name":"Song Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
