INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-ngu', 'Nhân Ngư', 'The Mermaid', 'https://phimimg.com/upload/vod/20240207-1/b6855f5c31db0ee8dad7f5881c85645c.jpg', 'https://phimimg.com/upload/vod/20240207-1/0f1d38c41ee731a7d22419fd857de37a.jpg', '<p>Hướng Dương là tiên cá được con người nuôi dưỡng, anh sinh ra đã có hai giới tính, khác biệt với người thường, luôn cảm thấy cô độc. Truyền thuyết kể rằng họ có thể điều khiển mọi đàn cá và chữa lành mọi vết thương, thậm chí còn có tin đồn rằng họ sẽ thay đổi giới tính của mình chỉ khi gặp được tình yêu đích thực, đời này mãi làm một đôi quyến lữ. Một ngày nọ, anh cảm nhận được tin tức của giống loài từ viên huyết ngọc của Lục Giai Giai, vì muốn về nhà, anh cố ý tiếp cận cô nhưng dần dần bị cô thu hút, vì cô mà xác định giới tính của mình. Từ đó họ cùng nhau bảo vệ vùng biển xanh mát này bằng tình yêu,bảo vệ ngôi nhà chung của đôi tình lữ...</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Huan","avatar":""},{"name":"Chen Hao Ming","avatar":""},{"name":"Lee Li-Chun","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Xin Lu","avatar":""},{"name":"Ren Qingnamu","avatar":""},{"name":"Sun Yi Ming","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324256);
