INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('samurai-mat-xanh', 'Samurai Mắt Xanh', 'Blue Eye Samurai', 'https://phimimg.com/upload/vod/20240219-1/0f680cb234dfb7526882f9ba530fefa9.jpg', 'https://phimimg.com/upload/vod/20240219-1/3ca4d17c18ead169a57954db695c58a4.jpg', '<p>Khát khao trả thù những kẻ đã khiến cô bị ruồng bỏ ở Nhật Bản thời Edo, nữ chiến binh trẻ nọ dấn thân vào con đường đẫm máu dẫn tới số mệnh của mình.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Maya Erskine","avatar":""},{"name":"George Takei","avatar":""},{"name":"Masi Oka","avatar":""},{"name":"Cary-Hiroyuki Tagawa","avatar":""},{"name":"Brenda Song","avatar":""},{"name":"Darren Barnet","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Kenneth Branagh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324256);
