INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-quan-o-duoi', 'Tướng Quân Ở Dưới', 'My Lady General', 'https://phimimg.com/upload/vod/20240209-1/819505ba0218170bf87ac58f80f10a2c.jpg', 'https://phimimg.com/upload/vod/20240209-1/c0516c06035bd72f0f931ddbdbd3536b.jpg', '<p>Để rửa sạch nỗi oan cho tiên thái tử, Ngụy Lẫm - nữ tướng quân thô lỗ mù chữ đã dùng phương thức hại địch một nghìn hại mình tám trăm để cầu hôn Cố Minh Châu - công tử đẹp trai ốm yếu của Cố gia. Không ngờ công tử đẹp trai ốm yếu là giả, kẻ phản diện điên cuồng vì tình yêu mới là thật. Các chủ Lệnh Các độc ác tàn nhẫn - Giang Quyện - giả làm Cố Minh Châu, gả vào phủ tướng quân để trộm Viêm ngọc chữa bệnh, không ngờ lại phải đền cả tấm chân tình của mình.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Qiru","avatar":""},{"name":"Cheng-Xuan Shih","avatar":""},{"name":"Xiang Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
