INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuan-khung-hoang', 'Tuần Khủng Hoảng', 'The Wonder Weeks', 'https://phimimg.com/upload/vod/20240128-1/286bb7f4c2f921419ff1393412d4deee.jpg', 'https://phimimg.com/upload/vod/20240128-1/bef798c9b1d853431e0c4353ba1a7a3c.jpg', '<p>Ba cặp đôi hiện đại xoay xở trước các mối quan hệ và sự nghiệp đòi hỏi khắt khe trong khi đương đầu với hành trình làm cha mẹ đầy khó đoán.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Sallie Harmsen","avatar":""},{"name":"Soy Kroon","avatar":""},{"name":"Yolanthe Cabau","avatar":""},{"name":"Iliass Ojja","avatar":""},{"name":"Sarah Chronis","avatar":""},{"name":"Katja Schuurman","avatar":""},{"name":"Louis Talpe","avatar":""},{"name":"Fenna Ramos","avatar":""},{"name":"Sjaak","avatar":""},{"name":"Frederik Brom","avatar":""},{"name":"Rachida Iaallala","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
