INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuan-khung-hoang', 'Tuần Khủng Hoảng', 'The Wonder Weeks', 'tuần khủng hoảng the wonder weeks sallie harmsen soy kroon yolanthe cabau iliass ojja sarah chronis katja schuurman louis talpe fenna ramos sjaak frederik brom rachida iaallala ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-thien-vung-cam', 'Già Thiên: Vùng Cấm', 'Forbidden Zone', 'https://phimimg.com/upload/vod/20240128-1/0ea4d78a47da22889b2ad55ce0c3b8bc.jpg', 'https://phimimg.com/upload/vod/20240128-1/3a7081fccd5275ed31515f4471b3b29e.jpg', '<p>Bầu trời giao hòa, hiện tượng kỳ lạ xuất hiện, trong vũ trụ, chín con rồng kéo chiếc quan khổng lồ bằng đồng ngọc lướt qua vùng sao Bắc Đẩu, và địa điểm cấm kỵ của cuộc sống, hòn đảo Chôn Thiên xuất hiện. Người ta đồn rằng trên hòn đảo Chôn Thiên ẩn chứa kho báu của đế quyền, có thể giúp các võ sĩ nâng cao đáng kể thực lực của họ. Các môn phái lớn và các hành hương tại vùng sao Bắc Đẩu đều tụ họp tại Thiên Đình Vịnh Trời để lên đảo tìm báu vật, trong đó có một người trẻ mồ côi tên là Hư Không. Hư Không từ nhỏ đã được người sư phụ nhận nuôi ở Tòng Lâu, sư phụ nhận thấy tài năng đặc biệt của cậu nên đã trả giá rất lớn để rèn luyện hàng triệu thanh kiếm, mới có thể gửi cậu vào Thiên Đình Vịnh Trời luyện tập. Lần này khi Chôn Thiên Đảo xuất hiện, Hư Không cùng với các đồ đệ trong Tòng Lâu đã lên đảo để cạnh tranh báu vật, khám phá con đường trở thành Đế vương. Nhưng ai ngờ trên hòn đảo Chôn Thiên, hoang dã kỳ lạ xuất hiện, trong các hang động vô số bí mật kín đáo, lớn nhất trong hàng ngàn năm trôi qua lại là một âm mưu đen tối</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feng Lijun","avatar":""},{"name":"Peng Gaochang","avatar":""},{"name":"Gao Shuguang","avatar":""},{"name":"Nan Sikai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324257);
