INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-thien-qua-hai', 'Man Thiên Quá Hải', 'The Invisible Guest', 'https://phimimg.com/upload/vod/20240212-1/a017a263f8d21b898d7178e0c9beade4.jpg', 'https://phimimg.com/upload/vod/20240212-1/b66e087d2c6046a27a4556b49134da0c.jpg', '<p>Nhiều năm xây dựng sự nghiệp ở phía đông Malaysia, Kiều Văn Na bị cuốn vào một vụ án giết người kỳ bí trong một mật thất. Phó trưởng cảnh sát Trịnh Uy đề xuất một thỏa thuận với bằng chứng mà ông ta đang giữ để giúp Kiều Văn Na thoát khỏi án buộc. Khi giao dịch diễn ra, cả hai lần lượt kiểm tra từng bước, sự thật gây sốc về hai vụ án giết người cuối cùng cũng được đưa ra ánh sáng.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Greg Hsu","avatar":""},{"name":"Janine Chang","avatar":""},{"name":"Yin Zheng","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Qian Yi","avatar":""},{"name":"Li Feng","avatar":""},{"name":"Maiqian Guo","avatar":""},{"name":"Xue Xuchun","avatar":""},{"name":"Hamza Al-sal","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324257);
