INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pit-babe-the-series', 'Pit Babe The Series', 'Pit Babe The Series', 'https://phimimg.com/upload/vod/20240206-1/edc9d05a3448411f4babd113ea3cd0da.jpg', 'https://phimimg.com/upload/vod/20240206-1/8e61edb46efff78c520cd633cba19743.jpg', '<p>Kể về mối quan hệ phức tạp giữa Babe-tay đua xe nổi tiếng với danh hiệu, vua đường đua, và Charlie- một mọt sách gợi cảm với ước mơ được gia nhập một đội đua. Charlie muốn tham gia đội đua đến mức đồng ý với lời đề nghị kỳ lạ của Babe để là trở thành nô lệ của cậu. Khi Babe đánh mất trái tim của mình cho Charlie, cậu ta liên tục phát hiện ra rằng mối quan hệ không như cậu mong đợi, và mục đích thực sự của Charlie khi tiếp cận cậu là để tiêu diệt cậu.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pavel Naret Promphaopun","avatar":""},{"name":"Pooh Krittin Kitjaruwannakul","avatar":""},{"name":"Nut Supanut Lourhaphanich","avatar":""},{"name":"Ping Obrnithi Leelavetchabutr","avatar":""},{"name":"Benz Atthanin Thaninphanuwiwat","avatar":""},{"name":"Lee Asre Wattanayakul","avatar":""},{"name":"Pon Thanapon Aiemkumchai","avatar":""},{"name":"Sailub Hemmawich Kwanamphaiphan","avatar":""},{"name":"Pantach Kankham","avatar":""},{"name":"TopTen Supa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324257);
