INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-chi-la-moi-quan-he-thue-chung-nha', 'Không Chỉ Là Mối Quan Hệ Thuê Chung Nhà', 'Not Just Flatmates', 'https://phimimg.com/upload/vod/20240118-1/2d3bba925126b34de4039d71729acaa0.jpg', 'https://phimimg.com/upload/vod/20240118-1/0c24bb4481f40a503e6bae3aade4247c.jpg', '<p>Lấy tinh thần khởi nghiệp của giới trẻ làm chủ đề, phim kể về câu chuyện tự kinh doanh của bốn người trẻ Xin Fan, Hua Qianjin, Su Du và Mi Ming, những người dũng cảm tiến về phía trước với ước mơ. Trong vở kịch, có những nhân viên bình thường làm việc chăm chỉ, những ông chủ quán trà sữa có ước mơ, những giám đốc công ty đầy nhiệt huyết và những cô gái dễ thương chịu khó chịu khó, họ là đại diện cho tinh thần khởi nghiệp của giới trẻ, họ xuống lầu ăn fan và lên lầu phải làm thêm giờ, động lực để phấn đấu là tinh thần cầu tiến không ngừng, là tình bạn đùm bọc giúp đỡ lẫn nhau, là tình thương yêu sẻ chia khó khăn. Với ước mơ của riêng mình, họ vượt qua khó khăn và dũng cảm tiến lên phía trước!</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đinh Cảnh Nghĩa","avatar":""},{"name":"Trương Tân Di","avatar":""},{"name":"Chu Quân Thần","avatar":""},{"name":"Cha Yichen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324257);
