INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-hang-tap-hoa-tinh-yeu-van-nang', 'Cửa Hàng Tạp Hóa Tình Yêu Vạn Năng', 'Love Magic Grocery', 'https://phimimg.com/upload/vod/20240111-1/58ac0143b1ad690c1dd5e751fadfed92.jpg', 'https://phimimg.com/upload/vod/20240111-1/4a57af7f860db4b95cb59f9ebc30b419.jpg', '<p>Phiên bản lãng mạn của &quot;Doraemon&quot; sắp ra mắt! Quản lý cửa hàng phù thủy A Sơ sử dụng nhiều đạo cụ tình yêu giả tưởng khác nhau để giúp con người giải quyết các vấn đề tình yêu, nhưng đã bị cảnh sát trưởng Juye mặt lạnh điều tra và truy đuổi. Không chỉ có những &quot;trò chơi mèo vờn chuột&quot; thú vị, trí tưởng tượng hoang dã, thiết kế nghệ thuật thời thượng và thú vị mà còn có những chủ đề tình yêu hấp dẫn và thú vị! Cửa hàng tạp hóa Universal Love đang chờ bạn đến ~</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324257);
