INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-thuoc-tri-mua-2', 'Có Thuốc Trị (Mùa 2)', 'Are You OK? (Season 2)', 'https://phimimg.com/upload/vod/20240104-1/b7fa7d4c9d53264cd31986c3b9e20a6e.jpg', 'https://phimimg.com/upload/vod/20240104-1/7233844efb19f9ffe6c0ea5cf14350bc.jpg', '<p>Câu chuyện diễn ra trong một thế giới tưởng tượng được gọi là Đại Lương, nơi nhiều người dân sau khi qua đời, linh hồn của họ lại bị chiếm đoạt bởi các linh hồn từ hai ngàn năm sau, biến họ trở thành những xuyên không giả. Những xuyên không giả này không chỉ mang đến cho Đại Lương kiến thức và kinh nghiệm tiên tiến, mà còn khiến Hoàng đế thời đó sợ hãi và thận trọng. Trong bão táp thăng trầm, Lâu Chủ -một xuyên không giả ủng hộ hòa bình đã gặp gỡ và kết thân với thiếu chủ Tả Vân của Bàng Môn, cố gắng tìm con đường tiến bộ và sự hòa hợp cho tất cả mọi người. Tuy nhiên, mâu thuẫn giữa triều đình và những người đi xuyên thời gian dòng cách nguy hiểm đã leo thang. Trong một vụ nổ, Lâu Chủ, vì để ngăn cản họ xem xét bị thương mà không may bị vùi dưới đống đổ nát, và từ đó về sau, không ai biết ông còn sống hay đã chết. Nửa năm trôi qua một cách nhanh chóng. Dựa vào cơ hội từ vụ nổ, Hoàng đế chính thức ra lệnh loại bỏ tất cả những người đi xuyên thời gian, trong khi tổ chức “Tiên phong” do Tiêu Giao Nhiên dẫn đầu có ý định lật đổ quyền lực hoàng gia và dựa vào vũ khí hiện đại để dẫn đầu trong chiến tranh. Cả hai bên đều tập trung vào một mục tiêu quan trọng - Lâu Chủ, nhân vật chính trong những câu chuyện tra dư tửu hậu chốn giang hồ…</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324257);
