INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-quan-x-duong-an-tri-menh', 'Phá Quân X: Đương Án Trí Mệnh', 'Legend Of Alkaid', 'https://phimimg.com/upload/vod/20240123-1/5172d3ddbd4b6bc954f13825498c2f74.jpg', 'https://phimimg.com/upload/vod/20240123-1/6ae6a5737e936e73489dd6508efaa6b9.jpg', '<p>Vào những năm đầu của Trung Hoa Dân Quốc, Tiêu Kiện một cậu bé mơ ước trở thành thám tử số một ở Thượng Hải, trong quá trình điều tra hàng loạt vụ án bí ẩn, cậu vô tình chạm vào cái gọi là sự cố kiểm soát của họ. Anh trở thành thành viên của Cục Điều tra Đặc biệt một cách khó hiểu.Một loạt các sự kiện ly kỳ, kỳ lạ và hồi hộp đã chiếm lấy mật danh \Broken Army\ và trở thành một người bảo vệ vô danh.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Shuang Li","avatar":""},{"name":"Sarah","avatar":""},{"name":"Zhao Ying Zi","avatar":""},{"name":"Bai Yun Feng","avatar":""},{"name":"Mu Lan","avatar":""},{"name":"Ken Lok","avatar":""},{"name":"Xu Zhan Wei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324257);
