INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-nong-la-gan-chu-heo', 'Làm Nóng Lá Gan Chú Heo', 'Butareba -The Story of a Man Turned Into a Pig-', 'https://phimimg.com/upload/vod/20240208-1/fe3d0f5512c4fc1d52caacd59d0d4894.jpg', 'https://phimimg.com/upload/vod/20240208-1/b7a84f178dcf74d026ca793771896838.jpg', '<p>Một gã mọt sách bị đau bụng dữ dội dẫn đến &#39;bất tỉnh nhân sự&#39; rồi tử vong ngay sau khi nốc một đĩa gan lợn sống. Khi tỉnh dậy, còn chưa kịp cảm thấy biết ơn vì được tái sinh ở một thế giới khác thì ổng chợt nhận ra mình CHỈ LÀ MỘT CON LỢN! Anh ta trở thành một con lợn, thậm chí không thể nói được mà chỉ phát ra âm thanh như tiếng lợn kêu. &quot;Không ổn rồi, vậy chẳng phải ham muốn của một con lợn đang chảy trong người tôi sao?&quot;. May sao, sau đó anh gặp một cô gái ngây thơ, xinh đẹp như thiên thần tên là Jess. Nhờ vào khả năng đọc được suy nghĩ nên Jess có thể hiểu được điều main chính muốn nói. Sự tương tác thú vị này đã khiến họ trở thành bạn bè...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Tomori Kusunoki","avatar":""},{"name":"Kent Ito","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Mamiko Noto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
