INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tot-thanh-doi', 'Chuyện Tốt Thành Đôi', 'Alliance', 'https://phimimg.com/upload/vod/20240206-1/e748509c4b42ad0d773f4d76e98677f1.jpg', 'https://phimimg.com/upload/vod/20240206-1/b2215b1bc76eb4438418fb8c12a75d6c.jpg', '<p>Lâm Thẩm Du là sinh viên xuất sắc của một trường đại học hàng đầu, cuối cùng lại trở thành một bà mẹ toàn thời gian. Nhưng cô đã bị phản bội và phải quay trở lại lực lượng lao động để đấu tranh giành quyền nuôi con. Trong tâm trạng nhếch nhác, cô gặp Cố Húc, bạn học cũ và hiện là một tài năng hải ngoại. Cô đối mặt với thử thách với Jiang Xi và Gu Xu, biến thành một người nội trợ chuyên nghiệp và yêu Gu Xu. Lin Shuang và Jiang Xi trải qua quá trình trưởng thành cá nhân, mở ra cuộc sống mới của riêng họ.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Xiaofei","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Zhang Jiani","avatar":""},{"name":"Li Zefeng","avatar":""},{"name":"Zhao Xin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
