INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-quoc-gia', 'Chiến Dịch: Quốc Gia', 'Operation: Nation', 'https://phimimg.com/upload/vod/20240121-1/26950fb2c518e8681a9f3836a77018f4.jpg', 'https://phimimg.com/upload/vod/20240121-1/5a7f66a19237cb613bc97f905abb8777.jpg', '<p>Một thành viên trong một nhóm theo chủ nghĩa dân tộc ở Warsaw bước vào chuyện tình bị cấm đoán với một nhà hoạt động cánh tả đầy nhiệt huyết, dẫn đến hàng loạt sự kiện bất ngờ.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Maciej Musiałowski","avatar":""},{"name":"Borys Szyc","avatar":""},{"name":"Magdalena Maścianica","avatar":""},{"name":"Antoni Królikowski","avatar":""},{"name":"Karol Kadłubiec","avatar":""},{"name":"Mateusz Król","avatar":""},{"name":"Karol Bernacki","avatar":""},{"name":"Piotr Cyrwus","avatar":""},{"name":"Aleksandra Justa","avatar":""},{"name":"Adam Cywka","avatar":""},{"name":"Dominika Walo","avatar":""},{"name":"Cezary Pazura","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
