INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kisi-ka-bhai-kisi-ki-jaan', 'Kisi Ka Bhai Kisi Ki Jaan', 'Kisi Ka Bhai... Kisi Ki Jaan', 'https://phimimg.com/upload/vod/20240108-1/f0fdd758c022c9ffbab1128bb0f92cd3.jpg', 'https://phimimg.com/upload/vod/20240108-1/e1dff562cc2bff8425873db3e07dcc52.jpg', '<p>Bhaijaan, một huấn luyện viên tự vệ sống hạnh phúc như một người độc thân với ba anh em Moh, Ishq và Luv và sử dụng bạo lực để dàn xếp thỏa thuận. Khi các anh trai của anh ấy, những người đã tìm được bạn đời, cùng nhau sắp xếp một trận đấu cho anh ấy, Bhagya Lakshmi, Bhaijaan quyết định sửa đổi con đường của mình vì lợi ích của người yêu. Tất cả như vỡ òa khi anh biết được gia đình của Bhagya đang phải đối mặt với những mối đe dọa từ quá khứ đầy ám ảnh của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Pooja Hegde","avatar":""},{"name":"Venkatesh","avatar":""},{"name":"Jagapati Babu","avatar":""},{"name":"Jassie Gill","avatar":""},{"name":"Siddharth Nigam","avatar":""},{"name":"Raghav Juyal","avatar":""},{"name":"Shehnaaz Gill","avatar":""},{"name":"Palak Tiwari","avatar":""},{"name":"Vinali Bhatnagar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
