INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-danh', 'Vô Danh', 'Hidden Blade', 'https://phimimg.com/upload/vod/20240108-1/3e3759e4620dceb716d5067efd734aa8.jpg', 'https://phimimg.com/upload/vod/20240108-1/945d5d4774f4de6976caa2ff0cefc0fd.jpg', '<p>Ngày 7 tháng 12 năm 1941, Nhật Bản tấn công Trân Châu Cảng. Ngày hôm sau, Chính phủ Vương giả tuân theo lời tuyên chiến của Nhật Bản với Anh và Hoa Kỳ, và Nhật Bản chiếm đóng toàn bộ Thượng Hải một cách tượng trưng. Với sự bùng nổ của Chiến tranh Thái Bình Dương, tình hình nỗ lực chiến tranh của Trung Quốc đã thay đổi hoàn toàn. Các thành viên của Đảng Cộng sản Trung Quốc đã mạo hiểm gửi thông tin để phá vỡ hòa bình giữa Nhật Bản và Tưởng và để bảo vệ tổ quốc.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Wang Yibo","avatar":""},{"name":"Zhou Xun","avatar":""},{"name":"Eric Wang","avatar":""},{"name":"Huang Lei","avatar":""},{"name":"Dong Chengpeng","avatar":""},{"name":"Maggie Jiang","avatar":""},{"name":"Zhang Jingyi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324257);
