INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-danh', 'Vô Danh', 'Hidden Blade', 'vô danh hidden blade tony leung chiu-wai wang yibo zhou xun eric wang huang lei dong chengpeng maggie jiang zhang jingyi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-bang-quan', 'Kẻ Bàng Quan', 'The Spectator', 'https://phimimg.com/upload/vod/20240119-1/43d16fa76443375779a244fad86f3064.jpg', 'https://phimimg.com/upload/vod/20240119-1/45f1ad3cc4d20ace726a8f5686fc1095.jpg', '<p><span style="text-wrap: nowrap;">Phim trinh thám “Kẻ bàng quan” là màn đấu trí cam go giữa cảnh sát và sát thủ liên hoàn. Phim cũng khiến người xem suy ngẫm về căn bệnh “vô cảm” trong xã hội hiện nay. Thái độ coi mình như người ngoài cuộc, thờ ơ, lãnh đạm của một số người, đã vô tình gây ra nhiều hậu quả đáng tiếc.</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Nữ cảnh sát Diêu Tự Như (Vương Mẫn Dịch đóng) mắc chứng nhạy cảm cao. Nếu như socola giúp cô giải tỏa căng thẳng và cân bằng cảm xúc, thì nước chanh muối lại có thể đồng loạt “bật công tắc” năm giác quan trong cô. Như tận dụng điều này để phá án. Sau khi uống chanh muối, rồi nhìn vào, sờ vào thi thể, vật chứng, Như có khả năng cảm ứng, đi vào suy nghĩ của nạn nhân hoặc hung thủ, khôi phục hiện trường ban đầu của vụ án. Nhờ chứng siêu nhạy cảm này, cô nhanh nhạy phát hiện những manh mối mà người khác dễ bỏ qua.</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Vương Mịch Hy (Châu Bách Hào đóng) – chủ tiệm cà phê Rabbit Cave, một người luôn ôn hòa, niềm nở. Hy rất biết cách quan sát để thấu hiểu khách, giúp họ cảm thấy dễ chịu và thư giãn mỗi khi đến quán. Tuy thích lắng nghe câu chuyện của mọi người nhưng anh lại hiếm khi chia sẻ về mình.</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Như tình cờ quen biết Hy khi cô tìm đến Rabbit Cave để điều tra về một vụ án. Mỗi lần trò chuyện với anh, những khúc mắc trong cô rất mau chóng được tháo gỡ. Họ dần trở nên thân thiết.</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Sau hai vụ án mà nạn nhân đều bị người ngoài cuộc gián tiếp hại chết, thì nhiều án mạng khác cũng liên tiếp xảy ra, mục tiêu của hung thủ là những kẻ sống nhởn nhơ ngoài vòng pháp luật. Dựa vào ký hiệu mà hung thủ để lại ở hiện trường, Như tin rằng kẻ sát nhân là cùng một người. Cô và sát thủ liên hoàn nhiều phen “cân não” nhằm đoán định tâm lý và hành động tiếp theo của đối phương. Khi chân tướng dần lộ diện, Như cảm thấy mình và hắn ta dường như tâm ý tương thông nhưng lập trường đối lập...</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Ly kỳ, lôi cuốn, 20 tập phim “Kẻ bàng quan”, phát sóng độc quyền và đồng thời với TVB lúc 21 giờ, thứ Hai đến thứ Sáu, từ ngày 01/01/2024, trên kênh SCTV9. Dàn diễn viên tham gia trong phim: Vương Mẫn Dịch, Châu Bách Hào, Ngô Nhược Hy, La Thiên Vũ, Mã Quán Đông, Liên Thi Nhã, Hồ Bội Úy, Tạ Đông Mẫn, Châu Chí Khang, Đặng Y Đình,...</span></p><p><span style="text-wrap: nowrap;">Nguồn: SCTV9</span></p><p><br/></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 2023, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Pakho Chau","avatar":""},{"name":"Venus Wong","avatar":""},{"name":"Shiga Lin","avatar":""},{"name":"Jinny Ng","avatar":""},{"name":"Mark Ma","avatar":""},{"name":"Joey Law","avatar":""},{"name":"Wong Ka-Lok","avatar":""},{"name":"Nicole Wan See Pui","avatar":""},{"name":"Brian Tse Tung Man","avatar":""},{"name":"Hero Yuen","avatar":""},{"name":"Janice Ting","avatar":""},{"name":"Joan Lee Wing-Yee","avatar":""},{"name":"Tai Wai To","avatar":""},{"name":"Daniel Chau","avatar":""},{"name":"Benjamin Yuen Wai-Ho","avatar":""},{"name":"Rosita Kwok","avatar":""},{"name":"Kayan Choi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324257);
