INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tri-tue-thu-nghiem', 'Trò Chơi Trí Tuệ - Thử Nghiệm', 'Mind Games - The Experiment', 'https://phimimg.com/upload/vod/20240104-1/f4c12bb4226d10d8549f99f439a18035.jpg', 'https://phimimg.com/upload/vod/20240104-1/b96ecf1368fa80b7cbf486a99b6e8d63.jpg', '<p>Tập thể dục có thể mài giũa những bộ óc thông minh nhất không? Trong thử nghiệm mang tính đột phá này, bốn game thủ đẳng cấp thế giới, thi đấu trong Thể thao điện tử, Cờ vua, Mạt chược và Trò chơi trí nhớ, đã thử nghiệm điều này.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Stephen Fry","avatar":""},{"name":"Ben Pridmore","avatar":""},{"name":"Kassa Korley","avatar":""},{"name":"Sherry Nhan","avatar":""},{"name":"Ryoei Hirano","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324257);
