INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-cuoc-doi-qua-ngan-ngui-vu-an-isabella-nardoni', 'Một Cuộc Đời Quá Ngắn Ngủi: Vụ Án Isabella Nardoni', 'A Life Too Short: The Isabella Nardoni Case', 'https://phimimg.com/upload/vod/20240102-1/6bd6b4e9f32a7cf31412e59848431e86.jpg', 'https://phimimg.com/upload/vod/20240102-1/53f8ca741715c12753bef6191ca2446a.jpg', '<p>Khi một bé gái 5 tuổi rơi khỏi căn hộ của người bố, mẹ của bé bước vào hành trình đòi công lý rồi thu hút sự chú ý của cả nước.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Brazil', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324257);
