INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-quan-tu-phuc-mua-2', 'Thiên Quan Tứ Phúc (Mùa 2)', 'Heaven Official''s Blessing (Season 2)', 'https://phimimg.com/upload/vod/20240111-1/d05d83d4fec4c79d00509804f99f7690.jpg', 'https://phimimg.com/upload/vod/20240111-1/e14c73cfd397cdadc71cdf443b332db1.jpg', '<p>Phim Thiên Quan Tứ Phúc là câu chuyện mang màu sắc đam mỹ tập trung vào tình cảm cấm kị giữa thần-quỷ. Câu chuyện kể về Tạ Liên một lòng trong sạch mà vì người thương nên náo loạn thiên đình. Đồng thời, câu chuyện cũng nhắc về Hoa Thành là một tình thánh, chờ đợi tám trăm năm để có thể được bên cạnh người yêu. &quot;Vì người, đánh đâu thắng đó, không gì cản nổi.&quot; Văn án (cũ): Giữa tam giới thần phật khắp nơi này, thế mà lại có một trò cười! Văn án (mới): Ái chà, nhân viên công vụ lượm đồng nát trên thiên giới có gian tình với đại quý nhân của quỷ giới kìa!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Guangtao","avatar":""},{"name":"Zhengyang Ma","avatar":""},{"name":"Yi Zhao","avatar":""},{"name":"Tu Xiongfei","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324257);
