INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hachiko', 'HACHIKO', 'HACHIKO', 'https://phimimg.com/upload/vod/20240102-1/f5512024ca8c4ad96b0171f8108ed9da.jpg', 'https://phimimg.com/upload/vod/20240102-1/0f488a7431781f48681e08ca1c5d0bc4.jpg', '<p>Bát Đồng đáng yêu thuộc giống chó ta của Trung Quốc, giữa biển người tấp nập lại có duyên gặp được người chủ định mệnh của mình là Trần Kính Tu, trở thành một thành viên nhà họ Trần. Năm tháng đổi thay, gia đình ấm êm một thời giờ đã là dĩ vãng, nhưng nơi ấy vẫn luôn có một Bát Đồng đợi chờ, trói sinh mệnh và gia đình thân yêu của chú chó ấy lại với nhau.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feng Xiao Gang","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Pax Congo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
