INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dung-dau-joaquin-murrieta', 'Người Đứng Đầu Joaquín Murrieta', 'The Head Of Joaquín Murrieta', 'https://phimimg.com/upload/vod/20240110-1/6eca9e13a3f4ed46268617cdc20cee89.jpg', 'https://phimimg.com/upload/vod/20240110-1/de8bfb35198a4e9c7f2a92738591749f.jpg', '<p>Lòng tham chiếm lấy California vì cơn sốt vàng. Nó làm cho mọi người khao khát của cải và đất đai. Ở đó, tại biên giới mới được vẽ ra giữa Mexico và Hoa Kỳ, một cuộc chiến vô luật pháp để giành quyền kiểm soát, được thúc đẩy bởi sự tức giận và tư tưởng bài ngoại của cuộc chiến trong quá khứ, được dẫn dắt bởi một nhóm người nhập cư, những người đã hợp lực để tạo ra huyền thoại về Robin Hood Latinh: Joaquin Murrieta.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2023, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Becky Zhu Wu","avatar":""},{"name":"Juan Manuel Bernal","avatar":""},{"name":"Alejandro Speitzer","avatar":""},{"name":"Steve Wilcox","avatar":""},{"name":"Yoshira Escárrega","avatar":""},{"name":"Emiliano Zurita","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
