INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-doc', 'Tin Độc', 'Scoop', 'https://phimimg.com/upload/vod/20240109-1/b91df82180dcc25c9292d269f6d2652e.jpg', 'https://phimimg.com/upload/vod/20240109-1/7c049939c5d7e7a23e28ac35c7b3dbc8.jpg', '<p>Vụ sát hại một nhà báo gây chấn động đẩy một phóng viên hình sự hàng đầu vào mạng lưới cảnh sát, giới truyền thông và thế giới ngầm Mumbai khi cô chiến đấu vì công lý.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Karishma Tanna","avatar":""},{"name":"Mohammed Zeeshan Ayyub","avatar":""},{"name":"Prosenjit Chatterjee","avatar":""},{"name":"Harman Baweja","avatar":""},{"name":"Tannishtha Chatterjee","avatar":""},{"name":"Deven Bhojani","avatar":""},{"name":"Tanmay Dhanania","avatar":""},{"name":"Inayat Sood","avatar":""},{"name":"Sanat Vyas","avatar":""},{"name":"Ira Dubey","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
