INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ksi-ngoai-doi-thuc', 'KSI: Ngoài Đời Thực', 'KSI: In Real Life', 'https://phimimg.com/upload/vod/20231230-1/5daca13b69e4bd6b70d488985ba62ca4.jpg', 'https://phimimg.com/upload/vod/20231230-1/2f8265794100e33d506b25519885fafd.jpg', '<p>Một cái nhìn toàn diện về quyền truy cập vào cuộc sống của siêu sao toàn cầu KSI khi anh ấy trải qua năm quan trọng nhất trong cuộc đời mình. Ở đỉnh cao danh vọng, được thúc đẩy bởi một cuộc chia tay, triệu phú YouTuber, võ sĩ quyền anh và rapper bắt đầu đánh giá lại các ưu tiên của mình. Làm thế nào mà JJ Olatunji, một đứa trẻ mọt sách đến từ Watford lại trở nên thành công như vậy và với cái giá nào?</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"KSI","avatar":""},{"name":"Deji Olatunji","avatar":""},{"name":"Jide Olatunji","avatar":""},{"name":"Yinka Olatunji","avatar":""},{"name":"Randolph","avatar":""},{"name":"S.X.","avatar":""},{"name":"Harry Lewis","avatar":""},{"name":"Vik Barn","avatar":""},{"name":"Simon Minter","avatar":""},{"name":"Alex Wassabi","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324257);
