INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-chong-yakuza-noi-tro-phan-2', 'Ông Chồng Yakuza Nội Trợ (Phần 2)', 'The Way Of The Househusband (Season 2)', 'https://phimimg.com/upload/vod/20240109-1/88dc854581c469a043184c58381daf0a.jpg', 'https://phimimg.com/upload/vod/20240109-1/8dc1fb3771a993555a542ab92c83d1c0.jpg', '<p>Cựu yakuza mà ai cũng yêu mến đã trở lại! Anh ấy cắt phiếu thưởng, lên kế hoạch cho những bữa ăn tiết kiệm tiền và rất nghiêm túc thực hiện vai trò người chồng nội trợ của mình.</p>', 'Hoàn Tất (5/5)', 5, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tsuda Kenjiro","avatar":""},{"name":"Ito Shizuka","avatar":""},{"name":"Okitsu Kazuyuki","avatar":""},{"name":"MAO","avatar":""},{"name":"Fukushima Jun","avatar":""},{"name":"Saito Kimiko","avatar":""},{"name":"Hosoya Yoshimasa","avatar":""},{"name":"Nogawa Masashi","avatar":""},{"name":"Yanagita Junichi","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Tanaka Atsuko","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
