INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-chong-yakuza-noi-tro-phan-2', 'Ông Chồng Yakuza Nội Trợ (Phần 2)', 'The Way Of The Househusband (Season 2)', 'ông chồng yakuza nội trợ (phần 2) the way of the househusband (season 2) tsuda kenjiro ito shizuka okitsu kazuyuki mao fukushima jun saito kimiko hosoya yoshimasa nogawa masashi yanagita junichi hochu otsuka tanaka atsuko ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-lang-gen-z', 'Hậu Lãng - Gen Z', 'The Waves Behind', 'https://phimimg.com/upload/vod/20240109-1/745d27aebe7069dce8dadf60b198a9d6.jpg', 'https://phimimg.com/upload/vod/20240109-1/8537f633faf6e0346e3f32e3916b0b21.jpg', '<p>Hậu Lãng - Gen Z xoay quanh Tôn Đầu Đầu, một cô nàng hơn 20 tuổi, không cha không mẹ. Trong một lần gặp phiền phức do từng lên tiếng khi thấy chuyện không công bằng, cô được giáo sư đại học Trung Y là Nhậm Tân Chính giúp đỡ. Sau này, ông biết được thân thế của Đầu Đầu, quyết định dẫn cô tham gia vào lớp Trung Y, giúp cô bắt đầu lại cuộc đời. Từ đây, dưới sự dẫn dắt của Nhậm Tân Chính, Tôn Đầu Đầu bắt đầu con đường học tập, kế thừa truyền thống gia đình. Ai ngờ khi vào lớp, cô và con trai của thầy giáo - Nhậm Thiên Chân đối đầu lẫn nhau, gây ra biết bao chuyện. &nbsp;Cả hai không ngừng va chạm, không ngừng trưởng thành, dần dần hiểu và gỡ bỏ hiểu lầm, từ từ tìm hiểu đối phương.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Giang San","avatar":""},{"name":"Triệu Lộ Tư","avatar":""},{"name":"Trương Manh","avatar":""},{"name":"La Nhất Châu","avatar":""},{"name":"Ngô Cương","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
