INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chao-mung-den-samdalri', 'Chào Mừng Đến Samdal-ri', 'Welcome to Samdal-ri', 'https://phimimg.com/upload/vod/20240103-1/f64358af9862342702c5fb6eddb426ad.jpg', 'https://phimimg.com/upload/vod/20240103-1/6e6efa1b5a6ffb0b3f88d29ca86caf7c.jpg', '<p>Sau khi rớt xuống từ trên đỉnh cao, nữ nhiếp ảnh gia nọ quay về quê hương và tình cờ gặp lại người bạn thơ ấu. Thế rồi mối tình còn dang dở cứ thế mà nhen nhóm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'ongoing', 14, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ji Chang-wook","avatar":""},{"name":"Shin Hye-sun","avatar":""},{"name":"Yu Oh-seong","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Seo Hyeon-cheol","avatar":""},{"name":"Shin Dong-mi","avatar":""},{"name":"Kang Mi-na","avatar":""},{"name":"Yang Kyung-won","avatar":""},{"name":"Kim Do-eun","avatar":""},{"name":"Kim Ja-young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
