INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chao-mung-den-samdalri', 'Chào Mừng Đến Samdal-ri', 'Welcome to Samdal-ri', 'chào mừng đến samdal-ri welcome to samdal-ri ji chang-wook shin hye-sun yu oh-seong kim mi-kyeong seo hyeon-cheol shin dong-mi kang mi-na yang kyung-won kim do-eun kim ja-young ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-toi-la-than-tinh-yeu', 'Người Yêu Tôi Là Thần Tình Yêu', 'My Man Is Cupid', 'https://phimimg.com/upload/vod/20240109-1/a9830d575da1279c2e87f73e60290dc8.jpg', 'https://phimimg.com/upload/vod/20240109-1/a1067654b3a10fe914b2743169413e46.jpg', '<p>Cheon Sang Hyuk là một nàng tiên lôi cuốn, người dễ dàng khiến phụ nữ phải lòng anh ta. 500 năm trước, đôi cánh của ông đã bị đốt cháy. Để khôi phục đôi cánh của mình, anh đã trải qua 27 lần. Vào lần thứ 28, anh ấy có quan hệ với Oh Baek Ryun.<br/></p><p>Baek Ryun là một bác sĩ thú y và cô làm việc tại một phòng khám động vật. Cô ấy là một người phụ nữ xinh đẹp.Cô đã có nhiều người đàn ông yêu cô vì sự hấp dẫn của cô. Bất cứ khi nào những người đàn ông này có mối quan hệ lãng mạn với cô ấy, họ luôn có trải nghiệm cận tử và sau đó sẽ chạy trốn khỏi cô ấy. Vì xui xẻo, Baek Ryun không hẹn hò với ai, nhưng cô rất muốn gặp một người đàn ông định mệnh.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'ongoing', 14, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Dong-yoon","avatar":""},{"name":"Nana","avatar":""},{"name":"Park Ki-woong","avatar":""},{"name":"Moon Ji-hoo","avatar":""},{"name":"Park Myung-hoon","avatar":""},{"name":"Eom Se-ung","avatar":""},{"name":"Gong Min-jeung","avatar":""},{"name":"Lim Jae-myung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
