INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mothers-day-is-cancelled', 'Mother''s Day Is Cancelled', 'Mother''s Day Is Cancelled', 'https://phimimg.com/upload/vod/20240121-1/e1714659c43b6476479baef3f17a22fe.jpg', 'https://phimimg.com/upload/vod/20240121-1/e2a74eac1f75c26211bfbe4742c05b90.jpg', '<p>Lidia và Manuel là một cặp vợ chồng mới cưới mà gia đình chỉ gặp nhau một lần. Giờ đây, họ lại cùng nhau kỷ niệm Ngày của Mẹ. Nhưng có một bí mật trong gia đình mà một khi nó bùng nổ, tất cả sẽ thay đổi. Esmeralda và Rosa phải dựa vào nhau để vượt qua một ngày dường như có điều gì đó chống lại họ.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gala Montes","avatar":""},{"name":"Michel Duval","avatar":""},{"name":"Leticia Huijara","avatar":""},{"name":"Anette Michel","avatar":""},{"name":"Alejandro Camacho","avatar":""},{"name":"Geraldine Galvan","avatar":""},{"name":"Giovanna Reynaud","avatar":""},{"name":"Anahí Allue","avatar":""},{"name":"Kenneth Lavíll","avatar":""},{"name":"Ignacio Guadalupe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
