INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('reggie', 'Reggie', 'Reggie', 'https://phimimg.com/upload/vod/20231230-1/5cb07cc50b0b526603fc5bed11f9c31d.jpg', 'https://phimimg.com/upload/vod/20231230-1/0a0fbdb8be0c3200ffe2ffe035480a42.jpg', '<p>Một trong những siêu sao đầu tiên và có ảnh hưởng nhất của thể thao, biểu tượng bóng chày được yêu mến và nhà vô địch World Series 5 lần Reggie Jackson coi di sản của ông là một vận động viên da đen tiên phong đấu tranh cho phẩm giá, sự tôn trọng và một chỗ ngồi trong bộ phim tài liệu thân mật và tiết lộ này khám phá cuộc đời ông và sự nghiệp phá vỡ rào cản.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reggie Jackson","avatar":""},{"name":"Julius Erving","avatar":""},{"name":"Hank Aaron","avatar":""},{"name":"Derek Jeter","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324257);
