INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nimona', 'Nimona', 'Nimona', 'https://phimimg.com/upload/vod/20231230-1/52d57b6532649f0dd82776ca4d409b46.jpg', 'https://phimimg.com/upload/vod/20231230-1/2758adf4a00f9ad609b2430fce65de43.jpg', '<p>Bị đổ oan tội ác bi thảm, hiệp sĩ nọ bắt tay với một thiếu nữ kiên cường, có khả năng thay đổi hình dạng để minh oan. Nhưng sẽ ra sao nếu cô là con quái vật anh thề sẽ tiêu diệt?</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chloë Grace Moretz","avatar":""},{"name":"Riz Ahmed","avatar":""},{"name":"Eugene Lee Yang","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"Lorraine Toussaint","avatar":""},{"name":"Beck Bennett","avatar":""},{"name":"Indya Moore","avatar":""},{"name":"RuPaul Charles","avatar":""},{"name":"Julio Torres","avatar":""},{"name":"Sarah Sherman","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
