INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-rong-chuong-phu-nhap-long-dau-ho', 'Đuổi Rồng - Chương Phụ: Nhập Long Đấu Hổ', 'Extras For Chasing The Dragon', 'https://phimimg.com/upload/vod/20231230-1/52e422867555df7f8d2c0ae6df8146c8.jpg', 'https://phimimg.com/upload/vod/20231230-1/76b32cd59d2b1ea9416b0cd15c74d0ad.jpg', '<p>Bộ phim kể về câu chuyện của 3 kẻ là Ngũ Quốc Hào, Đại Tiểu Uy và anh em thuở nhỏ vượt từ Quảng Đông đến Hồng Kông để kiếm sống và được Từ Nhạc - vị thám trưởng cẩn trọng mười phần coi trọng, vẽ nên câu chuyện hắc bạch lưỡng đạo tranh đấu trong thời kỳ sau ở Hong Kong. Từ Nhạc vốn chỉ là một thanh niên chí khí, khi gia nhập lực lượng cảnh sát vì muốn phục vụ công dân và bảo vệ công lý. Tuy nhiên, anh phát hiện ra rằng toàn bộ lực lượng cảnh sát vô cùng thối nát, nếu anh kiên định với các nguyên tắc của mình, anh sẽ chỉ bị vắt kiệt sức lực cho đến chết. Dưới sự hướng dẫn của đàn anh, anh quyết định phấn đấu chiếm thế thượng phong trong hệ thống thối nát này, trong thời gian ngắn trở thành thám trưởng quyền lực nhất, cải thiện nạn tham nhũng trong thời gian ngắn. Sau đó, vì thế lực xã hội đen của người anh em tốt Ngũ Quốc Hào ngày càng lớn, Từ Nhạc biết rằng mình không thể khuyên can người anh tốt của mình nữa nên đã gia nhập ICAC trong tuyệt vọng. Cuối cùng, trong đợi hành động của ICAC, anh đã cung cấp rất nhiều bằng chứng cho chính phủ, đồng thời phải trả giá cho những gì mình đã làm. Hai anh em trải qua thăng trầm, cuối cùng dấn thân vào hai con đường đời khác nhau, và Ngũ Quốc Hào cũng phải trả giá đắt cho lỗi lầm và bằng chứng phạm tội của chính mình.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Jordan Chan","avatar":""},{"name":"Vincent Wong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
