INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-noi-voi-anh-rang-em-yeu-anh', 'Hãy Nói Với Anh Rằng Em Yêu Anh', 'Tell Me That You Love Me', 'https://phimimg.com/upload/vod/20240119-1/a9baeeaaf65df4953dea7c3454522797.jpg', 'https://phimimg.com/upload/vod/20240119-1/9fb1f2b8cd6120528eb9669ad8d9dc80.jpg', '<p>Nó sẽ miêu tả câu chuyện về một người đàn ông khiếm thính thoải mái thể hiện cảm xúc qua hình ảnh thay vì lời nói và một người phụ nữ thể hiện những gì trong lòng mình qua giọng nói. Jung Woo Sung sẽ vào vai Cha Jin Woo, một người khiếm thính thể hiện cảm xúc của mình qua những bức ảnh. Shin Hyun Bin sẽ mang lại sự sống cho nhân vật có tên Jung Mo Eun. Cô ấy có lòng tự trọng cao và vô tư. Cô ấy là người dễ tính dù có nhiều định kiến trên thế giới.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Woo-sung","avatar":""},{"name":"Shin Hyun-bin","avatar":""},{"name":"Kim Ji-hyun","avatar":""},{"name":"Lee Jae-kyoon","avatar":""},{"name":"Park Jin-joo","avatar":""},{"name":"Oh So-hyun","avatar":""},{"name":"Shin Jae-hwi","avatar":""},{"name":"Heo Joon-seok","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Park Ki-deok","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
