INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-cuoi-cung-cua-nuoc-y', 'Hoàng Tử Cuối Cùng Của Nước Ý', 'The King Who Never Was', 'https://phimimg.com/upload/vod/20231219-1/dff8a17fcfef8a44ccb4de93c10c990f.jpg', 'https://phimimg.com/upload/vod/20231219-1/9e405633568eb4ddaaf879f572f1ea4e.jpg', '<p>Loạt phim tài liệu này hé mở vụ sát hại một thiếu niên người Đức vào năm 1978 qua lời kể của em gái anh và gia đình hoàng gia có liên quan đến vụ án.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 10, 2023, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Vittorio Emanuele di Savoia","avatar":""},{"name":"Emanuele Filiberto di Savoia","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324257);
