INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuoc-chuoc-phong-luu', 'Chước Chước Phong Lưu', 'The Legend Of Zhuohua', 'https://phimimg.com/upload/vod/20231219-1/0c9237f46c10602eedd4a89068fcc42a.jpg', 'https://phimimg.com/upload/vod/20231219-1/3b3c936f96f88024da4bd39a5d5cdb93.jpg', '<p>Chuyện kể về nữ quan Mộ Chước Hoa hăng say với sự nghiệp, chống lại chế độ hôn nhân truyền thống, quyết tâm đạt được công danh và chiến thần Lưu Diễn tắm máu chiến trường, gánh trên vai hận nước thù nhà. Hai người cứu rỗi lẫn nhau, quen biết yêu thương nhau, hợp tác chống thù trong giặc ngoài, bảo vệ nước nhà, cuối cùng trở thành nhân vật kiệt xuất một thời.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 13, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cảnh Điềm","avatar":""},{"name":"Phùng Thiệu Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324257);
