INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('indiana-jones-va-vong-quay-dinh-menh', 'Indiana Jones Và Vòng Quay Định Mệnh', 'Indiana Jones and the Dial of Destiny', 'null', 'https://phimimg.com/upload/vod/20230910-1/c88666e8c1a1d01d599a67cff53ab7d7.jpg', '<p>Nhận thấy mình đang ở trong một kỷ nguyên mới và sắp nghỉ hưu, Indy vật lộn với việc hòa nhập vào một thế giới dường như đã phát triển vượt xa anh. Nhưng khi những xúc tu của một ác quỷ quá quen thuộc quay trở lại dưới hình dạng một đối thủ cũ, Indy phải đội mũ và cầm roi một lần nữa để đảm bảo một cổ vật mạnh mẽ và cổ xưa không rơi vào tay kẻ xấu.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Phoebe Waller-Bridge","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Olivier Richters","avatar":""},{"name":"Ethann Isidore","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Karen Allen","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324257);
