INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-thu-vi-2', 'Kỳ Nghỉ Thú Vị 2', 'Vacation Friends 2', 'null', 'https://phimimg.com/upload/vod/20230910-1/aa8ccbe5a26b7c81ebe20d210a1f0110.jpg', '<p>Cặp vợ chồng mới cưới Marcus và Emily mời hai người bạn thân tự do Ron và Kyla đi nghỉ cùng họ khi Marcus có chuyến đi được đài thọ toàn bộ chi phí tới một khu nghỉ dưỡng ở Caribe. Khi Reese, người cha đang bị giam giữ của Kyla, được thả ra và xuất hiện tại khu nghỉ dưỡng mà không báo trước, mọi thứ vượt quá tầm kiểm soát, làm đảo lộn kế hoạch đã đặt ra tốt nhất của Marcus và biến chuyến đi hoàn hảo của những người bạn trong kỳ nghỉ trở nên hỗn loạn hoàn toàn.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lil Rel Howery","avatar":""},{"name":"Yvonne Orji","avatar":""},{"name":"John Cena","avatar":""},{"name":"Meredith Hagner","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Carlos Santos","avatar":""},{"name":"Ronny Chieng","avatar":""},{"name":"Arnold Y. Kim","avatar":""},{"name":"Jamie Hector","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
