INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-chim-barcelona', 'Lồng Chim Barcelona', 'Bird Box Barcelona', 'null', 'https://phimimg.com/upload/vod/20230910-1/534dd59d5ce200e83cdce6d8e5f181b0.jpg', '<p>Khi một thế lực bí ẩn tàn sát nhân loại, mối đe dọa hiểm ác mới phát triển trong bộ phim lấy bối cảnh ở Barcelona này (mở rộng câu chuyện của bom tấn &quot;Lồng chim&quot;).</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Mario Casas","avatar":""},{"name":"Georgina Campbell","avatar":""},{"name":"Diego Calva","avatar":""},{"name":"Naila Schuberth","avatar":""},{"name":"Alejandra Howard","avatar":""},{"name":"Patrick Criado","avatar":""},{"name":"Celia Freijeiro","avatar":""},{"name":"Lola Dueñas","avatar":""},{"name":"Gonzalo de Castro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324257);
