INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-super-mario', 'Anh em Super Mario', 'The Super Mario Bros Movie', 'null', 'https://phimimg.com/upload/vod/20230909-1/7ae2f1aaad159c36d787e798d3858a3d.jpg', '<p>The Super Mario Bros. Movie xoay quanh cuộc phiêu lưu ở thế giới Vương quốc Nấm của anh em thợ sửa ống nước Mario và Luigi. Sau khi tình cờ bước tới vùng đất lạ từ một ống nước, Luigi đã bị chia tách với Mario và rơi vào tay quái vật rùa xấu xa Bowser, hắn đang âm mưu độc chiếm thế giới. Trong lúc cố gắng tìm kiếm người anh em của mình, Mario đã chạm mặt anh bạn nấm Toad và công chúa Peach. Từ đây họ sát cánh bên nhau trên hành trình ngăn chặn thế lực hắc ám.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2023, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Chris Pratt","avatar":""},{"name":"Anya Taylor-Joy","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Sebastian Maniscalco","avatar":""},{"name":"Charles Martinet","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324257);
