INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-cong-that-gia', 'Tế Công Thật Giả', 'Ji Gong', 'https://phimimg.com/upload/vod/20231219-1/8f7e4ad882209670258c1bb5874f1a01.jpg', 'https://phimimg.com/upload/vod/20231219-1/310f321b8fb98273fa8ef4645b9a3a5c.jpg', '<p>Kể về câu chuyện của Tế Công vào thời khắc mấu chốt sắp sửa đột phá tầng cuối cùng để trở thành Hàng Long La Hán thì cảm nhận được dân làng ở thôn Bạch Thuỷ đang gặp nạn, vì vậy ông đã từ bỏ tu luyện, đi đến thôn Bạch Thuỷ để giải cứu người dân. Tại đây, ông gặp Hoàng Nguyên, một kẻ đang đóng giả làm Tế Công, gã đã mê hoặc mọi người đến mức suýt thiêu chết Tế Công. Nhưng cuối cùng Hoàng Nguyên đã được cảm hoá bởi Tế Công, cùng giúp Tế Công hàng phục yêu quái và giải cứu người dân thôn Bạch Thuỷ. Tế Công sau đó cũng đã trở thành Hàng Long La Hán.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Benny Chan","avatar":""},{"name":"Batu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324257);
