INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-ky-kim-tan-cong', 'Thư Ký Kim Tấn Công', 'Jin Secretary', 'https://phimimg.com/upload/vod/20240111-1/009d9a69664307ea2267fd272eb514a9.jpg', 'https://phimimg.com/upload/vod/20240111-1/a29eaffc73fe79598e4ba0d0eb63ee39.jpg', '<p>Nhà vô địch thế giới môn võ tự do Kim Hy Nhi quay về quê hương để tìm kiếm sự phát triển cho sự nghiệp mới, vô tình phát hiện em gái sinh đôi với mình bị đối xử bất công ở công ty. Thế là Kim Hy Nhi quyết định ra tay, cô đóng giả làm em gái mình và vào công ty, cô đã cho sếp và các đồng nghiệp xấu xa ăn hành ngập mồm, xem là thấy thỏa mãn!</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Hao","avatar":""},{"name":"Qu Tian Rui","avatar":""},{"name":"Zhao Qi Yue","avatar":""},{"name":"Li Bo Yan","avatar":""},{"name":"Dong Si Ting","avatar":""},{"name":"He Yan Chao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
