INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-biet-em-yeu-anh', 'Em Biết Em Yêu Anh', 'I Know I Love You', 'https://phimimg.com/upload/vod/20240105-1/018e9513efbaa4651b82297c3a7af014.jpg', 'https://phimimg.com/upload/vod/20240105-1/01602eeba3649130d2456af07b6233e3.jpg', '<p>Em Biết Em Yêu Anh - I Know I Love You xoay quanh 2 nhân vật Triệu Tấn và Hứa Nặc, Những người trưởng thành bị thúc giục kết hôn. Hôn nhân qua mai mối, sự khó khăn của ba mẹ, sự hiểu lầm của bạn bè khiến họ rơi vào khủng hoảng. Nhưng với sự quan tâm và chăm sóc của Triệu Tấn đã khiến Hứa Nặc cảm nhận được sự ấm áp mà cô chưa từng trải qua. Cô dùng tình yêu này vào công việc cắm hoa khiến mình trở thành một người bán hoa nổi tiếng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Di","avatar":""},{"name":"Cố Ngữ","avatar":""},{"name":"Trương Vãn Ý","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
