INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mh370-chiec-may-bay-bien-mat', 'MH370: Chiếc Máy Bay Biến Mất', 'MH370: The Plane That Disappeared', 'https://phimimg.com/upload/vod/20231219-1/18e9da29105703aa8f32f3d82dea4739.jpg', 'https://phimimg.com/upload/vod/20231219-1/585184eeb4a258d56aa9fc66448b5f1a.jpg', '<p>Năm 2014, một chiếc máy bay chở 239 người bỗng biến mất không dấu vết. Loạt phim tài liệu này tìm hiểu sâu về một trong những bí ẩn lớn nhất thời hiện đại: chuyến bay MH370.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324257);
