INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-unforgettable-year-spring', 'An Unforgettable Year: Spring', 'An Unforgettable Year: Spring', 'https://phimimg.com/upload/vod/20231213-1/05af6a51118cf3bc39079de989b54268.jpg', 'https://phimimg.com/upload/vod/20231213-1/30b652807be9e948eda53bb0b24c6885.jpg', '<p>Khi sắp thi trượt môn toán - môn học mà cô ghét nhất, Jasmine phải học lớp nâng cao với một gia sư trẻ dễ thương, nhưng lại là người đưa ra những con số trong mọi việc anh ta làm. Đối mặt với áp lực gia đình và dấn thân vào một tình yêu mạo hiểm, cô ấy sẽ cần vượt qua nỗi sợ hãi và giới hạn của bản thân để theo đuổi ước mơ thực sự của mình: trở thành một nghệ sĩ.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Lívia Silva","avatar":""},{"name":"Ronald Sotto","avatar":""},{"name":"Luís Lobianco","avatar":""},{"name":"Gabriel Contente","avatar":""},{"name":"Rogério Brito","avatar":""},{"name":"Giovanna Chaves","avatar":""},{"name":"Bia Jordão","avatar":""},{"name":"Juliana Alves","avatar":""},{"name":"Cláudia Assunção","avatar":""},{"name":"Martha Babsky","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
