INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-mac-thuong-huong', 'Công Tử Mặc Thượng Hương', 'Brushes Of Destiny', 'https://phimimg.com/upload/vod/20240108-1/efd08822aaccb7fbc68e21af54084a72.jpg', 'https://phimimg.com/upload/vod/20240108-1/301f068d9bc99b09086dfc01ddd2f08b.jpg', '<p>Đồng Tử Phù, một họa sĩ vẽ tay bán mình cho tư bản vô tình rơi vào tác phẩm truyện tranh của mình và gặp Văn Cảnh Trạm - đệ nhất họa sư ở kinh thành. Văn Cảnh Trạm một lòng muốn tòng quân lầm tưởng rằng Đồng Tử Phù là kẻ do thám mà cha mình phái đến. Trải qua thời gian ở bên nhau, hai người họ cùng chứng kiến sự trưởng thành của đối phương và cuối cùng kết thành một cặp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Minh Nguyên","avatar":""},{"name":"Dương Phức Vũ","avatar":""},{"name":"Lưu Dục Đình","avatar":""},{"name":"Lưu Bạc Hủ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324257);
