INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-la-quan-he-ly-hon', 'Chỉ Là Quan Hệ Ly Hôn', 'Crush On My Ex-Husband', 'https://phimimg.com/upload/vod/20240105-1/997196975f3ddb0425f591d428671541.jpg', 'https://phimimg.com/upload/vod/20240105-1/f715cf801d213760aee86d3f81f4017f.jpg', '<p>Trong thời gian hòa giải ly hôn, cuộc hôn nhân hào môn vốn đã tan vỡ, nhưng vì người vợ Khương Thi Thi bỗng dưng tỉnh ngộ, bắt đầu con đường trả thù vừa chống lại người thảo mai vừa diệt trừ âm mưu, Kỳ Quân Dạ đã cảm nhận được sức hấp dẫn khác biệt của vợ mình. Hai người bắt tay nhau lật đổ vai phản diện, diễn một vở tổng giám đốc bá đạo theo đuổi vợ yêu, cuối cùng nối lại duyên xưa.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Xun","avatar":""},{"name":"Zhu Jiaqian","avatar":""},{"name":"Yan Lü","avatar":""},{"name":"Wang Jiayu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
