INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyet-thuong-tam-than', 'Nguyệt Thượng Tâm Thần', 'My Jealous Husband', 'https://phimimg.com/upload/vod/20240105-1/fef083913b3c261a7c348a6e27ab9997.jpg', 'https://phimimg.com/upload/vod/20240105-1/ab01b1db35edd3d35e5c0a2732a63c52.jpg', '<p>Một nhân duyên hoang đường được nhà trời ban hôn, kẻ hay ghen &quot;quan thần liêm khiết&quot; Nghiêm Huyền Nguyệt gặp được &quot;con gái gian tướng&quot; tinh quái Ngọc Thần, ngày ngày đấu đá diễn cảnh cuộc sống hôn nhân &quot;ngọt ngào&quot;. Khi tình cảm của hai người dần khắng khít thì âm mưu đằng sau nhân duyên hoang đường này cũng bắt đầu được phơi bày...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Meichen","avatar":""},{"name":"Zhong Qi","avatar":""},{"name":"Quan Peilun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
