INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguyet-thuong-tam-than', 'Nguyệt Thượng Tâm Thần', 'My Jealous Husband', 'nguyệt thượng tâm thần my jealous husband jin meichen zhong qi quan peilun ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-noi-em-thich-toi', 'Nghe Nói Em Thích Tôi', 'Have A Crush On You', 'https://phimimg.com/upload/vod/20231219-1/578ce080d5603b33181a5de59859c5d9.jpg', 'https://phimimg.com/upload/vod/20231219-1/8013c4f6c28d2b180d00a4bccf535cb6.jpg', '<p>Sau bảy năm xa nhà, Nguyễn Lưu Tranh trở lại thành phố nơi cô lớn lên và trở thành bác sĩ bồi dưỡng nghiệp vụ tại khoa Ngoại Thần kinh của bệnh viện Bắc Nhã. Để có thể ở lại Bắc Nhã, Nguyễn Lưu Tranh đã dồn hết sức mình vào công việc. Có điều chồng cũ của cô - Ninh Chí Khiêm là bác sĩ khoa Ngoại Thần kinh giỏi nhất ở Bắc Nhã, anh ấy đã chủ động làm thầy hướng dẫn cho Nguyễn Lưu Tranh và truyền thụ mọi thứ có thể cho cô chỉ để bù đắp cho những tổn thương từ cuộc hôn nhân thất bại mà anh gây ra. Thế nhưng Nguyễn Lưu Tranh đã không còn là cô gái yếu đuối nhút nhát năm nào, dù là chữa bệnh cứu người hay đối diện với vấn đề tình cảm, cô đều có thể gánh vác và giữ vững sự kiên định của mình. Trong công việc, họ tranh cãi, giảng hòa và sát cánh bên nhau, sợi tơ hồng vận mệnh liên kết giữa họ chưa bao giờ bị cắt đứt. Hưởng ứng lời kêu gọi của Tổ quốc, họ đã tham gia đội y tế tình nguyện châu Phi. Trong quá trình cấp cứu bệnh nhân, Ninh Chí Khiêm bị đạn lạc bắn trọng thương, Nguyễn Lưu Tranh đã kiên trì cứu anh từ cõi chết trở về. Sau khi trải qua thử thách sinh tử, họ đã hiểu rõ hơn về cuộc sống và sinh mệnh, từ đó bắt đầu một mối quan hệ mới.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2023, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Quán Anh","avatar":""},{"name":"Vương Sở Nhiên","avatar":""},{"name":"Xuế Ni","avatar":""},{"name":"Lưu Nhuế Lân","avatar":""},{"name":"Mao Lâm Lâm","avatar":""},{"name":"Lý Tử Phong","avatar":""},{"name":"Chu Tuấn Lân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324257);
