INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nguoc-noi-yeu-em', 'Đếm Ngược Nói Yêu Em', 'Yesterday Once More', 'https://phimimg.com/upload/vod/20231211-1/ac1bc6e0e34051720a74fa215c58ccb0.jpg', 'https://phimimg.com/upload/vod/20231211-1/f5b9acb3b8e56fb8a5df00d4286a6625.jpg', '<p>Gu Yuxuan và Han Shuyan suýt có một cuộc gặp gỡ định mệnh khi họ còn nhỏ. Sau khi lớn lên, cả hai gặp lại nhau như định mệnh để yêu nhau. Sau khi trải qua hạnh phúc và sự ngọt ngào của tình yêu, họ đã phải đối mặt với thử thách của số phận cùng nhau. Liệu phép màu của tình yêu có thể giữ họ bên nhau?</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Arthur Chen","avatar":""},{"name":"Zhou Ye","avatar":""},{"name":"Sun Tianyu","avatar":""},{"name":"Xiaotang Zhao","avatar":""},{"name":"Fu Bohan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
