INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-quan-he-phuc-tap', 'Mối Quan Hệ Phức Tạp', 'Lagaslas', 'https://phimimg.com/upload/vod/20231212-1/8d88b4415d06972f8aa7f91fd26376e5.jpg', 'https://phimimg.com/upload/vod/20231212-1/f72b10f3940bb8410b579515c74fce2c.jpg', '<p>Một bộ phim kinh dị khiêu dâm hoang dã và ướt át với sự tham gia của nữ diễn viên gợi cảm mới nhất Manang Medina. Một chàng trai trẻ tên Edmar phải lòng Karisma, một cô gái barrio. Liệu anh ấy có còn yêu cô ấy nếu anh ấy phát hiện ra bí mật đen tối sâu thẳm nhất của Karisma?</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Ruby Rubi","avatar":""},{"name":"Julio Diaz","avatar":""},{"name":"Arnold Reyes","avatar":""},{"name":"VR Relosa","avatar":""},{"name":"Maebelle Medina","avatar":""},{"name":"Elora Españo","avatar":""},{"name":"Star Orjaliza","avatar":""},{"name":"Cataleya Surio","avatar":""},{"name":"Pow Pai","avatar":""},{"name":"Sky Alvarez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
