INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tia-o-the-gioi-u-linh', 'Bắn Tỉa Ở Thế Giới U Linh', 'GHOST SNIPER', 'https://phimimg.com/upload/vod/20231211-1/6d3ad4cce9aa0f75408548b3dc47e8e2.jpg', 'https://phimimg.com/upload/vod/20231211-1/08009833187bdafb19c1d78799846d92.jpg', '<p>Lâm Sâm và các đồng đội của mình đã lẻn vào một thị trấn do bọn khủng bố kiểm soát để thực hiện nhiệm vụ giải cứu nhà khoa học Nancy. Sau một trận chiến ác liệt, Nancy đã được giải cứu, và ngay khi họ chuẩn bị sơ tán như kế hoạch ban đầu một đứa trẻ kỳ lạ bị treo trong lồng trên cây cầu chặn đường họ. Vào một thời điểm quan trọng, Lâm Sâm và các đồng đội của mình lao về phía đứa trẻ vô tội mà họ nghĩ, ngay cả khi điều đó có nghĩa là chống lại mệnh lệnh và mạo hiểm mạng sống của họ. Ngay khi họ vừa cứu được cậu bé, một nhóm khủng bố đông đảo xuất hiện, và hỏa lực bắn tỉa đã phá vỡ đội hình của chúng, khiến những đồng đội đang bảo vệ cậu bé ngã xuống. Kẻ bắn tỉa là một người đàn ông được gọi là Ghost</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Collin Chou","avatar":""},{"name":"Mify","avatar":""},{"name":"Fu Zi Ming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324257);
