INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-cam-ngan-sao', 'Ngoại Cảm Ngàn Sao', 'Stardust Telepath', 'https://phimimg.com/upload/vod/20240105-1/b4c96d2ffc54e18c2cdfa5cb48b6402b.jpg', 'https://phimimg.com/upload/vod/20240105-1/1f74eddd893cbd0dd2d932d00d35e0c1.jpg', '<p>Konohoshi Umika là một nữ sinh trung học không giỏi giao tiếp với mọi người. Một ngày nọ, cô gặp Akeuchi Yu, một cô bé tự xưng là người vũ trụ, hứa với cô sẽ cùng cô hướng tới vũ trụ. Sau đó họ gặp lớp phó Takaragi Haruno và Raimon Matataki, một cô bé không chịu đến trường. Một câu chuyện về tuổi thanh xuân về các nữ sinh chế tạo tên lửa và hướng tới vũ trụ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yurie Funato","avatar":""},{"name":"Seria Fukagawa","avatar":""},{"name":"Moe Nagamuta","avatar":""},{"name":"Shiki Aoki","avatar":""},{"name":"Natsumi Takamori","avatar":""},{"name":"Hina Yomiya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324257);
