INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-quan-cua-world-cup', 'Thủ quân của World Cup', 'Captains of the World', 'https://phimimg.com/upload/vod/20240105-1/40dff4ef004d53ea5a3af1052ea7b8fd.jpg', 'https://phimimg.com/upload/vod/20240105-1/c5f843c6524831abb38f9052315ec628.jpg', '<p>Từ phòng thay đồ cho đến sân cỏ, loạt phim tài liệu này mang đến góc nhìn độc quyền về toàn bộ 32 đội khi họ chiến đấu vì vinh quang bóng đá tại FIFA World Cup 2022.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2023, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Lionel Messi","avatar":""},{"name":"Kylian Mbappé","avatar":""},{"name":"Luka Modric","avatar":""},{"name":"Cristiano Ronaldo","avatar":""},{"name":"Olivier Giroud","avatar":""},{"name":"Didier Deschamps","avatar":""},{"name":"Kingsley Coman","avatar":""},{"name":"Lionel Scaloni","avatar":""},{"name":"Lisandro Martínez","avatar":""},{"name":"Thiago Silva","avatar":""},{"name":"Neymar Jr","avatar":""},{"name":"Gary Lineker","avatar":""},{"name":"Gareth Bale","avatar":""},{"name":"Adrien Rabiot","avatar":""},{"name":"Hakim Ziyech","avatar":""},{"name":"Emiliano Martínez","avatar":""},{"name":"Virgil va","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324257);
