INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-quan-cua-world-cup', 'Thủ quân của World Cup', 'Captains of the World', 'thủ quân của world cup captains of the world lionel messi kylian mbappé luka modric cristiano ronaldo olivier giroud didier deschamps kingsley coman lionel scaloni lisandro martínez thiago silva neymar jr gary lineker gareth bale adrien rabiot hakim ziyech emiliano martínez virgil va ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('um-ano-inesquecivel-verao', 'Um Ano Inesquecível: Verão', 'An Unforgettable Year: Summer', 'https://phimimg.com/upload/vod/20231211-1/ce9b50c015853c71c997751572a150ec.jpg', 'https://phimimg.com/upload/vod/20231211-1/6c8aa6d8a51ed9dcb4d8b07d9b17614b.jpg', '<p>Để theo học ngành thời trang ở Paris, một cô gái trẻ quê mùa ghét lễ hội Carnival đã đến Rio de Janeiro để cố gắng nhận được sự hỗ trợ từ nhà thiết kế nổi tiếng nhất ở Brazil. Bắt đầu lẻn vào đội may của một trong những trường dạy samba lớn nhất, cô sẽ phát hiện ra rằng Lễ hội hóa trang chỉ kéo dài trong một tuần, nhưng một câu chuyện tình yêu có thể thay đổi cả cuộc đời cô.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Lívia Inhudes","avatar":""},{"name":"Micael Borges","avatar":""},{"name":"Mariana Rios","avatar":""},{"name":"Júlia Gomes","avatar":""},{"name":"Diego Martins","avatar":""},{"name":"Isaías Silva","avatar":""},{"name":"André Mattos","avatar":""},{"name":"Késia Estácio","avatar":""},{"name":"Duda Santos","avatar":""},{"name":"Regina Sampaio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
