INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-cuoc-doi-dep', 'Một Cuộc Đời Đẹp', 'A Beautiful Life', 'https://phimimg.com/upload/vod/20231211-1/62210d38944333453dc8b38ca96338f0.jpg', 'https://phimimg.com/upload/vod/20231211-1/19251ae4a82eee431a67a13c79c3267c.jpg', '<p>Được một nhà sản xuất âm nhạc phát hiện ra tài năng tiềm ẩn, chàng ngư dân trẻ nọ phải quyết định xem anh đã sẵn sàng để trở thành ngôi sao và yêu đương hay chưa.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Christopher","avatar":""},{"name":"Inga Ibsdotter Lilleaas","avatar":""},{"name":"Christine Albeck Børge","avatar":""},{"name":"Ardalan Esmaili","avatar":""},{"name":"Sebastian Jessen","avatar":""},{"name":"Paw Henriksen","avatar":""},{"name":"Jonathan Harboe","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
