INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-su-dai-tai', 'Pháp Sư Đại Tài', 'GREAT MAGICIAN', 'https://phimimg.com/upload/vod/20231210-1/7c8df43184d86b4ba16ee0e3f65a42ae.jpg', 'https://phimimg.com/upload/vod/20231210-1/0f1879f599710861e8035df46cb0b9ea.jpg', '<p>Hà Thiên Tài, một nghệ sĩ ảo thuật &nbsp;đã đối mặt với thử thách từ số phận để bảo vệ quyền nuôi dưỡng con gái nuôi Hà Giai Giai của mình. Với sự hỗ trợ và cổ vũ từ chủ nhà và hàng xóm, anh ta cố gắng phấn đấu và cuối cùng lên được sân khấu cuối cùng của cuộc thi tài năng, thành công giữ con gái bên mình. Đây là một câu chuyện cảm động và truyền cảm hứng về hạnh phúc tình thân.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vila Fan","avatar":""},{"name":"Zhang Hong Shuang","avatar":""},{"name":"Qianyi Ma","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Shiu Hung Hui","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
