INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sun-moon', 'Sun Moon', 'Sun Moon', 'https://phimimg.com/upload/vod/20231211-1/c64ac7ebde1671194fdb64900b3b026e.jpg', 'https://phimimg.com/upload/vod/20231211-1/00ca60fecf60ca3df7384a1ff0e55e64.jpg', '<p>Kelsey đang chạy trốn khỏi thất bại, đau lòng và tủi nhục. Trong nỗ lực tìm hiểu mục đích của Đức Chúa Trời cho cuộc đời mình, cô đến Đài Loan để dạy tiếng Anh. Liệu niềm tin của cô ấy có được đền đáp?</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mackenzie Mauzy","avatar":""},{"name":"Justin Chien","avatar":""},{"name":"Michael Huang","avatar":""},{"name":"Madison McLaughlin","avatar":""},{"name":"Leanne Morgan","avatar":""},{"name":"Jason Burkey","avatar":""},{"name":"Alicia Kelley","avatar":""},{"name":"Stephanie Hong","avatar":""},{"name":"Jordan Frechtman","avatar":""},{"name":"Sharon Landon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
