INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('house-of-stars-hoc-vien-dao-tao-ngoi-sao', 'House Of Stars: Học Viện Đào Tạo Ngôi Sao', 'House Of Stars', 'https://phimimg.com/upload/vod/20231219-1/54138f4b940aa9ae276af4da496df309.jpg', 'https://phimimg.com/upload/vod/20231219-1/14b717b0113cfae715ae1456d7c71447.jpg', '<p>Mỗi căn nhà đều có những quy tắc riêng. Vậy nếu đó là căn nhà của một người quản lý của các ngôi sao hàng đầu, nơi mà nhiều diễn viên hàng đầu đều tập trung. Họ phải sống chung với nhau dưới những quy tắc và cạnh tranh cho công việc của mình. Trái tim và khát vọng của họ đều mong muốn trở thành số một trong ngành công nghiệp. Nhưng luôn có một bí mật đằng sau màn đêm. Liệu họ có thể kiềm chế những khao khát trong đầu? Liệu họ có thể giấu kín những bí mật của chính mình? Hãy đến và chứng minh điều đó trong House of Stars: Học Viện Đào Tạo Ngôi Sao.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2023, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"PIPO NUTCHAPAN PARAMACHAROENROJ","avatar":""},{"name":"RUDKLAO AMRATISHA","avatar":""},{"name":"LEO SIRAPOB PRATIPNATSIRI","avatar":""},{"name":"BOSS PORNPIPAT KUNISORN","avatar":""},{"name":"Heng THATPONG ROJSANGRUANG","avatar":""},{"name":"Numchok TANON APITHANAWONG","avatar":""},{"name":"New AKARAVIN NANTHIPAT","avatar":""},{"name":"Double TUPTEP JIRAPRASERTKORN","avatar":""},{"name":"Oaey PORNCHANOK TEERAWAN","avatar":""},{"name":"Mie NANNAPAS S","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
