INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wolf-pack', 'Wolf Pack', 'Wolf Pack', 'https://phimimg.com/upload/vod/20231219-1/e0bf082f6acad00130540b44305a7553.jpg', 'https://phimimg.com/upload/vod/20231219-1/69ec7d08617a625d994e95e0aa22ed2a.jpg', '<p>Khi một trận cháy rừng dữ dội giải phóng một sinh vật siêu nhiên, bốn thanh niên thấy mình bị cuốn vào nhau dưới ánh trăng tròn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Michelle Gellar","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Armani Jackson","avatar":""},{"name":"Bella Shepard","avatar":""},{"name":"Chloe Rose Robertson","avatar":""},{"name":"Tyler Lawrence Gray","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
