INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('wolf-pack', 'Wolf Pack', 'Wolf Pack', 'wolf pack wolf pack sarah michelle gellar rodrigo santoro armani jackson bella shepard chloe rose robertson tyler lawrence gray ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-ma-ca-rong-tam-thuong', 'Công Chúa Ma Cà Rồng Tầm Thường', 'The Vexations of a Shut-In Vampire Princess', 'https://phimimg.com/upload/vod/20231230-1/bb7cb8f31b28e2c37a6c0ec56b08a7eb.jpg', 'https://phimimg.com/upload/vod/20231230-1/693482c5cb7019e5c570300e869ae999.jpg', '<p>“Hả? Gì cơ?”</p><p>Bừng tỉnh khỏi giấc ngủ, Terakomari - một hikikomori bỗng dưng được chỉ định làm chỉ huy, chưa kể quân đoàn do cô chịu trách nhiệm được biết đến là những kẻ đã lật đổ và mưu sát chính cấp trên của mình. Dù được sinh ra trong một gia tộc ma cà rồng danh giá, nhưng cô chẳng thể uống máu, chẳng có khả năng thể chất, cơ thể thì thấp bé so với lứa tuổi, đến cả ma thuật còn không dùng được.\n\nĐứng trước nỗi tuyệt vọng, cô hầu gái Vill đã ra tay cứu giúp.</p><p>“Komari-sama, cứ để thần lo, thần đảm bảo rằng ngài sẽ không bị phát hiện đâu.”</p><p>Bộ truyện fantasy hài hước kể về những cuộc đấu tranh của Komari bắt đầu từ đây. Dù chỉ là một Hikikomori, nhưng nếu cô nàng toàn tâm toàn ý thì sẽ làm nên chuyện chăng?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'ongoing', 18, 2023, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomori Kusunoki","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Miyuri Shimabukuro","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Hina Kino","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Saku Mizuno","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Masaaki Mizunaka","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Yusuke Kobayashi","avatar":""},{"name":"Jun Fukushima","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324257);
