INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-trieu-do-berlin', 'Phi Vụ Triệu Đô: Berlin', 'Berlín', 'https://phimimg.com/upload/vod/20231230-1/8a0739124416fe87038a0c3c5cfd8c76.jpg', 'https://phimimg.com/upload/vod/20231230-1/f4f78d48566796fa933e2229d4840502.jpg', '<p>Thời huy hoàng, Berlin và băng nhóm quy tụ ở Paris để thực hiện một trong những kế hoạch lớn nhất từ trước đến nay của anh ta: trộm trang sức trị giá 44 triệu euro trong một đêm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2023, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Pedro Alonso","avatar":""},{"name":"Michelle Jenner","avatar":""},{"name":"Tristán Ulloa","avatar":""},{"name":"Begoña Vargas","avatar":""},{"name":"Julio Peña","avatar":""},{"name":"Joel Sánchez","avatar":""},{"name":"Samantha Siqueiros","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324257);
