INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-dao-anh-hoang-da', 'Quần Đảo Anh Hoang Dã', 'Wild Isles', 'https://phimimg.com/upload/vod/20231208-1/2b8f83a170416eb0ef2ba25a986d5cb9.jpg', 'https://phimimg.com/upload/vod/20231208-1/a5f6fe3833dac4de2e9407cb4c58815e.jpg', '<p>Bộ phim tài liệu thiên nhiên này giới thiệu đến người xem hệ động vật và thực vật của Anh và Ireland trên bốn khu vực chính: rừng cây, đồng cỏ, nước ngọt và biển.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 8, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324257);
