INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-doan-anh-co-phai-anh-hung-khong', 'Em Đoán Anh Có Phải Anh Hùng Không', 'GUESS IF I AM A HERO', 'https://phimimg.com/upload/vod/20231210-1/e55f1babd6b824267e0de482af10e144.jpg', 'https://phimimg.com/upload/vod/20231210-1/c11ade835a863ca9daf369833aff943e.jpg', '<p>Dick và vợ Roman kết hôn đã mười năm, giống như nhiều gia đình khác, người vợ mạnh mẽ, người chồng thì nghe theo lời vợ, không dám làm trái. Dick, người không thể thoát khỏi lời nguyền mười năm của cuộc hôn nhân, đã lên kế hoạch ly hôn. Sử dụng trò thoát phòng để tập hợp mọi người để tạo ra một chương trình hay trong thời gian và không gian song song, sử dụng thời gian và không gian khác để tạo ra một cảnh hoàn hảo, trải nghiệm một loạt câu chuyện trớ trêu và ly kỳ, và vô tình đánh bại đối thủ kinh doanh Lỗ Thiếu, tìm lại chính mình mười năm trước và thành công chinh phục trái tim Roman.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Yang","avatar":""},{"name":"Danbao Huang","avatar":""},{"name":"Xiu Rui","avatar":""},{"name":"Li Taoyaoyao","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Wei Xiang","avatar":""},{"name":"Wen Song","avatar":""},{"name":"Phan Bân Long","avatar":""},{"name":"Xiao Shanzhu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
