INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-bat-sat-nhan', 'Truy Bắt Sát Nhân', 'To Catch A Killer', 'https://phimimg.com/upload/vod/20231210-1/03347a7f5ace67d323b2df8b727e6190.jpg', 'https://phimimg.com/upload/vod/20231210-1/312813db5d2588c3f4102fd450656a22.jpg', '<p>Baltimore. giao thừa. Một sĩ quan cảnh sát tài năng nhưng rắc rối được điều tra viên trưởng của FBI tuyển dụng để giúp lập hồ sơ và truy tìm một kẻ giết người hàng loạt.</p>', 'Full', 1, 'single', 'completed', 6, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shailene Woodley","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Jovan Adepo","avatar":""},{"name":"Ralph Ineson","avatar":""},{"name":"Rosemary Dunsmore","avatar":""},{"name":"Jason Cavalier","avatar":""},{"name":"Mark Camacho","avatar":""},{"name":"Darcy Laurie","avatar":""},{"name":"Karine Dion","avatar":""},{"name":"Arthur Holden","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324257);
