INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-song-con', 'Ranh Giới Sống Còn', 'Life On The Line', 'https://phimimg.com/upload/vod/20231210-1/7581b834781265e9a711b8e4247dc5d8.jpg', 'https://phimimg.com/upload/vod/20231210-1/faf64986e90af8c5a77886eb32df0415.jpg', '<p>Một loại methamphetamine mới vừa xuất hiện ở thành phố A. Phó đội trưởng đội chống ma túy Mạc Cao dồn mọi chú ý vào tên què buôn ma túy, nhưng do sơ suất của cảnh sát trẻ Ngô Hạo Vệ cho nên manh mối bị đứt đoạn. Mạc Gao biết được kẻ buôn ma túy đến thành phố A chính là Đào Tam - đối thủ cũ của đội trưởng Lưu. Tiểu Ngô bí mật bám theo đội trưởng Mạc và tìm ra người mật báo là Mạn Liên. Trên đường tìm kiếm manh mối,cậu bị tay sai số một của Đào Tam là Hoa Tý phát hiện, may sao Mạn Liên đã nhận Tiểu Ngô là cấp dưới của mình mới thoát được một kiếp. Để bù đắp cho lỗi lầm của mình, Tiểu Ngô - người luôn mong muốn lập công, đã đề nghị được làm gián điệp. Tiểu Ngô và Mạn Liêu liên tục mua ma túy từ Hoa Tý, nhân cơ hội này đề xuất một hợp đồng lớn để dụ Đào Tam lộ diện. Trong quá trình giao dịch, danh tính của Mạn Liêu bị nghi ngờ, đội trưởng Mạc cố chấp theo đuôi cũng thương tích đầy mình, Mạn Liên thì bị giết. Cái chết của Mạn Liên đã giáng một đòn nặng nề vào đội trưởng Mạc và Tiểu Ngô, thầy trò thề sẽ truy lùng bắt được kẻ buôn ma túy, vì lý do này mà chuyện tình cảm giữa đội trưởng Mạc và bạn gái Tiểu Như dần dần xa cách. Các đồng nghiệp ở các tỉnh lân cận báo cáo rằng một lô thuốc khác đang được tuồn đến thành phố A. Đội trưởng Mạc biết đây là cơ hội để bắt Đào Tam</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"GanTingTing","avatar":""},{"name":"Waise Lee","avatar":""},{"name":"Su You Chen","avatar":""},{"name":"Li Yan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324257);
