INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-dao-tuong-nhan', 'Ma Đạo Tượng Nhân', 'The Devildom Elephant Man', 'https://phimimg.com/upload/vod/20231210-1/756e7f14c36191832e006367956ff866.jpg', 'https://phimimg.com/upload/vod/20231210-1/5574845d202001f585f43a726f1a8891.jpg', '<p>Vào thời Khang Hy, nước Xiêm hải ngoại cúi đầu quy phục chính quyền nhà Thanh, câu chuyện bắt đầu từ việc công chúa Xiêm bị bí mật ám sát, nhiều thế lực nhúng tay vào. Hồng Hy Quan vào tù để trả thù, và một sự thay đổi lớn đã diễn ra trong cuộc đời. Tuy nhiên, cậu ấy đã tích cực vượt lên phía trước và giải quyết mọi khó khưn, chiến đấu chống lại những chú voi ma thuật</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Du Yu Hang","avatar":""},{"name":"Viola","avatar":""},{"name":"An hu","avatar":""},{"name":"Mu Lan","avatar":""},{"name":"He Yun Wei","avatar":""},{"name":"Norman Chui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324257);
