INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-su-che-tao-bom', 'Kỹ Sư Chế Tạo Bom', 'The Engineer', 'https://phimimg.com/upload/vod/20231209-1/1d223441cb79acf50fbe214853c049ac.jpg', 'https://phimimg.com/upload/vod/20231209-1/a2d9c6d5f6202c90334f1c3fd4fb2efd.jpg', '<p>Khi Israel rung chuyển bởi hàng loạt vụ đánh bom khủng bố, con gái của thượng nghị sĩ Mỹ thiệt mạng trong một vụ nổ đẫm máu. Giờ đây, cựu đặc vụ Mossad Etan phải lãnh đạo một đội đặc vụ và lính đánh thuê bí mật, tinh nhuệ để tìm ra kẻ chịu trách nhiệm—“Kỹ sư” khó nắm bắt. Liệu họ có thể tìm ra và tiêu diệt kẻ điên trước khi thêm nhiều sinh mạng vô tội bị mất?</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emile Hirsch","avatar":""},{"name":"Danny A. Abeckaser","avatar":""},{"name":"Tsahi Halevi","avatar":""},{"name":"Angel Bonanni","avatar":""},{"name":"Yarden Toussia-Cohen","avatar":""},{"name":"Oshri Cohen","avatar":""},{"name":"Adam Haloon","avatar":""},{"name":"Lee Keinan","avatar":""},{"name":"Omer Hazan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324257);
