INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-giac-long-trung', 'Bát Giác Long Trung', 'Never Say Never', 'https://phimimg.com/upload/vod/20231209-1/bccce33ffae08026bf0a687e8cdd5a56.jpg', 'https://phimimg.com/upload/vod/20231209-1/120522c0c52801ba325b73f1f6e5d50c.jpg', '<p>Bộ phim kể về Xiang Tenghui (do Wang Baoqiang thủ vai), người đã dốc hết sức mình để đào tạo những đứa trẻ không được chăm sóc tại địa phương thành những tài năng, điều này khiến những đứa trẻ không lối thoát nhìn thấy một tia hy vọng về tương lai. Tuy nhiên, như những video trình diễn trước đó được tung ra, những hình ảnh tàn ác và đẫm máu này đã kích thích thần kinh của những người chưa biết sự thật. Qua một đêm, dư luận bắt đầu lên men. Tính mạng của Xiang Tenghui và tương lai của những đứa trẻ bị mắc vào tấm lưới lớn do những người nhân danh lòng tốt giăng ra, khiến họ khó thoát ra và quay trở lại vũng lầy, về tương lai, lối thoát của họ sẽ ở đâu...</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'HD', 'Trung Quốc', 1, '[{"name":"Baoqiang Wang","avatar":""},{"name":"Chen Yongsheng","avatar":""},{"name":"Shi Pengyuan","avatar":""},{"name":"Wang Xun","avatar":""},{"name":"Zhang Yitong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
