INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-han-ba-ngay-de-yeu-anh', 'Thời Hạn Ba Ngày Để Yêu Anh', 'Love Me in Three Days', 'https://phimimg.com/upload/vod/20231207-1/87b048cbc4674579e7c3e3cd512f54c8.jpg', 'https://phimimg.com/upload/vod/20231207-1/626a52e28f517f292a13feef273e8962.jpg', '<p>Giám đốc Thiện Nhất Phàm mắc bệnh lạ, chỉ cần tiếp xúc với người khác 5 giây sẽ biến thành người đó, phải đến ba ngày sau mới có thể quay trở lại bình thường. Trong lần vô tình gặp gỡ Hạ Lạc Lạc - cô gái bình thường, lém lỉnh mắc bệnh căng thẳng, Thiện Nhất Phàm hôn Hà Lạc Lạc liền có thể trở lại hình dáng ban đầu nên anh muốn cô trở thành phương thuốc chữa bệnh của mình...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 18, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trịnh Nghệ Bân","avatar":""},{"name":"Đàm Diêm Diêm","avatar":""},{"name":"Kỷ Nhất Đồng","avatar":""},{"name":"An Khâm Phu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
