INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-truoc-yeu-sau-2', 'Cưới Trước Yêu Sau 2', 'Love Starts From Marriage 2', 'https://phimimg.com/upload/vod/20231207-1/aacdb58880615830b4824d3fe66900ad.jpg', 'https://phimimg.com/upload/vod/20231207-1/a342a59715f9c1d61ec7c79a6e7b64a5.jpg', '<p>Một người là nữ chủ tịch đầy mưu mô, độc đoán, còn người kia là một chàng trai trẻ dịu dàng, trầm ổn. Vì sự cố ngẫu nhiên đi xem mắt mà lại thành đôi, cả hai nắm tay nhau cùng đồng hành, bắt đầu cuộc sống hôn nhân dở khóc dở cười.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tất Bồi Hâm","avatar":""},{"name":"Phan Hân Ý","avatar":""},{"name":"Tạ Y Bác","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
