INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('um-ano-inesquecivel-outono', 'Um Ano Inesquecível - Outono', 'An Unforgettable Year – Autumn', 'https://phimimg.com/upload/vod/20231210-1/5f2daf26e58555ecdd704501fad8b7dc.jpg', 'https://phimimg.com/upload/vod/20231210-1/cf740d7f49087dc58e2e1a434477962a.jpg', '<p>Một sinh viên luật đầy tham vọng ghét âm nhạc cần lên một kế hoạch hoàn hảo để được nhận vào văn phòng mà cô thực tập – cho đến khi cô gặp một ca sĩ quyến rũ, người đã làm rung chuyển cuộc đời cô. Trong khi sống với mối tình đầu của mình, cô ấy cần phải đối mặt với quá khứ của chính mình và quyết định điều gì quan trọng hơn: làm những gì cô ấy yêu thích hay học cách yêu những gì cô ấy làm.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Gabz","avatar":""},{"name":"Lucas Leto","avatar":""},{"name":"Iza","avatar":""},{"name":"Larissa Luz","avatar":""},{"name":"Raphael Ghanem","avatar":""},{"name":"Vittor Fernando","avatar":""},{"name":"Enrico Cardoso","avatar":""},{"name":"Lulu Santos","avatar":""},{"name":"Marco Watanabe","avatar":""},{"name":"Maria Calú","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
