INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tu-minh', 'Quân Tử Minh', 'A League of Nobleman', 'https://phimimg.com/upload/vod/20231207-1/e1534285dbb776263bc496aafe7bc39e.jpg', 'https://phimimg.com/upload/vod/20231207-1/48ae9f986bdaa00faa46a04ba70b75e8.jpg', '<p>Vào thời đại vương triều nhà Ung, Lễ Bộ Thị Lang Lan Giác (do Tỉnh Bách Nhiên thủ vai) hằng năm đều phải quay cuồng trong các vụ tranh chấp của triều đình, nhìn thì có vẻ ôn nhuận ưu nhã, mọi thứ đều thuận lợi, nhưng thật ra đằng sau đó là cả một quá trình trưởng thành ít ai biết được. Trong một lần hành động bí mật, Lan Giác đã tình cờ gặp được Trương Bình (do Tống Uy Long thủ vai) là thiếu niên si án* một mình lên Kinh tham gia kỳ thi để theo đuổi lý tưởng của bản thân. Trương Bình một thiếu niên ngây thơ thẳng thắn, dựa vào năng lực suy luận thiên tài của mình mà phá giải vụ án, nhưng cũng phá vỡ kế hoạch chu đáo ban đầu của Lan Giác. Từ đây, hai con người với thân phận cách biệt tính cách khác nhau, vừa là thầy vừa là bạn, ngầm hợp tác, phá giải nghi án.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 17, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tỉnh Bách Nhiên","avatar":""},{"name":"Tống Uy Long","avatar":""},{"name":"Quách Thừa","avatar":""},{"name":"Hồng Nghêu","avatar":""},{"name":"Uông Đạc","avatar":""},{"name":"Trương Thư Luân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324257);
