INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bo-vi-ham', 'Bộ Bộ Vi Hạm', 'Bride''s Revenge - Hundred Days', 'https://phimimg.com/upload/vod/20231207-1/a10066f25bd9aee5e1a80bc295b41689.jpg', 'https://phimimg.com/upload/vod/20231207-1/99481abd35795ce6da37675ee3d839b7.jpg', '<p><em>Bộ Bộ Vi Hạm - Brides Revenge - Hundred Days Bride (VietSub - Thuyết Minh)</em>&nbsp;kể về hai anh em nhà họ Mộ kết hôn cùng ngày, song hỷ lâm môn. Ai ngờ, Diệp Thanh Lam, cô dâu “xung hỷ” của Nhị thiếu gia Mộ An Hòa, lại là người yêu cũ của Đại thiếu gia Mộ An Thừa.<br/>Không chỉ vậy, Mộ lão phu nhân còn coi Diệp Thanh Lam là sao chổi, hay đánh đập mắng mỏ cô. Diệp Thanh Khanh, là chị họ và chị dâu, thậm chí còn khiến mọi việc trở nên tồi tệ hơn đối với Diệp Thanh Lam. Ngay cả nha hoàn bên cạnh Nhị thiếu gia là Tri Hạ cũng đối xử tệ bạc với cô ấy.<br/>Diệp Thanh Lam chịu đựng đủ loại sỉ nhục và tra tấn ở bên Mộ An Hòa chỉ để báo ơn, nhưng cô không ngờ rằng Mộ An Hòa lại bị giết! Tràn đầy tức giận và thù hận, Diệp Thanh Lam nhắm vào Mộ An Thừa và hai người phụ nữ của anh ta để trả thù. Ngay cả khi có nhiều khó khăn, cô cũng liều mình từng bước báo thù…</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 13, 2023, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngụy Thiên Hạo","avatar":""},{"name":"Đại Cao Chính","avatar":""},{"name":"Khuất Mộng Nhữ","avatar":""},{"name":"Đổng Nhan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
