INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('spy-ops-hoat-dong-tinh-bao', 'Spy OPS: Hoạt Động Tình Báo', 'Spy Ops', 'https://phimimg.com/upload/vod/20231202-1/66698f39531e08b0744e5eb47c16d114.jpg', 'https://phimimg.com/upload/vod/20231202-1/1ad062b8fc8f926e5f792d4b4ce9284c.jpg', '<p>Các nhân viên tình báo từ MI6 đến CIA chia sẻ câu chuyện của người trong cuộc về nghề gián điệp, các chiến dịch trong Chiến tranh Lạnh và các cuộc đảo chính do mật vụ thực hiện.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324257);
