INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('spy-ops-hoat-dong-tinh-bao', 'Spy OPS: Hoạt Động Tình Báo', 'Spy Ops', 'spy ops: hoạt động tình báo spy ops  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nien-su-ky-arthdal-thanh-guom-cua-aramun', 'Niên Sử Ký Arthdal: Thanh Gươm Của Aramun', 'Arthdal Chronicles 2 - Arthdal Chronicles: The Sword of Aramun', 'https://phimimg.com/upload/vod/20231202-1/88d3716d208de653c1da320a6e0135ad.jpg', 'https://phimimg.com/upload/vod/20230919-1/ad5e8bd214b189ba9c5fb5f15739e1e0.jpg', '<p>Niên Sử Ký Arthdal: Thanh Gươm Của Aramun - Arthdal Chronicles 2: The Sword of Aramun (2023) là một bộ phim độc đáo với cốt truyện hấp dẫn. Bối cảnh diễn ra mười năm sau những biến động tại vùng Arthdal. Sau hơn tám năm, Arthdal đã đàn áp cuộc nổi dậy của các bộ tộc bị thảm sát bởi Ta Gon trong Mùa 1, và Agos cuối cùng đã thống nhất 30 bộ tộc sau 200 năm dưới sự lãnh đạo của Eun Seom. Trong Mùa 2, Vương quốc Arthdal của Ta Gon và Liên minh Ago của Eun Seom sẽ đối đầu trong cuộc chiến đẫm máu không thể tránh khỏi. Eun Seom đã trở thành vị thống đốc của miền Đông. Còn Tan Ya đã trở thành người kế vị của bộ tộc Wahan. Toàn bộ câu chuyện diễn ra tám năm sau khi Ta Gon trở thành vua.</p><p><br/></p><p>Niên Sử Ký Arthdal: Thanh Gươm Của Aramun - Arthdal Chronicles 2: The Sword of Aramun (2023) tiếp tục thu hút người xem vào một thế giới phong phú và đầy màu sắc. Từ những mâu thuẫn và mưu mô trong quyền lực cho đến những cuộc đấu tranh cam go vì tự do, bộ phim tái hiện một cách sống động một thời kỳ lịch sử đầy biến động. Những tình tiết gây cấn, những cuộc chiến đầy hào hứng và những bí mật đằng sau sẽ giữ cho khán giả cảm xúc mãnh liệt và không thể rời mắt. Nếu bạn đam mê những bộ phim lịch sử đầy kịch tính và những màn đấu trí không ngừng, Niên Sử Ký Arthdal: Thanh Gươm Của Aramun - Arthdal Chronicles 2: The Sword of Aramun (2023) chắc chắn là một lựa chọn thú vị.</p>', 'Tập 2', 12, 'series', 'ongoing', 20, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Dong-gun","avatar":""},{"name":"Lee Joon-Gi","avatar":""},{"name":"Park Hae Joon","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324257);
