INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-dia-tam', 'Thảm Họa Địa Tâm', 'Geocentric Crisis', 'https://phimimg.com/upload/vod/20230928-1/64e26987dc71ba2a6e1c93ddaee2c409.jpg', 'https://phimimg.com/upload/vod/20230928-1/1338d20d26eba7b639dc4372ea83866a.jpg', '<p>Trong tương lai, hiệu ứng nhà kính tăng cạnh, môi trường xấu đi và
 con người buộc phải chuyển đến các thành phố dưới lòng đất. Năng lượng 
trong thành phố ngầm đang đối mặt với sự cạn kiệt, các nhà khoa học đã 
dày công phát triển một tác nhân cân bằng nhiệt độ, với hy vọng đưa mọi 
người trở lại cuộc sống trên bề mặt. Tuy nhiên, vào ngày thí nghiệm phát
 thải khí, khí độc bị rò rỉ và những con thằn lằn Modor dưới lòng đất 
biến thành những con thú khổng lồ để tàn phá và thảm họa ập đến. . . . 
Mọi người phải đi chuyến tàu duy nhất dẫn lên mặt đất và bắt đầu hành 
trình trốn thoát tuyệt vọng.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Ziyi","avatar":""},{"name":"Liang Yuan","avatar":""},{"name":"Lee Lichun","avatar":""},{"name":"Li Yuan Yuan","avatar":""},{"name":"酷酷的滕","avatar":""},{"name":"Liming Cui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324257);
