INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chom-sao-may-man-cua-anh', 'Chòm Sao May Mắn Của Anh', 'My Lucky Star', 'https://phimimg.com/upload/vod/20231204-1/15e11975124900a166f9ddc5a244eac7.jpg', 'https://phimimg.com/upload/vod/20231204-1/99f05e96eeb9a866e39c24b41fd4df1a.jpg', '<p>Chòm Sao May Mắn Của Anh - My Lucky Star xoay quanh câu chuyện về 1 cô nàng đã nói dối quá nhiều lần. Vì vậy, khi cô nói ra sự thật, không ai tin cô ngoại trừ người khó tin nhất. Đó là một thiếu gia đang bỏ trốn của một đế chế trang sức. Niềm tin của anh đã truyền cảm hứng cho cô trở thành một nhà thiết kế trang sức thực thụ thay vì một kẻ lừa đảo đồ trang sức đầy mưu mô. Trong quá trình này, cô đã dạy cho anh giá trị của những món trang sức mà anh được định thừa kế.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 12, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Film Thanapat","avatar":""},{"name":"Bifern Anchasa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
