INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deadloch', 'Deadloch', 'Deadloch', 'https://phimimg.com/upload/vod/20231203-1/c1725130dc5cb87780a7e3ee51895a1b.jpg', 'https://phimimg.com/upload/vod/20231203-1/b10ad463911ae5f0328ff274877bd613.jpg', '<p>Hai nữ thám tử hoàn toàn khác nhau được tập hợp lại để giải quyết vụ sát hại một người đàn ông địa phương ở ngôi làng ven biển buồn ngủ Deadloch.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Box","avatar":""},{"name":"Madeleine Sami","avatar":""},{"name":"Nina Oyama","avatar":""},{"name":"Tom Ballard","avatar":""},{"name":"Alicia Gardiner","avatar":""},{"name":"Susie Youssef","avatar":""},{"name":"Pamela Rabe","avatar":""},{"name":"Kris McQuade","avatar":""},{"name":"Duncan Fellows","avatar":""},{"name":"Harvey Zielinski","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324257);
