INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-ha-di-van-luc', 'Hoàng Hà Dị Văn Lục', 'Mysterious Case In River', 'null', 'https://phimimg.com/upload/vod/20231201-1/8993fd9c4979aa4fbad8c73ad8eeffea.jpg', '<p>Bộ phim này kể về câu chuyện của Thần Thiên Nhất và bạn cùng lớp của anh ấy Tân Viễn Hàng, đã gặp phải một sự cố kỳ lạ về xác chết đi ngược dòng nước khi họ đang giải quyết vấn đề lũ lụt của sông Hoàng Hà,và vô tình giải cứu đồng đội cũ của họ. Họ đã cùng nhau khám phá sự thật đằng sau những sự kiện dối trá ở sông Hoàng Hà.Thần Thiên Nhất và những người khác đã phân tích từng bí ẩn, dần dần tiết lộ sự thật và tìm ra một phương pháp khoa học để kiểm soát lũ lụt, giúp khôi phục hoàn toàn sự yên bình của dân làng.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jeam","avatar":""},{"name":"Zhang Boyu","avatar":""},{"name":"Wang Yihan","avatar":""},{"name":"Li Ming","avatar":""},{"name":"Ma Chenglong","avatar":""},{"name":"Zeng Chen","avatar":""},{"name":"Liu Sasa","avatar":""},{"name":"Peng Yangyang","avatar":""},{"name":"Yu Bolin","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
