INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-boi-copenhagen-tro-chuyen-dem-voi-nicolas-winding-refn', 'Cao Bồi Copenhagen: Trò Chuyện Đêm Với Nicolas Winding Refn', 'Copenhagen Cowboy: Nightcall with Nicolas Winding Refn', 'https://phimimg.com/upload/vod/20231201-1/d017d1df9e910cda46a4f44a0a2a68be.jpg', 'https://phimimg.com/upload/vod/20231201-1/3fac7a67624153c2dbdc655e48de6cb1.jpg', '<p>Nhà sáng tạo Nicolas Winding Refn cùng đội ngũ trình bày chi tiết cách họ thổi hồn cho nữ anh hùng khắc kỷ và phiên bản cổ tích đen tối xoay quanh âm gian của Cao bồi Copenhagen.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Nicolas Winding Refn","avatar":""},{"name":"Lola Corfixen","avatar":""},{"name":"Angela Bundalovic","avatar":""},{"name":"Lili Zhang","avatar":""},{"name":"Magnus Nordenhof Jønck","avatar":""},{"name":"Liv Corfixen","avatar":""},{"name":"Zlatko Burić","avatar":""},{"name":"Andreas Lykke Jørgensen","avatar":""},{"name":"Jane Whittaker","avatar":""},{"name":"Louise Bruun","avatar":""},{"name":"Peter Peter","avatar":""},{"name":"Jason Hendil-Forssell","avatar":""},{"name":"Ramadan Huseini","avatar":""},{"name":"Ebriama Jaiteh","avatar":""},{"name":"Johanne Alg","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324257);
