INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cao-boi-copenhagen-tro-chuyen-dem-voi-nicolas-winding-refn', 'Cao Bồi Copenhagen: Trò Chuyện Đêm Với Nicolas Winding Refn', 'Copenhagen Cowboy: Nightcall with Nicolas Winding Refn', 'cao bồi copenhagen: trò chuyện đêm với nicolas winding refn copenhagen cowboy: nightcall with nicolas winding refn nicolas winding refn lola corfixen angela bundalovic lili zhang magnus nordenhof jønck liv corfixen zlatko burić andreas lykke jørgensen jane whittaker louise bruun peter peter jason hendil-forssell ramadan huseini ebriama jaiteh johanne alg ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bat-mong', 'Người Bắt Mộng', 'Desire Catcher', 'https://phimimg.com/upload/vod/20231203-1/745ea59f24ed230b9f2eba8d9c9684c9.jpg', 'https://phimimg.com/upload/vod/20231203-1/30715e1161a5b5ddc1f40077681d98f7.jpg', '<p>Câu chuyện kể về Lu Fengping, một nhà thôi miên thiên tài trong thế giới trò chơi, và Luo Fei, một cảnh sát hình sự say mê yêu ma sâu sắc. Để tìm ra sự thật của vụ án chưa được giải quyết mà họ đã tham gia cùng nhau mười năm Trước đây, cả hai đã cùng nhau giải quyết một loạt vụ án giết người bị thôi miên và cuối cùng đã khám phá ra sự thật.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trịnh Nghiệp Thành","avatar":""},{"name":"Tân Vân Lai","avatar":""},{"name":"Vương Gia Ngư","avatar":""},{"name":"Dương Lâm","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
