INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-oc-dai-su', 'Tẩy Ốc Đại Sư', 'The HAUNTING 2', 'https://phimimg.com/upload/vod/20231130-1/3a0dc99e63413462c919524ef811926f.jpg', 'https://phimimg.com/upload/vod/20231130-1/c13ea124bbc22fa71eb2e5b5ae6e5b1d.jpg', '<p>Hung trạch chính là những căn nhà có người mất. Dân gian kể rằng những kẻ này chết bất đắc kỳ tử, nên thọ mệnh trên dương thế của họ còn chưa tạn. “Bậc thầy dọn nhà ma\&quot; Giang Thước còn mua ngôi nhà ma với giá rẻ, trừ bỏ đi tàn hồ ma quỷ có trong nhà, sau đó lại bán đi với giá cao. Ngày ấy, Giang Thước không chịu nghe lời khuyên can của đối tác Tần Nhất Hằng, nhất quyết mua một tòa nhà nhỏ kiểu phương Tây rất rẻ, anh tình cờ phát hiện ra một ngôi mộ bí ẩn được giấu trong ngôi nhà ma, còn gặp được “cô quỷ nhỏ”. Sau đó, đủ loại vụ giết người kỳ quái, nham hiểm và những sự kiện kỳ lạ bắt đầu xảy ra ...</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiang Yu","avatar":""},{"name":"Wang Yanxin","avatar":""},{"name":"Chunqing Awei","avatar":""},{"name":"Li Ming","avatar":""},{"name":"Li Mengmeng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
