INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-cua-satan', 'Lời Nguyền Của Satan', 'Satan''s Curse', 'null', 'https://phimimg.com/upload/vod/20231130-1/615964bdd4aa6ba3d83f8c5c2dbb3700.jpg', '<p>Trong khi trốn kẻ cho vay nặng lãi máu lạnh, một doanh nhân trốn trong khách sạn hẻo lánh của người bạn thân để rồi nhanh chóng phát hiện ra những bí mật chết người nơi đây.</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'HD', 'Malaysia', 0, '[{"name":"Dato'' AC Mizal","avatar":""},{"name":"Farid Kamil","avatar":""},{"name":"Nynaa Harizal","avatar":""},{"name":"Jalaluddin Hassan","avatar":""},{"name":"Pakya Sepahtu","avatar":""},{"name":"Syaiful Zero","avatar":""},{"name":"Saiful Apek","avatar":""},{"name":"Azlan Komeng","avatar":""},{"name":"Azlee Senario","avatar":""},{"name":"Adam Shahz","avatar":""},{"name":"Cracky Don","avatar":""},{"name":"Aril RL","avatar":""},{"name":"Epy Kodiang","avatar":""},{"name":"Amai Kamarudin","avatar":""},{"name":"Kenji Sawahii","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
