INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-ngot-ngao', 'Vùng Đất Ngọt Ngào', 'Candy Land', 'https://phimimg.com/upload/vod/20231129-1/c6bd45dca29c09408609d251a825a9b2.jpg', 'https://phimimg.com/upload/vod/20231129-1/898ae30845b3285a2960d5f314dd47fd.jpg', '<p>Remy, một phụ nữ trẻ có vẻ ngây thơ và sùng đạo, thấy mình bị đuổi khỏi giáo phái của mình. Không còn nơi nào để quay đầu, cô đắm mình vào thế giới ngầm của những cô gái bán dâm ở bến xe tải. Dưới con mắt thận trọng của mẫu hệ và một luật sư địa phương bí ẩn, Remy điều hướng giữa hệ thống niềm tin căng thẳng của mình và mật mã để tìm thấy tiếng gọi thực sự của mình trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 7, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eden Brolin","avatar":""},{"name":"Olivia Luccardi","avatar":""},{"name":"William Baldwin","avatar":""},{"name":"Owen Campbell","avatar":""},{"name":"Brad Carter","avatar":""},{"name":"Virginia Rand","avatar":""},{"name":"Guinevere Turner","avatar":""},{"name":"Sam Quartin","avatar":""},{"name":"Billy Blair","avatar":""},{"name":"Bruce Davis","avatar":""},{"name":"Mark Stephen Ward","avatar":""},{"name":"Liz Ann Montaneli","avatar":""},{"name":"Mark Murphy","avatar":""},{"name":"Laevin Story","avatar":""},{"name":"Nick HallBilsback","avatar":""},{"name":"Nick Casa","avatar":""},{"name":"Kendall Wind","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
