INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-giong-bao', 'Vượt Qua Giông Bão', 'The Woman In The Storm', 'https://phimimg.com/upload/vod/20231209-1/bf45bf5f6a4b0a9864ff1549edf4ca14.jpg', 'https://phimimg.com/upload/vod/20231209-1/c8ead132e0764fc1d76c3c3a390c18af.jpg', '<p>Ở Trung Quốc, cứ 7,4 giây lại có một phụ nữ phải chịu bạo lực gia đình. Từ Mẫn cũng là một người từng bị chồng bạo hành trong thời gian dài tuy nhiên cô đã cố gắng trở nên mạnh mẽ với nỗ lực nhằm thoát khỏi người chồng thận trọng và không để lại bằng chứng... Khi ly hôn không phải là dấu chấm hết cho bạo lực gia đình, và chịu trách nhiệm không phải là nơi trú ẩn an toàn mà chính cơn bão, liệu Từ Mẫn có thể cam đảm vượt qua mọi chuyện?</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'HD', 'Trung Quốc', 1, '[{"name":"Đồng Lệ Á","avatar":""},{"name":"Ngô Dục Hàn","avatar":""},{"name":"Vương Ảnh Lộ","avatar":""},{"name":"Trương Hựu Hạo","avatar":""},{"name":"Khương Thụy Lâm","avatar":""},{"name":"La Dật Kiều","avatar":""},{"name":"Hoàng Lộ","avatar":""},{"name":"Tạ Hân Hoa","avatar":""},{"name":"Tạ Xuân Ý","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
