INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-gian-2023', 'Nội Gián', 'The Initiated', 'https://phimimg.com/upload/vod/20230921-1/8be5ea7341f7b9e58f835cf6bdb82a29.jpg', 'https://phimimg.com/upload/vod/20230921-1/de3a998ac96dc421e6e85f94337ad149.jpg', '<p>Lấy cảm hứng từ vũ trụ văn học nổi tiếng của tác giả người Colombia Mario Mendoza, bộ phim kinh dị hồi hộp đến nghẹt thở này. Trong một tương lai gần bị ảnh hưởng bởi tình trạng thiếu nước Frank Molina, một nhà báo cộc cằn phải đối mặt với những con quỷ của mình để đi đến vụ giết người.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Andrés Parra","avatar":""},{"name":"Aria Jara","avatar":""},{"name":"Juan Pablo Urrego","avatar":""},{"name":"Jorge Cao","avatar":""},{"name":"Francisco Denis","avatar":""},{"name":"Victoria Hernández","avatar":""},{"name":"Julio Pachón","avatar":""},{"name":"Jefferson Quiñones","avatar":""},{"name":"José Restrepo","avatar":""},{"name":"Silvia Varón Santamaría","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324257);
