INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-2023', 'Người Thừa Kế', 'Varisu', 'https://phimimg.com/upload/vod/20230922-1/c3f17453c49f7f9ae38f46cdad009170.jpg', 'https://phimimg.com/upload/vod/20230922-1/2537663fa1c7ed04e5f1e26bce8440a1.jpg', '<p>Vijay Rajendran, con trai út của một ông trùm kinh doanh nổi tiếng, Rajendran Palanisamy, bị từ chối và đuổi ra khỏi nhà khi từ chối tham gia công việc kinh doanh của gia đình, thay vào đó quyết định thành lập một công ty khởi nghiệp giao đồ ăn. Bảy năm sau, Rajendran được chẩn đoán mắc bệnh ung thư tuyến tụy giai đoạn cuối và chỉ còn sống được vài tháng nữa. Anh ta quyết định tiết lộ tình trạng cuối cùng của mình và xức dầu cho một trong hai người con trai lớn của mình, Jai hoặc Ajay, làm người kế vị, trước khi anh ta sắp chết...</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Vijay","avatar":""},{"name":"R. Sarathkumar","avatar":""},{"name":"Rashmika Mandanna","avatar":""},{"name":"Shaam","avatar":""},{"name":"Srikanth Meka","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Yogi Babu","avatar":""},{"name":"Ganesh Venkatraman","avatar":""},{"name":"Prabhu","avatar":""},{"name":"Jayasudha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324257);
