INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tien-ca-2023', 'Nàng Tiên Cá', 'The Little Mermaid', 'https://phimimg.com/upload/vod/20230915-1/68e6d390f09b316873bf38ed7428da7e.jpg', 'https://phimimg.com/upload/vod/20230915-1/f776519a7bc415d432c50e1ef31e4e33.jpg', '<p><span style="font-family: ">Là con gái út của vua thủy tề Triton và cũng là người lì lợm nhất, Ariel mơ ước được khám phá thế giới đất liền. Trong một lần lên trên mặt biển, cô đã nảy sinh tình cảm với hoàng tử điển trai Eric. Do mối quan hệ giữa người cá và con người bị nghiêm cấm, Ariel đã giao kèo với mụ phù thủy biển xấu xa Ursula để có cơ hội lên đất liền mà không biết rằng cô đã đưa mình và ngai vàng của cha mình vào nguy hiểm.</span></p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Halle Bailey","avatar":""},{"name":"Jonah Hauer-King","avatar":""},{"name":"Daveed Diggs","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Noma Dumezweni","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Melissa McCarthy","avatar":""},{"name":"Art Malik","avatar":""},{"name":"Jessica Alexander","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
