INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-tong-su-thuc-tinh-2023', 'Diệp Vấn: Tông Sư Thức Tỉnh', 'Ip Man: The Awakening', 'https://phimimg.com/upload/vod/20230926-1/aa2e25980a29d758e2ce3c3bbee97c8c.jpg', 'https://phimimg.com/upload/vod/20230926-1/14468c22bd8f721014dad47ef8641684.jpg', '<p>Phim xoay quanh câu chuyện về chàng thiếu niên trẻ tuổi Diệp Vấn. Anh đang trong quá trình hoàn thành khóa du học của mình tại Hồng Kông. Tuy nhiên, tại đây cuộc sống của anh lại thay đổi khi bị cuốn vào một vụ buôn lậu và buôn bán phụ nữ trái phép sang Trung Quốc. Không những thế tất cả vụ việt đều do tập đoàn Stank đứng sau và lừa gạt anh. Với tài năng võ thuật của Vịnh Xuân Quyền, Diệp Vấn đã dũng cảm đối đầu với các thế lực mạnh mẽ để có thể bảo vệ được danh dự cho đất nước Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tse Miu","avatar":""},{"name":"Chen Guanying","avatar":""},{"name":"Sergio De Ieso","avatar":""},{"name":"Hou Tongjiang","avatar":""},{"name":"Gu Lei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324257);
