INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-tam-song-sinh-kiep', 'Họa Tâm: Song Sinh Kiếp', 'Painted Heart: Twin Tribulations', 'https://phimimg.com/upload/vod/20231129-1/49e188bdb24774cc6645271dbf57b629.jpg', 'https://phimimg.com/upload/vod/20231129-1/79dc98ad238a27c43c29e858f946e818.jpg', '<p>Bộ phim kể về vị tướng bất bại Vương Thiên Sinh và Diêu Nhi ngày đêm sát cánh cùng nhau trên chiến trường, trên đường trở về Bắc Kinh, anh đã cứu một người phụ nữ xa lạ Tiểu Nhu, nhưng sự xuất hiện của Tiểu Nhu đã gây ra hiểu lầm giữa Vương Thiên Sinh và Diêu Nhi. Cuối cùng, Diêu Nhi buồn bã rời đi, và một âm mưu khủng khiếp đang diễn ra xung quanh câu chuyện của ba người.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Joe Xu","avatar":""},{"name":"Zhang Zhixi","avatar":""},{"name":"Hu Xue''er","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324257);
