INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-mat-tich', 'Cô Ấy Mất Tích', 'Lost in the Stars', 'https://phimimg.com/upload/vod/20231128-1/89414a7a7859e1e8329384761c2abcd8.jpg', 'https://phimimg.com/upload/vod/20231128-1/c233fa4458fbf23341f61b399373029e.jpg', '<p>Vợ của He Fei, Li Muzi, đã biến mất một cách bí ẩn trong chuyến đi kỷ niệm ngày cưới của họ tới Balandia, một hòn đảo nghỉ dưỡng ở Đông Nam Á. Khi He Fei tìm kiếm vô ích, vợ anh lại xuất hiện. Nhưng cô khẳng định mình không phải vợ anh. Người phụ nữ thậm chí còn đưa ra chứng minh thư để chứng minh. Khi luật sư Chen Mai và cảnh sát địa phương Zheng Cheng can thiệp vào vụ án kỳ lạ này, nhiều bí ẩn dần dần xuất hiện...</p>', 'Full', 1, 'single', 'completed', 8, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhu Yilong","avatar":""},{"name":"Ni Ni","avatar":""},{"name":"Janice Man","avatar":""},{"name":"Du Jiang","avatar":""},{"name":"Vincent Matile","avatar":""},{"name":"Scotty Cox","avatar":""},{"name":"Huang Ziqi","avatar":""},{"name":"Meng Zhixu","avatar":""},{"name":"Zhang Yiwenhan","avatar":""},{"name":"Zhu Haiyu","avatar":""},{"name":"Yu Chengqun","avatar":""},{"name":"Chen Mengqi","avatar":""},{"name":"Dima Shadow","avatar":""},{"name":"Jian Kang","avatar":""},{"name":"Hao Yang","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
