INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-thien-khu-vuc-cam', 'Già Thiên: Khu Vực Cấm', 'Forbidden Zone', 'https://phimimg.com/upload/vod/20231125-1/b5307593c168c3cdcc97eef17d563046.jpg', 'https://phimimg.com/upload/vod/20231125-1/068a4fb6a8ee81f7fbc8c85567b4b024.jpg', '<p>Trời đất dung hòa, dị tượng giáng thế, giữa tinh không hiện lên chín con rồng đang kéo cỗ quan tài đến tinh thành Bắc Đẩu, cấm địa Táng Thiên Đảo lộ diện. Tương truyền rằng Táng Thiên Đảo để có cất giấu bảo tàng vũ khí của Hoàng Đế, có thể hỗ trợ tăng tiến tu vi. Các môn phái thế gia của thành Bắc Đẩu, nhân sĩ tán tiên tề tựu lại Bạch Hổ Trường của Thánh Địa Vân Tiêu để bàn kế khai đảo đoạt bảo, trong số đó có cả tên cô nhi Cơ Không (Phùng Lệ Quân). Từ bé Cơ Không đã được sư tôn nuôi dưỡng ở Kiếm Lư. Sư tôn nhận ra thiên phú dị thường trên người câu, vì thánh địa, ông bỏ ra cái gái rất đắt để đưa mầm non kiếm tu này vào Thánh Địa Vân Tiêu rèn luyện. Lần này khi Táng Thiên Đảo xuất hiện, Cơ Không cùng đồng đạo bạn hữu ở Kiếm Lư lên đảo chiếm báu vật, bước lên con đường một cước thành vua.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feng Lijun","avatar":""},{"name":"Peng Gaochang","avatar":""},{"name":"Gao Shuguang","avatar":""},{"name":"Nan Sikai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
