INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dead-shot', 'Dead Shot', 'Dead Shot', 'https://phimimg.com/upload/vod/20231125-1/7b1d0611eb896ac8c94989368bef9506.jpg', 'https://phimimg.com/upload/vod/20231125-1/5443d45b7f699eda36629bbd77319885.jpg', '<p>Vào những năm 1970, một thành viên của IRA tiếp quản Đơn vị Dịch vụ Tích cực ở London sau khi vợ anh ta vô tình bị bắn chết ở Ireland. Nhiệm vụ của đơn vị là gây ra sự hỗn loạn và hủy diệt, trong khi mục đích cá nhân của anh ta là săn lùng kẻ giết vợ mình - một đội trưởng SAS, người cũng đang săn lùng anh ta.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Colin Morgan","avatar":""},{"name":"Aml Ameen","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Sophia Brown","avatar":""},{"name":"Tom Vaughan-Lawlor","avatar":""},{"name":"Will Keen","avatar":""},{"name":"Mairéad Tyers","avatar":""},{"name":"Dara Devaney","avatar":""},{"name":"Andrea Irvine","avatar":""},{"name":"Jack McMullen","avatar":""},{"name":"Steve Wall","avatar":""},{"name":"Caolan Byrne","avatar":""},{"name":"Stephen McMillan","avatar":""},{"name":"Hywel Morgan","avatar":""},{"name":"Martin McCardie","avatar":""},{"name":"Desmond Edwards","avatar":""},{"name":"Maria","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
