INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-minh-ky-tuong-kinh-so-kiem-nghia', 'Đại Minh Kỳ Tướng: Kinh Sở Kiếm Nghĩa', 'The General Yu Dayou', 'https://phimimg.com/upload/vod/20231125-1/50a474d418d6b542744fe05a48c613fb.jpg', 'https://phimimg.com/upload/vod/20231125-1/131ac6a6eb8c4cf46025599b50cbd67f.jpg', '<p>Câu chuyện của bộ phim này diễn ra vào thời Gia Tĩnh của triều đại nhà Minh, khi cướp biển và cướp biển Nhật Bản hoành hành, những người dân ở các khu vực ven biển phía nam khốn khổ. Bộ phim này lấy Đại Du một vị tướng nổi tiếng chống Nhật Bản, làm nhân vật chính, kể về câu chuyện của Đại Du người đã nhìn thấu thủ đoạn của hải tặc khi còn trẻ. Anh đã anh dũng chiến đấu chống lại chúng, bảo vệ người dân và lãnh thổ của nhà Minh.Điều đó&nbsp; thể hiện lòng yêu nước mạnh mẽ và niềm tự hào dân tộc Trong câu chuyện này, chàng trai trẻ Đại Du đã trải qua rất nhiều khó khăn dầ dần trưởng thành.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Han Dong","avatar":""},{"name":"Lu Xingyu","avatar":""},{"name":"Li Mingxuan","avatar":""},{"name":"Cui Zhenzhen","avatar":""},{"name":"Zhan Ni","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324257);
