INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-cach-mang-cua-chua', 'Cuộc Cách Mạng Của Chúa', 'Jesus Revolution', 'https://phimimg.com/upload/vod/20231125-1/ac4504c75605c9960f86853b9f14718c.jpg', 'https://phimimg.com/upload/vod/20231125-1/56e41e391f80514069da1252a3424d51.jpg', '<p>Vào những năm 1970, cậu thiếu niên không mục đích Greg Laurie tìm kiếm tất cả những điều đúng đắn ở tất cả những nơi không phù hợp cho đến khi anh gặp Lonnie Frisbee, một nhà thuyết giáo đường phố/hippie lôi cuốn. Cùng với mục sư địa phương Chuck Smith, họ mở cánh cửa của một nhà thờ đang lụi tàn cho một cuộc phục hưng bất ngờ.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joel Courtney","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Jonathan Roumie","avatar":""},{"name":"Kimberly Williams-Paisley","avatar":""},{"name":"Anna Grace Barlow","avatar":""},{"name":"Julia Campbell","avatar":""},{"name":"Alexia Ioannides","avatar":""},{"name":"Matthew Montemaro","avatar":""},{"name":"DeVon Franklin","avatar":""},{"name":"Mina Sundwall","avatar":""},{"name":"Steve Hanks","avatar":""},{"name":"Erin Schaut","avatar":""},{"name":"Jackson Robert Scott","avatar":""},{"name":"Nicholas Cirillo","avatar":""},{"name":"Nic Bishop","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324257);
