INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thuat-tien-sinh', 'Huyễn Thuật Tiên Sinh', 'The Great Magician', 'https://phimimg.com/upload/vod/20231125-1/a54e7ab0e36474a678f61be758078e5a.jpg', 'https://phimimg.com/upload/vod/20231125-1/0e73f37810932faf7a4d779515224e17.jpg', '<p>Huyễn Thuật Môn bắt nguồn từ triều đại nhà Thương và được chia thành năm trường phái: kim,mộc, thủy, hỏa và thổ. Vào những năm đầu của Trung Hoa Dân Quốc, Bậc thầy Hải quân Bùi Tịnh Chi đã đại khai sát giới vì muốn chiếm đoạt pháp bảo của Huyễn Thuật Môn, nhưng cuối cùng đã bị Hỏa sư Không Không Nhi phong ấn. Hai mươi năm sau, Bùi Tịnh Chi trở lại và giết chết Không Không Nhi. Trước khi Không Không Nhi qua đời, ông đã giao cô nhi Trác Phi Phàm của mình cho hỏa sư Lạc Hà Phi để học hỏa thuật.. Trác Phi Phàm thề sẽ trả thù cho Không Không Nhi, nhưng khi vô tình biết được Bùi Tịnh Chi chính là cha ruột của mình, cậu đã rơi vào tình thế tiến thoái lưỡng nan.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chin Siu-ho","avatar":""},{"name":"Du Yiheng","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Xu Hao","avatar":""},{"name":"Bai Yu","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324257);
