INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thu-2023', 'Báo Thủ', 'Medellin', 'https://phimimg.com/upload/vod/20230921-1/d4b3a35b7af3581facecd0d4e672481c.jpg', 'https://phimimg.com/upload/vod/20230921-1/2f144a97504ccf860704c87937151dd5.jpg', '<p>Để cứu em trai mình khỏi tay bọn ma túy nguy hiểm của băng đảng Medellín, Reda có một kế hoạch đơn giản nhưng hoàn toàn điên rồ: tập hợp một đội và đột kích Colombia. Nhưng cuộc phiêu lưu này sẽ hoàn toàn vượt khỏi tầm kiểm soát khi anh quyết định bắt cóc con trai của thủ lĩnh băng đảng để đổi lấy mạng sống của anh trai mình.</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Franck Gastambide","avatar":""},{"name":"Ramzy Bedia","avatar":""},{"name":"Anouar Toubali","avatar":""},{"name":"Rachid Guellaz","avatar":""},{"name":"Saïdou Camara","avatar":""},{"name":"Brahim Bouhlel","avatar":""},{"name":"Ragnar Le Breton","avatar":""},{"name":"Mike Tyson","avatar":""},{"name":"Raymond Cruz","avatar":""},{"name":"Essined Aponte","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324257);
