INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-noi-tieng', 'Người Nổi Tiếng', 'Celebrity', 'https://phimimg.com/upload/vod/20231202-1/670442f2b07ef818c2e3351ae32b46e1.jpg', 'https://phimimg.com/upload/vod/20230921-1/4914acf78a6de30edb4c5ef1dcd970bb.webp', '<p>Người nổi tiếng&nbsp;mô tả những ham muốn và bí ẩn xung quanh những người trở thành người có ảnh hưởng trên mạng xã hội, sống như những người được gọi là người nổi tiếng và những người ghen tị với họ. Danh tiếng.&nbsp;Tiền bạc.&nbsp;Quyền lực.&nbsp;Seo A-ri trở thành ngôi sao trên mạng xã hội chỉ sau một đêm — nhưng những hậu quả chết người đang chờ đợi trong thế giới hào nhoáng, hào nhoáng của những người có ảnh hưởng này.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 16, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Gyu-Young","avatar":""},{"name":"Kang Min-hyuk","avatar":""},{"name":"Lee Chung-Ah","avatar":""},{"name":"Lee Dong-Gun","avatar":""},{"name":"Jun Hyo-seong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324257);
