INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-ran-phanom-doi-than-ran', 'Thần rắn Phanom (Đồi Thần Rắn)', 'Phanom Nakha', 'https://phimimg.com/upload/vod/20231202-1/19d98e0b809307b69b6855a4cc928e0a.jpg', 'https://phimimg.com/upload/vod/20230919-1/e7cedf450a556cd2fbe7f4dc1f2742ec.jpg', '<p>Thần rắn Phanom, còn được gọi là Đồi Thần Rắn, là một địa điểm du lịch nổi tiếng tại Phanom Nakha, dự kiến sẽ khai trương vào năm 2023. Với vẻ đẹp hoang sơ và hùng vĩ, nơi này hứa hẹn sẽ là điểm đến hấp dẫn cho những người yêu thích khám phá thiên nhiên.</p><p>Thần rắn Phanom nằm giữa một khu rừng núi rậm phủ đầy cây xanh và động vật hoang dã. Điểm nổi bật của địa điểm này là hình dáng độc đáo của một con rắn khổng lồ được tạo thành từ đá tự nhiên. Với chiều dài khoảng hàng trăm mét, Thần rắn Phanom tạo nên một cảnh quan độc đáo và ấn tượng.</p><p>Du khách có thể tham gia vào các hoạt động như leo núi, trekking, và thám hiểm trong khu rừng xanh mát. Ngoài ra, khu vực này cũng có những điểm dừng chân để thưởng ngoạn cảnh quan đẹp và chụp ảnh. Với môi trường tự nhiên hoang sơ và không gian yên tĩnh, Thần rắn Phanom hứa hẹn sẽ mang đến cho du khách những trải nghiệm tuyệt vời và thú vị.</p><p><br/></p>', 'Tập 4', 19, 'series', 'ongoing', 22, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Green Ausadaporn Siriwattanakul","avatar":""},{"name":"Tre Porapat Srikajorn","avatar":""},{"name":"Petch Boranin","avatar":""},{"name":"Num Sornram Theappitak","avatar":""},{"name":"Kong Wittaya Teptip","avatar":""},{"name":"Yingying Sarucha Petchroj","avatar":""},{"name":"Unda Kulteera Yordchang","avatar":""},{"name":"Ploypailin Thangprapaporn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324258);
