INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sweetwater', 'Sweetwater', 'Sweetwater', 'https://phimimg.com/upload/vod/20231124-1/af2a59ba50c1be500e8870b5200b0a0a.jpg', 'https://phimimg.com/upload/vod/20231124-1/37b6848bc4c38fdbca024c0c7e790c7c.jpg', '<p>Năm 1990 ở Chicago, một tài xế taxi kể lại câu chuyện cuộc đời mình cho hành khách của mình, một nhà báo thể thao. Anh ấy tiết lộ mình là Nat &quot;Sweetwater&quot; Clifton, một trong những người Mỹ gốc Phi đầu tiên chơi ở NBA.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Everett Osborne","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Jim Caviezel","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"Jim Meskimen","avatar":""},{"name":"Jason Sklar","avatar":""},{"name":"Emmaline","avatar":""},{"name":"Ashani Roberts","avatar":""},{"name":"Robert Ri''chard","avatar":""},{"name":"Paul Hipp","avatar":""},{"name":"Eric Etebari","avatar":""},{"name":"Gary Clark Jr.","avatar":""},{"name":"Ernest Harden Jr.","avatar":""},{"name":"Wayne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324258);
