INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gian-diep-toan-cau', 'Gián Điệp Toàn Cầu', 'Citadel', 'https://phimimg.com/upload/vod/20231202-1/ab738dfa91203760c6103bf36bef5180.jpg', 'https://phimimg.com/upload/vod/20230922-1/9e739d393f76a785dcd1c1a894e96c5f.jpg', '<p>Cơ quan gián điệp toàn cầu Citadel đã sụp đổ, và ký ức của các đặc vụ của nó đã bị xóa sạch. Bây giờ tập đoàn hùng mạnh, Manticore, đang trỗi dậy trong khoảng trống. Các đặc vụ Thành cổ có thể nhớ lại quá khứ của họ và triệu tập sức mạnh để chống lại không?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 17, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Madden","avatar":""},{"name":"Priyanka Chopra Jonas","avatar":""},{"name":"Stanley Tucc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324258);
