INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-hiep-mau-chay-di', 'Thiếu Hiệp Mau Chạy Đi', 'LONGXING NORTHERN EXPEDITION', 'null', 'https://phimimg.com/upload/vod/20231124-1/93352c445171297d92cf036fa20cfd49.jpg', '<p>Vào thời Nam Tống, có Thiếu Hiệp và các huynh đệ từ quán trọ Phi Vân ở Ba Bách Lý, trợ giúp tướng quân Lý Tiên Trung phát động Bắc phạt Long Hưng thu phục sơn hà, nhưng phó tướng Thiệu Hồng Nguyên lại ghen ghét. Khi Bắc phạt thất bại, Thiếu Hiệp và những người khác bắt giữ Thiệu Hồng Nguyên và hỗ trợ mọi người rút lui kịp thời, chờ đợi khởi nghĩa Đông Sơn.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hou Junbo","avatar":""},{"name":"Zhan Zitong","avatar":""},{"name":"Liu Di","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324258);
