INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kai-sat-thu-di-nho-xe', 'Kai: Sát thủ đi nhờ xe', 'The Hatchet Wielding Hitchhiker', 'https://phimimg.com/upload/vod/20231121-1/cc2d6a73a929d1024d0283a9b4613de1.jpg', 'https://phimimg.com/upload/vod/20231121-1/5bfca9e3c0be6cbc802f8fc157d7ea13.jpg', '<p>Bộ phim tài liệu gây sửng sốt này ghi lại hành trình của một người du mục vô lo bỗng chốc nổi tiếng trên mạng xã hội rồi trượt dài đến mức phải ngồi tù.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324258);
