INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('royalteen-cong-chua-margrethe', 'Royalteen: Công chúa Margrethe', 'Royalteen: Prinsesse Margrethe', 'https://phimimg.com/upload/vod/20231120-1/d3088dfe2e8ba13a93cc9fdf76f0578e.jpg', 'https://phimimg.com/upload/vod/20231120-1/38bba7225df2a041942a996e090614f9.jpg', '<p>Sau vụ bê bối của mình tại buổi dạ hội, công chúa Margrethe muốn mọi chuyện trở lại bình thường khi cô vật lộn duy trì hình tượng hoàn hảo trong khi đối mặt với rắc rối gia đình.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Elli Rhiannon Müller Osborne","avatar":""},{"name":"Ines Høysæter Asserson","avatar":""},{"name":"Mathias Storhøi","avatar":""},{"name":"Amalie Sporsheim","avatar":""},{"name":"Sammy Germain Wadi","avatar":""},{"name":"Filip Bargee Ramberg","avatar":""},{"name":"Frode Winther","avatar":""},{"name":"Kirsti Stubø","avatar":""},{"name":"Julie Agnete Vang","avatar":""},{"name":"Afshin Firouzi","avatar":""},{"name":"Evelyn Rasmussen Osazuwa","avatar":""},{"name":"Tarjei Sandvik Moe","avatar":""},{"name":"Anderz Eide","avatar":""},{"name":"I","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324258);
