INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pro-detective-2023', 'Pro Detective', 'Pro Detective', 'https://phimimg.com/upload/vod/20230914-1/492e5c4d4159e348df25f6cc6a410539.webp', 'https://phimimg.com/upload/vod/20230914-1/1e4748c53fa3a005c1a1b1562f30ddf4.jpg', '<p>Câu chuyện này kể về một mạng lưới bầu trời thưa thớt và không bị rò rỉ, và cái ác không thể thắng cái thiện, Giám đốc đồn cảnh sát Đinh, thanh tra và doanh nhân giàu có địa phương Feng Datou cấu kết với những người nước ngoài và những kẻ phản bội để bán lại thuốc phiện vì mục đích ích kỷ của họ, và họ đã hy sinh bản thân để tìm ra kho báu huyền thoại, mạng sống của gia đình Tôn và gia vô tội hoàn toàn bị coi thường vì sự nguy hiểm của đất nước. Nữ thám tử Hoắc Thanh đến thị trấn Pujiang cùng với trợ lý tay phải Yan&#39;er, tuy có nhiều hiểu lầm với phó giám đốc đồn cảnh sát Hình Nghị nhưng may mắn là họ đã giải quyết kịp thời, ba người đã cùng nhau giải quyết. Vụ án giết người của nhà họ Tôn và nhà họ Chu, đồng thời vạch trần tội ác phản quốc của thanh tra Ding và Feng Datou, sự thật của mọi vụ án được tiết lộ, kẻ xấu bị trừng phạt xứng đáng, và thị trấn Pujiang trở lại như xưa. hòa bình trước đây.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 17, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"LI MAN","avatar":""},{"name":"Song Hong Yu","avatar":""},{"name":"Yang Yi","avatar":""},{"name":"Li Ze Yu","avatar":""},{"name":"Lei Kun","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324258);
