INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thu-ban-tia-phan-kich', 'Xạ Thủ Bắn Tỉa: Phản Kích', 'Sniper: Vengeance', 'https://phimimg.com/upload/vod/20231119-1/a93d656bd900ef6ddcbbde704e68658a.jpg', 'https://phimimg.com/upload/vod/20231119-1/1e03d67ca9f019549e0e11af1f2993ed.jpg', '<p>Tiểu đội Phong Bão bị phục kích bởi đội U Linh trong một nhiệm vụ hộ tống, và đội trưởng Cao Chiêm (do Vu Vinh Quang thủ vai) thoát chết dưới sự bảo vệ của đồng đội. Nửa năm sau, biệt đội Mãnh Hổ do Cao Chiêm và Bàng Kiến (do Hình n thủ vai) một lần nữa đối đầu với Biệt đội U Linh để giải cứu các nhà khoa học. Trong quá trình giải cứu con tin, những âm mưu to lớn ẩn chứa phía sau dần được hé lộ. Cao Chiêm và Mãnh Hổ lại bị phục kích và buộc phải chống trả, hóa ra mọi thứ đều nằm trong kế hoạch của Cao Chiêm. Cuối cùng, Cao Chiêm và Bàng Kiến đã chung tay bắt đầu cuộc đối đầu sinh tử với các thế lực thù địch</p>', 'Full', 1, 'single', 'completed', 9, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Rongguang","avatar":""},{"name":"Xing En","avatar":""},{"name":"Hong Shuang","avatar":""},{"name":"Yu Bolin","avatar":""},{"name":"Jane Wu","avatar":""},{"name":"Guo Mingyu","avatar":""},{"name":"Xun Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324258);
