INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-dac-vu-pathaan', 'Siêu Đặc Vụ Pathaan', 'Pathaan', 'https://phimimg.com/upload/vod/20231115-1/19ca5426673f2339be20926c76a15e1c.jpg', 'https://phimimg.com/upload/vod/20231115-1/b45232ba701e67f16dd23f44b3a5b5c1.jpg', '<p>Pathaan (Shah Rukh Khan) - 1 đặc vụ siêu cấp của Ấn Độ trạm chán với Jim (John Abraham) - cựu đặc vụ giỏi nhất Ấn Độ trong cuộc chiến ngăn chặn thảm họa vũ khí sinh học đe dọa đến toàn thể nhân loại. Trong quá trình, Pathaan lần đầu tiên gặp thất bại bởi mỹ nhân Rubai (Deepika Padukone), bên cạnh đó, Pathaan cũng được giúp đỡ bởi 1 đặc vụ xuất chúng khác Tiger (Salman Khan) sau khi anh bại bởi mỹ nhân để tiếp tục nhiệm vụ của 1 người lính chiến đấu cho đất Mẹ Ấn Độ!</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Shah Rukh Khan","avatar":""},{"name":"Deepika Padukone","avatar":""},{"name":"John Abraham","avatar":""},{"name":"Dimple Kapadia","avatar":""},{"name":"Ashutosh Rana","avatar":""},{"name":"Salman Khan","avatar":""},{"name":"Akash Bhatija","avatar":""},{"name":"Prakash Belawadi","avatar":""},{"name":"Viraf Patel","avatar":""},{"name":"Shaji Choudhary","avatar":""},{"name":"Diganta Hazarika","avatar":""},{"name":"Rajat Kaul","avatar":""},{"name":"Prem Jhangiani","avatar":""},{"name":"Keith Sequeira","avatar":""},{"name":"Manish Wadhwa","avatar":""},{"name":"Ashutosh Singh","avatar":""},{"name":"Grace G","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
