INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-the-gioi-ngam', 'Trận Chiến Thế Giới Ngầm', 'Kill the Drug Lords', 'https://phimimg.com/upload/vod/20231115-1/7d7f3107af29973ac41b731ca748132b.jpg', 'https://phimimg.com/upload/vod/20231115-1/10c150154893c83a5f97c2e13db32457.jpg', '<p>Bộ phim kể về câu chuyện của các sĩ quan cảnh sát công an như Cục trưởng Cục Cảnh Sát Lãnh Kiệt và cảnh sát chìm Trương Chính Dương cùng chiến đấu chống lại các nhóm tội phạm thế giới ngầm và sau cùng anh dũng hy sinh. Đồng thời khắc hoạ tình đồng chí, tình gia đình, tình yêu thương, làm thăng hoa hình ảnh người chiến sĩ công an nhân dân cũng bằng xương bằng thịt nhưng có thể đứng dậy trong gian nguy, bên cạnh đó truyền tải đến xã hội sự đúng đắn của đề cao công lý và thượng tôn pháp luật.\nBộ phim thể hiện mặt thiết yếu và kiên quyết của Đảng và Nhà nước trong công cuộc đấu tranh chống tội phạm bằng cách phơi bày tội ác của bọn côn đồ và thế lực xấu xa gây nguy hiểm cho an ninh xã hội và người dân, thể hiện quan niệm đặt nhân dân lên hàng đầu và diễn giải chân lý “Chính nghĩa luôn chiến thắng cái ác”, tiếp nối truyền thống vẻ vang của Đảng là luôn nghĩ đến sự an toàn và hạnh phúc của người dân.\nCuối cùng, bằng cách đưa ra các kết cục khác nhau của nhân vật chính diện và phản diện, bộ phim truyền tải những giá trị đúng đắn, giá trị đạo đức và nhân sinh quan đến thế hệ trẻ, trên đời này không có con đường tắt dẫn đến thành công.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ding Haifeng","avatar":""},{"name":"Zhao Zhen Ting","avatar":""},{"name":"Wang Zhipeng","avatar":""},{"name":"Gao Chenglong","avatar":""},{"name":"Fu Xiaoshuang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324258);
