INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('um-ano-inesquecivel-inverno', 'Um Ano Inesquecível - Inverno', 'An Unforgettable Year – Winter', 'https://phimimg.com/upload/vod/20231125-1/26a73f489e80830429643768fd56dae2.jpg', 'https://phimimg.com/upload/vod/20231125-1/cc98d2c3aa5794fc9c1d20e32a6dc80f.jpg', '<p>Thay vì tham gia chuyến đi tốt nghiệp cùng bạn bè, Mabel buộc phải cùng bố mẹ đến một khu trượt tuyết ở Chile. Chỉ có điều cô ấy không ngờ rằng khóa tu lạnh giá này có thể giới thiệu cô ấy với một nhóm bạn bí mật và một tình yêu mới tiềm năng.</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Maitê Padilha","avatar":""},{"name":"Michel Joelsas","avatar":""},{"name":"Letícia Spiller","avatar":""},{"name":"Marcelo Laham","avatar":""},{"name":"Rita von Hunty","avatar":""},{"name":"João Manoel","avatar":""},{"name":"Catarina de Carvalho","avatar":""},{"name":"Larissa Murai","avatar":""},{"name":"Lumi Kim","avatar":""},{"name":"Giulia Nassa","avatar":""},{"name":"Victorinha","avatar":""},{"name":"Lívia Inhudes","avatar":""},{"name":"Miguel Trajano","avatar":""},{"name":"Lilibell Cepedillo","avatar":""},{"name":"Carolina Stofella","avatar":""},{"name":"Dani Solano","avatar":""},{"name":"Fernand","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324258);
