INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('um-ano-inesquecivel-inverno', 'Um Ano Inesquecível - Inverno', 'An Unforgettable Year – Winter', 'um ano inesquecível - inverno an unforgettable year – winter maitê padilha michel joelsas letícia spiller marcelo laham rita von hunty joão manoel catarina de carvalho larissa murai lumi kim giulia nassa victorinha lívia inhudes miguel trajano lilibell cepedillo carolina stofella dani solano fernand ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-girl-from-the-other-side-siuil-a-run', 'The Girl From the Other Side: Siúil, a Rún', 'Totsukuni no Shoujo', 'https://phimimg.com/upload/vod/20231113-1/249bcbdfb27590eda9dd2a15b2296fc8.jpg', 'https://phimimg.com/upload/vod/20231113-1/e6c9a67e57553edbcc263e0121dc3e29.jpg', '<p>Ngày xửa ngày xưa, ở một nơi xa xôi, hẻo lánh, có hai vùng đất. Thế giới được chia thành vùng đất bên trong và vùng đất bên ngoài. Mọi người sợ hãi vùng đất bên ngoài, nơi sinh sống của những sinh vật kỳ lạ, những kẻ mang lời nguyền. Một ngày nọ, trên biên giới đến vùng đất nội địa có con người sinh sống, một sinh vật như vậy tìm thấy một cô gái trên đống xác chết bị bỏ rơi. Cô gái nói tên của mình là Shiva và thể hiện tình cảm với &quot;người&quot; đã tìm thấy cô, gọi anh ta là &quot;Sư phụ&quot;. Đây là câu chuyện về hai người — một con người, một phi nhân — sống sót trong ánh hoàng hôn mờ ảo ngăn cách giữa đêm và ngày.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Jun Fukuyama","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Hiroki Goto","avatar":""},{"name":"Tadashi Miyazawa","avatar":""},{"name":"Kouichi Sakaguchi","avatar":""},{"name":"Daiki Kobayashi","avatar":""},{"name":"Kento Shiraishi","avatar":""},{"name":"Kazuya Saji","avatar":""},{"name":"Tooru Arizumi","avatar":""},{"name":"Akira Orihara","avatar":""},{"name":"Haruna Kakiage","avatar":""},{"name":"Shio Kisui","avatar":""},{"name":"Mitsuka Abe","avatar":""},{"name":"Miyu Hanasaki","avatar":""},{"name":"Kanon Fujimura","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324258);
