INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hen-thu-ba-dai-nhat', 'Cuộc hẹn thứ ba dài nhất', 'Longest Third Date', 'https://phimimg.com/upload/vod/20231113-1/09585b1a08f73ac530c5c125f564e6a2.jpg', 'https://phimimg.com/upload/vod/20231113-1/daa1f806a70e4c5010d221a06528df73.jpg', '<p>Gặp nhau trên một ứng dụng hẹn hò, Khani và Matt nào ngờ COVID-19 sẽ biến chuyến đi ngẫu hứng của họ tới Costa Rica thành cuộc phiêu lưu kéo dài hàng tháng trời.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Robertson","avatar":""},{"name":"Khani Le","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324258);
