INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-danh-2023', 'Vô Danh', 'Hidden Blade', 'https://phimimg.com/upload/vod/20230915-1/61b6763cbc27d682b6ace09b1baa9e56.jpg', 'https://phimimg.com/upload/vod/20230915-1/20baa8e423cdca8fbdc5f745702f57cd.jpg', '<p><span style="font-family: ">Bộ phim kể về câu chuyện của những người làm việc ngầm, rủi ro tất cả để truyền đi thông tin trong cuộc kháng chiến toàn diện, bằng cả tâm huyết và sinh mạng, để bảo vệ đất nước. Ngày 7 tháng 12 năm 1941, Nhật Bản tấn công Trân Châu Cảng. Ngày hôm sau, chính phủ đồng minh của Uông Tinh Vệ theo sau Nhật Bản tuyên chiến với Anh và Mỹ, và Nhật Bản tiến hành chiếm đóng toàn bộ lãnh thổ Thượng Hải với tư cách biểu tượng. Với sự bùng nổ toàn diện của Chiến tranh Thái Bình Dương, tình hình kháng chiến của Trung Quốc cũng thay đổi hoàn toàn.</span></p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Wang Yibo","avatar":""},{"name":"Zhou Xun","avatar":""},{"name":"Eric Wang","avatar":""},{"name":"Huang Lei","avatar":""},{"name":"Dong Chengpeng","avatar":""},{"name":"Maggie Jiang","avatar":""},{"name":"Zhang Jingyi","avatar":""},{"name":"Hiroyuki Mori","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324258);
