INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-thu', 'Hà Thú', 'BEAST IN RIVER', 'https://phimimg.com/upload/vod/20231123-1/da72af69873b4927386b35a0b3705b98.jpg', 'https://phimimg.com/upload/vod/20231123-1/508758c14f5a8a0f92b38bae0b023a9b.jpg', '<p>Vào những năm đầu Trung Hoa Dân Quốc, cái chết kỳ quái của hàng chục công nhân thoát nước khiến người dân hoang mang, những xác chết không mảnh vải che thân nổi trên sông khiến thầy cúng khẳng định có ma nước và trấn đã gặp nguy hiểm lớn. Cảnh sát Cố Trí Viễn dựa vào những công việc nhỏ ở bến tàu để duy trì kế sinh nhai của anh và nuôi con gái.Vào ngày này, con quái vật hung ác trên sông đã lao vào bờ phá hủy nhà cửa và tính mạng của dân chúng, thậm chí còn bắt cóc con gái Cố Trí Viễn. Để cứu con gái mình, Trí Viễn đã bắt tay với Đường Tiểu Duy dể bắt đầu hành trình chuộc lỗi và tiêu diệt quái thú.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Ting Wen","avatar":""},{"name":"Lin Yo-Wei","avatar":""},{"name":"Hong Siyang","avatar":""},{"name":"Chen Rui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324258);
