INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-sac-cuong-hoa-long-tich-than-cung', 'Tuyệt Sắc Cuồng Hoa: Long Tích Thần Cung', 'The Dragon Trace Palace of Exquisite Wild Flowers', 'https://phimimg.com/upload/vod/20231111-1/7d375cdaf439451b9209ba0d28ea9159.jpg', 'https://phimimg.com/upload/vod/20231111-1/062343b8cbb7edd9f70998bb9dafac10.jpg', '<p>Lâm Tịch Du , Lâm Nhạc Dao và Lãnh Anh là ba thành viên của đội đặc công mang tên Hoa Bỉ Ngạn. Ba người họ đến khu vực sa mạc để cứu một nhóm khảo cổ bị mất liên lạc. Họ thành công đến ứng cứu nhưng không thể quay trở lại mặt đất và buộc phải dấn sâu vào ngôi mộ cổ để tìm đường ra. Đoàn khảo cổ vì muốn nghiên cứu nên đã tự tiện lấy cổ vật nên đã kích hoạt các cơ quan trong cổ thành. Lâm Tịch Du cố gắng đến mấy vẫn không cứu sống các thành viên trong đội khảo cổ. Lâm Nhạc Dao đã trao lại cơ hội sống sót duy nhất cho chị mình, bản thân cô em gái lại không còn lối thoát. Lâm Tịch Du và Lãnh Anh rời khỏi ngôi mộ và mang theo một viên ngọc trắng, Lâm Tịch Du nhận ra rằng viên ngọc trắng chính là một trong hai chiếc chìa khóa để mở cổ máy thời không</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Yongxi","avatar":""},{"name":"Li Yutong","avatar":""},{"name":"Cai Xuanyi","avatar":""},{"name":"Guo Zhen","avatar":""},{"name":"Xu Tieren","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324258);
