INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('85-south-giai-thoai-duong-pho', '85 South: Giai thoại đường phố', '85 South: Ghetto Legends', 'https://phimimg.com/upload/vod/20231109-1/b6dc7dbc8ae6773dab8d9f00b233a855.jpg', 'https://phimimg.com/upload/vod/20231109-1/18abf628f1442e5cdf13190e1b6bb088.jpg', '<p>DC Young Fly, Karlous Miller và Chico Bean mang podcast nổi tiếng lên sân khấu của sự kiện hài có một không hai, nơi không có gì vượt quá giới hạn và không ai ngần ngại điều chi.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"D.C. Young Fly","avatar":""},{"name":"Chico Bean","avatar":""},{"name":"Karlous Miller","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324258);
