INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('flash', 'Flash', 'The Flash', 'https://phimimg.com/upload/vod/20230915-1/e50bfb110fad81abfd8d90aaf95c6559.jpg', 'https://phimimg.com/upload/vod/20230915-1/b736540e934fe99e07146ca8e9157e0f.jpg', '<p><span style="font-family: ">Câu chuyện của Flash bắt đầu khi Barry Allen (Ezra Miller thủ vai) sử dụng siêu năng lực của mình để du hành thời gian nhằm thay đổi những sự kiện trong quá khứ. Nhưng khi nỗ lực cứu lấy gia đình mình vô tình thay đổi tương lai, Barry bị kẹt lại trong một thực tại, nơi tướng Zod tái xuất và đe dọa hủy diệt tất cả, nhưng không có bất cứ siêu anh hùng nào đứng ra giải cứu… Trừ khi Barry có thể thuyết phục một Batman rất khác và giải cứu một cư dân Kryptonian đang bị cầm tù… dẫu có thể đó không phải người mà anh thực sự tìm kiếm. Để giải cứu thế giới hiện tại cũng như trở lại tương lai mình từng biết, niềm hy vọng duy nhất của Barry là phải chạy đua vì cuộc đời mình. Vậy nhưng, sự hy sinh tuyệt đối đó có là đủ để đưa thế giới về lại như ban đầu?</span></p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ezra Miller","avatar":""},{"name":"Sasha Calle","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Ron Livingston","avatar":""},{"name":"Maribel Verdú","avatar":""},{"name":"Kiersey Clemons","avatar":""},{"name":"Antje Traue","avatar":""},{"name":"Saoirse-Monica Jackson","avatar":""},{"name":"Rudy Mancuso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68