INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lewis-capaldi-cam-giac-cua-toi-luc-nay', 'Lewis Capaldi: Cảm giác của tôi lúc này', 'Lewis Capaldi: How I''m Feeling Now', 'https://phimimg.com/upload/vod/20231108-1/be6deacc8568c0c023eeed9a8d9fae28.jpg', 'https://phimimg.com/upload/vod/20231108-1/05ec7e61db4c32898aad919899751623.jpg', '<p>Bộ phim tài liệu chân thật, hé lộ tất cả này ghi lại hành trình của Lewis Capaldi từ thiếu niên tham vọng có màn trình diễn nổi tiếng đến ngôi sao nhạc pop được đề cử giải Grammy.</p>', 'Full', 1, 'single', 'completed', 12, 2023, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Lewis Capaldi","avatar":""},{"name":"Jeremy Clarkson","avatar":""},{"name":"Danny O''Donoghue","avatar":""},{"name":"Tom Jones","avatar":""},{"name":"Stephen Colbert","avatar":""},{"name":"Jonathan Ross","avatar":""},{"name":"James Corden","avatar":""},{"name":"Alicia Keys","avatar":""},{"name":"Greg James","avatar":""},{"name":"Roman Kemp","avatar":""},{"name":"Sonny Jay","avatar":""},{"name":"Sian Welby","avatar":""},{"name":"Naga Munchetty","avatar":""},{"name":"Charlie Stayt","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324258);
