INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diet-hon', 'Diệt Hồn', 'Ghost Killing', 'https://phimimg.com/upload/vod/20231113-1/313a81f01a838a9c072ddd64f28f4833.jpg', 'https://phimimg.com/upload/vod/20231113-1/c48f409557bd34ec31484c74c6479be5.jpg', '<p>Trong thời Trung Hoa Dân Quốc, cảnh sát Bắc Hải Thám tử Trương Nhất Nhân&nbsp; được lệnh điều tra một vụ án giết người kỳ quái ở thị trấn Thái Bình. Trong quá trình điều tra, lại xảy ra những cái chết liên hoàn và&nbsp; rất kinh hoàng. Cuối cùng, với sự giúp đỡ của những người ăn xin Trương Nhất Nhân đã đưa kẻ sát nhân ra trước công lý. Đồng thời, anh cũng nhận thấy dường như có một bí mật khác đằng sau những vụ giết người hàng loạt.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Du Yiheng","avatar":""},{"name":"Xue Ke","avatar":""},{"name":"Liu Yajin","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Hu Yuying","avatar":""},{"name":"Zhou Sanyou","avatar":""},{"name":"Li Shu","avatar":""},{"name":"Han Qiuchi","avatar":""},{"name":"Du Jiangshan","avatar":""},{"name":"Xu Xiaoqin","avatar":""},{"name":"Wu Ningyan","avatar":""},{"name":"Li Shiyan","avatar":""},{"name":"Yu Huitao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
