INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhien-dong', 'Nhiên Đông', 'The Breaking Ice', 'https://phimimg.com/upload/vod/20231103-1/49d8a4432c7418458f1bda623e054fd2.jpg', 'https://phimimg.com/upload/vod/20231103-1/0435eda78fc255dda7b6ef3bdd6448cd.jpg', '<p>Trong mùa đông lạnh giá Yanji, một thành phố ở biên giới phía bắc Trung Quốc, Haofeng, một thanh niên thành thị, đến từ Thượng Hải, cảm thấy lạc lõng và lạc lõng. Tình cờ, anh tham gia một chuyến du lịch do Nana, một hướng dẫn viên du lịch quyến rũ, người ngay lập tức mê hoặc anh. Cô giới thiệu anh với Xiao, một nhân viên nhà hàng duyên dáng nhưng thất vọng. Cả ba nhanh chóng gắn bó trong một ngày cuối tuần say khướt. Đối mặt với những tổn thương cá nhân, những ham muốn băng giá của họ dần tan biến khi họ tìm cách giải phóng bản thân khỏi một thế giới băng giá.</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Dongyu","avatar":""},{"name":"Liu Haoran","avatar":""},{"name":"Qu Chuxiao","avatar":""},{"name":"Ruguang Wei","avatar":""},{"name":"Baisha Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324258);
