INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-segura-bua-ta', 'Tom Segura: Búa tạ', 'Tom Segura: Sledgehammer', 'https://phimimg.com/upload/vod/20231101-1/fcdf72bc04c714de2602fb3992962445.jpg', 'https://phimimg.com/upload/vod/20231101-1/698803bce2567549c325d8788431d3d8.jpg', '<p>Từ lời thú tội khác thường lúc lâm chung của bố cho đến việc chứng kiến mẹ lên cơn phê, Tom Segura kể những câu chuyện thẳng thắn đến kinh ngạc về hôn nhân, cái chết, v.v.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Segura","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324258);
