INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-van-dao', 'Tây Du Vấn Đạo', 'Journey to the West: Ask tao', 'https://phimimg.com/upload/vod/20231101-1/389f592422d63fdb11608002d01ffb78.jpg', 'https://phimimg.com/upload/vod/20231101-1/61338493e6c9d6703071c2ebbc998446.jpg', '<p>Phim kể về câu chuyện Tôn Ngộ Không đánh bại Đức Phật và cùng với tróc yêu sư Hoa Tình giải cứu tất cả chúng sinh trong yêu giới. Từ thời Bàn Cổ mở cõi Hồng Mông, trận chiến giữa thần tộc và yêu tộc chưa từng dừng lại. Tôn Ngộ Không phạm tội ác tày trời đi theo Đường Tăng đến Tây Thiên thỉnh kinh, trên đường đi Ngộ Không đã đánh bại và phong ấn người bạn cũ Ngưu Ma Vương đến báo thù, từ đó Tôn Ngộ Không bị yêu tộc coi là kẻ phản bội không thể tha thứ. Cùng lúc đó, nhân lúc Bồ Tát phải thực hiện giới luật, Hồng Hài Nhi vì muốn dùng sức mình gầy dựng lại vinh quang của yêu tộc, đã giết Ngộ Không để báo thù cho yêu tộc và giải cứu Ngưu Ma Vương. Nhờ vào pháp lực mạnh mẽ, Hồng Hài Nhi được yêu tộc tôn làm Yêu Vương. Dưới sự lãnh đạo của y, toàn bộ yêu tộc hừng hực nhiệt huyết, hăng hái gây rối và giết người vô tội một cách bừa bãi. \nĐể giải cứu chúng sinh, Tôn Ngộ Không quay trở lại cõi phàm trần, trên đường đi hắn bắt gặp tróc yêu sư Hoa Tình, cả hai cùng bắt tay hợp tác để chống lại Yêu Vương Hồng Hài Nhi. Vì yêu tộc tàn sát Thần tộc và tróc yêu sư, Nhị lang thần Dương Tiễn đã ra lệnh giết thẳng tay toàn bộ yêu tộc, khó tránh khỏi một trận chiến đẫm máu giữa thần tộc và yêu tộc.</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sammy Hung","avatar":""},{"name":"Kimmy Tong Fei","avatar":""},{"name":"Lanyi Zhang","avatar":""},{"name":"Xu Jingwen","avatar":""},{"name":"Edward Chui","avatar":""},{"name":"Hou Jiawei","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324258);
