INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-knight-ngay-doc-lap', 'Thám Tử Knight : Ngày Độc Lập', 'Detective Knight: Independence', 'https://phimimg.com/upload/vod/20231029-1/2d52b0356c279ef5a17c8628e68e0978.jpg', 'https://phimimg.com/upload/vod/20231029-1/f8ba2e0bc59a4c691252022dbace45d9.jpg', '<p>Nhiệm vụ vào phút cuối của thám tử James Knight trong ca trực Ngày Độc lập biến thành một cuộc chạy đua để ngăn chặn một chiếc xe cứu thương EMT không cân bằng gây nguy hiểm cho các lễ hội của thành phố. Người cảnh giác lầm đường, đóng vai cảnh sát với khẩu súng và đồng phục bị đánh cắp, có một kho tiền ngân hàng đầy lý do để tổ chức màn trình diễn pháo hoa của riêng mình… một màn trình diễn sẽ tấn công nguy hiểm gần nhà của Knight.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Jack Kilmer","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Jimmy Jean-Louis","avatar":""},{"name":"Willow Shields","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Timothy V. Murphy","avatar":""},{"name":"Lorenzo Antonucci","avatar":""},{"name":"Joe Munroe","avatar":""},{"name":"Dax Campbell","avatar":""},{"name":"Robert Laenen","avatar":""},{"name":"Xzavier Estrada","avatar":""},{"name":"Francis Cronin","avatar":""},{"name":"Kimberley Christann Pember","avatar":""},{"name":"Cesar Miramontes","avatar":""},{"name":"Craine Jo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
