INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-thien-nga-cau-chuyen-than-tien', 'Công Chúa Thiên Nga: Câu Chuyện Thần Tiên', 'The Swan Princess: A Fairytale Is Born', 'https://phimimg.com/upload/vod/20231024-1/b978c4cc3d840ab27cece3267f37ecb3.jpg', 'https://phimimg.com/upload/vod/20231024-1/9476802a513a96098301bdd276a9d6e7.jpg', '<p>Trước khi trở thành nữ hoàng, Uberta sống một cuộc sống khiêm tốn với chồng Maximillian khi cô bất ngờ được đưa vào hoàng gia. Thông qua chiến thắng và bi kịch, cô học được những bài học cần thiết để trở thành Nữ hoàng được yêu mến, đồng thời nuôi dưỡng thế hệ cai trị tiếp theo. Khi đến lúc Uberta trao quyền trượng hoàng gia cho Odette và Derek, Nữ hoàng Wixom đối địch có kế hoạch của riêng mình để phá hỏng lễ đăng quang vĩ đại nhất của vương quốc.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nina Herzog","avatar":""},{"name":"Yuri Lowenthal","avatar":""},{"name":"Jennifer Miller","avatar":""},{"name":"Bleau Essen","avatar":""},{"name":"Grant Durazzo","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324258);
