INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-thu-vi-cung-ban-be-2', 'Kỳ Nghỉ Thú Vị Cùng Bạn Bè 2', 'Vacation Friends 2', 'https://phimimg.com/upload/vod/20231022-1/8e7d95c8dbbd71a4e3f5ffedfe7b9cfd.jpg', 'https://phimimg.com/upload/vod/20231022-1/6a216a98923b006ba0524d9e9189c75d.jpg', '<p>Cặp vợ chồng mới cưới Marcus và Emily mời hai người bạn thân tự do Ron và Kyla đi nghỉ cùng họ khi Marcus có chuyến đi được đài thọ toàn bộ chi phí tới một khu nghỉ dưỡng ở Caribe. Khi người cha Reese đang bị giam giữ của Kyla được trả tự do và xuất hiện tại khu nghỉ dưỡng mà không báo trước, mọi thứ vượt quá tầm kiểm soát, làm đảo lộn những kế hoạch tốt nhất mà Marcus đã đặt ra và biến chuyến đi hoàn hảo của những người bạn trong kỳ nghỉ trở nên hỗn loạn hoàn toàn.</p>', 'Full', 1, 'single', 'completed', 10, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lil Rel Howery","avatar":""},{"name":"Yvonne Orji","avatar":""},{"name":"John Cena","avatar":""},{"name":"Meredith Hagner","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Carlos Santos","avatar":""},{"name":"Ronny Chieng","avatar":""},{"name":"Arnold Y. Kim","avatar":""},{"name":"Jamie Hector","avatar":""},{"name":"Lovensky Jean-Baptiste","avatar":""},{"name":"Julee Cerda","avatar":""},{"name":"Hugh Moore","avatar":""},{"name":"T. Love","avatar":""},{"name":"Kevin Yamada","avatar":""},{"name":"Brandon St. Clair","avatar":""},{"name":"Mariana Novak","avatar":""},{"name":"Chris Costanz","avatar":""},{"name":"Max","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324258);
