INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-bi-mat', 'Vương Quốc Bí Mật', 'The Secret Kingdom', 'https://phimimg.com/upload/vod/20231022-1/298e592726bb625e5df1353ae95f3403.jpg', 'https://phimimg.com/upload/vod/20231022-1/071c500cc761f822bca3e00a7e287867.jpg', '<p>Chuyến đi của Verity và Peter đến dinh thự cũ của gia đình rẽ sang một hướng khác khi sàn phòng của họ đột nhiên nhường chỗ và họ rơi vào một căn phòng dưới lòng đất, nơi họ gặp một nền văn minh của sinh vật. Người lãnh đạo nói với họ rằng sự xuất hiện của Peter đã được báo trước vì anh ấy là người có thể sử dụng Đồng hồ vĩ đại của Thành cổ để khởi động lại thời gian và tiêu diệt Shroud, một sinh vật độc ác sống bằng chính nỗi sợ hãi...</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Sam Everingham","avatar":""},{"name":"Alyla Browne","avatar":""},{"name":"Alice Parkinson","avatar":""},{"name":"Beth Champion","avatar":""},{"name":"Christopher Gabardi","avatar":""},{"name":"Darius Williams","avatar":""},{"name":"Gabrielle Chan","avatar":""},{"name":"Rowland Holmes","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324258);
