INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-soi-tuoi-teen-ban-dien-anh', 'Người Sói Tuổi Teen: Bản Điện Ảnh', 'Teen Wolf: The Movie', 'https://phimimg.com/upload/vod/20231020-1/e55b891301480cebce64fc8c8bcb8449.jpg', 'https://phimimg.com/upload/vod/20231020-1/a3f5a74ef0ccb7b0b01d64f7c8a690a4.jpg', '<p>Trăng tròn mọc ở Beacon Hills, và cùng với đó là một ác quỷ đáng sợ đã xuất hiện. Những con sói lại hú lên, kêu gọi sự trở lại của Banshees, Werecoyotes, Hellhounds, Kitsunes và mọi kẻ biến hình khác trong đêm. Nhưng chỉ một người sói như Scott McCall, không còn là một thiếu niên nhưng vẫn là một Alpha, mới có thể tập hợp cả hai đồng minh mới và đoàn tụ những người bạn đáng tin cậy để chống lại kẻ thù có thể là mạnh nhất và nguy hiểm nhất mà họ từng đối mặt.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tyler Posey","avatar":""},{"name":"Crystal Reed","avatar":""},{"name":"Holland Roden","avatar":""},{"name":"Tyler Hoechlin","avatar":""},{"name":"Shelley Hennig","avatar":""},{"name":"JR Bourne","avatar":""},{"name":"Ian Bohen","avatar":""},{"name":"Colton Haynes","avatar":""},{"name":"Linden Ashby","avatar":""},{"name":"Melissa Ponzio","avatar":""},{"name":"Ryan Kelley","avatar":""},{"name":"Seth Gilliam","avatar":""},{"name":"Orny Adams","avatar":""},{"name":"Dylan Sprayberry","avatar":""},{"name":"Khylin Rhambo","avatar":""},{"name":"Aaron Hendry","avatar":""},{"name":"Vince Mattis","avatar":""},{"name":"Amy L. Workman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324258);
