INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('renfield-tay-sai-cua-quy', 'Renfield: Tay Sai Của Quỷ', 'Renfield', 'https://phimimg.com/upload/vod/20231019-1/2ca1793f05540b521bee2cb290526fd1.jpg', 'https://phimimg.com/upload/vod/20231019-1/e7f805e51db10206f5b352e8eb30c94a.jpg', '<p>Renfield phát ốm vì mối quan hệ đồng phụ thuộc kéo dài hàng thế kỷ với Dracula. Với hy vọng tạo dựng một cuộc sống mới ở thế giới con người, tại New Orleans thời hiện đại, cuộc sống của Renfield trở nên phức tạp hơn khi anh phải lòng một cảnh sát giao thông. Mà trong lúc đó, anh ta vẫn phải đối phó với những yêu cầu, đòi hỏi quái lạ từ Dracula - một ông chủ thực sự đến từ địa ngục.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nicholas Hoult","avatar":""},{"name":"Nicolas Cage","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Ben Schwartz","avatar":""},{"name":"Shohreh Aghdashloo","avatar":""},{"name":"Brandon Scott Jones","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Camille Chen","avatar":""},{"name":"Bess Rous","avatar":""},{"name":"Jenna Kanell","avatar":""},{"name":"Danya LaBelle","avatar":""},{"name":"Rhonda Johnson Dents","avatar":""},{"name":"Christopher Matthew Cook","avatar":""},{"name":"Michael P. Sullivan","avatar":""},{"name":"Rosha Washington","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324258);
