INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-nghi-chet-choc', 'Hội Nghị Chết Chóc', 'The Conference', 'https://phimimg.com/upload/vod/20231018-1/7ca95803b380963a86d52c2c8141ba32.jpg', 'https://phimimg.com/upload/vod/20231018-1/78484d89b410bfeb31a3d2f35d0bea47.jpg', '<p>Trong kỳ nghỉ tưởng chừng vô hại, một nhóm nhân viên khu vực công đủ thành phần không chỉ chiến đấu với mối bất hòa của chính họ mà còn với tên sát nhân khát máu.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Katia Winter","avatar":""},{"name":"Adam Lundgren","avatar":""},{"name":"Eva Melander","avatar":""},{"name":"Bahar Pars","avatar":""},{"name":"Amed Bozan","avatar":""},{"name":"Maria Sid","avatar":""},{"name":"Christoffer Nordenrot","avatar":""},{"name":"Claes Hartelius","avatar":""},{"name":"Cecilia Nilsson","avatar":""},{"name":"Lola Zackow","avatar":""},{"name":"Marie Agerhäll","avatar":""},{"name":"Jimmy Lindström","avatar":""},{"name":"Martin Lagos","avatar":""},{"name":"Robert Follin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
