INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-ac-quy', 'Âm Mưu Ác Quỷ', 'The Devil Conspiracy', 'https://phimimg.com/upload/vod/20231017-1/55153c9a4dcb3efeffabb3cf225ca3b6.jpg', 'https://phimimg.com/upload/vod/20231017-1/5cc0ef49be34d8e84b6daa2d69982b2c.jpg', '<p>Một công ty công nghệ sinh học hùng mạnh có công nghệ đột phá cho phép họ nhân bản những người có ảnh hưởng nhất trong lịch sử chỉ bằng một vài đoạn DNA. Đằng sau công ty này là một nhóm những người theo chủ nghĩa Satan đánh cắp tấm vải liệm của Chúa Kitô, khiến họ sở hữu DNA của Chúa Jesus. Bản sao này sẽ đóng vai trò là lễ vật cuối cùng cho quỷ dữ. Tổng lãnh Thiên thần Michael đến trái đất và sẽ không dừng lại ở đó để chấm dứt âm mưu của quỷ dữ.</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Séc', 0, '[{"name":"Alice Orr-Ewing","avatar":""},{"name":"Joe Doyle","avatar":""},{"name":"Eveline Hall","avatar":""},{"name":"Peter Mensah","avatar":""},{"name":"Joe Anderson","avatar":""},{"name":"Brian Caspe","avatar":""},{"name":"Spencer Wilding","avatar":""},{"name":"James Faulkner","avatar":""},{"name":"Victoria Chilap","avatar":""},{"name":"Wendy Rosas","avatar":""},{"name":"Natalia Germani","avatar":""},{"name":"Pavel Kříž","avatar":""},{"name":"Jiří Valeš","avatar":""},{"name":"Anushka Holding","avatar":""},{"name":"Kevin Michael Clarke","avatar":""},{"name":"Jim High","avatar":""},{"name":"Andrea Scarduzio","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784