INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-khong-moi-2023', 'Khách Không Mời', 'Unwelcome', 'https://phimimg.com/upload/vod/20230922-1/9b019d75cd602f7b0ab12b670e33cb5b.jpg', 'https://phimimg.com/upload/vod/20230922-1/422ec32cd1f460765fbfca4941a89a1f.jpg', '<p>Cặp đôi London Maya and Jamie quyết định tránh xa khói bụi đô thị ồn ào về vùng quê Ireland yên tĩnh để tìm lại chút yên bình trong tâm hồn. Nhưng thứ bây giờ chào đón họ là những con yêu tinh hung ác với khát khao tàn sát ẩn nấp trong khu rừng cổ thụ ngay dưới mảnh vườn mới của họ.</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Hannah John-Kamen","avatar":""},{"name":"Douglas Booth","avatar":""},{"name":"Jamie Lee O''Donnell","avatar":""},{"name":"Chris Walley","avatar":""},{"name":"Kristian Nairn","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Niamh Cusack","avatar":""},{"name":"Lalor Roddy","avatar":""},{"name":"Finbar Lynch","avatar":""},{"name":"Bradley Turner","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324258);
