INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bup-be-ma', 'Búp Bê Ma', 'Spirit Puppet', 'https://phimimg.com/upload/vod/20231014-1/87ab8d7fe104ef57f5d2799246cce9a6.jpg', 'https://phimimg.com/upload/vod/20231014-1/a94405784fb293170c706f23693c8930.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim kể về câu chuyện của Trung Hoa Dân Quốc, nam diễn viên đoàn múa rối Sega sắp kết hôn với vị hôn thê Ubisoft, nhưng sau khi anh ta mang về nhà một con rối bí ẩn, anh ta đã chết vào đêm đó, nghi ngờ tự tử. Ubisoft, người rất buồn nhưng từ chối chấp nhận việc kết thúc vụ tự tử, và Chao Yuan, một sĩ quan cảnh sát nghi ngờ vụ án, quyết định tiếp tục điều tra nguyên nhân cái chết của Sega, và nhiều manh mối hội tụ, và bí mật gây sốc đằng sau con rối dần dần xuất hiện...</span></p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Haosen","avatar":""},{"name":"Gao Weiman","avatar":""},{"name":"Qiang Chuan","avatar":""},{"name":"Wuhan Jiang","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Equus","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324258);
