INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-roi-go-kinh-hoang', 'Con Rối Gỗ Kinh Hoàng', 'The Puppet', 'https://phimimg.com/upload/vod/20231013-1/febe2f8b661c72c829edb3e440c4fd24.jpg', 'https://phimimg.com/upload/vod/20231013-1/e8f67f691f37bd9a493cb2026f065f33.jpg', '<p>Thời Trung Hoa Dân Quốc, Wu Wei, một trí thức trẻ cao cấp, đưa bạn gái và những người anh em tốt của mình về nông thôn để thu thập tin tức. Mọi người đến một thị trấn hẻo lánh - Thị trấn Múa rối, và dưới sự sắp xếp của thị trưởng, họ đã thành công di chuyển vào khu nhà của gia đình Huang. Quản gia của sân nhà họ Hoàng vẻ mặt u ám, dẫn mọi người vào thăm nhà, nhưng chỉ cấm vào phòng trên tầng ba. Wu Wei và bạn gái tò mò đã không nghe lời quản gia và họ đã phát hiện ra âm mưu ẩn giấu từ lâu ở Puppet Town. Wu Wei phải tránh xa những con rối, đồng thời tìm ra sự thật về cái chết bí ẩn của con gái người điều hành đoàn kịch một năm trước.</p>', 'Full', 1, 'single', 'completed', 11, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Terence Yin","avatar":""},{"name":"Carmen Tong","avatar":""},{"name":"Waise Lee","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
