INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-luan-canh', 'Côn Luân Cảnh', 'Mystic Land', 'https://phimimg.com/upload/vod/20231013-1/4f0a9163fa36c4a7ecc7820ea1384d13.jpg', 'https://phimimg.com/upload/vod/20231013-1/a579dfef9d911f68fed370177651f2fc.jpg', '<p>Li Xiang, người bị dày vò bởi sự mất tích bí ẩn của cha mẹ trong quá trình nghiên cứu khoa học, không ngừng tìm kiếm sự thật đằng sau tấm gương Kunlun. Một tai nạn xe hơi đã cho phép Li Xiang cùng những người bạn Lu Yao và Yu Deshui &quot;du hành&quot; đến một song song thế giới xuyên qua Gương Kunlun và rơi vào bẫy của Lei Zeqi. Trong môi trường này, Tam giác sắt đã trải qua nhiều thử thách sinh tử ly kỳ: trận chiến tay đôi với người đá trong căn phòng bí mật, trận chiến đẫm máu cùng với một con trăn zombie... Những người bạn lần lượt hy sinh ở một thế giới khác, Li Xiang đã chết để chiến đấu với con rồng nến, và vô tình đánh thức sức mạnh được lựa chọn trong cơ thể anh ta...</p>', 'Full', 1, 'single', 'completed', 14, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Tingdong","avatar":""},{"name":"Hu Xue''er","avatar":""},{"name":"Ben Liu","avatar":""},{"name":"Ding Huiyu","avatar":""},{"name":"Ryan Yuan","avatar":""},{"name":"Zhong Lei","avatar":""},{"name":"Zhengzheng Pei","avatar":""},{"name":"Ci Zhang","avatar":""},{"name":"Roada Xu","avatar":""},{"name":"Zhu Haijun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324258);
