INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-la-dan-gian-nguy-hi-ban', 'Chuyện Lạ Dân Gian : Ngụy Hi Ban', 'Folklore Strange Smell of The Strange Troupe', 'https://phimimg.com/upload/vod/20231012-1/8c72e1913d112a4f59af2d6bdc2c0148.jpg', 'https://phimimg.com/upload/vod/20231012-1/d63a54104fbc4c6c489a4cebd26381d5.jpg', '<p>Bộ phim này lấy bối cảnh ở một thị trấn xa xôi thời Trung Hoa Dân Quốc, nơi Xu Tianyou nghèo và mẹ anh phải vật lộn để kiếm sống. Trong cơn giông bão, Xu trú ẩn trong một gian hàng, nơi anh gặp ba người đàn ông bí ẩn đang đánh bạc bằng một hộp tiền bạc. Người chiến thắng sẽ lấy tất cả số tiền bên trong hộp. Xu tham gia trò chơi nhưng một trong những người chơi đột nhiên chết sau khi thua cuộc, và Xu nhận ra rằng đây là một trò chơi chết chóc. Sau đó, một số người hầu trong thị trấn bị sát hại và những sự việc kỳ lạ bắt đầu xảy ra. Thám tử Han Ming và con gái của thị trưởng Zhang Paner hợp tác để điều tra và truy tìm kẻ giết người.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
