INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-son-dao-nhan-lac-thien-hoang', 'Bàn Sơn Đạo Nhân: Lạc Thiên Hoang', 'Taoist Priest In The Tomb', 'https://phimimg.com/upload/vod/20231012-1/0dee7242d755caa70c6347b5795ac708.jpg', 'https://phimimg.com/upload/vod/20231012-1/0d02d75893ad2e78491b90b525ed4520.jpg', '<p>Phim kể về đoàn người của Bàn Sơn đạo nhân Chu Khước bị đại soái quân phiệt uy hiếp, cùng nhau đi đến cổ mộ Lạc Thiên Hoang thăm dò tình hình. Bích hoạ Nữ Thần Phi Thiên trong cổ mộ, thực chất là mê cốt hương, nhiễu loạn tâm trí, thời khắc nguy nan gặp đệ tử Bàn Sơn Môn Gia Cát Huyền, mới có thể đánh bại quái vật, vì thế mà Chu Khước và Gia Cát Huyền mới nhận ra nhau. Không ngờ đường đến cổ mộ nguy hiểm đầy rẫy, đám người Chu Khước liên tục tháo chạy, đây là một cuộc so tài giữa thiện và ác, một sự lựa chọn giữa đạo nghĩa và phản bội.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Eddy Ko","avatar":""},{"name":"Guo Jianuo","avatar":""},{"name":"Li Ruoxi","avatar":""},{"name":"Shuangli Zhang","avatar":""},{"name":"Zhonghua He","avatar":""},{"name":"Wang Shengli","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324258);
