INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thanh-thien-thu-vien-quy-su', 'Bao Thanh Thiên : Thư Viện Quỷ Sự', 'Judge Bao : Academy Intrigue', 'https://phimimg.com/upload/vod/20231012-1/d71ed8a22925f86d3a1949124dd0a9b3.jpg', 'https://phimimg.com/upload/vod/20231012-1/472831b0965d352dd7f91bb76329a8e2.jpg', '<p>Kỳ thi cung điện sắp diễn ra nhưng Học viện Yingtian lại nghe tin một học giả đã bị &quot;Dama giết&quot; Sau khi nhận được một lá thư lạ từ người thầy của mình, Bao Chửng lên đường đến học viện để tìm hiểu. Tuy nhiên, học viện này không đơn giản như vẻ ngoài của nó, hiệu trưởng mất tích, các học giả lần lượt chết, và toàn bộ học viện bị bao phủ trong một bầu không khí kỳ lạ. Để tìm người thầy của mình và ngăn chặn hành động giết người của Yama Luo, Bao Zheng quyết tâm xử tử việc này, điều tra rõ ràng. Khi sự thật đến gần, các manh mối dần đan xen, Bao Chửng phát hiện ra rằng có một âm mưu lớn hơn ẩn giấu phía trên triều đình...</p>', 'Full', 1, 'single', 'completed', 13, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Matthew Ko","avatar":""},{"name":"Gu Landi","avatar":""},{"name":"Yang Shiqian","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Chen Xuewei","avatar":""},{"name":"Li Xiaohong","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
