INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-lua', 'Bão Lửa', 'Firestorm', 'https://phimimg.com/upload/vod/20231006-1/6efe7f01baea750fcde5e0bc01e475f3.jpg', 'https://phimimg.com/upload/vod/20231006-1/21c9de9f6f1f20d83e82eb872622abdc.jpg', '<p>Vệ Phong ngồi tù vì gây tai nạn giao thông. Sau khi thời gian thụ 
án kết thúc, anh biết được chị gái đã gom hết tiền bồi thường để giải 
cứu anh, nhưng lại sa vào lời mời mọc của bọn lừa đảo qua đường dây điện
 thoại, rồi lại tự kết liễu mình vì đã biển thủ công quỹ. Với mục tiêu 
tìm hiểu nguyên nhân cái chết của chị gái, Vệ Phong sử dụng kỹ năng lái 
xe tuyệt vời của mình, thông qua cuộc đua với tay phụ tá của băng nhóm 
tội phạm - Vĩ Thiểu, anh thành công tiếp cận băng nhóm tội phạm. Để cuối
 cùng thu hút được tên cầm đầu băng nhóm tội phạm là anh Ba, anh phải tự
 làm tổn thương đồng đội và chịu đựng nhục nhã để tiếp cận băng nhóm tội
 phạm. Cùng với sự hỗ trợ của đồng đội Tiểu Bằng, anh đã thu thập được 
bằng chứng tội phạm của băng nhóm. Khi vụ việc bị phát hiện, Vĩ Thiểu đã
 chết vì tai nạn xe hơi trong quá trình trốn chạy,anh Ba muốn trả thù 
cho Vĩ Thiểu, và đã có cuộc đối đầu sinh tử với Vệ Phong. Kịch tính càng
 cao khi cảnh sát xuất hiện kịp thời và bắt giữ anh Ba, cuối cùng, băng 
nhóm tội phạm đã bị diệt sạch dưới sự truy nã của cảnh sát.</p><p><br/></p><p><br/></p>', 'Full', 1, 'single', 'completed', 27, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xing Yu","avatar":""},{"name":"Peng Tianying","avatar":""},{"name":"Chen Ran","avatar":""},{"name":"John Wu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324258);
