INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-dai-phan-3', 'Anh Đại (Phần 3)', 'Top Boy (Season 3)', 'https://phimimg.com/upload/vod/20231004-1/a3958a984e21511c9cbf70f22395e472.jpg', 'https://phimimg.com/upload/vod/20231004-1/0845eb3b4945bbf53a889420eb0695b9.jpg', '<p>Sully đứng ra nhận trách nhiệm, buộc Dushane phải rút tiền. Nhưng một mệnh lệnh mới lại kéo theo những thách thức, mối đe dọa và hậu quả mới.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 18, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ashley Walters","avatar":""},{"name":"Kane Robinson","avatar":""},{"name":"Micheal Ward","avatar":""},{"name":"Simbiatu Ajikawo","avatar":""},{"name":"Shone Romulus","avatar":""},{"name":"Jasmine Jobson","avatar":""},{"name":"Lisa Dwan","avatar":""},{"name":"Kadeem Ramsay","avatar":""},{"name":"Hope Ikpoku Jr.","avatar":""},{"name":"Araloyin Oshunremi","avatar":""},{"name":"David Omoregie","avatar":""},{"name":"Keiyon Cook","avatar":""},{"name":"Jolade Obasola","avatar":""},{"name":"NoLay","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324258);
