INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-lanh-phan-2', 'Điểm Lành (Phần 2)', 'Good Omens (Season 2)', 'https://phimimg.com/upload/vod/20231004-1/6ecbb5ca3d9c689769b8268051e237a7.jpg', 'https://phimimg.com/upload/vod/20231004-1/0eae21e6479b029028d73e3c615de735.jpg', '<p>Một tổng lãnh thiên thần khỏa thân xuất hiện trước cửa hiệu sách của thiên thần nổi loạn Aziraphale, không nhớ mình là ai hay làm cách nào mà mình đến được đó, và cuộc sống của Aziraphale và con quỷ đã nghỉ hưu Crowley trở nên vô cùng phức tạp. Thiên đường và Địa ngục đều tuyệt vọng tìm kiếm kẻ chạy trốn. Khi Crowley và Aziraphale cố gắng hàn gắn mối tình lãng mạn của con người, mọi thứ ngày càng trở nên không an toàn đối với họ, trong quá khứ và hiện tại.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 21, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Sheen","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Nina Sosanya","avatar":""},{"name":"Maggie Service","avatar":""},{"name":"Shelley Conn","avatar":""},{"name":"Doon Mackichan","avatar":""},{"name":"Quelin Sepulveda","avatar":""},{"name":"Liz Carr","avatar":""},{"name":"Gloria Obianyo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324258);
