INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tay-ma-thuat', 'Bàn Tay Ma Thuật', 'Behind Your Touch', 'https://phimimg.com/upload/vod/20230929-1/6cc768557480a5da7cc7a7e84ac190ad.jpg', 'https://phimimg.com/upload/vod/20230929-1/75c5a1e2d9c8b760dd9e314683f7a11a.jpg', '<p>Một bác sĩ thú y có năng lực ngoại cảm và một thanh tra hợp sức phá các vụ án ở thị trấn nhỏ. Nhưng kỹ năng của họ bị thử thách khi lật mở bí ẩn rùng rợn về tên sát nhân hàng loạt.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'ongoing', 25, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Ji-min","avatar":""},{"name":"Lee Min-ki","avatar":""},{"name":"Suho","avatar":""},{"name":"Joo Min-kyung","avatar":""},{"name":"Yang Jae-sung","avatar":""},{"name":"Park Sung-yeon","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Jung Yi-rang","avatar":""},{"name":"Jo Min-kook","avatar":""},{"name":"Lee Seung-joon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324258);
