INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-phu-hanh-dong-2-diep-huyet', 'Chiến Phủ Hành Động 2: Điệp Huyết', 'Bloody Border 2', 'https://phimimg.com/upload/vod/20230930-1/97d70283056f79c6a87a14701ea38a0b.jpg', 'https://phimimg.com/upload/vod/20230930-1/2cdf952a768edfadb1077a6115aa2e9a.jpg', '<p>Một vụ buôn bán ma túy ở thị trấn biên giới thành phố Tân Nam nằm 
dưới sự giám sát bí mật của cảnh sát, một vụ tai nạn đã làm mất đi bằng 
chứng quan trọng nhất trong vụ án, và cảnh sát chìm bắt đầu tìm kiếm. A 
Bu người vừa mới ra tù và chuẩn bị chào đón cuộc sống mới của mình, bất 
ngờ trở thành mục tiêu chỉ trích của công chúng.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dai Xiangyu","avatar":""},{"name":"Zheng Zihao","avatar":""},{"name":"Tian Lu","avatar":""},{"name":"Qiao Yaona","avatar":""},{"name":"Wu Long","avatar":""},{"name":"Dai Haotian","avatar":""},{"name":"Zhao Zhonghua","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324258);
