INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-mon-don-giap-2', 'Kỳ Môn Độn Giáp 2', 'Fantasy Magician 2', 'https://phimimg.com/upload/vod/20230929-1/949cd828cff4876fbc32536e9ac1f670.jpg', 'https://phimimg.com/upload/vod/20230929-1/67f0395ff3caa764f6c1895010965ba8.jpg', '<p>Một sơn tặc đã vô tình tham gia vào cuộc đấu tranh giữa Vụ Ấn Môn 
và quái vật Thiên Tà, sau bao gian khổ đấu tranh, hắn hiểu được giá trị 
của tinh thần sẵn sàng hy sinh để bảo vệ thế giới, cuối cùng hắn đã dẹp 
bỏ mọi thứ trên đời và tham gia bí mật bảo vệ nhân gian</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Xiaochen","avatar":""},{"name":"Liu Yase","avatar":""},{"name":"Liu Xiaoqing","avatar":""},{"name":"Jiang Lie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324258);
