INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-mon-don-thuat-2', 'Kỳ Môn Độn Thuật 2', 'Thousand Faces of Qi Men', 'https://phimimg.com/upload/vod/20230929-1/3bde0287ab6b5e878925533c938e9884.jpg', 'https://phimimg.com/upload/vod/20230929-1/20a143e02ba79972917b9f48eeed6064.jpg', '<p>Vào thời Thiên triều, sứ thần Đông Doanh mê hoặc hoàng đế, mưu đồ
 thả yêu thần đã bị phong ấn hàng nghìn năm Si Vưu, để gây họa cho nhân 
gian. Các kỳ môn giáo phái đã bao vây đàn áp để bảo vệ phong ấn. Trưởng 
lão Đông Quách phiêu bạt phố thị, tình cờ gặp Liễu Tử Mặc trời sinh tài 
năng, ngỏ ý định nhận anh làm đồ đệ của mình. Dưới sự thắt chặt truy 
đuổi của tặc tử Đông Doanh, nhóm người Lưu Tử Mặc đã nhiều lần chống cự,
 Đông Quách đã hy sinh thân mình để bảo vệ Lưu Tử Mặc rời đi an toàn, 
cũng như giao cho cậu đồng tỳ mở phong ấn. Bị buộc phải gánh vác trọng 
trách nặng nề, Lưu Tử Mặc bắt đầu hành trình tu luyện, đồng thời rơi vào
 một tình trắc trở. Yêu cơ Đông Doanh mê hoặc Nguyên Huệ Tử nhân cơ hội 
thả Si Vưu, thiên địa biến sắc, phong ba quật khởi, một trận tử chiến đã
 sẵn sàng bùng nổ.<br/></p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ashin Shu","avatar":""},{"name":"Zhu Moyan","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Zhu Yuan","avatar":""},{"name":"Chen Youjun","avatar":""},{"name":"Chen Guoliang","avatar":""},{"name":"Chen Jie","avatar":""},{"name":"Liu Sasa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324258);
