INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-canh-cuong-hoa-1', 'Lạt Cảnh Cuồng Hoa 1', 'Spicy Police Flower 1', 'https://phimimg.com/upload/vod/20230929-1/b658266b156f9d2538b849252c436c09.jpg', 'https://phimimg.com/upload/vod/20230929-1/65463f14431aea195cd18544d6e9516d.jpg', '<p>Bộ phim kể rằng để bắt được trùm ma túy Triệu Văn Cửu cảnh sát đã 
sắp xếp cho Đường Thi Vũ, một thành viên cảnh sát đặc biệt, tiếp cận em 
gái của Triệu Văn Cửu, Nhã Nhã, vì vậy khi gia nhập băng đảng ma túy với
 tư cách là một đặc vụ chìm. Trong khoảng thời gian này, kẻ thù của 
Triệu Văn Cửu, trùm ma túy lớn Trần Gia Hoa , đã thâm nhập vào Trung 
Quốc để trả thù, Đường Thi Vũ xử lý cả hai bên, một mặt thu thập bằng 
chứng, một mặt liên lạc với Hoa Tửu, cấp dưới của Triệu Văn Cửu, sau khi
 trải qua hàng loạt khúc mắc và đến lượt, Hoa Tửu bắt đầu tin tưởng 
Đường Thi Vũ, với sự giúp đỡ của Hoa Tửu, đã khéo léo truyền đi mật tín 
và thành công quét sạch toàn bộ tội phạm. Câu chuyện thể hiện rằng, là 
người công an nhân dân, chúng ta không những phải phân biệt được thiện 
ác, trừng trị ác bá thiện mà còn phải dũng cảm xông pha cứu giúp nhân 
dân khi tính mạng của họ gặp nguy hiểm. Là một phụ nữ, Đường Thi Vũ cũng
 thể hiện trí thông minh phi thường và khả năng biến nguy thành món hời 
khi đối mặt với nguy hiểm, không thua kém gì các thành viên nam, cô cũng
 lãnh đạo đội cảnh sát đặc nhiệm nữ của riêng mình, hợp tác ăn ý với 
nhau , và xử lý chúng một cách nhanh chóng và chính xác, thể hiện được 
tinh thần thép và năng lực nghiệp vụ của mình!</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Ran","avatar":""},{"name":"Yan Jiaying","avatar":""},{"name":"Jing Zhao","avatar":""},{"name":"Hong Shuang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324258);
