INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-thu-dong-bac', 'Mãnh Thú Đông Bắc', 'Northeast Beast', 'https://phimimg.com/upload/vod/20230929-1/5bae875725f6560e3d5bb5bff2206aa9.jpg', 'https://phimimg.com/upload/vod/20230929-1/45cfc1e46be09b7e343140f2229ceedf.jpg', '<p><span class="key"></span>Bộ phim kể về câu chuyện của Tôn Đắc Hữu,
 giám đốc cũ của vườn thú, người khăng khăng vận hành vườn thú bằng 
nhiều cách kỳ lạ dưới áp lực của thời đại thay đổi và những khó khăn nội
 bộ. Kiên trì vận hành sở thú thông qua nhiều phương tiện tuyệt vời khác
 nhau, câu chuyện thông qua việc thiết lập mối quan hệ giữa cha và con 
trai, chân thực cho thấy các vấn đề xã hội như sự già hóa nghiêm trọng 
của vùng Đông Bắc và sự mất mát của những người trẻ tuổi. Qua việc bàn 
đến lợi ích kinh tế và lợi ích tinh thần thể hiện giá trị hòa hợp, thống
 nhất trong xã hội ngày nay. Trong câu chuyện, Tôn Đắc Hữu và những 
người khác là những người nhỏ bé bình thường, nhưng các nhân vật mặc dù 
bình thường nhưng lại chứa đựng những giá trị phi thường và năng lượng 
tích cực, tạo hình của con trai ông Tôn Tiểu Hổ giới thiệu góc nhìn của 
những người trẻ tuổi. Tôn Tiểu Hổ tìm lại được lòng mong mỏi quay về cố 
hương hương, để khán giả cảm nhận được sự dũng cảm và quyết tâm vượt qua
 bối rối của những người trẻ tuổi, điều này phản ánh những chỉ dẫn tinh 
thần của &quot;Dự án Ngỗng hoang trở về&quot; do đất nước thực hiện. Bằng cách thể
 hiện sự cải cách của sở thú, nó cho thấy tinh thần chiến đấu của người 
dân ở Đông Bắc Trung Quốc, những người không bao giờ từ bỏ hoặc bỏ cuộc.
 Chỉ có sự phát triển hài hòa của con người và gia đình mới có thể tạo 
ra một cuộc sống tốt đẹp hơn.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wen Song","avatar":""},{"name":"Cui Zhijia","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Xia Zitong","avatar":""},{"name":"Zhang Zidong","avatar":""},{"name":"Du Jianqiao","avatar":""},{"name":"Haoyu Yang","avatar":""},{"name":"Kou Zhenhai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324258);
