INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-thon-lu-diem', 'Sơn Thôn Lữ Điếm', 'The Haunting 3', 'https://phimimg.com/upload/vod/20230929-1/d7df3c46ad203a90f9f75e8fe1dc305f.jpg', 'https://phimimg.com/upload/vod/20230929-1/75e4eb14f8262b71616944a1d401b5a0.jpg', '<p><span class="key"></span>Ngạ quỷ là một trong lục đạo trong Phật 
ngữ, người nào khi còn sống làm điều ác sẽ vào cõi ngạ quỷ, sau khi chết
 sẽ bị hành hạ trong địa ngục. Nhiều năm trước, có một vị sư phụ đến một
 ngôi làng cằn cỗi để ngủ qua đêm, dân làng tình cờ phát hiện ra vị sư 
phụ đang làm lễ hiến tế và phục sinh trên xác vợ mình, dân làng sợ hãi 
đã thiêu sống vợ của vị sư phụ. Trong nỗi kinh hoàng, quá tức giận, anh 
ta đã thả ma đói. Từ đó dân làng không còn ăn được nữa nên chém giết lẫn
 nhau. Người ta nói rằng một người trở thành ma đói sẽ không thể sống 
mãi mãi trừ khi anh ta bắt được vật tế thần ... Vài năm sau, ngôi nhà ma
 ám nhận được một đơn đặt hàng lớn bí ẩn, và một nhóm họ lái xe đến ngôi
 làng bí ẩn năm đó. Nhưng chỉ thấy một khách sạn bỏ hoang, và khách sạn 
trong ngôi làng hoang vắng này thường xuyên xảy ra những sự cố kỳ lạ, 
hết vụ mất tích này đến vụ mất tích khác...</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiang Yu","avatar":""},{"name":"Wang Yanxin","avatar":""},{"name":"Chunqing Awei","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Wang Shuangbao","avatar":""},{"name":"Li Mengmeng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324258);
