INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-linh-tran-thien-quan', 'Tần Lĩnh Trấn Thiên Quan', 'The Sky Coffin in Qinling Town', 'https://phimimg.com/upload/vod/20230929-1/75e9a86ec12d256deb33265116366a47.jpg', 'https://phimimg.com/upload/vod/20230929-1/9a6b662550190ac527eb2bc214cbeee1.jpg', '<p>Những năm đầu thời kỳ Dân Quốc, một khối thiên thạch rơi từ trên 
trời xuống, đáp trúng vùng núi Tần Lĩnh, tình cờ khai phá được một mộ cổ
 bí ẩn. Thiên hạ truyền tai trong mộ cất giữ những kho báu có giá trị. 
Ấy cũng là lúc Quân Phiệt tranh quyền, vì muốn thâu tóm khó báu sung 
quân phí, Dương Tư lệnh ngay lập tức sai người phong tỏa hiện trường. 
Thời kỳ này, có bao kẻ hèn bán nước cầu vinh, cũng không thiếu bậc anh 
tài hy sinh cứu quốc. Đệ tử Mã Cửu Xuyên của môn Thôi Hiển Linh chính là
 một trong số anh tài thuở ấy. Dương Tư lệnh, Tần Thiên, dẫn theo đám 
tay sai xông vào nhà của Thôi Hiển Linh, ép buộc Mã Cửu Xuyên dẫn đường 
quật mộ. Khi Mã Cửu Xuyên và đồng đội đến gần hố sâu trên Tần Lĩnh, một 
đội ngũ khác cũng đến đấy cùng một lúc- đó là quân Nhật do Eguchi Taku 
dẫn đầu. Vì bảo tàng trong mộ, ai nấy cũng ẩn giấu ý đồ trong lòng. Sau 
khi trải qua những hiện tượng kỳ quái và nguy hiểm chết người trong mộ, 
cuối cùng mọi người đã thấy được kho báu mà họ ao ước, sự xấu xa của các
 Quân Phiệt và Quân Nhật đã được tiết lộ vào lúc này...</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Gang","avatar":""},{"name":"Yucheng Cao","avatar":""},{"name":"Zhang Bonan","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Lou Yunfei","avatar":""},{"name":"Liu Sasa","avatar":""},{"name":"Kai Shen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324258);
