INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-ban-tia-am-sat', 'Vua Bắn Tỉa: Ám Sát', 'King of Snipers', 'https://phimimg.com/upload/vod/20230929-1/555eb380337c85bcdeb82ffc0f51faf0.jpg', 'https://phimimg.com/upload/vod/20230929-1/bd2df9f73bdc0481de8cd887bcb7fd3c.jpg', '<p><span class="key"></span>Nữ xạ thủ tài năng Anna buộc phải nhận 
nhiệm vụ ám sát, trong quá trình thực hiện nhiệm vụ, dần giác ngộ để trở
 thành một chiến binh chính nghĩa của lòng tốt và tình yêu thương, 
Artest, một đặc vụ quân sự, đã cùng cô đứng lên và bảo vệ công lý trước 
những tên trùm ma túy đang đàn áp người dân. Cả hai đã hợp tác để ngăn 
chặn việc thông qua luật hợp pháp hóa việc trồng và buôn bán ma túy ở 
Libiwala, đồng thời phát động trận chiến sinh tử với trùm ma túy phản 
diện Roger, cuối cùng đập tan âm mưu của kẻ ác, bảo vệ người dân khỏi ma
 túy, cứu lấy đất nước.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Xing","avatar":""},{"name":"Henry Prince Mak","avatar":""},{"name":"Li Donghe","avatar":""},{"name":"Guo Muhan","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Du Kang","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Rui Xiu","avatar":""},{"name":"Zhang Bohao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324258);
