INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-tam-ke-bat-coc', 'Lương Tâm Kẻ Bắt Cóc', 'The Kidnapping Day', 'https://phimimg.com/upload/vod/20230929-1/a1a1e31fb5e81597f4bdae6e14b06400.jpg', 'https://phimimg.com/upload/vod/20230929-1/0a68b948c6553b6bc825cb24ad9afd37.jpg', '<p>The Kidnapping Day là một bộ phim đầy kịch tính kể về cuộc sống đầy bi kịch của Kim Myung-Joon (Yoon Kye-Sang), một người đàn ông nghèo nhưng trái tim ấm áp.Myung-Joon đang đối mặt với cuộc khủng hoảng tài chính khi con gái của anh, mắc một căn bệnh nặng nề, cần phẫu thuật cấp cứu. Trong lúc khó khăn như vậy, người vợ cũ của Myung-Joon, người đã bỏ anh và con gái từ lâu, xuất hiện và đề nghị một kế hoạch táo bạo. Cô đề xuất Myung-Joon bắt cóc Choi Ro-Hee, một cô bé 11 tuổi và con gái của một gia đình giàu có, để đổi lấy tiền chuộc đủ để cứu sống con gái anh.</p>', 'Tập 6', 12, 'series', 'ongoing', 27, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoon Kye-sang","avatar":""},{"name":"Jeon Yu-na","avatar":""},{"name":"Park Sung-hoon","avatar":""},{"name":"Kim Shin-rock","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Seo Jae-hee","avatar":""},{"name":"Kang Yeong-seok","avatar":""},{"name":"Choi Eun-woo","avatar":""},{"name":"Jeon Kwang-jin","avatar":""},{"name":"Go Ha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324258);
