INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dat-giang-ho', 'Đất Giang Hồ', 'Mob Land', 'https://phimimg.com/upload/vod/20230928-1/4afe74d5f09123b6a4b4571aec4f5801.jpg', 'https://phimimg.com/upload/vod/20230928-1/6ac7a1e18929d49c921154d9f85f8668.jpg', '<p>Một cảnh sát trưởng cố gắng giữ hòa bình khi một người đàn ông tuyệt vọng của gia đình cùng với anh rể của mình cướp một nhà máy thuốc một cách thô bạo, báo động cho người thi hành án của mafia New Orleans.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"John Travolta","avatar":""},{"name":"Shiloh Fernandez","avatar":""},{"name":"Stephen Dorff","avatar":""},{"name":"Ashley Benson","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Timothy V. Murphy","avatar":""},{"name":"Emily Tremaine","avatar":""},{"name":"Robert Miano","avatar":""},{"name":"Tommy G. Kendrick","avatar":""},{"name":"Jesse Sharp","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324258);
