INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scoobydoo-and-krypto-too', 'Scooby-Doo! And Krypto, Too!', 'Scooby-Doo! And Krypto, Too!', 'https://phimimg.com/upload/vod/20230926-1/0cc55f8eeeeb910c1d90c2919c552dd9.jpg', 'https://phimimg.com/upload/vod/20230926-1/0139026720ef07a0f1aae085f2e7803a.jpg', '<p>Khi Justice League mất tích và những kẻ phản diện tràn ngập Metropolis, chỉ có một đội có thể giải quyết bí ẩn này: Scooby-Doo và băng đảng! Nhưng chờ đã, có một chú chó mới trong thị trấn – Krypto – Siêu nhân của Siêu nhân với Siêu năng lực. Mystery Inc. sẽ cần mọi sự trợ giúp có thể khi các bóng ma đe dọa trụ sở của Justice League.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frank Welker","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Kate Micucci","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Victoria Grace","avatar":""},{"name":"Charles Halford","avatar":""},{"name":"Nolan North","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Fred Tatasciore","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324258);
