INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-giang-hong', 'Mãn Giang Hồng', 'Full River Red', 'https://phimimg.com/upload/vod/20230925-1/c5f217ef89f4ce6fb6cde16bcea81d0b.jpg', 'https://phimimg.com/upload/vod/20230925-1/56fa1575df93e511691017a8d0db339e.jpg', '<p>Mãn Giang Hồng - Full River Red lấy bối cảnh thời Thiệu Hưng, nhà Nam Tống (Trung Quốc), bốn năm sau khi Tướng quân Nhạc Phi qua đời. Vào đêm trước cuộc đàm phán dẫn đầu bởi Tể tướng Tần Cối với nhà Tấn, sứ giả của nước này bị phát hiện chết tại dinh thự của ông ta, và bức thư bí mật mang theo đã biến mất. Người lính Trương Đại và phó chỉ huy quân đội Tôn Quân tình cờ bị cuốn vào âm mưu to lớn này và được lệnh cho cả hai phải tìm ra kẻ giết người trong vòng một giờ.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shen Teng","avatar":""},{"name":"Jackson Yee","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Lei Jiayin","avatar":""},{"name":"Yunpeng Yue","avatar":""},{"name":"Wang Jiayi","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Yu Ailei","avatar":""},{"name":"Guo Jingfei","avatar":""},{"name":"Oho Ou","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
