INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-can-x', 'Nghi Can X', 'Jaane Jaan', 'https://phimimg.com/upload/vod/20230925-1/bd6a41ce46f0a5b0352a0154fd1a2b35.jpg', 'https://phimimg.com/upload/vod/20230925-1/a56a4c7c94950162462f4acf5c618a3f.jpg', '<p>Khi một bà mẹ đơn thân, cô con gái tuổi teen của mình vướng vào một tội ác chết người, tìm thấy một đồng minh bất ngờ ở người hàng xóm của họ, một giáo viên dạy toán giản dị, lém lỉnh nhưng thiên tài đến giúp đỡ, trong khi một cảnh sát ngoan cường điều tra vụ án.</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Kareena Kapoor Khan","avatar":""},{"name":"Jaideep Ahlawat","avatar":""},{"name":"Vijay Varma","avatar":""},{"name":"Naisha Khanna","avatar":""},{"name":"Saurabh Sachdeva","avatar":""},{"name":"Karma Takapa","avatar":""},{"name":"Lin Laishram","avatar":""},{"name":"Suhita Thatte","avatar":""},{"name":"Uditi Singh","avatar":""},{"name":"Ujjwal Chopra","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324258);
