INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-doan-sieu-anh-hung', 'Quân Đoàn Siêu Anh Hùng', 'Legion of Super-Heroes', 'https://phimimg.com/upload/vod/20230923-1/f16a0b4abbfb4478ade09c4174ea1505.jpg', 'https://phimimg.com/upload/vod/20230923-1/da72c41fdce392a7084a7830b1734b74.jpg', '<p>Kara, đau khổ vì mất đi Krypton, đấu tranh để thích nghi với cuộc sống mới trên Trái đất. Superman chính là cố vấn cho cô. Trong khi đó, cô phải đối đầu với một nhóm bí ẩn có tên là Dark Circle đang tìm kiếm một vũ khí mạnh mẽ được cất giữ trong hầm của Học viện.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meg Donnelly","avatar":""},{"name":"Harry Shum Jr.","avatar":""},{"name":"Darren Criss","avatar":""},{"name":"Jensen Ackles","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Cynthia Hamidi","avatar":""},{"name":"Yuri Lowenthal","avatar":""},{"name":"Gideon Adlon","avatar":""},{"name":"Ely Henry","avatar":""},{"name":"Darin De Paul","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324258);
