INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dixie-be-bong', 'Dixie Bé Bỏng', 'Little Dixie', 'https://phimimg.com/upload/vod/20230923-1/36c156ba6cff85c85c3643a0c7e4543f.jpg', 'https://phimimg.com/upload/vod/20230923-1/1536534ad76c819cbc8b000413fd85ba.jpg', '<p>Đặc vụ của Lực lượng đặc biệt trước đây, Doc Alexander được yêu cầu môi giới một thỏa thuận đình chiến với tập đoàn ma túy Mexico một cách bí mật. Khi Thống đốc bang Oklahoma Richard Jeffs ăn mừng vụ hành quyết một thành viên cartel cấp cao trên TV, Tham mưu trưởng và Bác sĩ đã thông báo cho ông ta về hòa bình vừa kết thúc. Nhưng đã quá muộn, vì Cuco, kẻ cầm đầu băng đảng, đã nhắm mục tiêu trả thù Dixie, con gái của Doc.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frank Grillo","avatar":""},{"name":"Eric Dane","avatar":""},{"name":"Annabeth Gish","avatar":""},{"name":"Mercedes Mason","avatar":""},{"name":"Peter Greene","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Thomas Dekker","avatar":""},{"name":"Maurice Compte","avatar":""},{"name":"Sufe Bradshaw","avatar":""},{"name":"Luis Da Silva Jr.","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324258);
