INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-go-o-can-nha-go', 'Tiếng Gõ Ở Căn Nhà Gỗ', 'Knock at the Cabin', 'https://phimimg.com/upload/vod/20230922-1/17f059ddada838de2988b8d50f4b92ee.jpg', 'https://phimimg.com/upload/vod/20230922-1/96ab395b1cf7342829b6a78c06fd1450.jpg', '<p>Trong một kỳ nghỉ, một bé gái và gia đình cô bị bắt làm con tin bởi những kẻ lạ mặt có vũ trang, những kẻ này yêu cầu họ phải đưa ra sự lựa chọn để ngăn chặn ngày tận thế.</p>', 'Full', 1, 'single', 'completed', 22, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dave Bautista","avatar":""},{"name":"Jonathan Groff","avatar":""},{"name":"Ben Aldridge","avatar":""},{"name":"Nikki Amuka-Bird","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Abby Quinn","avatar":""},{"name":"Kristen Cui","avatar":""},{"name":"McKenna Kerrigan","avatar":""},{"name":"Ian Merrill Peakes","avatar":""},{"name":"Denise Nakano","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324258);
