INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hai-dai-ngu', 'Thâm Hải Đại Ngư', 'Monster of The Deep', 'https://phimimg.com/upload/vod/20230922-1/57d4e98dd8a72363bc2cfcf89f0356e9.jpg', 'https://phimimg.com/upload/vod/20230922-1/b01818ebec8047d377f2013bf578c5f6.jpg', '<p>Trương Dương, người đã dành nửa đời sống trên biển sau khi chứng kiến cái chết của vợ mình trong một vụ đắm tàu, đã thề sẽ không bao giờ đặt chân ra biển nữa. Thế nhưng, vào dịp sinh nhật lần thứ 12 của con gái, để thực hiện tâm nguyện của con gái, Trương Dương đã bỏ qua lời khuyên ngăn của bạn bè, vi phạm lời thề và tham gia vào một vụ buôn lậu đường biển, bước chân lên con tàu vượt đại dương trông thoạt nhìn như một căn nhà tù làm bằng sắt. Cùng lúc đó, một tai nạn kinh hoàng đã xảy ra, một con quái vật biển sâu chưa ai từng thấy đã trốn thoát khỏi phòng thí nghiệm trên tàu, dựa vào gen thợ săn bẩm sinh, nó đã bắt đầu một cuộc săn lùng không thương tiếc với những người trên tàu, khiến tất cả mọi người rơi vào một bài kiểm tra sống còn.</p>', 'Full', 1, 'single', 'completed', 23, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Lanpeng","avatar":""},{"name":"Zhang Boyu","avatar":""},{"name":"Li Muyun","avatar":""},{"name":"Fang Xushi","avatar":""},{"name":"Tian Haoning","avatar":""},{"name":"Frank Wong","avatar":""},{"name":"Chen Xianmin","avatar":""},{"name":"Zhu Haiyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324258);
