INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('waltair-veerayya', 'Waltair Veerayya', 'Waltair Veerayya', 'https://phimimg.com/upload/vod/20230922-1/784c4680304be75b61e28b728f4d5ff9.jpg', 'https://phimimg.com/upload/vod/20230922-1/87737330dcbb8e445899ddbcbd1bfef5.jpg', '<p>Một tên buôn lậu khét tiếng Waltair Veerayya được CI Seethapathi thuê, đến Malaysia với nhiệm vụ bề ngoài là bắt cóc một thủ lĩnh mafia ma túy tên là Solomon, kẻ đã trốn thoát khỏi Ấn Độ sau khi tàn phá các đặc vụ RAW và cảnh sát địa phương. Veerayya cố gắng hạ gục Solomon, người được bảo vệ quyết liệt bởi người anh trai trùm băng đảng tàn nhẫn Kaala. Tình thế đảo ngược khi Veerayya tiết lộ rằng anh có quá khứ đầy sóng gió với Kaala và ACP Vikram Sagar, người quyết tâm chấm dứt các hoạt động buôn lậu của mình.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Chiranjeevi","avatar":""},{"name":"Shruti Haasan","avatar":""},{"name":"Ravi Teja","avatar":""},{"name":"Catherine Tresa","avatar":""},{"name":"Bobby Simha","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Rajendra Prasad","avatar":""},{"name":"Vennela Kishore","avatar":""},{"name":"Saptagiri","avatar":""},{"name":"Pradeep Ram Singh Rawat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324258);
