INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-pooh-mau-va-mat', 'Gấu Pooh: Máu và Mật', 'Winnie-the-Pooh: Blood and Honey', 'https://phimimg.com/upload/vod/20230922-1/23d712a00864afec8429a8e0d2563e8e.jpg', 'https://phimimg.com/upload/vod/20230922-1/5a29fc22913c744dac4deda11094dcdc.jpg', '<p><span style="font-family: ">Những ngày phiêu lưu và vui vẻ đã kết thúc, khi Christopher Robin, giờ là một chàng trai trẻ, đã để lại Gấu Pooh và Piglet phía sau cho chúng tự lo liệu. Thời gian trôi qua, cảm thấy tức giận và bị bỏ rơi, cả hai dần trở nên hoang dã và thèm khát thức ăn. Và khi Christopher trở lại cũng là lúc cơn thịnh nộ của những sinh vật này bắt đầu.</span></p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Nikolai Leon","avatar":""},{"name":"Craig David Dowsett","avatar":""},{"name":"Chris Cordell","avatar":""},{"name":"Amber Doig-Thorne","avatar":""},{"name":"Maria Taylor","avatar":""},{"name":"Natasha Rose Mills","avatar":""},{"name":"Natasha Tosini","avatar":""},{"name":"Danielle Ronald","avatar":""},{"name":"May Kelly","avatar":""},{"name":"Paula Coiz","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324258);
