INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-tuyen-luan-hoi', 'Tam Tuyến Luân Hồi', 'The River', 'https://phimimg.com/upload/vod/20230922-1/0bf5218033df74928c73812c9d645956.jpg', 'https://phimimg.com/upload/vod/20230922-1/a322f0745e7697cdd2d926700112da0f.jpg', '<p>Ba Đường Luân Hồi (Tam Tuyến Luân Hồi) - San Xian Lun Hui 2023 kể lại vào thời cổ đại, người quyền quý thường đem báu vật truyền đời cất dưới nước, con cháu cầm theo bằng chứng là được thừa kế. Cất và nhận đều được hoàn thành dưới đáy nước, có thể hiểu đơn giản là ngân hàng dưới nước. Từ xưa đến nay ngân hàng dưới nước sẽ do ba nhà Dịch, Đinh, Khương chưởng quản, đến nay họ vẫn sống ẩn dật trong thành phố và tiếp tục công việc này.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiang Peiyao","avatar":""},{"name":"Zhang Yaqi","avatar":""},{"name":"Xie Mingyu","avatar":""},{"name":"Tao Xu","avatar":""},{"name":"Liang Guorong","avatar":""},{"name":"Wa Er","avatar":""},{"name":"Lu Yu","avatar":""},{"name":"Dong Qianyu","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324258);
