INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-cua-bay-vi-vua', 'Cái Chết Của Bảy Vị Vua', 'The Last Kingdom: Seven Kings Must Die', 'https://phimimg.com/upload/vod/20230922-1/bff41a0634072116ee58c0b17d2273e6.jpg', 'https://phimimg.com/upload/vod/20230922-1/9dd6e236b43e6f7cb81dd19d6d264a7e.jpg', '<p><span style="font-family: ">Sau khi vua Edward qua đời, Uhtred xứ Bebbanburg và các đồng đội phiêu lưu qua một vương quốc bị chia cắt với hi vọng cuối cùng sẽ thống nhất nước Anh.</span></p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Alexander Dreymon","avatar":""},{"name":"Mark Rowley","avatar":""},{"name":"Arnas Fedaravicius","avatar":""},{"name":"Harry Gilby","avatar":""},{"name":"Laurie Davidson","avatar":""},{"name":"Cavan Clerkin","avatar":""},{"name":"James Northcote","avatar":""},{"name":"Elaine Cassidy","avatar":""},{"name":"Pekka Strang","avatar":""},{"name":"Rod Hallett","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324259);
