INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ba-nu', 'Nhà Bà Nữ', 'The House Of No Man', 'https://phimimg.com/upload/vod/20230922-1/d2cfd0e655a35fd296702ab53226061e.jpg', 'https://phimimg.com/upload/vod/20230922-1/8e7ee122a3ca993f858a005ab9b8211d.jpg', '<p><span style="font-family: ">Câu chuyện xoay quanh gia đình bà Nữ gồm ba thế hệ sống cùng nhau trong một ngôi nhà. Bà Nữ một tay cáng đáng mọi sự, nổi tiếng với quán bánh canh cua và cũng khét tiếng với việc kiểm soát cuộc sống của tất cả mọi người, từ con gái đến con rể. Mọi chuyện diễn ra bình thường cho đến khi cô con gái út si mê anh chàng điển trai xuất thân từ một gia đình giàu có. Truyện phim khắc họa mối quan hệ phức tạp, đa chiều xảy ra với các thành viên trong gia đình. Câu tagline (thông điệp) chính &quot;Ai cũng có lỗi, nhưng ai cũng nghĩ mình là... nạn nhân&quot; chứa nhiều ẩn ý về nội dung bộ phim muốn gửi gắm.</span></p>', 'Full', 1, 'single', 'completed', 28, 2023, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Uyển Ân","avatar":""},{"name":"Lý Hạo Mạnh Quỳnh","avatar":""},{"name":"Phương Lan","avatar":""},{"name":"Trấn Thành","avatar":""},{"name":"Lê Giang","avatar":""},{"name":"Ngọc Giàu","avatar":""},{"name":"Lê Dương Bảo Lâm","avatar":""},{"name":"Song Luan","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Việt Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324259);
