INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-bien-mot-bo-phim-ve-michael-j-fox', 'BẤT BIẾN: Một Bộ Phim Về Michael J. Fox', 'STILL: A Michael J. Fox Movie', 'https://phimimg.com/upload/vod/20230922-1/101715159a7c096f05c37456ba4830a4.jpg', 'https://phimimg.com/upload/vod/20230922-1/d96169e32c000b4b933fd1ab93c37d90.jpg', '<p>Một cậu bé thấp bé đến từ căn cứ quân đội Canada trở thành đứa con cưng của văn hóa đại chúng quốc tế trong những năm 1980—chỉ để rồi nhận ra cuộc đời mình bị thay đổi bởi một chẩn đoán đáng kinh ngạc. Điều gì xảy ra khi một người lạc quan không thể chữa khỏi phải đối mặt với một căn bệnh nan y?</p>', 'Full', 1, 'single', 'completed', 25, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael J. Fox","avatar":""},{"name":"Tracy Pollan","avatar":""},{"name":"Sam Fox","avatar":""},{"name":"Aquinnah Fox","avatar":""},{"name":"Schuyler Fox","avatar":""},{"name":"Annabelle Fox","avatar":""},{"name":"Susan Bressman","avatar":""},{"name":"Ryan Orser","avatar":""},{"name":"Siobhan Murphy","avatar":""},{"name":"Danny Irizarry","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324259);
