INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-ky', 'Tri Kỷ', 'Soulmate', 'https://phimimg.com/upload/vod/20230922-1/fb050d1302098fd0432534bc85b7c143.jpg', 'https://phimimg.com/upload/vod/20230922-1/b8f7dd49451b065a137d87af674b88b1.jpg', '<p><span style="font-family: ">Soulmate xoay quanh những thăng trầm trong mối quan hệ và quá trình trưởng thành của Mi So (Kim Da Mi) và Ha Eun (Jeon So Nee), hai người con gái sinh năm 1988 cùng trải qua thời niên thiếu với nhau. Thế giới yên bình của hai người họ bắt đầu có những rạn nứt khi Ha Eun có mối tình đầu với bạn cùng lớp Jin Woo (Byeon Woo Seok). Cả hai dần xa cách nhau khi Mi So lên thành phố để theo đuổi cuộc sống phiêu lưu với một tâm hồn tự do, còn Ha Eun ở lại quê nhà mưu cầu một cuộc sống ổn định.</span></p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Da-mi","avatar":""},{"name":"Jeon So-nee","avatar":""},{"name":"Byeon Woo-seok","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Park Choong-seon","avatar":""},{"name":"Kim Soo-hyung","avatar":""},{"name":"Ryu Ji-an","avatar":""},{"name":"Heo Ji-na","avatar":""},{"name":"Kang Mal-geum","avatar":""},{"name":"Nam Yoon-su","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324259);
