INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('peter-pan-wendy', 'Peter Pan & Wendy', 'Peter Pan & Wendy', 'https://phimimg.com/upload/vod/20230922-1/4ca5c4e2a642cb24de417b47a54b9b3a.jpg', 'https://phimimg.com/upload/vod/20230922-1/3a6e8962677c3e75d533af20f84f61fc.jpg', '<p>Wendy Darling, một cô gái trẻ sợ phải rời xa ngôi nhà thời thơ ấu của mình, gặp Peter Pan, một cậu bé không chịu lớn. Cùng với các anh trai của mình và một nàng tiên nhỏ bé, Tinker Bell, cô du hành cùng Peter đến thế giới huyền diệu Neverland. Ở đó, cô gặp thuyền trưởng cướp biển độc ác, thuyền trưởng Hook và dấn thân vào một cuộc phiêu lưu ly kỳ sẽ thay đổi cuộc đời cô mãi mãi.</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexander Molony","avatar":""},{"name":"Ever Anderson","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Alyssa Wapanatâhk","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Joshua Blue Pickering","avatar":""},{"name":"Jacobi Jupe","avatar":""},{"name":"Molly Parker","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Yara Shahidi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324259);
