INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-tron-sinh-tu', 'Vòng Tròn Sinh Tử', 'Circle Line', 'https://phimimg.com/upload/vod/20230922-1/93557ee85a989d6040453a78662ccb8f.jpg', 'https://phimimg.com/upload/vod/20230922-1/eaf67c020c69689689f80e7d57b1577f.jpg', '<p>Bị mắc kẹt trong hệ thống đường hầm tàu điện ngầm, quyết tâm bảo vệ con trai của người mẹ đơn thân bị thử thách đến cùng cực khi cả hai đều là số ít người sống sót sau cuộc tấn công của quái vật. Trong khi đó ở phòng điều khiển, các kỹ sư trực chiến đấu hết mình để giải cứu những người sống sót bị mắc kẹt.</p>', 'Full', 1, 'single', 'completed', 16, 2023, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Jesseca Liu","avatar":""},{"name":"Andie Chen","avatar":""},{"name":"Peter Yu","avatar":""},{"name":"Patrick Lee","avatar":""},{"name":"Nathaniel Ng","avatar":""},{"name":"Alan Tan","avatar":""},{"name":"Ashley Seow","avatar":""},{"name":"Johnny Ng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324259);
