INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-do-te-boston', 'Gã Đồ Tể Boston', 'Boston Strangler', 'https://phimimg.com/upload/vod/20230922-1/380d70a442f4e1267f5a3c080ef658c3.jpg', 'https://phimimg.com/upload/vod/20230922-1/9cf19db655437a06f9a78f42417dc54b.jpg', '<p><span style="font-family: ">Bộ phim dựa trên câu chuyện có thật về Gã Đồ Tể Boston - kẻ sát hại 13 phụ nữ chỉ bằng cách siết cổ những năm 1960. Công đầu trong vụ trọng án này phải kể đến nữ phóng viên Loretta McLaughlin và Jean Cole, những người đã thách thức chủ nghĩa phân biệt giới tính để đưa tin về kẻ giết người hàng loạt khét tiếng nhất thành phố.</span></p>', 'Full', 1, 'single', 'completed', 23, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Carrie Coon","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Rory Cochrane","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Peter Gerety","avatar":""},{"name":"Robert John Burke","avatar":""},{"name":"Ryan Winkles","avatar":""},{"name":"Morgan Spector","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324259);
