INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nguoi-duyen-ma-ngoai-truyen', 'Tình Người Duyên Ma: Ngoại Truyện', 'Tid Noi: More Than True Love', 'https://phimimg.com/upload/vod/20230921-1/27ea03d033c012397793392669922fff.jpg', 'https://phimimg.com/upload/vod/20230921-1/51c364b09418ca132640e31e94be1fcb.jpg', '<p><span style="font-family: ">Dựa trên truyền thuyết về nàng Nak, không xuất hiện trong lịch sử - Tid Noi là câu chuyện khai thác về một nhân vật mới trong mối quan hệ giữa Pee Mak và Mae Nak. Khác với suy đoán về một chuyện tình tay ba ngang trái, Tid Noi đơn thuần là anh bạn hàng xóm mang trong mình tình yêu đơn phương thuần khiết dành cho cô gái nhà bên là Nak.</span></p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Patchrapa Chaichua","avatar":""},{"name":"Pongsak Pongsuwan","avatar":""},{"name":"Ananda Everingham","avatar":""},{"name":"Rusameekae Fagerlund","avatar":""},{"name":"Napapa Tantrakul","avatar":""},{"name":"Chalerm Parnkerd","avatar":""},{"name":"Chaleumpol Tikumpornteerawong","avatar":""},{"name":"Somchai Kemglad","avatar":""},{"name":"Choosak Iamsook","avatar":""},{"name":"Sornsutha Klunmalee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324259);
