INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-tau-ma', 'Trạm Tàu Ma', 'The Ghost Station', 'https://phimimg.com/upload/vod/20230921-1/aad16e87e4db148b578cf458444a6d9d.jpg', 'https://phimimg.com/upload/vod/20230921-1/e096b6d3c96ed105c49ca096bd0b75b8.jpg', '<p><span style="font-family: ">Lời đồn ma ám về nhà ga Oksu ngày càng nhiều khi những vụ án kinh hoàng liên tục xảy ra. Một đường ray cũ kỹ, một chiếc giếng bỏ hoang, những con số gây ám ảnh hay những vết thương kỳ dị trên thi thể người xấu số... Tất cả dẫn đến một bí mật đau lòng bị chôn vùi nhiều năm trước.</span></p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Bo-ra","avatar":""},{"name":"Kim Jae-hyun","avatar":""},{"name":"Shin So-yul","avatar":""},{"name":"Oh Jin-seok","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324259);
