INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-thinh-no-cua-becky', 'Cơn Thịnh Nộ Của Becky', 'The Wrath of Becky', 'https://phimimg.com/upload/vod/20230921-1/a1d55f98be0c197b4850776e54e936f0.jpg', 'https://phimimg.com/upload/vod/20230921-1/c42a8dc6723462e401ae26d6c011f879.jpg', '<p>Hai năm sau khi thoát khỏi cuộc tấn công bạo lực nhằm vào gia đình, Becky, 16 tuổi, cố gắng làm lại cuộc đời dưới sự chăm sóc của một người phụ nữ lớn tuổi - một người đồng hương tên là Elena. Tuy nhiên, khi một nhóm bạo lực được gọi là Noble Men đột nhập vào nhà của họ, tấn công họ và bắt đi chú chó yêu quý của họ, Becky phải quay lại con đường cũ để bảo vệ bản thân và những người thân yêu.</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lulu Wilson","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Denise Burse","avatar":""},{"name":"Jill Larson","avatar":""},{"name":"Michael Sirow","avatar":""},{"name":"Aaron Dalla Villa","avatar":""},{"name":"Matt Angel","avatar":""},{"name":"Courtney Gains","avatar":""},{"name":"Alison Cimmet","avatar":""},{"name":"Derek Gaines","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324259);
