INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-duoi-be-nuoc', 'Quái Vật Dưới Bể Nước', 'The Tank', 'https://phimimg.com/upload/vod/20230921-1/36c735e35491ccd06fa7558c945fed87.jpg', 'https://phimimg.com/upload/vod/20230921-1/129142efadfff263590c4e865f5fc0ce.jpg', '<p><span style="font-family: ">Năm 1978 ở Oregon, Ben và Jules được thừa kế một tài sản ven biển bị bỏ hoang từ người mẹ quá cố của Ben, người chưa bao giờ đề cập đến nó. Ngôi nhà hoang sơ đã được giữ bí mật trong 40 năm và đi kèm với một vịnh nhỏ và bãi biển riêng tuyệt đẹp. Jules tìm kiếm câu trả lời trong khi Ben vô tình đánh thức một sinh vật bảo vệ quyết liệt.</span></p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Luciane Buchanan","avatar":""},{"name":"Matt Whelan","avatar":""},{"name":"Jaya Beach-Robertson","avatar":""},{"name":"Mark Mitchinson","avatar":""},{"name":"Ascia Maybury","avatar":""},{"name":"Holly Shervey","avatar":""},{"name":"Graham Vincent","avatar":""},{"name":"Jack Barry","avatar":""},{"name":"Zara Nausbaum","avatar":""},{"name":"Coco White","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324259);
