INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-tron-khoi-kandahar', 'Chạy Trốn Khỏi Kandahar', 'Kandahar', 'https://phimimg.com/upload/vod/20230921-1/83128b7ed0e9ae2a2b68a198e48cbbc8.jpg', 'https://phimimg.com/upload/vod/20230921-1/dc5ed694842a01ba4033a87f188236a7.jpg', '<p>Sau khi nhiệm vụ của anh ta bị bại lộ, một đặc vụ CIA bí mật bị mắc kẹt sâu trong lãnh thổ thù địch ở Afghanistan phải tìm đường thoát ra, cùng với phiên dịch viên người Afghanistan của anh ta, đến một điểm rút lui ở Kandahar, đồng thời trốn tránh các lực lượng tinh nhuệ của kẻ thù và các điệp viên nước ngoài được giao nhiệm vụ săn lùng họ.</p>', 'Full', 1, 'single', 'completed', 15, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Navid Negahban","avatar":""},{"name":"Travis Fimmel","avatar":""},{"name":"Ali Fazal","avatar":""},{"name":"Bahador Foladi","avatar":""},{"name":"Nina Toussaint-White","avatar":""},{"name":"Mark Arnold","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Hakeem Jomah","avatar":""},{"name":"Tom Rhys Harries","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
