INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('stephen-curry-tai-nang-vuot-dinh-kien', 'Stephen Curry: Tài Năng Vượt Định Kiến', 'Stephen Curry: Underrated', 'https://phimimg.com/upload/vod/20230921-1/e7e23db911ea5a9dfc32f84ba4de3cd1.jpg', 'https://phimimg.com/upload/vod/20230921-1/5546d8af8aa5c22bac17c0732e969c0c.jpg', '<p><span style="font-family: ">Câu chuyện hấp dẫn về sự trưởng thành của Stephen Curry - một trong các cầu thủ giàu ảnh hưởng, năng nổ và gây bất ngờ nhất trong lịch sử bóng rổ - từ một cầu thủ đại học thấp bé đến bốn lần vô địch NBA.</span></p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Curry","avatar":""},{"name":"Bob McKillop","avatar":""},{"name":"Reggie Miller","avatar":""},{"name":"Kevin Durant","avatar":""},{"name":"Ayesha Curry","avatar":""},{"name":"Dell Curry","avatar":""},{"name":"Sonya Curry","avatar":""},{"name":"Draymond Green","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324259);
