INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-kamen-rider', 'Shin Kamen Rider', 'Shin Kamen Rider', 'https://phimimg.com/upload/vod/20230921-1/d7a2cafd67d09b5100d1f8e9604d3395.jpg', 'https://phimimg.com/upload/vod/20230921-1/27355b0da0053cdfb2f6e8cd19dbc7d8.jpg', '<p>Một người đàn ông bị buộc phải nắm giữ quyền lực và bị tước đoạt nhân tính. Một người phụ nữ hoài nghi về hạnh phúc. Takeshi Hongo, một Phép tăng cường do SHOCKER thực hiện và Ruriko Midorkawa, một kẻ nổi loạn của tổ chức, trốn thoát trong khi chiến đấu chống lại bọn sát thủ. Công lý là gì? Cái gì là ác? Liệu bạo lực này có chấm dứt? Bất chấp sức mạnh của mình, Hongo vẫn cố gắng trở thành con người. Cùng với tự do, Ruriko đã lấy lại được trái tim. Họ sẽ chọn con đường nào?</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sosuke Ikematsu","avatar":""},{"name":"Minami Hamabe","avatar":""},{"name":"Tasuku Emoto","avatar":""},{"name":"Mirai Moriyama","avatar":""},{"name":"Nanase Nishino","avatar":""},{"name":"Toru Tezuka","avatar":""},{"name":"Nao Omori","avatar":""},{"name":"Kanata Hongo","avatar":""},{"name":"Masami Nagasawa","avatar":""},{"name":"Tori Matsuzaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324259);
