INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khao-khat-hoan-hao', 'Khao Khát Hoàn Hảo', 'Perfect Addiction', 'https://phimimg.com/upload/vod/20230921-1/2ad33f6226e3bc5b6cfc70e420928809.jpg', 'https://phimimg.com/upload/vod/20230921-1/4795a910b5ce2e811ca8ce7d9b2af689.jpg', '<p>Một nữ huấn luyện viên quyền anh phát hiện ra rằng người bạn trai vô địch võ sĩ lồng của cô đã lừa dối cô với em gái cô và quyết định tìm cách trả thù bằng cách huấn luyện đối thủ không đội trời chung của mình để thách đấu anh ta.</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kiana Madeira","avatar":""},{"name":"Ross Butler","avatar":""},{"name":"Matthew Noszka","avatar":""},{"name":"Bree Winslow","avatar":""},{"name":"Nicholas Duvernay","avatar":""},{"name":"Manu Bennett","avatar":""},{"name":"Ryan Bown","avatar":""},{"name":"Poppy Gilbert","avatar":""},{"name":"Cecilia Diesch","avatar":""},{"name":"Alex Czerwinski","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324259);
