INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-mao-bac-ma', 'Nam Mao Bắc Mã', 'Nan Mao Bei Ma', 'https://phimimg.com/upload/vod/20230921-1/f9e15ae83aa5f9452decb88ae53401b4.jpg', 'https://phimimg.com/upload/vod/20230921-1/79c88b63059f89014f020e7d458c8bf9.jpg', '<p>Trong thời Trung Hoa Dân Quốc, chiến tranh nổ ra. Một vụ giết người kỳ lạ tại ngôi đền trên núi đã phá vỡ sự yên tĩnh của thị trấn. Đoàn lữ hành của thiếu gia thị trưởng và nhóm của anh ta, ngoại trừ thiếu gia, những người còn lại đều chết bất đắc kỳ tử. Người ta đồn đại rộng rãi trong thị trấn rằng vụ giết người là do một nữ ma gây ra, khiến cả thị trấn hoảng sợ. Chú Anh, người phái Mao Sơn trong thị trấn, đã dùng y thuật để trấn áp tình trạng của cậu chủ trẻ, nhưng ông không thể loại bỏ được tận gốc bệnh tình của cậu chủ. Một nhóm pháp sư đã đến thị trấn để trừ tà cho cậu chủ. Tuy nhiên, những điều kỳ lạ thường xuyên xảy ra trong thị trấn...</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ge Shuai","avatar":""},{"name":"Du Zhiguo","avatar":""},{"name":"Yu Jiachuan","avatar":""},{"name":"Lin Ziqing","avatar":""},{"name":"Jie Ma","avatar":""},{"name":"Wang Zezong","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324259);
