INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-kha-chien-bai-atom-eve-tap-dac-biet', 'Bất Khả Chiến Bại: Atom Eve (Tập Đặc Biệt)', 'Invincible: Atom Eve', 'null', 'https://phimimg.com/upload/vod/20230921-1/289ddcc13aad9ec1b97b95002c8858cd.jpg', '<p>Trong tập tiền truyện đặc biệt này, Samantha Eve Wilkins, hay còn gọi là Atom Eve, lớn lên lạc lõng trong chính gia đình của mình. Khi ai đó từ quá khứ bước vào cuộc sống của cô ấy, cô ấy phát hiện ra câu chuyện bi thảm của mình cũng như nguồn gốc và tiềm năng thực sự của sức mạnh của cô ấy.</p>', 'Full', 1, 'hoathinh', 'completed', 27, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Yeun","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Madison Calderon","avatar":""},{"name":"Lauren Cohan","avatar":""},{"name":"Taylor Dearden","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324259);
