INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-la-thuong-de', 'Đạn Là Thượng Đế', 'God Is a Bullet', 'https://phimimg.com/upload/vod/20230921-1/98e3bc4fef27366e53e0153863a9873c.jpg', 'https://phimimg.com/upload/vod/20230921-1/c9dc6e71c9f66f3647726dd503ad6b35.jpg', '<p>Dựa trên sự kiện có thật và tiểu thuyết cùng tên. Phó thám tử Bob Hightower phát hiện vợ cũ của mình bị sát hại và con gái bị một giáo phái bắt cóc. Thất vọng vì các cuộc điều tra chính thức thất bại, anh ta rời bỏ lực lượng và thâm nhập vào giáo phái để truy lùng thủ lĩnh với sự giúp đỡ của Case Hardin, nạn nhân nữ duy nhất trốn thoát của giáo phái.</p>', 'Full', 1, 'single', 'completed', 23, 2023, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Maika Monroe","avatar":""},{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Karl Glusman","avatar":""},{"name":"January Jones","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Paul Johansson","avatar":""},{"name":"David Thornton","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Jonathan Tucker","avatar":""},{"name":"Brendan Sexton III","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324259);
