INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-sau-bi-an', 'Hố Sâu Bí Ẩn', 'Crater', 'https://phimimg.com/upload/vod/20230921-1/477c6239c4884550cb95e93cec18a3a9.jpg', 'https://phimimg.com/upload/vod/20230921-1/db7712357855a64ce198bd8f03ceed03.jpg', '<p>Sau cái chết của cha mình, một cậu bé lớn lên trên khu khai thác mỏ trên mặt trăng thực hiện chuyến đi khám phá một miệng núi lửa huyền thoại, cùng với bốn người bạn thân nhất của mình, trước khi được chuyển vĩnh viễn đến một hành tinh khác.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Isaiah Russell-Bailey","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Billy Barratt","avatar":""},{"name":"Orson Hong","avatar":""},{"name":"Thomas Boyce","avatar":""},{"name":"Kid Cudi","avatar":""},{"name":"Selenis Leyva","avatar":""},{"name":"Hero Hunter","avatar":""},{"name":"Carson Minniear","avatar":""},{"name":"Viviana Chavez","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324259);
