INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngan-le-mot', 'Một Ngàn Lẻ Một', 'A Thousand and One', 'https://phimimg.com/upload/vod/20230921-1/d7e5a8aa2d600951176e7ec0c38563fc.jpg', 'https://phimimg.com/upload/vod/20230921-1/82faafdaa1dcf4efeabd44b19ad8dba6.jpg', '<p>Đấu tranh nhưng không hối lỗi khi sống theo ý mình, Inez đang chuyển từ nơi trú ẩn này sang nơi trú ẩn khác vào giữa những năm 1990 tại Thành phố New York. Với cậu con trai 6 tuổi Terry đang được chăm sóc nuôi dưỡng và không thể rời xa cậu lần nữa, cô bắt cóc cậu để họ có thể cùng nhau xây dựng cuộc sống. Năm tháng trôi qua, gia đình họ ngày càng phát triển và Terry trở thành một thiếu niên thông minh nhưng trầm lặng, nhưng bí mật đã quyết định cuộc sống của họ có nguy cơ phá hủy ngôi nhà mà họ đã xây dựng một cách không tưởng.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Teyana Taylor","avatar":""},{"name":"William Catlett","avatar":""},{"name":"Josiah Cross","avatar":""},{"name":"Aven Courtney","avatar":""},{"name":"Aaron Kingsley Adetola","avatar":""},{"name":"Terri Abney","avatar":""},{"name":"Delissa Reynolds","avatar":""},{"name":"Amelia Workman","avatar":""},{"name":"Adriane Lenox","avatar":""},{"name":"Gavin Schlosser","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
