INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban', 'Bạn', 'Amigos', 'https://phimimg.com/upload/vod/20230920-1/c916b1aaa410b3953d8154db7c7bcfc4.jpg', 'https://phimimg.com/upload/vod/20230920-1/3a68351429fcf25cbe1ebead4a828a2e.jpg', '<p>Siddharth, một chàng trai trẻ điều hành một doanh nghiệp gia đình đã rất ngạc nhiên khi tìm thấy bản sao Manjunath và Michael của mình trên getdopple.com. Sau khi gặp nhau ở Goa, họ đến Hyderabad để giúp Siddarth thu phục Ishika, một cô gái đang tìm siêu nhân làm chồng mình. Nhưng mọi thứ chuyển biến mạnh mẽ khi NIA bắt tay vào bắt Michael, hay còn gọi là Bipin Roy.</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Kalyan Ram","avatar":""},{"name":"Ashika Ranganath","avatar":""},{"name":"Brahmaji","avatar":""},{"name":"Jayaprakash","avatar":""},{"name":"Saptagiri","avatar":""},{"name":"Rajeev Pillai","avatar":""},{"name":"Ravi Prakash","avatar":""},{"name":"Sivannarayana Naripeddi","avatar":""},{"name":"Raghu Karumanchi","avatar":""},{"name":"Chaitanya Krishna","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
