INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('97-phut-song-con', '97 Phút Sống Còn', '97 Minutes', 'https://phimimg.com/upload/vod/20230920-1/c13f4ca831c98697862ed85d8f3b2a62.jpg', 'https://phimimg.com/upload/vod/20230920-1/cca6617e42a22ea9fb99c969d6d3dd72.jpg', '<p><span style="font-family: ">Một chiếc máy bay 767 bị không tặc sẽ rơi chỉ sau 97 phút khi hết nhiên liệu. Chống lại ý chí mạnh mẽ của Phó NSA Toyin, Giám đốc NSA Hawkins chuẩn bị cho chiếc máy bay bị bắn hạ trước khi nó gây ra bất kỳ thiệt hại thảm khốc nào trên mặt đất, để lại số phận của những hành khách vô tội trong tay của Alex, một đặc vụ ngầm của Interpol, người đã nhúng tay vào. trong phòng giam khủng bố.</span></p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"MyAnna Buring","avatar":""},{"name":"Jo Martin","avatar":""},{"name":"Michael Sirow","avatar":""},{"name":"Pavan Grover","avatar":""},{"name":"Anjul Nigam","avatar":""},{"name":"Davor Tomic","avatar":""},{"name":"Slavko Sobin","avatar":""},{"name":"Peter Brooke","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
