INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-uc-den-toi', 'Hồi Ức Đen Tối', 'The Machine', 'https://phimimg.com/upload/vod/20230920-1/efe274ee697b2e8842feac1de3fc9c82.jpg', 'https://phimimg.com/upload/vod/20230920-1/05a22ce7fdc5e47cff86e4af56679d14.jpg', '<p>Phim kể về Bert Kreischer, một diễn viên hài nổi tiếng với biệt danh The Machine. Trong phần biểu diễn đặc trưng của mình, anh ta kể lại trải nghiệm thực sự với các tên trùm mafia Nga trong chuyến du lịch đầy rượu của mình khi còn là sinh viên. Bây giờ, 23 năm sau đó, chuyến đi đó trở thành một cơn ác mộng khi anh và cha mình (do Mark Hamill đóng) bị bắt cóc trở lại Nga bởi bọn mafia để chuộc lỗi cho những gì họ nói rằng Bert đã làm. Cùng nhau, Bert và cha mình phải đi theo dấu vết của bản thân trẻ (do Jimmy Tatro đóng) giữa một cuộc chiến trong một gia đình tội phạm tâm thần, trong khi cố gắng tìm một mặt đất chung trong mối quan hệ thường xuyên gặp rắc rối của họ.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bert Kreischer","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Jimmy Tatro","avatar":""},{"name":"Stephanie Kurtzuba","avatar":""},{"name":"Nikola Đuričko","avatar":""},{"name":"Iva Babić","avatar":""},{"name":"Martyn Ford","avatar":""},{"name":"Robert Maaser","avatar":""},{"name":"Jessica Gabor","avatar":""},{"name":"Rita Bernard-Shaw","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324259);
