INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-quy', 'Mặt Nạ Quỷ', 'The Ghost Within', 'https://phimimg.com/upload/vod/20230920-1/68e48522a1fcd6750c8078a9a7075df0.jpg', 'https://phimimg.com/upload/vod/20230920-1/31b70d3fa38c10f386aef3a5a3602880.jpg', '<p><span style="font-family: ">Bí ẩn về cái chết của em gái Evie 20 năm trước còn bỏ ngỏ, vào lúc 09:09 hằng đêm, hàng loạt cuộc chạm trán kinh hoàng xảy ra. Liệu Margot có biết được sự thật ai là kẻ giết em gái mình?</span></p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michaela Longden","avatar":""},{"name":"Rebecca Phillipson","avatar":""},{"name":"Tom Millen","avatar":""},{"name":"Victor Mellors","avatar":""},{"name":"Simon Davies","avatar":""},{"name":"Sarah Alexandra Marks","avatar":""},{"name":"Honor Davis-Pye","avatar":""},{"name":"Georgina Jane","avatar":""},{"name":"Ivy Deakin","avatar":""},{"name":"Alice Thoma","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324259);
