INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-vong-du-hy-cuoi-cung', 'Tử Vong Du Hý Cuối Cùng', 'The Final Game of Death', 'null', 'https://phimimg.com/upload/vod/20230920-1/a7bfcace669cd4ece217f98e67620aa2.jpg', '<p>Vào ngày 17 tháng 7 năm 2023, Arrow Films đã phát hành một bộ hộp 4K UHD/Blu-ray bao gồm các bộ phim của Lý Tiểu Long tại hãng Golden Harvest. Bộ hộp này bao gồm một tài liệu phim dài 223 phút về quá trình sản xuất bộ phim &quot;Tử Vong Du Hý&quot;. Tài liệu phim bao gồm toàn bộ hai giờ footage được quay cho dự án bởi Lee trước khi ông qua đời, đã được khôi phục từ bản mẫu sau quét. Tài liệu phim cũng bao gồm một tập hợp các đoạn footage, cùng với một phần giới thiệu mới được quay để bù đắp cho các yếu tố cốt truyện mà không bao giờ được quay.</p>', 'Full', 1, 'single', 'completed', 24, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Flower","avatar":""},{"name":"Bruce Lee","avatar":""},{"name":"James Tien Chuen","avatar":""},{"name":"Chieh Yuan","avatar":""},{"name":"Dan Inosanto","avatar":""},{"name":"Ji Han-Jae","avatar":""},{"name":"Kareem Abdul-Jabbar","avatar":""},{"name":"Whang In-sik","avatar":""},{"name":"Billy Chan","avatar":""},{"name":"Lam Ching-Ying","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324259);
