INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-den-vay-ham', 'Bóng Đen Vây Hãm', 'The Blackening', 'https://phimimg.com/upload/vod/20230920-1/bdcaddf634cb1f5d5ba28e43526eddd0.jpg', 'https://phimimg.com/upload/vod/20230920-1/d4e972231c53e552197ece07792d2fe4.jpg', '<p>Phim xoay quanh một nhóm bạn da đen tại Mỹ tái hợp để có một kỳ nghỉ cuối tuần vào dịp lễ Juneteenth. Tuy nhiên, họ nhanh chóng nhận ra mình bị mắc kẹt trong một căn nhà xa xôi với một tên sát nhân tàn ác. Bị buộc phải chơi theo quy tắc của tên sát nhân này, nhóm bạn sớm nhận ra rằng đây không phải là trò chơi đùa vui mà là cuộc sống và cái chết thật sự đang đe dọa.</p>', 'Full', 1, 'single', 'completed', 17, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antoinette Robertson","avatar":""},{"name":"Sinqua Walls","avatar":""},{"name":"Dewayne Perkins","avatar":""},{"name":"X Mayo","avatar":""},{"name":"Melvin Gregg","avatar":""},{"name":"Grace Byers","avatar":""},{"name":"Jermaine Fowler","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Yvonne Orji","avatar":""},{"name":"Jay Pharoah","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324259);
