INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuoc-phim-kinh-hoang', 'Thước Phim Kinh Hoàng', 'Streamer', 'https://phimimg.com/upload/vod/20230920-1/3e9df20598e111221334b4636107ac64.jpg', 'https://phimimg.com/upload/vod/20230920-1/e380d1bd3c8eef699208a72804b81b31.jpg', '<p><span style="font-family: ">Một bộ phim kinh dị Hàn Quốc xoay quanh hành trình khám phá toà nhà bỏ hoang của 5 streamer Momo, Jun, Taku, Jaemin và Dasuel. Nơi đây là trung tâm phúc lợi người khiếm thị Sori có thật tại Hàn Quốc, đã ngừng hoạt động trong thời gian dài với nhiều lời đồn thổi về ma quỷ. 5 streamer đã rủ nhau “lên kèo” livestream tại toà nhà này nhằm tìm hiểu chân tướng đứng sau cái chết của một streamer trước đó, vì họ cho rằng kẻ này chỉ đang dựng chuyện để “câu view”.</span></p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Pu-reum","avatar":""},{"name":"Kwon Min-hyuk","avatar":""},{"name":"Kim Mo-beom","avatar":""},{"name":"Kim Jun-hyung","avatar":""},{"name":"Shim So-young","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324259);
