INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-binh-phuong-lai-tu-dau', 'Yêu Bình Phương Lại Từ Đầu', 'Squared Love All Over Again', 'https://phimimg.com/upload/vod/20230920-1/55be87f9caaf6488770b213bf9715df8.jpg', 'https://phimimg.com/upload/vod/20230920-1/e21f3a73be403a11fef774fcaddf6255.jpg', '<p><span style="font-family: ">Mối quan hệ của một nhà báo nổi tiếng và một giáo viên thực tế bước vào giai đoạn sóng gió khi một công việc xen ngang cuộc sống chung mới của họ.</span></p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Adrianna Chlebicka","avatar":""},{"name":"Mateusz Banasiuk","avatar":""},{"name":"Mirosław Baka","avatar":""},{"name":"Helena Mazur","avatar":""},{"name":"Mikołaj Roznerski","avatar":""},{"name":"Krzysztof Czeczot","avatar":""},{"name":"Monika Krzywkowska","avatar":""},{"name":"Jacek Feliks Knap","avatar":""},{"name":"Tomasz Karolak","avatar":""},{"name":"Ewa Kolasińska-Szramel","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324259);
