INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('somewhere-in-queens', 'Somewhere in Queens', 'Somewhere in Queens', 'https://phimimg.com/upload/vod/20230920-1/3c8fdd3c62d36c00201ba481e0ff0399.jpg', 'https://phimimg.com/upload/vod/20230920-1/bb0c18ec13aff4c6b59eab7c4b765ef4.jpg', '<p>Leo và Angela Russo có một cuộc sống đơn giản, bình dị xung quanh những người hàng xóm lâu đời gốc Ý của họ ở Queens (Hoa Kỳ). Tuy nhiên, khi cậu con trai Matthew tỏ ra vượt trội với bộ môn bóng rổ ở trường và có cơ hội nhận học bổng đại học, Leo đã cố gắng tìm mọi cách để giúp kể cả việc đến gặp bạn gái cũ của Matthew và mong cô bé có thể quay trở lại. giúp con trai mình nhanh chóng thoát khỏi những sự tổn thương và tiếp tục niềm đam mê bóng rổ.</p>', 'Full', 1, 'single', 'completed', 20, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Romano","avatar":""},{"name":"Laurie Metcalf","avatar":""},{"name":"Jacob Ward","avatar":""},{"name":"Sadie Stanley","avatar":""},{"name":"Jennifer Esposito","avatar":""},{"name":"Deirdre Friel","avatar":""},{"name":"Jon Manfrellotti","avatar":""},{"name":"Danny Garcia","avatar":""},{"name":"Erik Griffin","avatar":""},{"name":"June Gable","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
