INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-trang-xanh-hoang-gia', 'Đỏ, Trắng & Xanh Hoàng Gia', 'Red, White & Royal Blue', 'https://phimimg.com/upload/vod/20230920-1/e7c22af3dd51b110bc662750fcec6bab.jpg', 'https://phimimg.com/upload/vod/20230920-1/d5f387bb5921e0d9b74ead0e57254806.jpg', '<p><span style="font-family: ">Sau khi một cuộc ẩu đả xảy ra giữa Alex (con trai của tổng thống) và Hoàng tử Henry của nước Anh tại một sự kiện hoàng gia trở thành chủ đề bị bàn tán trên báo mạng, hiềm khích bấy lâu giữa hai người đã gây ảnh hưởng đến mối quan hệ giữa hai nước Mỹ và Anh. Khi họ bị buộc phải giả bộ làm lành, mối quan hệ băng giá giữa hai người đã tan chảy và dần nảy nở thành một tình cảm sâu sắc mà chính họ cũng không ngờ tới.</span></p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taylor Zakhar Perez","avatar":""},{"name":"Nicholas Galitzine","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Rachel Hilson","avatar":""},{"name":"Sarah Shahi","avatar":""},{"name":"Ellie Bamber","avatar":""},{"name":"Thomas Flynn","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Malcolm Atobrah","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324259);
