INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ban-trung-quoc-cuoc-phan-cong', 'Bóng Bàn Trung Quốc: Cuộc Phản Công', 'Ping-Pong: The Triumph', 'https://phimimg.com/upload/vod/20230920-1/17ddc30d9569564c4f2fe5da017c7e1d.jpg', 'https://phimimg.com/upload/vod/20230920-1/f0916a217d37864ddd3052fc3260913a.jpg', '<p>Bộ phim kể về câu chuyện huyền thoại của đội tuyển bóng bàn Trung Quốc vào đầu những năm 1990. Khi đó, đội tuyển bóng bàn nam đã bị các cường quốc châu Âu đè bẹp, Năm con hổ bóng bàn nam đã phát huy lợi thế của mình, và cuối cùng đã tổ chức một cuộc phản công tuyệt vời trong Giải vô địch bóng bàn thế giới năm 1995.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Deng Chao","avatar":""},{"name":"Sun Li","avatar":""},{"name":"Timmy Xu","avatar":""},{"name":"Duan Bowen","avatar":""},{"name":"Cai Yida","avatar":""},{"name":"Ding Guansen","avatar":""},{"name":"Sun Xilun","avatar":""},{"name":"Alan Aruna","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Liang Chao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
