INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nguoi-tot', 'Một Người Tốt', 'A Good Person', 'https://phimimg.com/upload/vod/20230920-1/c8587700927c0439e849b1b46e783fed.jpg', 'https://phimimg.com/upload/vod/20230920-1/e2a230ca176bf9c61eb1a11097fd4033.jpg', '<p>Bộ phim xoay quanh Allison, người đang có cuộc sống hạnh phúc nhưng mọi chuyện bỗng chốc sụp đổ khi chiếc xe cô cầm lái gặp phải tai nạn khiến cho chị gái của vị hôn phu sắp kết hôn qua đời. Mặc cảm và tội lỗi, Allison không dám đối mặt với mọi người, đặc biệt là người mà suýt chút nữa trở thành bố chồng của mình, Daniel. Dẫu vậy, cuộc gặp gỡ giữa cả hai đã mang đến những hy vọng mới để Allison hồi phục sau những tổn thương.</p>', 'Full', 1, 'single', 'completed', 22, 2023, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Florence Pugh","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"Celeste O''Connor","avatar":""},{"name":"Zoe Lister-Jones","avatar":""},{"name":"Chinaza Uche","avatar":""},{"name":"Toby Onwumere","avatar":""},{"name":"Nichelle Hines","avatar":""},{"name":"Ignacio Diaz-Silverio","avatar":""},{"name":"Alex Wolff","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
