INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oppenheimer', 'Oppenheimer', 'Oppenheimer', 'https://phimimg.com/upload/vod/20230920-1/ca7de43a07b7aee504d3ffee1dd9ca52.jpg', 'https://phimimg.com/upload/vod/20230920-1/4bf3d952409f5a2013a713f4fdd0608f.jpg', '<p><span style="font-family: ">Với nhân vật trung tâm là J. Robert Oppenheimer, nhà vật lý lý thuyết người đứng đầu phòng thí nghiệm Los Alamos, thời kỳ Thế chiến II. Ông đóng vai trò quan trọng trong Dự án Manhattan, tiên phong trong nhiệm vụ phát triển vũ khí hạt nhân, và được coi là một trong những “cha đẻ của bom nguyên tử”.</span></p>', 'Full', 1, 'single', 'completed', 33, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Florence Pugh","avatar":""},{"name":"Josh Hartnett","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Benny Safdie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '[]', 1784690324259);
