INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lego-cong-chua-disney-nhiem-vu-lau-dai', 'LEGO Công Chúa Disney: Nhiệm Vụ Lâu Đài', 'LEGO Disney Princess: The Castle Quest', 'https://phimimg.com/upload/vod/20230920-1/3e90b00db80b31022b47cb634be36e9d.jpg', 'https://phimimg.com/upload/vod/20230920-1/437b48f3302486d6628a2578eb828827.jpg', '<p>Tiana, Moana, Bạch Tuyết, Rapunzel và Ariel đang tham gia vào một cuộc phiêu lưu khi mỗi người bất ngờ được chuyển đến một lâu đài bí ẩn. Ngay sau khi đến nơi, họ nhanh chóng phát hiện ra rằng Gaston đã ấp ủ một kế hoạch độc ác nhằm chiếm lấy toàn bộ vương quốc của họ!. Các nhân vật Công chúa phải làm việc cùng nhau để giải quyết những thách thức ẩn sâu trong các bức tường lâu đài và cố gắng cứu vương quốc của họ khỏi Gaston. Liệu lòng dũng cảm, sự nhanh trí và tinh thần đồng đội sẽ thắng thế?</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2023, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Jodi Benson","avatar":""},{"name":"Auli''i Cravalho","avatar":""},{"name":"Mandy Moore","avatar":""},{"name":"Anika Noni Rose","avatar":""},{"name":"Katherine Von Till","avatar":""},{"name":"Richard White","avatar":""},{"name":"Jo Anne Worley","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Jeff Bennett","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324259);
