INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-ro-dac-biet', 'Đội Bóng Rổ Đặc Biệt', 'Champions', 'https://phimimg.com/upload/vod/20230920-1/fa187756aa781344e98961c747a176d9.jpg', 'https://phimimg.com/upload/vod/20230920-1/2a31d411670da355c847a906123a0243.jpg', '<p>Một cựu huấn luyện viên bóng rổ của giải đấu nhỏ được tòa án ra lệnh quản lý một đội gồm các cầu thủ thiểu năng trí tuệ. Anh ấy sớm nhận ra rằng bất chấp những định kiến ban đầu của bản thân, cùng nhau, đội này có thể tiến xa hơn những gì họ từng tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 18, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Woody Harrelson","avatar":""},{"name":"Kaitlin Olson","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Matt Cook","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Madison Tevlin","avatar":""},{"name":"Joshua Felder","avatar":""},{"name":"Kevin Iannucci","avatar":""},{"name":"Ashton Gunning","avatar":""},{"name":"Matthew Von Der Ahe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324259);
