INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('10-ngay-cua-mot-ke-xau', '10 Ngày Của Một Kẻ Xấu', '10 Days of a Bad Man', 'https://phimimg.com/upload/vod/20230920-1/73c32c090edf31588f623c8c3616670a.jpg', 'https://phimimg.com/upload/vod/20230920-1/f52dd82a9bdfbc55773b89077991724c.jpg', '<p>Bị thương, suy sụp và mất người thân, một thám tử tư phải dốc sức vượt qua muôn vàn dối trá nhằm lật mở sự thật đằng sau vụ án mạng trong biệt thự.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Nejat İşler","avatar":""},{"name":"Nur Fettahoğlu","avatar":""},{"name":"Şenay Gürler","avatar":""},{"name":"Erdal Yildiz","avatar":""},{"name":"Ilayda Akdoğan","avatar":""},{"name":"Hazal Filiz Küçükköse","avatar":""},{"name":"Riza Kocaoğlu","avatar":""},{"name":"Kadir Çermik","avatar":""},{"name":"Mahir Günşiray","avatar":""},{"name":"Ilayda Alişan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324259);
