INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-ma-tinh-than', 'Long Mã Tinh Thần', 'Ride On', 'https://phimimg.com/upload/vod/20230919-1/02baedf537ad52148ea0c561649a6506.jpg', 'https://phimimg.com/upload/vod/20230919-1/6785ef2fd5d8342425b48566328b2e80.jpg', '<p><span style="font-family: ">Võ sĩ Long Hổ xinh đẹp một thời giờ đã thất thường Lão La sống với con ngựa yêu quý của mình, Xích Thố. Do tranh chấp nợ nần liên quan đến Xích Thố, anh phải đối mặt với cuộc khủng hoảng &quot;cha con ly tán&quot;. Trong cơn tuyệt vọng, lão La nhờ đến sự giúp đỡ của con gái Bao và bạn trai của cô ấy, những người đã hiểu lầm anh trong nhiều năm. Trên con đường tự lực của ba người một ngựa, họ pha trò rất nhiều và dần thân thiết với nhau hơn.</span></p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Liu Haocun","avatar":""},{"name":"Kevin Guo","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Joey Yung","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Andy On","avatar":""},{"name":"Xiao Shenyang","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Aarif Rahman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
