INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-nu-thoat-y', 'Vũ Nữ Thoát Y', 'Suki', 'https://phimimg.com/upload/vod/20230919-1/1e4ff916f069c513481b00295eeb856a.jpg', 'https://phimimg.com/upload/vod/20230919-1/b4e7a6e63c1e2cbc1777c7710cde9c9e.jpg', '<p>Một vũ nữ thoát y và một chàng trai gigolo đã hứa với nhau rằng công việc của họ không thể chia rẽ họ. Nhưng khi dục vọng và cám dỗ xuất hiện, họ bắt đầu đặt câu hỏi về lời thề của mình.</p>', 'Full', 1, 'single', 'completed', 22, 2023, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Azi Acosta","avatar":""},{"name":"Alona Navarro","avatar":""},{"name":"John Flores","avatar":""},{"name":"Jiad Arroyo","avatar":""},{"name":"Gwen Garci","avatar":""},{"name":"Yda Manzano","avatar":""},{"name":"Chad Kinis","avatar":""},{"name":"Soliman Cruz","avatar":""},{"name":"Alexa Ocampo","avatar":""},{"name":"Sheila Snow","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
