INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ki-mon-phi-giap', 'Kì Môn Phi Giáp', 'The Thousand Faces of Feijia', 'https://phimimg.com/upload/vod/20230919-1/b7837103e1e1c1655aebd89ca1dcf54e.jpg', 'https://phimimg.com/upload/vod/20230919-1/186a8f8dcfb30b5a971e57bbfee75072.jpg', '<p>Vương Tiểu Hiệp vốn là một thanh niên không có hoài bão gì lớn lao, sống chung với người cha mù tại trấn. Nguyện vọng duy nhất của cậu là có thể chữa khỏi cho mắt của cha. Trong một lần tình cờ, Vương Tiểu Hiệp gặp được Thẩm Lam Nhi, không may sao lại bị cuốn vào một âm mưu. Anh đến Kỳ Ẩn Môn và cuối cùng phát hiện ra thân thế bị giấu kín của mình.</p>', 'Full', 1, 'single', 'completed', 22, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Qiwei","avatar":""},{"name":"Hu Xue''er","avatar":""},{"name":"Liu Yajin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324259);
