INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-sinh-am-duong', 'Tiên Sinh Âm Dương', 'Mr. Ghost', 'https://phimimg.com/upload/vod/20230919-1/700451cc6ba2ab5d6c70f6773f06ebf0.jpg', 'https://phimimg.com/upload/vod/20230919-1/377cef606e0b803189f945af73737d87.jpg', '<p>Tương truyền có một người tên Diêm Bất Phiền rất được yêu mến vì hay lén giúp đỡ người dân ở thị trấn nọ. Người ta đồn rằng, ông trên thông thiên văn dưới tường địa lý, phương pháp trừ tà bắt quỷ tất thảy đều thông thạo, nhìn thấy điều người thường không thấy, vạch rõ bất bình trong thị phi, được xưng là Dương Tiên Sinh. Diêm Bất Phiền được nhà họ Lâm mời đến phân xử, khi ông bước vào cửa đã nhìn thấy một hàng &quot;dấu chân ma&quot; trên mặt đất đi về phía trước, theo lời kể của tổng quản nhà họ Lâm, Diêm Bất Phiền đi theo dấu chân và bắt tay giải quyết những &quot;thứ ma quái&quot; trong Lâm gia.</p>', 'Full', 1, 'single', 'completed', 26, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ryan Zhang","avatar":""},{"name":"Gao Chenglong","avatar":""},{"name":"Fu Xiaoshuang","avatar":""},{"name":"Gong Hanlin","avatar":""},{"name":"Liu Yiwei","avatar":""},{"name":"Wang Zhipeng","avatar":""},{"name":"Hou Tongjiang","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324259);
