INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-tuoc', 'Bá Tước', 'El Conde', 'https://phimimg.com/upload/vod/20230919-1/5cb9252f04273445f23c2e6264df5886.jpg', 'https://phimimg.com/upload/vod/20230919-1/b76629d4a7e41d200564b0b9019fce6f.jpg', '<p>Bộ phim kể câu chuyện về Augusto Pinochet, một ma cà rồng 250 tuổi. Cuộc đời dài đằng đẵng của ông trôi qua mà chỉ khiến cho người khác nhớ đến mình như một tên trộm, chính vì vậy, Augusto quyết định sẽ ra đi một lần và mãi mãi để thoát khỏi sự mệt mỏi và chán ngán này</p>', 'Full', 1, 'single', 'completed', 24, 2023, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Jaime Vadell","avatar":""},{"name":"Gloria Münchmeyer","avatar":""},{"name":"Alfredo Castro","avatar":""},{"name":"Paula Luchsinger","avatar":""},{"name":"Stella Gonet","avatar":""},{"name":"Catalina Guerra","avatar":""},{"name":"Amparo Noguera","avatar":""},{"name":"Antonia Zegers","avatar":""},{"name":"Marcial Tagle","avatar":""},{"name":"Diego Muñoz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324259);
