INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-hung-xanh', 'Bọ Hung Xanh', 'Blue Beetle', 'https://phimimg.com/upload/vod/20230919-1/f2decb35bccc896b9696d0ca6cf642c0.jpg', 'https://phimimg.com/upload/vod/20230919-1/3a2781241b049c1601e90d22c615fc77.jpg', '<p>Cậu sinh viên mới tốt nghiệp Jaime Reyes trở về nhà với tràn trề niềm tin và hy vọng về tương lai, để rồi nhận ra quê nhà của anh đã thay đổi rất nhiều so với trước đây. Khi tìm kiếm mục đích sống trên thế giới này, Jamie đối mặt với bước ngoặt cuộc đời khi anh nhận ra mình sở hữu một di sản cổ đại của công nghệ sinh học ngoài hành tinh: Scarab (Bọ Hung). Khi Scarab chọn Jamie trở thành vật chủ, anh được ban tặng một bộ áo giáp với siêu sức mạnh đáng kinh ngạc không ai có thể lường trước. Số phận của Jamie hoàn toàn thay đổi khi giờ đây, anh đã là siêu anh hùng BLUE BEETLE.</p>', 'Full', 1, 'single', 'completed', 23, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Xolo Mariduena","avatar":""},{"name":"Bruna Marquezine","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Raoul Max Trujillo","avatar":""},{"name":"Damián Alcázar","avatar":""},{"name":"Adriana Barraza","avatar":""},{"name":"George Lopez","avatar":""},{"name":"Belissa Escobedo","avatar":""},{"name":"Elpidia Carrillo","avatar":""},{"name":"Harvey Guillén","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324259);
