INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chu-3', 'Bà Chủ 3', 'Queen of Triads 3', 'https://phimimg.com/upload/vod/20230919-1/f0e9ae69ca156da7512ecbb94398ee33.jpg', 'https://phimimg.com/upload/vod/20230919-1/8c654f61d32535b1d18089293bc5dc70.jpg', '<p>Câu chuyện diễn ra tại một quốc gia ở Đông Nam Á, nữ chính Thiết Gia Văn chia tay sự nghiệp cảnh sát với nỗi đau mất người yêu và thất bại trong nhiệm vụ, cô mở một phòng tập thể dục ẩn danh và bí mật tìm kiếm dấu vết của kẻ buôn ma túy Bạch Hổ. Sau khi trải qua hàng loạt thất bại và thử thách, cô đã dựa vào lòng dũng cảm, trí tuệ và kỹ năng phi thường của mình để đứng ra đòi công lý cho các nữ huấn luyện viên thể dục, cuối cùng cô đã tự tay bắt được kẻ thù và giao hắn cho cảnh sát Quốc tế.</p>', 'Full', 1, 'single', 'completed', 19, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Ron Ng","avatar":""},{"name":"Oscar Li Ka","avatar":""},{"name":"Dominic Ho","avatar":""},{"name":"Xie Sitong","avatar":""},{"name":"Cai Xiangyu","avatar":""},{"name":"Li Muyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
