INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thu-cu-khoi', 'Xạ Thủ Cừ Khôi', 'Kill Shot', 'https://phimimg.com/upload/vod/20230919-1/89da0ae6b26d91b06a72b46902b0e5da.jpg', 'https://phimimg.com/upload/vod/20230919-1/dfaeda707d19166c367d2fd87db3351a.jpg', '<p>Trong vai thợ săn, một nhóm khủng bố đang tìm kiếm 100 triệu đô la đã bị đánh cắp và thất lạc trong một vụ tai nạn máy bay trên đường từ Afghanistan.</p>', 'Full', 1, 'single', 'completed', 21, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rib Hillis","avatar":""},{"name":"Rachel Cook","avatar":""},{"name":"Todd Gordon","avatar":""},{"name":"Ari Novak","avatar":""},{"name":"Xian Mikol","avatar":""},{"name":"Mara Ohara","avatar":""},{"name":"Anaya Patel","avatar":""},{"name":"Jeff Medley","avatar":""},{"name":"Bobby Maximus","avatar":""},{"name":"Joe Cebula","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
