INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-ke', 'Ông Kẹ', 'The Boogeyman', 'https://phimimg.com/upload/vod/20230919-1/81eb128419c1eda6f3e7ce4762cb882d.jpg', 'https://phimimg.com/upload/vod/20230919-1/c539681e20799d2a2a9911838848df93.jpg', '<p><span style="font-family: ">Từ nguyên tác truyện ngắn của bậc thầy truyện kinh dị Stephen King, “Ông Kẹ” kể về câu chuyện của gia đình Harper khi một thực thể siêu nhiên bám theo và liên tục phá rối gia đình họ. Khi mà con quái vật này lấp ló trong bóng tối và chực chờ làm hại cô bé Sawyer như chực chờ một con mồi, chị gái Sadie và bố Will sẽ phải hành động để ngăn chặn điều này trước khi quá muộn.</span></p>', 'Full', 1, 'single', 'completed', 24, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sophie Thatcher","avatar":""},{"name":"Vivien Lyra Blair","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Marin Ireland","avatar":""},{"name":"Madison Hu","avatar":""},{"name":"Maddie Nichols","avatar":""},{"name":"Mabel Tyler","avatar":""},{"name":"Leeann Ross","avatar":""},{"name":"Rio Sarah Machado","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324259);
