INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-dive-2023', 'The Dive (2023)', 'The Dive (2023)', 'https://phimimg.com/upload/vod/20230919-1/a9091c13183e629a83e77edc15f8a22c.jpg', 'https://phimimg.com/upload/vod/20230919-1/21a075d344543bea36b9171debbdbcb6.jpg', '<p>Hai chị em đi lặn ở một địa điểm đẹp, xa xôi. Một trong hai chị em bị đá rơi trúng, khiến cô bị mắc kẹt ở độ sâu 28 mét bên dưới. Với lượng oxy thấp đến mức nguy hiểm và nhiệt độ lạnh giá, em gái cô phải chiến đấu để giành lấy mạng sống.</p>', 'Full', 1, 'single', 'completed', 23, 2023, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Louisa Krause","avatar":""},{"name":"Sophie Lowe","avatar":""},{"name":"Stella Uhrig","avatar":""},{"name":"Shire Richardson","avatar":""},{"name":"David Scicluna","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324259);
