INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-hoi-van-minh', 'Xã Hội Văn Minh', 'Polite Society', 'https://phimimg.com/upload/vod/20230918-1/587533e8e3c97af30912dcb0777e6799.jpg', 'https://phimimg.com/upload/vod/20230918-1/b41cd384c2fe4e5d9ea99d4ced9084e8.jpg', '<p>Võ sĩ tập sự Ria Khan tin rằng cô phải cứu chị gái Lena khỏi cuộc hôn nhân sắp xảy ra. Sau khi tranh thủ sự giúp đỡ của bạn bè, Ria cố gắng thực hiện vụ cướp đám cưới đầy tham vọng nhất dưới danh nghĩa độc lập và tình chị em.</p>', 'Full', 1, 'single', 'completed', 24, 2023, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Priya Kansara","avatar":""},{"name":"Ritu Arya","avatar":""},{"name":"Shobu Kapoor","avatar":""},{"name":"Ella Bruccoleri","avatar":""},{"name":"Seraphina Beh","avatar":""},{"name":"Shona Babayemi","avatar":""},{"name":"Nimra Bucha","avatar":""},{"name":"Jeff Mirza","avatar":""},{"name":"Akshay Khanna","avatar":""},{"name":"Renu Brindle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
