INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hao-truy-sat', 'Linh Hào Truy Sát', 'The Comeback', 'null', 'https://phimimg.com/upload/vod/20230910-1/d95415c33ebda4d618726b13664898a4.jpg', '<p>Shang Wang Yinshou (do Fei Xiang thủ vai) cấu kết với hồ ly yêu Daji (do Na Ran thủ vai) để tàn ác và vô tội, gây ra sự trừng phạt của thần thánh. Nàng tiên Côn Lôn Jiang Ziya (do Huang Bo thủ vai) đã xuống núi cùng với &quot;Fengshen Bang&quot; để tìm chủ nhân chung của thế giới và cứu lấy những người dân thường. Ji Fa (do Yu Shi thủ vai), con trai của Xibohou, dần dần phát hiện ra màu sắc thực sự của Yin Shou và quay trở lại Chaoge. Các lực lượng của tất cả các bên đang tăng mạnh, và tình hình đang thay đổi đang bắt đầu xuất hiện ...</p>', 'Full', 1, 'single', 'completed', 24, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Andy On","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Jiang Peiyao","avatar":""},{"name":"Mu Lei","avatar":""},{"name":"Waise Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
