INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-khach', 'Hành Khách', 'The Passenger', 'https://phimimg.com/upload/vod/20230916-1/80f21a46dfc1269c3bd7702dc8db6b2b.jpg', 'https://phimimg.com/upload/vod/20230916-1/7ab685001104c49d50f66c4890ea6c41.jpg', '<p>Khi Randy, một đồng nghiệp của Benson bất ngờ tìm gặp lại anh ta, câu chuyện về quá khứ giết người của Benson sống trở lại và đẩy tất cả vào rắc rối kinh khủng. Randy bị ép buộc chạy trốn trên một chuyến xe mà chưa biết điểm dừng cuối cùng là lúc nào và bao nhiêu tội ác nữa phải được thực thi</p>', 'Full', 1, 'single', 'completed', 29, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kyle Gallner","avatar":""},{"name":"Johnny Berchtold","avatar":""},{"name":"Liza Weil","avatar":""},{"name":"Billy Slaughter","avatar":""},{"name":"Matthew Laureano","avatar":""},{"name":"Jordan Sherley","avatar":""},{"name":"Kanesha Washington","avatar":""},{"name":"Lupe Leon","avatar":""},{"name":"Merah Benoit","avatar":""},{"name":"Glendon Ray Hobgood","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324259);
