INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-me-va-trach-nhiem', 'Đam Mê Và Trách Nhiệm', 'Sentinelle', 'https://phimimg.com/upload/vod/20230916-1/9c5b0a6f01e444ca2d0dcc7f6758652b.jpg', 'https://phimimg.com/upload/vod/20230916-1/e206301fa49748d088dfdbe667552614.jpg', '<p>François Sentinelle, người sống hai cuộc đời khác nhau. Trong ban ngày, anh là một cảnh sát nổi tiếng nhất trên Đảo Réunion, nổi tiếng với phong cách cứng rắn và áo sơ mi hoa, truy đuổi tội phạm trên chiếc xe Defender màu vàng nổi tiếng của mình. Nhưng vào thời gian còn lại, Sentinelle cũng là một ca sĩ quyến rũ. Mọi chuyện trở nên phức tạp khi một vụ án quan trọng trong đời anh buộc anh phải chọn giữa việc làm cảnh sát và tình yêu của mình đối với âm nhạc.</p>', 'Full', 1, 'single', 'completed', 27, 2023, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jonathan Cohen","avatar":""},{"name":"Raphaël Quenard","avatar":""},{"name":"Emmanuelle Bercot","avatar":""},{"name":"Gustave Kervern","avatar":""},{"name":"Ramzy Bedia","avatar":""},{"name":"Laurent Evuort","avatar":""},{"name":"Ken Eind","avatar":""},{"name":"Joseph Woerlen","avatar":""},{"name":"Matthieu Virginius","avatar":""},{"name":"Dimitri Virginius","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
