INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-bay-cuu', 'Trò Chơi Bầy Cừu', 'Lamb Game', 'https://phimimg.com/upload/vod/20230916-1/bce5206eee97f694fcac15aa194b5df0.jpg', 'https://phimimg.com/upload/vod/20230916-1/96a61686680cf740883a0064ab9c2ad6.jpg', '<p><span style="text-wrap: nowrap;">Thuý Anh, cựu vô địch judo trẻ đầy nhiệt huyết từ Bangkok. Cô quyết định rời sự nghiệp thể thao để theo đuổi công việc ngân hàng. Tuy nhiên, đêm Trung thu, một sự cố đẩy cô vào vòng xoáy nguy hiểm khi xe hỏng và điện thoại mất sóng.</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Tình cờ, Thuý Anh khám phá âm mưu đen tối của nhóm tội phạm và nhân viên bảo vệ, đang lên kế hoạch đánh cắp số tiền khổng lồ từ ngân hàng. Bị bắt và giam cầm tại một căn phòng, cô không bao phục và quyết tâm sử dụng kỹ năng judo và trí thông minh để chiến đấu.</span></p>', 'Full', 1, 'single', 'completed', 28, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lynn Hung","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Ricky Chan Po-Yuen","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Zhao Jingshuyu","avatar":""},{"name":"Pang Wai-On","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324259);
