INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-ruoi', 'Một Ngày Rưỡi', 'A Day And A Half', 'https://phimimg.com/upload/vod/20230916-1/e582d0c22afad33f30cebd4ab9b0ade4.jpg', 'https://phimimg.com/upload/vod/20230916-1/92a119f1ce90e1530d5bb3e341d1449d.jpg', '<p>Trong nỗ lực tuyệt vọng để đoàn tụ với con gái, một người đàn ông có vũ trang xông vào trung tâm y tế nơi người vợ ghẻ lạnh của anh ta làm việc và bắt cóc cô.</p>', 'Full', 1, 'single', 'completed', 28, 2023, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Alexej Manvelov","avatar":""},{"name":"Alma Pöysti","avatar":""},{"name":"Fares Fares","avatar":""},{"name":"Stina Ekblad","avatar":""},{"name":"Annika Hallin","avatar":""},{"name":"Daniel Guldstrand","avatar":""},{"name":"Annica Liljeblad","avatar":""},{"name":"Richard Forsgren","avatar":""},{"name":"Bella Klaus","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
