INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-goi-am-binh', 'Tiếng Gọi Âm Binh', 'Khanzab (2023)', 'https://phimimg.com/upload/vod/20230916-1/11e0f318c3fe624d1b19fb3aa0502a9e.jpg', 'https://phimimg.com/upload/vod/20230916-1/58e8fb915b5572bcba3f8cebe5622fb6.jpg', '<p><span style="font-family: ">Phim được dựa trên một vụ thảm sát thầy cúng với tà thuật đen ở Indonesia năm 1998. Chuyện phim diễn ra ở một ngôi làng tại Indonesia và hiện tượng kì lạ ở nhà cầu nguyện trong làng khi các người dân liên tục bị quấy phá khi cầu nguyện. Cha của Rahayu là một người thầy cúng nổi tiếng về việc chữa bệnh bằng việc liên kết với các vong hồn vất vưởng. Do đó, có một số người dân cảm thấy ghê sợ và tin rằng ông có liên kết đến những vong linh chuyên đi quấy phá dân làng. Và có kẻ đã đứng đằng sau âm mưu giết hại đã ra tay với ông một cách tàn nhẫn trước mặt con gái ông - Rahayu.</span></p>', 'Full', 1, 'single', 'completed', 30, 2023, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Yasamin Jasem","avatar":""},{"name":"Tika Bravani","avatar":""},{"name":"Arswendi Nasution","avatar":""},{"name":"Munggaran","avatar":""},{"name":"Rizky Hanggono","avatar":""},{"name":"Fuad Idris","avatar":""},{"name":"Vonny Anggraini","avatar":""},{"name":"Badriyah Afiff","avatar":""},{"name":"Sheryl Drisanna Kuntadi","avatar":""},{"name":"Sabian","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324259);
