INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieng-goi-am-binh', 'Tiếng Gọi Âm Binh', 'Khanzab (2023)', 'tiếng gọi âm binh khanzab (2023) yasamin jasem tika bravani arswendi nasution munggaran rizky hanggono fuad idris vonny anggraini badriyah afiff sheryl drisanna kuntadi sabian ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('72-gio-chien-dich-hoang-kim', '72 giờ: Chiến Dịch Hoàng Kim', '72 Hours - Operation Gold', 'https://phimimg.com/upload/vod/20230916-1/3430f97a9c9c449a138c1acc1f1d4f47.jpg', 'https://phimimg.com/upload/vod/20230916-1/9d925c8e70ec05c970cf16d7160a0404.jpg', '<p><strong>72 Giờ</strong>: Chiến Dịch Hoàng Kim 72 Hour Golden Operation 2023 Full HD Vietsub Thuyết Minh Trong thành phố Phổ Quang, một nhóm băng đảng xã hội đen đã khủng bố cư dân bằng hàng loạt tội ác tàn bạo. Chúng tham gia vào việc buôn bán ma túy, trốn thuế và gây gỗ, để lại dấu vết đen tối trên mọi ngóc ngách của thành phố. Trong nhiều năm qua, cảnh sát Phổ Quang đã dốc hết sức lực để đối mặt với băng đảng này, nhưng vấn đề lớn nhất vẫn là không thể bắt giữ người lãnh đạo đen tối đứng sau mọi vụ án.</p><p>Một ngày, cuộc sống của Vịnh Lâm - một thành viên bên trong băng đảng - thay đổi khi cô quyết định đứng lên chống lại ác quỷ mình đã từng phục vụ. Với lòng trung thành và niềm tin vào công lý, Vịnh Lâm tìm đến cảnh sát và bắt đầu chia sẻ những bí mật, chứng cứ mà chỉ cô biết. Thượng úy Đường Phi, một chiến binh kì cựu trong cuộc chiến chống băng đảng, tiếp tục phá vỡ mọi ranh giới để giúp Vịnh Lâm và tập hợp một đội ngũ các sĩ quan ưu tú từ các đội trinh sát, chống ma túy, giao thông và đặc nhiệm.</p><p>Với thông tin nội bộ và chứng cứ được Vịnh Lâm cung cấp, cảnh sát tiến hành một cuộc điều tra sâu rộng, đào sâu vào các hoạt động bí mật của băng đảng. Từ việc buôn bán ma túy cho đến gây gỗ và trốn thuế, họ đã tìm hiểu mọi góc khuất của băng đảng để triệt hạ chúng một lần and cho mãi mãi.</p><p>Cuộc đối đầu cuối cùng diễn ra trong vòng 72 giờ đầy căng thẳng. Sự hợp tác không ngừng giữa các đội trinh sát, đặc nhiệm và cảnh sát đem lại kết quả tốt đẹp. Bằng sự dũng cảm và tài năng của mình, họ tìm thấy những con người chủ chốt đứng sau băng đảng, tiêu diệt chúng và trả lại thành phố Phổ Quang ánh sáng và chân chính.</p><p><strong>72 Giờ</strong>: Chiến Dịch Hoàng Kim là một bộ phim kịch tính đầy hành động, xoay quanh sự hy sinh, lòng dũng cảm và khao khát công lý của những người lính cảnh sát tận tụy trong cuộc chiến chống lại ác quỷ xã hội đen.</p>', 'Full', 1, 'single', 'completed', 30, 2023, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Tse","avatar":""},{"name":"Jeana Ho Pui-Yu","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Ken Hung","avatar":""},{"name":"Kelvin Lee","avatar":""},{"name":"Zhu Huige","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
