INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-khuyen-bat-cong', 'Trung Khuyển Bát Công', 'Hachiko', 'https://phimimg.com/upload/vod/20230916-1/529eb90af3014286a0d5d1a0bc03ae98.jpg', 'https://phimimg.com/upload/vod/20230916-1/41f230e0a5586215a3c72616ad30bf5a.jpg', '<p>Đây là câu chuyện về chú chó con đã khiến hàng trăm triệu người trên thế giới cảm động. Hachiko (Batong) là một chú chó chăn cừu dễ thương của Trung Quốc. Anh gặp người chủ định mệnh của mình Chen Jingxiu trong đám đông rộng lớn và trở thành thành viên của gia đình Chen. Thời gian trôi qua, ngôi nhà xinh đẹp một thời không còn nữa, nhưng Batong vẫn chờ đợi ở nơi đó, và số phận của nó gắn chặt với gia đình. Bộ phim này được chuyển thể từ kịch bản gốc &quot;Hachiko&quot; của Kaneto Shindo.</p>', 'Full', 1, 'single', 'completed', 31, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feng Xiaogang","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Bai Jugang","avatar":""},{"name":"Huang Chutong","avatar":""},{"name":"Bo Qian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324259);
