INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-duoi-mot-huyen-thoai', 'Theo Đuổi Một Huyền Thoại', 'Air', 'null', 'https://phimimg.com/upload/vod/20230908-1/0214b970cd4e5d142aaae39459ab0847.jpg', '<p>Từ đạo diễn đã từng đoạt giải thưởng Ben Affleck, AIR hé lộ mối quan hệ đột phá giữa huyền thoại Michael Jordan khi mới bắt đầu sự nghiệp và bộ phận bóng rổ còn non trẻ của Nike, đã làm thay đổi thế giới thể thao và văn hóa đương đại với thương hiệu Air Jordan. Câu chuyện cảm động này kể về sự đánh cược khi đặt lên bàn cân tình hình kinh doanh của cả công ty, tầm nhìn vĩ đại của một người mẹ biết giá trị và tài năng của con trai mình, và một siêu sao bóng rổ đã trở thành huyền thoại.</p>', 'Full', 1, 'single', 'completed', 30, 2023, 'Vietsub', 'HD', 'Hoa Kỳ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Julius Tennon","avatar":""},{"name":"Chris Tucker","avatar":""},{"name":"Matthew Maher","avatar":""},{"name":"Gustaf Skarsgård","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324259);
