INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-toi', 'Bố Tôi', 'About My Father', 'https://phimimg.com/upload/vod/20230916-1/55de37669a7c25d3250ecfe43a257c53.jpg', 'https://phimimg.com/upload/vod/20230916-1/dfc27c3efbbae44a30444422134b99a5.jpg', '<p>Được sự khuyến khích của vị hôn thê, một người đàn ông và cha anh dành kỳ nghỉ cuối tuần với gia đình giàu có và cực kỳ lập dị của cô. Cuộc tụ tập sớm phát triển thành xung đột văn hóa, cho phép hai cha con khám phá ý nghĩa thực sự của gia đình.</p>', 'Full', 1, 'single', 'completed', 30, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sebastian Maniscalco","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Anders Holm","avatar":""},{"name":"David Rasche","avatar":""},{"name":"Brett Dier","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"Arielle Prepetit","avatar":""},{"name":"Adan James Carrillo","avatar":""},{"name":"Colby Shinn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324259);
