INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-luu-lac-giang-ho', 'Thiếu Nữ Lưu Lạc Giang Hồ', 'Egg and Stone (Girl''s Jiang Hu)', 'null', 'https://phimimg.com/upload/vod/20230908-1/52edaf81b73aa90c2a4a6dee68311ff8.jpg', '<p>Hoắc Tinh Thần, con gái của chưởng môn Ngũ Nhạc Môn nổi danh đệ nhất trong giang hồ, vì muốn chống lại số mệnh và cuộc hôn nhân sắp đặt mà quyết định bước chân vào giang hồ. Trên hành trình, cô gặp Tương Bộ Đinh - một thiếu hiệp đang điều tra vụ mất tích của tông đồ. Hai người tình cờ gặp gỡ rồi kết giao hành tẩu. Họ kết bạn với nhiều hiệp sĩ khác và khám phá sự thật về sự xuất hiện của &quot;dị tộc&quot; trong giang hồ. Cuối cùng đã điều tra đến tận cửa hai môn phái lớn là Mộ Lang và Tống Trường Sinh. Trong quá trình điều tra, Hoắc Tinh Thần dần trưởng thành hơn, nàng vạch trần âm mưu trùng điệp, cuối cùng cũng thực hiện được lý tưởng của bản thân. Nàng quay trở về nắm vị trí chưởng môn Ngũ Nhạc Môn, cũng nhau tìm thấy được chân ái của đời mình.</p>', 'Hoàn tất (24/24)', 24, 'series', 'completed', 32, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Từ Lộ","avatar":""},{"name":"Wu Xi Ze","avatar":""},{"name":"Vương Dĩ Luân","avatar":""},{"name":"Bunny Zhang","avatar":""},{"name":"Lizhuozhao","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324259);
