INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-len', 'Tiến Lên', 'Moving On', 'https://phimimg.com/upload/vod/20230915-1/e83bb8de7467d0f9fe618a54cc133b57.jpg', 'https://phimimg.com/upload/vod/20230915-1/38877cf830ce86df8af1a5341d358105.jpg', '<p>Hai người bạn cũ gặp lại nhau tại đám tang của bạn họ và quyết định trả thù chính xác người góa vợ đã đối xử tệ bạc với cả ba người họ nhiều thập kỷ trước.</p>', 'Full', 1, 'single', 'completed', 26, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jane Fonda","avatar":""},{"name":"Lily Tomlin","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Richard Roundtree","avatar":""},{"name":"Sarah Burns","avatar":""},{"name":"Marcel Nahapetian","avatar":""},{"name":"Amber Chardae Robinson","avatar":""},{"name":"Vachik Mangassarian","avatar":""},{"name":"Eddie Martinez","avatar":""},{"name":"Santina Muha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
