INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-bao', 'Tình Báo', 'Confidential Informant', 'https://phimimg.com/upload/vod/20230915-1/64cd0ce9eca45e50b25c4cfaf903a114.jpg', 'https://phimimg.com/upload/vod/20230915-1/0a20364c2a072af928d8eb20fb18704e.jpg', '<p>Trong một trận dịch crack, hai đặc vụ ma túy đang truy lùng một kẻ giết cảnh sát. Hy vọng có manh mối, Moran và Thorton đền đáp một kẻ nghiện cung cấp thông tin. Để chu cấp cho vợ và con trai, Moran lôi kéo con chim bồ câu vào một âm mưu chết người. Điều này khiến các đối tác phải chịu sự giám sát của một nhân viên nội vụ đáng ngờ.</p>', 'Full', 1, 'single', 'completed', 30, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominic Purcell","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Arielle Raycene","avatar":""},{"name":"Nick Stahl","avatar":""},{"name":"Erik Valdez","avatar":""},{"name":"Jon Lindstrom","avatar":""},{"name":"Camila Savia","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
