INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nhu-lan-dau', 'Yêu Như Lần Đầu', 'Love Again', 'https://phimimg.com/upload/vod/20230915-1/0e97f3625413200966b4a2aedacf4554.jpg', 'https://phimimg.com/upload/vod/20230915-1/dcf6ba38e8565dbcbf0b58d4f8a55d00.jpg', '<p>Chấp niệm với một người là quá lớn khi chỉ cần thấy người ấy, ta như quay về lại lúc mới yêu. Nếu sâu thẳm trong bạn vẫn còn có hình bóng ấy thì valentine này, sao không để họ hay?</p>', 'Full', 1, 'single', 'completed', 29, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Priyanka Chopra Jonas","avatar":""},{"name":"Sam Heughan","avatar":""},{"name":"Céline Dion","avatar":""},{"name":"Sofia Barclay","avatar":""},{"name":"Russell Tovey","avatar":""},{"name":"Lydia West","avatar":""},{"name":"Steve Oram","avatar":""},{"name":"Omid Djalili","avatar":""},{"name":"Nick Jonas","avatar":""},{"name":"Celia Imrie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324259);
