INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-ra-chien-dau', 'Đi Ra Chiến Đấu', 'Come Out Fighting', 'https://phimimg.com/upload/vod/20230915-1/6c81c794788d65608f1167558c8d2f52.jpg', 'https://phimimg.com/upload/vod/20230915-1/59400087fa799b3145d4c674244115cc.jpg', '<p>Trong Thế chiến thứ hai, một đội lính Mỹ gốc Phi được cử đi làm nhiệm vụ giải cứu phía sau phòng tuyến của kẻ thù để xác định vị trí sĩ quan chỉ huy bị mất tích và một phi công chiến đấu bị bắn rơi.</p>', 'Full', 1, 'single', 'completed', 28, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Michael Jai White","avatar":""},{"name":"Kellan Lutz","avatar":""},{"name":"Vicellous Reon Shannon","avatar":""},{"name":"Hiram A. Murray","avatar":""},{"name":"Justen Jones","avatar":""},{"name":"Gary David Keast","avatar":""},{"name":"Aaron Courteau","avatar":""},{"name":"Martin Davis","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324259);
