INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lay-banh-lam-moi', 'Lấy Bánh Làm Mồi', 'Sitting in Bars with Cake', 'https://phimimg.com/upload/vod/20230915-1/df6e4ded2a4a652e2cdcbf96e8c38cc9.jpg', 'https://phimimg.com/upload/vod/20230915-1/10c691655ead328d4d124754edc90d7d.jpg', '<p>Corinne hướng ngoại thuyết phục Jane, một thợ làm bánh tài năng, nhút nhát, cam kết thực hiện một năm mang bánh đến các quán bar để giúp cô gặp gỡ mọi người và xây dựng sự tự tin. Nhưng khi Corinne nhận được chẩn đoán thay đổi cuộc sống, cặp đôi phải đối mặt với thử thách không giống bất cứ điều gì họ từng trải qua trước đây.</p>', 'Full', 1, 'single', 'completed', 28, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Yara Shahidi","avatar":""},{"name":"Odessa A''zion","avatar":""},{"name":"Bette Midler","avatar":""},{"name":"Ron Livingston","avatar":""},{"name":"Maia Mitchell","avatar":""},{"name":"Aaron Domínguez","avatar":""},{"name":"Rish Shah","avatar":""},{"name":"Martha Kelly","avatar":""},{"name":"Adina Porter","avatar":""},{"name":"Navid Negahban","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
