INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-toi-thu-sau', 'Kế Hoạch tối Thứ Sáu', 'Friday Night Plan', 'https://phimimg.com/upload/vod/20230915-1/5664e482950e02f507d0a346c71f51c1.jpg', 'https://phimimg.com/upload/vod/20230915-1/c0ba1fd0bea1aa37ef0a3e35306a5fbf.jpg', '<p>Khi mẹ đi công tác, hai anh em hay cãi vã đã bí mật tham dự bữa tiệc hot nhất năm trước khi mẹ trở về.</p>', 'Full', 1, 'single', 'completed', 26, 2023, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Babil Khan","avatar":""},{"name":"Amrith Jayan","avatar":""},{"name":"Juhi Chawla","avatar":""},{"name":"Medha Rana","avatar":""},{"name":"Aadhya Anand","avatar":""},{"name":"Ninad Kamat","avatar":""},{"name":"Aditya Jain","avatar":""},{"name":"Rishabh Joshi","avatar":""},{"name":"Mazda Taraporewala","avatar":""},{"name":"Vyom Vyas","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324259);
