INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-hoach-toi-thu-sau', 'Kế Hoạch tối Thứ Sáu', 'Friday Night Plan', 'kế hoạch tối thứ sáu friday night plan babil khan amrith jayan juhi chawla medha rana aadhya anand ninad kamat aditya jain rishabh joshi mazda taraporewala vyom vyas ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-anh-muoi-nam-trao-em-nua-doi', 'Cùng Anh Mười Năm, Trao Em Nửa Đời', 'Ten Years', 'https://phimimg.com/upload/vod/20230914-1/100e553b1185d2cc98ed517c128c522b.jpg', 'https://phimimg.com/upload/vod/20230914-1/dbad57f1ded5aee8646f22de6fe5dc78.jpg', '<p>Lin Yi Cheng xuất thân nghèo khó và trở thành phóng viên truyền hình như mong muốn sau khi tốt nghiệp. Anh dần dần trở thành trụ cột của nhóm mạng lưới truyền hình. Anh ấy có những nguyên tắc và điểm mấu chốt nhất định, đồng thời đã trải qua nhiều câu chuyện khác nhau của tuổi trẻ trong suốt chặng đường. Anh ấy rất lịch sự và có trách nhiệm với lòng tự trọng cao. Wang Yan, một phụ nữ có chỉ số IQ cao, một thợ đào vàng nhưng cũng là một tinh hoa chuyên nghiệp tự lập, sinh ra trong một gia đình nghèo. Với vẻ ngoài xinh đẹp, cô rất giỏi dựa vào sắc đẹp để lấy tài nguyên cho bản thân và giúp bạn bè xé bỏ &#39;mặt nạ đàn ông&#39;. Trong hành trình động viên và thấu hiểu lẫn nhau của Lin Yi Cheng, tình yêu lặng lẽ nảy sinh, nhưng đối mặt với hiện thực, anh chỉ có thể kiên nhẫn chịu đựng áp lực cuộc sống và tận hưởng nó. Ngoài ra, vì sự cống hiến và hiểu biết của Lin Yi Cheng đối với cuộc sống và công việc của Wang Yan, cô vô cùng cảm động, nhưng lại bị vướng mắc giữa hiện thực và tham vọng.</p>', '', 24, 'series', 'completed', 31, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yao","avatar":""},{"name":"Zhang Yaqin","avatar":""},{"name":"Dong Xuan","avatar":""},{"name":"Yuan Jiahuan","avatar":""},{"name":"Wen Li","avatar":""},{"name":"Zhao Xinghui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324260);
