INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-khong-noi-cung-hieu', 'Yêu Em Không Nói Cũng Hiểu', 'Love You Self-Evident', 'https://phimimg.com/upload/vod/20230914-1/a9b7af4f860ff7fcf85783114635f984.jpg', 'https://phimimg.com/upload/vod/20230914-1/5ca5f1ea34c83285d0f17d7e1efcb51c.jpg', '<p>Nhiều năm trước, Mặc Ninh Tịch rơi vào hoàn cảnh tuyệt vọng, không còn cách nào khác là phải bán mình. Kết quả là cô bị đứa em gái lôi kéo và người mẹ kế độc ác đuổi ra khỏi nhà và bị ép đưa ra nước ngoài. Sáu năm sau, cô trở lại với tư cách là một nhà thiết kế thời trang nổi tiếng với hai em bé dễ thương, gặp Li Xi Cheng, CEO đẹp trai và giàu có của tập đoàn Li, và đưa các con của cô vào mối quan hệ thứ hai.</p>', '', 20, 'series', 'completed', 31, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324260);
