INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-le-toi-da-yeu-roi', 'Có Lẽ Tôi Đã Yêu Rồi', 'Maybe This is Love', 'https://phimimg.com/upload/vod/20230914-1/1aca9573fe6ea88367e52122df7b562d.webp', 'https://phimimg.com/upload/vod/20230914-1/c852685228c2ece386b2c21f3a9864ed.png', '<p>Zhongli Xue của Trung tâm y tế Zhongli chịu ảnh hưởng từ cha mình, từ khi còn nhỏ anh đã coi tình yêu thương lớn lao và sự gắn bó với trái tim mình là nguyên tắc hành xử của mình. Tuy nhiên, khi cô lên bảy tuổi, cha cô đột ngột qua đời vì bệnh tật khi đang điều trị cho Chu Luyan, một thanh niên khuyết tật trong tổ chức, bệnh viện bị những kẻ phản bội vu khống và làm trì hoãn cơ hội điều trị của Chu Luyan, danh tiếng của nó giảm mạnh và không thể tiếp cận được. Để chấn hưng phòng khám y tế, Zhong Lixue đã không ngần ngại làm vệ sĩ cho Chu Luyan khi lớn lên. Không ngờ, trong cuộc chiến trí tuệ và lòng dũng cảm với thiếu gia vô tích sự, Zhong Lixue phát hiện ra rằng những lời chỉ trích mà phòng khám y tế phải chịu đựng hồi đó chỉ là một lời nói dối đã được lên kế hoạch từ lâu. kẻ thù, hóa ra cũng giống mình, thủ phạm và nạn nhân của sự dối trá. Vì vậy, đối mặt với sự an toàn của người khác và lợi ích cá nhân, Zhong Lixue kiên quyết lựa chọn đứng về phía Chu Luyan yếu đuối và chiến đấu chống lại thế lực tà ác.</p>', '', 12, 'series', 'completed', 30, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yan Ni","avatar":""},{"name":"Feifan Yu","avatar":""},{"name":"Fengyao Liu","avatar":""},{"name":"Er Wen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324260);
