INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('what-if-2023', 'What If', 'What If', 'https://phimimg.com/upload/vod/20230913-1/4da9f83cf83b6b9c3be6774af1c8c9d7.jpg', 'https://phimimg.com/upload/vod/20230913-1/8a4e88b4be385dec4d5cf56ba55e0b22.jpg', '<p>Mắc kẹt trong cơn bão khi đang hưởng tuần trăng mật trên đảo, cặp vợ chồng nhạc sĩ mới cưới nọ phải đối mặt với những sự thật phũ phàng có thể hủy hoại cuộc hôn nhân của họ.</p>', 'Full', 1, 'single', 'completed', 24, 2023, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Alessandra de Rossi","avatar":""},{"name":"JM de Guzman","avatar":""},{"name":"Chard Ocampo","avatar":""},{"name":"Ana Abad-Santos","avatar":""},{"name":"Nicole Omillo","avatar":""},{"name":"Angie Castrence","avatar":""},{"name":"Soliman Cruz","avatar":""},{"name":"Jett Pangan","avatar":""},{"name":"Sunshine Guimary","avatar":""},{"name":"Anna Luna","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324260);
