INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-marlowe', 'Thám Tử Marlowe', 'Marlowe', 'https://phimimg.com/upload/vod/20230913-1/ff5ec39fe3abc9ea93b5e2b3c873cb27.jpg', 'https://phimimg.com/upload/vod/20230913-1/35c73f25eb1616b9d0ae9fa8163ee104.jpg', '<p><span style="font-family: ">Dựa trên tác phẩm bán chạy &quot;The Black-Eyed Blonde&quot;, Marlowe lấy bối cảnh Bay City những năm 1930, là câu chuyện xoay quanh vị thám tử cùng tên được một tỉ phú thừa kế quyến rũ thuê để tìm người yêu cũ mất tích. Vụ mất tích là bước ngoặt đầu tiên trong một loạt các sự kiện gây hoang mang, và ngay sau đó Marlowe bị lôi kéo vào một cuộc điều tra án mạng cùng quyết tâm đưa tổ chức tội phạm ra ánh sáng.</span></p>', 'Full', 1, 'single', 'completed', 27, 2023, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Jessica Lange","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Ian Hart","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Daniela Melchior","avatar":""},{"name":"Patrick Muldoon","avatar":""},{"name":"Colm Meaney","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324260);
