INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trom-mo', 'Trộm Mộ', 'Lop Nor Tomb', 'https://phimimg.com/upload/vod/20230913-1/731ead75629b60d3db401e5eb48b3252.jpg', 'https://phimimg.com/upload/vod/20230913-1/f5c30ceed41b540bf6a7fca0a6d31480.jpg', '<p>Để giúp Shirley Yang tìm kiếm cha mình, Hu Bayi, Wang Pangzi và Shirley Yang cùng với Giáo sư Chen và những người khác bắt đầu cuộc hành trình tìm kiếm tàn tích của thành phố cổ Lop Nor. Trên đường đi, họ gặp phải vô số nguy hiểm, bao gồm lăng mộ núi lửa, chuột chũi khổng lồ, cơ chế tượng đá, v.v. Dù đã nỗ lực nhưng họ vẫn không thể tìm ra manh mối nào. Ngay khi mọi người chuẩn bị bỏ cuộc, thái độ của Chu Siyu đã khơi dậy sự nghi ngờ của Hu Bayi, và Sherly Yang đột nhiên biến mất, khiến con đường tìm kiếm thành phố cổ Lop cũng không còn bối rối nữa.</p>', 'Full', 1, 'single', 'completed', 28, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bai En","avatar":""},{"name":"Hu Xue''er","avatar":""},{"name":"Yang Dongqi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324260);
