INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-thuc-tinh', 'Quỷ Dữ Thức Tỉnh', 'The Last Voyage of the Demeter', 'null', 'https://phimimg.com/upload/vod/20230906-1/9a2c5c49c034fa6a99d4b0daf438efec.jpg', '<p>Một đoàn thủy thủ tham gia vào nhiệm vụ vận chuyển một “đơn hàng” bí ẩn từ Carpathia đến London trên con tàu Demeter huyền thoại. Hải trình tưởng chừng như đơn giản thế nhưng lại ẩn chứa một cơn ác mộng kinh hoàng khi “đơn hàng” họ vận chuyển đang dần thức tỉnh. Nỗi khiếp sợ chính thức mở ra khi một vài thủy thủ bắt đầu phát hiện những dấu hiệu bất thường trên tàu, sự ra đi hàng loạt của động vật, cho đến cái chết bí ẩn của người thủy thủ đã khiến cho chuyến hành trình đến London trở nên ám ảnh hơn bao giờ hết. Giờ đây, tất cả mọi người phải tranh giành sự sống với mọi giác quan để chống lại con quái vật khát máu đã thức tỉnh trên tàu – Dracula. Liệu họ có cập bến thành công? Hay kết cục chỉ còn là sự chết chóc và một con tàu vô chủ?</p>', 'Full', 1, 'single', 'completed', 34, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Corey Hawkins","avatar":""},{"name":"Aisling Franciosi","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Chris Walley","avatar":""},{"name":"Jon Jon Briones","avatar":""},{"name":"Stefan Kapičić","avatar":""},{"name":"Martin Furulund","avatar":""},{"name":"Nikolai Nikolaeff","avatar":""},{"name":"Woody Norman","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324260);
