INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie', 'Barbie', 'Barbie', 'null', 'https://phimimg.com/upload/vod/20230906-1/7433612b1129b29f33b8adb004e2aef6.jpg', '<p>BARBIE sẽ được nhào nặn và chắp bút bởi nữ đạo diễn kiêm biên kịch từng nhận nhiều Đề cử Tượng vàng Oscar – Greta Grewig. Hai nhân vật chính Barbie và Ken sẽ được hóa thân bởi nữ diên viên Margot Robbie và nam thần Ryan Gosling, hứa hẹn sẽ tạo nên “chemistry” đáng yêu giữa hai nhân vật búp bê nổi tiếng thế giới.</p>', 'Full', 1, 'single', 'completed', 33, 2023, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Margot Robbie","avatar":""},{"name":"Ryan Gosling","avatar":""},{"name":"America Ferrera","avatar":""},{"name":"Kate McKinnon","avatar":""},{"name":"Ariana Greenblatt","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Issa Rae","avatar":""},{"name":"Alexandra Shipp","avatar":""},{"name":"Emma Mackey","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324260);
