INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('barbie', 'Barbie', 'Barbie', 'barbie barbie margot robbie ryan gosling america ferrera kate mckinnon ariana greenblatt michael cera will ferrell issa rae alexandra shipp emma mackey ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-anh-chay-ve-phia-em', 'Khi Anh Chạy Về Phía Em', 'When I Fly Towards You', 'https://phimimg.com/upload/vod/20230929-1/e7e0790c8f05fe27a758d37bf5c1fd90.jpg', 'https://phimimg.com/upload/vod/20230929-1/a6110983f8de490e116383020adc4662.jpg', '<p>Vào đầu mùa thu năm 2012, một trường trung học phổ thông trọng điểm của thành phố Z mở kì thi tuyển học sinh mới, Tô Tại Tại đã trúng tuyển và được bước chân vào ngôi trường. Vào ngày đầu tiên đi học, Trương Lục Nhượng đã thu hút sự chú ý của Tô Tại Tại, khiến cô đã “Yêu ngay từ cái nhìn đầu tiên”. Nhờ sự ấm áp như ánh mặt trời của mình, Tô Tại Tại đã giúp Trương Lục Nhượng thoát khỏi sự tự ti. Còn Tô Tại Tại, người luôn đi theo số đông mà không biết kế hoạch, mục tiêu của mình là gì, dưới tác động của học bá Trương Lục Nhượng, cô dần dần hiểu ra cách lập kế hoạch và mục tiêu cho cuộc đời mình. Câu chuyện cho ta thấy ý nghĩa của sự thiếu hiểu trong tuổi trẻ và dần từ từ tiến đến một tương lai tươi sáng, tốt đẹp hơn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 41, 2023, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Yi Ran","avatar":""},{"name":"Miaoyi Zhang","avatar":""},{"name":"ZhiNan Jiang","avatar":""},{"name":"Bian Tianyang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324260);
