INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-ve-vox-machina-phan-1', 'Truyền Thuyết về Vox Machina (Phần 1)', 'The Legend Of Vox Machina (Season 1)', 'https://phimimg.com/upload/vod/20240409-1/f6e9952b7d0d32cc5cbee5f6999eb2c6.jpg', 'https://phimimg.com/upload/vod/20240409-1/677479d4c5ad65ead32f823ad7cc258b.jpg', '<p>Họ ồn ào, họ giễu cợt, họ sai khiến trở thành lính đánh thuê. Vox Machina quan tâm đến tiền dễ dàng và bia rẻ hơn là thực sự bảo vệ vương quốc. Nhưng khi vương quốc bị đe dọa bởi cái ác, phi hành đoàn huyên náo này nhận ra rằng họ là những người duy nhất có khả năng khôi phục lại công lý. Những gì bắt đầu như một ngày trả lương đơn giản bây giờ là câu chuyện nguồn gốc đằng sau những anh hùng mới nhất của Exandria.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 48, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laura Bailey","avatar":""},{"name":"Taliesin Jaffe","avatar":""},{"name":"Ashley Johnson","avatar":""},{"name":"Liam O''Brien","avatar":""},{"name":"Marisha Ray","avatar":""},{"name":"Travis Willingham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324260);
