INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-thuong-khung-phan-5', 'Đấu Phá Thương Khung (Phần 5)', 'Fights Break Sphere (Season 5)', 'https://phimimg.com/upload/vod/20240822-1/27bfb98b2cf23111b0c11e82b0483fc4.jpg', 'https://phimimg.com/upload/vod/20240822-1/58a4a1135f235b376641c5171d410b04.jpg', '<p>Phim Đấu Phá Thương Khung: Chuyển thể từ tiểu thuyết cùng tên của tác giả Thiên Tàm Thổ Đậu. &nbsp;Tiêu Viêm là thiên tài tu luyện đấu khí của nhà họ Tiêu, 11 tuổi đã đột phá Thập Đoạn Đấu Chi Khí, trở thành đấu thủ trẻ tuổi nhất của gia tộc suốt trăm năm qua. Nhưng đến năm 12 tuổi, Tiêu Viêm bất ngờ mất đi khả năng tu luyện, chỉ còn lại Tam Đoạn Đấu Chi Khí. Trong 3 năm sau đó, nhà họ Tiêu cũng liên tiếp gặp nhiều bất trắc. &nbsp;Đúng vào lúc Tiêu Viêm tuyệt vọng nhất, một linh hồn xuất hiện từ trong chiếc nhẫn trên tay Tiêu Viêm, mở ra trước mắt Tiêu Viêm một cánh cửa hoàn toàn mới. Dưới sự giúp đỡ của Dược lão, Tiêu Viêm đã hồi phục và nâng cao được công lực của mình, đánh bại Nạp Lan Yên Nhiên khi giao hẹn ba năm đến. &nbsp;Nhưng không may là cha Tiêu Viêm lại bị Vân Lam tông bắt đi, Tiêu Viêm lại bắt đầu cuộc hành trình nhiều thử thách nhằm cứu thoát cha mình…</p>', 'Tập 207', 500, 'hoathinh', 'ongoing', 78, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"劉三木","avatar":""},{"name":"张沛","avatar":""},{"name":"刘雨轩","avatar":""},{"name":"蘇婉","avatar":""},{"name":"祝俊","avatar":""},{"name":"陳奕雯","avatar":""},{"name":"楊夢露","avatar":""},{"name":"文曉依","avatar":""},{"name":"閻麼麼","avatar":""},{"name":"夏磊","avatar":""},{"name":"Dian Tao","avatar":""},{"name":"张韦","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324260);
