INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-pha-thuong-khung-phan-5', 'Đấu Phá Thương Khung (Phần 5)', 'Fights Break Sphere (Season 5)', 'đấu phá thương khung (phần 5) fights break sphere (season 5) 劉三木 张沛 刘雨轩 蘇婉 祝俊 陳奕雯 楊夢露 文曉依 閻麼麼 夏磊 dian tao 张韦 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-mo-2022', 'Thần Mộ', 'Tomb Of Fallen Gods', 'https://phimimg.com/upload/vod/20251124-1/74ab8505711d0ca1a57d85c0a13fb19f.jpg', 'https://phimimg.com/upload/vod/20251124-1/b20ca22d56f6ea0c41cdafea81018a64.jpg', '<p>Thần Mộ kể về chàng thiếu niên tên Thần Nam được hồi sinh sau 1 vạn năm tại Thần Ma Lăng Viên. Thần Ma Lăng Viên nằm ở chính giữa Thiên Nguyên đại lục. Đây là nơi an táng những nhân vật mạnh nhất trong lịch sử xuyên suốt vũ trụ từ thời hồng hoang. Nơi này bền vững cùng thiên địa cao xanh. Khu mộ phần được phân loại theo cấp độ mạnh yếu, càng tiến vào sâu bên trong thì càng có nhiều mộ của những nhân vật cực mạnh. Mỗi ngôi mộ, nếu không phải của thần linh thì cũng là của yêu ma thượng cổ. Đây chính là nơi thần thánh và ma quỷ yên nghỉ ngàn thu. &nbsp;Sau khi tỉnh lại, nam chính Thần Nam sẽ trải qua hành trình tìm lại bản thân, biết được nguyên nhân vì sao mình lại xuất hiện tại Thần Ma Lăng Viên và làm thế nào để tìm được Vũ Hinh – người con gái mình yêu.</p>', 'Tập 93', 120, 'hoathinh', 'ongoing', 49, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"张思淼","avatar":""},{"name":"余可婧","avatar":""},{"name":"Si Xi","avatar":""},{"name":"魏茹晨","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["神墓年番","God''s Tomb","Sepultura Divina","Túmulo dos Deuses","Tomb of Fallen Gods","Thần Mộ","神墓"]', 1784690324260);
