INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khanh-khanh-nhat-thuong-tan-xuyen-nhat-thuong', 'Khanh Khanh Nhật Thường (Tân Xuyên Nhật Thường)', 'New Life Begins', 'https://phimimg.com/upload/vod/20250617-1/b982ecf94f8a976a4c55bb108ddf55b7.jpg', 'https://phimimg.com/upload/vod/20250617-1/4c3d370053e63ebdfb68b1c8d1c9f748.jpg', '<p>Khanh Khanh Nhật Thường (Tân Xuyên Nhật Thường, New Life Begins) kể về câu chuyện của các cô gái đến từ trời nam đất bắc vì một mối liên hôn mà tề tựu tại Tân Xuyên. Lục thiếu gia ở Tân Xuyên là Doãn Tranh chỉ muốn cố gắng thi rớt, bất ngờ kết mối duyên với Lý Vi đang trải qua những ngày nhàn nhã ở quê nhà , cùng nhau mở ra một cuộc sống mới xảy ra đủ loại tình huống dở khóc dở cười. Theo Doãn Tranh khai phủ, thượng triều, hai người dần dần nảy xinh tình cảm, tâm ý tương thông, chung tay trải qua bốn mùa ba bữa, cùng trưởng thành với các sư huynh muội có tính cách vận mệnh khác nhau, cùng nhau viết nên cuộc sống thường ngày ấm áp ở đại gia đình Tân Xuyên.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 82, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Kính Đình","avatar":""},{"name":"Điền Hi Vi","avatar":""},{"name":"Trần Tiểu Vân","avatar":""},{"name":"Lưu Lệnh Tư","avatar":""},{"name":"Lưu Quan Lân","avatar":""},{"name":"Lưu Mĩ Hàm","avatar":""},{"name":"Trương Hiểu Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["New.Life.Begins","清穿日常","青川日常","新川日常","川內相親","卿卿日常"]', 1784690324260);
