INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-17-ki-la-cua-toi', 'Tuổi 17 Kì Lạ Của Tôi', 'So Young (My Unimaginable 17)', 'https://phimimg.com/upload/vod/20260704-1/a2ed976745a6c8736171b9fa17e05c0c.jpg', 'https://phimimg.com/upload/vod/20260704-1/735467a41a37c55fb088a2baa356aafc.jpg', '<p>An Tĩnh là một nữ sinh trung học lầm lì và tự ti, muốn dựa vào việc sáng tác tiểu thuyết để tự chữa khỏi vết thương trong lòng mình. Câu chuyện về ba nữ chính cùng những người bạn với muôn vàn tính cách khác nhau trong tiểu thuyết cũng phản ánh quá trình trưởng thành của chính An Tĩnh. Sau khi viết xong cuốn tiểu thuyết, An Tĩnh chấp nhận đón lấy khiếm khuyết của cuộc đời, vĩnh biệt tuổi mười bảy của mình mà không một chút hối tiếc.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 44, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tử Mộc","avatar":""},{"name":"Sư Minh Trạch","avatar":""},{"name":"Trần Phẩm Diên","avatar":""},{"name":"Đại Siêu","avatar":""},{"name":"Thời An","avatar":""},{"name":"Vương Sở Du","avatar":""},{"name":"Vương Gia Tuệ","avatar":""},{"name":"Tống Nguyên","avatar":""},{"name":"Vương Nặc Nhất","avatar":""},{"name":"Khổng Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我奇怪的17岁","再见，十七岁","بدرود، ۱۷ سالگی","با ۱۷ سالگی من خداحافظی کن","So Young","I''m a Strange 17"]', 1784690324260);
