INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuoi-17-ki-la-cua-toi', 'Tuổi 17 Kì Lạ Của Tôi', 'So Young (My Unimaginable 17)', 'tuổi 17 kì lạ của tôi so young (my unimaginable 17) trương tử mộc sư minh trạch trần phẩm diên đại siêu thời an vương sở du vương gia tuệ tống nguyên vương nặc nhất khổng lâm 我奇怪的17岁 再见，十七岁 بدرود، ۱۷ سالگی با ۱۷ سالگی من خداحافظی کن so young i''m a strange 17', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-quy-co-say-xin-phan-2', 'Những Quý Cô Say Xỉn (Phần 2)', 'Work Later, Drink Now (Season 2)', 'https://phimimg.com/upload/vod/20260703-1/0a65e2e0c85c06cdde94c02a538ade07.jpg', 'https://phimimg.com/upload/vod/20260703-1/9afefd8762993c10c58b471b2b5370c1.jpg', '<p>Là những phụ nữ độc thân, độc lập và ngoài 30, ban ngày So Hee, Ji Yeon và Ji Gu vùi đầu vào công việc, nhưng khi màn đêm buông xuống họ cùng tụ tập để thưởng thức cốc bia lạnh, kết thúc một ngày bận rộn. Đồng hành cùng họ là anh chàng PD Kang Buk Gu hài hước. Tình bạn giữa ba cô gái và Buk Gu sẽ được khắc họa rõ nét qua những buổi nhậu tâm tình, động viên nhau trước mọi vấn đề trong cuộc sống.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 46, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sun-bin","avatar":""},{"name":"Han Seon-hwa","avatar":""},{"name":"Jung Eun-ji","avatar":""},{"name":"Choi Si-won","avatar":""},{"name":"Yoo In-young","avatar":""},{"name":"Joo Eo-jin","avatar":""},{"name":"Yoon Shi-yoon","avatar":""},{"name":"Jung Hae-na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["술꾼도시여자들"]', 1784690324260);
