INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-truyen', 'Gia Truyền', 'Legacy', 'https://phimimg.com/upload/vod/20260630-1/99ca84246265215812d2c8c8d4c85385.jpg', 'https://phimimg.com/upload/vod/20260630-1/20b59e96e752a46a16959900505a9892.jpg', '<p>Lấy bối cảnh Thượng Hải cuối những năm 1920, phim xoay quanh gia tộc họ Dịch – chủ của Tinh Hoa Bách Hóa. Khi người đứng đầu gia tộc phải chọn người kế nghiệp, ba chị em Dịch Chung Linh, Dịch Chung Ngọc và Dịch Chung Tú từ đối đầu dần học cách đoàn kết để bảo vệ gia nghiệp giữa thời cuộc đầy biến động, đồng thời góp sức cho sự nghiệp cứu nước trong thời kỳ chiến tranh.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 33, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Lam","avatar":""},{"name":"Hàn Canh","avatar":""},{"name":"Ngô Cẩn Ngôn","avatar":""},{"name":"Nhiếp Viễn","avatar":""},{"name":"Trương Nam","avatar":""},{"name":"Trịnh Khải","avatar":""},{"name":"Lưu Quân","avatar":""},{"name":"Miêu Phố","avatar":""},{"name":"Trương Dật Kiệt","avatar":""},{"name":"Lưu Nhuế Lân","avatar":""},{"name":"Trương Dật Luân","avatar":""},{"name":"Phan Bân Long","avatar":""},{"name":"Trương Dịch","avatar":""},{"name":"Hà Phụng Thiên","avatar":""},{"name":"Vương Khả Như","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El Legado de la Grandeza","El Legado","權力攻略之家族傳奇","传家"]', 1784690324260);
