INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-nguyen-thuy-phan-2', 'Vùng Đất Nguyên Thuỷ (Phần 2)', 'La Brea (Season 2)', 'https://phimimg.com/upload/vod/20260630-1/465e8f2c1986a25ee9c085a835ebbbe6.jpg', 'https://phimimg.com/upload/vod/20260630-1/14d351fb7e10f9530759fbc25694ab27.jpg', '<p>Một cuộc phiêu lưu sử thi bắt đầu khi một hố sụt khổng lồ bất ngờ mở ra ngay giữa lòng thành phố Los Angeles, kéo theo hàng trăm người và các tòa nhà xuống độ sâu thăm thẳm. Những người không may rơi xuống nhận ra mình đang ở trong một vùng đất nguyên thủy đầy rẫy nguy hiểm và bí ẩn, nơi họ không còn lựa chọn nào khác ngoài việc phải đoàn kết lại để sinh tồn. Trong khi đó, phần còn lại của thế giới tuyệt vọng tìm kiếm câu trả lời cho những gì đã xảy ra. Trên hành trình đi tìm lời giải ấy, một gia đình bị chia cắt bởi thảm họa này sẽ phải giải mã những bí mật của sự kiện không thể lý giải trên để tìm đường đoàn tụ với nhau.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 48, 2022, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Eoin Macken","avatar":""},{"name":"Chiké Okonkwo","avatar":""},{"name":"Zyra Gorecki","avatar":""},{"name":"Rohan Mirchandaney","avatar":""},{"name":"Lily Santiago","avatar":""},{"name":"Josh McKenzie","avatar":""},{"name":"Jon Seda","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["加州异世界","Sinkhöhle","라 브레아","ลาเบรีย ผจญภัยโลกดึกดำบรรพ์","La Brea (2021)","La Brea"]', 1784690324260);
