INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thoi-dai-vang-son-phan-1', 'Thời Đại Vàng Son (Phần 1)', 'The Gilded Age (Season 1)', 'thời đại vàng son (phần 1) the gilded age (season 1) carrie coon morgan spector louisa jacobson denée benton taissa farmiga harry richardson blake ritson simon jones jack gilpin ben ahlers kelley curran celia keenan-bolger ben lamb debra monk kristine nielsen kelli o''hara patrick page the gilded age : la loi du vieux new york عصر طلایی دوره طلایی 더 길디드 에이지 the gilded age', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-do-o-dau-do', 'Ai Đó Ở Đâu Đó', 'Somebody Somewhere', 'https://phimimg.com/upload/vod/20260630-1/2c136462560ff1c5395f65d1ccdb067f.jpg', 'https://phimimg.com/upload/vod/20260630-1/09cff3bd374dc332a67937c5657b7adb.jpg', '<p>Bề ngoài Sam là một người Kansan thực thụ nhưng bên trong tất cả đều phải vật lộn để phù hợp với khuôn mẫu quê hương. Khi cô ấy vật lộn với mất mát và chấp nhận, ca hát là ân huệ cứu rỗi của Sam và dẫn dắt cô ấy vào cuộc hành trình khám phá bản thân và một cộng đồng những người bên ngoài không phù hợp nhưng không bỏ cuộc, cho thấy rằng việc tìm thấy con người của bạn và tìm thấy giọng hát của bạn, là có khả năng. Bất cứ nơi nào. Một nơi nào đó.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 34, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bridget Everett","avatar":""},{"name":"Jeff Hiller","avatar":""},{"name":"Mary Catherine Garrison","avatar":""},{"name":"Murray Hill","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Quelqu''un quelque part","Somebody Somewhere"]', 1784690324260);
