INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-ke-hoach-quai-vat-phan-2', 'Gấu Boonie: Kế Hoạch Quái Vật (Phần 2)', 'Boonie Bears: Monster Plan (Season 2)', 'https://phimimg.com/upload/vod/20260429-1/2ff0ebae4bd61b77070e0bad2366fd6c.jpg', 'https://phimimg.com/upload/vod/20260429-1/fe985f039c8e0b6df6a89bf41ca86b88.jpg', '<p>Thất bại sau kế hoạch đầu tiên, tiến sĩ Rex Vector trở lại với những phát minh công nghệ tinh vi và nguy hiểm gấp bội. Lần này, các thiết bị hấp thụ năng lượng được nâng cấp khiến mọi động vật đứng trước nguy cơ bị tước đoạt hoàn toàn bản năng sinh tồn. Anh em gấu Boonie và Vick một lần nữa phải hợp lực, không chỉ bằng sức mạnh mà còn bằng trí tuệ, để phá tan âm mưu của quân đoàn rô-bốt mới nhằm bảo vệ khu rừng yêu quý.</p>', 'Tập 40', 52, 'hoathinh', 'ongoing', 43, 2022, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Wei","avatar":""},{"name":"Zhang Bingjun","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"Yingying Miu","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["熊出没之探险日记3","熊出没之怪兽计划"]', 1784690324260);
