INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-va-anh-vua-hay-dung-luc', 'Thời Gian Và Anh, Vừa Hay Đúng Lúc', 'Time And Him Are Just Right', 'https://phimimg.com/upload/vod/20260628-1/92518d07d2e36811c6f89983c97439f2.jpg', 'https://phimimg.com/upload/vod/20260628-1/6562b7ae09a745bc05c446567eefb59e.jpg', '<p>Bộ phim là câu chuyện về cô thiếu nữ Lâm Tích bướng bỉnh đáng yêu cố ý tiếp cận thánh học giỏi nham hiểm Quý Quân Hành. Từ &quot;theo đuôi&quot; rồi dần trở thành bạn bè, hai người nảy sinh tình cảm với nhau, cùng nhau trưởng thành. Trong khoảng thời gian ấy, họ không những có thêm nhiều người bạn tốt mà còn thực hiện được ước mơ của chính mình, thể hiện giá trị bản thân trong cuộc sống.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 40, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lư Dục Hiểu","avatar":""},{"name":"Ngô Tuấn Đình","avatar":""},{"name":"Lư Tuấn Kiệt","avatar":""},{"name":"Tiêu Vũ","avatar":""},{"name":"Đổng Tử Phàm","avatar":""},{"name":"Lê Minh Húc","avatar":""},{"name":"Hồ Gia Hân","avatar":""},{"name":"Trương Hằng Minh","avatar":""},{"name":"Trương Giác","avatar":""},{"name":"Lý Giai Úy","avatar":""},{"name":"Hám Tử Nghĩa","avatar":""},{"name":"Ngô Địch Phi","avatar":""},{"name":"Lan Hi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Tempo e Ele Estão Certos","时光与他，恰是正好","Shi Guang Yu Ta, Qia Shi Zheng Hao","時光與他，恰是正好","Meeting You Is Luckiest Thing to Me","Time Is Just Right With Him"]', 1784690324260);
