INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dieu-toi-chua-tung-phan-3', 'Những Điều Tôi Chưa Từng (Phần 3)', 'Never Have I Ever (Season 3)', 'https://phimimg.com/upload/vod/20240118-1/b713635a56dfdd8a1f27657a3eefe52e.jpg', 'https://phimimg.com/upload/vod/20240118-1/5431a1e8bb9663c974eac997f57a039e.jpg', '<p>Có thể Devi và bạn bè cuối cùng đã không còn độc thân nữa, nhưng họ sắp học được rằng các mối quan hệ sẽ đi cùng với cả một hành trình tự khám phá – và đủ mọi rắc rối.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 30, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maitreyi Ramakrishnan","avatar":""},{"name":"Poorna Jagannathan","avatar":""},{"name":"Richa Moorjani","avatar":""},{"name":"Ranjita Chakraverty","avatar":""},{"name":"John McEnroe","avatar":""},{"name":"Ramona Young","avatar":""},{"name":"Lee Rodriguez","avatar":""},{"name":"Megan Suri","avatar":""},{"name":"Jaren Lewison","avatar":""},{"name":"Darren Barnet","avatar":""},{"name":"Christina Kartchner","avatar":""},{"name":"Common","avatar":""},{"name":"Adam Shapiro","avatar":""},{"name":"Niecy Nash","avatar":""},{"name":"Sendhil Ramamurthy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324260);
