INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ruby-va-gieng-than-phan-2', 'Ruby Và Giếng Thần (Phần 2)', 'Ruby And The Well (Season 2)', 'https://phimimg.com/upload/vod/20260626-1/f2260fcf3142a267f4b772cc89ce61a9.jpg', 'https://phimimg.com/upload/vod/20260626-1/0d2376c2ff2e81b65d7e927cfa2a2f9d.jpg', '<p>Khi cha cô được thừa kế một vườn cây ăn quả hoang vu, Ruby O&#39;Reilly đã tình cờ phát hiện ra một chiếc giếng thần kỳ. Cô được chọn để trở thành &quot;người bảo hộ&quot; mới của giếng, và giờ đây, trọng trách biến những điều ước chưa thành hiện thực của mọi người thành lòng thực tế đang đè nặng lên vai cô cùng hai người bạn thân Mina và Sam.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 57, 2022, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Zoe Wiesenthal","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Espoirs secrets","Ruby & the Well","Ruby and the Well"]', 1784690324260);
