INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-hoi-su-ao-den', 'Triệu Hồi Sư Áo Đen', 'Black Summoner / Kuro No Shoukanshi', 'https://phimimg.com/upload/vod/20260625-1/b4ab309ba934a1b273fa95e07ea6b31b.jpg', 'https://phimimg.com/upload/vod/20260625-1/c12421d9f1f6798f9996e31534bed924.jpg', '<p>Tự dưng thức dậy ở một nơi xa lạ, và không nhớ được gì quá khứ của tiền kiếp. Kelvin biết được anh đã đánh đổi những kí ức đó lấy sức mạnh mới trong qua trình đầu thai của mình. Kelvin tiến ra đương đầu với thế giới với vai trò Triệu hồi sư, và người đầu tiên cùng đồng hành với anh trên con đường khám phá thế giới là nữ thần Melfina - người đã đưa anh đến với thế giới này. Kelvin phải đương đầu hết đối thủ mạnh này đến đối thủ mạnh khác, từ &quot;Ác linh kị sĩ của thành cổ&quot; cho đến &quot;Ác ma ẩn trong hang động&quot;. Anh, một kẻ nghiện chiến đấu khoác trên mình cái áo choàng đen cùng đồng hành với đồng đội trên con đường thăng tiến lên làm &quot;Anh hùng&quot;.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 27, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Koki Uchiyama","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Randhi","avatar":""},{"name":"Yosuke Akimoto","avatar":""},{"name":"Minori Suzuki","avatar":""},{"name":"Yume Miyamoto","avatar":""},{"name":"Konomi Inagaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Black Summoner",