INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-trai-khung-long-phan-2', 'Trang Trại Khủng Long (Phần 2)', 'Dino Ranch (Season 2)', 'https://phimimg.com/upload/vod/20260616-1/710a3488a18f99586de84cf41c4fcee9.jpg', 'https://phimimg.com/upload/vod/20260616-1/683036fef3ed100df643303484cde421.jpg', '<p>Dino Ranch theo chân những cuộc phiêu lưu đầy thú vị của gia đình Cassidy khi họ cùng nhau trải nghiệm cuộc sống trong một bối cảnh giả tưởng thời &quot;tiền viễn tây&quot; hoang dã, nơi các loài khủng long vẫn còn roam tự do trên mặt đất. Trong quá trình học hỏi các kỹ năng để trở thành những mục đồng thực thụ, các bạn nhỏ không chỉ khám phá ra niềm vui của cuộc sống trang trại mà còn được dấn thân vào thế giới tự nhiên bao la để vượt qua những thử thách bất ngờ.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 41, 2022, 'Thuyết Minh', 'FHD', 'Canada', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["恐龙牧场","Dino Ranch"]', 1784690324260);
