INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-dong-mau-anh-hung-heros-a-moitie', 'Nửa Dòng Máu Anh Hùng (Héros à moitié)', '50/50 Heroes', 'https://phimimg.com/upload/vod/20260615-1/7ec0b50e6a10ae08dd025390e5b82a98.jpg', 'https://phimimg.com/upload/vod/20260615-1/f7116e73bfb784e64aaa3de89b44dd22.jpg', '<p>Hai anh em cùng cha khác mẹ (hoặc cùng mẹ khác cha) là Mo và Sam tình cờ phát hiện ra rằng họ được thừa kế một vài năng lượng siêu nhiên từ người bà cố tổ của mình — người từng có một mối tình chớp nhoáng với một siêu anh hùng từ thuở xa xưa.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 36, 2022, 'Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Thomas Sagols","avatar":""},{"name":"Fanny Bloc","avatar":""},{"name":"Adeline Chetail","avatar":""},{"name":"Emmanuel Curtil","avatar":""},{"name":"Kerstin Julia Dietrich","avatar":""},{"name":"Benjamin Bollen","avatar":""},{"name":"Cathy Cerda","avatar":""},{"name":"Emmanuel Garijo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Наполовина герои","雙拼英雄","Poloviční superhrdinové","Héroes y hermanos","Fele-Fele hősök","Eroi a metà","ハーフ･ヒーロー","Herosi pół na pół","Eroi în jumătate","Poloviční hrdinovia","Nửa Dòng Máu Anh Hùng","Héros à moitié"]', 1784690324260);
