INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('drstone-ngoai-truyen-dr-stone-ryuusui', 'DR.STONE: Ngoại Truyện (Dr. Stone: Ryuusui)', 'Dr. Stone: Stone Wars', 'https://phimimg.com/upload/vod/20240403-1/d84517ce35d4bf3073cfc7412ef66467.jpg', 'https://phimimg.com/upload/vod/20240403-1/4d781e031f293172de1ca67cd67ac48d.jpg', '<p>Senkuu đã thực hiện mục tiêu của mình là mang lại thành tựu hai triệu năm của loài người và hồi sinh toàn bộ những người đã biến thành tượng đá. Tuy nhiên, một người đàn ông đã cản đường anh ta: Tsukasa Shishiou, người tin rằng chỉ những người khỏe mạnh nhất trong số những người đã hóa đá mới được hồi sinh. Khi tuyết tan và mùa xuân đến gần, Senkuu và các đồng minh của mình ở Làng Ishigami đã hoàn thành việc chuẩn bị cho cuộc tấn công vào Đế chế Tsukasa. Với một mẫu điện thoại di động được tái sáng tạo, Vương quốc Khoa học đã sẵn sàng khởi động kế hoạch mới nhất của mình để chiêu mộ một số lượng lớn quân đội của Tsukasa về phe của họ. Tuy nhiên, đó là một cuộc chạy đua với thời gian; Mỗi ngày Vương quốc Khoa học dành để hoàn thiện các phát minh của họ, đế chế này nhanh chóng phát triển về số lượng. Đoàn tụ với những người bạn cũ và có được những đồng minh mới, Senkuu và Vương quốc Khoa học phải ngăn chặn lực lượng của Tsukasa để hoàn thành mục tiêu khôi phục nhân loại và tất cả các tác phẩm. Với việc hai bên đều theo đuổi thế giới lý tưởng của mình, Stone Wars giờ đã bắt đầu!</p>', 'Hoàn Tất (2/2)', 2, 'hoathinh', 'completed', 35, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324260);
