INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-tron-hoc', 'Thần Thám Trốn Học', 'Detective Chen', 'https://phimimg.com/upload/vod/20260607-1/985fcd44cab4ae60d0beb5e90cdf13bf.jpg', 'https://phimimg.com/upload/vod/20260607-1/8f4677665c1cbd1d71d0087e3072beb2.jpg', '<p>Một vụ giết người kỳ lạ xảy ra ở trường trung học St. Martin. Hà Mạn Quân, con trai của Bộ trưởng Bộ Quân sự và Chính trị đã chết một cách kỳ lạ. Viên cảnh sát Trần Hổ nhận nhiệm vụ và bí mật điều tra sự thật trong trường. Khuôn viên tưởng chừng yên bình lại ngấm ngầm dậy sóng, thầy trò chia bè kết phát, nhưng lại có thể cùng nhau chống lại kẻ thù bên ngoài, người ta nghi ngờ người bạn gái bị bắt từng báo cảnh sát bắt Hà Mạn Quân vì tội cưỡng hiếp. Người đàn ông đeo mặt nạ với thân thủ nhanh nhẹn, những tranh chấp dai dẳng của xã hội đen, cô giáo dịu dàng quyến rũ, và học sinh xinh đẹp đáng thương, mối quan hệ giữa họ và vụ án giết người là gì? Với những nỗ lực của Trần Hổ, bí mật ẩn giấu cuối cùng đã được tiết lộ, nhưng vụ án ngày càng trở nên phức tạp và khó hiểu, mạng người hóa ra chỉ là phần nổi của tảng băng chìm, và sự thật thực sự chỉ ra một thứ khác.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ashton Chen","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Liu Tianzuo","avatar":""},{"name":"Norman Tsui Siu-Keung","avatar":""},{"name":"Steven Hao","avatar":""},{"name":"Yang Qianlong","avatar":""},{"name":"Zhang Haoyu","avatar":""},{"name":"Jiang Zhongwei","avatar":""},{"name":"Zhu Haiyu","avatar":""},{"name":"Guo Ziheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Mountain.Porter.2022","逃学神探"]', 1784690324260);
