INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pennyworth-nguon-goc-quan-gia-cua-nguoi-doi-phan-3', 'Pennyworth: Nguồn Gốc Quản Gia Của Người Dơi (Phần 3)', 'Pennyworth: The Origin of Batman''s Butler (Season 3)', 'https://phimimg.com/upload/vod/20260531-1/081794eeb2702367f2a8413e5e94d8ed.jpg', 'https://phimimg.com/upload/vod/20260531-1/ca8b815b41daa8189d4260efdc27bffe.jpg', '<p>Trước khi trở thành vị quản gia trầm tĩnh của Người Dơi, Alfred Pennyworth đã có một thời tuổi trẻ cực kì sôi nổi trong vai trò một thám tử chuyên lật tẩy những âm mưu to lớn tại nước Anh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 22, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jack Bannon","avatar":""},{"name":"Ben Aldridge","avatar":""},{"name":"Emma Paetz","avatar":""},{"name":"Ryan Fletcher","avatar":""},{"name":"Dorothy Atkinson","avatar":""},{"name":"Ramon Tikaram","avatar":""},{"name":"Simon Manyonda","avatar":""},{"name":"Harriet Slater","avatar":""},{"name":"Paloma Faith","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Pennyworth: A Origem de Alfred","Pennyworth","PENNYWORTH ペニーワース","PENNYWORTH/ペニーワースバットマンの右腕になる男","Пенніуорт","Pennyworth: The Origin of Batman''s Butler"]', 1784690324260);
