INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-kien-johnny-va-amber-phien-toa-tai-my', 'Vụ Kiện Johnny Và Amber: Phiên Tòa Tại Mỹ', 'Johnny vs Amber: The US Trial', 'https://phimimg.com/upload/vod/20260531-1/f8ec8308a514909bd7e077ce1de9c6a7.jpg', 'https://phimimg.com/upload/vod/20260531-1/ed0264810e589a4aeca47f761aa20a79.jpg', '<p>Vụ kiện với vợ cũ Amber Heard của nam tài tử Johnny Depp chứa đựng nhiều tình tiết căng thẳng nhưng không kém phần hài hước với chiến thắng lần này dành cho Johnny.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 16, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Sasha Wass","avatar":""},{"name":"Patrick Johnson","avatar":""},{"name":"Vanessa Paradis","avatar":""},{"name":"Traci Lords","avatar":""},{"name":"Kate Moss","avatar":""},{"name":"Pamela Romanowsky","avatar":""},{"name":"Paul Barresi","avatar":""},{"name":"Dylan Howard","avatar":""},{"name":"Minnie Stephenson","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Johnny vs Amber: The U.S. Trial","Johnny vs Amber: The US Trial"]', 1784690324260);
