INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-kien-johnny-va-amber-phien-toa-tai-my', 'Vụ Kiện Johnny Và Amber: Phiên Tòa Tại Mỹ', 'Johnny vs Amber: The US Trial', 'vụ kiện johnny và amber: phiên tòa tại mỹ johnny vs amber: the us trial johnny depp amber heard sasha wass patrick johnson vanessa paradis traci lords kate moss pamela romanowsky paul barresi dylan howard minnie stephenson johnny vs amber: the u.s. trial johnny vs amber: the us trial', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-luyen-thanh-than', 'Bách Luyện Thành Thần', 'Apotheosis', 'https://phimimg.com/upload/vod/20260325-1/4b4ec9d8f1d7a4f263c1e73c51abac47.jpg', 'https://phimimg.com/upload/vod/20260325-1/3d6c40ac7e223fe989e8c2f3ae1b7671.jpg', '<p>La Chinh vốn là thiếu gia chủ của La gia – một gia tộc lớn mạnh bậc nhất ở Đông Vực, từ nhỏ đã có tài năng kiệt xuất. Nhưng từ khi cha hắn qua đời, gia tộc nội loạn, hắn đã bị người trong gia tộc hãm hại, đánh đập. Từ một thiếu gia cao cao tại thượng lại biến thành một gia nô thấp hèn. Trong lúc mê man, hắn vô tình nhận được một cuốn thần công luyện thể - Thái Thượng Luyện Khí Pháp, luyện thân mình thành binh khí. Từ đó về sau, dựa vào đánh đấm mà luyện thể đổi mệnh, lội ngược dòng từ gia nô thấp kém đến thiên tài tuyệt thế ai ai cũng ngưỡng mộ. Tuy nhiên, vào thời khắc hắn huy hoàng nhất, thì lại phát hiện cuộc đời mình chỉ như một cuốn kịch bản, mỗi bước đi dường như đều bị thế lực thần bí nào đó sắp xếp sẵn từ trước vậy. Liệu hắn có khám phá ra được bí ẩn về vận mệnh của đời mình, viết nên một câu chuyện về con đường thành thần của riêng bản thân hay không?</p>', 'Tập 130', 156, 'hoathinh', 'ongoing', 14, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Pei","avatar":""},{"name":"Yanyi Chen","avatar":""},{"name":"Bingtian Wang","avatar":""},{"name":"Xiangjin Luan","avatar":""},{"name":"Yang Miao","avatar":""},{"name":"Wen Liu","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bai Lian Cheng Shen","百炼成神","Cien refinamientos para convertise en un Dios","百煉成神","The Endless Road to Divinity","Tempered into Immortal","Elevation to the Status of a God","Apotheosis","Forged Success","Ascension to Godhood","Bách Luyện Thành Thần"]', 1784690324260);
