INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-dien', 'Lưới Điện', 'Grid', 'https://phimimg.com/upload/vod/20260522-1/fead1a09a82cb0c647b11ad85d6d75dc.jpg', 'https://phimimg.com/upload/vod/20260522-1/cdfaf3155ba0371517771e6980efc629.jpg', '<p>Vào năm 1997, một bóng ma bí ẩn đã cứu mạng nhân loại rồi đột ngột biến mất. 24 năm sau, bóng ma ấy lại xuất hiện một lần nữa, nhưng lần này là để giúp một kẻ sát nhân hàng loạt trốn thoát. Kim Sae Ha, Jung Sae Byeok và Song Eo Jin cùng nhau truy đuổi bóng ma này vì những mục đích khác nhau.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 23, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo Kang-joon","avatar":""},{"name":"Kim A-joong","avatar":""},{"name":"Lee Si-young","avatar":""},{"name":"Kim Moo-yul","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Heo Joon-seok","avatar":""},{"name":"Lee Gyu-hoe","avatar":""},{"name":"Song Sang-eun","avatar":""},{"name":"Kim Hyeong-mook","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Kim Young-sung","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zero","제로","Grid","Grid_korea","그리드"]', 1784690324260);
