INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-trom-mot-xu-phan-1', 'Tên Trộm Một Xu (Phần 1)', 'One Cent Thief (Season 1)', 'https://phimimg.com/upload/vod/20260518-1/4b308dd4efb8d32931e731d9a5073cbd.jpg', 'https://phimimg.com/upload/vod/20260518-1/6d65bc6029b7ff1b5f063af993002a8d.jpg', '<p>Khi hóa đơn viện phí của người bố ốm yếu ngày một chồng chất, nhân viên ngân hàng túng thiếu nọ nảy ra âm mưu tinh vi để đánh cắp một xu từ tài khoản của mỗi khách hàng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 35, 2022, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Syafiq Kyle","avatar":""},{"name":"Faizal Hussein","avatar":""},{"name":"Azira Shafinaz","avatar":""},{"name":"Fabian Loo","avatar":""},{"name":"Sofia Jane","avatar":""},{"name":"Kamarulzaman Taib","avatar":""},{"name":"Trisha Ooi","avatar":""},{"name":"Syarul Ezani","avatar":""},{"name":"Shashi Tharan","avatar":""},{"name":"Tony Eusoff","avatar":""},{"name":"Evon Tay","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["One Cent Thief"]', 1784690324260);
