INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-dau-tien-cua-nhat-ky', 'Trang đầu Tiên Của Nhật Ký', 'A Diary''s First Page', 'https://phimimg.com/upload/vod/20260518-1/cc2b5348026ce369c4bbcfbed6444dd5.jpg', 'https://phimimg.com/upload/vod/20260518-1/95235f902db1b65ed82b348f67f1a2ce.jpg', '<p>Những dòng chữ trên trang đầu của cuốn nhật ký buộc hai người bạn phải nhớ lại quá khứ, đặt ra những câu hỏi về sự kết thúc khi ranh giới giữa tình yêu và tình bạn trở nên mờ nhạt. Những ký ức về quá khứ ập đến khi Prabhat nhìn về góc phố nơi hai người từng tụ tập trước đây. Trong khi đó, Ahan phát hiện ra cuốn nhật ký mà anh đã tặng Prabhat từ rất lâu trước đây. Prabhat vẫn mang nó bên mình. Có một sự quen thuộc khó chịu. Tất cả những điều này quá sức chịu đựng đối với cả hai người, khiến họ không thể hiểu được ý nghĩa của nó. Ahan đi ngủ. Prabhat quyết định rời đi, nhưng cũng để lại một lời nhắn.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Akhil Nair","avatar":""},{"name":"Vikrant Yadav","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Diary''s First Page"]', 1784690324260);
