INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-duong-sau-tham', 'Đại Dương Sâu Thẳm', 'Deep Ocean', 'https://phimimg.com/upload/vod/20260518-1/e790a6b2c3c965ed80afc78c5534ff53.jpg', 'https://phimimg.com/upload/vod/20260518-1/7d691aa583c22f816f59b4f0fdef9666.jpg', '<p>Một chàng trai thầm thương trộm nhớ người mình yêu đang đấu tranh với cảm xúc của mình khi chứng kiến người mình yêu ngày càng thân thiết với những người khác, chìm sâu hơn vào sự hỗn loạn cảm xúc của chính mình.</p>', 'Full', 1, 'single', 'completed', 26, 2022, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"朱喬淵","avatar":""},{"name":"林輝瑝","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["深海"]', 1784690324260);
