INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhin-toi', '#Nhìn Tôi', '#LookAtMe', 'https://phimimg.com/upload/vod/20260518-1/3ff712b4ed97c757ed9780aca75d2fa4.jpg', 'https://phimimg.com/upload/vod/20260518-1/dee8b7de9397b53e16316b3cc3fd93bf.jpg', '<p>Một Youtuber đăng tải một video khiếm nhã chế giễu một mục sư của một nhà thờ lớn, để bảo vệ người anh em sinh đôi đồng tính của ông ta. Anh ta bị xã hội phỉ báng, bị xét xử tại tòa án, và bị đặt vào thế đối đầu với một nền văn hóa đang đe dọa hủy hoại gia đình anh ta.</p>', 'Full', 1, 'single', 'completed', 37, 2022, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Yao","avatar":""},{"name":"Pamela Oei","avatar":""},{"name":"Shu Yi Ching","avatar":""},{"name":"Fakkah Fuzz","avatar":""},{"name":"Rishi Budhrani","avatar":""},{"name":"Ghafir Akbar","avatar":""},{"name":"Sivakumar Palakrishnan","avatar":""},{"name":"Janice Koh Yu-Mei","avatar":""},{"name":"Adrian Pang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["#LookAtMe"]', 1784690324260);
