INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('latex', 'Latex', 'Latex', 'https://phimimg.com/upload/vod/20260518-1/9d6d5a553318053cd6735a9bb4333efe.jpg', 'https://phimimg.com/upload/vod/20260518-1/5346dd1271f97ae422e62be335ebe557.jpg', '<p>Jeong-su, người sở hữu năng lực tâm linh, đã sử dụng năng lực của mình để giả làm pháp sư, kiếm tiền và quyến rũ đàn ông. Su-hyun, người thầm yêu Jeong-su nhưng không được đáp lại, giúp anh điều hành công việc xem bói nhưng không thể chịu đựng được lối sống liều lĩnh của Jeong-su. Trong cơn tuyệt vọng, Su-hyun tìm đến một pháp sư quyền năng tên là Gi-hwan để xóa bỏ năng lực của Jeong-su.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Latex","라텍스"]', 1784690324260);
