INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('big-mouth', 'Big Mouth', 'Big Mouth', 'https://phimimg.com/upload/vod/20260515-1/a45004295a2c2a58bab127ccb486674e.jpg', 'https://phimimg.com/upload/vod/20260515-1/df0d73908c09da82d237bf36fea4b21c.jpg', '<p>Big Mouth kể về câu chuyện về một anh chàng luật sư kém tài và không may bị cuốn vào một vụ án giết người. Để sống sót và bảo vệ gia đình mình, anh bắt buộc phải đào sâu khám phá âm mưu lớn của tầng lớp thượng lưu. Park Chang Ho, một luật sư hạng ba với tỷ lệ “cãi thắng” thành công là 10% và được người quen đặt biệt danh “Big Mouth&quot; bởi tính cách giỏi nói chứ không giỏi làm. Một ngày kia, cuộc sống của anh bỗng nhiên bị đảo lộn sau khi bị nhầm lẫn với một kẻ lừa đảo thiên tài có tên “Big Mouse”. Go Mi Ho, người vợ luôn hết mình ủng hộ chồng của Park Chang Ho. Go Mi Ho là một cô y tá xinh đẹp, dịu dàng nhưng cũng rất sắc bén, mạnh mẽ. Cô sẽ chiến đấu đến cùng trong tuyệt vọng để cứu người chồng bị vu oan của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 28, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jong-suk","avatar":""},{"name":"Yoona","avatar":""},{"name":"Kim Ju-hun","avatar":""},{"name":"Kwak Dong-yeon","avatar":""},{"name":"Yang Kyung-won","avatar":""},{"name":"Ok Ja-yeon","avatar":""},{"name":"Oh Eui-sik","avatar":""},{"name":"Kim Jeong-hyeon","avatar":""},{"name":"Lee Yoo-jun","avatar":""},{"name":"Oh Ryoong","avatar":""},{"name":"Yoon Seok-hyun","avatar":""},{"name":"Park Hoon","avatar":""},{"name":"Kim Kyu-seon","avatar":""},{"name":"Jang Hyuk-jin","avatar":""},{"name":"Kim Sun-hoa","avatar":""},{"name":"Park Se-hyun","avatar":""},{"name":"Jeong Jae-seong","avatar":""},{"name":"Kang Hyung-wook","avatar":""},{"name":"Lee Ki-y","avatar":""}]', '[{"name":"Tì