INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-den-mat-2022', 'Mắt đền Mắt', 'Eye For Eye', 'https://phimimg.com/upload/vod/20260512-1/906c2e13913c24b178f8cc125e82937c.jpg', 'https://phimimg.com/upload/vod/20260512-1/0098785a96f2f8b299ed2b5ef14d4adf.jpg', '<p>Ông trùm chăn nuôi gia súc muốn chiếm đoạt trang trại nhỏ của Reagan và người đẹp gốc Latinh Lola McLaughlin. Người của hắn đã giết chết người vợ đang mang thai của Reagan. Reagan để lại huy hiệu thiếc của mình trên mộ Consuela, và với khẩu súng Winchester, súng săn và súng Colt, ông một mình cưỡi ngựa chống lại cả trăm người.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Savage","avatar":""},{"name":"Shane Clouse","avatar":""},{"name":"Blanca Blanco","avatar":""},{"name":"L.J. Martin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Eye for Eye"]', 1784690324260);
