INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-tiec-tai-nha-cua-chung-toi', 'Bữa Tiệc Tại Nhà Của Chúng Tôi', 'Our House Party', 'https://phimimg.com/upload/vod/20260513-1/8c54b0bb2e5f19ab9e1df243259f8156.jpg', 'https://phimimg.com/upload/vod/20260513-1/8a810eb4f929df4f9f3c64084145d22c.jpg', '<p>Tomoya là một sinh viên đại học 21 tuổi ở Tokyo, và một cuộc gặp gỡ tình cờ với Shoichi, một chủ quán bar đồng tính hoạt động ở Shinjuku 2-chome, đã cho Tomoya cơ hội bắt đầu công khai xu hướng đồng tính của mình. Cậu sẽ có rất nhiều người đàn ông để học hỏi khi bị cuốn vào một bữa tiệc tại gia do Akito và bạn trai Yasushi, Naoki, chủ một câu lạc bộ đồng tính, cùng người bạn Masashi của anh ta, và Kenichi, một nhiếp ảnh gia, tổ chức. Khi rượu tràn ngập và bữa tiệc trở nên sôi động, Tomoya nhận ra mọi chuyện không ổn với những vị khách khác khi những lo lắng và cảm xúc bị kìm nén của họ dần dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takashi Hashizume","avatar":""},{"name":"Keiichi Kageyama","avatar":""},{"name":"Ryo Matsumoto","avatar":""},{"name":"Hiroshi Yokoro","avatar":""},{"name":"卯ノ原圭吾","avatar":""},{"name":"Sho Kubota","avatar":""},{"name":"Ryosuke Inoura","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["ボクらのホームパーティー"]', 1784690324260);
