INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-gio', 'Chuông Gió', 'Wind Bell', 'https://phimimg.com/upload/vod/20260513-1/80ac5cc663ce11e18f6246aaec57a74d.jpg', 'https://phimimg.com/upload/vod/20260513-1/7e7ac075052497bf61e1c728671c37e0.jpg', '<p>Vào một ngày hè nóng nực, Jeongwoo, một sinh viên đại học, trở về quê hương cũ Buan. Ngôi nhà cũ của anh ngày càng đổ nát, và những ký ức ùa về trong tâm trí Jeongwoo. Khi anh gặp lại người cộng sự cũ Donga, liệu quá khứ có một lần nữa trở về hiện tại?</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"한현준","avatar":""},{"name":"윤우","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["어제의 바람"]', 1784690324260);
