INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-cua-chung-toi', 'Thời Gian Của Chúng Tôi', 'Our Time', 'https://phimimg.com/upload/vod/20260513-1/8f7d17db3e4348e96a2933866627f2e3.jpg', 'https://phimimg.com/upload/vod/20260513-1/b872feb453df5f1fc3a9c90a18246517.jpg', '<p>Ji Eun, người từng là người yêu của Won Young, đến thăm cô, người giờ đã chôn vùi quá khứ. Ji Eun rủ Won Young đi hẹn hò, và Won Young đau khổ tột cùng. Cuối cùng, như Ji Eun đã nói, cô sẽ không bao giờ quay lại nếu chỉ ở bên cô một ngày, Won Young miễn cưỡng quay lại những nơi kỷ niệm cùng Ji Eun, và cả hai bắt đầu một chuyến du hành ký ức.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["우리가 함께한 시간"]', 1784690324260);
