INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-be-deu-ghet-toi', 'Bạn Bè Đều Ghét Tôi', 'All My Friends Hate Me', 'https://phimimg.com/upload/vod/20260509-1/e80f480acc6ab6ec2ebcdccd5486bac7.jpg', 'https://phimimg.com/upload/vod/20260509-1/8c75368f342b027cedc6391ff784b180.jpg', '<p>Buổi họp mặt cựu sinh viên trở nên tồi tệ khi Pete nghi ngờ bạn bè mình đang âm mưu hãm hại anh ta… Khi kỳ nghỉ cuối tuần ngày càng trở nên khó chịu, liệu Pete có nên lo lắng cho sự an toàn của mình, hay tất cả chỉ là do anh ta tưởng tượng?</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tom Stourton","avatar":""},{"name":"Georgina Campbell","avatar":""},{"name":"Charly Clive","avatar":""},{"name":"Antonia Clarke","avatar":""},{"name":"Joshua McGuire","avatar":""},{"name":"Dustin Demri-Burns","avatar":""},{"name":"Graham Dickson","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Kieran Hodgson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["올 마이 프렌즈 헤이트 미","All My Friends Hate Me"]', 1784690324260);
