INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-hoc-thien-va-ac', 'Trường Học Thiện Và Ác', 'The School For Good And Evil', 'trường học thiện và ác the school for good and evil sofia wylie sophia anne caruso kerry washington charlize theron laurence fishburne jamie flatters earl cave holly sturton kit young freya parks scaredy kat cate blanchett liam woon rachel bloom rob delaney sandra yaw denis coleman mark ch 善惡魔法學院 la escuela del bien y el mal مدرسه‌ای برای خیر و شر l''école du bien et du mal the school for good and evil', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vang-2022', 'Vàng', 'Gold', 'https://phimimg.com/upload/vod/20260509-1/4a485d40fc53a452a4021d290ef84037.jpg', 'https://phimimg.com/upload/vod/20260509-1/61689ef7209a42cb084f1083688f82e7.jpg', '<p>Trong một tương lai không xa, hai kẻ lữ hành băng qua sa mạc tình cờ phát hiện ra khối vàng lớn nhất từng được tìm thấy. Giấc mơ về sự giàu sang tột đỉnh và lòng tham bắt đầu trỗi dậy. Họ lập kế hoạch khai thác kho báu này: một người rời đi để tìm kiếm dụng cụ cần thiết, người còn lại ở lại canh giữ khối vàng. Người ở lại phải chống chọi với sự khắc nghiệt của thiên nhiên sa mạc, những đàn chó hoang đói khát và những kẻ lạ mặt bí ẩn, đồng thời phải đấu tranh với nỗi nghi ngờ ngày càng lớn rằng mình đã bị đồng đội bỏ mặc cho đến chết.</p>', 'Full', 1, 'single', 'completed', 28, 2022, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Zac Efron","avatar":""},{"name":"Anthony Hayes","avatar":""},{"name":"Susie Porter","avatar":""},{"name":"Andreas Sobik","avatar":""},{"name":"Akuol Ngot","avatar":""},{"name":"Thiik Biar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Жажда золота","더 골드","Gold - Im Rausch der Gier","Gold"]', 1784690324260);
