INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sao-bang-2022', 'Sao Băng', 'Shooting Stars', 'https://phimimg.com/upload/vod/20260506-1/bde8d1b7bf68f4153d8b9e2f27833c46.jpg', 'https://phimimg.com/upload/vod/20260506-1/81217a81e88872580715f72f798589b2.jpg', '<p>Bộ phim lấy chủ đề về giới giải trí và các công ty quản lí, kể về câu chuyện các minh tinh như những ngôi sao không thể tự mình tỏa sáng trên bầu trời, chủ yếu là câu chuyện của những người làm việc ở hậu trường ngành giải trí, những con người làm việc chăm chỉ khổ cực sau những lùm xùm của các minh tinh. Là câu chuyện từ thù hận đến tình yêu lãn mạn giữa Oh Han Byul là trưởng nhóm PR tại một công ty giải trí, và ngôi sao nổi tiếng Gong Tae Sung. Một trưởng nhóm quan hệ công chúng tài giỏi có năng lực phản ứng tuyệt vời khi các scandal xảy ra, và một ngôi sao nổi tiếng trong làng giải trí, chuyện gì sẽ xảy ra giữa họ? Bộ phim có sự tham gia của các diễn viên Lee Sung Kyung và Kim Young Dae.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 19, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sung-kyung","avatar":""},{"name":"Kim Young-dae","avatar":""},{"name":"Yoon Jong-hoon","avatar":""},{"name":"Kim Yoon-hye","avatar":""},{"name":"Park So-jin","avatar":""},{"name":"Lee Jung-shin","avatar":""},{"name":"Ha Do-kwon","avatar":""},{"name":"Lee Seung-hyub","avatar":""},{"name":"Jeong Ji-an","avatar":""},{"name":"Yun Sang-jeong","avatar":""},{"name":"Kwon Han-sol","avatar":""},{"name":"Shin Hyeon-seung","avatar":""},{"name":"Lee Si-woo","avatar":""},{"name":"Jin Ho-eun","avatar":""},{"name":"Jang He-ryung","avatar":""},{"name":"Lee Ju-won","avatar":""},{"name":"Jang Do-ha","avatar":""},{"name":"Kim Dae-gon","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-