INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hiep-si-mat-na-gia-dinh-sieu-pham', 'Hiệp Sĩ Mặt Nạ: Gia Đình Siêu Phàm', 'Kamen Rider Revice the Movie: Battle Familia', 'hiệp sĩ mặt nạ: gia đình siêu phàm kamen rider revice the movie: battle familia kentaro maeda subaru kimura wataru hyuga ayaka imoto kane kosugi noritaka hamao hikari kabashima hayata seki junya komatsu claud hachijoin miku ito jun hashimoto kurara emi shigeyuki totsugi shingo fujimori yutaka saigo issei mamehara har gekijôban kamen raidâ ribaisu: batoru famiria kamen rider revice battle familia 劇場版 仮面ライダーリバイス バトルファミリア', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-ngoai-hanh-tinh-phan-2', 'Bác Sĩ Ngoài Hành Tinh (Phần 2)', 'Resident Alien (Season 2)', 'https://phimimg.com/upload/vod/20250722-1/7fca2bf4e6755ce68a38527fb24f2fcb.jpg', 'https://phimimg.com/upload/vod/20250722-1/2c4334f69b33bbda6ca557374d2bf877.jpg', '<p>Bộ phim dựa trên truyện tranh cùng tên của Peter Hogan và Steve Parkhouse. Câu chuyện kể về một anh chàng người ngoài hành tinh, sau khi hạ cánh xuống Trái Đất anh lấy thân phận là bác sĩ và sinh sống tại thị trấn Colorado. Tại đây, anh chàng người ngoài hành tinh phải vật lộn trong tình thế tiến thoái lưỡng nan giữa nhiệm vụ bí mật và đạo đức con người. Đồng thời anh chàng còn phải đối phó với cậu bé 9 tuổi, người duy nhất biết được thân phận thật sự của anh. Liệu anh chàng sẽ lựa chọn giữa nhiệm vụ hủy diệt Trái Đất hay cứu giúp nhân loại?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alan Tudyk","avatar":""},{"name":"Sara Tomko","avatar":""},{"name":"Corey Reynolds","avatar":""},{"name":"Alice Wetterlund","avatar":""},{"name":"Levi Fiehler","avatar":""},{"name":"Elizabeth Bowen","avatar":""},{"name":"Meredith Garretson","avatar":""},{"name":"Judah Prehn","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Местен извънземен","外星居民","תושב חייזרי","レジデント・エイリアン ～宇宙からの訪問者～","Местный пришелец","Пришелец-постоялец","Резидент прибулець","Постоялець з космосу","Resident Alien"]', 1784690324260);
