INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-thu-thai-cuc', 'Dị Thú Thái Cực', 'Taichi''s Beast Mound', 'https://phimimg.com/upload/vod/20260502-1/150d8eb069409cd0da3e61b9985804eb.jpg', 'https://phimimg.com/upload/vod/20260502-1/766f804e06d0929c47615f7e37ce0b47.jpg', '<p>Bộ phim kể về Trần Thừa Phong một đệ tử của môn phái Thái Cực cùng sư muội Yên Nhiên trong lúc bị bao vây bởi con gái trưởng môn phái Ma La và một nhóm đệ tử, hai người họ đã vô tình bước vào nơi bí mật nhất của giáo phái Thái Cực - lăng mộ quái thú. Sau khi trải qua những khó khăn, bí mật của môn phái Thái Cực cuối cùng đã được tiết lộ.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Narisu","avatar":""},{"name":"Li Zhongyu","avatar":""},{"name":"Hou Peishan","avatar":""},{"name":"Li Zhu","avatar":""},{"name":"Qin Chuming","avatar":""},{"name":"Dou Yikun","avatar":""},{"name":"Han Yinlong","avatar":""},{"name":"Peng Jing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Tai Ji Zhi Yi Shou Zhong","Dị Thú Thái Cực","太极之异兽冢"]', 1784690324260);
