INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quang-dong-thap-ho-thiet-quyen-vo-dich', 'Quảng Đông Thập Hổ: Thiết Quyền Vô Địch', 'Ten Tigers of Guangdong: Invincible Iron Fist', 'https://phimimg.com/upload/vod/20260502-1/2def3e0e05c8e6472616cf43a3afe372.jpg', 'https://phimimg.com/upload/vod/20260502-1/49dc6f8469856ff0d9b1257e9ba1dba3.jpg', '<p>(JiangHu) Bộ phim kể về câu chuyện của Lương Khôn, một trong những người của Quảng Đông Thập Hổ người đã luyện tập võ thuật để bảo vệ những người thân yêu của mình. Dù rơi vào bẫy bị hãm hại anh nhưng anh vẫn tiếp tục tìm kiếm sự thật với lòng kiên trì bất diệt của mình. Cuối cùng, anh đã tạo ra năm đấm sắt cho riêng mình và đánh bại thế lực tà ác đứng sau.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Zaimire Aheiti","avatar":""},{"name":"Norman Tsui Siu-Keung","avatar":""},{"name":"Edward Chui Wai-Tung","avatar":""},{"name":"Canti Lau Sek-Ming","avatar":""},{"name":"Wu Guobao","avatar":""},{"name":"Chen Weiran","avatar":""},{"name":"Yeung Lun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["广东十虎之铁拳无敌","Ten Tigers of Guangdong Invincible Iron Fist","광동십호 : 철권무적","广东十虎：铁拳无敌"]', 1784690324260);
