INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-duoi', 'Săn Đuổi', 'The Hunting', 'https://phimimg.com/upload/vod/20231116-1/a276f3a5aff962ee861564d21472579f.jpg', 'https://phimimg.com/upload/vod/20231116-1/b99b6fc408e6f6a47efbbd63a05dcf80.jpg', '<p>Lão Mã mất con trai, căm hận bọn săn trộm, từng rơi vào tâm trạng đen tối muốn trả thù, nhưng dần dần bị lòng nhiệt tình và lòng tốt của Tiểu Cốc lay động, cuối cùng lấy lại được hy vọng. Ngược lại, những kẻ săn trộm lại hoàn toàn ngược lại với ngựa quen đường cũ, tước đi bao sinh mạng vô tội vì những ham muốn ích kỷ của bản thân, đi con đường riêng để trả thù, rốt cuộc kết thúc bằng một kết cục bi thảm.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cao Weiyu","avatar":""},{"name":"Yu Kang","avatar":""},{"name":"Pema Jyad","avatar":""},{"name":"Jiang Baocheng","avatar":""},{"name":"Fang Xushi","avatar":""},{"name":"Wang Haocheng","avatar":""},{"name":"Wo Zhiqiang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324260);
