INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-long-dot-bien', 'Khủng Long Đột Biến', 'Variation of Tyrannosaurus', 'https://phimimg.com/upload/vod/20231123-1/5439171a744cfc2e3460e56374378677.jpg', 'https://phimimg.com/upload/vod/20231123-1/c5ce132ee11a7db818595e5d6b59f250.jpg', '<p>Khủng Long Đột Biến - Variation of Tyrannosaurus tại một viện nghiên cứu Gen đột biến, người giúp viện vô tình mở một chiếc lồng sắt tại phòng thí nghiệm và bị một quái vật giết chết. Để điều tra nguồn gốc vụ án có liên quan đến con trăn kỳ lạ, A Lương một nhà sinh vật động vật hoang dã, đã đến tập đoàn Gen nơi bạn gái cũ Thi Văn làm việc. Tại đây, anh phát hiện ra được những bí mật kinh hoàng mà công ty Gen tạo ra.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Gao Shuang","avatar":""},{"name":"Wang Xingchen","avatar":""},{"name":"Cheng Fangxu","avatar":""},{"name":"Sun Ruiqi","avatar":""},{"name":"Kong Qingxin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324260);
