INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-sa-mac', 'Quái Thú Sa Mạc', 'Desert Monster', 'https://phimimg.com/upload/vod/20231101-1/1e914b8104b386b3ee97e8bdeee073f0.jpg', 'https://phimimg.com/upload/vod/20231101-1/a4a688926c82f1f77e920a6eda04a048.jpg', '<p>Vào những năm đầu của Trung Hoa Dân Quốc, Viện Sinh học của Hiệp hội Khoa học Tây Bắc đã nhận được một bức thư bí ẩn và biết rằng các sinh vật đột biến đã lây nhiễm vào biển cát, vì vậy họ đã cử một nhóm thám hiểm đến phòng thí nghiệm sinh học. Lưu Mộng Tây và Hạ Huyên đã mang theo mẫu vật và trốn thoát nhưng họ đã gặp sự cố ở trấn cồn cát và mẫu vật bị hủy mất. Cuối cùng họ được cung thủ Liễu Anh giải cứu. Hai người họ phát hiện ra rằng hầu như chỉ còn lại những người già, yếu, bệnh tật và tàn tật ở trấn cồn cát, và bên ngoài thị trấn, con quái vật dường như đã nghe thấy điều gì đó và đang lặng lẽ tiếp cận trấn cồn cát...</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Jin Yanna","avatar":""},{"name":"Bo Xiao","avatar":""},{"name":"Yu Xinyan","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Shuangli Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324260);
