INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chu-2', 'Bà Chủ 2', 'Queen Of Triads 2', 'https://phimimg.com/upload/vod/20260502-1/e2fb29b51163c38aee7681d923871944.jpg', 'https://phimimg.com/upload/vod/20260502-1/fd469a1a1be861bba1e2ef26ea51a771.jpg', '<p>Hồng Kông những năm 70 bị thực dân Anh chiếm đóng người dân ở tầng lớp thấp sống rất khổ cực, cảnh sát Anh cấu kết với các lực lượng tội phạm, bao che các giao dịch phi pháp như mại dâm, cờ bạc, ma túy. Cha của Rose bị Kun giết vì tịch thu ma túy mà không thỏa hiệp. Vì sự an toàn, Rose được người chú gửi đến Đài Loan. Khi lớn lên, Rose quyết tâm trả thù và đưa Kun cùng những tên buôn ma túy khác ra trước công lý. Rose gia nhập Ủy ban chống tham nhũng để do thám trùm ma túy tên Hạo, hoạt động dưới vỏ bọc là gián điệp chờ cơ hội lấy thông tin. Tuy nhiên, khi Rose và Hạo ca quen nhau, giữa hai người đã nảy sinh một tình yêu không nên có. Một mặt, là hành trình trả thù cho cha và đưa tên trùm ma túy ra trước công lý. Mặt khác, là cơ hội để nối lại tình cảm tuổi thơ. Khi Rose vướng vào một quyết định định mệnh, cô ấy nên làm gì?</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tạ Thiên Hoa","avatar":""},{"name":"Từ Đông Đông","avatar":""},{"name":"Thang Trấn Nghiệp","avatar":""},{"name":"Quế Tinh Tinh","avatar":""},{"name":"Lưu Hạo Tuấn Long","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Queen of the Triads 2","Queen of Triads 2","老闆娘2無間潛行","老板娘2無間潛行","老板娘2：无间潜行"]', 1784690324260);
