INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-nu-sinh', 'Bẫy Nữ Sinh', 'Next Sohee', 'https://phimimg.com/upload/vod/20260502-1/5ef5b58fb1ae1888ae531151d06f9fd5.jpg', 'https://phimimg.com/upload/vod/20260502-1/63062dc908f0ebf0ae29b7af1bebd455.jpg', '<p>Nữ sinh Sohee bị lừa thực tập tại một công ty, nhưng vì áp lực và lòng tham của nơi đó đã đẩy cô đến cái chết. Thám tử Yoo Jin vào cuộc điều tra, và dần hé lộ sự thật đen tối phía sau một đế chế.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Si-eun","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Jung Hoe-ryn","avatar":""},{"name":"Kang Hyun-oh","avatar":""},{"name":"Bahk Woo-young","avatar":""},{"name":"Lee In-young","avatar":""},{"name":"Park Hui-eun","avatar":""},{"name":"Kim Yong-jun","avatar":""},{"name":"Sim Hee-seop","avatar":""},{"name":"Yoon Ga-i","avatar":""},{"name":"Jung Soo-ha","avatar":""},{"name":"Park Yoon-hee","avatar":""},{"name":"Choi Hee-jin","avatar":""},{"name":"Yoo Jeong-ho","avatar":""},{"name":"Moon Jung-woong","avatar":""},{"name":"Kim Tae-yoon","avatar":""},{"name":"Yoo Jae-won","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Park Seo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Daeum Sohui","About Kim Sohee","Next Sohee","Będą następne Sohee","Da-eum So-hee","Sıradaki Kız","다음 소희"]', 1784690324260);
