INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hinh-the-phan-2', 'Hình Thể (Phần 2)', 'Physical (Season 2)', 'https://phimimg.com/upload/vod/20260430-1/912a5c4498e373fd98a1034ee966e073.jpg', 'https://phimimg.com/upload/vod/20260430-1/70f386f47cf9cf9408c5c59967a63339.jpg', '<p>Phần hai tìm thấy người hùng Sheila Rubin của chúng ta đã ra mắt thành công video thể dục đầu tiên của mình nhưng lại gặp phải một số chướng ngại vật mới và lớn hơn trên con đường của cô ấy. Cô ấy bị giằng xé giữa lòng trung thành với chồng và những giá trị mà anh ấy đại diện, và sự hấp dẫn nguy hiểm đối với người khác. Và vì cô ấy không còn là trò chơi duy nhất trong thị trấn, cô ấy thấy mình phải vượt qua một số đối thủ cạnh tranh mới khốc liệt trên con đường xây dựng một đế chế thể hình chính thức</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rose Byrne","avatar":""},{"name":"Rory Scovel","avatar":""},{"name":"Dierdre Friel","avatar":""},{"name":"Paul Sparks","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["جسمانی","فیزیکی","Physical"]', 1784690324260);
