INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-cua-cho-va-lon', 'Thế Giới Của Chó Và Lợn', 'The King of Pigs', 'https://phimimg.com/upload/vod/20260424-1/701c6119bde95d3059131ad3b5718324.jpg', 'https://phimimg.com/upload/vod/20260424-1/f55f733d4581f0987f7e86f3388f26fb.jpg', '<p>Được chuyển thể từ bộ phim hoạt hình “The King of Pigs” (돼지 의 왕) của Yeon Sang Ho, bộ phim Vua Lợn kể về 2 người bạn gặp lại nhau khi họ nhận được tin nhắn từ một người bạn 20 năm trước. Từ cuộc gặp gỡ đó, những vụ giết người hàng loạt bí ẩn bắt đầu xảy ra.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 22, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Dong-wook","avatar":""},{"name":"Kim Sung-kyu","avatar":""},{"name":"Chae Jung-an","avatar":""},{"name":"Choi Hyeon-jin","avatar":""},{"name":"Oh Min-suk","avatar":""},{"name":"Moon Seong-hyun","avatar":""},{"name":"Han Soo-yeon","avatar":""},{"name":"Lee Ji-ha","avatar":""},{"name":"Jung Eui-jae","avatar":""},{"name":"Ji Chan","avatar":""},{"name":"Song Seung-hwan","avatar":""},{"name":"Sim Hyun-seo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["猪猡之王","El Rey de los Cerdos","The King of Pigs","پادشاه خوک ها","돼지의 왕"]', 1784690324260);
