INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-cua-cho-va-lon', 'Thế Giới Của Chó Và Lợn', 'The King of Pigs', 'thế giới của chó và lợn the king of pigs kim dong-wook kim sung-kyu chae jung-an choi hyeon-jin oh min-suk moon seong-hyun han soo-yeon lee ji-ha jung eui-jae ji chan song seung-hwan sim hyun-seo 猪猡之王 el rey de los cerdos the king of pigs پادشاه خوک ها 돼지의 왕', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-an-vuong-toa', 'Thần Ấn Vương Tọa', 'Throne Of Seal', 'https://phimimg.com/upload/vod/20250423-1/d6a5827d17ac61860286357fbe66f3a1.jpg', 'https://phimimg.com/upload/vod/20250423-1/560bc7dbd5121fb6e2681160f638409c.jpg', '<p>6000 năm trước, hoàng đế Ma Thần Phong Tú và 72 Ma Thần Trụ giáng xuống, tất cả sinh vật bị nhiễm hơi thở của Ma Thần Trụ, lập tức biến thành Ma Vật, loài người bước vào thời đại đen tối. Sau đó, những kẻ mạnh của loài người đã lập thành Lục Đại Thánh Điện ngăn chặn Ma Vật, hình thành cục diện người và ma quỷ cùng tồn tại. Long Hạo Thiên một trong Lục Đại Thánh Điện, trở thành kỵ sĩ chỉ để cứu mẹ. Hạo Thiên từng bước trưởng thành, liên tiếp trải qua những cuộc gặp gỡ kỳ lạ, âm mưu quỷ kế, tình yêu và tình bạn định mệnh. Hạo Thiên tuân thủ tinh thần kỵ sĩ, nhận được sự công nhận của người khác nhờ vào nhân cách và sự nỗ lực của bản thân, cùng những nhân tài khác của Lục Đại Thánh Điện thành lập “Săn Ma Đoàn số 1” để đấu với Ma Vật, đấu tranh cho sự sống còn và tôn nghiêm của loài người.</p>', 'Tập 208', 208, 'hoathinh', 'ongoing', 14, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chang Rongshan","avatar":""},{"name":"Nianru Shen","avatar":""},{"name":"Liu Mingyue","avatar":""},{"name":"Ye Zhiqiu","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Yang Tianxiang","avatar":""},{"name":"Yeqiao Yan","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"Xin Teng","avatar":""},{"name":"Meme Yan","avatar":""},{"name":"Yuntu Cao","avatar":""},{"name":"Tong Yin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":