INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-lang-phe-pha-phan-2', 'Lâng Lâng (Phê Pha) (Phần 2)', 'Euphoria (Season 2)', 'lâng lâng (phê pha) (phần 2) euphoria (season 2) zendaya hunter schafer sydney sweeney jacob elordi alexa demie angus cloud barbie ferreira maude apatow javon walton eric dane dominic fike storm reid nika king austin abrams еуфория 亢奋 高校十八禁 ユーフォリア/euphoria ユーフォリア／euphoria 유포리아 eiforija euphoria us phê pha euphoria', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-uoc-di-tieu-thu-tien-ky', 'Hãy Ước Đi Tiểu Thư Tiên Kỳ', 'Make A Wish Miss Xianqi', 'https://phimimg.com/upload/vod/20260420-1/e833ecb6baba1bb9c640a3ab638e4890.jpg', 'https://phimimg.com/upload/vod/20260420-1/9c07e44313e2da09b377bf1c59f52253.jpg', '<p>Bộ phim kể về Trần Tiên Kỳ, một biên tập viên nhỏ của một tạp chí thời trang, vô tình làm mất viên kim cương mà tạp chí cho mượn, nhưng lại hiểu lầm là luật sư thực tập Tiêu Gia Hữu đã nhặt được nó. Trần Tiên Kỳ lần theo dấu vết của Tiêu Gia Hữu, nhưng không những không lấy lại được viên kim cương mà còn mất việc, thậm chí còn gánh khoản nợ khổng lồ. Ngay khi Trần Tiên Kỳ đang trong tình trạng tuyệt vọng, cô vô tình được thừa kế một chiếc vòng tay bí ẩn, cô phát hiện ra rằng chiếc vòng dường như ẩn chứa một sức mạnh thần bí nào đó. Trời xui đất khiến Tiêu Gia Hữu vô tình trở thành bạn cùng phòng của Trần Tiên Kỳ, thuê chung căn hộ hai phòng ngủ với cô ấy, hai người vốn ghét nhau buộc phải bắt đầu cuộc sống chung đụng. Họ đã dùng sức mạnh của chiếc vòng tay để giúp đỡ rất nhiều người, trải nghiệm nhiều điều và trái tim họ đang dần xích lại gần nhau hơn.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 26, 2022, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Khâu Khải Vĩ","avatar":""},{"name":"Lý Gia Kỳ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xian Qi Xiao Jie Xu Yuan Ba","家有仙妻","Jia You Xian Qi","Make a Wish Miss Xian Qi","The Fairy Lady","仙琦小姐许愿吧"]', 1784690324260);
