INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-khoi-lung-tay', 'Phong Khởi Lũng Tây', 'The Wind Blows From Longxi', 'https://phimimg.com/upload/vod/20260415-1/a36fe9efe5c9f31c23c565ee7e3b6376.jpg', 'https://phimimg.com/upload/vod/20260415-1/5fab20b6e9638bf0abbd43262b172fcd.jpg', '<p>Thời Tam Quốc, quân Thục đánh bại quân Ngụy bằng nỏ do họ chế tạo. Để có được vũ khí lợi hại này, nhà Ngụy cử rất nhiều gián điệp xâm nhập vào nước Thục. Trần Cung và Tuân Hủ là gián điệp của quân Thục đã xâm nhập vào nước Ngụy nhiều năm. Sau khi biết kế hoạch của Ngụy, họ quyết tâm ngăn chặn. Trần Cung tiếp tục ở lại nước Ngụy làm nội gián, còn Tuân Hủ quay về để tìm ra nội gián của Ngụy trong nước mình, phá hoại kế hoạch của Ngụy.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 21, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Khôn","avatar":""},{"name":"Bạch Vũ","avatar":""},{"name":"Nhiếp Viễn","avatar":""},{"name":"Thường Viễn","avatar":""},{"name":"Angela Baby","avatar":""},{"name":"Tôn Di","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Feng Qi Long Xi","The Wind Blows From Longxi","风起陇西"]', 1784690324260);
