INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-gai-thue-phan-2', 'Bạn Gái Thuê (Phần 2)', 'Rent-A-Girlfriend (Season 2)', 'bạn gái thuê (phần 2) rent-a-girlfriend (season 2) shun horie sora amamiya aoi yuuki nao toyama rie takahashi yu serizawa yukari nozawa sayuri sadaoka masayuki akasaka gakuto kajiwara 租借女友 किराए पर प्रेमिका kano kari kanojo, okarishimasu kanojo, okarishimasu 2 kanokari 2 彼女、お借りします rental girlfriend the animation kanojo okarishimasu una novia de alquiler девушка напрокат девушка на час девушка в аренду สะดุดรักยัยแฟนเช่า i''d like to borrow a girlfriend rental girlfriend rental girlfriend 2 rent-a-girlfriend dịch vụ thuê bạn gái bạn gái, tôi thuê cô', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-quang-chi-thanh', 'Lưu Quang Chi Thành', 'City Of Streamer', 'https://phimimg.com/upload/vod/20260330-1/fde458ceb5449bd32adc56850bfcd281.jpg', 'https://phimimg.com/upload/vod/20260330-1/2beba6929cdae950d2ee76a460554c1b.jpg', '<p>Lưu Quang Chi Thành được chuyển thể từ tiểu thuyết của tác giả Mĩ Bảo. Câu chuyện diễn ra ở Thượng Hải phồn hoa, nơi có nhà họ Dung nổi tiếng phú quý bậc nhất. Dung Gia Thượng (Hứa Ngụy Châu) là đại thiếu gia của nhà họ Dung, nổi tiếng là người lạnh lùng, kiêu ngạo. Phùng Thế Chân (Cảnh Điềm) không vì thế mà e ngại, đã vào nhà họ Dung và trở thành gia sư cho Dung Gia Thượng. Câu chuyện tình yêu giữa hai nhân vật trong Lưu Quang Chi Thành vừa ngọt ngào, vừa trắc trở, khi mắc kẹt bởi những âm mưu âm thầm sắp đặt cũng như dòng chảy của thời cuộc không dễ mà thoát khỏi. Dung Gia Thượng và Phùng Thế Chân dành tình cảm cho nhau, nhưng đồng thời cũng thử thách nhau, thậm chí là phản bội, dẫn đến những tổn thương. Trong câu chuyện, Dung Gia Thượng và Phùng Thế Chân như hai luồng ánh sáng giữa Thượng Hải phồn hoa. Cái kết của họ là song hành hay ly biệt, khán giả chỉ có thể tìm thấy câu trả lời khi phim lên sóng.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 28, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Cảnh Điềm","avatar":""},{"name":"Hứa Ngụy Châu","avatar":""},{"name":"Kinh Siêu","avatar":""},{"name":"Hải Linh","avatar":""},{"name":"Trì Gia","avatar":""},{"name":"Vương Nhất Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Liu Guang Zhi Cheng","City Of Streaming Light","The City of Passing Time","流光之城"]', 1784690324260);
