INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-con-cho-dia-nguc', 'Những Con Chó Địa Ngục', 'Hell Dogs', 'https://phimimg.com/upload/vod/20260409-1/12ca0b80378eca459750ade732fee9f6.jpg', 'https://phimimg.com/upload/vod/20260409-1/3e97cac836bd8bea745992b8bed0dc7e.jpg', '<p>Với lòng thù hận sâu sắc, một cựu cảnh sát bị ám ảnh bởi chấn thương tâm lý phải thâm nhập vào một tổ chức yakuza bằng cách kết bạn với một trong những thành viên mất trí nhất của nhóm.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Junichi Okada","avatar":""},{"name":"Kentaro Sakaguchi","avatar":""},{"name":"Mayu Matsuoka","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Shinobu Otake","avatar":""},{"name":"MIYAVI","avatar":""},{"name":"Satoshi Kanada","avatar":""},{"name":"Mitsuo Yoshihara","avatar":""},{"name":"Mai Kiryu","avatar":""},{"name":"Arisa Nakajima","avatar":""},{"name":"Yasumasa Oba","avatar":""},{"name":"Ukon Onoe","avatar":""},{"name":"Miou Tanaka","avatar":""},{"name":"Jun Murakami","avatar":""},{"name":"Yoshi Sakō","avatar":""},{"name":"Mariko Akama","avatar":""},{"name":"Ayaka Koyanagi","avatar":""},{"name":"Takashi Shi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hell Dogs ~Jigoku no Inutachi~","Hell Dogs - In The House Of Bamboo","Hell Dogs","سگ‌های جهنمی","Hell Dogs：竹之家","Hell Dogs: En la casa de bambú","ヘルドッグス"]', 1784690324260);
