INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-drovers-wife-the-legend-of-molly-johnson', 'The Drover''s Wife: The Legend of Molly Johnson', 'The Drover''s Wife: The Legend of Molly Johnson', 'https://phimimg.com/upload/vod/20260409-1/e8a45a1cf106d496917bc5753655a34b.jpg', 'https://phimimg.com/upload/vod/20260409-1/a8f352bac6c0b945b4bac58d66a084a8.jpg', '<p>Năm 1893, Molly Johnson đang mang thai nặng nề và các con phải vật lộn để sống sót trong sự cô lập giữa vùng đất khắc nghiệt của Úc sau khi chồng cô bỏ đi chăn cừu ở vùng cao. Một ngày nọ, cô tìm thấy một người thổ dân bị xiềng xích và bị thương tên là Yakada trên mảnh đất của mình. Khi một mối liên kết kỳ lạ bắt đầu hình thành giữa họ, anh ta tiết lộ những bí mật về thân phận thực sự của cô. Nhận ra chồng của Molly thực sự mất tích, viên cảnh sát mới của thị trấn, Nate Clintoff, bắt đầu nghi ngờ và cử cảnh sát của mình đi điều tra.</p>', 'Full', 1, 'single', 'completed', 43, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Úc', 0, '[{"name":"Leah Purcell","avatar":""},{"name":"Rob Collins","avatar":""},{"name":"Sam Reid","avatar":""},{"name":"Jessica De Gouw","avatar":""},{"name":"Malachi Dower-Roberts","avatar":""},{"name":"Benedict Hardie","avatar":""},{"name":"Harry Greenwood","avatar":""},{"name":"Nicholas Hope","avatar":""},{"name":"Maggie Dence","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Victoria Haralabidou","avatar":""},{"name":"Nash Zammit-Harvey","avatar":""},{"name":"Jobe Zammit-Harvey","avatar":""},{"name":"Tammy Macintosh","avatar":""},{"name":"Magnolia Maymuru","avatar":""},{"name":"Anth","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Drovers Wife","The Drover''s Wife","A Esposa de Drover: A Lenda de Molly Johnson","A Lenda de Molly Johnson","The Legend of Molly Johnson","Molly Johnson","La Leyenda Molly Johnson","The Drover''s Wife: The Legend of Molly Johnson"]', 1784690324260);
