INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hau-phong-bi-an-phan-1', 'Người Hầu Phòng Bí Ẩn (Phần 1)', 'The Cleaning Lady (Season 1)', 'https://phimimg.com/upload/vod/20260410-1/688dead4dccc2616b80a4aae1eb431a0.jpg', 'https://phimimg.com/upload/vod/20260410-1/75cdf5a653f5aaf950ab1756be664552.jpg', '<p>Nội dung bộ phim là câu chuyện về một vị bác sĩ người Campuchia là một người phụ nữ đầy bản lĩnh, tài giỏi nhưng vẫn không thể tự một mình cứu lấy đứa con thân yêu của mình. Cô đã quyết định đưa con đến Mỹ để chữa bệnh. Nhưng trong hành trình đi tìm lại sự sống cho con mình cô đã gặp vô số những khó khăn, sự bất công và cả nguy hiểm khiến cô trở thành một người giúp việc đầy bí hiểm. Liệu cô sẽ làm gì để có thể vượt qua nó?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 14, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Élodie Yung","avatar":""},{"name":"Sebastien LaSalle","avatar":""},{"name":"Valentino LaSalle","avatar":""},{"name":"Eva De Dominici","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["女清洁工","The Cleaning Lady (US)","The Cleaning Lady"]', 1784690324260);
