INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-lap', 'Vòng Lặp', 'The Labyrinth', 'https://phimimg.com/upload/vod/20260409-1/e8f9ddff2e3408880007f9ffe0741961.jpg', 'https://phimimg.com/upload/vod/20260409-1/b5bec073be53853bfa24f5cc29534b58.jpg', '<p>Bộ phim là câu chuyện tại một tuyến vòng tàu điện ngầm của thành phố nọ, Đao Ca, Cao Phi, Hàn Hiểu và một số người khác gặp phải một chuyện kì quái. Họ bị một con quái thú tấn công. Để trốn thoát, ban đầu mọi người đều rất hoảng loạn, phải đến khi đồng đội bị giết, họ mới tỉnh ngộ, đoàn kết như một, cùng nhau chiến đấu với lũ quái vật, và cuối cùng mới thoát được. Toàn bộ câu chuyện hấp dẫn, gay cấn cùng một số yếu tố hài hước vui nhộn khiến câu chuyện trở nên hấp dẫn hơn, đồng thời còn thể hiện phản ứng khác nhau của những con người có thân phận và tính cách khác nhau khi đối mặt với hoạn nạn, cũng như mối quan hệ tình cảm giữa người với người.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Bành Kính Từ","avatar":""},{"name":"Quách Quân","avatar":""},{"name":"Thôi Khả","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Centipede Express","Huan xian","Loop Line","环线"]', 1784690324261);
