INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-nu-dac-canh', 'Tôi Là Nữ Đặc Cảnh', 'Female Special Police Officer (I Am A Female Special Weapons And Tactics)', 'https://phimimg.com/upload/vod/20260409-1/1e839e10244e243b180f5bd293c4d958.jpg', 'https://phimimg.com/upload/vod/20260409-1/7f201afcf7ab9deb23be288cda784d80.jpg', '<p>Bộ phim xoay quanh nữ cảnh sát đặc nhiệm Thịnh Nam. Trong một lần tham gia triển lãm trang sức, cô vô tình đối mặt với nhóm cướp hung tợn đang bắt giữ con tin. Với bản lĩnh của một đặc nhiệm, Thịnh Nam đã vượt qua mọi khó khăn, phối hợp cùng đồng đội dưới sự chỉ đạo của lãnh đạo cục. Dựa vào kỹ năng tác chiến thượng thừa và tâm lý vững vàng, cô đã phản công ngoạn mục giữa những cạm bẫy và âm mưu ám sát hiểm độc. Như một lưỡi dao sắc bén và bộ giáp kiên cường, Thịnh Nam chiến đấu hết mình, giáng đòn chính xác để đập tan âm mưu của nhóm tội phạm tài chính quốc tế, tóm gọn toàn bộ băng đảng.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Mẫu Kỳ Di Nhã","avatar":""},{"name":"Trình Khải Mông","avatar":""},{"name":"Ngụy Tử Thiên","avatar":""},{"name":"Quách Dã","avatar":""},{"name":"Bao Á Minh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Female Special Police Officer","I Am a SWAT Woman","I Am a Special Policewoman","1 am A Female Special Weapons And Tactics","我是女特警"]', 1784690324261);
