INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-la-chung-nha', 'Người Lạ Chung Nhà', 'My Perfect Roommate', 'https://phimimg.com/upload/vod/20260409-1/68295bd771a1386722131b7697803da4.jpg', 'https://phimimg.com/upload/vod/20260409-1/ea1b0ea462e78777ec8bb7ec5ad127f6.jpg', '<p>Một học sinh mồ côi đến sống với một bà lão khắc khổ, tự cô lập và không tin tưởng bất kỳ ai. Trải qua nhiều thăng trầm và nhiều khúc mắc được tháo gỡ, cả hai đã tìm thấy sự ấm áp từng đánh mất.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Na Moon-hee","avatar":""},{"name":"Choi Woo-sung","avatar":""},{"name":"Choi Sun-ja","avatar":""},{"name":"Kim Kang-min","avatar":""},{"name":"Moon Dong-hyeok","avatar":""},{"name":"Lee Dong-kyu","avatar":""},{"name":"Kim Sol-bi","avatar":""},{"name":"Seo Ju-hyeong","avatar":""},{"name":"An Kil-kang","avatar":""},{"name":"Jeong In-gi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Room Sharing","花漾奶奶金難搞","跨代同居","룸 쉐어링"]', 1784690324261);
