INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vao-ma-gioi-roi-day-irumakun-phan-3', 'Vào Ma Giới Rồi Đấy! Iruma-Kun (Phần 3)', 'Welcome To Demon School! Iruma-kun (Season 3)', 'https://phimimg.com/upload/vod/20251026-1/4126137d5b4bc818b2b14cd290f552a8.jpg', 'https://phimimg.com/upload/vod/20251026-1/2224fb8b3b2a0226a957edf3355d1664.jpg', '<p>Câu chuyện kể về Ikoma, một cậu bé 14 tuổi đã bị cha mẹ mình bán cho ác ma để đạt được những điều họ muốn. Tuy nhiên, ác ma đã mua cậu về vốn không có cháu trai nối dõi nên ông rất yêu mến Ikoma và gửi cậu vào trường học ác ma.</p>', 'Hoàn Tất (21/21)', 21, 'hoathinh', 'completed', 14, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Ayaka Asai","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Takuya Sato","avatar":""},{"name":"Takaya Kuroda","avatar":""},{"name":"Mitsuki Saiga","avatar":""},{"name":"Yoshitaka Yamaya","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Tetsuya Kakihara","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Gakuto Kajiwara","avatar":""},{"name":"Takuto Yoshinaga","avatar":""},{"name":"Genki Okawa","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Junko Takeuchi","avatar":""},{"name":"Shin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Iruma à l’école des démons","डेमन स्कूल में आपका स्वागत है! इरुमा-कुन","Mairimashita! Iruma-kun","Mairimashita! Iruma-kun 2","Mairimashita, Iruma-kun","Mairimashita, Iruma-kun 2","Mairimashita! Iruma-kun 3","魔入りました！入間くん４","마계학교 이루마군","악마에 입문했습니다! 이루마 군","마계학교! 이루마군","Iruma w szkole demonów","อิรุมะคุงกับโรงเรียนปิศาจ","Welcome to Demon-School, Iruma-kun","Welcome to Demon School, Iruma-kun","The Demon, Iruma-kun, Came and Enrolled!","Enrolled Demon Iruma!","Here Comes the Demon! Iruma-Kun","Welcome to Demon School! Iruma-kun 2","Welcome to Demon-School! Iruma-kun 3","Vào Ma Giới Rồi Đấy","Vào Ma Giới Rồi Đấy! Iruma-kun","Vào Ma Giới Rồi Đấy Iruma-kun","魔入りました！入間くん"]', 1784690324261);
