INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vao-ma-gioi-roi-day-irumakun-phan-3', 'Vào Ma Giới Rồi Đấy! Iruma-Kun (Phần 3)', 'Welcome To Demon School! Iruma-kun (Season 3)', 'vào ma giới rồi đấy! iruma-kun (phần 3) welcome to demon school! iruma-kun (season 3) ayumu murase ryohei kimura ayaka asai daisuke ono saori hayami takuya sato takaya kuroda mitsuki saiga yoshitaka yamaya nao toyama tetsuya kakihara kaede hondo gakuto kajiwara takuto yoshinaga genki okawa shunichi toki junko takeuchi shin iruma à l’école des démons डेमन स्कूल में आपका स्वागत है! इरुमा-कुन mairimashita! iruma-kun mairimashita! iruma-kun 2 mairimashita, iruma-kun mairimashita, iruma-kun 2 mairimashita! iruma-kun 3 魔入りました！入間くん４ 마계학교 이루마군 악마에 입문했습니다! 이루마 군 마계학교! 이루마군 iruma w szkole demonów อิรุมะคุงกับโรงเรียนปิศาจ welcome to demon-school, iruma-kun welcome to demon school, iruma-kun the demon, iruma-kun, came and enrolled! enrolled demon iruma! here comes the demon! iruma-kun welcome to demon school! iruma-kun 2 welcome to demon-school! iruma-kun 3 vào ma giới rồi đấy vào ma giới rồi đấy! iruma-kun vào ma giới rồi đấy iruma-kun 魔入りました！入間くん', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ty-gia-dinh-bat-dong-san-hang-sang-phan-2', 'Công Ty Gia Đình Bất Động Sản Hạng Sang (Phần 2)', 'The Parisian Agency Exclusive Properties (Season 2)', 'https://phimimg.com/upload/vod/20260406-1/175b316943812dc1548898deaf575d20.jpg', 'https://phimimg.com/upload/vod/20260406-1/51410a00b3604a56b189c41007a15c20.jpg', '<p>Series thực tế này theo chân gia đình Kretz và công việc kinh doanh bất động sản xa xỉ của họ, khi họ giúp đỡ các khách hàng mua và bán những dinh thự tuyệt mỹ tại Pháp cũng như trên toàn thế giới.</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 18, 2022, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Olivier Kretz","avatar":""},{"name":"Sandrine Kretz","avatar":""},{"name":"Martin Kretz","avatar":""},{"name":"Valentin Kretz","avatar":""},{"name":"Louis Kretz","avatar":""},{"name":"Raphaël Kretz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["巴黎地产家族：热门豪宅","L''Agence - L''immobilier de luxe en famille"]', 1784690324261);
