INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soundtrack-1', 'Soundtrack #1', 'Soundtrack #1', 'https://phimimg.com/upload/vod/20260401-1/0dd460970d28f61ffd4bae070c23bb46.jpg', 'https://phimimg.com/upload/vod/20260401-1/f8dcca45fed48ed351b2add363081730.jpg', '<p>Han Sun-Woo (Park Hyung-Sik) là một nhiếp ảnh gia trẻ. Anh ấy ít nói nhưng là một người đàn ông tốt bụng và ấm áp. Anh ấy là bạn với Lee Eun-Soo (Han So-Hee). Họ là bạn thân của nhau được 20 năm. Trong khi đó, Lee Eun Soo làm công việc viết lời bài hát để kiếm sống. Cô ấy có một tính cách trung thực và tươi sáng. Vì một lý do, Han Sun-Woo và Lee Eun-Soo bắt đầu sống chung một nhà trong 2 tuần. Ở bên nhau, mối quan hệ của họ phát triển một cách lãng mạn.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 19, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hyung-sik","avatar":""},{"name":"Han So-hee","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Kim Ju-hun","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Kim Do-shin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["单恋原声带","사운드트랙 넘버원","Саундтрек #1","Soundtrack No.1","사운드트랙 #1"]', 1784690324261);
