INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-that-tou-qi', 'Đầu Thất (Tou Qi)', 'The Funeral', 'https://phimimg.com/upload/vod/20260324-1/13da31cc56c2c43543a4b5a45812aaaa.jpg', 'https://phimimg.com/upload/vod/20260324-1/082b2a8b188737ed474fdcf44330e443.jpg', '<p>Nữ chính Xuân Hoa, người đã rời bỏ gia đình và cắt đứt quan hệ với cha mình suốt nhiều năm, bất ngờ nhận được tin ông nội qua đời. Cực chẳng đã, cô đành phải dẫn theo con gái nhỏ quay trở về quê cũ để tham gia nghi lễ &quot;Đầu Thất&quot; cho ông nội. Người cha đã nhiều năm không gặp vẫn giữ thái độ lạnh nhạt, thậm chí có phần thô bạo, không hề dành cho Xuân Hoa và cháu ngoại lấy một sắc mặt tốt. Tuy nhiên, khi màn đêm buông xuống, trong căn nhà cũ dường như lại ẩn chứa một bí mật còn kinh khủng hơn thế. Vào đúng ngày Đầu Thất, thứ thực sự quay trở về lại chính là...</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Nhậm Gia Huyên","avatar":""},{"name":"Trần Dĩ Văn","avatar":""},{"name":"Cao Vũ Dung","avatar":""},{"name":"Trần Gia Quỳnh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["مراسم تدفین","The Funeral","頭七"]', 1784690324261);
