INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-phong-bong-toi-phan-1', 'Cuồng Phong Bóng Tối (Phần 1)', 'Dark Winds (Season 1)', 'https://phimimg.com/upload/vod/20251216-1/c2541f1c7152dfb4dc166feaa1377cf0.jpg', 'https://phimimg.com/upload/vod/20251216-1/1fa3f92645d2f50a2a875246650e2817.jpg', '<p>Bộ phim kinh dị tâm lý này theo chân hai cảnh sát Navajo, Leephorn và Chee, ở Tây Nam những năm 1970 khi họ tìm kiếm manh mối trong một vụ án giết người kép rùng rợn buộc họ phải thách thức niềm tin tâm linh của chính mình và đối mặt với những tổn thương trong quá khứ của họ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zahn McClarnon","avatar":""},{"name":"Kiowa Gordon","avatar":""},{"name":"Jessica Matten","avatar":""},{"name":"Deanna Allison","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dark Winds - Der Wind des Bösen","Dark Winds"]', 1784690324261);
