INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-soi-ban', 'Cây Sồi Bần', 'Suro', 'https://phimimg.com/upload/vod/20260311-1/a091e2b4138fba1bec32011eb35ead47.jpg', 'https://phimimg.com/upload/vod/20260311-1/83be0ee032b5706f29c30aeee49e6482.jpg', '<p>Khi chuẩn bị chào đón đứa con đầu lòng, Helena và Iván quyết định rời bỏ nhịp sống đô thị để chuyển về vùng nông thôn Catalonia, nơi họ thừa kế một đồn điền sồi bần. Họ tin rằng giữa rừng cây và đất đai màu mỡ, mình có thể gây dựng một cuộc sống bình yên và vững vàng hơn cho gia đình nhỏ. Thế nhưng, thực tế khắc nghiệt của công việc, áp lực tài chính và những khác biệt âm thầm dần thử thách tình yêu của họ. Giấc mơ về mái ấm giữa thiên nhiên vì thế trở thành hành trình học cách thấu hiểu và cùng nhau trưởng thành.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Pol López","avatar":""},{"name":"Victoria Luengo","avatar":""},{"name":"Ilyass El Ouahdani","avatar":""},{"name":"Josep Estragués","avatar":""},{"name":"David Parcet","avatar":""},{"name":"Vicente Botella","avatar":""},{"name":"Josep Maria Gómez","avatar":""},{"name":"Irina Moradell","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Suro"]', 1784690324261);
