INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('roise-va-frank', 'Roise và Frank', 'Róise & Frank', 'https://phimimg.com/upload/vod/20260311-1/1d74dd0f6008e3e5f8183e028de94ec8.jpg', 'https://phimimg.com/upload/vod/20260311-1/20010495945b428a46a8483c3846b616.jpg', '<p>Roise chìm trong nỗi đau sau sự ra đi của chồng, sống lặng lẽ giữa ký ức chưa nguôi. Một ngày, một con chó lạc bất ngờ xuất hiện và kiên trì đi theo bà khắp nơi. Sự gắn bó kỳ lạ ấy khiến Roise tin rằng đó là hiện thân của người chồng đã khuất trở về bên mình. Giữa ranh giới của mất mát và niềm tin, bà dần tìm thấy sự an ủi, như thể tình yêu vẫn còn hiện diện theo một cách khác.</p>', 'Full', 1, 'single', 'completed', 33, 2022, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Bríd Ní Neachtain","avatar":""},{"name":"Cillian O''Gairbhi","avatar":""},{"name":"Lorcan Cranitch","avatar":""},{"name":"Ruadhán de Faoite","avatar":""},{"name":"Michelle Beamish","avatar":""},{"name":"Claire O''Connor","avatar":""},{"name":"Peadar Cox","avatar":""},{"name":"Deaglan de Paor","avatar":""},{"name":"Cormac Hennessy","avatar":""},{"name":"Seán Mac Gearailt","avatar":""},{"name":"Áine Ní Mhuirí","avatar":""},{"name":"Jim Cunningham","avatar":""},{"name":"Elaine O''Hara","avatar":""},{"name":"Aonghus Og McAnally","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Mo Ghrá Buan","Róise and Frank","萝榭与弗兰克","Róise & Frank"]', 1784690324261);
