INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('roise-va-frank', 'Roise và Frank', 'Róise & Frank', 'roise và frank róise & frank bríd ní neachtain cillian o''gairbhi lorcan cranitch ruadhán de faoite michelle beamish claire o''connor peadar cox deaglan de paor cormac hennessy seán mac gearailt áine ní mhuirí jim cunningham elaine o''hara aonghus og mcanally mo ghrá buan róise and frank 萝榭与弗兰克 róise & frank', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lu-khach-cuoi-dem-dai', 'Lữ Khách: Cuối Đêm Dài', 'The Traveller: At The End Of The Night', 'https://phimimg.com/upload/vod/20260311-1/582ec8850fc315524b161eb751d350db.jpg', 'https://phimimg.com/upload/vod/20260311-1/f6993b23796a2e29d44045aeb751d3c4.jpg', '<p>Laurent - em trai của Đại úy Kandinsky - vướng vào mâu thuẫn căng thẳng với một cô gái trẻ, người công khai tố anh quấy rối. Bi kịch xảy ra khi cô gái được phát hiện đã chết vào sáng hôm sau, khiến mọi ánh mắt nghi ngờ lập tức hướng về Laurent. Giữa áp lực dư luận và vòng xoáy điều tra, Kandinsky rơi vào thế khó khi phải đứng giữa ranh giới công lý và tình thân. Anh buộc phải lần theo từng manh mối để tìm ra sự thật, trước khi định kiến và những lời buộc tội biến em trai mình thành “vị vua trần truồng” giữa cơn bão phán xét.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Romain Faure","avatar":""},{"name":"Mathis Deblock","avatar":""},{"name":"Jules Didner","avatar":""},{"name":"Mehdi Slaoui","avatar":""},{"name":"Elisabeth Tricot","avatar":""},{"name":"Gabin Grandgirard","avatar":""},{"name":"Réma Moudiongui","avatar":""},{"name":"Ivan Suly","avatar":""},{"name":"Téo Serralunga","avatar":""},{"name":"Clément Berthelot","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Au bout de la nuit"]', 1784690324261);
