INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-khoi-lac-duong-coi-am-duong', 'Phong Khởi Lạc Dương: Cõi Âm Dương', 'Reincarnation Land', 'https://phimimg.com/upload/vod/20260308-1/ba879af1dd72a05dd8d67aa8da9c3cfe.jpg', 'https://phimimg.com/upload/vod/20260308-1/ba6725e01efb068a3e333d830e4b0824.jpg', '<p>Thời Ngô Chu, hai cô gái sống ở hai đầu sông Lạc Hà ở Lạc Dương, thuộc hai thân phận khác nhau vô tình vướng vào một vụ án chưa được giải quyết, họ cùng nhau vạch trần âm mưu của kẻ ác. Hai cô gái đó là Triệu Thanh Thanh - con gái của Kim Ngô và một cô gái lừa đảo cuộc sống lưu bạt. Hai người hhai số phận khác nhau, sau khi gặp phải hàng loạt vụ án kỳ quái ở thành phố Lạc Dương đã trở thành bạn bè. Họ cùng nhau trải qua những khó khăn, nhưng vẫn giữ được tinh thần chính nghĩa, can đảm, trong một thế giới hỗn loạn.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nam Tinh","avatar":""},{"name":"Trương Gia Hàng","avatar":""},{"name":"Trương Xuân Trung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Wind Rises in Luoyang","Feng Qi Luo Yang Zhi Yin Yang Jie","Feng Qi Luo Yang","Storm Over Luoyang: Yin and Yang Realm","风起洛阳之阴阳界"]', 1784690324261);
