INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-den-ben-em-voi-van-toc-493km', 'Chạy Đến Bên Em Với Vận Tốc 493Km', 'Love All Play', 'https://phimimg.com/upload/vod/20260308-1/81b639680c6ad3a04c6b25cb398e5cca.jpg', 'https://phimimg.com/upload/vod/20260308-1/f0d84b5054b0a7dba0742afb0f186419.jpg', '<p>Bộ phim tình cảm thể thao miêu tả niềm đam mê và tình cảm với cầu lông của một nam và nữ nhân vật chính là một nhóm đôi nam nữ với những người chơi từ đội kinh doanh cầu lông. Park Tae Joon, người tự nhiên bén duyên với thế giới cầu lông vì công việc kinh doanh thiết bị cầu lông của cha mẹ anh. Mặc dù anh ấy đã bắt đầu coi môn thể thao này là công việc, nhưng niềm đam mê cầu lông của anh ấy lại được khơi dậy do mong muốn gây ấn tượng với một người phụ nữ. Park Tae Yang là cựu vận động viên điền kinh, người đã phải rời bỏ làng cầu lông thế giới trong ba năm vì một vụ bê bối hối lộ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 12, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Ju-hyun","avatar":""},{"name":"Chae Jong-hyeop","avatar":""},{"name":"Park Ji-hyun","avatar":""},{"name":"Kim Moo-joon","avatar":""},{"name":"Seo Ji-hye","avatar":""},{"name":"Cho Han-cheul","avatar":""},{"name":"In Gyo-jin","avatar":""},{"name":"Lee Seo-hwan","avatar":""},{"name":"Choi Seung-yoon","avatar":""},{"name":"Cho Soo-hyang","avatar":""},{"name":"Moon Dong-hyeok","avatar":""},{"name":"Kwon So-hyun","avatar":""},{"name":"Jeon Hye-won","avatar":""},{"name":"Lee Chae-min","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Sung Ki-yoon","avatar":""},{"name":"Park Doo-sik","avatar":""},{"name":"Bin Chan-u","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","i