INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-hoang-metal', 'Ông Hoàng Metal', 'Metal Lords', 'https://phimimg.com/upload/vod/20260307-1/96aa6a2608a5ca40c644dec86f11ec55.jpg', 'https://phimimg.com/upload/vod/20260307-1/e040ce22ceefa413c7c889c49764ac74.jpg', '<p>Hai đứa trẻ muốn bắt đầu một ban nhạc heavy metal ở một trường trung học và chúng đều thích heavy metal. Giấc mơ của Hunter là giành chiến thắng trong Trận chiến của các ban nhạc, anh ấy biết rất rõ lịch sử và ngã ba của mình. Kevin được bạn mình mời chơi trống. Rất khó để tìm một người chơi bass vì các bạn cùng trường quan tâm đến ngôi sao nhạc pop hơn Black Sabbath. Emily đang chơi cello thì Kevin tình cờ nghe được cô ấy. Phi hành đoàn motley phải cạnh tranh với trường học, cha mẹ, kích thích tố và những cơn giận dữ của thanh thiếu niên trong khi cố gắng duy trì hòa hợp đủ lâu để Skullf * cker giành chiến thắng trong Trận chiến của các ban nhạc</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jaeden Martell","avatar":""},{"name":"Adrian Greensmith","avatar":""},{"name":"Isis Hainsworth","avatar":""},{"name":"Noah Urrea","avatar":""},{"name":"Brett Gelman","avatar":""},{"name":"Analesa Fisher","avatar":""},{"name":"Michelle Mao","avatar":""},{"name":"Phelan Davis","avatar":""},{"name":"Austin Huynh","avatar":""},{"name":"Joe Manganiello","avatar":""},{"name":"Teddy Van Ee","avatar":""},{"name":"Aroon Nagappan","avatar":""},{"name":"Kieran Thomas","avatar":""},{"name":"Jonathan Saks","avatar":""},{"name":"Sufe Bradshaw","avatar":""},{"name":"Jalon Howard","avatar":""},{"name":"Jeff Steitzer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c