INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('formula-1-cuoc-dua-song-con-phan-4', 'Formula 1: Cuộc Đua Sống Còn (Phần 4)', 'Formula 1: Drive To Survive (Season 4)', 'formula 1: cuộc đua sống còn (phần 4) formula 1: drive to survive (season 4) max verstappen lewis hamilton charles leclerc sergio pérez george russell carlos sainz jr. nico hülkenberg lando norris esteban ocon fernando alonso valtteri bottas daniel ricciardo kevin magnussen pierre gasly lance stroll 角田裕毅 oscar pias f1: dirigir para viver formule 1: touha po vítězství formule 1 : pilotes de leur destin formula 1：極速求生 פורמולה 1: המרוץ לניצחון формула 1: гонять, чтобы выживать formula 1 รถแรงแซงชีวิต формула 1: ганяти, щоб виживати формула 1: їзда заради виживання formula 1 drive to survive formula 1: cuộc đua sống còn formula 1: drive to survive', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-ma-dau-lo-tay-roi-phan-2', 'Tiểu Ma Đầu Lộ Tẩy Rồi (Phần 2)', 'Busted! Darklord (Season 2)', 'https://phimimg.com/upload/vod/20260228-1/793f6ea6279d8098f117a9a2b061784f.jpg', 'https://phimimg.com/upload/vod/20260228-1/04f26c793b9fa8dea369e2b6130f141c.jpg', '<p>Để sống tiếp trên giang hồ, con trai giáo chủ ma giáp Vu Nhân Kiệt nhận lệnh trà trộn vào “học viện chính đạo” chỉ tuyển đệ tử danh môn chính phái, mục tiêu để giành được “chứng nhận người tốt” nằm rửa sạch thân phận ma giáo. Chuyến đi này cực kỳ hung hiểm, một khi bị lộ thâm phận ma giáo thì sẽ bị vô số hiệp khách chính đạo giết ngay tại chỗ. Nhưng hôm báo cáo, Vu Nhân Kiệt xấu hổ phát hiện thông tin cá nhân của mình sớm đã bị người tra điều tra rõ mồn một rồi, vì để che giấu thân phận anh cuối cùng chọn… mặc áo quần con gái. Cuộc sống vườn trường hung hiểm lại hài hước sắp bắt đầu.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 17, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiao Mo Tou Baolu La","Xiao Mo Tou Bao Lu La !","Xiao Mo Tou Baolu La!","Xiǎo Mó Tóu Bàolù La!","Busted! Darklord","Busted Darklord","Tiểu Ma Đầu Lộ Tẩy Rồi","小魔头暴露啦！"]', 1784690324261);
