INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-bep-dia-nguc-phan-21', 'Nhà Bếp Địa Ngục (Phần 21)', 'Hell''s Kitchen (Season 21) (Battle Of The Ages)', 'https://phimimg.com/upload/vod/20250721-1/7b39d87e450bb183f8da59886072d3dd.jpg', 'https://phimimg.com/upload/vod/20250721-1/cc890d42db9a51704ce89cb5ab20987b.jpg', '<p>Những đầu bếp đầy tham vọng phải đối mặt với Ramsay và sự chỉ huy nóng nảy của ông trong căn bếp, khi ông đưa các thí sinh trải qua một học viện ẩm thực khắc nghiệt để chứng minh rằng họ sở hữu sự kết hợp hoàn hảo các yếu tố cần thiết để giành được giải thưởng lớn thay đổi cuộc đời.</p>', 'Hoàn Tất (16/16)', 16, 'tvshows', 'completed', 20, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gordon Ramsay","avatar":""},{"name":"James Avery","avatar":""},{"name":"Marino Monferrato","avatar":""},{"name":"Michelle Tribble","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Hells Kitchen (US)","Hell''s Kitchen (US)","헬스 키친","Hell''s Kitchen"]', 1784690324261);
