INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-hoa-hong', 'Kỵ Sĩ Hoa Hồng', 'Knight Of The Rose', 'https://phimimg.com/upload/vod/20260221-1/7d403ad76fc62583936803b7e38d2be7.jpg', 'https://phimimg.com/upload/vod/20260221-1/cbfb6474a12d113198c4f8d795bd0ad1.jpg', '<p>Bộ phim kể về câu chuyện tình yêu giữa một cô gái từng là lính đặc công và một vị tổng tài lạnh lùng, trí tuệ. Xuất thân từ môi trường quân đội nghiêm khắc, cô mạnh mẽ, dứt khoát và sở hữu kỹ năng chiến đấu xuất sắc. Ngược lại, anh là CEO của một tập đoàn lớn, điềm tĩnh, lý trí và luôn giữ khoảng cách với mọi người xung quanh. Hai người vốn sống trong hai thế giới hoàn toàn khác biệt, nhưng một sự cố bất ngờ đã khiến họ gặp nhau khi cô vô tình can thiệp vào một vụ cướp có liên quan đến anh.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 17, 2022, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hoan","avatar":""},{"name":"Lý Thục Tình","avatar":""},{"name":"Tần Hiểu Hiên","avatar":""},{"name":"Trần Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Mei Gui Qi Shi","玫瑰骑士"]', 1784690324261);
