INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-vo-hinh-cong-ly-mu', 'Tội Ác Vô Hình (Công Lý Mù)', 'Blind', 'https://phimimg.com/upload/vod/20260218-1/1dede7fa59f070a12ca000b3ebd6ad00.jpg', 'https://phimimg.com/upload/vod/20260218-1/4aec5178300ef5a8de3179f249b72b74.jpg', '<p>Ryu Sung Joon là một thanh tra đầy nhiệt huyết và quyết tâm truy bắt những kẻ xấu. Jo Eun Ki là nhân viên xã hội với một trái tim ấm áp, luôn tin vào công lý. Còn Ryu Sung Hoon, anh trai của Sung Joon, là một vị thẩm phán đầy tài năng, luôn đưa ra những phán xét công bằng. Ba người vô tình dính vào một vụ án giết người hàng loạt mà nạn nhân là các thành viên của bồi thẩm đoàn và cùng nhau giải mã bí ẩn đằng sau những vụ án này.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 16, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ok Taec-yeon","avatar":""},{"name":"Ha Seok-jin","avatar":""},{"name":"Jung Eun-ji","avatar":""},{"name":"Park Ji-bin","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Kim Pub-lae","avatar":""},{"name":"Kang Na-eon","avatar":""},{"name":"Oh Seung-yun","avatar":""},{"name":"Choi Hong-il","avatar":""},{"name":"Jo Kyung-sook","avatar":""},{"name":"Baek Seoung-hee","avatar":""},{"name":"Cho Seung-yeon","avatar":""},{"name":"Kim Ha-kyoon","avatar":""},{"name":"Choi Jae-sup","avatar":""},{"name":"Chae Dong-hyeon","avatar":""},{"name":"Song Yi-hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["局中人","Blind (2022)","블라인드","Blind局中人","BLIND 局中人","Blind"]', 1784690324261);
