INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-so-do', 'Quý Ông Số Đỏ', 'Gentleman', 'https://phimimg.com/upload/vod/20260217-1/98615c32fc775839bffccbfd0b5ef7f2.jpg', 'https://phimimg.com/upload/vod/20260217-1/78df27c84eafdf2c988f8f46a1b3ccfd.jpg', '<p>Ji Hyun Soo, Giám đốc điều hành của một công ty thám tử tư. Trong một lần thực hiện công việc, anh ta bị vu cáo là bắt cóc khách hàng. Trong thời gian Hyeon-soo bị bắt, một vụ tai nạn xe hơi nghiêm trọng xảy ra và mọi người hiểu nhầm Hyeon-soo là công tố viên thay vì nghi phạm. Để tìm ra tên tội phạm thực sự, Hyeon-soo quyết định giả làm công tố viên. Tại đây anh đã gặp Hwa-jin, một công tố viên ưu tú bị giáng chức khi cố gắng truy bắt tập đoàn luật Do-hoon, gặp Hyeon-soo. Cả hai bắt đầu hợp tác với nhau, và họ nhận ra rằng có một sự thật ẩn sau tội ác.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ju Ji-hoon","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Choi Sung-eun","avatar":""},{"name":"Park Hae-eun","avatar":""},{"name":"Kang Hong-suk","avatar":""},{"name":"Lee Dal","avatar":""},{"name":"Kwon Han-sol","avatar":""},{"name":"Lee Seo-hwan","avatar":""},{"name":"Park Ji-hoon","avatar":""},{"name":"Pyo Young-seo","avatar":""},{"name":"Im Sung-jae","avatar":""},{"name":"Lee Hyun-kyun","avatar":""},{"name":"Han Sa-myeong","avatar":""},{"name":"Na Gyeong-cheol","avatar":""},{"name":"Kim Seung-bee","avatar":""},{"name":"Salim Benoit","avatar":""},{"name":"Kwak Min-kyu","avatar":""},{"name":"Kim Nan-hee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c