INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-trung-hoa-phong-van-tai-khoi-2022', 'Anh Hùng Trung Hoa: Phong Vân Tái Khởi', 'A Man Called Hero', 'https://phimimg.com/upload/vod/20260215-1/d1443523ece7b265e911d1da55af3fae.jpg', 'https://phimimg.com/upload/vod/20260215-1/6cf73a8b749491536f93c72f475ea437.jpg', '<p>Để bảo vệ Trung Hoa Ngạo Quyết và trong cuộc chiến ác liệt, vào lúc hấp hối Kim Ngạo đã chuyển giao Trung Hoa Ngạo Quyết cho anh hùng Hoa. Anh hùng Hoa người được mệnh danh là &quot;Thiên Sát Cô Tinh&quot;, khi cha mẹ và vợ mất, anh rời xa con cái bạn bè chuyên tâm tập luyện 20 năm nhưng vẫn không thể thành thạo Trung Hoa Ngạo Quyết. Cuối cùng, trong trận chiến ác liệt anh đã hiểu ra và giành thắng lợi.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Binh","avatar":""},{"name":"Viên Phúc Phúc","avatar":""},{"name":"Lý Mục Vân","avatar":""},{"name":"Vương Tử Đồng","avatar":""},{"name":"Tôn Giao Long","avatar":""},{"name":"Lưu Hạo Tuấn Long","avatar":""},{"name":"Quách Chỉ Nghiên","avatar":""},{"name":"Trương Tân Đồng","avatar":""},{"name":"Cao Tử Cương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Man Called Hero","中华英雄之风云再起"]', 1784690324261);
