INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hung-long-phong-ba-phan-1', 'Hùng Long Phong Bá (Phần 1)', 'Brothers For Life (Season 1)', 'https://phimimg.com/upload/vod/20240326-1/b79cdc640456a8ba8068ffa73d5ded89.jpg', 'https://phimimg.com/upload/vod/20240326-1/d9047c849f5fb53fe278a581636a9afb.jpg', '<p>Phim xoay quanh hành trình của 4 chàng trai quê gồm Hùng (Tùng Min), Long (Steven Nguyễn), Phong (Võ Đình Hiếu), Bá (Trầm Minh Hoàng) bước chân lên thành phố với đầy tham vọng, nhưng trớ trêu thay cả 4 người bạn đều vô tình vướng vào một cuộc chiến của thế giới ngầm, để rồi đánh mất chính mình cùng tình anh em bao lâu gắn bó.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 25, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Tùng Min","avatar":""},{"name":"Steven Nguyễn","avatar":""},{"name":"Trầm Minh Hoàng","avatar":""},{"name":"Võ Đình Hiếu","avatar":""},{"name":"NSƯT Công Ninh","avatar":""},{"name":"Tiểu Bảo Quốc","avatar":""},{"name":"Quách Ngọc Tuyên","avatar":""},{"name":"Thanh Hoa","avatar":""},{"name":"Phan Ngân","avatar":""},{"name":"Vũ Ngọc Anh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324261);
