INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ong-2022', 'Đường Ống (Dò tìm lối thoát)', 'Crawlspace', 'https://phimimg.com/upload/vod/20260210-1/1c481cec9400f6214deacf613fa54c95.jpg', 'https://phimimg.com/upload/vod/20260210-1/071290660f37f2d33e6ed2472a83dcbe.jpg', '<p>Sau khi chứng kiến một vụ giết người tàn bạo trong một căn nhà gỗ, một người đàn ông trốn trong một không gian đường ống để thu thập thông tin trong khi những kẻ giết người lùng sục tài sản để tìm một tài sản giấu kín. Khi họ đến gần hơn, anh ta phải quyết định xem không gian chật hẹp này sẽ là lăng mộ của anh ta hay chiến trường trong cuộc chiến sinh tồn của anh ta.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Henry Thomas","avatar":""},{"name":"Bradley Stryker","avatar":""},{"name":"C. Ernst Harth","avatar":""},{"name":"Jennifer Robertson","avatar":""},{"name":"Olivia Taylor Dudley","avatar":""},{"name":"Catherine Lough Haggquist","avatar":""},{"name":"Joe Costa","avatar":""},{"name":"Colin Decker","avatar":""},{"name":"Andrei Kovski","avatar":""},{"name":"Charles Jarman","avatar":""},{"name":"Fletcher Donovan","avatar":""},{"name":"Justin Lacey","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["마루 밑 배관공","Crawlspace: Em Confinamento","Tarama Alanı","Підвал","Crawlspace"]', 1784690324261);
