INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-ma-tuy', 'Thợ Săn Ma Túy', 'Drug Hunter', 'https://phimimg.com/upload/vod/20260208-1/87f4de1e0cebea35731f0a1234a2ad30.jpg', 'https://phimimg.com/upload/vod/20260208-1/d654b6803e29783bded257834aca74c4.jpg', '<p>Trong một chiến dịch phòng chống ma túy ở một thành phố nọ, đội trưởng đội phòng chống ma túy Vũ Phàm và đồng đội của anh đã thu giữ một lô ma túy nguyên chất từ Tam Giác Vàng. Tuy nhiên, cả hai bên giao dịch đều vô cùng xảo quyệt và có khả năng chống trinh sát mạnh mẽ, nên không để lại bất kì dấu tích, manh mối nào. Sau hàng loạt cuộc điều tra và phân tích đánh giá tỉ mỉ, Vũ Phàm và đội phòng chống ma túy băt đầu nhắm tới với Lý Dũng- người cầm đầu phụ trách phân phối ma túy. Sau sự nỗ lực và nhiều lần đổ máu trả giá bằng tính mạng thì cuối cùng họ đã tìm ra một đường dây buôn bán ma túy, và thành công thâm nhập vào đường dây buôn bán ma túy bí ẩn này. Vũ Phàm và đồng đội chia thành nhiều nhóm và lên kế hoạch bắt gọn tội phạm buôn ma túy trong lần giao dịch tiếp theo. Cuối cùng, đường dây buôn bán ma túy đã bị tiêu diệt.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cần Hạo","avatar":""},{"name":"Bành Bột","avatar":""},{"name":"Đinh Hải Phong","avatar":""},{"name":"Kenny","avatar":""},{"name":"Tony","avatar":""},{"name":"Chun Yu Shan Shan","avatar":""},{"name":"Cristina","avatar":""},{"name":"Trịnh Tinh Tinh","avatar":""},{"name":"Triệu Kỉnh Hi","avatar":""},{"name":"Lưu Tinh Hiên","avatar":""},{"name":"Vương Á Bân","avatar":""},{"name":"Tăng Hùng Hào","avatar":""},{"name":"Chu Tân Huy","avatar":""},{"name":"Thôi Khắc","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324261);
