INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quang-dong-thap-ho-nam-dam-sat-bat-kha-chien-bai', 'Quảng Đông Thập Hổ: Nắm Đấm Sắt Bất Khả Chiến Bại', 'Iron Kung Fu Fist (Jiang Hu)', 'https://phimimg.com/upload/vod/20260208-1/db1e604747f754a80eaac67d303026a3.jpg', 'https://phimimg.com/upload/vod/20260208-1/8676b2258f3e44985641160595eb7b28.jpg', '<p>Bộ phim kể về câu chuyện của Lương Khôn, một trong những người của Quảng Đông Thập Hổ người đã luyện tập võ thuật để bảo vệ những người thân yêu của mình. Dù rơi vào bẫy bị hãm hại anh nhưng anh vẫn tiếp tục tìm kiếm sự thật với lòng kiên trì bất diệt của mình. Cuối cùng, anh đã tạo ra năm đấm sắt cho riêng mình và đánh bại thế lực tà ác đứng sau.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Phàn Thiếu Hoàng","avatar":""},{"name":"Tái Mị Nhiệt","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Từ Vĩ Đống","avatar":""},{"name":"Hoàng Vĩ","avatar":""},{"name":"Trần Uy Nhiên","avatar":""},{"name":"Lưu Tích Minh","avatar":""},{"name":"Ngô Quốc Bảo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["广东十虎：铁拳无敌"]', 1784690324261);
