INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ban-dai-ky', 'Nhất Bàn Đại Kỳ', 'Big Three Dragons', 'https://phimimg.com/upload/vod/20260208-1/87432935274280e8eb0e32da4572fa14.jpg', 'https://phimimg.com/upload/vod/20260208-1/6c5f16a24712f3504e4d80f695c23bf8.jpg', '<p>Lão Đoạn từng phải ngồi tù nhiều năm vì nghi án liên quan đến một vụ trọng án năm xưa. Ngay khi vừa ra tù, để làm sáng tỏ chân tướng sự việc, ông đã quyết tâm vạch ra một ván cờ &#39;kế trong kế&#39; vô cùng tinh vi.&nbsp; Nào ngờ, hành động lần này lại lôi kéo cả ba đứa con với ba tính cách hoàn toàn khác biệt của ông và ba người vợ cũ vào cuộc: Ngô Văn, Mạc Mặc và Đường Ninh. Gia đình bốn người này một mặt phải hợp lực chống lại kẻ thù, mặt khác lại không ngừng &#39;bóc phốt&#39; và phá bĩnh lẫn nhau.&nbsp; Liệu đây sẽ là màn &#39;cha con cùng ra trận&#39; của những con cáo già và cáo non, hay là một cuộc rượt đuổi &#39;mèo vờn chuột&#39; đầy rẫy sự lừa lọc? Khi mọi thứ dần vượt khỏi tầm kiểm soát, vở hài kịch trào phúng với vô số những cú lật kèo (twist) này khiến người xem không tài nào đoán trước được nước cờ tiếp theo sẽ đi về đâu...</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Thao","avatar":""},{"name":"Tiểu Thẩm Dương","avatar":""},{"name":"Tuệ Duệ","avatar":""},{"name":"Trương Nghệ Thượng","avatar":""},{"name":"Phạm Minh","avatar":""},{"name":"Dư Ân Thái","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Big Three Dragons","蚂蚁撼大象","弹棉花","Big Thrfe Dragons","一盘大棋"]', 1784690324261);
