INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-mo-mac-kim', 'Lăng Mộ Mạc Kim', 'Touching Gold Captain', 'https://phimimg.com/upload/vod/20260208-1/062883cdc2ebcefed9b14c3fd41bced5.jpg', 'https://phimimg.com/upload/vod/20260208-1/6db8934600f63d67d19980e5f9c61f41.jpg', '<p>Tào Thuận là hậu duệ dòng dõi Mạc Kim Giáo Uý, nhưng cha Tào Thuận chưa bao giờ dạy Tào Thuận bất kỳ kỹ năng nào của giáo uý. Tào Thuận không học hành gì, cậu ta dựa vào miệng lưỡi ngon ngọt để lừa người kiếm sống. Một ngày nọ, một kẻ độc ác vào làng, đích thân chỉ danh yêu cầu dòng dõi của Mạc Kim là Tào Thuận giúp hắn tìm báu vật, nếu từ chối sẽ giết cả làng. Tào Thuận bất đắc dĩ cải trang thành giáo uý cùng bọn chúng tiến vào lăng mộ…</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Lạc Gia","avatar":""},{"name":"Vương Nam Xiêm","avatar":""},{"name":"Bạch Hải Long","avatar":""},{"name":"Đường Tân","avatar":""},{"name":"Lộ Thuận","avatar":""},{"name":"Lý Cao Cơ","avatar":""},{"name":"Tưởng Siêu","avatar":""},{"name":"Đồng Lệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324261);
