INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-mo-mac-kim', 'Lăng Mộ Mạc Kim', 'Touching Gold Captain', 'lăng mộ mạc kim touching gold captain vương lạc gia vương nam xiêm bạch hải long đường tân lộ thuận lý cao cơ tưởng siêu đồng lệ ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-than-do-ma', 'Chiến Thần Đồ Ma', 'Fighting Darksider', 'https://phimimg.com/upload/vod/20260207-1/28aa7995a63e427872a150e87934fa55.jpg', 'https://phimimg.com/upload/vod/20260207-1/7ada7f64e24ff3714abf6a694eb6c61b.jpg', '<p>Hai mươi năm trước, bộ tộc hắc ám đã tấn công loài người. Chiến thần Trương Xích Viêm đã không ngần ngại hy sinh bản thân để đánh thức Thần Kiếm, chỉ để sau đó đánh đuổi hắc ám. Nhưng giờ đây, bộ tộc hắc ám đã trỗi dậy trở lại, đang chuẩn bị tấn công loài người. Để ngăn chặn thảm họa lớn này, các thế hệ sau của Chiến thần Trương Kha, Vân Linh và Phúc Hỉ đã bắt tay vào việc đánh thức Thần Kiếm. Trên con đường chiến đấu và đối mặt với nguy hiểm, Trương Kha và Vân Linh đã bắt đầu nảy sinh tình cảm. Trương Kha cũng trưởng thành hơn và trở thành Chiến thần mới, trong trận đại chiến cuối cùng cũng đã đánh thức Thần Kiếm, lãnh đạo tộc người tiêu diệt thế lực hắc ám.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiết Miêu","avatar":""},{"name":"Thiệu Vân","avatar":""},{"name":"Long Dương Dương","avatar":""},{"name":"Tôn Viên Ninh","avatar":""},{"name":"Canti Lau","avatar":""},{"name":"Nhạc Đông Phong","avatar":""},{"name":"Lý Bân Lễ","avatar":""},{"name":"Thạch Quốc Huy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324261);
