INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-huyen-bi-4-ma-ca-rong-bien-hinh', 'Khách Sạn Huyền Bí 4: Ma Cà Rồng Biến Hình', 'Hotel Transylvania: Transformania', 'https://phimimg.com/upload/vod/20250412-1/767af0fc1d3a2c46a253290454ab2904.jpg', 'https://phimimg.com/upload/vod/20250412-1/2a97079e18535d1386010af00a829d06.jpg', '<p>Khách Sạn Huyền Bí: Ma Cà Rồng Biến Hình là tập phim cuối cùng của thương hiệu với màn hóan đổi thân phận hài hước gây náo loạn cả xứ sở quái vật. Cậu con rể của Dracula đã thành công trong việc tự biến thành quái vật. Thế nhưng, dù có là giống loài nào thì bản tính hậu đậu trời ban vẫn không thể rời xa Johnny.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Andy Samberg","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"David Spade","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Brian Hull","avatar":""},{"name":"Fran Drescher","avatar":""},{"name":"Brad Abrell","avatar":""},{"name":"Asher Blinkoff","avatar":""},{"name":"Tyler Blevins","avatar":""},{"name":"Zoe Berri","avatar":""},{"name":"Genndy Tartakovsky","avatar":""},{"name":"Asher Bishop","avatar":""},{"name":"Jennifer Kluska","avatar":""},{"name":"Vic","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387