INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-doi-thuong-binh-pham-anh-hung', 'Anh Hùng Đời Thường (Bình Phàm Anh Hùng)', 'Ordinary Hero', 'https://phimimg.com/upload/vod/20260202-1/0133d8b5eb915c8640df8472083bde50.jpg', 'https://phimimg.com/upload/vod/20260202-1/d078723b995d99fdbda4c0f6c371ee09.jpg', '<p>Bộ phim được chuyển thể từ cuộc giải cứu và điều trị &quot;Tốc độ sinh tử&quot; cho một cậu bé bị gãy tay ở Hetian, Tân Cương. Các bác sĩ, thành viên phi hành đoàn, hành khách, cảnh sát và những người khác thuộc mọi tầng lớp xã hội ở Tân Cương đã vượt qua 1.400 km, và cuộc sống tiếp sức kéo dài 8 giờ đã tạo nên một điều kỳ diệu của cuộc sống.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Băng Băng","avatar":""},{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Lâm Vĩnh Kiện","avatar":""},{"name":"Trương Nhất Sơn","avatar":""},{"name":"Parman Parlehati","avatar":""},{"name":"Erfan Aziz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["平凡的英雄","Píngfán Yīnxióng","平凡英雄"]', 1784690324261);
