INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-chung-song-cuoi-cung', 'Nhân Chứng Sống Cuối Cùng', 'Last Seen Alive', 'https://phimimg.com/upload/vod/20260202-1/6fab5d397c71f266f286fbcd713abea9.jpg', 'https://phimimg.com/upload/vod/20260202-1/a21aff36ba1d123d0060fc538b471f97.jpg', '<p>Phim xoay quanh câu chuyện của một người đàn ông Will Spann(Gerard Butler thủ vai) và cô vợ sắp cưới Lisa về nhà bố mẹ đẻ của họ. Khi họ dừng lại nghỉ ngơi ở trạm xăng, Lisa đột nhiên biến mất. Will Spann điên cuồng tìm kiếm cô, cũng như đối mặt với cảnh sát và gia đình cô, vì anh không biết cô đang ở đâu. Will phải tự mình tìm cách giải quyết mọi chuyện, cũng như chạy đua với thời gian để tìm ra Lisa trước khi quá muộn, bởi mọi nghi ngờ đều hướng về anh.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Jaimie Alexander","avatar":""},{"name":"Russell Hornsby","avatar":""},{"name":"Ethan Embry","avatar":""},{"name":"Michael Irby","avatar":""},{"name":"Bruce Altman","avatar":""},{"name":"Jordan Salloum","avatar":""},{"name":"Dani Deetté","avatar":""},{"name":"David Kallaway","avatar":""},{"name":"Chip Lane","avatar":""},{"name":"Alphonso A''Qen-Aten Jackson","avatar":""},{"name":"Cindy Hogan","avatar":""},{"name":"Aleks Alifirenko Jr.","avatar":""},{"name":"Emily Brinks","avatar":""},{"name":"Billy Burns","avatar":""},{"name":"Robin Fletch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Местонахождение неизвестно","라스트 씬 얼라이브","آخرین لحظه زندگی","آخرین باری که زنده دیده شد","آخرین حضور زنده","Chase","Chase - Nichts hält ihn auf","Last Seen Alive","Vista Por Última V