INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhan-chung-song-cuoi-cung', 'Nhân Chứng Sống Cuối Cùng', 'Last Seen Alive', 'nhân chứng sống cuối cùng last seen alive gerard butler jaimie alexander russell hornsby ethan embry michael irby bruce altman jordan salloum dani deetté david kallaway chip lane alphonso a''qen-aten jackson cindy hogan aleks alifirenko jr. emily brinks billy burns robin fletch местонахождение неизвестно 라스트 씬 얼라이브 آخرین لحظه زندگی آخرین باری که زنده دیده شد آخرین حضور زنده chase chase - nichts hält ihn auf last seen alive vista por última vez chase - last seen alive ostatni ślad 最后一次露面', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-to-vien-lach-luat', 'Công Tố Viên Lách Luật', 'Bad Prosecutor', 'https://phimimg.com/upload/vod/20260202-1/34d10c5ee63191bd796ce55b33b9bb8e.jpg', 'https://phimimg.com/upload/vod/20260202-1/d6144f4394c91d656c5d2e05f6cc9db5.jpg', '<p>Jin Jung là một công tố viên chuyên gây rối của Văn phòng Quận Trung tâm. Với một ý chí mạnh mẽ về công lý và sự điên cuồng, anh ta trừng phạt những kẻ tội phạm nhiều hơn những gì họ đáng phải nhận. A Ra là cộng sự của Jung, một công tố viên có năng lực, người luôn đánh giá các vấn đề một cách khách quan và xử lý chúng một cách dứt điểm. Cũng tại Văn phòng Quận trung tâm là công tố viên ưu tú Do Hwan, người tin rằng tiền bạc và quyền lực là tất cả. Anh ấy là một người đàn ông sẵn sàng làm bất cứ điều gì cần thiết để vươn lên cao hơn. Trong một thế giới bị thối nát bởi sự giàu có và xấu xa, câu chuyện về những công tố viên này sẽ mở ra.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Doh Kyung-soo","avatar":""},{"name":"Lee Se-hee","avatar":""},{"name":"Ha Jun","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Lee Si-eon","avatar":""},{"name":"Joo Bo-young","avatar":""},{"name":"Yeon Jun-seok","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Choi Gwang-il","avatar":""},{"name":"Kim Keum-soon","avatar":""},{"name":"Shin Seung-hwan","avatar":""},{"name":"Kim Hieora","avatar":""},{"name":"Yoo Hwan","avatar":""},{"name":"Baek Ha-been","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b9