INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toa-nha-troi-dat', 'Tòa nhà trôi dạt', 'Drifting Home', 'tòa nhà trôi dạt drifting home mutsumi tamura asami seto ayumu murase daiki yamashita yumiko kobayashi inori minase kana hanazawa bin shimada rikako aikawa nana mizuki aya endo masaaki ihara junji tachibana ryunosuke watanuki anri tachibana ayano shibuya minami iinuma ame wo tsugeru hyōryū danchi ame wo tsugeru hyouryuu danchi dom na falach hogar a la deriva les murs vagabonds ديار في قلب المحيط 漂流之家 표류단지 tòa nhà trôi dạt בית בלב האוקיינוס căminul plutitor 宣告风雨的漂流团地 дрейфуючий дім 雨を告げる漂流団地 雨を告げる漂流団地', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-vuong-huyen-thoai', 'Nữ Vương Huyền Thoại', 'The Woman King', 'https://phimimg.com/upload/vod/20260124-1/4545a7a14a4eaf4f6e7fae52d4376a47.jpg', 'https://phimimg.com/upload/vod/20260124-1/228be84d60ad9adadfc8713881bc0bae.jpg', '<p>Nữ Vương Huyền Thoại là câu chuyện đội quân nữ chiến binh phi thường Agojie đã bảo vệ vương quốc Dahomey ở Châu Phi vào những năm 1800 với kỹ năng và sự kiên cường không giống bất cứ điều gì thế giới từng thấy. Lấy cảm hứng từ những sự kiện lừng lẫy có thật, The Woman King là khúc hùng ca đầy cảm xúc về cuộc hành trình của vị nữ tướng Nanisca (thủ vai bởi diễn viên Viola Davis, người từng đoạt giải Oscar®) khi cô đào tạo thế hệ tân binh tiếp theo và sẵn sàng cho họ chiến đấu chống lại kẻ thù tàn bạo đang đe dọa vương quốc của họ.</p>', 'Full', 1, 'single', 'completed', 23, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Viola Davis","avatar":""},{"name":"Thuso Mbedu","avatar":""},{"name":"Lashana Lynch","avatar":""},{"name":"Sheila Atim","avatar":""},{"name":"John Boyega","avatar":""},{"name":"Jordan Bolger","avatar":""},{"name":"Hero Fiennes Tiffin","avatar":""},{"name":"Jimmy Odukoya","avatar":""},{"name":"Masali Baduza","avatar":""},{"name":"Jayme Lawson","avatar":""},{"name":"Adrienne Warren","avatar":""},{"name":"Chioma Antoinette Umeala","avatar":""},{"name":"Siyamthanda Makakane","avatar":""},{"name":"Shaina West","avatar":""},{"name":"Sivuyile Ngesi","avatar":""},{"name":"Riaan Visman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["มหาศึกวีรสตรีเหล