INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-vuong-huyen-thoai', 'Nữ Vương Huyền Thoại', 'The Woman King', 'nữ vương huyền thoại the woman king viola davis thuso mbedu lashana lynch sheila atim john boyega jordan bolger hero fiennes tiffin jimmy odukoya masali baduza jayme lawson adrienne warren chioma antoinette umeala siyamthanda makakane shaina west sivuyile ngesi riaan visman มหาศึกวีรสตรีเหล็ก a mulher rei אשת המלך karotājas אישה מלכה 女王 女戰不敗 królowa wojownik la mujer rey sieviete karalis kráľovná amazoniek the woman king', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-hoan-doi-the-gioi', 'Tình Yêu Hoán Đổi Thế Giới', 'Vice Versa', 'https://phimimg.com/upload/vod/20260123-1/d5299298059ef120549d96542936bdf3.jpg', 'https://phimimg.com/upload/vod/20260123-1/4c23ac2bbbcf30ba9be5bfa4706aadad.jpg', '<p>Talay là một sinh viên tài năng mới ra trường. Anh ấy nhận được xác nhận cho công việc mới của mình với tư cách là một thợ pha màu và rất vui. Thật không may, trong một chuyến đi biển với bạn bè của mình, Talay bị chết đuối. Anh ta thức dậy trong một vũ trụ thay thế, bên trong cơ thể của một người khác. Anh phát hiện ra rằng người đó tên là Tess. Tess là một đứa con nhà giàu hư hỏng rắc rối. Trong bệnh viện, Talay gặp một y tá khác từ vũ trụ của anh ấy, người cũng đã chuyển đến đó. Cô ấy giải thích sự tồn tại của hai vũ trụ song song và nhấn mạnh sự cần thiết phải tìm ra “Portkey”. Cô ấy cũng nhắc lại rằng có thể có mối liên hệ sâu sắc nào đó giữa Talay và chiếc chìa khóa. Khi Talay tiếp cận với những người bạn của Tess, anh bắt gặp một người bạn thời tiểu học, Tun. Khi gặp Tun, Talay nhận thấy một số điều kỳ lạ và nhận ra rằng linh hồn của Tun ban đầu cũng đã biến đổi. Talay thú nhận với anh chàng mới rằng anh ta cũng đến từ vũ trụ khác. Khi cả hai làm việc cùng nhau để tìm các khóa cổng, mối quan hệ của họ càng bền chặt. Nhưng điều gì sẽ xảy ra khi họ trở lại vũ trụ của chính mình? Liệu họ có gặp lại nhau và nhận ra nhau?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Tawinan Anukoolprasert","avatar":""},{"name":"Jitaraphol Potiwihok","avatar":""},{"name":"Korapat Kirdpan","avatar":""},{"name":"Pawat Chittsawangdee","avatar":""},{"name":"Trai Nimtawat","avatar":""},{"name":"Thanaboon Kiatniran","avatar":""},{"name":"Lalana Kongthoranin","avatar":""},{"name":"Maneerat Kam-Uan","avatar":""},{"name":"Tipnaree Weerawatnodom","avatar":""},{"name":"Phanuroj Chalermkijporntavee","avatar":""},{"name":"Tharatorn Jantharaworakarn","avatar":""},{"name":"Daweerit Chul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["异世恋中恋","รักสลับโลก"]', 1784690324261);
