INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-bi-cao', 'Cô Dâu Bị Cáo', 'Prisoner Of Love', 'https://phimimg.com/upload/vod/20251220-1/8644c6db29f69c45821b0a2141c75292.jpg', 'https://phimimg.com/upload/vod/20251220-1/a366717ecd11017f7b15516362a630ec.jpg', '<p>Câu chuyện báo thù đầy tình yêu này bắt đầu khi Sichon (Kritarit Butprom), một doanh nhân trẻ sở hữu một vườn nho ở Phetchabun, gặp Ingjan (Hana Lewis), một sinh viên xinh đẹp ở nước ngoài trốn việc kết hôn với Sia Mongkol (Chalermphon Phumphanwong)suýt bị xe của anh ta đâm vào. Ngay cả khi nhìn rõ khuôn mặt của cô ấy, Sichon cũng không nói nên lời bởi vì anh nhớ rằng Ingjhan là người anh yêu đã bỏ rơi anh hai năm trước. Sichon không biết chuyện gì đã xảy ra với Ingjan. Nhưng Ingjan không nhớ anh, cô đã yêu cầu giúp cô trốn khỏi đây càng sớm càng tốt. Mặc dù vẫn chưa hiểu nhiều nhưng Sichon vẫn quyết định làm theo yêu cầu của Ingchan. Trước khi Ingjan bất tỉnh vì bị chuốc thuốc.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Krittarit Butprom","avatar":""},{"name":"Hana Lewis","avatar":""},{"name":"Kharittha Sungsaopath","avatar":""},{"name":"Premanan Sripanich","avatar":""},{"name":"Randapa Muntalumpa","avatar":""},{"name":"Anisa Nugraha","avatar":""},{"name":"Wasu Saengsingkaeo","avatar":""},{"name":"Nahathai Pichitra","avatar":""},{"name":"Prakasit Bosuwan","avatar":""},{"name":"Daran Thitakawin","avatar":""},{"name":"Paweena Charivsakul","avatar":""},{"name":"Siraprapa Sookdamrong","avatar":""},{"name":"Poonpat Attapanyapol","avatar":""},{"name":"Chale","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"na