INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nu-diep-vu-tho-xu-ly-vuong-mien-2', 'Năm Nữ Điệp Vụ: Thợ Xử Lý Vương Miện 2', 'Princess Principal: Crown Handler: Chapter 2 – Revealing Reviews', 'https://phimimg.com/upload/vod/20260117-1/7af9671a8b7dd3522368e03e30b3883e.jpg', 'https://phimimg.com/upload/vod/20260117-1/7f86f66bc097554288c6101662dbb474.jpg', '<p>Bối cảnh là cuối thế kỷ 19. Vương quốc Albion bị chia cắt do cuộc cách mạng cộng hòa. Thủ đô London bị phân tách bởi một bức tường khổng lồ: phía Đông do Vương quốc cai trị, phía Tây do Cộng hòa kiểm soát, nơi đây đã trở thành tiền tuyến của &#39;cuộc chiến trong bóng tối&#39; với sự hoạt động ráo riết của gián điệp các nước.mười năm sau cuộc cách mạng, tại ngôi trường danh giá dành cho nữ sinh Mayfair của Vương quốc, có năm thiếu nữ đang hoạt động dưới danh nghĩa gián điệp của phía Cộng hòa trong vỏ bọc nữ sinh trung học. Sau khi ngăn chặn thành công âm mưu ám sát Nữ hoàng và kết thúc kỳ nghỉ dưỡng tại Casablanca, họ nhận được chỉ thị mới từ Trung tâm điều hành (Control). Bắt đầu từ nhiệm vụ này, năm cô gái — Đội Bồ Câu Trắng (Team White Pigeon) — bắt đầu bị cuốn vào một vòng xoáy khổng lồ làm rung chuyển cả quốc gia.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Koga","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Akari Kageyama","avatar":""},{"name":"Nozomi Furuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Princess Principal Crown Handler Chapter 2 OVA","プリンセス・プリンシパル Crown Handler 第2章「Revealing Reviews」"]', 1784690324261);
