INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nam-nu-diep-vu-tho-xu-ly-vuong-mien-2', 'Năm Nữ Điệp Vụ: Thợ Xử Lý Vương Miện 2', 'Princess Principal: Crown Handler: Chapter 2 – Revealing Reviews', 'năm nữ điệp vụ: thợ xử lý vương miện 2 princess principal: crown handler: chapter 2 – revealing reviews aoi koga akira sekine you taichi akari kageyama nozomi furuki princess principal crown handler chapter 2 ova プリンセス・プリンシパル crown handler 第2章「revealing reviews」', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-tieng-gia-toc', 'Danh Tiếng Gia Tộc', 'Modern Dynasty', 'https://phimimg.com/upload/vod/20260116-1/c84e42cf3fd84428cec51fda3f1f8015.jpg', 'https://phimimg.com/upload/vod/20260116-1/3f03de56f6a306f65e52e0d3e004c7f3.jpg', '<p>Dương Thiến Nghiêu và La Tử Dật cùng hợp tác trong phim mới nhưng lại không vào vai vợ chồng. Trương Trí Lâm trở lại với hình tượng lịch lãm nhưng đầy mưu mô.

Gia tộc họ Mã là danh gia vọng tộc trăm năm, thế nhưng sau vẻ ngoài hào nhoáng lại tiềm ẩn những bí mật khó nói.

Ông Mã Thế Hoành (do Vu Dương đóng) có ba người con trai, cả ba đều cưới mỹ nhân. Con trai cả Mã Diệu Tông (do Quách Chính Hồng đóng) kết hôn với Diệp Thể Vi (do Hùng Đại Lâm đóng) và có hai cô con gái. Con trai thứ hai - Mã Diệu Tổ (do Huỳnh Hạo Nhiên đóng) kết hôn với Chân Tâm (do Dương Thiến Nghiêu đóng) – một phụ nữ đầy tham vọng, muốn đạt đến đỉnh cao quyền lực của gia tộc. Con trai thứ ba - Mã Diệu Đường (do La Tử Dật đóng) kết hôn với Giả Lạc Nghi (do Lý Thể Hoa đóng) - cô vì muốn trả thù cho mẹ mà chấp nhận gả vào Mã gia.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 17, 2022, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Trí Lâm","avatar":""},{"name":"Dương Di","avatar":""},{"name":"Huỳnh Hạo Nhiên","avatar":""},{"name":"Lý Thể Hoa","avatar":""},{"name":"Hùng Đại Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["家族荣耀","Modern Dynasty","家族榮耀"]', 1784690324261);
