INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-trieu-cuoi-cung-phan-5', 'Vương Triều Cuối Cùng (Phần 5)', 'The Last Kingdom (Season 5)', 'https://phimimg.com/upload/vod/20260112-1/bf0d2c71f9ab108655e4ae0a2b57f040.jpg', 'https://phimimg.com/upload/vod/20260112-1/c31f1f85435eb02570acdbdf0d17894e.jpg', '<p>Một bộ phim về những chiến công anh hùng và những trận chiến hoành tráng với chiều sâu chủ đề bao gồm chính trị, tôn giáo, chiến tranh, lòng dũng cảm, tình yêu, lòng trung thành và hành trình tìm kiếm bản sắc chung của chúng ta. &nbsp;Kết hợp các nhân vật và sự kiện lịch sử có thật với các nhân vật hư cấu, đó là câu chuyện về cách một dân tộc kết hợp sức mạnh của họ dưới một trong những vị vua nổi tiếng nhất lịch sử để khai hoang đất đai cho chính họ và xây dựng một nơi mà họ gọi là quê hương.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Alexander Dreymon","avatar":""},{"name":"Emily Cox","avatar":""},{"name":"Eliza Butterworth","avatar":""},{"name":"Mark Rowley","avatar":""},{"name":"Ruby Hartley","avatar":""},{"name":"Cavan Clerkin","avatar":""},{"name":"Arnas Fedaravičius","avatar":""},{"name":"Harry Gilby","avatar":""},{"name":"Timothy Innes","avatar":""},{"name":"Stefanie Martini","avatar":""},{"name":"Phia Saban","avatar":""},{"name":"Adrian Schiller","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sonuncu Krallıq","Последното кралство","O Último Reino","孤国春秋","最后的王国","Το Τελευταίο Βασίλειο","最後的王國","Posljednje kraljevstvo","Az utolsó királyság","آخرین پادشاهی","ラスト・キングダム","라스트 킹덤","Paskutinioji karalystė","Det siste kongeriket","Upadek królestwa","Poslednje kraljevstvo","Последнее королевство","المملكة الأخيرة","Posledné kráľovstvo","Son Krallık","Останнє Королівство","Vương Triều Cuối Cùng","The Last Kingdom"]', 1784690324261);
