INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-huu-van-phan-2', 'Quân Hữu Vân (Phần 2)', 'Word Of Honor (Season 2)', 'https://phimimg.com/upload/vod/20250626-1/80e459757bc285b36ce66f42412c5652.jpg', 'https://phimimg.com/upload/vod/20250626-1/6806b2c7e01a09b0cd57691fb6aee5ae.jpg', '<p>4 thiếu niên rời khỏi trường bước chân vào giang hồ, trên đường tìm kiếm chân tướng, làm sáng tỏ câu đố thân thế. Vì thành quân tử mà trải qua muôn vàn khó khăn nguy hiểm. Họ trọng đạo quân tử, thể hiện sự hiệp nghĩa lấy thân là sức, thực hiện công đạo nhân gian. Một bộ kỳ thư, một trận ân oán, một loại tín ngưỡng, một đoạn truyền kỳ.</p>', 'Hoàn Tất (32/32)', 32, 'hoathinh', 'completed', 9, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Fuzheng","avatar":""},{"name":"Tang Xiaoxi","avatar":""},{"name":"Jie Cai","avatar":""},{"name":"Li Lanling","avatar":""},{"name":"Wei Chao","avatar":""},{"name":"Jinwen Chen","avatar":""},{"name":"Liu Cong","avatar":""},{"name":"Li Shimeng","avatar":""},{"name":"Haiting Cai","avatar":""},{"name":"Titus Jin","avatar":""},{"name":"Liu Mingyue","avatar":""},{"name":"Teng Xin","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Jun You Yun","Jun Youyun","Word of Honor (Jun You Yun)","သိုင်းလောက ကတိစကား","君有云","Word of Honor","Quân Hữu Vân"]', 1784690324261);
