INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quan-huu-van-phan-2', 'Quân Hữu Vân (Phần 2)', 'Word Of Honor (Season 2)', 'quân hữu vân (phần 2) word of honor (season 2) zhang fuzheng tang xiaoxi jie cai li lanling wei chao jinwen chen liu cong li shimeng haiting cai titus jin liu mingyue teng xin jun you yun jun youyun word of honor (jun you yun) သိုင်းလောက ကတိစကား 君有云 word of honor quân hữu vân', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-tien-hoat-hinh', 'Tru Tiên', 'Jade Dynasty', 'https://phimimg.com/upload/vod/20250710-1/e1308950e246287ef6892927c31a7f0c.jpg', 'https://phimimg.com/upload/vod/20250710-1/3a1c89d60b8e66fc7d6a95992444b958.jpg', '<p>Chính ma đại chiến đã qua mười năm, Trương Tiểu Phàm hóa thân thành quỷ lệ, chinh phạt tứ phương trong nội đấu ma giáo. Lúc này dị bảo đầm lầy tử vong xuất thế, dẫn tới các thế lực tranh đoạt, Quỷ Lệ cùng Lục Tuyết Kỳ gặp lại, hai người lâm vào gút mắc yêu hận càng sâu.Sau đó Quỷ Lệ bởi vì chuyện cấp dưới mất tích mà điều tra tới Phần Hương cốc, ngoài ý muốn cứu ra Cửu Vĩ Thiên Hồ Tiểu Bạch, đạt được manh mối của Cổ Vu tộc,Quỷ Lệ trải qua cửu tử nhất sinh, cuối cùng cầu được đại vu sư nắm giữ chiêu hồn kỳ thuật đáp ứng đi tới cứu chữa Bích Dao, tâm nguyện mười năm, đến tột cùng kết quả như thế nào.</p>', 'Hoàn Tất (78/78)', 78, 'hoathinh', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Rong Zeng","avatar":""},{"name":"Duan Yixuan","avatar":""},{"name":"Mengqiao Zhao","avatar":""},{"name":"Xuecen Bai","avatar":""},{"name":"Jinger Wang","avatar":""},{"name":"Ba He","avatar":""},{"name":"Zhang Siwangzhi","avatar":""},{"name":"Jinwen Chen","avatar":""},{"name":"Qing Liu","avatar":""},{"name":"Ling Jun","avatar":""},{"name":"Shao Tong","avatar":""},{"name":"Yufeng Li","avatar":""},{"name":"Yan Hao","avatar":""},{"name":"Yi Fan","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Zhao Mingzhou","avatar":""},{"name":"Gao Xudong","avatar":""},{"name":"杨洁","avatar":""},{"name":"Chen Zhangtaikang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Dinastia Jade","诛仙动画","诛仙动画片","Zhuxian","Zhu Xian","Dinastía de Jade","제이드 다이너스티(Jade Dynasty)","Dinastia de Jade","誅仙","誅僊","Jade.Dynasty","诛仙"]', 1784690324261);
