INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-da-gap-duoc-vi-cuu-tinh', 'Tôi Đã Gặp Được Vị Cứu Tinh', 'Hi Venus', 'https://phimimg.com/upload/vod/20250331-1/4fbe72641705ed42eb294c8596ee7d5e.jpg', 'https://phimimg.com/upload/vod/20250331-1/240cfd298b12838c006647b814ce0a01.jpg', '<p>Bộ phim&nbsp;nói về bác sĩ khoa nhi Diệp Thời Lam tới hỗ trợ cho trạm y tế thôn Đào Nguyên vì nảy sinh hiểu lầm nên quen biết với viện trưởng mới Lục Chiêu Tây, tình cờ Diệp Thời Lam lại trở thành trợ lý của tạm thời của Lục Chiêu Tây. Trong quá trình hai người cùng nhau giải quyết những vấn đề về cứu chữa bệnh nhân và vận hành bệnh viện đã nảy sinh hảo cảm rồi rơi vào tình yêu. Đồng thời hai người cũng dần dần trưởng thành và hiểu rõ hơn sứ mệnh của bác sĩ, cùng nhau trưởng thành.<span style="color: rgb(255, 255, 255); font-family: Roboto, Arial, sans-serif; font-size: 14px; white-space: pre-wrap; background-color: rgba(255, 255, 255, 0.1);">nói về bác sĩ khoa nhi Diệp Thời Lam tới hỗ trợ cho trạm y tế thôn Đào Nguyên vì nảy sinh hiểu lầm nên quen biết với viện trưởng mới Lục Chiêu Tây, tình cờ Diệp Thời Lam lại trở thành trợ lý của tạm thời của Lục Chiêu Tây. Trong quá trình hai người cùng nhau giải quyết những vấn đề về cứu chữa bệnh nhân và vận hành bệnh viện đã nảy sinh hảo cảm rồi rơi vào tình yêu. Đồng thời hai người cũng dần dần trưởng thành và hiểu rõ hơn sứ mệnh của bác sĩ, cùng nhau trưởng thành.</span></p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Thuấn Hi","avatar":""},{"name":"Lương Khiết","avatar":""},{"name":"Chu Tử Hàn","avatar":""},{"name":"Lý Lâm Phi","avatar":""},{"name":"Tư Vũ Đồng","avatar":""},{"name":"Cao Khải","avatar":""},{"name":"Khương Phong","avatar":""},{"name":"Chu Phác","avatar":""},{"name":"Cơ Thần Mục","avatar":""},{"name":"Lí Văn Linh","avatar":""},{"name":"Tiền Ba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Ke Neng Yu Dao Le Jiu Xing","บังเอิญพบรัก","我可能遇到了救星","I May Have Met a Savior","Hi Venus"]', 1784690324261);
