INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-da-gap-duoc-vi-cuu-tinh', 'Tôi Đã Gặp Được Vị Cứu Tinh', 'Hi Venus', 'tôi đã gặp được vị cứu tinh hi venus tăng thuấn hi lương khiết chu tử hàn lý lâm phi tư vũ đồng cao khải khương phong chu phác cơ thần mục lí văn linh tiền ba wo ke neng yu dao le jiu xing บังเอิญพบรัก 我可能遇到了救星 i may have met a savior hi venus', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-toi-theo-dong-nuoc-ngam', 'Phạt Tội: Theo Dòng Nước Ngầm', 'Chasing The Undercurrent', 'https://phimimg.com/upload/vod/20251226-1/e67449f5a5fcb97fac2acb895807274f.jpg', 'https://phimimg.com/upload/vod/20251226-1/ce8282bf2d759dc5301504aa76529424.jpg', '<p>Trong quá trình điều tra vụ án nổ súng ở biệt thự ngoại ô, Thường Chinh đội phó đội cảnh sát hình sự, đã khóa chặt nghi phạm Triệu Bằng Tường. Không muốn dính líu đến cái chết của Triệu Bằng Trình kiểm sát viên con trai thứ hai của gia đình họ Triệu trở thành tội phạm bị truy nã. Với sự giúp đỡ của một đội điều tra bí mật do Bộ Công an cử đến để điều tra sự thật, Thường Chinh không chỉ đối mặt với những mâu thuẫn với người thân và người yêu của mình mà còn khám phá ra những trải nghiệm thực tế trong cuộc sống. Cuối cùng, anh từ bỏ quan hệ tình thân lựa chọn công lý, hỗ trợ hợp tác với đội điều tra. Cuối cùng tên tội phạm đã bị tóm gọn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Cảnh Du","avatar":""},{"name":"Vương Truyền Quân","avatar":""},{"name":"Lương Khiết","avatar":""},{"name":"Lý Hữu Bân","avatar":""},{"name":"Sa Nhật Na","avatar":""},{"name":"Trương Đồng","avatar":""},{"name":"Mai Hồng Siêu","avatar":""},{"name":"Tần Tuấn Kiệt","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Fa Zui","Qian Liu Zhui Zong","潜流追踪","罚罪","罚罪2","Fa Zui Zhi Ying Xiong Jian Shi","Punishment","Наказание","Chasing t