INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-thuyet-thuc-son-van-kiem-quy-tong', 'Truyền Thuyết Thục Sơn: Vạn Kiếm Quy Tông', 'Swords Drawn', 'truyền thuyết thục sơn: vạn kiếm quy tông swords drawn trần minh hạo lý gia nghi lữ tống hiền phạm điềm điềm dương thụ phong bạch hồng tinh swords drawn shushan of ten thousand swords returns 蜀山传：万剑归宗', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-khoi-bien-sau', 'Thoát Khỏi Biển Sâu', 'Deep Sea Escape', 'https://phimimg.com/upload/vod/20251226-1/07c42c5fa0f861384d729b61b6e9b9e1.jpg', 'https://phimimg.com/upload/vod/20251226-1/967af8f366f2c296da7495fe9ccc1748.jpg', '<p>Quan Tử Huyên là một nhà nghiên cứu sinh vật biển đang tiến hành nghiên cứu hải dương, một con kỳ nhông đầu ngắn trong phòng thí nghiệm đột biến đã làm bị thương một người rồi trốn thoát, mà trước đó, cha cô cũng biến mất trên một hòn đảo hoang vắng. Vì muốn tìm ra tung tích của cha mình và kỳ giông khổng lồ, cô đã lên thuyền đến hoang đảo, những người cùng đi trên thuyền mỗi người đều có những tâm sự và bóng ma tâm lý riêng mình. Trên đường đi, họ gặp phải một con kỳ nhông khổng lồ bị đột biến. Mấy người họ cùng chạy trốn tới hoang đảo, mà lúc này Quan Tử Huyên cũng tìm được kỳ nhông biến dị cùng cha mình. Trên hoang đảo nguy hiểm trùng trùng ập tới, nhưng mọi người đều may mắn thoát nạn an toàn.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Thiên Di","avatar":""},{"name":"Phương Tĩnh Sa","avatar":""},{"name":"Trương Chí Vĩ","avatar":""},{"name":"Dương Kỳ Vũ","avatar":""},{"name":"Giang Tư Hân","avatar":""},{"name":"Trương Miêu Nhi","avatar":""},{"name":"Giang Kiến Tân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["深海逃生"]', 1784690324261);
