INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thoat-khoi-bien-sau', 'Thoát Khỏi Biển Sâu', 'Deep Sea Escape', 'thoát khỏi biển sâu deep sea escape lý thiên di phương tĩnh sa trương chí vĩ dương kỳ vũ giang tư hân trương miêu nhi giang kiến tân 深海逃生', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-duong-tien', 'Phong Thần: Dương Tiễn', 'God Of Trident: YangJian', 'https://phimimg.com/upload/vod/20251226-1/239a46f36b72477a61532ac14f194625.jpg', 'https://phimimg.com/upload/vod/20251226-1/92958cd9c35b47699793ec589a0e9940.jpg', '<p>Dương Tiễn bẩm sinh hình dạng khác thường, từ nhỏ đã phải chịu sự lạnh lùng và kỳ thị của dân làng. Tuy nhiên, một ngày nọ, mẹ của Dương Tiễn, vì bảo vệ dân làng nên đã bị kẻ thù giết hại. Đối mặt với tất cả những điều đó, Dương Tiễn đã sống trong những ngày tháng đầy đau khổ. Sau đó, anh biết được rằng, chỉ bằng cách phá vỡ phong ấn, anh có thể lấy lại thần tính của mình mới đánh bại Thần tướng, biết được sự thật và cứu mẹ của mình. Dưới sự chỉ dẫn của Lộ Tử Bào, Dương Tiễn bái sư trở thành học trò của Ngọc Đỉnh chân nhân . Trải nghiệm hành trình sinh tử, từ kén thành bướm, chăm chỉ tu luyện cuối cùng Dương Tiễn đã chinh phục tà ác, đánh bại Thần tướng, có được sự bất tử.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Minh Dương","avatar":""},{"name":"A Cách","avatar":""},{"name":"Thi Tuyết Tinh","avatar":""},{"name":"Vinh Nhĩ Gia","avatar":""},{"name":"Thiên Ca","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["The God of War","The Legend of Yang Jian","封神杨戬"]', 1784690324261);
