INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shikimorisan-cua-toi-khong-chi-de-thuong-kawaii-dake-ja-nai-shikimorisan', 'Shikimori-San Của Tôi Không Chỉ Dễ Thương (Kawaii dake ja Nai Shikimori-san)', 'Shikimori''s Not Just A Cutie', 'https://phimimg.com/upload/vod/20251223-1/f17fa59af4c624b109410204ee732182.jpg', 'https://phimimg.com/upload/vod/20251223-1/3b9f450a6b20a451ed7e882e3acdce46.jpg', '<p>Shikimori dường như là một mẫu bạn gái hoàn hảo: dễ thương, vui vẻ và ngọt ngào mỗi khi cô muốn… thế nhưng, cô lại sở hữu một &quot;mặt tối&quot; cực ngầu, thường sẽ bộc phát trong những tình huống nhất định. Và bạn trai của cô, Izumi, lại cực kỳ yêu thích việc ở bên cạnh mỗi khi điều đó xảy ra!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saori Onishi","avatar":""},{"name":"Shuichiro Umeda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["式守同学不只可爱而已","我家女友可不止可爱呢","式守同学不仅仅只是可爱","式守同學不只可愛而已","Shikimori Tidak Hanya Manis","Kawaii dake ja Nai Shikimori-san","Kawaii Dake Janai Shikimori-san","可愛いだけじゃない式守さん"]', 1784690324261);
