INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-thuong-ngay-cua-tien-vuong-phan-3', 'Nhật Ký Thường Ngày Của Tiên Vương (Phần 3)', 'The Daily Life Of The Immortal King (Season 3)', 'https://phimimg.com/upload/vod/20251207-1/2f2fc87c86880b76da606bcfa6f7b771.jpg', 'https://phimimg.com/upload/vod/20251207-1/4b6fbb599f7e4f1c31c14e8f0056ff28.jpg', '<p>Chuyện nói về một anh chàng với tuổi thơ bắt đầu năm sáu tuổi, anh giết vua quỷ Swallow Sky Clam. Là một phù thủy tu luyện toàn năng, Tiên vương phải che giấu sức mạnh của mình và sống giữa một nhóm sinh viên tu luyện bình thường.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sun Lulu","avatar":""},{"name":"Qian Chen","avatar":""},{"name":"Yin Long","avatar":""},{"name":"Gu Jiangshan","avatar":""},{"name":"Titus Jin","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"Shuai Guan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["仙王的日常生活第二季","Xian Wang De Ri Chang Sheng Huo","王令的日常生活","الحياة اليومية للملك الخالد","不滅の王の日常","Daily Life of the Immortal King","Cuộc Sống Thường Ngày Của Tiên Vương","仙王的日常生活"]', 1784690324261);
