INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-dong-vat', 'Thành Phố Động Vật+', 'Zootopia+ (Zootopia Plus)', 'https://phimimg.com/upload/vod/20251207-1/74d744e561e3c2d24fa45df15d83ca5c.jpg', 'https://phimimg.com/upload/vod/20251207-1/819d760448fb95c420b449b9b12e3a9b.jpg', '<p>Quay trở lại đô thị động vật có vú có nhịp độ nhanh trong loạt phim ngắn này đi sâu hơn vào cuộc sống của một số nhân vật hấp dẫn nhất trong phim, bao gồm Fru Fru, chuột chù Bắc cực mới kết hôn; vũ công hổ tài năng của Gazelle; và con lười đầy bất ngờ, Flash.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["疯狂动物城+","疯狂动物城大小事","זוטופיה+","ズートピア+","Zootropolis+","Zootopia Plus","Zootopia+"]', 1784690324262);
