INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ultraman-trigger-tap-dac-biet-z', 'Ultraman Trigger Tập Đặc Biệt Z', 'Ultraman Trigger: Episode Z', 'https://phimimg.com/upload/vod/20251207-1/20a554c2939eacc8edbf26fbcf1f6f34.jpg', 'https://phimimg.com/upload/vod/20251207-1/17c8bc5ba5cff568ad25f89526e98f66.jpg', '<p>Hai năm sau trận chiến cuối cùng, khi hòa bình tưởng chừng đã trở lại, quái vật bất ngờ trỗi dậy khiến Trái Đất một lần nữa rơi vào hỗn loạn. Sau chuỗi sự kiện trong Ultraman Trigger, Kengo và đội GUTS-Select phát hiện Dark Z đang nhắm đến sức mạnh của Trigger, kéo theo một âm mưu nguy hiểm đe dọa toàn nhân loại. Trước hiểm họa ngày càng lớn, Ultraman Trigger buộc phải hợp lực cùng Ultraman Z trong trận chiến quyết định để ngăn chặn thảm họa và bảo vệ hòa bình vũ trụ.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Raiga Terasaka","avatar":""},{"name":"Kohshu Hirano","avatar":""},{"name":"Runa Toyoda","avatar":""},{"name":"Shunya Kaneko","avatar":""},{"name":"Meiku Harukawa","avatar":""},{"name":"Tadashi Mizuno","avatar":""},{"name":"Katsuya Takagi","avatar":""},{"name":"Kei Hosogai","avatar":""},{"name":"Shin Takuma","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Akinori Ando","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Tomoki Ono","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Ultraman Trigger Episode Z","特利迦奥特曼 最终章","ウルトラマントリガー エピソードZ"]', 1