INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-gio-minh-gap-nhau-di', 'Bây Giờ Mình Gặp Nhau Đi', 'Let''s Meet Now', 'https://phimimg.com/upload/vod/20251207-1/33c388471c5efe8668f7816f689254cb.jpg', 'https://phimimg.com/upload/vod/20251207-1/e3fdce87ccad23e9d0f59a9d1b3ccb37.jpg', '<p>Bộ phim xoay quanh câu chuyện tình yêu giữa tuyển thủ bắn súng Châu Tử Khiêm và biên đạo Quý Thu. Vốn quen biết nhau khi bé, nhưng khi gặp lại ở buổi triển lãm thì Quý Thu lại chẳng nhận ra Châu Tử Khiêm vì anh quá khác biệt so với lúc nhỏ. Sau đó họ có cơ hội tiếp xúc nhiều hơn trong chương trình “Bây giờ mình gặp nhau đi”. Phải chăng tình yêu một lần nữa nở rộ giữa hai người?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lô Dương Dương","avatar":""},{"name":"Hòa Vũ","avatar":""},{"name":"Trương Tử Kiện","avatar":""},{"name":"Giang Chi Nam","avatar":""},{"name":"Chu Tuấn Vĩ","avatar":""},{"name":"Trương Miểu Di","avatar":""},{"name":"Phương Hiểu Đông","avatar":""},{"name":"Lý Chi Phồn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Vamos a conocernos ahora","見面吧就現在","Let''s Meet Each Other Now","见面吧就现在"]', 1784690324262);
