INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-song-cua-thieu-nu-hanh-quyet', 'Cách Sống Của Thiếu Nữ Hành Quyết', 'The Executioner And Her Way Of Life', 'https://phimimg.com/upload/vod/20251204-1/bc167e6e871c4ed46e2a863ff8c01813.jpg', 'https://phimimg.com/upload/vod/20251204-1/b93b6b9f043251a58916c03522681126.jpg', '<p>Trong một thế giới nơi những kẻ bị triệu hồi từ Nhật Bản được xem là hiểm họa thay vì anh hùng, Menou – một nữ pháp sư lạnh lùng – mang trên vai nhiệm vụ hành quyết họ trước khi tai họa xảy ra. Nhưng khi gặp Akari, một cô gái bí ẩn với sức mạnh vượt ngoài dự đoán, hành trình của Menou lại rẽ sang một con đường không ngờ tới...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Iori Saeki","avatar":""},{"name":"Moe Kahara","avatar":""},{"name":"Hisako Kanemoto","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Tamie Kubota","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Virgin Road: Die Henkerin und ihre Art zu leben","Shokei Shōjo no Virgin Road","Shokei Shoujo no Virgin Road","処刑少女の生きる道（バージンロード）","Życie egzekutorki","Virgin Road","The Way of the Executioner Girl","処刑少女の生きる道"]', 1784690324262);
