INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-long-nu-2022', 'Tiểu Long Nữ', 'The Dragon Lady', 'https://phimimg.com/upload/vod/20251126-1/f02a20e1bceb8f73a2652071a8fbb3fb.jpg', 'https://phimimg.com/upload/vod/20251126-1/4b1550d65a901bbfe7c29571db01e439.jpg', '<p>Theo truyền thuyết, con người và ma quỷ không tương thích với nhau. Yêu tộc Long nữ lần đầu tiên đến thế giới loài người và vô tình gặp Hoằng Tế. Hai nhân vật đối lập này đến đô phủ để tìm chị gái mất tích của Bạch Long . Một câu chuyện tình yêu tuyệt vời và cảm động bắt đầu từ đó...</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Sở Hàn","avatar":""},{"name":"Khổng Thư Hàng","avatar":""},{"name":"Mã Tuyết Dương","avatar":""},{"name":"Trương Đặc","avatar":""},{"name":"Rain Lau Yuk‑Chui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Little Dragon Maiden","The Little Dragon Girl","小龙女"]', 1784690324262);
