INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieu-long-nu-2022', 'Tiểu Long Nữ', 'The Dragon Lady', 'tiểu long nữ the dragon lady trương sở hàn khổng thư hàng mã tuyết dương trương đặc rain lau yuk‑chui little dragon maiden the little dragon girl 小龙女', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-yeu-2022', 'Ngư Yêu', 'The Legend Of Aqua Witch', 'https://phimimg.com/upload/vod/20251126-1/a6543dbf6068420d35d47043e1f092b6.jpg', 'https://phimimg.com/upload/vod/20251126-1/89fbd30ae9172c79a6907b9bb84378ec.jpg', '<p>Đã có rất nhiều tin đồn. Gần đến tết trung thu, theo phong tục, Thái tử sẽ để tang người mẹ đã khuất của mình bên dòng sông trong Vườn thượng uyển. Quách Trưởng Chi lo lắng cho sự an toàn của Thái tử và ra lệnh cho ra lệnh cho Đại Lý Tự giải quyết vụ việc càng sớm càng tốt. Đại Lí Tự Chính Tiết Dương cùng với Đinh Nha Nhi liên thủ để cùng tìm ra hung thủ. Trong quá trình điều tra phát hiện ra ở dưới sông có một quái thú khổng lồ ăn thịt người được người ta nuôi, mà người nuôi cá quái thú lại là con quỷ võ công cao cường biến hóa tài tình. Vì một trận động đất, con quỷ cá đã thoát ra khỏi lồng khiến thảm kịch xảy ra. Mục đích của hắn là muốn quái thú cá ăn thịt Thái tử. Liên quan đến việc kế vị ngai vàng, Tiết Dương bị vu oan và bị tống vào nhà giam. May mắn thay, Quách Trưởng Chi đã giúp và bí mật cử người đến giúp đỡ. Vào đêm Trung thu trên sông Khúc, một trận chiến của người và cá đã ngăn chặn âm mưu giết Thái tử.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Đông Đông","avatar":""},{"name":"Ân Tử Vĩ","avatar":""},{"name":"Lý Nham","avatar":""},{"name":"Bành Tĩnh","avatar":""},{"name":"Mã Suất","avatar":""},{"name":"Thành Thành","avatar":""},{"name":"Lưu Phong Cương","avatar":""},{"name":"Dương Vĩnh Văn","avatar":""},{"name":"Lợi Việt Sơ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夜长安","The Fish Demon Journal","The Legend Of Aqua-witch","鱼妖志"]', 1784690324262);
