INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngu-yeu-2022', 'Ngư Yêu', 'The Legend Of Aqua Witch', 'ngư yêu the legend of aqua witch từ đông đông ân tử vĩ lý nham bành tĩnh mã suất thành thành lưu phong cương dương vĩnh văn lợi việt sơ 夜长安 the fish demon journal the legend of aqua-witch 鱼妖志', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-cuu-mon-thanh-son-hai-duong', 'Lão Cửu Môn: Thanh Sơn Hải Đường', 'The Mystic Nine: Begonia From Qingshan (The Mystic Nine Qing Shan Hai Tang)', 'https://phimimg.com/upload/vod/20251126-1/a5ed22170415b5d1f25bfb58f1eba47a.jpg', 'https://phimimg.com/upload/vod/20251126-1/e2b3b86ed7307ede340a366e6ad99e4d.jpg', '<p>Thiếu niên Trương Khải Sơn gánh vác mối thù cả quốc gia lẫn gia đình, gặp bầu gánh trẻ Nhị Nguyệt Hồng có tài tuyệt vời lần đầu khi chàng mới đến với Trường Sa. Hai người “bắt tay” trừng phạt và diệt trừ kẻ xấu, đánh thẳng vào sào huyệt địch. Sau cuộc quyết chiến trong căn phòng bí mật, hai người cùng nhau chống lại quân phiệt Tả Khiêm Chi vô cùng độc ác, chiếm cứ Trường Sa đã lâu. Cuối cùng họ vạch trần sự thật “quái vật” và bảo vệ được thành Trường Sa.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Hạo Nhiên","avatar":""},{"name":"Chu Tán Cẩm","avatar":""},{"name":"Lạc Đạt Hoa","avatar":""},{"name":"Chu Vịnh Đằng","avatar":""},{"name":"Quách Gia Nam","avatar":""},{"name":"Lưu Sướng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Mystic Nine Qing Shan Hai Tang","The Mystic Nine Begonia from Qingshan","老九门之青山海棠"]', 1784690324262);
