INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lao-cuu-mon-thanh-son-hai-duong', 'Lão Cửu Môn: Thanh Sơn Hải Đường', 'The Mystic Nine: Begonia From Qingshan (The Mystic Nine Qing Shan Hai Tang)', 'lão cửu môn: thanh sơn hải đường the mystic nine: begonia from qingshan (the mystic nine qing shan hai tang) đổng hạo nhiên chu tán cẩm lạc đạt hoa chu vịnh đằng quách gia nam lưu sướng the mystic nine qing shan hai tang the mystic nine begonia from qingshan 老九门之青山海棠', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-phu-quai-dam', 'Đao Phủ: Quái Đàm', 'Executioner''s Strange Talk', 'https://phimimg.com/upload/vod/20251126-1/95da98d4f1cc7df3c13b85c8091b3120.jpg', 'https://phimimg.com/upload/vod/20251126-1/fb278e34167a1d26bb85d9fb35535f50.jpg', '<p>Đao phủ Tạ Thất người nắm giữ quỷ đầu đao, đã vi phạm điều cấm kị, chặt đầu nữ tù nhân có đôi đồng tử vào giờ cấm, để rồi gặp ma nữ quay lại trả thù. Người dân thị trấn vô cùng tức giận và đổ lỗi cho Tạ Thất về tất cả những điều kỳ lạ đã xảy ra. Tạ Thất muốn sử dụng phương pháp cổ xưa là đem đầu người chết đến thợ săn để khâu lại và sau đó đốt nó để hủy bỏ sự xuất hiện của ma nữ. Thật bất ngờ, đầu người đã bị đánh cắp và người thợ khâu đã bị giết. Ngoài ra, việc di dời mộ của những người giàu có củatrấn và vụ án cô gái mất tích cũngliên quan lẫn nhau. Sự nguy hiểm đang từng bước đến gần Tạ Thất…</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Cửu Thắng","avatar":""},{"name":"Tào Hỷ Nguyệt","avatar":""},{"name":"Lý Thiên Vũ","avatar":""},{"name":"Lin Phong Diệp","avatar":""},{"name":"Cao Xuân Minh","avatar":""},{"name":"Billy Lau Nam-Quang","avatar":""},{"name":"Nguyễn Khang","avatar":""},{"name":"Phù Nhân","avatar":""},{"name":"Quách Vân","avatar":""},{"name":"Trần Tử Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["حکایت‌های عجیب جلاد","افسانه‌های شگفت‌انگیز جلاد","قصه‌های عجیب مامور اعدام","刽子手·怪谈"]', 1784690324262);
