INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dao-phu-quai-dam', 'Đao Phủ: Quái Đàm', 'Executioner''s Strange Talk', 'đao phủ: quái đàm executioner''s strange talk vương cửu thắng tào hỷ nguyệt lý thiên vũ lin phong diệp cao xuân minh billy lau nam-quang nguyễn khang phù nhân quách vân trần tử hân حکایت‌های عجیب جلاد افسانه‌های شگفت‌انگیز جلاد قصه‌های عجیب مامور اعدام 刽子手·怪谈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-han-quan-hon', 'Đại Hán Quân Hồn', 'Army Soul Of Han Dynasty', 'https://phimimg.com/upload/vod/20251126-1/f86d843067ed75ff21031e554110aa01.jpg', 'https://phimimg.com/upload/vod/20251126-1/a7cdd11fa96d580c0ffd70f1cfee7443.jpg', '<p>Đông Hán năm kiến quốc đầu tiên,Hung Nô từ phương Bắc lợi dụng lúc thôn tính Tây Vực khống chế cả Con Đường Tơ Lụa, nhà Hán cử Ban Siêu đến Tây Vực mở lại Con Đường Tơ Lụa. Trước sự cướp bóc man rợ của Hung Nô, Tư Mã Cảnh Cung đã dẫn quân Hán một lưới bắt sống hoàng tử của Hung Nô, lập được đại công. Sau khi được tiến chức, ông đóng thủ tại Jushi Kim Bồ Thành của tiền triều. Thiền Vu của Hung Nô giận dữ ngút trời, ra lệnh cho 20.000 kỵ binh tinh nhuệ tấn công Kim Bồ. Lúc này, trong thành chỉ có hơn 300 người được Cảnh Cung mang đến giao chiến. Vào thời điểm sinh tử, Cảnh Cung quyết định quay sang bảo vệ Thành phố Kashgar vốn là nơi dễ thủ khó công, phát động cuộc chiến vang danh thiên cổ về 13 dũng tướng tắm máu cả một tòa thành!</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Hải Băng","avatar":""},{"name":"Trương Thần Quang","avatar":""},{"name":"Đỗ Ngọc Minh","avatar":""},{"name":"Chu Hải Mỹ","avatar":""},{"name":"Triệu Sở Luân","avatar":""},{"name":"Ngụy Khải","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["대한군혼","The military spirit of Han dynasty","大汉军魂"]', 1784690324262);
