INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-trai-tim-nhay-nhot', 'Những Trái Tim Nhảy Nhót', 'Những Trái Tim Nhảy Nhót', 'https://phimimg.com/upload/vod/20240609-1/de65694c07ca7b5c62c11f284ef31ea0.jpg', 'https://phimimg.com/upload/vod/20251125-1/8cc12cd32ca15c2b94008fee5d0c66a3.jpg', '<p>“NHỮNG TRÁI TIM NHẢY NHÓT” là hành trình đi tìm mẹ ruột của Họa Mi – cô bé có khả năng thiên bẩm về âm nhạc. Trên hành trình ấy, cô bé có một người bạn đồng hành tên là Hoàng Bách. Cậu bé là người duy nhất còn nhớ dung nhan của mẹ cô bé, bởi từ nhỏ Bách đã say mê giọng ca của mẹ bé Mi - cô đào thường hát ở Miếu năm xưa. Liệu mẹ con Phương Linh – Họa Mi có nhận ra nhau và được đoàn tụ? Liệu Phương Linh có mở lòng đón nhận tình cảm của ông Minh? Liệu ngôi biệt thự của ông Minh có trở thành “Nhà” cho những người ông yêu thương quay về khi mệt mỏi hoặc phạm sai lầm? Một bức tranh hài hước, cảm động và không thiếu những bài học sâu sắc về giá trị gia đình, tình thân sẽ được kể trong hành trình đầy cung bậc cảm xúc mang tên “NHỮNG TRÁI TIM NHẢY NHÓT”.</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 16, 2022, 'Lồng Tiếng', 'HD', 'Việt Nam', 0, '[{"name":"Thanh Thủy","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Quách Ngọc Tuyên","avatar":""},{"name":"Long Đẹp Trai","avatar":""},{"name":"Lê Lộc","avatar":""},{"name":"Tấn Dũng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324262);
