INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-quy-2022', 'Thợ Săn Quỷ', 'Chainsaw Man', 'https://phimimg.com/upload/vod/20250106-1/d1c9fd62c8b80ec84e3510b578a695c6.jpg', 'https://phimimg.com/upload/vod/20250106-1/cdd0f20f79311a101e87a0ec0edb3d3f.jpg', '<p>Denji có một ước mơ đơn giản là sống một cuộc sống hạnh phúc và yên bình, dành thời gian cho một cô gái anh thích. Tuy nhiên, điều này khác xa với thực tế, vì Denji bị yakuza buộc phải giết quỷ để trả những món nợ chồng chất của mình. Sử dụng con quỷ cưng Pochita của mình làm vũ khí, anh ta sẵn sàng làm bất cứ điều gì chỉ vì một ít tiền mặt.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kikunosuke Toya","avatar":""},{"name":"Tomori Kusunoki","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Fairouz Ai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["电锯人","鏈鋸人","चेनसॉ मैन","مرد اره زنجیری","مرد اره برقی","Chensō Man","전기톱 맨","체인소맨","Человек-бензопила","رجل المنشار","Людина-бензопила","CSM","Chainsaw Man: Thợ Săn Quỷ","チェンソーマン"]', 1784690324262);
