INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-ca-hanh', 'Thiếu Niên Ca Hành', 'The Blood Of Youth', 'https://phimimg.com/upload/vod/20241024-1/3e0f0bb226d902a86fee6961d0f54d78.jpg', 'https://phimimg.com/upload/vod/20241024-1/76cd1f17cf343d24fda56afcc6da4d05.jpg', '<p>Phim kể về thiếu niên hiệp khách non nớt Lôi Vô Kiệt (Ngao Thụy Bằng) đang trên đường đến thành Tuyết Nguyệt (được mệnh danh là nơi đứng đầu trên giang hồ) lại lạc vào Tuyết Lạc sơn trang. Lần đầu hành hiệp trượng nghĩa, Lôi Vô Kiệt phải chịu trách nhiệm cho việc đập phá quán trọ của ông chủ Tiêu Sắt (Lý Hoành Nghị). Thế nên, y không còn cách nào khác ngoài việc cùng Tiêu Sắt lên đường đến thành Tuyết Nguyệt để vay tiền trả nợ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 11, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hoành Nghị","avatar":""},{"name":"Ngao Thụy Bằng","avatar":""},{"name":"Lưu Học Nghĩa","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["少年歌行真人版","少年歌行(剧版)","Shao Nian Ge Xing","Shaonian Ge Xing","Shaonian Gexing","ดรุณพเนจรท่องยุทธภพ","少年歌行劇版","The Blood of Youth","少年歌行"]', 1784690324262);
