INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duong-trieu-quy-su-luc', 'Đường Triều Quỷ Sự Lục', 'Strange Tales Of Tang Dynasty', 'đường triều quỷ sự lục strange tales of tang dynasty dương húc văn dương chí cương cáo tư văn trần sáng thạch duyệt an hâm tôn tuyết ninh la gia lương 唐朝诡事录 唐朝诡事录之长安 唐朝诡事录之西行 唐朝诡事录之蜀道 唐诡奇谭 唐诡 唐诡2 唐诡3 唐诡4 داستان‌های ترسناک سلسله تانگ قصه‌های عجیب سلسله تانگ 唐朝詭事録：西へ 唐朝詭事録 唐朝詭事録：長安へ 당조궤사록 : 장안 ปริศนาลับราชวงศ์ถัง ณ​ ฉางอัน 唐朝詭事錄之長安 strange tales of tang dynasty horror stories of tang dynasty strange legend of tang dynasty tang chao gui shi lu strange tales of tang dynasty iii to changan strange tales of tang dynasty 2 strange tales of tang dynasty 3 strange tales of tang dynasty 3: to changan strange tales of tang dynasty ii to the west strange chronicles of tang strange tales of tang dynasty v: the forbidden shu road strange legend of tang dynasty ⅲ đường triều quỷ sự lục 3: trường an', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-ha-nguyet-minh', 'Sơn Hà Nguyệt Minh', 'The Imperial Age', 'https://phimimg.com/upload/vod/20251107-1/9c13eec3d7c25a61bb3df06cc8bb598b.jpg', 'https://phimimg.com/upload/vod/20251107-1/e2250f407d1478fadec89ae8571b7274.jpg', '<p>Phim kể về con trai thứ tư của Hoàng đế khai quốc Minh Triều Chu Nguyên Chương (Trần Bảo Quốc thủ vai) là Chu Đệ (Phùng Thiệu Phong). Từ nhỏ Chu Đệ đã đi theo tướng Từ Đạt chinh chiến và trải qua nhiều cuộc tắm máu nơi chiến trường. Khi còn là một hoàng tử, Chu Đệ được phong làm Yên Vương đóng đô ở Bắc Bình (nay là Bắc Kinh). Nhờ sự ủng hộ của vợ là Từ Diệu Vân (Dĩnh Nhi thủ vai), con gái của tướng Từ Đạt cùng các tướng lĩnh dưới quyền, Yên Vương đã trở thành một nhà chỉ huy quân đội tài ba, ông củng cố quyền lực của mình ở phía Bắc và tiêu diệt các thế lực thù địch. Minh Thái Tổ Chu Nguyên Chương chỉ định người kế vị là đích tôn Minh Huệ Đế Chu Doãn Văn. Tuy nhiên hoàng đế mới lên ngôi chịu sự giật dây của nhà mẹ nên đã bắt đầu giáng chức và tiêu diệt những quan viên thân cận cũng nhưng những hoàng thân quốc thích nhà họ Chu.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Thành Nghĩa","avatar":""},{"name":"Ứng Nhi","avatar":""},{"name":"Trần Bảo Quốc","avatar":""},{"name":"Trương Phong Nghệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b2