INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-ho-ngoai-truyen', 'Phi Hồ Ngoại Truyện', 'Side Story Of Fox Volant', 'https://phimimg.com/upload/vod/20251107-1/8d4f2b8e158260fee57bdc45c48a6921.jpg', 'https://phimimg.com/upload/vod/20251107-1/47d0698df83199ec8b65d5cfbbc6f08e.jpg', '<p>Bộ phim lấy bối cảnh dưới thời vua Càn Long, Hồ Phỉ dấn thân vào chốn giang hồ để trả thù cho cha. Sau khi gia nhập võ lâm, Hồ Phỉ phát sinh ân oán với Phùng Thiên Nam, và nảy sinh tình cảm với Viên Tử Y - con gái giáo chủ phái Thiên Sơn. Hồ Phỉ sau đó tìm thấy Miêu Nhân Phong - người vào sinh ra tử với cha anh - bị mù sau trận giao đấu với Điền Quý Nông. Để giúp đỡ tiền bối, Hồ Phỉ mạo hiểm đến Thung lũng Dược Cốc, tìm thuốc trị thương cho Miêu Nhân Phong.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Tuấn Kiệt","avatar":""},{"name":"Lương Kiệt","avatar":""},{"name":"Hình Phi","avatar":""},{"name":"Lâm Vũ Thân","avatar":""},{"name":"Hà Nhuận Đông","avatar":""},{"name":"Diệp Hạng Minh","avatar":""},{"name":"Hoàng Mộng Anh","avatar":""},{"name":"Lưu Du Phong","avatar":""},{"name":"Hải Linh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fei Hu Wai Zhuan","飛狐外傳","La Historia Secundaria de Fox Volant","داستان روباه پرنده","داستان جانبی روباه پرنده","روباه پرنده جوان","飛狐外伝（ひこがいでん） レガシー・オブ・ヒーロー","飛狐外伝 レガシー・オブ・ヒーロー","The Young Flying 