INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-luat-8020-cua-tinh-yeu', 'Định Luật 80/20 Của Tình Yêu', 'She And Her Perfect Husband', 'https://phimimg.com/upload/vod/20251104-1/5c2d2419e740e57cd5855d8b5bf2cb26.jpg', 'https://phimimg.com/upload/vod/20251104-1/0e54df653c8cc64ae25d644fb19a7487.jpg', '<p>Nữ luật sư độc thân Tần Thi một lòng theo đuổi sự nghiệp, nhưng luôn bị bố mẹ thúc giục lập gia đình. Lúc này, văn phòng luật sư hàng đầu Thành &amp; Tuệ công khai tuyển nhân sự vào Ban Hôn nhân và Gia đình, chỉ chấp nhận những ứng viên đã kết hôn. Tần Văn Vũ - anh trai thứ của Tần Thi là một chuyên viên tuyển dụng không hề đáng tin, chưa được sự đồng ý đã tự mình sửa tình trạng hôn nhân của Tần Thi thành “Đã kết hôn”, bịa ra một người chồng không hề tồn tại. Cứ thế Tần Thi được nhận vào làm việc mà không hay biết gì. Tần Thi biểu hiện xuất sắc, giành được sự tán thưởng của người thành lập văn phòng là Lão Kim. Trong bữa tiệc với bên đối tác, Lão Kim giới thiệu Tần Thi đủ tiêu chuẩn để đảm nhận vai trò luật sư cố vấn Hiệp hội Nữ doanh nhân. Tần Thi lúc này mới biết là mình “đã kết hôn”</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Hứa Khải","avatar":""},{"name":"Lý Trạch Phong","avatar":""},{"name":"Thang Tinh Mị","avatar":""},{"name":"Vương Tử Tuyền","avatar":""},{"name":"Lưu Lâm","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ela e o seu Marido Perfeito","Regra do 80/20 do Amor","Ai De Er Ba Ding Lu","ချစ်ခြင်း၏ ၈၀/၂၀ နိယာမ","Любовный Принцип Парето","Она и её идеальный муж","กฎล็อกลิขิตรัก","愛的二八定律","The 80/20 Rule of Love","She & Her Perfect Husband","The Two Eight Law of Love","爱的二八定律"]', 1784690324262);
