INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoa-chat-cua-nao-suzume', 'Khóa Chặt Cửa Nào Suzume', 'Suzume', 'https://phimimg.com/upload/vod/20251104-1/9508461f4eb797c076b7fd26f4faf1d1.jpg', 'https://phimimg.com/upload/vod/20251104-1/dbfa7cc79cd28fd4626f37dc9f420e4b.jpg', '<p>Câu chuyện bắt đầu khi Suzume vô tình gặp chàng trai Souta đến thị trấn nơi cô sinh sống với mục đích tìm kiếm &quot;một cánh cửa&quot;. Để bảo vệ Nhật Bản khỏi thảm họa, những cánh cửa rải rác khắp nơi phải được đóng lại, và bất ngờ thay Suzume cũng có khả năng đóng cửa đặc biệt này. Từ đó cả hai cùng nhau thực hiện sự mệnh &quot;khóa chặt cửa&quot;!</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Nanoka Hara","avatar":""},{"name":"Hokuto Matsumura","avatar":""},{"name":"Eri Fukatsu","avatar":""},{"name":"Shota Sometani","avatar":""},{"name":"Sairi Ito","avatar":""},{"name":"Kotone Hanase","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Matsumoto Hakuō II","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Ann Yamane","avatar":""},{"name":"Akari Miura","avatar":""},{"name":"Yoji Ueda","avatar":""},{"name":"Aimi","avatar":""},{"name":"Yuu Ayase","avatar":""},{"name":"Akihiro Tajima","avatar":""},{"name":"Ryoko Nagata","avatar":""},{"name":"Shinnosuke Imazu","avatar":""},{"name":"Kyo Yaoya","avatar":""},{"name":"Hina","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Suzume no Tojimari","Suzume''s Door-Locking","鈴芽的門鎖","关门雀","Suzume Locking Up the Doors","ซุซุเมะ","铃芽小姐来锁门","铃芽户缔","सु