INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoa-chat-cua-nao-suzume', 'Khóa Chặt Cửa Nào Suzume', 'Suzume', 'khóa chặt cửa nào suzume suzume nanoka hara hokuto matsumura eri fukatsu shota sometani sairi ito kotone hanase kana hanazawa matsumoto hakuō ii ryunosuke kamiki ann yamane akari miura yoji ueda aimi yuu ayase akihiro tajima ryoko nagata shinnosuke imazu kyo yaoya hina suzume no tojimari suzume''s door-locking 鈴芽的門鎖 关门雀 suzume locking up the doors ซุซุเมะ 铃芽小姐来锁门 铃芽户缔 सुज़ुमे khóa chặt cửa nào suzume 스즈메의 문단속 سوزومی 鈴芽之旅 铃芽之旅 судзуме, що зачиняє двері судзуме, та що зачиняє двері სუზუმე すずめの戸締まり', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-gioi-hoang-hon-phan-5', 'Môi Giới Hoàng Hôn (Phần 5)', 'Selling Sunset (Season 5)', 'https://phimimg.com/upload/vod/20251101-1/5677ba2b01429b783c720174d3aed6bd.jpg', 'https://phimimg.com/upload/vod/20251101-1/b66765e2c3fc9dde8998f3932bbdc4c0.jpg', '<p>Những tình yêu mới. Những kẻ thù cũ. Một gương mặt mới. Khi thị trường xa xỉ đang bùng cháy, cuộc cạnh tranh ở công ty môi giới sôi sục. Ai sẽ tỏa sáng? Ai sẽ vấp ngã?</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brett Oppenheim","avatar":""},{"name":"Jason Oppenheim","avatar":""},{"name":"Chrishell Stause","avatar":""},{"name":"Mary Fitzgerald","avatar":""},{"name":"Emma Hernan","avatar":""},{"name":"Amanza Smith","avatar":""},{"name":"Chelsea Lazkani","avatar":""},{"name":"Bre Tiesi","avatar":""},{"name":"Nicole Young","avatar":""},{"name":"Alanna Gold","avatar":""},{"name":"Sandra Vergara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["日落家园","Selling Sunset"]', 1784690324262);
