INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-doi-dau', 'Sát Thủ Đối Đầu', 'Bullet Train', 'https://phimimg.com/upload/vod/20251028-1/76b529f499ee55d4373b539cdde2c38b.jpg', 'https://phimimg.com/upload/vod/20251028-1/9635cc49683dfd3ce503009d3338810f.jpg', '<p>Ladybug - một sát thủ lành nghề vừa trở lại sau khoảng thời gian nghỉ hưu. Anh nhận nhiệm vụ từ một phụ nữ bí ẩn là thu hồi chiếc vali trên chuyến tàu cao tốc ở Nhật Bản. Những tưởng đây sẽ là phi vụ dễ ăn thì một loạt biến cố ập đến. Ladybug phải đối mặt với vô số thế lực khác nhau trên chiếc tàu hỏa cùng nhắm vào chiếc vali kia. Đối thủ của anh lần lượt là Lemon, Kimura, Hornet, Prince và Tangerine. Mỗi người đều có những âm mưu và cách thức hoạt động riêng dẫn đến một cục diện vô cùng rối ren.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Brad Pitt","avatar":""},{"name":"Joey King","avatar":""},{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Brian Tyree Henry","avatar":""},{"name":"Andrew Koji","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Sandra Bullock","avatar":""},{"name":"Bad Bunny","avatar":""},{"name":"Logan Lerman","avatar":""},{"name":"Zazie Beetz","avatar":""},{"name":"Masi Oka","avatar":""},{"name":"Karen Fukuhara","avatar":""},{"name":"Kevin Akiyoshi Ching","avatar":""},{"name":"Minchi Murakami","avatar":""},{"name":"Kaori Taketani","avatar":""},{"name":"Toshitaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Швидкісний потяг","弾丸列車","Скоростной поезд","Быстрее пули","