INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-quy-nhi-ma-thu-ba-the-movie', 'Nhất Quỷ Nhì Ma, Thứ Ba: The Movie', 'Teasing Master Takagi-san: The Movie', 'https://phimimg.com/upload/vod/20251023-1/a78482561c5e5e301803acf9c3a4ad4d.jpg', 'https://phimimg.com/upload/vod/20251023-1/ae9fe58a5d1285a27224954ee276eb2d.jpg', '<p>Mùa hè cuối cùng của Takagi và Nishikata ở trường trung học cơ sở sắp bắt đầu, và nó đã có một khởi đầu ấm áp! Khi cặp đôi tìm thấy một chú mèo con bị bỏ rơi, họ quyết định làm việc cùng nhau và chăm sóc người bạn đồng hành mới đáng yêu của mình cho đến khi tìm được người mẹ mất tích của nó.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Kaji","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Yui Ogura","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Jun Fukushima","avatar":""},{"name":"Fukushi Ochiai","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Aoi Yuuki","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Kotori Koiwai","avatar":""},{"name":"Madoka Asahina","avatar":""},{"name":"Hinata Tadokoro","avatar":""},{"name":"Aimi Tanaka","avatar":""},{"name":"Tomohisa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["映画 からかい上手の高木さん","Eiga Karakai Jōzu no Takagi-san","Eiga Karakai Jouzu no Takagi-san","擅長捉弄人的高木同學劇場版","Karakai Jouzu no Takagi-san Movie","Teasing Master Takagi-san: The Movie","Skilled Teaser Takagi-san: The Movie","Gekijouban Karakai Jouzu no Takagi-san","แกล้งนัก รักนะรู้ยัง? เดอะมูฟวี่","Мастер дразнилок Такаги. Фильм","Озорная Такаги. Фильм","劇場版 からかい上手の高木さん"]', 1784690324262);
