INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-quy-nhi-ma-thu-ba-the-movie', 'Nhất Quỷ Nhì Ma, Thứ Ba: The Movie', 'Teasing Master Takagi-san: The Movie', 'nhất quỷ nhì ma, thứ ba: the movie teasing master takagi-san: the movie yuki kaji rie takahashi inori minase konomi kohara mao ichimichi yui ogura haruka tomatsu jun fukushima fukushi ochiai nobuhiko okamoto koki uchiyama aoi yuuki yuma uchida kotori koiwai madoka asahina hinata tadokoro aimi tanaka tomohisa 映画 からかい上手の高木さん eiga karakai jōzu no takagi-san eiga karakai jouzu no takagi-san 擅長捉弄人的高木同學劇場版 karakai jouzu no takagi-san movie teasing master takagi-san: the movie skilled teaser takagi-san: the movie gekijouban karakai jouzu no takagi-san แกล้งนัก รักนะรู้ยัง? เดอะมูฟวี่ мастер дразнилок такаги. фильм озорная такаги. фильм 劇場版 からかい上手の高木さん', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-quy-nhi-ma-thu-ba-takagi-phan-3', 'Nhất Quỷ Nhì Ma Thứ Ba Takagi (Phần 3)', 'Teasing Master Takagi-san (Season 3)', 'https://phimimg.com/upload/vod/20240324-1/0c3f750ee7b10a9d16a95d97b520cc44.jpg', 'https://phimimg.com/upload/vod/20240324-1/2e399cf947ca7bc4c49fd6786c1c38f8.jpg', '<p>Takagi và Nishikata là bạn học chung lớp tại trường sơ trung và ngồi cạnh nhau. Takagi thích Nishikata và cô hay trêu chọc cậu bằng những trò đùa của mình. Đáp lại, Nishikata luôn lập kế hoạch phục thù Takagi nhưng luôn thất bại khi cô nàng tận dụng lại để phản đòn. Những câu truyện xoay quanh cuộc sống thường ngày của Takagi, Nishikata và những người bạn học cùng lớp. Đây là phần 3 của bộ phim.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324262);
