INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anne-co-gai-muon-mat', 'Anne: Cô Gái Muôn Mặt', 'Faces Of Anne', 'https://phimimg.com/upload/vod/20251023-1/31bfc3638ff4d872830fa37c65d5a9eb.jpg', 'https://phimimg.com/upload/vod/20251023-1/f4f393868d194ce90542a04113f78ecc.jpg', '<p>10 cô gái, 10 nhân diện, thức dậy tại một nơi xa lạ với những mảnh vỡ kí ức hỗn tạp - tất cả họ đều là gọi Anne. Tại nơi được gọi là phòng bệnh, các &quot;Anne&quot; bị tiêm thuốc và thôi miên mỗi ngày để &quot;chữa trị&quot; chứng hoang tưởng và giúp họ nhớ ra mình là ai. Cơn ác mộng dần hiện nguyên hình khi mỗi một lần &quot;Anne&quot; mở mắt hoặc chết, hay khi mà khuôn mặt họ bị biến đổi. Nỗi sợ hãi dần dần bén rễ và sinh sôi trong tâm trí của các &quot;Anne&quot; còn sống sót, cho đến khi họ chạm trán với &quot;Vertigo&quot; - một quái nhân đầu hươu mình người. Để tồn tại, tất cả các &quot;Anne&quot; phải hợp sức với nhau nhằm tìm ra lối thoát trước khi “nó” đến. Cách duy nhất để giải được bài toán tử thần là ghép nối các mảnh vụn từ quá khứ cùng những bí ẩn của hiện tại để dẫn đến một sự thật duy nhất - chìa khóa cứu sống họ khỏi lưỡi hái tử thần.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Praewa Suthamphong","avatar":""},{"name":"Jennis Oprasert","avatar":""},{"name":"Sutatta Udomsilp","avatar":""},{"name":"Chutimon Chuengcharoensukying","avatar":""},{"name":"Waruntorn Paonil","avatar":""},{"name":"Arachaporn Pokinpakorn","avatar":""},{"name":"Phantira Pipityakorn","avatar":""},{"name":"Eisaya Hosuwan","avatar":""},{"name":"Sawanya Paisarnpayak","avatar":""},{"name":"Violette Wautier","avatar":""},{"name":"Ploiyukhon Rojanakatanyoo","avatar":""},{"name":"Priya Sangkhachinda","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Faces of Anne","แอน"]', 1784690324262);
