INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('upin-ipin-phan-16', 'Upin & Ipin (Phần 16)', 'Upin & Ipin (Season 16)', 'upin & ipin (phần 16) upin & ipin (season 16) asyiela putri siti khairunnisa hajah ainon ariff calvin tony lokeemin tang ying sowk muhammad hafiz hassan muhammad fareez daniel rufaidah mohamed fadzil usayd uqashah kamsani siti nor adwin safie irfan fahim maheswary mohan suleiman bakti azl upin & ipin', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-luc-ngay-tho', 'Yêu Em Lúc Ngây Thơ', 'Childhood In A Capsule', 'https://phimimg.com/upload/vod/20251018-1/f3df8bca7ba7b344ce4bdc6f3acdd6c5.jpg', 'https://phimimg.com/upload/vod/20251018-1/f50a6159a030564cbc55caebc138c031.jpg', '<p>Đinh Hựu Nghinh (do Trương Chấn Lãng đóng) là người có sức ảnh hưởng trên mạng xã hội. Các đoạn phim dạy trang điểm và bình luận mỹ phẩm của Nghinh thu hút lượng lớn người xem, được cộng đồng mạng đánh giá cao. Trong khi đó, nữ giám đốc điều hành Lôi Tử Đồng (do Cao Hải Ninh đóng) xuất thân danh giá, bá khí ngút trời. Cô tự mình vực dậy nhãn hiệu mỹ phẩm vốn có tiếng nhưng hết thời, với tham vọng vươn tầm thế giới. Nhưng các sản phẩm của Đồng lại bị Nghinh bình luận tiêu cực trên mạng, dẫn đến doanh số sụt giảm nghiêm trọng. Đồng quyết định đích thân đến gặp Nghinh để thay đổi cách nhìn của anh và muốn anh PR cho sản phẩm của mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2022, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Cao Hải Ninh","avatar":""},{"name":"Trương Chấn Lãng","avatar":""},{"name":"Trần Triển Bằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Childhood In A Capsule","童時愛上你"]', 1784690324262);
