INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-anh-an-mot-bua-ngon', 'Cùng Anh Ăn Một Bữa Ngon', 'Dine With Love', 'https://phimimg.com/upload/vod/20251017-1/be9b4db34775ea03003272422d867fae.jpg', 'https://phimimg.com/upload/vod/20251017-1/b4e2a2e16c15b3c1c5fbe67a289d2b84.jpg', '<p>Phim kể về cô gái Tô Tiểu Ninh, một biên tập viên ẩm thực, trong quá trình làm việc đã gặp Lý Phi, một đầu bếp tài năng nhưng lạnh lùng. Hai người từ hiểu lầm đến cảm mến nhau, cùng nhau trải qua những khoảnh khắc ấm áp bên bàn ăn, dần học được cách yêu thương và chữa lành vết thương lòng qua những món ăn giản dị nhưng chan chứa tình cảm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Hán Vũ","avatar":""},{"name":"Chu Y Diên","avatar":""},{"name":"Trương Ba","avatar":""},{"name":"Lưu Nhuế Lâm","avatar":""},{"name":"Triệu Chỉ Lâm","avatar":""},{"name":"Hứa Dương","avatar":""},{"name":"Dương Khải Trí","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["陪你一起好好吃饭","Pei Ni Yi Qi Hao Hao Chi Fan","Dine With Love","一起吃饭吧","Кушайте с любовью","陪你一起好好吃飯"]', 1784690324262);
