INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-cai-phan-1', 'Của Cải (Phần 1)', 'Loot (Season 1)', 'https://phimimg.com/upload/vod/20251016-1/7edd7123ea97383864e4395634d051e3.jpg', 'https://phimimg.com/upload/vod/20251016-1/547a5a89c705d59e4316205aaf024c39.jpg', '<p>Sau khi ly hôn với người chồng đã chung sống 20 năm, Molly Novak phải tìm ra cách tiêu khoản thanh toán 87 tỷ đô-la của mình. Cô quyết định tương tác lại với quỹ từ thiện của mình và kết nối lại với thế giới thực, đồng thời tìm thấy chính mình trên hành trình đó.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maya Rudolph","avatar":""},{"name":"Michaela Jaé Rodriguez","avatar":""},{"name":"Joel Kim Booster","avatar":""},{"name":"Nat Faxon","avatar":""},{"name":"Ron Funches","avatar":""},{"name":"Stephanie Styles","avatar":""},{"name":"Meagen Fay","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["שלל","Loot"]', 1784690324262);
