INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('family-guy-phan-21', 'Family Guy (Phần 21)', 'Family Guy (Season 21)', 'family guy (phần 21) family guy (season 21) seth macfarlane alex borstein mila kunis seth green patrick warburton arif zahir გრიფინები keluarga pria مرد خانه خانواده‌ دوست 쇼킹 패밀리 쇼킹패밀리 परिवारको केटा сім’янин ґріффіни family guy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-do-bien-hinh', 'Gấu Đỏ Biến Hình', 'Turning Red', 'https://phimimg.com/upload/vod/20251014-1/efbe2f1bba5049895236cebf0815b5ca.jpg', 'https://phimimg.com/upload/vod/20251014-1/e61ad5f6391423bbbc93765c2064f0c1.jpg', '<p>Với &quot;Gấu Đỏ Biến Hình&quot;, Disney và Pixar mang đến cô bé 13 tuổi Mei Lee (Rosalie Chiang lồng tiếng) đầy tự tin, hơi ngố, đang bị giằng xé giữa hình ảnh con ngoan và sự nổi loạn của tuổi mới lớn. Sự bảo vệ và đeo bám hơi thái quá của mẹ Ming (Sandra Oh lồng tiếng) cũng là một rắc rối mà cô bé phải đối mặt. Không chỉ bối rối vì các thay đổi về sở thích, tình cảm và cơ thể, cô bé còn có một vấn đề nan giải khác. Bất cứ khi nào quá phấn khích (một việc THƯỜNG XUYÊN xảy ra), cô bé sẽ &quot;biến hình&quot; thành một con gấu trúc đỏ khổng lồ! Sản phẩm của đạo diễn Domee Shi (đoạt giải Oscar với hoạt hình Pixar ngắn &quot;Bao&quot;) và nhà sản xuất Lindsey Collins. Một số phân đoạn có họa tiết hoặc hiệu ứng chớp sáng có thể gây ảnh hưởng lên các khán giả nhạy cảm. Một số phân đoạn có họa tiết hoặc hiệu ứng chớp sáng có thể gây ảnh hưởng lên các khán giả nhạy cảm.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rosalie Chiang","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Ava Morse","avatar":""},{"name":"Hyein Park","avatar":""},{"name":"Maitreyi Ramakrishnan","avatar":""},{"name":"Orion Lee","avatar":""},{"name":"Wai Ching Ho","avatar":""},{"name":"Tristan Allerick Chen","avatar":""},{"name":"James Hong","avatar":""},{"name":"Lori Tan Chinn","avatar":""},{"name":"Mia Tagano","avatar":""},{"name":"Sherry Cola","avatar":""},{"name":"Lillian Lim","avatar":""},{"name":"Jordan Fisher","avatar":""},{"name":"FINNEAS","avatar":""},{"name":"Topher Ngo","avatar":""},{"name":"Grayson Villanueva","avatar":""},{"name":"Josh Levi","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["变红","Devenir rouge","터닝 레드","เขินแรงแดงเป็นแพนด้า","메이의 새빨간 비밀","熊抱青春記","Proměna","Red - Crescer É Uma Fera","Jaz, rdeča panda","Volviendose Rojo (Red)","Over de rooie","Turning Red"]', 1784690324262);
