INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gau-do-bien-hinh', 'Gấu Đỏ Biến Hình', 'Turning Red', 'gấu đỏ biến hình turning red rosalie chiang sandra oh ava morse hyein park maitreyi ramakrishnan orion lee wai ching ho tristan allerick chen james hong lori tan chinn mia tagano sherry cola lillian lim jordan fisher finneas topher ngo grayson villanueva josh levi s 变红 devenir rouge 터닝 레드 เขินแรงแดงเป็นแพนด้า 메이의 새빨간 비밀 熊抱青春記 proměna red - crescer é uma fera jaz, rdeča panda volviendose rojo (red) over de rooie turning red', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-2022', 'Trở Về', 'Communion', 'https://phimimg.com/upload/vod/20251012-1/21deb41b1ce802305f502a174bfe128a.jpg', 'https://phimimg.com/upload/vod/20251012-1/23b527e2dff075fb1e103f2db8dece5c.jpg', '<p>Vì nhiều mâu thuẫn, vợ chồng chủ quán ăn Việt Đức Cư, Âu Diệu Tổ và Đặng Lệ Quyên, quyết định ly hôn. Lệ Quyên dẫn theo con trai cả đi nơi khác lập nghiệp, xây dựng đế chế ẩm thực cho riêng mình; còn Diệu Tổ ở lại quản lý quán ăn cùng con trai út. 25 năm sau, Lệ Quyên đột nhiên quay lại để mở chi nhánh, còn đòi lại thương hiệu Việt Đức Cư. Hai cậu con trai cũng gặp lại nhau và có nhiều va chạm trên đường sự nghiệp. Mối quan hệ giữa vợ chồng, anh em liệu có trở về hạnh phúc ấm cúng như ban đầu?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 6, 2022, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Quách Tấn An","avatar":""},{"name":"Trần Vi","avatar":""},{"name":"Hà Quảng Bái","avatar":""},{"name":"Trần Hiểu Hoa","avatar":""},{"name":"Châu Gia Lạc","avatar":""},{"name":"Ngô Vĩ Hào","avatar":""},{"name":"Đái Tổ Nghi","avatar":""},{"name":"Du Giai Hân","avatar":""},{"name":"Lâm Chính Phong","avatar":""},{"name":"Từ Vinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Communion","回歸","回歸光影頌","曙光","Silver Lining"]', 1784690324262);
