INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-ve-2022', 'Trở Về', 'Communion', 'trở về communion quách tấn an trần vi hà quảng bái trần hiểu hoa châu gia lạc ngô vĩ hào đái tổ nghi du giai hân lâm chính phong từ vinh communion 回歸 回歸光影頌 曙光 silver lining', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-dung-doi-ta-xem-huong-dan', 'Tạm Dừng! Đợi Ta Xem Hướng Dẫn', 'Let Me Check The Walkthrough First', 'https://phimimg.com/upload/vod/20251012-1/8ad3fd646fe5333210972816194de51a.jpg', 'https://phimimg.com/upload/vod/20251012-1/e8906281c497d66ad29c028749ac8b3e.jpg', '<p>Do mắc phải một sai sót trong quá trình thực hiện triệu hồi mà một cô gái 30 tuổi tên là Lưu Y Nặc đã vô tình bị triều hồi vào bên trong thế giới game. Để nhanh chóng quay trở lại hiện thực, cô nàng Lưu Y Nặc đã bắt đầu giúp đỡ một &quot;kẻ dũng cảm&quot; tên là Điền Ân Nhã mới 18 tuổi để đi giải cứu thế giới. Lưu Y Nặc sở dĩ là một người chơi cấp cao, và dựa vào những nhận thức xuất sắc sẵn có của mình, ở Dị giới ấy liền như hổ mọc cạnh, cá gặp nước. Ân Nhã cũng xuất phát từ một cô gái nhỏ vô cùng bướng bỉnh mà giờ đã trở thành một cô nàng trưởng thành và đáng tin cậy.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ye Zhiqiu","avatar":""},{"name":"Chang Rongshan","avatar":""},{"name":"Jiang Yingjun","avatar":""},{"name":"Yeqiao Yan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Zan Ting! Rang Wo Cha Gong Lve","Zanting! Rang Wo Cha Gonglue","Zanting! Rang Wo Cha Gonglüe","Zan Ting! Rang Wo Cha Gonglue","Kouryaku Wanted! Isekai Sukuimasu!?","Kōryaku Wanted! Isekai Sukuimasu!?","공략 원티드! ~이세계 구합니다!?~","공략 원티드","Дайте 