INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-ve-tham-lang', 'Hộ Vệ Thầm Lặng', 'Against Darkness', 'https://phimimg.com/upload/vod/20251010-1/a254da1fe2e8fcd74b738f82f0fc86f2.jpg', 'https://phimimg.com/upload/vod/20251010-1/095032ff6f563cad1d6ff040631a2dba.jpg', '<p>Sau nhiều năm nằm vùng, trung sĩ Cao Huy (do Trần Triển Bằng đóng) được điều đến tổ trọng án, dưới sự dẫn dắt của cấp trên là Phương Tử Kiều (do Trần Vỹ đóng). Mặc dù đã thay đổi môi trường làm việc, nhưng Huy vẫn còn ám ảnh về quá khứ và giữ lối phá án cũ. Điều đó khiến anh và Kiều thường xuyên xích mích. Tuy nhiên, sau nhiều lần vào sinh ra tử, họ bắt đầu hợp tác ăn ý và thân thiết với nhau hơn.

Về phần Kiều, cô vốn là mẹ đơn thân, sống cùng con trai đang tuổi vị thành niên, tên Hà Tử Tuấn (do Dương Khải Bác đóng). Vì mải mê phá án, Kiều ít có thời gian ở bên con, khiến Tuấn vô tình kết bạn với người xấu và bị lợi dụng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2022, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ruco Chan Chin-Pang","avatar":""},{"name":"Alice Chan","avatar":""},{"name":"Sharon Chan Man-Chi","avatar":""},{"name":"Joseph Lee Kwok-Lun","avatar":""},{"name":"Kong Ka-Man","avatar":""},{"name":"Brian Tse Tung Man","avatar":""},{"name":"Andrew Yuen","avatar":""},{"name":"Stephanie Che Yuen-Yuen","avatar":""},{"name":"Lee Shing-Cheong","avatar":""},{"name":"Chan Kwok-Fung","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["黯夜守護者","Against Darkness"]', 1784690324262);
