INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ho-ve-tham-lang', 'Hộ Vệ Thầm Lặng', 'Against Darkness', 'hộ vệ thầm lặng against darkness ruco chan chin-pang alice chan sharon chan man-chi joseph lee kwok-lun kong ka-man brian tse tung man andrew yuen stephanie che yuen-yuen lee shing-cheong chan kwok-fung 黯夜守護者 against darkness', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-em-nguoi-bat-tu-phan-2', 'Gửi Em, Người Bất Tử (Phần 2)', 'To Your Eternity (Season 2)', 'https://phimimg.com/upload/vod/20251008-1/b8ff04f174009c39ab55804a24c9e717.jpg', 'https://phimimg.com/upload/vod/20251008-1/82f95a804c0c0177e2bc535f0a0ae4fc.jpg', '<p>Nó, là một vật thể bất tử, được gửi đến Trái Đất, Nó không mang cảm xúc, cũng không có danh tính. Tuy nhiên, Nó có thể nhập vào bất cứ sinh vật nào có năng lượng. Lúc đầu, Nó là một khối cầu tròn. Sau đó, Nó bắt đầu mô phỏng hình dáng của đá. Nhiệt độ đã giảm và tuyết cũng đã phủ dày, Nó bắt đầu mô phỏng những cây rêu trên đá. Khi bị thương, một chú sói cô đơn nằm chết lặng lẽ trên tuyết, Nó bắt đầu mô phỏng hình dạng của chú sói đó. Cuối cùng, Nó có được nhận thức và đi lang thang qua ngôi làng Tsundra vắng vẻ cho tới khi Nó gặp được một cậu bé. Cậu bé đang sống một mình trong ngôi làng ma này, khi mà người lớn đã ra đi để tìm lấy thiên đường trong biển tuyết trắng xóa. Tuy nhiên, nỗ lực của họ đã công cốc và bây giờ cậu bé đã ra đi trong tình trạng tuyệt vọng. Nó lấy hình dạng của cậu bé và bắt đầu một cuộc hành trình không hồi kết, để lấy được những kinh nghiệm, khám phá những nơi mới và gặp gỡ những người mới.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Reiji Kawashima","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Tomori Kusunoki","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Aya Uchida","avatar":""},{"name":"Fukushi Ochiai","avatar":""},{"name":"Chiharu Sawashiro","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Shouto Kashii","avatar":""},{"name":"Rumi Okubo","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Tasuku Hatanaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fumetsu no Anata e","Para a Sua Eternidade","Uma Vida Imortal","致不灭的你","Para ti, el inmortal","不滅のあなたへ 第2シリーズ","Fumetsu no Anata e Season 2","إلى أبديتك","給不滅的你","To You, the Immortal","不滅のあなたへ"]', 1784690324262);
