INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gui-em-nguoi-bat-tu-phan-2', 'Gửi Em, Người Bất Tử (Phần 2)', 'To Your Eternity (Season 2)', 'gửi em, người bất tử (phần 2) to your eternity (season 2) reiji kawashima kenjiro tsuda tomori kusunoki megumi han yumiri hanamori aya uchida fukushi ochiai chiharu sawashiro aoi koga shouto kashii rumi okubo shizuka itoh shin-ichiro miki tasuku hatanaka fumetsu no anata e para a sua eternidade uma vida imortal 致不灭的你 para ti, el inmortal 不滅のあなたへ 第2シリーズ fumetsu no anata e season 2 إلى أبديتك 給不滅的你 to you, the immortal 不滅のあなたへ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rang-cua-em-nho-anh-roi', 'Răng Của Em Nhớ Anh Rồi', 'My Tooth Your Love', 'https://phimimg.com/upload/vod/20251008-1/e9addf40492091407a2640460a5250b9.jpg', 'https://phimimg.com/upload/vod/20251008-1/39f3814befa6806e060b12b9e3add456.jpg', '<p>Khoảng cách giữa bệnh nhân và nha sĩ là khoảng cách gần nhất giữa những người xa lạ. Nhưng... bạn cũng sợ đi khám răng sao? Tình yêu cũng giống như đi khám răng vậy, nếu sợ hãi sẽ không giải quyết được vấn đề. Bạn phải can đảm ngồi lên bàn chẩn đoán. Trải qua nhiều lần điều trị, tìm ra cách tốt nhất để tình yêu của mình được chăm sóc và được đối đãi một cách hoàn hảo. Đây là một câu chuyện từ những chiếc răng đến tình yêu. Trong cơ thể chúng ta, ngoài DNA ra, thì răng là thứ độc nhất vô nhị. Chúng có thể tồn tại cùng bạn cho đến lúc già, thậm chí nghìn năm không hỏng. Khi điều đáng sợ nhất có liên quan đến tình yêu, một câu chuyện khác được cất giấu trong đó sẽ được mở ra. Trên thế giới này, thứ khó mà &quot;dứt&quot; ra được, ngoài răng ra thì còn có tình yêu nữa.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2022, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Andy Wu","avatar":""},{"name":"Snoopy Yu","avatar":""},{"name":"Michael Chang","avatar":""},{"name":"Alex Chou","avatar":""},{"name":"Esther Huang","avatar":""},{"name":"Jae-Hoon Kim","avatar":""},{"name":"Hung Chien","avatar":""},{"name":"Tim Cheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ကျနော်ချစ်သော သွားဆရာဝန်","我的牙想你"]', 1784690324262);
