INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rang-cua-em-nho-anh-roi', 'Răng Của Em Nhớ Anh Rồi', 'My Tooth Your Love', 'răng của em nhớ anh rồi my tooth your love andy wu snoopy yu michael chang alex chou esther huang jae-hoon kim hung chien tim cheng ကျနော်ချစ်သော သွားဆရာဝန် 我的牙想你', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-da-danh-cap-nu-hon-cua-toi', 'Ai Đã Đánh Cắp Nụ Hôn Của Tôi', 'Who Stole My Kiss', 'https://phimimg.com/upload/vod/20251008-1/308a17303091694c843e3dfcd3ec0e48.jpg', 'https://phimimg.com/upload/vod/20251008-1/bcdec3fa31a78a62832047aa7c74650c.jpg', '<p>Hàn Đình Đình, người mơ ước trở thành &quot;Nữ hoàng tình yêu&quot;, là nhân viên thiết kế của một công ty game tình yêu. Sau bữa tiệc của một dự án, cô say khướt và mơ thấy một chàng trai mặc áo sơ mi trắng từ từ tiến lại gần cô, hơi ngại ngùng và hôn cô một cách thâm tình... Sau khi tỉnh dậy, Hàn Đình Đình phát hiện ra mình đã bị hôn lén, nhưng cô không thể nhớ được ai đã cướp đi nụ hôn đó. Là nhà chế tác trò chơi át chủ bài ngoài lạnh trong nóng khuôn mặt băng giá Lục Bạch? Là chàng idol đang trong thời kỳ đỉnh cao Tần Mặc Trì? Là cậu nhóc thanh xuân tươi trẻ Lộ Viễn Du? Hay người bạn từ thời thơ ấu thích thầm Hàn Đình Đình nhiều năm Hạ Nhượng? Mời bạn đón xem Hàn Đình Đình bắt đầu hành trình thăm dò xem ai đã &quot;cướp&quot; nụ hôn của cô...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Meihan","avatar":""},{"name":"Xia Ningjun","avatar":""},{"name":"Ding Zhi","avatar":""},{"name":"Song Peize","avatar":""},{"name":"Qu Yicheng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Who Secretly Kissed Me","是谁偷吻我"]', 1784690324262);
