INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-ha-ma-manh', 'Điện Hạ Ma Mãnh', 'Your Highness', 'https://phimimg.com/upload/vod/20251007-1/47373d276d7986820353db0a6af73625.jpg', 'https://phimimg.com/upload/vod/20251007-1/5f871320cdbbcb8ef378c87afc443c47.jpg', '<p>Kỷ Uy, tứ hoàng tử nước Bách Thắng, vừa không biết võ công vừa mắc bệnh suyễn nên không được phụ hoàng thương yêu. Cũng vì thế mà chàng bị ép thành thân với Nạp Khắc Ôn Nhu, nàng công chúa giỏi võ của nước Ca Liên Thần, nhằm tạo quan hệ bang giao giữa hai nước. Bất mãn với hôn sự này, Ôn Nhu tìm cách giết Kỷ Uy, nhưng rồi cả hai lại cùng rơi xuống biển, mất hết trí nhớ và lưu lạc đến trấn Thủ Chấn. Cả hai may mắn được thu nhận vào tiêu cục Dịch Phong và cùng nhau tìm cách lấy lại ký ức đã mất.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2022, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Gia Lạc","avatar":""},{"name":"Trần Dự","avatar":""},{"name":"Vương Hạo Nhi","avatar":""},{"name":"Chu Mẫn Hàn","avatar":""},{"name":"Trương Anh Khang","avatar":""},{"name":"Ngô Đái Dung","avatar":""},{"name":"Tào Vĩnh Liêm","avatar":""},{"name":"Mạch Mỹ Ân","avatar":""},{"name":"Vi Gia Hùng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Jade Your Highness","痞子殿下","Your Highness","اعلی‌حضرت"]', 1784690324262);
