INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-lay-binh-minh-season-1', 'Đón Lấy Bình Minh (Season 1)', 'Arknights (Season 1)', 'https://phimimg.com/upload/vod/20250831-1/c7944d89247087ac06eb636cd93a5d8b.jpg', 'https://phimimg.com/upload/vod/20250831-1/a68df907a7ee2f536b90dfa8b84964de.jpg', '<p>Sau những thảm họa chưa biết ở trung tâm Terra, một loại khoáng chất có sức mạnh không thể tưởng tượng được đã được phát hiện. Nhờ nó, công nghệ của xã hội đã có những bước tiến vượt bậc, nhưng chất này lại gây ra một căn bệnh nan y chết người, dẫn đến tình trạng nô lệ hóa trên toàn thế giới của những người bị nhiễm bệnh. Khi một cuộc nổi loạn đang nổi lên, một công ty dược phẩm chạy đua để tìm ra phương pháp chữa trị để cứu nhân loại.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomoyo Kurosawa","avatar":""},{"name":"Yuki Kaida","avatar":""},{"name":"Shizuka Ishigami","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["明日方舟：黎明前奏","明日方舟：冬隐归路","明日方舟：焰烬曙明","明日方舟：冬隱歸路","Arknights：Enshin Shomei","Arknights: Prelude to Dawn","Arknights: Perish in Frost","Arknights: Rise from Ember","Arknights: Reimei Zensou","Arknights [Reimei Zensou]","アークナイツ【黎明前奏/PRELUDE TO DAWN】","Arknights: Touin Kiro","Arknights [Touin Kiro]","アークナイツ【冬隠帰路/PERISH IN FROST】","アークナイツ【焔燼曙明/RISE FROM EMBER】","Arknights: Enshin Shomei","Arknights [Enshin Shomei]","명일방주 여명의 전주곡","명일방주: 여명의 전주곡","아크나이츠 여명의 전주곡","명일방주 서리 속의 죽음","Аркнайтс: Прелюдия к рассвету","Arknights: Прелюдия рассвета","Arknights [PRELUDE TO DAWN]","Arknights [PERISH IN FROST]","Arknights [RISE FROM EMBER]","Arknights","明日方舟"]', 1784690324262);
