INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-bup-be-thu-do-cua-toi-biet-yeu-phan-2', 'Nàng Búp Bê Thử Đồ Của Tôi Biết Yêu (Phần 2)', 'My Dress-Up Darling (Season 2)', 'https://phimimg.com/upload/vod/20250707-1/b966696c3ef139ba0fdfcc2174348399.jpg', 'https://phimimg.com/upload/vod/20250707-1/bf5eafd05689b6dbc406469af3630088.jpg', '<p>My Dress-Up Darling (Season 2) tiếp tục câu chuyện ngọt ngào giữa Gojo - chàng trai nhút nhát yêu búp bê truyền thống và Marin - cô nàng sôi nổi mê cosplay. Ở mùa mới, cả hai cùng bước vào những dự án táo bạo, gặp gỡ các nhân vật mới và đối mặt với những cảm xúc ngày càng rõ ràng trong mối quan hệ của mình. Khi niềm đam mê và trái tim dần hòa làm một, Gojo và Marin phải học cách hiểu nhau hơn cả trong công việc lẫn cuộc sống.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hina Suguta","avatar":""},{"name":"Shoya Ishige","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Atsushi Ono","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Minha Adorável Cosplayer","更衣人偶坠入爱河","恋上换装娃娃","יקירתי מתלבשת","Sono Bisuku Dōru wa Koi wo Suru","Sono Kisekae Ningyou wa Koi wo suru","Sono Kisekae Ningyō wa Koi wo suru","Sono Bisque Doll wa Koi wo Suru","Sono Bisuku Douru wa Koi wo Suru","Любовь с иголочки","Эта фарфоровая кукла влюбилась","ملابسي يا عزيزي","戀上換裝娃娃","戀上換裝娃娃 Season 2","My Dress-Up Darling","その着せ替え人形は恋をする"]', 1784690324262);
