INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kaguyasama-cuoc-chien-to-tinh-nu-hon-dau-khong-hoi-ket-2022', 'Kaguya-sama: Cuộc Chiến Tỏ Tình - Nụ Hôn Đầu Không Hồi Kết', 'Kaguya-sama: Love Is War -The First Kiss That Never Ends-', 'kaguya-sama: cuộc chiến tỏ tình - nụ hôn đầu không hồi kết kaguya-sama: love is war -the first kiss that never ends- makoto furukawa aoi koga konomi kohara ryota suzuki miyu tomita yumiri hanamori momo asakura rina hidaka taku yashiro kana ichinose haruka fukuhara yutaka aoyama takehito koyasu ari ozawa yuka nukui madoka asahina ayaka asai nobunaga shim kaguya-sama wa kokurasetai: first kiss wa owaranai kaguya-sama wa kokurasetai first kiss wa owaranai kaguya-sama wa kokurasetai: i̇lk öpücük ve owaranai kaguya sama wa kokurasetai first kiss wa owaranai 辉夜大小姐想让我告白  初吻不会结束 госпожа кагуя: в любви как на войне – первый поцелуй никогда не заканчивается госпожа кагуя: в любви как на войне. бесконечный первый поцелуй 辉夜大小姐想让我告白：初吻不会结束 辉夜大小姐想让我告白 かぐや様は告らせたい-ファーストキッスは終わらない-', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-linh-tuoi-tre', 'Bản Lĩnh Tuổi Trẻ', 'Freedom Memories', 'https://phimimg.com/upload/vod/20251004-1/dbcec6c595c5960c0f3d9bcf3ea19b68.jpg', 'https://phimimg.com/upload/vod/20251004-1/2c13628227ba82ec6bb4334e7079d48b.jpg', '<p>Vào thập niên 1980, hai người bạn thân Liễu Đức Vinh và Tề Khánh Châu cùng tham gia lớp huấn luyện nghệ sĩ. Tại đây, họ gặp gỡ Á hậu Hồng Kông Khương Chi Nhạn và Ôn Sở Du, con gái một nghệ sĩ nổi tiếng. Cả bốn người cùng nỗ lực đóng phim nhưng may mắn lại không đến với tất cả. Tình bạn giữa Đức Vinh và Khánh Châu thì dần dần rạn nứt trước những thử thách khắc nghiệt của giới giải trí. Liệu những người trẻ tuổi có đủ bản lĩnh để vượt qua sóng gió trên con đường nghệ thuật?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 7, 2022, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Dư Đức Thành","avatar":""},{"name":"Đinh Tử Lương","avatar":""},{"name":"Lưu Anh Huỳnh","avatar":""},{"name":"Đái Tổ Nghi","avatar":""},{"name":"Ngụy Lạc Tễ","avatar":""},{"name":"Lâm Chính Phong","avatar":""},{"name":"Du Hải Hân","avatar":""},{"name":"Khổng Đức Hiền","avatar":""},{"name":"Tạ Khả Di","avatar":""},{"name":"Đái Diệu Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["青春不要脸","青春不要臉","Freedom Memories"]', 1784690324262);
