INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-da-vu-tru-moi-thu-moi-noi-moi-luc', 'Cuộc Chiến Đa Vũ Trụ (Mọi Thứ Mọi Nơi Mọi Lúc)', 'Everything Everywhere All At Once', 'https://phimimg.com/upload/vod/20251003-1/2ace3a75e64e4e21059d595a10074b75.jpg', 'https://phimimg.com/upload/vod/20251003-1/3ada2ec9caa8791de8dd87c03ba5b404.jpg', '<p>Một phụ nữ trung niên nhập cư người Trung Quốc bị cuốn vào một cuộc phiêu lưu điên cuồng, nơi cô ấy một mình giải cứu thế giới bằng cách khám phá các vũ trụ khác và các bản thể khác của chính cô.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michelle Yeoh","avatar":""},{"name":"Stephanie Hsu","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"James Hong","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Tallie Medel","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Harry Shum Jr.","avatar":""},{"name":"Biff Wiff","avatar":""},{"name":"Sunita Mani","avatar":""},{"name":"Aaron Lazar","avatar":""},{"name":"Brian Le","avatar":""},{"name":"Andy Le","avatar":""},{"name":"Narayana Cabral","avatar":""},{"name":"Chelsey Goldsmith","avatar":""},{"name":"Craig Henningsen","avatar":""},{"name":"Anthony Molinari","avatar":""},{"name":"Dan Brown","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["הכל בכל מקום בבת אחת","Τα Πάντα Όλα","Tout, partout, tout à la fois","Усе завжди і водночас","Све у исто време","Tudo em Todo Lugar ao Mesmo Tempo","媽的多重宇宙","Todo en Todas Partes al Mismo Tiempo","Todo En Todas Partes Al Mismo Tiempo","Her şey Her Yerde Aynı Anda","에브리씽 에브리웨어 올 앳 원스","Wszystko wszędzie naraz","양자경의 더 모든 날 모든 순간","Ամեն ինչ ամենուր Միանգամից","EEAAO","EEAO","Tudo em Todo o Lado ao Mesmo Tempo","Todo a la vez en todas partes","Hər Şey Hər Yerdə Eyni Anda","Everything Everywhere All at Once - La vita, il multiverso e tutto quanto","奇異女俠玩救宇宙","瞬息全宇宙","エブリシング・エブリウェア・オール・アット・ワンス","Everything Everywhere All at Once"]', 1784690324262);
