INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-da-vu-tru-moi-thu-moi-noi-moi-luc', 'Cuộc Chiến Đa Vũ Trụ (Mọi Thứ Mọi Nơi Mọi Lúc)', 'Everything Everywhere All At Once', 'cuộc chiến đa vũ trụ (mọi thứ mọi nơi mọi lúc) everything everywhere all at once michelle yeoh stephanie hsu ke huy quan james hong jamie lee curtis tallie medel jenny slate harry shum jr. biff wiff sunita mani aaron lazar brian le andy le narayana cabral chelsey goldsmith craig henningsen anthony molinari dan brown הכל בכל מקום בבת אחת τα πάντα όλα tout, partout, tout à la fois усе завжди і водночас све у исто време tudo em todo lugar ao mesmo tempo 媽的多重宇宙 todo en todas partes al mismo tiempo todo en todas partes al mismo tiempo her şey her yerde aynı anda 에브리씽 에브리웨어 올 앳 원스 wszystko wszędzie naraz 양자경의 더 모든 날 모든 순간 ամեն ինչ ամենուր միանգամից eeaao eeao tudo em todo o lado ao mesmo tempo todo a la vez en todas partes hər şey hər yerdə eyni anda everything everywhere all at once - la vita, il multiverso e tutto quanto 奇異女俠玩救宇宙 瞬息全宇宙 エブリシング・エブリウェア・オール・アット・ワンス everything everywhere all at once', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-noi-gi-anh-lai-bao-em-ngoc', 'Không Nói Gì Anh Lại Bảo Em Ngốc', 'Cutie Pie', 'https://phimimg.com/upload/vod/20251001-1/c5cdd663e482ab9e0af8e1a5d327a4fe.jpg', 'https://phimimg.com/upload/vod/20251001-1/ca3c864b9db5a7ecdf0c3d7c67cf7b8f.jpg', '<p>Với cuộc hôn nhân sắp đặt, một ông trùm trẻ và một sinh viên vô tư đối mặt với thử thách khi một trong hai người nhận ra rằng họ chỉ bên nhau vì nghĩa vụ chứ không phải tình yêu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chawarin Perdpiriyawong","avatar":""},{"name":"Pruk Panich","avatar":""},{"name":"Natasitt Uareksit","avatar":""},{"name":"Max Kornthas Rujeerattanavorapan","avatar":""},{"name":"Koraphat Lamnoi","avatar":""},{"name":"Prarinyakorn Kansawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["큐티파이","คิวตี้พาย","นิ่งเฮียก็หาว่าซื่อ"]', 1784690324262);
