INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-khong-loi-thoat-phan-2', 'Thế Giới Không Lối Thoát (Phần 2)', 'Alice In Borderland (Season 2)', 'https://phimimg.com/upload/vod/20250925-1/0dbd2b82e0c50cdd87b8d0e5b28209b5.jpg', 'https://phimimg.com/upload/vod/20250925-1/b08eefe1ec84fd4292a55780271e852e.jpg', '<p>Một game thủ lông bông cùng hai người bạn nhận ra họ đã lọt vào thế giới Tokyo song song, nơi họ buộc phải thi đấu trong một loạt trò chơi tàn bạo để tồn tại.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub + Lồng Tiếng', 'HD', 'Nhật Bản', 0, '[{"name":"Kento Yamazaki","avatar":""},{"name":"Tao Tsuchiya","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["এলিস ইন বর্ডারল্যান্ড","今际之国的闯关者","彌留之國的愛麗絲","弥留之国的爱丽丝","Alice in Borderland","Η Αλίκη στη Χώρα των Εσχάτων","今际之国的有栖","אליס בבורדרלנד","آلیس در منطقه مرزی","Imawa no Kuni no Alice","Imawa no Kuni no Arisu","아리스 인 보더랜드","Аліса в Бордерленді","Аліса в Ігрокраї","Ajal o''yini","Alisa chegara ortida","Thế Giới Không Lối Thoát","今際の国のアリス"]', 1784690324262);
