INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-khong-loi-thoat-phan-2', 'Thế Giới Không Lối Thoát (Phần 2)', 'Alice In Borderland (Season 2)', 'thế giới không lối thoát (phần 2) alice in borderland (season 2) kento yamazaki tao tsuchiya এলিস ইন বর্ডারল্যান্ড 今际之国的闯关者 彌留之國的愛麗絲 弥留之国的爱丽丝 alice in borderland η αλίκη στη χώρα των εσχάτων 今际之国的有栖 אליס בבורדרלנד آلیس در منطقه مرزی imawa no kuni no alice imawa no kuni no arisu 아리스 인 보더랜드 аліса в бордерленді аліса в ігрокраї ajal o''yini alisa chegara ortida thế giới không lối thoát 今際の国のアリス', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-don-glees', 'Tạm Biệt, Don Glees!', 'Goodbye, Don Glees!', 'https://phimimg.com/upload/vod/20250926-1/8cac6a49fdb2af80b298d2f31ceade9e.jpg', 'https://phimimg.com/upload/vod/20250926-1/c54197eea99af27b47a7e65152f17336.jpg', '<p>Roma, Toto và Drop là &quot;kẻ ngoài lề&quot; nên luôn gắn bó và gọi nhau là Don Glees. Vô tình thành nghi phạm của vụ cháy rừng, bộ ba lên đường tìm cách rửa oan nhưng nào ngờ cuộc đời họ cũng rẽ lối từ đây.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Rino Sashihara","avatar":""},{"name":"Atsushi Tamura","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Goodbye, Don Glees!","¡Hasta siempre, Don Glees!","Goodbye","Goodbye, Don Glees! - Wege einer Freundschaft","Gubbai, Don Gurîzu!","再见了，夏日冒险","再见，唐·格里斯！","奇迹的暑假","グッバイ、ドン・グリーズ！"]', 1784690324262);
