INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tam-biet-don-glees', 'Tạm Biệt, Don Glees!', 'Goodbye, Don Glees!', 'tạm biệt, don glees! goodbye, don glees! natsuki hanae yuki kaji ayumu murase kana hanazawa rino sashihara atsushi tamura goodbye, don glees! ¡hasta siempre, don glees! goodbye goodbye, don glees! - wege einer freundschaft gubbai, don gurîzu! 再见了，夏日冒险 再见，唐·格里斯！ 奇迹的暑假 グッバイ、ドン・グリーズ！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-sinh-cuu-tu', 'Long Sinh Cửu Tử', 'The Dragon Nine', 'https://phimimg.com/upload/vod/20250926-1/140379a2ab0f27069b208921873778f8.jpg', 'https://phimimg.com/upload/vod/20250926-1/6bc9cb66ee97111cffa0a10dcb59b426.jpg', '<p>Huyết thống cuối cùng của gia tộc rồng Phong Nhất Phàm đã vô tình nuốt phải viên thuốc thần của tổ tiên và sinh ra Long Cửu Tử tài giỏi. Cửu Tử đã có thể nói khi vừa sinh ra, và truyền thuyết kể rằng máu thịt của Cửu Tử khi thanh lọc và dung hợp cùng nhau có thể trường sinh. Điều này khiến Cửu Tử bị nhiều thế lực xấu thèm muốn, vì vậy gia đình bắt đầu một cuộc hành trình trốn thoát. Hành trình chạy trốn điên cuồng cùng trải nghiệm cận kề cái chết khiến cả gia đình trở nên hưng thịnh, đồng thời cũng khiến Cửu Tử tài năng hiểu được trách nhiệm vai trò tồn tại của mỗi người. Cuối cùng, Cửu Tử đã có thể bảo vệ mọi người bằng tinh thần đồng đội và sự hợp tác.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Khán Bân Bân","avatar":""},{"name":"Trịnh Tử Hảo","avatar":""},{"name":"Lý Uy","avatar":""},{"name":"Minh Tuấn Thần","avatar":""},{"name":"Thư Nghị","avatar":""},{"name":"Lý Mộng Lộ","avatar":""},{"name":"Mạnh Phàm Diễu","avatar":""},{"name":"Cao Huyền Minh","avatar":""},{"name":"Trâu Minh Dương","avatar":""},{"name":"Long Vũ","avatar":""},{"name":"Vương Thạc","avatar":""},{"name":"Lãnh Hạo Trạch","avatar":""},{"name":"Trương Nghệ Khiêm","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"