INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-cao-den-2025', 'Giải Cứu Cáo Đen', 'Black Fox: Ultimate Rescue', 'https://phimimg.com/upload/vod/20250926-1/44ff6d5e5dfc8b247efc80279aec7280.jpg', 'https://phimimg.com/upload/vod/20250926-1/fd5585378193787fa1bc03f83af70a71.jpg', '<p>Vào tháng 7 năm 1945, chuyên gia quân sự Liên Xô Gavrier (La Phi), mang thông tin tình báo đến Trung Quốc, đã bị quân đội Nhật Bản cướp trên đường đi. Đội cứu hộ do Mã Long Xuyên của Quốc dân đảng dẫn đầu đã thất bại thảm hại. Cùng lúc đó, Vương Văn Uyên của Đội quân số 8 được lệnh gia nhập lực lượng tinh nhuệ của Đội biệt kích, sau nhiều khó khăn và nguy hiểm, La Phi đã được giải cứu thành công.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Thừa Hiên","avatar":""},{"name":"Phong Việt","avatar":""},{"name":"Menier","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["黑狐之绝地营救"]', 1784690324262);
