INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-sam-iv-tinh-yeu-va-sam-set', 'Thần Sấm IV:  Tình Yêu Và Sấm Sét', 'Thor: Love And Thunder', 'https://phimimg.com/upload/vod/20250923-1/2777ecb8ac6e48fb907b583df8f34117.jpg', 'https://phimimg.com/upload/vod/20250923-1/56b59045be261e78ae5a4aa6a3a2bbc1.jpg', '<p>Vốn từng là một chiến binh hùng mạnh của Asgard, trải qua vô số trận chiến lớn nhỏ nhưng sau sự kiện trong Avengers: Endgame (2019) cùng vô số mất mát, Thần Sấm không còn muốn theo đuổi con đường siêu anh hùng. Từ đây, anh lên đường tìm ra ý nghĩa của cuộc sống và nhìn nhận lại bản thân mình.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Christian Bale","avatar":""},{"name":"Tessa Thompson","avatar":""},{"name":"Taika Waititi","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Jaimie Alexander","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Pom Klementieff","avatar":""},{"name":"Sean Gunn","avatar":""},{"name":"Vin Diesel","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Carly Rees","avatar":""},{"name":"Kat Dennings","avatar":""},{"name":"Brett","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["雷神4：爱与雷霆","Thor 4","Тор 4","থর: প্রেম এবং বজ্রপাত","Marvel Studios'' Thor: Love and Thunder","Thor: Love and Thunder de Marvel Studios","Thor : Amour et tonnerre de Marvel Studios","Thor 4: Tình Yêu và Sấm Sét","თორი: სიყვარული და ჭექა-ქუხილი","토르 4","Թոր: Սեր և ամպրոպ","תור: אהבה ורעם","Thor: Cinta dan Guntur","마블 토르: 러브 앤 썬더","토르 러브 앤 썬더","ธอร์: ด้วยรักและอัสนี","Thor 4 - Love and Thunder","Θορ: Έρωτας και Κεραυνός","Thor - Love and Thunder","Thor: Láska jako hrom","Тор: Любовь и гром","Thor IV","باوکی ڕوحی","Thor Miłość i grom","Thor: Sevgi və Göy Gurultusu","Thor 4: Love and Thunder","ثور الحب والرعد","Thor: Love and Thunder"]', 1784690324262);
