INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum-giang-ho-phan-1', 'Ông Trùm Giang Hồ (Phần 1)', 'Tulsa King (Season 1)', 'https://phimimg.com/upload/vod/20250226-1/9d88c3455ebe45fb1b496bf138b2d42d.jpg', 'https://phimimg.com/upload/vod/20250226-1/e49275dbd3b5db845210359b23c5e4fc.jpg', '<p>Sau khi ra tù, thủ lĩnh mafia Dwight &quot;The General&quot; Manfredi bị đày đến Tulsa, Oklahoma, nơi hắn xây dựng một đế chế tội phạm mới với một nhóm gồm những nhân vật không có khả năng.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Jay Will","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Vincent Piazza","avatar":""},{"name":"Tatiana Zappardino","avatar":""},{"name":"Annabella Sciorra","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Domenick Lombardozzi","avatar":""},{"name":"Garrett Hedlund","avatar":""},{"name":"Dana Delany","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["塔爾薩之王","המלך של טולסה","پادشاه تولسا","Talsas karalis","Król Tulsy","Краљ Талсе","Kansas City","The Tulsa King","Ông Trùm Vùng Tulsa","Tulsa King"]', 1784690324262);
