INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-sau', 'Nước Sâu', 'Deep Water', 'https://phimimg.com/upload/vod/20250920-1/dc0a18c8b8e73be21d9a2ee9fb9a362d.jpg', 'https://phimimg.com/upload/vod/20250920-1/a76de79e2cae79db97c2dae3839d5020.jpg', '<p>Nước Sâu kể về Vic và Melinda Van Allen là một cặp đôi ở thị trấn nhỏ Little Wesley. Cuộc hôn nhân không tình yêu của họ được tổ chức với nhau chỉ bởi một sự sắp đặt bấp bênh, theo đó, để tránh những rắc rối của cuộc ly hôn, Melinda được phép gặp bất kỳ người tình nào miễn là cô ấy không từ bỏ gia đình của mình. Tuy nhiên, mọi chuyện trở nên rắc rối khi Vic bị cuốn hút bởi vụ giết người chưa được giải quyết của một trong những người tình cũ của Melinda, Malcolm McRae.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Tracy Letts","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Dash Mihok","avatar":""},{"name":"Finn Wittrock","avatar":""},{"name":"Kristen Connolly","avatar":""},{"name":"Jacob Elordi","avatar":""},{"name":"Rachel Blanchard","avatar":""},{"name":"Michael Braun","avatar":""},{"name":"Jade Fernandez","avatar":""},{"name":"Grace Jenkins","avatar":""},{"name":"Brendan Miller","avatar":""},{"name":"Devyn A. Tyler","avatar":""},{"name":"Jeff Pope","avatar":""},{"name":"Michael Scialabba","avatar":""},{"name":"Paul Teal","avatar":""},{"name":"Jul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gelmė","Hlboká voda","Глубокие воды","底知れぬ愛の闇：2022","Deep Water"]', 1784690324262);
