INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ga-he-dien-loan-2', 'Gã Hề Điên Loạn 2', 'Terrifier 2', 'gã hề điên loạn 2 terrifier 2 david howard thornton lauren lavera elliott fullam sarah voigt kailey hyman casey hartnett charlie mcelveen amelie mclain johnath davis samantha scaffidi leah voysey chris irvine felissa rose owen myre griffin santopietro devon roth amy ru テリファー 2 terrifier 2. masakra w święta terrifier: aterrorizante 2 terrifier 2: el payaso siniestro ужасающий 2 damien leone''s terrifier 2 gã hề điên loạn 2 テリファー　終わらない惨劇 той, що жахає 2 жахаючий 2 مرعب ۲ страховидло 2 ужасяващо 2 aterrorizante 2 terrifier 2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-gon-song', 'Trái Tim Gợn Sóng', 'Hello My Love', 'https://phimimg.com/upload/vod/20250917-1/b794bd70191ebfdbc8edeff45e18a98e.jpg', 'https://phimimg.com/upload/vod/20250917-1/0ab4e41f2bbbb11bbec17311b565e41d.jpg', '<p>Trương Phàn một nhà thiết kế nội thất đã ly hôn, độc thân và không còn tin tưởng vào một mối quan hệ ổn định. Phan Hiểu Thần một nhân viên bán bảo hiểm người đang trải qua cuộc tình 7 năm. La Tiêu Tiêu một blogger về thú cưng chưa từng yêu ai. Ba nhân vật chính ở độ tuổi khác nhau với tính cách khác nhau.Trong hoàn cảnh khó khăn của cuộc sống, họ đã nghi ngờ, do dự, đấu tranh và cuối cùng họ quyết định đối mặt với cuộc sống và dũng cảm chiến đấu. Đối mặt với sự phản bội, lừa dối và cạm bẫy, họ đã vượt qua nút thắt của cuộc đời bằng sự chân thành và tính kiên trì, mở ra những điểm nhấn trong cuộc sống và tìm được một bản thân tốt hơn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Lam","avatar":""},{"name":"Bào Tiểu Bảo","avatar":""},{"name":"Vương An Vũ","avatar":""},{"name":"Trương Phàm","avatar":""},{"name":"Lưu Duẫn Hạo","avatar":""},{"name":"Chu Giai Hi","avatar":""},{"name":"Cao Dương","avatar":""},{"name":"Vương Diễm","avatar":""},{"name":"Tôn Ninh","avatar":""},{"name":"Trương Hâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["芳心蕩漾","Hello My Love","芳心荡漾"]', 1784690324262);
