INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-toi-thuong-da-vu-tru-hon-loan', 'Phù Thủy Tối Thượng: Đa Vũ Trụ Hỗn Loạn', 'Doctor Strange In The Multiverse Of Madness', 'https://phimimg.com/upload/vod/20250917-1/5a1f97d583f6a3954526e134238bbd39.jpg', 'https://phimimg.com/upload/vod/20250917-1/7789e2225cc29a40aa5e520147aa2f05.jpg', '<p>Sự kiện xảy sau phần phim Người Nhện: Không còn nhà (2021) và mùa đầu tiên của Loki (2021), Bác sĩ Stephen Strange đã sử dụng một phét thuật bị cấm và mở ra cánh cổng dẫn tới đa vũ trụ, vô tình dẫn đưa một biến thể hắc ám của Stephen Strange khác đến vũ trụ mình - mối đe dọa lớn mà Dr. Strange có thể phải đối đầu hoặc hợp sức chống lại một cái ác khác, đồng hành cùng Strange còn có Wong và Wanda Maximoff cùng với nhân vật mới American Chavez.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Benedict Cumberbatch","avatar":""},{"name":"Xochitl Gomez","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Jett Klyne","avatar":""},{"name":"Julian Hilliard","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Anson Mount","avatar":""},{"name":"Lashana Lynch","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Sheila Atim","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich