INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-gia-thien-ha-2-dai-dia-vien-chinh', 'Vương Giả Thiên Hạ 2: Đại Địa Viễn Chinh', 'Kingdom 2: Far And Away', 'https://phimimg.com/upload/vod/20250915-1/47f6dcd08fe3e1d61b143ed7f9fa3ca6.jpg', 'https://phimimg.com/upload/vod/20250915-1/9bf84cd60782630ec64f5d0fb9391433.jpg', '<p>Vào thời Chiến Quốc của Trung Hoa cổ đại, chiến tranh đã gây nên vô số những điều thảm khốc khiến nhiều người mất đi gia đình, người thân. Tín là một trong số đó, cậu có ước mơ trở thành “thiên hạ đệ nhất tướng quân”. Để rồi cuộc đời đưa đẩy Tín trở thành người phò tá dưới trướng đương kim thánh thượng Doanh Chính - người có gương mặt giống hệt bạn thân Phiêu của Tín.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kento Yamazaki","avatar":""},{"name":"Ryo Yoshizawa","avatar":""},{"name":"Kanna Hashimoto","avatar":""},{"name":"Nana Seino","avatar":""},{"name":"Amane Okayama","avatar":""},{"name":"Takahiro Miura","avatar":""},{"name":"Takayuki Hamatsu","avatar":""},{"name":"Etsushi Toyokawa","avatar":""},{"name":"Yukiyoshi Ozawa","avatar":""},{"name":"Tsutomu Takahashi","avatar":""},{"name":"Kiyohiko Shibukawa","avatar":""},{"name":"Miou Tanaka","avatar":""},{"name":"Shinnosuke Mitsushima","avatar":""},{"name":"Togi Makabe","avatar":""},{"name":"Chihiro Yamamoto","avatar":""},{"name":"Masah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e