INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-bao-dai-bao', 'Siêu Bão (Đại Bão)', 'Typhoon', 'https://phimimg.com/upload/vod/20250910-1/56ae4334961c38abc1677e509bca82fc.jpg', 'https://phimimg.com/upload/vod/20250910-1/6edab6ec53e1440f5468530c388f4728.jpg', '<p>Mười năm trước, Trương Nhất Phàn đội trưởng đội cứu hộ đưa gia đình đi nghỉ mát ở bãi biển thì bất ngờ gặp bão, trên đường trở về thì gặp tai nạn ô tô, Trương Nhất Phàn đã cố gắng hết sức để giải cứu những người bị thương, và không ngờ con trai Trương Dật Thiên của mình bị chết vì lở đất. Trong mười năm qua, Trương Nhất Phàn vô cùng hối hận, chán nản, đã bỏ công việc ở đội cứu hộ và mở một cửa hàng sửa chữa ô tô. Cái chết của con trai khiến anh căng thẳng, lo lắng về những nguy hiểm trong cuộc sống và bảo vệ quá mức cho cô con gái Trương Hinh Dao. Vợ anh không hài lòng với tình trạng suy sụp của anh và hai người đã li thân chuẩn bị li hôn. Vào ngày lễ tròn 18 tuổi của con gái, Trương Nhất Phàn muốn nhân cơ hội để cứu vãn gia đình mình. Một trận bão chưa từng có ập đến, vợ anh bị mắc kẹt vì bão, và con gái anh bị bắt cóc. Đối mặt với thảm họa này, Nhất Phàn không còn cách nào khác là bắt tay vào hành trình giải cứu vợ và con gái của mình trong cơn bão.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Quán Thành","avatar":""},{"name":"Nghi Mỹ Thư","avatar":""},{"name":"Tống Tử Khảo","avatar":""},{"name":"Tống Khánh","avatar":""},{"name":"Tôn Doanh Nhân","avatar":""},{"name":"Thẩm Văn Tuấn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Typhoon","대태풍","大台风"]', 1784690324262);
