INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-bi-loai-2022', 'Ảnh Bị Loại', 'B Cut', 'https://phimimg.com/upload/vod/20241221-1/a272762d62ef290c08ac89fd1380fec7.jpg', 'https://phimimg.com/upload/vod/20241221-1/fef6d5f654e5bdf7d88c7c02d38b6235.jpg', '<p>&#39;B-Cut&#39; là một bộ phim kinh dị tội phạm kỹ thuật số diễn ra khi Seunghyun (Kim Dong Wan), một thợ sửa chữa điện thoại có ước mơ trở thành hacker. Một ngày, anh nhận được một chiếc điện thoại có chứa bí mật của một ứng cử viên tổng thống quyền lực từ một người phụ nữ. Cô ta yêu cầu khôi phục dữ liệu đã xóa của chiếc điện thoại này. Với yêu cầu này, Seunghyun cảm thấy tò mò và phát hiện ra rằng dữ liệu này sẽ gây ra một vụ bê bối lớn ở Hàn Quốc.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Dong-wan","avatar":""},{"name":"Jeon Se-hyun","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Choi Jae-hwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["b-keot","B级文件","B컷"]', 1784690324262);
