INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-mong-tay-du-ngu-hanh-son', 'Đại Mộng Tây Du: Ngũ Hành Sơn', 'Journey To The West: The Five Elements Mountains', 'https://phimimg.com/upload/vod/20250910-1/e51ace34966d0cdc143eeff94e3be977.jpg', 'https://phimimg.com/upload/vod/20250910-1/6e5e2c0bcabb30fd1c005d7a86f4fe73.jpg', '<p>Bộ phim kể về Tôn Ngộ Không sau khi đại náo thiên cung bị Phật Như Lai trấn áp dưới Ngũ Hành Sơn trong suốt 500 năm. Trong khoảng thời gian dài bị giam cầm, Tề Thiên Đại Thánh vừa hối hận vừa nung nấu ý chí muốn thoát khỏi gông cùm, chờ đợi cơ hội để tái xuất giang hồ. Đồng thời, các thế lực yêu ma quỷ quái không ngừng quấy phá nhân gian, gây ra nhiều tai hoạ. Phim tái hiện quá trình Tôn Ngộ Không đấu tranh giữa tự do và trách nhiệm, mở đường cho hành trình thỉnh kinh cùng Đường Tăng sau này.</p>', 'Full', 1, 'single', 'completed', 30, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tín Triết","avatar":""},{"name":"Phó Mộng Ni","avatar":""},{"name":"Trì Trọng Thuỵ","avatar":""},{"name":"Lê Diệu Tường","avatar":""},{"name":"Lý Lập Quần","avatar":""},{"name":"Đổng Cửu Hợp","avatar":""},{"name":"Trương Hi Viên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Marble Mountains","Ngũ Hành Bí Thuật","Five Elements","大梦西游之五行山"]', 1784690324262);
