INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-xa-truong-nu-sinh', 'Cự Xà Trường Nữ Sinh', 'Rising Boas In A Girls School', 'https://phimimg.com/upload/vod/20250910-1/75266f9ade8f09be8eef7d5b50c719a1.jpg', 'https://phimimg.com/upload/vod/20250910-1/b0f057590ada5bc8e48957396cb45be7.jpg', '<p>Một ngôi trường nữ sinh yên bình bỗng trở thành địa ngục khi những con mãng xà khổng lồ đột nhiên xuất hiện, tấn công điên loạn. Nhóm học sinh và giáo viên bị mắc kẹt trong khuôn viên trường, phải tìm cách đoàn kết chống chọi để sinh tồn. Trong cuộc chiến sinh tử, sự thật kinh hoàng phía sau thí nghiệm bí mật dần bị phơi bày, và con người phải đối mặt với lựa chọn giữa lòng tham, nỗi sợ và sự sống còn.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"rịnh Long","avatar":""},{"name":"Bành Bồ","avatar":""},{"name":"Thị Xuân Như","avatar":""},{"name":"Tào Thiên Khải","avatar":""},{"name":"Bành Vĩnh","avatar":""},{"name":"Thẩm Ngọc Đĩnh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เลื้อยฉก โรงเรียนหญิง","巨蛇闯女校"]', 1784690324262);
