INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mechamato-phan-2', 'Mechamato (Phần 2)', 'Mechamato (Season 2)', 'https://phimimg.com/upload/vod/20250907-1/092d69ba5fec6f9ad19424428ce93fee.jpg', 'https://phimimg.com/upload/vod/20250907-1/5f38c49406407d1ad54d361aa76f68df.jpg', '<p>Một cậu bé nhiệt huyết chiến đấu với cái ác bằng cách hợp lực với một con robot có khả năng chuyển đổi vật thể bình thường thành thiết bị công nghệ cao.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 20, 2022, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Armand Ezra","avatar":""},{"name":"Adzlan Nazir","avatar":""},{"name":"Ielham Iskandar","avatar":""},{"name":"Marissa Balqis","avatar":""},{"name":"Syabil Syamin","avatar":""},{"name":"Alexander Machado","avatar":""},{"name":"Alex Teixeira","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["机甲猛斗","メカアマト","Armored Hero Mechamato","Mechamato","Siri Animasi Mechamato","เมก้ามาโต้ เดอะ ซีรีส์","Mechamato The Animated Series"]', 1784690324262);
