INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-khau-thien-quan-di-tich-con-lon', 'Phát Khâu Thiên Quan: Di Tích Côn Lôn', 'The Legend Of Kunlun', 'https://phimimg.com/upload/vod/20250905-1/32e9533103fa6cda30c0c167e4935511.jpg', 'https://phimimg.com/upload/vod/20250905-1/d17f08e9529d6b0797cee921272df66a.jpg', '<p>Để ngăn chặn thế lực ngoại bang đánh cắp cây trường sinh, Phát Khâu Thiên Quan Văn Phong và những người bạn của mình đã vô tình đâm vào Di tích Côn Lôn, một khu vực thần kì ẩn chứa &quot;trăm thần&quot;. Côn Lôn chứa đầy bảo vật quý hiếm, xen lẫn là xác chết của những kẻ trộm bảo vật, tràn ngập một bầu không khí u ám và đáng kinh sợ. Núi rừng xung quanh đầy rẫy những truyền thuyết đáng sợ về nơi này. Mỗi ngày sau khi trời tối, trong khe núi thường có những tiếng la hét vô cùng đáng sợ. Tuy nhiên, điều mà Văn Phong không ngờ tới là đằng sau những truyền thuyết kinh dị rùng rợn và chuyến hành trình đầy gian nguy ấy còn có những con người thâm sâu khó lường.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bối Tử Thiêm","avatar":""},{"name":"Vương Đình","avatar":""},{"name":"An Duy Lăng","avatar":""},{"name":"Lý Tử Hùng","avatar":""},{"name":"Đường Văn Long","avatar":""},{"name":"Vương Khản","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Legend of Kunlun","Faqiu: The Lost Legend","发丘天官：昆仑墟"]', 1784690324262);
