INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-du-truyen', 'Đông Du Truyện', 'Journey Of East', 'https://phimimg.com/upload/vod/20250804-1/c56c03caf300785451813cdadd2f1784.jpg', 'https://phimimg.com/upload/vod/20250804-1/4d5d92529c7b1ba45f733cc6485a9543.jpg', '<p>Bộ phim kể về câu chuyện của Lã Động Tân đi thuyền đến tìm Bach Anh để hủy hôn, khi đến nhà Bạch Anh thì anh phát hiện cha của Bạch Anh đã mất tích ở Bách Hoa Lầu, sau đó liền đi đến Bách Hoa Lầu gặp được Bạch Anh và bị thuộc hạ của Hắc Giao tấn công. Sau khi trốn thoát khỏi Bách Hoa Lầu, Lã Động Tân đã gặp Thái Bạch Kim Tinh và biết được rằng bản thân chính là hóa thân của Bạch Hạc, Hắc Giao cũng là kiếp nạn mà Động Tân phải trải qua và cũng có tình duyên tam sinh tam thế với Bạch Anh.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hạo Dân","avatar":""},{"name":"Lý Mộng Mộng","avatar":""},{"name":"Clara Lee (Clara Lee hoặc Lý Gia Anh)","avatar":""},{"name":"Lệ Gia Binh","avatar":""},{"name":"Bàng Vũ","avatar":""},{"name":"Nhạc Đông Phong","avatar":""},{"name":"Diêu Kính","avatar":""},{"name":"Tăng Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Journey of East","东游传"]', 1784690324262);
