INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-du-truyen', 'Đông Du Truyện', 'Journey Of East', 'đông du truyện journey of east trần hạo dân lý mộng mộng clara lee (clara lee hoặc lý gia anh) lệ gia binh bàng vũ nhạc đông phong diêu kính tăng văn journey of east 东游传', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-ky-lan-lua-du-hoa-ky-lan', 'Địch Nhân Kiệt: Kỳ Lân Lửa (Dư Hỏa Kỳ Lân)', 'Di Renjie And Fire Unicorn (Detective Dee: Fire Kirin)', 'https://phimimg.com/upload/vod/20250905-1/9b59694fb2379338799d3a80985c56b5.jpg', 'https://phimimg.com/upload/vod/20250905-1/9dc6efc04920de975d6ba25f7acbc2ea.jpg', '<p>Khi mới đến Trường An để nhận chức vụ Địch Nhân Kiệt đã chứng kiến một sự việc kỳ lạ trên con phố sầm uất là một con kỳ lân bị lửa đốt cháy khắp người, gây ra sự cố lớn ở chợ đèn lồng của Lễ hội Thượng Nguyên khiến nhiều người bị thương. Địch Nhân Kiệt đã cứu một đứa trẻ bắt tay với Mộc Lâm để đuổi kỳ lân lửa, nhưng kỳ lân lửa đã trốn thoát. Võ Tắc Thiên rất tức giận và ra lệnh cho Khanh Tiết Khâm điều tra vụ việc. Vì những hiểu lầm khác nhau, con gái của Tiết Khâm và Định Nhân Kiệt đã trở thành một cặp, hai người bất đắc dĩ phải cùng nhau hợp tác để điều tra vụ án của Kì Lân Lửa. Địch Nhân Kiệt tìm thấy một chiếc kẹp tóc quý hiếm ở chợ đèn lồng, manh mối này chỉ hướng có liên quan đến Tề Vương Phủ, liên quan câu chuyện tình yêu của Tiểu Vương gia và vũ nữ trẻ Mộ Dung Linh. Khi điều tra, Địch Nhân Kiệt phát hiện ra rằng vụ án ngày càng trở nên rối rắm,liên quan đến tai họa của việc tiêu diệt gia tộc mười năm trước...</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Nghệ Hân","avatar":""},{"name":"Vương Lộ Thanh","avatar":""},{"name":"Lỗ Vũ","avatar":""},{"name":"Lưu Quản Kỳ","avatar":""},{"name":"Lý Trác Hành","avatar":""},{"name":"Hà Lam Đẩu","avatar":""},{"name":"Chu Lệ Lan","avatar":""},{"name":"Bành Ba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["狄仁杰之浴火麒麟","Di Renjie and Fire Unicorn","Di Renjie-Fire Kirin","Detective Dee and Fire Unicorn","Địch Nhân Kiệt: Kỳ Lân Lửa","狄仁傑之浴火麒麟"]', 1784690324262);
