INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dich-nhan-kiet-ky-lan-lua-du-hoa-ky-lan', 'Địch Nhân Kiệt: Kỳ Lân Lửa (Dư Hỏa Kỳ Lân)', 'Di Renjie And Fire Unicorn (Detective Dee: Fire Kirin)', 'địch nhân kiệt: kỳ lân lửa (dư hỏa kỳ lân) di renjie and fire unicorn (detective dee: fire kirin) hoàng nghệ hân vương lộ thanh lỗ vũ lưu quản kỳ lý trác hành hà lam đẩu chu lệ lan bành ba 狄仁杰之浴火麒麟 di renjie and fire unicorn di renjie-fire kirin detective dee and fire unicorn địch nhân kiệt: kỳ lân lửa 狄仁傑之浴火麒麟', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-thien-dai-thanh-2022', 'Tề Thiên Đại Thánh', 'The Monkey King', 'https://phimimg.com/upload/vod/20250905-1/d3bd82318f75a6700ba337d6aa8c114f.jpg', 'https://phimimg.com/upload/vod/20250905-1/9c17e77e5dba7d2787cca7b5e9fc26aa.jpg', '<p>Tôn Ngộ Không bị giam giữ ở Ngũ Chỉ Sơn 400 năm, tình cờ được A Nhất cứu thoát. Cha mẹ của A Nhất bị Long thái tử giết hại, nàng ấy muốn Tôn Ngộ Không dẫn nàng đi đến thiên cung để cáo trạng. Long thái tử biết được Tôn Ngộ Không đã thoát khỏi Ngũ Chỉ Sơn, chuẩn bị bẩm báo việc năm đó Đông Hải Long Cung bị phá hủy, lợi dụng huynh đệ tốt của Ngộ Không là Ma Vương để giết hại Ngộ Không. Mặc dù pháp lực của Ngộ Không bị khống chế nhưng Ma vương vẫn ám sát thất bại. Vì vậy đã bắt A Nhất, để cứu A Nhất, Ngộ Không đánh đến Long cung. Ngộ Không và thái tử giao tranh từ biển cho đến tận Nam Thiên Môn. Cuối cùng Ngộ Không được A Nhất cảm hóa, trở về Ngũ Chỉ Sơn tiếp tục tu hành, chờ đợi người có cơ duyên đã định.</p>', 'Full', 1, 'single', 'completed', 32, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tạ Miêu","avatar":""},{"name":"Từ Đông Đông","avatar":""},{"name":"An Tuấn Kỳ","avatar":""},{"name":"Triệu Vân Thiên","avatar":""},{"name":"Trương Đông Hạo","avatar":""},{"name":"Quách Bật Đông","avatar":""},{"name":"Trần Dự Đồng","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '["Qi Tian Da Sheng","The Monkey King","齐天大圣"]', 1784690324262);
