INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiep-ao-phan-2', 'Kiếp Ảo (Phần 2)', 'Upload (Season 2)', 'https://phimimg.com/upload/vod/20250831-1/b25698e8a2d0eb4b1b46c4a3471b5434.jpg', 'https://phimimg.com/upload/vod/20250831-1/3a105deeea790911cb5d9a3a3ec9fca7.jpg', '<p>2033, những người sắp chết có thể được “tải lên” vào các khách sạn thực tế ảo do 6 công ty công nghệ điều hành. Nora, một cô gái nghèo sống ở Brooklyn, làm nhân viên chăm sóc khách hàng cho khách sạn “Lakeview” sang trọng. Khi chiếc xe tự lái của L.A. party-boy/coder Nathan gặp tai nạn, cô bạn gái giàu có của anh ta đã tải anh lên thế giới VR của Nora vĩnh viễn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robbie Amell","avatar":""},{"name":"Andy Allo","avatar":""},{"name":"Allegra Edwards","avatar":""},{"name":"Zainab Johnson","avatar":""},{"name":"Kevin Bigley","avatar":""},{"name":"Owen Daniels","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["上传","Věčnost","אפלוד","アップロード デジタルなあの世へようこそ","アップロード ～デジタルなあの世へようこそ～","Выгрузка","อัปโหลด","Upload Complete","Upload"]', 1784690324263);
