INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-trieu-do-han-quoc', 'Phi Vụ Triệu Đô: Hàn Quốc', 'Money Heist: Korea - Joint Economic Area', 'https://phimimg.com/upload/vod/20250827-1/7fbee8977aa39d363cd319cc3a34e6e1.jpg', 'https://phimimg.com/upload/vod/20250827-1/2eff8fe8c1f587eb04a111315a285d7d.jpg', '<p>Giáo sư (Yoo Ji-Tae) lên kế hoạch cho một vụ trộm đầy tham vọng sẽ có một khoản tiền lớn. Đối với kế hoạch của mình, Giáo sư tìm kiếm các thành viên tiềm năng trong nhóm. Các thành viên được tuyển chọn chọn tên thành phố làm mật danh và họ đều có cá tính mạnh mẽ. Kế hoạch của họ có vẻ hoàn hảo, nhưng do bắt giữ các con tin, họ phải đối mặt với một tình huống bất ngờ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Ji-tae","avatar":""},{"name":"Yunjin Kim","avatar":""},{"name":"Park Hae-soo","avatar":""},{"name":"Jun Jong-seo","avatar":""},{"name":"Lee Won-jong","avatar":""},{"name":"Kim Ji-hoon","avatar":""},{"name":"Jang Yoon-ju","avatar":""},{"name":"Lee Hyun-woo","avatar":""},{"name":"Kim Ji-hoon","avatar":""},{"name":"Lee Kyu-ho","avatar":""},{"name":"Park Myung-hoon","avatar":""},{"name":"Kim Seung-o","avatar":""},{"name":"Lee Ju-bin","avatar":""},{"name":"Lee Si-woo","avatar":""},{"name":"Kil Eun-sung","avatar":""},{"name":"Park Soo-young","avatar":""},{"name":"Jang Hyun-sung","avatar":""},{"name":"Lim Ji-yeon","avatar":""},{"name":"Lee Yoon-h","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa