INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-minh-ruc-lua-phan-1', 'Bình Minh Rực Lửa (Phần 1)', 'Dragon Raja (Season 1)', 'https://phimimg.com/upload/vod/20250825-1/7fb57a904d0e88d367edc7c9544da9a8.jpg', 'https://phimimg.com/upload/vod/20250825-1/7f61e81135113728746edf6eb6527af8.jpg', '<p>Minh Phi là một học sinh trung học bình thường như bao người. Tuy nhiên sau lần <span style="text-wrap-mode: wrap;">Minh Phi</span> nhận được thư nhập học từ học viện Cassell , nơi mà anh chưa từng đăng ký trước đây, sau khi nhiều lần do dự, <span style="text-wrap-mode: wrap;">Minh Phi</span> quyết định tìm hiểu và cuộc đời anh cũng chính thức thay đổi chấn động từ thời điểm này.

Học viện đặc biệt của anh ta, với đội ngũ giảng viên lập dị và tập thể sinh viên kỳ quặc, có nhiệm vụ tiêu diệt kẻ thù của loài người, &quot;những con rồng&quot;, bằng cách tập hợp những con người từ khắp nơi trên thế giới, những người mang trong mình dòng máu rồng. <span style="text-wrap-mode: wrap;">Minh Phi</span> nhận ra mình bị cuốn vào cuộc chiến chống lại chúa tể loài rồng - những kẻ đã ngủ yên hàng nghìn năm, khi anh biết được sự thật đằng sau lịch sử ẩn giấu về cuộc chiến của loài người chống lại Dragon Raja.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jinwen Chen","avatar":""},{"name":"Xiangning Zhou","avatar":""},{"name":"Wenxiao He","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Long Zu","龙族动画","Lóngzú Dònghuà","Lóngzú","Lóng Zú","龙族Ⅱ：悼亡者之瞳","悼亡者之瞳","龙族 第2季","龙族 第二季","龙族 第一季","龙族 第1季","龙族2·悼亡者之瞳","龙族Ⅱ 悼亡者之瞳","龙族：火之晨曦","龙族Ⅰ：火之晨曦","龙族 -Dragon Raja-","Dragon Raja - The Blazing Dawn","Dragon Raja -The Blazing Dawn","Ryuzoku -The Blazing Dawn-","アニメ龍族","龍族Ⅱ -The Mourner''s Eyes-","The Mourner''s Eyes","龍族Ⅰ -The Blazing Dawn-","용족 -The Blazing Dawn-","Повелитель драконов","Dragon Raja: Пылающий рассвет","Дракон Раджа","Драконий клан","จอมเวทผนึกมังกร","ราชามังกร -จอมเวทย์ผนึกมังกร-","龍族","龍族II 悼亡者之瞳","The Blazing Dawn","Dragon Raja II -The Mourner’s Eyes-","Dragon Raja -The Mourner’s Eyes-","Dragon Raja The Blazing Dawn","Dragon Raja - Bình Minh Rực Lửa","龙族"]', 1784690324263);
