INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-the-cuc-cu-phan-1', 'Hôn Thê Cúc Cu (Phần 1)', 'A Couple Of Cuckoos (Season 1)', 'https://phimimg.com/upload/vod/20250824-1/9f395adfc083e06f4436b127ed8c182d.jpg', 'https://phimimg.com/upload/vod/20250824-1/4d7a177ba34cdba0b542812508d3541f.jpg', '<p>Cậu học sinh thiên tài Umino Nagi, 16 tuổi, đang học năm hai tại Học viện Megurogawa, bất ngờ phát hiện mình đã bị tráo nhầm ngay từ khi mới sinh. Trên đường đến bữa tối để gặp lại cha mẹ ruột, Nagi tình cờ gặp Amano Erika – một cô gái bộc trực, mạnh mẽ, luôn tìm cách chống lại hôn nhân sắp đặt, và thậm chí kéo Nagi đóng giả làm bạn trai để che mắt mọi người. Thế nhưng, khi Nagi đến buổi gặp gỡ, cậu choáng váng khi biết rằng cha mẹ hai bên đã quyết định “giải quyết” vụ tráo nhầm này bằng cách cho Nagi kết hôn với cô con gái mà cha mẹ ruột đã nuôi dưỡng – và người đó không ai khác chính là Erika! Một câu chuyện hài hước, lãng mạn bắt đầu, nơi những rắc rối dở khóc dở cười nối tiếp, và cũng từ đây tình yêu định mệnh dần hé mở.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaito Ishikawa","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Yukiko Aruga","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '