INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-moi-den-dia-nguc', 'Lời Mời Đến Địa Ngục', 'The Invitation', 'https://phimimg.com/upload/vod/20250823-1/a73086d92f240873bd971634b20ac676.jpg', 'https://phimimg.com/upload/vod/20250823-1/a9f25ffcc8d2a755c77f46bf663414a4.jpg', '<p>Sau khi mẹ qua đời, Evie không còn bất kỳ người thân nào trên đời. Cô quyết định làm xét nghiệm ADN và phát hiện ra mình còn một người em họ đã thất lạc từ lâu. Nhờ vậy mà Evie được gia đình người này mời đến dự một đám cưới xa hoa ở vùng nông thôn nước Anh. Ban đầu, cô có cảm tình với một chàng quý tộc điển trai nhưng nhanh chóng bị đẩy vào cơn ác mộng khi khám phá ra những bí mật đen tối trong lịch sử gia đình mình và âm mưu kinh hoàng đằng sau sự xa hoa của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nathalie Emmanuel","avatar":""},{"name":"Thomas Doherty","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Hugh Skinner","avatar":""},{"name":"Carol Ann Crawford","avatar":""},{"name":"Alana Boden","avatar":""},{"name":"Stephanie Corneliussen","avatar":""},{"name":"Tian Chaudhry","avatar":""},{"name":"Courtney Taylor","avatar":""},{"name":"Scott Alexander Young","avatar":""},{"name":"Ian Lindsay","avatar":""},{"name":"Lili Walters","avatar":""},{"name":"Elizabeth Counsell","avatar":""},{"name":"Virág Bárány","avatar":""},{"name":"Jeremy Wheeler","avatar":""},{"name":"Vik","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Bride","วิวาห์ผวา","La invitación","世紀婚魘","Поканата","The Invitation"]', 1784690324263);
