INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-moi-den-dia-nguc', 'Lời Mời Đến Địa Ngục', 'The Invitation', 'lời mời đến địa ngục the invitation nathalie emmanuel thomas doherty sean pertwee hugh skinner carol ann crawford alana boden stephanie corneliussen tian chaudhry courtney taylor scott alexander young ian lindsay lili walters elizabeth counsell virág bárány jeremy wheeler vik the bride วิวาห์ผวา la invitación 世紀婚魘 поканата the invitation', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-khong-lo-hung-bao', 'Sói Khổng Lồ Hung Bạo', 'The Wolves', 'https://phimimg.com/upload/vod/20250506-1/6c22b4afbfd69ebeb17467935c7c7966.jpg', 'https://phimimg.com/upload/vod/20250506-1/12281e63843f77c7e7dc11b4a4c039ea.jpg', '<p>Trong một chuyến khảo sát khoa học, nhóm nghiên cứu gặp tai nạn máy bay và rơi xuống một vùng băng tuyết hoang vu. Cuộc hành trình nghiên cứu trở thành cuộc chiến sinh tồn khi họ bị một đàn sói đột biến tấn công. Nhân vật chính, Tống Vũ (do Quách Tấn Đông thủ vai), dẫn dắt những người sống sót tìm cách thoát khỏi sự truy đuổi của bầy sói. Tình hình trở nên nghiêm trọng khi con gái tự kỷ của anh, Tĩnh Văn (do Lưu Nhất Hàm thủ vai), bị bắt cóc bởi một con sói khổng lồ. Để cứu con, Tống Vũ quyết định đơn thân xâm nhập hang ổ của bầy sói, đối đầu với những sinh vật đột biến trong một trận chiến sinh tử. Bộ phim kết hợp yếu tố hành động, kinh dị và tình cảm gia đình, mang đến trải nghiệm hồi hộp và cảm động cho khán giả.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Tấn Đông","avatar":""},{"name":"Sử Chấn Long","avatar":""},{"name":"Mã Nguyên","avatar":""},{"name":"Lưu Nhất Hàm","avatar":""},{"name":"Trương Bân","avatar":""},{"name":"Lương Gia Nhân","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["อุบัติหมาป่ายักษ์มฤตยู","The Wolves","狂暴巨狼"]', 1784690324263);
