INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-luong-nhan-chi-u-minh-co-vuong', 'Bất Lương Nhân Chi: U Minh Cổ Vương', 'Invisible Guard', 'https://phimimg.com/upload/vod/20250823-1/a7dc2a385db8e01a7f336232b7c5dcda.jpg', 'https://phimimg.com/upload/vod/20250823-1/5d26e4c59cca456c9bb2054b1ea03183.jpg', '<p>Thời Đường có một bộ máy đặc biệt —— Bất Lương Nhân bọn họ là những nha dịch nhưng bản thân lại là những tội phạm. Một vụ án điều khiển rối côn trùng giết người, khiến bất lương soái Bùi Tiển và những người khác rơi vào tình thế khó khăn.Bùi Tiển người đang chuyên tâm điều tra không biết rằng điều chờ đợi họ ở phía trước sẽ là một âm mưu đáng sợ hơn...</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Anh Đan","avatar":""},{"name":"Trịnh Minh","avatar":""},{"name":"Đinh Liễu Yên","avatar":""},{"name":"Tăng Thiên Vũ","avatar":""},{"name":"Trương Phong Quân","avatar":""},{"name":"Hà Mộng Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Invistble Guard","不良人之幽冥蛊王"]', 1784690324263);
