INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-quai-kiet', 'Băng Đảng Quái Kiệt', 'The Bad Guys', 'https://phimimg.com/upload/vod/20250823-1/35e1e5df0a4546d2a2206347e0ade451.jpg', 'https://phimimg.com/upload/vod/20250823-1/1865ef85659eed318a420281ad4d0d11.jpg', '<p>Năm nhân vật phản diện khét tiếng, những người đã dành cả cuộc đời cùng nhau để thực hiện những vụ cướp lớn, mệt mỏi với cuộc sống tội ác và quyết định sống cuộc đời của họ như những lực lượng lương thiện</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sam Rockwell","avatar":""},{"name":"Marc Maron","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Richard Ayoade","avatar":""},{"name":"Zazie Beetz","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Lilly Singh","avatar":""},{"name":"Barbara Goodson","avatar":""},{"name":"Dina Morrone","avatar":""},{"name":"Michael Godere","avatar":""},{"name":"Kelly Cooney Cilella","avatar":""},{"name":"Walt Dohrn","avatar":""},{"name":"David P. Smith","avatar":""},{"name":"John Venzon","avatar":""},{"name":"Jesse Averna","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["더 배드 가이즈","ザ・バッド・ガイズ","Лоши момци","De Bad Guys","坏家伙们","Pis Uşaqlar","පහේ කල්ලිය","Os Caras Malvados","The Bad Guys"]', 1784690324263);
