INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-ruc-lua-2022', 'Con Đường Rực Lửa', 'Falling Into You', 'https://phimimg.com/upload/vod/20250821-1/99ea20e418650855a7f7c61d5e04c33e.jpg', 'https://phimimg.com/upload/vod/20250821-1/05e3f07f29973fd7775344a541ad699c.jpg', '<p>Con Đường Rực Lửa – Falling Into You (2022) với sự tham gia diễn chính của bộ đôi Kim Thần – Vương An Vũ, được chuyển thể từ tiểu thuyết cùng tên của tác giả Twentine. Nội dung phim xoanh quanh mối tình chị em cách nhau 8 tuổi, nữ chính là huấn luyện viên của nam chính. Trong phim Kim Thần vào vai nữ chính La Na – một huấn luyện viên có cá tính mạnh mẽ, luôn nhiệt huyết, tận tâm và có trách nhiệm với công việc của mình. Trong khi đó Vương An Vũ vào vai Đoàn Vũ Thành – một chàng trai trẻ ngây ngô tràn đầy năng lượng, có đam mê tuyệt đối với bộ môn thể thao điền kinh. Trong quá trình gắn bó, hỗ trợ, cùng nhau phát triển, La Na và Vũ Thành dẫn nảy sinh tình cảm. Liệu tình yêu đôi lứa có vượt qua được rào cản về tuổi tác?</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Thần","avatar":""},{"name":"Vương An Vũ","avatar":""},{"name":"Trì Gia","avatar":""},{"name":"Trương Khải Oánh","avatar":""},{"name":"Lý Trác Chiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cayendo en ti","Falling Into You","炽道"]', 1784690324263);
