INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-phan-dien-cua-toi', 'Bạn Trai Phản Diện Của Tôi', 'Mr. Bad', 'https://phimimg.com/upload/vod/20250821-1/d7b3e97302011a268dcf8358ae657fe2.jpg', 'https://phimimg.com/upload/vod/20250821-1/134be00b55a45cea1eaec3cb73ed81f5.jpg', '<p>Nam Tinh (do Thẩm Nguyệt thủ vai) là một cô gái có sở thích viết tiểu thuyết, trong lúc cầu nguyện đã vô tình triệu hồi nhân vật phản diện Tiêu Vô Địch (do Trần Triết Viễn thủ vai) trong cuốn tiểu thuyết của cô. Tiêu Vô Địch thông minh và xảo quyệt vừa mới đến thế giới này, đã đe dọa Nam Tinh và sống cạnh nhà cô ấy, hai người họ bắt đầu một cuộc sống tranh giành và bất đồng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Triết Viễn","avatar":""},{"name":"Thẩm Nguyệt","avatar":""},{"name":"Lạc Minh Kiệt","avatar":""},{"name":"Khương Trinh Trinh","avatar":""},{"name":"Quốc Tiếu Thiên","avatar":""},{"name":"Tô Tử San","avatar":""},{"name":"Đổng Huyên","avatar":""},{"name":"Vương Tự Kiện","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的反派男友","Mr BAD"]', 1784690324263);
