INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-trai-phan-dien-cua-toi', 'Bạn Trai Phản Diện Của Tôi', 'Mr. Bad', 'bạn trai phản diện của tôi mr. bad trần triết viễn thẩm nguyệt lạc minh kiệt khương trinh trinh quốc tiếu thiên tô tử san đổng huyên vương tự kiện 我的反派男友 mr bad', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-nay-co-em', 'Đời Này Có Em', 'Because Of Love (I Have You In This Life)', 'https://phimimg.com/upload/vod/20250818-1/fba77e4ea88f7a114f9694e1d503465a.jpg', 'https://phimimg.com/upload/vod/20250818-1/d3000eb63e1526cc15a3b1ec06726cc7.jpg', '<p>Đời Này Có Em kể về bà mẹ đơn thân Đàm Tĩnh sống cùng cậu con trai mắc bệnh tim bẩm sinh. Để tiết kiệm tiền phẫu thuật cho con trai, Đàm Tĩnh làm việc chăm chỉ và sống chắt chiu. Dù cuộc sống khó khăn nhưng cô không hề oán hận và bất mãn, cô vẫn độc lập và mạnh mẽ, tự mình nuôi dạy con khôn lớn. Nhiếp Vũ Thịnh là một bác sĩ phẫu thuật, người đang chuẩn bị một dự án để giúp đỡ trẻ em mắc bệnh tim bẩm sinh, và con trai của Đàm Tĩnh là người đầu tiên được chọn. Khi đi khám, Vũ Thịnh mới biết mẹ của đứa trẻ chính là Đàm Tĩnh, người tình của anh 7 năm trước. Trong quá trình điều trị, Vũ Thịnh vẫn bị thu hút bởi vẻ đẹp của sự kiên trì và dũng cảm ở Đàm Tĩnh, đồng thời cũng bị rung động trước sự dễ thương của con trai cô. Cuộc sống và thời gian đã cho cả hai bên thật nhiều thử thách, liệu họ có can đảm để đối diện với tình yêu một cách chín chắn hơn?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cổ Bân","avatar":""},{"name":"Lý Tiểu Nhiễm","avatar":""},{"name":"Vương Dương","avatar":""},{"name":"Điền Lôi Hi","avatar":""},{"name":"Chung Hán Lương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["a Chance Meeting","В этой жизни у меня есть ты","往後餘生","Jin Sheng You Ni","For The Rest Of Your Life","今生有你","Wang Hou Yu Sheng","Because of Love","往后余生"]', 1784690324263);
