INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-nay-co-em', 'Đời Này Có Em', 'Because Of Love (I Have You In This Life)', 'đời này có em because of love (i have you in this life) cổ bân lý tiểu nhiễm vương dương điền lôi hi chung hán lương a chance meeting в этой жизни у меня есть ты 往後餘生 jin sheng you ni for the rest of your life 今生有你 wang hou yu sheng because of love 往后余生', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-tu-phan-1', 'Thứ Tư (Phần 1)', 'Wednesday (Season 1)', 'https://phimimg.com/upload/vod/20250806-1/39b47c939bc52e34b1c11ce01b34acce.jpg', 'https://phimimg.com/upload/vod/20250806-1/b1583a89ebe62e7b32887a38ef505666.jpg', '<p>Thông minh, hay châm chọc và &quot;chết trong lòng&quot; một chút, Wednesday Addams điều tra một vụ giết người liên hoàn trong khi có thêm bạn và cả kẻ thù mới ở Học viện Nevermore.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jenna Ortega","avatar":""},{"name":"Emma Myers","avatar":""},{"name":"Joy Sunday","avatar":""},{"name":"Hunter Doohan","avatar":""},{"name":"Moosa Mostafa","avatar":""},{"name":"Georgie Farmer","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Isaac Ordonez","avatar":""},{"name":"Luyanda Unati Lewis-Nyawo","avatar":""},{"name":"Victor Dorobantu","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Billie Piper","avatar":""},{"name":"Evie Templeton","avatar":""},{"name":"Owen Painter","avatar":""},{"name":"Noah B. Taylor","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Вэнсдэй","星期三","ოთხშაბათი","Γουένσντεϊ Άνταμς","וונסדי","Merlina","Уэнсдэй","Венздей","Sreda","เวนส์เดย์","Wednesday Addams","Uenzdey","Wednesday"]', 1784690324263);
