INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-tu-phan-1', 'Thứ Tư (Phần 1)', 'Wednesday (Season 1)', 'thứ tư (phần 1) wednesday (season 1) jenna ortega emma myers joy sunday hunter doohan moosa mostafa georgie farmer catherine zeta-jones luis guzmán isaac ordonez luyanda unati lewis-nyawo victor dorobantu steve buscemi billie piper evie templeton owen painter noah b. taylor вэнсдэй 星期三 ოთხშაბათი γουένσντεϊ άνταμς וונסדי merlina уэнсдэй венздей sreda เวนส์เดย์ wednesday addams uenzdey wednesday', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-tu-hang-ma', 'Lãng Tử Hàng Ma', 'Subdue The Devil', 'https://phimimg.com/upload/vod/20250804-1/a8891ac1ada5d4bea4f5563ed64ad9b4.jpg', 'https://phimimg.com/upload/vod/20250804-1/53879a9c1c4ca72c223444179dc10a58.jpg', '<p>Châu Chu một thanh niên có sức mạnh siêu nhiên, ngang ngạnh và nổi loạn, luôn làm điều xấu với mục đích tốt bị người dân coi như kẻ quái dị. Vào một đêm, để cứu những đứa trẻ ở ngoài thành, Châu Chu đã giết chết yêu quái hổ trắng, nhưng không ngờ lại mang đến tai họa cho người dân nơi đây. Trong trận chiến với Hổ Vương, Châu Chu bị thương nặng. Sau đó, Hổ Vương đã sử dụng các trò ảo thuật của mình, người dân nơi đây rơi vào cảnh lầm than. Châu Chu từ khi mất đi siêu năng lực, trở thành một người bình thường, nhận được sự ưu ái, chăm sóc của mọi người, nhận ra những sai lầm trước đây của mình, đồng thời hiểu được tinh thần và trách nhiệm của một anh hùng. Cuối cùng, Châu Chu đã quay lại, mặc bộ giáp Thiên Tinh của cha mình để lại, đánh bại Hổ Vương.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Dực","avatar":""},{"name":"Đường Bản","avatar":""},{"name":"Trần Quốc Khôn","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Lang Zi Xiang Mo","Subdue the Devil","浪子降魔"]', 1784690324263);
