INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-mon-am-nhan', 'Kỳ Môn Ám Nhẫn', 'Strange Door and Dark Blade', 'https://phimimg.com/upload/vod/20250804-1/8fadaea23107537fd81a465be42711c0.jpg', 'https://phimimg.com/upload/vod/20250804-1/1cae0c0d33009ad11add5b1f693ccae6.jpg', '<p>Trong thời kỳ thái bình của nhà Tống và nhà Liêu, Đường Tử Yên một đặc vụ được đào tạo bởi tổ chức bí mật &quot;Phụng Hỏa Quân&quot;, được đưa vào hoàng thành nhậm chức. Khi cô muốn rời khỏi chốn kinh thành về sống yên bình cùng phu quân thì bị đe dọa, phu quân bị Phụng Hỏa Quân cưỡng chế bắt đi và giao nhiệm vụ mới cho Đường Tử Yên là ám sát đặc sứ triều đại phương Bắc.Khi phu quân bị Phụng Hỏa Quân giết hại, Tử Yên đã quyết tâm lật đổ Phụng Hỏa Quân. Cô giả vờ như không bị dao động và tiếp tục lên kế hoạch cho bước tiếp theo của kế hoạch ám sát, nhưng bất ngờ khi phát hiện ra mục tiêu chỉ ở bên cạnh mình. Cuối cùng, Tử Yên cùng với đặc sứ đã cùng nhau đánh bại Phụng Hỏa Quân trả lại sự thái bình cho kinh thành.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Vịnh Hy","avatar":""},{"name":"Kỳ Thánh Hàn","avatar":""},{"name":"Triệu Nham","avatar":""},{"name":"Trịnh Hi Y","avatar":""},{"name":"Đỗ Ngọc Minh","avatar":""},{"name":"Trương Xuân Trung","avatar":""},{"name":"Dương Hạnh","avatar":""},{"name":"Trình Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Qi Men an Ren","Qimen Dark Blade","기문도","奇门暗刃"]', 1784690324263);
