INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-mon-am-nhan', 'Kỳ Môn Ám Nhẫn', 'Strange Door and Dark Blade', 'kỳ môn ám nhẫn strange door and dark blade lưu vịnh hy kỳ thánh hàn triệu nham trịnh hi y đỗ ngọc minh trương xuân trung dương hạnh trình đào qi men an ren qimen dark blade 기문도 奇门暗刃', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-nguyen-10-nam-10-nam-con-lai', 'Ước Nguyện 10 Năm (10 Năm Còn Lại)', 'The Last 10 Years', 'https://phimimg.com/upload/vod/20250804-1/6761c2096eae5062b530a736b9299d57.jpg', 'https://phimimg.com/upload/vod/20250804-1/10fc1d0b23bd3a6a6a9a66bd5559e028.jpg', '<p>Chỉ còn 10 năm để sống, Matsuri chẳng còn mơ mộng đến một tương lai hạnh phúc và luôn cố gắng chạy trốn khỏi tình yêu. Nhưng kể từ sau lần gặp Kazuto, từ 2 con người không có lý do để tồn tại lại khao khát sống hạnh phúc cùng nhau. Bộ phim dựa trên tiểu thuyết của Kosaka Ruka và cũng là câu chuyện có thật của cô. Cô qua đời năm 2017 ở tuổi 39 vì căn bệnh nan y.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nana Komatsu","avatar":""},{"name":"Kentaro Sakaguchi","avatar":""},{"name":"Yuki Yamada","avatar":""},{"name":"Satoru Iguchi","avatar":""},{"name":"Haru Kuroki","avatar":""},{"name":"Tetsushi Tanaka","avatar":""},{"name":"Hideko Hara","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"Nao","avatar":""},{"name":"Toko Miura","avatar":""},{"name":"Hibiki Kitazawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yomei 10-nen","The Last 10 Years","Jomei 10 nen","Yomei Ju-nen","餘命10年","余生那些年","여명 10년","よめいじゅうねん","۱۰ سال آخر","Son 10 İl","Ước Nguyện 10 Năm","Os Últimos 10 Anos","余命10年"]', 1784690324263);
