INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('uoc-nguyen-10-nam-10-nam-con-lai', 'Ước Nguyện 10 Năm (10 Năm Còn Lại)', 'The Last 10 Years', 'ước nguyện 10 năm (10 năm còn lại) the last 10 years nana komatsu kentaro sakaguchi yuki yamada satoru iguchi haru kuroki tetsushi tanaka hideko hara yutaka matsushige lily franky nao toko miura hibiki kitazawa yomei 10-nen the last 10 years jomei 10 nen yomei ju-nen 餘命10年 余生那些年 여명 10년 よめいじゅうねん ۱۰ سال آخر son 10 i̇l ước nguyện 10 năm os últimos 10 anos 余命10年', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-lan-quyet-ban-hoat-hinh-phan-1', 'Thương Lan Quyết (Bản Hoạt Hình) (Phần 1)', 'Love Between Fairy And Devil (Season 1)', 'https://phimimg.com/upload/vod/20250803-1/0dbdf54104fad719e36d3af88638402a.jpg', 'https://phimimg.com/upload/vod/20250803-1/d0c7d4ffc0640904ef29bde485ada2ae.jpg', '<p>Đông Phương Thanh Thương người bị đàn áp hàng ngàn năm đã quay trở lại Tam giới, sau khi hồi sinh, đã gây ra một cuộc chiến giữa tiên giới và ma giới, nhưng vì linh lực chưa hồi phục nên đã bị trọng thương. Để trốn thoát, Ma tôn và tiểu tiên Tiểu Lan Hoa đã hoán đổi linh hồn, nhưng Tiểu Lan Hoa, vì không muốn điều khiển ma lực nên đã vô tình làm chết tiên thân của mình, hai người rơi vào tình thế khó xử khi dùng chung thân thể. Trong cơn tuyệt vọng, cả hai lao vào hành trình tìm kiếm một cơ thể mới. Trên đường đi, cả hai trải qua đủ thứ chuyện, Tiểu Tiên Hoa đã thầm yêu Đông Phương Thanh Thương nhưng không hề biết rằng lúc này Đông Phương Thanh Thương chỉ coi cô ấy như một công cụ để hồi sinh. Hơn nữa một âm mưu vô cùng lớn đang âm thầm diễn ra trong sự yên bình...</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ajie","avatar":""},{"name":"Nie Xiying","avatar":""},{"name":"Yang Tianxiang","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["苍兰诀动画版","Cang Lan Jue","蒼蘭訣","Love Between Fairy and Devil","Love Between Fairy and Devil (Animation)","苍兰诀"]', 1784690324263);
