INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-lac-bo-ryman', 'Câu Lạc Bộ Ryman', 'Salaryman''s Club', 'https://phimimg.com/upload/vod/20250728-1/b2b4c0105a778bca81516ea355ef69f5.jpg', 'https://phimimg.com/upload/vod/20250728-1/b711a2a8b3e1e88a524d7630d45630e6.jpg', '<p>Câu Lạc Bộ Ryman kể về Mikoto Shiratori, một thần đồng cầu lông, người bị chấn thương sau trận thua tại giải đấu liên cấp. Sau chấn thương, anh trở thành nhân viên làm công ăn lương tại công ty Sunlight Beverage và kết bạn với Tatsuru Miyazumi, cầu thủ kiêm nhân viên bán hàng có thành tích tốt nhất trong đội.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Junya Enoki","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Tetsuya Kakihara","avatar":""},{"name":"Ryota Osaka","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Haruki Ishiya","avatar":""},{"name":"Yukihiro Nozuyama","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Daiki Hamano","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Tomokazu Sugi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Ryman''s Club","リーマンズクラブ"]', 1784690324263);
