INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-lung-so-hai-tai-sinh', 'Kẻ Săn Lùng Sợ Hãi: Tái Sinh', 'Jeepers Creepers: Reborn', 'https://phimimg.com/upload/vod/20250727-1/c4d3f64491ee76152c8bff65161e2a9a.jpg', 'https://phimimg.com/upload/vod/20250727-1/37e15761fe4c727ba92c338c2cfbfff8.jpg', '<p>Kẻ Săn Lùng Sợ Hãi: Tái Sinh mở ra câu chuyện về Horror Hound Festival (Lễ hội Chó săn kinh dị) diễn ra lần đầu tiên tại Louisiana, lễ hội này thu hút hàng trăm người hâm mộ quái đản, có sở thích với những điều kinh dị từ khắp nơi tụ họp về. Trong số đó có fanboy Chase và bạn gái Laine - cô bị ép buộc đi vì phải chở bạn trai đến Louisiana. Khi sự kiện càng đến gần, Laine bắt đầu trải qua những linh cảm không thể giải thích được và trong tiềm thức cô thấy những viễn cảnh ghê rợn từng diễn ra tại thị trấn này, đặc biệt là về huyền thoại quỷ săn thịt người Creeper. Trong lúc diễn ra lễ hội, Laine cảm nhận được nhiều điều kì lạ, rùng rợn tại lễ hội này đang tập trung vào cô. Và cô chính là nhân vật được tế trong sự kiện đẫm máu lần này.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sydney Craven","avatar":""},{"name":"Imran Adams","avatar":""},{"name":"Jarreau Benjamin","avatar":""},{"name":"Peter Brooke","avatar":""},{"name":"Ocean Navarro","avatar":""},{"name":"Matt Barkley","avatar":""},{"name":"Dee Wallace","avatar":""},{"name":"Gary Graham","avatar":""},{"name":"Gabriel Freilich","avatar":""},{"name":"Timo Vuorensola","avatar":""},{"name":"Georgia Goodman","avatar":""},{"name":"Terry Bird","avatar":""},{"name":"Colin Murtagh","avatar":""},{"name":"Jodie Mcmullen","avatar":""},{"name":"Alexander Halsall","avatar":""},{"name":"Sophie Walker","avatar":""},{"name":"Helen Laure","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Jeepers Creepers 4","Джиперс Криперс: Возрождённый","El Mensajero de Satanás: Renace","שובו של הג׳יפרס קריפרס","ג''יפרס קריפרס 4: נולד מחדש","ジーパーズ クリーパーズ: リボーン","โฉบกระชาก กลับมาเกิด","Jeepers Creepers: El renacer","Jeepers Creepers: La reencarnación del demonio","Jeepers Creepers: Reborn"]', 1784690324263);
