INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-san-lung-so-hai-tai-sinh', 'Kẻ Săn Lùng Sợ Hãi: Tái Sinh', 'Jeepers Creepers: Reborn', 'kẻ săn lùng sợ hãi: tái sinh jeepers creepers: reborn sydney craven imran adams jarreau benjamin peter brooke ocean navarro matt barkley dee wallace gary graham gabriel freilich timo vuorensola georgia goodman terry bird colin murtagh jodie mcmullen alexander halsall sophie walker helen laure jeepers creepers 4 джиперс криперс: возрождённый el mensajero de satanás: renace שובו של הג׳יפרס קריפרס ג''יפרס קריפרס 4: נולד מחדש ジーパーズ クリーパーズ: リボーン โฉบกระชาก กลับมาเกิด jeepers creepers: el renacer jeepers creepers: la reencarnación del demonio jeepers creepers: reborn', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-la-mat-song-sinh', 'Người Lạ Mặt Song Sinh', 'Stranger Anniversary', 'https://phimimg.com/upload/vod/20250727-1/03ddd4a4fd1e9d980266e70bea257749.jpg', 'https://phimimg.com/upload/vod/20250727-1/5d4f05dca8c8803114c163c2028a711e.jpg', '<p>Cao Thu Thành (Mã Đức Chung đóng) là một đại luật sư có danh có tiếng, trưởng văn phòng luật uy tín thuộc tập đoàn của ba vợ anh - đại gia Lợi Quán Khanh (Khương Đại Vệ đóng). Nhưng cuộc sống như mơ bên vợ là nữ luật sư tài giỏi, xinh đẹp - Lợi Tử Doanh (Trần Vỹ đóng) bỗng chốc xáo trộn khi anh tình cờ biết đến trang web “Người khác trong tôi”. Qua đó, anh phát hiện người yêu cũ của mình - Du Phong (Thang Lạc Văn đóng) đăng tin tìm một người giống anh để làm bạn trai ngắn hạn. Mười tám năm trước, khi đang yêu nhau thắm thiết thì Thành bỏ đi không từ biệt.

Người ứng tuyển là Vu Kỳ Nam (Mã Đức Chung đóng) có ngoại hình y hệt Thành. Vừa lo lắng người yêu cũ bị lợi dụng, vừa muốn bù đắp tình cảm dang dở khi xưa, Thành bí mật thỏa thuận với Nam để được làm người yêu thế thân của Du Phong trong hai tuần. Đồng thời, Nam sẽ đóng vai Thành, vừa đối phó với vợ và ba vợ Thành, vừa ứng phó với những mối nguy ở văn phòng luật sư.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2022, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Roxanne Tong","avatar":""},{"name":"Alice Chan Wai","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Matthew Ho","avatar":""},{"name":"Angel Chiang","avatar":""},{"name":"Winki Lai","avatar":""},{"name":"Tsui Wing","avatar":""},{"name":"Pak Man-Biu","avatar":""},{"name":"Lesley Chiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["雙生陌生人","Stranger Anniversary"]', 1784690324263);
