INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luon-mai-yeu-em', 'Luôn Mãi Yêu Em', 'Always Amore', 'https://phimimg.com/upload/vod/20250727-1/4313d6d95b40b4e3b7c5ccc7aa94b914.jpg', 'https://phimimg.com/upload/vod/20250727-1/1e40ae63572c6772090dbe2e3f9f73dd.jpg', '<p>Một góa phụ bất đắc dĩ phải thuê chuyên gia tư vấn để giúp duy trì hoạt động cho nhà hàng của người chồng quá cố. Khi dần mở lòng để thay đổi, liệu cô có thể đón nhận tình yêu mới?</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Autumn Reeser","avatar":""},{"name":"Tyler Hynes","avatar":""},{"name":"Patty McCormack","avatar":""},{"name":"Lisa Marie DiGiacinto","avatar":""},{"name":"Lyndsey Gavin","avatar":""},{"name":"Matthew Del Bel Belluz","avatar":""},{"name":"Rachelle Goulding","avatar":""},{"name":"Peter Bryant","avatar":""},{"name":"Francisca Dennis","avatar":""},{"name":"Latonya Williams","avatar":""},{"name":"Seth Ranaweera","avatar":""},{"name":"Miranda Edwards","avatar":""},{"name":"Kurt Long","avatar":""},{"name":"Jovanna Huguet","avatar":""},{"name":"Eli Gabay","avatar":""},{"name":"Scott Me","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Always Amore"]', 1784690324263);
