INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-dao-cang-thuong', 'Lỗi Đạo Cang Thường', 'Violating Ethical Conduct', 'https://phimimg.com/upload/vod/20250726-1/0a18a132186fcb471f2378188c5a81a1.jpg', 'https://phimimg.com/upload/vod/20250726-1/4f1ef5edc2c7d076bbb482c54e2cbaaa.jpg', '<p>Lỗi Đạo Cang Thường là câu chuyện về một Như Bình nhẫn tâm bỏ người vợ tàu khang nuôi mình ăn học, một Oanh lạnh lùng để lại chồng con bơ vơ đi theo tiếng gọi của giàu sang và nhân tình. Liệu khi bỏ hết những tình xưa nghĩa cũ, Oanh có được sống cuộc sống sung sướng như mình hằng mơ ước khi không được bà Thân, mẹ của Hội đồng Đàng chấp nhận - lại còn bị trượt chân làm sảy thai? Như Bình liệu có hạnh phúc khi Hai Hương với sức khỏe yếu như ngọn đèn trước gió, còn gia sản nhà cô vốn do Bà chủ Phận quản lý bấy lâu nay?</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Oanh Kiều","avatar":""},{"name":"Phúc An","avatar":""},{"name":"Mã Hiểu Đông","avatar":""},{"name":"Dương Cẩm Lynh","avatar":""},{"name":"Hòa Hiệp","avatar":""},{"name":"Huy Khánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324263);
