INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trinh-cong-son', 'Trịnh Công Sơn', 'Trinh Cong Son', 'https://phimimg.com/upload/vod/20250725-1/edd73e05b3e8bed50ed8257f6e493ccb.jpg', 'https://phimimg.com/upload/vod/20250725-1/9f2461cf1707dce3df4e6e545fd1d774.jpg', '<p>Phim cùng tên tác giả “Trịnh Công Sơn” dài 93 phút, chỉ xoay quanh tuổi trẻ của chàng Trịnh, từ một chàng thư sinh theo chủ nghĩa lãng mạn, trở thành một nhạc sĩ vĩ đại, viết vì tình yêu và nỗi đau nhân loại. Những bóng hồng đến rồi đi trong phim Trịnh Công Sơn là nguồn cảm hứng mãnh liệt để chàng Trịnh tìm thấy trong đó một tình yêu lớn, vĩnh cửu với âm nhạc và cái đẹp. Bộ phim tràn đầy cảm hứng về người nhạc sĩ vĩ đại, đã sống và sáng tác trong chiến tranh với tình yêu cứu rỗi, vượt lên mọi tan vỡ, khổ đau.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lương Anh Vũ","avatar":""},{"name":"Phạm Nguyễn Lan Thy","avatar":""},{"name":"Hoàng Hà","avatar":""},{"name":"Bùi Lan Hương","avatar":""},{"name":"Phạm Nhật Linh","avatar":""},{"name":"Samuel An","avatar":""},{"name":"Việt Hưng","avatar":""},{"name":"Hà Quốc Hoàng","avatar":""},{"name":"Bảo Long","avatar":""},{"name":"Trọng Trinh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Phim \"Trịnh Công Sơn\"","Trịnh Công Sơn"]', 1784690324263);
