INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-roi', 'Trăng Rơi', 'Moonfall', 'https://phimimg.com/upload/vod/20250725-1/65a62650a023c1e57da378a42cecacd6.jpg', 'https://phimimg.com/upload/vod/20250725-1/fe91e121eb06e3166abf2cb30c8817b6.jpg', '<p>Năm 2011, một tai nạn ngoài vũ trụ khiến một phi hành gia tử vong đầy bí ẩn. Đúng 10 năm sau, Mặt Trăng đột nhiên rời khỏi quỹ đạo và dần trên đường va chạm với Trái Đất. Chuyện dường như có liên quan tới tai nạn năm xưa, và chỉ có những đồng đội của phi hành gia xấu số kia mới có thể tìm ra chân tướng sự việc, cũng như bản chất của Mặt Trăng sau hàng tỷ năm bị giấu kín.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Halle Berry","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"John Bradley","avatar":""},{"name":"Charlie Plummer","avatar":""},{"name":"Kelly Yu","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Carolina Bartczak","avatar":""},{"name":"Zayn Maloney","avatar":""},{"name":"Ava Weiss","avatar":""},{"name":"Hazel Nugent","avatar":""},{"name":"Chris Sandiford","avatar":""},{"name":"Jonathan Maxwell Silver","avatar":""},{"name":"Eme Ikwuakor","avatar":""},{"name":"Stephen Bogaert","avatar":""},{"name":"Maxim Roy","avatar":""},{"name":"Ryan Bommarito","avatar":""},{"name":"Kathleen Fee","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["วันวิบัติ จันทร์ถล่มโลก","月球隕落","Moonfall: Ameaça Lunar","ムーンフォール：2022","Moonfall"]', 1784690324263);
