INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-moi-gioi', 'Người Môi Giới', 'Broker', 'https://phimimg.com/upload/vod/20250725-1/c51173d272a1bf2925851374c12a6bf2.jpg', 'https://phimimg.com/upload/vod/20250725-1/4f323a2a9deabc9d23deef2b3fee8d2b.jpg', '<p>Sang-hyun (Song Kang Ho) là chủ một cửa tiệm giặt ủi ngập đầu trong nợ nần. Dong-soo (Gang Dong Won) – từng là trẻ mồ côi và hiện đang làm việc cho một cơ sở vận hành “chiếc hộp em bé”. Vào một đêm mưa gió, Sang-hyun và Dong-soo lén lút mang đi một đứa bé vừa bị bỏ rơi trong hộp. Trớ trêu thay, bà mẹ trẻ So-young (Lee Ji Eun) đột nhiên đổi ý và quay trở lại tìm con mình. Dù bán tín bán nghi, So-young quyết định tham gia vào chuyến đi kỳ lạ tìm kiếm gia đình mới cho chính con mình. Trong lúc đó, nữ cảnh sát Soo-jin (Doona Bae) cùng cấp dưới của mình, cảnh sát Lee (Lee Joo Young) đã luôn theo sát và chứng kiến toàn bộ quá trình. Họ lặng lẽ theo dõi bộ ba để thu thập những bằng chứng mang tính quyết định. Cuộc hành trình bám theo những người môi giới của các thanh tra sẽ diễn biến theo một chiều hướng mà chính họ cũng không thể lường trước được. Tất cả mọi chuyện đều bắt đầu từ “chiếc hộp em bé”.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Kang-ho","avatar":""},{"name":"Gang Dong-won","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"IU","avatar":""},{"name":"Lee Joo-young","avatar":""},{"name":"Lim Seung-soo","avatar":""},{"name":"Park Ji-yong","avatar":""},{"name":"Song Sae-byuk","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Lee Mu-saeng","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Kim Sae-byuk","avatar":""},{"name":"Bek Hyun-jin","avatar":""},{"name":"Oh Hee-jun","avatar":""},{"name":"Ryu Kyung-soo","avatar":""},{"name":"Jong Ho","avatar":""},{"name":"Sung Yu-been","avatar":""},{"name":"Park Kang-seop","avatar":""},{"name":"Kim Keum-soon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["요람","Beurokeo","브로커"]', 1784690324263);
