INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liep-lang-hanh-dong', 'Liệp Lang Hành Động', 'Dealer Hunting', 'https://phimimg.com/upload/vod/20250725-1/0d5e69d03784f926506ab2e9fa5b824d.jpg', 'https://phimimg.com/upload/vod/20250725-1/dfa5ed1ee4d8557d7a3acd1d9945eae0.jpg', '<p>Thiên Gia là trùm ma túy lớn nhất Giang Thành. Anh ta hành động một cách thận trọng và không bao giờ tham gia vào các giao dịch một cách trực tiếp. Để bắt được Thiên Gia, đội trưởng đội chống ma túy của Sở Công an thành phố Bình Giang Trần Xương Vinh, đã bí mật thâm nhập vào cơ sở buôn bán ma túy của Thiên Gia. Trận chiến cuối cùng đã gần kề!</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lỗ Nặc","avatar":""},{"name":"Lý Tinh","avatar":""},{"name":"Bành Phác","avatar":""},{"name":"Điền Tùng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["猎狼行动"]', 1784690324263);
