INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-panama', 'Cuộc Chiến Panama', 'Panama', 'https://phimimg.com/upload/vod/20250725-1/c4943abeef55cea36133bb9d7f377dd2.jpg', 'https://phimimg.com/upload/vod/20250725-1/88beb3994a9797291ed464c96435fdc3.jpg', '<p>Một cựu lính thủy đánh bộ được một nhà thầu quốc phòng thuê tới Panama để hoàn tất một hợp đồng mua bán vũ khí. Trong quá trình này, anh ta tham gia vào cuộc xâm lược Panama của Hoa Kỳ và học được một bài học quan trọng về bản chất thực sự của quyền lực chính trị.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Puerto Rico', 0, '[{"name":"Cole Hauser","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Kate Katzman","avatar":""},{"name":"Charlie Weber","avatar":""},{"name":"Jackie Cruz","avatar":""},{"name":"Victor Turpin","avatar":""},{"name":"Simon Phillips","avatar":""},{"name":"Kiara Liz","avatar":""},{"name":"Priscilla Huggins","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Panama"]', 1784690324263);
