INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-mat-tich', 'Thành Phố Mất Tích', 'The Lost City', 'https://phimimg.com/upload/vod/20250724-1/b092df0ceec61db5fae37ba505d26aca.jpg', 'https://phimimg.com/upload/vod/20250724-1/8e93030baa2f2afe15635885e8f9676d.jpg', '<p>Loretta Sage thường viết tiểu thuyết về những lăng mộ cổ và nhiều cuộc phiêu lưu táo bạo, nhưng điều đó không có nghĩa là cô ấy sẵn sàng đối diện với chúng trong đời thực. Bị một tỷ phú lập dị bắt cóc để truy tìm tung tích thành phố mất tích trong truyền thuyết, Alan, người mẫu trang bìa điển trai của Loretta, đã tiến hành một cuộc giải cứu quả cảm nhưng lại kém may mắn. Trải qua chuyến hành trình ly kỳ và hoành tráng xuyên qua rừng rậm, cặp đôi lạc quẻ phải hợp tác và kiên nhẫn với nhau để vượt qua các hiện tượng thiên nhiên và tìm ra kho báu theo lời đồn tại thành phố trước khi nó biến mất vĩnh viễn.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Daniel Radcliffe","avatar":""},{"name":"Da''Vine Joy Randolph","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Oscar Nuñez","avatar":""},{"name":"Patti Harrison","avatar":""},{"name":"Bowen Yang","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Joan Pringle","avatar":""},{"name":"Héctor Aníbal","avatar":""},{"name":"Thomas Forbes-Johnson","avatar":""},{"name":"Sli Lewis","avatar":""},{"name":"Olga Buccarelli","avatar":""},{"name":"Adam Nee","avatar":""},{"name":"Raymond Lee","avatar":""},{"name":"Omar Pati","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài