INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('acapulco-phan-2', 'Acapulco (Phần 2)', 'Acapulco (Season 2)', 'https://phimimg.com/upload/vod/20250724-1/c93060a3e4b5c9a2aba7df8bdd577556.jpg', 'https://phimimg.com/upload/vod/20250724-1/2b3007c4c2b1dba7396aa0645ef4d833.jpg', '<p>Năm 1984, mong ước của Maximo Gallardo trở thành hiện thực khi anh nhận được công việc trong mơ ở khu nghỉ mát hấp dẫn hàng đầu, Las Colinas. Thế nhưng, anh sớm nhận ra rằng công việc ở đây phức tạp hơn nhiều so với những gì anh tưởng tượng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eugenio Derbez","avatar":""},{"name":"Enrique Arrizon","avatar":""},{"name":"Raphael Alejandro","avatar":""},{"name":"Camila Perez","avatar":""},{"name":"Chord Overstreet","avatar":""},{"name":"Fernando Carsa","avatar":""},{"name":"Jessica Collins","avatar":""},{"name":"Vanessa Bauche","avatar":""},{"name":"Regina Reynoso","avatar":""},{"name":"Rafael Cebrian","avatar":""},{"name":"Bianca Marroquín","avatar":""},{"name":"Regina Orozco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["阿卡普尔科","אקפולקו","Acapulco"]', 1784690324263);
