INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-den-van-gia', 'Hạnh Phúc Đến Vạn Gia', 'The Story Of Xing Fu', 'https://phimimg.com/upload/vod/20250722-1/201e9228e61d058fe65a4989aa95a23a.jpg', 'https://phimimg.com/upload/vod/20250722-1/6fc6e3a557e182f74b409bf35350eed9.jpg', '<p>Cả Vạn Gia Trang đến chung vui cùng nhà họ Vương vì cậu con trai cả Khánh Lai cưới được vợ đẹp, cô dâu mới Hạnh Phúc. Thế nhưng ngay trong ngày đại hỉ này, một vụ quấy rối tập thể xảy ra mà nạn nhân chính là em gái cô dâu đã dẫn đến hậu quả không ngờ: Cô dâu Hạnh Phúc đánh bể đầu con trai ông bí thư Vạn. Liệu cô dâu mới Hạnh Phúc có thể tiếp tục sống ở Vạn Gia Trang bằng bản lĩnh kiên cường của mình hay không?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Lưu Uy","avatar":""},{"name":"Đường Tằng","avatar":""},{"name":"La Tấn","avatar":""},{"name":"Trương Khả Doanh","avatar":""},{"name":"Lưu Diễn Thần","avatar":""},{"name":"Tân Bằng","avatar":""},{"name":"Tống Nguyên Phủ","avatar":""},{"name":"Ngô Cương","avatar":""},{"name":"Huệ Anh Hồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Story Of Xing Fu","ความสุขของซิ่งฝู","幸福到万家"]', 1784690324263);
