INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-he-thien-duong-phan-1', 'Mùa Hè Thiên Đường (Phần 1)', 'The Summer I Turned Pretty (Season 1)', 'mùa hè thiên đường (phần 1) the summer i turned pretty (season 1) lola tung christopher briney gavin casalegno sean kaufman rain spencer jackie chung isabella briggs kristen connolly 我变美的那夏天 我变漂亮的那个夏天 el verano en que me enamoré הקיץ בו הפכתי ליפה 내가 예뻐진 그 여름 то лето, когда я похорошела літо, коли я стала привабливою the summer i turned pretty', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-khung-long-lanh-dia', 'Thế Giới Khủng Long: Lãnh Địa', 'Jurassic World Dominion', 'https://phimimg.com/upload/vod/20250717-1/3efe7f608495e862c7fd261b30ddfe1e.jpg', 'https://phimimg.com/upload/vod/20250717-1/15155c2afc0685b31e13473b00f9299b.jpg', '<p>Bốn năm sau kết thúc Jurassic World: Fallen Kingdom, những con khủng long đã thoát khỏi nơi giam cầm và tiến vào thế giới loài người. Giờ đây, chúng xuất hiện ở khắp mọi nơi. Sinh vật to lớn ấy không còn chỉ ở trên đảo như trước nữa mà gần ngay trước mắt, thậm chí còn có thể chạm tới. Owen Grady may mắn gặp lại cô khủng long mà anh và khán giả vô cùng yêu mến - Blue. Tuy nhiên, Blue không đi một mình mà còn đem theo một chú khủng long con khác. Điều này khiến Owen càng quyết tâm bảo vệ mẹ con cô được sinh sống an toàn. Thế nhưng, hai giống loài quá khác biệt. Liệu có thể tồn tại một kỷ nguyên mà khủng long và con người sống chung một cách hòa bình?</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris Pratt","avatar":""},{"name":"Bryce Dallas Howard","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"DeWanda Wise","avatar":""},{"name":"Mamoudou Athie","avatar":""},{"name":"Isabella Sermon","avatar":""},{"name":"Campbell Scott","avatar":""},{"name":"BD Wong","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Justice Smith","avatar":""},{"name":"Daniella Pineda","avatar":""},{"name":"Scott Haze","avatar":""},{"name":"Dichen Lachman","avatar":""},{"name":"Kristoffer Polaha","avatar":""},{"name":"Caleb Hearon","avatar":""},{"name":"Freya Par","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85