INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-troi-day-cua-khien-hiep-si-phan-2', 'Sự Trỗi Dậy Của Khiên Hiệp Sĩ (Phần 2)', 'The Rising Of The Shield Hero (Season 2)', 'https://phimimg.com/upload/vod/20240509-1/4657b469c8dbab3cd8c392ee46d5dc9d.jpg', 'https://phimimg.com/upload/vod/20240509-1/b32e12d251f9dda963c35e219b74eb62.jpg', '<p>Naofumi và các bạn lên đường đến vương quốc bên cạnh để ngăn mối đe dọa trong truyền thuyết gây ra tai họa chưa từng có đối với thế giới.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ishikawa Kaito","avatar":""},{"name":"Seto Asami","avatar":""},{"name":"Hidaka Rina","avatar":""},{"name":"Matsuoka Yoshitsugu","avatar":""},{"name":"Takahashi Makoto","avatar":""},{"name":"Yamaya Yoshitaka","avatar":""},{"name":"Hara Natsuko","avatar":""},{"name":"Uchida Maaya","avatar":""},{"name":"Inoue Kikuko","avatar":""},{"name":"Hanazawa Kana","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324263);
