INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-troi-day-cua-khien-hiep-si-phan-2', 'Sự Trỗi Dậy Của Khiên Hiệp Sĩ (Phần 2)', 'The Rising Of The Shield Hero (Season 2)', 'sự trỗi dậy của khiên hiệp sĩ (phần 2) the rising of the shield hero (season 2) ishikawa kaito seto asami hidaka rina matsuoka yoshitsugu takahashi makoto yamaya yoshitaka hara natsuko uchida maaya inoue kikuko hanazawa kana ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-khe-uoc-minh-than', 'Địch Nhân Kiệt: Khế Ước Minh Thần', 'Detective Dee And The Pact With The Underworld Gods', 'https://phimimg.com/upload/vod/20250714-1/7c9022d913d9b5a411687d2571a5319c.jpg', 'https://phimimg.com/upload/vod/20250714-1/19e262cc1597ee98d9dd0a2d4904d6ff.jpg', '<p>Vào năm Thiên Thọ thứ hai, một sự kiện chấn động đã xảy ra ở Ngụy Châu. Khi chủ tiệm cầm đồ bị giết, người ta đồn rằng do Minh Thần làm. Lòng dân hỗn loạn, lo sợ và họ cho rằng do hoàng đế loạn chính, dẫn đến trời giận người căm. Võ Tắc Thiên tức giận sai Địch Nhân Kiệt đi điều tra sự việc. Với những suy luận phá án thông minh cùng tài quan sát, ông đã nhanh chóng tìm ra thủ phạm về quy án, đem lại sự trong sạch cho triều Đường.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạ Cương","avatar":""},{"name":"Hoàng Nhất Sơn","avatar":""},{"name":"Trương Toàn Đản","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Revive in a New Guis","狄仁傑之冥神契約","狄仁杰之冥神契约","Di Renjie zhi ming shen qiyue"]', 1784690324263);
