INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-ban-voi-ke-thu', 'Làm Bạn Với Kẻ Thù', 'Friend To Enemy', 'https://phimimg.com/upload/vod/20250713-1/47fb957feec44cdf72d306c18e8e0a8b.jpg', 'https://phimimg.com/upload/vod/20250713-1/c684073948d384c171fec79b0b7b4be8.jpg', '<p>Là bạn thân, nhưng Weiha, Tawan đều đem lòng yêu Nithang. Bi kịch ập đến khi mẹ của cả hai cùng qua đời đầy bí ẩn. Giữa bao sóng gió, liệu tình bạn ấy vẫn bền vững hay sẽ thành tình tay ba rối rắm?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2022, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Iang Sittha Sapanuchart","avatar":""},{"name":"Saran Sirilak","avatar":""},{"name":"Yuranunt Pamornmontri","avatar":""},{"name":"Willie McIntosh","avatar":""},{"name":"Maprang Alrisa Kunkwaeng","avatar":""},{"name":"Songsit Rungnopakunsi","avatar":""},{"name":"Siriam Pakdeedumrongrit","avatar":""},{"name":"Amarin Nitipon","avatar":""},{"name":"Asre Wattanayakul","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["深蓝向日葵","Fah Tan Tawan","ฟ้า/ทาน/ตะวัน"]', 1784690324263);
