INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuc-dia-nguc', 'Vực địa ngục', 'Hellhole', 'vực địa ngục hellhole piotr żurawski olaf lubaszenko sebastian stankiewicz lech dyblik rafał iwaniuk krzysztof satała malwina dubowska zbigniew waleryś antoni augustyniak wojciech niemczyk kamil pardo ireneusz tomaszewski rafał kiełbowicz józef smok sylwester now ขุมนรก l''abîme de l''enfer ヘルホール 悪霊館 ostatnia wieczerza', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-quoc-dai-trinh-tham', 'Dân Quốc Đại Trinh Thám', 'Checkmate', 'https://phimimg.com/upload/vod/20250709-1/18495faa4353fe3abe5e69c891eaee93.jpg', 'https://phimimg.com/upload/vod/20250709-1/1911c674d9bc2cf641d73f67016ab80d.jpg', '<p>Xoay quanh những vụ án được xâu chuỗi với nhau, che giấu âm mưu lớn từ vụ án chính. Tư Đồ Nhan là một luật sư trẻ và cũng là công tố viên. Lúc này, anh đang buộc tội võ sư người Anh là nghi phạm trong vụ án giết người ở nhà ga nhưng vì võ sư người Anh được bao che bởi thế lực bên ngoài và kết quả là anh ta được trắng án, nhân dân phẫn nộ khắp nơi. Tư Đồ Nhan không chấp nhận được nên đã từ chức. Trong lúc vô cùng tuyệt vọng, ân sư Thẩm Kiến Đức mời anh đến Cáp Nhĩ Tân để cùng thành lập văn phòng luật sư cũng như giúp anh tìm lại chân lý trong tim mình. Tư Đồ Xuyên đã cố gắng hết sức để tìm ra kẻ sát nhân thật sự. Sau khi chân tướng được làm rõ, dù cho kết quả không như dự đoán nhưng khả năng suy luận thiên tài của Tư Đồ Nhan được mọi người khen ngợi không ngớt. Cùng lúc đó, Thiếu Xuyên cũng liên quan đến một vụ thảm sát, Thiếu Xuyên đã nhờ Tư Đồ Nhan giúp anh rửa sạch hàm oan. Tư Đồ Nhan không phụ lòng kỳ vọng, đã giúp Thiếu Xuyên rửa sạch nỗi oan và họ trở thành sinh tử chi giao.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Nhất Thiên","avatar":""},{"name":"Trương Vân Long","avatar":""},{"name":"Trương Hinh Dư","avatar":""},{"name":"Tuyên Ngôn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Checkmate 2022","民国大侦探"]', 1784690324263);
