INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-vang', 'Đãi Vàng', 'Gold Panning', 'https://phimimg.com/upload/vod/20250709-1/052aa1c6999151c09c3e94141d9e3636.jpg', 'https://phimimg.com/upload/vod/20250709-1/c914215a9bdcff22ff98d0f4cdfff646.jpg', '<p>Năm 1986, Trần Bảo Kim mới 20 tuổi, đến khu vực Altai tìm người anh trai đã mất tích khi đi đãi vàng. Trong hoàn cảnh phức tạp, anh ấy bị cuốn vào cuộc tranh chấp giữa nhiều thế lực. Đồng thời, nhiều việc kỳ lạ xảy ra liên tiếp. Sau vượt qua nhiều khó khăn, tất cả các manh mối đều dẫn anh ấy sang Tỉ Muội Hải, một nơi thần bí giữ bảo tàng to lớn mà không ai sống sót trở về được. Trong quá trình đấu tranh với con người và thiên nhiên, anh ấy tìm được &quot;Giếng Thứ Bảy&quot; trong Tỉ Muội Hải và chân tướng về việc mất tích của anh trai. Cuối cùng anh hiểu rõ dũng khí và cái thiện mới là bảo tàng quan trọng nhất với nhân loại.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Liêu Phàm","avatar":""},{"name":"Trần Phi Vũ","avatar":""},{"name":"Lữ Hiểu Lâm","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["1986淘金惊魂","淘金"]', 1784690324263);
