INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang-bup-be-thu-do-cua-toi-biet-yeu-phan-1', 'Nàng Búp Bê Thử Đồ Của Tôi Biết Yêu (Phần 1)', 'My Dress-Up Darling (Season 1)', 'nàng búp bê thử đồ của tôi biết yêu (phần 1) my dress-up darling (season 1) hina suguta shoya ishige atsumi tanezaki hina youmiya atsushi ono minha adorável cosplayer 更衣人偶坠入爱河 恋上换装娃娃 יקירתי מתלבשת sono bisuku dōru wa koi wo suru sono kisekae ningyou wa koi wo suru sono kisekae ningyō wa koi wo suru sono bisque doll wa koi wo suru sono bisuku douru wa koi wo suru любовь с иголочки эта фарфоровая кукла влюбилась ملابسي يا عزيزي 戀上換裝娃娃 戀上換裝娃娃 season 2 my dress-up darling その着せ替え人形は恋をする', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luyen-khi-3000-nam', 'Luyện Khí 3000 Năm', 'Qi Refining For 3000 Years', 'https://phimimg.com/upload/vod/20250707-1/8a90528fee0845bfa9506980223582d1.jpg', 'https://phimimg.com/upload/vod/20250707-1/5eab4a5c85651851a1ebea8afbfd4d41.jpg', '<p>Ba ngàn năm trước, Bạch Thu Nhiên thiên tư tuyệt đỉnh được người sáng lập Thanh Minh Kiếm Tông Thanh Minh Đạo Nhân thu làm đệ tử, bắt đầu con đường tu tiên.

Ba ngàn năm về sau, sư tôn Thanh Minh Đạo Nhân của Bạch Thu Nhiên phi thăng thành Tiên, đại sư huynh Độ Kiếp thất bại thân tử đạo tiêu, ngay cả tiểu sư muội nhỏ nhất cũng đột phá thành trúc cơ, học xong ngự kiếm cưỡi gió mà đi.

Mà kinh lịch trải qua ba ngàn năm khổ tu, Bạch Thu Nhiên hắn, cuối cùng đạt đến Luyện Khí Kỳ thứ sáu vạn 6,664 tầng cảnh giới.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiang Xu","avatar":""},{"name":"Xiao Sibai","avatar":""},{"name":"Su Ziwu","avatar":""},{"name":"Li Chunyin","avatar":""},{"name":"Liu Zhaokun","avatar":""},{"name":"Li Yuting","avatar":""},{"name":"Xinchun Cai","avatar":""},{"name":"琦雯","avatar":""},{"name":"Huang Ji","avatar":""},{"name":"Yu Fengshuo","avatar":""},{"name":"Kong Xin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lian Qi Lian Le 3000 Nian","Lianqi Lianle 3000 Nian","Lian Qi Lianle 3000 Nian","Liàn Qì Liàn Liǎo 3000 Nián","炼气练了三千年","Qi Refining for 3000 years","Refinador de Qi por 3000 años","I Have Refined Qi For 3000 Years","I AM Legend","Qi Refining for 3000 Years","I Have Refined Qi For 3000 Years!","3000 years of Qi Training","Refining Qi for 3000 years","Ta Ba Ngàn Năm Luyện Khí","炼气练了3000年"]', 1784690324263);
