INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-x-phan-2', 'Hồ Sơ X (Phần 2)', 'The Taiwan X-Files (Part 2)', 'https://phimimg.com/upload/vod/20250628-1/3a3c60da06cdae3235837f859d3e0d5e.jpg', 'https://phimimg.com/upload/vod/20250628-1/5ff03828a805b275c977ca354d2be9cf.jpg', '<p>Tệ nạn ma túy ngày càng nghiêm trọng, thậm chí còn nhắm đến đối tượng học sinh cấp một, cấp hai. Đội điều tra các nước muốn xử lý triệt để đường dây này, còn các tổ chức phi pháp lại đang cố gắng tranh giành bằng được công nghệ sản xuất ma túy mới. Trước tình hình đó, một đội điều tra đặc biệt gồm các thành viên tinh anh được thành lập để truy lùng bọn tội phạm nguy hiểm, dập tắt mọi âm mưu xấu xa của chúng.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 16, 2022, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Lưu Thư Hoành","avatar":""},{"name":"Dương Nhã Trúc","avatar":""},{"name":"Chu Vũ Mưu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Taiwan X Files","台灣X檔案"]', 1784690324263);
