INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ha-xan-lan', 'Tinh Hà Xán Lạn', 'Love Like The Galaxy', 'https://phimimg.com/upload/vod/20250625-1/b59a8c62a0fa15d8c56b1d20dfced21a.jpg', 'https://phimimg.com/upload/vod/20250625-1/3d0d671c31861eabc31468b369ea80b1.jpg', '<p>Nữ nhi Trình gia tên Thiếu Thương, vì chiến loạn nên từ nhỏ phải ở cùng bà nội, nhưng gặp phải thẩm nương ác độc, ý đồ nuôi dạy nàng thành phế nhân. Đối mặt với cạm bẫy trùng trùng, nàng vì mạng sống mà giả vờ hư hỏng, che giấu tài năng chờ cha mẹ trở về. Tình cờ, Trình tiểu thư gặp gỡ và kết giao cùng nghĩa tử Lăng Bất Nghi của tân đế, tài tử Viên Thận của núi Bạch Lộc, Lâu Nghiêu con em thế gia. Ba chàng trai tuấn tú, mỗi người có một ưu điểm riêng, liệu ai sẽ ngự trị trong tim nàng Thiếu Thương?</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 14, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Lỗi","avatar":""},{"name":"Triệu Lộ Tư","avatar":""},{"name":"Tằng Lê","avatar":""},{"name":"Từ Kiều","avatar":""},{"name":"Trần Ý Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["the Starry Man","ستاره باشکوه","Любовь как галактика","Сияние звёзд","ดาราจักรรักลำนำใจ","Love Like the Galaxy","The Stars Are Brilliant","Splendid Stars","星汉灿烂"]', 1784690324263);
