INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-gui-mot-toi-nguoi-da-yeu-em', 'Nhắn Gửi Một Tôi, Người Đã Yêu Em', 'To Me, the One Who Loved You', 'https://phimimg.com/upload/vod/20250624-1/0997792f22d6674dfa43e8b0dcdbe470.jpg', 'https://phimimg.com/upload/vod/20250624-1/644873bb9ececd804d6a0742de5aa774.jpg', '<p>&quot;Nhắn gửi một tôi, người đã yêu em&quot; là câu chuyện tình yêu đầy biến cố của Hidaka Koyomi và Satou Shiori, hai đứa trẻ cùng chịu cảnh gia đình không trọn vẹn, gặp nhau ở Viện nghiên cứu Khoa học Hư chất. Cả hai dần có tình cảm với nhau nhưng bố mẹ của hai người lại tái hôn và họ trở thành anh-em kế. Hai người quyết định sẽ cùng nhau chạy trốn đến một thế giới khác, nơi mà họ có thể ở bên nhau, nhưng biến cố xảy ra...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hio Miyazawa","avatar":""},{"name":"Aju Makita","avatar":""},{"name":"Ai Hashimoto","avatar":""},{"name":"Kimiko Yo","avatar":""},{"name":"Maki Mizuno","avatar":""},{"name":"Tokuma Nishioka","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kimi wo Aishita Hitori no Boku e","KimiAi","Parallel World part 2 - ถึงผมคนหนึ่งที่รักเธอ","To the Solitary Me That Loved You","To the Solitary Me Who Loved You","致深愛妳的那個我","Kimi o Aishita Hitori no Boku e","너를 사랑했던 한 사람의 나에게","君を愛したひとりの僕へ"]', 1784690324263);
