INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-quen-anh-yeu-em', 'Đừng Quên Anh Yêu Em', 'Don''t Forget I Love You', 'https://phimimg.com/upload/vod/20250624-1/9a675821d3c24728a1b61157d790acb9.jpg', 'https://phimimg.com/upload/vod/20250624-1/27307b4ea27cc3be07768d21443f8815.jpg', '<p>Mỗi sáng thức dậy, Hứa Tinh Nguyệt phải đối diện với một Lục Nghiêu luôn quên đi chuyện hôm qua cũng quên đi cô. Yêu nhau đến thế, lại xa cách như thế, liệu họ có vượt lên tất cả để có cái kết đẹp?</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cổ Lực Na Trát","avatar":""},{"name":"Lưu Dĩ Hào","avatar":""},{"name":"Trương Hâm Nghệ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["فراموش نکن دوستت دارم","یادت نره عاشقتم","不要忘记我爱你"]', 1784690324263);
