INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-thanh-trong-guong', 'Cô Thành Trong Gương', 'Lonely Castle In The Mirror', 'cô thành trong gương lonely castle in the mirror ami touma mana ashida yuki kaji takumi kitamura sakura kiryu rihito itagaki naho yokomizo minami takayama kumiko aso aoi miyazaki shingo fujimori karen takizawa the solitary castle in the mirror el castillo a través del espejo kagami no kojou かがみの孤城', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-hoa-luc', 'Mộng Hoa Lục', 'A Dream Of Splendor', 'https://phimimg.com/upload/vod/20250623-1/bf36dc99dccaf22281529215fb1ebf0e.jpg', 'https://phimimg.com/upload/vod/20250623-1/8a8c16fe0f003862b2258bfdb0145ecb.jpg', '<p>Triệu Phán Nhi, chủ quán trà ở Hàng Châu nhận được tin vui vị hôn phu của nàng - Âu Dương Húc đã đậu thám hoa ở kinh thành, nhưng kết quả là hắn đã bỏ rơi nàng. Không muốn chấp nhận số phận, nàng thề phải tới kinh thành đòi lại công bằng. Trên đường tới kinh thành, nàng đã cứu tỷ muội tốt của mình là Tống Dẫn Chương bị người ta lừa cưới mà rơi vào cảnh bị ngược đãi, đồng thời nàng cũng cứu giúp Tôn Tam Nương, người muốn nhảy sông tự vẫn vì cuộc sống hôn nhân bất hạnh. Khi Âu Dương Húc biết được tin Triệu Phán Nhi đã đến kinh thành, tìm được nơi ở của hắn, hắn liền tìm đủ cách để đuổi nàng ra khỏi Biện Kinh. Triệu Phán Nhi, Tống Dẫn Chương và Tôn Tam Nương đã quyết định ở lại Biện Kinh, dựa vào bản lĩnh của mình để kiếm sống. Trải qua muôn vàn khó khăn, gặp đủ mọi trắc trở, cuối cùng thì ba tỷ muội cũng phát triển từ một quán trà trở thành một tửu lâu lớn nhất tại Biện Kinh.</p>', 'Hoàn Tất (/)', 40, 'series', 'completed', 9, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Diệc Phi","avatar":""},{"name":"Trần Hiểu","avatar":""},{"name":"Liễu Nham","avatar":""},{"name":"Lâm Duẫn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["汴京梦华图","Meng hua lu","MengHuaLu","Мечта о величии","สามบุปผาลิขิตฝัน","A Dream of Splendor","梦华录"]', 1784690324263);
