INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-o-gaus', 'Chuyện Tình Ở Gaus', 'Gaus Electronics', 'https://phimimg.com/upload/vod/20250623-1/779cd358c5e2ad5eeebebd183a240faa.jpg', 'https://phimimg.com/upload/vod/20250623-1/e5297ba44a75cbfda27532a8e40588f8.jpg', '<p>Chuyện Tình Ở Gaus xoay quanh cuộc sống công việc lẫn tình yêu của những người trẻ tài năng đầy nhiệt huyết đang làm chung trong bộ phận marketing 3 tại Gaus Electronics. Lee Sang Sik (Kwak Dong Yeon đóng) - thông minh, suy nghĩ tích cực, tính cách tươi sáng nhưng khuyết điểm là không để ý đến tâm trạng của người khác vì vậy hay gây ra rắc rối ngoài ý muốn trong văn phòng. Cha Na Rae (Go Sung Hee đóng) - trợ lý giám đốc, tính khí như lửa, cọc cằn khó chịu. Baek Ma Tan (Bae Hyun Seong đóng) - con trai trong gia đình đang điều hành một công ty lớn, là người kiệm lời. Geon Kang Mi (Kang Min Ah đóng) - nhân viên nữ xinh đẹp nhất công ty nhưng khi say xỉn thì cô trở thành một người hoàn toàn khác.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kwak Dong-yeon","avatar":""},{"name":"Ko Sung-hee","avatar":""},{"name":"Bae Hyeon-seong","avatar":""},{"name":"Kang Min-ah","avatar":""},{"name":"Bek Hyun-jin","avatar":""},{"name":"Heo Jeong-do","avatar":""},{"name":"Jeon Seok-chan","avatar":""},{"name":"Koh Woo-ri","avatar":""},{"name":"Baek Soo-jang","avatar":""},{"name":"Cho Jung-chi","avatar":""},{"name":"Lee So-hee","avatar":""},{"name":"Kim Kyeong-il","avatar":""},{"name":"Sazal Mahamud","avatar":""},{"name":"Jeon Jung-il","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["高斯电子","گاوس الکترونیک","Gaus Jeonja","ဂါအူးစ် အီလက်ထရောနစ်","Компания \"Гаус Электроникс\"","高斯電子公司","가우스전자"]', 1784690324263);
