INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-ca-heo', 'Cậu Bé Cá Heo', 'Dolphin Boy', 'https://phimimg.com/upload/vod/20241127-1/c6bcc5db13332a1bba994d4a6078c120.jpg', 'https://phimimg.com/upload/vod/20241127-1/89413b2e34f7a416a6e754eaf3404e9e.jpg', '<p>Cậu bé Cá Heo lớn lên trong lòng đại dương bao la dưới sự nuôi dạy của hai mẹ con cá heo Nana và Bông Tuyết. Cho đến khi Bạch Tuộc độc ác nắm quyền cai trị nơi đây, cậu bé bị đưa về đất liền. Được một thuyền trưởng tốt bụng chăm sóc, cậu bắt đầu hành trình tìm hiểu chính mình và đấu tranh cho thế giới dưới nước.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2022, 'Lồng Tiếng', 'FHD', 'Đức', 0, '[{"name":"Polina Avdeenko","avatar":""},{"name":"Yuliya Rudina","avatar":""},{"name":"Boris Khasanov","avatar":""},{"name":"Yuliya Zorkina","avatar":""},{"name":"Vasilisa Ruchimskaya","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Мальчик-дельфин","Malchik-delfin","Sea Level 3: Dolphin Boy","El niño delfín","Dolphin Boy","Yunus Çocuk","Izurde Mutikoa","El nen dofí","Dolphin Boy - Abenteuer unter dem Meer","الولد الدولفين"]', 1784690324263);
