INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ma-bup-be-chucky-phan-2', 'Ma Búp Bê Chucky (Phần 2)', 'Chucky (Season 2)', 'ma búp bê chucky (phần 2) chucky (season 2) zackary arthur brad dourif björgvin arnarson alyvia alyn lind devon sawa chucky: a série чаки 鬼娃恰吉 child''s play: the tv series don mancini''s chucky chucky', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luan-ai-xung-danh-anh-hung', 'Luận Ai Xứng Danh Anh Hùng', 'Heroes', 'https://phimimg.com/upload/vod/20250608-1/9da076a5f7c74af337a5bfcac406b058.jpg', 'https://phimimg.com/upload/vod/20250608-1/4db750730ea6b83d4b97341cce519eb7.jpg', '<p>Bộ phim&nbsp;chuyển thể từ tiểu thuyết võ hiệp cùng tên của nhà văn Ôn Thụy An. Bộ phim xoay quanh thiếu niên anh hùng Vương Tiểu Thạch (Tăng Thuấn Hi), trời sinh tính tình thiện lương là đồ đệ của Thiên Y cư sĩ. Tiểu Thạch xuống núi đi ngao du, lần đầu bước chân vào chốn giang hồ, nhân duyên đưa đẩy gặp gỡ và kết giao bằng hữu chí cốt với Ôn Nhu (Dương Siêu Việt), Bạch Sầu Phi (Lưu Vũ Ninh) và Tô Mộng Chẩm (Trần Sở Hà). Bốn người với xuất thân khác nhau cùng một chí anh hùng mà quyết lập lời thề hẹn kiếp này. Họ cùng nhau vượt qua những khó khăn, hiểm nguy khó lường nơi giang hồ hiểm ác, dần trưởng thành và hiểu được đạo nghĩa làm người, chí anh hùng thật sự.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Siêu Việt","avatar":""},{"name":"Lưu Vũ Ninh","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Tằng Thuấn Hy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["说英雄谁是英雄","說英雄誰是英雄"]', 1784690324263);
