INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-cuu-hoa-chicago-phan-11-2022', 'Đội Cứu Hoả Chicago (Phần 11)', 'Chicago Fire (Season 11)', 'đội cứu hoả chicago (phần 11) chicago fire (season 11) taylor kinney david eigenberg joe miñoso christian stolte miranda rae mayo daniel kyri hanako greensmith jocelyn hudon jake lockett dermot mulroney chicago fire : caserne 51 风城烈火 芝加哥烈火群英 chicago fire שיקגו fire שיקגו פייר آتش‌نشانی شیکاگو чикаго в огне one chicago chicago fire', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hau-luu-hac-ban', 'Hoàng Hậu Lưu Hắc Bàn', 'The Legendary Life Of Queen Lau', 'https://phimimg.com/upload/vod/20250602-1/e69359688b6bc31385f46958ed570568.jpg', 'https://phimimg.com/upload/vod/20250602-1/d26017dc5e64b67364142733bf1f4225.jpg', '<p>Phim kể về hành trình trở thành hoàng hậu của Lưu Hắc Bàn (Lạt Mục Dương Tử). Nàng là con rơi của Thừa tướng đương triều Lưu Hiết. Hai mẹ con nàng bị cha bỏ rơi tại miền thôn quê, số mạng của nàng luôn gắn liền với mẹ. Đến năm nàng 9 tuổi, vì Thừa tướng Lưu Hiết không có con gái để gả cho Thái tử Đoàn Vân Chướng (Lý Hoành Nghị) nên đành đưa nàng về phủ và nuôi nấng. Lưu Hắc Bàn được gả vào hoàng cung làm hoàng hậu một cách đầy kịch tính chọc toàn triều chê cười, còn bị hoàng đế phu quân cho rằng có tâm mưu hại. Sau đại hôn, hoàng đế thử thách đủ bề, Kim Phượng tiếp chiêu ứng đối, chọc đến hậu cung gà bay chó sủa, theo đôi hoan hỉ oan gia trải qua càng ngày càng nhiều chuyện, từ một đôi không hề xứng, đế hậu lại thành một đôi tình nhân. Hai người từ oan gia rồi trở thành bạn bè, tri kỉ và cùng nhau cai quản giang sơn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lạt Mục Dương Tử","avatar":""},{"name":"Lý Hoành Nghị","avatar":""},{"name":"Trần Hân Dư","avatar":""},{"name":"Quách Thừa","avatar":""},{"name":"Bạch Chú","avatar":""},{"name":"Diêu Thiên Vũ","avatar":""},{"name":"Vương Đông","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["皇后刘黑胖","我叫刘金凤","มเหสีป่วนรัก","皇后劉黑胖","我叫劉金鳳"]', 1784690324263);
