INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anikulapo', 'Aníkúlápó', 'Aníkúlápó', 'https://phimimg.com/upload/vod/20250601-1/45924d5b3f563f2410a2b171cc020298.jpg', 'https://phimimg.com/upload/vod/20250601-1/8c103b3853d9dbe6d687578696a2fa36.jpg', '<p>Sau khi phải chết vì tội ngoại tình với nữ hoàng, người lữ khách sôi nổi gặp một con chim thần bí có quyền năng trao cho anh một cuộc đời khác.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Nigeria', 0, '[{"name":"Kunle Remi","avatar":""},{"name":"Bimbo Ademoye","avatar":""},{"name":"Hakeem Kae-Kazim","avatar":""},{"name":"Sola Sobowale","avatar":""},{"name":"Taiwo Hassan","avatar":""},{"name":"Adebayo Salami","avatar":""},{"name":"Moji Afolayan","avatar":""},{"name":"Adebowale Adedayo","avatar":""},{"name":"Yinka Quadri","avatar":""},{"name":"Samson Eluwole","avatar":""},{"name":"Ronke Ojo","avatar":""},{"name":"Yemi Elebuibon","avatar":""},{"name":"Sunday Omobolanle","avatar":""},{"name":"Ropo Ewenla","avatar":""},{"name":"Ayandotun Emmanuel","avatar":""},{"name":"Kareem Adepoju","avatar":""},{"name":"Dele O","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Anikulapo","Aníkúlápó"]', 1784690324263);
