INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anikulapo', 'Aníkúlápó', 'Aníkúlápó', 'aníkúlápó aníkúlápó kunle remi bimbo ademoye hakeem kae-kazim sola sobowale taiwo hassan adebayo salami moji afolayan adebowale adedayo yinka quadri samson eluwole ronke ojo yemi elebuibon sunday omobolanle ropo ewenla ayandotun emmanuel kareem adepoju dele o anikulapo aníkúlápó', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ha-truong-ha', 'Thiên Hạ Trường Hà', 'The Long River', 'https://phimimg.com/upload/vod/20250531-1/0b40a939417f6ce2a2056d5b68907403.jpg', 'https://phimimg.com/upload/vod/20250531-1/0bca021d9813dde2ef8900bb27ee376f.jpg', '<p>Năm Khang Hy thứ 15, sau một trận lũ lụt lớn, Hoàng đế Khang Hy trẻ tuổi đã tổ chức kỳ thi đặc biệt để tuyển chọn nhân tài trị thủy. Trong số đó, Trần Hoằng, một cử nhân thi trượt 24 tuổi, đã nổi bật nhờ kiến thức sâu rộng về thủy lợi. Ông cùng với Cận Phụ, một quan chức có kinh nghiệm, hợp tác để thực hiện công cuộc trị thủy kéo dài nửa thế kỷ, đối mặt với nhiều biến động chính trị trong triều đình. Tuy nhiên, do sự ganh ghét và âm mưu của các quan lại, Trần Hoằng bị vu cáo và qua đời trong oan ức, để lại tác phẩm &quot;Hà Phòng Thuật Yếu&quot; về kinh nghiệm trị thủy. Đến năm Khang Hy thứ 51, sau khi bình định các vùng đất và ổn định dòng chảy của Hoàng Hà, Hoàng đế Khang Hy đã đến thăm đền thờ hai vị và ghi nhận công lao của họ trong việc bảo vệ đất nước.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2022, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"La Tấn","avatar":""},{"name":"Doãn Phương","avatar":""},{"name":"Hoàng Chí Trung","avatar":""},{"name":"Tề Mỹ Quyên","avatar":""},{"name":"Lương Quán Hoa","avatar":""},{"name":"Tô Khả","avatar":""},{"name":"Lục Tư Vũ","avatar":""},{"name":"Công Lỗi","avatar":""},{"name":"Bạch Khánh Lâm","avatar":""},{"name":"Triệu Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tian Xia Chang He","The Long River","天下长河"]', 1784690324263);
