INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-ha-truong-ha', 'Thiên Hạ Trường Hà', 'The Long River', 'thiên hạ trường hà the long river la tấn doãn phương hoàng chí trung tề mỹ quyên lương quán hoa tô khả lục tư vũ công lỗi bạch khánh lâm triệu kỳ tian xia chang he the long river 天下长河', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-ngua-ben-thuong-hai', 'Đua Ngựa Bến Thượng Hải', 'Shanghai Knight', 'https://phimimg.com/upload/vod/20250530-1/f2fb6b3b4397611eb5bdb227176e69e6.jpg', 'https://phimimg.com/upload/vod/20250530-1/1ea62b2d24d9ff65b0dda18b2fbb2bc6.jpg', '<p>Phim kể về thời Dân quốc Thương hội người Hoa thành lập Câu lạc bộ chơi ngựa. Nhà yêu nước Kim Quảng Vinh vì để giữ được quyền kiểm soát bến cảng đã ký một hiệp định với Thương hội Nhật Bản. Nhưng những tranh chấp của nhiều thế lực vẫn đang ngấm ngầm diễn ra. Mã Vân Phi anh hùng của nơi đây với kỹ năng cưỡi ngựa siêu việt , vì tiểu nhân hãm hại nên có xích mích với Kim Quảng Vinh và sau một đêm đã biến thành &quot;kẻ sát nhân&quot;. Một lần cá cược, một làn sóng âm mưu, và một cuộc đua ngựa gay cấn đã khiến cho bến Thượng Hải vốn đã hỗn loạn lại càng trở nên hỗn loạn hơn...</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lữ Lương Vĩ","avatar":""},{"name":"Đồng Phi","avatar":""},{"name":"Lưu Trác Đình","avatar":""},{"name":"Nhậm Tư Tề","avatar":""},{"name":"Dư Tử Huyên","avatar":""},{"name":"Lý Nham","avatar":""},{"name":"Trần Tác Thâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Lie Ma Zheng Feng Shang Hai Tan","열마쟁봉상해탄","烈马争锋上海滩"]', 1784690324263);
