INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dua-ngua-ben-thuong-hai', 'Đua Ngựa Bến Thượng Hải', 'Shanghai Knight', 'đua ngựa bến thượng hải shanghai knight lữ lương vĩ đồng phi lưu trác đình nhậm tư tề dư tử huyên lý nham trần tác thâm lie ma zheng feng shang hai tan 열마쟁봉상해탄 烈马争锋上海滩', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-ga-ra-kho-bau', 'Thỏ Gà Rà Kho Báu', 'Chickenhare And The Hamster Of Darkness', 'https://phimimg.com/upload/vod/20250527-1/27bdb76cf1dd9640194a627ccc263c58.jpg', 'https://phimimg.com/upload/vod/20250527-1/fb501d41cd505d6a6b9cab3f483e8dda.jpg', '<p>Bộ phim theo chân cuộc phiêu lưu của Chickenhare, vị anh hùng trẻ tuổi sinh ra là nửa thỏ rừng nửa gà, được Vua Peter- một nhà thám hiểm thỏ rừng nổi tiếng nhận nuôi. Chickenhare luôn háo hức với những chuyến phiêu lưu, và mong muốn được yêu thương mặc cho những khác biệt của mình. Khi kẻ phản diện sừng sỏ nhất của vương quốc, cũng chính là cậu của Chickenhare trốn khỏi ngục và đe dọa lật đổ cha mình, Chickenhare dấn thân vào một cuộc đua kỳ thú cùng với Abe- chú rùa thích châm chọc, và Meg- nữ chuyên gia võ thuật liều lĩnh nhằm ngăn chặn âm mưu của cậu mình.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Bỉ', 0, '[{"name":"Jordan Tartakow","avatar":""},{"name":"Joe Ochman","avatar":""},{"name":"Laila Berzins","avatar":""},{"name":"Danny Fehsenfeld","avatar":""},{"name":"Chris McCune","avatar":""},{"name":"Michael Orenstein","avatar":""},{"name":"Dino Andrade","avatar":""},{"name":"Kyle Hebert","avatar":""},{"name":"James Fredrick","avatar":""},{"name":"Jeff Doucette","avatar":""},{"name":"Joey Camen","avatar":""},{"name":"Cedric L. Williams","avatar":""},{"name":"Marcus Griffin","avatar":""},{"name":"Donte Paris","avatar":""},{"name":"Michael Sorich","avatar":""},{"name":"Brad Venable","avatar":""},{"name":"Mark Irons","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Hopper En De Hamster Der Duisternis","Hopper et le hamster des ténèbres","Hopper und der Hamster der Finsternis","Hopper, el polloliebre","Thỏ Gà Rà Kho Báu","怪胎英雄：奇克探險記","飞兔大联盟","鸡兔英雄与暗黑仓鼠","鸡兔联盟：寻找暗黑仓鼠","Hanahérinn og myrkrahamsturinn","Chickenhare and the Hamster of Darkness"]', 1784690324263);
