INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tho-ga-ra-kho-bau', 'Thỏ Gà Rà Kho Báu', 'Chickenhare And The Hamster Of Darkness', 'thỏ gà rà kho báu chickenhare and the hamster of darkness jordan tartakow joe ochman laila berzins danny fehsenfeld chris mccune michael orenstein dino andrade kyle hebert james fredrick jeff doucette joey camen cedric l. williams marcus griffin donte paris michael sorich brad venable mark irons hopper en de hamster der duisternis hopper et le hamster des ténèbres hopper und der hamster der finsternis hopper, el polloliebre thỏ gà rà kho báu 怪胎英雄：奇克探險記 飞兔大联盟 鸡兔英雄与暗黑仓鼠 鸡兔联盟：寻找暗黑仓鼠 hanahérinn og myrkrahamsturinn chickenhare and the hamster of darkness', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pororo-cuoc-phieu-luu-den-dinh-thu-rong', 'Pororo: Cuộc Phiêu Lưu Đến Dinh Thự Rồng', 'Pororo: Dragon Castle Adventure', 'https://phimimg.com/upload/vod/20250527-1/13cf08068b5328fecf9c0513a9cca206.jpg', 'https://phimimg.com/upload/vod/20250527-1/32a727d27acbcba44fa6971a2f11306a.jpg', '<p>Chim cánh cụt đáng yêu Pororo sẽ trở lại vào dịp Tết này với một chuyến phiêu lưu mới. Lần này là cuộc phiêu lưu đến Dinh Thự Rồng. Tên phù thủy xấu xa Gad đang tìm cách đánh cắp &quot;Trái tim Rồng&quot;, một viên ngọc được phong ấn bằng sức mạnh to lớn của vua rồng nhỏ Arthur. Trong khi đó, Crong, người đã vô tình hấp thụ sức mạnh của &quot;Trái tim rồng&quot;, biến thành một Crong khổng lồ và khiến Pororo và những người bạn của cậu gặp nguy hiểm. Arthur, Pororo và những người bạn phải đến Dinh Thự Rồng tham gia vào trận chiến để lấy lại sức mạnh từ tay phù thủy độc ác. Liệu Pororo có thể bảo vệ Dinh Thự Rồng và cứu lấy những người bạn của mình?</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2022, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sun","avatar":""},{"name":"Lee Mi-ja","avatar":""},{"name":"Kim Hyun-ji","avatar":""},{"name":"Hong So-young","avatar":""},{"name":"Chung Mi-sook","avatar":""},{"name":"Kim Seo-young","avatar":""},{"name":"Kim Hwan-jin","avatar":""},{"name":"So Yeon","avatar":""},{"name":"Kim Hye-seong","avatar":""},{"name":"Lee Jang-won","avatar":""},{"name":"Sa Moon-young","avatar":""},{"name":"Um Sang-hyun","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Pororo Movie: Dragon Castle Adventure","뽀로로 극장판 드래곤캐슬 대모험"]', 1784690324263);
