INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-gui-tat-ca-cac-em-nhung-nguoi-toi-da-yeu', 'Nhắn Gửi Tất Cả Các Em, Những Người Tôi Đã Yêu', 'To Every You I''ve Loved Before', 'https://phimimg.com/upload/vod/20250527-1/a6d89076c3f7287e7a6dafb9883e20a5.jpg', 'https://phimimg.com/upload/vod/20250527-1/8d8741145db913352e5dc5464b4a7a1d.jpg', '<p>Trong đa vũ trụ, ta vẫn sẽ là các phiên bản hệt nhau? Người ta yêu ở thế giới khác, vẫn là người ấy chứ? Chuyện tình yêu xuyên vũ trụ của Takasaki Koyomi đã mở ra góc nhìn đặc biệt này cho khán giả.</p>', 'Full', 1, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hio Miyazawa","avatar":""},{"name":"Ai Hashimoto","avatar":""},{"name":"Kimiko Yo","avatar":""},{"name":"Maki Mizuno","avatar":""},{"name":"Tokuma Nishioka","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Boku ga Aishita Subete no Kimi e","BokuAi","Parallel World part 1 - ถึงเธอทุกคนที่ผมรัก","致我深愛的每個妳","To Every You I Have Loved Before","僕が愛したすべての君へ"]', 1784690324263);
