INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-phai-vo-meo-huyen-thoai-mot-chu-cho', 'Môn Phái Võ Mèo: Huyền Thoại Một Chú Chó', 'Paws Of Fury: The Legend Of Hank', 'https://phimimg.com/upload/vod/20250527-1/eca763d7544fd5db2715407c438ce61d.jpg', 'https://phimimg.com/upload/vod/20250527-1/03018103bdc28ff69d17e05461c5fe9d.jpg', '<p>Hank là chú chó đáng yêu có ước mơ trở thành một samurai vĩ đại. Trên con đường đi tìm định mệnh, Hank vô tình lạc vào một thị trấn đầy mèo. Và mèo thì không hề thích chó. Cũng vì mong muốn giành được tình cảm của cư dân thị trấn, Hank vô tình mắc vào âm mưu thôn tính thị trấn của tay mèo phản diện Ika Chu. Ika Chu đã lừa Hank giúp hắn đuổi các cư dân mèo khỏi thị trấn. Cùng với những người bạn mới quen, Hank phải tìm cách ngăn chặn âm mưu của Ika Chu và chuộc lại sai lầm của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Canada', 0, '[{"name":"Michael Cera","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Ricky Gervais","avatar":""},{"name":"Kylie Kuioka","avatar":""},{"name":"Mel Brooks","avatar":""},{"name":"George Takei","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Cathy Shim","avatar":""},{"name":"Stephen Apostolina","avatar":""},{"name":"Kirk Baily","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Ranjani Brow","avatar":""},{"name":"William Calvert","avatar":""},{"name":"David Chen","avatar":""},{"name":"Miles","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["猫狗武林","Blazing Samurai","El perro samurái: La leyenda de Kakamucho","O Lendário Cão Guerreiro","Fureur sur pattes: La légende de Hank","El perro samurái: La Leyenda de Kakamucho","Tomboló blöki","Hundurinn Hank í klóm kattarins","De legende van Samoerai Henk","Blazing Samurai: Myke poter - skarpe klør","Paws of Fury","刀鋒劍客","Tassar av stål","Kung Fu Tačke","Tassar av stål - Legenden om Hank","Samouraï Academy","非常貓狗反轉武林","블레이드 퍼피 워리어","블레이징 사무라이","Пёс-самурай и город кошек","刀锋剑客","Paws of Fury: The Legend of Hank"]', 1784690324263);
