INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-tho-hoi-tu', 'Tinh Thổ Hội Tụ', 'Miraculous 5', 'https://phimimg.com/upload/vod/20250525-1/b1c9b1bff1e3f9ccd641f66fd5ef259f.jpg', 'https://phimimg.com/upload/vod/20250525-1/82c7b1f470df60c8c12e62513c928870.jpg', '<p>Năm người đàn ông được sinh ra cùng ngày — thứ Bảy, ngày mùng 5 — được Apichai nhận nuôi và dẫn dắt họ bước vào con đường tu luyện để trở thành bất tử. Mỗi người đều sở hữu một năng lực đặc biệt: Diao Somdet: có thể nghe được âm thanh từ khoảng cách rất xa. Thoed Yodthong: có khả năng tàng hình khi nín thở. Don Thakradan: trong lúc thiền định có thể du hành không gian và khoảng cách. Yod Nangphaya: có thể xuyên qua mọi vật cản. Kring Khlongtakhian: có tốc độ cực nhanh và có thể biến hình thành bất kỳ ai. Nhiệm vụ của họ là truy đuổi nhóm Jarga, những kẻ đã đánh cắp một quả bom sinh học gây bệnh từ phòng thí nghiệm ở châu Âu và giấu nó tại Thái Lan. Trong hành trình này, họ được hỗ trợ bởi: Bussakorn – con gái của Apichai, một chuyên gia trong lĩnh vực sinh học liên quan đến quả bom. Duangkamol – một phụ nữ dũng cảm, cải trang để thâm nhập và điều tra vụ việc.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jinna Navarat","avatar":""},{"name":"Phattharapon Dejpongwaranon","avatar":""},{"name":"Chanakan Poonsiriwong","avatar":""},{"name":"Oath Ratthee Vorarojyothin","avatar":""},{"name":"Sapol Assawamunkong","avatar":""},{"name":"Anyarin Terathananpat","avatar":""},{"name":"Noey Paphada Klinsuman","avatar":""},{"name":"Jayda Saranya Chunhasart","avatar":""},{"name":"Karn Menisa Chumsaisakul","avatar":""},{"name":"Garn Nuttacha Chayangkanont","avatar":""},{"name":"Nattapon Ra","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["เสาร์ 5"]', 1784690324264);
