INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-chuyen-phan-6', 'Lắm Chuyện (Phần 6)', 'Big Mouth (Season 6)', 'https://phimimg.com/upload/vod/20240509-1/320005e815d8ab77281302c2a229eb06.jpg', 'https://phimimg.com/upload/vod/20240509-1/f6930ee923727361e4780d088bf58526.jpg', '<p>Họ hàng bí mật, câu đố nổi tiếng trên mạng và rắc rối tình cảm châm ngòi cho làn sóng dằn vặt và hành trình tự khám phá mới của nhóm bạn ở trường cấp hai Bridgeton.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick Kroll","avatar":""},{"name":"John Mulaney","avatar":""},{"name":"Jessi Klein","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Jordan Peele","avatar":""},{"name":"Maria Bamford","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Gina Rodriguez","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Ali Wong","avatar":""},{"name":"Chelsea Peretti","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Andrew Rannells","avatar":""},{"name":"Zachary Quinto","avatar":""},{"name":"Ayo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["فم كبير","大嘴巴","Hormonokkal túlfűtve","פה גדול","ビッグマウス","빅마우스","Gură bogată","青春無密語","Bigmouth","Big Mouth"]', 1784690324264);
