INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blueming-hoa-no-vi-em', 'Blueming: Hoa Nở Vì Em', 'Blueming', 'https://phimimg.com/upload/vod/20240403-1/cd01ceded84c48b96452f3fa1c9663ea.jpg', 'https://phimimg.com/upload/vod/20250523-1/76dd8351fde95241f25ca39a69456102.jpg', '<p>Bộ phim Hàn Quốc “Blueming Hoa Nở Vì Em” là bộ phim webtoon BL do MOVIE\u0026NEW và KENAZ Comics hợp tác sản xuất. “Blueming Hoa Nở Vì Em” cải biên từ tiểu thuyết nổi tiếng “Sự Nổi Tiếng Có Gì Đó Sai Sai”, kể về câu chuyện lãng mạn học đường của hai chàng sinh viên khoa điện ảnh: Cha Si Won dùng cách quản lý thấu đáo để bảo thân độc chiếm toàn bộ sự nổi tiếng nhưng sự nổi tiếng đó lại không còn như trước sau khi gặp phải Daun Hyeong – chàng trai vừa sinh ra đã mang theo sự nổi tiếng. Cha Siwon (Gang Eun Bin đóng), khi còn nhỏ từng bị chế giễu là xấu xí, nên cậu quyết tâm thay đổi bản thân. Sau khi trưởng thành, Cha Siwon trở thành một anh chàng đẹp trai. Cậu rất coi trọng sự nổi tiếng của mình và muốn được mọi người chú ý đến mình mọi lúc mọi nơi. Sau khi vào đại học, cậu tự tin rằng mình sẽ trở thành ông hoàng nổi tiếng, nhưng cậu lại gặp phải ông hoàng nổi tiếng thực sự Daun Hyeong (Cho Jun-hyuk đóng), người hoàn hảo cả về ngoại hình, tính cách, lẫn gia đình và điểm số! Bộ phim do đạo diễn Hwang Da Seul của những bộ phim BL đình đám như “Nơi Ánh Mắt Cậu Nán Lại”, “Gửi Đến Ngôi Sao Của Anh” làm đạo diễn.</p>', 'Full', 11, 'series', 'completed', 29, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Eun Bin Kang","avatar":""},{"name":"Hyuk Jun Cho","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324264);
