INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-mole-ai-la-noi-gian-phan-1', 'The Mole: Ai Là Nội Gián (Phần 1)', 'The Mole (Season 1)', 'https://phimimg.com/upload/vod/20250523-1/bb9fd248317bdfb6172f2f9665f4d40d.jpg', 'https://phimimg.com/upload/vod/20250523-1/e2448e768c9e90ac5f641addd1152c69.jpg', '<p>Trong bản làm lại chương trình kinh điển đình đám này, mười hai người chơi hoàn thành các thử thách trong khi cố nhận dạng một kẻ trong số họ đang phá hoại các nhiệm vụ.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ari Shapiro","avatar":""},{"name":"Antonio Alejandro Castellanos","avatar":""},{"name":"Quaylyn","avatar":""},{"name":"Sean","avatar":""},{"name":"Ryan Warner","avatar":""},{"name":"Neesh Riaz","avatar":""},{"name":"Muna Abdulahi","avatar":""},{"name":"Michael O''Brien","avatar":""},{"name":"Melissa Lummus","avatar":""},{"name":"Jennifer","avatar":""},{"name":"Hannah Burns","avatar":""},{"name":"Deanna Thompson","avatar":""},{"name":"Andy Mintzer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["เดอะ โมล","The Mole"]', 1784690324264);
