INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-tap-phan-1', 'Diễn Tập (Phần 1)', 'The Rehearsal (Season 1)', 'https://phimimg.com/upload/vod/20250521-1/7e981d74b0cf3d543f9badb6b47a3fa4.jpg', 'https://phimimg.com/upload/vod/20250521-1/934c4746564140aecf7176ab6cb4776a.jpg', '<p>Nathan Fielder giúp mọi người chuẩn bị cho những khoảnh khắc khó khăn nhất trong cuộc sống bằng cách dàn dựng các buổi diễn tập được thiết kế tỉ mỉ về các sự kiện trong thế giới thực, nhưng những gì bắt đầu bằng việc diễn tập các quyết định khó khăn nhất trong cuộc sống lại trở thành một thử nghiệm gây sốc về khả năng kiểm soát, bản sắc và nỗi ám ảnh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nathan Fielder","avatar":""},{"name":"Anna Lamadrid","avatar":""},{"name":"Journey Baker","avatar":""},{"name":"Gigi Burgdorf","avatar":""},{"name":"Drew Carlan","avatar":""},{"name":"Andrea M. Anderson","avatar":""},{"name":"Gabrielle Guilmette","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["排练人生","彩排","人生彩排","El Ensayo","The Rehearsal"]', 1784690324264);
