INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duyen-kiep', 'Duyên Kiếp', 'Predestined Affinity', 'https://phimimg.com/upload/vod/20250519-1/fa6080bff6b69a1bfa3a586c594145ca.jpg', 'https://phimimg.com/upload/vod/20250519-1/d2d13d33c91f7707809e37ce9b5f1199.jpg', '<p>Duyên kiếp xoay quanh hai chị em Lan (Oanh Kiều), Huệ (Trương Mỹ Nhân) và hai người chủ tớ Thành (Huỳnh Đông), Hai Lương (Bạch Công Khanh). Huệ và Lan cùng sinh ra lớn lên trong một gia đình nông dân nghèo, con gái của một tá điền. Cả hai xinh đẹp, giỏi giang nhất vùng, lại hiếu thảo nên được nhiều trai làng để ý. Tiếng lành vang xa, người người nghe tin đều tỏ lòng mến mộ, dù nhà hai cô nghèo nhất vùng.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Bạch Công Khanh","avatar":""},{"name":"NSƯT Huỳnh Đông","avatar":""},{"name":"Thân Thúy Hà","avatar":""},{"name":"Khương Thịnh","avatar":""},{"name":"Trương Minh Quốc Thái","avatar":""},{"name":"Trương Mỹ Nhân","avatar":""},{"name":"Ngô Phương Anh","avatar":""},{"name":"Oanh Kiều","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324264);
