INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-nhin-thau-tro-gian', 'Kẻ Nhìn Thấu Trò Gian', 'Usogui', 'https://phimimg.com/upload/vod/20250517-1/cc6f4bb9e04ff868b5157ef2b3008208.jpg', 'https://phimimg.com/upload/vod/20250517-1/9299960c6177bc9295d17622243cc280.jpg', '<p>Hội Kakerou là một tổ chức thống trị thế giới ngầm của Nhật Bản, là nơi cờ bạc được thăng hoa. Tại đây có các thành viên là những con bạc sừng sỏ và trọng tài - những người giám sát và thu hồi nợ khi các canh bạc đã hoàn thành. Madarame Baku là một con bạc bí ẩn có biệt danh là Usogui (có nghĩa là Kẻ ăn lời nói dối). Anh tham gia những trận cá cược đầy nguy hiểm, tìm ra những mánh khoé lừa đảo của đối thủ và đánh bại họ để vươn tới đỉnh cao của Kakerou.</p>', 'Full', 1, 'single', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryusei Yokohama","avatar":""},{"name":"Hayato Sano","avatar":""},{"name":"Mai Shiraishi","avatar":""},{"name":"Kanata Hongo","avatar":""},{"name":"Win Morisaki","avatar":""},{"name":"Kaito Sakurai","avatar":""},{"name":"Hiroaki Murakami","avatar":""},{"name":"Shohei Miura","avatar":""},{"name":"Ryô Kimura","avatar":""},{"name":"Shingo Tsurumi","avatar":""},{"name":"Moe Yuki","avatar":""},{"name":"Minoru Matsumoto","avatar":""},{"name":"Satoshi Uekiya","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["บาคุ ลับ ลวง หลอก","Usogui","嘘喰い"]', 1784690324264);
