INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-nam-ay-chung-ta-cung-gay-ra', 'Tội Ác Năm Ấy Chúng Ta Cùng Gây Ra', 'Remember 15', 'https://phimimg.com/upload/vod/20240909-1/67b1d828016ea4202e774b83da53fd3b.jpg', 'https://phimimg.com/upload/vod/20240909-1/415c0c0586ed93f9fefe7f65791592d4.jpg', '<p>Một tin nhắn bí ẩn từ Lyla, một ngôi sao học đường đã tự sát năm năm trước, được gửi đến các bạn học cũ và em gái của cô khiến mọi người hoang mang. 12 người quay trở lại hoang đảo, nơi Lyla đã chết, để tưởng niệm cô và tìm ra ai là người gửi tin nhắn. Nhưng càng tiến gần đến sự thật, họ càng khám phá ra quá khứ tàn khốc của mình. Những bí mật đen tối của những người mà họ gọi là “bạn bè” đã biến hoang đảo này trở thành một đấu trường đẫm máu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Venita Loywattanakul","avatar":""},{"name":"Prapakorn Chairak","avatar":""},{"name":"พฤกษ์ พานิช","avatar":""},{"name":"Sittichok Pueakpoolpol","avatar":""},{"name":"Karn Kritsanaphan","avatar":""},{"name":"Chitsanupong Sakunnanthiphat","avatar":""},{"name":"Purewarin Kosiriwalanon","avatar":""},{"name":"Tanatorn Saenangkanikorn","avatar":""},{"name":"Theerarat Wongchuen","avatar":""},{"name":"Nilawan Iamchuasawad","avatar":""},{"name":"Daranpope Charmpoonod","avatar":""},{"name":"Thanyachano","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324264);
