INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoai-cam', 'Khoái cảm', 'Safe Word', 'https://phimimg.com/upload/vod/20250515-1/bc96cd5fead328d5114f57e2a2e48271.jpg', 'https://phimimg.com/upload/vod/20250515-1/3dd6326b28cf75c3bd561b9570705fb6.jpg', '<p>Cô ca sĩ nhạc rap ngây thơ Misa không gặp vấn đề gì khi đánh những gã đàn ông độc hại. Khi được dạy cách trở thành một người thống trị, cô trở nên tự tin hơn, nhưng liệu cả hai con đường sự nghiệp có phù hợp không? Và bao lâu nữa thì cô sẽ sử dụng từ an toàn của riêng mình &quot;Anh yêu em&quot;?</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Chisako Kawase","avatar":""},{"name":"Nagisa Toriumi","avatar":""},{"name":"Ai Otoha","avatar":""},{"name":"Masahiro Takashima","avatar":""},{"name":"Ryuchell","avatar":""},{"name":"Ryoka Neya","avatar":""},{"name":"Shigehiro Yamaguchi","avatar":""},{"name":"Keisaku Kimura","avatar":""},{"name":"Shigeo Ôsako","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Kōji Shiraishi''s Aishiteru!","Aishiteru!","愛してる！"]', 1784690324264);
