INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-phu-thuy', 'Trò Chơi Phù Thủy', 'Game Of Witches', 'https://phimimg.com/upload/vod/20250515-1/6f6444dc2fa0ae355f0308ffa44c1619.jpg', 'https://phimimg.com/upload/vod/20250515-1/164dd70866123dc5d9bb12b4366bcccb.jpg', '<p>Bộ phim xoay quanh sự trả thù của hai người phụ nữ: Seol Yoo-Kyung là một người phụ nữ xinh đẹp và thành đạt, trước khi trở thành Giám đốc điều hành Tập đoàn Chunha, cô từng là thư ký của Chủ tịch Ma Hyun-Deok, người mà cô nghi ngờ đứng sau vụ hoả hoạn giết chết con gái cô 19 năm trước. Sau khi phát hiện con gái của mình vẫn còn sống, cô đã nhẫn nhịn, âm thầm lên kế hoạch hoàn hảo để trả thù, đồng thời tìm lại đứa con gái thất lạc của mình.</p>', 'Hoàn Tất (79/79)', 79, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Seo-hee","avatar":""},{"name":"Oh Chang-seok","avatar":""},{"name":"Kim Kyu-seon","avatar":""},{"name":"Han Ji-Wan","avatar":""},{"name":"Ban Hyo-jung","avatar":""},{"name":"Kim Si-heon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["魔女的游戏","بازی جادوگر","Manyeoui Geim","마녀의 게임","The Witch''s Game","Trò Chơi Phù Thủy"]', 1784690324264);
