INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-bosch-ke-thua-phan-1', 'Thanh Tra Bosch: Kế Thừa (Phần 1)', 'Bosch: Legacy (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/bd7f7036ac1251a5946563006ebda51d.jpg', 'https://phimimg.com/upload/vod/20231219-1/f85da8269db507b4743a37ffa8ace4b1.jpg', '<p>Bosch hiện đang kiếm sống bằng công việc điều tra viên tư nhân hai năm sau khi anh ta rời khỏi LAPD và thấy mình đang làm việc với kẻ thù một thời và luật sư hàng đầu Honey “Money” Chandler. Trong khi đó, con gái của Bosch, Maddie, đang mạo hiểm tham gia vào thế giới của LAPD.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Titus Welliver","avatar":""},{"name":"Mimi Rogers","avatar":""},{"name":"Madison Lintz","avatar":""},{"name":"Stephen A. Chang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324264);
