INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-the-ly-giai-noi-aharensan-phan-1', 'Chẳng Thể Lý Giải Nổi Aharen-san (Phần 1)', 'Aharen-san wa Hakarenai (Season 1)', 'https://phimimg.com/upload/vod/20240603-1/0f383bf03f61841969d6215f5b536543.jpg', 'https://phimimg.com/upload/vod/20240603-1/42ffbcc1565bb87dc67e3330460b6f80.jpg', '<p>Aharen Reina-san là một cô bạn nhỏ con và trầm lặng. Chẳng những thế còn khá tệ trong việc cân đo khoảng cách tiếp xúc với những người xung quanh. Ngồi cạnh Aharen-san trong lớp là Raidou-kun, cậu rất bận tâm về khoảng cách Aharen-san tạo ra giữa hai người. Cho đến một ngày nọ, khi Raidou-kun nhặt hộ cục tẩy Aharen-san làm rơi, khoảng cách giữa họ đột nhiên thu hẹp lại đến bất ngờ! Thật không thể lường trước được khi nào Aharen-san quá xa hay quá gần. Cùng vén màn câu chuyện tình cảm tuổi trẻ hài hước về mối quan hệ khắn khít khó có thể lý giải này nào!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324264);
