INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-lac-2', 'Đạn Lạc 2', 'Lost Bullet 2', 'https://phimimg.com/upload/vod/20250511-1/e33f233a1569b397507995b3d4637424.jpg', 'https://phimimg.com/upload/vod/20250511-1/35741dfea304bc418e7e1bdc0b1d3305.jpg', '<p>Sau khi được minh oan, thợ máy thiên tài Nilo chỉ có một mục tiêu trong đầu: trả thù những cảnh sát tha hóa đã giết em trai và thầy của anh.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Alban Lenoir","avatar":""},{"name":"Stéfi Celma","avatar":""},{"name":"Pascale Arbillot","avatar":""},{"name":"Sébastien Lalanne","avatar":""},{"name":"Diego Martín","avatar":""},{"name":"Jérôme Niel","avatar":""},{"name":"Anne Serra","avatar":""},{"name":"Quentin D''Hainaut","avatar":""},{"name":"Thibaut Évrard","avatar":""},{"name":"Nicolas Duvauchelle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["แรงทะลุกระสุน 2","Lost Bullet 2","Lost Bullet 2: Back for More","Verirrte Kugel 2","Bala perdida 2","Balle perdue 2"]', 1784690324264);
