INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-cong-sieu-dang-maverick', 'Phi Công Siêu Đẳng: Maverick', 'Top Gun: Maverick', 'https://phimimg.com/upload/vod/20250511-1/b29baf32c3383d84495fb0074f4e59c1.jpg', 'https://phimimg.com/upload/vod/20250511-1/c18fd23da5c2781cb69260baabd51d11.jpg', '<p>Sau hơn 30 năm phụng sự với tư cách phi công hàng đầu của hải quân, Pete “Maverick” Mitchell giờ đang làm việc mình yêu thích: bứt phá giới hạn trong vai trò một phi công thử nghiệm dũng cảm. Tuy nhiên, Maverick phải đối đầu với bóng ma quá khứ khi anh trở lại TOPGUN để đào tạo một nhóm học viên ưu tú và đối mặt với Trung úy Bradshaw, con trai của phi công yểm trợ cũ &quot;Goose&quot;. Sự cạnh tranh gay gắt bùng nổ khi các phi công chuẩn bị cho một nhiệm vụ chuyên biệt đòi hỏi sự hy sinh tột bậc từ những người được chọn bay.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Monica Barbaro","avatar":""},{"name":"Lewis Pullman","avatar":""},{"name":"Jay Ellis","avatar":""},{"name":"Danny Ramirez","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"Bashir Salahuddin","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Charles Parnell","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Jack Schumacher","avatar":""},{"name":"Manny Jacinto","avatar":""},{"name":"Kara Wang","avatar":""},{"name":"Greg Tarzan Davis","avatar":""},{"name":"Jake Picking","avatar":""},{"name":"Raymond Lee","avatar":""},{"name":"Val K","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Лучший стрелок 2","Top Gun 2","Кращий стрілець 2","Top Gun 2 - Maverick","Phi Công Siêu Đẳng Maverick","Кращий стрілець: Меверік","توب قن: مافريك","Top Gun: Sayohatchi","Топ ган: Маверик","Λογότυπο της ταινίας","تاپ گان: ماوریک","توب غان: مافريك","Top Gun - Maverick","Топ Ган 2","壮志凌云2：独行侠","टॉप गन: मैवरिक","탑건: 매버릭","トップガン マーヴェリック","טופ גאן 2: מאווריק","טופ גאן: מאווריק","Top Gun: Maverick","تاپ گان ۲: ماوریک","تاپ گان ۲","탑 건: 매버릭","TopGun Maverick","Թոք Գան։ Մավերիք","Топ Ган: Мэверик","壮志凌云：独行侠"]', 1784690324264);
