INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-lang-hai-phan-2', 'Huyền Thoại Làng Hài (Phần 2)', 'Hacks (Season 2)', 'https://phimimg.com/upload/vod/20250111-1/6cf7aa0e0d6c57f8f17c93e247c2a026.jpg', 'https://phimimg.com/upload/vod/20250111-1/b730c9d538b1248036a0bd27971cbb92.jpg', '<p>Sau thảm họa ở mùa trước, Deborah quyết định đổi gió bằng cách lên đường lưu diễn cùng với Ava. Nhưng hậu quả từ email tai hại Ava gửi đi khiến mối quan hệ của họ trở nên phúc tạp.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jean Smart","avatar":""},{"name":"Hannah Einbinder","avatar":""},{"name":"Carl Clemons-Hopkins","avatar":""},{"name":"Megan Stalter","avatar":""},{"name":"Paul W. Downs","avatar":""},{"name":"Mark Indelicato","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["老哏新侃","天后与草莓","Полезные советы","Hacks"]', 1784690324264);
