INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-lang-nghe-loi-thi-tham', 'Người Lắng Nghe: Lời Thì Thầm', 'Listeners: The Whispering', 'https://phimimg.com/upload/vod/20231012-1/5f4ee10801b1f4b4c55bc5a5ea3cc4fb.jpg', 'https://phimimg.com/upload/vod/20231012-1/31089d7d8863bef9a04cbf11c6f123b2.jpg', '<p>Chuyện phim kể về việc bác sỹ tâm lý Tường Minh (Quang Sự) trị liệu cho nhà văn trẻ An Nhiên (Oanh Kiều) bị trầm cảm, dẫn đến rối loạn lo âu. Nhiên cho rằng bản thân đang bị một cô gái ám ảnh. Điều kỳ lạ là, cô gái mà Nhiên hay nhắc đến lại là nhân vật chính trong quyển truyện “Lời thì thầm”, một sáng tác đầu tay của Nhiên. Bằng các biện pháp chuyên môn, Tường Minh cố gắng giúp An Nhiên đối diện lại với những câu chuyện trong quá khứ. Anh hy vọng điều này sẽ giúp cô giải tỏa được những uẩn ức, từ đó vượt qua những ám ảnh và bắt đầu một cuộc sống mới. Tuy nhiên, trong quá trình nhập tâm để điều trị cho An Nhiên, Tường Minh cũng dần dần bị cuốn vào chính câu chuyện và những ám ảnh của Nhiên. Từ đây, Tường Minh thường xuyên gặp ác mộng, thấy ảo giác. Và đỉnh điểm là Minh cũng thấy bản thân cũng đang dần bị ám ảnh bởi một cô gái lạ.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Quang Sự","avatar":""},{"name":"Oanh Kiều","avatar":""},{"name":"Phạm Quỳnh Anh","avatar":""},{"name":"Quốc Cường","avatar":""},{"name":"Lý Hồng Ân","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324264);
