INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-bat-tu', 'Cuộc Chiến Bất Tử', 'How To Save The Immortal', 'https://phimimg.com/upload/vod/20250508-1/e783af7f762f95d0437eb11e46d04c56.jpg', 'https://phimimg.com/upload/vod/20250508-1/86e1053e86f5d653abfa3adeb2384d02.jpg', '<p>Phim xoay quanh cuộc đời của nhân vật Drybone sở hữu sức mạnh bất tử, dù luôn trẻ trung và bảnh bao nhưng vẫn không thể tìm được cô dâu cho mình trong suốt 300 năm. Mặc cho anh ta đe dọa, bắt cóc hay thậm chí biến nhiều công chúa thành ếch thì kế hoạch tán tỉnh của Hoàng Tử Bóng Đêm cùng không thuộn buồm xuôi gió hơn. Trong khi đó thì tất cả những gì mà nữ chiến binh xinh đẹp và dũng cảm Barbara làm là chống lại những kẻ sắp theo đuổi cô trên đấu trường hay những kẻ cầu hôn chỉ vì thèm muốn của hồi môn của Barbara. Sự đối lập này vô tình đưa Drybone và Barbara vào cuộc gặp gỡ định mệnh và cùng chiến đấu với phe phản diện mới là Vua Lentil – kẻ nắm giữ cây kim có thể tước đoạt mạng sống của Hoàng Tử Bóng Đêm Drybone. Dù vậy, hắn không thể ngờ vẫn còn điều kỳ diệu ẩn chứa bên trong trái tim của Drybone giúp anh ấy sống sót...</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Lồng Tiếng', 'FHD', 'Nga', 0, '[{"name":"Victor Dobronravov","avatar":""},{"name":"Elizaveta Boyarskaya","avatar":""},{"name":"Roman Artemyev","avatar":""},{"name":"Irina Savina","avatar":""},{"name":"Ekaterina Tarasova","avatar":""},{"name":"Elena Shulman","avatar":""},{"name":"Anton Eldarov","avatar":""},{"name":"Nikita Kologrivyy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Koshchey. Pokhititel nevest","Koschey. Pokhititel nevest","Koschey. The Bride Kidnapper","몬스터 신부 : 101번째 프로포즈","몬스터 신부: 101번째 프로포즈","몬스터 신부; 101번째 프로포즈","Кощей. Похититель невест"]', 1784690324264);
