INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-rinh-mo', 'Kẻ Rình Mò', 'Watcher', 'kẻ rình mò watcher maika monroe karl glusman burn gorman mãdãlina anea daniel nuta gabriela butuc cristina deleanu ștefan iancu florian ghimpu flaviu crisan ioana abur alexandru ion aida economu bogdan farcaș tudor petruț lucian ionescu radu bunescu ciprian el extraño наблюдающий спостерігач observada 왓쳐 beobachtet 監視殺機 biri gözetliyor הצופה watcher', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hiem-gia-hang-dong-abyss-phan-2', 'Thám Hiểm Gia Hang Động Abyss (Phần 2)', 'Made In Abyss (Season 2)', 'https://phimimg.com/upload/vod/20250505-1/f95cbdcbfd6f61173c901c972b8d501f.jpg', 'https://phimimg.com/upload/vod/20250505-1/2e1c7657d66c1a40d83c4ce1e7b75157.jpg', '<p>Hệ thống hang động khổng lồ, nơi duy nhất trên thế giới còn chưa được khám phá hay còn được biết đến với cái tên, Abyss. Không ai biết được mê cung bí ẩn này sâu xuống bao nhiêu, có những quái vật cũng như di tích nào. Rất nhiều nhà thám hiểm đã dấn thân vào công cuộc thám hiểm nơi đâu. Qua thờii gian, những ai có đủ can đảm để bước xuống mê cung này thường được gọi bằng cái tên Thám hiểm gia hang động. Ở Oosu, thị trấn bên rìa Abyss, có một cô bé mồ côi tên là Rico, nuôi ước trở thành một thám hiểm gia hang động như mẹ cô mà giải được bí ẩn cả Abyss. Một ngày nọ khi đang khám phá những bí ẩn bên dưới Abyss, cô đã gặp được một cậu bé robot...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miyu Tomita","avatar":""},{"name":"Mariya Ise","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Made in Abyss","Made in Abyss: Die Goldene Stadt der sengenden Sonne","Meidoinabisu","Meidoinabisu: Retsujitsu no ôgonkyô","メイドインアビス 烈日の黄金郷","Made in Abyss Retsujitsu No Ougonkyou","来自深渊：烈日的黄金乡","メイドインアビス","Рождённый в Бездне","