INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-re-hai-mat', 'Chàng Rể Hai Mặt', 'My Bossy Wife', 'https://phimimg.com/upload/vod/20240603-1/1d9f963f20b29371e5b7be0149e90120.jpg', 'https://phimimg.com/upload/vod/20240603-1/4c0a1f7cfc27ba0b520e138d7d3c2fbe.jpg', '<p>Lộ Tiểu Bạch thích sống tự do, lang thang khắp nơi. Nhưng cuộc đời chàng lại va phải nữ bổ đầu &quot;khét tiếng&quot; Thẩm Quân Dạ. Một sự cố bất ngờ xảy ra, Lộ Tiểu Bạch phải ký khế ước đến ở rể tại Thẩm phủ. Từ chỗ đối nghịch, cả hai dần hiểu nhau, cùng phối hợp vô cùng ăn ý trong quá trình phá giải nhiều vụ án khác nhau.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Hạo Đông","avatar":""},{"name":"Thiệu Vân","avatar":""},{"name":"Tào Quân Hào","avatar":""},{"name":"Đồng Gia Hào","avatar":""},{"name":"Du Thanh Lôi","avatar":""},{"name":"Đào Gia Kim","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324264);
