INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-minh-thich-tiec-tung-ban-hoat-hinh', 'Khổng Minh Thích Tiệc Tùng (Bản Hoạt Hình)', 'Ya Boy Kongming!', 'https://phimimg.com/upload/vod/20250502-1/34c2e1fa3ab0629d74885e635589b18e.jpg', 'https://phimimg.com/upload/vod/20250502-1/abc658703d4a672741bb7d1ac506437e.jpg', '<p>Khổng Minh Gia Cát Lượng, thừa tướng nước Thục, sau khi qua đời cứ ngỡ sẽ xuống âm tào địa phủ, ai dè xuyên không về khu Shibuya xập xình nhạc hội thời hiện đại. Ban đầu Khổng Minh còn ngáo ngơ không biết, rồi được một cô ca sĩ nghiệp dư cho ở nhà qua đêm và chỉ dạy những kiến thức hiện đại, Khổng Minh mới biết mình xuyên không và chấp nhận cuộc sống mới mẻ này. Để trả ơn, Khổng Minh còn tuyên bố sẽ giúp cô gái kia trở thành ca sĩ chuyên nghiệp.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaede Hondo","avatar":""},{"name":"Ryotaro Okiayu","avatar":""},{"name":"Jun Fukushima","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Hibiku Yamamura","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["派对浪客诸葛孔明","派對咖孔明","派对咖孔明","Paripi Kōmei","Paripi Koumei","パリピこうめい","Paripi Koumei (Ya Boy Kongming!)","Imprezowicz Kongming","Party People Koumei","Khổng Minh Thích Tiệc Tùng","パリピ孔明"]', 1784690324264);
