INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-minh-thich-tiec-tung-ban-hoat-hinh', 'Khổng Minh Thích Tiệc Tùng (Bản Hoạt Hình)', 'Ya Boy Kongming!', 'khổng minh thích tiệc tùng (bản hoạt hình) ya boy kongming! kaede hondo ryotaro okiayu jun fukushima shoya chiba hibiku yamamura 派对浪客诸葛孔明 派對咖孔明 派对咖孔明 paripi kōmei paripi koumei パリピこうめい paripi koumei (ya boy kongming!) imprezowicz kongming party people koumei khổng minh thích tiệc tùng パリピ孔明', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nuong-tu-nha-do-te', 'Tiểu Nương Tử Nhà Đồ Tể', 'The Lady In Butcher''s House', 'https://phimimg.com/upload/vod/20240220-1/31b804fa7e4b01fa6eabfd32ce171bdb.jpg', 'https://phimimg.com/upload/vod/20240220-1/c9b294364065ba970819f317aa156846.jpg', '<p>Câu chuyện xoay quanh mối tình &quot;cưới trước yêu sau&quot; giữa Hồ Kiều, một cô gái mạnh mẽ xuất thân từ gia đình làm nghề bán thịt, và Hứa Thanh Gia, một thư sinh nghèo nhưng học giỏi. Hai người được gia đình hứa hôn từ nhỏ. Sau khi Hứa Thanh Gia thi đỗ Bảng Nhãn, anh thực hiện lời hứa kết hôn với Hồ Kiều. Ban đầu, cuộc sống hôn nhân của họ gặp nhiều trắc trở do sự khác biệt về tính cách và hoàn cảnh. Tuy nhiên, qua thời gian sống chung và cùng nhau vượt qua khó khăn, họ dần hiểu và yêu thương nhau. Hứa Thanh Gia trở thành quan huyện, luôn nỗ lực cải cách để phục vụ nhân dân, trong khi Hồ Kiều tích cực hỗ trợ chồng trong công việc và các hoạt động xã hội. Tình yêu của họ ngày càng sâu đậm, minh chứng cho sự đồng lòng và thấu hiểu trong hôn nhân.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Mộng Thực","avatar":""},{"name":"Trương Hàm Vận","avatar":""},{"name":"Trần Dịch Long","avatar":""},{"name":"Vương Nhược Lân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324264);
