INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieu-nuong-tu-nha-do-te', 'Tiểu Nương Tử Nhà Đồ Tể', 'The Lady In Butcher''s House', 'tiểu nương tử nhà đồ tể the lady in butcher''s house đồng mộng thực trương hàm vận trần dịch long vương nhược lân ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-nho-cua-hai-nguoi', 'Khu Rừng Nhỏ Của Hai Người', 'A Romance Of The Little Forest', 'https://phimimg.com/upload/vod/20240603-1/4c1fa336126b5ac07dba76fa9a210d2c.jpg', 'https://phimimg.com/upload/vod/20240603-1/fd4d228a0813b45aec16ae9d72d2bb8f.jpg', '<p>Trang Vũ, một giáo sư thực vật học chuyên tâm nghiên cứu khoa học và thờ ơ với danh vọng, vật chất và giao tiếp xã hội. Điều này cũng vô tình làm tổn thương Ngu Mỹ Nhân, một cô gái đã phải lòng anh nhiều năm trước. Nhiều năm sau, Ngu Mỹ Nhân lấy được bằng tiến sĩ điểu học với kết quả xuất sắc, vì không muốn chịu áp lực nghiên cứu khoa học nên đã thay đổi nghề nghiệp và trở thành một blogger thời trang, không ngờ cô và Trang Vũ lại một lần nữa gặp nhau. Trang Vũ đến thôn Thanh Thuỷ để tiến hành nghiên cứu thực địa và tình cờ sống tại nhà trọ của Ngu Mỹ Nhân. Với sự giúp đỡ của cô, quá trình nghiên cứu khoa học của anh tiến triển thuận lợi, đồng thời anh cũng cảm nhận được tình yêu thương, sự ấm áp mà thực vật không thể mang lại từ cô. Ngu Mỹ Nhân cũng được truyền cảm hứng bởi sự cống hiến cho khoa học của anh, nên đã quyết tâm ứng dụng những kiến thức đã học trước đó để cống hiến cho quê hương. Một người không ngừng tiến lên phía trước để vượt qua khó khăn, người còn lại tích cực ủng hộ việc bảo vệ môi trường, hai người trẻ tuy có xuất phát điểm khác nhau nhưng đều có chung một lý tưởng là xây dựng đất nước, quê hương và cùng nắm tay nhau trên hành trình dài sắp tới.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngu Thư Hân","avatar":""},{"name":"Trương Bân Bân","avatar":""},{"name":"Lệ Gia Kỳ","avatar":""},{"name":"Đinh Quán Sâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324264);
