INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-bach-ho-truy-phu', 'Tiểu Bạch Hồ Truy Phu', 'Fox Spirit God Lord''s Love', 'https://phimimg.com/upload/vod/20250429-1/13a37e28ff04b1e4800c7286fdfa40fd.jpg', 'https://phimimg.com/upload/vod/20250429-1/59deed81a07638a9dccd378a2188b95f.jpg', '<p>Tức giận vì cha cưới vợ mới, Công chúa Tuyết Lăng Tử của Ma giới bỏ nhà ra đi và lạc vào Thần giới. Tại đây, vì pháp lực bị phong ấn nên nàng bị mắc kẹt trong hình dạng hồ ly và bị Thần quân Quân Mộc Dương đưa về. Giữa hai người dần dần nảy sinh tình cảm, nhưng mối tình này lại gặp phải muôn vàn trắc trở không chỉ vì thân phận khác biệt, mà còn vì trong người Tuyết Lăng Tử ẩn chứa uy lực có thể hủy thiên diệt địa, khiến nàng trở thành đối tượng săn đuổi của nhiều thế lực xấu xa.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đan Nễ","avatar":""},{"name":"Tôn Lịch Hàm","avatar":""},{"name":"Hạ Hải Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shen Jun Jia De Xiao Bai Hu","神君家的小白狐"]', 1784690324264);
