INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-dao-kinh-hoang', 'Xà Đảo Kinh Hoàng', 'Snake Lady', 'https://phimimg.com/upload/vod/20231206-1/dbca5bf8402c0021ece1991f0a8bbf16.jpg', 'https://phimimg.com/upload/vod/20231206-1/035e8aed73cc7681dd096d84d24b9358.jpg', '<p>Lý Đồng đưa đội thu thập tin tức tài liệu của công ty đến Đảo Rắn để lấy tin đồng thời cũng để tìm ra sự thật về sự mất tích của cha mình. Sau khi đổ bộ lên đảo một vài người đã phát hiện ra sự kỳ lạ của thổ dân trên đảo, sự phản kháng của họ đối với người ngoài khiến mọi người cảm thấy rất kỳ lạ. Nhà trọ duy nhất mở cửa trên đảo do hai chị em Lan Nhiễm và Lan Sa làm chủ. Tính cách lập dị của chị gái Lan Nhiễm, sự cẩn thận của Lan Sa và sự hung dữ của người hầu Ba Đồ đã đưa nhiều người vào sự nguy hiểm. Một số người cuối cùng đã biết được sự thật đằng sau Lan Nhiễm và những người khác, nhưng họ đã bị ba con rắn khổng lồ bao vây trên đảo. Đúng lúc này, một người bí ẩn đã giải cứuLý Đồng và đội của họ...</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"龚小钧","avatar":""},{"name":"Wang Yi Han","avatar":""},{"name":"Yubolin","avatar":""},{"name":"Yubolin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324264);
