INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-cuoc-quai-2', 'Đại Cước Quái 2', 'Bigfoot', 'https://phimimg.com/upload/vod/20230930-1/111eea610ee47c385608aa1d43bad61b.jpg', 'https://phimimg.com/upload/vod/20230930-1/f464b12c060bc4ab5e54cd0c71a1e815.jpg', '<p>Ông nội của Anna là một nhà cổ sinh vật học, nhưng kể từ một nhiệm
 vụ nghiên cứu mười năm trước, ông đã mất tích. Giờ đây, Anna một nhân 
viên của Viện Sinh học, sau một lần tình cờ phát hiện ra manh mối do ông
 nội để lại, cô và Tiến sĩ Tạ ở Viện đã tìm thấy chủ đại lý xe hơi Lý &nbsp;
Vũ Hàng và trợ lý của ông ta là Đại Tuyết. Vài người trên chiếc SUV cũ 
kỹ này bắt tay vào cuộc hành trình thám hiểm khu rừng bí ẩn. Họ đi bộ 
xuyên núi vượt rừng trèo dòi lội suối. Họ băng qua những ngọn núi để đến
 vùng đất không người, chạm trán với những loài động thực vật đã tuyệt 
chủng từ xa xưa, và sau nhiều nguy hiểm, cuối cùng họ cũng tìm thấy dấu 
chân khổng lồ, và một mối nguy hiểm lớn hơn đang đến...</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Mengxuan","avatar":""},{"name":"Jason Sze","avatar":""},{"name":"He Gang","avatar":""},{"name":"Pan Yuanjia","avatar":""},{"name":"Hou Chang-Rong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324264);
