INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('makkali-yeu-dau', 'Makkali Yêu Dấu', 'Makkali The Love Tree', 'https://phimimg.com/upload/vod/20241209-1/e5915aafc42412824c0386f908a4f992.jpg', 'https://phimimg.com/upload/vod/20241209-1/2e713c370cf91862f8d1d340722bb17a.jpg', '<p>Bộ phim kể về câu chuyện của một giáo sư trẻ đau lòng vì tình yêu tan vỡ, buộc anh phải tìm đến rừng sâu để tìm sự an ủi từ thiên nhiên. Trong một đêm mưa lớn, khi cầu vồng xuất hiện giữa mặt trăng, một cô gái bí ẩn xuất hiện từ một cây trong rừng Himmapan, không phải là con người, mà là Makkaliphon. Cô ấy đã vượt qua lỗ hổng giữa hai thế giới để đến với anh. Từ đó, cuộc sống của giáo sư trẻ đã thay đổi mãi mãi. Liệu tình yêu giữa con người và Makkali của rừng Himmapan có thể đạt được hạnh phúc mãi mãi hay không?</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sirilak Kwong","avatar":""},{"name":"Weerakaniz Kanwatthanakul","avatar":""},{"name":"Cake Nattavat Kaewbuasai","avatar":""},{"name":"Pongsapat Kankam","avatar":""},{"name":"Penpetch Benyakul","avatar":""},{"name":"Penpak Sirikul","avatar":""},{"name":"Sarocha Watittapan","avatar":""},{"name":"Jirawat Wachirasarunpat","avatar":""},{"name":"Nattanon Tongsaeng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["มักกะลีที่รัก"]', 1784690324264);
