INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-co-lon', 'Ván Cờ Lớn', 'Game Of Wisdom', 'https://phimimg.com/upload/vod/20250425-1/c251205ff66f85298f555e967134165a.jpg', 'https://phimimg.com/upload/vod/20250425-1/83a278dc2f61662448416d19e8a338dd.jpg', '<p>Bộ phim xoay quanh câu chuyện giữa ba người bạn thân: Tôn Hoạ Bình, Dương Liễu và Lưu Tất Định. Sau khi tốt nghiệp đại học, Dương Liễu và Lưu Tất Định đứng ra thành lập công ty riêng, trong khi đó Tôn Hoạ Bình giữ chức vụ Giám đốc kinh doanh Tập đoàn Thiết bị miền Bắc. Trước đó, tập đoàn này đang ở trên bờ vực phá sản, Tôn Hoạ Bình được điều khẩn cấp từ Đông Nam Á để trở thành người lãnh đạo mới nhằm vực dậy tập đoàn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Hạo","avatar":""},{"name":"Vạn Thiến","avatar":""},{"name":"Điền Vũ","avatar":""},{"name":"Trương Manh","avatar":""},{"name":"Đàm Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Game of Wisdom","大博弈"]', 1784690324264);
