INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tar', 'TÁR', 'TÁR', 'https://phimimg.com/upload/vod/20250424-1/19501e1279870496603696088f6e8a82.jpg', 'https://phimimg.com/upload/vod/20250424-1/08d45c1be918643e30c9435ae203cbd3.jpg', '<p>TÁR là một bộ phim chính kịch tâm lý do Todd Field đạo diễn, với sự tham gia của Cate Blanchett trong vai Lydia Tár – một nhạc trưởng thiên tài và là người phụ nữ đầu tiên dẫn dắt Dàn nhạc Giao hưởng Berlin. Phim khắc họa sâu sắc quá trình Tár đối mặt với quyền lực, danh tiếng và những hệ lụy từ các mối quan hệ cá nhân, khi quá khứ và hiện tại dần đan xen, đẩy cô vào vòng xoáy khủng hoảng.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cate Blanchett","avatar":""},{"name":"Nina Hoss","avatar":""},{"name":"Noémie Merlant","avatar":""},{"name":"Sophie Kauer","avatar":""},{"name":"Julian Glover","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Sylvia Flote","avatar":""},{"name":"Allan Corduner","avatar":""},{"name":"Mila Bogojevic","avatar":""},{"name":"Adam Gopnik","avatar":""},{"name":"Marc-Martin Straub","avatar":""},{"name":"Egon Brandstetter","avatar":""},{"name":"Ylva Pollak","avatar":""},{"name":"Paula Först","avatar":""},{"name":"Sydney Lemmon","avatar":""},{"name":"Nicolas Hopchet","avatar":""},{"name":"Zethphan Smith","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tár","ทาร์","TAR","塔爾","Тар","Tar","塔尔","TÁR"]', 1784690324264);
