INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chat-doc-cua-su-noi-tieng', 'Chất Độc Của Sự Nổi Tiếng', 'Sick of Myself', 'https://phimimg.com/upload/vod/20250424-1/e41524381d20b2601c1587bc69ee178b.jpg', 'https://phimimg.com/upload/vod/20250424-1/202632b406699cc4e1dc9d871068b268.jpg', '<p>Không chấp nhận bản thân tầm thường, Signe biến mình thành nạn nhân để nổi tiếng và trở thành hình tượng vượt qua nghịch cảnh. Tuy nhiên, cái giá của sự nổi tiếng giả dối nào mà chẳng đắt đỏ.</p>', 'Full', 1, 'single', 'completed', 36, 2022, 'Vietsub', 'FHD', 'Na Uy', 0, '[{"name":"Kristine Kujath Thorp","avatar":""},{"name":"Eirik Sæther","avatar":""},{"name":"Fanny Vaager","avatar":""},{"name":"Fredrik Stenberg Ditlev-Simonsen","avatar":""},{"name":"Sarah Francesca Brænne","avatar":""},{"name":"Steinar Klouman Hallert","avatar":""},{"name":"Ingrid Vollan","avatar":""},{"name":"Andrea Bræin Hovig","avatar":""},{"name":"Henrik Mestad","avatar":""},{"name":"Anders Danielsen Lie","avatar":""},{"name":"Frida Natland","avatar":""},{"name":"Guri Hagen Glans","avatar":""},{"name":"Matilda Höög","avatar":""},{"name":"Se","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["İlgi Manyağı","ซิค ออฟ มายเซลฟ์","#시그네","我恨我自己","Sick of Myself","Sick of Myself: Chất độc của sự nổi tiếng","Syk pike"]', 1784690324264);
