INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chat-doc-cua-su-noi-tieng', 'Chất Độc Của Sự Nổi Tiếng', 'Sick of Myself', 'chất độc của sự nổi tiếng sick of myself kristine kujath thorp eirik sæther fanny vaager fredrik stenberg ditlev-simonsen sarah francesca brænne steinar klouman hallert ingrid vollan andrea bræin hovig henrik mestad anders danielsen lie frida natland guri hagen glans matilda höög se i̇lgi manyağı ซิค ออฟ มายเซลฟ์ #시그네 我恨我自己 sick of myself sick of myself: chất độc của sự nổi tiếng syk pike', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mozart-ngoai-vu-tru', 'Mozart Ngoài Vũ Trụ', 'Mozart From Space', 'https://phimimg.com/upload/vod/20250424-1/c8ad6ab8d8929773c3eecb7ab6ca63a0.jpg', 'https://phimimg.com/upload/vod/20250424-1/d071048be37b4a9149fa90bc0fddf49c.jpg', '<p>Một người ngoài hành tinh tên &quot;Mozart&quot; xuất hiện trong cuộc sống của hai cha con vốn bất hòa. Nhậm Đại Vọng mong muốn con trai Nhậm Tiểu Thiên, một người đam mê thiên văn học, trở thành nghệ sĩ piano, và sự khác biệt của họ đã trở thành nguồn cơn cho những cuộc cãi vã liên miên. Một ngày nọ, người ngoài hành tinh bí ẩn Mozart xuất hiện trước mặt họ. Mozart giúp Nhậm Tiểu Thiên trong một &quot;cuộc chiến trí tuệ và lòng dũng cảm&quot; chống lại cha mình. Điều Nhậm Tiểu Thiên không bao giờ ngờ tới là Mozart đến Trái đất vì một nhiệm vụ.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Bột","avatar":""},{"name":"Vinh Tử Sam","avatar":""},{"name":"Diêu Thần","avatar":""},{"name":"Hoàng Dương Điền Điềm","avatar":""},{"name":"Mai Đình","avatar":""},{"name":"Hoàng Giác","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Mozart in Outer Space","Панда из космоса","外太空的莫札特","Mozart from Space","外太空的莫扎特"]', 1784690324264);
