INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-lai-huong', 'Dạ Lai Hương', 'My Sassy Psychic', 'https://phimimg.com/upload/vod/20250423-1/4076a6c15885c7c798c7e1527739b398.jpg', 'https://phimimg.com/upload/vod/20250423-1/6a23683f83536dd06c565c6c22fc496e.jpg', '<p>Saran và cộng sự của anh đang thực hiện một nhiệm vụ bí mật để gặp một bà đồng tên là Sonklin, trùng tên với một vị nữ thần. Sonklin buộc phải giúp Saran với tư cách nhân chứng trong cuộc điều tra, đồng thời hợp tác với bác sĩ Pran để truy tìm một bùa hộ mệnh có khả năng giải thoát linh hồn, đưa họ tiếp tục chu kỳ nghiệp báo. Trong lúc đó, họ cũng phải làm sáng tỏ bí ẩn về sự mất tích của Sarum.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Prama Imanothai","avatar":""},{"name":"Ranida Techasit","avatar":""},{"name":"Chattarika Sittiprom","avatar":""},{"name":"Sarut Vichitrananda","avatar":""},{"name":"Vivid Bavornkiratikajorn","avatar":""},{"name":"Kummun Klomkaew","avatar":""},{"name":"Supachai Suwanon","avatar":""},{"name":"Gosin Rachakrom","avatar":""},{"name":"Thongthong Mokjok","avatar":""},{"name":"Chokchai Charoensuk","avatar":""},{"name":"Passakorn Kruasopon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Songlin , Sonklin","ซ่อนกลิ่น"]', 1784690324264);
