INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-thuong-truong-ke-truyen-thua', 'Bẫy Thương Trường (Kẻ Truyền Thừa)', 'The Giver', 'https://phimimg.com/upload/vod/20240520-1/a818d6ca7460644df12d3be79670c5fb.jpg', 'https://phimimg.com/upload/vod/20240520-1/4ad0f3643144ed13259ed55e07d986cb.jpg', '<p>Sau cái chết bất ngờ của bố mẹ, cuộc sống của hai chị em Tailah và Fahrung bị đảo lộn. Tailah dính líu đến Hiran, con trai của một chủ doanh nghiệp giàu có và quyền lực. Cha con Hiran dùng quyền lực tống Tailah vào tù. Trong tù, Tailah gặp một tù nhân người Hoa họ Yang, ông dạy cho anh nhiều bí quyết kinh doanh. Khi ra tù, Tailah bắt đầu bước vào một cuộc chiến mới, chống lại cái ác và sự bất công.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Tor Thanapob","avatar":""},{"name":"Plengkwan Nattaya","avatar":""},{"name":"Ben Raviyanun","avatar":""},{"name":"Bright Norraphat Vilaiphan","avatar":""},{"name":"Dom Haetrakul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324264);
