INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-tuoi-van-con-zin-se-bien-thanh-phu-thuy', '30 Tuổi Vẫn Còn Zin Sẽ Biến Thành Phù Thủy', 'Cherry Magic The Movie', 'https://phimimg.com/upload/vod/20250419-1/2226db975248eec96582805189e4b5b1.jpg', 'https://phimimg.com/upload/vod/20250419-1/776f3f09aad9ecba8256113ba66f2dc8.jpg', '<p>Adachi là một nhân viên văn phòng, bước sang tuổi 30 và vẫn còn &quot;zin&quot;. Vào sinh nhật thứ 30 của mình, anh chàng được ban tặng phép thuật kỳ lạ. Adachi có thể đọc được suy nghĩ của những người anh ta chạm vào. Kurosawa là người yêu của Adachi tại nơi làm việc, nổi tiếng và thành đạt. Họ yêu nhau bí mật tại chốn công sở. Một ngày nọ, Adachi nhận được một cơ hội việc làm mới. Adachi sẽ được làm việc mình thích nhưng địa điểm mới lại ở Nagasaki, cách Kurosawa tận 1.200 km. Trải qua những khó khăn và thử thách khiyêu xa khiến họ phải suy nghĩ lại về mối quan hệ và tương lai của mình. Mối quan hệ của họ sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Eiji Akaso","avatar":""},{"name":"Keita Machida","avatar":""},{"name":"Kodai Asaka","avatar":""},{"name":"Yutaro","avatar":""},{"name":"Takuya Kusakawa","avatar":""},{"name":"Ryo Sato","avatar":""},{"name":"Suzunosuke Tanaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cheri maho: Za mūbī – Sanjūsai made dōtei da to mahōtsukai ni narerurashii","Cheri maho: THE MOVIE – 30-sai made dōtei da to mahōtsukai ni narerurashii","Cheri maho: THE MOVIE – Sanjūsai made dōtei da to mahōtsukai ni narerurashii","Cherry maho: THE MOVIE – 30-sai made dōtei da to mahōtsukai ni narerurashii","Cherry maho: THE MOVIE – Sanjūsai made dōtei da to mahōtsukai ni narerurashii","チェリまほ THE MOVIE 30歳まで童貞だと魔法使いになれるらしい","チェリまほ THE MOVIE","ถ้า 30 ยังซิง! จะมีพลังวิเศษ","“Cherry Magic! Thirty Years Of Virginity Can Make You A Wizard ?!” The Movie","如果30歲還是處男，似乎就能成為魔法師","電影版 如果30歲還是處男，似乎就能成為魔法師","チェリまほ THE MOVIE 〜30歳まで童貞だと魔法使いになれるらしい〜"]', 1784690324264);
