INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('30-tuoi-van-con-zin-se-bien-thanh-phu-thuy', '30 Tuổi Vẫn Còn Zin Sẽ Biến Thành Phù Thủy', 'Cherry Magic The Movie', '30 tuổi vẫn còn zin sẽ biến thành phù thủy cherry magic the movie eiji akaso keita machida kodai asaka yutaro takuya kusakawa ryo sato suzunosuke tanaka cheri maho: za mūbī – sanjūsai made dōtei da to mahōtsukai ni narerurashii cheri maho: the movie – 30-sai made dōtei da to mahōtsukai ni narerurashii cheri maho: the movie – sanjūsai made dōtei da to mahōtsukai ni narerurashii cherry maho: the movie – 30-sai made dōtei da to mahōtsukai ni narerurashii cherry maho: the movie – sanjūsai made dōtei da to mahōtsukai ni narerurashii チェリまほ the movie 30歳まで童貞だと魔法使いになれるらしい チェリまほ the movie ถ้า 30 ยังซิง! จะมีพลังวิเศษ “cherry magic! thirty years of virginity can make you a wizard ?!” the movie 如果30歲還是處男，似乎就能成為魔法師 電影版 如果30歲還是處男，似乎就能成為魔法師 チェリまほ the movie 〜30歳まで童貞だと魔法使いになれるらしい〜', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-d-khong-de-choc', 'Tiểu Thư D Không Dễ Chọc', 'Great MissD', 'https://phimimg.com/upload/vod/20241008-1/dbcb2aff492551e7fe84efd9ef4d26fe.jpg', 'https://phimimg.com/upload/vod/20241008-1/648591215d9571ae2657c7a725629c63.jpg', '<p>Thượng Hải đầu những năm 1930, nhiều thế lực khác nhau trỗi dậy, xã hội hỗn loạn. Đinh Dịch Thanh con gái của một doanh nhân giàu có người Ninh Ba, một mình đến Thượng Hải để tìm người anh trai mất tích, nhưng không ngờ lại dùng tài kinh doanh của mình để dấn thân vào con đường cách mạng. Trên con đường này, cô đã gặp được hy vọng, và người đàn ông trẻ đầy triển vọng Lâm Mặc Sâm sẵn sàng chiến đấu cùng cô. Trên con đường này, cô đã chứng kiến sự tuyệt vọng, những nhà lãnh đạo cách mạng của cô là Đổng Hồng Ngọc và Đỗ Anh lần lượt gục ngã. Trên con đường này, cô ấy cuối cùng đã tiếp nhận chiếc gậy truyền tay của hội tiểu thư D, thề sẽ mang lại sự thái bình cho thế hệ trẻ ...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tịnh Nghi","avatar":""},{"name":"Ngưu Tuấn Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Great MissD","了不起的D小姐"]', 1784690324264);
