INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ban-mot-tuan-2022', 'Người Bạn Một Tuần', 'One Week Friends', 'https://phimimg.com/upload/vod/20250410-1/2fc1d159610ab22f8f8728c268699b72.jpg', 'https://phimimg.com/upload/vod/20250410-1/32b4231b590196c7b6bcee5f6fe194bc.jpg', '<p>Lớp học ôn thi lại đại học trường trung học Thắng Hoa vừa có học sinh mới chuyển đến tên Lâm Tương Chi. Cô thông minh, dịu dàng ít nói, nhưng lại luôn cô đơn một mình, không kết bạn với ai. Nhưng như thế lại thu hút sự chú ý của tên học sinh yếu kém Từ Hựu Thụ, Tống Hiểu Nam tinh ranh và chàng học sinh giỏi lạnh lùng Tưởng Ngô. Trong quá trình cố gắng kết bạn với Tương Chi, Hựu Thụ phát hiện ra bí mật của cô. Hóa ra cô mắc một căn bệnh đặc biệt, đó là kí ức về bạn bè của cô chỉ tồn tại trong 7 ngày. Vì giúp đỡ cô nàng cô độc này, Từ Hựu Thụ càng tích cực hơn. Bốn người họp lại thành tiểu đội &quot;sinh tồn ngày tận thế&quot;, không ngừng tạo ra những kỉ niệm bất ngờ chỉ thuộc về riêng họ. Nhưng chẳng thể ngờ, đằng sau căn bệnh của Lâm Tương Chi lại là một bí mật còn đau lòng hơn...</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Kim Mạch","avatar":""},{"name":"Lâm Nhất","avatar":""},{"name":"Thẩm Nguyệt","avatar":""},{"name":"Uông Giai Huy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一周的朋友"]', 1784690324264);
