INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('be-noi-phan-1', 'Bề Nổi (Phần 1)', 'Surface (Season 1)', 'bề nổi (phần 1) surface (season 1) gugu mbatha-raw oliver jackson-cohen millie brady phil dunster gavin drea rupert graves tara fitzgerald nina sosanya joely richardson freida pinto ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-cho-rieng-minh-em', 'Dành Cho Riêng Mình Em', 'Never Let Me Go', 'https://phimimg.com/upload/vod/20250412-1/be8ab1c4d311f9001bd9aed1f8c09a0b.jpg', 'https://phimimg.com/upload/vod/20250412-1/ef06ab9fce081b6b1787b5ecafff9946.jpg', '<p>Nuengdiao là người thừa kế của một gia đình danh giá. Địa vị của cậu buộc cậu phải lớn lên trong sự cô lập, không có chỗ cho sai lầm. Nhưng cha của cậu bị bắn chết ngay trước mặt cậu. Giờ đây, cậu và mẹ mình đang đối mặt với nguy hiểm. Palm, con trai của một nhân viên trung thành với gia tộc Kiattrakulmethee, được giao nhiệm vụ bảo vệ cậu khỏi những mối đe dọa cả trong lẫn ngoài trường học. Trong cuộc sống đầy bất ổn của mình, sự xuất hiện của Palm mang đến cho Nuengdiao những trải nghiệm hoàn toàn mới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Naravit Lertratkosum","avatar":""},{"name":"Phuwin Tangsakyuen","avatar":""},{"name":"Rasee Wacharapolmek","avatar":""},{"name":"Nat Sakdatorn","avatar":""},{"name":"Wachirawit Ruangwiwat","avatar":""},{"name":"Tanapon Sukumpantanasan","avatar":""},{"name":"Pitisak Yaowananon","avatar":""},{"name":"Panadda Ruangwut","avatar":""},{"name":"Thanik Kamontharanon","avatar":""},{"name":"Wanwimol Jaenasavamethee","avatar":""},{"name":"Supakit Tungtatsawat","avatar":""},{"name":"Pisith Nimitsamanjit","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["绝不放手","เพื่อนายแค่หนึ่งเดียว","Phuea Nai Khae Nueng Diao","絕不放手","只為你一人","Only for You","Living For You"]', 1784690324264);
