INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('danh-cho-rieng-minh-em', 'Dành Cho Riêng Mình Em', 'Never Let Me Go', 'dành cho riêng mình em never let me go naravit lertratkosum phuwin tangsakyuen rasee wacharapolmek nat sakdatorn wachirawit ruangwiwat tanapon sukumpantanasan pitisak yaowananon panadda ruangwut thanik kamontharanon wanwimol jaenasavamethee supakit tungtatsawat pisith nimitsamanjit 绝不放手 เพื่อนายแค่หนึ่งเดียว phuea nai khae nueng diao 絕不放手 只為你一人 only for you living for you', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-5', 'Họa giang hồ chi bất lương nhân (Phần 5)', 'A Portrait of Jianghu: Bad Guys (Season 5) / The Degenerate-Drawing Jianghu 5', 'https://phimimg.com/upload/vod/20250412-1/052df35874e0772fbd509d73ddcf2fad.jpg', 'https://phimimg.com/upload/vod/20250412-1/fabc2170fa778d85494242a90e900a07.jpg', '<p>Sau khi đoàn người trở về từ Nhiêu Cương, Trung Nguyên đã thay đổi hoàn toàn. Lý Tự Nguyên xưng làm Giám quốc, nhân danh Thiên tử truy sát Bất Lương Nhân. Bất Lương Soái là Viên Thiên Cương đã chết, tổ chức Bất Lương Nhân đã mất đi vị thủ lĩnh mạnh nhất và rơi vào tình trạng hỗn loạn, khó khăn bủa vây tứ phía. Trong bối cảnh đó, Thiên tử Lý Tinh Vân đứng trước một lựa chọn mới. Để cứu dân chúng Thái Nguyên, hắn đã trở thành tù nhân. Sau khi trải qua nhiều thử thách và khổ ải, Lý Tinh Vân dần trưởng thành. Trong phần này, hắn từ bỏ quá khứ và trở nên mạnh mẽ hơn để đối mặt với tranh chấp giang hồ. Cùng lúc đó, Cơ Như Tuyết cũng thoát khỏi hình ảnh yếu đuối trước đây, trở nên độc lập và mạnh mẽ, cùng với Lý Tinh Vân hỗ trợ nhau, cùng nhau đối diện với những thử thách.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Mengmeng Yan","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Qiuxiang Shen","avatar":""},{"name":"Jun Chu","avatar":""},{"name":"Shuren Zhao","avatar":""},{"name":"Xuecen Bai","avatar":""},{"name":"Lu Zhixing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["画江湖之不良人动画版","Huajianghu Bu Liang Ren","Buliang Ren VI","画江湖之不良人Ⅴ","Buliang Ren II","Buliang Ren V","Buliang Ren III","Buliang Ren IV","Buliang Ren","Drawing Jianghu Of Bu Liang Ren Ⅵ","Drawing Jianghu of Bu Liang Ren","Hua Jiang Hu Zhi Bu Liang Ren","The Degenerate-Drawing Jianghu","画江湖之不良人II","画江湖之不良人第七季：九幽玄天","画江湖之不良人","畫江湖之不良人","A Portrait of Jianghu Bad Guys","A Portrait of Jianghu : Bad Guys"]', 1784690324264);
