INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuoc-vai-se-duyen', 'Thước Vải Se Duyên', 'The Kinnaree Conspiracy', 'https://phimimg.com/upload/vod/20250411-1/15e6fec0d8a6c9b81e331431630d73da.jpg', 'https://phimimg.com/upload/vod/20250411-1/eff44e9824918fce1a4f77d7fe4412ad.jpg', '<p>Thời kỳ vua Narai thịnh vượng, người Tây nhập cư cùng những hoạt động thương mại sôi nổi. Thế nhưng, cái chết bí ẩn của một thuyền trưởng người Pháp đã đe dọa an nguy vương quốc khi Pháp có thể mượn cớ phát động xâm lược Ayutthaya. Lúc này, ba người, ba thân phận cùng tham gia điều tra vụ án, mở ra cuộc tình tay ba ngang trái.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 6, 2022, 'Vietsub + Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Nadech Kugimiya","avatar":""},{"name":"Urassaya Sperbund","avatar":""},{"name":"Diana Flipo","avatar":""},{"name":"Jirayu Thantrakul","avatar":""},{"name":"David Asavanond","avatar":""},{"name":"Puttachat Pongsuchat","avatar":""},{"name":"Natha Lloyd","avatar":""},{"name":"Daraneenute Pasutanavin","avatar":""},{"name":"Bongkot Kongmalai","avatar":""},{"name":"Prissana Klampinij","avatar":""},{"name":"Cake Nattavat Kaewbuasai","avatar":""},{"name":"Kanjanaporn Plodpai","avatar":""},{"name":"Sarut Vichitrananda","avatar":""},{"name":"Suk","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ลายกินรี"]', 1784690324264);
