INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-minh-do-2022', 'Bình Minh Đỏ', 'Red Dawn', 'https://phimimg.com/upload/vod/20250406-1/9022f97792662a60157f2374513a6fcf.jpg', 'https://phimimg.com/upload/vod/20250406-1/d22e1c15fc6a55b8b06b077c74aae4d8.jpg', '<p>Phim lấy bối cảnh Việt Nam sau tết Mậu Thân 1968, bộ Tư lệnh Đoàn 559 giao nhiệm vụ cho Binh trạm 9, Binh trạm 12 tuyển gấp một số nữ thanh niên xung phong để đào tạo lái xe vận tải trung chuyển cho chiến trường. Chuyện phim xoay quanh 4 nhân vật Châu, Hân, Sa, Thương là những nữ chiến sĩ lái xe từ Bến Thủy đến Tây Trường Sơn. Trong quá trình làm nhiệm vụ, lần lượt sự hi sinh của Hân, Thương, Sa và anh trai đã để lại nỗi đau lớn đối với Châu. Nhưng với lòng quyết tâm và ý chí mạnh mẽ, Châu đã tiếp tục ra chiến trường để thực hiện nhiệm vụ.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Phạm Quỳnh Anh","avatar":""},{"name":"Phạm Bảo Hân","avatar":""},{"name":"Hà Phương Anh","avatar":""},{"name":"Hoàng Bích Phượng","avatar":""},{"name":"Trần Việt Hoàng","avatar":""},{"name":"NSND Quốc Trị","avatar":""},{"name":"NSƯT Bùi Minh Phương","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["迷霧中的孩子","Children of the Mist","Những Đứa Trẻ Trong Sương"]', 1784690324264);
