INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-giay-got-nhon', 'Cuộc Chiến Giày Gót Nhọn', 'Kill Heel', 'https://phimimg.com/upload/vod/20240419-1/37901f03ad265a6e5054f302199ef0dc.jpg', 'https://phimimg.com/upload/vod/20240419-1/b4173d8ebcd65956241cfd4ec64ee9d7.jpg', '<p>Bộ phim truyền hình Hàn Quốc Kill Heel Cuộc Chiến Giày Gót Nhọn lấy nhân vật chính Woo Hyun làm trung tâm mô tả thế giới mua sắm online khốc liệt. Câu chuyện xoay quanh những người phụ nữ sống sót trong một thế giới đầy cạnh tranh và quyền lực của những nhân viên bán hàng với những tính cách khác biệt.\nNhân viên bán hàng thời trang Woo Hyun (do Kim Ha Neu thủ vai) tuy duy trì được phong độ tốt với hình ảnh gần gũi với mọi người nhưng lại thấy phiền não vì mọi thứ đang bị trì trệ.\nBộ phim được đạo diễn bởi No Do Cheol của Mặt Nạ Quân Chủ và được viết bởi biên kịch Hội Nữ Thám Tử Trường Seonam. Diễn viên chính Kim Ha Neu.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Ha Neul","avatar":""},{"name":"Kim Sung Ryoung","avatar":""},{"name":"Hye Young Lee","avatar":""},{"name":"Hye-yeong Lee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324264);
