INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-khong-biet-yeu', 'Chúng Ta Không Biết Yêu', 'Why Women Love', 'https://phimimg.com/upload/vod/20250404-1/800da1ec134575dffecbe005f0eee36c.jpg', 'https://phimimg.com/upload/vod/20250404-1/9a9804845165ce9d88699c7d5d290d2c.jpg', '<p>Phim Chúng ta không biết yêu xoay quanh Cố Gia Tâm một công tử giàu có nhưng không mảy may đến ý định sẽ thừa kế tài sản của gia đình. Chàng công tử Cố Gia Tâm có máu ăn chơi bị mẹ gửi gắm đến làm trợ lý cho nữ giám đốc Triệu Giang Nguyệt để học hỏi kinh nghiệm, sau này kế thừa gia sản. Cũng bắt đầu từ đây Cố Gia Tâm và Triệu Giang Nguyệt nảy sinh tình cảm, họ cùng nhau thực hiện ước mơ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Thần","avatar":""},{"name":"Vương Tử Dị","avatar":""},{"name":"Bành Nhã Kỳ","avatar":""},{"name":"Trịnh Diệu","avatar":""},{"name":"Hà Trạch Viễn","avatar":""},{"name":"Trần Tùng Linh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Why Women Love","不会恋爱的我们","不會戀愛的我們","Bu Hui Lian Ai De Wo Men","We are Not in Love","불회연애적아문 : 연애 못하는 우리","Научи меня любить"]', 1784690324264);
