INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hiep-phan-le-hoa', 'Nữ Hiệp Phàn Lê Hoa', 'Nvxia Fan Lihua', 'https://phimimg.com/upload/vod/20250402-1/8250719f505a66cf96b8b47619ff0cfd.jpg', 'https://phimimg.com/upload/vod/20250402-1/5ec1daeafe6d8b2c9a4a263394ca7abf.jpg', '<p>Câu chuyện này kể về thuyền thuyết dẹp cướp của nữ hiệp cổ đại. Cốt truyện tàn bạo và có một chút hài. Vì muốn tiêu diệt bọn cướp nên Lê Hoa đã có mối lương duyên định mệnh với anh hùng Đinh Sơn, cô yêu Đinh Sơn ngay từ cái nhìn đầu tiên nhưng Đinh Sơn muốn cô gác kiếm . Cuối cùng, cả hai đã trải qua bao gian khổ, thấu hiểu lòng nhau, cùng nhau hợp sức tiêu diệt bọn cướp. Cuối cùng, Đinh Sơn tin rằng Lê Hoa chết vì cứu mình</p>', 'Full', 1, 'single', 'completed', 5, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Zhimo Feng","avatar":""},{"name":"朱致靈","avatar":""},{"name":"Chen Yiming","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Dehui Zhang","avatar":""},{"name":"Zhao Tieying","avatar":""},{"name":"Li Weikang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324264);
