INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-no-sinh-tu', 'Vụ Nổ Sinh Tử', 'Blasting', 'https://phimimg.com/upload/vod/20250402-1/abeab073cfb6a1cb3355e3636ee75e43.jpg', 'https://phimimg.com/upload/vod/20250402-1/f17b702a7e44081d29d954742cb20051.jpg', '<p>Một vụ nổ xảy ra tại một nhà kho ở phía bắc thành phố Tân Hải, gây chấn động cả thành phố. Trong quá trình điều tra, Từ Trung Dân phát hiện ra rằng tàn dư vụ nổ ở hiện trường rất giống với vụ án &quot;ngày 11 tháng 6&quot; tám năm trước. Tám năm trước, một vụ cướp và đánh bom tàn khốc đã xảy ra tại một cửa hàng trang sức ở thành phố Tân Hải. Từ Trung Dân không thể tháo gỡ quả bom, dẫn đến cái chết của nghi phạm Sài Trí Phong, hai tên xã hội đen A Qủy và Điêu Thúc nhân cơ hội trốn thoát và biến mất khỏi hiện trường. Từ Trung Dân tự trách mình nên đã chăm sóc mẹ và em trai Sài Trí Phong trong nhiều năm. Cục Công an đã kết hợp vụ án đánh bom với vụ án &quot;ngày 11 tháng 6&quot; , chỉ thị cho Từ Trung Dân và đội cảnh sát hình sự thành lập một đội chuyên án để cùng phá án, bắt đầu một cuộc chiến sinh tử với tội phạm. Và vào sáng sớm cùng ngày, A Qủy người đã mãn hạn tù, lén lút đến thành phố Tân Hải gặp Điêu Thúc. Một vụ nổ bất ngờ khiến bất ngờ xảy ra ... Rốt cuộc ai mới là thủ phạm thực sự đứng sau tất cả những chuyện này?</p>', 'Full', 1, 'single', 'completed', 5, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Leni Lan","avatar":""},{"name":"Ken Lok Tat-Wah","avatar":""},{"name":"Bai Haitao","avatar":""},{"name":"Zhong Lei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["生死爆破"]', 1784690324264);
