INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-vu-hoa', 'Băng Vũ Hoả', 'Being A Hero', 'https://phimimg.com/upload/vod/20250401-1/9a669a5450524361afedd26fe4aacd99.jpg', 'https://phimimg.com/upload/vod/20250401-1/7b912d1e85d325929f2d91ac76e618d7.jpg', '<p>Ba năm trước, Ngô Cương bị sát hại bởi tập đoàn buôn ma túy K do liên quan đến ma túy. Con trai ông, Ngô Chấn Phong (do Trần Hiểu thủ vai), vì hành động bốc đồng và vi phạm kỷ luật nên bị khai trừ khỏi lực lượng cảnh sát. Chấn Phong rơi vào tuyệt vọng và định rời khỏi đất nước, nhưng bị người anh em thân thiết Trần Vũ (do Vương Nhất Bác thủ vai) ngăn cản. Trên đường đi, cả hai suýt bị tập kích, và để cứu Trần Vũ, Chấn Phong bị bọn buôn ma túy bắt cóc, từ đó mất tích hoàn toàn. Giây phút ấy đã thay đổi hoàn toàn số phận của cả hai. Ba năm sau, Trần Vũ trở thành cảnh sát phòng chống ma túy. Nhưng bất ngờ thay, Ngô Chấn Phong quay trở lại, đồng thời bị cuốn vào một vụ án mạng. Sau khi rửa sạch hiềm nghi, Trần Vũ dần phát hiện Chấn Phong có mối liên hệ chặt chẽ với tập đoàn buôn ma túy. Để triệt phá tổ chức này, Trần Vũ chấp hành nhiệm vụ từ cấp trên, tạm rời khỏi ngành và bắt đầu hành trình thâm nhập thế giới tội phạm. Chính lúc đó, anh mới biết được rằng Ngô Chấn Phong thực chất là một anh hùng đơn độc đã âm thầm thâm nhập vào tổ chức buôn ma túy suốt ba năm qua. Cả hai lần lượt xâm nhập vào nội bộ băng đảng, phối hợp ăn ý, cùng nhau chiến đấu, và cuối cùng, dưới sự chỉ huy của lực lượng cảnh sát, họ đã quét sạch toàn bộ tổ chức tội phạm ma túy. Sau nhiệm vụ sinh tử này, hai người tiếp tục cống hiến hết mình cho sự nghiệp phòng chống ma túy, giữ vững lý tưởng, không quên sứ mệnh của mình.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hiểu","avatar":""},{"name":"Vương Nhất Bác","avatar":""},{"name":"Vương Kình Tùng","avatar":""},{"name":"Lưu Dịch Quân","avatar":""},{"name":"Triệu Chiêu Nghi","avatar":""},{"name":"Trương Chí Kiên","avatar":""},{"name":"Phùng Gia Di","avatar":""},{"name":"Chương Dục Kỳ","avatar":""},{"name":"Quách Hiểu Đình","avatar":""},{"name":"Đồ Băng","avatar":""},{"name":"Cao Húc Dương","avatar":""},{"name":"Cung Lỗi","avatar":""},{"name":"Ngải Đông","avatar":""},{"name":"Triệu Huyên","avatar":""},{"name":"Đường Lữ Tinh","avatar":""},{"name":"Vương Tú Trúc","avatar":""},{"name":"Tống Hi","avatar":""},{"name":"Triệu Hiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Being a Hero","ฮีโร่ ล่าทรชน","Ice Rain Fire","冰雨火"]', 1784690324264);
