INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bang-vu-hoa', 'Băng Vũ Hoả', 'Being A Hero', 'băng vũ hoả being a hero trần hiểu vương nhất bác vương kình tùng lưu dịch quân triệu chiêu nghi trương chí kiên phùng gia di chương dục kỳ quách hiểu đình đồ băng cao húc dương cung lỗi ngải đông triệu huyên đường lữ tinh vương tú trúc tống hi triệu hiên being a hero ฮีโร่ ล่าทรชน ice rain fire 冰雨火', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-vun-huong-phai', 'Trầm Vụn Hương Phai', 'Immortal Samsara', 'https://phimimg.com/upload/vod/20250331-1/c02300c24123949c4a4888f777847d53.jpg', 'https://phimimg.com/upload/vod/20250331-1/dc2c393362f79d0c64b0eaccef160c3c.jpg', '<p>Trầm Hương Như Tiết (Trầm Vụn Hương Phai) chuyển thể từ tiểu thuyết cùng tên của tác giả Tô Mịch. Nhan Đàm (Dương Tử) là một đóa sen từ thời Thượng Cổ, cả người đều là dược liệu quý giá nhất. Trong buổi thịnh yến của Vương mẫu nương nương, cô và tỷ muội sinh đôi hóa thân thành người trước thời hạn trăm năm. Từ đó gặp phải tình kiếp lớn nhất đời mình là Ứng Uyên (Thành Nghị), một Ngư tinh của Nam Cực Tiên Ông. Để đổi lấy đôi chân cho Ứng Uyên, Nhan Đàm đã dùng nửa trái tim của mình đánh đổi. Nào ngờ Ứng Uyên lại quên mất cô, nửa trái tim còn lại làm Nhan Đàm sống như tro tàn. Cô từ bỏ tiên thể của mình để luân hồi, linh hồn tổn thương lưu lạc bên Vong Xuyên hơn 800 năm.</p>', 'Hoàn Tất (59/59)', 59, 'series', 'completed', 9, 2022, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Zi","avatar":""},{"name":"Cheng Yi","avatar":""},{"name":"Ray Zhang","avatar":""},{"name":"Meng Ziyi","avatar":""},{"name":"Xu Kaining","avatar":""},{"name":"Ye Qing","avatar":""},{"name":"Zhu Yongteng","avatar":""},{"name":"Fu Fangjun","avatar":""},{"name":"Li Xinze","avatar":""},{"name":"Han Chengyu","avatar":""},{"name":"Zhu Lilan","avatar":""},{"name":"Vicky Liang","avatar":""},{"name":"Lin Yuan","avatar":""},{"name":"Elisa Ye","avatar":""},{"name":"Hou Mengyao","avatar":""},{"name":"Zhang Zhixi","avatar":""},{"name":"Yang Xizi","avatar":""},{"name":"Sun Zeyuan","avatar":""},{"name":"Johnny Zhang","avatar":""},{"name":"Liu Mengmeng","avatar":""},{"name":"Zhong Qi","avatar":""},{"name":"Linda Zhang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["沉香如屑","沉香重华","沉香如屑·沉香重华","Agarwood Like Crumbs","Щепки агарового дерева","Вечная самсара","อวลกลิ่นละอองรัก","Ölümsüz Samsara","Immortal Samsara"]', 1784690324264);
