INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-bat-lua-va-vay-cong-chua', 'Chiếc Bật Lửa Và Váy Công Chúa', 'Lighter And Princess', 'https://phimimg.com/upload/vod/20240331-1/41262c6d3381d5ff35b619677bc33ac2.jpg', 'https://phimimg.com/upload/vod/20240331-1/38e0c5c60e6b48d51a71a59429d12ecb.jpg', '<p>Dù đến từ hai thế giới hoàn toàn khác nhau, giữa Lý Tuân và Chu Vận vẫn nảy sinh tình cảm sâu đậm. Nhưng rồi bi kịch đã xảy ra khiến Lý Tuân phải vào tù, chia cách đôi uyên ương. Bất chấp sự phản đối của gia đình, Chu Vận chưa từng bỏ rơi Lý Tuân và quyết tâm giúp anh vượt qua nỗi đau, làm lại cuộc đời sau khi ra tù.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 24, 2022, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phi Vũ","avatar":""},{"name":"Trương Tịnh Nghi","avatar":""},{"name":"Triệu Chí Vỹ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324264);
