INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-vong-phap-luat-2', 'Ngoài vòng pháp luật 2', 'The Roundup', 'https://phimimg.com/upload/vod/20250331-1/30fc850c32c489b3fb71d047c9d3ec98.jpg', 'https://phimimg.com/upload/vod/20250331-1/d42ca2f27a4273551e0faad371a932be.jpg', '<p>4 năm sau chiến dịch truy quét ở Garibong-dong, thám tử Ma Seok-do cùng với Đội trưởng Jeon Il-man và nhóm của anh đến Việt Nam để dẫn độ một nghi phạm, nhưng ngay sau khi anh đến, Seok-do phát hiện thêm một vụ án giết người và được nghe kể về Kang Hae-sang, một kẻ giết người độc ác đã nhẫn tâm giết chết nhiều du khách trong nhiều năm chỉ vì ham mê tiền bạc. Tại Việt Nam, bộ đôi không tài nào bắt được Kang Hae-sang, kẻ đã giết con trai duy nhất của một ông trùm kinh doanh Hàn Quốc. Họ quay trở lại Hàn Quốc để truy đuổi kẻ giết người sau khi Hae-sang tự nhập lậu bản thân vào đất nước này để tống tiền ông trùm kinh doanh. Bất chấp sự truy đuổi ráo riết của Seok-do ở Hàn Quốc, Kang Hae-sang vẫn luồn lách thoát khỏi vòng vây của cảnh sát, tiếp tục đi bắt cóc và giết người.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Don Lee","avatar":""},{"name":"Son Suk-ku","avatar":""},{"name":"Choi Gwi-hwa","avatar":""},{"name":"Park Ji-hwan","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Ha Jun","avatar":""},{"name":"Jeong Jae-kwang","avatar":""},{"name":"Nam Moon-chul","avatar":""},{"name":"Park Ji-young","avatar":""},{"name":"Lee Ju-won","avatar":""},{"name":"Um Mun-suk","avatar":""},{"name":"Kim Chan-hyung","avatar":""},{"name":"Lee Gyu-woon","avatar":""},{"name":"Jeon Jin-oh","avatar":""},{"name":"Lee Da-il","avatar":""},{"name":"Kim Young-sung","avatar":""},{"name":"Cha Woo-jin","avatar":""},{"name":"Park Kwang-jae","avatar":""},{