INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-gia', 'Trả Giá', 'Bargain', 'https://phimimg.com/upload/vod/20240302-1/d40d7162819e904cbc2cc86732e2e5ae.jpg', 'https://phimimg.com/upload/vod/20240302-1/5a871b6a7ece80b78868e14f8b9b3178.jpg', '<p>No Hyung Soo đến phòng trọ để gặp Park Joo Young. Anh ấy hài lòng với vẻ ngoài của cô ấy và vui vẻ trả tiền cho các dịch vụ của cô ấy, nhưng một điều bất ngờ đang chờ đợi No Hyung Soo. Anh ấy sớm bị bao vây bởi những người đến mua nội tạng của anh ấy. Họ mặc cả giá nội tạng của anh ấy với Park Joo Young tiến hành cuộc đấu giá, nhưng một trận động đất bất ngờ xảy ra. Trong tòa nhà bị sập, họ phải vật lộn để tồn tại.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jin Sun-Kyu","avatar":""},{"name":"Jun Jong-Seo","avatar":""},{"name":"Chang Ryul","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324264);
