INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-hieu-con-tim-phan-5', 'Tín Hiệu Con Tim (Phần 5)', 'Heart Signal (Season 5)', 'https://phimimg.com/upload/vod/20240608-1/2d8f4849e8a77cc7b77fe00909ad7245.jpg', 'https://phimimg.com/upload/vod/20250327-1/ad0e2100f8f9f3487a91cf52d40ee04a.jpg', '<p>Tín Hiệu Con Tim Mùa 5 là chương trình tiếp nối loạt chương trình thực tế giao lưu suy luận về tình cảm nam nữ. Với sự tham gia của hàng loạt người nổi tiếng giới nghệ sỹ showbiz Trung hứa hẹn mang đến nhiều trải nghiệm vui tươi cho các cặp đôi…</p>', 'Hoàn Tất (33/33)', 33, 'tvshows', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"AngelaBaby","avatar":""},{"name":"Du Haitao","avatar":""},{"name":"Yang Chaoyue","avatar":""},{"name":"Chengxuan Li","avatar":""},{"name":"Wu Xin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324264);
