INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-than-va-gai-quy', 'Tử Thần Và Gái Quỷ', 'Love Forever After', 'https://phimimg.com/upload/vod/20250326-1/3e64669e243c1272bdf783ccbd1847f8.jpg', 'https://phimimg.com/upload/vod/20250326-1/0f9ce9cfca6287ef68e9799db0b5685d.jpg', '<p>Tử Thần Và Gái Quỷ - Love Forever After kể về một ma nữ gặp phải vị thần chết đẹp trai chất ngất và trúng tiếng sét ái tình. Cả hai cùng nhau tạo nên một chuyện tình vừa bi hài vừa lãng mạn. Trong phim, Tualek là một linh hồn lang thang, một ngày nọ tình cờ gặp được Thần chết. Khi gặp cô, anh đưa cô đến Hội trường phán xét, nhưng cô chống đối kịch liệt và cố gắng trở lại cơ thể vô hồn của mình trong tuyệt vọng. Thần chết đành hứa sẽ giúp cô trở lại cơ thể của mình nếu cô hoàn thành nhiệm vụ được giao. Tualek chấp nhận thử thách, không biết rằng đó là một nhiệm vụ bất khả thi.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kamolned Ruengsri","avatar":""},{"name":"Vachiravit Paisarnkulwong","avatar":""},{"name":"Kajbhunditt Jaidee","avatar":""},{"name":"Namkhing Avika Pramesiripaisan","avatar":""},{"name":"Natasha Chulanond","avatar":""},{"name":"Atthama Chiwanitchaphan","avatar":""},{"name":"Kornnarat Ongsaranont","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["ยมทูตกับภูตสาว"]', 1784690324264);
