INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-truong-xac-song', 'Ngôi Trường Xác Sống', 'All of Us Are Dead', 'ngôi trường xác sống all of us are dead park ji-hu yoon chan-young cho yi-hyun lomon yoo in-soo lee you-mi kim byung-chul lee kyoo-hyung jeon bae-soo كلّنا موتى estamos muertos all of us are dead 僵尸校园 jigeum uri hakgyoneun είμαστε όλοι νεκροί 殭屍校園 mindannyian halottak vagyunk non siamo più vivi 今、私たちの学校は... now my school all of us are dead усі ми мертві ngôi trường xác sống 지금 우리 학교는', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-re-nha-toc-truong', 'Ở Rể Nhà Tộc Trưởng', 'My Matrilocal Husband', 'https://phimimg.com/upload/vod/20250325-1/ccaa12be618ca2e56ca28ab3c070c19d.jpg', 'https://phimimg.com/upload/vod/20250325-1/abe132ef6cae18dcfa83538f43b596a3.jpg', '<p>Tổng tài Lục Ngạo Thiên, người luôn kiêu ngạo và lạnh lùng, vì sao lại chấp nhận trở thành “chàng rể ở rể” để ở lại Hoa Thành? Người mẹ mất tích của anh có mối liên hệ gì với dãy núi tuyết bí ẩn này? Tộc trưởng Đoạn Nhược Nhu, vốn mạnh mẽ và quyết đoán, tại sao lại chủ động yêu cầu kết hôn với một người xa lạ? Trong khi đó, Tiểu Bạch, cô bạn thân kiêm nữ streamer nổi tiếng của Lục Ngạo Thiên, sẽ mang đến những điều mới mẻ gì cho bộ lạc này? Cuộc chiến hào môn tranh đấu sẽ diễn ra như thế nào trên mảnh đất lạnh giá này?</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thái Lạc","avatar":""},{"name":"Ngưu Ngọc Khôn","avatar":""},{"name":"Ngưu Tại Tại","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Son-in-Law of The Patriarch","The Patriarch''s Son-in-Law","Zu Zhang De Zhui Xu","族长的赘婿"]', 1784690324264);
