INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hon-nhan-xa-la', 'Cuộc Hôn Nhân Xa Lạ', 'On Marriage', 'https://phimimg.com/upload/vod/20250325-1/338bcf637927ec7294bc8e60e0b45a38.jpg', 'https://phimimg.com/upload/vod/20250325-1/98b533725eecd4813eefc54651bb2127.jpg', '<p>Bộ phim&nbsp;được trình bày theo hình thức tuyển tập và khai thác góc nhìn u ám, nhằm khơi gợi sự thảo luận và suy ngẫm về hôn nhân. Bộ phim tập trung vào đề tài gia đình, mang đến sự đồng cảm sâu sắc cho khán giả, đặc biệt là những người đã kết hôn. Trong cả 5 câu chuyện, các cặp đôi đều cố gắng sử dụng những sản phẩm công nghệ để cứu vãn cuộc hôn nhân đang trên bờ vực đổ vỡ.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 15, 2022, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lưu Quán Đình","avatar":""},{"name":"Tôn Khả Phương","avatar":""},{"name":"Lý Quốc Nghị","avatar":""},{"name":"Hoàng Địch Dương","avatar":""},{"name":"Lam Vi Hoa","avatar":""},{"name":"Lý Hạnh","avatar":""},{"name":"Diêu Thuần Diệu","avatar":""},{"name":"Giản Mạn Thư","avatar":""},{"name":"Lý Thuần","avatar":""},{"name":"Ngô Tử Phi","avatar":""},{"name":"Thi Danh Soái","avatar":""},{"name":"Hạ Vu Kiều","avatar":""},{"name":"Lâm Dự Hi","avatar":""},{"name":"Ôn Trinh Lăng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["你的婚姻不是你的婚姻：恭請光臨曾賈府喜事","你的婚姻不是你的婚姻：沙之書","你的婚姻不是你的婚姻：鼠患","你的婚姻不是你的婚姻：聖筊","你的婚姻不是你的婚姻：尾號1314","你的婚姻不是你的婚姻：命運事件簿","你的婚姻不是你的婚姻：梅莉","On Marriage: Save the Date","On Marriage: Book of Bayes","On Marriage: Marriage No.1314","On Marriage: Wishful Syncing","On Marriage: Mary''s Merry Marriage","Ni Te Hun Yin Pu Shih Ni Te Hun Yin","Ni De Hun Yin Bu Shi Ni De Hun Yin","On Marriage","你的婚姻不是你的婚姻"]', 1784690324264);
