INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-hon-nhan-xa-la', 'Cuộc Hôn Nhân Xa Lạ', 'On Marriage', 'cuộc hôn nhân xa lạ on marriage lưu quán đình tôn khả phương lý quốc nghị hoàng địch dương lam vi hoa lý hạnh diêu thuần diệu giản mạn thư lý thuần ngô tử phi thi danh soái hạ vu kiều lâm dự hi ôn trinh lăng 你的婚姻不是你的婚姻：恭請光臨曾賈府喜事 你的婚姻不是你的婚姻：沙之書 你的婚姻不是你的婚姻：鼠患 你的婚姻不是你的婚姻：聖筊 你的婚姻不是你的婚姻：尾號1314 你的婚姻不是你的婚姻：命運事件簿 你的婚姻不是你的婚姻：梅莉 on marriage: save the date on marriage: book of bayes on marriage: marriage no.1314 on marriage: wishful syncing on marriage: mary''s merry marriage ni te hun yin pu shih ni te hun yin ni de hun yin bu shi ni de hun yin on marriage 你的婚姻不是你的婚姻', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-hoa-bi', 'Tân Họa Bì', 'The New Painted Skin', 'https://phimimg.com/upload/vod/20250324-1/4caeb3137f4f0c406ede9c413cde02ea.jpg', 'https://phimimg.com/upload/vod/20250324-1/376d9fc232798844a97ad51509a8969c.jpg', '<p>Tướng quân Thủ Dương của nhân tộc đã giả vờ đầu hàng yêu tộc trong một trận chiến lớn và chờ đợi thời điểm thích hợp để giết Quỷ vương. Qủy Vương ra lệnh bắt Thu Tang vị hôn thê của Thủ Dương làm con tin. Tuy nhiên, sau khi giết Thu Tang do nhầm lẫn, chủ xưởng Trường Miên chế tạo mặt nạ da đã cải trang thành Thu Tang. Thủ Dương đưa Thu Tang trở lại trấn yêu, và Trường Miên thay thế Thu Tang làm vợ . Ma Vương biết được bộ mặt thật của Trường Miên, đã đe dọa Trường Miên. Trường Miên không thể chịu đựng được việc lừa dối Thủ Dương đã chủ động tiết lộ sự thật cho Thủ Dương biết. Khi Ma Vương xuất quân Thủ Dương đã chiến đấu với Ma Vương, nhưng vào lúc chiến thắng, ông nhìn thấy Trường Miên đóng giả Ma Vương. Hóa ra là Trường Miên đã bí mật thiết lập một âm mưu, liều mạng của mình, để giết Ma Vương một mình. Cô cải trang thành Ma Vương và đến gặp Thủ Dương, sẵn sàng chết dưới lưỡi kiếm của chàng.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Meng","avatar":""},{"name":"Li Jiaming","avatar":""},{"name":"Guo Zhiyan","avatar":""},{"name":"Liu Haojunlong","avatar":""},{"name":"Chi Jia","avatar":""},{"name":"Shang Na","avatar":""},{"name":"Yuxi Yang","avatar":""},{"name":"Cui Yinger","avatar":""},{"name":"Zhang Zuoyan","avatar":""},{"name":"Yang Yuxi","avatar":""},{"name":"Diana Dai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["新画皮"]', 1784690324264);
