INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tro-tay-hanh', 'Nhà Trọ Tây Hành', 'Westbound Inn', 'https://phimimg.com/upload/vod/20231211-1/458b30cd2fbc5aceb4905521d292516b.jpg', 'https://phimimg.com/upload/vod/20231211-1/dbb650af05a37d7ff2ed163f971dcefa.jpg', '<p>Ở vùng đất cát vàng, võ sĩ chống Nhật Bản Truy Mã lưu lạc đếm đây và mở một quán trọ. Một ngày nọ, con gái của kẻ thù, Bạch Lộc chạy trốn đến nơi này với một rương kho báu. Những mối hận thù nổi lên. Đây là cơ hội trời cho, chuyện gì cũng có thể giải quyết nhanh chóng. Tuy nhiên, đối mặt với những bí mật chống Nhật Bản , vì lợi ích của quốc gia và đất nước, Truy Mã đã từ bỏ mối hận thù của mình, chịu đựng những xung đột do hiểu lầm và bảo vệ Bạch Lộc bằng cả mạng sống của mình, từ đó cuối cùng thực hiện được ước mơ, phục vụ tổ quốc.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ren Yu","avatar":""},{"name":"Mishell","avatar":""},{"name":"Xingyao Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324264);
