INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-thuyet-mau-hong', 'Học Thuyết Màu Hồng', 'GAP The Series', 'https://phimimg.com/upload/vod/20250322-1/e9bcd387e81e710ce3ff6352b0ec8863.jpg', 'https://phimimg.com/upload/vod/20250322-1/4a7dfd857197289cb0fce30357a305de.jpg', '<p>Mon, một sinh viên mới tốt nghiệp đại học, bắt đầu làm thực tập sinh tại một công ty lớn vì cô ngưỡng mộ Sam — nữ chủ tịch siêu giàu từ khi còn nhỏ. Tuy nhiên, khi Mon gặp lại Sam, hình ảnh về cô ấy hoàn toàn sụp đổ, vì Sam không hề giống như những gì truyền thông thể hiện.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Rebecca Patricia Armstrong","avatar":""},{"name":"Sarocha Chankimha","avatar":""},{"name":"Asavarid Pinitkanjanapun","avatar":""},{"name":"Urassaya Malaiwong","avatar":""},{"name":"Natnicha Vorrakittikun","avatar":""},{"name":"Orntara Poolsak","avatar":""},{"name":"Punnisa Sirisang","avatar":""},{"name":"Ratchanon Kanpiang","avatar":""},{"name":"Suttatip Wutchaipradit","avatar":""},{"name":"Thongthong Mokjok","avatar":""},{"name":"Natsinee Charoensitthisap","avatar":""},{"name":"Jirawat Wachi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["GAP The Series","Pink Theory","GAP Yuri","ทฤษฎีสีชมพู"]', 1784690324264);
