INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-lan-quyet', 'Thương Lan Quyết', 'Love Between Fairy And Devil', 'https://phimimg.com/upload/vod/20240409-1/d174d89b47afecd290a8b5e33b61d9ca.jpg', 'https://phimimg.com/upload/vod/20240409-1/b8713c42f66c99ae9bbfaf5b5de1757c.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết Ma tôn của tác giả Cửu Lộ Phi Hương. Câu chuyện kể về mối lương duyên ngang trái giữa Thần nữ thuộc tộc Phách Tâm và Ma tôn Phương Đông Thanh Thương. Thần nữ Phách Tâm tộc bị Ma tôn Đông Phương Thanh Thương diệt tộc, vạn năm sau sống lại trở thành thần tiên cấp thấp ở tiên giới Hoa Lan Nhỏ, vô tình làm cho Ma tôn đang bị nhốt trong tháp Hạo Thiên sống lại. Để hóa giải phong ấn chú thuật trên người cũng như hồi sinh kẻ thù lớn nhất, lần này Đông Phương Thanh Thương cần phải hy sinh hồn thần nữ của Hoa Lan Nhỏ. Tuy nhiên trong quá trình đó, đại ma đầu đã dần yêu tiểu tiên nữ ranh ma đáng yêu. Giới thiệu tập: Thương Lan Quyết kể về câu chuyện của thần nữ Phách Tâm tộc bị Ma Tôn Đông Phương Thanh Thương ( do Vương Hạc Đệ thủ vai) diệt toàn tộc. Vạn năm sau, nàng sống lại thành Hoa Lan Nhỏ (do Ngu Thư Hân thủ vai) – một tiên nữ cấp thấp trên thiên giới. Lúc sống lại chẳng ngờ lại vô tình đụng độ kẻ thù diệt tộc của chính mình. Đông Phương Thanh Thương bị vây trong Hạo Thiên Tháp, để giành được tự do, hắn phải lấy hồn thần nữ của Hoa Lan Nhỏ để giải phong ấn trên người. Trong quá trình ấy, đại ma đầu đã đoạn tình tuyệt ái vậy mà lại đem lòng yêu Hoa Lan Nhỏ khả ái dịu ngoan.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Ngu Thư Hân","avatar":""},{"name":"Vương Hạc Đệ","avatar":""},{"name":"Từ Hải Kiều","avatar":""},{"name":"Quách Hiểu Đình","avatar":""},{"name":"Trương Lăng Hách","avatar":""},{"name":"Lâm Bách Duệ","avatar":""},{"name":"Hồng Tiêu","avatar":""},{"name":"Trương Thần Tiêu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324264);
