INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-cua-ke-da-chet-phan-1', 'Vợ Của Kẻ Đã Chết (Phần 1)', 'Woman Of The Dead (Season 1)', 'https://phimimg.com/upload/vod/20240603-1/a72a259000755a110b3f378ef0efc2b4.jpg', 'https://phimimg.com/upload/vod/20240603-1/c4ae90eeba004021b6c4a720debd1ca6.jpg', '<p>Trong hành trình đầy thù hận để tìm ra kẻ đã sát hại chồng mình, một phụ nữ rốt cuộc đã phơi bày những bí mật sâu kín và xấu xí nhất ở cộng đồng nhỏ của cô.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anna Maria Mühe","avatar":""},{"name":"Yousef Sweid","avatar":""},{"name":"Hans-Uwe Bauer","avatar":""},{"name":"Felix Klare","avatar":""},{"name":"Emilia Pieske","avatar":""},{"name":"Lilian Rosskopf","avatar":""},{"name":"Romina Küper","avatar":""},{"name":"Simon Schwarz","avatar":""},{"name":"Sebastian Hülk","avatar":""},{"name":"Shenja Lacher","avatar":""},{"name":"Gregor Bloéb","avatar":""},{"name":"Robert Palfrader","avatar":""},{"name":"Michou Friesz","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324264);
