INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-cua-ke-da-chet-phan-1', 'Vợ Của Kẻ Đã Chết (Phần 1)', 'Woman Of The Dead (Season 1)', 'vợ của kẻ đã chết (phần 1) woman of the dead (season 1) anna maria mühe yousef sweid hans-uwe bauer felix klare emilia pieske lilian rosskopf romina küper simon schwarz sebastian hülk shenja lacher gregor bloéb robert palfrader michou friesz ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-an-thit-nguoi-phan-1', 'Làng Ăn Thịt Người (Phần 1)', 'Gannibal (Season 1)', 'https://phimimg.com/upload/vod/20240517-1/a8d88bbb74214d6ea09795b9cb2c164b.jpg', 'https://phimimg.com/upload/vod/20240517-1/2a022d6a2de691268c03cfb5c6cecf39.jpg', '<p>Truyện tranh hồi hộp gây sốc cùng tên của Masaaki Ninomiya, đã bán được tổng cộng hơn 2 triệu bản, sẽ được dựng thành phim truyền hình người thật đóng dưới dạng sê-ri từ Nhật Bản. Dàn nhân sự hàng đầu của Nhật Bản đã tập hợp cho tác phẩm này, vốn được cho là khó thực hiện live action do nội dung gây sốc.Daigo Agawa và gia đình đóng quân tại một ngôi làng miền núi cách xa thành phố. Tuy nhiên, có một tin đồn ở ngôi làng xinh đẹp rằng mọi người sẽ bị ăn thịt trong ngôi làng này... Daigo tìm kiếm sự thật với niềm tin là một sĩ quan cảnh sát, nhưng chẳng bao lâu sau, cuộc sống hàng ngày bình lặng của ngôi làng bắt đầu lộ ra một bộ mặt đáng sợ. Những sự kiện bí ẩn nối tiếp nhau, những người dân làng thân thiện nhưng hơi kỳ quái... Daigo trở nên nghi ngờ mọi thứ và bị đẩy đến bờ vực của sự điên loạn. Tôi hay họ xa lạ? Với sự tham gia của Yuya Yagira, đạo diễn thiên tài Shinzo Katayama và nhà biên kịch từng đoạt giải Cannes Takayoshi Oe giới thiệu một bộ phim bom tấn kinh dị tâm lý làm rung chuyển lẽ thường trong một xã hội làng quê khép kín.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuya Yagira","avatar":""},{"name":"Show Kasamatsu","avatar":""},{"name":"Riho Yoshioka","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324264);
