INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-huy-diet-phan-2', 'Sự Hủy Diệt (Phần 2)', 'Star Trek: Picard (Season 2)', 'https://phimimg.com/upload/vod/20240403-1/7dd38cb2f3ee4578d3be27cec3bbc43d.jpg', 'https://phimimg.com/upload/vod/20240403-1/0f4796022945082140d632d802d75ecd.jpg', '<p>Phần hai đưa huyền thoại Jean-Luc Picard và phi hành đoàn của anh ấy vào một hành trình mới táo bạo và thú vị: về quá khứ. Picard phải tranh thủ những người bạn cũ và mới để đối đầu với những hiểm họa của Trái đất thế kỷ 21 trong một cuộc chạy đua tuyệt vọng với thời gian để cứu lấy tương lai của thiên hà - và đối mặt với thử thách cuối cùng từ một trong những kẻ thù lớn nhất của mình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Stewart","avatar":""},{"name":"Jeri Ryan","avatar":""},{"name":"Michelle Hurd","avatar":""},{"name":"Ed Speleers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324264);
