INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-cau-tinh-dau-cua-toi', 'Gửi Cậu, Tình Đầu Của Tôi', 'Dear M', 'https://phimimg.com/upload/vod/20250318-1/cc413a62b9a52aa1452d717f9ca60780.jpg', 'https://phimimg.com/upload/vod/20250318-1/a1253049c04a9622a86e4a01ab609b62.jpg', '<p>Một lá thư tỏ tình gửi cho “M” do một người giấu tên đăng lên diễn đàn sinh viên của trường đại học Seoyeon. Ngay sau khi đăng tải, bức thư lập tức được sinh viên trong trường bàn tán xôn xao và bắt đầu cuộc hành trình tìm kiếm nhân vật “M” trong thư.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hye-su","avatar":""},{"name":"Jaehyun","avatar":""},{"name":"Roh Jeong-eui","avatar":""},{"name":"Bae Hyeon-seong","avatar":""},{"name":"Lee Jin-hyuk","avatar":""},{"name":"Woo Da-vi","avatar":""},{"name":"Kwon Eun-bin","avatar":""},{"name":"Hwang Bo-reum-byeol","avatar":""},{"name":"Lee Jung-sic","avatar":""},{"name":"Yoon Jin-sol","avatar":""},{"name":"Kim Joon-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dear. M","dieoem","디어엠-연플리","dieo.em","Dear M","戀愛播放列表DearM","디어엠"]', 1784690324264);
