INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-tuyet-dieu-cua-nhoc-nicholas', 'Mùa Hè Tuyệt Diệu Của Nhóc Nicholas', 'Nicholas'' Fantastic Summer', 'https://phimimg.com/upload/vod/20250318-1/579d9212beee6fb565a3fef5ae08f689.jpg', 'https://phimimg.com/upload/vod/20250318-1/b6d4af3a97037be4146324a3fc0619f5.jpg', '<p>Mùa hè tuyệt vời đã đến với Nicholas và bạn bè của cậu: dành thời gian cho gia đình, tìm những địa điểm mới để khám phá, và trên hết là... gặp gỡ những người bạn mới. Mùa hè ở biển còn là thời điểm tuyệt hảo để đi săn tìm kho báu với hội bạn, hoặc xây lâu đài cát và tưởng tượng mình là những hiệp sĩ dũng cảm bảo vệ một công chúa bí ẩn!</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 8, 2022, 'Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Wilson DOS SANTOS","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Apartment 413"]', 1784690324264);
