INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-con-gai-va-bo-thong-thai', 'Bốn Con Gái Và Bố Thông Thái', 'Living With Dad', 'https://phimimg.com/upload/vod/20250318-1/bdf12ac39de4a608a0276950eea3828f.jpg', 'https://phimimg.com/upload/vod/20250318-1/276b88287dcfc50a0043ba39d2be6fdd.jpg', '<p>Bốn chị em gái – 2, 8, 12 và 18 tuổi – mỗi người một tính cách, cũng như mỗi người có một người mẹ khác nhau! Tuy nhiên, họ đều có chung một người cha – một diễn viên đã nhận vai diễn lớn nhất đời mình: chăm sóc bốn cô con gái yêu dấu của mình.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 9, 2022, 'Thuyết Minh', 'FHD', 'Bỉ', 0, '[{"name":"Damien Boisseau","avatar":""},{"name":"Émilie Marié","avatar":""},{"name":"Alice Orsat","avatar":""},{"name":"Emmylou Homs","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Les Filles de Dad"]', 1784690324265);
