INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-trung-vo-nhan', 'Mục Trung Vô Nhân', 'Eye For An Eye', 'https://phimimg.com/upload/vod/20240219-1/7a3fa50502a174e0b4b1f358b6213645.jpg', 'https://phimimg.com/upload/vod/20240219-1/c2ee71d025611c0b9496ecffabb2665f.jpg', '<p>Bộ phim hành động tội phạm cổ trang &quot;Mục Trung Vô Nhân&quot; do Ngụy Tuấn Tử sản xuất, giám chế Trương Triết, Dương Bỉnh đạo diễn kiêm kịch bản, cùng sự tham gia của các diễn viên Cao Duy Mạn, Hướng Hạo, Lưu Bôn, Trương Địch Anh. Anh chàng “bắt dao” với những pha nguy hiểm, gặp Nghê Yến một cô gái bị làm nhục, vốn dĩ không muốn can thiệp, nhưng vô tình bị kéo vào một cuộc tranh chấp quyền lực đen tối. Thành Hạt Tử bắt đầu con đường tìm kiếm công lí và trả thù, dần dần danh tính thực sự của cậu ta cũng được tiết lộ...</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Miu Tse","avatar":""},{"name":"Gao Wei Wan","avatar":""},{"name":"Xiang Hao","avatar":""},{"name":"Liu Ben","avatar":""},{"name":"Zhang Di","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324265);
