INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xi-trum-phan-2', 'Xì Trum (Phần 2)', 'The Smurfs 3D (Season 2)', 'https://phimimg.com/upload/vod/20250313-1/d9910227f7f9ffb1a2715c3fd0eb18ac.jpg', 'https://phimimg.com/upload/vod/20250313-1/8faeb648c93e9b0c0cbc49c8c2ee007b.jpg', '<p>Bộ phim là những cuộc phiêu lưu của các cô cậu Xì Trum màu xanh nhỏ bé, sống trong những ngôi nhà hình nấm dễ thương ở một ngôi làng yên bình. Chỉ cần nghe tên gọi là có thể biết được tố chất, bản tính của họ, nào là Tí Vua, Tí Quạu, Tí Cô Nương, Tí Điệu, Tí Đô, Tí Quậy... Họ luôn đoàn kết, bảo bọc nhau trước cái xấu và những âm mưu, thủ đoạn của lão Gà Mên độc ác.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 9, 2022, 'Lồng Tiếng', 'FHD', 'Pháp', 0, '[]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["개구쟁이 스머프 NEW"]', 1784690324265);
