INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-meo-cua-simon-phan-dac-biet', 'Chú Mèo Của Simon (Phần Đặc Biệt)', 'Simon''s Cat (Special)', 'https://phimimg.com/upload/vod/20250313-1/59f23ad7d762ca72595ae398471b84fd.jpg', 'https://phimimg.com/upload/vod/20250313-1/841c20a6fce104a28317c316a8e17c7b.jpg', '<p>Phim là những cuộc phiêu lưu dường như vô tận của chú mèo béo ú, thông minh và vô cùng nghịch ngợm nhà Simon. Là chú mèo luôn đói bụng, chú ta đã khiến cậu chủ Simon thường xuyên rơi vào các tình huống khó xử nhưng không kém phần vui nhộn.</p>', '4', 4, 'hoathinh', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Simon Tofield","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["西蒙和他的猫","Simon''s Cat"]', 1784690324265);
