INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-son-phi-ho-kho-bau-phuong-bac', 'Tuyết Sơn Phi Hồ: Kho Báu Phương Bắc', 'The Hidden Fox', 'https://phimimg.com/upload/vod/20250305-1/f4d1aaed2e1282084ec436fe25e12041.jpg', 'https://phimimg.com/upload/vod/20250305-1/fd8e1fd1451ea9a9fcffe39fd4152b6e.jpg', '<p>Kho báu của vua Sấm để lại đã làm thiệt hại biết bao nhiêu sinh mạng vì lòng tham không đáy. Kẻ tham lam, độc ác nhất phải nói đến Điền Quy Nông hắng ta cùng thuộc hạ đã lập mưu thâm ác hãm hại 2 anh hùng là Hồ Nhất Đao và Miêu Nhân Phụng tử nạn, để hòng chiếm lấy kho báu, nhưng không ngờ lúc này bản đồ chỉ đường biến mất mãi đến tận 10 năm sau mới xuất hiện, thế là chúng ác nhân quy tụ, tranh giành đẫm máu.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Huawei","avatar":""},{"name":"Chen Yusi","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Chunyu Shanshan","avatar":""},{"name":"Chen Zihan","avatar":""},{"name":"Yang Yi","avatar":""},{"name":"Zhao Zichong","avatar":""},{"name":"Fu Jia","avatar":""},{"name":"Ben Ng Ngai-Cheung","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["설산비호 : 새북보장","The Flying Swordsman","ขุมทรัพย์แห่งเฟยหู","雪山飞狐之塞北宝藏"]', 1784690324265);
