INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-trong-tam-tri-toi', 'Ngôi Sao Trong Tâm Trí Tôi', 'Star And Sky: Star In My Mind', 'https://phimimg.com/upload/vod/20250305-1/fc216cf41a3982b2ace4206609a6b67e.jpg', 'https://phimimg.com/upload/vod/20250305-1/f7f1f2b977c7c0d37f1b1ef1b80503cc.jpg', '<p>Daonuea từng thầm thích Khabkluen khi còn học cấp ba và lấy hết can đảm để tỏ tình vào ngày cuối cùng trước khi rời trường. Tuy nhiên, cậu đã bị từ chối một cách nhẹ nhàng. Bước vào cuộc sống đại học, Daonuea bất ngờ phát hiện rằng bạn cùng ký túc xá của mình không ai khác chính là Khabkluen. Điều gì sẽ xảy ra khi một người ngừng yêu, nhưng người kia mới bắt đầu rung động?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Archen Aydin","avatar":""},{"name":"Natachai Boonprasert","avatar":""},{"name":"Jiruntanin Trairattanayon","avatar":""},{"name":"Jirakit Thawornwong","avatar":""},{"name":"Weerayut Chansook","avatar":""},{"name":"Chinnarat Siriphongchawalit","avatar":""},{"name":"Supoj Janjareonborn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["星空恋人","ขั้วฟ้าของผม","แล้วแต่ดาว | ขั้วฟ้าของผม Special EP","แล้วแต่ดาว"]', 1784690324265);
