INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-sao-trong-tam-tri-toi', 'Ngôi Sao Trong Tâm Trí Tôi', 'Star And Sky: Star In My Mind', 'ngôi sao trong tâm trí tôi star and sky: star in my mind archen aydin natachai boonprasert jiruntanin trairattanayon jirakit thawornwong weerayut chansook chinnarat siriphongchawalit supoj janjareonborn 星空恋人 ขั้วฟ้าของผม แล้วแต่ดาว | ขั้วฟ้าของผม special ep แล้วแต่ดาว', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-y-vi-sao', 'Theo Ý Vì Sao', 'Star And Sky: Sky In Your Heart', 'https://phimimg.com/upload/vod/20240409-1/3f6607a7d3491d2e217cb3d7449e973d.jpg', 'https://phimimg.com/upload/vod/20250305-1/71be34a3517ed53dc739fc6a2f73ab2a.jpg', '<p>Daonuea (Natachai Boonprasert) phải sang Đức học cấp 3 nên anh đã đi nhờ mọi người ký tên và ghi lời chúc lên áo đồng phục của mình. Dao thích thầm Kluen, trước khi đi, Dao đã đến gặp Kabkluen (Archen Aydin). Daonuea đã thổ lộ lòng mình với anh ấy nhưng không nhận được câu trả lời.Sau khi học xong tại Đức, Daonuea lại trở về Thái Lan để học đại học. Trùng hợp thay, Danuea lại học chung trường, thậm chí là ở cùng ký túc xá với Kabkluen. Sau khi gặp lại, Kabkluen dần dần rung động trước Daonuea nhưng Daonuea lại không muốn mở lòng với ai nữa. Từ đây, cả hai bắt đầu hành trình đi tìm cảm xúc thật sự của mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Natachai Boonprasert","avatar":""},{"name":"Archen Aydin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324265);
