INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('theo-y-vi-sao', 'Theo Ý Vì Sao', 'Star And Sky: Sky In Your Heart', 'theo ý vì sao star and sky: sky in your heart natachai boonprasert archen aydin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nam-khong-co-cong-viec-2022', 'Một Năm Không Có Công Việc', 'A Year Without A Job', 'https://phimimg.com/upload/vod/20250305-1/e73be47d79ae899e90d1de2687a5d188.jpg', 'https://phimimg.com/upload/vod/20250305-1/41c3344994a71f3da4538924dd156b85.jpg', '<p>Đại Vũ sinh năm 1985, vì quá quan tâm đến công việc không còn thời gian chăm sóc bạn trai, đồng thời một lúc mất cả bạn trai và mất việc. Tiểu Vũ sinh năm 1995, làm việc một cách ngẫu hứng và tự nguyện xin nghỉ việc vì chán nản. Cả hai vô tình sống chung một mái nhà vào ngày đầu tiên Đại Vũ mất việc. Cứ thế hai con người xa lạ đã giúp đỡ nhau thay đổi bản thân, cũng như tìm được ý nghĩa của cuộc sống và công việc.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 5, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Gia Kỳ","avatar":""},{"name":"Vạn Bằng","avatar":""},{"name":"Trạch Tử Lộ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["没有工作的那一年","A Year With Freedom","Mei You Gong Zuo De Yi Nian","a Year Without a Job","没有工作的一年"]', 1784690324265);
