INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-nam-khong-co-cong-viec-2022', 'Một Năm Không Có Công Việc', 'A Year Without A Job', 'một năm không có công việc a year without a job lý gia kỳ vạn bằng trạch tử lộ 没有工作的那一年 a year with freedom mei you gong zuo de yi nian a year without a job 没有工作的一年', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-cung-biet-anh-yeu-em', 'Ai Cũng Biết Anh Yêu Em', 'Almost Lover', 'https://phimimg.com/upload/vod/20240215-1/de9b69f30c1561eb973d1db340daaf89.jpg', 'https://phimimg.com/upload/vod/20240215-1/8acb7861ae1d42e3a147dbe9ff5342b7.jpg', '<p>He Xiao Ran là MC của một chương trình radio đêm khuya. Nhưng những biến cố xảy ra trong vài năm cuối đời khi còn là sinh viên vẫn ám ảnh cô. Cô thầm yêu Xiao Shang Qi, một người bạn thân khác giới. Nhưng thay vì tiến đến với anh, cô phải bất lực nhìn anh theo đuổi giấc mơ tình yêu của mình với một người phụ nữ khác - người bạn chung của họ là Chen Fei Er. Cô ấy bị cưỡng bức chịu đựng sự đau lòng khi chứng kiến người đàn ông cô yêu bắt đầu mối quan hệ với bạn thân của cô. Và vì tình bạn mà cô ấy quý trọng, cô ấy giữ kín tình cảm của mình. Cuối cùng, cô chuyển đi và bắt đầu làm DJ trên đài phát thanh. Nhưng quá khứ quay trở lại cắn xé cô 8 năm sau khi Xiao Shang Qi đến thị trấn sau một thời gian dài ở nước ngoài. Anh được giao nhiệm vụ xoay chuyển tình thế của một khách sạn độc quyền đã rơi vào thời kỳ khó khăn. Con đường của họ lại giao nhau, và lần này Xiao Shang Qi tỏ ra quyết tâm sửa chữa những sai lầm trước đây của mình. Anh nói với cô rằng anh chưa bao giờ ngừng nghĩ về cô. Nhưng liệu có quá muộn để hòa giải? Hay thần Cupid có thể tìm cách quay ngược kim đồng hồ về một mối quan hệ không bao giờ có ... nhưng lẽ ra luôn nên có?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cung Uyển Di","avatar":""},{"name":"Tống Thiến","avatar":""},{"name":"Hứa Ngụy Châu","avatar":""},{"name":"Cao Duệ Phỉ Nhi","avatar":""},{"name":"Cao Nhân","avatar":""},{"name":"Quách Thước Kiệt","avatar":""},{"name":"Nhâm Bân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324265);
