INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-dau-yeu-anh', 'Lần Đầu Yêu Anh', 'Special: First Love', 'https://phimimg.com/upload/vod/20240302-1/39798d4f62bde67412de8bcf69c4e17f.jpg', 'https://phimimg.com/upload/vod/20240302-1/ea6a742dd26b8674fabbd43a5ddc37ee.jpg', '<p>Lần Đầu Yêu Anh là một bộ phim về tình yêu tuổi trẻ của đạo diễn Thẩm Thấm Nguyên với sự tham gia của Điền Hi Vi và Vương Tinh Việt.Bộ phim kể về Lư Vãn Vãn - cô sinh viên năm hai khoa Lâm sàng của trường Đại học Y Thanh Diệu, vậy mà tâm lý kém khiến cô có biểu hiện bất thường mỗi khi thi cử, điều này không phù hợp với ngôi trường y khoa nghiêm ngặt. Sau nhiều năm yêu thầm không thành, Lư Vãn Vãn say rượu tuyên bố sẽ theo đuổi siêu cấp học bá cùng trường Nhâm Sơ.Sau tuyên bố này khiến scandal tình ái giữa hai người ngày càng lan rộng, ảnh hưởng nghiêm trọng đến việc học tập và cuộc sống vốn đã rất vất vả của Lư Vãn Vãn. Để làm rõ mối quan hệ giữa hai người, cô đã cùng với Nhâm Sơ tạo ra Kế hoạch loại bỏ Scandal. Trong quá trình làm rõ scandal, cả hai đã nhìn thấy điểm sáng trong tính cách của nhau và dần nảy sinh tình cảm với nhau. Với sự giúp đỡ và hướng dẫn của Nhâm Sơ, Lư Vãn Vãn đã dần vượt qua chính mình, tìm được sự cân bằng giữa sở thích và việc học của mình, đồng thời chăm chỉ học tập để trở thành một sinh viên y khoa đạt chuẩn. Nhâm Sơ cũng bị Vãn Vãn ảnh hưởng , bỏ đi vẻ mặt kiểu ngạo lạnh lũng càng ngày càng trở lên dễ gần và thân thiện hơn. Cả hai đã vô tình thay đổi lẫn nhau và trở thành một phiên bản tốt hơn của chính họ, cuối cùng họ đã có được một mối tình lãng mạn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Điền Hi Vi","avatar":""},{"name":"Vương Tinh Việt","avatar":""},{"name":"Thôi Thiệu Dương","avatar":""},{"name":"Phương Hiểu Đông","avatar":""},{"name":"Triệu Dục Huyên","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324265);
