INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-nhoc-do-chang-dang-yeu', 'Cậu Nhóc Đó Chẳng Đáng Yêu', 'Cute Bodyguard', 'https://phimimg.com/upload/vod/20250302-1/12c71d14c70837650291bb5e18219935.jpg', 'https://phimimg.com/upload/vod/20250302-1/29ee0419e58800e309835c6a7bdb7568.jpg', '<p>Phim&nbsp;kể về câu chuyện Cố Vinh, một chàng trai ngang ngược, hống hách, tựa như một cậu ấm chuyên gây chuyện. Còn Tô Tịnh Tịnh, một cô gái trông có vẻ dễ thương nhưng thực chất lại rất giỏi võ. Một chuyện ngoài ý muốn đã khiến hai người vốn không hề liên quan đã phải dính dáng đến nhau, Tô Tịnh Tịnh còn trở thành vệ sĩ riêng của Cố Vinh. Mối tình lãng mạn sắp sửa bắt đầu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đặc","avatar":""},{"name":"Lăng Mỹ Sĩ","avatar":""},{"name":"Chu Tử Hinh","avatar":""},{"name":"Thường Triết Khoan","avatar":""},{"name":"Từ Phương Chu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["那小子不可爱","Этот парень не милый","That Guy Is Not Cute"]', 1784690324265);
