INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cat-roi-ky-uc-phan-1', 'Cắt Rời Ký Ức (Phần 1)', 'Severance (Season 1)', 'https://phimimg.com/upload/vod/20250301-1/62f813613efc14e47ba81b826cead435.jpg', 'https://phimimg.com/upload/vod/20250301-1/b7fa31b018679eb7541563793f235907.jpg', '<p>Mark dẫn đầu một nhóm nhân viên văn phòng có ký ức được tách rời giữa công việc và cuộc sống riêng. Khi một đồng nghiệp bí ẩn xuất hiện ở phạm vi ngoài công việc, nó mở đầu cho một hành trình khám phá sự thật về công việc của họ.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Scott","avatar":""},{"name":"Britt Lower","avatar":""},{"name":"Tramell Tillman","avatar":""},{"name":"Zach Cherry","avatar":""},{"name":"Jen Tullock","avatar":""},{"name":"Michael Chernus","avatar":""},{"name":"Dichen Lachman","avatar":""},{"name":"Sarah Bock","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Patricia Arquette","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Разделяне","Ruptura","人生切割术","Hüvitis","生活割離術","ניתוק","جدایی","جداسازی","세브란스: 단절","الشَّطر","Поділ","Розділення","Severance"]', 1784690324265);
