INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-gai-me-ke-la-ban-gai-cu-cua-toi', 'Con Gái Mẹ Kế Là Bạn Gái Cũ Của Tôi', 'My Stepmom''s Daughter Is My Ex', 'https://phimimg.com/upload/vod/20250301-1/9ccc71eed6aa67603e74414360e17273.jpg', 'https://phimimg.com/upload/vod/20250301-1/f5d64cc36ce4775c04ff380c973aa21f.jpg', '<p>Irido Mizuto và Ayai Yume từng hẹn hò trong thời sơ trung. Tuy nhiên, vì bất đồng trong những chuyện nhỏ nhặt mà hai người đã quyết định chia tay nhau vào ngày tốt nghiệp. Tưởng rằng mọi chuyện đã kết thúc, ngay sau đó Mizuto lại biết được người mẹ kế mà bố cậu sắp tái hôn lại chính là mẹ của Yume. Cũng vì thế mà Mizuto và Yume trở thành chị em một nhà trên danh nghĩa. Để giữ bí mật quan hệ tình cảm trước kia với bố mẹ, hai người đã đặt ra &quot;luật lệ anh chị em&quot;, rằng đối phương nào tỏ tình trước sẽ là người thua cuộc.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiro Shimono","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Miyu Tomita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Mamahaha no Tsurego ga Moto Kano Datta","Tsurekano","Mamahaha no Tsurego ga Motokano datta","Mamahaha Tsurego Motokano","継母の連れ子が元カノだった"]', 1784690324265);
