INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-lan-ky-vuc-vo-song-chau', 'Thần Lan Kỳ Vực Vô Song Châu', 'The Land of Miracles', 'https://phimimg.com/upload/vod/20250227-1/f33d763c529fe3faba16829b0f39dbcc.jpg', 'https://phimimg.com/upload/vod/20250227-1/68734f004eace47d6c1445b7296e5825.jpg', '<p>Vào năm 2501 - kỳ Băng Hà, hành tinh của Yêu tộc và Thú tộc đã va chạm với đại lục Yêu Tinh. Tổ tiên loài người đã đoán trước thảm họa này. Để cứu lấy thế giới, hai tộc Yêu và Tinh đã liên kết với các chủng tộc khác, cùng tạo ra thần khí Thất Thần Châu nhằm hóa giải sức mạnh của vụ va chạm. Tuy nhiên, hậu quả để lại là đại lục Yêu Tinh bị vỡ nát, chia tách nên sáu thành lớn và bảy sắc biển, gọi là Thần Lan Kỳ Vực. Hơn 300 năm sau, Yêu tộc dần thức tỉnh và bắt đầu xâm chiếm khắp nơi. Trong thời loạn lạc đó, có hai thiếu niên vô tình sở hữu Vô Song Châu – một phần của Thất Thần Châu. Nhờ bảo vật này, họ có khả năng triệu hồi và hỗ trợ nhau, mở ra một hành trình đầy biến động.</p>', 'Hoàn Tất (45/45)', 45, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Zekun Shi","avatar":""},{"name":"Yumeng Zhang","avatar":""},{"name":"Yun Wei Yi","avatar":""},{"name":"Wenxiao He","avatar":""},{"name":"Qiu Qiu","avatar":""},{"name":"Jinger Wang","avatar":""},{"name":"Sicen Liu","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Shen Lan Qi Yu Wushuang Zhu","The Land of Miracles - Wu Shuang Pearl","神瀾奇域無雙珠","神瀾奇域","Thần Lan Kỳ Vực Vô Song Châu","神澜奇域无双珠"]', 1784690324265);
