INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-bi-mat', 'Ngôi Nhà Bí Mật', 'The Secret House', 'https://phimimg.com/upload/vod/20250226-1/c9ef5a8ca08800d5c8341edfc8c2edf2.jpg', 'https://phimimg.com/upload/vod/20250226-1/d8685f5bed2310b8d061b979511ae676.jpg', '<p>Woo Ji Hwan là một luật sư, vì theo đuổi dấu vết về người mẹ mất tích mà anh đã quyết định khám phá những bí mật xung quanh mình. Ji Hwan có một gia đình bất hạnh, đây cũng là bí mật mà anh luôn che giấu. Mối tình đầu của Woo Ji Hwan là bác sĩ phẫu thuật Baek Joo Hong, một người con gái thẳng tính và tốt bụng. Còn Nam Tae Hyung là một công tố viên với tính tình tự phụ, anh ta có một cuộc sống hoàn hảo, đầy đủ tiền bạc, tài năng và cả gia đình giàu có, nhưng lại luôn thua kém Woo Ji Hwan.</p>', 'Hoàn Tất (124/124)', 124, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo Ha-jun","avatar":""},{"name":"Lee Young-eun","avatar":""},{"name":"Kim Jeong-hoon","avatar":""},{"name":"Kang Byul","avatar":""},{"name":"Lee Seung-yun","avatar":""},{"name":"Yoon Bok-in","avatar":""},{"name":"Yoon A-jung","avatar":""},{"name":"Park Ye-rin","avatar":""},{"name":"Jang Hang-seon","avatar":""},{"name":"Park Choong-seon","avatar":""},{"name":"Kim Nan-hee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bimilui Jib","House of Secrets","비밀의 집","A Secret House","Дом с секретом","Sırlar Evi","Ngôi Nhà Bí Mật"]', 1784690324265);
