INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-cua-ho-ly-ban-thai', 'Mùa Hè Của Hồ Ly (Bản Thái)', 'You Are My Heartbeat', 'https://phimimg.com/upload/vod/20250224-1/f837c7ba0cc70fd3799f18cb74b0b935.jpg', 'https://phimimg.com/upload/vod/20250224-1/bd25985e3702a66d6a9e37c9f3478324.jpg', '<p>Bộ phim xoay quanh chuyện tình của Sira - Phó chủ tịch đẹp trai của tập đoàn GU - và nhà thiết kế xinh đẹp Kanghan. Sira là một người cực kỳ sạch sẽ ngăn nắp, ghét sự giả dối, trong khi đó Kanghan lại luộm thuộm và có tính cách trái ngược hoàn toàn với anh. Vì một số lý do, cả hai phải làm việc cùng nhau. Dần dần sự khác biệt giữa họ đã chuyển hóa thành tình yêu. Tuy nhiên, mối quan hệ này cũng gặp phải không ít trắc trở khi có sự xuất hiện của Din - người thừa kế quan trọng của tập đoàn GU, là em trai của Sira đồng thời là người yêu cũ Kanghan. Chuyện tình duyên dáng hài hước và lắm rắc rối này rồi sẽ ra sao?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Davika Hoorne","avatar":""},{"name":"Puttichai Kasetsin","avatar":""},{"name":"Jackrin Kungwankiatichai","avatar":""},{"name":"Carissa Springett","avatar":""},{"name":"Blue Pongtiwat Tan","avatar":""},{"name":"Thanakorn Chinakul","avatar":""},{"name":"Mintita Wattanakul","avatar":""},{"name":"Penpak Sirikul","avatar":""},{"name":"Gina Virahya Pattarachokchai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["泰版狐狸的夏天","Mr. Clean Heart Beat","Jangwa Hua Jai Nai Saat","You Are My Heartbeat","จังหวะหัวใจนายสะอาด"]', 1784690324265);
