INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pantheon-phan-1', 'Pantheon (Phần 1)', 'Pantheon (Season 1)', 'https://phimimg.com/upload/vod/20250224-1/6600c4ff1343fe062d311e33817e3ae7.jpg', 'https://phimimg.com/upload/vod/20250224-1/a74c8d9d65741dcdcf30903dbf2ed948.jpg', '<p>Một thiếu niên bị bắt nạt nhận được sự giúp đỡ bí ẩn từ một người trực tuyến: một người lạ hóa ra lại chính là cha của cô, David, người đã qua đời gần đây. Ý thức của ông đã được tải lên Đám mây sau một cuộc quét não thử nghiệm hủy diệt. David là người đầu tiên thuộc dạng tồn tại mới - &#39;Trí tuệ được Tải lên&#39; hay &#39;UI&#39; - nhưng ông không phải là người cuối cùng, khi một âm mưu toàn cầu được hé lộ đe dọa kích hoạt một loại chiến tranh thế giới mới.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Katie Chang","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Rosemarie DeWitt","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Taylor Schilling","avatar":""},{"name":"Ron Livingston","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Raza Jaffrey","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["パンテオン: デジタルの神々","Panteón","Пантеон","Pantheon"]', 1784690324265);
