INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-ut-nha-tai-phiet', 'Cậu Út Nhà Tài Phiệt', 'Reborn Rich', 'https://phimimg.com/upload/vod/20240324-1/3ce3d5fd3db995123087608e02a89660.jpg', 'https://phimimg.com/upload/vod/20240324-1/4ba08be654ca801d4c0461ebad5b0315.jpg', '<p>Được chuyển thể từ tiểu thuyết The Youngest Son of a Conglomerate, xoay quanh nhân vật Yoon Hyun Woo (Song Joong Ki), một thư ký của Tập đoàn Sunyang. Hyun Woo là một nhân viên trung thành, nhưng lại nhận kết cục thảm khốc bởi chính gia đình mà anh cúc cung tận tuỵ. Sau khi chết thảm, Yoon Hyun Woo sống lại một lần nữa dưới thân xác Jin Do Joon, con trai út của gia đình Sunyang Group. Mang hình hài của Jin Do Joon, Yoon Hyun Woo làm việc tiếp quản công ty cũng như bắt đầu màn trả thù của mình.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Hyun-bin","avatar":""},{"name":"Lee Sung Min","avatar":""},{"name":"Song Joong Ki","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324265);
