INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-vuong', 'Xà Vương', 'Deep Sea Mutant Snake', 'https://phimimg.com/upload/vod/20250219-1/33d90944e9102cc00bcf7521299d405e.jpg', 'https://phimimg.com/upload/vod/20250219-1/f23d6bf2cc707518d8081f92935222d1.jpg', '<p>Câu chuyện kể về việc vị hôn thê của Tần Vũ chết một cách bí ẩn khi điều tra Tập đoàn Cass. Để có thể làm chứng chống lại tập đoàn sinh học độc ác này tại tòa, Tần Vũ theo dõi Jason, người nắm giữ bằng chứng về tội ác của tập đoàn, lên tàu du lịch. Tuy nhiên, họ bất ngờ bị tấn công bởi đàn rắn biến dị và lạc vào hòn đảo nơi Tập đoàn Cass đang tiến hành các thí nghiệm bất hợp pháp. Môi trường sinh thái kỳ lạ của hòn đảo và cuộc tấn công của những con rắn khổng lồ lại càng đặt Tần Vũ và những người khác vào tình thế nguy hiểm chết người. Cuối cùng, họ cùng nhau vượt qua khó khăn và công khai tội ác của Tập đoàn Cass trước công chúng.&quot;</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Yixin","avatar":""},{"name":"Jacinda Li","avatar":""},{"name":"Qiu Shijian","avatar":""},{"name":"Jiang Yanxi","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Lopsang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Deep Sea Mutant Snake","Shen hai she nan","Cobra Mutante do Fundo do Mar","深海蛇难"]', 1784690324265);
