INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-rung-gia', 'Bí Ẩn Rừng Già', 'Crying Forest', 'https://phimimg.com/upload/vod/20250214-1/3e0fb89a0e43a5cb900140c47f4346e8.jpg', 'https://phimimg.com/upload/vod/20250214-1/d9aa6acca712816027e2ed5b22f9f2dd.jpg', '<p>Sáu người bạn, những người đã mất liên lạc với nhau, quyết định cùng nhau thực hiện một chuyến đi đến Rừng Mộng Khóc. Những sự kiện bí ẩn mà họ trải qua ở đó đảm bảo rằng họ sẽ không bao giờ quên cuộc hành trình trong rừng rậm này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 16, 2022, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Yadanar Bo","avatar":""},{"name":"Naw Phaw Eh Htar","avatar":""},{"name":"Shein Tin Htoo","avatar":""},{"name":"Aung Min Khant","avatar":""},{"name":"Shinn Myat","avatar":""},{"name":"Htut Myat Shwe Yi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["အိမ်မက်ငိုတော"]', 1784690324265);
