INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-ngo-tim-duoc-tinh-yeu-phan-2', 'Bất Ngờ Tìm Được Tình Yêu (Phần 2)', 'Assalamualaikum Calon Imam (Season 2)', 'https://phimimg.com/upload/vod/20250214-1/97ab7374fdd2f1bcb8d7eea4d53d257a.jpg', 'https://phimimg.com/upload/vod/20250214-1/16598526dd2fc2408006188a7d8173dd.jpg', '<p>Fisya, một sinh viên năng động, bất ngờ bị cuốn vào số phận phức tạp. Sau khi mất đi mối tình đầu, Fisya lại đính hôn với Alif, người thầy kế nhiệm của cô, người khá lạnh lùng. Nhưng hóa ra tình yêu lại đến theo cách họ không ngờ tới.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Miller Khan","avatar":""},{"name":"Mentari De Marelle","avatar":""},{"name":"Baskara Mahendra","avatar":""},{"name":"Kezia Aletheia","avatar":""},{"name":"Ray Sahetapy","avatar":""},{"name":"Dewi Irawan","avatar":""},{"name":"Lania Fira","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Assalamualaikum Calon Imam"]', 1784690324265);
