INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-luan-don-phan-2', 'Băng Đảng Luân Đôn (Phần 2)', 'Gangs Of London (Season 2)', 'https://phimimg.com/upload/vod/20250214-1/f47252bcd240261fe0b00ee0daf091ae.jpg', 'https://phimimg.com/upload/vod/20250214-1/1290191a4c7c4273b16c6861035fb88e.jpg', '<p>Phim kể câu chuyện về London bị xé nát bởi các cuộc đấu tranh quyền lực hỗn loạn của các băng đảng quốc tế và khoảng trống quyền lực bất ngờ được tạo ra khi người đứng đầu gia đình tội phạm quyền lực nhất London bị ám sát.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jasmine Armando","avatar":""},{"name":"Orli Shuka","avatar":""},{"name":"Sope Dirisu","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Lucian Msamati","avatar":""},{"name":"Michelle Fairley","avatar":""},{"name":"Narges Rashidi","avatar":""},{"name":"Brian Vernel","avatar":""},{"name":"Fady Elsayed","avatar":""},{"name":"Pippa Bennett-Warner","avatar":""},{"name":"Waleed Zuaiter","avatar":""},{"name":"Aymen Hamdouchi","avatar":""},{"name":"Asif Raza Mir","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Gangues de Londres","伦敦黑帮","Gangs of London"]', 1784690324265);
