INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-pham-toi-phan-2', 'Bằng Chứng Phạm Tội (Phần 2)', 'The Capture (Season 2)', 'https://phimimg.com/upload/vod/20250214-1/7f5b164fe2e854d920a4b64c7c3ed16a.jpg', 'https://phimimg.com/upload/vod/20250214-1/34e2c2cdb8936ef2359a566204ac4597.jpg', '<p><span style="text-wrap-mode: wrap;">Khi bản án giết người ở Afghanistan của người lính Shaun Emery bị hủy bỏ do bằng chứng video bị lỗi, anh trở về cuộc sống tự do với cô con gái nhỏ. Nhưng khi đoạn CCTV tố cáo từ một đêm ra ngoài ở London xuất hiện, cuộc đời của Shaun rẽ sang một hướng bất ngờ và anh phải một lần nữa chiến đấu để giành lại tự do.</span></p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Holliday Grainger","avatar":""},{"name":"Ben Miles","avatar":""},{"name":"Lia Williams","avatar":""},{"name":"Paapa Essiedu","avatar":""},{"name":"Indira Varma","avatar":""},{"name":"Charlie Murphy","avatar":""},{"name":"Tessa Wong","avatar":""},{"name":"Andy Nyman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["真相捕捉","The Capture","더 캡쳐","捕風捉影"]', 1784690324265);
