INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-giet-nguoi-o-thanh-pho-yellowstone', 'Vụ Giết Người Ở Thành Phố Yellowstone', 'Murder At Yellowstone City', 'https://phimimg.com/upload/vod/20250203-1/8ef743fe4463924a2dd87370b571375a.jpg', 'https://phimimg.com/upload/vod/20250203-1/9d9dcadd83241d36eaf1bc9e996b277c.jpg', '<p>Một cựu nô lệ đến thành phố Yellowstone, Montana, một cựu Boomtown hoang vắng hiện đang suy giảm, tìm kiếm một nơi để gọi về nhà. Cùng ngày hôm đó, một người tìm kiếm địa phương phát hiện ra vàng - và bị sát hại.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gabriel Byrne","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Isaiah Mustafa","avatar":""},{"name":"Anna Camp","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Aimee Garcia","avatar":""},{"name":"Zach McGowan","avatar":""},{"name":"Danny Bohnen","avatar":""},{"name":"Emma Kenney","avatar":""},{"name":"Scottie Thompson","avatar":""},{"name":"Isabella Ruby","avatar":""},{"name":"Tanaya Beatty","avatar":""},{"name":"Lia Marie Johnson","avatar":""},{"name":"Jenna Ciralli","avatar":""},{"name":"Kate Britton","avatar":""},{"name":"Emily Rasmuss","avatar":""},{"name":"Tim M","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Murder At Emigrant Gulch","Murder at Yellowstone City"]', 1784690324265);
