INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-canh-sat-cua-toi', 'Chàng Cảnh Sát Của Tôi', 'My Policeman', 'https://phimimg.com/upload/vod/20231125-1/9a1ef5f072ee54420d744c08c29eed60.jpg', 'https://phimimg.com/upload/vod/20231125-1/a33ebe398dba2777f5be0af40a4ac458.jpg', '<p>Một câu chuyện tuyệt đẹp về tình yêu bị ngăn cấm và những quy ước xã hội đang thay đổi, My Policeman theo chân ba người trẻ tuổi - cảnh sát Tom (Harry Styles), giáo viên Marion (Emma Corrin) và người phụ trách bảo tàng Patrick (David Dawson) - khi họ bắt tay vào một cuộc tình đầy cảm xúc hành trình vào những năm 1950 ở Anh. Bước qua những năm 1990, Tom (Linus Roache), Marion (Gina McKee) và Patrick (Rupert Everett) vẫn quay cuồng với khao khát và tiếc nuối, nhưng giờ đây họ có một cơ hội cuối cùng để sửa chữa những thiệt hại của quá khứ. Dựa trên cuốn sách của Bethan Roberts, đạo diễn Michael Grandage đã khắc họa một bức chân dung đầy trực quan, đau lòng về ba người bị cuốn vào dòng chảy của lịch sử, tự do và sự tha thứ.</p>', 'Full', 1, 'single', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Harry Styles","avatar":""},{"name":"Emma Corrin","avatar":""},{"name":"David Dawson","avatar":""},{"name":"Gina McKee","avatar":""},{"name":"Rupert Everett","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Kadiff Kirwan","avatar":""},{"name":"Dora Davis","avatar":""},{"name":"Andrew Tiernan","avatar":""},{"name":"Jack Bandeira","avatar":""},{"name":"Tristan Sturrock","avatar":""},{"name":"Ian Drysdale","avatar":""},{"name":"Richard Dempsey","avatar":""},{"name":"Maddie Rice","avatar":""},{"name":"Róisín Monaghan","avatar":""},{"name":"Sarah Lockett","avatar":""},{"name":"Paul Candelent","avatar":""},{"name":"Jose","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324265);
