INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-canh-tham-vong-phan-1', 'Đôi Cánh Tham Vọng (Phần 1)', 'As The Crow Flies (Season 1)', 'https://phimimg.com/upload/vod/20250122-1/5050b3f25ef02e6a4aa02b5f06b11c7c.jpg', 'https://phimimg.com/upload/vod/20250122-1/861f212dee5960a407bd07a4c2786f3e.jpg', '<p>Một người hâm mộ trẻ tìm cách vào phòng tin của một biên tập viên dày dạn nhưng nhanh chóng phải đối mặt với mặt tối của tham vọng, sự đố kị và khát khao được lên hình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2022, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Birce Akalay","avatar":""},{"name":"Miray Daner","avatar":""},{"name":"İbrahim Çelikkol","avatar":""},{"name":"Burak Yamantürk","avatar":""},{"name":"İrem Sak","avatar":""},{"name":"Defne Kayalar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324265);
