INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('40-ngay-yeu', '40 Ngày Yêu', 'Love In 40 Days', 'https://phimimg.com/upload/vod/20250121-1/bbe130aa831b2eaec521057464709d40.jpg', 'https://phimimg.com/upload/vod/20250121-1/fa35b5ffc8095efe89583f9936154caa.jpg', '<p>Cuộc sống bắt đầu ở thế giới bên kia đối với Jane, một nhân viên bảo hiểm gan dạ gặp phải cái chết tức tưởi trong vụ tai nạn xe cộ. Cô bỏ lại người em trai, những người thân ruột thịt và một vụ bảo hiểm mà cô đang điều tra trước khi chết. Linh hồn của Jane được ở lại thế giới người sống trong 40 ngày, cô quen với Edward họ đã cùng nhau trải qua những biến cố mới trên con đường tìm kiếm sự thật trong vụ tai nạn xe của Jane. Với một tình yêu được hun đúc bởi thế giới bên kia, liệu họ có thể sống sót qua nỗi kinh hoàng của cuộc sống thực?</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 14, 2022, 'Lồng Tiếng', 'FHD', 'Philippines', 0, '[{"name":"Loisa Andalio","avatar":""},{"name":"Ronnie Alonte","avatar":""},{"name":"Mylene Dizon","avatar":""},{"name":"Janice de Belen","avatar":""},{"name":"Lotlot De Leon","avatar":""},{"name":"Leo Martinez","avatar":""},{"name":"William Lorenzo","avatar":""},{"name":"Chie Filomeno","avatar":""},{"name":"Katrina Michelle Legaspi","avatar":""},{"name":"Renshi de Guzman","avatar":""},{"name":"Vaughn Piczon","avatar":""},{"name":"Zabel Lamberth","avatar":""},{"name":"Raven Molina","avatar":""},{"name":"Ana Abad Santos","avatar":""},{"name":"Benedix Ramos","avatar":""},{"name":"Andi Abaya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love in 40 Days"]', 1784690324265);
