INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tac-hoan-hao', 'Đối Tác Hoàn Hảo', 'Good Job', 'https://phimimg.com/upload/vod/20240215-1/aa02ec3e2834c5557441631b37438f16.jpg', 'https://phimimg.com/upload/vod/20240215-1/219293ec97e33fc8c54518d56db3743a.jpg', '<p>Bộ phim này nói về cuộc điều tra chung và câu chuyện lãng mạn của một chaebol sống cuộc đời thứ hai với tư cách là một thám tử và một người phụ nữ có tầm nhìn siêu phàm.Eun Sun Woo là một chaebol trong số các chaebol, người sở hữu tập đoàn Eunkang và cũng điều hành một công ty thám tử. Ngay từ khi còn nhỏ, Eun Sun Woo đã thể hiện một trí tuệ thông minh và khả năng thể thao vô song đáng kinh ngạc. Anh ta là một nhân vật hoàn toàn khác nhau trong hai cuộc đời làm thám tử và làm chủ tịch một tập đoàn, dễ dàng chuyển từ tự phụ sang trở thành một quý ông. Don Se Ra là một người vui vẻ, được sinh ra với siêu thị giác. Để che giấu sức mạnh của mình, Don Se Ra đi khắp nơi đeo một cặp kính dày để bí mật sử dụng khả năng của mình. Trong khi đảm nhận nhiều công việc lặt vặt để giúp đỡ những người xung quanh, cô gặp Eun Sun Woo và bắt đầu một câu chuyện tình yêu đầy hỗn loạn</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 17, 2022, 'Vietsub + Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Il Woo","avatar":""},{"name":"Jung Il Woo","avatar":""},{"name":"Eum Moon Suk","avatar":""},{"name":"Song Sang Eun","avatar":""},{"name":"Yoon Sun Woo","avatar":""},{"name":"Lee Joon Hyuk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324265);
