INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-phan-dien-bao-nuoi-trum-cuoi', 'Nữ Phản Diện Bao Nuôi Trùm Cuối', 'I''m The Villainess, So I''m Taming The Final Boss', 'https://phimimg.com/upload/vod/20250110-1/e2f4d59ca7594c3985b2e27136d1fd38.jpg', 'https://phimimg.com/upload/vod/20250110-1/2c6837ddc5cb9df6dc28821479653a50.jpg', '<p>&quot;Hôn ước của ta và cô chấm dứt từ đây&quot;

Hai chữ huỷ hôn bất ngờ xuất hiện trong buổi dạ tiệc hào nhoáng, Aileen Lauren Dautriche vì cú sốc đấy mà nhớ lại được tiền kiếp của bản thân, hiểu được tình trạng bản thân hiện tại. Đây là thế giới trong game otome mà Aileen cực kì yêu thích trong tiền kiếp của mình - &quot;Thánh kiếm, Ma vương và thiếu nữ vương giả&quot;.

Bản thân đóng vai trò là trở ngại trên con đường tình yêu của nữ chính, trở thành nhân vật phản diện Aileen. Theo ký ức của tiền kiếp, tương lai của Aileen chỉ ngập tràn route dẫn đến cái chết. Một trong những route dẫn đến cái chết có xuất hiện Ma Vương Claude Jeanne Elmir. Nếu gặp được Claude và biến anh ta thành người yêu, Aileen có thể tránh được route chết.

Aileen nghĩ vậy, tuyên bố với Ma vương diễm lệ: &quot;Ta muốn ngài kết hôn với ta&quot;.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rie Takahashi","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Toshiki Masuda","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Takuto Yoshinaga","avatar":""},{"name":"Shinichiro Kamio","avatar":""},{"name":"Yu Miyazaki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["作为恶役大小姐就该养魔王","Akuyaku Reijou Nanode Last Boss wo Katte Mimashita","AkuRasu","Akuyaku Reijō Nanode Last Boss wo Katte Mimashita","Akuyaku Reijou","Akuyaku Reijou nano de Last Boss wo Katte Mimashita","Я стала злодейкой, поэтому мне нужно охмурить последнего босса","Я стала злодейкой, поэтому мне нужно заарканить последнего босса","Akuyaku Reijou Nano De Last Boss O Katte Mimashita","悪役令嬢なのでラスボスを飼ってみました"]', 1784690324265);
