INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hen-song-con-phan-4', 'Cuộc Hẹn Sống Còn (Phần 4)', 'Date A Live (Season 4)', 'https://phimimg.com/upload/vod/20250106-1/7115ca21221969b2297657d5ec981bab.jpg', 'https://phimimg.com/upload/vod/20250106-1/7b66347042dda03451a18f63123dca29.jpg', '<p>Date A Live IV là phần anime thứ 4 chuyển thể từ light novel cùng tên do Koshi Tachibana sáng tác. Nhân vật chính của Date A Live là Shido, một chàng trai sở hữu khả năng đặc biệt có thể phong ấn các Tinh Linh - những cô gái có sức mạnh vô cùng khủng khiếp. Để kích hoạt phong ấn, Shido sẽ phải tiếp cận từng Tinh Linh và khiến họ yêu anh. Từ đây câu chuyện &quot;tán gái cứu thế giới&quot; hấp dẫn chính thức bắt đầu.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Misuzu Togashi","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Iori Nomizu","avatar":""},{"name":"Asami Sanada","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Sarah Emi Bridcutt","avatar":""},{"name":"Minori Chihara","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Takehito Koyasu","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["约会大作战","约战","デート・ア・ライブⅢ","Dēto A Raibu","デート・ア・ライブⅡ","デート・ア・ライブ IV","デート・ア・ライブⅣ","デート・ア・ライブⅤ","約會大作戰 DATE A LIVE 第四季","約會大作戰DATEALIVE第四季","Date a 