INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-tri-2022', 'Đấu Trí', 'Battle Of Wits', 'https://phimimg.com/upload/vod/20250105-1/a0f9485380e4f7d64136bd514469c615.jpg', 'https://phimimg.com/upload/vod/20250105-1/30b7ba3e9c2a14bdb17276a51a813577.jpg', '<p>Lê Anh Vũ (Thanh Sơn), một chiến sĩ cảnh sát kinh tế trẻ của tỉnh Đông Bình cùng các đồng nghiệp khác đã liên tục phải chịu những sức ép từ vụ Công ty Khải Tuấn đẩy giá sinh phẩm kit test cho đến vụ buôn lậu hàng trăm nghìn chiếc điện thoại di động tuồn qua biên giới của Công ty Thịnh Gia, Thái Lai mà hậu thuẫn không chỉ dừng lại ở một chi cục trưởng trong cơ quan bộ ngành. Ở cuộc chiến đầy cam go này, bên cạnh những người như Vũ, Phong (Xuân Phúc),... luôn kiên trì đứng vững, cũng đã có những trường hợp thiếu bản lĩnh, để rồi gục ngã trước &quot;viên đạn bọc đường&quot;..</p>', 'Hoàn Tất (74/74)', 74, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Trung Anh","avatar":""},{"name":"Thanh Sơn","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Lương Thu Trang","avatar":""},{"name":"Vĩnh Xương","avatar":""},{"name":"Trịnh Mai","avatar":""},{"name":"Nguyệt Hằng","avatar":""},{"name":"Xuân Phúc","avatar":""},{"name":"Hồng Quang","avatar":""},{"name":"Tô Dũng","avatar":""},{"name":"Phan Thắng","avatar":""},{"name":"Anh Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Анечка"]', 1784690324265);
