INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-tri-2022', 'Đấu Trí', 'Battle Of Wits', 'đấu trí battle of wits trung anh thanh sơn doãn quốc đam lương thu trang vĩnh xương trịnh mai nguyệt hằng xuân phúc hồng quang tô dũng phan thắng anh đào анечка', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lap-toi-do-giam-phan-1', 'Lạp Tội Đồ Giám (Phần 1)', 'Under The Skin (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/c0ac02a6c095f68c3d7cf8cd4c71e69b.jpg', 'https://phimimg.com/upload/vod/20231219-1/5fb06f94b9a13bffda1ae0d17c4f9368.jpg', '<p>Nhận lời mời của Cục trưởng Trương, Thẩm Dực gia nhập cục cảnh sát và dùng tài năng vẽ của mình để hỗ trợ phá án. Đội trưởng Đỗ Thành “bằng mặt không bằng lòng” vì Thẩm Dực từng vô tình khiến cho Lôi Nhất Phỉ, một cảnh sát nằm vùng và cũng là bạn thân của anh, phải bỏ mạng. Nhưng sau nhiều lần phá những vụ án tưởng chừng như rơi vào ngõ cụt, Thành dần dần công nhận tài năng của Thẩm Dực. Cả hai sau đó đã cùng nhau điều tra sự thật về cái chết của Lôi Nhất Phỉ.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đàn Kiện Thứ","avatar":""},{"name":"Kim Thế Giai","avatar":""},{"name":"Lục Nghiên Kỳ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324265);
