INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-dao-so-1-phan-1', 'Tiền Đạo Số 1 (Phần 1)', 'Blue Lock (Season 1)', 'https://phimimg.com/upload/vod/20250102-1/1bdb885de0d372dd58eeb9bf1f22d85b.jpg', 'https://phimimg.com/upload/vod/20250102-1/9393d319957a2cf6e6aa962da1432766.jpg', '<p>Năm 2018, Nhật Bản đã để thua top 16 tại World Cup, để chiêu mộ những “mũi tấn công” có thể phá vỡ thế bế tắc này, Liên đoàn bóng đá Nhật Bản đã quyết định áp dụng một kế hoạch táo bạo: triệu tập 300 học sinh trung học FW (tiền đạo) và xếp họ vào sân. dưới danh nghĩa &quot;những kẻ tấn công&quot; Luyện Gu trong ký túc xá của &quot;Blue Lock&quot;! Ngay cả khi tương lai 299 người sẽ hy sinh, một tiền đạo đẳng cấp thế giới độc nhất vô nhị phải được sinh ra! Một tiền đạo trung học vô danh, Jesse Il, cũng kiên quyết quyết định tham gia vào trận chiến sống còn này để loại bỏ tất cả các đối thủ!</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kazuki Ura","avatar":""},{"name":"Tasuku Kaito","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Soma Saito","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Blue Lock","蓝色禁区","ლურჯი ციხე","زندان آبی","قلعه آبی","ブルーロック VS. U-20 JAPAN","القفل الأزرق","Blue Lock ขังดวลแข้ง","BLUELOCK","ブルーロック"]', 1784690324265);
