INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-ca-phe-luat', 'Quán Cà Phê Luật', 'The Law Cafe', 'https://phimimg.com/upload/vod/20240403-1/37ec001f3b03e1486d0d964f196bb5da.jpg', 'https://phimimg.com/upload/vod/20240403-1/fb5f184bc809ccd0a34ebbaffd9ef097.jpg', '<p>Đó là câu chuyện tình lãng mạn giữa một cựu công tố viên trở thành chủ nhà mở quán cà phê / công ty luật lai với một cựu Hoa hậu Hàn Quốc.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Seung Ki","avatar":""},{"name":"Lee Se Young","avatar":""},{"name":"Jang Hye Jin","avatar":""},{"name":"Baek Hyun Joo","avatar":""},{"name":"Lee Min Young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324265);
