INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-vong-ruc-do', 'Tham Vọng Rực Đỏ', 'Red Balloon', 'https://phimimg.com/upload/vod/20240326-1/88377ba97c9383df366dc33517610c93.jpg', 'https://phimimg.com/upload/vod/20240326-1/df09ccb86551a66e5804b2a6d6bd4f6e.jpg', '<p>Dục vọng và lòng tham muốn đạt được mục đích của 4 con người ở 4 địa vị khác nhau trong cuộc sống. Jo Eun Kang (Seo Ji Hye đóng) chỉ đơn giản mong muốn trở thành giáo viên nhưng lại trượt kỳ thi giảng dạy. Bề ngoài Eun Kang có vẻ là một người bình tĩnh nhưng thực chất sâu bên trong, cô có những khao khát lớn và có thể làm bất cứ điều gì để đạt được nó. Eun Kang có mối quan hệ nguy hiểm, vượt giới hạn với Go Cha Won (Lee Sang Woo đóng) - chồng của bạn thân Han Ba Da (Hong Soo Hyun đóng). Dù đã làm bạn từ thời trung học nhưng vì xuất thân giàu có của Ba Da, Eun Kang luôn cảm thấy có sự khác biệt.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo Ji Hye","avatar":""},{"name":"Lee Sung Jae","avatar":""},{"name":"Lee Sang Woo","avatar":""},{"name":"Hong Soo Hyun","avatar":""},{"name":"Lee Bo Hee","avatar":""},{"name":"Jung Bo Suk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324265);
