INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sao-lai-la-oh-soo-jae', 'Tại Sao Lại Là Oh Soo Jae', 'Why Her', 'https://phimimg.com/upload/vod/20240418-1/c1f40ca80e6c40ffbe6ddbb12cb0b770.jpg', 'https://phimimg.com/upload/vod/20240418-1/2e2f7a9bb2747920d1c98e2ef39258ff.jpg', '<p>Oh Soo Jae ( Seo Hyun Jin ) là một luật sư tài năng và là cộng sự trẻ tuổi nhất tại Công ty Luật TK, công ty luật tốt nhất ở Hàn Quốc. Oh Soo Jae được thúc đẩy bởi mong muốn thắng kiện và cả những nguyên tắc tự cho mình là đúng. Cô ấy đã sống hết mình để đạt được thành công, nhưng cô ấy vướng vào một trường hợp bất ngờ và cô ấy bị giáng chức xuống làm trợ giảng tại một trường luật. Tại trường luật, Oh Soo Jae gặp Gong Chan ( Hwang In Yup ). Anh ấy là sinh viên ở đó. Gong Chan đã trải qua một quá khứ đau buồn, nhưng anh vẫn có một trái tim ấm áp. Anh ấy yêu Oh Soo Jae và anh ấy sẽ làm bất cứ điều gì cho cô ấy. Trong khi đó, Choi Tae Kook ( Heo Joon Ho ) là chủ tịch của Công ty Luật TK. Anh ta sẽ làm bất cứ điều gì để thỏa mãn ham muốn của mình, ngay cả khi điều đó là bất hợp pháp hay trái đạo đức.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo Hyun Jin","avatar":""},{"name":"Hwang In Yup","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324265);
