INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-trong-trang-oh-woo-ri', 'Cô Nàng Trong Trắng Oh Woo Ri', 'Woori The Virgin', 'https://phimimg.com/upload/vod/20240409-1/0206ab3b7514e76e69746dbe06a7d443.jpg', 'https://phimimg.com/upload/vod/20240409-1/6f5ac789f12eee9a194b722efa8ea47d.jpg', '<p>Oh Woo Ri luôn giữ mình trước khi kết hôn, nhưng cuối cùng cô lại mang thai đứa con của Raphael - CEO của một công ty lớn, sau sự cố trong một cuộc kiểm tra y tế. Kể từ đây, nhiều tình huống dở khóc, dở cười đã xảy đến với cô và Raphael. Phim được làm lại từ tác phẩm hài lãng mạn của Mỹ mang tên Jane the Virgin.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Sung Hoon","avatar":""},{"name":"Im Soo Hyang","avatar":""},{"name":"Shin Dong Wook","avatar":""},{"name":"Hong Ji Yoon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324265);
