INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-mau', 'Hạnh Phúc Máu', 'Blood Karma', 'https://phimimg.com/upload/vod/20241231-1/e2f8f134a50b2934fe850b4403eff318.jpg', 'https://phimimg.com/upload/vod/20230922-1/500439d3f96493940e856beca3401233.jpg', '<p><span style="font-family: ">Bộ phim kể về thảm kịch của gia đình Vương Đình, nơi người đứng đầu gia đình thường sử dụng ma thuật để kiểm soát các thành viên. Người mẹ, vì thói quen mạnh định, tôn trọng đàn ông và khinh thường phụ nữ, và sẵn sàng cho con trai mình mà không cần đến bất kỳ thủ đoạn nào. Dù phải trả giá cho những hành động của mình, đau đớn vì tội lỗi, nhưng sâu trong tâm hồn vẫn là tình mẫu tử thiêng liêng của một người mẹ, tình yêu vô điều kiện của mẹ.</span></p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Kim Xuân","avatar":""},{"name":"Phạm Minh Hữu Tiến","avatar":""},{"name":"Hữu Tài","avatar":""},{"name":"Lê Thiện","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Phạm Huỳnh Hữu Tài","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324265);
