INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ma-vuong-manh-nhat-lich-su-chuyen-sinh-thanh-dan-lang-a', 'Đại Ma Vương Mạnh Nhất Lịch Sử Chuyển Sinh Thành Dân Làng A', 'The Greatest Demon Lord Is Reborn as a Typical Nobody', 'https://phimimg.com/upload/vod/20241228-1/821343ced31eebb2e054d0ee7a7dd26b.jpg', 'https://phimimg.com/upload/vod/20241228-1/33f8ed023e60ca97c73c77e3492c2724.jpg', '<p>Trong tiền kiếp của mình, anh được biết đến với cái tên Chúa quỷ Varvatos, một người cai trị và sử dụng ma thuật toàn năng. Nhưng anh ta đang rất cô đơn sau sự mất mát của bạn bè và những người thân yêu của mình trong quá trình lên nắm quyền, vì vậy trong những giây phút hấp hối, Varvatos đã thi triển một câu thần chú chuyển sinh để anh ta có cơ hội thứ hai trở thành một chàng trai bình thường. Lúc đầu, có vẻ như điều đó sẽ thành công - anh ta tái sinh đến hàng nghìn năm sau với tư cách là dân làng Ard. Thật không may, những ký ức vẫn còn nguyên vẹn và anh ấy không biết đã mất đi bao nhiêu thứ trong khoảng thời gian không tồn tại, và có vẻ như điều đó sẽ khiến anh ấy phải trả giá bằng cuộc sống bình thường của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshinari Fukamachi","avatar":""},{"name":"Wakana Maruoka","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Ayaka Ohashi","avatar":""},{"name":"Mie Sonozaki","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Yuki Kaida","avatar":""},{"name":"Yui Ogura","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Kenta Miyake","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a