INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-xe-doi-phan-1', 'Biệt Đội Xe Dơi (Phần 1)', 'Batwheels (Season 1)', 'https://phimimg.com/upload/vod/20241224-1/f22ee64001db6af64dcf91e11592d741.jpg', 'https://phimimg.com/upload/vod/20241224-1/b2942db588f69786321897aa7037b128.jpg', '<p>Batwheels theo chân một đội chống tội phạm tài năng. Họ kết hợp với nhau để chống lại cái xấu, hóa giải các vụ án, và dọn dẹp các con phố của Gotham. Họ là Batwheels, một nhóm những phương tiện chống tội phạm ở thành phố Gotham.</p>', 'Hoàn Tất (36/36)', 36, 'hoathinh', 'completed', 9, 2022, 'Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Noah Kaye Bentley","avatar":""},{"name":"Jacob Bertrand","avatar":""},{"name":"Kimberly Brooks","avatar":""},{"name":"Madigan Kacmar","avatar":""},{"name":"Lilimar","avatar":""},{"name":"Mick Wingert","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Titus Blake","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["超级蝙蝠车","Meet the Batwheels","Batwheels: Holidays on Ice","Batwheels"]', 1784690324265);
