INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cot-ngu-phan-2', 'Cốt Ngữ (Phần 2)', 'Talking Bones (Season 2)', 'https://phimimg.com/upload/vod/20241220-1/ea6ff9da64173681af90c407b0dee5be.jpg', 'https://phimimg.com/upload/vod/20241220-1/528994cf4cc61d7acd56dc9fe03ec9a3.jpg', '<p>Câu chuyện xoay quanh Thượng Kiệt (Cao Nhân thủ vai), người đứng đầu đội điều tra tội phạm và Hạ Huỳnh (Trương Linh Tâm), một nhà khám nghiệm pháp y đam mê với công việc, thám tử Lý Học Khải (Thái Nghi Đạt) và cũng là một người tìm dấu vết giỏi, Tống Mễ (Ngô Ngạn Tư), một nhà phân tích ngây thơ và ngờ nghệch cùng với Anh Minh (Trương Gia Đỉnh), một tài phiệt thế hệ thứ hai đang làm công việc phân tích tâm lí tội phạm. Cả năm người bị xem là những thành phần đáng bỏ đi, nhưng khi tất cả lập thành một nhóm, thông qua làm việc chung và cống hiến hết mình, họ thành công trong việc giải quyết những vụ án mạng dị thường nhấ</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Linh Tâm","avatar":""},{"name":"Cao Nhất Nhân","avatar":""},{"name":"Thái Nghi Đạt","avatar":""},{"name":"Lý Hàn Lâm","avatar":""},{"name":"Giang An Thanh","avatar":""},{"name":"Triệu Nghĩa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["骨语","Talking Bones"]', 1784690324265);
