INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-tinh-2022', 'Thức Tỉnh', 'The Neuron Doctors', 'https://phimimg.com/upload/vod/20241219-1/0aa75b42934046f535f10fcb23bdcd35.jpg', 'https://phimimg.com/upload/vod/20241219-1/e4559f5991e58f5b672a9e7abd989390.jpg', '<p>Đinh Học Khôn, chủ nhiệm khoa nội thần kinh của bệnh viện số 9 bất ngờ qua đời, Đinh Viễn Chí con trai của một sinh viên y học phương Tây ưu tú đạng du học ở Thụy Sĩ xa xôi, cùng với Hàn Tây Lâm, một sinh viên Đông y đã nhiều năm ở nước ngoài trở về bệnh viện số 9, cùng điều tra sự thật của nguyên nhân tử vong. Quan điểm tinh thần của nhân viên y tế &quot;y gia nhân tâm&quot; của các nhà y tế thế hệ thứ ba của Trung Thanh, cũng như sự kiên trì và trưởng thành đã trải qua trong quá trình kết hợp văn hóa Đông y dược và Tây y.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"David Chour","avatar":""},{"name":"Wang Youjun","avatar":""},{"name":"Chen Haolan","avatar":""},{"name":"Zhang Zhijian","avatar":""},{"name":"Xu Yue","avatar":""},{"name":"Zhiwen Wang","avatar":""},{"name":"Jiang Shan","avatar":""},{"name":"Liu Jia","avatar":""},{"name":"Zhang Xilin","avatar":""},{"name":"Bi Yanjun","avatar":""},{"name":"Du Chun","avatar":""},{"name":"Wang Yuanke","avatar":""},{"name":"Zhang Jiading","avatar":""},{"name":"Wang Jiayu","avatar":""},{"name":"Liu Linger","avatar":""},{"name":"Zhao Simei","avatar":""},{"name":"Liang Jiatong","avatar":""},{"name":"Liu Yiyue","avatar":""},{"name":"Yu Xiao Rui","avatar":""},{"name":"He Yu","avatar":""},{"name":"Huo Ya Ming","avatar":""},{"name":"Guo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["神经家族","亲爱的神经","Shen Jing Jia Zu","Qin Ai De Shen Jing","Cu Xing Zhe","The Neurons","Dear Neurons","Nerve family","The Neuron Doctors","促醒者"]', 1784690324265);
