INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-goi-la-thu-hang-truong-trung-hoc-cua-toi', 'Cái Gọi Là Thứ Hạng Trường Trung Học Của Tôi', 'My So Called High School Rank', 'https://phimimg.com/upload/vod/20241211-1/969ae156ec8b87d9220da4a88d9d7cac.jpg', 'https://phimimg.com/upload/vod/20241211-1/3d5ff93f5382cc6d5b7c879a5ed5da1d.jpg', '<p>Bộ phim tài liệu về quá trình thực hiện cũng như những tác động của vở nhạc kịch có tên Xếp Hạng - vốn là tác phẩm của một trường trung học, lên đời sống xã hội Mỹ trong vấn đề gánh nặng kì vọng của phụ huynh đối với các em học sinh ngày nay.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kyle Holmes","avatar":""},{"name":"David Taylor Gomes","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["My So-Called High School Rank"]', 1784690324265);
