INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-thuc-giac-gap-lai-nhung-guong-mat-than-quen', 'Thanh Xuân Thức Giấc: Gặp Lại Những Gương Mặt Thân Quen', 'Spring Awakening: Those You''ve Known', 'https://phimimg.com/upload/vod/20241211-1/bea3e922f6ec86f2fbb976d9fe4bec36.jpg', 'https://phimimg.com/upload/vod/20241211-1/57e78b6d4517e21b27a303900db2f38a.jpg', '<p>Bộ phim tài liệu là cuộc hội ngộ của dàn diễn viên từng tham gia vở nhạc kịch &quot;Thanh xuân thức giấc&quot; gây tiếng vang lớn trên sân khấu kịch Broadway. Sau những thăng trầm cùng vở diễn, họ đã đi những con đường khác nhau, và nay trở lại để tái hiện vở kịch lần nữa.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jonathan Groff","avatar":""},{"name":"Lea Michele","avatar":""},{"name":"John Gallagher Jr.","avatar":""},{"name":"Lilli Cooper","avatar":""},{"name":"Skylar Astin","avatar":""},{"name":"Remy Zaken","avatar":""},{"name":"Gideon Glick","avatar":""},{"name":"Phoebe Strole","avatar":""},{"name":"Jonathan B. Wright","avatar":""},{"name":"Jennifer Damiano","avatar":""},{"name":"Brian Charles Johnson","avatar":""},{"name":"Christine Estabrook","avatar":""},{"name":"Stephen Spinella","avatar":""},{"name":"Tom Hulce","avatar":""},{"name":"Krysta Rodriguez","avatar":""},{"name":"Lauren P","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["O Despertar da Primavera: As Pessoas que Encontramos","Spring Awakening: Those You''ve Known"]', 1784690324265);
