INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-len-tieng-that-lon', 'Hãy Lên Tiếng Thật Lớn', 'Habla Loud', 'https://phimimg.com/upload/vod/20241210-1/1a412737666680b92389a84e463ba573.jpeg', 'https://phimimg.com/upload/vod/20241210-1/a167c17fa4fb34d269499484e5de4f68.jpg', '<p>Phim tài liệu ngắn quy tụ nhiều người Mỹ gốc Latinh để nói về những vấn đề nổi cộm trong đời sống của cộng đồng này tại nước Mỹ đương đại.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Residente","avatar":""},{"name":"Carla Morrison","avatar":""},{"name":"Wilson Cruz","avatar":""},{"name":"Isabella Gómez","avatar":""},{"name":"Olga Merediz","avatar":""},{"name":"Leila Cobo","avatar":""},{"name":"Natalie Diaz","avatar":""},{"name":"Nicolás Entel","avatar":""},{"name":"Bianca Marroquín","avatar":""},{"name":"Mickey Melendez","avatar":""},{"name":"Curly Velasquez","avatar":""},{"name":"Leonardo Nam","avatar":""},{"name":"Ritchie Torres","avatar":""},{"name":"Carmen Yulín Cruz","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Habla Loud"]', 1784690324265);
