INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loai-hoa-danh-vong', 'Loài Hoa Danh Vọng', 'Flower Of Lust', 'https://phimimg.com/upload/vod/20241203-1/6d104e3f81b82f364e458e42c55769d5.jpg', 'https://phimimg.com/upload/vod/20241203-1/d9a1345491f54fad67b7c4fa9d946399.jpg', '<p>Now, một cô gái dân tộc thiểu số, vô tình gặp gỡ và có tình cảm với gã doanh nhân bảnh trai Pi-Tool. Nghe lời ngon ngọt, Now đã trao thân cho anh ta. Ngay sau khi biết mình có thai, cô vội vàng lên Băng Cốc tìm Pi-Tool vào đúng ngày hôn lễ của anh ta và bị cô dâu Pen-Ny sỉ nhục thậm tệ, thậm chí truy sát ráo riết. Sau khi thoát chết, cuộc đời Nao bước vào một ngã rẽ mới với chuỗi ngày nung nấu ý định trả thù...</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pathompong Reonchaidee","avatar":""},{"name":"Thana Suthikamorn","avatar":""},{"name":"Punyaporn Poonpipat","avatar":""},{"name":"Chiranan Manochaem","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ร่านดอกงิ้ว","Raan 2021","Raan Dok Ngiew","ร่าน2021","Ran Dok Ngiew"]', 1784690324265);
