INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-dai-tro-lai', 'Chị Đại Trở Lại', 'Big Sister Returns', 'https://phimimg.com/upload/vod/20241203-1/0a3df1072252db30eb911a1f3f31a6b1.jpg', 'https://phimimg.com/upload/vod/20241203-1/cc23e538e08d48371d1cc60df4b8061c.jpg', '<p>“Chị Đại trở lại” là bộ phim mang đến một màu sắc cực kì mới lạ và hấp dẫn khi kết hợp giữa âm nhạc thay cho lời thoại, vũ đạo thay cho hành động, song song đó còn có dung hòa giữa các yếu tố thời trang, tâm lý, tình cảm gia đình, tình yêu học trò, …khắc họa cuộc sống học sinh cực kì nhiều màu sắc sinh động. Bên cạnh đó cũng khắc họa những góc khuất không ai có thể ngờ tới khi cứ mãi cho rằng học đường là nơi an toàn nhất cho thanh thiếu niên.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thiên An","avatar":""},{"name":"Bùi Tấn Hảo","avatar":""},{"name":"Tú Tri","avatar":""},{"name":"Lê Thu","avatar":""},{"name":"Dương Trí Nghĩa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cha Cha Cha"]', 1784690324265);
