INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-om-thu-hai', 'Cái Ôm Thứ Hai', 'My Way', 'https://phimimg.com/upload/vod/20241130-1/de9a9b184cb31667c2a59ccfded54a42.jpg', 'https://phimimg.com/upload/vod/20241130-1/57fc8e25e46945259497f50a9adfe64a.jpg', '<p>Vụ tự tử của người bạn thân Trình Như Anh đã gây ra những sóng gió trong cuộc sống của 4 người mẹ - Phương Nguyên, Kim Lộ, Vưu Tiểu Trúc và Đinh Mộc Mộc. Họ cả đời luôn đi tìm sự thật về cái chết của cô, phá vỡ cuộc sống ở nhà nội trợ. Phương Nguyên vì chồng là Lí Thành mắc khoản nợ khổng lồ, nên bất đắc dĩ phải bán nhà. Kim Lộ một người theo chủ nghĩa độc thân chuẩn bị thực hiện ước mơ nghề nghiệp của mình, thì bất ngờ lại mang thai và cha của đứa trẻ là bạn trai tạm thời. Luật sư Vưu Tiểu Trúc mong chồng cô kiếm được tiền để đổi nhà, nhưng nhiều lần bị từ chối, và mẹ chồng cô sinh con thứ hai. Giáo viên dạy piano Đinh Mộc Mộc dường như là một bà mẹ đơn thân, nhưng chồng cô và mẹ cô đang ở nước ngoài đột ngột xuất hiện. Bốn người mẹ đã dũng cảm đối mặt với những ngã rẽ và tìm ra định hướng ước mơ ban đầu của mình, đồng thời cùng nhau làm sáng tỏ sự thật về cái chết của Trình Như Anh.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Shu","avatar":""},{"name":"Zhou Fang","avatar":""},{"name":"Zhang Xinyi","avatar":""},{"name":"Ma Su","avatar":""},{"name":"Du Chun","avatar":""},{"name":"Li Naiwen","avatar":""},{"name":"Zhao Xiaosu","avatar":""},{"name":"Mao Yi","avatar":""},{"name":"Zhao Da","avatar":""},{"name":"Zhao Ziqi","avatar":""},{"name":"Li Yuanyuan","avatar":""},{"name":"Zhang Baijia","avatar":""},{"name":"Zhang Qiaoer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["强大的妈妈","我的名字","My Way","My Way 2022","第二次拥抱"]', 1784690324265);
