INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kisaragi-nha-ga-nuot-chung', 'Kisaragi: Nhà Ga Nuốt Chửng', 'Kisaragi Station', 'https://phimimg.com/upload/vod/20241122-1/ad9d6ea52153bdf41a79bdd5b5478b91.jpg', 'https://phimimg.com/upload/vod/20241122-1/0bbb60cb9c5ab8ce7d564f29b5c1e4c4.jpg', '<p>Haruna Tsunematsu (Yuri Tsunematsu) đang học nghiên cứu về chuyên ngành văn hoá dân gian tại trường đại học. Cô quyết định lựa chọn truyền thuyết đô thị nổi tiếng là “Nhà ga Kisagari” để làm luận văn tốt nghiệp. Đây là câu chuyện rùng rợn từng được lưu truyền và khuấy đảo cộng động mạng vào năm 2004. Trong suốt quá trình thu thập tài liệu, Haruma gặp một người phụ nữ có tên là Junko Hayama (Eriko Sato). Nhiều lời đồn cho rằng, Junko chính là người đã đăng câu chuyện trên lên mạng với tên gọi “Hasumi”. Junko kể cho Haruna rằng cô đã lưu lạc tới một thế giới khác, và điều đó đã dẫn Haruna tới ga tàu Kisaragi - khởi nguồn của truyền thuyết đô thị rùng rợn năm xưa…</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuri Tsunematsu","avatar":""},{"name":"Eriko Sato","avatar":""},{"name":"Miyu Honda","avatar":""},{"name":"Riko","avatar":""},{"name":"Raiga Terasaka","avatar":""},{"name":"Rui Kihara","avatar":""},{"name":"Tateto Serizawa","avatar":""},{"name":"Taki Nanami","avatar":""},{"name":"Yui Segizawa","avatar":""},{"name":"Masahiro Noguchi","avatar":""},{"name":"Mamoru Tsubouchi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Kisaragi Station","Kisaragi Eki","きさらぎえき","きさらぎ駅"]', 1784690324265);
