INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kisaragi-nha-ga-nuot-chung', 'Kisaragi: Nhà Ga Nuốt Chửng', 'Kisaragi Station', 'kisaragi: nhà ga nuốt chửng kisaragi station yuri tsunematsu eriko sato miyu honda riko raiga terasaka rui kihara tateto serizawa taki nanami yui segizawa masahiro noguchi mamoru tsubouchi kisaragi station kisaragi eki きさらぎえき きさらぎ駅', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-lao-xac-song', 'Cù Lao Xác Sống', 'Lost In Mekong Delta', 'https://phimimg.com/upload/vod/20241121-1/a9ab75f9f717f64ef168fb2363238729.jpg', 'https://phimimg.com/upload/vod/20241121-1/ea578f7b02391a397cf03e8b030453ba.jpg', '<p>Phim nói về hành trình của một nhóm người cùng nhau sinh tồn và cố gắng thoát khỏi sự truy đuổi của xác sống để đến chuyến phà cuối cùng tại một cù lao trên vùng hạ lưu sông Mekong khi đại dịch xác sống bùng nổ. Công - một thầy thuốc đông y nhưng đã mất đi niềm tin vào tình người, quyết định đưa cha mình và con gái tìm đường rời đi. Trong quá trình chạy trốn, họ thất lạc nhau, Công hoang mang đi tìm đứa con gái rồi vô tình gặp được một gia đình hiền lành, hai chàng trai ma lanh, đôi bạn trẻ lương thiện và một người đàn ông có trái tim dũng cảm. Họ cùng nhau hợp sức thành một nhóm chống trả để giành giật sự sống. Đúng lúc này, sự tị hiềm, tham lam, ích kỷ của lòng người nảy sinh và lại đẩy họ vào những thử thách sống còn. Liệu hành trình của nhóm người này sẽ đi về đâu khi đại dịch càng ngày càng lan rộng?</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Huỳnh Đông","avatar":""},{"name":"Ốc Thanh Vân","avatar":""},{"name":"Trần Phong","avatar":""},{"name":"Loc Le","avatar":""},{"name":"La Thành","avatar":""},{"name":"Xuân Nghị","avatar":""},{"name":"Hoàng Mèo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["僵尸岛","Cù Lao Xác Sống"]', 1784690324265);
