INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cu-lao-xac-song', 'Cù Lao Xác Sống', 'Lost In Mekong Delta', 'cù lao xác sống lost in mekong delta huỳnh đông ốc thanh vân trần phong loc le la thành xuân nghị hoàng mèo 僵尸岛 cù lao xác sống', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-y', 'Cuộc Chiến Y', 'War Of Y', 'https://phimimg.com/upload/vod/20241118-1/a8f987f79e18b117a1ca206e63cc948d.jpg', 'https://phimimg.com/upload/vod/20241118-1/a77236358a72268561ff139064432f62.jpg', '<p>War of Y được chia thành bốn câu chuyện về những cuộc đấu tranh trong ngành giải trí. Câu chuyện 1- Con tàu mới Trước con tàu, mọi chuyện không hề dễ dàng. Nhưng thời đại mới này thậm chí còn khó khăn hơn. Chuyện 2 - Cuộc Chiến Của Các Nhà Quản Lý Câu chuyện về một cặp vợ chồng chuyển tàu vốn là một cặp đôi thực sự. Quản lý và kịch xung đột cho đến khi cặp đôi buộc phải chia tay. Câu chuyện 3 - Y-Idol Một cuộc tìm kiếm thực tế các diễn viên mới—những người có thể hát, nhảy và diễn xuất—và sự hỗn loạn của Idol Camp. Câu chuyện 4 - Vợ Khi một nửa của cặp vợ chồng tàu biển có vợ, liệu tương lai của họ trong ngành này có bị hủy hoại?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["耽圈乱战","War Of Y The Series","วอร์ออฟวาย"]', 1784690324265);
