INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arifureta-tu-tam-thuong-den-bat-kha-chien-bai-phan-2', 'Arifureta: Từ Tầm Thường Đến Bất Khả Chiến Bại (Phần 2)', 'Arifureta: From Commonplace To World''s Strongest (Season 2)', 'https://phimimg.com/upload/vod/20240403-1/5e289b186eaafd6188b72c4410ffad04.jpg', 'https://phimimg.com/upload/vod/20240403-1/59207f0d89e1a7950209219960dcb2cd.jpg', '<p>Nagumo Hajime là một đứa bị bắt nạt trong trường, cùng với bạn học cùng lớp bị triệu hồi thế giới khác. Mặc dù các bạn học lần lượt được ban cho siêu năng lực chiến đấu đặc biệt, nhưng Hajime chỉ được năng lực tầm thường của biến đổi sư. Hơn nữa, chàng đã yếu đuối nhất trong thế giới khác, lại bị bạn học đẩy rơi vào vực sâu mê cung!? Dưới vực sâu tuyệt vọng không tìm được biện pháp gì thoát khỏi, Hajime gặp gỡ quỷ hút máu Uki và lên đường trở thành người mạnh nhất thế giới với tư cách biến đổi sư...</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324265);
