INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('arifureta-tu-tam-thuong-den-bat-kha-chien-bai-phan-2', 'Arifureta: Từ Tầm Thường Đến Bất Khả Chiến Bại (Phần 2)', 'Arifureta: From Commonplace To World''s Strongest (Season 2)', 'arifureta: từ tầm thường đến bất khả chiến bại (phần 2) arifureta: from commonplace to world''s strongest (season 2)  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-vao-the-gioi-game-phan-4', 'Lạc Vào Thế Giới Game (Phần 4)', 'Overlord (Season 4)', 'https://phimimg.com/upload/vod/20241116-1/5e572ab28bda50d879eb6430cdb64dfc.jpg', 'https://phimimg.com/upload/vod/20241116-1/5fe259f2ead7489d6025bf9451339127.jpg', '<p>Bộ phim lấy bối cảnh năm 2138 khi con người không còn phân biệt được đâu là thực đâu là ảo được nữa. Yggdrasil, một trò chơi trực tuyến nổi tiếng đã âm thầm bị đóng cửa trong quá khứ. Tuy nhiên một top-player tên Momonga đã quyết định sống chết cùng với trò chơi này và sau đó hắn đã trở thành một tên Cốt Bạch Hắc Ma có sức mạnh lớn nhất trong trò chơi này. Thế giới dần đổi thay, cho đến khi các NPC dần dần có cảm xúc của một con người. Không gia đình, không bạn bè, không việc làm hay chỗ đứng trong xã hội, hắn quyết định chiếm lấy thế giới này cho riêng mình.</p>', 'Hoàn Tất (13/13)', 56, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Satoshi Hino","avatar":""},{"name":"Yumi Hara","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Manami Numakura","avatar":""},{"name":"Akeno Watanabe","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Emiri Kato","avatar":""},{"name":"Yumi Uchiyama","avatar":""},{"name":"Masayuki Katou","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Hiromi Igarashi","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Kei Shindo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong"