INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lac-vao-the-gioi-game-phan-4', 'Lạc Vào Thế Giới Game (Phần 4)', 'Overlord (Season 4)', 'lạc vào thế giới game (phần 4) overlord (season 4) satoshi hino yumi hara sumire uesaka manami numakura akeno watanabe aoi yuki ayumu murase ayane sakura emiri kato yumi uchiyama masayuki katou kenta miyake hiromi igarashi mikako komatsu asami seto ayane sakura kei shindo 不死者之王 overlord ōbārōdo オーバーロードⅲ オーバーロードⅱ オーバーロード2 オーバーロード3 overlord ple ple pleiades soushuuhen overlord オーバーロードⅳ overlord повелитель властелин владыка повелитель 1 повелитель 4 повелитель 3 повелитель 2 โอเวอร์ลอร์ด оверлорд 3 оверлорд ⅲ оверлорд 2 оверлорд ⅱ оверлорд ii оверлорд iii оверлорд overlord 3 overlord ⅱ overlord ii overlord iii overlord ⅲ overlord 2 overlord iv lạc vào thế giới game オーバーロード', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xua-kia-co-ngoi-luu-ly', 'Xưa Kia Có Ngói Lưu Ly', 'Memory of Encaustic Tile', 'https://phimimg.com/upload/vod/20241113-1/9c4e359d4736e87e19e7b9030c483d1a.jpg', 'https://phimimg.com/upload/vod/20241113-1/f554a130b1b17d9433c4004437d79003.jpg', '<p>Xưa Có Ngói Lưu Ly - Memory Of Encaustic Tile kể về Thiếu Tuyết, Trịnh Tố Niên, Trường Kỳ là con của những nghệ nhân tu sửa văn vật Cố Cung, ba người cùng nhau trải qua thời kỳ dịch SARS, trưởng thành lớn lên trong con ngõ cũ kỹ ở Bắc Kinh. Ba đứa trẻ thanh mai trúc mã, cũng bởi vì cá tính khác biệt mà lựa chọn con đường hoàn toàn khác nhau. Thiếu Tuyết bị ảnh hưởng bởi mẹ của Tố Niên, không muốn vì tình yêu mà từ bỏ tương lai vô hạn của mình, lựa chọn con đường thả hương. Còn Tố Niên lựa chọn kế thừa chí nguyện của mẹ mình, tiếp quản sửa văn vật, cảm nhận thời gian từ các văn vật bất tử, như được tiếp thêm sức mạnh. Trường Kỳ với thiên phú toán học đã sớm được đi du học, đêm trước ngày đi du học, cậu lựa chọn giấu kín tình cảm với Thiếu Tuyết. Trịnh Tố Niên và Thiếu Tuyết đã xác nhận tâm ý của nhau, nhưng lúc Thế Vận Hội Olympic đang diễn ra thì 2 người chia tay. Trải qua nhiều năm sau, lúc quay về thì tất cả mọi người dường như đều có được cuộc sống tốt đẹp hơn.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yukee Chen","avatar":""},{"name":"Lin Yi","avatar":""},{"name":"Tian Ai","avatar":""},{"name":"Sun Kai","avatar":""},{"name":"Yan Zidong","avatar":""},{"name":"Yuan Ran","avatar":""},{"name":"Tang Xu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Воспоминания о черепице","昔有琉璃瓦","Xi You Liu Li Wa","Glazed Tiles in the Past"]', 1784690324265);
