INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-dem-den', 'Ác Mộng Đêm Đen', 'Nightsiren', 'https://phimimg.com/upload/vod/20241112-1/dc28964cca3d501557b43f6f687fae8c.jpg', 'https://phimimg.com/upload/vod/20241112-1/3a8944a77808f48f29079cbdb89b2ffe.jpg', '<p>Phim kể về một người phụ nữ trở về làng nơi cô lớn lên để tìm hiểu về thời thơ ấu đầy bất ổn của mình. Trong quá trình tìm kiếm sự thật, cô phải đối mặt với những hiện tượng siêu nhiên và bị người làng cáo buộc là phù thủy và giết người.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'FHD', 'Séc', 0, '[{"name":"Natalia Germani","avatar":""},{"name":"Eva Mores","avatar":""},{"name":"Juliana Oľhová","avatar":""},{"name":"Iva Bittová","avatar":""},{"name":"Jana Oľhová","avatar":""},{"name":"Marek Geišberg","avatar":""},{"name":"Zuzana Konečná","avatar":""},{"name":"Noël Czuczor","avatar":""},{"name":"Peter Ondrejička","avatar":""},{"name":"Matúš Ryšan","avatar":""},{"name":"Sára Tömölová","avatar":""},{"name":"Ela Stanová","avatar":""},{"name":"Petra Vajdová","avatar":""},{"name":"Timothy Hlinka","avatar":""},{"name":"Denis Polyák","avatar":""},{"name":"Milan Mikulčík","avatar":""},{"name":"Róbert Jakab","avatar":""},{"name":"Monik","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Svetlonoc"]', 1784690324265);
