INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-to-vien-chuyen-sinh', 'Công Tố Viên Chuyển Sinh', 'Again My Life', 'https://phimimg.com/upload/vod/20240326-1/eb18766331e8be78527dd318d0282471.jpg', 'https://phimimg.com/upload/vod/20240326-1/69f11b53acc62dadb3efdaa42910f681.jpg', '<p>Công tố viên Kim Hee Woo bị mưu sát khi cố điều tra vụ án tham nhũng của chính trị gia Jo Tae Seob. Biết được Hee Woo là người chính trực và nhiệt huyết, luôn đứng về phía kẻ yếu, thần chết đã trao cho anh cơ hội tái sinh bằng cách trở về 15 năm trước. Từ đây, Hee Woo nung nấu ý định trả thù cũng như đưa sự thật ra ánh sáng.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Joon Gi","avatar":""},{"name":"Lee Kyung Young","avatar":""},{"name":"Kim Ji Eun","avatar":""},{"name":"Cha Joo Young","avatar":""},{"name":"Jung Sang Hoon","avatar":""},{"name":"Kim Jae Kyung","avatar":""},{"name":"Park Chul Min","avatar":""},{"name":"Kim Hee Jung","avatar":""},{"name":"Kim Jin Woo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324265);
