INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-gia', 'Oan Gia', 'My Friend The Enemy', 'https://phimimg.com/upload/vod/20240419-1/9cf79adc4154f135d68ad14bd023adb0.jpg', 'https://phimimg.com/upload/vod/20240419-1/4e38a0b3c443b0e5fb10ee0acd0458ca.jpg', '<p>Trong Oan Gia (My Friend the Enemy) vietsub, Beam (Patricia Tanchanok Good) là một cô gái mạnh mẽ, tốt tính nhưng lại nóng nảy và quá thẳng thắn. Điều này đã khiến Beam thường xuyên gây ra chuyện. Trong khi Wan (Mo Monchanok Saengchaipiangpen) là một cô gái dịu dàng, khéo léo và luôn được đánh giá là người tốt. Nhưng thực chất, Wan lại mưu mô và hiếu thắng. Cả hai cùng vào làm tại một văn phòng luật và quen hai chàng trai: Nick (Pon Nawasch Phupantachsee), thông minh, lạnh lùng và Wayu (God Itthipat Thanit) đẹp trai, ấm áp. Từ đây, bốn người với bốn tính cách khác nhau bị cuốn vào vòng xoáy của cạnh tranh, hận thù... và có lẽ, cả tình yêu.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 8, 2022, 'Vietsub + Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Patricia Tanchanok Good","avatar":""},{"name":"Mo Monchanok Saengchaipiangpen","avatar":""},{"name":"Pon Nawasch Phupantachsee","avatar":""},{"name":"God Itthipat Thanit","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324265);
