INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sinh-2022', 'Tái Sinh', 'Rebirth', 'https://phimimg.com/upload/vod/20241104-1/14894bbb6844bc8ffda553e6fbe79ff2.jpg', 'https://phimimg.com/upload/vod/20241104-1/f3d350fc049f0ef049ec14264d5afeca.jpg', '<p>Để chuộc lỗi lầm, Bảo Ngọc, nữ sinh viên ngành y từng là F0, đăng ký trở thành chiến sĩ tuyến đầu chống dịch bất chấp sự phản đối của gia đình. Cùng sự giúp đỡ chuyên môn của đội trưởng Việt và các thành viên đội Truy Vết, Ngọc ngày một hoàn thiện, sẵn sàng chống chọi với đại dịch lịch sử.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Ngọc Xuân","avatar":""},{"name":"Thuận Nguyễn","avatar":""},{"name":"Việt Linh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["步步惊心 韩国版","月亮的恋人","Moon Lovers:scarlet Heart Ryeo","月之恋人","步步惊心","Corazon Escarlata","מאהבי הירח","レイ〜はなもゆるはちにんのおうじたち〜","麗＜レイ＞～花萌ゆる８人の皇子たち～","麗〜花萌ゆる8人の皇子たち〜","麗<レイ>〜花萌ゆる8人の皇子たち〜","Bobogyungsim: Ryeo","보보경심: 려","달의 연인 - 보보경심 려","Scarlet Heart","Алое сердце","ข้ามมิติ ลิขิตสวรรค์","月之戀人－步步驚心：麗","Закохані під місяцем: Багряні серця Рьо","Time Slip: Ryeo","Moon Lovers","Scarlet Heart: Goryeo","Moon Lovers: Scarlet Heart Ryeo"]', 1784690324265);
