INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-so-hai', 'Không Sợ Hãi', 'No Fear', 'https://phimimg.com/upload/vod/20241104-1/7e014d17f270c99dc1e6b39093a4a00e.jpg', 'https://phimimg.com/upload/vod/20241104-1/709f39cc53467af6d14ab935fe1c733b.jpg', '<p>Dịch COVID-19 tại TP Hồ Chí Minh bùng phát đỉnh điểm vào tháng 7 năm 2021 và cướp đi sinh mạng của hàng nghìn người. Tại tâm dịch, những &quot;anh hùng thầm lặng&quot; không ngại nguy hiểm, kêu gọi hỗ trợ và sẵn sàng giúp đỡ người bệnh và người đang mắc kẹt tại thành phố vì phong tỏa.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["السابق: حارس الكنز","Stealer-七个朝鲜通报","Karma: Seven Joseon Notices","Stealer: Seven Joseon Coins","تاوان: هفت هشدار چوسان","نتیجه عمل: هفت هشدار چوسان","카르마: 일곱 개의 조선통보","حاميها حراميها","스틸러: 일곱 개의 조선통보"]', 1784690324265);
