INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hem-tu-than', 'Hẻm Tử Thần', 'Death Alley', 'https://phimimg.com/upload/vod/20241104-1/7c3abb177f1fddc0fd34e2593bfb5ea7.jpg', 'https://phimimg.com/upload/vod/20241104-1/34975af5e880f1dbaf51bc0f113d56bf.jpg', '<p>Một con hẻm đầy tệ nạn như trộm cắp, đâm chém, kinh khủng đến mức nhiều người đã gọi nó là &quot;hẻm tử thần&quot;. Phim là hành trình của lực lượng cảnh sát trong việc nỗ lực cải tạo, với hy vọng mang lại ánh sáng cho nơi đây. Liệu những người từng lầm lỡ sẽ có cơ hội hoàn lương, được sống tích cực trong ánh sáng công lý?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Công Dũng","avatar":""},{"name":"Minh Thảo","avatar":""},{"name":"Đức Sơn","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["الصفقة","The Perfect Deal","Georae","Deal","거래"]', 1784690324265);
