INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-ngan-do-phan-2', 'Gái Ngàn Đô (Phần 2)', 'Thousand Dollar Girl (Season 2)', 'https://phimimg.com/upload/vod/20241104-1/c327a6bb70115589eea7ec830d343024.jpg', 'https://phimimg.com/upload/vod/20241104-1/4dcd688e6f089d046327b79a269896b6.jpg', '<p>Là nạn nhân trong những màn tranh gà cưng, giành địa bàn của những tên trùm sừng sỏ, tình thế của ba cô gái làng chơi đã khó nay càng khổ hơn khị bị hành hạ cả về thể xác lẫn tinh thần. Lối đi nào cho họ khi giờ nhan sắc của họ đều đã qua thời hoàng kim và có thể bị đào thải bất cứ lúc nào.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Đinh Ngọc Anh","avatar":""},{"name":"Phạm Bảo Anh","avatar":""},{"name":"Doãn Quốc Đam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gái Ngàn Đô"]', 1784690324265);
