INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tinh-chen-ngang', 'Cuộc Tình Chen Ngang', 'Us X Her', 'https://phimimg.com/upload/vod/20241102-1/d163513b763e6b918c99cd41e2fc20e9.jpg', 'https://phimimg.com/upload/vod/20241102-1/e126eb983753d2ddd232ac694ea5a20f.jpg', '<p>Cuộc hôn nhân đang lung lay của một cặp vợ chồng trẻ trở nên hỗn loạn hơn khi có một người phụ nữ khác xen vào. Nhưng chuyện gì sẽ xảy ra khi hai người phụ nữ yêu nhau?</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"AJ Raval","avatar":""},{"name":"Angeli Khang","avatar":""},{"name":"Kiko Estrada","avatar":""},{"name":"Bob Jbeili","avatar":""},{"name":"MJ Cayabyab","avatar":""},{"name":"Jiad Arroyo","avatar":""},{"name":"Kate Alejandrino","avatar":""},{"name":"Joanna Marie Katanyag","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Us X Her"]', 1784690324265);
