INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-tay-sung-huyen-thoai', 'Hai Tay Súng Huyền Thoại', 'A Tale of Two Guns', 'https://phimimg.com/upload/vod/20241031-1/3e1565d8a2563189b134aaee91c875f1.jpg', 'https://phimimg.com/upload/vod/20241031-1/a1ef1b1453b47be01dee96220c6c9d0c.jpg', '<p>Ở miền Tây vô luật pháp, The Cowboys, một hội anh em khét tiếng gồm những kẻ giết người và trộm cắp, thống trị vùng đất bằng những nắm đấm tàn bạo và những khẩu súng nhanh. Số phận cuối cùng đã bắt kịp họ và giờ đây băng đảng tàn nhẫn chỉ còn một thành viên duy nhất còn sống sót. Khi một tay súng được chỉ định thực hiện lời kêu gọi săn lùng Cowboy cuối cùng, cuộc rượt đuổi vẫn tiếp tục và đạn bay, và chỉ một trong số những người đàn ông cứng rắn này có thể sống sót.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dendrie Taylor","avatar":""},{"name":"Jennifer Wenger","avatar":""},{"name":"Griff Furst","avatar":""},{"name":"Edward Finlay","avatar":""},{"name":"Ed Morrone","avatar":""},{"name":"Randy Charach","avatar":""},{"name":"Daniel Luján","avatar":""},{"name":"Curt Lambert","avatar":""},{"name":"David Nett","avatar":""},{"name":"Tony A. Sims","avatar":""},{"name":"Jeff Dean","avatar":""},{"name":"Robert Amato","avatar":""},{"name":"Dan Koenig","avatar":""},{"name":"Troy Coleman","avatar":""},{"name":"Brian Cunningham","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Casper Van Dien","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["A Tale of Two Guns"]', 1784690324265);
