INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-tan-ruc-ro', 'Tro tàn rực rỡ', 'Glorious Ashes', 'https://phimimg.com/upload/vod/20241030-1/4243692c368c8207de3f49030c5e4cfd.jpg', 'https://phimimg.com/upload/vod/20241030-1/119d5d0c1beba051e428fa39e2ae98a3.jpg', '<p>Lấy bối cảnh ở Thơm Rơm, một ngôi làng nghèo ven biển ở Cà Mau với nhiều chất liệu điện ảnh và văn hóa của một vùng quê sông nước miền Tây, bộ phim xoay quanh ba người phụ nữ, có cuộc sống tình yêu khác thường, kể câu chuyện về cách họ yêu và tìm cách giữ người đàn ông của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Pháp', 1, '[{"name":"Lê Công Hoàng","avatar":""},{"name":"Juliet Bảo Ngọc Doling","avatar":""},{"name":"Phương Anh Đào","avatar":""},{"name":"Ngô Quang Tuấn","avatar":""},{"name":"Ngô Phạm Hạnh Thúy","avatar":""},{"name":"Thạch Kim Long","avatar":""},{"name":"Nguyễn Thị Ngọc Hiệp","avatar":""},{"name":"Mai Thế Hiệp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Cendres Glorieuses","Tro Tàn Rực Rỡ"]', 1784690324266);
