INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hac-lau', 'Hoàng Hạc Lâu', 'Hoàng Hạc Lâu', 'https://phimimg.com/upload/vod/20241029-1/138025cdb1c719bf6b892058309b557a.jpg', 'https://phimimg.com/upload/vod/20241029-1/ee545ddd350fcd4e522b45b316f046ba.jpg', '<p>Toàn cảnh bộ phim là một bức tranh đẹp về làng quê Việt Nam vào những năm đầu thập niên 1950. Nội dung phim tập trung ca ngợi Chân - Thiện - Mỹ trong cuộc sống thời bấy giờ, ca ngợi những con người hiền lành lương thiện, dù gặp phải những hoàn cảnh khắc nghiệt khó khăn nhất, mà họ vẫn bình thản tìm cách vượt qua bằng chữ tâm chữ tình và bằng đạo lý làm người.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thuỳ Trang","avatar":""},{"name":"Ngân Quỳnh","avatar":""},{"name":"Quách Ngọc Ngoan","avatar":""},{"name":"Ngọc Lan","avatar":""},{"name":"Cao Minh Đạt","avatar":""},{"name":"Khánh Trinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Hoàng Hạc Lâu"]', 1784690324266);
