INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-thep-phan-5', 'Bằng Chứng Thép (Phần 5)', 'Forensic Heroes (Season 5)', 'https://phimimg.com/upload/vod/20240118-1/e9ff01341920776b2e327915ad694804.jpg', 'https://phimimg.com/upload/vod/20240118-1/b74b01a4925e98072c9cea5293b8b5c2.jpg', '<p>Ngay khi khởi động, <em>Bằng chứng thép 5</em> gây chú ý khi đánh dấu sự trở lại của Huỳnh Tông Trạch sau 4 năm vắng bóng trên màn ảnh TVB. Anh vào vai chuyên gia pháp chứng Từ Tinh Bách. Trang <em>Sohu</em> đánh giá tài tử có phần mở màn ấn tượng nhờ ngoại hình cuốn hút tuổi 41. Anh khiến khán giả thót tim trong khoảnh khắc bị một con bạch tuộc quấn lấy người ở phân cảnh lặn xuống biển để tìm chứng cứ phá án.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Bosco Won","avatar":""},{"name":"Benjamin Yuen","avatar":""},{"name":"Venus Wong","avatar":""},{"name":"Sisley Choi","avatar":""},{"name":"Tony Hung","avatar":""},{"name":"Jacky Cai","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324266);
