INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('609-cau-chuyen-truoc-khi-di-ngu', '609 Câu Chuyện Trước Khi Đi Ngủ', '609 Bedtime Story', 'https://phimimg.com/upload/vod/20241026-1/20f8cec4f2b274058458867c4e7ff338.jpg', 'https://phimimg.com/upload/vod/20241026-1/35badd0e0490baa642ec0b63c596d362.jpg', '<p>Đột nhiên có một chàng trai trẻ xuất hiện trên giường ngủ của Mum - một tay ăn chơi và cũng là chủ nhân căn phòng số 609. Cả hai phát sinh quan hệ nồng cháy ngay từ lần gặp đầu tiên. Nhưng đêm đó lại trở thành &quot;ngày cuối cùng&quot; của cuộc đời Dew. Sau đó kéo theo những sự việc kỳ lạ không thể giải thích nổi. Mum lựa chọn quên đi sự nhớ nhung về lần &quot;đụng chạm&quot; với Dew bằng cách quan hệ với các cô gái khác. Nhưng điều đó chỉ càng khiến anh thêm nhớ nhung chàng trai trẻ trong mộng mà thôi. Vì vậy anh cố gắng căng não để kết nối những sự kiện và đến cuối cùng cũng anh gặp được Dew - một chàng trai trẻ được gia đình đặt nhiều kì vọng, và rồi anh đã tìm ra sự thật về kẻ đã giết Dew đêm đó.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thitiwat Ritprasert","avatar":""},{"name":"ณธัช ศิริพงษ์ธร","avatar":""},{"name":"Pronpiphat Pattanasettanon","avatar":""},{"name":"Potae Watcharayu Suradet","avatar":""},{"name":"ทสร กลิ่นเนียม","avatar":""},{"name":"Tom Jakkrit Yompayorm","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["เบดไทม์สตอรี่"]', 1784690324266);
