INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-danh-tieng', 'Trò Chơi Danh Tiếng', 'The Fame Game', 'https://phimimg.com/upload/vod/20241023-1/58d6e2e72eb6b70cafcba9a924bac203.jpg', 'https://phimimg.com/upload/vod/20241023-1/2a97cc2437b4a333d1ef3dd3d36bbace.jpg', '<p>Khi nữ diễn viên nổi tiếng nhất Ấn Độ mất tích, cuộc tìm kiếm đã dần phá vỡ vỏ bọc hoàn mỹ của cuộc đời và gia đình cô, phơi bày những sự thật đau đớn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Madhuri Dixit","avatar":""},{"name":"Sanjay Kapoor","avatar":""},{"name":"Manav Kaul","avatar":""},{"name":"Suhasini Mulay","avatar":""},{"name":"Lakshvir Saran","avatar":""},{"name":"Muskkaan Jaferi","avatar":""},{"name":"Rajshri Deshpande","avatar":""},{"name":"Gagan Arora","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Το Παιχνίδι της Δόξας","Finding Anamika","The Fame Game"]', 1784690324266);
