INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-quyen-ru-chet-nguoi-2022', 'Sự Quyến Rũ Chết Người', 'The Warp Effect', 'https://phimimg.com/upload/vod/20241024-1/d51a548c82d5a88aa1b3acb597fdc448.jpg', 'https://phimimg.com/upload/vod/20241024-1/0aefd2a73b84fc16b108d549efdc39a1.jpg', '<p>Một cơn bão bất ngờ xuất hiện trên biển khiến thuyền của Tai Kong Chang vỡ tan, toàn bộ thủy thủ đoàn gặp nạn, duy chỉ mình anh sống sót. Được người dân ở ngôi làng nọ cứu sống và cưu mang, nhờ tài năng của mình mà anh đã được đại nhân Thanong để ý đến. Và cuộc gặp gỡ định mệnh này đã đưa cuộc đời Tai Kong đi theo một ngã rẽ mới.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thitipoom Techa-apaikhun","avatar":""},{"name":"ยงวรี อนิลบล","avatar":""},{"name":"Harit Cheewagaroon","avatar":""},{"name":"Ployshompoo Supasap","avatar":""},{"name":"Pavida Moriggi","avatar":""},{"name":"รัตท์ริชา ประภากิติ","avatar":""},{"name":"ภูวินทร์ ตั้งศักดิ์ยืน","avatar":""},{"name":"Chanunphat Kamolkiriluck","avatar":""},{"name":"ภูสิษฐ์ ดิษฐพิสิษฐ์","avatar":""},{"name":"Thinnaphan Tantui","avatar":""},{"name":"อาเชน ไอย์ดึน","avatar":""},{"name":"ภาคิน คุณาอนุวิทย์","avatar":""},{"name":"Jira Jaroent","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Warp Effect รูปลับรหัสวาร์ป","รูปลับรหัสวาร์ป"]', 1784690324266);
