INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-bien-xanh-ban-thai', 'Chuyện Tình Biển Xanh (Bản Thái)', 'The Myths Of The Andaman', 'https://phimimg.com/upload/vod/20240521-1/de78feb1f8920b4d667e453f095cfd78.jpg', 'https://phimimg.com/upload/vod/20240521-1/d0707124b68d538a95962b6b163228a5.jpg', '<p>Anda là công chúa của biển cả. Trên đường trốn chạy khỏi sự truy đuổi của Sinthu - vua của vùng biển phía Nam, nàng được anh chàng loài người Naren giúp đỡ. Cả hai dần có tình cảm và yêu thương nhau lúc nào không hay. Về phía Sinthu, tức giận vì không lấy được Anda làm vợ, hắn đã gây ra cuộc chiến đẫm máu, ép Anda một lần nữa phải trốn chạy khỏi thế giới loài người.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 9, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Golf Anuwat Choocherdratana","avatar":""},{"name":"Jean Gaewalin Sriwanna","avatar":""},{"name":"Malinee Adelaide Coates","avatar":""},{"name":"Kit Krit Amornchailerk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324266);
