INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thay-giong-noi-cua-em', 'Nghe Thấy Giọng Nói Của Em', 'Hello, My Noisy MP3', 'https://phimimg.com/upload/vod/20241019-1/fe19a41ed74207f7c098d370858e4ac3.jpg', 'https://phimimg.com/upload/vod/20241019-1/be58ce0b1118ec1044c51fa5b97fc2ab.jpg', '<p>Một máy MP3 cũ, khiến Triệu Mạn Nhi một ngôi sao gần 30 tuổi có thể giao tiếp với bản thân mình 11 năm trước thông qua các bản ghi âm. Khi cô nghĩ rằng cuối cùng mình có thể thay đổi cuộc sống tồi tệ hiện tại của bản thân nhưng không ngờ lại khiến bản thân trong quá khứ và hiện tại rơi vào khủng hoảng lớn hơn...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"張楚寒","avatar":""},{"name":"Zhang Kaitai","avatar":""},{"name":"Chen Ye Sheng","avatar":""},{"name":"He Ling Yao","avatar":""},{"name":"Yi Zhang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["صدای من را بشنو","سلام، ام‌پی‌تری پلیر پر سر و صدام","听见我的声音"]', 1784690324266);
