INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nghe-thay-giong-noi-cua-em', 'Nghe Thấy Giọng Nói Của Em', 'Hello, My Noisy MP3', 'nghe thấy giọng nói của em hello, my noisy mp3 張楚寒 zhang kaitai chen ye sheng he ling yao yi zhang صدای من را بشنو سلام، ام‌پی‌تری پلیر پر سر و صدام 听见我的声音', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-hoc-tinh-yeu-thu-9', 'Bài Học Tình Yêu Thứ 9', 'Lesson in Love', 'https://phimimg.com/upload/vod/20241019-1/7bb3fc6471cc8acb69ae175450f1ea00.jpg', 'https://phimimg.com/upload/vod/20241019-1/4152c42a2b18d8fabd796d1f545de4ae.jpg', '<p>Bộ phim này kể về một mối tình lãng mạn và cấm kỵ giữa giáo viên và học sinh trong khuôn viên trường. Nữ chính Hứa Vỹ Ninh đóng vai Trần Mạnh Quân, một giáo viên trung học dạy Trung văn, Trần Hạo Sâm đóng vai Trương Nhất Tường, một học sinh giỏi toán và khoa học thích gây rối, và ảnh đế Kim Chung đương nhiệm Tiết Sĩ Lăng đóng vai giám đốc học thuật ấm áp Lí Đại Vi. Tại một lễ hội vui vẻ trong khuôn viên trường, giáo viên Trung văn Trần Mạnh Quân (do Hứa Vỹ Ninh thủ vai) gục xuống ở một góc của khuôn viên trường, học sinh tài năng 17 tuổi Trương Nhất Tường (do Trần Hạo Sâm thủ vai) không thể tưởng tượng được mà nhìn con dao găm vào bụng cô, trên mặt là đau lòng và lo lắng, đứng trước mặt cô, thông qua buổi phát sóng trực tiếp mà cả thế giới đều có thể xem được, cô đã vô tình phát hiện ra mối quan hệ thầy trò cấm kỵ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"許瑋甯","avatar":""},{"name":"Edward Chen","avatar":""},{"name":"尹馨","avatar":""},{"name":"Simon Hsueh","avatar":""},{"name":"Chin-Lan Chang","avatar":""},{"name":"Wang Yu Ping","avatar":""},{"name":"Kota Kagami","avatar":""},{"name":"Jackson Yang","avatar":""},{"name":"Yuto Lin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["บทเรียนรักต้องห้าม","第九節課","The 9th Period","第9節課"]', 1784690324266);
