INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bai-hoc-tinh-yeu-thu-9', 'Bài Học Tình Yêu Thứ 9', 'Lesson in Love', 'bài học tình yêu thứ 9 lesson in love 許瑋甯 edward chen 尹馨 simon hsueh chin-lan chang wang yu ping kota kagami jackson yang yuto lin บทเรียนรักต้องห้าม 第九節課 the 9th period 第9節課', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-he-nhi-phan', 'Tình Yêu Hệ Nhị Phân', 'Binary Love', 'https://phimimg.com/upload/vod/20241019-1/8bab2def8364d14361c6dfee84702658.jpg', 'https://phimimg.com/upload/vod/20241019-1/c191e03ca6da3aabbbd5f12db7092d84.jpg', '<p>Phim kể về câu chuyện tình yêu ngọt ngào và đan xen những nỗi buồn giữa Châu Lâm Lâm một học sinh kém và cô hàng xóm học bá Phương Dư Khả. Vốn dĩ cho rằng sau khi kết thúc kì thi Đại học thì hai người mỗi người một nơi, nhưng không ngờ hai người họ cùng trúng tuyển vào khoa Chăn nuôi của trường đại học nổi tếng. Để bù đắp &quot;tổn thương&quot; mà anh đã vô tình gây ra cho Phương Dư Khả, Châu Lâm Lâm đã làm mọi cách để theo đuổi lại &quot;mối tình đầu&quot;, nhưng anh lại vô tình rơi vào cạm bẫy của tuổi trẻ. Mùa tốt nghiệp sắp đến, liệu rằng người luôn trong tâm trí bạn, người bạn luôn theo đuổi quan tâm thời thanh xuân sẽ mãi bên bạn không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"任宥纶","avatar":""},{"name":"Zhuang Dafei","avatar":""},{"name":"Qu Qin Han","avatar":""},{"name":"刘宇航","avatar":""},{"name":"阳兵卓","avatar":""},{"name":"刘书源","avatar":""},{"name":"吴逸迦","avatar":""},{"name":"李依蒙","avatar":""},{"name":"Hu Jiaxin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Amor Binario","สูตรรักเลขฐานสอง","二進制戀愛","Binary Love","二进制恋爱"]', 1784690324266);
