INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-mat-na-dau-truong-tham-vong', 'Hiệp Sĩ Mặt Nạ: Đấu Trường Tham Vọng', 'Kamen Rider: Geats', 'https://phimimg.com/upload/vod/20241013-1/c06352fe1d936de3abcd1eade80d648d.jpg', 'https://phimimg.com/upload/vod/20241013-1/d5ec292d0d52fca910dcbb5181dbe0f4.jpg', '<p>Sau khi được tuyển chọn gắt gao bởi một thế lực bí ẩn, một nhóm người chơi buộc phải biến thành Kamen Rider và tham gia một giải đấu sinh tồn khắc nghiệt để bảo vệ người dân khỏi lũ quái vật xâm lược. Người chiến thắng cuối cùng sẽ có thể biến bất kì điều ước nào thành sự thật, còn những người thua cuộc sẽ bị tan biến khỏi thế giới hoặc bị tẩy não. Tổ chức đứng sau trò chơi này là ai và mục đích thật sự của họ là gì?</p>', 'Hoàn Tất (49/49)', 49, 'hoathinh', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hideyoshi Kan","avatar":""},{"name":"Ryuga Sato","avatar":""},{"name":"Yuna Hoshino","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["假面骑士Geats","Reiwa Rider 4","Masked Rider Geats","仮面ライダーギーツ"]', 1784690324266);
