INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-trong-nhung-nha-tu-khoc-liet-nhat-the-gioi-phan-6', 'Bên Trong Những Nhà Tù Khốc Liệt Nhất Thế Giới (Phần 6)', 'Inside The World''s Toughest Prisons (Season 6)', 'https://phimimg.com/upload/vod/20241011-1/76fa5751af72ee82d375f5124cd2c867.jpg', 'https://phimimg.com/upload/vod/20241011-1/468a03a789a4533e38a058f43757efb5.jpg', '<p>Từng là tù nhân bị kết án oan, Raphael Rowe tiếp tục điều tra những nhà tù kinh khủng ở Bosnia và Herzegovina, Cộng hòa Síp, Hi Lạp và Moldova.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Paul Connolly","avatar":""},{"name":"Raphael Rowe","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["深入世界最艰苦的监狱","最凶监狱大揭秘","深入全球最难熬的监狱","Inside the World''s Toughest Prisons"]', 1784690324266);
