INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ben-trong-nhung-nha-tu-khoc-liet-nhat-the-gioi-phan-6', 'Bên Trong Những Nhà Tù Khốc Liệt Nhất Thế Giới (Phần 6)', 'Inside The World''s Toughest Prisons (Season 6)', 'bên trong những nhà tù khốc liệt nhất thế giới (phần 6) inside the world''s toughest prisons (season 6) paul connolly raphael rowe 深入世界最艰苦的监狱 最凶监狱大揭秘 深入全球最难熬的监狱 inside the world''s toughest prisons', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-bat-nghi-phan-2', 'Lưỡng Bất Nghi (Phần 2)', 'No Doubt in Us (Season 2)', 'https://phimimg.com/upload/vod/20241011-1/6611b647c6e406a86f6b0d234ba74209.jpg', 'https://phimimg.com/upload/vod/20241011-1/f342751a6125f9a7923c4f482a2d315e.jpg', '<p>Lưỡng Bất Nghi kể về hoàng hậu xuất thân nhà quan võ, không giỏi cầm kỳ thi hoạ nhưng binh võ lại không thua ai. Nàng bước vào hoàng cung bị vua lạnh nhạt nhiều năm, chịu đủ loại uất ức. Nhưng đến một ngày, tai nạn nhỏ xảy ra, nàng phát hiện... Mình bị đổi thân thể với Hoàng thượng rồi!!! Sau khi đổi thân thể, hoàng hậu giúp hoàng thượng thượng triều, xuất binh đánh trận. Hoàng thượng giúp nàng quản lý hậu cung, mọi hiểu lầm dần được xoá bỏ. Đế hậu thân mật hơn xưa.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"徐佳琦","avatar":""},{"name":"張傑","avatar":""},{"name":"Su Shangqing","avatar":""},{"name":"李詩萌","avatar":""},{"name":"金弦","avatar":""},{"name":"Qian Chen","avatar":""},{"name":"杨天翔","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"劉琮","avatar":""},{"name":"Yitong Zhao","avatar":""},{"name":"Sun Lulu","avatar":""},{"name":"谷江山","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Liang Bu Yi","No Doubt In Us","两不疑"]', 1784690324266);
