INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luong-bat-nghi-phan-2', 'Lưỡng Bất Nghi (Phần 2)', 'No Doubt in Us (Season 2)', 'lưỡng bất nghi (phần 2) no doubt in us (season 2) 徐佳琦 張傑 su shangqing 李詩萌 金弦 qian chen 杨天翔 guo haoran 劉琮 yitong zhao sun lulu 谷江山 liang bu yi no doubt in us 两不疑', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-tru-ta', 'Thiên Sư Trừ Tà', 'The Exorcist', 'https://phimimg.com/upload/vod/20241009-1/ddfe48c3d56db958153ba5a0ad9910ec.jpg', 'https://phimimg.com/upload/vod/20241009-1/d4201624f43eddeee4c597f6bfe05351.jpg', '<p>Phim kể về câu chuyện của thần trừ tà Lâm Thiên sư và người học trò Lưu Nhất Trạch, với tấm lòng hướng thiện, không ngại gian khổ và nguy hiểm, cuối cùng đã khuất phục được yêu quái để cứu người dân. Quá trình hàng phục con quỷ hồ ly muốn dạy mọi người thoát khỏi mê tín dị đoan, không bị che mắt bởi những khái niệm thế tục trước đó và biết phân biệt thiện và ác.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"錢小豪","avatar":""},{"name":"于小彬","avatar":""},{"name":"Chen Yeling","avatar":""},{"name":"贾笑涵","avatar":""},{"name":"Gao Weiman","avatar":""},{"name":"He Xinzhu","avatar":""},{"name":"Lai Xiaosheng","avatar":""},{"name":"Jin Ziyan","avatar":""},{"name":"Li Xiong","avatar":""},{"name":"Zhang Haifeng","avatar":""},{"name":"Wei Jinsong","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"Wang Jiaqiang","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["The Exorcist","驱魔天师"]', 1784690324266);
