INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hanh-trinh-tuyet-voi-phan-5', 'Cuộc Hành Trình Tuyệt Vời (Phần 5)', 'The Grand Tour (Season 5)', 'https://phimimg.com/upload/vod/20241008-1/2c92098bbb3a058e872633949ef37f61.jpg', 'https://phimimg.com/upload/vod/20241008-1/2277716032e3d64de41d766f111abd20.jpg', '<p>Sau loạt phim đầu tiên, các phân đoạn trường quay của chương trình được quay vĩnh viễn tại Cotswolds. Ngoài ra, những người nổi tiếng đã tham gia đầy đủ hơn vào chương trình so với sự xuất hiện nhỏ mà họ có trong loạt phim trước, tham gia vào một phân đoạn đặc biệt được sử dụng trong phần này chỉ liên quan đến các vòng đối đầu có tính thời gian giữa hai khách mời trong mỗi tập, ngoại trừ của tập cuối cùng là một tập đặc biệt.</p>', 'Hoàn Tất (3/3)', 3, 'tvshows', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jeremy Clarkson","avatar":""},{"name":"Richard Hammond","avatar":""},{"name":"James May","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Гранд тур","伟大的旅程","大世界之旅","歌朗途","The Grand Tour","เดอะแกรนด์ทัวร์","Grand Tour, The"]', 1784690324266);
