INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-tu-la-bat-tu', 'Địch Nhân Kiệt: Tu La Bất Tử', 'Di Ren Jie: Zhi Bu Si Xiu Luo', 'https://phimimg.com/upload/vod/20241007-1/96c0775e111a3397277d1208c8787083.jpg', 'https://phimimg.com/upload/vod/20241007-1/091c54682c253385b2aac23d31aea88c.jpg', '<p>Địch Nhân Kiệt: Tu La Bất Tử kể về Địch Nhân Kiệt khi anh đến Giang Nam để điều tra vụ án. Giang Nam lúc đó bị bão lụt, nông dân nổi loạn và họ đi theo phái Tu La, giáo chủ &quot;Tu La Bất Tử&quot; có ý đồ phục quốc nên tuyên chiến với triều đình. Anh lẻn vào cung điện ngầm và sau khi bắt sống giáo chủ thì giáo chủ lại bị bắn chết. Vốn tưởng rằng giáo chủ của Tu La đã chết, sự kiện của Tu La Bất Tử đã kết thúc, không ngờ Tu La Bất Tử lại xuất hiện, khuôn mặt người này giống hệt thủ lĩnh bị Địch Nhân Kiệt giết trước đó. Địch Nhân Kiệt và những người khác hết sức chống cự, và mọi người đều xác nhận rằng &quot;Tu La Bất Tử&quot; lần này đã chết thật, và một sự cố không thể tưởng tượng được lại xảy ra, lại xuất hiện với một Tu La hình dáng cũ, với thuật trường sinh bất tử...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2022, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Guoliang","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Di Ren Jie Zhi Bu Si Xiu Luo","狄仁杰之不死修罗"]', 1784690324266);
