INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-ho-than-toc', 'Hẹn Hò Thần Tốc', 'The Skip Dating', 'https://phimimg.com/upload/vod/20241004-1/af9faa87be49a629527657d9affece09.jpg', 'https://phimimg.com/upload/vod/20241004-1/741ca17f9a15bdefeefc50afeebe72a5.jpg', '<p>Trong thời hiện đại bận rộn này, không có đủ thời gian để tìm một người bạn đời lãng mạn. Đối với họ, MC Yoo Jae-seok, Jeon So-min và Nucksal sắp xếp một buổi hẹn hò xem mắt 4:4 nhanh chóng và thú vị. Người tham gia nhấn nút trái tim hoặc nút bỏ qua tùy theo cảm nhận của họ. Đó là một công việc tình yêu nhanh chóng và thú vị.</p>', 'Hoàn Tất (22/22)', 22, 'tvshows', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"유재석","avatar":""},{"name":"전소민","avatar":""},{"name":"넉살","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["스킵"]', 1784690324266);
