INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-troi-day', 'Hổ Trỗi Dậy', 'The Tiger Rising', 'https://phimimg.com/upload/vod/20241004-1/e5611acb180f888595ce89004ced3363.jpg', 'https://phimimg.com/upload/vod/20241004-1/3a9631f4a24162609129797994111274.jpg', '<p>Khi Rob Horton, 12 tuổi, phát hiện ra một con hổ bị nhốt trong chuồng trong rừng gần nhà, trí tưởng tượng của cậu trở nên điên cuồng và cuộc sống bắt đầu thay đổi theo những cách không ngờ tới nhất. Với sự giúp đỡ của cô hầu gái khôn ngoan và bí ẩn, Willie May và cô gái mới bướng bỉnh ở trường, anh phải vượt qua những ký ức tuổi thơ, nỗi đau lòng và những cuộc phiêu lưu kỳ thú.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dennis Quaid","avatar":""},{"name":"Katharine McPhee","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Sam Trammell","avatar":""},{"name":"Christian Convery","avatar":""},{"name":"Madalen Mills","avatar":""},{"name":"Angela Giarratana","avatar":""},{"name":"Faith Dillon","avatar":""},{"name":"Nicholas Ryan Hernandez","avatar":""},{"name":"Selah Kimbro Jones","avatar":""},{"name":"Jayden Fontaine","avatar":""},{"name":"Sarah Rad","avatar":""},{"name":"Wayne Hughes","avatar":""},{"name":"Eden Luse","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Despierta, tigre","The Tiger Rising"]', 1784690324266);
