INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-va-nuoc-phan-3', 'Máu Và Nước (Phần 3)', 'Blood & Water (Season 3)', 'https://phimimg.com/upload/vod/20241004-1/3de5df0fa097ccec76669ec4bc147382.jpg', 'https://phimimg.com/upload/vod/20241004-1/e5aecafbf960be54d10e23e8c4738b7d.jpg', '<p>Khi một năm nữa bắt đầu ở Parkhurst, Puleng và Fiks tìm kiếm một người thân thất lạc nhưng sự kiên trì của cả hai có thể đẩy họ vào hiểm cảnh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Ama Qamata","avatar":""},{"name":"Khosi Ngema","avatar":""},{"name":"Gail Mabalane","avatar":""},{"name":"Thabang Molaba","avatar":""},{"name":"Dillon Windvogel","avatar":""},{"name":"Natasha Thahane","avatar":""},{"name":"Arno Greeff","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["疑是同根生","Blood & Water"]', 1784690324266);
