INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-nam-cua-chung-ta', 'Mười Năm Của Chúng Ta', 'Our Ten Years', 'https://phimimg.com/upload/vod/20241004-1/131af23338a8d560c0f44c8a42712cc0.jpg', 'https://phimimg.com/upload/vod/20241004-1/0f736da09a7c78d8ae4e718e54df35e2.jpg', '<p>Toàn bộ bộ phim chia làm mười một phần là &quot;Đường cung dạ yến&quot;, &quot;Nhiệt tình yêu thương&quot;, &quot;Lệ kiếm&quot;, &quot;Một ngày ba bữa&quot;, &quot;Kiên trì&quot;, &quot;Tiền Hải&quot;, &quot;Sa mạc chi quang&quot;, &quot;Tây hương minh nguyệt&quot;, &quot;Tâm chi sở hướng&quot; và &quot;Tương lai đã đến&quot; và &quot;Cuộc sống lý tưởng&quot;, với các chủ đề khác nhau, lựa chọn các trường hợp nhân vật chân thực để tiến hành xử lý nghệ thuật, để hình thành chân dung của con người trong thời đại mới, lấy những vết cắt nhỏ phản ánh chủ đề lớn, nhân vật nhỏ miêu tả thời đại lớn, thể hiện đầy đủ từ Đại hội 18 của Đảng đến nay. Dưới sự lãnh đạo của Đảng Cộng sản Trung Quốc, thành tựu rực rỡ của Chủ nghĩa xã hội đặc sắc Trung Quốc trong thời đại mới, thể hiện chặng đường tốt đẹp mà quần chúng nhân dân giành được với cảm giác hạnh phúc, cảm giác an toàn ngày càng phát triển. Đồng thời ca ngợi diện mạo mới, cuộc đấu tranh mới, tinh thần mới của quần chúng nhân dân trong thời đại mới.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Baihe","avatar":""},{"name":"張慧雯","avatar":""},{"name":"白宇帆","avatar":""},{"name":"Hou Yong","avatar":""},{"name":"Jiao Junyan","avatar":""},{"name":"郭晓东","avatar":""},{"name":"Yan Ni","avatar":""},{"name":"楊玏","avatar":""},{"name":"田雨","avatar":""},{"name":"宋伊人","avatar":""},{"name":"董潔","avatar":""},{"name":"Yuan Hong","avatar":""},{"name":"Chen He","avatar":""},{"name":"Lou Yixiao","avatar":""},{"name":"林一","avatar":""},{"name":"黃志忠","avatar":""},{"name":"譚松韻","avatar":""},{"name":"聶遠","avatar":""},{"name":"翟子路","avatar":""},{"name":"Dong Yong","avatar":""},{"name":"Pinyuan Huang","avatar":""},{"name":"楊子姍","avatar":""},{"name":"王凱","avatar":""},{"name":"Wang Lei","avatar":""},{"name":"Shen Yue","avatar":""},{"name":"萬鵬","avatar":""},{"name":"张炯敏","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Our Ten Years","Our Times","我们这十年"]', 1784690324266);
