INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-ngung-nhip-phan-1', 'Trái Tim Ngừng Nhịp (Phần 1)', 'Heartstopper (Season 1)', 'https://phimimg.com/upload/vod/20240409-1/ec79aeb4287a7de1d7a4813146f76742.jpg', 'https://phimimg.com/upload/vod/20240409-1/46881c013691e4ea3f68a62c85e1c7fb.jpg', '<p>Trong loạt phim tuổi dậy thì này, các thiếu niên Charlie và Nick xoay xở giữa việc học và tình yêu non trẻ rồi nhận ra tình bạn lạ kỳ của họ có thể còn sâu sắc hơn thế.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kit Connor","avatar":""},{"name":"Joe Locke","avatar":""},{"name":"William Gao","avatar":""},{"name":"Yasmin Finney","avatar":""},{"name":"Corinna Brown","avatar":""},{"name":"Kizzy Edgell","avatar":""},{"name":"Tobie Donovan","avatar":""},{"name":"Rhea Norwood","avatar":""},{"name":"Jenny Walser","avatar":""},{"name":"Sebastian Croft","avatar":""},{"name":"Cormac Hyde-Corrin","avatar":""},{"name":"Fisayo Akinade","avatar":""},{"name":"Chetna Pandya","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Stephen Fry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324266);
