INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song', 'Cuộc Sống', 'Living', 'https://phimimg.com/upload/vod/20241003-1/ff5c8af5213a364e090461a754cc508c.jpg', 'https://phimimg.com/upload/vod/20241003-1/439a1f18aa319f132a82691dc48b2606.jpg', '<p>Lấy bối cảnh ở London năm 1953, phim theo chân Williams, người đang đối mặt với một căn bệnh hiểm nghèo và cố gắng dành khoảng thời gian cuối cùng tận hưởng những điều tuyệt vời trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Thụy Điển', 0, '[{"name":"Bill Nighy","avatar":""},{"name":"Aimee Lou Wood","avatar":""},{"name":"Alex Sharp","avatar":""},{"name":"Tom Burke","avatar":""},{"name":"Adrian Rawlins","avatar":""},{"name":"Oliver Chris","avatar":""},{"name":"Hubert Burton","avatar":""},{"name":"Zoe Boyle","avatar":""},{"name":"Barney Fishwick","avatar":""},{"name":"Patsy Ferran","avatar":""},{"name":"Michael Cochrane","avatar":""},{"name":"Lia Williams","avatar":""},{"name":"Anant Varman","avatar":""},{"name":"Jessica Flood","avatar":""},{"name":"Jamie Wilkes","avatar":""},{"name":"Richard Cunningham","avatar":""},{"name":"John Mackay","avatar":""},{"name":"Ffion Jol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Vivre","Ikiru","生之欲英国版","Yaşamaq","Living"]', 1784690324266);
