INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-toi-di-fletch', 'Thú Tội Đi Fletch', 'Confess, Fletch', 'https://phimimg.com/upload/vod/20241001-1/fb0022b9c6d5c0ba800e1d8347c3a1ff.jpg', 'https://phimimg.com/upload/vod/20241001-1/33e74f4289ced0f471e8bdf7c677e638.jpg', '<p>Trong bộ phim thú vị này, Jon Hamm đóng vai Fletch quyến rũ và vô cùng rắc rối, người trở thành nghi phạm chính trong một vụ án giết người khi đang tìm kiếm một bộ sưu tập nghệ thuật bị đánh cắp. Cách duy nhất để chứng minh mình vô tội? Tìm ra ai trong danh sách dài những kẻ tình nghi là thủ phạm - từ tay buôn nghệ thuật lập dị và một tay ăn chơi mất tích cho đến người hàng xóm điên rồ và bạn gái người Ý của Fletch. Trên thực tế, tội phạm chưa bao giờ là vô tổ chức.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Lorenza Izzo","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Roy Wood Jr.","avatar":""},{"name":"Ayden Mayeri","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Annie Mumolo","avatar":""},{"name":"Lucy Punch","avatar":""},{"name":"John Behlmann","avatar":""},{"name":"Caitlin Zerra Rose","avatar":""},{"name":"Aaron Andrade","avatar":""},{"name":"Travis \"Taco\" Bennett","avatar":""},{"name":"Nhumi Threadgill","avatar":""},{"name":"Anna Osceola","avatar":""},{"name":"Gene Amoros","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Fletch","La machine infernale","Indrøm det, Fletch","Gib''s zu, Fletch","Confess, Fletch"]', 1784690324266);
