INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tad-truy-tim-kho-bau-3-loi-nguyen-xac-uop', 'Tad Truy Tìm Kho Báu 3: Lời Nguyền Xác Ướp', 'Tad, the Lost Explorer and the Emerald Tablet', 'https://phimimg.com/upload/vod/20241001-1/4caec2b52b0a4ca91cbef92ed90e92b1.jpg', 'https://phimimg.com/upload/vod/20241001-1/28ba93175ac4f1ddf1c46cf50e5188c4.jpg', '<p>Tad rất muốn các đồng nghiệp khảo cổ học chấp nhận anh ta là một người của họ, nhưng anh ta luôn làm mọi thứ rối tung lên. Tad vô tình phá hủy một cỗ quan tài và sử dụng một câu thần chú cổ xưa gây nguy hiểm đến tính mạng của những người bạn: Mummy, Jeff và Belzoni. Với tất cả mọi người chống lại anh ta và chỉ được Sara giúp đỡ, anh ta bắt đầu một cuộc phiêu lưu sẽ đưa anh ta từ Mexico đến Chicago và từ Paris đến Ai Cập, để chấm dứt lời nguyền của Xác ướp.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Óscar Barberán","avatar":""},{"name":"Luis Posada","avatar":""},{"name":"Michelle Jenner","avatar":""},{"name":"Anuska Alborg","avatar":""},{"name":"Alexandra Jiménez","avatar":""},{"name":"Tito Valverde","avatar":""},{"name":"Cecilia Suárez","avatar":""},{"name":"José Corbacho","avatar":""},{"name":"Berta Cortés","avatar":""},{"name":"Pablo Gómez","avatar":""},{"name":"Manuel Burque","avatar":""},{"name":"Roser Aldabó","avatar":""},{"name":"Gloria González","avatar":""},{"name":"Marcelo Navarro","avatar":""},{"name":"Ben Cura","avatar":""},{"name":"Claudio Serrano","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id