INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nui-lua-giai-cuu-tai-whakaari', 'Núi lửa: Giải cứu tại Whakaari', 'The Volcano: Rescue from Whakaari', 'https://phimimg.com/upload/vod/20241001-1/65473f5790d5bdf98b0363e5097cfe9d.jpg', 'https://phimimg.com/upload/vod/20241001-1/5d52d11dd71ac3afc9690f30bb6d5fd7.jpg', '<p>Bộ phim tài liệu hấp dẫn này tái hiện vụ núi lửa phun trào đầy chết chóc năm 2019 ở New Zealand qua lời kể của những người sống sót và đội cứu hộ cũng như cảnh quay theo từng phút.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'FHD', 'New Zealand', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["White Island","火山：法卡里营救","กู้ภัยจากวากาอาริ","The Volcano: Rescue from Whakaari","Der Vulkan: Rettung von Whakaari","Wulkan: Ewakuacja z Whakaari"]', 1784690324266);
