INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dung-trung-so', 'Bỗng Dưng Trúng Số', '6/45', 'https://phimimg.com/upload/vod/20241001-1/e7b27f88144119d18166d36dd3f14d2b.jpg', 'https://phimimg.com/upload/vod/20241001-1/21d1fdca03402f6c88811ef2f879e1a6.jpg', '<p>Người lính Hàn Quốc Chun Woo (Ko Kyoung-pyo) vô tình nhặt được tờ vé số trúng độc đắc trị giá lên đến gần 6 triệu đô! Nhưng chưa kịp vui mừng bao lâu, tờ vé số ấy không may bị cuốn bay sang bên kia biên giới và rơi vào tay anh lính Triều Tiên Yong Ho (Lee Yi-kyung). Chun Woo cần tờ vé số để đổi tiền, trong khi Yong Ho dù nắm giữ tờ vé quan trọng lại không thể đặt chân đến Hàn Quốc. Câu chuyện ngày càng trở nên rắc rối và hài hước khi có thêm những người đồng đội của hai anh chàng biết được sự việc và nhất quyết tham gia vào cuộc đàm phán chia tiền.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"고경표","avatar":""},{"name":"이이경","avatar":""},{"name":"음문석","avatar":""},{"name":"박세완","avatar":""},{"name":"곽동연","avatar":""},{"name":"이순원","avatar":""},{"name":"김민호","avatar":""},{"name":"윤병희","avatar":""},{"name":"류승수","avatar":""},{"name":"이준혁","avatar":""},{"name":"Shin Won-ho","avatar":""},{"name":"Nam Do-yoon","avatar":""},{"name":"정인기","avatar":""},{"name":"박희진","avatar":""},{"name":"이현걸","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["乐透大作战","军旅六合彩","6.45","6\\45","6/45","육사오","육사오（6/45）"]', 1784690324266);
