INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-2022', 'Giải Cứu', 'Come Back Home', 'https://phimimg.com/upload/vod/20241001-1/17223b05b85de0d20ba8cac9f8cfe0ac.jpg', 'https://phimimg.com/upload/vod/20241001-1/f5d3451cf24aa08c1c6203565524cd9f.jpg', '<p>Phim kể về một nhóm du khách đi ô tô đến núi Trường Bạch ở Đông Bắc Trung Quốc vào mùa đông lạnh giá, chuyến đi vui vẻ nhưng đứa con trai 8 tuổi của họ không may bị lạc do lỗi của người cha Ade ( do Chân Tử Đan thủ vai ). Vợ chồng Ade đã tìm kiếm sự hỗ trợ từ chính quyền địa phương có liên quan và chiến dịch tìm kiếm cứu nạn đã bắt đầu ngay lập tức.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Han Xue","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Tang Xu","avatar":""},{"name":"Hou Tianlai","avatar":""},{"name":"Guangyu Xu","avatar":""},{"name":"Lin Chenhan","avatar":""},{"name":"胡明","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Polar Rescue","Come Back Home","极地救援","Come Back Home CN","Tormenta de Nieve: Catástrofe Polar","搜救"]', 1784690324266);
