INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi', 'Cười', 'Smile', 'https://phimimg.com/upload/vod/20241001-1/cabf238c8e0212c5ac31d388cf3bf620.jpg', 'https://phimimg.com/upload/vod/20241001-1/cd37fb89d1066d8e26efa8ce3f8076e4.jpg', '<p>Sau khi chứng kiến một sự việc đau thương nhưng vô cùng kỳ lạ liên quan đến một bệnh nhân, những điều đáng sợ khó giải thích đã lần lượt xảy ra với Tiến sĩ Rose Cotter. Khi nỗi kinh hoàng bắt đầu xâm chiếm, bao trùm lấy cuộc sống của cô, Rose sẽ phải đối mặt với những rắc rối ở quá khứ để tìm cách tồn tại và thoát khỏi thực tại mới vô cùng kinh hoàng này.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Sosie Bacon","avatar":""},{"name":"Kyle Gallner","avatar":""},{"name":"Caitlin Stasey","avatar":""},{"name":"Jessie T. Usher","avatar":""},{"name":"Kal Penn","avatar":""},{"name":"Rob Morgan","avatar":""},{"name":"Robin Weigert","avatar":""},{"name":"Judy Reyes","avatar":""},{"name":"Gillian Zinser","avatar":""},{"name":"Jack Sochet","avatar":""},{"name":"Meghan Brown Pratt","avatar":""},{"name":"Nick Arapoglou","avatar":""},{"name":"Jared Johnston","avatar":""},{"name":"Shevy Gutierrez","avatar":""},{"name":"Ura Yoana Sánchez","avatar":""},{"name":"Scot Teller","avatar":""},{"name":"Dora Kiss","avatar":""},{"name":"Miche","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["魅笑","Smile - Siehst du es auch?","לחייך","لبخند","Усмивка","Sourire","Gülümse","Smile スマイル","ยิ้มสยอง","Gülümsə","夺命微笑","Something''s Wrong with Rose","Χαμογéλα","危笑","Buzëqeshja","Осмех","Zâmbește!","Smile"]', 1784690324266);
