INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('container-39', 'Container 39', 'Container 39', 'https://phimimg.com/upload/vod/20241001-1/11a20fae07da36286401be420147bca4.jpg', 'https://phimimg.com/upload/vod/20241001-1/a5fe4b4231af8a10ebece926c4884444.jpg', '<p>Lấy cảm hứng từ một sự kiện có thật gây chấn động thế giới với 39 người Việt thiệt mạng trong xe container, phim kể về hành trình vượt biên kinh hoàng của cặp tình nhân trẻ và khát vọng sống của họ.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lãnh Thanh","avatar":""},{"name":"Khánh Tiên Leona","avatar":""},{"name":"Sỹ Toàn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Container 39"]', 1784690324266);
