INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dong-hanh-ban-la-ai', 'Người Đồng Hành: Bạn Là Ai?', 'Tripmate: Who Are You?', 'https://phimimg.com/upload/vod/20241001-1/881377be1733bd1db695585568157052.jpg', 'https://phimimg.com/upload/vod/20241001-1/7feeb24f435affbc0755bf5466de9847.jpg', '<p>Các ngôi sao K-Pop và nghệ sĩ đến từ Indonesia, Thái Lan, Việt Nam sẽ lên đường đi &#39;du hí&#39; mà không hề biết trước bạn đồng hành của mình là ai. Lần đầu gặp gỡ, tình bạn mới và vô số những điều bất ngờ không thể đoán trước đang chờ đợi họ ở phía trước.</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jun Vũ","avatar":""},{"name":"Bomi (Apink)","avatar":""},{"name":"Jin Hyuk","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["트립메이트: 후아유"]', 1784690324266);
