INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-cua-toi', 'Bầu Trời Của Tôi', 'You''re My Sky', 'https://phimimg.com/upload/vod/20241001-1/8e64d262276c331419739357a4241dfc.jpg', 'https://phimimg.com/upload/vod/20241001-1/4a1dc7348a794e7a7e7e4bbb59bf2c7a.jpg', '<p>Thorn là sinh viên đại học năm thứ nhất, yêu thích chơi bóng rổ và mơ ước trở thành một cầu thủ cấp cao. Mặc dù cam kết đạt được thành công nhưng anh ấy vẫn gặp lại Tupfah, một cựu cầu thủ bóng rổ lớn tuổi mà anh ấy từng biết và hiện đã dập tắt tham vọng thể thao của riêng mình. Thorn cảm thấy bị Tupfah thu hút, nhưng không chắc liệu mình có nên nói với Tupfah về cảm xúc của mình hay không vì lo lắng rằng làm như vậy có thể gây ra vấn đề. Nhưng khi họ dành nhiều thời gian bên nhau hơn, tình bạn phát triển khi Thorn cố gắng thuyết phục cậu học sinh lớn tuổi quay trở lại với môn thể thao này - nhưng liệu tất cả có thể biến thành tình yêu?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Suar Kritsanaphong Sripattiyanon","avatar":""},{"name":"Tae Chayapat Kongsub","avatar":""},{"name":"Boom Thanut Jiraratchakit","avatar":""},{"name":"Jump Kananat Yansukon","avatar":""},{"name":"Porsche Tanathorn Charoenratanaporn","avatar":""},{"name":"Kris Sakris Strickland","avatar":""},{"name":"Perce Patarakorn Thaveesittikullarp","avatar":""},{"name":"First Thammarat Janngam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["You are My Sky","Chutmai Khue Thongfa","จุดหมายคือท้องฟ้า","SPECIAL EP. จุดหมายคือท้องฟ้า You’re My Sky The Series","You''re My Sky: Special Ep."]', 1784690324266);
