INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bau-troi-cua-toi', 'Bầu Trời Của Tôi', 'You''re My Sky', 'bầu trời của tôi you''re my sky suar kritsanaphong sripattiyanon tae chayapat kongsub boom thanut jiraratchakit jump kananat yansukon porsche tanathorn charoenratanaporn kris sakris strickland perce patarakorn thaveesittikullarp first thammarat janngam you are my sky chutmai khue thongfa จุดหมายคือท้องฟ้า special ep. จุดหมายคือท้องฟ้า you’re my sky the series you''re my sky: special ep.', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-thuc', 'Thượng Thực', 'Royal Feast', 'https://phimimg.com/upload/vod/20240825-1/f981a0a94ba5cf9a01007efc2a1d9e82.jpg', 'https://phimimg.com/upload/vod/20240825-1/0e35912df42ad66a567c5cec21455fba.jpg', '<p>Thượng Thực lấy bối cảnh năm Vĩnh Lạc thứ 19, triều nhà Minh mưa thuận gió hòa, quốc thái dân an. Để tiếp đãi sứ thần các nước, hoàng đế Vĩnh Lạc chiếu cáo thiên hạ, tuyển chọn nữ tử vào cung học về ẩm thực ở Sở Thượng Thực. Trải qua nhiều đợt tuyển chọn cam go, tiểu nữ Diêu Tử Khâm (Ngô Cẩn Ngôn) trở thành cung nữ của Sở Thượng Thực. Nàng lớn lên trong thâm cung và kiên quyết theo đuổi các kỹ năng ẩm thực của Trung Quốc thời bấy giờ. Chốn hoàng cung sâu thẳm, nàng vẫn quyết tâm và kiên trì làm việc theo cách của mình. Trong thời gian tự trui rèn khả năng nàng bất chợt gặp được Chu Chiêm Cơ (Hứa Khải), một thiên tài văn võ song toàn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2022, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"許凱","avatar":""},{"name":"吴谨言","avatar":""},{"name":"Wang Yizhe","avatar":""},{"name":"王楚然","avatar":""},{"name":"Zhang Nan","avatar":""},{"name":"何瑞賢","avatar":""},{"name":"何奉天","avatar":""},{"name":"Wang Yan","avatar":""},{"name":"Liu Min","avatar":""},{"name":"Shumei Lian","avatar":""},{"name":"于荣光","avatar":""},{"name":"Hong Jiantao","avatar":""},{"name":"Zhang Zhixi","avatar":""},{"name":"Cheng Lisha","avatar":""},{"name":"Han Shuai","avatar":""},{"name":"Zhu Zhiling","avatar":""},{"name":"Zhou Tai Heng","avatar":""},{"name":"Joy Sheng","avatar":""},{"name":"Yixi Zhang","avatar":""},{"name":"范楨","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id