INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-cruise-hanh-trinh-bat-kha-thi', 'Tom Cruise: Hành Trình "Bất Khả Thi"', 'Tom Cruise: Lights, Camera, Action', 'https://phimimg.com/upload/vod/20240928-1/1d18a721f18ce0ba5afbe87fb2a7fb50.jpg', 'https://phimimg.com/upload/vod/20240928-1/075eaf5ca7f71123eb55ee459db48f50.jpg', '<p>Vừa bước sang tuổi 60, Tom Cruise vẫn là một trong những tên tuổi hàng đầu ở Hollywood. Là một diễn viên sản xuất dồi dào với sự nghiệp kéo dài hơn 40 năm, anh tiếp tục xây dựng một di sản vĩ đại trong ngành điện ảnh với các tác phẩm kinh điển như Mission: Impossible hay Top Gun.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tom Cruise","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Tom Cruise: Lights, Camera, Action"]', 1784690324266);
