INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ly-tieu-long-2022', 'Huyền Thoại Lý Tiểu Long', 'Bruce Lee: The Way Of The Warrior', 'https://phimimg.com/upload/vod/20240928-1/e802bff50cafb6c7016f49fde606c67f.jpg', 'https://phimimg.com/upload/vod/20240928-1/85116b57a17bcf1fd6037baa9301b186.jpg', '<p>Lý Tiểu Long hay Bruce Lee là huyền thoại đã mang võ thuật Trung Hoa phổ biến đến Hollywood ở thế kỷ XX. Năm 2022, đạo diễn Ben Sempey đã kể lại chuyện đời tài hoa và đoản mệnh này dưới một góc nhìn khác.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Lý Tiểu Long","avatar":""},{"name":"Barbara Anderson","avatar":""},{"name":"Robert Baker","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Bruce Lee: The Way of the Warrior"]', 1784690324266);
