INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-am-tinh-dau', 'Thanh Âm Tình Đầu', 'Ditto', 'https://phimimg.com/upload/vod/20240928-1/5892ebade221244192fbe429d4787f71.jpg', 'https://phimimg.com/upload/vod/20240928-1/67b166f523106b7562c06acb15a8178c.jpg', '<p>&quot;Thanh Âm Tình Đầu&quot; xoay quanh câu chuyện của hai bạn sinh viên trẻ cùng học tại một trường đại học, nhưng lại sống ở hai mốc thời gian khác nhau: Kim Yong sống vào năm 1999, và Mo-nee sống vào năm 2022. Cả hai tình cờ có được một chiếc radio cũ kỹ. Trong lần nguyệt thực toàn phần vào năm 1999 và 2022, cặp đôi này có thể liên lạc với nhau xuyên thời gian một cách kỳ diệu thông qua radio. Họ bắt đầu tâm sự về câu chuyện tình yêu cũng như tình bạn của mỗi người.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"여진구","avatar":""},{"name":"조이현","avatar":""},{"name":"김혜윤","avatar":""},{"name":"나인우","avatar":""},{"name":"배인혁","avatar":""},{"name":"노재원","avatar":""},{"name":"Nam Min-woo","avatar":""},{"name":"Lim Yu-bin","avatar":""},{"name":"유재명","avatar":""},{"name":"박하선","avatar":""},{"name":"Shin Joo-hyup","avatar":""},{"name":"Yeo Joo-ha","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ditto","Agreement","同感頻率","同感","Соглашение","Donggam","Дітто","The Agreement","동감"]', 1784690324266);
