INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-ngam-ke-theo-doi', 'Đá Ngầm: Kẻ Theo Dõi', 'The Reef: Stalked', 'https://phimimg.com/upload/vod/20240926-1/609985dcc024a92453ca3595a12a9b56.jpg', 'https://phimimg.com/upload/vod/20240926-1/8b474be327af4cf7e933a5bc96cbc326.jpg', '<p>Sau cái chết của em gái, Nic, em gái cô và hai người bạn tìm kiếm niềm an ủi thông qua chuyến phiêu lưu chèo thuyền kayak trên đảo Thái Bình Dương. Vài giờ sau chuyến đi, những người phụ nữ bị một con cá mập rình rập và phải đoàn kết lại, đối mặt với nỗi sợ hãi và cứu nhau.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Teressa Liane","avatar":""},{"name":"Ann Truong","avatar":""},{"name":"Saskia Archer","avatar":""},{"name":"Kate Lister","avatar":""},{"name":"Bridget Burt","avatar":""},{"name":"Tim Ross","avatar":""},{"name":"Wendy P. Mocke","avatar":""},{"name":"Eva Mocke-Kanaki","avatar":""},{"name":"Sophie Naime","avatar":""},{"name":"Barney Ling","avatar":""},{"name":"Steve Daddow","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Reef 2","The Reef - Stalked","The Reef: Stalked"]', 1784690324266);
