INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-choi-khong-so-con-roi', 'Dân Chơi Không Sợ Con Rơi', 'My Father is a Playboy', 'https://phimimg.com/upload/vod/20240925-1/bff792e761ae56eb475716bb040427e4.jpg', 'https://phimimg.com/upload/vod/20240925-1/bd5ea04257f2ceb3362033d6225be743.jpg', '<p>Quân, một dân chơi miệt vườn với tài “sát gái” thượng hạng, bỗng một ngày phải gánh lấy &quot;cục nợ con rơi&quot; từ bạn gái cũ. Được sự trợ giúp &quot;ba phần đắc lực bảy phần phá đám&quot; của Tám Mánh, Quân dần mất hết hy vọng tìm lại mẹ cho đứa bé và dần trở thành người cha hoàn hảo trong mắt Bé Thỏ. &nbsp;Cuộc sống đầy sắc màu và tiếng cười của hai cha con bị đặt trước thử thách lớn lao khi người mẹ mà Bé Thỏ ngày đêm mong ngóng cuối cùng cũng xuất hiện…</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Tiến Luật","avatar":""},{"name":"Bé Bảo Thi","avatar":""},{"name":"Huỳnh Phương","avatar":""},{"name":"Vân Trang","avatar":""},{"name":"Ngô Kiến Huy","avatar":""},{"name":"Lê Khánh","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Senior Playboy, Junior Papa","คุณพ่อเพลย์บอย","Dân Chơi Không Sợ Con Rơi"]', 1784690324266);
