INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-phut-dam-me', 'Sau Phút Đam Mê', 'After The Moment Of Passion', 'https://phimimg.com/upload/vod/20240924-1/d0b63a86df524e1e5d88a9819c861a61.jpg', 'https://phimimg.com/upload/vod/20240924-1/03e953dcc2810aee16702b6f33dad427.jpg', '<p>Phim xoay quanh câu chuyện về Thiện Tâm – 16 tuổi, trong một tai nạn cậu tình cờ phát hiện mình là đứa con được tạo ra bởi tội lỗi của người cha ruột. Bi kịch tiếp nối bi kịch khiến Thiện Tâm từ một cậu bé sống an yên hạnh phúc bỗng mất đi tất cả, ôm nỗi oán hận và quyết tâm giành lại bằng được phần tài sản đã bị người cha ruột chiếm mất. Từ hai bàn tay trắng, cậu phải đương đầu với bao nhiêu thử thách và cám dỗ, đôi lúc gục ngã rơi vào tuyệt vọng. Nhưng với tấm lòng lương thiện và niềm đam mê với nghệ thuật điêu khắc gỗ truyền thống của gia đình, Thiện Tâm đã sống và tận hưởng hạnh phúc trọn vẹn với đam mê mình theo đuổi.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Oanh Kiều","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Cao Minh Đạt","avatar":""},{"name":"Thành Khôn","avatar":""},{"name":"Thân Thúy Hà","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yuan Zui","原罪2","原罪"]', 1784690324266);
