INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('black-adam', 'Black Adam', 'Black Adam', 'https://phimimg.com/upload/vod/20240920-1/25e7ec547ec0a70be677ef10ee877fbb.jpg', 'https://phimimg.com/upload/vod/20240920-1/f896d2b2c6a26ea2676e760ca29c772b.jpg', '<p>Dwayne Johnson sẽ góp mặt trong tác phẩm hành động - phiêu lưu mới của New Line Cinema, mang tên BLACK ADAM. Đây là bộ phim đầu tiên trên màn ảnh rộng khai thác câu chuyện của siêu anh hùng DC này, dưới sự sáng tạo của đạo diễn Jaume Collet-Serra (đạo diễn của Jungle Cruise). Gần 5.000 năm sau khi bị cầm tù với quyền năng tối thượng từ những vị thần cổ đại, Black Adam (Dwayne Johnson) sẽ được giải phóng khỏi nấm mồ chết chóc của mình, mang tới thế giới hiện đại một kiểu nhận thức về công lý hoàn toàn mới.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Aldis Hodge","avatar":""},{"name":"Noah Centineo","avatar":""},{"name":"Sarah Shahi","avatar":""},{"name":"Quintessa Swindell","avatar":""},{"name":"Marwan Kenzari","avatar":""},{"name":"Mo Amer","avatar":""},{"name":"Bodhi Sabongui","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"James Cusati-Moyer","avatar":""},{"name":"Jalon Christian","avatar":""},{"name":"Benjamin Patterson","avatar":""},{"name":"Odelya Halevi","avatar":""},{"name":"Uli Latukefu","avatar":""},{"name":"Jennifer Holland","avatar":""},{"name":"Henry Winkler","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849