INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aziz-ansari-dien-vien-hai-hop-dem', 'Aziz Ansari: Diễn Viên Hài Hộp Đêm', 'Aziz Ansari: Nightclub Comedian', 'https://phimimg.com/upload/vod/20240713-1/6c3fb83d5110a1e40c724c13c125fdee.jpg', 'https://phimimg.com/upload/vod/20240713-1/6cad62a4ee0daffcbce504f4e21c8c28.jpg', '<p>Sau một năm ngừng hoạt động nữa, Aziz bước lên sân khấu để phá hủy cuộc sống của đại dịch, cách ly, thẻ vắc xin, hợp đồng biểu diễn phụ của người nổi tiếng, điện thoại thông minh, v.v.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aziz Ansari","avatar":""},{"name":"Phil Hanley","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324266);
