INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chu-nha-chappelle-earthquake-legendary', 'Đội Chủ Nhà Chappelle - Earthquake: Legendary', 'Chappelle''s Home Team - Earthquake: Legendary', 'https://phimimg.com/upload/vod/20240713-1/fc9e6f737d340aaad81c55c65d9f0ebc.jpg', 'https://phimimg.com/upload/vod/20240713-1/6df7686c61643f0473f692b04f87a40e.jpg', '<p>Earthquake làm rung chuyển sân khấu với câu nói sức khỏe là của cải, kiểm tra tuyến tiền liệt và một đám tang đặc biệt kéo dài của người nổi tiếng.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Earthquake","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324266);
