INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('norm-macdonald-khong-co-gi-dac-biet', 'Norm Macdonald: Không Có Gì đặc Biệt', 'Norm Macdonald: Nothing Special', 'https://phimimg.com/upload/vod/20240713-1/f7469d44ade16e8fc79f5f8138cd2e57.jpg', 'https://phimimg.com/upload/vod/20240713-1/12cc2f867a51131d33177ef35d782737.jpg', '<p>Trong bộ phim hài đặc biệt cuối cùng của mình, Norm Macdonald suy ngẫm về các sòng bạc, tục ăn thịt người, ý chí sống và lý do tại sao bạn phải sẵn sàng cho bất cứ điều gì cuộc sống xảy ra theo cách của bạn, tất cả đều được thực hiện trước máy quay, không có khán giả và chỉ trong một lần quay. Sau buổi diễn của anh ấy, bạn bè và đồng nghiệp của Norm tụ tập để chào anh ấy.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Norm Macdonald","avatar":""},{"name":"Dave Chappelle","avatar":""},{"name":"David Letterman","avatar":""},{"name":"Conan O''Brien","avatar":""},{"name":"Adam Sandler","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"David Spade","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324266);
