INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-nguyen-hinh', 'Hiện Nguyên Hình', 'Showing Up', 'https://phimimg.com/upload/vod/20240711-1/d1cf9feb07a7276aea7b838ffa341833.jpg', 'https://phimimg.com/upload/vod/20240711-1/172f925275ad1ff43a75505327882311.jpg', '<p>Trong những ngày chuẩn bị diễn ra một cuộc triển lãm có thể sẽ thay đổi nghề nghiệp, một nhà điêu khắc điều chỉnh các mối quan hệ của mình với gia đình, bạn bè và đồng nghiệp.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Williams","avatar":""},{"name":"Hong Chau","avatar":""},{"name":"Maryann Plunkett","avatar":""},{"name":"John Magaro","avatar":""},{"name":"André 3000","avatar":""},{"name":"Amanda Plummer","avatar":""},{"name":"Matt Malloy","avatar":""},{"name":"Heather Lawless","avatar":""},{"name":"James Le Gros","avatar":""},{"name":"Denzel Rodriguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324266);
