INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-pho-tuong-co', 'Lời Nguyền Pho Tượng Cổ', 'Monstrous', 'https://phimimg.com/upload/vod/20240914-1/640703963fbc228a5a57ecdefc2e6f4e.jpg', 'https://phimimg.com/upload/vod/20240914-1/cab4286ba31163634e0e59a13042c526.jpg', '<p>Chuyện phim Monstrous bắt đầu từ Jung Ji Hoon (Koo Kyo Hwan thủ vai), người sống với đam mê tìm kiếm những hiện tượng siêu nhiên kỳ lạ với tư cách là một nhà khảo cổ học, nhưng cuộc đời anh đã bước sang một ngã rẽ sau một sự cố bất ngờ. Hiện tại, anh đang xuất bản tạp chí Chuyện lạ hàng tháng và điều hành kênh Youtube Chuyện lạ hàng tháng. Tự hứa với lòng sẽ không quay lại nghề khảo cổ học nhưng vì vợ cũ của anh là Lee Soo Jin (Shin Hyun Bin đóng), anh đến quận Jinyang để nghiên cứu “Gwibul” - một bức tượng Phật giáo bị linh hồn quỷ ám. Tại đây, nam chính Monstrous phải đối mặt với một hiện tượng vô cùng kỳ lạ và đáng sợ.</p>', 'Full', 1, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"구교환","avatar":""},{"name":"신현빈","avatar":""},{"name":"김지영","avatar":""},{"name":"박호산","avatar":""},{"name":"곽동연","avatar":""},{"name":"남다름","avatar":""},{"name":"박소이","avatar":""},{"name":"동현배","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324266);
