INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-cua-nhung-chiec-nhan-nhung-chiec-nhan-quyen-nang-phan-1', 'Chúa Tể Của Những Chiếc Nhẫn : Những Chiếc Nhẫn Quyền Năng (Phần 1)', 'The Lord of the Rings : The Rings of Power (Season 1)', 'https://phimimg.com/upload/vod/20240830-1/b90edabcd95ef5bfe426eca6ef117ab4.jpg', 'https://phimimg.com/upload/vod/20240830-1/da6cc4673b9eb77b48ab53f379078b36.jpg', '<p>Mở đầu từ một thời đại tương đối an bình, ta theo dõi một nhóm nhân vật đối đầu với sự tái xuất của cái ác ở Trung Địa. Từ nơi sâu tối tăm nhất của Dãy núi Sương mù, đến những khu rừng hùng vĩ của Lindon, vương quốc đảo Númenor ngoạn mục, những nơi xa nhất trên bản đồ. Kể cả khi không còn nữa, những vương quốc và nhân vật này vẫn để lại di sản trường tồn.</p>', 'Hoàn Tất (8/8)', 29, 'series', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Morfydd Clark","avatar":""},{"name":"Charlie Vickers","avatar":""},{"name":"Robert Aramayo","avatar":""},{"name":"Owain Arthur","avatar":""},{"name":"Ismael Cruz Cordova","avatar":""},{"name":"نازنین بنیادی","avatar":""},{"name":"Lloyd Owen","avatar":""},{"name":"Maxim Baldry","avatar":""},{"name":"Markella Kavenagh","avatar":""},{"name":"Tyroe Muhafidin","avatar":""},{"name":"Daniel Weyman","avatar":""},{"name":"Charles Edwards","avatar":""},{"name":"Trystan Gravelle","avatar":""},{"name":"Sophia Nomvete","avatar":""},{"name":"Ema Horvath","avatar":""},{"name":"Geoff Morrell","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"6856