INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-o-cua-so', 'Qua Ô Cửa Sổ', 'Through My Window', 'https://phimimg.com/upload/vod/20230926-1/7c0b7bb4ab2d9aaba2a1945d7d2baa41.jpg', 'https://phimimg.com/upload/vod/20230926-1/23e732b977c2bed298e058c1864f5ec4.jpg', '<p>Raquel thích chàng hàng xóm từ lâu, và giờ tình ý ấy bỗng tiến triển xa hơn khi anh bắt đầu có tình cảm với cô – bất chấp sự phản đối của gia đình.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Clara Galle","avatar":""},{"name":"Julio Peña","avatar":""},{"name":"Guillermo Lasheras","avatar":""},{"name":"Natalia Azahara","avatar":""},{"name":"Hugo Arbues","avatar":""},{"name":"Eric Masip","avatar":""},{"name":"Pilar Castro","avatar":""},{"name":"Abel Folk","avatar":""},{"name":"Rachel Lascar","avatar":""},{"name":"Emilia Lazo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324266);
