INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tu-do', 'Hành Trình Tự Do', 'Emancipation', 'https://phimimg.com/upload/vod/20230925-1/54aab29e82ad92d45d62cc0252766f08.jpg', 'https://phimimg.com/upload/vod/20230925-1/f8acbd2eba04dacc0c303fc37b0cd126.jpg', '<p>Lấy cảm hứng từ câu chuyện có thật hấp dẫn về một người đàn ông sẵn sàng làm bất cứ điều gì vì gia đình mình—và vì tự do. Khi Peter, một nô lệ, liều mạng trốn thoát và trở về với gia đình, anh dấn thân vào một hành trình đầy nguy hiểm của tình yêu và sự chịu đựng.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Charmaine Bingwa","avatar":""},{"name":"Steven Ogg","avatar":""},{"name":"Gilbert Owuor","avatar":""},{"name":"Mustafa Shakir","avatar":""},{"name":"Grant Harvey","avatar":""},{"name":"Ronnie Gene Blevins","avatar":""},{"name":"Jayson Warner Smith","avatar":""},{"name":"Jabbar Lewis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324266);
