INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-an-dam-mau', 'Dự Án Đẫm Máu', 'X', 'https://phimimg.com/upload/vod/20231018-1/2924a4d41633a8dd663bede411ce1f0c.jpg', 'https://phimimg.com/upload/vod/20231018-1/e172a9256cb162e79702b3a4f5f87516.jpg', '<p>Năm 1979, một nhóm cá nhà làm phim khiêu dâm trẻ tuổi bắt đầu bộ phim của mình ở vùng nông thôn Texas, nhưng khi đôi vợ chồng chủ nhà già phát hiện những điều họ làm, dàn diễn viên bị cuốn vào cuộc truy đuổi kịch tính và không kém phần nhục dục.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mia Goth","avatar":""},{"name":"Jenna Ortega","avatar":""},{"name":"Brittany Snow","avatar":""},{"name":"Kid Cudi","avatar":""},{"name":"Martin Henderson","avatar":""},{"name":"Owen Campbell","avatar":""},{"name":"Stephen Ure","avatar":""},{"name":"James Gaylyn","avatar":""},{"name":"Simon Prast","avatar":""},{"name":"Geoff Dolan","avatar":""},{"name":"Matthew J. Saville","avatar":""},{"name":"Bryony Skillington","avatar":""},{"name":"Karen Gillan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324266);
