INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-quyen', 'Đặc Quyền', 'The Privilege', 'https://phimimg.com/upload/vod/20231110-1/7022c24f18468d544e75639de8f6df25.jpg', 'https://phimimg.com/upload/vod/20231110-1/fd9ccaca0c44db321add04bbcb52b36e.jpg', '<p>Đang theo học trường tư ưu tú, một thiếu niên giàu có cùng bạn bè khám phá ra âm mưu đen tối trong khi điều tra hàng loạt sự kiện siêu nhiên kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Max Schimmelpfennig","avatar":""},{"name":"Lea van Acken","avatar":""},{"name":"Tijan Marei","avatar":""},{"name":"Milena Tscharntke","avatar":""},{"name":"Lise Risom Olsen","avatar":""},{"name":"Roman Knizka","avatar":""},{"name":"Nadeshda Brennicke","avatar":""},{"name":"Horst Janson","avatar":""},{"name":"Caroline Hartig","avatar":""},{"name":"Jeanette Spassova","avatar":""},{"name":"Oleg Tikhomirov","avatar":""},{"name":"Maurice Lattke","avatar":""},{"name":"Rojan Juan Barani","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324266);
