INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-thinh-no-cua-chua', 'Cơn thịnh nộ của Chúa', 'The Wrath of God', 'https://phimimg.com/upload/vod/20231103-1/67fa8d78679190536eef0e0e5d585e23.jpg', 'https://phimimg.com/upload/vod/20231103-1/658802a876d10cc6160cdac8011bce74.jpg', '<p>Tin rằng cái chết bi thảm của người thân mình là do vị tiểu thuyết gia nổi tiếng mà cô đang làm việc cùng sắp đặt, Luciana nhờ một nhà báo vạch trần sự thật.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Argentina', 0, '[{"name":"Diego Peretti","avatar":""},{"name":"Juan Minujín","avatar":""},{"name":"Macarena Achaga","avatar":""},{"name":"Mónica Antonópulos","avatar":""},{"name":"Guillermo Arengo","avatar":""},{"name":"Romina Pinto","avatar":""},{"name":"Pedro Merlo","avatar":""},{"name":"Ornella D''Elía","avatar":""},{"name":"Santiago Achaga","avatar":""},{"name":"Juanita Reale","avatar":""},{"name":"Pablo Lapadula","avatar":""},{"name":"Lisandro Fiks","avatar":""},{"name":"Ana Waisbein","avatar":""},{"name":"Germán de Silva","avatar":""},{"name":"Silvina Sabater","avatar":""},{"name":"Briana Patin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324266);
