INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-thinh-no-cua-chua', 'Cơn thịnh nộ của Chúa', 'The Wrath of God', 'cơn thịnh nộ của chúa the wrath of god diego peretti juan minujín macarena achaga mónica antonópulos guillermo arengo romina pinto pedro merlo ornella d''elía santiago achaga juanita reale pablo lapadula lisandro fiks ana waisbein germán de silva silvina sabater briana patin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-day-hoang-lan', 'Sợi Dây Hoàng Lan', 'Sroi Sabunnga', 'https://phimimg.com/upload/vod/20240909-1/32db16ab9ddbf424bef58bc43892a535.jpg', 'https://phimimg.com/upload/vod/20240909-1/36292c19631c74690055f2620cceb69a.jpg', '<p>Sroi Sabunnga sinh ra trong một gia đình quý tộc. Từ bé, cô đã được cha dạy dỗ để luôn tự hào về dòng máu cũng như địa vị của mình, với mục tiêu đưa gia đình trở lại vinh quang trước đây sau khi bị bỏ rơi vì chiến tranh. Khi anh trai và cha đột ngột qua đời, Ngam chuyển đến cung điện Rawiwath, được người dì Mhom Saengjuntra chăm sóc. Ở đó Ngam gặp Hoàng tử Aiyares, người giống với chàng hoàng tử trong mộng của cô. Giống như cha đã dạy, cô đặt mục tiêu kết hôn với Hoàng tử Aiyares, người hoàn hảo và xứng đáng nhất trong mắt cô. Tuy nhiên, cô cũng gặp Tian, một chủ nhà máy người Trung Quốc trung thực, yêu cô vô điều kiện. Dù trái tim rất khao khát, nhưng Ngam không thể ở bên Tian vì lời hứa với cha mình. Yêu một người phụ nữ đầy tham vọng, Tian phải đau đớn hết lần này đến lần khác nhưng trái tim anh lại không muốn Sroi chịu bất kì tổn thương nào.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pimchanok Luevisadpaibul","avatar":""},{"name":"ณภัทร เสียงสมบุญ","avatar":""},{"name":"Tong Savitree Samipak","avatar":""},{"name":"Chartayodom Hiranyatithi","avatar":""},{"name":"Sueangsuda Lawanprasert","avatar":""},{"name":"Apasiri Nitibhon","avatar":""},{"name":"Kawin Imanothai","avatar":""},{"name":"Prima Bhunjaroeun","avatar":""},{"name":"Mona Amolrada Chaiyadej","avatar":""},{"name":"Pijittra Siriwetchapan","avatar":""},{"name":"Khwanruedi Klomklom","avatar":""},{"name":"Phanudet Watn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324266);
