INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-ngo-ngao-nguoi-dep-ngu-trong-rung', 'Công Chúa Ngổ Ngáo Người Đẹp Ngủ Trong Rừng', 'My Sassy Princess Wake Up Sleeping Beauty', 'https://phimimg.com/upload/vod/20240908-1/61cdfe916930b85a2a10a2eb3b994247.jpg', 'https://phimimg.com/upload/vod/20240908-1/1e802841e4fc6e15381ea0cb02d3bd88.jpg', '<p>Tái hiện lại câu chuyện cổ tích &quot;Người đẹp ngủ trong rừng&quot; trong xã hội hiện đại. Aurora thời đại mới là một cô nàng nóng bỏng, phóng khoáng và táo bạo. Cô lên đường với sự tự tin vì biết rằng dù có chuyện gì xảy ra thì chàng hoàng tử cưỡi bạch mã sẽ luôn đến cứu cô. Thế nhưng, liệu có phải lúc nào hoàng tử cũng đến kịp lúc?</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Lee Thanat Lowkhunsombat","avatar":""},{"name":"Kimmy Chermarin Cole","avatar":""},{"name":"Pepo Nutchapan Paramacharenroj","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324266);
