INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('maksym-osa-vang-cua-nguoi-soi', 'Maksym Osa: Vàng Của Người Sói', 'Maksym Osa: The Gold of Werewolf', 'https://phimimg.com/upload/vod/20231101-1/a8cc032bba6494ebdcd3aac7ccf230e3.jpg', 'https://phimimg.com/upload/vod/20231101-1/be0f0e962daaecb2fd3fd3b786eeb880.jpg', '<p>Ukraine - 1636. Ai đó đã tấn công một tiểu đoàn cô-dắc đang vận chuyển vàng của vua Ba Lan. Một cossack - Maksym Osa - cố gắng tìm số vàng bị mất tích, nhưng nhanh chóng trở thành một trong những nghi phạm chính.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Vasyl Kukharskyi","avatar":""},{"name":"Olga Makeeva","avatar":""},{"name":"Vladimir Yushchenko","avatar":""},{"name":"Volodymyr Hurin","avatar":""},{"name":"Serhii Denha","avatar":""},{"name":"Albina Korzh","avatar":""},{"name":"Bohdan Beniuk","avatar":""},{"name":"Mykhailo Illienko","avatar":""},{"name":"Myroslav Latyk","avatar":""},{"name":"Serhii Shadrin","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324266);
