INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-hoa-bi', 'Chỉ Hoạ Bì', 'Paper Beauty', 'https://phimimg.com/upload/vod/20231101-1/9242b576b01f283ffb105f23353d1cd1.jpg', 'https://phimimg.com/upload/vod/20231101-1/7b2894bb56013fd18a6480d373c06a2f.jpg', '<p>Hoạ sư cung đình Lục Cửu Khanh vô tình dùng bút thần mở ra thế giới trong tranh, gặp gỡ tinh linh thảo mộc Nhan Ca. Nữ tử trong thành liên tiếp bị huỷ hoại gương mặt, để điều tra chân tướng hai người họ đã vào mộ sinh tử. Yêu vương lột đi da mặt của chúng tinh linh thảo mộc, Nhan Ca mất đi gương mặt xinh đẹp trở thành cành cây khô cằn dữ tợn. Một cuộc thử thách giữa vẻ bề ngoài và tấm lòng được đặt ra ngay trước mặt Lục Cửu Khanh.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhu Shengyi","avatar":""},{"name":"Chen Yilong","avatar":""},{"name":"Chi Shuai","avatar":""},{"name":"Wu Chunyan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324266);
