INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-cho-em-su-yeu-chieu-doc-nhat-2', 'Dành Cho Em Sự Yêu Chiều Độc Nhất 2', 'Here Is My Exclusive Indulge S2', 'https://phimimg.com/upload/vod/20240403-1/e865f464d8d442292683a7a5b97a1bdb.jpg', 'https://phimimg.com/upload/vod/20240403-1/c01f669980f69f6ff654c550b253a6f3.jpg', '<p>Vân Tưởng Tưởng dùng hình tượng doanh nhân của Phó Tư Hàn để vẽ một cuốn truyện tranh thiếu nữ nhằm kiếm tiền thuốc men cho mẹ. Bị Phó Tư Hàn phát hiện và truy cứu nhà xuất bản. Để tránh bị truy cứu, Vân Tưởng Tưởng đến tìm gặp Phó Tư Hàn để xin lỗi nhưng lại nhận được một lời đề nghị bất ngờ từ Phó Tư Hàn: Đóng giả vợ sắp cưới của anh ta.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"LinFengsong","avatar":""},{"name":"Sissi Bao","avatar":""},{"name":"Chen Siqi","avatar":""},{"name":"Sun Yuchen","avatar":""},{"name":"Han Yutong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324266);
