INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-va-nhung-vi-sao-cua-toi', 'Tình Yêu Và Những Vì Sao Của Tôi', 'My Love And Stars', 'https://phimimg.com/upload/vod/20240831-1/f6db86d35350794d5bdb1fb7c202127b.jpg', 'https://phimimg.com/upload/vod/20240831-1/03fdde8381f726a6599ceb40a2a7e7f7.jpg', '<p>Nữ minh tinh Tân Thần từ ngôi sao hạng A lạc rơi xuống làm trợ lý cho nam ca sĩ An Tiểu Dữ vừa ra mắt, sự nghiệp và tình yêu đả kích cùng lúc, người mạnh mẽ kiên cường như cô ấy làm sao để ngược gió trở mình, quay lại đỉnh cao. An Tiểu Dữ bề ngoài luôn không chấp nhận Tân Thần, làm sao nhìn thấy ánh sáng của nhau từ trong hiểm cảnh, nắm lấy tay nhau?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Diêu Trì","avatar":""},{"name":"Tống Phương Viên","avatar":""},{"name":"Trương Nam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324266);
