INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blues-noi-dao-xanh', 'Blues Nơi đảo Xanh', 'Our Blues', 'https://phimimg.com/upload/vod/20240403-1/c3fe75b165237525dba1597ab5f04e42.jpg', 'https://phimimg.com/upload/vod/20240403-1/451a0e2fc653cdbe0e31e0a294e1e098.jpg', '<p>Tình yêu ngọt ngào và cay đắng, còn cuộc sống đầy những nốt thăng và nốt trầm trong nhiều câu chuyện về những con người sống và làm việc trên đảo Jeju nhộn nhịp.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2022, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Byung Hun","avatar":""},{"name":"Shin Min A","avatar":""},{"name":"Cha Seoung Won","avatar":""},{"name":"Lee Jung Eun","avatar":""},{"name":"Han Ji Min","avatar":""},{"name":"Kim Woo Bin","avatar":""},{"name":"Uhm Jung Hwa","avatar":""},{"name":"Kim Hye Ja","avatar":""},{"name":"Go Du Sim","avatar":""},{"name":"Park Ji Hwan","avatar":""},{"name":"Choi Young Jun","avatar":""},{"name":"Bae Hyeon Seong","avatar":""},{"name":"Noh Yoon Seo","avatar":""},{"name":"Gi So You","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324266);
