INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('blues-noi-dao-xanh', 'Blues Nơi đảo Xanh', 'Our Blues', 'blues nơi đảo xanh our blues lee byung hun shin min a cha seoung won lee jung eun han ji min kim woo bin uhm jung hwa kim hye ja go du sim park ji hwan choi young jun bae hyeon seong noh yoon seo gi so you ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-duong', 'Bác Sĩ Đường', 'Dr. Tang', 'https://phimimg.com/upload/vod/20240828-1/955d77af19c31fbfba3f12a1f02c371c.jpg', 'https://phimimg.com/upload/vod/20240828-1/0a606ff67d5e38a92a7c93e6b55051f5.jpg', '<p>Bộ phim là câu chuyện của Đường Giai Du, một nữ bác sĩ khoa tim đã hành nghề y ở nước ngoài nhiều năm, được Phó viện trưởng Lưu Phong mời về nước đảm nhận chức vụ Chủ nhiệm Trung tâm Tim mạch của bệnh viện An Hoà Tế Sinh Bắc Kinh. Từ việc không đánh không quen với Âu Dương Chân Dư đến việc dần dần trở thành tri kỷ cùng bác sĩ gây mê Diệp Dịch Minh. Đồng thời lại dẫn dắt 5 thành viên của nhóm bệnh hiểm nghèo: Giang Bách Liệt, Long Hướng Đông, Tần Đại Trung, Chu Đạt, Liêu Tiểu Ba cùng nhau cứu chữa 28 trường hợp mắc bệnh tim hiếm gặp. Dưới sự cố gắng và phát triển không ngừng đã thúc đẩy việc nghiên cứu và phát triển thành công &quot;trái tim nhân tạo&quot;, tạo nên lịch sử mới của trong việc nghiên cứu tim nhân tạo ở Trung Quốc. Đồng thời nhân vật cũng nhận ra những sai lầm của bản thân và tìm ra hạnh phúc của chính mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2022, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"秦嵐","avatar":""},{"name":"魏大勛","avatar":""},{"name":"高露","avatar":""},{"name":"Huang Jue","avatar":""},{"name":"David Wang","avatar":""},{"name":"Geng Yizhan","avatar":""},{"name":"Xuan Yan","avatar":""},{"name":"Jin Zehao","avatar":""},{"name":"宁文彤","avatar":""},{"name":"Zhang Xiang","avatar":""},{"name":"Qu Gaowei","avatar":""},{"name":"Peng Yang","avatar":""},{"name":"Jia Jinghui","avatar":""},{"name":"劉美含","avatar":""},{"name":"Yang Zihua","avatar":""},{"name":"Zhang Wen","avatar":""},{"name":"王策","avatar":""},{"name":"劉奕君","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324266);
