INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-anh-hung-samaritan', 'Siêu Anh Hùng Samaritan', 'Samaritan', 'https://phimimg.com/upload/vod/20230925-1/d3cd193cd01e8deef385f135e3af5728.jpg', 'https://phimimg.com/upload/vod/20230925-1/ad8777e727b5a45b558e1637030e33af.jpg', '<p>Một cậu bé biết rằng một siêu anh hùng được cho là đã mất tích sau một trận chiến kinh thiên động địa hai mươi năm trước trên thực tế có thể vẫn còn ở đây.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Javon Walton","avatar":""},{"name":"Sylvester Stallone","avatar":""},{"name":"Dascha Polanco","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"Pilou Asbæk","avatar":""},{"name":"Sophia Tatum","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Henry G. Sanders","avatar":""},{"name":"Jared Odrick","avatar":""},{"name":"Abraham Clinkscales","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324266);
