INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-thu-am-666', 'Phòng Thu Âm 666', 'Studio 666', 'https://phimimg.com/upload/vod/20231107-1/fa08a440ffd129b06be3d337617f091d.jpg', 'https://phimimg.com/upload/vod/20231107-1/d5eb213a0e10e6ea36226016affa197d.jpg', '<p>Vào năm 1993 , Encino , Skye Willow, ca sĩ chính của ban nhạc rock Dream Widow, đang bò dọc sàn nhà với một cái chân bị gãy, theo sát là người đứng đầu của ban nhạc, Greg Nole, người đang cầm một chiếc búa. Skye nhìn thấy thi thể của một thành viên khác trong ban nhạc, người đã bị Greg đánh gãy hàm, trước khi Greg lái chiếc búa xuyên qua trán cô và liên tục đập vào đầu cô, làm vỡ sọ cô. Greg treo cổ tự vẫn trên cửa sổ.<strong>Phòng thu âm 666</strong> Vào năm 2019, Foo Fighters bị áp lực bởi người quản lý Jeremy Shill của họ để vượt qua sự ngăn cản của nhà văn của họ và thu âm một album mới. Cả nhóm di chuyển vào biệt thự, nơi mà Dave Grohl, thủ lĩnh Dave Grohl trở nên say mê với ngôi nhà như một nguồn cảm hứng. Một trong những trợ giúp công nghệ của họ, Krug, bị điện giật bởi dây điện và ban nhạc quyết định dành tặng album của họ cho anh ấy.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dave Grohl","avatar":""},{"name":"Taylor Hawkins","avatar":""},{"name":"Nate Mendel","avatar":""},{"name":"Pat Smear","avatar":""},{"name":"Chris Shiflett","avatar":""},{"name":"Rami Jaffee","avatar":""},{"name":"Whitney Cummings","avatar":""},{"name":"Leslie Grossman","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Jenna Ortega","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Kerry King","avatar":""},{"name":"Marti Matulis","avatar":""},{"name":"Lionel Richie","avatar":""},{"name":"John Carpenter","avatar":""},{"name":"Jason Trost","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Mike Escamilla","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324267);
