INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-2022', 'Bán Thân', 'Showroom', 'https://phimimg.com/upload/vod/20240827-1/b184826c861cdcbfc2462da6eb470670.jpg', 'https://phimimg.com/upload/vod/20240827-1/8bbb9a1c8fc36c4aa4befbdb639b2947.jpg', '<p>Liezel, một đặc vụ đầy tham vọng, biết rằng đồng nghiệp của cô, Susan, sử dụng cơ thể của cô để bán các căn hộ; vì vậy cô ấy bắt chước kế hoạch của mình. Khi thế trận lật ngược lại, Liezel bắt đầu đối mặt với từng hình phạt của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Quinn Carrillo","avatar":""},{"name":"Robb Guinto","avatar":""},{"name":"Kit Thompson","avatar":""},{"name":"Emilio Garcia","avatar":""},{"name":"Ralmon Mendoza","avatar":""},{"name":"Massimo Scofield","avatar":""},{"name":"Alvaro Oteyza","avatar":""},{"name":"Aaron Concepcion","avatar":""},{"name":"Paolo Rivero","avatar":""},{"name":"Elmo Elarmo Jr.","avatar":""},{"name":"Richard Solano","avatar":""},{"name":"Calvin Reyes","avatar":""},{"name":"VJ Vera","avatar":""},{"name":"Rayah Minioza","avatar":""},{"name":"KC Contreras","avatar":""},{"name":"Itan Magnaye","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324267);
