INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-hoa-ruc-lua', 'Rừng Hoa Rực Lửa', 'Desirable Flowers', 'https://phimimg.com/upload/vod/20240826-1/9585a421d7df7d8feaf04b174d62801e.jpg', 'https://phimimg.com/upload/vod/20240826-1/cf6e76877bb3aa145c5c715204b81d69.jpg', '<p>Đối với Pongdanai, người thừa kế của một tập đoàn nhập khẩu lớn, phụ nữ chỉ là những bông hoa tô điểm cho cuộc đời, anh có thể chọn lựa, vui đùa, rồi vứt bỏ. Thế nhưng, những người phụ nữ vẫn chấp nhận trở thành đóa hoa trong tay anh để đạt được mục đích riêng của mình. Và khi khu rừng ấy có quá nhiều bông hoa thì cuộc chiến để trở thành bông hoa duy nhất trong lòng Pongdanai cũng trở nên quyết liệt hơn bao giờ hết.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Puttichai Kasetsin","avatar":""},{"name":"Pimprapa Tangprabhaporn","avatar":""},{"name":"Thitipoom Techa-apaikhun","avatar":""},{"name":"Savika Chaiyadej","avatar":""},{"name":"Punyaporn Pongpipat","avatar":""},{"name":"Laknara Piatha","avatar":""},{"name":"Sirinart Sugandharat","avatar":""},{"name":"Nirut Sirijanya","avatar":""},{"name":"Supranee Charoenpol","avatar":""},{"name":"Tonon Wongboon","avatar":""},{"name":"Sarawut Martthong","avatar":""},{"name":"Tussaporn Pattanapasai","avatar":""},{"name":"Ornanong P","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324267);
