INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xua-co-ngoi-luu-ly', 'Xưa Có Ngói Lưu Ly', 'Memory Of Encaustic Tile', 'https://phimimg.com/upload/vod/20240825-1/02200298a43facc8073c5c9a1681f9ec.jpg', 'https://phimimg.com/upload/vod/20240825-1/37edb2ee9cc54a8c4b2d9a2e34808a04.jpg', '<p>Xưa Có Ngói Lưu Ly - Memory Of Encaustic Tile kể về Thiếu Tuyết, Trịnh Tố Niên, Trường Kỳ là con của những nghệ nhân tu sửa văn vật Cố Cung, ba người cùng nhau trải qua thời kỳ dịch SARS, trưởng thành lớn lên trong con ngõ cũ kỹ ở Bắc Kinh. Ba đứa trẻ thanh mai trúc mã, cũng bởi vì cá tính khác biệt mà lựa chọn con đường hoàn toàn khác nhau. Thiếu Tuyết bị ảnh hưởng bởi mẹ của Tố Niên, không muốn vì tình yêu mà từ bỏ tương lai vô hạn của mình, lựa chọn con đường thả hương. Còn Tố Niên lựa chọn kế thừa chí nguyện của mẹ mình, tiếp quản sửa văn vật, cảm nhận thời gian từ các văn vật bất tử, như được tiếp thêm sức mạnh. Trường Kỳ với thiên phú toán học đã sớm được đi du học, đêm trước ngày đi du học, cậu lựa chọn giấu kín tình cảm với Thiếu Tuyết. Trịnh Tố Niên và Thiếu Tuyết đã xác nhận tâm ý của nhau, nhưng lúc Thế Vận Hội Olympic đang diễn ra thì 2 người chia tay. Trải qua nhiều năm sau, lúc quay về thì tất cả mọi người dường như đều có được cuộc sống tốt đẹp hơn.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yukee Chen","avatar":""},{"name":"林一","avatar":""},{"name":"Zhang Tian''ai","avatar":""},{"name":"Sun Kai","avatar":""},{"name":"Yan Zidong","avatar":""},{"name":"Yuan Ran","avatar":""},{"name":"Tang Xu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324267);
