INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-thuong-khung-ban-dac-biet-4-duyen-khoi', 'Đấu Phá Thương Khung Bản Đặc Biệt 4 (Duyên Khởi)', 'Fights Break Sphere Special 4 (Origin)', 'https://phimimg.com/upload/vod/20240822-1/986dcb3f0dbb3ebfa5cf14987d2147e2.jpg', 'https://phimimg.com/upload/vod/20240822-1/9990844737546f9a7f97547e1df99ca1.jpg', '<p><span style="text-wrap: wrap;">Ba năm trước, Naran Yanran, thiếu gia của phái Yun Lan, vội vàng hủy bỏ hôn ước. Xiao Yan xấu hổ sau đó đã có một cuộc hẹn ba năm với Naran Yanran. Vì lần giao dịch này, Tiêu Viêm đã tu luyện không ngừng, từ ma thú sơn mạch đến sa mạc kinh nghiệm, từ luyện đan đến các loại hỏa diễm thiêu thân thống khổ, tất cả đều là để chứng minh cho câu nói của hắn: “Sông đông ba mươi năm, ba mươi năm đến phía tây sông, đừng coi thường những người trẻ tuổi đã mất tất cả. Bây giờ, những người trong gia đình Xiao nhất định sẽ đối mặt với thử thách và không bao giờ lùi bước. Con đường phát triển của Xiao Yan vẫn tiếp tục.……</span></p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324267);
