INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-sieu-nhan-dien-quang', 'Tân Siêu Nhân Điện Quang', 'Shin Ultraman', 'https://phimimg.com/upload/vod/20230925-1/1015b9eaba4c353997d8e3afd3b43271.jpg', 'https://phimimg.com/upload/vod/20230925-1/4d4128640c06bfb2a05d5104b2b8dbe3.jpg', '<p>Chính phủ Nhật Bản thành lập đội đặc nhiệm để chống lại những sinh vật khổng lồ bất ngờ xuất hiện trên khắp đất nước. Chẳng bao lâu, đội bất ngờ gặp một hình người khổng lồ màu bạc bắt đầu xuất hiện mỗi khi bị quái vật không gian tấn công!</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Takumi Saitoh","avatar":""},{"name":"Masami Nagasawa","avatar":""},{"name":"Hidetoshi Nishijima","avatar":""},{"name":"Daiki Arioka","avatar":""},{"name":"Akari Hayami","avatar":""},{"name":"Tetsushi Tanaka","avatar":""},{"name":"Kōji Yamamoto","avatar":""},{"name":"Ryo Iwamatsu","avatar":""},{"name":"Kyūsaku Shimada","avatar":""},{"name":"Toru Masuoka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324267);
