INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-nong-bong', 'Người Tình Nóng Bỏng', 'Relyebo', 'https://phimimg.com/upload/vod/20240819-1/72081e56027e31781996c586b9ef4f20.jpg', 'https://phimimg.com/upload/vod/20240819-1/4b667e4f8a05524c34ba77ed1de27e50.jpg', '<p>Một nhân viên bảo vệ bị quyến rũ bởi một người thuê nhà nóng bỏng mà anh ta gọi là cô F. Tưởng tượng tình dục của anh ta sẽ đưa anh ta đến cực điểm sẽ thay đổi cuộc sống của anh ta và vợ anh ta mãi mãi.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Christine Bermas","avatar":""},{"name":"Sean de Guzman","avatar":""},{"name":"Jela Cuenca","avatar":""},{"name":"Jeric Raval","avatar":""},{"name":"Lara Morena","avatar":""},{"name":"Carlene Aguilar","avatar":""},{"name":"Jeffrey Hidalgo","avatar":""},{"name":"Juliana Parizcova Segovia","avatar":""},{"name":"Giovanni Baldisseri","avatar":""},{"name":"Juan Carlo Tarobal","avatar":""},{"name":"Francis Mata","avatar":""},{"name":"Angel Raymundo","avatar":""},{"name":"Abraham Gonzales","avatar":""},{"name":"Punky Taguines","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324267);
