INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-tre', 'Người Mẹ Trẻ', 'Pamasahe', 'https://phimimg.com/upload/vod/20230923-1/8623386e73d81fdd2887df9b23ea953f.jpg', 'https://phimimg.com/upload/vod/20230923-1/83cfb4390d28434d336a6bca2a50f6bd.jpg', '<p>Một người mẹ không một xu dính túi cùng đứa con sơ sinh của mình thực hiện cuộc hành trình bằng đường bộ và đường biển để tìm chồng ở Manila. Nhưng chuyến đi này sẽ không miễn phí vì cô phải sử dụng cơ thể của mình để đến đích.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Mark Anthony Fernandez","avatar":""},{"name":"Felix Roco","avatar":""},{"name":"Azi Acosta","avatar":""},{"name":"Julio Diaz","avatar":""},{"name":"Shirley Fuentes","avatar":""},{"name":"Shiena Yu","avatar":""},{"name":"Alvaro Oteyza","avatar":""},{"name":"Rash Flores","avatar":""},{"name":"Richard Solano","avatar":""},{"name":"Erlinda Villalobos","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324267);
