INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chom-sao-thien-hau', 'Chòm Sao Thiên Hậu', 'Cassiopeia', 'https://phimimg.com/upload/vod/20240819-1/469cac6c9b9fa712acea0072eaa565e5.jpg', 'https://phimimg.com/upload/vod/20240819-1/fc39a79ff6e6183f00056ec219157830.jpg', '<p>Phim kể về Soo-Jin, một luật sư và người mẹ đơn thân, sau khi ly hôn, cô phát hiện mình mắc bệnh Alzheimer. Cha của cô, In-Woo, bắt đầu đồng hành cùng Soo-Jin và con gái của cô để họ có thể sống tiếp dù cô dần mất đi ký ức.</p>', 'Full', 1, 'single', 'completed', 4, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"안성기","avatar":""},{"name":"서현진","avatar":""},{"name":"Joo Ye-rim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324267);
