INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-ngan-vang-cua-selina', 'Cái Ngàn Vàng Của Selina', 'Selina''s Gold', 'https://phimimg.com/upload/vod/20240819-1/bfb49217fc96eb2adb11a59752703c38.jpg', 'https://phimimg.com/upload/vod/20240819-1/24a179a81fa9b70ff6f4d827827f99f6.jpg', '<p>Cha của Selina bán cô cho Tiago, người đã biến cô thành nô lệ tình dục. Với sự giúp đỡ của Domeng, nô lệ mù của Tiago, cô lên kế hoạch thoát khỏi địa ngục trần gian này.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Angeli Khang","avatar":""},{"name":"Gold Aceron","avatar":""},{"name":"Jay Manalo","avatar":""},{"name":"Azi Acosta","avatar":""},{"name":"Soliman Cruz","avatar":""},{"name":"Aurora Sevilla","avatar":""},{"name":"Mickey Ferriols","avatar":""},{"name":"Archie Adamos","avatar":""},{"name":"Gwen Garci","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324267);
