INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tha-thi-thien-ha', 'Thả Thí Thiên Hạ', 'Who Rules The World', 'https://phimimg.com/upload/vod/20240814-1/b9fd0dcca05596dab60e8f265569ee80.jpg', 'https://phimimg.com/upload/vod/20240814-1/3a7bf74e4b432cf72feb8278f9b5f506.jpg', '<p>Phim chuyển từ tiểu thuyết ngôn tình võ hiệp cùng tên rất được yêu thích của tác giả Khuynh Linh Nguyệt. Phim lấy bối cảnh các quốc gia tranh đấu để giành thiên hạ. Nội dung xoay quanh hành trình chinh phục giang hồ và thiên hạ của nữ chính Bạch Phong Tịch, người được đồn sẽ thay đổi số mệnh của các quốc gia. Trong đó, Bạch Phong Tịnh và Hắc Phong Tức là một đôi tri kỷ hơn 10 năm trời, đồng thời cũng là kỳ phùng địch thủ đáng gờm. Tình yêu của hai người bị cách trở khi cả hai đều là những người đứng đầu mỗi quốc gia.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"杨洋","avatar":""},{"name":"赵露思","avatar":""},{"name":"Zhang Fengyi","avatar":""},{"name":"Carman Lee Yeuk-Tung","avatar":""},{"name":"Xuan Lu","avatar":""},{"name":"Lai Yi","avatar":""},{"name":"Liu Ruilin","avatar":""},{"name":"An Yuexi","avatar":""},{"name":"He Kai Lang","avatar":""},{"name":"张昊唯","avatar":""},{"name":"黄毅","avatar":""},{"name":"Wang Xuan","avatar":""},{"name":"Zhao Zhuoting","avatar":""},{"name":"Jiang Kai","avatar":""},{"name":"Zhao Xin","avatar":""},{"name":"Cui Enci","avatar":""},{"name":"Zheng Xiaoning","avatar":""},{"name":"Wang Gang","avatar":""},{"name":"Ma Yue","avatar":""},{"name":"Fu Bohan","avatar":""},{"name":"Lin Xuepiao","avatar":""},{"name":"Jie Bing","avatar":""},{"name":"Li Yixuan","avatar":""},{"name":"Lu Shun","avatar":""},{"name":"Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa2