INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-tu-nhien', 'Siêu Tự Nhiên', 'Super/Natural', 'https://phimimg.com/upload/vod/20240731-1/fb79e0e79b9884cd21f9d6c55eae5105.jpg', 'https://phimimg.com/upload/vod/20240731-1/b25b49a37b83a3ca13b29887643dd354.jpg', '<p>Sử dụng những cải tiến khoa học mới nhất và công nghệ làm phim tiên tiến, bộ phim tài liệu này tiết lộ sức mạnh bí mật và siêu giác quan của những loài động vật phi thường nhất thế giới, đồng thời mời người xem nhìn và nghe vượt xa nhận thức thông thường của con người để trải nghiệm thế giới tự nhiên như một loài cụ thể. - từ việc nhìn thấy những bông hoa trong tầm nhìn của loài ong đến việc nghe lén cuộc trò chuyện giữa hải cẩu voi cho đến việc bay vút dọc theo chiều dài của một sân bóng với những con sóc phát sáng trong bóng tối.</p>', 'Tập 6', 6, 'series', 'ongoing', 12, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Benedict Cumberbatch","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324267);
