INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-di-hia-dieu-uoc-cuoi-cung', 'Mèo Đi Hia: Điều Ước Cuối Cùng', 'Puss in Boots: The Last Wish', 'https://phimimg.com/upload/vod/20231018-1/92c0979037fe08f819bb2ef466c05faf.jpg', 'https://phimimg.com/upload/vod/20231018-1/83214ada07319d8530b2b12358efb2c0.jpg', '<p>Puss phát hiện ra rằng niềm đam mê phiêu lưu mạo hiểm của anh đã gây ra hậu quả: Anh đã đốt cháy 8 trong số 9 mạng sống của mình, bây giờ chỉ còn lại đúng một mạng. Anh ta bắt đầu một cuộc hành trình để tìm Điều ước cuối cùng thần thoại trong Rừng Đen nhằm khôi phục lại chín mạng sống của mình. Chỉ còn một mạng sống, đây có lẽ sẽ là cuộc hành trình nguy hiểm nhất của Puss.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Antonio Banderas","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Harvey Guillén","avatar":""},{"name":"Wagner Moura","avatar":""},{"name":"Florence Pugh","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Samson Kayo","avatar":""},{"name":"John Mulaney","avatar":""},{"name":"Da''Vine Joy Randolph","avatar":""},{"name":"Anthony Mendez","avatar":""},{"name":"Kevin McCann","avatar":""},{"name":"Bernardo de Paula","avatar":""},{"name":"Betsy Sodaro","avatar":""},{"name":"Artemis Pebdani","avatar":""},{"name":"Conrad V","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '