INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-bi-an-chua-loi-dap-phan-3', 'Những bí ẩn chưa lời đáp (Phần 3)', 'Unsolved Mysteries (Season 3)', 'https://phimimg.com/upload/vod/20240731-1/dae54a1145831e3dce58ffa448273c9c.jpg', 'https://phimimg.com/upload/vod/20240731-1/617cb620f0f9e903fb0de4b1d8a2c4cf.jpg', '<p>Với những án mạng chấn động, trường hợp đụng độ siêu nhiên và vụ mất tích khó lý giải nhưng hoàn toàn có thật, loạt phim tài liệu nổi tiếng trở lại đầy hấp dẫn.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
