INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-hon-phan-1', 'Hoàn Hồn (Phần 1)', 'Alchemy Of Souls (Season 1)', 'https://phimimg.com/upload/vod/20240730-1/f8112a7e4e751ff1042e2f1aece37f54.jpg', 'https://phimimg.com/upload/vod/20240730-1/f953715518dc9cffd5458ed78b41026d.jpg', '<p>Một phù thủy quyền năng trong cơ thể của một phụ nữ mù tình cờ gặp người đàn ông xuất thân từ gia đình danh giá, cũng là người muốn cô giúp thay đổi số phận của mình.

Jang Wook tình cờ gặp Deok Yi. Cô ấy là một chiến binh ưu tú, nhưng linh hồn của cô ấy lại bị mắc kẹt trong một cơ thể yếu ớt . Cô trở thành người hầu của Jang Wook, nhưng cô cũng bí mật dạy anh cách chiến đấu.

Seo Yool xuất thân từ gia đình Seo quý tộc. Anh ta có vẻ ngoài hoàn hảo với ngoại hình đẹp, trí thông minh và kỹ năng võ thuật cao cường. Go Won là thái tử của Daeho. Anh ấy hy vọng sẽ trở thành một vị vua hào phóng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이재욱","avatar":""},{"name":"고윤정","avatar":""},{"name":"민현","avatar":""},{"name":"신승호","avatar":""},{"name":"유준상","avatar":""},{"name":"오나라","avatar":""},{"name":"유인수","avatar":""},{"name":"아린","avatar":""},{"name":"조재윤","avatar":""},{"name":"도상우","avatar":""},{"name":"박은혜","avatar":""},{"name":"임철수","avatar":""},{"name":"홍서희","avatar":""},{"name":"이도경","avatar":""},{"name":"이하율","avatar":""},{"name":"서혜원","avatar":""},{"name":"Kim Yong-jin","avatar":""},{"name":"정지안","avatar":""},{"name":"Cha Yong-hak","avatar":""},{"name":"최광일","avatar":""},{"name":"심소영","avatar":""},{"name":"박소진","avatar":""},{"name":"Lee Ji-hoo","avatar":""},{"name":"Song Seung-hwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324267);
