INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-diet-vong-phan-4', 'Biệt Đội Diệt Vong (Phần 4)', 'Doom Patrol (Season 4)', 'https://phimimg.com/upload/vod/20240729-1/17c101051d7cbf2309a07d8c0309f1cf.jpg', 'https://phimimg.com/upload/vod/20240729-1/6fca83ef03d2a1ae48babf5096fb1db7.jpg', '<p>Doom Patrol là loạt phim truyền hình web của Mỹ được tạo bởi Jeremy Carver cho DC Universe. Dựa trên nhóm siêu anh hùng cùng tên của DC Comics, bộ truyện có Jane, Rita Farr, Vic Stone, Larry Trainor, Cliff Steele, và Chief là thành viên của Doom Patrol. Lấy bối cảnh năm 2019, nhóm Doom Patrol - bao gồm Robotman, Negative Man, Elasti-Woman, Crazy Jane cùng thành viên mới Cyborg dưới sự dẫn dắt của Dr. Niles Caulder - nhận nhiệm vụ bảo vệ thế giới khỏi kẻ thù nguy hiểm tên là Mr. Nobody.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Diane Guerrero","avatar":""},{"name":"April Bowlby","avatar":""},{"name":"Joivan Wade","avatar":""},{"name":"Skye Roberts","avatar":""},{"name":"Riley Shanahan","avatar":""},{"name":"Matthew Zuk","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Brendan Fraser","avatar":""},{"name":"Michelle Gomez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324267);
