INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-von-chuot-phan-4', 'Mèo Vờn Chuột (Phần 4)', 'Killing Eve (Season 4)', 'https://phimimg.com/upload/vod/20240729-1/dd0c8548d9143fcded550795f0989726.jpg', 'https://phimimg.com/upload/vod/20240729-1/9b30b114686e3123c2827024ffca0f45.jpg', '<p>Dù không còn làm ở cơ quan tình báo, Eve vẫn tiếp tục săn lùng Hội Thập Nhị để trả thù. Villanelle ẩn náu tại một nhà thờ ở Anh với mong muốn chuộc tội cho những tội ác đã gây ra trước kia. Và một trong những thử thách lớn nhất của Villanelle lúc này là thuyết phục Eve tin vào quyết tâm hối cải của cô.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sandra Oh","avatar":""},{"name":"Jodie Comer","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Kim Bodnia","avatar":""},{"name":"Camille Cottin","avatar":""},{"name":"Robert Gilbert","avatar":""},{"name":"Anjana Vasan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324267);
