INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-rong-phan-4', 'Hoàng Tử Rồng (Phần 4)', 'The Dragon Prince (Season 4)', 'https://phimimg.com/upload/vod/20240727-1/465659e1a94ce1ccb1054c5802fb8a02.jpg', 'https://phimimg.com/upload/vod/20240727-1/582c7bb37268df4145a6e1dd9dace845.jpg', '<p>Hai năm sau, khi Claudia dấn sâu hơn vào thế giới yêu thuật, Callum, Ezran và bạn bè gấp rút ngăn cô giải thoát cho Aaravos hùng mạnh.Một khám phá bất ngờ đã thôi thúc hai hoàng tử loài người và một sát thủ yêu tinh lùn hợp tác với nhau trong công cuộc mang lại hòa bình cho các vùng đất chiến tranh.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 4, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jack De Sena","avatar":""},{"name":"Sasha Rojen","avatar":""},{"name":"Jason Simpson","avatar":""},{"name":"Racquel Belmonte","avatar":""},{"name":"Jesse Inocalla","avatar":""},{"name":"Erik Dellums","avatar":""},{"name":"Paula Burrows","avatar":""},{"name":"Omari Newton","avatar":""},{"name":"Vincent Tong","avatar":""},{"name":"Rena Anakwe","avatar":""},{"name":"Jonathan Holmes","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324267);
