INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-bat-phan-2', 'Nắm Bắt Phần 2', 'The Capture Season 2', 'https://phimimg.com/upload/vod/20240719-1/626c55fb38dbaa5f00fb24332b29c796.jpg', 'https://phimimg.com/upload/vod/20240719-1/6e09f6d5a6b67c6690ea98e952200861.jpg', '<p>Gia nhập đơn vị “Chỉnh sửa” của chính Vương quốc Anh, DCI Rachel Carey nhận ra mình đang vướng vào một âm mưu mới – với mục tiêu mới. Nhưng làm sao cô có thể giải quyết vụ án này khi ngay cả những đồng nghiệp thân cận nhất của mình cũng không thể tin tưởng được? Series hai kể về những sát thủ “vô hình”, sự trỗi dậy đáng sợ của công nghệ deepfake, căng thẳng ngày càng gia tăng giữa chính phủ và Big Tech cũng như nạn tham nhũng trong lòng truyền thông Anh.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2022, 'Thuyết Minh', 'FullHD', 'Anh', 0, '[{"name":"Holliday Grainger","avatar":""},{"name":"Ben Miles","avatar":""},{"name":"Lia Williams","avatar":""},{"name":"Paapa Essiedu","avatar":""},{"name":"Indira Varma","avatar":""},{"name":"Charlie Murphy","avatar":""},{"name":"Tessa Wong","avatar":""},{"name":"Andy Nyman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
