INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-to-vien-quan-su-doberman', 'Công Tố Viên Quân Sự Doberman', 'Military Prosecutor Doberman', 'https://phimimg.com/upload/vod/20240126-1/9c3c17127cbdd6112c9e272bf4c695c6.jpg', 'https://phimimg.com/upload/vod/20240126-1/326d2e2dfc704648c9ad3766fa4c1619.jpg', '<p>Bộ phim truyền hình Hàn Quốc Công Tố Viên Quân Sự Doberman do đạo diễn phim Chip In Chin ChanGyu và biên kịch Yoon Hyun Ho của phim Luật sư vô pháp đồng sản xuất.Công Tố Viên Quân Sự Doberman kể về câu chuyện Doberman (do Ahn BoHyun thủ vai) vì tiền nên trở thành công tố viên, và Cha WooIn (do Cho BoAh thủ vai), người trở thành công tố viên quân đội để trả thù. Sau khi hai người gặp nhau đã cùng chung tay tìm và phá bỏ cái đen tối thối rừa trong quân đội, trải qua những khó khăn hai người đã trưởng thành hơn và trở thành những công tố viên thực thụ.Ahn BoHyun đóng vai công tố viên quân độiDobman</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cho Bo-ah","avatar":""},{"name":"Yeon-su Oh","avatar":""},{"name":"Kim Yeong Min","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
