INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nao-cun-con', 'Đi Nào, Cún Con!', 'Đi Nào, Cún Con!', 'https://phimimg.com/upload/vod/20240608-1/28f34147d5032a7ec1ffbdc79e86cfc8.jpg', 'https://phimimg.com/upload/vod/20240608-1/859278fd1bcb5e63af34798889f59c26.jpg', '<p>Thống kê cho thấy, tổng số vật nuôi của cả Trung Quốc khoảng 100 triệu con, trong đó gần 5% là chó nghiệp vụ tham gia các hoạt động xã hội. Từ truy dấu buôn lậu hay truy đuổi kẻ sát nhân đến nơi xảy ra thảm họa nguy hiểm, cả đời chúng hết lòng vì nghĩa vụ và phục vụ xã hội. Tuy nhiên, khi chó nghiệp vụ ngày càng được công nhận và số lượng tăng đột biến, gần một nghìn chú chó nghiệp vụ phải chọn nghỉ hưu mỗi năm do nhiều nguyên nhân như tuổi tác, bệnh tật, thương tật. Đáng tiếc, thói quen làm việc lâu năm cộng với tâm lý căng thẳng khiến những chú chó nghiệp vụ đã nghỉ hưu này khó thích nghi với cuộc sống xã hội, thậm chí nhiều lần phải đối mặt với tình huống bị từ chối nuôi dưỡng.</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324267);
