INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kung-fu-panda-hiep-si-rong-phan-3', 'Kung Fu Panda: Hiệp Sĩ Rồng (Phần 3)', 'Kung Fu Panda: The Dragon Knight (Season 3)', 'https://phimimg.com/upload/vod/20240608-1/b69a794d3df735dce26efc0c1f028402.jpg', 'https://phimimg.com/upload/vod/20240608-1/13ec0f343f1cb9f6039bdfa31015a8cd.jpg', '<p>Trong hành trình gấp rút phá hủy vĩnh viễn vũ khí Tianshang toàn năng, các Hiệp Sĩ Rồng đối đầu với những kẻ thù vừa quen thuộc vừa không ngờ tới.</p>', 'Hoàn Tất (19/19)', 19, 'hoathinh', 'completed', 21, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Black","avatar":""},{"name":"Rita Ora","avatar":""},{"name":"James Hong","avatar":""},{"name":"Chris Geere","avatar":""},{"name":"Amy Hill","avatar":""},{"name":"Nolan North","avatar":""},{"name":"Della Saba","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324267);
