INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kung-fu-panda-hiep-si-rong-phan-3', 'Kung Fu Panda: Hiệp Sĩ Rồng (Phần 3)', 'Kung Fu Panda: The Dragon Knight (Season 3)', 'kung fu panda: hiệp sĩ rồng (phần 3) kung fu panda: the dragon knight (season 3) jack black rita ora james hong chris geere amy hill nolan north della saba ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-x-yakuza', 'Cảnh Sát X Yakuza', 'Kei X Yaku - Dangerous Buddy', 'https://phimimg.com/upload/vod/20240608-1/806fc35c69e228311a62aa9a490e5a79.jpg', 'https://phimimg.com/upload/vod/20240608-1/f21f5a25c564bd87a4a4172d944b3ff8.jpg', '<p>Ichirou (do Suzuki Nobuyuki thủ vai), một điều tra viên trực thuộc Cảnh sát đô thị Bộ Công an, nhận lệnh từ Trưởng phòng Taguchi (do Tokui Yoshimi thủ vai) đã tiến hành điều tra Hanabusa Shirou (do Inukai Atsuhiro thủ vai), thiếu gia của một tập đoàn vũ trang. Sau khi nắm giữ quyền hạn trong tổ chức với một tốc độ nhanh không tưởng, hắn đã xây dựng các mối quan hệ mật thiết với những nhân vật lớn trong nhiều lĩnh vực để khuếch trương sức ảnh hưởng của mình. Tại sao Bộ Công an lại chú ý đến một tên Yakuza? Bộ trưởng Taguchi không màn giải đáp thắc mắc ấy của Ichirou. Trong quá trình theo dõi Shirou, Ichirou đã phát hiện ra việc hắn đang điều hành một đấu trường bất hợp pháp với vỏ bọc salon giới hạn thành viên do mình quản lý. Ichirou đóng giả thành người tham gia và trà trộn vào đấu trường, nhưng thân phận của anh nhanh chóng bị Shirou phát giác. Hắn đưa ra một kèo cá cược, rằng nếu Ichirou thua, hắn sẽ dùng mọi thủ đoạn để moi được thông tin từ anh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nobuyuki Suzuki","avatar":""},{"name":"Atsuhiro Inukai","avatar":""},{"name":"Chiaki Kuriyama","avatar":""},{"name":"Yoshimi Tokui","avatar":""},{"name":"Itsuji Itao","avatar":""},{"name":"Matsu","avatar":""},{"name":"Kaito Yoshimura","avatar":""},{"name":"Minori Hagiwara","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324267);
