INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-dien-cuong', 'Tình Yêu Điên Cuồng', 'Crazy Love', 'https://phimimg.com/upload/vod/20240608-1/fde0562a78e57707da6221bddde4236b.jpg', 'https://phimimg.com/upload/vod/20240608-1/9accb37a75698bf3e9e08a43d3bb3a14.jpg', '<p>No Go Jin là giảng viên toán học nổi tiếng nhất trong lĩnh vực giáo dục tư nhân và là Giám đốc điều hành của GOTOP Education. Mặc dù chỉ có trình độ học vấn trung học phổ thông, nhưng anh ấy đã đạt được tất cả thành công nhờ trí thông minh vượt trội của mình. Anh ấy có vẻ là một người đàn ông hoàn hảo với vẻ ngoài đẹp trai, chỉ số IQ cao và giàu có. Anh ấy cũng tự ái. Một ngày nọ, anh ta đột nhiên được cảnh báo rằng anh ta sẽ bị sát hại. Lee Shin A làm thư ký của No Go Jin. Cô ấy là một nhân viên siêng năng và có trách nhiệm. Do tính cách trầm lặng và hướng nội nên cô ít có mặt với sếp No Go Jin và đồng nghiệp tại nơi làm việc. Các đồng nghiệp của cô bắt đầu nhận ra cô, vì cô đã làm việc cho No Go Jin khét tiếng hơn 1 năm. Sau đó, cô biết rằng cô không còn nhiều thời gian để sống.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jae Wook","avatar":""},{"name":"Krystal","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324267);
