INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-chi-dinh-nhan-vat-yeu-duong', 'Mời Chỉ Định Nhân Vật Yêu Đương', 'Designated Love', 'https://phimimg.com/upload/vod/20240608-1/142fbdd01ae2d6620dfccdcc1e3858e4.jpg', 'https://phimimg.com/upload/vod/20240608-1/9c1efd3b67af41b5ddb172f12358c34d.jpg', '<p>Tần Tịch, giám đốc nghệ thuật của công ty game trước giờ chỉ biết đến yêu đương, sau khi thất tình bị cuốn vào game Hành hạ bạn trai cũ. Nào ai ngờ đâu, người bạn trai cũ trong game và bạn trai cũ ngoài đời lại giống y hệt nhau. Từng bước khám phá về người bạn trai hai mặt, cô đi hết từ bất ngờ này đến bất ngờ khác.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fan Wei","avatar":""},{"name":"Cui Yuxin","avatar":""},{"name":"Boa","avatar":""},{"name":"Yu Yifu","avatar":""},{"name":"Cheng Zhiwei","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324267);
