INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-tu-ky', 'Trân Tu Ký', 'Delicacies Destiny', 'https://phimimg.com/upload/vod/20240608-1/6a7edef57166e9f6894613f7da369677.jpg', 'https://phimimg.com/upload/vod/20240608-1/1b81ef8d69af9bf0ca1b06aa63aed694.jpg', '<p>Nữ đầu bếp trẻ tuổi Lăng Tiểu Tiểu được thái tử Chu Thọ Khuê yêu thích cho vào Trân Tu Phòng, lập chí trở thành Thiên Hạ Đệ Nhất Ngự Trù. Đối diện với nhiều lần thử thách của Tấn vương, Lý quý phi, hoàng hậu, Lăng Tiểu Tiểu nhờ sự giúp đỡ của thái tử cùng tài nấu nướng cao siêu và phẩm đức hiền lành của mình đã dần dần hoá giải được hết nguy cơ, thắng được lòng tin của các cung nhân, cũng phát triển tình yêu cùng thái tử. Nhưng thân là thái tử phi tương lai, cô bị đế hậu cấm không cho vào nhà bếp nữa. Trải qua khó khăn lựa chọn, Lăng Tiểu Tiểu rời cung tiếp tục làm đầu bếp, thái tử đau buồn không dứt, cuối cùng giả chết, từ bỏ ngôi thái tử để theo Lăng Tiểu Tiểu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Thuỵ Hiền","avatar":""},{"name":"Lạt Mục Dương Tử","avatar":""},{"name":"Lưu Mẫn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324267);
