INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-gia-100-won', 'Quản Gia 100 Won', 'May I Help You', 'https://phimimg.com/upload/vod/20240608-1/a1c2e0ede1bbdd42b0c62b5d8cf4f871.jpg', 'https://phimimg.com/upload/vod/20240608-1/285024bb74e60b3303c687462dcebf68.jpg', '<p>Có một cô gái làm giám đốc nhà tang lễ tên là Baek Dong Ju. Cô ấy có một khả năng cho phép cô ấy nhìn thấy và nói chuyện với những người đã chết. Baek Dong Ju được người chết yêu cầu ban điều ước cuối cùng của họ. Nếu Baek Dong Ju không thực hiện điều ước của họ, một ngày của cô ấy sẽ đầy bất hạnh. Người làm việc vặt thuộc sở hữu của chú anh ta, người tên là Lee Gyu Han. Thay bóng đèn là một trong những việc nhỏ mà Ildangbaek có thể làm cho khách hàng. Kim Jib Sa làm mọi thứ có thể cho khách hàng của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Hyeri","avatar":""},{"name":"Lee Jun Young","avatar":""},{"name":"Song Duk Ho","avatar":""},{"name":"Lee Gyu Han","avatar":""},{"name":"Tae In-Ho","avatar":""},{"name":"Park Soo Young","avatar":""},{"name":"Oh Dae Hwan","avatar":""},{"name":"Seo Hye Won","avatar":""},{"name":"Ahn Hyun Ho","avatar":""},{"name":"Han Dong Hee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324267);
