INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-sang-trong-dem-dong-cua-em', 'Tỏa Sáng Trong Đêm Đông Của Em', 'Winter Night', 'https://phimimg.com/upload/vod/20240603-1/02edfa578ad67c57d4b3a53768a7e7cb.jpg', 'https://phimimg.com/upload/vod/20240603-1/130fd80188e409dba36884dd8a1e9bb2.jpg', '<p>Trịnh Đạt Tiền, một nhân viên bình thường ở công ty phải chịu hai cú sốc liên tiếp trong cả công việc lẫn tình yêu. Cuộc sống vất vưởng trong thành phố của cô bỗng chốc thay đổi khi nhận được khoản tiền đền bù di dời. Trên đường về quê, một trận mưa sao băng lửa gây ra trận bão từ và cuốn cô vào thế giới song song. Gia đình đổ vỡ bỗng hoàn chỉnh như xưa, ngay cả mối tình đầu của cô là Mộ Tử Lý cũng xuất hiện một cách vô cùng thần kỳ. Đã không thể trở lại thế giới ban đầu, Trịnh Đạt Tiền quyết định nắm chắc cơ hội này để bù đắp lại từng nuối tiếc đã qua. Thế nhưng, ngay lúc cuộc sống đang có khởi sắc, mưa sao băng lửa lại xuất hiện khiến cặp tình nhân Trình Đạt Tiền và Mộ Tử Lý bị chia cắt ở hai thế giới không có điểm nối.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kiều Hân","avatar":""},{"name":"Mã Tư Siêu","avatar":""},{"name":"Chu Dực Nhiên","avatar":""},{"name":"Vương Vi","avatar":""},{"name":"Diệp Tiểu Vĩ","avatar":""},{"name":"Nhâm Soái","avatar":""},{"name":"Hách Dương","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
