INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-cuoi-nang-phu-thuy', 'Tình Cuối Nàng Phù Thuỷ', 'My Queen Thai Ver', 'https://phimimg.com/upload/vod/20240603-1/e5be91b7470baa2870012ebfaf48c0e2.jpg', 'https://phimimg.com/upload/vod/20240603-1/516f00780f7c096d35732bb38f8c2aba.jpg', '<p>Bị chồng sắp cưới bỏ rơi trước khi cử hành hôn lễ, điều đó đã trở thành ám ảnh tâm lý của Bee khiến cô không dám yêu đương hay mở lòng với bất kỳ ai, dù bản thân là một người phụ nữ thành đạt, có tất cả. Tuy nhiên, thần tình yêu cuối cùng cũng gõ cửa trái tim cô một lần nữa khi tình cờ làm việc chung và nảy sinh tình cảm với Neng – sinh viên y khoa có bạn gái đột nhiên biến mất.<br/>Mối tình chị em đang trên đà phát triển và nảy nở, thì bỗng một ngày vị hôn phu cũ của Bee trở về, chuyện gì sẽ diễn ra tiếp theo? Liệu vị hôn phu của Bee có quyết tâm dành lại cô và trước tình huống như vậy, Neng sẽ có động thái gì để bảo vệ tình yêu của mình?</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Bee Namthip","avatar":""},{"name":"Neng Sarun","avatar":""},{"name":"Gunsmile Chanagun","avatar":""},{"name":"Mook Worranit","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
