INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nham-chi-dau', 'Yêu Nhầm Chị Dâu', 'The Love Proposal', 'https://phimimg.com/upload/vod/20240603-1/4cb6b5e932b6b8db9bcb0ab5ece9035f.jpg', 'https://phimimg.com/upload/vod/20240603-1/dab1414d5e3b69e56df4566fbb0b7938.jpg', '<p>Một lần thất bại trong tình yêu khiến Time dè dặt và không vội vàng để yêu một ai khác. Và rồi định mệnh như trêu đùa khi để anh phải lòng Treenuch, nhưng họ lại chẳng thể bước bên nhau. Hơn thế nữa, khi người anh trai Thatthai chen ngang vào tình yêu của anh và cô khiến mối quan hệ giữa họ trở thành cuộc tình tay ba đầy trái ngang.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Tre Porapat Srikajorn","avatar":""},{"name":"Ferny Nopjira Lerkkajornnamkul","avatar":""},{"name":"Toy Pathompong Reonchaidee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
