INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-bong-trung-dien', 'Dưới Bóng Trung Điện', 'Under The Queen''s Umbrella', 'https://phimimg.com/upload/vod/20240603-1/18e7cf1acdff5890128e735c9a2396c7.jpg', 'https://phimimg.com/upload/vod/20240603-1/b912e96588021537ce2a5d4c2a1be2b1.jpg', '<p>Một trung điện mạnh mẽ cố rèn những đứa con gây rối vào khuôn phép để một trong số họ có thể trở thành vị vua tiếp theo của Joseon, trong khi các đối thủ ganh đua giành ngai vàng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hye Soo","avatar":""},{"name":"Kim Hae Sook","avatar":""},{"name":"Choi Won Yeong","avatar":""},{"name":"Kim Eui Sung","avatar":""},{"name":"Moon Sang Min","avatar":""},{"name":"Ok Ja Yeon","avatar":""},{"name":"Kang Chan Hee","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324267);
