INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('new-normal-zine', 'New Normal Zine', 'New Normal Zine', 'https://phimimg.com/upload/vod/20240603-1/d58f3a052adc7e62c6ce934670188e6d.jpg', 'https://phimimg.com/upload/vod/20240603-1/129761549204942e4ad04d969d03c263.jpg', '<p>Cha Ji Min là một phụ nữ độc thân theo đuổi lối sống chậm rãi. Cô làm phóng viên tin tức địa phương cho một tạp chí, nhưng không may tạp chí đó bị đóng cửa. Sau đó, cô bắt đầu làm biên tập viên cho tạp chí kỹ thuật số New Normal Zine thuộc cùng một công ty mẹ. Ở đó, sếp mới của cô là Tổng biên tập Song Ro Ji. Cha Ji Min và Song Ro Ji quen biết nhau, khi họ bắt đầu làm việc cho công ty mẹ vào cùng năm. Song Ro Ji là một người nghiện công việc và hoàn toàn khác với Cha Ji Min, do vậy Cha Jin Min phải bắt đầu tìm cách tồn tại ở nơi này.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
