INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('new-normal-zine', 'New Normal Zine', 'New Normal Zine', 'new normal zine new normal zine  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-ra-la-thay-giao', 'Hóa Ra Là Thầy Giáo!', 'Brilliant Class 8', 'https://phimimg.com/upload/vod/20240603-1/bbc1d2ac39b8a65e960f506d7d07fc6f.jpg', 'https://phimimg.com/upload/vod/20240603-1/f2e0ab03ec88170cbdc3bdce58336ca1.jpg', '<p>Hóa Ra Là Thầy Giáo xoay quay câu chuyện của Hướng Đông Nam, là một ca sĩ-nhạc sĩ tài năng, từng trở thành siêu sao một cách suôn sẻ sau khi bắt đầu sự nghiệp từ chương trình tuyển chọn nghệ sĩ. Nhưng 5 năm sau, anh ấy gặp khó trong quá trình sáng tác, không những vướng bê bối, mà còn bị nhiều người mắng cút khỏi giới giải trí bởi sự hiểm nhầm ăn cắp. Đã đến cùng đường, trợ lý Lâm Thanh hợp tác với hiệu trưởng trường trung học, mượn cớ chương trình thực tế đòi Hướng Đông Nam trở thành một thầy giáo. Sau được biết sự thật, Hướng Đông Nam đành phải để lại ở trường cũ của mình bởi khế ước tinh thần. Bởi vậy, siêu sao mắc nạn trở thành thầy chủ nhiệm của lớp nghệ thuật trong trường, lại bất ngờ trở thành bạn cùng phòng với cô tiếng Anh Tô Kỳ và thầy toán Trần Lục Tam. Khi siêu sao lười cực gặp gỡ người ham mê hồ sơ vừa nhiệt huyết vừa cố chấp, chuyện hài giữa các oan gia ùn ùn đến. Như thế, Hướng Đông Nam và các bạn lảo đảo trên đường, giúp học sinh tìm được bản thân mình trong các nỗi buồn trưởng thành và họ cũng được trưởng thành dần, cuối cùng tìm được tình yêu và hạnh phúc riêng mình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 18, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cheney Chen","avatar":""},{"name":"Karlina Zhang","avatar":""},{"name":"Zhang Li","avatar":""},{"name":"Vương Thụy Xương","avatar":""},{"name":"Bian Cheng","avatar":""},{"name":"Mễ Nhiệt","avatar":""},{"name":"Zheng Fan Xing","avatar":""},{"name":"Zidan Sun","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Liu Jun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324267);
