INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-ra-la-thay-giao', 'Hóa Ra Là Thầy Giáo!', 'Brilliant Class 8', 'hóa ra là thầy giáo! brilliant class 8 cheney chen karlina zhang zhang li vương thụy xương bian cheng mễ nhiệt zheng fan xing zidan sun lưu lâm liu jun ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-thien-tai-dua-dat-nuoc-thoat-khoi-no-nan-dung-roi-ban-nuoc-thoi', 'Hoàng Tử Thiên Tài Đưa Đất Nước Thoát Khỏi Nợ Nần - Đúng Rồi, Bán Nước Thôi', 'Tensai Oji No Akaji Kokka Saisei Jutsu - So Da, Baikoku Shiyo, The Genius Prince''s Guide To Raising A Nation Out Of Debt, The Genius Prince''s Guide To Raising A Nation Out Of Debt (Hey, How About Treason?)', 'https://phimimg.com/upload/vod/20240603-1/b18df2889338cc27644dd543cc9d9f8b.jpg', 'https://phimimg.com/upload/vod/20240603-1/2b05232f895ece9212b579aab4587cd8.jpg', '<p>Có một hoàng tử tại một vương quốc nhỏ, cậu chỉ có duy nhất một ước muốn đó là bán vương quốc đi và sống một cuộc sống yên bình. Tuy nhiên, ước mơ ấy ngày càng xa vời khi kẻ thù lớn nhất chính là bộ óc thiên tài của chính cậu ta. Cậu cứ tiếp tục gặt hái thành công trong vương quốc, thì lại ngày càng nhận được nhiều sự ưu ái hơn với người dân trong vương quốc của mình… điều này khiến việc thực hiện ước mơ bán vương quốc trở nên càng khó khăn hơn!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
