INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-than-y-trong-truyen-thuyet', 'Lục Thần Y Trong Truyền Thuyết', 'Legendary Doctor Lu', 'https://phimimg.com/upload/vod/20240603-1/89a88805fae64430a1dc188ee0dd39f8.jpg', 'https://phimimg.com/upload/vod/20240603-1/c2c09ae292c0e293add78ffda2144ae4.jpg', '<p>Su Lin, cô gái quê ở Spring Mountain Residence, đột nhiên mắc một chứng bệnh lạ và không thể hát. em gái của Lu Yusheng, người đã cải trang thành nam giới, đưa cô về nhà và giấu cô. Su Lin, người đã ăn trộm thuốc để cứu mạng cô, đã sớm bị Lu Yusheng phát hiện. Cả hai đã thỏa thuận rằng Su Lin sẽ là một cậu bé thử nghiệm ma túy cho Lu Yusheng, và Lu Yusheng sẽ cố gắng hết sức để chữa lành cho Su Lin</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shaydan Akbar","avatar":""},{"name":"Pupu","avatar":""},{"name":"Li Wenru","avatar":""},{"name":"Wang Ziming","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324267);
