INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-loi-duoi-long-con-luan', 'Lạc Lối Dưới Lòng Côn Luân', 'Lost In The KunLun Mountains', 'https://phimimg.com/upload/vod/20240603-1/6be2b7a1c207026c011f1983e9c80f51.jpg', 'https://phimimg.com/upload/vod/20240603-1/b593b7fe34a41a1ea2daa58d0a7ed1c0.jpg', '<p>Lạc Lối Dưới Lòng Côn Luân xoay quanh nhân vật Đinh Vân Tề, một du học sinh tài giỏi vừa trở về sau chuyến du học quốc tế, đồng thời cũng là người duy nhất đủ tư cách để thừa kế kho báu của di tích Côn Luân.\nVì vậy, ngay khi trở về nước, Đinh Vân Tề đã trở thành tâm điểm chú ý của nhiều thế lực. Để tránh khỏi nguy hiểm, anh cùng những người bạn của mình bắt đầu cuộc hành trình khám phá bí mật của di tích Côn Luân và đối đầu với không ít khó khăn, cạm bẫy.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hứa Khải","avatar":""},{"name":"Chung Sở Hi","avatar":""},{"name":"Wayne","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Ruan Ju","avatar":""},{"name":"MorniChang","avatar":""},{"name":"HeiZe","avatar":""},{"name":"Meng A Sai","avatar":""},{"name":"Ma Qi Yue","avatar":""},{"name":"Viann Zhang","avatar":""},{"name":"Zhang Fan","avatar":""},{"name":"He Feng Tian","avatar":""},{"name":"Hong Jian Tao","avatar":""},{"name":"Gao Thự Quang","avatar":""},{"name":"He Sai Fei","avatar":""},{"name":"Cheng Tao","avatar":""},{"name":"Gai Yu Jia","avatar":""},{"name":"Zuo Jin Zhu","avatar":""},{"name":"Emily","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b