INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phu-nu-trong-ngoi-nha-ben-kia-duong-doi-dien-co-gai-ben-khung-cua', 'Người Phụ Nữ Trong Ngôi Nhà Bên Kia Đường Đối Diện Cô Gái Bên Khung Cửa', 'The Woman In The House Across The Street From The Girl In The Window', 'https://phimimg.com/upload/vod/20240603-1/4bcedfd3105d56b0b00c74d39511c61b.jpg', 'https://phimimg.com/upload/vod/20240603-1/dfe3de850b101b30d135a385adb3e085.jpg', '<p>Kết hợp rượu, thuốc, món hầm và trí tưởng tượng quá đà, Anna bị ám ảnh về người hàng xóm vạm vỡ bên kia đường và chứng kiến một vụ án mạng. Mà có đúng vậy không?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristen Bell","avatar":""},{"name":"Michael Ealy","avatar":""},{"name":"Tom Riley","avatar":""},{"name":"Samsara Yett","avatar":""},{"name":"Mary Holland","avatar":""},{"name":"Cameron Britton","avatar":""},{"name":"Christina Anthony","avatar":""},{"name":"Shelley Hennig","avatar":""},{"name":"Benjamin Levy Aguilar","avatar":""},{"name":"Brenda Koo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
