INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moc-tieu-thu-tan-cong', 'Mộc Tiểu Thư Tấn Công', 'Let''s Go Fighting', 'https://phimimg.com/upload/vod/20240603-1/56a22194ebcf35d42e976a1633c3a067.jpg', 'https://phimimg.com/upload/vod/20240603-1/8b4655f7211f6dbb72b439d51dac319a.jpg', '<p>Cả gia đình Mộc Thị, doanh nghiệp đứng đầu ngành dịch vụ ăn uống, gặp tai nạn ngoài ý muốn ở nước ngoài. Nhị tiểu thư Mộc Ly nhận tim cấy ghép từ chị mình, thay người chị song sinh hóa thân thành một cô nàng thông minh lanh lợi được mọi người thích, hòng tiếp cận anh rể tương lai Mặc Thần, người khởi xướng việc thu mua tập đoàn Mộc Thị như tin đồn trên mạng, để âm thầm điều tra chân tướng vụ án, nhưng lại phát hiện hàng tấn bí mật phía sau vụ thu mua này. Hai người ômý đồ riêng mà thăm dò, hóa giải hết nguy cơ này đến nguy cơ khác, cuối cùng phát hiện đối thủ bí mật đứng đằng sau, lần theo manh mối tra được chân tướng vụ tai nạn xe, xóa bỏ ân oán.Từ đó, hai người bắt tay chống lại kẻ thù thật sự đằng sau, đồng thời bắt đầu khoảng thời gian tán tỉnh và được tán tỉnh đến là vui vẻ, cuối cùng Mộc Ly không chỉ “hốt” được chàng sếp tổng ngang ngược mà còn bắt được tất cả những kẻ hãm hại gia đình cô ra chịu sự trừng trị của pháp luật.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Han Donglin","avatar":""},{"name":"Wang Peihan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
