INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mighty-express-phan-7', 'Mighty Express (Phần 7)', 'Mighty Express (Season 7)', 'https://phimimg.com/upload/vod/20240603-1/421251d99c12aa32ca9eae35e92a9a2b.jpg', 'https://phimimg.com/upload/vod/20240603-1/8695ecf98365bec0c3cd284c7901d753.jpg', '<p>Nate, Flicker và những đoàn tàu khác lên đường với thêm nhiều chuyến giao hàng ly kỳ, nhiệm vụ đặc biệt và bài học thú vị trên đường ray.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jay Hatton","avatar":""},{"name":"Zoe Hatz","avatar":""},{"name":"Meesha Contreras","avatar":""},{"name":"Dylan Schombing","avatar":""},{"name":"Tyler Nathan","avatar":""},{"name":"Leo Orgil","avatar":""},{"name":"Michela Luci","avatar":""},{"name":"Ian Ho","avatar":""},{"name":"Evan Lefeuvre","avatar":""},{"name":"Annick Obonsawin","avatar":""},{"name":"Gracen Daly","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324267);
