INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xa-tinh-duyen-lai-den', 'Thanh Xà - Tình Duyên Lại Đến', 'Deity Of Love', 'https://phimimg.com/upload/vod/20240603-1/130f319838b67bc1785a8b30009765d8.jpg', 'https://phimimg.com/upload/vod/20240603-1/e7580a94fcfad0c25958bdaeefde71f3.jpg', '<p>Sau sự kiện nước ngập Kim Sơn, Pháp Hải đã phong ấn Tiểu Thanh và giao cho Trấn Hồn Ty canh giữ. 500 năm sau, Lý Tu Ninh tham gia ứng tuyển vào Trấn Hồn Ty lại đi nhầm đến nơi giam giữ Tiểu Thanh, vô tình phá vỡ phong ấn khiến nàng tỉnh lại. Nhưng do phong ấn bị cưỡng chế phá vỡ, Tiểu Thanh cũng mất đi trí nhớ. Để tìm lại ký ức, tìm hiểu về thế giới, Tiểu Thanh đã theo Lý Tu Ninh đến Thanh Vân Cốc, bắt đầu lại một cuộc sống mới. Trong quá trình từ từ quen biết, nàng vô tình phát hiện ra một thân phận khác của Lý Tu Ninh. Chuyện phong ấn 500 năm trước cũng dần sáng tỏ, bắt đầu một mối tình ngang trái trải dài nhiều kiếp…</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324267);
