INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alma', 'Alma', 'The Girl In The Mirror', 'https://phimimg.com/upload/vod/20240603-1/d4de5e24fa240749d4c03bf663984fa0.jpg', 'https://phimimg.com/upload/vod/20240603-1/0558b47175dd29d5bba098e7bd822557.jpg', '<p>Mất trí nhớ sau vụ tai nạn kỳ lạ đã giết chết đa số bạn cùng lớp, Alma cố gắng làm sáng tỏ những gì đã xảy ra ngày hôm đó – và lấy lại danh tính của mình.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Mireia Oriol","avatar":""},{"name":"Álex Villazán","avatar":""},{"name":"Pol Monen","avatar":""},{"name":"Javier Morgade","avatar":""},{"name":"Nil Cardoner","avatar":""},{"name":"María Caballero","avatar":""},{"name":"Claudia Roset","avatar":""},{"name":"Milena Smit","avatar":""},{"name":"Marta Belaustegui","avatar":""},{"name":"Josean Bengoetxea","avatar":""},{"name":"Kandido Uranga","avatar":""},{"name":"Nacho Fresneda","avatar":""},{"name":"Alejandro Serrano","avatar":""},{"name":"Elena Irureta","avatar":""},{"name":"Katia Borlado","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324267);
