INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoa-xa-giang-ho', 'Ngõa Xá Giang Hồ', 'The Theatre Stories', 'https://phimimg.com/upload/vod/20240603-1/9d91db52fec8f31f548405413af48d2e.jpg', 'https://phimimg.com/upload/vod/20240603-1/02f0c53fa2b511b40b03189a54a09e60.jpg', '<p>Ở một triều đại một thế hệ nào đó, đất nước phồn vinh, thiên hạ thái bình, thiên hạ ai cũng ca tụng vị hoàng đế nhỏ bé anh minh tài giỏi. Nhưng trên thực tế, tiểu hoàng đế vẫn chưa lên nắm quyền, quyền lực nằm trong tay thái hậu và hoàng thúc. Vị hoàng đế nhỏ bé, người không quan tâm đến các công việc của triều chính, chỉ mong muốn xuất cung du ngoại, và rất say mê với nhạc kịch. Một ngày nọ, vị hoàng đế nhỏ tìm thấy một lối đi bí mật trong cung điện và lặng lẽ lẻn ra ngoài, không ngờ cuối lối đi bí mật lại là một ngôi nhà ngói đã đóng cửa từ lâu (nhà hát cổ và hội quán). Ở đây vị hoàng đế nhỏ này gặp Bạch Tiểu Thanh. Từ đó vị hoàng đế đã che dấu thân phận làm bạn với nhóm người ở đây. Sau khi vượt qua những thăng trầm, tranh chấp triền miên, khó có thể chia lìa ...</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Qin Xiao Xian","avatar":""},{"name":"Triệu Tiểu Đường","avatar":""},{"name":"Meng Hetang","avatar":""},{"name":"Cao He Yang","avatar":""},{"name":"Li He Dong","avatar":""},{"name":"Zhang Hao Yue","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324267);
