INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-trang-diem-phan-4', 'Phù Thủy Trang Điểm (Phần 4)', 'Glow Up (Season 4)', 'https://phimimg.com/upload/vod/20240603-1/30771e0e765c065b5825a92879b7c472.jpg', 'https://phimimg.com/upload/vod/20240603-1/fc04e5644f5f06c9d0c61f33a2c37ea9.jpg', '<p>Trong cuộc thi này, các nghệ sĩ trang điểm khao khát thành công dấn thân vào những thử thách nhiều sắc màu để giành cơ hội làm nên sự nghiệp trong ngành làm đẹp.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Val Garland","avatar":""},{"name":"Dominic Skinner","avatar":""},{"name":"Maya Jama","avatar":""},{"name":"Stacey Dooley","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324267);
