INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-thich-nguoi-theo-doi-cua-toi', 'Ai Thích Người Theo Dõi Của Tôi?', 'Who Likes My Follower?', 'https://phimimg.com/upload/vod/20240603-1/feb1c1d48dd07723f88bd997c1991f57.jpg', 'https://phimimg.com/upload/vod/20240603-1/6f776ad73819d474a8f09a32a802bb58.jpg', '<p>Ba người có ảnh hưởng, mỗi người huấn luyện một người theo dõi khi họ thu hẹp phạm vi đối tượng hẹn hò tiềm năng, hy vọng đổi lượt thích trên mạng lấy tình yêu ngoài đời.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Luján Argüelles","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
