INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-vong-3-hiep-can-nghia-dam-tham-kiem-tam', 'Kiếm Võng 3: Hiệp Can Nghĩa Đảm Thẩm Kiếm Tâm', 'JX Online3：The Adventure Of Shen Jianxin 3rd Season', 'https://phimimg.com/upload/vod/20240603-1/16605944ea644f977e56e5f59208fa2d.jpg', 'https://phimimg.com/upload/vod/20240603-1/5244cf79fcfb12e620462408917a0f08.jpg', '<p>Giang hồ sớm đã không còn bình yên. Ngũ Thánh giáo yên phận ở một phương liên tiếp bị hãm hại, thôn trang ở Phong Hoa cốc hoang tàn đổ nát đột nhiên có động tĩnh dị thường. A Tát Tân tái xuất giang hồ, Khúc Vân và A Lượng mới xuất hiện,... Thẩm Kiếm Tâm lưu lạc nhiều năm tại đảo Thanh Thuỷ đột nhiên bị ám sát. Lần này anh sẽ đối mặt với nguy hiểm gì đây?</p>', 'Full', 11, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324267);
