INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-trai-tim-toi-cuong', 'Những Trái Tim Tối Cường', 'Extreme Hearts', 'https://phimimg.com/upload/vod/20240603-1/3d3231156e1bde1306b3750f5ff7d165.jpg', 'https://phimimg.com/upload/vod/20240603-1/0c4131ec64d3af40d5d6fc5aefc32cd6.jpg', '<p>Đây là câu chuyện về một tương lai không xa thực tại. Hypersports (Siêu thể thao) tận dụng Support Item Extreme Gear (Trang thiết bị hỗ trợ tối cường) để chơi đã trở thành sở thích của đông đảo người lớn lẫn trẻ nhỏ. Câu chuyện bắt đầu khi Hayama Hiyori, một ca sĩ trung học vốn không hề có duyên với thể thao cường điệu gặp tai nạn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324267);
