INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-tai-hanh-toi-tram-ngan-lan', 'Tổng Tài Hành Tôi Trăm Ngàn Lần', 'Female CEO Love Me', 'https://phimimg.com/upload/vod/20240603-1/67a4cfe3aef6d9ccb5cba23a92f37fb0.jpg', 'https://phimimg.com/upload/vod/20240603-1/38dd89c86203f7068249bfbdd56dee76.jpg', '<p>Bộ phim kể về câu chuyện nữ chủ tịch bá đạo bề ngoài cứng rắn bên trong yếu mềm, sắc bén và giàu có Hạ Mộng Vy yêu nhân viên đứng quầy đẹp trai ngọt ngào, nhiều kỹ năng sống Cố Ngôn ngay từ cái nhìn đầu tiên. Chủ tịch bá đạo dũng cảm theo đuổi tình yêu, tấn công quyết liệt, cuối cùng cũng theo đuổi được Cố Ngôn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cai YiJia","avatar":""},{"name":"Yang Xinying","avatar":""},{"name":"Zhang Qingqing","avatar":""},{"name":"Bell Jin","avatar":""},{"name":"Chu Qian","avatar":""},{"name":"Chen Yeling","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
