INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('david-letterman-buoi-dien-ha-man', 'David Letterman: Buổi Diễn Hạ Màn', 'That''s My Time With David Letterman', 'https://phimimg.com/upload/vod/20240603-1/7d03a8c3d31d3094e4803769cd9391eb.jpg', 'https://phimimg.com/upload/vod/20240603-1/b66937a1ceeb96934e651c94869553e5.jpg', '<p>David Letterman mời một số ngôi sao hài độc thoại triển vọng và đình đám nhất đến biểu diễn một tiết mục rồi ngồi lại cùng trò chuyện.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Letterman","avatar":""},{"name":"Sam Morril","avatar":""},{"name":"Naomi Ekperigin","avatar":""},{"name":"Rosebud Baker","avatar":""},{"name":"Brian Simpson","avatar":""},{"name":"Robin Tran","avatar":""},{"name":"Phil Wang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324267);
