INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-trinh-nghe-nghiep-den-dinh-cao', 'Lộ Trình Nghề Nghiệp Đến Đỉnh Cao', 'Vocational Path To The Top', 'https://phimimg.com/upload/vod/20240603-1/737cdc22ff30a205e9777df8a760a9a1.jpg', 'https://phimimg.com/upload/vod/20240603-1/94ec1dff84743e943b6ebfdeca937160.jpg', '<p>Một bộ phim hài nhẹ nhàng về đô thị lấy bối cảnh là giáo dục nghề nghiệp, kể về câu chuyện của Yang Xiaoqi, nữ anh hùng khao khát trở thành bậc thầy về máy xúc, và Bai He, nữ anh hùng khao khát trở thành người dẫn đầu ngành làm đẹp và làm tóc., một câu chuyện đầy cảm hứng về việc thành lập một nhóm chuyên nghiệp liên kỹ thuật với các sinh viên từ lớp đầu bếp và lớp sửa chữa ô tô để tham gia hỗ trợ khôi phục nông thôn của trường. Bộ phim phù hợp với định hướng chủ đạo và kế hoạch giáo dục phát triển mạnh mẽ giáo dục nghề nghiệp của đất nước, thông qua các nhân vật trẻ trung, câu chuyện hài hước và cốt truyện sinh động, cảm động, bộ phim đã mở ra một bức tranh đầy màu sắc về phổ cập và quảng bá giáo dục nghề nghiệp.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vu Lãng","avatar":""},{"name":"Vương Gia Hiên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
