INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('supreme-ntm-bo-doi-hip-hop-phap', 'Suprême NTM: Bộ Đôi Hip Hop Pháp', 'Reign Supreme', 'https://phimimg.com/upload/vod/20240603-1/5e46ed6a3a85117894771fac0f9118f8.jpg', 'https://phimimg.com/upload/vod/20240603-1/f1f25e3b72f9f6d50f99e594c9a3e1d8.jpg', '<p>Từ các dự án đến các tụ điểm lớn nhất Paris, loạt phim này theo chân đôi bạn tuổi teen chí cốt khi họ sáng tạo ra và nâng tầm hip-hop Pháp.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Anthony Bajon","avatar":""},{"name":"Melvin Boomer","avatar":""},{"name":"Andranic Manet","avatar":""},{"name":"Laïka Blanc-Francard","avatar":""},{"name":"Victor Bonnel","avatar":""},{"name":"Léo Chalié","avatar":""},{"name":"Yannick Choirat","avatar":""},{"name":"Emmanuelle Hiron","avatar":""},{"name":"Elga Gnaly","avatar":""},{"name":"Daouda Keita","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324267);
