INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('supreme-ntm-bo-doi-hip-hop-phap', 'Suprême NTM: Bộ Đôi Hip Hop Pháp', 'Reign Supreme', 'suprême ntm: bộ đôi hip hop pháp reign supreme anthony bajon melvin boomer andranic manet laïka blanc-francard victor bonnel léo chalié yannick choirat emmanuelle hiron elga gnaly daouda keita ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-minh-thich-tiec-tung', 'Khổng Minh Thích Tiệc Tùng', 'Ya Boy Kongming!', 'https://phimimg.com/upload/vod/20240603-1/9f2b9e3db0484ebf9ac71e8ef3e24542.jpg', 'https://phimimg.com/upload/vod/20240603-1/4d4b0fd7d187738149ccc340f2694176.jpg', '<p>Quân sư tài ba Tam Quốc, Gia Cát Khổng Minh người đời ai cũng biết đã ra đi tại gò Ngũ Trượng. Nhưng ông một lần nữa tái sinh với thân xác trẻ, ngay giữa lòng phố Shibuya tấp nập của Nhật Bản hiện đại. Ông được những thanh niên trẻ tuổi rủ rê đến câu lạc bộ hiện đại vang vọng tiếng nhạc trên sân khấu. Tại đây ông tình cờ được cô gái Tsukimi Eiko đang nhắm đến làm ca sĩ. Cuộc gặp gỡ tình cờ này đã mở cho ông sang trang mới ở cuộc đời thứ hai. Ông quyết định trở thành quân sư cho cô gái trẻ có ước mơ trở thành ca sĩ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
