INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-gai-ong-trum-va-nguoi-giam-ho', 'Con Gái Ông Trùm Và Người Giám Hộ', 'Kumichou Musume To Sewagakari The Yakuza''s Guide To Babysitting', 'https://phimimg.com/upload/vod/20240603-1/34b133979160a3b163bbde21b2e0a0a8.jpg', 'https://phimimg.com/upload/vod/20240603-1/7797fcf50cf938b5c34015d8e468aef6.jpg', '<p>Toru Kirishima, người giải quyết mọi chuyện rắc rối bằng bạo lực, được mệnh danh là ác quỷ của tổ chức Sakuragi ở thế giới ngầm. Một ngày nọ, Kirishima bất ngờ được thủ lĩnh của băng Sakuragi gọi đến và chỉ định làm người chăm sóc cho cô con gái duy nhất của ông là Yaehana. Một vở hài kịch ấm áp giữa người thủ lĩnh trẻ và cô con gái duy nhất của ông trùm. Chuỗi ngày mới của hai người họ bắt đầu từ đó.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324267);
