INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('big-dragon-the-series', 'Big Dragon The Series', 'Big Dragon The Series', 'https://phimimg.com/upload/vod/20240603-1/c7e63db93499c8a904a01d2e557858c7.jpg', 'https://phimimg.com/upload/vod/20240603-1/5eabfdb26b58e18fc91d59247ff08365.jpg', '<p>Kể về câu chuyện về Mangkorn và Yhai Hai kẻ thù cùng yêu cùng một người phụ nữ nhưng sau đó lại tình cờ quan hệ tình dục vì họ say rượu tại quán rượu SUNRISE thuộc sở hữu của Yhai, người thừa kế của gia đình nổi tiếng. “Singhawattanachoke” Yhai không thể chấp nhận lời nói của Mangkorn về đêm đó, rằng anh ấy đã chiến thắng tất cả và mong muốn chiến thắng. Do đó, anh ấy đã cố gắng phá hủy quán rượu với hy vọng xóa đi những ký ức tồi tệ mà anh ấy đã mất trước Mangkorn. lần duy nhất cha của Yai, Borom, muốn cải tạo lại quán rượu. Do đó, ông buộc phải nhận trách nhiệm này. Thay vì đến Maldives cùng bạn bè. Tuy nhiên, mọi chuyện không đơn giản như ai cũng có thể tưởng tượng khi Một trong những kiến trúc sư được thuê là Mungkorn, một sinh viên kiến trúc năm thứ 5 đến làm việc tại Công ty Thiết kế G. Liệu có phải sự tình cờ đã đưa họ trở lại với nhau từ ghét thành yêu? Điều gì sẽ xảy ra tiếp theo với sự cải tạo của quán rượu này. . .?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mos Panuwat Sopadit","avatar":""},{"name":"Isbanky Mondop Heamtan","avatar":""},{"name":"Fong Bovorn kongnawdee","avatar":""},{"name":"JJ Rathasat butwong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
