INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('eirik-jensen-canh-sat-hay-toi-pham', 'Eirik Jensen: Cảnh Sát Hay Tội Phạm?', 'Mr. Good: Cop Or Crook?', 'https://phimimg.com/upload/vod/20240603-1/fb43125025836a67ec9aa6d10df5e11f.jpg', 'https://phimimg.com/upload/vod/20240603-1/f44f84783b96203c77748c2b13194d09.jpg', '<p>Trong loạt phim tài liệu hấp dẫn này, viên cảnh sát hàng đầu Na Uy bị tình nghi buôn ma túy khiến các điều tra viên tự hỏi anh là sĩ quan tốt hay tên tội phạm nguy hiểm?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Eirik Jensen","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324267);
