INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-cuoi-cua-arsnotoria-hoat-hinh', 'Nụ Cười Của Arsnotoria (Hoạt Hình)', 'Smile Of The Arsnotoria The Animation', 'https://phimimg.com/upload/vod/20240603-1/c00a9c07cbc23165c8c35054ebff70be.jpg', 'https://phimimg.com/upload/vod/20240603-1/c023aad5264f0db8ee3aa511724b45f3.jpg', '<p>Đây là câu chuyện về cuộc sống thường nhật đầy tiếng cười của một cô gái đang nỗ lực để trở thành một quí cô, trong khi đang học và luyện tập phép thuật, cũng như đường lối ứng xử đúng đắn tại học viện ma thuật nội trú tại thành phố Ashram.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324267);
