INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-ong-chu', 'Giải Cứu Ông Chủ', 'Unlock My Boss', 'https://phimimg.com/upload/vod/20240603-1/9fe57a105e38f0b28d0ec15275b70f0d.jpg', 'https://phimimg.com/upload/vod/20240603-1/e76962a84af600c6d2fa6b01fd1ddcc1.jpg', '<p>Nó dựa trên một webtoon cùng tên của nhà văn Park Seong-hyun, được đăng nhiều kỳ trên Naver. Phim xoay quanh về Seon Ju 39 tuổi, một CEO thiên tài của một tập đoàn lớn đã vô tình qua đời và trở thành một chiếc điện thoại thông minh, và In Seong, một người tìm việc 29 tuổi vô tình nhặt được chiếc điện thoại thông minh, cùng nhau hợp tác để tìm ra kẻ giết người.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Chae Jong Hyeop","avatar":""},{"name":"Park Sung Woong","avatar":""},{"name":"Seo Eun Soo","avatar":""},{"name":"Lee Sang Hee","avatar":""},{"name":"Byun Jun Seo","avatar":""},{"name":"Bang Joo Hwan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324267);
