INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuoc-vai-ma-mi', 'Thước Vải Ma Mị', 'Undying Secret', 'https://phimimg.com/upload/vod/20240603-1/37d136901a8989d2497134f30fc82ade.jpg', 'https://phimimg.com/upload/vod/20240603-1/4b7a9df279f444b71eca25adda5ded07.jpg', '<p>Gia đình Alada sở hữu tấm vải Luntaya màu hồng tuyệt đẹp do bà nội cô dệt cho Công chúa Minphayu. Tuy nhiên, sau đó, bà cô lại bị mù một cách bí ẩn. Đam mê với ngành dệt, Alada tham gia nghiên cứu việc bảo quản vải cổ tại Viện dệt may Saodor ở Anh. Sau khi tốt nghiệp, cô trở về Thái Lan và gặp gỡ những người bạn mới. Thật tình cờ khi cả nhóm đều có mối liên hệ với tấm vải Luntaya và họ đã cùng nhau giải mã bí ẩn xung quanh nó.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 8, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Yui Chiranan Manochaem","avatar":""},{"name":"Wawwa Nichari Chokprajakchat","avatar":""},{"name":"Nike Nitidon Pomsuwan","avatar":""},{"name":"Fluke Jira Danbawornkiat","avatar":""},{"name":"Tian Atcharee Buakhiao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324267);
