INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tu-khong-thanh-co', 'Tình Yêu Từ Không Thành Có', 'Fall In Love', 'https://phimimg.com/upload/vod/20240603-1/6465767d9a8fcafbc5248776291659b7.jpg', 'https://phimimg.com/upload/vod/20240603-1/bb2c815de226558aceb34a0754b6efe5.jpg', '<p>Phim kể về đại tiểu thư ngạo kiều Cảnh Tri Hạ gặp phải chàng CEO hai nhân cách ngang ngược Phó Trạch Nhất và bắt đầu cho một tam giác tình ngọt ngào cay đáng. Nam nữ mạnh mẽ dứt khoát, xây dựng nên tình yêu của những người trưởng thành.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Thái Trác Nghi","avatar":""},{"name":"Tiêu Khải Trung","avatar":""},{"name":"Bành Cao Xướng","avatar":""},{"name":"Thẩm Dương","avatar":""},{"name":"Châu Tiểu Xuyên","avatar":""},{"name":"Thôi Nam","avatar":""},{"name":"Dư Khải Ninh","avatar":""},{"name":"Hoàng Thiên Thạc","avatar":""},{"name":"Nhậm Tư Tề","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324267);
