INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-tu-khong-thanh-co', 'Tình Yêu Từ Không Thành Có', 'Fall In Love', 'tình yêu từ không thành có fall in love thái trác nghi tiêu khải trung bành cao xướng thẩm dương châu tiểu xuyên thôi nam dư khải ninh hoàng thiên thạc nhậm tư tề ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-ngay-yeu-em', 'Tháng Ngày Yêu Em', 'Love You Day And Month', 'https://phimimg.com/upload/vod/20240603-1/df7c09b1659d66986ba60e8f6e218ef5.jpg', 'https://phimimg.com/upload/vod/20240603-1/a866c8198d44cbb4d616104384eb456e.jpg', '<p>Cô gái dọn dẹp Minh Hiểu Hiểu và tổng tài bá đạo Hoắc Vân Đình gặp nhau ở thôn nghỉ dưỡng vì một lần hiểu lầm tình cờ, lại vì một việc ngoài ý muốn mà hôn nhau, trở thành đôi oan gia vui vẻ. Minh Hiểu Hiểu ngây thơ đáng yêu nhưng lại mắc chứng trở ngại trí lực nhẹ, Hoắc Vân Đình lạnh lùng xấu xa nhưng lại bị phản đồ của gia tộc hãm hại, hai người vốn không liên quan nhưng vì Hoắc Vân Đình gặp tai nạn cần người chăm sóc mà bắt đầu cuộc sống chung dưới mái nhà với nhau.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lợi Lạc","avatar":""},{"name":"Phùng Y Y","avatar":""},{"name":"Tần Đại Sâm","avatar":""},{"name":"Kiều Diệu Na","avatar":""},{"name":"Lý Vỹ Tiệp","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
