INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thang-ngay-yeu-em', 'Tháng Ngày Yêu Em', 'Love You Day And Month', 'tháng ngày yêu em love you day and month lợi lạc phùng y y tần đại sâm kiều diệu na lý vỹ tiệp ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-tu-abyss-ngay-khong-tat-nang-o-lang-hoang-kim', 'Đến Từ Abyss: Ngày Không Tắt Nắng Ở Làng Hoàng Kim', 'Made In Abyss: The Golden City Of The Scorching Sun', 'https://phimimg.com/upload/vod/20240603-1/bc46dea0ef0105bc6a1262f782286d8a.jpg', 'https://phimimg.com/upload/vod/20240603-1/ffb4f7fd5ea8f41227d97dff515bc4f7.jpg', '<p>Có một hệ thống hang động khổng lồ bí ẩn được biết đến với cái tên: Abyss, nơi các loài sinh vật kỳ lạ còn sống, các di vật quý hiếm đang ngủ yên. Riko, cô sống ở thị trấn Orth, nuôi dưỡng ước mơ một ngày nào đó sẽ trở thành một nhà thám hiểm vĩ đại và làm sáng tỏ bí ẩn của Abyss. Một ngày nọ, cô quyết định đi sâu xuống Abyss sau khi tìm thấy chiếc còi trắng của mẹ mình. Trên đường đi cô nhặt được một cậu bé robot tên Reg. Mất trí nhớ, Reg quyết định cùng du hành với Riko để tìm lại ký ức của mình. Chuyến thám hiểm đã quy tụ cho nhóm Riko thêm những người bạn mới: Nanachi - người bị biến thành narehate bởi Bondrewd; Pruschka - con gái nuôi của Bondrewd đã bị hắn thí nghiệm đến dị dạng, giờ đã trở thành còi trắng của Riko. Cùng nhau, cả nhóm tiến đến tầng 6 của Abyss, nơi ngự trị ngôi làng của narehate.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
