INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('den-tu-abyss-ngay-khong-tat-nang-o-lang-hoang-kim', 'Đến Từ Abyss: Ngày Không Tắt Nắng Ở Làng Hoàng Kim', 'Made In Abyss: The Golden City Of The Scorching Sun', 'đến từ abyss: ngày không tắt nắng ở làng hoàng kim made in abyss: the golden city of the scorching sun  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-lap-lanh', 'Ngôi Sao Lấp Lánh', 'Shining For One Thing', 'https://phimimg.com/upload/vod/20240603-1/3660fc37ee13872376fafeb1ea54d22c.jpg', 'https://phimimg.com/upload/vod/20240603-1/8329ccc18208396d2a2fa5f515ae8bbf.jpg', '<p>Phim kể về thiếu nữ từng trải Lâm Bắc Tinh ( Trương Giai Ninh thủ vai ) sắp bước vào tuổi 30 đã từ bỏ điện thờ tình yêu vì bạn trai Triển Vũ hủy hôn ước , cuộc sống và công việc cũng vì thế mà trở nên rối loạn . Không biết là số mệnh quan tâm hay là trò đùa của Nguyệt Lão , Lâm Bắc Tinh bất ngờ trở lại năm 18 tuổi . Lớp 12 vốn là ác mộng , nhưng Lâm Bắc Tinh dự định sẽ tham gia thi đại học lần nữa , thoát khỏi Triển Vũ , vì bản thân mà sống thêm một lần , nhưng mộng đẹp của Lâm Bắc Tinh liên tục bị một thanh niên tên Trương Vạn Sâm ( Khuất Sở Tiêu thủ vai ) phá vỡ . Cuộc gặp gỡ bất ngờ với Trương Vạn Sâm sau kì thi đại học lại trở thành công tắc kết thúc cuộc hành trình xuyên thời không của Lâm Bắc Tinh , Lâm Bắc Tinh bắt đầu cuộc tác chiến cứu Trương Van Sâm thoát khỏi những âm mưu trong bóng tối . Những ngày tháng trung học năm 2 lãng mạn mà ngắn ngủi , thay đổi khiến Lâm Bắc Tinh thu được những điều tốt đẹp cô từng bỏ lỡ . Khi mùa hè đến , Lâm Bắc Tinh cũng phát hiện cô không chỉ cứu học bá Trương Vạn Sâm , mà còn cứu cả tình yêu của thanh niên này từ lúc đó với cô bắt đầu như sao trời biển rộng</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Khuất Sở Tiêu","avatar":""},{"name":"Trương Giai Ninh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
