INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-lap-lanh-phan-1', 'Cô Nàng Lấp Lánh (Phần 1)', 'Shining Girls (Season 1)', 'https://phimimg.com/upload/vod/20240603-1/e4ab0f5ca58cbf7353a32e13b45c53e0.jpg', 'https://phimimg.com/upload/vod/20240603-1/b55840f3a2618c5b11a411300fe97a7c.jpg', '<p>Nhiều năm sau khi một cuộc tấn công tàn bạo khiến cô ấy rơi vào một thực tế liên tục thay đổi, Kirby Mazrachi biết rằng một vụ giết người gần đây có liên quan đến vụ tấn công của cô ấy. Cô ấy hợp tác với một phóng viên kỳ cựu để hiểu hiện tại luôn thay đổi của cô ấy và đối đầu với quá khứ của cô ấy.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amy Brenneman","avatar":""},{"name":"Phillipa Soo","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Wagner Moura","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324267);
