INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-ky-bach-ngay-nao-cung-muon-tu-chuc', 'Thư Ký Bạch Ngày Nào Cũng Muốn Từ Chức', 'I Want To Resign Every Single Day', 'https://phimimg.com/upload/vod/20240603-1/9dbb1737f63899c0531a45b7c2837f49.jpg', 'https://phimimg.com/upload/vod/20240603-1/9515e56d91c41ee64308f241cb769d78.jpg', '<p>Thư ký Bạch Tĩnh không hài lòng về chuyện tổng giám đốc Kim Thế An sắp xếp công việc cho mình nên đã xin nghỉ việc với anh. Nào ngờ cô lại bị cuốn vào vòng lặp thời gian. Trong quá trình này, Bạch Tĩnh dần tìm được sự thực của việc Kim Thế An làm khó cô và phát hiện ra điểm tốt của anh. Hai người cùng thổ lộ tình cảm với nhau, nắm tay cùng giải quyết nguy cơ của công ty, cuối cùng có được tình yêu tuyệt vời.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Tử Hào","avatar":""},{"name":"Hàn Nhạc Dao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
