INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-ngoai-toa-an', 'Bên Ngoài Tòa Án', 'Out Of Court', 'https://phimimg.com/upload/vod/20240603-1/1a1ae37c0782fdf7b5ab1d4b92c6fc41.jpg', 'https://phimimg.com/upload/vod/20240603-1/9e8d3c7aea9f3a8121cd1580c344329c.jpg', '<p>Kiều Thiệu Đình là một luật sư hàng đầu, anh gặp rất nhiều khó khăn khi đại diện xử lý cho một vụ án hình sự, nhưng trước những hụt hẫng và tổn thất nặng nề trong cuộc đời, anh vẫn cố chấp với việc điều tra chân tướng vụ án, đồng thời cộng tác với luật sư trẻ xuất sắc Tiêu Trăn để theo dõi việc xem xét án tử hình đối với các vụ án.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"La Tấn","avatar":""},{"name":"Tiêu Tuấn Diễm","avatar":""},{"name":"Hạ Vũ","avatar":""},{"name":"Lý Quang Khiết","avatar":""},{"name":"Lý Tông Hàn","avatar":""},{"name":"Cao Diệp","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
