INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-duoi-2022', 'Săn Đuổi', 'Hunted (Boar Hunt)', 'https://phimimg.com/upload/vod/20240603-1/178a2777686117ea2b0749c51147e3e5.jpg', 'https://phimimg.com/upload/vod/20240603-1/751678c5b4cdcf081af1ebbee4635499.jpg', '<p>Bộ phim này kể về một câu chuyện xảy ra tại một ngôi làng bình thường, trong đó một vụ án mất tích xảy ra vào một ngày săn lợn rừng và những bí mật của dân làng xung quanh vụ án đang lần lượt được hé mở.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Ho San","avatar":""},{"name":"Ye Soo Jung","avatar":""},{"name":"Kim Soo Jin","avatar":""},{"name":"Lee Kyu Hoe","avatar":""},{"name":"Lee Hyo Je","avatar":""},{"name":"Yoo Soon Woong","avatar":""},{"name":"Kwak Ja Hyung","avatar":""},{"name":"Hwang Jae Yeol","avatar":""},{"name":"Cha Si Won","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324267);
