INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-sam-hoi-muon-mang-ii', 'Lời Sám Hối Muộn Màng II', 'Lời Sám Hối Muộn Màng II', 'https://phimimg.com/upload/vod/20240603-1/602035d06ef0551e15eb06f82434e7cf.jpg', 'https://phimimg.com/upload/vod/20240603-1/7469b27d52359259eedc27b7c3fd17fb.jpg', '<p>Diêu Thượng Khiêm vì tham vọng nổi tiếng đã nhận vơ một tác phẩm không phải của mình. Bạn thân của Thượng Khiêm là Phương Chí Hạo, cũng là chủ phòng tranh bị lừa một cách thuyết phục và quyết tâm giúp Thượng Khiêm nổi tiếng. Nào ngờ tác giả bức tranh đó là Thẩm Việt, học trò của Thượng Khiêm 18 năm về trước. Hai người, một bên vì danh lợi, một bên vì sinh kế, đã hợp tác với nhau, lâu dần sinh tình cảm. Cũng vì bức tranh ấy, một vụ án mạng ly kỳ xảy ra, nạn nhân lại là vợ của Thượng Khiêm - Trang Nhuệ Đình . Những thủ đoạn lừa dối, nghi kỵ lẫn nhau, những cơn sóng gió dồn dập đã cuốn mọi người vào vòng xoáy không tài nào dứt ra được.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Đàm Tuấn Ngạn","avatar":""},{"name":"Cung Gia Hân","avatar":""},{"name":"Trần Sơn Thông","avatar":""},{"name":"Đàm Khải Kỳ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
