INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-sam-hoi-muon-mang-ii', 'Lời Sám Hối Muộn Màng II', 'Lời Sám Hối Muộn Màng II', 'lời sám hối muộn màng ii lời sám hối muộn màng ii đàm tuấn ngạn cung gia hân trần sơn thông đàm khải kỳ ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-cua-truong-ve-quoc', 'Mùa Hè Của Trương Vệ Quốc', 'Guo''s Summer', 'https://phimimg.com/upload/vod/20240603-1/8075a5741501ae22b6e4ab6bc303cb6d.jpg', 'https://phimimg.com/upload/vod/20240603-1/c1ede44ccf793dfb67c70703b21893da.jpg', '<p>Trương Vệ Quốc là một người đàn ông trung niên, là một diễn viên áo vằn của đoàn kinh kịch. Là một người bình thường trong con hẻm Bắc Kinh, anh sống tự do tự tại trong thế giới nhỏ của mình như chú cá vàng anh nuôi trong bể. Cho đến một ngày, người cha già đột ngột qua đời, nhiều rắc rối bất ngờ kéo theo khiến cuộc sống của anh bị hỗn loạn hoàn toàn. Hàng loạt biến cố khiến anh không thể không thay đổi, cuối cùng anh cũng nhận ra rằng trong nửa đầu cuộc đời anh đã quá thờ ơ với thế giới. Trương Vệ Quốc quyết định thử thách bản thân, trong quá trình thay đổi anh từng trải qua đỉnh cao của cuộc đời và từng đánh mất chính mình. Nhưng gia đình và bạn bè đã hướng dẫn anh đến ý nghĩa thực sự của cuộc sống vào những thời điểm quan trọng. Cuối cùng anh ấy cũng nhận ra rằng, cuộc sống hạnh phúc là tất cả những gì xung quanh, đừng chỉ tập trung vào mục tiêu và vùi đầu vào lên đường mà bỏ lỡ những vẻ đẹp bình dị.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hoàng Lỗi","avatar":""},{"name":"Lưu Dịch Quân","avatar":""},{"name":"Hải Thanh","avatar":""},{"name":"Mai Đình","avatar":""},{"name":"Lý Lâm Khiêm","avatar":""},{"name":"Giang Bằng","avatar":""},{"name":"Tô Tiểu Minh","avatar":""},{"name":"Hàn Đồng Sinh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
