INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-he-cua-truong-ve-quoc', 'Mùa Hè Của Trương Vệ Quốc', 'Guo''s Summer', 'mùa hè của trương vệ quốc guo''s summer hoàng lỗi lưu dịch quân hải thanh mai đình lý lâm khiêm giang bằng tô tiểu minh hàn đồng sinh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-diem-dot-kich', 'Lam Diễm Đột Kích', 'Blue Flame Assault', 'https://phimimg.com/upload/vod/20240603-1/cead3f37f98df7156e787e412e6e6f28.jpg', 'https://phimimg.com/upload/vod/20240603-1/0dcd834a916cf6ddec8b2430d49ee97b.jpg', '<p>Vì muốn giúp đỡ cho cửa tiệm của mẹ sớm được mở cửa trở lại, Lý Khê Thành đã gia nhập đội cứu hỏa ở khu vực. Sau khi trải qua quá trình huấn luyện gian khổ, phải liên tục đối mặt với hiểm nguy trong công việc, Khê Thành đã dần hiểu ra ý nghĩa của người lính cứu hỏa và ngày càng yêu công việc của mình.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Trần Tiểu Vân","avatar":""},{"name":"Hàn Vũ Thần","avatar":""},{"name":"Tạ Lâm Đồng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324267);
