INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-hop-lop-nho-doi', 'Buổi Họp Lớp Nhớ Đời', 'The Afterparty', 'https://phimimg.com/upload/vod/20240603-1/e847b942bf97b80ddf47cd19d2e9fa45.jpg', 'https://phimimg.com/upload/vod/20240603-1/9248a1b782ba86cb045a0885a620f8f1.jpg', '<p>Khi bữa tiệc hậu họp lớp trung học kết thúc bằng một cái chết gây choáng váng, tất cả mọi người đều là nghi can. Một thám tử tra hỏi từng người bạn học cũ, tìm ra động cơ tiềm ẩn khi mỗi người kể phiên bản câu chuyện của riêng họ - dẫn đến sự thật gây sốc.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tiffany Haddish","avatar":""},{"name":"Sam Richardson","avatar":""},{"name":"Zoë Chao","avatar":""},{"name":"Ben Schwartz","avatar":""},{"name":"Ike Barinholtz","avatar":""},{"name":"Ilana Glazer","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Jamie Demetriou","avatar":""},{"name":"John Early","avatar":""},{"name":"Genevieve Angelson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324267);
