INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bao-giang-sinh', 'Cơn Bão Giáng Sinh', 'A Storm For Christmas', 'https://phimimg.com/upload/vod/20240603-1/9c10f9748723ac4fbfb151492e735395.jpg', 'https://phimimg.com/upload/vod/20240603-1/1cb70e29fbe48e86ab2584395c45a1b9.jpg', '<p>Các số phận giao thoa khi thời tiết khắc nghiệt khiến cả du khách và nhân viên mắc kẹt ở sân bay, buộc họ phải dành những giờ cuối cùng trước Giáng sinh bên nhau.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Ida Elise Broch","avatar":""},{"name":"Dennis Storhøi","avatar":""},{"name":"Jan Gunnar Røise","avatar":""},{"name":"Alexandra Rapaport","avatar":""},{"name":"Jon Øigarden","avatar":""},{"name":"Maibritt Saerens","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324267);
