INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-bao-tinh-yeu-va-thoi-tiet', 'Dự Báo Tình Yêu Và Thời Tiết', 'Forecasting Love And Weather', 'https://phimimg.com/upload/vod/20240603-1/3dbb8f8c33c0e8de4d85ceb4b1051731.jpg', 'https://phimimg.com/upload/vod/20240603-1/efe64af5346a0d42f39b129cf746cd08.jpg', '<p>Phim kể về công việc và tình yêu, cuộc sống của những người làm việc tại Cục Khí tượng Hàn Quốc, dịch vụ dự báo thời tiết quốc gia của Hàn Quốc.Jin Ha Kyung (Park Min Young) là một người thông minh và có tổ chức cao. Cô làm mọi thứ theo lý thuyết và khó tính trong việc giữ cuộc sống cá nhân với nghề nghiệp của mình một cách riêng biệt. Do tính cách lạnh lùng, cô ấy có ít bạn bè tại nơi làm việc và trở thành “người ngoài cuộc theo sự lựa chọn”.Lee Shi Woo (Song Kang) là người sở hữu một tinh thần tự do, luôn suy nghĩ cởi mở. Mặc dù có vẻ ngoài vụng về nhưng anh ấy tự hào có chỉ số IQ ấn tượng 150 và có thể đạt được bất cứ điều gì một khi anh ấy quyết tâm. Tuy nhiên, bất chấp trí thông minh và khả năng của mình, tất cả những gì anh ta quan tâm là thời tiết.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Min Young","avatar":""},{"name":"Song Kang","avatar":""},{"name":"Yoon Park","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
