INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-khoa-hoc-nhi-ada-twist-phan-2', 'Nhà Khoa Học Nhí Ada Twist (Phần 2)', 'Ada Twist, Scientist (Season 2)', 'https://phimimg.com/upload/vod/20240603-1/c62fc5c99c2f3179ce6809b2ffa10fac.jpg', 'https://phimimg.com/upload/vod/20240603-1/365cac85bf188b4c819b1ca5be9bc12e.jpg', '<p>Trong mùa mới này, Ada cùng những người bạn yêu khoa học lục tung mọi ngóc ngách để tìm kiếm câu trả lời, từ cao tít trên trời đến sâu dưới lòng đất, và tất thảy mọi nơi!</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Christine","avatar":""},{"name":"Nicholas Crovetti","avatar":""},{"name":"Candace Kozak","avatar":""},{"name":"Terrence Little Gardenhigh","avatar":""},{"name":"Susan Kelechi Watson","avatar":""},{"name":"Taye Diggs","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324267);
