INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-khoa-hoc-nhi-ada-twist-phan-2', 'Nhà Khoa Học Nhí Ada Twist (Phần 2)', 'Ada Twist, Scientist (Season 2)', 'nhà khoa học nhí ada twist (phần 2) ada twist, scientist (season 2) amanda christine nicholas crovetti candace kozak terrence little gardenhigh susan kelechi watson taye diggs ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-em-co-gai-ruc-ro', 'Gặp Em Cô Gái Rực Rỡ', 'Hello, My Shining Love', 'https://phimimg.com/upload/vod/20240603-1/82dcd7e69a6deb0df896d487e6f7736d.jpg', 'https://phimimg.com/upload/vod/20240603-1/c373edd13e35c35c5a3daccf600461fc.jpg', '<p>Phim kể về cô gái mạnh mẽ, thành đạt Độc Cô Nhược Nam (do Trần Kiều Ân thủ vai) bỗng dưng bị nghệ sĩ dưới quyền quản lý của mình là Tống Tử Hào (do Vương Tử Duệ thủ vai) và nhân viên bắt tay nhau phản bội, sự nghiệp đang đà thăng tiến bỗng rơi xuống vực thẳm chỉ trong một đêm. Nhược Nam chưa bao giờ chịu thua, thề phải quay về thời kỳ huy hoàng. Cô dốc bao tâm huyết lăng xê Tư Đạt (do Trần Hựu Duy thủ vai), trong hành trình khởi đầu sự nghiệp lần thứ hai, trời xui đất khiến Độc Cô Nhược Nam lại cùng tổng giám đốc vừa nho nhã vừa độc miệng là Quý Mặc (do Kim Hạn thủ vai) bắt đầu cuộc hành trình vừa tô điểm cho nhau vừa soi tỏ cá tính riêng và sưởi ấm lẫn nhau, hai con người từng chịu tổn thương trong tình cảm cùng trình diễn một cuộc chiến ái tình trưởng thành đầy sâu sắc...</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"ChenQiaoen","avatar":""},{"name":"JinHan","avatar":""},{"name":"ChenYouwei","avatar":""},{"name":"WangZixuan","avatar":""},{"name":"Zou Tingwei","avatar":""},{"name":"Wang Jianing","avatar":""},{"name":"WangZirui","avatar":""},{"name":"Xie Shuai","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324267);
