INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sasaki-va-miyano', 'Sasaki Và Miyano', 'Sasaki And Miyano, Sasamiya, Sasaki To Miyano', 'https://phimimg.com/upload/vod/20240603-1/5d621a20060d9b2d2d6a7c8d2687f0f4.jpg', 'https://phimimg.com/upload/vod/20240603-1/365ed729c705663abf27db5a0951ff4d.jpg', '<p>Tất cả bắt đầu giống như một cốt truyện tình yêu điển hình của những cậu bé học sinh cũ - học sinh lớp trưởng xấu gặp một học sinh lớp dưới vụng về đáng yêu, một trong số họ yêu nhau, vân vân và vân vân. Nhưng mặc dù Miyano là một chuyên gia tình yêu của các chàng trai tự xưng, anh ấy đã không hoàn toàn nhận ra… chính anh ấy đang ở trong một tình yêu. Điều đó có nghĩa là tùy thuộc vào Sasaki để đảm bảo câu chuyện của họ có một hạnh phúc mãi mãi…!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 17, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324267);
