INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-chuong-la', 'Hồi Chuông Lạ', 'From', 'https://phimimg.com/upload/vod/20240603-1/e1a74af5433b99bbd1c030552cf9828e.jpg', 'https://phimimg.com/upload/vod/20240603-1/bd8281f442a3feb06ed40a2228750a1b.jpg', '<p>Làm sáng tỏ bí ẩn về một thị trấn hoang tàn ở miền Trung nước Mỹ, bẫy tất cả những ai bước vào. Khi những cư dân không muốn chiến đấu để giữ một cảm giác bình thường và tìm kiếm một lối thoát, họ cũng phải sống sót trước những mối đe dọa từ khu rừng xung quanh – bao gồm cả những sinh vật đáng sợ xuất hiện khi mặt trời lặn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eion Bailey","avatar":""},{"name":"Catalina Sandino Moreno","avatar":""},{"name":"Harold Perrineau","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324267);
