INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-tho-samurai-cau-chuyen-ve-usagi', 'Chú Thỏ Samurai: Câu Chuyện Về Usagi', 'Samurai Rabbit: The Usagi Chronicles', 'https://phimimg.com/upload/vod/20240603-1/af6ad964d2237070b1a48c131dd589b7.jpg', 'https://phimimg.com/upload/vod/20240603-1/3ae26f2074eb00c5e3a2f98a5f9ca3d7.jpg', '<p>Muốn trở thành samurai đích thực, chú thỏ thiếu niên bắt tay với hội bạn chiến binh mới để bảo vệ thành phố khỏi quái vật Yokai, ninja, người ngoài hành tinh xấu xa.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Darren Barnet","avatar":""},{"name":"Aleks Le","avatar":""},{"name":"Mallory Low","avatar":""},{"name":"Keone Young","avatar":""},{"name":"Shelby Rabara","avatar":""},{"name":"SungWon Cho","avatar":""},{"name":"Eric Bauza","avatar":""},{"name":"Sumalee Montano","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324268);
