INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lap-harem-chon-me-cung-o-di-gioi', 'Lập Harem Chốn Mê Cung Ở Dị Giới', 'A Harem In The Fantasy World Dungeon', 'https://phimimg.com/upload/vod/20240603-1/2b7c726821da3d3afd5c09c0267c7921.jpg', 'https://phimimg.com/upload/vod/20240603-1/9cffc063ecb700a00fede6f72469f391.jpg', '<p>Vào một ngày nọ, Michi Kaga, một chàng trai đã tuyệt vọng với thế giới này, vô tình phát hiện một trò chơi trực tuyến kỳ lạ. Nếu đã chán nản với thế giới đang sống, sao không sống ở một thế giới khác, bị thu hút bởi lời mời viết trên đó, Michio đã thật sự được dịch chuyển sang một thế giới khác ngay khi hoàn thành thiết lập nhân vật và thiết kế nhân vật. Ở vũ đài nơi dị giới, với những thiết lập không khác gì một trò chơi như Kĩ năng, Nghề nghiệp, Ma pháp và Mê cung, cuộc mạo hiểm của Michio Kaga bắt đầu, với sức mạnh cho phép cậu tái thiết lập bảng trạng thái của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
