INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-so-truc-quy', 'Ma Sơ Trục Quỷ', 'The Exorcist', 'https://phimimg.com/upload/vod/20231024-1/26682bfe41a12adb0fbd00857fbf58ee.jpg', 'https://phimimg.com/upload/vod/20231024-1/81d43e9359a65e269324001596af4118.jpg', '<p>Ofelia - một nữ tu trẻ vừa đặt chân đến thị trấn San Ramon đã bị ép phải thực hiện buổi lễ trừ tà cho một phụ nữ đang mang thai. Tưởng chừng buổi trục quỷ đã hoàn tất, Ofelia bàng hoàng nhận ra hiện thân quỷ dữ chưa từng biến mất.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"María Evoli","avatar":""},{"name":"Diana Bracho","avatar":""},{"name":"Tina Romero","avatar":""},{"name":"Norma Lazareno","avatar":""},{"name":"Salvador Sánchez","avatar":""},{"name":"Pilar Santacruz","avatar":""},{"name":"Julio Bracho","avatar":""},{"name":"Ramón Medína","avatar":""},{"name":"Juan Carlos Colombo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324268);
