INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-rong', 'Kỵ Sĩ Rồng', 'Dragon Knight', 'https://phimimg.com/upload/vod/20231023-1/707d1b6c0b383f2c58890ab305d52194.jpg', 'https://phimimg.com/upload/vod/20231023-1/ca8c5a7c43e3d0b30d2e946767431e7e.jpg', '<p>Nhiều năm sau khi chiến tranh thất bại và tất cả những con rồng bị giết, một hiệp sĩ đơn độc du hành đến vùng đất Agonos để tìm cách gây dựng một đội quân chống lại chúa quỷ Abaddon. Khi tầm nhìn của một người chữa bệnh cho thấy một con rồng vẫn còn sống, và cùng với một cận vệ trẻ đầy nhiệt huyết, hiệp sĩ lên đường tìm kiếm sinh vật huyền thoại. Khi quân đội của Abaddon tràn xuống vương quốc loài người, con rồng là hy vọng cuối cùng của họ chống lại đám đông trước khi nó tàn phá vùng đất của con người. Nhưng liệu sinh vật này có tồn tại không? Và nếu có, liệu nó có chiến đấu vì họ một lần nữa không?</p>', 'Full', 1, 'single', 'completed', 5, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ryan Livingstone","avatar":""},{"name":"Megan Tremethick","avatar":""},{"name":"Regan Walker","avatar":""},{"name":"Michael Daviot","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324268);
