INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-up-ro-dau-tien', 'Cú Úp Rổ Đầu Tiên', 'THE FIRST SLAM DUNK', 'https://phimimg.com/upload/vod/20231020-1/0ac9e300f5e1b10d44b1327145561b9a.jpg', 'https://phimimg.com/upload/vod/20231020-1/e5c2670ef85fe4e17bbf76862255adbe.jpg', '<p>“Người bảo vệ tốc độ” và người bảo vệ điểm của Shohoku, Ryota Miyagi, luôn chơi trí tuệ và tốc độ cực nhanh, chạy vòng quanh đối thủ trong khi giả vờ bình tĩnh. Vào năm thứ hai trung học, Ryota chơi với đội bóng rổ của trường trung học Shohoku cùng với Sakuragi , Rukawa, Akagi và Mitsui khi họ bước lên sân khấu tại Giải vô địch quốc gia liên cấp trung học. Và giờ đây, họ đang trên đà thách thức các nhà đương kim vô địch, Trường trung học Sannoh Kogyo.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shugo Nakamura","avatar":""},{"name":"Jun Kasama","avatar":""},{"name":"Shinichiro Kamio","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Ryota Iwasaki","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Chikahiro Kobayashi","avatar":""},{"name":"Masafumi Kobatake","avatar":""},{"name":"Kenichirou Matsuda","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Katsuhisa Houki","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
