INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-xe-giao-hang', 'Quái Xế Giao Hàng', 'Special Delivery', 'https://phimimg.com/upload/vod/20231018-1/573405cc78261ad335db09db23581686.jpg', 'https://phimimg.com/upload/vod/20231018-1/edbc273855c543eb9874d1e9f32df5ab.jpg', '<p>Eun Ha là nữ quái xế chuyên vận chuyển những “món hàng” bất thường với tỉ lệ thành công 100%. Vào ngày nọ, vì ra tay cứu giúp một đứa trẻ, cô đã trở thành mục tiêu săn đuổi của tên trùm tội phạm khét tiếng lẫn lực lượng cảnh sát Hàn.</p>', 'Full', 1, 'single', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park So-dam","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Song Sae-byuk","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Jung Hyeon-jun","avatar":""},{"name":"Yeon Woo-jin","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Han Hyun-min","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Yoo Seung-ho","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Baek Do-kyeom","avatar":""},{"name":"Han Kyu-won","avatar":""},{"name":"Kang Joon-kyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324268);
