INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('finnick-ngoi-nha-quai-vat', 'Finnick: Ngôi Nhà Quái Vật', 'Finnick', 'https://phimimg.com/upload/vod/20231018-1/91a7904138786e88b5bef29977d19ba0.jpg', 'https://phimimg.com/upload/vod/20231018-1/3211c21e6da52a5f61414af9c706fa04.jpg', '<p>Finnick là một người dường như không quan tâm đến việc kiếm tiền từ ngôi nhà của mình. Mọi thứ thay đổi khi một gia đình mới đến nhà anh ấy và những mánh khóe của Finnick hoàn toàn không hiệu quả. Anh gặp Christine và những sự kiện không thể giải thích được bắt đầu xảy ra trong thành phố. Finnick và Christine sẽ phải hợp tác và làm việc cùng nhau để giải quyết bí ẩn của các sự kiện và cứu thành phố. Kết thúc hành trình đó liệu cô bé Christine và yêu tinh Finnick có đem lại sự hòa bình cho ngôi làng và ‘một bí ẩn khác’ của Finnick có được phát hiện hay không?</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2022, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Danya Milokhin","avatar":""},{"name":"Ida Galich","avatar":""},{"name":"Aleksandr Gudkov","avatar":""},{"name":"Артур Бабич","avatar":""},{"name":"Boris Dergachev","avatar":""},{"name":"Mikhail Khrustalev","avatar":""},{"name":"Andrey Levin","avatar":""},{"name":"Ivan Chaban","avatar":""},{"name":"Mikhail Chernyak","avatar":""},{"name":"Maxim Sergeev","avatar":""},{"name":"Svetlana Kuznetsova","avatar":""},{"name":"Boris Khasanov","avatar":""},{"name":"Vladimir Maslakov","avatar":""},{"name":"Sergey Mardar","avatar":""},{"name":"Valeri Solovyev","avatar":""},{"name":"Igor Yakove","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]',