INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhim-sonic-2', 'Nhím Sonic 2', 'Sonic the Hedgehog 2', 'https://phimimg.com/upload/vod/20231017-1/f43b8f92948121593cd856c84d363765.jpg', 'https://phimimg.com/upload/vod/20231017-1/cc871d41d5ab8fdd5f3cc568903baa4b.jpg', '<p>Chú nhím xanh được yêu thích nhất thế giới trở lại cho cuộc phiêu lưu ở cấp độ tiếp theo trong Nhím Sonic 2. Sau khi định cư ở Green Hills, Sonic háo hức chứng tỏ mình sở hữu điều cần thiết để trở thành anh hùng thực thụ. Thách thức cho cậu xuất hiện khi Tiến sĩ Robotnik trở lại, lần này cùng đối tác mới là Knuckles, với mục đích kiếm tìm viên ngọc lục bảo có sức mạnh hủy diệt các nền văn minh. Sonic hợp tác với người bạn Tails và họ cùng nhau trên hành trình khắp địa cầu nhằm tìm ra viên ngọc lục bảo trước khi nó rơi vào tay kẻ xấu.</p>', 'Full', 1, 'single', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ben Schwartz","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Tika Sumpter","avatar":""},{"name":"Colleen O''Shaughnessey","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Jim Carrey","avatar":""},{"name":"Natasha Rothwell","avatar":""},{"name":"Adam Pally","avatar":""},{"name":"Shemar Moore","avatar":""},{"name":"Lee Majdoub","avatar":""},{"name":"Melody Nosipho Niemann","avatar":""},{"name":"Tom Butler","avatar":""},{"name":"Brad Kalilimoku","avatar":""},{"name":"Krista Alvarez","avatar":""},{"name":"Donna Jay Fulks","avatar":""},{"name":"Scott Patey","avatar":""},{"name":"Lei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","s