INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-sao-ma-thuat', 'Cây Sáo Ma Thuật', 'The Magic Flute', 'https://phimimg.com/upload/vod/20231017-1/9ecab259cb166ef9542e00e6ece68be3.jpg', 'https://phimimg.com/upload/vod/20231017-1/c8b8b8b9157fea7f1e52ba77818180c4.jpg', '<p>Một cậu bé mười bảy tuổi đi từ London đến dãy Alps của Áo để theo học trường nội trú huyền thoại Mozart. Ở đó, anh phát hiện ra một lối đi bị lãng quên hàng thế kỷ dẫn vào thế giới tuyệt vời của &quot;Cây sáo thần&quot; của Mozart.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Jack Wolfe","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Iwan Rheon","avatar":""},{"name":"Jeanne Goursaud","avatar":""},{"name":"Amir Wilson","avatar":""},{"name":"Stéfi Celma","avatar":""},{"name":"Wilson Gonzalez Ochsenknecht","avatar":""},{"name":"Steffen Mennekes","avatar":""},{"name":"Niamh McCormack","avatar":""},{"name":"Waldemar Kobus","avatar":""},{"name":"Luyanda Unati Lewis-Nyawo","avatar":""},{"name":"Stefan Konarske","avatar":""},{"name":"Tedros Teclebrhan","avatar":""},{"name":"Asha Banks","avatar":""},{"name":"Jasmin Shaker","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
