INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-nhan-tinh', 'Phi Nhân Tính', 'Unhuman', 'https://phimimg.com/upload/vod/20230925-1/f4688a0cc03aef755d8c46b22035f330.jpg', 'https://phimimg.com/upload/vod/20230925-1/c78a0f095a66d941428937810765b7d1.jpg', '<p>Sau khi xe buýt của trường gặp tai nạn, một nhóm học sinh trung học bị ném vào một cuộc chiến sinh tồn kinh hoàng khi họ cố gắng hạ gục một nhóm man rợ vô nhân đạo… trước khi chúng giết nhau trước.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brianne Tju","avatar":""},{"name":"Ali Gallo","avatar":""},{"name":"Benjamin Wadsworth","avatar":""},{"name":"Drew Scheid","avatar":""},{"name":"Lo Graham","avatar":""},{"name":"C.J. LeBlanc","avatar":""},{"name":"Uriah Shelton","avatar":""},{"name":"Joshua Mikel","avatar":""},{"name":"Peter Giles","avatar":""},{"name":"Blake Burt","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324268);
