INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('monster-portal', 'Monster Portal', 'Monster Portal', 'https://phimimg.com/upload/vod/20230925-1/dbe8400f1af33adab9f116b226007560.jpg', 'https://phimimg.com/upload/vod/20230925-1/a563d41ae846c9ebdfd8d58a638100b6.jpg', '<p>Một phụ nữ trẻ thừa kế tài sản của người cha ghẻ lạnh sau cái chết bí ẩn của ông. Khi cô và những người bạn của mình đến dinh thự, họ phát hiện ra rằng ngôi nhà nằm trên một nghĩa trang cũ, nơi có sức mạnh mở ra cánh cổng dẫn đến một thế giới khác, nơi chứa đựng những sinh vật được nhà văn H.P. Lovecraft.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sian Altman","avatar":""},{"name":"Sarah Alexandra Marks","avatar":""},{"name":"Louis James","avatar":""},{"name":"Judy Tcherniak","avatar":""},{"name":"George Nettleton","avatar":""},{"name":"Richard Harfst","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324268);
