INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('monster-portal', 'Monster Portal', 'Monster Portal', 'monster portal monster portal sian altman sarah alexandra marks louis james judy tcherniak george nettleton richard harfst ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-truoc-yeu-sau', 'Cưới Trước Yêu Sau', 'Love Start From Marriage', 'https://phimimg.com/upload/vod/20240521-1/bda3fa9e5aa35d6f4760af6339ec0ea4.jpg', 'https://phimimg.com/upload/vod/20240521-1/37787d99456bdf38b0a03c41ab5937d5.jpg', '<p>Cố Thừa Trạch và Hạ Thiên Ca vốn không dính dáng gì đến nhau, sau một cuộc gặp gỡ ngoài ý muốn, lại từ ấn tượng vốn có lúc ban đầu đến phá vỡ nhận thức truyền thống về nhau và trở nên hòa hợp với nhau, từ đó đưa ra lựa chọn theo trái tim mình. Hạ Thiên Ca vốn phải đeo xiềng xích từ gia đình, vì trách nhiệm và sứ mệnh trong lòng mà không dám theo đuổi tình cảm và cuộc sống mới. Nhưng sau khi tiếp xúc với Cố Thừa Trạch, sự dũng cảm bày tỏ, sự nghiền ngẫm và theo đuổi tình cảm cũng như sự nghiệp của Cố Thừa Trạch đã dần đánh thức tiếng lòng của Hạ Thiên Ca. Sau nhiều lần bại, cuối cùng cô cũng đập tan gông cùm số phận áp đặt lên người mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiao Keran","avatar":""},{"name":"Han Jihui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
