INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ly-thuc-thi', 'Công Lý Thực Thi', 'Justice Served', 'https://phimimg.com/upload/vod/20240521-1/23c0078001e1a104c37a42736ebea5be.jpg', 'https://phimimg.com/upload/vod/20240521-1/bf930dd9a5a0e24ae5ea5c97c7f04f18.jpg', '<p>Nhóm đấu tranh cho tự do thâm nhập phiên tòa xét xử sĩ quan cảnh sát da trắng bắn một người đàn ông da đen, và tình huống bắt giữ con tin được tường thuật trên toàn quốc.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Hlomla Dandala","avatar":""},{"name":"Pallance Dladla","avatar":""},{"name":"Alex McGregor","avatar":""},{"name":"Lerato Mvelase","avatar":""},{"name":"Dineo Rasedile","avatar":""},{"name":"Panch Gasela","avatar":""},{"name":"Morné Visser","avatar":""},{"name":"Nompumelelo Mayiyane","avatar":""},{"name":"Tiisetso Thoka","avatar":""},{"name":"Jack Devnarain","avatar":""},{"name":"Thabo Bopape","avatar":""},{"name":"Thami Dish","avatar":""},{"name":"Anton David Jeftha","avatar":""},{"name":"Bokang Phelane","avatar":""},{"name":"Daniel Janks","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
