INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-ly-thuc-thi', 'Công Lý Thực Thi', 'Justice Served', 'công lý thực thi justice served hlomla dandala pallance dladla alex mcgregor lerato mvelase dineo rasedile panch gasela morné visser nompumelelo mayiyane tiisetso thoka jack devnarain thabo bopape thami dish anton david jeftha bokang phelane daniel janks ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-vong-tro-lai', 'Cầu Vồng Trở Lại', 'Fallen Rainbow (Sai Roong)', 'https://phimimg.com/upload/vod/20240521-1/1f4fa70b64cf41690570a3ae60f0543b.jpg', 'https://phimimg.com/upload/vod/20240521-1/adae1f20d2b29ba9f75d2ddcc5250bc7.jpg', '<p>Methinee (Sammy Cowell) là một người mẫu xinh đẹp và tài giỏi. Cuộc sống của Me rất khổ sở do sống cùng người mẹ nghiện rượu, lại phải gánh thêm khoản nợ nần chồng chất từ bà. Me có mối tình đầu rất đẹp với Phak (Pong Nawat Kulrattanarak) nhưng vì sự ngăn cấm của mẹ mà Me buộc phải chia tay với anh. Phak quá suy sụp và chết trong một vụ tai nạn xe hơi. Me rất hối hận vì đã để xảy ra cơ sự này. Sóng gió lại đến với cuộc đời Me một lần nữa khi Me vô tình gặp Phongsathon (Pong Nawat Kulrattanarak), người trông giống hệt Phak. Vậy Phong là ai? Và liệu anh ta có liên quan đến Phak?</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2022, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Pong Nawat Kulrattanarak","avatar":""},{"name":"Sammy Cowell","avatar":""},{"name":"Pip Ravit Terdwong","avatar":""},{"name":"Kat Katreeya English","avatar":""},{"name":"Trerak Rakkandee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
