INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-gia-sieu-nang', 'Sứ Giả Siêu Năng', 'Sứ Giả Siêu Năng', 'https://phimimg.com/upload/vod/20240521-1/84391bb3857662cda81cc271e06b7698.jpg', 'https://phimimg.com/upload/vod/20240521-1/83f557b89c96dc8e844719db19f2ae3b.jpg', '<p>Ba người không quen biết xui xẻo gặp tai nạn thảm khốc cùng với nhau. Nhưng thần kỳ là họ không chết, mà sau tai nạn đó nhóm người còn bộc lộ năng lực siêu cường. Có người có khả năng ngưng đọng thời gian, người lại có thể trị liệu, người khác thì mình đồng da sắt. Kể từ đó, nhóm người vốn chẳng quen biết lại gắn kết với nhau theo cách đặc biệt nhất.<br/>&nbsp;</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Trần Triển Bằng","avatar":""},{"name":"Đường Thi Vịnh","avatar":""},{"name":"Trần Sơn Thông","avatar":""},{"name":"Vương Quân Hinh","avatar":""},{"name":"Lưu Bội Nguyệt","avatar":""},{"name":"Lưu Dĩnh Tuyền","avatar":""},{"name":"Thẩm Chấn Hiên","avatar":""},{"name":"Lâm Tử Thiện","avatar":""},{"name":"Ngũ Lạc Di","avatar":""},{"name":"Âu Thoại Vĩ","avatar":""},{"name":"Trương Quốc Cường","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
