INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tien-len-cac-be-cun-phan-3', 'Tiến Lên, Các Bé Cún! (Phần 3)', 'Go, Dog. Go! (Season 3)', 'tiến lên, các bé cún! (phần 3) go, dog. go! (season 3) michela luci callum shoniker lyon smith tajja isen anand rajaram david berni linda ballantyne joshua graham patrick mckenna judy marshak martin roach katie griffin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-cam-lanh', 'Chuyện Tình Cảm Lạnh', 'Love Is For Suckers', 'https://phimimg.com/upload/vod/20240521-1/c8b7fef1458cdd1571a1f359abff5d42.jpg', 'https://phimimg.com/upload/vod/20240521-1/9afe5476406717b151fd947875371166.jpg', '<p>Kể về Gu Yeo-Reum (Lee Da-Hee) làm giám đốc cho các chương trình truyền hình. Cô ấy đã làm việc với tư cách là một PD trong 10 năm qua, nhưng cô ấy đang gặp khủng hoảng do các buổi diễn của cô ấy bị hủy bỏ. Dự án tiếp theo của cô là chương trình truyền hình thực tế Kingdom of Love. Cô ấy làm việc chăm chỉ để làm cho buổi biểu diễn đó thành công. Trong cuộc sống cá nhân của riêng mình, Gu Yeo-Reum là bạn tốt của Park Jae-Hun (Choi Si-Won). Họ đã là bạn hơn 20 năm và họ cũng là hàng xóm của nhau. Park Jae-Hun là một bác sĩ và anh ấy làm việc cho một phòng khám phẫu thuật thẩm mỹ. Anh ấy đã không còn hứng thú với công việc của mình và việc tìm kiếm một đối tác lãng mạn. Để giúp đỡ người bạn Gu Yeo-Reum, anh quyết định tham gia chương trình truyền hình thực tế Kingdom of Love của cô với tư cách là một diễn viên bình thường. Trong khi làm việc cùng nhau với tư cách là một PD và thành viên diễn viên, họ đã bất ngờ nảy sinh tình cảm với nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Da-Hee","avatar":""},{"name":"Choi Si-Won","avatar":""},{"name":"Song Jong-Ho","avatar":""},{"name":"Jo Soo-Hyang","avatar":""},{"name":"Park Yeon-Woo","avatar":""},{"name":"Lim Ha-Ryong","avatar":""},{"name":"Yang Hee-Kyeong","avatar":""},{"name":"Min Jin-Woong","avatar":""},{"name":"Noh Susanna","avatar":""},{"name":"Lee Dae-Hwi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
