INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('exception', 'Exception', 'Exception', 'https://phimimg.com/upload/vod/20240521-1/4084ca767939a4e71ffb46f1e30d35d5.jpg', 'https://phimimg.com/upload/vod/20240521-1/b1c29e9e6e9bcde91f67ff7f89738cdc.jpg', '<p>Trong tương lai xa xôi khi con người buộc phải rời khỏi Trái Đất, một tàu vũ trụ chở phi hành đoàn in 3D gồm các chuyên gia được cử đi để địa khai hóa một hành tinh mới.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 9, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nolan North","avatar":""},{"name":"Robbie Daymond","avatar":""},{"name":"Ali Hillis","avatar":""},{"name":"Eugene Byrd","avatar":""},{"name":"Nadine Nicole","avatar":""},{"name":"Laura Bailey","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
