INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-tro-nen-manh-hon-nho-nang-cap-cac-ky-nang-cua-nong-dan', 'Tôi Trở Nên Mạnh Hơn Nhờ Nâng Cấp Các Kỹ Năng Của Nông Dân', 'I''ve Somehow Gotten Stronger When I Improved My Farm-Related Skills', 'https://phimimg.com/upload/vod/20240521-1/c5ea07998eae4d1fdfd1c792b89b9907.jpg', 'https://phimimg.com/upload/vod/20240521-1/a9c6e913cf3e6a4336e370adda9249ef.jpg', '<p>Al Wayne rất thích làm nông. Không phải là làm nông trong game đâu nhé, mà anh ta muốn trở thành một nông dân thực thụ cơ. Nhưng trong quá trình nâng điểm cho kỹ năng làm nông, vì một lý do nào đó mà chỉ số tổng thể của anh đã tăng vọt! Sức manh của anh đã trở nên không tưởng, đến mức ngay cả dũng sĩ mạnh nhất thế giới cũng phải ghen tị. Anh chỉ muốn một cuộc sống của nông dân bình thường, nhưng với việc quái vật và quỷ đến xâm lược, Al buộc phải khoác lên áo choàng dũng sĩ để bảo vệ giấc mơ của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324268);
