INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-tinh-phai-long-tuong-quan-trom-phai-tim-chang', 'Vô Tình Phải Lòng Tướng Quân (Trộm Phải Tim Chàng)', 'Follow My Dear General', 'https://phimimg.com/upload/vod/20240521-1/22f15ca1964dd0cf2bab7e3168fbc276.jpg', 'https://phimimg.com/upload/vod/20240521-1/bbaf82363723b7683e37ab57368e1b6d.jpg', '<p>Đệ nhất nữ tặc của An Hồn các đang có ý định rửa tay gác kiếm, quy ẩn chốn đồng quê. Nàng được giao nhiệm vụ đánh cắp bản đồ phòng thủ biên giới phía Nam của chiến thần nước Đông Duệ, Định Nam Tướng quân. Trong quá trình trà trộn vào làm tùy tùng thân cận bên cạnh Tướng quân, nàng đã đem lòng yêu nam nhân trung quân ái quốc này, đồng thời thấu hiểu đại nghĩa quốc gia, từ đó sát cánh cùng Tướng quân chống lại giặc thù, viết nên câu chuyện kề vai chiến đấu tuyệt đẹp.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Giai Lâm","avatar":""},{"name":"Hắc Trạch","avatar":""},{"name":"Đại Siêu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324268);
