INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tra-thu-cua-nguoi-thu-3', 'Sự Trả Thù Của Người Thứ 3', 'Revenge Of Others', 'https://phimimg.com/upload/vod/20240521-1/87e065aa68247df2d1d392574e65d430.jpg', 'https://phimimg.com/upload/vod/20240521-1/6bf3ef9a03a9ac416186887c9e23ed8b.jpg', '<p>Một cậu bé rơi xuống chết ở trường, nhưng Ok Chanmi không tin rằng anh trai sinh đôi của cô, Park Wonseok, đã tự tử. Chanmi chuyển đến trường của anh trai cô, Yongtan High, và gặp Ji Sooheon, người đã chứng kiến cái chết của anh trai cô.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Yoo-Jin","avatar":""},{"name":"Lomon","avatar":""},{"name":"Seo Ji-Hoon","avatar":""},{"name":"Chae Sang-Woo","avatar":""},{"name":"Lee Soo-Min","avatar":""},{"name":"Chung Su-Bin","avatar":""},{"name":"Kim Joo-Ryung","avatar":""},{"name":"Woo Yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
