INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-kich-giet-cha-cua-gia-dinh-templet', 'Bi Kịch Giết Cha Của Gia Đình Templet', 'I Just Killed My Dad', 'https://phimimg.com/upload/vod/20240521-1/ceed603eaf7c03fa0596d948cab377e1.jpg', 'https://phimimg.com/upload/vod/20240521-1/7d9ed859ac0261e7c0720475f9879900.jpg', '<p>Anthony Templet đã bắn cha mình và không hề phủ nhận điều đó. Nhưng việc này dẫn đến câu hỏi phức tạp với hàm ý sâu xa vượt khỏi phạm vi một gia đình: tại sao y làm vậy?</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324268);
