INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-nhat-anh-muon-sao-day', 'Long Nhật, Anh Muốn Sao Đây?', 'Dragon Day, You''re Dead S3', 'https://phimimg.com/upload/vod/20240521-1/1dbab4046156c3ab4f89733da212972c.jpg', 'https://phimimg.com/upload/vod/20240521-1/826c8afe61e77ce9b0cc0668dc29ecde.jpg', '<p>Sau khi tốt nghiệp, sinh viên xuất sắc Trương Tịnh Mỹ xuất thân từ một gia đình bình thường, vừa phải đối mặt với áp lực của việc chọn nghề, vừa phải kết hôn với chàng thiếu gia nhà giàu Long Nhất và có một cuộc sống hoàng tử với công chúa khiến người khác ngưỡng mộ. Tuy nhiên, cuộc sống giàu sang và con đường sự nghiệp không hề dễ dàng như trong tưởng tượng. Những thử thách trong cuộc sống liên tục ập đến với đôi vợ chồng son này. Khi thiếu gia nhà giàu rời khỏi ghế nhà trường bắt đầu bước vào xã hội, cùng Trương Tịnh Mỹ đối mặt với các thử thách trong cuộc sống thì có vô số vấn đề đang chờ họ cùng nhau giải quyết.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"QiuHenan","avatar":""},{"name":"HouPeishan","avatar":""},{"name":"Su Yuhang","avatar":""},{"name":"Bai Huizi","avatar":""},{"name":"Mai Wulan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
