INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fakes', 'Fakes', 'Fakes', 'https://phimimg.com/upload/vod/20240521-1/78839b90cfefac08350687aa5d2cb5a4.jpg', 'https://phimimg.com/upload/vod/20240521-1/9cce5a416c3648a41fb482de60ddf27f.jpg', '<p>Đôi bạn thân tuổi teen Zoe và Becca bắt tay vào xây dựng đế chế ID giả của riêng mình, nhưng khi việc kinh doanh nở rộ, cuộc sống tội phạm của họ trở nên quá thật.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Emilija Baranac","avatar":""},{"name":"Jennifer Tong","avatar":""},{"name":"Richard Harmon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
