INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-kim-nha-hoan', 'Thiên Kim Nha Hoàn', 'Qian Jin Ya Huan', 'https://phimimg.com/upload/vod/20240521-1/ca1bb9334eef0cc4bd65977785e0aceb.jpg', 'https://phimimg.com/upload/vod/20240521-1/ff440e893c8881d31dc6a247cf689660.jpg', '<p>Nhà họ Đổng ở Giang thành bị giết sạch sau một đêm, thiên kim Đổng Thính Dao bị buộc phải đến nhà vị hôn phu tìm kiếm sự giúp đỡ. Không thể ngờ sau khi đến nhà họ Phương, Thính Dao phát hiện mình bị thay thế, bản thân từ thiên kim trở thành nha hoan, hơn nữa lại phát hiện người mình cầu hầu hạ lại chính là kẻ thù giết cha mình - Đốc quân Phương Thiên Dật nổi danh khắp Giang thành. Thính Dao một lòng muốn báo thù nhưng cô không hề hay biết người thật sự mang đến hoạ cho nhà họ Đổng chính là vị hôn phu Phương Thiên Trạch của cô. Đổng Thính Dao làm thế nào để hoàn thành kế hoạch báo thù? Phải làm sao đối diện với tình cảm của hai chú cháu nhà họ Phương?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Phương Đồng","avatar":""},{"name":"Đại Cao Chính","avatar":""},{"name":"Nguỵ Thiên Hạo","avatar":""},{"name":"Đổng Nhan","avatar":""},{"name":"Hầu Oánh Giác","avatar":""},{"name":"Trương Thuỵ Ân","avatar":""},{"name":"Hồ Hi Phàm","avatar":""},{"name":"Trần Viễn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324268);
