INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trai-cua-mat-tich-phan-2', 'Mặt Trái Của Mất Tích (Phần 2)', 'Missing: The Other Side (Season 2)', 'https://phimimg.com/upload/vod/20240521-1/e57b96b458d7c25b1b112b795f3c0d14.jpg', 'https://phimimg.com/upload/vod/20240521-1/297ec9c0ae931da71d5d6f84b42a2001.jpg', '<p>Hành trình giải mã bí ẩn tại ngôi làng có linh hồn của những người đã mất tích sinh sống của Kim Wook cùng gã đàn ông bí hiểm Pan Seok và cô nàng hacker cá tính Jong Ah lại tiếp tục. Cả nhóm sẽ cố gắng tìm thi thể của những người mất tích và khám phá sự thật đằng sau cái chết của họ.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Go Soo","avatar":""},{"name":"Heo Jun Ho","avatar":""},{"name":"Ahn So Hee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
