INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hoa-nguyen-ky-cua-ha-gia-gia', 'Đào Hoa Nguyên Ký Của Hà Gia Gia', 'Jiajia''s Lovely Journey', 'https://phimimg.com/upload/vod/20240521-1/d8bd79e3360341b3709de8da46dcd019.jpg', 'https://phimimg.com/upload/vod/20240521-1/450a8fbec6f1b85f00f202a3c674b265.jpg', '<p>Sau khi chịu liền lúc hai cú sốc vừa thất nghiệp vừa bị bạn trai bỏ rơi thì Hà Gia Gia đã rời bỏ cuộc sống thành thị, đến với vùng thôn quê xinh đẹp sinh sống. Tại nơi này, cô đã gặp rất nhiều người với tính cách khác nhau, trong đó có nhà văn Phương Văn Vũ. Mối quan hệ của họ bắt đầu từ một sự hiểu lầm sau đó là cùng chung tay giải quyết vấn đề. Với vẻ đẹp tự nhiên của vùng nông thôn và tình yêu thương của mọi người xung quanh, Gia Gia dần bắt đầu tìm lại chính mình, tìm lại sự tự tin và tìm thấy hạnh phúc, hướng đi trong tương lai cho bản thân.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Đức Thụy","avatar":""},{"name":"Wang Ying Ying","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
