INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sherwood-phan-1', 'Sherwood (Phần 1)', 'Sherwood (Season 1)', 'https://phimimg.com/upload/vod/20240521-1/314d8abe0d938f907ddd3092f03aabc4.jpg', 'https://phimimg.com/upload/vod/20240521-1/315e8edee3f07e5d7221c05dc5c47946.jpg', '<p>Hai vụ giết người làm tan nát một cộng đồng vốn đã rạn nứt dẫn đến một trong những vụ truy lùng lớn nhất trong lịch sử nước Anh, đồng thời đe dọa thổi bùng những chia rẽ lịch sử đã gây ra trong Cuộc đình công của thợ mỏ ba thập kỷ trước.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"David Morrissey","avatar":""},{"name":"Adam Hugill","avatar":""},{"name":"Terence Maynard","avatar":""},{"name":"Robert Glenister","avatar":""},{"name":"Andrea Lowe","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
