INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sherwood-phan-1', 'Sherwood (Phần 1)', 'Sherwood (Season 1)', 'sherwood (phần 1) sherwood (season 1) david morrissey adam hugill terence maynard robert glenister andrea lowe ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-quan-nguy-hiem-cua-ta', 'Phu Quân Nguy Hiểm Của Ta', 'Dangerous Love', 'https://phimimg.com/upload/vod/20240521-1/f59c81cfa3e9bee04cd5b7812a7e6f0a.jpg', 'https://phimimg.com/upload/vod/20240521-1/9197c99dc5e0cb7a3916d6edb7619ae5.jpg', '<p>Hoàng đế Đại Chu còn nhỏ tuổi, việc triều chính do tên gian thần Vệ Thương Chi nắm giữ. Nghe đồn rằng Vệ Thương Chi là một kẻ vừa xấu xa vừa háo sắc, cưới liên tiếp sáu bà vợ đều đột ngột qua đời trong đêm tân hôn. Bạch Chỉ là người vợ thứ bảy của hắn, nàng run rẩy gả vào phủ Tĩnh Bắc Hầu, vốn tưởng rằng mình sẽ không sống nổi một ngày, ai ngờ lại phát hiện tên gian thần này dường như không giống với lời đồn đại bên ngoài…</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Qige","avatar":""},{"name":"Yang Xiaoting","avatar":""},{"name":"Wang Hanwen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324268);
