INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-xuyen-thoi-khong', 'Tình Yêu Xuyên Thời Không', 'Love Unexpected', 'https://phimimg.com/upload/vod/20240521-1/ca39f494317e42a0b9441992b2173865.jpg', 'https://phimimg.com/upload/vod/20240521-1/b9836c7b4ea7141d72a872decd3f1d3e.jpg', '<p>Câu chuyện kể rằng Lộc Phiên Phiên, một chuyên gia dinh dưỡng, trở về 5 năm trước nhờ bong bóng Fermi, cô gặp Lưu Nhược Sâm- một luật sư vẫn chưa nổi tiếng. Lưu Nhược Sâm đã yêu cô gái ngốc nghếch ngay từ cái nhìn đầu tiên, và thậm chí lao vào lửa để cứu cô. Chính vì ngọn lửa này, Lộc Phiên Phiên hiểu rằng lần trở về này có thể là cơ hội để cô bắt đầu lại từ đầu. Sau đó, Lộc Phiên Phiên và Lưu Nhược Sâm đã chung tay giải cứu Lâm Anh Tử, nạn nhân của bạo hành gia đình. Giúp ca sĩ thần tượng thế hệ mới Tiền Minh Lịch giải quyết được nút thắt của trái tim và tìm lại được người thân bị lạc, điều gây náo động cả làng giải trí. Ngay khi Lưu Nhược Sâm lấy hết can đảm để tỏ tình vớiLộc Phiên Phiên, một tai nạn và một mối nguy hiểm ập đến. Lộc Phiên Phiên bị mất trí nhớ và biến mất đột ngột, Lưu Nhược Sâm chết trong một vụ nổ, và những người bạn của anh lần lượt gặp nguy hiểm.Chuyện này là sao? Kẻ chủ mưu đứng sau là ai? Hãy cùng đón xem...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tingdong Yang","avatar":""},{"name":"Gong Wan Yi","avatar":""},{"name":"Yinsong Ren","avatar":""},{"name":"Ren Yin Peng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324268);
