INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-mau-trang-hoa', 'Dòng Máu Trăng Hoa', 'Lady Kaki', 'https://phimimg.com/upload/vod/20240521-1/d432d54b4db8e52caab19bae2f568dbf.jpg', 'https://phimimg.com/upload/vod/20240521-1/412d7a297836bc408b535a596fa3b5f5.jpg', '<p>Phim xoay quanh những cuộc chiến tranh giành tình cảm, những đấu đá đi cùng với sự trả thù, rửa hận. Những ân - oán - tình - thù của đời bố mẹ từ quá khứ kéo dài đến hiện tại, ảnh hưởng đến cả thế hệ con cái. Liệu tình yêu có thể chấm dứt những hận thù để mọi thứ trở về đúng nghĩa vốn có của nó?</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Kelly Rattapong Tanapat","avatar":""},{"name":"Ae Isariya Saisanan","avatar":""},{"name":"Kett Tharntup","avatar":""},{"name":"Benz Punyaporn Pongpipat","avatar":""},{"name":"Indy Intad Leowrakwong","avatar":""},{"name":"Natalie Panalee Varunwongse","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
