INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-ket-tinh-yeu', 'Hồi Kết Tình Yêu', 'The End Of Love', 'https://phimimg.com/upload/vod/20240521-1/018665affbcb496deacf5d7b277395e7.jpg', 'https://phimimg.com/upload/vod/20240521-1/72f977e1aca0020ae5a0d88cb16aa928.jpg', '<p>Sau khi đoàn tụ với quá khứ của mình, Tamara - một nghệ sĩ rock theo chủ nghĩa nữ quyền theo chủ nghĩa Do Thái cũ - ly thân với bạn trai, phản đối tình yêu lãng mạn và chế độ một vợ một chồng để dấn thân vào con đường khám phá nhằm tìm kiếm mong muốn của riêng mình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Lali Espósito","avatar":""},{"name":"Vera Spinetta","avatar":""},{"name":"Julieta Giménez Zapiola","avatar":""},{"name":"Mariana Genesio Peña","avatar":""},{"name":"Andres Gil","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
