INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pinecone-pony-phan-1', 'Pinecone & Pony (Phần 1)', 'Pinecone & Pony (Season 1)', 'https://phimimg.com/upload/vod/20240520-1/29f18d12063e9b223a0da5d4a3e7fd77.jpg', 'https://phimimg.com/upload/vod/20240520-1/0c3d386ecc24aaf3ad14c5fbd320504e.jpg', '<p>Cuốn sách yêu thích của Kate Beaton trở nên sống động trong loạt phim hoạt hình này. Là một chiến binh đang được huấn luyện, Pinecone không sợ thử thách nào. Rất may, Pony luôn đảm bảo rằng Pinecone không bao giờ vượt lên trên đầu cô ấy. Họ cùng nhau tìm hiểu cuộc sống có thể là một cuộc phiêu lưu đầy thú vị.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maria Nash","avatar":""},{"name":"Andy Hull","avatar":""},{"name":"Chase W. Dillon","avatar":""},{"name":"Rachel House","avatar":""},{"name":"Thom Allison","avatar":""},{"name":"Viola Abley","avatar":""},{"name":"Alicia Richardson","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
