INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-cua-me', 'Giấc Mơ Của Mẹ', 'Giấc Mơ Của Mẹ', 'https://phimimg.com/upload/vod/20240625-1/f2d2b125af901aa88d6c60fc0a4e8271.jpg', 'https://phimimg.com/upload/vod/20240625-1/fd7ab183f7b9209a9d5f8e37125328e2.jpg', '<p>Giấc Mơ Của Mẹ là bộ phim gần gũi và thân thuộc với mọi cảnh đời Việt Nam, khai thác nỗi lòng của người mẹ với các con của mình. Trong Giấc Mơ Của Mẹ, người xem sẽ thấy chính mình và những người thân quen nhất với bàn tay tài ba của đạo diễn Nguyễn Minh Chung, nhà sản xuất Nguyễn Quang Dũng, đạo diễn hình ảnh Nguyễn Tranh và diễn xuất của các diễn viên: NSND Hồng Vân, NSƯT Hữu Châu, NSND Kim Xuân, Huỳnh Anh Tuấn, Khánh Huyền, Nhan Phúc Vinh, Diễm My 9x, Trần Ngọc Vàng, Trần Quốc Anh, Kim Nhã.</p>', 'Hoàn Tất (87/87)', 87, 'series', 'completed', 11, 2022, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"NSND Hồng Vân","avatar":""},{"name":"NSƯT Hữu Châu","avatar":""},{"name":"Diễm My 9x","avatar":""},{"name":"Nhan Phúc Vinh","avatar":""},{"name":"Trần Quốc Anh","avatar":""},{"name":"Trần Ngọc Vàng","avatar":""},{"name":"NSƯT Kim Xuân","avatar":""},{"name":"Khánh Huyền","avatar":""},{"name":"Huỳnh Tuấn Anh","avatar":""},{"name":"Kim Nhã","avatar":""},{"name":"Ngân Hòa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
