INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anime-ba-quyen', 'Anime Bá Quyền', 'Anime Supremacy', 'https://phimimg.com/upload/vod/20240624-1/26ebab4f1dacd86a7115d6e940c340aa.jpg', 'https://phimimg.com/upload/vod/20240624-1/3bb3ddd2810475e38e6e91d30856bc59.jpg', '<p>Hitomi làm việc cho một công ty sản xuất phim hoạt hình Nhật Bản và cuối cùng cũng nhận được bộ phim đầu tay do mình làm đạo diễn. Khó khăn chồng chất khó khăn khi cô phải làm việc chung với một nhà sản xuất khó tính cùng đội ngũ nhân viên thiếu tinh thần hợp tác của anh ta. Không chỉ có vậy, thách thức lại như được nhân đôi khi tác phẩm do cô đạo diễn sẽ lên sóng cùng khung giờ với tác phẩm mới đầy hứa hẹn của vị đạo diễn lẫy lừng Chiharu. Một cuộc đối đầu nảy lửa sẽ xảy ra khi cả hai cùng hướng về mục tiêu cao nhất: “Anime Bá Quyền”.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Riho Yoshioka","avatar":""},{"name":"Tomoya Nakamura","avatar":""},{"name":"Tasuku Emoto","avatar":""},{"name":"Machiko Ono","avatar":""},{"name":"Asuka Kudo","avatar":""},{"name":"古舘寛治","avatar":""},{"name":"Karin Ono","avatar":""},{"name":"Yuu Tokui","avatar":""},{"name":"高野麻里佳","avatar":""},{"name":"Seiji Rokkaku","avatar":""},{"name":"Tomoya Maeno","avatar":""},{"name":"朴璐美","avatar":""},{"name":"Kou Maehara","avatar":""},{"name":"Minosuke","avatar":""},{"name":"Mina Ōba","avatar":""},{"name":"新谷真弓","avatar":""},{"name":"Toshihiro Yashiba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
