INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-trom-lich-su-ngan-hang-trung-uong-brazil', 'Vụ Trộm Lịch Sử Ngân Hàng Trung Ương Brazil', 'The Great Robbery Of Brazil''s Central Bank', 'https://phimimg.com/upload/vod/20240520-1/2940d0fb663e223f7af52fb22263f0fa.jpg', 'https://phimimg.com/upload/vod/20240520-1/f62c8c4c83897f348f376e95ea832ddc.jpg', '<p>Loạt phim tài liệu khám phá vụ trộm lịch sử đầy ngoạn mục năm 2005: bọn trộm đào hầm vào kho tiền của một ngân hàng ở Fortaleza, Brazil và cuỗm hơn 160 triệu real.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Brazil', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
