INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-que-mochi-mo-nha-hang', 'Bánh Quế + Mochi: Mở Nhà Hàng', 'Waffles + Mochi''s Restaurant', 'https://phimimg.com/upload/vod/20240520-1/a07084915fd821efa0d22196a6d95a92.jpg', 'https://phimimg.com/upload/vod/20240520-1/8b4a7a1355763b5fd6908d8bd8873b54.jpg', '<p>Đôi bạn mê ẩm thực Bánh Quế và Mochi nấu ăn trong nhà hàng của chính họ, nơi những thực khách đói bụng tìm đến để thưởng thức hương vị từ khắp nơi trên thế giới!</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
