INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-luat-su', 'Bộ Đôi Luật Sư', 'May It Please The Court', 'https://phimimg.com/upload/vod/20240520-1/c22f8aeb01c4f09e1cefe79353262f20.jpg', 'https://phimimg.com/upload/vod/20240520-1/09948cb0e54e6d40adf8b3f91caf32d8.jpg', '<p>Luật sư Ace của một công ty luật lớn, No Chak Hee, sẵn sàng chấp nhận mọi rủi ro để thắng một vụ kiện và được thiết lập để được thăng chức lên vị trí đối tác nhưng một vấn đề xảy ra trong một vụ án mà cô ấy đã chấp nhận. Vì vụ án, cô ấy bị đình chỉ trong một năm. Sau đó, cô bắt đầu bắt đầu công việc như một người bảo vệ công cộng nhưng hy vọng sẽ trở lại vị trí của mình tại công ty luậtnơi cô ấy đã làm việc trước đây. Là một người bảo vệ công chúng, cô ấy chia sẻ văn phòng với người bảo vệ công chúng, Jwa Shi Baek, một sinh viên tốt nghiệp hàng đầu từ Viện Nghiên cứu và Đào tạo Tư pháp. Thay vì trở thành thẩm phán, công tố viên hoặc luật sư tại một công ty luật lớn, anh ấy đã chọn làm một người bảo vệ công chúng. Anh ấy nhiệt tình với công việc của mình nhưng cũng có một phần bí ẩn trong cuộc sống cá nhân của mình mà không ai biết về. Không có Chak Hee và Jwa Shi Baek không hợp nhau lắm, nhưng một vụ án giết người hàng loạt đã đưa họ đến với nhau và khi họ cố gắng giải quyết vụ án cùng nhau, nhiều bí mật được hé lộ và họ trở nên tin tưởng lẫn nhau.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 16, 2022, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Ryeo-Won","avatar":""},{"name":"Lee Kyu-Hyung","avatar":""},{"name":"Jung Jin-Young","avatar":""},{"name":"Kim Hye-Eun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
