INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rac-roi-be-bi', 'Rắc Rối Bé Bi', 'Baby Fever', 'https://phimimg.com/upload/vod/20240520-1/3043e54b2ec8b2485143200d8b1ea0d9.jpg', 'https://phimimg.com/upload/vod/20240520-1/e8fefa9c66f1f7f97f64a1b99f1fcb14.jpg', '<p>Sau khi thụ tinh trứng của mình với tinh trùng của bạn trai cũ trong lúc say, vị bác sĩ sản khoa phải chật vật giải thích về cái thai và giành lại tình yêu đã mất.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2022, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Josephine Park","avatar":""},{"name":"Olivia Joof","avatar":""},{"name":"Simon Sears","avatar":""},{"name":"Emil Prenter","avatar":""},{"name":"Mikael Birkkjær","avatar":""},{"name":"Charlotte Munck","avatar":""},{"name":"Tammi Øst","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
