INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-cuc-cua-toi', 'Thiên Cực Của Tôi', 'Sky In Your Heart', 'https://phimimg.com/upload/vod/20240520-1/fe7c0f597b9a177c66bc2ba6334a4dd1.jpg', 'https://phimimg.com/upload/vod/20240520-1/9198e0452eb80e38afcf5d08889004b0.jpg', '<p>Phim kể về Kuafah (Mek Jirakit Thawornwong) cùng nhóm bạn đang đi đến một ngôi làng ở vùng núi xa xôi để làm bác sĩ tình nguyện. Tại đây, Kuafah đã gặp Prince (Mark Jiruntanin Trairattanayon), giáo nguyên tình nguyện duy nhất của ngôi làng. Từ đó, giữa họ luôn xảy ra những mâu thuẫn từ nhỏ nhặt đến phức tạp. Tuy nhiên, dần dần, họ lại nảy sinh tình cảm với nhau.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mek Jirakit Thawornwong","avatar":""},{"name":"Mark Jiruntanin Trairattanayon","avatar":""},{"name":"Joong Archen Aydin","avatar":""},{"name":"Dunk Natachai Boonprasert","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
