INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-tinh-noi', 'Bình Tĩnh Nói', 'Simmer Down', 'https://phimimg.com/upload/vod/20240520-1/d4ad0403653203469163ea6a6ba466e6.jpg', 'https://phimimg.com/upload/vod/20240520-1/81e8b02ad969b66848f7cda12a2a3179.jpg', '<p>Yang Guang, người dẫn chương trình chuyên mục tâm sự tình cảm, đã từ chối giao tiếp chân thành với mọi người cả trong công việc và cuộc sống vì bị bóng đen tâm lý từ thuở ấu thơ. Cho đến khi một chương trình mới hot thay thế vị trí chính của chuyên mục Dương Quang. Trước sức ép, Dương Quảng quyết định sửa đổi chuyên mục, từ nghe trực tuyến sang hòa giải ngoại tuyến, và hòa giải các tranh chấp có thể gây nóng mạng xã hội. Chuyên mục nhận được sự chú ý vì điều này, và nó cũng khiến Yang Guang lần đầu tiên đối mặt với vấn đề của chính mình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Xiao","avatar":""},{"name":"Wang Xiaochen","avatar":""},{"name":"Wang Yaoqing","avatar":""},{"name":"Zeng Li","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
