INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-co-goo-pil-soo', 'Không Có Goo Pil Soo', 'Goo Pil Soo Is Not There', 'https://phimimg.com/upload/vod/20240520-1/89e0727ea13f6713698e353e2d133279.jpg', 'https://phimimg.com/upload/vod/20240520-1/b380cbc524bc9313ea5d74d83063cf84.jpg', '<p>Jung Seok là một thiên tài ở độ tuổi 20, người có mục đích thành lập công ty khởi nghiệp của riêng mình. Sau khi vào trường cao đẳng danh giá nhất ở Seoul mà không có bất kỳ sự trợ giúp nào từ các cơ sở giáo dục tư nhân, Jung Seok mơ ước trở thành Mark Zuckerberg của Hàn Quốc, đồng sáng lập Facebook. Không có Goo Pil Soo sẽ khắc họa tình cảm giữa Jung Seok và Goo Pil Soo, một người đàn ông ở độ tuổi 40 đang tìm kiếm một bước đột phá trong cuộc sống của mình, sẽ do Kwak Do Won thủ vai. Ngoài ra, bộ phim cũng sẽ đề cập đến các vấn đề xã hội đa dạng ở Hàn Quốc, từ giáo dục đến việc làm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kwak Do-Won","avatar":""},{"name":"Yoon Doo-Joon","avatar":""},{"name":"Han Go-Eun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
