INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tu-thoi-thuong', 'Bộ Tứ Thời Thượng', 'The Fabulous', 'https://phimimg.com/upload/vod/20240520-1/c64b742ed7de1aaf5ca6fa35a51d4ba2.jpg', 'https://phimimg.com/upload/vod/20240520-1/f48a845d6e17939e52dddc7271fe8ee8.jpg', '<p>Bốn người bạn thân vừa theo đuổi ước mơ nơi thế giới thời trang đầy cạnh tranh, vừa xoay sở giữa công việc yêu cầu cao, rắc rối tình ái và những đêm điên cuồng trong thành phố.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 4, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Chae Soo Bin","avatar":""},{"name":"Choi Min Ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
