INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-du-hanh-di-gioi-cua-toi', 'Chuyến Du Hành Dị Giới Của Tôi', 'My Journey In An Alternate World', 'https://phimimg.com/upload/vod/20240520-1/ac9b94f09c855391a15e4e2de5ccd66f.jpg', 'https://phimimg.com/upload/vod/20240520-1/d5a503e63a1d975c13be22e1c98fbde5.jpg', '<p>Thiếu niên Trần Tiểu Phàm vì nuốt nhầm Hỗn Nguyên Châu mà tiến vào một thế giới khác, trở thành thiếu gia nhà họ Trần kiếm cơm nhờ khuôn mặt mĩ nam tử đẹp nhất thành Mộ Vân. Hắn phát hiện tuy hắn nhận được sự mến mộ và theo đuổi của nữ tử trong thành Mộ Vân nhưng lại là một tên phế vật không thể tu luyện. Vì để quay lại được thế giới của mình hắn từ bỏ cuộc sống yên ổn của một thiếu gia, chống lại sự phản đối kịch liệt của gia tộc, kiên quyết dấn thân vào con đường tu luyện.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
