INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-hong-nuong-cua-yeu-hoang-dai-nhan', 'Tiểu Hồng Nương Của Yêu Hoàng Đại Nhân', 'Demon Emperor''s Little Matchmaker', 'https://phimimg.com/upload/vod/20240520-1/837e9f302c62dee797034b3afa695fc9.jpg', 'https://phimimg.com/upload/vod/20240520-1/1e4d562b3c5a440b1c221ae5484f3da1.jpg', '<p>Lệ Vô Ưu - người thừa kế vị yêu hoàng vì mang dòng máu nửa nửa người yêu mà chịu bao khổ sở, dần dần trở nên cô độc, lạnh lùng, không muốn tiếp xúc nữ với tử. Chuyện này làm cho người đã hứa sẽ cho anh một mối lương duyên tốt đẹp là Nguyệt Lão lo không lắng yên, đành bất lực mà đẩy chuyện này cho hồng nương thực tập Kiều Sở. Nguyệt Lão phái cô hạ phạm, thắt dây tơ hồng thay Lệ Vô Ưu, nếu thành công có thể trở thành hồng nương chính thức của điện Lão Nguyệt. Để hoàn thành nhiệm vụ, Kiều Sở đã nghĩ ra rất nhiều quỷ kế, cuộc sống đang yên bình của Lệ Vô Trừng từ đó cũng bỗng chốc loạn hết hết lên. Trái tim cũng không biết đã trao cho nàng tiên nữ kì quái này tự lúc...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 4, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lâm Thế Kiệt","avatar":""},{"name":"Vương Nặc Nhất","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324268);
