INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-dam-mau', 'Trái Tim Đẫm Máu', 'Bloody Heart', 'https://phimimg.com/upload/vod/20240520-1/2cde2d8f8327a8c1532bff4e29350f18.jpg', 'https://phimimg.com/upload/vod/20240520-1/1f4c7b4c4464f0e25b874b48345e38cc.jpg', '<p>Trái Tim Đẫm Máu là một bộ phim lịch sử hư cấu kể về câu chuyện tình chính trị đẫm máu giữa Lee Tae (Lee Joon đóng), một vị vua vì để tồn tại mà phải từ bỏ người phụ nữ mình yêu và Yoo Jung (Kang Han Na thủ vai), một người phụ nữ buộc phải chấp nhận trở thành vương hậu để tồn tại. Có thể nói tóm gọn đây là bộ phim giống như chuyện tình Romeo và Juliet nhưng là ở thời Joseon, hứa hẹn sẽ mang đến chuyện tình bi thương, đẫm nước mắt của cặp đôi chính.Được biết, nam chính Lee Tae trong phim Trái Tim Đẫm Máu vốn là con trai hợp pháp của Vua Sunjong, người trở thành vua sau cuộc nổi loạn, lên ngôi của Joseon. Cha của Lee Tae đã phế truất nhà vua với sự giúp đỡ của Park Gye Won và cha anh trở thành vua của một triều đại mới. Sau khi nối ngôi cha, Lee Tae sau đó trở thành vị vua tiếp theo. Lee Tae tin rằng bất kỳ hành động nào cũng là chính đáng để đạt được mục đích của mình. Anh ta muốn cai trị như một vị vua tuyệt đối, nhưng Phó Thủ tướng thứ nhất Park Gye Won phản đối ý tưởng đó. Park Gye Won thậm chí còn quyền lực hơn cả vua.Trong khi đó, Yoo Jung là con gái của một gia đình quyền quý. Lee Tae coi cô ấy như vợ của anh ấy. Do đó, gia đình cô vướng vào một cuộc tranh giành quyền lực trong cung đình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Joon","avatar":""},{"name":"Kang Han Na","avatar":""},{"name":"Jang Hyuk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
