INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-an-do-da-thu-bangalore', 'Sát Nhân Ấn Độ: Dã Thú Bangalore', 'Beast Of Bangalore: Indian Predator', 'https://phimimg.com/upload/vod/20240520-1/22df8ac40cc4b65228cc2f216b335d0f.jpg', 'https://phimimg.com/upload/vod/20240520-1/ab096855ad5bb8a136f492bbc4aa3beb.jpg', '<p>Cuộc truy đuổi phụ nữ tàn bạo và chết chóc của một kẻ săn mồi hung ác khiến lực lượng cảnh sát phải chật vật truy lùng hắn, trong khi cả tiểu bang quay cuồng trong kinh hoàng.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324268);
