INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nguyen-chi-chu', 'Tinh Nguyên Chi Chủ', 'Master Of The Star Spring', 'https://phimimg.com/upload/vod/20240520-1/985fe3849a060b3f4ab9745de4b4fe9b.jpg', 'https://phimimg.com/upload/vod/20240520-1/fc7174078455b90b792c03809ceb5a8f.jpg', '<p>Thiếu niên vô dụng Tô Cửu bị thần thạch Tinh Nguyên trên trời rơi xuống đập trúng, từ một học sinh bình thường không có bất cứ tu luyện nào, lại trở thành Chủ Tinh Nguyên tân nhiệm. Hai siêu đại mỹ nữ của Vạn Giới là U Diệc Hàn và Thẩm Mộng Tuyết cũng vì tìm kiếm Tinh Nguyên mà tới. Hai người mượn danh nghĩa trốn tránh kẻ thù mà ép buộc ở nhờ, đồng thời vì thu hút Tô Cửu gia nhập tông môn mình mà tạm thời đạt thành giao kèo, cùng dạy dỗ Tô Cửu tu luyện. Ai ngờ, tu vi của Tô Cửu sở hữu Tinh Nguyên tiến bộ nhanh chóng, vượt xa tưởng tượng của hai cô gái.</p>', 'Hoàn Tất (48/48)', 48, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
