INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cyberpunk-edgerunners', 'Cyberpunk: Edgerunners', 'Cyberpunk: Edgerunners', 'https://phimimg.com/upload/vod/20240520-1/3ec4f6aefbe9f49fea0503e69ebb411c.jpg', 'https://phimimg.com/upload/vod/20240520-1/ec9e66f3c794625936dd65acb4a06e61.jpg', '<p>Giữa cảnh loạn lạc đầy sự thối nát và siêu thiết bị điều khiển, tên nhóc đường phố tài ba mà liều lĩnh cố gắng trở thành edgerunner, lính đánh thuê ngoài vòng pháp luật.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 12, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kenn","avatar":""},{"name":"Yuki Aoi","avatar":""},{"name":"Touchi Hiroki","avatar":""},{"name":"Michiko Kaiden","avatar":""},{"name":"Takako Honda","avatar":""},{"name":"Takagi Wataru","avatar":""},{"name":"Kurosawa Tomoyo","avatar":""},{"name":"Inoue Kazuhiko","avatar":""},{"name":"Hino Yurika","avatar":""},{"name":"Tsuda Kenjiro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324268);
