INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-da-hanh-gia', 'Ám Dạ Hành Giả', 'Day Breaker', 'https://phimimg.com/upload/vod/20240520-1/31a3565f0a27da30188822d4dcb611c7.jpg', 'https://phimimg.com/upload/vod/20240520-1/81721f04c48b636aed92b4a4eab58e24.jpg', '<p>Ám Dạ Hành Giả (Day Breaker 2022) là bộ phim xoay quanh câu chuyện của nam chính Lạc Tường (Lý Dịch Phong thủ vai) trong một lần làm nhiệm vụ thuộc chiến dịch bí mật bị mọi người hiểu lầm là đã qua đời. 5 năm sau, Lạc Tường quay trở lại, anh thay đổi thân phận và bắt đầu gia nhập vào tổ chức buôn ma túy nhằm truy tìm ông trùm đứng đằng sau băng đảng này. Bộ phim còn có sự tham gia của Tống Dật sẽ thủ vai Tô Thanh Trúc – một chủ quán trà có khí chất ngổ ngáo, cùng sự tham gia của diễn viên nổi tiếng Phùng Đức Luân.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Yi Feng","avatar":""},{"name":"Tống Dật","avatar":""},{"name":"Phùng Đức Luân","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
