INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-tai-di-gioi-cua-hien-gia-tai-sinh-toi-nhan-duoc-chuc-nghiep-thu-hai-va-da-tro-thanh-nguoi-manh-nhat-the-gioi', 'Cuộc Sống Tại Dị Giới Của Hiền Giả Tái Sinh - Tôi Nhận Được Chức Nghiệp Thứ Hai, Và Đã Trở Thành Người Mạnh Nhất Thế Giới', 'Tensei Kenja No Isekai Life: Dai-2 No Shokugyou Wo Ete Sekai Saikyou Ni Narimashita My Isekai Life: I Gained A Second Character Class And Became The Strongest Sage In The World', 'https://phimimg.com/upload/vod/20240520-1/e39e2a225222629a5a58ebee9e6cb3bf.jpg', 'https://phimimg.com/upload/vod/20240520-1/a71af037e67b548ebcae4cc9f373f73f.jpg', '<p>Sano Yuuji là nhân viên của một công ty đen, được triệu hồi đến thế giới khác trong khi làm việc tại nhà. Anh được ban nghề nghiệp luyện thú sư, nhưng đó lại được xem là nghề khó trở thành nhà mạo hiểm. Tuy nhiên, nhờ vào các slime anh đã tình cờ gặp gỡ, anh đã đạt được sức mạnh ma pháp và chức nghiệp thứ hai, hiền giả. Yuuji đã nhận được sức mạnh áp đảo nhưng bản thân mình lại không nhận ra được sức mạnh đó? Không nhận ra được bản thân đã có năng lực mạnh nhất thế giới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
