INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-song-tai-di-gioi-cua-hien-gia-tai-sinh-toi-nhan-duoc-chuc-nghiep-thu-hai-va-da-tro-thanh-nguoi-manh-nhat-the-gioi', 'Cuộc Sống Tại Dị Giới Của Hiền Giả Tái Sinh - Tôi Nhận Được Chức Nghiệp Thứ Hai, Và Đã Trở Thành Người Mạnh Nhất Thế Giới', 'Tensei Kenja No Isekai Life: Dai-2 No Shokugyou Wo Ete Sekai Saikyou Ni Narimashita My Isekai Life: I Gained A Second Character Class And Became The Strongest Sage In The World', 'cuộc sống tại dị giới của hiền giả tái sinh - tôi nhận được chức nghiệp thứ hai, và đã trở thành người mạnh nhất thế giới tensei kenja no isekai life: dai-2 no shokugyou wo ete sekai saikyou ni narimashita my isekai life: i gained a second character class and became the strongest sage in the world  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-anh-trang', 'Hiệp Sĩ Ánh Trăng', 'Moon Knight', 'https://phimimg.com/upload/vod/20240520-1/c104b0c88abfc9d31b09e4466d509f72.jpg', 'https://phimimg.com/upload/vod/20240520-1/5c5a721c16825622615a921f0aacf3e1.jpg', '<p>Hiệp Sĩ Ánh Trăng kể về Marc Spector - người mắc chứng rối loạn đa nhân cách, anh bị cuốn vào một cuộc chiến chết chóc của các vị thần với nhiều nhân cách của bản thân.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Oscar Isaac","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Gaspard Ulliel","avatar":""},{"name":"May Calamawy","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Fernanda Andrade","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324268);
