INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hiep-si-anh-trang', 'Hiệp Sĩ Ánh Trăng', 'Moon Knight', 'hiệp sĩ ánh trăng moon knight oscar isaac ethan hawke gaspard ulliel may calamawy f. murray abraham fernanda andrade ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-thu-than-quen', 'Đối Thủ Thân Quen', 'Nice To Meet You Again', 'https://phimimg.com/upload/vod/20240520-1/515f2c157da9e2c8719a20f4282778dc.jpg', 'https://phimimg.com/upload/vod/20240520-1/622c20f6d19f33de24dc343667a725ea.jpg', '<p>Cuộc sống hiện đại xô bồ và bon chen, cuốn theo đó là sự hối hả của con người trong dòng đời tất bật đôi khi khiến bạn chệch nhịp. Và bạn có thể chọn cuốn theo dòng đời thăng trầm hoặc chỉ cam chịu. Cuộc sống nó giống như là tấm đề thi mở, vốn không có đáp án tiêu chuẩn, chỉ có thể bù trừ cho nhau nhưng không cho phép bất kỳ ai được gian lận. Nhìn lại tình cảm giữa Lâm Thiệu Đào và Giản Ngải, từ mối tình sét đánh thời đại học đến khi vượt qua lời nguyền chia tay khi tốt nghiệp, trải qua nhiều thăng trầm để bước vào lễ đường tiến tới hôn nhân, một hành trình luôn khiến người ta khác ngưỡng mộ. Vì vậy, Lâm Thiệu Đào không thể ngờ được rằng, lúc bản thân khởi xướng cuộc cải cách trong ngành lúc đã trung niên thì cũng là lúc gia đình mình bước ra khỏi vùng an toàn vốn có. Về lý do ly hôn, Giản Ngải chưa từng giải thích với ai. Ban đầu cô muốn rời Bắc Kinh đến Đại Lý, nhưng vì kinh nghiệm làm việc trước đây nên được Lưu Ánh Hà bổ nhiệm gấp vào VG Trung Quốc để giúp cô giải quyết mối nguy. Điều trùng hợp là chồng cũ của cô, Lâm Thiệu Đào đã đánh bại VG, trở thành Tổng Giám Đốc điều hành. Những người thân, bạn bè không muốn hai người ly hôn trong nhiều cơ duyên đã dùng đủ mọi cách để cả hai quay lại với nhau. Lâm Thiệu Đào muốn vừa phải loại bỏ những người có ý đồ xấu ở môi trường làm việc, cùng lúc còn phải đối phó với sự kết hợp của Giản Ngải và Lưu Ánh Hà, chưa kể những rắc rối bên trong và bên ngoài của đám bạn xấu gây ra. Cuối cùng liệu anh có thể giành lại trái tim người đẹp hay hai người sẽ đường ai nấy đi?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jin Dong","avatar":""},{"name":"Li Xiaoran","avatar":""},{"name":"YangYue","avatar":""},{"name":"YIYAD Zhang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
