INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-tac-cua-quy-co', 'Quy Tắc Của Quý Cô', 'Lady Of Law', 'https://phimimg.com/upload/vod/20240520-1/4446991639bea8cdc0a8159551bb30e8.jpg', 'https://phimimg.com/upload/vod/20240520-1/4de3a585753d818639343fa0ee8448ed.jpg', '<p>Nội dung chủ yếu của phim là về các vụ án, vượt mọi chông gai hướng đến chân tướng, bảo vệ sự cân bằng của tình lý và pháp lý, bảo vệ công bằng và chính nghĩa, luật chính ôn tình thể hiện rõ nhân tính quang minh.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Giang Sơ Ảnh","avatar":""},{"name":"Lưu Mẫn Đào","avatar":""},{"name":"Bành Dục Sướng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
