INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-co-an-toan', 'Bạn Có An Toàn?', 'Are You Safe', 'https://phimimg.com/upload/vod/20240520-1/6330c8d904dc7a4745b39f8f56958b3f.jpg', 'https://phimimg.com/upload/vod/20240520-1/f9afb1f5f352ac9f002d7784a5853ba7.jpg', '<p>Tần Hoài, Châu Du, Trần Mặc, tính cách khác biệt, nhưng đều chung ý định “công nghệ hóa mọi điều tốt đẹp” khi tham gia thế giới mạng. Họ đã cùng nhau lật tẩy một số nhóm tội phạm mạng, những kẻ lợi dụng lỗ hổng trên không gian ảo để tấn công người dùng.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đàn Kiện Thứ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324268);
