INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-gia-gan', 'Lão Già Gân', 'The Old Man', 'https://phimimg.com/upload/vod/20240520-1/f3877c3136d66a40f04ef1997b7e551f.jpg', 'https://phimimg.com/upload/vod/20240520-1/dc4223d7126f84a9cc5c0af8c05f2f74.jpg', '<p>Dan Chase là một cựu đặc nhiệm CIA, người đã sống ngoài lưới điện trong một thời gian khá dài. Khi một sát thủ đến và cố gắng đưa Chase ra ngoài, đặc nhiệm cũ phải bỏ chạy. Trong khi chạy trốn, Chase thuê một căn phòng từ Zoe McDonald, người mà anh ta buộc phải hợp tác với nhau khi anh ta đấu tranh cho sự thật. Khi Chase trốn thoát, Trợ lý Giám đốc FBI về Phản gián, Harold Harper, được yêu cầu truy lùng anh ta vì quá khứ phức tạp của anh ta với kẻ đào tẩu bất hảo. Làm việc cùng với Harper là người bảo trợ của anh, Đặc vụ Angela Adams, và Đặc vụ Raymond Waters, cũng như Julian Carson, một nhà thầu hoạt động đặc biệt được đào tạo chuyên sâu được cử đi theo đuổi lão già gân Chase</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"EJ Bonilla","avatar":""},{"name":"Bill Heck","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324268);
