INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nong-noi-cong-so', 'Tình Nồng Nơi Công Sở', 'Buff In Love', 'https://phimimg.com/upload/vod/20240520-1/2a88a260514b9910042e0ecec1eb3483.jpg', 'https://phimimg.com/upload/vod/20240520-1/2e02a668d11d0c87d8b3db74235714e4.jpg', '<p>Dương Y Phàm và bạn trai cũ Hoàng Vũ Thần phải cùng tranh nhau một cơ hội được chuyển làm nhân viên chính thức, hai người chung đụng nhau từ ngày còn ở sân trường cho đến nơi công sở, đồng thời trong quá trình tranh đấu lần hai người lại phát hiện một mặt đáng yêu chân thành của nhau, trải qua một phen chia tay rồi tái hợp hai người dần trưởng thành, trở thành những thành viên ưu tú của công sở.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 4, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Quân Hạo","avatar":""},{"name":"Thiệu Vũ Thất","avatar":""},{"name":"Vu Tiểu Uyển","avatar":""},{"name":"Lưu Mộc Tử","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
