INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ung-cuu-dau-tien', 'Những Người Ứng Cứu Đầu Tiên', 'The First Responders', 'https://phimimg.com/upload/vod/20240520-1/0ea4595d145371bc851e28b7927a60d3.jpg', 'https://phimimg.com/upload/vod/20240520-1/97a321febc24460a54458b7f60c74a46.jpg', '<p>Thực hiện theo các hoạt động chung của lực lượng cảnh sát và sở cứu hỏa, những người sẽ cùng nhau kể một câu chuyện ly kỳ.Thám tử hung hãn Jin Ho Gae chỉ toàn bắt những kẻ thấp hèn. Anh ta giải quyết các vụ án bằng khả năng tuyệt vời của mình trong việc nắm bắt hiện trường vụ án, đọc được suy nghĩ của tội phạm và có ý chí chiến thắng cao. Trong khi anh chàng lính cứu hỏa Bong Do Jin bề ngoài có vẻ lạnh lùng nhưng lại tốt với những người xung quanh và chăm sóc nạn nhân rất chu đáo. Anh lao đến các địa điểm khai hỏa mà không một chút do dự. Tham gia cùng bộ đôi là Song Seol, một nhân viên y tế đồng cảm, người chữa lành những trái tim tan vỡ trong khi điều trị vết thương.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Rae Won","avatar":""},{"name":"Son Ho Jun","avatar":""},{"name":"Gong Seung Yeon","avatar":""},{"name":"Jung Jin Woo","avatar":""},{"name":"Lee Jung Hun","avatar":""},{"name":"Ji Woo","avatar":""},{"name":"Jung Sang Hoon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324268);
