INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cua-bep-truong-pizza', 'Bàn Của Bếp Trưởng: Pizza', 'Chef''s Table: Pizza', 'https://phimimg.com/upload/vod/20240520-1/10bb869eec6c43d9b6e4d8feac9a5e7d.jpg', 'https://phimimg.com/upload/vod/20240520-1/b6488e4c908d0944dbf38afdd93bb753.jpg', '<p>Khám phá những chiếc bánh pizza ngon nhất từ khắp nơi trên thế giới do những đầu bếp nổi tiếng chế biến. Họ đưa niềm đam mê, sự sáng tạo và chăm chỉ vào từng miếng bánh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324268);
