INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ms-marvel', 'Ms. Marvel', 'Ms. Marvel', 'https://phimimg.com/upload/vod/20240520-1/1ead92c8c0144f57c6b28b7a77f65619.jpg', 'https://phimimg.com/upload/vod/20240520-1/c36becf878e2b25b53448e5b6087592b.jpg', '<p>Ms. Marvel sẽ không chỉ giới thiệu một anh hùng mới vào Vũ trụ Điện ảnh Marvel mà còn tạo tiền đề cho sự ra mắt của người mới Iman Vellani trong nhượng quyền thương mại. Bộ phim sắp tới của Disney là vai diễn chính đầu tiên của nữ diễn viên, nhưng Vellani dường như không bị ảnh hưởng bởi thực tế đó. Thay vào đó, nữ diễn viên trẻ đã nói về sự phấn khích của cô ấy về hợp đồng diễn xuất của mình, với việc cô ấy chỉ ra tình yêu của cô ấy đối với toàn bộ loạt phim Marvel.Một phần tốt trong cách tiếp thị của &nbsp;Ms. Marvel chủ yếu tập trung vào tình yêu của Vellani đối với vũ trụ Marvel, với đoạn teaser đầu tiên &nbsp;thực sự cho thấy phản ứng của nữ diễn viên khi được chọn &nbsp;cho vai diễn này. Người sáng tạo của Kamala Khan, Sana Amanat cũng &nbsp;chỉ ra rằng năng lượng ham chơi và nhiệt huyết tuổi teen của Vellani là lý tưởng cho một nhân vật như Kamala Khan, người &nbsp;không phải là Avenger truyền thống của bạn.Ngoài việc là một người hâm mộ Marvel thẳng thắn, Vellani còn là một người ủng hộ Iron Man tự xưng. Giờ đây, nữ diễn viên đã mở lòng về tình yêu của cô dành cho Armored Avenger được chuyển thành vai trò MCU của cô như thế nào.&nbsp;</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 4, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iman Vellani","avatar":""},{"name":"Alysia Reiner","avatar":""},{"name":"Matt Lintz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324268);
