INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-groot', 'Em Là Groot', 'I Am Groot', 'https://phimimg.com/upload/vod/20240520-1/6427dc6bec383c5cba5cc6a5c0af76a4.jpg', 'https://phimimg.com/upload/vod/20240520-1/a3167cb4520395e0ebae52c846bdf839.jpg', '<p>Không có người bảo vệ thiên hà khỏi đứa trẻ tinh nghịch này! Hãy sẵn sàng khi Baby Groot bước lên sân khấu trung tâm trong bộ sưu tập quần đùi của riêng mình, khám phá những ngày vinh quang khi lớn lên và gặp rắc rối giữa các ngôi sao.</p>', 'Hoàn Tất (5/5)', 5, 'hoathinh', 'completed', 4, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vin Diesel","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
