INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-reload-zeroin', 'Tây Du Ký RELOAD -ZEROIN-', 'Saiyuuki RELOAD -ZEROIN-', 'https://phimimg.com/upload/vod/20240520-1/0d8454bd085317554955301fdaea3431.jpg', 'https://phimimg.com/upload/vod/20240520-1/708e118eb2427089856cb5f1e70ba908.jpg', '<p>Tại Chốn Đào Nguyên vừa hỗn loạn nhưng cũng thật yên bình này. Nơi con người và yêu quái, khoa học và phép thuật cùng nhau tồn tại. Thế nhưng, do ảnh hưởng tiêu cực từ thí nghiệm hồi sinh Ngưu Ma Vương, bọn yêu quái đột nhiên trở nên mất kiểm soát và phá hủy sự cân bẳng. Ngài Huyền Trang Tam Tạng, được sự phó thác của Quan Thế Âm Bồ Tất từ Thiên giới đã cùng với Tôn Ngộ Không, Sa Ngộ Tịnh, Trư Bát giới lên đường đến Tây Vực Thiên Trúc để ngăn chặn thí nghiệm hồi sinh Ngưu Ma Vương. Trên đường đi, nhóm Tam Tạng chạm trán Hazel Grouse, kẻ có khả năng hồi sinh người chết và người tùy tùng của hắn, Gat. Mục đích của Hazel khi đi từ Tây Vực đến đây là gì...</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 4, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
