INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuat-nha-nuoc-thieu-hut-troi-day-lai-cua-hoang-tu-thien-tai', 'Thuật Nhà Nước Thiếu Hụt Trỗi Dậy Lại Của Hoàng Tử Thiên Tài', 'The Genius Prince''s Guide To Raising A Nation Out Of Debt', 'https://phimimg.com/upload/vod/20240520-1/499c494628b1877b92d3968a83e4bc54.jpg', 'https://phimimg.com/upload/vod/20240520-1/30861fd90da1ede2642bd3367df3c551.jpg', '<p>Wein là hoàng tử trẻ của một nhà nước yếu ớt thiếu tài nguyên và nhân tài. Chàng văn võ kiêm toàn, được các thần dân tin cậy, lại có một ước mơ không ai biết: “Thật muốn bán nước và trốn chạy đó!” Đúng vậy, bộ mặt thật của hoàng tử là kẻ bán nước chỉ muốn sống một cuộc sống ở ẩn! Tuy nhiên, chàng xoa dịu nước mạnh lại bất ngờ độc chiếm lợi ích và luôn luôn thắng lợi hoàn toàn khi đối chọi nhau với nước yếu. Mặc dù tiếng tăm lừng lẫy, nhưng chàng cũng ngày càng lệch hướng mục tiêu bán nước và khí thế thần dân cũng ngày một vang dậy mà khiến chàng cưỡi trên lưng cọp! Câu chuyện vận hành nhà nước yếu ớt đầy nguy hiểm với nhân vật chính là hoàng tử thiên tài sắp mở màn!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
