INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('byron-bay-thi-tran-nguoi-noi-tieng', 'Byron Bay: Thị Trấn Người Nổi Tiếng', 'Byron Baes', 'https://phimimg.com/upload/vod/20240520-1/079895f3615cba25899608e340051c52.jpg', 'https://phimimg.com/upload/vod/20240520-1/5a43b9775bcf6a9ff5cdb21bb36b4740.jpg', '<p>Người nổi tiếng ở Úc tràn đến Vịnh Byron vì ở đây ấm áp, bãi biển đẹp, đậm chất thú vị, sáng tạo. Hãy dõi theo những người bạn này khi họ dàn xếp cuộc sống và tình yêu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Úc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
