INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-ngo', 'Nghi Ngờ', 'Suspicion', 'https://phimimg.com/upload/vod/20240520-1/037d32a073a96478d111de31a8b5b562.jpg', 'https://phimimg.com/upload/vod/20240520-1/2b9d65c1c6be90cfe6f9080223d651b3.jpg', '<p>Câu chuyện kể về 5 người gốc Anh đang sinh sống bình thường, thì bỗng chốc đảo lộn sau khi trở thành kẻ tình nghi bắt cóc cậu con trai yêu quý của một ông trùm giới truyền thông của Mỹ. Vì thế giờ đây, cả 5 người cùng nhau hợp sức chạy đua với thời gian để có thể chứng minh bản thân vô tội. Nhưng mọi chuyện sẽ ra sao? Liệu họ có thể chứng minh được, liệu mọi người có thể tin lời bọn họ?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Henstridge","avatar":""},{"name":"Elyes Gabel","avatar":""},{"name":"Kunal Nayyar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324268);
