INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-tren-yen-ngua', 'Thanh Xuân Trên Yên Ngựa', 'Gunjou No Fanfare', 'https://phimimg.com/upload/vod/20240520-1/249047c4cca313e084ea0936b8f62255.jpg', 'https://phimimg.com/upload/vod/20240614-1/1a682b3ac7c35a6f4861954d7c00cd5c.jpg', '<p>Câu chuyện kể về ba cậu học sinh 15 tuổi, nhập học vào học viện đua ngựa nổi tiếng với ước mơ trở thành nài ngựa. Tuy nhiên, học viện này có tỉ lệ đầu vào khó gấp 10 ~ 20 lần so với các trường học thông thường. Những ai có nguyện vọng thi vào, phải vượt qua ba bài kiểm tra về học vấn, thể chất và năng lực phù hợp. Trước đây, Arimura Yuu từng là thành viên của nhóm nhạc Idol nổi tiếng và rất được lòng fan, rồi cậu bắt đầu chạy theo tiếng gọi của đam mê và mê mẩn việc đua ngựa. Kazanami Shun sinh ra và lớn lên trên đảo, nên cậu ao ước được cưỡi ngựa. Cuối cùng là Grace Amane sinh ra lại Vương quốc Anh, từ chối đi theo con đường mà bố mẹ vạch sẵn để theo đuổi ước mơ của bản thân.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 17, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324268);
