INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-sat-nhan-lang-man', 'Kẻ Sát Nhân Lãng Mạn', 'Romantic Killer', 'https://phimimg.com/upload/vod/20240520-1/78d02616470b89fb37d8333847c9ad6d.jpg', 'https://phimimg.com/upload/vod/20240520-1/4567a455ad0956a5eacb7823e1fb75c2.jpg', '<p>Có cuộc sống độc thân tuyệt vời, Anzu chẳng màng đến tình yêu. Thế rồi một phù thủy mai mối tí hon bỗng biến cuộc sống của cô thành bộ phim hài lãng mạn khuôn sáo.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takahashi Rie","avatar":""},{"name":"Komatsu Mikako","avatar":""},{"name":"Umehara Yuichiro","avatar":""},{"name":"Kajiwara Gakuto","avatar":""},{"name":"Hanae Natsuki","avatar":""},{"name":"Tsuda Kenjiro","avatar":""},{"name":"Iwami Manaka","avatar":""},{"name":"Shimono Hiro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
