INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lai-la-mot-ngay-lam-viec-cham-chi-2', 'Lại Là Một Ngày Làm Việc Chăm Chỉ 2', 'Another Hard Day 2', 'https://phimimg.com/upload/vod/20240520-1/65efe2b3dd5c3549d7a79156fbffd1f5.jpg', 'https://phimimg.com/upload/vod/20240520-1/c17f02dd9a50671959f4ecd635ea80f9.jpg', '<p>Tiếp tục cốt truyện của phần đầu tiên, phim kể rằng Xin Fan, người quyết tâm nghỉ hưu sớm ở tuổi 35, đã bị thực tế đánh bại ngay khi vừa bước đầu tiên. những người trẻ tiếp tục viết về cuộc sống của họ và tiếp tục sân khấu hóa những câu chuyện về tình yêu, sự ấm áp, đấu tranh và trưởng thành.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ding Jingyi","avatar":""},{"name":"Zhang Xinyi","avatar":""},{"name":"Chu Junchen","avatar":""},{"name":"Zha Yichen","avatar":""},{"name":"Bai Jie","avatar":""},{"name":"Shi Yaxin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
