INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lai-la-mot-ngay-lam-viec-cham-chi-2', 'Lại Là Một Ngày Làm Việc Chăm Chỉ 2', 'Another Hard Day 2', 'lại là một ngày làm việc chăm chỉ 2 another hard day 2 ding jingyi zhang xinyi chu junchen zha yichen bai jie shi yaxin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-dau-gai', 'Dây Dầu Gai', 'Between Us', 'https://phimimg.com/upload/vod/20240520-1/f0f3314d22894bd0d5d273655beadc35.jpg', 'https://phimimg.com/upload/vod/20240520-1/24107932dfbabe9f4cb1d41927d17593.jpg', '<p>Bộ phim xoay quanh cặp đôi Win và Team. Team luôn gặp vấn đề về giấc ngủ trước giải đấu bơi lội khiến cậu ấy không thể có được thành tích tốt để tham gia đội tuyển bơi lội quốc gia. Win nhận ra vấn đề này và quyết định bước thêm một bước để giúp đỡ. Win biết rằng Team chỉ muốn ai đó ở bên cạnh nên cậu ấy cho phép Team ngủ trong phòng của mình. Nhờ điều đó mà Team cảm thấy thoải mái hơn trước khi thi đấu và vấn đề về giấc ngủ của cậu ấy không còn nghiêm trọng nữa. Chính vào lúc này, Win bắt đầu có cảm tình với người đàn em của mình, Team. Nhưng vì bối cảnh gia đình, Win là người chỉ biết cho đi tình yêu thương mà không bao giờ được nhận lại, chỉ biết đối xử bình đẳng với mọi người nên càng khó tiếp cận Team hơn. Chính điều đó làm cho Team biết rằng chính cậu ấy là người đặc biệt đối với Win.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Boun Noppanut Guntachai","avatar":""},{"name":"Prem Warut Chawalitrujiwong","avatar":""},{"name":"Prem","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
