INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-ho-diep', 'Mộng Hồ Điệp', 'To Sir, With Love', 'https://phimimg.com/upload/vod/20240520-1/af49e9fa569ac2fdd0559fbfb42c87e1.jpg', 'https://phimimg.com/upload/vod/20240520-1/ccd46348062c90e98f6fa5e0786baa9a.jpg', '<p>Để kế thừa cơ nghiệp giàu có của gia đình, Tian buộc phải dùng mọi cách để che giấu giới tính thật của mình. Cuộc chiến giành quyền thừa kế đang đến hồi gay cấn và bí mật có nguy cơ bị lật tẩy, liệu “quý ông” Tian sẽ làm thế nào?To Sir, With Love - Mộng Hồ Điệp, phim thai lan mong ho diep, mong ho diep thuyet minh hd, mong ho diep vietsub, mong ho diep tap 1, xem phim mong ho diep, mong ho diep</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Film Thanapat Kawila","avatar":""},{"name":"Tong Kitsakorn Kanoktorn","avatar":""},{"name":"Camilla Kittivat Kirn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
