INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-hoan-hao', 'Người Mẹ Hoàn Hảo', 'The Perfect Mother', 'https://phimimg.com/upload/vod/20240520-1/f6148439e6bac602f752208f4cc33691.jpg', 'https://phimimg.com/upload/vod/20240520-1/39dd77a4a6b6ff1eb79a4c8577fd750a.jpg', '<p>Tin rằng con gái mình vô tội trong một vụ án mạng, người mẹ hết lòng vì con sớm phát hiện ra nhiều sự thật đáng ngại khi ranh giới giữa nạn nhân và kẻ thủ ác mờ đi.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Julie Gayet","avatar":""},{"name":"Tomer Sisley","avatar":""},{"name":"Eden Ducourant","avatar":""},{"name":"Andreas Pietschmann","avatar":""},{"name":"Cyril Gueï","avatar":""},{"name":"Frédérique Tirmont","avatar":""},{"name":"Sylvain Dieuaide","avatar":""},{"name":"Maxim Driesen","avatar":""},{"name":"Emilia Nöth","avatar":""},{"name":"Halima Ilter","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
