INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-hoan-hao-sakamoto', 'Thánh Hoàn Hảo Sakamoto', 'Haven''t You Heard? I''m Sakamoto', 'https://phimimg.com/upload/vod/20240520-1/8ead99e415d298aa1a951e2019f70ca1.jpg', 'https://phimimg.com/upload/vod/20240520-1/76f9bea031d70ddacc8176b6d25211d0.jpg', '<p>Phim hoạt hình kể về câu chuyện của nam sinh toàn năng Sakamoto học ở Trường Trung học phổ thông Học Văn thuộc tỉnh. Chàng thỉnh thoảng hành động quá mức bình thường mà khiến nữ sinh khâm phục và khiến nam sinh ghen tị chàng không thể không bái phục.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 4, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324268);
