INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-hoan-hao-sakamoto', 'Thánh Hoàn Hảo Sakamoto', 'Haven''t You Heard? I''m Sakamoto', 'thánh hoàn hảo sakamoto haven''t you heard? i''m sakamoto  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-gia-manh-nhat-voi-dau-an-yeu-nhat', 'Hiền Giả Mạnh Nhất Với Dấu Ấn Yếu Nhất', 'The Strongest Sage Of Disqualified Crest, Shikkakumon No Saikyokenja, Shikkakumon No Saikyo Kenja ~Sekai Saikyo No Kenja Ga Sara Ni Tsuyoku Naru Tame Ni Tensei Shimashita~', 'https://phimimg.com/upload/vod/20240520-1/1b0b70fb3334c2d20ab365c2c1694589.jpg', 'https://phimimg.com/upload/vod/20240520-1/cabff7995fa79e0874d6dd1719bb10ea.jpg', '<p>Trong thế giới ma thuật, sức mạnh và tương lai của một pháp sư được xác định trước khi sinh ra thông qua cái gọi là Dấu hiệu —của bốn biểu tượng phân loại năng khiếu ma thuật của con người. Than thở về sự thật rằng dấu ấn của anh ta bị coi là không phù hợp cho chiến đấu và chỉ hữu ích cho việc gia tăng ma thuật, một nhà hiền triết vô cùng tài giỏi đã quyết định tái sinh hàng nghìn năm trong tương lai. Tái sinh trong vai Mathias Hildesheimr - một cậu bé sáu tuổi và là con trai thứ ba của gia đình một công tước - cậu đạt được dấu hiệu cận chiến mà cậu hằng mong ước. Thật không may, người ta cũng phát hiện ra rằng kiến thức của nhân loại về ma thuật và kiếm thuật đã giảm sút nghiêm trọng trong thời đại này; chỉ những thiết bị ma thuật kém chất lượng mới có thể được tìm thấy lẻ tẻ, trong khi ngay cả những phép thuật cơ bản nhất cũng đã bị lãng quên. Để tăng thêm sự xúc phạm cho chấn thương, dấu ấn hiện tại của anh ấy, từng được ca ngợi là mạnh nhất, giờ bị coi là tồi tệ nhất. Khi Mathias 12 tuổi, kiếm thuật vô song của anh đã đưa anh vào Học viện Hoàng gia thứ hai. Phá tan những định kiến, anh ta nhanh chóng tạo nên những gợn sóng trong học viện và hơn thế nữa. Tuy nhiên, nhà hiền triết cũ đã phát hiện ra những dấu hiệu của các thế lực đen tối đang hoạt động trong bóng tối, và với việc nhân loại yếu hơn bao giờ hết, Mathias phải ngăn cản kế hoạch xấu xa của họ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324268);
