INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-cau-may', 'Cô Nàng Cầu May', 'Cô Nàng Cầu May', 'https://phimimg.com/upload/vod/20240520-1/4af1f36c2821841ba58c13bd2ceb0660.jpg', 'https://phimimg.com/upload/vod/20240520-1/c58587c6d1943a4cc265a61b64710ff2.jpg', '<p>Câu chuyện kể về một cô gái mang thân phận của một cô nàng cá koi không may vướng vào mối tình với một anh chàng hotboy của trường. Hai người độc thân có thể đến với nhau từ trong bụng mẹ?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Ý Hàm","avatar":""},{"name":"Khâu Hồng Khải","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
