INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-hau-thu-phap', 'Tối Hậu Thư: Pháp', 'The Ultimatum: France', 'https://phimimg.com/upload/vod/20240520-1/261a894ffdd02c505b31177005b0a57c.jpg', 'https://phimimg.com/upload/vod/20240520-1/f16ae57e5899595554f5436a2882051d.jpg', '<p>Sáu cặp đôi đang ở trên đỉnh cao của tình yêu trọn đời thì đứng trước tối hậu thư: Đính hôn hoặc chia tay. Trước khi ra quyết định, họ sẽ tráo đổi nửa kia trong ba tuần.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
