INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-gia-xa-hoi-den-yeu-toi', 'Thiếu Gia Xã Hội Đen Yêu Tôi', 'KinnPorsche The Series', 'https://phimimg.com/upload/vod/20240520-1/d891687c9c2ee222906a53c51ad65997.jpg', 'https://phimimg.com/upload/vod/20240520-1/c2041c4e52a21d7ca39a944cbb511fce.jpg', '<p>Thiếu Gia Xã Hội Đen Yêu Tôi (KinnPorsche The Series) xoay quanh câu chuyện của hai chị em Jennaree và Lalisa, họ muốn trở thành cảnh sát để trả thù cho cha. Họ vào văn phòng của Công tố viên Non, người đã xử lí vụ án Sakda, tên mafia giết cha họ. Cả hai đều hài lòng với vụ án này. Nhưng cuối cùng, Jennaree đã giết chết Sakda do nhầm lẫn. Thuộc hạ của Sakda sau đó đã trả thù bằng cách giết mẹ của họ. Điều này khiến Lalisa rất giận Jennaree, tạo nên rạn nứt không thể hàn gắn giữa hai chị em. Công tố viên Non cố gắng giúp Jennaree, nhưng thay vào đó lại tạo ra mối tình tay ba cho ba người họ. Lalisa trở nên ghen tị với Jennaree khi cô phát hiện ra những gì Công tố viên Non đã làm cho Jennaree. Công tố viên Non đợi Jennaree quay lại bên mình, nhưng Jennaree lại luôn tránh xa anh, khiến mặt tốt xấu của hai chị em đối lập nhau. Xung đột khó tránh khỏi này có khả năng giúp cả hai yêu thương nhau lần nữa.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 4, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mile Pakphoom Romsaithong","avatar":""},{"name":"Apo Nattawin Wattanagitiphat","avatar":""},{"name":"Bible Wichapas Sumettikul","avatar":""},{"name":"Build Jakapan Puttha","avatar":""},{"name":"Jeff Worakamol Satur","avatar":""},{"name":"Barcode Trinnasit Isarapongporn","avatar":""},{"name":"Nankhun Pakapatpornpob","avatar":""},{"name":"Bas Chatshol Ponpiboon","avatar":""},{"name":"Tong Thanayut Thakoonauttaya","avatar":""},{"name":"Nod Nutthasid Pa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324268);
