INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pepsi-chien-dau-co-cua-toi-dau', 'Pepsi, Chiến đấu Cơ Của Tôi đâu?', 'Pepsi, Where''s My Jet?', 'https://phimimg.com/upload/vod/20240520-1/136c9dd5347ada59beb500ccf87998d3.jpg', 'https://phimimg.com/upload/vod/20240520-1/5aab24b1aeb33dda3af0c93b63dc5b95.jpg', '<p>Nỗ lực thắng phần thưởng là chiến đấu cơ trong chương trình rút thăm trúng thưởng của Pepsi, một thanh niên 20 tuổi khơi mào cuộc chiến pháp lý trứng chọi đá vô cùng nổi tiếng.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324268);
