INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-ky-cung-jonathan-van-ness', 'Hiếu Kỳ Cùng Jonathan Van Ness', 'Getting Curious With Jonathan Van Ness', 'https://phimimg.com/upload/vod/20240520-1/a71e6f5596f3fee57973af3150865bf7.jpg', 'https://phimimg.com/upload/vod/20240520-1/813e637a5c746ce916903b71be14c53e.jpg', '<p>Jonathan Van Ness để sự tò mò dẫn dắt khi anh chuyển từ đồ ăn vặt sang tóc giả trong chương trình dựa trên podcast này. Có nhiều chuyên gia và khách mời đặc biệt.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonathan Van Ness","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324268);
