INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nho-than-yeu', 'Bạn Nhỏ Thân Yêu', 'Left Right', 'https://phimimg.com/upload/vod/20240520-1/3e3dd1ebb3de4f3a292dca2fd5aec0c5.jpg', 'https://phimimg.com/upload/vod/20240520-1/e51b1d049e2c5f4f4848e4a02f95bf17.jpg', '<p>Câu chuyện kể về câu chuyện của Phương Nhất Nặc xinh đẹp ngây thơ vì tình yêu mà bất chấp tất cả cùng mối tình đầu Tiêu Lộ kết hôn không cần cưới xin. Không ngờ cuộc sống hôn nhân đáng tự hào đó lại xảy mâu thuẫn khi con vừa tròn một tuổi. Phương Nhất Nặc quyết định li hôn và cùng với con gái bắt đầu cuộc sống mới. Hai năm sau đã tiến tới hôn nhân với Tạ Thiên Hoa người yêu thầm cô suốt bao năm.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tần Hạo","avatar":""},{"name":"Ren Su Xi","avatar":""},{"name":"Nhiếp Viễn","avatar":""},{"name":"Shaking","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
