INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-khong-roi-tay-anh-yeu-em', 'Mua Không Rời Tay Anh Yêu Em', 'Miss Buyer', 'https://phimimg.com/upload/vod/20240520-1/7af65b7b5534bbe7bd89fbe9143fcb10.jpg', 'https://phimimg.com/upload/vod/20240520-1/42a7d822eaca2c0d6eadba7450febff1.jpg', '<p>Bộ phim kể về câu chuyện của một người phụ nữ, một người không có chút kinh nghiệm nào trong việc mua hàng thời trang trở thành một người mua hàng siêu đẳng cấp và câu chuyện tình yêu của cô.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tina Tang","avatar":""},{"name":"Mickey","avatar":""},{"name":"Peng Gao Chang","avatar":""},{"name":"Zhang Lei","avatar":""},{"name":"Liao Wang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
