INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-nguoi-khong-yeu-toi', 'Gửi Người Không Yêu Tôi', 'Dear X Who Doesn''t Love Me', 'https://phimimg.com/upload/vod/20240520-1/0cbec9fe22ed84e369f07c89a9f4895d.jpg', 'https://phimimg.com/upload/vod/20240520-1/c97e1b72d9e034a3c7c7bd74ab69ad3b.jpg', '<p>Gửi Người Không Yêu Tôi - Dear X Who Doesnt Love Me kể câu chuyện của những người trẻ ở độ tuổi 20 - những người đang đau đầu bởi ước mơ và tình yêu. Nhân vật chính trong phim là Jung Shi Ho - một sinh viên đại học bị tổn thương và Hee Soo - cô nàng không có lòng tự trọng và không biết yêu bản thân. Sau khi tìm thấy một cuốn sổ bí ẩn có thể khiến tình yêu thành sự thật, Hee Soo đã tận dụng nó để có thể có mối quan hệ với nhiều bạn nam bao gồm cả bạn thân khác giới Shi Ho.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Ji-Hyo","avatar":""},{"name":"Do Young","avatar":""},{"name":"Kwon Ah-Reum","avatar":""},{"name":"Bang Jae-Min","avatar":""},{"name":"Son Hyun-Woo","avatar":""},{"name":"Kim Ji-Hoon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
