INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-nguoi-yeu-quat-tu-cua-toi', 'Xin Chào, Người Yêu Quất Tử Của Tôi', 'A Robot In The Orange Orchard', 'https://phimimg.com/upload/vod/20240520-1/6f56105c7871eff5f7d26389e613a611.jpg', 'https://phimimg.com/upload/vod/20240520-1/8d4bfba7ea72abb591e66d5986bdd83f.jpg', '<p>Lu Kun, chủ tịch của công ty công nghệ emu, mắc một căn bệnh hiếm gặp. Khi chạm vào một người, anh ta sẽ bị phản ứng dị ứng. Tình cờ là Tiến sĩ thiên tài Boyang đã bí mật tạo ra người máy đồng hành thông minh Friday. Phương án cuối cùng, bác sĩ Fu Yang thuê trợ lý cũ của mình là Yang Shanshan để thay thế ông.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tôn Thiên","avatar":""},{"name":"Lương Tĩnh Khang","avatar":""},{"name":"Vương Phóng","avatar":""},{"name":"Chu Vân Huệ","avatar":""},{"name":"Trình Dã Tinh","avatar":""},{"name":"Châu Vũ Hàng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
