INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngheo-hoc-lam-sang', 'Nghèo Học Làm Sang', 'Get On A Flat', 'https://phimimg.com/upload/vod/20240520-1/e589d5796636bf5d18daa2c8ad4cbfca.jpg', 'https://phimimg.com/upload/vod/20240520-1/37c49ce05b3e51ac38e8b8d810db7a6e.jpg', '<p>Tại Hồng Kông, việc sở hữu một căn nhà là vô cùng khó, có người dành cả đời cũng không thể. Năm 2008 xảy ra khủng hoảng tài chính, Xa Chí Minh (do Lâm Mẫn Thông đóng) phải bán căn nhà lớn. Sau 14 năm, dù Minh làm cửa hàng trưởng ở siêu thị, tiết kiệm từng đồng nhưng vẫn chưa mua được nhà, chỉ có thể thuê nhà của ông chủ. Vợ của Minh là Mạc Văn Tuệ (do Giang Mỹ Nghi đóng) cũng luôn mong ước có một căn nhà. Tuệ làm công theo giờ tại nhà giàu có, nên đã cùng gia đình mình liên tục chụp ảnh ở nơi đây rồi đăng lên mạng xã hội khoe khoang.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Che Chin-chin","avatar":""},{"name":"Che Zi-ming","avatar":""},{"name":"Tse Juk-ha","avatar":""},{"name":"Mok Man-wai","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
