INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-noi-gian', 'Kẻ Nội Gián', 'Insider', 'https://phimimg.com/upload/vod/20240520-1/f2351f11c50f6825f669530b3ae95683.jpg', 'https://phimimg.com/upload/vod/20240520-1/2666feea8b50c8c1c2b8aaf39d158daf.jpg', '<p>Kể về câu chuyện của một thực tập sinh tư pháp tên là Kim Yo Han. Sau khi bí mật điều tra, Kim Yo Han trải qua một cuộc khủng hoảng và cuối cùng phải vật lộn để cố gắng có được một lá bài có thể thay đổi số phận của mình khi anh ta đánh bạc trong tù. Kim Yo Han thận trọng và luôn suy nghĩ trước một vài bước đi trước, và anh ấy luôn giữ một bộ mặt poker. Mặc dù anh ấy rơi vào một tình huống nguy hiểm khi bị lôi kéo vào một sự cố bất ngờ trong quá trình điều tra, anh ấy sẽ tiếp tục chiến đấu để tồn tại và cố gắng phát triển với khả năng biến khủng hoảng thành cơ hội.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2022, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Ha Neul","avatar":""},{"name":"Lee Yoo Young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324268);
