INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-co-gai-bi-da-tren-bang', 'Các Cô Gái Bi Đá Trên Băng', 'Curling Girls', 'https://phimimg.com/upload/vod/20240517-1/0099db79a7e07bed66635b3047b450bb.jpg', 'https://phimimg.com/upload/vod/20240517-1/1f2531f75098d10b46ee7c38d31d43a9.jpg', '<p>Khi Xia Tangyuan, một cô gái đang khao khát tìm kiếm một người đàn ông, gặp Zhao Yibing, một huấn luyện viên ma quỷ đang khát khao chiến thắng Dream, Zhao Yibing đã phải giữ cô lại, và tìm thấy Han Xinyan, một cao thủ thiên tài sau khi trải qua vô số mâu thuẫn và xích mích, Xia Tangyuan dần dần phát hiện ra tình yêu thủy chung trong trái tim của những cô gái dường như hoàn toàn khác biệt với thế giới này, và dần dần cảm kích họ. đứng trên bục giảng, tuyên bố sức mạnh của các cô gái với tất cả mọi người.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiang Zhinan","avatar":""},{"name":"Yang Yue","avatar":""},{"name":"Zhou Qianxiao","avatar":""},{"name":"Zhuo Yinam","avatar":""},{"name":"Gao Tian","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
