INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-lai-cau-vong', 'Tìm Lại Cầu Vồng', 'Finding The Rainbow', 'https://phimimg.com/upload/vod/20240517-1/45828a82bc05b347c06a1ac5caef4f20.jpg', 'https://phimimg.com/upload/vod/20240517-1/6e6b2009ec2efe79819f019c52cde630.jpg', '<p>Bộ phim xoay quanh mối tình kéo dài 30 năm của Nont (God Itthipat Thanit) và Fern (Aom Sushar Manaying), trải qua vô vàn biến cố của lịch sử và xã hội. Nont yêu Fern từ khi còn trẻ. Sau đó, vì một vài sự việc mà họ chia xa. Sau nhiều năm, cả hai gặp lại nhau, nhưng lúc này Fern đang là vị hôn phu của doanh nhân Wilson giàu có.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Aom Sushar Manaying","avatar":""},{"name":"God Itthipat Thanit","avatar":""},{"name":"Nichkhun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
