INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-phai-nu-dung-len', 'Khi Phái Nữ Đứng Lên', 'Women Walk The Line', 'https://phimimg.com/upload/vod/20240517-1/9a5f349e14ca5cbd6560cc2f69184982.jpg', 'https://phimimg.com/upload/vod/20240517-1/cb0ccb9dc6ae3b9247c4744143745697.jpg', '<p>Viên Ca và Cốc Kiều là đôi bạn đến từ một thành phố nhỏ, khi tốt nghiệp đại học, một người chọn ở lại Thượng Hải làm việc, một người chọn về quê làm vợ hiền. Ở độ tuổi gần 30, cả hai lần lượt gặp những khó khăn chưa từng có trong cuộc đời. Suốt bao năm Viên Ca chuyên tâm làm lụng mà bỏ bê đời sống tình cảm, đồng thời sức khoẻ cũng xuất hiện vấn đề, cô bắt đầu cố gắng thay đổi bản thân. Cốc Kiều vì tình yêu mà suốt tám năm không ngừng thoả hiệp, cuối cùng thứ cô nhận được lại là tờ giấy thoả thuận ly hôn, vì vậy cô liền quyết tâm bắt đầu gây dựng lại sự nghiệp. Đôi bạn này tuy có tính cách hoàn toàn khác nhau nhưng đều kiên cường, dũng cảm, không sợ vấp ngã. Ở một thành phố đầy cơ hội nhưng cũng dễ lạc lối như Thượng Hải, họ vẫn luôn kiên trì, cùng nhau tiến lên, cùng vượt qua khó khăn trong cuộc sống. Giúp đỡ lẫn nhau, cùng nhau đạt được những thành tựu, cuối cùng hai người đều có thu hoạch trong cả công việc và tình cảm, cùng hoàn thành quá trình lột xác của thanh xuân, mở ra một tuổi 30 hoàn toàn mới.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Từ Lộ","avatar":""},{"name":"Trần Đô Linh","avatar":""},{"name":"Trương Vũ Kiếm","avatar":""},{"name":"Quách Phẩm Siêu","avatar":""},{"name":"Đặng Tuỵ Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
