INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-phai-2', 'Thiếu Niên Phái 2', 'Growing Pain 2', 'https://phimimg.com/upload/vod/20240517-1/244ac66e298f3a32ebe0b03af6eb85b1.jpg', 'https://phimimg.com/upload/vod/20240517-1/7d75cda49c24499e12ca3fb51fddab27.jpg', '<p>Nó kể về câu chuyện của bốn người bạn học cũ Lin Miaomiao, Qian Sanyi, Deng Xiaoqi, Jiang Tianhao và gia đình của họ sắp tốt nghiệp đại học, mặc dù họ có những rắc rối riêng nhưng họ vẫn nỗ lực để tiến về phía trước.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Jiayi","avatar":""},{"name":"Yan Ni","avatar":""},{"name":"Zhao Jinmai","avatar":""},{"name":"Guo Junchen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324268);
