INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-vi-tien', 'Chạy Vì Tiền', 'Run For The Money', 'https://phimimg.com/upload/vod/20240517-1/9f1c1f34441b006a34abf830d02c2bd7.jpg', 'https://phimimg.com/upload/vod/20240517-1/139a29b624f7eaa71198905b9f7870c9.jpg', '<p>Trong cuộc đua với thời gian, các thí sinh là người nổi tiếng dốc hết sức để thoát khỏi Thợ Săn mặc đồ đen nhằm giành giải thưởng tiền mặt ngày càng tăng.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sato Jiro","avatar":""},{"name":"Asei","avatar":""},{"name":"Ano","avatar":""},{"name":"Igeta Hiroe","avatar":""},{"name":"Elly","avatar":""},{"name":"Okubo Yoshito","avatar":""},{"name":"Kanemura Miku","avatar":""},{"name":"Kinjo Sukai","avatar":""},{"name":"Kuroki Hikari","avatar":""},{"name":"Kuro-chan","avatar":""},{"name":"Kosei","avatar":""},{"name":"Koumoto Junichi","avatar":""},{"name":"Kojima Yoshio","avatar":""},{"name":"Saito Tsukasa","avatar":""},{"name":"Sato Keigo","avatar":""},{"name":"Sano Hayato","avatar":""},{"name":"Shibatar","avatar":""},{"name":"Jinjin","avatar":""},{"name":"Seto Toshiki","avatar":""},{"name":"Tanakaga","avatar":""},{"name":"Tsud","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324268);
