INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-bac-si', 'Cảm Ơn Bác Sĩ', 'Thank You, Doctor', 'https://phimimg.com/upload/vod/20240517-1/6e9ecdcff4b55daae3f264f14ee6ea84.jpg', 'https://phimimg.com/upload/vod/20240517-1/4e781c46831cb684d4603743a0431fff.jpg', '<p>Dựa trên tiểu thuyết ICU 48 Giờ của tác giả Sheng Li, kể về cuộc sống của các bác sĩ trong khoa cấp cứu, nhằm tôn vinh những anh hùng thầm lặng bảo vệ tính mạng nhiều người. Phim xoay quanh bác sĩ Tiêu Nghiên (Dương Mịch), một cô gái thông minh đầy tâm huyết với nghề y. Sau khi hôn phu qua đời, Tiêu Nghiên chuyển công tác đến khoa cấp cứu bệnh viện Đồng Sơn. Tại đây, cô gặp Bạch Thuật (Bạch Vũ), một bác sĩ tài giỏi. Lúc đầu Tiêu Nghiên và Bạch Thuật có nhiều mâu thuẫn nhưng dần nhận ra những ưu điểm của đối phương, cùng nhau dốc hết tâm huyết vượt qua mọi khó khăn trong cuộc chiến giành lại sự sống cho bệnh nhân.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2022, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Bạch Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324268);
