INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-phap-y-jd', 'Nữ Pháp Y JD', 'Forensic JD', 'https://phimimg.com/upload/vod/20240517-1/4ed7a0bb22db5f7e6e68e6c6b7aaacf8.jpg', 'https://phimimg.com/upload/vod/20240517-1/c5e63678f99180cae542a37bb0ab8ca4.jpg', '<p>Bộ phim kể về cảnh ngộ của nữ pháp y JD Tống An Nghiên ở Viện giải mã nguyên nhân tử vong như một manh mối hỗ trợ cảnh sát phá những vụ án kì lạ. JD muốn tìm ra chân tướng trong vụ án của cha mình năm xưa, đã cùng cô gái bí ẩn Lâm Tiểu Mỹ, thám tử nhiệt huyết Lưu Chí Minh mở ra hàng loạt những câu chuyện ly kỳ chấn động. Nữ chính JD Tống An Nghiên mắc chứng HSP (hội chứng nhạy cảm cao) nên sở hữu một bộ não cực kỳ nhạy cảm, có thể tự động tiếp nhận tất cả thông tin trong mọi hoàn cảnh, tuy vô cùng khó chịu nhưng cũng không ít lần phải nhờ vào lượng thông tin dự trữ khác thường của bộ não siêu phàm để lần ra manh mối, giải mã nhưng câu đố chưa được phá giải.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"CharleneChoi","avatar":""},{"name":"Joseph","avatar":""},{"name":"GillianChung","avatar":""},{"name":"Kenny Kwan","avatar":""},{"name":"Prince Mak","avatar":""},{"name":"Carlos Chan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324268);
