INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-cua-vu-be-boi', 'Sự Thật Của Vụ Bê Bối', 'Anatomy Of A Scandal', 'https://phimimg.com/upload/vod/20240517-1/eecdad1351e65f6caf5c3a01d64fd73b.jpg', 'https://phimimg.com/upload/vod/20240517-1/6d1186b04a7147d25bd8c53b4eda1d05.jpg', '<p>Cuộc sống đầy đặc quyền của Sophie, vợ của chính trị gia quyền lực James, bỗng đảo lộn khi các bí mật tai tiếng lộ ra – và ông bị cáo buộc về tội ác động trời.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sienna Miller","avatar":""},{"name":"Michelle Dockery","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Naomi Scott","avatar":""},{"name":"Josette Simon","avatar":""},{"name":"Joshua McGuire","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324268);
