INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-that-cua-vu-be-boi', 'Sự Thật Của Vụ Bê Bối', 'Anatomy Of A Scandal', 'sự thật của vụ bê bối anatomy of a scandal sienna miller michelle dockery rupert friend naomi scott josette simon joshua mcguire ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-han-tinh-thu', 'Yêu Hận Tình Thù', 'Love Of Kill, Koroshi Ai, Cặp Đôi Sát Thủ', 'https://phimimg.com/upload/vod/20240517-1/0fcbcdfe3ace415dc8999524fb2b52b7.jpg', 'https://phimimg.com/upload/vod/20240517-1/dcf6daf23c46a0705a5f69e520da1159.jpg', '<p>Chateau Dankworth là một thợ săn tiền thưởng có tính cách im lặng và nghiêm khắc. Mục tiêu của cô là Son Ryang-ha - một kẻ giết người khét tiếng được biết đến với việc giết chết 18 quan chức cấp cao chỉ trong một đêm. Cho đến nay, những vụ giết người của hắn vẫn diễn ra nhanh chóng, hiệu quả và đẫm máu. Tuy nhiên, sau khi Son Ryang-ha áp đảo Chateau trong lần chạm trán đầu tiên của họ, anh ta tiết lộ ý định của riêng mình: anh ta cũng theo đuổi cô, nhắm đến trái tim của cô. Những nỗ lực của Son Ryang-ha để thu hút sự chú ý của cô ấy là khá độc đáo. Anh ta tặng quà cho cô ấy dưới dạng mục tiêu hiện tại của cô ấy, bị trói và bị đánh đập, và sẽ làm bất cứ điều gì để dành nhiều thời gian hơn cho nhau. Miễn cưỡng, Chateau tiếp tục hành động này, và thế là bắt đầu trò chơi mèo vờn chuột giữa hai kẻ giết người.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324268);
