INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nang-luc-cua-toi-khong-co-cam-giac-ton-tai', 'Siêu Năng Lực Của Tôi Không Có Cảm Giác Tồn Tại', 'My Superpowers Have No Sense Of Existence', 'https://phimimg.com/upload/vod/20240517-1/1704f4b7fb7e9442edcdcce4ff41e258.jpg', 'https://phimimg.com/upload/vod/20240517-1/189f4671779bcec06caf3a2b9ce2e481.jpg', '<p>Trương Vĩ lầm lì từ nhỏ đã bắt đầu ra đời làm việc, bạn bè thầy cô, đồng nghiệp cấp trên và thậm chí cả bố mẹ cũng thường quên đi sự tồn tại của cậu, trở thành ai đó bị phớt lờ từ nhỏ đến lớn. Nhưng năng lực tưởng chừng xui xẻo này lại vô tình khiến cậu trở thành một đặc công hàng đầu, nhiều lần trừ hại cho dân, đánh phá phản diện và làm anh hùng cứu mỹ nhân.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vu Tiểu Bân","avatar":""},{"name":"Tào Uyển Cẩn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
