INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-ky-quac-cua-james-va-max', 'Những Cuộc Phiêu Lưu Kỳ Quặc Của James Và Max', 'Oddballs', 'https://phimimg.com/upload/vod/20240517-1/765987592e83e77c951171b84f0a5e07.jpg', 'https://phimimg.com/upload/vod/20240517-1/c4d8ecc20985207908205ddb49389c32.jpg', '<p>Cậu bé hình bong bóng James thắc mắc đủ mọi chuyện và mọi thứ khiến cậu khó chịu. Kết quả ra sao? Một cuộc sống tuyệt vời ngập tràn cuộc phiêu lưu kỳ lạ cùng hai người bạn thân.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Rallison","avatar":""},{"name":"Julian Gant","avatar":""},{"name":"Kimberly Brooks","avatar":""},{"name":"Gary Anthony Williams","avatar":""},{"name":"Misty Lee","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
