INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-quoc-thien-nien', 'Chiến Quốc Thiên Niên', 'Millenniums Of Warring States', 'https://phimimg.com/upload/vod/20240517-1/12f1c2452b6477cbd5bb5fc140d215f8.jpg', 'https://phimimg.com/upload/vod/20240517-1/bc92339afb6fa8dde9de0a8e50890993.jpg', '<p>Cơ Thanh một blogger cao tay dùng plug-in Thiếu Hạo Cốt vượt thời gian về Xuân Thu Chiến Quốc. Nhưng quỹ đạo lịch sử đi chệch hướng, trong Hàm Dương Cung, Kinh Kha hành thích thành công Tần vương, bảy nước quần hùng nổi dậy, chiến quốc kéo dài ngàn năm. Hào hiệp Nhậm Dũng cùng tồn tại với kỹ thuật bách gia. Trung nghĩa thế gia và quần hùng tranh thiên hạ. Cùng xem người bất tử Cơ Thanh, rời Ung Thành vào Học cung, dùng thế lực Cửu Lê, tung hoành loạn thế.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
