INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('adamas', 'Adamas', 'Adamas', 'https://phimimg.com/upload/vod/20240517-1/e51ae2949cfd223ed1f455c16e059373.jpg', 'https://phimimg.com/upload/vod/20240517-1/4807423c920fd89dbb1fa65f092614ed.jpg', '<p>Bộ phim kể về câu chuyện của hai anh em sinh đôi (Ji Sung) chiến đấu chống lại cái ác để tiết lộ sự thật đằng sau một vụ giết người xảy ra 22 năm trước nhằm xóa tội danh cha ruột của họ, người bị buộc tội giết cha dượng của họ sau khi nghe án tử hình đã được lên kế hoạch cho cha ruột của họ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 18, 2022, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Sung","avatar":""},{"name":"Seo Ji Hye","avatar":""},{"name":"Lee Soo Kyung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
