INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-mai-cung-muon-gap-anh', 'Ngày Mai Cũng Muốn Gặp Anh', 'See You Tomorrow', 'https://phimimg.com/upload/vod/20240517-1/d35b6f4f1d3af5871df8726da5b71da9.jpg', 'https://phimimg.com/upload/vod/20240517-1/e34654f5f3e020305479557862f64edd.jpg', '<p>Ngày Mai Cũng Muốn Gặp Anh kể về câu chuyện của hai cặp đôi đầy duyên phận. Đinh Liễu Liễu, mộ người nhiệt tình và vui vẻ, biên đạo mới chương trình dân sinh của đài truyền hình Giang Hạ. Giang Khản tiến sĩ ngành dược, lạnh lùng, trầm mặc. Hai con người với tính cách hoàn toàn trái ngược nhau tình cờ trở thành bạn cùng phòng. Hàng loạt tình huống oái oăm đan xen giữa công việc và cuộc sống xảy ra giữa họ, cả hai ban đầu đều không ưa gì đối phương nhưng dần dần họ cũng hiểu nhau và cởi mở hơn. Hai người cùng thuê phòng còn lại là cậu em Đinh Mãn và streamer Liêm Ca Dao, hai người đều yêu thầm đối phương sau đó thì trải qua một mối tình đầy ngọt ngào. Hai cặp nam nữ đã tạo nên những câu chuyện hài hước ấm áp trong cuộc sống hàng ngày. Bốn nhân vật chăm chỉ làm việc cuối cùng sẽ cùng nhau đối mặt với thử thách của cuộc đời...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bunny Zhang","avatar":""},{"name":"Kangle Zhang","avatar":""},{"name":"Xie Xing Yang","avatar":""},{"name":"Lu Yu Xiao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324269);
