INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-ke-chuyen-nua-dem', 'Hội Kể Chuyện Nửa Đêm', 'The Midnight Club', 'https://phimimg.com/upload/vod/20240517-1/57c1adb4da7fe99e0055c79fb991ae52.jpg', 'https://phimimg.com/upload/vod/20240517-1/ffe42ab7d0926a3804b4e633bec1700e.jpg', '<p>Ở nhà an dưỡng cuối đời cho thiếu niên mắc bệnh nan y, các thành viên của một hội độc nhất vô nhị có giao kèo rợn gáy: người đầu tiên chết phải gửi tín hiệu về từ thế giới bên kia.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iman Benson","avatar":""},{"name":"Igby Rigney","avatar":""},{"name":"Ruth Codd","avatar":""},{"name":"Heather Langenkamp","avatar":""},{"name":"Annarah Cymone","avatar":""},{"name":"Chris Sumpter","avatar":""},{"name":"Adia","avatar":""},{"name":"Furukawa Aya","avatar":""},{"name":"Sauriyan Sapkota","avatar":""},{"name":"Matt Biedel","avatar":""},{"name":"Samantha Sloyan","avatar":""},{"name":"Zach Gilford","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
