INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-ngoai-hanh-tinh-sai-tieu-that-2', 'Cô Gái Ngoài Hành Tinh Sài Tiểu Thất 2', 'My Girlfriend Is An Alien 2', 'https://phimimg.com/upload/vod/20240517-1/08539813c1d6e9cb8d3ea33674f1fba3.jpg', 'https://phimimg.com/upload/vod/20240517-1/6fa8e0586c681bfc31accbf7d5c27cb2.jpg', '<p>Câu chuyện tình yêu sắp đến hồi viên mãn lại gặp phải sóng gió của Sài Tiểu Thất và Phương Lãnh. Được biết, trong phần hai của bộ phim này, Giang Thập Nhất, vị hôn phu chính tông của Sài Tiểu Thất ở Cape Town đã nghe mệnh lệnh của mẫu hoàng, phải cưỡng chế đưa Sài Tiểu Thất trở về ngay trong ngày cưới của hai người rồi tiến hành tẩy não cô. Liệu CP Không khí lạnh này có vượt qua được sóng gió, tìm lại thời khắc ngọt ngào của mình không? Một câu chuyện mới, nhất định có thể mang đến cảm giác mới mẻ và đầy bất ngờ cho các bạn khán giả.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vạn Bằng","avatar":""},{"name":"Từ Chính Hiên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
