INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-vung-dat-lanh', 'Từ Vùng Đất Lạnh', 'In From The Cold', 'https://phimimg.com/upload/vod/20240517-1/3bfce074353e1fe38a7abcd5be3bac30.jpg', 'https://phimimg.com/upload/vod/20240517-1/83a9f566f54928776a1e88a998b3f627.jpg', '<p>Lộ tẩy là cựu điệp viên Nga, bà mẹ đơn thân người Mỹ phải xoay sở giữa đời sống gia đình và các kỹ năng thay đổi hình dạng độc đáo để đấu với kẻ thù xảo quyệt.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Margarita Levieva","avatar":""},{"name":"Cillian OSullivan","avatar":""},{"name":"Lydia Fleming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324269);
