INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-vo-hinh', 'Thanh Tra Vô Hình', 'Shadow Detective', 'https://phimimg.com/upload/vod/20240517-1/7a43977bfe497aee14fc7e508f34e57a.jpg', 'https://phimimg.com/upload/vod/20240517-1/3773f2012f8bfd948b9d52de13b7f2b9.jpg', '<p>Kể về Kim Taek-Rok (Lee Sung-Min), một thám tử kỳ cựu tại Sở cảnh sát Geumo. Anh ấy đang chờ ngày nghỉ hưu. Kuk Jin-Han (Jin Goo) được chuyển đến Sở cảnh sát Geumo với tư cách là đội trưởng đội điều tra nơi Kim Taek-Rok làm việc. Một ngày nọ, Kim Taek-Rok nhận được một cuộc điện thoại. Người gọi nói với Kim Taek-Rok rằng anh ta là một người bạn cũ. Đó là cách mà cuộc điện thoại bí ẩn của anh ấy bắt đầu. Trong một cuộc gọi, người bạn cũ của Kim Taek-Rok nói với anh ta rằng anh ta đã giết đồng nghiệp của Kim Taek-Rok là Woo Hyun-Seok. Kim Taek-Rok sớm trở thành nghi phạm trong vụ giết Woo Hyun-Seok. Người gọi gợi ý rằng họ nên nhìn vào quá khứ của Kim Taek-Rok để tìm ra những điều anh ấy đã làm sai. Ban đầu, Kuk Jin-Han nghi ngờ Kim Taek-Rok là kẻ giết người trong cái chết của Woo Hyun-Seok, nhưng anh bắt đầu tin tưởng Kim Taek-Rok và sự vô tội của anh ấy. Họ bắt đầu tìm kiếm người bạn cũ của Kim Taek-Rok với sự giúp đỡ của các thám tử Lee Sung-A (Kyung Soo-Jin) và Son Kyung-Chan (Lee Hak-Joo).</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Sung-Min","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Kyung Soo-Jin","avatar":""},{"name":"Lee Hak-Joo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324269);
