INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-hau-thu-cuoi-hay-nghi', 'Tối Hậu Thư: Cưới Hay Nghỉ', 'The Ultimatum: Marry Or Move On', 'https://phimimg.com/upload/vod/20240517-1/103f2c740bfbe87baed90fbb1454aaa7.jpg', 'https://phimimg.com/upload/vod/20240517-1/7e162b6adeb932918cad095ef98032fa.jpg', '<p>Kết hôn hay chia tay? Các cặp đôi thử thách tình yêu của họ – trong khi sống cùng với người ghép đôi tiềm năng khác – trong loạt chương trình thực tế cuốn hút.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nick Lachey","avatar":""},{"name":"Vanessa Lachey","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
