INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-nguyet-hoi', 'Thương Nguyệt Hội', 'Pretty Guardian Of The City', 'https://phimimg.com/upload/vod/20240517-1/be172d464e71e34c66e7dfcb49cc317f.jpg', 'https://phimimg.com/upload/vod/20240517-1/75636ff1caf78dd13391a7b6b93bcfff.jpg', '<p>Thương Nguyệt Hội (Mỹ Nhân Nghịch Lân) là bộ phim kể về câu chuyện của Lạc gia, bị bọn xã hội đen cướp vì sở hữu phượng chi bí ẩn. Gia tộc này đã bị tiêu diệt và chỉ còn lại Lạc Khê Vân một cô gái bị nhiễm chất độc bào thai. Tám năm sau Lạc Khê Vân đã trở thành nhà khảo sát dân sự nổi tiếng nhất ở thành phố Thương Nguyệt. Cô dựa vào bán bản đồ và vẽ bản đồ khảo sát để kiếm sống. Cô bị nhiễm độc nặng và chỉ còn sống được ba tháng. Trước khi chết, cô muốn trả thù cho anh trai mình bằng cách giết Giang Triều Hi. Lúc này, phố Kiến Gia vốn là nơi duy nhất mang lại hơi ấm cho cô sắp bị phá hủy do quy hoạch phát triển thành phố. Để bảo vệ ngôi nhà của tổ tiên và dân làng, Lạc Khê Vân đã dồn hết tài năng của mình để đưa ra một bản đồ quy hoạch mới, sau đó cô tiếp cận Giang Triều Hi, trở thành khách hàng của hắn. Tình cờ, cô phát hiện ra rằng anh trai bất tỉnh của mình đang được giấu trong phủ. Cô cũng khám phá ra một bí mật đáng ngạc nhiên của Triều Hi. Trong quá trình cải trang và giao lưu với nhau họ nảy sinh tình cảm với nhau. Tuy nhiên, Khê Vân lại gặp nguy hiểm khi danh tính thực sự của cô ấy được bi tiết lộ</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xi Yu Li","avatar":""},{"name":"Yi Liyuan","avatar":""},{"name":"Jin Ze","avatar":""},{"name":"Liu Ying Lun","avatar":""},{"name":"Guan Xin","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
