INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-lake-phan-1', 'The Lake (Phần 1)', 'The Lake (Season 1)', 'https://phimimg.com/upload/vod/20240517-1/e75177d8b25e53a6847fa61b6296be6a.jpg', 'https://phimimg.com/upload/vod/20240517-1/53495461b9a5efb87fdf56bcf95544d8.jpg', '<p>Trở về từ nước ngoài sau cuộc chia tay với người tình lâu năm, Justin lên kế hoạch kết nối với cô con gái tuổi teen mà anh đã cho làm con nuôi. Kế hoạch tạo nên những kỷ niệm mới với con gái tại ngôi nhà nhỏ của gia đình anh trở nên tồi tệ khi anh phát hiện ra cha mẹ mình đã để lại nó cho người chị kế đẹp như tranh vẽ của anh, Maisy-May.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Brielle Robillard","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
