INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yakamoz-s245', 'Yakamoz S-245', 'Yakamoz S-245', 'https://phimimg.com/upload/vod/20240517-1/004e53f5f6d8e168f5b2062810441003.jpg', 'https://phimimg.com/upload/vod/20240517-1/1d7b08df8310a10a3cbf5d483e3e6212.jpg', '<p>Sau khi một thảm họa ập đến với Trái Đất, nhà sinh vật biển trong sứ mệnh nghiên cứu bằng tàu ngầm cùng thủy thủ đoàn phải chiến đấu để sinh tồn khi một âm mưu lộ diện.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 18, 2022, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Kıvanç Tatlıtuğ","avatar":""},{"name":"Özge Özpirinçci","avatar":""},{"name":"Ertan Saban","avatar":""},{"name":"Ece Çeşmioğlu","avatar":""},{"name":"Jerry Hoffmann","avatar":""},{"name":"Ecem Uzun","avatar":""},{"name":"Meriç Aral","avatar":""},{"name":"Ersin Arıcı","avatar":""},{"name":"Onur Ünsal","avatar":""},{"name":"Güven Murat Akpınar","avatar":""},{"name":"Hakan Salınmış","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
