INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-vi-pham-toi-phan-16', 'Hành Vi Phạm Tội (Phần 16)', 'Criminal Minds (Season 16)', 'https://phimimg.com/upload/vod/20240517-1/a625cbf1b409ce7d67c872c312920cd5.jpg', 'https://phimimg.com/upload/vod/20240517-1/256984ab4c5afd141d97ecd98c931334.jpg', '<p>Khi một kẻ hủy diệt gia đình bắt cóc một cô gái tuổi teen, BAU điều tra vụ án ở cả hai phía của đất nước để cứu cô ấy. Nhưng một mối liên hệ khó có thể xảy ra với một bộ dụng cụ bí ẩn đã dẫn đến một cuộc điều tra lớn hơn và trung tâm của cuộc điều tra là Penelope Garcia.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"A.J. Cook","avatar":""},{"name":"Joe Mantegna","avatar":""},{"name":"Adam Rodríguez","avatar":""},{"name":"Daniel Henney","avatar":""},{"name":"Aisha Tyler","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
