INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-o-mat-tran-phia-tay', 'Trận chiến ở Mặt trận phía Tây', 'Battle for the Western Front', 'https://phimimg.com/upload/vod/20240602-1/a44fb2d52b34a04d7fd9a9dabffeac7b.jpg', 'https://phimimg.com/upload/vod/20240602-1/9c5943d36a48c6e97c7b8e739bfdfbd2.jpg', '<p>Lấy cảm hứng từ phi công xuất sắc của Canuck thế chiến thứ nhất Billy Bishop, hai người lính trẻ xông vào tiền tuyến vào tháng 8 năm 1918. Khi quân Đồng minh bị giam giữ, trung đội của họ phải tuyệt vọng cầm cự bên cạnh tay bắn tỉa Anishinaabe huyền thoại Francis &quot;Peggy&quot; Pegahmagabow.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Michael Lake","avatar":""},{"name":"Christopher Cordell","avatar":""},{"name":"Sylvain Plasse","avatar":""},{"name":"Somerville Black","avatar":""},{"name":"Aaron Huggett","avatar":""},{"name":"Corey Chainey","avatar":""},{"name":"Sam Biskey","avatar":""},{"name":"Julian Seguin","avatar":""},{"name":"Adam Daniel Mezel","avatar":""},{"name":"Kyle Naylor","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324269);
