INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-hinh-tuong-takeaway', 'Tiệm Hình Tượng Take-away', 'Be Yourself', 'https://phimimg.com/upload/vod/20240517-1/e6ad3434d0f65ab58ca2a13db852cb5e.jpg', 'https://phimimg.com/upload/vod/20240517-1/06d47da3d39ce75e64607e18f958a5e6.jpg', '<p>Tiệm Hình Tượng Take-away kể về một tổ chức bí ẩn đã xuất hiện trong app di động của cô gái mắc bệnh ngại giao tiếp Trì Tiểu Ngư, ở đây cô có thể đặt hàng một hình tượng đơn giản như đặt ship đồ ăn. Để hoàn thành công việc, Trì Tiểu Ngư đã sử dụng một hình tượng con người khác nhưng cũng vì đó mà cô vô tình phát động cuộc tấn công chống lại chủ tịch độc đoán và khiến chàng chủ tịch bá đạo rơi vào lưới tình. Ngay khi Trì Tiểu Ngư chuẩn bị thoát kiếp FA, hình tượng tổng tài thành công của Tố Dương cũng sụp đổ</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bao Thượng Ân","avatar":""},{"name":"Phạm Tân Vĩ","avatar":""},{"name":"Chu Minh Lương","avatar":""},{"name":"Tôn Xán","avatar":""},{"name":"Đậu Nghệ Khôn","avatar":""},{"name":"Đinh Tử Thần","avatar":""},{"name":"Lý Tĩnh Nhất","avatar":""},{"name":"Viên Chí Dĩnh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
