INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-huu-van', 'Quân Hữu Vân', 'Word Of Honor', 'https://phimimg.com/upload/vod/20240517-1/0c63d1b2166d2a010ffa5b021a531e7d.jpg', 'https://phimimg.com/upload/vod/20240517-1/0ee6f198c651c8cd14dcd8828559fe4a.jpg', '<p>4 thiếu niên rời khỏi trường bước chân vào giang hồ, trên đường tìm kiếm chân tướng, làm sáng tỏ câu đố thân thế. Vì thành quân tử mà trải qua muôn vàn khó khăn nguy hiểm. Họ trọng đạo quân tử, thể hiện sự hiệp nghĩa lấy thân là sức, thực hiện công đạo nhân gian. Một bộ kỳ thư, một trận ân oán, một loại tín ngưỡng, một đoạn truyền kỳ.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
