INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-trieu-giap-de', 'Tôi Là Triệu Giáp Đệ', 'Zhao Jiadi', 'https://phimimg.com/upload/vod/20240517-1/eff0521aa53d4e12f3aa5a3874319b87.jpg', 'https://phimimg.com/upload/vod/20240517-1/a6957a5a557a55752cdac2271433da0b.jpg', '<p>Triệu Giáp Đệ, người thừa kế của tập đoàn kinh tế khổng lồ phương Bắc “Jinhai Industry”, đến Haicheng để bắt đầu cuộc sống đại học của mình. Triệu Giáp Đệ không thể đồng ý với những hành động xấu của cha mình từ khi còn nhỏ, anh luôn có một mối quan hệ cứng nhắc và không nhận tiền của cha mình, và sống một cuộc sống nghèo khổ. Ở Haicheng, “Thế hệ thứ hai chống lại người giàu” không điển hình này đã trải qua cuộc sống đại học, trải qua tình yêu và hoàn thành quá trình trưởng thành của một người đàn ông sau tất cả các loại trải nghiệm.Cùng lúc đó, cuộc tranh giành quyền lực của gia đình giàu có dần trở nên gay gắt, hàng loạt thế lực ngầm khiến Triệu Giáp Đệ rơi vào tâm điểm của vòng xoáy. Với niềm tin rằng “con người phải kiên trì để đạt được thành công”, cậu bé Zhao Jiadi đã tha thứ cho cha mình. Trong đấu trường này, Triệu Giáp Đệ đã một tay chuộc lại gia đình bình thường mà anh hằng mong ước.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Peng","avatar":""},{"name":"Yang Xing","avatar":""},{"name":"Zhuojun Yao","avatar":""},{"name":"Ma Yi","avatar":""},{"name":"Wang Ziyun","avatar":""},{"name":"Tan Xiaofan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324269);
