INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-duong-di-mua-he-ha-thien-khi-yeu', 'Yêu Đương Đi Mùa Hè (Hạ Thiên Khi Yêu)', 'Discovery Of Romance', 'https://phimimg.com/upload/vod/20240517-1/d076b2766c01b777fddda630104724e6.jpg', 'https://phimimg.com/upload/vod/20240517-1/d94ab2689120ca6cf3d6e527d5fe283e.jpg', '<p>Yêu Đương Đi Mùa Hè (Hạ Thiên Khi Yêu, Discovery Of Romance, Tình Yêu Mùa Hè) là bộ phim xoay quanh hành trình tình yêu vô cùng rối ren của người trưởng thành. Ngô Thiến vào vai một nhà thiết kế có sự nghiệp sáng chói ở ngưỡng tuổi 30. Thế nhưng lần gặp lại bạn trai cũ của cô lại khiến cuộc đời cô thay đổi chóng mặt. Lúc này đây, tình cảm của cô cùng bạn trai hiện tại gặp biến cố và sứt mẻ. Liệu quyết định của cô ấy sẽ như thế nào? Hãy cùng đón xem trên iQIYI với thông tin lịch chiếu Yêu Đương Đi Mùa Hè, tóm tắt nội dung Yêu Đương Đi Mùa Hè - Hạ Thiên Khi Yêu được cập nhật sớm nhất.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Janice Wu","avatar":""},{"name":"Qin Jun Jie","avatar":""},{"name":"Yang Bing Zhuo","avatar":""},{"name":"Sun Yi Ning","avatar":""},{"name":"Alika","avatar":""},{"name":"Xia Zhi Yuan","avatar":""},{"name":"Liu Dan","avatar":""},{"name":"劉儀偉","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
