INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-anh-dao-cuoi-dong', 'Hoa Anh Đào Cuối Đông', 'Cherry Blossoms After Winter', 'https://phimimg.com/upload/vod/20240517-1/800ad61c1bef599b6abb26acbb1f8a7f.jpg', 'https://phimimg.com/upload/vod/20240517-1/23a7281a569e667f174f5c5c5318f809.jpg', '<p>Mất cha mẹ trong một vụ tai nạn năm 8 tuổi, Hae Bom cuối cùng phải sống ở nhà Tae Seong. Họ là bạn thân và mẹ của họ cũng rất thân thiết. Tuy nhiên, Tae Seong thích Hae Bom như một đối tác chứ không phải một anh trai nên ban đầu cực lực phản đối việc sống với anh, vì Tae Seong phản đối, Hae Bom đã nói rằng anh không thích anh và anh đã giữ anh lại. Tae Seong nhìn thấy Hae Bom bị một học sinh bắt nạt Tae Seong đã bị sốc và sau đó anh ấy bắt đầu quan tâm đến anh ấy. sự thân thiết đã trở nên sâu sắc hơn qua một số sự cố.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Hui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
