INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-truc-thong-thai-phan-2', 'Gấu Trúc Thông Thái (Phần 2)', 'Stillwater (Season 2)', 'https://phimimg.com/upload/vod/20240509-1/cced89ce60038254a31417b783f65b6e.jpg', 'https://phimimg.com/upload/vod/20240509-1/823d7aa8f7f03bd2ffa1e625a9a17bd0.jpg', '<p>Anh em Karl, Addy và Michael có một người hàng xóm rất đặc biệt: một chú gấu trúc khôn ngoan tên là Stillwater. Tình bạn và những câu chuyện của anh ấy mang đến cho họ những góc nhìn mới về thế giới, về bản thân và về nhau.</p>', 'Hoàn Tất (7/7)', 7, 'hoathinh', 'completed', 10, 2022, 'Lồng Tiếng', 'HD', 'Âu Mỹ', 0, '[{"name":"James Sie","avatar":""},{"name":"Eva Binder","avatar":""},{"name":"Tucker Chandler","avatar":""},{"name":"Judah Mackey","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
