INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-mai-cung-muon-gap-em', 'Ngày Mai Cũng Muốn Gặp Em', 'I Wanna See You Again', 'https://phimimg.com/upload/vod/20240509-1/cb9618a51069c4cad95c34522a1b4187.jpg', 'https://phimimg.com/upload/vod/20240509-1/021d319e2e1f7c6b9b0b543711bd9dc4.jpg', '<p>Đinh Liễu Liễu mộ người nhiệt tình và vui vẻ, biên đạo mới chương trình dân sinh của đài truyền hình Giang Hạ. Giang Khản tiến sĩ ngành dược, lạnh lùng, trầm mặc. Hai con người với tính cách hoàn toàn trái ngược nhau tình cờ trở thành bạn cùng phòng. Hàng loạt tình huống oái oăm đan xen giữa công việc và cuộc sống xảy ra giữa họ, cả hai ban đầu đều không ưa gì đối phương nhưng dần dần họ cũng hiểu nhau và cởi mở hơn. Hai người cùng thuê phòng còn lại là cậu em Đinh Mãn và streamer Liêm Ca Dao, hai người đều yêu thầm đối phương sau đó thì trải qua một mối tình đầy ngọt ngào. Hai cặp nam nữ đã tạo nên những câu chuyện hài hước ấm áp trong cuộc sống hàng ngày. Bốn nhân vật chăm chỉ làm việc cuối cùng sẽ cùng nhau đối mặt với thử thách của cuộc đời...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bunny Zhang","avatar":""},{"name":"Kangle Zhang","avatar":""},{"name":"Xie Xing Yang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
