INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-an-do-nhat-ky-ke-giet-nguoi-hang-loat', 'Sát Nhân Ấn Độ: Nhật Ký Kẻ Giết Người Hàng Loạt', 'Indian Predator: The Diary Of A Serial Killer', 'https://phimimg.com/upload/vod/20240509-1/78c3a98ce9468ff197427db32c94f601.jpg', 'https://phimimg.com/upload/vod/20240509-1/87a6ab826cc0abf45c062ed1d857eab6.jpg', '<p>Khi tìm được nghi phạm trong vụ sát hại một nhà báo, vụ việc được coi là đã khép lại cho đến khi cuốn nhật ký bí mật hé lộ thêm 13 nạn nhân – và tình tiết ăn thịt người.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324269);
