INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-gio-ma-di', 'Hướng Gió Mà Đi', 'Flight To You', 'https://phimimg.com/upload/vod/20240509-1/86d672ad32b4fa3a26e6e48ce7a119a1.jpg', 'https://phimimg.com/upload/vod/20240509-1/9f95ff69c16053a7f8a5574ec46333f6.jpg', '<p>Là câu chuyện thanh xuân tràn ngập nhiệt huyết, về hành trình cùng nhau trưởng thành giữa phó giám đốc bộ phận bay khó tính Cố Nam Đình (Vương Khải) và nữ phi công nghịch ngợm Trình Tiêu (Đàm Tùng Vận). Hai người cùng công tác trong một đơn vị, với tính cách khác nhau lại tình cờ trở thành thầy trò, trải qua hàng loạt xung đột và thử thách trong các sự cố hàng không, cuối cùng gạt bỏ mọi trở ngại, cùng nhau xây dựng ước mơ.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Khải","avatar":""},{"name":"Đàm Tùng Vận","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
