INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phieu-luu-trong-nha-ma', 'Phiêu Lưu Trong Nhà Ma', 'Rose In Da House', 'https://phimimg.com/upload/vod/20240509-1/a0dd8619531de2bed39b3e9e723bab24.jpg', 'https://phimimg.com/upload/vod/20240509-1/ef4d8d79b2f61875c8f795f27cc8fe7d.jpg', '<p>Vào lúc nửa đêm trong Lễ hội Phật giáo (Ngày cạo đầu và Đêm trăng tròn), 6 thần tượng nổi tiếng là Kacha, Boon, Zee, Talay, Tommy và Mark đã đến địa điểm do công ty DnD sắp xếp. Họ tập trung ở đây để tập luyện cho chương trình biểu diễn lớn đầu tiên trong năm của họ. Nhưng không ai ngờ rằng, tại căn phòng màu đỏ gạch này, họ đã gặp Rose, một linh hồn đã sống ở đây hơn 200 năm. Cô là một linh hồn cô đơn, điên cuồng, bị ám ảnh bởi những bộ phim truyền hình và ngượng ngùng khi gặp được những idol này. Giữa họ xảy ra một loạt những sự hỗn loạn. Tình huống vừa bất ngờ ngoài sức tưởng tượng, vừa kỳ quái và vui nhộn. Sự kiện bí ẩn trong ngôi nhà màu đỏ gạch buộc 6 thanh niên này buộc phải bắt đầu cuộc phiêu lưu mạo hiểm của mình để tìm hiểu xem những điều đã xảy ra với họ là ma ám thật, hay chỉ là trong sự tưởng tượng của họ...</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nontanun Anchuleepradit","avatar":""},{"name":"Pruk Panich","avatar":""},{"name":"Noppanut Guntachai","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
