INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-long', 'Chiếc Lồng', 'The Cage', 'https://phimimg.com/upload/vod/20240509-1/da6059a7412580c649e2c93accf17945.jpg', 'https://phimimg.com/upload/vod/20240509-1/3dc7f3ee21eda1637c96098a70152855.jpg', '<p>Một chuyên gia tư vấn hôn nhân cố khuyên can những khách hàng đang mâu thuẫn đừng ly hôn, đồng thời xử lý loạt tình huống éo le trong chuyện tình cảm của chính mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Khaled Ameen","avatar":""},{"name":"Hussien Almahdi","avatar":""},{"name":"Rawan Mahdi","avatar":""},{"name":"Lamya Tareq","avatar":""},{"name":"Shabnam Khan","avatar":""},{"name":"Hessa Al Nabhan","avatar":""},{"name":"Shawq","avatar":""},{"name":"Mai Al Balushi","avatar":""},{"name":"Ahmed Mossaed","avatar":""},{"name":"Zaina Mahdi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
