INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-hong-nhan', 'Nợ Hồng Nhan', 'Lost Promise', 'https://phimimg.com/upload/vod/20240509-1/78a857ab518ef5f3dfc164e54364225f.jpg', 'https://phimimg.com/upload/vod/20240509-1/39fd429f38090eef94ef3054902ce3ca.jpg', '<p>Trong thế giới võ thuật, hai sự phát triển lớn đã xảy ra. Đầu tiên, Võ sư Jiang Qing Liu mới bị tấn công tại buổi lễ của ông, khiến ông mất nội lực. Thứ hai, Chúa quỷ Bo Ye Jing Xing trốn thoát khỏi nơi giam cầm sau khi bị giam cầm trong 11 năm bởi cựu Võ sư Jiang Yin Tian. Trong khi mọi người đang tìm kiếm Chúa Quỷ, họ ít biết rằng hắn đang trốn trong buồng ngủ của Qing Liu. Bo Ye Jing Xing sẽ giúp Qing Liu phục hồi sức mạnh bên trong khi anh ấy ở bên cạnh. Nhiều ngày sau, một người phụ nữ xinh đẹp được giao cho Qing Liu trong một chiếc hộp gấm cùng với sách hướng dẫn và một số viên thuốc rouge. Qing Liu giả vờ say mê cô và giữ cô làm vợ lẽ. Gia đình họ Jiang và những người hầu đều bối rối trước người phụ nữ có vẻ ngoài đoan trang nhưng thô kệch.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Diêu Vọng","avatar":""},{"name":"Dương Á Minh","avatar":""},{"name":"Vu Văn Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324269);
