INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-la-phan-2', 'Kẻ Thù Lạ (Phần 2)', 'An Unknown Enemy (Season 2)', 'https://phimimg.com/upload/vod/20240509-1/8638285ed14bb5ce7d49e696bbf88014.jpg', 'https://phimimg.com/upload/vod/20240509-1/45c14de9cda494656862aaf614c1be60.jpg', '<p>Fernando Barrientos, Trưởng ban An ninh Quốc gia, Cảnh sát Bí mật Mexico, đang cố gắng đạt được vị trí cao nhất trong nước. Trên con đường của mình, anh ta sẽ phải thao túng, phản bội và giết chóc, và anh ta đã chuẩn bị kỹ càng cho điều đó. Tuy nhiên, con đường của anh ấy sẽ đầy chướng ngại vật. Không ai, kể cả gia đình anh ta, sẽ miễn nhiễm với sự hỗn loạn còn sót lại trong hành trình tìm kiếm quyền lực toàn diện của anh ta.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 13, 2022, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Daniel Giménez Cacho","avatar":""},{"name":"Fernando Becerril","avatar":""},{"name":"Antonio de la Vega","avatar":""},{"name":"Hernán del Riego","avatar":""},{"name":"Karina Gidi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
