INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-con-cua-bo-lac-phan-2', 'Người Con Của Bộ Lạc (Phần 2)', 'Barbarians (Season 2)', 'https://phimimg.com/upload/vod/20240509-1/d88011902745820d4a1a213136f14d68.jpg', 'https://phimimg.com/upload/vod/20240509-1/97d2aabd1c6cc78a568a3d2b78132860.jpg', '<p>Một năm sau thất bại của Varus, một vị tướng La Mã mới bắt nhịp với cuộc sống ở Germania khi Ari tìm cách trở thành vua của mọi bộ tộc – song một đối thủ cản đường anh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Laurence Rupp","avatar":""},{"name":"Jeanne Goursaud","avatar":""},{"name":"David Schütter","avatar":""},{"name":"Ronald Zehrfeld","avatar":""},{"name":"Nicki von Tempelhoff","avatar":""},{"name":"Bernhard Schütz","avatar":""},{"name":"Eva Verena Müller","avatar":""},{"name":"Sophie Rois","avatar":""},{"name":"Gaetano Aronica","avatar":""},{"name":"Nikolai Kinski","avatar":""},{"name":"Jeremy Miliker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
