INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-phan-5', 'Đế Chế (Phần 5)', 'Dynasty (Season 5)', 'https://phimimg.com/upload/vod/20240509-1/9b0e6baedba23fe6a5ba701300cddd6c.jpg', 'https://phimimg.com/upload/vod/20240509-1/ccf0607c38951d5aa16da16660783df6.jpg', '<p>Trong xã hội thượng lưu Atlanta, hai gia đình giàu có rơi vào xung đột dữ dội về quyền lực, thanh thế và tình yêu. Và để bám trụ thì phải chơi bẩn.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Gillies","avatar":""},{"name":"Grant Show","avatar":""},{"name":"Rafael De La Fuente","avatar":""},{"name":"Robert Christopher Riley","avatar":""},{"name":"Sam Adegoke","avatar":""},{"name":"Alan Dale","avatar":""},{"name":"Maddison Brown","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
