INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-re-hon-nhan', 'Ngã Rẽ Hôn Nhân', 'Two Conjectures About Marriage', 'https://phimimg.com/upload/vod/20240509-1/b6c4ea09ada2c3f867e8ccaf850f27ff.jpg', 'https://phimimg.com/upload/vod/20240509-1/927745086a433accdb65546813f2e0d2.jpg', '<p>Ngã Rẽ Hôn Nhân chuyện kể về hôn nhân chớp nhoáng của Thẩm Minh Bảo- người phụ nữ tài giỏi và Dương Tranh- người đàn ông IT khô khan. Nhưng đôi vợ chồng mới cưới bận rộn đến mức chỉ có thể gặp nhau 2 lần một tuần. Tiết Khả Hân-cô tiểu thư xinh đẹp giàu có, là bạn từ nhỏ của Thẩm Minh Bảo, vừa kết hôn với Trần Đồng Cương- một nam diễn viên kém cô tám tuổi. Để giúp đỡ sự nghiệp của chồng, cô đã mua lại một công ty nào ngờ đây chính là nơi mà Thẩm Minh Bảo làm việc. Để bù đắp cho việc mất khách hàng, Thẩm Minh Bảo đã làm việc hết sức dẫn đến sẩy thai. Dương Tranh biết tin đã từ chức cho cô nhưng điều này đã gây ra mâu thuẫn vợ chồng. Tiết Khả Hân và Trần Đồng Cương do bất đồng trong tính cách cuối cùng lựa chọn ly hôn. Thẩm Minh Bảo có thai một lần nữa, nhưng sự nghiệp của Dương Tranh đi xuống, Thẩm Minh Bảo lại càng phải cố gắng nhiều hơn nữa để giúp công ty hồi sinh. Bốn con người đều trải qua khó khăn trong cuộc sống, sau cùng Tiết Khả Hân và Trần Đồng Cương tái hôn, Thẩm Minh Bảo và Dương Tranh sẽ phải cùng nhau đối mặt với hôn nhân của mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Tử San","avatar":""},{"name":"Bành Quán Anh","avatar":""},{"name":"Lâm Bằng","avatar":""},{"name":"Triệu Chí Vỹ","avatar":""},{"name":"Mã Tô","avatar":""},{"name":"Từ Nhạc Đồng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad3