INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-vung-dat-leadale', 'Tại Vùng Đất Leadale', 'World Of Leadale, In The Land Of Leadale, Riadeiru No Daichi Nite', 'https://phimimg.com/upload/vod/20240509-1/99584df47dcb3d4621bfa0c78d6b8713.jpg', 'https://phimimg.com/upload/vod/20240509-1/fca0ada2cf6fdd96b8022ba0547404f0.jpg', '<p>Keina là một cô gái trẻ không thể sống thiếu hệ thống Hỗ trợ Sự sống. Một ngày nọ, Hệ thống ngừng hoạt động đã khiến Keina mất mạng. Tuy nhiên khi tỉnh dậy, Keina đã ở Leadale của Riad 200 năm sau. Cuộc phiêu lưu nhàn nhã bắt đầu từ đây.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
