INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-phan-2', 'Cô Ấy (Phần 2)', 'She (Season 2)', 'https://phimimg.com/upload/vod/20240509-1/3da8a48cec54864fc80cf0d4db4aab3b.jpg', 'https://phimimg.com/upload/vod/20240509-1/252382a418214ca7b2d958687685b4d2.jpg', '<p>Sau khi thề trung thành với ông trùm Nayak, Bhumi khám phá tự do tình dục – và mặt tối của cô – khi bước trên ranh giới giữa nghĩa vụ và ham muốn.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Aaditi Pohankar","avatar":""},{"name":"Vijay Varma","avatar":""},{"name":"Vishwas Kini","avatar":""},{"name":"Kishore Kumar G.","avatar":""},{"name":"Shivani Rangole","avatar":""},{"name":"Suhita Thatte","avatar":""},{"name":"Sandeep Dhabale","avatar":""},{"name":"Saqib Ayub","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
