INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-nuong-cat-tuong', 'Tân Nương Cát Tường', 'The Blessed Bride', 'https://phimimg.com/upload/vod/20240509-1/77962844e4f958f1af49ca0346538ab5.jpg', 'https://phimimg.com/upload/vod/20240509-1/b236294ee49cda5d4b2db84cd84f0b49.jpg', '<p>Bộ phim xoay quanh Nước Cẩn, Nguyệt Lưu Doanh, vốn chỉ là một thiếu nữ nghịch ngợm ngây thơ, nhưng bị nghĩa huynh hạ độc uy hiếp ép gả cho Lăng Tề Diệp làm thiếp. Nguyệt Lưu Doanh không muốn bị khống chế phải làm ra trò gian tế, nhưng lại không có cách nào thoát khỏi sự khống chế của nghĩa huynh, đành phải đi tìm con đường khác để sống. Vào đêm tân hôn tìm cách hạ độc tân lang chết giả để cô có thể trốn khỏi Lăng gia, tìm lại tự do. Nhưng bất đắc dĩ, đêm tân hôn mỗi người đều ôm một ý đồ khác, vô tình tạo nên Ông bà Smith phiên bản cổ đại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tôn Nghệ Ninh","avatar":""},{"name":"Văn Uyên","avatar":""},{"name":"Phan Duyệt","avatar":""},{"name":"Vương Uẩn Phàm","avatar":""},{"name":"Lý Bái Lâm","avatar":""},{"name":"Đặng Thi Vận","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324269);
