INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiger-bunny-phan-2', 'TIGER & BUNNY (Phần 2)', 'TIGER & BUNNY (Season 2)', 'https://phimimg.com/upload/vod/20240509-1/578bb8b0587471e5039e23e584cb5a0e.jpg', 'https://phimimg.com/upload/vod/20240509-1/05a44a5810042862afd85e95d0596075.jpg', '<p>Bộ đôi anh hùng đũa lệch Hổ Dữ và Barnaby dẫn đầu trong việc giữ hòa bình và có được nhà tài trợ khi các anh hùng từ khắp nơi trên thế giới bước vào cuộc chiến.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hirata Hiroaki","avatar":""},{"name":"Morita Masakazu","avatar":""},{"name":"Yusa Koji","avatar":""},{"name":"Kotobuki Minako","avatar":""},{"name":"Kaida Yuhko","avatar":""},{"name":"Inoue Go","avatar":""},{"name":"Tsuda Kenjiro","avatar":""},{"name":"Ise Mariya","avatar":""},{"name":"Kusunoki Taiten","avatar":""},{"name":"Okamoto Nobuhiko","avatar":""},{"name":"Fujiwara Keiji","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324269);
