INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-lof-lo-va-vao-nhau', 'Tâm LOF - Lỡ Va Vào Nhau', 'Tâm LOF - Lỡ Va Vào Nhau', 'https://phimimg.com/upload/vod/20240509-1/e1bcd03e084de2e66df2ba856a0613f6.jpg', 'https://phimimg.com/upload/vod/20240509-1/cf80cfa08262ec11ee6d94e3f131e877.jpg', '<p>Câu chuyện về mối quan hệ giữa Tâm Lof (Tuấn Trần) -&nbsp; chàng trai cục súc, nong tính nhưng ẩn chứa một trái tim ấm áp, luôn giúp đỡ mọi người; Thương (Midu) - người mẹ đơn thân siêu cool - ngầu, xinh đẹp, có chính kiến và hết mình vì công việc; Dũng (Kiều Minh Tuấn) - anh chàng hào hoa, phong nhã và khéo léo. Tất cả lỡ va vào nhau trong một hoàn cảnh không ai ngờ tới, dẫn đến bao câu chuyện éo le, sóng gió. Nhưng cuối cùng, tất cả đều chọn yêu thương để hóa giải mâu thuẫn và gặt quả ngọt của hạnh phúc.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Tuấn Trần","avatar":""},{"name":"MiDu","avatar":""},{"name":"Puka","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""},{"name":"La Thành","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324269);
