INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-cong-chua', 'Bảy Công Chúa', 'Sctv9', 'https://phimimg.com/upload/vod/20240509-1/985ef2e69bcc8597a46d9c6d7d78d48f.jpg', 'https://phimimg.com/upload/vod/20240509-1/cc30780a7d9b0fbc12865a3eb9a6e129.jpg', '<p>Bảy Công Chúa – SCTV9 TVB (2022) Cố Bách Phương là một đại gia giàu có, khi qua đời ông để lại cho 7 người con cùng cha khác mẹ của mình một tấm di thư. Ông mong rằng, họ sẽ tìm thấy nhau và sống hạnh phúc bên nhau. Cố Linh San là cô chị cả, luật sư tài giỏi nhưng qua lại với người đã có gia đình. Cố Thanh Đồng, Cố Song Nhi là hai người em ruột của cô. Họ không thực sự hòa đồng. Cố Ngư Yến là người em thứ ba, Triệu Quân Nguyệt là người con thứ 5, Phương Sở Du là người con thứ 6. Rồi ngày nọ, cả 6 chị em biết tin mình còn một người em thứ 7. Họ quyết định cùng nhau đi tìm em, cũng là thời gian để họ tìm lại giá trị của chính mình.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
