INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-lan-nhat-phien-phong-van-khoi', 'Bằng Lan Nhất Phiến Phong Vân Khởi', 'Defying The Storm', 'https://phimimg.com/upload/vod/20240509-1/0128aa22c39a2a309997d7bf2dae1508.jpg', 'https://phimimg.com/upload/vod/20240509-1/4855d4875bba0fe54576cb0f8e5a697d.jpg', '<p>Bằng Lan Nhất Phiến Phong Vân Khởi xoay quanh thời kỳ khó khăn của Trung Quốc trong những năm 1937-1945, miêu tả ba gia đình tri thức cùng một nhóm thanh niên phi công và học sĩ, bảo tồn văn mạch truyền đời, phát triển hàng không cứu quốc, trên con đường từ Nam sang Tây đưa ra những hi sinh cùng lựa chọn của họ. Bộ phim ca ngợi tình cảm yêu nước, nhân cách độc lập, lý tưởng tự do và tinh thần thuần túy của những quốc sĩ giỏi văn giỏi võ trong thời kỳ lịch sử đầy biến động ấy.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hồ Nhất Thiên","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Vương Kính Tùng","avatar":""},{"name":"Trương Hi Lâm","avatar":""},{"name":"Trương Hách","avatar":""},{"name":"Lâm Tử Lộ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
