INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-buong-hieu-ky-cua-guillermo-del-toro', 'Căn Buồng Hiếu Kỳ Của Guillermo Del Toro', 'Guillermo Del Toro''s Cabinet Of Curiosities', 'https://phimimg.com/upload/vod/20240509-1/5ab4d24695d3e83645a04a1b2754a83a.jpg', 'https://phimimg.com/upload/vod/20240509-1/f400bb3e139575504b29548e4498eaf0.jpg', '<p>Những ác mộng kỳ quặc diễn ra trong tám câu chuyện kinh hoàng thuộc bộ sưu tập chuyện kinh dị rợn gáy và mãn nhãn này do Guillermo del Toro tuyển chọn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Blake Nelson","avatar":""},{"name":"Sebastian Roché","avatar":""},{"name":"Elpidia Carrillo","avatar":""},{"name":"Demetrius Grosse","avatar":""},{"name":"David Hewlett","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Glynn Turman","avatar":""},{"name":"Luke Roberts","avatar":""},{"name":"Kate Micucci","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Dan Stevens","avatar":""},{"name":"Ben Barnes","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Oriana Leman","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Ismael Cru","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324269);
