INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('can-buong-hieu-ky-cua-guillermo-del-toro', 'Căn Buồng Hiếu Kỳ Của Guillermo Del Toro', 'Guillermo Del Toro''s Cabinet Of Curiosities', 'căn buồng hiếu kỳ của guillermo del toro guillermo del toro''s cabinet of curiosities tim blake nelson sebastian roché elpidia carrillo demetrius grosse david hewlett f. murray abraham glynn turman luke roberts kate micucci martin starr dan stevens ben barnes crispin glover oriana leman rupert grint ismael cru ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-hoa-duc-vong', 'Bông Hoa Dục Vọng', 'Raan Dok Ngiw', 'https://phimimg.com/upload/vod/20240509-1/b902147308b51092ef7ba523ecc498f3.jpg', 'https://phimimg.com/upload/vod/20240509-1/bc954e4cf66d21bab822adbcfb4d2a35.jpg', '<p>Nao, cô gái dân tộc miền Bắc Thái Lan, vô tình gặp gỡ và có cảm tình với chàng giám đốc Phitoon. Nghe lời ngon ngọt của Phitoon, Nao đã trao thân cho anh ta. Ngay sau khi biết mình có thai, cô vội vàng lên Băng Cốc tìm Phitoon, nào ngờ anh ta lại sắp cưới Penpayom, một người phụ nữ quyền lực và giàu có. Penpayom biết chuyện liền cho người giết Nao một cách dã man nhưng cô may mắn thoát được. Từ đây, cuộc đời Nao bước vào một ngã rẽ mới với chuỗi ngày nung nấu ý định trả thù.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 4, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Yui Chiranan Manochaem","avatar":""},{"name":"Oil Thana Suttikamol","avatar":""},{"name":"Than Thanakorn","avatar":""},{"name":"Toy Pathompong Reonchaidee","avatar":""},{"name":"Nonny Nutcha Jeka","avatar":""},{"name":"Pornchita Na Songkhla","avatar":""},{"name":"Benz Punyaporn Pongpipat","avatar":""},{"name":"Beam Kawee Tanjararak","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
