INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-phap-luat-quyen-cong-to', 'Đế Chế Pháp Luật - Quyền Công Tố', 'The Empire', 'https://phimimg.com/upload/vod/20240509-1/d16723ea3885e261c2a7388b99b44047.jpg', 'https://phimimg.com/upload/vod/20240509-1/2d7ba6e01b913c9f9aa40aecbc59be7a.jpg', '<p>Đế Chế Pháp Luật - The Empire 2022, một bộ phim miêu tả chi tiết và xúc tích những vụ bê bối tai tiếng từ những quan chức cấp cao, giới thượng lưu của quốc gia với ước mơ được cha truyền con nối.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Sun Ah","avatar":""},{"name":"Ahn Jae Wook","avatar":""},{"name":"Lee Mi Sook","avatar":""},{"name":"Song Young Chang","avatar":""},{"name":"Shin Goo","avatar":""},{"name":"Oh Hyun Kyung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324269);
