INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngam-chuan-hong-tam-thai-kim-diep', 'Ngắm Chuẩn Hồng Tâm! Thái Kim Diệp', 'Aim The Heart! Archeress', 'https://phimimg.com/upload/vod/20240509-1/8cb648b43280a18acde63a416d0ad2c5.jpg', 'https://phimimg.com/upload/vod/20240509-1/559fee4c2c63af911c4045088e04ac21.jpg', '<p>Bộ phim kể về câu chuyện cựu ngôi sao Hàn Nhược Phi muốn xây dựng lại hình tượng người đàn ông thể thao nên được công ty sắp xếp tham gia vào đội bắn cung và trở thành học trò của Thái Kim Diệp. Ban đầu hai người vốn không ưa gì nhau, chuyện gì cũng phải giằng co một phen, dồn sức gây phiền toái cho đối phương. Trong thời gian bên nhau, sự bầu bạn của Hàn Nhược Phi cũng trở thành động lực lớn để Thái Kim Diệp theo đuổi ước mơ, hai trái tim cứ thế liên tục đến gần nhau. Hai mũi tên vốn chẳng liên quan nhau đang dần nỗ lực bay về hướng hồng tâm thuộc về họ...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nghiêm Trí Siêu","avatar":""},{"name":"Kim Giai Ngộ","avatar":""},{"name":"Triệu Mộ Nhan","avatar":""},{"name":"Kha Bác Luân","avatar":""},{"name":"Trình Phàm","avatar":""},{"name":"Lục Vũ","avatar":""},{"name":"Tô Na","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
