INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('futoku-no-girudo', 'Futoku No Girudo', 'Immoral Guild', 'https://phimimg.com/upload/vod/20240509-1/4701f77f6ff374ed0a1c6e80f822fa8b.jpg', 'https://phimimg.com/upload/vod/20240509-1/d5ebb6a11ae9e24c747bf4f7c253d86f.jpg', '<p>Câu chuyện kể về người thợ săn lành nghề Kikuru Madan, người đã quyết định nghỉ hưu vì sợ lãng phí tuổi trẻ của mình. Một ngày nọ, nhân viên của hiệp hội đã gợi ý rằng anh ta nên thực hiện một nhiệm vụ cùng nữ võ sĩ tên là Hitamu Kyan. Tuy nhiên, cô ấy liên tục bị đánh bởi quái vật này đến quái vật khác.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324269);
