INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-phan-dien-dien-sieu-sau', 'Bạn Gái Phản Diện Diễn Siêu Sâu', 'Life Is Drama', 'https://phimimg.com/upload/vod/20240509-1/509f1d90d193c13b28f11633263893ce.jpg', 'https://phimimg.com/upload/vod/20240509-1/45d8cd2ef5c8912b8cd76bd35d18c912.jpg', '<p>Nữ chính Nhan Phi kế thừa một nhà hát xuống cấp do cha mẹ để lại. Để vực dậy nhà hát, Nhan Phi đã dùng hết bản lĩnh của mình. Trong một lần tình cờ, cô gặp được Tạ Tri, vì muốn có được sự giúp đỡ của Tạ Tri, Nhan Phi tung ra nhiều chiêu trò tán tỉnh, sự nghiệp liên tục chuyển bại thành thắng, đồng thời cũng gặt hái được tình yêu đích thực.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 4, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hồ Diệc Dao","avatar":""},{"name":"Lưu Hựu Sướng","avatar":""},{"name":"Dương Tuấn","avatar":""},{"name":"Hàn Hạnh Ngâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
