INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-gau-bong-ky-dieu', 'Chú Gấu Bông Kỳ Diệu', 'The Miracle Of Teddy Bear', 'https://phimimg.com/upload/vod/20240509-1/5d060f8076e1d0832873993a5fdfe4d6.jpg', 'https://phimimg.com/upload/vod/20240509-1/6edc2b008123cb0324fbc0037f013624.jpg', '<p>Khi chú gấu bông của một thiếu niên hé lộ hình hài con người của mình, chú cố gắng tìm hiểu về quá khứ của bản thân trước khi thời gian mang hình người kết thúc.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Sarin Ronnakiat","avatar":""},{"name":"Thuchapon Koowongbundit","avatar":""},{"name":"Thanapon Jarujitranon","avatar":""},{"name":"Parada Chutchavalchotikul","avatar":""},{"name":"Apasiri Chantrasmi","avatar":""},{"name":"Rinlanee Sripen","avatar":""},{"name":"Chatayodom Hiranyasthiti","avatar":""},{"name":"Tantachj Tharinpirom","avatar":""},{"name":"Punpredee Khumprom Rodsward","avatar":""},{"name":"Wasun Uttamayodhin","avatar":""},{"name":"Chusak Suteeratham","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
