INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-khong-lua-doi-diem-den-sardinia', 'Tình Yêu Không Lừa Dối: Điểm Đến Sardinia', 'Love Never Lies: Destination Sardinia', 'https://phimimg.com/upload/vod/20240509-1/c38f09b0dfe8124e65b7b24c66c4ae9d.jpg', 'https://phimimg.com/upload/vod/20240509-1/0d6ba8a1d4abbdb674337c8e68c0589d.jpg', '<p>Một nhóm mới gồm những cặp đôi tưởng chừng rất gắn bó sẽ thử thách mối quan hệ của họ. Trong cuộc theo đuổi tình yêu và tiền bạc, liệu sự thật sẽ gây tổn thương hay giúp chữa lành?</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 9, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
