INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-khong-lua-doi-diem-den-sardinia', 'Tình Yêu Không Lừa Dối: Điểm Đến Sardinia', 'Love Never Lies: Destination Sardinia', 'tình yêu không lừa dối: điểm đến sardinia love never lies: destination sardinia  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-thoi-ban-ha-da-man-sinh-truong', 'Gió Thổi Bán Hạ (Dã Man Sinh Trưởng)', 'Wild Bloom', 'https://phimimg.com/upload/vod/20240509-1/afec2dfeef6715a53412533f7db06020.jpg', 'https://phimimg.com/upload/vod/20240509-1/3df28d06da9b13837d5c76af8f8b018e.jpg', '<p>Gió Thổi Bán Hạ (Dã Man Sinh Trưởng) kể về câu chuyện khi mẹ của Hứa Bán Hạ đã mất vì khó sinh, từ khi cô sinh ra người cha cũng chẳng hề quan tâm cô. Vì thế cô trở thành một cô gái kiêu ngạo đầy cá tính. Với sự phát triển nhanh chóng của kinh tế Trung Quốc, Hứa Bán Hạ đã dẫn dắt 2 người bạn cùng khởi nghiệp kinh doanh thép phế liệu và vận tải. Trong ngành công nghiệp thép do nam giới thống trị, Hứa Bán Hạ thể hiện tinh thần mạo hiểm và thái độ thực dụng, sau đó dũng cảm dấn thân lăn lộn. Sau khi trải qua vô số khó khăn và thậm chí là thử thách sinh tử, cô đã mở một doanh nghiệp nhập khẩu thép quốc tế độc lập và thu hoạch thành quả đầu tiên trong công việc kinh doanh của mình. Lúc này, sự cạnh tranh trên thị trường thép rất gay gắt. Với tầm nhìn xuất chúng, tính cách táo bạo và nhạy bén với thị trường, Hứa Bán Hạ đã vượt qua mọi khó khăn và từng bước mở rộng địa bàn kinh doanh của mình. Thông qua những trải nghiệm trong cuộc sống, tình yêu và công việc, Hứa Bán Hạ học cách giải quyết vấn đề một cách dứt khoát, vượt qua giới hạn của bản thân để có được sự nghiệp và tình yêu.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 4, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Âu Hào","avatar":""},{"name":"Li Guang Jie","avatar":""},{"name":"LiuWei","avatar":""},{"name":"Michelle","avatar":""},{"name":"Nhiệm Trọng","avatar":""},{"name":"Wang Jin Song","avatar":""},{"name":"Vivienne Liu","avatar":""},{"name":"Sun Qian","avatar":""},{"name":"Bill","avatar":""},{"name":"Shi An","avatar":""},{"name":"Sissi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324269);
