INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-phuc-thuy-thu-cua-akebi', 'Đồng Phục Thủy Thủ Của Akebi', 'Akebi''s Sailor Uniform, Akebi-chan No Sailor Fuku', 'https://phimimg.com/upload/vod/20240509-1/c96d581f1e9d961912d46772ef20b022.jpg', 'https://phimimg.com/upload/vod/20240509-1/bfac2b0971804796c64618d266a6cb40.jpg', '<p>Akebi Komichi sống ở vùng nông thôn cùng gia đình. Cô ấy đã trúng tuyển vào trường trung học cơ sở Học viện Roubai danh tiếng dành cho nữ sinh và giờ cô ấy chỉ muốn hai điều — mặc đồng phục thủy thủ của trường và kết bạn với hàng trăm người!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 18, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324269);
