INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-hang-nhat', 'Cuộc Sống Hạng Nhất', 'First Class', 'https://phimimg.com/upload/vod/20240509-1/01d6b6ff54464c926f3bac1ee309c1d3.jpg', 'https://phimimg.com/upload/vod/20240509-1/da1b622f7b5f6e9e79d040e05554760f.jpg', '<p>Họ có chung niềm yêu thích thời trang khoa trương, những bữa tiệc sang trọng và sự kiện độc quyền. Hãy khám phá cuộc sống của nhóm bạn này ở Barcelona.</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 12, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
