INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-bong-toi-2022', 'Vượt Qua Bóng Tối', 'Through The Darkness', 'https://phimimg.com/upload/vod/20240509-1/440621c87b07801ab309c6caaf4d2b4e.jpg', 'https://phimimg.com/upload/vod/20240509-1/168973ec15df2b442637c27d5b2e5675.jpg', '<p>Vượt Qua Bóng Tối - Through the Darkness kể về câu chuyện của những người đấu tranh ngày đêm để đọc được suy nghĩ của những kẻ giết người. Dựa trên cuốn sách cùng tên do Kwon II Yong và Go Na Wo đồng chắp bút, bộ phim sẽ xoay quanh câu chuyện của Kwong II Yong. Anh trở thành cảnh sát năm 1989 và đã trở thành profiler đầu tiên người Hàn Quốc, chuyên săn đuổi những tên giết người hàng loạt. Kwong II Yong đã tham gia vào các vụ án liên quan đến những tên tội phạm khét tiếng như Yoo Young Chul và Young Nam Gyu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Nam Gil","avatar":""},{"name":"Kim So-Jin","avatar":""},{"name":"Jin Seon Kyu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
