INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gang-phan-3', 'Cố Gắng (Phần 3)', 'Trying (Season 3)', 'https://phimimg.com/upload/vod/20240509-1/e9089785b4d599b42ad92e676fa22d8b.jpg', 'https://phimimg.com/upload/vod/20240509-1/d3387032b3d7de458bea13cdfdf43e97.jpg', '<p>Phần ba bắt đầu với Nikki và Jason thức dậy với tư cách là cha mẹ mới của hai đứa trẻ mà họ vẫn đang làm quen. Bây giờ họ chỉ cần giữ chúng, điều này chứng tỏ là phức tạp hơn họ nghĩ ban đầu. Bị ném thẳng vào vực sâu của cha mẹ, mối quan hệ của Nikki và Jason với nhau cũng như với những người thân yêu và gần gũi nhất của họ được thử thách khi họ cố gắng vượt qua những thăng trầm của việc nuôi dạy con cái một cách tuyệt vọng - trong khi vẫn bám lấy con cái và sự tỉnh táo của chúng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Rafe Spall","avatar":""},{"name":"Esther Smith","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Ophelia Lovibond","avatar":""},{"name":"Oliver Chris","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324269);
