INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-tuoi-tre', 'Vũ Điệu Tuổi Trẻ', 'Cheer Up', 'https://phimimg.com/upload/vod/20240509-1/e67ab3416bc4e6e39c5b5b40dd0cd0c8.jpg', 'https://phimimg.com/upload/vod/20240509-1/9f6add83e45f05404f02bb600c14619e.jpg', '<p>Do Hae Yi sáng sủa và siêng năng, đang là sinh viên Đại học Yeonhee. Vì tình hình tài chính không tốt của gia đình, cô ấy ưu tiên kiếm tiền hơn là đi học.<br/>Một ngày nọ, Do Hae Yi bất ngờ gia nhập đội cổ vũ Teyia đã tồn tại 50 năm tại Đại học Yeonhee. Cô ấy chỉ tham gia câu lạc bộ vì tiền, nhưng trong khi tham gia vào đội cổ vũ, Do Hae Yi bắt đầu trải nghiệm niềm vui của cuộc sống trong khuôn viên trường và gặp gỡ nhiều người khác nhau từ Teyia bao gồm Bae Young Woong, người từng là thành viên của Teyia và anh ấy là cựu sinh viên của Yeonhee Univers, hỗ trợ đội cổ vũ về mặt tài chính và tình cảm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Ji Hyun","avatar":""},{"name":"Bae In Hyuk","avatar":""},{"name":"Kim Hyun Jin","avatar":""},{"name":"Jang Gyu Ri","avatar":""},{"name":"Lee Min Jae","avatar":""},{"name":"Lee Eun Saem","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
