INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-blouse-trang-2', 'Người Hùng Blouse Trắng 2', 'Big White Duel 2', 'https://phimimg.com/upload/vod/20240509-1/1aa29067449b681d710700a9408168c2.jpg', 'https://phimimg.com/upload/vod/20240509-1/b807fee6d259eaaff3fa044705ee8aaf.jpg', '<p>Dù đối chọi nhau trên phương diện tình cảm hay công việc, mục đích chung của các bác sĩ vẫn là cứu người. Đứng trước ranh giới mỏng manh giữa sự sống và cái chết, họ phải bỏ qua mọi mâu thuẫn, cùng bắt tay viết lên những kỳ tích trong ngành y.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Quách Tấn An","avatar":""},{"name":"Mã Quốc Minh","avatar":""},{"name":"Hồ Định Hân","avatar":""},{"name":"Trần Hào","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
