INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-cung-cung-den-luot-toi-yeu', 'Cuối Cùng Cũng Đến Lượt Tôi Yêu', 'Time To Fall In Love', 'https://phimimg.com/upload/vod/20240509-1/ddaf883c23a5caa4a3f5a798335493a4.jpg', 'https://phimimg.com/upload/vod/20240509-1/2d0e73c7e89b820e35acfe1b4dc49e8e.jpg', '<p>Cuối Cùng Cũng Đến Lượt Tôi Yêu kể về câu chuyện của cô nàng Tô Nhan Hề, là người có tính cách lạc quan và mạnh mẽ, có sự nghiệp riêng, một mình chăm sóc người mẹ bệnh nặng. Cũng giống như những người trẻ chăm chỉ khác, cô ấy rất tự lập, và sự lương thiện tốt bụng ấm áp của cô cũng đã truyền cảm hứng năng lượng cho những người xung quanh. Trong khi đó, Cố Tây Thành là người hành động quyết đoán trong sự nghiệp, theo đuổi ước mơ bằng chính năng lực của mình. Tô Nhan Hề bị chị gái song sinh Hạ Cẩm Hề uy hiếp, bắt buộc trở thành bạn gái hợp đồng tổng tài hào môn Cố Tây Thành. Cố Tây Thành vốn muốn giả vờ yêu đương để dỗ ngọt bà nội bị bệnh, nhưng dần bị cô gái Tô Nhan Hề lạc quan vui vẻ này thu hút, hai người sống chung một mái nhà cũng dần tình cảm cũng dần ấm áp. Dưới sự quan tâm tinh tế của Tô Nhan Hề, Cố Tây Thành từng bước tháo xuống vỏ bọc nóng nảy vô tình của mình, lộ ra nội tâm mềm mại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lin Xin Yi","avatar":""},{"name":"La Chính","avatar":""},{"name":"Yang Ze","avatar":""},{"name":"Zhang Yao","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
