INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ro-bot-biet-tuot-gio-giai-dap', 'Rô Bốt Biết Tuốt: Giờ Giải Đáp', 'StoryBots: Answer Time', 'https://phimimg.com/upload/vod/20240509-1/a96aeba1417750f138fe850a9e9e4f86.jpg', 'https://phimimg.com/upload/vod/20240509-1/95cd54a09921c07ed0e6a3711ab4515b.jpg', '<p>Bạn có câu hỏi? Rô bốt biết tuốt có câu trả lời! Hãy tham gia cùng hội bạn tò mò Beep, Boop, Bing, Bang và Bo trong cuộc phiêu lưu thú vị để tìm ra sự thật cho các bạn nhỏ như bạn.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Judy Greer","avatar":""},{"name":"Jeff Gill","avatar":""},{"name":"Nate Theis","avatar":""},{"name":"Erin Fitzgerald","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Evan Spiridellis","avatar":""},{"name":"Patton Oswalt","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
