INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ro-bot-biet-tuot-gio-giai-dap', 'Rô Bốt Biết Tuốt: Giờ Giải Đáp', 'StoryBots: Answer Time', 'rô bốt biết tuốt: giờ giải đáp storybots: answer time judy greer jeff gill nate theis erin fitzgerald fred tatasciore evan spiridellis patton oswalt ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-minh-cua-phu-thuy', 'Bình Minh Của Phù Thủy', 'Mahoutsukai Reimeiki, The Dawn Of The Witch', 'https://phimimg.com/upload/vod/20240509-1/da884b681c68b50dcbdd562ea5e147ba.jpg', 'https://phimimg.com/upload/vod/20240509-1/07593eab4897d531958b32208f6c962e.jpg', '<p>Sable, một học sinh của Trường Ma pháp bị mất hết ký ức trước khi nhập học. Cậu ấy phải trải qua một cuộc sống học đường rỗng tuếch, không biết lý do vì sao bản thân mình lại ở đây và cứ thế mà sa sút vì chẳng có động lực nào để học. Thấy Sable như thế, Albus, hiệu trưởng Trường Ma pháp đã đột ngột tuyên bố sẽ cho cậu ấy tham gia tập huấn đặc biệt đầy mạo hiểm và bảo rằng Hãy cho những kẻ Thợ săn Phù thủy trong vùng thấy ma thuật hữu dụng đến nhường nào. Bởi lẽ, vài năm sau khi cuộc chiến giữa Giáo hội và Phù thủy kết thúc, thế giới vẫn chưa hoàn toàn chấp nhận phù thủy và ma thuật. Và lúc này chính là thời điểm khởi đầu của phù thủy. Đây là câu chuyện kể về một chàng thiếu niên tìm lại chính mình cùng những người bạn luôn che giấu những vết thương trong thâm tâm.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
