INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-cuphead-phan-3', 'Anh Em Cuphead (Phần 3)', 'The Cuphead Show! (Season 3)', 'https://phimimg.com/upload/vod/20240509-1/221dc586604dc6b8334f3bf60f5bc4bf.jpg', 'https://phimimg.com/upload/vod/20240509-1/82d221e43b55eaa9416f36a9b7389fa3.jpg', '<p>Từ những trò tai quái và nỗi sợ tột cùng cho đến màn ăn mừng dịp lễ: mùa này có tất cả khi các cậu nhóc dám táo tợn lừa Ác quỷ cũng như khuấy động rắc rối khắp thị trấn!</p>', 'Full', 11, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tru Valentino","avatar":""},{"name":"Frank Todaro","avatar":""},{"name":"Wayne Brady","avatar":""},{"name":"Joe Hanna","avatar":""},{"name":"Luke Millington-Drake","avatar":""},{"name":"Grey Griffin","avatar":""},{"name":"Cosmo Segurson","avatar":""},{"name":"Dave Wasson","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
