INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-nguoi-dung-cam', 'Gửi Người Dũng Cảm', 'To Be A Brave One', 'https://phimimg.com/upload/vod/20240509-1/d7604a80e8f423ea22b645b3ff8565fa.jpg', 'https://phimimg.com/upload/vod/20240509-1/cf40b9c4ec4e6c9ab766659ae63d9ecd.jpg', '<p>Bộ phim Gửi Người Dũng Cảm do Quan Hồng và Đặng Gia Giai đóng chính có nội dung kể về chuyện tình lệch tuổi giữa An Dư – chủ tịch tập đoàn Hảo Vật và anh chàng trẻ tuổi Thiệu Mặc Ly. An Dư rơi vào hôn mê suốt hai năm trời do một tai nạn xe, sau khi tỉnh dậy cô phải đối mặt với sự phản bội của người mình yêu và những trắc trở trong sự nghiệp. Bị hiện thực tát thẳng vào mặt, An Dư không cam tâm thất bại mà nhanh chóng vực dậy. Phát hiện giữa mình và Thiệu Mặc Ly có nhiều ý tưởng giống nhau, An Dư quyết định cùng chàng thanh niên trẻ này gầy dựng lại sự nghiệp. Trải qua nhiều thăng trầm, cuối cùng An Dư và Thiệu Mặc Ly cũng nhận ra tình cảm dành cho nhau.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Quan Hồng","avatar":""},{"name":"Đặng Gia Giai","avatar":""},{"name":"Lưu Ân Hữu","avatar":""},{"name":"Trần Diễm Thiến","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
