INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-cua-thoi-gian', 'Câu Chuyện Của Thời Gian', 'The Old Dreams', 'https://phimimg.com/upload/vod/20240509-1/caf0b8057a7246edabd2aca203213c00.jpg', 'https://phimimg.com/upload/vod/20240509-1/aa2741d9408035a6c2956eac68ed281d.jpg', '<p>Câu Chuyện Của Thời Gian lấy bối cảnh thanh đảo từ những năm 90 đến đầu năm 2000, bộ phim kể về những thăng trầm của Trần Nhất Đóa và những người bạn đồng hành trọng tình trong tòa nhà đồng hành Tất Lai Phúc của Trần gia, miêu tả một nhóm thanh niên nhiệt huyết của những năm 90 lớn lên trong thời đại thay đổi, không phụ tuổi trẻ, theo đuổi một cuộc sống tốt đẹp hơn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jelly Lin","avatar":""},{"name":"Gao Zhi Ting","avatar":""},{"name":"Ge Zheng","avatar":""},{"name":"He Peng","avatar":""},{"name":"Liu Yu Feng","avatar":""},{"name":"Lý Nhược Ninh","avatar":""},{"name":"Li Hong Tao","avatar":""},{"name":"Wang Hai Yan","avatar":""},{"name":"Bao Da Zhi","avatar":""},{"name":"Zhang Tao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324269);
