INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kieu-the-nha-ta-khong-de-choc', 'Kiều Thê Nhà Ta Không Dễ Chọc', 'Afterlife Of Love And Revenge', 'https://phimimg.com/upload/vod/20240509-1/1f844da8335b4956f7c39d0520136586.jpg', 'https://phimimg.com/upload/vod/20240509-1/99755c39d876145114a81664cced3709.jpg', '<p>Người phụ nữ chua ngoa nhất huyện Thanh Thủy - Lung Nguyệt - tính tình đanh đá hung dữ, bảo vệ chồng như mạng sống của mình. Trước khi được sống lại lần nữa, Lung Nguyệt bị hãm hại, bỏ rơi, chỉ có Lý Thanh Mục đối xử với nàng chân thành nhưng lại vẫn bị xúi giục hòa ly, ôm hận mà chết. Kiếp này, Lung Nguyệt quyết định, đã có được cơ hội sống lại, nàng nhất định phải trân trọng người mình yêu, khiến những kẻ từng sỉ nhục, bỏ rơi nàng phải trả giá.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ma Qianqian","avatar":""},{"name":"Xu Nuoyan","avatar":""},{"name":"Xu Gang","avatar":""},{"name":"Suo Fei","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324269);
