INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khai-huyen-thoi-co-dai', 'Khải Huyền Thời Cổ Đại', 'Ancient Apocalypse', 'https://phimimg.com/upload/vod/20240509-1/1d78fde44850b9c559599be3f3945909.jpg', 'https://phimimg.com/upload/vod/20240509-1/f96682d961b39eac39033348ed44c182.jpg', '<p>Nhà báo Graham Hancock chu du khắp thế giới, săn tìm bằng chứng về những nền văn minh đã mất đầy bí ẩn kể từ Kỷ băng hà cuối cùng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Graham Hancock","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324269);
