INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-than-tuong', 'Bóng Ma Thần Tượng', 'Kami Kuzu☆Idol Phantom Of The Idol', 'https://phimimg.com/upload/vod/20240509-1/1af6cd24eefe53816831f133ca21e621.jpg', 'https://phimimg.com/upload/vod/20240509-1/30bb618dc42edcad7e78ca997a363461.jpg', '<p>Yuya là một thành viên trong nhóm nhạc đôi ZINGS. Cậu là một ca sĩ lười chưa từng thấy trong cái ngành công nghiệp giải trí này. Trong lúc cộng sự của mình đang cố gắng 110% mỗi đêm và trở nên nổi tiếng thì Yuya lại thể hiện những màn trình diễn kém cỏi và thái độ độc hại với khán giả, khiến người quản lý phải tìm mọi lý do để gỡ gạc cho cậu. Con đường để trở thành thần tượng dường như không êm đềm và màu hồng như cậu nghĩ. Sau một đêm trình diễn thiếu sức sống, Yuya đã gặp một cô gái sau cánh gà. Cô ấy diện một bộ đồ sắc sỡ, tràn đầy nhiệt huyêt để trình diễn, chỉ có một vấn dề là... cô ấy đã chết từ 1 năm trước. Đó chính là hồn ma của Asahi Mogami, người đã không còn cơ hội trình diễn trên sân khấu. Nếu như hồn ma là có thật thì nhập hồn cũng đâu phải là bất khả thi nhỉ?</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324269);
