INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-lang-dinh', 'Hồi Lang Đình', 'The Murder In Kairoutei', 'https://phimimg.com/upload/vod/20240509-1/6c735d84c01c086d24b3d48cdf572f10.jpg', 'https://phimimg.com/upload/vod/20240509-1/b4245d619efee9cf36519661dbacabc8.jpg', '<p>Phim chuyển thể từ tiểu thuyết Nhật Bản Vụ Án Mạng Ở Lữ Quán Kairotei (Kairōtei Satsujin Jiken) của tác giả Keigo Higashino. Câu chuyện bắt đầu từ hành lang của một khu trọ, giữa đêm vắng đột ngột xảy ra hỏa hoạn. Một người đàn ông vùi thân nơi biển lửa, các nhà chức trách không tìm ra nguyên nhân đằng sau. Khương Viễn Tinh bị bỏng nặng dẫn đến dung mạo bị hủy hoại. Giữa giây phút tuyệt vọng đó Trình Thành xuất hiện như tia sáng cuối con đường trong cuộc đời của Viễn Tinh. Vận mạng của hai người cũng dính vào nhau và hoàn toàn thay đổi từ sau vụ hỏa hoạn đó.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Tân Thành","avatar":""},{"name":"Đặng Gia Giai","avatar":""},{"name":"Thiệu Binh","avatar":""},{"name":"Lương Ái Kì","avatar":""},{"name":"Vương Diễm","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
