INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-quy-ong-moi-dung-nghiem', 'Các Quý Ông, Mời Đứng Nghiêm', 'Gentlemen Attention Please', 'https://phimimg.com/upload/vod/20240509-1/187070641da1e46b717dcbdd655f8992.jpg', 'https://phimimg.com/upload/vod/20240509-1/f1825c5f0ace56206abeff2095483c6b.jpg', '<p>Các Quý Ông, Mời Đứng Nghiêm - Gentlemen Attention Please lấy cột mốc năm 2020, lúc này nhóm bạn chí cốt từ thuở đại học gồm 4 anh chàng thế hệ thập niên 80 đang bước vào giai đoạn khủng hoảng của sự nghiệp. Đây sẽ là cuộc hành trình đầy gian nan và khó khăn, dàn nhân vật bước qua hàng vạn rắc rối từ chuyện tình, chuyện đời để đạt được bến bờ bình yên ở độ tuổi chạm ngõ hàng 4.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Hàn","avatar":""},{"name":"Đỗ Thuần","avatar":""},{"name":"Kinh Siêu","avatar":""},{"name":"Vương Hiểu Thần","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
