INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-ma', 'Bác Sĩ Ma', 'Ghost Doctor', 'https://phimimg.com/upload/vod/20240509-1/b5b37687a9e6b2e98fcd0962eab7589c.jpg', 'https://phimimg.com/upload/vod/20240509-1/476cfc7a5cb502a82e6680a5466832b2.jpg', '<p>Bộ phim Bác Sĩ Ma (Ghost Doctor) kể về câu chuyện của hai bác sĩ khác hẳn nhau về cuộc sống, cá tính và tính tình. Cả linh hồn lẫn thân thể của họ bất ngờ kết hợp lại và họ trở thành bác sĩ âm hồn không rời khỏi bệnh viện cũng như bệnh nhân nổi sau khi qua đời. Phim có sự tham gia của hai nam thần điện ảnh Hàn - Bi Rain và Kim Bum.\n\nTrong phim, Go Seung Tak (Kim Bum đóng) là một chàng trai vô cùng thông minh, xuất thân từ gia đình tài phiệt. Sinh ra trong một gia đình có điều kiện nên Go Seung Tak sở hữu cho mình rất nhiều ưu điểm. Anh hiện đang là bác sĩ nội trú may mắn nhất khi có ông nội là người sáng lập bệnh viện Myung-Shin và mẹ là chủ tịch bệnh viện.\n\nMột ngày nọ, Seung Tak vô tình vướng vào bác sĩ phẫu thuật lồng ngực thiên tài Cha Young Min (Bi Rain thủ vai), là một bác sĩ thiên tài, với kỹ năng phẫu thuật xuất sắc, nhưng anh lại ích kỷ và kiêu ngạo. Và rồi chẳng may, linh hồn của Young Min chiếm hữu cơ thể của một bác sĩ khác sau một vụ án bất ngờ, đó là Seong Tak. Từ đây, hàng loạt tình huống dở khóc dở cười sẽ xảy đến với bộ đôi bác sĩ ma tài năng này.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Bum","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324269);
