INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-goi-toi-la-tong-giam-doc', 'Hãy Gọi Tôi Là Tổng Giám Đốc', 'Master Of My Own', 'https://phimimg.com/upload/vod/20240509-1/aa2b166213e19aa097d7732cf4b432d5.jpg', 'https://phimimg.com/upload/vod/20240509-1/c1745ce67d85889cac53ee7a1f04b134.jpg', '<p>Chuyện phim Xin Gọi Tôi Là Tổng Giám bắt đầu từ câu chuyện về một người khất phục người kia theo sau ông chủ “T-Rex” và “người huấn luyện động vật” của anh ta. Ninh Mông (Đàm Tùng Vận thủ vai), người luôn mơ ước được tiến lên các nấc thang của công ty để trở thành giám đốc, nhưng sếp của cô ấy không nghĩ rằng cô ấy có những gì cần thiết để thành công trong thế giới đầu tư. Chính vì cả hai thường xuyên “khắc khẩu” nên không ngại “đấu nhau” khắp nơi trong mọi công việc.Ninh Mông dường như tiếp tục rời xa ước mơ của mình kể từ khi tốt nghiệp. Sếp của cô, Lục Ký Minh (Lâm Canh Tâm đóng) từ lâu đã chứng minh năng lực kinh doanh của mình trong các khoản đầu tư với tư cách là chủ tịch một công ty. Lục Ký Minh không tin rằng Ninh Mông có thể trở thành một nhà đầu tư đủ năng lực.Chuyện tình Xin Gọi Tôi Là Tổng Giám chỉ thực sự xảy ra khi Ninh Mông quyết định rời khỏi Lục Ký Minh một lần và mãi mãi để cho anh ấy và bản thân thấy rằng cô ấy có thể tự mình thành công. Ninh Mông đi tìm việc và sau nhiều lần thất bại, cô đã tìm được việc làm tại Eagle Stone Investment để bắt đầu lại.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
