INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-y-dai-nhan-cho-gheo-ta', 'Thần Y Đại Nhân Chớ Ghẹo Ta', 'My Fairy Doctor', 'https://phimimg.com/upload/vod/20240509-1/16c50f54c9f8ba33550683903d88fd44.jpg', 'https://phimimg.com/upload/vod/20240509-1/3545c271e8002df22debf5049ed259f6.jpg', '<p>Đường Kỷ Tử con gái Trung y thế gia tình cờ cứu được thần y đời Đường bị giam trong tranh, vì chiếc vòng tay cô đeo từ bé có liên kết với ngọc bội của người đó mà hai người bị trói buộc phải ở gần nhau trong vòng một trượng, cuộc sống chung đụng thân mật cũng bắt đầu từ đây. Trong quá trình nỗ lực thích ứng cuộc sống hiện đại, thần y Đường Cần Giản cũng tự thân dạy dỗ Đường Kỷ Tử trở thành một bác sĩ trung y ưu tú.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Di Hinh","avatar":""},{"name":"Chu Mân Hân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324269);
