INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sago-mini-friends', 'Sago Mini Friends', 'Sago Mini Friends', 'https://phimimg.com/upload/vod/20240509-1/65f78ba3ac108ac4925fc2e51f9d5a82.jpg', 'https://phimimg.com/upload/vod/20240509-1/a7565b31a4ab226b9bc27f73ab9c733e.jpg', '<p>Chào mừng bạn đến với Sagoville, nơi Harvey thích vui chơi và khám phá những cách để tận hưởng niềm vui ngớ ngẩn! Anh ấy và những người bạn thân nhất của mình khám phá, tưởng tượng và bày tỏ lòng biết ơn thực sự đối với mọi thứ, dù lớn hay nhỏ, thông qua những cuộc phiêu lưu sáng tạo và những bài hát khó quên.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 11, 2022, 'Lồng Tiếng', 'HD', 'Âu Mỹ', 0, '[{"name":"Ian Ho","avatar":""},{"name":"Claire Poon","avatar":""},{"name":"Liam McKenna","avatar":""},{"name":"Christina Churchill","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
