INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pham-vi-ben-ngoai', 'Phạm Vi Bên Ngoài', 'Outer Range', 'https://phimimg.com/upload/vod/20240524-1/7560ca38ac5c9b4e0621e1812431b18e.jpg', 'https://phimimg.com/upload/vod/20240524-1/dd7c32c7711cd635881c8082d7b77a2b.jpg', '<p>Outer Range là một bộ phim truyền hình khoa học viễn tưởng tân viễn Tây kể về một chủ trang trại ở Wyoming, người phát hiện ra một lỗ đen bí ẩn trên vùng đất của mình và hậu quả của việc lộn xộn với nó.&nbsp;</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Josh Brolin","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Tom Pelphrey","avatar":""},{"name":"Tamara Podemski","avatar":""},{"name":"Will Patton","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
