INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-chien-dao-hansan-rong-troi-day', 'Thủy Chiến Đảo Hansan: Rồng Trỗi Dậy', 'Hansan: Rising Dragon', 'https://phimimg.com/upload/vod/20240518-1/9f737d4254b04d6e5e9788b97d74acad.jpg', 'https://phimimg.com/upload/vod/20240518-1/591d85b29989d2abbb7ff4f216141d0d.jpg', '<p>Tiếp nối thành công của bom tấn sử thi The Admiral: Roaring Currents (Đại Thủy Chiến) khuynh đảo phòng vé Hàn Quốc vào năm 2014, đạo diễn Kim Han Min đã sẵn sàng để trở lại với phần phim tiếp theo về Đại Đô Đốc thủy quân nổi danh của bán đảo Triều Tiên, Yi Sun Shin bất bại. Thủy Chiến Đảo Hansan: Rồng Trỗi Dậy (Hansan: Rising Dragon) sẽ là một câu chuyện diễn ra trước trận đánh nổi danh ở Myeongnyang, trận chiến ở Hansan là nơi mà cái tên Yi Sun Shin đã gieo rắc sự sợ hãi vào tâm trí của thủy quân Nhật, đặc biệt bằng thuyền đầu rùa (Quy bối thuyền) lừng danh.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"박해일","avatar":""},{"name":"변요한","avatar":""},{"name":"안성기","avatar":""},{"name":"손현주","avatar":""},{"name":"김성규","avatar":""},{"name":"김성균","avatar":""},{"name":"김향기","avatar":""},{"name":"옥택연","avatar":""},{"name":"공명","avatar":""},{"name":"박지환","avatar":""},{"name":"조재윤","avatar":""},{"name":"윤제문","avatar":""},{"name":"박훈","avatar":""},{"name":"Park Jae-min","avatar":""},{"name":"Lee Seo-jun","avatar":""},{"name":"Kim Jae-young","avatar":""},{"name":"Yoon Jin-young","avatar":""},{"name":"Kim Kang-il","avatar":""},{"name":"이준혁","avatar":""},{"name":"김민재","avatar":""},{"name":"Kim Koo-taek","avatar":""},{"name":"Son Kyoung-won","avatar":""},{"name":"안성봉","avatar":""},{"name":"Lee Woon-san","avatar":""},{"name":"김명곤","avatar":""},{"name":"김영웅","avatar":""},{"name":"공정환","avatar":""},{"name":"배현성","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Jung Ye-hun","avatar":""},{"name":"김한민","avatar":""},{"name":"Jung Je-w","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324269);
