INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hau-gai-toi-moi-thue-gan-day-that-dang-ngo', 'Cô Hầu Gái Tôi Mới Thuê Gần Đây Thật Đáng Ngờ', 'The Maid I Hired Recently Is Mysterious', 'https://phimimg.com/upload/vod/20240419-1/1d561ffc980a060935cf71f5965c6aa4.jpg', 'https://phimimg.com/upload/vod/20240419-1/df7e1e5f7f282118beb2d44b648b9dfe.jpg', '<p>Cô hầu gái xinh đẹp Lilith gần đây đã được thuê để trông nom cậu chủ nhỏ Yuuri. Tuy nhiên, Yuuri luôn nghĩ rằng cô là một người rất chi là đáng ngờ, và rằng cô đang có âm mưu đen tối nào đó sau lưng cậu. Trước sự mê sảng của cậu chủ nhỏ, Lilith sẽ phản ứng thế nào đây?</p>', 'Full', 11, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324269);
