INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jashin-phi-cuoc-x-mua-3', 'Jashin Phi Cước X (Mùa 3)', 'Dropkick On My Devil!! X Jashin-chan Dropkick (Season 3)', 'https://phimimg.com/upload/vod/20240419-1/ed63ca5eca08e7ff4aaa3a63ad3d9e27.jpg', 'https://phimimg.com/upload/vod/20240419-1/a99d2fd3b93dd42c73471040b8f31abc.jpg', '<p>Ác quỷ của Ma Giới, tên thường gọi là Jashin. Một ngày nọ, Jashin bất ngờ bị triệu hồi đến Nhân Giới, và người triệu hồi là Hanazono Yurine, cô gái với tâm hồn có chút đen tối sống trong một căn trọ tồi tàn ở Jinbocho. Tuy nhiên, Yurine lại không biết cách đưa Jashin trở về Ma Giới. Không còn cách nào khác, cả hai bắt đầu sống chung với nhau. Và rồi Jashin nói rằng Có thể về Ma Giới nếu người triệu hồi chết đi. Jashin sẽ hành động ra sao?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
