INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liem-chinh-truy-kich', 'Liêm Chính Truy Kích', 'Mission Run', 'https://phimimg.com/upload/vod/20240419-1/5a4de266ebd0bde8bcfe3248d3f89337.jpg', 'https://phimimg.com/upload/vod/20240419-1/d2bc89b143b03e81683fa1b12a2858e7.jpg', '<p>Lạc Tử Phong (Huỳnh Tông Trạch đóng) - Tổng Chủ nhiệm điều tra của Sở Liêm Chính có dịp hợp tác với Vi Kế Minh (Vương Hạo Tín đóng) - Thanh tra cao cấp của Cục Điều tra tội phạm có tổ chức và xã hội đen, khi cùng điều tra một vụ án mà nạn nhân là ba nuôi của Phương Gia Tình (Huỳnh Trí Văn đóng). Gia Tình là ca sĩ phòng trà. Sau biến cố đó, Phong và Minh giúp cuộc sống của Tình ổn định trở lại. Ba người họ cũng gặp lại Trác Dĩ Phàm (Ngô Trác Hy đóng). Công việc luật sư khiến Phàm nhiều lần chạm trán Phong và Minh.

Phương thức, thủ đoạn hoạt động của các cá nhân, tổ chức phạm tội ngày càng tinh vi, xảo quyệt. Quá trình điều tra, Phong và Minh nhận thấy nhiều vụ án dính líu đến thương gia Trác Đình Quang (Huỳnh Trí Hiền đóng). Oái ăm, ông lại là người thân của Phàm.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 9, 2022, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Bosco Wong","avatar":""},{"name":"Ron Ng","avatar":""},{"name":"Vincent Wong","avatar":""},{"name":"Sisley Choi","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Nancy Wu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
