INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-cracow', 'Quái Vật Cracow', 'Cracow Monsters', 'https://phimimg.com/upload/vod/20240419-1/847616e8bdf5e353f89cb58e8b5b18d4.jpg', 'https://phimimg.com/upload/vod/20240419-1/4411d8c5c156251315ce8898395b06f9.jpg', '<p>Bị ám ảnh với quá khứ, một phụ nữ trẻ nhập hội cùng vị giáo sư bí ẩn và nhóm sinh viên tài năng khi họ điều tra hiện tượng siêu nhiên – và chiến đấu với ác quỷ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Barbara Liberek","avatar":""},{"name":"Stach Linowski","avatar":""},{"name":"Andrzej Chyra","avatar":""},{"name":"Małgorzata Bela-Pawlikowska","avatar":""},{"name":"Anna Paliga","avatar":""},{"name":"Daniel Namiotko","avatar":""},{"name":"Mateusz Górski","avatar":""},{"name":"Małgorzata Gorol","avatar":""},{"name":"Maja Chan","avatar":""},{"name":"Kaja Chan","avatar":""},{"name":"Stanisław Cywka","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324269);
