INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-thoi-hien-dai-amsterdam', 'Tình Yêu Thời Hiện Đại Amsterdam', 'Modern Love Amsterdam', 'https://phimimg.com/upload/vod/20240419-1/48f1d0ac98f2bb5682e6c5f17df506ec.jpg', 'https://phimimg.com/upload/vod/20240419-1/e9f248968b3725727d259a7c62f9fdf4.jpg', '<p>Theo dõi sáu câu chuyện về tình yêu và cách tình yêu luôn chiến thắng khi đối mặt với những thử thách và tình huống khó khăn trong cuộc sống. Từ việc hiện thực hóa mong muốn có con đến đấu tranh với những thách thức của một mối quan hệ mở. Từ thương tiếc cho một tình yêu đã mất trong quá khứ đến chấp nhận tình yêu mới và thích nghi với tương lai. Tình yêu, dưới mọi hình thức, là phổ quát.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 13, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fedja van Huêt","avatar":""},{"name":"Jack Wouterser","avatar":""},{"name":"Rifka Lodeizen","avatar":""},{"name":"Eva van de Wijdeven","avatar":""},{"name":"Arjan Ederveen","avatar":""},{"name":"Hanna van Vliet","avatar":""},{"name":"Hannah Hoekstra","avatar":""},{"name":"Yootha Wong-Loi-Sing","avatar":""},{"name":"Jonas Smulders","avatar":""},{"name":"Werner Kolf","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
