INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-ngo-ngao-lo-lem', 'Công Chúa Ngổ Ngáo: Lọ Lem', 'My Sassy Princess: Cinderella', 'https://phimimg.com/upload/vod/20240419-1/53bb896a35015a1e87b35e4fc011bd23.jpg', 'https://phimimg.com/upload/vod/20240419-1/8991e68e31eb05c9f5845d99d387e3e2.jpg', '<p>Một câu chuyện Lọ lem hiện đại khác xa với phiên bản cổ tích. Nàng Lọ lem không hề nhờ đến sự giúp đỡ của bà Tiên để biến điều ước thành hiện thực. Dù cuộc sống khó khăn, thiếu thốn nhưng cô sẽ tự tìm ra con đường cho mình. Lọ lem thay đổi ngoại hình, đi dép thủy tinh và bắt đầu theo đuổi trái tim của “hoàng tử”. Liệu sự chủ động này có mang đến cho Lọ lem một cái kết như trong truyện cổ tích?</p>', 'Hoàn Tất (8/8)', 10, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Bank Thiti Mahayotaruk","avatar":""},{"name":"Earnearn Fatima Dechawaleekul","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324269);
