INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-hinh-tro-ly-nho-lai-gay-chuyen', 'Cậu Hình, Trợ Lý Nhỏ Lại Gây Chuyện', 'My Naughty Assistant', 'https://phimimg.com/upload/vod/20240419-1/5308fc10e81207f698f70a7477ad0cd8.jpg', 'https://phimimg.com/upload/vod/20240419-1/120038e1eafb3f487fc3b3fb0a27bc15.jpg', '<p>Sau khi chính mắt nhìn thấy bạn trai ngoại tình, nữ diễn viên nhỏ Trương Đoá Đoá bất ngờ được minh tinh đang nổi Hình Ân Thần khí phách bảo vệ, cũng bắt đầu yêu đương với nam thần trời sáng này. Hai trái tim dần thu hút nhau, dần đến gần nhau, anh vì cô mà từ bỏ ước mơ cùng danh tiếng, cô vì anh không ngại từ bỏ tình yêu đi tha hương. Sau cùng nhờ sự nỗ lực của cả hai mà họ lại tìm về với nhau.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cảnh Nghiên","avatar":""},{"name":"Châu Tử Nam","avatar":""},{"name":"Giang Đông Húc","avatar":""},{"name":"Hoa Tuệ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
