INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-vien-tay-phan-4', 'Thế Giới Viễn Tây (Phần 4)', 'Westworld (Season 4)', 'https://phimimg.com/upload/vod/20240419-1/76092cf19ffcbbc25cc6de589192ff7c.jpg', 'https://phimimg.com/upload/vod/20240419-1/39d85a6e91f83d69ffa2abb243267f55.jpg', '<p>Một cuộc phiêu lưu đen tối về buổi bình minh của ý thức nhân tạo và sự tiến hóa của tội lỗi. Lấy bối cảnh ở giao điểm của tương lai gần và quá khứ được tưởng tượng lại, phim khám phá một thế giới mà ở đó mọi khẩu vị của con người, bất kể cao quý hay sa đọa, đều có thể được yêu thích.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Evan Rachel Wood","avatar":""},{"name":"Thandiwe Newton","avatar":""},{"name":"Jeffrey Wright","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
