INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-dep-ngay-vui-biet-bao-gio', 'Cảnh Đẹp Ngày Vui Biết Bao Giờ', 'Love In Flames Of War', 'https://phimimg.com/upload/vod/20240419-1/a99a0d67161eefe8f7ba859ed2a38f6d.jpg', 'https://phimimg.com/upload/vod/20240419-1/375f2e404639860418d21a50513e9a96.jpg', '<p>Năm 15 tuổi, Lâm Hàng Cảnh đến nhà bạn của cha là Tiêu đại soái để lánh nạn, đây là lần đầu cô gặp Tiêu Bắc Thần. Sự mạnh mẽ, cá tính của cô đã thu hút Tiêu Bắc Thần, khiến anh phải lòng cô lúc nào không hay. Thế nhưng, hai người họ vẫn mãi hữu duyên nhưng không phận. Trải qua nhiều sóng gió của thời cuộc, bảy năm sau gặp lại nhau, liệu cả hai có cùng viết nên một cái kết viên mãn?</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 8, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Đậu Kiêu","avatar":""},{"name":"Trần Đô Linh","avatar":""},{"name":"Hồ Quân","avatar":""},{"name":"Vương Kính Tùng","avatar":""},{"name":"Viên Hạo","avatar":""},{"name":"Triệu Anh Tử","avatar":""},{"name":"Lại Nghệ","avatar":""},{"name":"Đổng Tuyền","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324269);
