INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-gian-tan-nuong', 'Hoa Gian Tân Nương', 'Believe In Love', 'https://phimimg.com/upload/vod/20240419-1/35271c32ad467eaacc0c869059247ea0.jpg', 'https://phimimg.com/upload/vod/20240419-1/639ebc45fe628d138a2e02d669b4832b.jpg', '<p>Lục Nguyệt Nhi 17 tuổi là chủ tiệm mì Vân Nguyệt. Hoa Diệc Nam có vẻ ngoài anh tuấn nhưng bên trong lại khá đen tối, luôn làm mọi cách để có được thứ mình muốn. Tuy mới có 20 tuổi nhưng Diệc Nam đã được hàng vạn dân chúng sùng bái. Khi gặp gỡ Nguyệt Nhi, chàng luôn bí mật quan tâm chăm sóc nàng, bảo vệ nàng bằng mọi giá. Trải qua nhiều khó khăn sóng gió, cuối cùng ông trời đã an bài cho họ một cái kết viên mãn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trịnh Hợp Huệ Tử","avatar":""},{"name":"Huỳnh Thánh Trì","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
