INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nhac-ben-bo-bien', 'Ban Nhạc Bên Bở Biển', 'The Seaside Band', 'https://phimimg.com/upload/vod/20240419-1/c7d0d6475cfd9e5d0d4a896f8d284910.jpg', 'https://phimimg.com/upload/vod/20240419-1/73522f58e9bfb9d3b207b730806acda5.jpg', '<p>Là chương trình truyền hình thực tế truyền cảm hứng dành cho phụ nữ do Mango TV thực hiện. Trong chương trình, sáu khách mời nữ trên 30 tuổi với chuyên môn âm nhạc và sự hiểu biết đầy đủ của riêng mình sẽ cùng nhau đến một vùng biển. Trong 21 ngày, họ xây dựng và vận hành một nhà hàng âm nhạc bên bờ biển từ hai bàn tay trắng. Họ cũng sẽ khám phá mối quan hệ giữa công việc và cuộc sống trong quá trình hoạt động.quan hệ, truyền tải quan điểm sống “làm việc chăm chỉ và sống tốt”.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 13, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324269);
