INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tai-co-ban-phap', 'Thiên Tài Cơ Bản Pháp', 'The Heart Of Genius', 'https://phimimg.com/upload/vod/20240419-1/9381f7100b7f2be34551c25e1037da75.jpg', 'https://phimimg.com/upload/vod/20240419-1/2565a55921deda206f58a820a918e846.jpg', '<p>Thiên Tài Cơ Bản Pháp (Phương Pháp Cơ Bản Để Trở Thành Thiên Tài) kể về câu chuyện của thiên tài toán học Lâm Triệu Sinh, con gái của ông Lâm Triều Tịch, và một thiếu niên có chỉ số IQ cao - Bùi Chi là những người tìm thấy chính mình trong lý luận toán học và tương tác không-thời gian kép. Một công thức toán học bí ẩn đã bất ngờ đưa Lâm Triều Tịch 13 tuổi đến một thế giới song song. Trong chuyến phiêu lưu kỳ lạ này, Lâm Triều Tịch bằng kinh nghiệm thi Olympic Toán học tích lũy trong nhiều năm, chợt nhận ra rằng những lần hụt hẫng, mất niềm tin, và cả căn bệnh nan y của cha, khi cô tìm được sự ưu ái này từ số phận, mọi thứ đều có khả năng bù đắp lại - cho dù đó là khởi đầu vô cùng tồi tệ, cuộc sống cũng có thể có sức sống vô hạn.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lôi Gia Âm","avatar":""},{"name":"Wendy Zhang","avatar":""},{"name":"Trương Tân Thành","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
