INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vang-hai-tac-cua-dao-adak', 'Vàng Hải Tặc Của Đảo Adak', 'Pirate Gold Of Adak Island', 'https://phimimg.com/upload/vod/20240419-1/cc130134a881e1677b64c9aa3abf1a3d.jpg', 'https://phimimg.com/upload/vod/20240419-1/4fc70c9d6e843a36242ee60f5748bb21.jpg', '<p>Liệu đội chuyên gia này có tìm được kho báu cướp biển huyền thoại? Hãy theo dõi cuộc truy tìm vàng giữa vùng hoang dã khắc nghiệt của Alaska trong loạt phim tài liệu này.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324269);
