INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-quang-trong-thu-han', 'Vinh Quang Trong Thù Hận', 'The Glory', 'https://phimimg.com/upload/vod/20240419-1/29c9212774881368c2b70485c8fe5414.jpg', 'https://phimimg.com/upload/vod/20240419-1/9623dbac435e2af8fa966fe9b2429f84.jpg', '<p>Nhiều năm sau khi thoát khỏi cảnh bạo lực kinh hoàng ở trường cấp ba, một phụ nữ tiến hành âm mưu trả thù đầy tinh vi để khiến các thủ phạm phải trả giá cho tội ác của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Hye Kyo","avatar":""},{"name":"Lee Do Hyun","avatar":""},{"name":"Lim Ji Yeon","avatar":""},{"name":"Yeom Hye Ran","avatar":""},{"name":"Park Sung Hoon","avatar":""},{"name":"Jung Sung Ill","avatar":""},{"name":"Kim Hieora","avatar":""},{"name":"Cha Joo Young","avatar":""},{"name":"Kim Gun Woo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
