INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-tinh-yeu', 'Bậc Thầy Tình Yêu', 'Catch Me Baby', 'https://phimimg.com/upload/vod/20240419-1/d8ac0cc50d824d25a16ab40f6be2c7bf.jpg', 'https://phimimg.com/upload/vod/20240419-1/5076fcb3da869cd5bb1f8dbb725dbcc6.jpg', '<p>Phat là một Bậc Thầy Tình Yêu, dưới vỏ bọc là thư ký riêng của Sia Wut - một ông chủ đào hoa hẹn hò với năm người bạn gái cùng một lúc. Sia Wut lúc nào cũng phải tìm cách tránh cho các cô bạn gái biết được sự tồn tại của nhau. Nhưng sau sự xuất hiện của thư ký mới là Cher - một người giỏi xem tướng thì mọi sự bình lặng vốn có liền trở nên phức tạp, vì cô ấy nói bản thân là một thám tử chuyên đi điều tra những anh chàng đào hoa. Phat liền rơi vào thế khó, thế là anh ta tìm đến cô em gái nuôi Pinky, một người rất giỏi diễn xuất, Jim Ben cùng Captain (đối thủ cạnh tranh của em trai Cher - Foie) để thành lập một liên minh. Đây là trò mèo vờn chuột giữa Phat và Cher cùng với bầu không khí vô cùng căng thẳng giữa hai người. Liên tục đối đầu như vậy, liệu Phat có kìm nén được tình cảm đối với kẻ thù không độ trời chung của mình không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Great Sapol Assawamunkong","avatar":""},{"name":"Four Sakonrut Woraurai","avatar":""},{"name":"Beau Thanakorn Chinakul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
