INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-thay-tinh-yeu', 'Bậc Thầy Tình Yêu', 'Catch Me Baby', 'bậc thầy tình yêu catch me baby great sapol assawamunkong four sakonrut woraurai beau thanakorn chinakul ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('under-the-banner-of-heaven', 'Under The Banner Of Heaven', 'Under The Banner Of Heaven', 'https://phimimg.com/upload/vod/20240419-1/402dfb4a5e717b3d27f4878bef1e2d90.jpg', 'https://phimimg.com/upload/vod/20240419-1/7b7ed20937f913239ead8600b97960de.jpg', '<p>Phim tập trung vào hai anh em đã giết người vợ và con gái trẻ sơ sinh của em trai họ. Những kẻ giết người tuyên bố họ đã hành động theo đơn đặt hàng từ Thiên Chúa, phù hợp với sự giải thích của họ về một cách giải thích cơ bản, quay trở lại sự hình thành của sự maymonism. Anh em là thành viên của một nhóm splinter có tên là Trường Tiên tri, tuân thủ các nguyên lý gốc của đức tin bao gồm đa thê và niềm tin rằng các tín đồ thực sự có thể nói chuyện trực tiếp với Chúa. Những thứ này đã bắt nguồn từ đức tin đã phát triển đến một kháng cáo chính thống, nhưng anh em vẫn bị thuyết phục rằng họ đang vâng lời chỉ huy của Chúa khi họ phạm tội ghê tởm.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Daisy Edgar-Jones","avatar":""},{"name":"Wyatt Russell","avatar":""},{"name":"Billy Howle","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324269);
