INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('under-the-banner-of-heaven', 'Under The Banner Of Heaven', 'Under The Banner Of Heaven', 'under the banner of heaven under the banner of heaven andrew garfield sam worthington daisy edgar-jones wyatt russell billy howle ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve', 'Trở Về', 'Communion', 'https://phimimg.com/upload/vod/20240419-1/ea99c97b764004ee2397f1b2bcabed55.jpg', 'https://phimimg.com/upload/vod/20240419-1/85dfbd1e7b990c8fbdfb831d0ad78197.jpg', '<p>Từ năm 1997, vợ chồng Âu Diệu Tổ (do Quách Tấn An đóng) và Đặng Lệ Quyên (do Trần Vỹ đóng) cùng nhau kinh doanh quán ăn Việt Đức Cư. Do có nhiều mâu thuẫn, sau đó họ đã ly hôn. Vốn là một phụ nữ mạnh mẽ, Lệ Quyên quyết định đến Đại Lục để khởi nghiệp, xây dựng vương quốc ẩm thực cho riêng mình. Con trai cả Âu Gia Khiêm (do Ngô Vỹ Hào đóng) theo mẹ sang Đại Lục. Em út Âu Gia Kiện (do Châu Gia Lạc đóng) ở lại Hồng Kông cùng ba. Sau 25 năm, Lệ Quyên đột nhiên về Hồng Kông mở chi nhánh, còn đòi lại thương hiệu Việt Đức Cư. Âu Gia Khiêm trở thành giám đốc điều hành một công ty mới thành lập, anh được mời làm người hướng dẫn cuộc thi thanh niên khởi nghiệp. Âu Gia Kiện cùng em gái nuôi Lăng Xảo Dao (do Trần Gia Tuệ đóng) tham gia cuộc thi và gặp lại anh trai Gia Khiêm. Họ từ va chạm đã dần hiểu nhau hơn, còn hợp tác với Trương Lai (do Đới Tổ Nghi đóng) sáng lập vũ trụ ảo Việt Đức Cư. Quán thực thể và vũ trụ ảo sau đó đều bị kiện vì xâm phạm bản quyền. Diệu Tổ, Lệ Quyên, Gia Khiêm và Gia Kiện đều đối mặt với khó khăn. Mối quan hệ giữa vợ chồng, anh em liệu có trở về hạnh phúc ấm cúng như ban đầu?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 9, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Quách Tấn An","avatar":""},{"name":"Trần Vỹ","avatar":""},{"name":"Ngô Vỹ Hào","avatar":""},{"name":"Châu Gia Lạc","avatar":""},{"name":"Đới Tổ Nghi","avatar":""},{"name":"Du Gia Hân","avatar":""},{"name":"Trần Gia Tuệ","avatar":""},{"name":"Từ Vinh","avatar":""},{"name":"Trần Đình Hân","avatar":""},{"name":"Huỳnh Tử Hằng","avatar":""},{"name":"Bạch Bưu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324269);
