INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hakozume-nu-canh-sat-phan-cong', 'Hakozume: Nữ Cảnh Sát Phản Công', 'Police In A Pod, Hakozume: Kouban Joshi No Gyakushuu', 'https://phimimg.com/upload/vod/20240419-1/55ec72c1d0e851b238d7d6a3f85374fa.jpg', 'https://phimimg.com/upload/vod/20240419-1/47a7a9bd2fe0d6229ed6ce5de9976926.jpg', '<p>Nữ cảnh sát Kawai đã có đủ nghề nghiệp mà cô ấy thậm chí còn chưa đến và chuẩn bị nộp hồ sơ đăng ký, thì điều không tưởng đã xảy ra — cô ấy đã gặp nữ giám đốc mới tại sở của mình! Và sau khi dành một ít thời gian với hình mẫu tuyệt đẹp này, Kawai nhận ra rằng có lẽ rốt cuộc cô ấy vẫn chưa hoàn thành việc làm một sĩ quan.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324269);
