INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-sinh-thanh-kiem', 'Chuyển Sinh Thành Kiếm', 'Reincarnated As A Sword', 'https://phimimg.com/upload/vod/20240419-1/5abb65a116f8e390f5944ace1794f9d5.jpg', 'https://phimimg.com/upload/vod/20240419-1/2b8e4eb519a0003170d30ac2c3d534cd.jpg', '<p>Tôi đã chuyển sinh thành một thanh kiếm... Được chuyển sinh dưới dạng Thanh kiếm được gọi với cái tên Vũ khí mang ý thức, anh ta vừa mong ngóng được gặp người sẽ trang bị mình, vừa nỗ lực thu thập các Kỹ năng trong cô độc. Một ngày nọ, do bất cẩn, anh ta đã bước chân vào Khu rừng héo tàn, một nơi có thể hấp thụ ma lực khiến anh không thể cử động dù chỉ một bước. Trong lúc còn đang bối rối, anh đã gặp Fran, một nô lệ thuộc tộc Hắc miêu đã chịu nhiều áp bức. Fran lúc này đang bị một con Ma thú khổng lồ tấn công, và đang rơi vào thế ngàn cân treo sợi tóc. Cô bé đã rút anh ấy lên và dùng sức mạnh đó để thoát khỏi tình thế hiểm nghèo. Sau đó, cô bé đã đặt cái tên Sư phụ cho anh ấy và chính thức trở thành người trang bị anh ấy. Cùng với Sư phụ, Fran đã trở thành mạo hiểm giả. Hai người cùng nhau mài giũa kỹ năng và dần thành thạo hơn qua các nhiệm vụ. Fran là vì để đạt đến Tiến hóa, điểm cuối cùng của sức mạnh. Còn sư phụ là để giúp Ước nguyện của cô bé thành hiện thực. Cuộc hành trình của thiếu nữ tai thú cùng thanh kiếm kiêm người cha nuông chiều con cái chính thức bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324269);
