INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-hoa-dep-nhat', 'Bông Hoa Đẹp Nhất', 'The Most Beautiful Flower', 'https://phimimg.com/upload/vod/20240419-1/d2f89529e452889ef97e893ab414226f.jpg', 'https://phimimg.com/upload/vod/20240419-1/bebffe59a11e2e6b1f4b457fedfa64f9.jpg', '<p>Dáng đẹp, tóc xoăn, tự tin, Mich biết mình tuyệt vời. Giờ cô chỉ cần thuyết phục mọi người ở trường cấp ba Xochimilco tin vào điều đó.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Esmeralda Soto","avatar":""},{"name":"Isabel Yudice","avatar":""},{"name":"Alicia Vélez","avatar":""},{"name":"Michelle Olvera","avatar":""},{"name":"Germán Bracco","avatar":""},{"name":"Tadeo Tovar","avatar":""},{"name":"Angélica Rogel","avatar":""},{"name":"Luis Fernando Peña","avatar":""},{"name":"Gael García","avatar":""},{"name":"Ivanna García","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
