INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('iron-chef-tim-kiem-dau-bep-huyen-thoai', 'Iron Chef: Tìm Kiếm Đầu Bếp Huyền Thoại', 'Iron Chef: Quest For An Iron Legend', 'https://phimimg.com/upload/vod/20240419-1/9479f9b8a739692acd8e91f29b7d8fc2.jpg', 'https://phimimg.com/upload/vod/20240419-1/db22c6c29d738a8d541c6aa09a758540.jpg', '<p>Siêu Đầu bếp đã trở lại! Trong cuộc thi nấu ăn đỉnh cao này, các ngôi sao ẩm thực cạnh tranh để lọt vào vòng chung kết hoành tráng và giành danh hiệu Đầu bếp Huyền thoại.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Alton Brown","avatar":""},{"name":"Kristen Kish","avatar":""},{"name":"Mark Dacascos","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324269);
