INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-ngoi-sao-cua-anh', 'Em Là Ngôi Sao Của Anh', 'You Are My Stars', 'https://phimimg.com/upload/vod/20240419-1/ce559d34d0f3962c86aee13d515d9224.jpg', 'https://phimimg.com/upload/vod/20240419-1/fe18beb6c2114a4ec129252310131c9d.jpg', '<p>Một lần trao đổi thẻ phòng tình cờ đã khiến Chu Ruoyun vô tình rơi vào cuộc hôn nhân hợp đồng với bạn thân của cô và bạn trai Long Haotian. Mặc dù đây là cuộc hôn nhân thương mại do nhóm lợi ích ép buộc, Long Hạo Thiên không bằng lòng với việc nhà họ Chu ức hiếp Chu Nhược Vân, vẫn độc đoán ra tay bảo vệ vị hôn thê của mình. Hai người yêu nhau từ lúc nào không hay, thầm hứa trong lòng rồi quyết định làm đám cưới ngọt ngào. Nhưng sự xuất hiện của bạn trai cũ và sự trở lại đột ngột của cậu bạn thân đã phá vỡ mọi thứ tưởng chừng yên bình ...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Yuanyuan","avatar":""},{"name":"Cen Ming","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324269);
