INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-sau-khi-chinh-phuc-the-gioi', 'Tình Yêu Sau Khi Chinh Phục Thế Giới', 'Koi Wa Sekai Seifuku No Ato De, Love After World Domination', 'https://phimimg.com/upload/vod/20240419-1/e64ec1bc7b372175ebb142e594514622.jpg', 'https://phimimg.com/upload/vod/20240419-1/b31e716f3479fd448ed5f90b05d3e89e.jpg', '<p>Trong mắt công chúng, Fudo Aikawa và Desumi Magahara là hai kẻ thù không đội trời chung. Fudo là Red Gelato, đội trưởng của biệt đội anh hùng Gelato 5 có nhiệm vụ bảo vệ nền hòa bình thế giới. Trong khi đó, Desumi là thủ lĩnh của Gekko một tổ chức tội ác luôn tìm cách thống trị thế giới. Tuy nhiên, mặc cho sự khác biệt này, họ lại có một mối quan hệ mà khó ai ngờ tới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324269);
