INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-dau', 'Khởi Đầu', 'Reset', 'https://phimimg.com/upload/vod/20240419-1/678f680463ac943442cc87469b79980b.jpg', 'https://phimimg.com/upload/vod/20240419-1/e04fcbf2ffc93ad30aeaf296c0cc9c5e.jpg', '<p>Cô sinh viên Lý Thi Tình và lập trình viên công ty trò chơi Tiêu Hạc Vân tình cờ cùng có mặt trên một chuyến xe buýt đã được định sẵn là sẽ phát nổ. Tại đây, cả hai đã cùng trải qua vòng tuần hoàn vô hạn của các sự kiện kỳ lạ. Để ngăn chiếc xe buýt phát nổ cũng như giải cứu chính bản thân và mọi người, cả hai đã hợp sức để tìm ra sự thật. Đồng thời thông qua quá trình này, họ cũng nhận ra được những giá trị và ý nghĩa mới của cuộc sống.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Bạch Kính Đình","avatar":""},{"name":"Triệu Kim Mạch","avatar":""},{"name":"Lưu Dịch Quân","avatar":""},{"name":"Lưu Đào","avatar":""},{"name":"Hoàng Giác","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324269);
