INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tui-den-ban-phan-1', 'Túi Đen Bẩn (Phần 1)', 'That Dirty Black Bag (Season 1)', 'https://phimimg.com/upload/vod/20240419-1/31aa12baeb513d13e573880153d4cfff.jpg', 'https://phimimg.com/upload/vod/20240419-1/5df6ac1f2657576e09f158e98cd34a58.jpg', '<p>Túi Đen Bẩn Phần 1 - That Dirty Black Bag Season 1 xoay quanh câu chyện về cuộc đụng độ giữa hai người đàn ông được kéo dài đến 8 ngày. Đó là McCoy một cảnh sát trưởng bất cần đời và có một quá khứ vô cùng đen tối, Red Bill một kẻ giết người, luôn có nỗi ám ảnh báo thù, nhưng anh không thể nào thực hiện thành công. Liệu cuộc chiến của hai người đàn ông này sẽ ra sao?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Douglas Booth","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Niv Sultan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324270);
