INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-nao-ma-oi', 'Diễn Nào, Ma Ơi!', 'From Now On, Showtime!', 'https://phimimg.com/upload/vod/20240419-1/ac7430853440fd8fe90e22a430f15f9c.jpg', 'https://phimimg.com/upload/vod/20240419-1/185050188523553dead36396197026cd.jpg', '<p>Diễn Nào, Ma Ơi! - From Now On, Showtime! là phim hài lãng mạn giả tưởng về một pháp sư và một nữ cảnh sát. Park Hae Jin vào vai nam chính Cha Cha Woong, một pháp sư lôi cuốn, người có khả năng nhìn thấy và điều khiển các hồn ma. Jin Ki Joo vào vai nữ chính Go Seul Hae, một cảnh sát đầy nhiệt huyết nhưng bí ẩn. Với mục tiêu gia nhập bộ phận tội phạm, Go Seul Hae rất hăng say trong công việc. Khi cô tham gia với pháp sư Cha Cha Woong, một câu chuyện thú vị sẽ bắt đầu mở ra.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jin Ki Joo","avatar":""},{"name":"Park Hae-Jin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324270);
