INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-bao-gio-la-qua-muon', 'Không Bao Giờ Là Quá Muộn', 'Never Too Late', 'https://phimimg.com/upload/vod/20240419-1/aacfeb5dbfa1f753c7b2d87278513779.jpg', 'https://phimimg.com/upload/vod/20240419-1/5e85727de8438656743010e683cd5b16.jpg', '<p>Nhà thiết kế đồ lót Jiang Xile tái hợp với Ding Ran, mối tình mười năm trước của cô theo cách chết người. Sự xấu hổ chưa dừng lại ở đó. Ngay khi cô về đến nhà, mẹ cô đã tuyên bố lớn rằng cô sẽ tái hôn, và đối tác tái hôn hóa ra là cha của Ding Ran. Từ những người yêu thời thơ ấu đến bác sĩ và bệnh nhân cho đến gia đình được tổ chức lại vào thời điểm này, một mối quan hệ hơi phức tạp kéo dài, và hai tình yêu liên quan đến tuổi thiếu niên lại được bắt đầu lại ...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiao Yu","avatar":""},{"name":"Cao Enqi","avatar":""},{"name":"Xiao Ranxin","avatar":""},{"name":"Wang Junhao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324270);
