INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-mai-se-tot-hon', 'Ngày Mai Sẽ Tốt Hơn', 'Tomorrow Will Be Better', 'https://phimimg.com/upload/vod/20240419-1/bbe7bb850d011564084f2f281038a6b8.jpg', 'https://phimimg.com/upload/vod/20240419-1/4f80e9b04dd5ca919f131287c6aa8902.jpg', '<p>Phim kế về tình cảm bất hoà của một đôi bạn thân như chị em ruột, từ thân thiết bầu bạn cùng nhau trở nên đố kỵ hận thù, đề cao chân thiện mỹ trong nhân tính, soi ra cái ác cái xấu trong lòng người.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sài Bích Vân","avatar":""},{"name":"Lý Thiến","avatar":""},{"name":"Hà Minh Hàn","avatar":""},{"name":"Thiệu Phong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324270);
