INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-trong-khu-vuon', 'Ma Cà Rồng Trong Khu Vườn', 'Vampire In The Garden', 'https://phimimg.com/upload/vod/20240419-1/deff7262e303740588bf2d19dfafd094.jpg', 'https://phimimg.com/upload/vod/20240419-1/0990a1ade182676b22c451325a9e3aeb.jpg', '<p>Nữ hoàng ma cà rồng và một cô gái loài người hợp sức chống lại mọi khó khăn để tìm kiếm thiên đường – nơi con người và ma cà rồng chung sống hòa bình.</p>', 'Hoàn Tất (5/5)', 5, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Han Megumi","avatar":""},{"name":"Kobayashi Yu","avatar":""},{"name":"Kobayashi Chiaki","avatar":""},{"name":"Fukami Rica","avatar":""},{"name":"Touchi Hiroki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324270);
