INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shantaram', 'Shantaram', 'Shantaram', 'https://phimimg.com/upload/vod/20240419-1/483036e27d7075e6b49a5d528d848ee1.jpg', 'https://phimimg.com/upload/vod/20240419-1/a249c1f0c88e84ad73b329fafe88ae29.jpg', '<p>Kẻ bị kết án trốn thoát Lin Ford chạy trốn đến những con phố đông đúc của Bombay những năm 1980, tìm cách biến mất. Làm việc như một người cứu thương cho những người nghèo và bị bỏ rơi của thành phố, Lin tìm thấy tình yêu bất ngờ, sự kết nối và lòng dũng cảm trên con đường dài để cứu chuộc.Tên tù Lin Ford vượt ngục và giả danh với tư cách là một bác sĩ trong khu ổ chuột ở Bombay. Mối quan hệ của anh ta với thế giới ngầm tội phạm ở đó dẫn anh ta đến Afghanistan, nơi anh ta hợp tác với một tên trùm băng đảng bị nhốt trong trận chiến với bọn tội phạm Nga.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonia Desplat","avatar":""},{"name":"Charlie Hunnam","avatar":""},{"name":"Fayssal Bazzi","avatar":""},{"name":"Sujaya Dasgupta","avatar":""},{"name":"Elham Ehsas","avatar":""},{"name":"David Field","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324270);
