INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('shantaram', 'Shantaram', 'Shantaram', 'shantaram shantaram antonia desplat charlie hunnam fayssal bazzi sujaya dasgupta elham ehsas david field ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-peripheral', 'The Peripheral', 'The Peripheral', 'https://phimimg.com/upload/vod/20240419-1/19b5d3d34b2dc54e1e404b4b40d3fd00.jpg', 'https://phimimg.com/upload/vod/20240419-1/c0b754e94f331e60fb41e55593f8da3d.jpg', '<p>Bị mắc kẹt trong một thị trấn Appalachian nhỏ, lối thoát duy nhất của một phụ nữ trẻ khỏi công việc hàng ngày là chơi các trò chơi điện tử nâng cao. Cô ấy là một người chơi giỏi đến nỗi một công ty gửi cho cô ấy một hệ thống trò chơi điện tử mới để thử nghiệm… nhưng nó có một điều bất ngờ trong cửa hàng. Nó mở ra tất cả những giấc mơ của cô ấy về việc tìm thấy mục đích, sự lãng mạn và sự quyến rũ trong những thứ có vẻ giống như một trò chơi… nhưng nó cũng khiến cô ấy và gia đình cô ấy gặp nguy hiểm thực sự.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chloë Grace Moretz","avatar":""},{"name":"Gary Carr","avatar":""},{"name":"Jack Reynor","avatar":""},{"name":"Julian Moore-Cook","avatar":""},{"name":"Louis Herthum","avatar":""},{"name":"Chris Coy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324270);
