INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-peripheral', 'The Peripheral', 'The Peripheral', 'the peripheral the peripheral chloë grace moretz gary carr jack reynor julian moore-cook louis herthum chris coy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sabikui-bisco-thanh-pho-dang-ri-set', 'Sabikui Bisco: Thành Phố Đang Rỉ Sét', 'Sabikui Bisuko', 'https://phimimg.com/upload/vod/20240419-1/5e51e008b3d1a8cd90a56fab6801f2be.jpg', 'https://phimimg.com/upload/vod/20240419-1/5627dadc57eeda3f8adbea05f430fdcd.jpg', '<p>Phim hoạt hình “Sabikui Bisco: Thành Phố Đang Rỉ Sét - 2022” được chuyển thể từ bộ tiểu thuyết cùng tên được viết bởi tác giả Shinji Cobkubo, minh họa bởi K Chigishi. Tác phẩm đã đạt huy chương Bạc tại Giải thưởng Tiểu thuyết Dengeki lần thứ 24 (2017). Trong “Cuốn tiểu thuyết này thật tuyệt vời! 2019 \được xếp hạng nhất trong hạng mục thư viện và hạng mục tác phẩm mới, đồng thời xếp hạng ba trong hạng mục thư viện của giải thưởng Light Novel được yêu thích nhất của nhân viên cửa hàng năm 2019.\nCâu chuyện kể rằng \gió gỉ\ xuất hiện ở Nhật Bản, trung tâm là ở Tokyo, nó thổi liên tục khắp Nhật Bản, phong hóa mọi thứ và hủy diệt nền văn minh. Không một ai biết đến nguyên nhân “gió gỉ”xuất hiện. Để tồn tại con người đã xây dựng các hàng rào chắn gió cao ở biên giới các quận, toàn Nhật Bản trong trạng thái bao vây. Tokyo, Saitama và các thành phố khác từng thịnh vượng đã trở thành \Sa mạc sắt Kitasaitama\- nơi con người không thể tồn tại. Những cơn “gió gỉ” cũng có thể khiến con người mắc phải căn bệnh nan y “bệnh gỉ sắt”.\nAkaboshi đến từ bộ tộc Người bảo vệ Nấm, với biệt danh “Nấm ăn người” đã cùng sư phụ của mình là Garvey phiêu lưu qua những vùng đất hoang từ Gunma đến Jihama, để tìm kiếm \Sabikui\ – một loại thuốc thần kỳ có thể chữa khỏi bệnh gỉ sắt\nĐạo diễn sản xuất Atsushi Ikariya (Stein Gate, Vinland Saga) và đạo diễn Daisuke Mataga.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2022, 'Lồng Tiếng', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324270);
