INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-ho-3', 'Phi Hổ 3', 'Flying Tiger 3', 'https://phimimg.com/upload/vod/20240419-1/b177031574be586d555af638eaed666d.jpg', 'https://phimimg.com/upload/vod/20240419-1/36657a39566aaecfd18d62043b7a6356.jpg', '<p>Một vụ mua bán vũ khí hóa học, dẫn đến sự dòm ngó của một tổ chức khủng bố lớn, từ đó diễn biến thành vụ bắt cóc, uy hiếp con tin ở trung tâm đại nhạc hội. Trương Gia Hiên (Huỳnh Tông Trạch), Cao Tử Lạc (Ngô Trác Hy) và Dư Hiểu Hân (Thái Tư Bối) – những thành viên của đội Phi Hổ, vô tình bị dính líu vào vụ án. Họ cùng với Hà Gia Bảo (Trần Oánh) – cảnh sát điểm O, bị nhóm khủng bố bắt giữ tại hiện trường.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Miêu Kiều Vỹ","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Ngô Trác Hy","avatar":""},{"name":"Mã Đức Chung","avatar":""},{"name":"Quách Tấn An","avatar":""},{"name":"Tiêu Chính Nam","avatar":""},{"name":"Diêu Tử Linh","avatar":""},{"name":"Chu Thần Lệ","avatar":""},{"name":"Thái Tư Bối","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324270);
