INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-xua-ngay-xua-nhung-khong-con-nua', 'Ngày Xửa Ngày Xưa... Nhưng Không Còn Nữa', 'Once Upon A Time... Happily Never After', 'https://phimimg.com/upload/vod/20240419-1/23538ffc448cb5598fecb02c9a41afe1.jpg', 'https://phimimg.com/upload/vod/20240419-1/b5bc64bec3520e3a55ab803cd76e47ca.jpg', '<p>Một cặp đôi bị ép chia cắt phải tìm thấy nhau trong kiếp khác để phá bỏ bùa chú nhắm vào thị trấn của họ, nơi mà không ai có thể yêu.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Sebastián Yatra","avatar":""},{"name":"Nia Correia","avatar":""},{"name":"Mónica Maranillo","avatar":""},{"name":"Asier Etxeandia","avatar":""},{"name":"Mariana Treviño","avatar":""},{"name":"Mariola Fuentes","avatar":""},{"name":"Itziar Castro","avatar":""},{"name":"Julián Villagrán","avatar":""},{"name":"Daniela Vega","avatar":""},{"name":"Rossy de Palma","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324270);
