INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-nguyet-te-quan-tam', 'Minh Nguyệt Tế Quân Tâm', 'Minh Yue Ji Jun Xin', 'https://phimimg.com/upload/vod/20240419-1/b0da03783d0bf5f7863163f421de78e4.jpg', 'https://phimimg.com/upload/vod/20240419-1/c3787f5c2723170a1f555b3db896512e.jpg', '<p>Đêm quốc hôn của con trai tướng quân Tĩnh quốc Tiêu Kỳ Phong cùng công chúa Ninh quốc, một bộ hài cốt mặc thanh y bất ngờ xuất hiện trong miệng giếng bỏ hoang. Tiêu tướng quân, Tiêu phu nhân và Thiên Mệnh Ty huyền nữ Tố Tinh tranh nhau nhận tội, hoàng hậu Tĩnh quốc suýt bị ám sát. Phút chốc Tiêu phủ trở thành cục diện tu la, chân tướng đằng sau hài cốt thanh y cũng dần dần lộ ra.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Diệp Tiểu Vĩ","avatar":""},{"name":"Quan Sướng","avatar":""},{"name":"Lưu Vịnh Thần","avatar":""},{"name":"Đới Lệ Cáp Na Y Mãn","avatar":""},{"name":"Nhậm Vũ","avatar":""},{"name":"Mãn Ninh Khê","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324270);
