INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-goi-cho-saul-phan-6', 'Hãy Gọi Cho Saul (Phần 6)', 'Better Call Saul (Season 6)', 'https://phimimg.com/upload/vod/20240419-1/ff1738465976f72e3f2bf464dd92a72e.jpg', 'https://phimimg.com/upload/vod/20240419-1/b978dd6003809f18fa480e35f28aada9.jpg', '<p>Trong mùa cuối loạt phim được giới phê bình đánh giá cao, cú lột xác của Jimmy khép lại trọn vẹn với các cuộc đối đầu, phi vụ mờ ám và hàng loạt khách hàng mới.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Odenkirk","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Rhea Seehorn","avatar":""},{"name":"Michael McKean","avatar":""},{"name":"Patrick Fabian","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Michael Mando","avatar":""},{"name":"Tony Dalton","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Brandon K. Hampton","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Jeremiah Bitsui","avatar":""},{"name":"Rainer Bock","avatar":""},{"name":"Robert Forster","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324270);
