INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sabikui-bisco', 'SABIKUI BISCO', 'Rust-Eater Bisco', 'https://phimimg.com/upload/vod/20240419-1/3014cbc149c66f073fb5ed88f3706064.jpg', 'https://phimimg.com/upload/vod/20240419-1/ad10d72717d40f75d16d0475239a2a99.jpg', '<p>Câu chuyện lấy bối cảnh ở Nhật Bản sau khi “Cơn gió bụi” đã quét đi mọi thứ. Mọi người sống trong nỗi sợ hãi về sự rỉ sét ăn mòn các thành phố. Một cậu bé tên là Bisco Akaboshi đến từ bộ tộc Người bảo vệ Nấm bị khinh thường bắt đầu cuộc hành trình để lấy nấm “Ăn rỉ” – một loại thuốc thần kỳ có thể thanh tẩy tất cả thứ rỉ sét – để cứu người thầy đang hấp hối của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324270);
