INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-trom-gang-tay-xanh-luc', 'Băng Trộm Găng Tay Xanh Lục', 'The Green Glove Gang', 'https://phimimg.com/upload/vod/20240419-1/b80b0da78575b84fef12f4f391ef9193.jpg', 'https://phimimg.com/upload/vod/20240419-1/4a2060835fa1ca37a368fae5ef2c5185.jpg', '<p>Khi vụ trộm gần nhất đổ bể, ba nữ đạo chích lớn tuổi trốn tránh chính quyền bằng cách ẩn nấp trong viện dưỡng lão rồi khám phá ra một bí mật hiểm ác ở đó.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Magdalena Kuta","avatar":""},{"name":"Małgorzata Potocka","avatar":""},{"name":"Anna Romantowska","avatar":""},{"name":"Beata Bandurska","avatar":""},{"name":"Mirosław Zbrojewicz","avatar":""},{"name":"Karolina Rzepa","avatar":""},{"name":"Andrzej Grabowski","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324270);
