INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-ap-gap-go-em', 'Ấm Áp Gặp Gỡ Em', 'Warm Meet You', 'https://phimimg.com/upload/vod/20240419-1/c7b66ebbc9468df6e0bbe6f0e9bf16a0.jpg', 'https://phimimg.com/upload/vod/20240419-1/9058de9788604f00d4a6528c6b9f422f.jpg', '<p>Cô gái bình thường Zhao Nuannuan, do một cuộc phỏng vấn tình cờ, đã tạo nên mối quan hệ với Gu Yichen, chủ tịch của trò chơi di động Z. Thật bất ngờ, Zhao Nuannuan tình cờ có được chiếc kính thần kỳ có thể nhìn thấy vận may của mọi người, và cô ấy phát hiện ra rằng Gu Yichen chính là Vua cá chép Koi đầy may mắn! Vì vậy, Zhao Nuannuan đã tiếp cận Gu Yichen với thái độ muốn thử... Gu Yichen cũng đang mắc chứng dị cảm vì lý do gia đình. Noan Noan muốn xoa xoa vận may của Gu Yichen, nhưng Gu Yichen không thể động lòng với một cô gái, giữa chạm và không thể chạm, cả hai bắt đầu một trận chiến hài hước ...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Ge Yang","avatar":""},{"name":"Qi Yu Chen","avatar":""},{"name":"Xu Ke","avatar":""},{"name":"Yu Cong","avatar":""},{"name":"Gao Jun Jie","avatar":""},{"name":"Wang Qian Guo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324270);
