INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ma-nha-van-phan-3', 'Hồn Ma Nhà Văn (Phần 3)', 'Ghostwriter (Season 3)', 'https://phimimg.com/upload/vod/20240419-1/f45044b73106ffbdd2472c988c883d8c.jpg', 'https://phimimg.com/upload/vod/20240419-1/8eb707c2f00c58ba5ecf395de87dd0f0.jpg', '<p>Khi một con ma ám ảnh một hiệu sách và thả các nhân vật hư cấu vào thế giới thực, một nhóm bạn làm việc để giải quyết một bí ẩn thú vị xung quanh công việc kinh doanh còn dang dở của con ma. Trong khi giải quyết bí ẩn lớn, các anh hùng trẻ tuổi dấn thân vào sáu cuộc phiêu lưu kỳ lạ với các nhân vật lấy cảm hứng từ câu chuyện “The Wonderful Wizard of Oz” của L. Frank Baum; tác giả Pablo Cartaya của “¡Leo! El Magnífico”; tiểu thuyết “Con chuột và chiếc xe máy” của Beverly Cleary; bài hát Shes a Rainbow của Mick Jagger và Keith Richard; E.B. cuốn sách của White “Charlottes Web”; và câu chuyện “Ma thuật Bayou” của Jewell Parker Rhodes.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Princess K. Mapp","avatar":""},{"name":"Nour Assaf","avatar":""},{"name":"Daire McLeod","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324270);
