INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-co-that', 'Phù Thuỷ Có Thật', 'The Witch Is Alive', 'https://phimimg.com/upload/vod/20240418-1/fdcab85c08951f2fca8c43a94a6ffa98.jpg', 'https://phimimg.com/upload/vod/20240418-1/17a44559bb1e880c6359439cbab5c89e.jpg', '<p>Ba người bạn nữ, đến từ những hoàn cảnh hoàn toàn khác nhau, gặp phải kẻ thù mà họ muốn giết. Gong Ma Ri là một bà nội trợ có cuộc sống viên mãn bên chồng và con gái. Khi cô ấy phát hiện ra người bạn đời của mình ngoại tình, cô ấy đã tìm một phương pháp thay thế để kết thúc cuộc hôn nhân của mình.Chae Hee Soo là con dâu trong một gia đình tài phiệt. Cuộc sống hôn nhân của cô ấy không suôn sẻ. Cô ấy không chỉ phải chiều mẹ chồng, người đau khổ về thể xác và đau khổ khỏi bệnh Alzheimer, cô cũng phải chịu đựng sự thờ ơ lạnh nhạt của chồng đối với cô khi cô phải vật lộn để mang thai. Một ngày nọ, mẹ chồng của Hee Soo đưa ra lời đề nghị đáng sợ nhưng đầy hấp dẫn.Chồng của Yang Jin A là một người xấu. Sau khi chết, Jin A thu được một số tiền đáng kể từ hợp đồng bảo hiểm nhân thọ của mình. Với số tiền đó, cô có thể tận hưởng một lối sống mà trước đây cô không quen. Thay vì. cô luôn canh chừng trong cơn gió chướng của mình, lo lắng sợ ai đó sẽ lấy mất nó.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Yoo Ri","avatar":""},{"name":"Lee Min Young","avatar":""},{"name":"Yoon So Yi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324270);
