INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-tac-su-dung-loi-noi-doi', 'Quy Tắc Sử Dụng Lời Nói Dối', 'Better A Lie Than A Truth', 'https://phimimg.com/upload/vod/20240418-1/ad24e8ebfa0324056d13fce5bbc7f217.jpg', 'https://phimimg.com/upload/vod/20240418-1/d0140d5fffdea74ca7955bbb5d291315.jpg', '<p>Qiao Musheng ban đầu trưởng thành và tàn nhẫn đã trải qua cuộc ly hôn của cha mẹ và cái chết bất ngờ của người anh song sinh. Để bảo vệ mẹ mình, anh đã đóng vai Lu Jingnian xinh xắn và dễ thương trước mặt anh. Khi Qiao Musheng gặp lại Su Nian, anh nhớ ra rằng họ đã có quá khứ thời trung học và chọn cách sử dụng danh tính của em trai mình là Lu Jingnian để kết thân với Su Nian một lần nữa. Nói dối là chân thành theo quy tắc sử dụng, tất cả những lời nói dối được bắt đầu bởi Qiao Musheng, và kết thúc ở Lu Jingnian ...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Junyu","avatar":""},{"name":"Niu Yukun","avatar":""},{"name":"Xuan Hao","avatar":""},{"name":"Shi Guang","avatar":""},{"name":"Guo Qianwen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324270);
