INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('love-live-sieu-sao-mua-2', 'Love Live! Siêu Sao!! (Mùa 2)', 'Love Live! Superstar!! (2nd Season)', 'https://phimimg.com/upload/vod/20240418-1/4123be94c6228b1f4ddc05bc3017cf70.jpg', 'https://phimimg.com/upload/vod/20240418-1/1ba24615f48828abb79e03a186a42f9f.jpg', '<p>Trường nữ sinh tư thục mới thành lập Yuigaoka, tọa lạc giữa Ometesando, Harajuku và Aoyama đã bước sang mùa xuân thứ hai. Nhóm Idol học đường Liella! do Shibuya Kanon và các bạn thành lập chuẩn bị đón thêm bốn thành viên mới, những cô đã bắt đầu cất bước chạy trong vai trò Idol học đường!. Họ đã nghĩ vậy. Rằng phải cố gắng cùng với các thành viên mới... Câu chuyện nơi tất cả cùng biến nó trở thành sự thật của Kanon và các bạn. Đón chào thành viên mới và hướng đến ngôi sao đầu tiên. Tung cánh bay nào! Love Live của chúng ta!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324270);
