INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-khong-lo-xanh', 'Nữ Khổng Lồ Xanh', 'She-Hulk: Attorney At Law', 'https://phimimg.com/upload/vod/20240418-1/1ab47fc8e8bd9aff05e6aa95813c3fd0.jpg', 'https://phimimg.com/upload/vod/20240418-1/4936faa0db2a65e021a6f701e266697f.jpg', '<p>Jennifer Walters điều hướng cuộc sống phức tạp của một luật sư 30 tuổi độc thân, đồng thời cũng là một gã khổng lồ siêu cường cao 6 feet 7 inch màu xanh lá cây.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tatiana Maslany","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Ginger Gonzaga","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324270);
