INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-luu-nien', 'Phúc Lưu Niên', 'Lost Track Of Time', 'https://phimimg.com/upload/vod/20240418-1/82c7a75d8290470493c6c09685cfe854.jpg', 'https://phimimg.com/upload/vod/20240418-1/a77bdd9518677eb63f42057668ebe758.jpg', '<p>Khoảnh khắc tỉnh lại đó, gió máu mười năm khuấy động trái tim Lục An Nhiên. Ngoài kia hoa đào trên thế gian vẫn nở rộ, nhưng lòng nàng đã lấp đầy thù hận và không còn là Lục An Nhiên ngây thơ thuở nào. Chàng thiếu niên năm đó đứng trên mũi tàu mà vẫn chưa trở thành ác quỷ, chàng thiếu niên phiêu bạt giang hồ và yêu cuồng nhiệt suốt cả một đời. Khi hai người họ lần nữa đứng trước ngã rẽ năm tháng, liệu Lục An Nhiên sẽ đưa ra quyết định thế nào?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hình Phi","avatar":""},{"name":"Trạch Tử Lộ","avatar":""},{"name":"Kinh Siêu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324270);
