INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-on-dung-sung-toi', 'Làm Ơn Đừng Sủng Tôi', 'Please Don''t Spoil Me', 'https://phimimg.com/upload/vod/20240418-1/a34bdd8732be2191f6ebabc350d339fc.jpg', 'https://phimimg.com/upload/vod/20240418-1/2430d68890fabbeba6c52754291690cf.jpg', '<p>Nhà văn Internet Yan Yi Yi đã bước vào cuốn tiểu thuyết của chính mình và trở thành một người ủng hộ nữ độc ác. Cô đã chiến đấu trí tuệ và dũng cảm với hoàng đế để tránh cái kết bi thảm khi vào cung điện lạnh lùng nhưng bị quan sách nhắc nhở rằng nếu cô không vào cung điện lạnh lẽo theo đúng cốt truyện thì cô sẽ bị xóa sổ. Vì vậy, Yan Yi Yi sống sót giữa việc duy trì cốt truyện và tránh một kết cục tồi tệ và yêu thầm hoàng đế.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Miaoyi","avatar":""},{"name":"Jin Xianzheng","avatar":""},{"name":"Pupu","avatar":""},{"name":"Han Jiahui","avatar":""},{"name":"Tang Hao","avatar":""},{"name":"Sun Yuchong","avatar":""},{"name":"Zhao Yiyang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324270);
