INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-thi-tran-nho', 'Bí Mật Thị Trấn Nhỏ', 'Hold Tight', 'https://phimimg.com/upload/vod/20240418-1/6bc699b3687af5e9c84e180b651b8ad8.jpg', 'https://phimimg.com/upload/vod/20240418-1/eec871db19cd9a4074e884245c6877b2.jpg', '<p>Khi một thiếu niên mất tích ngay sau khi bạn của cậu chết, cuộc sống ở vùng ngoại ô Warsaw giàu có, khăng khít từ từ hé lộ, bóc trần bí mật và những điều dối trá.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Magdalena Boczarska","avatar":""},{"name":"Leszek Lichota","avatar":""},{"name":"Krzysztof Oleksyn","avatar":""},{"name":"Agnieszka Grochowska","avatar":""},{"name":"Grzegorz Damięcki","avatar":""},{"name":"Agata Łabno","avatar":""},{"name":"Dominika Krzemińska","avatar":""},{"name":"Klementyna Karnkowska","avatar":""},{"name":"Justyna Wasilewska","avatar":""},{"name":"Jacek Poniedziałek","avatar":""},{"name":"Julia Wyszyńska","avatar":""},{"name":"Adam Nawojczyk","avatar":""},{"name":"Mikołaj Śliwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324270);
