INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-mat-thi-tran-nho', 'Bí Mật Thị Trấn Nhỏ', 'Hold Tight', 'bí mật thị trấn nhỏ hold tight magdalena boczarska leszek lichota krzysztof oleksyn agnieszka grochowska grzegorz damięcki agata łabno dominika krzemińska klementyna karnkowska justyna wasilewska jacek poniedziałek julia wyszyńska adam nawojczyk mikołaj śliwa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('love-mechanics', 'Love Mechanics', 'Love Mechanics', 'https://phimimg.com/upload/vod/20240418-1/b8b20f19ce1a8f875601c93cce73e376.jpg', 'https://phimimg.com/upload/vod/20240418-1/47a3b7ef4096da0d7d532a59063d09f7.jpg', '<p>Love Mechanics là câu chuyện thấy bạn mình được một đàn em theo đuổi, Vee - người luôn tin rằng cả đời chỉ có thể yêu duy nhất một người đành bất đắc dĩ phải kết thúc tình bạn với Mark. Nhưng một sự cố bất ngờ đã khiến mối quan hệ của họ nảy sinh một chút lạ thường. Mark lựa chọn tránh né, cậu cho rằng chuyện của hai người nên dừng lại ở đó. Nhưng Vee lại không ngừng dây dưa với cậu. Thực tế thì Mark cũng thích Vee, dù Vee đã có bạn gái, lại còn rất thương yêu cô bạn gái đó của mình. Chuyện tình yêu của hai anh em này sẽ đi về đâu? Sự ngượng ngùng của họ đến bao giờ mới có thể lên đến đỉnh điểm? Cuối cùng Vee sẽ quyết định như thế nào?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Yin Anan Wong","avatar":""},{"name":"War Wanarat Ratsameerat","avatar":""},{"name":"Toosafe Krittawat Suwanich","avatar":""},{"name":"Prom Ratchapat Worrasarn","avatar":""},{"name":"Perth Veerinsara Tangkitsuvanich","avatar":""},{"name":"Ritz Rueangritz Siriphanit","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324270);
