INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-anh-em-phan-2', 'Tình Anh Em (Phần 2)', 'Brotherhood (Season 2)', 'https://phimimg.com/upload/vod/20240418-1/0e96525cbc7a45b69e7b79e7f5bcde4e.jpg', 'https://phimimg.com/upload/vod/20240418-1/9a7413b8aa137f035b180faaea697708.jpg', '<p>Sau cuộc bạo động chết chóc, Edson và Cristina vật lộn với những kẻ thù và mối đe dọa mới. Nhưng trong hiểm nguy, mối quan hệ giữa họ được thử thách.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 20, 2022, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Naruna Costa","avatar":""},{"name":"Seu Jorge","avatar":""},{"name":"Hermila Guedes","avatar":""},{"name":"Lee Taylor","avatar":""},{"name":"Danilo Grangheia","avatar":""},{"name":"Emílio de Mello","avatar":""},{"name":"Wesley Guimarães","avatar":""},{"name":"Fábio Lago","avatar":""},{"name":"Pedro Wagner","avatar":""},{"name":"Milhem Cortaz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324270);
