INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cung-phong-bi-mat-cua-toi', 'Bạn Cùng Phòng Bí Mật Của Tôi', 'Love In Time', 'https://phimimg.com/upload/vod/20240418-1/8bf60f209d247486214c0c4fb99cdd28.jpg', 'https://phimimg.com/upload/vod/20240418-1/07ba52b2fde297b43d3b8591432f6d4f.jpg', '<p>Xoay quanh câu chuyện về luật sư tài năng Kha Chấn Vũ khi anh trải qua sự tuột dốc của sự nghiệp và sau đó chuyển đến sống tại một căn hộ cũ. Với một cơ duyên thần bí nào đó, anh chàng gặp được nữ phóng viên Trình Gia Lạc vô tình xuyên không đến nơi đây. Cô nàng nói rằng mình là người đến từ thời điểm bốn tháng trước và giờ đây họ bị buộc trở thành bạn cùng phòng của nhau. Do sự hợp nhất giữa thời gian và không gian trong 46 phút mỗi đêm, câu chuyện của cặp đôi trong bộ phim Bạn Cùng Phòng Bí Mật Của Tôi đã bắt đầu và tạo ra một tình yêu du hành xuyên thời gian và không gian kỳ lạ và lãng mạn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Xu Wen","avatar":""},{"name":"Xiang Han Zhi","avatar":""},{"name":"Lillian","avatar":""},{"name":"Molly","avatar":""},{"name":"Từ Khải Hâm","avatar":""},{"name":"Alvin","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324270);
