INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('them-mot-lan-nua', 'Thêm Một Lần Nữa', 'Once Again', 'https://phimimg.com/upload/vod/20240418-1/f70296cc61a06a580a2932626ed88b4f.jpg', 'https://phimimg.com/upload/vod/20240418-1/105317bdc56ce459e8b9e9ef0d21cae6.jpg', '<p>Kể về câu chuyện tình lãng mạn giả tưởng vượt thời gian giữa của cặp đôi khi có thể gặp lại nhau sau 15 năm. Jae Woo là một chàng trai sống với tổn thương thời thơ ấu và bỗng thấy mình du hành về quá khứ, nơi anh gặp Ji Hoon, một sinh viên luật đang chuẩn bị cho kỳ thi quan trọng và cũng người mà Jae Woo ngưỡng mộ nhất. Khi du hành về quá khứ, liệu rằng cặp đôi có thể thay đổi số phận của nhau?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Hyun Jun","avatar":""},{"name":"Moon Ji Yong","avatar":""},{"name":"Kang Woo Jung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324270);
