INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-cuphead-phan-2', 'Anh Em Cuphead (Phần 2)', 'The Cuphead Show! (Season 2)', 'https://phimimg.com/upload/vod/20240418-1/c5dc499f2e4a03a9113a83384fa760e6.jpg', 'https://phimimg.com/upload/vod/20240418-1/e075540c7325c6a5b87b8e7c9b32c619.jpg', '<p>Cuộc phiêu lưu của cướp biển, cây bạc hà khổng lồ, đinh ba của ác quỷ, v.v. Trong mùa này, Cuphead cùng Mugman vui chơi và bày trò tinh quái bất cứ nơi nào họ đến.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tru Valentino","avatar":""},{"name":"Frank Todaro","avatar":""},{"name":"Wayne Brady","avatar":""},{"name":"Joe Hanna","avatar":""},{"name":"Luke Millington-Drake","avatar":""},{"name":"Grey Griffin","avatar":""},{"name":"Cosmo Segurson","avatar":""},{"name":"Dave Wasson","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324270);
