INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-oi-co-len', 'Mẹ Ơi Cố Lên !!!', 'Mom Wow', 'https://phimimg.com/upload/vod/20240418-1/0f43cf0d26ee5e812093d59a774351a9.jpg', 'https://phimimg.com/upload/vod/20240418-1/01ce52a5056ecccfaa58093ba11fe0be.jpg', '<p>Làm mẹ không dễ chứ chưa nói đến làm mẹ đơn thân. Zhou Nannan, một bà mẹ đơn thân, tin rằng chỉ cần một mình cô có thể mang lại cho cậu con trai Xiaoyang một cuộc sống hạnh phúc. Nhưng ở thời điểm quan trọng khi đưa con trai vào trường tiểu học sau khi cậu tốt nghiệp mẫu giáo, cô nhận ra rằng tất cả các bà mẹ ở trường mẫu giáo đều có những rắc rối riêng. Những người phụ nữ có năng lực nghề nghiệp thấy mình thất bạihãy là những người mẹ tốt trong khi những bà nội trợ toàn thời gian chỉ tập trung vào chồng con của họ cảm thấy khá bị phớt lờ. Ví dụ, một chủ cửa hàng đặt ước mơ không thành hiện thực của mình vào đứa con của mình và cuối cùng trả phần thưởng cho sự phù phiếm của cô ấy; một cô gái trẻ giàu có đang trực tiếp hứng chịu những giông tố của cuộc đời chỉ qua một đêm. Con thì trẻ con nhưng mẹ cũng là người mới lớn. Không ai sinh ra để làm mẹ. Họ nên nuôi dưỡng con cái của họ thành những người tinh hoa bằng mọi giá hay chỉ để chúng như vậy? Những người mẹ đó nên từ bỏ mọi thứ vì con cái hay là chính mình? Sau khi hiểu lầm, xung đột và hòa giải, những người mẹ ở trường mẫu giáo đã giúp con họ bước vào một giai đoạn cuộc sống mới ở trường tiểu học và cũng có được sự trưởng thành của bản thân.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Vũ Kỳ","avatar":""},{"name":"Lý Trạch Phong","avatar":""},{"name":"Ngô Việt","avatar":""},{"name":"Đổng Khiết","avatar":""},{"name":"Hải Lục","avatar":""},{"name":"Phan Chi Lâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324270);
