INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-kim-ba-dao', 'Thiên Kim Bá Đạo', 'My Life As A Villain Characte', 'https://phimimg.com/upload/vod/20240418-1/5663d0f10dc6ab38b811bdd3ef662e0d.jpg', 'https://phimimg.com/upload/vod/20240418-1/eca1815ff6c1b95eda035df2fa833837.jpg', '<p>Súc Diệp bất ngờ bị tai nạn ô tô, khi tỉnh dậy, cô thấy mình trở thành tiểu thư kiêu ngạo của một gia đình giàu có. Súc Diệp nghĩ rằng chỉ cần cô tác hợp cho tổng tài Mộ Thần và tiểu thư Uyển Tình thì bản thân có thể trở về như lúc đầu. Tuy nhiên, sau những thất bại liên tiếp, Súc Diệp nhận ra rằng mình chỉ có thể rời đi sau khi hoàn thành những chuyện liên quan đến duyên phận tình cảm và sự nghiệp. Đang trong quá trình thăng cấp, cô đột nhiên phát hiện Mộ Thần bên cạnh mình từ một con người lạnh lùng biến thành một người chu đáo, rất ân cần, giống như hai người đã quen biết nhau nhiều năm. Hóa ra Súc Diệp bị hôn mê sau một vụ tai nạn xe hơi và được điều trị bằng công nghệ điện não, Mộ Thần cũng tiến vào thế giới điện não để đánh thức cô. Với sự nỗ lực của Mộ Thần, cuối cùng Súc Diệp cũng tỉnh dậy. Cuối cùng, cả hai tiếp tục cuộc giải cứu và bảo vệ trong thế giới viễn tưởng và tiếp tục câu chuyện tình yêu của họ ở thế giới thực.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Nhuận Trạch","avatar":""},{"name":"Quý Mỹ Hàm","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324270);
