INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trolley', 'Trolley', 'Trolley', 'https://phimimg.com/upload/vod/20240418-1/e5494bf4343ce1efc9fd8e871841782e.jpg', 'https://phimimg.com/upload/vod/20240418-1/370ca4047cdd35085581565e3a3e05ab.jpg', '<p>Một bi kịch bất ngờ đưa vợ của một nghị sĩ ra khỏi cuộc sống riêng và buộc cô phải đối diện với những bí mật của gia đình cũng như quá khứ rắc rối của chính mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hyun Joo","avatar":""},{"name":"Park Hee Soon","avatar":""},{"name":"Kim Moo Yeol","avatar":""},{"name":"Chung Su Bin","avatar":""},{"name":"Ryu Hyun Kyung","avatar":""},{"name":"Ki Tae Young","avatar":""},{"name":"Seo Jeong Yeon","avatar":""},{"name":"Won Mi Won","avatar":""},{"name":"Jang Kwang","avatar":""},{"name":"Kim Me Kyung","avatar":""},{"name":"Gil Hae Yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324270);
