INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-xanh', 'Hành Tinh Xanh', 'The Green Planet', 'https://phimimg.com/upload/vod/20240418-1/6af2bd3fea56c55df47acd8767e65b01.jpg', 'https://phimimg.com/upload/vod/20240418-1/e7dc7a2a756d4d09fa73aaebfd5c3c85.jpg', '<p>Loạt phim tài liệu về thực vật này là sự miêu tả nhập vai đầu tiên về một thế giới vô hình, liên kết với nhau, đầy những hành vi mới đáng chú ý, những câu chuyện xúc động và những anh hùng đáng ngạc nhiên trong thế giới thực vật. Hành tinh Trái đất dưới góc nhìn của thực vật.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324270);
