INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('angry-birds-quay-tung-mua-he-phan-2', 'Angry Birds: Quậy Tưng Mùa Hè (Phần 2)', 'Angry Birds: Summer Madness (Season 2)', 'https://phimimg.com/upload/vod/20240418-1/86b880107ad54d34867c3bd0ba4fb2c2.jpg', 'https://phimimg.com/upload/vod/20240418-1/f040e5270df585cb9522bd691d74bb5b.jpg', '<p>Những chú chim thiếu niên Đỏ, Chuck, Bomb và Stella đang càn quét Trại Hè Gỗ Vụn cùng các trại sinh lông vũ khác cho một mùa hè đầy những trò vui bay cao!</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Kirschner","avatar":""},{"name":"Ana Sani","avatar":""},{"name":"Deven Christian Mack","avatar":""},{"name":"Gigi Saul Guerrero","avatar":""},{"name":"Ian Hanlin","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Peter Kelamis","avatar":""},{"name":"Tabitha St. Germain","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324270);
